INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('no-le-cong-so-dinh-doat-chuyen-di-gioi-isekai-no-sata-wa-shachiku-shidai', 'Nô Lệ Công Sở Định Đoạt Chuyện Dị Giới (Isekai no Sata wa Shachiku Shidai)', 'Isekai Office Worker: The Other World''s Books Depend on the Bean Counter', 'https://phimimg.com/upload/vod/20260121-1/3228ed594c442139b26f62d67512f287.jpg', 'https://phimimg.com/upload/vod/20260121-1/62f45f94b50ce0aa5407117bfbee31fe.jpg', '<p>Seiichirou Kondou vô tình bị cuốn vào một nghi lễ triệu hồi và bị dịch chuyển đến một thế giới song song mang tên Vương quốc Romany. Vốn là một người nghiện công việc, anh ngay lập tức yêu cầu một việc làm và gia nhập Bộ Kế toán Hoàng gia. Sau khi may mắn sống sót khỏi tác dụng phụ chết người của một loại thuốc tăng lực nhờ sự trợ giúp của ma thuật, Seiichirou đã phó thác bản thân cho Aresh — đội trưởng Đội kỵ binh Hoàng gia thứ ba, người vẫn được mệnh danh là &#39;Hoàng tử Băng giá&#39;.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 26, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kent Ito","avatar":""},{"name":"Tomoaki Maeno","avatar":""},{"name":"Seiichiro Yamashita","avatar":""},{"name":"Hiroki Touchi","avatar":""},{"name":"Tomohiro Yamaguchi","avatar":""},{"name":"Yuna Kamakura","avatar":""},{"name":"Takaaki Torashima","avatar":""},{"name":"Win Morisaki","avatar":""},{"name":"Kazuyuki Okitsu","avatar":""},{"name":"Shiori Izawa","avatar":""},{"name":"Yuki Ono","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["异世界的安泰全看社畜","Isekai no Sata wa Shachiku Shidai","iseshachi","The Affairs of the Other World Depend on the Corporate Slave","Isekai Office Worker The Other Worlds Books Depend on the Bean Counter","異世界の沙汰は社畜次第"]', 1784690324115);
