INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sep-oi-mai-dung-gap-nhau', 'Sếp Ơi, Mai Đừng Gặp Nhau!', 'See You at Work Tomorrow!', 'https://phimimg.com/upload/vod/20260623-1/1be20a5cd056cb313d1c34df5dd59e6e.jpg', 'https://phimimg.com/upload/vod/20260623-1/77c5521e966482a49401f0e80766055e.jpg', '<p>Bộ phim xoay quanh cuộc sống của Cha Ji-yoon (do Park Ji-hyun thủ vai), một nhân viên văn phòng kỳ cựu với 7 năm kinh nghiệm. Cô vốn là một nhân viên tận tụy, được đồng nghiệp tin tưởng nhờ kỹ năng làm việc xuất sắc, nhưng hiện tại cô đang rơi vào trạng thái bế tắc (slump) cả trong sự nghiệp lẫn chuyện tình cảm. Cuộc đời của Ji-yoon trở nên đảo lộn khi cô phải làm việc dưới quyền của Kang Si-u (do Seo In-guk thủ vai) – vị quản lý trực tiếp của cô. Si-u là một người đàn ông có ngoại hình hoàn hảo và phong thái kỷ luật, nhưng lại nổi tiếng là &quot;kẻ khó tính nhất công ty&quot; với tính cách lạnh lùng, thẳng thắn và gai góc. Ban đầu, Ji-yoon coi Si-u là &quot;cái xấu ít hơn&quot; để tránh những rắc rối tệ hại hơn tại nơi làm việc. Tuy nhiên, trong quá trình tiếp xúc và đối mặt với những áp lực công việc hàng ngày, Ji-yoon dần nhận ra những khía cạnh ấm áp ẩn giấu sau vẻ ngoài nghiêm nghị của sếp mình. Ngược lại, Si-u cũng bị thu hút bởi sự kiên cường và bản lĩnh của Ji-yoon. Từ mối quan hệ cấp trên – cấp dưới đầy căng thẳng, họ dần trở thành chỗ dựa tinh thần không thể thay thế cho nhau.</p>', 'Tập 6', 12, 'series', 'ongoing', 177, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Seo In-guk","avatar":""},{"name":"Park Ji-hyun","avatar":""},{"name":"Kang Mi-na","avatar":""},{"name":"Won Gyu-bin","avatar":""},{"name":"Choi Kyung-hoon","avatar":""},{"name":"Park Ye-yeong","avatar":""},{"name":"Han Tae-ha","avatar":""},{"name":"Kim Jung-young","avatar":""},{"name":"Kang Ki-doong","avatar":""},{"name":"Lee Jae-yi","avatar":""},{"name":"Han Jae-hoon","avatar":""},{"name":"Yeom Seung-yi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["明天也要上班！","Nae-il-do-chul-geun","Naeildo Chulgeun","සී යූ ඇට් වර්ක් ටුමොරෝ!","හෙට ඔෆිස් එකේදී හමුවෙමු!","เจอกันที่ออฟฟิศพรุ่งนี้นะ!","Tomorrow’s Work","Going to Work Tomorrow","Going to Work Tomorrow Too","Going to Work","Back to Work!","내일도 출근!"]', 1784690324115);
