INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sep-oi-mai-dung-gap-nhau', 'Sếp Ơi, Mai Đừng Gặp Nhau!', 'See You at Work Tomorrow!', 'sếp ơi, mai đừng gặp nhau! see you at work tomorrow! seo in-guk park ji-hyun kang mi-na won gyu-bin choi kyung-hoon park ye-yeong han tae-ha kim jung-young kang ki-doong lee jae-yi han jae-hoon yeom seung-yi 明天也要上班！ nae-il-do-chul-geun naeildo chulgeun සී යූ ඇට් වර්ක් ටුමොරෝ! හෙට ඔෆිස් එකේදී හමුවෙමු! เจอกันที่ออฟฟิศพรุ่งนี้นะ! tomorrow’s work going to work tomorrow going to work tomorrow too going to work back to work! 내일도 출근!', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cay-cam-o-nha-cau-ay-nhung-qua-cam-luon-roi-sang-nha-toi', 'Cây cam ở nhà cậu ấy nhưng quả cam luôn rơi sang nhà tôi', 'When Oranges Fall', 'https://phimimg.com/upload/vod/20260604-1/0bac1b5f368a775a32cbcce15d0a254d.jpg', 'https://phimimg.com/upload/vod/20260604-1/5eba4d6cc1ea46ac42f086d9e9e3c844.jpg', '<p>Ko là một cậu bé mê cam hơn bất cứ thứ gì trên đời - nhưng không phải cam nào cậu cũng thích. Nhất định phải là cam từ cây ở nhà bên cạnh mới được. Không có loại cam nào ngon bằng, cũng chẳng có loại nào khiến cậu hạnh phúc đến thế. Thơm, ngọt, ngon lành - mọi thứ về những quả cam nhà trồng ấy, Ko đều yêu thích vô cùng. Chỉ có một điều ngoại lệ: chủ nhân thật sự của cây cam đó. Cậu con trai mang cái tên ngầu y hệt tên cậu. Vì hai người trùng tên nên mọi người gọi cậu ta là “Ko Hai”, theo cách gọi quen thuộc mỗi khi có hai người cùng tên. Và thế là Ko nghiễm nhiên trở thành “Ko Một”. Nhưng ngoài cái tên giống nhau ra, cả hai chẳng có điểm gì chung. Tính cách trái ngược hoàn toàn - như thể ông trời đã phái một vị thần tối cao xuống để trừng trị con quỷ cam tinh nghịch vậy. Trong lúc câu chuyện của hai Ko dần mở ra, họ cũng lớn lên - không chỉ về dáng hình mà cả những cảm xúc âm thầm nảy nở trong tim.</p>', 'Tập 9', 12, 'series', 'ongoing', 77, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Passawish Thamasungkeeti","avatar":""},{"name":"Poomsuwan suwansatit","avatar":""},{"name":"Kanthee Limpitikranon","avatar":""},{"name":"Tanan Lohawatanakul","avatar":""},{"name":"Justin Angus Moir","avatar":""},{"name":"Sitthithat Tungtisanon","avatar":""},{"name":"Sujira Arunpipat","avatar":""},{"name":"Phutanate Hongmanop","avatar":""},{"name":"Thinnaphan Tantui","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["The Orange Tree Is at Their House, but the Orange Fruits Always Fall at Our House","ต้นส้มบ้านเขา แต่ผลส้มหล่นมาบ้านเราตลอดเลย"]', 1784690324115);
