INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cay-cam-o-nha-cau-ay-nhung-qua-cam-luon-roi-sang-nha-toi', 'Cây cam ở nhà cậu ấy nhưng quả cam luôn rơi sang nhà tôi', 'When Oranges Fall', 'cây cam ở nhà cậu ấy nhưng quả cam luôn rơi sang nhà tôi when oranges fall passawish thamasungkeeti poomsuwan suwansatit kanthee limpitikranon tanan lohawatanakul justin angus moir sitthithat tungtisanon sujira arunpipat phutanate hongmanop thinnaphan tantui the orange tree is at their house, but the orange fruits always fall at our house ต้นส้มบ้านเขา แต่ผลส้มหล่นมาบ้านเราตลอดเลย', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toa-sang-nhu-nhung-vi-sao', 'Tỏa Sáng Như Những Vì Sao', 'Road To Success', 'https://phimimg.com/upload/vod/20260705-1/ddc50091c30657bb3654d3afd516188b.jpg', 'https://phimimg.com/upload/vod/20260705-1/4995d1804a29701702e98853668a03b6.jpg', '<p>Bộ phim kể về hành trình của tiến sĩ tâm lý Lâm Vãn Tinh khi trở về quê hương giảng dạy, gặp gỡ huấn luyện viên hàng đầu Vương Pháp và dẫn dắt nhóm học sinh cá biệt vượt qua nghịch cảnh để theo đuổi ước mơ. Qua phương pháp giáo dục tự do, cô giúp các thiếu niên xây dựng nhân cách độc lập, tìm thấy bản thân và hướng tới tương lai tươi sáng.</p>', 'Tập 22', 32, 'series', 'ongoing', 331, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngu Thư Hân","avatar":""},{"name":"Trần Tĩnh Khả","avatar":""},{"name":"Tạ Khả Dần","avatar":""},{"name":"Mã Bá Khiên","avatar":""},{"name":"Lưu Tuấn","avatar":""},{"name":"Trương Minh Dư","avatar":""},{"name":"Dương Tinh Tuệ","avatar":""},{"name":"Dương Quân Hạo","avatar":""},{"name":"Lư Triển Tường","avatar":""},{"name":"Triệu Bằng Hạo","avatar":""},{"name":"Đổng Lý Vô Ưu","avatar":""},{"name":"Chu Bác Nham","avatar":""},{"name":"Diêm Ngọc Thần","avatar":""},{"name":"Hà Đức Thụy","avatar":""},{"name":"Diệp Khải Văn","avatar":""},{"name":"Chương Vân Hạo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["狭路","As Bright as the Stars","灿如繁星"]', 1784690324115);
