INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kinh-thanh-ky-tham', 'Kinh Thành Kỳ Thám', 'Cases Between Us', 'https://phimimg.com/upload/vod/20260706-1/48ecec93d8b3f63066a605c8feb2a3ae.jpg', 'https://phimimg.com/upload/vod/20260706-1/b0c53082328c4518e39fd898c6676e2a.jpg', '<p>Triệu Thiếu Thương và Nguyên Hồng là hai chàng trai có xuất thân, nền tảng giáo dục và quá trình trưởng thành hoàn toàn khác biệt. Qua từng vụ án, họ vừa âm thầm học hỏi lẫn nhau, vừa cùng nhau trưởng thành. Giữa bối cảnh thời đại đầy biến động, cả hai dần trở thành cặp bài trùng khắc tinh đáng gờm nhất trong mắt bọn tội phạm.</p>', 'Tập 22', 36, 'series', 'ongoing', 225, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Mã Tư Siêu","avatar":""},{"name":"Trạch Tử Lộ","avatar":""},{"name":"Vu Hân Hòa","avatar":""},{"name":"Vương Sách","avatar":""},{"name":"Phùng Lỗi","avatar":""},{"name":"Tiểu Ái","avatar":""},{"name":"Dương Khải Trình","avatar":""},{"name":"Xuân Hạ","avatar":""},{"name":"Trần Ý Hàm","avatar":""},{"name":"Châu Cửu Lương","avatar":""},{"name":"Mạnh Hạc Đường","avatar":""},{"name":"Phạm Điềm Điềm","avatar":""},{"name":"Lâm Mộc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jing Cheng Qi Tan","Cases Between Us","京城奇探"]', 1784690324115);
