INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-nhan-mang-nhieu-diem-lanh', 'Quý Nhân Mang Nhiều Điềm Lành', 'Auspicious Nobles', 'https://phimimg.com/upload/vod/20260703-1/0f60661273c63f0def064a969450f3d1.jpg', 'https://phimimg.com/upload/vod/20260703-1/70a56fb4c06701f7df01430c9bb816cd.jpg', '<p>Nữ thiên tài ngành tài chính Lý Thanh Thanh bất ngờ xuyên không về thời cổ đại, trở thành phu nhân của xa kỵ tướng quân Phan Dương. Cô chỉ mong muốn sống yên ổn, không ngờ ba năm sau, phu quân của cô lại dẫn theo tình nhân Lý Mộc Nhan cùng trở về nhà. Bí mật tráo đổi thân phận của Lý gia cũng được đưa ra ánh sáng, hóa ra Lý Mộc Nhan mới là thiên kim thật sự của Lý gia.</p>', 'Tập 21', 26, 'series', 'ongoing', 186, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lư Dương Dương","avatar":""},{"name":"Phan Nghị Hồng","avatar":""},{"name":"Vương Trạch Hiên","avatar":""},{"name":"Dư Chỉ Tuệ","avatar":""},{"name":"Cẩm Lang","avatar":""},{"name":"Vương Tuấn Triết","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Gui Ren Duo Wang Shi","贵人多旺事"]', 1784690324115);
