INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thuc-the-quy-quyet-hau-phong-vo-tan', 'Thực Thể Quỷ Quyệt (Hậu Phòng Vô Tận)', 'Backrooms', 'thực thể quỷ quyệt (hậu phòng vô tận) backrooms chiwetel ejiofor renate reinsve mark duplass finn bennett lukita maxwell avan jogia robert bobroczkyi ember ambrose krista kosonen philip granger katharine isabelle peter new sarah hayward natalie moon calix fraser sawyer fraser patrick ba задните стаи бекрумс бекрумсите tagaruumid backrooms: bez izlaza. arka odalar backrooms: za stenou นรกห้องลับ backrooms: brez izhoda الباكرومز backrooms: thực thể quỷ quyệt ນະຮົກຫ້ອງລັບ الغرف الخلفية באקרומס backrooms: um não-lugar backrooms: o labirinto закулисье бэкрумс แบ็กรูมส์ backrooms - za tebou backrooms: everything must go edition закулисье реальности バックルームズ backrooms: everything must go backrooms', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-yeu-hanh', 'Đạo Yêu Hành', 'Aliens Among Immortals', 'https://phimimg.com/upload/vod/20260312-1/1fd77b198bbcfc53b17dd17f75d70899.jpg', 'https://phimimg.com/upload/vod/20260312-1/2821d43d21af1b468167989aa1774fa8.jpg', '<p>Thánh nữ Thiều Nguyệt của Cửu Tuyền Tông bị sắp đặt thành thân cùng thích khách Giang Nguyên bên Thái Huyền Lâu. Cả hai đều chẳng cam tâm, nhưng vì đại cục hai phái, đành kết thành một đôi phu thê trên danh nghĩa. Bề ngoài là cuộc liên hôn tương xứng giữa hai thế lực lớn, song ẩn dưới lớp vỏ hòa thuận ấy lại là toan tính nhắm vào trọng bảo của nhau. Thông qua thân phận vợ chồng hờ, mỗi người âm thầm dò xét, chờ cơ hội chiếm lấy bí vật của đối phương. Ngay trong đêm hợp cẩn, sát ý đã bùng lên. Nhưng khi lưỡi kiếm chạm nhau, cả hai mới nhận ra đối phương đều mang thân thể bất diệt. Nguyên do nằm ở một bí mật chung: Thiều Nguyệt và Giang Nguyên vốn là kẻ lưu lạc từ tinh cầu khác, quê hương từng bị thế lực mang tên “Hư Vô” hủy diệt. Vì tránh kiếp nạn, họ mới trôi dạt tới thế giới này. Không còn đường lui, hai người tiếp tục duy trì mối quan hệ giả tạo ấy, vừa tìm hiểu bí bảo, vừa cùng nhau chống đỡ những hiểm nguy bủa vây. Thế nhưng sống cạnh nhau giữa sinh tử, từ lúc nào chẳng hay, sự đề phòng dần hóa thành tin tưởng, rồi thành đồng minh kề vai sát cánh. Cuối cùng, mục tiêu của họ không còn dừng ở bảo vật nữa. Thứ họ muốn đối mặt chính là “Hư Vô”, kẻ đã chôn vùi quê hương năm cũ. Giữa thế giới đầy toan tính này, hai con người mang chung quá khứ mất mát bắt đầu tìm kiếm cơ hội xoay chuyển số phận, quyết không để bi kịch lặp lại.</p>', 'Tập 44', 80, 'hoathinh', 'ongoing', 70, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Dao Yao Xing","Aliens Among Immortals","盗妖行"]', 1784690324115);
