INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-mac-vien', 'Chủng Mặc Viên', 'Zhong Mo Yuan', 'https://phimimg.com/upload/vod/20260701-1/c5476e1431233cb0011cf3ef9092a318.jpg', 'https://phimimg.com/upload/vod/20260701-1/b9dcaf15420bdaee111b7393c5d9952d.jpg', '<p>Lấy nghề chế tác giấy Tuyên - di sản văn hóa phi vật thể - làm chủ đề, bộ phim kể về Tuyên Ngạn, người kế thừa nghề làm giấy Tuyên, và Lâm Y Nhiên, một cán bộ trẻ trở về quê hương công tác, cùng gắn bó với thị trấn Đào Hoa. Hai người dung hòa giữa việc gìn giữ phương pháp làm giấy truyền thống và đổi mới theo hướng hiện đại, hóa giải những khác biệt trong quan niệm giữa hai thế hệ nghệ nhân, vượt qua bao gian khó để phát triển ngành nghề, chung tay bảo tồn nghề giấy nghìn năm và mở ra con đường mới cho việc phục hưng làng nghề di sản phi vật thể.</p>', 'Tập 25', 34, 'series', 'ongoing', 89, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trịnh Nghiệp Thành","avatar":""},{"name":"Trương Nguyệt","avatar":""},{"name":"Mã Thiếu Hoa","avatar":""},{"name":"Vương Thiến Hoa","avatar":""},{"name":"Hồ Vân Hạo","avatar":""},{"name":"Hùng Duệ Linh","avatar":""},{"name":"Doãn Tiểu Thiên","avatar":""},{"name":"Kỳ Khiên Quân","avatar":""},{"name":"Tống Vũ","avatar":""},{"name":"Anh Tử","avatar":""},{"name":"Vương Kính Tùng","avatar":""},{"name":"Đinh Dũng Đại","avatar":""},{"name":"Ngô Kỳ Giang","avatar":""},{"name":"Ngô Kinh An","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Zhong Mo Yuan","Paper Dreams In Ink","种墨园"]', 1784690324115);
