INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cho-hoang-va-xuong', 'Chó Hoang Và Xương', 'Love For You', 'chó hoang và xương love for you tống uy long trương tịnh nghi lương tĩnh khang hà thụy hiền châu thiết luyện luyện ye gou gu tou 莫道桑榆晚 野狗骨头 love for you', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-thanh-chieu-kinh-bien', 'Cô Thành Chiếu: Kinh Biến', 'Dynasty Of The Undead: Mutate', 'https://phimimg.com/upload/vod/20260706-1/eea0f8561ced283ddbc4c21de1c85b57.jpg', 'https://phimimg.com/upload/vod/20260706-1/1d9f3d1433573d56c6942f2742b6344c.jpg', '<p>Lấy bối cảnh một triều đại cổ đại hư cấu, bí thuật của nước Di Cương đã tạo ra đội quân quái vật bất tử, không sợ đau đớn hay cái chết, bất ngờ tấn công Đại Thịnh. Kinh thành thất thủ, hoàng đế bị bắt làm tù binh. Đứa con mồ côi của Di Cương là Phương Chuẩn - người sở hữu đôi mắt ưng bẩm sinh đã bắt tay với Trưởng công chúa Đại Thịnh là Tiêu Tình. Giữa vòng xoáy quyền mưu, âm mưu phản loạn và làn sóng xác sống vây thành, họ dẫn dắt quân dân dùng vũ khí lạnh cùng hỏa thương tử chiến, chống lại đội quân quái vật và cả những kẻ phản bội từ bên trong để bảo vệ giang sơn và bách tính. Bộ phim kết hợp giữa quyền mưu phương Đông, sinh tồn tận thế và năng lực siêu nhiên thức tỉnh, mang màu sắc u tối, khốc liệt với nhịp phim dồn dập căng thẳng.</p>', 'Tập 22', 41, 'series', 'ongoing', 163, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phim Ngắn","slug":"phim-ngan","id":"4f02d28224c0747511790d57fbb63a62"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324115);
