INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('y-chi-kim-cuong', 'Ý Chí Kim Cương', 'Strong Will', 'https://phimimg.com/upload/vod/20260619-1/d27cee3db697f0b6d6ca7d22b14be2f2.jpg', 'https://phimimg.com/upload/vod/20260619-1/ca96e7f068f84776ca2b4e52b9e971bc.jpg', '<p>Chàng nhạc công tài năng xuất thân nghèo khó và một nữ sinh trung học giàu có nảy sinh tình cảm giữa những mối thù địch cá nhân và một biến cố làm thay đổi cuộc đời.</p>', 'Tập 18', 30, 'series', 'ongoing', 147, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Taentawan Taddeo Majoli Maggioli","avatar":""},{"name":"Kharittha Sungsaopath","avatar":""},{"name":"Krissada Supphapprom","avatar":""},{"name":"Somchai Kemklad","avatar":""},{"name":"Natthapat Jiraphawasut","avatar":""},{"name":"Wanrada Petchamnan","avatar":""},{"name":"Panadda Ruangwut","avatar":""},{"name":"Penpetch Benyakul","avatar":""},{"name":"Kwantuch Na Takuatoong","avatar":""},{"name":"Vivid Bavornkiratikajorn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Corazón de diamante","꺾이지 않은","ลูกผู้ชายหัวใจเพชร"]', 1784690324115);
