INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-doi-tra-2026', 'Trò Chơi Dối Trá', 'LIAR GAME', 'https://phimimg.com/upload/vod/20260411-1/49af586eff3cd03a5f3e5558aa451f58.jpg', 'https://phimimg.com/upload/vod/20260411-1/a951760069de3be74886366297435981.jpg', '<p>Khi Nao Kanzaki nhận được một lá thư kỳ lạ cùng chiếc vali chứa 100 triệu yên, cô bàng hoàng nhận ra mình đã được chọn để tham gia vào LIAR GAME (Trò chơi Dối trá). Trong cuộc chiến tâm lý đầy rủi ro này, sự lừa lọc, dối trá và phản bội luôn ngự trị tối cao. Với bản tính ngây thơ và thật thà, Nao phải tìm đến sự trợ giúp của Shinichi Akiyama — một thiên tài lừa đảo vừa ra tù — để tìm cách sống sót qua trò chơi tàn khốc này. Giữa một cuộc chơi được xây dựng trên những lời dối trá, liệu lòng trung thực có thể giành chiến thắng?</p>', 'Tập 15', 24, 'hoathinh', 'ongoing', 58, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Saya Hitomi","avatar":""},{"name":"Takeo Otsuka","avatar":""},{"name":"Kazuhiro Nakaya","avatar":""},{"name":"Nobuo Tobita","avatar":""},{"name":"Yoji Ueda","avatar":""},{"name":"Yasutaka Tomioka","avatar":""},{"name":"Shoya Ishige","avatar":""},{"name":"Ryosuke Asano","avatar":""},{"name":"Taro Kiuchi","avatar":""},{"name":"Riko Akechi","avatar":""},{"name":"Toshinari Fukamachi","avatar":""},{"name":"Naoya Miyase","avatar":""},{"name":"Misuzu Yamada","avatar":""},{"name":"Taihi Kimura","avatar":""},{"name":"Misano Sakai","avatar":""},{"name":"Aya Gomazuru","avatar":""},{"name":"Ryo Nishizawa","avatar":""},{"name":"Taku Y","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["LIAR GAME -ライアーゲーム-","ライアーゲーム","LIAR GAME"]', 1784690324115);
