INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-em-va-toi', 'Thế Giới Em Và Tôi', 'The Two Faces Of Thatri', 'https://phimimg.com/upload/vod/20260609-1/5550efbb49cb839af1d56ec050851185.jpg', 'https://phimimg.com/upload/vod/20260609-1/c54b7834adf8578b0167b600502bdcba.jpg', '<p>Theo yêu cầu của người bạn bị thương giống tên, Thatri, trong tình cảnh phá sản, mạo danh người bạn đó để nhận thừa kế và thay đổi số phận của cả hai.</p>', 'Tập 11', 19, 'series', 'ongoing', 74, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Nawasch Phupantachsee","avatar":""},{"name":"Yeena Salas","avatar":""},{"name":"Weerakaniz Kanwatthanakul","avatar":""},{"name":"Prima Bhunjaroeun","avatar":""},{"name":"Saranya Jumpatip","avatar":""},{"name":"Natthanit Praditthan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["ธาตรี"]', 1784690324115);
