INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hiep-si-xuong-tren-duong-du-hanh-den-the-gioi-khac-phan-2', 'Hiệp Sĩ Xương Trên Đường Du Hành Đến Thế Giới Khác (Phần 2)', 'Skeleton Knight In Another World (Season 2)', 'https://phimimg.com/upload/vod/20260705-1/561c22e37143930082aa6b208bdc9ad9.jpg', 'https://phimimg.com/upload/vod/20260705-1/0bfec379d64859044e30d3840776d173.jpg', '<p>Một ngày nọ, một game thủ chơi game cho đến khi anh ta ngủ thiếp đi… và khi anh ta tỉnh dậy, anh ta thấy mình đang ở trong thế giới games – và nhập vào một bộ xương! Được trang bị vũ khí và áo giáp mạnh mẽ như avatar &nbsp;của mình nhưng bị mắc kẹt với ngoại hình bộ xương đáng sợ, Arc phải tìm một chỗ đứng cho mình trong vùng đất mới lạ này. Tất cả hy vọng của anh ta về một cuộc sống yên tĩnh bị tiêu tan khi anh ta vượt qua con đường với một chiến binh yêu tinh xinh đẹp, đưa anh ta vào một cuộc hành trình đầy máu và nước mắt.</p>', 'Tập 2', 12, 'hoathinh', 'ongoing', 53, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Tomoaki Maeno","avatar":""},{"name":"Fairouz Ai","avatar":""},{"name":"Nene Hieda","avatar":""},{"name":"Miyu Tomita","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["骸骨骑士大人奇幻冒险中","骸骨骑士大人异世界冒险中","骸骨骑士大人奇幻世界冒险中","骸骨騎士大人異世界冒險中","Skeleton Knight in Another World","Gaikotsu Kishi-sama, Tadaima Isekai e Odekakechū","Gaikots