INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duoi-o-cua-sang-den', 'Dưới Ô Cửa Sáng Đèn', 'Under The Bright Window', 'https://phimimg.com/upload/vod/20260603-1/1f7121f61ac26ca917c8e6d70c3a629c.jpg', 'https://phimimg.com/upload/vod/20260603-1/350fdb0e13cb5809f7f7e61237b39538.jpg', '<p>&quot;Dưới ô cửa sáng đèn&quot; khắc họa cuộc sống đầy trăn trở của những người hàng xóm tại khu tập thể cũ Hà Nội, nơi tình làng nghĩa xóm vượt qua những áp lực thời đại. Phim tập trung vào nhân vật Sinh cùng những câu chuyện đời thường, vất vả mưu sinh và sự gắn kết con người trong bối cảnh khu tập thể chờ giải tỏa.</p>', 'Tập 25', 30, 'series', 'ongoing', 168, 2026, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Bùi Bài Bình","avatar":""},{"name":"Chí Trung","avatar":""},{"name":"Quang Sự","avatar":""},{"name":"Tuấn Tú","avatar":""},{"name":"Quỳnh Châu","avatar":""},{"name":"Ngọc Huyền","avatar":""},{"name":"Tiến Lộc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Dưới ô cửa sáng đèn"]', 1784690324115);
