INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('duoi-o-cua-sang-den', 'Dưới Ô Cửa Sáng Đèn', 'Under The Bright Window', 'dưới ô cửa sáng đèn under the bright window bùi bài bình chí trung quang sự tuấn tú quỳnh châu ngọc huyền tiến lộc dưới ô cửa sáng đèn', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-cai-thao', 'Đời Cải Thảo', 'Cabbage Your Life', 'https://phimimg.com/upload/vod/20260401-1/3da5e28a5385bce1bb889122860fad8d.jpg', 'https://phimimg.com/upload/vod/20260401-1/2ce035e2b1c5494938e002300f9b939f.jpg', '<p>Khi giám đốc điều hành Seong Tae Hun bất ngờ bị điều chuyển công tác về ngôi làng hẻo lánh Yeonri-ri, gia đình anh bỗng chốc rơi vào cảnh hỗn loạn giữa cuộc sống nông thôn. Mi Ryeo chật vật thích nghi với công việc đồng áng, Ji Cheon bắt đầu phải suy nghĩ lại về tương lai của chính mình, trong khi vị trưởng làng luôn giữ thái độ cảnh giác và xa cách. Khi nỗi nhớ nhà ngày một lớn dần và những căng thẳng bắt đầu nảy sinh, cả gia đình phải đứng trước lựa chọn khó khăn: tiếp tục chịu đựng để hòa nhập hay tìm đường quay trở lại thành phố.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 71, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Sung-woong","avatar":""},{"name":"Lee Soo-kyung","avatar":""},{"name":"Lee Jin-woo","avatar":""},{"name":"Choi Gyu-ri","avatar":""},{"name":"Lee Seo-hwan","avatar":""},{"name":"Nam Mi-jung","avatar":""},{"name":"Seo Yun-hyuk","avatar":""},{"name":"Yang Woo-hyeok","avatar":""},{"name":"Choi Woo-jin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["寻牛就到连理里","Simwoomyeon Yeonriri","Сельская жизнь в Ëнрири","الملفوف حياتك","If it''s Deep, Yeonriri","심우면 연리리"]', 1784690324116);
