INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rick-va-morty-phan-9', 'Rick Và Morty (Phần 9)', 'Rick And Morty (Season 9)', 'https://phimimg.com/upload/vod/20260604-1/56460003fbb5366fc854821a32c228e2.jpg', 'https://phimimg.com/upload/vod/20260604-1/b1c22d42dde3369e0cff0a9ac5e58d0f.jpg', '<p>Season 9 tiếp tục sau các sự kiện lớn liên quan đến Evil Morty và sự sụp đổ của Citadel. Khác với một số mùa gần đây thiên về các tập độc lập, mùa này quay trở lại với một cốt truyện xuyên suốt về đa vũ trụ và mối quan hệ phức tạp giữa Rick, Morty và Evil Morty.</p>', 'Tập 8', 10, 'hoathinh', 'ongoing', 106, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Justin Roiland","avatar":""},{"name":"Chris Parnell","avatar":""},{"name":"Spencer Grammer","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Rick e Morty","瑞克和莫蒂","瑞克与莫蒂","リック・アンド・モーティ","릭 앤 모티","Рик Морти хоёр","Рік і Морті","Vindicators 2","Vindicators 2: Last Stand Between Earth and Doom","Rick and Morty"]', 1784690324116);
