INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-toc-rong-phan-3', 'Gia Tộc Rồng (Phần 3)', 'House Of The Dragon (Season 3)', 'https://phimimg.com/upload/vod/20260622-1/344ec2281ef56c96894e787a834f0ace.jpg', 'https://phimimg.com/upload/vod/20260622-1/ace539cd539e20a8fd3642678f65d525.jpg', '<p>Kịch bản lấy bối cảnh 200 năm trước các sự kiện của Game of Thrones, kể về câu chuyện của dòng họ Targaryen. Họ chinh phục và thống trị lục địa Westeros trong thời gian dài nhờ khả năng điều khiển loài rồng. Tuy nhiên, cuộc nội chiến đẫm máu kéo dài để tranh giành Ngôi Báu Sắt đã khiến gia tộc này ngày càng suy yếu và đi đến bờ vực của sự diệt vong.</p>', 'Tập 4', 10, 'series', 'ongoing', 192, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Matt Smith","avatar":""},{"name":"Emma D''Arcy","avatar":""},{"name":"Olivia Cooke","avatar":""},{"name":"Steve Toussaint","avatar":""},{"name":"Rhys Ifans","avatar":""},{"name":"Fabien Frankel","avatar":""},{"name":"Ewan Mitchell","avatar":""},{"name":"Tom Glynn-Carney","avatar":""},{"name":"Sonoya Mizuno","avatar":""},{"name":"Harry Collett","avatar":""},{"name":"Bethany Antonia","avatar":""},{"name":"Phoebe Campbell","avatar":""},{"name":"Phia Saban","avatar":""},{"name":"Jefferson Hall","avatar":""},{"name":"Matthew Needham","avatar":""},{"name":"James Norton","avatar":""},{"name":"Tom Bennet","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn