INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gia-toc-rong-phan-3', 'Gia Tộc Rồng (Phần 3)', 'House Of The Dragon (Season 3)', 'gia tộc rồng (phần 3) house of the dragon (season 3) matt smith emma d''arcy olivia cooke steve toussaint rhys ifans fabien frankel ewan mitchell tom glynn-carney sonoya mizuno harry collett bethany antonia phoebe campbell phia saban jefferson hall matthew needham james norton tom bennet дом дракона la maison du dragon / house of the dragon 龙之家族 maison du dragon 龍之家族 משחקי הכס: בית הדרקון 하우스 오브 드래곤 하우스 오브 더 드래곤 ⵜⴰⴷⴷⴰⵔⵜ ⵏ ⵉⴷⵖⴰⵖⵏ a guerra dos tronos: house of the dragon casa do dragão آل التنين هاوس أوف ذا دراغون дім дракона game of thrones: house of the dragon hotd the house that dragons built house of the dragon', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoan-sa-luc', 'Hoán Sa Lục', 'The Silk Master From The Future', 'https://phimimg.com/upload/vod/20260702-1/dd59b9cae2a63d6cfea005a6e1937573.jpg', 'https://phimimg.com/upload/vod/20260702-1/845561af7c749c5de39afdb764616ff1.jpg', '<p>Tiến sĩ y học hiện đại Lý Vân Hà bất ngờ xuyên không, ở rể nhà họ Chu và cũng là niềm hy vọng duy nhất để khôi phục Hương Vân Sa – loại lụa từng là cống phẩm cho triều đình. Với kiến thức hiện đại và tài kinh doanh xuất chúng, anh liên tục phá giải mọi âm mưu chèn ép của kình địch Lục Kỳ Phong, đồng thời gây chấn động bằng “Đại hội Nghê Thường”, giúp Hương Vân Sa giành lại vinh quang. Sau khi phò tá hoàng đế Triệu Vân Trác dẹp tan cuộc nổi loạn của Ninh Vương, anh từ chàng rể bị coi thường trở thành huyền thoại của thời đại.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 162, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Mông Ân","avatar":""},{"name":"Hồ Đan Đan","avatar":""},{"name":"KK Cheung","avatar":""},{"name":"Ngô Tuyên","avatar":""},{"name":"Trần Vận Cẩm","avatar":""},{"name":"Augus","avatar":""},{"name":"Tô Vũ Hàng","avatar":""},{"name":"Trương Đông Tử","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Huan Sha Lu","浣纱录"]', 1784690324116);
