INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-va-to-la-hai-thai-cuc-doi-lap-seihantai-na-kimi-to-boku-phan-2', 'Cậu Và Tớ Là Hai Thái Cực Đối Lập (Seihantai na Kimi to Boku) (Phần 2)', 'You and I Are Polar Opposites (Season 2)', 'https://phimimg.com/upload/vod/20260706-1/825b10536abaa977ea710bf4cbd4a7e4.jpg', 'https://phimimg.com/upload/vod/20260706-1/a7325eb2658ffe5ad2d8a782910f5542.jpg', '<p>Suzuki, cô nữ sinh trung học sôi nổi và hướng ngoại, trót &quot;cảm nắng&quot; cậu bạn cùng lớp Tani hoàn toàn trái ngược với cô. Liệu cô có vượt qua được cảm giác hồi hộp để ngỏ lời hẹn hò?</p>', 'Tập 2', 24, 'hoathinh', 'ongoing', 61, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Sayumi Suzushiro","avatar":""},{"name":"Shogo Sakata","avatar":""},{"name":"Yuna Taniguchi","avatar":""},{"name":"Konatsu Hirabayashi","avatar":""},{"name":"Anji Iwata","avatar":""},{"name":"Miyuri Shimabukuro","avatar":""},{"name":"Wataru Katoh","avatar":""},{"name":"Cocoro Omori","avatar":""},{"name":"Tomori Kusunoki","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["相反的你和我","आप और मैं एक दूसरे के बिल्कुल विपरीत हैं","Seihantai na Kimi to Boku","Ти і я - полярні протилежності","正反対な君と僕"]', 1784690324116);
