INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cau-va-to-la-hai-thai-cuc-doi-lap-seihantai-na-kimi-to-boku-phan-2', 'Cậu Và Tớ Là Hai Thái Cực Đối Lập (Seihantai na Kimi to Boku) (Phần 2)', 'You and I Are Polar Opposites (Season 2)', 'cậu và tớ là hai thái cực đối lập (seihantai na kimi to boku) (phần 2) you and i are polar opposites (season 2) sayumi suzushiro shogo sakata yuna taniguchi konatsu hirabayashi anji iwata miyuri shimabukuro wataru katoh cocoro omori tomori kusunoki 相反的你和我 आप और मैं एक दूसरे के बिल्कुल विपरीत हैं seihantai na kimi to boku ти і я - полярні протилежності 正反対な君と僕', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hau-phuong-manh-nhat-the-gioi-nha-khai-pha-tan-binh-cua-vuong-quoc-me-cung', 'Hậu Phương Mạnh Nhất Thế Giới - Nhà Khai Phá Tân Binh Của Vương Quốc Mê Cung', 'The World''s Strongest Rearguard', 'https://phimimg.com/upload/vod/20260706-1/f71f0f1d25c2cf1dbee49f48d2c10b65.jpg', 'https://phimimg.com/upload/vod/20260706-1/77db63f704e93279e6a31c668daf3c32.jpg', '<p>Nhân vật chính là một nô lệ của tư bản, sau khi gặp tai nạn bất ngờ đã chuyển sinh đến dị giới mang tên “Vương quốc mê cung”. Tại nơi đó, anh trở thành một nhà thám hiểm mê cung và thức tỉnh một nghề nghiệp bí ẩn mang tên “Hậu phương” Đây là một nghề hỗ trợ toàn năng, vừa có thể tấn công, phòng thủ lẫn trị liệu! Phía sau, cùng với cô gái lính đánh thuê á nhân bí ẩn, vị sếp nữ xinh đẹp từ kiếp trước và những người đồng đội đầy cá tính, chàng trai liên tục leo hạng trong Vương quốc mê cung! &quot;Mọi người, tôi đến hỗ trợ mọi người đây!&quot; Sự hỗ trợ ấy sẽ tăng cường sức mạnh và sợi dây gắn kết. Câu chuyện phiêu lưu của hậu phương mạnh nhất chính thức mở màn!</p>', 'Tập 2', 12, 'hoathinh', 'ongoing', 72, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yoshitsugu Matsuoka","avatar":""},{"name":"Yui Ishikawa","avatar":""},{"name":"Kanon Takao","avatar":""},{"name":"Aoi Koga","avatar":""},{"name":"Saori Hayami","avatar":""},{"name":"Yuuka Aisaka","avatar":""},{"name":"Kaede Hondo","avatar":""},{"name":"Sakura Nakamura","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Sekai Saikyou no Kouei: Meikyuukoku no Shinjin Tansakusha","Sekai Saikyou no Kouei Meikyuukoku no Shinjin Tansakusha","The World''s Strongest Rearguard: Labyrinth Country''s Novice Seeker","世界最強の後衛 ～迷宮国の新人探索者～"]', 1784690324116);
