INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tia-sang-cua-ngay-mai', 'Tia Sáng Của Ngày Mai', 'Sparks Of Tomorrow', 'tia sáng của ngày mai sparks of tomorrow yuma uchida sora amamiya koki uchiyama daisuke ono shunsuke takeuchi minako kotobuki you taichi natsumi kawaida kazuki ura daisuke hirakawa ayahi takagaki 20 seiki denki mokuroku -eureka evrika- nijūseiki denki mokuroku -eureka evrika- nijuuseiki denki mokuroku -eureka evrika- 20th century electricity catalog 二十世紀電氣目録-ユーレカ・エヴリカ-', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-biet-lara', 'Tạm Biệt, Lara', 'Goodbye, Lara', 'https://phimimg.com/upload/vod/20260706-1/a58d4995de5cca37d9a5505d0f7ca237.jpg', 'https://phimimg.com/upload/vod/20260706-1/921417e1ad5a13789142b510a53cf56e.jpg', '<p>Ngày xửa ngày xưa, một nàng tiên cá tên Lara đã đem lòng yêu một hoàng tử loài người. Để được ở bên anh, nàng đã dùng lọ thuốc của phù thủy để biến thành người — nhưng ma thuật luôn đi kèm với cái giá phải trả: Nếu không thể tìm thấy tình yêu đích thực, nàng sẽ tan biến thành bọt biển mãi mãi. Giờ đây, 200 năm sau, Lara bất ngờ tỉnh giấc tại Hồ Biwa với một cơ hội cuối cùng để giành lấy sự sống và tình yêu.</p>', 'Tập 2', 12, 'hoathinh', 'ongoing', 53, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hana Hishikawa","avatar":""},{"name":"Nana Kawaishi","avatar":""},{"name":"Rica Fukami","avatar":""},{"name":"Ayumu Murase","avatar":""},{"name":"Tomohiro Ono","avatar":""},{"name":"Mitsuaki Madono","avatar":""},{"name":"Nanae Sumitomo","avatar":""},{"name":"Masaki Terasoma","avatar":""},{"name":"Minami Tsuda","avatar":""},{"name":"Kazutomi Yamamoto","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["再见，拉拉","Sayonara Lara","さよララ","SayoLara","Sayonara Rara","Прощай, Лара","さよならララ"]', 1784690324116);
