INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('that-nghiep-chuyen-sinh-phan-3', 'Thất Nghiệp Chuyển Sinh (Phần 3)', 'Mushoku Tensei: Jobless Reincarnation (Season 3)', 'thất nghiệp chuyển sinh (phần 3) mushoku tensei: jobless reincarnation (season 3) yumi uchiyama tomokazu sugita ai kakuma ai kayano konomi kohara 无职转生～在异世界认真地活下去～ 无职转生 无职转生2 无职转生～到了异世界就拿出真本事 mushoku tensei: nezaměstnaný dostává druhou šanci mushoku tensei - jobless reincarnation mushoku tensei jobless reincarnation mushoku tensei, jobless reincarnation mushoku tensei: isekai ittara honki dasu mushoku tensei: isekai ittara honki dasu 2nd season 無職転生ⅱ ～異世界行ったら本気だす～ mushoku tensei ii: isekai ittara honki dasu mushoku tensei isekai ittara honki dasu mushoku tensei: isekai ittara honki dasu - eris no goblin toubatsu mushoku tensei ii: isekai ittara honki dasu - shugo jutsushi fitz mushoku tensei s3 무직 전생 ~이세계에 갔으면 최선을 다한다~ reencarnación sin trabajo: lo intentaré seriamente si voy a otro mundo mushoku tensei: jobless reincarnation parte 2 реинкарнация безработного mushoku tensei: перерождение безработного перерождение безработного реинкарнация безработного: история о приключениях в другом мире 無職轉生 無職轉生～到了異世界就拿出真本事 реінкарнація безробітного: історія про пригоди в іншому світі jobless reincarnation: i will seriously try if i go to another world mushoku tensei mushoku tensei: jobless reincarnation part 2 jobless reincarnation mushoku tensei: jobless reincarnation - eris the goblin slayer mushoku tensei: jobless reincarnation season 2 - guardian fitz 無職転生 ～異世界行ったら本気だす～', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lop-hoc-cua-meo-den-va-phu-thuy-hac-mieu-va-lop-hoc-phu-thuy', 'Lớp Học Của Mèo Đen Và Phù Thủy (Hắc Miêu Và Lớp Học Phù Thủy)', 'The Classroom Of A Black Cat And A Witch', 'https://phimimg.com/upload/vod/20260413-1/93efc2d5ad3299c2dc12c08520de5acb.jpg', 'https://phimimg.com/upload/vod/20260413-1/9776326318785b666ce90ecfdc3982c1.jpg', '<p>Spica Virgo luôn khao khát được gia nhập học viện phép thuật, nhưng có một vấn đề lớn: Cô hoàn toàn không thể sử dụng ma thuật! Không có người hướng dẫn hay bất kỳ mối quan hệ nào, cơ hội của cô dường như bằng không — cho đến khi một chú mèo đen biết nói đầy bí ẩn xuất hiện. Vốn là một pháp sư quyền năng bị dính lời nguyền trong hình hài mèo, ông ta đồng ý dạy cô phép thuật để đổi lấy sự giúp đỡ nhằm phá giải phong ấn. Khi bản giao kèo bí mật bắt đầu, Spica chính thức bước chân vào một thế giới của ma thuật, những ẩn số và những bất ngờ ngoài sức tưởng tượng.</p>', 'Tập 14', 24, 'hoathinh', 'ongoing', 36, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kaede Hondo","avatar":""},{"name":"Nobunaga Shimazaki","avatar":""},{"name":"Fuka Izumi","avatar":""},{"name":"Miho Wataya","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Kuroneko to Majo no Kyoushitsu","Kuroneko to Majo no Kyōshitsu","黒猫と魔女の教室"]', 1784690324116);
