INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-thoi-kaikigumi', 'Đi Thôi Kaikigumi', 'Let''s Go KAIKIGUMI', 'https://phimimg.com/upload/vod/20260706-1/571204c973f76dd9377a357420b15752.jpg', 'https://phimimg.com/upload/vod/20260706-1/680ae24ed59e33a7ab55234175942dc8.jpg', '<p>Một người đàn ông vô danh với nỗi sợ ma quái gấp sáu lần người bình thường bỗng chốc bị cuốn vào thế giới siêu nhiên. Mọi rắc rối bắt đầu khi anh tình cờ chạm trán với Mechako, một cô gái gan dạ đang điều hành Kaiki-gumi — tổ chức chuyên quản lý các hiện tượng siêu nhiên. Mechako đã lôi kéo anh vào hành trình giúp cô vực dậy tổ chức này. Từ đó, hàng loạt sự kiện kỳ lạ, dở khóc dở cười và những trò quậy phá đầy ma mị bắt đầu bùng nổ!</p>', 'Tập 2', 12, 'hoathinh', 'ongoing', 48, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Tasuku Hatanaka","avatar":""},{"name":"Ruriko Aoki","avatar":""},{"name":"Shigeru Chiba","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Lets Go Kaikigumi","レッツゴー怪奇組"]', 1784690324116);
