INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-bep-sieu-dang', 'Đầu Bếp Siêu Đẳng', 'Iron Wok Jan!', 'https://phimimg.com/upload/vod/20260706-1/b2bd6336d4e6266a9d3ac3b01c2f7cc6.jpg', 'https://phimimg.com/upload/vod/20260706-1/13d679c94a90467a85b46f88da920fef.jpg', '<p>Câu chuyện theo chân Jan, một bậc thầy đầu bếp món Hoa với phong cách đầy quái dị và ngông cuồng, người sẵn sàng làm bất cứ điều gì để nghiền nát các đối thủ của mình. Đây là một hành trình đầy kịch tính và nghẹt thở, nơi dàn nhân vật bất chấp mọi quy chuẩn đạo đức thông thường, xem nấu ăn như một thứ ma thuật và sáng tạo ra đủ loại món ăn hoang dại nhất. Jan thẳng tiến về phía trước để đối đầu với trận chiến ẩm thực Trung Hoa đỉnh cao, sẵn sàng thách thức cả thế giới!</p>', 'Tập 2', 12, 'hoathinh', 'ongoing', 45, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kikunosuke Toya","avatar":""},{"name":"Ikumi Hasegawa","avatar":""},{"name":"Kohei Amasaki","avatar":""},{"name":"Kenjiro Tsuda","avatar":""},{"name":"Masuo Amada","avatar":""},{"name":"Mao Ichimichi","avatar":""},{"name":"Takahiro Sakurai","avatar":""},{"name":"Taishi Murata","avatar":""},{"name":"Yusuke Kobayashi","avatar":""},{"name":"Tomokazu Sugita","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Tetsunabe no Jan!","铁锅料理王！","鉄鍋のジャン！"]', 1784690324116);
