INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chay-dua-cua-tinh-va-tien', 'Cuộc Chạy Đua Của Tình Và Tiền', 'The Running Of Love And Money', 'https://phimimg.com/upload/vod/20260629-1/b8d61d3c356a30941f0548973005b5cc.jpg', 'https://phimimg.com/upload/vod/20260629-1/d9d82ad102c98c4f158d025ed0b81b6b.jpg', '<p>Tình yêu, ước mơ, cuộc sống mưu sinh xoáy vào nhau khi nhóm &quot;Gen Me&quot; đối diện nhịp sống hối hả ở Thái Lan, nơi trưởng thành đánh đổi bằng nước mắt, tình cảm và sự thật nghiệt ngã.</p>', 'Tập 5', 19, 'series', 'ongoing', 88, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Eisaya Hosuwan","avatar":""},{"name":"Panuwat Premmaneenan","avatar":""},{"name":"Suppapong Udomkaewkanjana","avatar":""},{"name":"Tadsapon Wiwitawan","avatar":""},{"name":"Prima Bhunjaroeun","avatar":""},{"name":"Phatrakorn Boosarakumwadi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["The Running เงิน งาน ความรัก"]', 1784690324116);
