INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-mau-bi-mat-cua-tieu-thu', 'Bảo Mẫu Bí Mật Của Tiểu Thư', 'Rich Girl Caretaker: I''m Secretly the Caregiver of the Most Popular Girl in This Rich Kid School', 'https://phimimg.com/upload/vod/20260705-1/bb555252d6405782a1ca8c04a6f4f310.jpg', 'https://phimimg.com/upload/vod/20260705-1/9cb6f0492fcdf331cb804240d4c7e2e9.jpg', '<p>Hinako Konohana là một tiểu thư hoàn hảo trong mắt mọi người — duyên dáng, thanh lịch và không một tì vết… hoặc ít nhất đó là những gì họ nghĩ. Đằng sau cánh cửa đóng kín, cô nàng lại là một &quot;thảm họa&quot; toàn diện, kẻ thậm chí không thể tự xoay xở với những công việc nhà cơ bản nhất! Khi cậu học sinh bình thường Itsuki Tomonari trở thành người chăm sóc cho cô, cậu bị kéo vào cuộc chiến dọn dẹp rắc rối 24/7 để bảo vệ hình tượng &quot;hoàn mỹ&quot; của nàng tiểu thư. Cuộc sống chung đầy vụng về và hỗn loạn không ngừng ấy, trớ trêu thay, lại bắt đầu nhen nhóm thành một thứ cảm xúc ngọt ngào tựa như tình yêu…</p>', 'Tập 2', 12, 'hoathinh', 'ongoing', 59, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuto Uemura","avatar":""},{"name":"Konomi Kohara","avatar":""},{"name":"Saori Onishi","avatar":""},{"name":"Rio Tsuchiya","avatar":""},{"name":"Kentaro Kumagai","avatar":""},{"name":"Ami Maeshima","avatar":""},{"name":"Ami Koshimizu","avatar":""},{"name":"Takehito Koyasu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Saijo no Osewa: Takane no Hana-darake na Meimonkō de, Gakuin-ichi no Ojō-sama (Seikatsu Nōryoku Kai Mu)","Saijo no Osewa: Takane no Hanadarake na Meimonkou de, Gakuin Ichi no Ojousama (Seikatsu Nouryoku Kaimu) wo Kagenagara Osewa suru Koto ni Narimashita","Saijo no Osewa","Saijo no Osewa Takane no Hanadarake na Meimonkou de Gakuin Ichi no Ojou-sama Seikatsu Nouryoku Kaimu wo Kagenagara Osewa suru Koto ni Narimashita","Rich Girl Caretaker","才女のお世話 高嶺の花だらけな名門校で、学院一のお嬢様（生活能力皆無）を陰ながらお世話することになりました"]', 1784690324116);
