INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dac-vu-kim-tai-khoi-dong', 'Đặc Vụ Kim Tái Khởi Động', 'Agent Kim Reactivated', 'đặc vụ kim tái khởi động agent kim reactivated so ji-sub choi dae-hoon yoon kyung-ho ju sang-uk son na-eun lee dong-ha jo bok-rae kim sung-kyu won hyun-jun won tae-min 金部长 kim bujang kim bu-jang kim-bu-jang ඒජන්ට් කිම් රීඇක්ටිවේටඩ් ඒජන්ට් කිම්: නැවතත් ක්‍රියාත්මකයි ඒජන්ට් කිම්: නැවත සක්‍රීයයි ඒජන්ට් කිම් නැවත සක්‍රීයයි менеджер ким عودة العميل كيم director kim mr. kim manager kim mr kim bố tôi là đặc vụ đặc vụ kim quản lý kim 김부장', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lop-hoc-tinh-yeu-phan-3', 'Lớp Học Tình Yêu (Phần 3)', 'Love Class (Season 3)', 'https://phimimg.com/upload/vod/20260604-1/2353791bb14f17a7f695106b9c7c6852.jpg', 'https://phimimg.com/upload/vod/20260604-1/4e28f3a3299759d4bf98c97b154a46cc.jpg', '<p>Hyun Jae và Soo An từng gặp nhau trong một chương trình sống còn tuyển chọn idol. Trong thời gian thi đấu, cả hai dần nảy sinh tình cảm. Tuy nhiên cuối cùng chỉ có Hyun Jae được debut, còn Soo An bị loại, khiến họ phải chia xa dù vẫn còn tình cảm với nhau.</p>', 'Tập 14', 16, 'series', 'ongoing', 95, 2026, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Sae Byeol","avatar":""},{"name":"Seo I-han","avatar":""},{"name":"Lee Woo-jin","avatar":""},{"name":"Panutuch Saelee","avatar":""},{"name":"Kang Yeon","avatar":""},{"name":"Park Jin-seok","avatar":""},{"name":"Ahn Hyo-jun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["爱情同课程","僕らの恋は授業中です2","Sueobjung Ibnida","수업중입니다","Love Class","အချစ်တန်း","現正上課中"]', 1784690324116);
