INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lop-hoc-tinh-yeu-phan-3', 'Lớp Học Tình Yêu (Phần 3)', 'Love Class (Season 3)', 'lớp học tình yêu (phần 3) love class (season 3) sae byeol seo i-han lee woo-jin panutuch saelee kang yeon park jin-seok ahn hyo-jun 爱情同课程 僕らの恋は授業中です2 sueobjung ibnida 수업중입니다 love class အချစ်တန်း 現正上課中', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buoc-chan-vao-doi', 'Bước Chân Vào Đời', 'Step Into Life', 'https://phimimg.com/upload/vod/20260226-1/39e50c2e2e64f30fce13b4ec9cf98151.jpg', 'https://phimimg.com/upload/vod/20260226-1/0722263a7f51e2323aafb8b5841b2c63.jpg', '<p>Phim là cuộc hành trình trưởng thành của 3 chị em Thương (Quỳnh Kool), Trang (Ngọc Thủy), Minh (Sơn Tùng) sau biến cố bố mẹ đột ngột qua đời. Mỗi người một tính cách nhưng họ luôn yêu thương và bao bọc nhau. Trong đó, Quỳnh Kool đảm nhận vai chị cả Thương, cô vừa tốt nghiệp đại học sư phạm hơn 1 năm với tấm bằng giỏi nhưng vẫn lận đận chưa có việc làm. Giờ đây, Thương có cơ hội vào làm hợp đồng tại 1 trường cấp 2. Để có tiền mưu sinh, lo cho em gái học năm 3 đại học và em trai học lớp 11, Thương ngoài đi dạy còn phải làm nhiều công việc khác. Thế nhưng, tình yêu và sự bao bọc của Thương dành cho các em đôi khi lại lại khiến các em cảm thấy ngột ngạt, gây nên những xung đột không đáng có.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 123, 2026, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Quỳnh Kool","avatar":""},{"name":"Mạnh Trường","avatar":""},{"name":"Huỳnh Anh","avatar":""},{"name":"Ngọc Thủy","avatar":""},{"name":"Sơn Tùng","avatar":""},{"name":"NSND Lan Hương","avatar":""},{"name":"NSƯT Quách Thu Phương","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324116);
