INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanakimi-phan-2', 'Hana-Kimi (Phần 2)', 'Hana-Kimi (Season 2)', 'https://phimimg.com/upload/vod/20260705-1/a08c40145f765c8bd186e77ef8da67e6.jpg', 'https://phimimg.com/upload/vod/20260705-1/0019fafae5546eb65eeadcca477abb25.jpg', '<p>Mizuki Ashiya đang thực hiện một nhiệm vụ táo bạo: cải trang thành nam sinh và ghi danh vào một trường nội trú nam sinh để tiếp cận thần tượng của mình – ngôi sao nhảy cao Izumi Sano. Thế nhưng, sau khi thâm nhập thành công, cô bàng hoàng phát hiện ra anh đã đột ngột từ bỏ thể thao! Giờ đây, Mizuki vừa phải khéo léo né tránh mọi sự nghi ngờ để bảo vệ thân phận thật, vừa phải tìm cách lay động trái tim chàng trai mà cô hằng ngưỡng mộ — tất cả diễn ra giữa sự náo loạn và rắc rối của một ký túc xá toàn nam giới!</p>', 'Tập 3', 12, 'hoathinh', 'ongoing', 76, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Aya Yamane","avatar":""},{"name":"Taku Yashiro","avatar":""},{"name":"Kikunosuke Toya","avatar":""},{"name":"Koki Uchiyama","avatar":""},{"name":"Yuuichirou Umehara","avatar":""},{"name":"Reiji Kawashima","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hana-Kimi","Hanazakari no Kimitachi e","Hana-Kimi: For You in Full Blossom","For You in Full Blossom","花ざかりの君たちへ"]', 1784690324116);
