INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hanakimi-phan-2', 'Hana-Kimi (Phần 2)', 'Hana-Kimi (Season 2)', 'hana-kimi (phần 2) hana-kimi (season 2) aya yamane taku yashiro kikunosuke toya koki uchiyama yuuichirou umehara reiji kawashima hana-kimi hanazakari no kimitachi e hana-kimi: for you in full blossom for you in full blossom 花ざかりの君たちへ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vao-ma-gioi-roi-day-irumakun-phan-4', 'Vào Ma Giới Rồi Đấy! Iruma-kun (Phần 4)', 'Welcome To Demon School! Iruma-kun (Season 4)', 'https://phimimg.com/upload/vod/20260407-1/d12a54fa0682e1b66ab4c1b0f147b0ab.jpg', 'https://phimimg.com/upload/vod/20260407-1/c4b0b33444924bf81ca7bfe6081e4ef7.jpg', '<p>Iruma tiếp tục cuộc sống tại học viện Babyls với những thử thách ngày càng khó khăn. Cậu cùng các bạn phải đối mặt với kỳ thi mới và những âm mưu bí ẩn trong thế giới ma quái. Sự trưởng thành của Iruma dần được thể hiện khi cậu học cách bảo vệ bạn bè và khẳng định bản thân. Các mối quan hệ xung quanh cậu cũng trở nên sâu sắc và phức tạp hơn. Giữa tiếng cười và hiểm nguy, Iruma tiến gần hơn tới vị trí đặc biệt trong ma giới.</p>', 'Tập 15', 24, 'hoathinh', 'ongoing', 54, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ayumu Murase","avatar":""},{"name":"Ryohei Kimura","avatar":""},{"name":"Ayaka Asai","avatar":""},{"name":"Daisuke Ono","avatar":""},{"name":"Saori Hayami","avatar":""},{"name":"Takuya Sato","avatar":""},{"name":"Takaya Kuroda","avatar":""},{"name":"Mitsuki Saiga","avatar":""},{"name":"Yoshitaka Yamaya","avatar":""},{"name":"Nao Toyama","avatar":""},{"name":"Tetsuya Kakihara","avatar":""},{"name":"Kaede Hondo","avatar":""},{"name":"Gakuto Kajiwara","avatar":""},{"name":"Takuto Yoshinaga","avatar":""},{"name":"Genki Okawa","avatar":""},{"name":"Shunichi Toki","avatar":""},{"name":"Setsuo Ito","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Iruma à l’école des démons","डेमन स्कूल में आपका स्वागत है! इरुमा-कुन","Mairimashita! Iruma-kun","Mairimashita! Iruma-kun 2","Mairimashita, Iruma-kun","Mairimashita, Iruma-kun 2","Mairimashita! Iruma-kun 3","魔入りました！入間くん４","마계학교 이루마군","악마에 입문했습니다! 이루마 군","마계학교! 이루마군","Iruma w szkole demonów","อิรุมะคุงกับโรงเรียนปิศาจ","Welcome to Demon-School, Iruma-kun","Welcome to Demon School, Iruma-kun","The Demon, Iruma-kun, Came and Enrolled!","Enrolled Demon Iruma!","Here Comes the Demon! Iruma-Kun","Welcome to Demon School! Iruma-kun 2","Welcome to Demon-School! Iruma-kun 3","Vào Ma Giới Rồi Đấy","Vào Ma Giới Rồi Đấy! Iruma-kun","Vào Ma Giới Rồi Đấy Iruma-kun","魔入りました！入間くん"]', 1784690324116);
