INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vao-ma-gioi-roi-day-irumakun-phan-4', 'Vào Ma Giới Rồi Đấy! Iruma-kun (Phần 4)', 'Welcome To Demon School! Iruma-kun (Season 4)', 'vào ma giới rồi đấy! iruma-kun (phần 4) welcome to demon school! iruma-kun (season 4) ayumu murase ryohei kimura ayaka asai daisuke ono saori hayami takuya sato takaya kuroda mitsuki saiga yoshitaka yamaya nao toyama tetsuya kakihara kaede hondo gakuto kajiwara takuto yoshinaga genki okawa shunichi toki setsuo ito iruma à l’école des démons डेमन स्कूल में आपका स्वागत है! इरुमा-कुन mairimashita! iruma-kun mairimashita! iruma-kun 2 mairimashita, iruma-kun mairimashita, iruma-kun 2 mairimashita! iruma-kun 3 魔入りました！入間くん４ 마계학교 이루마군 악마에 입문했습니다! 이루마 군 마계학교! 이루마군 iruma w szkole demonów อิรุมะคุงกับโรงเรียนปิศาจ welcome to demon-school, iruma-kun welcome to demon school, iruma-kun the demon, iruma-kun, came and enrolled! enrolled demon iruma! here comes the demon! iruma-kun welcome to demon school! iruma-kun 2 welcome to demon-school! iruma-kun 3 vào ma giới rồi đấy vào ma giới rồi đấy! iruma-kun vào ma giới rồi đấy iruma-kun 魔入りました！入間くん', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-trai-cong-tuoc-tuyen-bo-se-khong-yeu-toi-nhung-van-ton-tho-toi', 'Con Trai Công Tước Tuyên Bố Sẽ Không Yêu Tôi Nhưng Vẫn Tôn Thờ Tôi', 'The Duke''s Son Claims He Won''t Love Me, But Showers Me With Adoration', 'https://phimimg.com/upload/vod/20260705-1/0eeac7b7da1c0a34155c0d3bbb7156c6.jpg', 'https://phimimg.com/upload/vod/20260705-1/9be8fa8b5c1f4f767a6153480304d4cd.jpg', '<p>Một cuộc hôn nhân sắp đặt. Hai người hoàn toàn xa lạ. Một câu chuyện tình yêu vô cùng đáng yêu! Khi tiểu thư quý tộc hoạt bát Elsa bất ngờ phải kết hôn với người kế vị công tước lạnh lùng Julius, cả hai đều không ngờ rằng cuộc hôn nhân chính trị này lại có thể làm nảy sinh một thứ tình cảm sâu đậm hơn. Giữa những hiểu lầm vụng về, những cử chỉ ngọt ngào và những rung động ngày một lớn dần, cặp đôi mới cưới này nhận ra rằng việc phải lòng nhau vừa là điều dễ dàng nhất, nhưng cũng là điều thử thách nhất trong cuộc sống hôn nhân.</p>', 'Tập 2', 12, 'hoathinh', 'ongoing', 54, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Soma Saito","avatar":""},{"name":"Yui Ishikawa","avatar":""},{"name":"Mariko Kouda","avatar":""},{"name":"Daisuke Namikawa","avatar":""},{"name":"Maaya Uchida","avatar":""},{"name":"Makoto Tamura","avatar":""},{"name":"Ryohei Kimura","avatar":""},{"name":"Chika Anzai","avatar":""},{"name":"Hibiku Yamamura","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["不爱公爵","说了不打算爱我的公爵继承人，不知为何对我宠爱有加","\"Kimi wo Aisuru Ki wa Nai\" to Itta Jiki Koushaku-sama ga Nazeka Dekiai Shitekimasu","きみ愛","Kimiai","Kimi wo Aisuru Ki wa nai to Itta Jiki Koushaku-sama ga Naze ka Dekiai Shitekimasu","The Duke’s Son Claims He Won’t Love Me Yet Showers Me with Adoration","「きみを愛する気はない」と言った次期公爵様がなぜか溺愛してきます"]', 1784690324116);
