INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('con-trai-cong-tuoc-tuyen-bo-se-khong-yeu-toi-nhung-van-ton-tho-toi', 'Con Trai Công Tước Tuyên Bố Sẽ Không Yêu Tôi Nhưng Vẫn Tôn Thờ Tôi', 'The Duke''s Son Claims He Won''t Love Me, But Showers Me With Adoration', 'con trai công tước tuyên bố sẽ không yêu tôi nhưng vẫn tôn thờ tôi the duke''s son claims he won''t love me, but showers me with adoration soma saito yui ishikawa mariko kouda daisuke namikawa maaya uchida makoto tamura ryohei kimura chika anzai hibiku yamamura 不爱公爵 说了不打算爱我的公爵继承人，不知为何对我宠爱有加 "kimi wo aisuru ki wa nai" to itta jiki koushaku-sama ga nazeka dekiai shitekimasu きみ愛 kimiai kimi wo aisuru ki wa nai to itta jiki koushaku-sama ga naze ka dekiai shitekimasu the duke’s son claims he won’t love me yet showers me with adoration 「きみを愛する気はない」と言った次期公爵様がなぜか溺愛してきます', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-menh-coi-hoang-tuyen', 'Song Mệnh Cõi Hoàng Tuyền', 'Daemons Of The Shadow Realm', 'https://phimimg.com/upload/vod/20260406-1/5b01bfa978886e99a559d3a0d9b8940e.jpg', 'https://phimimg.com/upload/vod/20260406-1/3c48ae9098dc344eb0dd90b9ed136bcd.jpg', '<p>Câu chuyện khởi nguồn tại Làng Đông, một ngôi làng nhỏ biệt lập trên núi, nơi thời gian như ngừng trôi suốt 400 năm. Chàng thợ săn trẻ Yuru sống bình yên bên mây ngàn gió núi và làm nhiệm vụ bảo vệ người em gái sinh đôi Asa. Thế nhưng, thế giới thanh bình ấy bỗng chốc vỡ vụn khi những “con rồng sắc” bay đầy trời, kéo theo một đạo quân trang bị vũ khí tối tân tàn sát dân làng. Từ đây, Yuru bước vào một hành trình đẫm máu tại xã hội hiện đại. Tâm điểm của cuộc chiến chính là bí ẩn về “Cặp song sinh chia cắt ngày và đêm” cùng sức mạnh thao túng Song Tinh, những linh thể mang sức mạnh hủy diệt luôn tồn tại theo đôi theo cặp.</p>', 'Tập 14', 24, 'hoathinh', 'ongoing', 71, 2026, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Kensho Ono","avatar":""},{"name":"Yume Miyamoto","avatar":""},{"name":"Yuichi Nakamura","avatar":""},{"name":"Misaki Kuno","avatar":""},{"name":"Takako Honda","avatar":""},{"name":"Rikiya Koyama","avatar":""},{"name":"Miyuri Shimabukuro","avatar":""},{"name":"Junichi Suwabe","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Yomi no Tsugai - Daemons do Reino das Sombras","