INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-sao-hay-sieu-xit', 'Siêu Sao Hay Siêu Xịt', 'Lost To Light', 'https://phimimg.com/upload/vod/20260622-1/7b286191e1a4bfca5980823dab19744a.jpg', 'https://phimimg.com/upload/vod/20260622-1/1b6811163c1de486f67cab2707a9d02d.jpg', '<p>Một nhóm nhạc thần tượng từng ôm mộng vinh quang nay phải đối mặt với nỗi tủi hổ khi phải mặc đồ linh vật biểu diễn các bài hát thiếu nhi. Lần lượt mọi người đều bỏ cuộc và rời đi… ngoại trừ Jeng, người duy nhất lựa chọn ở lại bên cạnh vị sếp Sithian bướng bỉnh, cố chấp của mình.</p>', 'Tập 4', 10, 'series', 'ongoing', 59, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Phemadech Vattanapati","avatar":""},{"name":"Ratchanon Khajitpornphun","avatar":""},{"name":"Thakrit Phatthanaworakit","avatar":""},{"name":"Posan Chaivirach","avatar":""},{"name":"Sunhanut Chaijarearn","avatar":""},{"name":"Jaturawit Cheawprasit","avatar":""},{"name":"Thanaphon Krawtima","avatar":""},{"name":"Phuminrat Manokan","avatar":""},{"name":"Phiravich Attachitsataporn","avatar":""},{"name":"Pannawit Phattanasiri","avatar":""},{"name":"Thanatchaphan Buranachiwawi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["迷失于光","อาจจะดัง หรือ อาจจะยัง"]', 1784690324116);
