INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngon-duoc-den', 'Ngọn Đuốc Đen', 'BLACK TORCH', 'https://phimimg.com/upload/vod/20260705-1/4d3ebec9ff1cc589f273f5ea080a4e41.jpg', 'https://phimimg.com/upload/vod/20260705-1/70406bff9bc6c46c77760afa1b842c2f.jpg', '<p>Jirô là một cậu bé có khả năng nói chuyện với động vật, được ông nuôi dưỡng và đào tạo thành ninja. Bị xa lánh vì khác biệt, cậu tìm thấy sự an ủi bên những loài động vật và bảo vệ chúng. Một ngày nọ, cậu cứu Ragô, một con mèo đen bị thương, nhưng phát hiện ra rằng nó không phải là mèo bình thường mà là một mononoke, một linh hồn đang bị một tổ chức bí ẩn săn đuổi. Không do dự, Jirô quyết định giúp đỡ nó.</p>', 'Tập 2', 13, 'hoathinh', 'ongoing', 81, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ryota Suzuki","avatar":""},{"name":"Yoji Ueda","avatar":""},{"name":"Sayaka Senbongi","avatar":""},{"name":"Junya Enoki","avatar":""},{"name":"Junichi Suwabe","avatar":""},{"name":"Reina Ueda","avatar":""},{"name":"Toshiyuki Morikawa","avatar":""},{"name":"Nobuhiko Okamoto","avatar":""},{"name":"Shinpachi Tsuji","avatar":""},{"name":"Yuhko Kaida","avatar":""},{"name":"Hochu Otsuka","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["黑炬","黑炬 Black Torch","BLACK TORCH 暗黑灯火","暗黑灯火","ブラックトーチ","Kara Meşale","BLACK TORCH 闇黑燈火","闇黑燈火","BLACK TORCH"]', 1784690324116);
