INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoanh-dau-lai-lau-nuoc-mat-cho-cau', 'Ngoảnh Đầu Lại Lau Nước Mắt Cho Cậu', 'Smile After Tears', 'https://phimimg.com/upload/vod/20260521-1/28e2e31c0af9493f7baf4a33ad713234.jpg', 'https://phimimg.com/upload/vod/20260521-1/01e4cd04d8ff52a0f32331f5d13b31b7.jpg', '<p>Trương Quân Gia, một học sinh chuyển trường luôn tỏ ra lạc quan dù mang nhiều áp lực gia đình và kinh tế, dần thay đổi khi gặp Hòa Ngạn Khải, chàng ca sĩ ban nhạc rực rỡ trên sân khấu trường học. Khi tình cảm giữa họ vừa chớm nở, một tai nạn bất ngờ đã cướp đi Tiểu Hòa, để lại Quân Gia chìm trong mất mát và nhớ thương. Trong những ngày cô đơn ấy, Trịnh Điêu Tần, thành viên đội bóng rổ luôn âm thầm ở bên, trở thành chỗ dựa giúp cậu học cách đối diện với nỗi đau. Đan xen giữa âm nhạc, ký ức và những rung động tuổi trẻ, bộ phim là hành trình chữa lành, buông bỏ quá khứ và bước tiếp với tình yêu còn ở lại trong tim.</p>', 'Tập 9', 12, 'series', 'ongoing', 54, 2026, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Dennis Chang","avatar":""},{"name":"Kai","avatar":""},{"name":"Brian Cheng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["转过头帮你擦眼泪","หันกลับมา เช็ดน้ำตาให้นาย","轉過頭幫你擦眼淚","轉過頭，幫你擦眼淚"]', 1784690324116);
