INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('meitantei-precure', 'Meitantei Precure!', 'Star Detective Precure!', 'https://phimimg.com/upload/vod/20260607-1/9369fb0b1a0db1c015470c105d065ba0.jpg', 'https://phimimg.com/upload/vod/20260607-1/0d46f3ca0500b986fda2df9d94ab9efa.jpg', '<p>Cốt truyện xoay quanh Anna Akechi, một nữ sinh 14 tuổi sống tại thành phố Makoto Mirai vào năm 2027. Vào ngày sinh nhật của mình, Anna được dẫn dắt bởi một tiên nữ tên là Pochitan và một chiếc mặt dây chuyền bí ẩn, khiến cô bị du hành ngược thời gian về thành phố Makoto Mirai của năm 1999. Tại đây, Anna gặp gỡ Mikuru Kobayashi, một cô gái trẻ đầy nhiệt huyết với ước mơ trở thành thám tử lừng danh. Khi một vụ trộm kỳ lạ xảy ra do những kẻ được gọi là &quot;Băng trộm bóng đêm&quot; (Phantom Thieves) thực hiện, cả hai đã cùng nhau biến hình thành các chiến binh nòng cốt</p>', 'Tập 23', 24, 'hoathinh', 'ongoing', 54, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hikari Senga","avatar":""},{"name":"Kaede Hondo","avatar":""},{"name":"Yuki Kaji","avatar":""},{"name":"Emiri Kato","avatar":""},{"name":"Satoshi Hino","avatar":""},{"name":"Yoshitsugu Matsuoka","avatar":""},{"name":"Ayaka Ohashi","avatar":""},{"name":"Eiichi Ishikawa","avatar":""},{"name":"Nao Toyama","avatar":""},{"name":"Hina Youmiya","avatar":""},{"name":"Shinnosuke Musashi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Viễn Tưởng","slug":"vien-tuong