INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('meitantei-precure', 'Meitantei Precure!', 'Star Detective Precure!', 'meitantei precure! star detective precure! hikari senga kaede hondo yuki kaji emiri kato satoshi hino yoshitsugu matsuoka ayaka ohashi eiichi ishikawa nao toyama hina youmiya shinnosuke musashi 名侦探光之美少女！ 名侦探光之美少女 名侦探偶像光之美少女♪ 名偵探光之美少女 star detective precure! meitantei pretty cure! great detective pretty cure! star detective pretty cure! star detective precure! 名探偵プリキュア！', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nu-phep-thuat-nanoha-exceeds', 'Thiếu Nữ Phép Thuật Nanoha EXCEEDS', 'Magical Girl Lyrical NANOHA EXCEEDS Gun Blaze Vengeance', 'https://phimimg.com/upload/vod/20260706-1/3ac8729f843495fb268641072a973034.jpg', 'https://phimimg.com/upload/vod/20260706-1/40bbf964e950a439724f18b1521ceee4.jpg', '<p>Ba mươi năm trước, người ngoài hành tinh đã tấn công Trái Đất và suýt chút nữa đẩy nhân loại đến bờ vực tuyệt chủng. Kể từ đó, loài người phải chật vật giành giật sự sống, chiến đấu với những kẻ xâm lược để giành lại từng tấc đất, và Liên Hợp Quốc đã thành lập EXCEEDS — một tổ chức chuyên ngăn chặn các mối đe dọa từ ngoài hành tinh. Tại một hòn đảo xa xôi giữa thế giới hỗn loạn, thợ săn trẻ Shiina luôn khao khát một cuộc sống bình yên bên cạnh người em gái Setsuna, thế nhưng một sự cố duy nhất đã cuốn cô vào trận chiến vĩ đại của nhân loại.</p>', 'Tập 2', 12, 'hoathinh', 'ongoing', 55, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Azusa Tachibana","avatar":""},{"name":"Rina Hidaka","avatar":""},{"name":"Yukari Tamura","avatar":""},{"name":"Nana Mizuki","avatar":""},{"name":"Kana Ueda","avatar":""},{"name":"Asaki Yuikawa","avatar":""},{"name":"Chiharu","avatar":""},{"name":"Aika Kobayashi","avatar":""},{"name":"Ayasa Ito","avatar":""},{"name":"Hina Aoki","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["魔法少女奈叶 EXCEEDS Gun Blaze Vengeance","Mahou Shoujo Lyrical Nanoha EXCEEDS Gun Blaze Vengeance","魔法少女リリカルなのは EXCEEDS Gun Blaze Vengeance"]', 1784690324116);
