INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-nang-mot-sach', 'Cô Nàng Mọt Sách', 'Ascendance Of A Bookworm (Adopted Daughter Of An Archduke)', 'https://phimimg.com/upload/vod/20260413-1/123b7a5cfa19c587ac0fb3395cd828f0.jpg', 'https://phimimg.com/upload/vod/20260413-1/7a0e4154b3a97790815b0ffa25ffcf2b.jpg', '<p>Ritsu được thừa hưởng giác quan thứ sáu từ ông nội, cùng với một hộ pháp bảo vệ thuộc cõi âm tên là Blue Storm. Những hiện tượng kỳ lạ dường như luôn bám theo bộ đôi này, và nhiệm vụ của họ là phải tìm ra chân tướng của những sự kiện bí ẩn đó. Mỗi câu chuyện là một phần độc lập nhưng đều có sự xuất hiện của các nhân vật quen thuộc những người mà bạn sẽ dần thấu hiểu và trân trọng khi chứng kiến cách họ đối mặt với những thứ &quot;không thuộc về thế giới này&quot; theo phong cách riêng của mỗi người.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 46, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuka Iguchi","avatar":""},{"name":"Show Hayami","avatar":""},{"name":"Mutsumi Tamura","avatar":""},{"name":"Takehito Koyasu","avatar":""},{"name":"Megumi Nakajima","avatar":""},{"name":"Tsuyoshi Koyama","avatar":""},{"name":"Fumiko Orikasa","avatar":""},{"name":"Tomoaki Maeno","avatar":""},{"name":"Kazuhiko Inoue","avatar":""},{"name":"Toshiyuki Morikawa","avatar":""},{"name":"Yuuichirou Umehara","avatar":""},{"name":"Yuko Sanpei","avatar":""},{"name":"Sho Karino","avatar":""},{"name":"Kiyono Yasuno","avatar":""},{"name":"Minami Takayama","avatar":""},{"name":"Yuka Terasaki","avatar":""},{"name":"Kik","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["O Sonho de uma Apaixonada por Livros","小書痴的下剋上","小書痴","爱书的下克上","小書痴的下剋上：為了成為圖書管理員不擇手段！","小书痴的下克上：为了成为图书管理员不择手段","Ascendance of a Bookworm","El ratón de Biblioteca","Ascenderé de ratón de biblioteca","El Ratón De Biblioteca: Haré cualquier cosa para convertirme en bibliotecaria","Honzuki no Gekokujō","本好きの下剋上","Honzuki no Gekokujou","Honzuki no Gekokujou: Shisho ni Naru Tame ni wa Shudan wo Erandeiraremasen","Honzuki no Gekokujou: Shisho ni Naru Tame ni wa Shudan o Erande Iraremasen","本好きの下剋上 司書になるためには手段を選んでいられません 第3期","本好きの下剋上～司書になるためには手段を選んでいられません～ 第3部","Honzuki no Gekokujou: Ryoushu no Youjo","本好きの下剋上 領主の養女","本好きの下剋上〜司書になるためには手段を選んでられません〜 領主の養女","책벌레의 하극상","책벌레의 하극상 ~사서가 되기 위해서라면 뭐든지 할 수 있어~ 영주의 양녀","Власть книжного червя: Я пойду на всё, чтоб стать библиотекарем","小書痴的下剋上第三季","小書痴的下剋上為了成為圖書管理員不擇手段第三季","小書痴的下剋上為了成為圖書管理員不擇手段","Історія буквоїжки: Стати бібліотекарем за будь-яку ціну","Ascendance of a Bookworm: Adopted Daughter of an Archduke","本好きの下剋上 司書になるためには手段を選んでいられません"]', 1784690324116);
