INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-nang-mot-sach', 'Cô Nàng Mọt Sách', 'Ascendance Of A Bookworm (Adopted Daughter Of An Archduke)', 'cô nàng mọt sách ascendance of a bookworm (adopted daughter of an archduke) yuka iguchi show hayami mutsumi tamura takehito koyasu megumi nakajima tsuyoshi koyama fumiko orikasa tomoaki maeno kazuhiko inoue toshiyuki morikawa yuuichirou umehara yuko sanpei sho karino kiyono yasuno minami takayama yuka terasaki kik o sonho de uma apaixonada por livros 小書痴的下剋上 小書痴 爱书的下克上 小書痴的下剋上：為了成為圖書管理員不擇手段！ 小书痴的下克上：为了成为图书管理员不择手段 ascendance of a bookworm el ratón de biblioteca ascenderé de ratón de biblioteca el ratón de biblioteca: haré cualquier cosa para convertirme en bibliotecaria honzuki no gekokujō 本好きの下剋上 honzuki no gekokujou honzuki no gekokujou: shisho ni naru tame ni wa shudan wo erandeiraremasen honzuki no gekokujou: shisho ni naru tame ni wa shudan o erande iraremasen 本好きの下剋上 司書になるためには手段を選んでいられません 第3期 本好きの下剋上～司書になるためには手段を選んでいられません～ 第3部 honzuki no gekokujou: ryoushu no youjo 本好きの下剋上 領主の養女 本好きの下剋上〜司書になるためには手段を選んでられません〜 領主の養女 책벌레의 하극상 책벌레의 하극상 ~사서가 되기 위해서라면 뭐든지 할 수 있어~ 영주의 양녀 власть книжного червя: я пойду на всё, чтоб стать библиотекарем 小書痴的下剋上第三季 小書痴的下剋上為了成為圖書管理員不擇手段第三季 小書痴的下剋上為了成為圖書管理員不擇手段 історія буквоїжки: стати бібліотекарем за будь-яку ціну ascendance of a bookworm: adopted daughter of an archduke 本好きの下剋上 司書になるためには手段を選んでいられません', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-meo-va-con-rong', 'Con Mèo Và Con Rồng', 'The Cat And The Dragon', 'https://phimimg.com/upload/vod/20260628-1/72b2dbd4ea6b8259b07dd9abe2618d0a.jpg', 'https://phimimg.com/upload/vod/20260628-1/42ef1fa70615d6076afd6d4c72ccef28.jpg', '<p><span class="">Mồ côi ngay từ khi mới nở,</span><span class=""> chú rồng cô độc mang tên &quot;Bác Đôi Cánh&quot; được một gia đình mèo biết sử dụng ma thuật nhận nuôi và nuôi nấng như con ruột.</span><span class=""> Khi lớn lên,</span><span class=""> Bác Đôi Cánh trở thành người bảo vệ cho đàn mèo,</span><span class=""> quyết tâm giữ cho chúng được an toàn trước loài người.</span><span class=""> Thế nhưng,</span><span class=""> khi chứng kiến những chú mèo dùng phép thuật của mình để kết nối với con người,</span><span class=""> Bác Đôi Cánh cũng dần mở lòng và có thiện cảm hơn với họ trong câu chuyện đầy cảm xúc và xúc động này.</span></p>', 'Tập 3', 12, 'hoathinh', 'ongoing', 50, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Takehito Koyasu","avatar":""},{"name":"Kikuko Inoue","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["猫与龙","Neko to Ryū","The Cat and the Dragon","猫と竜"]', 1784690324116);
