INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-thu-2026', 'Báo Thù', 'Payback', 'https://phimimg.com/upload/vod/20260531-1/68b88366c18cc8eb0427da64dcd82cb9.jpg', 'https://phimimg.com/upload/vod/20260531-1/44b98f8dceee0f4b7f0a576c9237410e.jpg', '<p>Một nhân viên đòi nợ thuê đang ôm nỗi đau mất mát quyết định dấn thân vào thế giới giải trí đầy rẫy thị phi để tìm cách trả thù. Thế nhưng, tại nơi đây, người này lại bất ngờ rơi vào một mối tình đầy nguy hiểm và mê hoặc với một vị giám đốc điều hành quyền lực.</p>', 'Tập 7', 8, 'series', 'ongoing', 105, 2026, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Thanakorn Wichanukhor","avatar":""},{"name":"Jarukit Kaewmoonrueang","avatar":""},{"name":"Paramee Thesdaroon","avatar":""},{"name":"Thanawat Shinawatra","avatar":""},{"name":"Chaikamon Sermsongwittaya","avatar":""},{"name":"Jirapat Uttamanan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["复仇","改过迁善","改過遷善","Payback The Series","เพย์แบค เดอะซีรีส์"]', 1784690324116);
