INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bao-thu-2026', 'Báo Thù', 'Payback', 'báo thù payback thanakorn wichanukhor jarukit kaewmoonrueang paramee thesdaroon thanawat shinawatra chaikamon sermsongwittaya jirapat uttamanan 复仇 改过迁善 改過遷善 payback the series เพย์แบค เดอะซีรีส์', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('100-ngay-tro-thanh-vua', '100 Ngày Trở Thành Vua', 'Crowned In A Hundred Days', 'https://phimimg.com/upload/vod/20260705-1/be3861cd61b17562208ac480e1a72485.jpg', 'https://phimimg.com/upload/vod/20260705-1/fa3aca9eeb59b42dfcda83b0c2d85fd4.jpg', '<p>Bị dồn đến bờ vực của sự tuyệt vọng, Minh — chủ của một quán ăn — đã tạo nên một mối liên kết không tưởng với linh hồn của chân mệnh Thiên tử là Quốc vương Lie sau khi nuốt chửng linh hồn này để cứu lấy người mình yêu. Bị ràng buộc bởi định mệnh, cả hai dấn thân vào một cuộc hành trình đầy hiểm nguy để thách thức kẻ bạo chúa đã chiếm đoạt ngai vàng. Với vỏn vẹn một trăm ngày để xoay chuyển số phận, Minh đã tận dụng trí nhớ phi thường của mình để làm chủ những ma pháp cổ xưa đã thất truyền từ lâu, đồng thời chiêu mộ đồng minh và thu phục lòng dân trên suốt chặng đường. Khi sức mạnh ngày một lớn dần, quyết tâm lật đổ triều đại thối nát, đòi lại vương vị cho vị vua đích thực và khôi phục thái bình cho vương quốc của họ lại càng thêm sục sôi.</p>', 'Tập 6', 25, 'hoathinh', 'ongoing', 69, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Gu Jiangshan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Bai Ri Cheng Wang","百日成王"]', 1784690324116);
