INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('100-ngay-tro-thanh-vua', '100 Ngày Trở Thành Vua', 'Crowned In A Hundred Days', '100 ngày trở thành vua crowned in a hundred days gu jiangshan bai ri cheng wang 百日成王', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trach-thien-ky', 'Trạch Thiên Ký', 'Fighter Of The Destiny 3D', 'https://phimimg.com/upload/vod/20260204-1/1aca6f23b3cda6ce17fbfe32ada51669.jpg', 'https://phimimg.com/upload/vod/20260204-1/551fbd9cb8955022c0b50a60727decaa.jpg', '<p>Sinh ra đã bị thời gian kết án, chàng trai họ Trần mang theo hơi thở mong manh bước ra khỏi núi hoang, chọn đối diện vận mệnh thay vì chờ nó khép lại. Một thân bệnh tật, một lòng không khuất phục, đó là hành trang duy nhất khi hắn tiến vào trung tâm quyền lực của thiên hạ, nơi kẻ yếu chỉ là quân cờ. Thế cuộc không dung người trái ý. Một mối ràng buộc từ quá khứ khiến hắn trở thành mục tiêu, bị đẩy khỏi ánh đèn danh vọng, lưu đày vào nơi hoang phế. Chính tại chốn bị quên lãng ấy, &nbsp;hắn lật mở cổ điển thất truyền, lấy tri thức xưa làm đuốc, từng bước dò đường giữa bóng tối. Giữa chiến địa phong kín, hắn gặp lại người con gái mang dung nhan phượng hoàng dưới lớp ngụy trang. Hai người kề vai trong máu lửa, lấy sinh tử vá lại niềm tin, đập tan mưu đồ hắc ám.</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 64, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xinran Yang","avatar":""},{"name":"Duan Yixuan","avatar":""},{"name":"Sanshi","avatar":""},{"name":"童思琦","avatar":""},{"name":"乔耀辉","avatar":""},{"name":"李乘风","avatar":""},{"name":"葉保華","avatar":""},{"name":"Liu Mingyue","avatar":""},{"name":"Li Lanling","avatar":""},{"name":"Zheng Liu","avatar":""},{"name":"Zhenyan Liu","avatar":""},{"name":"Lin Maomao","avatar":""},{"name":"Tong Yin","avatar":""},{"name":"Yeqiao Yan","avatar":""},{"name":"孙佳禾","avatar":""},{"name":"Shuiyu Tang","avatar":""},{"name":"乔木心 Muxin Qiao","avatar":""},{"name":"程美璇","avatar":""},{"name":"Zhang Huzi","avatar":""},{"name":"Chang Rongshan","avatar":""},{"name":"图特哈蒙","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["择天记3D","Ze Tian Ji","Fighter of the Destiny","Way of Choices","Fighter of the Destiny (3D)","择天记"]', 1784690324116);
