INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('trach-thien-ky', 'Trạch Thiên Ký', 'Fighter Of The Destiny 3D', 'trạch thiên ký fighter of the destiny 3d xinran yang duan yixuan sanshi 童思琦 乔耀辉 李乘风 葉保華 liu mingyue li lanling zheng liu zhenyan liu lin maomao tong yin yeqiao yan 孙佳禾 shuiyu tang 乔木心 muxin qiao 程美璇 zhang huzi chang rongshan 图特哈蒙 择天记3d ze tian ji fighter of the destiny way of choices fighter of the destiny (3d) 择天记', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('manh-ghep-bi-an', 'Mảnh Ghép Bí Ẩn', 'The Murder Puzzle', 'https://phimimg.com/upload/vod/20260702-1/cdea57137cb6b0d8cb1d3b932f808edc.jpg', 'https://phimimg.com/upload/vod/20260702-1/fcd0a866253f0559bf4c18ecbed9f3ee.jpg', '<p>Phó đội trưởng Đội Trọng án Lý Khải Dương cùng người đồ đệ &quot;oan gia&quot; Giang Hãn hợp sức điều tra hàng loạt vụ án bạo dâm liên hoàn và những vụ án xác chết khỏa thân đầy bí ẩn. Không ngờ, một vụ rơi lầu lại tiếp tục xảy ra, trong khi &quot;Găng Tay Đỏ&quot; - kẻ từng bị bắn hạ - lại kỳ dị xuất hiện như thể sống lại, liên tiếp gây ra những thảm án mới. Nhờ hai thầy trò không tiếc hy sinh, dốc hết sức mình điều tra, chân tướng của một vụ án bí ẩn bị chôn vùi suốt nhiều năm cuối cùng cũng dần được hé lộ.</p>', 'Hoàn Tất (34/34)', 34, 'series', 'completed', 182, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Kim Hiền Chính","avatar":""},{"name":"Viên Tử Minh","avatar":""},{"name":"Tào Tử Hàm","avatar":""},{"name":"Vương Tử Thần","avatar":""},{"name":"Davia","avatar":""},{"name":"Diên Tường","avatar":""},{"name":"Phan Tử Hân","avatar":""},{"name":"Tào Kỳ Nguyên","avatar":""},{"name":"Lưu Giai Manh","avatar":""},{"name":"Triệu Cương","avatar":""},{"name":"Tô Vũ Nhuận","avatar":""},{"name":"Tống Nhất","avatar":""},{"name":"Châu Tử Hạ","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mi An Pin Tu","谜案拼图"]', 1784690324116);
