INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('manh-ghep-bi-an', 'Mảnh Ghép Bí Ẩn', 'The Murder Puzzle', 'mảnh ghép bí ẩn the murder puzzle kim hiền chính viên tử minh tào tử hàm vương tử thần davia diên tường phan tử hân tào kỳ nguyên lưu giai manh triệu cương tô vũ nhuận tống nhất châu tử hạ mi an pin tu 谜案拼图', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-tro-thanh-huyen-thoai-sau-tran-chien-cuoi-cung-keo-dai-10-nam', 'Tôi Trở Thành Huyền Thoại Sau Trận Chiến Cuối Cùng Kéo Dài 10 Năm', 'I Became A Legend After My 10 Year-Long Last Stand', 'https://phimimg.com/upload/vod/20260704-1/a8f6b21fcd15b32c96ced6bc94dea8d6.jpg', 'https://phimimg.com/upload/vod/20260704-1/a44afe16d4e891f03232d84f2cf1a78c.jpg', '<p>Luck, một pháp sư hạng S thuộc tổ đội anh hùng, đã quyết định ở lại chặn hậu và tử chiến với Ma Vương để cứu những người đồng đội của mình. Khi anh giành chiến thắng và trở về, mười năm đã trôi qua, và thế giới đã tôn vinh anh như một anh hùng huyền thoại đã hy sinh nơi sa trường. Không thể quay lại cuộc sống trước kia, Luck đành che giấu thân phận và bắt đầu lại từ đầu với cái tên &quot;Lock&quot; — một mạo hiểm giả hạng F, tự tay gầy dựng lại tương lai trong một thế giới vốn đã tiếp diễn mà không có anh.</p>', 'Tập 2', 12, 'hoathinh', 'ongoing', 66, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Gakuto Kajiwara","avatar":""},{"name":"Toshiyuki Morikawa","avatar":""},{"name":"Tsuyoshi Koyama","avatar":""},{"name":"Yui Ishikawa","avatar":""},{"name":"Mayu Sagara","avatar":""},{"name":"Mao Ichimichi","avatar":""},{"name":"Yurie Kozakai","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Koko wa Ore ni Makasete Saki ni Ike to Itte kara 10-nen ga Tattara Densetsu ni Natteita.","Kokoore","ここ俺","Koko wa Ore ni Makasete Saki ni Ike to Ittekara 10-nen ga Tattara Densetsu ni Natteita","ここは俺に任せて先に行けと言ってから10年がたったら伝説になっていた。"]', 1784690324116);
