INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('toi-tro-thanh-huyen-thoai-sau-tran-chien-cuoi-cung-keo-dai-10-nam', 'Tôi Trở Thành Huyền Thoại Sau Trận Chiến Cuối Cùng Kéo Dài 10 Năm', 'I Became A Legend After My 10 Year-Long Last Stand', 'tôi trở thành huyền thoại sau trận chiến cuối cùng kéo dài 10 năm i became a legend after my 10 year-long last stand gakuto kajiwara toshiyuki morikawa tsuyoshi koyama yui ishikawa mayu sagara mao ichimichi yurie kozakai koko wa ore ni makasete saki ni ike to itte kara 10-nen ga tattara densetsu ni natteita. kokoore ここ俺 koko wa ore ni makasete saki ni ike to ittekara 10-nen ga tattara densetsu ni natteita ここは俺に任せて先に行けと言ってから10年がたったら伝説になっていた。', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-hong-ruc-lua', 'Hoa Hồng Rực Lửa', 'Burning Rose', 'https://phimimg.com/upload/vod/20260703-1/a2eaa143ce291388fcd8eb400e2d3cfb.jpg', 'https://phimimg.com/upload/vod/20260703-1/26444c7914bea3ce361d6e417299b716.jpg', '<p>Lấy bối cảnh một thành phố biên giới vào thập niên 1990, nhân viên tiệm mạt chược Điền Yên vì muốn cứu sư phụ nên cố ý tiếp cận thương nhân ngọc thạch nguy hiểm Bàng Kính Phú. Từ chỗ lợi dụng và nghi kỵ lẫn nhau, cả hai dần nảy sinh tình cảm, nhưng mối quan hệ luôn bị giằng xé giữa tình yêu, thù hận và những bí mật trong quá khứ.</p>', 'Tập 24', 24, 'series', 'ongoing', 162, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chung Nhã Đình","avatar":""},{"name":"Trần Thánh Hanh","avatar":""},{"name":"Trịnh Thư Hoàn","avatar":""},{"name":"Diêu Tinh Hạo","avatar":""},{"name":"Vương Vân Phàm","avatar":""},{"name":"Châu Mộc","avatar":""},{"name":"Triệu Dạng","avatar":""},{"name":"Lộ Hân","avatar":""},{"name":"Đinh Hiểu Minh","avatar":""},{"name":"Lâm Tử Lộ","avatar":""},{"name":"Tùng Thụy Lân","avatar":""},{"name":"Tôn Chinh Vũ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Ke Zhi Sheng Wen","克制升温"]', 1784690324116);
