INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giot-ruou-than-thanh-2026', 'Giọt Rượu Thần Thánh', 'The Drops Of God', 'https://phimimg.com/upload/vod/20260413-1/201f677ff7c169d650dc9dd620950d4c.jpg', 'https://phimimg.com/upload/vod/20260413-1/0349d814fb2c329fed969eb51e4704fa.jpg', '<p>Khi nhà phê bình rượu vang nổi tiếng thế giới Toyotaka Kanzaki qua đời, &nbsp;ông để lại một bộ sưu tập đáng ghen tị. Di chúc hứa sẽ trao toàn bộ gia sản cho bất cứ ai đoán đúng nhãn hiệu và năm sản xuất của 12 loại rượu vang hảo hạng nhất mà ông đã chọn, &nbsp;và loại rượu vang huyền thoại đứng đầu trong số đó, &quot;Drops of God&quot; (Giọt Thần). Những người thách đấu là con trai của Toyotaka, &nbsp;Shizuku Kanzaki, và một nhà phê bình trẻ tuổi, Issei Tomine, người được Toyotaka nhận làm con nuôi.</p>', 'Tập 14', 24, 'hoathinh', 'ongoing', 42, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Takuya Sato","avatar":""},{"name":"Kazuya Kamenashi","avatar":""},{"name":"Maaya Uchida","avatar":""},{"name":"Banjo Ginga","avatar":""},{"name":"Yuhko Kaida","avatar":""},{"name":"Shinshu Fuji","avatar":""},{"name":"Misa Watanabe","avatar":""},{"name":"Yuuya Uchida","avatar":""},{"name":"Jin Urayama","avatar":""},{"name":"Lynn","avatar":""},{"name":"Akihiko Ishizumi","avatar":""},{"name":"Soshiro Hori","avatar":""},{"name":"Konomi Kohara","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Les Gouttes de Dieu","Kami no Shizuku","Drops of God","神の雫"]', 1784690324116);
