INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ve-xong-di-roi-hay-chet', 'Vẽ Xong Đi, Rồi Hãy Chết!', 'Draw This, Then Die!', 'https://phimimg.com/upload/vod/20260705-1/6aba22327663c3122b8e9184764e375d.jpg', 'https://phimimg.com/upload/vod/20260705-1/6b0abe9e476c2371ef7e79a385f58479.jpg', '<p>Ai Yasumi là nữ sinh năm nhất trung học sống trên đảo Izu Ōshima, đồng thời là một cô gái vô cùng yêu thích truyện tranh manga. Thế nhưng, sau một bước ngoặt trong cuộc đời, Ai quyết tâm không chỉ đọc manga mà còn tự mình sáng tác nên những câu chuyện của riêng mình. Khi dấn thân vào con đường trở thành họa sĩ truyện tranh, Ai phải đối mặt với vô vàn thử thách, không ngừng trưởng thành và trải nghiệm niềm vui xen lẫn khó khăn trong hành trình theo đuổi ước mơ sáng tạo. Cuộc hành trình ấy rồi sẽ đưa cô đến đâu?</p>', 'Tập 2', 12, 'hoathinh', 'ongoing', 47, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Akira Sekine","avatar":""},{"name":"Saori Hayami","avatar":""},{"name":"Saya Hitomi","avatar":""},{"name":"Kanon Fujimura","avatar":""},{"name":"Inori Minase","avatar":""},{"name":"Noriko Hidaka","avatar":""},{"name":"Atsumi Tanezaki","avatar":""},{"name":"Yukana","avatar":""},{"name":"Kikuko Inoue","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["描绘直至生命尽头","画完这个再去死","Kore Kaite Shine","Намалюй це і помри","Draw This and Die","これ描いて死ね"]', 1784690324116);
