INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nu-quai-vat-caramelise', 'Thiếu Nữ Quái Vật Caramelise', 'KAIJU GIRL CARAMELISE', 'https://phimimg.com/upload/vod/20260705-1/de6a0162ba87730b3a2b19a4df2e6b9f.jpg', 'https://phimimg.com/upload/vod/20260705-1/043c383c01c00117e193b52790c1d630.jpg', '<p>Kuroe Akaishi chỉ muốn có một cuộc sống trung học bình thường — nhưng điều đó là không thể khi cô mắc phải một căn bệnh hiếm gặp: cứ mỗi khi cảm xúc dâng trào là cô lại biến thành một quái thú kaiju khổng lồ! Mọi chuyện thậm chí còn tồi tệ hơn khi cô lỡ đem lòng thầm thương trộm nhớ Arata Minami, nam sinh nổi tiếng nhất lớp. Giờ đây, mỗi cái đỏ mặt, mỗi nhịp tim loạn nhịp hay một chút rung động cũng có thể kích hoạt quá trình biến hình thành quái vật. Liệu Kuroe có thể sống sót qua tình yêu tuổi học trò trước khi nó phá hủy mọi thứ xung quanh cô?!</p>', 'Tập 2', 12, 'hoathinh', 'ongoing', 53, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hikari Senga","avatar":""},{"name":"Daishi Kajita","avatar":""},{"name":"Akira Sekine","avatar":""},{"name":"Haruka Shiraishi","avatar":""},{"name":"Kotono Mitsuishi","avatar":""},{"name":"Katsuyuki Konishi","avatar":""},{"name":"Eriko Matsui","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["少女怪兽焦糖味","少女怪兽焦糖恋心","Otome Kaijuu Carameliser","Otome Kaijū Carameliser","Otome Kaiju Caramelize","Meiden Kaiju Carameliser","Monster Maiden Caramelise","Kaiju Girl Caramelize","Kaiju Girl Caramelise","乙女怪獣キャラメリゼ"]', 1784690324116);
