INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lanh-chua-vung-dat-khong-cu-dan', 'Lãnh Chúa Vùng Đất Không Cư Dân', 'The Frontier Lord Begins With Zero Subjects', 'https://phimimg.com/upload/vod/20260704-1/bb60d3ab25624df34574d31752b9eb6a.jpg', 'https://phimimg.com/upload/vod/20260704-1/7db800258223261eb92a9a4796b73549.jpg', '<p>Chiến tranh đã kết thúc, và người anh hùng Dias cuối cùng cũng được ban thưởng một vùng đất riêng – nhưng anh phát hiện ra đó là một vùng biên giới hoang vu, không có người, không có làng mạc, và không có dấu hiệu của nền văn minh. Với chỉ những thảo nguyên trải dài vô tận trước mặt, Dias bắt đầu xây dựng lãnh địa của mình từ con số không. Nhưng sau khi gặp Alna, một cô gái bí ẩn với chiếc sừng màu xanh lam, vùng biên giới cô đơn của anh sắp sửa bừng tỉnh sức sống.</p>', 'Tập 2', 12, 'hoathinh', 'ongoing', 48, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kenichirou Matsuda","avatar":""},{"name":"Shion Wakayama","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Ryōmin 0-nin Start no Henkyō Ryōshu-sama","Ryoumin 0-nin Start no Henkyou Ryoushu-sama","Ryoumin 0 Nin Start no Henkyou Ryoushu-sama","Ryoumin Nin Start No Henkyou Ryoushu Sama","領民0人スタートの辺境領主様"]', 1784690324116);
