INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trong-giap-hiep-si-chuyen-sinh-bi-luu-day-tro-nen-vo-dich-nho-kien-thuc-ve-game', 'Trọng Giáp Hiệp Sĩ Chuyển Sinh Bị Lưu Đày Trở Nên Vô Địch Nhờ Kiến Thức Về Game', 'The Exiled Heavy Knight Knows How To Game The System', 'https://phimimg.com/upload/vod/20260704-1/732482354bbfaf0663881f84392f73df.jpg', 'https://phimimg.com/upload/vod/20260704-1/4b4d7d08fc0707be4fe3940998383a8f.jpg', '<p>Trong Nghi lễ Ban Phước Thần Thánh nhằm xác định đẳng cấp của tuổi 15, Elymas thức tỉnh lớp nhân vật Trọng Giáp Hiệp Sĩ, vốn bị coi là khiếm khuyết và vô dụng. Vì vậy, cậu bị tước quyền thừa kế gia tộc Edvaughn và chịu kiếp lưu đày. Thế nhưng, Elymas nhanh chóng nhận ra thế giới này giống hệt trò chơi cậu từng chinh phục ở kiếp trước, nơi Trọng Giáp Hiệp Sĩ mới là lớp nhân vật mạnh nhất. Mang theo ký ức về mọi bí mật của thế giới, cậu quyết tâm lật ngược số phận và từng bước vươn tới đỉnh cao sức mạnh.</p>', 'Tập 2', 26, 'hoathinh', 'ongoing', 56, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Takeo Otsuka","avatar":""},{"name":"Shion Wakayama","avatar":""},{"name":"Natsuko Abe","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["遭到流放的转生重骑士凭借游戏知识大开无双","被追放的转生重骑士用游戏知识开无双","Tsuihou sareta Tensei Juukishi wa Game Chishiki de Musou suru","Tsuihō Sareta Tensei Jū Kishi wa Game Chishiki de Musō Suru","The Exiled Heavy Knight Knows How to Game the System","追放された転生重騎士はゲーム知識で無双する"]', 1784690324116);
