INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('trong-giap-hiep-si-chuyen-sinh-bi-luu-day-tro-nen-vo-dich-nho-kien-thuc-ve-game', 'Trọng Giáp Hiệp Sĩ Chuyển Sinh Bị Lưu Đày Trở Nên Vô Địch Nhờ Kiến Thức Về Game', 'The Exiled Heavy Knight Knows How To Game The System', 'trọng giáp hiệp sĩ chuyển sinh bị lưu đày trở nên vô địch nhờ kiến thức về game the exiled heavy knight knows how to game the system takeo otsuka shion wakayama natsuko abe 遭到流放的转生重骑士凭借游戏知识大开无双 被追放的转生重骑士用游戏知识开无双 tsuihou sareta tensei juukishi wa game chishiki de musou suru tsuihō sareta tensei jū kishi wa game chishiki de musō suru the exiled heavy knight knows how to game the system 追放された転生重騎士はゲーム知識で無双する', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luc-do-toi-da-chuyen-sinh-thanh-slime-phan-4', 'Lúc Đó Tôi Đã Chuyển Sinh Thành Slime (Phần 4)', 'That Time I Got Reincarnated As A Slime (Season 4)', 'https://phimimg.com/upload/vod/20260406-1/26f4b114b4e3d0ac0bba2f6687131a3c.jpg', 'https://phimimg.com/upload/vod/20260407-1/ab90a78161fa03e2b3f48f84bf250d05.jpg', '<p>Chuyển thể từ light novel cùng tên của tác giả Fuse. Anh chàng Satoru Mikami, 37 tuổi, FA nhiều năm với sống cuộc sống chán chường và không mấy vui vẻ gì. Ngày kia vận số đen đủi bám lấy anh chàng, bị cướp tấn công, giết ngay tại chỗ, tưởng chừng tháng ngày chán ngắt ấy đã kết thúc. Nhưng không! Ấy lại chính là sự khởi đầu của một cuộc sống mới, Mikami tỉnh dậy, thấy mình đang ở trong một thế giới kì lạ.

Và điều quái dị là anh ta không còn hình dạng người nữa mà đã trở thành quái vật slime dẻo quẹo và không có mắt. Khi dần quen với hình dáng mới này, anh chàng bắt đầu khám phá thế giới cùng với những quái vật khác. Và thế là, cuộc đời làm Slime ở một thế giới mới bắt đầu.</p>', 'Tập 14', 24, 'hoathinh', 'ongoing', 58, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Miho Okasaki","avatar":""},{"name":"Tomoaki Maeno","avatar":""},{"name":"Takuya Eguchi","avatar":""},{"name":"Hochu Otsuka","avatar":""},{"name":"Asuna Tomari","avatar":""},{"name":"Chikahiro Kobayashi","avatar":""},{"name":"Jun Fukushima","avatar":""},{"name":"Rie Tanaka","avatar":""},{"name":"Rina Hidaka","avatar":""},{"name":"Anzu Haruno","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Aquella vez que reencarne como un Slime","關於我轉生變成史萊姆這檔事","Tensei Shitara Slime Datta Ken","关于我转生变成史莱姆这档事","That Time I Got Reincarnated as a Slime","TenSura","Regarding Reincarnated to Slime","Aquella vez que me convertí en Slime","Moi, quand je me réincarne en Slime","تولد دوباره به‌عنوان یک اسلایم","وقتی به‌عنوان یک اسلایم تناسخ پیدا کردم","آن زمان که به‌عنوان یک اسلایم زندگی دوباره یافتم","Tensei shitara Slime Datta Ken","Tensei Slime","TenSura 2","Tensei shitara Slime Datta Ken 2","転生したらスライムだった件","転スラ","Tensei Shitara Slime Datta Ken 3rd Season","Tensei Shitara Slime Datta Ken: Coleus no Yume","Tensei Shitara Slime Datta Ken S4","Tensei Shitara Slime Datta Ken 4th Season","전생했더니 슬라임이었던 건에 대하여","전생했더니 슬라임이었던 건에 대하여 3기","關於我轉生變成史萊姆這檔事 柯里烏斯之夢","Моє переродження в Слиз","That Time I Got Reincarnated as a Slime 2","That Time I Got Reincarnated as a Slime: Visions of Coleus","Chuyển Sinh Thành Slime"]', 1784690324116);
