INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('luc-do-toi-da-chuyen-sinh-thanh-slime-phan-4', 'Lúc Đó Tôi Đã Chuyển Sinh Thành Slime (Phần 4)', 'That Time I Got Reincarnated As A Slime (Season 4)', 'lúc đó tôi đã chuyển sinh thành slime (phần 4) that time i got reincarnated as a slime (season 4) miho okasaki tomoaki maeno takuya eguchi hochu otsuka asuna tomari chikahiro kobayashi jun fukushima rie tanaka rina hidaka anzu haruno aquella vez que reencarne como un slime 關於我轉生變成史萊姆這檔事 tensei shitara slime datta ken 关于我转生变成史莱姆这档事 that time i got reincarnated as a slime tensura regarding reincarnated to slime aquella vez que me convertí en slime moi, quand je me réincarne en slime تولد دوباره به‌عنوان یک اسلایم وقتی به‌عنوان یک اسلایم تناسخ پیدا کردم آن زمان که به‌عنوان یک اسلایم زندگی دوباره یافتم tensei shitara slime datta ken tensei slime tensura 2 tensei shitara slime datta ken 2 転生したらスライムだった件 転スラ tensei shitara slime datta ken 3rd season tensei shitara slime datta ken: coleus no yume tensei shitara slime datta ken s4 tensei shitara slime datta ken 4th season 전생했더니 슬라임이었던 건에 대하여 전생했더니 슬라임이었던 건에 대하여 3기 關於我轉生變成史萊姆這檔事 柯里烏斯之夢 моє переродження в слиз that time i got reincarnated as a slime 2 that time i got reincarnated as a slime: visions of coleus chuyển sinh thành slime', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-sugar-phan-2', 'Thám Tử Sugar (Phần 2)', 'Sugar (Season 2)', 'https://phimimg.com/upload/vod/20260622-1/b0209bc80e3103ffce7d5fcba5b024de.jpg', 'https://phimimg.com/upload/vod/20260622-1/d6476ee9f35ad61ed03b527097b0f8ff.jpg', '<p>Colin Farrell vào vai John Sugar, một thám tử tư hào hoa đang len lỏi qua những góc khuất tăm tối của vùng đất LA đầy nắng. Dù luôn nhìn thấy điểm tốt ở con người, Sugar lại bị ám ảnh bởi một bí mật quá đỗi nguy hiểm để có thể phơi bày.</p>', 'Tập 4', 8, 'series', 'ongoing', 78, 2026, 'Vietsub', 'FHD', 'Ireland', 0, '[{"name":"Colin Farrell","avatar":""},{"name":"Jin Ha","avatar":""},{"name":"Tony Dalton","avatar":""},{"name":"Raymond Lee","avatar":""},{"name":"Laura Donnelly","avatar":""},{"name":"Sasha Calle","avatar":""},{"name":"Shea Whigham","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["谜探休格","洛城奇探","謎探休格","סוכר","Sugar"]', 1784690324116);
