INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tadaima-ojamasaremasu', 'Tadaima, Ojamasaremasu!', 'Pardon the Intrusion, I''m Home!', 'https://phimimg.com/upload/vod/20260607-1/87bbd7c00962785bdd6add8380d8ab45.jpg', 'https://phimimg.com/upload/vod/20260607-1/e106cea9cc36f8885d67a1b4347a3515.jpg', '<p>Đây có phải là kiểu “ở ghép” thời nay không vậy?! Rinko – một nhân viên văn phòng 24 tuổi – sống một mình và bí mật là một otaku. Một ngày nọ, căn hộ của cô bất ngờ bị “thông” với hai phòng bên cạnh thông qua một cái lỗ trên tường. Ở phòng bên trái là một chàng trai trẻ trung, trông hiền lành nhưng lại đầy bí ẩn, và cực kỳ ngọt ngào với Rinko. Còn phòng bên phải là một người đàn ông có xu hướng bạo lực, cũng bí ẩn không kém... Nhưng khoan đã! “Mình… mình nghĩ là mình biết anh ta!” Không gian riêng tư duy nhất của Rinko – căn hộ của cô – giờ đã bị đảo lộn hoàn toàn. Từ đó, mỗi ngày của cô đều tràn ngập những tình huống hồi hộp, tim đập nhanh!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 31, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kana Hanazawa","avatar":""},{"name":"Kaito Ishikawa","avatar":""},{"name":"Haruki Ishiya","avatar":""},{"name":"Chiaki Kobayashi","avatar":""},{"name":"Riho Sugiyama","avatar":""},{"name":"Miyu Tomita","avatar":""},{"name":"Sumire Morohoshi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["当前、正被打扰中！","我回来了，他又来打扰了！","Tadaima Ojamasaremasu","Tadaima, Ojamasaremasu!","Disculpen la interrupción, estoy en casa!","I''m Home, Sorry for the Intrusion!","I''m Home, Pardoning the Intrusion","ただいま、おじゃまされます！"]', 1784690324116);
