INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tadaima-ojamasaremasu', 'Tadaima, Ojamasaremasu!', 'Pardon the Intrusion, I''m Home!', 'tadaima, ojamasaremasu! pardon the intrusion, i''m home! kana hanazawa kaito ishikawa haruki ishiya chiaki kobayashi riho sugiyama miyu tomita sumire morohoshi 当前、正被打扰中！ 我回来了，他又来打扰了！ tadaima ojamasaremasu tadaima, ojamasaremasu! disculpen la interrupción, estoy en casa! i''m home, sorry for the intrusion! i''m home, pardoning the intrusion ただいま、おじゃまされます！', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muc-do-hao-cam-cua-matsurikachan-da-vuot-nguong', 'Mức Độ Hảo Cảm Của Matsurika-chan Đã Vượt Ngưỡng', 'Marika''s Love Meter Malfunction', 'https://phimimg.com/upload/vod/20260521-1/2035a22087096763292daafd5b7ee179.jpg', 'https://phimimg.com/upload/vod/20260521-1/0a2b99bc2df80c14cbe8814bc47155e8.jpg', '<p>Tôi vốn chẳng đủ dũng khí để mở lời tỏ tình với cô bạn thanh mai trúc mã, Marika. Thế rồi một ngày nọ, tôi đã gửi gắm một điều ước mãnh liệt vào ngôi sao băng: Rằng tôi có thể đọc được cảm xúc của người khác giống như trong các trò chơi hẹn hò (dating sim). Ngay ngày hôm sau, thật không thể tin được, điều ước đó đã trở thành sự thật…?! Những &quot;thanh đo tình cảm&quot; đột ngột xuất hiện phía trên đầu các cô gái trong lớp. Trong lúc còn đang bàng hoàng trước cảnh tượng siêu thực này, tôi đánh liều kiểm tra thanh của Marika, để rồi chết lặng khi thấy mức độ thiện cảm của cậu ấy đã chạm đáy vực thẳm địa ngục…?! Marika, nếu cậu ghét tớ đến nhường ấy, vậy tại sao bấy lâu nay cậu luôn dịu dàng với tớ đến thế...? Sự thật đằng sau cảm xúc bị che giấu của Marika là gì? Liệu cậu ấy thực sự căm ghét tôi, hay là...?!</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 40, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kohei Amasaki","avatar":""},{"name":"Maaya Uchida","avatar":""},{"name":"Ayasa Ito","avatar":""},{"name":"Yurie Igoma","avatar":""},{"name":"Rie Kugimiya","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["茉莉花同学的好感度坏得很彻底","茉莉花同学","茉莉花同学的好感度","茉莉花同学的好感度崩了","Marika chan no koukando ha bukkowareteiru","Marika''s Love Meter Malfunction","茉莉花ちゃんの好感度はぶっ壊れている"]', 1784690324116);
