INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lua-trang-2026', 'Lửa Trắng', 'White Fire', 'https://phimimg.com/upload/vod/20260620-1/3e4a5707b7b1cd0e9e4fcee32e630cf1.jpg', 'https://phimimg.com/upload/vod/20260620-1/6af15a5d669675ae5a9bd4ef1efb4af4.jpg', '<p>Phim xoay quanh cuộc chiến chống tội phạm ma túy trong thời đại công nghệ số. Một loại ma túy mới mang tên &quot;Bụi Trắng&quot; được ngụy trang dưới nhiều vỏ bọc hợp pháp và lan rộng qua mạng xã hội, livestream và giới giải trí. Lực lượng công an phải đối đầu với các đường dây tội phạm ngày càng tinh vi để triệt phá tổ chức đứng sau.</p>', 'Tập 8', 20, 'series', 'ongoing', 218, 2026, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Thu Quỳnh","avatar":""},{"name":"Duy Hưng","avatar":""},{"name":"Việt Hoa","avatar":""},{"name":"Hồ Phong","avatar":""},{"name":"Phú Kiên","avatar":""},{"name":"Bảo Anh","avatar":""},{"name":"Nguyễn Mạnh Cường","avatar":""},{"name":"Cù Thị Trà","avatar":""},{"name":"Nguyễn Tú","avatar":""},{"name":"Lưu Duy Khánh","avatar":""},{"name":"Tuấn Cường","avatar":""},{"name":"Nông Dũng Nam","avatar":""},{"name":"Hoàng Du Ka","avatar":""},{"name":"Trương Thảo My","avatar":""},{"name":"Quỳnh Lương","avatar":""},{"name":"Nguyễn Trọng Nghĩa","avatar":""},{"name":"Bùi Quốc Việt","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Lửa trắng"]', 1784690324116);
