INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lua-trang-2026', 'Lửa Trắng', 'White Fire', 'lửa trắng white fire thu quỳnh duy hưng việt hoa hồ phong phú kiên bảo anh nguyễn mạnh cường cù thị trà nguyễn tú lưu duy khánh tuấn cường nông dũng nam hoàng du ka trương thảo my quỳnh lương nguyễn trọng nghĩa bùi quốc việt lửa trắng', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('karna-nguoi-bao-ve', 'Karna Người Bảo Vệ', 'Karna The Guardian', 'https://phimimg.com/upload/vod/20260511-1/33fc057ce771e24a58e4b333c4c1431b.jpg', 'https://phimimg.com/upload/vod/20260511-1/3e284a552dddd758be8c10f0c649d84c.jpg', '<p>Karna vốn sống như một cậu bé bình thường cho đến khi ác quỷ cổ xưa Kalimba thoát khỏi phong ấn và gieo rắc sự hỗn loạn khắp thế giới. Khi bóng tối xâm chiếm chính người mẹ của mình, sức mạnh trong Karna bừng tỉnh, hé lộ thân phận thực sự: Người Cân Bằng – một Hộ vệ được sinh ra để khôi phục lại sự hài hòa cho thế giới. Để cứu mẹ và ngăn chặn sự tàn phá của Kalimba, Karna phải rèn luyện để làm chủ nguồn sức mạnh tiềm ẩn, bằng không cậu sẽ mất đi tất cả những gì mình yêu thương.</p>', 'Tập 10', 12, 'hoathinh', 'ongoing', 35, 2026, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Aditya Pednekar","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Karna the Guardian"]', 1784690324116);
