INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieng-anh-thanh-tieng-yeu', 'Tiếng Anh Thành Tiếng Yêu', 'My Tutor, My Love', 'https://phimimg.com/upload/vod/20260624-1/6e87f321ab981ee0c3ecd25cb4fcc76d.jpg', 'https://phimimg.com/upload/vod/20260624-1/343a4926192b76407591f65c006d823b.jpg', '<p>Bộ phim&nbsp;là hành trình tình yêu giữa một gia sư điển trai và một nữ minh tinh nổi tiếng. Vì muốn hòa nhập với gia đình thượng lưu của bạn trai cũng như để chuẩn bị cho vai diễn nói tiếng Anh sắp tới, nữ diễn viên Eva quyết định theo học tiếng Anh với chàng gia sư Pun. Sau một thời gian tiếp xúc, giữa họ bắt đầu nảy sinh tình cảm. Khi tính mạng của Eva bị đe dọa, Pun phải kiêm luôn vai trò vệ sĩ để bảo vệ cô. Tình yêu của họ liệu có thể vượt qua những sóng gió đang chờ phía trước?</p>', 'Tập 6', 14, 'series', 'ongoing', 93, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Mookda Narinrak","avatar":""},{"name":"Sanpetch Kunakorn","avatar":""},{"name":"Louis Scott","avatar":""},{"name":"Chonlathorn Kongyingyong﻿","avatar":""},{"name":"Yanin Opassathaworn","avatar":""},{"name":"Teerapong Liaorakwong","avatar":""},{"name":"Suttatip Wutchaipradit","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["我的家教恋人","家有爱师","ติวเธอร์ที่รัก","Tiu Thoe(r)...Thi Rak","My Tutor My Love","ติวเธอ(ร์)...ที่รัก"]', 1784690324117);
