INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-de-nghi-cua-cong-to-vien', 'Lời Đề Nghị Của Công Tố Viên', 'The Prosecutor''s Proposal', 'https://phimimg.com/upload/vod/20260627-1/00bad3e184efb751806ae1f5562ace36.jpg', 'https://phimimg.com/upload/vod/20260627-1/4840456fa6f40d96ff25e2b01dc85da9.jpg', '<p>Mười lăm năm trước, một vụ giết người tàn bạo đã kéo hai cậu bé vào địa ngục. Một người trở thành con trai của nạn nhân; người kia, lại là con của kẻ sát nhân. Nhiều năm sau, định mệnh đã đưa họ tái ngộ trong vai trò một công tố viên và một điều tra viên. Trong khi chiến đấu chống lại mạng lưới tham nhũng pháp lý và doanh nghiệp khổng lồ, họ phát hiện ra một điều còn nguy hiểm hơn thế: chính là đối phương. Họ là điểm yếu chí mạng — và cũng là sự cứu rỗi duy nhất của nhau.</p>', 'Tập 6', 10, 'series', 'ongoing', 150, 2026, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Si-woo","avatar":""},{"name":"Yoon Do-gun","avatar":""},{"name":"Kim Jung-tae","avatar":""},{"name":"Cho Min-gyu","avatar":""},{"name":"Seo Han-gyeol","avatar":""},{"name":"Kim Nak-kyun","avatar":""},{"name":"Lee Ga-kyung","avatar":""},{"name":"Seol Jun-su","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["检察官室的提案","检察官办公室的提议","檢察官辦公室的提議","檢察官的提案","The Prosecutor''s Office''s Proposal","A Proposal in the Prosecutors Office","검사실의 제안"]', 1784690324117);
