INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('loi-de-nghi-cua-cong-to-vien', 'Lời Đề Nghị Của Công Tố Viên', 'The Prosecutor''s Proposal', 'lời đề nghị của công tố viên the prosecutor''s proposal park si-woo yoon do-gun kim jung-tae cho min-gyu seo han-gyeol kim nak-kyun lee ga-kyung seol jun-su 检察官室的提案 检察官办公室的提议 檢察官辦公室的提議 檢察官的提案 the prosecutor''s office''s proposal a proposal in the prosecutors office 검사실의 제안', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-bi-lu-mo-den-ap-dao', 'Từ Bị Lu Mờ Đến Áp Đảo', 'From Overshadowed To Overpowered: Second Reincarnation Of A Talentless Sage', 'https://phimimg.com/upload/vod/20260627-1/abd77cee9d652ac7687193990c84d18b.jpg', 'https://phimimg.com/upload/vod/20260627-1/9666857e1a0a2ed9de5fc5bb07691193.jpg', '<p>Đại hiền triết Ephtal qua đời trong nỗi tuyệt vọng cay đắng sau khi thất bại trong việc chạm đến đỉnh cao của ma pháp — thế nhưng 400 năm sau, ông đã tái sinh với toàn bộ ký ức và sức mạnh được giữ nguyên vẹn! Giữa một thế giới nơi ma pháp đã suy tàn và những câu thần chú cổ xưa bị coi là phép màu hiếm có, Ephtal thẳng tiến vào một học viện ma pháp danh giá để khôi phục lại nghệ thuật thuật phù thủy chân chính. Khi sức mạnh của ông làm rung chuyển cả thế giới, những huyền thoại từ lâu đã bị lãng quên cũng bắt đầu thức tỉnh!</p>', 'Tập 3', 12, 'hoathinh', 'ongoing', 68, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shuichiro Umeda","avatar":""},{"name":"Reo Osanai","avatar":""},{"name":"Haruka Shiraishi","avatar":""},{"name":"Emiri Kato","avatar":""},{"name":"Daisuke Hirakawa","avatar":""},{"name":"Kentaro Ito","avatar":""},{"name":"Naomi Kusumi","avatar":""},{"name":"Masaya Fukunishi","avatar":""},{"name":"Tsuyoshi Koyama","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["落第贤者的学院无双～第二次转生的S级开外挂魔术师冒险录～","落第贤者的学院无双～第二回转生，S等级作弊魔术师冒险记～","Rakudai Kenja no Gakuin Musō: Nido Tensei Shita Saikyō Kenja","Rakudai Kenja no Gakuin Musou ~Nidome no Tensei, S-Rank Cheat Majutsushi Boukenroku~","Rakudai Kenja no Gakuin Musou","Rakudai Kenja no Gakuin Musou Nidome no Tensei S-Rank Cheat Majutsushi Boukenroku","From Overshadowed to Overpowered: Second Reincarnation of a Talentless Sage","The Failed Sage''s Academy Domination","落第賢者の学院無双 ～二度目の転生、Ｓランクチート魔術師冒険録～"]', 1784690324117);
