INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-mua-lan-su-rong', 'Điệu Múa Lân Sư Rồng', 'Dance Of The Lion', 'https://phimimg.com/upload/vod/20260524-1/81ce77b655ecaa3c56d135a7cfb67066.jpg', 'https://phimimg.com/upload/vod/20260524-1/4b4c3823a4274321a54f96d4ff2840c7.jpg', '<p>Sau tai nạn của cha, một cô gái trẻ vùng Isan tiếp quản đoàn múa lân gia đình và kết hợp với nhạc Mor Lam truyền thống để duy trì hoạt động của đoàn.</p>', 'Tập 25', 28, 'series', 'ongoing', 66, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Thithinan Sanla","avatar":""},{"name":"Sattaphong Phiangphor","avatar":""},{"name":"Yuki Penphaka","avatar":""},{"name":"Thanadon Siriwaew","avatar":""},{"name":"Lamyong Nonghinhow","avatar":""},{"name":"Somjit Jongjohor","avatar":""},{"name":"Tree Chainarong","avatar":""},{"name":"Puri Hiranprueck","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Singto Lam Sing","Lion Lam Sing","สิงโตลำซิ่ง"]', 1784690324117);
