INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-nhiem-tham-tu-wan-phan-2', 'Đặc Nhiệm Thám Tử Wan! (Phần 2)', 'Bungo Stray Dogs WAN! (Season 2)', 'https://phimimg.com/upload/vod/20260704-1/4330df27a090ee2e1646b6992baafb0a.jpg', 'https://phimimg.com/upload/vod/20260704-1/6eb74d23a4ec3b98fb035361a4daa840.jpg', '<p>Những ngày tháng bình yên của tác phẩm ăn khách đình đám Bungou Stray Dogs đã đến. Các nhân vật thuộc Cơ quan Thám tử Vũ trang và băng đảng Mafia Cảng giờ đây bỗng xuất hiện dưới hình dáng tí hon Chibi?! Với việc Atsushi và những người bạn trở nên vô cùng dễ thương, đây sẽ là một trải nghiệm hoàn toàn khác biệt so với nguyên tác — một bộ truyện tranh hài hước đầy dễ chịu và thư giãn!</p>', 'Tập 2', 12, 'hoathinh', 'ongoing', 45, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bungo Stray Dogs Wan","Bungou Stray Dogs Wan!","文豪ストレイドッグス わん!"]', 1784690324117);
