INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-dream-yumemita', 'BanG Dream! YUME∞MITA', 'BanG Dream! YUME∞MITA', 'https://phimimg.com/upload/vod/20260704-1/29a589ed48f54ae69bc0e4f64aa5e4c7.jpg', 'https://phimimg.com/upload/vod/20260704-1/9983df3cc4dc24d7c3e450aa10f13f62.jpg', '<p>Bất ngờ được tập hợp lại với nhau, một nhóm thiếu nữ giờ đây chuẩn bị ra mắt với tư cách là ban nhạc ảo mang tên Mugendai Mewtype. Họ sở hữu cả tài năng lẫn cá tính riêng biệt, nhưng lại hoàn toàn không có chút khái niệm nào về việc phải biểu diễn như một thể thống nhất. Liệu họ có thể sống sót, chứ chưa nói đến việc vươn lên đỉnh cao trong thế giới âm nhạc đầy khắc nghiệt này?</p>', 'Tập 4', 13, 'hoathinh', 'ongoing', 36, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Arale Nakamachi","avatar":""},{"name":"Nonoka Miyanaga","avatar":""},{"name":"Ritsu Minetsuki","avatar":""},{"name":"Miyako Fuji","avatar":""},{"name":"Yuno Sengoku","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["BanG Dream! YUME∞MITA","BanG Dream! Yume Mita","BanG Dream YumeMita","バンドリ！ ゆめ∞みた"]', 1784690324117);
