INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-dao-hoang', 'Bác Sĩ Đảo Hoang', 'Doctor on the Edge', 'https://phimimg.com/upload/vod/20260603-1/658491161287e882fe760f8e8716d503.jpg', 'https://phimimg.com/upload/vod/20260603-1/2e03fed51702bd8387cc01b428e2a96b.jpg', '<p>Một bác sĩ y tế công cộng trên một hòn đảo bị xa lánh và một nữ y tá bí ẩn bắt đầu một mối tình lãng mạn giữa con người và y khoa.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 149, 2026, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Jae-wook","avatar":""},{"name":"Shin Ye-eun","avatar":""},{"name":"Hong Min-gi","avatar":""},{"name":"Lee Soo-kyung","avatar":""},{"name":"Kim Yoon-woo","avatar":""},{"name":"Kil Hae-yeon","avatar":""},{"name":"Lee Yoon-mi","avatar":""},{"name":"Jung Ae-yeun","avatar":""},{"name":"Joo In-young","avatar":""},{"name":"박준서","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["死撑医生","死守医生","존버닥터","Dakteo Seomboi","طبيب على حافة الهاوية","Jonber Doctor","Endurance Doctor","Doctor Jonbeo","Doctor Seomboy","The Last-Stand Doctor","The Persevering Doctor","닥터 섬보이"]', 1784690324117);
