INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bac-si-dao-hoang', 'Bác Sĩ Đảo Hoang', 'Doctor on the Edge', 'bác sĩ đảo hoang doctor on the edge lee jae-wook shin ye-eun hong min-gi lee soo-kyung kim yoon-woo kil hae-yeon lee yoon-mi jung ae-yeun joo in-young 박준서 死撑医生 死守医生 존버닥터 dakteo seomboi طبيب على حافة الهاوية jonber doctor endurance doctor doctor jonbeo doctor seomboy the last-stand doctor the persevering doctor 닥터 섬보이', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-qua-toi-gan', 'Đêm Qua Tới Gần', 'Inseparable', 'https://phimimg.com/upload/vod/20260625-1/3b5b161d27f29f270ddfe676e11993c5.jpg', 'https://phimimg.com/upload/vod/20260625-1/dc823fbb4d00527e0006c84cd1a5c28b.jpg', '<p>Chủ tiệm mì Hàn Đông và vợ Lâm Mỹ Nguyệt tưởng chừng sống một cuộc đời yên bình nhưng đằng sau đó là quá khứ đầy sóng gió. Lâm Mỹ Nguyệt từng là &quot;Lý Vinh Trân&quot; ở hộp đêm, nay cô bị bạn cũ là chị Linh đe dọa và phơi bày thân phận. Cùng lúc đó, bí mật được Hàn Đông giấu trốn suốt 20 năm cũng bị một người bí ẩn đe dọa trả thù mà tiết lộ. Hàn Đông bị bạn cũ Tôn Hải Đào đe dọa khiến hai vợ chồng bị mắc vào một lưới đen vô hình. Năm xưa, chính sự hèn nhát của Hàn Đông đã đẩy bạn học cấp ba Triệu Hiểu Kỳ vào thời khắc tăm tối nhất cuộc đời còn Lâm Mỹ Nguyệt bắt tay với chị em cũ A Muội cũng kéo theo một bí mật chấn động về quá khứ nhơ nhớp, mũi nhọn cuối cùng hướng thẳng vào nhà họ Tôn quyền thế. Đối mặt với nhà họ Tôn có thể một tay che trời, hai vợ chồng từ thế bị động phòng thủ dần chuyển sang phản công trong, cùng nhau bảo vệ gia đình. Cuối cùng, tội ác của nhà họ Tôn sụp đổ. Sau khi mọi chuyện lắng xuống, Hàn Đông và Lâm Mỹ Nguyệt vì những bất đắc dĩ trong quá khứ cùng những hành động vượt giới hạn trong quá trình phản kháng mà phải vào tù thụ án.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 100, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đồng Đại Vĩ","avatar":""},{"name":"Vương Giai Giai","avatar":""},{"name":"Mã Tô","avatar":""},{"name":"Giang Sơ Ảnh","avatar":""},{"name":"Nhậm Trọng","avatar":""},{"name":"Trương Bách Kiều","avatar":""},{"name":"Cát Hâm Di","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yi Wang De Shi Guang","遗忘的时光","昨夜将至"]', 1784690324117);
