INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tram-than-pham-tran-than-vuc-phan-2', 'Trảm Thần: Phàm Trần Thần Vực (Phần 2)', 'Slay The Gods (Season 2)', 'https://phimimg.com/upload/vod/20260627-1/4c213d3213bfbfff8254a2bace26b730.jpg', 'https://phimimg.com/upload/vod/20260627-1/84241482e7ba7ceb6139e4c6df6c5163.jpg', '<p>&quot;Như ảm đêm cuối cùng lâm, ta tất đứng ở vạn vạn người trước, hoành đao hướng uyên, máu nhuộm thiên khung!&quot; Ngươi là có hay không nghĩ tới, tại nghê hồng óng ánh đô thị phía dưới, ẩn giấu đến từ xưa lão thần lời nói quái vật? Ngươi là có hay không nghĩ tới, tại kia treo cao tại thế đầu người đỉnh trên mặt trăng, đứng lặng lấy canh gác nhân gian thần minh? Ngươi là có hay không nghĩ tới, tại biển người mãnh liệt hiện đại trong thành thị, tồn tại thay thế thần minh hành tẩu nhân gian siêu phàm người?</p>', 'Tập 5', 15, 'hoathinh', 'ongoing', 72, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Mã Chính Dương","avatar":""},{"name":"Viên Minh Triết","avatar":""},{"name":"Tam Thạch","avatar":""},{"name":"Hồ Lương Vĩ","avatar":""},{"name":"Tôn Hy Hạc","avatar":""},{"name":"Tôn Duệ Dương","avatar":""},{"name":"Lưu Thiên Hàm","avatar":""},{"name":"Đoàn Nghệ Tuyền","avatar":""},{"name":"Hạ Mịch Trần","avatar":""},{"name":"Dư Hạo Uy","avatar":""},{"name":"Gia Minh","avatar":""},{"name":"Ngâm Lương Khuyển","avatar":""},{"name":"Văn Sâm","avatar":""},{"name":"Đường Sách","avatar":""},{"name":"Bảo Mộc Trung Dương","avatar":""},{"name":"Trần Trương Thái Khang","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["我在精神病院学斩神","斩神","斩神动画","Z