INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tram-than-pham-tran-than-vuc-phan-2', 'Trảm Thần: Phàm Trần Thần Vực (Phần 2)', 'Slay The Gods (Season 2)', 'trảm thần: phàm trần thần vực (phần 2) slay the gods (season 2) mã chính dương viên minh triết tam thạch hồ lương vĩ tôn hy hạc tôn duệ dương lưu thiên hàm đoàn nghệ tuyền hạ mịch trần dư hạo uy gia minh ngâm lương khuyển văn sâm đường sách bảo mộc trung dương trần trương thái khang 我在精神病院学斩神 斩神 斩神动画 zhan shen: fanchen shen yu zhan shen wo zai jingshenbing yuan xue zhan shen zhan shen zhanshenzhifanchenshenyu zhan shen zhi fan chen shen yu slay the gods 斩神之凡尘神域 zhanshen i was learning to kill gods in a mental hospital i learn to kill gods in an asylum trảm thần: phàm trần thần vực trảm thần phàm trần thần vực phàm trần thần vực', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuong-da-3d', 'Tương Dạ 3D', 'Ever Night', 'https://phimimg.com/upload/vod/20260423-1/950380cf1fa0a107247fefbd2b2e2346.jpg', 'https://phimimg.com/upload/vod/20260423-1/1f987788a47a6b0e4ade3cff648b996a.jpg', '<p>Tương Dạ, hẳn không còn ít ai cảm thấy xa lạ với câu chuyện xuyên không của anh chàng Ninh Khuyết nữa, nay được dựng lên thành một bộ hoạt hình 3D đầy sống động và trang hoàng. Thời kỳ tuy là Đại Đường của Trung Quốc nhưng đây lại chính là nơi để mọi người thể hiện sức mạnh tu luyện của mình. Ninh Khuyết bị kéo vào cuộc du hành thời gian đến đây và rất thiếu may mắn cho anh chàng khi mà anh chẳng có tí sức mạnh nào cả, mọi thứ bị kéo xuống cùng cực của tuyệt vọng và bắt buộc anh phải tự tồn tại bằng chính bản năng của mình giữa muôn trùng hiểm nguy lũ lượt kéo đến.</p>', 'Tập 13', 19, 'hoathinh', 'ongoing', 52, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Jiang Ye","Jiangye","Ever Night","Ever Night (2026)","将夜"]', 1784690324117);
