INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-nhan-phan-2', 'Tiêu Nhân (Phần 2)', 'Blades Of The Guardians (Season 2)', 'https://phimimg.com/upload/vod/20260613-1/8c0436d9e1adaddeac035caf2d040148.jpg', 'https://phimimg.com/upload/vod/20260613-1/6f4181a4babd4d769a24fc35922162e6.jpg', '<p>Năm Đại Nghiệp thứ ba, biên cương rục rịch bất ổn, Tùy Dương Đế cho tuần tra phương Bắc, uy hiếp biên thùy phía Tây. Tiêu nhân Đao Mã được bằng hữu cũ nhờ hộ tống thủ lĩnh loạn đảng là Tri Thế Lang đến Trường An, hoàn thành lý tưởng cứu giúp loạn thế. Nhưng sau lưng hắn luôn có một kẻ độc nhãn ôm theo mối thù bám riết không buông, cả quá khứ đã qua lẫn hiểm nguy hiện tại cùng ập đến, hãy xem Đao Mã đã khuấy đảo máu tanh giang hồ dưới thời loạn thế như thế nào! Phát Chia sẻ</p>', 'Tập 6', 15, 'hoathinh', 'ongoing', 53, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Liu Beichen","avatar":""},{"name":"Wan Qian","avatar":""},{"name":"Zhao Qianjing","avatar":""},{"name":"Wang Xiaobing","avatar":""},{"name":"Yan Ning","avatar":""},{"name":"Huang Xiangyu","avatar":""},{"name":"Li Chanfei","avatar":""},{"name":"Sanshi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Biaoren","Biao Ren","镖人第二季","Blades of the Guardians","鏢人","镖人"]', 1784690324117);
