INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('van-tu-hanh', 'Vân Tú Hành', 'The Legend Of Rosy Clouds', 'vân tú hành the legend of rosy clouds lý nhất đồng tăng thuấn hy đặng vi đại lộ oa vương dĩ luân trình hoành hâm điền gia thụy giản vũ hy phạm tịnh văn đặng hiếu từ doãn chú thắng bào đại chí 云起时 彩云国物语 彩云国 the legend of rosy clouds take me where the clouds rise 云秀行', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toan-chuc-phap-su-phan-7', 'Toàn Chức Pháp Sư (Phần 7)', 'Full-Time Magister (Season 7)', 'https://phimimg.com/upload/vod/20260519-1/dee7ca0537499751b0b5382d0bce65ed.jpg', 'https://phimimg.com/upload/vod/20260519-1/d7584901fa2edcff0bf19aa372bbec40.jpg', '<p>Sau khi sự kiện Hỏa Diễm Ma Nữ kết thúc, Mạc Phàm quay trở lại với việc tu luyện tại học phủ Ma Đô. Tuy nhiên, ngay vào thời khắc quan trọng nhất, tin dữ bất ngờ ập đến. Người anh em tốt của cậu là Trương Tiểu Hầu đã mất tích. Là một người trọng tình trọng nghĩa, Mạc Phàm ngay lập tức dừng lịch trình thi đấu, cùng với cô bạn huyết tộc Ma Đô là Liễu Nhàn cấp tốc lên đường đến Cổ Đô. Tại đây, họ đã dấn thân vào khu vực trung tâm nguy hiểm – nơi các loài yêu ma đang trong thời kỳ hoạt động mạnh mẽ nhất.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 50, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Feng Junhua","avatar":""},{"name":"Niang Gui","avatar":""},{"name":"Li Yuantao","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Quan Zhi Fa Shi","全职法师特别篇之神秘委托","The Almighty Wizard","全职法师","The Almighty Wizard SP:A Mysterious Commission","Quanzhi Fashi","Almighty Mage","전직 법사","Маг на полную ставку","Штатный волшебник","Full-Time Magister","Versatile Mage"]', 1784690324117);
