INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-anh-hung-thanh-nu-khong-toi-chi-la-mot-hau-gai-dam-dang-va-tu-hao-ve-dieu-do', 'Nữ Anh Hùng? Thánh Nữ? Không, Tôi Chỉ Là Một Hầu Gái Đảm Đang (Và Tự Hào Về Điều Đó)!', 'Heroine? Saint? No, I''m an All-Works Maid (and Proud of It)!', 'https://phimimg.com/upload/vod/20260624-1/7ff159a01fa1e15897bb6280436b6ce8.jpg', 'https://phimimg.com/upload/vod/20260624-1/7522d87508d184b3d5ecf8e292b5b41a.jpg', '<p>Melody có thể là vị nữ anh hùng và thánh nữ mang thiên mệnh giải cứu thế giới khỏi sự trỗi dậy của ma vương — thế nhưng ước muốn duy nhất của cô lại là trở thành một hầu gái hoàn hảo! Sau khi chuyển sinh vào một trò chơi điện tử cốt truyện, Melody đã rẽ hướng khỏi lộ trình định sẵn, thẳng thừng từ chối lời kêu gọi dấn thân vào cuộc chiến, thay vào đó cô lại dùng chính sức mạnh thần thánh của mình để... dọn dẹp nhà cửa. Quyết định này khiến thế giới mới của cô ngày càng trở nên hỗn loạn, còn cốt truyện gốc thì sao? Hoàn toàn đảo lộn và không cách nào lường trước được.</p>', 'Tập 3', 12, 'hoathinh', 'ongoing', 51, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Heroine? Seijo? Iie, All Works Maid desu (Ko)!","Heroine? Seijo? Iie, All Works Maid desu (Hokori)!","ヒロイン？聖女？いいえ、オールワークスメイドです（誇）！","Heroine Seijo Iie All Works Maid desu Ko","히로인？ 성녀？ 아니요, 올 워크스 메이드입니다(자랑)!"]', 1784690324117);
