INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nu-anh-hung-thanh-nu-khong-toi-chi-la-mot-hau-gai-dam-dang-va-tu-hao-ve-dieu-do', 'Nữ Anh Hùng? Thánh Nữ? Không, Tôi Chỉ Là Một Hầu Gái Đảm Đang (Và Tự Hào Về Điều Đó)!', 'Heroine? Saint? No, I''m an All-Works Maid (and Proud of It)!', 'nữ anh hùng? thánh nữ? không, tôi chỉ là một hầu gái đảm đang (và tự hào về điều đó)! heroine? saint? no, i''m an all-works maid (and proud of it)!  heroine? seijo? iie, all works maid desu (ko)! heroine? seijo? iie, all works maid desu (hokori)! ヒロイン？聖女？いいえ、オールワークスメイドです（誇）！ heroine seijo iie all works maid desu ko 히로인？ 성녀？ 아니요, 올 워크스 메이드입니다(자랑)!', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-mang-cap-999-tu-lang-que-dan-lang-cap-999', 'Kẻ Mang Cấp 999 Từ Làng Quê (Dân Làng Cấp 999)', 'The Villager Of Level 999', 'https://phimimg.com/upload/vod/20260702-1/371a851fe264aba5ba792e50dbc7e8bd.jpg', 'https://phimimg.com/upload/vod/20260702-1/d6636feba0735a0b093f8c0cae118f01.jpg', '<p>Tại thế giới Earthclear, mọi người đều sinh ra với một vai trò cố định, và &quot;dân làng&quot; là những kẻ yếu ớt nhất trong số đó. Hầu hết họ không bao giờ có thể vượt qua Cấp độ 5 — ngoại trừ Koji Kagami, một dân làng sở hữu Cấp độ lên tới... 999?! Trong một cuộc săn lùng quái vật, anh tình cờ gặp gỡ Alice, con gái của Ma Vương, và phát hiện ra rằng cả hai cùng chia sẻ một giấc mơ tưởng chừng như không tưởng: sự chung sống hòa bình giữa loài người và ma tộc. Giữa một thế giới vốn được định sẵn cho những xung đột tàn khốc, họ đã cùng nhau lao vào trận chiến để thách thức số phận và đập tan những quy luật bất công.</p>', 'Tập 3', 12, 'hoathinh', 'ongoing', 59, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Satoshi Inomata","avatar":""},{"name":"Nao Toyama","avatar":""},{"name":"Hiroya Egashira","avatar":""},{"name":"Manaka Iwami","avatar":""},{"name":"Nobunaga Shimazaki","avatar":""},{"name":"Aoi Koga","avatar":""},{"name":"Lynn","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Lv999 no Murabito","The Villager of Level 999","The Level 999 Villager","Dân Làng Cấp 999","LV999の村人"]', 1784690324117);
