INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-gai-nguoi-may', 'Bạn Gái Người Máy', 'AI Girl', 'https://phimimg.com/upload/vod/20260702-1/88140f84f7bde451cb436d2693f74efb.jpg', 'https://phimimg.com/upload/vod/20260702-1/9ddc66c01bd307e5fd64162459ea38d5.jpg', '<p>Cuộc sống yên bình của Jen bị đảo lộn khi Ai, một robot bí ẩn có ngoại hình giống hệt cô gái trong mộng của cô, xuất hiện và gọi cô là &quot;Chủ nhân&quot;. Bị buộc phải sống chung, Jen không ngờ rằng mình lại đem lòng yêu cỗ máy tinh nghịch này. Khi mối liên kết giữa họ ngày càng sâu đậm, cô phải đối mặt với câu hỏi cuối cùng: Ai chỉ là một chương trình lỗi lạc, hay chính là tình yêu của đời cô?</p>', 'Tập 2', 10, 'series', 'ongoing', 63, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Chanya Amarit Duval","avatar":""},{"name":"Khawisara Singplod","avatar":""},{"name":"Thitipong Sangngey","avatar":""},{"name":"Nattharinphon Phrommin","avatar":""},{"name":"Namthip Siamthong","avatar":""},{"name":"Satida Pinsinchai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["机器人女友","机器人女友 AI Girl","AI Girl","จะ Gen จนกว่าจะเจอ"]', 1784690324117);
