INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-dong-muifei-muoi-phi', 'Bà Đồng Muifei (Muội Phi)', 'Mui Fei (Muifei The Medium)', 'https://phimimg.com/upload/vod/20260618-1/4daf691fdbcabbedc0890a863677c9ad.jpg', 'https://phimimg.com/upload/vod/20260618-1/1c5c2f1516d809ce698ddac881b72bde.jpg', '<p>Bà Đồng Muifei là một cô gái trẻ sống trong một ngôi làng ở vùng núi, mang trên vai trách nhiệm gánh chịu những điều bất hạnh và đau khổ thay cho cộng đồng. Cuộc đời Muifei bắt đầu rẽ sang bước ngoặt bi kịch khi cô đem lòng yêu chàng trai thành phố Phum và rời bỏ quê nhà để đi theo tiếng gọi của con tim. Tuy nhiên, hy vọng về một cuộc sống tốt đẹp hơn nhanh chóng tan biến khi cô phải đối mặt với vô vàn khó khăn, sự bóc lột và những hành vi ngược đãi tàn nhẫn. Bị nhấn chìm trong đau đớn tột cùng, Muifei trở lại dưới hình dạng một linh hồn báo oán, quyết tâm đòi lại công lý.</p>', 'Tập 8', 20, 'series', 'ongoing', 127, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Chayanit Chansangavej","avatar":""},{"name":"Kantapon Jindataweephol","avatar":""},{"name":"Paythai Ploymeeka","avatar":""},{"name":"Phichet Priabyodying","avatar":""},{"name":"Thana Chatborirak","avatar":""},{"name":"Sahatchai Chumrum","avatar":""},{"name":"Arisara Wongchalee","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Mui Fei","Muifei the Medium","มุ่ยเฟย"]', 1784690324117);
