INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ranh-gioi', 'Ranh Giới', 'Border 2', 'https://phimimg.com/upload/vod/20260326-1/f6d07acf2e80ede21ed8fc68ecd37fcc.jpg', 'https://phimimg.com/uploads/movies/20260708/ranh-gioi-poster.webp', '<p>Ba người lính lý tưởng trong quân đội, hải quân và không quân Ấn Độ phải đối mặt với điều kiện chiến đấu khắc nghiệt trong bộ phim lấy bối cảnh cuộc chiến tranh Ấn Độ - Pakistan năm 1971.</p>', 'Full', 1, 'single', 'completed', 123, 2026, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Sunny Deol","avatar":""},{"name":"Varun Dhawan","avatar":""},{"name":"Diljit Dosanjh","avatar":""},{"name":"Ahan Shetty","avatar":""},{"name":"Mona Singh","avatar":""},{"name":"Sonam Bajwa","avatar":""},{"name":"Anya Singh","avatar":""},{"name":"Medha Rana","avatar":""},{"name":"Paramvir Singh Cheema","avatar":""},{"name":"Guneet Sandhu","avatar":""},{"name":"Abhinav Ranga","avatar":""},{"name":"Vansh Bhardwaj","avatar":""},{"name":"Bhushan Vikas","avatar":""},{"name":"Ali Mughal","avatar":""},{"name":"Imran Farooqui","avatar":""},{"name":"Ishika Gagneja","avatar":""},{"name":"Suniel Shetty","avatar":""},{"name":"Akshaye","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["边境战争2","बॉर्डर २"]', 1784690324117);
