INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kill-it-slay-toi-ben', 'Kill It: Slay Tới Bến', 'Kill It: Style Creator War', 'https://phimimg.com/upload/vod/20260527-1/84ccf8719dca6861665a4b71ce848501.jpg', 'https://phimimg.com/upload/vod/20260527-1/da7cd233799fe9902368a808b5d78c4b.jpg', '<p>Cuộc chiến thời trang sống còn giữa những nhà sáng tạo dẫn đầu xu hướng của Hàn Quốc đã bắt đầu. Phong cách nào sẽ lên ngôi? Bộ cánh nào mới là slay nhất? Hãy tận mắt chiêm ngưỡng những &quot;dân chơi thời thượng&quot; bùng cháy trên sàn diễn.</p>', 'Tập 9', 12, 'tvshows', 'ongoing', 81, 2026, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jang Yoon-ju","avatar":""},{"name":"Lee Jong-won","avatar":""},{"name":"Yeonjun","avatar":""},{"name":"Cha Jung-won","avatar":""},{"name":"Ahn Ah-reum","avatar":""},{"name":"양갱","avatar":""},{"name":"Chung Lea","avatar":""},{"name":"Kelly Kim","avatar":""},{"name":"Miu","avatar":""},{"name":"Choi Mina Sue","avatar":""},{"name":"Lee Yeon-hwa","avatar":""},{"name":"Kitadera Uwa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Kill It: Style Creator Battle","Kill It","Kill It: Style Creator Showdown","킬잇: 스타일 크리에이터 대전쟁"]', 1784690324117);
