INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vi-thanh-vo-tu-khong-the-kiem-che-suc-manh', 'Vị Thánh Vô Tư Không Thể Kiềm Chế Sức Mạnh', 'The Oblivious Saint Can''t Contain Her Power', 'https://phimimg.com/upload/vod/20260701-1/7fc61795974d18ee3472d7a877487832.jpg', 'https://phimimg.com/upload/vod/20260701-1/3d205d488b2232aebb3498457c5bd610.jpg', '<p>Bị lu mờ bởi người em gái hoàn hảo như thánh nữ Flora, cô gái giản dị Carolina đã nắm lấy cơ hội để chứng tỏ giá trị của mình bằng cách đồng ý tham gia một cuộc hôn nhân chính trị với một vị hoàng tử bị đồn đại là vô cùng tàn bạo. Thế nhưng, vị hoàng tử đó lại hoàn toàn khác xa với những gì cô tưởng tượng — anh là một quý ông đích thực, và lần đầu tiên trong đời, Carolina cảm thấy bản thân mình được trân trọng. Khi Carolina bắt đầu tỏa sáng, cô không chỉ tìm thấy giá trị của bản thân cùng một sức mạnh bí ẩn, mà cùng lúc đó, cuộc sống vốn dĩ hoàn hảo của Flora ở quê nhà cũng bắt đầu rạn nứt và sụp đổ.</p>', 'Tập 2', 14, 'hoathinh', 'ongoing', 56, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Rie Takahashi","avatar":""},{"name":"Makoto Furukawa","avatar":""},{"name":"Haruka Shiraishi","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Mujikaku Seijo wa Kyou mo Muishiki ni Chikara wo Tare Nagasu","The Oblivious Saint Can''t Contain Her Power: Forget My Sister! Turns Out I Was the Real Saint All Along!","無自覚聖女は今日も無意識に力を垂れ流す"]', 1784690324117);
