INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phia-ben-kia-thanh-pho', 'Phía Bên Kia Thành Phố', 'The Other Side Of The City', 'https://phimimg.com/upload/vod/20260603-1/b5e7f3373b9a442f09b65c2234db86cd.jpg', 'https://phimimg.com/upload/vod/20260603-1/7fd55181a699c9473ea154a9cd45b33c.jpg', '<p>Phim lấy bối cảnh một khu phố lao động ven đô, xoay quanh đôi bạn thân trái tính trái nết là Cương và Khuê. Cả hai cùng trải qua những biến động tâm lý tuổi học đường, áp lực thành tích và rạn nứt tình cảm khi một cô bạn mới xuất hiện, khơi lại những bí mật quá khứ của gia đình họ.</p>', 'Tập 26', 35, 'series', 'ongoing', 96, 2026, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Thái Vũ","avatar":""},{"name":"Võ Hoài Vũ","avatar":""},{"name":"Ali Thục Phương","avatar":""},{"name":"Huyền Sâm","avatar":""},{"name":"Minh Tiệp","avatar":""},{"name":"Khánh Linh","avatar":""},{"name":"Nguyễn Lê Như Thành","avatar":""},{"name":"Nguyên Châu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324117);
