INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nut-that', 'Nút Thắt', 'KNOT', 'https://phimimg.com/upload/vod/20260702-1/1b8bc37d5683e785764ff94ce8eef51a.jpg', 'https://phimimg.com/upload/vod/20260702-1/0bc8b35212cf621b9858b600f9981df8.jpg', '<p>Cuộc đời của một chàng trai trẻ đã thay đổi mãi mãi khi anh bị một Alpha quyền năng đánh dấu, buộc chặt định mệnh của cả hai vào một mối liên kết không thể nào trốn chạy.</p>', 'Tập 2', 12, 'series', 'ongoing', 62, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Pasakorn Sanrattana","avatar":""},{"name":"Yongyut Termtuo","avatar":""},{"name":"Phubeth Atarunwong","avatar":""},{"name":"Teerawat Tanacom","avatar":""},{"name":"Waranluck Phonpawiworakun","avatar":""},{"name":"Jakrin Sangruan","avatar":""},{"name":"James Uzumaki","avatar":""},{"name":"Thanakrid Suteepakornchai","avatar":""},{"name":"Chachana Thirakod","avatar":""},{"name":"Kantheephop Sirorattanaphanit","avatar":""},{"name":"Nanthipat Sirorattanaphanit","avatar":""},{"name":"Natheephat Nop","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Knot The Series","ซีรีส์"]', 1784690324117);
