INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ca-the-gioi-dang-nhay-mua', 'Cả Thế Giới Đang Nhảy Múa', 'The World Is Dancing', 'https://phimimg.com/upload/vod/20260702-1/9038bb3c768ce91b1cde47eda45c6fc8.jpg', 'https://phimimg.com/upload/vod/20260702-1/f8662440354f9db1059ba828e1e5ce8d.jpg', '<p>Vào năm 1374, giữa những biến động của cuộc xung đột kéo dài giữa Nam-Bắc Triều, một cậu bé tên Oniyasha được sinh ra trong một gia đình nghệ sĩ biểu diễn kịch Sarugaku. Cậu trải qua những ngày tháng trong một sự u buồn lặng lẽ, bị ám ảnh bởi một câu hỏi đơn giản nhưng dai dẳng: Tại sao con người ta lại nhảy múa? Thế rồi, một ngày nọ, cậu được tận mắt chứng kiến một điệu nhảy mà bản thân cảm nhận là &quot;đạt&quot; — và mọi thứ bắt đầu thay đổi. Đây là câu chuyện về một thiếu niên xinh đẹp, người mà một ngày nào đó sẽ định hình nên nghệ thuật kịch Noh và được người đời nhớ đến với cái tên Zeami.</p>', 'Tập 2', 12, 'series', 'ongoing', 40, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yumiri Hanamori","avatar":""},{"name":"Shimba Tsuchiya","avatar":""},{"name":"Maaya Uchida","avatar":""},{"name":"Romi Park","avatar":""},{"name":"Katsuyuki Konishi","avatar":""},{"name":"Haruki Ishiya","avatar":""},{"name":"Takahiro Sakurai","avatar":""},{"name":"Nobuo Tobita","avatar":""},{"name":"Mamiko Noto","avatar":""},{"name":"Inori Minase","avatar":""},{"name":"Hazuki Seto","avatar":""},{"name":"Yoji Matsuda","avatar":""},{"name":"Miyuki Sawashiro","avatar":""},{"name":"Kenichirou Matsuda","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["THE WORLD IS DANCING 世界在起舞","World Is Dancing","ワールド イズ ダンシング"]', 1784690324117);
