INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ca-the-gioi-dang-nhay-mua', 'Cả Thế Giới Đang Nhảy Múa', 'The World Is Dancing', 'cả thế giới đang nhảy múa the world is dancing yumiri hanamori shimba tsuchiya maaya uchida romi park katsuyuki konishi haruki ishiya takahiro sakurai nobuo tobita mamiko noto inori minase hazuki seto yoji matsuda miyuki sawashiro kenichirou matsuda the world is dancing 世界在起舞 world is dancing ワールド イズ ダンシング', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trang-trai-dutton', 'Trang Trại Dutton', 'Dutton Ranch', 'https://phimimg.com/upload/vod/20260604-1/40b25c7cee4e1c8455dc7acbfef9f8b4.jpg', 'https://phimimg.com/upload/vod/20260604-1/c714d7ad21f9fea3380edbfba93b72e8.jpg', '<p>Trang trại Dutton là series cao bồi, chính kịch, tập trung vào hành trình mới của cặp đôi biểu tượng được người hâm mộ vô cùng yêu thích trong vũ trụ nổi tiếng Yellowstone, Beth Dutton và Rip Wheeler. Tiếp nối ngay sau biến cố cuối cùng của gia tộc Dutton trong loạt phim gốc Yellowstone, Beth và Rip quyết định rời khỏi Montana để xây dựng tương lai mới tại Trang trại Dutton ở Texas cùng Carter, cậu bé họ xem như con trai của mình, nhưng vùng đất mới này vốn không hề dễ sống. Trang trại mới của họ nhanh chóng trở thành mục tiêu của bà trùm chăn nuôi địa phương, những tay tài phiệt muốn thâu tóm đất đai và cả giới chính trị. Rip phải quay lại cuộc sống đẫm máu quen thuộc để bảo vệ gia đình, còn Beth tiếp tục dùng trí thông minh, sự tàn nhẫn và bản lĩnh thép để chống lại mọi kẻ thù. Với dàn diễn viên hạng A, cùng với nhịp phim dồn dập, các pha hành động đậm chất Viễn Tây… đã tạo nên thương hiệu của đạo diễn tài năng Taylor Sheridan hứa hẹn dây là bộ phim không thể bỏ lỡ của các tín đồ điện ảnh.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 72, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kelly Reilly","avatar":""},{"name":"Cole Hauser","avatar":""},{"name":"Finn Little","avatar":""},{"name":"Juan Pablo Raba","avatar":""},{"name":"Jai Courtney","avatar":""},{"name":"J.R. Villarreal","avatar":""},{"name":"Marc Menchaca","avatar":""},{"name":"Natalie Alyn Lind","avatar":""},{"name":"Ed Harris","avatar":""},{"name":"Annette Bening","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '["Ferma Dutton","Beth & Rip","The Dutton Ranch","Dutton Ranch"]', 1784690324117);
