INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oan-gia-thanh-doi', 'Oan Gia Thành Đôi', 'Enemies With Benefits', 'https://phimimg.com/upload/vod/20260604-1/e769f9fdc95b050450fa90171a393d98.jpg', 'https://phimimg.com/upload/vod/20260604-1/5855383b097fbc952cdb1c054e5cf25f.jpg', '<p>Hai người luôn đối đầu ở nơi làm việc như “kẻ thù truyền kiếp”. Nhưng sau một đêm ngoài ý muốn, họ bắt đầu mối quan hệ kiểu “friends with benefits” — chỉ thân mật thể xác, không yêu đương. Để tránh đồng nghiệp phát hiện, cả hai vẫn giả vờ ghét nhau ở công ty. Tuy nhiên càng ở gần nhau, mối quan hệ dần chuyển thành tình cảm thật.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 69, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Ployshompoo Supasap","avatar":""},{"name":"Prariyapit Yu","avatar":""},{"name":"Ploynira Hiruntaveesin","avatar":""},{"name":"Rutricha Phapakithi","avatar":""},{"name":"Juthapich Indrajundra","avatar":""},{"name":"Phatchatorn Thanawat","avatar":""},{"name":"Chayakorn Jutamas","avatar":""},{"name":"Kittipat Chalaragse","avatar":""},{"name":"Niti Chaichitathorn","avatar":""},{"name":"Leo Saussay","avatar":""},{"name":"Rattanawadee Wongthong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["ลัลล์ไม่ชอบไวน์"]', 1784690324117);
