INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nua-co-hoi-song-chuyen-gia-tuoi-trung-nien', 'Nửa Cơ Hội Sống (Chuyên Gia Tuổi Trung Niên)', 'Fifties Professionals', 'https://phimimg.com/upload/vod/20260604-1/cb8fc4d0b70189dd03ab746d707f8ad2.jpg', 'https://phimimg.com/upload/vod/20260604-1/571a4ff47b891a2c50f131b328f59193.jpg', '<p>Bộ phim kể về ba người đàn ông trung niên từng có quá khứ lừng lẫy nhưng hiện đang sống một cuộc đời &quot;về hưu&quot; bình lặng. Mọi chuyện thay đổi khi một biến cố bất ngờ xảy ra, buộc bộ ba &quot;lão làng&quot; này phải tập hợp lại. Dù cơ thể không còn nhanh nhẹn như thời trai trẻ và thường xuyên gặp phải những tình huống &quot;dở khóc dở cười&quot; do khoảng cách thế hệ, họ vẫn chứng minh được rằng &quot;gừng càng già càng cay&quot; khi giải quyết các vấn đề theo cách riêng của mình.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 76, 2026, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Shin Ha-kyun","avatar":""},{"name":"Oh Jung-se","avatar":""},{"name":"Heo Sung-tae","avatar":""},{"name":"Kim Shin-rok","avatar":""},{"name":"Lee Hak-ju","avatar":""},{"name":"Han Ji-eun","avatar":""},{"name":"Kim Sang-kyung","avatar":""},{"name":"Kim Sang-ho","avatar":""},{"name":"Shin Dong-mi","avatar":""},{"name":"Kwon Yul","avatar":""},{"name":"Hyun Bong-sik","avatar":""},{"name":"Kim Byeong-ok","avatar":""},{"name":"Jeong Seok-yong","avatar":""},{"name":"Ahn Nae-sang","avatar":""},{"name":"Kim Ki-cheon","avatar":""},{"name":"Park Ji-hwan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["五十专家","Osippeuro","O-sip-peu-ro","محترفي الخمسينيات","Fifty Percent","50Pro","50 Pro","오십프로"]', 1784690324117);
