INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-he-nong-nhiet', 'Mùa Hè Nồng Nhiệt', 'Never-Ending Summer', 'https://phimimg.com/upload/vod/20260616-1/f9a3568b070e468019ee3bfde41b712e.jpg', 'https://phimimg.com/upload/vod/20260616-1/247abad1d18477f9983cbf3877e4f070.jpg', '<p>Bộ phim kể về câu chuyện cô gái Chu Vãn vì muốn cứu bà mà cố tình tiếp cận chàng trai Lục Tây Kiêu. Trong quá trình cứu rỗi lẫn nhau, cả hai dần nảy sinh tình cảm nhưng lại phải chia cắt vì hiện thực. Mười năm sau gặp lại, mối tình đầy rối ren đó được họ lấy danh nghĩa “trả thù” để lần nữa thắp lại ngọn lửa tình yêu.</p>', 'Hoàn Tất (29/29)', 29, 'series', 'completed', 112, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Bao Thượng Ân","avatar":""},{"name":"Châu Kha Vũ","avatar":""},{"name":"Triệu Anh Bác","avatar":""},{"name":"Kha Thuần","avatar":""},{"name":"Từ Viên Y Na","avatar":""},{"name":"Phó Vĩ Luân","avatar":""},{"name":"Lý Nguyên","avatar":""},{"name":"Vương Sách","avatar":""},{"name":"Phương Phương","avatar":""},{"name":"Viên Nhiễm","avatar":""},{"name":"Hoàng Đình Đình","avatar":""},{"name":"Dương Kỳ Nguyên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Xi Feng Xiang Wan","坠落","西风向晚","炽夏"]', 1784690324117);
