INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mua-he-nong-nhiet', 'Mùa Hè Nồng Nhiệt', 'Never-Ending Summer', 'mùa hè nồng nhiệt never-ending summer bao thượng ân châu kha vũ triệu anh bác kha thuần từ viên y na phó vĩ luân lý nguyên vương sách phương phương viên nhiễm hoàng đình đình dương kỳ nguyên xi feng xiang wan 坠落 西风向晚 炽夏', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-hoang-luc-2026', 'Thành Hoàng Lục', 'The Chronicles Of City God (CHENGHUANG)', 'https://phimimg.com/upload/vod/20260610-1/9a9b23f99dc5d6fe58df79ac48253370.jpg', 'https://phimimg.com/upload/vod/20260610-1/00bded8495748116463dc924dedc12d4.jpg', '<p>Tại hiện trường của hàng loạt vụ án con người hóa ác quỷ, camera đều ghi lại hình ảnh một hung thủ có khuôn mặt giống hệt nam chính. Nhận được lệnh truy nã từ Địa phủ, nữ chính lập tức bắt giữ nam chính để áp giải về quy án, chờ Hắc Bạch Vô Thường xét xử. Để rửa sạch oan khuất cho bản thân, nam chính bất đắc dĩ phải dùng kế ép nữ chính cùng mình điều tra chân tướng sự việc. Khi vụ án dần được làm sáng tỏ, cả hai lần lượt vén màn âm mưu đằng sau chuỗi vụ án con người hóa ác quỷ, đồng thời phát hiện mối liên hệ bí ẩn giữa hung thủ và nam chính. Thế nhưng, sự thật cuối cùng còn đáng sợ hơn họ tưởng tượng: hóa ra mọi chuyện từ đầu đến cuối đều nằm trong sự sắp đặt của kẻ chủ mưu đứng sau tất cả...</p>', 'Hoàn Tất (6/6)', 6, 'hoathinh', 'completed', 37, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Cheng Huang Lu","CHENGHUANG","城隍录"]', 1784690324117);
