INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mao', 'MAO', 'MAO', 'https://phimimg.com/upload/vod/20260407-1/e848f6fcf159dd1ba4b6865bbc46616b.jpg', 'https://phimimg.com/upload/vod/20260407-1/8bfc211dbf6e0ad5ae4c0c4be2109b47.jpg', '<p>Tám năm trước, Nanoka Kiba là người duy nhất sống sót thần kỳ sau một tai nạn thảm khốc tại trung tâm thương mại thị trấn Gogyo. Ở hiện tại, trên đường đi học về, cô bị thu hút bởi một lối đi bỏ hoang và bất ngờ bị dịch chuyển về thời đại Taisho của Nhật Bản. Tại đây, cô gặp gỡ Mao – một chàng trai bí ẩn cũng vừa đặt chân đến ngôi làng đầy ma quỷ cùng lúc với cô. Cùng nhau, họ bắt đầu điều tra những sự kiện kỳ quái xảy ra xung quanh. Nanoka dần chắp vá lại những ký ức vụn vỡ về vụ tai nạn năm xưa và nhận ra rằng, cô và Mao có thể đang cùng mang trong mình một vận mệnh chung đầy đen tối.</p>', 'Hoàn Tất (14/14)', 14, 'hoathinh', 'completed', 35, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuki Kaji","avatar":""},{"name":"Natsumi Kawaida","avatar":""},{"name":"Hiro Shimono","avatar":""},{"name":"Toshiyuki Toyonaga","avatar":""},{"name":"Momoka Terasawa","avatar":""},{"name":"Kazuyuki Okitsu","avatar":""},{"name":"Motoko Kumai","avatar":""},{"name":"Yoko Hikasa","avatar":""},{"name":"Risa Shimizu","avatar":""},{"name":"Reina Ueda","avatar":""},{"name":"Takashi Matsuyama","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["摩绪","マオ","MAO マオ","Mao","MAO(마오)","MAO 摩緒","MAO"]', 1784690324117);
