INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('one-piece-nu-hung', 'One Piece: Nữ Hùng', 'One Piece: Heroines', 'https://phimimg.com/upload/vod/20260706-1/08a7596632159d1134da64bb6c3925f9.jpg', 'https://phimimg.com/upload/vod/20260706-1/1730a63dedf5a516c07e33ef6d8b4e71.jpg', '<p>Anime ONE PIECE HEROINES sẽ thể hiện những nét quyến rũ của các nữ nhân vật trong One Piece mà bản chính chưa từng khai thác. &nbsp;Nguyên tác dựa trên series tiểu thuyết ONE PIECE novel HEROINES được đăng trên ONE PIECE magazine. &nbsp;Trong đó, một phần truyện mang tên &quot;episode : NAMI&quot; sẽ được chuyển thể thành anime. &nbsp;Ngoài ra, tác phẩm còn có sự xuất hiện của Robin và bổ sung thêm các yếu tố nguyên bản của anime, tạo nên một cốt truyện mới.</p>', 'Full', 1, 'hoathinh', 'completed', 36, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Akemi Okamura","avatar":""},{"name":"Yuriko Yamaguchi","avatar":""},{"name":"Maaya Sakamoto","avatar":""},{"name":"Takehito Koyasu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["海贼王：女英雄们的故事","航海王：女英雄们的故事","ONE PIECE HEROINES - Episode: NAMI","ONE PIECE HEROINES"]', 1784690324117);
