INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-va-to-la-hai-thai-cuc-doi-lap-seihantai-na-kimi-to-boku-phan-1', 'Cậu Và Tớ Là Hai Thái Cực Đối Lập (Seihantai na Kimi to Boku) (Phần 1)', 'You And I Are Polar Opposites (Season 1)', 'https://phimimg.com/upload/vod/20260112-1/e4c41efa551b8361f48ec33791e57a21.jpg', 'https://phimimg.com/upload/vod/20260706-1/34491fe3f69a1c5b716b73ccbd4a65ab.jpg', '<p>Suzuki, cô nữ sinh trung học sôi nổi và hướng ngoại, trót &quot;cảm nắng&quot; cậu bạn cùng lớp Tani hoàn toàn trái ngược với cô. Liệu cô có vượt qua được cảm giác hồi hộp để ngỏ lời hẹn hò?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 36, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Sayumi Suzushiro","avatar":""},{"name":"Shogo Sakata","avatar":""},{"name":"Yuna Taniguchi","avatar":""},{"name":"Konatsu Hirabayashi","avatar":""},{"name":"Anji Iwata","avatar":""},{"name":"Miyuri Shimabukuro","avatar":""},{"name":"Wataru Katoh","avatar":""},{"name":"Cocoro Omori","avatar":""},{"name":"Tomori Kusunoki","avatar":""},{"name":"Nobuyuki Sakuma","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["相反的你和我","आप और मैं एक दूसरे के बिल्कुल विपरीत हैं","Seihantai na Kimi to Boku","Ти і я - полярні протилежності","正反対な君と僕"]', 1784690324117);
