INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cau-va-to-la-hai-thai-cuc-doi-lap-seihantai-na-kimi-to-boku-phan-1', 'Cậu Và Tớ Là Hai Thái Cực Đối Lập (Seihantai na Kimi to Boku) (Phần 1)', 'You And I Are Polar Opposites (Season 1)', 'cậu và tớ là hai thái cực đối lập (seihantai na kimi to boku) (phần 1) you and i are polar opposites (season 1) sayumi suzushiro shogo sakata yuna taniguchi konatsu hirabayashi anji iwata miyuri shimabukuro wataru katoh cocoro omori tomori kusunoki nobuyuki sakuma 相反的你和我 आप और मैं एक दूसरे के बिल्कुल विपरीत हैं seihantai na kimi to boku ти і я - полярні протилежності 正反対な君と僕', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhiem-vu-gia-dinh-yozakura-phan-2-yozakurasan-chi-no-daisakusen', 'Nhiệm Vụ: Gia Đình Yozakura (Phần 2) (Yozakura-san Chi no Daisakusen)', 'Mission: Yozakura Family (Season 2)', 'https://phimimg.com/upload/vod/20260422-1/4ab299c7351685f075f7cc9d3694fcfe.jpg', 'https://phimimg.com/upload/vod/20260422-1/c7c0e1cff16430f29e26beda0a793b9e.jpg', '<p>Taiyo Asano trở nên đơn độc kể từ sau khi cha mẹ qua đời, và người duy nhất thực sự quan tâm đến cậu là cô bạn thân thuở nhỏ kiêm bạn cùng lớp, Mutsumi Yozakura. Thế nhưng, Mutsumi đang nắm giữ một bí mật động trời—cô chính là người đứng đầu của một gia tộc điệp viên lừng lẫy! Chưa dừng lại ở đó, anh trai của cô là Kyoichiro lại là một kẻ bảo vệ em gái quá mức đến mức nguy hiểm. Để ngăn Kyoichiro sát hại mình, Taiyo và Mutsumi buộc phải thực hiện một bước ngoặt không tưởng: kết hôn! Bởi lẽ, trong gia tộc Yozakura, các thành viên trong gia đình tuyệt đối không được phép tàn sát lẫn nhau.</p>', 'Tập 12', 13, 'hoathinh', 'ongoing', 28, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["夜樱家大作战","夜櫻家大作戰","המשימה: משפפחת יוזאקורה","Yozakura-san Chi no Daisakusen","夜桜さんちのミニ作戦","Yozakura-san Chi no Mini Sakusen","Mission Yozakura Family","夜桜さんちの大作戦"]', 1784690324117);
