INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-tren-dau-gio', 'Đứng Trên Đầu Gió', 'Riding The Wind', 'https://phimimg.com/upload/vod/20260629-1/7b3af32ef7aaaf6bf22e49c6bfa4676a.jpg', 'https://phimimg.com/upload/vod/20260629-1/ff8cb4090ccc2095b5293a3e9d4f69fc.jpg', '<p>Trong thời đại đất nước phát triển mạnh mẽ, Tiêu Nhất Phàm từ một nhân viên mới chập chững bước vào thương trường đã từng bước khẳng định bản thân bằng sự nỗ lực không ngừng và sự nhạy bén với thị trường. Vượt qua hàng loạt đối thủ cạnh tranh, anh nhanh chóng vươn lên trở thành nhân vật xuất sắc trong ngành bất động sản. Thế nhưng, Tiêu Nhất Phàm không bằng lòng với những thành công trước mắt. Anh dẫn dắt đội ngũ tích cực chuyển đổi mô hình, đưa doanh nghiệp hoàn toàn lột xác.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 36, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Lỗi","avatar":""},{"name":"Đồng Phi","avatar":""},{"name":"Lãnh Ba","avatar":""},{"name":"Lâm Thiếu Dương","avatar":""},{"name":"Nhậm Thiên Dã","avatar":""},{"name":"Tôn Băng Pháp","avatar":""},{"name":"Kim Ngọc Đình","avatar":""},{"name":"Dụ Ân Thái","avatar":""},{"name":"Diêm Kỷ Kỳ","avatar":""},{"name":"Ngô Xuân Di","avatar":""},{"name":"Dương Vận Nhiên","avatar":""},{"name":"Thương Đỉnh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Feng kou zhi shang","风口之上"]', 1784690324117);
