INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dung-tren-dau-gio', 'Đứng Trên Đầu Gió', 'Riding The Wind', 'đứng trên đầu gió riding the wind lý lỗi đồng phi lãnh ba lâm thiếu dương nhậm thiên dã tôn băng pháp kim ngọc đình dụ ân thái diêm kỷ kỳ ngô xuân di dương vận nhiên thương đỉnh feng kou zhi shang 风口之上', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-tich-tap-su', 'Chủ Tịch Tập Sự', 'Reborn Rookie', 'https://phimimg.com/upload/vod/20260531-1/8a6d8d1d15ce5d216a24d63ff0572a7c.jpg', 'https://phimimg.com/upload/vod/20260531-1/33c234df337af20625ef6b255580cbae.jpg', '<p>Kang Yong Ho là một chủ tịch quyền lực đã đưa tập đoàn của mình vào top 10 thế giới. Sau một tai nạn bất ngờ, linh hồn của ông hoán đổi với một thanh niên trẻ tên Hwang Jun Hyeon. Trong thân xác mới, vị chủ tịch này buộc phải bắt đầu lại từ con số không với tư cách là một nhân viên mới ngay tại chính tập đoàn mình gây dựng. Chủ Tịch Tập Sự (Reborn Rookie) đào sâu góc nhìn độc đáo về sự phân hóa giai cấp, mâu thuẫn trong gia đình tài phiệt và sự khắc nghiệt của môi trường công sở hiện đại, đồng thời truyền tải thông điệp về giá trị của lòng trắc ẩn và sự thấu hiểu từ những vị trí thấp nhất trong xã hội.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 207, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Jun-young","avatar":""},{"name":"Son Hyun-joo","avatar":""},{"name":"Lee Ju-myoung","avatar":""},{"name":"Jeon Hye-jin","avatar":""},{"name":"Jin Goo","avatar":""},{"name":"Yun Yoo-sun","avatar":""},{"name":"Lee Sung-wook","avatar":""},{"name":"Kim Jong-tae","avatar":""},{"name":"Park Cheon","avatar":""},{"name":"Jeong Jae-seong","avatar":""},{"name":"Lee Seo-an","avatar":""},{"name":"Kwon Hae-sung","avatar":""},{"name":"Byun Joong-hee","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["新入社員カン会長","Sinibsawon Ganghoejang","العودة القوية","新进社员姜会长","Rookie Employee Chairman Kang","New Employee Chairman Kang","Suddenly Intern","신입사원 강회장"]', 1784690324117);
