INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chu-tich-tap-su', 'Chủ Tịch Tập Sự', 'Reborn Rookie', 'chủ tịch tập sự reborn rookie lee jun-young son hyun-joo lee ju-myoung jeon hye-jin jin goo yun yoo-sun lee sung-wook kim jong-tae park cheon jeong jae-seong lee seo-an kwon hae-sung byun joong-hee 新入社員カン会長 sinibsawon ganghoejang العودة القوية 新进社员姜会长 rookie employee chairman kang new employee chairman kang suddenly intern 신입사원 강회장', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chieu-dien-hoa-khai', 'Chiếu Điện Hoa Khai', 'Camellias', 'https://phimimg.com/upload/vod/20260623-1/d84b6c80fa559654124bdc5c014433c9.jpg', 'https://phimimg.com/upload/vod/20260623-1/affbc3dbc0538f99a35c1ab96178a98c.jpg', '<p>Thánh nữ tộc Thiệu Khương Ngọc Quỳ từ nhỏ đã sống trong ngục tối. Khi hay tin tỷ tỷ chết thảm, nàng mang theo sức mạnh Tư Mệnh quyết tâm báo thù. Được Cửu Thiên Tuế Phong Diệp đưa về bên cạnh, từ chỗ nghi kỵ lẫn nhau, hai người dần nảy sinh tình cảm và cùng hợp sức chống lại bạo quân cùng độc hậu. Nào ngờ người tỷ tỷ năm xưa vẫn còn sống, thậm chí còn là kẻ đứng sau mọi âm mưu. Bao năm sắp đặt chỉ để đoạt lấy hoàng quyền. Khi bí mật về cặp song sinh được phơi bày, yêu hận cuối cùng cũng đối mặt với số mệnh, cùng nhau bước tới ngày hoa nở rực rỡ.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 45, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Thích Nghiên Địch","avatar":""},{"name":"Tiêu Khải Trung","avatar":""},{"name":"Đổng Nhan","avatar":""},{"name":"Lợi Lạc","avatar":""},{"name":"Trần Đằng Diệu","avatar":""},{"name":"Bạch Dư Phi","avatar":""},{"name":"Tào Tinh Vũ","avatar":""},{"name":"Lý Tinh Lâm","avatar":""},{"name":"Trương Viên Ngọc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Zhao Dian Hua Kai","照殿花开"]', 1784690324117);
