INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chieu-dien-hoa-khai', 'Chiếu Điện Hoa Khai', 'Camellias', 'chiếu điện hoa khai camellias thích nghiên địch tiêu khải trung đổng nhan lợi lạc trần đằng diệu bạch dư phi tào tinh vũ lý tinh lâm trương viên ngọc zhao dian hua kai 照殿花开', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-than-yeu-nguoi-duoc-yeu-thuong', 'Người Thân Yêu (Người Được Yêu Thương)', 'LOVED ONE', 'https://phimimg.com/upload/vod/20260428-1/c19577800a099b8ad98470fb33cd1ccb.jpg', 'https://phimimg.com/upload/vod/20260428-1/01c20b2ed4ed5fb66ce13ecd0c8d9d2f.jpg', '<p>&quot;Lời từ biệt&quot; là điều có thể xảy ra với bất kỳ ai vào ngày mai, và những gì còn lại sau đó là những cảm xúc khắc khoải. Thông qua đề tài chuyên sâu về &quot;pháp y&quot;, bộ phim ghi lại một cách tinh tế tình yêu thương giữa người với người và những dấu ấn về quãng thời gian họ đã sống. Phim lặng lẽ soi rọi ánh sáng vào những góc tối của một &quot;xã hội nơi nguyên nhân cái chết vẫn còn là ẩn số&quot;, từ đó xoa dịu nỗi đau và mang lại sự thanh thản cho những người ở lại.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 44, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Dean Fujioka","avatar":""},{"name":"Kumi Takiuchi","avatar":""},{"name":"Yusei Yagi","avatar":""},{"name":"Keito Tsuna","avatar":""},{"name":"Seira Anzai","avatar":""},{"name":"Asuka Kawatoko","avatar":""},{"name":"Takuya Kusakawa","avatar":""},{"name":"Sayaka Yamaguchi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["被爱之人","曾被爱的人","ラブドワン","亲爱的逝者"]', 1784690324117);
