INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-niem-so-kien-cam-y-dao', 'Nhất Niệm Sơ Kiến Cẩm Y Dao', 'Angels And Guards', 'https://phimimg.com/upload/vod/20260620-1/c1ce152da94b83c8ed93ca1b38a5d053.jpg', 'https://phimimg.com/upload/vod/20260620-1/6d96b21eced6e9b82608f0bd290e3dc8.jpg', '<p>Để điều tra chân tướng vụ án oan của cha mình, &quot;nữ thợ săn tiền thưởng&quot; Thẩm Băng Phàm đã gia nhập Bắc Trấn Phủ Ty thuộc Cẩm Y Vệ. Tại đây, cô cùng Trình Hân Điềm và Hoa Mãn Các trở thành những nữ Cẩm Y Vệ tài ba. Trong quá trình điều tra phá án, cô lại liên minh với ông chủ bí ẩn Thường Bắc Minh và cậu tạp dịch Hứa Đa Ngư. Họ cùng nhau đối đầu với các thế lực cường quyền, phá giải hàng loạt kỳ án, từng bước vạch trần sự thật về vụ án năm xưa khi cha cô bị hãm hại...</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 41, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Nam","avatar":""},{"name":"Cát Thu Cốc","avatar":""},{"name":"Khương Triều","avatar":""},{"name":"Đặng Hiếu Từ","avatar":""},{"name":"Lộ Trác","avatar":""},{"name":"Trác Nguyên","avatar":""},{"name":"Lưu Hạo Vũ","avatar":""},{"name":"Đới Nhã Kỳ","avatar":""},{"name":"Lý Dịch Trăn","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["一念初见锦衣谣"]', 1784690324117);
