INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhat-niem-so-kien-cam-y-dao', 'Nhất Niệm Sơ Kiến Cẩm Y Dao', 'Angels And Guards', 'nhất niệm sơ kiến cẩm y dao angels and guards trương nam cát thu cốc khương triều đặng hiếu từ lộ trác trác nguyên lưu hạo vũ đới nhã kỳ lý dịch trăn 一念初见锦衣谣', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-cong-quan', 'Nam Công Quán', 'A Controversial Entertainer', 'https://phimimg.com/upload/vod/20260518-1/321b62cae031f7cec9cdd591c07ea9cf.jpg', 'https://phimimg.com/upload/vod/20260518-1/29a58da98d376d74d594e017736e10a8.jpg', '<p>Khi một vận may lớn bất ngờ ập đến, bạn sẽ phản ứng thế nào? Liệu bạn có bị lòng tham làm mờ mắt? Phan Hạo, một tên lưu manh hạng tép riu với niềm đam mê mãnh liệt dành cho kim cương, cuối cùng lại phải vào viện tâm thần. Tại đây, anh cùng những con người khác – mỗi người đều mang trong mình một câu chuyện phức tạp riêng – đã cùng nhau tìm nơi ẩn náu tại một câu lạc bộ tiếp viên nam. Trong một bước ngoặt kỳ lạ của số phận, họ bỗng chốc lột xác thành năm &quot;trai bao&quot; hàng đầu của câu lạc bộ. Cuộc sống lập dị nhưng không kém phần hào nhoáng của họ bắt đầu mở ra, đan xen giữa những mối tình đầu, tình bạn sâu sắc và cả những cuộc cạnh tranh khốc liệt, khi mỗi người đều phải tự tìm lối đi cho riêng mình trong thế giới tiếp viên cao cấp đầy cám dỗ.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 34, 2026, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Trương Lập Ngang","avatar":""},{"name":"Trần Dịch","avatar":""},{"name":"Ngô Tư Hiền","avatar":""},{"name":"La Hoành Chính","avatar":""},{"name":"Thạch Tri Điền","avatar":""},{"name":"Chu Dư Thiên","avatar":""},{"name":"Chu Hiểu Hàm","avatar":""},{"name":"Khâu Ty Cầm","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["男公館"]', 1784690324117);
