INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-canh-kinh-hoang', 'Đôi Cánh Kinh Hoàng', 'Wings Of Dread', 'https://phimimg.com/upload/vod/20260705-1/c55ea6ea2a0a5d1e7fd1661a43175b3c.jpg', 'https://phimimg.com/upload/vod/20260705-1/da17fb96c14f9e569331b051d829b99f.jpg', '<p>Trên chuyến bay trở về từ nước ngoài, cảnh sát hàng không Cố Triều Dương đã bất ngờ đối mặt với một vụ không tặc. Với tố chất nghiệp vụ cực cao, anh liều mình ngăn chặn, mở ra cuộc chiến sinh tử diễn ra giữa độ cao chục nghìn mét trên không trung…</p>', 'Full', 1, 'single', 'completed', 78, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Thích Tiểu Long","avatar":""},{"name":"Iko Uwais","avatar":""},{"name":"Hạ Nhược Nghiên","avatar":""},{"name":"Khuất Tinh Tinh","avatar":""},{"name":"Lưu Phong Siêu","avatar":""},{"name":"Nhậm Thiên Dã","avatar":""},{"name":"Đào Hải","avatar":""},{"name":"Cao Nghị","avatar":""},{"name":"Hồng Sảng","avatar":""},{"name":"Hoàng Đào","avatar":""},{"name":"Ban Mã Gia","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["10,000 Meter Crisis","万米危机"]', 1784690324117);
