INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hell-mode-game-thu-xuat-chung-tung-hoanh-chon-di-gioi-hon-nguyen-phan-1', 'Hell Mode: Game Thủ Xuất Chúng Tung Hoành Chốn Dị Giới Hỗn Nguyên (Phần 1)', 'Hell Mode: The Hardcore Gamer Dominates In Another World With Garbage Balancing (Season 1)', 'https://phimimg.com/upload/vod/20260110-1/58766107856d6bf99459af844ed71618.jpg', 'https://phimimg.com/upload/vod/20260705-1/a6d215f7720c796c4e0b61378bc5fdfa.jpg', '<p>Kenichi Yamada, một nhân viên văn phòng 35 tuổi độc thân, đã dành phần lớn thời gian trưởng thành của mình để cày cuốc mọi tựa game MMORPG trên thị trường. Chán nản với vòng lặp của lối chơi lặp lại và luôn ưu ái người chơi mới, anh lập tức bị thu hút bởi lời quảng cáo về một trò chơi mới: không có hồi kết và đặc biệt là có chế độ &#39;Hell Mode&#39; (Chế độ Địa ngục). Đây là mức độ khó khiến việc thăng cấp trở nên gần như không tưởng, nhưng bù lại hứa hẹn tiềm năng tăng trưởng không giới hạn. Sau khi chọn lớp nhân vật Triệu hồi sư vừa ra mắt, Kenichi thấy mình tái sinh dưới hình hài Allen, một đứa trẻ sơ sinh trong một gia đình nông nô, với hành trang duy nhất là trí tuệ và những ký ức từ kiếp trước để dẫn lối.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 52, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Mutsumi Tamura","avatar":""},{"name":"Mayu Iizuka","avatar":""},{"name":"Tasuku Hatanaka","avatar":""},{"name":"Sayaka Senbongi","avatar":""},{"name":"Hideo Ishikawa","avatar":""},{"name":"Sayaka Ohara","avatar":""},{"name":"Makoto Koichi","avatar":""},{"name":"Tomokazu Sugita","avatar":""},{"name":"Shoya Chiba","avatar":""},{"name":"Marie Miyake","avatar":""},{"name":"Akio Otsuka","avatar":""},{"name":"Takahiro Miyamoto","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["地狱模式～喜欢挑战特殊成就的玩家在废设定的异世界成为无双～第二季","Hell Mode: Yarikomizuki no Gamer wa Hai Settei no Isekai de Musou suru","ヘルモード ～やり込み好きのゲーマーは廃設定の異世界で無双する～","Hell Mode: Yarikomi Suki no Gamer wa Haisettei no Isekai de Musou Suru","へるもーどやりこみずきのげーまーははいせっていのいせかいでむそうする","Hell Mode Yarikomizuki no Gamer wa Hai Settei no Isekai de Musou suru","헬 모드","地獄模式 ～喜歡挑戰特殊成就的玩家在廢設定的異世界成為無雙～ 2nd Season","Hell Mode: The Hardcore Gamer Dominates in Another World with Garbage Balancing","Hell Mode","ヘルモード ～やり込み好きのゲーマーは廃設定の異世界で無双する～ はじまりの召喚士"]', 1784690324117);
