INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-den-ky-quai-5', 'Ngôi Đền Kỳ Quái 5', 'Pee Nak 5', 'https://phimimg.com/upload/vod/20260705-1/3004beedc286a49ed16f58278d0da628.jpg', 'https://phimimg.com/upload/vod/20260705-1/fc8b1cc13f62a71a7fda561d43423b03.jpg', '<p>Thương hiệu Kinh dị - Hài Thái Lan ăn khách nhất đã trở lại. Một năm sau khi đánh bại hồn ma Nak Tinn, nhóm bạn của Balloon và First chưa kịp tận hưởng cuộc sống bình yên thì một linh hồn báo thù bất ngờ quay trở lại và săn đuổi họ. Nhưng lần này mục tiêu của Pee Nak không phải là Balloon hay First mà là chú tiểu Nott và những người thân của cậu. Để phá giải lời nguyền “Kẻ nào được yêu thương thì phải chết”, cả nhóm buộc phải quay lại ngôi đền bí ẩn và đối mặt với thế lực tàn ác hơn bao giờ hết!</p>', 'Full', 1, 'single', 'completed', 118, 2026, 'Vietsub', 'FHD', 'Thái Lan', 1, '[{"name":"Witthawat Rattanaboonbaramee","avatar":""},{"name":"Bhuripat Vejvongsatechavat","avatar":""},{"name":"Phiravich Attachitsataporn","avatar":""},{"name":"Denkhun Ngamnet","avatar":""},{"name":"Atiwat Saengtien","avatar":""},{"name":"Khunnapat Pichetworawut","avatar":""},{"name":"Pannawit Phattanasiri","avatar":""},{"name":"Worawat Boonchuen","avatar":""},{"name":"Mintra Chauwangkam","avatar":""},{"name":"Thammachad Yothajul","avatar":""},{"name":"Tatchai Yuang-ngen","avatar":""},{"name":"Parinp","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["พี่นาค 5"]', 1784690324117);
