INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hana-kimi-phan-1', 'Hana Kimi (Phần 1)', 'Hana-Kimi (Season 1)', 'https://phimimg.com/upload/vod/20260106-1/4ae15bd9e3c95a6d4219549b74531526.jpg', 'https://phimimg.com/upload/vod/20260705-1/cad072bfd8f6dab28a4e8c785b27c523.jpg', '<p>Mizuki Ashiya đang thực hiện một nhiệm vụ táo bạo: cải trang thành nam sinh và ghi danh vào một trường nội trú nam sinh để tiếp cận thần tượng của mình – ngôi sao nhảy cao Izumi Sano. Thế nhưng, sau khi thâm nhập thành công, cô bàng hoàng phát hiện ra anh đã đột ngột từ bỏ thể thao! Giờ đây, Mizuki vừa phải khéo léo né tránh mọi sự nghi ngờ để bảo vệ thân phận thật, vừa phải tìm cách lay động trái tim chàng trai mà cô hằng ngưỡng mộ — tất cả diễn ra giữa sự náo loạn và rắc rối của một ký túc xá toàn nam giới!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 33, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Aya Yamane","avatar":""},{"name":"Taku Yashiro","avatar":""},{"name":"Kikunosuke Toya","avatar":""},{"name":"Koki Uchiyama","avatar":""},{"name":"Yuuichirou Umehara","avatar":""},{"name":"Reiji Kawashima","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hana-Kimi","Hanazakari no Kimitachi e","Hana-Kimi: For You in Full Blossom","For You in Full Blossom","花ざかりの君たちへ"]', 1784690324117);
