INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-boy-and-i-who-will-break-up-in-100-days', 'The Boy And I Who Will Break Up In 100 Days', 'The Boy And I Who Will Break Up In 100 Days', 'https://phimimg.com/upload/vod/20260603-1/744f3ac669d0dcc079ff34b2f7a6094e.jpg', 'https://phimimg.com/upload/vod/20260603-1/78c2517c4926dc386b05660e5a9f7b08.jpg', '<p>Sau khi câu chuyện chia tay của Yuma và Itsuki trở nên nổi tiếng trên mạng, hai người yêu cũ phải giả vờ có một mối quan hệ hoàn hảo trong một bộ phim tài liệu kéo dài 100 ngày, đồng thời che giấu việc họ đã thực sự chia tay.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 28, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["100 Nichi Go Ni Wakareru Boku to Kare","Hyakunichigo ni Wakareru Boku to Kare","100 Days Until We Break Up","100日後に別れる僕と彼"]', 1784690324117);
