INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-boy-and-i-who-will-break-up-in-100-days', 'The Boy And I Who Will Break Up In 100 Days', 'The Boy And I Who Will Break Up In 100 Days', 'the boy and i who will break up in 100 days the boy and i who will break up in 100 days  100 nichi go ni wakareru boku to kare hyakunichigo ni wakareru boku to kare 100 days until we break up 100日後に別れる僕と彼', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gio-thoang-tinh-theo', 'Gió Thoảng Tình Theo', 'The Air 4 Elements', 'https://phimimg.com/upload/vod/20260518-1/44e82161567f7c384837926ad3ee9407.jpg', 'https://phimimg.com/upload/vod/20260518-1/915794645eafc3f63b90e9a4175bf5f6.jpg', '<p>Công chúa Blue, người thừa kế ngai vàng xứ Madelin, có chuyến công du đến Thái Lan và gặp gỡ Wayo Wathinwanit – một sĩ quan cảnh sát được giao nhiệm vụ bảo vệ an toàn cho cô. Tuy nhiên, chuyến đi nhanh chóng trở thành một cơn ác mộng khi một âm mưu ám sát nổ ra, buộc công chúa phải tháo chạy, và Lom là người duy nhất có thể bảo vệ cô.&nbsp; Trong thời gian lẩn trốn kẻ thù, cả hai phải đối mặt với vô vàn hiểm nguy và những tình huống ngặt nghèo. Chính sự đồng cam cộng khổ ấy đã kéo họ lại gần nhau hơn, làm nảy sinh một thứ tình cảm thân mật và cấm đoán không thể cứu vãn. Dù biết rõ rằng mối tình này là bất khả thi, trái tim của Lom vẫn thúc giục cô phải bảo vệ công chúa bằng mọi giá. Khi kẻ thù tìm ra nơi ẩn náu của họ, một trận chiến sinh tử cuối cùng chuẩn bị bắt đầu.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 40, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Sarocha Chankimha","avatar":""},{"name":"Becky Armstrong","avatar":""},{"name":"Orntara Poolsak","avatar":""},{"name":"Prompatcha Sanitwong Na Ayutthaya","avatar":""},{"name":"Renée Veronica","avatar":""},{"name":"Lapisara Intarasut","avatar":""},{"name":"Panthita Jencharoentham","avatar":""},{"name":"Engfa Waraha","avatar":""},{"name":"Charlotte Austin","avatar":""},{"name":"Milin Watinthanakit","avatar":""},{"name":"Justin Angus Moir","avatar":""},{"name":"Wanchana Sawasdee","avatar":""},{"name":"Thitisan Goodbu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Air 4 Elements","บ้านวาทินวณิช: เสน่หาวาโย","4 Elements: The Air","เสน่หาวาโย บ้านวาทินวณิช","เสน่หาวาโย"]', 1784690324117);
