INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gio-thoang-tinh-theo', 'Gió Thoảng Tình Theo', 'The Air 4 Elements', 'gió thoảng tình theo the air 4 elements sarocha chankimha becky armstrong orntara poolsak prompatcha sanitwong na ayutthaya renée veronica lapisara intarasut panthita jencharoentham engfa waraha charlotte austin milin watinthanakit justin angus moir wanchana sawasdee thitisan goodbu the air 4 elements บ้านวาทินวณิช: เสน่หาวาโย 4 elements: the air เสน่หาวาโย บ้านวาทินวณิช เสน่หาวาโย', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-be-khong-len-thien-duong', 'Cậu Bé Không Lên Thiên Đường', 'Ticket To Heaven', 'https://phimimg.com/upload/vod/20260601-1/f6dc2a96c812fe8f0596eba956a95fcd.jpg', 'https://phimimg.com/upload/vod/20260601-1/932dc859d74c05563fe32e7719cd8eb6.jpg', '<p>Một nam sinh đang ôm nỗi đau mất mát và trên con đường tu học để trở thành linh mục bỗng phải đối mặt với một cuộc khủng hoảng đức tin trầm trọng khi anh đem lòng yêu một người bạn học mới có cuộc sống đầy rẫy rắc rối. Câu chuyện diễn ra trong một thế giới bị thống trị bởi những giáo điều và luật lệ vô cùng hà khắc.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 38, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Norawit Titicharoenrak","avatar":""},{"name":"Nattawat Jirochtikul","avatar":""},{"name":"Peerakan Teawsuwan","avatar":""},{"name":"Oliver Poupart","avatar":""},{"name":"Rapheephong Thapsuwan","avatar":""},{"name":"Phakawat Tangchatkeaw","avatar":""},{"name":"Supakorn Kantanit","avatar":""},{"name":"Chayada Akiyama","avatar":""},{"name":"Thamonchita Narmkool","avatar":""},{"name":"Poon Sutarom","avatar":""},{"name":"Phollawat Manuprasert","avatar":""},{"name":"Sinjai Plengpanich","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["不上天堂的男孩","天国男孩","The Boy Who Doesn''t Go to Heaven","Ticket to Heaven","เด็กชายไม่ไปสวรรค์"]', 1784690324117);
