INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('theo-duoi-tinh-yeu-2026', 'Theo Đuổi Tình Yêu', 'Chasing Love', 'https://phimimg.com/upload/vod/20260608-1/676bc74f4423d409f268fd914d11bb14.jpg', 'https://phimimg.com/upload/vod/20260608-1/44184d13c7951494a74e957e4919b17b.jpg', '<p>Song, một nữ nghiên cứu sinh ẩm thực mang phong cách &quot;mọt sách quyến rũ&quot;, đã có một đêm cuồng nhiệt với một người phụ nữ bí ẩn dưới một điều kiện nghiêm ngặt: không ràng buộc tình cảm. Thế nhưng, đối phương đã vi phạm thỏa thuận khi chủ động đòi hỏi một sự gắn kết về mặt cảm xúc. Song lập tức chấm dứt cuộc gặp gỡ nóng bỏng ấy và quay lưng bước đi.&nbsp; Nhưng trái đất quả thực rất tròn. Người phụ nữ đêm đó hóa ra lại là Piangrawin — con gái cưng của chủ tịch tập đoàn nơi Song đang làm việc. Và Piangrawin thì không dễ dàng buông tay đến vậy. Cô nàng bắt đầu theo đuổi Song với sự si mê và trung thành như một chú cún con, dùng sự quyến rũ đầy táo bạo của mình để len lỏi và làm đảo lộn cả trái tim lẫn cuộc sống thường nhật của Song. Thậm chí, cô còn tuyên bố rằng mình đã đặt sẵn tên cho đứa con tương lai của hai người.</p>', 'Tập 5', 8, 'series', 'ongoing', 60, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Chanidapa Sommitthanakul","avatar":""},{"name":"Natchaya Vongbut","avatar":""},{"name":"Apisara Lertwisettheerakul","avatar":""},{"name":"Onnalin Lilaburanathanakun","avatar":""},{"name":"Sirinart Sugandharat","avatar":""},{"name":"Nuttharat Papirom","avatar":""},{"name":"Duangdao Jarujinda","avatar":""},{"name":"Duangjai Hathaikarn","avatar":""},{"name":"Tewin Surachardkait","avatar":""},{"name":"Thitaree Paksirichayanon","avatar":""},{"name":"Nannapas Pattanapasai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chasing Love พี่เองก็ลำบาก","พี่เองก็ลำบาก"]', 1784690324117);
