INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('theo-duoi-tinh-yeu-2026', 'Theo Đuổi Tình Yêu', 'Chasing Love', 'theo đuổi tình yêu chasing love chanidapa sommitthanakul natchaya vongbut apisara lertwisettheerakul onnalin lilaburanathanakun sirinart sugandharat nuttharat papirom duangdao jarujinda duangjai hathaikarn tewin surachardkait thitaree paksirichayanon nannapas pattanapasai chasing love พี่เองก็ลำบาก พี่เองก็ลำบาก', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('eren-thuan-tay-trai', 'Eren Thuận Tay Trái', 'Eren The Southpaw', 'https://phimimg.com/upload/vod/20260420-1/22a03c8f116ee54451afa28cf4889be5.jpg', 'https://phimimg.com/upload/vod/20260420-1/0bdad34858c22b87d58f01e474661fe0.jpg', '<p>Khi những năm tháng trung học đi được nửa chặng đường, Koichi Asakura — chàng trai mang ước mơ theo đuổi ngành thiết kế tại một trường nghệ thuật — đã bị chấn động mạnh trước những nét vẽ graffiti bùng nổ trên bức tường của một bảo tàng. Tác giả của chúng là Eren Yamagishi, một cô gái thuận tay trái vốn đã chôn vùi tài năng thiên bẩm của mình sau một biến cố trong quá khứ. Bị thu hút bởi nghệ thuật của nhau, Koichi quyết tâm theo đuổi con đường thiết kế trong khi Eren bắt đầu cầm cọ vẽ trở lại. Tuy nhiên, nỗi sợ hãi, tham vọng và những vết sẹo cũ bắt đầu đe dọa con đường mà họ đã chọn, buộc cả hai phải đối mặt với thực tế khốc liệt của đam mê.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 27, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shoya Chiba","avatar":""},{"name":"Yumi Uchiyama","avatar":""},{"name":"Yui Ishikawa","avatar":""},{"name":"Akira Sekine","avatar":""},{"name":"Kazuyuki Okitsu","avatar":""},{"name":"Yurina Amami","avatar":""},{"name":"Koji Yusa","avatar":""},{"name":"Tarusuke Shingaki","avatar":""},{"name":"Asaki Yuikawa","avatar":""},{"name":"Kenichirou Matsuda","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hidarikiki no Eren","左ききのエレン","Ellen the Southpaw"]', 1784690324117);
