INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-duong-hanh-y', 'Con Đường Hành Y', 'Trial Of Healer', 'https://phimimg.com/upload/vod/20260624-1/6df8af82450cbcd538bc826c6255171c.jpg', 'https://phimimg.com/upload/vod/20260624-1/daa3150f5ce96252887eff11f152e930.jpg', '<p>Thần y Dương Vân Phàm, người từng mất trí nhớ sau biến cố cả gia tộc bị thảm sát, nay trở về Giang Thành với khí thế mạnh mẽ. Thế nhưng, anh lại vô tình bị cuốn vào cuộc tranh quyền đoạt lợi giữa các gia tộc thuộc Huyền Y Hội. Giữa những mối quan hệ đan xen với nữ tổng tài bá đạo Diệp Khinh Tuyết, nữ dược sư dịu dàng Lục Đàn Hương, nữ sát thủ xinh đẹp Lâm Hồng Tụ cùng nhiều bóng hồng khác, liệu Dương Vân Phàm có thể vén màn bí mật về thân thế của mình hay không?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 30, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Tử Kiện","avatar":""},{"name":"Lưu Mỹ Đồng","avatar":""},{"name":"Vu Tân Thông","avatar":""},{"name":"Triệu Tịnh Y","avatar":""},{"name":"Hoàng Nhược Phi","avatar":""},{"name":"Lý Hựu Xuyên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["行医道"]', 1784690324117);
