INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-co-phao-hoa', 'Tình Yêu Có Pháo Hoa', 'Love Has Fireworks', 'https://phimimg.com/upload/vod/20260615-1/c2def538c0d18eeace93e7a6c358679f.jpg', 'https://phimimg.com/upload/vod/20260615-1/db63587e4b529e6604d423307c8d0258.jpg', '<p>Tình Yêu Có Pháo Hoa là bộ phim tình cảm đô thị xoay quanh Lý Diệc Phi, một chuyên gia ngân hàng đầu tư sa cơ sau thất bại trong công việc, và Tiền Phi, cô gái đang chật vật đối mặt với cú sốc thất tình lẫn thất nghiệp. Tình cờ trở thành bạn cùng nhà để giảm bớt gánh nặng tài chính, cả hai liên tục va chạm vì khác biệt về tính cách, hoàn cảnh và quan điểm sống. Thế nhưng qua những ngày chung sống đầy dở khóc dở cười, họ dần thấu hiểu, động viên và giúp nhau trưởng thành, từ đó viết nên một câu chuyện tình yêu ngọt ngào giữa lòng thành phố hiện đại.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 81, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Đàn Kiện Thứ","avatar":""},{"name":"Vương Sở Nhiên","avatar":""},{"name":"Lý Nãi Văn","avatar":""},{"name":"Lý Hân Trạch","avatar":""},{"name":"Khương Bội Dao","avatar":""},{"name":"Trịnh Thủy Tinh","avatar":""},{"name":"Lưu Nhuế Lân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["爱情有烟火","我们住在一起","愛情有煙火","Ai Qing You Yan Huo","We live together","Shining Character"]', 1784690324117);
