INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-ngoan-len-thien-duong', 'Trai Ngoan Lên Thiên Đường', 'Good Boys Go to Heaven', 'https://phimimg.com/upload/vod/20260608-1/60b53fd5f7096a3a65b16e92e51aabf6.jpg', 'https://phimimg.com/upload/vod/20260608-1/15326b50398ae7bf62d3a42e622f63cf.jpg', '<p>Khi con trai bị sát hại tại Kuala Makar yên bình, người cha không có bằng chứng ngoại phạm thành nghi phạm chính. Ông quyết tự tìm hung thủ thật sự để minh oan.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 52, 2026, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Beto Kusyairy","avatar":""},{"name":"Zahirah MacWilson","avatar":""},{"name":"Sky Iskandar","avatar":""},{"name":"Amerul Affendi","avatar":""},{"name":"Amanda Ang","avatar":""},{"name":"Firdaus Karim","avatar":""},{"name":"Malek Mccrone","avatar":""},{"name":"Mila Mohsin","avatar":""},{"name":"Dai Fuad","avatar":""},{"name":"Marzuki Noh","avatar":""},{"name":"Zaleha Iman","avatar":""},{"name":"Sayf Mikael","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Good Boys Go to Heaven"]', 1784690324117);
