INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-gioi-nha-ma', 'Môi Giới Nhà Ma', 'Haunted House Secrets', 'https://phimimg.com/upload/vod/20260203-1/3068f6fa20435dbdce513c582373794a.jpg', 'https://phimimg.com/upload/vod/20260203-1/6c76769cf92816664e3b8d9986aa67ca.jpg', '<p>Một nhóm chuyên xử lý các ngôi nhà bị ám đi tìm hiểu những câu chuyện của những linh hồn mắc kẹt. Qua mỗi lần hóa giải chấp niệm, họ không chỉ chữa lành cho người đã khuất mà còn đối diện và vượt qua những tổn thương trong chính tâm hồn mình.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 45, 2026, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Christopher Lee Ming-Shun","avatar":""},{"name":"Fandy Fan","avatar":""},{"name":"Buffy Chen","avatar":""},{"name":"Hong Huifang","avatar":""},{"name":"Shih Ming-shuai","avatar":""},{"name":"Allison Lin","avatar":""},{"name":"Cammy Chiang","avatar":""},{"name":"Purple Hsu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324117);
