INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('super-subbu', 'Super Subbu', 'Super Subbu', 'https://phimimg.com/upload/vod/20260703-1/944df7dd0ad9bcf37168e7a379bb66c2.jpg', 'https://phimimg.com/upload/vod/20260703-1/e03705a76efed4a45c6eba6ff4bd2dcf.jpg', '<p>Một thầy giáo đen đủi bị điều động về giảng dạy bộ môn giáo dục giới tính tại một ngôi làng đầy định kiến và thù địch. Liệu anh có thể cân bằng được việc giữ kín bí mật này, trong khi vừa phải theo đuổi ước mơ của bản thân, vừa phải cứu vãn mối quan hệ tình cảm của chính mình?</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 42, 2026, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Sundeep Kishan","avatar":""},{"name":"Mithila Palkar","avatar":""},{"name":"Murali Sharma","avatar":""},{"name":"Maanasa Chaudhary","avatar":""},{"name":"Sampoornesh Babu","avatar":""},{"name":"Divya Pillai","avatar":""},{"name":"Brahmanandam","avatar":""},{"name":"Raghu Babu","avatar":""},{"name":"Getup Srinu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["אין על סאבו","Super Subbu"]', 1784690324117);
