INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-o-thoi-lenh-hoa-cua-ngai-dara', 'Cuộc Sống Ở Thời Lệnh Hòa Của Ngài Dara', 'Dara-san Of Reiwa', 'https://phimimg.com/upload/vod/20260703-1/70c74fd95e4902512ea412da15873c26.jpg', 'https://phimimg.com/upload/vod/20260703-1/fa2d431e68ed9e55d3d455b57253d1d7.jpg', '<p>Sau khi liều lĩnh tiến vào một khu rừng núi hiểm trở và bị cấm, hai anh em Hinata và Kaoru đã chạm trán với một vị xà thần vô cùng đáng sợ, nhưng rồi họ lại bất ngờ trở thành những người bạn thân thiết của nhau! Bất chấp vẻ ngoài ban đầu có phần ghê rợn, vị thần tự xưng là &quot;thần xui xẻo&quot; này thực chất lại rất vụng về, cô đơn và dễ trò chuyện một cách ngạc nhiên.</p>', 'Tập 1', 13, 'hoathinh', 'ongoing', 28, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["令和的斑小姐","令和妖神斑小姐","Reiwa no Dara-san","Dara-san of the Reiwa Era","令和のダラさん"]', 1784690324118);
