INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-von-hien-luong', 'Vợ Vốn Hiền Lương', 'Inherently Kind', 'https://phimimg.com/upload/vod/20260623-1/2862b42208ce70206049da9b56385ad6.jpg', 'https://phimimg.com/upload/vod/20260623-1/0cb13c5580ae718af2e4b962c0480997.jpg', '<p>Khi đang điều tra bí mật về nguyên liệu của công ty mỹ phẩm Quốc tế Mỹ Nghiên, Tô Lê không may gặp tai nạn mất trí nhớ. Cô bị nhận nhầm thành Cố Thanh Mai, nàng dâu nhu nhược của nhà họ Hạ. Tại đây, Tô Lê kết đồng minh với Mục Thiếu Trạch, kẻ đang âm thầm báo thù cho bố. Cả hai sát cánh phá bỏ lớp màn bí ẩn, từng bước vạch trần sự thật đằng sau.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 28, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Tịch Tịch","avatar":""},{"name":"Lâm Trạch Huy","avatar":""},{"name":"Chu Hoành","avatar":""},{"name":"Văn Cảnh Chi","avatar":""},{"name":"Dư Tông Vĩ","avatar":""},{"name":"Châu Ngữ Đình","avatar":""},{"name":"Lưu Tích Minh","avatar":""},{"name":"Vương Lệ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["妻本善良"]', 1784690324118);
