INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuyen-dau-hai-quan', 'Tuyến Đầu Hải Quan', 'Gimlet Eyes', 'https://phimimg.com/upload/vod/20260702-1/2ab97749432fbbc02cf5cef2c2a79e9a.jpg', 'https://phimimg.com/upload/vod/20260702-1/4dc23ceff09e332fff483825ce4bab14.jpg', '<p>Lấy bối cảnh lực lượng hải quan kiểm tra hành lý tại một sân bay quốc tế, phim kể về trưởng khoa kiểm tra Quách Thông cùng các đồng đội ngày đêm đấu tranh với những đường dây buôn lậu, vận chuyển hàng cấm và tội phạm xuyên biên giới. Thông qua nhiều vụ án điển hình, bộ phim khắc họa tinh thần trách nhiệm, sự chuyên nghiệp và lòng tận tụy của những cán bộ hải quan trong việc bảo vệ lợi ích quốc gia.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 46, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Kinh Siêu","avatar":""},{"name":"Hoàng Nghiêu","avatar":""},{"name":"Đồ Chỉ Oánh","avatar":""},{"name":"Đồng Duyệt","avatar":""},{"name":"Tề Khuê","avatar":""},{"name":"Dương Khải Trình","avatar":""},{"name":"Tôn Trọng Thu","avatar":""},{"name":"Lục Tinh","avatar":""},{"name":"Quốc Lệ Na","avatar":""},{"name":"Phó Mạn","avatar":""},{"name":"Lý Viện","avatar":""},{"name":"Tác Lãng Vượng Mỗm","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["吾辈当关","金关·旅检一科","金关"]', 1784690324118);
