INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-quy', 'Chung Quỳ', 'Master Zhong (Zhong Kui)', 'https://phimimg.com/upload/vod/20260702-1/b98d4d9d44046912207111bd0f287f17.jpg', 'https://phimimg.com/upload/vod/20260702-1/e4f8e86eaa373210c77d8a1c71db8895.jpg', '<p>Thiếu nữ phàm nhân Sơ Cửu vô tình xâm nhập địa phủ và được Chung Quỳ cứu giúp. Cô trở thành đồng hành của Chung Quỳ trong hành trình trừ yêu diệt quỷ, bảo vệ tam giới. Khi điều tra các vụ yêu quái tác oai tác quái, cả hai dần phát hiện một âm mưu khổng lồ đe dọa sự cân bằng giữa nhân gian và địa phủ.</p>', 'Full', 1, 'hoathinh', 'completed', 34, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đoàn Nghệ Tuyền","avatar":""},{"name":"Dư Hạo Uy","avatar":""},{"name":"Hồ Lương Vĩ","avatar":""},{"name":"Triệu Thành Thần","avatar":""},{"name":"Ba Hách","avatar":""},{"name":"Hồ Chính Kiện","avatar":""},{"name":"Lộ Tây","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Master Zhong","钟馗"]', 1784690324118);
