INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chung-quy', 'Chung Quỳ', 'Master Zhong (Zhong Kui)', 'chung quỳ master zhong (zhong kui) đoàn nghệ tuyền dư hạo uy hồ lương vĩ triệu thành thần ba hách hồ chính kiện lộ tây master zhong 钟馗', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-muon-cham-dut-tro-choi-tinh-yeu-nay', 'Tôi Muốn Chấm Dứt Trò Chơi Tình Yêu Này', 'I Want To End This Love Game', 'https://phimimg.com/upload/vod/20260420-1/d86cc64d08fa8f33a0ee33addaaa75a0.jpg', 'https://phimimg.com/upload/vod/20260420-1/30b258a9cd85345a33cde7ee8dce1453.jpg', '<p>Nao là một bản sao được tạo ra để trở thành &quot;hình nhân thế thân&quot; hoàn hảo cho Sunao Aikawa, chuyên thay thế Sunao mỗi khi cô nàng trốn học. Nao đi học, chơi thể thao và sống mỗi ngày chỉ vì bản chính—cho đến một ngày, cô nảy sinh tình cảm với một chàng trai. Đột nhiên, cuộc đời lặng lẽ mượn tạm của Nao bừng sáng với những buổi hẹn hò bí mật và những lời hứa thẹn thùng. Thế nhưng, Nao càng trân trọng những khoảnh khắc ấy bao nhiêu thì cô càng phải che giấu kỹ bấy nhiêu trước Sunao, người đang bắt đầu nhận ra những thay đổi lạ thường ở bản sao của mình.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 28, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kaito Ishikawa","avatar":""},{"name":"Miku Ito","avatar":""},{"name":"Wakana Maruoka","avatar":""},{"name":"Yui Ogura","avatar":""},{"name":"Kaede Hondo","avatar":""},{"name":"Takehito Koyasu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["想让“我爱你”游戏快点结束","I Want to End the \"I Love You\" Game","I Want to End the Game That I Love","I Want to End the Game of Love","Aishiteru Game wo Owarasetai","Zakończmy Grę w \"Kocham Cię\"","Я хочу закінчити цю любовну гру","愛してるゲームを終わらせたい"]', 1784690324118);
