INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('toi-muon-cham-dut-tro-choi-tinh-yeu-nay', 'Tôi Muốn Chấm Dứt Trò Chơi Tình Yêu Này', 'I Want To End This Love Game', 'tôi muốn chấm dứt trò chơi tình yêu này i want to end this love game kaito ishikawa miku ito wakana maruoka yui ogura kaede hondo takehito koyasu 想让“我爱你”游戏快点结束 i want to end the "i love you" game i want to end the game that i love i want to end the game of love aishiteru game wo owarasetai zakończmy grę w "kocham cię" я хочу закінчити цю любовну гру 愛してるゲームを終わらせたい', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-samurai-nhung-nam-thang-edo', 'Huyền Thoại Samurai: Những Năm Tháng Edo', 'Song Of The Samurai: Chapter Youthful Days In Edo', 'https://phimimg.com/upload/vod/20260513-1/3765bd1e33786391947756e427190e6b.jpg', 'https://phimimg.com/upload/vod/20260513-1/ceb2d9977a438ab68d4442d9a05d999b.jpg', '<p>Một bản chuyển thể live-action đưa di sản sâu sắc này lên màn ảnh rộng. Lấy bối cảnh tại Kyoto vào cuối thời Edo, câu chuyện khắc họa cuộc đời mãnh liệt và đầy nhiệt huyết của Shinsengumi – lực lượng samurai biểu tượng đã bảo vệ Kyoto trong những năm cuối cùng của chế độ Mạc phủ tại Nhật Bản – thông qua những màn hành động mãn nhãn và cách diễn giải táo bạo dựa trên các sự thật lịch sử. Chuyện phim theo chân tay đấm đường phố Hijikata Toshizo (Yuki Yamada), người đã tìm thấy một gia đình mới bên cạnh Kondo Isami và Okita Soji. Hijikata cùng các đồng đội trong Shinsengumi đã rèn giũa một mối liên kết của lòng trung thành – thứ vốn bị thử thách bởi sự phản bội, bệnh tật và chiến tranh – khi họ không chỉ chiến đấu chống lại kẻ thù mà còn phải đấu tranh với chính lý tưởng của bản thân mình.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 25, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuki Yamada","avatar":""},{"name":"Nobuyuki Suzuki","avatar":""},{"name":"Aoi Nakamura","avatar":""},{"name":"Kanata Hosoda","avatar":""},{"name":"Shuhei Uesugi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["A Canção do Samurai","武士之歌","La canción del samurái","Song of the Samurai","ちるらん 新撰組鎮魂歌 ～江戸青春篇～","ちるらん しんせんぐみれくいえむ","Chiruran Shinsengumi Chinkonka Edo Seishun Hen","Chiruran Shinsengumi Requiem","ちるらん 新撰組鎮魂歌 江戸青春篇"]', 1784690324118);
