INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-nu-thich-hang-hieu-2', 'Yêu Nữ Thích Hàng Hiệu 2', 'The Devil Wears Prada 2', 'https://phimimg.com/upload/vod/20260701-1/c9933962bce57a3399c3743a720c73bd.jpg', 'https://phimimg.com/upload/vod/20260701-1/206bfd58c7217cdb7d8046e24ac9a09a.jpg', '<p>Hai mươi năm sau màn hóa thân kinh điển vào các vai diễn Miranda, Andy, Emily và Nigel — Meryl Streep, Anne Hathaway, Emily Blunt và Stanley Tucci sẽ chính thức trở lại với những con phố thời thượng của New York và văn phòng sang trọng của Tạp chí Runway trong &quot;The Devil Wears Prada 2&quot; (Yêu Nữ Thích Hàng Hiệu 2). Đây là phần phim tiếp theo cực kỳ được mong đợi từ 20th Century Studios, kế thừa sức hút từ hiện tượng điện ảnh năm 2006 từng định hình phong cách cho cả một thế hệ. Bộ phim được đạo diễn bởi David Frankel, kịch bản bởi Aline Brosh McKenna, sản xuất bởi Wendy Finerman, điều hành sản xuất bởi Michael Bederman, Karen Rosenfelt và Aline Brosh McKenna.</p>', 'Full', 1, 'single', 'completed', 62, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Meryl Streep","avatar":""},{"name":"Anne Hathaway","avatar":""},{"name":"Emily Blunt","avatar":""},{"name":"Stanley Tucci","avatar":""},{"name":"Kenneth Branagh","avatar":""},{"name":"Justin Theroux","avatar":""},{"name":"Lucy Liu","avatar":""},{"name":"Tracie Thoms","avatar":""},{"name":"Tibor Feldman","avatar":""},{"name":"B.J. Novak","avatar":""},{"name":"Patrick Brammall","avatar":""},{"name":"Simone Ashley","avatar":""},{"name":"Caleb Hearon","avatar":""},{"name":"Helen J. Shen","avatar":""},{"name":"Rachel Bloom","avatar":""},{"name":"Larry Mitchell","avatar":""},{"name":"George C. Wolfe","avatar":""},{"name":"Danie","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Yêu Nữ Mặc Đồ Prada 2","Djalli vishet me prada 2","Şeytan Marka Giyer 2","Дьявол носит Prada 2","The Devil Wears Prada 2"]', 1784690324118);
