INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hang-xom-toi-te-nhat', 'Người Hàng Xóm Tồi Tệ Nhất', 'Worst Neighbor Ever', 'https://phimimg.com/upload/vod/20260701-1/fe4b45168b017d2179e2c88a092fc22e.jpg', 'https://phimimg.com/upload/vod/20260701-1/47aff003833e436ed2c955aa64c2340d.jpg', '<p>Từ người từng ở nhờ nhà Shawna và Dave, Frances dần trở thành một người hàng xóm hoang tưởng, bị ám ảnh bởi những bất mãn và quyết đẩy cuộc đối đầu chỉ từ phía mình đi xa hơn nữa.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 64, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Worst Neighbor Ever"]', 1784690324118);
