INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-he-36-lete-36', 'Mùa Hè 36 (L''Été 36)', 'Summer ''36', 'https://phimimg.com/upload/vod/20260701-1/fc9f0286f18f831713db69f36cfef392.jpg', 'https://phimimg.com/upload/vod/20260701-1/faae7c9b2e0e17ddf529e2bc63623871.jpg', '<p>Nợ cờ bạc. Người cha đối mặt với án tử. Một người con trai chưa ai biết đến. Tình nhân bí mật. Bốn người phụ nữ đều liên quan đến một công tố viên bị sát hại trong phòng khách sạn.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 42, 2026, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Julie de Bona","avatar":""},{"name":"Sofia Essaïdi","avatar":""},{"name":"Nolwenn Leroy","avatar":""},{"name":"Constance Gay","avatar":""},{"name":"François-Xavier Demaison","avatar":""},{"name":"Miou-Miou","avatar":""},{"name":"Pascal Elbé","avatar":""},{"name":"Sam Karmann","avatar":""},{"name":"Constance Dollé","avatar":""},{"name":"Camille Japy","avatar":""},{"name":"Simon Ehrlacher","avatar":""},{"name":"Assaad Bouab","avatar":""},{"name":"Arnaud Binard","avatar":""},{"name":"Antoine Simony","avatar":""},{"name":"Patrick Ridremont","avatar":""},{"name":"Victoria Eber","avatar":""},{"name":"Cléme","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Лето 1936-го","Summer ''36","L''Été 36"]', 1784690324118);
