INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguyen-thuong-phong-van-phong-van-tren-cao-nguyen', 'Nguyên Thượng Phong Vân (Phong Vân Trên Cao Nguyên)', 'Storm Over The Plateau', 'https://phimimg.com/upload/vod/20260701-1/c83f41a6130d30e311df1040e2b30bf1.jpg', 'https://phimimg.com/upload/vod/20260701-1/d9bde3e846708efb7a8463f05b77e1e7.jpg', '<p>Trong thời kỳ Kháng chiến chống Nhật, quân đội Nhật tiến đánh cửa ải Hàm Cốc ở vùng Dự Tây (phía tây tỉnh Hà Nam), mưu toan khai thông tuyến đường trọng yếu để tiến quân về phía tây. Đảng viên Cộng sản Thái Bảo Tử trở về quê hương để phát động phong trào kháng chiến, không may rơi vào cảnh hiểm nghèo, lại còn bị hiểu lầm và chịu hàm oan đến mức phải ngồi tù. Trong ngục tối, anh kết giao với thủ lĩnh của hai băng đảng đao khách địa phương; bằng sự gan dạ và tầm nhìn lớn của mình, anh đã hóa giải ân oán và quy tụ lòng người. Sau khi ra tù, anh bôn ba khắp nơi để liên lạc, đoàn kết các đao khách, quan binh yêu nước cùng người dân chính nghĩa trong vùng, hợp nhất các lực lượng để thành lập một đội quân kháng Nhật.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 27, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Mã Kính Hàm","avatar":""},{"name":"Trương Văn","avatar":""},{"name":"Lý Thịnh Diệp","avatar":""},{"name":"Lưu Lập Vĩ","avatar":""},{"name":"Thôi Bảo Nguyệt","avatar":""},{"name":"Tiền Y","avatar":""},{"name":"Trương Á Khôn","avatar":""},{"name":"Khương Chấn Hạo","avatar":""},{"name":"Mã Luân","avatar":""},{"name":"Vương Lan","avatar":""},{"name":"Đàm Kiến Xương","avatar":""},{"name":"Trương Kế Nam","avatar":""},{"name":"Vương Nghệ Thiền","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yuan Shang Feng Yun","塬上风云"]', 1784690324118);
