INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-phuot-ban-gioi-han', 'Đi Phượt Bản Giới Hạn', 'Unplanned Trip: Limited Edition', 'https://phimimg.com/upload/vod/20260701-1/d7cb0e0309b9e22e7eda8fe6e6037998.jpg', 'https://phimimg.com/upload/vod/20260701-1/f04ad30580880b8a79225d41d309642f.jpg', '<p>Các minh tinh Park Seo Joon, Jung Yu Mi và Choi Woo Sik bất ngờ bị &quot;lạc trôi&quot; vào một chuyến đi phượt bất định, không có kế hoạch trước. Họ sẽ chống chọi ra sao với chuyến chu du tự túc vòng quanh Hàn Quốc cùng vô vàn tình huống dở khóc dở cười?</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 42, 2026, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Seo-jun","avatar":""},{"name":"Choi Woo-shik","avatar":""},{"name":"Jung Yu-mi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["꽃보다 청춘: 리미티드 에디션"]', 1784690324118);
