INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-den-noi-hoa-dao-no-ro-noi-hoa-dao-no-ro-2', 'Đi Đến Nơi Hoa Đào Nở Rộ (Nơi Hoa Đào Nở Rộ 2)', 'Finding Home In Blossoms (What Place Blossoms Bloom 2)', 'https://phimimg.com/upload/vod/20260701-1/be8e4ec5d8f41256b8ea4847f141f72f.jpg', 'https://phimimg.com/upload/vod/20260701-1/946c553801349489af3994e36e1aae10.jpg', '<p>Một nữ tiến sĩ sau khi học hành thành tài trở về quê hương phải đối mặt với việc nhiều mẫu giống phục vụ nghiên cứu liên tiếp bị phá hoại; một người cha khốn đốn vì trốn nợ, phải rời bỏ quê nhà lại bị cô con gái là người nổi tiếng trên mạng tìm đến; một người làm vườn coi đất khách như quê hương đang đứng trước nguy cơ những nhà kính trồng rau quý như sinh mạng của mình bị tháo dỡ; một người kế thừa nghề thủ công phi vật thể phải lựa chọn giữa việc giữ vững chất lượng và chạy theo doanh số. Đây là làng Hoa Đào xinh đẹp của Tây Tạng, nơi mỗi ngày đều diễn ra những câu chuyện đầy cuốn hút.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 26, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Qu Tao Hua Sheng Kai Di Di Fang","去桃花盛开的地方2","To Where Peach Blossoms Bloom","What Place Blossoms Bloom 2","Finding Home in Blossoms 2","去桃花盛开的地方"]', 1784690324118);
