INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-nhan-phong-khoi-dai-mac', 'Tiêu Nhân: Phong Khởi Đại Mạc', 'Blades of the Guardians: Wind Rises In the Desert', 'https://phimimg.com/upload/vod/20260701-1/b76615c234fb052b15e4229e809c962f.jpg', 'https://phimimg.com/upload/vod/20260701-1/b86406f3d161bec49c43fa45b3197662.jpg', '<p>Trên sa mạc mênh mông, tiêu sư, quan phủ cùng năm đại gia tộc Tây Vực đan xen lợi ích, âm thầm tranh đấu. Đao Mã – kẻ bị truy nã hạng hai thiên hạ – nhận một nhiệm vụ áp tiêu đặc biệt, cùng đồng đội hộ tống một người từ Tây Vực đến Trường An. Không ngờ, người họ bảo vệ lại chính là Tri Thế Lang – kẻ bị truy nã số một thiên hạ. Vì lợi ích riêng, các thế lực liên tiếp nhập cuộc, kéo theo những trận tranh đoạt tiêu hàng và chém giết không ngừng.</p>', 'Full', 1, 'single', 'completed', 50, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wu Jing","avatar":""},{"name":"Nicholas Tse Ting-Fung","avatar":""},{"name":"Chen Lijun","avatar":""},{"name":"Yu Shi","avatar":""},{"name":"Sun Yizhou","avatar":""},{"name":"Li Yunxiao","avatar":""},{"name":"Ju Qianlang","avatar":""},{"name":"Ci Sha","avatar":""},{"name":"Tony Leung Ka-fai","avatar":""},{"name":"Max Zhang","avatar":""},{"name":"Jet Li","avatar":""},{"name":"Kara Hui Ying-Hung","avatar":""},{"name":"Zhang Yi","avatar":""},{"name":"Liu Yaowen","avatar":""},{"name":"Xiong Jinyi","avatar":""},{"name":"Bai Narisu","avatar":""},{"name":"Liang Biying","avatar":""},{"name":"Jun","avatar":""},{"name":"Winwin","avatar":""},{"name":"Lin Qiunan","avatar":""},{"name":"Jing Ci","avatar":""},{"name":"Zhan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["镖人电影版","镖人：风起大漠","Biao Ren","Остриетата на пазителите","Blades of the Guardians: Wind Rises in the Desert","Biao ren: Feng qi da mo"]', 1784690324118);
