INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-ca-ban-sao-cung-biet-yeu', 'Kể Cả Bản Sao Cũng Biết Yêu', 'Even A Replica Can Fall In Love', 'https://phimimg.com/upload/vod/20260420-1/db5888e4993b3d623f019c49f44ba3f7.jpg', 'https://phimimg.com/upload/vod/20260420-1/eef10bc3a1c236abe1c0d113d9af2cc4.jpg', '<p>Nao là một bản sao được tạo ra để trở thành &quot;hình nhân thế thân&quot; hoàn hảo cho Sunao Aikawa, chuyên thay thế Sunao mỗi khi cô nàng trốn học. Nao đi học, chơi thể thao và sống mỗi ngày chỉ vì bản chính—cho đến một ngày, cô nảy sinh tình cảm với một chàng trai. Đột nhiên, cuộc đời lặng lẽ mượn tạm của Nao bừng sáng với những buổi hẹn hò bí mật và những lời hứa thẹn thùng. Thế nhưng, Nao càng trân trọng những khoảnh khắc ấy bao nhiêu thì cô càng phải che giấu kỹ bấy nhiêu trước Sunao, người đang bắt đầu nhận ra những thay đổi lạ thường ở bản sao của mình.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 21, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Sumire Morohoshi","avatar":""},{"name":"Ryota Suzuki","avatar":""},{"name":"Yuuki Takada","avatar":""},{"name":"Kaori Nazuka","avatar":""},{"name":"Jun Fukuyama","avatar":""},{"name":"Rina Hidaka","avatar":""},{"name":"Shugo Nakamura","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["レプリコ","Repurika Datte, Koi o Suru.","Repurika Datte, Koi wo Suru.","Replica Datte, Koi wo Suru.","Replica Datte, Koi o Suru.","Even a Replica Falls in Love","レプリカだって、恋をする。"]', 1784690324118);
