INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-du-tu-luyen-nguc', 'Quỷ Dữ Từ Luyện Ngục', 'King Kaew', 'https://phimimg.com/upload/vod/20260701-1/ddb253f98f8651ff266be5963ee29dd7.jpg', 'https://phimimg.com/upload/vod/20260701-1/24e1fc5d036c26320f14d4851fee6318.jpg', '<p>Kingkaew lấy cảm hứng từ vụ án có thật năm 1978, tại nhà tù Bang Kwang khét tiếng. Một người phụ nữ mắc bệnh tâm thần bị buộc tội bắt cóc và sát hại trẻ em gây chấn động. Dù chứng cứ dồn dập, cô vẫn khẳng định “Tôi vô tội”. Cuối cùng, tòa tuyên án tử hình, Kingkaew chết trong oán hận tột cùng. Sau cái chết, hàng loạt hiện tượng kinh hoàng bắt đầu xảy ra. Oan hồn Kingkaew quay lại, gieo rắc nỗi ám ảnh lên tất cả những người liên quan. Khi nỗi sợ dâng cao, họ buộc phải đối mặt với sự thật đen tối phía sau vụ án… và thứ tà ác vẫn chưa chịu ngủ yên.</p>', 'Full', 1, 'single', 'completed', 71, 2026, 'Vietsub', 'FHD', 'Thái Lan', 1, '[{"name":"Intira Jaroenpura","avatar":""},{"name":"Apinya Sakuljaroensuk","avatar":""},{"name":"Napat Injaieua","avatar":""},{"name":"Pympan Chalayanacupt","avatar":""},{"name":"Ekkachai Srivichai","avatar":""},{"name":"Thanetpiphat Sutthihirandamrong","avatar":""},{"name":"Phakeeya Phongern","avatar":""},{"name":"Sonthaya Chitmanee","avatar":""},{"name":"Kapon Thongphlap","avatar":""},{"name":"Thanaphat Imkiat","avatar":""},{"name":"Chakrit Pongwang","avatar":""},{"name":"Montree Pothong","avatar":""},{"name":"Supachai Nak","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Kingkaew","King Keaw","Quỷ Dữ Từ Luyện Ngục","The Devil''s Justice","กิ่งแก้ว"]', 17