INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luc-do-toi-chuyen-sinh-thanh-slime-nuoc-mat-dai-duong', 'Lúc Đó Tôi Chuyển Sinh Thành Slime: Nước Mắt Đại Dương', 'That Time I Got Reincarnated as a Slime the Movie: Tears of the Azure Sea', 'https://phimimg.com/upload/vod/20260701-1/4d884724364e234134e8911a47838142.jpg', 'https://phimimg.com/upload/vod/20260701-1/1faace394727a8548def2edc00a890c6.jpg', '<p>Cốt truyện diễn ra sau lễ hội khai quốc tại Tempest. Rimuru và bạn bè nhận lời mời từ Nữ hoàng Ermesia của Sarion để đến nghỉ dưỡng tại một hòn đảo riêng tư, nhưng sau đó bị cuốn vào một biến cố lớn liên quan đến cô gái bí ẩn tên Yura và những bí mật dưới đáy đại dương.</p>', 'Full', 1, 'hoathinh', 'completed', 25, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Miho Okasaki","avatar":""},{"name":"Mao Ichimichi","avatar":""},{"name":"Tomoaki Maeno","avatar":""},{"name":"Makoto Furukawa","avatar":""},{"name":"Sayaka Senbongi","avatar":""},{"name":"Hisako Kanemoto","avatar":""},{"name":"Koichi Domoto","avatar":""},{"name":"Saori Onishi","avatar":""},{"name":"Koji Yusa","avatar":""},{"name":"Takuya Eguchi","avatar":""},{"name":"Anzu Haruno","avatar":""},{"name":"Rina Hidaka","avatar":""},{"name":"Ayako Kawasumi","avatar":""},{"name":"Chikahiro Kobayashi","avatar":""},{"name":"Akane Kumada","avatar":""},{"name":"Lynn","avatar":""},{"name":"Manami Numakura","avatar":""},{"name":"Sayak","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["TenSura Movie 2","Tensei Shitara Slime Datta Ken: Soukai no Namida-hen","Tensei Shitara Slime Datta Ken Movie 2: Soukai no Namida-hen","That Time I Got Reincarnated as a Slime the Movie: Tears of the Blue Sea","Gekijouban Tensei Shitara Slime Datta Ken: Soukai no Namida-hen","That Time I Got Reincarnated as a Slime: Tears of the Azure Sea","Lúc Đó Tôi Chuyển Sinh Thành Slime: Nước Mắt Đại Dương","That Time I Got Reincarnated as a Slime Tears of the Azure Sea","Meine Wiedergeburt als Schleim in einer anderen Welt - Die Tränen des azurblauen Meeres","劇場版 転生したらスライムだった件 蒼海の涙編"]', 1784690324118);
