INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ban-gai-thue-phan-5', 'Bạn Gái Thuê (Phần 5)', 'Rent-A-Girlfriend (Season 5)', 'bạn gái thuê (phần 5) rent-a-girlfriend (season 5) shun horie sora amamiya aoi yuuki nao toyama rie takahashi yu serizawa yukari nozawa sayuri sadaoka masayuki akasaka gakuto kajiwara 租借女友 किराए पर प्रेमिका kano kari kanojo, okarishimasu kanojo, okarishimasu 2 kanokari 2 彼女、お借りします rental girlfriend the animation kanojo okarishimasu una novia de alquiler девушка напрокат девушка на час девушка в аренду สะดุดรักยัยแฟนเช่า i''d like to borrow a girlfriend rental girlfriend rental girlfriend 2 rent-a-girlfriend dịch vụ thuê bạn gái bạn gái, tôi thuê cô', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-khong-bi-ngan', 'Thâm Không Bỉ Ngạn', 'The Other Side Of Deep Space', 'https://phimimg.com/upload/vod/20260117-1/244d10537faac8dd7541481eea14976e.jpg', 'https://phimimg.com/upload/vod/20260117-1/0c3f5d7611c746ebb64b5b778feb4d0a.jpg', '<p>Tân thuật tôn sùng việc tu tiên bằng khoa học kỹ thuật trỗi dậy, trong khi Cựu thuật tu chân đã được lưu truyền ngàn năm lại dần dần suy tàn. Vương Huyên, một thiếu niên thiên tài của Cựu thuật, đã vô tình gia nhập tổ chức bí ẩn Mật Lộ. Trong một loạt các cuộc phiêu lưu mạo hiểm và kịch tính, từ việc đoạt chí bảo, chiến đấu với Tân thuật, đến đối đầu với các Liệt Tiên, cậu đã khám phá ra bí mật to lớn được ẩn giấu của Cựu thuật. Để đối phó với một cuộc khủng hoảng khổng lồ sắp ập đến, Vương Huyên đã không ngần ngại tiến sâu vào vũ trụ, thách thức giới hạn trưởng thành của bản thân.</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 18, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shen Kong Bi An","Shen Kong Bi''An","The Other Side of Deep Space","First Frost","Endless Devotion","深空彼岸"]', 1784690324118);
