INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-phu-thuy', 'Nam Phù Thủy', 'WU', 'https://phimimg.com/upload/vod/20260506-1/07bbce9a6b0e8f159f13ef2e42cf3252.jpg', 'https://phimimg.com/upload/vod/20260506-1/94c1e5ae93ccfd42ab8c76af91416256.jpg', '<p>Một chàng trai trẻ mang trong mình mảnh linh hồn của quỷ dữ đã bắt tay cùng một đồng minh bí ẩn để săn lùng những thực thể siêu nhiên chuyên hút sinh lực của con người. Giữa cuộc chiến khốc liệt với bóng tối, anh vừa phải tìm cách kiểm soát sức mạnh tà ác đang dần trỗi dậy trong chính cơ thể mình, vừa phải bảo vệ nhân loại khỏi những hiểm họa vô hình đang rình rập.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 25, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Wongravee Nateetorn","avatar":""},{"name":"Hirunkit Changkham","avatar":""},{"name":"Tachakorn Boonlupyanun","avatar":""},{"name":"Sapol Assawamunkong","avatar":""},{"name":"Singha Luangsuntorn","avatar":""},{"name":"Kanthee Limpitikranon","avatar":""},{"name":"Tiranat Kittisattho","avatar":""},{"name":"Chayuth Gorsurat","avatar":""},{"name":"Perawat Sangpotirat","avatar":""},{"name":"Chompoopuntip Temtanamongkol","avatar":""},{"name":"Palang Rocksilp","avatar":""},{"name":"Phuwin Tangsakyuen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wu","WU อู"]', 1784690324118);
