INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-hien', 'Tận Hiến', 'Dedication', 'https://phimimg.com/upload/vod/20260513-1/3048bddd30fbd3f3bc95cb636d67efee.jpg', 'https://phimimg.com/upload/vod/20260513-1/51f724508514799548dfaace58be692f.jpg', '<p>Trong giai đoạn chính trị phức tạp ở khu vực Đông Dương thập niên 60 thế kỷ trước, người đàn ông mang bí danh P1 được Bộ Công an Việt Nam giao nhiệm vụ thâm nhập vào hàng ngũ đối phương trên đất Lào. Anh đã phải đánh cược sự an toàn không chỉ của bản thân mà cả gia đình để thực thi sứ mệnh thiêng liêng với Tổ quốc. Bộ phim nhằm tôn vinh sự hy sinh thầm lặng của những chiến sĩ tình báo thuộc lực lượng CAND trên đất Lào từ 1957 đến 1977, với lý tưởng và sự tận hiến, kiên trung, tuyệt đối trung thành với đất nước.</p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 38, 2026, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Hứa Vĩ Văn","avatar":""},{"name":"Ho Phong","avatar":""},{"name":"Ngọc Thanh Tâm","avatar":""},{"name":"Phương Nam","avatar":""},{"name":"Đàm Hằng","avatar":""},{"name":"Trung Anh","avatar":""},{"name":"Hoàng Ka Tê","avatar":""},{"name":"Quốc Quân","avatar":""},{"name":"Hoàng Du Ka","avatar":""},{"name":"Ngọc Yến","avatar":""},{"name":"Cami Lam Anh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Tận Hiến"]', 1784690324118);
