INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tan-hien', 'Tận Hiến', 'Dedication', 'tận hiến dedication hứa vĩ văn ho phong ngọc thanh tâm phương nam đàm hằng trung anh hoàng ka tê quốc quân hoàng du ka ngọc yến cami lam anh tận hiến', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-cua-nhung-loi-doi-tra', 'Ngôi Nhà Của Những Lời Dối Trá', 'The Lie We Lived In', 'https://phimimg.com/upload/vod/20260606-1/3d42c9f0351cf731faa71f3979d50cf4.jpg', 'https://phimimg.com/upload/vod/20260606-1/149b3de70031b4a373a224e59f46ca2b.jpg', '<p>Seo I-do, một sát thủ chuyên nghiệp, được giao nhiệm vụ thủ tiêu Heo Dong-hwa tại một căn nhà biệt lập. Tuy nhiên, trước khi hoàn thành nhiệm vụ, anh bất ngờ nhận lệnh phải giữ Dong-hwa sống và giam giữ anh ta thay vì giết chết. Mọi chuyện trở nên phức tạp khi Chu Tae-jeong xuất hiện. Tae-jeong là bạn cũ của Dong-hwa và vô tình nhầm I-do là em trai của Dong-hwa. Để che giấu thân phận thật, I-do tiếp tục sống trong lời nói dối đó. Nhưng anh sớm phát hiện Tae-jeong thực chất là một cảnh sát đang điều tra những bí mật xoay quanh căn nhà và những người trong đó. Trong khi cố giữ bí mật về thân phận sát thủ của mình, I-do dần nảy sinh tình cảm với Tae-jeong. Tình yêu ngày càng lớn khiến anh phải lựa chọn giữa hoàn thành nhiệm vụ và bảo vệ người mình yêu. Khi những bí mật trong quá khứ lần lượt bị phơi bày, tất cả đều phải đối mặt với sự thật đằng sau &quot;ngôi nhà nơi những lời dối trá sinh sống&quot;.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 35, 2026, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Seung-beom","avatar":""},{"name":"Kim Kyung-min","avatar":""},{"name":"Lee Jung-ho","avatar":""},{"name":"Lee Seung-noh","avatar":""},{"name":"Donghyun Baek","avatar":""},{"name":"Takuya Terada","avatar":""},{"name":"Im Jeong-gyu","avatar":""},{"name":"Lee Jae-jun","avatar":""},{"name":"Ju Jeong-hyeon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["杀人屋","杀戮之家","杀戮屋","谎言居住的家","谎言之屋","킬링 하우스","킬링하우스","Killing House","거짓말이 사는 집"]', 1784690324118);
