INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngoi-nha-cua-nhung-loi-doi-tra', 'Ngôi Nhà Của Những Lời Dối Trá', 'The Lie We Lived In', 'ngôi nhà của những lời dối trá the lie we lived in kim seung-beom kim kyung-min lee jung-ho lee seung-noh donghyun baek takuya terada im jeong-gyu lee jae-jun ju jeong-hyeon 杀人屋 杀戮之家 杀戮屋 谎言居住的家 谎言之屋 킬링 하우스 킬링하우스 killing house 거짓말이 사는 집', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-than-internet', 'Thiên Thần Internet', 'Needy Girl Overdose', 'https://phimimg.com/upload/vod/20260410-1/8ad8e28bef9ff742d59d36fb0061bd5c.jpg', 'https://phimimg.com/upload/vod/20260410-1/bea5e2c63c294d8536e1da3350df60a2.jpg', '<p>Trong một thế giới nơi lượt &quot;thích&quot; là tiền tệ và mỗi người xem đều là một thẩm phán, OMGkawaiiAngel — hay còn được biết đến với cái tên KAngel — hạ quyết tâm trở thành &quot;Thiên sứ Internet&quot; tối thượng. Tuy nhiên, ẩn sau nụ cười màu pastel kẹo ngọt và những buổi phát trực tiếp đầy năng lượng, mọi chuyện không hề đơn giản như những gì người ta nhìn thấy. Để duy trì ánh hào quang ảo, cô phải đối mặt với áp lực tâm lý nặng nề, sự mong manh của danh vọng và những góc khuất đầy bất ổn trong cuộc sống thực tại.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 19, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Rina Kawaguchi","avatar":""},{"name":"Satsuki Shiina","avatar":""},{"name":"Seena Hoshiki","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["ニーディガール オーバードーズ","NEEDY GIRL OVERDOSE"]', 1784690324118);
