INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mac-ly', 'Mạc Ly', 'The First Jasmine', 'https://phimimg.com/upload/vod/20260609-1/089ebc9ac027d516a2885aaee749d354.jpg', 'https://phimimg.com/upload/vod/20260609-1/ae12c9e970982d4ce4c70e9633b5d2cc.jpg', '<p>Trưởng nữ Diệp Ly của Diệp Phủ được gả sang Định Vương Phủ suy tàn, 
thành thân với kẻ tàn tật hai chân là Định Vương Mặc Tu Nghiêu. Ngày 
Diệp Ly xuất giá, Lê Vương Mặc Cảnh Lê cũng thành thân với thứ nữ Diệp 
Phủ là Diệp Oánh. Là hậu duệ Ly Sơn, Diệp Ly từng bị nhốt trong núi 8 
năm. Sau khi thành thân, bề ngoài nàng tỏ ra an phận, nhưng thực chất 
lại âm thầm lên kế hoạch loại bỏ từng kẻ từng hãm hại Ly Sơn năm xưa. 
Trong quá trình ấy, nàng vấp phải sự nghi ngờ của Mặc Tu Nghiêu, người 
cũng đang nuôi chí báo thù. Hai người mỗi bên đều âm thầm hành động, 
khiến mặt hồ tưởng chừng bình lặng dậy sóng. Mặc Cảnh Lê vốn là thanh 
mai trúc mã của Diệp Ly, mang tiếng là một &quot;Vương gia mê hí khúc&quot;, hắn 
lại âm thầm thao túng thế cuộc, nung nấu dã tâm đoạt ngôi. Cuối cùng, 
Diệp Ly và Mặc Tu Nghiêu liên thủ phò tá tiểu hoàng đế chấp chính, liên 
tiếp phá tan âm mưu của Mộc Dương Hầu và Lê Vương, mang lại cảnh thái 
bình cho thiên hạ.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 110, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Bạch Lộc","avatar":""},{"name":"Thừa Lỗi","avatar":""},{"name":"Thái Chính Kiệt","avatar":""},{"name":"Dương Thư Y","avatar":""},{"name":"Lâm Mộc Nhiên","avatar":""},{"name":"Đổng Khiết","avatar":""},{"name":"Yann","avatar":""},{"name":"Trương Nguyệt","avatar":""},{"name":"Lưu Kình","avatar":""},{"name":"Khưu Tâm Chí","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mo Li","盛世嫡妃","The First Jasmine","莫离"]', 1784690324118);
