INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-len-nao-nakamura', 'Cố Lên Nào, Nakamura!', 'Go For It, Nakamura-kun!!', 'https://phimimg.com/upload/vod/20260404-1/adfa1fd8b6e66dd8dfe8792720b1d033.jpg', 'https://phimimg.com/upload/vod/20260404-1/466af76915c255d72728f682c9471120.jpg', '<p>Nakamura là một cậu học sinh trung học nhút nhát, đã đem lòng thầm thương trộm nhớ cậu bạn cùng lớp Hirose ngay từ cái nhìn đầu tiên. Trớ trêu thay, dù học chung lớp nhưng cả hai vẫn chưa một lần trò chuyện với nhau. Liệu những nỗ lực vụng về, ngây ngô của Nakamura chỉ để thốt ra một lời chào &quot;Xin chào&quot; đơn giản có thể giúp cậu mở lòng và tạo nên một mối kết nối thực sự với người trong mộng? Một câu chuyện ngọt ngào và dở khóc dở cười về sự dũng cảm của tình yêu tuổi học trò.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 22, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Chiaki Kobayashi","avatar":""},{"name":"Yuki Sakakihara","avatar":""},{"name":"Fairouz Ai","avatar":""},{"name":"Takuya Eguchi","avatar":""},{"name":"Tsubasa Sasa","avatar":""},{"name":"Yukihiro Nozuyama","avatar":""},{"name":"Atsushi Tamaru","avatar":""},{"name":"Yume Maihara","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Força, Nakamura!!","加油吧！中村君！！","加油吧！中村君!!","加油！中村同学！！","Adelante, Nakamura-kun!!","Ganbare! Nakamura-kun!!","Go for It, Nakamura-kun!!","ガンバレ！中村くん！！"]', 1784690324118);
