INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buc-tuong-bang', 'Bức Tường Băng', 'The Ramparts Of Ice', 'https://phimimg.com/upload/vod/20260404-1/e1b14c45500af93e16f521d03f92f071.jpg', 'https://phimimg.com/upload/vod/20260404-1/26f579bccac331f2d8f665e7f351f741.jpg', '<p>Koyuki chật vật trong việc kết nối với mọi người và chấp nhận sống những năm tháng trung học cô độc – và rồi Minato xuất hiện, quyết tâm làm tan lớp băng bao quanh cô.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 23, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Anna Nagase","avatar":""},{"name":"Shoya Chiba","avatar":""},{"name":"Fuka Izumi","avatar":""},{"name":"Satoshi Inomata","avatar":""},{"name":"Chiaki Kobayashi","avatar":""},{"name":"Sakura Shinfuku","avatar":""},{"name":"Akari Kito","avatar":""},{"name":"Kakeru Hatano","avatar":""},{"name":"Natsumi Kawaida","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["こおりのじょうへき","Kōri no Jyōheki","Koori no Jyōheki","Koori no Jouheki","Koori no Jyouheki","Ice Castle Wall","氷の城壁"]', 1784690324118);
