INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('buc-tuong-bang', 'Bức Tường Băng', 'The Ramparts Of Ice', 'bức tường băng the ramparts of ice anna nagase shoya chiba fuka izumi satoshi inomata chiaki kobayashi sakura shinfuku akari kito kakeru hatano natsumi kawaida こおりのじょうへき kōri no jyōheki koori no jyōheki koori no jouheki koori no jyouheki ice castle wall 氷の城壁', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nippon-sangoku', 'Nippon Sangoku', 'NIPPON SANGOKU: The Three Nations of the Crimson Sun', 'https://phimimg.com/upload/vod/20260414-1/996d72798f08b5b60d89f921e266a9db.jpg', 'https://phimimg.com/upload/vod/20260414-1/2311134382d7fb112d72d7245c518308.jpg', '<p>Một cuộc cách mạng bùng nổ do chiến tranh hạt nhân, thiên tai và sự cai trị tồi tệ đã dẫn đến sự sụp đổ của xã hội Nhật Bản. Quốc gia này bị chia cắt thành ba nước nhỏ luôn tranh giành quyền bá chủ, và kỷ nguyên Sangoku (Tam Quốc) bắt đầu. Aoteru Misumi, một cựu quan chức nông nghiệp, đã thề sẽ tái thống nhất Nhật Bản. Chỉ với tri thức và tài hùng biện của mình, anh dần thăng tiến qua các cấp bậc trong quân đội và chính trường. Hãy cùng chứng kiến huyền thoại về người đàn ông mà sau này được ca tụng là một chiến lược gia thiên tài.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 28, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kensho Ono","avatar":""},{"name":"Jun Fukuyama","avatar":""},{"name":"Takashi Nagasako","avatar":""},{"name":"Asami Seto","avatar":""},{"name":"Megumi Han","avatar":""},{"name":"Kazuhiro Yamaji","avatar":""},{"name":"Yuichi Nakamura","avatar":""},{"name":"Taihi Kimura","avatar":""},{"name":"Minami Tsuda","avatar":""},{"name":"Kenyu Horiuchi","avatar":""},{"name":"Shuichiro Umeda","avatar":""},{"name":"Shunsuke Sakuya","avatar":""},{"name":"Ayumu Murase","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Nippon Sangoku","Nippon Sangoku: Las tres naciones del sol carmesí","نيبون سانغوكو: عصر الممالك الثلاث","عصر الممالك الثلاث","日本三國"]', 1784690324118);
