INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-silom', 'Chuyện Tình Silom', 'Love Of Silom', 'https://phimimg.com/upload/vod/20260428-1/3dc85f5a14c2f7ad5a06c1a837c14dfb.jpg', 'https://phimimg.com/upload/vod/20260428-1/2addc27160eb0c215cf6de244a763823.jpg', '<p>Một viên cảnh sát đang mang trong mình trái tim tan vỡ và phải che giấu một mối tình ngang trái, bất ngờ tìm thấy cơ hội thứ hai trong tình yêu khi anh giải cứu một cậu sinh viên đang gặp rắc rối tại một hộp đêm ở Silom. Giữa ánh đèn mờ ảo và nhịp sống hối hả của khu phố không ngủ, cuộc gặp gỡ định mệnh này đã gắn kết hai tâm hồn đang tổn thương, giúp họ cùng nhau vượt qua những định kiến và rào cản để đi tìm hạnh phúc thực sự.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 31, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Poompat Iam-samang","avatar":""},{"name":"Phuripan Sapsangsawat","avatar":""},{"name":"Talay Sanguandikul","avatar":""},{"name":"Yanissa Diratorn","avatar":""},{"name":"Supakit Phuengpradach","avatar":""},{"name":"Siravitch Kamonworawut","avatar":""},{"name":"Chanakan Poonsiriwong","avatar":""},{"name":"Perawitch Chotimanon","avatar":""},{"name":"Intouch Kooramasuwan","avatar":""},{"name":"Tanapon Hathaidachadusadee","avatar":""},{"name":"Phollawat Manuprasert","avatar":""},{"name":"Wacharin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["รักแห่งสีลม"]', 1784690324118);
