INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-ac-mong-hoi-chuong-la-phan-4', 'Thị Trấn Ác Mộng (Hồi Chuông Lạ) (Phần 4)', 'FROM (Season 4)', 'https://phimimg.com/upload/vod/20260423-1/072edb466660a2d84553a19c93f8c33c.jpg', 'https://phimimg.com/upload/vod/20260423-1/95cb687835c1321b9ebc17330ecbd20d.jpg', '<p>Làm sáng tỏ bí ẩn về một thành phố ở Trung Mỹ giam giữ tất cả những ai bước vào. Khi các cư dân đấu tranh để trở &nbsp;lại bình thường và tìm kiếm một lối thoát, họ cũng phải sống sót trước các mối đe dọa của khu rừng xung quanh.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 58, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Harold Perrineau","avatar":""},{"name":"Catalina Sandino Moreno","avatar":""},{"name":"Eion Bailey","avatar":""},{"name":"Pegah Ghafoori","avatar":""},{"name":"Hannah Cheramy","avatar":""},{"name":"Simon Webster","avatar":""},{"name":"Elizabeth Moy","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["梦魇绝镇","Origen","מבחוץ","המקום","منشا","از سوی","フロム 閉ざされた街","مِنْ","بلدة الضياع","FROM"]', 1784690324118);
