INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-thang-ruc-lua', 'Năm Tháng Rực Lửa', 'The Age Of Fire', 'https://phimimg.com/upload/vod/20260616-1/65079fd9391072eba72a32b52cf3ce9e.jpg', 'https://phimimg.com/upload/vod/20260616-1/c98478c0cd0d248bb00d070899d3d11c.jpg', '<p>Chu Triều Dương, một kỹ thuật viên massage chân và là con trai của một phạm nhân cải tạo lao động, bất ngờ xuyên không từ năm 2025 về năm 1997, nhập vào thân xác của cha mình là Chu Nghĩa Hải. Mang theo tư duy hiện đại, Chu Nghĩa Hải liên tiếp vượt qua khó khăn, dẫn dắt anh em gây dựng sự nghiệp và làm giàu. Đồng thời, anh từng bước vạch trần, đập tan âm mưu của tên ác bá địa phương Long Tiếu, từ đó nghịch thiên cải mệnh, viết lại số phận của chính mình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 32, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Xuyên Bắc","avatar":""},{"name":"Diêm Giai Dĩnh","avatar":""},{"name":"Lưu Giai Manh","avatar":""},{"name":"Lưu Giả Tỷ","avatar":""},{"name":"Khám Tử Nghĩa","avatar":""},{"name":"Chu Thụy","avatar":""},{"name":"Trần Lâm Sinh","avatar":""},{"name":"Kim Khải Kiệt","avatar":""},{"name":"Vương Ninh","avatar":""},{"name":"Triệu Dĩnh Thi","avatar":""},{"name":"Vương Tích Nhiễm","avatar":""},{"name":"Vu Thủy Ca","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["似火年华"]', 1784690324118);
