INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nam-thang-ruc-lua', 'Năm Tháng Rực Lửa', 'The Age Of Fire', 'năm tháng rực lửa the age of fire dương xuyên bắc diêm giai dĩnh lưu giai manh lưu giả tỷ khám tử nghĩa chu thụy trần lâm sinh kim khải kiệt vương ninh triệu dĩnh thi vương tích nhiễm vu thủy ca 似火年华', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-si-can-ba', 'Dũng Sĩ Cặn Bã', 'Scum Of The Brave', 'https://phimimg.com/upload/vod/20260114-1/353e77efcf6edac484eaa86408e670a2.jpg', 'https://phimimg.com/upload/vod/20260114-1/c3395990c9bbb381c756590cc125d881.jpg', '<p>Vào giữa thế kỷ 21, thế giới ngầm Tokyo bị thống trị bởi những tên Mafia đã biến thành “Ma Vương” nhờ vào các cuộc phẫu thuật cường hóa Ether.

Những thợ săn tiền thưởng chuyên tiêu diệt đám Ma Vương này… chính là các Dũng sĩ.

Các Dũng sĩ sử dụng một loại thuốc gọi là “E3” để cường hóa năng lực Ether nhằm chống lại Ma Vương. Hành vi giết chóc của họ được hợp pháp hóa, biến Dũng sĩ trở thành một nghề nghiệp “sát nhân”.

Trong bối cảnh đó, một nữ sinh trung học tự xưng là “đệ tử” bất ngờ ập đến chỗ của Yashiro – một Dũng sĩ tự do với biệt danh “Tử Thần”. Cô bé ấy là Jougamine, một thực tập sinh Dũng sĩ. Mặc dù miễn cưỡng chấp nhận cô bé, Yashiro lại bị cuốn vào những vụ rắc rối chẳng ra đâu vào đâu!

Một “Sư phụ” cặn bã và một “Đệ tử” tự xưng. Tấm màn của bộ phim hành động dị năng thời hiện đại với cấp độ siêu khủng bắt đầu được vén lên!</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 20, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ryota Suzuki","avatar":""},{"name":"Akari Kito","avatar":""},{"name":"Momo Harumi","avatar":""},{"name":"Yumiri Hanamori","avatar":""},{"name":"Hinata Tadokoro","avatar":""},{"name":"Daisuke Hirakawa","avatar":""},{"name":"Yasuhiro Takato","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["बहादुरों का मैल","Yuusha no Kuzu","Yūsha no Kuzu","Scum of the Brave","勇者のクズ"]', 1784690324118);
