INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-duoc-chua', 'Yêu Được Chưa', 'Let''s Begin Again', 'https://phimimg.com/upload/vod/20260428-1/4662191e6d221754a7a3d4c62e1d7742.jpg', 'https://phimimg.com/upload/vod/20260428-1/d563a77898b12886e0cc5eea272f1745.jpg', '<p>Sau khi bị mối tình đầu phản bội, Wayruree luôn phải vật lộn với nỗi đau và không còn niềm tin vào tình yêu. Mọi thứ bắt đầu thay đổi khi cô gặp Mr. TJ — người đã dẫn dắt cô trên hành trình trưởng thành và dạy cô hiểu được ý nghĩa thực sự của tình yêu. Nhờ sự chân thành của anh, Wayruree dần chữa lành những vết thương lòng và một lần nữa mở rộng trái tim để đón nhận hạnh phúc.</p>', 'Hoàn Tất (19/19)', 19, 'series', 'completed', 28, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Pichukkana Wongsarattanasin","avatar":""},{"name":"Chutavuth Pattarakampol","avatar":""},{"name":"Parisaya Jaronetisat","avatar":""},{"name":"Khwanruedi Klomklom","avatar":""},{"name":"Thakrit Tawanpong","avatar":""},{"name":"Kanyaphak Pongsak","avatar":""},{"name":"Rudklao Amratisha","avatar":""},{"name":"Chattarika Sittiprom","avatar":""},{"name":"Sittawasilp Kabilchonlathit","avatar":""},{"name":"Lorena Schuett","avatar":""},{"name":"Jacqueline Muench","avatar":""},{"name":"Tarika Insuwan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Rak Dai Rue Young","รักได้หรือ Young"]', 1784690324118);
