INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-gia-bon-mua-vu-dieu-mua-xuan', 'Sứ Giả Bốn Mùa: Vũ Điệu Mùa Xuân', 'Agents Of The Four Seasons: Dance Of Spring', 'https://phimimg.com/upload/vod/20260403-1/f74b91913b26df1bc3c22176c7a57f18.jpg', 'https://phimimg.com/upload/vod/20260403-1/a095ce2e1bf08a7fe7af81c0f26bfb53.jpg', '<p>“Mùa Xuân đã thuận lợi đến nơi đây.” Mùa Đông là mùa duy nhất tồn tại trên thế giới, nhưng vì không chịu nổi cô đơn, nó đã tự cắt sinh mệnh của mình để tạo ra Mùa Xuân. Để đáp ứng mong muốn của trái đất, nó lại sinh ra đời Mùa Hè và Mùa Thu, thế là thế giới có bốn mùa. Về sau, con người gánh vác trách nhiệm duy trì sự luân chuyển của các mùa, và sứ mệnh ấy được trao cho những người được gọi là “Sứ giả của Bốn Mùa&quot;. Hiện tại, một nữ thần trẻ mang trong mình ý thức sứ mệnh mạnh mẽ đang chuẩn bị đứng ra gánh vác trọng trách. Mùa mà Thần của bốn mùa ban cho cô ấy là “Mùa Xuân”, cái tên mẹ đặt cho cô là Kayou, cô ấy chính là Thần Mùa Xuân mất tích cách đây mười năm của quốc gia này. Cô ấy đã vượt qua những tháng năm khổ đau, trở lại là &quot;vị thần sống&quot; hiện tại. Để đối đầu với kẻ đã bắt cóc và khiến cô chịu nhục nhã suốt mười năm, cô cùng người hầu của mình chuẩn bị tiến bước bước đi đầu tiên.</p>', 'Hoàn Tất (14/14)', 14, 'hoathinh', 'completed', 25, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuka Nukui","avatar":""},{"name":"Yoshino Aoyama","avatar":""},{"name":"Sumire Uesaka","avatar":""},{"name":"Ranko Baba","avatar":""},{"name":"Hime Sawada","avatar":""},{"name":"Taku Yashiro","avatar":""},{"name":"Shogo Sakata","avatar":""},{"name":"Satoshi Hino","avatar":""},{"name":"Kana Hanazawa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shunkashūtō Daikōsha","Shunkashūtō Daikōsha: Haru no Mai","Shunkashuutou Daikousha","Shunkashuutou Daikousha: Haru no Mai","Agents of the Four Seasons","春夏秋冬代行者 春の舞"]', 1784690324118);
