INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('goi-dad-di-tharn', 'Gọi Dad Đi Tharn', 'Your Dear Daddy', 'https://phimimg.com/upload/vod/20260510-1/ee515474b3152374a0dc8d5aecba4794.jpg', 'https://phimimg.com/upload/vod/20260510-1/bb0d43ba1fea3723cfa7d3dd1cbf0095.jpg', '<p>Sau khi bị buộc rời khỏi nhà, Saitharn đến Chiang Rai để bắt đầu lại cuộc sống và tình cờ gặp Sila, người trở thành chỗ dựa giúp anh chữa lành cả thể xác lẫn tinh thần. Khi tình cảm giữa họ dần sâu đậm, Saitharn không chỉ khám phá những tổn thương ẩn giấu của Sila mà còn học được cách yêu thương, trưởng thành và bảo vệ người mình yêu.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 22, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Pusit Dittapisit","avatar":""},{"name":"Jitaboon Ngamboonyarak","avatar":""},{"name":"Ramita Kamiya","avatar":""},{"name":"Methakarn Anektanasuwan","avatar":""},{"name":"Phudis Kannaphan","avatar":""},{"name":"Defei Chan","avatar":""},{"name":"Setthanan Manunapichu","avatar":""},{"name":"Jakarin Puribhat","avatar":""},{"name":"Nisachon Tuamsoongnuen","avatar":""},{"name":"Namnung Suttidachanai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["เรียกแด๊ดสิธาร"]', 1784690324118);
