INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-hoa-luan-hoi', 'Cánh Hoa Luân Hồi', 'Petals Of Reincarnation', 'https://phimimg.com/upload/vod/20260404-1/fcf47b00f03e8c0c4b609351c7e80d21.jpg', 'https://phimimg.com/upload/vod/20260404-1/55f3192300e6d5d2168e3f4de7d1a048.jpg', '<p>Petals Of Reincarnation mở ra thế giới kỳ lạ, nơi một vật được gọi là Nhánh Luân Hồi, có thể đánh thức tài năng từ kiếp trước, nhưng phải trả giá bằng nỗi đau. Toya Senji là một nam sinh luôn tự ti, khao khát có được siêu năng lực để khẳng định bản thân. Cuộc đời cậu thay đổi khi gặp Haito Luo Buffett - người sở hữu sức mạnh của kiếm sĩ Miyamoto Musashi. Từ đó, Toya bước vào thế giới của những con người có thể triệu hồi tài năng tiền kiếp bằng cách sử dụng Cành Luân Hồi. Bị cuốn vào những trận chiến nguy hiểm, cậu buộc phải đối mặt với quá khứ và tìm ra giá trị thật của mình.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 27, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shoya Chiba","avatar":""},{"name":"Wakana Maruoka","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Haruka Shiraishi","avatar":""},{"name":"Kaito Ishikawa","avatar":""},{"name":"Reina Ueda","avatar":""},{"name":"Marina Inoue","avatar":""},{"name":"Shugo Nakamura","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["轮回的花瓣","Reincarnation no Kaben","Reincarnation no Hanabira","リィンカーネーションの花弁"]', 1784690324118);
