INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-vo-toi-la-mafia', 'Bố Vợ Tôi Là Mafia', 'Bapa Mentuaku Mafia', 'https://phimimg.com/upload/vod/20260530-1/b0b753ff71f8b4cb2feeafe00a55687a.jpg', 'https://phimimg.com/upload/vod/20260530-1/49f2ecff904434957696dc8a48d676e0.jpg', '<p>Một người đàn ông không chút nghi ngờ bỗng phải tẩy trắng hình ảnh cho một gia tộc tội phạm quyền lực sau khi bị ép cưới con gái của ông trùm.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 53, 2026, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Zahiril Adzim","avatar":""},{"name":"Siti Hariesa","avatar":""},{"name":"Sweta Sekhon","avatar":""},{"name":"Nafiez Zaidi","avatar":""},{"name":"Auni Yusri","avatar":""},{"name":"Abdul Razak Ahmad","avatar":""},{"name":"Aishah Atan","avatar":""},{"name":"Iskandar Norzaman","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bapa Mentuaku Mafia"]', 1784690324118);
