INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('snowball-earth-trai-dat-dong-bang', 'Snowball Earth: Trái Đất Đóng Băng', 'SNOWBALL EARTH', 'https://phimimg.com/upload/vod/20260407-1/6e869c254c26aa9b05c679a2a81aea68.jpg', 'https://phimimg.com/upload/vod/20260407-1/1d64a782edacee880b7ca8255d2b02dd.jpg', '<p>Một thiếu niên hướng nội, gặp khó khăn trong giao tiếp, nhưng lại được mọi người gọi là “cứu tinh”, điều khiển một robot khổng lồ có ý thức riêng, theo hạm đội vũ trụ rời Trái Đất, bước vào hành trình tiêu diệt quái vật trong dải ngân hà. Không ngờ, trong trận chiến cuối cùng, cậu lại vô tình thất bại. Ngay lúc đó, robot khổng lồ quyết định kích hoạt chế độ tự phát nổ, đồng thời dùng khoang thoát hiểm đưa cậu trở về Trái Đất. Thế nhưng, khi cậu an toàn trở lại, cảnh tượng trước mắt lại là một Trái Đất trắng xóa, đóng băng, không còn sự sống…</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 22, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Takuto Yoshinaga","avatar":""},{"name":"Daisuke Hirakawa","avatar":""},{"name":"Ami Koshimizu","avatar":""},{"name":"Konomi Tamura","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["SNOWBALL EARTH","スノウボールアース"]', 1784690324118);
