INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-giau-van-payak-raai-sorn-laai', 'Hổ Giấu Vằn (Payak Raai Sorn Laai)', 'Wicked Temptation', 'https://phimimg.com/upload/vod/20260516-1/491a74f039db3dc1ecf09fb0f715f57b.jpg', 'https://phimimg.com/upload/vod/20260516-1/77c1b40f3b62b6bbc79c5e1040b2340b.jpg', '<p>Sau khi người cha nuôi bị sát hại bởi tổ chức bí mật Phượng Hoàng Lửa, Taiga lên đường sang Thái Lan để tìm kiếm sự thật. Bằng cách thâm nhập vào một tập đoàn quyền lực có mối liên hệ mật thiết với thế giới ngầm tội phạm, anh ráo riết truy lùng tung tích của kẻ bí ẩn mang danh &quot;Ác Quỷ&quot;. Tại đây, Taiga liên tục đụng độ với Rin – một vệ sĩ luôn sống khép kín, người cũng mang trong mình mối thù sâu sắc liên quan đến cùng một âm mưu đen tối.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 22, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Panuwat Premmaneenan","avatar":""},{"name":"Matira Tantiprasut","avatar":""},{"name":"Kaliya Niehuns","avatar":""},{"name":"Chartayodom Hiranyatithi","avatar":""},{"name":"Rinlanee Sripen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Payak Raai Sorn Laai","Phayak Rai Son Lai","พยัคฆ์ร้ายซ่อนลาย"]', 1784690324118);
