INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dang-say-tua-doa-bach-hop-kamiina-botan', 'Dáng Say Tựa Đoá Bách Hợp (Kamiina Botan)', 'Botan Kamiina Fully Blossoms When Drunk', 'https://phimimg.com/upload/vod/20260413-1/684a284a51ef59ab2360576d80b9b273.jpg', 'https://phimimg.com/upload/vod/20260413-1/39c3c47e45a625051b19bf06e232c186.jpg', '<p>Câu chuyện xoay quanh Kamiina Botan, một cô sinh viên năm nhất 20 tuổi vừa bắt đầu cuộc sống tự lập tại ký túc xá. Tại đây, Botan đã gặp gỡ những người tiền bối cá tính và cùng họ xây dựng những tình bạn bền chặt thông qua những buổi “nhâm nhi” đầy thú vị.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 19, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Sayumi Suzushiro","avatar":""},{"name":"Yoshino Aoyama","avatar":""},{"name":"Minako Kotobuki","avatar":""},{"name":"Yurina Amami","avatar":""},{"name":"Miyu Tomita","avatar":""},{"name":"Maki Kawase","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["上伊那牡丹，醉姿如百合","上伊那牡丹，酒醉身姿似百合花般","上伊那牡丹，酩酊身姿似百合之花","Botan Kamiina, Her Drunken Appearance Is Like a Lily Flower","Kamiina Botan, Yoheru Sugata wa Yuri no Hana","Kamiina Botan, Yoeru Sugata wa Yuri no Hana","Kamiina Botan, the Drunken Appearance Is a Lily Flower","上伊那ぼたん、酔へる姿は百合の花"]', 1784690324118);
