INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-sinh-thanh-xuong-suon-cua-dung-si', 'Chuyển Sinh Thành Xương Sườn Của Dũng Sĩ', 'My Ribdiculous Reincarnation', 'https://phimimg.com/upload/vod/20260420-1/1e00b55b2c565774b0c608230682a429.jpg', 'https://phimimg.com/upload/vod/20260420-1/2c2cf03c6ca0da1a3c07ccef9ad9ca03.jpg', '<p>Câu chuyện xoay quanh một người đàn ông bị kẹt trong vòng luân hồi vô tận. Thay vì kiên nhẫn chờ đợi hàng thế kỷ để được đầu thai thành những anh hùng hay bậc vĩ nhân, anh ta quyết định &quot;đi tắt&quot; bằng cách tái sinh vào bất kỳ hình hài nào có sẵn, dù là kỳ quặc nhất. Từ một con ốc mượn hồn, một loại rau củ cho đến cả một khối thuốc nổ, anh dấn thân vào những cuộc phiêu lưu dở khóc dở cười. Với kinh nghiệm từ hàng ngàn kiếp sống, anh dùng tư duy của con người để tồn tại và quậy phá trong những hình dạng không tưởng, tạo nên những tình huống tréo ngoe chưa từng có.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 26, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Atsushi Abe","avatar":""},{"name":"Mao Ichimichi","avatar":""},{"name":"Daisuke Namikawa","avatar":""},{"name":"Toshihiko Seki","avatar":""},{"name":"Show Hayami","avatar":""},{"name":"Kana Asumi","avatar":""},{"name":"Yuka Iguchi","avatar":""},{"name":"Marina Inoue","avatar":""},{"name":"Yuji Ueda","avatar":""},{"name":"Yuma Uchida","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["女神「异世界转生想成为什么」我「勇者的肋骨」","转生成为肋巴骨","Megami \"Isekai Tensei Nani ni Naritai Desu ka\" Ore \"Yuusha no Rokkotsu de\"","Megami \"Isekai Tensei Nani ni Naritai Desu ka\" Ore \"Yūsha no Rokkotsu de\"","めがおれ","Yuusha no Rokkotsu de","Goddess: ''What Do You Want to Be Reincarnated As?'' Me: ''The Hero''s Ribs''","What Do You Want to Turn Into When You’re Reincarnated?","女神『異世界転生何になりたいですか』俺『勇者の肋骨で』"]', 1784690324118);
