INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-sinh-thanh-xuong-suon-cua-dung-si', 'Chuyển Sinh Thành Xương Sườn Của Dũng Sĩ', 'My Ribdiculous Reincarnation', 'chuyển sinh thành xương sườn của dũng sĩ my ribdiculous reincarnation atsushi abe mao ichimichi daisuke namikawa toshihiko seki show hayami kana asumi yuka iguchi marina inoue yuji ueda yuma uchida 女神「异世界转生想成为什么」我「勇者的肋骨」 转生成为肋巴骨 megami "isekai tensei nani ni naritai desu ka" ore "yuusha no rokkotsu de" megami "isekai tensei nani ni naritai desu ka" ore "yūsha no rokkotsu de" めがおれ yuusha no rokkotsu de goddess: ''what do you want to be reincarnated as?'' me: ''the hero''s ribs'' what do you want to turn into when you’re reincarnated? 女神『異世界転生何になりたいですか』俺『勇者の肋骨で』', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kieu-so', 'Kiều Sở', 'Ashes To Crown', 'https://phimimg.com/upload/vod/20260602-1/a8cc94cc8b24db6f9471b0521c13e151.jpg', 'https://phimimg.com/upload/vod/20260602-1/b87ac3cb735ca1bbeb9ef74670272e0e.jpg', '<p>Sở Triêu, con gái đại tướng quân, vì muốn thay đổi số phận bi thảm là quân cờ cho Tiêu Tuần đoạt quyền đã quyết định chủ động tấn công. Với sự hỗ trợ của Tạ Yến Lai, nàng vượt bao hiểm nguy, hộ tống hoàng trưởng tôn vào cung, đấu trí trước điện, phò tá hoàng trưởng tôn kế vị, chặt đứt con đường xưng đế của Tiêu Tuần. Tân đế lên ngôi khi Đại Sở thù trong giặc ngoài, Sở Triêu cùng Tạ Yến Lai vừa khéo léo đối nội vừa cầm quân dẹp loạn, thay đổi vận mệnh của mình, mang lại thái bình cho bá tánh.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 51, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Đô Linh","avatar":""},{"name":"Châu Dực Nhiên","avatar":""},{"name":"Đường Hiểu Thiên","avatar":""},{"name":"Vương Thụy Xương","avatar":""},{"name":"Ngô Thi Lạc","avatar":""},{"name":"Cao Mậu Đồng","avatar":""},{"name":"Tưởng Khải","avatar":""},{"name":"Mã Dược","avatar":""},{"name":"Uông Trác Thành","avatar":""},{"name":"Chương Thời An","avatar":""},{"name":"Tăng Tuyết Dao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Qiao Chu","楚后","Императрица Чу","Ashes to crown","翘楚"]', 1784690324118);
