INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-thuat-hoi-chien-phan-3', 'Chú Thuật Hồi Chiến (Phần 3)', 'Jujutsu Kaisen (Season 3)', 'https://phimimg.com/upload/vod/20260109-1/30bbc3c9118bdda3e751cec034b99886.jpg', 'https://phimimg.com/upload/vod/20260109-1/c99ee9406799474fcd724211f93a1d4d.jpg', '<p>Vì một lý do kỳ lạ nào đó, Yuji Itadori, mặc dù với thể chất hoàn hảo nhưng anh lại đâm đầu vào tham gia CLB Huyền Bí. Tuy nhiên, họ đã sớm phát hiện ra là những câu chuyện huyền bí hoàn toàn có thật khi các thành viên trong CLB lần lượt bị tấn công! Trong khi đó, Megumi Fushiguro “bí ẩn” lại đang truy tìm một đối tượng bị nguyền rủa cấp đặc biệt và cuộc tìm kiếm này đã đưa nhóm bạn đến Itadori</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 33, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jujutsu Kaisen","咒术回战","咒术回战 第一季","咒术回战 第二季","咒术回战 第三季","咒術迴戰","Jujutsu Kaisen: Guerra de hechiceros","अभिशाप नेटवर्क","呪術廻戦 懐玉・玉折","呪術廻戦 渋谷事変","呪術廻戦 死滅回游 前編","Jujutsu Kaisen: Shimetsu Kaiyuu - Zenpen","Guerra de magia","Магическая битва","มหาเวทย์ผนึกมาร","咒術迴戰 死滅迴游 前篇","Магічна битва","Sorcery Fight","JJK","JUJUTSU KAISEN Season 3: The Culling Game Part 1","Chú Thuật Hồi Chiến","呪術廻戦"]', 1784690324118);
