INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chua-chien-binh-va-vua-da-nhan-himekishi-wa-barbaroi-no-yome', 'Công Chúa Chiến Binh Và Vua Dã Nhân (Himekishi wa Barbaroi no Yome)', 'The Warrior Princess And The Barbaric King', 'https://phimimg.com/upload/vod/20260410-1/29b19b6fa702fc43ec9bdf24ff3055a7.jpg', 'https://phimimg.com/upload/vod/20260410-1/765cbdf2bf70b87a46ec04c87f8a7d7e.jpg', '<p>“Hãy giết tôi đi!” Đó là những lời của Serafina de Lavillant, nữ hiệp sĩ mạnh nhất phương Tây. Sau khi bị đánh bại trong cuộc chiến với phương Đông, nàng đã trở thành tù nhân của bọn man rợ! Điều chờ đợi Serafina là một cuộc sống đầy báo thù, tra tấn và sỉ nhục… ít nhất nàng đã nghĩ vậy! Thay vào đó, điều nàng được đề nghị là một cuộc hôn nhân với vị vua man rợ?! Một câu chuyện ly kỳ về cuộc hôn nhân siêu nhiên sắp bắt đầu!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 17, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Sayumi Suzushiro","avatar":""},{"name":"Satoshi Inomata","avatar":""},{"name":"Hana Hishikawa","avatar":""},{"name":"Aki Toyosaki","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["女骑士成为蛮族新娘","姬骑士是蛮族的新娘","公主骑士是蛮族的新娘","Himekishi wa Barbaroi no Yome","Hime Kishi wa Barbaroi no Yome","The Warrior Princess and the Barbaric King","The Bride of Barbaroi","The Barbarian''s Bride","姫騎士は蛮族の嫁"]', 1784690324118);
