INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cong-chua-chien-binh-va-vua-da-nhan-himekishi-wa-barbaroi-no-yome', 'Công Chúa Chiến Binh Và Vua Dã Nhân (Himekishi wa Barbaroi no Yome)', 'The Warrior Princess And The Barbaric King', 'công chúa chiến binh và vua dã nhân (himekishi wa barbaroi no yome) the warrior princess and the barbaric king sayumi suzushiro satoshi inomata hana hishikawa aki toyosaki 女骑士成为蛮族新娘 姬骑士是蛮族的新娘 公主骑士是蛮族的新娘 himekishi wa barbaroi no yome hime kishi wa barbaroi no yome the warrior princess and the barbaric king the bride of barbaroi the barbarian''s bride 姫騎士は蛮族の嫁', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-tram-canh-dep-cua-awajima', 'Một Trăm Cảnh Đẹp Của Awajima', 'A Hundred Scenes Of Awajima', 'https://phimimg.com/upload/vod/20260411-1/975dedaeba72e2d1371c9ce5a4c80444.jpg', 'https://phimimg.com/upload/vod/20260411-1/63291633fd188b99785ff7b61666d2df.jpg', '<p>Tại Trường Opera Awajima, những cô gái từ khắp nơi trên Nhật Bản luôn nỗ lực để giành được một vị trí trên sân khấu. Wakana tiến bước nhờ tình yêu mãnh liệt dành cho nhạc kịch, trong khi Kinue theo đuổi việc học với sự kỷ luật thầm lặng. Emi, một học sinh nhận học bổng, thu hút sự chú ý của tất cả mọi người — nhưng đặc biệt là từ Keiko, người luôn phải vật lộn giữa lòng ngưỡng mộ và sự so bì. Thông qua những góc nhìn thay đổi luân phiên, những ngày tháng đan xen của họ khám phá về tham vọng, tình bạn và hành trình tự khám phá bản thân.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 24, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Niina Nakabayashi","avatar":""},{"name":"You Taichi","avatar":""},{"name":"Ai Kayano","avatar":""},{"name":"Natsumi Fujiwara","avatar":""},{"name":"Ayumi Tsunematsu","avatar":""},{"name":"Kana Ichinose","avatar":""},{"name":"Risa Shimizu","avatar":""},{"name":"Asuna Tomari","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Awajima Hyakkei","淡島百景"]', 1784690324118);
