INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kujima-hot-ca-nha-veo-von-kujima-utaeba-ie-hororo', 'Kujima Hót, Cả Nhà Véo Von (Kujima Utaeba Ie Hororo)', 'Kujima: Why Sing, When You Can Warble?', 'https://phimimg.com/upload/vod/20260410-1/52ef46e081a42e896c7501a782266244.jpg', 'https://phimimg.com/upload/vod/20260410-1/9db61bce839243e0ff15f3c07b51184f.jpg', '<p>Vào mùa thu năm nhất trung học, Arata Kouda gặp Kujima, một sinh vật kỳ lạ trông giống như một con chim. Vì Kujima đang đói, Arata mang nó về nhà… Nhưng vì anh trai cậu thi trượt kỳ thi tuyển sinh, Kujima trở nên quá khích và cuối cùng sống nhờ ở nhà Kouda. Nó nói chỉ đến khi nào nó vượt qua được mùa đông và đón chào sự ấm áp của mùa xuân, nhưng…</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 16, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuria Kozuki","avatar":""},{"name":"Ayumu Murase","avatar":""},{"name":"Yohei Azakami","avatar":""},{"name":"Ryoko Shiraishi","avatar":""},{"name":"Hirofumi Nojima","avatar":""},{"name":"Nene Hieda","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["库吉马唱歌的家","Le cri du Kujima","Kujima Utaeba Ie Hororo","If Kujima Sings, the House Gurgles","Kujima Why Sing When You Can Warble","クジマ歌えば家ほろろ"]', 1784690324118);
