INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('star-wars-mandalorian-va-grogu', 'Star Wars: Mandalorian và Grogu', 'The Mandalorian and Grogu', 'https://phimimg.com/upload/vod/20260625-1/eae0e72afab9c7228da9b12df8859b53.jpg', 'https://phimimg.com/upload/vod/20260625-1/e43e9e9207618823fa3ca762e8fc274e.jpg', '<p>Đế Chế tàn bạo đã sụp đổ, nhưng những lãnh chúa chiến tranh của phe Đế Chế vẫn còn rải rác khắp thiên hà. Khi Nền Cộng hòa Mới nỗ lực bảo vệ những gì Quân Nổi Loạn đã chiến đấu để giành lấy, họ đã nhờ đến sự trợ giúp của thợ săn tiền thưởng Mandalorian - huyền thoại Din Djarin và cậu bé học việc Grogu.</p>', 'Full', 1, 'single', 'completed', 43, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Pedro Pascal","avatar":""},{"name":"Jeremy Allen White","avatar":""},{"name":"Sigourney Weaver","avatar":""},{"name":"Brendan Wayne","avatar":""},{"name":"Lateef Crowder","avatar":""},{"name":"Steve Blum","avatar":""},{"name":"Jonny Coyne","avatar":""},{"name":"Matthew Willig","avatar":""},{"name":"Martin Scorsese","avatar":""},{"name":"Hemky Madera","avatar":""},{"name":"Stephen McKinley Henderson","avatar":""},{"name":"Shirley Henderson","avatar":""},{"name":"Cullen Douglas","avatar":""},{"name":"Nigel Gibbs","avatar":""},{"name":"Bahia Haifi","avatar":""},{"name":"Ajay Mehta","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Звёздные Войны: Мандалорец и Грогу","The Mandalorian & Grogu","Star Wars: O Mandaloriano e Grogu","מלחמת הכוכבים: המנדלוריאן וגרוגו","Le Mandaloria