INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('heman-va-nhung-chien-binh-vu-tru', 'He-Man và Những Chiến Binh Vũ Trụ', 'Masters of the Universe', 'https://phimimg.com/upload/vod/20260625-1/2f0744171e86ee20f20e0077e236347c.jpg', 'https://phimimg.com/upload/vod/20260625-1/fe24eb04b5201e40bd364d134b70eb4b.jpg', '<p>Thương hiệu huyền thoại trở lại màn ảnh rộng. Sau 15 năm thất lạc, Thanh Gươm Quyền Năng đưa Hoàng tử Adam (Nicholas Galitzine) trở về hành tinh Eternia và phát hiện quê hương đã rơi vào sự cai trị tàn bạo của Skeletor (Jared Leto). Để cứu gia đình và thế giới của mình, Adam phải sát cánh cùng những đồng minh thân cận như Teela (Camila Mendes) và Duncan/Man-At-Arms (Idris Elba), đồng thời chấp nhận định mệnh thật sự của mình: trở thành He-Man - người đàn ông mạnh nhất vũ trụ.</p>', 'Full', 1, 'single', 'completed', 66, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Nicholas Galitzine","avatar":""},{"name":"Camila Mendes","avatar":""},{"name":"Idris Elba","avatar":""},{"name":"Jared Leto","avatar":""},{"name":"Alison Brie","avatar":""},{"name":"Jóhannes Haukur Jóhannesson","avatar":""},{"name":"Jon Xue Zhang","avatar":""},{"name":"Sam C. Wilson","avatar":""},{"name":"Charlotte Riley","avatar":""},{"name":"James Purefoy","avatar":""},{"name":"Morena Baccarin","avatar":""},{"name":"Kristen Wiig","avatar":""},{"name":"Sasheer Zamata","avatar":""},{"name":"Christian Vunipola","avatar":""},{"name":"Tom Wilton","avatar":""},{"name":"Artie Wilkins","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"685649