INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vi-ngot-chet-choc', 'Vị Ngọt Chết Chóc', 'Saccharine', 'https://phimimg.com/upload/vod/20260625-1/f8c3668b3c20ebdbcb6cc3254bea2695.jpg', 'https://phimimg.com/upload/vod/20260625-1/94607ac38b959728ff688b9de0470999.jpg', '<p>Sau khi lao vào một trào lưu giảm cân kỳ quái liên quan đến việc ăn tro cốt người chết, nữ sinh y khoa Hana đang tuyệt vọng vì tình bắt đầu bị ám bởi linh hồn của chính người mà cô đã ăn.</p>', 'Full', 1, 'single', 'completed', 48, 2026, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"Midori Francis","avatar":""},{"name":"Danielle Macdonald","avatar":""},{"name":"Madeleine Madden","avatar":""},{"name":"Joseph Baldwin","avatar":""},{"name":"Robert Taylor","avatar":""},{"name":"Emily Milledge","avatar":""},{"name":"Lisa Crittenden","avatar":""},{"name":"Lucy Goleby","avatar":""},{"name":"Showko Showfukutei","avatar":""},{"name":"Anna Adams","avatar":""},{"name":"Daniela Rene Fink","avatar":""},{"name":"Andre Ong Carlesso","avatar":""},{"name":"Darius Googe","avatar":""},{"name":"Rachel Khalaf","avatar":""},{"name":"Jeremiah Louis","avatar":""},{"name":"Mackenzi","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Saccharine"]', 1784690324118);
