INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mahou-no-shimai-lulutto-lilly', 'Mahou no Shimai Lulutto Lilly', 'Magical Sisters LuluttoLilly', 'https://phimimg.com/upload/vod/20260417-1/af8335ede8a6c9a9872bacee3cf19d4d.jpg', 'https://phimimg.com/upload/vod/20260417-1/9981e5c5464815b1ddeb28c004e9b792.jpg', '<p>Hai chị em Fuu và Rui từng rất thân thiết, nhưng gần đây họ dần trở nên xa cách. Một ngày nọ, Fuu tình cờ chạm trán với một phi thuyền bí ẩn và nhận được sức mạnh phép thuật. Cùng lúc đó, Rui cũng có được năng lực kỳ diệu, giúp cả hai có thể biến thân thành những người trưởng thành mà họ hằng mơ ước. Tuy nhiên, sức mạnh của hai chị em đi kèm với hai điều kiện bắt buộc: phép thuật chỉ có tác dụng trong vòng một năm và không một ai được phép biết về bí mật này. Trong khi vẫn giấu kín bí mật với đối phương, Fuu và Rui bắt đầu dấn thân vào con đường trở thành những thần tượng (idols) nổi tiếng.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 21, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"May Tachibana","avatar":""},{"name":"Nao Ojika","avatar":""},{"name":"Hiroki Nanami","avatar":""},{"name":"Ai Kayano","avatar":""},{"name":"Fuka Izumi","avatar":""},{"name":"Fu Hirohara","avatar":""},{"name":"Hikaru Yaotome","avatar":""},{"name":"Kohei Amasaki","avatar":""},{"name":"Tatsumaru Tachibana","avatar":""},{"name":"Tomokazu Sugita","avatar":""},{"name":"Takako Ohta","avatar":""},{"name":"Yu Mizushima","avatar":""},{"name":"Jun Kasama","avatar":""},{"name":"Megumi Oohara","avatar":""},{"name":"Aya Endo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221