INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mahou-no-shimai-lulutto-lilly', 'Mahou no Shimai Lulutto Lilly', 'Magical Sisters LuluttoLilly', 'mahou no shimai lulutto lilly magical sisters luluttolilly may tachibana nao ojika hiroki nanami ai kayano fuka izumi fu hirohara hikaru yaotome kohei amasaki tatsumaru tachibana tomokazu sugita takako ohta yu mizushima jun kasama megumi oohara aya endo 魔法姐妹露露莉莉 魔法的姐妹露露和莉莉 魔法的姐妹露露与莉莉 魔法姐妹露露特莉莉 mahō no shimai lulutto lilly lululilly mahō no shimai luluttolilly mahou no shimai luluttolilly mahou no shimai lulutto lilly 루루토리리 마법의 자매 룰루토 릴리 magical sisters lulutto lilly 魔法の姉妹ルルットリリィ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vi-vua-manh-nhat-lam-gi-o-kiep-thu-hai-phan-2', 'Vị Vua Mạnh Nhất Làm Gì Ở Kiếp Thứ Hai (Phần 2)', 'The Beginning After The End (Season 2)', 'https://phimimg.com/upload/vod/20260407-1/20c13944700ada228e91a1ae8e0c84c1.jpg', 'https://phimimg.com/upload/vod/20260407-1/aedbffec5010775e98d8061eae35fca4.jpg', '<p>Grey, vị vua mạnh nhất trong lịch sử, là nhân vật chính của câu chuyện. Bất chấp danh tiếng, tài sản và quyền lực vô song, không ai ủng hộ anh ta... và anh ta không tin tưởng bất cứ ai. Một ngày nọ, Gray bất ngờ qua đời và tái sinh ở một thế giới phép thuật với cái tên Arthur, một đứa bé bất lực. Arthur bắt đầu khám phá những niềm vui trong cuộc sống mới này mà anh không hề biết đến ở cuộc sống cũ, được bao bọc bởi một gia đình và bạn bè yêu thương. Nhưng gia đình anh bị bọn cướp tấn công khi đang đi du lịch...</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 29, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Natsumi Fujiwara","avatar":""},{"name":"Makoto Furukawa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["三岁开始做王者","终末起点","最强的王者，在第二次的人生能做什么？","最强王者，第二人生要做什么？","El comienzo después del fin","Saikyou no Ousama, Nidome no Jinsei wa Nani o Suru?","Saikyô no Ôsama, Nidome no Jinsei wa Nani wo Suru?","Saikyo2dome","Saikyou no Ousama Nidome no Jinsei wa Nani wo Suru","끝이 아닌 시작","최강의 왕, 두번째 인생에는 무엇을 하는가?","Начало после конца","البداية بعد النهاية","三歲開始做王者","最強的王者，在第二次的人生能做什麼？","終末起點 第 2 季","Що зробить найсильніший король у другому житті?","TBATE","The Beginning After the End","Ánh Sáng Cuối Con Đường","最強の王様、二度目の人生は何をする？"]', 1784690324118);
