INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vi-vua-manh-nhat-lam-gi-o-kiep-thu-hai-phan-2', 'Vị Vua Mạnh Nhất Làm Gì Ở Kiếp Thứ Hai (Phần 2)', 'The Beginning After The End (Season 2)', 'vị vua mạnh nhất làm gì ở kiếp thứ hai (phần 2) the beginning after the end (season 2) natsumi fujiwara makoto furukawa 三岁开始做王者 终末起点 最强的王者，在第二次的人生能做什么？ 最强王者，第二人生要做什么？ el comienzo después del fin saikyou no ousama, nidome no jinsei wa nani o suru? saikyô no ôsama, nidome no jinsei wa nani wo suru? saikyo2dome saikyou no ousama nidome no jinsei wa nani wo suru 끝이 아닌 시작 최강의 왕, 두번째 인생에는 무엇을 하는가? начало после конца البداية بعد النهاية 三歲開始做王者 最強的王者，在第二次的人生能做什麼？ 終末起點 第 2 季 що зробить найсильніший король у другому житті? tbate the beginning after the end ánh sáng cuối con đường 最強の王様、二度目の人生は何をする？', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-otaku-va-hai-nang-gal-bi-an-otaku-ni-yasashii-gal-wa-inai', 'Chàng Otaku Và Hai Nàng Gal Bí Ẩn (Otaku ni Yasashii Gal wa Inai!?)', 'Gals Can''t Be Kind To Otaku!?', 'https://phimimg.com/upload/vod/20260423-1/e81f759bfaba7e666b1f12287c9b4146.jpg', 'https://phimimg.com/upload/vod/20260423-1/b2133457c5c60d9153267fd7c85a3a95.jpg', '<p>Takuya Seo là một chàng trai hướng nội, một otaku chính hiệu luôn cố gắng sống lặng lẽ tại trường—cho đến khi hai cô nàng &quot;gal&quot; sành điệu trong lớp bắt đầu chủ động tiếp cận cậu. Đó là Kei Amane, một cô gái cực ngầu nhưng đôi khi lại rất lơ đãng, và Kotoko Ijichi, một nữ sinh luôn tràn đầy năng lượng và vui vẻ. Dù tính cách hoàn toàn khác biệt, cả ba sớm trở nên thân thiết nhờ niềm đam mê chung dành cho anime, trò chơi điện tử và văn hóa fandom. Tuy nhiên, một câu hỏi lớn vẫn luôn quẩn quanh trong đầu Takuya: Liệu những cô nàng gal xinh đẹp và tốt bụng chịu chơi thân với otaku có thực sự tồn tại ngoài đời không?!</p>', 'Tập 12', 13, 'hoathinh', 'ongoing', 18, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shou Komura","avatar":""},{"name":"Konomi Inagaki","avatar":""},{"name":"Yu Serizawa","avatar":""},{"name":"Jun Kasama","avatar":""},{"name":"Konomi Kohara","avatar":""},{"name":"Atsumi Tanezaki","avatar":""},{"name":"Emiri Kato","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["没有辣妹会对阿宅温柔！？","哪里有温柔对待阿宅的辣妹！？","没有辣妹会对阿宅温柔","Otaku ni Yasashii Gal wa inai!?","Otaku ni Yasashii Gyaru wa Inai","Дівчата не можуть бути добрими до отаку!?","オタクに優しいギャルはいない!?"]', 1784690324118);
