INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('varzea-cai-noi-cua-bong-da-varzea-onde-nasce-o-futebol', 'Várzea:  Cái Nôi Của Bóng Đá (Várzea: Onde Nasce o Futebol)', 'The Root Of The Game', 'https://phimimg.com/upload/vod/20260625-1/1f75410f479e6e4b820c67a3fc6ed81b.jpg', 'https://phimimg.com/upload/vod/20260625-1/b23427e4418f9239a08199a87ba792cf.jpg', '<p>Brazil sống, thở và xuất khẩu &quot;várzea&quot; — thứ bóng đá phong trào hoang dã và thuần khiết nhất. Loạt phim này đi sâu vào những câu chuyện phía sau &quot;trò chơi đẹp&quot;, nơi trái bóng tròn mang trong mình sức mạnh diệu kỳ để thay đổi hoàn toàn những số phận.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 40, 2026, 'Vietsub', 'FHD', 'Brazil', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Várzea: Onde Nasce o Futebol"]', 1784690324118);
