INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-nghiem-hoa-ky', 'Thử Nghiệm Hoa Kỳ', 'The American Experiment', 'https://phimimg.com/upload/vod/20260625-1/4ac0d033f2bd7ef072f5615e1edb6ebb.jpg', 'https://phimimg.com/upload/vod/20260625-1/e71191d70c79e8ccbe4dbc5596ab99f1.jpg', '<p>Sự sống. Quyền tự do. Và mưu cầu hạnh phúc. Loạt phim tài liệu lịch sử hoành tráng này sẽ tái hiện lại hành trình những lý tưởng của các nhà lập quốc Hoa Kỳ đã khơi nguồn và khai sinh ra một quốc gia như thế nào.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 36, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Martin Sheen","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["The American Experiment"]', 1784690324118);
