INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-sinh-thanh-may-ban-hang-va-vuot-ai-ham-nguc-phan-3', 'Chuyển Sinh Thành Máy Bán Hàng Và Vượt Ải Hầm Ngục (Phần 3)', 'Reborn As A Vending Machine, I Now Wander The Dungeon (Season 3)', 'https://phimimg.com/upload/vod/20260512-1/4d67322c07ddba99029c00d35aeab034.jpg', 'https://phimimg.com/upload/vod/20260512-1/8029ff3ad5249c83e797a215873f3bd8.jpg', '<p>Một người cuồng máy bán hàng tự động đã bị chết một cách hết sức &quot;ba láp ba xàm&quot; khi bị chính thứ mình yêu thích giết chế. Không biết nên vui hay buồn nhưng anh lại được đầu thai thành một chiếc máy bán hàng tự động ở thế giới mới. Sau khi xuất hiện trong một khu rừng có nhiều ếch và quái vật, máy bán hàng tự động lại cần phải có tiền xu để duy trì hàng hóa và nâng cấp kỹ năng mới.

May mắn thay, chiếc máy bán hàng tự động đã được một cô gái trẻ cứu giúp và cô đã nhanh chóng nhận ra đây là một chiếc máy có ý thức, cô đã mang nó đến khu định cư của con người. Kể từ đây, chiếc máy kỳ lạ này dần tạo ra được ảnh hưởng trong thế giới xung quanh. &nbsp;(Nguồn: VuiGhe)</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 20, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Jun Fukuyama","avatar":""},{"name":"Kaede Hondo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Aquela vez em que reencarnei numa máquina de vendas!","Reborn as a Vending Machine","Jidōhanbaiki ni Umarekawatta Ore wa Meikyū o Samayō","Jidou Hanbaiki ni Umarekawatta Ore wa Meikyuu wo Samayou","Jidō Hanbaiki ni Umarekawatta Ore wa Meikyū wo Samayō","Jidouhanbaiki ni Umarekawatta Ore wa Meikyuu o Samayou","Jihanki","Ore Jihanki","Reborn as a Vending Machine, I Now Wander the Dungeon","Переродившись в торговый автомат, я блуждаю по подземелью","Я переродився у торговий автомат і тепер блукаю підземеллям","自動販売機に生まれ変わった俺は迷宮を彷徨う"]', 1784690324118);
