INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-tham-tu-cuu-an-mang-luc-nua-dem', 'Đội Thám Tử Cừu: Án Mạng Lúc Nửa Đêm', 'The Sheep Detectives', 'https://phimimg.com/upload/vod/20260624-1/6d50988f56467c15b38354752f8c9d38.jpg', 'https://phimimg.com/upload/vod/20260624-1/998077b1ee33d003e0aac3f255068467.jpg', '<p>Trong bộ phim trinh thám hài hước, độc đáo này, George (Hugh Jackman) là một người chăn cừu, mỗi tối đều đọc tiểu thuyết trinh thám cho đàn cừu yêu quý nghe, nghĩ rằng chúng không thể hiểu được. Nhưng khi George bất ngờ qua đời trong một sự cố bí ẩn trên trang trại, đàn cừu quyết định tự mình trở thành thám tử. Lần theo manh mối và điều tra các nghi phạm là con người, chúng chứng minh rằng ngay cả cừu cũng có thể phá án xuất sắc.</p>', 'Full', 1, 'single', 'completed', 70, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Hugh Jackman","avatar":""},{"name":"Julia Louis-Dreyfus","avatar":""},{"name":"Emma Thompson","avatar":""},{"name":"Nicholas Braun","avatar":""},{"name":"Chris O''Dowd","avatar":""},{"name":"Bryan Cranston","avatar":""},{"name":"Nicholas Galitzine","avatar":""},{"name":"Molly Gordon","avatar":""},{"name":"Tosin Cole","avatar":""},{"name":"Hong Chau","avatar":""},{"name":"Regina Hall","avatar":""},{"name":"Patrick Stewart","avatar":""},{"name":"Conleth Hill","avatar":""},{"name":"Kobna Holdbrook-Smith","avatar":""},{"name":"Brett Goldstein","avatar":""},{"name":"Rhys Darby","avatar":""},{"name":"B","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Three Bags Full: A Sheep Detective Movie","Бараны-детективы","Bêêêêtective Privé","Béé team na stopě","แก๊งแกะรอย ยอดนักสืบ","Lammasetsivät","Bèèèèh: Het Mysterie van de Wei","Detektivët e deleve","کاراگاهان گوسفند","les moutons détectives","Bir Koyun Polisiyesi","Следствие ведут овечки","De Schapenspeurders","The Sheep Detectives"]', 1784690324119);
