INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doi-tham-tu-cuu-an-mang-luc-nua-dem', 'Đội Thám Tử Cừu: Án Mạng Lúc Nửa Đêm', 'The Sheep Detectives', 'đội thám tử cừu: án mạng lúc nửa đêm the sheep detectives hugh jackman julia louis-dreyfus emma thompson nicholas braun chris o''dowd bryan cranston nicholas galitzine molly gordon tosin cole hong chau regina hall patrick stewart conleth hill kobna holdbrook-smith brett goldstein rhys darby b three bags full: a sheep detective movie бараны-детективы bêêêêtective privé béé team na stopě แก๊งแกะรอย ยอดนักสืบ lammasetsivät bèèèèh: het mysterie van de wei detektivët e deleve کاراگاهان گوسفند les moutons détectives bir koyun polisiyesi следствие ведут овечки de schapenspeurders the sheep detectives', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chao-mung-den-voi-lop-hoc-de-cao-thuc-luc-phan-4', 'Chào Mừng Đến Với Lớp Học Đề Cao Thực Lực (Phần 4)', 'Classroom Of The Elite (Season 4)', 'https://phimimg.com/upload/vod/20260404-1/cb803bac59c99eb91844825910cee138.jpg', 'https://phimimg.com/upload/vod/20260404-1/42a1f87963e90769ee66706a8a52bacb.jpg', '<p>Ayanokoji cùng cả lớp bước vào năm hai tại Trường Trung học Bồi dưỡng Nâng cao đầy khắc nghiệt. Những bài kiểm tra mới nhanh chóng đẩy họ vào tình thế căng thẳng khi phải hợp tác với nhóm học sinh năm nhất bí ẩn. Đặc biệt, tuy kỳ thi đầu tiên buộc hai khối phối hợp, nhưng chỉ học sinh năm hai phải đối mặt nguy cơ bị đuổi học nếu thất bại. Sự xuất hiện của một học sinh đến từ Phòng Trắng khiến bầu không khí càng trở nên nguy hiểm và khó đoán. Giữa vòng xoáy âm mưu và đấu trí, Ayanokoji phải tìm ra kẻ thù ẩn danh để bảo toàn vị trí của mình.</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 20, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shoya Chiba","avatar":""},{"name":"Akari Kito","avatar":""},{"name":"Ayana Taketatsu","avatar":""},{"name":"Yurika Kubo","avatar":""},{"name":"Mao Ichimichi","avatar":""},{"name":"Ryota Osaka","avatar":""},{"name":"Eiji Takeuchi","avatar":""},{"name":"Rina Hidaka","avatar":""},{"name":"Nao Toyama","avatar":""},{"name":"Rina Sato","avatar":""},{"name":"Rie Takahashi","avatar":""},{"name":"Momoko Seto","avatar":""},{"name":"Mao Ichimichi","avatar":""},{"name":"Masaaki Mizunaka","avatar":""},{"name":"Toshiki Iwasawa","avatar":""},{"name":"Shinnosuke Tokudome","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id"