INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuu-nghia-nhan-yen-van-tu', 'Cửu Nghĩa Nhân: Yên Vân Tú', 'The Embroidered Truth', 'https://phimimg.com/upload/vod/20260612-1/6ce8f2313456d536296b45fc08b24a5e.jpg', 'https://phimimg.com/upload/vod/20260612-1/29a5c3d150dc2831d7c5f5b9b30205a1.jpg', '<p>Chủ phường thêu Ngô Liêm cậy quyền cậy thế, mượn tay nghề thêu để hại đời bao nhiêu tú nương. Lận Như Lan bị làm nhục và vu oan, uất ức tự sát nhưng may mắn sống sót. Bạn thân cô là Mạnh Uyển nhẫn nhục chịu đựng ba năm. Dưới sự giúp đỡ của nhiều trang nghĩa hiệp, những cô nương bị Ngô Liêm hại đời đã lấy mồ hôi xương máu làm vũ khí, lấy sự nhẫn nại làm mưu lược, vùng lên từ đường cùng, phá tan quyền mưu độc ác, cuối cùng tự mình rửa sạch oan khuất, trả lại công bằng cho phụ nữ và yên bình cho thế gian.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 37, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Mộc Hề","avatar":""},{"name":"Hàn Vũ Thần","avatar":""},{"name":"Hồng Giai Ninh","avatar":""},{"name":"Vương Khải Dập","avatar":""},{"name":"Y Linh","avatar":""},{"name":"Niệm Chân","avatar":""},{"name":"Trương Khải","avatar":""},{"name":"Tiêu Mục Hàm","avatar":""},{"name":"Trần Giai Kỳ","avatar":""},{"name":"Lam Huyên","avatar":""},{"name":"Vu Lỗi","avatar":""},{"name":"Vương Tư Hàm","avatar":""},{"name":"Thi Ý","avatar":""},{"name":"Dương Khải Văn","avatar":""},{"name":"Tiêu Đông Hạo","avatar":""},{"name":"Trần Nhuận","avatar":""},{"name":"Triệu Bội Huyên","avatar":""},{"name":"Tề Hàng","avatar":""},{"name":"Hoàng Hạ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["九义人之烟云绣"]', 1784690324119);
