INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuu-nghia-nhan-yen-van-tu', 'Cửu Nghĩa Nhân: Yên Vân Tú', 'The Embroidered Truth', 'cửu nghĩa nhân: yên vân tú the embroidered truth trương mộc hề hàn vũ thần hồng giai ninh vương khải dập y linh niệm chân trương khải tiêu mục hàm trần giai kỳ lam huyên vu lỗi vương tư hàm thi ý dương khải văn tiêu đông hạo trần nhuận triệu bội huyên tề hàng hoàng hạ 九义人之烟云绣', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-bang-gap-nhau-mot-lan', 'Chi Bằng Gặp Nhau Một Lần', 'Endless Love', 'https://phimimg.com/upload/vod/20260620-1/227177994926f7f3cdfd7cd0c5a63110.jpg', 'https://phimimg.com/upload/vod/20260620-1/9b17ce036447116fda3c53b120a5c979.jpg', '<p>Chuyển thể từ bài hát “Chi Bằng Gặp Nhau Một Lần” của Hải Lai A Mộc, kể 
về mối tình trái ngang đẫm máu, dây dưa ba kiếp giữa Mộ Như Nhất, Công 
chúa Tây Lăng và Lăng Kiêu, Thái tử Đông Thanh. Nàng cứu chàng trong cơn
 hoạn nạn, nhưng chàng lại bắt tay với kẻ thù, quay về nhuốm máu ngày 
thành thân, đẩy họ vào thế đối đầu. Nàng giả chết, giả làm hồn ma báo 
thù. Chàng mụ mị, u mê vì máu đầu tim và cỏ Vong Tình, để rồi số phận 
làm cho yêu hận giữa họ cứ thế đan xen khó rạch ròi. Ba kiếp dây dưa là 
duyên hay nợ, chẳng qua chỉ là ba vở kịch đời này ta diễn cùng người.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 45, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Tín Triết","avatar":""},{"name":"Tưởng Bằng Vũ","avatar":""},{"name":"Hoàng Đào","avatar":""},{"name":"Vương Mễ Trạch","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["不如见一面"]', 1784690324119);
