INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-vuong-trum-cuoi-cung-hung-cuc-ac-se-doc-suc-vi-nguoi-dan-phan-2', 'Nữ Vương Trùm Cuối Cùng Hung Cực Ác Sẽ Dốc Sức Vì Người Dân (Phần 2)', 'The Most Heretical Last Boss Queen: From Villainess to Savior (Season 2)', 'https://phimimg.com/upload/vod/20260415-1/7ba5f25dfed689511b68e27a33b83c0a.jpg', 'https://phimimg.com/upload/vod/20260415-1/afbf9cf3edf9d21a9990282099bab6ec.jpg', '<p>&quot;Nếu ta trở thành một nữ vương tồi tệ thì hãy giết ta.&quot;

Công chúa Pride Royal Ivy khi lên 8 tuổi đã nhận ra kiếp trước của mình là một cô gái bình thường, con của một gia đình bình dân ở Nhật Bản. Giờ đây, cô phát hiện mình đã trở thành nữ vương độc ác, tàn độc trong một Otome-game...

Cô đã chuyển sinh vào Otome-game &quot;Người và tia sáng của thế gian&quot;. Theo mạch truyện thì Pride là người tàn độc sẽ đày ải toàn bộ đất nước và thần dân. Dựa vào ký ức của tiền kiếp về tựa game, cô đã biết mình sẽ trở thành trùm cuối nên quyết định sẽ bằng mọi giá tránh cho thảm kịch xảy đến.

Đây chính là câu chuyện kỳ ảo về một nữ công chúa phản diện cùng hung cực ác cố gắng tránh khỏi thảm kịch xảy đến với mình và sẽ xây dựng một thế giới nơi mọi nhân vật đều được hạnh phúc.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 16, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Fairouz Ai","avatar":""},{"name":"Haruka Tomatsu","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Higeki no Genkyō to Naru Saikyō Gedō Last Boss Joō wa Tami no Tame ni Tsukushimasu.","Higeki no Genkyou to Naru Saikyou Gedou Last Boss Joou wa Tami no Tame ni Tsukushimasu.","ラス為","LasTame","成為悲劇元兇的最強異端，最後頭目女王為了人民犧牲奉獻 第二季","The Most Heretical Last Boss Queen: From Villainess to Savior.","悲劇の元凶となる最強外道ラスボス女王は民の為に尽くします。"]', 1784690324119);
