INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nu-vuong-trum-cuoi-cung-hung-cuc-ac-se-doc-suc-vi-nguoi-dan-phan-2', 'Nữ Vương Trùm Cuối Cùng Hung Cực Ác Sẽ Dốc Sức Vì Người Dân (Phần 2)', 'The Most Heretical Last Boss Queen: From Villainess to Savior (Season 2)', 'nữ vương trùm cuối cùng hung cực ác sẽ dốc sức vì người dân (phần 2) the most heretical last boss queen: from villainess to savior (season 2) fairouz ai haruka tomatsu higeki no genkyō to naru saikyō gedō last boss joō wa tami no tame ni tsukushimasu. higeki no genkyou to naru saikyou gedou last boss joou wa tami no tame ni tsukushimasu. ラス為 lastame 成為悲劇元兇的最強異端，最後頭目女王為了人民犧牲奉獻 第二季 the most heretical last boss queen: from villainess to savior. 悲劇の元凶となる最強外道ラスボス女王は民の為に尽くします。', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-tri-tinh-yeu', 'Tiên Tri Tình Yêu', 'Magic Move', 'https://phimimg.com/upload/vod/20260423-1/3589c3c1c058b0a71cf2d172d3ec1db1.jpg', 'https://phimimg.com/upload/vod/20260423-1/10ec151d7bd9724043f06af1618bbcf1.jpg', '<p>Một sinh viên kiến trúc năm cuối dồn hết tâm huyết vào đồ án tốt nghiệp lấy cảm hứng từ “đá rune”. Cuộc sống của cậu bất ngờ rẽ sang hướng khác khi tình cờ trở thành thầy bói tại quán bar Magic Move của bạn mình, và những lời tiên đoán chính xác đến khó tin khiến cậu nổi tiếng chỉ sau một đêm. Rồi định mệnh đưa cậu bước vào một mối tình hỗn loạn—thứ sẽ thay đổi cuộc đời cậu mãi mãi.</p>', 'Tập 10', 10, 'series', 'ongoing', 28, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Napatsak Ekphiphatthana","avatar":""},{"name":"Wutthiphat Rungcharoenareechit","avatar":""},{"name":"Pitchawat Wisittarakul","avatar":""},{"name":"Patpong Loymaping","avatar":""},{"name":"Yaninsinee Chotisuriyaphong","avatar":""},{"name":"Sorrawit Kaewprasert","avatar":""},{"name":"Rattaphon Thepmanee","avatar":""},{"name":"Shino Peraphat Dhanarattananont","avatar":""},{"name":"Thanaporn Wagprayoon","avatar":""},{"name":"Sumet Ong-ard","avatar":""},{"name":"Praiya Padung","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["ทำนายทายรัก","猜猜爱"]', 1784690324119);
