INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-ket-ban-voi-co-gai-xinh-thu-hai-trong-lop', 'Tôi Kết Bạn Với Cô Gái Xinh Thứ Hai Trong Lớp', 'I Made Friends With The Second Prettiest Girl In My Class', 'https://phimimg.com/upload/vod/20260411-1/7759e4be2e53c959346d31b4571998d3.jpg', 'https://phimimg.com/upload/vod/20260411-1/3bebbce4b49b7075cb5f83c075d16f38.jpg', '<p>Maki Maehara, một nam sinh bị cô lập trong lớp, cuối cùng cũng có được người bạn đầu tiên: Umi Asanagi — cô gái xinh đẹp thứ hai trong khối và luôn là tâm điểm của mọi sự chú ý. Maki luôn tin rằng cô ấy ở một đẳng cấp hoàn toàn khác so với mình, nhưng khi tình bạn bất ngờ giữa họ dần khăng khít hơn, anh bắt đầu tự hỏi... liệu có thể tồn tại một điều gì đó sâu đậm hơn cả tình bạn giữa hai người hay không?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 17, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Haruki Ishiya","avatar":""},{"name":"Manaka Iwami","avatar":""},{"name":"Sayumi Suzushiro","avatar":""},{"name":"Ikumi Hasegawa","avatar":""},{"name":"Yuhko Kaida","avatar":""},{"name":"Shizuka Itoh","avatar":""},{"name":"Minami Tsuda","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["我和班上第二可爱的女生成为朋友","和班上第二可爱的女孩成了朋友","和班上第二可爱的女生成为朋友","和班里第二可爱的女孩子成为了朋友","Class de 2-ban Me ni Kawaii Onna no Ko to Tomodachi ni Natta","Kura Nika","クラにか","Kurasu de Ni-ban Me ni Kawaii Onna no Ko to Tomodachi ni Natta","kuranika","Class de 2-banme ni Kawaii Onnanoko to Tomodachi ni Natta","我和班上第二可愛的女生成為朋友","Подружився з 2-ю за популярністю дівчиною в класі","クラスで２番目に可愛い女の子と友だちになった"]', 1784690324119);
