INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('toi-ket-ban-voi-co-gai-xinh-thu-hai-trong-lop', 'Tôi Kết Bạn Với Cô Gái Xinh Thứ Hai Trong Lớp', 'I Made Friends With The Second Prettiest Girl In My Class', 'tôi kết bạn với cô gái xinh thứ hai trong lớp i made friends with the second prettiest girl in my class haruki ishiya manaka iwami sayumi suzushiro ikumi hasegawa yuhko kaida shizuka itoh minami tsuda 我和班上第二可爱的女生成为朋友 和班上第二可爱的女孩成了朋友 和班上第二可爱的女生成为朋友 和班里第二可爱的女孩子成为了朋友 class de 2-ban me ni kawaii onna no ko to tomodachi ni natta kura nika クラにか kurasu de ni-ban me ni kawaii onna no ko to tomodachi ni natta kuranika class de 2-banme ni kawaii onnanoko to tomodachi ni natta 我和班上第二可愛的女生成為朋友 подружився з 2-ю за популярністю дівчиною в класі クラスで２番目に可愛い女の子と友だちになった', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bach-quy-da-hanh-ky-hyakki-yagshosho', 'Bách Quỷ Dạ Hành Ký (Hyakki Yagshosho)', 'Beyond Twilight', 'https://phimimg.com/upload/vod/20260412-1/b4a448e7f4a5822cb197228d0e83cc48.jpg', 'https://phimimg.com/upload/vod/20260412-1/fd3245f9897105ea0358a833300400c9.jpg', '<p>Ritsu được thừa hưởng giác quan thứ sáu từ ông nội, cùng với một hộ pháp bảo vệ thuộc cõi âm tên là Blue Storm (Thanh Lam). Những hiện tượng kỳ lạ dường như luôn bám theo bộ đôi này, và nhiệm vụ của họ là phải tìm ra chân tướng của những sự kiện bí ẩn đó. Mỗi câu chuyện là một phần độc lập nhưng đều có sự xuất hiện của các nhân vật quen thuộc — những người mà bạn sẽ dần thấu hiểu và trân trọng khi chứng kiến cách họ đối mặt với những thứ &quot;không thuộc về thế giới này&quot; theo phong cách riêng của mỗi người.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 21, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Nobuhiko Okamoto","avatar":""},{"name":"Kazuki Kyan","avatar":""},{"name":"Ikumi Hasegawa","avatar":""},{"name":"Hironori Kondoh","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hyakki Yakoushou","Hyakki Yakōshō","Hyakki Yagshosho","Beyond Twilight","百鬼夜行抄"]', 1784690324119);
