INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tracker-phan-3', 'Tracker (Phần 3)', 'Tracker (Season 3)', 'https://phimimg.com/upload/vod/20260308-1/6863811034a23294dda02e625c0d278a.jpg', 'https://phimimg.com/upload/vod/20260308-1/c8ef6f8ba54c66a337937976876ee7aa.jpg', '<p>Colter Shaw, một người đàn ông có kỹ năng sinh tồn điêu luyện và lối sống cô độc, rong đuổi khắp đất nước với tư cách là một &#39;kẻ tìm kiếm phần thưởng&#39;. Anh sử dụng khả năng theo dấu bậc thầy của mình để giúp đỡ những người dân thường và lực lượng hành pháp giải quyết mọi loại bí ẩn, đồng thời phải đối mặt với những rạn nứt và bóng ma quá khứ từ chính gia đình mình.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 24, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Justin Hartley","avatar":""},{"name":"Fiona Rene","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["LE TRAQUEUR","寻踪者","寻宝侦探","ردیاب","The Never Game","Tracker"]', 1784690324119);
