INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-trinh', 'Song Trình', 'Double Helix', 'https://phimimg.com/upload/vod/20260512-1/287682d5c7d053358d83c9e0734c8685.jpg', 'https://phimimg.com/upload/vod/20260512-1/7eb1db1214339f6fae154cbca5bed169.jpg', '<p>Hai chàng trai từng yêu nhau thời trung học bị gia đình và xã hội chia cắt. Nhiều năm sau, họ gặp lại khi một người trở thành cấp trên của người kia, từ đó phải đối mặt với tình yêu cũ, hiểu lầm và những tổn thương chưa thể chữa lành.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 40, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tôn Chính","avatar":""},{"name":"Lữ Tư Đồng","avatar":""},{"name":"Pháp Tuyên Các","avatar":""},{"name":"Hạ Gia Thuật","avatar":""},{"name":"Lý Kha Dập","avatar":""},{"name":"Dương Khả Hân","avatar":""},{"name":"Diệu Tĩnh Âu","avatar":""},{"name":"Cừu Tử Dịch","avatar":""},{"name":"Long Gia Dự","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["新版双程","A Round Trip to Love 2026","双程"]', 1784690324119);
