INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('song-trinh', 'Song Trình', 'Double Helix', 'song trình double helix tôn chính lữ tư đồng pháp tuyên các hạ gia thuật lý kha dập dương khả hân diệu tĩnh âu cừu tử dịch long gia dự 新版双程 a round trip to love 2026 双程', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xuyen-khong-thanh-tien-de-he-thong-den-muon-tam-van-nam', 'Xuyên Không Thành Tiên Đế, Hệ Thống Đến Muộn Tám Vạn Năm', 'Traveling Through Time To Become An Immortal Emperor, The System Arrives 80,000 Years Late', 'null', 'https://phimimg.com/upload/vod/20260515-1/f0365b752ae13dc9ffd3be2e5488e1d9.jpg', '<p>Sau hàng ngàn năm khổ tu vẫn không thể tiến thêm một bước, Triệu Anh Hùng bắt đầu hoài nghi con đường mình đang đi. Sự xuất hiện của hệ thống mang đến một cơ hội, nhưng cũng đặt ra những câu hỏi lớn. Nhiệm vụ kỳ lạ, phần thưởng hiếm có, tất cả dường như không đơn giản chỉ là cơ duyên. Khi trở về Thanh Vân Tông, chứng kiến sự suy tàn và những biến đổi của người cũ, anh càng nhận ra thời gian có thể thay đổi mọi thứ. Qua từng biến cố, từng trận chiến, anh dần hiểu rằng tu hành không chỉ là truy cầu sức mạnh, mà còn là việc nhìn thấu bản chất của vận mệnh. Và khi Hồng Mông Đạo Vận tích lũy đủ nhiều, câu hỏi lớn nhất hiện ra, liệu anh đang tự do bước đi, hay chỉ đang lần theo một con đường đã được vạch sẵn từ tám vạn năm trước?</p>', 'Hoàn Tất (40/40)', 40, 'hoathinh', 'completed', 23, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324119);
