INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-so-nam-bo', 'Hồ Sơ Nam Bộ', 'Archives: The Nanyang Mystery', 'https://phimimg.com/upload/vod/20260611-1/fe461009ad3b79e5581a16bf014041bb.jpg', 'https://phimimg.com/upload/vod/20260611-1/532ffe60e51a3380b6e15dd8a2023e06.jpg', '<p>Thời kỳ đầu Dân Quốc, trên vùng biển Nam Dương xảy ra vụ án mạng kỳ bí &quot;Thủy quỷ vọng hương&quot;. Hai nhân viên thuộc Cục Lưu trữ Phía Nam - đơn vị chuyên điều tra các sự kiện huyền bí của gia tộc họ Trương là Trương Hải Diêm và Trương Hải Hà được cử đến hiện trường. Không ngờ họ vướng vào một âm mưu tử thần nhằm săn lùng các thành viên họ Trương ở hải ngoại. Trương Hải Hà hy sinh thân mình để mở đường cho Hải Diêm lên chuyến tàu Nam An trở về Hạ Môn, hy vọng đồng đội có cơ hội sống sót. Nhưng chuyến hải trình đầy sóng gió này mới chỉ là khởi đầu: một tên quân phiệt quyền lực, chàng kế toán trẻ ngây thơ nhưng kiên định, cùng người thân thập niên chưa gặp... Hải Diêm đơn độc đối mặt với những biến cố dồn dập. Và khi chân anh chạm đất Hạ Môn, số phận thực sự của hai chàng trai mới bắt đầu thay đổi...</p>', 'Hoàn Tất (33/33)', 33, 'series', 'completed', 49, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Tân Thành","avatar":""},{"name":"Đinh Vũ Hề","avatar":""},{"name":"Khương Bội Dao","avatar":""},{"name":"Phú Đại Long","avatar":""},{"name":"Lưu Lệnh Tư","avatar":""},{"name":"Trương Thần Tiêu","avatar":""},{"name":"Lý Hoan","avatar":""},{"name":"Khương Trác Quân","avatar":""},{"name":"Hàn Đống","avatar":""},{"name":"Quý Tiêu Băng","avatar":""},{"name":"Từ Chấn Hiên","avatar":""},{"name":"Ứng Hạo Minh","avatar":""},{"name":"Khúc Cao Vị","avatar":""},{"name":"Khấu Chấn Hải","avatar":""},{"name":"Đồng Thần Khiết","avatar":""},{"name":"Trình Tương","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Nan Bu Dang An","Nanbu Dangan","南部檔案","Южное бюро","Southern Archives","Cases of the South","The South Bureau","Southern Anecdote Archives","Archives: The Nanyang Mystery","Southern Anecdote","Hồ Sơ Nam Bộ","南部档案"]', 1784690324119);
