INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ho-so-nam-bo', 'Hồ Sơ Nam Bộ', 'Archives: The Nanyang Mystery', 'hồ sơ nam bộ archives: the nanyang mystery trương tân thành đinh vũ hề khương bội dao phú đại long lưu lệnh tư trương thần tiêu lý hoan khương trác quân hàn đống quý tiêu băng từ chấn hiên ứng hạo minh khúc cao vị khấu chấn hải đồng thần khiết trình tương nan bu dang an nanbu dangan 南部檔案 южное бюро southern archives cases of the south the south bureau southern anecdote archives archives: the nanyang mystery southern anecdote hồ sơ nam bộ 南部档案', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-lop-truong-vung-ve-va-co-gai-mac-vay-ngan', 'Cô Lớp Trưởng Vụng Về Và Cô Gái Mặc Váy Ngắn', 'The Klutzy Class Monitor And The Girl With The Short Skirt', 'https://phimimg.com/upload/vod/20260407-1/3059c10258289a44623435464b0200d8.jpg', 'https://phimimg.com/upload/vod/20260407-1/eefcd47bed2bc21f1520fd5c519aca96.jpg', '<p>Mỗi sáng, Sakuradaimon đều nghiêm túc thực hiện nhiệm vụ kiểm tra nội quy tại cổng trường, và mục tiêu quen thuộc của cậu chính là Poem – cô nàng luôn bị tuýt còi vì chiếc váy quá ngắn. Thế nhưng, khi cả hai &quot;bị nhốt&quot; chung trong lớp học phụ đạo, Poem đã tình cờ phát hiện ra bí mật động trời: Chàng thanh niên nghiêm túc, cứng nhắc Sakuradaimon hóa ra lại là một &quot;kẻ mù chữ&quot; chính hiệu trong việc học tập! Giữa những màn đấu khẩu nảy lửa và những tình huống dở khóc dở cười tại trường học, hai thái cực đối lập này dần xích lại gần nhau, tạo nên một tình bạn – và có lẽ là cả tình yêu – đầy bất ngờ.</p>', 'Tập 12', 13, 'hoathinh', 'ongoing', 18, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Riko Akechi","avatar":""},{"name":"Junya Enoki","avatar":""},{"name":"Hayato Dojima","avatar":""},{"name":"Jun Fukuyama","avatar":""},{"name":"Yuina Ito","avatar":""},{"name":"Ayaka Fukuhara","avatar":""},{"name":"Yuhko Kaida","avatar":""},{"name":"Tetsu Inada","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["一根筋的风纪委员与裙长不当的JK","木頭風紀委員和迷你裙JK的故事","木头风纪委员和迷你裙JK的故事","废柴风纪委员与裙子长度不合规的JK的故事","Ponkotsu Fūkiin to Skirt Take ga Futekisetsu na JK no Hanashi","Ponkotsu Fuukiin to Skirt Take ga Futekisetsu na JK no Hanashi","Ponkotsu Fuuki Iin to Skirt-take ga Futekisetsu na JK no Hanashi","The Story Between a Dumb Prefect and a High School Girl With an Inappropriate Skirt Length","Story of the Useless Public Morals Committeeman and the High School Girl With Inappropriate Skirt Length","Story of the Useless Prefect and the High School Girl With an Inappropriate Skirt Length","The Klutzy Class Monitor and the Girl With the Short Skirt","ポンコツ風紀委員とスカート丈が不適切なJKの話"]', 1784690324119);
