INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-nop-tan-the-cho-quoc-gia', 'Tôi Nộp Tận Thế Cho Quốc Gia', 'Project Spark', 'https://phimimg.com/upload/vod/20260427-1/ec8a2146c4f901aec1fbbd7f1700e2ee.jpg', 'https://phimimg.com/upload/vod/20260427-1/378a3e730c40382b7449f4ca07cd823a.jpg', '<p>Câu chuyện về những cuộc chiến với xác sống không còn mới mẻ nữa, nhưng Tôi Nộp Tận Thế Cho Quốc Gia thì lại hoàn toàn khác, xác sống ở đây không hiện hữu trong thế giới hiện đại của con người, mà ở một thế giới hoàn toàn khác, có lẽ thế giới ấy đã bị ăn mòn tới cùng cực, giống như là đã và đang ở giai đoạn tận thế ấy. Và thế giới tận thế ấy được phát hiện bởi anh thanh niên Trần Phong bằng thứ năng lực xuyên không kỳ lạ của mình, anh dễ dàng đi lại giữa hai thế giới mà chẳng vướng chút khó khăn nào. Trần Phong rất thật thà nên đã báo cáo ngay sự việc hệ trọng ấy tới quốc gia và rất nhanh chóng, quốc gia đã thành lập những đội quân hùng mạnh và được vũ trang bằng những vũ khí hiện đại nhất để đến và chinh phục thế giới xác sống tận thế ấy. Không nằm ngoài dự liệu, quân đội của quốc gia đã chiến được thế áp đảo hoàn toàn trước thế giới xác sống và các tên trùm sỏ nơi đây. Ngoài việc kiếm được những lợi ích từ công nghệ và khoa học nơi đây, thì quốc gia của Trần Phong cũng phải đứng trước sự ganh tị và dòm ngó từ những quốc gia xung quanh, sẵn sàng đưa mọi thứ trở nên căng thẳng, thậm chí là những cuộc giao tranh có thể nổ ra.</p>', 'Tập 37', 40, 'hoathinh', 'ongoing', 22, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wo Ba Mo Ri Shang Jiao Gei Le Guo Jia","我把末日上交给了国家"]', 1784690324119);
