INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lai-bi-giet-nua-a-thua-tham-tu-mata-korosarete-shimatta-no-desu-ne-tanteisama', 'Lại Bị Giết Nữa À, Thưa Thám Tử? (Mata Korosarete Shimatta no desu ne, Tantei-sama)', 'Killed Again, Mr. Detective.', 'https://phimimg.com/upload/vod/20260407-1/02fbec15b9bd3ee0f0d7ff0a361e7849.jpg', 'https://phimimg.com/upload/vod/20260407-1/4f566d4b42cdc2b6c4258def0d878a99.jpg', '<p>Sakuya Otsuki là con trai của một thám tử lừng danh, người đang tiếp bước cha mình cùng với cô trợ lý Lilithea. Tuy nhiên, chàng thám tử trung học này lại có một điểm &quot;khác biệt&quot; đến quái đản: Bất cứ nơi nào cậu đặt chân đến, cậu đều vướng vào các vụ án — nhưng không phải với tư cách thám tử, mà là nạn nhân bị sát hại.&nbsp; Khi Sakuya nhận nhiệm vụ thâm nhập vào một con tàu du lịch sang trọng, cậu lại một lần nữa bị giết. Thế nhưng, mỗi khi mở mắt ra, Lilithea đã luôn ở bên cạnh, sẵn sàng giúp cậu sống lại để truy tìm sự thật đến cùng...</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 24, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Rikuya Yasuda","avatar":""},{"name":"Shion Wakayama","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["又被杀掉了呢，侦探大人","Mata Korosarete Shimatta no desu ne, Tantei-sama","Matakoro","Mata Korosarete Shimatta no desu ne Tantei-sama","またころ","また殺されてしまったのですね、探偵様"]', 1784690324119);
