INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ichijouma-mankitsugurashi', 'Ichijouma Mankitsugurashi', 'Ichijouma Mankitsugurashi', 'https://phimimg.com/upload/vod/20260414-1/29b07b3c7c269e145b43a040311b48ee.jpg', 'https://phimimg.com/upload/vod/20260414-1/042274d110b2f594a24d416123a9e508.jpg', '<p>Meiko, một cô gái đến từ vùng nông thôn, được nhận vào học tại một ngôi trường nữ sinh danh giá với điều kiện cô phải tham gia vào chương trình tình nguyện của trường. Thế nhưng, thay vì làm các dịch vụ học đường thông thường, cô lại thấy mình đang sống và làm việc tại một tiệm cà phê truyện tranh (manga cafe)! Thật bất ngờ, cuộc sống trong một gian hàng nhỏ hẹp không hề tệ như cô tưởng — và với dàn nhân viên toàn là những nữ sinh trung học dễ thương, công việc này thậm chí còn trở nên vô cùng thú vị. Hãy cùng tận hưởng sức hút của một tiệm cà phê truyện tranh ngập tràn sắc màu nữ sinh!</p>', 'Tập 11', 13, 'hoathinh', 'ongoing', 15, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324119);
