INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-quyen-phap-bac-dau', 'Huyền Thoại Quyền Pháp Bắc Đẩu', 'Fist of the North Star: HOKUTO NO KEN / 北斗の拳', 'https://phimimg.com/upload/vod/20260607-1/184ac62770cdcba6924d9a9225366e98.jpg', 'https://phimimg.com/upload/vod/20260607-1/788b4ade09d3c4d3454fd3e10f0f2dd1.jpg', '<p>Năm 199X, thế giới chìm trong biển lửa hạt nhân!! &nbsp;Thế nhưng... nhân loại bằng cách nào đó vẫn sống sót!! Một người đàn ông đơn độc với bảy vết sẹo trên ngực xuất hiện. Tên anh ta là Kenshiro, người thừa kế của Hokuto Shinken. Trong một thế giới nơi chỉ kẻ mạnh mới tồn tại, Kenshiro tạo nên con đường riêng bằng nắm đấm sắt của mình!</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 17, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shunsuke Takeuchi","avatar":""},{"name":"Daiki Yamashita","avatar":""},{"name":"Mao Ichimichi","avatar":""},{"name":"Wataru Takagi","avatar":""},{"name":"Tsuguo Mogami","avatar":""},{"name":"Taiten Kusunoki","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["北斗神拳 -FIST OF THE NORTH STAR-","北斗神拳","Fist of the North Star - HOKUTO NO KEN","Fist of the North Star, HOKUTO NO KEN","Fist of the North Star HOKUTO NO KEN","Hokuto no Ken","Hokuto no Ken -FIST OF THE NORTH STAR-","Fist of the North Star (2026)","Fist of the Big Dipper  -FIST OF THE NORTH STAR-","北斗の拳 -FIST OF THE NORTH STAR-"]', 1784690324119);
