INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('diamond-no-ace-act-ii-second-season', 'Diamond no Ace: Act II Second Season', 'Ace of Diamond Act II Season 2', 'diamond no ace: act ii second season ace of diamond act ii season 2 ryota osaka takahiro sakurai nobunaga shimazaki natsuki hanae shintaro asanuma daiya no a ダイヤのa actⅱ dia no ace ace of diamond ダイヤのエース 다이아몬드 a 다이아몬드에이스 다이아몬드a 다이아 몬드 에이스 величайший бейсболист 鑽石王牌 act2 第二季 diamond no ace diamond''s ace ace of diamond act ii ace of the diamond act ii ダイヤのa', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buoi-hoa-nhac-ma-nhung-bai-hat-that-lac', 'Buổi Hòa Nhạc Ma: Những Bài Hát Thất Lạc', 'Ghost Concert: Missing Songs', 'https://phimimg.com/upload/vod/20260407-1/144c18214363250b12f99e9d426e1f5e.jpg', 'https://phimimg.com/upload/vod/20260407-1/8e8a8ae6a8f1f25d487ef137fa03be2e.jpg', '<p>Năm 2045, việc ca hát bị cấm đoán hoàn toàn, và hệ thống AI mang tên MiucS đã thay thế con người để tạo ra âm nhạc. Seria Aiba, một nữ sinh trung học có khả năng nhìn thấy linh hồn, vẫn luôn sống lặng lẽ dưới những quy luật khắc nghiệt này — cho đến một ngày, cô tình cờ nghe thấy một giọng hát thực sự của con người. Men theo tiếng hát, Seria đã tìm thấy nguồn phát: một hồn ma. Giờ đây, Seria phải đứng trước lựa chọn: tiếp tục im lặng hay đánh đổi mọi thứ để mang âm nhạc thực thụ trở lại với thế giới.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Minori Fujidera","avatar":""},{"name":"Rina Hidaka","avatar":""},{"name":"Nao Ojika","avatar":""},{"name":"Miyuki Sakurai","avatar":""},{"name":"Yuri An","avatar":""},{"name":"Satomi Sato","avatar":""},{"name":"Satoshi Hino","avatar":""},{"name":"Miyu Irino","avatar":""},{"name":"Emiri Suyama","avatar":""},{"name":"Minako Kotobuki","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["幽灵音乐会","幽灵音乐会：遗失的歌曲","GHOST CONCERT：missing Songs","ゴーストコンサート : missing Songs","GHOST CONCERT ： 失落之歌"]', 1784690324119);
