INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('buoi-hoa-nhac-ma-nhung-bai-hat-that-lac', 'Buổi Hòa Nhạc Ma: Những Bài Hát Thất Lạc', 'Ghost Concert: Missing Songs', 'buổi hòa nhạc ma: những bài hát thất lạc ghost concert: missing songs minori fujidera rina hidaka nao ojika miyuki sakurai yuri an satomi sato satoshi hino miyu irino emiri suyama minako kotobuki 幽灵音乐会 幽灵音乐会：遗失的歌曲 ghost concert：missing songs ゴーストコンサート : missing songs ghost concert ： 失落之歌', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-theo-doi-vi-hon-the-tu-nhan-minh-la-nu-phu-phan-dien', 'Nhật Ký Theo Dõi Vị Hôn Thê Tự Nhận Mình Là Nữ Phụ Phản Diện', 'Observation Records of My Fiancée: The Misadventures of a Self-Proclaimed Villainess (An Observation Log Of My Fiancée Who Calls Herself A Villainess)', 'https://phimimg.com/upload/vod/20260404-1/4c819f22455d19963d8514c9852163fd.jpg', 'https://phimimg.com/upload/vod/20260404-1/1dd2fc07faf2ab024f86f2dbc750c5a3.jpg', '<p>Thái tử Cecil là một thiên tài xuất chúng đến mức mọi thứ trong cuộc sống đối với anh đều dễ dàng đến mức nhàm chán. Thế rồi một ngày nọ, vị hôn thê của anh, Bertia, đột ngột tuyên bố: &quot;Thưa Thái tử Cecil, thiếp chính là một nữ phụ phản diện!&quot;&nbsp; Cô khẳng định rằng thế giới này giống hệt một &quot;otome game&quot; (trò chơi hẹn hò) từ tiền kiếp của mình và cô đang đóng vai &quot;nữ phụ phản diện&quot; trong đó. Mục tiêu của Bertia là hoàn thành tốt vai diễn của mình để cuộc đính hôn giữa hai người bị hủy bỏ. Với mục tiêu đó, cô bắt đầu gây ra hàng loạt rắc rối, làm đảo lộn cuộc sống thường nhật của Cecil.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 16, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yusuke Kobayashi","avatar":""},{"name":"Miyu Tomita","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jisho Akuyakureijo na Konyakusha no Kansatsukiroku.","Jishou Akuyaku Reijou na Konyakusha no Kansatsu Kiroku.","Fiance''s Observation Log of the Self-Proclaimed Villainess","Observation Records of My Fiancée: The Misadventures of a Self-Proclaimed Villainess","Observation Record of a Self-Proclaimed Villainess’ Fiance","自称悪役令嬢な婚約者の観察記録。"]', 1784690324119);
