INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buc-tuong-me-cung', 'Bức Tường Mê Cung', 'Wonder Wall', 'https://phimimg.com/upload/vod/20260608-1/bcd7384818519e27affebb095781aa16.jpg', 'https://phimimg.com/upload/vod/20260608-1/0725d5ba7030d8b83a89cde01385b422.jpg', '<p>Một cặp vợ chồng xui xẻo đủ đường tình cờ thế nào lại chuyển vào sống trong một căn biệt thự sang trọng. Không ngờ, họ lại phát hiện bên trong biệt thự đang cất giấu một khoản tiền khổng lồ. Từ đó, hàng loạt biến cố dồn dập kéo đến, khiến cả hai không còn phân biệt nổi đâu là giấc mộng đổi đời, và đâu là cơn ác mộng thực sự.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 17, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Quách Kính Phi","avatar":""},{"name":"Nhậm Tố Tịch","avatar":""},{"name":"Cốc Gia Thành","avatar":""},{"name":"Tất Dục Thần","avatar":""},{"name":"Ôn Tranh Vanh","avatar":""},{"name":"Lưu Thiên Tá","avatar":""},{"name":"Chi Peng","avatar":""},{"name":"Phương Phương","avatar":""},{"name":"Đổng Bác","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wonder Wall","迷墙"]', 1784690324119);
