INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-chu-kanan-thuc-ra-rat-de-du', 'Nữ Chủ Kanan Thực Ra Rất Dễ Dụ', 'Mistress Kanan Is Devilishly Easy', 'https://phimimg.com/upload/vod/20260407-1/a603d7fced9cca9ab0c455c1b70433d8.jpg', 'https://phimimg.com/upload/vod/20260407-1/034f4b9f33bc51c1275bf2f8fc08a869.jpg', '<p>Một “nữ chủ” tưởng chừng nguy hiểm nhưng lại mang đến những tình huống dở khóc dở cười bởi sự &quot;dễ dụ&quot;. Sự đối lập giữa vẻ ngoài quyến rũ và những phản ứng bất ngờ tạo nên một câu chuyện hài hước, nhẹ nhàng và đầy cuốn hút.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 14, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Aoi Koga","avatar":""},{"name":"Seiichiro Yamashita","avatar":""},{"name":"Sayumi Suzushiro","avatar":""},{"name":"Maki Kawase","avatar":""},{"name":"Ayaka Nanase","avatar":""},{"name":"Fuka Izumi","avatar":""},{"name":"Hikaru Tono","avatar":""},{"name":"Yoshino Nanjo","avatar":""},{"name":"Takaya Kuroda","avatar":""},{"name":"Yui Ogura","avatar":""},{"name":"Ayana Taketatsu","avatar":""},{"name":"Yu Kobayashi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["容易对付的恶魔大人","Kanan-sama wa Akumade Choroi","カナン様はあくまでチョロい"]', 1784690324119);
