INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khu-vuon-chu-than-cua-kusunoki', 'Khu Vườn Chư Thần Của Kusunoki', 'Kusunoki''s Garden Of Gods', 'https://phimimg.com/upload/vod/20260407-1/d54eca353906c82e4f6ac9468cab3618.jpg', 'https://phimimg.com/upload/vod/20260407-1/edae1e09b6fccf37d4631ef7c9424866.jpg', '<p>Một khu vườn huyền bí nơi thần linh và con người cùng tồn tại, mở ra những câu chuyện vừa kỳ ảo vừa sâu lắng. Mỗi cuộc gặp gỡ đều mang theo thông điệp riêng, khiến người xem dần chìm vào không gian đầy chất thơ và ý nghĩa.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 19, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shogo Sakata","avatar":""},{"name":"Shinshu Fuji","avatar":""},{"name":"Yuuichirou Umehara","avatar":""},{"name":"Shinnosuke Tokudome","avatar":""},{"name":"Makoto Koichi","avatar":""},{"name":"Minako Kotobuki","avatar":""},{"name":"Yoshiki Nakajima","avatar":""},{"name":"Daiki Kobayashi","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Kami no Niwatsuki Kusunoki-tei","Сад Богів Кусунокі","神の庭付き楠木邸"]', 1784690324119);
