INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-ke-cua-akane', 'Chuyện Kể Của Akane', 'Akane-banashi', 'https://phimimg.com/upload/vod/20260406-1/4abaebf131a964fa54695cf899dbdaf7.jpg', 'https://phimimg.com/upload/vod/20260406-1/4a85124c6909360ca8f62b21c7ff86b2.jpg', '<p>Từ khi còn nhỏ, Akane Osaki đã bị mê hoặc bởi những màn trình diễn đầy ma thuật của cha mình, Shinta Arakawa. Tuy nhiên, cô đã phải chứng kiến một sự cố gây sốc ngay trong buổi biểu diễn quyết định để cha cô được thăng cấp lên danh hiệu shin&#39;uchi (bậc thầy).&nbsp; Sáu năm sau, giờ đây đã là một nữ sinh trung học, Akane đặt mục tiêu tự mình trở thành một shin&#39;uchi — dấn thân vào thế giới đầy cạnh tranh khốc liệt của nghệ thuật kể chuyện đơn độc Rakugo.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 21, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Anna Nagase","avatar":""},{"name":"Takuya Eguchi","avatar":""},{"name":"Rie Takahashi","avatar":""},{"name":"Jun Fukuyama","avatar":""},{"name":"Nobunaga Shimazaki","avatar":""},{"name":"Chiaki Kobayashi","avatar":""},{"name":"Yohei Azakami","avatar":""},{"name":"Seiichiro Yamashita","avatar":""},{"name":"Akihisa Shiono","avatar":""},{"name":"Masaki Terasoma","avatar":""},{"name":"Akio Otsuka","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["朱音落语","Akane-banashi","Tales of Akane","Akane Story","あかね噺"]', 1784690324119);
