INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-ke-cua-akane', 'Chuyện Kể Của Akane', 'Akane-banashi', 'chuyện kể của akane akane-banashi anna nagase takuya eguchi rie takahashi jun fukuyama nobunaga shimazaki chiaki kobayashi yohei azakami seiichiro yamashita akihisa shiono masaki terasoma akio otsuka 朱音落语 akane-banashi tales of akane akane story あかね噺', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-ra-the-thong-gi-nua-phan-2', 'Còn Ra Thể Thống Gì Nữa (Phần 2)', 'How Dare You! (Season 2)', 'https://phimimg.com/upload/vod/20260125-1/13a49743588595a8eb026d73bc0a6a0b.jpg', 'https://phimimg.com/upload/vod/20260125-1/9dcbcb16f91ede9be5f896569e486cb9.jpg', '<p>Còn Ra Thể Thống Gì Nữa? (How Dare You?!) kể về câu chuyện xoay quanh Dữu Vãn Âm. Một ngày nọ, Dữu Vãn Âm bỗng xuyên không vào tiểu thuyết cung đấu. Vì để đảo ngược số phận mà cô đã chọn hợp lực với một tên bạo chúa nhưng lại không thể ngờ rằng hoàng đế và nữ chính trong truyện cũng là xuyên sách mà tới. Cô vẫn luôn hy vọng rằng ba người hiện đại có thể gác lại những tranh chấp trong hoàng cung và ngồi lại cùng nhau để cùng chơi đấu địa chủ và ăn lẩu. Tuy nhiên, nữ chính trong truyện tin rằng mình là người được chọn và lựa chọn chống lại hoàng đế và Vãn Âm... Dữu Vãn Âm vì để có thể sống sót mà phải ra chiêu, cũng vừa là cứu mình mà cũng là giúp Đại Hạ tránh khỏi cuộc kiếp nạn.</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 26, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Cheng He Ti Tong","成何体统 第2季","成何体统动画","Cheng He Titong","成何体统","성하체통: 체통따위는 없다","¿Como te atreves?","ทะลุมิติตะลุยวังหลวง","What A Scandal","How Dare You","How dare you!？"]', 1784690324119);
