INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('con-ra-the-thong-gi-nua-phan-2', 'Còn Ra Thể Thống Gì Nữa (Phần 2)', 'How Dare You! (Season 2)', 'còn ra thể thống gì nữa (phần 2) how dare you! (season 2)  cheng he ti tong 成何体统 第2季 成何体统动画 cheng he titong 成何体统 성하체통: 체통따위는 없다 ¿como te atreves? ทะลุมิติตะลุยวังหลวง what a scandal how dare you how dare you!？', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-hien-gia-riddle-hoi-quy-bao-thu-daikenja-riddle-no-jikan-gyakkou', 'Đại Hiền Giả Riddle Hồi Quy Báo Thù (Daikenja Riddle no Jikan Gyakkou)', 'The Regression Of Great Sage Riddle (The Time Reversal Of The Great Sage Riddle)', 'https://phimimg.com/upload/vod/20260407-1/0465acf01f7208424c1a2207bf1b23fa.jpg', 'https://phimimg.com/upload/vod/20260407-1/8afa96862e0268ea258b4a802d0e8d99.jpg', '<p>Hãy lấy lại tất cả những gì đã mất — trong lần thứ hai dấn thân vào thế giới này. Tổ chức bí ẩn mang tên “Chiếc Hộp Hiểm Độc” đã cướp đi mọi thứ của chàng trai trẻ Ryddel: từ đồng đội, thế giới cho đến cả tương lai của anh. Đứng bên bờ vực tuyệt vọng, anh nảy ra một ý tưởng cuối cùng: Liệu mình có thể quay trở về thời điểm trước khi mọi thứ bị hủy diệt?&nbsp; Sau khi sống sót qua ngàn năm và biến đổi thành một thực thể vượt xa loài người, Ryddel cuối cùng đã thành công trong việc đảo ngược thời gian. “Lần này... ta sẽ ngăn chặn tất cả!” Mang theo kiến thức và kinh nghiệm của một thiên niên kỷ vào cơ thể thời niên thiếu, Đại hiền giả Ryddel chính thức bắt đầu cuộc hành trình xoay chuyển định mệnh!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 15, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Junya Enoki","avatar":""},{"name":"Azusa Tadokoro","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["大贤者里德尔的时空逆行","Daikenja Riddle no Jikan Gyakkou","Daikenja Riddle no Jikan Gyakkō","The Regression of Great Sage Riddle","The Great Sage Ryddel and the Hands of Time","大賢者リドルの時間逆行"]', 1784690324119);
