INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-le-anh-no-em', 'Hôn lễ anh nợ em', 'Dog Man', 'https://phimimg.com/upload/vod/20260620-1/d94cd00c7bc499458606a607b8701fba.jpg', 'https://phimimg.com/upload/vod/20260620-1/69fafef85a370acbfe31e240085cfc64.jpg', '<p>Giữa thành phố sôi động đầy khát vọng, một nhạc sĩ đang lên và những người thân cận đối mặt với áp lực ngày càng lớn khi hình ảnh trước công chúng trái ngược với đời tư chật vật.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 32, 2026, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Joseph Chang Hsiao-Chuan","avatar":""},{"name":"Tarcy Su","avatar":""},{"name":"Berant Zhu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Dogman","欠妳的那場婚禮"]', 1784690324119);
