INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-phong-quy-mau-rung-thieng', 'Phí Phông: Quỷ Máu Rừng Thiêng', 'Phi Phong: The Blood Demon', 'https://phimimg.com/upload/vod/20260620-1/f9f017b676af1005b05491f5a520cc7f.jpg', 'https://phimimg.com/upload/vod/20260620-1/3ed9a180dfc699fbc0502962e67d86b7.jpg', '<p>Phí Phông, loài quỷ khát máu trong truyền thuyết dân gian của đồng bào miền núi gây ám ảnh bao đời nay. Phim xoay quanh Còn (Kiều Minh Tuấn) và Dương (Minh Anh), hai pháp sư tập sự lên núi cứu người mẹ đang bị lời nguyền Phí Phông đánh gục. Cùng lúc đó, trong bản sâu cũng xảy ra nhiều cái chết ghê rợn. Mọi nghi ngờ đổ dồn về hai mẹ con Mon (Diệp Bảo Ngọc) và Lua (Nina Nutthacha), những người mang đặc tính y hệt Phí Phông. Thế nhưng, vẫn còn những bí mật động trời bị chôn vùi trong chốn rừng thiêng nước độc, cuốn hai anh em Còn và Dương vào cuộc truy lùng “Phí Phông” không hồi kết.</p>', 'Full', 1, 'single', 'completed', 176, 2026, 'Vietsub', 'CAM', 'Việt Nam', 1, '[{"name":"Kiều Minh Tuấn","avatar":""},{"name":"Nutthacha Padovan","avatar":""},{"name":"Diệp Bảo Ngọc","avatar":""},{"name":"Trần Gia Huy","avatar":""},{"name":"Minh Anh","avatar":""},{"name":"Ngô Phạm Hạnh Thúy","avatar":""},{"name":"Cris Phan","avatar":""},{"name":"Minh Coca","avatar":""},{"name":"Nguyễn Sỹ Hậu","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Phi Phong: The Blood Demon","Phí Phông: Quỷ Máu Rừng Thiêng"]', 1784690324119);
