INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cung-nguoi-vuot-kiep', 'Cùng Người Vượt Kiếp', 'Journey With You', 'https://phimimg.com/upload/vod/20260604-1/a5c8351ba2208c3c223af74d1cf69e33.jpg', 'https://phimimg.com/upload/vod/20260604-1/811a60164649b3028e75c2eb88e2e9a3.jpg', '<p>Nhân vật trung tâm là Ân Kỳ – một hoàng tử thất sủng sống trong triều đình đầy âm mưu. Người duy nhất luôn đứng về phía anh là Bùi Ngạn Chi, một cận thần lạnh lùng nhưng trung thành tuyệt đối. Ở kiếp đầu, vì tranh quyền đoạt vị và hiểu lầm trong cung, Bùi Ngạn Chi bị hãm hại rồi chết thảm. Ân Kỳ cũng mất tất cả và mang theo hối hận lớn nhất đời mình.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 16, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tang Bide","avatar":""},{"name":"Wang Jinghan","avatar":""},{"name":"Duan Tongzhou","avatar":""},{"name":"Li Youcheng","avatar":""},{"name":"Wang Yuezhi","avatar":""},{"name":"Zhao Jiayi","avatar":""},{"name":"Luo Siqi","avatar":""},{"name":"Zuo Zhouyuan","avatar":""},{"name":"Du Yiheng","avatar":""},{"name":"Liu Chen","avatar":""},{"name":"Xie Xiaohan","avatar":""},{"name":"Xie Weina","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["风定花开","与君同"]', 1784690324119);
