INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muon-dung-nhan', 'Mượn Dung Nhan', 'Visage And Soul', 'https://phimimg.com/upload/vod/20260606-1/c1cf62cf11d7d6974c84ec341dd17a04.jpg', 'https://phimimg.com/upload/vod/20260606-1/2b35e460e8b4d0d3b9785edc7aff5216.jpg', '<p>Sau khi mất trí nhớ, Kiều Tiểu Mễ bị anh trai Kiều Chí Uy gây khó dễ ngay trong đám tang của bố. Đúng lúc đó, chồng sắp cưới của cô là Tần Dữ mất tích ba năm trời bất ngờ xuất hiện giải vây cho cô. Với sự giúp đỡ của Tần Dữ, ký ức của Tiểu Mễ dần hé lộ về vụ hỏa hoạn chết người trong quá khứ. Thế nhưng, sự xuất hiện của Tần Dữ thực chất lại là sắp đặt của Kiều Chí Uy. Khi sự thật dần được phơi bày, tình yêu nảy sinh từ những lời dối trá ấy cũng đứng trước lựa chọn đầy nghiệt ngã.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 22, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Nhậm Vận Kiệt","avatar":""},{"name":"Thích Nghiên Địch","avatar":""},{"name":"Tân Hạo Giang","avatar":""},{"name":"An Kiều Nhi","avatar":""},{"name":"Liễu Kỳ","avatar":""},{"name":"Vương Diệu","avatar":""},{"name":"Ngụy Tử Tường","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["不一样的她之借颜","Jie Yan","The Unique Her","借颜"]', 1784690324119);
