INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('goi-ngay-bac-si-khuong', 'Gọi Ngay Bác Sĩ Khương!', 'Call For Dr. Jiang', 'https://phimimg.com/upload/vod/20260616-1/717e6db1d2a7d5d79b349afb8ee562a2.jpg', 'https://phimimg.com/upload/vod/20260616-1/07620970358d7bbd946ffe19967eb62d.jpg', '<p>Bác sĩ phẫu thuật răng hàm mặt Khương Thiên Tài, người có thiên phú xuất chúng nhưng tính cách kiêu ngạo, bất ngờ rơi vào giai đoạn thất bại nhất cuộc đời. Sau nhiều biến cố, anh đến một bệnh viện nha khoa tại thành phố ven biển nhỏ để bắt đầu lại từ đầu. Trong không gian phòng khám nhỏ bé, anh dần mài giũa bản thân bằng sự tận tâm với nghề và học được cách đồng cảm với bệnh nhân trong hành trình bảo vệ sức khỏe răng miệng cho họ. Giữa nhịp sống bình dị của thị trấn ven biển và hơi ấm của ngành y, Khương Thiên Tài từng bước trưởng thành, trở thành một người thầy thuốc vừa giỏi chuyên môn vừa giàu y đức và lòng nhân ái.</p>', 'Hoàn Tất (19/19)', 19, 'series', 'completed', 25, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Phan Tử Kiếm","avatar":""},{"name":"Lâm Hân Nghi","avatar":""},{"name":"Lưu Kình","avatar":""},{"name":"Wei Xiaoxuan","avatar":""},{"name":"Diêm Hải Minh","avatar":""},{"name":"Diệu Tịnh Âu","avatar":""},{"name":"Deng Liyuan","avatar":""},{"name":"Vương Hoành Triết","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hu jiao yi sheng jian tian cai","Call Dr. Jiang Tiancai","Call Dr Jiang Tiancai","呼叫！医生姜天才"]', 1784690324119);
