INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-nhan-chi-ha-phan-6-nguoi-tren-van-nguoi', 'Nhất Nhân Chi Hạ (Phần 6) (Người Trên Vạn Người)', 'The Outcast (Season 6) (Hitori No Shita)', 'https://phimimg.com/upload/vod/20260110-1/1c5432188e44458e51aa2119a8ac3aab.jpg', 'https://phimimg.com/upload/vod/20260110-1/a38472e5429e9d6645ed16ef2c47935e.jpg', '<p>Sau biến cố tại Bích Du Thôn, Trương Sở Lam tiếp tục hành trình tìm kiếm bí mật về thân thế của Phùng Bảo Bảo. Lần này, anh tới bái kiến lão nhân gia Lục Cẩn và may mắn có được danh sách của &quot;Ba mươi sáu tặc&quot;. Cũng từ đây, Trương Sở Lam tình cờ phát hiện ra chân tướng sự việc Kim Phượng bị bắt cóc. Để ngăn chặn những báu vật của Vô Căn Sinh rơi vào tay kẻ xấu, nhóm của Trương Sở Lam đã quyết định dấn thân vào sâu trong dãy núi Tần Lĩnh, hướng về phía Nhị Thập Tứ Tiết Cốc đầy rẫy hiểm nguy...</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 25, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xiao Liansha","avatar":""},{"name":"Sheng Feng","avatar":""},{"name":"Yuntu Cao","avatar":""},{"name":"Shan Xin","avatar":""},{"name":"Ajie","avatar":""},{"name":"Wang Chenguang","avatar":""},{"name":"Baomu Zhongyang","avatar":""},{"name":"Teng Xin","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["一人之下","Fengqi Yunyong, Luotian Dajiao","异人","Yi Ren Zhi Xia","