INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-hoach-gau-truc-2-bo-toc-ky-dieu', 'Kế Hoạch Gấu Trúc 2: Bộ tộc kỳ diệu', 'Panda Plan 2: The Magical Tribe', 'https://phimimg.com/upload/vod/20260619-1/bb60f4ba8bf08944e1c39d594b015d20.jpg', 'https://phimimg.com/upload/vod/20260619-1/d558ca71d78a9d6555fe6782af545f3a.jpg', '<p>Chú gấu trúc &quot;Huhu&quot; sắp chuyển đến chuồng nuôi mới thì bất ngờ bị một tên cướp quốc tế tấn công. Trong lúc giao chiến với bọn cướp, Huhu ngã xuống vách đá, rồi tỉnh dậy và phát hiện mình đang ở trong một bộ lạc bí ẩn. Để trở về chuồng, nhóm người thú vị này giúp bộ lạc giải quyết nhiều vấn đề khác nhau...</p>', 'Full', 1, 'single', 'completed', 34, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"Ma Li","avatar":""},{"name":"Qiao Shan","avatar":""},{"name":"Yu Yang","avatar":""},{"name":"Wang Yinglu","avatar":""},{"name":"Zhang Zidong","avatar":""},{"name":"Ke Da","avatar":""},{"name":"Song Muzi","avatar":""},{"name":"Wang Chengsi","avatar":""},{"name":"Feng Man","avatar":""},{"name":"Wang Xing","avatar":""},{"name":"JJ Lin","avatar":""},{"name":"Ma Chi","avatar":""},{"name":"Yu Rongguang","avatar":""},{"name":"Pan Binlong","avatar":""},{"name":"Hu Xiaoyuan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Panda Project 2","Panda Plan 2","熊猫计划2","แพนด้าเด้งยกกำลังฟัด","熊猫计划2：部落奇遇记","熊猫计划之部落奇遇记"]', 1784690324119);
