INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('monster-eater', 'Monster Eater', 'Monster Eater', 'https://phimimg.com/upload/vod/20260404-1/cdb42be74223b974d82efb2b04b966d6.jpg', 'https://phimimg.com/upload/vod/20260404-1/9459c291889ef9b32674f9e7afa4696d.jpg', '<p>Rude, một mạo hiểm giả hạng E. Kỹ năng duy nhất của anh, &quot;Vô hiệu hóa trạng thái bất thường&quot;, là một khả năng cực kỳ hạn hẹp, vốn chỉ được coi là hữu ích cho việc hái thảo dược trong những hầm ngục đầy chướng khí. Với khả năng chiến đấu gần như bằng không, đồng đội thường chế nhạo anh bằng biệt danh &quot;Kẻ nhặt rác trong chướng khí&quot;.&nbsp; Trong một nỗ lực tuyệt vọng để thay đổi cuộc đời, Rude dấn thân vào một hầm ngục mới — để rồi bị chính tổ đội của mình phản bội và bỏ mặc cho đến chết. Khi nhu yếu phẩm đã cạn kiệt và sự sống dần lụi tàn, anh đã đưa ra một lựa chọn cấm kỵ: ăn thịt quái vật.&nbsp; Từ đây bắt đầu cuộc hành trình mạo hiểm mang tên &quot;Nuốt chửng quái vật&quot; của Rude, nơi anh chiếm đoạt được những kỹ năng mới chỉ bằng cách ăn thịt kẻ thù của mình!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 14, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Makoto Furukawa","avatar":""},{"name":"Yuki Nakashima","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mamonogurai no Boukensha: Ore dake Mamono wo Kuratte Tsuyoku Naru","Mamono Kurai no Boukensha: Ore Dake Mamono o Kuratte Tsuyoku Naru","まものくらいのぼうけんしゃ～おれだけまものをくらってつよくなる～","Monster Eater Adventurer","魔物喰らいの冒険者～俺だけ魔物を喰らって強くなる～"]', 1784690324119);
