INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('monster-eater', 'Monster Eater', 'Monster Eater', 'monster eater monster eater makoto furukawa yuki nakashima mamonogurai no boukensha: ore dake mamono wo kuratte tsuyoku naru mamono kurai no boukensha: ore dake mamono o kuratte tsuyoku naru まものくらいのぼうけんしゃ～おれだけまものをくらってつよくなる～ monster eater adventurer 魔物喰らいの冒険者～俺だけ魔物を喰らって強くなる～', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kirio-fan-club', 'Kirio Fan Club', 'Kirio Fan Club', 'https://phimimg.com/upload/vod/20260404-1/ba89de75fa55ab9ba0082b9050052c4e.jpg', 'https://phimimg.com/upload/vod/20260404-1/0be4fc2978bcd7e0feb3bb9cdde40265.jpg', '<p>Bạn sẽ làm gì nếu người trong mộng của mình có những cú &quot;xì hơi&quot; vang trời? Với Aimi và Nami, câu trả lời chính là khóc trong hạnh phúc vì có thể định vị được Kirio – đối tượng thầm thương trộm nhớ của họ – từ khoảng cách xa chỉ qua một tiếng &quot;tủm&quot;.&nbsp; Đây chính là kiểu câu hỏi triết học sâu sắc mà hai cô bạn thân (kiêm tình địch) này thường đặt ra cho nhau để chứng minh tình yêu dành cho chàng trai dường như chẳng hề hay biết đến sự tồn tại của họ. Tuy nhiên, điều đó không thể ngăn cản họ thực hiện các nghi lễ hàng đêm để mời gọi anh bước vào giấc mơ, hay liệt kê chi tiết những gì họ thích ở anh, tỉ mỉ đến từng... cơ quan nội tạng.&nbsp; Nhưng khi đối mặt với thời khắc quyết định, liệu họ sẽ lựa chọn tình bạn đầy hài hước này hay đánh đổi nó để lấy một cơ hội có được tình yêu?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 18, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Nene Hieda","avatar":""},{"name":"Shion Wakayama","avatar":""},{"name":"Gakuto Kajiwara","avatar":""},{"name":"Yuya Hirose","avatar":""},{"name":"Jin Ogasawara","avatar":""},{"name":"Ayasa Ito","avatar":""},{"name":"Fuka Izumi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["雾尾粉丝俱乐部","Kirio Fanclub","霧尾ファンクラブ"]', 1784690324119);
