INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('haibara-choi-lai-tuoi-teen', 'Haibara Chơi Lại Tuổi Teen', 'Haibara''s Teenage New Game+', 'https://phimimg.com/upload/vod/20260404-1/4ceed603850e15b1ccb46c0b4ed26946.jpg', 'https://phimimg.com/upload/vod/20260404-1/63d1ec4012030b5ff7934bcc4252606c.jpg', '<p>Natsuki Haibara luôn tự nhủ rằng những năm tháng trung học của mình là một thất bại thảm hại — cho đến khi cậu đột nhiên tỉnh dậy và nhận ra mình đã trở lại là một nam sinh năm nhất, với toàn bộ kiến thức và trải nghiệm tích lũy được từ thời đại học. Quyết tâm viết lại cuộc đời, Natsuki dấn thân vào nhóm bạn nổi tiếng trong trường, kết giao với những người bạn mà kiếp trước cậu chưa từng có, và tìm cách thu hẹp khoảng cách với người con gái mình thầm thương trộm nhớ. Thế nhưng, cơ hội thứ hai không đơn giản như việc nhấn nút &quot;Khởi động lại&quot;. Liệu Natsuki có thể biến những hối tiếc trong quá khứ thành một thời thanh xuân rực rỡ sắc màu hay không?!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 14, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuto Uemura","avatar":""},{"name":"Kanon Takao","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["灰原君的青春二周目","灰原同学重返过去，开启所向无敌的第二轮青春游戏","Haibara-kun no Tsuyokute Seishun New Game","Haibarakun no Tsuyokute Seisyun NewGame","灰原くんの強くて青春ニューゲーム"]', 1784690324119);
