INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('haibara-choi-lai-tuoi-teen', 'Haibara Chơi Lại Tuổi Teen', 'Haibara''s Teenage New Game+', 'haibara chơi lại tuổi teen haibara''s teenage new game+ yuto uemura kanon takao 灰原君的青春二周目 灰原同学重返过去，开启所向无敌的第二轮青春游戏 haibara-kun no tsuyokute seishun new game haibarakun no tsuyokute seisyun newgame 灰原くんの強くて青春ニューゲーム', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngu-linh-the-gioi', 'Ngự Linh Thế Giới', 'B.King / Tamers / Spirit Master / Yu Ling Shi', 'https://phimimg.com/upload/vod/20260607-1/e1321f372a37cf10e07871b8a14ff00e.jpg', 'https://phimimg.com/upload/vod/20260607-1/9489dfc0af9573abb938934c5569aa9a.jpg', '<p>Câu chuyện kể về một họa sĩ truyện tranh nổi tiếng, người đã trở nên lừng danh với bộ truyện tranh B.King. Tuy nhiên, sau nhiều năm, ông cạn kiệt ý tưởng và chỉ có thể dựa vào việc liên tục bỏ rơi các nhân vật của mình để thu hút sự chú ý. Một ngày nọ, ông nhận được một cuộc điện thoại bí ẩn và bị hút vào thế giới của B.King với thân phận một nhân vật tên là Vương Hiểu Long. Từ đó, Vương Hiểu Long, người giờ đây mang trong mình suy nghĩ của “người sáng tạo”, cùng với các nhân vật do chính mình tạo ra, bắt đầu một cuộc phiêu lưu kỳ ảo có thể được miêu tả là “Đường tắt của Thượng Đế, một bước lên thiên đường”.</p>', 'Tập 18', 18, 'hoathinh', 'ongoing', 21, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wang Ning","avatar":""},{"name":"Wang Junyao","avatar":""},{"name":"Li Hanlin","avatar":""},{"name":"Ma Zhengyang","avatar":""},{"name":"Xiao Liansha","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Yu Ling Shi","정령사:나타르 전기","Tamers","Spirit Master","BKing","驭灵师"]', 1784690324119);
