INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cha-se-tim-con', 'Cha Sẽ Tìm Con', 'I Will Find You', 'https://phimimg.com/upload/vod/20260619-1/0a4bfab3456c798bb20ac93e24c3ad46.jpg', 'https://phimimg.com/upload/vod/20260619-1/3312cfb64b0cd159bcf0ace038e61587.jpg', '<p>Bị ngồi tù oan vì tội giết chính con trai mình, một người cha dấn thân vào sứ mệnh giải cứu tuyệt vọng sau khi biết tin cậu bé có thể vẫn còn sống.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 41, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sam Worthington","avatar":""},{"name":"Britt Lower","avatar":""},{"name":"Logan Browning","avatar":""},{"name":"Erin Richards","avatar":""},{"name":"Milo Ventimiglia","avatar":""},{"name":"Jonathan Tucker","avatar":""},{"name":"Chi McBride","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["הרלן קובן: אני אמצא אותך","Я найду тебя","Я тебе відшукаю","Harlan Coben''s I Will Find You","I Will Find You"]', 1784690324119);
