INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ap-luc', 'Áp Lực', 'Pressure', 'https://phimimg.com/upload/vod/20260618-1/aed95ad6945378f3fc26c9cd0967aa5d.jpg', 'https://phimimg.com/upload/vod/20260618-1/7bdd3440d74aa893c7d0d175af22c63b.jpg', '<p>Bối cảnh diễn ra trong 72 giờ trước cuộc đổ bộ Normandy (D-Day) ngày 6/6/1944. Khi quân Đồng minh đã sẵn sàng cho chiến dịch quân sự lớn nhất lịch sử, chỉ còn một yếu tố chưa chắc chắn: thời tiết. Nhân vật trung tâm là nhà khí tượng học James Stagg và Tướng Dwight D. Eisenhower. Stagg phải đưa ra dự báo thời tiết chính xác nhất trong sự nghiệp của mình, vì một quyết định sai có thể khiến hàng chục nghìn binh sĩ thiệt mạng và làm thay đổi cục diện chiến tranh. Eisenhower phải lựa chọn giữa việc phát động cuộc tấn công ngay lập tức hay trì hoãn và đối mặt với nguy cơ thất bại chiến lược.</p>', 'Full', 1, 'single', 'completed', 51, 2026, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Andrew Scott","avatar":""},{"name":"Brendan Fraser","avatar":""},{"name":"Kerry Condon","avatar":""},{"name":"Chris Messina","avatar":""},{"name":"Damian Lewis","avatar":""},{"name":"Con O''Neill","avatar":""},{"name":"Tamsin Topolski","avatar":""},{"name":"Henry Ashton","avatar":""},{"name":"Michael Benz","avatar":""},{"name":"Wil Coban","avatar":""},{"name":"Joshua Hill","avatar":""},{"name":"Daniel Quinn-Toye","avatar":""},{"name":"Sebastian Orozco","avatar":""},{"name":"Max Croes","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["A Pressão","Pressure"]', 1784690324119);
