INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-ha-nhap-mong', 'Tinh Hà Nhập Mộng', 'Per Aspera Ad Astra', 'https://phimimg.com/upload/vod/20260618-1/a5a87f8529c3a304ab26bfba197d3ecb.jpg', 'https://phimimg.com/upload/vod/20260618-1/13549224aa58e15faa55a4a73891fce4.jpg', '<p>Khi một hệ thống AI gặp sự cố đe dọa tàu vũ trụ, kỹ thuật viên nọ phải bước vào giấc mơ của một thành viên phi hành đoàn để lấy mã khóa và giải cứu các hành khách.</p>', 'Full', 1, 'single', 'completed', 21, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dylan Wang","avatar":""},{"name":"Victoria Song","avatar":""},{"name":"Zu Feng","avatar":""},{"name":"Luo Haiqiong","avatar":""},{"name":"Wang Duo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Per Aspera Ad Astra","Xing He Ru Meng","宇宙生存指南","星河入梦"]', 1784690324119);
