INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('huyen-thoai-linh-bep-anh-nuoi-thang-cap-thanh-huyen-thoai', 'Huyền Thoại Lính Bếp (Anh Nuôi - Thăng Cấp Thành Huyền Thoại)', 'The Legend of Kitchen Soldier', 'huyền thoại lính bếp (anh nuôi - thăng cấp thành huyền thoại) the legend of kitchen soldier park ji-hoon lee hong-nae yoon kyung-ho han dong-hee lee sang-yi jung woong-in kang ha-kyung lim ji-ho kang joon-kyu lee sang-jun han min park so-ri jeon so-young seo jeong-yeon choi deok-moon 菜鸟炊事兵 超新丁伙頭兵 伝説のキッチンソルジャー أسطورة جندي المطبخ the military cook becomes a legend becoming a cooking soldier legend the legendary cook soldier the cook becomes a legend 취사병 전설이 되다', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rezero-bat-dau-lai-o-the-gioi-khac-phan-4', 'ReZERO - Bắt Đầu Lại Ở Thế Giới Khác (Phần 4)', 'ReZERO - Starting Life In Another World (Season 4)', 'https://phimimg.com/upload/vod/20260423-1/b2ee47fa752ddfa5793c46ae57537dde.jpg', 'https://phimimg.com/upload/vod/20260423-1/ffd6a732d5b223183fdcde2169e43b61.jpg', '<p>Re:Zero Mùa 4 sẽ tập trung vào Arc 6 (Hành lang ký ức), đưa Subaru và nhóm bạn tiến về phía đông đến Tháp canh Pleiades giữa sa mạc cát chết chóc để tìm cách giải cứu những người bị ăn mất &quot;tên&quot; và &quot;ký ức&quot;. Tại đây, họ phải đối mặt với 5 thử thách khắc nghiệt từ người canh giữ tòa tháp là Shaula và huyền thoại Reid Astrea, đồng thời Subaru sẽ rơi vào trạng thái tuyệt vọng tột cùng khi chính bản thân anh bị mất trí nhớ, không còn nhớ mình là ai hay khả năng &quot;Trở về từ cõi chết&quot;. Đây được đánh giá là phần nội dung đen tối và kịch tính nhất từ trước đến nay, nơi ranh giới giữa cái chết và sự điên loạn trở nên mong manh hơn bao giờ hết.</p>', 'Tập 11', 19, 'hoathinh', 'ongoing', 23, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yusuke Kobayashi","avatar":""},{"name":"Rie Takahashi","avatar":""},{"name":"Yumi Uchiyama","avatar":""},{"name":"Chinatsu Akasaki","avatar":""},{"name":"Yuichi Nakamura","avatar":""},{"name":"Inori Minase","avatar":""},{"name":"Rie Murakawa","avatar":""},{"name":"Takehito Koyasu","avatar":""},{"name":"Satomi Arai","avatar":""},{"name":"Kohei Amasaki","avatar":""},{"name":"Nobuhiko Okamoto","avatar":""},{"name":"Kaori Nazuka","avatar":""},{"name":"Aimi Tanaka","avatar":""},{"name":"Maaya Sakamoto","avatar":""},{"name":"Marika Kouno","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lư