INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hinh-phat-vi-yeu-em', 'Hình Phạt Vì Yêu Em', 'Love''s Shattered Reflections', 'hình phạt vì yêu em love''s shattered reflections naphat siangsomboon ranchrawee uakoolwarawat tarkoon karntip marilyn kate gardner louis scott phulita supinchompoo ekkaphong jongkesakorn supachai suwanon chinnaphat kitichaivaranggoon stephanie lerce supoj janjareonborn santi santivejakul tan thot than thi rak thoe โทษฐานที่รักเธอ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('de-xong-mat-ca-to-nhung-ca-toi-cau-duoc-lai-con-to-hon', 'Để Xổng Mất Cá To, Nhưng Cá Tôi Câu Được Lại Còn To Hơn', 'Always A Catch!', 'https://phimimg.com/upload/vod/20260404-1/45dcc3e57567aa73d658e771ce5c7643.jpg', 'https://phimimg.com/upload/vod/20260404-1/c793f2d15c2d6800e7cccc0f2270790c.jpg', '<p>&quot;Mọi chuyện bắt đầu từ một màn hủy hôn đầy bất ngờ.&quot;

Maria, hay còn gọi là Mimi, là tiểu thư của gia tộc Công tước Annovazzi, một gia tộc nổi tiếng về võ đạo. Dù là con út nhưng lại bộc lộ &quot;tài năng võ thuật&quot; nên được nuôi dạy để làm người thừa kế. Thế nhưng khi em trai chào đời, cô đột ngột phải nhường lại vị trí đó. Cha cô ra lệnh phải tìm cho bằng được một mối thật ngon, nhưng những công tử quý tộc sáng giá trong vương quốc Muro gần như đã có nơi có chốn hết rồi. Vì vậy cô đành nhờ người họ hàng xa là Aida, sang du học ở vương quốc láng giềng Rubini để tiếp tục hành trình tìm chồng. Nào ngờ ngay tại buổi tiệc tốt nghiệp của Học viện Hoàng gia, hoàng tử Renato, người cô mới gặp lần đầu, lại đột ngột tuyên bố hủy hôn với cô, dù hai người vốn chưa từng đính hôn!

Chưa có hôn ước gì mà đã đòi hủy, con đường tìm chồng của Maria rồi sẽ đi về đâu đây?

Một romcom náo loạn của tiểu thư giỏi võ chính thức bắt đầu!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 11, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yu Serizawa","avatar":""},{"name":"Atsushi Tamaru","avatar":""},{"name":"Saori Hayami","avatar":""},{"name":"Shuichiro Umeda","avatar":""},{"name":"Taku Yashiro","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["关于虽然逃走的鱼很大、但钓上来的鱼却太大了这件事","溜掉的大鱼比不上自己钓到的鱼","Nigashita Sakana wa Ookikatta ga Tsuriageta Sakana ga Ookisugita Ken","Nigetsuri","Nigashita Sakana wa Ōkikatta ga Tsuriageta Sakana ga Ōkisugita Ken","逃がした魚は大きかったが釣りあげた魚が大きすぎた件"]', 1784690324119);
