INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hut-thuoc-phia-sau-sieu-thi-cung-em-super-no-ura-de-yani-suu-futari', 'Hút Thuốc Phía Sau Siêu Thị Cùng Em (Super no Ura de Yani Suu Futari)', 'Smoking Behind The Supermarket With You', 'https://phimimg.com/upload/vod/20260616-1/d63cb6d4195e442d3b35aa5c24756a17.jpg', 'https://phimimg.com/upload/vod/20260616-1/a83abbda83a8271d4a0aecbeb56ed616.jpg', '<p>Gặp gỡ Sasaki, một nhân viên văn phòng trung niên làm việc quá sức. Ngày của anh chỉ toàn là những công việc nhàm chán, tẻ nhạt ở công ty. Hút thuốc giúp anh giảm bớt căng thẳng, nhưng ngoài ra, điểm sáng duy nhất trong ngày của anh là khi anh đến siêu thị gần đó và nhìn thấy khuôn mặt tươi cười của Yamada. Vì vậy, một buổi tối sau một ngày mệt mỏi nữa, anh đến siêu thị và phát hiện ra mình đã lỡ ca làm việc của Yamada. Chán nản, anh quyết định đi tìm khu vực hút thuốc nhưng lại không tìm thấy. Ngay khi anh chuẩn bị rời đi, một cô gái mặc áo khoác da kiểu biker tên là Tayama rủ anh đến một khu vực hút thuốc bí mật!</p>', 'Tập 12', 24, 'series', 'ongoing', 27, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Seena Hoshiki","avatar":""},{"name":"Takuya Sato","avatar":""},{"name":"Shinya Takahashi","avatar":""},{"name":"Toa Yukinari","avatar":""},{"name":"Megumi Toyoguchi","avatar":""},{"name":"Rikuya Yasuda","avatar":""},{"name":"Yoko Hikasa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["在超市后门吸烟的二人","躲在超市后门抽烟的两人","Super no Ura de Yani Suu Futari","Super no Ura de Yani Sū Futari","Behind the supermarket, smoking with you.","躲在超市後門抽菸的兩人","スーパーの裏でヤニ吸うふたり"]', 1784690324119);
