INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-trang-2026', 'Mặt trăng', 'Mārama', 'https://phimimg.com/upload/vod/20260617-1/1342f494446eabeb5f31b30f5984ccce.jpg', 'https://phimimg.com/upload/vod/20260617-1/e0ff77a61b865ee7e7e6002d8a1d0fc6.jpg', '<p>Năm 1859. Khi một phụ nữ trẻ người Māori được triệu tập từ New Zealand đến North Yorkshire, cô phát hiện ra di sản thuộc địa kinh hoàng của mình và buộc phải đối đầu và tiêu diệt người đàn ông Anh quý tộc đã tàn phá gia đình cô.</p>', 'Full', 1, 'single', 'completed', 33, 2026, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Ariāna Osborne","avatar":""},{"name":"Toby Stephens","avatar":""},{"name":"Umi Myers","avatar":""},{"name":"Erroll Shand","avatar":""},{"name":"Jordan Mooney","avatar":""},{"name":"Evelyn Towersy","avatar":""},{"name":"Mihi Te Rauhi Daniels","avatar":""},{"name":"Turia Schmidt-Peke","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Mārama"]', 1784690324119);
