INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-troi-day', 'Vùng đất trỗi dậy', 'Badland Rising', 'https://phimimg.com/upload/vod/20260617-1/e06eadf4e038a3b171dd605a611deadd.jpg', 'https://phimimg.com/upload/vod/20260617-1/6c11902d949cfbce9c43c13c9e0ff6ec.jpg', '<p>Một người đàn ông bình thường bắt đầu chuyến hành trình lái xe về nhà kéo dài 19 tiếng, không hề hay biết mình đang bị hai tên tội phạm điên rồ truy đuổi. Khi phát hiện ra động cơ của chúng, chuyến đi của anh ta biến thành một cuộc chiến sinh tồn khốc liệt.</p>', 'Full', 1, 'single', 'completed', 29, 2026, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"Nathan Phillips","avatar":""},{"name":"Robert Rabiah","avatar":""},{"name":"Jeremy Lindsay Taylor","avatar":""},{"name":"Aaron Glenane","avatar":""},{"name":"Hannah Levien","avatar":""},{"name":"Jake Ryan","avatar":""},{"name":"Daniel Nelson","avatar":""},{"name":"Steve Mouzakis","avatar":""},{"name":"Christopher Sommers","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Badland Rising"]', 1784690324119);
