INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bhooth-bangla', 'Bhooth Bangla', 'Bhooth Bangla', 'https://phimimg.com/upload/vod/20260617-1/9b69cedaa54dcbc45db0ebc10916d6e6.jpg', 'https://phimimg.com/upload/vod/20260617-1/06ec4c0e0be0f474f32284dc7db9d591.jpg', '<p>Bhooth Bangla là một bộ phim hài kinh dị sắp ra mắt do Akshay Kumar đóng chính và Priyadarshan đạo diễn. Sự hợp tác này đánh dấu sự tái hợp của họ sau 14 năm, kể từ khi từng hợp tác thành công trong các bộ phim như Hera Pheri và Bhool Bhulaiyaa. Dàn diễn viên bổ sung bao gồm Paresh Rawal, Rajpal Yadav và Asrani, đưa bộ ba huyền thoại trở lại với nhau. Phim được sản xuất bởi Balaji Telefilms và hợp tác với Cape of Good Films, dự kiến sẽ bắt đầu quay phim sớm.</p>', 'Full', 1, 'single', 'completed', 43, 2026, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Akshay Kumar","avatar":""},{"name":"Wamiqa Gabbi","avatar":""},{"name":"Paresh Rawal","avatar":""},{"name":"Tabu","avatar":""},{"name":"Jisshu Sengupta","avatar":""},{"name":"Rajpal Yadav","avatar":""},{"name":"Asrani","avatar":""},{"name":"Mithila Palkar","avatar":""},{"name":"Rajesh Sharma","avatar":""},{"name":"Manoj Joshi","avatar":""},{"name":"Zakir Hussain","avatar":""},{"name":"Perin Monish Malde","avatar":""},{"name":"Bhavna Pani","avatar":""},{"name":"Alexx O''Nell","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["บังกะโลผีสิง","Bhooth Bangla","鬼叫你要嫁","भूत बंगला"]', 1784690324119);
