INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ustaad-bhagat-singh', 'Ustaad Bhagat Singh', 'Ustaad Bhagat Singh', 'https://phimimg.com/upload/vod/20260617-1/055d41790b3899e4fce8c6de674149ae.jpg', 'https://phimimg.com/upload/vod/20260617-1/24b18cd825f74a827bfccd9a4a3666ad.jpg', '<p>Một cậu bé thuộc bộ lạc được hình thành bởi những giá trị của người thầy, người đã đặt cho cậu cái tên &#39;Bhagat Singh&#39;. Cậu lớn lên với những chuẩn mực đạo đức vững chắc, dẫn dắt hành động của cậu suốt cuộc đời. Cậu kiên định chống lại bất công và đối đầu với những thế lực tà ác hùng mạnh, ngay cả khi phải đối mặt với những khó khăn tưởng chừng không thể vượt qua.</p>', 'Full', 1, 'single', 'completed', 28, 2026, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Pawan Kalyan","avatar":""},{"name":"Sreeleela","avatar":""},{"name":"Raashii Khanna","avatar":""},{"name":"R. Parthiban","avatar":""},{"name":"Nawab Shah","avatar":""},{"name":"Avinash","avatar":""},{"name":"Gautami Tadimalla","avatar":""},{"name":"Narra Srinu","avatar":""},{"name":"Naga Mahesh","avatar":""},{"name":"Temper Vamsi","avatar":""},{"name":"Mathew Varghese","avatar":""},{"name":"Vadlamani Srinivas","avatar":""},{"name":"Mahesh Achanta","avatar":""},{"name":"Pallavi Dora","avatar":""},{"name":"Vamsee Chaganti","avatar":""},{"name":"Rao Ramesh","avatar":""},{"name":"Kamal Kamaraju","avatar":""},{"name":"Maganti","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Bhavadeeyudu! Bhagat Singh","Ustad Bhagat Singh","Ustaad Bagat Singh","ఉస్తాద్ భగత్ సింగ్"]', 1784690324119);
