INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-ta-ta-tu-mo', 'Đời Ta, Ta Tự Mò', 'Luck My Life', 'https://phimimg.com/upload/vod/20260617-1/7af6dbc287b311cd043085217f5b208a.jpg', 'https://phimimg.com/upload/vod/20260617-1/dfa294cc342b853711e3e9d81c3bded1.jpg', '<p>Khi vận may không còn mỉm cười, một người đàn ông tìm đến trường dạy mạt chược để học những kỹ năng cần thiết nhằm đánh bại kình địch và giành lại vận may của mình.</p>', 'Full', 1, 'single', 'completed', 29, 2026, 'Vietsub', 'FHD', 'Quốc Gia Khác', 0, '[{"name":"Richie Koh","avatar":""},{"name":"Tay Ping-Hui","avatar":""},{"name":"Cynthia Li","avatar":""},{"name":"Nick Shen","avatar":""},{"name":"Yang Shi Bin","avatar":""},{"name":"Rurusama","avatar":""},{"name":"Tan Ting Fong","avatar":""},{"name":"Joey Swee","avatar":""},{"name":"Charlene Huang","avatar":""},{"name":"Noah Yap","avatar":""},{"name":"Franster Wong","avatar":""},{"name":"Bunz","avatar":""},{"name":"Ben Logan","avatar":""},{"name":"Jaylene Hong","avatar":""},{"name":"Patricia Mok","avatar":""},{"name":"Chen Xiuhuan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["我的人生我自摸"]', 1784690324119);
