INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-y-co-dai-o-thanh-pho', 'Thần Y Cổ Đại Ở Thành Phố', 'Divine Doctor', 'https://phimimg.com/upload/vod/20260525-1/2354ed0d17c57a57ab7c9e38ab9f2bfd.jpg', 'https://phimimg.com/upload/vod/20260525-1/d43e954db21443e5841728ac0c4f7540.jpg', '<p>Truyền nhân của thần y, Ngô Danh xuống núi để truy đuổi kẻ phản bội Quỷ Trần. Bằng tuyệt học gia truyền, anh đã cứu sống gia chủ nhà Dã Điền, khiến hai nàng thiên kim tiểu thư Trí Tử và Mỹ Đại Tử đem lòng ngưỡng mộ. Sau đó, anh lại dùng y thuật cùng tấm lòng nhân hậu chữa khỏi căn bệnh kỳ lạ của sếp tổng mạnh mẽ Tô Uyển, chiếm được cảm tình của cô. Cuối cùng, với sự hỗ trợ của các mỹ nhân, Ngô Danh đã tiêu diệt kẻ phản bội Quỷ Trần. Từ đó về sau, anh và các cô gái cùng đồng hành trên con đường hành y cứu người, cứu đời.</p>', 'Tập 36', 36, 'series', 'ongoing', 26, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hàn Nhất Đình","avatar":""},{"name":"Nhiếp Tân Nguyên","avatar":""},{"name":"Phan Minh Duẫn","avatar":""},{"name":"Tiền Tư Di","avatar":""},{"name":"Tịch Lạc","avatar":""},{"name":"Trương Băng Thiến","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["都市古医仙"]', 1784690324120);
