INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-cua-gia-dinh-toi-storia-della-mia-famiglia-phan-2', 'Câu Chuyện Của Gia Đình Tôi (Storia della mia famiglia) (Phần 2)', 'My Family (Season 2)', 'https://phimimg.com/upload/vod/20260615-1/c816fabdcc4b4ec77702daf4350fde7b.jpg', 'https://phimimg.com/upload/vod/20260615-1/2bc6d41d53d982661c6293d12547078e.jpg', '<p>Một người bố mắc bệnh nan y chuẩn bị để gia đình hỗn loạn của mình chăm sóc hai đứa con nhỏ và đối mặt với cuộc sống không có anh – nhưng họ phải gạt bỏ những bất hòa cũ.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 27, 2026, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Eduardo Scarpetta","avatar":""},{"name":"Vanessa Scalera","avatar":""},{"name":"Massimiliano Caiazzo","avatar":""},{"name":"Cristiana Dell''Anna","avatar":""},{"name":"Gaia Weiss","avatar":""},{"name":"Antonio Gargiulo","avatar":""},{"name":"Filippo Gili","avatar":""},{"name":"Aurora Giovinazzo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Storia della mia famiglia"]', 1784690324120);
