INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cau-chuyen-cua-gia-dinh-toi-storia-della-mia-famiglia-phan-2', 'Câu Chuyện Của Gia Đình Tôi (Storia della mia famiglia) (Phần 2)', 'My Family (Season 2)', 'câu chuyện của gia đình tôi (storia della mia famiglia) (phần 2) my family (season 2) eduardo scarpetta vanessa scalera massimiliano caiazzo cristiana dell''anna gaia weiss antonio gargiulo filippo gili aurora giovinazzo storia della mia famiglia', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ki-am-thuc-cua-nang-hau-sanh-an', 'Nhật Kí Ẩm Thực Của Nàng Hầu Sành Ăn', 'The Food Diary Of Miss Maid', 'https://phimimg.com/upload/vod/20260407-1/f5c28659b2dacd97c7400dd5bfddfa3c.jpg', 'https://phimimg.com/upload/vod/20260407-1/88e9d776ad7839eaaf8b83d2dd64abd8.jpg', '<p>Sau một sự cố bí ẩn khiến cô phải rời bỏ công việc tại một dinh thự cổ ở Anh, Suzume chuyển đến một căn hộ nhỏ và bắt đầu cuộc sống mới tại Nhật Bản. Với sự tò mò về môi trường xung quanh, cô đắm mình vào nền văn hóa ẩm thực rực rỡ của xứ sở hoa anh đào. Từ những quán ăn bình dân địa phương cho đến các sạp hàng rong trên phố, Suzume khám phá ra những hương vị mới lạ, gặp gỡ những con người thú vị và tìm thấy niềm vui sống qua từng bữa ăn.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 15, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kana Ichinose","avatar":""},{"name":"Chihiro Suno","avatar":""},{"name":"Maki Kawase","avatar":""},{"name":"Shizuka Ishigami","avatar":""},{"name":"Hiromi Igarashi","avatar":""},{"name":"Daisuke Sakuma","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Maid-san wa Taberu Dake","Покоївка, що лише їсть","Miss Maid Simply Loves to Eat","メイドさんは食べるだけ"]', 1784690324120);
