INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhat-ki-am-thuc-cua-nang-hau-sanh-an', 'Nhật Kí Ẩm Thực Của Nàng Hầu Sành Ăn', 'The Food Diary Of Miss Maid', 'nhật kí ẩm thực của nàng hầu sành ăn the food diary of miss maid kana ichinose chihiro suno maki kawase shizuka ishigami hiromi igarashi daisuke sakuma maid-san wa taberu dake покоївка, що лише їсть miss maid simply loves to eat メイドさんは食べるだけ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hien-truong-vu-an', 'Hiện Trường Vụ Án', 'Crime Scene', 'https://phimimg.com/upload/vod/20260606-1/3f8132a2ab9ed92a75544024bdf1766c.jpg', 'https://phimimg.com/upload/vod/20260606-1/4f0a054fe3d3088f4c1d91faa131b40c.jpg', '<p>Một thi thể phụ nữ bất ngờ được phát hiện dưới sông. Cảnh sát hình sự lần theo manh mối, nhanh chóng tìm ra hung thủ và bắt giữ tên tội phạm nguy hiểm. Thế nhưng, đằng sau những vụ việc tưởng chừng không liên quan ấy, kẻ thủ ác thực sự vẫn đang nhởn nhơ ngoài vòng pháp luật... Tội phạm liên tục giăng bẫy, tạo ra những lớp sương mù che giấu sự thật, còn cảnh sát phải lần mò từng dấu vết để truy tìm chân tướng. Trong lúc điều tra án mạng, cảnh sát hình sự Sở Phong bất ngờ phát hiện một âm mưu đen tối đang dần lộ diện. Cùng lúc đó, chủ nhân một biệt thự bị sát hại, cả gia đình bị thảm sát. Trận đối đầu cuối cùng giữa cảnh sát và hung thủ đang đến rất gần!</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 22, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Tuấn Hiếu","avatar":""},{"name":"Lưu Vũ Hàng","avatar":""},{"name":"Hứa Hiểu Nặc","avatar":""},{"name":"Trần Mộng Dao","avatar":""},{"name":"Dương Minh Na","avatar":""},{"name":"Vương Kiến Tân","avatar":""},{"name":"Lưu Kim","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["罪案现场"]', 1784690324120);
