INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-lam-linh', 'Vũ Lâm Linh', 'Zhan Zhao Adventures', 'https://phimimg.com/upload/vod/20260513-1/7235dbc79b06a818fca87e79fd1b3dba.jpg', 'https://phimimg.com/upload/vod/20260513-1/652c18734c19a60250449ddc87a860f2.jpg', '<p>Nam hiệp Triển Chiêu (Dương Dương) vì truy tìm manh mối về vụ mưu phản của Tương Dương Vương do cố nhân để lại mà một thân một mình xuống phía Nam. Trên đường đi điều tra Triển Chiêu liên tục bị truy sát, lúc này Triển Chiêu tình cờ kết bạn với Hoắc Linh Lung (Chương Nhược Nam) đang trên đường hành tẩu giang hồ. Để bảo vệ chứng cứ vẹn toàn, Triển Chiêu lấy thân mình làm mồi nhử kẻ địch, vì muốn cứu giúp bách tính mà liên tục rơi vào hiểm cảnh. Trong lúc nguy cấp, Cẩm Mao Thử Bạch Ngọc Đường (Phương Dật Luân) đã ra tay tương cứu. Ba người liên thủ điều tra manh mối, thu thập tội chứng Tương Dương Vương cấu kết với cả 2 phe chính tà áp bức dân lành thông đồng ngoại địch. Cuối cùng Triển Chiêu và bạn bè cùng nhau đập tan âm mưu nơi triều đình lẫn giang hồ, trả lại chính khí cho võ lâm và sự bình yên cho bách tính.</p>', 'Hoàn Tất (37/37)', 37, 'series', 'completed', 48, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Dương","avatar":""},{"name":"Chương Nhược Nam","avatar":""},{"name":"Phương Dật Luân","avatar":""},{"name":"Trương Dư Hi","avatar":""},{"name":"Nhạc Dương","avatar":""},{"name":"Tu Khánh","avatar":""},{"name":"Lỗ Nặc","avatar":""},{"name":"Trương Minh Ân","avatar":""},{"name":"Khương Chấn Hạo","avatar":""},{"name":"Thị An","avatar":""},{"name":"Vương Tử Duệ","avatar":""},{"name":"Từ Nguy La","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb7