INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-du-day-tron-ven', 'Tình Yêu Đủ Đầy (Trọn Vẹn)', 'Fulfill', 'https://phimimg.com/upload/vod/20260425-1/c4c270186245d96b88f536aa6ea5d562.jpg', 'https://phimimg.com/upload/vod/20260425-1/3df6124ba8ce281cef9b6ccd8807097b.jpg', '<p>Cuộc sống hôn nhân của hai người phụ nữ tưởng chừng là cái kết viên mãn, nhưng thật ra chỉ mới bắt đầu. Họ phải học cách yêu lại từ đầu qua từng chi tiết nhỏ của đời sống chung, đối mặt với niềm vui, nỗi buồn và cả những lựa chọn lớn lao như chuyện sinh con. Mỗi thử thách đều buộc họ nhìn sâu vào nhau hơn — để hiểu, để chấp nhận, và để tình yêu trở nên đủ đầy theo cách trưởng thành nhất.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 20, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Saralee Prasitdumrong","avatar":""},{"name":"Eisaya Hosuwan","avatar":""},{"name":"Kanin Stanley","avatar":""},{"name":"Sarut Nawapraditkul","avatar":""},{"name":"Daraneenute Pasutanavin","avatar":""},{"name":"Sriphan Chunechomboon","avatar":""},{"name":"Parisaya Jaronetisat","avatar":""},{"name":"Daran Thitakawin","avatar":""},{"name":"Thanatchaporn Utsahajit","avatar":""},{"name":"Thanapat Sornkoon","avatar":""},{"name":"Amanda Sparey","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["婚后罗曼史","Rak Term Tem","Rak Toem Tem","Fulfill Fulfilling love","รักเติมเต็ม"]', 1784690324120);
