INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mau-ta-ac-den-kolory-za-czer', 'Màu Tà Ác: Đen (Kolory zła: Czerń)', 'Colors Of Evil: Black', 'màu tà ác: đen (kolory zła: czerń) colors of evil: black jakub gierszał marianna zydek zdzisław wardejn andrzej chyra robert gonera beata ścibakówna piotr żurawski julian świeżewski adam bobik róża łukaszewicz bartosz mikulak dorota ruśkowska cezary łukaszewicz łukasz pawłowski dariusz starczewski kolory zła - czerń colors of evil: black farben des bösen - schwarz 极恶原色：黑暗谜镇 kolory zła: czerń', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mai-co', 'Mai Cồ', 'Michael', 'https://phimimg.com/upload/vod/20260610-1/de455d52d9a992748923792d0e7d711f.jpg', 'https://phimimg.com/upload/vod/20260610-1/5d97ad4e52952ce97e0500cfa68ee61e.jpg', '<p>Michael là bức chân dung điện ảnh khắc họa cuộc đời và di sản của một trong những nghệ sĩ có sức ảnh hưởng lớn nhất mà thế giới từng biết đến. Bộ phim kể về cuộc đời của Michael Jackson ngoài âm nhạc, theo dấu hành trình từ khi tài năng phi thường của ông được phát hiện trong vai trò giọng ca chính của nhóm Jackson Five, cho đến khi ông trở thành một nghệ sĩ có tầm nhìn xa, với khát vọng sáng tạo không ngừng để vươn tới danh hiệu “ngôi sao giải trí vĩ đại nhất thế giới”. Cho thấy cuộc sống phía sau hào quang sân khấu lẫn những màn trình diễn mang tính biểu tượng nhất trong giai đoạn đầu sự nghiệp solo, bộ phim mang đến cho khán giả một góc nhìn chân thực hơn bao giờ hết về Michael Jackson. Đây chính là nơi câu chuyện của ông bắt đầu.</p>', 'Full', 1, 'single', 'completed', 48, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Jaafar Jackson","avatar":""},{"name":"Colman Domingo","avatar":""},{"name":"Nia Long","avatar":""},{"name":"Juliano Krue Valdi","avatar":""},{"name":"Miles Teller","avatar":""},{"name":"KeiLyn Durrel Jones","avatar":""},{"name":"Kendrick Sampson","avatar":""},{"name":"Joseph David-Jones","avatar":""},{"name":"Rhyan Hill","avatar":""},{"name":"Jamal Henderson","avatar":""},{"name":"Trey Horton","avatar":""},{"name":"Jessica Sula","avatar":""},{"name":"Larenz Tate","avatar":""},{"name":"Laura Harrier","avatar":""},{"name":"Mike Myers","avatar":""},{"name":"Nathaniel Logan McIntyre","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["迈克尔·杰克逊：巨星之路","麥可傑克森","Michael Jackson Biopic","ไมเคิล","米高積遜","Майкл","مايكل جاكسون","Michael","マイケル","Մայքլ","مایکَل","Мајкл","مائیکل","Mai Cồ"]', 1784690324120);
