INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-so-toi-pham-phan-2', 'Hồ Sơ Tội Phạm (Phần 2)', 'Criminal Record (Season 2)', 'https://phimimg.com/upload/vod/20260424-1/61beb549b27efe75f4e42c869cdf716a.jpg', 'https://phimimg.com/upload/vod/20260424-1/f608a45666891fe3652c9f2f44e9f2e4.jpg', '<p>Ở trung tâm London, một cuộc điện thoại ẩn danh đã thu hút hai thanh tra tài giỏi — một phụ nữ trẻ đang ở giai đoạn đầu sự nghiệp và một người đàn ông có giao thiệp tốt quyết tâm bảo vệ di sản của mình — tham gia vào cuộc chiến sửa sai một vụ án oan cũ.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 26, 2026, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Peter Capaldi","avatar":""},{"name":"Cush Jumbo","avatar":""},{"name":"Zoë Wanamaker","avatar":""},{"name":"Cathy Tyson","avatar":""},{"name":"Stephen Campbell Moore","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Криминално досие","犯罪记录","Ποινικό Μητρώο","תיק פלילי","سوء پیشینه","Teistumas","Kriminalni dosje","Кримінальне досьє","Criminal Record"]', 1784690324120);
