INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoi-roi-moi-rung-dong-cuoi-roi-moi-dong-long', 'Cưới Rồi Mới Rung Động (Cưới Rồi Mới Động Lòng)', 'Late To Love', 'https://phimimg.com/upload/vod/20260527-1/565e12b2001c8ead7d2f0b69b4300c8d.jpg', 'https://phimimg.com/upload/vod/20260527-1/761e80c08920840f519b8e6e441a1f8c.jpg', '<p>Vì muốn kéo dài thời gian tốt nghiệp, tiến sĩ y học Hứa Nam Ca đã thỏa thuận kết hôn cùng ông trùm kinh doanh Hoắc Bắc Yến, anh ta muốn nhân cơ hội này củng cố quyền lực gia tộc, hai người đều đạt được mục đích của mình. Trước mặt người ngoài, họ đóng vai cặp vợ chồng yêu thương thắm thiết, nhưng sau lưng, mỗi người lại có bí mật riêng, cô âm thầm điều tra công ty anh, còn anh treo thưởng để truy tìm thân phận thật của cô. Một cuộc hôn nhân bắt đầu từ toan tính, liệu có thể hóa giả thành thật không?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 20, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hà Kiện Kỳ","avatar":""},{"name":"Vương Nhã Giai","avatar":""},{"name":"Lý Minh Nguyên","avatar":""},{"name":"Lý Gia Đồng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Late to Love","婚后再心动"]', 1784690324120);
