INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cac-te-bao-cua-yumi-phan-3', 'Các Tế Bào Của Yumi (Phần 3)', 'Yumi''s Cells (Season 3)', 'https://phimimg.com/upload/vod/20260515-1/57f28e5e6d6399e53687174216c67bf6.jpg', 'https://phimimg.com/upload/vod/20260515-1/9bdab524f98b5904ac478b03c17853b3.jpg', '<p>Xoay quanh câu chuyện của Yumi, một nhân viên văn phòng bình thường nhưng sống theo quan điểm của nhiều tế bào não trong đầu cô ấy điều khiển mọi suy nghĩ, cảm xúc và hành động của cô ấy. Vì cú sốc sau mối tình không thành, Yumi đã không còn tin vào câu chuyện tình yêu. Tuy nhiên, tế bào bị ngủ quên của Yumi sẽ được Goo Woong đánh thức. Liệu rồi Yumi có chịu thay đổi, có được hạnh phúc?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 22, 2026, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Go-eun","avatar":""},{"name":"Kim Jae-won","avatar":""},{"name":"Jun Suk-ho","avatar":""},{"name":"Lee Yu-bi","avatar":""},{"name":"Mi Ram","avatar":""},{"name":"Choi Daniel","avatar":""},{"name":"Cho Hye-jeong","avatar":""},{"name":"Sung Ji-ru","avatar":""},{"name":"Park Se-in","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["柔美的细胞小将","Клетки Юми","Клетки Ю Ми","유미의 세포들"]', 1784690324120);
