INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-quay-marsupilami', 'Siêu Quậy Marsupilami', 'Marsupilami', 'https://phimimg.com/upload/vod/20260609-1/ce83fd4f831ee631c254b3c9eeb7c9ac.jpg', 'https://phimimg.com/upload/vod/20260609-1/3591605a882f0bd65e1a8f22bbe793f1.jpg', '<p>Để cứu lấy công việc, David Ticoule chấp nhận vận chuyển một kiện hàng bí ẩn từ Nam Mỹ về Pháp. Anh đưa con trai Léo và vợ cũ Tess đi cùng, vô tình kéo họ vào một phi vụ nguy hiểm mà chính anh cũng chưa kịp hiểu rõ. Mọi thứ nhanh chóng vượt khỏi tầm kiểm soát khi kiện hàng bị mở ra ngoài ý muốn. Bên trong là một sinh vật nhỏ bé, đáng yêu nhưng kéo theo hàng loạt rắc rối không tưởng. Từ một chuyến đi tưởng chừng đơn giản, hành trình trên biển bỗng biến thành chuỗi tình huống dở khóc dở cười. Giữa đại dương, họ phải học cách tin tưởng và sát cánh bên nhau để vượt qua hỗn loạn, đồng thời bảo vệ chính gia đình mình.</p>', 'Full', 1, 'single', 'completed', 44, 2026, 'Vietsub', 'FHD', 'Pháp', 1, '[{"name":"Philippe Lacheau","avatar":""},{"name":"Jamel Debbouze","avatar":""},{"name":"Tarek Boudali","avatar":""},{"name":"Élodie Fontan","avatar":""},{"name":"Julien Arruti","avatar":""},{"name":"Jean Reno","avatar":""},{"name":"Corentin Guillot","avatar":""},{"name":"Gérard Jugnot","avatar":""},{"name":"Didier Bourdon","avatar":""},{"name":"Alban Ivanov","avatar":""},{"name":"Reem Kherici","avatar":""},{"name":"Booder","avatar":""},{"name":"Vincent Desagnat","avatar":""},{"name":"Romain Lancry","avatar":""},{"name":"Paco Boisson","avatar":""},{"name":"Laurent Spielvogel","avatar":""},{"name":"Claudette Wal","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["ყვითელკუდა მარსუპილამი","长尾豹马修","Marsupilami"]', 1784690324120);
