INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trong-vung-xam', 'Trong Vùng Xám', 'In the Grey', 'https://phimimg.com/upload/vod/20260602-1/b777c022173c0bbe8d7defd3f98fa9f9.jpg', 'https://phimimg.com/upload/vod/20260602-1/8980bb4035ff3c2d1546e21ab9d3037d.jpg', '<p>Khi một tên bạo chúa tàn nhẫn cướp đi khối tài sản trị giá 1 tỷ đô la, một đội đặc nhiệm tinh nhuệ hoạt động bí mật trong bóng tối toàn cầu được giao nhiệm vụ đoạt lại số tiền đó trong một phi vụ mà với bất kỳ ai khác cũng gần như là nhiệm vụ tự sát. Thành thạo thao túng quyền lực và tầm ảnh hưởng không kém gì sử dụng vũ khí tự động và thuốc nổ hạng nặng, họ bước vào một vụ cướp tưởng chừng bất khả thi rồi nhanh chóng bị cuốn vào một cuộc chiến toàn diện của chiến lược, lừa dối và sinh tồn.</p>', 'Full', 1, 'single', 'completed', 28, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Anh', 0, '[{"name":"Henry Cavill","avatar":""},{"name":"Jake Gyllenhaal","avatar":""},{"name":"Eiza González","avatar":""},{"name":"Carlos Bardem","avatar":""},{"name":"Michael Vu","avatar":""},{"name":"Fisher Stevens","avatar":""},{"name":"Rosamund Pike","avatar":""},{"name":"Mohammed Al Turki","avatar":""},{"name":"Kojo Attah","avatar":""},{"name":"Jason Wong","avatar":""},{"name":"Emmett J. Scanlan","avatar":""},{"name":"Christian Ochoa Lavernia","avatar":""},{"name":"Karlos Klaumannsmoller","avatar":""},{"name":"Kristofer Hivju","avatar":""},{"name":"Gonzalo Bouza","avatar":""},{"name":"Silvia","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["En La Zona Gris","Guerra Sem Regras","Šedá zóna","เหลี่ยมจารชน คนเหนือเทา","In the grey - miljardikeikka","In the Grey"]', 1784690324120);
