INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-xa-thu', 'Bảy Xạ Thủ', 'Seven Snipers', 'https://phimimg.com/upload/vod/20260608-1/fbb2d1e5689a6570b4a7e3c30b1d2fd6.jpg', 'https://phimimg.com/upload/vod/20260608-1/b4445d1cd317262c26e26cc1ee34db25.jpg', '<p>Khi một cựu xạ thủ bắn tỉa tinh nhuệ bị truy sát bởi tên lãnh chúa tàn bạo từng giam cầm mình, cô buộc phải chiến đấu sống còn để bảo vệ đứa con gái mà cô đã nuôi nấng trong cảnh ẩn dật tại một trang trại hẻo lánh ở Úc.</p>', 'Full', 1, 'single', 'completed', 27, 2026, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"Radha Mitchell","avatar":""},{"name":"Tim Roth","avatar":""},{"name":"Annabel Wolfe","avatar":""},{"name":"Ioan Gruffudd","avatar":""},{"name":"Ryan Kwanten","avatar":""},{"name":"Lee Tiger Halley","avatar":""},{"name":"Charles Cottier","avatar":""},{"name":"Pacharo Mzembe","avatar":""},{"name":"Damien Ryan","avatar":""},{"name":"Bianca Wallace","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Seven Snipers"]', 1784690324120);
