INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-thia-so-co-la', 'Một thìa sô cô la', 'One Spoon of Chocolate', 'https://phimimg.com/upload/vod/20260608-1/62a3a09daa105e14b49f0b6891d2af92.jpg', 'https://phimimg.com/upload/vod/20260608-1/d40b87052c878e8a9ffd80697fe0ed48.jpg', '<p>Sau khi hoàn thành nghĩa vụ quân sự, Unique bị vu khống tội hành hung và phải ngồi tù. Khi được trả tự do, anh đến Ohio để bắt đầu lại cuộc đời và tìm gặp người thân duy nhất còn lại của mình là Ramsey. Tuy nhiên, thị trấn này đang ẩn chứa những điều đen tối: gã cảnh sát trưởng phân biệt chủng tộc cùng đám tay sai có cùng tư tưởng thù hận đều là những kẻ ưa bạo lực và đang che giấu một bí mật kinh hoàng liên quan đến hàng loạt vụ mất tích của các thanh niên da đen gần đây. Khi chúng nhắm vào Unique và đảo lộn cuộc sống của anh, cựu quân nhân này không còn lựa chọn nào khác ngoài việc đáp trả dữ dội để trừng trị gã cảnh sát trưởng cùng đám tay sai của hắn.</p>', 'Full', 1, 'single', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Shameik Moore","avatar":""},{"name":"Blair Underwood","avatar":""},{"name":"RJ Cyler","avatar":""},{"name":"Paris Jackson","avatar":""},{"name":"Emyri Crutchfield","avatar":""},{"name":"Michael Harney","avatar":""},{"name":"Harry Goodwins","avatar":""},{"name":"Johnell Young","avatar":""},{"name":"Rockmond Dunbar","avatar":""},{"name":"Déjá Dee","avatar":""},{"name":"Jason Isbell","avatar":""},{"name":"Isaiah Hill","avatar":""},{"name":"James Lee Thomas","avatar":""},{"name":"Alex Borton","avatar":""},{"name":"Brandon Bonilla","avatar":""},{"name":"Tye Alexander","avatar":""},{"name":"Cabot Basden","avatar":""},{"name":"M","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["One Spoon of Chocolate"]', 1784690324120);
