INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('disco', 'D.I.S.C.O.', 'D.I.S.C.O.', 'https://phimimg.com/upload/vod/20260608-1/8872f1ac408595982699d49c1af952fa.jpg', 'https://phimimg.com/upload/vod/20260608-1/673f38901132b840dd5ca6efc8675883.jpg', '<p>Chiến dịch được cơ quan tình báo D.I.S.C.O. bí mật thực hiện từ lâu đã thất bại vì đặc vụ Ertan. Ertan, người bị đình chỉ công tác, đi nghỉ mát cùng vợ là Seda. Tại đây, anh tình cờ gặp gỡ Zafer và vợ là Aynur. Zafer, người đã biết về nghề nghiệp của Ertan, chỉ đưa ra một điều kiện duy nhất: giữ im lặng. Đó là cùng nhau hoàn thành nhiệm vụ dang dở của Ertan. Bởi vì mục tiêu của tổ chức đang ở cùng khách sạn và số phận của chiến dịch nằm trong tay Ertan. Ertan, người chưa từng là đặc vụ thực địa bao giờ, bắt đầu nhiệm vụ bằng cách phải có sự giúp đỡ của Zafer. Sự hỗ trợ bất ngờ từ Seda và Aynur sẽ thay đổi tất cả.</p>', 'Full', 1, 'single', 'completed', 26, 2026, 'Vietsub', 'FHD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Giray Altınok","avatar":""},{"name":"Kerem Özdoğan","avatar":""},{"name":"Özge Özaçar","avatar":""},{"name":"Yıldız Çağrı Atiksoy","avatar":""},{"name":"Saygın Soysal","avatar":""},{"name":"Devrim Yakut","avatar":""},{"name":"İrem Sak","avatar":""},{"name":"Şükrü Özyıldız","avatar":""},{"name":"Cosimo Fusco","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["DISCO","D.I.S.C.O."]', 1784690324120);
