INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-lon', 'Ngôi nhà lớn', 'Casa Grande', 'https://phimimg.com/upload/vod/20260608-1/e9524768dbd4376604777c9f13ebfe30.jpg', 'https://phimimg.com/upload/vod/20260608-1/12c389da9c0b88b724e03ea899f5ceee.jpg', '<p>Một người con gái lạc lối trở về đoàn tụ với gia đình tại trang trại trong thời điểm khó khăn, khi người cha ốm yếu của cô phải đối mặt với cả chẩn đoán bệnh nan y và áp lực ngày càng tăng từ các đối thủ cạnh tranh. Những vết thương cũ lại trỗi dậy khi họ vật lộn với những gì phía trước.</p>', 'Full', 1, 'single', 'completed', 39, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"John Pyper-Ferguson","avatar":""},{"name":"Christina Moore","avatar":""},{"name":"Madison Lawlor","avatar":""},{"name":"Lou Diamond Phillips","avatar":""},{"name":"Daniel Edward Mora","avatar":""},{"name":"Javier Bolanos","avatar":""},{"name":"Loren Escandon","avatar":""},{"name":"Kate Mansi","avatar":""},{"name":"Terry Woodberry","avatar":""},{"name":"Shalim Ortiz","avatar":""},{"name":"Lauren Swickard","avatar":""},{"name":"Zeus Ley","avatar":""},{"name":"Shaun Paul Piccinino","avatar":""},{"name":"Victor Carrera","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '["Casa Grande: The Movie","Голямата къща","Casa Grande"]', 1784690324120);
