INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-da-han-quoc-ho-nuot-nguoi', 'Ma Da Hàn Quốc: Hồ Nuốt Người', 'Salmokji: Whispering Water', 'https://phimimg.com/upload/vod/20260608-1/b5862c2062d0266c33b01dda7fc6bffc.jpg', 'https://phimimg.com/upload/vod/20260608-1/c3342c62abb8c3b628a76d675edcd118.jpg', '<p>Bên dưới vẻ tĩnh lặng của hồ Salmokji là nơi trú ngụ của một thực thể tà ma. Bị thu hút bởi những vụ án tại hồ Salmokji, một nhóm phóng viên dấn thân vào cuộc điều tra đưa tin. Thế nhưng, họ không ngờ chính mình đang bước vào bẫy tử thần. Con ác ma dưới đáy hồ sâu không chỉ trực chờ đoạt mạng, mà còn thao túng tâm lý nạn nhân bằng những lời thì thầm ám ảnh. Khi cả nhóm chính thức lọt vào tầm ngắm của ám ma hồ Salmokji, mặt nước tĩnh lặng kia khi về đêm sẽ trở thành mồ chôn không lối thoát.</p>', 'Full', 1, 'single', 'completed', 44, 2026, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"Kim Hye-yoon","avatar":""},{"name":"Lee Jong-won","avatar":""},{"name":"Kim Jun-han","avatar":""},{"name":"Kim Young-sung","avatar":""},{"name":"Oh Dong-min","avatar":""},{"name":"Yoon Jae-chan","avatar":""},{"name":"Jang Da-a","avatar":""},{"name":"Jeon So-hyun","avatar":""},{"name":"Sul Youn-ji","avatar":""},{"name":"Lee Sung-wook","avatar":""},{"name":"Nam Min-woo","avatar":""},{"name":"Yoon Ye-joo","avatar":""},{"name":"Kim Tae-jun","avatar":""},{"name":"Kim Kye-hyung","avatar":""},{"name":"Heo Jun-ho","avatar":""},{"name":"Limm Yea-eun","avatar":""},{"name":"Cho Sung-hwan","avatar":""},{"name":"Choi Hee-do","avatar":""},{"name":"Lee Tae-y","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["杀木池","ซัลมกจี สตรีทวิว สยองต้องสาป","Salmokchi","살목지"]', 17