INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-mau-tren-bien', 'Bẫy Máu Trên Biển', 'Chum', 'https://phimimg.com/upload/vod/20260608-1/70670043801b60404e53de11d6d55b99.jpg', 'https://phimimg.com/upload/vod/20260608-1/3feff9fbb441bc682046cbb443df26b3.jpg', '<p>phim kinh dị sinh tồn lấy bối cảnh một đám cưới tại Malta. Khi một con cá mập khát máu tấn công ngoài khơi, nhóm bạn trẻ tưởng được cứu sống bởi một ngư dân bí ẩn, nhưng nhanh chóng nhận ra họ đang mắc kẹt giữa hai mối đe dọa chết người: cá mập dưới biển và một kẻ săn mồi tâm thần trên tàu. Để sống sót, họ buộc phải đối mặt với những bí mật, sự phản bội và nỗi ám ảnh nguy hiểm của con người.</p>', 'Full', 1, 'single', 'completed', 17, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Alice Eve","avatar":""},{"name":"Eric Michael Cole","avatar":""},{"name":"Elle Haymond","avatar":""},{"name":"Sarah Siadat","avatar":""},{"name":"Johnny Gaffney","avatar":""},{"name":"Lisa Yaro","avatar":""},{"name":"Jim Klock","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chum"]', 1784690324120);
