INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-sinh-tu-ii', 'Cuộc Chiến Sinh Tử II', 'Mortal Kombat II', 'https://phimimg.com/upload/vod/20260519-1/d68170850071c3aa73dfb26e6a18133e.jpg', 'https://phimimg.com/upload/vod/20260519-1/3c295de9c27fa4449eb82919363a80d7.jpg', '<p>Những chiến binh được yêu thích nhất — nay có thêm sự góp mặt của Johnny Cage — buộc phải đối đầu lẫn nhau trong trận chiến tối thượng đẫm máu và không khoan nhượng. Mục tiêu: đánh bại sự thống trị tàn bạo của Shao Kahn, kẻ đang đe dọa sự tồn vong của Địa Giới và tất cả những ai đứng lên bảo vệ nó.</p>', 'Full', 1, 'single', 'completed', 37, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Karl Urban","avatar":""},{"name":"Adeline Rudolph","avatar":""},{"name":"Jessica McNamee","avatar":""},{"name":"Josh Lawson","avatar":""},{"name":"Martyn Ford","avatar":""},{"name":"Ludi Lin","avatar":""},{"name":"Mehcad Brooks","avatar":""},{"name":"Tati Gabrielle","avatar":""},{"name":"Lewis Tan","avatar":""},{"name":"Max Huang","avatar":""},{"name":"Damon Herriman","avatar":""},{"name":"Chin Han","avatar":""},{"name":"Tadanobu Asano","avatar":""},{"name":"Joe Taslim","avatar":""},{"name":"Hiroyuki Sanada","avatar":""},{"name":"Desmond Chiam","avatar":""},{"name":"CJ. Bloomfield","avatar":""},{"name":"Sophia Xu","avatar":""},{"name":"Ana Thu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Mortal Kombat 2","มอร์ทัล คอมแบท 2","Мортал Комбат 2","Mortal Kombat II"]', 1784690324120);
