INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-tham-tron-hoc-2', 'Thần Thám Trốn Học 2', 'Detective Chen 2', 'https://phimimg.com/upload/vod/20260607-1/f218e7e6c1a5e36791344bf1f2d629c9.jpg', 'https://phimimg.com/upload/vod/20260607-1/1490eaa7f1335029774af0d2d8c9b347.jpg', '<p>Bị kết án oan và sắp phải đối mặt với án tử hình tại nhà tù Bình Dương, số phận của Trần Hổ dường như đã được định đoạt. Để cứu anh, Bạch Khắc bí mật thâm nhập vào Học viện Sakura nhằm điều tra những manh mối quan trọng, nhưng liên tiếp gặp phải vô vàn trở ngại. Trong khi đó, những sự việc kỳ lạ liên tục xảy ra trong nhà tù khi các phạm nhân lần lượt biến mất không dấu vết. Lợi dụng danh nghĩa điều tra, viên quản ngục đã chuyển Trần Hổ đến một khu giam giữ bí mật đầy nguy hiểm như một phần của âm mưu tạo cớ cho cuộc xâm lược Trung Quốc của quân Nhật. Tuy nhiên, Trần Hổ từ lâu đã nhìn thấu kế hoạch này. Hợp tác cùng quản ngục, Lý Đại và Bạch Khắc, anh bí mật giăng một cái bẫy ngược, dẫn đến cuộc đối đầu cuối cùng với những kẻ chủ mưu đứng sau toàn bộ âm mưu.</p>', 'Full', 1, 'single', 'completed', 25, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Ashton Chen","avatar":""},{"name":"Liu Tianzuo","avatar":""},{"name":"Huang Qiao","avatar":""},{"name":"Tan Kai","avatar":""},{"name":"Norman Tsui Siu-Keung","avatar":""},{"name":"Yan Jie","avatar":""},{"name":"Chunyu Shanshan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Mật Thám Thần Bí 2","卧底神探"]', 1784690324120);
