INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-nga-cua-chua', 'Bản Ngã Của Chúa', 'Is God Is', 'https://phimimg.com/upload/vod/20260608-1/0fec5127b1397a419f3197cfbe688038.jpg', 'https://phimimg.com/upload/vod/20260608-1/84620d5188461eec90b35b3784a85d85.jpg', '<p>Hai chị em bắt tay vào hành trình trả thù hoành tráng, đối mặt với lịch sử gia đình đầy khó khăn đã đẩy họ vào chặng đường dài phi thường.</p>', 'Full', 1, 'single', 'completed', 18, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kara Young","avatar":""},{"name":"Mallori Johnson","avatar":""},{"name":"Vivica A. Fox","avatar":""},{"name":"Sterling K. Brown","avatar":""},{"name":"Janelle Monáe","avatar":""},{"name":"Mykelti Williamson","avatar":""},{"name":"Erika Alexander","avatar":""},{"name":"Xavier Mills","avatar":""},{"name":"Justen Ross","avatar":""},{"name":"Josiah Cross","avatar":""},{"name":"Nuri Barnes","avatar":""},{"name":"Navali Barnes","avatar":""},{"name":"Noah J. Craig","avatar":""},{"name":"Lindsey G. Smith","avatar":""},{"name":"Rhonda Johnson Dents","avatar":""},{"name":"Mark Druhet","avatar":""},{"name":"Nol","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Is God Is"]', 1784690324120);
