INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('son-than', 'Sơn Thần', 'Mountain Deity', 'https://phimimg.com/upload/vod/20260608-1/2aa81b6cbf9e1f4d56e51e5d2b4cbc85.jpg', 'https://phimimg.com/upload/vod/20260608-1/e0c5a5d19bfbe34a813e99a09aed04c3.jpg', '<p>Sơn thần Xuân Giản đã tha mạng cho phàm nhân Cơ Cửu sau khi phát hiện ra anh ta có liên kết với kiếp nạn thiên đình chưa thể hóa giải của mình. Thế nhưng, trong khi nàng hy vọng anh có thể giúp cứu mạng nàng, thì Cơ Cửu lại bí mật lên kế hoạch cướp đi trái tim thần tiên của nàng để hồi sinh người yêu đã khuất. Khi sự phản bội bóp nghẹt niềm tin và thần lực dần tan biến, những sự thật bị che giấu từ một thế kỷ trước cũng bắt đầu được đưa ra ánh sáng.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 21, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tiêu Vũ","avatar":""},{"name":"Đàm Tư Nguyên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["山神的新郎"]', 1784690324120);
