INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('griya-rahsia-seorang-lelaki', 'Griya: Rahsia Seorang Lelaki', 'Griya', 'https://phimimg.com/upload/vod/20260512-1/b526dab7500367e79c3d1703398e4baa.jpg', 'https://phimimg.com/upload/vod/20260512-1/7ec94863afee4e2d66e04a986c22234f.jpg', '<p>Câu chuyện theo chân Sophia, một nữ luật sư thông minh, người đã quyết định thâm nhập thực tế để điều tra Razman – một góa phụ giàu có bị nghi ngờ đã sát hại hai người vợ cũ và chiếm đoạt tài sản của họ. Một cuộc tình giả tạo đã dẫn họ đến cuộc hôn nhân chính thức, giúp Sophia có cơ hội đột nhập vào dinh thự của Razman nhằm phơi bày những bí mật đen tối mà hắn đang che giấu.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 15, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Nazim Othman","avatar":""},{"name":"Chacha Maembong","avatar":""},{"name":"Scha Al-Yahya","avatar":""},{"name":"Dynas Mokhtar","avatar":""},{"name":"Nia Atasha","avatar":""},{"name":"Hanna Aqeela","avatar":""},{"name":"Marisa Yasmin","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Griya: Rahsia Seorang Lelaki"]', 1784690324120);
