INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-ngay-xa-me', 'Đếm Ngày Xa Mẹ', 'Number One', 'https://phimimg.com/upload/vod/20260227-1/388f27b93c3074c6c703e634ce37acd4.jpg', 'https://phimimg.com/upload/vod/20260227-1/5f60e239ce59d59bfc842da562d6cfc4.jpg', '<p>Đếm Ngày Xa Mẹ xoay quanh cặp mẹ con Eun-sil (Jang Hye-jin) và Ha-min (Choi Woo-shik). Mỗi lần ăn một món do mẹ nấu, Ha-min lại nhìn thấy một con số khó lý giải. Sau mỗi bữa ăn, con số ấy giảm đi một đơn vị. Ha-min sớm nhận ra một sự thật kinh hoàng: khi con số chạm về 0, mẹ anh sẽ qua đời. Kể từ đó, cuộc sống bình thường của Ha-min bị đảo lộn hoàn toàn. Để bảo vệ quãng thời gian còn lại của mẹ, Ha-min bắt đầu tránh xa những bữa cơm nhà, viện đủ mọi lý do để không phải ngồi vào bàn ăn và dần trở nên xa cách với mẹ. Liệu thời gian để Hamin ở bên mẹ còn được bao lâu nữa?</p>', 'Full', 1, 'single', 'completed', 30, 2026, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"Choi Woo-shik","avatar":""},{"name":"Jang Hye-jin","avatar":""},{"name":"Gong Seung-yeon","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Number 1","넘버 원","นับหนึ่งถึงมื้อแม่","넘버원"]', 1784690324120);
