INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('usa-94-brazil-tro-lai-vinh-quang-tetra-acreditar-de-novo', 'USA 94: Brazil Trở Lại Vinh Quang (Tetra: Acreditar de Novo)', 'USA 94: Brazil''s Return To Glory', 'https://phimimg.com/upload/vod/20260607-1/28f5e582c731102c1ff8c5b8f0f66acd.jpg', 'https://phimimg.com/upload/vod/20260607-1/b4894293f4e5c6b418e68ade3f0d5687.jpg', '<p>Bộ phim dõi theo hành trình chinh phục chức vô địch World Cup lần thứ tư trong lịch sử của đội tuyển Brazil vào năm 1994, mang đến cho người xem các cuộc phỏng vấn độc quyền với những cầu thủ ngôi sao cùng những thước phim hậu trường chưa từng được công bố tại giải đấu năm đó.</p>', 'Full', 1, 'single', 'completed', 30, 2026, 'Vietsub', 'FHD', 'Brazil', 0, '[{"name":"Romário","avatar":""},{"name":"Bebeto","avatar":""},{"name":"Dunga","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Tetra: Acreditar de Novo"]', 1784690324120);
