INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('qua-muon-thanh-tri-moi-gap-dung-nguoi', 'Qua Muôn Thành Trì Mới Gặp Đúng Người', 'A Thousand Miles To Your Heart', 'https://phimimg.com/upload/vod/20260601-1/b611dc2811e84186e3030753e697ac75.jpg', 'https://phimimg.com/upload/vod/20260601-1/f6d8d4dcdd1ed4d8e3f79ec4da210e5f.jpg', '<p>Tề Xí - viên quan nuôi gà bên cạnh Hoàng đế - bất ngờ được thiên tử bổ nhiệm làm khâm sai ngầm, bí mật đi khắp nơi tìm kiếm các vương gia có khả năng kế thừa ngôi báu. Trên đường, Tề Xí cùng Thái tử và công chúa nước Yên Âu Dương Yến trở thành đồng đội, liên tiếp phá giải những &quot;âm mưu&quot; dở khóc dở cười, kéo theo hàng loạt tình huống vừa ly kỳ vừa hài hước. Sau tất cả, cả ba không chỉ nhận ra tình cảm của chính mình mà còn hiểu rõ trách nhiệm phải gánh vác trên vai.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 25, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Xuyên","avatar":""},{"name":"Trịnh Tưu Hoằng","avatar":""},{"name":"Vương Nhất Triết","avatar":""},{"name":"Phùng Lệ Quân","avatar":""},{"name":"Lạt Mục Dương Tử","avatar":""},{"name":"Vương Mậu Lôi","avatar":""},{"name":"Tào Khắc Nan","avatar":""},{"name":"Vương Ninh","avatar":""},{"name":"Y Vân Hạc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["不当皇帝的100个理由","100 Reasons Not to Be King","过遍千城才识君"]', 1784690324120);
