INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-uc-lap-lai', 'Ký Ức Lặp Lại', 'Affection', 'https://phimimg.com/upload/vod/20260606-1/02b1f6e322ddcc86cb9618d8f2c4326c.jpg', 'https://phimimg.com/upload/vod/20260606-1/10e05b03dbf42fb094cde360e58e046f.jpg', '<p>Ellie Carter tỉnh dậy trong một ngôi nhà xa lạ. Bên cạnh cô là một người đàn ông tự nhận là chồng mình, còn một bé gái gọi cô là mẹ. Điều đáng sợ là Ellie không nhớ bất kỳ ai trong số họ. Người đàn ông tên Bruce giải thích rằng Ellie mắc một căn bệnh bí ẩn khiến ký ức của cô liên tục bị &quot;reset&quot;. Mỗi lần lên cơn, cô lại quên sạch cuộc sống hiện tại và phải bắt đầu từ đầu. Tuy nhiên, càng tìm hiểu, Ellie càng nghi ngờ mọi thứ xung quanh mình. Trong khi cố ghép nối các mảnh ký ức rời rạc, cô phát hiện những bí mật kinh hoàng về chính bản thân, gia đình và nguồn gốc thực sự của sự tồn tại của mình. Cuộc chạy đua với thời gian trở nên tuyệt vọng vì mỗi lần tiến gần đến sự thật, ký ức của cô có thể biến mất bất cứ lúc nào.</p>', 'Full', 1, 'single', 'completed', 18, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jessica Rothe","avatar":""},{"name":"Joseph Cross","avatar":""},{"name":"Julianna Layne","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Affection"]', 1784690324120);
