INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dan-do-linh-hon-muoi-nam', 'Dẫn Độ Linh Hồn: Mười Năm', 'The Ferry Man 10th Anniversary', 'https://phimimg.com/upload/vod/20260606-1/e865d297ad11b573883ba3a11e0c6f12.jpg', 'https://phimimg.com/upload/vod/20260606-1/4dddf2cc78d960be45b74db8c0c51969.jpg', '<p>Tại thành phố Huyễn Hải, Hạ Đông Thanh và Á cùng nhau quản lý tiệm tạp hóa số 444 – nơi giao thoa giữa ngày và đêm. Họ kết hợp cùng người đồng đội mới là một &quot;Người gác đêm&quot; có ngoại hình giống hệt Triệu Lại đã mất tích, tạo thành bộ ba cùng bảo vệ sự cân bằng giữa nhân giới và linh giới. Trong những ngày tháng bình dị, bộ ba đã hóa giải thành công nhiều sự kiện kỳ quái, thế nhưng một tai nạn bất ngờ đã phá vỡ sự yên bình vốn có... Khi trăng máu treo cao, mọi người đồng lòng tiêu diệt âm mưu đen tối để đưa mọi thứ trở lại thực tại. Thành phố Huyễn Hải khôi phục lại vẻ tĩnh lặng, tiệm tạp hóa số 444 tiếp tục mở cửa đón khách, nhưng những giai thoại kỳ bí mới đã âm thầm nảy sinh trên con đường lát đá xanh.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 17, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vu Nghị","avatar":""},{"name":"Lưu Trí Dương","avatar":""},{"name":"Tiêu Nhân","avatar":""},{"name":"Hứa Giai Kỳ","avatar":""},{"name":"Khương Phức Di","avatar":""},{"name":"Cố Chấn Tường","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["灵魂摆渡十年","灵魂摆渡·十年"]', 1784690324120);
