INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('poldi', 'Poldi', 'Poldi', 'https://phimimg.com/upload/vod/20260604-1/d2fac741d13281871535711cf2198796.jpg', 'https://phimimg.com/upload/vod/20260604-1/7ed4d78db36a2de2a10de27159b07b3d.jpg', '<p>Là một cầu thủ bóng đá, một doanh nhân, một gương mặt được người hâm mộ yêu mến và là một người hùng đích thực của cộng đồng — Lukas Podolski nhìn lại hành trình sự nghiệp đầy thăng trầm của mình và chia sẻ về những dự định tiếp theo trong bộ phim tài liệu đầy chân thực và gần gũi này.</p>', 'Full', 1, 'single', 'completed', 31, 2026, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Lukas Podolski","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"}]', '["Poldi"]', 1784690324120);
