INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-lung-do', 'Linh Lung Độ', 'Linglong''s Ferry', 'https://phimimg.com/upload/vod/20260606-1/6503705e997ece5d84a0d98c6c6d776f.jpg', 'https://phimimg.com/upload/vod/20260606-1/7553dd347ab4191774d421c25da1f2fa.jpg', '<p>Phim lấy bối cảnh cuối thời Thanh, xoay quanh Hồ Linh Lung – cô gái cải nam trang để kế thừa gia nghiệp trà Kỳ Môn. Một nữ trà nhân hiện đại tên Kiều Hân bất ngờ xuyên không và nhập vào ngọc bội của Linh Lung. Hai người cùng nhau vượt qua tranh đấu gia tộc, chống lại sự chèn ép của thương nhân ngoại quốc, cải tiến kỹ thuật chế trà và gìn giữ văn hóa trà Trung Hoa.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 21, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cao Vũ Đồng","avatar":""},{"name":"Chiêm Duy Ngạo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["玲珑渡"]', 1784690324120);
