INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-toc-do', 'Quỷ tốc độ', 'Speed Demon', 'https://phimimg.com/upload/vod/20260605-1/167134cacefc973441639f44b72f6cd9.jpg', 'https://phimimg.com/upload/vod/20260605-1/ab3a55afa0289f0414a7dc09a6d482e9.jpg', '<p>Trên một chuyến tàu cao tốc, một nữ tu đã mất niềm tin phải thực hiện nghi lễ trừ tà đầu tiên của mình cho một hành khách bị ma ám, người đang quyết tâm làm cho đoàn tàu mất kiểm soát lao vào vòng xoáy tai nạn.</p>', 'Full', 1, 'single', 'completed', 15, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Katie Cassidy","avatar":""},{"name":"William H. Macy","avatar":""},{"name":"John Patrick Jordan","avatar":""},{"name":"Michael Emery","avatar":""},{"name":"Allen McCullough","avatar":""},{"name":"Sabrina Schlegel-Mejia","avatar":""},{"name":"Noriko Sato","avatar":""},{"name":"Ray Faiola","avatar":""},{"name":"Jeremy Feight","avatar":""},{"name":"Michael John Improta","avatar":""},{"name":"George Banghart Jr.","avatar":""},{"name":"Sky Vaux Fuller","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Скоростен демон","Speed Demon"]', 1784690324120);
