INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ruc-chay-giua-ban-trua', 'Rực Cháy Giữa Ban Trưa', 'Twin Fire Dawn', 'https://phimimg.com/upload/vod/20260523-1/0723b34e9ffdae498a9c073892c42d40.jpg', 'https://phimimg.com/upload/vod/20260523-1/3bfd70f192ef3d08e42c0db6726e7a9a.jpg', '<p>Người anh trai song sinh mạo danh đốc quân, thảm sát cả nhà họ Trang. Trang Vận Thu thoát chết trong gang tấc, giả mạo thiên kim tiểu thư để gả vào phủ đốc quân báo thù. Trong quá trình bày mưu tính kế, cô dần nhận ra điểm bất thường và phát hiện vị đốc quân kia thực chất do người anh sinh đôi đóng giả, còn người em trai thật sự đang âm thầm nhẫn nhịn, bí mật điều tra chứng cứ tội ác. Hai kẻ mang mối thù sâu nặng từ chỗ dò xét lẫn nhau dần nảy sinh tình cảm, rồi cùng liên thủ giăng bẫy, vạch trần tội ác của đám quyền quý, đem lại bình yên cho dân chúng.</p>', 'Tập 30', 30, 'series', 'ongoing', 25, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hà Tuyên Lâm","avatar":""},{"name":"Nghiêm Tử Hiền","avatar":""},{"name":"He Boyuan","avatar":""},{"name":"Trương Vĩnh Cương","avatar":""},{"name":"Hướng Hân","avatar":""},{"name":"Trình Trừng","avatar":""},{"name":"Lưu Tâm Dư","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["宿命","Twin Flames in Daybreak","燃双为昼"]', 1784690324120);
