INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rak-rak-truc-giac-tinh-yeu', 'Rak Rak: Trực Giác Tình Yêu', 'Rak Rak: Sense Of Love', 'https://phimimg.com/upload/vod/20260430-1/b9371757be9971be0f77e57c07427615.jpg', 'https://phimimg.com/upload/vod/20260430-1/52d73be2ab6e0cc20b795169743a30c5.jpg', '<p>Khi cảm xúc dâng trào và trái tim đối mặt với những phép thử, chẳng có gì là bất biến. Trong Rak Rak, chỉ một khoảnh khắc cũng có thể thay đổi tất cả, giữa rung động và lý trí, họ sẽ lựa chọn điều gì?</p>', 'Tập 7', 8, 'series', 'ongoing', 19, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324120);
