INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huong-ve-sao-bang-cau-nguyen', 'Hướng Về Sao Băng Cầu Nguyện', 'Wishing Upon the Shooting Stars', 'https://phimimg.com/upload/vod/20260404-1/a51c6f3471dda694f0b79e10cc95bede.jpg', 'https://phimimg.com/upload/vod/20260404-1/9c0b84096a0310d005f2836350bf78f7.jpg', '<p>Trên đảo Tinh Phố, chàng trai Hà Hướng Vĩnh tuyệt vọng ước biến mất và tỉnh dậy với thân phận mới là Chung Tiểu Hữu, chỉ có bạn thân Uyển Triết nhận ra anh. Khi Tiểu Hữu dần tìm thấy ấm áp trong cuộc sống mới và kết nối lại với những người xung quanh, những mối tình cũ và điều ước kỳ diệu khiến các mối quan hệ trở nên rắc rối. Trước khi sao băng vụt qua lần nữa, họ phải đối mặt với sự thật, giá phải trả của điều ước và đưa ra những lựa chọn định mệnh, thử thách tình yêu và tương lai của mình.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 34, 2026, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Sơ Mạnh Hiên","avatar":""},{"name":"Chung Nhạc Hiên","avatar":""},{"name":"Dư Kiệt Ân","avatar":""},{"name":"Các Vụ Hiếu Thái","avatar":""},{"name":"Tào Lan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Desejo sob estrelas cadentes","向流星许愿的我们","คำอธิษฐานสุดท้าย…ที่ปลายดาว","Hướng Về Sao Băng Cầu Nguyện","Chúng Ta Ước Nguyện Với Sao Băng","向流星許願的我們"]', 1784690324120);
