INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-be-hang-xom-phan-2', 'Bạn Bè & Hàng Xóm (Phần 2)', 'Your Friends & Neighbors (Season 2)', 'https://phimimg.com/upload/vod/20260410-1/46ee5af3e308d7abffbb2056bc508974.jpg', 'https://phimimg.com/upload/vod/20260410-1/1491dd99231608d1832bed578668dfa0.jpg', '<p>Khi một đại gia tài chính đột ngột rơi vào cảnh ly hôn và mất việc, anh ta bắt đầu đi ăn trộm những nhà hàng xóm giàu có để trang trải cuộc sống. Ăn trộm của hội mình chơi cùng đem lại khoái cảm kỳ lạ, nhưng dần dần khiến anh ta sa vào hố sâu chết chóc.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 17, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jon Hamm","avatar":""},{"name":"Amanda Peet","avatar":""},{"name":"Olivia Munn","avatar":""},{"name":"Hoon Lee","avatar":""},{"name":"Mark Tallman","avatar":""},{"name":"Lena Hall","avatar":""},{"name":"Aimee Carrero","avatar":""},{"name":"Eunice Bae","avatar":""},{"name":"Isabel Gravitt","avatar":""},{"name":"Donovan Colan","avatar":""},{"name":"James Marsden","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Your Friends & Neighbours","Your Friends and Neighbours","掩耳盗邻","Vrais Voisins, Faux Amis","Φίλοι και γείτονες","החברים והשכנים שלך","دوستان و همسایگانتان","Tavo draugai ir kaimynai","Your Friends and Neighbors","Your Friends & Neighbors"]', 1784690324120);
