INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuong-tu-ky', 'Tường Tự Ký', 'Xiang Xu Ji', 'https://phimimg.com/upload/vod/20260516-1/6d0fa36f40e2d7aa05c3f3dad205c983.jpg', 'https://phimimg.com/upload/vod/20260516-1/9dc6fb58a75cf38c67b71267a02dbc37.jpg', '<p>Thiếu niên Giang Nghiễn Thu võ lực mạnh nhưng học kém, bị dụ vào Thân Tử Thư Trai – học viện xếp hạng bét. Tại đây, cậu dùng sức mạnh áp đảo nhóm học sinh cá biệt và cùng Thẩm Thanh Ngộ, Kỷ Lâm Sương lập thành nhóm ba người. Khi hiệu trưởng giả nam Tần Chiêu Tuyết muốn đưa thư trai đội sổ lên hạng ưu, một câu chuyện học đường hài hước với “lấy bút làm kiếm, lấy sách làm khiên” bắt đầu.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 20, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Leslie Li","avatar":""},{"name":"Wang Yunkai","avatar":""},{"name":"Wu Huicen","avatar":""},{"name":"Ni Songyang","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Xiang Xu Ji","祥序记"]', 1784690324120);
