INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thinh-duong-ky-an', 'Thịnh Đường Kỳ Án', 'Tang Dynasty Occult Mysteries', 'https://phimimg.com/upload/vod/20260603-1/bdbb8139c4963b1ad1abe46dd9281285.jpg', 'https://phimimg.com/upload/vod/20260603-1/231eaafa0e8b7f550adac3609d454262.jpg', '<p>Vào thời Đường, nhà điều tra pháp y tài ba Lý Cảnh Lam đã hợp tác với &quot;quỷ thám&quot; đầy bí ẩn Giác Minh và nữ bổ đầu bản lĩnh Tô Vũ An để phá giải một chuỗi các vụ án gây chấn động. Khi họ vạch trần những âm mưu ẩn giấu sau mỗi tội ác, sự nguy hiểm, công lý và tình yêu cũng dần trở nên gắn kết sâu sắc với nhau.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 14, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hà Hoằng San","avatar":""},{"name":"Lý Phi","avatar":""},{"name":"Hà Bạc Viễn","avatar":""},{"name":"Lư Tinh Vũ","avatar":""},{"name":"Lại Vũ Mông","avatar":""},{"name":"Lục Nghiên Kỳ","avatar":""},{"name":"Hạ Cương","avatar":""},{"name":"Ứng Hạo Minh","avatar":""},{"name":"Vương Cương","avatar":""},{"name":"Khương Thụy Lâm","avatar":""},{"name":"Triệu Anh Tử","avatar":""},{"name":"Đỗ Dịch Hành","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Tang.Dynasty.Occult.My.steries","盛唐奇案"]', 1784690324120);
