INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-phan-boi', 'Tình Yêu Phản Bội', 'Wrong Side Of The Rainbow', 'https://phimimg.com/upload/vod/20260403-1/93687521ef7c8ec3e2ef8800f90da089.jpg', 'https://phimimg.com/upload/vod/20260403-1/b21288eb60ac6655368a9186cc5cfe60.jpg', '<p>Sau lần đổ vỡ trong tình yêu, một cô dâu mới cưới sẵn sàng bắt đầu lại. Nhưng khi phát hiện chồng mình lại là bạn với mối tình đầu, cô quyết định giữ kín quá khứ của họ.</p>', 'Hoàn Tất (19/19)', 19, 'series', 'completed', 21, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Warintorn Panhakarn","avatar":""},{"name":"Rinrada Kaewbuasai","avatar":""},{"name":"Khunnarong Pratesrat","avatar":""},{"name":"Saralee Prasitdumrong","avatar":""},{"name":"Lorena Schuett","avatar":""},{"name":"Paradee Wongsawat","avatar":""},{"name":"Chintara Sukapatana","avatar":""},{"name":"Sukol Sasijulaka","avatar":""},{"name":"Aanan Boonnak","avatar":""},{"name":"Pamela Bowden","avatar":""},{"name":"Khemarat Soonthornnont","avatar":""},{"name":"Suppakorn Kitsuwan","avatar":""},{"name":"Suttatip Wutchaipradi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["爱与背叛","รักหักหลัง"]', 1784690324120);
