INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yet-hi', 'Yết Hí', 'Love Between Lines', 'https://phimimg.com/upload/vod/20260109-1/cc0563a07da12a6896dffc6aa176c998.jpg', 'https://phimimg.com/upload/vod/20260109-1/d6d82c20c56d61f31894bd979c3eda4a.jpg', '<p>Tiêu Trĩ Vũ và Hồ Tu gặp gỡ nhờ một buổi chơi “truy tìm lối thoát” có chủ đề dân quốc. Ở thế giới kịch bản đầy tuyết rơi và những bóng ma gián điệp chập chùng, hai người đánh ra tia lửa định mệnh. Thế nhưng, cuộc tái ngộ bất ngờ ngoài đời thực lại mở ra những bí ẩn về thân phận thật sự của đối phương. Xuyên qua không gian đan xen giữa hiện thực và hư cấu, họ cùng nhau bước hành trình trưởng thành song hành, từ những ràng buộc vượt qua mọi chiều không gian, để hoàn thành bước tiến hóa của tình yêu và chính bản thân mình.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 33, 2026, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Tinh Húc","avatar":""},{"name":"Lư Dục Hiểu","avatar":""},{"name":"Đài Húc","avatar":""},{"name":"Lý Đinh Đinh","avatar":""},{"name":"Nhân Hữu Luân","avatar":""},{"name":"Triệu Hạo Hồng","avatar":""},{"name":"Hà Cửu","avatar":""},{"name":"Giang Khải","avatar":""},{"name":"Trương Kiến Diệp","avatar":""},{"name":"Phương Đông Đức Mạo","avatar":""},{"name":"Lưu Di Nô","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ga Xi","Filming Simultaneously","Amor entre líneas","轧戏"]', 1784690324120);
