INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('yet-hi', 'Yết Hí', 'Love Between Lines', 'yết hí love between lines trần tinh húc lư dục hiểu đài húc lý đinh đinh nhân hữu luân triệu hạo hồng hà cửu giang khải trương kiến diệp phương đông đức mạo lưu di nô ga xi filming simultaneously amor entre líneas 轧戏', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-pha-cuu-thien', 'Long Phá Cửu Thiên', 'Dragon''S Triumph In The Celestial Realm', 'https://phimimg.com/upload/vod/20260212-1/cb16ed532f06f071cffbd9f8ade6915b.jpg', 'https://phimimg.com/upload/vod/20260212-1/011e3bdf72257ffabb50b1cbe79a9dd4.jpg', '<p>Lâm Thần xuất thân từ một giang hồ đầy mộng tưởng, mang trong mình khát vọng vươn tới đỉnh cao võ đạo. Con đường ấy không hề bằng phẳng, những sự sỉ nhục, những lần thất bại và những thử thách nghiệt ngã liên tiếp bào mòn ý chí của anh chàng. Chỉ sau khi nếm đủ cay đắng của kiếp người, Lâm Thần mới từng bước đứng vào hàng ngũ cường giả, trở thành cái tên khiến thiên hạ kính phục. Thế nhưng, vinh quang chưa kịp vẹn tròn, Lâm Thần lại đối diện những mất mát không lời giải. Trong tận cùng đau khổ, một cảnh giới hiếm có được khai mở, nó được gọi là Tâm Giác, tầng nhận thức vượt xa võ học thông thường. Nhờ đó, Lâm Thần chạm đến bản chất của sinh diệt, nhìn rõ dòng chảy vô tình của số phận, đồng thời thoáng thấy manh mối về sự biến mất bí ẩn của phụ thân. Biết được chưa bao giờ đồng nghĩa với nắm giữ, mà để làm chủ sức mạnh ấy và truy tìm chân tướng sự việc, Lâm Thần buộc phải tiếp tục bước sâu vào vòng xoáy giang hồ, nơi mỗi lựa chọn đều có thể đổi lấy máu và định mệnh.</p>', 'Tập 40', 80, 'hoathinh', 'ongoing', 13, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["修罗战魂","Long Po Jiutian","Long Po Jiu Tian","Дракон сокрушает девять небес","龙破九天"]', 1784690324120);
