INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luoi-dao-trong-tay-chuong-trung-nhan', 'Lưỡi Dao Trong Tay (Chưởng Trung Nhận)', 'Within The Grip', 'https://phimimg.com/upload/vod/20260428-1/2d8c2c614fc91b33f9c192d22d95042c.jpg', 'https://phimimg.com/upload/vod/20260428-1/7dc95353b828664381cd1531c004e51c.jpg', '<p>Thái tử Ân Trú để né tránh sự điều tra và tai họa đã quyết định giả danh Cố Triều Tịch để thâm nhập vào Cố gia. Trong khi đó, Cố Ngư Lạc lại muốn lợi dụng sự hiện diện của Ân Trú để tìm ra sự thật về thân thế bí ẩn của chính mình. Cả hai đều che giấu những bí mật riêng, từ những kẻ đối đầu gay gắt ban đầu, họ dần trở thành những người đồng đội ăn ý và tin tưởng lẫn nhau. Đứng trước vòng xoáy của nhân tính và dục vọng quyền lực, giữa những lời nói dối và sự thật tàn khốc, họ sẽ phải đưa ra lựa chọn thế nào khi đối mặt với ranh giới sinh tử?</p>', 'Tập 8', 24, 'series', 'ongoing', 24, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Ca Dương","avatar":""},{"name":"Lý Khải Hinh","avatar":""},{"name":"Phùng Lệ Quân","avatar":""},{"name":"Kim Vưu Mỹ","avatar":""},{"name":"Đổng Tuệ","avatar":""},{"name":"Từ Hạo Tường","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["掌中刃"]', 1784690324120);
