INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('project-y-gai-ngoan-doi-doi', 'Project Y: Gái Ngoan Đổi Đời', 'Project Y', 'project y: gái ngoan đổi đời project y han so-hee jeon jong-seo kim shin-rock jeong young-ju lee jae-kyoon yooa kim sung-cheol park bo-in han sung-min bek hyun-jin park hwan-hee song yi-hyun han hyeon-jun lee sae-on lee hong-nae kim in-woo choi deok-moon yu sin seo wu-joon 프로젝트 와이 y计划 peurojekteu y project y proyecto y 프로젝트 y', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moc-canh-kho-thoat', 'Mọc Cánh Khó Thoát', 'No Way To Escape', 'https://phimimg.com/upload/vod/20260603-1/708b50edb9609f70cabbbba69a007969.jpg', 'https://phimimg.com/upload/vod/20260603-1/a386dfd71b65d588772fdaa1c49d6127.jpg', '<p>Lôi Minh vì hành động hấp tấp cách đây năm năm mà khiến thầy mình là Liên Bình chết trong một vụ nổ. Từ đó anh luôn mang cảm giác áy náy với con gái của thầy là Liên Huệ, thậm chí còn cắt đứt quan hệ với cô. Anh dốc toàn lực phá án chỉ để an ủi linh hồn người đã khuất Một băng cướp gồm ba nam một nữ đến từ Quảng Nam gây án xong chạy trốn, đúng lúc ấy, một tài xế xe dù ở Bá Thành bị sát hại. Các manh mối trùng khớp khiến Lôi Minh khẳng định băng cướp này đã xâm nhập nơi đây. Sau khi chúng giết người rồi cho nổ xe để bỏ trốn, Lôi Minh truy đuổi và vô tình bắn sượt khiến Đường Tiếu Tiếu bị thương. Anh phát hiện chất nổ mà cô sử dụng giống hệt vụ nổ năm xưa khiến thầy mình hy sinh, khiến thù cũ hận mới bùng lên ý chí chiến đấu. Trong bệnh viện, anh tình cờ gặp lại Liên Huệ, hóa giải khúc mắc trong lòng và từ đó xác định được danh tính của Đường Tiếu Tiếu. Băng nhóm tiếp tục lên kế hoạch cướp chợ thuốc lá. Lôi Minh giăng bẫy bắt được Đường Tiếu Tiếu nhưng lại đau đớn mất đi đồng đội Lưu Đại Vũ. Sau khi biết Đường Tiếu Tiếu mang thai, cảnh sát dùng điều này để khai thác đột phá. Lôi Minh dự đoán tên cầm đầu Khương Hổ sẽ quay lại liền bố trí mai phục, khống chế những thành viên còn lại và dồn hắn vào đường cùng trên sân thượng bệnh viện. Trong trận đối đầu cuối cùng trên sân thượng, Khương Hổ bắt Liên Huệ làm con tin để chống trả khiến cô bị thương. Lôi Minh liều mạng chiến đấu với hắn. Đúng lúc ấy, Đường Tiếu Tiếu xuất hiện, nói ra sự thật về đứa bé trong bụng. Khương Hổ hoàn toàn sụp đổ, hối hận muộn màng rồi tự sát vì sợ tội. Cuối cùng, Lôi Minh dùng huân chương quân công hạng nhì an ủi linh hồn thầy giáo, đồng thời hóa giải hiềm khích với Liên Huệ.</p>', 'Full', 1, 'single', 'completed', 20, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Khúc Cao Vị","avatar":""},{"name":"Hoàng Mãnh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["插翅难飞"]', 1784690324120);
