INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ga-vao-nha-quyen-quy', 'Gả Vào Nhà Quyền Quý', 'Daughter Of Fortune', 'https://phimimg.com/upload/vod/20260518-1/724b77523620f8c57913e32b1f01000a.jpg', 'https://phimimg.com/upload/vod/20260518-1/1292c63e44bba61e1f7cb8ab6e130734.jpg', '<p>Thẩm Chi Niệm và đích tỷ Thẩm Nam Kiều cùng trùng sinh. Để tránh thảm họa chốn hậu cung ở kiếp trước, Thẩm Nam Kiều ép Chi Niệm thay mình nhập cung . Thẩm Chi Niệm từng bước thận trọng bày kế, liên tiếp lật ngược thế cờ, nhờ mưu trí khiến hoàng đế Nam Cung Huyền Vũ chú ý. Từ triều đình đến hậu cung đầy rẫy âm mưu xảo quyệt, nàng và Nam Cung Huyền Vũ thăm dò rồi cảm mến nhau, hợp sức cùng phá giải tình thế nguy cấp chốn cung đình!</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 19, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đặng Hiếu Từ","avatar":""},{"name":"Trịnh Tưu Hoằng","avatar":""},{"name":"Trình Phóng","avatar":""},{"name":"Thẩm Chi Dịch","avatar":""},{"name":"Thôi Húc Vũ","avatar":""},{"name":"Tiền Khả Nhi","avatar":""},{"name":"Lưu Dịch Linh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["凰宫梦","桃叶渡春","嫁金枝"]', 1784690324120);
