INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nho-em-yeu-em', 'Nhớ em, yêu em', 'Miss You, Love You', 'https://phimimg.com/upload/vod/20260602-1/bcb588cff890f2d2a2e25343f9ed286d.jpg', 'https://phimimg.com/upload/vod/20260602-1/866a5c81b86c9733b29e80a5fb047926.jpg', '<p>Một góa phụ thẳng thắn, đau khổ buộc phải lên kế hoạch tang lễ cho chồng mình với một người hoàn toàn xa lạ: trợ lý của người con trai mà bà đã xa cách bấy lâu. Khi họ vật lộn với nỗi đau và hoàn cảnh kỳ lạ, hài hước đen tối, những bí mật chôn giấu và những oán hận lâu năm dần lộ diện, nhưng sự hợp tác của họ lại trở thành một cầu nối bất ngờ, mang đến tiếng cười và sự hàn gắn cho người mẹ này và người con trai thay thế bất đắc dĩ của bà.</p>', 'Full', 1, 'single', 'completed', 8, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Allison Janney","avatar":""},{"name":"Andrew Rannells","avatar":""},{"name":"Suzy Nakamura","avatar":""},{"name":"Bonnie Hunt","avatar":""},{"name":"Oscar Nuñez","avatar":""},{"name":"Lisa Schurga","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Miss You, Love You"]', 1784690324120);
