INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('he-thong', 'Hệ thống', 'System', 'https://phimimg.com/upload/vod/20260602-1/015268a31ff21bbafd3d287a5b811a8b.jpg', 'https://phimimg.com/upload/vod/20260602-1/5c9d6d956e1253d8c5b56584643b714e.jpg', '<p>Khi Neha Rajvansh, một công tố viên có địa vị cao, gặp Sarika Rawat, một thư ký tòa án xuất thân từ gia đình bình dị, cuộc sống của họ bị đảo lộn, nơi quyền lực định nghĩa sự thật, làm mờ ranh giới pháp lý và đặt ra câu hỏi về ý nghĩa thực sự của công lý đối với họ.</p>', 'Full', 1, 'single', 'completed', 29, 2026, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Sonakshi Sinha","avatar":""},{"name":"Jyothika","avatar":""},{"name":"Ashutosh Gowariker","avatar":""},{"name":"Adinath Kothare","avatar":""},{"name":"Aashriya Mishra","avatar":""},{"name":"Gaurav Pandey","avatar":""},{"name":"Sayandeep Gupta","avatar":""},{"name":"Preeti Agarwal Mehta","avatar":""},{"name":"Vijayant Kohli","avatar":""},{"name":"Diwanshu Gambhir","avatar":""},{"name":"Freya Kothari","avatar":""},{"name":"Bhupendra Chauhan","avatar":""},{"name":"Dev Chauhan","avatar":""},{"name":"Ajay Madhok","avatar":""},{"name":"Divija Gambhir","avatar":""},{"name":"Saad Baba","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["System","体制","सिस्टम"]', 1784690324120);
