INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moc-lan-huyet-nhan', 'Mộc Lan: Huyết Nhẫn', 'Mulan: Light A fire', 'https://phimimg.com/upload/vod/20260512-1/9f6ec13a10392a85f9447f2a94f25afb.jpg', 'https://phimimg.com/upload/vod/20260512-1/c6c40710a8b4a33f27ec101f038f44aa.jpg', '<p>Sau khi xuất ngũ, Mộc Lan trở về quê hương và phát hiện cha mẹ bị sát hại, còn em trai mất tích. Trong quá trình điều tra, cô vạch trần đường dây đúc tiền giả cùng âm mưu tham nhũng của các quan lại quyền thế, nhưng lại bị hãm hại và mất đi người thân trong bi kịch. Chứng kiến nỗi khổ của dân chúng, Mộc Lan một lần nữa khoác lên mình áo giáp để dẫn dắt cuộc phản kháng chống lại kẻ áp bức và giành lại công lý cho bá tánh.</p>', 'Full', 1, 'single', 'completed', 26, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Chu Aixu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["木兰：血刃"]', 1784690324121);
