INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phoi-sat', 'Phổi Sắt', 'Iron Lung', 'https://phimimg.com/upload/vod/20260507-1/b089d8e0ae874ad7aa986887bed23a0c.jpg', 'https://phimimg.com/upload/vod/20260507-1/148f3d0329ce075fb763be4207fdf10e.jpg', '<p>Một đại dương máu. Hy vọng cuối cùng còn sót lại sau Đại Tận Diệt Lặng Im. Trong những hành lang rỉ sét của các trạm không gian đang sụp đổ, tàn dư cuối cùng của nhân loại chế tạo một chiếc tàu ngầm để thăm dò những tầng sâu đang chảy máu… và hàn kín một linh hồn bên trong để điều khiển nó. Nhưng hy vọng nơi hư vô này mong manh chẳng khác gì ánh sao xa xôi. Đây không phải một chuyến thám hiểm. Đây là một bản án tử hình.</p>', 'Full', 1, 'single', 'completed', 35, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mark Fischbach","avatar":""},{"name":"Caroline Kaplan","avatar":""},{"name":"Troy Baker","avatar":""},{"name":"Elsie Lovelock","avatar":""},{"name":"Elle LaMont","avatar":""},{"name":"Mick Lauer","avatar":""},{"name":"Dave Pettitt","avatar":""},{"name":"Holt Boggs","avatar":""},{"name":"Isaac McKee","avatar":""},{"name":"Roman Parsons Crow","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["ไอร์ออน ลังก์","철제호흡보조기","Markiplier''s IRON LUNG","Железное легкое","Iron Lung"]', 1784690324121);
