INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-tri-tuyet-doi-cua-lang-man', 'Giá Trị Tuyệt Đối Của Lãng Mạn', 'Absolute Value of Romance', 'https://phimimg.com/upload/vod/20260509-1/40a5a9f7445ae1ebee273a8aa54c73a2.jpg', 'https://phimimg.com/upload/vod/20260509-1/584e66818e68f5429f85d0df2257a8ad.jpg', '<p>Eui-ju, một nữ sinh trầm lặng ban ngày, là một tiểu thuyết gia viết tiểu thuyết tình cảm ban đêm, được truyền cảm hứng khi bốn giáo viên điển trai xuất hiện: Woo-su lạnh lùng, Da-ju sôi nổi, Gi-jeon cộc cằn và Dong-ju dịu dàng. Cô đưa họ vào cuốn tiểu thuyết mới của mình, và nó nổi tiếng chỉ sau một đêm! Nhưng bí mật của cô bị Woo-su, kẻ thù không đội trời chung từ trước đến giờ, phát hiện. Cô chấp nhận lời đề nghị của anh ta để bảo vệ bí mật của mình, nhưng liệu cô có thể hoàn thành cuốn tiểu thuyết này mà không bị tổn hại gì không?</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 29, 2026, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Hyang-gi","avatar":""},{"name":"Cha Hak-yeon","avatar":""},{"name":"Kim Jae-hyun","avatar":""},{"name":"Demian","avatar":""},{"name":"Kim Dong-kyu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["القيمة المطلقة للحب","วุ่นนัก รักสัมบูรณ์","浪漫的絕對值","The Absolute Value of Romance","Absolute Value of Romance","로맨스의 절댓값"]', 1784690324121);
