INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gia-tri-tuyet-doi-cua-lang-man', 'Giá Trị Tuyệt Đối Của Lãng Mạn', 'Absolute Value of Romance', 'giá trị tuyệt đối của lãng mạn absolute value of romance kim hyang-gi cha hak-yeon kim jae-hyun demian kim dong-kyu القيمة المطلقة للحب วุ่นนัก รักสัมบูรณ์ 浪漫的絕對值 the absolute value of romance absolute value of romance 로맨스의 절댓값', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luong-tam-bat-nghi', 'Lưỡng Tâm Bất Nghi', 'No Doubt In Us', 'https://phimimg.com/upload/vod/20260509-1/6d9a6a62ba90a8bce713634cb748e54e.jpg', 'https://phimimg.com/upload/vod/20260509-1/c76078fd5407de645dd41285a36e0336.jpg', '<p>Vị hoàng đế vốn chỉ trọng văn chương, không chút võ nghệ và vị hoàng hậu xuất thân võ tướng, thích múa đao bắn cung vốn dĩ luôn chán ghét và thiếu tin tưởng lẫn nhau. Sau một tai nạn bất ngờ, hai người bị hoán đổi linh hồn và buộc phải chấp nhận thực tại oái oăm này. Trong quá trình đóng giả thân phận của đối phương, họ dần tháo gỡ được những hiểu lầm và học cách yêu thương, tin tưởng nhau hơn.&nbsp; Khi ở trong thân xác của hoàng hậu, hoàng đế tận mắt chứng kiến cảnh phi tần cung nữ và ngay cả Thái hậu cũng lạnh lùng mỉa mai, bày kế hãm hại vị hoàng hậu vốn không được sủng ái, từ đó mới thấu hiểu nàng đã phải sống khổ cực thế nào. Ngược lại, hoàng hậu trong thân xác hoàng đế cũng cuối cùng đã hiểu được lý do vì sao bấy lâu nay hoàng đế luôn giữ lòng nghi kỵ đối với gia tộc của mình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 20, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đại Cao Chính","avatar":""},{"name":"Hà Tuyên Lâm","avatar":""},{"name":"Dư Dật Lôi","avatar":""},{"name":"Mã Hàm Diệc","avatar":""},{"name":"Lý Khanh Nhĩ","avatar":""},{"name":"Dữ Thất","avatar":""},{"name":"Hứa Nặc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Liang Bu Yi","两不疑","两心不疑​"]', 1784690324121);
