INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ao-giac-mau', 'Ảo Giác Máu', 'Blood Devotion', 'https://phimimg.com/upload/vod/20260602-1/43d9bc79b68949af373a9c9adacc67ba.jpg', 'https://phimimg.com/upload/vod/20260602-1/010901257a135570df278921256c670d.jpg', '<p>Qistina và Aqil đến sống trong nhà của người cha quá cố, nơi những ảo ảnh đáng sợ ám ảnh cô. Nghi lễ của bà đồng mang lại bình yên trong chốc lát trước khi thế lực đen tối trở lại.</p>', 'Full', 1, 'single', 'completed', 31, 2026, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Qi Razali","avatar":""},{"name":"Yasmin Hani","avatar":""},{"name":"Maria Farida","avatar":""},{"name":"Namron","avatar":""},{"name":"Hilal Azman","avatar":""},{"name":"Nafiz Anuar","avatar":""},{"name":"Rhea Ervina","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Lakhus: Tangisan Iblis","Pemuja"]', 1784690324121);
