INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ao-giac-mau', 'Ảo Giác Máu', 'Blood Devotion', 'ảo giác máu blood devotion qi razali yasmin hani maria farida namron hilal azman nafiz anuar rhea ervina lakhus: tangisan iblis pemuja', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luong-tran-my-cam', 'Lương Trần Mỹ Cẩm', 'A Splendid Match', 'https://phimimg.com/upload/vod/20260504-1/95985e2f2e38ad97c847ff0c7b375486.jpg', 'https://phimimg.com/upload/vod/20260504-1/52232226fda0a7c261fcd55d3a6dbdc2.jpg', '<p>Đại cô nương nhà họ Cố - Cố Cẩm Triêu (Nhậm Mẫn) từ nhỏ đã được nuôi dưỡng tại nhà ngoại tổ. Tuy bị cha mẹ ruột thờ ơ, nhưng nhờ được ngoại tổ mẫu yêu thương, nàng vẫn sống một cuộc đời tự do, phóng khoáng. Sau khi trở về nhà họ Cố, Cố Cẩm Triêu luôn mạnh mẽ đối đầu với mọi người và mọi việc. Khác biệt với những cô gái bình thường, nàng đã thu hút sự chú ý sâu sắc của các nhân vật quyền thế như trọng thần trong nội các - Trần Ngạn Doãn (Thử Sa), Thế tử gia Diệp Hạn (Đổng Tư Thành), và bậc quân tử đoan chính - Trần Huyền Thanh (Tả Diệp). Đối mặt với chuyện hôn nhân, Cố Cẩm Triêu có quan điểm riêng của mình. Khi dần hiểu rõ lòng mình, nàng kiên định lựa chọn Trần Ngạn Doãn - người tôn trọng bản chất thật của nàng và cho nàng được sống là chính mình. Sau khi thành hôn, nàng dần trưởng thành, trở thành người vợ xứng đáng của trọng thần, phụ tá Trần Ngạn Doãn bước lên vị trí Thủ phụ. Họ cùng nhau thực hiện các chính sách vì dân vì nước, xoa dịu nỗi khổ của bá tánh, kiến tạo thời đại thái bình thịnh trị.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 43, 2026, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Nhậm Mẫn","avatar":""},{"name":"Thử Sa","avatar":""},{"name":"Đổng Tư Thành","avatar":""},{"name":"Hoàng Nghệ","avatar":""},{"name":"Ngô Cương","avatar":""},{"name":"Tả Diệp","avatar":""},{"name":"Trương Diệu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Liang Chen Mei Jin","A Splendid Match","良陈美锦"]', 1784690324121);
