INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kinh-trap-vo-thanh', 'Kinh Trập Vô Thanh', 'Scare Out', 'https://phimimg.com/upload/vod/20260601-1/73b290df49db630e2753a5b47e8c7914.jpg', 'https://phimimg.com/upload/vod/20260601-1/f78950cb5149e82d07e822e42bb1c129.jpg', '<p>Nội dung kể về đội an ninh quốc gia mở chiến dịch “Kinh Trập” để truy tìm gián điệp và kẻ nội gián sau khi dữ liệu tuyệt mật bị đánh cắp. Trong quá trình điều tra, các thành viên liên tục nghi ngờ lẫn nhau, bị cài bẫy và thao túng bằng thông tin giả. Nhân vật trẻ Nghiêm Địch dần trở thành tâm điểm của cuộc đấu trí khi thân phận thật của anh liên quan đến một kế hoạch nằm vùng kéo dài nhiều năm. Phim thiên về đấu não, phản gián và những cú twist kiểu “gián điệp trong gián điệp”.</p>', 'Full', 1, 'single', 'completed', 21, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Jackson Yee","avatar":""},{"name":"Zhu Yilong","avatar":""},{"name":"Song Jia","avatar":""},{"name":"Lei Jiayin","avatar":""},{"name":"Yang Mi","avatar":""},{"name":"Zhang Yi","avatar":""},{"name":"Liu Shishi","avatar":""},{"name":"Liu Yaowen","avatar":""},{"name":"Lin Boyang","avatar":""},{"name":"Pan Binlong","avatar":""},{"name":"Annabel Yao","avatar":""},{"name":"Duan Yihong","avatar":""},{"name":"Chen Minghao","avatar":""},{"name":"Jiang Qilin","avatar":""},{"name":"Wang Shengdi","avatar":""},{"name":"Huang Yan","avatar":""},{"name":"Fei Fan","avatar":""},{"name":"Jiang Pengyu","avatar":""},{"name":"Daniel Manwaring","avatar":""},{"name":"Yi Anxi","avatar":""},{"name":"Dai Wenbo","avatar":""},{"name":"D","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-