INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-loai-su-tra-thu', 'Thể Loại: Sự Trả Thù', 'Dhurandhar: The Revenge', 'https://phimimg.com/upload/vod/20260505-1/210f860465e0d0d55db47e196d655766.jpg', 'https://phimimg.com/upload/vod/20260505-1/e9b0ef30d1b3caaa042c990ab033dbca.jpg', '<p>Khi các băng đảng đối địch, quan chức tham nhũng và Thiếu tá Iqbal tàn nhẫn ngày càng siết chặt vòng vây, nhiệm vụ vì đất nước của Hamza dần biến thành một cuộc chiến cá nhân đẫm máu, nơi ranh giới giữa người yêu nước và kẻ tàn bạo biến mất trên đường phố Lyari.</p>', 'Full', 1, 'single', 'completed', 35, 2026, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Ranveer Singh","avatar":""},{"name":"Arjun Rampal","avatar":""},{"name":"R. Madhavan","avatar":""},{"name":"संजय दत्त","avatar":""},{"name":"Sara Arjun","avatar":""},{"name":"Rakesh Bedi","avatar":""},{"name":"Gaurav Gera","avatar":""},{"name":"Manav Gohil","avatar":""},{"name":"Danish Iqbal","avatar":""},{"name":"Ankit Sagar","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Dhurandhar 2","征服者2：复仇","Dhurandhar The Revenge (Raw & Undekha)","ปฏิบัติการกล้าสนั่นเมือง 2","ปฏิบัติการกล้าสนั่นเมือง: แค้นเดือดไร้ปรานี","Dhurandhar The Revenge","धुरंधर: द रिवेंज"]', 1784690324121);
