INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-moi-phan-8', 'Lính Mới (Phần 8)', 'The Rookie (Season 8)', 'https://phimimg.com/upload/vod/20260116-1/12bc365f98d70c5e3ab3b783500a78bf.jpg', 'https://phimimg.com/upload/vod/20260116-1/57b5ff4837c77ab0d389eb750ae35ead.jpg', '<p>John Nolan và biệt đội của mình được cử đi thực hiện một nhiệm vụ quốc tế đầy hiểm nguy tại Prague, trước khi quay trở lại với những mối đe dọa không ngừng biến đổi trong cuộc sống tại Sở Cảnh sát Los Angeles (LAPD). Ở quê nhà, đơn vị phải đối mặt với một cục diện đầy biến động bởi những áp lực chính trị, các mối đe dọa chưa được giải quyết và sự trở lại của những đối thủ cũ — bao gồm cả những manh mối cho thấy nữ luật sư tham nhũng Monica Stevens có thể sẽ sớm tái xuất.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 24, 2026, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Nathan Fillion","avatar":""},{"name":"Melissa O''Neil","avatar":""},{"name":"Eric Winter","avatar":""},{"name":"Alyssa Diaz","avatar":""},{"name":"Mekia Cox","avatar":""},{"name":"Richard T. Jones","avatar":""},{"name":"Shawn Ashmore","avatar":""},{"name":"Jenna Dewan","avatar":""},{"name":"Lisseth Chavez","avatar":""},{"name":"Deric Augustine","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["الروكي","菜鸟警察","The Rookie : Le Flic de Los Angeles","Ο Νεοσύλλεκτος","عنوان فارسی : تازه‌کار","ザ・ルーキ","더 루키","Руки","Новачок","The Rookie"]', 1784690324121);
