INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-oi', 'Thỏ Ơi!!', 'Bunny!!', 'https://phimimg.com/upload/vod/20260601-1/a93bfd52980655de0571d55d9c9f2440.jpg', 'https://phimimg.com/upload/vod/20260601-1/034afe4d9f1198904977bb7cd8297a56.jpg', '<p>Với tâm thế luôn mang đến những điều mới để cho khán giả của mình không nhàm chán, Thỏ Ơi!!&nbsp;-&nbsp;bộ phim điện ảnh thứ 4 của đạo diễn Trấn Thành hứa hẹn sẽ mang đến một màu sắc hoàn toàn khác biệt.</p>', 'Full', 1, 'single', 'completed', 81, 2026, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Trấn Thành","avatar":""},{"name":"Nguyen Dieu Huyen","avatar":""},{"name":"LyLy","avatar":""},{"name":"Pháp Kiều","avatar":""},{"name":"Gil Le","avatar":""},{"name":"Ali Hoàng Dương","avatar":""},{"name":"BB Trần","avatar":""},{"name":"Ngọc Diệp","avatar":""},{"name":"Quốc Anh","avatar":""},{"name":"Quỳnh Anh Shyn","avatar":""},{"name":"Ngọc Hoa","avatar":""},{"name":"Văn Mai Hương","avatar":""},{"name":"Vĩnh Đam","avatar":""},{"name":"Thanh Lam","avatar":""},{"name":"Khuyến Dương","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Thỏ Ơi!!"]', 1784690324121);
