INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xuan-dang-dang-sap-tan', 'Xuân Đằng Đẵng Sắp Tàn', 'Shadows Of The Late Spring', 'https://phimimg.com/upload/vod/20260601-1/368720d6e1c8b4cde873e93b46555649.jpg', 'https://phimimg.com/upload/vod/20260601-1/2a3fa0d974d65aeceb7ffba878f11d24.jpg', '<p>Nơi cung cấm sâu thẳm, nàng là nhị công chúa sắc sảo ẩn mình, chuyên tâm bào chế độc dược. Phía ngoài cung cấm, y là sát thủ mang mối thù diệt môn, mai danh ẩn tính, chỉ để tìm muội muội và báo thù. Trong một yến tiệc cung đình, người xưa đeo mặt nạ trở về, nhưng hình xăm sau lưng sớm đã bị xóa sạch. Y là cậu thiếu niên trong rừng sáu năm trước của nàng chăng? Nàng là người muội muội ruột thịt đã thất lạc nhiều năm của y chăng? Ngọc bội làm tín vật, hình xăm làm bằng chứng, thì ra hết thảy đều hướng về một âm mưu động trời. Tranh giành quyền lực, thân thế hoán đổi, những ân oán đẫm máu của hai thế hệ, cuối cùng hóa thành một cuộc hợp tác gài bẫy để phản công trong tuyệt cảnh. Công chúa và thiếu niên, từ bỏ lỡ lúc nhận nhau đến khi thấu hiểu, bên nhau, mở ra một lối thoát từ trong kẽ hở giữa quyền mưu và chân tình.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 29, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Hiên","avatar":""},{"name":"Đặng Giai Úy","avatar":""},{"name":"Phòng Hàm Băng","avatar":""},{"name":"Trần Trí Tuệ","avatar":""},{"name":"Trương Thụy Ân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["迟迟春欲晚"]', 1784690324121);
