INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-trai-cua-mat-tich-ban-thai', 'Mặt Trái Của Mất Tích (Bản Thái)', 'Missing', 'https://phimimg.com/upload/vod/20260508-1/89eebf5df41b8d49a4ca3104fbae8b8d.jpg', 'https://phimimg.com/upload/vod/20260508-1/d831a279c7601239f09cc867d0c515c3.jpg', '<p>Tại một ngôi làng bí ẩn, có những linh hồn vất vưởng vẫn chưa thể siêu thoát vì cái chết của họ vẫn còn nhiều uẩn khúc. Trong lúc đi tìm một đứa trẻ mất tích, thám tử tư Thamnitthi đã vô tình đặt chân đến ngôi làng này và phát hiện anh có khả năng nhìn thấy những hồn ma ở nơi đây. Cũng từ đó, anh bắt đầu bước chân vào hành trình làm sáng tỏ sự thật phía sau sự ra đi của những người đã khuất để giúp họ an lòng rời khỏi thế giới người sống và sang thế giới bên kia.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 25, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Norraphat Vilaiphan","avatar":""},{"name":"Ployshompoo Supasap","avatar":""},{"name":"Panuwat Premmaneenan","avatar":""},{"name":"Chatchai Plengpanich","avatar":""},{"name":"Poon Mitpakdee","avatar":""},{"name":"Supitcha Sangkhachinda","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Missing ห่วง หาย ตาย จาก"]', 1784690324121);
