INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luc-luong-marshals', 'Lực Lượng Marshals', 'Marshals', 'https://phimimg.com/upload/vod/20260313-1/4409eaf231fcbcf80844dc99467dcf95.jpg', 'https://phimimg.com/upload/vod/20260313-1/3f3338df36c67cc619fb17365f9529de.jpg', '<p>Rời xa trang trại Yellowstone, Kayce Dutton gia nhập một đơn vị tinh nhuệ của Lực lượng Cảnh sát Tư pháp Hoa Kỳ (U.S. Marshals). Tại đây, anh kết hợp kỹ năng của một chàng cao bồi và một đặc nhiệm Navy SEAL để thực thi công lý trên các vùng thảo nguyên ở Montana. Anh cùng các đồng đội phải tìm cách cân bằng giữa gia đình, nghĩa vụ và những cái giá đắt về tâm lý khi đóng vai trò là lá chắn cuối cùng trong cuộc chiến chống bạo lực tại khu vực này.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Luke Grimes","avatar":""},{"name":"Logan Marshall-Green","avatar":""},{"name":"Arielle Kebbel","avatar":""},{"name":"Ash Santos","avatar":""},{"name":"Tatanka Means","avatar":""},{"name":"Brecken Merrill","avatar":""},{"name":"Mo Brings Plenty","avatar":""},{"name":"Gil Birmingham","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Marshals: Një histori nga Yellowstone","法警小队","Y: Marssalid","Marshals: A Yellowstone Story","Yellowstone: Marshals","Y: Marshals","Marshals"]', 1784690324121);
