INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('instadocs-alex-murdaugh-huy-ket-an', 'Instadocs: Alex Murdaugh, Hủy Kết Án', 'Instadocs: Alex Murdaugh, Unconvicted', 'https://phimimg.com/upload/vod/20260531-1/11f74b667d4825bb56146b2ddb6499fe.jpg', 'https://phimimg.com/upload/vod/20260531-1/b34b38765d3ac3bd45344043404747e1.jpg', '<p>Tại sao bản án của Alex Murdaugh lại bị lật ngược? Tập phim mở màn của loạt phim &quot;Instadocs&quot; sẽ đi sâu bóc tách những cáo buộc gây rúng động về hành vi can thiệp và tác động đến bồi thẩm đoàn trong phiên tòa xét xử tội danh sát hại hai mạng người của ông ta.</p>', 'Full', 1, 'single', 'completed', 11, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Alex Murdaugh","avatar":""},{"name":"Alan Wilson","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Alex Murdaugh, Unconvicted","Instadocs: Alex Murdaugh, Unconvicted"]', 1784690324121);
