INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-giam-2026', 'Lồng Giam', 'Cage Of Shadows', 'https://phimimg.com/upload/vod/20260530-1/684a5fa72bc466c54faf39a83819b6ae.jpg', 'https://phimimg.com/upload/vod/20260530-1/915600ba656eabe07318828e3ed99166.jpg', '<p>Nam Yên Chỉ, con gái của một người thợ thủ công, phải gánh chịu thảm kịch khi cả gia đình bị tàn sát. Sau biến cố, nàng bái Trang Vô Cữu làm sư phụ, từ một cô gái ngây thơ thuần khiết học cách biến mình thành một &quot;ác nữ&quot; gai góc, chấp nhận giãy giụa trong vũng bùn tăm tối. Dựa vào những manh mối ít ỏi có được, nàng đơn thương độc mã thâm nhập vào Linh Nhai Tháp để thực hiện kế hoạch trả thù. Theo lời đồn đại, bất kỳ ai bước chân vào Linh Nhai Tháp đều sẽ biến thành dã thú trong đấu trường và không một ai có thể sống sót trở ra. Ngay vào khoảnh khắc Nam Yên Chỉ ngỡ rằng bản thân hoàn toàn cô độc và không lời trợ giúp, nàng lại kinh hoàng nhận ra Trang Vô Cữu đang đứng đó với tư cách là kẻ thống trị tối cao của Linh Nhai Tháp…</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 27, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Mỹ Hàm","avatar":""},{"name":"Phó Tương","avatar":""},{"name":"Mộc Lam","avatar":""},{"name":"Vương Trữ Đan","avatar":""},{"name":"Liễu Giai Hy","avatar":""},{"name":"Lôi Hạo Tường","avatar":""},{"name":"Lý Tịch Mạn","avatar":""},{"name":"Lý Giai Di","avatar":""},{"name":"Triệu Thiến","avatar":""},{"name":"Đào Đức Yến","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["樊笼"]', 1784690324121);
