INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('long-giam-2026', 'Lồng Giam', 'Cage Of Shadows', 'lồng giam cage of shadows lưu mỹ hàm phó tương mộc lam vương trữ đan liễu giai hy lôi hạo tường lý tịch mạn lý giai di triệu thiến đào đức yến 樊笼', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('emi-martinez-cau-be-ngung-thoi-gian-dibu-martinez-el-pibe-que-ataja-el-tiempo', 'Emi Martínez Cậu Bé Ngừng Thời Gian (Dibu Martínez: El pibe que ataja el tiempo)', 'Emi Martínez: The Kid Who Stops Time', 'https://phimimg.com/upload/vod/20260530-1/39bcdeb29a5790bfd8eb6b5f19a22856.jpg', 'https://phimimg.com/upload/vod/20260530-1/2587b7d726a7e75478d0a3e407abe990.jpg', '<p>Emiliano, một cậu bé hay mơ mộng đến từ vùng Mar del Plata, đã vươn mình trở thành &quot;Dibu&quot; mà tất cả chúng ta đều biết đến ngày hôm nay – một trong những người hùng vĩ đại nhất của nền bóng đá Argentina. Được chấp bút bởi biên kịch Hernán Casciari và dàn dựng dưới bàn tay đạo diễn Gustavo Cova, tác phẩm kể về câu chuyện của cậu nhóc năm nào tình cờ phát hiện mình sở hữu siêu năng lực ngưng đọng thời gian, và những cuộc tranh luận của cậu với quả bóng – thứ luôn nhắc nhở cậu về tất cả những thử thách đang đợi phía trước. Bằng sự kết hợp khéo léo giữa các thước phim hoạt hình sống động được sáng tạo bởi Liniers, tư liệu lưu trữ chân thực cùng các cuộc phỏng vấn độc quyền với bạn bè, gia đình và đồng đội, bộ phim là một câu chuyện vừa dịu dàng vừa quả cảm về cách mà sức mạnh nội tại đã dẫn lối anh chạm tay đến vinh quang, trở thành nguồn cảm hứng bất tận cho các thế hệ mai sau.</p>', 'Full', 1, 'single', 'completed', 38, 2026, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Emiliano Martínez","avatar":""},{"name":"Lionel Messi","avatar":""},{"name":"Agustín Aristarán","avatar":""},{"name":"Lionel Scaloni","avatar":""},{"name":"Miguel Ángel \"Pepé\" Santoro","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Dibu Martínez: El pibe que ataja el tiempo"]', 1784690324121);
