INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-nhuyen-dich-than-khi-than-mem-long', 'Tâm Nhuyễn Đích Thần (Khi Thần Mềm Lòng)', 'Soft-Hearted God', 'https://phimimg.com/upload/vod/20260524-1/128163c2939ea8f5e3b4608393bdd21d.jpg', 'https://phimimg.com/upload/vod/20260524-1/11c5f80d9e55c2050d0f4e42439753b4.jpg', '<p>Thần Diêm Triệu giáng trần vì tình yêu, nhưng lại vướng vào mối tình với Công chúa Chu Hi Hi, người che giấu một thân phận kép nguy hiểm. Mối quan hệ của họ kéo dài qua nhiều kiếp, đối mặt với số phận, quyền lực và những sự thật bị chôn vùi, cuối cùng hé mở một câu chuyện về lòng tận tụy và sự hy sinh.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 30, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Nghiêm Tử Hiền","avatar":""},{"name":"Ô Nhật Lệ Cách","avatar":""},{"name":"Quách Hinh Ngọc","avatar":""},{"name":"Vu Dương","avatar":""},{"name":"Sách Á Tín","avatar":""},{"name":"Khôi Nguyên","avatar":""},{"name":"Chung Tinh Huy","avatar":""},{"name":"Lôi Chú","avatar":""},{"name":"Vương Nghệ Bác","avatar":""},{"name":"Quyền Duệ","avatar":""},{"name":"Vương Tinh Khải","avatar":""},{"name":"Mạnh Lộ Minh","avatar":""},{"name":"Tôn Dực Đằng","avatar":""},{"name":"Uông Điềm Nhĩ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["心软的神"]', 1784690324121);
