INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-chung-cuoi-cung-phan-2', 'Nhân Chứng Cuối Cùng (Phần 2)', 'A Good Girl''s Guide To Murder (Season 2)', 'https://phimimg.com/upload/vod/20260530-1/a9d19e7f94dc24d5bb9558b293d49721.jpg', 'https://phimimg.com/upload/vod/20260530-1/886ce7843b33d86c160bae086994d387.jpg', '<p>Năm năm sau cái chết của cô nữ sinh Andie Bell, Pippa Fitz-Amobi quyết định bắt tay vào hành trình phơi bày sự thật về những gì đã thực sự xảy ra với nạn nhân. Sal Singh, bạn trai của Andie, từng thừa nhận bản thân là hung thủ trước khi tự kết liễu đời mình, thế nhưng Pip không tin anh là kẻ thủ ác. Cô đã bắt tay với Ravi, em trai của Sal, để cùng lật lại vụ án nhằm tìm ra chân tướng. Nếu như Sal Singh thực sự bị oan và kẻ thủ ác vẫn đang nhởn nhơ ngoài vòng pháp luật, hắn sẽ sẵn sàng đi xa đến mức nào để ngăn cản Pip tìm ra sự thật?</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 36, 2026, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Emma Myers","avatar":""},{"name":"Zain Iqbal","avatar":""},{"name":"Asha Banks","avatar":""},{"name":"Yasmin Al-Khudhairi","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["好女孩的谋杀手册","好女孩的谋杀调查报告","好女孩的谋杀调查指南","Meurtre Mode d''Emploi","Flinke pikers håndbok for mord","دليل جرائم القتل من فتاة صالحة","A Good Girl''s Guide to Murder"]', 1784690324121);
