INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bon-mua-phan-2', 'Bốn Mùa (Phần 2)', 'The Four Seasons (Season 2)', 'https://phimimg.com/upload/vod/20260530-1/1d11ac46cb39b64778a6e79d8a64b70a.jpg', 'https://phimimg.com/upload/vod/20260530-1/494e58a0b0ba40476967ccbfb665fc78.jpg', '<p>Tình bạn kéo dài hàng thập kỷ của ba cặp vợ chồng bị thử thách khi một đôi ly hôn, khiến truyền thống đi nghỉ cuối tuần hàng quý của họ trở nên rối rắm.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 14, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tina Fey","avatar":""},{"name":"Colman Domingo","avatar":""},{"name":"Erika Henningsen","avatar":""},{"name":"Kerri Kenney","avatar":""},{"name":"Will Forte","avatar":""},{"name":"Marco Calvani","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["四季情","他们的春夏秋冬","The Four Seasons"]', 1784690324121);
