INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-calabasas', 'Bí Mật Calabasas', 'Calabasas Confidential', 'https://phimimg.com/upload/vod/20260530-1/2f5598f9b12fdaa796704e7276f3e772.jpg', 'https://phimimg.com/upload/vod/20260530-1/848a5dfbaf711237a36048eb4cafa647.jpg', '<p>Sau khi tốt nghiệp đại học, cả nhóm cùng quay trở lại Calabasas để tận hưởng &quot;một mùa hè họ sẽ không bao giờ quên&quot;. Trở về nhà và sống trong những căn biệt thự xa hoa của cha mẹ trên sườn đồi, họ phải đối mặt với thực tế khó khăn khi phải giải quyết những mâu thuẫn chưa có hồi kết trong quá khứ, đồng thời cố gắng định hình hướng đi tiếp theo cho cuộc sống và các mối quan hệ của mình. Bốn năm xa cách có thể đã tạo ra khoảng cách giữa họ, nhưng những ngọn lửa tình yêu mới, những mối thù hằn cũ và những bí mật không ngờ tới sẽ không thể mãi giữ kín phía sau cánh cổng của mã bưu chính được thèm khát nhất Los Angeles.</p>', 'Hoàn Tất (8/8)', 8, 'tvshows', 'completed', 29, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Suede Brooks","avatar":""},{"name":"Sterling Retzlaff","avatar":""},{"name":"Raine Michaels","avatar":""},{"name":"Preston Pippen","avatar":""},{"name":"Hercy Miller","avatar":""},{"name":"Nicole Sahebi","avatar":""},{"name":"Kimora Lewis","avatar":""},{"name":"Jemma Durrant","avatar":""},{"name":"Alexie Olivo","avatar":""},{"name":"Emilie Nelson","avatar":""},{"name":"Emma Medrano","avatar":""},{"name":"Ben Favaedi","avatar":""},{"name":"Dylan Wolf","avatar":""},{"name":"Jodie Woods","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Calabasas Confidential"]', 1784690324121);
