INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('san-khau-uoc-mo', 'Sân Khấu Ước Mơ', 'DREAM STAGE', 'https://phimimg.com/upload/vod/20260502-1/f66a1952cdc0568f2129111f0197737b.jpg', 'https://phimimg.com/upload/vod/20260502-1/1cb65ce5abb839eaf78bdbe74dbebe63.jpg', '<p>Phim kể về mối liên kết bền chặt giữa một nam nhà sản xuất âm nhạc người Nhật từng rất tài năng nhưng bị đuổi khỏi ngành sau khi gây ra rắc rối trong quá khứ, và bảy thực tập sinh “đội sổ” của một công ty giải trí nhỏ ở Hàn Quốc. Họ cùng nhau vượt qua khác biệt về thế hệ, quốc tịch và những thất bại cá nhân để theo đuổi giấc mơ tỏa sáng trong ngành công nghiệp K-pop đầy cạnh tranh.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 28, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Tomoya Nakamura","avatar":""},{"name":"Elaiza Ikeda","avatar":""},{"name":"Yoji Iwase","avatar":""},{"name":"Lee Yi-kyung","avatar":""},{"name":"Ha Yeon-soo","avatar":""},{"name":"Kim Jae-kyung","avatar":""},{"name":"Jung Ho-jin","avatar":""},{"name":"Riku Shiga","avatar":""},{"name":"松瀬太虹","avatar":""},{"name":"ISAAC (KAJA)","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["ドリームステージ","金曜ドラマ DREAM STAGE","DREAM STAGE"]', 1784690324121);
