INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('frieren-phap-su-tien-tang-phan-2', 'Frieren: Pháp Sư Tiễn Táng (Phần 2)', 'Frieren: Beyond Journey''s End (Season 2)', 'https://phimimg.com/upload/vod/20260118-1/78361b7dccef8920073dc9d7464f0729.jpg', 'https://phimimg.com/upload/vod/20260118-1/40488f12abb7092629737b64256b8c01.jpg', '<p>Tiếp nối câu chuyện kỳ ảo và giàu cảm xúc của Frieren - một pháp sư sống lâu hơn hầu hết những người bạn đồng hành - sau khi Ma Vương bị đánh bại. Trải qua nhiều biến cố và mất mát ở mùa đầu tiên, Frieren cùng học trò Fern và chiến binh Stark tiếp tục hành trình hướng về phương Bắc, đối mặt với những thử thách mới và tàn dư của kẻ thù. Trên chặng đường ấy, họ dần thấu hiểu sâu sắc hơn về ý nghĩa của cuộc sống, ký ức và những cảm xúc mong manh của con người hữu hạn. Hành trình này không chỉ là một chuyến phiêu lưu, mà còn là con đường tìm kiếm câu trả lời cho quá khứ và tương lai.</p>', 'Hoàn Tất (10/10)', 10, 'hoathinh', 'completed', 29, 2026, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Atsumi Tanezaki","avatar":""},{"name":"Kana Ichinose","avatar":""},{"name":"Chiaki Kobayashi","avatar":""},{"name":"Nobuhiko Okamoto","avatar":""},{"name":"Hiroki Touchi","avatar":""},{"name":"Yoji Ueda","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["葬送的芙莉莲","Sósó no Frieren","葬送的芙莉蓮","פ