INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-khong-gian-phan-5', 'Cuộc Chiến Không Gian (Phần 5)', 'For All Mankind (Season 5)', 'https://phimimg.com/upload/vod/20260328-1/67e6e6d30e92a915772037bc76969520.jpg', 'https://phimimg.com/upload/vod/20260328-1/0d85497eac010d38bb678fe3d666731e.jpg', '<p>Thế giới sẽ ra sao nếu cuộc chạy đua vào không gian chưa bao giờ kết thúc? Ronald D. Moore thử tìm lời đáp qua câu chuyện giả tưởng ly kỳ về các phi hành gia ngôi sao của NASA và gia đình họ.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 16, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Joel Kinnaman","avatar":""},{"name":"Toby Kebbell","avatar":""},{"name":"Mireille Enos","avatar":""},{"name":"Edi Gathegi","avatar":""},{"name":"Cynthy Wu","avatar":""},{"name":"Coral Peña","avatar":""},{"name":"Costa Ronin","avatar":""},{"name":"Sean Kaufman","avatar":""},{"name":"Ruby Cruz","avatar":""},{"name":"Wrenn Schmidt","avatar":""},{"name":"Ines Høysæter Asserson","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bütün İnsanlıq Üçün","为全人类","עבור כל האנושות","برای همه بشریت","Ради всего человечества","For All Mankind"]', 1784690324121);
