INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-chien-khong-gian-phan-5', 'Cuộc Chiến Không Gian (Phần 5)', 'For All Mankind (Season 5)', 'cuộc chiến không gian (phần 5) for all mankind (season 5) joel kinnaman toby kebbell mireille enos edi gathegi cynthy wu coral peña costa ronin sean kaufman ruby cruz wrenn schmidt ines høysæter asserson bütün i̇nsanlıq üçün 为全人类 עבור כל האנושות برای همه بشریت ради всего человечества for all mankind', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-giu-den-o-chua-ky-cot', 'Người Giữ Đèn Ở Chùa Ký Cốt', 'LightKeeper Of Jigu Temple', 'https://phimimg.com/upload/vod/20260518-1/3edc00db70c870aa5e04c20148e6db04.jpg', 'https://phimimg.com/upload/vod/20260518-1/86e453a3ea87cd3603483e54a458c7d2.jpg', '<p>Giữa thời quân phiệt hỗn chiến loạn lạc, một quân y nghiện rượu biệt danh Lão Tửu Quỷ trở về quê nhà, tá túc trong ngôi chùa lưu giữ hài cốt. Tại đây, ông cứu góa phụ Như Linh, vạch trần âm mưu &quot;tế sống trẻ con cho Sơn Thần&quot; và trở thành người canh đèn của ngôi chùa. Ông cảm hóa gã lãng tử Đông Sinh, giúp anh phá vụ án buôn lậu vũ khí, cứu Thu Anh khỏi số phận vật hiến tế, đồng thời đấu trí với tà giáo và giải cứu những chí sĩ yêu nước. Cuối cùng, Lão Tửu Quỷ thanh thản nhắm mắt xuôi tay, còn những người từng được ông cứu đều dấn thân vào con đường cách mạng.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 20, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lâm Gia Xuyên","avatar":""},{"name":"Lưu Nghệ Đồng","avatar":""},{"name":"Dụ Cương","avatar":""},{"name":"Tề Thần Quân","avatar":""},{"name":"Tống Ngôn Chi","avatar":""},{"name":"Vương Hiểu Thần","avatar":""},{"name":"Tiền Tinh Duệ","avatar":""},{"name":"Hùng Dục Quyền","avatar":""},{"name":"Lý Trạch Vũ","avatar":""},{"name":"Hoàng Húc Cao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["寄骨寺守灯人"]', 1784690324121);
