INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bu-nhin-bong-dem', 'Bù Nhìn Bóng Đêm', 'The Scarecrow', 'https://phimimg.com/upload/vod/20260421-1/ca215496bd35f5555a42db46c6929593.jpg', 'https://phimimg.com/upload/vod/20260421-1/f650d2178218b84e7277bdafbf2a95b9.jpg', '<p>Bị giáng chức về vùng quê Gangseong, cựu thám tử sừng sỏ Kang Tae-ju rơi vào tâm điểm của chuỗi vụ án giết người hàng loạt rúng động. Để lật tẩy sự thật tàn khốc bị vùi lấp suốt 31 năm (từ 1988 đến 2019) và khôi phục lại danh dự, anh buộc phải bắt tay với kẻ mình căm ghét nhất - công tố viên Cha Shi-young. Khi lần theo sự thật, họ nhận ra kẻ sát nhân không chỉ lặp lại quá khứ mà đang hoàn thành thứ còn dang dở.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 34, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Hae-soo","avatar":""},{"name":"Lee Hee-jun","avatar":""},{"name":"Kwak Sun-young","avatar":""},{"name":"Seo Ji-hye","avatar":""},{"name":"Jung Moon-sung","avatar":""},{"name":"Bek Hyun-jin","avatar":""},{"name":"Yoo Seung-mok","avatar":""},{"name":"Lee Suk-hyeong","avatar":""},{"name":"Kim Hwan-hee","avatar":""},{"name":"Song Geon-hee","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["かかし","The Scarecrow","허수아비"]', 1784690324122);
