INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rac-roi-tien-bac-cua-margo', 'Rắc Rối Tiền Bạc Của Margo', 'Margo''s Got Money Troubles', 'https://phimimg.com/upload/vod/20260420-1/eb8e826d7fed0482bd24c6cb8bcd5fd6.jpg', 'https://phimimg.com/upload/vod/20260420-1/661235c88b4beb7cf1d5c8be427deef0.jpg', '<p>Khi nữ nhà văn đầy tham vọng Margo Millet mang thai, cô buộc phải bỏ dở đại học và đối mặt với cảnh túng quẫn. Nhưng khi người cha xa cách là cựu đô vật chuyên nghiệp xuất hiện, Margo tìm thấy một cách bất ngờ để kiếm tiền từ tài năng kể chuyện của mình.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 19, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Elle Fanning","avatar":""},{"name":"Nick Offerman","avatar":""},{"name":"Greg Kinnear","avatar":""},{"name":"Thaddea Graham","avatar":""},{"name":"Michael Angarano","avatar":""},{"name":"Michelle Pfeiffer","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Margo e a Falta de Dinheiro","מרגו צריכה כסף","Margo ha problemi di soldi","Margo''nun Paraya İhtiyacı Var","Margo''s Got Money Troubles"]', 1784690324122);
