INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('rac-roi-tien-bac-cua-margo', 'Rắc Rối Tiền Bạc Của Margo', 'Margo''s Got Money Troubles', 'rắc rối tiền bạc của margo margo''s got money troubles elle fanning nick offerman greg kinnear thaddea graham michael angarano michelle pfeiffer margo e a falta de dinheiro מרגו צריכה כסף margo ha problemi di soldi margo''nun paraya i̇htiyacı var margo''s got money troubles', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luat-cam-yeu-em', 'Luật Cấm Yêu Em', 'Girl Rules', 'https://phimimg.com/upload/vod/20260311-1/b5c270f3b1a4cd449a40eb691d78b519.jpg', 'https://phimimg.com/upload/vod/20260311-1/66497c2b4712eb6e0db16dda17fe1225.jpg', '<p>Bộ phim khám phá những mối quan hệ đan xen phức tạp của sáu người phụ nữ.&nbsp; Trung tâm của câu chuyện là Bambi, người bất ngờ xuất hiện trở lại trong cuộc đời của bạn gái cũ. Cô thuê Prim — một doanh nhân đang lên, người cùng bạn thân Min điều hành một công ty quảng cáo — để dẫn dắt chiến dịch cho thương hiệu thời trang mới của mẹ mình.&nbsp; Chiến dịch này quy tụ một đội ngũ đầy năng động: Gorya, đàn em khóa dưới thời trung học của Prim, được chỉ định làm stylist cho dự án; trong khi đó, nàng mẫu đầy lôi cuốn Shasha trở thành gương mặt đại diện cho chiến dịch. Sự phức tạp càng tăng thêm khi Praew — một nhiếp ảnh gia tài năng tại hộp đêm mà Min thường ghé thăm — cũng tham gia vào đội ngũ sản xuất.&nbsp; Thông qua những mối liên kết ngày càng rắc rối giữa họ, bộ phim hé lộ lý do tại sao các quy tắc luôn tồn tại trong cả kinh doanh lẫn tình yêu, và điều gì sẽ xảy ra khi những ranh giới đó bị vượt qua.</p>', 'Tập 11', 12, 'series', 'ongoing', 18, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Tipnaree Weerawatnodom","avatar":""},{"name":"Rachanun Mahawan","avatar":""},{"name":"Pansa Vosbein","avatar":""},{"name":"Pattranite Limpatiyakorn","avatar":""},{"name":"Benyapa Jeenprasom","avatar":""},{"name":"Rattanawadee Wongtong","avatar":""},{"name":"Rutricha Phapakithi","avatar":""},{"name":"Alissa Intusmith","avatar":""},{"name":"Mintita Wattanakul","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Girl Rules กฎหลัก...ห้ามรักเธอ","Girl Rules Special","กฎหลัก...ห้ามรักเธอ"]', 1784690324122);
