INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-san-hoa-hong', 'Thợ Săn Hoa Hồng', 'Rose Hunter', 'https://phimimg.com/upload/vod/20260524-1/0654edecf1604c6a1993dd5f314828ed.jpg', 'https://phimimg.com/upload/vod/20260524-1/6227f05fdf3ee0d42f0b9ce6bb95163d.jpg', '<p>Sau một tai nạn khiến cô mất thị lực và chồng mất tích bí ẩn, nữ thừa kế Diệp Chi Mỹ phát hiện người đàn ông chăm sóc mình có thể đang giả danh chồng cô. Khi dần lấy lại ánh sáng, cô bắt đầu lần theo âm mưu đen tối xoay quanh tài sản khổng lồ và những bí mật chết người.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 14, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đặng Khải","avatar":""},{"name":"Trương Sở Hàn","avatar":""},{"name":"Lưu Dĩ Hòa","avatar":""},{"name":"Ái Lệ Phi Á","avatar":""},{"name":"Dương Lâm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mei Gui Lie Shou","女子推理社","玫瑰猎手"]', 1784690324122);
