INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-an-han-tich-dau-vet-toi-ac', 'Tội Án Hằn Tích (Dấu Vết Tội Ác)', 'Echoes Of Evidence', 'https://phimimg.com/upload/vod/20260524-1/2529705168c8822656c75bef862b80e1.jpg', 'https://phimimg.com/upload/vod/20260524-1/87a88eed1c0fc2c525f8a90fcac8e102.jpg', '<p>Một chuyên gia dấu vết pháp y và một thám tử đã bắt tay cùng nhau để phá giải một loạt các vụ án kỳ lạ, đồng thời vạch trần những bi kịch tăm tối của con người trong suốt cuộc hành trình. Khi cuộc điều tra ngày càng đi vào chiều sâu, họ phát hiện ra một mối liên hệ ẩn giấu với một vụ án mạng từ một thập kỷ trước — và một nhân vật bí ẩn có khả năng xóa sạch mọi dấu vết.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 24, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cảnh Nghiệp Đình","avatar":""},{"name":"Lý Mộc Phong","avatar":""},{"name":"Ngô Linh Vi","avatar":""},{"name":"Tông Phong Nham","avatar":""},{"name":"Trương Kỳ","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["罪案痕迹"]', 1784690324122);
