INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tien-nhan-chi-thuong', 'Tiên Nhân Chi Thượng', 'Beyond Immortals', 'tiên nhân chi thượng beyond immortals quách ngô quận mã đông thần vương nam đỗ tôn vũ dư trương song lợi lý nhược châu tưởng thân xian ren zhi shang 仙人之上', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ga-trong-2026', 'Gà Trống (Ông Già Lắm Chiêu)', 'Rooster', 'https://phimimg.com/upload/vod/20260422-1/7a19187507f49b618a1dd61015be9f96.jpg', 'https://phimimg.com/upload/vod/20260422-1/680a37852cf10049213f37556f4c249a.jpg', '<p>Chuyến hành trình của một chàng trai trẻ để tham dự một đám tang và một đám cưới trong cùng một ngày đã trở thành bước ngoặt giúp anh khám phá lại bản thân. Mọi chuyện bắt đầu khi anh bị mê hoặc bởi một cuộc gặp gỡ tình cờ trên đường đi. Giữa ranh giới mong manh của sự mất mát và niềm hạnh phúc, cuộc gặp gỡ định mệnh này đã khiến anh thay đổi hoàn toàn cách nhìn về cuộc sống, tình yêu và những giá trị thực sự mà mình đang tìm kiếm.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 9, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Steve Carell","avatar":""},{"name":"Danielle Deadwyler","avatar":""},{"name":"Phil Dunster","avatar":""},{"name":"John C. McGinley","avatar":""},{"name":"Lauren Tsai","avatar":""},{"name":"Charly Clive","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["公雞","Рустер","Rooster"]', 1784690324122);
