INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-hong-trang', 'Tẫn Hồng Trang', 'Vow In Ashes', 'https://phimimg.com/upload/vod/20260524-1/623665be9275fe91f529e41b371d30fe.jpg', 'https://phimimg.com/upload/vod/20260524-1/a103747a7c1d0cbd0e20c73c574e9775.jpg', '<p>Vào năm Xương Hòa thứ hai mươi tư, Thái Tổ băng hà đã làm bùng nổ một cuộc chiến giành ngôi vị tàn khốc. Trong cơn lốc quyền lực ấy, Yến Thanh Thù bị hãm hại dẫn đến việc bị hủy hôn, gia đình tan nát, người mất nhà tan, nhưng may mắn được Tiêu Cảnh Viêm ra tay cứu mạng. Để đòi lại công lý, hai người quyết định kết thành đồng minh, cùng nhau quay trở lại kinh thành để vạch ra kế hoạch báo thù.&nbsp; Tại nơi hoàng quyền đầy cạm bẫy, họ từng bước lột trần tội ác mưu phản của Lăng Vương và thế lực Tạ gia cùng các phe phái khác, đồng thời cùng nhau trải qua biết bao thử thách sinh tử để rồi dần nảy sinh tình cảm sâu đậm. Cuối cùng, cả hai đã sát cánh bên nhau phá tan đại cục, làm sáng tỏ mọi âm mưu đen tối, đứng vững trước sóng gió để xoay chuyển tình thế và tái thiết lại giang sơn đất nước giữa thời loạn lạc.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 20, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Dịch Khâm","avatar":""},{"name":"Chu Lệ Lam","avatar":""},{"name":"Âu Tĩnh Kiêu","avatar":""},{"name":"Hồ Tử Trình","avatar":""},{"name":"Hoàng Văn Khanh","avatar":""},{"name":"Chu Tuấn Phong","avatar":""},{"name":"Vương Sán Kỳ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["烬红妆"]', 1784690324122);
