INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tan-hong-trang', 'Tẫn Hồng Trang', 'Vow In Ashes', 'tẫn hồng trang vow in ashes triệu dịch khâm chu lệ lam âu tĩnh kiêu hồ tử trình hoàng văn khanh chu tuấn phong vương sán kỳ 烬红妆', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-hoa-duyen', 'Tẫn Hoa Duyên', 'Embers Of Love', 'https://phimimg.com/upload/vod/20260524-1/ed5a4039d8ef242a46262e143195154d.jpg', 'https://phimimg.com/upload/vod/20260524-1/7f4a99ba346047de33de1880530869b3.jpg', '<p>A Hoa vốn là một tinh linh thuộc Thiên Nhãn Bộ, vì lỡ tay phá hủy tiên sơn Ngạo Lai nên bị ép phải đến Ma tộc làm gián điệp, nhằm dò xét xem Ma quân Nhai Tứ có ý đồ tấn công Thần tộc hay không. Nhờ giọng ca và những bài dân ca của mình, cô đã lọt vào mắt xanh của Nhai Tứ và trở thành tỳ nữ thân cận bên cạnh hắn. Đại trưởng lão của Ma tộc – một kẻ khẩu Phật tâm xà (khẩu tiếu tâm đao) – muốn lôi kéo A Hoa về phe mình nhưng bị từ chối, gã liền sinh lòng thù hận và muốn giết cô để diệt khẩu.&nbsp; Vào khắc sinh tử, Nhai Tứ đã kịp thời ra tay cứu mạng cô, đồng thời nhận ra A Hoa chính là ân nhân từng cứu mạng mình từ một trăm năm trước nên đã chủ động cầu hôn cô. Qua những lần dò hỏi, A Hoa biết được Nhai Tứ thực chất không hề có kế hoạch khơi mào chiến tranh. Thế nhưng, cô lại bị Đán Cơ hãm hại và rơi vào bẫy rập. Sau khi chọn cách đồng quy vu tận với Đán Cơ, A Hoa được Thiên hậu hồi sinh và sắc phong vào hàng tiên ban, đồng thời cô cũng thực sự thấu hiểu được ý nghĩa của hai chữ trách nhiệm.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 20, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Niệm","avatar":""},{"name":"Lữ Huyễn Nhạc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["烬花缘"]', 1784690324122);
