INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-kien-nam-kieu', 'Nhất Kiến Nam Kiều', 'The First Sight Of Nanyang Overseas Chinese', 'https://phimimg.com/upload/vod/20260524-1/4a0ea39205684332498748c7d8c75bfa.jpg', 'https://phimimg.com/upload/vod/20260524-1/3b46549d7c7296779670a476110a3cf9.jpg', '<p>Sau khi sống sót qua một trận ném bom thời chiến năm 1941, Lâm Diệu Tổ — một tài xế tình nguyện người Hoa hải ngoại — đã dịch chuyển thời gian một cách bí ẩn đến năm 2025. Khi anh chia sẻ những hy sinh thầm lặng chưa từng được kể của các tài xế tình nguyện Nam Dương với Tống Dao và những người khác, chuyến du hành xuyên thời gian của anh đã kết nối thế hệ trẻ hiện đại với lòng yêu nước bất diệt và di sản kiên cường của những người Hoa hải ngoại trong thời chiến.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 12, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Diệp Vân Phỉ","avatar":""},{"name":"Chu Nhất","avatar":""},{"name":"Lưu Hàm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["一见·南侨"]', 1784690324122);
