INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chiec-ken-harmonica-sac-ben', 'Chiếc Kèn Harmonica Sắc Bén', 'Sharp Harmonica', 'https://phimimg.com/upload/vod/20260524-1/eed9204549ccf523b7d0690b76645975.jpg', 'https://phimimg.com/upload/vod/20260524-1/d8c05baae8b56b9eba3c16e3347692ba.jpg', '<p>Trong thời kỳ Nhật Bản chiếm đóng Cáp Nhĩ Tân, một nhóm kháng chiến bí mật cải trang thành một hội nhóm thổi kèn harmonica đã sử dụng âm nhạc để truyền tin tức tình báo và chiến đấu chống lại các thế lực thù địch, bất chấp việc phải chịu đựng những sự phản bội và hy sinh.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 14, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vu Chấn","avatar":""},{"name":"Mã Tâm Thụy","avatar":""},{"name":"Triệu Việt","avatar":""},{"name":"Tả Hàng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["锋利的口琴"]', 1784690324122);
