INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-giao-phoi', 'Mùa Giao Phối', 'Mating Season', 'https://phimimg.com/upload/vod/20260523-1/ab9832481194780fc40e86a197bdd38b.jpg', 'https://phimimg.com/upload/vod/20260523-1/7058eae9b6a1945a0de5d2b6b0e2040b.jpg', '<p>Từ những bộ óc quái chiêu của &quot;Lắm Chuyện&quot;, một loạt phim hoạt hình hài người lớn cực kỳ táo bạo về tình yêu, tình dục và các mối quan hệ trong thế giới động vật.</p>', 'Hoàn Tất (10/10)', 10, 'hoathinh', 'completed', 11, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Nick Kroll","avatar":""},{"name":"June Diane Raphael","avatar":""},{"name":"Zach Woods","avatar":""},{"name":"Sabrina Jalees","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mating Season"]', 1784690324122);
