INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kylie', 'Kylie', 'Kylie', 'https://phimimg.com/upload/vod/20260523-1/c507bca8b035b35cd463d1ceb9b73c0f.jpg', 'https://phimimg.com/upload/vod/20260523-1/731ab6bfa96ae3e19fcb72361c84ad62.jpg', '<p>Bộ phim mang đến cái nhìn sâu sắc về cuộc đời của Minogue, khi cô lần đầu mở lại kho lưu trữ cá nhân và chiêm nghiệm về một sự nghiệp lẫy lừng với hơn 80 triệu bản thu âm được bán ra, cùng những lần cô tự tái định hình bản thân – và qua đó là cả nền âm nhạc đại chúng. Những thước phim tự quay tại nhà, những bức ảnh cá nhân chưa từng công bố cùng các cuộc phỏng vấn mới nhất sẽ hé mở một bức tranh toàn cảnh về cuộc đời cô. Tại đây, nữ ca sĩ cũng thẳng thắn chia sẻ về cách cô đối diện với sự soi mói của công chúng, những mất mát cá nhân và cả những biến cố bạo bệnh trong đời.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kylie Minogue","avatar":""},{"name":"Dannii Minogue","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Kylie"]', 1784690324122);
