INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('desi-xa-hoa', 'Desi Xa Hoa', 'Desi Bling', 'https://phimimg.com/upload/vod/20260523-1/b168ac3c7986c8f892cbf62f1082b4c7.jpg', 'https://phimimg.com/upload/vod/20260523-1/f5740f4f97d2e61c3bff8fac6826372d.jpg', '<p>Những bữa tiệc lộng lẫy và các bí mật ngọt ngào ngập tràn trong cuộc sống của hội kiều bào Ấn Độ siêu giàu. Họ sẵn sàng chi tiền không tiếc tay — và cũng không ngần ngại tạo nên những màn kịch tính, thị phi đỉnh điểm.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 25, 2026, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Tejasswi Prakash","avatar":""},{"name":"Karan Kundra","avatar":""},{"name":"Dyuti Parruck","avatar":""},{"name":"Pamala Serena","avatar":""},{"name":"Alizey Mirza","avatar":""},{"name":"Rizwan Sajan","avatar":""},{"name":"Lailli Mirza","avatar":""},{"name":"Iryna Kinakh","avatar":""},{"name":"Tabinda Sanpal","avatar":""},{"name":"Satish Sanpal","avatar":""},{"name":"Sana Sajan","avatar":""},{"name":"Adel Sajan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["देसी ब्लिंग"]', 1784690324122);
