INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-nhuong-phai-dep', 'Xin Nhường Phái Đẹp', 'Ladies First', 'https://phimimg.com/upload/vod/20260523-1/1810473496ce7859dadc4c8b1e8cf0ca.jpg', 'https://phimimg.com/upload/vod/20260523-1/ae8b01cf4e0bae7c673fb62ce8bfa2db.jpg', '<p>Gã sát gái ngạo mạn nhưng cuốn hút thấy cuộc sống đầy tiền tài, quyền lực và những cuộc tình chớp nhoáng của mình bị đảo lộn khi tỉnh dậy ở thế giới song song nơi phụ nữ nắm quyền.</p>', 'Full', 1, 'single', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sacha Baron Cohen","avatar":""},{"name":"Rosamund Pike","avatar":""},{"name":"Tom Davis","avatar":""},{"name":"Emily Mortimer","avatar":""},{"name":"Weruche Opia","avatar":""},{"name":"Charles Dance","avatar":""},{"name":"Fiona Shaw","avatar":""},{"name":"Richard E. Grant","avatar":""},{"name":"Red Tennant","avatar":""},{"name":"Kathryn Hunter","avatar":""},{"name":"Kadiff Kirwan","avatar":""},{"name":"Bill Paterson","avatar":""},{"name":"Paul Chahidi","avatar":""},{"name":"Jordan Metcalfe","avatar":""},{"name":"Danny Ashok","avatar":""},{"name":"Dani Moseley","avatar":""},{"name":"Maddie Rice","avatar":""},{"name":"Ron C","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Сначала дамы","נשים תחילה","Ladies First"]', 1784690324122);
