INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('xin-nhuong-phai-dep', 'Xin Nhường Phái Đẹp', 'Ladies First', 'xin nhường phái đẹp ladies first sacha baron cohen rosamund pike tom davis emily mortimer weruche opia charles dance fiona shaw richard e. grant red tennant kathryn hunter kadiff kirwan bill paterson paul chahidi jordan metcalfe danny ashok dani moseley maddie rice ron c сначала дамы נשים תחילה ladies first', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tron-khong-thoat-toi', 'Trốn Không Thoát Tội', 'Inevitable Justice', 'https://phimimg.com/upload/vod/20260512-1/deb242e23a9fc12d4cf922fb7c09ce53.jpg', 'https://phimimg.com/upload/vod/20260512-1/2b64b47185b49f5d1c30bb944a38bafb.jpg', '<p>Để kiếm tiền chạy chữa cho con gái bị bệnh nặng, La Tiêu bị tên trùm băng đảng Trần Vĩnh Giang uy hiếp và vướng vào vụ án giết người chặt xác. Để tự bảo vệ mình, anh đã giết Trần Vĩnh Giang, thế chỗ hắn tiếp quản hoạt động rửa tiền của tổ chức tín dụng đen. Trong quá trình điều tra, cảnh sát Trương Hanh dần phát hiện ra dấu vết phạm tội của La Tiêu, cùng mạng lưới tài chính chằng chịt phía sau. Theo từng bước đi sâu điều tra của cảnh sát, cả mạng lưới tội phạm khổng lồ liên quan đến giết người, rửa tiền và góc khuất y tế dần được phơi bày qua hàng loạt những cuộc đối đầu và lựa chọn đầy kịch tính.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 19, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Giai Hàng","avatar":""},{"name":"Lưu Hải Khoan","avatar":""},{"name":"Từ Duyệt","avatar":""},{"name":"Hà Trung Hoa","avatar":""},{"name":"Trương Xuân Trọng","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Inevitable Justice","罪无可逃"]', 1784690324122);
