INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-yeu-mien-que', 'Người Yêu Miền Quê', 'Hometown Romance', 'https://phimimg.com/upload/vod/20260407-1/1dcc5617ab314f874e49844c210e96f6.jpg', 'https://phimimg.com/upload/vod/20260407-1/dad52d55fc16488e0a5b223aab03fe71.jpg', '<p>Si, một tiểu thư thừa kế của giới thượng lưu, luôn khao khát vị trí chủ tịch tập đoàn gia đình. Tuy nhiên, bố mẹ cô lại trao quyền điều hành cho người em gái, vì cho rằng Si quá nuông chiều bản thân, thiếu trách nhiệm và chỉ biết tiêu xài hoang phí. Khi công việc kinh doanh của gia đình rơi vào khủng hoảng do hợp đồng thuê đất quan trọng không được gia hạn, mọi nỗ lực thương lượng đều thất bại — cho đến khi Klaokavee, chủ sở hữu khu đất, đưa ra một đề nghị kỳ lạ: Cô sẽ gia hạn hợp đồng chỉ khi Si đồng ý kết hôn với mình. Bất chấp lối sống hoàn toàn trái ngược, cuộc hôn nhân sắp đặt này đã đưa cả hai vào một mối quan hệ đầy phức tạp và bất ngờ.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 31, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Punyapat Wangpongsathaporn","avatar":""},{"name":"Saranphat Pedersen","avatar":""},{"name":"Thanyares Chamnan","avatar":""},{"name":"Pisanu Chutanimsakul","avatar":""},{"name":"Supakson Ruengsomboon","avatar":""},{"name":"Narupornkamol Chaisang","avatar":""},{"name":"Supanut Satpan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["乡村恋人","คุณแฟนบ้านนอก","Khun Faen Ban Nok","สามีบ้านนอก","Hometown Romance"]', 1784690324122);
