INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('caro-tuyet-pham-carisima', 'Caro Tuyệt Phẩm (Carísima)', 'Carizzma', 'https://phimimg.com/upload/vod/20260521-1/54efefae890d8f9b47757f043732f6c0.jpg', 'https://phimimg.com/upload/vod/20260521-1/b8c6866d27844f38db2bc5c24c22411e.jpg', '<p><span class="">Caro Pardíaco,</span><span class=""> một nữ influencer lấp lánh và là một &quot;diva&quot; toàn thời gian,</span><span class=""> dường như đang sở hữu mọi thứ trong tay.</span><span class=""> Thế nhưng ở tuổi ba mươi,</span><span class=""> ngay giữa cuộc khủng hoảng tuổi trung niên,</span><span class=""> cô lại vô tình rơi vào bẫy lưới của một tình yêu lãng mạn.</span></p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 31, 2026, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Julián Kartun","avatar":""},{"name":"Alex Pelao","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Carísima"]', 1784690324122);
