INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('caro-tuyet-pham-carisima', 'Caro Tuyệt Phẩm (Carísima)', 'Carizzma', 'caro tuyệt phẩm (carísima) carizzma julián kartun alex pelao carísima', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-khong-co-co-tich', 'Tình Yêu Không Có Cổ Tích', 'Lady Liberty', 'https://phimimg.com/upload/vod/20260429-1/45bc3c41ca85315f1a483471c7a643c5.jpg', 'https://phimimg.com/upload/vod/20260429-1/df1097e4cb606360fbfa8cb7100916e5.jpg', '<p>Lâm Triển Kiều là một phụ nữ thành thị độc lập về kinh tế, chín chắn trong suy nghĩ. Xung quanh cô không thiếu người theo đuổi, nhưng cô vẫn lựa chọn cuộc sống độc thân. Không phải cô bài xích hôn nhân, mà là không muốn thỏa hiệp; sâu thẳm trong lòng, cô luôn khao khát một tình yêu chân thành và một cuộc hôn nhân thuần khiết. Sau khi gặp Hà Đức Chương, giữa hai người ban đầu tồn tại không ít hiểu lầm. Thế nhưng, trong hành trình cùng nhau trưởng thành và đứng trước những lựa chọn của tình yêu lẫn sự nghiệp, họ dần nhận ra đối phương chính là người bạn đời lý tưởng của mình. Vượt qua muôn vàn trở ngại từ thực tế, cả hai quyết định nắm tay bước vào hôn nhân. Những người bạn của Lâm Triển Kiều, sau khi đưa ra lựa chọn cho cuộc đời mình, cũng tìm được bến đỗ riêng. Cuối cùng, tất cả họ đều thấu hiểu ý nghĩa đích thực của tình yêu và hôn nhân, sống một cuộc đời bình dị mà hạnh phúc, giản đơn nhưng không hề tầm thường.</p>', 'Hoàn Tất (37/37)', 37, 'series', 'completed', 12, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đường Yên","avatar":""},{"name":"Triệu Hựu Đình","avatar":""},{"name":"Dương Thái Ngọc","avatar":""},{"name":"Phùng Thiệu Phong","avatar":""},{"name":"Yến Tử Đông","avatar":""},{"name":"Hà Lam Đậu","avatar":""},{"name":"Vương Cúc","avatar":""},{"name":"Trương Siêu","avatar":""},{"name":"Trần Hạo Sâm","avatar":""},{"name":"Nghê Hồng Khiết","avatar":""},{"name":"Lưu Quân","avatar":""},{"name":"Sa Bảo Lượng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["独身女人","Lady Liberty","爱情没有神话"]', 1784690324122);
