INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-gioi-the-thao-anh-quoc-phep-mau-istanbul-cua-liverpool', 'Bí Mật Giới Thể Thao Anh Quốc: Phép Màu Istanbul Của Liverpool', 'Untold UK: Liverpool''s Miracle Of Istanbul', 'https://phimimg.com/upload/vod/20260520-1/1153cd617fd97f3256be64f8ace76628.jpg', 'https://phimimg.com/upload/vod/20260520-1/2988c00ca2342ab3ef008344e0418e0c.jpg', '<p>Tại hiệp một của trận chung kết Champions League năm 2005, Liverpool đã bị dẫn trước với tỷ số 3-0. Những gì diễn ra tiếp theo sau đó đã đi vào lịch sử bóng đá thế giới – câu chuyện kinh điển này sẽ được tái hiện chân thực qua lời kể của chính các cầu thủ trong bộ phim tài liệu này.</p>', 'Full', 1, 'single', 'completed', 33, 2026, 'Vietsub', 'FHD', 'Thụy Sĩ', 0, '[{"name":"Jamie Carragher","avatar":""},{"name":"Steven Gerrard","avatar":""},{"name":"Rafael Benítez","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"}]', '["Untold UK: Liverpool''s Miracle of Istanbul"]', 1784690324122);
