INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('binh-thuong', 'Bình Thường', 'Normal', 'https://phimimg.com/upload/vod/20260520-1/ff87ba8a9e4579c5c18d4dd6893b6faa.jpg', 'https://phimimg.com/upload/vod/20260520-1/99878b96a60d02c323cc11cbef2d935d.jpg', '<p>Được điều động đến thị trấn Normal hẻo lánh ngập trong tuyết trắng tại bang Minnesota, vị cảnh sát trưởng lâm thời Ulysses vô tình lật tẩy một âm mưu tội phạm quốc tế ngay tại trung tâm của thị trấn nhỏ tưởng chừng như rất đỗi bình yên này. Mọi chuyện bắt đầu khi anh ra tay ứng cứu một cặp đôi cướp ngân hàng, những kẻ đang bị lún sâu và mắc kẹt trong một mớ hỗn độn chết chóc.</p>', 'Full', 1, 'single', 'completed', 25, 2026, 'Vietsub', 'FHD', 'Thụy Sĩ', 0, '[{"name":"Bob Odenkirk","avatar":""},{"name":"Ryan Allen","avatar":""},{"name":"Billy MacLellan","avatar":""},{"name":"Lena Headey","avatar":""},{"name":"Henry Winkler","avatar":""},{"name":"Reena Jolly","avatar":""},{"name":"Brendan Fletcher","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Normal"]', 1784690324122);
