INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-chien-thanh-long-trai', 'Huyến Chiến Thanh Long Trại', 'The Final Battle', 'https://phimimg.com/upload/vod/20260520-1/07161f06af3521c3af6222c577d97d59.jpg', 'https://phimimg.com/upload/vod/20260520-1/f791138e3e490157d63e7634ee4422bf.jpg', '<p>Đầu thời kỳ giải phóng, nạn cướp hoành hành. Trung đội trưởng trinh sát Quân Giải phóng Hướng Dương được lệnh tiến vào Tam Loan Lý trấn áp bọn cướp. Trong lúc cải trang thâm nhập, anh bất ngờ tái ngộ người anh trai Hướng Thiên, hiện là cậu ba của Thanh Phong Trại. Hai anh em vì lập trường đối lập, đã có những mâu thuẫn gay gắt giữa tình thân và lý tưởng. Hướng Dương cắn răng chịu đựng nội tâm giằng xé, nằm vùng trong hang ổ bọn cướp, dùng mưu trí lấy tình báo, đốt kho lương, phối hợp với đồng đội từ bên ngoài tấn công vây hãm. Trước sự phản kích tàn bạo của bọn cướp Long Mù, Hướng Dương dẫn dắt đơn vị chiến đấu ngoan cường. Nhờ sự hy sinh giúp đỡ của người anh Hướng Thiên, cuối cùng băng cướp Thanh Phong Trại bị tiêu diệt hoàn toàn. Sau cuộc chiến đấu đẫm máu và lửa đạn, vùng đất này cuối cùng cũng đón chào bình minh của hòa bình.</p>', 'Full', 1, 'single', 'completed', 12, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"La Lập Quần","avatar":""},{"name":"Đỗ Dịch Hoành","avatar":""},{"name":"Đỗ Lạc","avatar":""},{"name":"Thẩm Phương Hy","avatar":""},{"name":"Cố Vấn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Xue Zhan Qing Long Zhai","血战青龙寨"]', 1784690324122);
