INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duc-vong-tham-kin-canh-chim-giau-tinh', 'Dục Vọng Thầm Kín (Cánh Chim Giấu Tình)', 'Whisper of Desire', 'https://phimimg.com/upload/vod/20260428-1/9b44b7cce09f2ffb077471d2218892a1.jpg', 'https://phimimg.com/upload/vod/20260428-1/10603d35b81405c8b633a0a1b56e7fb2.jpg', '<p>Shen, con gái của một gia đình thương gia giàu có, bị ép gả cho Phoem – một người đàn ông mang nặng toan tính làm ăn. Hôm sau, Phoem bỏ Shen lại để sang Penang công tác ba tháng. Khi Phoem trở về, anh trở nên xa cách và không còn đụng chạm đến vợ. Cuộc sống của Shen hoàn toàn sụp đổ. Liệu cô có thể chạy trốn để bắt đầu lại, hay sẽ mãi bị trói buộc bởi thù hận và định mệnh?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 20, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Henry Myron","avatar":""},{"name":"Veerinsara Tangkitsuvanich","avatar":""},{"name":"Thanapat Kawila","avatar":""},{"name":"Akaravin Nanthipat","avatar":""},{"name":"Sinjai Plengpanich","avatar":""},{"name":"Pimlapas Jungsura","avatar":""},{"name":"Songsit Rungnopakunsi","avatar":""},{"name":"Klot Atthaseri","avatar":""},{"name":"Paweena Charivsakul","avatar":""},{"name":"Songsin Jaipan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["隐欲囚笼","飞鸟藏爱","Sakuna Son Rak","สกุณาซ่อนรัก"]', 1784690324122);
