INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bon-huyen-nha-la-phuc-tinh', 'Bổn Huyền Nha Là Phúc Tinh', 'The Crow Princess Of Fortune', 'https://phimimg.com/upload/vod/20260518-1/269b911e5a65c3ffdd833d0185f51c91.jpg', 'https://phimimg.com/upload/vod/20260518-1/5d84618135e167e5c95166923ed80247.jpg', '<p>Thiếu chủ Huyền Nha trời sinh được ban phúc, có thể giao tiếp với muông thú, nhưng lại bị hiểu lầm là kẻ mang tới xui xẻo nên bị vứt bỏ ở bãi tha ma. Nàng đại náo yến tiệc Hầu phủ, cứu mạng Tĩnh Vương Tiêu Hành - nam nhân mang mệnh Thiên Sát Cô Tinh. Dựa vào thần lực trời sinh cùng sự lanh lợi của mình, nàng đã diệt trừ yêu ma, đối đầu với lũ gian tà, tiêu diệt kẻ ác, vạch trần bí mật chốn hoàng cung, giúp Vương gia từng bước vực dậy. Từ &quot;miệng quạ đen&quot; bị người người chán ghét, nàng thay đổi số phận trở thành Phúc Tinh quận chúa, vừa đáng yêu vừa bá đạo, bảo vệ cha mình và xoay chuyển thiên mệnh.</p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 21, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hoàng Thiên Kỳ","avatar":""},{"name":"Dương Thù Âm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["本玄鸦是福星"]', 1784690324122);
