INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ca-con-cau-co', 'Cá Con Cau Có', 'The Pout-Pout Fish', 'https://phimimg.com/upload/vod/20260504-1/b7f9ecfbe2cd89e6cdbab2da48dc4382.jpg', 'https://phimimg.com/upload/vod/20260504-1/3691fae54d7ae1386cf2dee9d2f78367.jpg', '<p>Sống trên một con tàu đắm cũ nát, ông Cá một ngày nọ phát hiện ra một con rồng biển nhỏ hiếu động tên Pip – kẻ nhầm nhà ông là bãi phế liệu – đang ăn cắp đồ đạc của ông. Cuộc tranh cãi nảy lửa sau đó khiến cả hai ngôi nhà đều bị tàn phá. Nhưng vẫn còn hy vọng! Bắt đầu một cuộc hành trình tưởng chừng như bất khả thi để tìm kiếm &quot;Ánh sáng lấp lánh&quot; huyền thoại nhằm ban điều ước, chỉ có một vấn đề: có kẻ khác cũng đang săn lùng nó…</p>', 'Full', 1, 'hoathinh', 'completed', 29, 2026, 'Vietsub', 'FHD', 'Úc', 1, '[{"name":"Nick Offerman","avatar":""},{"name":"Nina Oyama","avatar":""},{"name":"Miranda Otto","avatar":""},{"name":"Amy Sedaris","avatar":""},{"name":"Jordin Sparks","avatar":""},{"name":"Remy Hii","avatar":""},{"name":"Mark Coles Smith","avatar":""},{"name":"Nazeem Hussain","avatar":""},{"name":"Mel Buttle","avatar":""},{"name":"Bessie Holland","avatar":""},{"name":"Christopher James Baker","avatar":""},{"name":"Grant Denyer","avatar":""},{"name":"Andrew Buchanan","avatar":""},{"name":"Ricard Cussó","avatar":""},{"name":"Nadine Bates","avatar":""},{"name":"Lorenzo Shakhovskoy","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["菲什先生住在一艘破败不堪的沉船上。一天，他发现一只精力旺盛的小海龙皮皮把他的家误当成了垃圾场，正在偷他的东西。两人随即爆发激烈争吵，结果把彼此的住所都弄得一片狼藉。 但希望尚存。他们踏上了一场看似不可能完成的冒险，去寻找传说中的 “微光” 来实现愿望。可唯一的麻烦是：另有其人也在寻找它。","O Peixe Pout-Pout","The Pout-Pout Fish"]', 1784690324122);
