INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ca-con-cau-co', 'Cá Con Cau Có', 'The Pout-Pout Fish', 'cá con cau có the pout-pout fish nick offerman nina oyama miranda otto amy sedaris jordin sparks remy hii mark coles smith nazeem hussain mel buttle bessie holland christopher james baker grant denyer andrew buchanan ricard cussó nadine bates lorenzo shakhovskoy 菲什先生住在一艘破败不堪的沉船上。一天，他发现一只精力旺盛的小海龙皮皮把他的家误当成了垃圾场，正在偷他的东西。两人随即爆发激烈争吵，结果把彼此的住所都弄得一片狼藉。 但希望尚存。他们踏上了一场看似不可能完成的冒险，去寻找传说中的 “微光” 来实现愿望。可唯一的麻烦是：另有其人也在寻找它。 o peixe pout-pout the pout-pout fish', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-hoac', 'Mê Hoặc', 'Fascination', 'https://phimimg.com/upload/vod/20260430-1/17f72bb1291939148ca89403f1a09e6c.jpg', 'https://phimimg.com/upload/vod/20260430-1/fcc032d77f4ffb0d2c9531e60f55313c.jpg', '<p>Lin Moqing giả mạo danh tính để thao túng và huấn luyện Lan Hewei như một phần trong kế hoạch tính toán nhằm chống lại gia tộc quyền lực của anh ta. Nhưng khi sự lừa dối, những liên minh thay đổi và những động cơ ngầm va chạm, Lan Hewei chứng tỏ mình mạnh mẽ hơn nhiều so với dự đoán. Điều bắt đầu như một trò chơi chiến lược giành quyền kiểm soát dần dần phát triển thành một mối quan hệ căng thẳng và khó lường, nơi sự cạnh tranh và sức hút hòa quyện vào nhau—và không ai có thể đoán trước được ai sẽ là người chiến thắng.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 12, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ren Yunjie","avatar":""},{"name":"Qi Yandi","avatar":""},{"name":"Gao Tianni","avatar":""},{"name":"Liu Yanqiao","avatar":""},{"name":"Wu Shengqi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Zhao Mi","着迷"]', 1784690324122);
