INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hive', 'Hive', 'Hive', 'https://phimimg.com/upload/vod/20260519-1/6e6fc80579bbd40a1b7f06333f129c3a.jpg', 'https://phimimg.com/upload/vod/20260519-1/5d0937a7978bed801c84483d52907d19.jpg', '<p>Một cô giữ trẻ tuổi teen căng thẳng vì mất đứa trẻ mình trông nom và phải đối mặt với một thế lực đen tối ẩn nấp giữa đám trẻ ở sân chơi. Khi ranh giới giữa thực và ảo trở nên mờ nhạt, cô bé phải tìm cách sống sót trong một thế giới đầy dối trá.</p>', 'Full', 1, 'single', 'completed', 34, 2026, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Xochitl Gomez","avatar":""},{"name":"Aaron Dominguez","avatar":""},{"name":"Jenny le Roux","avatar":""},{"name":"Kelly Chandrapaul","avatar":""},{"name":"Tanya van Graan","avatar":""},{"name":"Thulani Nzonzo","avatar":""},{"name":"Victoria Firsova","avatar":""},{"name":"Zenobia Kloppers","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hive"]', 1784690324122);
