INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pinecone-nguoi-ban-trong-rung', 'Pinecone: Người Bạn Trong Rừng', 'Pinecone', 'https://phimimg.com/upload/vod/20260519-1/bb69243ba8c8b81f1a4bfa1479df959e.jpg', 'https://phimimg.com/upload/vod/20260519-1/942c8aad1376df912e50b2ee1d84926f.jpg', '<p>Phim lấy bối cảnh Ireland thế kỷ 19, kể về “Pinecone” — một sinh vật giống Bigfoot sống cùng gia đình trong rừng. Sau khi con người phát hiện sự tồn tại của họ và bắt đầu săn đuổi vì sợ hãi, Pinecone bị lạc khỏi cha mẹ rồi được một cô bé loài người tên Kit giúp đỡ.</p>', 'Full', 1, 'single', 'completed', 12, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ashley Hays Wright","avatar":""},{"name":"Cadence Wright","avatar":""},{"name":"David Owen Wright","avatar":""},{"name":"Jaina Wright","avatar":""},{"name":"Scout Wright","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Pinecone"]', 1784690324122);
