INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('pinecone-nguoi-ban-trong-rung', 'Pinecone: Người Bạn Trong Rừng', 'Pinecone', 'pinecone: người bạn trong rừng pinecone ashley hays wright cadence wright david owen wright jaina wright scout wright pinecone', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lao-to-luyen-the-manh-nhat-lich-su', 'Lão Tổ Luyện Thể Mạnh Nhất Lịch Sử', 'The Supreme Body Refining Master', 'https://phimimg.com/upload/vod/20260126-1/c2fc222be96f905f019f4dc2923b1812.jpg', 'https://phimimg.com/upload/vod/20260126-1/3e39b509bdf0432f6e1174ceaf648bb6.jpg', '<p>Lão Tổ Luyện Thể Mạnh Nhất Lịch Sử hay còn được biết đến là một áng sử thi mang tên anh chàng Diệp Thương Huyền, người mà sinh ra đã mang thân thể dị thường, khí huyết như hồng hoang, sức mạnh đủ sánh vai thần linh. Tu hành với anh ta chưa từng là gông xiềng, bước lên đỉnh cao Cửu Huyền rồi tiến thẳng Thần Giới chỉ như thuận nước đẩy thuyền mà thôi. Nhưng từ nơi chí cao nhìn xuống, Diệp Thương Huyền thấy rõ một kết cục không thể chấp nhận được, một nhân gian suy tàn, đại lục Cửu Huyền rơi vào bế tắc, sinh linh chìm trong thống khổ. Lão Tổ Diệp Thương Huyền lựa chọn quay đầu, nghịch mệnh mà rơi xuống trần, mang theo ký ức và ý chí vượt khỏi quy tắc. Tái nhập thế gian, anh lão tổ bắt đầu từ con số không, dùng thân luyện thể, lấy quyền cước mở đường. Man Châu bị quét sạch, tà đạo bị chấn áp, sáu thế lực rời rạc dần quy tụ dưới một trật tự mới. Khi Thiên Đạo giáng áp lực, anh lão tổ Diệp Thương Huyền dùng thân xác đối kháng, khi Thần Giới can thiệp, anh cũng thẳng tay phá cục. Đây không phải hành trình cầu đạo, mà là cuộc phản công của phàm nhân trước số phận, nơi một lão tổ lấy thân làm mốc, quyết định lại ranh giới giữa trời và người.</p>', 'Tập 40', 80, 'hoathinh', 'ongoing', 14, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["The Strongest Physical-Training Ancestor","史上最强炼体老祖"]', 1784690324122);
