INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-than-bang-thuong-nhan-nu-than-che-mat', 'Nữ Thần Bàng Thượng Nhãn (Nữ Thần Che Mắt)', 'The Inner Eye', 'https://phimimg.com/upload/vod/20260131-1/747d2683508962605512aee2120a4437.jpg', 'https://phimimg.com/upload/vod/20260131-1/c297a14096ea75f48cf901f8d607767e.jpg', '<p>“Nữ luật sư bất bại” Đường Doanh Doanh (Tân Chỉ Lôi thủ vai) cùng cấp trên trực tiếp Khang Tuấn (Lâm Vũ Thân thủ vai) liên tục đối đầu trong hàng loạt vụ án phản ánh muôn mặt đời sống. Qua những va chạm ấy, họ từng bước làm sáng tỏ bài toán mang đậm màu sắc Trung Quốc về “tình người và pháp lý”. cuối cùng thu hoạch được câu chuyện động lòng người về sự trưởng thành của bản thân. Bộ phim khai thác nhiều chủ đề được xã hội quan tâm như tình yêu và hôn nhân, sự nghiệp và gia đình, pháp lý và đạo đức…, nỗ lực khắc họa sâu sắc cuộc sống và những lựa chọn của các nhóm người khác nhau, qua đó khích lệ khán giả giữ vững dũng khí và hy vọng khi đối mặt với những thử thách của đời sống.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'ongoing', 22, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tân Chí Lôi","avatar":""},{"name":"Lâm Vũ Thân","avatar":""},{"name":"Trương Nghệ Thượng","avatar":""},{"name":"Trịnh Hi Di","avatar":""},{"name":"Vương Tử Duệ","avatar":""},{"name":"Đái Vân Phi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["The Inner Eye","Nv Shen Meng Shang Yan","女神蒙上眼"]', 1784690324122);
