INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nu-than-bang-thuong-nhan-nu-than-che-mat', 'Nữ Thần Bàng Thượng Nhãn (Nữ Thần Che Mắt)', 'The Inner Eye', 'nữ thần bàng thượng nhãn (nữ thần che mắt) the inner eye tân chí lôi lâm vũ thân trương nghệ thượng trịnh hi di vương tử duệ đái vân phi the inner eye nv shen meng shang yan 女神蒙上眼', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuc-tham', 'Vực Thẳm', 'Crimes Of The Abyss', 'https://phimimg.com/upload/vod/20260518-1/3e272c9d1d0cccbc58c6327fe030af56.jpg', 'https://phimimg.com/upload/vod/20260518-1/94a80134dbd43e0d3a6d17d1c564043f.jpg', '<p>Tại thành phố Đồng Giang, chỉ trong vòng vỏn vẹn ba tháng đã liên tiếp xảy ra ba vụ án mạng đặc biệt nghiêm trọng: Đầu tiên, một khách du lịch phát hiện một cánh tay đứt lìa trôi dạt trên sông ở vùng ngoại ô Đại Hắc Sơn; tiếp sau đó, cậu sinh viên đại học Lộ Dương tử vong không rõ nguyên nhân ngay tại nhà riêng; và ngay sau đó, diệp Khải Minh – một doanh nhân trẻ tiêu biểu của thành phố – cũng không qua khỏi sau một vụ tai nạn giao thông nghiêm trọng.&nbsp; Nữ cảnh sát hình sự Tưởng Mai thuộc Cục hình sự thành phố cùng Thẩm Phong – người vừa được điều động từ Sở Công an tỉnh về – nhận mệnh lệnh phối hợp phá giải chuỗi vụ án này. Khi cuộc điều tra đầy gian truân từng bước tiến triển, những hành vi sát hại tàn nhẫn, những ân oán tình thù giấu kín cùng mối quan hệ chằng chịt, phức tạp phía sau dần dần lộ diện. Nguyên nhân sâu xa của những vụ án đẫm máu này đã phản chiếu mối quan hệ nhân quả không thể tách rời giữa sự cám dỗ của dục vọng vật chất và những tâm hồn bị biến dạng, tha hóa.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 16, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Thừa","avatar":""},{"name":"Chu Mỹ Cát","avatar":""},{"name":"Mạnh Tử Diệp","avatar":""},{"name":"Ngụy Tử Thiên","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["深渊"]', 1784690324122);
