INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-o-nhan-gian-pha-quy-su', 'Tôi Ở Nhân Gian Phá Quỷ Sự', 'Folk Exorcist', 'https://phimimg.com/upload/vod/20260518-1/63f6f9fe704587ec9e702361d01946c7.jpg', 'https://phimimg.com/upload/vod/20260518-1/5a555771f9abc3b4db13d3ccbaf4e255.jpg', '<p>Sau khi nhà Thanh sụp đổ, Vương Thập Thất – truyền nhân của phái Âm Quế – kế thừa chức vị Sứ giả dẫn đường Phong Đô, mang theo quỷ đầu đao đi diệt trừ yêu ma quỷ quái. Trên đường đi qua trấn Đào Hoa, anh bị cuốn vào hàng loạt vụ án quỷ dị liên hoàn như anh nhi oán linh làm loạn, tà chú Lỗ Ban thuật, hay quỷ kỹ đòi mạng. Tại đây, anh kết bạn cùng Tô Uyển Dung – thiên kim tiểu thư của trưởng trấn và Ngân Liên – cháu gái của một bậc bán tiên. Nhóm người đã cùng nhau vạch trần tội ác của cha con nhà họ Tông, đồng thời hợp lực chống lại âm mưu đen tối của phái Cửu Cúc Nhất Phái đến từ Nhật Bản, quyết tâm bảo vệ cổ vật của thị trấn và sự bình yên cho bách tính. Trên hành trình phá giải những hiện tượng quỷ dị ấy, họ đã viết nên những giai thoại vừa dở khóc dở cười nhưng cũng không kém phần nhiệt huyết.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 12, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Nghiệp Minh","avatar":""},{"name":"Hà Thích","avatar":""},{"name":"Thôi Trường Tồn","avatar":""},{"name":"Thượng Na","avatar":""},{"name":"Dĩ Mạt","avatar":""},{"name":"Mưu Phụng Bân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wo Zai Ming Jian Po Gui Shi","Folk Exorcist","我在民间破诡事"]', 1784690324122);
