INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('toi-o-nhan-gian-pha-quy-su', 'Tôi Ở Nhân Gian Phá Quỷ Sự', 'Folk Exorcist', 'tôi ở nhân gian phá quỷ sự folk exorcist dương nghiệp minh hà thích thôi trường tồn thượng na dĩ mạt mưu phụng bân wo zai ming jian po gui shi folk exorcist 我在民间破诡事', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-nhu-tuyet-tren-dinh-thien-son', 'Tình Yêu Như Tuyết Trên Đỉnh Thiên Sơn', 'Millennium Love', 'https://phimimg.com/upload/vod/20260518-1/2bb8e1c1721f5e507807a711465fbff4.jpg', 'https://phimimg.com/upload/vod/20260518-1/65a0384880d51107cfae2ce3a94b6b80.jpg', '<p>Do không được mời tham dự tiệc Bàn Đào, thủy quái Dao Trì đã nổi giận dâng nước lũ làm loạn. Vương Mẫu Nương Nương bèn ném chiếc trâm bích ngọc hóa thành định hải thần châm để bình định sóng dữ, đồng thời giao cho tiên nữ Ngọc Dao canh giữ. Thần quan thiên đình Lục Tư Niên nhận mệnh đi trấn áp hậu duệ của thủy quái là Huyền Thanh, từ đó quen biết và nảy sinh tình cảm với Ngọc Dao.&nbsp; Khi Huyền Thanh đột ngột tăng tiến pháp lực và làm Ngọc Dao trọng thương, Lục Tư Niên đã liều mình hái trộm tuyết liên Thiên Sơn để cứu nàng. Hành vi này xúc phạm thiên điều, khiến anh bị phạt đày xuống trần gian, trải qua 99 kiếp luân hồi. Ở kiếp thứ 99, Lục Tư Niên trở thành một sinh viên đang ôn thi cao học. Huyền Thanh đã dụ anh đến Thiên Trì nhằm hấp thụ nguyên linh ái thần của anh và Ngọc Dao để nhổ định hải thần châm. Trong tình thế ngàn cân treo sợi tóc, Lục Tư Niên khôi phục ký ức, đỡ thay Ngọc Dao một đòn chí mạng. Lúc này, Huyền Thanh cũng nhận ra sự thật cay đắng rằng mình chỉ bị tổ tiên là Huyền Hành lợi dụng trong một mối tình sai trái, bèn tự sát để chuộc tội. Ngọc Dao cõng Lục Tư Niên vượt thiên thang cầu xin Vương Mẫu Nương Nương cứu mạng, thượng tiên nguyên linh ái thần đã mở ra cánh cửa tái sinh cho họ. Cả hai cuối cùng gặp lại nhau tại Thiên Trì thuộc Thiên Sơn, viết nên cái kết viên mãn cho mối tình ngàn năm.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 20, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lâm Na","avatar":""},{"name":"Tinh Trạch","avatar":""},{"name":"Tổ Các Nhĩ","avatar":""},{"name":"Lưu Tuệ","avatar":""},{"name":"Vương Tử Tuấn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["爱如天山不化雪"]', 1784690324122);
