INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tinh-yeu-nhu-tuyet-tren-dinh-thien-son', 'Tình Yêu Như Tuyết Trên Đỉnh Thiên Sơn', 'Millennium Love', 'tình yêu như tuyết trên đỉnh thiên sơn millennium love lâm na tinh trạch tổ các nhĩ lưu tuệ vương tử tuấn 爱如天山不化雪', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-he-cua-thuong-bao', 'Mùa Hè Của Thường Bảo', 'Changzhou Never Quits', 'https://phimimg.com/upload/vod/20260518-1/5c3381fbeebd585b43e635f5c991a2bd.jpg', 'https://phimimg.com/upload/vod/20260518-1/1f06d3a979e6b99ee3176e5020efb36a.jpg', '<p>Bộ phim là câu chuyện truyền cảm hứng và ấm áp, xoay quanh quá trình trưởng thành và nỗ lực vươn lên không ngừng nghỉ của một đội bóng đá nghiệp dư tại Thường Châu. Đội bóng gồm những người dân thành thị bình thường, dù liên tiếp thất bại trên sân cỏ nhưng chưa bao giờ từ bỏ đam mê. Từ khởi đầu thảm hại trước mùa giải, nhờ vào sự dẫn dắt của huấn luyện viên, sự thấu hiểu từ gia đình và sự ủng hộ của cả thành phố, các thành viên đã dần gắn kết thành một khối thống nhất. Cuối cùng, họ đã giành được sự tôn trọng và trở nên trưởng thành hơn.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 12, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Nghiệp Minh","avatar":""},{"name":"Hoàng Trường Phong","avatar":""},{"name":"Thường Lỗ Phong","avatar":""},{"name":"Lữ Mẫn","avatar":""},{"name":"Khúc Song Khanh","avatar":""},{"name":"Khâu Gia Kỳ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["常宝的夏天"]', 1784690324122);
