INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-chang-theo-long', 'Mặt Chẳng Theo Lòng', 'The Double Game', 'https://phimimg.com/upload/vod/20260506-1/ebe9f7b5d88a760fb5a911ad046ae5a2.jpg', 'https://phimimg.com/upload/vod/20260506-1/a0327f82d018fee124d0ac2acf0db137.jpg', '<p>Để thu thập chứng cứ, Ôn Nhan đành phải trà trộn vào hào môn, trở thành dâu thứ trong gia tộc; còn Lục Đình Kiêu vì báo thù cho mẹ nên bày mưu đoạt quyền. Trớ trêu thay, cô lại chính là &quot;kẻ giả mạo&quot; từng có một đêm dây dưa với anh. Ban ngày, cô ra tay dạy dỗ người chồng nhu nhược; anh thì âm thầm giăng bẫy. Đêm đến, cả hai đều mang toan tính riêng, giằng co đến cực hạn, từ chỗ đề phòng lẫn nhau đến liên thủ lật đổ cả gia tộc. Mối tình cấm kỵ cũng theo những âm mưu toan tính đó mà dần trở nên mất kiểm soát.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 13, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đặng Khải","avatar":""},{"name":"Tôn Nghệ Nhiên","avatar":""},{"name":"Trương Huyên","avatar":""},{"name":"Vương Trác Dịch","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Double Game","颜不由心"]', 1784690324122);
