INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-thay-bang-ca-the-gioi', 'Yêu Thầy Bằng Cả Thế Giới', 'Love You Teacher', 'https://phimimg.com/upload/vod/20260316-1/d275b1c9a7a0b45106291ec86564777c.jpg', 'https://phimimg.com/upload/vod/20260316-1/2170bcd5e900bdde3c3d77dae92e94c7.jpg', '<p>Giáo viên tiểu học Pobmek không thích trẻ con, nhưng bạn trai anh, giáo viên Solar, lại rất thích, và anh yêu Solar đủ để bù đắp cho điều đó. Tuy nhiên, khi Solar gặp tai nạn, anh bị tổn thương não, đôi khi trở về trạng thái tinh thần của một đứa trẻ bảy tuổi. Sau khi anh đưa Nong Solar về nhà, có những ngày Pobmek không được nghỉ ngơi chút nào khỏi lũ trẻ.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 20, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Tanapon Sukumpantanasan","avatar":""},{"name":"Pongsapak Udomphoch","avatar":""},{"name":"Samantha Melanie Coates","avatar":""},{"name":"Kay Lertsittichai","avatar":""},{"name":"Ploynira Hiruntaveesin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ruk Kru Tao Lok Loey","รักครูเท่าโลกเลย"]', 1784690324122);
