INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phu-nhan-dai-quan-the-ky-21', 'Phu Nhân Đại Quân Thế Kỷ 21', 'Perfect Crown', 'phu nhân đại quân thế kỷ 21 perfect crown iu byeon woo-seok steve sanghyun noh gong seung-yeon yoo su-bin lee yeon lee jae-won chae seo-an cho seung-yeon park ji-ye sung joon lee si-hoon choi ji-su choi cheol-gyoo 윤설아 진세린 jeong ji-an kim jung-woon jo jae-yun park jun-myun kim a esposa do grande príncipe do século 21 21segi daegun buin 21st century grand prince''s wife wife of a 21st century prince 21세기 대군부인', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('only-friends-dream-on', 'Only Friends: Dream On', 'Only Friends: Dream On', 'https://phimimg.com/upload/vod/20260303-1/f8933787adf6dacc01c4a5ffbb7cd4cd.jpg', 'https://phimimg.com/upload/vod/20260303-1/b8a22fc1dcc74c0adb2fcff8c5b7873f.jpg', '<p>Câu chuyện lấy bối cảnh đại học nghệ thuật, nơi “vở kịch của khoa” là cuộc chiến danh dự khiến ai cũng muốn thắng. Năm nay, sinh viên năm 4 Jack tiếp tục giữ vai trò đạo diễn và quyết định dựng Romeo &amp; Romeo, phiên bản chuyển thể từ Romeo &amp; Juliet theo góc nhìn tình yêu giữa hai chàng trai và hứa hẹn một “happy ending”. Nhưng ngay khi việc phân vai bắt đầu, mọi thứ nhanh chóng biến thành một mạng lưới cạnh tranh và cảm xúc chồng chéo. Tâm điểm là cuộc giằng co giữa diễn viên kỳ cựu đồng thời là người yêu cũ của Jack là Dean và cậu bạn cùng khoa đã thầm thích Jack suốt nhiều năm là Raffy. Dean tin chắc Jack sẽ lại chọn mình như mọi lần trước, còn Raffy thì vừa khát khao vai “Romeo”, vừa khao khát cả thứ mà Dean từng có: vị trí trong lòng Jack. Khi tình cảm cũ chưa kịp nguội, cạnh tranh trên sân khấu lại càng đẩy những ranh giới riêng tư trở nên mong manh. Sự rối rắm tiếp tục tăng cấp khi Rome bước vào dự án với vai trò âm thanh/sound cho vở diễn. Sự xuất hiện của Rome vô tình trở thành “biến số” khiến kế hoạch của mỗi người lung lay, kéo theo nghi ngờ, ghen tuông và những màn đấu trí ngầm ngay trong nhóm làm kịch. Song song đó là một tuyến tình cảm khác: Tua là người luôn tìm cách ở gần người mình thích đưa Arnold (nam thần khoa múa, chưa có kinh nghiệm diễn kịch) vào dự án để nhận vai nam chính, từ đó mở ra một mối quan hệ vừa ngọt vừa dễ tổn thương. Giữa một quá trình dựng kịch hỗn loạn, nơi ai cũng phải “diễn” cả trên sân khấu lẫn ngoài đời, câu chuyện đặt cược bằng tình yêu, tình bạn và những bí mật không ai muốn bị lộ. Và đúng như tinh thần của series: trong vở kịch này, không ai là vai phụ, mỗi người đều là nhân vật chính với lựa chọn, tham vọng và nỗi sợ của riêng mình.&nbsp;</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 22, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Sahaphap Wongratch","avatar":""},{"name":"Pirapat Watthanasetsiri","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324122);
