INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-dich-co-loi', 'Tình Địch Có Lợi', 'Enemies With Benefits', 'https://phimimg.com/upload/vod/20260512-1/88f5d663a2f75fdffdbe76425234407b.jpg', 'https://phimimg.com/upload/vod/20260512-1/85e124c4895b56bad4a2a5d7bcecd386.jpg', '<p>Lal, Trưởng phòng Kinh doanh, luôn quyết tâm phải giành chiến thắng trước Wine – Trưởng phòng Kế toán. Wine vốn là thái cực hoàn toàn trái ngược với Lal và nổi tiếng là người không biết khoan nhượng. Tuy nhiên, sau một đêm quá chén, mối quan hệ giữa họ bất ngờ chuyển biến thành &quot;bạn giường&quot; (friends with benefits). Cả hai tìm mọi cách để giữ kín bí mật này bằng cách giả vờ làm kẻ thù của nhau tại công ty để không một ai nghi ngờ. Thế nhưng, trong quá trình diễn kịch, sự gần gũi mới mẻ này đã dần biến thành tình yêu mà chính họ cũng không hề hay biết.</p>', 'Tập 2', 10, 'series', 'ongoing', 19, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Ployshompoo Supasap","avatar":""},{"name":"Prariyapit Yu","avatar":""},{"name":"Ploynira Hiruntaveesin","avatar":""},{"name":"Rutricha Phapakithi","avatar":""},{"name":"Juthapich Indrajundra","avatar":""},{"name":"Phatchatorn Thanawat","avatar":""},{"name":"Chayakorn Jutamas","avatar":""},{"name":"Kittipat Chalaragse","avatar":""},{"name":"Niti Chaichitathorn","avatar":""},{"name":"Leo Saussay","avatar":""},{"name":"Rattanawadee Wongthong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["ลัลล์ไม่ชอบไวน์"]', 1784690324122);
