INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-an-tien-gia', 'Đại Án Tiền Giả', 'The Great Money Robbery', 'https://phimimg.com/upload/vod/20260514-1/7b1bcdb67e915d72d217e2141d96c064.jpg', 'https://phimimg.com/upload/vod/20260514-1/bf0ec8831e6e82df721220392783863a.jpg', '<p>Năm 1999, cựu vô địch tán đả Trịnh Minh tham gia vào một đường dây tiền giả trong lúc cố gắng cứu cô con gái đang bệnh nặng. Đội trưởng cảnh sát Tạ Gia Đồng bắt đầu điều tra nguồn gốc của số tiền giả, mở ra cuộc đấu trí mèo vờn chuột đầy phức tạp giữa anh và Trịnh Minh. Ban đầu, Trịnh Minh chỉ dùng tiền giả để trả nợ, nhưng dần dần bị cuốn sâu vào thế giới tội phạm. Anh bị cả cảnh sát lẫn băng đảng truy đuổi. Có thời điểm, Trịnh Minh cố hợp tác với cảnh sát với vai trò chỉ điểm viên. Sau khi kế hoạch bỏ trốn thất bại, ông trùm đường dây tiền giả Kiều Đại Tường bắt cóc con gái của Trịnh Minh để uy hiếp anh. Cuối cùng, trong buổi tế tổ của làng họ Kiều, Trịnh Minh và Tạ Gia Đồng hợp sức giải cứu cô bé và thành công bắt giữ Kiều Đại Tường, qua đó triệt phá toàn bộ đường dây tiền giả.</p>', 'Full', 1, 'single', 'completed', 8, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wu Yue","avatar":""},{"name":"Bao Bei''er","avatar":""},{"name":"Tan Kai","avatar":""},{"name":"Rui Xiu","avatar":""},{"name":"Daniella Wang","avatar":""},{"name":"Liang Songqing","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["The Counterfeit","偽鈔重案","伪钞重案"]', 1784690324122);
