INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giua-cha-va-con-trai', 'Giữa Cha Và Con Trai', 'Between Father and Son', 'https://phimimg.com/upload/vod/20260513-1/0df9910a1873314e920a44c909ed4a10.jpg', 'https://phimimg.com/upload/vod/20260513-1/929da6295404148a9be51b73284d0152.jpg', '<p>Khi luật sư thành đạt nọ đến thăm gia đình vị hôn phu, cô dần thân mật một cách nguy hiểm với con trai nhiều bất ổn của anh, giữa những căng thẳng âm ỉ và những bí mật đáng ngại.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 27, 2026, 'Vietsub', 'FHD', 'Quốc Gia Khác', 0, '[{"name":"Pamela Almanza","avatar":""},{"name":"Erick Elías","avatar":""},{"name":"Graco Sendel","avatar":""},{"name":"Natalia Plascencia","avatar":""},{"name":"Ivanna Castro","avatar":""},{"name":"Carmen Delgado","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Entre padre e hijo"]', 1784690324122);
