INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('giua-cha-va-con-trai', 'Giữa Cha Và Con Trai', 'Between Father and Son', 'giữa cha và con trai between father and son pamela almanza erick elías graco sendel natalia plascencia ivanna castro carmen delgado entre padre e hijo', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-ac-ngo-ngan-toi-pham-iq-thap', 'Tội Ác Ngớ Ngẩn (Tội Phạm IQ Thấp)', 'Born With Luck', 'https://phimimg.com/upload/vod/20260505-1/8e30f987ddb41c6988ae56740220bb03.jpg', 'https://phimimg.com/upload/vod/20260505-1/f765c66c3564338b47645f6348d1fbeb.jpg', '<p>Cảnh sát Trương Nhất Ngang đã rời xa công việc điều tra hình sự trực tiếp nhiều năm, bỗng được cử đến Tam Giang Khẩu để điều tra một vụ án do lá đơn tố cáo nặc danh gửi đến Công an tỉnh. Không lâu sau khi đến nơi, Trương Nhất Ngang chứng kiến vụ án Trưởng đội Cảnh sát Hình sự bị sát hại. Trong lúc tự thanh minh nghi ngờ, anh tình cờ bắt được hung thủ một loạt vụ giết người, nhanh chóng gây dựng thanh thế. Trương Nhất Ngang tập trung điều tra vào nhóm doanh nhân giàu có Chu Vinh, nhưng lũ tội phạm ngốc nghếch cứ liên tục xuất hiện. Những mâu thuẫn, tranh giành nội bộ của chúng lại như hiệu ứng cánh bướm, vô tình giúp đội cảnh sát do Trương Nhất Ngang dẫn đầu lập được nhiều chiến công. &quot;Duyên phận&quot; đã đưa Trương Nhất Ngang và đám tội phạm ngốc nghếch cùng hội tụ một chỗ. Bằng trí tuệ và lòng dũng cảm, anh đã cười đến phút cuối, đồng thời làm rõ nguyên nhân cái chết của đồng đội, cuối cùng đưa hung thủ thực sự vào vòng lao lý.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 11, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Kiêu","avatar":""},{"name":"Điền Hi Vi","avatar":""},{"name":"Vương Truyền Quân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["擒贼记","Low IQ Crime","Born with Luck","低智商犯罪"]', 1784690324122);
