INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-luon-la-em', 'Vẫn Luôn Là Em', 'You, Always', 'https://phimimg.com/upload/vod/20260513-1/2e5c0f6def443f916b33f772b4ba2de5.jpg', 'https://phimimg.com/upload/vod/20260513-1/9fe0951f1892fe1ca5466b94496330de.jpg', '<p>Ethan là một người bạn thân vô cùng tận tâm, nhưng anh sớm nhận ra mình đã yêu bác sĩ Jen Bell từ bấy lâu nay. Tuy nhiên, thế giới của Jen hoàn toàn bị đảo lộn trước sự xuất hiện của Patrick – một nhà văn đầy lôi cuốn. Đứng trước sự xuất hiện của &quot;kẻ thứ ba&quot; đầy sức hút này, Ethan phải đối mặt với nỗi lo sợ đánh mất người mình yêu, trong khi Jen bị giằng xé giữa tình cảm chân thành của người bạn thân và sự quyến rũ mới mẻ của chàng nhà văn hào hoa.</p>', 'Full', 1, 'single', 'completed', 27, 2026, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"Adrian Grenier","avatar":""},{"name":"Jessica De Gouw","avatar":""},{"name":"Desmond Chiam","avatar":""},{"name":"Yasmin Kassim","avatar":""},{"name":"Spencer McLaren","avatar":""},{"name":"Adyn Kingi","avatar":""},{"name":"Aria Burton","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["You, Always"]', 1784690324122);
