INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-trong-thanh-pho', 'Tình Yêu Trong Thành Phố', 'Do Deewane Seher Mein', 'https://phimimg.com/upload/vod/20260513-1/097ec689d1f1bb2cb88076a1c619ee4f.jpg', 'https://phimimg.com/upload/vod/20260513-1/e4faccc84002d0561f2f42ab169b2e0d.jpg', '<p>Hai người trẻ thuộc thế hệ Millennials tại Mumbai, vốn vụng về trong các mối quan hệ xã hội, đã tìm thấy tình yêu trong khi đang chật vật với việc học cách chấp nhận bản thân. Khi cùng nhau chiến đấu chống lại những nỗi bất an và áp lực từ xã hội, hành trình của họ trải dài từ sự hỗn loạn của phố thị đến sự tĩnh lặng, yên bình nơi vùng núi cao. Tại đó, họ không chỉ tìm thấy nhau mà còn tìm thấy sự bình yên trong chính tâm hồn mình.</p>', 'Full', 1, 'single', 'completed', 27, 2026, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Siddhant Chaturvedi","avatar":""},{"name":"Mrunal Thakur","avatar":""},{"name":"Ila Arun","avatar":""},{"name":"Joy Sengupta","avatar":""},{"name":"Ayesha Raza Mishra","avatar":""},{"name":"Viraj Ghelani","avatar":""},{"name":"Sandeepa Dhar","avatar":""},{"name":"Deepraj Rana","avatar":""},{"name":"Mona Ambegaonkar","avatar":""},{"name":"Naveen Kaushik","avatar":""},{"name":"Achint Kaur","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["दो दीवाने शहर में"]', 1784690324122);
