INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tinh-yeu-trong-thanh-pho', 'Tình Yêu Trong Thành Phố', 'Do Deewane Seher Mein', 'tình yêu trong thành phố do deewane seher mein siddhant chaturvedi mrunal thakur ila arun joy sengupta ayesha raza mishra viraj ghelani sandeepa dhar deepraj rana mona ambegaonkar naveen kaushik achint kaur दो दीवाने शहर में', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cay-sinh-menh', 'Cây Sinh Mệnh', 'Born To Be Alive', 'https://phimimg.com/upload/vod/20260202-1/4e769d07eabcd16b000c266cab10d118.jpg', 'https://phimimg.com/upload/vod/20260202-1/180bbf895ad2ece7fff268339392c5ed.jpg', '<p>Vào những năm 1990 của thế kỷ trước, huyện Mã Trị trên cao nguyên Thanh Hải phụ thuộc nặng nề vào nông nghiệp và chăn nuôi, từng rơi vào cảnh nghèo đói kéo dài. Khu vực Bác La Mộc La lân cận là vùng đất không người, giàu tài nguyên khoáng sản và động vật hoang dã, khiến các nhóm săn trộm và khai thác trái phép vì lợi nhuận khổng lồ mà tàn sát, khai thác bừa bãi. Phó huyện trưởng huyện Mã Trị là Đa Kiệt, với sự ủng hộ của huyện trưởng Lâm Bồi Sinh, đã thành lập đội tuần núi. Ban đầu, mục đích của đội là thăm dò khoáng sản trong vùng đất không người nhằm xóa đói giảm nghèo. Nhưng sau khi tận mắt chứng kiến cảnh linh dương Tây Tạng bị thảm sát, Đa Kiệt đã dốc toàn bộ tâm huyết cho sự nghiệp bảo vệ môi trường. Trong đội tuần núi, nữ cảnh sát trẻ Bạch Cúc trở thành biến số định mệnh của Đa Kiệt. Cô là trẻ mồ côi được bác sĩ chi viện Tây Tạng Trương Cần Cần nhận nuôi, cũng là cô con gái út gan dạ, dám xông pha của nhà họ Bạch.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 13, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Tử","avatar":""},{"name":"Hồ Ca","avatar":""},{"name":"Lý Quang Khiết","avatar":""},{"name":"Trương Triết Hoa","avatar":""},{"name":"Mai Đình","avatar":""},{"name":"Viên Hồng","avatar":""},{"name":"Dương Thác","avatar":""},{"name":"Châu Du","avatar":""},{"name":"Tằng Bồi","avatar":""},{"name":"Tống Tỉnh Nham","avatar":""},{"name":"Kim Ba","avatar":""},{"name":"Phùng Binh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sheng ming shu","Born To Be Alive","The Tree of Life","Life Tree","生命树"]', 1784690324122);
