INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-nguoi-deu-rat-on-phan-2', 'Mọi người đều rất ổn (Phần 2)', 'Everyone Is Doing Great (Season 2)', 'https://phimimg.com/upload/vod/20260512-1/3523f92634d101b350fbe164db69d2bd.jpg', 'https://phimimg.com/upload/vod/20260512-1/0520e377b5d55ffed6cd9ffbdfe169fb.jpg', '<p>Jeremy ngày càng xuống tinh thần sau khi ly thân với Andrea. Anh cố cai nghiện, chữa lành bản thân nhưng liên tục tái phạm vì áp lực cuộc sống và cảm giác thất bại. Jeremy vẫn yêu Andrea, nhưng mối quan hệ của họ gần như không thể cứu vãn vì sự thiếu tin tưởng và những sai lầm cũ.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"James Lafferty","avatar":""},{"name":"Stephen Colletti","avatar":""},{"name":"Alexandra Park","avatar":""},{"name":"Cariba Heine","avatar":""},{"name":"Karissa Lee Staples","avatar":""},{"name":"Tom Fugedi","avatar":""},{"name":"Bob Turton","avatar":""},{"name":"Matthew Atkinson","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["우리 진짜 잘 지내","Everyone Is Doing Great"]', 1784690324122);
