INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ten-cuop-mot-cau-chuyen-tinh-yeu', 'Tên cướp: Một câu chuyện tình yêu', 'Dacoit: A Love Story', 'https://phimimg.com/upload/vod/20260511-1/365cd330448bc542ea649e371bf01a4b.jpg', 'https://phimimg.com/upload/vod/20260511-1/99ba33dea87d85a9afb726a686f1eeee.jpg', '<p>Bị người yêu phản bội, một người đàn ông bị kết tội oan. Sau khi được tự do, anh ta truy tìm cô ta để trả thù, và câu chuyện của cả hai đan xen với một loạt vụ cướp.</p>', 'Full', 1, 'single', 'completed', 24, 2026, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Adivi Sesh","avatar":""},{"name":"Mrunal Thakur","avatar":""},{"name":"Anurag Kashyap","avatar":""},{"name":"Prakash Raj","avatar":""},{"name":"Sunil Varma","avatar":""},{"name":"Zayn Marie Khan","avatar":""},{"name":"Kamakshi Bhaskarla","avatar":""},{"name":"Atul Kulkarni","avatar":""},{"name":"Vaibhav Tatwawadi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Dacoit - A Love Story","Dacoit - Ek Prem Katha","డెకాయిట్"]', 1784690324122);
