INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-ngau-thien-thanh', 'Giai Ngẫu Thiên Thành', 'Fate Chooses You', 'https://phimimg.com/upload/vod/20260425-1/b9f63dabb69f77176b12ccf23fbf699d.jpg', 'https://phimimg.com/upload/vod/20260425-1/e4618fe07df335795ba86b3241b1d57c.jpg', '<p>Lục Thiên Kiều, người thuộc tộc Chiến Quỷ phải phá giải lời nguyền và chuyển sinh thành người để giữ gìn huyết mạch. Anh giả thân phận làm quan và kết hôn với Tân Mi, một nữ tu mang mệnh khắc phu. Thế nhưng khi bí mật và hiểm nguy dần lộ diện, cả hai lại bị cuốn vào một mối duyên định mệnh, nhiều lần gặp lại và dần thay đổi mối quan hệ giữa họ.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 33, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Nhậm Gia Luân","avatar":""},{"name":"Vương Hạc Nhuận","avatar":""},{"name":"Trương Khải Oánh","avatar":""},{"name":"Vương Dĩ Luân","avatar":""},{"name":"Hoàng Nghệ","avatar":""},{"name":"Phó Vĩ Luân","avatar":""},{"name":"Tôn Trạch Nguyên","avatar":""},{"name":"Trương Y Cách","avatar":""},{"name":"Đinh Tiếu Doanh","avatar":""},{"name":"Tiêu Thuấn Nghiêu","avatar":""},{"name":"Lưu Học Nghĩa","avatar":""},{"name":"Trịnh Nghiệp Thành","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Perfect Match","Fate Chooses You","佳偶天成"]', 1784690324122);
