INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-yeu-cu-te-nhat-phan-2', 'Người yêu cũ tệ nhất (Phần 2)', 'Worst Ex Ever (Season 2)', 'https://phimimg.com/upload/vod/20260511-1/e34c5c44f6270b4d00d33a674fe2ab1e.jpg', 'https://phimimg.com/upload/vod/20260511-1/76279e6206cf43661b2df507be5e87e3.jpg', '<p>Từ những vụ phản bội lạnh gáy đến âm mưu giết người, loạt phim tài liệu về tội ác có thật này mổ xẻ mặt tối của tình yêu qua lời khai của nhân chứng.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 13, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Farlige ekser","Кошмарні колишні","Worst Ex Ever"]', 1784690324122);
