INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-mot-la-thu-gui-tu-thanh-pho-cang', 'Có Một Lá Thư Gửi Từ Thành Phố Cảng', 'Echoes Of Gang City', 'https://phimimg.com/upload/vod/20260424-1/42d8ab09e1c1a74eb88290ce759cb335.jpg', 'https://phimimg.com/upload/vod/20260424-1/f67fcad1c1757fb69db83171f8d50acc.jpg', '<p>Tập đoàn họ Hứa ở Cảng Thành liên tiếp gặp sóng gió, đứng trên bờ vực sụp đổ. Hứa Vãn Tín đành cầu cứu gia đình có hôn ước nhưng lại bị thừa nước đục thả câu. Đúng lúc này, thiên tài công nghệ Thẩm Cố mang theo số cổ phần lớn bất ngờ trở về và ký kết khế ước hôn nhân với cô. Cả hai hợp lực chống lại sự thâu tóm của tư bản ngoại, đập tan âm mưu của cha con họ Thẩm, rồi dần nảy sinh chân tình khi kề vai sát cánh bảo vệ gia nghiệp. Thế nhưng, trong mắt ông nội Hứa, mối nhân duyên giữa Vãn Tín và Thẩm Cố thực chất đã bắt nguồn từ một đôi vợ chồng huyền thoại thời Dân quốc...</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 16, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hồ Liên Hinh","avatar":""},{"name":"Triệu Hoa Vi","avatar":""},{"name":"Tống Mộc Tâm","avatar":""},{"name":"Trương Đằng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["夜港寄归人","You Gang Hui Xin","有港回信"]', 1784690324122);
