INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phim-super-mario-thien-ha', 'Phim Super Mario Thiên Hà', 'The Super Mario Galaxy Movie', 'https://phimimg.com/upload/vod/20260508-1/b9482988285cb67c118bc092404d804a.jpg', 'https://phimimg.com/upload/vod/20260508-1/6bf821d68045c5310a192c5244992ac0.jpg', '<p>Nối tiếp thành công của phần phim đầu tiên, Mario và Luigi dấn thân vào một cuộc phiêu lưu ngoài sức tưởng tượng khi họ bị cuốn vào không gian sâu thẳm. Lần này, họ gặp gỡ Rosalina, người bảo vệ các vì sao và là &quot;mẹ&quot; của những sinh vật Luma đáng yêu. Cả nhóm phải hợp sức để ngăn chặn âm mưu thôn tính toàn bộ vũ trụ của Bowser, khi hắn đang thu thập các Grand Stars để xây dựng một đế chế thiên hà hùng mạnh. Phim hứa hẹn mang đến những màn rượt đuổi nghẹt thở giữa các hành tinh với trọng lực siêu thực và hình ảnh rực rỡ.</p>', 'Full', 1, 'hoathinh', 'completed', 23, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 1, '[{"name":"Chris Pratt","avatar":""},{"name":"Anya Taylor-Joy","avatar":""},{"name":"Charlie Day","avatar":""},{"name":"Jack Black","avatar":""},{"name":"Keegan-Michael Key","avatar":""},{"name":"Benny Safdie","avatar":""},{"name":"Donald Glover","avatar":""},{"name":"Glen Powell","avatar":""},{"name":"Luis Guzmán","avatar":""},{"name":"Issa Rae","avatar":""},{"name":"Kevin Michael Richardson","avatar":""},{"name":"Brie Larson","avatar":""},{"name":"Juliet Jelenic","avatar":""},{"name":"Ed Skudder","avatar":""},{"name":"Roxana Ortega","avatar":""},{"name":"Virginia Dare Jelenic","avatar":""},{"name":"Eric Bauza","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d