INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vaa-vaathiyaar', 'Vaa Vaathiyaar', 'Vaa Vaathiyaar', 'https://phimimg.com/upload/vod/20260511-1/e0b94881d5d0f80f40605835e61d8084.jpg', 'https://phimimg.com/upload/vod/20260511-1/30b9af23245632a6befdf04f560eb7a7.jpg', '<p>Sau khi được nuôi dưỡng như là kiếp sau của một diễn viên nổi tiếng, một người đàn ông nhận thấy mình phải đối mặt với những kỳ vọng mà ông nội đặt lên mình.</p>', 'Full', 1, 'single', 'completed', 21, 2026, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Karthi","avatar":""},{"name":"Krithi Shetty","avatar":""},{"name":"Sathyaraj","avatar":""},{"name":"Rajkiran","avatar":""},{"name":"Anandaraj","avatar":""},{"name":"Shilpa Manjunath","avatar":""},{"name":"Karunakaran","avatar":""},{"name":"G. M. Sundar","avatar":""},{"name":"Ramesh Thilak","avatar":""},{"name":"Vadivukarasi","avatar":""},{"name":"Nizhalgal Ravi","avatar":""},{"name":"P.L. Thenappan","avatar":""},{"name":"Vidhya Borgia","avatar":""},{"name":"Nivas Adithan","avatar":""},{"name":"Madhur Mittal","avatar":""},{"name":"Melvin Dennis","avatar":""},{"name":"Carl A. Harte","avatar":""},{"name":"Raghu Babu","avatar":""},{"name":"Ravi Ma","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Karthi 28","Annagaru Vostaru","Vaa vathiyar","Va Vathiyar","Vaa Vathiyaar","வா வாத்தியார்"]', 1784690324122);
