INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vaa-vaathiyaar', 'Vaa Vaathiyaar', 'Vaa Vaathiyaar', 'vaa vaathiyaar vaa vaathiyaar karthi krithi shetty sathyaraj rajkiran anandaraj shilpa manjunath karunakaran g. m. sundar ramesh thilak vadivukarasi nizhalgal ravi p.l. thenappan vidhya borgia nivas adithan madhur mittal melvin dennis carl a. harte raghu babu ravi ma karthi 28 annagaru vostaru vaa vathiyar va vathiyar vaa vathiyaar வா வாத்தியார்', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-shin', 'Bác Sĩ Shin', 'Doctor Shin', 'https://phimimg.com/upload/vod/20260326-1/c53b3724cc73c1bf43d9936886a086a6.jpg', 'https://phimimg.com/upload/vod/20260326-1/fef2b9e88f9ac3cb7d7dd1cd331fcc30.jpg', '<p>Một tai nạn bất ngờ khiến ngôi sao hàng đầu Mo Mo (Baek Seo Ra) rơi vào hôn mê sâu, để lại người mẹ Ran Hui (Joo Se Bin) tuyệt vọng nhìn con gái dần tàn lụi. Trong khoảnh khắc giữa sống và chết, Ran Hui đưa ra quyết định điên rồ – đánh đổi chính mạng sống mình để cứu lấy Mo Mo. Từ đó, bác sĩ thiên tài Ju Sin (Jung E Chan) bước vào, người từng yêu Mo Mo và nay bị cuốn vào một thử nghiệm vượt qua ranh giới của Thượng Đế. Khi Mo Mo tỉnh lại, cô dường như là một người khác – nụ cười, ánh mắt, cách nói chuyện… tất cả đều lạ lẫm. Giữa những người đàn ông từng yêu cô và những bí mật ẩn sâu trong phòng thí nghiệm, câu hỏi ám ảnh dần hiện ra: khi ta yêu một người, ta yêu linh hồn hay thể xác? Bộ phim xoáy sâu vào ranh giới mong manh giữa khoa học và cảm xúc, giữa tình yêu và tội lỗi, nơi mọi lựa chọn đều mang theo cái giá không thể đo đếm.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 24, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jung E-chan","avatar":""},{"name":"Baek Seo-ra","avatar":""},{"name":"An Woo-yeon","avatar":""},{"name":"Joo Se-Bin","avatar":""},{"name":"Chun Young-min","avatar":""},{"name":"Song Ji-in","avatar":""},{"name":"Jeon No-min","avatar":""},{"name":"Gee Young-san","avatar":""},{"name":"Kang Na-eon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Doctor Shin","Dakteosin","Doctor Sin","닥터신"]', 1784690324122);
