INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-song-muu-meo', 'Dòng Sông Mưu Mẹo', 'The Water (The Water 4 Elements)', 'https://phimimg.com/upload/vod/20260323-1/08980cac09ceebc2f7e3e5ac77c8e612.jpg', 'https://phimimg.com/upload/vod/20260323-1/bd347dcb38ff8dc21f27d6e3696721eb.jpg', '<p>Giữa cuộc chiến quyền lực khốc liệt giữa &quot;Tập đoàn Vatin&quot; và &quot;Tập đoàn Vatchara&quot;, Chonlada – cô con gái bí mật của ông trùm Pheemdet – bị biến thành quân cờ để phá hoại đối thủ cạnh tranh. Cô thâm nhập vào công ty với tư cách là một nhân viên lễ tân nhằm tiếp cận Apo, một nữ điều hành sắc sảo và đầy kinh nghiệm. Dù ngay từ đầu Apo đã nhìn thấu kế hoạch này, nhưng cô vẫn chọn cách thuận theo trò chơi để bảo vệ Lada khỏi những mối nguy hiểm đang rình rập. Trải qua những vụ bê bối và những cuộc khủng hoảng đe dọa đến tính mạng, những bức tường ngăn cách giữa họ dần sụp đổ, biến sự đối đầu thành sự quan tâm chân thành dành cho nhau.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 22, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Engfa Waraha","avatar":""},{"name":"Charlotte Austin","avatar":""},{"name":"Thanthip Thaweesinthanat","avatar":""},{"name":"Suchita Oxman","avatar":""},{"name":"Panichada Kongsawanya","avatar":""},{"name":"Chutima Sodaphak","avatar":""},{"name":"Sarocha Chankimha","avatar":""},{"name":"Milin Watinthanakit","avatar":""},{"name":"Lapisara Intarasut","avatar":""},{"name":"Panthita Jencharoentham","avatar":""},{"name":"Asavarid Pinitkanjanapun","avatar":""},{"name":"Nicole Theriault","avatar":""},{"name":"Pete Thongch","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Water 4 Elements","บ้านวาทินวณิช: นทีร้อยเล่ห์","4 Elements: The Water","นทีร้อยเล่ห์ บ้านวาทินวณิช","นทีร้อยเล่ห์"]', 1784690324122);
