INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-ma-hanh-phuc', 'Bóng Ma Hạnh Phúc', 'The Ghost Of Happiness', 'https://phimimg.com/upload/vod/20260411-1/86ef3be13cd96c237487646c36173140.jpg', 'https://phimimg.com/upload/vod/20260411-1/e846238c395ac0fea302be8b608ddab0.jpg', '<p>Bóng Ma Hạnh Phúc xoay quanh cuộc hôn nhân đầy rạn nứt giữa Hoàng Dũng và Thanh Mai khi người vợ từ bỏ sự nghiệp để làm hậu phương nhưng lại bị chồng phản bội bởi sự xuất hiện của &quot;tiểu tam&quot; Như Trang, từ đó phơi bày những ích kỷ, dối trá và bi kịch ẩn sau vỏ bọc gia đình hoàn mỹ.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 23, 2026, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Lương Thế Thành","avatar":""},{"name":"Lê Phương","avatar":""},{"name":"Ngân Hòa","avatar":""},{"name":"Tăng Huỳnh Như","avatar":""},{"name":"Lê Nguyên Bảo","avatar":""},{"name":"Hoài An","avatar":""},{"name":"Bảo Anh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324122);
