INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sac-thai-cam-do', 'Sắc Thái Cám Dỗ', 'All Shades of Temptation', 'https://phimimg.com/upload/vod/20260508-1/27c4e74b043fc43f60b2e7782bbb0cc4.jpg', 'https://phimimg.com/upload/vod/20260508-1/c3d793784d18e90c6daf816bfded6584.jpg', '<p>Tại Lemberg (Lviv) năm 1897, Amelia Kryzhevska-Zeg trở về trang viên gia đình nơi cô lớn lên sau tuần trăng mật. Cô tràn đầy hy vọng về tương lai và mơ ước mở hiệu thuốc riêng. Nhưng dần dần, ngôi nhà thời thơ ấu của cô biến thành một cái bẫy nguy hiểm, và những kế hoạch của Amelia trở thành những ước muốn không thể thực hiện được.</p>', 'Full', 1, 'single', 'completed', 38, 2026, 'Vietsub', 'FHD', 'Quốc Gia Khác', 0, '[{"name":"Olena Lavreniuk","avatar":""},{"name":"Volodymyr Dantes","avatar":""},{"name":"Daniel Salem","avatar":""},{"name":"Oksana Cherkashyna","avatar":""},{"name":"Olena Khokhlatkina","avatar":""},{"name":"Oleksandr Kobzar","avatar":""},{"name":"Serhii Lavreniuk","avatar":""},{"name":"Bohdan Zhdanov","avatar":""},{"name":"Valerii Shalyha","avatar":""},{"name":"Oleg Artamonov","avatar":""},{"name":"Serhii Korotun","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Vsi vidtinky spokusy","Всі відтінки спокуси"]', 1784690324122);
