INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gianh-lai-cong-ly-2026', 'Giành Lại Công Lý', 'Oscar Shaw', 'https://phimimg.com/upload/vod/20260508-1/4db838f3828076250f516186c8195fe0.jpg', 'https://phimimg.com/upload/vod/20260508-1/b757ac4a4daf55bdcf9dad6adda61f33.jpg', '<p>Sau khi giải ngũ khỏi ngành cảnh sát, một thám tử kiên cường bị ám ảnh bởi cái chết bi thảm của người bạn thân nhất bắt đầu một cuộc hành trình đầy nguy hiểm để trả thù, tìm kiếm sự chuộc lỗi và chiến đấu để khôi phục công lý cho những con phố mà anh từng thề sẽ bảo vệ.</p>', 'Full', 1, 'single', 'completed', 7, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Michael Jai White","avatar":""},{"name":"Tyrese Gibson","avatar":""},{"name":"Isaiah Washington","avatar":""},{"name":"Andrew C. English Jr.","avatar":""},{"name":"Cecile Cubiló","avatar":""},{"name":"Jeanette Josue","avatar":""},{"name":"Hiro Ortiz","avatar":""},{"name":"James Choi","avatar":""},{"name":"Rich Paul","avatar":""},{"name":"Jabari Striblin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Oscar Shaw"]', 1784690324123);
