INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-anh-hung-21-tuoi', 'Người Anh Hùng 21 Tuổi', 'Ikkis / Twenty One', 'https://phimimg.com/upload/vod/20260508-1/6c0478e1f083829850c380f84df97244.jpg', 'https://phimimg.com/upload/vod/20260508-1/cfcb286af086f7f8d6905f9a93fae72f.jpg', '<p>Trung úy Arun Khetarpal, người trẻ tuổi nhất Ấn Độ được nhận Huân chương Param Vir Chakra, đã hy sinh mạng sống khi chiến đấu cho tiểu đoàn và đất nước trong trận Basantar năm 1971. Ikkis cũng nhìn nhận một cách sâu sắc về sự vô nghĩa của chiến tranh qua con mắt của cha Khetarpal, người đến thăm quê nhà ở Sargodha và trường cũ để đoàn tụ, nay thuộc Pakistan thời hậu phân chia, 30 năm sau.</p>', 'Full', 1, 'single', 'completed', 40, 2026, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Dharmendra","avatar":""},{"name":"Jaideep Ahlawat","avatar":""},{"name":"Agastya Nanda","avatar":""},{"name":"Simar Bhatia","avatar":""},{"name":"Shree Bishnoi","avatar":""},{"name":"Suhasini Mulay","avatar":""},{"name":"Rahul Dev","avatar":""},{"name":"Sikandar Kher","avatar":""},{"name":"Ekavali Khanna","avatar":""},{"name":"Vivaan Shah","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Ikkis (2026)","इक्कीस"]', 1784690324123);
