INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-huntsman', 'The Huntsman', 'The Huntsman', 'https://phimimg.com/upload/vod/20260508-1/370200678e40596c9bc87a4550b19370.jpg', 'https://phimimg.com/upload/vod/20260508-1/20356daf3699075a21323e87ca0b251d.jpg', '<p>Khi câu chuyện tiếp diễn, Max trở thành người chăm sóc sống cùng Lincoln sau khi anh tỉnh dậy, bất chấp sự phản đối của Darby Albright, em gái của y tá và cũng là thám tử chính của vụ án. Nhưng Max có thể có một động cơ thầm kín khi chuyển đến sống cùng Lincoln và người vợ xinh đẹp Jolene, một nhà điêu khắc tài ba và là mẹ của cô con gái mới sinh Rosy, một động cơ có thể dẫn đến những tiết lộ gây sốc nhất từ trước đến nay.</p>', 'Full', 1, 'single', 'completed', 13, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Shawn Ashmore","avatar":""},{"name":"Elizabeth Mitchell","avatar":""},{"name":"Jessy Schram","avatar":""},{"name":"Garret Dillahunt","avatar":""},{"name":"Brent Bailey","avatar":""},{"name":"Maddison Bullock","avatar":""},{"name":"Jobie James","avatar":""},{"name":"John W Heath","avatar":""},{"name":"Adam Hampton","avatar":""},{"name":"Bruce Davis","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["The Huntsman"]', 1784690324123);
