INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giet-tony-ngay-xua-ngay-xua-o-texas', 'Giết Tony: Ngày Xửa Ngày Xưa ở Texas', 'Kill Tony: Once Upon A Time In Texas', 'https://phimimg.com/upload/vod/20260508-1/7f467083fe2ea3ee41d02b8efd01a8cb.jpg', 'https://phimimg.com/upload/vod/20260508-1/9b64088fe1087e541e9e54f32ff9920e.jpg', '<p>Một phút. Một micro. Không khoan nhượng. Tony Hinchcliffe và một nhóm khách mời nổi tiếng sẽ thử thách các diễn viên hài triển vọng tại một buổi trình diễn đầy cam go ở Austin.</p>', 'Full', 1, 'single', 'completed', 9, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tony Hinchcliffe","avatar":""},{"name":"Brian Redban","avatar":""},{"name":"Gabriel Iglesias","avatar":""},{"name":"Harland Williams","avatar":""},{"name":"Carrot Top","avatar":""},{"name":"Rob Schneider","avatar":""},{"name":"Roseanne Barr","avatar":""},{"name":"Joe DeRosa","avatar":""},{"name":"James McCann","avatar":""},{"name":"Dedrick Flynn","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Kill Tony: Once Upon a Time in Texas"]', 1784690324123);
