INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-on-moi-nguoi-tiep-theo-phan-3', 'Cảm Ơn, Mời Người Tiếp Theo (Phần 3)', 'Thank You, Next (Season 3)', 'https://phimimg.com/upload/vod/20260508-1/9b7ca146807c0ae4b4ec846b08f3de67.jpg', 'https://phimimg.com/upload/vod/20260508-1/0d6cbb96062c4c7895522b41f39acd0f.jpg', '<p>Leyla cố gắng vượt qua mối quan hệ cũ đầy tổn thương và quyết định sống theo cách riêng của mình. Nhưng cô lại bước vào một mối quan hệ mới bất ngờ trong khi bạn bè vẫn luôn đồng hành bên cạnh.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 25, 2026, 'Vietsub', 'FHD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Serenay Sarikaya","avatar":""},{"name":"Metin Akdülger","avatar":""},{"name":"Boran Kuzum","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Спасибо. Следующий!","Thank You, Next","Kimler Geldi Kimler Geçti"]', 1784690324123);
