INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-vat-vo-gia', 'Kỷ vật vô giá', 'Remarkably Bright Creatures', 'https://phimimg.com/upload/vod/20260508-1/d2c603a9f458a02cf0913e486f2bc2b7.jpg', 'https://phimimg.com/upload/vod/20260508-1/f91ffad964f751ab20bf555b3597254a.jpg', '<p>Phim kể về Tova — một góa phụ lớn tuổi làm ca đêm tại thủy cung — dần hình thành tình bạn kỳ lạ với Marcellus, một con bạch tuộc cực kỳ thông minh. Trong lúc đó, cô gặp Cameron, chàng trai trẻ đang tìm kiếm gia đình thật sự của mình. Ba nhân vật cùng dần hé lộ một bí mật gia đình kéo dài nhiều năm.</p>', 'Full', 1, 'single', 'completed', 11, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sally Field","avatar":""},{"name":"Lewis Pullman","avatar":""},{"name":"Alfred Molina","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["尤为明亮的生物","幸运有八只触手","Remarkably Bright Creatures"]', 1784690324123);
