INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mat-ngu-ky', 'Mật Ngữ Kỷ', 'The Epoch Of Miyu', 'mật ngữ kỷ the epoch of miyu chung hán lương chu châu lý mộng kinh siêu nhậm bân từ hải kiều quách hiểu đình cao khanh trần hải lục mi yu ji 蜜语纪', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-gian-kinh-hong-khach', 'Nhân Gian Kinh Hồng Khách', 'A Lover In The Mortal World', 'https://phimimg.com/upload/vod/20260430-1/aad56f56f5dc2e9c3ab2201b4c25c730.jpg', 'https://phimimg.com/upload/vod/20260430-1/19351214552aa69354fb98be863c22c4.jpg', '<p>Tại biên giới giữa Tĩnh Lan và tộc Xương Mạc, pháo đài Thiên Lang Quan do Tiêu Trì, “quân thần Bạch Mã,” trấn giữ. Trong lễ thành thân của thuộc hạ, anh phát hiện tân nương bị ép gả nên lập tức ra tay, cách chức chú rể và tống giam, rồi đích thân thẩm vấn. Không ngờ, cô chính là Hàn Vân Linh—người từng cứu mạng anh năm xưa. Hóa ra, cô chấp nhận cuộc hôn nhân này để cứu bạn thân Khương Vãn Ngọc bị bắt oan. Sau khi làm rõ sự thật, Tiêu Trì thả cả hai. Tuy nhiên, Hàn Vân Linh sớm nhận ra anh mắc bệnh nặng, khó sống lâu nếu không kịp chữa trị. Dù Tiêu Trì yêu cầu giữ kín, cô khẳng định mình có thể chữa khỏi cho anh.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 24, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chu Chính Đình","avatar":""},{"name":"Lô Dương Dương","avatar":""},{"name":"Tạ Bân Bân","avatar":""},{"name":"Chiến Vũ","avatar":""},{"name":"Địch Thanh","avatar":""},{"name":"Trác Y Na Mục","avatar":""},{"name":"Đàm Hiểu Phàm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ni Shi Ren Jian Jing Hong Ke","大唐女史薛涛传","你是人间惊鸿客","Мир полон сюрпризов","You Are a Lover in the Mortal World","The World Is Full of Surprises","人间惊鸿客"]', 1784690324123);
