INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-ca-kashgar', 'Tình Ca Kashgar', 'Bloom Life', 'https://phimimg.com/upload/vod/20260506-1/27680fc97bc7c7bfd9279325197fcfd0.jpg', 'https://phimimg.com/upload/vod/20260506-1/5b969212efd973b56700ab36f264d2a7.jpg', '<p>Câu chuyện kể về ba chị em lớn lên trong thành cổ Kashgar, đối mặt với những khó khăn trong cuộc sống, trưởng thành từ sự va chạm giữa truyền thống và hiện đại, cùng nhau vượt qua bão tố cuộc đời, dùng tình yêu thương và hơi ấm để chữa lành cho nhau và bắt đầu lại cuộc sống của mình.</p>', 'Tập 8', 24, 'series', 'ongoing', 21, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Lan Địch","avatar":""},{"name":"Quách Tuấn Thần","avatar":""},{"name":"Khâu Thiên","avatar":""},{"name":"Mộc Khắc Nhiệt Mộc · Khai Tát Nhĩ","avatar":""},{"name":"Oa Nhĩ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["半个月亮爬上来","喀什古城","喀什恋歌"]', 1784690324123);
