INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tinh-ca-kashgar', 'Tình Ca Kashgar', 'Bloom Life', 'tình ca kashgar bloom life lý lan địch quách tuấn thần khâu thiên mộc khắc nhiệt mộc · khai tát nhĩ oa nhĩ 半个月亮爬上来 喀什古城 喀什恋歌', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tin-don-tinh-yeu', 'Tin Đồn Tình Yêu', 'Scandal Love', 'https://phimimg.com/upload/vod/20260411-1/80b7946e133c587e98b4461d540d1f80.jpg', 'https://phimimg.com/upload/vod/20260411-1/914298f15e5b27d9381fca76d7c0834d.jpg', '<p>Trong ngành công nghiệp thần tượng bị thương mại hóa cao độ, cảm xúc thường được &quot;sản xuất&quot; và bán đi như một phần của thương hiệu. Scandal Love theo chân bốn người phụ nữ đang chèo lái qua những tầng nấc quyền lực khác nhau trong hệ thống nhóm nhạc nữ K-pop. Khi phải vật lộn với những bản hợp đồng khắc nghiệt, sự soi mói quá mức từ công chúng và những rung cảm thực sự của chính mình, mỗi người đều buộc phải đưa ra những lựa chọn bất khả thi. Bộ phim khám phá một câu hỏi cốt lõi: Liệu tình yêu thực sự có thể tồn tại bên trong những mối quan hệ đã được thiết kế và kiểm soát một cách tỉ mỉ?</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 19, 2026, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Heo So Yoon","avatar":""},{"name":"Kim Hyeon-soo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["스캔덜러브","緋聞營業中","Scandal Love","스캔들러브"]', 1784690324123);
