INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tin-don-tinh-yeu', 'Tin Đồn Tình Yêu', 'Scandal Love', 'tin đồn tình yêu scandal love heo so yoon kim hyeon-soo 스캔덜러브 緋聞營業中 scandal love 스캔들러브', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-ky-dieu-dong-bac-khuc-dieu-lam', 'Câu Chuyện Kỳ Diệu Đông Bắc: Khúc Diêu Lam', 'Northeast Mysteries 2', 'https://phimimg.com/upload/vod/20260508-1/a1b4c4bd36c6995223bae1d41596a8d6.jpg', 'https://phimimg.com/upload/vod/20260508-1/eb4c8a99368160a296f084911a5c919f.jpg', '<p>Bên giếng Ứng Thanh, Quách Thúy Lan lúc nửa đêm bỗng gọi một cô gái trẻ là &quot;mẹ&quot;. Đứa con trai khờ khạo của bà là Phác Thông đã chết, nhưng bà kiên quyết thủ linh ba ngày, không cho mang xác đi. Lão Bạch Đầu cùng Tiêu Mặc và Lâm Vọng Nhi vào làng, phát hiện hương cúng bị trộn ngải cứu đắng. Đêm thủ linh, cái xác bỗng không mà dời vào phòng khách, trên sàn xuất hiện dấu chân băng giá. Tiêu Mặc bị siết cổ ngất đi và bị nhét vào quan tài giấy, còn Lâm Vọng Nhi nhìn vào gương thì thấy mình biến thành một bà lão. Người cháu trai Quách Dũng bề ngoài tỏ ra sốt sắng lo hậu sự, nhưng sau lưng lại dùng hợp đồng nhà đất ép cô mình ký sang tên, đánh tráo hương cúng và ngụy tạo hiện tượng xác chết di chuyển nhằm đổ tội &quot;người mẹ điên giết con&quot;. Lão Bạch Đầu nhìn thấu trò lừa, phơi bày sự thật: Quách Thúy Lan bị chứng mất trí nhớ (Alzheimer), lúc phát bệnh thì đánh con, khi tỉnh táo lại cho con uống canh độc, con chết còn bà sống độc thân. Lão Bạch Đầu đã tạo ra ảo cảnh để hai mẹ con được từ biệt nhau. Đằng sau tất cả những chuyện quái dị là lòng tham và tình yêu bị lãng quên của một người mẹ.</p>', 'Full', 1, 'single', 'completed', 8, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Minh","avatar":""},{"name":"Quách Thúy Lan","avatar":""},{"name":"Phác Thông","avatar":""},{"name":"Lão Bạch Đầu","avatar":""},{"name":"Tiêu Mặc","avatar":""},{"name":"Lâm Vọng Nhi","avatar":""},{"name":"Quách Dũng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["东北奇妙故事之摇篮曲"]', 1784690324123);
