INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('legends', 'Legends', 'Legends', 'https://phimimg.com/upload/vod/20260507-1/0afcc02a501353ed4dad29dd7c71d02f.jpg', 'https://phimimg.com/upload/vod/20260507-1/d46695a2acbb3c8e99618fe8cb528908.jpg', '<p>Một điều tra viên kỳ cựu (Steve Coogan) chỉ dẫn một nhân viên hải quan sống khép kín (Tom Burke) khi anh và một đội tân binh thâm nhập các băng đảng ma túy tàn bạo của Anh.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 21, 2026, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Tom Burke","avatar":""},{"name":"Steve Coogan","avatar":""},{"name":"Tom Hughes","avatar":""},{"name":"Aml Ameen","avatar":""},{"name":"Jasmine Blackborow","avatar":""},{"name":"Hayley Squires","avatar":""},{"name":"Douglas Hodge","avatar":""},{"name":"Johnny Harris","avatar":""},{"name":"Alex Jennings","avatar":""},{"name":"Con O''Neill","avatar":""},{"name":"Gerald Kyd","avatar":""},{"name":"Charlotte Ritchie","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["เลเจนด์ สายลับทลายยา","Legends"]', 1784690324123);
