INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-nam-ve-sau-thoat-xac', 'Chiến Nam: Ve Sầu Thoát Xác', 'Chien Nam: The Shedding Cicada', 'https://phimimg.com/upload/vod/20260507-1/ea3d4093eb27d4835e09a5ac015f7741.jpg', 'https://phimimg.com/upload/vod/20260507-1/b9d7f3b36b278eb47f283ea8dec16979.jpg', '<p>Khi nhà báo điều tra Ngọc biến mất cùng bằng chứng chống lại tập đoàn Thái Minh Huyền Thoại, một chiếc USB định mệnh rơi vào tay người bạn thân nhất của cô, Kim. Bị một đế chế tội phạm nhắm đến, người bảo vệ duy nhất của Kim là cảnh sát Chiến Nam. Điều bắt đầu như một nhiệm vụ bảo vệ dần biến thành một cuộc thâm nhập sâu vào tổ chức. Khi K52—đồng nghiệp của Chiến Nam—mất tích và Kim bị bắt cóc, Chiến Nam dấn thân vào mạng lưới âm mưu của Thái Minh. Ngay khi công lý dường như trong tầm tay, tên trùm thực hiện kế hoạch “thoát hiểm bằng vỏ ve sầu”. Cuộc chiến thực sự chỉ mới bắt đầu, buộc Chiến Nam phải dấn thân vào những góc tối nhất để khám phá sự thật đằng sau một màn ảo thuật được dàn dựng hoàn hảo.</p>', 'Trailer', 1, 'single', 'ongoing', 22, 2026, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Hứa Minh Đạt","avatar":""},{"name":"Huỳnh Phương","avatar":""},{"name":"Vinh Râu","avatar":""},{"name":"Thái Vũ","avatar":""},{"name":"Trương Minh Cường","avatar":""},{"name":"Longka","avatar":""},{"name":"Quách Ngọc Tuyên","avatar":""},{"name":"Nhi Katy","avatar":""},{"name":"Hoàng Mèo","avatar":""},{"name":"Tùng Yuki","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Chiến Nam: Ve Sầu Thoát Xác"]', 1784690324123);
