INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-ba-toi-mot-phong', 'Nhà Ba Tôi Một Phòng', 'Nhà Ba Tôi Một Phòng', 'https://phimimg.com/upload/vod/20260507-1/2b161d7705add929b9c9f3bed848f9e2.jpg', 'https://phimimg.com/upload/vod/20260507-1/d67e0e2903442bb3f3b70eb8c1efc900.jpg', '<p>Lấy bối cảnh một khu chung cư cũ với căn nhà chỉ vỏn vẹn một phòng, Nhà Ba Tôi Một Phòng khắc họa mối quan hệ “lệch pha” giữa người cha bảo thủ và cô con gái Gen Z đầy mơ ước. Khi những khác biệt thế hệ va chạm trong không gian chật chội, tình thân dần được thử thách và hàn gắn. Bộ phim mang đến một lát cắt gần gũi về gia đình Việt hiện đại, nơi yêu thương đôi khi bắt đầu từ sự thấu hiểu.</p>', 'Trailer', 1, 'single', 'ongoing', 37, 2026, 'Lồng Tiếng', 'FHD', 'Việt Nam', 1, '[{"name":"Trường Giang","avatar":""},{"name":"Minh Anh","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Nhà Ba Tôi Một Phòng"]', 1784690324123);
