INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-gia-tro-lai', 'Bố Già Trở Lại', 'Bố Già Trở Lại', 'https://phimimg.com/upload/vod/20260507-1/6834c013ed4434aa676934c122519b47.jpg', 'https://phimimg.com/upload/vod/20260507-1/d920d15acd45fab965d9f1ccfd496c5e.jpg', '<p>Bộ phim kể về Đằng, một cựu đặc vụ ngầm, người tưởng rằng quá khứ đẫm máu của mình đã lùi lại phía sau, nhưng lại bị buộc phải quay trở lại cuộc chiến khốc liệt khi con gái anh, Yến, đột nhiên bị bắt cóc. Việc giải cứu cô không chỉ trở thành cuộc chiến không khoan nhượng chống lại cái ác tàn nhẫn, mà còn là một hành trình chuộc lỗi và hàn gắn tình cảm sâu sắc, khi Đằng đối mặt với những rạn nứt và mất mát trong chính gia đình mình.</p>', 'Trailer', 1, 'single', 'ongoing', 29, 2026, 'Lồng Tiếng', 'FHD', 'Việt Nam', 1, '[{"name":"Mỹ Uyên","avatar":""},{"name":"Tuấn Voi","avatar":""},{"name":"Huỳnh Đông","avatar":""},{"name":"Trần Quang Đại","avatar":""},{"name":"ไซม่อน กุ๊ก","avatar":""},{"name":"Nhi Katy","avatar":""},{"name":"Hải Ngân","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Bố Già Trở Lại"]', 1784690324123);
