INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('daredevil-tai-xuat-phan-2', 'Daredevil: Tái Xuất (Phần 2)', 'Daredevil: Born Again (Season 2)', 'https://phimimg.com/upload/vod/20260325-1/4ba73b9444858633f1592a417fa2c0dc.jpg', 'https://phimimg.com/upload/vod/20260325-1/7268bfab7c97370dad7a07d1c93ff834.jpg', '<p>Bộ phim xoay quanh Matt Murdock (do Charlie Cox thủ vai), một luật sư mù ở Hell’s Kitchen, New York, người sống hai cuộc đời: ban ngày là một luật sư đấu tranh cho công lý, ban đêm là Daredevil – một siêu anh hùng đeo mặt nạ bảo vệ thành phố. Phim lấy bối cảnh vài năm sau các sự kiện của loạt phim Netflix, khi Matt cùng hai người bạn thân là Foggy Nelson (Elden Henson) và Karen Page (Deborah Ann Woll) đã tìm thấy sự ổn định trong cuộc sống với văn phòng luật của họ.Tuy nhiên, sự yên bình này không kéo dài khi Wilson Fisk (Vincent D’Onofrio), tức Kingpin – kẻ thù truyền kiếp của Daredevil, tái xuất với một kế hoạch đầy tham vọng. Không còn hoạt động trong thế giới ngầm như trước, Fisk giờ đây hướng đến chính trường và trở thành một nhân vật quyền lực tại New York, thậm chí có thể là thị trưởng. Mâu thuẫn giữa Matt và Fisk leo thang khi cả hai đối đầu trong một cuộc chiến vừa mang tính cá nhân vừa ảnh hưởng đến cả thành phố.</p>', 'Tập 8', 9, 'series', 'ongoing', 36, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Charlie Cox","avatar":""},{"name":"Vincent D''Onofrio","avatar":""},{"name":"Margarita Levieva","avatar":""},{"name":"Wilson Bethel","avatar":""},{"name":"Deborah Ann Woll","avatar":""},{"name":"Krysten Ritter","avatar":""},{"name":"Matthew Lillard","avatar":""},{"name":"Ayelet Zurer","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f