INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-tinh-da-trach', 'Huyền Tình Dạ Trạch', 'Huyền Tình Dạ Trạch', 'https://phimimg.com/upload/vod/20260505-1/8c5199c76e20e44fdefaf1f2b1484883.jpg', 'https://phimimg.com/upload/vod/20260505-1/b9d049135af04f106ff216123c0f2bb3.jpg', '<p>Huyền Tình Dạ Trạch không chỉ là một bản tình ca lãng mạn về tình yêu vượt mọi quy tắc giữa chàng trai tận tụy Chử Đồng Tử và công chúa Tiên Dung, mà còn là một cuộc hành trình văn hóa sử thi đưa khán giả trở về với vẻ huy hoàng của Đông Sơ Đông. Cuộc gặp gỡ định mệnh của họ tại đầm lầy Dạ Trạch rộng lớn trở thành biểu tượng của tình yêu bất diệt và là cuộc hành trình chung về sự định cư, sinh tồn và nỗ lực chinh phục thiên nhiên của nhân loại trong thời đại Văn Lang.</p>', 'Trailer', 1, 'single', 'ongoing', 15, 2026, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Xuân Phúc","avatar":""},{"name":"Lê Trần Thanh Tâm","avatar":""},{"name":"Viết Liên","avatar":""},{"name":"Chiều Xuân","avatar":""},{"name":"Trọng Trinh","avatar":""},{"name":"Minh Tiệp","avatar":""},{"name":"Bảo Anh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Huyền Tình Dạ Trạch"]', 1784690324123);
