INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-nhap-trang-2', 'Quỷ Nhập Tràng 2', 'The Corspe 2', 'https://phimimg.com/upload/vod/20260505-1/cbc5286fb860a0c8aaf625058869d6fe.jpg', 'https://phimimg.com/upload/vod/20260505-1/ffbe96cdfc4d8a0c2551286a019fe36b.jpg', '<p>Quỷ Nhập Tràng 2 là tiền truyện của nhân vật Minh Như, trở về xưởng nhuộm gia đình sau nhiều năm bị xua đuổi. Tại đây, cô phải đối mặt với những hiện tượng ma quái cùng sự thật tàn khốc về cái chết của mẹ và giao ước đẫm máu năm xưa. Ác giả ác báo, liệu Minh Như có thoát khỏi vòng vây của quỷ dữ?</p>', 'Trailer', 1, 'single', 'ongoing', 36, 2026, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Khả Như","avatar":""},{"name":"Ngô Quang Tuấn","avatar":""},{"name":"Thanh Hiền","avatar":""},{"name":"Phương Bình","avatar":""},{"name":"Doãn Quốc Đam","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Quỷ Nhập Tràng 2"]', 1784690324123);
