INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-the', 'Tư Thế', 'Pose', 'https://phimimg.com/upload/vod/20260505-1/e65b876761fccf94cecc5d528fb7df36.jpg', 'https://phimimg.com/upload/vod/20260505-1/da2cd4027ea91214c092f0aae71bb767.jpg', '<p>Bị cô lập trong một trang viên rộng lớn ở vùng quê, một nghệ sĩ sống ẩn dật trải qua một cuối tuần đầy đam mê và hoang tưởng với người yêu cũ, một người hâm mộ cuồng nhiệt và một nàng thơ tiềm năng. Hy vọng khơi dậy một làn sóng sáng tạo nghệ thuật mới trong vài ngày hỗn loạn, đầy rẫy những điều bất ngờ và những tiết lộ, nhưng không phải ai trong số họ cũng sẽ sống sót trở về.</p>', 'Trailer', 1, 'single', 'ongoing', 15, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"James McAvoy","avatar":""},{"name":"Lucas Bravo","avatar":""},{"name":"Leila Farzad","avatar":""},{"name":"Almudena Amor","avatar":""},{"name":"Aisling Franciosi","avatar":""},{"name":"Elektra Jansson-Kilbey","avatar":""},{"name":"Maria Therese Bassetti","avatar":""},{"name":"Kristin Zakala","avatar":""},{"name":"Shubham Saraf","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Turn Up the Sun!","Aumente o brilho do sol!","Pose"]', 1784690324123);
