INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-tim-ban-se-tan-vo', 'Trái Tim Bạn Sẽ Tan Vỡ', 'Your Heart Will Be Broken', 'https://phimimg.com/upload/vod/20260505-1/6c38f25a6930573329db7f298e70c316.jpg', 'https://phimimg.com/upload/vod/20260505-1/baa72b0c577d0e1e20d4091d6fb55deb.jpg', '<p>Polina, một nữ sinh trung học, được cứu thoát khỏi nạn bắt nạt ở trường mới và thỏa thuận với tên bắt nạt chính Bars: hắn phải giả vờ làm bạn trai của cô và bảo vệ cô, còn cô phải làm theo mọi điều hắn yêu cầu. Trong trò chơi này, cả hai nảy sinh tình cảm thật sự, nhưng gia đình và bạn bè cùng lớp của cô lại có lý do để chia rẽ hai người.</p>', 'Trailer', 1, 'single', 'ongoing', 28, 2026, 'Vietsub', 'FHD', 'Nga', 0, '[{"name":"Вероника Журавлёва","avatar":""},{"name":"Даниэль Вегас","avatar":""},{"name":"Аля Майер","avatar":""},{"name":"Максим Сапрыкин","avatar":""},{"name":"Евгения Лоза","avatar":""},{"name":"Павел Кузьмин","avatar":""},{"name":"Иван Трушин","avatar":""},{"name":"Александра Тихонова","avatar":""},{"name":"Маргарита Дьяченкова","avatar":""},{"name":"Антон Соломатин","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Твоё сердце будет разбито","Tvoe serdtse budet razbito","Tvoyo serdtse budet razbito","Your Heart Will Be Broken"]', 1784690324123);
