INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-tien-gia-dai-chien-sieu-nang-luc', 'Tu Tiên Giả Đại Chiến Siêu Năng Lực', 'The Immortal VS Superheroes', 'https://phimimg.com/upload/vod/20260215-1/a9dc47d34e46184e69788f562a52db55.jpg', 'https://phimimg.com/upload/vod/20260215-1/289e30dc68cbebd1ae7e6705c7392900.jpg', '<p>Nham Sâm từng là cao thủ chí tôn của giới tu chân, bị kẻ ác kiêng dè, người trong môn phái bị tàn sát thảm hại. Nham Sâm muốn báo thù cho họ, nhưng lại bất cẩn để đối phương hợp lực phong ấn. Trong một lần tình cờ, hắn xuyên không đến thế giới của những người có siêu năng lực. Nơi đây, phần lớn con người đều sở hữu đủ loại siêu năng lực khác nhau, họ được gọi là “anh hùng”, quanh năm chiến đấu với quái thú, cứu vớt thế giới.</p>', 'Tập 40', 80, 'hoathinh', 'ongoing', 9, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Immortal VS Superheroes","修仙者大战超能力"]', 1784690324123);
