INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-ac-dao-mon-do-cuong-tin', 'Tam Ác Đạo: Môn Đồ Cuồng Tín', 'Samakdo', 'https://phimimg.com/upload/vod/20260505-1/0b080786cbe29e0059308f69b69fcf8c.jpg', 'https://phimimg.com/upload/vod/20260505-1/91f288108be4436c8a168c8ed1a499a1.jpg', '<p>Phim theo chân một nhà sản xuất chương trình điều tra, quyết định dấn thân vào hành trình vạch trần giáo phái “Samseondo” - một giáo phái đã bị phong ấn từ thời kỳ Nhật Bản đô hộ. Tại đây, những manh mối dần đưa họ tiến gần hơn đến sự thật kinh hoàng, khơi dậy nỗi ám ảnh lịch sử lên đỉnh điểm.</p>', 'Trailer', 1, 'single', 'ongoing', 16, 2026, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"조윤서","avatar":""},{"name":"곽시양","avatar":""},{"name":"Yang Joo-ho","avatar":""},{"name":"Im So Young","avatar":""},{"name":"장의수","avatar":""},{"name":"이푸름","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["삼악도"]', 1784690324123);
