INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-tien-ca-chet-nguoi', 'Nàng Tiên Cá Chết Người', 'The Deadly Little Mermaid', 'https://phimimg.com/upload/vod/20260505-1/d927c07f77e29bcbfbe1c94d46e6a280.jpg', 'https://phimimg.com/upload/vod/20260505-1/c424e056b120324fcae98d156c36f9cb.jpg', '<p>Một số bí mật tốt hơn hết nên để dưới đáy đại dương. Nhưng một khi cô ấy đã vào nhà bạn, sẽ không còn đường thoát. Khi một nghệ sĩ đang gặp khó khăn cứu sống một người phụ nữ xinh đẹp, bất tỉnh khỏi vùng nước lạnh giá ven biển, anh ta nghĩ mình đã làm nên một phép màu. Nhưng khi cô ấy hồi phục trong ngôi nhà biệt lập của anh, một loạt sự kiện đáng lo ngại dẫn anh đến một nhận thức kinh hoàng: sự hiện diện của cô ấy không phải là trùng hợp ngẫu nhiên. Cô ấy có mối liên hệ mật thiết với cùng một nấm mộ dưới nước đã cướp đi sinh mạng gia đình anh nhiều năm trước.</p>', 'Trailer', 1, 'single', 'ongoing', 17, 2026, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Elliott Eason","avatar":""},{"name":"Sophia Carroll","avatar":""},{"name":"Eleanor Mackenzie","avatar":""},{"name":"Anastasia Nikolaeva","avatar":""},{"name":"Maddy Baskerville","avatar":""},{"name":"Sasha Van Reenen","avatar":""},{"name":"Christian Ndonda","avatar":""},{"name":"Tristan Reynolds","avatar":""},{"name":"Ray Redmond","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["The Deadly Little Mermaid"]', 1784690324123);
