INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-cam', 'Trái Cấm', 'Forbidden Fruits', 'https://phimimg.com/upload/vod/20260504-1/4a885508c8762d6868569322b47e6333.jpg', 'https://phimimg.com/upload/vod/20260504-1/83668e20d04276574a2dbbe79d05bfb0.jpg', '<p>Apple, nhân viên của Free Eden, bí mật điều hành một hội kín nữ giới nhuốm màu phù thủy trong tầng hầm của cửa hàng ở trung tâm thương mại sau giờ đóng cửa, cùng với 2 “trái cấm” đồng hành là Cherry và Fig. Nhưng khi nhân viên mới Pumpkin lên tiếng thách thức thứ tình chị em đầy tính trình diễn của họ, cả nhóm buộc phải đối mặt với những độc tố trong chính mình, nếu không muốn bị cuốn vào một kết cục đẫm máu.</p>', 'Full', 1, 'single', 'completed', 18, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lili Reinhart","avatar":""},{"name":"Lola Tung","avatar":""},{"name":"Victoria Pedretti","avatar":""},{"name":"Alexandra Shipp","avatar":""},{"name":"Emma Chamberlain","avatar":""},{"name":"Gabrielle Union","avatar":""},{"name":"Hailey Summer","avatar":""},{"name":"Jordan Duarte","avatar":""},{"name":"David Pinard","avatar":""},{"name":"R Austin Ball","avatar":""},{"name":"Charlie Larsen","avatar":""},{"name":"Siddharth Sharma","avatar":""},{"name":"Jeff Sinasac","avatar":""},{"name":"Kwaku Adu-Poku","avatar":""},{"name":"Devery Jacobs","avatar":""},{"name":"Zack Thompson","avatar":""},{"name":"Jacqu","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["ЗАПРЕТНЫЙ ΠΛΟΔ","Forbidden Fruits"]', 1784690324123);
