INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-troi-day-cua-ke-chinh-phuc', 'Sự trỗi dậy của kẻ chinh phục', 'Rise of the Conqueror', 'https://phimimg.com/upload/vod/20260504-1/f511cee27340e69d64376e522bc4909f.jpg', 'https://phimimg.com/upload/vod/20260504-1/fd8f25fab457d3b8953412071a6eb5f8.jpg', '<p>Vào thế kỷ 14, khi Con đường Tơ lụa sụp đổ và các phe phái đối địch xé nát vùng đất, chiến binh dũng mãnh Timur nổi lên từ nơi lưu đày. Bị tước đoạt mọi thứ, ông chiến đấu để thống nhất các vương quốc tan vỡ, sử dụng chiến lược và ý chí kiên cường để tạo dựng một đế chế từ hỗn loạn. Bất bại trong chiến trận và được coi là một trong những nhà lãnh đạo và chiến thuật gia quân sự vĩ đại nhất trong lịch sử, chưa kể đến là một trong những người tàn bạo nhất, Timur đã thành lập Đế chế Timurid, cai trị Afghanistan, Iran và Trung Á ngày nay.</p>', 'Full', 1, 'single', 'completed', 37, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Christian Mortensen","avatar":""},{"name":"Mahesh Jadu","avatar":""},{"name":"Joshua Jo","avatar":""},{"name":"Sayed Badreya","avatar":""},{"name":"Yulduz Rajabova","avatar":""},{"name":"Arazou Baker","avatar":""},{"name":"Paul Marlon","avatar":""},{"name":"Dulguun Odkhuu","avatar":""},{"name":"Sanzhar Madi","avatar":""},{"name":"Umit Ulgen","avatar":""},{"name":"Aziz Beyshenaliev","avatar":""},{"name":"Yerkebulan Daiyrov","avatar":""},{"name":"Zhandos Aibassov","avatar":""},{"name":"Maksat Kairatuly","avatar":""},{"name":"Maruf Otajonov","avatar":""},{"name":"Majit Assan","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["Timur","Tamerlane: Rise of the Last Conquerer","Rise of the Conquerer","Amir Temur","Tamerlan","Temurlang","Амир Тимур","征服者崛起","帖木儿:征服者崛起","Rise of the Conqueror"]', 1784690324123);
