INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-tay-ban', 'Bàn tay bẩn', 'Dirty Hands', 'https://phimimg.com/upload/vod/20260504-1/b8abb6aaf4f9d16c61240314b05bb444.jpg', 'https://phimimg.com/upload/vod/20260504-1/14ee03f61d7770c5878a4027b6fcb28c.jpg', '<p>Trong thế giới ngầm của Chicago, một vụ giao dịch ma túy thông thường bỗng trở nên tồi tệ đối với anh em nhà Denton, Richie và Danny. Con trai của một ông trùm bị sát hại, một băng đảng đối thủ đang truy lùng ráo riết, và chính ông chủ của họ đang cố gắng giải quyết mớ hỗn độn mà họ gây ra, hai anh em phải chiến đấu để bảo vệ mạng sống của mình nếu muốn sống sót đến sáng hôm sau.</p>', 'Full', 1, 'single', 'completed', 11, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Patrick Muldoon","avatar":""},{"name":"Kevin Interdonato","avatar":""},{"name":"Michael Beach","avatar":""},{"name":"Denise Richards","avatar":""},{"name":"Guy Nardulli","avatar":""},{"name":"Wes McGee","avatar":""},{"name":"John Wollman","avatar":""},{"name":"Donald John Volpenhein","avatar":""},{"name":"Natara Easter","avatar":""},{"name":"Niko Anagnopoulos","avatar":""},{"name":"Erik Audé","avatar":""},{"name":"Dominic Berardi","avatar":""},{"name":"Joey Berardi","avatar":""},{"name":"A.J. Brugger","avatar":""},{"name":"John Fallon","avatar":""},{"name":"Brendan Kelleher","avatar":""},{"name":"Joh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Dirty Hands"]', 1784690324123);
