INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mavka-true-myth', 'Mavka. True Myth', 'Mavka. True Myth', 'https://phimimg.com/upload/vod/20260504-1/4b674742358db623eff3b3b7ff880c70.jpg', 'https://phimimg.com/upload/vod/20260504-1/b45819c23929ca1b9fbbcce20989ffae.jpg', '<p>Mavka, một tiên nữ rừng rậm huyền bí và nguy hiểm, đã đem lòng yêu nhà sinh vật học Lukyan thay vì tiêu diệt anh ta trong hồ nước bí ẩn giữa rừng, nơi các nàng tiên cá và những tiên nữ khác đang chờ đợi linh hồn con người. Và họ sẵn sàng làm bất cứ điều gì để giữ Mavka ở lại phe bóng tối.</p>', 'Full', 1, 'single', 'completed', 25, 2026, 'Vietsub', 'FHD', 'Quốc Gia Khác', 0, '[{"name":"Arina Bocharova","avatar":""},{"name":"Ivan Dovzhenko","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Mavka: The True Myth","Mavka: Die wahre Legende","Mavka. Spravzhnii mif","Мавка. Справжній міф"]', 1784690324123);
