INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kalevala-kullervon-tarina', 'Kalevala: Kullervon tarina', 'Son of Revenge – The Story of Kalevala', 'https://phimimg.com/upload/vod/20260504-1/a67f64ff557c0daa54036b3d172aaa66.jpg', 'https://phimimg.com/upload/vod/20260504-1/b7c01f2cc9f70e2b3fa59d3fdef6250c.jpg', '<p>Karelia vào thế kỷ 12. Mối thù giữa Kalervo và Untamo dẫn đến vụ thảm sát cả một ngôi làng. Người sống sót duy nhất là con trai của Kalervo, Kullervo, người mà Untamo quyết định nuôi dưỡng như con ruột. Khi lớn lên, sức mạnh tàn bạo và bản tính nổi loạn khiến Kullervo trở nên nguy hiểm, và dân làng muốn loại bỏ cậu ta vĩnh viễn. Kullervo dành cả đời để tìm kiếm mục đích sống và khả năng của mình. Khi những sự kiện trong quá khứ được hé lộ, số phận của cậu ta đã rõ ràng. Con đường báo thù dẫn Kullervo đến đối đầu với Untamo và buộc hắn phải chịu trách nhiệm về tội lỗi của mình.</p>', 'Full', 1, 'single', 'completed', 19, 2026, 'Vietsub', 'FHD', 'Phần Lan', 0, '[{"name":"Elias Salonen","avatar":""},{"name":"Eero Aho","avatar":""},{"name":"Ilkka Koivula","avatar":""},{"name":"Ronja Kuoppamäki","avatar":""},{"name":"Olli Rahkonen","avatar":""},{"name":"Krista Kosonen","avatar":""},{"name":"Johannes Holopainen","avatar":""},{"name":"Janne Hyytiäinen","avatar":""},{"name":"Seela Sella","avatar":""},{"name":"Jesse Gyllenbögel","avatar":""},{"name":"Julius Susimäki","avatar":""},{"name":"Jaakko Ohtonen","avatar":""},{"name":"Oona Airola","avatar":""},{"name":"Leo Kortelainen","avatar":""},{"name":"Aino Sihvonen","avatar":""},{"name":"Eevi Lappalainen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["卡勒瓦拉","卡勒瓦拉-库勒沃的故事","Kalevala: Kullervon tarina"]', 1784690324123);
