INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-dua', 'Tay Đua', 'Biker', 'https://phimimg.com/upload/vod/20260504-1/c11540e0734053ab272cb496bcd761c6.jpg', 'https://phimimg.com/upload/vod/20260504-1/44d89852090970689993b6e705a721d3.jpg', '<p>Niềm tự hào và mâu thuẫn gia đình đan xen khi một người đàn ông theo đuổi vinh quang trong môn đua mô tô địa hình, được thúc đẩy bởi lòng dũng cảm, tinh thần và sự nguy hiểm cận kề.</p>', 'Full', 1, 'single', 'completed', 17, 2026, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Sharwanand","avatar":""},{"name":"Dr. Rajasekhar","avatar":""},{"name":"Malavika Nair","avatar":""},{"name":"Atul Kulkarni","avatar":""},{"name":"Brahmaji","avatar":""},{"name":"Dayanand Reddy","avatar":""},{"name":"Shashank","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["ไบเกอร์: ซิ่งเดือดสายเลือดนักบิด","Biker","బైకర్"]', 1784690324123);
