INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-em-duoi-lan-dan', 'Anh em dưới làn đạn', 'Brothers Under Fire', 'https://phimimg.com/upload/vod/20260504-1/7c80c76350085c4da057db21ac58021b.jpg', 'https://phimimg.com/upload/vod/20260504-1/b510a8f2a9d592a5be3f5caf7310ece1.jpg', '<p>Phi đội của Đại úy Jordan Wright đang nghỉ phép dự đám cưới ở Mexico thì chạm trán với một băng đảng ma túy khét tiếng. Khi Jordan cố gắng dẫn những người sống sót đến nơi an toàn, chiến tranh nổ ra giữa đội của anh và băng đảng, buộc anh phải tham gia vào trận chiến để cứu đồng đội.</p>', 'Full', 1, 'single', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kiefer Sutherland","avatar":""},{"name":"Tommy Martinez","avatar":""},{"name":"Ashton Sanders","avatar":""},{"name":"Solly McLeod","avatar":""},{"name":"Laura Osma","avatar":""},{"name":"Omar Chaparro","avatar":""},{"name":"Orlando Pineda","avatar":""},{"name":"Laird Akeo","avatar":""},{"name":"Flora Martínez","avatar":""},{"name":"Gabriel Camero","avatar":""},{"name":"Sabrina Scutt","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Sierra Madre","Under Fire","Brothers Under Fire"]', 1784690324123);
