INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-tu-than', 'Cổng Tử Thần', 'The Gates', 'https://phimimg.com/upload/vod/20260425-1/d6553bdc31293dfb9ab6a022330150ea.jpg', 'https://phimimg.com/upload/vod/20260425-1/8722568f411d48cd7affe1f6362e2405.jpg', '<p>Kể về ba người bạn trong chuyến road trip vô tình chứng kiến một vụ giết người trong một khu dân cư khép kín. Họ nhanh chóng bị mắc kẹt bên trong và trở thành mục tiêu săn đuổi của cư dân nơi đây – những người tin rằng họ phải chịu trách nhiệm cho sự việc. Trong khi cố gắng sống sót, tình bạn của họ dần rạn nứt, còn một nhân vật đứng đầu khu dân cư – vừa lôi cuốn vừa nguy hiểm – ngày càng siết chặt vòng vây.</p>', 'Full', 1, 'single', 'completed', 9, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mason Gooding","avatar":""},{"name":"Algee Smith","avatar":""},{"name":"Keith Powers","avatar":""},{"name":"James Van Der Beek","avatar":""},{"name":"Brad Leland","avatar":""},{"name":"Kylr Coffman","avatar":""},{"name":"Elle Evans","avatar":""},{"name":"Sofia Hublitz","avatar":""},{"name":"Aliyah Celeste","avatar":""},{"name":"Rob Gallavan","avatar":""},{"name":"Jaxon Noble Pickens","avatar":""},{"name":"Natasha Ellie","avatar":""},{"name":"Randy Wayne","avatar":""},{"name":"Shelby Simmons","avatar":""},{"name":"Rachel Thundat","avatar":""},{"name":"Isabella Betwee","avatar":""},{"name":"Tate Talley","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Gates"]', 1784690324123);
