INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-sang-dem-toi-hac-da-cao-bach', 'Ánh Sáng Đêm Tối (Hắc Dạ Cáo Bạch)', 'Light To The Night', 'https://phimimg.com/upload/vod/20260427-1/85220547b32cc943094bfe9df2388445.jpg', 'https://phimimg.com/upload/vod/20260427-1/c97610bf8a67fbc5e02c45834b5a6f3d.jpg', '<p>Một loạt vụ án bí ẩn xảy ra trong đêm, kéo theo những bí mật bị chôn giấu của nhiều người. Các nhân vật chính lần lượt bị cuốn vào cuộc điều tra, đối mặt với quá khứ và sự thật đen tối, nơi ranh giới giữa đúng – sai và thiện – ác dần trở nên mờ nhạt.</p>', 'Tập 17', 28, 'series', 'ongoing', 22, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Phan Việt Minh","avatar":""},{"name":"Vương Hạc Đệ","avatar":""},{"name":"Nhậm Mẫn","avatar":""},{"name":"Khương Bội Dao","avatar":""},{"name":"Trịnh Kỳ","avatar":""},{"name":"Triệu Hổ","avatar":""},{"name":"Khương Kỷ Lâm","avatar":""},{"name":"Lưu Sảng","avatar":""},{"name":"Chu Đại Dũng","avatar":""},{"name":"Lư Chính","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hei Ye Gao Bai","Zhui Ying Zhe","追影者","Confession in the Dark","Light to the Night","黑夜告白"]', 1784690324123);
