INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-xe-am-phu', 'Cuốc Xe Âm Phủ', 'Karma In The Backseat', 'https://phimimg.com/upload/vod/20260502-1/da1d0c0160b622b659c756519c3e320e.jpg', 'https://phimimg.com/upload/vod/20260502-1/38c638c8cd249ac11cdeb0699c9f9390.jpg', '<p>Hùng - tài xế taxi, kinh hoàng phát hiện vị khách cuối cùng trong ngày lại là một xác chết, kèm bọc tiền nhờ đi hỏa táng. Cứ tưởng chỉ là sự tình cờ xui xẻo, nhưng đó lại là một &quot;nghiệp báo&quot; đáng sợ.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 29, 2026, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Nguyễn Phương Nam","avatar":""},{"name":"Nguyễn Yến My","avatar":""},{"name":"Lâm Đức Anh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '[]', 1784690324123);
