INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thon-phe-tinh-khong-movie-quyet-chien-nguyen-thuy-tinh', 'Thôn Phệ Tinh Không Movie: Quyết Chiến Nguyên Thủy Tinh', 'Swallowed Star The Movie: Decisive Battle on the Primordial Star', 'https://phimimg.com/upload/vod/20260505-1/1ed0d0dbd16e93cc0969ebf10d2a84b1.jpg', 'https://phimimg.com/upload/vod/20260505-1/b1c0b05eb398b839f293dccdbaabe21d.jpg', '<p>La Phong từ rất lâu đã trở thành một vị anh hùng trong vũ trụ này, nhưng câu chuyện của lần này có phần rất đáng nói bởi nó gợi nhớ đến một trận đánh long trời lở đất trên Nguyên Thủy Tinh giữa anh và các thế lực dị tộc nơi đây. Vốn là khi đang rèn luyện vô cùng khắc nghiệt trên Nguyên Thủy Tinh ấy, La Phong chẳng may phải đối mặt với các thế lực dị tộc mạnh mẽ như Cơ Giới tộc, Yêu tộc, côn trùng tộc. Ba tộc ấy liên minh lại với nhau và cả 6000 gã tôn giả trong vũ trụ, tất cả đều đứng về một phe để chống lại La Phong. Tuy nhiên, sự liều lĩnh của các dị tộc ấy đã phải trả một cái giá rất đắt, bởi người mà họ đối đầu chính là La Phong, không hề dễ dàng đối phó chút nào. Trí tuệ, sức mạnh, La Phong đều có, cùng với một thanh đao sáng ngời trên tay và sức mạnh của Ngã Vi Vũ Trụ, La Phong một mình đã cân hết tất cả, tạo ra một trận chiến đáng nhớ về sau, một trận đánh đã bảo vệ sự tôn quý và danh dự của nhân loại, khẳng định vị thế trên vũ trụ rộng lớn này.</p>', 'Full', 1, 'hoathinh', 'completed', 21, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhao Qianjing","avatar":""},{"name":"Wen Liu","avatar":""},{"name":"Lei Wu","avatar":""},{"name":"Chang Xu","avatar":""},{"name":"Zhang Lei","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c892