INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lop-hoc-cua-tae-ri', 'Lớp Học Của Tae Ri', 'Curtain Up, Class!', 'https://phimimg.com/upload/vod/20260309-1/616597d9e87019a72fe6aa71d9a69d15.jpg', 'https://phimimg.com/upload/vod/20260309-1/37f25717bf68f8dbe17fe60f8225d06f.jpg', '<p>Trường tiểu học thôn quê bỗng trở nên rộn ràng với lớp học kịch nghệ giảng dạy bởi cô giáo mới vào nghề Kim Tae Ri cùng trợ giảng Choi Hyun Wook và ca sĩ Kangnam. Khi sân khấu dần trở nên sống động, những thay đổi nhỏ bắt đầu lan tỏa ra ngoài phạm vi lớp học.</p>', 'Hoàn Tất (10/10)', 10, 'tvshows', 'completed', 22, 2026, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Tae-ri","avatar":""},{"name":"Choi Hyun-wook","avatar":""},{"name":"Kangnam","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Banggwahu Yeongeukban","After School Teacher Tae-ri","After School Theater Club","방과후 태리쌤"]', 1784690324123);
