INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-ho-trong-sinh-so-kieu-truyen-2', 'Băng Hồ Trọng Sinh (Sở Kiều Truyện 2)', 'Rebirth', 'https://phimimg.com/upload/vod/20260408-1/ae14f7758a769790000d14f01e84aa5f.jpg', 'https://phimimg.com/upload/vod/20260408-1/8ac546753f16b7e2ff322ed6bc3fe8a3.jpg', '<p>Trong trận chiến trên hồ băng, Gia Cát Nguyệt (Lý Quân Nhuệ) và Sở Kiều (Hoàng Dương Điền Điềm) cùng rơi xuống hồ nước giá lạnh. Sở Kiều được Yến Tuân (Trương Khang Lạc) cứu sống. Nhưng khi hay tin Gia Cát Nguyệt đã tử nạn, nàng bèn tìm mọi cơ hội để trả thù Yến Tuân. Tại Biện Đường, Sở Kiều nhiều lần nhận được sự trợ giúp từ một người bí ẩn. Cảm giác quen thuộc khó tả khiến nàng không khỏi nghi ngờ rằng Gia Cát Nguyệt vẫn còn sống. Trong khi đó, Yến Tuân ngày càng trở nên tàn bạo, khơi mào loạn lạc khắp bốn phương. Cuối cùng, liệu Sở Kiều có thể bình định thiên hạ, khiến Yến Tuân lầm đường lạc lối biết quay đầu là bờ? Liệu nàng có thể một lần nữa kề vai sát cánh cùng Gia Cát Nguyệt, trả lại mái ấm bình yên cho bách tính?</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 22, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Quân Nhuệ","avatar":""},{"name":"Hoàng Dương Điền Điềm","avatar":""},{"name":"Trương Khang Lạc","avatar":""},{"name":"Hạ Mộng","avatar":""},{"name":"Lý Hiếu Khiêm","avatar":""},{"name":"Lý Mộng","avatar":""},{"name":"Thịnh Nhất Luân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["楚乔: 冰湖重生","11處特工皇妃","Frozen Awakening","楚乔传2","Bing Hu Chong Sheng","冰湖重生"]', 1784690324123);
