INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mo-tu-tu-bach-nhat-de-dang', 'Mộ Tư Từ (Bạch Nhật Đề Đăng)', 'Love Beyond The Grave', 'https://phimimg.com/upload/vod/20260329-1/d86f8a6861ade21ad623082454d939b0.jpg', 'https://phimimg.com/upload/vod/20260329-1/07efc63f356411a39d21aa4c2b0d9f43.jpg', '<p>Quỷ vương Hạ Tư Mộ thiên phú xuất chúng tình cờ gặp gỡ tiểu tướng quân Đoàn Tư trong lúc nghỉ ngơi kiếm mồi. Vị tiểu tướng quân mang theo tín vật của cố nhân này dường như lại không phải Đoàn Tư thực sự? Hai người dò xét lẫn nhau, cuối cùng Hạ Tư Mộ cũng biết được quá khứ đen tối cùng chí hướng trong lòng Đoàn Tư, còn Đoàn Tư cũng phát hiện ra sự kiên định và nỗi cô đơn của Hạ Tư Mộ. Một người phàm tuổi thọ chẳng quá trăm năm và một ác quỷ bốn trăm tuổi vẫn mang hình hài thiếu nữ, dùng tình yêu chống lại dòng chảy thời gian.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 21, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Địch Lệ Nhiệt Ba","avatar":""},{"name":"Trần Phi Vũ","avatar":""},{"name":"Ngụy Triết Minh","avatar":""},{"name":"Trương Lệ","avatar":""},{"name":"Cao Hàn","avatar":""},{"name":"Dương Hật Tử","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["白日提灯​"]', 1784690324123);
