INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chatha-pacha-chiec-nhan-cua-rowdies', 'Chatha Pacha Chiếc nhẫn của Rowdies', 'Chatha Pacha: The Ring of Rowdies', 'https://phimimg.com/upload/vod/20260312-1/8ce1a3796d8a2ba938137fa74e2814cd.jpg', 'https://phimimg.com/upload/vod/20260312-1/207bfe8920a85ee89a4e25bd341b84f0.jpg', '<p>Tại trung tâm Fort Kochi, ba anh em và nhóm bạn lập dị của họ vô tình lạc vào thế giới hoang dã của đấu vật hóa trang kiểu WWE. Những gì bắt đầu như một trò kiếm tiền nhỏ lẻ nhanh chóng bùng nổ thành một cuộc hỗn loạn với những chiếc mặt nạ, cái tôi và sự điên cuồng tột độ, tất cả diễn ra trong bối cảnh một thành phố không bao giờ tuân theo luật lệ. Nhưng liệu tình anh em của họ có thể tồn tại khi cuộc chiến thực sự bắt đầu bên ngoài võ đài?</p>', 'Full', 1, 'single', 'completed', 19, 2026, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Arjun Ashokan","avatar":""},{"name":"Roshan Mathew","avatar":""},{"name":"Vishak Nair","avatar":""},{"name":"Ishan Shoukath","avatar":""},{"name":"Carmen S Mathew","avatar":""},{"name":"Mammootty","avatar":""},{"name":"Siddique","avatar":""},{"name":"Raffi","avatar":""},{"name":"Saikumar","avatar":""},{"name":"Khalid Al Ameri","avatar":""},{"name":"Lakshmi Menon","avatar":""},{"name":"Muthumani Somasundaran","avatar":""},{"name":"Thezni Khan","avatar":""},{"name":"Dartagnan Sabu","avatar":""},{"name":"Vyshnav Biju","avatar":""},{"name":"Krishnan Nambiar","avatar":""},{"name":"Minon John","avatar":""},{"name":"Zarin Shihab","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Chatha Pacha","สังเวียนนี้ต้องทุ่ม","ചത്താ പച്ച: The Ring of Rowdies"]', 1784690324123);
