INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-nhan-phan-1', 'Tù Nhân (Phần 1)', 'Prisoner (Season 1)', 'https://phimimg.com/upload/vod/20260503-1/38f5167f00621a25406dae4bddd4819e.jpg', 'https://phimimg.com/upload/vod/20260503-1/b7b3ef0effb5cbf2a289204c7032551b.jpg', '<p>Một nữ nhân viên áp giải tù nhân trẻ tuổi được giao nhiệm vụ đưa một phạm nhân nguy hiểm đi làm chứng chống lại tổ chức tội phạm của hắn. Trong hành trình đó, đoàn xe bị phục kích, và hai người trở thành những người sống sót duy nhất — bị còng tay với nhau và buộc phải hợp tác để sống sót.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 18, 2026, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Tahar Rahim","avatar":""},{"name":"Izuka Hoyle","avatar":""},{"name":"Leonie Benesch","avatar":""},{"name":"Finn Bennett","avatar":""},{"name":"Laurie Davidson","avatar":""},{"name":"Ken Nwosu","avatar":""},{"name":"Sam Troughton","avatar":""},{"name":"Kitty Reed","avatar":""},{"name":"Daniel Betts","avatar":""},{"name":"Selorm Adonu","avatar":""},{"name":"Brían F. O''Byrne","avatar":""},{"name":"Catherine McCormack","avatar":""},{"name":"Eddie Marsan","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Prisoner.2026","Prisoner"]', 1784690324123);
