INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-ngam-2026', 'Bẫy Ngầm', 'Misdirection', 'https://phimimg.com/upload/vod/20260503-1/1c1a749bc2452d1d53d547a4f225d292.jpg', 'https://phimimg.com/upload/vod/20260503-1/5938a61ca29ba3866a885f5880f884cf.jpg', '<p>Một cặp đôi túng quẫn, vì món nợ khổng lồ với băng mafia, đã chọn con đường liều mạng: đột nhập vào những ngôi nhà sang trọng, đánh cắp tài sản để gom tiền trả nợ. Mọi thứ tưởng chừng nằm trong tầm kiểm soát cho đến khi họ chọn sai mục tiêu. Ngôi nhà mới này không chỉ có của cải — mà còn ẩn chứa một thế lực nào đó đang chờ sẵn.
 Khi màn đêm buông xuống, kế hoạch trơn tru của họ nhanh chóng biến thành cơn ác mộng. Từng bước, những kẻ săn mồi bỗng trở thành con mồi trong trò chơi rượt đuổi chết chóc. Không còn đường lui, họ buộc phải tìm cách sống sót giữa mê cung bẫy rập, nơi mỗi tiếng động đều có thể là tín hiệu cho một cái chết đang tiến đến rất gần.</p>', 'Full', 1, 'single', 'completed', 6, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Olga Kurylenko","avatar":""},{"name":"Frank Grillo","avatar":""},{"name":"Oliver Trevena","avatar":""},{"name":"Landa Morland","avatar":""},{"name":"Vladislav Lapidus","avatar":""},{"name":"Lacy McClory","avatar":""},{"name":"Emilija Matić","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Misdirection - Rache sitzt tief","Dezorientare","Misdirection"]', 1784690324123);
