INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-ruc-ro-cua-em-mua-em-ruc-ro', 'Mùa Rực Rỡ Của Em (Mùa Em Rực Rỡ)', 'In Your Radiant Season', 'https://phimimg.com/upload/vod/20260223-1/62667ee973537d0636ed2105c1d16dcc.jpg', 'https://phimimg.com/upload/vod/20260223-1/8a44c515d71551459012656dfccf6e31.jpg', '<p>Chan sống mỗi ngày như thể đó là kỳ nghỉ hè. Haran thì lại bị mắc kẹt trong một mùa đông cô đơn. Khi quá khứ bị lãng quên đưa họ gặp lại nhau, Chan quyết tâm tặng cô một mùa xuân khác. Qua những tiếng cười và nước mắt, họ cùng nhau đối mặt với mùa đông và tìm thấy mùa xuân của mình trong câu chuyện tình lãng mạn ấm áp này.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 33, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Sung-kyung","avatar":""},{"name":"Chae Jong-hyeop","avatar":""},{"name":"Han Ji-hyeon","avatar":""},{"name":"Oh Ye-ju","avatar":""},{"name":"Lee Mi-sook","avatar":""},{"name":"Kang Seok-woo","avatar":""},{"name":"Kwon Hyuk","avatar":""},{"name":"Jung Hae-kyun","avatar":""},{"name":"Kang Ae-sim","avatar":""},{"name":"Ki Hyun-woo","avatar":""},{"name":"Lee Seung-yeon","avatar":""},{"name":"Yun Chae-bin","avatar":""},{"name":"Kim Tae-Young","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Challanhan Neoui Gyejeore","موسمك المشرق","In Your Brilliant Season","In Your Radiant Season","찬란한 너의 계절에"]', 1784690324123);
