INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luat-su-bong-ma-van-phong-luat-su-shin-i-rang', 'Luật Sư Bóng Ma (Văn Phòng Luật Sư Shin I Rang)', 'Phantom Lawyer', 'https://phimimg.com/upload/vod/20260314-1/8d048e1956a9a918f4c58ce087d00105.jpg', 'https://phimimg.com/upload/vod/20260314-1/3c0e3fe8e9dcfacb2ac5ff882a3b6af9.jpg', '<p>Bộ phim xoay quanh Shin Yi Rang (Yoo Yeon Seok), một luật sư bất ngờ có khả năng nhìn thấy hồn ma sau khi chuyển văn phòng đến nơi từng là nhà của một pháp sư. Những linh hồn mang theo uẩn khúc chưa được giải quyết tìm đến anh để nhờ giúp đỡ, buộc Yi Rang phải hóa thân, sống lại ký ức của họ nhằm tìm manh mối cho các vụ án. Đồng hành cùng anh là Han Na Hyun (Esom), nữ luật...Xem thêm</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 30, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yoo Yeon-seok","avatar":""},{"name":"Esom","avatar":""},{"name":"Jun Suk-ho","avatar":""},{"name":"Kim Kyung-nam","avatar":""},{"name":"Choi Gwang-il","avatar":""},{"name":"Kim Mi-kyeong","avatar":""},{"name":"Son Yeo-eun","avatar":""},{"name":"Jung Seung-kil","avatar":""},{"name":"Yeon Je-hyung","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sin-i-rang Beom-nyul-sa-mu-so","Shinyirang Beobryulsamuso","Defensores de Fantasmas","神與律師事務所","God and the Law Firm","Shin I-rang Law Office","Văn Phòng Luật Sư Shin Rang","신이랑 법률사무소"]', 1784690324123);
