INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('luat-su-bong-ma-van-phong-luat-su-shin-i-rang', 'Luật Sư Bóng Ma (Văn Phòng Luật Sư Shin I Rang)', 'Phantom Lawyer', 'luật sư bóng ma (văn phòng luật sư shin i rang) phantom lawyer yoo yeon-seok esom jun suk-ho kim kyung-nam choi gwang-il kim mi-kyeong son yeo-eun jung seung-kil yeon je-hyung sin-i-rang beom-nyul-sa-mu-so shinyirang beobryulsamuso defensores de fantasmas 神與律師事務所 god and the law firm shin i-rang law office văn phòng luật sư shin rang 신이랑 법률사무소', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duoi-bong-dien-ha', 'Dưới Bóng Điện Hạ', 'The King''s Warden', 'https://phimimg.com/upload/vod/20260502-1/ed80c975a15230cf01aa24c0ed34960a.jpg', 'https://phimimg.com/upload/vod/20260502-1/e8a82c3de8a8c2c08a0c4b3eaa91fb78.jpg', '<p>Lấy mốc năm 1457 dưới triều đại Joseon, Dưới Bóng Điện Hạ khắc họa số phận nghiệt ngã của vua Danjong - vị quân vương thứ sáu của triều đại (Park Ji-hoon thủ vai). Lên ngôi khi tuổi đời còn non trẻ, Danjong nhanh chóng trở thành quân cờ trong vòng xoáy quyền lực tàn khốc. Bị chính người chú lật đổ, phế truất và đày đến vùng Cheongnyeongpo heo hút, cuộc đời của vị vua trẻ rẽ sang một ngã rẽ đầy u uất. Tại chốn lưu đày, ông gặp trưởng làng Eom Heung Do (Yoo Hai-jin thủ vai) - người đã chủ động biến ngôi làng nghèo thành nơi giam giữ nhà vua, đổi lại hy vọng cứu vãn sinh kế cho dân làng. Từ hai thân phận tưởng chừng đối lập, một cựu đế vương và một thường dân, bộ phim dần hé mở mối liên kết lặng lẽ nhưng sâu sắc - nơi lòng trung thành, sự che chở âm thầm và những phận người nhỏ bé cùng trôi dạt giữa cơn sóng lớn của lịch sử.</p>', 'Full', 1, 'single', 'completed', 45, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 1, '[{"name":"Yoo Hai-jin","avatar":""},{"name":"Park Ji-hoon","avatar":""},{"name":"Yoo Ji-tae","avatar":""},{"name":"Jeon Mi-do","avatar":""},{"name":"Kim Min","avatar":""},{"name":"Park Ji-hwan","avatar":""},{"name":"Lee Jun-hyuk","avatar":""},{"name":"Ahn Jae-hong","avatar":""},{"name":"Lee Jun-hyeok","avatar":""},{"name":"Kim Soo-jin","avatar":""},{"name":"Oh Dal-su","avatar":""},{"name":"Park Ji-yun","avatar":""},{"name":"Baek Do-kyeom","avatar":""},{"name":"Jeong Jin-woon","avatar":""},{"name":"Kim Yong-seok","avatar":""},{"name":"No Kyung","avatar":""},{"name":"Yang Seung-lee","avatar":""},{"name":"Han Jong-hoon","avatar":""},{"name":"Jang Hyun-sung","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["与王生活的男人","ดันจง ราชันย์นักโทษแห่งชอนยอนโพ","왕과 사는 남자"]', 1784690324123);
