INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ten-toi-la-agneta', 'Tên tôi là Agneta', 'Je m''appelle Agneta', 'https://phimimg.com/upload/vod/20260502-1/a5e4af06d877ff3d2898d6f75f762566.jpg', 'https://phimimg.com/upload/vod/20260502-1/7ff627a598c681b800510b35fdd220ca.jpg', '<p>Vừa mất việc và khao khát một khởi đầu mới, Agneta nhận việc trông trẻ ở Provence. Nhưng công việc này lại trở thành một cuộc trốn thoát đầy tận hưởng... và một sự thức tỉnh bất ngờ.</p>', 'Full', 1, 'single', 'completed', 27, 2026, 'Vietsub', 'FHD', 'Thụy Điển', 0, '[{"name":"Eva Melander","avatar":""},{"name":"Claes Månsson","avatar":""},{"name":"Jérémie Covillault","avatar":""},{"name":"Anne-Marie Ponsot","avatar":""},{"name":"Björn Kjellman","avatar":""},{"name":"Matilda Ekström","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["My Name Is Agneta","Bonjour Agneta","Je m''appelle Agneta"]', 1784690324123);
