INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ten-toi-la-agneta', 'Tên tôi là Agneta', 'Je m''appelle Agneta', 'tên tôi là agneta je m''appelle agneta eva melander claes månsson jérémie covillault anne-marie ponsot björn kjellman matilda ekström my name is agneta bonjour agneta je m''appelle agneta', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-thuyet-tho-san-nui-truong-bach-2', 'Truyền Thuyết Thợ Săn Núi Trường Bạch 2', 'Legend of the Changbai Mountain Hunter 2', 'https://phimimg.com/upload/vod/20260502-1/33a0762481db220702795e2d06e3a600.jpg', 'https://phimimg.com/upload/vod/20260502-1/7bd77470c8e701698b0ec90e960537b1.jpg', '<p>Cuối thời dân quốc, những chuyện kỳ quặc xảy ra liên tục ở ngôi làng bao phủ trong sương mù sâu trong núi Trường Bạch. Anh chàng dân làng tên Trần Cẩu Tử tình cờ gặp một cô dâu bí ẩn và cưu mang cô. Từ đó số phận anh chuyển biến đột ngột: làm giàu nhanh chóng rồi lại bạo bệnh qua đời một cách kỳ lạ. Những cái chết liên hoàn khiến cả làng chìm trong khiếp sợ. Ông thợ săn già Mã Tam gia dẫn mọi người truy tìm sự thật, khám phá câu đố giữa những tin đồn ma quái và lòng người khó đoán. Những bí mật cùng tranh chấp thiện ác trong sâu thẳm núi rừng đang dần lộ diện.</p>', 'Full', 1, 'single', 'completed', 9, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yue Dongfeng","avatar":""},{"name":"Wang Shuangbao","avatar":""},{"name":"An Jianlin","avatar":""},{"name":"Yue Xunyu","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["长白山猎人传说2"]', 1784690324123);
