INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-la-ke-nam-vung', 'Tôi Là Kẻ Nằm Vùng', 'I''m Undercover', 'https://phimimg.com/upload/vod/20260502-1/f2dc8adad8f554afba0e3e74f4553694.jpg', 'https://phimimg.com/upload/vod/20260502-1/ad4f5390cb04cb538f3fde6627366463.jpg', '<p>Để giải quyết một vụ án gián điệp kéo dài nhiều năm, cựu cảnh sát trưởng Tư Đồ Cường cử cảnh sát hình sự Hoắc Đào, người đang rất cần tiền chữa bệnh cho con gái, thâm nhập vào một băng đảng tội phạm. Hoắc Đào giả dạng là kẻ móc túi để lấy lòng tin của thủ lĩnh băng đảng ông Bối. Trong quá trình đó, anh quen biết với tên trộm Tiểu Phi. Hoắc Đào phối hợp với kế hoạch của cảnh sát, tình cờ phát hiện ra ông Bối cấu kết với người khác đánh cắp bí mật thương mại. Cuối cùng, Hoắc Đào hợp tác với cảnh sát bắt giữ tất cả tội phạm, hoàn thành tâm nguyện của Tư Đồ Cường.</p>', 'Full', 1, 'single', 'completed', 9, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Collin Chou","avatar":""},{"name":"Yu Rongguang","avatar":""},{"name":"Li Yankui","avatar":""},{"name":"Wen Dongjun","avatar":""},{"name":"Zhang Shasha","avatar":""},{"name":"Wang Tao","avatar":""},{"name":"Wang Boqing","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["I.m.Undercover","我是卧底"]', 1784690324123);
