INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-cam-lang-ac-mong-trong-suong', 'Đồi Câm Lặng: Ác Mộng Trong Sương', 'Return To Silent Hill', 'https://phimimg.com/upload/vod/20260225-1/fa407ab97f1b404c46cb558d6e2c272b.jpg', 'https://phimimg.com/upload/vod/20260225-1/dbac0f3d8cdf9b2c5fdcde1fc9452659.jpg', '<p>Khi James nhận được một bức thư bí ẩn từ Mary — người yêu đã mất của mình — anh bị kéo trở lại Silent Hill, thị trấn quen thuộc một thời nay đã chìm trong bóng tối. Trong hành trình tìm kiếm cô, James phải đối mặt với những sinh vật quái dị và dần hé lộ một sự thật kinh hoàng, thứ sẽ đẩy anh đến bờ vực của sự tỉnh táo.</p>', 'Full', 1, 'single', 'completed', 33, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Jeremy Irvine","avatar":""},{"name":"Hannah Emily Anderson","avatar":""},{"name":"Evie Templeton","avatar":""},{"name":"Pearse Egan","avatar":""},{"name":"Nicola Alexis","avatar":""},{"name":"Robert Strange","avatar":""},{"name":"Emily Carding","avatar":""},{"name":"Eve Macklin","avatar":""},{"name":"Lara Duru","avatar":""},{"name":"Karya Duru","avatar":""},{"name":"Alana Maria","avatar":""},{"name":"Howard Saddler","avatar":""},{"name":"Martine Richards","avatar":""},{"name":"Matteo Pasquini","avatar":""},{"name":"Melissa Graham","avatar":""},{"name":"Rhiannon Moushall","avatar":""},{"name":"Slaviša","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Room 318","Retour a Silent Hill","Сайлент Гілл. Повернення","Povratak u Sajlent Hil","Silent Hill - Visszatérés","Silent Hill: Noční můry","Terror En Silent Hill Regreso Al Infierno","Vrnitev v Silent Hill","Atgriešanās Klusajā kalnā","Silent Hill: Nočné mory","重返沉