INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doi-cam-lang-ac-mong-trong-suong', 'Đồi Câm Lặng: Ác Mộng Trong Sương', 'Return To Silent Hill', 'đồi câm lặng: ác mộng trong sương return to silent hill jeremy irvine hannah emily anderson evie templeton pearse egan nicola alexis robert strange emily carding eve macklin lara duru karya duru alana maria howard saddler martine richards matteo pasquini melissa graham rhiannon moushall slaviša room 318 retour a silent hill сайлент гілл. повернення povratak u sajlent hil silent hill - visszatérés silent hill: noční můry terror en silent hill regreso al infierno vrnitev v silent hill atgriešanās klusajā kalnā silent hill: nočné mory 重返沉默之丘 povratak u silent hill возвращение в сайлент хилл silent hill: întoarcerea în iad trở về ngọn đồi câm lặng დაბრუნება silent hill-ში return to silent hill リターン・トゥ・サイレントヒル', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-anh-truy-tung', 'Điệp Ảnh Truy Tung', 'In The Name Of The Father', 'https://phimimg.com/upload/vod/20260502-1/1a0f97fa422df6bbc0b279b4b5841fb2.jpg', 'https://phimimg.com/upload/vod/20260502-1/c1e692279aed302dcce0bee4b3e2e17d.jpg', '<p>Ba năm trước, cảnh sát chống ma túy Đại Kỳ mất đồng đội trong một hành động gián điệp. Anh lòng đầy tự trách và ở ẩn tại một thị trấn nhỏ ở Nam Quốc, âm thầm che chở và bảo vệ con gái đồng đội là Tiểu Điệp. Tiểu Điệp rất tò mò về người hàng xóm trầm lặng này nhưng cuộc sống của cô bé bỗng chốc thay đổi khi bị bắt cóc. Tinh thần cảnh sát bị chôn vùi của Đại Kỳ lại thức tỉnh. Anh một mình bước vào cuộc đuổi truy sinh tử. Liệu con đường giải cứu này có giúp anh giữ được lời hứa với đồng đội không?</p>', 'Full', 1, 'single', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Y Dương","avatar":""},{"name":"Lý Lạc Y","avatar":""},{"name":"Đặng Trường Thành","avatar":""},{"name":"Đường Văn Đình","avatar":""},{"name":"Cảnh Thiên","avatar":""},{"name":"Trương Khôn","avatar":""},{"name":"Tôn Chinh Vũ","avatar":""},{"name":"Dương Hiểu Ba","avatar":""},{"name":"Trương Hỏa Hỏa","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["蝶影追踪"]', 1784690324123);
