INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-quyen-privileges', 'Đặc Quyền (Privilèges)', 'Privileges', 'https://phimimg.com/upload/vod/20260413-1/8f7cf5800322a3d63ea07bd55f28df93.jpg', 'https://phimimg.com/upload/vod/20260413-1/8bd5b21dd6259f7524e4931a9d34d557.jpg', '<p>Với hy vọng mong manh về một cơ hội cuối cùng để chuộc lại lỗi lầm, một thanh niên vừa ra tù đã chấp nhận công việc bên trong một khách sạn sang trọng tại Paris. Tuy nhiên, đằng sau vẻ hào nhoáng của nơi này là một thế giới đầy rẫy những tham vọng tàn khốc và sự phản bội. Anh sớm nhận ra rằng việc tìm kiếm sự cứu rỗi giữa những cạm bẫy tinh vi và những cuộc đấu đá ngầm của giới thượng lưu còn khó khăn hơn nhiều so với cuộc sống phía sau song sắt.</p>', 'Tập 6', 6, 'series', 'ongoing', 21, 2026, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Manon Bresch","avatar":""},{"name":"Melvil Poupaud","avatar":""},{"name":"Nina Zem","avatar":""},{"name":"Anne Azoulay","avatar":""},{"name":"Zar Amir Ebrahimi","avatar":""},{"name":"Sandor Funtek","avatar":""},{"name":"Joseph Olivennes","avatar":""},{"name":"Stephanie Atala","avatar":""},{"name":"Lili Aubry","avatar":""},{"name":"Nadia Benzakour","avatar":""},{"name":"Paula Puro","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Privilèges"]', 1784690324123);
