INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dac-quyen-privileges', 'Đặc Quyền (Privilèges)', 'Privileges', 'đặc quyền (privilèges) privileges manon bresch melvil poupaud nina zem anne azoulay zar amir ebrahimi sandor funtek joseph olivennes stephanie atala lili aubry nadia benzakour paula puro privilèges', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-ky-dieu-dong-bac', 'Câu Chuyện Kỳ Diệu Đông Bắc', 'Northeast Mysteries', 'https://phimimg.com/upload/vod/20260502-1/2f835866893f59913c9c2089a87e4b07.jpg', 'https://phimimg.com/upload/vod/20260502-1/55864fd603ad84ddfc09e67e14e69785.jpg', '<p>Sinh viên khoa Triết học Tiếu Mặc đến nhà tang lễ thực tập, cố gắng tìm lời giải đáp cho câu hỏi &quot;sinh tử&quot;, thì bất ngờ gặp phải cái chết ly kỳ của người hướng dẫn Trần Huy. Trong làng lưu truyền rằng một chiếc &quot;giếng vọng tiếng&quot; có thể khiến người chết sống lại. Sau khi con trai của Trần Huy qua đời trong một vụ tai nạn, Trần Huy đã cầu nguyện bên giếng cổ và ngày hôm sau anh liền mất tích một cách kỳ lạ. Tiếu Mặc cùng nhân viên tang lễ bí ẩn là Lão Bạch Đầu quay về làng điều tra. Lão Bạch Đầu dùng khoa học lần lượt giải mã những hiện tượng &quot;kỳ bí&quot;: xác chết dưới giếng, con gái nuôi thắt cổ tự tử, bức tường ma quái trong màn sương dày đặc... tất cả những chuyện quái đản này thực chất là những màn lừa bịp được sắp đặt tinh vi. Khi nỗi ám ảnh gặp phải khoa học, những lời nói dối bị sự thật vạch trần, mọi người mới nhận ra vực thẳm thực sự không nằm trong giếng, mà nằm ở trái tim con người.</p>', 'Full', 1, 'single', 'completed', 9, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Tuyết Hàm","avatar":""},{"name":"Phùng Tiêu Đồng","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["东北奇妙物语","东北奇妙故事"]', 1784690324123);
