INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giao-long-long-khau', 'Giao Long Long Khẩu', 'The Jiaolong of Longkou', 'https://phimimg.com/upload/vod/20260501-1/cee4ae1f9163be4890b9c84a6812f79f.jpg', 'https://phimimg.com/upload/vod/20260501-1/4e98e5a5dc8eaa778f5b1f031a90f9ba.jpg', '<p>Cả thị trấn đang chờ &quot;thuồng luồng&quot; hóa rồng, nào biết có kẻ đang chờ để hiến tế! Mưa như trút suốt bảy ngày, cái chết kỳ lạ nối tiếp nhau... Đạo sĩ Trương Bất Bình xông vào trấn Long Khẩu, phát hiện trên người mỗi nạn nhân đều có một &quot;dấu móng rồng rơi&quot; không nên có. Là điềm báo ngàn năm ứng nghiệm, hay một vụ án hoàn hảo mượn thần để giết người?</p>', 'Full', 1, 'single', 'completed', 21, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yuan Fufu","avatar":""},{"name":"Huang Yuntong","avatar":""},{"name":"Xu Wenguang","avatar":""},{"name":"Liang Chao","avatar":""},{"name":"Qian Yi","avatar":""},{"name":"Li Sibo","avatar":""},{"name":"Bai Haitao","avatar":""},{"name":"Wang Weicheng","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["The Dragon of Longkou","龙口走蛟"]', 1784690324124);
