INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-troi-dresden', 'Mặt trời Dresden', 'The Dresden Sun', 'https://phimimg.com/upload/vod/20260318-1/1bad79c07cb0eecc0c090c9bdd03f242.jpg', 'https://phimimg.com/upload/vod/20260318-1/ffba0de68c8e815349fc4f163ec55282.jpg', '<p>Một lính đánh thuê tài giỏi, có nguyên tắc với quá khứ đầy tổn thương hợp tác với một người nội bộ để đánh cắp một tài sản quý giá từ Tập đoàn Peredor có tên là “quả cầu”. Tập đoàn C &amp; Earth, đang tranh giành quyền thống trị toàn cầu, tìm cách giải quyết một công nghệ ngoài hành tinh thông qua dự án của một nhà khoa học. Trong khi đó, một nhà phân tích tài chính, người căm ghét công việc của mình tại công ty đầu tư quyền lực Mutual One, thấy mình bị cuốn vào giữa các đối thủ doanh nghiệp nguy hiểm, gian lận tài chính và gián điệp công nghệ, và cuối cùng buộc phải chạy trốn khỏi một nhà thầu quân sự mắc chứng rối loạn tâm thần.</p>', 'Full', 1, 'single', 'completed', 14, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Christina Ricci","avatar":""},{"name":"Mena Suvari","avatar":""},{"name":"Linus Roache","avatar":""},{"name":"Steven Ogg","avatar":""},{"name":"Leigh McCloskey","avatar":""},{"name":"Angel Manuel","avatar":""},{"name":"Samantha Win","avatar":""},{"name":"Brett Rickaby","avatar":""},{"name":"Aaron Craven","avatar":""},{"name":"Richard Blackmon","avatar":""},{"name":"Anne Marie Howard","avatar":""},{"name":"Chelsea London Lloyd","avatar":""},{"name":"Krystle Martin","avatar":""},{"name":"Terry Maratos","avatar":""},{"name":"Blair Brienza","avatar":""},{"name":"Ethan Howlett","avatar":""},{"name":"Richa","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f008490