INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-de', 'Nữ Đế', 'Ascent Of An Empress', 'https://phimimg.com/upload/vod/20260428-1/54757218dba83681349309b9de271df9.jpg', 'https://phimimg.com/upload/vod/20260428-1/e7dd30f0672297a3e05cdbe0d0e5939a.jpg', '<p>Trong một triều đại mà những người có thiên bẩm vừa nắm giữ quyền năng vừa bị đàn áp, Kỷ Minh Nguyệt bị ép vào vị trí nữ đế khi những căng thẳng chính trị gia tăng. Sát cánh cùng Hách Liên Cẩn — một thành viên thuộc bộ tộc nô lệ, nàng phải chèo lái giữa những liên minh không ngừng thay đổi, sự phản bội và chiến tranh. Cùng nhau, họ đứng lên chống lại những quan lại tham nhũng và cuối cùng thách thức hoàng đế để định hình lại tương lai của đế chế.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 21, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Mã Văn Viễn","avatar":""},{"name":"Thiên Ái","avatar":""},{"name":"Quách Giai Lạc","avatar":""},{"name":"Lưu Tuấn Phong","avatar":""},{"name":"Chu Tiếu Nhất","avatar":""},{"name":"Dương Kiều Ngữ","avatar":""},{"name":"Ngô Hải Đường","avatar":""},{"name":"Phương Suất","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Nv Di","女帝"]', 1784690324124);
