INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nu-de', 'Nữ Đế', 'Ascent Of An Empress', 'nữ đế ascent of an empress mã văn viễn thiên ái quách giai lạc lưu tuấn phong chu tiếu nhất dương kiều ngữ ngô hải đường phương suất nv di 女帝', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cu-the-ma-gap-em', 'Cứ Thế Mà Gặp Em', 'Just To Meet You', 'https://phimimg.com/upload/vod/20260420-1/313f257d8576d976e187c613d50fd3dc.jpg', 'https://phimimg.com/upload/vod/20260420-1/30b6b83ad83afa5bee137f4b8f2a5cfd.jpg', '<p>Góa phụ ba đời chồng nay tái giá với Diệp Lãng, cậu con riêng của tỷ phú. Cô cứ ngỡ mình tự dưng vớ được một chàng trai trẻ si tình, dịu dàng, nào ngờ lại rơi vào cái bẫy do một người trọng sinh giăng sẵn! Kiếp trước, Diệp Lãng vì nặng tình mà phải chết trong lễ cưới. Sau khi sống lại, anh thề sẽ trả thù, thế nhưng cuối cùng vẫn một lần nữa chìm đắm trong chiếc bẫy dịu dàng của cô. Giữa vòng xoáy yêu hận đan xen, những bí ẩn dần được phơi bày. Sau màn sương mù ấy, hóa ra còn có một người trọng sinh khác đang âm thầm thao túng tất cả.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 13, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cao Dung Phương","avatar":""},{"name":"Trương Cảnh Vân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["偏偏遇见你"]', 1784690324124);
