INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-nhuyen-dich-than', 'Tâm Nhuyễn Đích Thần', 'Soft-Hearted God', 'https://phimimg.com/upload/vod/20260430-1/b1fdab2299e8e2534a4a935db4245c7a.jpg', 'https://phimimg.com/upload/vod/20260430-1/8bee02fee00e42553f4652b85324c7aa.jpg', '<p>Vị ác thần cao ngạo Diệp Chiêu vì yêu mà chấp nhận sa chân vào chốn hồng trần, trong khi đế cơ của vương quốc là Sở Hy Hòa lại mang trong mình bí mật về kiếp sống song sinh. Giữa biển hận tình thù, cả hai đã có những màn đối đầu kịch liệt giữa hai tâm hồn mạnh mẽ. Trải qua trăm năm luân hồi, từ cái nhìn đầu tiên đầy rung động đến nỗi hận thấu xương tủy, cuộc cá cược tình yêu thuần khiết này sẽ dần hé mở sự thật tàn khốc giữa sự si mê của thần và người, cũng như trách nhiệm nặng nề với đại nghĩa quốc gia.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 17, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Nghiêm Tử Hiền","avatar":""},{"name":"Ô Nhật Lệ Cách","avatar":""},{"name":"Quách Hinh Ngọc","avatar":""},{"name":"Vu Dương","avatar":""},{"name":"Thư Á Tín","avatar":""},{"name":"Khôi Nguyên","avatar":""},{"name":"Chung Tinh Huy","avatar":""},{"name":"Lôi Thụ","avatar":""},{"name":"Vương Nghệ Bác","avatar":""},{"name":"Quyền Duệ","avatar":""},{"name":"Vương Tinh Khải","avatar":""},{"name":"Mạnh Lộ Minh","avatar":""},{"name":"Tôn Dực Đằng","avatar":""},{"name":"Uông Điềm Nhĩ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["心软的神"]', 1784690324124);
