INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-phu-nu-khong-hoan-hao', 'Những Người Phụ Nữ Không Hoàn Hảo', 'Imperfect Women', 'https://phimimg.com/upload/vod/20260329-1/06d5968801e967c96db7b93be3523629.jpg', 'https://phimimg.com/upload/vod/20260329-1/a13610f28bff9ad0e0094dda8628eb5f.jpg', '<p>Sau một vụ giết người làm tan nát cuộc sống của ba người bạn, tình bạn kéo dài hàng chục năm của họ bị đẩy đến giới hạn khi cuộc điều tra dần hé lộ những sự thật gây chấn động.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 13, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Elisabeth Moss","avatar":""},{"name":"Kerry Washington","avatar":""},{"name":"Kate Mara","avatar":""},{"name":"Joel Kinnaman","avatar":""},{"name":"Corey Stoll","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["不完美的女人","נשים לא מושלמות","Imperfect Women"]', 1784690324124);
