INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-boonie-phan-4', 'Biệt Đội Boonie (Phần 4)', 'Boonie Squad (Season 4)', 'https://phimimg.com/upload/vod/20260429-1/e1935e811ac7d1ab7232fecfdda55ccd.jpg', 'https://phimimg.com/upload/vod/20260429-1/b7a19a1b54bf652501c6fe9102d438a8.jpg', '<p>Thị trấn tổ chức rất nhiều sự kiện văn hóa nhằm giới thiệu, bảo tồn và tôn vinh các phong tục, nghệ thuật dân gian như: múa lân, chèo thuyền rồng, nặn tò he, vẽ tranh bằng đường... Cũng vì thế, rất nhiều rắc rối liên tục xuất hiện, cần tới sự giúp đỡ của Biệt Đội Boonie. Qua mỗi tập phim, các bạn nhỏ cùng trải nghiệm nhiều trò chơi thú vị, dần hiểu hơn vẻ đẹp của văn hóa truyền thống.</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 36, 2026, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["Boonie Squad","熊熊帮帮团"]', 1784690324124);
