INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cung-nu-nay-khong-may-binh-tinh', 'Cung Nữ Này Không Mấy Bình Tĩnh', 'This Palace Maid Isn''t Very Calm', 'https://phimimg.com/upload/vod/20260413-1/bd7e363ff78ff144350dff3e65afb31b.jpg', 'https://phimimg.com/upload/vod/20260413-1/a632daf1fe657bbaccedf45c4d7c451a.jpg', '<p>Nữ bác sĩ y học cổ truyền hiện đại Thẩm Chiêu Đệ bất ngờ xuyên vào một cuốn tiểu thuyết cung đấu, trở thành cung nữ lót đường vừa mở đầu đã bị phạt trượng mất mạng. Dựa vào y thuật cao minh và việc biết trước cốt truyện, nàng đã vươn lên thay đổi số phận, chữa bệnh cho Thái hậu, giúp nữ chính có được chỗ đứng, và cùng vị Thập Tứ Vương gia lạnh lùng, cao ngạo sa lầy vào một câu chuyện tình cảm ngọt ngào xen lẫn đắng cay. Hãy cùng theo dõi cách nàng bình tĩnh lật ngược thế cờ giữa chốn hậu cung đầy rẫy hiểm nguy, sống cuộc đời rực rỡ của riêng mình nhé!</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 18, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yên Duyệt Khê","avatar":""},{"name":"Lưu Minh Hạo","avatar":""},{"name":"Kim Huyền Vũ","avatar":""},{"name":"Hàn Phượng Nhi","avatar":""},{"name":"Vương Tư Oánh","avatar":""},{"name":"Tô Kỳ","avatar":""},{"name":"Mã Dao Dao","avatar":""},{"name":"Lữ Minh Việt","avatar":""},{"name":"Đường Hâm Vũ","avatar":""},{"name":"Phàn Chỉ Manh","avatar":""},{"name":"Ngô Lam","avatar":""},{"name":"Trần Dịch Thiên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Maid Needs to Stay Calm","这个宫女不太冷静"]', 1784690324124);
