INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-se-doat-mang', 'Chúng Sẽ Đoạt Mạng', 'They Will Kill You', 'https://phimimg.com/upload/vod/20260428-1/5ced462d6e656edc10e10f874884de9b.jpg', 'https://phimimg.com/upload/vod/20260428-1/db0a64d576c4364a998ceb2e17a26aaa.jpg', '<p>Đến từ New Line Cinema và Nocturna, CHÚNG SẼ ĐOẠT MẠNG (tựa gốc: THEY WILL KILL YOU) là một tác phẩm kinh dị - hành động - hài hước đẫm máu và đầy kịch tính xoay quanh cuộc chiến sống còn của một người phụ nữ tại tòa nhà xa hoa The Virgil - hang ổ của một giáo phái ma quỷ. Khi màn đêm buông xuống, những cạm bẫy được giăng ra, kẻ không thể sống sót sẽ trở thành vật tế tiếp theo. Một trận chiến chết chóc mãn nhãn cùng phong cách hài đen đầy mê hoặc sẽ sớm bắt đầu trên màn ảnh rộng.</p>', 'Full', 1, 'single', 'completed', 35, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Zazie Beetz","avatar":""},{"name":"Patricia Arquette","avatar":""},{"name":"Myha''la","avatar":""},{"name":"Paterson Joseph","avatar":""},{"name":"Tom Felton","avatar":""},{"name":"Heather Graham","avatar":""},{"name":"Willie Ludik","avatar":""},{"name":"David Viviers","avatar":""},{"name":"Gabe Gabriel","avatar":""},{"name":"Viktoriya Korotkova","avatar":""},{"name":"James Remar","avatar":""},{"name":"Dorothy Ann Gould","avatar":""},{"name":"Mike Huff","avatar":""},{"name":"Darron Meyer","avatar":""},{"name":"Orefile Moloi","avatar":""},{"name":"Brandon Auret","avatar":""},{"name":"Angus Sampson","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Eles vão te matar","Ti uccideranno","Najdou si tě","Ils te tueron