INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trinh-tong', 'Trinh Tống', 'Detective In The Song Dynasty', 'https://phimimg.com/upload/vod/20260428-1/1fc5a66033823e1d487f2d1b24af18c4.jpg', 'https://phimimg.com/upload/vod/20260428-1/fa9e82d5ca241889879df5c2bce3024b.jpg', '<p>Sau khi xuyên không về thời cổ đại, bác sĩ pháp y Lưu Xuyên đã tiếp nhận thân phận của một nạn nhân bị sát hại có ngoại hình giống hệt mình. Anh thấy mình bị ràng buộc vào một cuộc hôn nhân bất ngờ trong khi phải phá giải hàng loạt vụ án mạng ly kỳ bằng kỹ năng điều tra hiện đại của mình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 18, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cảnh Nghiên Tuấn","avatar":""},{"name":"Thôi Bảo Nguyệt","avatar":""},{"name":"Trương Kế Minh","avatar":""},{"name":"Triệu Tử Lạc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Zhen Song","侦宋"]', 1784690324124);
