INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('trinh-tong', 'Trinh Tống', 'Detective In The Song Dynasty', 'trinh tống detective in the song dynasty cảnh nghiên tuấn thôi bảo nguyệt trương kế minh triệu tử lạc zhen song 侦宋', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-danh-cua-co-ay', 'Tội Danh Của Cô Ấy', 'Her Crime', 'https://phimimg.com/upload/vod/20260428-1/b31adf572464daad1dbc9e53dfd4d789.jpg', 'https://phimimg.com/upload/vod/20260428-1/2c758c4574605d184de3025324d46eba.jpg', '<p>Một vụ trọng án kinh hoàng xảy ra tại khu nhà trọ ở thành phố Quảng Nam, nạn nhân là Li Na Linda — một cô gái làm việc tại hộp đêm — bị sát hại dã man. Cảnh sát hình sự Lâm Uy cùng người đồng đội dày dạn kinh nghiệm Mã Quốc Đống đã phối hợp điều tra. Từ những chi tiết nhỏ tại hiện trường, họ bác bỏ giả thuyết giết người cướp của thông thường và chuyển hướng mục tiêu sang Tào Ái Viện, một phục vụ viên đang mất tích và băng nhóm đứng sau cô ta.&nbsp; Qua điều tra, cảnh sát phát hiện Tào Ái Viện vì chịu đựng sự khinh miệt, nhục mạ lâu ngày từ người quá cố nên đã nảy sinh oán hận, từ đó cấu kết với Hoa Vệ Hồng và đồng bọn dàn cảnh gây án. Trong quá trình truy dấu, cảnh sát dần bóc tách sự thật về một băng nhóm chuyên mưu sát vì tiền, cùng những cuộc nội chiến và trốn chạy của chúng. Vụ án kéo dài ròng rã ba năm, Tào Ái Viện thay tên đổi họ rồi tiếp tục gây thêm mạng người, nhưng cuối cùng vẫn bị Lâm Uy khuất phục trước pháp luật. Trong cuộc truy đuổi nghẹt thở, người cảnh sát già Mã Quốc Đống đã hy sinh anh dũng dù đang mang trọng bệnh. Câu chuyện không chỉ là hành trình phá án mà còn mổ xẻ những góc khuất về gia đình, thiện ác và sự vùng vẫy ở tầng lớp đáy xã hội, tôn vinh sứ mệnh chính nghĩa của người chiến sĩ công an.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Từ Dương","avatar":""},{"name":"Hồng Tuấn Gia","avatar":""},{"name":"Ngô Thiên Kỳ","avatar":""},{"name":"Hạ Cương","avatar":""},{"name":"Lương Siêu","avatar":""},{"name":"Hoàng Doãn Đồng","avatar":""},{"name":"Tiền Y","avatar":""},{"name":"Tông Phong Nham","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["她的罪名"]', 1784690324124);
