INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('toi-danh-cua-co-ay', 'Tội Danh Của Cô Ấy', 'Her Crime', 'tội danh của cô ấy her crime từ dương hồng tuấn gia ngô thiên kỳ hạ cương lương siêu hoàng doãn đồng tiền y tông phong nham 她的罪名', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-dich-bon-chan', 'Tình Địch Bốn Chân', 'My Rival My Love', 'https://phimimg.com/upload/vod/20260428-1/b765c098587960ebfb607c46f4bc1bf9.jpg', 'https://phimimg.com/upload/vod/20260428-1/27a6cae82017f94bac6d1743a0cb92ac.jpg', '<p>Sếp Tiết cả đời ghét nhất kiểu người như cậu ba Hạ: bề ngoài đạo mạo, con cưng của trời, lúc nào cũng mang bộ mặt lạnh tanh như người chết, mà trong lòng thì thâm hiểm hơn ai hết. Còn cậu ba Hạ lại ghét nhất loại người như sếp Tiết: miệng đầy lời thô tục, đánh nhau hung hãn, chỉ cần người khác cho chút ân huệ là đã cảm kích đến mức làm trâu làm ngựa. Suốt bốn năm đại học, họ là tình địch (giả) của nhau, là kẻ thù không đội trời chung, cứ gặp là đánh nhau. Cứ tưởng sau khi tốt nghiệp, hai người chẳng ưa gì nhau sẽ không còn liên quan. Cho đến khi tin “bạch nguyệt quang” kết hôn truyền đến, sếp Tiết uống rượu giải sầu trong quán bar, không may trúng thuốc, được cậu ba Hạ tình cờ đi ngang qua cứu giúp. Trên giường khách sạn, dưới tác động của thuốc, sếp Tiết không còn tỉnh táo, nhìn gương mặt điển trai của cậu ba Hạ mà nảy sinh ý nghĩ khác, kéo áo anh ra lệnh: “Giúp tôi một lần”. Cậu ba Hạ nheo mắt, ở lại chăm sóc anh suốt đêm để giải tác dụng của thuốc, khiến sếp Tiết khổ sở đến mức kêu la, nước mắt lưng tròng. Sáng hôm sau, sếp Tiết ôm cái mông đau nhức, vừa đấm đá cậu ba Hạ, cuối cùng lại tự làm mình vào viện. Lần này thì mối thù coi như kết thúc rồi.</p>', 'Hoàn Tất (8/8)', 8, 'hoathinh', 'completed', 28, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phim Ngắn","slug":"phim-ngan","id":"4f02d28224c0747511790d57fbb63a62"}]', '[]', 1784690324124);
