INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hom-nay-cung-dang-giai-cuu-the-gioi-hom-nay-cung-ban-cuu-the-gioi', 'Hôm Nay Cũng Đang Giải Cứu Thế Giới (Hôm Nay Cũng Bận Cứu Thế Giới)', 'Another Day Saving The World', 'https://phimimg.com/upload/vod/20260428-1/dfbdaf44a12c6a80d29db1297393b3e1.jpg', 'https://phimimg.com/upload/vod/20260428-1/7c9f89937e50c9a959ac9fa8f4ec5c74.jpg', '<p>Trên ranh giới giữa cái chết và sự sống, Lục Đan Vũ được đưa đến một thế giới có tri giác mang tên Vĩnh Quang. Khi sự cân bằng của thế giới này bị phá vỡ bởi một thế lực chưa rõ danh tính, nàng bị cuốn vào hành trình giải mã bí ẩn đằng sau sự thức tỉnh của thế giới đó và vai trò của chính mình trong cuộc hành trình này.</p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 15, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lâm Thanh","avatar":""},{"name":"Mộc Dương","avatar":""},{"name":"Thẩm Bảo Bình","avatar":""},{"name":"Trần Tư Kỳ","avatar":""},{"name":"Tằng Khánh Sinh","avatar":""},{"name":"Trương Dịch Vinh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["今天也在拯救世界"]', 1784690324124);
