INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hom-nay-cung-dang-giai-cuu-the-gioi-hom-nay-cung-ban-cuu-the-gioi', 'Hôm Nay Cũng Đang Giải Cứu Thế Giới (Hôm Nay Cũng Bận Cứu Thế Giới)', 'Another Day Saving The World', 'hôm nay cũng đang giải cứu thế giới (hôm nay cũng bận cứu thế giới) another day saving the world lâm thanh mộc dương thẩm bảo bình trần tư kỳ tằng khánh sinh trương dịch vinh 今天也在拯救世界', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giay-ngan-tinh-dai', 'Giấy Ngắn Tình Dài', 'Remittance Letter', 'https://phimimg.com/upload/vod/20260428-1/a53da02f5b7fa55136f2fdee31177ed3.jpg', 'https://phimimg.com/upload/vod/20260428-1/69acc5dc659905ef23120e3d7c189ef8.jpg', '<p>Bộ phim kể về chàng thiếu niên Trần Gia Đống, người từng tận mắt chứng kiến cha mẹ bị sát hại tại Mã Lai vì phát hiện bí mật về các thí nghiệm trên cơ thể người của quân đội Nhật. Khi đó, anh được gửi gắm như một &quot;kiện hàng sống&quot; thông qua hệ thống Kiều phi (mạng lưới gửi thư và tiền của Hoa kiều) để trốn về Tuyền Châu. Mười hai năm sau, Gia Đống quay trở lại Nam Dương để tìm kiếm sự thật. Tại đây, anh đã sát cánh cùng anh em nhà họ Lâm là Lâm Minh Thư và Lâm Vọng Thư để vạch trần tội ác, đồng thời bảo vệ danh sách những đồng bào bị nạn và những lá thư nhà quý giá. Trong thời đại loạn lạc, họ dùng những chuyến &quot;Kiều phi&quot; làm sợi dây liên kết, khéo léo đối đầu với kẻ thù. Thứ họ chuyển đi không chỉ là ngân tín mà còn là niềm tin và tình yêu thương trong khói lửa chiến tranh. Cuối cùng, Trần Gia Đống kế thừa di chí của cha mẹ, bôn ba giữa Nam Dương và quê hương, trưởng thành từ những đau thương để trở thành người bảo vệ lịch sử và gia viên.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Minh Tuấn","avatar":""},{"name":"Phan Quân Nhã","avatar":""},{"name":"Uông Tịch Triều","avatar":""},{"name":"Phàn Dịch Ninh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Zhi Duan Qing Chang","纸短情长"]', 1784690324124);
