INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gui-chung-ta-cua-thuo-ban-dau', 'Gửi Chúng Ta Của Thuở Ban Đầu', 'Once We Were', 'https://phimimg.com/upload/vod/20260428-1/b5a2c22154a0445a5e34db2a3460196d.jpg', 'https://phimimg.com/upload/vod/20260428-1/b1b561b40d622071608a3f0f19e9f54a.jpg', '<p>Bộ phim kể về câu chuyện thanh xuân của Hùng Nguyên Bảo – một đứa trẻ mồ côi và người hàng xóm Mục Thanh Quân. Giữa những thăng trầm của một thời đại đặc biệt, họ đã cùng nhau trưởng thành và trở thành điểm tựa vững chắc cho nhau. Phim khắc họa sâu sắc những sợi dây liên kết tình cảm bền chặt của đôi bạn thanh mai trúc mã, cùng hành trình theo đuổi lý tưởng và hoài bão giữa những biến động của cuộc sống.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đinh Trạch Nhân","avatar":""},{"name":"Chu Dung Quân","avatar":""},{"name":"Lam Bác","avatar":""},{"name":"Kiều Tĩnh Văn","avatar":""},{"name":"Trần Diệp Sinh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["致最初的我们"]', 1784690324124);
