INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ghi-chep-ky-di-thanh-dong-tan-linh', 'Ghi Chép Kỳ Dị Thanh Đồng Tần Lĩnh', 'The Qinling Bronze Occult Chronicles', 'https://phimimg.com/upload/vod/20260428-1/e4db7e545e0ccdd3f406b756d7f0fc2c.jpg', 'https://phimimg.com/upload/vod/20260428-1/efb810fb0e88e5e59db42909957a2513.jpg', '<p>Sự cố biến dị tại ngôi mộ đồng, từng bị vùi lấp sau thảm họa hầm mỏ Tần Lĩnh năm 1971, bất ngờ trỗi dậy sau nhiều năm. Cựu lính trinh sát Tần Nhạc dẫn đội tiến thẳng vào vùng lõi Tần Lĩnh. Tại khu cấm địa dưới lòng đất - nơi giao thoa giữa hoạt động thăm dò khoa học hiện đại và những nghi thức tế lễ thượng cổ, họ đã từng bước vén màn sự thật tàn khốc về cuộc huyết tế trải dài qua hai thế hệ.</p>', 'Hoàn Tất (60/60)', 60, 'series', 'completed', 29, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phim Ngắn","slug":"phim-ngan","id":"4f02d28224c0747511790d57fbb63a62"}]', '["The Qinling Bronze Occult Chronicles"]', 1784690324124);
