INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-bay-dem-phan-2', 'Chuyến Bay Đêm (Phần 2)', 'Red Eye (Season 2)', 'https://phimimg.com/upload/vod/20260428-1/acd2740af7af8cd2829645ac9ab5f589.jpg', 'https://phimimg.com/upload/vod/20260428-1/ee72a7cd4bbb5c8b051d87dd606d2f3f.jpg', '<p>Nữ cảnh sát London, Hana Li, nhận nhiệm vụ dẫn giải bác sĩ Matthew Nolan trở lại Bắc Kinh, nơi anh bị cáo buộc phạm tội. Tuy nhiên, ngay trên chuyến bay số hiệu 357, cô nhận ra mình đang bị cuốn vào một âm mưu thâm độc cùng những vụ giết người liên tiếp xảy ra ở độ cao hàng vạn dặm. Giữa không gian chật hẹp của khoang máy bay, Hana phải nỗ lực tìm ra sự thật để bảo vệ nhân chứng và chính mạng sống của mình trước khi quá muộn.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 17, 2026, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Jing Lusi","avatar":""},{"name":"Martin Compston","avatar":""},{"name":"Nicholas Rowe","avatar":""},{"name":"Trevor White","avatar":""},{"name":"Tom Forbes","avatar":""},{"name":"Cash Holland","avatar":""},{"name":"Steph Lacey","avatar":""},{"name":"Guy Williams","avatar":""},{"name":"Lesley Sharp","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Code Rouge","Красный глаз","Red Eye"]', 1784690324124);
