INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-face-men-4', 'The Face Men 4', 'The Face Men Thailand 4', 'https://phimimg.com/upload/vod/20260404-1/0de8543ae57541263a2c240fa35e26a8.jpg', 'https://phimimg.com/upload/vod/20260404-1/2cc9884e35dcf16137d4a02450eb7404.jpg', '<p>The Face Men Thailand 4 là một cuộc thi tìm kiếm người mẫu truyền hình thực tế của Thái Lan mang tầm quốc tế dành cho nam giới. Chương trình tập trung vào việc tìm kiếm những gương mặt người mẫu và diễn viên nam hàng đầu thế hệ mới.&nbsp; Đây là phiên bản tách ra (spin-off) từ The Face Thailand, với sự góp mặt của các đội được dẫn dắt bởi những chuyên gia hàng đầu trong ngành. Các thí sinh sẽ phải tranh tài qua các thử thách hàng tuần về kỹ năng diễn xuất, người mẫu và phong thái lôi cuốn.</p>', 'Hoàn Tất (8/8)', 8, 'tvshows', 'completed', 15, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Jumpol Adulkittiporn","avatar":""},{"name":"Phakphum Romsaithong","avatar":""},{"name":"Khemanit Jamikorn","avatar":""},{"name":"Ananda Everingham","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["เดอะเฟซเมนไทยแลนด์"]', 1784690324124);
