INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-vc-cung-kevin-hart', 'Hài vc Cùng Kevin Hart', 'Funny AF With Kevin Hart', 'https://phimimg.com/upload/vod/20260422-1/1fd30020c68fb161393197ee198e9047.jpg', 'https://phimimg.com/upload/vod/20260422-1/58e9a6d70db09e020103b07ddb3b7eb8.jpg', '<p>Kevin Hart cùng sự giúp sức của những huyền thoại trong làng hài sẽ thực hiện một chuyến hành trình xuyên khắp đất nước để tìm kiếm siêu sao hài độc thoại tiếp theo. Những thí sinh triển vọng nhất sẽ phải nỗ lực chinh phục khán giả để giành lấy ngôi vị quán quân — người sẽ được vinh danh trực tiếp thông qua hệ thống bình chọn theo thời gian thực của chính bạn.</p>', 'Tập 6', 8, 'series', 'ongoing', 21, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kevin Hart","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Funny AF with Kevin Hart"]', 1784690324124);
