INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-gap-van-thuong-cung-chang-gap-nguoi', 'Chẳng Gặp Vân Thường, Cũng Chẳng Gặp Người', 'The Moment I Met You', 'https://phimimg.com/upload/vod/20260412-1/f41b7d97137ae498e47a37cca18d3773.jpg', 'https://phimimg.com/upload/vod/20260412-1/6d617cb101ec6bf4c72db8ecb3081d47.jpg', '<p>Bổ khoái Mao Bất Ngộ phải lòng cô gái bán hoa Sở Vân Thường, người đang che giấu thân phận là thủ lĩnh của Đạo môn. Để cưới được Vân Thường, chàng hạ quân lệnh, thề bắt giữ bằng được Phi Thiên Ngọc Thử, thủ lĩnh Đạo môn để thăng chức làm bổ đầu. Gánh vác trách nhiệm tiếp nối sứ mệnh gia tộc, Vân Thường liên tục hoán đổi giữa hai thân phận là thủ lĩnh Đạo môn và cô gái bán hoa. Trận chiến mèo và chuột cũng từ đó mà chính thức bắt đầu!</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 23, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Nhậm Hào","avatar":""},{"name":"Tống Y Nhân","avatar":""},{"name":"Lý Vũ Hạo","avatar":""},{"name":"Mây Thiên Thiên","avatar":""},{"name":"Trương Tư Phàm","avatar":""},{"name":"Triệu Nghiêu Kha","avatar":""},{"name":"Triệu Tây","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bu Yu Yun Shang Bu Yu Ni","Yun Shang Zhi Yu Ni","云裳只遇你","不遇云裳不遇你"]', 1784690324124);
