INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-nghin-dam-duong-may-va-trang', 'Tám Nghìn Dặm Đường Mây Và Trăng', 'Echoes Of A Thousand Moons', 'https://phimimg.com/upload/vod/20260411-1/6675afdbb380e65c1425bbc8b5c79947.jpg', 'https://phimimg.com/upload/vod/20260411-1/25080e45410b1d8aae29adc7c6d3c136.jpg', '<p>Chiến dịch Tùng Hỗ bùng nổ, đầu bếp Mạnh Vạn Phúc chỉ muốn sống sót nhưng bị Quốc Dân Đảng bắt đi đóng quân. Lữ đoàn trưởng Trương Vân Khôi một lòng báo quốc nhưng vì sự chỉ huy sai lầm của cấp trên mà lâm vào nguy hiểm. Trên chiến trường, Trương Vân Khôi liều chết dẫn tàn quân đột phá vòng vây để đón quân tiếp viện. Mạnh Vạn Phúc nhận lời giao phó của anh, vượt đường xa đến Nam Kinh báo tang. Thế rồi Trương Vân Khôi sống sót một cách kỳ diệu nhưng bị cấp trên Quốc Dân đảng vu oan là &quot;quân đào ngũ&quot;. Sau khi khiếu nại không được chấp nhận, anh gặp được chỉ huy trung đoàn Tạ Ngữ Phong của Tân Tứ quân và lại bùng lên hy vọng. Anh trở về quê, thành lập đoàn dân quân chống Nhật và gia nhập Đảng Cộng sản Trung Quốc. Trong khi đó, Mạnh Vạn Phúc tình cờ lại chăm sóc cho cả gia đình nhà họ Trương. Anh ta cùng vợ của Trương Vân Khôi là Đinh Ngọc Kiều hoạn nạn có nhau. Dưới sự dẫn dắt của đảng viên ngầm Tăng Tuyết Phi, cả hai lần lượt tham gia cách mạng cộng sản.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 13, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Dương","avatar":""},{"name":"Vạn Thiến","avatar":""},{"name":"Hoàng Trừng Trừng","avatar":""},{"name":"Vu Hòa Vĩ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ba Qian Li Lu Yun He Yue","Eight Thousand Miles of Cloud and Moon","八千里路云和月"]', 1784690324124);
