INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoat-khoi-tan-the', 'Thoát Khỏi Tận Thế', 'Project Hail Mary', 'https://phimimg.com/upload/vod/20260425-1/f26df5c51ab4664ae0febda78fb15b9e.jpg', 'https://phimimg.com/upload/vod/20260425-1/972224cff3b934fa1aa8781de7822a0d.jpg', '<p>Mất trí nhớ và lạc lõng trên một con tàu vũ trụ, một phi hành gia khám phá ra rằng anh là hy vọng duy nhất của nhân loại trước bờ vực tuyệt chủng. Một liên minh bất ngờ được hình thành, nắm giữ vận mệnh của tất cả.</p>', 'Full', 1, 'single', 'completed', 29, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Ryan Gosling","avatar":""},{"name":"Sandra Hüller","avatar":""},{"name":"James Ortiz","avatar":""},{"name":"Lionel Boyce","avatar":""},{"name":"Milana Vayntrub","avatar":""},{"name":"Ken Leung","avatar":""},{"name":"Priya Kansara","avatar":""},{"name":"Mia Soteriou","avatar":""},{"name":"Annelle Olaleye","avatar":""},{"name":"Maya Eva Hosein","avatar":""},{"name":"Bastian Antonio Fuentes","avatar":""},{"name":"Alice Brittain","avatar":""},{"name":"Michael Akinsulire","avatar":""},{"name":"Travis Jay","avatar":""},{"name":"Geoffrey Lumb","avatar":""},{"name":"Paul Lambert","avatar":""},{"name":"Orion","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Projet dernière chance","Der Astronaut - Project Hail Mary","ภารกิจกู้สุริยะ","Проект «Аве Мария»","Proyecto Salvación","Проект «Конец света»","مشروع هيل ماري","プロジェクト・ヘイル・メアリー","Devoradores de Estrelas","Projecto Hail Mary","Проект «Последняя надежда»","Projecto Fin del Mundo","Projekti Shpresa e Fundit","Project Hail Mary"]', 1784690324124);
