INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-la-trieu-ngo-dich-khoi-dong-lai', 'Tôi Là Triệu Ngô Địch: Khởi Động Lại', 'My Name is Zhao Wudi: Starting Over', 'https://phimimg.com/upload/vod/20260415-1/32fa894b8ddac31ac6e649627c9095ce.jpg', 'https://phimimg.com/upload/vod/20260415-1/4e5419d698b91ae42349408b04c8a771.jpg', '<p>Đây là phần tiếp theo của &quot;Tôi Là Triệu Ngô Địch&quot;, kể về câu chuyện sau khi Triệu Ngô Địch và Thẩm Tinh Ngữ kết hôn thì bất ngờ bị mất trí nhớ, lưu lạc đến một vùng đất đầy rẫy hiểm nguy không nằm dưới sự quản lý của chính phủ. Tại đây, Triệu Ngô Địch một lần nữa gặp lại Thẩm Tinh Ngữ và còn trở thành vệ sĩ của cô. Cả hai cùng nhau vượt qua nhiều kẻ thù nguy hiểm, dần tìm lại ký ức đã mất và bắt đầu một cuộc đời mới.</p>', 'Tập 24', 24, 'series', 'ongoing', 22, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Nghiệp Minh","avatar":""},{"name":"Hướng Hân","avatar":""},{"name":"Cheng Long","avatar":""},{"name":"Bộ Tử Dĩnh","avatar":""},{"name":"Khương Nghệ Thanh","avatar":""},{"name":"Long Thăng","avatar":""},{"name":"Huỳnh Thước Văn","avatar":""},{"name":"Sun Ying","avatar":""},{"name":"Cát Nguyên Tuyết","avatar":""},{"name":"Kiều Hinh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["My Name is Zhao Wudi: Starting Over"]', 1784690324124);
