INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-aang-tiet-khi-su-cuoi-cung', 'Huyền Thoại Aang: Tiết Khí Sư Cuối Cùng', 'Avatar Aang: The Last Airbender', 'https://phimimg.com/upload/vod/20260423-1/17955048a71a832f9606a66d05b70d3f.jpg', 'https://phimimg.com/upload/vod/20260423-1/8ef1f659da45ebf9acea9926f7e45238.jpg', '<p>Avatar Aang, ngự khí sư cuối cùng của thế giới, vô tình biết được một sức mạnh cổ xưa có khả năng cứu vãn nền văn hóa của mình khỏi nguy cơ tuyệt chủng hoàn toàn. Cùng với sự giúp sức của những người bạn đồng hành thân thiết, Aang dấn thân vào một cuộc hành trình xuyên lục địa để tìm kiếm nguồn sức mạnh đó trước khi nó rơi vào tay kẻ xấu—những kẻ đang âm mưu lật đổ nền hòa bình mà nhóm của anh đã phải hy sinh tất cả mới có thể gây dựng nên.</p>', 'Full', 1, 'hoathinh', 'completed', 38, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Eric Nam","avatar":""},{"name":"Dave Bautista","avatar":""},{"name":"Jessica Matten","avatar":""},{"name":"Román Zaragoza","avatar":""},{"name":"Steven Yeun","avatar":""},{"name":"Dionne Quan","avatar":""},{"name":"Dee Bradley Baker","avatar":""},{"name":"Freida Pinto","avatar":""},{"name":"Ke Huy Quan","avatar":""},{"name":"Taika Waititi","avatar":""},{"name":"Geraldine Viswanathan","avatar":""},{"name":"Peta Sergeant","avatar":""},{"name":"Jonathan Ohye","avatar":""},{"name":"Vic Chao","avatar":""},{"name":"François Chau","avatar":""},{"name":"Sander Argabrite","avatar":""},{"name":"Ronny Chieng","avatar":""},{"name":"K","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name"