INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoai-dao', 'Ngoại đạo', 'Unchosen', 'https://phimimg.com/upload/vod/20260423-1/af9a6a6e3fab0701feafb77a12436567.jpg', 'https://phimimg.com/upload/vod/20260423-1/3d94111411ef81c324c41d8f51b83b07.jpg', '<p>Một người mẹ trẻ trong giáo phái khép kín tình cờ gặp một người lạ bí ẩn và bước vào mối quan hệ đầy rủi ro, khơi dậy những khao khát và bí mật đen tối.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 22, 2026, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Molly Windsor","avatar":""},{"name":"Asa Butterfield","avatar":""},{"name":"Fra Fee","avatar":""},{"name":"Siobhan Finneran","avatar":""},{"name":"Christopher Eccleston","avatar":""},{"name":"Rory Wilmot","avatar":""},{"name":"Olivia Pickering","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["未选之人","非选之人","Out of the Dust","Отвергнутая","Unchosen"]', 1784690324124);
