INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngoai-dao', 'Ngoại đạo', 'Unchosen', 'ngoại đạo unchosen molly windsor asa butterfield fra fee siobhan finneran christopher eccleston rory wilmot olivia pickering 未选之人 非选之人 out of the dust отвергнутая unchosen', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-la-anh-duong-cua-toi', 'Em Là Ánh Dương Của Tôi', 'My Only Sunshine', 'https://phimimg.com/upload/vod/20260301-1/c48e1184a6e9b7c331e5ef83bd5eff4a.jpg', 'https://phimimg.com/upload/vod/20260301-1/845147cf428e2d58acbd3c52ba9e571e.jpg', '<p>Nữ diễn viên đang lên Sun đã dành nhiều năm để theo đuổi trái tim của Rafah – một nữ điều hành xe sang quyền lực và cũng là chị gái của bạn thân cô. Tuy nhiên, khi &#39;phản ứng hóa học&#39; trên màn ảnh giữa Sun và một nam bạn diễn mới nổi làm bùng phát những tin đồn hẹn hò rầm rộ, những cảm xúc bị chôn giấu của Rafah bỗng chốc bùng nổ thành sự ghen tuông dữ dội.&nbsp; Giữa tâm bão của những vụ bê bối, ảnh rò rỉ và những lần bị bắt gặp đầy nghi vấn, Rafah đã dọn vào căn hộ của Sun để vừa bảo vệ, vừa kiểm soát cô. Thế nhưng, khi Sun bắt đầu xuất hiện ở những nơi mà cô thề rằng mình chưa từng đặt chân đến, cô bắt đầu nghi ngờ tất cả mọi thứ.&nbsp; Sự thật còn chấn động hơn bất kỳ lời đồn đại nào: Sun có một người chị em song sinh thất lạc từ lâu.&nbsp; Với một người tình cũ đang quyết tâm giành lại Rafah và một đoạn clip rò rỉ đe dọa hủy hoại sự nghiệp của Sun, tình yêu giờ đây trở thành một chiến trường của lòng tin, sự ám ảnh và những bí mật kinh hoàng.</p>', 'Tập 8', 8, 'series', 'ongoing', 18, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Aphichaya Kamnoetsirikun","avatar":""},{"name":"Siripath Sarakune","avatar":""},{"name":"Danita Choktadaporn","avatar":""},{"name":"Deviyabha Uddhachandra","avatar":""},{"name":"Pataravadee Thitivoodtikul","avatar":""},{"name":"Dangtawan Ho","avatar":""},{"name":"Supatsorn Suriyakul","avatar":""},{"name":"Parima Peamkaroonrath","avatar":""},{"name":"Chotiros Srimongkol","avatar":""},{"name":"Wacharanon Seeduan","avatar":""},{"name":"Krisz Ahandrik","avatar":""},{"name":"Nichanat Setasawatpong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["唯你是阳光","Tawan Rafa","My Only Sunshine The Series","ตะวันระฟ้า"]', 1784690324124);
