INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giac-mo-dien-ro', 'Giấc Mơ Điên Rồ', 'Mad Concrete Dreams', 'https://phimimg.com/upload/vod/20260422-1/0ad2b8563974be65fcbfeec48b78ef94.jpg', 'https://phimimg.com/upload/vod/20260422-1/7e55136675663862cc7b94dde8fa882c.jpg', '<p>Diễn ra tại Hàn Quốc, nơi mà sự thành công thường được đo bằng việc sở hữu một tòa nhà. Nhân vật chính, Ki Su Jong, từng là một nhân viên văn phòng bình thường, quyết tâm đầu tư tất cả sức lực của mình vào việc trở thành chủ đất, bất chấp nguy cơ lún sâu vào nợ nần. Tuy nhiên, khi làn sóng đầu tư toàn cầu tràn đến và đe dọa khiến tòa nhà của anh bị tịch thu,</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 16, 2026, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ha Jung-woo","avatar":""},{"name":"Lim Soo-jung","avatar":""},{"name":"Kim Jun-han","avatar":""},{"name":"Krystal Jung","avatar":""},{"name":"Shim Eun-kyung","avatar":""},{"name":"Lee Shin-ki","avatar":""},{"name":"Park Seo-kyung","avatar":""},{"name":"Kim Keum-soon","avatar":""},{"name":"Lee Ju-woo","avatar":""},{"name":"Nam Myung-ryeol","avatar":""},{"name":"Hyun Bong-sik","avatar":""},{"name":"Yoon Jun-won","avatar":""},{"name":"MIYAVI","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["在大韩民国成为房主的方法","在韩国成为房主的方法","在大韩民国成为屋主的方法","أحلام ملموسة جنون","Landlord","How to Become a Building Owner in Korea","대한민국에서 건물주 되는 법"]', 1784690324124);
