INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quyet-chien-vuong-trieu', 'Quyết Chiến Vương Triều', 'The Last Duel', 'https://phimimg.com/upload/vod/20260322-1/978934a5b2ada8a73a0d00d20dafb6a3.jpg', 'https://phimimg.com/upload/vod/20260322-1/bb1d9603f0fcd0ff58dcc7692ba725bd.jpg', '<p>Phim kể về mối quan hệ phức tạp giữa Hoàng tử Naresuan và Mingyi Swa khi Ayutthaya thất thủ dưới tay Hongsawadi. Từ đôi bạn lớn lên như anh em trong cảnh làm con tin, sự tàn khốc của chiến tranh và khát vọng tự do đã đẩy họ vào thế đối đầu sinh tử. Phim tái hiện cuộc chiến khốc liệt giữa lòng trung thành và âm mưu chính trị, nơi tình huynh đệ bị phá vỡ để nhường chỗ cho bổn phận với vương quốc.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 18, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Naphat Siangsomboon","avatar":""},{"name":"Porapat Srikajorndecha","avatar":""},{"name":"Varitthisa Limthammahisorn","avatar":""},{"name":"Chartayodom Hiranyatithi","avatar":""},{"name":"Phiyada Jutharattanakul","avatar":""},{"name":"Natthawut Skidjai","avatar":""},{"name":"Wannarot Sonthichai","avatar":""},{"name":"Punnavich Sirikiatvanit","avatar":""},{"name":"Chatchai Plengpanich","avatar":""},{"name":"Jakkrasin Atsavatanachai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["最後決戰","勃固王朝：終局之戰","หงสาวดี"]', 1784690324124);
