INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trevor-noah-niem-vui-trong-gian-kho', 'Trevor Noah: Niềm Vui Trong Gian Khó', 'Trevor Noah: Joy In The Trenches', 'https://phimimg.com/upload/vod/20260422-1/3fc448155475a9b8c01a47310aa89cae.jpg', 'https://phimimg.com/upload/vod/20260422-1/f92435e3d6c47140f7cf5e59e551e042.jpg', '<p>Từ những màn khẩu chiến bất ngờ trên mạng xã hội cho đến những &quot;cú tát sự thật&quot; đầy thâm thúy từ bác sĩ tâm lý, Trevor Noah đã biến những hỗn loạn của cuộc sống thành những tràng cười không ngớt. Trong tiết mục hài độc thoại đầy nhạy bén và vui nhộn này, anh mang đến những góc nhìn hài hước nhưng không kém phần sâu sắc về thế giới hiện đại, khiến khán giả vừa phải bật cười vừa phải suy ngẫm.</p>', 'Full', 1, 'single', 'completed', 7, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Trevor Noah","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Trevor Noah: Joy in the Trenches"]', 1784690324124);
