INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hon-siren', 'Nụ Hôn Siren', 'Siren''s Kiss', 'https://phimimg.com/upload/vod/20260309-1/32b40e018eba61d97214e250cc1c106d.jpg', 'https://phimimg.com/upload/vod/20260309-1/84b2688ea91444f5923a6a23428544e1.jpg', '<p>Điều tra viên bảo hiểm hàng đầu Cha Woo-seok truy đuổi một đường dây lừa đảo liên quan đến hàng loạt cái chết bí ẩn. Trong quá trình điều tra, anh bị cuốn vào mối quan hệ nguy hiểm với Han Seol-ah — một nữ đấu giá nghệ thuật hoàn hảo đến mê hoặc, nhưng những người đàn ông từng yêu cô dường như đều có kết cục bi thảm. Khi ranh giới giữa sự hấp dẫn và nghi ngờ dần trở nên mờ nhạt, Woo-seok phải tìm ra sự thật: liệu Seol-ah là kẻ sát nhân, hay chỉ là nạn nhân của một âm mưu đen tối, trước khi chính mạng sống của anh trở thành cái giá phải trả cho sự thật.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 34, 2026, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Min-young","avatar":""},{"name":"Wi Ha-jun","avatar":""},{"name":"Kim Jung-hyun","avatar":""},{"name":"Han Jun-woo","avatar":""},{"name":"Kong Seong-ha","avatar":""},{"name":"Hong Gi-jun","avatar":""},{"name":"Kim Keum-soon","avatar":""},{"name":"Ha Seok-jin","avatar":""},{"name":"Yoon Jong-hoon","avatar":""},{"name":"Kim Dong-jun","avatar":""},{"name":"Heo Jae-ho","avatar":""},{"name":"Lee Elijah","avatar":""},{"name":"Jung Lael","avatar":""},{"name":"Song Lee-woo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["O Beijo da Sereia","A szirén csókja","Sⅰren","Pocał