INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-tu-luu-day', 'Hoàng Tử Lưu Đày', 'Release That Witch', 'https://phimimg.com/upload/vod/20260322-1/763dc7da5ea5ac3b112502d5ad3c9f10.jpg', 'https://phimimg.com/upload/vod/20260322-1/b66db28f84fdc5ac260b201a2bea0954.jpg', '<p>Roland, một người đàn ông hiện đại được tái sinh thành hoàng tử tại vùng Biên Thùy trấn đầy rẫy hiểm nguy, đã cứu thoát các phù thủy Anna và Nana Pine khỏi bàn tay của Giáo hội. Tận dụng sức mạnh phi thường của họ, anh đã kết hợp ma thuật và công nghệ để chế tạo vũ khí, quân đội và động cơ hơi nước nhằm bảo vệ thần dân của mình. Khi Mặt Trăng Quỷ trỗi dậy và những âm mưu bủa vây lấy gia tộc, Roland phải dẫn dắt một cuộc cách mạng để bảo vệ các đồng minh và tái thiết lại thế giới.</p>', 'Tập 8', 12, 'hoathinh', 'ongoing', 13, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chen Zhangtaikang","avatar":""},{"name":"Qiao Su","avatar":""},{"name":"Guo Zhengjian","avatar":""},{"name":"Lu Lifeng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Fangkai Nage Nuwu","Fang Kai Na Ge Nu Wu","Fangkai Nage Nüwu","Brujas: El Destino del Reino (2026)","마녀를 지켜라","放开那个女巫"]', 1784690324124);
