INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tra-thu-2026', 'Trả Thù', 'Vengeance / Venganza', 'https://phimimg.com/upload/vod/20260420-1/03fe705c75ec3a12b986c65b769bd7d2.jpg', 'https://phimimg.com/upload/vod/20260420-1/80593b82fa3d383f5e18a173a9b96fea.jpg', '<p>Vụ sát hại dã man vợ của “Toro”, một anh hùng quân đội trong lực lượng đặc nhiệm, đã biến anh ta thành một người đàn ông với một mục đích duy nhất: trả thù. Sau khi vận may đưa đẩy anh ta trở thành triệu phú, Carlos đã biến khối tài sản khổng lồ của mình thành một kho vũ khí và cùng với những người lính thân cận nhất, lên đường truy lùng những kẻ chịu trách nhiệm.</p>', 'Full', 1, 'single', 'completed', 33, 2026, 'Vietsub', 'FHD', 'Mexico', 0, '[{"name":"Omar Chaparro","avatar":""},{"name":"Alejandro Speitzer","avatar":""},{"name":"Paola Nuñez","avatar":""},{"name":"Natalia Solián","avatar":""},{"name":"Luis Alberti","avatar":""},{"name":"Iazua Larios","avatar":""},{"name":"Lizeth Selene","avatar":""},{"name":"Gustavo Sánchez Parra","avatar":""},{"name":"Vasil Simeonov","avatar":""},{"name":"Manuel Cruz Vivas","avatar":""},{"name":"Pablo Cruz","avatar":""},{"name":"José Salof","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Vengeance","Un billón a uno","Venganza"]', 1784690324124);
