INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuc-may-man-va-vui-len-dung-chet', 'Chúc May Mắn Và Vui Lên, Đừng Chết', 'Good Luck, Have Fun, Don''t Die', 'https://phimimg.com/upload/vod/20260312-1/9ca85cbff9905a1ce283afa5982dd8a1.jpg', 'https://phimimg.com/upload/vod/20260312-1/4e88fa30e6ba9124ce58e12719be2f36.jpg', '<p>Một đêm mưa hiếm hoi ở Los Angeles, quán ăn nhỏ giữa trung tâm thành phố bất ngờ trở thành tâm điểm của một câu chuyện điên rồ: một người đàn ông lạ mặt (Sam Rockwell) xông vào, khẳng định mình đến từ tương lai và bắt toàn bộ thực khách làm con tin. Nhưng anh ta không tìm tiền, cũng chẳng đòi đường thoát — thứ anh cần là những “ứng viên” đặc biệt để cùng anh ngăn chặn một thảm họa sắp xảy ra với thế giới.</p>', 'Full', 1, 'single', 'completed', 19, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sam Rockwell","avatar":""},{"name":"Juno Temple","avatar":""},{"name":"Haley Lu Richardson","avatar":""},{"name":"Michael Peña","avatar":""},{"name":"Zazie Beetz","avatar":""},{"name":"Asim Chaudhry","avatar":""},{"name":"Tom Taylor","avatar":""},{"name":"Georgia Goodman","avatar":""},{"name":"Daniel Barnett","avatar":""},{"name":"Artie Wilkinson-Hunt","avatar":""},{"name":"Riccardo Drayton","avatar":""},{"name":"Dominique Maher","avatar":""},{"name":"David Sturzaker","avatar":""},{"name":"Adam Burton","avatar":""},{"name":"Elly Condron","avatar":""},{"name":"Meghan Oberholzer","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Zlom vaz, bav se, n