INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('finding-harry-the-craft-behind-the-magic', 'Finding Harry: The Craft Behind the Magic', 'Finding Harry: The Craft Behind the Magic', 'https://phimimg.com/upload/vod/20260420-1/909a602f36931e1d21586d74a90f9c9f.jpg', 'https://phimimg.com/upload/vod/20260420-1/2a99deed8bd3c1ef81a15d94529232e3.jpg', '<p>Với các cuộc phỏng vấn từ các thành viên của nhóm tuyển chọn diễn viên, thiết kế sản xuất, thiết kế trang phục và hiệu ứng sinh vật, hãy cùng theo dõi hành trình hậu trường đưa loạt sách Harry Potter lên màn ảnh nhỏ. Khám phá cách bộ ba vàng mới được tìm thấy và cùng tôn vinh sự tận tâm đến từng chi tiết của các nghệ sĩ, thợ thủ công và kỹ thuật viên đã cùng nhau mang thế giới phù thủy đến với cuộc sống.</p>', 'Full', 1, 'single', 'completed', 20, 2026, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Nick Frost","avatar":""},{"name":"Dominic McLaughlin","avatar":""},{"name":"Arabella Stanton","avatar":""},{"name":"Alastair Stout","avatar":""},{"name":"John Lithgow","avatar":""},{"name":"Janet McTeer","avatar":""},{"name":"Paapa Essiedu","avatar":""},{"name":"Mark Mylod","avatar":""},{"name":"Francesca Gardiner","avatar":""},{"name":"Mara LePere-Schloop","avatar":""},{"name":"Holly Waddington","avatar":""},{"name":"Adriano Goldman","avatar":""},{"name":"Christophe Nuyens","avatar":""},{"name":"Lucy Bevan","avatar":""},{"name":"Emily Brockmann","avatar":""},{"name":"John Nolan","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["В поисках Гарри: Искусство создания волшебства","В поисках Гарри","Мир Гарри Поттера: Мастерство, стоящее за магией","Гарри Поттер. В поисках Гарри","У пошуках Гаррі: Як твориться магія","Finding Harry: The Craft Behind the Magic"]', 1784690324124);
