INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-so-ngam', 'tần số ngầm', 'undertone', 'https://phimimg.com/upload/vod/20260416-1/b3f8c3248fd102cac5ddfa1ee5d13745.jpg', 'https://phimimg.com/upload/vod/20260416-1/55237a39087e4a44cc9cbc5c44a25ab2.jpg', '<p>Người dẫn một podcast nổi tiếng về hiện tượng siêu nhiên bắt đầu bị ám ảnh bởi những bản ghi âm kinh hoàng được gửi đến cô một cách bí ẩn. Khi càng đào sâu vào nguồn gốc của các đoạn ghi ấy, ranh giới giữa công việc và nỗi sợ cá nhân dần sụp đổ.</p>', 'Full', 1, 'single', 'completed', 23, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Canada', 0, '[{"name":"Nina Kiri","avatar":""},{"name":"Adam DiMarco","avatar":""},{"name":"Michèle Duquet","avatar":""},{"name":"Keana Bastidas","avatar":""},{"name":"Jeff Yung","avatar":""},{"name":"Ryan Turner","avatar":""},{"name":"Brian Quintero","avatar":""},{"name":"Marisol D’Andrea","avatar":""},{"name":"Austin Tuason","avatar":""},{"name":"Seled Calderon","avatar":""},{"name":"Bianca Nugara","avatar":""},{"name":"Jayda Woods","avatar":""},{"name":"Sarah Beaudin","avatar":""},{"name":"Christina Notto","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["The Undertone","undertone"]', 1784690324124);
