INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ronaldinho-huyen-thoai-duy-nhat', 'Ronaldinho: Huyền Thoại Duy Nhất', 'Ronaldinho: The One and Only', 'https://phimimg.com/upload/vod/20260420-1/01338e5c565475b63945c25d132ceb90.jpg', 'https://phimimg.com/upload/vod/20260420-1/ebecdfc2e0d2570ef9dd35103026864f.jpg', '<p>Bộ phim tài liệu theo chân hành trình của Ronaldinho từ cậu bé đam mê bóng đá tại Porto Alegre đến khi trở thành biểu tượng toàn cầu, tái hiện những khoảnh khắc đỉnh cao trong sự nghiệp, danh hiệu Quả Bóng Vàng và phong cách chơi bóng đầy ngẫu hứng làm say đắm hàng triệu người hâm mộ.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 27, 2026, 'Vietsub', 'FHD', 'Brazil', 0, '[{"name":"Ronaldinho","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Ronaldinho Gaúcho"]', 1784690324124);
