INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-khi-toi-lam-gia-su-cho-ke-thu', 'Từ Khi Tôi Làm Gia Sư Cho Kẻ Thù', 'Tutoring My Enemy', 'https://phimimg.com/upload/vod/20260420-1/269e34633f2d9f39fb7a040587530308.jpg', 'https://phimimg.com/upload/vod/20260420-1/b57976e5ca3859837c0b91c72783da52.jpg', '<p>Push và James là hai kẻ đối đầu không đội trời chung trong trường. Để kiếm tiền giúp gia đình, Push đi làm thêm bên ngoài nhưng lại bị ông chủ tiệm xe sỉ nhục. Đúng lúc đó, một ông trùm xã hội đen bất ngờ bắt cóc Push, ép cậu phải dạy kèm cho con trai mình. Ngày đầu nhận việc, Push mới bàng hoàng phát hiện con trai của ông trùm ấy không ai khác chính là James, kẻ thù truyền kiếp của mình. Bị James khiêu khích, Push quyết định nhận công việc, chịu đựng đủ kiểu trêu chọc và “hành hạ” từ James, mà không hề nhận ra rằng tình cảm giữa hai người đang âm thầm nảy nở trong những lần tiếp xúc gần gũi…</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 31, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Suppawit Thongyuen","avatar":""},{"name":"Kashane Pichetsopon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phim Ngắn","slug":"phim-ngan","id":"4f02d28224c0747511790d57fbb63a62"}]', '["Tutoring My Enemy","Tutoring My Nemesis","ติวเตอร์หัวใจนายตัวแสบ"]', 1784690324124);
