INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cardfight-vanguard-divinez-genma-seisenhen', 'Cardfight!! Vanguard- Divinez Genma Seisen-hen', 'Cardfight!! Vanguard- Divinez Parallactic Clash', 'https://phimimg.com/upload/vod/20260204-1/f776eabb906af224cf4061e55cb87da8.jpg', 'https://phimimg.com/upload/vod/20260204-1/19f9ee76ebfd261ed555dc7ae1b36044.jpg', '<p>Akina và những người bạn của cậu, sau khi lạc vào Thế giới Ảo ảnh, đã bị chặn đường bởi những “Chiến binh Ảo ảnh”. &nbsp;Những người duy nhất có thể chống lại chúng là những “Chiến binh Thần thoại” đặc biệt được lựa chọn bởi các lá bài. &nbsp;Chiến binh Ảo ảnh là gì? &nbsp;Tên gọi chung cho những người đối mặt với thực tại và chiến đấu để bảo vệ những điều được tạo dựng. &nbsp;Chiến binh Thần thoại là gì? &nbsp;Tên gọi chung cho những người chống lại Ảo ảnh và chiến đấu để bảo vệ thực tại. &nbsp;Liệu thế giới song song sẽ bị xóa bỏ, hay nó sẽ trở thành chân lý? &nbsp;—Hãy đứng lên và chiến đấu với sự tồn tại của chính mình.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324124);
