INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kho-luong', 'Khó Lường', 'The Silent Rift', 'https://phimimg.com/upload/vod/20260406-1/3f1f3b3c03dda70a68b768263fb1fa1d.jpg', 'https://phimimg.com/upload/vod/20260406-1/ec2db1d300e5287711ef9fd4f29a025c.jpg', '<p>Manh mối về một vụ cướp bị lãng quên suốt 18 năm bất ngờ xuất hiện, khiến Mạnh Quảng Tài - một doanh nhân nổi tiếng đi lên từ hai bàn tay trắng và đang ở đỉnh cao vinh quang - đột ngột bị bắt giam. Trong khi đó, Chu Hách Lai - một cảnh sát già đã lui về làm việc lặng lẽ tại nhà ăn suốt nhiều năm - lại trở thành nhân vật then chốt để phá giải vụ án này. Mạnh Quảng Tài cùng nhóm cướp năm xưa đã thêu dệt nên mê cung dối trá, không ngừng đấu trí với Chu Hách Lai và lực lượng cảnh sát. Từ đây, bức màn bí mật về vận mệnh khó lường, đầy rẫy những ân oán thăng trầm suốt 28 năm quen biết giữa hai người họ chính thức được hé lộ...</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 15, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Diệp","avatar":""},{"name":"Nhiếp Nguyên","avatar":""},{"name":"Vương Giai Giai","avatar":""},{"name":"Lý Kiện","avatar":""},{"name":"Phùng Binh","avatar":""},{"name":"Vương Tử Vy","avatar":""},{"name":"Đổng Khả Phi","avatar":""},{"name":"Lãnh Kỷ Nguyên","avatar":""},{"name":"Lưu Tuấn Hiếu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Po Ce","파측","Unpredictable","叵测"]', 1784690324124);
