INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('kho-luong', 'Khó Lường', 'The Silent Rift', 'khó lường the silent rift lưu diệp nhiếp nguyên vương giai giai lý kiện phùng binh vương tử vy đổng khả phi lãnh kỷ nguyên lưu tuấn hiếu po ce 파측 unpredictable 叵测', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-dau-gia-bao-thu', 'Cô Dâu Giả Báo Thù', 'Revenge Of The False Bride', 'https://phimimg.com/upload/vod/20260410-1/69a9f4029232ce7adcdc428ca445ea31.jpg', 'https://phimimg.com/upload/vod/20260410-1/457adf49c28881dd57241a580b53c331.jpg', '<p>Gánh trên mình mối thù và món nợ ân tình chồng chất, cô nhi Lê Mộ Hà mượn thân phận thiên kim Thẩm Niệm quay về báo thù và gả cho thiếu soái mặt lạnh Lục Nhạc Đình bằng một tờ hôn thư. Cuộc hôn nhân khởi đầu từ toan tính ấy lại trở thành chỗ dựa vững chắc nhất của cô. Cô giải quyết mọi việc giữa mẹ kế, thương hội và dược đường, còn anh luôn là lưỡi dao và tấm khiên đứng sau cô. Thế nhưng sự xuất hiện của chiến hữu cũ cùng án cũ nơi chiến trường bất ngờ phơi bày những nghi vấn nhắm vào Lục Nhạc Đình. Yêu hận đan xen giữa âm mưu gia tộc và ngoại bang xâm lấn. Cuối cùng, giữa khói lửa chiến tranh, cô đối diện mọi ân oán, cởi bỏ lớp ngụy trang, lấy lại tên thật của mình và cùng người thật lòng yêu cô sánh bước hướng tới tương lai nước nhà.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 17, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hàn Đông Lâm","avatar":""},{"name":"Trương Uyển Oánh","avatar":""},{"name":"Vương Tử Ninh","avatar":""},{"name":"Vương Giai Ninh","avatar":""},{"name":"Dương Tây Nhã","avatar":""},{"name":"Vương Vũ Bác","avatar":""},{"name":"Trần Khiết","avatar":""},{"name":"Lư Dự Văn","avatar":""},{"name":"Trần Khuê Hy","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Revenge of the False Bride","春霆念未央"]', 1784690324124);
