INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('may-nuong-banh', 'Máy nướng bánh', 'Toaster', 'https://phimimg.com/upload/vod/20260416-1/78ea5820ef97f0fbabb0ca5445b65a90.jpg', 'https://phimimg.com/upload/vod/20260416-1/3ca803f8d3d9281d845f2d261bb0332f.jpg', '<p>Án mạng và hỗn loạn bùng nổ khi một kẻ keo kiệt bị ám ảnh bởi chiếc máy nướng bánh mì mà hắn đã tặng làm quà cưới.</p>', 'Full', 1, 'single', 'completed', 22, 2026, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Rajkummar Rao","avatar":""},{"name":"Sanya Malhotra","avatar":""},{"name":"Abhishek Banerjee","avatar":""},{"name":"Upendra Limaye","avatar":""},{"name":"Seema Pahwa","avatar":""},{"name":"Farah Khan","avatar":""},{"name":"Archana Puran Singh","avatar":""},{"name":"Jitendra Joshi","avatar":""},{"name":"Pratik Gandhi","avatar":""},{"name":"Patralekhaa","avatar":""},{"name":"Karamveer Choudhary","avatar":""},{"name":"Vinod Rawat","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["टोस्टर"]', 1784690324124);
