INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hay-song-cho-ngay-mai-hay-chet-hom-nay', 'Hãy sống cho ngày mai. Hãy chết hôm nay.', 'ALL YOU NEED IS KILL', 'https://phimimg.com/upload/vod/20260416-1/4f5973081267fe9aaaafef2dba69f4cf.jpg', 'https://phimimg.com/upload/vod/20260416-1/559a2a19600d62b4b83869c802f84707.jpg', '<p>Khi một bông hoa ngoài hành tinh khổng lồ mang tên &quot;Darol&quot; bất ngờ bùng nổ trong một sự kiện chết người, giải phóng những sinh vật quái dị tàn sát dân số Nhật Bản, Rita bị cuốn vào vòng xoáy hủy diệt—và bị giết chết. Nhưng rồi cô tỉnh dậy. Và lại tỉnh dậy lần nữa. Bị mắc kẹt trong một vòng lặp thời gian vô tận, Rita phải vượt qua nỗi đau và sự lặp lại của cái chết cho đến khi cô gặp Keiji, một chàng trai trẻ nhút nhát cũng bị mắc kẹt trong vòng luẩn quẩn tương tự. Cùng nhau, họ chiến đấu để thoát khỏi vòng lặp và tìm kiếm ý nghĩa trong sự hỗn loạn xung quanh.</p>', 'Full', 1, 'hoathinh', 'completed', 16, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ai Mikami","avatar":""},{"name":"Natsuki Hanae","avatar":""},{"name":"Kana Hanazawa","avatar":""},{"name":"Hiccorohee","avatar":""},{"name":"Mo Chugakusei","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["オールユーニードイズキル","明日边缘","ALL YOU NEED IS KILL"]', 1784690324124);
