INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-nam-giu-su-that-alguien-tiene-que-saber', 'Người Nắm Giữ Sự Thật (Alguien tiene que saber)', 'Someone Has To Know', 'https://phimimg.com/upload/vod/20260416-1/37c84c4f53d3f299dea7b5a83f40ab8b.jpg', 'https://phimimg.com/upload/vod/20260416-1/87965391c2244e262533b9bb1b3d5f50.jpg', '<p>Một cậu bé đột ngột mất tích, và không một ai có thể tìm thấy dấu vết của cậu. Đây tưởng chừng là một vụ án đơn giản có thể phá giải nhanh chóng, ngoại trừ một sự thật phũ phàng: hoàn toàn không có bất kỳ manh mối nào được để lại. Có đến 300 người xuất hiện xung quanh cậu bé vào thời điểm đó, nhưng kỳ lạ thay, không một ai nhìn thấy bất cứ điều gì? Sự im lặng đến đáng sợ của các nhân chứng đẩy cuộc điều tra vào ngõ cụt và mở ra những nghi vấn về một sự thật kinh hoàng đang bị che giấu.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 17, 2026, 'Vietsub', 'FHD', 'Chile', 0, '[{"name":"Paulina García","avatar":""},{"name":"Alfredo Castro","avatar":""},{"name":"Benjamín Vicuña","avatar":""},{"name":"Gabriel Cañas","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["ใครสักคนต้องรู้ความจริง","Someone Has to Know","Alguien tiene que saber"]', 1784690324125);
