INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thai-binh-nien', 'Thái Bình Niên', 'Swords Into Plowshares', 'https://phimimg.com/upload/vod/20260124-1/0be72950d217cc243d213c4b9f91df7f.jpg', 'https://phimimg.com/upload/vod/20260124-1/230377b369c8b86013a47bfa8599b9e1.jpg', '<p>Vào thời kỳ Ngũ đại Thập quốc, trật tự chính trị sụp đổ, chiến tranh liên tục nổ ra khiến dân chúng phải sống trong lầm than. Trước tình cảnh đó, Tiền Hoằng Thục, Triệu Khuông Dận và Quách Vinh dần nhận ra rằng chỉ có thống nhất đất nước mới có thể chấm dứt được loạn lạc và tang thương. Thái Bình Niên ba theo chân ba con người mang chí lớn này trong hành trình đầy gian nan và thử thách để thực hiện khát vọng chấm dứt chiến tranh và mang lại thái bình cho dân chúng.</p>', 'Hoàn Tất (48/48)', 48, 'series', 'completed', 22, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Bạch Vũ","avatar":""},{"name":"Châu Vũ Đồng","avatar":""},{"name":"Chu Á Văn","avatar":""},{"name":"Nghiêu Hạo Minh","avatar":""},{"name":"Đổng Dũng","avatar":""},{"name":"Nhan Đại Hồng","avatar":""},{"name":"Mai Đình","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["吴越归宗之太平年","The Age of Peace","Swords into Plowshares","太平年"]', 1784690324125);
