INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieng-thet-7', 'Tiếng Thét 7', 'Scream 7', 'https://phimimg.com/upload/vod/20260320-1/02357f6d4016248c8f7551004471f943.jpg', 'https://phimimg.com/upload/vod/20260320-1/47c0a38e4b50f086e788286cc4758e15.jpg', '<p>Sidney Evans (Neve Campbell), nạn nhân sống sót của một vụ thảm sát nhiều năm trước, giờ đang sống hạnh phúc cùng chồng và con gái ở một thị trấn khác thì tên sát nhân Ghostface mới lại xuất hiện. Những nỗi sợ hãi đen tối nhất của cô trở thành hiện thực khi con gái cô Tatum Evans (Isabel May) trở thành mục tiêu tiếp theo. Quyết tâm bảo vệ gia đình, Sidney buộc phải đối mặt với những kinh hoàng trong quá khứ để chấm dứt cuộc đổ máu một lần và mãi mãi.</p>', 'Full', 1, 'single', 'completed', 19, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Neve Campbell","avatar":""},{"name":"Courteney Cox","avatar":""},{"name":"Isabel May","avatar":""},{"name":"Jasmin Savoy Brown","avatar":""},{"name":"Mason Gooding","avatar":""},{"name":"Roger L. Jackson","avatar":""},{"name":"Anna Camp","avatar":""},{"name":"Joel McHale","avatar":""},{"name":"Celeste O''Connor","avatar":""},{"name":"Sam Rechner","avatar":""},{"name":"Asa Germann","avatar":""},{"name":"Mckenna Grace","avatar":""},{"name":"Matthew Lillard","avatar":""},{"name":"Kraig Dane","avatar":""},{"name":"Ethan Embry","avatar":""},{"name":"Mark Consuelos","avatar":""},{"name":"Victor Turpin","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Scar Tissue","Scream VII","Pânico VII","หวีดสุดขีด 7","Tiếng Thét 7","BlackBird","Çığlık 7","驚聲尖叫7","Врисак 7","Кр