INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toa-an-gia-dinh', 'Toà Án Gia Đình', 'Hold A Court Now', 'https://phimimg.com/upload/vod/20260329-1/10ddb6b894676a12063035033d20bfb6.jpg', 'https://phimimg.com/upload/vod/20260329-1/b228380e2ef38bf6d7d8ab653cfa2910.jpg', '<p>Bộ phim kể về thẩm phán trẻ Thẩm Tạ Trật, cùng luật sư Tần Duệ và các đồng nghiệp như Thư Tĩnh, Hồ Ngải Khê, Trần Hướng Huy… cùng nhau xuống dưới cơ sở, trực tiếp giải quyết những vấn đề xã hội và gia đình phức tạp cho người dân, từ mâu thuẫn giữa cha mẹ với con cái đến khủng hoảng hôn nhân. Qua từng vụ án, họ luôn giữ vững nguyên tắc &quot;pháp luật vô tình nhưng con người thì có tình&quot;, kiên trì thực hiện lý tưởng ban đầu, và luôn giữ vững niềm tin vào thượng tôn pháp luật.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 15, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cung Tuấn","avatar":""},{"name":"Nhậm Mẫn","avatar":""},{"name":"Hoàng Lộ","avatar":""},{"name":"Cao Hâm","avatar":""},{"name":"Hàn Vân Vân","avatar":""},{"name":"Trương Phàm","avatar":""},{"name":"Trương Thừa","avatar":""},{"name":"Trâu Nguyên Thanh","avatar":""},{"name":"Vương Cung Lương","avatar":""},{"name":"Châu Dương Dương","avatar":""},{"name":"Lý Thành Nho","avatar":""},{"name":"Bao Bối Nhĩ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["开庭现场","我们与法庭的距离","가사법정 - 지금, 법정을 연다","가사법정","Family Court","家事法庭"]', 1784690324125);
