INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('salish-va-jordan-matter', 'Salish Và Jordan Matter', 'Salish & Jordan Matter', 'https://phimimg.com/upload/vod/20260415-1/6492cdf87df0d55668460714a4ae37f3.jpg', 'https://phimimg.com/upload/vod/20260415-1/c0229d0b48f9dcd8c8b331fc2d85896f.jpg', '<p>Hãy cùng theo chân hai cha con Jordan và Salish trải qua những tình huống oái oăm và những thử thách cực hạn trong bản tổng hợp các khoảnh khắc gia đình kinh điển này. Từ những trò đùa tinh quái đến những cuộc phiêu lưu đầy kịch tính, chương trình mang đến cái nhìn ấm áp và hài hước về tình cảm cha con gắn bó qua từng thử thách khó khăn nhất.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Salish Matter","avatar":""},{"name":"Jordan Matter","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Salish and Jordan Matter","Salish & Jordan Matter"]', 1784690324125);
