INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-anh-khong-kho-doan', 'Lòng Anh Không Khó Đoán', 'Born To Be The Villain', 'https://phimimg.com/upload/vod/20260415-1/6767e8498fe1c17e04f54e85ff9c9d73.jpg', 'https://phimimg.com/upload/vod/20260415-1/39a16b13490d5200e7091f6c3c560638.jpg', '<p>Lục Trình Văn vô tình xuyên vào thế giới tiểu thuyết, trở thành nhân vật phản diện được định sẵn kết cục chết thảm. Để bảo toàn tính mạng, anh ta quyết định nhẫn nhịn để sống qua ngày. Nào ngờ, hành động này lại vô tình khiến các nữ chính thức tỉnh khả năng đọc được suy nghĩ, khiến toàn bộ diễn biến cốt truyện bị xáo trộn hoàn toàn. Cuối cùng, anh ta quyết định bắt tay cùng nam chính của cuốn tiểu thuyết đã thức tỉnh là Cố Trảm Thiên, cùng chống lại &quot;Thiên đạo&quot; đang điều khiển số phận, từ đó tìm lại được chính mình và con đường trở về của mình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 12, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Hạo Quần","avatar":""},{"name":"Tiêu Vũ","avatar":""},{"name":"Quách Hinh Ngọc","avatar":""},{"name":"Đinh Tử Lãng","avatar":""},{"name":"Tôn Thiên Dữ","avatar":""},{"name":"Kỳ Thần","avatar":""},{"name":"Kim Lan Tịch","avatar":""},{"name":"Châu Mỹ Kỳ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["舔狗反派只想苟, 女主不按套路走","Ta Xin Bu Nan Ce","他心不难测"]', 1784690324125);
