INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tyson-fury-vs-arslanbek-makhmudov', 'Tyson Fury vs. Arslanbek Makhmudov', 'Tyson Fury vs. Arslanbek Makhmudov', 'https://phimimg.com/upload/vod/20260415-1/04615e84052ed957bce6962a296fc17a.jpg', 'https://phimimg.com/upload/vod/20260415-1/dbe83b9f2c4c432cae5db078c1ea7f2a.jpg', '<p>Trận đấu đánh dấu màn tái xuất của Tyson Fury sau thời gian giải nghệ, đối đầu với tay đấm mạnh mẽ Arslanbek Makhmudov.Fury nhanh chóng thể hiện đẳng cấp vượt trội nhờ kinh nghiệm, kỹ thuật và khả năng kiểm soát trận đấu. Sau vài hiệp đầu thăm dò, anh dần áp đảo, liên tục ghi điểm bằng các cú đấm chính xác và chiến thuật hợp lý.</p>', 'Full', 1, 'single', 'completed', 34, 2026, 'Vietsub', 'FHD', 'Ả Rập Xê Út', 0, '[{"name":"Tyson Fury","avatar":""},{"name":"Arslanbek Makhmudov","avatar":""},{"name":"Conor Benn","avatar":""},{"name":"Regis Prograis","avatar":""},{"name":"Jeamie Tshikeva","avatar":""},{"name":"Richard Riakporhe","avatar":""},{"name":"Justis Huni","avatar":""},{"name":"Frazer Clarke","avatar":""},{"name":"Simon Zachenhuber","avatar":""},{"name":"Pawel August","avatar":""},{"name":"Mikie Tallon","avatar":""},{"name":"Leandro Jose Blanc","avatar":""},{"name":"Breyon Gorham","avatar":""},{"name":"Eduardo Costa Do Nascimento","avatar":""},{"name":"Felix Cash","avatar":""},{"name":"Liam O&","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"}]', '["Fury vs. Makhmudov","Tyson Fury vs. Arslanbek Makhmudov"]', 1784690324125);
