INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuc-han', 'Cực Hạn', 'Climax', 'https://phimimg.com/upload/vod/20260317-1/a1b772bb127660d04caec55e9e078aae.jpg', 'https://phimimg.com/upload/vod/20260317-1/a48394f3e66faf31b648658324ef3381.jpg', '<p>Để cứu vãn sự nghiệp, công tố viên Bang Tae Seop lên kế hoạch phanh phui tội tham nhũng của thị trưởng Seoul và Lee Yang Mi, người đứng đầu tập đoàn WR. Đồng minh của anh bao gồm Hwang Jeong Won – cô gái nắm giữ nhiều bí mật của giới thượng lưu, và Kwon Jong Uk – thành viên của gia tộc WR nhưng lại ôm mối hận riêng với Yang Mi.

Mọi chuyện trở nên phức tạp khi Tae Seop phát hiện chính vợ anh cũng đang che giấu những bí mật vô cùng nguy hiểm. Đặt trong bối cảnh giao thoa giữa giới giải trí và tài phiệt, Đỉnh Cao Tham Vọng (Climax) khắc họa cuộc chiến quyền lực khốc liệt giữa những kẻ sẵn sàng đánh đổi tất cả để đứng trên đỉnh cao.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 19, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ju Ji-hoon","avatar":""},{"name":"Ha Ji-won","avatar":""},{"name":"Nana","avatar":""},{"name":"Cha Joo-young","avatar":""},{"name":"Oh Jung-se","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["权欲之巅","Апогей","Climax","클라이맥스"]', 1784690324125);
