INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noah-kahan-trai-nghiem-thoat-xac', 'Noah Kahan: Trải Nghiệm Thoát Xác', 'Noah Kahan: Out Of Body', 'https://phimimg.com/upload/vod/20260414-1/7abe8057621852e30ebf27835edee6e3.jpg', 'https://phimimg.com/upload/vod/20260414-1/507602a8b6c8a1988d507a958a13cb4f.jpg', '<p>Sau khi vụt sáng thành sao và nhận được sự nổi tiếng trên toàn cầu, nam ca sĩ kiêm nhạc sĩ Noah Kahan phải đối mặt với áp lực đè nặng trong việc thực hiện album tiếp theo. Để tìm lại sự cân bằng và kết nối lại với chính mình, anh quyết định trở về quê hương Vermont, tìm về với cội nguồn và gia đình. Bộ phim ghi lại hành trình tìm kiếm cảm hứng giữa những cảnh sắc quen thuộc, nơi anh cố gắng gạt bỏ những hào nhoáng bên ngoài để lắng nghe những giai điệu chân thực nhất từ sâu thẳm tâm hồn.</p>', 'Full', 1, 'single', 'completed', 23, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Noah Kahan","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '["Noah Kahan: Out of Body"]', 1784690324125);
