INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-nhan-dien-loan', 'Sát Nhân Điên Loạn', 'Psycho Killer', 'https://phimimg.com/upload/vod/20260413-1/3a8e0b8dc82d3c3f2a8e12d2cd54ba88.jpg', 'https://phimimg.com/upload/vod/20260413-1/3b96f466cacad6ea41a5598a9148ca79.jpg', '<p>Sau vụ sát hại dã man của người chồng, một nữ cảnh sát tuần tra đường cao tốc bang Kansas bắt đầu hành trình truy tìm hung thủ. Càng tiến sâu vào cuộc săn lùng, cô dần nhận ra kẻ đứng sau tội ác không chỉ là một tên sát nhân hàng loạt tàn bạo, mà còn là một kẻ biến thái bệnh hoạn với mức độ suy đồi tâm trí và âm mưu đen tối vượt xa mọi tưởng tượng.</p>', 'Full', 1, 'single', 'completed', 20, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Georgina Campbell","avatar":""},{"name":"James Preston Rogers","avatar":""},{"name":"Malcolm McDowell","avatar":""},{"name":"Logan Miller","avatar":""},{"name":"Grace Dove","avatar":""},{"name":"Aaron Merke","avatar":""},{"name":"Joshua Banman","avatar":""},{"name":"Cassandra Ebner","avatar":""},{"name":"Darren Martens","avatar":""},{"name":"Sydney Sabiston","avatar":""},{"name":"Nigel Shawn Williams","avatar":""},{"name":"Terry Ray","avatar":""},{"name":"Coby Friesen","avatar":""},{"name":"Bailey Chin","avatar":""},{"name":"Michelle Crossman","avatar":""},{"name":"Rachel Sheen","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["사이코 킬러","Psycho Killer"]', 1784690324125);
