INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-phe-thai', 'Kẻ Phế Thải', 'Wasteman', 'https://phimimg.com/upload/vod/20260413-1/a3b91eaf80a5b6d4bca4fc86dd86f246.jpg', 'https://phimimg.com/upload/vod/20260413-1/1b4dc05de3421d559d67df2b3224e543.jpg', '<p>Hy vọng về một khởi đầu mới sau khi ra tù của Taylor bị đe dọa bởi sự xuất hiện của người bạn tù Dee. Khi Dee che chở cho Taylor, một vụ tấn công tàn bạo đã thử thách mối quan hệ của họ, buộc Taylor phải lựa chọn giữa việc bảo vệ Dee và cơ hội tự do của chính mình.</p>', 'Full', 1, 'single', 'completed', 15, 2026, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"David Jonsson","avatar":""},{"name":"Tom Blyth","avatar":""},{"name":"Alex Hassell","avatar":""},{"name":"Neil Linpow","avatar":""},{"name":"Paul Hilton","avatar":""},{"name":"Corin Silva","avatar":""},{"name":"Layton Blake","avatar":""},{"name":"Jack Barker","avatar":""},{"name":"Fred Muthui","avatar":""},{"name":"Lunga Skosana","avatar":""},{"name":"Robert Rhodes","avatar":""},{"name":"Keaton Ancona-Francis","avatar":""},{"name":"Cole Martin","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wasteman"]', 1784690324125);
