INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-tuyet-yeti', 'Người tuyết Yeti', 'The Yeti', 'https://phimimg.com/upload/vod/20260413-1/5da1914ccf27a7ffa7593f1921368869.jpg', 'https://phimimg.com/upload/vod/20260413-1/59627d9b72349306d9b2fb2c25c9f95b.jpg', '<p>Khi một ông trùm dầu mỏ và một nhà thám hiểm nổi tiếng biến mất trong mùa đông khắc nghiệt ở vùng Alaska xa xôi phía bắc, một đội cứu hộ được lựa chọn kỹ lưỡng đã nỗ lực đưa họ trở về. Điều họ không biết là họ đang xâm phạm lãnh thổ của Người Tuyết Yeti, và thiên nhiên khắc nghiệt chỉ là mối lo nhỏ nhất của họ.</p>', 'Full', 1, 'single', 'completed', 9, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jim Cummings","avatar":""},{"name":"Brittany Allen","avatar":""},{"name":"Eric Nelsen","avatar":""},{"name":"Corbin Bernsen","avatar":""},{"name":"William Sadler","avatar":""},{"name":"Heather Lind","avatar":""},{"name":"Christina Bennett Lind","avatar":""},{"name":"Elizabeth Cappuccino","avatar":""},{"name":"Linc Hand","avatar":""},{"name":"Johnathan Brownlee","avatar":""},{"name":"Gene Gallerano","avatar":""},{"name":"Gina D''Acciaro","avatar":""},{"name":"Jeff Barry","avatar":""},{"name":"Zach Franklin","avatar":""},{"name":"Jimmy Mehs","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sniega cilvēks","The Yeti"]', 1784690324125);
