INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-dau', 'Cô Dâu!', 'The Bride!', 'https://phimimg.com/upload/vod/20260409-1/43305e5e217ff699a63ca56d2894a0cc.jpg', 'https://phimimg.com/upload/vod/20260409-1/d6269335b48762ea0beb444ec33237fd.jpg', '<p>Một cách tiếp cận táo bạo, phá vỡ mọi khuôn mẫu đối với một trong những câu chuyện hấp dẫn nhất thế giới. Bộ phim theo chân Frankenstein cô đơn (do Chrisitian Bale thủ vai) lên đường đến Chicago những năm 1930 để tìm đến nhà khoa học Dr. Euphronious (Annette Bening – 5 lần đề cử Oscar thủ vai), với hy vọng bà có thể tạo ra một người bạn đồng hành cho mình. Cả hai hồi sinh một cô gái trẻ đã bị sát hại, và Cô Dâu (Buckley thủ vai) đã ra đời. Những gì xảy ra sau đó đã vượt xa mọi tưởng tượng của họ: những vụ giết người, sự chiếm hữu, một phong trào văn hóa hoang dại và cấp tiến cũng như mối tình ngoài vòng pháp luật đầy cuồng nhiệt và bùng nổ!</p>', 'Full', 1, 'single', 'completed', 18, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Jessie Buckley","avatar":""},{"name":"Christian Bale","avatar":""},{"name":"Peter Sarsgaard","avatar":""},{"name":"John Magaro","avatar":""},{"name":"Jeannie Berlin","avatar":""},{"name":"Annette Bening","avatar":""},{"name":"Jake Gyllenhaal","avatar":""},{"name":"Penélope Cruz","avatar":""},{"name":"Zlatko Burić","avatar":""},{"name":"Louis Cancelmi","avatar":""},{"name":"Julianne Hough","avatar":""},{"name":"Matthew Maher","avatar":""},{"name":"Massiel Mordan","avatar":""},{"name":"Anthony Abbato","avatar":""},{"name":"Neil Vincent Smith","avatar":""},{"name":"Ethan Dubin","avatar":""},{"name":"Wil","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b