INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('theo-dau-toi-ac', 'Theo Dấu Tội Ác', 'The Sin Trade', 'https://phimimg.com/upload/vod/20260410-1/a2a4aa808ad1e6af220eb525bd2ee13f.jpg', 'https://phimimg.com/upload/vod/20260410-1/895471e7964fe16464d58b0c662172de.jpg', '<p>Ở vùng núi, nạn buôn người hoành hành. Cảnh sát Trì Phong một mình thâm nhập tìm hung thủ, giải cứu nạn nhân trong hầm, đối mặt với dân làng bạo loạn, đẫm máu chiến đấu trong hộp đêm. Anh thề sẽ dùng bạo lực để trấn áp bạo lực, bảo vệ công lý pháp luật.</p>', 'Full', 1, 'single', 'completed', 14, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Ashton Chen","avatar":""},{"name":"Wang Zhener","avatar":""},{"name":"Liu Fengchao","avatar":""},{"name":"Liu Yitong","avatar":""},{"name":"Mao Fan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324125);
