INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-nhan-giau-mat-chuong-3', 'Sát Nhân Giấu Mặt: Chương 3', 'The Strangers: Chapter 3', 'https://phimimg.com/upload/vod/20260413-1/1ed2158d188345ca1d9697786946a184.jpg', 'https://phimimg.com/upload/vod/20260413-1/19be01aba2e20bfc66943ad1dc0e9e2f.jpg', '<p>Bị trói chặt bởi một kết cục đáng sợ, Maya và những kẻ xa lạ bị cuốn vào quỹ đạo va chạm không thể tránh khỏi — tàn nhẫn và không khoan nhượng. Cuộc đối đầu cuối cùng ấy phơi bày một sự thật rõ ràng: họ đã không còn là những người xa lạ từ lâu.</p>', 'Full', 1, 'single', 'completed', 15, 2026, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Madelaine Petsch","avatar":""},{"name":"Richard Brake","avatar":""},{"name":"Ema Horvath","avatar":""},{"name":"Gabriel Basso","avatar":""},{"name":"Pedro Leandro","avatar":""},{"name":"Rachel Shenton","avatar":""},{"name":"George Young","avatar":""},{"name":"Kyle Breitkopf","avatar":""},{"name":"Finn Cofell","avatar":""},{"name":"Stevee Davies","avatar":""},{"name":"Hannah Galway","avatar":""},{"name":"Sara Freedland","avatar":""},{"name":"Dani Klupsch","avatar":""},{"name":"Ella Bruccoleri","avatar":""},{"name":"Krystal Ellsworth","avatar":""},{"name":"Janis Ahern","avatar":""},{"name":"Pablo Sands","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Os Estranhos: Capítulo 3","The Strangers","Strangers: Capítulo final","The Strangers: Chapter 3"]', 1784690324125);
