INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xam-nhap-2026', 'Xâm Nhập', 'Infiltrate', 'https://phimimg.com/upload/vod/20260413-1/52491defed326cb42e4ac1c983ef517c.jpg', 'https://phimimg.com/upload/vod/20260413-1/5511c298c0d6f1872aa2cfdec65e0b14.jpg', '<p>Trong một thành phố ngập tràn tội phạm, đặc vụ chính phủ Lily Chen buộc phải lựa chọn giữa nhiệm vụ và gia đình khi chồng cô bị bắt cóc, và cô bị tống tiền để ám sát những tên tội phạm cấp cao nhằm cứu anh ta. Khi dấn thân sâu hơn vào thế giới ngầm tội phạm, cuộc truy tìm công lý không ngừng nghỉ của Lily đã vạch trần một mạng lưới tham nhũng, dẫn đến một quyết định cuối cùng, thay đổi cuộc đời cô mãi mãi.</p>', 'Full', 1, 'single', 'completed', 24, 2026, 'VIetsub', 'FHD', 'Canada', 0, '[{"name":"Orphée Ladouceur-Nguyen","avatar":""},{"name":"Alain Moussi","avatar":""},{"name":"Tim Rozon","avatar":""},{"name":"Finn McCager Higgins","avatar":""},{"name":"Lisa Berry","avatar":""},{"name":"Paul Braunstein","avatar":""},{"name":"Jason Cavalier","avatar":""},{"name":"Jonathan Goad","avatar":""},{"name":"Mitra Suri","avatar":""},{"name":"Jeff Yung","avatar":""},{"name":"Aniko Kaszas","avatar":""},{"name":"Jason Gosbee","avatar":""},{"name":"Allen Keng","avatar":""},{"name":"Phi Huynh","avatar":""},{"name":"Sean Jones","avatar":""},{"name":"Stéphane Julien","avatar":""},{"name":"Dennis Lafond","avatar":""},{"name":"Greg","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["인필트레이트","Infiltrate"]', 1784690324125);
