INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-to-du-doi', 'Bão Tố Dữ Dội', 'Sharp Downpour', 'https://phimimg.com/upload/vod/20260406-1/6f1fb2abf8e481c29a540570c085e613.jpg', 'https://phimimg.com/upload/vod/20260406-1/10820dd6e425eb126e1d5111d470e6b4.jpg', '<p>Nữ cảnh sát Lộc Nhất suốt nhiều năm qua luôn bị những cơn ác mộng đeo bám, nhưng vẫn âm thầm kiên trì điều tra sự thật về vụ án khiến cha cô bị trọng thương và rơi vào hôn mê. Trong quá trình điều tra, cô tình cờ gặp nữ cảnh sát lạnh lùng Lâm Thâm. Cả hai cùng nhau phá giải hàng loạt vụ án mạng ly kỳ, bí ẩn. Khi tình đồng đội ngày càng gắn bó, Lộc Nhất dần phát hiện Lâm Thâm dường như có liên quan mật thiết đến vụ án cũ của cha mình…</p>', 'Tập 19', 20, 'series', 'ongoing', 21, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Mộc Thần","avatar":""},{"name":"Tuyên Lộ","avatar":""},{"name":"Đỗ Dận Vĩ","avatar":""},{"name":"Nghê Cảnh Dương","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Storm","暴锋雨"]', 1784690324125);
