INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-diep-vien-ngam', 'Nữ Điệp Viên Ngầm', 'Pretty Dangerous', 'https://phimimg.com/upload/vod/20260324-1/657ff08e59d1560a18cdccbf27a17c93.jpg', 'https://phimimg.com/upload/vod/20260324-1/bf31b8e6cedf3c1af02da6db86c430ef.jpg', '<p>Thanh tra Phan Dịch Phong sau nhiều năm nằm vùng đã thành công đưa Quyền Thế Hào - kẻ cầm đầu đường dây sản xuất ma túy &quot;Bột Tinh Linh&quot; - ra trước vành móng ngựa. Tuy nhiên, bằng thủ đoạn tinh vi, Thế Hào chỉ nhận mức án nhẹ. Lo ngại Thế Hào sau khi ra tù sẽ tiếp tục gieo rắc tội ác, Dịch Phong đề xuất thành lập một đội nữ điệp viên, bí mật truy tìm kẻ cung cấp nguyên liệu, nhằm triệt phá tận gốc chuỗi sản xuất ma túy &quot;Bột Tinh Linh&quot;. Ba nữ điệp viên được tuyển chọn đều sở hữu năng lực vượt trội: Thẩm Giai Kỳ được ví như &quot;Nữ Sherlock Holmes&quot;, Giang Diệu Tư - cao thủ võ thuật, đầu óc nhạy bén và Đồng Tiểu Như - &quot;kho dữ liệu di động&quot; với khả năng biến hóa linh hoạt. Giữa áp lực từ nội bộ và nguy hiểm luôn rình rập, Dịch Phong vẫn kiên trì thúc đẩy nhiệm vụ, bởi đằng sau chiến dịch này, anh còn mang trong lòng một mục đích riêng: tìm ra hung thủ đã sát hại bạn gái mình…</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 26, 2026, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Mã Quán Đông","avatar":""},{"name":"Trương Hy Văn","avatar":""},{"name":"Trần Oánh","avatar":""},{"name":"La Dục Nghi","avatar":""},{"name":"Chung Nhu Mỹ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["特勤女团","特勤女團","特勤女將","臥底嬌娃"]', 1784690324125);
