INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rung-thep', 'Rừng Thép', 'Sunsets Secrets Regrets', 'https://phimimg.com/upload/vod/20260404-1/02949ec5a3960d592e7c5b45ef159336.jpg', 'https://phimimg.com/upload/vod/20260404-1/47285dd5514f9846167e47c352e3c6c3.jpg', '<p>Một thi thể nữ đã hé lộ những manh mối hoàn toàn mới cho vụ án treo &quot;8.17&quot; năm xưa, khiến hồ sơ vụ án chính thức được lật lại. Chu Cẩn (Thái Văn Tĩnh thủ vai), một nữ cảnh sát hình sự, vô cùng chấn động khi giáo sư tâm lý học tội phạm Giang Hàn Thanh (Tỉnh Bách Nhiên thủ vai) bất ngờ gia nhập chuyên án. Càng bất ngờ hơn khi người chồng &quot;cưới hỏi thần tốc&quot; của cô hóa ra từng là cảnh sát của sở tỉnh, và mũi dùi điều tra hiện đang chĩa thẳng vào Tưởng Thành (Tần Tuấn Kiệt thủ vai) – người yêu đầu thanh mai trúc mã của cô.&nbsp; Ba con người vốn đang bị mắc kẹt trong vũng lầy của quá khứ vì vụ án năm xưa lại một lần nữa rơi vào vòng xoáy ân oán. Liệu họ có thể vượt qua tầng tầng lớp lớp bí mật và cạm bẫy để tìm ra sự thật, chữa lành cho những người mình yêu thương? Đó chính là câu đố nan giải nhất mà định mệnh đã đặt ra.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 15, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tỉnh Bách Nhiên","avatar":""},{"name":"Thái Văn Tĩnh","avatar":""},{"name":"Tần Tuấn Kiệt","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Gang Tie Sen Lin","Steel Forest","钢铁森林"]', 1784690324125);
