INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chim-an-lua-doi-cuu-hoa-rach-ruoi-vung-ushu', 'Chim Ăn Lửa: Đội Cứu Hỏa Rách Rưới Vùng Ushu', 'Oedo Fire Slayer: The Legend Of Phoenix', 'https://phimimg.com/upload/vod/20260112-1/bf4bb9d5b12f2b297cc654cd23b1b171.jpg', 'https://phimimg.com/upload/vod/20260112-1/8011193ce2592362aa12ed84da2cac33.jpg', '<p>&quot;Gengo Matsunaga, người từng vang danh với biệt hiệu &#39;Phượng Hoàng&#39;, là võ sĩ diệt hỏa vĩ đại nhất khắp vùng Edo. Sau khi gác kiếm từ bỏ nghề chữa cháy, Gengo nhận được lời mời từ phiên bang Shinjo. Được sự cổ vũ từ người vợ Miyuki, ông đã lên đường để gây dựng lại một đội cứu hỏa vốn đã lụi tàn. Gengo tập hợp một nhóm những kẻ &#39;bất đắc chí&#39; và lập nên Đội diệt hỏa Ragged (Nhóm diệt hỏa rách rưới), cùng nhau điều tra những vụ hỏa hoạn bí ẩn được gây ra bởi kẻ phóng hỏa khét tiếng Kitsunebi (Hỏa Hồ).</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 19, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuuichirou Umehara","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["大江戶 烈火殺手 鳳凰傳說","大江户 烈火杀手 凤凰传说","烈火杀手","烈火殺手","大江户烈火杀手：凤凰传说","火喰鳥","Hikuidori","Hikuidori: Ushuboro Tobigumi","Hikuidori: Ushuu Boro Tobi-gumi","Hikuidori Ushūboro Tobigumi","Hi no Tori Hagoromohen","火喰鳥 羽州ぼろ鳶組"]', 1784690324125);
