INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('minh-chau-ky-dam-phan-2', 'Minh Châu Kỳ Đàm (Phần 2)', 'The Secret Of The Lost Pearl (Season 2)', 'https://phimimg.com/upload/vod/20260401-1/18d5541c204657907c4c083b0636eb70.jpg', 'https://phimimg.com/upload/vod/20260401-1/69116df39c813bf034baa0675bce66a1.jpg', '<p>Chuyên gia khảo cổ - văn vật Trần Hữu Hy tập hợp đội ngũ, dấn thân vào Trùng Cốc bí ẩn truy tìm ngọc Linh Tiêu. Trên hành trình, họ gặp tiến sĩ sinh học Đinh Hiểu Minh. Thoát khỏi sự truy sát của những kẻ canh giữ kho báu suốt nhiều thế hệ, cả đoàn lại phát hiện bộ mặt thật của Đinh Hiểu Minh – kẻ đang âm mưu chiếm đoạt ngọc Linh Tiêu! Liệu họ có thể tránh được những đòn tập kích chí mạng và bảo vệ bảo vật truyền đời?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 16, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tiêu Thuận Nghiêu","avatar":""},{"name":"Trương Chỉ Khê","avatar":""},{"name":"Lý Nhược Đồng","avatar":""},{"name":"Lý Trấn Trạch","avatar":""},{"name":"Tín Bằng","avatar":""},{"name":"Triệu Nghị","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["鬼吹灯","Ming Zhu Qi Tan","​明珠奇谭第二季​","​明珠奇谭第三季​","Candle in the Tomb","Ghost Blows Out the Light","The Secret of the Lost Pearl S3","明珠奇谭"]', 1784690324125);
