INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-la-niem-vui-den-muon', 'Em Là Niềm Vui Đến Muộn', 'You Are My Fateful Love', 'https://phimimg.com/upload/vod/20260327-1/2150c9e59a708e8a8a02df9d30d612d9.jpg', 'https://phimimg.com/upload/vod/20260327-1/b620853af2ef56a4fa2db9b684b372c1.jpg', '<p>Nguyễn Dụ đã viết một tiểu thuyết dựa trên mối tình thầm kín thời trung học của mình, bất ngờ trở nên nổi tiếng nhưng lại vướng vào tranh chấp đạo văn. Cô quyết định khởi kiện, nhưng không ngờ người phụ trách vụ án bên phía luật sư lại chính là Hứa Hoài Tụng, nguyên mẫu của nam chính trong tiểu thuyết. Hai người giả vờ như không quen biết, nhưng trong quá trình làm việc đầy căng thẳng và giằng co, họ dần ghép lại những mảnh ký ức của mối tình thầm lặng năm xưa.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 21, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Phương Đồng","avatar":""},{"name":"Trương Hạo Nhiên","avatar":""},{"name":"Lý Phi","avatar":""},{"name":"Vương Nhất Nặc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ni Shi Chi Lai De Huan Xi","你是迟来的欢喜"]', 1784690324125);
