INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-quan-hai-mat-cua-ta', 'Phu Quân Hai Mặt Của Ta', 'Destined Love', 'https://phimimg.com/upload/vod/20260411-1/b1de3ac52af01500af6ace333617a8cd.jpg', 'https://phimimg.com/upload/vod/20260411-1/98642b4412bebeb9d1ec624ebaa88db0.jpg', '<p>Để trả thù cho thanh mai trúc mã Cố Thành Ngọc, Mộc Cửu Vân đã ngụy trang thành công chúa hòa thân để gả cho chiến thần mặt sắt Mặc Ngọc. Tuy nhiên, cô bàng hoàng nhận ra mọi cử chỉ, lời nói của Mặc Ngọc đều giống hệt người quá cố Cố Thành Ngọc. Trong khi đó, người trợ thủ Tô Thành lại nắm rõ những bí mật mà vốn chỉ có cô và Cố Thành Ngọc mới biết. Để tìm ra sự thật, Mộc Cửu Vân sẽ phải hành động ra sao? Ai mới thực sự là Cố Thành Ngọc, ai là cái bóng thay thân, sự thật phía sau vô cùng mờ mịt và khó đoán.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 18, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tống Bội Trạch","avatar":""},{"name":"Cáo Tư Văn","avatar":""},{"name":"Trần Thánh Hanh","avatar":""},{"name":"Du Tư Viễn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["我的双面夫君"]', 1784690324125);
