INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuy-trieu-len-knokke-off-phan-3', 'Thủy Triều Lên (Knokke Off) (Phần 3)', 'High Tides (Season 3)', 'https://phimimg.com/upload/vod/20260411-1/8a00ad7ffd4433b2b47f0160cc0c3a63.jpg', 'https://phimimg.com/upload/vod/20260411-1/f5b6f76603592329e1bb5db20395cfa4.jpg', '<p>Tình yêu. Dục vọng. Dối trá. Những lâu đài thần thánh của giới thượng lưu bờ biển Bỉ che giấu mạng lưới bê bối có thể hủy hoại cuộc sống chỉ trong chớp mắt.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 26, 2026, 'Vietsub', 'FHD', 'Bỉ', 0, '[{"name":"Pommelien Thijs","avatar":""},{"name":"Willem De Schryver","avatar":""},{"name":"Eliyha Altena","avatar":""},{"name":"Anna Drijver","avatar":""},{"name":"Manouk Pluis","avatar":""},{"name":"Ayana Doucouré","avatar":""},{"name":"Kes Bakker","avatar":""},{"name":"Jef Hellemans","avatar":""},{"name":"Ruth Becquart","avatar":""},{"name":"Geert Van Rampelberg","avatar":""},{"name":"Ini Massez","avatar":""},{"name":"Jasmine Sendar","avatar":""},{"name":"Emma Moortgat","avatar":""},{"name":"Caroline Stas","avatar":""},{"name":"Felicia Van Remoortel","avatar":""},{"name":"Pieter Genard","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["High Tides","Knokke off"]', 1784690324125);
