INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-phong-tam-quoc', 'Băng Phong Tam Quốc', 'Frozan Three Kingdoms (Ice War Three Kingdoms)', 'https://phimimg.com/upload/vod/20260411-1/5b4944ec65680b02bcbcd700f22fea32.jpg', 'https://phimimg.com/upload/vod/20260411-1/ea58e34a098ee95e0f7f7a10a122fef1.jpg', '<p>Nhân viên văn phòng hiện đại Lưu Thừa tình cờ xuyên không về thời kỳ Tam Quốc giữa mùa đông giá rét, khi sông ngòi đóng băng và dân chúng lầm than. Không chỉ đối mặt với thiên nhiên khắc nghiệt, thế giới này còn bị xáo trộn bởi những người chịu ảnh hưởng từ linh lực kỳ bí. Trong tình thế nguy cấp, Lưu Thừa đã dùng kỹ năng chiến đấu hiện đại để bảo vệ trẻ nhỏ và gặp gỡ Triệu Vân – vị tướng trẻ mặc giáp bạc, tay cầm trường thương. Cả hai nhanh chóng kết hợp, cùng Bùi Nguyên Thiệu bình định loạn lạc và cứu được Thanh Y khi cô đang xuống núi tìm thảo dược.&nbsp; Để bảo vệ bá tánh, ba người cùng đến hội minh ở Toan Tảo. Tại cửa ải Tị Thủy, Lưu Thừa nhìn ra sơ hở của Hoa Hùng, âm thầm hỗ trợ giải vây cho Quan Vũ. Đến dưới chân thành Hổ Lao, anh bất chấp linh lực bất ổn để cứu Quan Vũ và Trương Phi thoát thân, trong khi Thanh Y tiêu hao tâm sức dùng thuật trị thương để ổn định sức mạnh cho anh. Sau khi theo Lưu Bị đến Dĩnh Xuyên, Lưu Thừa dùng kiến thức hiện đại để xây lò nung sưởi ấm và dựng nhà kính trồng lương thực, biến vùng đất hoang tàn thành nơi an cư lạc nghiệp. Khi quân của Viên Thiệu áp sát, anh dẫn dắt dân chúng chế tạo khí giới, kiên cường thủ vững nhà cửa. Giữa loạn thế băng giá, câu chuyện về một người bình thường nỗ lực thắp lên hy vọng sắp sửa bắt đầu.</p>', 'Hoàn Tất (9/9)', 9, 'hoathinh', 'completed', 20, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["冰封三国"]', 1784690324125);
