INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trot-yeu-quy-co-lanh-lung', 'Trót Yêu Quý Cô Lạnh Lùng', 'Frozen Valentine', 'https://phimimg.com/upload/vod/20260301-1/cc1a7638e020b62d99fc8bc52e50ff87.jpg', 'https://phimimg.com/upload/vod/20260301-1/4f1aa86e27b697fddb144c1a21f3ed62.jpg', '<p>Pingrak là một nữ sinh đại học sở hữu ngoại hình thu hút và cực kỳ nổi tiếng trong mắt bạn bè. Thế nhưng, ít ai biết rằng cô từng là một cô nàng &#39;mọt sách&#39; nhút nhát với cặp kính cận dày cộm, người đã đem lòng thầm yêu một đàn chị khóa trên xinh đẹp nhưng lạnh lùng như băng giá.&nbsp; Thế rồi định mệnh đã sắp đặt một bước ngoặt. Pingrak bất ngờ tái ngộ với mối tình đầu của mình — &#39;P’Charm, người con gái băng giá&#39;.&nbsp; Về phần P’Charm, cô hoàn toàn không hề hay biết rằng mỹ nhân vạn người mê trước mắt lại chính là đứa trẻ đeo kính cận từng lẽo đẽo đi theo mình năm xưa. Liệu P’Charm sẽ nghĩ gì nếu biết được cô gái này từng dành cho mình một tình cảm sâu đậm đến thế?</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 18, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Natthamon Jantraviphart","avatar":""},{"name":"Purichaya Saranark","avatar":""},{"name":"Inthira Sae-sieo","avatar":""},{"name":"Nichapat Sujipinyo","avatar":""},{"name":"Peerada Namwong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["冰冻情人节","Frozen Valentine ปิ๊งรักคุณพี่เย็นชา","ปิ๊งรักคุณพี่เย็นชา"]', 1784690324125);
