INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-vu-mi7', 'Đặc vụ MI7', 'Happy Patel: Khatarnak Jasoos', 'https://phimimg.com/upload/vod/20260409-1/a07c603229150beb7281b705fba00391.jpg', 'https://phimimg.com/upload/vod/20260409-1/c32c90eacf6b72fa62f7054f6464e664.jpg', '<p>Đặc vụ MI7 Happy Patel, người luôn gặp thất bại trong các nhiệm vụ, cuối cùng cũng được giao một nhiệm vụ ở Goa, nơi anh phát hiện ra nguồn gốc Ấn Độ của mình và phải giải cứu một nhà khoa học nổi tiếng khỏi tay trùm tội phạm Mama. Không hề hay biết về dòng dõi Ấn Độ của mình và lại nói giọng Anh một cách hài hước, những sai lầm của Happy đã gây ra một loạt sự cố hỗn loạn có thể dẫn anh đến việc vạch trần một mạng lưới tội phạm.</p>', 'Full', 1, 'single', 'completed', 16, 2026, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Vir Das","avatar":""},{"name":"Mona Singh","avatar":""},{"name":"Mithila Palkar","avatar":""},{"name":"Sharib Hashmi","avatar":""},{"name":"Srushti Tawade","avatar":""},{"name":"Aamir Khan","avatar":""},{"name":"Imran Khan","avatar":""},{"name":"Andrew Sloman","avatar":""},{"name":"Simon Fielder","avatar":""},{"name":"Prajakta Kavalekar","avatar":""},{"name":"Sumukhi Suresh","avatar":""},{"name":"Sharvari Deshpande","avatar":""},{"name":"Ojasvi Bhatti","avatar":""},{"name":"Jehan Khambatta","avatar":""},{"name":"Gunja Javani","avatar":""},{"name":"Krishiv Bhandari","avatar":""},{"name":"Jemima Dunn","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["हैप्पी पटेल: ख़तरनाक जासूस"]', 1784690324126);
