INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diem-luu-cuoi-cung', 'Điểm lưu cuối cùng', 'Last Save Point', 'https://phimimg.com/upload/vod/20260409-1/f35a907014296dd89b9039953547f4c2.jpg', 'https://phimimg.com/upload/vod/20260409-1/c482f94adfb990f223207b9479b5f306.jpg', '<p>Trong một thế giới hoang tàn, hậu tận thế, sự sống còn mong manh và lòng tin đầy nguy hiểm. Khi một kẻ cô độc chai sạn phát hiện ra một người đàn ông ngây thơ với tâm hồn trẻ con, cả hai hình thành một liên minh bất đắc dĩ, hành trình của họ va chạm với một ngôi trường hiểm ác, nơi những học sinh cũ (nay đã trưởng thành) vẫn bị chi phối bởi những nhân vật quyền lực của quá khứ. Nỗi sợ hãi, những bí mật và những mối đe dọa ngăn cản họ khám phá những gì nằm ngoài khu vực khép kín của cộng đồng.</p>', 'Full', 1, 'single', 'completed', 8, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jonathan Abbott","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Last Save Point"]', 1784690324126);
