INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truot-bang-xuong-dia-nguc', 'Trượt băng xuống địa ngục', 'Skate to Hell', 'https://phimimg.com/upload/vod/20260409-1/619f44630a32b3e9eebc4feeecf62595.jpg', 'https://phimimg.com/upload/vod/20260409-1/eaaf8bf318f2866126c40693d4ebe42a.jpg', '<p>Một nhóm thiếu niên đã đánh cắp một chiếc ván trượt siêu nhiên thuộc sở hữu của con trai quỷ Satan. Giờ đây, ác quỷ muốn lấy lại nó.</p>', 'Full', 1, 'single', 'completed', 8, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Eric Roberts","avatar":""},{"name":"Todd Bridges","avatar":""},{"name":"Jenna Jameson","avatar":""},{"name":"Robert Carradine","avatar":""},{"name":"James Duval","avatar":""},{"name":"Robert LaSardo","avatar":""},{"name":"Spencer Breslin","avatar":""},{"name":"Lorelei Linklater","avatar":""},{"name":"Oliver Robins","avatar":""},{"name":"Lisa Wilcox","avatar":""},{"name":"Nicole Butler","avatar":""},{"name":"Douglas Tait","avatar":""},{"name":"Scott Schwartz","avatar":""},{"name":"Kevin Duffy","avatar":""},{"name":"Brett Wagner","avatar":""},{"name":"Shawn C. Phillips","avatar":""},{"name":"Eileen Die","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Skate to Hell"]', 1784690324126);
