INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doan-ket', 'Đoàn Kết', 'Bandi', 'https://phimimg.com/upload/vod/20260410-1/23de3fadb2d99ec1c35e1b228e294238.jpg', 'https://phimimg.com/upload/vod/20260410-1/e01b28839bed86286b5403bc0630c596.jpg', '<p>Sau cái chết của mẹ — chỗ dựa tinh thần và là điểm tựa vững chắc của họ — mười một anh chị em, từ 7 đến 23 tuổi, cố gắng giữ vững sự đoàn kết trước nghịch cảnh. Nhưng đối với một số người trong số họ, buôn bán ma túy dường như là con đường duy nhất để sinh tồn. Đây là một quyết định không hề được tất cả đồng thuận, và nó đã đặt sức mạnh gắn kết của gia đình họ vào thử thách khắc nghiệt.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 17, 2026, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Rudgy Pajany","avatar":""},{"name":"Jonathan Zaccaï","avatar":""},{"name":"Rémy Laquittant","avatar":""},{"name":"Djody Grimeau","avatar":""},{"name":"William Paul-Joseph","avatar":""},{"name":"Evan Lienafa","avatar":""},{"name":"Ambre Bozza","avatar":""},{"name":"Souane Rosamont","avatar":""},{"name":"Steeven Mornet","avatar":""},{"name":"Lucas Pernock","avatar":""},{"name":"Rodney Dijon","avatar":""},{"name":"Patrick Trieste","avatar":""},{"name":"Cédric Camille","avatar":""},{"name":"Hay-Lee-Jah Caloc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Bandi"]', 1784690324126);
