INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-thanh-pho-an-danh', 'Anh Hùng Thành Phố Ẩn Danh', 'Hero in the Hidden CIty', 'https://phimimg.com/upload/vod/20260410-1/0a261668cb4b257925e5ce78e1eff18c.jpg', 'https://phimimg.com/upload/vod/20260410-1/42d5347733e41e132bb55b18f987413b.jpg', '<p>Nội dung cốt lõi của bộ phim là sự “thức tỉnh phi điển hình” của những con người tầng lớp dưới trong thời loạn lạc thời Dân Quốc — lấy khu nhà đại tạp viện như một không gian thị dân khép kín. Các nhân vật như Từ Thiên, Điền Đan, Bát Cô… từ chỗ “nhẫn nhịn để sinh tồn” dần chuyển sang “chủ động phản kháng vì gia đình và đất nước”. Câu chuyện xoay quanh việc những con người nhỏ bé dùng trí tuệ dân gian để chống lại cường quyền, và trong sự lương thiện giản dị lại ẩn chứa nghĩa lớn, tạo nên hành trình phản công trong bước đường cùng.</p>', 'Full', 1, 'single', 'completed', 9, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Peng Yusi","avatar":""},{"name":"Lian Yiming","avatar":""},{"name":"王莎","avatar":""},{"name":"Yu Lihong","avatar":""},{"name":"Lai Xi","avatar":""},{"name":"Ma Shihong","avatar":""},{"name":"Zhai Xingyue","avatar":""},{"name":"Zhang Jiahao","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["隐市英雄"]', 1784690324126);
