INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lieu-phap-su-that-phan-3', 'Liệu Pháp Sự Thật (Phần 3)', 'Shrinking (Season 3)', 'https://phimimg.com/upload/vod/20260129-1/d7d51b0ba8f65297360c1d067219a947.jpg', 'https://phimimg.com/upload/vod/20260129-1/5bff88fd0dd2f5f25e4d0b6e709cb4de.jpg', '<p>Jimmy đang vật lộn để vượt qua nỗi đau mất vợ trong khi vẫn phải làm cha, làm bạn và làm nhà trị liệu. Anh quyết định thử cách tiếp cận mới với mọi người: thẳng thắn không kiêng nể. Liệu điều đó có khiến mọi chuyện trở nên tốt hơn — hay sẽ gây ra hỗn loạn?</p>', 'Full', 11, 'series', 'completed', 15, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jason Segel","avatar":""},{"name":"Harrison Ford","avatar":""},{"name":"Jessica Williams","avatar":""},{"name":"Luke Tennie","avatar":""},{"name":"Michael Urie","avatar":""},{"name":"Lukita Maxwell","avatar":""},{"name":"Christa Miller","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["诊疗中","诚实诊疗室","Terapia sin filtro","שרינקינג","シュリンキング 悩めるセラピスト","Мозгоправство","Shrinking"]', 1784690324126);
