INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-thuyet-linh-tinh-linh-tinh-truyen', 'Truyền Thuyết Linh Tinh (Linh Tinh Truyện)', 'Legend Of Ling Jing', 'https://phimimg.com/upload/vod/20260409-1/95a669c077e681e2317ecf6e9ed6b3d7.jpg', 'https://phimimg.com/upload/vod/20260409-1/8747b92390dfae3a02f753124da724e9.jpg', '<p>Linh Tinh Truyện dựa trên truyền thuyết Bạch Xà, tái hiện lại kiếp trước và kiếp này của Bạch Tô. Kiếp trước cô là con nuôi của một vị tướng quân, phải chia cắt, sinh ly tử biệt với huynh trưởng thanh mai trúc mã do thế tục. Kiếp này cô mượn thân xác của yêu quái tái sinh, cùng tỷ muội Tinh Cô ngao du nhân gian gian nhưng lại tình cờ gặp gỡ và phải lòng con trai của cố nhân là Hứa Tuyên. Khi luân hồi định mệnh xoay vần, ân oán lại nổi lên, mối tình cấm kỵ vượt qua ranh giới người và yêu ấy sẽ đi về đâu?</p>', 'Full', 1, 'single', 'completed', 11, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hồ Duyệt","avatar":""},{"name":"Cung Tiểu Quân","avatar":""},{"name":"Mạnh Lộ","avatar":""},{"name":"Hà Thông Duệ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Legend of Lingjing","灵菁传"]', 1784690324126);
