INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('truyen-thuyet-linh-tinh-linh-tinh-truyen', 'Truyền Thuyết Linh Tinh (Linh Tinh Truyện)', 'Legend Of Ling Jing', 'truyền thuyết linh tinh (linh tinh truyện) legend of ling jing hồ duyệt cung tiểu quân mạnh lộ hà thông duệ the legend of lingjing 灵菁传', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-dao-sac-ben-phong-chien-si', 'Thanh Đao Sắc Bén: Phong Chiến Sĩ', 'Blade Warrior Of Blade Action', 'https://phimimg.com/upload/vod/20260409-1/c268434f256487f4b88a485aa522f53f.jpg', 'https://phimimg.com/upload/vod/20260409-1/f45ba20856aa75611ff3e70a72ca79b0.jpg', '<p>Đội cảnh sát đặc nhiệm của Trình Cương, dưới sự chỉ huy và lên kế hoạch tài tình của Cục trưởng Trần Hải An, đã bước vào một cuộc chiến cân não và đầy kịch tính với tập đoàn buôn lậu do Hoàng Tán cầm đầu. Để phá giải vụ án buôn lậu cổ vật và vây quét các phần tử tội phạm, các chiến sĩ đặc nhiệm – đặc biệt là Trình Cương và Thẩm Hân – đã phải đánh đổi bằng những hy sinh to lớn và sự cống hiến quên mình. Cuối cùng, họ đã thành công tóm gọn toàn bộ băng nhóm tội phạm, bảo vệ bình yên cho xã hội.</p>', 'Full', 1, 'single', 'completed', 14, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Bác Nam","avatar":""},{"name":"Ngụy Tiểu Hoan","avatar":""},{"name":"Kỷ Soái","avatar":""},{"name":"Vương Nghị Phàm","avatar":""},{"name":"Mã Sướng","avatar":""},{"name":"Vương Cương","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Blade.Warrior.of.Blade.Action","利刃之刀锋战士"]', 1784690324126);
