INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-that-va-bi-kich-cua-moriah-wilson', 'Sự Thật Và Bi Kịch Của Moriah Wilson', 'The Truth And Tragedy Of Moriah Wilson', 'https://phimimg.com/upload/vod/20260409-1/2a1cfc2840c3a521d512873e0816e155.jpg', 'https://phimimg.com/upload/vod/20260409-1/3a6dbd19a057526c48b59f4f96f85f25.jpg', '<p>Đi sâu hơn những dòng tít báo, bộ phim tài liệu này khắc họa cuộc đời đầy sức sống của tay đua Moriah Wilson, vụ án mạng gây chấn động và nỗ lực né tránh sự truy bắt của kẻ gây án.</p>', 'Full', 1, 'single', 'completed', 14, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Olivia Sinnott","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["The Truth and Tragedy of Moriah Wilson"]', 1784690324126);
