INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('su-that-va-bi-kich-cua-moriah-wilson', 'Sự Thật Và Bi Kịch Của Moriah Wilson', 'The Truth And Tragedy Of Moriah Wilson', 'sự thật và bi kịch của moriah wilson the truth and tragedy of moriah wilson olivia sinnott the truth and tragedy of moriah wilson', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-vu-tran', 'Mê Vụ Trấn', 'Shrouded Hamet', 'https://phimimg.com/upload/vod/20260409-1/9a441d4d1bb07f3440300e2564158019.jpg', 'https://phimimg.com/upload/vod/20260409-1/77c8067ebfc69014a9ac293b39f1a061.jpg', '<p>Trong màn sương dày đặc, mọi người dân trong thị trấn đều bị những tấm gương nhào nặn thành một khuôn mẫu giống hệt nhau. Khi người bạn thân duy nhất không chấp nhận sự đồng hóa – A Triệt – đột ngột mất tích, cô gái nhỏ bé và nhút nhát Hiểu Dật đã lần theo những manh mối mong manh để xông vào Gương Từ (đền thờ gương). Tại đây, cô phát hiện A Triệt đang bị giam cầm trong một thế giới gương, nơi nỗi sợ hãi nuốt chửng lòng người và sự áp bức sẽ nhân bản ra một &quot;bản sao&quot; khác của chính mình. Để giải cứu bạn, Hiểu Dật phải đối mặt với nỗi sợ thầm kín của mẹ cô, sự thật tàn khốc sau trận đồ gương và trực diện tấn công hệ thống trật tự đang xóa sổ sự khác biệt của con người. Giữa sự sụp đổ và đối kháng, Hiểu Dật dần học được cách làm chủ bản thân, cùng A Triệt hợp lực giành lại cuộc đời thuộc về chính mình.</p>', 'Full', 1, 'single', 'completed', 9, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hiểu Dật","avatar":""},{"name":"Kính Bà","avatar":""},{"name":"A Triệt","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324126);
