INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-quang-kiem-anh', 'Đao Quang Kiếm Ảnh', 'A Knife Of The Weapon Gleams With Blood', 'https://phimimg.com/upload/vod/20260409-1/52f56762b75b2e6b5add813133119677.jpg', 'https://phimimg.com/upload/vod/20260409-1/1d116ef17489a82d578bfefdbe7db2d5.jpg', '<p>Đại Cách tộc vốn có bốn vị dũng sĩ, nhưng Nguyên Thái và Côn Bố đã phản bội tổ quốc. Nguyên Thái dẫn liên quân Tây Khuê và Nam Ly tấn công, khiến Hoàng đế Đại Cách tộc phải tự sát. Trong cơn biến loạn, Thái Bát Nhi mang theo Thất Khổng Đao bỏ chạy và cứu được một cậu bé được bầy sói nuôi dưỡng trong rừng sâu, đặt tên là Tổ Triệt. Sau 15 năm ẩn dật, Tổ Triệt dưới sự dạy bảo của Thái Bát Nhi đã rèn luyện được đao pháp thượng thừa, quyết định xuống núi để khôi phục lại vương triều Đại Cách.</p>', 'Full', 1, 'single', 'completed', 16, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Càn Minh","avatar":""},{"name":"Tôn Đan Đan","avatar":""},{"name":"Trương Xuân Trọng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["The knife of the weapon gleams with blood","武器之刀光剑影"]', 1784690324126);
