INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-gioi-the-thao-chieu-het', 'Bí Mật Giới Thể Thao: Chiếu Hết', 'Untold: Chess Mates', 'https://phimimg.com/upload/vod/20260409-1/b16963c59130af1cfced1156717ee3d8.jpg', 'https://phimimg.com/upload/vod/20260409-1/a6fba1dfa54b91cbb4b14b32150417bb.jpg', '<p>Làm sao một trận đấu giữa hai đại kiện tướng cờ vua lại biến thành vụ bê bối kỳ quặc về hạt rung hậu môn? Bộ phim tài liệu này đào sâu câu chuyện kỳ lạ đến mức tưởng như hư cấu.</p>', 'Full', 1, 'single', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Magnus Carlsen","avatar":""},{"name":"Hans Niemann","avatar":""},{"name":"Danny Rensch","avatar":""},{"name":"Erik Allebest","avatar":""},{"name":"Hikaru Nakamura","avatar":""},{"name":"Bruce Pandolfini","avatar":""},{"name":"Henrik Carlsen","avatar":""},{"name":"Levy Rozman","avatar":""},{"name":"Piers Morgan","avatar":""},{"name":"Donald Trump","avatar":""},{"name":"Fabiano Caruana","avatar":""},{"name":"Joe Rogan","avatar":""},{"name":"Trevor Noah","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Untold: Chess Mates"]', 1784690324126);
