INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sa-doa', 'Sa Đoạ', 'In Love With Loving You', 'https://phimimg.com/upload/vod/20260329-1/48d859ae7a5dba530bd5d63ea8232ba1.jpg', 'https://phimimg.com/upload/vod/20260329-1/10d72b1f7dba3142997f194b4c5dfc90.jpg', '<p>Khi rơi vào thời khắc tăm tối nhất, Tống Chiêu Lễ gặp Kỷ Tuyền - cô gái cũng đang trải qua biến cố gia đình - và âm thầm tài trợ để cô hoàn thành việc học. Nhiều năm sau, một biến cố bất ngờ khiến Kỷ Tuyền lần nữa bước vào cuộc đời anh. Vượt qua muôn vàn trở ngại, Tống Chiêu Lễ từng bước lật ngược thế cờ, vươn lên nắm quyền. Trong những lần giằng co không dứt, hai người dần thấu hiểu và tôn trọng lẫn nhau, dùng tình yêu để chữa lành những tổn thương của đối phương.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 18, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tiêu Vũ","avatar":""},{"name":"Trương Phỉ Nhiên","avatar":""},{"name":"Miêu Thiên Thiêm","avatar":""},{"name":"Đới Manh","avatar":""},{"name":"Trần Tư Dư","avatar":""},{"name":"Chu Thiêm Bác","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["沉靡"]', 1784690324126);
