INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-quan-he-nguy-hiem-2026', 'Mối Quan Hệ Nguy Hiểm', 'The Dark Romance', 'https://phimimg.com/upload/vod/20260403-1/b1474d13a099c2df1dd954e83e0ca038.jpg', 'https://phimimg.com/upload/vod/20260403-1/724b5648155abbc96103ad606423020d.jpg', '<p>Gói bưu phẩm cuối cùng của cô bạn thân gửi lại trước khi kết thúc cuộc đời, đề tên một người đàn ông &quot;hoàn hảo&quot;. Yên Linh không tin vào việc bạn thân lại có thể tự kết liễu đời mình. Để vén màn sự thật, cô liều mình giả dạng, thâm nhập vào giới thượng lưu đầy dối trá. Khi chạm gần đến đáp án, người đàn ông với ánh mắt dịu dàng ấy xuất hiện. Anh như tia sáng xoa dịu nỗi đau mất bạn, nhưng cũng âm thầm cô lập cô với thế giới bên ngoài. Trong thứ tình yêu ngột ngạt ấy, Yên Linh bàng hoàng nhận ra: mình đã trở thành con mồi tiếp theo. Đằng sau vẻ ngoài hoàn hảo là một cạm bẫy được tính toán kỹ lưỡng của sự thao túng tình cảm (PUA). Đây không phải một cuộc tình, mà là cuộc chiến sinh tử để tự cứu lấy chính mình. Cô quyết định sẽ tự tay kéo gã quỷ dữ ấy xuống khỏi bệ thần...</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 15, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tôn Lệ","avatar":""},{"name":"Ngô Khảng Nhân","avatar":""},{"name":"Vương Qua","avatar":""},{"name":"Trần Tỉ Húc","avatar":""},{"name":"Đào Tuệ","avatar":""},{"name":"Trần Thiên Vũ","avatar":""},{"name":"Ngô Niệm Hiên","avatar":""},{"name":"Liêu Ngân Nguyệt","avatar":""},{"name":"Mã Nguyên","avatar":""},{"name":"Hình Giai Đống","avatar":""},{"name":"Thích Cửu Châu","avatar":""},{"name":"Trương Vũ Ninh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["执迷","Obstinately","Wei Xian Guan Xi","Опасная связь","執迷","The Dark Romance","危险关系"]', 1784690324126);
