INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-tinh-xua', 'Dấu Tình Xưa', 'Yesterday', 'https://phimimg.com/upload/vod/20260226-1/53d3bea7efab524b8cae398385723b64.jpg', 'https://phimimg.com/upload/vod/20260226-1/80a2dc53736f31c12df3679b7c5d386d.jpg', '<p>Vier, người thừa kế của tập đoàn VPG, gặp gỡ Kelvin – con trai thứ của tập đoàn KING. Anh đã giúp Kelvin đấu tranh giành quyền lực trước người anh cùng cha khác mẹ đầy mưu mô là Ken. Sau khi bị phản bội và phải chạy trốn đến Chiang Mai nhờ sự giúp đỡ của Nana, cuộc đời Vier rơi vào cảnh bế tắc.&nbsp; Một ngày nọ, Vier tình cờ gặp lại Kelvin. Giờ đây, cả hai phải đối mặt với Ken – kẻ đã kết hôn với Lalin và đang thâu tóm tập đoàn LOYDE. Đứng trước sự thao túng của phe đối địch, Vier và Kelvin phải cùng nhau dấn thân vào một cuộc chiến sinh tử, nơi ranh giới giữa quyền lực và mạng sống trở nên vô cùng mong manh.</p>', 'Full', 11, 'series', 'completed', 15, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Wasuthorn Chaijindar","avatar":""},{"name":"Thitipong Sangngey","avatar":""},{"name":"Dina Pophring","avatar":""},{"name":"Natthanicha Srisawasdiphalodom","avatar":""},{"name":"Chotipat Suthadsanasoung","avatar":""},{"name":"Natsakan Chairote","avatar":""},{"name":"Sattaphong Phiangphor","avatar":""},{"name":"Patiparn Pataweekarn","avatar":""},{"name":"Sarut Vichitrananda","avatar":""},{"name":"Wiphop Bangyeekan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Roi Rak Wan Wan","Yesterday The Series","รอยรัก วันวาน"]', 1784690324126);
