INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cai-ten-an-danh', 'Cái Tên Ẩn Danh', 'Vanished Name', 'https://phimimg.com/upload/vod/20260327-1/584255257519c3206c6877141769a620.jpg', 'https://phimimg.com/upload/vod/20260327-1/958aadd537c10f1562b60abd69098f53.jpg', '<p>Một cái tên tùy tiện. Một cái tên bị đánh cắp. Một cái tên không thuộc về cô. Một cái tên không dám nhắc lại. Một cái tên chưa từng bị lãng quên. Nhậm Tiểu Danh luôn rất ghét cái tên của mình, nhưng dù ghét đến đâu, đó vẫn là bằng chứng cho thấy cô còn tồn tại trên thế gian này, là tiền đề để cô trở thành chính mình. Cô muốn giành lại cái tên đã bị đánh cắp. Cái tên ấy không chỉ thuộc về riêng cô, mà còn thuộc về rất nhiều người. Những cái tên vô hình ấy bị vùi lấp giữa khói lửa đời thường của cơm áo gạo tiền, giữa những lời bàn tán phán xét, giữa những năm tháng dài đằng đẵng khó nhọc, và rồi dần đánh mất đi danh tính. Nhưng vẫn luôn có người nhớ đến họ, và cũng luôn có người tiếp bước theo dấu chân họ, cho đến khi cái tên của họ được tất cả mọi người nhìn thấy. Đây là một câu chuyện về sự đấu tranh và cứu rỗi của hai thế hệ phụ nữ.</p>', 'Tập 31', 31, 'series', 'ongoing', 23, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Nghê Ni","avatar":""},{"name":"Diêm Ni","avatar":""},{"name":"Lưu Nhã Sắt","avatar":""},{"name":"Lưu Mẫn Đào","avatar":""},{"name":"Bảo Kiếm Phong","avatar":""},{"name":"Đổng Khiết","avatar":""},{"name":"Vương Thánh Địch","avatar":""},{"name":"Hàn Hạo Lâm","avatar":""},{"name":"Na Nhất","avatar":""},{"name":"Châu Du","avatar":""},{"name":"Khuất Thanh Thanh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a