INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuong-phong-bong-toi-phan-4', 'Cuồng Phong Bóng Tối (Phần 4)', 'Dark Winds (Season 4)', 'cuồng phong bóng tối (phần 4) dark winds (season 4) zahn mcclarnon kiowa gordon jessica matten deanna allison isabel deroy-olson franka potente dark winds - der wind des bösen dark winds', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thay-tam-doi-tanh', 'Thay Tâm Đổi Tánh', 'Turn Over A New Leaf', 'https://phimimg.com/upload/vod/20260406-1/c7691286bee1bf3d669e289603ee0ee8.jpg', 'https://phimimg.com/upload/vod/20260406-1/176598d09ec82c40ff7039d5b07413c0.jpg', '<p>Hạ Nam, đội trưởng đội đua Giang Nam, vốn là tay đua kiệt xuất liên tục lập chiến công. Tuy nhiên, bạn gái anh — phóng viên thể thao Trần Tử Hi — vì muốn phanh phui góc khuất của giới đua xe đã mạo hiểm thâm nhập vào hệ thống của đội đua Siêu Âm Thanh, dẫn đến việc bị sát thủ truy sát và không may qua đời. Trong nỗi đau cùng cực, Hạ Nam quyết tâm tìm lại công lý và làm sáng tỏ sự thật cho người yêu.&nbsp; Anh thay tên đổi họ thành Cố Hạo Nhiên, đại thiếu gia của tập đoàn họ Cố, âm thầm xâm nhập vào trung tâm của giới đua xe. Trên hành trình đó, anh gặp gỡ em gái của Trần Tử Hi là Trần Tử Thanh, một cô gái có niềm đam mê mãnh liệt với tốc độ. Cả hai dần nảy sinh tình cảm trong quá trình sát cánh bên nhau.&nbsp; Hạ Nam đã tập hợp những tay đua và kỹ thuật viên bị chèn ép để thành lập một đội đua riêng, từng bước bóc trần những mưu đồ thao túng trận đấu, hối lộ trọng tài và thậm chí là mưu sát đối thủ của giới thượng tầng đua xe, mà kẻ đứng sau không ai khác chính là Thạch Thần — cấp cao của Liên minh Đua xe.&nbsp; Trong giải đua quyết định, dù đối thủ đã giăng ra vô số bẫy rập, đội của Hạ Nam vẫn lội ngược dòng giành chức vô địch bằng tài năng và ý chí quật cường. Họ đã thu thập đầy đủ bằng chứng phạm tội của Thạch Thần và đưa ra ánh sáng, khiến hắn phải đền tội trước pháp luật. Trải qua sự lột xác, Hạ Nam từ một tay đua đơn thuần đã trưởng thành thành một nhà lãnh đạo đầy trách nhiệm, không chỉ quét sạch thế lực tà ác để bảo vệ sự công bằng cho môn thể thao tốc độ, mà còn tìm thấy hạnh phúc bên Trần Tử Thanh, cùng nhau chiến đấu vì tương lai của ngành đua xe.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 13, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Văn Tình","avatar":""},{"name":"Vương Tử Hòa","avatar":""},{"name":"Mã Lật","avatar":""},{"name":"Lưu Chung Hoành","avatar":""},{"name":"Tiền Khả Nhi","avatar":""},{"name":"Tống Diễm Nghiêu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["改头换面"]', 1784690324126);
