INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thay-tam-doi-tanh', 'Thay Tâm Đổi Tánh', 'Turn Over A New Leaf', 'thay tâm đổi tánh turn over a new leaf văn tình vương tử hòa mã lật lưu chung hoành tiền khả nhi tống diễm nghiêu 改头换面', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-ky-nhu-tranh', 'Chiến Kỳ Như Tranh', 'Flags Of Glory (Banner Of Heroes)', 'https://phimimg.com/upload/vod/20260406-1/c30bd612c1d250c80278a4c1987caf2e.jpg', 'https://phimimg.com/upload/vod/20260406-1/f96eead465af53ab4288a3350d79b5cd.jpg', '<p>Năm 1950, Ngụy Chính Hoa mạo danh Trịnh Hùng Tài tham gia chiến trường Triều Tiên. Dù liên tiếp lập được nhiều chiến công, anh phải trải qua muôn vàn thử thách sinh tử, đau đớn chứng kiến cảnh anh em ly tán, người thân và bạn bè lần lượt ngã xuống. Anh cùng các chiến hữu đã vào sinh ra tử, chiến đấu đẫm máu để đập tan các âm mưu cũng như cuộc chiến tranh vi khuẩn của quân Mỹ, và cuối cùng giành được thắng lợi trong trận quyết chiến. Năm 1953, hiệp định đình chiến được ký kết. 70 năm sau, người lính Ngụy Chính Hoa nay đã mái đầu bạc trắng, một lần nữa dang rộng lá cờ năm xưa để tưởng nhớ anh linh những đồng đội đã khuất và tri ân hòa bình.</p>', 'Hoàn Tất (33/33)', 33, 'series', 'completed', 14, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Đồng","avatar":""},{"name":"Tô Thanh","avatar":""},{"name":"Lưu Thiên Tá","avatar":""},{"name":"Mã Tô","avatar":""},{"name":"Lý Thần","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["战旗如画"]', 1784690324126);
