INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chien-ky-nhu-tranh', 'Chiến Kỳ Như Tranh', 'Flags Of Glory (Banner Of Heroes)', 'chiến kỳ như tranh flags of glory (banner of heroes) trương đồng tô thanh lưu thiên tá mã tô lý thần 战旗如画', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phap-su-kunon-co-the-nhin-thay-majutsushi-kunon-wa-mieteiru', 'Pháp Sư Kunon Có Thể Nhìn Thấy (Majutsushi Kunon wa Mieteiru)', 'Kunon The Sorcerer Can See', 'https://phimimg.com/upload/vod/20260112-1/9a5105f378ecaea87a5aa7336727bb38.jpg', 'https://phimimg.com/upload/vod/20260112-1/d952ca11041fd1fa4838da93e8c2ef5f.jpg', '<p>Kunon, một chàng trai trẻ mang đôi mắt mù lòa, đã tự đặt ra mục tiêu cho đời mình: tạo ra đôi mắt mới bằng ma pháp hệ Thủy. Chỉ sau vỏn vẹn 5 tháng bắt đầu học thuật pháp, Kunon đã vượt xa cả người thầy của mình, không ngừng mài giũa tài năng để thực hiện một kỳ tích chưa từng có trong lịch sử. Câu chuyện kỳ ảo về một thiên tài khiếm thị, người dùng sự tò mò và khát khao chinh phục ma pháp để mở ra một thế giới mới cho chính mình, chuẩn bị bắt đầu!</p><p><br/></p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Saori Hayami","avatar":""},{"name":"Maaya Uchida","avatar":""},{"name":"Akari Kito","avatar":""},{"name":"Rikako Yamaguchi","avatar":""},{"name":"Nobunaga Shimazaki","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Majutsushi Kunon wa Mieteiru","魔術師クノンは見えている","Majutsu-shi Kunon wa Mieteiru","Kunon the Sorcerer Can See"]', 1784690324126);
