INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phap-su-kunon-co-the-nhin-thay-majutsushi-kunon-wa-mieteiru', 'Pháp Sư Kunon Có Thể Nhìn Thấy (Majutsushi Kunon wa Mieteiru)', 'Kunon The Sorcerer Can See', 'pháp sư kunon có thể nhìn thấy (majutsushi kunon wa mieteiru) kunon the sorcerer can see saori hayami maaya uchida akari kito rikako yamaguchi nobunaga shimazaki majutsushi kunon wa mieteiru 魔術師クノンは見えている majutsu-shi kunon wa mieteiru kunon the sorcerer can see', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lop-hoc-phi-nhan-loai-cua-thay-giao-ghet-con-nguoi-jingai-kyoushitsu-no-ningengirai-kyoushi', 'Lớp Học Phi Nhân Loại Của Thầy Giáo Ghét Con Người (Jingai Kyoushitsu no Ningengirai Kyoushi)', 'A Misanthrope Teaches A Class For Demi-Humans', 'https://phimimg.com/upload/vod/20260112-1/846d330c8939e3eda13c1f14c5e9b5a1.jpg', 'https://phimimg.com/upload/vod/20260112-1/89c51b7d580ba7cc73f43a95cbf28b76.jpg', '<p>Sau một biến cố đau lòng khiến sự nghiệp giảng dạy chấm dứt, Rei Hitoma hoàn toàn chắc chắn rằng mình căm ghét con người. Thế nhưng, khi nhìn thấy mẩu tin tuyển dụng cho vị trí &#39;một giáo viên thực sự quan tâm đến học sinh&#39;, anh vẫn cảm thấy thôi thúc phải nộp đơn. Trước khi kịp nhận ra chuyện gì đang xảy ra, Rei đã được nhận vào làm — để rồi bàng hoàng phát hiện ra học sinh của mình đều là những Á nhân (Demi-human). Những gì bắt đầu như một công việc đơn thuần đã trở thành một hành trình chữa lành cho cả một người thầy đã mất niềm tin vào nhân loại và những học sinh luôn khao khát về thế giới ấy.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 12, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Toshiki Masuda","avatar":""},{"name":"Sora Amamiya","avatar":""},{"name":"Saori Onishi","avatar":""},{"name":"Maria Naganawa","avatar":""},{"name":"Rui Tanabe","avatar":""},{"name":"Yui Horie","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jingai Kyoushitsu no Ningengirai Kyoushi","인외 교실의 인간 혐오 교사","人外教室の人間嫌い教師"]', 1784690324126);
