INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('san-toi-huyet-oan', 'Săn Tội Huyết Oán', 'Hunting For Crime: Red Deep Grudge', 'https://phimimg.com/upload/vod/20260329-1/fa73e9868c59bcb98b053d1a8e562f02.jpg', 'https://phimimg.com/upload/vod/20260329-1/a040779e0c77c1c193c047f028cb539d.jpg', '<p>Tại biệt thự nhà họ Lâm liên tiếp xảy ra các vụ án mạng kỳ lạ. Bà Lâm và cô giúp việc lần lượt qua đời. Các chứng cứ tại hiện trường vụ án đều liên quan tới một bộ hí phục đỏ rực, khiến lời đồn &quot;hí phục đòi mạng&quot; lan rộng. Thanh tra Hoàng Kim Nhung phối hợp cùng pháp y Lý Xuân Thành và Đoạn Thanh Thanh vào cuộc điều tra, từng bước vén màn oan khuất của Bạch Mai ẩn giấu phía sau bộ hí phục, cũng như sự thật về các mối quan hệ bí mật, tham nhũng và sự trả thù đằng sau gia đình họ Lâm.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 12, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Huỳnh Thánh Kiệt","avatar":""},{"name":"Trương Tinh Dao","avatar":""},{"name":"Ôn Áo","avatar":""},{"name":"Chung Tư Hoa","avatar":""},{"name":"Lý Băng Băng","avatar":""},{"name":"Châu Hi Văn","avatar":""},{"name":"Tất Siêu","avatar":""},{"name":"Nhạc Huấn Vũ","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["猎罪·赤怨","猎罪赤怨"]', 1784690324126);
