INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngon-lua-ruc-ro-cua-co-ay', 'Ngọn Lửa Rực Rỡ Của Cô Ấy', 'Her Blaze', 'https://phimimg.com/upload/vod/20260317-1/e9ebc05d684bf4be4c78f32106e12166.jpg', 'https://phimimg.com/upload/vod/20260317-1/b3e7068078ec213627f6ff1a26191abc.jpg', '<p>Ba năm trước, thiên tài toán học Nhiêu Vũ Từ bị bạn thân kiêm đối tác khởi nghiệp Bạch Tịnh Tịnh gài bẫy hãm hại. Vũ Từ bị hãm hại là &quot;nghiện thuốc&quot; dẫn đến hành vi tấn công mẹ ruột, cô bị gia đình cưỡng chế đưa vào Trung tâm điều trị tâm lý. Trong khi đó, Bạch Tịnh Tịnh lại bán công ty do hai người đồng sáng lập, trở thành giám đốc cấp cao của tập đoàn Lịch Sâm. Tình thân, tình bạn, tình yêu và sự nghiệp – tất cả đều hoàn toàn biến mất khỏi cuộc đời Vũ Từ. Giây phút một thiên tài rơi xuống đáy vực cũng là lúc cô khắc cốt ghi tâm gương mặt kẻ đã đẩy mình vào chỗ chết. Ba năm sau, Nhiêu Vũ Từ khỏi bệnh xuất viện. Cô bắt đầu lập kế hoạch trả thù, thề sẽ xé toạc lớp mặt nạ đạo đức giả của Bạch Tịnh Tịnh, khiến mọi tội ác của ả phải phơi bày hoàn toàn dưới ánh mặt trời...</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 13, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Mã Tư Thuần","avatar":""},{"name":"Ninh Lý","avatar":""},{"name":"Viên San San","avatar":""},{"name":"Trạch Tử Lộ","avatar":""},{"name":"Chương Đào","avatar":""},{"name":"Phạm Điềm Điềm","avatar":""},{"name":"Trương Duy Y","avatar":""},{"name":"Liễu Tiểu Hải","avatar":""},{"name":"Tiêu Ngọc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sheng Nu","盛怒","Ta De Sheng Yan","Rage","她的盛焰"]', 1784690324126);
