INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngon-lua-ruc-ro-cua-co-ay', 'Ngọn Lửa Rực Rỡ Của Cô Ấy', 'Her Blaze', 'ngọn lửa rực rỡ của cô ấy her blaze mã tư thuần ninh lý viên san san trạch tử lộ chương đào phạm điềm điềm trương duy y liễu tiểu hải tiêu ngọc sheng nu 盛怒 ta de sheng yan rage 她的盛焰', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-qua-xuan-den', 'Đông Qua Xuân Đến', 'Live Up To Your Youth', 'https://phimimg.com/upload/vod/20260329-1/001e5abfbc2bc35fe21a35d7f3b48820.jpg', 'https://phimimg.com/upload/vod/20260329-1/8b31d167350f7f17cdc24de08776fe02.jpg', '<p>Ở Bắc Kinh vào những năm 90, quán trọ Đông Qua Xuân Đến đã chứng kiến cuộc sống thăng trầm của những nam nữ thanh niên từ khắp mọi miền đất nước đổ về đây ôm ấp giấc mơ sống và làm việc tại Bắc Kinh. Họ là Từ Thắng Lợi, một người đam mê viết kịch bản nhưng thường bị từ chối vẫn kiên trì chiến đấu sau mỗi lần thất bại; Trang Trang, một ca sĩ khao khát bước lên sân khấu thanh lịch nhưng chỉ có thể mưu sinh qua những buổi diễn thương mại; Thẩm Nhiễm Nhiễm, cô gái hi vọng được đóng vai nữ chính lại phải đối mặt với cơ hội và lựa chọn trong làng giải trí hào nhoáng; Đào Lượng Lượng, một nghệ sĩ kèn saxophone tài hoa chơi nhạc cho khách qua đường dưới chân cầu vượt để thực hiện giấc mơ âm nhạc; Quách Tông Bảo, một diễn viên quần chúng yêu văn nghệ nhưng lại làm đủ thứ việc vặt để kiếm tiền chữa bệnh cho vợ con; Tào Dã, một họa sĩ muốn gây tiếng vang với những ý tưởng nghệ thuật tiên phong nhưng không ai thấu hiểu.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 15, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Bạch Vũ","avatar":""},{"name":"Chương Nhược Nam","avatar":""},{"name":"Lâm Duẫn","avatar":""},{"name":"Vương Ngạn Lâm","avatar":""},{"name":"Điền Vũ","avatar":""},{"name":"Phùng Gia Di","avatar":""},{"name":"Lưu Quán Lân","avatar":""},{"name":"Tống Gia Đằng","avatar":""},{"name":"Tào Chinh","avatar":""},{"name":"Đinh Dũng Đại","avatar":""},{"name":"Tát Nhật Na","avatar":""},{"name":"Tả Tiểu Thanh","avatar":""},{"name":"Bao Bối Nhĩ","avatar":""},{"name":"Anh Đạt","avatar":""},{"name":"Nhậm Trọng","avatar":""},{"name":"Lâm Gia Xuyên","avatar":""},{"name":"Lưu Kim Sơn","avatar":""},{"name":"Vương Tiểu Lợi","avatar":""},{"name":"Ngưu Lợi","avatar":""},{"name":"Khổng Lâ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Live up to Your Youth","冬去春来"]', 1784690324126);
