INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dong-qua-xuan-den', 'Đông Qua Xuân Đến', 'Live Up To Your Youth', 'đông qua xuân đến live up to your youth bạch vũ chương nhược nam lâm duẫn vương ngạn lâm điền vũ phùng gia di lưu quán lân tống gia đằng tào chinh đinh dũng đại tát nhật na tả tiểu thanh bao bối nhĩ anh đạt nhậm trọng lâm gia xuyên lưu kim sơn vương tiểu lợi ngưu lợi khổng lâ live up to your youth 冬去春来', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-ke-bong-toi', 'Cận Kề Bóng Tối', 'Dark And Dawn', 'https://phimimg.com/upload/vod/20260321-1/6608625097126142fffe4d9aca2c886a.jpg', 'https://phimimg.com/upload/vod/20260321-1/7a48e9cd90bca2ef3ef5027c0f419ba1.jpg', '<p>Diệp Tiểu Ái – cô gái luôn khao khát trở thành nhà thiết kế và Trang Ly Ly – người mẫu đang chạy trốn khỏi bạo hành gia đình, đã tình cờ gặp gỡ và trở thành bạn thân. Tiểu Ái đã sát cánh giúp Ly Ly chống lại gã chồng tồi Lý Tấn, còn Ly Ly giúp Tiểu Ái tháo gỡ được khúc mắc với &quot;chú trẻ&quot; Lâm Sâm. Trải qua những tháng ngày bên nhau, cả hai cô gái cuối cùng cũng thực hiện được ước mơ và cùng bước sang một trang hoàn toàn mới của cuộc đời.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 13, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hứa Giai Kỳ","avatar":""},{"name":"Đại Cao Chính","avatar":""},{"name":"Hồng Nghêu","avatar":""},{"name":"Tạ Nhĩ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["校服的裙摆","不一样的她 第一部","Bu Yi Yang De Ta","不一样的她之临暗","不一樣的她之臨暗","The Unique Her: Lin An","The Unique Her","临暗"]', 1784690324126);
