INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-thien-movie-vac-quan-tai-chien-vuong-dang', 'Già Thiên Movie: Vác Quan Tài Chiến Vương Đằng', 'Shrounding The Heavens Movie：Fighting Against Wang Teng with Copper Coffin', 'https://phimimg.com/upload/vod/20260404-1/df10006f21897c413d78a6ba88206231.jpg', 'https://phimimg.com/upload/vod/20260404-1/0dc0e027ba14407627ecdff3b7ac8644.jpg', '<p>Diệp Phàm và Vương Đằng, cuộc đối đầu định mệnh giữa hai đại thiên kiêu. Bắc Nguyên Vương gia kéo đến hung hãn, lão tổ Cơ gia thì ôm lòng riêng hiểm độc. Giữa vòng xoáy đó, Cơ Tử Nguyệt lại bị biến thành công cụ liên hôn của gia tộc, còn Diệp Phàm thì rơi vào cảnh trở thành mục tiêu công kích của vạn người. Khi Hoang Cổ Thánh Thể va chạm với truyền thừa Loạn Cổ, liệu ai mới là người thực sự sở hữu phong thái của một bậc Đại Đế tương lai?</p>', 'Full', 1, 'single', 'completed', 17, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xiang Xu","avatar":""},{"name":"Huang Xiangyu","avatar":""},{"name":"Li Chanfei","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["遮天剧场版：背棺战王腾","Shrounding the Heavens Movie: Fighting Against Wang Teng with Copper Coffin","Shrouding the Heavens: The Imperial Path"]', 1784690324126);
