INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-chao-1983', 'Xin Chào 1983', 'Dream Of Golden Years', 'https://phimimg.com/upload/vod/20260319-1/5a5b6d0060ae397cd841b720b0ae2f53.jpg', 'https://phimimg.com/upload/vod/20260319-1/3e5edb52e9586f68653000deeda662b0.jpg', '<p>Ở tuổi 36, Hạ Hiểu Lan – nữ quản lý cấp cao – mất tất cả sau khi công ty phá sản. Trong lúc tuyệt vọng, cô xuyên không về quá khứ, trở thành cô gái nông thôn 18 tuổi. Không tiền bạc hay chỗ dựa, nhưng với trí tuệ, nhan sắc và nhiệt huyết tuổi trẻ, cô quyết tâm làm lại cuộc đời. Hiểu Lan vừa học tập, vừa khởi nghiệp từ con số 0, từng bước xây dựng sự nghiệp và theo đuổi ước mơ đại học. Trên hành trình đó, cô tìm thấy tình yêu, tình thân và những mối quan hệ đầy ý nghĩa, khẳng định bản thân và tạo nên một cuộc sống mới rực rỡ hơn xưa.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 11, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Châu Dã","avatar":""},{"name":"Trạch Tiêu Văn","avatar":""},{"name":"Đồng Tuyết","avatar":""},{"name":"Vương Quán Dật","avatar":""},{"name":"Triệu Đạt","avatar":""},{"name":"Đồ Lăng","avatar":""},{"name":"Tưởng Dịch","avatar":""},{"name":"Trịnh Vĩ","avatar":""},{"name":"Lâm Tiêu","avatar":""},{"name":"Phàn Lâm Phong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ni Hao 1983","1983我来了","Here I Come","重生八零：媳妇有点辣","Hello 1983","Dream of golden years","你好1983"]', 1784690324126);
