INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('xin-chao-1983', 'Xin Chào 1983', 'Dream Of Golden Years', 'xin chào 1983 dream of golden years châu dã trạch tiêu văn đồng tuyết vương quán dật triệu đạt đồ lăng tưởng dịch trịnh vĩ lâm tiêu phàn lâm phong ni hao 1983 1983我来了 here i come 重生八零：媳妇有点辣 hello 1983 dream of golden years 你好1983', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('high-school-kimengumi', 'High School! Kimengumi', 'High School Funny-face Club', 'https://phimimg.com/upload/vod/20260112-1/ae308d5b8f63e6eed531b37e02624abd.jpg', 'https://phimimg.com/upload/vod/20260112-1/ab2c7c7d82072c8005376b3e96477598.jpg', '<p>Rei Ichido, Go Reietsu, Kiyoshi Shusse, Jin Daima và Dai Monohoshi là năm chàng trai tinh quái đang theo học tại trường cấp hai Ichiou. Với mỗi người một cá tính lập dị và biệt tài gây náo loạn, họ đã cùng nhau tạo nên danh tiếng cho nhóm &#39;Kimen-gumi&#39; (Nhóm Mặt Quỷ) lừng lẫy.Một ngày nọ, cô nữ sinh mới chuyển trường Yui Kawa và bạn của mình là Chie Uru đã chạm trán nhóm ngũ quái này và nhanh chóng bị cuốn vào những trò đùa tinh nghịch của họ. Xung quanh họ còn có những hội nhóm đầy màu sắc khác — từ nhóm mỹ nam &#39;Iro Otoko-gumi&#39; do Shou Kireide dẫn đầu, nhóm bất hảo &#39;Ban-gumi&#39; của You Nihiruda, nhóm vận động viên &#39;Ude-gumi&#39; của Kai Undou, cho đến biệt đội nữ quái &#39;Onna-gumi&#39; do Jako Amano cầm đầu.Khi thời gian trôi qua và một mùa xuân mới lại về, cuộc sống thường nhật của những học sinh lập dị này bắt đầu mở ra một câu chuyện học đường đầy sôi động và hài hước.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Tomokazu Seki","avatar":""},{"name":"Shunsuke Takeuchi","avatar":""},{"name":"Yoshitsugu Matsuoka","avatar":""},{"name":"Chiaki Kobayashi","avatar":""},{"name":"Kikunosuke Toya","avatar":""},{"name":"Haruka Shiraishi","avatar":""},{"name":"Ikumi Hasegawa","avatar":""},{"name":"Nobuhiko Okamoto","avatar":""},{"name":"Yusuke Kobayashi","avatar":""},{"name":"Mao Ichimichi","avatar":""},{"name":"Daisuke Sakuma","avatar":""},{"name":"Kohsuke Toriumi","avatar":""},{"name":"Yoko Hikasa","avatar":""},{"name":"Yui Horie","avatar":""},{"name":"Katsuyuki Konishi","avatar":""},{"name":"Show","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Le Collège fou, fou, fou","High School! Kimengumi (2026)","High School Kimengumi","High School Funny-face Club","Funny Faces in High School","ハイスクール！奇面組"]', 1784690324126);
