INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-quen-ke-thu', 'Đừng Quên Kẻ Thù', 'Never Forget Your Enemy', 'https://phimimg.com/upload/vod/20260321-1/014b4d5234072df4117b77b916e99cba.jpg', 'https://phimimg.com/upload/vod/20260321-1/844e5a3b8fb51a3cf7aab038822dc097.jpg', '<p>Diệp Tiểu Ái – cô gái luôn khao khát trở thành nhà thiết kế và Trang Ly Ly – người mẫu đang chạy trốn khỏi bạo hành gia đình, đã tình cờ gặp gỡ và trở thành bạn thân. Tiểu Ái đã sát cánh giúp Ly Ly chống lại gã chồng tồi Lý Tấn, còn Ly Ly giúp Tiểu Ái tháo gỡ được khúc mắc với &quot;chú trẻ&quot; Lâm Sâm. Trải qua những tháng ngày bên nhau, cả hai cô gái cuối cùng cũng thực hiện được ước mơ và cùng bước sang một trang hoàn toàn mới của cuộc đời.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 18, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Hwang Jun-su","avatar":""},{"name":"Lee Ja-woon","avatar":""},{"name":"Oh Jae-hyeong","avatar":""},{"name":"Fila Lee","avatar":""},{"name":"Park Eun-jo","avatar":""},{"name":"Shim So-yeon","avatar":""},{"name":"Lee Jeong-hyun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["别忘了你的敌人","别忘了你的仇人","네 원수를 잊지 마라","Ne Wonsureul Itji Mara","Yangngai... Ko Chai Nai","ยังไง..ก็ใช่นาย","Still You"]', 1784690324126);
