INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dung-quen-ke-thu', 'Đừng Quên Kẻ Thù', 'Never Forget Your Enemy', 'đừng quên kẻ thù never forget your enemy hwang jun-su lee ja-woon oh jae-hyeong fila lee park eun-jo shim so-yeon lee jeong-hyun 别忘了你的敌人 别忘了你的仇人 네 원수를 잊지 마라 ne wonsureul itji mara yangngai... ko chai nai ยังไง..ก็ใช่นาย still you', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('darwin-jihen', 'Darwin Jihen', 'The Darwin Incident', 'https://phimimg.com/upload/vod/20260121-1/ea8ded1d03735642b708ff7eb8e5c57b.jpg', 'https://phimimg.com/upload/vod/20260121-1/3a0d8fdbedbfe289c8b7a98a297fd954.jpg', '<p>Charlie là một sinh vật độc nhất vô nhị. Là một &#39;Humanzee&#39; (con lai giữa người và tinh tinh), trí tuệ và năng lực thể chất của cậu vượt xa mọi giới hạn thông thường. Đó cũng chính là lý do khiến Liên minh Giải phóng Động vật (ALA), một tổ chức khủng bố, khao khát có được cậu bằng mọi giá. Chúng sẵn sàng thực hiện những biện pháp cực đoan nhất để chiếm đoạt Charlie. Tuy nhiên, Charlie đã quyết tâm chiến đấu đến cùng để bảo vệ những người mà cậu yêu thương.</p>', 'Tập 13', 13, 'hoathinh', 'ongoing', 19, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Atsumi Tanezaki","avatar":""},{"name":"Mitsuho Kambe","avatar":""},{"name":"Akio Otsuka","avatar":""},{"name":"Toshiyuki Morikawa","avatar":""},{"name":"Rina Sato","avatar":""},{"name":"Yoji Ueda","avatar":""},{"name":"Kaito Ishikawa","avatar":""},{"name":"Hiroya Egashira","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Darwin Jihen","Przypadek Darwina","Darwin''s Incident","ダーウィン事変"]', 1784690324126);
