INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-than', 'Kê Thân', 'Agent From Above', 'https://phimimg.com/upload/vod/20260403-1/353163822a676c83118e7d25749862b7.jpg', 'https://phimimg.com/upload/vod/20260403-1/f7394d378df6b0de2532e7fbc9e5ea69.jpg', '<p>Thế lực tà ác. Những cuộc chạm trán siêu nhiên. Những cái chết bí ẩn. Đặc vụ thiên giới Hàn Kiệt đối mặt với cả quỷ dữ trong lòng lẫn ác quỷ thật sự khi chiến đấu bảo vệ nhân loại.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 21, 2026, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Kha Chấn Đông","avatar":""},{"name":"Vương Bá Kiệt","avatar":""},{"name":"Tiết Sĩ Lăng","avatar":""},{"name":"Trần Nghiên Phi","avatar":""},{"name":"Dương Minh Uy","avatar":""},{"name":"Trần Dĩ Văn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Agent From Above","สายลับฟ้าส่ง","乩身：踏火伏魔的罪人","Agent from Above","乩身"]', 1784690324126);
