INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dinh-menh-vuot-xa-kich-ban-nam-tuong-tu', 'Định Mệnh Vượt Xa Kịch Bản (Nam Tương Tư)', 'Fate Beyond Script', 'https://phimimg.com/upload/vod/20260403-1/1a81a788d053423fc1898f9551900feb.jpg', 'https://phimimg.com/upload/vod/20260403-1/b6c85caecefa7bf3af1742028177ef41.jpg', '<p>Thiên kim tiểu thư Kim Châu hân hoan được gả cho Ninh Vương Chu Nam Chi. Thế nhưng, ngay trong đêm tân hôn, cô tình cờ nhìn thấy những dòng &quot;đạn mạc&quot; (bình luận chạy trên màn hình) và bàng hoàng nhận ra mình chỉ là một nữ phụ làm nền (pháo hôi) trong một cuốn truyện tranh ngôn tình cổ đại, và định mệnh là sẽ phải chết ngay trong đêm đó. Để tự cứu lấy mạng sống, Kim Châu đã lợi dụng những thông tin từ đạn mạc để nắm thóp bí mật của Lâu Tứ Ý. Một kẻ là &quot;pháo hôi&quot; đoản mệnh, một kẻ là nhân vật phản diện, họ bước vào cuộc đối đầu kịch tính nhưng rồi lại dần nảy sinh tình cảm chân thành qua những lần giao đấu. Tuy nhiên, tình yêu đi ngược lại thiết lập ban đầu là điều không được thế giới truyện tranh cho phép. Đối mặt với sự kìm kẹp của các quy tắc, nam nữ chính đã cùng nhau sát cánh để giải cứu vận mệnh và bảo vệ tình yêu của chính mình.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 19, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tăng Hựu Trăn","avatar":""},{"name":"Nghiêm Tử Hiền","avatar":""},{"name":"Trương Hiên Du","avatar":""},{"name":"Ngô Lạc Hàm","avatar":""},{"name":"Mao Duy Gia","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Nan Xiang Si","Fate of Southern Love","南相思"]', 1784690324126);
