INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-cung-ai-tinh', 'Mê Cung Ái Tình', 'Maze Of Love', 'https://phimimg.com/upload/vod/20260124-1/e26bcfddcca10421f15eff47851c7a81.jpg', 'https://phimimg.com/upload/vod/20260124-1/0cbb5c63e65ccf6825ec98b793aa0f3e.jpg', '<p>Mái ấm tưởng chừng như hoàn hảo giữa Tường Lan và Tùng bỗng sụp đổ với sự xuất hiện của kẻ thứ ba, một cô gái trẻ đẹp tên Angela. Không chỉ chen chân vào cuộc hôn nhân giữa Lan và Tùng, Angela còn rắp tâm muốn hủy hoại thanh danh và sự nghiệp của Lan. Sau một thời gian dài tranh chấp với chồng và tình nhân của chồng, cuối cùng Lan cũng có thể ra đi mà không phải đánh mất tất cả. Trong quá trình tìm lại bản thân sau cuộc hôn nhân thất bại, Lan bất ngờ rơi vào Mê Cung Ái Tình với một chàng trai trẻ. Liệu rằng đó sẽ là cái kết đẹp cho một chuyện tình cổ tích hay là âm mưu thâm độc nào khác?</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 20, 2026, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Ny Saki","avatar":""},{"name":"Trần Nhật Hào","avatar":""},{"name":"Nhật Dương","avatar":""},{"name":"Kim Ngân","avatar":""},{"name":"Trần Cường","avatar":""},{"name":"Hồng Điễm","avatar":""},{"name":"Khiết Đan","avatar":""},{"name":"Tuấn Kiệt","avatar":""},{"name":"Hữu Thạch","avatar":""},{"name":"Võ Minh Khải","avatar":""},{"name":"Mỹ Dung","avatar":""},{"name":"Khang An","avatar":""},{"name":"Công Hiếu","avatar":""},{"name":"Lim Phước Sang","avatar":""},{"name":"Phúc Lâm","avatar":""},{"name":"bé Quỳnh Anh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324126);
