INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('me-cung-ai-tinh', 'Mê Cung Ái Tình', 'Maze Of Love', 'mê cung ái tình maze of love ny saki trần nhật hào nhật dương kim ngân trần cường hồng điễm khiết đan tuấn kiệt hữu thạch võ minh khải mỹ dung khang an công hiếu lim phước sang phúc lâm bé quỳnh anh ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-quan', 'Tình Quan', 'The Ghost Marriage', 'https://phimimg.com/upload/vod/20260402-1/dddec363606390bf4c91d661fd445490.jpg', 'https://phimimg.com/upload/vod/20260402-1/7bd5cd7710774a0f550c2b479fa84ed8.jpg', '<p>Nữ diễn viên Liễu Thanh bị ma quái đeo bám hằng đêm, ranh giới giữa vai diễn và hiện thực dần bị xóa nhòa. Hồn ma đám cưới âm phủ cứ dai dẳng quấn lấy cô. Dưới bề ngoài hào nhoáng lại ẩn giấu những bí mật rợn người, một âm mưu đẫm máu được xây dựng trên sinh mạng của người khác! Một bác sĩ trẻ về vùng quê khám chữa bệnh miễn phí, bàng hoàng phát hiện người đàn bà điên trong làng chính là nữ minh tinh từng một thời nổi tiếng. Phía sau âm mưu tàn độc của tên bá chủ thôn làng là những bí ẩn tà dị kéo dài suốt trăm năm. Một lời nguyền kinh hoàng vượt qua thời đại đang lặng lẽ bao trùm tất cả. Liệu chuỗi sự kiện kỳ dị này có thực sự được chấm dứt?</p>', 'Full', 1, 'single', 'completed', 9, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Từ Tử Nhân","avatar":""},{"name":"Trương Tử Kiện","avatar":""},{"name":"Lưu Thượng Lân","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["情棺"]', 1784690324126);
