INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-menh-tru-doc', 'Sứ Mệnh Trừ Độc', 'Drug Hunt Mission', 'https://phimimg.com/upload/vod/20260402-1/d50913aa0a6c21ea5538c1d216d75dc8.jpg', 'https://phimimg.com/upload/vod/20260402-1/3b63f204e8db70745f2816619a26422a.jpg', '<p>Cảnh sát chìm sắt đá truy quét ma túy; người yêu nhuốm máu, mỗi người một chiến tuyến! Cảnh sát chống ma túy Nhân mang theo sứ mệnh, xâm nhập hang hùm ổ sói, sống chết khó lường. Anh thâm nhập bên cạnh trùm ma túy tàn bạo anh Sâm, nhưng phát hiện ra em gái ruột của Sâm lại chính là người anh yêu. Một bên là tình yêu sinh tử, tình thân ruột thịt; một bên là sứ mệnh phòng chống ma túy, kiên trì với công lý. Trong cục diện kinh hoàng, chính và tà đối đầu, thiện và ác giao tranh. Giữa tuyệt vọng sinh tử, anh sẽ đi về đâu?</p>', 'Full', 1, 'single', 'completed', 12, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jerry","avatar":""},{"name":"Na Tân","avatar":""},{"name":"Lưu Dịch Nhiên","avatar":""},{"name":"Đặng Khải Vân","avatar":""},{"name":"Trương Dũng","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["缉毒使命"]', 1784690324126);
