INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-khong-lo-cuoi-cung', 'Người Khổng Lồ Cuối Cùng', 'The Giant Falls', 'https://phimimg.com/upload/vod/20260402-1/a75803da961f3f47cc896c86e972b992.jpg', 'https://phimimg.com/upload/vod/20260402-1/a0b2c5aabbdd279a01aaae440aa1c840.jpg', '<p>Khi người cha bỏ đi từ lâu bất ngờ trở về, một hướng dẫn viên du lịch buộc phải đối diện với những vết thương cũ và đứng trước lựa chọn có thể định đoạt tương lai của cả hai.</p>', 'Full', 1, 'single', 'completed', 13, 2026, 'Vietsub', 'FHD', 'Argentina', 0, '[{"name":"Oscar Martínez","avatar":""},{"name":"Matías Mayer","avatar":""},{"name":"Inés Estévez","avatar":""},{"name":"Luis Luque","avatar":""},{"name":"Silvia Kutika","avatar":""},{"name":"Johanna Francella","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Giant Falls","L''Ultimo Gigante","El último gigante"]', 1784690324126);
