INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('len-nhu-dieu-gap-gio', 'Lên Như Diều Gặp Gió', 'Mamba', 'https://phimimg.com/upload/vod/20260402-1/36b8608b8ce88fe185965b120289cc06.jpg', 'https://phimimg.com/upload/vod/20260402-1/5a675862d2e5542656d459afeaa344f8.jpg', '<p>Nhà phát minh trẻ Trương Hữu Vi thuở nhỏ từng chứng kiến bố mình đột ngột qua đời vì nhồi máu cơ tim. Sự việc này đã để lại một vết sẹo khó phai trong tâm trí anh, thôi thúc anh phát minh ra một loại máy bay cứu thương khẩn cấp có khả năng cứu sống bệnh nhân. Từ đó, anh quyết tâm chế tạo ra một thiết bị bay cấp cứu có thể kịp thời cứu sống bệnh nhân trong những tình huống khẩn cấp. Sau những ngày đêm nỗ lực, anh cuối cùng đã thành công. Thế nhưng trên con đường tìm kiếm nguồn vốn để phát triển dự án, anh lại phải đối mặt với đủ loại người phức tạp và những trở ngại trớ trêu. Chuỗi hành trình ấy mang đến cho anh hàng loạt tình huống dở khóc dở cười đầy bất ngờ.</p>', 'Full', 1, 'single', 'completed', 11, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Siêu","avatar":""},{"name":"Lý Á Tuyên","avatar":""},{"name":"Giả Nhất Trạch","avatar":""},{"name":"Quách Giang Đào","avatar":""},{"name":"Trâu Đôn Minh","avatar":""},{"name":"Lý Phách","avatar":""},{"name":"Lý Bính Huy","avatar":""},{"name":"Mã Hy Khắc","avatar":""},{"name":"Vương Tân Bác","avatar":""},{"name":"Lư Lưu Lâm","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["飞黄腾达"]', 1784690324126);
