INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('den-dan-hon-2', 'Đèn Dẫn Hồn 2', 'Soul Guiding Lantern 2', 'https://phimimg.com/upload/vod/20260402-1/d8a8dcb708ce96b52f6885f8c078ff42.jpg', 'https://phimimg.com/upload/vod/20260402-1/455bdf1f70c606b0585721cd4a92eaff.jpg', '<p>Đầu thời Dân Quốc, bảo vật &quot;Đèn gọi hồn&quot; ẩn chứa bí thuật trường sinh. Các đệ tử trong Thiên Phong môn tranh giành nhau. Hoa Can Sinh thua trong cuộc tỉ thí với sư muội Đào Vân, tức giận rời núi và thề sẽ cướp bảo vật bí ẩn. Hai mươi năm sau, Đào Vân cứu được cô gái mồ côi Nguyệt Lạc Tịch mang mệnh toàn âm trong đám cháy. Tình cờ cô được công tử Liên Gia, Liên Thành Bích ái mộ. Hoa Can Sinh phát hiện ra sự tồn tại của Nguyệt Lạc Tịch. Nguyệt Lạc Tịch mang theo đèn gọi hồn thức tỉnh sức mạnh và đối đầu với Hoa Can Sinh tại tàn tích của sư môn năm xưa.</p>', 'Full', 1, 'single', 'completed', 15, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Thuần Vu San San","avatar":""},{"name":"Sa Cảnh Xương","avatar":""},{"name":"Trần Sáng","avatar":""},{"name":"Miêu Hải Trung","avatar":""},{"name":"Thi Tuấn Triết","avatar":""},{"name":"Hùng Tiểu Tiểu","avatar":""},{"name":"Dịch Lỵ","avatar":""},{"name":"Nhạc Đông Phong","avatar":""},{"name":"Tư Lực Canh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Soul-Guiding Lamp 2","Yin Hun Deng 2","引魂灯2"]', 1784690324126);
