INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('den-dan-hon-2', 'Đèn Dẫn Hồn 2', 'Soul Guiding Lantern 2', 'đèn dẫn hồn 2 soul guiding lantern 2 thuần vu san san sa cảnh xương trần sáng miêu hải trung thi tuấn triết hùng tiểu tiểu dịch lỵ nhạc đông phong tư lực canh soul-guiding lamp 2 yin hun deng 2 引魂灯2', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dap-tan-toi-ac', 'Đập Tan Tội Ác', 'Crush The Wicked', 'https://phimimg.com/upload/vod/20260402-1/24f9ef61173fb40a044f4ef9ddde4697.jpg', 'https://phimimg.com/upload/vod/20260402-1/a058c8dbcf3a2ce122ec5e8b9cd099bb.jpg', '<p>Năm 1992, băng nhóm tội phạm do Trương Bân cầm đầu đã gây ra nhiều vụ cướp xe và giết người. Cảnh sát hình sự Ngô Hiểu Quang theo đuổi hung thủ suốt tám năm nhưng vẫn chưa có kết quả. Tám năm sau, vì muốn cứu đứa con trai đang mắc bệnh, Trương Bân lại tái phạm. Lúc này, cảnh sát Ngô Hiểu Quang cùng Quan Siêu, người thân của một nạn nhân năm xưa, cùng nhau phối hợp điều tra. Sau khi vượt qua nhiều trở ngại, họ cuối cùng đã bắt được băng nhóm của Trương Bân vào năm 2000, kết thúc vụ án kéo dài tám năm.</p>', 'Full', 1, 'single', 'completed', 14, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Phan Bân Long","avatar":""},{"name":"Bao Bối Nhĩ","avatar":""},{"name":"Triệu Nhuận Nam","avatar":""},{"name":"Clara (Lý Thừa Mẫn)","avatar":""},{"name":"Chu Đại Dũng","avatar":""},{"name":"Vu Bách Lâm","avatar":""},{"name":"Quách Tử Hằng","avatar":""},{"name":"Hầu Hạo Nhiên","avatar":""},{"name":"Thích Tiểu Long","avatar":""},{"name":"Thang Trấn Nghiệp","avatar":""},{"name":"Lữ Khổng Duy","avatar":""},{"name":"Thường Thành","avatar":""},{"name":"Hà Bội Du","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["扫恶"]', 1784690324126);
