INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-kiem-ky-dam-cam-tam-kiem-phach', 'Cổ Kiếm Kỳ Đàm: Cầm Tâm Kiếm Phách', 'Swords Of Legends: Heart Of The Sword', 'https://phimimg.com/upload/vod/20260402-1/702c77d0c8659aa4d0daef95ae5847a0.jpg', 'https://phimimg.com/upload/vod/20260402-1/da31a42486651e2c7831f72c3b515d66.jpg', '<p>Tiên nhân Trường Cầm phạm lỗi nên bị đày xuống hạ giới, mệnh hồn của ông bị luyện thành hung kiếm Phần Tịch, còn tâm phách thì chuyển sinh thành người, chính là Âu Dương Thiếu Cung. Thanh kiếm Phần Tịch sau đó được phong ấn vào cơ thể Hàn Vân Khê. Thiếu Cung dần lạc vào con đường tà ác, gây họa cho bách tính. Để bảo vệ thiên hạ, Vân Khê đã cùng Thiếu Cung đồng quy vu tận. Người yêu của Vân Khê là Phong Tình Tuyết mang theo hồn phách của anh, bước lên hành trình dài tìm cách hồi sinh…</p>', 'Full', 1, 'single', 'completed', 17, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Bạch Chú","avatar":""},{"name":"Lương Tịnh Nhàn","avatar":""},{"name":"Khương Chấn Hạo","avatar":""},{"name":"Hoàng Nghệ","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["古剑奇谭之琴心剑魄"]', 1784690324126);
