INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-gioi-the-thao-cuoc-doi-va-cai-chet-cua-lamar-odom', 'Bí Mật Giới Thể Thao: Cuộc Đời Và Cái Chết Của Lamar Odom', 'Untold: The Death & Life Of Lamar Odom', 'https://phimimg.com/upload/vod/20260402-1/2b7f37841f4f07346d367188e668cb48.jpg', 'https://phimimg.com/upload/vod/20260402-1/948d8b99cc1ec713da1d13e4ae8551ed.jpg', '<p>Phim tài liệu này theo chân cuộc đời của Lamar Odom, từ khi anh vươn lên thành ngôi sao NBA và kết hôn với Khloé Kardashian đến vụ sốc thuốc suýt mất mạng tại một nhà thổ ở Nevada.</p>', 'Full', 1, 'single', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lamar Odom","avatar":""},{"name":"Khloé Kardashian","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["体坛秘史：拉玛·奥多姆的生死边缘","体坛秘史：拉玛尔·奥多姆的生死边缘","Untold: The Death & Life of Lamar Odom"]', 1784690324126);
