INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-ly-nha-xac', 'Trợ Lý Nhà Xác', 'The Mortuary Assistant', 'https://phimimg.com/upload/vod/20260402-1/d2f6ff7c5215b0313a62d6a77a408b86.jpg', 'https://phimimg.com/upload/vod/20260402-1/57b49f14ad1ed26df32b9a59c92380d3.jpg', '<p>Rebecca Owens, một sinh viên mới tốt nghiệp ngành khoa học nhà xác, nhận công việc ca đêm tại nhà xác River Fields. Ban đầu, công việc có vẻ đơn giản — ướp xác, hoàn thành giấy tờ và giữ gìn vệ sinh. Nhưng khi Rebecca bắt đầu làm ca đêm, mọi chuyện bắt đầu trở nên tăm tối.</p>', 'Full', 1, 'single', 'completed', 22, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Willa Holland","avatar":""},{"name":"Paul Sparks","avatar":""},{"name":"John Adams","avatar":""},{"name":"Mark Steger","avatar":""},{"name":"Shelly Gibson","avatar":""},{"name":"Emily Bennett","avatar":""},{"name":"Keena Ferguson","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["La morgue: Turno nocturno","Помощникът в моргата: Филмът","The Mortuary Assistant"]', 1784690324126);
