INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-kinh-ma-quai', 'Ống Kính Ma Quái', 'Bodycam', 'https://phimimg.com/upload/vod/20260401-1/72487aabd7466c67d527f03afcbbcab8.jpg', 'https://phimimg.com/upload/vod/20260401-1/e1de61b13a17ae0c450417a6be0ec884.jpg', '<p>Một cuộc gọi tưởng như bình thường dẫn hai sĩ quan cảnh sát đến một ngôi nhà yên ắng trong khu ngoại ô. Chỉ vài phút sau, không khí im lặng ấy vỡ tan bởi tiếng súng, và sai lầm khủng khiếp xảy ra — một người đàn ông cùng đứa con sơ sinh bị bắn chết ngay trước ống kính bodycam. Từ khoảnh khắc đó, mọi thứ trượt ra khỏi tầm kiểm soát. Những hình ảnh ghi lại dường như không chỉ đơn thuần là bằng chứng, mà còn mở ra một cánh cửa dẫn đến thứ gì đó vượt ngoài lý trí. Khi tội lỗi, sợ hãi và bóng tối dần nuốt chửng họ, các sĩ quan buộc phải đối mặt với câu hỏi: liệu có thứ gì đang ẩn nấp sau những thước phim, hay chính họ mới là người bị săn đuổi?</p>', 'Full', 1, 'single', 'completed', 22, 2026, 'Vietsub', 'FHD', 'Canada', 0, '[]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["911: Llamada Infernal","Bodycam"]', 1784690324126);
