INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-the-kiem-soat-con-tim', 'Chẳng Thể Kiểm Soát Con Tim', 'Lose My Heart To You', 'https://phimimg.com/upload/vod/20260327-1/c54f900e4dd3ca18ee0e7dbc34c30d09.jpg', 'https://phimimg.com/upload/vod/20260327-1/490ed79083d882fc6ef0c250bd051367.jpg', '<p>Vị tổng tài bá đạo Cố Thiên Thành sau khi trải qua ca phẫu thuật thay tim, đột nhiên bắt đầu nảy sinh tình cảm với Lâm Gia Kỳ, người vốn là thư ký của đối thủ không đội trời chung với mình trên thương trường. Từ thế đối đầu gay gắt, cả hai dần nhận ra nhịp đập chung của con tim qua những lần chạm trán trong công việc và cuộc sống, rồi quyết định cùng kề vai sát cánh, hướng đến mục tiêu chung.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 12, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Từ Hải Kiều","avatar":""},{"name":"Giả Thanh","avatar":""},{"name":"Trương Tường","avatar":""},{"name":"Lưu Quán Lân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["心爱的","순정에 반하다","心不由己"]', 1784690324126);
