INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('minh-chau-ky-dam-phan-1', 'Minh Châu Kỳ Đàm (Phần 1)', 'The Secret Of The Lost Pearl (Season 1)', 'https://phimimg.com/upload/vod/20260319-1/673f590c72d17254a4b579c2924c5c65.jpg', 'https://phimimg.com/upload/vod/20260319-1/30ebfd4f1d7b459de466be9f669f3cef.jpg', '<p>Một đôi giày thêu hoa đã mở ra hành trình phiêu lưu của chuyên gia cổ vật Trần Hữu Hi. Trên đường tìm kiếm ngọc Linh Tiêu, nhóm thám hiểm bốn người đã nhiều lần phải đối đầu với bọn trộm mộ. Nhưng sau khi tìm được viên ngọc Linh Tiêu đầu tiên, họ lại phát hiện mình đã rơi vào một âm mưu còn lớn hơn…</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tiêu Thuận Nghiêu","avatar":""},{"name":"Trương Chỉ Khê","avatar":""},{"name":"Lý Nhược Đồng","avatar":""},{"name":"Lý Trấn Trạch","avatar":""},{"name":"Tín Bằng","avatar":""},{"name":"Triệu Nghị","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["鬼吹灯","Ming Zhu Qi Tan","​明珠奇谭第二季​","​明珠奇谭第三季​","Candle in the Tomb","Ghost Blows Out the Light","The Secret of the Lost Pearl S3","明珠奇谭"]', 1784690324126);
