INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gieo-hong-dau-noi-duoi-may-nang', 'Gieo Hồng Đậu Nơi Đuôi Mày Nàng', 'Seeds Of Scarlet Longing', 'https://phimimg.com/upload/vod/20260401-1/0e1a3cc67cf2aedbf699b7b9836e3dba.jpg', 'https://phimimg.com/upload/vod/20260401-1/2aea3b06b5f3dfb004a54da7eed57646.jpg', '<p>Giang Chúc, một người phụ nữ mang trong mình lời nguyền thần bí, buộc phải tìm kiếm một người bạn đời để có thể tiếp tục tồn tại. Thế nhưng, một sự cố bất ngờ đã khiến cô dùng &quot;tình chú&quot; trói buộc vận mệnh của mình với Thẩm Mâu – một vị quan viên lạnh lùng, chính trực. Khi sợi dây liên kết giữa họ ngày càng sâu đậm, cả hai bắt đầu khám phá ra ý nghĩa thực sự của tình yêu. Họ quyết định sát cánh bên nhau để phơi bày sự thật và đòi lại công lý cho tộc nhân của cô.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 18, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trịnh Nghiệp Thành","avatar":""},{"name":"Triệu Tình","avatar":""},{"name":"Đặng Hiếu Từ","avatar":""},{"name":"Phó Đông Noãn","avatar":""},{"name":"Tiêu Nhiên Tâm","avatar":""},{"name":"Vương Diệu Thừa","avatar":""},{"name":"Đậu Nghệ Khôn","avatar":""},{"name":"Lục Vũ Tình","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Seeds of Scarlet Longing","在你眉梢种红豆"]', 1784690324126);
