INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-duong-phan-2', 'Thiên Đường (Phần 2)', 'Paradise (Season 2)', 'https://phimimg.com/upload/vod/20260304-1/58a28dc738c1e1fcef5cf515788e9365.jpg', 'https://phimimg.com/upload/vod/20260304-1/132e16e33ba4578ca8192f64058936b4.jpg', '<p>Đặc vụ Xavier Collins phát hiện ra một trong những người quyền lực nhất thế giới đã bị giết hại dã man. Nhưng sau cái chết bí ẩn của tổng thống, anh nhận ra bản thân đang nằm trong một âm mưu đe dọa lớn lao, không chỉ ở sự an toàn của bản thân mà còn là nền tự do của cả thế giới.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 13, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sterling K. Brown","avatar":""},{"name":"Julianne Nicholson","avatar":""},{"name":"Sarah Shahi","avatar":""},{"name":"Nicole Brydon Bloom","avatar":""},{"name":"Krys Marshall","avatar":""},{"name":"Enuka Okuma","avatar":""},{"name":"Aliyah Mastin","avatar":""},{"name":"Percy Daggs IV","avatar":""},{"name":"Charlie Evans","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["גן עדן","Paradise City","Paradise"]', 1784690324126);
