INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ikoku-nikki', 'Ikoku Nikki', 'Journal With Witch', 'https://phimimg.com/upload/vod/20260107-1/c562ce5068a116be3bc76180badf0b47.jpg', 'https://phimimg.com/upload/vod/20260107-1/006c08c92488f1bd117ade10eb657ae7.jpg', '<p>Tiểu thuyết gia sống ẩn dật Makio Koudai vốn luôn thích bầu bạn với những trang sách hơn là con người. Thế nhưng, khi người em gái và em rể đột ngột qua đời, Makio bất ngờ trở thành người giám hộ cho cô cháu gái 15 tuổi, Asa Takumi. Giữa nỗi đau mất mát, những nét tính cách đối lập và những khó khăn khi chung sống dưới một mái nhà, cả hai đã dần mở lòng với nhau, để rồi cùng khám phá ra hơi ấm, sự thấu cảm và ý nghĩa thực sự của hai tiếng gia đình.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 12, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Miyuki Sawashiro","avatar":""},{"name":"Fuko Mori","avatar":""},{"name":"Junichi Suwabe","avatar":""},{"name":"Sumire Morohoshi","avatar":""},{"name":"Eriko Matsui","avatar":""},{"name":"Takashi Kondo","avatar":""},{"name":"Sayaka Ohara","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ikoku Nikki","Worlds Apart","Diary of a Strange Land","Journal With Witch","違国日記"]', 1784690324126);
