INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-yeu-em-sau-dam-yeu-em-say-dam', 'Anh Yêu Em Sâu Đậm (Yêu Em Say Đắm)', 'Love Behind The Years', 'https://phimimg.com/upload/vod/20260320-1/cbccd6c8a00c7f57a9dab02bdd0c11c1.jpg', 'https://phimimg.com/upload/vod/20260320-1/2fb01eab312f3a03c0d9aee5f94dc230.jpg', '<p>Nhiều năm sau khi một hiểu lầm kết thúc mối tình thời thanh xuân, Phương Hân Nghiên và Giang Hải Dương tình cờ tái ngộ với tư cách đồng nghiệp và quyết định gác lại quá khứ để làm việc cùng nhau. Sau cái chết của chồng Phương Hân Nghiên, Giang Hải Dương đã luôn ở bên hỗ trợ cô vượt qua nỗi đau và cùng chăm sóc gia đình cô. Khi hành động sai lầm của một đồng nghiệp đẩy nhà máy vào cuộc khủng hoảng trầm trọng, cả hai đã hợp sức để khôi phục sự ổn định và giúp người đó tìm lại sự chuộc lỗi.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Phó Tinh","avatar":""},{"name":"Trình Phong","avatar":""},{"name":"Lý Siêu","avatar":""},{"name":"Tôn Sảng","avatar":""},{"name":"Sử Quang Huy","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wo Shen Shen De Ai Zhe Ni","我深深地愛著你","So Deep In Love Am I","我深深地爱着你"]', 1784690324126);
