INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-phuc-kim-an', 'Vạn Phúc Kim An', 'Glory Back', 'https://phimimg.com/upload/vod/20260317-1/38d4210cedab3142d931e619056519c0.jpg', 'https://phimimg.com/upload/vod/20260317-1/7c439da54dca8f9906fc78198f781b1c.jpg', '<p>Hoàng hậu Cố Thanh bị hãm hại, bỏ mạng trong biển lửa, sau đó hồn xuyên vào thân xác Phượng Khanh - tỳ nữ ở Thượng Y Cục. Để bảo vệ muội muội Cố Uyển và truy tìm hung thủ thật sự, nàng dùng thân phận tỳ nữ để khéo léo đối phó với đám phi tần. Ngoài ra, nàng còn liên thủ với đệ đệ là thái y Cố Huyền để đấu trí với khắp các thế lực trong hậu cung. Từng bước mưu tính cẩn trọng chốn thâm cung, sợi dây nhân duyên ràng buộc giữa nàng và bậc đế vương Tiêu Lạc cũng âm thầm được nối lại qua những lần đấu trí kịch liệt.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 16, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cao Dung Phương","avatar":""},{"name":"Triệu Hoa Vi","avatar":""},{"name":"Vương Nghệ Cẩn","avatar":""},{"name":"Ngô Mạnh Tư","avatar":""},{"name":"Trữ Tự Thuyên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wan Fu Jin An","万福金安"]', 1784690324126);
