INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('van-phuc-kim-an', 'Vạn Phúc Kim An', 'Glory Back', 'vạn phúc kim an glory back cao dung phương triệu hoa vi vương nghệ cẩn ngô mạnh tư trữ tự thuyên wan fu jin an 万福金安', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-chi-co-the-tuong-tuong-2', 'Tôi Chỉ Có Thể Tưởng Tượng 2', 'I Can Only Imagine 2', 'https://phimimg.com/upload/vod/20260331-1/a2968209e7fd206de4c366c5345b24d8.jpg', 'https://phimimg.com/upload/vod/20260331-1/806668d8e665dfcf50216892d04c6025.jpg', '<p>Sau thành công vang dội của ca khúc &quot;I Can Only Imagine&quot;, Bart Millard của nhóm MercyMe đang sống trong những ngày tháng rực rỡ nhất: những buổi biểu diễn cháy vé tại các đấu trường lớn, lượng người hâm mộ cuồng nhiệt và một sự nghiệp thăng hoa. Thế nhưng, đằng sau ánh hào quang sân khấu, quá khứ của Bart lại đang đe dọa hạnh phúc gia đình mà anh dày công vun đắp, đặc biệt là mối quan hệ mong manh với cậu con trai Sam.&nbsp; Khi tân binh đầy triển vọng Tim Timmons tham gia vào chuyến lưu diễn lớn nhất của ban nhạc, anh đã vô tình mang đến cho Bart một sự biết ơn mới mẻ thông qua tình bạn bất ngờ giữa hai người. Bart sớm nhận ra rằng chính Tim cũng đang mang trong mình những nỗi khổ tâm và bí mật riêng. Điều này buộc Bart phải đối diện với quá khứ, nỗ lực hàn gắn mối quan hệ với con trai Sam và người vợ Shannon trước khi sự nổi tiếng cướp đi những thứ quan trọng nhất trong cuộc đời anh.</p>', 'Full', 1, 'single', 'completed', 20, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"J. Michael Finley","avatar":""},{"name":"Milo Ventimiglia","avatar":""},{"name":"Sophie Skelton","avatar":""},{"name":"Arielle Kebbel","avatar":""},{"name":"Sammy Dell","avatar":""},{"name":"Mark Furze","avatar":""},{"name":"Ezra Proch","avatar":""},{"name":"Jason Burkey","avatar":""},{"name":"Aaron Benward","avatar":""},{"name":"Anjelah Johnson-Reyes","avatar":""},{"name":"Trace Adkins","avatar":""},{"name":"Dennis Quaid","avatar":""},{"name":"Randy McDowell","avatar":""},{"name":"Island Austin","avatar":""},{"name":"Jake Miles Johnston","avatar":""},{"name":"Isabella Moon","avatar":""},{"name":"Luk","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["I Can Only Imagine Sequel","אפשר רק לדמיין 2","I Can Only Imagine 2"]', 1784690324126);
