INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-vien-anh-hung-vigilantes-phan-2', 'Học Viện Anh Hùng: Vigilantes (Phần 2)', 'My Hero Academia: Vigilantes (Season 2)', 'https://phimimg.com/upload/vod/20260105-1/24c2d87f10a7357eedc94d84e6f1e902.jpg', 'https://phimimg.com/upload/vod/20260105-1/492761072f727011bb185b8a85ba9196.jpg', '<p>Học Viện Anh Hùng: Vigilantes là một góc nhìn khác về thế giới anh hùng, nơi những người hùng không giấy phép, những &quot;&quot;vệ binh&quot;&quot; đường phố, chiến đấu để bảo vệ thành phố. Koichi Haimawari, với năng lực khiêm tốn, khoác lên mình bộ trang phục lấy cảm hứng từ All Might, dấn thân vào hành trình hành hiệp bất hợp pháp. Bộ phim là cuộc phiêu lưu đầy thử thách, nơi ranh giới giữa chính nghĩa và tội ác trở nên mong manh, và những góc khuất của xã hội siêu anh hùng được phơi bày.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 16, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shuichiro Umeda","avatar":""},{"name":"Ikumi Hasegawa","avatar":""},{"name":"Yasuhiro Mamiya","avatar":""},{"name":"Kenta Miyake","avatar":""},{"name":"Junichi Suwabe","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["正义使者 -我的英雄学院之非法英雄-","My Hero Academia Vigilantes","אקדמיית הגיבורים שלי: פורעי חוק","ヴィジランテ 僕のヒーローアカデミア ILLEGALS","Vigilante: Boku no Hero Academia ILLEGALS","ヴィジランテ -僕のヒーローアカデミア ILLEGALS- 第2期","Моя геройская академия: Вне закона","Моя геройська академія: Вігіланти","Моя геройська академія: Лінчувальники","Vigilante -My Hero Academia ILLEGALS-","MHA Vigilantes","ヴィジランテ -僕のヒーローアカデミア ILLEGALS-"]', 1784690324126);
