INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoc-vien-anh-hung-vigilantes-phan-2', 'Học Viện Anh Hùng: Vigilantes (Phần 2)', 'My Hero Academia: Vigilantes (Season 2)', 'học viện anh hùng: vigilantes (phần 2) my hero academia: vigilantes (season 2) shuichiro umeda ikumi hasegawa yasuhiro mamiya kenta miyake junichi suwabe 正义使者 -我的英雄学院之非法英雄- my hero academia vigilantes אקדמיית הגיבורים שלי: פורעי חוק ヴィジランテ 僕のヒーローアカデミア illegals vigilante: boku no hero academia illegals ヴィジランテ -僕のヒーローアカデミア illegals- 第2期 моя геройская академия: вне закона моя геройська академія: вігіланти моя геройська академія: лінчувальники vigilante -my hero academia illegals- mha vigilantes ヴィジランテ -僕のヒーローアカデミア illegals-', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-tich-phan-1-2026', 'Mất Tích (Phần 1)', 'Vanished (Season 1)', 'https://phimimg.com/upload/vod/20260304-1/3922581e4c647faf8eead7c35af1b282.jpg', 'https://phimimg.com/upload/vod/20260304-1/8cf421d75d25d250b3a92c113b3f13b3.jpg', '<p>Bộ phim xoay quanh Alice Monroe, một nhà khảo cổ học người Mỹ đang tận hưởng mối tình lãng mạn kéo dài 4 năm với Tom Parker, một nhân viên cứu trợ nhân đạo có vẻ ngoài hoàn hảo. Câu chuyện bắt đầu khi Alice nhận được một vị trí giảng dạy danh giá tại Đại học Princeton và rủ Tom cùng ổn định cuộc sống tại New Jersey (Mỹ). Trước khi bắt đầu chương mới của cuộc đời, họ quyết định thực hiện một chuyến tàu hỏa lãng mạn từ Paris đến Arles (miền Nam nước Pháp). Tuy nhiên, bi kịch ập đến khi Tom rời khỏi chỗ ngồi trên tàu để nghe một cuộc điện thoại và không bao giờ quay trở lại. Không thể chờ đợi sự giúp đỡ từ chính quyền sở tại, Alice tự mình lần theo các dấu vết. Cô nhận được sự giúp đỡ từ Hélène (một phụ nữ Pháp tình cờ gặp trên tàu) và bắt đầu khám phá ra những bí mật đen tối về người đàn ông mà cô định gắn bó cả đời. Sự kết hợp giữa bối cảnh thơ mộng của nước Pháp và bầu không khí căng thẳng, nghẹt thở của một vụ mất tích bí ẩn. Diễn xuất của Kaley Cuoco trong vai người phụ nữ tuyệt vọng đi tìm sự thật được giới phê bình phim đánh giá cao khiến đây là một bộ phim phù hợp dành cho cho những khán giả yêu thích thể loại truy tìm sự thật và những âm mưu ẩn giấu đằng sau những mối quan hệ tưởng chừng như hoàn hảo.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 15, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kaley Cuoco","avatar":""},{"name":"Sam Claflin","avatar":""},{"name":"Karin Viard","avatar":""},{"name":"Matthias Schweighöfer","avatar":""},{"name":"Simon Abkarian","avatar":""},{"name":"Dar Zuzovsky","avatar":""},{"name":"Olivier Sa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Vanished"]', 1784690324126);
