INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trang-chieu-ruc-ro', 'Trăng Chiều Rực Rỡ', 'In The Clear Moonlit Dusk', 'https://phimimg.com/upload/vod/20260113-1/f8b8e380c7706cc6437b74f832ffbfc9.jpg', 'https://phimimg.com/upload/vod/20260113-1/e2b63c3c759af96194e8d24d35228bcd.jpg', '<p>Yoi Takiguchi là một nữ sinh trung học năm nhất, cô luôn được mọi người ngưỡng mộ bởi vẻ ngoài điển trai cùng trái tim chân thành, điều này đã giúp cô có biệt danh là &#39;Hoàng tử&#39;. Một ngày nọ, cô tình cờ va phải Kohaku Ichimura, một đàn anh khóa trên và cũng là một &#39;Hoàng tử&#39; khác của trường. Khi cả hai dần trở nên thân thiết hơn, liệu thứ tình cảm đang nảy nở giữa họ là tình bạn hay tình yêu? Câu chuyện tình yêu tuổi trẻ giữa một chàng trai và một cô gái đều được gọi là &#39;Hoàng tử&#39; chính thức bắt đầu!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Rei Ichinomiya","avatar":""},{"name":"Ryota Suzuki","avatar":""},{"name":"Aya Yamane","avatar":""},{"name":"Momoko Seto","avatar":""},{"name":"Shota Hayama","avatar":""},{"name":"Kentaro Kumagai","avatar":""},{"name":"Kensho Ono","avatar":""},{"name":"Kenjiro Tsuda","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["皎洁迎宵之月","Uruwashi no Yoi no Tsuki","Mooning Over You","うるわしの宵の月"]', 1784690324127);
