INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-phan-dien-duoc-hoang-tu-nuoc-lang-gieng-yeu-men', 'Nữ Phản Diện Được Hoàng Tử Nước Láng Giềng Yêu Mến', 'The Villainess Is Adored by the Prince of the Neighbor Kingdom', 'https://phimimg.com/upload/vod/20260114-1/ed13ec167659375eabecf986662cfe12.jpg', 'https://phimimg.com/upload/vod/20260114-1/91ee78b105a7f89504686b54e3aad4d2.jpg', '<p>Tiararose Lapis Clementille bàng hoàng nhận ra mình đã tái sinh thành vị hôn thê phản diện trong trò chơi mô phỏng hẹn hò từng chơi ở kiếp trước. Tại lễ tốt nghiệp, Hoàng tử Hartknights kết tội cô, hủy hôn và trục xuất khỏi vương quốc để chọn nữ chính Akari làm vợ. Khi số phận tưởng chừng khép lại, Hoàng tử Aquasteed của quốc gia láng giềng bất ngờ xuất hiện và bày tỏ tình yêu với Tiararose. Từ một kẻ bị ruồng bỏ, cô bước vào cuộc sống mới tràn ngập yêu thương và hy vọng. Hành trình thay đổi số phận của nữ phản diện chính thức bắt đầu.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 13, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Mai Fuchigami","avatar":""},{"name":"Yuuichirou Umehara","avatar":""},{"name":"Takuya Sato","avatar":""},{"name":"Yumiri Hanamori","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The.Villiainess.Is.Adored.by.the.Crown.Prince.of.the.Neighboring.Kingdom","Akuyaku Reijō wa Ringoku no Ōtaishi ni Dekiai Sareru","Akuyaku Reijou wa Ringoku no Outaishi ni Dekiai Sareru","Akudeki","被鄰國王太子溺愛的反派千金","The Villainess Is Adored by the Prince of the Neighbor Kingdom","悪役令嬢は隣国の王太子に溺愛される"]', 1784690324127);
