INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-khoan-2026', 'Tử Khoản', 'Dead Account', 'https://phimimg.com/upload/vod/20260113-1/c425695aff7590f7d643a28cd1854366.jpg', 'https://phimimg.com/upload/vod/20260113-1/f08d56e30aae2c66237412ef5f7d9a64.jpg', '<p>&quot;Gengo Matsunaga, người từng vang danh với biệt hiệu &#39;Phượng Hoàng&#39;, là võ sĩ diệt hỏa vĩ đại nhất khắp vùng Edo. Sau khi gác kiếm từ bỏ nghề chữa cháy, Gengo nhận được lời mời từ phiên bang Shinjo. Được sự cổ vũ từ người vợ Miyuki, ông đã lên đường để gây dựng lại một đội cứu hỏa vốn đã lụi tàn. Gengo tập hợp một nhóm những kẻ &#39;bất đắc chí&#39; và lập nên Đội diệt hỏa Ragged (Nhóm diệt hỏa rách rưới), cùng nhau điều tra những vụ hỏa hoạn bí ẩn được gây ra bởi kẻ phóng hỏa khét tiếng Kitsunebi (Hỏa Hồ).</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 11, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Nobuhiko Okamoto","avatar":""},{"name":"Koki Uchiyama","avatar":""},{"name":"Fairouz Ai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Dead Account: Conta Desativada","死亡账号","デッドアカウント"]', 1784690324127);
