INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-mua-khuynh-thanh', 'Mùa Mưa Khuynh Thành', 'Turbulent Love', 'https://phimimg.com/upload/vod/20260319-1/4f7e456ecc6780830f62020b5ecfe9b4.jpg', 'https://phimimg.com/upload/vod/20260319-1/5d0e7d458102bdcbb230b2bce160b07c.jpg', '<p>Tại cảng Theron ở nước ngoài, Hác Vũ, con gái nuôi của cảnh sát trưởng, đã thâm nhập vào băng đảng dưới danh nghĩa người cung cấp thông tin và trở thành bạn gái của Thái tử băng đảng Quý Tri Tiết. Quý Tri Tiết, với tính cách tàn bạo và quyết đoán, mặc dù biết rõ cô là người cung cấp thông tin, nhưng vẫn sẵn lòng bị cuốn vào mối tình này, thậm chí còn liều mạng bảo vệ cô. Khi người yêu cũ của Hác Vũ là cảnh sát Chu Tử Hành trở về, họ sẽ đưa ra sự lựa chọn gì giữa công lý, sự thật và tình yêu?</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 12, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Phàn Trị Hân","avatar":""},{"name":"Lỗ Chiếu Hoa","avatar":""},{"name":"Lại Gia Binh","avatar":""},{"name":"Ngô Quý Phong","avatar":""},{"name":"Thị Tuyên Như","avatar":""},{"name":"Tôn Thiên Dữ","avatar":""},{"name":"Mẫn Chính","avatar":""},{"name":"Yiu Ging Lee","avatar":""},{"name":"Chung Viễn Triết","avatar":""},{"name":"Lý Hồng Vũ","avatar":""},{"name":"Chu Bái Thần","avatar":""},{"name":"Tiêu Mộ Trần","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["暗涌","계우경성 : 비와 같은 사랑","Invisible Love","季雨倾城"]', 1784690324127);
