INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-dieu-hanh-trigun-phan-2', 'Cuộc Diễu Hành Trigun (Phần 2)', 'Trigun Stargaze', 'https://phimimg.com/upload/vod/20260113-1/68b58f8d873a08a660a0c93fb8ecaeac.jpg', 'https://phimimg.com/upload/vod/20260113-1/9cdb692f4d61387ca704239e3da438ff.jpg', '<p>Vash the Stampede là một tay súng yêu hòa bình và luôn tràn đầy lạc quan, vậy tại sao anh ta lại bị treo thưởng lên tới <strong>6 triệu đô-la</strong>? Đó chính là điều khiến cô phóng viên tập sự Meryl Stryfe và người cộng sự kỳ cựu dày dạn kinh nghiệm của mình cảm thấy khó hiểu. Khi điều tra về gã dân binh này, họ chỉ tìm thấy một kẻ cực kỳ ghét bạo lực và đổ máu. Thế nhưng, cuộc điều tra của họ đã vô tình hé lộ một sự thật kinh hoàng — sự tồn tại của người em trai sinh đôi tàn ác của anh, Millions Knives.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yoshitsugu Matsuoka","avatar":""},{"name":"Sakura Ando","avatar":""},{"name":"Yoshimasa Hosoya","avatar":""},{"name":"Chika Ayamori","avatar":""},{"name":"Ryuji Sato","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["枪神 史丹比特","TRIGUN STAMPEDE（トライガン・スタンピード）","トライガン・スタンピード","TRIGUN STARGAZE","トライガン・スターゲイズ","TRIGUN STARGAZE(トライガン・スターゲイズ)","트라이건 스타게이즈","Триган: Бегство","槍神 史坦畢特","TRIGUN STAMPEDE"]', 1784690324127);
