INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-vat-va-cua-mao-hiem-gia-doc-than-29-tuoi', 'Cuộc Sống Vất Vả Của Mạo Hiểm Giả Độc Thân 29 Tuổi', 'An Adventurer''s Daily Grind At Age 29', 'https://phimimg.com/upload/vod/20260109-1/0c437b0a63c50038c39c25522a5096b8.jpg', 'https://phimimg.com/upload/vod/20260109-1/f9f09ba53269993eb0dffcffd3298278.jpg', '<p>Sinh ra và lớn lên trong khu ổ chuột, Hajime Shinonome – một mạo hiểm giả 29 tuổi – hiện đang tận hưởng cuộc sống bình lặng tại ngôi làng Komai. Thế nhưng, chuỗi ngày yên ả ấy bỗng chốc đảo lộn khi anh phát hiện Lirui, một cô bé bị bỏ rơi, đang bị lũ Slime tấn công. Xúc động trước sự tuyệt vọng của cô bé và nhìn thấy hình ảnh của chính mình năm xưa, Hajime đã đưa cô về làng chăm sóc. Từ đây, Hajime và Lirui bắt đầu một chương mới trong cuộc đời, nơi đan xen giữa những thử thách bất ngờ và những ngày tháng dịu dàng bên nhau!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 11, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Makoto Furukawa","avatar":""},{"name":"Sayumi Suzushiro","avatar":""},{"name":"Shizuka Itoh","avatar":""},{"name":"Yuuki Kuwahara","avatar":""},{"name":"Yuna Ogata","avatar":""},{"name":"Kaori Maeda","avatar":""},{"name":"Tomohiro Ono","avatar":""},{"name":"Haruka Shiraishi","avatar":""},{"name":"Yasunori Matsumoto","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["29-sai Dokushin Chūken Bōkensha no Nichijō","29-sai Dokushin Chuuken Boukensha no Nichijou","29sai Dokushin Chuuken Boukensha no Nichijou","The Daily Life of a Single 29-Year-Old Adventurer","29歳独身中堅冒険者の日常"]', 1784690324127);
