INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-song-vat-va-cua-mao-hiem-gia-doc-than-29-tuoi', 'Cuộc Sống Vất Vả Của Mạo Hiểm Giả Độc Thân 29 Tuổi', 'An Adventurer''s Daily Grind At Age 29', 'cuộc sống vất vả của mạo hiểm giả độc thân 29 tuổi an adventurer''s daily grind at age 29 makoto furukawa sayumi suzushiro shizuka itoh yuuki kuwahara yuna ogata kaori maeda tomohiro ono haruka shiraishi yasunori matsumoto 29-sai dokushin chūken bōkensha no nichijō 29-sai dokushin chuuken boukensha no nichijou 29sai dokushin chuuken boukensha no nichijou the daily life of a single 29-year-old adventurer 29歳独身中堅冒険者の日常', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tiem-tham-tu-nu-kiem-lan', 'Tiệm Thám Tử Nữ Kiếm Lan', 'Excellent Women', 'https://phimimg.com/upload/vod/20260330-1/c10a292b87dfffa3af794959c5ec375b.jpg', 'https://phimimg.com/upload/vod/20260330-1/6cbec98f57078f166505c65e980108ce.jpg', '<p>Nhà ngoại cảm Ngô Nguyệt hợp sức cùng một nữ cảnh sát, một chuyên gia pháp y và một họa sĩ phác họa hiện trường để điều tra chuỗi vụ án gây rúng động, từ những vụ giả chết sống lại cho đến những kẻ sát nhân hàng loạt. Khi đội điều tra toàn nữ của họ càng đào sâu, Ngô Nguyệt vô tình chạm mặt Kỷ Văn Tuyên – một người thừa kế giàu có đang che giấu những bí mật sâu kín, kéo họ vào một âm mưu gia tộc đầy nguy hiểm. Khi sự thật dần lộ diện, những người phụ nữ không chỉ phải đối mặt với những kẻ sát nhân xảo quyệt, mà còn phải đối diện với mặt tối của lòng người, những khao khát dục vọng và sự báo thù tàn khốc.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 13, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Hạo Hiên","avatar":""},{"name":"Trần Tư Dư","avatar":""},{"name":"Lư Đông Húc","avatar":""},{"name":"Lâm Phàm","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["剑兰女探社"]', 1784690324127);
