INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luc-nao-ta-cung-se-gap-lai', 'Lúc Nào Ta Cũng Sẽ Gặp Lại', 'Always Meet Again', 'https://phimimg.com/upload/vod/20260330-1/6e67c6b3034c916dc0497a8aa0d3e213.jpg', 'https://phimimg.com/upload/vod/20260330-1/ed82ccdb08236710bb238f3def1a9735.jpg', '<p>Sau khi tỉnh dậy và thấy mình trở lại tuổi 18, một họa sĩ nổi tiếng đã được đoàn tụ với mối tình đầu của mình và đối mặt với cơ hội hiếm có để viết lại câu chuyện của hai người.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 12, 2026, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Woo Ji-han","avatar":""},{"name":"Shin Jeong-u","avatar":""},{"name":"Seo Seung-hyun","avatar":""},{"name":"Min Do-hee","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["与你重逢","Eonjena Dasi Manna","언제나다시만나","總會再相遇","We''ll Always Meet Again","언제나 다시 만나"]', 1784690324127);
