INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chieu-tuyet', 'Chiêu Tuyết', 'The Vindication Of Shadows', 'https://phimimg.com/upload/vod/20260330-1/c9bad990ee517fdd51c80aac7dd8028f.jpg', 'https://phimimg.com/upload/vod/20260330-1/28952c228e936cb08eb84ecdf323e73d.jpg', '<p>Cải trang thành nam nhi, Tô Chiêu Tuyết tiến vào kinh thành để tìm ra sự thật đằng sau vụ thảm sát oan uổng của gia đình mình và tìm lại người em gái mất tích. Bắt tay cùng với Ngự sử Phương Cơ, nàng điều tra một vụ án phù thủy, dẫn dắt họ đến với một âm mưu sâu rộng, buộc cả hai phải mạo hiểm mọi thứ để vạch trần nó.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 25, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vu Hiên Thần","avatar":""},{"name":"Mộc Lam","avatar":""},{"name":"Thường Triết Khoan","avatar":""},{"name":"Trang Dĩnh","avatar":""},{"name":"Trương Phong Lâm","avatar":""},{"name":"Tống Vũ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Zhao Xue","昭雪"]', 1784690324127);
