INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chieu-tuyet', 'Chiêu Tuyết', 'The Vindication Of Shadows', 'chiêu tuyết the vindication of shadows vu hiên thần mộc lam thường triết khoan trang dĩnh trương phong lâm tống vũ zhao xue 昭雪', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-sinh-thanh-trung-rong-muc-tieu-khong-gi-khac-ngoai-tro-thanh-ke-manh-nhat-tensei-shitara-dragon-no-tamago-datta', 'Chuyển Sinh Thành Trứng Rồng – Mục Tiêu Không Gì Khác Ngoài Trở Thành Kẻ Mạnh Nhất (Tensei shitara Dragon no Tamago datta)', 'Reincarnated As A Dragon Hatchling', 'https://phimimg.com/upload/vod/20260204-1/43669447db69559618789cfcdad9f5f3.jpg', 'https://phimimg.com/upload/vod/20260204-1/e510e640e8eea7a668395eb4a00ed7fc.jpg', '<p>Tôi tỉnh dậy trong một khu rừng mà mình chưa từng thấy bao giờ.

Nơi đó trông như một thế giới giả tưởng xa lạ.

Nhìn xung quanh, tôi chỉ thấy toàn là những quái vật đáng sợ.

Rồi tôi nhìn lại bản thân mình, và…

Hả? Cái quái gì thế này

Tôi bị chuyển sinh thành… một quả trứng sao?!

Cuối cùng thì tôi có thể tiến hóa thành rồng, nhưng nếu muốn nở ra, tôi phải chiến đấu với quái vật và nâng cấp cấp độ.

Nhưng chiến đấu kiểu gì chứ? Tôi chỉ là một quả trứng thôi mà!

Rồi tôi cũng tiến hóa được, nhưng khi cuối cùng gặp được con người, họ lại cho rằng tôi là quái vật.

Tôi chỉ muốn làm bạn với con người thôi mà, mọi người ơi!

Luôn ở trong tình trạng nguy hiểm đến tính mạng!

Những ngày phiêu lưu của Illusia, một con người chuyển sinh thành trứng rồng vẫn cứ tiếp diễn mãi không hồi kết!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shunichi Toki","avatar":""},{"name":"Ami Koshimizu","avatar":""},{"name":"Miku Ito","avatar":""},{"name":"Rie Kugimiya","avatar":""},{"name":"Tomori Kusunoki","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Tensei shitara Dragon no Tamago datta","ドラたま","DoraTama","Reincarnated as a Dragons Egg","転生したらドラゴンの卵だった～最強以外目指さねぇ～"]', 1784690324127);
