INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('osananajimi-to-wa-love-comedy-ni-naranai', 'Osananajimi to wa Love Comedy ni Naranai', 'You Can''t Be in a Rom-Com with Your Childhood Friends! (No More Love With the Girls.)', 'https://phimimg.com/upload/vod/20260107-1/3421f2919cd655a3447bad5e9b2ee768.jpg', 'https://phimimg.com/upload/vod/20260107-1/e97947fa3fdfa547b299eeb0046388fc.jpg', '<p>Eiyuu - một cậu học sinh cao trung, hiện đang có một vấn đề! Hai người bạn thuở nhỏ của cậu ấy quá đỗi dễ thương! Nếu như hai người họ phát hiện ra cậu ấy nhìn với ánh mắt tục tĩu (mặc dù không có ý đó...), thì cậu ấy sẽ chết mất! Ngoài ra, hai người đó cũng có bí mật riêng của mình... Thật kỳ quặc và xấu hổ, nhưng dù sao bạn thuở nhỏ vẫn là nhất! Một câu chuyện ngọt ngào và vội vã giữa một mối tình tay ba đầy những điều giấu kín!&nbsp;</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 11, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Rin Kusumi","avatar":""},{"name":"Yu Serizawa","avatar":""},{"name":"Sae Hiratsuka","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["青梅竹马的恋爱喜剧无法成立","You Can’t Be in a Rom-Com with Your Childhood Friends!","Osananajimi to wa Love Comedy ni Naranai","Osananajimi to wa LoveCom ni Naranai","Osananajimi to wa Lovecome ni Naranai","No more love with the girls.","I''ll Never Have a Romantic Comedy with My Childhood Friend","It Won''t Become a Romcom with Childhood Friends Misu Shinya","No More Love With the Girls","幼馴染とはラブコメにならない"]', 1784690324127);
