INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('arne-no-jikenbo', 'Arne no Jikenbo', 'The Case Book Of Arne', 'https://phimimg.com/upload/vod/20260213-1/4f03b60ad8531bf7485194312236801e.jpg', 'https://phimimg.com/upload/vod/20260213-1/87a9d3c3fbb951dfe1f2950af3e95004.jpg', '<p>Arne Neuntöte là một thám tử ma cà rồng có khả năng điều khiển các sức mạnh siêu nhiên. Lynn Reinweiß là con gái của một quý tộc, người yêu thích ma cà rồng. Thế giới của họ lẽ ra không bao giờ nên giao nhau, nhưng họ lại bắt tay nhau để giải quyết một bí ẩn đẫm máu. Trong đêm tối nhất, Lynn thấy mình đang rất cần sự giúp đỡ. Rồi cô lạc vào thành phố bí ẩn &quot;Lügenberg&quot;, nơi sinh sống của những sinh vật không phải con người.&nbsp; Thế giới của Lynn thay đổi hoàn toàn khi cô gặp &quot;Arne&quot;, một ma cà rồng được gọi là &quot;kẻ tồi tệ nhất&quot; trong thành phố. Và đêm nay, một &quot;vụ án mạng&quot; mới đã xảy ra. Sự thật đằng sau những sự kiện kỳ lạ diễn ra trong một thế giới nơi con người và những điều kỳ quái giao thoa là gì?&nbsp; &quot;Nào, con người. Ngươi có thể vui vẻ nhảy múa dưới ánh trăng đỏ thắm.&quot;</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Mariya Ise","avatar":""},{"name":"Koki Uchiyama","avatar":""},{"name":"Aimi Tanaka","avatar":""},{"name":"Yuka Nukui","avatar":""},{"name":"Yuki Sakakihara","avatar":""},{"name":"Yuuki Shin","avatar":""},{"name":"Yoko Hikasa","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Arne no Jiken-bo","Arne no Jikenbo","The Casebook of Arne","アルネの事件簿"]', 1784690324127);
