INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-tra-hole-harry-hole', 'Thanh Tra Hole (Harry Hole)', 'Detective Hole', 'https://phimimg.com/upload/vod/20260330-1/cae05ecb448b0832fe8b16496bb18e15.jpg', 'https://phimimg.com/upload/vod/20260330-1/e1312c80ee6249864898a1ecd47b4b39.jpg', '<p>Khi hàng loạt án mạng theo nghi thức xảy ra ở Oslo, viên thanh tra tài ba nọ phải xoay xở với những quy luật tội ác, sự biến chất và cả ác quỷ nội tâm để tóm gọn tên sát nhân.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 31, 2026, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Tobias Santelmann","avatar":""},{"name":"Joel Kinnaman","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jo Nesbøs Harry Hole","Jo Nesbø''s Harry Hole","Детектив Холе","Jo Nesbø''s Detective Hole","Jo Nesbo''s Detective Hole","Jo Nesboe''s Harry Hole","Harry Hole"]', 1784690324127);
