INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cau-lac-bo-ban-bi-mat', 'Câu Lạc Bộ Bạn Bí Mật', 'The Secret Friends Club', 'câu lạc bộ bạn bí mật the secret friends club yoshihiro akiyama noh hong-chul lee su-ji dex jennie jung hae-in go youn-jung park myung-soo kim do-hoon yoon nam-no hong jin-kyung cha tae-hyun park bo-young lee sun-bin hwang kwang-hee kang hoon 秘密朋友俱乐部 마니또 클럽 the secret friends club manitto club', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kho-thai-hoa', 'Khổ Thái Hoa', 'The Lettuce', 'https://phimimg.com/upload/vod/20260330-1/fcb470a16ffdab0da5008891d731febc.jpg', 'https://phimimg.com/upload/vod/20260330-1/a90a9686f234ef3a79dbcc568567fb78.jpg', '<p>Lấy bối cảnh tại làng Vương Quan, vùng Kiều Đông, Sơn Đông trong thời kỳ kháng chiến chống Nhật, bộ phim xoay quanh gia đình người nông dân Phùng Đức Cường. Sau khi cha mình bị quân Nhật và bọn hán gian sát hại, Phùng Đức Cường đã tham gia Bát Lộ quân và trưởng thành thành một chiến sĩ ưu tú. Em gái anh là Quyên Tử cũng tham gia vào cuộc đấu tranh kháng chiến dưới sự lãnh đạo của đảng viên Khương Vĩnh Tuyền.&nbsp; Dưới sự ảnh hưởng của các con, người mẹ cũng dấn thân vào con đường kháng chiến. Bà đã phải chịu đựng những đòn tra tấn dã man và mất đi đứa con gái út do sự phản bội của tên hán gian Vương Giản Chi. Sau khi vạch trần hành vi phản bội của Vương Giản Chi và thi hành bản án tử hình hắn, Phùng Đức Cường đã giả danh hán gian để thâm nhập vào đồn bốt quân Nhật nhằm thu thập tình báo. Cuối cùng, anh phối hợp cùng Bát Lộ quân tấn công và giải phóng huyện lỵ đang bị quân Nhật chiếm đóng.</p>', 'Hoàn Tất (39/39)', 39, 'series', 'completed', 12, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Hồng Chu","avatar":""},{"name":"Lý Lâm","avatar":""},{"name":"Trương Dĩnh","avatar":""},{"name":"Đào Hồng","avatar":""},{"name":"Quách Gia Minh","avatar":""},{"name":"Lý Thành Nho","avatar":""},{"name":"Quách Khải Mẫn","avatar":""},{"name":"Triệu Lượng","avatar":""},{"name":"Duật Húc Đông","avatar":""},{"name":"Trương Lập","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Lettuce"]', 1784690324127);
