INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('kho-thai-hoa', 'Khổ Thái Hoa', 'The Lettuce', 'khổ thái hoa the lettuce vương hồng chu lý lâm trương dĩnh đào hồng quách gia minh lý thành nho quách khải mẫn triệu lượng duật húc đông trương lập the lettuce', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-o-dai-hoc-tu-sua-van-vat', 'Tôi Ở Đại Học Tu Sửa Văn Vật', 'Glaze Of Love', 'https://phimimg.com/upload/vod/20260329-1/1d9af2ca5b8f3d5e0bab61f5412e61e9.jpg', 'https://phimimg.com/upload/vod/20260329-1/80418d9f25ec30338a8598c031388c0e.jpg', '<p>Hứa Kiêu là một chàng trai đầy kiêu ngạo nhưng sở hữu kỹ năng phục chế cổ vật cực kỳ cao siêu. Ngược lại, Triệu Tiểu Sầm lại là một cô gái luôn mang trong mình nỗi sợ hãi giao tiếp xã hội. Cả hai tình cờ quen biết và trở thành một đội khi cùng thực hiện bài tập phục chế đồ sứ trên lớp. Dưới sự giúp đỡ tận tình của Hứa Kiêu, Triệu Tiểu Sầm dần mở lòng mình với thế giới xung quanh; đồng thời, Hứa Kiêu cũng nhờ sự ảnh hưởng của cô mà hóa giải được những mâu thuẫn bấy lâu với gia đình. Sau khi trải qua những hiểu lầm và trắc trở, tình cảm của họ càng thêm gắn bó. Cả hai cùng nhau bắt đầu hành trình bảo vệ di sản văn hóa và sẵn sàng đón nhận những thử thách trong tương lai.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 12, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lại Vĩ Minh","avatar":""},{"name":"Chu Ích Như","avatar":""},{"name":"Trần Thánh Hanh","avatar":""},{"name":"Vương Kiều Hy","avatar":""},{"name":"Nghiệp Văn","avatar":""},{"name":"Vương Giang Nhất","avatar":""},{"name":"Hứa Thuần","avatar":""},{"name":"Dư Miểu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wo Zai Da Xue Xiu Wen Wu","我在大學修文物","我在大学修文物"]', 1784690324127);
