INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hac-nguyet-te-dan-cua-trang', 'Hắc Nguyệt: Tế Đàn Của Trăng', 'Dark Moon: The Blood Altar', 'https://phimimg.com/upload/vod/20260110-1/5c17ac3b9bc9dcb637556ddb179b5638.jpg', 'https://phimimg.com/upload/vod/20260110-1/be3ea96c106dd6a3ea056e99d25ab84e.jpg', '<p>Từ nhỏ, Sooha đã phải che giấu năng lực siêu phàm của mình để tránh bị nhầm là ma cà rồng, nhưng cô vẫn bị đổ lỗi gây ra cái chết cho người bạn thân. Mang theo nỗi oan khuất, Sooha ghi danh vào Học viện Decelis - ngôi trường có những lớp học ban đêm, nơi các sinh vật siêu nhiên bị cấm bước vào. Tại đây, cô gặp Heli và nhóm bạn bí ẩn gồm Jaan, Jino, Shion, Jakah, Noa và Solon, những người dường như đang bị cô thu hút một cách mạnh mẽ. Khi một loạt vụ giết người liên quan đến ma cà rồng xảy ra, quá khứ đen tối và mối liên hệ thực sự của bảy chàng trai dần lộ diện. Bị cuốn vào mối thù truyền kiếp giữa ma cà rồng và người sói, Sooha phải đối mặt với sự thật rằng cô đang ở rất gần những sinh vật mà mình từng căm ghét nhất.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 16, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kikunosuke Toya","avatar":""},{"name":"Hiroto Shimizu","avatar":""},{"name":"Shugo Nakamura","avatar":""},{"name":"Jin Ogasawara","avatar":""},{"name":"Shunichi Toki","avatar":""},{"name":"Yuto Uemura","avatar":""},{"name":"Chiaki Kobayashi","avatar":""},{"name":"Fuka Izumi","avatar":""},{"name":"Taihi Kimura","avatar":""},{"name":"Hayato Dojima","avatar":""},{"name":"Shohei Komatsu","avatar":""},{"name":"Shoya Chiba","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Dark Moon: Tsuki no Saidan","DARK MOON Kuro no Tsuki Tsuki no Saidan","HẮC NGUYỆT","DARK MOON　-黒の月: 月の祭壇-"]', 1784690324127);
