INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-khuat-cua-tamonkun-hai-mat-cua-tamon', 'Mặt Khuất Của Tamon-kun (Hai Mặt Của Tamon)', 'Tamon''s B-Side', 'https://phimimg.com/upload/vod/20260101-1/56122b8a707ce9874ca3d4750122d37f.jpg', 'https://phimimg.com/upload/vod/20260101-1/3d0e3fa30e9810729e524474dacfdd7d.jpg', '<p>Nhóm nhạc thần tượng F/ACE đang nổi đình nổi đám nhờ Tamon Fukuhara - trưởng nhóm điển trai, có phong cách trình diễn hoang dã và đầy tài năng. Utage Kinoshita, cô gái 17 tuổi, là một fan cuồng nhiệt, hết mình ủng hộ Tamon và làm việc bán thời gian tại công ty dọn dẹp nhà cửa. Một ngày nọ, Utage được giao phụ trách việc chăm sóc căn hộ cho một khách hàng cũng mang tên Tamon và không ngờ người đó chính là thần tượng mà cô hằng ngưỡng mộ. Tuy nhiên, trái ngược với hình ảnh rực rỡ trên sân khấu, anh chàng ngoài đời lại u sầu, thiếu tự tin và cô độc. Quyết tâm bảo vệ bí mật của anh, Utage ở bên động viên Tamon, mở ra những tình huống vừa hài hước vừa ấm áp, phơi bày “mặt sáng” và “mặt tối” của một idol.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 13, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Saori Hayami","avatar":""},{"name":"Kakeru Hatano","avatar":""},{"name":"Shoya Chiba","avatar":""},{"name":"Tasuku Hatanaka","avatar":""},{"name":"Kohei Amasaki","avatar":""},{"name":"Ryuho Nagaoka","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["现在的是哪一个多闻！？","现在的是哪一个多闻！ ？","多聞くん今どっち!?","Tamon''s B-Side, Which Face Does Tamon Have Now?","Tamon s B-side","多聞くん今どっち！？"]', 1784690324127);
