INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thua-phong-du', 'Thừa Phong Du', 'Riding On The Wind', 'https://phimimg.com/upload/vod/20260329-1/b482322c4c0a25cece3b6a754f9eec06.jpg', 'https://phimimg.com/upload/vod/20260329-1/6fdae6dbb5a0c154367a08b910746815.jpg', '<p>Vào triều đại nhà Tống, thần đồng hội họa trẻ tuổi Hy Mạnh thăng tiến trong Học viện Hội họa Hoàng gia, đồng thời phải đối mặt với những mối quan hệ sư đồ phức tạp, sự đố kỵ và lòng trung thành nơi triều đình. Khi hành trình của anh gắn liền với Hoàng đế Huy Tông, những nỗ lực và sự thức tỉnh của anh cuối cùng đã trở thành nguồn cảm hứng tạo nên kiệt tác hội họa huyền thoại &quot;Thiên Lý Giang Sơn Đồ&quot;.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 16, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Nghiêm Ngật Khoan","avatar":""},{"name":"Chu Lịch Kiệt","avatar":""},{"name":"Trần Bách Dung","avatar":""},{"name":"Lôi Thụ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["乘風遊","Cheng Feng You","乘风游"]', 1784690324127);
