INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thua-phong-du', 'Thừa Phong Du', 'Riding On The Wind', 'thừa phong du riding on the wind nghiêm ngật khoan chu lịch kiệt trần bách dung lôi thụ 乘風遊 cheng feng you 乘风游', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuy-long-ngam-2026', 'Thủy Long Ngâm', 'Dianchi Sleeping Beauty', 'https://phimimg.com/upload/vod/20260329-1/9d2e2db7c290f21e1b797616db3a601a.jpg', 'https://phimimg.com/upload/vod/20260329-1/520713fa2038620dafae898ecdc08f61.jpg', '<p>Thuở hồng hoang mới mở, đất trời nuôi dưỡng ba vị thần thú: Tổ Long, Nguyên Phượng và Kỳ Lân. Sau trận đại chiến chấn động lục địa, ba vị thần thú ngã xuống. Trước khi tạ thế, Tổ Long đã để lại một viên Thất Bảo Linh Châu, được long tộc đời đời canh giữ. Công chúa long tộc Ao Linh cùng Vân Uyên đã kề vai sát cánh chống lại ma tộc vốn luôn dòm ngó viên linh châu. Trong lúc cứu Vân Uyên, Ao Linh bị trọng thương, mất đi ký ức và rơi vào giấc ngủ sâu, viên linh châu cũng theo đó mà vỡ tan.&nbsp; Để tìm Càn Khôn Đỉnh nhằm phục hồi linh châu, Vân Uyên đã lặn lội tới vùng Côn Di, dùng chính thân mình làm vật dẫn để hóa giải lệ khí suốt ngàn năm, được bách tính tôn xưng là Côn Di Vương. Ngàn năm sau, Ao Linh tỉnh lại và du ngoạn đến Côn Di, tại đây cô gặp lại Vân Uyên nhưng lại xem anh như người xa lạ. Trải qua bao sóng gió, Vân Uyên đã phục hồi được linh châu, Ao Linh cũng tìm lại được ký ức.&nbsp; Lúc này, ma tộc quay trở lại, vì muốn đoạt lấy linh châu và Càn Khôn Đỉnh, chúng đã thi triển độc chú không lời giải mang tên &quot;Hoàng Tuyền Bích Lạc&quot; nhằm lật đổ tam giới. Ao Linh vượt qua kiếp nạn tại Long Môn, thức tỉnh sức mạnh của Tổ Long và cùng Vân Uyên chống lại kẻ thù. Để bảo vệ địa mạch Côn Di và cứu rỗi sinh linh khỏi cảnh lầm than, Ao Linh đã hòa mình vào đá ngũ sắc, hóa thân thành dãy núi Mỹ Nhân Ngủ (Thụy Mỹ Nhân sơn), còn Vân Uyên cùng Càn Khôn Đỉnh hóa thành dòng nước hồ Điền Trì. Núi sông ôm ấp, đời đời kiếp kiếp thủ hộ vùng đất linh thiêng Côn Di này.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'ongoing', 24, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Từ Lan Địch","avatar":""},{"name":"Quách Hân","avatar":""},{"name":"Lưu Vũ Trạch","avatar":""},{"name":"Phạm Gia Kỳ","avatar":""},{"name":"Tiêu Ảnh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shui Long Yin","古滇传说水龙吟","水龙吟"]', 1784690324127);
