INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-cam-do-nong-bong-duc-phan-2', 'Sự Cám Dỗ Nóng Bỏng: Đức (Phần 2)', 'Too Hot To Handle: Germany (Season 2)', 'https://phimimg.com/upload/vod/20260329-1/6ca333c0661d1d40e52e854cbda19d62.jpg', 'https://phimimg.com/upload/vod/20260329-1/0691c50965d13f685e2dffadbf461ed6.jpg', '<p>Mười người độc thân quyến rũ cùng hội ngộ tại một thiên đường nhiệt đới. Họ không hề biết rằng để giành được giải thưởng trị giá 200.000 €, họ sẽ phải từ bỏ hoàn toàn việc quan hệ tình dục.</p>', 'Hoàn Tất (8/8)', 8, 'tvshows', 'completed', 21, 2026, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Brenda Brinkmann","avatar":""},{"name":"Joena Steilen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Too Hot to Handle: Germany"]', 1784690324127);
