INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mot-dieu-rat-toi-te-sap-xay-ra', 'Một Điều Rất Tồi Tệ Sắp Xảy Ra', 'Something Very Bad Is Going To Happen', 'một điều rất tồi tệ sắp xảy ra something very bad is going to happen camila morrone adam dimarco gus birney jeff wilbusch karla crome jennifer jason leigh ted levine zlatko burić sawyer fraser something very bad is going to happen', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-madison-phan-1', 'Vùng Đất Madison (Phần 1)', 'The Madison (Season 1)', 'https://phimimg.com/upload/vod/20260322-1/fcdebf18a66a1a64fb85cfebc9125312.jpg', 'https://phimimg.com/upload/vod/20260322-1/dcefd5ed3d2695d10ab23b72bbb8ceee.jpg', '<p>Bộ phim xoay quanh gia đình Clyburn, một gia đình thượng lưu sống cuộc đời xa hoa bậc nhất tại Manhattan, New York. Bi kịch ập đến khi Preston Clyburn, là người chồng - người cha và là trụ cột chính của gia đình và em trai Paul tử nạn trong một vụ rơi máy bay tại vùng núi Montana khi đang đi câu cá. Cái chết đột ngột này khiến người vợ, Stacy, là một “cô gái thành phố chính hiệu”, người ghét sự hoang dã và thiếu tiện nghi của vùng nông thôn rơi vào khủng hoảng sâu sắc, bà quyết định đưa cả gia đình (gồm hai cô con gái, một chàng rể và các cháu ngoại) rời bỏ New York chuyển đến thung lũng sông Madison, Montana để thực hiện di nguyện của người chồng quá cố là gắn bó với vùng đất này và để chính Stacy tìm kiếm sự chữa lành. Nếu bạn đang tìm một bộ phim chữa lành, một drama gia đình đa thế hệ diễn ra nơi miền quê xa xôi, vừa hài hước vừa giàu tính nhân văn, nhẹ nhàng nhưng đầy sắc sảo trong từng câu thoại với lối chơi chữ tinh tế mang đậm dấu ấn của Taylor Sheridan… được đánh giá là tác phẩm &quot;đời&quot; nhất và giàu cảm xúc nhất của Taylor Sheridan tính đến thời điểm hiện tại, với sự góp mặt của hai huyền thoại điện ảnh là Michelle Pfeiffer và Kurt Russell thì đây chắc chắn là lựa chọn không thể bỏ qua.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 34, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Michelle Pfeiffer","avatar":""},{"name":"Kurt Russell","avatar":""},{"name":"Beau Garrett","avatar":""},{"name":"Patrick J. Adams","avatar":""},{"name":"Elle Chapman","avatar":""},{"name":"Amiah Miller","avatar":""},{"name":"Alaina Pollack","avatar":""},{"name":"Ben Schnetzer","avatar":""},{"name":"Kevin Zegers","avatar":""},{"name":"Rebecca Spence","avatar":""},{"name":"Matthew Fox","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Річка Медісон","2024","The Madison"]', 1784690324127);
