INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-vo-hinh-va-vo-tuong-lai-cua-anh-ta', 'Người Vô Hình Và Vợ Tương Lai Của Anh Ta', 'The Invisible Man And His Soon-to-Be Wife', 'https://phimimg.com/upload/vod/20260109-1/9c7f266aacd9b091b3e84ea1349cc9bc.jpg', 'https://phimimg.com/upload/vod/20260109-1/7cc35028e620e60c87a0ae04a88627b7.jpg', '<p>Akira Tounome là một quý ông tàng hình đang điều hành một văn phòng thám tử, và Shizuka Yakou là một người phụ nữ khiếm thị có tính cách dịu dàng làm việc tại đó. Shizuka luôn luôn có thể tìm thấy Akira, ngay cả khi anh ấy trở nên hoàn toàn vô hình. Tình yêu bắt đầu nảy nở giữa hai người khi họ xích lại gần nhau hơn qua từng ngày. Một câu chuyện tình cảm hài hước, cảm động nhưng cũng đầy những khoảnh khắc &#39;ngọt ngào đến phát hờn&#39; chuẩn bị bắt đầu!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 16, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yohei Azakami","avatar":""},{"name":"Yuka Nukui","avatar":""},{"name":"Riho Sugiyama","avatar":""},{"name":"Masaya Fukunishi","avatar":""},{"name":"Tomohiro Ono","avatar":""},{"name":"Kaori Ishihara","avatar":""},{"name":"Junya Enoki","avatar":""},{"name":"Shinnosuke Tachibana","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Herr Unsichtbar und seine zukünftige Frau","Tōmei Otoko to Ningen Onna: Sonouchi Fūfu ni Naru Futari","Toumei Otoko to Ningen Onna: Sonouchi Fuufu ni Naru Futari","Toumei Otoko to Ningen Onna Sonouchi Fuufu ni Naru Futari","투명남과 인간녀 곧 부부가 될 두 사람","透明男子與人類女孩～兩人遲早會成為夫妻～","Невидимець і звичайна дівчина: ці двоє скоро стануть парою","Invisible Man & Human Lady","The Invisible Man and the Human Woman: Two People Who Will Soon Become Husband and Wife","透明男と人間女～そのうち夫婦になるふたり～"]', 1784690324127);
