INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chen-thanh-cua-eris', 'Chén Thánh Của Eris', 'The Holy Grail Of Eris', 'https://phimimg.com/upload/vod/20260109-1/41713201f176b8fe3190b2618594d0b0.jpg', 'https://phimimg.com/upload/vod/20260109-1/63a9246498e3e810e00736fe720e1fe9.jpg', '<p>Bị hãm hại bởi nhân tình của vị hôn phu và bị tuyên án tử hình công khai, Constance Grail – cô con gái giản dị và chân thật của một vị Tử tước – tưởng như đã phải đối mặt với cái chết, cho đến khi một giọng nói bí ẩn vang lên đề nghị sự cứu rỗi. Scarlett Castiel, một quý tộc lẫy lừng đã chết từ lâu, có lẽ là hy vọng duy nhất của cô. Cùng nhau, hai người đồng minh không ngờ tới này đã bắt đầu lật tẩy một âm mưu đen tối đang ẩn mình nơi trung tâm của giới thượng lưu — nơi mà sự phản bội, những bí mật và quyền lực va chạm khốc liệt.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 12, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kana Ichinose","avatar":""},{"name":"Sayumi Suzushiro","avatar":""},{"name":"Yohei Azakami","avatar":""},{"name":"Mao Ichimichi","avatar":""},{"name":"Maaya Uchida","avatar":""},{"name":"Natsuki Hanae","avatar":""},{"name":"Jun Fukuyama","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Erisu no Seihai","エリスのせいはい","Eris no Seihai","エリスの聖杯"]', 1784690324127);
