INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cach-giet-de-giau', 'Cách Giết Để Giàu', 'How to Make a Killing', 'https://phimimg.com/upload/vod/20260326-1/ff2f8db597515bacf6e998151469d750.jpg', 'https://phimimg.com/upload/vod/20260326-1/a49b480b41178b119dfec7cce224c592.jpg', '<p>Bị gia đình siêu giàu ruồng bỏ ngay từ khi chào đời, Becket Redfellow — một gã lao động chân tay — sẵn sàng làm mọi thứ để giành lại phần thừa kế của mình, bất chấp phải loại bỏ bao nhiêu người thân đang đứng chắn đường.</p>', 'Full', 1, 'single', 'completed', 18, 2026, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Glen Powell","avatar":""},{"name":"Margaret Qualley","avatar":""},{"name":"Jessica Henwick","avatar":""},{"name":"Ed Harris","avatar":""},{"name":"Bill Camp","avatar":""},{"name":"Topher Grace","avatar":""},{"name":"Zach Woods","avatar":""},{"name":"Bianca Amato","avatar":""},{"name":"Raff Law","avatar":""},{"name":"Alexander Hanson","avatar":""},{"name":"Nell Williams","avatar":""},{"name":"Sean Cameron Michael","avatar":""},{"name":"Grady Wilson","avatar":""},{"name":"Maggie Toomey","avatar":""},{"name":"Lisa Tredoux","avatar":""},{"name":"James Frecheville","avatar":""},{"name":"Martin Munro","avatar":""},{"name":"Susa","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Huntington","Rothchild","Kā novākt radiņus","L''ultime heritier","Jugada Maestra","How to Make a Killing"]', 1784690324127);
