INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cach-giet-de-giau', 'Cách Giết Để Giàu', 'How to Make a Killing', 'cách giết để giàu how to make a killing glen powell margaret qualley jessica henwick ed harris bill camp topher grace zach woods bianca amato raff law alexander hanson nell williams sean cameron michael grady wilson maggie toomey lisa tredoux james frecheville martin munro susa huntington rothchild kā novākt radiņus l''ultime heritier jugada maestra how to make a killing', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-gom-xac', 'Kẻ Gom Xác', 'We Bury the Dead', 'https://phimimg.com/upload/vod/20260210-1/832dd9e501fa59d93ccf7122a0c80dbb.jpg', 'https://phimimg.com/upload/vod/20260210-1/e22ef637e0350274f942b33741b25e0c.jpg', '<p>Sau một thảm họa quân sự chưa từng có, thế giới rơi vào hỗn loạn khi những người đã chết bất ngờ sống dậy. Chính quyền trấn an rằng họ chậm chạp, vô hại – và các gia đình có thể yên tâm rằng người thân của mình vẫn còn “đâu đó”. Nhưng Ava (Daisy Ridley) không tin. Khi chồng cô mất tích trong khu cách ly, cô liều mình xâm nhập vào vùng cấm, nơi tin đồn nói rằng các xác chết đang trở nên khác thường.Giữa không khí ngột ngạt, những dãy hành lang bỏ hoang và âm thanh rền rĩ của loa cảnh báo, Ava phát hiện ra sự thật kinh hoàng: những “kẻ trở lại” không còn là nạn nhân, mà là thợ săn. Càng về sau, chúng càng nhanh hơn, khát máu hơn, như thể đang tiến hóa từng phút một. Và khi quân đội cố che giấu mọi thứ, Ava phải lựa chọn giữa chạy trốn hay đối mặt với điều đang chờ trong bóng tối — thứ có thể xóa sổ toàn bộ nhân loại nếu bị thả ra ngoài.</p>', 'Full', 1, 'single', 'completed', 16, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Úc', 0, '[{"name":"Daisy Ridley","avatar":""},{"name":"Brenton Thwaites","avatar":""},{"name":"Mark Coles Smith","avatar":""},{"name":"Matt Whelan","avatar":""},{"name":"Chloe Hurst","avatar":""},{"name":"Kym Jackson","avatar":""},{"name":"Holly Hargreaves","avatar":""},{"name":"Deanna Cooney","avatar":""},{"name":"Elijah Williams","avatar":""},{"name":"Salme Geransar","avatar":""},{"name":"Luke Jai  McIntosh","avatar":""},{"name":"Joel Jackson","avatar":""},{"name":"Dan Paris","avatar":""},{"name":"Nicola Bartlett","avatar":""},{"name":"Kim Fleming","avatar":""},{"name":"Kingsley Judd","avatar":""},{"name":"Megan Holl","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["We Bury the Dead"]', 1784690324127);
