INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-ma-anh-quoc-nguoi-bat-tu', 'Bóng Ma Anh Quốc: Người Bất Tử', 'Peaky Blinders: The Immortal Man', 'https://phimimg.com/upload/vod/20260320-1/3d6f579d26f2f3938a9fce5bba7e448e.jpg', 'https://phimimg.com/upload/vod/20260320-1/53505c93750c4c1be12c5a24f81a19de.jpg', '<p>Sau khi cậu con trai xa cách bị cuốn vào một âm mưu của Đức Quốc xã, trùm tội phạm sống lưu vong Tommy Shelby buộc phải trở lại Birmingham để cứu gia đình và bảo vệ đất nước.</p>', 'Full', 1, 'single', 'completed', 21, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Anh', 0, '[{"name":"Cillian Murphy","avatar":""},{"name":"Tim Roth","avatar":""},{"name":"Rebecca Ferguson","avatar":""},{"name":"Barry Keoghan","avatar":""},{"name":"Sophie Rundle","avatar":""},{"name":"Stephen Graham","avatar":""},{"name":"Ned Dennehy","avatar":""},{"name":"Packy Lee","avatar":""},{"name":"Ian Peck","avatar":""},{"name":"Jay Lycurgo","avatar":""},{"name":"Kasper Hilton-Hille","avatar":""},{"name":"Ruby Ashbourne Serkis","avatar":""},{"name":"Thomas Arnold","avatar":""},{"name":"Sam Baker Jones","avatar":""},{"name":"Iain Fletcher","avatar":""},{"name":"Jasna Anderson","avatar":""},{"name":"Sammy Jonas","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Immortal Man: A Peaky Blinders Film","The Immortal Man","Gangy z Birminghamu: Nesmrtelný muž","Peaky Blinders: O Homem Imortal","Peaky Blinders - The Immortal Man","Peaky Blinders: The Immortal Man"]', 1784690324127);
