INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lieu-mang-tron-chay', 'Liều Mạng Trốn Chạy', 'Desperate Dash', 'null', 'https://phimimg.com/upload/vod/20260326-1/6b45ea22d6c92a16f519ba168d47fb44.jpg', '<p>Nhà vật lý thiên tài Trình Huyền đã phát minh ra chiếc nhẫn đi xuyên thời-không, anh dùng nó để du hành đến nhiều chiều không gian và thời gian khác nhau, cho rằng khoa học công nghệ có thể thay đổi thế giới. Một nhóm thế lực xấu xa vẫn luôn nhòm ngó chiếc nhẫn du hành thời-không của Trình Huyền, chúng nghĩ đủ mọi cách cử nhiều người đến để bày kế chiếm đoạt nó. Vì vậy Trình Huyền không thể không chạy trốn!</p>', 'Full', 1, 'single', 'completed', 13, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Desperate Dash","绝地狂奔"]', 1784690324127);
