INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-cuoc-song', 'Trò chơi cuộc sống', 'The Game of Life', 'https://phimimg.com/upload/vod/20260326-1/a2ba3f6960755515333256c1119fdce8.jpg', 'https://phimimg.com/upload/vod/20260326-1/a98733198c83fb66c13474ed72cb17c6.jpg', '<p>Jack Folly là một lập trình viên trí tuệ nhân tạo thông minh, khó tính và thất nghiệp. Khi bạn gái thúc giục anh ta bắt đầu đóng góp tài chính cho gia đình, anh ta đã liều lĩnh đánh cược vào thị trường chứng khoán bằng chương trình trí tuệ nhân tạo mới của mình, &quot;Babylon&quot;. Nhưng ván cược phản tác dụng, khiến Jack mất tiền, mất người yêu và cả sự tỉnh táo.</p>', 'Full', 1, 'single', 'completed', 11, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Nick Salazar","avatar":""},{"name":"Brittany Shonka","avatar":""},{"name":"Alexa Potts","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["The Game of Life"]', 1784690324127);
