INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-aryan-papers', 'The Aryan Papers', 'The Aryan Papers', 'https://phimimg.com/upload/vod/20260326-1/d88dd128714bb1a6fb8fff38d0e1f923.jpg', 'https://phimimg.com/upload/vod/20260326-1/631cccdd5adc87372d7e325e7cca5228.jpg', '<p>Stuttgart, 1942: Phát xít Đức đã dẹp tan các cộng đồng Do Thái khỏi các thị trấn và làng mạc. Hai đứa trẻ Do Thái sinh ra ở Đức chạy trốn khỏi phát xít Đức, những kẻ đã giết hại gia đình chúng, được Gisella hộ tống. Gisella là thành viên của Lebensborn, một chương trình &quot;Chủng tộc thượng đẳng&quot; của SS.</p>', 'Full', 1, 'single', 'completed', 23, 2026, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Cara Chase","avatar":""},{"name":"Leona Clarke","avatar":""},{"name":"Richard Hawley","avatar":""},{"name":"Alex Reece","avatar":""},{"name":"Matthew Hendrickson","avatar":""},{"name":"Grayson James Matthews","avatar":""},{"name":"Jade Morris","avatar":""},{"name":"Celia Learmonth","avatar":""},{"name":"Lauren Staerck","avatar":""},{"name":"Moses Gomes-Santos","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["The Aryan Papers"]', 1784690324127);
