INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-thanh-tra', 'Nữ Thanh Tra', 'Yogida', 'https://phimimg.com/upload/vod/20260326-1/7e3e93cbd5ec473f66d49c7d0cde9212.jpg', 'https://phimimg.com/upload/vod/20260326-1/d4411c24b94b6d43506199f31b47f97a.jpg', '<p>Câu chuyện kể về Yogi, một nữ thanh tra cảnh sát trung thực và thẳng thắn, làm việc tại Coimbatore. Tại đây, cô chứng minh vụ &quot;tự sát&quot; của một chủ xưởng dệt thực chất là một vụ giết người do chính con trai ông ta gây ra, dẫn đến việc cô bị điều chuyển đến khu vực trừng phạt Vyasarpadi ở phía Bắc Chennai. Ở đó, cô đối đầu với trùm tội phạm tàn nhẫn Shekar Babu, kẻ kiểm soát khu vực và lực lượng cảnh sát bằng sự sợ hãi, quyền lực và ảnh hưởng chính trị, nhưng Yogi từ chối khuất phục và bắt đầu hành động chống lại mạng lưới của hắn.</p>', 'Full', 1, 'single', 'completed', 17, 2026, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Sai Dhanshika","avatar":""},{"name":"Kabir Duhan Singh","avatar":""},{"name":"Sayaji Shinde","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Yogi Da","யோகிடா"]', 1784690324127);
