INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-nghi-duong-cua-chang-quy-toc-on-hoa-odayaka-kizoku-no-kyuuka-no-susume', 'Kỳ Nghỉ Dưỡng Của Chàng Quý Tộc Ôn Hòa (Odayaka Kizoku no Kyuuka no Susume)', 'A Gentle Noble''s Vacation Recommendation', 'https://phimimg.com/upload/vod/20260116-1/b5aed4ddbb54e3c808d9dddd70d210ee.jpg', 'https://phimimg.com/upload/vod/20260116-1/7a62aea1dfc99613d6e4fadfae9fdd89.jpg', '<p>Lizel, vị thủ tướng trẻ tuổi đầy tài ba của một quốc gia hùng mạnh trong vương quốc giả tưởng, đột nhiên thấy mình bị dịch chuyển đến một thế giới khác — ngay giữa lúc đang trò chuyện. Không hề bối rối, anh quyết định coi đây như một chuyến nghỉ phép và trở thành một nhà mạo hiểm! Bắt cặp với Gil, một cao thủ hạng nhất thích hành động độc hành, Lizel đã vận dụng sự nhạy bén, sức hút và trí tuệ siêu việt của mình để khám phá thế giới mới này. Từ đây, những cuộc phiêu lưu đầy ngẫu hứng của một quý tộc đang trong kỳ nghỉ chính thức bắt đầu!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Soma Saito","avatar":""},{"name":"Yuuichirou Umehara","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Odayaka Kizoku no Kyuuka no Susume.","優雅貴族的休假指南","A Gentle Nobles Vacation Recommendation","穏やか貴族の休暇のすすめ。"]', 1784690324127);
