INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('no-le-cua-ma-do-tinh-binh-phan-2', 'Nô Lệ Của Ma Đô Tinh Binh (Phần 2)', 'Chained Soldier (Season 2)', 'https://phimimg.com/upload/vod/20260110-1/19f2d88ca8a30cbead7ebfd4d05017fe.jpg', 'https://phimimg.com/upload/vod/20260110-1/6afc2a9035c96502a69aafdc937868f9.jpg', '<p>Bỗng nhiên những cánh cổng bí ẩn đã xuất hiện trên khắp Nhật Bản.

Bên kia cánh cổng là dị thứ nguyên được gọi là Ma Đô, nơi có những trái đào ban cho các thiếu nữ năng lực đặc biệt nếu ăn chúng. Để tiêu diệt Xú Quỷ đến từ nơi này, một lực lượng chiến đấu toàn các nữ chiến binh đã được thành lập với tên gọi Kháng Ma Đội.

Một ngày nọ, chàng thiếu niên tên Wakura Yuuki đã lạc vào Ma Đô trong lúc đang đi tìm đường mưu sinh và bị Xú Quỷ tấn công. Uzen Kyouka, đội trưởng xinh đẹp của Phân đội 7 thuộc Kháng Ma Đội đã lập tức tới ứng cứu. Kyouka có năng lực biến Yuuki thành nô lệ và khiến cậu có thể đánh bại Xú Quỷ. Từ đó, Yuuki đã trở thành nô lệ kiêm tạp vụ của Kháng Ma Đội.

Câu chuyện giả tưởng về “chàng thiếu niên bị xiềng xích” sẽ bắt đầu!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 14, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuya Hirose","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["魔都精兵的奴隸","Esclavo de los soldados de élite de la ciudad mágica","Mato Seihei no Slave","Prajurit yang Dirantai","Mato Seihei no Sureibu","魔都精兵のスレイブ2","Demon Slave","Slave of the Magic Capital''s Elite Troops","Slave of the Hell Soldiers","Nô Lệ Của Đội Tinh Nhuệ Ma Đô","魔都精兵のスレイブ"]', 1784690324127);
