INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('no-le-cua-ma-do-tinh-binh-phan-2', 'Nô Lệ Của Ma Đô Tinh Binh (Phần 2)', 'Chained Soldier (Season 2)', 'nô lệ của ma đô tinh binh (phần 2) chained soldier (season 2) yuya hirose 魔都精兵的奴隸 esclavo de los soldados de élite de la ciudad mágica mato seihei no slave prajurit yang dirantai mato seihei no sureibu 魔都精兵のスレイブ2 demon slave slave of the magic capital''s elite troops slave of the hell soldiers nô lệ của đội tinh nhuệ ma đô 魔都精兵のスレイブ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-bo-tat-ca-toi-se-chien-dau-cho-mot-cuoc-song-binh-thuong-voi-tinh-yeu-cua-doi-minh-va-chiec-thanh-kiem-bi-nguyen-rua', 'Từ Bỏ Tất Cả, Tôi Sẽ Chiến Đấu Cho Một Cuộc Sống Bình Thường Với Tình Yêu Của Đời Mình Và Chiếc Thanh Kiếm Bị Nguyền Rủa!', 'Roll Over And Die: I Will Fight For An Ordinary Life With My Love And Cursed Sword!', 'https://phimimg.com/upload/vod/20260109-1/ab0e7f9ac648d4719aca92c601e26546.jpg', 'https://phimimg.com/upload/vod/20260109-1/799749af0679b757b39c936678c7e9cc.jpg', '<p>Flum không được chọn vì sức mạnh — bởi cô chẳng có chút sức mạnh nào. Không ma pháp, không kỹ năng, cô chỉ sở hữu một năng lực mang tên &#39;Nghịch Đảo&#39; mà ngay cả bản thân cô cũng không hề thấu hiểu. Vậy tại sao Chúa lại đặt cô vào nhóm của anh hùng? Sau khi bị phản bội và bị bán làm nô lệ, Flum bị hành hạ và cuối cùng bị ném cho lũ quái vật để làm trò tiêu khiển. Giờ đây, khi đối mặt với cái chết, Flum phải đưa ra lựa chọn: bị xé xác hoặc cầm lấy thanh ma kiếm bị nguyền rủa — thứ được truyền tụng là sẽ kết liễu chính người sử dụng nó.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 17, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ayaka Nanase","avatar":""},{"name":"Miku Ito","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["凭你也想讨伐魔王？","就凭你也想打败魔王吗","\"Omae Gotoki ga Maou ni Kateru to Omouna\" to Yuusha Party wo Tsuihou sareta node, Outo de Kimama ni Kurashitai","Omagoto","Omae Gotoki ga Maou ni Kateru to Omou na to Yuusha Party wo Tsuihou Sareta node Outo de Kimama ni Kurashitai","ROLL OVER AND DIE","ROLL OVER AND DIE: I Will Fight for an Ordinary Life With My Love and Cursed Sword!","NẰM XUỐNG VÀ CHẾT ĐI","「お前ごときが魔王に勝てると思うな」と勇者パーティを追放されたので、王都で気ままに暮らしたい"]', 1784690324127);
