INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-thu-le-hoa-nhat-khinh-chau', 'Nhất Thụ Lê Hoa, Nhất Khinh Châu', 'The Fatal Bloom', 'https://phimimg.com/upload/vod/20260327-1/aa7e86a38ae714ccc78bd9cfd66d3cdd.jpg', 'https://phimimg.com/upload/vod/20260327-1/fa7f278ce2a265a603615e56a6357900.jpg', '<p>Vào thời Dân quốc, Chu Lạc Lê – thiên kim của hãng xà phòng dược liệu nhà họ Chu – gả cho Đốc quân Tống Hoài Nam. Ngay trong ngày đại hỷ, cô phải chứng kiến cảnh cả gia tộc bị Tống Hoài Nam cấu kết với nhà họ Diêu sát hại dã man. May mắn sống sót sau thảm kịch, Chu Lạc Lê quyết định phẫu thuật thay đổi diện mạo, giả danh thành thiên kim nhà họ Diêu để tái giá với kẻ thù Tống Hoài Nam nhằm thực hiện kế hoạch báo thù.&nbsp; Cô tìm cách lôi kéo nhị thiếu gia nhà họ Tống là Tống Khinh Chu, giúp anh tìm lại người mẹ (Hồng dì) vốn bị Tống Hoài Nam bức hại, từ đó cả hai bắt tay liên minh. Họ lần lượt lật đổ nhà họ Diêu, sau đó trộm được bản hợp đồng bán nước của Tống Hoài Nam khiến hắn thân bại danh liệt và mất hết quyền lực. Tống Khinh Chu kế nhiệm chức Đốc quân. Sau khi cha của Tống Hoài Nam nói ra sự thật về quá khứ, hắn hối hận và tự kết liễu đời mình. Cuối cùng, Chu Lạc Lê vực dậy xưởng xà phòng nhà họ Chu, cùng Tống Khinh Chu kết thành quyến thuộc, cùng nhau bảo vệ Giang Thành.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 12, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Thang Mộng Giai","avatar":""},{"name":"Đại Cao Chính","avatar":""},{"name":"Trình Vũ Phong","avatar":""},{"name":"Lý Hoan","avatar":""},{"name":"Lâm Á Đông","avatar":""},{"name":"Lôi Tiếu Ngữ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yi Shu Li Hua Yi Qing Zhou","一树梨花一轻舟"]', 1784690324127);
