INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khai-giap-chan-truyen-yoroi-shin-den-samurai-troopers', 'Khải Giáp Chân Truyền (Yoroi Shin Den Samurai Troopers)', 'Yoroi-Shinden Samurai Troopers', 'khải giáp chân truyền (yoroi shin den samurai troopers) yoroi-shinden samurai troopers hiiro ishibashi junya enoki ayumu murase shunsuke takeuchi kentaro kumagai toshiki masuda lynn katsuyuki konishi takuya sato kohsuke toriumi takuma terashima tomokazu sugita kohei amasaki 铠真传 武士骑兵 魔神坛斗士 yoroi shin den samurai troopers yoroishinden samurai torūpā new armor legend samurai troopers 鎧真伝サムライトルーパー', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-an-nhuoc-mong', 'Lâm An Nhược Mộng', 'Reincarnated Love', 'https://phimimg.com/upload/vod/20260319-1/2ace71b7c718c424a315260decbed0ca.jpg', 'https://phimimg.com/upload/vod/20260319-1/ec82bbeb3ce932686ddf2cecc9403a34.jpg', '<p>Phim kể về Khương Nhược Ly, đích nữ của phủ Thừa tướng vốn có khả năng tiên tri. Cô nằm mơ thấy cha mẹ mình sẽ bị sát hại vào lễ Thượng Nguyên, nên đã tìm mọi cách để thay đổi vận mệnh nhưng lại vô tình bị cuốn vào một âm mưu thâm độc. Tại đây, cô gặp gỡ Hoắc Lâm Xuyên, thế tử của phủ Quốc công – người đang mang trong mình bí ẩn về mười kiếp luân hồi. Nhờ vào ký ức từ những kiếp trước, Hoắc Lâm Xuyên đã nhiều lần cứu mạng Khương Nhược Ly. Từ những đồng minh sát cánh bên nhau, cả hai dần nảy sinh tình cảm. Trải qua bao sóng gió từ quyền mưu gia tộc, những khúc mắc về thân thế và hiểu lầm, họ đã cùng nhau đối đầu với kẻ chủ mưu đứng sau tất cả. Vượt qua vòng lặp luân hồi, cuối cùng họ đã phá giải được lời nguyền và được ở bên nhau trọn đời.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 20, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Dịch Khâm","avatar":""},{"name":"Hồ Diệc Dao","avatar":""},{"name":"Bạch Xuyên","avatar":""},{"name":"Sử Nhuế Y","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["臨安若夢","Lin An Ruo Meng","임안약몽 : 윤회의 사랑","시공간 초월 로맨스 〈임안약몽〉","临安若梦"]', 1784690324127);
