INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-than-vo-dich', 'Diệp Thần Vô Địch', 'The Hidden Heir Ye Chen', 'https://phimimg.com/upload/vod/20260310-1/7520913037ed252f94561f4d4c26e150.jpg', 'https://phimimg.com/upload/vod/20260310-1/749a5d5ddf4bcc40b7773bca23fa85d4.jpg', '<p>Thân phận ẩn giấu của chàng rể hào môn hóa ra lại là đích tôn của người giàu nhất thế giới. Để bảo toàn tính mạng, anh phải mai danh ẩn tích, dùng thân phận con rể để càn quét giới thượng lưu và tìm kiếm kẻ chủ mưu đứng sau vụ sát hại cha mẹ mình. Trên hành trình đó, Diệp Thần vừa thu phục các &quot;đàn em&quot;, vừa kết giao với những &quot;hồng nhan tri kỷ&quot;, cuối cùng hé mở sự thật về cái chết của song thân. Thế nhưng, những &quot;cuộc khủng hoảng thân phận&quot; liên tiếp ập đến, Diệp Thần sẽ phải đối mặt ra sao?</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 11, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Nhậm Hào","avatar":""},{"name":"Lý Mộc Thần","avatar":""},{"name":"Lâm Tĩnh","avatar":""},{"name":"Triệu Nghị","avatar":""},{"name":"Hách Bình","avatar":""},{"name":"Lư Tinh Vũ","avatar":""},{"name":"Trương Hạo Luân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jin Ji De Ye Chen","上门龙婿","Wo Shi Ye Chen","进击的叶辰"]', 1784690324127);
