INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nui-va-bien-cua-toi', 'Núi Và Biển Của Tôi', 'My Destiny', 'https://phimimg.com/upload/vod/20260311-1/f4e23fa7f99f74691a720656c47fa504.jpg', 'https://phimimg.com/upload/vod/20260311-1/3a0ba6c2d1f9158fb44bc4a54fa9c378.jpg', '<p>Bộ phim kể về hành trình vươn lên của Phương Uyển Chi, một cô gái thuộc thế hệ 7X rời vùng núi Tây Nam đến Thâm Quyến lập nghiệp. Câu chuyện bắt đầu từ khi cô thoát khỏi những ràng buộc của gia đình gốc, trải qua nhiều thử thách nghiệt ngã của cuộc sống, rồi cuối cùng nắm bắt được cơ hội trong nhịp chuyển mình của thời đại để lột xác và trưởng thành. Từ đó phim phản chiếu sự cộng hưởng sâu sắc giữa số phận cá nhân và xã hội trong làn sóng cải cách mở cửa.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 17, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Đàm Tùng Vận","avatar":""},{"name":"Đổng Thanh","avatar":""},{"name":"Khê Vọng","avatar":""},{"name":"Cao Trí Đình","avatar":""},{"name":"Vương Kim Tông","avatar":""},{"name":"Lưu Uy","avatar":""},{"name":"Sư Vân Bân","avatar":""},{"name":"Triệu Chí Vĩ","avatar":""},{"name":"Trương Kiều Quốc","avatar":""},{"name":"Biện Thành","avatar":""},{"name":"Khúc Chấn Minh","avatar":""},{"name":"Nhậm Toàn","avatar":""},{"name":"Quách Bân","avatar":""},{"name":"Đới Thủy Bội","avatar":""},{"name":"Ngô Viện Viện","avatar":""},{"name":"Lộ Lâm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["我和我的命","Wo De Shan Yu Hai","我的山与海"]', 1784690324127);
