INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nui-va-bien-cua-toi', 'Núi Và Biển Của Tôi', 'My Destiny', 'núi và biển của tôi my destiny đàm tùng vận đổng thanh khê vọng cao trí đình vương kim tông lưu uy sư vân bân triệu chí vĩ trương kiều quốc biện thành khúc chấn minh nhậm toàn quách bân đới thủy bội ngô viện viện lộ lâm 我和我的命 wo de shan yu hai 我的山与海', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truc-ngoc', 'Trục Ngọc', 'Pursuit Of Jade', 'https://phimimg.com/upload/vod/20260307-1/81572d43eddf1dc784f3f53f6323f46d.jpg', 'https://phimimg.com/upload/vod/20260307-1/7e5b11b1d5ce3514f6d62787d164b816.jpg', '<p>Bộ phim kể về cô nàng bán thịt Phàn Trường Ngọc, người có cuộc gặp gỡ định mệnh với hầu gia lưu lạc Tạ Chinh trong một đêm tuyết rơi. Một người mồ côi cha mẹ, quyết tâm trở thành nữ chủ hộ còn một người cố gắng mai danh ẩn tích để trả &nbsp;mối huyết thù 17 năm. Hai người &quot;mỗi người một mục đích&quot; đã diễn một vở kịch hôn nhân giả nhưng lại chớm nở một tình yêu thật! Từ lợi dụng nhau đã biến thành yêu thương, nhưng tình yêu ấy lại mang đến cuộc chiến đẫm máu, khiến đôi trai gái phải chia lìa. Phàn Trường Ngọc cầm dao mổ lợn ra chiến trường tìm người thân, tìm chồng, tìm công lý. Tạ Chinh trở lại là vị thiết huyết hầu gia, bảo vệ đất nước, che chở người yêu và truy tìm sự thật! Cuối cùng họ cũng gặp lại nhau nơi chiến trường, sát cánh bên nhau không sợ sinh tử; vạch trần sự thật, không e dè quyền uy; trở về quê hương mà vẫn giữ trọn tấm lòng ban đầu!</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 23, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Lăng Hách","avatar":""},{"name":"Điền Hi Vi","avatar":""},{"name":"Nhậm Hào","avatar":""},{"name":"Khổng Tuyết Nhi","avatar":""},{"name":"Đặng Khải","avatar":""},{"name":"Lý Khanh","avatar":""},{"name":"Du Chung Lê","avatar":""},{"name":"Lưu Lâm","avatar":""},{"name":"Nghiêm Dịch Khoan","avatar":""},{"name":"Nhạc Dương","avatar":""},{"name":"Đỗ Thuần","avatar":""},{"name":"Đàm Khải","avatar":""},{"name":"Mao Lâm Lâm","avatar":""},{"name":"Diệp Tổ Tân","avatar":""},{"name":"Vu Dương","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Em Busca de Jade","Busca de Jade","Busca por Jade","Perseguição de Jade","Zhu Yu","축옥: 옥을 찾아서","옥을 찾아서","Chasing Jade","Pursuit of Jade","逐玉"]', 1784690324127);
