INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuy-trieu-tinh-yeu-phan-2', 'Thủy Triều Tình Yêu (Phần 2)', 'Tide Of Love (Season 2)', 'https://phimimg.com/upload/vod/20260206-1/5cd5415aa2775e52755f9aaca107e931.jpg', 'https://phimimg.com/upload/vod/20260206-1/f38225ffd928c85e486a044f88b6ad6e.jpg', '<p>Một người thừa kế giàu có và một sinh viên nghệ thuật bước vào một thỏa thuận mang tính giao dịch. Thế nhưng, mối quan hệ ấy dần dần nảy sinh tình cảm thật lòng, buộc cả hai phải đối mặt với những khao khát thực sự của bản thân.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 13, 2026, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Hyun-seo","avatar":""},{"name":"Jung Myeong-cheol","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["타이드오브러브 시즌2","漲潮時接吻第二季","Tide of Love S2","타이드 오브 러브"]', 1784690324127);
