INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuoi-tac-trong-tinh-yeu', 'Tuổi Tác Trong Tình Yêu', 'Age Of Attraction', 'https://phimimg.com/upload/vod/20260314-1/e4e46002c14d7da6cef7fecf992ad60c.jpg', 'https://phimimg.com/upload/vod/20260314-1/65ba756a239e223319d9ba30169edc9d.jpg', '<p>Khi những người độc thân đi tìm tri kỷ, tuổi tác không còn là rào cản. Liệu tình yêu có thực sự không phân biệt tuổi tác, hay những khoảng cách về năm tháng sẽ trở thành bức tường ngăn cách họ?</p>', 'Hoàn Tất (8/8)', 8, 'tvshows', 'completed', 19, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Natalie Joy Viall","avatar":""},{"name":"Nick Vail","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Age of Attraction"]', 1784690324127);
