INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tuoi-tac-trong-tinh-yeu', 'Tuổi Tác Trong Tình Yêu', 'Age Of Attraction', 'tuổi tác trong tình yêu age of attraction natalie joy viall nick vail age of attraction', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tim-moi-tinh-dau-qua-giong-noi', 'Tìm Mối Tình Đầu Qua Giọng Nói', 'Tune In To The Midnight Heart', 'https://phimimg.com/upload/vod/20260109-1/e24b0a82d83353483580b3c9fc7a280a.jpg', 'https://phimimg.com/upload/vod/20260109-1/e27f86a28a6b70f879fe191912acc649.jpg', '<p>Mỗi khi nằm một mình trong đêm, Arisu Yamabuki luôn tìm thấy sự an ủi từ giọng nói ấm áp của nữ phát thanh viên bí ẩn mang biệt danh “Apollo”. Thế nhưng, một ngày nọ cô đột ngột biến mất khỏi làn sóng radio mà không để lại bất kỳ lời giải thích nào. Nhiều năm sau, khi đã là học sinh lớp 11, Arisu quyết tâm tìm lại Apollo vì vẫn còn những điều chưa kịp nói. Dù không biết diện mạo hay tên thật của cô, cậu lần theo những manh mối dẫn mình đến Câu lạc bộ Phát thanh của trường. Tại đây, Arisu gặp bốn cô gái Rikka, Shinobu, Nene và Iko - những người sở hữu chất giọng giống hệt Apollo và cùng nuôi dưỡng ước mơ trở thành phát thanh viên, mở ra hành trình tìm kiếm giọng nói năm xưa với những rung động tuổi trẻ đầy cảm xúc.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 14, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Rikuya Yasuda","avatar":""},{"name":"Momoko Seto","avatar":""},{"name":"Rumi Okubo","avatar":""},{"name":"Sayumi Suzushiro","avatar":""},{"name":"Miku Ito","avatar":""},{"name":"Kana Hanazawa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["午夜心旋律","深夜的心之曲","Mayonaka Heart Tune","Finding the girl behind the voice.","午夜的傾心旋律","Tune In to the Midnight Heart","真夜中ハートチューン"]', 1784690324127);
