INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nem-huong-dao-mong', 'Nếm Hương Đào Mọng', 'Peach Lover', 'https://phimimg.com/upload/vod/20260121-1/0a3a4eab4ad7fe0269c6d0ef21f5e22c.jpg', 'https://phimimg.com/upload/vod/20260121-1/d3ce87b2bee8d982a3ef702484c34ecd.jpg', '<p>Một người hâm mộ cuồng nhiệt đã may mắn giành được cơ hội đóng chung với nữ diễn viên phim người lớn mà mình yêu thích nhất. Tuy nhiên, trong quá trình làm việc, mối quan hệ giữa họ đã vượt ra ngoài kịch bản và trở thành một tình yêu thực sự.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 19, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Niwat Naknuan","avatar":""},{"name":"Nuttapart Tuntistinchai","avatar":""},{"name":"Theerameth Pheerabawornsuk","avatar":""},{"name":"Praptpadol Suwanbang","avatar":""},{"name":"Asavarid Pinitkanjanapun","avatar":""},{"name":"Panurat Panyafu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["桃子恋人","Peach Lover The Series","ลูกพีชทานสด"]', 1784690324127);
