INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lanh-chua-vo-tu-vui-thu-bao-ve-lanh-dia-bien-ngoi-lang-vo-danh-thanh-phao-dai-manh-nhat-bang-ma-phap-he-san-xuat-', 'Lãnh Chúa Vô Tư Vui Thú Bảo Vệ Lãnh Địa ~ Biến ngôi làng vô danh thành pháo đài mạnh nhất bằng ma pháp hệ sản xuất ~', 'Easygoing Territory Defense By The Optimistic Lord', 'https://phimimg.com/upload/vod/20260109-1/e3862da81f12532d667ea9eb86d34f54.jpg', 'https://phimimg.com/upload/vod/20260109-1/d0722fbd37247c45336e0b7359877d1f.jpg', '<p>Được tái sinh thành con trai thứ tư của một gia đình Hầu tước, Van từng được ca ngợi là một thiên tài lỗi lạc — cho đến khi cậu bị trục xuất tới một ngôi làng biên giới vô danh vì sở hữu &#39;Ma pháp Sản xuất&#39;, một loại ma pháp bị coi là vô dụng trong thế giới này. Thế nhưng, khi Van sử dụng sức mạnh &#39;vô dụng&#39; đó để chế tạo vũ khí, công cụ và những điều kỳ diệu vượt xa trí tưởng tượng, ngôi làng bắt đầu chuyển mình mạnh mẽ! Những gì bắt đầu như một cuộc lưu đày giờ đây lại là khởi đầu cho một cuộc sống mới — và một chuyến phiêu lưu làm thay đổi cả thế giới!</p><p><br/></p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 13, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yumi Uchiyama","avatar":""},{"name":"Mao Ichimichi","avatar":""},{"name":"Mariya Ise","avatar":""},{"name":"Yoko Hikasa","avatar":""},{"name":"Shion Wakayama","avatar":""},{"name":"Kenyu Horiuchi","avatar":""},{"name":"Chikahiro Kobayashi","avatar":""},{"name":"Makoto Furukawa","avatar":""},{"name":"Wakana Kuramochi","avatar":""},{"name":"Gen Sato","avatar":""},{"name":"Nonoka Obuchi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["安闲领主的愉快领地防卫","Spaßige Gebietsverteidigung für lässige Lehnsherren","आशावादी स्वामी द्वारा सहज क्षेत्रीय रक्षा","Okiraku Ryoushu no Tanoshii Ryouchi Bouei: Seisankei Majutsu de Na mo Naki Mura wo Saikyou no Jousai Toshi ni","Okiraku Ryoushu no Tanoshii Ryouchi Bouei","Easygoing Territory Defense by the Optimistic Lord","Lãnh chúa vô tư vui thú bảo vệ lãnh địa","お気楽領主の楽しい領地防衛 ～生産系魔術で名もなき村を最強の城塞都市に～"]', 1784690324127);
