INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lanh-chua-vo-tu-vui-thu-bao-ve-lanh-dia-bien-ngoi-lang-vo-danh-thanh-phao-dai-manh-nhat-bang-ma-phap-he-san-xuat-', 'Lãnh Chúa Vô Tư Vui Thú Bảo Vệ Lãnh Địa ~ Biến ngôi làng vô danh thành pháo đài mạnh nhất bằng ma pháp hệ sản xuất ~', 'Easygoing Territory Defense By The Optimistic Lord', 'lãnh chúa vô tư vui thú bảo vệ lãnh địa ~ biến ngôi làng vô danh thành pháo đài mạnh nhất bằng ma pháp hệ sản xuất ~ easygoing territory defense by the optimistic lord yumi uchiyama mao ichimichi mariya ise yoko hikasa shion wakayama kenyu horiuchi chikahiro kobayashi makoto furukawa wakana kuramochi gen sato nonoka obuchi 安闲领主的愉快领地防卫 spaßige gebietsverteidigung für lässige lehnsherren आशावादी स्वामी द्वारा सहज क्षेत्रीय रक्षा okiraku ryoushu no tanoshii ryouchi bouei: seisankei majutsu de na mo naki mura wo saikyou no jousai toshi ni okiraku ryoushu no tanoshii ryouchi bouei easygoing territory defense by the optimistic lord lãnh chúa vô tư vui thú bảo vệ lãnh địa お気楽領主の楽しい領地防衛 ～生産系魔術で名もなき村を最強の城塞都市に～', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-con-cua-than-tuong-phan-3', 'Đứa Con Của Thần Tượng (Phần 3)', 'Oshi No Ko (Season 3)', 'https://phimimg.com/upload/vod/20260115-1/c8e4463ee795aba62dd54f41fae39697.jpg', 'https://phimimg.com/upload/vod/20260115-1/d430fcb28fcb9abc62e7178d0b188186.jpg', '<p>Nửa năm đã trôi qua kể từ khi “POP IN 2” được phát hành, câu chuyện Oshi No Ko bước sang một giai đoạn mới. Nhờ sự nỗ lực của Mem-cho, B-Komachi đang đứng trước một cơ hội lớn. Aqua tiếp tục trưởng thành về tính cách, Akane ngày càng tiến bộ trên con đường trở thành một diễn viên tài năng. Trái lại, Kana dần đánh mất sự vui vẻ vốn có của mình. Cuối cùng, trong hành trình tìm ra sự thật đằng sau cái chết của Ai và Gorou, Ruby vươn lên trong ngành giải trí, sử dụng những lời nói dối như một vũ khí.</p>', 'Tập 11', 12, 'hoathinh', 'ongoing', 12, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Takeo Otsuka","avatar":""},{"name":"Yurie Igoma","avatar":""},{"name":"Megumi Han","avatar":""},{"name":"Rumi Okubo","avatar":""},{"name":"Manaka Iwami","avatar":""},{"name":"Kent Ito","avatar":""},{"name":"Yumi Uchiyama","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["【我推的孩子】","我推的孩子","Mein Star","Oshi No Ko: Mein Star","Oshi No Ko - Mein*Star","【OSHI Nの KO】","\"Oshi no Ko\"","Oshi no Ko","최애의 아이","Moja gwiazda","Ребёнок айдола","เกิดใหม่เป็นลูกโอชิ","My Favorite Idol''s Children","Oshi No Ko","【推しの子】"]', 1784690324127);
