INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dua-con-cua-than-tuong-phan-3', 'Đứa Con Của Thần Tượng (Phần 3)', 'Oshi No Ko (Season 3)', 'đứa con của thần tượng (phần 3) oshi no ko (season 3) takeo otsuka yurie igoma megumi han rumi okubo manaka iwami kent ito yumi uchiyama 【我推的孩子】 我推的孩子 mein star oshi no ko: mein star oshi no ko - mein*star 【oshi nの ko】 "oshi no ko" oshi no ko 최애의 아이 moja gwiazda ребёнок айдола เกิดใหม่เป็นลูกโอชิ my favorite idol''s children oshi no ko 【推しの子】', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuyen-thu-de-mui-vi-chien-thang', 'Tuyển Thủ Dê: "Mùi" Vị Chiến Thắng', 'GOAT', 'https://phimimg.com/upload/vod/20260325-1/57000b826e67c1db2727e310aec0b004.jpg', 'https://phimimg.com/upload/vod/20260325-1/1f5f942c1627deb2064d8be37d172855.jpg', '<p>Will là một chú dê nhỏ với những ước mơ lớn, người có được cơ hội duy nhất trong đời để gia nhập các vận động viên chuyên nghiệp và thi đấu môn rugebol — một môn thể thao cường độ cao, pha trộn và đối kháng toàn diện, nơi các loài động vật nhanh nhất và hung dữ nhất thế giới thống trị. Những đồng đội mới của Will không mấy hào hứng khi có một chú dê nhỏ trong đội hình, nhưng Will quyết tâm tạo nên một cuộc cách mạng cho môn thể thao này và chứng minh một lần và mãi mãi rằng: “Nhỏ bé cũng biết chơi!”</p>', 'Full', 1, 'hoathinh', 'completed', 27, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Caleb McLaughlin","avatar":""},{"name":"Gabrielle Union","avatar":""},{"name":"Stephen Curry","avatar":""},{"name":"Aaron Pierre","avatar":""},{"name":"Nicola Coughlan","avatar":""},{"name":"David Harbour","avatar":""},{"name":"Nick Kroll","avatar":""},{"name":"Jenifer Lewis","avatar":""},{"name":"Patton Oswalt","avatar":""},{"name":"Jelly Roll","avatar":""},{"name":"Jennifer Hudson","avatar":""},{"name":"Sherry Cola","avatar":""},{"name":"Eduardo Franco","avatar":""},{"name":"Andrew Santino","avatar":""},{"name":"Bobby Lee","avatar":""},{"name":"Wayne Knight","avatar":""},{"name":"Ayesha Curry","avatar":""},{"name":"Van","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["GOAT: Мечтай по крупному","고트","山羊","ゴート","CAPRA","CABRA","VUOHI","GOAT: Labākais pasaulē","GOAT: Visų laikų geriausias","Keçi","คุณแพะหัวใจไม่ยอมแพ้","الماعز","G.O.A.T. - Bock auf große Sprünge","GOAT","G.O.A.T Bock auf grosse Spruenge"]', 1784690324127);
