INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuu-2026', 'Cứu', 'Send Help', 'https://phimimg.com/upload/vod/20260325-1/27d72029d90f0c2560523fd8ab08a30e.jpg', 'https://phimimg.com/upload/vod/20260325-1/8b58708f9dc3aeb6db816ff4067a9019.jpg', '<p>Hai đồng nghiệp trở thành những người sống sót duy nhất sau một vụ rơi máy bay và bị mắc kẹt trên một hòn đảo hoang. Tại đây, họ buộc phải gạt bỏ những mâu thuẫn trong quá khứ để hợp tác sinh tồn. Nhưng càng kéo dài, cuộc chiến không chỉ còn là chống chọi với thiên nhiên khắc nghiệt — mà trở thành màn đấu trí và đấu ý chí, nơi chỉ những người đủ tỉnh táo và quyết liệt mới có cơ hội thoát ra sống sót.</p>', 'Full', 1, 'single', 'completed', 23, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Rachel McAdams","avatar":""},{"name":"Dylan O''Brien","avatar":""},{"name":"Edyll Ismail","avatar":""},{"name":"Dennis Haysbert","avatar":""},{"name":"Xavier Samuel","avatar":""},{"name":"Chris Pang","avatar":""},{"name":"Thaneth Warakulnukroh","avatar":""},{"name":"Emma Raimi","avatar":""},{"name":"Kristy Best","avatar":""},{"name":"Francesca Waters","avatar":""},{"name":"Olivia Sawyer","avatar":""},{"name":"Brad Flett","avatar":""},{"name":"Nana Miya","avatar":""},{"name":"Anuwat Pornladawong","avatar":""},{"name":"Benjawan Teawsomboonkit","avatar":""},{"name":"Aaron Shore","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Kömək Göndərin","HELP/Fukushu Jima","SOS!","샌드 헬프","โปรดส่งใครมาช่วยฉันที","Пришлите помощь","SOS","Send Help (Enviad ayuda)","冤家路绝","Send Help"]', 1784690324127);
