INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-dai-va-manh-liet', 'Hoang Dại Và Mãnh Liệt', 'Wild & Fiery', 'https://phimimg.com/upload/vod/20260317-1/d8325ebc1bab6d0191933c52e4017177.jpg', 'https://phimimg.com/upload/vod/20260317-1/68c595bd0c2fae3fd2c8d939e8fbcf00.jpg', '<p>20 năm trước, một kế hoạch tráo đổi con đã khiến người thừa kế thực sự của nhà họ Mục là Thẩm Ký Bạch phải lưu lạc, sống cuộc đời nghèo khó và đầy rẫy hiểm nguy. Trong khi đó, tiểu thư giả Mục Tri Du thì trở thành một chuyên gia đấu giá hàng đầu. Cô quyết định về nước với mục tiêu giành lại sàn đấu giá từ tay mẹ kế Hứa Minh Châu. Bà mẹ kế thâm độc đã lợi dụng Thẩm Ký Bạch để tiếp cận Mục Tri Du. Giữa vòng xoáy quyền lực và mưu kế chốn hào môn, hai người từ chỗ đối đầu đã dần quyết định bắt tay nhau báo thù rửa hận...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 12, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Nhậm Vận Kiệt","avatar":""},{"name":"Bành Nhã Kỳ","avatar":""},{"name":"Trương Sa Sa","avatar":""},{"name":"Ngô Hạo Phong","avatar":""},{"name":"Vương Tuyết Viên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["You Ye You Lie","契約有刺","契约有刺","Qi Yue You Ci","Сложный контракт","The Contract Has Thorns","Wild and Fiery","又野又烈"]', 1784690324127);
