INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuoi-tre-sherlock-holmes-phan-1', 'Tuổi Trẻ Sherlock Holmes (Phần 1)', 'Young Sherlock (Season 1)', 'https://phimimg.com/upload/vod/20260314-1/108529d5a57ebd5816411afb54a177c9.jpg', 'https://phimimg.com/upload/vod/20260314-1/c95848ec79a5634921f458c745b56a2e.jpg', '<p>Lấy bối cảnh nước Anh những năm 1870 tại Đại học Oxford, phim xoay quanh Sherlock Holmes khi mới 19 tuổi – một chàng trai bốc đồng, chưa được mài giũa và thường xuyên gặp rắc rối. Khi vô tình vướng vào một vụ án giết người đe dọa đến sự tự do của bản thân, Sherlock bắt đầu dấn thân vào cuộc điều tra đầu tiên, từ đó khám phá ra một âm mưu toàn cầu nguy hiểm. Trong hành trình này, anh gặp gỡ James Moriarty và bắt đầu quá trình phát triển các kỹ năng thám tử huyền thoại của mình trước khi trở thành biểu tượng tại Baker Street.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 18, 2026, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Hero Fiennes Tiffin","avatar":""},{"name":"Dónal Finn","avatar":""},{"name":"Zine Tseng","avatar":""},{"name":"Joseph Fiennes","avatar":""},{"name":"Natascha McElhone","avatar":""},{"name":"Max Irons","avatar":""},{"name":"Colin Firth","avatar":""},{"name":"Holly Cattle","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jovem Sherlock","Young Sherlock: กำเนิดนักสืบ เชอร์ล็อก โฮล์มส์","Yosh Sherlok","Young Sherlock"]', 1784690324127);
