INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hay-rua-sach-tat-ca-kirei-ni-shitemoraemasu-ka', 'Hãy Rửa Sạch Tất Cả (Kirei ni Shitemoraemasu ka.)', 'Wash It All Away', 'https://phimimg.com/upload/vod/20260114-1/d01eacb557d5e0b2611b936c16c4986f.jpg', 'https://phimimg.com/upload/vod/20260114-1/3ae5b297207ac295fbf7ebe046d1cafe.jpg', '<p>Trong suốt hai năm qua, cô gái vui vẻ và chăm chỉ Kinme Wakana đã điều hành một tiệm giặt ủi nhỏ tại thị trấn suối nước nóng ven biển Atami. Giữa những ngày tháng bình lặng trôi qua, Wakana nhận ra mình bị cuốn vào những câu chuyện vừa ngọt ngào vừa cay đắng, nhưng cũng đầy ấm áp của những con người xung quanh cô.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Sayumi Suzushiro","avatar":""},{"name":"Shuichiro Umeda","avatar":""},{"name":"Konomi Inagaki","avatar":""},{"name":"Yoshino Aoyama","avatar":""},{"name":"Kento Shiraishi","avatar":""},{"name":"Ami Koshimizu","avatar":""},{"name":"Wasabi Mizuta","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["可以帮忙洗干净吗？","大姐姐的绮丽日常","Kirei ni Shitemoraemasu ka.","Kirei ni Shite Moraemasu ka.","きにして","Kinishite","Will You Clean This for Me?","綺麗にしてもらえますか。"]', 1784690324127);
