INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hay-rua-sach-tat-ca-kirei-ni-shitemoraemasu-ka', 'Hãy Rửa Sạch Tất Cả (Kirei ni Shitemoraemasu ka.)', 'Wash It All Away', 'hãy rửa sạch tất cả (kirei ni shitemoraemasu ka.) wash it all away sayumi suzushiro shuichiro umeda konomi inagaki yoshino aoyama kento shiraishi ami koshimizu wasabi mizuta 可以帮忙洗干净吗？ 大姐姐的绮丽日常 kirei ni shitemoraemasu ka. kirei ni shite moraemasu ka. きにして kinishite will you clean this for me? 綺麗にしてもらえますか。', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-kiem-ky-dam-phan-tich-thien-kiep', 'Cổ Kiếm Kỳ Đàm: Phần Tịch Thiên Kiếp', 'Swords Of Legends: Doomsday (The Legend Of The Ancient Sword: Fire Tribulation)', 'https://phimimg.com/upload/vod/20260323-1/1f03f92ec71d1b1bb8e20040bdf3d686.jpg', 'https://phimimg.com/upload/vod/20260323-1/14964af72ee6667ccbbbc1c924f93bd6.jpg', '<p>Ba trăm năm sau đại chiến Bồng Lai, Bách Lý Đồ Tô cuối cùng được Phong Thanh Tuyết hồi sinh. Âu Dương Thiếu Cung cũng được Tốn Phương giải cứu. Xi Vưu khống chế Thiếu Cung gây họa cho dân chúng, mọi người hợp lực chống lại nhưng bất thành. Đồ Tô được Nữ Oa chỉ điểm, đem Kiếm Phách trao cho Thiếu Cung. Cuối cùng, hai người hợp hai làm một, có được tiên lực hoàn chỉnh, đánh bại Xi Vưu, cứu rỗi tam giới. Nhưng Phong Tình Tuyết linh lực cạn kiệt, lâm vào hôn mê. Đồ Tô thề nhất định sẽ cứu người con gái anh yêu tỉnh lại.</p>', 'Full', 1, 'single', 'completed', 18, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Bạch Thụ","avatar":""},{"name":"Lương Tịnh Nhàn","avatar":""},{"name":"Khương Chấn Hạo","avatar":""},{"name":"Hoàng Nghệ","avatar":""},{"name":"Vương Tĩnh Hâm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["古剑奇谭之焚寂天劫"]', 1784690324128);
