INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luan-hoi-cao-quy-kizoku-tensei-megumareta-umare-kara-saikyou-no-chikara-wo-eru', 'Luân Hồi Cao Quý (Kizoku Tensei: Megumareta Umare kara Saikyou no Chikara wo Eru)', 'Noble Reincarnation: Born Blessed, So I''ll Obtain Ultimate Power', 'https://phimimg.com/upload/vod/20260109-1/1338e3eba9fe12cdcd0ddb509889cb89.jpg', 'https://phimimg.com/upload/vod/20260109-1/f92d4bbcfb32c34b339a5426825e029a.jpg', '<p>Kiếp trước của Noa chỉ là một thanh niên dân làng bình thường, chẳng có gì đáng để nhắc tới. Thế nhưng giờ đây, cậu đã được tái sinh thành Nhị thập tam Hoàng tử (Hoàng tử thứ 13) của một đế quốc hùng mạnh! Bảng thông số hiển thị một khả năng đặc biệt: sức mạnh của Noa sẽ tăng tiến tỷ lệ thuận với số lượng người phục tùng dưới trướng cậu. Để đạt được sức mạnh tối thượng, Noa sẵn sàng làm bất cứ điều gì cần thiết để đảm bảo rằng những kẻ đã phụng sự cậu sẽ phải trung thành suốt đời!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Karin Nanami","avatar":""},{"name":"Saki Miyashita","avatar":""},{"name":"Iori Saeki","avatar":""},{"name":"Yui Ishikawa","avatar":""},{"name":"Misaki Watada","avatar":""},{"name":"Azusa Tachibana","avatar":""},{"name":"Shin-ichiro Miki","avatar":""},{"name":"Koji Yusa","avatar":""},{"name":"Kengo Kawanishi","avatar":""},{"name":"Nana Mizuki","avatar":""},{"name":"Tetsuo Komura","avatar":""},{"name":"Kazuhiko Inoue","avatar":""},{"name":"Daisuke Ono","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Kizoku Tensei: Megumareta Umare kara Saikyou no Chikara wo Eru","Aristocratic Reincarnation: Getting the Strongest Power From Blessed Birth","Noble Reincarnation: Born Blessed, So I''ll Obtain Ultimate Power","Noble Reincarnation Born Blessed So Ill Obtain Ultimate Power","Noble Reincarnation: Born Blessed","貴族転生 ～恵まれた生まれから最強の力を得る～"]', 1784690324128);
