INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('luan-hoi-cao-quy-kizoku-tensei-megumareta-umare-kara-saikyou-no-chikara-wo-eru', 'Luân Hồi Cao Quý (Kizoku Tensei: Megumareta Umare kara Saikyou no Chikara wo Eru)', 'Noble Reincarnation: Born Blessed, So I''ll Obtain Ultimate Power', 'luân hồi cao quý (kizoku tensei: megumareta umare kara saikyou no chikara wo eru) noble reincarnation: born blessed, so i''ll obtain ultimate power karin nanami saki miyashita iori saeki yui ishikawa misaki watada azusa tachibana shin-ichiro miki koji yusa kengo kawanishi nana mizuki tetsuo komura kazuhiko inoue daisuke ono kizoku tensei: megumareta umare kara saikyou no chikara wo eru aristocratic reincarnation: getting the strongest power from blessed birth noble reincarnation: born blessed, so i''ll obtain ultimate power noble reincarnation born blessed so ill obtain ultimate power noble reincarnation: born blessed 貴族転生 ～恵まれた生まれから最強の力を得る～', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-thuong-ngay-cua-nhan-vien-tra-tan-ban-thoi-gian', 'Cuộc Sống Thường Ngày Của Nhân Viên Tra Tấn Bán Thời Gian (Đã Đến Lúc Tra Tấn Công Chúa)', 'The Daily Life Of A Part-time Torturer, The Everyday Life of Part-Time Torture Workers', 'https://phimimg.com/upload/vod/20260105-1/a1531b6fb0a1f1f6d47c904033dfed79.jpg', 'https://phimimg.com/upload/vod/20260105-1/c3b0a98f729e5533efdd9c0e20bcd7e9.jpg', '<p>Trong một xã hội nơi tra tấn là hợp pháp — và thậm chí là một ngành kinh doanh béo bở — tập đoàn Spirytus đang thống trị thị trường bằng kỹ năng điêu luyện, phong cách lịch lãm và một tinh thần làm việc nhóm vui vẻ đến bất ngờ. Bộ tứ nhân viên bán thời gian gồm Cero, Shiu, Mikke và Hugh cùng nhau xử lý những &#39;ca làm việc&#39; với khách hàng, những trò quậy phá nơi công sở, và thậm chí là đối đầu với cả những sát thủ nội gián... tất cả đều được thực hiện với một nụ cười nở trên môi! Cuộc sống tại Spirytus chứng minh rằng ngay cả trong một thế giới đầy rẫy sự đau đớn, công việc vẫn có thể thú vị một cách khó tin!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 12, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shunichi Toki","avatar":""},{"name":"Takuma Terashima","avatar":""},{"name":"Takuma Nagatsuka","avatar":""},{"name":"Yohei Azakami","avatar":""},{"name":"Kisho Taniyama","avatar":""},{"name":"Rikuya Yasuda","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Gomon Baito-kun no Nichijo","Goumon Baito-kun no Nichijou","The Everyday Life of Part-Time Torture Workers","The Daily Life of a Part-Time Torturer","拷問バイトくんの日常"]', 1784690324128);
