INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-bien', 'Quái Vật Biển', 'Kraken', 'https://phimimg.com/upload/vod/20260312-1/8a9099f79c783115a7e4dc4b32d72189.jpg', 'https://phimimg.com/upload/vod/20260312-1/699b844e5899165ab432691b0831c1ef.jpg', '<p>Bối cảnh đặt vào thời Chiến tranh Lạnh, một tàu ngầm tên lửa Nga biến mất bí ẩn trên Biển Greenland. Đại úy Viktor Voronin (Alexander Petrov) — người em của chỉ huy tàu mất tích — dẫn đầu chiến dịch cứu hộ. Trong khi đó, một căn cứ địa chất ở Bắc Cực vô tình đánh thức con Kraken—một quái vật biển sâu khổng lồ với khả năng ngụy trang siêu việt và trí thông minh đáng sợ. Khi nhóm cứu hộ tiếp cận khu vực tàu ngầm mất tích, họ cũng phải đối mặt với sinh vật huyền thoại đang nổi lên từ đáy đại dương</p>', 'Full', 1, 'single', 'completed', 28, 2026, 'Vietsub', 'FHD', 'Na Uy', 0, '[{"name":"Sara Khorami","avatar":""},{"name":"Mikkel Bratt Silset","avatar":""},{"name":"Ingvild Holthe Bygdnes","avatar":""},{"name":"Øyvind Brandtzæg","avatar":""},{"name":"Jenny Evensen","avatar":""},{"name":"Steinar Klouman Hallert","avatar":""},{"name":"Filip Bargee Ramberg","avatar":""},{"name":"Jon Erik Myre","avatar":""},{"name":"Hans Morten Hansen","avatar":""},{"name":"Magnús Blöndal Jóhannsson","avatar":""},{"name":"Jon Kennedy Dushime Niyokindi","avatar":""},{"name":"Silje Breivik","avatar":""},{"name":"Anderz E","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Kraken (by Pål Øie)","Kraken"]', 1784690324128);
