INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('naari-naari-naduma-murari', 'Naari Naari Naduma Murari', 'Naari Naari Naduma Murari', 'https://phimimg.com/upload/vod/20260312-1/6a9679ea6fd9548ba4473a628409d0f2.jpg', 'https://phimimg.com/upload/vod/20260312-1/0e4f7a225b6acd5e5dc77daf3b79e982.jpg', '<p>Mắc kẹt giữa hai người phụ nữ, một chàng trai trẻ phải đối mặt với mối tình tay ba phức tạp, đồng thời xử lý những cảm xúc và những lựa chọn thay đổi cuộc đời ảnh hưởng đến cả mối quan hệ tình cảm và gia đình của mình.</p>', 'Full', 1, 'single', 'completed', 15, 2026, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Sharwanand","avatar":""},{"name":"Sakshi Vaidya","avatar":""},{"name":"Samyuktha","avatar":""},{"name":"Sree Vishnu","avatar":""},{"name":"Vennela Kishore","avatar":""},{"name":"Naresh","avatar":""},{"name":"Satya","avatar":""},{"name":"Sampath Raj","avatar":""},{"name":"Nellore Sudharshan","avatar":""},{"name":"Sivannarayana Naripeddi","avatar":""},{"name":"Raghu Babu","avatar":""},{"name":"Getup Srinu","avatar":""},{"name":"Srikanth Iyengar","avatar":""},{"name":"Sirisha Hanumanth","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Naari Naari Naduma Murari","NNNM","నారీ నారీ నడుమ మురారి"]', 1784690324128);
