INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-khong-con-yeu-nua', 'Tôi Không Còn Yêu Nữa', 'I Don''t Love You Anymore', 'https://phimimg.com/upload/vod/20260312-1/5f4993b9719cf92f0aa82e8c509f5cc2.jpg', 'https://phimimg.com/upload/vod/20260312-1/1113a640bf8f0ae2e922069284af47fd.jpg', '<p>Một người đàn ông được tìm thấy nổi bất động trong bể bơi của một cặp vợ chồng ở ngoại ô, và mọi chi tiết trong câu chuyện đều không khớp nhau. Trong các cuộc thẩm vấn riêng biệt của cảnh sát, lời khai mâu thuẫn của họ trở nên rối rắm và đứt đoạn, hé lộ một mạng lưới dối trá, dục vọng bị chôn vùi và những sự thật bị chối bỏ từ lâu giống như trong phim Rashomon. Khi đêm xảy ra vụ xả súng được tái hiện từ nhiều góc nhìn khác nhau, một câu chuyện về tình yêu, lòng trung thành và sự phản bội dần dần được hé lộ — đen tối và đáng sợ hơn bất cứ ai muốn thừa nhận.</p>', 'Full', 1, 'single', 'completed', 13, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Marcus Henderson","avatar":""},{"name":"Hope Lauren","avatar":""},{"name":"Henri Esteve","avatar":""},{"name":"Paul McCrane","avatar":""},{"name":"Dionne Lea","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["I Don''t Love You Anymore"]', 1784690324128);
