INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-tim-cua-tuong-lai', 'Trái Tim Của Tương Lai', 'Heart of the Future', 'null', 'https://phimimg.com/upload/vod/20260312-1/2efe5fd23bee5844600a05dab8cdba2f.jpg', '<p>Hai nhà phát minh Yu Shu và Liang Lan tạo ra &quot;Siêu vỏ não&quot; (The Hyper-Cortex), một trí tuệ nhân tạo đột phá có khả năng tái tạo các hệ sinh thái đã tuyệt chủng. Nhưng khi con trai họ lâm bệnh nặng, trong tuyệt vọng, Liang Lan hợp tác với nhà đầu tư bí ẩn, ông He, để xây dựng &quot;Công viên Mecha-Eden&quot; đầy lợi nhuận, trong khi Yu Shu, một người theo chủ nghĩa thuần túy, bỏ trốn cùng con trai, tin rằng tạo vật của họ quá thiêng liêng để bị đem ra trưng bày. Nhiều năm sau, khi thời gian của con trai họ sắp hết, Yu Shu trở về, giao nộp mảnh ghép cuối cùng của câu đố. Mã nguồn bị đánh cắp, bị biến chất, và những sinh vật hùng vĩ trong thần thoại trở thành cỗ máy hủy diệt. Trong hỗn loạn, một gia đình tan vỡ phải tìm cách đoàn tụ trước khi con quái vật khổng lồ, tạo vật của họ, nuốt chửng thế giới...</p>', 'Full', 1, 'single', 'completed', 11, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["未来之心"]', 1784690324128);
