INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-tren-manh-dat-ma-am', 'Ngôi nhà trên mảnh đất ma ám', 'The House on Haunted Grounds', 'https://phimimg.com/upload/vod/20260312-1/f5c3f8e7623ffd7b1908c4565ee2040c.jpg', 'https://phimimg.com/upload/vod/20260312-1/36f78b2ecef2abc75db549a12fc4629d.jpg', '<p>Họ bước vào một ngôi nhà ma ám với lịch sử bị ma nhập và giết người. Các nạn nhân không bao giờ trở ra, nhưng đoạn phim thì có.</p>', 'Full', 1, 'single', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Logan Wallace","avatar":""},{"name":"Andrew Thomas","avatar":""},{"name":"Stuart Maxheimer","avatar":""},{"name":"Cashmere Moniqué","avatar":""},{"name":"Dylan DeVane","avatar":""},{"name":"Brent Downs","avatar":""},{"name":"Austin J. Rhodes","avatar":""},{"name":"Kellan Rudnicki","avatar":""},{"name":"Shaelyn Clark","avatar":""},{"name":"Emily Thorton","avatar":""},{"name":"Kristi Tavolacci","avatar":""},{"name":"Jordan Patterson","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["The House on Haunted Grounds"]', 1784690324128);
