INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngoi-nha-tren-manh-dat-ma-am', 'Ngôi nhà trên mảnh đất ma ám', 'The House on Haunted Grounds', 'ngôi nhà trên mảnh đất ma ám the house on haunted grounds logan wallace andrew thomas stuart maxheimer cashmere moniqué dylan devane brent downs austin j. rhodes kellan rudnicki shaelyn clark emily thorton kristi tavolacci jordan patterson the house on haunted grounds', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-em-nhe', 'Yêu Em Nhé', 'Love Me Love Me', 'https://phimimg.com/upload/vod/20260312-1/9c708b0689fba3feffab7dfe1cbbd2a8.jpg', 'https://phimimg.com/upload/vod/20260312-1/206868e4751711ca1a0673dcada63d5d.jpg', '<p>Sau khi mất anh trai trong một tai nạn, June (Mia Jenkins) quyết định rời quê nhà để bắt đầu lại ở Milan – thành phố của ánh đèn, thời trang và những cảm xúc mới. Trong ngôi trường quốc tế nơi mọi thứ đều xa lạ, cô gặp Will (Pepe Barroso) – chàng học sinh gương mẫu, điềm đạm và có vẻ như nắm giữ mọi câu trả lời mà cô đang tìm kiếm. Nhưng rồi James (Luca Melucci) xuất hiện – người bạn thân của Will, cũng là kẻ mang trong mình bóng tối của những trận đấu MMA bí mật và quá khứ không mấy yên bình. &nbsp;Giữa Will an toàn và James nguy hiểm, June dần bị cuốn vào một vòng xoáy cảm xúc mà chính cô cũng không ngờ tới. Tình yêu, nỗi sợ và sự mất mát hòa trộn, khiến mọi ranh giới giữa đúng – sai, an toàn – đam mê trở nên mờ nhạt. Tại Milan, nơi mỗi góc phố đều ẩn chứa một câu chuyện, June phải tự tìm ra đâu mới là điều trái tim mình thật sự khao khát.</p>', 'Full', 1, 'single', 'completed', 15, 2026, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Pepe Barroso","avatar":""},{"name":"Mia Jenkins","avatar":""},{"name":"Luca Melucci","avatar":""},{"name":"Andrea Guo","avatar":""},{"name":"Michelangelo Vizzini","avatar":""},{"name":"Madior Fall","avatar":""},{"name":"Elizabeth Kinnear","avatar":""},{"name":"Tommaso Caporali","avatar":""},{"name":"Bruno Cabrerizo","avatar":""},{"name":"Ángel de Miguel","avatar":""},{"name":"Alessio Di Chirico","avatar":""},{"name":"Edoardo De Marte","avatar":""},{"name":"Vanessa Donghi","avatar":""},{"name":"Jim Bannister","avatar":""},{"name":"Marco Patrassi","avatar":""},{"name":"Riccardo Ri","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Love Me Love Me: Corações Magnéticos","爱我，爱我：心动磁场","Love Me, Love Me","Love Me Love Me"]', 1784690324128);
