INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-ong-bo', 'Mật ong bó', 'Honey Bunch', 'https://phimimg.com/upload/vod/20260312-1/c06ce94c29044353217978a4cbd4f6ac.jpg', 'https://phimimg.com/upload/vod/20260312-1/d3e2cbab4b4fb04c1c232f2e204e5681.jpg', '<p>Chồng của Diana đưa cô đến một cơ sở điều trị chấn thương thử nghiệm sâu trong vùng hoang dã, nhưng cô không nhớ lý do tại sao... Khi ký ức dần trở lại, cô cũng phát hiện ra một số sự thật đáng sợ về cuộc hôn nhân của mình.</p>', 'Full', 1, 'single', 'completed', 17, 2026, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Grace Glowicki","avatar":""},{"name":"Ben Petrie","avatar":""},{"name":"Jason Isaacs","avatar":""},{"name":"Kate Dickie","avatar":""},{"name":"Julian Richings","avatar":""},{"name":"Jesse LaVercombe","avatar":""},{"name":"Sarah Kolasky","avatar":""},{"name":"India Brown","avatar":""},{"name":"Ahmed Moneka","avatar":""},{"name":"Cynthia Ashperger","avatar":""},{"name":"Patricia Tulasne","avatar":""},{"name":"Lina Roessler","avatar":""},{"name":"Kyisha Williams","avatar":""},{"name":"Jimi Shlag","avatar":""},{"name":"Mark MacDonald","avatar":""},{"name":"Mickey MacDonald","avatar":""},{"name":"Annick C","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Honey Bunch"]', 1784690324128);
