INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bon-nguoi', 'Bốn Người', 'The Fairfield County Four', 'https://phimimg.com/upload/vod/20260312-1/cb3e634219664116ce1ee48022ed3b57.jpg', 'https://phimimg.com/upload/vod/20260312-1/f09687d9bfa67d5c823a02a14f2bc98e.jpg', '<p>Bốn thanh niên mất tích khi đang điều tra những báo cáo về một sinh vật to lớn, giống chó sói. Mặc dù không tìm thấy dấu vết nào của bốn người, nhưng chiếc máy quay phim của họ cuối cùng đã được tìm thấy. Đây có lẽ là đoạn phim cuối cùng được biết đến về nhóm &quot;Bốn người ở hạt Fairfield&quot;.</p>', 'Full', 1, 'single', 'completed', 7, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Noah J. Welter","avatar":""},{"name":"Erica Fett","avatar":""},{"name":"Celeste Blandon","avatar":""},{"name":"Jake Kopronica","avatar":""},{"name":"John Bloom","avatar":""},{"name":"Otis B. Dreds","avatar":""},{"name":"Cory Cowley","avatar":""},{"name":"Tommy Bechtold","avatar":""},{"name":"Chelsea LeSage","avatar":""},{"name":"Connor Flynn","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["The Fairfield County Four"]', 1784690324128);
