INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vi-con-gai-toi-co-the-danh-bai-ca-ma-vuong', 'Vì Con Gái, Tôi Có Thể Đánh Bại Cả Ma Vương', 'The Demon King''s Daughter Is Too Kind!!', 'https://phimimg.com/upload/vod/20260109-1/e404c164149e0e479cffb11ec0467c14.jpg', 'https://phimimg.com/upload/vod/20260109-1/88ada5b2e2b1a5b6b33fb09218b5c398.jpg', '<p><span class="">&quot;Từng là kẻ thống trị đáng sợ của muôn loài quỷ,</span><span class=""> Quỷ Vương Ahriman luôn nung nấu ý định chinh phục thế giới… cho đến khi ông bị ngăn cản bởi một thế lực không ngờ tới:</span><span class=""> chính là cô con gái Dou của mình!</span><span class=""> Vì quá tốt bụng để gây ra sự hỗn loạn và quá dịu dàng để khơi mào chiến tranh,</span><span class=""> Dou đã làm tan chảy trái tim của quỷ dữ,</span><span class=""> loài người và thậm chí là cả các thiên thần.</span><span class=""> Tuyệt vọng trong việc khôi phục lòng kiêu hãnh của tộc quỷ,</span><span class=""> cận thần Jahi của Ahriman đã thề sẽ huấn luyện Dou trở thành một ác quỷ thực thụ.</span><span class=""> Thế nhưng,</span><span class=""> liệu Jahi có thể chống lại được sự bao dung và lòng trắc ẩn của Dou?!</span><span class=""></span></p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Misaki Kuno","avatar":""},{"name":"Ayaka Ohashi","avatar":""},{"name":"Akio Otsuka","avatar":""},{"name":"Shigeru Chiba","avatar":""},{"name":"Ayasa Ito","avatar":""},{"name":"Kaori Ishihara","avatar":""},{"name":"Yuko Sanpei","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"na