INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('kiem-com-bang-tro-choi-sinh-tu', 'Kiếm Cơm Bằng Trò Chơi Sinh Tử', 'SHIBOYUGI: Playing Death Games To Put Food On The Table', 'kiếm cơm bằng trò chơi sinh tử shiboyugi: playing death games to put food on the table chiyuki miura inori minase rena motomura haruka sato mutsumi tamura rina kawaguchi shiboyugi: jogos mortais para colocar comida na mesa 以死亡游戏为生。 靠死亡游戏混饭吃。 shiboyugi: das phantom-mädchen im spiel des todes shiboyugi: juegos mortales para ganarse el pan 靠死亡遊戲混飯吃。 shibou yuugi de meshi o kuu playing death games to put food on the table 사망 유희로 밥을 먹는다. shiboyugi: me gano el pan participando de juegos mortales смертельная игра ради еды на столе ลิขิตชะตาเกมท้าตาย смертельні ігри заради їжі на столі shiboyugi playing death games to put food on the table kiếm cơm bằng trò chơi sinh tử 死亡遊戯で飯を食う。', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phai-long-thien-than', 'Phải Lòng Thiên Thần', 'Be My Angel', 'https://phimimg.com/upload/vod/20260131-1/12b7fd3c3419e22b54acb1cee14d8db2.jpg', 'https://phimimg.com/upload/vod/20260131-1/81b0b21d3395638e077a34452a505123.jpg', '<p>Jane là một cô nàng lính mới nơi công sở với vận xui không ai bằng. Quá tuyệt vọng, cô đã dùng toàn bộ điểm tích đức cả đời của mình để đổi lấy ba điều ước trong một ứng dụng mang tên Lucky Points. Tuy nhiên, không những điều ước chẳng thành hiện thực, ứng dụng lại gửi đến cho cô Z — một thiên sứ &#39;hạng bét&#39; với kỹ năng bằng không.</p>', 'Tập 8', 8, 'series', 'ongoing', 14, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Thitiya Jirapornsilp","avatar":""},{"name":"Niwirin Limkangwalmongkol","avatar":""},{"name":"Matira Tantiprasut","avatar":""},{"name":"Rathavit Kijworalak","avatar":""},{"name":"Usha Seamkhum","avatar":""},{"name":"Chayanit Chansangavej","avatar":""},{"name":"Gornpop Janjaroen","avatar":""},{"name":"Hassaya Isariyasereekul","avatar":""},{"name":"Ratchaneeboon Pheinwikraisophon","avatar":""},{"name":"Thanakrit Panichawid","avatar":""},{"name":"Piamchon Damrongsunthornchai","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["ฉันหลงรักเทวดาของฉัน"]', 1784690324128);
