INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phai-long-thien-than', 'Phải Lòng Thiên Thần', 'Be My Angel', 'phải lòng thiên thần be my angel thitiya jirapornsilp niwirin limkangwalmongkol matira tantiprasut rathavit kijworalak usha seamkhum chayanit chansangavej gornpop janjaroen hassaya isariyasereekul ratchaneeboon pheinwikraisophon thanakrit panichawid piamchon damrongsunthornchai ฉันหลงรักเทวดาของฉัน', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-da-tai-nhung-vo-dung-bi-duoi-khoi-to-doi-anh-hung-yuusha-party-wo-oidasareta-kiyoubinbou', 'Kẻ Đa Tài Nhưng Vô Dụng Bị Đuổi Khỏi Tổ Đội Anh Hùng (Yuusha Party wo Oidasareta Kiyoubinbou)', 'Jack-of-All-Trades, Party Of None', 'https://phimimg.com/upload/vod/20260104-1/befd0f462ea8a29f489ad5fffc0e3024.jpg', 'https://phimimg.com/upload/vod/20260104-1/08910dbe836cf92ebaa1957472d9d517.jpg', '<p>Bị phản bội bởi chính người bạn thuở nhỏ và bị trục xuất khỏi Tổ đội Anh hùng, Orhun Dura — người từng là Pháp sư Cường hóa (Enchanter) trung thành của họ — đã bị các đồng đội cũ gắn mác là &#39;kẻ đa tài nhưng vô dụng&#39;. Cô độc giữa thế gian, anh dấn thân vào một hành trình mới với tư cách là một mạo hiểm giả đơn độc.Chuyến đi của anh bùng nổ với những trận chiến rực lửa, những đối thủ chết chóc và cả những đồng minh không ngờ tới — để rồi anh sẽ đứng lên phá tan mọi định kiến của kẻ khác. Cuộc lội ngược dòng vĩ đại nhất của kẻ độc hành chính thức bắt đầu!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Takeo Otsuka","avatar":""},{"name":"Hina Tachibana","avatar":""},{"name":"Saori Onishi","avatar":""},{"name":"You Taichi","avatar":""},{"name":"Manaka Iwami","avatar":""},{"name":"Yoshiki Nakajima","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["勇者パーティを追い出された器用貧乏　～パーティ事情で付与術士をやっていた剣士、万能へと至る～","Yuusha Party wo Oida Sareta Kiyou Binbou","Yūsha Party o Oidasareta Kiyō Binbō","Yuusha Party wo Oidasareta Kiyoubinbou","The Jack-of-All-Trades Kicked Out of the Hero''s Party: The Swordsman Who Became a Support Mage Due to Party Circumstances, Becomes All-Powerful","The Jack-of-All-Trades Kicked Out of the Hero''s Party","Jack-of-All-Trades, Party of None","Jack-of-All-Trades Party of None","勇者パーティを追い出された器用貧乏"]', 1784690324128);
