INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('han-the-nha-toi-khong-de-choc', 'Hãn Thê Nhà Tôi Không Dễ Chọc', 'My Valiant Wife', 'https://phimimg.com/upload/vod/20260321-1/597eb6075c1a7334e1b06aab43507803.jpg', 'https://phimimg.com/upload/vod/20260321-1/f1d83db01efda36cbda02b04766852e4.jpg', '<p>Chàng thư sinh mặt trắng Tiêu Bạch thành thân với người vợ dữ dằn Từ Tam Nương. Nào ngờ, nàng thực chất là một nữ tướng quân bị mất trí nhớ, còn chàng lại là một thế tử đang ẩn danh. Từ đôi phu thê hờ, họ dần trở thành những người đồng đội sát cánh bên nhau, tập hợp quân đội nhân dân để chống lại giặc Oa (hải tặc Nhật Bản) và đối đầu với bọn quyền hoạn (thái giám lũng đoạn quyền lực). Hai vợ chồng cùng nhau đập tan những âm mưu thâm độc, cứu giúp những người cô độc, yếu thế, và giữa thời loạn lạc, họ đã gầy dựng nên một tòa thành hiệp nghĩa cho bách tính.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 17, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Sở Ái Húc","avatar":""},{"name":"Cẩm Siêu","avatar":""},{"name":"Vương Song Bảo","avatar":""},{"name":"Dương Thanh Văn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["吾家悍妻不可欺"]', 1784690324128);
