INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vat-ao-dong-phuc', 'Vạt Áo Đồng Phục', 'Too Young To Love', 'https://phimimg.com/upload/vod/20260225-1/cb835ee9e13a13a6b2becee779c6c820.jpg', 'https://phimimg.com/upload/vod/20260225-1/03c081818c868643090b8283bc5e46a2.jpg', '<p>Cô thiếu nữ Y Lan từ nhỏ đã được mẹ hun đúc tình yêu với đàn Cello, và sớm bộc lộ tài năng thiên bẩm. Ngay tuần đầu tiên bước vào trường trung học, dưới sự khích lệ của người bạn thanh mai trúc mã Đồng Tiểu Lạc, cô quyết tâm thành lập ban nhạc tam tấu của riêng mình.&nbsp; Với mục tiêu &#39;đánh bại ban nhạc của trường&#39; và &#39;tham gia lễ hội văn hóa thường niên&#39;, Y Lan trở thành một &#39;tiểu thái dương&#39; luôn tràn đầy nhiệt huyết và năng lượng bền bỉ. Đồng Tiểu Lạc bị sự nhiệt tình ấy lan tỏa, cũng dần tìm lại được giấc mơ âm nhạc đã từng bỏ lỡ.&nbsp; Trong tiếng đàn du dương trầm bổng, trong những tiếng cười đùa cùng bạn bè, và cả những giọt nước mắt thầm kín của thiếu nữ, tà váy tung bay, tia sáng của ước mơ chợt lóe lên. Một cô gái đã tấu lên khúc nhạc thanh xuân của riêng mình, đồng thời chiếu sáng cả thế giới của một chàng thiếu niên. Những nam thanh nữ tú gặp nhau ở độ tuổi đẹp đẽ nhất, dùng âm nhạc, dùng ước mơ để viết nên mùa hè rực rỡ nhất của đời mình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 12, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tạ Bân Bân","avatar":""},{"name":"Trương Tân Di","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Xiao Fu De Qun Bai","School Uniform","Twirl of The Uniform Skirt","Hem of Youth","校服的裙摆"]', 1784690324128);
