INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-ai-tinh-yeu-tuoi-tre', 'Thanh Ái (Tình Yêu Tuổi Trẻ)', 'Love Youth', 'https://phimimg.com/upload/vod/20260320-1/ed87670bced4f607126e757776bd909d.jpg', 'https://phimimg.com/upload/vod/20260320-1/ff3e78162be3be6a97f8c0f3b4dd33fc.jpg', '<p>Quý Kiệt, người mất mẹ từ nhỏ, luôn ôm lòng oán hận sâu sắc và thường xuyên xảy ra xung đột với cha mình là Quý Thập Tam. Sự xuất hiện đột ngột của Thẩm Khôn đã buộc Quý Thập Tam phải hé lộ bí mật mà ông đã chôn giấu trong lòng suốt hơn mười năm với Quý Kiệt. Những mâu thuẫn giữa hai cha con dần được hóa giải trong sự ấm áp của tình thân. Với sự giúp đỡ của Dự án Thanh Ái và câu lạc bộ phúc lợi công cộng của Đại học Trung Hải, Quý Thập Tam và Quý Kiệt đã cùng nhau lên đường tìm kiếm Thẩm Khôn.</p>', 'Full', 1, 'single', 'completed', 9, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Kính Tùng","avatar":""},{"name":"Hướng Năng","avatar":""},{"name":"Vương Xuân Tử","avatar":""},{"name":"Nhâm Minh Tùng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["青爱"]', 1784690324128);
