INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-ve-dac-biet', 'Bảo Vệ Đặc Biệt', 'Code: Guardian (Special Security)', 'https://phimimg.com/upload/vod/20260320-1/5bc5c8d87392d465bdf4f4d0f1324c22.jpg', 'https://phimimg.com/upload/vod/20260320-1/c3b8ed5432ccdf55e14e177cd66aea3d.jpg', '<p>Câu chuyện kể về Hành Phong, một người làm trong ngành vệ sĩ. Vào lúc công ty sắp phá sản, anh bất ngờ nhận được một đơn hàng từ người bạn cũ, nhiệm vụ là tìm kiếm Trần Trác, ông chủ cũ của người bạn ấy. Khi Hành Phong đặt chân đến Tân Hải, mọi thế lực cũng lần lượt xuất hiện: kẻ nội gián phản bội, vị tổng tài bị thương, băng nhóm tội phạm có thể xuất hiện bất cứ lúc nào, cùng với cảnh sát luôn theo dõi họ sát sao. Một cuộc chiến đẫm máu và màn đấu trí căng thẳng là điều không thể tránh khỏi.</p>', 'Full', 1, 'single', 'completed', 12, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Dịch Danh","avatar":""},{"name":"Hàn Bá Duy","avatar":""},{"name":"Đàm Văn Tĩnh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Special Security","特殊安保"]', 1784690324128);
