INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-phap-y', 'Bác Sĩ Pháp Y', 'Scarpetta', 'https://phimimg.com/upload/vod/20260320-1/6ca82860c86069ef3d5f84f3f3ae73fe.jpg', 'https://phimimg.com/upload/vod/20260320-1/29a6e84d2221c7808cbd31b578a592c2.jpg', '<p>Bác sĩ pháp y lừng danh Kay Scarpetta trở lại vị trí Giám đốc Y khoa Bang Virginia, nơi bà điều tra một vụ giết người gây ám ảnh với những manh mối kỳ quái gợi nhớ đến vụ án lớn đầu tiên của bà từ nhiều thập kỷ trước. Vào năm 1998, Scarpetta làm việc cùng Thám tử Pete Marino và Đặc vụ FBI Benton Wesley khi họ điều tra một loạt vụ siết cổ dã man. Dựa trên những cuốn tiểu thuyết bán chạy nhất của Patricia Cornwell.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Nicole Kidman","avatar":""},{"name":"Jamie Lee Curtis","avatar":""},{"name":"Bobby Cannavale","avatar":""},{"name":"Simon Baker","avatar":""},{"name":"Rosy McEwen","avatar":""},{"name":"Jake Cannavale","avatar":""},{"name":"Hunter Parrish","avatar":""},{"name":"Ariana DeBose","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["首席女法医","猎杀史卡佩塔","Scarpetta"]', 1784690324128);
