INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-boc-ngot-ngao', 'Vỏ Bọc Ngọt Ngào', 'Sugar And Lies', 'https://phimimg.com/upload/vod/20260319-1/7d9cb8cc3e3260691a5162ec4aaea44c.jpg', 'https://phimimg.com/upload/vod/20260319-1/b72e83cf48a0179afc90a50412285ddf.jpg', '<p>Vào ngay đêm trước lễ đính hôn, Đinh Đang tình cờ tái ngộ với mối tình đầu của mình là Trần A Minh. Thế nhưng, cô không ngờ rằng anh giờ đây đã đổi tên thành Dư Khôn và mang một thân phận hoàn toàn mới. Để chữa trị chứng phân liệt nhân cách của Trần A Minh — hệ quả từ một cuộc thí nghiệm thất bại trong quá khứ — Đinh Đang đã cùng những người bạn âm thầm lập ra kế hoạch mang tên &quot;Vỏ bọc đường&quot; (Đường Y). Qua đó, cô dẫn dắt anh đối mặt với những nỗi đau xưa cũ, giúp anh thoát khỏi sự giằng xé giữa cảm xúc và ký ức để tìm lại chính mình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 11, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Kha Thuần","avatar":""},{"name":"Dư Nhân","avatar":""},{"name":"Tưởng Vân Lâm","avatar":""},{"name":"Úc Thông","avatar":""},{"name":"Cam Vọng Tinh","avatar":""},{"name":"Tạ Nhĩ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["不一样的她之糖衣","The Unique Her: Sugar and Lies","糖衣"]', 1784690324128);
