INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vo-boc-ngot-ngao', 'Vỏ Bọc Ngọt Ngào', 'Sugar And Lies', 'vỏ bọc ngọt ngào sugar and lies kha thuần dư nhân tưởng vân lâm úc thông cam vọng tinh tạ nhĩ 不一样的她之糖衣 the unique her: sugar and lies 糖衣', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-cua-ke-thuc-dung', 'Tình Yêu Của Kẻ Thực Dụng', 'Love Story In The 1970s', 'https://phimimg.com/upload/vod/20260319-1/52fb711d7bfb9ef899f7656e83110307.jpg', 'https://phimimg.com/upload/vod/20260319-1/a7c6881e7513a6409b13a4d080bf5200.jpg', '<p>Vào những năm 70, nữ công nhân xưởng dệt Phí Nghê luôn nuôi khát vọng vào đại học để thay đổi số phận. Khi bạn học cũ Phương Mục Dương bị thương sau khi cứu người và được tôn vinh là anh hùng, cô chủ động chăm sóc anh với hy vọng được đề cử đi học, nhưng liên tục thất bại. Trước áp lực cuộc sống và để giúp anh trai có nhà sau khi kết hôn, Phí Nghê đề nghị kết hôn giả với Phương Mục Dương để được phân nhà.

Từ một cuộc hôn nhân trên danh nghĩa, hai người cùng vượt qua khó khăn, động viên nhau theo đuổi ước mơ và dần nảy sinh tình cảm trong những ngày tháng bình dị. Cuối cùng, Phí Nghê được vào đại học như mong muốn, còn Phương Mục Dương thực hiện ước mơ trở thành họa sĩ, cùng nhau bước tiếp về phía tương lai và hạnh phúc.</p>', 'Hoàn Tất (29/29)', 29, 'series', 'completed', 13, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Phi Vũ","avatar":""},{"name":"Tôn Thiên","avatar":""},{"name":"Quách Hiểu Đình","avatar":""},{"name":"Lưu Hựu Sướng","avatar":""},{"name":"Lưu Mẫn Đào","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["实用主义者的爱情","Love Story in the 1970s","纯真年代的爱情"]', 1784690324128);
