INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-ho-da-vu-thap-nien-dang', 'Giang Hồ Dạ Vũ Thập Niên Đăng', 'Generation to Generation', 'https://phimimg.com/upload/vod/20260225-1/fa2e4182792f1e496901235e4aa32b60.jpg', 'https://phimimg.com/upload/vod/20260225-1/712c09a1fc9cb38da9b7afcd46456759.jpg', '<p>Mộ Thanh Yến, một thiếu chủ thâm độc bí hiểm hành sự quyết đoán cùng Thái Chiêu, một nữ hiệp không tranh với đời tính tình thoải mái và sáng suốt, có một màn giằng co giữa hai kẻ mạnh và tạo nên một mối tình ngọt ngào xen lẫn đau thương. Giữa chốn giang hồ quỷ quyệt khôn lường, hai người chung tay xé tan lớp mặt nạ giả dối của nhân sĩ võ lâm, trải qua yêu hận đan xen, vô vàn ngã rẽ, đấu trí không ngừng, khắc họa nên bức chân dung hiệp nghĩa đầy hơi thở nhân gian.</p>', 'Hoàn Tất (37/37)', 37, 'series', 'completed', 28, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chu Dực Nhiên","avatar":""},{"name":"Bao Thượng Ân","avatar":""},{"name":"Dư Gia Thành","avatar":""},{"name":"Phạm Tĩnh Y","avatar":""},{"name":"Biên Thiên Dương","avatar":""},{"name":"Đoàn Ngọc","avatar":""},{"name":"Diêm Ngọc Thần","avatar":""},{"name":"Đại Húc","avatar":""},{"name":"Lý Viện","avatar":""},{"name":"Kinh Siêu","avatar":""},{"name":"Lư Sam","avatar":""},{"name":"Xa Bảo La","avatar":""},{"name":"Triệu Anh Bác","avatar":""},{"name":"Thịnh Nhất Luân","avatar":""},{"name":"Vạn Bằng","avatar":""},{"name":"Lý Quân Nhuệ","avatar":""},{"name":"Lưu Nhuận Minh","avatar":""},{"name":"Thiện Kính Nghiêu","avatar":""},{"name":"Trình Hoằng Hâ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d