INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('giang-ho-da-vu-thap-nien-dang', 'Giang Hồ Dạ Vũ Thập Niên Đăng', 'Generation to Generation', 'giang hồ dạ vũ thập niên đăng generation to generation chu dực nhiên bao thượng ân dư gia thành phạm tĩnh y biên thiên dương đoàn ngọc diêm ngọc thần đại húc lý viện kinh siêu lư sam xa bảo la triệu anh bác thịnh nhất luân vạn bằng lý quân nhuệ lưu nhuận minh thiện kính nghiêu trình hoằng hâ jiang hu ye yu shi nian deng chasing legends 江湖夜雨十年灯 ทิวากาลแห่งพิรุณโปรย ten years lantern on a stormy martial arts world night jianghu night rain ten years of lights a decade of nightscape lights generation to generation', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tram-khoa-tinh', 'Trâm Khoá Tình', 'The Inescapable', 'https://phimimg.com/upload/vod/20260309-1/872ed7e913666c2336ccd9f118accb78.jpg', 'https://phimimg.com/upload/vod/20260309-1/d2a60306fcc9d2a518dd80def617dd95.jpg', '<p>Bách Hiểu sơn trang tọa lạc giữa chốn rừng sâu chướng khí ngút ngàn, suốt mấy chục năm qua luôn là một vùng cấm địa bí ẩn. Thế nhưng, ngay trước thềm Bách Hiểu dạ yến, trang chủ Bách Hiểu sơn trang lại đột nhiên mất tích một cách khó hiểu. Giữa lúc cấp bách, tử tù Diệp Lễ đã tự nguyện đứng ra, bắt tay cùng bổ khoái Đại Lý Tự là Hóa Càn Khôn để điều tra chân tướng. Cả hai đã xả thân nhập cuộc, xông pha vào chốn hiểm nguy, để rồi vô tình vén lên bức màn che giấu một âm mưu kinh thiên động địa ẩn sau sơn trang…</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 19, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Quản Nhạc","avatar":""},{"name":"Phó Nhu Mỹ Kỳ","avatar":""},{"name":"Dương Vũ Bân","avatar":""},{"name":"Hà Hạo Dương","avatar":""},{"name":"Ngô Hựu Nam","avatar":""},{"name":"Tiểu Đậu Hoa","avatar":""},{"name":"Tô Đông Thanh","avatar":""},{"name":"Miêu Khả","avatar":""},{"name":"La Đại Đào","avatar":""},{"name":"Khương Khải Văn","avatar":""},{"name":"Trương Bắc Bắc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["锁簪"]', 1784690324128);
