INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-mong-du-2026', 'Kẻ Mộng Du', 'Sleepwalker', 'https://phimimg.com/upload/vod/20260318-1/8cd70559408679045752c9ba7ddb1979.jpg', 'https://phimimg.com/upload/vod/20260318-1/88b1e1b5ff804a78657ce286b21bafe5.jpg', '<p>Một người mẹ đau khổ bị ám ảnh bởi cái chết bi thảm của con gái trong một tai nạn xe hơi — tai nạn đã khiến người chồng bạo hành của cô rơi vào trạng thái hôn mê. Khi dần trượt sâu vào bóng tối của những trải nghiệm siêu thực, các cơn mộng du của cô ngày càng dữ dội. Bị dày vò bởi những ảo ảnh rùng rợn về người chồng xuất hiện trong chính ngôi nhà của mình, cô phải vật lộn để phân định đâu là thực tại… và đâu là cơn ác mộng.</p>', 'Full', 1, 'single', 'completed', 13, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Hayden Panettiere","avatar":""},{"name":"Justin Chatwin","avatar":""},{"name":"Beverly D''Angelo","avatar":""},{"name":"Mischa Barton","avatar":""},{"name":"Lori Tan Chinn","avatar":""},{"name":"Eric Lutes","avatar":""},{"name":"Kea Ho","avatar":""},{"name":"Laird LaCoste","avatar":""},{"name":"Corinne Sweeney","avatar":""},{"name":"Cathy Salvodon","avatar":""},{"name":"Gene Dante","avatar":""},{"name":"Chris Everett","avatar":""},{"name":"Tom DeNucci","avatar":""},{"name":"Robert Goon","avatar":""},{"name":"Jana Nawartschi","avatar":""},{"name":"Jazz Mann","avatar":""},{"name":"Shirvorne Bruder","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Sleepwalker"]', 1784690324128);
