INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doan-tu-su-that-tham-lang', 'Đoàn Tụ: Sự Thật Thầm Lặng', 'Saikai: Silent Truth', 'https://phimimg.com/upload/vod/20260114-1/423bed6ed65589d998bf4225703a37ea.jpg', 'https://phimimg.com/upload/vod/20260114-1/dcb0ee410723016b4ba26770015713e7.jpg', '<p>Trở về quê nhà điều tra một vụ án mạng, thám tử nọ phát hiện những mối liên hệ chấn động giữa chính mình với nghi phạm chính và hung khí.</p>', 'Tập 9', 10, 'series', 'ongoing', 21, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ryoma Takeuchi","avatar":""},{"name":"Mao Inoue","avatar":""},{"name":"Daichi Watanabe","avatar":""},{"name":"Koji Seto","avatar":""},{"name":"Kana Kita","avatar":""},{"name":"Yasunori Danta","avatar":""},{"name":"Noriko Eguchi","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Reunion / 再会","Saikai ~Silent Truth~","Saikai Silent Truth","再会～Silent Truth～"]', 1784690324128);
