INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bui-hoa-hong', 'Bụi Hoa Hồng', 'About Love', 'https://phimimg.com/upload/vod/20260227-1/5b9a25050a82a4606d80dd00af9cd35e.jpg', 'https://phimimg.com/upload/vod/20260227-1/8b60d37846e87e2403abdaf5ec396b39.jpg', '<p>Bộ phim kể về cuộc gặp gỡ định mệnh giữa Lý Hiểu Hề – một cô gái luôn nghiêm túc và thận trọng trong chuyện tình cảm – và chàng trai Tiểu Bối, từ đó, họ bắt đầu một mối tình lãng mạn. Chính sự chân thành và kiên định của Tiểu Bối đã tiếp thêm sức mạnh, giúp Lý Hiểu Hề dần vượt qua những cảm giác bất an và lo sợ trong tình yêu. Ngược lại, nhờ sự đồng hành và bao dung của Lý Hiểu Hề, Tiểu Bối cũng chữa lành được những vết thương lòng trong quá khứ, dần dần buông bỏ nỗi đau và học cách trân trọng hiện tại. Hành trình vun đắp tình cảm ấy đã giúp cả hai nhìn thấy nhiều khía cạnh đa dạng hơn của tình yêu. Sau khi cùng nhau trải qua bao khó khăn và thử thách, cuối cùng họ cũng trưởng thành hơn và tìm thấy tình yêu chân thành.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 10, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Tử Văn","avatar":""},{"name":"Lưu Vũ Ninh","avatar":""},{"name":"Tưởng Hân","avatar":""},{"name":"Cốc Gia Thành","avatar":""},{"name":"Chu Gia Kỳ","avatar":""},{"name":"Hoàng Tử Kỳ","avatar":""},{"name":"An Điền","avatar":""},{"name":"Châu Đại Vi","avatar":""},{"name":"Dương Hạnh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["蝉女","相遇恰逢其时","五光十色的我们","Mei Gui Cong Sheng","最爱的你","爱如蝉翼","Цикада","Заросли шиповника","Девушки-цикады","蟬女","Cicada Girls","About Love","玫瑰丛生"]', 1784690324128);
