INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bui-hoa-hong', 'Bụi Hoa Hồng', 'About Love', 'bụi hoa hồng about love vương tử văn lưu vũ ninh tưởng hân cốc gia thành chu gia kỳ hoàng tử kỳ an điền châu đại vi dương hạnh 蝉女 相遇恰逢其时 五光十色的我们 mei gui cong sheng 最爱的你 爱如蝉翼 цикада заросли шиповника девушки-цикады 蟬女 cicada girls about love 玫瑰丛生', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuan-tra-dem', 'Tuần Tra Đêm', 'Night Patrol', 'https://phimimg.com/upload/vod/20260318-1/826d7b3e205761a96891680d50d38f45.jpg', 'https://phimimg.com/upload/vod/20260318-1/062948665955cbddc37fc2a6aa2b04aa.jpg', '<p>Một cảnh sát ở Los Angeles phát hiện ra rằng một đội đặc nhiệm địa phương đang che giấu một bí mật nguy hiểm — bí mật có thể đẩy những cư dân trong khu phố nơi anh lớn lên vào vòng hiểm họa. Khi sự thật dần lộ diện, anh buộc phải lựa chọn giữa việc bảo vệ huy hiệu và bảo vệ chính cộng đồng của mình.</p>', 'Full', 1, 'single', 'completed', 11, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jermaine Fowler","avatar":""},{"name":"Justin Long","avatar":""},{"name":"Phil Brooks","avatar":""},{"name":"Dermot Mulroney","avatar":""},{"name":"Freddie Gibbs","avatar":""},{"name":"RJ Cyler","avatar":""},{"name":"YG","avatar":""},{"name":"Nicki Micheaux","avatar":""},{"name":"Flying Lotus","avatar":""},{"name":"Jon Oswald","avatar":""},{"name":"Mike Ferguson","avatar":""},{"name":"Evan Shafran","avatar":""},{"name":"Zuri Reed","avatar":""},{"name":"Kim Yarbrough","avatar":""},{"name":"Nick Gillie","avatar":""},{"name":"Dennis Boyd","avatar":""},{"name":"Colin Young","avatar":""},{"name":"Brionna Maria Lynch","avatar":""},{"name":"Dartenea","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Night Patrol"]', 1784690324128);
