INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('se-duyen-dia-dai', 'Se Duyên Địa Đại', 'The Earth (The Earth 4 Elements)', 'https://phimimg.com/upload/vod/20260202-1/b39e2d2629e64c885124c853359433be.jpg', 'https://phimimg.com/upload/vod/20260202-1/f0bf841d6429e5979cc1ae1d936fcd48.jpg', '<p>Rose Thippapha, người thừa kế của trang trại Chomjan, vội vã từ Mỹ trở về Chiang Rai sau khi cha dượng của cô rơi vào tình trạng hôn mạng sau một tai nạn đầy nghi vấn. Tại đây, cô rơi vào tầm ngắm nguy hiểm của Wasu – một chủ vườn nho đang âm mưu ép cô kết hôn nhằm chiếm đoạt đất đai cho các hoạt động kinh doanh phi pháp của hắn.&nbsp; May mắn thay, Din Kasama Wathinwanit – người bạn thanh mai trúc mã và cũng là chủ một trang trại rau hữu cơ – đã xuất hiện để bảo vệ cô. Để đảm bảo an toàn tuyệt đối cho Rose, cả hai buộc phải bước vào một cuộc hôn nhân giả. Dù chỉ là danh nghĩa, nhưng sự gần gũi sau nhiều năm xa cách đã dần khiến những cảm xúc thật sự nảy nở giữa họ.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 13, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Lapisara Intarasut","avatar":""},{"name":"Panthita Jencharoentham","avatar":""},{"name":"Sarocha Chankimha","avatar":""},{"name":"Engfa Waraha","avatar":""},{"name":"Milin Watinthanakit","avatar":""},{"name":"Nutthasid Panyangarm","avatar":""},{"name":"Pathsitar Phengkong","avatar":""},{"name":"Natsinee Charoensitthisap","avatar":""},{"name":"Piya Vimuktayon","avatar":""},{"name":"Surasak Chaiat","avatar":""},{"name":"Ake Oree","avatar":""},{"name":"Rachaya Rakkasikorn","avatar":""},{"name":"Penpetch Benyakul","avatar":""},{"name":"Tha","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["四大元素","The Earth 4 Elements","4 Elements: The Earth","บ้านวาทินวณิช: วิวาห์ปฐพี","วิวาห์ปฐพี บ้านวาทินวณิช","วิวาห์ปฐพี"]', 1784690324128);
