INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giau-kin-tinh-yeu', 'Giấu Kín Tình Yêu', 'Love In A Secret (Forbidden Love)', 'https://phimimg.com/upload/vod/20260309-1/fef4a6abe4c9795c803496ed3a8c6516.jpg', 'https://phimimg.com/upload/vod/20260309-1/229328e8b1812312028f173da0d95f97.jpg', '<p>Người anh kế tâm cơ Diệp Mãn từng bước bày mưu tính kế để tiếp cận cô em gái Lộc Trúc, trong khi bà mẹ kế điên cuồng chèn ép cô về mọi mặt, từ danh lợi, địa vị cho đến tình thân. Mọi thứ đều đang đứng bên bờ vực sụp đổ. Thế nhưng, không ai có thể ngờ rằng, khởi đầu của ván cờ này lại là việc người anh kế đánh mất lý trí, đem lòng yêu chính cô em gái vốn dĩ phải là quân cờ bị mình tính kế... Phải chăng thứ tình cảm bị cấm đoán ấy sẽ mãi mãi bị chôn giấu trong những góc tối u ám?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 11, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Diêu Quán Vũ","avatar":""},{"name":"Châu Tử Hâm","avatar":""},{"name":"Lương Dực Trình","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Forbidden Love","藏匿爱意"]', 1784690324128);
