INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-chung-so-yeu', 'Hội Chứng Sợ Yêu', 'Love Phobia', 'https://phimimg.com/upload/vod/20260228-1/ad4d28e4f4cc791f56b3666b8cbbf6ab.jpg', 'https://phimimg.com/upload/vod/20260228-1/61331adaf8959d15b132eaf69d7987d2.jpg', '<p>Một CEO của công ty hẹn hò thực tế ảo, người ghét tình yêu, gặp gỡ một nhà văn hoàn toàn không hiểu gì về chuyện tình cảm. Khi họ xung đột giữa đam mê do trí tuệ nhân tạo điều khiển và cảm xúc đời thực, một câu chuyện ngọt ngào nhưng cũng đầy rắc rối về sự hàn gắn và kết nối bất ngờ dần hé mở.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 13, 2026, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yeon Woo","avatar":""},{"name":"Kim Hyun-jin","avatar":""},{"name":"Jo Yoon-seo","avatar":""},{"name":"Choi Byung-chan","avatar":""},{"name":"Im Ji-eun","avatar":""},{"name":"Han Gyu-min","avatar":""},{"name":"Lee Ji-hae","avatar":""},{"name":"Kim Ki-nam","avatar":""},{"name":"Kim So Ha","avatar":""},{"name":"Hwang Ha-jung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["爱情恐惧症","恋爱恐惧症","Fobia al amor","فوبيا الحب","戀愛恐懼症","Love Phobia","러브 포비아"]', 1784690324128);
