INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-pham-101', 'Tội Phạm 101', 'Crime 101', 'https://phimimg.com/upload/vod/20260315-1/2138140c11fca88230f350e2238d11f2.jpg', 'https://phimimg.com/upload/vod/20260315-1/2977a8030c437759cb7f9b493d3e9cf2.jpg', '<p>Lấy bối cảnh thành phố Los Angeles đầy nắng và bụi đường, Tội Phạm 101 kể về một tên trộm nữ trang bí ẩn (Chris Hemsworth) với hàng loạt phi vụ táo bạo khiến cảnh sát phải đau đầu. Trong lúc chuẩn bị cho phi vụ lớn nhất của mình, hắn gặp gỡ một nữ nhân viên bảo hiểm (Halle Berry), người cũng đang vật lộn với những lựa chọn trong đời mình. Trong khi đó, một thanh tra (Mark Ruffalo) đã tìm ra quy luật trong chuỗi các vụ án và đang ráo riết truy đuổi tên trộm, khiến cuộc chơi trở nên căng thẳng hơn bao giờ hết. Khi phi vụ định mệnh đến gần, ranh giới giữa kẻ săn đuổi và con mồi dần trở nên mờ nhạt và cả ba buộc phải đối mặt với những lựa chọn khó khăn và không còn cơ hội để quay đầu lại. Bộ phim được chuyển thể từ tiểu thuyết ngắn nổi tiếng cùng tên của Don Winslow, do Bart Layton (tác giả của American Animals, The Imposter) viết kịch bản và đạo diễn. Dàn diễn viên có sự tham gia của Barry Keoghan, Monica Barbaro, Corey Hawkins, Jennifer Jason Leigh và Nick Nolte.</p>', 'Full', 1, 'single', 'completed', 25, 2026, 'Vietsub', 'CAM', 'Anh', 1, '[{"name":"Chris Hemsworth","avatar":""},{"name":"Mark Ruffalo","avatar":""},{"name":"Halle Berry","avatar":""},{"name":"Barry Keoghan","avatar":""},{"name":"Monica Barbaro","avatar":""},{"name":"Nick Nolte","avatar":""},{"name":"Corey Hawkins","avatar":""},{"name":"Jennifer Jason Leigh","avatar":""},{"name":"Peter Banifaz","avatar":""},{"name":"Babak Tafti","avatar":""},{"name":"Payman Maadi","avatar":""},{"name":"Hossein Mardani","avatar":""},{"name":"Tate Donovan","avatar":""},{"name":"Andra Nechita","avatar":""},{"name":"Crosby Fitzgerald","avatar":""},{"name":"Patrick Mulvey","avatar":""},{"name":"Hanako F","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ceļš uz noziegumu","Cinayət 101","Cesta zločinu","Caminos del Crimen","Kelias į nusikaltimą","เส้นทางปล้นโคตรระห่ำ","Autostrada e krimit","الجريمة 101","Crime 101"]', 1784690324128);
