INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trao-em-ca-vu-tru', 'Trao Em Cả Vũ Trụ', 'Our Universe', 'https://phimimg.com/upload/vod/20260209-1/e898e1eda8286fc1188ce909123253d4.jpg', 'https://phimimg.com/upload/vod/20260209-1/6244cc481b717b579d553961a2d013fb.jpg', '<p>Hai người họ hàng bên nội và bên ngoại, sau một biến cố đau lòng, bị buộc phải cùng nhau nuôi dạy đứa cháu nhỏ mồ côi. Sống chung dưới một mái nhà, họ dần vượt qua những hiểu lầm và định kiến về nhau. Thông qua hành trình cùng làm cha mẹ, cả hai không chỉ tìm thấy sự trưởng thành cho bản thân mà còn nảy sinh một tình cảm lãng mạn không ngờ tới.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 15, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Bae In-hyuk","avatar":""},{"name":"Roh Jeong-eui","avatar":""},{"name":"Park Seo-ham","avatar":""},{"name":"Ku Sung-hwan","avatar":""},{"name":"Choi Gyu-ri","avatar":""},{"name":"Oh Hyun-joong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Notre univers","Ujureul Julge","عالمنا","จักรวาลบันดาลรัก","I''ll Give You the Universe","우주를 줄게"]', 1784690324128);
