INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-lai-nam-2000-theo-duoi-nang-hoa-khoi-cung-ban', 'Trở Lại Năm 2000: Theo Đuổi Nàng Hoa Khôi Cùng Bàn', 'Reborn In 2000: Crush On My Deskmate', 'https://phimimg.com/upload/vod/20260309-1/f6278fe68b14bb04818aee5ee0f816bf.jpg', 'https://phimimg.com/upload/vod/20260309-1/83922aa682c3a4ddbb1134506ce8b776.jpg', '<p>Trần Phàm, một người đàn ông mang trong mình căn bệnh nan y, bất ngờ trọng sinh quay trở lại năm 2000. Khi ấy, anh được gặp lại Tô Nhược Sơ, cô bạn hoa khôi cùng bàn, người mà ở kiếp trước đã không may qua đời trong một vụ tai nạn ô tô, cũng là người mà anh thầm mến. Để bù đắp cho những tiếc nuối năm xưa, Trần Phàm quyết tâm bắt đầu lại từ hai bàn tay trắng, từng bước gây dựng nên một đế chế thương mại hùng mạnh, trao tặng cho cô gái anh yêu một tình yêu hoàn mỹ và một tương lai rực rỡ nhất.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 9, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Thiệu Vũ Thất","avatar":""},{"name":"Tưởng Tập Minh","avatar":""},{"name":"Vương Trung Hạo","avatar":""},{"name":"Dư Toàn","avatar":""},{"name":"Chu Hạo Khiêm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chong Sheng 2000: Cong Zhui Qiu Qing Se Xiao Hua Tong Zhuo Kai Shi","Chong Sheng 2000 Cong Zhui Qiu Qing Se Xiao Hua Tong Zhuo Kai Shi","重生2000：从追求青涩校花同桌开始"]', 1784690324128);
