INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-cuoi-cua-sao-eric-dane', 'Lời Cuối Của Sao: Eric Dane', 'Famous Last Words: Eric Dane', 'https://phimimg.com/upload/vod/20260314-1/a6fe7b04285521f1087046f570114cd9.jpg', 'https://phimimg.com/upload/vod/20260314-1/5045e3fe74419a4a4c72ca5a358a4402.jpg', '<p>Trong cuộc phỏng vấn xúc động này, cố diễn viên kiêm nhà hoạt động vì bệnh nhân ALS, Eric Dane, chia sẻ thông điệp cuối của mình với thế giới – được phát sóng sau khi ông qua đời.</p>', 'Full', 1, 'single', 'completed', 8, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Eric Dane","avatar":""},{"name":"Brad Falchuk","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Últimas palabras : Eric Dane","Últimas palabras famosas: Eric Dane","Famous Last Words: Eric Dane"]', 1784690324128);
