INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-do-esa-noche', 'Đêm Đó (Esa noche)', 'That Night', 'https://phimimg.com/upload/vod/20260314-1/9b4eb5ba91260dcd4be06a3c0c69b18c.jpg', 'https://phimimg.com/upload/vod/20260314-1/077650ce76c1d613002b5055e7178895.jpg', '<p>Khi một người mẹ đơn thân trẻ tuổi, ngây thơ vướng vào một vụ án mạng trong kỳ nghỉ trên đảo, các chị của cô vội đến giúp đỡ. Nhưng họ chỉ khiến mọi việc tồi tệ hơn.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 15, 2026, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Clara Galle","avatar":""},{"name":"Claudia Salas","avatar":""},{"name":"Paula Usero","avatar":""},{"name":"Null García","avatar":""},{"name":"Raidher Díaz","avatar":""},{"name":"Gabriel Polanco","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["เรื่องในคืนนั้น","That Night","Esa noche"]', 1784690324128);
