INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giot-ruou-than-thanh-les-gouttes-de-dieu-phan-2', 'Giọt Rượu Thần Thánh (Les Gouttes de Dieu) (Phần 2)', 'Drops Of God (Season 2)', 'https://phimimg.com/upload/vod/20260209-1/fa6dcde8ec2627242af173dae8fbffba.jpg', 'https://phimimg.com/upload/vod/20260209-1/4b0d1fe7bff304c11fb4884ae7d6e8c2.jpg', '<p>Trong khi thế giới rượu vang tiếc thương cái chết của Alexandre Léger, Camille - cô con gái bị ghẻ lạnh của ông biết rằng bộ sưu tập đặc biệt của ông giờ là của cô. Nhưng trước khi đòi được quyền thừa kế của mình, Camille phải vượt qua Issei, người mà Alexandre bảo trợ, trong một cuộc thi về giác quan của họ.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 20, 2026, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Fleur Geffrier","avatar":""},{"name":"Tomohisa Yamashita","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["神之水滴","ღვინის წვეთები","ღვთის წვეთები","טיפות של אלוהים","Kami no Shizuku/Drops of God","Kami no Shizuku","Les Gouttes de Dieu"]', 1784690324128);
