INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thap-thien-thong', 'Tháp Thiên Thông', 'Tower Of Babel', 'https://phimimg.com/upload/vod/20260310-1/38ec03e97ea53683742d1de22a03f219.jpg', 'https://phimimg.com/upload/vod/20260310-1/e52b9eac973e3ead5527073c4aafe432.jpg', '<p>Vụ án mạng lúc nửa đêm tại biệt thự Thông Thiên Tháp ở Miến Thành đã trở thành một truyền thuyết đô thị đầy ám ảnh: Chủ nhà bị chém chết, người vợ tự thiêu kết liễu đời mình, hai mạng người ra đi chỉ trong một đêm. Vài tháng sau, sáu người cùng tụ họp tại Thông Thiên Tháp nhằm vén màn sự thật về bản di chúc. Thế nhưng, họ không hề hay biết mình đã rơi vào chiếc lưới định mệnh được giăng sẵn từ lâu. Khi bí mật dần lộ diện cũng là lúc nguy hiểm rình rập khắp nơi, không một ai có thể rút lui an toàn. Dưới lớp màn u ám của âm mưu và toan tính, rốt cuộc chân tướng là gì?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 11, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ô Nhật Lệ Cách","avatar":""},{"name":"Phó Mai","avatar":""},{"name":"Vương Minh","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["通天之塔"]', 1784690324128);
