INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hua-voi-em-muoi-nam-hen-uoc-10-nam', 'Hứa Với Em Mười Năm (Hẹn Ước 10 Năm)', 'Love After Addiction', 'https://phimimg.com/upload/vod/20260210-1/c8785c9c89966455aa490e80fbe0b925.jpg', 'https://phimimg.com/upload/vod/20260210-1/ba6ce46c84837edbeb69d82e3a3bdaa0.jpg', '<p>Hai người họ hàng bên nội và bên ngoại, sau một biến cố đau lòng, bị buộc phải cùng nhau nuôi dạy đứa cháu nhỏ mồ côi. Sống chung dưới một mái nhà, họ dần vượt qua những hiểu lầm và định kiến về nhau. Thông qua hành trình cùng làm cha mẹ, cả hai không chỉ tìm thấy sự trưởng thành cho bản thân mà còn nảy sinh một tình cảm lãng mạn không ngờ tới.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 15, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lin Fengsong","avatar":""},{"name":"Chen Wen","avatar":""},{"name":"Wang Peiwei","avatar":""},{"name":"Hu Heran","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Xu Ni Shi Nian","I Promise You 10 Years","许你十年"]', 1784690324128);
