INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vinh-vo-chi-canh-boi-khong-ngung-nghi', 'Vịnh Vô Chỉ Cảnh (Bơi Không Ngừng Nghỉ)', 'Swimming Limitless', 'https://phimimg.com/upload/vod/20260310-1/7a3541c72db11b095b39d3b5a3ce221a.jpg', 'https://phimimg.com/upload/vod/20260310-1/afe6cc88bc806b69a43b0f44d962a1da.jpg', '<p>hiếu niên nổi loạn Lâm Bắc đã khám phá ra tài năng bơi lội thiên bẩm của mình dưới sự dẫn dắt của Huấn luyện viên Trương Trúc Điền. Cùng với Phan Lượng – người từ đối thủ đã trở thành đồng đội – cậu phải đối mặt với những trăn trở của bản thân, áp lực từ gia đình và sự cạnh tranh khốc liệt. Nhờ vào lòng kiên trì và tinh thần đồng đội, họ đã cùng nhau trưởng thành, vượt qua mọi chướng ngại và gặt hái vinh quang cho cả cá nhân lẫn tập thể trên đường đua xanh.</p>', 'Hoàn Tất (17/17)', 17, 'series', 'completed', 9, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tề Tử Kiệt","avatar":""},{"name":"Dương Dịch Đức","avatar":""},{"name":"Tề Kha Phỉ","avatar":""},{"name":"Trương Hinh Nhi","avatar":""},{"name":"Lôi Vũ Phi","avatar":""},{"name":"Lý Hãn Quân","avatar":""},{"name":"Vương Thi Mông","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yong Wu Zhi Jing","泳无止境"]', 1784690324128);
