INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sawatdee-krab-cuoc-phieu-luu-o-thai-lan', 'Sawatdee Krab: Cuộc Phiêu Lưu Ở Thái Lan', 'Sawatdee Krab: Adventure In Thailand', 'https://phimimg.com/upload/vod/20260310-1/6b17471ac89342b4952369b499228d43.jpg', 'https://phimimg.com/upload/vod/20260310-1/8a3eafd406d1b7a3fe1c9866eec6d98a.jpg', '<p>Nghìn năm trước, Công chúa Chiêu Dương nhà Nguyên và Hoàng tử Sukhothai bị ám sát trên đường đi hòa thân, cả hai cùng bảo vật &quot;Nước mắt Buluotuo&quot; và bốn con ếch đồng rơi xuống vực thẳm, bảo vật từ đó biệt tăm không dấu vết. Thời hiện đại, Lưu Vũ vì cha mẹ mất tích khi theo Giáo sư Vi đi khảo cổ nên luôn mang lòng oán hận ông, nhưng nhờ khả năng chịu được sự xung kích của luồng thông tin AI, anh được Giáo sư Vi trả trọng kim để mời vào không gian ảo AI đóng vai Hoàng tử Sukhothai nhằm tìm kiếm manh mối bảo vật. Anh không hề biết rằng tổ chức Hắc Xà đã sớm cài cắm nội gián, cử con gái nuôi đang mắc bệnh ung thư não là Su Laya đóng giả Công chúa Chiêu Dương thâm nhập vào không gian ảo. Tại đây, hai người vừa thăm dò lẫn nhau vừa che giấu thân phận thật sự của mình.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 12, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hầu Trọng Ngọc","avatar":""},{"name":"A Y Hạ","avatar":""},{"name":"Nhậm Thiên Dã","avatar":""},{"name":"Đỗ Cẩm Hồng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sa Wa Di Ka Tai Jing Qi Yuan","萨瓦迪卡泰境奇缘","Sawasdeeka - A Thai Adventure","Sawadika—The Thai Adventure","萨瓦迪卡—泰境奇缘"]', 1784690324128);
