INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oan-gia-duong-tom', 'Oan Gia Đường Tôm', 'Shrimp Encounter', 'https://phimimg.com/upload/vod/20260310-1/a53c1562c9c5d235defe61348da3950a.jpg', 'https://phimimg.com/upload/vod/20260310-1/e0a8da7c9fa99ef674fc53120fa9c527.jpg', '<p>Mọi chuyện bắt đầu từ một sự cố dở khóc dở cười liên quan đến chiếc chum thần! Để che giấu lỗi lầm, Vệ Long cùng hai người bạn lên đường sửa chum, nào ngờ lại bị cuốn vào âm mưu gián điệp rối ren, rồi lạc bước đến chốn thế ngoại đào nguyên. Tại đây, nhờ &quot;bảo vật thông cống&quot; thần kỳ, họ bất ngờ bắt đầu hành trình khởi nghiệp giữa thời cổ đại. Khi âm mưu đen tối chạm trán tinh hoa ẩm thực, khi tình yêu vướng phải những hiểu lầm oái oăm, ba cây hài này đã dùng món tôm hùm đất tê cay để viết nên một huyền thoại cổ trang cực kỳ hoang đường!</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 15, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Thành Tư","avatar":""},{"name":"Ngụy Tử Hân","avatar":""},{"name":"Cao Thiên Ni","avatar":""},{"name":"Thường Tô Thịnh","avatar":""},{"name":"Lưu Dĩ Hàng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["虾路相逢"]', 1784690324128);
