INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-dang-yeu', 'Gia Đình Đáng Yêu', 'The Adorable Family', 'https://phimimg.com/upload/vod/20260310-1/1c12bea5cb8c83dc2f5b050bb4ad1f99.jpg', 'https://phimimg.com/upload/vod/20260310-1/7a8e1d8d2940db0b1f6b371cc423084e.jpg', '<p>Sau khi sinh con, một người phụ nữ thành đạt vốn luôn hoàn mỹ trong công việc bỗng thấy mình bị choáng ngợp trước thực tế khắc nghiệt của việc làm mẹ. Với hy vọng nhận được sự quan tâm và thấu hiểu hơn từ gia đình, cô đã giả vờ mình bị trầm cảm sau sinh. Thế nhưng, lời nói dối ấy đã phản tác dụng khi hai thế hệ bắt đầu dọn về sống chung, đẩy cuộc sống của cô vào cảnh hỗn loạn giữa những nỗ lực cân bằng sự nghiệp, các mối quan hệ và bản ngã của chính mình.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 12, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Hạo Minh","avatar":""},{"name":"Tạ Trạch Thành","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["萌萌哒一家"]', 1784690324128);
