INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-tam-bo-tam-su', 'Bẫy Tâm (Bộ Tâm Sư)', 'Soul Seizer', 'https://phimimg.com/upload/vod/20260310-1/2b82eaeff56a1e2da21296f7c0852fa5.jpg', 'https://phimimg.com/upload/vod/20260310-1/55a7effe8f421752f4e3e4c8c3948301.jpg', '<p>Câu chuyện bắt đầu bằng một vụ tai nạn giao thông kinh hoàng: Cao Cách Phi — Phó Viện trưởng Bệnh viện Đại học Y Hạ Giang — lái xe gây tai nạn khiến 3 người chết và 2 người bị thương. Gia đình và luật sư bào chữa của ông ta tìm cách thoát tội bằng bản giám định tư pháp cho rằng ông ta bị &#39;Rối loạn tâm thần thoáng qua cấp tính&#39;, gây nên làn sóng phẫn nộ trong dư luận.&nbsp; Luật sư ưu tú Du Ngư mượn vụ án này để khẳng định danh tiếng, trong khi phóng viên Lâm Đạt ra sức thúc đẩy dư luận tìm lại công bằng. Bác sĩ tâm lý Du Mặc Hàn tham gia vào quá trình giám định, nhưng kinh hoàng phát hiện ra vụ án này có những điểm trùng hợp kỳ quái với vụ án kẻ sát nhân tâm thần thoát tội từng sát hại người yêu mình 5 năm trước.&nbsp; Cuộc điều tra dần hé lộ những góc khuất đen tối trong giới y tế Hạ Giang: những giao dịch quyền - tiền, quyền - sắc đan xen. Một vụ tai nạn y tế nghiêm trọng bị che đậy có liên quan trực tiếp đến con đường thăng tiến bất thường của Cao Cách Phi, chỉ ra một mạng lưới lợi ích được đan cài tinh vi. Đứng trước sức ép của quyền lực, đạo đức nghề nghiệp và lương tri, mỗi nhân vật đều phải đứng trước ngã rẽ của sự lựa chọn. Cuối cùng, khi chuỗi chứng cứ xuyên thủng màn đêm, sự thật phơi bày rằng bi kịch này tuyệt đối không phải ngẫu nhiên.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 9, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hùng Hiền Đạt","avatar":""},{"name":"Trần Tế Hành","avatar":""},{"name":"Thái Vân Hồng","avatar":""},{"name":"Trương Tuyết","avatar":""},{"name":"Tài Ngạn Hùng","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bu Xin Shi","捕心师"]', 1784690324128);
