INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-trai-phan-2', 'Bạn Trai (Phần 2)', 'The Boyfriend (Season 2)', 'https://phimimg.com/upload/vod/20260116-1/d3e68fd6aa5ced94f25fe5465379df51.jpg', 'https://phimimg.com/upload/vod/20260116-1/41e9ccf5ac527c4cf9c063624d7c49ea.jpg', '<p>Các chàng trai đến ngôi nhà nhỏ ven biển rồi chia sẻ những ấn tượng đầu tiên. Khi tình cảm nảy sinh và một gương mặt mới khiến mọi chuyện nóng lên, một mùa hè khó quên bắt đầu.</p>', 'Hoàn Tất (15/15)', 15, 'tvshows', 'completed', 17, 2026, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"MEGUMI","avatar":""},{"name":"Chiaki Horan","avatar":""},{"name":"Thelma Aoyama","avatar":""},{"name":"Durian Lollobrigida","avatar":""},{"name":"Yoshimi Tokui","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["รถกาแฟเร่หารัก","夏日咖啡男友","ボーイフレンド"]', 1784690324128);
