INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-bong-da-giao-hang', 'Vua Bóng Đá Giao Hàng', 'Rack ''n'' Roll Delivery', 'https://phimimg.com/upload/vod/20260309-1/eeda2bd6228f192579c6916601b1cc6c.jpg', 'https://phimimg.com/upload/vod/20260309-1/c69a2375267eed811d896c7e9b9f8690.jpg', '<p>Từng là thiên tài snooker bách chiến bách thắng, Trình Dã bị hãm hại trong một trận đấu dẫn đến cái chết oan khuất của bạn gái, rồi biến mất khỏi làng bi-a suốt mười năm. Nay sống dưới thân phận nhân viên giao hàng “Hắc Bát”, anh vô tình phát hiện những bí ẩn chưa được làm sáng tỏ năm xưa, buộc phải quay lại đấu trường để truy tìm sự thật.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Kim Hiền Chính","avatar":""},{"name":"Mạnh Lộ","avatar":""},{"name":"Tăng Hi Đường","avatar":""},{"name":"Dư Dật Lôi","avatar":""},{"name":"Nhung Uy Phong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wai Mai Qiu Huang","外卖球皇"]', 1784690324128);
