INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-dau-2026', 'Tình Đầu', 'First Love', 'https://phimimg.com/upload/vod/20260309-1/d551045bc11ca0c90288e0232f356aea.jpg', 'https://phimimg.com/upload/vod/20260309-1/a1320258cc6397a79c5c5078efec1471.jpg', '<p>Ava, một nữ KOL người Thái Lan đang có chuyến du lịch kết hợp làm việc tại đảo Koh Samui, đã vô tình gặp gỡ Ethan – một blogger du lịch người Trung Quốc ngay trên bờ biển. Từ những hành động vô tình ban đầu, cả hai dần trở nên thân thiết hơn thông qua những chuyến hành trình trải nghiệm, cùng nhau chụp ảnh và chia sẻ về những quan điểm sống khác biệt. Tuy nhiên, mối quan hệ của họ không hề trải đầy hoa hồng; họ phải đối mặt với những do dự, lo âu về khoảng cách địa lý và đặc biệt là sự phản đối gay gắt từ phía gia đình. Liệu tình yêu của họ có đủ lớn để vượt qua những rào cản đó?</p>', 'Hoàn Tất (3/3)', 0, 'series', 'completed', 18, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Nunnicha Saehuang","avatar":""},{"name":"Lý Bác","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324128);
