INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kho-lanh-chet-choc', 'Kho Lạnh Chết Chóc', 'Cold Storage', 'https://phimimg.com/upload/vod/20260309-1/f82a6ef402f94d36946330ca7cdd2987.jpg', 'https://phimimg.com/upload/vod/20260309-1/a11a6f97fcd9e5f9f214706451a7fa18.jpg', '<p>Khi một loại nấm biến dị cực kỳ nguy hiểm và có khả năng lây lan nhanh thoát khỏi một cơ sở niêm phong, hai nhân viên trẻ tuổi — cùng với một đặc vụ chống khủng bố sinh học dày dạn — buộc phải sống sót qua ca trực đêm điên rồ nhất trong đời. Giữa hỗn loạn, lây nhiễm và thời gian cạn dần, họ phải ngăn chặn thảm họa trước khi nhân loại đứng trước bờ vực tuyệt chủng.</p>', 'Full', 1, 'single', 'completed', 12, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Anh', 0, '[{"name":"Joe Keery","avatar":""},{"name":"Georgina Campbell","avatar":""},{"name":"Liam Neeson","avatar":""},{"name":"Lesley Manville","avatar":""},{"name":"Sosie Bacon","avatar":""},{"name":"Aaron Heffernan","avatar":""},{"name":"Andrew Brooke","avatar":""},{"name":"Rob Collins","avatar":""},{"name":"Darrell D''Silva","avatar":""},{"name":"Clare Holman","avatar":""},{"name":"Vanessa Redgrave","avatar":""},{"name":"Richard Brake","avatar":""},{"name":"Ellora Torchia","avatar":""},{"name":"Justin Salinger","avatar":""},{"name":"Gavin Spokes","avatar":""},{"name":"Lujza Richter","avatar":""},{"name":"Nahel","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Alerta Extinción","Sērga","Cold Storage"]', 1784690324128);
