INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-nghe-tieng-gio-dai-ngan-nghe-tieng-gio-hoang-da', 'Đi Nghe Tiếng Gió Đại Ngàn (Nghe Tiếng Gió Hoang Dã)', 'Dreams Never End', 'https://phimimg.com/upload/vod/20260309-1/ae5e40bee0d5c638efda1493a8c82751.jpg', 'https://phimimg.com/upload/vod/20260309-1/da2c358578302033c9070bd3d2833fb3.jpg', '<p>Lưu Mã, một nhạc sĩ đang chật vật với sự nghiệp, lên đường tới Lâm Thương, Vân Nam để đòi một món nợ. Thế nhưng, tại đây anh lại vô tình bị cuốn vào cuộc sống của những người dân địa phương chân thành và yêu âm nhạc nồng nhiệt. Khi mối gắn kết giữa họ dần sâu đậm và Lưu Mã cùng họ tham gia vào một cuộc thi âm nhạc đầy kịch tính, hành trình chung này đã buộc anh phải đối mặt với nỗi thất vọng và sự vỡ mộng của chính bản thân mình.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Gia Nguyên","avatar":""},{"name":"Lý Trạch Vũ","avatar":""},{"name":"Lữ Dịch Hào","avatar":""},{"name":"Tạ Văn Địch","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Qu Ting Kuang Ye De Feng","去听旷野的风"]', 1784690324128);
