INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-vu-chi-tam', 'Mê Vụ Chi Tâm', 'Misty Hearts', 'https://phimimg.com/upload/vod/20260309-1/443dead79b02918b09cc643af17ecff8.jpg', 'https://phimimg.com/upload/vod/20260309-1/da1d871c7a6ecb83bb95df06a220075a.jpg', '<p>Nàng họa sĩ truyện tranh Mỹ Lâm đang dần đánh mất niềm đam mê sáng tác, cô quyết định tìm đến tỉnh Phayao với hy vọng tìm lại nguồn cảm hứng mới. Tại đây, cô đã gặp Nilan, một quản lý khách sạn điềm đạm, ít nói nhưng lại sở hữu một tâm hồn nghệ thuật sâu sắc.&nbsp; Bắt đầu từ những hiểu lầm nhỏ nhặt ngay ngày đầu tiên gặp gỡ, cả hai dần xích lại gần nhau hơn thông qua những chuyến hành trình, niềm đam mê nghệ thuật, sự giao hòa với thiên nhiên và cả những cuộc trò chuyện chân thành. Từ đó, họ bắt đầu thấu hiểu và mở lòng với đối phương.</p><p><br/></p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 17, 2026, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Chatchawit Techarukpong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["หัวใจในสายหมอก"]', 1784690324128);
