INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('keo-ngot-2026', 'Kẹo Ngọt', 'Candy', 'https://phimimg.com/upload/vod/20260118-1/631442b8d378a2ce456422f6334f564b.jpg', 'https://phimimg.com/upload/vod/20260118-1/06895f495bf771e767d7c332e929e67f.jpg', '<p>Trong giới giải trí đầy giả tạo, nữ minh tinh Lâm Xán rơi xuống đáy vì khủng hoảng truyền thông và tái ngộ Ôn Noãn Noãn — mối tình bị lãng quên thời thanh xuân — nay trở lại với vai trò trợ lý. Cùng nhau rời xa thành phố giữa bão dư luận, họ dần tìm lại tình yêu chân thật. Song song đó, mối quan hệ đầy giằng xé giữa quản lý Tư Hàn và ngôi sao Giang Vãn phơi bày cuộc đấu giữa tình cảm và quyền lực trong showbiz khắc nghiệt.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 17, 2026, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Lu Xin","avatar":""},{"name":"Sun Yanqing","avatar":""},{"name":"Ke Xin","avatar":""},{"name":"Zhang Ruiyi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Candy","糖果"]', 1784690324128);
