INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieng-coi-tu-than', 'Tiếng Còi Tử Thần', 'Whistle', 'https://phimimg.com/upload/vod/20260308-1/38e8259cbe0fadd83efb9a4e20ff3697.jpg', 'https://phimimg.com/upload/vod/20260308-1/7335f20352d30476bb26febf6f07569a.jpg', '<p>Một nhóm học sinh trung học lạc lõng tình cờ phát hiện một chiếc còi tử thần cổ xưa của người Aztec. Họ sớm nhận ra rằng mỗi khi thổi chiếc còi này, âm thanh kinh hoàng phát ra sẽ triệu hồi chính cái chết trong tương lai của họ quay lại săn lùng. Khi số người thiệt mạng ngày càng tăng, cả nhóm buộc phải lần theo nguồn gốc của di vật chết chóc ấy, trong nỗ lực tuyệt vọng nhằm chấm dứt chuỗi sự kiện kinh hoàng mà chính họ đã vô tình khởi động.</p>', 'Full', 1, 'single', 'completed', 17, 2026, 'Vietsub', 'FHD', 'Ireland', 0, '[{"name":"Dafne Keen","avatar":""},{"name":"Sophie Nélisse","avatar":""},{"name":"Sky Yang","avatar":""},{"name":"Jhaleil Swaby","avatar":""},{"name":"Alissa Skovbye","avatar":""},{"name":"Percy Hynes White","avatar":""},{"name":"Michelle Fairley","avatar":""},{"name":"Nick Frost","avatar":""},{"name":"Janaya Stephens","avatar":""},{"name":"Lanette Ware","avatar":""},{"name":"Mika Amonsen","avatar":""},{"name":"Stephen Kalyn","avatar":""},{"name":"Troy James","avatar":""},{"name":"Cameron Norris","avatar":""},{"name":"Maynuka Sarwar","avatar":""},{"name":"Ruth Chiang","avatar":""},{"name":"Julia Dyan-Porter","avatar":""},{"name":"T","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["O Som da Morte","Le sifflet","Whistle"]', 1784690324128);
