INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-hung-xuat-kich', 'Song Hùng Xuất Kích', 'The Dual Heroes Strike', 'https://phimimg.com/upload/vod/20260308-1/b22044a995072b60f05e57bb09a762f1.jpg', 'https://phimimg.com/upload/vod/20260308-1/617f4aede6e062f2b56744e5e00aadaa.jpg', '<p>Tại nước M ở Đông Nam Á, cảnh sát chìm Ngang Cơ nằm vùng trong một ổ ma túy để điều tra công thức điều chế &quot;Thiên Đường Xanh&quot;. Tại đây anh gặp được Ca Đăng, một lính đặc chủng đã giải ngũ. Vợ của Ca Đăng bị trùm ma túy Khôn Sa sát hại dã man, còn con trai thì bị bắt cóc. Hai người hợp tác vì chính nghĩa và lòng báo thù, cùng xông vào ổ ma túy, giải cứu trẻ em bị bắt cóc, chiến đấu chống lại cảnh sát tay sai và bọn buôn ma túy. Sau nhiều lần vào sinh ra tử, cuối cùng họ cũng đập tan băng đảng của Khôn Sa. Niềm tin trấn áp tội phạm ma túy luôn rực cháy, tình nghĩa anh em luôn sục sôi, thể hiện sức mạnh chính nghĩa cái thiện luôn thắng cái ác.</p>', 'Full', 1, 'single', 'completed', 9, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Huy","avatar":""},{"name":"Lý Bác","avatar":""},{"name":"Trương Vĩnh Hoa","avatar":""},{"name":"Chu Thành Vân","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Double Hero Strike","Double Heroes Strike Back","双雄出击"]', 1784690324128);
