INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('song-hung-xuat-kich', 'Song Hùng Xuất Kích', 'The Dual Heroes Strike', 'song hùng xuất kích the dual heroes strike vương huy lý bác trương vĩnh hoa chu thành vân double hero strike double heroes strike back 双雄出击', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-the-nhan-nhin', 'Không Thể Nhẫn Nhịn', 'The Unforgiven', 'https://phimimg.com/upload/vod/20260308-1/6f36d84f27e1c9e9805e1e853421520f.jpg', 'https://phimimg.com/upload/vod/20260308-1/ce1123b3e8af82e0606a76dc52a1dff8.jpg', '<p>Trương Chấn từng vì một phút bốc đồng gây thương tích trong một trận thi đấu mà phải ngồi tù. Sau khi mãn hạn tù, anh quyết tâm làm lại cuộc đời, cùng bạn gái kinh doanh nhỏ và thề sẽ không bao giờ đụng đến găng đấm bốc nữa. Tuy nhiên, Vương Học Văn – anh trai của Vương Học Võ (người từng bị Trương Chấn đánh trọng thương năm xưa) – khi biết tin Trương Chấn ra tù đã quyết định đòi lại công đạo cho em trai. Hắn liên tục bày trò khiêu khích, nhục mạ Trương Chấn. Dẫu vậy, Trương Chấn vẫn nhẫn nhịn hết lần này đến lần khác với hy vọng giữ được cuộc sống bình yên. Mọi chuyện đẩy lên đỉnh điểm khi Vương Học Văn bắt cóc bạn gái của anh. Không còn đường lui, Trương Chấn buộc phải phá vỡ lời thề, một lần nữa tung nắm đấm để bảo vệ những người mình yêu thương nhất.</p>', 'Full', 1, 'single', 'completed', 11, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yên Tử Luân","avatar":""},{"name":"Hoàng Tử Quân","avatar":""},{"name":"A Nặc","avatar":""},{"name":"Từ Gia Châu","avatar":""},{"name":"Trịnh Húc Đào","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["忍无可忍"]', 1784690324128);
