INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-chien-van-menh', 'Đại Chiến Vận Mệnh', 'Battle Of Fates', 'https://phimimg.com/upload/vod/20260227-1/624088b5f00aaac1ceef03c021109c31.jpg', 'https://phimimg.com/upload/vod/20260227-1/012b0b6ec3011efdac8f32c5c2e81d37.jpg', '<p>Liệu số phận của chúng ta đã được định trước? Và liệu có ai thực sự có thể đọc được nó? Một cuộc thi đột phá dám tìm ra câu trả lời. 49 chuyên gia đọc vận mệnh hàng đầu Hàn Quốc – những bậc thầy về pháp sư, bói toán, bài tarot và xem tướng mặt – sẽ đặt danh dự của mình vào cuộc thi. Chỉ những người thực sự có thể đọc được vận mệnh mới sống sót. Ai sẽ là người chiến thắng?</p>', 'Hoàn Tất (10/10)', 10, 'tvshows', 'completed', 17, 2026, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jeon Hyun-moo","avatar":""},{"name":"Park Na-rae","avatar":""},{"name":"Park Ha-seon","avatar":""},{"name":"Shindong","avatar":""},{"name":"Kang Ji-young","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Unmyeong Jeonjaeng 49","Battle of Fates","운명전쟁49"]', 1784690324129);
