INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-vo-tran-chan-to-gioi-phong-van', 'Tinh Võ Trần Chân: Tô Giới Phong Vân', 'Fist of Fury: The Winds of Jingwu', 'https://phimimg.com/upload/vod/20260307-1/391472254f8913fcaca68b1703727923.jpg', 'https://phimimg.com/upload/vod/20260307-1/df756c8248825dd04564ec2e9eca4cc2.jpg', '<p>Năm 1911, sau khi trả thù cho sư phụ Hoắc Nguyên Giáp, Trần Chân tham gia cách mạng, gia nhập Trung Quốc Đồng Minh Hội. Anh được giao nhiệm vụ điều tra việc quân phiệt thông đồng với Nhật ở tô giới Thiên Tân. Trong một lần làm nhiệm vụ bị phục kích, các đồng đội thì bị trúng độc, Trần Chân và người quân nhân từng đối đầu với mình là Trịnh Thiệu Viễn đã bắt tay hợp tác, cuối cùng Trần Chân quyết đấu một trận sinh tử với thủ lĩnh gián điệp Nhật Bản ở tô giới, vạch trần âm mưu và lôi ra ánh sáng.</p>', 'Full', 1, 'single', 'completed', 8, 2026, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Danny Chan Kwok-Kwan","avatar":""},{"name":"Lu Yanbei","avatar":""},{"name":"Wang Hongzhe","avatar":""},{"name":"Ma Qunxiong","avatar":""},{"name":"Zhang Shuyang","avatar":""},{"name":"Sun Yingyi","avatar":""},{"name":"张永华","avatar":""},{"name":"阿诺","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["The Winds of Jingwu","Fist of Fury: Storm in the Concession","精武陈真：租界风云"]', 1784690324129);
