INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-dam-dinh-menh-hoi-ket', 'Một Dặm Định Mệnh: Hồi Kết', 'One Mile: Chapter Two', 'https://phimimg.com/upload/vod/20260307-1/84b391aada4c9c6e72be79775d6ec603.jpg', 'https://phimimg.com/upload/vod/20260307-1/8267ccb4968b34c7c37542bcd3268cfc.jpg', '<p>Cựu đặc nhiệm Danny bị buộc phải quay trở lại một hòn đảo hẻo lánh khi một cộng đồng bí mật và bạo lực trả thù bằng cách bắt cóc con gái anh, Alex, từ đó khởi đầu một cuộc truy đuổi không ngừng nghỉ chống lại kẻ thù luôn sẵn sàng cho mọi hành động của anh.</p>', 'Full', 1, 'single', 'completed', 11, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ryan Phillippe","avatar":""},{"name":"Amélie Hoeferle","avatar":""},{"name":"Sara Canning","avatar":""},{"name":"Sage Linder","avatar":""},{"name":"Beverley Elliott","avatar":""},{"name":"Phil Burke","avatar":""},{"name":"Gabrielle Jacinto","avatar":""},{"name":"C. Thomas Howell","avatar":""},{"name":"Keana Velsen","avatar":""},{"name":"Garfield Wilson","avatar":""},{"name":"Simon Chin","avatar":""},{"name":"Jude Wilson","avatar":""},{"name":"William Wilder","avatar":""},{"name":"Loreen Regnander","avatar":""},{"name":"Jonathan Whitesell","avatar":""},{"name":"Parveen Dosanjh","avatar":""},{"name":"E","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["One More Mile","Un Mille: Chapitre 2","One Mile: Chapter Two"]', 1784690324129);
