INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ban-trai-theo-yeu-cau', 'Bạn Trai Theo Yêu Cầu', 'Boyfriend On Demand', 'bạn trai theo yêu cầu boyfriend on demand jisoo seo in-guk gong min-jeung lee hak-ju ahn ha-young cho han-cheul han ga-eul 月刊男友 novio a la carta un novio por suscripción бойфренд по запросу 월간남친', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-nhan-kiet-phu-do-thong-thien', 'Địch Nhân Kiệt: Phù Đồ Thông Thiên', 'Detective Dee: Buddha''s Wrath', 'https://phimimg.com/upload/vod/20260307-1/da358f9c2d383c862bbdad13201d2643.jpg', 'https://phimimg.com/upload/vod/20260307-1/541178d4498ac65e10807da8031b001d.jpg', '<p>Vào những năm đầu đời Đường, tàn tích của tòa Phù Đồ Thông Thiên từng sụp đổ tại thao trường ngoại ô bỗng sống dậy như có linh hồn chỉ sau một đêm. Một con rồng lửa xuất hiện trên bầu trời, thắp sáng màn đêm và phun ra những quả cầu lửa thiêu rụi toàn bộ thao trường, khiến vô số người thương vong. Ngay sau đó, Phù Đồ Thông Thiên cũng bốc cháy dữ dội, hóa thành tro bụi. Cùng lúc ấy, dị tộc theo tà đạo huyên náo ngoài thành, tuyên bố rằng chỉ khi Võ Tắc Thiên noi theo Đức Phật tự thiêu thì thiên hạ mới thoát khỏi tai họa. Trong ngoài thành mọi người đều hoang mang. Địch Nhân Kiệt phụng mệnh điều tra vụ án nhưng lại gặp phải thiếu khanh Đại Lý Tự vốn có hiềm khích với mình Bùi Đông Thăng. Cả hai không đánh không quen, bất đắc dĩ phải cùng nhau phá án. Đối diện với sự xâm lăng của kẻ thù và sự nghi kỵ của đồng đội, Địch Nhân Kiệt quyết liều một phen sống mái, thế sẽ điều tra ra chân tướng vụ án.</p>', 'Full', 1, 'single', 'completed', 16, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"La Lập Quần","avatar":""},{"name":"Từ Tường","avatar":""},{"name":"Trương Uyển Lâm","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Di Renjie''s Tongtian Pagoda","Di Ren Jie Zhi Tong Tian Fu Tu","狄仁杰之通天浮屠"]', 1784690324129);
