INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-xuan-tro-lai', 'Thanh Xuân Trở Lại', 'Young Again', 'https://phimimg.com/upload/vod/20260215-1/23d44adf2cdbd99c99e50af62b850ce0.jpg', 'https://phimimg.com/upload/vod/20260215-1/7b8105c8032deb03eac6515b21f70bb0.jpg', '<p>Sáu sinh viên đại học với tính cách hoàn toàn trái ngược đã đến thực tập tại cộng đồng dưỡng lão. Qua sự tiếp xúc gần gũi và những điều tai nghe mắt thấy tại đây, họ đã xóa bỏ được những định kiến ban đầu và thấu hiểu chân thực về cuộc sống của người cao tuổi. Họ ngỡ ngàng nhận ra rằng, các cụ vẫn căng tràn sức sống thanh xuân với những tư tưởng mới mẻ, vốn sống phong phú dày dặn, và cả những nét tinh nghịch, hóm hỉnh như trẻ nhỏ. Kỳ thực tập ngắn ngủi trong một học kỳ đã thay đổi hoàn toàn cách nhìn của nhóm sinh viên, biến họ trở thành những &quot;người bạn vong niên&quot; thân thiết của các ông bà trong cộng đồng dưỡng lão.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 9, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Thành Nho","avatar":""},{"name":"Hứa Đệ","avatar":""},{"name":"Thái Minh","avatar":""},{"name":"Phạm Minh","avatar":""},{"name":"Lương Thiên","avatar":""},{"name":"Trương Hồng Minh","avatar":""},{"name":"Lưu Đồng","avatar":""},{"name":"Lý Lộ","avatar":""},{"name":"Hồ Bạch","avatar":""},{"name":"Triệu Tịch Lâm","avatar":""},{"name":"Trương Văn Tinh Vũ","avatar":""},{"name":"Mã Hách","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Young Again","We Are Still Young","重返青春"]', 1784690324129);
