INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thanh-xuan-tro-lai', 'Thanh Xuân Trở Lại', 'Young Again', 'thanh xuân trở lại young again lý thành nho hứa đệ thái minh phạm minh lương thiên trương hồng minh lưu đồng lý lộ hồ bạch triệu tịch lâm trương văn tinh vũ mã hách young again we are still young 重返青春', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nien-phao-hoa-nam-thang-huu-tinh', 'Thiếu Niên Pháo Hoa (Năm Tháng Hữu Tình)', 'Our Dazzling Days', 'https://phimimg.com/upload/vod/20260221-1/9b37668a2e05de35ee6728bd87e73695.jpg', 'https://phimimg.com/upload/vod/20260221-1/4d566e61d1eafca7eccce2501cb7999c.jpg', '<p>Tại một nhà máy quân dụng ở Thiết Thành những năm 1990, nhóm bạn Tiểu Mãn, Hạ Lôi và Nghiêm Hiểu Đan lớn lên cùng nhau trong khu tập thể công nhân, trải qua tuổi thơ rực rỡ. Khi thời cuộc thay đổi, nhà máy suy tàn, mỗi người buộc phải rẽ hướng: người sang Nhật mưu sinh, kẻ bươn chải nơi đô thị lớn. Đầu thế kỷ 21, nhà máy sụp đổ, hàng vạn người ly tán. Ba người bạn trở về quê hương, mang theo khát vọng và tri thức, cùng nhau hồi sinh nhà máy cũ. Đối đầu với thế lực địa phương, họ kiên cường gìn giữ tinh thần “con em nhà máy”, viết tiếp câu chuyện dựng xây quê hương của những con người bình dị trong thời đại mới.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hoàng Cảnh Du","avatar":""},{"name":"Quan Hiểu Đồng","avatar":""},{"name":"Từ Nhược Hàm","avatar":""},{"name":"Vương Thiên Thần","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["烟花与少年","子弟","烟花少年","岁月有情时"]', 1784690324129);
