INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-toi-la-hoa-khoi', 'Mẹ Tôi Là Hoa Khôi', 'Mama Go!', 'https://phimimg.com/upload/vod/20260216-1/87bbfafdd06ca8a8630aff0897d8e349.jpg', 'https://phimimg.com/upload/vod/20260216-1/edd459010eabd53533c2b85a07abb298.jpg', '<p>&quot;Mẹ Tôi Là Hoa Khôi&quot; kể về cậu sinh viên Khổng Tiểu Xán. Sau khi biết tin mẹ mình là Khổng Quế Phương mắc bệnh nan y, cậu đã thực hiện một giao dịch hoán đổi &quot;năng lượng sinh mệnh&quot;, giúp người mẹ 45 tuổi lấy lại vẻ ngoài trẻ trung như tuổi 20 và bắt đầu ra một hành trình cuộc đời mới. Đây là một hành trình kỳ diệu, nơi Khổng Quế Phương cùng con trai và những người bạn trẻ tuổi cùng nhau trưởng thành, để bà lột xác trở thành một người hoàn toàn mới.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 18, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đặng Ân Hi","avatar":""},{"name":"Tưởng Long","avatar":""},{"name":"Lưu Lâm","avatar":""},{"name":"Lưu Tá Ninh","avatar":""},{"name":"Tả Lâm Kiệt","avatar":""},{"name":"Hứa Huệ Cường","avatar":""},{"name":"Mã Phàm Đinh","avatar":""},{"name":"Thổ Đậu","avatar":""},{"name":"Phương Viên Viên","avatar":""},{"name":"Chước Nhất","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["我的妈妈是校花"]', 1784690324129);
