INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('me-toi-la-hoa-khoi', 'Mẹ Tôi Là Hoa Khôi', 'Mama Go!', 'mẹ tôi là hoa khôi mama go! đặng ân hi tưởng long lưu lâm lưu tá ninh tả lâm kiệt hứa huệ cường mã phàm đinh thổ đậu phương viên viên chước nhất 我的妈妈是校花', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-cung-ky-an-thanh-vu-phong-minh', 'Đường Cung Kỳ Án: Thanh Vụ Phong Minh', 'Unveil: Jadewind', 'https://phimimg.com/upload/vod/20260205-1/a3cf3375b958f71bfeed0ac302b76bc9.jpg', 'https://phimimg.com/upload/vod/20260205-1/365d6e501c0e0d6263f51b0225429670.jpg', '<p>Vào tiết Nguyên Tiêu, công chúa Ninh Viễn chết một cách ly kỳ trong dạ yến, Lý Bội Nghi của Nội Yết Cục và Thái Sử thừa Tiêu Hoài Cẩn của Thái Sử Cục phụng mệnh điều tra. Lý Bội Nghi võ nghệ cao cường lại giỏi nhìn thấu lòng người, vẻ ngoài lạnh lùng nhưng tâm địa lương thiện, một lòng truy tìm chân tướng. Với cô, phá án không chỉ là truy tìm sự thật mà còn là cuộc đấu trí so tài với hung thủ. Dưới sự phối hợp ăn ý với Tiêu Hoài Cẩn tư duy kín kẽ, họ từng bước bóc tách sự thật, thông qua cô gái quyền quý hống hách và Vũ Lâm Lang Tướng Kim Ngô Vệ mang trong mình bí mật, cuối cùng đã điều tra ra chân tướng, tìm được hung thủ. Sau đó, hàng loạt bí mật thâm cung và các vụ án kỳ lạ phức tạp liên tiếp xảy ra trong nội đình Đại Đường. &quot;Hoa trên tường đá&quot;, &quot;Huyết Sắc Thiên Tư&quot;, &quot;Lời đồn bí mật giờ lành&quot;, &quot;Thất Tinh Thác&quot; và nhiều vụ án khác liên quan đến số phận của nữ tử hậu cung.</p>', 'Hoàn Tất (34/34)', 34, 'series', 'completed', 19, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Bạch Lộc","avatar":""},{"name":"Vương Tinh Việt","avatar":""},{"name":"Diêu An Na","avatar":""},{"name":"Triệu Thanh","avatar":""},{"name":"Triệu Diệp Cầm","avatar":""},{"name":"Trương Vĩ Na","avatar":""},{"name":"Đái Lộ Oa","avatar":""},{"name":"Lâm Ninh","avatar":""},{"name":"Lý Tĩnh Nham","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Os Segredos do Palácio Tang","Tang Gong Qi An Zhi Qing Wu Feng Ming","당궁기안지청무풍명","Unveil: Jadewind","唐宫奇案之青雾风鸣"]', 1784690324129);
