INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-he-nhung-nam-80', 'Mùa Hè Những Năm 80', 'A Summer Meant For Us', 'https://phimimg.com/upload/vod/20260215-1/05e557ffd5c823bf5451d40b94b4731d.jpg', 'https://phimimg.com/upload/vod/20260215-1/3334ac0ee9d8b61df22f743188b54d81.jpg', '<p>Nhà họ Trịnh và nhà họ Vương vốn đã có mối hiềm khích từ trước. Thế nhưng, vào cuối mùa hạ những năm 80, một biến cố tình cờ lại khiến vận mệnh của hai gia đình lần nữa đan xen. Sau khi bị mất việc ở nhà máy, con gái thứ nhà họ Vương, Vương Ánh Dung lâm vào cảnh lao đao: nuôi lợn thất bại, khởi nghiệp làm giấm cũng không suôn sẻ. Trên suốt chặng đường gian nan ấy, cô luôn nhận được sự giúp đỡ âm thầm từ con trai cả nhà họ Trịnh là Trịnh Mân Giang. Lửa gần rơm lâu ngày cũng bén, giữa họ dần nảy sinh tình cảm sâu đậm. Cuối cùng, những khúc mắc giữa hai gia đình được hóa giải. Mối thâm thù năm xưa khép lại, nhường chỗ cho ngày vui khi hai nhà kết thành thông gia.</p>', 'Tập 30', 30, 'series', 'ongoing', 20, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Khương Chi Nam","avatar":""},{"name":"Vương Hạo Trinh","avatar":""},{"name":"Cẩm Lang","avatar":""},{"name":"Vương Tuấn Triết","avatar":""},{"name":"Dương Hân Nhiên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Er Ba Gang De Xia Tian","二八杠的夏天"]', 1784690324129);
