INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tham-hoa-thien-thach-di-tan', 'Thảm Họa Thiên Thạch: Di Tản', 'Greenland 2: Migration', 'thảm họa thiên thạch: di tản greenland 2: migration gerard butler morena baccarin roman griffin davis tommie earl jenkins trond fausa aurvåg amber rose revah gina gangar antonio de lima peter polycarpou beruce khan megan jacobs shrivastava mitu panicucci gísli örn garðarsson sidsel siem koch greenland 2 thảm họa địa cầu 2 ґренландія: міграція el día del fin del mundo: migración גרינלנד 2: בתנועה greenland: migration greenland 2: útěk greenland 2 migration greenland 2 - migration غرينلاند ٢: الهجرة greenland 2: migration', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-nguyen-trung-co', 'Lời Nguyền Trung Cổ', 'The Dreadful', 'https://phimimg.com/upload/vod/20260303-1/139c8410f2bee996958482cb2141de7c.jpg', 'https://phimimg.com/upload/vod/20260303-1/49b0616017ae1b2e3b56290ba76a5393.jpg', '<p>Giữa nước Anh thời Trung Cổ, trong một ngôi làng nhỏ bị lãng quên giữa rừng sương mù, Anne (Sophie Turner) và mẹ chồng Morwen (Marcia Gay Harden) sống lặng lẽ bên rìa xã hội, bị dân làng xa lánh vì những lời đồn về tà thuật. Khi Thomas (Kit Harington) – người đàn ông từng biến mất trong chiến tranh – bất ngờ trở về, không khí trong làng bắt đầu chuyển lạnh lẽo lạ thường. Một hiệp sĩ bí ẩn xuất hiện vào những đêm trăng, và cùng với hắn là những cái chết kỳ lạ, những vết dấu không thể lý giải. Càng cố tìm nguyên nhân, Anne càng nhận ra có một lời nguyền cổ xưa đang trỗi dậy, gắn chặt máu thịt của cô với tội lỗi mà cả ngôi làng đã chôn vùi hàng thế kỷ trước. Khi màn sương cuối cùng tan, câu hỏi duy nhất còn lại là: ai mới thật sự bị nguyền rủa?</p>', 'Full', 1, 'single', 'completed', 12, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sophie Turner","avatar":""},{"name":"Kit Harington","avatar":""},{"name":"Marcia Gay Harden","avatar":""},{"name":"Laurence O''Fuarain","avatar":""},{"name":"Jonathan Howard","avatar":""},{"name":"Catherine McDonough","avatar":""},{"name":"Zachary Cohen","avatar":""},{"name":"Isidro-Lucking Dylan","avatar":""},{"name":"Nik Harber","avatar":""},{"name":"Jürgen Koenen","avatar":""},{"name":"Tigerlily Langford","avatar":""},{"name":"Huxley Sheppard","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":