INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tehran-phan-3', 'Tehran (Phần 3)', 'Tehran (Season 3)', 'https://phimimg.com/upload/vod/20260111-1/7e2b010a8793e69aa2e2f81073804a6a.jpg', 'https://phimimg.com/upload/vod/20260111-1/18fecea8fc9e4eebb1b0151a1171c9fe.jpg', '<p>Tamar, điệp viên hacker của Mossad, thâm nhập vào Tehran bằng danh tính giả để giúp phá huỷ lò phản ứng hạt nhân của Iran. Nhưng khi nhiệm vụ của cô thất bại, Tamar phải lên kế hoạch một chiến dịch làm tất cả những người cô yêu quý lâm nguy.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 14, 2026, 'Vietsub', 'FHD', 'Greece', 0, '[{"name":"Niv Sultan","avatar":""},{"name":"Shaun Toub","avatar":""},{"name":"Shervin Alenabi","avatar":""},{"name":"Hugh Laurie","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Tehran","Teherán","Téhéran","Тегеран","טהרן"]', 1784690324129);
