INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-mau', 'Hoa Máu', 'Bloody Flower', 'https://phimimg.com/upload/vod/20260205-1/a5d253401164da7d1fb45b0c4534b168.jpg', 'https://phimimg.com/upload/vod/20260205-1/50a279c9ab6a570c8a60f2b672efc30a.jpg', '<p>Bộ phim kể về Lee U Gyeom, kẻ sát nhân hàng loạt nắm giữ công nghệ y học cứu người. Phim xoay quanh cuộc đấu trí giữa luật sư muốn cứu con và công tố viên đòi công lý. Liệu hắn là tội đồ hay hy vọng cuối cùng? Một tác phẩm tâm lý tội phạm đầy gai góc về đạo đức và sự sống.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 13, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ryeoun","avatar":""},{"name":"Sung Dong-il","avatar":""},{"name":"Keum Sae-rok","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Кърваво цвете","Цветок смерти","الزهرة الدامية","블러디 플라워"]', 1784690324129);
