INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trung-quoc-ky-dam-phan-2', 'Trung Quốc Kỳ Đàm (Phần 2)', 'Yao-Chinese Folktales (Season 2)', 'https://phimimg.com/upload/vod/20260110-1/3b4a9dd7670dd5965fffd56638132a2a.jpg', 'https://phimimg.com/upload/vod/20260110-1/0b4aa3e714bbfc7192347f3f815350da.jpg', '<p>Tuyển tập phim hoạt hình ngắn 《Trung Quốc Kỳ Đàm 2》 gồm 9 phim ngắn với phong cách đa dạng:《Làm thế nào để trở thành Ba con Rồng》, 《Người trong tai》, 《Sở thú hôm nay》, 《Tiểu Tuyết》, 《Tam Lang》, 《Chim lớn》, 《Bái sơn》, 《Hình Thiên》, 《Quý nhân lớn》.12 đạo diễn, trên nền tảng tiếp nối trí tưởng tượng mang đậm màu sắc Trung Hoa, đã khám phá nhiều đề tài và phong cách khác nhau, đào sâu cách biểu đạt nội hàm văn hóa Trung Hoa, đồng thời tăng cường sự quan sát hiện thực và tính ngụ ngôn. Trong bối cảnh kỳ ảo, các tác phẩm tìm kiếm và suy ngẫm về những vấn đề của đời sống thực, như bản sắc cá nhân, quan hệ gia đình và quan hệ xã hội của con người.</p>', 'Tập 9', 9, 'hoathinh', 'ongoing', 11, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Zhong Guo Qi Tan","Yao-Chinese Folktales","中国奇谭.Yao-Chinese.Folktales","Yao Chinese Folktales","中国奇谭2","중국기담(中國奇譚)","Truyện cổ Trung Quốc","中国奇谭"]', 1784690324129);
