INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-bat-hung-thu', 'Truy Bắt Hung Thủ', 'Catch The Killer', 'https://phimimg.com/upload/vod/20260227-1/bdfa4d8ab542c60dfe2c47bbb67ca6f0.jpg', 'https://phimimg.com/upload/vod/20260227-1/e0a14a80457cdb1040f8e35584cb3feb.jpg', '<p>Cục công an nhận được báo án: có người phát hiện hai mảnh thi thể cách nhau chưa đầy ba trăm mét dọc bờ sông. Điều tra hình sự cho thấy hung thủ định cưỡng hiếp Tô Bảo Diễm nhưng lại bị cô vô tình giết chết. Chị gái Tô Mai Diễm cùng bạn trai Cao Hùng đứng ra che chở em, làm nhiều việc tưởng như để bảo vệ Tô Bảo Diễm, nhưng từng bước sai lầm, cuối cùng rơi thẳng vào vực sâu không lối thoát.</p>', 'Full', 1, 'single', 'completed', 11, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Tử Do","avatar":""},{"name":"Trương Vũ Kiếm","avatar":""},{"name":"Lý Mộng","avatar":""},{"name":"Vương Kính Tùng","avatar":""},{"name":"Trương Hạo Nhiên","avatar":""},{"name":"Lưu Hiểu Khiết","avatar":""},{"name":"Triệu Dương","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["追凶行动"]', 1784690324129);
