INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-la-noi-gian', 'Tôi Là Nội Gián', 'I''m Undercover', 'https://phimimg.com/upload/vod/20260227-1/2294aabcacda6da292b8b8b58b0ee4c3.jpg', 'https://phimimg.com/upload/vod/20260227-1/f65e4c60d46cbdc8a666fb4e2343f480.jpg', '<p>Phim xoay quanh hành trình thâm nhập nguy hiểm của một cảnh sát chìm được cài vào tổ chức tội phạm nhằm thu thập chứng cứ triệt phá đường dây tội ác xuyên quốc gia. Trong quá trình làm nội gián, anh phải đối mặt với sự nghi kỵ từ cả hai phía – vừa phải giành được lòng tin của băng nhóm, vừa giữ kín thân phận thật trước những đồng đội ngoài vòng pháp luật.&nbsp; Khi âm mưu và các phi vụ phạm tội ngày càng leo thang, ranh giới giữa chính – tà dần trở nên mong manh, buộc anh phải đưa ra những lựa chọn sinh tử giữa nhiệm vụ và tình người. Cuối cùng, bằng sự mưu trí và lòng dũng cảm, thân phận nội gián được phơi bày, góp phần đưa toàn bộ tổ chức tội phạm ra trước pháp luật.</p>', 'Full', 1, 'single', 'completed', 11, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Châu Triệu Long","avatar":""},{"name":"Vu Vinh Quang","avatar":""},{"name":"Lý Ngạn Khuê","avatar":""},{"name":"Văn Đông Quân","avatar":""},{"name":"Trương Sa Sa","avatar":""},{"name":"Vương Đào","avatar":""},{"name":"Vương Bác Thanh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["I.m.Undercover","我是卧底"]', 1784690324129);
