INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-an-dat', 'Kẻ Ẩn Dật', 'Shelter', 'https://phimimg.com/upload/vod/20260225-1/dd7e9f8cd0896dd30e241bdd6dce9301.jpg', 'https://phimimg.com/upload/vod/20260225-1/32b51c917dc2063444851e999c86e6d7.jpg', '<p>Michael Mason, một cựu sát thủ chính phủ đang sống ẩn dật trên một hòn đảo hẻo lánh tại Scotland, tình cờ cứu mạng một cô bé tên Jessie sau một cơn bão dữ dội. Hành động nghĩa hiệp này vô tình khiến tung tích của anh bị lộ, buộc Mason phải đối đầu với những bóng ma từ quá khứ và các đặc vụ MI6 đang truy đuổi gắt gao. Để bảo vệ đứa trẻ, anh phải từ bỏ cuộc sống yên bình, vận dụng mọi kỹ năng sinh tồn và chiến đấu để thoát khỏi vòng vây của những kẻ thù nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 21, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Jason Statham","avatar":""},{"name":"Bodhi Rae Breathnach","avatar":""},{"name":"Michael Shaeffer","avatar":""},{"name":"Anna Crilly","avatar":""},{"name":"Bill Nighy","avatar":""},{"name":"Harriet Walter","avatar":""},{"name":"Eugenia Caruso","avatar":""},{"name":"Celine Buckens","avatar":""},{"name":"Naomi Ackie","avatar":""},{"name":"Bally Gill","avatar":""},{"name":"Bronson Webb","avatar":""},{"name":"Lohan Buson","avatar":""},{"name":"Bryan Vigier","avatar":""},{"name":"Rodaidh Findlay","avatar":""},{"name":"Ryan Fletcher","avatar":""},{"name":"Tomi May","avatar":""},{"name":"Ansko Pitkänen","avatar":""},{"name":"Dan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["El Guardián Último Refugio","庇护之地","Shelter","Shelter: El protector"]', 1784