INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-quai-vat-phan-2', 'Trò Chơi Quái Vật (Phần 2)', 'Beast Games (Season 2)', 'https://phimimg.com/upload/vod/20260207-1/18dbb99d1bf2125dcbbf249bc4ac1430.jpg', 'https://phimimg.com/upload/vod/20260207-1/73612d41d9c79f09b07a806ac1b8c0eb.jpg', '<p>Tôi đã tập hợp 1.000 người để chiến đấu giành giải thưởng 5.000.000 đô la – giải thưởng tiền mặt LỚN NHẤT trong lịch sử truyền hình! Ngoài ra, chúng tôi còn có một hòn đảo riêng, những chiếc Lamborghini, cùng hàng triệu đô la tiền thưởng dành cho các thí sinh xuyên suốt cuộc thi! Hãy xem ngay để tận mắt chứng kiến chương trình hoành tráng nhất từng có!</p>', 'Hoàn Tất (10/10)', 10, 'tvshows', 'completed', 23, 2026, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jimmy Donaldson","avatar":""},{"name":"Chandler Hallow","avatar":""},{"name":"Karl Jacobs","avatar":""},{"name":"Nolan Hansen","avatar":""},{"name":"Tareq Salameh","avatar":""},{"name":"Mack Hopkins","avatar":""},{"name":"Sean Klitzner","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Beast Games: Forte vs. Esperto","משחקי הביסט","משחקי ביסט","بازی‌های مستر بیست","Игры Мистера Биста","Beast Games: Strong vs Smart","Beast Games: Strong vs. Smart","Beast Games 2: Strong vs Smart","Beast Games"]', 1784690324129);
