INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tro-choi-quai-vat-phan-2', 'Trò Chơi Quái Vật (Phần 2)', 'Beast Games (Season 2)', 'trò chơi quái vật (phần 2) beast games (season 2) jimmy donaldson chandler hallow karl jacobs nolan hansen tareq salameh mack hopkins sean klitzner beast games: forte vs. esperto משחקי הביסט משחקי ביסט بازی‌های مستر بیست игры мистера биста beast games: strong vs smart beast games: strong vs. smart beast games 2: strong vs smart beast games', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-tich-cua-gio', 'Tàn Tích Của Gió', 'The Truth', 'https://phimimg.com/upload/vod/20260205-1/879e5a26ae35ebe359e05caf242f937a.jpg', 'https://phimimg.com/upload/vod/20260205-1/ce3f07950e932fc695b9ac14d217945e.jpg', '<p>Phòng Kỹ thuật Hình sự, Cục Công an thành phố Vân Tịch là nơi tập trung các vụ án lớn và vụ án kỳ lạ. Dưới sự dẫn dắt của đội trưởng Lãnh Khải Minh, tổ điều tra bao gồm Diệp Khiêm, Tư Nguyên Long, Tiêu Lỗi, Trương Tử Vu... đã tạo nên một biệt đội cảnh sát hình sự tinh nhuệ, trẻ trung và chuyên nghiệp. Trong số họ, có người giỏi phân tích, người thì giỏi suy luận và nắm bắt tâm lý; có người giỏi công nghệ, làm chủ mọi thiết bị trinh sát; còn có cảnh sát kỳ cựu túc trí đa mưu, luôn đưa ra những chỉ dẫn then chốt, và cả chàng thanh niên lanh lợi, khéo léo luôn mang lại tiếng cười cho cả đội. Với tôn chỉ &quot;Giải mã mật mã tử thi, bảo vệ phẩm giá sinh mệnh&quot;, mỗi người một thế mạnh, ai nấy đều làm tròn chức trách, liên tiếp phá giải những vụ án lạ lùng, khó tin. Qua từng vụ án, họ nhìn thấu tâm tính con người và ra sức thực thi công lý. Núi cao còn có núi cao hơn, vụ án này lại lồng vào vụ án kia, khi sự thật dần lộ diện cũng là lúc bản chất con người được phơi bày.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 14, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cung Tuấn","avatar":""},{"name":"Khương Võ","avatar":""},{"name":"Tôn Di","avatar":""},{"name":"Vương Tấn","avatar":""},{"name":"Giả Băng","avatar":""},{"name":"Lý Kiến Nghĩa","avatar":""},{"name":"Trương Khai Thái","avatar":""},{"name":"Vương Manh Lê","avatar":""},{"name":"Phùng Huy","avatar":""},{"name":"Lưu Hải Lam","avatar":""},{"name":"Khổng Lâm","avatar":""},{"name":"Vương Nhuận Trạch","avatar":""},{"name":"Sài Tuyển Triết","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["尸案调查科","풍과류흔","Ветер оставляет следы","风过留痕"]', 1784690324129);
