INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-truong-ngoc-nghech', 'Sư Trưởng Ngốc Nghếch', 'The Naive Leader', 'https://phimimg.com/upload/vod/20260225-1/ab0590298f11b65817e399ae2f02b7ef.jpg', 'https://phimimg.com/upload/vod/20260225-1/f61ae757c2f1edc1331db41b1f569d7d.jpg', '<p>Phú thiếu gia Phàn Sỏa Nhi vì cướp kho lương mà bị Phàn lão gia chôn sống, sau đó trốn thoát và lưu lạc mở quán lẩu cùng cha con Tú Cô. Bị Hoắc công tử hãm hại, lại nghe theo sự chỉ dẫn của Huyền Cơ Tử, anh lạc vào băng cướp và dần trở thành thủ lĩnh, lập nên hội huynh đệ hành hiệp trượng nghĩa. Về sau, nhờ tiêu diệt quân Nhật mà được chiêu an, lập chiến công, bài trừ cờ bạc, chỉnh đốn quân kỷ, cuối cùng trưởng thành thành sư trưởng dẫn quân kháng Nhật.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Liêu Kiện","avatar":""},{"name":"Lý Bá Thanh","avatar":""},{"name":"Hướng Điềm","avatar":""},{"name":"Đoàn Hiểu Vy","avatar":""},{"name":"Hoàng Chí Trung","avatar":""},{"name":"Âu Dương Phấn Cường","avatar":""},{"name":"Hoàng Phẩm Nguyên","avatar":""},{"name":"Lưu Á Tân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sha Er Shi Zhang","傻儿师长"]', 1784690324129);
