INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('baby-den-roi', 'Baby Đến Rồi!', 'Positively Yours', 'https://phimimg.com/upload/vod/20260119-1/97353760bbeaf11746aec8cf43222132.jpg', 'https://phimimg.com/upload/vod/20260119-1/d86e4511a783ac1a47f1514cc5e1b7c6.jpg', '<p>Kang Doo Jun - một tài phiệt lạnh lùng và hoàn hảo, thề sẽ không bao giờ kết hôn. Jang Hee Won - một phụ nữ xinh đẹp tập trung vào sự nghiệp, cũng khép kín bản thân với tình yêu. Sau một “tai nạn&quot; bất ngờ, cuộc sống của họ bị đảo lộn, buộc họ phải tìm hiểu cách trở thành cha mẹ. Và con đường không nằm trong kế hoạch này cuối cùng lại dẫn họ đến tình yêu.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 17, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Choi Jin-hyuk","avatar":""},{"name":"Oh Yeon-seo","avatar":""},{"name":"Hong Jong-hyun","avatar":""},{"name":"Kim Da-som","avatar":""},{"name":"Son Byung-ho","avatar":""},{"name":"Kim Sun-kyung","avatar":""},{"name":"Baek Eun-hae","avatar":""},{"name":"Kim Soo-jin","avatar":""},{"name":"Kim Ki-doo","avatar":""},{"name":"Jeong Soo-young","avatar":""},{"name":"Jang Yeo-bin","avatar":""},{"name":"Ryu Tae-ho","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["我有孩子了","宝宝出生了","理事长和我的秘密关系","لك بشكل ايجابي","아기가 생겼어요"]', 1784690324129);
