INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ten-trom-dau-yeu', 'Tên Trộm Dấu Yêu', 'To My Beloved Thief', 'https://phimimg.com/upload/vod/20260105-1/b06c35ac98344554a8a5031bf75c53d5.jpg', 'https://phimimg.com/upload/vod/20260105-1/0adea2e823ede3d6a2bca22d1f0ac286.jpg', '<p>Lấy bối cảnh thời Joseon, phim kể về Hong Eun Jo (Nam Ji Hyun), một cô gái sống cuộc đời “hai mặt”. Ban ngày, cô là một thầy thuốc giỏi, nhưng ban đêm cô trở thành một tên trộm huyền thoại cướp của người giàu chia cho người nghèo. Cuộc sống của cô trở nên phức tạp hơn khi hoàng tử Yi Yeol (Moon Sang Min) nhập vai thám tử điều tra, quyết tâm tìm ra thân phận thật của tên trộm lừng danh.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'ongoing', 22, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Nam Ji-hyun","avatar":""},{"name":"Moon Sang-min","avatar":""},{"name":"Hong Min-gi","avatar":""},{"name":"Han So-eun","avatar":""},{"name":"Kim Suk-hoon","avatar":""},{"name":"Ha Seok-jin","avatar":""},{"name":"Choi Won-young","avatar":""},{"name":"Kim Jung-nan","avatar":""},{"name":"Seo Young-hee","avatar":""},{"name":"Han Ji-hye","avatar":""},{"name":"Lee Jin-hee","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["亲爱的盗贼大人","إلى لصي الحبيب","To My Beloved Thief","은애하는 도적님아"]', 1784690324129);
