INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-bi-bat-coc', 'Cô Gái Bị Bắt Cóc', 'Girl Taken', 'https://phimimg.com/upload/vod/20260215-1/67d01695f09f41e24207b3ff4a97c125.jpg', 'https://phimimg.com/upload/vod/20260215-1/8dfdde245e2c570b7c0f33cb1ff55e01.jpg', '<p>Câu chuyện theo chân hai chị em song sinh Lily và Abby, những người có cuộc sống êm đềm tại một thị trấn nông thôn yên bình ở Anh đã bị xé nát khi Lily bị bắt cóc bởi Rick Hansen — một thầy giáo địa phương vốn rất được lòng mọi người. Sau nhiều năm bị giam cầm và lạm dụng, Lily đã trốn thoát thành công. Tuy nhiên, cô sớm nhận ra rằng tự do cũng mang đến những thử thách nghiệt ngã của riêng nó.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 12, 2026, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Tallulah Evans","avatar":""},{"name":"Delphi Evans","avatar":""},{"name":"Jill Halfpenny","avatar":""},{"name":"Alfie Allen","avatar":""},{"name":"Vikash Bhai","avatar":""},{"name":"Niamh Walsh","avatar":""},{"name":"Levi Brown","avatar":""},{"name":"Victoria Ekanoye","avatar":""},{"name":"Holly Atkins","avatar":""},{"name":"Kiran Krishnakumar","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Vajza e rrëmbyer","Baby Doll","Girl Taken"]', 1784690324129);
