INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuoi-tre-tai-cao', 'Tuổi Trẻ Tài Cao', 'No Pain No Gain', 'https://phimimg.com/upload/vod/20260131-1/09053bd2932d9d5a0f6d201bee4ad1ac.jpg', 'https://phimimg.com/upload/vod/20260131-1/b24912cda8d9fedb73dc49b6c4718207.jpg', '<p>Bùi Khiêm, một nhân viên làm việc tại tập đoàn lớn, vừa bị sa thải thì bất ngờ nhận được lời mời từ một ông trùm bí ẩn để thành lập một công ty với mục tiêu bắt buộc là... phải thua lỗ. Thế là anh tập hợp một đám nhân viên tạp nham, khởi động kế hoạch &quot;đốt tiền&quot; của mình. Anh vắt óc suy nghĩ cách tăng lương, cho nghỉ phép dài hạn, thêm đãi ngộ &quot;trên trời&quot; cho nhân viên và đầu tư vào hàng loạt dự án kỳ quặc. Tuy nhiên, lần nào dự án cũng lội ngược dòng ngoạn mục, thu được lãi lớn. Bùi Khiêm bỗng chốc trở thành &quot;ông chủ quốc dân&quot; trong lòng nhân viên, thiên tài kinh doanh được giới thương nhân công nhận, nhưng trong lòng lại khổ tâm không nói nên lời. Bùi Khiêm đành phải ngậm ngùi nuốt nỗi khổ vì bỗng dưng giàu sụ vào trong, tiếp tục tìm thêm cơ hội khác để &quot;lội ngược dòng&quot;...</p>', 'Tập 26', 26, 'series', 'ongoing', 19, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Bành Dục Sướng","avatar":""},{"name":"Lâm Duẫn","avatar":""},{"name":"Lưu Quán Lân","avatar":""},{"name":"Vương Thiên Phóng","avatar":""},{"name":"Hà Thụy Hiền","avatar":""},{"name":"Ngô Tuấn Đình","avatar":""},{"name":"Diêu Nhất Kỳ","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["亏成首富从游戏开始","Nian Shao You Wei","Kui Cheng Shou Fu Cong You Xi Kai Shi","Нет боли – нет результата","Молодые и перспективные","The Richest Poor Guy","The Poor Winner","NO ΡAΙN NO GAIN","年少有为"]', 1784690324129);
