INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tuoi-tre-tai-cao', 'Tuổi Trẻ Tài Cao', 'No Pain No Gain', 'tuổi trẻ tài cao no pain no gain bành dục sướng lâm duẫn lưu quán lân vương thiên phóng hà thụy hiền ngô tuấn đình diêu nhất kỳ 亏成首富从游戏开始 nian shao you wei kui cheng shou fu cong you xi kai shi нет боли – нет результата молодые и перспективные the richest poor guy the poor winner no ρaιn no gain 年少有为', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phon-hoa-lui-tan', 'Phồn Hoa Lụi Tàn', 'The Glory Fades', 'https://phimimg.com/upload/vod/20260203-1/a8f6795b78547be683886e48c9dd3bb8.jpg', 'https://phimimg.com/upload/vod/20260203-1/3adc8a6d8f07e32c39a1e7781bbf1e63.jpg', '<p>Để điều tra nguyên nhân cái chết của chị gái, Tô Vũ Niệm đã thâm nhập vào &quot;Phồn Hoa Thâm Xứ&quot; – chốn ăn chơi xa hoa trụy lạc, cô vô tình bị cuốn vào cuộc chiến quyền mưu đẫm máu giữa Nhiếp Phong và Đồ Gia Thịnh, đồng thời phát hiện ra chị gái mình bị diệt khẩu vì nắm giữ một bằng chứng chí mạng. Hiểm nguy dồn dập kéo đến: bạn thân phản bội, &quot;đào chính&quot; hãm hại, lại còn bị Nhiếp Phong đưa vào tầm ngắm. Giữa cô và Đồ Gia Thịnh tồn tại mối quan hệ vừa là địch vừa là bạn. Ẩn sâu dưới vẻ hào nhoáng của chốn phồn hoa ấy, tất cả chỉ là những lời dối trá nhuốm máu.</p>', 'Tập 34', 34, 'series', 'ongoing', 19, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Kim Hãn","avatar":""},{"name":"Chu Tuấn Vĩ","avatar":""},{"name":"Lý Gia Nặc","avatar":""},{"name":"Lâm Nhất Đình","avatar":""},{"name":"Vương Tỉ","avatar":""},{"name":"Tiết Vũ Tân","avatar":""},{"name":"Đỗ Diêu","avatar":""},{"name":"Diêm Nhược Châu","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Fan Hua Luo Jin","A Fairyland Beyond the Ordinary World","繁华落尽"]', 1784690324129);
