INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('pavane', 'Pavane', 'Pavane', 'pavane pavane ko a-sung byun yo-han moon sang-min lee e-dam han yu-eun seo yi-ra shin jung-keun park hae-joon lee bong-ryeon lee sang-jin kwon do-kyun jang yo-hoon seo ho-seok byun jin-su park hee-jeong woo jeong-won lim yoon-bi lee da-hye kim hong-ju 죽은 왕녀를 위한 파반느 pavane: for a dead princess jukeun wangnyeoreul wihan pabanneu pavane เมื่อใจบ่มรัก 파반느', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhen-tien', 'Nhện Tiên', 'Spider Fairy', 'https://phimimg.com/upload/vod/20260221-1/a86471e4a2b65214ea5c91afec3c6b5d.jpg', 'https://phimimg.com/upload/vod/20260221-1/6d600cc1a9c6043a1be2b48299a6b1c0.jpg', '<p>Sau một nghìn năm tu luyện, Hàn Phách Thải Chu, Chu Nhi được Phật tổ giác ngộ và hóa thành người, hóa thân thành thợ săn yêu xuống trần gian. Cô cùng Cam Lộ, Chi Thảo và Trường Phong kề vai sát cánh trừ ma bảo vệ đạo. Họ cùng nhau tiêu diệt ma quỷ và bảo vệ đạo pháp. Chu Nhi có tình cảm sâu đậm với Cam Lộ, nhưng vì người và yêu khác biệt nên cô rơi vào đau khổ. Khi Vô Hư chưởng môn bị yêu lực phản phệ, mưu tính đoạt lấy tu vi của cô, Chu Nhi đã hi sinh ba ngàn năm đạo hạnh để diệt trừ tà ma cứu lấy mọi người. Sau tất cả, cô mới thấu hiểu tình cảm chân thành thực sự thuộc về Chi Thảo.</p>', 'Full', 1, 'single', 'completed', 13, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hàn Đống","avatar":""},{"name":"Cam Đình Đình","avatar":""},{"name":"Trương Địch","avatar":""},{"name":"Từ Thiếu Cường","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["蛛仙"]', 1784690324129);
