INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luyen-ca-dong-bac-lua-giua-ngay-dong', 'Luyến Ca Đông Bắc: Lửa Giữa Ngày Đông', 'Never Alone Again', 'https://phimimg.com/upload/vod/20260221-1/eb41248ed9191072c5741d72b2e23334.jpg', 'https://phimimg.com/upload/vod/20260221-1/fdc7bed492c882849c3c35c4abef299e.jpg', '<p>Tại thành phố Cáp Nhĩ Tân những năm 90, Từ Thiết – một người vừa mãn hạn tù – tình cờ gặp gỡ Bách Linh, một vũ nữ giả câm. Qua vài lần chạm mặt và những đêm dài bầu bạn, tình cảm giữa hai người dần nảy sinh. Sự ấm áp của đêm giao thừa đã kéo họ lại gần nhau hơn, nhưng rồi những ngăn cách thực tế và sự hiểu lầm từ phía gia đình khiến mối quan hệ ấy cứ mãi giằng co.&nbsp; Cuốn sổ tay bí mật ghi lại việc Bách Linh phải gánh nợ thay cha đã giúp Từ Thiết thấu hiểu được nỗi khổ tâm của cô. Sự truy đuổi, bức hại của Lôi Lực càng đẩy cả hai vào bước đường cùng. Từ Thiết đã bất chấp tính mạng để cứu Bách Linh khỏi cảnh giam cầm, cuối cùng cũng nhận được sự chúc phúc từ gia đình. Hai tâm hồn cô độc ấy, dưới sức ép nặng nề của thế tục, đã dùng tình yêu chân thành để sưởi ấm cuộc đời nhau.</p>', 'Full', 1, 'single', 'completed', 11, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Kiều Sam","avatar":""},{"name":"Lý Mộc Thần","avatar":""},{"name":"Tôn Nghệ Châu","avatar":""},{"name":"Vương Trí","avatar":""},{"name":"Trương Hạo","avatar":""},{"name":"Hàn Ngạn Bác","avatar":""},{"name":"Lý Hội","avatar":""},{"name":"Triệu Hải Yến","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Northeastern Bro Ⅲ","东北恋歌：冬天里的一把火"]', 1784690324129);
