INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-vien-thuong-luu', 'Học Viện Thượng Lưu', 'The School', 'https://phimimg.com/upload/vod/20260123-1/d12206fcc2721c4b5dcc333ac69d05c6.jpg', 'https://phimimg.com/upload/vod/20260123-1/e2491775851629d9d5c0e45c360a8480.jpg', '<p>Bộ phim kể về cuộc chiến giữa công lý và quyền lực tại trường quốc tế ISK. Khi nam sinh nghèo Kanatee bị vu oan sau một vụ án mạng chấn động, giáo viên Key đã đứng ra bảo vệ cậu, phơi bày những góc khuất đen tối và sự thối nát đằng sau vẻ hào nhoáng của giới tinh hoa.</p>', 'Tập 10', 32, 'series', 'ongoing', 23, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Aff Taksaorn Paksukcharoen","avatar":""},{"name":"Aom Phiyada","avatar":""},{"name":"Chakrit Yamnam","avatar":""},{"name":"Fern Nopjira","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["ศักดินาวิทยาลัย"]', 1784690324129);
