INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hau-vua-nhu-hau-cop', 'Hầu Vua Như Hầu Cọp', 'Shall We Dance', 'https://phimimg.com/upload/vod/20260207-1/a9d75735db1f70ea22525e30f0cb0049.jpg', 'https://phimimg.com/upload/vod/20260207-1/b013fcabd6f04b99e3c96505bd224cbb.jpg', '<p>Thuở nhỏ, Thái tử Trử Anh tình cờ quen biết với tiểu thái giám Tiểu Mãn, hai người thanh mai trúc mã, kết thành tâm giao. Sau khi Tiên đế băng hà, Thái tử Trử Anh lên ngôi hoàng đế, còn Tiểu Mãn lại bị trục xuất khỏi cung. Mười năm sau, Tiểu Mãn cải trang nam nhi quay lại hoàng cung. Hai người ngoài mặt thì trông thân thiết nhưng thực chất lại âm thầm dò xét, thử thách lẫn nhau. Sau khi cùng nhau trải qua những sóng gió tranh đấu chốn triều đình, tình cảm của cả hai bắt đầu nảy sinh biến chuyển...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 20, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngô Hải","avatar":""},{"name":"Lâm Lâm","avatar":""},{"name":"Quách Uyển Đông","avatar":""},{"name":"Vương Thần Húc","avatar":""},{"name":"Mã Lệ Á","avatar":""},{"name":"Vưu Chinh Huyên","avatar":""},{"name":"Tiêu Kì Tâm","avatar":""},{"name":"Ưng Chấn Nam","avatar":""},{"name":"Châu Dạng","avatar":""},{"name":"Thang Duy Văn","avatar":""},{"name":"Wang Mengqi","avatar":""},{"name":"Vương Tử Hàm","avatar":""},{"name":"Lâm Thần Nghị","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324129);
