INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-moi-thuy-dien', 'Đầu Mối Thụy Điển', 'The Swedish Connection', 'https://phimimg.com/upload/vod/20260221-1/b41242ed60d29c90a814d05cd0181cfe.jpg', 'https://phimimg.com/upload/vod/20260221-1/084c5d0710cfd9dda6bc7e9c1f89e6eb.jpg', '<p>Trong câu chuyện có thật ít người biết này, quan chức Thụy Điển nọ bất đắc dĩ hóa anh hùng chiến tranh khi nỗ lực cứu mạng người Do Thái trong những ngày đen tối nhất Thế chiến II.</p>', 'Full', 1, 'single', 'completed', 28, 2026, 'Vietsub', 'FHD', 'Thụy Điển', 0, '[{"name":"Henrik Dorsin","avatar":""},{"name":"Sissela Benn","avatar":""},{"name":"Jonas Karlsson","avatar":""},{"name":"Johan Glans","avatar":""},{"name":"Olle Jansson","avatar":""},{"name":"Oscar Töringe","avatar":""},{"name":"Loa Falkman","avatar":""},{"name":"Marianne Mörck","avatar":""},{"name":"Rakel Benér","avatar":""},{"name":"Figge Norling","avatar":""},{"name":"Christoffer Nordenrot","avatar":""},{"name":"Per Lasson","avatar":""},{"name":"Jonas Malmsjö","avatar":""},{"name":"Carl Jacobson","avatar":""},{"name":"Richard Ulfsäter","avatar":""},{"name":"Stefan Gödicke","avatar":""},{"name":"Simon Norrth","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Swedish Connection","The Swedish Rescue: Dark Line","Den svenska länken"]', 1784690324129);
