INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dau-moi-thuy-dien', 'Đầu Mối Thụy Điển', 'The Swedish Connection', 'đầu mối thụy điển the swedish connection henrik dorsin sissela benn jonas karlsson johan glans olle jansson oscar töringe loa falkman marianne mörck rakel benér figge norling christoffer nordenrot per lasson jonas malmsjö carl jacobson richard ulfsäter stefan gödicke simon norrth the swedish connection the swedish rescue: dark line den svenska länken', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chan-tuong-bi-che-giau', 'Chân Tướng Bị Che Giấu', 'The Hidden Truth', 'https://phimimg.com/upload/vod/20260207-1/0e6030b6059c0bffc78694d3eeff6d07.jpg', 'https://phimimg.com/upload/vod/20260207-1/614b476b80412da24e6e3b1db31f152b.jpg', '<p>Cảnh sát hình sự trẻ Đường Đường theo chân sư phụ tham gia điều tra vụ án tiệc khỏa thân 15 năm trước. Kẻ chủ mưu trước đây là Bạch Khởi Minh lại trở về thành phố Thanh Thành, khiến cảnh sát chú ý. Trong quá trình giám sát và điều tra, họ phát hiện ra y liên quan đến nhiều băng nhóm tội phạm hơn. Trên nền tảng mạng, dưới danh nghĩa “Nhà nuôi chó hoang vì tình yêu thương”, thực chất là đang lừa đảo người dân để thu lợi bất chính, đồng thời cũng có liên hệ rất sâu sắc đến hành vi phạm tội của Bạch Khởi Minh; nhóm trộm chó liên tục gây chuyện trong thành phố, việc người già và trẻ nhỏ ăn phải thực phẩm độc hại khiến mâu thuẫn xã hội trở nên gay gắt hơn, đằng sau dường như có liên quan mật thiết đến “Lão Bạch”; ông chủ nhà hàng Hồng Vận nổi tiếng địa phương, Vương Lực, vô tình giết người; cùng với sự mất tích bí ẩn của người vô gia cư… Đằng sau những bí ẩn này, chàng thanh niên chính trực Đường Đường dần dần khám phá ra sự thật.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 12, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đinh Quán Sâm","avatar":""},{"name":"Ấn Tiểu Thiên","avatar":""},{"name":"Hoàng Đình Đình","avatar":""},{"name":"Quách Phẩm Siêu","avatar":""},{"name":"Vương Ninh","avatar":""},{"name":"Hạ Chí Khanh","avatar":""},{"name":"Trạch Vũ Giai","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bei Yin Ni De Zhen Xiang","被隐匿的真相"]', 1784690324129);
