INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chan-tuong-bi-che-giau', 'Chân Tướng Bị Che Giấu', 'The Hidden Truth', 'chân tướng bị che giấu the hidden truth đinh quán sâm ấn tiểu thiên hoàng đình đình quách phẩm siêu vương ninh hạ chí khanh trạch vũ giai bei yin ni de zhen xiang 被隐匿的真相', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-to-vien-phi-thuong', 'Công Tố Viên Phi Thường', 'The Unusual Prosecutor', 'https://phimimg.com/upload/vod/20260122-1/1813b604df25e8cca3605b2370e95535.jpg', 'https://phimimg.com/upload/vod/20260122-1/e7c32ae55b580242e5536234f15ef53e.jpg', '<p>Bao Hy Nhân là chuyên viên công tố hình sự, trợ lý cao cấp của Sở Tư pháp, đồng thời mắc “hội chứng phản xạ xúc giác gương” – căn bệnh hiếm khiến anh có khả năng cảm nhận sâu sắc nỗi đau và cảm xúc của người khác. Chính năng lực đặc biệt ấy giúp Hy Nhân kiên trì truy tìm toàn bộ sự thật trong mỗi vụ án, thuyết phục bị cáo đối diện với tội lỗi để phần nào xoa dịu những mất mát mà các nạn nhân phải gánh chịu. Đồng hành cùng anh là những cộng sự cùng chung lý tưởng như Công Tôn Phách, Triển Hùng Phi, Tần Sương Ngôn và công tố viên tập sự Triệu Tử Trinh. Trên hành trình bảo vệ công lý, họ liên tục đối mặt với vô vàn khó khăn, thử thách cùng những vụ án ngày càng phức tạp và khắc nghiệt.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 20, 2026, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Mã Đức Chung","avatar":""},{"name":"Ngô Vỹ Hào","avatar":""},{"name":"Lại Úy Linh","avatar":""},{"name":"Trần Vỹ","avatar":""},{"name":"Trần Hiểu Hoa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["非常检控观","Fei Chang Jian Kong Guan","The Unusual Prosecutor","非常檢控觀"]', 1784690324129);
