INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cong-to-vien-phi-thuong', 'Công Tố Viên Phi Thường', 'The Unusual Prosecutor', 'công tố viên phi thường the unusual prosecutor mã đức chung ngô vỹ hào lại úy linh trần vỹ trần hiểu hoa 非常检控观 fei chang jian kong guan the unusual prosecutor 非常檢控觀', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('28-nam-sau-ngoi-den-tu-than', '28 Năm Sau: Ngôi Đền Tử Thần', '28 Years Later: The Bone Temple', 'https://phimimg.com/upload/vod/20260221-1/7e0124c06ca3b26ae515d50200bae1c3.jpg', 'https://phimimg.com/upload/vod/20260221-1/517ac91a356d526719b95d849e3c3d27.jpg', '<p>Mở rộng thế giới do Danny Boyle và Alex Garland xây dựng trong loại phim 28 Năm Sau nhưng đồng thời đảo ngược hoàn toàn mọi trật tự vốn có trong thế giới ấy. Nia DaCosta đảm nhận vai trò đạo diễn bộ phim 28 Năm Sau: Thánh Địa Xương. Tiếp nối câu chuyện, bác sĩ Kelson (Ralph Fiennes) bất ngờ rơi vào một mối quan hệ mới đầy bất ngờ, có khả năng làm thay đổi cả thế giới mà ta từng biết. Trong khi đó, cuộc chạm trán của Spike (Alfie Williams) với Jimmy Crystal (Jack O&quot;Connell) lại biến thành một cơn ác mộng không lối thoát của cậu bé. Trong thế giới của Thánh Địa Xương, những kẻ bị nhiễm bệnh không còn là mối đe dọa sinh tồn lớn nhất mà chính sự vô nhân tính của những kẻ sống sót mới là thứ quái lạ và đáng sợ hơn.</p>', 'Full', 1, 'single', 'completed', 19, 2026, 'Vietsub', 'FHD', 'Anh', 1, '[{"name":"Ralph Fiennes","avatar":""},{"name":"Jack O''Connell","avatar":""},{"name":"Alfie Williams","avatar":""},{"name":"Erin Kellyman","avatar":""},{"name":"Chi Lewis-Parry","avatar":""},{"name":"Emma Laird","avatar":""},{"name":"Sam Locke","avatar":""},{"name":"Connor Newall","avatar":""},{"name":"Maura Bird","avatar":""},{"name":"Ghazi Al Ruffai","avatar":""},{"name":"Robert Rhodes","avatar":""},{"name":"Mirren Mack","avatar":""},{"name":"Louis Ashbourne Serkis","avatar":""},{"name":"Gordon Alexander","avatar":""},{"name":"David Sterne","avatar":""},{"name":"Elliot Benn","avatar":""},{"name":"Lynne A","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["28 Years Later 2","28년 후: 뼈의 사원","Extermínio 4","Extermínio 4: O Templo dos Ossos","28 Years Later II: The Bone Temple","28 Năm Sau: Thánh Địa Xương","28 років по тому: Храм кісток","28 let poté: Chrám z kostí","28 Ans plus tard - Le Temple des morts","28 ปีให้หลัง เชื้อเขมือบคน: วิหารซากกะโหลก","The Bone Temple","28 Years Later: The Bone Temple"]', 1784690324129);
