INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('28-nam-sau-ngoi-den-tu-than', '28 Năm Sau: Ngôi Đền Tử Thần', '28 Years Later: The Bone Temple', '28 năm sau: ngôi đền tử thần 28 years later: the bone temple ralph fiennes jack o''connell alfie williams erin kellyman chi lewis-parry emma laird sam locke connor newall maura bird ghazi al ruffai robert rhodes mirren mack louis ashbourne serkis gordon alexander david sterne elliot benn lynne a 28 years later 2 28년 후: 뼈의 사원 extermínio 4 extermínio 4: o templo dos ossos 28 years later ii: the bone temple 28 năm sau: thánh địa xương 28 років по тому: храм кісток 28 let poté: chrám z kostí 28 ans plus tard - le temple des morts 28 ปีให้หลัง เชื้อเขมือบคน: วิหารซากกะโหลก the bone temple 28 years later: the bone temple', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-phan-trung-sinh', 'Thẩm Phán Trùng Sinh', 'The Judge Returns', 'https://phimimg.com/upload/vod/20260103-1/6e21b9f5293afc32c1c8562389a63080.jpg', 'https://phimimg.com/upload/vod/20260103-1/554f1cc080753e7c1b6a600ad51afd77.jpg', '<p>Lee Han Young (Ji Sung) – một thẩm phán từng lún sâu vào tham nhũng để rồi bị hãm hại bởi chính những người anh từng phục vụ. Trong khoảnh khắc đối mặt với cái chết, một sự kiện siêu nhiên đã xảy ra, đưa linh hồn anh trở về thời điểm 10 năm trước, khi anh vẫn còn là một tân binh trong ngành tư pháp. Được trao cơ hội thứ hai, anh quyết tâm tìm lại công lý bằng cách trừng phạt cái ác.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 22, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ji Sung","avatar":""},{"name":"Won Jin-ah","avatar":""},{"name":"Park Hee-soon","avatar":""},{"name":"Baek Jin-hee","avatar":""},{"name":"Oh Se-young","avatar":""},{"name":"Hwang Hee","avatar":""},{"name":"Tae Won-seok","avatar":""},{"name":"Park Geon-il","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["法官李汉英","Judge Lee Han-young","The Judge Returns"]', 1784690324129);
