INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thap-tam-giao-9', 'Thập Tam Giao 9', 'Thirteen Talks', 'https://phimimg.com/upload/vod/20260131-1/79731c7ba53efb513db9300bedb1c346.jpg', 'https://phimimg.com/upload/vod/20260131-1/3a539ebb6fc18e3d10d9eeab8aa6d93e.jpg', '<p>Mùa thứ chín chào đón một khởi đầu hoàn toàn mới. Giữa những biến động to lớn của thời đại, chương trình nỗ lực phá vỡ trạng thái &#39;lơ lửng&#39; của tư duy để thâm nhập sâu vào những kết cấu thô ráp và chân thực nhất của thế giới. Hứa Tri Hòa sẽ đồng hành cùng những vị khách mời có kiến giải độc đáo về thời đại, cùng họ nhận diện phương hướng thông qua những hành động cụ thể, và đi tìm sự xác tín giữa một thế giới đầy những bất định.</p>', 'Tập 2', 13, 'tvshows', 'ongoing', 26, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xu Zhiyuan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["十三邀","Thirteen Talks","Shi San Yao"]', 1784690324129);
