INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sommore-den-chum-ruc-sang', 'Sommore: Đèn Chùm Rực Sáng', 'Sommore: Chandelier Fly', 'https://phimimg.com/upload/vod/20260219-1/54492589f4853ebe00e3f45be6c20fa3.jpg', 'https://phimimg.com/upload/vod/20260219-1/448321d71b3511ef6b9df613e4c1ad1d.jpg', '<p>Hãy sẵn sàng chào đón sự trở lại của &#39;Nữ hoàng không ngai&#39; trong làng hài kịch — Sommore. Cô quay trở lại Detroit để thực hiện chương trình đặc biệt thứ 7 của mình với một phong cách gần gũi và cá tính hơn bao giờ hết tại Nhà hát Garden, được ghi hình trực tiếp vào ngày 28 tháng 6.</p>', 'Full', 1, 'single', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sommore","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Sommore: Chandelier Fly"]', 1784690324129);
