INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-quy-ky-an', 'Đường Quỷ Kỳ Án', 'Mysterious And Absurd Cases Of The Tang Dynasty', 'https://phimimg.com/upload/vod/20260210-1/757ec49a1f666a81a16470c58ba8eeb3.jpg', 'https://phimimg.com/upload/vod/20260210-1/be8b24857a1c74805c43209123d31782.jpg', '<p><span class="info__field-name"></span>Nhà Đường, giữa thời Khai Nguyên 
thịnh thế, ẩn dưới lớp vỏ phồn hoa rực rỡ của thành Trường An là những 
vụ án hết sức ly kỳ. Thám tử chốn dân gian Thân Đồ Bách Kỳ đã hợp tác 
cùng Thiếu khanh Đại Lý Tự Nghiêu Viễn và Mục Quy Đề, lần lượt phá giải 
hàng loạt vụ kỳ án như tế lễ hài nhi, trấn yểm quan tài, đánh bại quỷ 
dữ, rối gỗ đòi mạng, giấy gán vợ… Dần dà, họ từng bước lột trần những 
tham vọng quyền lực và chấp niệm cuồng si, vì người đã khuất mà truy tìm
 chân tướng, lặng lẽ giúp họ đòi lại công lý…</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 19, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Dật Kiệt","avatar":""},{"name":"Quản Nhạc","avatar":""},{"name":"Hầu Trình Nguyệt","avatar":""},{"name":"Lưu Vận Hàm","avatar":""},{"name":"Hạ Cương Cao","avatar":""},{"name":"Ngô Xuân Di","avatar":""},{"name":"Trương Minh Minh","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Tang Gui Qi An","长安变","Tang Dynasty Mysterious Cases","唐诡奇案"]', 1784690324129);
