INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('suong-mu-mua-dong-phan-2', 'Sương Mù Mùa Đông (Phần 2)', 'Kohrra (Season 2)', 'https://phimimg.com/upload/vod/20260216-1/1caead737df07914856c420c8c968362.jpg', 'https://phimimg.com/upload/vod/20260216-1/fdd7471222c80001d7fa9053135555a5.jpg', '<p>Khi một chú rể NRI được tìm thấy đã chết vài ngày trước đám cưới của anh, hai cảnh sát phải làm sáng tỏ vụ án rắc rối này khi sóng gió ập xuống cuộc sống của chính họ.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 19, 2026, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Barun Sobti","avatar":""},{"name":"Mona Singh","avatar":""},{"name":"Rannvijay Singha","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["कोहरा"]', 1784690324129);
