INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sau-khi-thuc-tinh-toi-dai-khai-sat-gioi', 'Sau Khi Thức Tỉnh, Tôi Đại Khai Sát Giới', 'Awakened Into Beast Mode', 'https://phimimg.com/upload/vod/20260216-1/083d975cfa59061be49c102af1e258bd.jpg', 'https://phimimg.com/upload/vod/20260216-1/56003033ff01cf280175744b654df515.jpg', '<p>Học sinh trung học bình thường Tấn An tình cờ bị đâm xe sau đó tỉnh thức và phát hiện ra rằng thế giới mình đang sống thực chất là trò chơi sinh tồn toàn cảnh &quot;Khải Huyền&quot;, và bản thân lại chính là người quản trị hệ thống có quyền điều khiển dữ liệu. Cậu có thể dùng lệnh để xóa dữ liệu bất thường và sửa đổi quy tắc thế giới nhưng cũng bị “thú ký sinh” trong trò chơi và chương trình quét diệt hệ thống truy sát. Tấn An gặp Lâm Khê, người chơi đến từ thế giới thực. Hai người kết đội chống lại thú ký sinh liên tục biến dị, quái thú tinh anh ẩn náu và tổ chức bí ẩn &quot;Thập Nhị Tinh Cung&quot;. Để bảo vệ thế giới trò chơi đang trên bờ vực sụp đổ và tìm đường trở về thế giới thực, họ xuyên qua nhiều thế giới, từ đô thị phép thuật hơi nước đến võ lâm giang hồ, ttừ tàn tích cyberpunk đến nghĩa địa trên mặt trăng. Trên hành trình mở khóa quyền quản trị, hợp nhất lõi tính toán, họ đối đầu với các boss tối thượng như “Tiên Tôn Vô Lượng” nắm giữ thế giới và vén màn sự thật về trật tự sắp đổ vỡ của thế giới trò chơi. Cuối cùng, với sự trợ giúp từ vô số điểm thức tỉnh, họ xuyên phá gông cùm ảo giác, đối diện trực diện với những kẻ xâm lược từ thế giới thực.</p>', 'Hoàn Tất (80/80)', 80, 'hoathinh', 'completed', 15, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324129);
