INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nho-kim-dan-toi-ganh-ca-tong-mon', 'Nhờ Kim Đan Tôi Gánh Cả Tông Môn', 'The Sect Of Pros And Their Beginner Senior', 'https://phimimg.com/upload/vod/20260216-1/43412a91e47a9627fb4d9e5097f266ab.jpg', 'https://phimimg.com/upload/vod/20260216-1/96191dd7e8140d8edfd245b1a6e2bbef.jpg', '<p>Đại sư huynh Trần Trường Sinh kẻ bị xem là “vô dụng” nhất toàn 
giới tu luyện hao tốn trăm năm trời cuối cùng cũng kết thành Kim Đan. 
Anh quyết tâm sử dụng tu vi “mạnh mẽ” của mình để bảo vệ các sư muội, sư
 đệ “tài năng bình thường nhưng vận số cực kỳ tốt.” trong môn phái. Điều
 anh không hề hay biết là: từ tông chủ cho đến đệ tử tạp dịch của Thanh 
Vân Đạo Tông, tất cả đều là các thần thánh và bậc đại nhân đã phi thăng 
nhưng vẫn ở lại thế gian vì anh. Mục tiêu duy nhất của họ trong kiếp này
 là bảo vệ người có ký ức và sức mạnh đều bị phong ấn: vị Đạo Tổ khai 
thiên lập địa Trần Trường Sinh.</p>', 'Hoàn Tất (80/80)', 80, 'hoathinh', 'completed', 13, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324129);
