INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mang-theo-mot-vuon-linh-duoc-toi-doc-doan-van-co-bang-cach-luyen-dan', 'Mang Theo Một Vườn Linh Dược Tôi Độc Đoán Vạn Cổ Bằng Cách Luyện Đan', 'Gardening My Way To Supremacy', 'https://phimimg.com/upload/vod/20260216-1/0062d6dba5eebf172b50d708487aef57.jpg', 'https://phimimg.com/upload/vod/20260216-1/7f14aa58bb2dbc3d0395155fce15f561.jpg', '<p>Tu sĩ Nguyên Anh là Lục Ẩn bị đàn anh Vân Thiên Dật phản bội và bị
 tước đi đạo thể rồi ném vào lò luyện đan. Tuy nhiên, anh lại vô tình 
kết nối với bảo vật cổ xưa &quot;Hư Không Điện&quot; và cùng hệ thống tái sinh vào
 cơ thể một thiếu niên cùng tên trên trái đất. Với sự kết hợp giữa &quot;Khoa
 học kỹ thuật + Tu tiên&quot;, anh dùng sản phẩm công nghiệp Trái Đất làm đòn
 bẩy khai thác tài nguyên giới tu tiên, thành lập Khoa học kỹ thuật Kính
 Tượng, tập hợp đội ngũ nòng cốt gồm Trần Lăng (điều hành thương mại), 
Tô Tiểu Tiểu (kỹ thuật cốt lõi), Tần Thụ (lãnh đạo an ninh). Anh vừa 
nhanh chóng tích lũy tài sản và tu vi, vừa bắt đầu báo thù Vân Thiên 
Dật. Từ việc phát triển linh thảo trên Trái Đất, tấn công tài chính, đến
 tiêu thụ sản phẩm công nghiệp trong giới tu tiên, xây dựng liên minh 
môn phái, Lục Ẩn đã phá vỡ những quy tắc cũ và tạo ra trật tự mới. Khi 
sức mạnh ngày càng mạnh mẽ, anh đã tổng hợp tài nguyên từ Trái Đất, giới
 tu tiên, yêu vực, ma vực rồi tạo ra chuỗi cung ứng đa thế giới và hạm 
đội vũ trụ. Anh từ một kẻ báo thù vừa được tái sinh từ lò luyện đan trở 
thành người tạo dựng trật tự mới giữa các thế giới.</p>', 'Hoàn Tất (80/80)', 80, 'hoathinh', 'completed', 36, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phim Ngắn","slug":"phim-ngan","id":"4f02d28224c0747511790d57fbb63a62"}]', '[]', 1784690324129);
