INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duyen-khoi-tran-duong-khuynh-thanh', 'Duyên Khởi Trần Đường: Khuynh Thành', 'Chentang Genesis: Love In Fallen City', 'https://phimimg.com/upload/vod/20260216-1/a7f25841a191cdcde1ac8a09871869e5.jpg', 'https://phimimg.com/upload/vod/20260216-1/e9c00842a8a53bb15b3a2dc5fe74c33a.jpg', '<p>Ân Vũ Hàm tình cờ xuyên không về cửa ải Trần Đường Quan thời nhà Thương, sát cánh cùng vị hôn phu Lý Tịnh chống lại cuộc xâm lăng của Hải tộc. Bằng trí tuệ thời hiện đại, cô không chỉ nhìn thấu những âm mưu thâm độc mà còn tìm ra các món thần khí, thậm chí chế tạo ra thuốc súng để xoay chuyển cục diện chiến trường. Trong trận quyết chiến cuối cùng, Ân Vũ Hàm đã chấp nhận hy sinh thân mình để bảo vệ bách tính. May mắn thay, cô được thần thú Chu Tước che chở, giúp cô hồi sinh. Hai người cùng nhau đẩy lui đại quân của địch, bảo vệ sự bình yên cho cả một vùng đất. Thế nhưng, tận sâu dưới đại dương sâu thẳm, một cơn sóng dữ mới đã bắt đầu trỗi dậy...</p>', 'Hoàn Tất (17/17)', 17, 'series', 'completed', 33, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Phim Ngắn","slug":"phim-ngan","id":"4f02d28224c0747511790d57fbb63a62"}]', '["缘起陈塘之倾城"]', 1784690324129);
