INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-kiep-an', 'Đại Kiếp Án', 'Fury In The Shadows', 'https://phimimg.com/upload/vod/20260215-1/171e70ecbf5f0a044731543af9e9d2e6.jpg', 'https://phimimg.com/upload/vod/20260215-1/56a887f722e66b00334e1bd695b8aa47.jpg', '<p>Những năm 80 tại Đông Nam Á, băng cướp hung hãn do Đàm Lực cầm đầu đã bị mắc kẹt tại thành phố Đế Nam sau một vụ cướp. Thanh tra hình sự Kumar cùng cảnh sát người Hoa Vương Chấn liên thủ, vạch trần từng tầng mưu kế xảo quyệt của bọn chúng. Vì người tình bị làm nhục, Đàm Lực từ bỏ ý định trốn chạy, liều lĩnh tiếp tục gây án. Dựa vào mạng lưới quan hệ, cảnh sát siết chặt vòng vây. Cuối cùng, cuộc đối đầu sinh tử bùng nổ trong vụ cướp ngân hàng. Đàm Lực bắt giữ con tin, nhưng lại bị khống chế, còn người tình của hắn cũng sa lưới. Cuộc đối đầu chính tà này kết thúc với thắng lợi tuyệt đối thuộc về phía cảnh sát.</p>', 'Full', 1, 'single', 'completed', 16, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Thích Ngạn Năng","avatar":""},{"name":"Trương Hạo Nhiên","avatar":""},{"name":"Vương Uyển Trung","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Fury in the Shadows","大劫案"]', 1784690324129);
