INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-vu', 'Phong Vũ', 'Ancient Bracelet', 'https://phimimg.com/upload/vod/20260131-1/75cb763d10f51a91b359b89cd4a9ed43.jpg', 'https://phimimg.com/upload/vod/20260131-1/141144b4fbea09bc5d499948b8a3ef0a.jpg', '<p>A Chiêu, một y nữ thuộc tộc Vu Nguyệt, vốn là hậu duệ của Thần nữ nhưng chính cô cũng không hề hay biết. Cô tình cờ gặp gỡ và đem lòng yêu Quân chủ nước Bồ La là Ứng Đô, nhưng sau đó lại phải tận mắt chứng kiến cảnh anh ta tàn sát tộc nhân và những người thân thiết nhất của mình.&nbsp; Nhờ vào sức mạnh của chiếc vòng Phong Vũ Trạc có khả năng quay ngược thời gian, hai người đã cùng nhau trải qua ba kiếp luân hồi đầy đau khổ và trắc trở. Cuối cùng, A Chiêu cũng điều tra ra toàn bộ sự thật phía sau, dũng cảm đối đầu với xiềng xích &#39;cấm tình&#39; mà Thiên đạo áp đặt lên Thần nữ. Cô đã thành công phá bỏ số phận nghiệt ngã để cùng Ứng Đô kết thành quyến thuộc.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 16, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tăng Hự Trân","avatar":""},{"name":"Phạm Hiểu Đông","avatar":""},{"name":"Tan Siyuan","avatar":""},{"name":"Mã Tâm Dư","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Feng Wu","Love Against Destiny","风舞"]', 1784690324129);
