INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-truong', 'Linh Trưởng', 'Primate', 'https://phimimg.com/upload/vod/20260213-1/492338f69dcb3344f8a3bbdb0dcdc354.jpg', 'https://phimimg.com/upload/vod/20260213-1/ae8ce6e1bf80b7438f6d23680e01c2f1.jpg', '<p>Lucy, một sinh viên đại học, cùng nhóm bạn đến nghỉ dưỡng tại ngôi nhà gia đình cô ở Hawaii, nơi còn có Ben — con tinh tinh cưng của cô. Nhưng khi Ben nhiễm bệnh dại sau khi bị một con vật mang mầm bệnh cắn, kỳ nghỉ nhanh chóng biến thành cơn ác mộng. Khi Ben trở nên hung bạo và mất kiểm soát, cả nhóm buộc phải chiến đấu để giành lấy mạng sống và tìm cách thoát khỏi con vật từng được xem như một phần của gia đình.</p>', 'Full', 1, 'single', 'completed', 18, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Johnny Sequoyah","avatar":""},{"name":"Jessica Alexander","avatar":""},{"name":"Troy Kotsur","avatar":""},{"name":"Victoria Wyant","avatar":""},{"name":"Gia Hunter","avatar":""},{"name":"Benjamin Cheng","avatar":""},{"name":"Charlie Mann","avatar":""},{"name":"Tienne Simon","avatar":""},{"name":"Miguel Hernando Torres Umba","avatar":""},{"name":"Amina Abdi","avatar":""},{"name":"Rob Chalk","avatar":""},{"name":"Joe Abercrombie","avatar":""},{"name":"Nick Romano","avatar":""},{"name":"Rob Delaney","avatar":""},{"name":"Ben Pronsky","avatar":""},{"name":"Stuart Whelan","avatar":""},{"name":"Kae Alexand","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Osaru Ben","Curious Ben","Primat","Primate"]', 1784690324129);
