INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-belfast-toi-thien-duong', 'Từ Belfast Tới Thiên Đường', 'How To Get To Heaven From Belfast', 'https://phimimg.com/upload/vod/20260213-1/ab6c66025bb272c68fbbb72cc8da731d.jpg', 'https://phimimg.com/upload/vod/20260213-1/c3b29e2b1b85e9de8b405dcf4b686951.jpg', '<p>Ba người bạn chí cốt bước vào cuộc hành trình đầy hỗn loạn để giải mã bí ẩn về cái chết đáng ngờ của người bạn cũ và giữ kín bí mật đen tối của riêng họ.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 16, 2026, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Roisin Gallagher","avatar":""},{"name":"Sinéad Keenan","avatar":""},{"name":"Caoilfhionn Dunne","avatar":""},{"name":"Saoirse-Monica Jackson","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["如何从贝尔法斯特去天堂","贝尔法斯特天堂路","How to Get to Heaven from Belfast"]', 1784690324130);
