INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-hut-manh-liet', 'Thu Hút Mãnh Liệt', 'Affinity', 'https://phimimg.com/upload/vod/20260123-1/6cad1ae1f5a68aaef4ffafc7b32f24f3.jpg', 'https://phimimg.com/upload/vod/20260123-1/1fe5ea0dc9608596d3bc1eac1db703d0.jpg', '<p>Năm năm trước, Ngô Nùng Vũ theo anh trai Ngô Tư Nguyên đến hiện trường một vụ án mạng, từ đó số phận cô giao thoa với nghi phạm Tạ Tân Tự. Dường như cơ thể cô tự nhiên tỏa ra sức hấp dẫn đặc biệt đối với anh, khiến anh vừa trông thấy cô đã nảy sinh khao khát mãnh liệt muốn chiếm hữu cô. Năm năm sau, để có được Ngô Nùng Vũ, Tạ Tân Tự ngụy trang thành một giáo sư y khoa lạnh lùng, âm mưu tiếp cận cô, cẩn thận giăng bẫy khiến cô yêu mình, hai người cùng dấn thân vào một cuộc phiêu lưu mạo hiểm. Trong những tháng ngày tiếp xúc với cô gái rạng rỡ như mặt trời, gã điên trời sinh thiếu sự đồng cảm dần dần học được cách nhận biết cảm xúc như người bình thường!</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 19, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngô Nồng Vũ","avatar":""},{"name":"Phương Cẩn","avatar":""},{"name":"Tôn Vũ Tân","avatar":""},{"name":"Vương Nhất Tuân","avatar":""},{"name":"Lý Tương","avatar":""},{"name":"Cao Vĩ Mạn","avatar":""},{"name":"Lâm Quyển","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["炽热吸引","Affinity"]', 1784690324130);
