INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sac-dem-ngap-tran', 'Sắc Đêm Ngập Tràn', 'The Glamorous Night', 'https://phimimg.com/upload/vod/20260130-1/0760b3f78b24700d512ba475b8d1284e.jpg', 'https://phimimg.com/upload/vod/20260130-1/ef449da8e1b085ced7c655d013e12093.jpg', '<p>Dưới vỏ bọc của một bữa tiệc thịnh soạn đã khiến sóng ngầm giấu kín bấy lâu nay trỗi dậy, đánh thức tất cả những kẻ đang giả vờ ngủ say, đồng thời kích hoạt mối nguy sinh tồn lan rộng khắp các cấp bậc tại tập đoàn rượu GST. Khi mọi thứ đều là vấn đề sống còn, mỗi bước đi đều đòi hỏi sự cẩn trọng tột độ. Bảy nhân vật chính bị cuốn sâu vào vòng xoáy ấy, mỗi người đóng một vai trò khác nhau, cùng nhau phác họa nên sự phức tạp của lòng người và sự tàn khốc của thực tại. Tất cả cùng hướng đến một chủ đề chung: Làm thế nào để có thể sống lạc quan giữa những tháng ngày đầy rẫy bất an và lo sợ!</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 11, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Giang Sơ Ảnh","avatar":""},{"name":"Đồng Đại Vỹ","avatar":""},{"name":"Trương Siêu","avatar":""},{"name":"Lam Doanh Oánh","avatar":""},{"name":"Hám Thanh Tử","avatar":""},{"name":"Đại Húc","avatar":""},{"name":"Trương Triệu Huy","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Sales夫妇","The Sales","The Glamorous Night","夜色正浓"]', 1784690324130);
