INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quay-ve-nam-1995-de-yeu-em', 'Quay Về Năm 1995 Để Yêu Em', 'Once More Love In 1995', 'https://phimimg.com/upload/vod/20260130-1/7f651464603f005fd4723160a5458626.jpg', 'https://phimimg.com/upload/vod/20260130-1/614c3b3e65fc27c5c97960013a1eaafd.jpg', '<p>Cô gái hiện đại Trang Mạn Anh vô tình xuyên không trở về năm 1995. Với quyết tâm thay đổi số phận bi thảm của mẹ mình, cô đã vận dụng những kỹ năng thời hiện đại để thống trị chốn công sở và trừng trị thẳng tay gã đàn ông tồi tệ. Thế nhưng, cô lại bất ngờ rơi vào những rắc rối tình cảm không lường trước với người &#39;cậu&#39; lạnh lùng của mình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 16, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đại Cao Chính","avatar":""},{"name":"Trần Phương Đồng","avatar":""},{"name":"Trương Quản Tâm","avatar":""},{"name":"Niếp Thị Vân","avatar":""},{"name":"Vũ Gia Kỳ","avatar":""},{"name":"Tôn Tư Phàm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["穿越时光回到1995爱上你","Huo Dao Ai 1995 Ai Shang Ni","Fall in Love With You Back in 1995","回到1995爱上你"]', 1784690324130);
