INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('quay-ve-nam-1995-de-yeu-em', 'Quay Về Năm 1995 Để Yêu Em', 'Once More Love In 1995', 'quay về năm 1995 để yêu em once more love in 1995 đại cao chính trần phương đồng trương quản tâm niếp thị vân vũ gia kỳ tôn tư phàm 穿越时光回到1995爱上你 huo dao ai 1995 ai shang ni fall in love with you back in 1995 回到1995爱上你', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-ay-that-ruc-ro', 'Cô Ấy Thật Rực Rỡ', 'Fall In Love Again', 'https://phimimg.com/upload/vod/20260205-1/205de400f445b7902d300978c61bcd0e.jpg', 'https://phimimg.com/upload/vod/20260205-1/aaaaa27c6f254be435eca57bec183674.jpg', '<p>Sở Cánh Tịch rút lui khỏi làng giải trí vì tình yêu nhưng bị chồng chưa cưới phản bội. Sau cú sốc, cô thành lập công ty sản xuất phim với sự hỗ trợ của bạn thân và fan trung thành, đối mặt với scandal và âm mưu công khai. Trong quá trình đó, tình cảm mới nảy nở với Hà Tranh. Cuối cùng, cô dũng cảm giành lại sự nghiệp, danh dự và sống một cuộc đời rực rỡ.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 11, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Quan Tâm","avatar":""},{"name":"Lý Triết Hào","avatar":""},{"name":"Trương Tử Huyên","avatar":""},{"name":"Chu Huyền Nghi","avatar":""},{"name":"Trương Bác Nam","avatar":""},{"name":"Mạc Kiêm","avatar":""},{"name":"Dư Nhất Lôi","avatar":""},{"name":"Uân Tư Vĩ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["璀璨的她"]', 1784690324130);
