INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bach-da-lau', 'Bách Dạ Lâu', 'Huckster', 'https://phimimg.com/upload/vod/20260211-1/3bf219a02d372111da99cc29da80f7d8.jpg', 'https://phimimg.com/upload/vod/20260211-1/b404827dfee769bce5341d706c60f410.jpg', '<p>Thời Dân Quốc, thầy trò Mã Văn Tài và Trương Tiểu Hầu lang bạt phương Nam, chuyên giả danh cao nhân để lừa gạt kiếm sống. Không ngờ họ vô tình bị cuốn vào một vụ án mạng và bị hiểu lầm là hung thủ. Để rửa sạch nghi ngờ, cả hai buộc phải ở lại nơi này, lần theo manh mối truy tìm hung thủ thực sự. Hàng loạt sự việc quái dị liên tiếp xảy ra dường như xác thực những lời đồn xui rủi trước đó. Trương Tiểu Hầu dần phát hiện, mọi trải nghiệm gần đây của mình lại có liên hệ mật thiết với một giấc mơ đã ám ảnh anh suốt nhiều năm.</p>', 'Full', 1, 'single', 'completed', 11, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Phạm Minh","avatar":""},{"name":"Vương Lạc Gia","avatar":""},{"name":"Ngụy Hiểu Huyền","avatar":""},{"name":"Lâu Nam Quang","avatar":""},{"name":"Cửu Khổng","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["百夜楼"]', 1784690324130);
