INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('katt-williams-bao-cao-cuoi-cung', 'Katt Williams: Báo Cáo Cuối Cùng', 'Katt Williams: The Last Report', 'https://phimimg.com/upload/vod/20260211-1/ac47f378c88f432aabd5e66152e10b7c.jpg', 'https://phimimg.com/upload/vod/20260211-1/893abedd24de9e57a8a47087ad399922.jpg', '<p>Biểu tượng hài Katt Williams mang đến góc nhìn táo bạo làm nên tên tuổi của anh về thuyết âm mưu, người nổi tiếng và thế giới nói chung trong tiết mục hài độc thoại sôi động này.</p>', 'Full', 1, 'single', 'completed', 15, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Katt Williams","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Katt Williams: The Last Report"]', 1784690324130);
