INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-hy-chi-huong', 'Linh Hy Chi Hương', 'Infinite Cycle Of Love', 'https://phimimg.com/upload/vod/20260210-1/a341aa7408f7593acb5378a9f249a8ad.jpg', 'https://phimimg.com/upload/vod/20260210-1/53e51934cde8073f854549665f4e3bb8.jpg', '<p>Hoàng hậu Tiêu Linh, người từng bị phản bội và mắc kẹt trong cuộc hôn nhân lạnh lẽo, đầy nghi kỵ với Hoàng đế Lý Vân Hy, đã tái sinh một cách bí ẩn vào thời điểm một tháng trước khi nàng qua đời. Khi sống lại quá khứ qua nhiều vòng lặp luân hồi, nàng phải chèo lái giữa những âm mưu thâm độc chốn cung đình, lật mở những sự thật bị che giấu và đối mặt với những hiểu lầm đã định đoạt số phận bi thương của mình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 15, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hứa Mộc Thiền","avatar":""},{"name":"Vương Huy","avatar":""},{"name":"Trần Duệ Phong","avatar":""},{"name":"Triệu Hỉ Nguyệt","avatar":""},{"name":"Trang Anh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ling Xi Zhi Xiang","The Fragrance of Lingxi","灵犀之香"]', 1784690324130);
