INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuoc-dang-da-tat', 'Thuốc Đắng Dã Tật', 'Best Medicine', 'https://phimimg.com/upload/vod/20260107-1/237397424c02fe999fdf80968b0787bc.jpg', 'https://phimimg.com/upload/vod/20260107-1/e63e88e7ead043dbc91e5793431cc8c8.jpg', '<p>Một bác sĩ phẫu thuật tài năng đột ngột từ bỏ sự nghiệp lẫy lừng ở Boston để trở thành bác sĩ tại một làng chài ven biển miền Đông, nơi ông từng gắn bó với những mùa hè thời thơ ấu, nhưng tính cách thẳng thật một cách thái quá nhanh chóng khiến ông bị cả thị trấn xa lánh, dù ông là hy vọng y tế duy nhất của họ.</p>', 'Tập 4', 11, 'series', 'ongoing', 18, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Josh Charles","avatar":""},{"name":"Abigail Spencer","avatar":""},{"name":"Josh Segarra","avatar":""},{"name":"Annie Potts","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Best Medicine"]', 1784690324130);
