INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lieu-thuoc-cho-tinh-yeu', 'Liều Thuốc Cho Tình Yêu', 'Recipe For Love', 'https://phimimg.com/upload/vod/20260203-1/4fb11b10af5012bb21c20bbe93fae5dd.jpg', 'https://phimimg.com/upload/vod/20260203-1/c65d018cf7b9b5ec469fc42e15a0c60f.jpg', '<p>Tại thị trấn Onjeong, nơi hai dòng họ lớn đã cắt đứt quan hệ suốt nhiều thập kỷ. Kong Ju A nỗ lực đối đầu với áp lực từ người mẹ nghiêm khắc để tuyên bố từ bỏ sự nghiệp y khoa ngay sau khi vừa nhận được giấy phép hành nghề. Cô quyết định quay trở lại với chiếc máy khâu và những bản thiết kế dang dở, vốn là năng khiếu thiên bẩm mà cô được thừa hưởng từ người ông vốn là bác sĩ phẫu thuật tài hoa. Yang Hyeon Bin là quản lý cấp cao của tập đoàn thời trang Taehan SNC, anh trở về quê hương để thực hiện một dự án nghiên cứu thị trường mới. Hai đứa con đến từ hai dòng họ mâu thuẫn suốt nhiều năm hứa hẹn mang lại những thước phim gia đình, đời thường hấp dẫn cho dòng phim cuối tuần.</p>', 'Tập 2', 50, 'series', 'ongoing', 24, 2026, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jin Se-yeon","avatar":""},{"name":"Park Ki-woong","avatar":""},{"name":"Kim Mi-sook","avatar":""},{"name":"Kim Seung-su","avatar":""},{"name":"Yoo Ho-jeong","avatar":""},{"name":"Choi Dae-chul","avatar":""},{"name":"Ju Jin-mo","avatar":""},{"name":"Kim Hyeong-mook","avatar":""},{"name":"So I-hyeon","avatar":""},{"name":"Jo Mi-ryung","avatar":""},{"name":"Kim Sun-bin","avatar":""},{"name":"Yoon Seo-ah","avatar":""},{"name":"Kang Byul","avatar":""},{"name":"Jung Wook","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["给你爱情处方","وصفة من اجل الحب","사랑을 처방해 드립니다"]', 1784690324130);
