INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('star-trek-hoc-vien-starfleet', 'Star Trek: Học Viện Starfleet', 'Star Trek: Starfleet Academy', 'https://phimimg.com/upload/vod/20260119-1/292df9e9974ad38af0445daced13ae6b.jpg', 'https://phimimg.com/upload/vod/20260119-1/5ffee980632703524a03b01c90de335d.jpg', '<p>Một nhóm học viên trẻ tuổi cùng nhau theo đuổi giấc mơ chung về hy vọng và lý tưởng. Dưới sự giám sát nghiêm khắc của các giảng viên, họ sẽ dần khám phá điều gì cần thiết để trở thành sĩ quan Starfleet — khi tình bạn nảy nở, mâu thuẫn bùng nổ, những rung động đầu đời xuất hiện, và một kẻ thù mới trỗi dậy, đe dọa cả Học viện lẫn Liên bang.</p>', 'Tập 4', 10, 'series', 'ongoing', 17, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Holly Hunter","avatar":""},{"name":"Sandro Rosta","avatar":""},{"name":"Karim Diane","avatar":""},{"name":"Kerrice Brooks","avatar":""},{"name":"George Hawkins","avatar":""},{"name":"Bella Shepard","avatar":""},{"name":"Zoë Steiner","avatar":""},{"name":"Oded Fehr","avatar":""},{"name":"Gina Yashere","avatar":""},{"name":"Robert Picardo","avatar":""},{"name":"Tig Notaro","avatar":""},{"name":"Stephen Colbert","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Star Trek: Akademia e flotës yjore","星舰学院","Star Trek: Academia Starfleet","Star Trek: Starfleet Academy"]', 1784690324130);
