INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('goc-toi', 'Góc Tối', 'The Unseen', 'https://phimimg.com/upload/vod/20260131-1/fd2b083c054b17c108d3dc5f94818fb8.jpg', 'https://phimimg.com/upload/vod/20260131-1/cb3f3148fc48d0a2137ac65fbc1958d2.jpg', '<p>Nhằm truy tìm sự thật đằng sau vụ “tự sát” của chị gái, blogger Thẩm Mạn bị cuốn vào một vụ án vô cùng ly kỳ: trưởng khoa sản phụ khoa Ái Hạ bị cắt bỏ tử cung, đồng thời cô bị đưa vào diện tình nghi hàng đầu. Nữ cảnh sát Khương Lê ra tay giúp cô minh oan. Một tấm bưu thiếp kết nối hai vụ án với nhau đã buộc hai người vốn ở thế đối lập phải bắt tay hợp tác. Thế nhưng, vụ án mạng thứ hai lại tiếp tục xảy ra, màn sương bí ẩn lại ngày càng dày đặc…</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 11, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Từ Mộng Khiết","avatar":""},{"name":"Vương Hiểu Vân Tử","avatar":""},{"name":"Hàn Nhất Đình","avatar":""},{"name":"Tiêu Húc","avatar":""},{"name":"Bành Hạo Phong","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["An Chu","谁在暗处","暗处"]', 1784690324130);
