INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vien-son-di-van-luc', 'Viên Sơn Dị Văn Lục', 'Anecdotes Of Ape Mountain', 'https://phimimg.com/upload/vod/20260208-1/4dfc5868ed2f1c98e10b7b0020a302f0.jpg', 'https://phimimg.com/upload/vod/20260208-1/47cd69c4440f42e69f71421e4cbd7013.jpg', '<p>Theo truyền thuyết, xa xưa có một ngọn núi tên là núi Viên Hầu. Trên núi có một quốc gia gọi là nước Viên. Trong nước Viên có một con vượn trắng hiếm có. Nước Viên tôn thờ vượn trắng như một vị thần và gọi là "Viên Thần". Dân chúng thờ cúng ngày đêm để cầu bình an. Gần đây, có tin đồn rằng "Viên Thần" giận dữ và không bảo vệ nước Viên nữa, vì vậy nên nhà vua mới bệnh mãi không khỏi. Điều này khiến cho cả nước lo sợ.</p>', 'Full', 1, 'single', 'completed', 13, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Viên Phúc Phúc","avatar":""},{"name":"Vương Bồi Nghi","avatar":""},{"name":"Vương Thanh","avatar":""},{"name":"Vương Thuần","avatar":""},{"name":"Thiệu Phong","avatar":""},{"name":"Phó Hồng Thắng","avatar":""},{"name":"Lô Vũ","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324130);
