INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-mong-ky-duyen', 'Vân Mộng Kỳ Duyên', 'Yunmeng Romance', 'https://phimimg.com/upload/vod/20260208-1/892467c2a67f225fa23088b6714c134a.jpg', 'https://phimimg.com/upload/vod/20260208-1/23e3f59c283721e2cb1cd4de1e99f602.jpg', '<p>Giáo sư khảo cổ đã nghỉ hưu Vương Hoa luôn dốc lòng nghiên cứu những truyền thuyết trong Sơn Hải Kinh về Sở Tương Vương thời Chiến Quốc và Thần nữ Dao Cơ. Theo truyền thuyết, ngọn núi nơi chôn cất Dao Cơ nằm ở Hồ Bắc. Vương Hoa đã không từ mà biệt với con gái mình là Vương Gia, cùng các đồng nghiệp tiến vào vùng núi Vu Sơn để tìm kiếm cổ mộ, nhưng rồi đột ngột mất tích.  Trong tình thế cấp bách, Vương Gia buộc phải mời thám tử kỳ tài Tề Văn cùng mình lên đường tới Vu Sơn tìm cha. Thế nhưng cô không lường trước được rằng, chuyến đi này lại ẩn chứa vô vàn hiểm nguy rình rập.</p>', 'Full', 1, 'single', 'completed', 15, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Chí Bằng","avatar":""},{"name":"Trương Minh Minh","avatar":""},{"name":"Thư Dao Huyên","avatar":""},{"name":"Tôn Kiều Long","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324130);
