INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-co-ve-tran-quoc-than-dinh', 'Huyền Cơ Vệ: Trấn Quốc Thần Đỉnh', 'Geomancer', 'https://phimimg.com/upload/vod/20260208-1/2cfae7da112c30b6fd2a7974afd64205.jpg', 'https://phimimg.com/upload/vod/20260208-1/dbdd1592a04ca3bb41866d8a027d1b52.jpg', '<p>Một quả cầu lửa từ trên trời rơi xuống phá hủy ngôi làng biên cương. Chỉ sau một đêm, dân làng đột biến thành âm binh, lòng đất xuất hiện trận Tỏa Long cùng cự xà vảy đen khổng lồ. Kỳ tài của Huyền Cơ Vệ đã ẩn cư Bạch Ẩn Xuyên theo lời mời của Quốc sư mà tái xuất giang hồ. Anh liên thủ với người bạn cũ trong ngục là Trịnh Nguyên Báo và đội trưởng đội cấm vệ thân phận đầy bí ẩn Thi Linh Ngọc.</p>', 'Full', 1, 'single', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hạ Cương","avatar":""},{"name":"Viên Phúc Phúc","avatar":""},{"name":"Lý Minh Anh","avatar":""},{"name":"Lưu Lâm Thành","avatar":""},{"name":"Khâu Chấn Hải","avatar":""},{"name":"Lão Dương","avatar":""},{"name":"Tiểu Phi","avatar":""},{"name":"Dương Lôi","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Xuanji Guardian: The Divine Cauldron","玄机卫之镇国神鼎"]', 1784690324130);
