INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('huyen-co-ve-tran-quoc-than-dinh', 'Huyền Cơ Vệ: Trấn Quốc Thần Đỉnh', 'Geomancer', 'huyền cơ vệ: trấn quốc thần đỉnh geomancer hạ cương viên phúc phúc lý minh anh lưu lâm thành khâu chấn hải lão dương tiểu phi dương lôi xuanji guardian: the divine cauldron 玄机卫之镇国神鼎', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ha-hoang-dao', 'Hà Hoàng Dao', 'Hehuang Ballad', 'https://phimimg.com/upload/vod/20260207-1/82d28024c3b8ef5b9a7398e29d4c417f.jpg', 'https://phimimg.com/upload/vod/20260207-1/459dae46ea7d2c8cfd7a7fc0f1d6f833.jpg', '<p>Vào những năm 1990, thành phố Tây Ninh bị bao quanh bởi những ngọn núi hoang sơ phía Nam và phía Bắc, nơi gió cát hoành hành dữ dội. Một nhóm thanh niên tại Nhà máy Công cụ Thanh Hải — gồm Lâm Minh Sơn đang buồn chán, Hoàng Thu Anh kiên định, Chu Hữu Tài chân chất và Mã Bôn Đằng khôn ngoan — đã được định mệnh thúc đẩy dấn thân vào công trình phủ xanh đất trống.&nbsp; Giữa cái lạnh khắc nghiệt và hạn hán của vùng cao nguyên, họ vừa mày mò tìm phương pháp trồng cây hiệu quả, vừa phải trải qua nỗi đau mất đi đồng đội cùng những thử thách từ hiểu lầm và tranh chấp. Cuối cùng, bằng trí tuệ và sự kiên trì suốt hàng chục năm, họ đã biến vùng đất không một ngọn cỏ thành núi xanh nước biếc.&nbsp; Bộ phim kể về câu chuyện cảm động qua sự tiếp nối của hai thế hệ, tái hiện kỳ tích phủ xanh núi Nam Bắc ở Tây Ninh, đồng thời là lời ca ngợi những người xây dựng văn minh sinh thái — những người luôn gian khổ phấn đấu và sẵn sàng cống hiến thầm lặng.</p>', 'Full', 1, 'single', 'completed', 11, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Kenny Kan","avatar":""},{"name":"KIRA","avatar":""},{"name":"Cao Lợi","avatar":""},{"name":"Quách Phong Châu","avatar":""},{"name":"Tăng Bồi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324130);
