INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chinh-phuc-sieu-cao-oc-truc-tiep', 'Chinh Phục Siêu Cao Ốc Trực Tiếp', 'Skyscraper Live', 'https://phimimg.com/upload/vod/20260207-1/5aeea9e7f999360fbd261a12feab15c1.jpg', 'https://phimimg.com/upload/vod/20260207-1/e197ecdabcdc41096436789db0902903.jpg', '<p>Không có dây thừng. Không sợ hãi. Huyền thoại solo tự do Alex Honnold mạo hiểm tất cả trong cuộc đua trực tiếp đầy rủi ro khi leo lên một trong những tòa nhà chọc trời cao nhất thế giới ở Đài Bắc, Đài Loan.</p>', 'Full', 1, 'single', 'completed', 12, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Alex Honnold","avatar":""},{"name":"Elle Duncan","avatar":""},{"name":"Emily Harrington","avatar":""},{"name":"Mark Rober","avatar":""},{"name":"Sanni McCandless","avatar":""},{"name":"Colby Lopez","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Skyscraper Live"]', 1784690324130);
