INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nien-ca-hanh-thien-ha-vo-song', 'Thiếu Niên Ca Hành: Thiên Hạ Vô Song', 'The Blood Of Youth: Quest Of Heroic Hearts', 'https://phimimg.com/upload/vod/20260128-1/1fcf726edbb3424d0f9a1af953d89ce9.jpg', 'https://phimimg.com/upload/vod/20260128-1/8167399dc928b70ae07c611c92b4f036.jpg', '<p>Câu chuyện theo chân Vị Quy – thiếu niên mất trí nhớ mang mối thù diệt môn – cùng Lôi Linh Trạch và Hoa Tiểu Hoa trên hành trình truy tìm Thiên Trảm Kiếm, đối đầu thế lực ma đạo Thiên Ngoại Thiên, qua đó khắc họa một giang hồ đầy biến động nơi tình bạn, niềm tin và tinh thần hiệp nghĩa quyết định ai mới là “đệ nhất thiên hạ”.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 13, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lâm Tư Huy","avatar":""},{"name":"Thái Chính Kiệt","avatar":""},{"name":"Tăng Huy Diễm","avatar":""},{"name":"Chu Tử Kiệt","avatar":""},{"name":"Hoàng Diệp Bình","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Shao Nian Ge Xing Zhi Tian Xia Wu Shuang","少年歌行之天下无双"]', 1784690324130);
