INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('salvador', 'Salvador', 'Salvador', 'https://phimimg.com/upload/vod/20260206-1/797a5720add74b23ca7c03c85c85d02f.jpg', 'https://phimimg.com/upload/vod/20260206-1/27e105a5da51baa82b6275e748f5a029.jpg', '<p>Trong một cuộc đối đầu bạo lực được dàn xếp giữa những người hâm mộ quá khích của hai câu lạc bộ bóng đá, Salvador Aguirre, một tài xế xe cứu thương, đã giải cứu cô con gái bị thương của mình là Milena. Cô vốn là thành viên của một nhóm cổ động viên cực đoan (ultra) – nhóm người bảo vệ các giá trị phân biệt chủng tộc, bạo lực và kỳ thị đồng tính, hoàn toàn đối lập với những giá trị mà ông đã truyền dạy cho cô.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 20, 2026, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Luis Tosar","avatar":""},{"name":"Candela Arestegui","avatar":""},{"name":"Claudia Salas","avatar":""},{"name":"Juan Carlos Vellido","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324130);
