INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-chu-my-tham', 'Song Chu Mỹ Thám', 'Duet Of Shadows', 'https://phimimg.com/upload/vod/20260206-1/a3ef54902353efe03bf76e90c84a943d.jpg', 'https://phimimg.com/upload/vod/20260206-1/7324933995322dd7671f22c5d2f5b58a.jpg', '<p>Lấy bối cảnh Thượng Hải những năm 1920, người thừa kế Lâm Lan trở thành thám tử tại Sở Cảnh sát Trung tâm và bắt tay cùng chuyên gia pháp y Tần Hân cùng một đội điều tra tinh nhuệ. Cùng nhau, họ giải quyết những vụ án kỳ lạ, tạo nên một cặp bài trùng phá án quyền năng, đồng thời xây dựng nên một tình bạn không thể phá vỡ.</p>', 'Hoàn Tất (31/31)', 31, 'series', 'completed', 15, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tôn Diệp Hân","avatar":""},{"name":"Tôn Mỹ Lâm","avatar":""},{"name":"Hứa Hạo","avatar":""},{"name":"Tu Du","avatar":""},{"name":"Lý Viên","avatar":""},{"name":"Cao Từ Nguyệt","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shuang Shu Mei Tan","Two Beautiful Female Detectives","双姝美探"]', 1784690324130);
