INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-minh-am-anh-ba-tram-trung-hon', 'Đại Minh Ám Ảnh: Ba Trăm Trung Hồn', 'The 300 Loyal Ghosts', 'https://phimimg.com/upload/vod/20260131-1/40b1b539f149bbd3dc5adaf0093cf619.jpg', 'https://phimimg.com/upload/vod/20260131-1/48f8cbcfe54dcdc08d920dd10e0429dc.jpg', '<p>Đại Lý Tự Thiếu Khanh – Trương Dực, mang trong mình mối thù sâu đậm, chấp nhận nhẫn nhịn ẩn mình chờ thời cơ. Bề ngoài, y liên thủ với Cẩm Y Vệ Thẩm Do Chi để truy lùng hung thủ, chuyển từ thế đối đầu sang hợp tác. Nhưng phía sau, y chính là bàn tay thao túng toàn bộ cục diện để thực hiện kế hoạch báo thù. Khi mọi âm mưu đi đến hồi kết, chiếc bẫy công lý được dàn dựng tỉ mỉ bất ngờ thu lưới. Số phận của tất cả mọi người được quyết định khoảnh khắc này, buộc họ phải đưa ra lựa chọn cuối cùng giữa thế giới đầy cạm bẫy.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 14, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hoàng Hựu Minh","avatar":""},{"name":"Đoàn Tiểu Vi","avatar":""},{"name":"Xu Yang","avatar":""},{"name":"Vương Mậu Lôi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Da Ming An Ying San Bai Zhong Hun","The Ming Shadow: Three Hundred Loyal Souls","大明暗影三百忠魂"]', 1784690324130);
