INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-dao-khong-muon-lam-sat-thu', 'Thanh Dao Không Muốn Làm Sát Thủ', 'How To Train Your Killer', 'https://phimimg.com/upload/vod/20260124-1/481ed988b5175549c05f448c990fbaed.jpg', 'https://phimimg.com/upload/vod/20260124-1/33f234a7af5d0f86be096d5b19ded3b1.jpg', '<p>Vào đêm tân hôn, Thái tử phi Cố Thanh Dao bất ngờ chạm trán sát thủ máu lạnh Thập Nhất đang ám sát phu quân Thái tử của mình, cả hai vô tình bị hoán đổi linh hồn. Để bảo vệ phu quân, Cố Thanh Dao bắt đầu cuộc đấu trí đấu dũng với sát thủ Thập Nhất, mở ra một trò chơi ám sát kịch tính. Đằng sau đó còn ẩn chứa một cuộc tranh quyền đoạt vị kinh tâm động phách giữa chốn giang hồ và cung đình...</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 16, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Thôi Vũ Hâm","avatar":""},{"name":"Trương Sở Hàn","avatar":""},{"name":"Trần Danh Hào","avatar":""},{"name":"Tống Chiêu Nghệ","avatar":""},{"name":"Lưu Tĩnh Di","avatar":""},{"name":"Trần Đằng Diệu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Qing Yao Bu Xiang Dang Sha Shou","킬러 되기 싫어요!","Qingyao Doesn''t Want to be An Assassin","青瑶不想当杀手"]', 1784690324130);
