INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xa-than-lay-vo', 'Xà Thần Lấy Vợ', 'The Long Snake Takes A Wife', 'https://phimimg.com/upload/vod/20260121-1/af3b204b00453fbd764aa48673aeb092.jpg', 'https://phimimg.com/upload/vod/20260121-1/2dc5adf4c824656a88166ea83a52c5a9.jpg', '<p>Mẹ của Bạch Trung Thiên năm xưa gặp nạn một cách ly kỳ. Dân làng đều đồn đoán, nói bà đã bị Trường Tiên bắt đi. Nhiều năm sau, Bạch Trung Thiên một lần nữa quay trở lại trấn Bạch Vân. Những truyền thuyết quái dị như Trường Tiên cưới vợ, cắt giấy gọi hồn, gánh hát ma, hay chiếc ô giấy đỏ đã phủ lên trấn Bạch Vân một tấm màn huyền bí. Có dân làng trong lúc đi đốn củi lại tình cờ nhìn thấy Trường Tiên rước dâu. Bạch Trung Thiên quyết tâm lần theo manh mối, phơi bày sự thật ra ánh sáng.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 12, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trình Vũ Phong","avatar":""},{"name":"Trần Diệp Linh","avatar":""},{"name":"Hầu Thụy Thanh","avatar":""},{"name":"Vương Diệp","avatar":""},{"name":"Thành Siêu Việt","avatar":""},{"name":"Thái Minh Na","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chang She Qu Qi","长蛇娶亲","长蛇娶妻"]', 1784690324130);
