INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-phap-y-ngu-tu-tieu-ngo-tac-phan-2', 'Nữ Pháp Y (Ngự Tứ Tiểu Ngỗ Tác) (Phần 2)', 'The Imperial Coroner (Season 2)', 'https://phimimg.com/upload/vod/20260115-1/ced80a3951ba66119ab8d53fd11d316e.jpg', 'https://phimimg.com/upload/vod/20260115-1/00a94d9c229db057194649051ae26c58.jpg', '<p>Tiếp nối siêu phẩm đầy tiềm năng, dàn diễn viên cũ trở lại, câu chuyện sau hôn nhân của An Quận vương Tiêu Cẩn Du lạnh lùng và cô nàng ngỗ tác ngự ban Sở Sở. Sự nghiệp, tình cảm, tầm cỡ đều được nâng cấp. Họ cùng bắt tay với nhóm thiếu niên thuộc Tam Pháp Ty, truy tìm sự thật, phá kỳ án, đồng tâm hiệp lực bảo vệ sự bình yên cho Đại Đường.</p>', 'Tập 28', 36, 'series', 'ongoing', 23, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Tử Kỳ","avatar":""},{"name":"Tô Hiểu Đồng","avatar":""},{"name":"Dương Đình Đông","avatar":""},{"name":"Triệu Nghiêu Kha","avatar":""},{"name":"Trương Thần Tiêu","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["御赐小仵作 2","御赐小仵作 第二季","Yu Ci Xiao Wu Zuo 2","Yu Ci Xiao Wu Zuo","御赐小仵作 第2季","Yu Ci Xiao Wu Zuo Di Er Ji","Detektif Kerajaan S2","御用検事S2","황실 검시관","어사소오작: 미스터리 검시관","어사소오작 시즌2","机智女法医","Jade The Imperial Coroner","Императорский коронер 2","御賜小仵作","御賜小仵作 第二季","The Imperial Coroner","The Imperial Coroner S2","The Imperial Coroner Season 2","Ngự Tứ Tiểu Ngỗ Tác 2","御赐小仵作"]', 1784690324130);
