INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nu-phap-y-ngu-tu-tieu-ngo-tac-phan-2', 'Nữ Pháp Y (Ngự Tứ Tiểu Ngỗ Tác) (Phần 2)', 'The Imperial Coroner (Season 2)', 'nữ pháp y (ngự tứ tiểu ngỗ tác) (phần 2) the imperial coroner (season 2) vương tử kỳ tô hiểu đồng dương đình đông triệu nghiêu kha trương thần tiêu 御赐小仵作 2 御赐小仵作 第二季 yu ci xiao wu zuo 2 yu ci xiao wu zuo 御赐小仵作 第2季 yu ci xiao wu zuo di er ji detektif kerajaan s2 御用検事s2 황실 검시관 어사소오작: 미스터리 검시관 어사소오작 시즌2 机智女法医 jade the imperial coroner императорский коронер 2 御賜小仵作 御賜小仵作 第二季 the imperial coroner the imperial coroner s2 the imperial coroner season 2 ngự tứ tiểu ngỗ tác 2 御赐小仵作', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-tinh-yeu-bat-ngo-den', 'Một Tình Yêu Bất Ngờ Đến', 'My Page In The 90s', 'https://phimimg.com/upload/vod/20260123-1/2471928706147631054a87c6fd81f25d.jpg', 'https://phimimg.com/upload/vod/20260123-1/cc96ae16450a78d6d81fb6d072ee1a39.jpg', '<p>Một bộ phim hài tình cảm nhẹ nhàng, tràn ngập tiếng cười. Khi một streamer tư vấn tình cảm của năm 2025 bị cuốn vào cuốn tiểu thuyết lãng mạn kiểu cũ, cô đã chạm trán anh sếp tổng ngang ngược năm 1999, trông tưởng vô hại mà rất xảo quyệt. Màn đối đầu cuối cùng giữa lối mòn và gậy ông đập lưng ông của cả hai chính thức mở ra, ai sẽ là người giành phần thắng sau cùng? Để trở về thế giới hiện thực quen thuộc, streamer tư vấn tình cảm Lâm Hoan Nhi bắt đầu tung ra hàng loạt chiêu thức chinh phục sếp tổng ngang ngược Cao Hải Minh. Thế nhưng, thông minh quá hóa phản tác dụng. Khi đã dốc hết sức vượt ải và buộc phải rời khỏi thế giới trong sách, cô mới nhận ra mình đã lún sâu từ lâu, chẳng nỡ rời đi. Từ &quot;muốn đi mà vẫn phải ở lại&quot; đến &quot;muốn ở lại nhưng vẫn phải đi&quot;, ở đoạn kết của câu chuyện, liệu những người yêu nhau có thể nên duyên trọn vẹn?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 16, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Tinh Húc","avatar":""},{"name":"Vương Ngọc Văn","avatar":""},{"name":"Mã Tư Siêu","avatar":""},{"name":"Tằng Mộng Tuyết","avatar":""},{"name":"Vu Tường","avatar":""},{"name":"Đinh Nhiên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c1