INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhan-vat-chinh-va-nhung-nguoi-ban', 'Nhân Vật Chính Và Những Người Bạn', 'Roast', 'nhân vật chính và những người bạn roast shaogang zhang fan zhiyi 主咖 zhu ka he ta de peng you men main guest and their friends 主咖和ta的朋友们', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguyen-toi-2-nguon-goc-toi-loi-2', 'Nguyên Tội 2 (Nguồn Gốc Tội Lỗi 2)', 'Original Sin 2', 'https://phimimg.com/upload/vod/20260131-1/8f95381174a85cdf6ab811ef4faca528.jpg', 'https://phimimg.com/upload/vod/20260131-1/0d9ad3d8ecc179ba10effeaabc6bb481.jpg', '<p>Trong một khu chung cư cũ, hai tội phạm đang bị truy nã chết một cách kỳ lạ. Bác sĩ pháp y Đới Dữ và cảnh sát hình sự Trịnh Minh cùng nhau lần theo những nghi vấn trong vũng máu và xác chết được quấn như xác ướp, phát hiện mọi manh mối đều dẫn về một vụ bắt cóc xảy ra hơn mười năm trước.&nbsp; Sau khi hung thủ gây ra vụ bắt cóc chết thảm, người nhà nạn nhân lại bất ngờ tự sát. Đới Dữ phát hiện nghi phạm không ai khác chính là Tạ Đồng – mối tình đầu không thể quên trong lòng anh.&nbsp; Một vụ án khác lại xảy ra: ông chủ một công ty bất động sản bị đánh chết tại chỗ. Nghi phạm bốn lần thay đổi lời khai để thoát tội, nhưng Trịnh Minh nhận ra, đằng sau những lời nói dối ấy là sự phản kháng tuyệt vọng của ba con người bị dồn đến đường cùng.&nbsp; Một nghi phạm giả chết, sau đó lại bị chính người vợ sát hại. Từ một đoạn tóc bị cắt, Đới Dữ suy đoán rằng vẫn còn một nghi phạm khác đang lẩn trốn. Trịnh Minh phát hiện những điểm tương đồng giữa hai vụ án này trong một hồ sơ cũ, từ đó quyết định gộp án điều tra.&nbsp; Người thầy của Trịnh Minh – Đới Thụy Lân, cũng chính là viên cảnh sát từng thụ lý vụ án năm xưa, bất ngờ bị sát hại, khiến vụ án cũ càng rơi vào bế tắc. Cuối cùng, Đới Dữ và Trịnh Minh dựa vào một mẫu tinh trùng không có đuôi do nghi phạm để lại, thành công vạch mặt và bắt giữ hung thủ thật sự, khép lại chuỗi án mạng kéo dài nhiều năm.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 11, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Hạo Hiên","avatar":""},{"name":"Trần Hoàn","avatar":""},{"name":"Lý Hạo Phi","avatar":""},{"name":"Lâm Tĩnh","avatar":""},{"name":"Đinh Chí Dũng","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yuan Zui","原罪2","原罪"]', 1784690324130);
