INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nua-tinh-nua-me', 'Nửa Tỉnh Nửa Mê', 'Half-awake', 'https://phimimg.com/upload/vod/20260117-1/a5d267fd95c4d3d5012d42a23ea33692.jpg', 'https://phimimg.com/upload/vod/20260117-1/edfd650c6934413436de6264c3a7bcd9.jpg', '<p>Ông trùm thương mại Cố Dịch Tiêu nổi tiếng lạnh lùng tàn nhẫn, chỉ riêng cô thư ký Diệp Tinh Vãn là điểm yếu chí mạng của anh. Vì một hiểu lầm từ 15 năm trước, anh đã giăng bẫy để khống chế và dày vò cô. Nhưng cô gái Diệp Tinh Vãn với vẻ ngoài tưởng chừng yếu mềm ấy đã không còn cam chịu. Cô tương kế tựu kế, lấy chính bản thân làm mồi nhử, cuốn Cố Dịch Tiêu vào một mối tình đầy đau đớn khi mà yêu và hận cứ thế đan xen. Đến cuối cùng, cô cũng chấp nhận sự sám hối của Cố Dịch Tiêu và dấy lên cho anh tia hy vọng được cứu rỗi mong manh. Thế nhưng, liệu trái tim cô có thể thật sự được bình yên và hạnh phúc hay không? Đó là câu hỏi vẫn còn đang bỏ ngỏ.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 14, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Tịch Tịch","avatar":""},{"name":"Tạ Dư Vọng","avatar":""},{"name":"Lư Hi","avatar":""},{"name":"Trương Miện Thần","avatar":""},{"name":"Triệu Dư Hi","avatar":""},{"name":"Triệu Đông Trạch","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ban Xing","Half Awake","半醒"]', 1784690324130);
