INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-lon-noi-thanh-pho-nho', 'Chuyện Lớn Nơi Thành Phố Nhỏ', 'The Dream Maker', 'https://phimimg.com/upload/vod/20260112-1/c85f396d99015e905c3fc389ecf443b0.jpg', 'https://phimimg.com/upload/vod/20260112-1/cb76d589c1a6a9adbc61d441d9487a46.jpg', '<p>Để thúc đẩy phát triển kinh tế, huyện Bình Xuyên quyết định thành lập trấn Nguyệt Hải. Hai cán bộ trẻ có năng lực và cá tính nổi bật là Lý Thu Bình và Trịnh Đức Thành, kiên trì lý tưởng &quot;thành phố của nhân dân do nhân dân xây dựng&quot;, đã tận dụng chính sách cải cách và Văn kiện số 1 Trung ương Đảng Cộng sản Trung Quốc để tìm ra con đường đột phá. Không sử dụng ngân sách nhà nước, họ dẫn dắt hàng chục nghìn nông dân góp vốn, liên doanh, từng bước xây dựng một đô thị hiện đại trên vùng bãi bồi hoang vu. Đây được mô tả như một kỳ tích &quot;từ con số không&quot;, không chỉ làm thay đổi diện mạo vùng đất nghèo mà còn xoay chuyển vận mệnh của hàng trăm nghìn người nông dân Trung Quốc. Lý Thu Bình, Trịnh Đức Thành, Giải Xuân Lai, Cao Tuyết Mai cùng những người kiến tạo thành phố dám nghĩ dám làm, tiên phong đổi mới, đã viết nên một chương rực rỡ dưới ánh nắng chói chang của thập niên 1980.</p>', 'Tập 39', 40, 'series', 'ongoing', 22, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Lệ Dĩnh","avatar":""},{"name":"Huỳnh Hiểu Minh","avatar":""},{"name":"Trần Minh Hạo","avatar":""},{"name":"Chu Viên Viên","avatar":""},{"name":"Tần Tuấn Kiệt","avatar":""},{"name":"Cảnh Lạc","avatar":""},{"name":"Dư Ngai Lỗi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["造城者","소성대사","The City Maker","小城大事"]', 1784690324130);
