INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chieu-ly-phu', 'Chiêu Ly Phú', 'Elegy Of Zhao Li', 'https://phimimg.com/upload/vod/20260130-1/6f5f8ebdbe634b7556a2cd56d7977568.jpg', 'https://phimimg.com/upload/vod/20260130-1/dec4eca320d6fc4de2f1b5aca4bfb811.jpg', '<p>Giang Ly, con gái của Thái phó, vì muốn từ chối cuộc hôn nhân sắp đặt nên thường cùng tri kỷ là A Chiêu tới lánh đời tại Văn Hương Các. Sau khi bị ép gả cho Tả tướng quân và vào cung, cô bất ngờ phát hiện ra A Chiêu thực chất chính là đương kim hoàng thượng. Từ đó, Giang Ly bị cuốn sâu vào vòng xoáy tình yêu và những bí mật chốn hoàng cung. Hai người đã cùng nhau sát cánh dẹp loạn, vạch trần mọi âm mưu thủ đoạn. Sau khi trải qua tất cả sóng gió và hóa giải mọi hiểu lầm, họ quyết định bên nhau trọn đời.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Phùng Diệu Anh","avatar":""},{"name":"Lục Đông Túc","avatar":""},{"name":"Đông Tiểu Bái","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["昭离赋"]', 1784690324130);
