INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('wonder-man', 'Wonder Man', 'Wonder Man', 'https://phimimg.com/upload/vod/20260129-1/e30f4e5d3dfd6ab0ec28b18504bd4650.jpg', 'https://phimimg.com/upload/vod/20260129-1/0f5e9ce9a75f24b605401b67ceb193f0.jpg', '<p>Simon Williams, một diễn viên tài năng nhưng luôn chuẩn bị quá mức, khiến anh tự làm khó mình trong mắt giới làm phim. Cuộc đời Simon rẽ sang hướng khác khi anh gặp Trevor Slattery – “Mandarin giả” quen thuộc của MCU – người dần trở thành vừa là người thầy, vừa là bạn đồng hành của anh.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Yahya Abdul-Mateen II","avatar":""},{"name":"Arian Moayed","avatar":""},{"name":"X Mayo","avatar":""},{"name":"Ben Kingsley","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Marvel’s Wonder Man","Диво-людина","Marvel Television''s Wonder Man","Marvel Spotlight: Wonder Man","Wonder Man"]', 1784690324130);
