INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-gui-tuoi-tre-cua-toi', 'Thư gửi tuổi trẻ của tôi', 'A Letter to My Youth', 'https://phimimg.com/upload/vod/20260129-1/e9e6ea66d5b9724f82b98dd68ce8dc68.jpg', 'https://phimimg.com/upload/vod/20260129-1/dbcbe9ddd20c200b6d531a40922f99aa.jpg', '<p>Một thiếu niên nổi loạn và một người quản lý trầm lặng tạo nên sợi dây gắn kết lạ thường tại mái ấm nọ khi cả hai thỏa hiệp với quá khứ đau thương.</p>', 'Full', 1, 'single', 'completed', 25, 2026, 'Vietsub', 'FHD', 'Indonesia', 0, '[{"name":"Millo Taslim","avatar":""},{"name":"Cleo Haura","avatar":""},{"name":"Aqila Herby","avatar":""},{"name":"Jordan Omar","avatar":""},{"name":"Halim Latuconsina","avatar":""},{"name":"Diandra Salsabila Lubis","avatar":""},{"name":"Fendy Chow","avatar":""},{"name":"Agla Artalidia","avatar":""},{"name":"Wilza Lubis","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Gəncliyimə Məktub","Surat untuk Masa Mudaku","SUMM"]', 1784690324130);
