INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phan-quyet-yeu-ta', 'Phán Quyết Yêu Tà', 'Evil''s Return', 'https://phimimg.com/upload/vod/20260127-1/1afe0be0dbb928473794ee7ff83fdb07.jpg', 'https://phimimg.com/upload/vod/20260127-1/0e245843335dd749a5155adf05779003.jpg', '<p>Loạn lạc cuối thời nhà Đường, dịch bệnh hoành hành, thiên hạ lan truyền lời đồn rằng yêu nữ Ngô Song đã biến thành một tà linh, gây ra tai họa cho nhân loại. Tuy nhiên, ca ca của Ngô Song là Ngô Lệnh cũng là một Bất Lương Nhân chưa bao giờ tin rằng muội muội lương thiện của mình là yêu nữ mà người ta nói. Quyết rửa oan cho muội muội, Ngô Lệnh liều lĩnh thi triển bí thuật “khâu xác hoàn hồn”, hồi sinh Ngô Song đã bị chém đầu. Trong bóng đêm u ám của đền Ôn thần, hắn bày ra một cục diện quỷ dị để xét xử kẻ ác thật sự, cầu mong được minh oan và đòi lại công bằng.</p>', 'Full', 1, 'single', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Han Dong","avatar":""},{"name":"Dou Guiyu","avatar":""},{"name":"Song Haijie","avatar":""},{"name":"Zhao Daixi","avatar":""},{"name":"Liu Xu","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Judging the Evil Spirits","Pan Yao Xie","The Judgement of Demons and Evils","判妖邪"]', 1784690324130);
