INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-tim-dau-vet', 'Truy Tìm Dấu Vết', 'Tracks In The Snow', 'https://phimimg.com/upload/vod/20260120-1/2ed5110806af3dd613afdd3a7d459d74.jpg', 'https://phimimg.com/upload/vod/20260120-1/ab5dccda90a19c0f8ff69edf00faf4fa.jpg', '<p>Trò bói toán tà thuật của một người nổi tiếng trên mạng chuyên lừa đảo đã dẫn đến một vụ bắt cóc kỳ quái. Trong vòng 24 giờ, âm mưu chồng chất âm mưu, che giấu những bí mật không thể nói ra. Mối quan hệ giữa ba nhóm nhân vật vật đan xen phức tạp. Trong khoảng thời gian 24 giờ, từng lớp, từng lớp âm mưu vốn ẩn dưới mặt nước tưởng như bình lặng dần được lật mở. Hotgirl mạng xinh đẹp, bọn bắt cóc chợ đen, ông chủ hiệu cầm đồ lần lượt xuất hiện; trên hành trình chạy đua với thời gian, hoặc cứu người, mỗi kẻ đều phô diễn thủ đoạn của mình, dần dần lộ ra những bộ mặt xấu xí.</p>', 'Tập 19', 19, 'series', 'ongoing', 13, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Khương Siêu","avatar":""},{"name":"Sử Nguyên Đình","avatar":""},{"name":"Trạm Giai Minh","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yanbian 24 Hours","Yan Bian Shi Er Shi Chen","延边十二时辰","Xun Xue Mi Zong","寻雪迷踪"]', 1784690324130);
