INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('truy-tim-dau-vet', 'Truy Tìm Dấu Vết', 'Tracks In The Snow', 'truy tìm dấu vết tracks in the snow khương siêu sử nguyên đình trạm giai minh yanbian 24 hours yan bian shi er shi chen 延边十二时辰 xun xue mi zong 寻雪迷踪', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuyet-thu-tran-sang-dong', 'Tuyết Thu Tràn Sang Đông', 'Loving Strangers', 'https://phimimg.com/upload/vod/20260111-1/56d7f41b9cbd62d635cba39c879cb742.jpg', 'https://phimimg.com/upload/vod/20260111-1/998c6ca2a9d2d7b308d6f294015c80f2.jpg', '<p>Bộ phim là câu chuyện chữa lành về hai con người gặp khó khăn, cùng an ủi và sưởi ấm nhau giữa bùn lầy cuộc sống. Châu Ngộ An sinh ra trong nghèo khó và phải gánh nợ cho bố, gặp được Khương Gia Tề lúc anh đang vướng mắc cả về gia đình và sự nghiệp. Tình hình đấu đá ở công ty đã đẩy hai con người vốn không quan hệ gì lại gần nhau. Vì Khương Gia Tề quyết bảo vệ lẽ phải, khiến CEO Cố Thần mất đi cơ hội xin cấp phép thuốc mới, Cố Thần đã thuê Châu Ngộ An để tìm cách đuổi Khương Gia Tề đi. Bắt đầu từ hiểu lầm, Khương Gia Tề và Châu Ngộ An dần hiểu về nhau, Châu Ngộ An nhận ra khía cạnh ấm áp nhất của Khương Gia Tề, cuối cùng hai người cứu rỗi lẫn nhau, cùng nhau thoát khỏi cuộc sống tăm tối. Dù nam nữ chính đều chìm xuống đáy cuộc đời nhưng vẫn luôn đối mặt bằng thái độ tích cực, không gục ngã trước khó khăn, họ cùng dìu dắt nhau vượt qua bao trắc trở. Cả bộ phim kể lại câu chuyện hai người đi từ quen biết đến hiểu lầm, rồi thấu hiểu và cứu rỗi nhau một cách đầy ấm áp và chữa lành.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 9, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Hựu Đình","avatar":""},{"name":"Trương Tử Phong","avatar":""},{"name":"Trương Tân Thành","avatar":""},{"name":"Giang Nhất Nhiên","avatar":""},{"name":"Từ Dật Hề","avatar":""},{"name":"Tạ Gia Nghi","avatar":""},{"name":"Dương Nhất Oa","avatar":""},{"name":"Hứa Tuyền","avatar":""},{"name":"Từ Cang","avatar":""},{"name":"Vương Hạo Nhiên","avatar":""},{"name":"Tần Giai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["我的大叔（中国版）","谢谢你，听见我","谢谢你听见我","你一定要幸福呀","나의 아저씨","Спасибо, что услышали меня","Loving Stranger","秋雪漫过的冬天"]', 1784690324130);
