INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tuyet-thu-tran-sang-dong', 'Tuyết Thu Tràn Sang Đông', 'Loving Strangers', 'tuyết thu tràn sang đông loving strangers triệu hựu đình trương tử phong trương tân thành giang nhất nhiên từ dật hề tạ gia nghi dương nhất oa hứa tuyền từ cang vương hạo nhiên tần giai 我的大叔（中国版） 谢谢你，听见我 谢谢你听见我 你一定要幸福呀 나의 아저씨 спасибо, что услышали меня loving stranger 秋雪漫过的冬天', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguy-trang-gia-toc', 'Ngụy Trang Gia Tộc', 'Disguised Family', 'https://phimimg.com/upload/vod/20260125-1/5eabf3064a8eea2f2386d2e354841530.jpg', 'https://phimimg.com/upload/vod/20260125-1/6a9b3436e60102c84f6ff5458cd65f5e.jpg', '<p>Đặc vụ hàng đầu Nam Thái Vân để hoàn thành nhiệm vụ đã giả làm vợ chồng với đặc vụ cực kỳ tự luyến Nhan Anh Tuấn, cùng con gái Nam Tiểu Đường ngụy trang thành một &#39;gia đình ba người&#39; hạnh phúc. Gia đình ba người họ đã cùng nhau vượt qua những góc khuất đầy rẫy mưu mô trong giới hào môn, cuối trọng trở thành khách quý của những bữa tiệc thượng lưu, và &#39;cặp vợ chồng hờ&#39; cũng từ đó mà nảy sinh tình cảm thật lòng.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Leo Yang","avatar":""},{"name":"Carmen Tong","avatar":""},{"name":"Mu Le''en","avatar":""},{"name":"Yu Yifu","avatar":""},{"name":"Feng Mi","avatar":""},{"name":"Wang Zhonghao","avatar":""},{"name":"Zhang Xinyue","avatar":""},{"name":"Zhu Hong","avatar":""},{"name":"Fan Yize","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["伪装家族"]', 1784690324130);
