INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oan-danh', 'Oán Danh', 'Death Name', 'https://phimimg.com/upload/vod/20260125-1/ec3ec117f62974e937bf7beda1db730f.jpg', 'https://phimimg.com/upload/vod/20260125-1/424a68c4d12e501c59356a19b5bb3a86.jpg', '<p>Một phụ nữ Mỹ gốc Hàn trẻ tuổi khao khát tìm hiểu sâu hơn về cội nguồn của mình, nhưng không hề hay biết rằng càng đào sâu vào quá khứ gia đình, cô càng vô tình đánh thức một lời nguyền chết chóc đã bị chôn vùi từ lâu.</p>', 'Full', 1, 'single', 'completed', 9, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Amy Keum","avatar":""},{"name":"Kevin Woo","avatar":""},{"name":"Vana Kim","avatar":""},{"name":"Joseph Lim Kim","avatar":""},{"name":"Eliza Shin","avatar":""},{"name":"Alice Bang","avatar":""},{"name":"Michelle Sun","avatar":""},{"name":"April Valentine","avatar":""},{"name":"Jas Wang","avatar":""},{"name":"Andy Han","avatar":""},{"name":"Jason Her","avatar":""},{"name":"Jess Matney","avatar":""},{"name":"Desiree Mee Jung","avatar":""},{"name":"Caleb Y Moon","avatar":""},{"name":"John J. Shim","avatar":""},{"name":"David Christian Welborn","avatar":""},{"name":"Gracie Jackline","avatar":""},{"name":"Keiko Bell","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Death Name"]', 1784690324130);
