INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mo-mang-tam-mat', 'Mở Mang Tầm Mắt', 'Eyes Of The Sky', 'http://vcover-hz-pic.wetvinfo.com/vcover_hz_pic/0/739bzuv1tyz5pbc1768200914322/0?imageMogr2/thumbnail/1100x.jpg', 'https://phimimg.com/upload/vod/20260114-1/89c819827072ede7c02cfed666041e25.jpg', '<p>Một vụ nổ bất ngờ khiến Hoắc Minh mất trí nhớ, buộc phải mưu sinh với thân phận một nhân viên giao hàng. Không lâu sau, anh bị cuốn vào những sóng gió thương trường xoay quanh Lâm Vân. Trong quá trình điều tra sự thật, Hoắc Minh bị tấn công và chấn thương vùng đầu, vô tình kích hoạt con chip AI cấy trong não, từ đó sở hữu năng lực siêu phàm. Nhờ sức mạnh đặc biệt ấy, anh giúp Lâm Vân đối phó kẻ thù, bảo vệ và củng cố công ty, đồng thời từng bước khám phá thân phận thật sự của bản thân cùng bí mật liên quan đến bố mình. Cuối cùng, giữa hai người nảy sinh tình cảm chân thành. Họ cùng nhau trưởng thành và viết nên một câu chuyện đời đầy cảm hứng.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Sâm","avatar":""},{"name":"Chu Cận Đồng","avatar":""},{"name":"Hướng Hân","avatar":""},{"name":"Bành Ất Hàng","avatar":""},{"name":"Bộ Tử Dĩnh","avatar":""},{"name":"Trương Đạt Nguyên","avatar":""},{"name":"Lý Khởi Ca","avatar":""},{"name":"Lý Nặc Phi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Greatly to Widen One''s Horizon","大开眼界"]', 1784690324130);
