INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mo-mang-tam-mat', 'Mở Mang Tầm Mắt', 'Eyes Of The Sky', 'mở mang tầm mắt eyes of the sky vương sâm chu cận đồng hướng hân bành ất hàng bộ tử dĩnh trương đạt nguyên lý khởi ca lý nặc phi greatly to widen one''s horizon 大开眼界', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuu-vy-khong-the-giau', 'Cửu Vỹ Không Thể Giấu', 'Eternal Love Of The Fox', 'https://phimimg.com/upload/vod/20260122-1/83432bc81f0fa5db1cd81636a7ec8eb2.jpg', 'https://phimimg.com/upload/vod/20260122-1/ac44f1453a80a25def72c00f748e6a6e.jpg', '<p>Hoắc Trung Nhân, chủ bộ của thành Mộc Hề, đột ngột mất tích một cách bí ẩn trong cung. Để tìm kiếm tung tích của phụ thân, con gái ông là Hoắc Hương Cửu cải trang thành cung nữ, lén xâm nhập hoàng cung. Tuy nhiên, cô tình cờ phát hiện ra thân phận thực sự của phong thần quyền lực triều đình Phong Mặc Trần chính là hồ li tinh nghìn năm tuổi. Hai người còn vô tình hoán đổi linh hồn cho nhau. Cùng lúc đó, trong cung lại có rất nhiều sự kiện quái dị, khó lý giải liên tiếp xảy ra, là do yêu ma quỷ quái quấy phá, hay có người phàm đứng sau khuấy động phong ba? Mỗi người mang theo mục đích riêng, Hoắc Hương Cửu và Phong Mặc Trần buộc phải đồng hành, lần lượt phá giải từng vụ án kỳ lạ không tưởng, tạo nên vô số tình huống dở khóc dở cười. Đồng thời, họ cũng dần hé lộ một mối tình bảy kiếp sâu nặng và lay động lòng người bị chôn vùi suốt ngàn năm.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Nguyệt Nam","avatar":""},{"name":"Tôn Trần Tuấn","avatar":""},{"name":"Trương Cường Minh","avatar":""},{"name":"Trần Chương","avatar":""},{"name":"Công Hãn Lâm","avatar":""},{"name":"Tống Phong Nghiêm","avatar":""},{"name":"Vương Hành Vĩ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"