INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-mang-ten-em', 'Bí Mật Mang Tên Em', 'Secret By My Name', 'https://phimimg.com/upload/vod/20260115-1/83081706fc17ccb37fcfb88e0b5e5b69.jpg', 'https://phimimg.com/upload/vod/20260115-1/dbeb94909bed1e1f510ac1af02a9247f.jpg', '<p>Khi Đàm Kiếm Phi - tân tổng giám đốc Tập đoàn Đàm Thị - đang rơi vào cơn khủng hoảng, thì Lý Thư Tĩnh, người yêu cũ năm xưa của anh, bất ngờ được bổ nhiệm vào công ty. Hai người nhanh chóng đối đầu gay gắt trong cuộc chiến quyền lực đầy toan tính. Giữa những màn đấu trí căng thẳng, ngọn lửa tình yêu tưởng chừng đã nguội lạnh lại bùng cháy. Thế nhưng Đàm Kiếm Phi không hề hay biết rằng Lý Thư Tĩnh bước chân vào công ty với mục đích báo thù, để điều tra sự thật đằng sau cái chết của cha mình. Khi chân tướng được phơi bày, thứ ngăn cách hai người không chỉ là ân oán gia tộc, mà còn là một cái bẫy tình yêu đã được sắp đặt vô cùng tinh vi.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 14, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hồng Tiêu","avatar":""},{"name":"Dương Binh Trác","avatar":""},{"name":"Trần Thụy Phong","avatar":""},{"name":"Trịnh Thừa Thừa","avatar":""},{"name":"Hà Diệc Khả","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["火锅爱汤圆","叫作你的秘密"]', 1784690324130);
