INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-la-mu-quang-duc-phan-2', 'Yêu Là Mù Quáng: Đức (Phần 2)', 'Love Is Blind: Germany (Season 2)', 'https://phimimg.com/upload/vod/20260125-1/06751825d1c19651c35c3fd5a72d6864.jpg', 'https://phimimg.com/upload/vod/20260125-1/c865f2c1654fc0681cfc7bc074c46b11.jpg', '<p>Chương trình thử nghiệm này đã đến Đức, mang đến cơ hội cho những người độc thân nơi đây tìm kiếm tình yêu đích thực và cam kết gắn bó trọn đời, trước cả khi họ gặp mặt trực tiếp.</p>', 'Hoàn Tất (10/10)', 10, 'tvshows', 'completed', 15, 2026, 'Vietsub', 'FHD', 'Đức', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Love Is Blind: Germany"]', 1784690324130);
