INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-chat-phan-10', 'Sống Chất (Phần 10)', 'Queer Eye (Season 10)', 'https://phimimg.com/upload/vod/20260124-1/65555388f6e446d925e463ca4104c702.jpg', 'https://phimimg.com/upload/vod/20260124-1/efe083a3d06bdabcfa304bc365297078.jpg', '<p>Một nhóm &#39;Fab Five&#39; hoàn toàn mới sẽ đưa ra những lời khuyên cho phái mạnh về thời trang, chăm sóc diện mạo, ẩm thực, văn hóa và thiết kế trong phiên bản tái khởi động hiện đại của series thực tế từng giành giải Emmy này.</p>', 'Hoàn Tất (5/5)', 5, 'tvshows', 'completed', 14, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Antoni Porowski","avatar":""},{"name":"Tan France","avatar":""},{"name":"Karamo Brown","avatar":""},{"name":"Jonathan Van Ness","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["퀴어 아이","Натурал глазами гея","#QE","QE","Queer Eye For The Straight Guy","More than a makeover","Queer Eye"]', 1784690324130);
