INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('song-chat-phan-10', 'Sống Chất (Phần 10)', 'Queer Eye (Season 10)', 'sống chất (phần 10) queer eye (season 10) antoni porowski tan france karamo brown jonathan van ness 퀴어 아이 натурал глазами гея #qe qe queer eye for the straight guy more than a makeover queer eye', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-ha-lac-nhat', 'Trường Hà Lạc Nhật', 'River Sunset', 'https://phimimg.com/upload/vod/20260102-1/adea5c56811d857a22ed981f06a07e60.jpg', 'https://phimimg.com/upload/vod/20260102-1/9e93a102b8182a87e109352f0ce1577c.jpg', '<p>Loạt phim này, lần đầu tiên, đặt trải nghiệm của Trung Quốc trong Thế chiến thứ hai vào bối cảnh toàn cầu. Để hỗ trợ các cuộc không kích của Mỹ vào Tokyo, Trung Quốc đã cử một điệp viên chiến lược cấp cao, người sở hữu danh tính song song của cả Trung Quốc và Nhật Bản, cùng một học viên y khoa quân sự trẻ tuổi đến hòn đảo Sanzao – nơi được canh giữ cực kỳ chặt chẽ và được coi như một “nhà tù nổi”. Bốn mươi ngày sau, diễn biến của cuộc chiến ở Thái Bình Dương đã có những thay đổi đáng kể. Điều gì đã xảy ra trong suốt bốn mươi ngày đó? Tại sao cả mười sáu chiếc máy bay ném bom B-25 đều bị rơi ở vùng tây tỉnh Chiết Giang? Làm thế nào mà chiến dịch này đã thay đổi diễn biến của cuộc chiến ở khu vực Đông? Loạt phim sẽ giúp khán giả trên khắp thế giới giải đáp những bí ẩn này.</p>', 'Hoàn Tất (44/44)', 44, 'series', 'completed', 11, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Lỗ Nhất","avatar":""},{"name":"Trương Quân Ninh","avatar":""},{"name":"Trương Thần Quang","avatar":""},{"name":"Trương Tụng Văn","avatar":""},{"name":"Casper Van Dien","avatar":""},{"name":"Mộ Phan Long","avatar":""},{"name":"Thiệu Đồng","avatar":""},{"name":"Mạnh Thiệu Trọng","avatar":""},{"name":"Lâm Trừng","avatar":""},{"name":"Kim Sĩ Kiệt","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["长河落日",