INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bat-coc-elizabeth-smart', 'Bắt Cóc: Elizabeth Smart', 'Kidnapped: Elizabeth Smart', 'https://phimimg.com/upload/vod/20260124-1/fa57fdcdd12610eafb04b0ab6efe583b.jpg', 'https://phimimg.com/upload/vod/20260124-1/c4784cbe617463f6071b16d43edfb7d3.jpg', '<p>Trong bộ phim tài liệu này, vụ bắt cóc kinh hoàng của thiếu nữ 14 tuổi Elizabeth Smart tại nhà riêng ở Utah được hé lộ qua lời kể của nạn nhân và những tư liệu chưa từng công bố.</p>', 'Full', 1, 'single', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Elizabeth Smart","avatar":""},{"name":"Steevan Glover","avatar":""},{"name":"John Stableforth","avatar":""},{"name":"Brian David Mitchell","avatar":""},{"name":"Wanda Barzee","avatar":""},{"name":"Soledad O''Brien","avatar":""},{"name":"Katie Couric","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Kidnapped: Elizabeth Smart"]', 1784690324130);
