INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bat-coc-elizabeth-smart', 'Bắt Cóc: Elizabeth Smart', 'Kidnapped: Elizabeth Smart', 'bắt cóc: elizabeth smart kidnapped: elizabeth smart elizabeth smart steevan glover john stableforth brian david mitchell wanda barzee soledad o''brien katie couric kidnapped: elizabeth smart', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-boi-dieu-lam-noi-tren-lung-ngua', 'Mã Bối Diêu Lam (Nôi Trên Lưng Ngựa)', 'The Red Cradle', 'https://phimimg.com/upload/vod/20260114-1/193f04f79f96a05ac099ffa75145f48e.jpg', 'https://phimimg.com/upload/vod/20260114-1/c4e5de970189a45ae0a0bcd171fb2470.jpg', '<p>Bộ phim kể về câu chuyện diễn ra vào mùa thu đông năm 1946. Do tình hình chiến tranh thay đổi, Trường Mầm non số 2 thành phố Diên An được lệnh thành lập một đội hộ tống, đưa 136 đứa trẻ đến khu vực an toàn. Đây là cuộc hành trình được ví như một &quot;Cuộc Vạn lý Trường chinh tí hon&quot;. Giữa mưa bom bão đạn và điều kiện môi trường khắc nghiệt, toàn thể nhân viên trông giữ trẻ cùng các chiến sĩ đã sẵn sàng hy sinh xương máu để bảo vệ sự an toàn cho các em. Cuối cùng, họ đã hoàn thành kỳ tích vẻ vang ấy.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 11, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lam Doanh Oánh","avatar":""},{"name":"Lưu Trí Dương","avatar":""},{"name":"Chu Thiết","avatar":""},{"name":"Tiêu Nhân","avatar":""},{"name":"Ngưu Bắc Nhâm","avatar":""},{"name":"Dương Chí Cang","avatar":""},{"name":"Lưu Uy","avatar":""},{"name":"Nhạc Lệ Na","avatar":""},{"name":"Hà Chính Quân","avatar":""},{"name":"Lưu Vũ Kiều","avatar":""},{"name":"Trần Quan Anh","avatar":""},{"name":"Khương Phức Di","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The.Red.Cradle","马背摇篮"]', 1784690324130);
