INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('kaguya-cong-chua-vu-tru', 'Kaguya: Công Chúa Vũ Trụ!', 'Cosmic Princess Kaguya!', 'kaguya: công chúa vũ trụ! cosmic princess kaguya! yuko natsuyoshi anna nagase saori hayami miyu irino yuma uchida yoshitsugu matsuoka yoshino aoyama konomi kohara rie kugimiya fairouz ai natsuki hanae sarasa shoji chō kaguya-hime! chou kaguya-hime! cosm♪c princess kaguya! 초 가구야 공주! 超时空辉耀姬！ putri kosmik kaguya! 超時空輝耀姬！ 超かぐや姫！', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-giac-khi-rung-dong-la-day', 'Cảm Giác Khi Rung Động Là Đây', 'This Is The Feeling Of Love', 'https://phimimg.com/upload/vod/20260116-1/b33ce264b7f8bf4d27cae85473619919.jpg', 'https://phimimg.com/upload/vod/20260116-1/a76fe0b3080d51699a0b3994858c9676.jpg', '<p>Nữ hoàng thị phi vướng vào rắc rối và hiệp sĩ hai mặt bí ẩn, ai sẽ chinh phục được trái tim người kia trước? Hiệp sĩ bí ẩn hóa thân thành trợ lý thân cận của sếp lớn, hắn đang âm mưu điều gì, hay chỉ giả vờ buông lỏng để đối phương cắn câu? Khi một ma nữ kỳ quái tinh ranh trúng tiếng sét ái tình của hacker lạnh lùng, phía sau tình cảm tưởng chừng đơn phương liệu có phải con sóng ập tới cả hai hướng? Khi bạn gặp người trong lòng, trái tim bạn có đập thình thịch loạn nhịp? Khi rung động đến từ hai phía, liệu bạn có đủ can đảm để theo đuổi tình yêu đích thực?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2026, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Bách Dung","avatar":""},{"name":"Dư Văn Thi","avatar":""},{"name":"Thiệu Tân","avatar":""},{"name":"Tống Ích Phàm","avatar":""},{"name":"Trịnh Tương Mẫn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["这是心动的感觉"]', 1784690324130);
