INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vinh-hoa-lenh', 'Vinh Hoa Lệnh', 'Glory In Shadows', 'https://phimimg.com/upload/vod/20260112-1/27a772b5994444927cc869252a3e3f2d.jpg', 'https://phimimg.com/upload/vod/20260112-1/b80ba9e3a8afa7251780a438570c4ec0.jpg', '<p>Đích nữ Thẩm phủ Thẩm Dao Sơ bị ép gả cho vị tướng quân &quot;đã khuất&quot; Lê Tĩnh Xuyên, nhưng rồi cô bàng hoàng phát hiện ra anh ta thực chất chỉ giả chết để bí mật trở về. Sau cái chết oan ức và đầy nghi hoặc của mẫu thân, Thẩm Dao Sơ thề sẽ điều tra rõ chân tướng sự việc. Từ chỗ ban đầu chỉ là mối quan hệ hợp tác đôi bên cùng có lợi, cô và Lê Tĩnh Xuyên dần trở thành những người đồng đội kề vai sát cánh.Cùng nhau, hai người đã vượt qua những cuộc đấu đá gay gắt nơi thâm viên nội phủ, từ việc đối đầu với chủ mẫu độc ác, đập tan những âm mưu thâm hiểm cho đến việc phá giải những vụ án mạng ly kỳ. Cuối cùng, họ không chỉ lật mở được tấm màn bí mật kinh hoàng đã bị che giấu suốt nhiều năm trong phủ, mà còn tìm thấy chân tình sau biết bao lần cùng nhau vào sinh ra tử.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngô Giai Di","avatar":""},{"name":"Đổng Tử Phàm","avatar":""},{"name":"Tống Chiêu Nghệ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Rong Hua Ling","Ronghua Order","荣华令"]', 1784690324130);
