INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trieu-phuong-thanh-o-pho-cu', 'Triệu Phượng Thanh Ở Phố Cũ', 'Old Street Justice', 'https://phimimg.com/upload/vod/20260105-1/3b45b9f27da081237e66cd93f3153154.jpg', 'https://phimimg.com/upload/vod/20260105-1/9e64b73da424b49293ff959a2369cf1e.jpg', '<p>Năm 1995, sau khi quay về quê hương, Triệu Phượng Thanh bị bà con khu phố cổ hiểu lầm và xa lánh. Để hóa giải hiểu lầm ấy, anh đã dẫn dắt nhóm “Tứ hại phố cổ” dũng cảm đứng lên, vạch trần và đập tan âm mưu đen tối của các thế lực xấu xa, giải quyết những ân oán chồng chất, cuối cùng bảo vệ được sự bình yên cho quê hương.</p>', 'Tập 26', 26, 'series', 'ongoing', 13, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dụ Chung Lê","avatar":""},{"name":"Cẩm Lang","avatar":""},{"name":"Phạm Mộng","avatar":""},{"name":"Phạm Hiểu Đông","avatar":""},{"name":"Tôn Dục Hàm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Lao Jie Zhao Feng Sheng","老街赵凤声"]', 1784690324130);
