INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-phong-tu', 'Vãn Phong Từ', 'Undercover Us', 'https://phimimg.com/upload/vod/20260118-1/502c2c1f2479601a8a0e75d6af033c36.jpg', 'https://phimimg.com/upload/vod/20260118-1/eadc5588d96371d04f8eed0a18f78da8.jpg', '<p>Thành chủ Vân Châu — Tạ Từ Chu — từng mượn thế lực của Hoán Hoa Cốc để lên ngôi, nhưng vì lòng đa nghi mà trở mặt với Cốc chủ Tư Vũ, khiến Hoán Hoa Cốc phải ẩn dật khỏi giang hồ. Nhiều năm sau, sự bạo chính của Tạ Từ Chu khiến dân chúng lầm than, em trai hắn là Tuyên Bình Vương — Tạ Từ Uyên — đã dùng thân phận Các chủ Vô Phong Các để âm thầm kháng cự.Phương Mộ Vãn, truyền nhân của Hoán Hoa Cốc, từng vì một hiểu lầm mà giả danh thay thế thân phận, gả cho Tạ Từ Uyên suốt ba năm. Cuối cùng, nàng chọn cách tự thiêu để thoát thân, quay về cốc kế nhiệm vị trí Cốc chủ. Nàng quyết định rũ bỏ quá khứ, định ra hôn ước với ám vệ Thập Cửu.Cho đến khi một vụ án ám sát Các chủ Vô Phong Các đầy bí ẩn hiện hữu, Phương Mộ Vãn đích thân xuất mã. Thế nhưng, đằng sau chiếc mặt nạ của Các chủ lại chính là phu quân cũ — Tạ Từ Uyên. Trong khoảnh khắc bốn mắt nhìn nhau, nợ nước thù nhà cùng tình cũ chưa dứt lại một lần nữa đan xen. Lần này, thanh kiếm trong tay nàng sẽ chỉ hướng về thời loạn lạc, hay hướng về trái tim mà nàng chưa từng thực sự thấu hiểu?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 12, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Kê Ứng","avatar":""},{"name":"Phàn Hựu Thành","avatar":""},{"name":"Akilyar","avatar":""},{"name":"Vũ Tùng","avatar":""},{"name":"Lữ Diễm Bội","avatar":""},{"name":"Đại Thiệu Đông","avatar":""},{"name":"Lý Á Vân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wan Feng Ci","Farewell to the Evening Breeze","Undercover Us","晚风辞"]', 1784690324130);
