INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-that-dich-hung-thu-sat-nhan-bien-mat', 'Tiêu Thất Đích Hung Thủ (Sát Nhân Biến Mất)', 'Gone Murderer', 'https://phimimg.com/upload/vod/20260118-1/cb89d8781aba72b0ccfaab756f4fd54a.jpg', 'https://phimimg.com/upload/vod/20260118-1/ccd9b71a8623ff40d0b99a664de8740e.jpg', '<p>Sau khi người hàng xóm mới là Tô Nhiễm chuyển đến huyện Vũ Hiền, thám tử kỳ cựu Thạch Quang Minh bất ngờ bị cuốn vào một loạt vụ án mạng tàn khốc vừa bùng phát. Trong vai trò cố vấn, ông đã bắt tay cùng Lý Hạo — Đội trưởng đội điều tra hình sự của huyện. Cùng nhau, họ đã bóc tách những nút thắt của vụ án, lần theo dấu vết và đưa tất cả những kẻ thủ ác ra ánh sáng công lý.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 11, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Huyền Lộc","avatar":""},{"name":"Chu Thành Áo","avatar":""},{"name":"Vương Đại Kỳ","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Xiao Shi De Xiong Shou","消逝的凶手","消失的凶手"]', 1784690324130);
