INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-thien-huu-hy-ngay-ngay-co-chuyen-vui', 'Thiên Thiên Hữu Hỷ (Ngày Ngày Có Chuyện Vui)', 'A Happy Life', 'https://phimimg.com/upload/vod/20260118-1/2f89c21e6a63e0d3bd6a57e762bf9959.jpg', 'https://phimimg.com/upload/vod/20260118-1/a9f34c487fbec2daec1c495ff343a191.jpg', '<p>Câu chuyện bắt đầu từ cuộc sống kiêu căng, hống hách của Quận chúa Tô Cẩm Ly tại Hồng Thành, nơi cô gây ra vô số tranh chấp vì bản tính ham mê sắc đẹp. Trong một cơ hội tình cờ, cô bị xuyên không vào một trò chơi có tên là Hồng Thành Hữu Hỷ và hóa thân thành nhân vật Quận chúa trong game.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 11, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Kỷ Mỹ Hàm","avatar":""},{"name":"Trương Nghệ Kết","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["天天有囍"]', 1784690324130);
