INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hong-trang-van-giai-nhan', 'Hồng Trang Vấn Giai Nhân', 'A Girl In Tang Dynasty', 'https://phimimg.com/upload/vod/20260118-1/c8bfe7fa4e8bdcffe5582fae51e64b49.jpg', 'https://phimimg.com/upload/vod/20260118-1/7386da9c2de23afea6f3b2a3e59dc41e.jpg', '<p>Sau khi mất tất cả và rơi vào tình trạng hôn mê, Hứa Tiểu Phi tỉnh dậy giữa một kinh thành sầm uất. Từ hai bàn tay trắng, cô đã vươn lên xây dựng một sự nghiệp kinh doanh hưng thịnh bằng sự chính trực và lòng kiên định. Khi bắt tay cùng mật vụ hoàng gia Từ Tử Kỳ để phanh phui âm mưu thao túng giá cả nguy hiểm liên quan đến thương hội, cuộc hành trình theo đuổi công lý đã dẫn lối cho tình yêu nảy nở. Từ đó, Hứa Tiểu Phi trở thành một thương nhân huyền thoại.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 12, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Thái Chước Di","avatar":""},{"name":"Nghiêm Hỷ","avatar":""},{"name":"Trần Bân Yên","avatar":""},{"name":"Tào Tư Dương","avatar":""},{"name":"Lưu Hạo Nghiên","avatar":""},{"name":"Văn Quốc Hỉ","avatar":""},{"name":"Bạch Lộ","avatar":""},{"name":"Vu Đông","avatar":""},{"name":"Lương Du Thành","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["花倌唐小仙","唐女小霏","The Girl in Tang Dynasty","红妆问佳人"]', 1784690324130);
