INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hong-trang-van-giai-nhan', 'Hồng Trang Vấn Giai Nhân', 'A Girl In Tang Dynasty', 'hồng trang vấn giai nhân a girl in tang dynasty thái chước di nghiêm hỷ trần bân yên tào tư dương lưu hạo nghiên văn quốc hỉ bạch lộ vu đông lương du thành 花倌唐小仙 唐女小霏 the girl in tang dynasty 红妆问佳人', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mac-nhan-tang-kieu', 'Mặc Nhẫn Tàng Kiều', 'Sharp Blade In The Snow', 'https://phimimg.com/upload/vod/20260115-1/e22f60f7a8dd5228ab4f2a314f77fef1.jpg', 'https://phimimg.com/upload/vod/20260115-1/b58c9d67c2ab1dc50dcfb7bed237df86.jpg', '<p>Công chúa Phượng Ly bị gán cho tội danh giết cha và bị lưu đày đến vùng hoang mạc cằn cỗi. Bảy năm sau, cô trở về Mặc Thành với danh xưng &#39;Yêu Quân&#39; đầy quyền uy và tàn nhẫn. Tại đại tiệc Tước Lâu do người dì Mạnh Vũ thao túng, Phượng Ly đã chọn Vân Trạm — hậu duệ cuối cùng của Đông Ly với thân phận bí ẩn.Màn kịch tuyển nô bề ngoài có vẻ hoang lạc thực chất lại là cuộc thanh trừng máu lạnh của Phượng Ly nhắm vào các thế lực thù địch. Vân Trạm tiếp cận cô với thân phận &#39;Tước nô&#39; (nô lệ chim sẻ), anh vừa là mục tiêu ám sát, vừa là cố nhân trùng phùng, bởi cả hai từng là đôi bạn hoạn nạn có nhau thời thơ ấu tại vùng hoang mạc.Phượng Ly mượn thiết lập nhân vật &#39;điên phê&#39; (tàn nhẫn, bất cần) để âm thầm điều tra sự thật về cái chết của cha mình. Trong khi đó, Vân Trạm giả vờ phục tùng để chờ thời cơ báo thù phục quốc, nhưng lại vô tình rơi vào lưới tình trong những khoảnh khắc kề cạnh hư hư thực thực. Khi Phượng Ly nhìn thấy dấu ấn trên eo Vân Trạm và nhận ra người cũ, khi Vân Trạm tận mắt chứng kiến cô nôn ra máu nhưng vẫn mỉm cười uống độc dược, mọi lớp mặt nạ hoàn toàn vỡ vụn.Âm mưu biến Phượng Ly thành bù nhìn của Mạnh Vũ, quân cờ cầu thân của Thiếu chủ Tây Kỳ và ngọn lửa phục thù của tàn quân Đông Ly — tất cả đều bùng nổ trong ngày đại hôn của Nữ Quân. Cuối cùng, Phượng Ly tay cầm hổ phù đập tan mọi âm mưu, Vân Trạm vì cô mà từ bỏ đại nghiệp phục quốc. Hai linh hồn từng bò ra từ địa ngục, cuối cùng đã ôm lấy nhau trên ngai vàng nhuốm máu.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 11, 2026, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hoàng Tuấn Kiệt","avatar":""},{"name":"Ngô Giai Nhi","avatar":""},{"name":"Dương Diễn Nghệ","avatar":""},{"name":"Từ Thừa Nhiên","avatar":""},{"name":"Lưu Tử Ân","avatar":""},{"name":"Trương Tân Thành","avatar":""},{"name":"Lâm Thiên Thần","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mo Ren Cang Jiao","The Blade Conceals the Beauty","墨刃藏娇"]', 1784690324130);
