INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieng-yeu-nay-anh-dich-duoc-khong', 'Tiếng Yêu Này, Anh Dịch Được Không?', 'Can This Love Be Translated?', 'https://phimimg.com/upload/vod/20260116-1/92ad3288f61736574a2a2dd3c4ee5df1.jpg', 'https://phimimg.com/upload/vod/20260116-1/8b1201713adc08736e33e45ab1c1f2e4.jpg', '<p>Đi khắp thế giới để quay chương trình truyền hình, cảm xúc của một người nổi tiếng và phiên dịch viên của cô lại chẳng thể nào thông dịch. Liệu tình yêu có tìm được ngôn ngữ riêng?</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 45, 2026, 'Vietsub + Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Seon-ho","avatar":""},{"name":"Go Youn-jung","avatar":""},{"name":"Sota Fukushi","avatar":""},{"name":"Lee E-dam","avatar":""},{"name":"Choi Woo-sung","avatar":""},{"name":"Kim Won-hae","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["爱情怎么翻译？","이 사랑이 통역되나요?","Yi Sarang Tongyeok Dwenayo?","I Sarang Tongyeok Doenayo?","[이사랑 통역되나요？]","Чи можна перекласти цю любов?","Can This Love Be Translated?","Can You Interpret This Love?","Can This Love Be Interpreted?","Can Love Be Interpreted?","Can This Love Be Translated","이 사랑 통역 되나요?"]', 1784690324130);
