INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hiep-si-mat-na-zeztz', 'Hiệp Sĩ Mặt Nạ ZEZTZ', 'Kamen Rider ZEZTZ', 'https://phimimg.com/upload/vod/20250909-1/9687569eb69eb6084238e0c46149fbc0.jpg', 'https://phimimg.com/upload/vod/20250909-1/f24410500ec5132d041c94af7243ade3.jpg', '<p>Kamen Rider Zeztz xoay quanh một người hùng có năng lực điều khiển giấc mơ. Ban ngày, Yorozu Baku là một anh chàng thất nghiệp sống cùng em gái, nhưng đến đêm, anh lại trở thành một Kamen Rider bất khả chiến bại có khả năng xâm nhập vào giấc mơ của người khác. Khi một thế lực đen tối bắt đầu làm tổ trong giấc mơ của con người để rồi từ đó dần dần xâm lấn thế giới thực, Baku chính là người duy nhất có thể chiến đấu trong mơ để bảo vệ nhân loại và giấc ngủ của họ.</p>', 'Tập 43', 50, 'series', 'ongoing', 78, 2025, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Ryutaro Imai","avatar":""},{"name":"Maho Horiguchi","avatar":""},{"name":"Kenta Mishima","avatar":""},{"name":"Rina Onuki","avatar":""},{"name":"Miki Yagi","avatar":""},{"name":"Yuki Furukawa","avatar":""},{"name":"Jay Kabira","avatar":""},{"name":"Koichi Yamadera","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["假面骑士 ZEZTZ","Masked Rider Zeztz","幪面超人 ZEZTZ","假面騎士 Zeztz","Kamen Rider ZEZTZ","HSMN ZEZTZ","ZEZTZ","仮面ライダーゼッツ"]', 1784690324131);
