INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-chu-nha-que-tro-thanh-thanh-kiem-phan-1', 'Ông Chú Nhà Quê Trở Thành Thánh Kiếm (Phần 1)', 'From Old Country Bumpkin To Master Swordsman (Season 1)', 'https://phimimg.com/upload/vod/20250525-1/b807bed5b634c11c8c4e9826c2c0ad34.jpg', 'https://phimimg.com/upload/vod/20250525-1/c22c12d15137f735653aebb017496007.jpg', '<p>Beryl Gardenant, một kiếm sĩ trung niên điều hành một võ đường ở vùng hẻo lánh, sống một cuộc sống bình lặng, cho đến khi Allucia, cựu học trò và là Chỉ huy của Hội Hiệp sĩ Hoàng gia, xuất hiện! Cuộc sống của Beryl sắp thay đổi đáng kể! Cuộc sống thành thị. Học trò cũ. Bạn mới và kẻ thù đáng gờm. Quá nhiều thứ. Nhưng sau nhiều năm luyện tập, anh có những kỹ năng điên rồ, và anh được mệnh danh là &quot;kiếm sĩ vùng hẻo lánh&quot;.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 54, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hiroaki Hirata","avatar":""},{"name":"Nao Toyama","avatar":""},{"name":"Yuuki Hirose","avatar":""},{"name":"Hinaki Yano","avatar":""},{"name":"Hitomi Ueda","avatar":""},{"name":"Chiwa Saito","avatar":""},{"name":"Kaito Ishikawa","avatar":""},{"name":"Arisa Nakada","avatar":""},{"name":"Ryota Osaka","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["乡下大叔成为剑圣","Katainaka no Ossan, Kensei ni Naru","Ossan Kensei","おっさん剣聖","片田舎のおっさん, 剣聖になる","De viejo pueblerino a gran maestro espadachín","Backwater Old Man Becomes a Swordmaster","An Old Man from the Countryside Becomes a Swords Saint: I Was Just a Rural Sword Teacher, but My Successful Students Won''t Leave Me Alone!","片田舎のおっさん、剣聖になる"]', 1784690324131);
