INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-ma-thu-dua-tre-dinh-menh-va-anh-hung-bat-tu-phan-1', 'Vua Ma Thú, Đứa Trẻ Định Mệnh Và Anh Hùng Bất Tử (Phần 1)', 'Clevatess (Season 1)', 'https://phimimg.com/upload/vod/20250704-1/4f2ced9627428fbfe90694bdfa99d4e3.jpg', 'https://phimimg.com/uploads/movies/20260709/vua-ma-thu-dua-tre-dinh-menh-va-anh-hung-bat-tu-phan-1-poster.webp', '<p>Một trong những Lãnh Chúa Thú Hắc Ám, Clevatess, chứng kiến sự thống trị của mình sụp đổ khi hắn hồi sinh một anh hùng mà chính tay hắn từng giết và nhận nuôi một đứa trẻ lai người – hy vọng cuối cùng để cứu lấy một thế giới đang lụi tàn. Giờ đây bị ràng buộc với nhau bởi số phận, điều gì đang chờ đợi bộ ba bất ngờ này?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 88, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Haruka Shiraishi","avatar":""},{"name":"Mutsumi Tamura","avatar":""},{"name":"Yuichi Nakamura","avatar":""},{"name":"Saya Aizawa","avatar":""},{"name":"Aoi Yuuki","avatar":""},{"name":"Hiroki Yasumoto","avatar":""},{"name":"Chiharu Shigematsu","avatar":""},{"name":"Tomoyo Kurosawa","avatar":""},{"name":"Tomokazu Seki","avatar":""},{"name":"Miou Tanaka","avatar":""},{"name":"Jun Hashizume","avatar":""},{"name":"Shigeru Chiba","avatar":""},{"name":"Mamoru Miyano","avatar":""},{"name":"Yuki Ono","avatar":""},{"name":"Kenta Miyake","avatar":""},{"name":"Yuma Uchida","avatar":""},{"name":"Yohei Azakami","avatar":""},{"name":"S","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244