INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cai-chet-con-ky-lan', 'Cái Chết Con Kỳ Lân', 'Death Of A Unicorn', 'https://phimimg.com/upload/vod/20250502-1/38ff394f02c5c3722cd223ffc66f18d0.jpg', 'https://phimimg.com/upload/vod/20250502-1/a8fdb8a1b53469b5397df653def9d963.jpg', '<p>Trên đường đến kỳ nghỉ cuối tuần, hai cha con (Paul Rudd và Jenna Ortega) vô tình đâm phải... một con kỳ lân! Chuyện càng trở nên rắc rối khi ông chủ tỷ phú (Richard E. Grant) của người cha phát hiện ra sinh vật huyền thoại này có khả năng chữa lành kỳ diệu – và sẵn sàng làm mọi cách để khai thác nó. Một tai nạn kỳ quặc dẫn đến một chuỗi sự kiện dở khóc dở cười, nơi gia đình, lòng tham và phép màu va chạm đầy bất ngờ.</p>', 'Full', 1, 'single', 'completed', 92, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Paul Rudd","avatar":""},{"name":"Jenna Ortega","avatar":""},{"name":"Will Poulter","avatar":""},{"name":"Richard E. Grant","avatar":""},{"name":"Téa Leoni","avatar":""},{"name":"Sunita Mani","avatar":""},{"name":"Steve Park","avatar":""},{"name":"Anthony Carrigan","avatar":""},{"name":"Jessica Hynes","avatar":""},{"name":"David Pasquesi","avatar":""},{"name":"Denise Delgado","avatar":""},{"name":"Kathryn Erbe","avatar":""},{"name":"Nicholas Wittman","avatar":""},{"name":"Max Draskoczi","avatar":""},{"name":"Narantsogt Tsogtsaikhan","avatar":""},{"name":"Christine Grace Szarkó","avatar":""},{"name":"T","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Death of a Unicorne","Unikorn''un Ölümü","独角兽之死","Moartea unui Unicorn","Смерть единорога","Ükssarviku surm","La Muerte De Un Unicornio","Śmierć jednorożca","Death of a Unicorn"]', 1784690324131);
