INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cai-chet-con-ky-lan', 'Cái Chết Con Kỳ Lân', 'Death Of A Unicorn', 'cái chết con kỳ lân death of a unicorn paul rudd jenna ortega will poulter richard e. grant téa leoni sunita mani steve park anthony carrigan jessica hynes david pasquesi denise delgado kathryn erbe nicholas wittman max draskoczi narantsogt tsogtsaikhan christine grace szarkó t death of a unicorne unikorn''un ölümü 独角兽之死 moartea unui unicorn смерть единорога ükssarviku surm la muerte de un unicornio śmierć jednorożca death of a unicorn', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chiec-vong-ky-ao-lu-kinh-bo-loc', 'Chiếc Vòng Kỳ Ảo (Lự Kính / Bộ Lọc)', 'Filter', 'https://phimimg.com/upload/vod/20250226-1/377167fde75949fee8aadcf30b271ac8.jpg', 'https://phimimg.com/upload/vod/20250226-1/aa82c41fd81dba6a3c71a7cd95c0d411.jpg', '<p>Một sản phẩm công nghệ mới mang tên “vòng tay filter” đã khiến cho cô gái bình thường Tô Tranh Tranh có năng lực thay đổi diện mạo. Nhờ đó, cô biến thành cô gái xinh đẹp &quot;Tô Diểu&quot;, nữ tiến sĩ thông minh &quot;Phương Cẩn&quot;, chàng trai điển trai như bước ra từ truyện tranh &quot;Toàn Thắng Đường&quot;. Việc này không những khiến cô tận hưởng niềm vui khi lật ngược tình thế mà cô còn giúp đỡ những người yếu thế, thực thi công lý. Cùng lúc đó, Đường Kỳ rung động trước sự dũng cảm của Tô Diểu, đồng điệu với tư duy của Phương Cẩn, tán thưởng sự rạng rỡ, đẹp trai của Toàn Thắng Đường. Để giữ bí mật, Tô Tranh Tranh buộc phải nói dối hết lần này đến lần khác, khiến Đường Kỳ liên tục đánh mất người mình yêu. Trải qua những cú sốc dồn dập, bệnh về mắt của Đường Kỳ ngày càng nghiêm trọng khiến Tô Tranh Tranh chột dạ và áy náy khôn nguôi.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 84, 2025, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Đàn Kiện Thứ","avatar":""},{"name":"Lý Lan Địch","avatar":""},{"name":"Cao Hãn Vũ","avatar":""},{"name":"La Thu Vận","avatar":""},{"name":"Hoàng Tư Thụy","avatar":""},{"name":"Bồ Đào","avatar":""},{"name":"Vương Hoằng Nghị","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["滤镜","여경","Filter"]', 1784690324131);
