INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xanh-tham-phan-2', 'Xanh Thẳm (Phần 2)', 'Grand Blue Dreaming (Season 2)', 'https://phimimg.com/upload/vod/20250730-1/9b32a2c6b0e29fa3f620738248b422ce.jpg', 'https://phimimg.com/upload/vod/20250730-1/6c1f4b08c487b300ab58bc3f21158333.jpg', '<p>Iori Kitahara mong muốn có một tuổi thanh xuân tươi mới của mình trên bán đảo Izu khi anh chuẩn bị bắt đầu cuộc sống đại học ở đó, ở trong một căn phòng phía trên cửa hàng lặn &quot;Grand Blue&quot; của chú mình. Tuy nhiên, anh nhanh chóng bị sốc khi gặp Câu lạc bộ Lặn địa phương, một nhóm toàn thanh niên trai tráng dành nhiều thời gian để uống rượu, tiệc tùng và khỏa thân hơn là tập trung chuyên môn. Bất chấp những nỗ lực của mình để tránh xa nhóm, Iori nhanh chóng bị cuốn vào những trò hề của họ, trong khi chị em họ của anh cố gắng cho anh thấy những điều kỳ diệu khi lặn xuống biển và đại dương.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 43, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuma Uchida","avatar":""},{"name":"Ryohei Kimura","avatar":""},{"name":"Chika Anzai","avatar":""},{"name":"Kana Asumi","avatar":""},{"name":"Toa Yukinari","avatar":""},{"name":"Maaya Uchida","avatar":""},{"name":"Katsuyuki Konishi","avatar":""},{"name":"Hiroki Yasumoto","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Grand Blue","Guran Buru","GRAND BLUE 碧藍之海 2","Неосяжна блакить","Grand Blue Dreaming","GrandBlue","ぐらんぶる"]', 1784690324131);
