INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('digimon-beatbreak', 'DIGIMON BEATBREAK', 'Digimon Beatbreak', 'https://phimimg.com/upload/vod/20251111-1/b9d5ee4209289a3e9ba05a7b002f8e0c.jpg', 'https://phimimg.com/upload/vod/20251111-1/0db4abb38dc3193efe0ac7c3d7d4753b.jpg', '<p>&quot;e-Pulse&quot;, được tạo ra bởi suy nghĩ và cảm xúc của con người, đã được sử dụng làm nguồn năng lượng cho thiết bị hỗ trợ AI &quot;Sapotama&quot;. Từ bóng tối của sự phát triển đáng kinh ngạc này, những con quái vật đáng sợ xuất hiện. Digimon là những sinh vật sống tiến hóa bằng cách tiêu thụ e-Pulse. Tomoro Tenma bị cuốn vào một trải nghiệm phi thường sau khi gặp Gekkomon, người đột nhiên xuất hiện từ Sapotama của mình. Trong khi sống cùng Kyo Sawashiro và các thành viên khác của đội săn tiền thưởng &quot;Golden Dawn&quot;, Tomoro đã củng cố lại quyết tâm của mình. Tương lai mới nào sẽ được kiến tạo bởi con người và Digimon?</p>', 'Tập 37', 40, 'hoathinh', 'ongoing', 45, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Miyu Irino","avatar":""},{"name":"Megumi Han","avatar":""},{"name":"Tomoyo Kurosawa","avatar":""},{"name":"Mutsumi Tamura","avatar":""},{"name":"Arisa Sekine","avatar":""},{"name":"Misaki Kuno","avatar":""},{"name":"Yohei Azakami","avatar":""},{"name":"Daiki Hamano","avatar":""}]', '[{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["数码兽 BEATBREAK","数码暴龙 BEATBREAK","デジモンビートブレイク","Dejimon Bītobureiku","DIGIMON BEATBRE