INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-hoa-dao-no-ro', 'Nơi Hoa Đào Nở Rộ', 'Finding Home In Blossoms', 'https://phimimg.com/upload/vod/20250818-1/3375589288a1883e59c49d40a2d99b62.jpg', 'https://phimimg.com/upload/vod/20250818-1/aba46532cf8ea2b9267f39b32f97764b.jpg', '<p>Lấy bối cảnh sáng tác và câu chuyện diễn ra tại thôn Gala, Lâm Chi, Tây Tạng. Phim kể về một cô gái trẻ mang trong mình ước mơ trở thành họa sĩ minh họa, lên đường đến quê hương của mẹ ở Lâm Chi, Tây Tạng để tìm hiểu quá khứ. Cô dừng chân tại nhà trọ Đào Uyên Minh, và trong sự đồng hành của bà con các dân tộc nơi đây, bắt đầu hành trình lần theo dấu vết của mẹ mình.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 29, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lanka Tengjie","avatar":""},{"name":"Zhu Ya","avatar":""},{"name":"Dai Wenjun","avatar":""},{"name":"Wang Hanbang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Qu Tao Hua Sheng Kai Di Di Fang","去桃花盛开的地方2","To Where Peach Blossoms Bloom","What Place Blossoms Bloom 2","Finding Home in Blossoms 2","去桃花盛开的地方"]', 1784690324131);
