INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-si-da-hoi-sinh-the-gioi-phan-4', 'Tiến Sĩ Đá: Hồi Sinh Thế Giới (Phần 4)', 'Dr. STONE (Season 4)', 'https://phimimg.com/upload/vod/20250111-1/70b8653b53be96fa060e99e4d02fcaff.jpg', 'https://phimimg.com/upload/vod/20260404-1/f66064adf46ef11b60377b00c881ce8d.jpg', '<p>Chuyển thể từ manga cùng tên của tác giả Riichiro Inagaki. Lấy bối cảnh tương lai, ngày định mệnh của nhân loại đã đến, một tia sáng kì dị xuất hiện trên địa cầu khiến toàn bộ loài người hóa thành đá. Mấy ngàn năm trôi qua, ngày nọ cậu thiếu niên Senkuu bỗng nhiên phá đá thức tỉnh, trước mắt cậu là những pho tượng hóa đá của nhân loại. Cùng với cậu bạn của mình là Taiju bắt đầu đại nghiệp giải cứu nhân loại. Cuộc phiêu lưu mới bắt đầu, điều gì sẽ chờ đợi Senkuu và Taiju ở phía trước? Đại nghiệp ấy có thành công mỹ mãn hay thất bại trong tuyệt vọng?</p>', 'Hoàn Tất (37/37)', 37, 'hoathinh', 'completed', 35, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Доктор Стоун","石纪元","新石纪","石纪元 科学与未来 第2部分","Dr.STONE","डॉ. स्टोन","ドクターストーン","Dr.STONE STONE WARS","Dr.STONE (ドクターストーン)","Dr.STONE NEW WORLD","Dr.STONE SCIENCE FUTURE","닥터스톤","닥터스톤 4기","Доктор Стоун: Каменные войны","دكتور ستون","طبيب الحجر","Dr. STONE 新石紀","Dr. STONE WARS 新石紀 戰爭","Dr. STONE NEW WORLD 新石紀-新世界","Dr. STONE 龍水","石紀元","Dr. STONE: Stone Wars","Dr. STONE: New World","Dr. STONE: Science 