INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tien-si-da-hoi-sinh-the-gioi-phan-4', 'Tiến Sĩ Đá: Hồi Sinh Thế Giới (Phần 4)', 'Dr. STONE (Season 4)', 'tiến sĩ đá: hồi sinh thế giới (phần 4) dr. stone (season 4)  доктор стоун 石纪元 新石纪 石纪元 科学与未来 第2部分 dr.stone डॉ. स्टोन ドクターストーン dr.stone stone wars dr.stone (ドクターストーン) dr.stone new world dr.stone science future 닥터스톤 닥터스톤 4기 доктор стоун: каменные войны دكتور ستون طبيب الحجر dr. stone 新石紀 dr. stone wars 新石紀 戰爭 dr. stone new world 新石紀-新世界 dr. stone 龍水 石紀元 dr. stone: stone wars dr. stone: new world dr. stone: science future doctor stone tiến sĩ đá tiến sĩ đá: vương quốc khoa học tiến sĩ đá: cuộc chiến thế giới đá tiến sĩ đá: thuyền trưởng ryusui tiến sĩ đá: thế giới mới tiến sĩ đá: tương lai của khoa học', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-dai-vang-son-phan-3', 'Thời Đại Vàng Son (Phần 3)', 'The Gilded Age (Season 3)', 'https://phimimg.com/upload/vod/20260630-1/e8a6a19b5568da93708b17f0b4dee59b.jpg', 'https://phimimg.com/upload/vod/20260630-1/b40d9aeb7bf30700d38e26ee48d2699e.jpg', '<p>Vào năm 1882, khi Thời kỳ Hoàng kim của nước Mỹ đang ở giai đoạn đỉnh cao rực rỡ, Marian Brook — cô con gái mồ côi trẻ tuổi của một vị tướng miền Nam — đã chuyển đến New York để sống cùng các dì của mình, những người luôn tuân thủ các quy tắc truyền thống một cách cứng nhắc. Với sự giúp đỡ của Peggy Scott, một phụ nữ Mỹ gốc Phi đang giả làm hầu gái của cô, Marian bị cuốn vào cuộc sống hào nhoáng của những người hàng xóm giàu có, đồng thời phải đấu tranh để lựa chọn giữa việc tuân theo các chuẩn mực xã hội cũ kỹ hay tự tìm kiếm lối đi riêng cho chính mình.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 39, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Carrie Coon","avatar":""},{"name":"Morgan Spector","avatar":""},{"name":"Louisa Jacobson","avatar":""},{"name":"Denée Benton","avatar":""},{"name":"Taissa Farmiga","avatar":""},{"name":"Harry Richardson","avatar":""},{"name":"Blake Ritson","avatar":""},{"name":"Simon Jones","avatar":""},{"name":"Jack Gilpin","avatar":""},{"name":"Ben Ahlers","avatar":""},{"name":"Kelley Curran","avatar":""},{"name":"Celia Keenan-Bolger","avatar":""},{"name":"Ben Lamb","avatar":""},{"name":"Debra Monk","avatar":""},{"name":"Kristine Nielsen","avatar":""},{"name":"Kelli O''Hara","avatar":""},{"name":"Patrick Page","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Gilded Age : La loi du vieux New York","عصر طلایی","دوره طلایی","더 길디드 에이지","The Gilded Age"]', 1784690324131);
