INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thoi-dai-vang-son-phan-3', 'Thời Đại Vàng Son (Phần 3)', 'The Gilded Age (Season 3)', 'thời đại vàng son (phần 3) the gilded age (season 3) carrie coon morgan spector louisa jacobson denée benton taissa farmiga harry richardson blake ritson simon jones jack gilpin ben ahlers kelley curran celia keenan-bolger ben lamb debra monk kristine nielsen kelli o''hara patrick page the gilded age : la loi du vieux new york عصر طلایی دوره طلایی 더 길디드 에이지 the gilded age', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chua-te-huyen-bi', 'Chúa Tể Huyền Bí', 'Lord Of The Mysteries', 'https://phimimg.com/upload/vod/20250628-1/284d3bacb70acfe48b06c82dcc7d1cca.jpg', 'https://phimimg.com/upload/vod/20250628-1/b85e70f3b89c25f66500f12da35d7e8e.jpg', '<p>Trong thế giới thời Victoria ngập tràn hơi nước, tàu chiến và những điều huyền bí rợn người, Zhou Mingrui bất ngờ tỉnh lại trong thân xác của Klein Moretti. Bị cuốn vào vòng xoáy giữa các Giáo hội quyền lực, những nghi lễ cổ xưa và thế lực hắc ám, anh phải bước đi trên lưỡi dao mong manh giữa ánh sáng và bóng tối. Càng tiến sâu, Klein càng phát hiện ra một truyền thuyết kỳ bí về sức mạnh vô hạn - đi kèm là mối hiểm họa không thể gọi tên. Liệu anh sẽ trở thành người khai phá vận mệnh, hay bị chính nó nhấn chìm?</p>', 'Tập 15', 16, 'hoathinh', 'ongoing', 32, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Guimi Zhi Zhu","诡秘之主：小丑篇","诡秘之主动画","诡秘之主小丑卷","诡秘之主特别篇","詭秘之主","신비의 제왕 (애니메이션)","신비의 제왕 (애니)","신비의 제왕 (애니메)","신비의제왕","Повелитель Тайн","Lord of Mysteries: The Clown","詭秘之主：小丑篇","Lord of Mysteries","Lord of Mysteries：The Clown","LOTM","Lord of the Mysteries","Lord of Mysteries Specials","Sirlar hukmdori","Quỷ Bí Chi Chủ","Chúa Tể Huyền Bí: Quyển Tên Hề","Chúa Tể Huyền Bí","Quyển Tên Hề","诡秘之主"]', 1784690324131);
