INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chua-te-huyen-bi', 'Chúa Tể Huyền Bí', 'Lord Of The Mysteries', 'chúa tể huyền bí lord of the mysteries  guimi zhi zhu 诡秘之主：小丑篇 诡秘之主动画 诡秘之主小丑卷 诡秘之主特别篇 詭秘之主 신비의 제왕 (애니메이션) 신비의 제왕 (애니) 신비의 제왕 (애니메) 신비의제왕 повелитель тайн lord of mysteries: the clown 詭秘之主：小丑篇 lord of mysteries lord of mysteries：the clown lotm lord of the mysteries lord of mysteries specials sirlar hukmdori quỷ bí chi chủ chúa tể huyền bí: quyển tên hề chúa tể huyền bí quyển tên hề 诡秘之主', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-tinh-ai-2025', 'Trò Chơi Tình Ái', 'Game Of True Love', 'https://phimimg.com/upload/vod/20250323-1/224abbf41ff885c982d6e7afbaf5d8ee.jpg', 'https://phimimg.com/upload/vod/20250323-1/ff55d4a9611eef1d013bbf24f575e0cb.jpg', '<p>Thiên kim của tập đoàn Viễn Phi, Hứa Nặc, từ nhỏ lớn lên trong sự nuông chiều của bố mẹ. Sau khi du học nước ngoài trở về, cô kinh hoàng phát hiện gia đình hạnh phúc ngày nào đã tan nát. Mẹ cô bị đuổi ra khỏi nhà tay trắng, còn người anh không cùng huyết thống được gia đình cô nuôi dưỡng từ nhỏ Thẩm Gia Hòa lại sắp thay cô thừa kế sản nghiệp. Mà vị hôn thê của bố cô chính là Bạch Hạ, bạn gái tin đồn trước đây của Thẩm Gia Hòa, đồng thời cũng là kẻ thù không đội trời chung ngày xưa của cô.Hứa Nặc nhìn thấu âm mưu của Thẩm Gia Hòa. Để giành lại Viễn Phi và vạch trần bộ mặt thật của hắn, cô tính toán kỹ lưỡng, từng bước thực hiện kế hoạch. Cô cố ý dụ dỗ Thẩm Gia Hòa lao vào một canh bạc mang tên &quot;trò chơi tình ái&quot;, mở ra hành trình vừa yêu vừa hận giữa hai người.</p>', 'Hoàn Tất (56/56)', 56, 'series', 'completed', 39, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Fan Zhixin","avatar":""},{"name":"He Ruixian","avatar":""},{"name":"Wang Ce","avatar":""},{"name":"Wang Zuyi","avatar":""},{"name":"Huang Qiao","avatar":""},{"name":"Chen Yisha","avatar":""},{"name":"Mei Lingzhen","avatar":""},{"name":"Min Xinghan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chi Ai You Xi","炽爱游戏","炽爱游戏中国版","The Game of Love","The Game of Blazing Love","Buang Sanaeha","Crazy Love Game","挚爱游戏"]', 1784690324131);
