INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dich-khong-loi-thoat-mat-kiem-soat', 'Vùng Dịch Không Lối Thoát (Mất Kiểm Soát)', 'Uncontained', 'https://phimimg.com/upload/vod/20260624-1/91c77f5e50498490335d2bf3f0d850d4.jpg', 'https://phimimg.com/upload/vod/20260624-1/38bd315373df223c237c7057daeacaff.jpg', '<p>Giữa những khu rừng mùa đông ở Bắc Mỹ, một kẻ lang bạt bí ẩn chật vật bảo vệ một cậu bé bị bỏ rơi và em gái nhỏ của cậu khỏi một loại dịch bệnh biến con người thành những sinh vật hoang dại.</p>', 'Full', 1, 'single', 'completed', 40, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Morley Nelson","avatar":""},{"name":"Nicole Nelson","avatar":""},{"name":"Jack Nelson","avatar":""},{"name":"Brooke Nelson","avatar":""},{"name":"Peter O''Meara","avatar":""},{"name":"Brett Zimmerman","avatar":""},{"name":"Courtney Blythe Turk","avatar":""},{"name":"Hayley LeBlanc","avatar":""},{"name":"Joy Dolo","avatar":""},{"name":"Christos Kalabogias","avatar":""},{"name":"Allison Crandall","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Uncontained"]', 1784690324131);
