INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('americas-sweethearts-doi-co-vu-dallas-cowboys-phan-2', 'AMERICA''S SWEETHEARTS: Đội Cổ Vũ Dallas Cowboys (Phần 2)', 'AMERICA''S SWEETHEARTS: Dallas Cowboys Cheerleaders (Season 2)', 'https://phimimg.com/upload/vod/20250620-1/ca35973b1d694c90fa3a84c31c2a56c4.jpg', 'https://phimimg.com/upload/vod/20250620-1/a574f8fccb14953d915e88f68c70e379.jpg', '<p>Theo chân đội cổ vũ Dallas Cowboys từ các buổi tuyển chọn đến trại tập huấn và mùa giải NFL khi họ theo đuổi ước mơ và giành lấy một suất đáng mơ ước trong đội.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 28, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kelli Finglass","avatar":""},{"name":"Judy Trammell","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["AMERICA''S SWEETHEARTS: Dallas Cowboys Cheerleaders"]', 1784690324131);
