INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-xuyen-phan-2', 'Tử Xuyên (Phần 2)', 'Purple River (Season 2)', 'https://phimimg.com/upload/vod/20250813-1/073c45e99877cd52574b86cc3c0baba1.jpg', 'https://phimimg.com/upload/vod/20250813-1/f4d31a926b46f7bfd809527d9df711ae.jpg', '<p>Để thanh minh cho sợ trong sạch của mình thì con người ta có thể dùng đến những lời nói, nhưng đôi khi thì lời nói không phải hoàn toàn có giá trị và đáng tin, mà cách thiết thực nhất chính là chứng minh bằng thực lực và cả hành động. Tử Xuyên Tú vì muốn bảo vệ gia tộc Tử Xuyên của mình mà không ngần ngại ra tay trừng trị kẻ phản gián, bán mình cho ma tộc. Và cũng kể từ đó, Tử Xuyên Tú nhận được sự đồng tình và giúp đỡ tuyệt đối của các trưởng lão ở Miếu Thánh tại vùng đất Viễn Đông, một bước trở thành thủ lĩnh mới thống lĩnh trăm vạn quân liên minh và cũng hiên ngang trở thành một vị vua mới và cái tên là Quang Minh Vương của vùng đất Viễn Đông bao la ấy.</p>', 'Hoàn Tất (52/52)', 52, 'hoathinh', 'completed', 27, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tang Bao","avatar":""},{"name":"Zhengyang Ma","avatar":""},{"name":"Jiang Guangtao","avatar":""},{"name":"Baomu Zhongyang","avatar":""},{"name":"Ajie","avatar":""},{"name":"Qiao Shiyu","avatar":""},{"name":"Liangwei Hu","avatar":""},{"name":"Gao Qifan","avatar":""},{"name":"Xiao Han","avatar":""},{"name":"Yuanfei Mei","avatar":""},{"name":"Zhou Dong","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Zi Chuan","ZICHUAN","紫川动画","Purple River","紫川：光明王者","紫川·光明王者","紫川","紫川三傑","Eternal Brotherhood","The Legend of Zichuan Clan","Tử Xuyên 3D","Tử Xuyên"]', 1784690324131);
