INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ca-truc-dinh-menh-ca-dem', 'Ca Trực Định Mệnh (Ca đêm)', 'Late Shift', 'https://phimimg.com/upload/vod/20260617-1/45101b7db027b8849159241960dd478c.jpg', 'https://phimimg.com/upload/vod/20260617-1/2941351f706f2bf31dc3754a43474081.jpg', '<p>Cô y tá tận tâm Floria xoay xở giữa nhịp độ không ngừng nghỉ của khoa phẫu thuật thiếu nhân lực tại bệnh viện với lòng nhân ái và sự ấm áp. Khi ca trực đêm trở nên căng thẳng, cô bị đẩy đến giới hạn trong cuộc chạy đua với thời gian.</p>', 'Full', 1, 'single', 'completed', 40, 2025, 'Vietsub', 'FHD', 'Thụy Sĩ', 0, '[{"name":"Leonie Benesch","avatar":""},{"name":"Alireza Bayram","avatar":""},{"name":"Jürg Plüss","avatar":""},{"name":"Jasmin Mattei","avatar":""},{"name":"Lale Yavaş","avatar":""},{"name":"Andreas Beutler","avatar":""},{"name":"Urs Bihler","avatar":""},{"name":"Sonja Riesen","avatar":""},{"name":"Ali Kandas","avatar":""},{"name":"Margherita Schoch","avatar":""},{"name":"Nicole Bachmann","avatar":""},{"name":"Doris Schefer","avatar":""},{"name":"Selma Jamal Aldin","avatar":""},{"name":"Albana Agaj","avatar":""},{"name":"Ridvan Murati","avatar":""},{"name":"Urbain Guiguemde","avatar":""},{"name":"Elisabeth Rol","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["晚班护士","Nữ Anh Hùng","Kveldsvakt","Gece Vardiyası","شیفت عصر","Heldin"]', 1784690324131);
