INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-san-moi', 'Vùng Săn Mồi', 'Hunting Grounds', 'https://phimimg.com/upload/vod/20250710-1/3478a02239acce458532d97f5c3d49d6.jpg', 'https://phimimg.com/upload/vod/20250710-1/231f09bff8ce72693d653161d45156ca.jpg', '<p>Chloe Marvino là một người mẹ đơn thân, đang chạy trốn khỏi chồng cô – một gã có quan hệ mafia và đầy sức mạnh. Trong nỗ lực bảo vệ con cái, cô tìm đến một vùng rừng sâu và ẩn náu tại một cabin hoang vắng. Ở đó, Chloe gặp Jake – một người đàn ông lang thang, có quá khứ bí ẩn (là cựu lính đặc nhiệm). Ban đầu, anh dường như là người giúp đỡ cô. Nhưng khi những kẻ săn lùng do chồng cô cử đến ngày càng gần, Chloe mới phát hiện: chính Jake mới là mối nguy hiểm thực sự. Anh ta không chỉ đáng sợ hơn, mà còn nguy hiểm gấp bội cho cô và các con của cô so với những ai đang truy đuổi họ.</p>', 'Full', 1, 'single', 'completed', 35, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Canada', 0, '[{"name":"Emily Alatalo","avatar":""},{"name":"Tim Rozon","avatar":""},{"name":"Patrick Garrow","avatar":""},{"name":"Jon McLaren","avatar":""},{"name":"Milton Barnes","avatar":""},{"name":"Mikaël Conde","avatar":""},{"name":"Ryan Bainbridge","avatar":""},{"name":"Greg Bryk","avatar":""},{"name":"Eman Ayaz","avatar":""},{"name":"Simona Severino","avatar":""},{"name":"Nathaniel Wainman","avatar":""},{"name":"Khalid Karim","avatar":""},{"name":"Alex Jade","avatar":""},{"name":"Russell Yuen","avatar":""},{"name":"David MacInnis","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hunting Grounds"]', 1784690324131);
