INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-tu-quy', 'Hoàng Tử Quỷ', 'The Demon Prince', 'https://phimimg.com/upload/vod/20260616-1/e846044e179226ed112231cc4b5775f4.jpg', 'https://phimimg.com/upload/vod/20260616-1/6676f7a2d0bdedf1447f7f73825b745b.jpg', '<p>Hoàng Tử Quỷ xoay quanh Thân Đức - một hoàng tử được sinh ra nhờ tà thuật. Trốn thoát khỏi cung cấm, Thân Đức tham vọng giải thoát Quỷ Xương Cuồng khỏi Ải Mắt Người để khôi phục Xương Cuồng Giáo. Nhưng kế hoạch của Thân Đức chỉ thành hiện thực khi hắn có đủ cả hai “nguyên liệu” - Du Hồn Giả và Bạch Hổ Nguyên Âm. Đội lốt một lang y hiền lành, muốn chữa bệnh cứu người, Thân Đức lên đường đến làng Hủi và đụng độ trưởng làng Lỗ Đạt mạnh mẽ, liệu hắn có thể đạt được âm mưu tà ác của mình?</p>', 'Full', 1, 'single', 'completed', 64, 2025, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Anh Tú Atus","avatar":""},{"name":"Lương Thế Thành","avatar":""},{"name":"Hoàng Linh Chi","avatar":""},{"name":"Rima Thanh Vy","avatar":""},{"name":"Huỳnh Thanh Trực","avatar":""},{"name":"Vo Dang Duy Luan","avatar":""},{"name":"Lê Hà Phương","avatar":""},{"name":"Ngô Bảo Hân","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["Hoàng Tử Quỷ"]', 1784690324131);
