INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mot-seoul-chua-biet-den', 'Một Seoul Chưa Biết Đến', 'Our Unwritten Seoul', 'một seoul chưa biết đến our unwritten seoul park bo-young jinyoung ryu kyung-soo jang young-nam kim sun-young cha mi-kyeong won mi-kyung lim cheol-soo lee jae-in park yoon-ho yoo yu-jin moon dong-hyeok jung seung-kil jung eun-pyo park ye-yeong lee si-hoon shim so-young yang dae-hye 未知的首尔 미지의 서울 未知的首爾 seoul, the unknown unknown seoul our unwritten seoul', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kiem-lai-phan-2', 'Kiếm Lai (Phần 2)', 'The Swords (Season 2)', 'https://phimimg.com/upload/vod/20251226-1/9045124c0428d6bce416e9a37e969a53.jpg', 'https://phimimg.com/upload/vod/20251226-1/08023551b828aed0a2ec631575945f5d.jpg', '<p>Trần Bình An từ một thiếu niên vô danh buộc phải gánh lấy sứ mệnh dẫn dắt Lý Bảo Bình cùng đồng hành vượt biên, tìm đường đến nước Tùy xa xôi để nối tiếp học nghiệp còn chưa hoàn thành. Hành trình mở ra giữa non sông rộng lớn, phong cảnh tuy đẹp như tranh, nhưng sát cơ ẩn sâu trong từng bước chân. Thiết kỵ lạnh lùng truy bức không ngừng, yêu tà quỷ mị rình rập trong bóng tối, sinh tử chỉ cách nhau một nhịp thở. Trước gió bụi mịt mờ ấy, Trần Bình An không còn đường lùi, chỉ có thể tiến lên, dùng ý chí và nắm đấm mở lối sinh tồn. Giữa cơn loạn thế, những cường giả giấu tên lần lượt xuất hiện, âm thầm dang tay che chở, cũng đồng thời đẩy chàng vào vòng xoáy sâu hơn của võ đạo và đại cục.</p>', 'Hoàn Tất (27/27)', 27, 'hoathinh', 'completed', 32, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Chen Zhangtaikang","avatar":""},{"name":"Chen Hao","avatar":""},{"name":"Yun Wei Yi","avatar":""},{"name":"徐宇隆","avatar":""},{"name":"He Wenxiao","avatar":""},{"name":"Liu Xiaoyu","avatar":""},{"name":"Ling Zhenhe","avatar":""},{"name":"Bai Xuecen","avatar":""},{"name":"Shuxin Wan","avatar":""},{"name":"Li Min","avatar":""},{"name":"Yang Mo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["剑来 动画版","剑来","Jianlai","Jian Lai","The Swords","Sword of Coming"]', 1784690324131);
