INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('kiem-lai-phan-2', 'Kiếm Lai (Phần 2)', 'The Swords (Season 2)', 'kiếm lai (phần 2) the swords (season 2) chen zhangtaikang chen hao yun wei yi 徐宇隆 he wenxiao liu xiaoyu ling zhenhe bai xuecen shuxin wan li min yang mo 剑来 动画版 剑来 jianlai jian lai the swords sword of coming', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-da-quy', 'Tử Dạ Quy', 'Moonlit Reunion', 'https://phimimg.com/upload/vod/20250818-1/7e47f2924d70f231bc119a00c01a9bcb.jpg', 'https://phimimg.com/upload/vod/20250818-1/e6c2b3826944f2ba9b4de8f526620ad2.jpg', '<p>Tử Dạ Quy kể về hành trình tróc yêu của đạo sĩ Mai Trục Vũ – người được giao nhiệm vụ điều tra và tiêu diệt các thế lực yêu tà đang đe dọa cuộc sống người dân. Trong một lần điều tra chuỗi vụ án kỳ lạ, anh vô tình chạm trán Vũ Trinh – một cô tiểu thư xinh đẹp nhưng ẩn giấu thân phận là yêu miêu đã tu luyện hàng trăm năm. Tưởng rằng họ là kẻ thù không đội trời chung, nhưng càng tiếp xúc, Mai Trục Vũ càng nhận ra Vũ Trinh không giống những yêu quái khác. Cô lương thiện, thông minh, không chỉ giúp anh phá giải nhiều vụ án mà còn âm thầm bảo vệ người dân. Hai người từ nghi kỵ chuyển sang tin tưởng, từ đối đầu đến đồng hành trong các cuộc đấu pháp và hành trình khám phá những bí mật đen tối của thế giới yêu – người.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 46, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hứa Khải","avatar":""},{"name":"Điền Hi Vi","avatar":""},{"name":"Vương Giai Di","avatar":""},{"name":"Chu Chính Đình","avatar":""},{"name":"Ngô Tuấn Đình","avatar":""},{"name":"Dịch Đại Thiên","avatar":""},{"name":"Phạm Thi Nhiên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["梅夫人宠夫日常","ใต้แสงจันทร์วันหวนคืน","Zi Ye Gui","Moonlit Reunion","子夜归"]', 1784690324131);
