INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moc-lan-ngot-ngao-phan-4', 'Mộc Lan Ngọt Ngào (Phần 4)', 'Sweet Magnolias (Season 4)', 'https://phimimg.com/upload/vod/20250207-1/9b68de24ba327510ae676ab47ccd02a6.jpg', 'https://phimimg.com/upload/vod/20260611-1/df469f81554e3b167ee01fcb1a23ff98.jpg', '<p>Nhóm Mộc lan nâng ly chúc mừng những ngày tháng sắp tới. Nhà hàng tổ chức một sự kiện sang trọng. Một bữa tiệc Halloween vui vẻ khơi dậy những bất ngờ đầy mê hoặc.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 18, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"JoAnna Garcia Swisher","avatar":""},{"name":"Brooke Elliott","avatar":""},{"name":"Heather Headley","avatar":""},{"name":"Logan Allen","avatar":""},{"name":"Anneliese Judge","avatar":""},{"name":"Carson Rowland","avatar":""},{"name":"Justin Bruening","avatar":""},{"name":"Jamie Lynn Spears","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Suesse Magnolien","Sweet Magnolias"]', 1784690324131);
