INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('moc-lan-ngot-ngao-phan-4', 'Mộc Lan Ngọt Ngào (Phần 4)', 'Sweet Magnolias (Season 4)', 'mộc lan ngọt ngào (phần 4) sweet magnolias (season 4) joanna garcia swisher brooke elliott heather headley logan allen anneliese judge carson rowland justin bruening jamie lynn spears suesse magnolien sweet magnolias', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-dot-con-tim', 'Thiêu Đốt Con Tim', 'Love Beyond The Curse', 'https://phimimg.com/upload/vod/20250520-1/6e058b9ca639740c3e137920f8b5be07.jpg', 'https://phimimg.com/upload/vod/20250520-1/364c1fffc1ea474be18c22a6bdf40004.jpg', '<p>Sùng Dương của tộc Vĩnh Dạ trồng hoa Thực Dạ để kết liễu cuộc đời mình, thế nhưng hoa Thực Dạ lại mãi không nở, cho đến ngày gặp gỡ cô gái Viêm tộc là Quý Nam Tinh. Quý Nam Tinh bị nguyền rủa nếu muốn sống sót thì phải thành thân với Sùng Dương của tộc Vĩnh Dạ. Hai người, một hướng đến cái chết, một hướng đến sự sống, dần mở ra một cuộc tình đau thương cứu rỗi lẫn nhau…</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 20, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đại Cao Chính","avatar":""},{"name":"Hà Thích","avatar":""},{"name":"Lưu Bác","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["夜迷人","Fen Xin","焚心"]', 1784690324131);
