INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thieu-dot-con-tim', 'Thiêu Đốt Con Tim', 'Love Beyond The Curse', 'thiêu đốt con tim love beyond the curse đại cao chính hà thích lưu bác 夜迷人 fen xin 焚心', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-kiem-ky-hiep-truyen-3', 'Tiên Kiếm Kỳ Hiệp Truyện 3', 'Sword And Fairy 3 (Chinese Paladin 3)', 'https://phimimg.com/upload/vod/20251230-1/868ae9dcda90a490b619fb5cddfb166c.jpg', 'https://phimimg.com/upload/vod/20251230-1/369d8444034098215ab537a4bd859582.jpg', '<p>Ngàn năm trước, Thần tướng Phi Bồng và Ma tôn Trọng Lầu choảng nhau một trận long trời lở đất ở Tân Tiên Giới, đánh tới mức thần kiếm Chiếu Đảm bay thẳng xuống trần gian, còn Phi Bồng thì… bị đá khỏi hàng ngũ thần tiên. Ngàn năm sau, Thục Sơn yên ổn chưa được bao lâu thì tháp Toả Yêu rung lắc như sắp đổ, kéo theo một anh chàng bán đồ cổ lắm mồm tên Cảnh Thiên, chính là Phi Bồng đầu thai nhưng tạm thời quên mất mình từng oai phong thế nào. Chưa kịp hoàn hồn, Cảnh Thiên đã nhặt được ma kiếm, thứ vừa mạnh vừa lắm lời, mở màn cho chuỗi ngày sống không phút nào yên ổn. Từ đây, một tổ đội bá đạo hình thành. Cảnh Thiên miệng nhanh hơn não, Đường Tuyết Kiến nóng tính nhưng tốt bụng, Từ Trường Khanh nghiêm túc như sách giáo khoa, còn Tử Huyên thì bí ẩn đến mức mà nếu hỏi gì cũng chỉ cười trừ. Cả nhóm cùng nhau lên đường thu thập Ngũ Linh Châu, vừa cứu thế gian, vừa giải quyết ân oán ngàn năm giữa thần, ma và người.</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 18, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["仙剑奇侠传叁","仙剑奇侠传3动画版","仙剑奇侠传三动画版","仙剑奇侠传3‎","仙剑3动画","仙剑奇侠传3动画","仙剑三","Xian Jian Qi Xia Zhuan San","Chinese Paladin 3","Sword and Fairy 3"]', 1784690324131);
