INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-bac-cuc', 'Bờ Bắc Cực', 'Arctic''s Edge', 'https://phimimg.com/upload/vod/20260608-1/7d6fa0d2095ed23a151302e6379feb68.jpg', 'https://phimimg.com/upload/vod/20260608-1/c70428b88c993e0b7832d833ff1addd6.jpg', '<p>Calvin Trask sống trong một thị trấn hẻo lánh ở vùng Bắc Cực, tách biệt khỏi xã hội, cho đến khi người lạ mặt bí ẩn Lucas Wade xuất hiện, đảo lộn cuộc sống cô độc của anh. Sự tò mò thôi thúc Calvin và anh nhanh chóng bị cuốn vào thế giới nguy hiểm của Lucas. Khi những bí mật dần được hé lộ, Calvin nhận ra mình đang tự đẩy mình vào tình thế nguy hiểm như thế nào, một nơi mà giết người và phản bội là điều hiển nhiên, trong bộ phim kinh dị Bắc Âu lạnh lẽo này.</p>', 'Full', 1, 'single', 'completed', 19, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"David Lenik","avatar":""},{"name":"Rory Wilton","avatar":""},{"name":"Ricardo Freitas","avatar":""},{"name":"Johnny Vivash","avatar":""},{"name":"Rosie Edwards","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Краят на Арктика","Arctic''s Edge"]', 1784690324131);
