INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('grace', 'Grace', 'La Grazia', 'https://phimimg.com/upload/vod/20260608-1/3ef2fbe4e98a0cf75e0a7abc755845fe.jpg', 'https://phimimg.com/upload/vod/20260608-1/40f20361031fa880cc427fb2c2a8d8f4.jpg', '<p>Khi nhiệm kỳ Tổng thống Ý của ông Mariano De Santis sắp kết thúc, ông phải đối mặt với những quyết định khó khăn - cả về chính trị lẫn cá nhân sâu sắc. Giữa những tình huống tiến thoái lưỡng nan về mặt đạo đức, ông phải đối diện với lương tâm của chính mình và tìm kiếm sự hướng dẫn từ những người thân cận nhất, bao gồm cả người bạn tâm giao kiêm con gái ông, Dorotea.</p>', 'Full', 1, 'single', 'completed', 32, 2025, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Toni Servillo","avatar":""},{"name":"Anna Ferzetti","avatar":""},{"name":"Massimo Venturiello","avatar":""},{"name":"Milvia Marigliano","avatar":""},{"name":"Orlando Cinque","avatar":""},{"name":"Giuseppe Gaiani","avatar":""},{"name":"Giovanna Guida","avatar":""},{"name":"Alessia Giuliani","avatar":""},{"name":"Roberto Zibetti","avatar":""},{"name":"Linda Messerklinger","avatar":""},{"name":"Vasco Mirandola","avatar":""},{"name":"Rufin Doh Zeyenouin","avatar":""},{"name":"Guè","avatar":""},{"name":"Francesco Martino","avatar":""},{"name":"Alexandra Gottschl","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["라 그라치아","恩典","Žēlastība","Грация","Milost","A Kegyelem","Halastus","La Grâce","Malonė","A Graça","La grazia"]', 1784690324131);
