INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-tra', 'Điều Tra', 'The Mannequin', 'https://phimimg.com/upload/vod/20260608-1/ebbb6f3e1106b7c416391b54d0f0ee8f.jpg', 'https://phimimg.com/upload/vod/20260608-1/9a5a62b88d05270e673886dcd2ae041e.jpg', '<p>Một trợ lý stylist điều tra cái chết của chị gái mình trong một tòa nhà lịch sử ở Los Angeles, và bất ngờ đối mặt với hồn ma đầy thù hận của một kẻ giết người hàng loạt đã phân xác nạn nhân nhiều thập kỷ trước. Cô phải trốn thoát trước khi mình trở thành nạn nhân tiếp theo.</p>', 'Full', 1, 'single', 'completed', 23, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Isabella Gómez","avatar":""},{"name":"Lindsay LaVanchy","avatar":""},{"name":"Shireen Lai","avatar":""},{"name":"Maxwell Hamilton","avatar":""},{"name":"Gabriella Rivera","avatar":""},{"name":"Jack Sochet","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["The Mannequin"]', 1784690324131);
