INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-thon-thien-ha-truong-mon-tro-ve', 'Côn Thôn Thiên Hạ: Trưởng Môn Trở Về', 'The All-devouring Whale: Homecoming', 'https://phimimg.com/upload/vod/20250527-1/cacb186bfc68e2ed3ce29777939c1e5e.jpg', 'https://phimimg.com/upload/vod/20250527-1/8206393b7b032be91430ca02f8aff8d4.jpg', '<p>Phạm Linh Tiêu, một bậc thầy linh thú sở hữu tài năng xuất chúng, đã bị hãm hại trong cuộc thi thăng cấp môn phái cấp A và bị Côn – chính linh thú của mình – nuốt chửng. Khi mở mắt ra, chàng phát hiện bản thân đã chuyển sinh vào thân xác của một thiếu niên tên là Lưu Phong Mãng, và đang bị giam giữ trong ngục thất của Bạch Phủ.

Trong khi đó, chính môn phái của chàng – Linh Tiêu Các – lại đang rơi vào tình cảnh hiểm nguy. Để khám phá sự thật về việc bị Côn nuốt chửng và khôi phục lại môn phái, Phạm Linh Tiêu, cùng với những linh thú cũ còn theo mình, đã bắt đầu một cuộc hành trình phiêu lưu hoàn toàn mới bên cạnh Cố Linh, Trình Khê, và Nguyệt Đồng.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Shujun Lv","avatar":""},{"name":"Shujun Lv","avatar":""},{"name":"Ge Zirui","avatar":""},{"name":"Zhang Pei","avatar":""},{"name":"王小豫","avatar":""},{"name":"Zhimao","avatar":""},{"name":"Chong Chong","avatar":""},{"name":"苏翼","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["The All-devouring Whale：Homecoming","鲲吞天下","Kun Tun Tian Xia","Kun Tun Tian Xia Zhi Zuang Men Gui Lai","Kun Tun Tianxia","Kūn Tūn Tiānxià Zhī Zhǎng Mén Guīlái","Kun Tun Tianxia Zhi Zhang Men Guilai","Kun Tun Tianxia: Zhang Men Guilai","転生宗主の覇道譚: すべてを呑み込むサカナと這い上がる","転生宗主の覇道譚","転生宗主","Поглотить мир","Всепожирающий Кунь: Возвращение мастера","King of Spirit Beast","The All-devouring Whale","鲲吞天下之掌门归来"]', 1784690324131);
