INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-mong-ga-he-2', 'Ác Mộng Gã Hề 2', 'The Jester 2', 'https://phimimg.com/upload/vod/20260606-1/59b769692eedd2360c057f103fe30456.jpg', 'https://phimimg.com/upload/vod/20260606-1/5e5f2ec5743759e16e60158ac892a565.jpg', '<p>Tiếp nối phần đầu, tên hề bí ẩn The Jester tiếp tục xuất hiện trong đêm Halloween và nhắm đến những nạn nhân mới. Lần này, một cặp đôi trẻ vô tình chạm mặt hắn. Những trò ảo thuật và hành động tưởng như vô hại nhanh chóng biến thành các màn đe dọa đáng sợ khi The Jester bộc lộ bản chất sát nhân siêu nhiên của mình. Cuộc gặp gỡ ngắn ngủi dần trở thành một trò chơi sinh tử mà nạn nhân khó có thể thoát khỏi.</p>', 'Full', 1, 'single', 'completed', 20, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Michael Sheffield","avatar":""},{"name":"Kaitlyn Trentham","avatar":""},{"name":"Dingani Beza","avatar":""},{"name":"Hassen Kacem","avatar":""},{"name":"Jessica Ambuehl","avatar":""},{"name":"Charles Mckee","avatar":""},{"name":"Patrick Loree","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["The Jester 2"]', 1784690324131);
