INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hieu-truong-khiem-thinh-dau-tien', 'Hiệu Trưởng Khiếm Thính Đầu Tiên', 'Deaf President Now!', 'https://phimimg.com/upload/vod/20260606-1/2983fbcefaa682a7d89a0fada4b5dd09.jpg', 'https://phimimg.com/upload/vod/20260606-1/21a480fda4364f3b2970c232e6d2d8b9.jpg', '<p>Khám phá câu chuyện về phong trào quyền dân sự lớn nhất từng được biết. Trong tám ngày rúng động năm 1988 ở trường đại học duy nhất cho người điếc trên thế giới, bốn sinh viên phải tìm cách lãnh đạo một cuộc cách mạng - và thay đổi tiến trình lịch sử.</p>', 'Full', 1, 'single', 'completed', 27, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"I. King Jordan","avatar":""},{"name":"Jerry Covell","avatar":""},{"name":"Bridgetta Bourne-Firl","avatar":""},{"name":"Tim Rarus","avatar":""},{"name":"Greg Hlibok","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["데프 프레지던트 나우: 8일간의 혁명","聋哑校长","נשיא חירש עכשיו!","八日学运：还我听障校长！","Deaf President Now!"]', 1784690324131);
