INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-nhac-tinh-o-dao-wallis', 'Bản Nhạc Tình ở Đảo Wallis', 'The Ballad Of Wallis Island', 'https://phimimg.com/upload/vod/20260606-1/0268645d7d52104900af9372bf49cd9b.jpg', 'https://phimimg.com/upload/vod/20260606-1/bc46888d60322fd78e790dea0feda3bf.jpg', '<p>Charles – một triệu phú trúng số kỳ quái – sống ẩn dật trên đảo và luôn mơ về một buổi hòa nhạc trong mơ: buổi diễn riêng chỉ dành cho mình của nhạc sĩ thần tượng Herb McGwyer. Nhưng Charles còn có một bất ngờ khác: anh bí mật mời cả Nell – bạn gái cũ và đồng đội cũ của Herb – cùng chồng mới của cô đến biểu diễn lại những ca khúc năm xưa. Khi những mối tình dang dở, sự ghen tuông và âm nhạc va chạm nhau, một cơn bão bất ngờ giữ họ lại trên đảo. Trong không khí căng thẳng ấy, Charles cố níu kéo khoảnh khắc kỳ diệu mà anh từng tưởng tượng.</p>', 'Full', 1, 'single', 'completed', 28, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Tom Basden","avatar":""},{"name":"Tim Key","avatar":""},{"name":"Carey Mulligan","avatar":""},{"name":"Sian Clifford","avatar":""},{"name":"Akemnji Ndifornyen","avatar":""},{"name":"Steve Marsh","avatar":""},{"name":"Luka Downie","avatar":""},{"name":"Kerrie Thomason","avatar":""},{"name":"Arron Long","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["One For the Money","The Ballad of Wallis Island"]', 1784690324131);
