INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('zombie-land-saga-movie-thien-duong-ngan-ha-mong-tuong', 'Zombie Land Saga Movie: Thiên Đường Ngân Hà Mộng Tưởng', 'Zombie Land Saga: Yumeginga Paradise', 'https://phimimg.com/upload/vod/20260604-1/fc6c30d5caa6416fe705c9f017162bd6.jpg', 'https://phimimg.com/upload/vod/20260604-1/d9664a5f44618ac421a47a07999543ae.jpg', '<p>Zombie Land Saga: Yumeginga Paradise (2025) là movie tiếp nối mùa 2 của series anime Zombie Land Saga. Nội dung xoay quanh nhóm idol zombie Franchouchou khi họ trở thành đại sứ cho sự kiện Expo tại Saga. Tuy nhiên, một phi thuyền khổng lồ bất ngờ xuất hiện và tấn công tỉnh Saga, đẩy cả nhóm vào cuộc chiến giải cứu quê hương. Đặc biệt, Tae Yamada – thành viên bí ẩn nhất của nhóm – thức tỉnh ký ức và đóng vai trò then chốt trong việc chống lại cuộc xâm lăng.</p>', 'Full', 1, 'hoathinh', 'completed', 31, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kaede Hondo","avatar":""},{"name":"Asami Tano","avatar":""},{"name":"Risa Taneda","avatar":""},{"name":"Maki Kawase","avatar":""},{"name":"Rika Kinugawa","avatar":""},{"name":"Minami Tanaka","avatar":""},{"name":"Kotono Mitsuishi","avatar":""},{"name":"Mamoru Miyano","avatar":""},{"name":"Daisuke Ono","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Zombie Land Saga Movie","Eiga Zombieland Saga","Zombie Land Saga: Dream Galactic Paradise","Zombieland Saga: Yume Ginga Paradise","映画ゾンビランドサガ","剧场版 佐贺偶像是传奇 梦想银河乐园","劇場版 ゾンビランドサガ ゆめぎんがパラダイス"]', 1784690324131);
