INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tiem-anh-nam-kinh', 'Tiệm Ảnh Nam Kinh', 'Dead To Rights', 'https://phimimg.com/upload/vod/20260604-1/a38ebc5b85a766afcf234ed1bb95d920.jpg', 'https://phimimg.com/upload/vod/20260604-1/d4178d1a80678339427e992ec00a473f.jpg', '<p>Trong vụ thảm sát Nam Kinh năm 1937, để cứu mạng mình, người đưa thư A Chang đã giả làm thợ rửa ảnh trong một tiệm ảnh và rửa ảnh cho quân đội Nhật Bản. Anh ta cũng tiếp nhận một nhóm binh lính và thường dân Trung Quốc, biến tiệm ảnh thành nơi trú ẩn tạm thời. Tuy nhiên, trước sự tàn bạo của quân đội Nhật Bản, A Chang đã liều mạng để đưa những người tị nạn đến nơi an toàn và phơi bày bằng chứng về vụ thảm sát trước công chúng.</p>', 'Full', 1, 'single', 'completed', 82, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Daichi Harashima","avatar":""},{"name":"Takahashi Nobunaga","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["吉祥照相馆","Nan jing zhao xiang guan","Nanjing Zhao Xiang Guan","Dead To Rights","مرگ بر حق","Dead.to.Rights","جريمة قتل بشعة","南京照相馆"]', 1784690324131);
