INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-con-ho', 'Những con hổ', 'The Tigers', 'https://phimimg.com/upload/vod/20260602-1/b4fb82ebcc93372b60c1ab897d587c29.jpg', 'https://phimimg.com/upload/vod/20260602-1/1e3899c92ee10d97d4c3e1f7214a9035.jpg', '<p>Antonio và Estrella là hai anh em ruột cùng làm nghề lặn. Anh làm việc trong lĩnh vực hàng hải, còn cô nghiên cứu đời sống dưới nước và hỗ trợ anh. Tình hình kinh tế bấp bênh của họ có thể được cải thiện sau khi phát hiện cocaine được giấu trong khoang tàu neo đậu ở Huelva.</p>', 'Full', 1, 'single', 'completed', 38, 2025, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Antonio de la Torre","avatar":""},{"name":"Bárbara Lennie","avatar":""},{"name":"Joaquín Núñez","avatar":""},{"name":"Jesús del Moral","avatar":""},{"name":"César Vicente","avatar":""},{"name":"Skone","avatar":""},{"name":"Silvia Acosta","avatar":""},{"name":"Marta Correa Radwanska","avatar":""},{"name":"Fabiola Correa Radwanska","avatar":""},{"name":"Adrián Ledesma","avatar":""},{"name":"Claudia Vela","avatar":""},{"name":"Thimbo Samb","avatar":""},{"name":"Nico Montoya","avatar":""},{"name":"Carlos Bernardino","avatar":""},{"name":"Lupe Cano","avatar":""},{"name":"Melania Cruz","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Los Tigres"]', 1784690324131);
