INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-thu-ben-trong', 'Kẻ thù bên trong', 'An Enemy Within', 'https://phimimg.com/upload/vod/20260602-1/57d10bff57fa9ab6cf7395e0bee6d83a.jpg', 'https://phimimg.com/upload/vod/20260602-1/a326067287a0ee5a85558b1ec7458200.jpg', '<p>Vào đêm tân hôn, Caleb Wingate nhận lệnh phải giết cha vợ trước nửa đêm, nếu không cô dâu sẽ chết. Khi một sát thủ nguy hiểm đang đến gần và những bí mật gia đình bị phơi bày, Caleb phải tìm ra sự thật trước khi đêm kết thúc trong máu.</p>', 'Full', 1, 'single', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"William Moseley","avatar":""},{"name":"Patrick Baladi","avatar":""},{"name":"Kim Spearman","avatar":""},{"name":"Alexander Lincoln","avatar":""},{"name":"Tristan Gemmill","avatar":""},{"name":"Kate Isitt","avatar":""},{"name":"Toyin Omari-Kinch","avatar":""},{"name":"Frances Wilding","avatar":""},{"name":"Harrison Daniels","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["An Enemy Within"]', 1784690324131);
