INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-hang', 'Họ Hàng', 'Kindred', 'https://phimimg.com/upload/vod/20260602-1/dc7e8a82658aa80185a1ad8825d8c3e0.jpg', 'https://phimimg.com/upload/vod/20260602-1/5aba08f63510a4716522fe54ccc433f5.jpg', '<p>Hai tên tội phạm trẻ tuổi đột nhập vào biệt thự của một cặp vợ chồng giàu có và nhanh chóng phát hiện ra rằng cặp vợ chồng trung niên này nguy hiểm hơn vẻ bề ngoài của họ rất nhiều.</p>', 'Full', 1, 'single', 'completed', 35, 2025, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Deanna Jarvis","avatar":""},{"name":"Jonathan Goad","avatar":""},{"name":"Kylee Evans","avatar":""},{"name":"Randy Thomas","avatar":""},{"name":"Tennille Read","avatar":""},{"name":"Russell Sams","avatar":""},{"name":"Ish Morris","avatar":""},{"name":"Catherine McGregor","avatar":""},{"name":"Derick Agyemang","avatar":""},{"name":"Cindy Goh","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Kindred"]', 1784690324131);
