INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-sang-cua-the-gioi', 'Ánh sáng của thế giới', 'Light of the World', 'https://phimimg.com/upload/vod/20260602-1/15ce1758714686e29cd7bf9de25b84bc.jpg', 'https://phimimg.com/upload/vod/20260602-1/cfd0c4de179f9d7e2ce51b36e6796f1f.jpg', '<p>Một cậu bé bình thường, một niềm tin phi thường. Năm 30 sau Công nguyên, mọi người đang háo hức chờ đợi Đấng Mê-si-a đến. Mặc dù Chúa Giê-su không hoàn toàn giống như họ tưởng tượng, nhưng người đàn ông này lại có điều gì đó đặc biệt. Chẳng bao lâu sau, Giăng, Gia-cốp, An-đrê, Phi-e-rơ và những người khác bắt đầu theo Chúa Giê-su vào một cuộc phiêu lưu bất ngờ. Câu chuyện hoạt hình tuyệt đẹp về Chúa Giê-su được kể qua con mắt của người bạn trẻ yêu quý của Ngài, sứ đồ Giăng.</p>', 'Full', 1, 'hoathinh', 'completed', 24, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ian Hanlin","avatar":""},{"name":"Benjamin Jacobson","avatar":""},{"name":"Vincent Tong","avatar":""},{"name":"Michael Benyaer","avatar":""},{"name":"David A. Kaye","avatar":""},{"name":"Peter New","avatar":""},{"name":"Richard Newman","avatar":""},{"name":"Sam Darkoh","avatar":""},{"name":"Colin Murdock","avatar":""},{"name":"Jesse Inocalla","avatar":""},{"name":"Erin Mathews","avatar":""},{"name":"Dave Pettitt","avatar":""},{"name":"Ceara Morgana","avatar":""},{"name":"Bill Newton","avatar":""},{"name":"Mark Oliver","avatar":""},{"name":"Adam Nurada","avatar":""},{"name":"Dylan Leonard","avatar":""},{"name":"Adam Kozlic","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Jesús Luz Del Mundo","Liwanag ng Mundo","Licht der Welt","Lumière du Monde","Licht van de Wereld","Lumina Lumii","Світло Світу","Light of the World"]', 1784690324131);
