INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('downton-abbey-chao-mung-dai-ket-cuc', 'Downton Abbey Chào Mừng Đại Kết Cục', 'Downton Abbey Celebrates the Grand Finale', 'https://phimimg.com/upload/vod/20260531-1/3abccfe54428f74a2b26523da8f9ae4f.jpg', 'https://phimimg.com/upload/vod/20260531-1/510f840f7413d8b81896a727f9184244.jpg', '<p>Các ngôi sao của bộ phim chính kịch cổ trang được yêu thích Downton Abbey hội ngộ tại khách sạn Savoy ở London để chia sẻ kỷ niệm, những câu chuyện hậu trường, cùng một cái nhìn sớm về bộ phim cuối cùng.</p>', 'Full', 1, 'single', 'completed', 20, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Hugh Bonneville","avatar":""},{"name":"Jim Carter","avatar":""},{"name":"Laura Carmichael","avatar":""},{"name":"Raquel Cassidy","avatar":""},{"name":"Michelle Dockery","avatar":""},{"name":"Kevin Doyle","avatar":""},{"name":"Michael Fox","avatar":""},{"name":"Joanne Froggatt","avatar":""},{"name":"Paul Giamatti","avatar":""},{"name":"Harry Hadden-Paton","avatar":""},{"name":"Allen Leech","avatar":""},{"name":"Phyllis Logan","avatar":""},{"name":"Elizabeth McGovern","avatar":""},{"name":"Sophie McShera","avatar":""},{"name":"Lesley Nicol","avatar":""},{"name":"Penelope Wilton","avatar":""},{"name":"D","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Downton Abbey Celebrates the Grand Finale"]', 1784690324131);
