INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('la-chan-doi-tra-lop-vo-doi-tra', 'Lá Chắn Dối Trá (Lớp Vỏ Dối Trá)', 'Bodyguard of Lies', 'https://phimimg.com/upload/vod/20260531-1/6ec5fbca7885c057027499e8167dde2e.jpg', 'https://phimimg.com/upload/vod/20260531-1/df7f0e06d364cb6b3a11d96d4311fb4a.jpg', '<p>Phơi bày mạng lưới dối trá phức tạp do chính phủ Hoa Kỳ giăng ra trong suốt cuộc chiến kéo dài 20 năm tại Afghanistan, bộ phim tài liệu này hé lộ chiến dịch tuyên truyền sai lệch và lừa dối mà công chúng Mỹ đã bị dẫn dắt. Thông qua những lời khai gây sốc từ các nhân vật nội bộ chính phủ, tài liệu mật và các đoạn ghi âm riêng tư từ những người ở cấp cao nhất trong quân đội và giới lãnh đạo dân cử, bộ phim tài liệu kịch tính này kêu gọi một sự đối mặt nghiêm túc với những hệ lụy sâu rộng của sự dối trá chính trị trên quy mô toàn cầu.</p>', 'Full', 1, 'single', 'completed', 19, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Bodyguard of Lies"]', 1784690324131);
