INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-tran-tien-ngam', 'Ma Trận Tiền Ngầm', 'The Dark Money Game', 'https://phimimg.com/upload/vod/20260531-1/376d460bd6c896f6fb8f01ef14b2911d.jpg', 'https://phimimg.com/upload/vod/20260531-1/033f50858dd79d9bdd008f25ec1079f7.jpg', '<p>Bộ phim tài liệu phơi bày cách “tiền đen” âm thầm thao túng chính trị Mỹ qua các tổ chức vận động, tài trợ ẩn danh và mạng lưới quyền lực. Khám phá mối liên kết giữa tiền bạc, ảnh hưởng chính trị và những quyết định có thể làm thay đổi nền dân chủ.</p>', 'Hoàn Tất (2/2)', 2, 'series', 'completed', 20, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jane Mayer","avatar":""},{"name":"James Bopp","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["The Dark Money Game"]', 1784690324132);
