INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-gian-de-tung-canh', 'Không Gian Để Tung Cánh', 'Room To Move', 'https://phimimg.com/upload/vod/20260530-1/b5d3c697424f4fbedb52a0199423f2f3.jpg', 'https://phimimg.com/upload/vod/20260530-1/bc8be05d7a924d11dde2658cf4703d38.jpg', '<p>Biên đạo múa kiêm nghệ sĩ biểu diễn Jenn Freeman từ nhỏ đã luôn sở hữu món quà thiên bẩm về chuyển động. Ngay từ độ tuổi rất nhỏ, cô chỉ đơn giản là phải nhảy múa… mọi lúc mọi nơi. Thế nhưng, đi cùng với khao khát thường trực được bật nhảy, lao mình, rung lắc và cựa quậy ấy lại là một cuộc chiến không ngừng nghỉ để có thể tồn tại hài hòa trong một thế giới dường như luôn chực chờ tấn công vào các giác quan và sự cân bằng của cô ở mỗi một bước đi.</p>', 'Full', 1, 'single', 'completed', 19, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["מקום לנוע","Room to Move"]', 1784690324132);
