INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-he-diem-10', 'Thế Hệ Điểm 10', 'Generasi: Perfect 10', 'https://phimimg.com/upload/vod/20260527-1/53e76e2dd6ab371ef21ff1c8ffbc84cd.jpg', 'https://phimimg.com/upload/vod/20260527-1/0e8091517527fbdba73262592f53e2bf.jpg', '<p>Khi câu lạc bộ ở trường đóng cửa, Ezie nhút nhát nhưng đầy nghị lực gia nhập một học viện thể dục dụng cụ danh giá, nơi sự hoàn hảo ngự trị. Liệu cô có thể trụ vững trước áp lực?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 41, 2025, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Arena Wan","avatar":""},{"name":"Arabella Ellen","avatar":""},{"name":"Sofia Jane","avatar":""},{"name":"Sharifah Sakinah","avatar":""},{"name":"Daniel Fong","avatar":""},{"name":"Aiman Ameer","avatar":""},{"name":"Ellyza Azizi","avatar":""},{"name":"Sherie Merlis","avatar":""},{"name":"Qi Razali","avatar":""},{"name":"Zarra Zaff","avatar":""},{"name":"Anwaar Beg Moghal","avatar":""},{"name":"Chandni Nagadurga","avatar":""},{"name":"Dhabita Auji","avatar":""},{"name":"Aaliyah Natasha","avatar":""},{"name":"Hazi Juzaili","avatar":""},{"name":"Aila Azizul","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Generasi: Perfect 10"]', 1784690324132);
