INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gau-boonie-biet-doi-thu-nho-phan-2', 'Gấu Boonie: Biệt Đội Thu Nhỏ (Phần 2)', 'Boonie Bears: Shrunk (Season 2)', 'https://phimimg.com/upload/vod/20260429-1/0ff124edc06649e716b0979c1839aaa8.jpg', 'https://phimimg.com/upload/vod/20260429-1/46db909448c1a5f5118e34258e8e6e59.jpg', '<p>Cứ ngỡ thảm họa thu nhỏ đã lùi xa, nhưng một sự cố bất ngờ đã lại khiến Briar và Bramble rơi vào hình hài tí hon một lần nữa. Lần này, mọi thứ còn khắc nghiệt hơn khi những cạm bẫy cũ đã được thay thế bằng các thử thách hoàn toàn mới, nguy hiểm gấp bội. Nếu không kịp tìm ra cách đảo ngược quá trình trước khi mặt trời lặn, họ có thể sẽ bị kẹt lại trong thế giới thu nhỏ này mãi mãi.</p>', 'Hoàn Tất (52/52)', 52, 'hoathinh', 'completed', 40, 2025, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Wei","avatar":""},{"name":"Zhang Bingjun","avatar":""},{"name":"Tan Xiao","avatar":""},{"name":"贾晨露","avatar":""},{"name":"周子瑜","avatar":""}]', '[{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["熊出没之小小世界","Boonie Bears: Shrunk","熊出没之小小世界第二季","Boonie Bears：Shrunk 2","Отважные Мишки. Новые приключения"]', 1784690324132);
