INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-than-van-tuong-long-hon', 'Long Thần Vạn Tượng: Long Hồn', 'Soul of the Dragon', 'https://phimimg.com/upload/vod/20260527-1/2a55c645e977116649eb540025b32e88.jpg', 'https://phimimg.com/upload/vod/20260527-1/8bf33b409a4f4a90e26fb32e9854c8e3.jpg', '<p>Suốt triệu năm qua, Long tộc, chủng tộc cổ xưa và thần bí, vẫn không ngừng sinh sôi ở trung thổ đại lục. Thế nhưng cuộc tranh đấu giữa Quang hồn và Ám hồn ở Thần Giới cũng đã kéo Long tộc vào vòng xoáy. Long tộc rơi vào cảnh nội loạn tàn khốc, thậm chí còn đối mặt với nguy cơ diệt tộc. Trong thời khắc tuyệt vọng ấy, Ngao Tuyết – Thái tử Đông Hải, người bỏ đi đã lâu, nay mạnh mẽ trở về với khát vọng giải cứu Long tộc khỏi trận đại nạn.</p>', 'Tập 8', 40, 'hoathinh', 'ongoing', 15, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["西行纪","龙神万相之龙魂","Long Hun","Lóng Hún","The Dragon Spirit (2025)","龙魂"]', 1784690324132);
