INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dexter-hoi-sinh', 'Dexter: Hồi Sinh', 'Dexter: Resurrection', 'https://phimimg.com/upload/vod/20250719-1/b8a74a7c6276afe9bcea2225e95d233d.jpg', 'https://phimimg.com/upload/vod/20250719-1/a20268535fe70784e36d7a98983a1ad2.jpg', '<p>Sau một thời gian dài hôn mê, Dexter Morgan tỉnh lại trong cô độc – con trai anh, Harrison, đã biến mất không để lại dấu vết. Mang trong mình mặc cảm tội lỗi vì những gì từng gây ra cho con, Dexter lần theo dấu vết đến New York, quyết tâm tìm lại Harrison và sửa chữa những sai lầm quá khứ. Nhưng đường về không bao giờ dễ dàng. Khi Angel Batista từ Sở cảnh sát Miami xuất hiện với những nghi vấn cũ, bóng ma của quá khứ bắt đầu lộ diện. Trong thành phố không ngủ, hai cha con sớm nhận ra mình đã dấn thân quá sâu – và chỉ có một cách thoát ra: cùng nhau đối mặt.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Michael C. Hall","avatar":""},{"name":"Jack Alcott","avatar":""},{"name":"Uma Thurman","avatar":""},{"name":"David Zayas","avatar":""},{"name":"James Remar","avatar":""},{"name":"Ntare Guma Mbaho Mwine","avatar":""},{"name":"Kadia Saraf","avatar":""},{"name":"Dominic Fumusa","avatar":""},{"name":"Emilia Suárez","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Dexter: Ringjallja","Dexter: Resurrection"]', 1784690324132);
