INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-tai-tro', 'Nhà Tài Trợ', 'Sponsor', 'https://phimimg.com/upload/vod/20260525-1/a78c2990581ca87f78207e13efa18a1e.jpg', 'https://phimimg.com/upload/vod/20260525-1/e8d50644f5f05bdbd482db77bb12e159.jpg', '<p>Một bộ phim kể về hai chị em phải dùng chính cơ thể của mình để sinh tồn qua ngày. Để gánh vác và nuôi sống gia đình, Jasmine chấp nhận trở thành &quot;sugar baby&quot; cho một doanh nhân giàu có. Thế nhưng, cô sớm phải hối hận vì lựa chọn này khi nhận ra rằng nó đang đẩy cả mạng sống của bản thân lẫn em gái mình vào vòng nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 30, 2025, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Angela Morena","avatar":""},{"name":"Mon Confiado","avatar":""},{"name":"Micaella Raz","avatar":""},{"name":"Krista Miller","avatar":""},{"name":"Jem Milton","avatar":""},{"name":"Van Allen Ong","avatar":""},{"name":"Vic Romano","avatar":""},{"name":"Mark Dionisio","avatar":""},{"name":"Bobby Martino","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["性赞助","Sponsor"]', 1784690324132);
