INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-la-mu-quang-y-phan-1', 'Yêu Là Mù Quáng: Ý (Phần 1)', 'Love Is Blind: Italy (Season 1)', 'https://phimimg.com/upload/vod/20260525-1/2b369291c535f27a5dab5264d5258dd9.jpg', 'https://phimimg.com/upload/vod/20260525-1/2d78c245b67b01d1fe421480cf2580b5.jpg', '<p>Một nhóm những người độc thân khao khát được yêu thương vì chính con người thật của mình sẽ có cơ hội tìm kiếm tri kỷ mà không bị xao nhãng bởi thế giới bên ngoài. Họ sẽ phải chọn ra người mình muốn kết hôn mà chưa một lần gặp mặt trực tiếp. Khi ngày cưới cận kề, liệu những thực tế của cuộc sống đời thực và các yếu tố bên ngoài sẽ đẩy họ ra xa, hay họ vẫn sẽ kết hôn với người mà mình đã đem lòng yêu mù quáng?</p>', 'Hoàn Tất (10/10)', 10, 'tvshows', 'completed', 33, 2025, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Fabio Caressa","avatar":""},{"name":"Benedetta Parodi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["L''amore è cieco: Italia"]', 1784690324132);
