INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoc-trai-trong-suong-mu', 'Ngọc Trai Trong Sương Mù', 'Mutiara Dalam Debuan Kabus', 'https://phimimg.com/upload/vod/20260519-1/ddaec89fdb5e462707764fe37098e646.jpg', 'https://phimimg.com/upload/vod/20260519-1/6e02a6acbed4aa69e096cb9ad59eb8eb.jpg', '<p>Một cáo buộc nghiêm trọng khiến Uzzam phải ký giao kèo hôn nhân kéo dài năm năm với Aslin, đẩy cả hai vào một vòng xoáy bí mật, âm mưu và thù hận.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 35, 2025, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Zahiril Adzim","avatar":""},{"name":"Emma Maembong","avatar":""},{"name":"Jasmin Hamid","avatar":""},{"name":"Afzan A.Rahman","avatar":""},{"name":"Watie Sadali","avatar":""},{"name":"Manan Sulaiman","avatar":""},{"name":"Natasha Mahyan","avatar":""},{"name":"Safura Yaacob","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mutiara Dalam Debuan Kabus"]', 1784690324132);
