INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngoc-trai-trong-suong-mu', 'Ngọc Trai Trong Sương Mù', 'Mutiara Dalam Debuan Kabus', 'ngọc trai trong sương mù mutiara dalam debuan kabus zahiril adzim emma maembong jasmin hamid afzan a.rahman watie sadali manan sulaiman natasha mahyan safura yaacob mutiara dalam debuan kabus', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-gioi-chi-mon', 'Huyền Giới Chi Môn', 'The Gate Of Mystical Realm', 'https://phimimg.com/upload/vod/20251204-1/51bf27cf74dd8df0dfb0f3b327158cb8.jpg', 'https://phimimg.com/upload/vod/20251204-1/261186b439d048d6ce6669b4f92a741b.jpg', '<p>Huyền Giới Chi Môn, câu chuyện về hành trình từ một cậu thiếu niên tầm thường cho đến trở thành võ giả chân chính của Thạch Mục với những nốt thăng trầm đáng nhớ. Vốn xuất thân tầm thường, tầm thường đến mức chỉ là một con nuôi trong một thế gia, vậy nên Thạch Mục cũng bị phân biệt đối xử chẳng được ai coi trọng, việc tu luyện của cậu cũng vậy, chẳng có gì để trợ giúp như những người khác cả, phải tự thân vận động thôi. Bắt buộc phải trở thành võ giả, bởi chỉ có võ giả thì mới nhận được sự thừa nhận về năng lực cũng như sự kính trọng từ mọi người. Nhưng hành trình ấy của Thạch Mục cũng chẳng hề dễ dàng, gian nan và cũng không thiếu nguy hiểm. Từ những trận chiến thập tử nhất sinh, tưởng hẹo mười mươi, cho đến những ngày tháng bị rượt đuổi chạy như bị Tào Tháo rượt, những những khoảnh khắc ấy đã tôi luyện cho Thạch Mục ngày càng trưởng thành, trở thành một võ giả có thể cứu rỗi tương lai của muôn người.</p>', 'Tập 26', 26, 'series', 'ongoing', 22, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yitong Zhao","avatar":""},{"name":"Jiang Qiuzai","avatar":""},{"name":"Li Shimeng","avatar":""},{"name":"Shuang Zhao","avatar":""},{"name":"Wei Yifan","avatar":""},{"name":"Nie Xiying","avatar":""},{"name":"Liu Cong","avatar":""},{"name":"姜贺","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e07