INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thariq-ridzuwan-kho-bau-cua-anh', 'Thariq Ridzuwan: Kho báu của anh', 'Thariq Ridzuwan: His Treasure', 'https://phimimg.com/upload/vod/20260518-1/1fae8987ff9e568beb168d279285f991.jpg', 'https://phimimg.com/upload/vod/20260518-1/39cb5807b6ca701ed50f95657bffd60f.jpg', '<p>Thariq Ridzuwan (do Meerqeen thủ vai), một sĩ quan tinh nhuệ thuộc đơn vị Long Thần Thánh, nhận được tin sốc rằng người yêu cũ của anh, Husniya Radwa (do Qasrina Karim thủ vai), đang bị mẹ cô, Rozita, ép cưới. Mặc dù đã xa cách năm năm, Thariq từ bỏ nhiệm vụ của mình để cứu Radwa.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 30, 2025, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Meerqeen","avatar":""},{"name":"Qasrina Karim","avatar":""},{"name":"Noki K-Clique","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["THARIQ RIDZUWAN"]', 1784690324132);
