INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trong-thoi-ky-bat-on', 'Trong Thời Kỳ Bất ổn', 'In A Time Of Uncertainty', 'https://phimimg.com/upload/vod/20260518-1/c3cab8c1e26b2a7a065f833c1975ce62.jpg', 'https://phimimg.com/upload/vod/20260518-1/d04c5d333fd2fd1171305ca77b9e10f6.jpg', '<p>Chúng ta gặp nhau, tìm hiểu nhau, rồi yêu nhau; chúng ta hôn nhau, ôm nhau, gần gũi nhau, và tận hưởng khoảnh khắc ấy, nhưng liệu điều đó có nghĩa là chúng ta thực sự thuộc về nhau? Liệu có thể nào tất cả những ham muốn, cả thể xác lẫn trừu tượng, lại có thể tạo nên sự khác biệt trong một mối quan hệ? Bởi vì dù anh yêu em, anh vẫn nghĩ đến người khác…</p>', 'Full', 1, 'single', 'completed', 29, 2025, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"CJ Barinaga","avatar":""},{"name":"Jonathan Ivan Rivera","avatar":""},{"name":"Awin Valencia","avatar":""},{"name":"James Ramada","avatar":""},{"name":"Miguel Almendras","avatar":""},{"name":"Oliver Aquino","avatar":""},{"name":"Joy Raz","avatar":""},{"name":"Roy Salazar","avatar":""},{"name":"Dexter Doria","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Sa Panahon ng Walang Katiyakan"]', 1784690324132);
