INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('trong-thoi-ky-bat-on', 'Trong Thời Kỳ Bất ổn', 'In A Time Of Uncertainty', 'trong thời kỳ bất ổn in a time of uncertainty cj barinaga jonathan ivan rivera awin valencia james ramada miguel almendras oliver aquino joy raz roy salazar dexter doria sa panahon ng walang katiyakan', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('banh-sinh-nhat-cua-tong-thong', 'Bánh sinh nhật của Tổng thống', 'The President''s Cake', 'https://phimimg.com/upload/vod/20260517-1/a998e7bdda6df9507e97992dabf9e6c9.jpg', 'https://phimimg.com/upload/vod/20260517-1/9de658c4779b38ee8d6599952bf6a128.jpg', '<p>Trong khi người dân Iraq những năm 1990 đang vật lộn để sống sót qua chiến tranh và tình trạng thiếu lương thực, Saddam Hussein yêu cầu mỗi trường học trong cả nước phải chuẩn bị một chiếc bánh để mừng sinh nhật ông ta. Mặc dù đã cố gắng hết sức để không bị chọn, Lamia, 9 tuổi, vẫn bị chọn trong số các bạn cùng lớp. Cô bé giờ đây phải vận dụng trí thông minh và trí tưởng tượng của mình để thu thập các nguyên liệu cho chiếc bánh bắt buộc, nếu không sẽ phải đối mặt với hậu quả.</p>', 'Full', 1, 'single', 'completed', 13, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Baneen Ahmed Nayyef","avatar":""},{"name":"Sajad Mohamad Qasem","avatar":""},{"name":"Waheed Thabet Khreibat","avatar":""},{"name":"Rahim AlHaj","avatar":""},{"name":"Muthanna Malaghi","avatar":""},{"name":"Ahmad Qasem Saywan","avatar":""},{"name":"Thaer Salem","avatar":""},{"name":"Fatima Abouharoon","avatar":""},{"name":"Mohammed Rheimeh","avatar":""},{"name":"Rokia Alwadi","avatar":""},{"name":"Abdelkarim Jasim","avatar":""},{"name":"Maytham Mreidi","avatar":""},{"name":"Nadia Rashak","avatar":""},{"name":"Ali Khalaf","avatar":""},{"name":"Mahmoud Mazen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Kingdom of Reeds","مملكة القصب","Prezidentin Tortu","كعكه الرئيس","كعكه الريس","Cadeira do bolo","Gâteau du président","Tortas diktatoriui","Mamlaket al-qasab","The President''s Cake"]', 1784690324132);
