INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('panor-ta-thuat-huyet-ngai', 'Panor: Tà Thuật Huyết Ngải', 'Panor', 'https://phimimg.com/upload/vod/20260517-1/97a3b35287cfacb573c2b21b3eed1af1.jpg', 'https://phimimg.com/upload/vod/20260517-1/525b723ac823e903647c2070d95c5d21.jpg', '<p>Sinh ra trong một nghi lễ cổ xưa của làng, Panor phải đối mặt với sự cô lập khi những bất hạnh bí ẩn đeo bám những người xung quanh. Cô phải khám phá sự thật đằng sau lời nguyền đen tối đã ám ảnh cô từ khi sinh ra.</p>', 'Trailer', 1, 'single', 'ongoing', 24, 2025, 'Vietsub', 'FHD', 'Thái Lan', 1, '[{"name":"เฌอปราง อารีย์กุล","avatar":""},{"name":"จักริน กังวานเกียรติชัย","avatar":""},{"name":"ชลิตา ส่วนเสน่ห์","avatar":""},{"name":"รัตนวดี วงศ์ทอง","avatar":""},{"name":"Nuttawatt Thanathaveeprasert","avatar":""},{"name":"นันทวรรณ พงศ์ประเสริฐสิน","avatar":""},{"name":"พิจิกา จิตตะปุตตะ","avatar":""},{"name":"กฤชยศ เลิศประไพ","avatar":""},{"name":"สายฟ้า ตันธนา","avatar":""},{"name":"สหัสชัย ชุมรุม","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Art of the Devil: Beginning","พนอ"]', 1784690324132);
