INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('leanne-morgan-nhung-thu-khong-the-noi-ra', 'Leanne Morgan: Những Thứ Không Thể Nói Ra', 'Leanne Morgan: Unspeakable Things', 'https://phimimg.com/upload/vod/20260517-1/bbf5e777d4d8e54ac7abd12e8b59d27d.jpg', 'https://phimimg.com/upload/vod/20260517-1/78c5597c5ed5619e68e608939bd45ecf.jpg', '<p>Từ chia sẻ bí quyết để có cuộc hôn nhân dài lâu đến thử CBD lần đầu cũng như lần cuối, Leanne Morgan kể hết mọi chuyện thú vị với sự duyên dáng miền Nam của mình.</p>', 'Trailer', 1, 'single', 'ongoing', 12, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Leanne Morgan: Unspeakable Things"]', 1784690324132);
