INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lo-lem-choi-ngai', 'Lọ Lem Chơi Ngải', 'The Book Of Sijjin & Illiyyin', 'https://phimimg.com/upload/vod/20260517-1/f65ecbc37a8e86e30e9353b691e3e737.jpg', 'https://phimimg.com/upload/vod/20260517-1/0ccadb4cd4b772ef27c3f8dbe0f1de34.jpg', '<p>Khi còn nhỏ, Yuli đã chứng kiến cha mẹ mình chết dưới tay một thế lực bí ẩn sau khi mẹ cô bị quỷ ám. Bị gán cho cái mác là đứa trẻ bị nguyền rủa và không ai mong muốn, cô sống sót và lớn lên dưới mái nhà của người vợ khác của cha cô, Ambar, và con gái Laras, chịu đựng sự sỉ nhục liên tục. Được thúc đẩy bởi lòng hận thù, Yuli thực hiện một nghi lễ bị cấm. Khi ma thuật đen tối bén rễ, thế giới xung quanh cô bắt đầu tan vỡ.</p>', 'Trailer', 1, 'single', 'ongoing', 37, 2025, 'Vietsub', 'FHD', 'Indonesia', 1, '[{"name":"Yunita Siregar","avatar":""},{"name":"Dinda Kanyadewi","avatar":""},{"name":"Tarra Budiman","avatar":""},{"name":"Djenar Maesa Ayu","avatar":""},{"name":"Kawai Labiba","avatar":""},{"name":"Sulthan Hamonangan","avatar":""},{"name":"David Chalik","avatar":""},{"name":"Septian Dwi Cahyo","avatar":""},{"name":"Banon Gautama","avatar":""},{"name":"Eduwart Manalu","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Sijjin 2","復仇廝殺夜","Lọ Lem Chơi Ngải","Kitab Sijjin & Illiyyin"]', 1784690324132);
