INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xa-thuat-tieu-tam', 'Xà Thuật Tiểu Tam', 'Sihir Pelakor', 'https://phimimg.com/upload/vod/20260517-1/07b450f8857def39bee6c8463826cf2d.jpg', 'https://phimimg.com/upload/vod/20260517-1/cbe3768ac5f29ce5f9bee1152f1d1810.jpg', '<p>Vita – một nữ sinh trung học – từng có cuộc sống yên bình bên gia đình cho đến khi cô phát hiện cha mình, ông Edi, đang lén lút qua lại với một người phụ nữ tên Rini. Mọi chuyện trở nên tồi tệ hơn khi Rini, kẻ thứ ba đầy mưu mô, sử dụng ma thuật đen để chiếm đoạt Edi và khiến ông dần xa cách vợ con. Từ đó, hàng loạt hiện tượng rùng rợn bắt đầu xảy ra trong ngôi nhà. Âm thanh kỳ quái vang lên mỗi đêm, bầu không khí trở nên nặng nề, còn tính cách của người cha thì thay đổi bất thường. Dưới ảnh hưởng của tà thuật, Edi ngày càng lạnh nhạt, thậm chí tỏ ra xa lạ với chính gia đình mình. Là chị cả, Vita cố gắng níu giữ sự gắn kết giữa các thành viên, chống lại thế lực đen tối đang phá hủy mái ấm của cô.</p>', 'Trailer', 1, 'single', 'ongoing', 28, 2025, 'Vietsub', 'FHD', 'Indonesia', 1, '[{"name":"Anodya Shula Neona Ayu","avatar":""},{"name":"Marcella Zalianty","avatar":""},{"name":"Al Fathir Muchtar","avatar":""},{"name":"Asmara Abigail","avatar":""},{"name":"Jared Ali","avatar":""},{"name":"Hana Malasan","avatar":""},{"name":"Alfie Alfandy","avatar":""},{"name":"Indra Birowo","avatar":""},{"name":"Sofia Yulinar","avatar":""},{"name":"Ruth Marini","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["អំពើស្រីសហាយ","Xà Thuật Tiểu Tam","Cursed","Sihir Pelakor"]', 1784690324132);
