INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gdragon-trong-rap-chieu-phim-bermancy', 'G-Dragon Trong Rạp Chiếu Phim [Übermancy]', 'G-DRAGON IN CINEMA [Übermensch]', 'https://phimimg.com/upload/vod/20260517-1/ecfd90e2f348804e0bcd4749a7c59f48.jpg', 'https://phimimg.com/upload/vod/20260517-1/cbb118c63f5d2ee0cb4a499f2f98d04f.jpg', '<p>Sau tám năm, biểu tượng của một thế hệ đã trở lại với chuyến lưu diễn vòng quanh thế giới hoành tráng — ÜBERMENSCH. Từng nhịp điệu, từng hơi thở, từng khoảnh khắc định hình lại di sản của anh đều bùng nổ trên màn ảnh rộng. Từ những bản quốc ca làm rung chuyển thế giới — Crooked, PO￦ER, HEARTBREAKER — cho đến một danh sách bài hát hoành tráng bao gồm những bản hit kinh điển nhất của anh, cùng với dàn khách mời toàn sao bao gồm TAEYANG, DAESUNG, CL, và nhiều hơn nữa. Cảm nhận nguồn năng lượng thô sơ, ngọn lửa nhiệt huyết, ma thuật không gì sánh bằng — được ghi lại trực tiếp và giải phóng thông qua SCREENX, 4DX và ULTRA 4DX.</p>', 'Trailer', 1, 'single', 'ongoing', 24, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"지드래곤","avatar":""},{"name":"태양","avatar":""},{"name":"대성","avatar":""},{"name":"CL","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["지드래곤 인 시네마 [위버맨쉬]"]', 1784690324132);
