INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-ma-xo', 'Nhà Ma Xó', 'Nhà Ma Xó', 'https://phimimg.com/upload/vod/20260517-1/6afbc74dcc0c363fe03b227e08b583ac.jpg', 'https://phimimg.com/upload/vod/20260517-1/36b8ba62a91578879b6ee80f0cd8fa6f.jpg', '<p>Nhà Ma Xó xoay quanh câu chuyện về bà Hiền, người phụ nữ một mình nuôi 3 người con sau tai nạn chồng qua đời. Mọi chuyện bắt đầu khi người con trai giữa trong một lần thả lưới bắt cá vớt được một cái khạp bằng sành, nắp đậy kín. Từ đó, những hiện tượng kỳ quái liên tiếp xảy ra trong gia đình.</p>', 'Trailer', 1, 'single', 'ongoing', 33, 2025, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Ngô Quang Tuấn","avatar":""},{"name":"Huỳnh Đông","avatar":""},{"name":"Vân Trang","avatar":""},{"name":"Hoàng Kim Ngọc","avatar":""},{"name":"Lâm Thanh Nhã","avatar":""},{"name":"Thạch Kim Long","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Nhà Ma Xó"]', 1784690324132);
