INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pha-dam-sinh-nhat-me', 'Phá Đám: Sinh Nhật Mẹ', 'Spoiled: Mom''s Birthday Party', 'https://phimimg.com/upload/vod/20260517-1/ad67ffa5d2d07e1566bb07f27bdeb123.jpg', 'https://phimimg.com/upload/vod/20260517-1/cf6c033ac490be0f8414ce3abadf4246.jpg', '<p>Bị bọn côn đồ đe dọa, một chàng trai trẻ dàn dựng một đám tang giả cho mẹ mình để đòi tiền bảo hiểm. Nhưng kế hoạch điên rồ và bất hiếu của anh liên tục bị phá hoại — bởi cả người lạ, bạn bè, và đặc biệt là vì ngày anh định đưa mẹ vào quan tài lại trùng với sinh nhật lần thứ 60 của bà.</p>', 'Trailer', 1, 'single', 'ongoing', 18, 2025, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Tín Nguyễn","avatar":""},{"name":"Kim Hải","avatar":""},{"name":"Hồng Ánh","avatar":""},{"name":"Samuel An","avatar":""},{"name":"Hoàng Phi","avatar":""},{"name":"Ái Như","avatar":""},{"name":"Thành Hội","avatar":""},{"name":"Bé Sam","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Phá Đám: Sinh Nhật Mẹ"]', 1784690324132);
