INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-ky-nam', 'Quán Kỳ Nam', 'Ky Nam Inn', 'https://phimimg.com/upload/vod/20260517-1/6d4859c10bceb1a641a3d82954a413db.jpg', 'https://phimimg.com/upload/vod/20260517-1/98c0b325481b7a5d89986f443e68934d.jpg', '<p>Với sự nâng đỡ của người chú quyền lực, Khang được giao cho công việc dịch cuốn “Hoàng Tử Bé” và dọn vào căn hộ bỏ trống ở khu chung cư cũ. Anh làm quen với cô hàng xóm tên Kỳ Nam, một góa phụ từng nổi danh trong giới nữ công gia chánh và giờ lặng lẽ với nghề nấu cơm tháng. Một tai nạn xảy ra khiến Kỳ Nam không thể tiếp tục công việc của mình. Khang đề nghị giúp đỡ và mối quan hệ của họ dần trở nên sâu sắc, gắn bó. Liệu mối quan hệ của họ có thể tồn tại lâu dài giữa những biến động củа xã hội thời bấy giờ?</p>', 'Trailer', 1, 'single', 'ongoing', 25, 2025, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Liên Bỉnh Phát","avatar":""},{"name":"Do Thi Hai Yen","avatar":""},{"name":"Phương Bình","avatar":""},{"name":"Lý Kiều Hạnh","avatar":""},{"name":"Trần Thế Mạnh","avatar":""},{"name":"Tu Quyen","avatar":""},{"name":"Hồ Thành Trung","avatar":""},{"name":"Nguyễn Thu Thắm","avatar":""},{"name":"Lý Hồng Ân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Quán Kỳ Nam"]', 1784690324132);
