INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-giun-dat', 'Thị Trấn Giun đất', 'Wormtown', 'https://phimimg.com/upload/vod/20260514-1/5f8fb24845166e3849c113ad7e2d971b.jpg', 'https://phimimg.com/upload/vod/20260514-1/957f782220745b96f9a20a6e3c950615.jpg', '<p>Một năm sau khi dịch bệnh do loài giun ăn thịt người và gây biến đổi tâm trí gây ra, thị trấn Ashland, Ohio, vốn sống về đêm, đã chấp nhận sự thống trị của ký sinh trùng. Dưới sự lãnh đạo của Thị trưởng Joshua, một người cuồng tín, những người chăn nuôi gia súc truyền bá giáo lý của họ—bằng thuyết phục hoặc bằng vũ lực. Ba người phụ nữ không bị nhiễm bệnh bám trụ để sống sót bằng cách nhặt nhạnh thức ăn, giữ vệ sinh cực kỳ tốt và trốn tránh. Nhưng cuối cùng, tất cả đều gục ngã, dẫn đến sự phản bội, phạm thượng và những cảnh tượng kinh hoàng về xác thịt.</p>', 'Trailer', 1, 'single', 'ongoing', 19, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Caitlin McWethy","avatar":""},{"name":"Rachel Ryu","avatar":""},{"name":"Emily Soppe","avatar":""},{"name":"Maggie Lou Rader","avatar":""},{"name":"A.J. Baldwin","avatar":""},{"name":"Jordan Mullins","avatar":""},{"name":"Jim Azelvandre","avatar":""},{"name":"Madison Murrah","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Wormtown"]', 1784690324132);
