INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-vu-trinh-sat', 'Đặc Vụ Trinh Sát', 'Agent Recon', 'https://phimimg.com/upload/vod/20260512-1/2232e7ce0c1e55a2830e0019a11532f9.jpg', 'https://phimimg.com/upload/vod/20260512-1/2573e0b02953c993b3041423ec2f6644.jpg', '<p>Một đội đặc nhiệm quân sự bí mật theo dõi một nhiễu loạn năng lượng bí ẩn tại một căn cứ bí mật ở New Mexico, nơi bị nghi ngờ đang thử nghiệm công nghệ ngoài hành tinh. Tại đây, cả đội chạm trán một sinh vật bí ẩn sở hữu sức mạnh và tốc độ phi thường, cùng khả năng điều khiển một đội quân chiến binh vô tri. Bộ ba phải chiến đấu chống lại lũ quái vật hung hãn để ngăn chặn sự diệt vong của nhân loại.</p>', 'Full', 1, 'single', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Derek Ting","avatar":""},{"name":"Marc Singer","avatar":""},{"name":"Chuck Norris","avatar":""},{"name":"Sylvia Kwan","avatar":""},{"name":"Jason Scott Jenkins","avatar":""},{"name":"Matthew Ryan Burnett","avatar":""},{"name":"Nikki Leigh","avatar":""},{"name":"Teo Briones","avatar":""},{"name":"Christopher Showerman","avatar":""},{"name":"Yarett Harper","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '["Агент разведки","Agent Recon"]', 1784690324132);
