INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-chup-buc-anh-lich-su', 'Người Chụp Bức Ảnh Lịch Sử', 'The Stringer: The Man Who Took The Photo', 'https://phimimg.com/upload/vod/20260513-1/3351cba2e930b1e2514c486ec4dbf2af.jpg', 'https://phimimg.com/upload/vod/20260513-1/9c54bddec3c08c4821845e84343b57d8.jpg', '<p>Phim tài liệu xoay quanh hành trình điều tra xem ai thật sự chụp bức ảnh chiến tranh nổi tiếng “Napalm Girl”. Bộ phim mở ra bí mật được chôn giấu hơn 50 năm: có thể người chụp không phải là Nick Ut như lịch sử ghi nhận, mà là một nhiếp ảnh tự do Việt Nam tên Nguyễn Thành Nghệ.</p>', 'Full', 1, 'single', 'completed', 28, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Gary Knight","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["The Stringer","Napalm Kızı Fotoğrafını Kim Çekti?","The Stringer: The Man Who Took the Photo"]', 1784690324132);
