INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giot-nuoc-mat-cua-quy-phan-1', 'Giọt Nước Mắt Của Quỷ (Phần 1)', 'Devil May Cry (Season 1)', 'https://phimimg.com/upload/vod/20250404-1/baab62e8aa4f882504245632139c8ad6.jpg', 'https://phimimg.com/upload/vod/20250404-1/c6cf0c5fd29cf8a4c984d3af83dcfedb.jpg', '<p>Khi một ác nhân bí ẩn đe dọa mở cánh cổng Địa Ngục, một thợ săn quỷ siêu đẹp trai có thể là tia hi vọng lớn nhất để cứu rỗi thế giới.</p>', 'Hoàn Tất (8/8)', 8, 'hoathinh', 'completed', 34, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Johnny Yong Bosch","avatar":""},{"name":"Scout Taylor Compton","avatar":""},{"name":"Kevin Conroy","avatar":""},{"name":"Hoon Lee","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Devil May Cry","Д''ябал можа плакаць","鬼泣","השד יכול לבכות","شیطان هم میگرید","デビルメイクライシリーズ","Дьявол может плакать"]', 1784690324132);
