INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('giot-nuoc-mat-cua-quy-phan-1', 'Giọt Nước Mắt Của Quỷ (Phần 1)', 'Devil May Cry (Season 1)', 'giọt nước mắt của quỷ (phần 1) devil may cry (season 1) johnny yong bosch scout taylor compton kevin conroy hoon lee devil may cry д''ябал можа плакаць 鬼泣 השד יכול לבכות شیطان هم میگرید デビルメイクライシリーズ дьявол может плакать', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dinh-thinh-la-yeu', 'Dính ''Thính'' Là Yêu', 'Virus', 'https://phimimg.com/upload/vod/20250629-1/8f05a55f565c4540bbad93904a89f954.jpg', 'https://phimimg.com/upload/vod/20250629-1/a1550769d6e726d9afe2c579f7bc4494.jpg', '<p>Dính “Thính” Là Yêu là bộ phim hài lãng mạn xoay quanh cô nàng Taek-seon (Bae Doo-na) - bộ trưởng bộ thờ ơ, chủ tịch hội vô cảm, trưởng nhóm anti tình yêu. Đang sống cuộc đời như một “tảng băng di động”, Taek-seon bất ngờ bị nhiễm “virus tình yêu” - cơn dịch bệnh kỳ lạ khiến con người không thể kiềm chế ham muốn yêu và được yêu. Nếu không tìm được tình yêu đích thực của đời mình trong vòng 5 ngày, người nhiễm virus sẽ chết… vì cô đơn, theo đúng nghĩa đen. Đứng trước những ngã rẽ là can đảm đi tìm tình yêu hay chấp nhận từ bỏ cuộc sống, Taek-seon đã gặp gỡ 3 người đàn ông với hi vọng họ có thể thay đổi số phận của cô. Đó là nhà nghiên cứu Nam Soo-pil (Son Suk-ku), bạn học cùng tiểu học Kim Yeon-woo (Chang Ki-ha) và chuyên gia y tế Lee Kyun (Kim Yoon-seok). Những phản ứng tình yêu “dở khóc dở cười” bắt đầu bùng nổ trên hành trình chữa bệnh của Taek-seon khiến cô phải tự hỏi: Liệu đây chỉ là triệu chứng mà virus mang lại hay đó chính là tình yêu thật sự?</p>', 'Full', 1, 'single', 'completed', 24, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 1, '[{"name":"Bae Doona","avatar":""},{"name":"Kim Yun-seok","avatar":""},{"name":"Chang Ki-ha","avatar":""},{"name":"Son Suk-ku","avatar":""},{"name":"Moon Sung-keun","avatar":""},{"name":"Kim Hie-won","avatar":""},{"name":"Oh Hyun-kyung","avatar":""},{"name":"Min Jin-woong","avatar":""},{"name":"Yeom Hye-ran","avatar":""},{"name":"Kim Ye-won","avatar":""},{"name":"Park Hee-von","avatar":""},{"name":"Car","avatar":""},{"name":"the garden","avatar":""},{"name":"Lee Nam-gyeong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["病毒","Baireoseu","바이러스"]', 1784690324132);
