INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dinh-thinh-la-yeu', 'Dính ''Thính'' Là Yêu', 'Virus', 'dính ''thính'' là yêu virus bae doona kim yun-seok chang ki-ha son suk-ku moon sung-keun kim hie-won oh hyun-kyung min jin-woong yeom hye-ran kim ye-won park hee-von car the garden lee nam-gyeong 病毒 baireoseu 바이러스', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-nguoi-duyen-ma-tai-hop-2025', 'Tình Người Duyên Ma: Tái Hợp', 'Kang Solah From Kang Mak x Nenek Gayung', 'https://phimimg.com/upload/vod/20260513-1/453e2737621593c8c81466fb9549fb38.jpg', 'https://phimimg.com/upload/vod/20260513-1/68a170ab4199009439aa534577570055.jpg', '<p>Solah Vicenzio trở về quê hương cùng nhóm bạn Fajrul, Jaka và Supra. Solah cứ ngỡ ngày về của mình sẽ được chào đón như một vị anh hùng, nhưng trớ trêu thay, dân làng lại nhầm tưởng anh là một hồn ma. Nỗi thất vọng càng thêm chồng chất khi anh biết rằng Dara Gonzales – cô gái anh thầm thương trộm nhớ bao lâu nay – chuẩn bị kết hôn với chính em trai mình, Iqbal.&nbsp; Tuy nhiên, đám cưới của họ bị gián đoạn bởi sự xuất hiện kinh hoàng của Nenek Gayung – hồn ma &quot;Bà già gáo múc nước&quot; chuyên đi tìm kiếm nạn nhân tiếp theo để tắm rửa cho xác chết. Cách duy nhất để cứu vãn đám cưới của Iqbal và Dara là Solah cùng nhóm bạn phải đối mặt với Nenek Gayung và tìm kiếm sự giúp đỡ từ Kangmas Pusi.</p>', 'Full', 1, 'single', 'completed', 31, 2025, 'Vietsub', 'FHD', 'Indonesia', 1, '[{"name":"Rigen Rakelna","avatar":""},{"name":"Indra Jegel","avatar":""},{"name":"Indro","avatar":""},{"name":"Tora Sudiro","avatar":""},{"name":"Davina Karamoy","avatar":""},{"name":"Asri Welas","avatar":""},{"name":"Andre Taulany","avatar":""},{"name":"Praz Teguh","avatar":""},{"name":"Indy Barends","avatar":""},{"name":"Kenzy Taulany","avatar":""},{"name":"Alexandra Vallerie","avatar":""},{"name":"Sabrina Nazwa","avatar":""},{"name":"Sheila Kusnadi","avatar":""},{"name":"Sulthan Hamonangan","avatar":""},{"name":"Deni Kumis","avatar":""},{"name":"Jerry Libing","avatar":""},{"name":"Johan Juling","avatar":""},{"name":"Bagas Sianip","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Kang Solah","Kang Solah from Kang Mak x Nenek Gayung"]', 1784690324132);
