INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ta-khon-quy-doi-lot-nguoi', 'Ta Khon: Quỷ Đội Lốt Người', 'The Cursed Mask', 'https://phimimg.com/upload/vod/20260513-1/b2b832cd08e61e8fdc1c5c21515c7bdf.jpg', 'https://phimimg.com/upload/vod/20260513-1/3492e30d7dd204e0b5d39d9dbf32ef2e.jpg', '<p>Khi ngôi nhà mới được xây trên mảnh đất của thần linh, gia đình Joi đã phải lập tức đối mặt với cơn thịnh nộ của Phi Ta Khon(Quỷ Đội Lốt Người). Để giải cứu chính mình và em gái khỏi lời nguyền nghiệt ngã, Joi quyết tâm lật mở sự thật. Thế nhưng, đằng sau chiếc mặt nạ quỷ lại là một bí mật đen tối mà cậu không bao giờ ngờ tới.</p>', 'Full', 1, 'single', 'completed', 24, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Panuwat Sopradit","avatar":""},{"name":"Ploypaphas Fonkaewsiwaporn","avatar":""},{"name":"Diana Flipo","avatar":""},{"name":"Thiti Srinuan","avatar":""},{"name":"Noknoi Uraiporn","avatar":""},{"name":"Thanatsaran Samthonglai","avatar":""},{"name":"Dan Chupong","avatar":""},{"name":"Boonsong Nakphoo","avatar":""},{"name":"Panuwat Tawilchindarat","avatar":""},{"name":"Parinphop Pahoul","avatar":""},{"name":"Mondop Heamtan","avatar":""},{"name":"Rathasat Butwong","avatar":""},{"name":"Putticha Boonyamas","avatar":""},{"name":"Thunyaphat I","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Takhon","Ta Khon","Ta Khon: The Masked Curse","ตาโขน"]', 1784690324132);
