INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-tran-quy', 'Nhà Trấn Quỷ', 'Our House', 'https://phimimg.com/upload/vod/20260513-1/93ce7fcc63b4c292a64b27fd030c87bb.jpg', 'https://phimimg.com/upload/vod/20260513-1/eb23f4dba4598cefc01f54d4dbde9f7f.jpg', '<p>Phim kể về cặp vợ chồng trẻ dọn vào ngôi nhà hẻo lánh giá rẻ bất thường và dần bị cuốn vào những hiện tượng kỳ lạ, ám ảnh, khiến cuộc sống gia đình tan vỡ khi sự thật kinh hoàng lộ diện.</p>', 'Full', 1, 'single', 'completed', 20, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Teeradetch Metawarayut","avatar":""},{"name":"Sarunrat Puagpipat","avatar":""},{"name":"Pichsinee Veerasuthima","avatar":""},{"name":"Viyada Umarin","avatar":""},{"name":"Witsarut Himmarat","avatar":""},{"name":"Pacharapon Jantieng","avatar":""},{"name":"Sasatorn Buain","avatar":""},{"name":"Rinrada Lamroekchai","avatar":""},{"name":"Rutrawee Jeeradechakul","avatar":""},{"name":"Panisa Udomruangkiat","avatar":""},{"name":"Katanyu Swangsri","avatar":""},{"name":"Phunathat Wiwatphatthanaanan","avatar":""},{"name":"S","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Kang Baan","Next Door","Our House","ข้างบ้าน"]', 1784690324132);
