INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nha-tran-quy', 'Nhà Trấn Quỷ', 'Our House', 'nhà trấn quỷ our house teeradetch metawarayut sarunrat puagpipat pichsinee veerasuthima viyada umarin witsarut himmarat pacharapon jantieng sasatorn buain rinrada lamroekchai rutrawee jeeradechakul panisa udomruangkiat katanyu swangsri phunathat wiwatphatthanaanan s kang baan next door our house ข้างบ้าน', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lieu-an-nhieu-modual-nekad', 'Liều Ăn Nhiều (Modual Nekad)', 'Risky Business 2', 'https://phimimg.com/upload/vod/20260513-1/4a8ec665daca8be9184e9171f97226d5.jpg', 'https://phimimg.com/upload/vod/20260513-1/a22052ced6fab5f9ff350f09abcb1b44.jpg', '<p>Saipul và Jamal vô cùng giận dữ khi phát hiện số tiền trong vali của mình đã biến mất. Hóa ra, Marwan đã quyết định dùng số tiền đó để mua lại ngôi nhà của cha họ vốn đã bị ngân hàng tịch biên. Tuy nhiên, Marwan lại tìm thấy một bức ảnh với những con số bí ẩn được viết trên đó bên trong chiếc vali bị rách, điều này đã đẩy ba anh em vào một tình huống ngàn cân treo sợi tóc. Mọi chuyện bắt đầu dính líu đến một tay doanh nhân cực kỳ nguy hiểm, một công tố viên tham nhũng và cả quá khứ kinh hoàng của chính ba anh em.</p>', 'Full', 1, 'single', 'completed', 27, 2025, 'Vietsub', 'FHD', 'Indonesia', 0, '[{"name":"Gading Marten","avatar":""},{"name":"Tarra Budiman","avatar":""},{"name":"Fatih Unru","avatar":""},{"name":"Gisella Anastasia","avatar":""},{"name":"Gempita Nora Marten","avatar":""},{"name":"Sahila Hisyam","avatar":""},{"name":"Ira Wibowo","avatar":""},{"name":"Surya Saputra","avatar":""},{"name":"Sadana Agung","avatar":""},{"name":"Rigen Rakelna","avatar":""},{"name":"Ananta Rispo","avatar":""},{"name":"Ismi Melinda","avatar":""},{"name":"Josevanie Looranie Allestra","avatar":""},{"name":"Marella Mulwanto","avatar":""},{"name":"Ferry Maryadi","avatar":""},{"name":"Edo Borne","avatar":""},{"name":"B","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Modual Nekad"]', 1784690324132);
