INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-nhan-kiet-bi-ngan-ky-hoa', 'Địch Nhân Kiệt: Bỉ Ngạn Kỳ Hoa', 'Detective Dee: The Other Shore Flower', 'https://phimimg.com/upload/vod/20260511-1/3d65448efed11f8b79dab04cfefeb58b.jpg', 'https://phimimg.com/upload/vod/20260511-1/0fa13b63118ae56aba98d5ffee0b5dcd.jpg', '<p>Thẩm phán Dee điều tra một âm mưu liên quan đến một loại thần dược nguy hiểm và sự hỗn loạn siêu nhiên, cuối cùng vạch trần một vị tướng nổi loạn đã sử dụng thần dược làm cái cớ để âm mưu đảo chính quân sự chống lại Hoàng hậu Võ Tắc Thiên.</p>', 'Full', 1, 'single', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"陳浩民","avatar":""},{"name":"尚娜","avatar":""},{"name":"金宁","avatar":""},{"name":"Liu Jin","avatar":""},{"name":"崔冬辰","avatar":""},{"name":"岳训宇","avatar":""},{"name":"Liu Weizhou","avatar":""},{"name":"陈宇星","avatar":""},{"name":"陈炳强","avatar":""},{"name":"李颖芝","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["狄仁杰之彼岸奇花"]', 1784690324132);
