INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ung-cuu-loi-dinh', 'Ứng Cứu Lôi Đình', 'Thunderbolt Rescue', 'https://phimimg.com/upload/vod/20260511-1/c1b70a44c6b7cb8646cead94329b90cd.jpg', 'https://phimimg.com/upload/vod/20260511-1/3a47bfa6cbc6206c41986e976c0c63d6.jpg', '<p>Câu chuyện kể về Trình Khải, một lính đặc chủng đã giải ngũ. Để tìm kiếm người vợ là Tiêu Linh, một nhân viên y tế bị mất tích, anh một mình xâm nhập vào khu vực Shachar, nơi các thế lực khủng bố hoành hành. Trình Khải lén thâm nhập cứ điểm trung tâm Talin, đối đầu trực diện với bọn lính đánh thuê đang chiếm đóng nơi đây. Trong quá trình đó, anh nhận được sự trợ giúp then chốt từ Mira, một cô gái bị bắt cóc. Hai người cùng nhau trốn tránh truy sát, vượt qua muôn vàn hiểm nguy, cuối cùng phá vỡ vòng phong tỏa, giải cứu Mira khỏi nanh vuốt của đám lính đánh thuê, viết nên một hành trình sinh tử đầy cam go và quả cảm.<br/>&nbsp;</p>', 'Full', 1, 'single', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"安志傑","avatar":""},{"name":"Tara Clance","avatar":""},{"name":"赵儒嫣","avatar":""},{"name":"高明燊","avatar":""},{"name":"Zhuang Xiaolong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["雷霆营救"]', 1784690324132);
