INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-con-chung-ta', 'Không Còn Chúng Ta', 'Once We Were Us', 'https://phimimg.com/upload/vod/20260510-1/ce11fe85306b3e67e74d2eeb68b86623.jpg', 'https://phimimg.com/upload/vod/20260510-1/da9de1bb88783ed3479eb38cf4cf08a5.jpg', '<p>Jeong-won và Eun-ho yêu nhau chân thành và sâu đậm bằng những tất cả những gì họ có ở khoảng thời gian đẹp nhất của thanh xuân. Nhưng tình yêu của tuổi trẻ không tránh khỏi sự non nớt, bồng bột để rồi họ chọn rời xa nhau. Nhiều năm sau gặp lại, họ nhận ra: chính những tháng năm đã yêu và đã đau ấy đã giúp họ trưởng thành hơn, hiểu được tình yêu và biết cách yêu thương hơn. Chỉ tiếc rằng khi ấy, yêu thương này họ không dành cho nhau được nữa…</p>', 'Full', 1, 'single', 'completed', 24, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"Koo Kyo-hwan","avatar":""},{"name":"Mun Ka-young","avatar":""},{"name":"Shin Jung-keun","avatar":""},{"name":"Lee Sang-yeob","avatar":""},{"name":"Kim Seo-won","avatar":""},{"name":"Lim Jae-hyeok","avatar":""},{"name":"Kim So-yul","avatar":""},{"name":"Kang Mal-geum","avatar":""},{"name":"Ji Su-yeon","avatar":""},{"name":"Lee Jae-in","avatar":""},{"name":"Yeo Eun-chae","avatar":""},{"name":"Kim Keum-soon","avatar":""},{"name":"Yang Eui-jin","avatar":""},{"name":"Ji Su-yeon","avatar":""},{"name":"Song Chi-hoon","avatar":""},{"name":"Jang Ji-yong","avatar":""},{"name":"Song Chang-gyu","avatar":""},{"name":"Seo Soo-chan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["먼 훗날 우리","之后的我们","后来的我们","Una vez fuimos nosotros","Once We Were Us","もしも私たち","만약에 우리"]', 1784690324132);
