INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chiec-xe-tank', 'Chiếc Xe Tank', 'The Tank', 'https://phimimg.com/upload/vod/20260510-1/84cc9aae06555406f735e351cc7008ec.jpg', 'https://phimimg.com/upload/vod/20260510-1/dcfa3e7c11771c02469ba2e0efbeb2ff.jpg', '<p>Một kíp lái xe tăng Tiger của Đức được cử đi thực hiện nhiệm vụ nguy hiểm giải cứu sĩ quan Paul von Hardenburg bị mất tích khỏi một hầm trú ẩn tối mật phía sau chiến tuyến của địch. Khi vượt qua vùng đất không người đầy chết chóc, họ không chỉ phải đối mặt với kẻ thù mà còn cả nỗi sợ hãi và những ám ảnh nội tâm của chính mình. Được tiếp sức bởi ma túy đá của Wehrmacht, nhiệm vụ của họ dần trở thành một cuộc hành trình vào tận cùng bóng tối.</p>', 'Trailer', 1, 'single', 'ongoing', 37, 2025, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Laurence Rupp","avatar":""},{"name":"David Schütter","avatar":""},{"name":"Sebastian Urzendowsky","avatar":""},{"name":"Leonard Kunz","avatar":""},{"name":"Yoran Leicher","avatar":""},{"name":"André Hennicke","avatar":""},{"name":"Arndt Schwering-Sohnrey","avatar":""},{"name":"Tilman Strauss","avatar":""},{"name":"Yana Shevchenko","avatar":""},{"name":"Alžběta Malá","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Tank","Тигр","猛虎战车","猛虎末路","Der Tiger"]', 1784690324132);
