INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mong-vuot-gau-trai', 'Móng Vuốt Gấu Trại', 'Bear Claw Camp', 'https://phimimg.com/upload/vod/20260510-1/c789dff0f75a6a25e09cf5c24a600fd7.jpg', 'https://phimimg.com/upload/vod/20260510-1/5c96d368494cb728a54810cdf6e9c555.jpg', '<p>Trong một cuộc phiêu lưu cùng những đứa trẻ dũng cảm, một con chồn hôi biết nói và một kẻ phản diện với quá nhiều xi măng trên đầu, Maia và Jan, hai nhân vật chính của chúng ta, có một nhiệm vụ duy nhất: cứu lấy trại hè.</p>', 'Trailer', 1, 'single', 'ongoing', 41, 2025, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Júlia Raya","avatar":""},{"name":"Martín Abello","avatar":""},{"name":"Anabel Alonso","avatar":""},{"name":"Edu Soto","avatar":""},{"name":"Gonçalo Diniz","avatar":""},{"name":"Elisabet Casanovas","avatar":""},{"name":"Adrian Grösser","avatar":""},{"name":"Carlos Latre","avatar":""},{"name":"Ana Morgade","avatar":""},{"name":"Iñigo Galiano","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Campamento Garra de Oso"]', 1784690324132);
