INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kantara-huyen-thoai-chuong-1', 'Kantara - Huyền Thoại: Chương 1', 'Kantara - A Legend: Chapter 1', 'https://phimimg.com/upload/vod/20260510-1/e1b89f3d38bf98e689a87abda7bb29a4.jpg', 'https://phimimg.com/upload/vod/20260510-1/ce28ec45feba945609333aff96eb7499.jpg', '<p>Trong thời kỳ trị vì của triều đại Kadamba, vua Vijayendra, người cai trị vùng đất chư hầu hư cấu Bangra, đã gặp phải số phận cuối cùng của mình khi mạo hiểm vào khu rừng huyền bí Kantara. Chứng kiến điều này, con trai ông là Rajashekara đã phong tỏa biên giới vương quốc. Sau đó, hoàng tử Kulashekara đã mở lại biên giới bằng một cuộc tàn sát dã man. Nhân vật chính, Berme, trên con đường tìm kiếm sự thịnh vượng, đã vượt qua ranh giới và châm ngòi cho một cuộc xung đột về đức tin, quyền lực và số phận giữa Vương quốc và Thiên nhiên.</p>', 'Trailer', 1, 'single', 'ongoing', 23, 2025, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Rishab Shetty","avatar":""},{"name":"Rukmini Vasanth","avatar":""},{"name":"Jayaram","avatar":""},{"name":"Gulshan Devaiah","avatar":""},{"name":"Ramitha Shailendra","avatar":""},{"name":"Pramod Shetty","avatar":""},{"name":"Naveen D. Padil","avatar":""},{"name":"Rakesh Poojari","avatar":""},{"name":"Prakash Thuminad","avatar":""},{"name":"Deepak Rai Panaje","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Kantara: A Legend – Chapter 1","Kantara - A Legend: Chapter 1","ಕಾಂತಾರ: ಅಧ್ಯಾಯ - ೧"]', 1784690324132);
