INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-dung-cho-tre-em-an', 'Xin đừng Cho Trẻ Em ăn.', 'Please Don''t Feed The Children', 'https://phimimg.com/upload/vod/20260510-1/05f34960101d0ccb2489145390589ee5.jpg', 'https://phimimg.com/upload/vod/20260510-1/7b1bebd3c9db0fae182d535357d2a886.jpg', '<p>Sau khi một dịch bệnh virus tàn phá dân số trưởng thành của đất nước, một nhóm trẻ mồ côi lên đường về phía nam để tìm kiếm một cuộc sống mới, nhưng lại rơi vào tay một người phụ nữ điên loạn đang che giấu một bí mật nguy hiểm.</p>', 'Trailer', 1, 'single', 'ongoing', 20, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Michelle Dockery","avatar":""},{"name":"Zoe Colletti","avatar":""},{"name":"Andrew Liner","avatar":""},{"name":"Dean Scott Vazquez","avatar":""},{"name":"Regan Aliyah","avatar":""},{"name":"Joshuah Melnick","avatar":""},{"name":"Emma Meisel","avatar":""},{"name":"Giancarlo Esposito","avatar":""},{"name":"Vernon Davis","avatar":""},{"name":"Lilit Grigoryev","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["No alimentes a los niños","Não Alimente A Criança","Одни из нас","Пожалуйста, не кормите детей","S''il vous plaît, ne nourrissez pas les enfants","Please Don''t Feed the Children"]', 1784690324132);
