INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ve-dep-tu-noi-dau', 'Vẻ đẹp Từ Nỗi đau', 'Beauty From Pain', 'https://phimimg.com/upload/vod/20260510-1/d45e2bd0257769b8f6839b1188128870.jpg', 'https://phimimg.com/upload/vod/20260510-1/6266d57de968a0769dd91288e0999de6.jpg', '<p>Sau một biến cố đau lòng, một nữ nhạc sĩ trẻ đầy tham vọng đã trốn sang Úc. Cô đồng ý bắt đầu một mối tình không ràng buộc với một ông trùm rượu vang tỷ phú, nhưng khi nảy sinh tình cảm, cô phải lựa chọn giữa việc rời bỏ anh ta hoặc mạo hiểm trái tim mình với một người đàn ông sợ yêu.</p>', 'Trailer', 1, 'single', 'ongoing', 26, 2025, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"Samantha Allsop","avatar":""},{"name":"Jackson Gallagher","avatar":""},{"name":"Arielle Cartwright","avatar":""},{"name":"Callan Colley","avatar":""},{"name":"Brittany Grey","avatar":""},{"name":"Jasmine Barui","avatar":""},{"name":"Vanessa Moltzen","avatar":""},{"name":"Patrick Atchison","avatar":""},{"name":"Kim Denman","avatar":""},{"name":"Victoria Little","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Beauty from Pain"]', 1784690324132);
