INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-tre-mo-coi-2025', 'Đứa Trẻ Mồ Côi', 'The Orphans', 'https://phimimg.com/upload/vod/20260508-1/691783429f5666430e976c66b25517ff.jpg', 'https://phimimg.com/upload/vod/20260508-1/ab3684a0993a3781ebe82ab15c68644d.jpg', '<p>Gab và Driss, đôi bạn thời thơ ấu nhưng giờ đây bất hòa kể từ khi rời trại trẻ mồ côi, có cuộc sống hoàn toàn trái ngược - một người là cảnh sát thuộc Tổng cục Cảnh sát Quốc gia Nigeria (IGPN), người kia là tay sai cho bọn côn đồ. Khi người yêu đầu tiên của họ qua đời trong một tai nạn đáng ngờ, con gái 17 tuổi của cô, Leïla, lấy khẩu súng của Gab và bắt đầu truy tìm một tổ chức quyền lực sẵn sàng làm bất cứ điều gì để che đậy vụ án. Buộc phải hợp tác, hai người bạn mồ côi phải ngăn chặn cô trước khi cô vượt qua ranh giới không thể quay trở lại...</p>', 'Full', 1, 'single', 'completed', 22, 2025, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Alban Lenoir","avatar":""},{"name":"Dali Benssalah","avatar":""},{"name":"Sonia Faidi","avatar":""},{"name":"Anouk Grinberg","avatar":""},{"name":"Romain Levi","avatar":""},{"name":"Suzanne Clément","avatar":""},{"name":"Naidra Ayadi","avatar":""},{"name":"Guillaume Soubeyran","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Yetimlər","Les Orphelins"]', 1784690324132);
