INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-bong-va-ghi-ban', 'Chuyền bóng và ghi bàn', 'Pass and Goal', 'https://phimimg.com/upload/vod/20260508-1/56e85a174faffc541970a8c0bd3a6f86.jpg', 'https://phimimg.com/upload/vod/20260508-1/0269622062b19bad794dd3ca4c6675be.jpg', '<p>Từng là một cố vấn tài chính thành đạt, Hay Man mất tất cả và phải chuyển từ biệt thự xa hoa ở Deep Water Bay đến căn nhà khiêm tốn của người em họ ở &quot;Deep Water Bo&quot;. Với hy vọng khôi phục lại vận may, cô đồng ý huấn luyện một đội bóng đá U12 non nớt do người em họ Ying dẫn dắt cùng các em nhỏ trong khu phố tham gia một giải đấu do một người thừa kế giàu có thiếu kinh nghiệm tổ chức. Điều bắt đầu như một nhiệm vụ bất đắc dĩ nhanh chóng biến thành tình cảm hướng dẫn thực sự, khi Hay Man giúp các em nhỏ đối mặt với khó khăn và tìm lại được mục đích sống của chính mình. Khi đội bóng yếu thế lọt vào chung kết, cô phải lựa chọn giữa cuộc sống xa hoa trong quá khứ và bản sắc mới tìm được.</p>', 'Full', 1, 'single', 'completed', 24, 2025, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Gigi Leung Wing-Kei","avatar":""},{"name":"Peter Chan Charm-Man","avatar":""},{"name":"Ling Man-Lung","avatar":""},{"name":"Rachel Leung","avatar":""},{"name":"Tommy Chu Pak-Hong","avatar":""},{"name":"Henry Chan","avatar":""},{"name":"Chau Tsz-Yuet","avatar":""},{"name":"Sahal Zaman","avatar":""},{"name":"Rondi Chan","avatar":""},{"name":"Tam Tsun-Yin","avatar":""},{"name":"Shin Cheuk-Kiu","avatar":""},{"name":"Chan Fai-Hung","avatar":""},{"name":"Renci Yeung","avatar":""},{"name":"Carson Wong Tsz-Yin","avatar":""},{"name":"Sek Kam-Wah","avatar":""},{"name":"Andy Wong Chi-Dik","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["逆转上半场","逆轉上半場"]', 1784690324132);
