INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-lo-dao-tac', 'Đại Lộ Đạo Tặc', 'Thieves Highway', 'https://phimimg.com/upload/vod/20260508-1/ffd72bd580332b71d0f197cbdb104ada.jpg', 'https://phimimg.com/upload/vod/20260508-1/eea3d3c62496a8bdf41b214504fcb4d2.jpg', '<p>Giữa vùng hoang mạc mênh mông, nơi chỉ còn gió và bụi đỏ làm bạn, một viên cảnh sát cô độc (Aaron Eckhart) tình cờ phát hiện âm mưu vận chuyển đàn gia súc bị đánh cắp xuyên biên giới. Không có viện trợ, không có tín hiệu liên lạc, anh buộc phải đối mặt với một nhóm tội phạm liều lĩnh do một kẻ cầm đầu tàn nhẫn (Devon Sawa) dẫn dắt. Mỗi bước đi, mỗi phát súng đều có thể là ranh giới giữa sống và chết. Khi màn đêm buông xuống, trò chơi sinh tồn bắt đầu – một cuộc rượt đuổi nghẹt thở giữa công lý và tội ác, nơi chỉ kẻ kiên cường nhất mới có thể trụ lại đến bình minh.</p>', 'Full', 1, 'single', 'completed', 22, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Aaron Eckhart","avatar":""},{"name":"Devon Sawa","avatar":""},{"name":"Lochlyn Munro","avatar":""},{"name":"Brooke Langton","avatar":""},{"name":"Michael Shamus Wiles","avatar":""},{"name":"Lucy Martin","avatar":""},{"name":"Ronnie Gene Blevins","avatar":""},{"name":"Darin Cooper","avatar":""},{"name":"Ava Paloma","avatar":""},{"name":"Shane Graham","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["כביש הגנבים","Thieves Highway"]', 1784690324132);
