INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-vu-cuoi-cung-phat-sung-dinh-menh', 'Phi Vụ Cuối Cùng (Phát Súng Định Mệnh)', 'The Last Shot', 'https://phimimg.com/upload/vod/20260424-1/56a04859e68b0ef916133e682b367a37.jpg', 'https://phimimg.com/upload/vod/20260424-1/1a2c8a85d127d1bc755132458079cbf7.jpg', '<p>Petch là một tay súng đánh thuê, người đã dành phần lớn cuộc đời sống giữa thế giới bạo lực, nơi những phi vụ đẫm máu diễn ra như một phần công việc thường nhật. Sau nhiều năm lún sâu vào tội lỗi, Petch bắt đầu khao khát rời bỏ con đường cũ để tìm lại tự do và một cuộc sống bình thường. Thế nhưng quá khứ không dễ dàng buông tha anh. Khi những người thân cận bị cuốn vào cuộc thanh trừng giữa các băng nhóm, Petch buộc phải quay lại thế giới mà anh từng cố gắng trốn chạy. Anh chấp nhận thực hiện một nhiệm vụ cuối cùng đầy nguy hiểm, với hy vọng có thể xóa bỏ mọi ân oán trong quá khứ. Nhưng cũng từ đây, Petch bị đẩy vào cuộc đối đầu nghẹt thở với những thế lực từng tạo nên anh. Trong trận chiến sinh tử ấy, mỗi viên đạn đều mang theo cái giá phải trả, và chỉ một sai lầm cũng có thể khiến anh đánh đổi bằng chính mạng sống của mình.</p>', 'Full', 1, 'single', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Thái Lan', 1, '[{"name":"Somphol Rungphanit","avatar":""},{"name":"Patara Eksangkul","avatar":""},{"name":"Sarika Sathsilpsupa","avatar":""},{"name":"Benjamin Joseph Varney","avatar":""},{"name":"Auttakorn Boonpeng","avatar":""},{"name":"Chatchai Plengpanich","avatar":""},{"name":"Arun Pawilai","avatar":""},{"name":"Jirawat Wachirasarunpat","avatar":""},{"name":"Suchatti Janed","avatar":""},{"name":"Arunphong Naraphan","avatar":""},{"name":"Yasaka Chaisorn","avatar":""},{"name":"Peeraphon Thiancharoen","avatar":""},{"name":"Nopphanan Thon","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mue Puen","Phi Vụ Cuối Cùng","라스트샷","Vida de Assassino","มือปืน"]', 1784690324133);
