INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mien-dat-sinh-ton', 'Miền Đất Sinh Tồn', '40 Acres', 'https://phimimg.com/upload/vod/20260509-1/c3bc2ceb43848bb7c8b2b207ed474048.jpg', 'https://phimimg.com/upload/vod/20260509-1/fa657a863de9730a923f4f4d5276cd61.jpg', '<p>Lấy bối cảnh tương lai hậu tận thế khi nạn đói và dịch bệnh khiến xã hội sụp đổ, gia đình Freeman — hậu duệ của những người nông dân da màu từng chạy sang Canada sau Nội chiến Mỹ — phải bảo vệ trang trại và nguồn lương thực của mình trước các băng nhóm bạo lực và cả những kẻ ăn thịt người.</p>', 'Full', 1, 'single', 'completed', 21, 2025, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Danielle Deadwyler","avatar":""},{"name":"Kataem O''Connor","avatar":""},{"name":"Michael Greyeyes","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["40 Acres"]', 1784690324133);
