INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-theo-doi-toi', 'Đừng Theo Dõi Tôi', 'Don''t Follow Me', 'https://phimimg.com/upload/vod/20260507-1/f83f734722fe1ad073ae22cc722e1c59.jpg', 'https://phimimg.com/upload/vod/20260507-1/4c33060d1478fed3dc1aba7c3e5075e3.jpg', '<p>Ám ảnh bởi việc gây sốt với các video về ma và hiện tượng siêu nhiên, Carla, một người khao khát trở thành người có sức ảnh hưởng trên mạng xã hội, chuyển đến sống trong một tòa nhà nổi tiếng bị ma ám. Ở đó, cô bắt đầu giả vờ có ma xuất hiện để thu hút thêm người theo dõi, mà không hề hay biết rằng một thế lực tà ác thực sự đang trú ngụ trong căn hộ của cô và sẽ hành hạ cô cho đến khi không ai, kể cả chính cô, có thể phân biệt được đâu là thật và đâu là giả.</p>', 'Trailer', 1, 'single', 'ongoing', 26, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Karla Rodríguez Coronado","avatar":""},{"name":"Yankel Stevan","avatar":""},{"name":"Julia Maque","avatar":""},{"name":"Cesar Serrano Prado ''Parker''","avatar":""},{"name":"María Ulloa","avatar":""},{"name":"Miranda García","avatar":""},{"name":"Luz María Meza","avatar":""},{"name":"Fernanda Chicurel","avatar":""},{"name":"Victoria Yamasaki","avatar":""},{"name":"Joel Marroquín","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Don''t Follow Me","Lễ Đoạt Hồn","Unfollow","No me sigas"]', 1784690324133);
