INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-le', 'Vợ Lẽ', 'Gundik', 'https://phimimg.com/upload/vod/20260507-1/ace84433293a1d0d5e37fd7cf657b37c.jpg', 'https://phimimg.com/upload/vod/20260507-1/77a55d421c7cd17189d145df7b577549.jpg', '<p>Một cựu binh nhận việc cướp một ngôi nhà, nhưng hóa ra đó lại là nhà của Nyai, một thê thiếp, tức Gundik.</p>', 'Trailer', 1, 'single', 'ongoing', 27, 2025, 'Vietsub', 'FHD', 'Indonesia', 0, '[{"name":"Luna Maya","avatar":""},{"name":"Maxime Bouttier","avatar":""},{"name":"Agus Kuncoro","avatar":""},{"name":"Rukman Rosadi","avatar":""},{"name":"Safira Ratu Sofya","avatar":""},{"name":"Arief Didu","avatar":""},{"name":"Dian Sidik","avatar":""},{"name":"Tio Pakusadewo","avatar":""},{"name":"Vonny Anggraini","avatar":""},{"name":"Ence Bagus","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["ខ្មោចម្ចាស់ស្រី","Siêu Lừa Gặp Siêu Thoát","Gundik"]', 1784690324133);
