INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('13-ngay-va-dem', '13 Ngày Và Đêm', '13 Days, 13 Nights: In The Hell Of Kabul', 'https://phimimg.com/upload/vod/20260507-1/5b022b6bbc41737926e2bbd2c0b5f954.jpg', 'https://phimimg.com/upload/vod/20260507-1/adf8c6cd092894b42ccace48cf13081c.jpg', '<p>Kabul, ngày 15 tháng 8 năm 2021. Quân đội Hoa Kỳ đang chuẩn bị rút khỏi Afghanistan, trong khi Taliban đang tiến về thủ đô để giành quyền lực. Giữa cảnh hỗn loạn, Chỉ huy Mohamed Bida và đội của ông phụ trách an ninh tại Đại sứ quán Pháp, phái bộ phương Tây cuối cùng còn hoạt động. Bị mắc kẹt cùng với 500 người, bị bỏ mặc tự xoay xở, cả đội phải đến được sân bay bằng mọi giá. Một nhiệm vụ nguy hiểm không có gì đảm bảo thành công: trốn thoát khỏi địa ngục Kabul và giải cứu những người còn sót lại của nhân loại.</p>', 'Trailer', 1, 'single', 'ongoing', 25, 2025, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Roschdy Zem","avatar":""},{"name":"Lyna Khoudri","avatar":""},{"name":"Sidse Babett Knudsen","avatar":""},{"name":"Christophe Montenez","avatar":""},{"name":"Sina Parvaneh","avatar":""},{"name":"Yan Tual","avatar":""},{"name":"Fatima Adoum","avatar":""},{"name":"Shoaib Saïd","avatar":""},{"name":"Sayed Hashimi","avatar":""},{"name":"Benjamin Hicquel","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["13 days, 13 nights","Operation: Kabul","13 Tage, 13 Nächte","13 Jours, 13 Nuits"]', 1784690324133);
