INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('13-ngay-va-dem', '13 Ngày Và Đêm', '13 Days, 13 Nights: In The Hell Of Kabul', '13 ngày và đêm 13 days, 13 nights: in the hell of kabul roschdy zem lyna khoudri sidse babett knudsen christophe montenez sina parvaneh yan tual fatima adoum shoaib saïd sayed hashimi benjamin hicquel 13 days, 13 nights operation: kabul 13 tage, 13 nächte 13 jours, 13 nuits', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-sat-nhan-stone-creek', 'Kẻ Sát Nhân Stone Creek', 'Stone Creek Killer', 'https://phimimg.com/upload/vod/20260505-1/b3c718791cde5aafb4cc80a5aa257c72.jpg', 'https://phimimg.com/upload/vod/20260505-1/4cc7fb6e33e220b30b915ce2bd95a99f.jpg', '<p>Lấy bối cảnh một thị trấn nhỏ yên bình, phim theo chân vị cảnh sát trưởng đang truy lùng một kẻ giết người hàng loạt nguy hiểm, trong khi phải nhờ đến những thị kiến bí ẩn của một nhà ngoại cảm để lần theo dấu vết hung thủ, đồng thời anh cũng phải chiến đấu để chứng minh sự vô tội của chính mình trước những nghi ngờ và âm mưu chồng chéo</p>', 'Trailer', 1, 'single', 'ongoing', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Clayne Crawford","avatar":""},{"name":"Lyndon Smith","avatar":""},{"name":"Andrew J. West","avatar":""},{"name":"Adam Hicks","avatar":""},{"name":"Britney Young","avatar":""},{"name":"Vincent Washington","avatar":""},{"name":"Lily Rains","avatar":""},{"name":"Wilmer Calderon","avatar":""},{"name":"David Sullivan","avatar":""},{"name":"AprilAnn Dais","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Stone Creek Killer"]', 1784690324133);
