INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phep-mau-cua-nguoi-cha', 'Phép Màu Của Người Cha', 'A Father''s Miracle', 'https://phimimg.com/upload/vod/20260505-1/ed4db1a2966a02bda0623ecac7d1bd8e.jpg', 'https://phimimg.com/upload/vod/20260505-1/1b56fcc2652870f169ba6b5534aecadf.jpg', '<p>Sau khi bị vu oan về một tội ác khủng khiếp, Hector, một người đàn ông bị khuyết tật về thần kinh, bị giam giữ trong một nhà tù bí mật. Lòng tốt của anh đã chinh phục các tù nhân, những người đang lên kế hoạch chứng minh sự vô tội của mình.</p>', 'Trailer', 1, 'single', 'ongoing', 22, 2025, 'Vietsub', 'FHD', 'Mexico', 0, '[{"name":"Omar Chaparro","avatar":""},{"name":"Jorge A. Jimenez","avatar":""},{"name":"Mariana Calderón","avatar":""},{"name":"Natalia Reyes","avatar":""},{"name":"Sofía Álvarez","avatar":""},{"name":"Gustavo Sánchez Parra","avatar":""},{"name":"Felipe Camargo Vargas","avatar":""},{"name":"Marco Treviño","avatar":""},{"name":"Laura Alonso Escobar","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Cell of Miracles","A Father''s Miracle","La celda de los milagros"]', 1784690324133);
