INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phep-mau-cua-nguoi-cha', 'Phép Màu Của Người Cha', 'A Father''s Miracle', 'phép màu của người cha a father''s miracle omar chaparro jorge a. jimenez mariana calderón natalia reyes sofía álvarez gustavo sánchez parra felipe camargo vargas marco treviño laura alonso escobar the cell of miracles a father''s miracle la celda de los milagros', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cha-me-chi-va-em', 'Cha Mẹ Chị Và Em', 'Father Mother Sister Brother', 'https://phimimg.com/upload/vod/20260505-1/8b9643dcb95dcae4476af9486a48fe5c.jpg', 'https://phimimg.com/upload/vod/20260505-1/1a16842d69f079aa207c815fe96d49f6.jpg', '<p>Sau nhiều năm không gặp, hai anh em vốn chẳng còn nói chuyện với nhau bất ngờ bị “triệu hồi” về ngôi nhà cũ khi cha mẹ họ – những người lạnh lùng, xa cách – quyết định tổ chức một buổi kỷ niệm gia đình. Không khí gượng gạo nhanh chóng biến thành chuỗi tình huống dở khóc dở cười khi những ký ức bị chôn vùi, những lời chưa kịp nói và cả những vết thương cũ lần lượt trồi lên.Giữa căn nhà đầy tiếng cười pha lẫn im lặng khó xử, từng người phải đối mặt với chính bản thân và với cách họ đã lớn lên trong một gia đình tưởng chừng chẳng ai hiểu ai. Jim Jarmusch mang đến sự kết hợp lạ giữa hài hước châm biếm và nỗi buồn tinh tế, với dàn diễn viên kỳ cựu như Tom Waits, Adam Driver, Mayim Bialik, Charlotte Rampling và Cate Blanchett – mỗi người là một mảnh ghép vừa lạc lõng vừa thân thuộc trong bức tranh gia đình đầy méo mó nhưng rất thật.</p>', 'Trailer', 1, 'single', 'ongoing', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Waits","avatar":""},{"name":"Adam Driver","avatar":""},{"name":"Mayim Bialik","avatar":""},{"name":"Charlotte Rampling","avatar":""},{"name":"Cate Blanchett","avatar":""},{"name":"Vicky Krieps","avatar":""},{"name":"Sarah Greene","avatar":""},{"name":"Indya Moore","avatar":""},{"name":"Luka Sabbat","avatar":""},{"name":"Françoise Lebrun","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["پدر مادر خواهر برادر","파더 마더 시스터 브라더","Бацька маці сястра брат","Отец мать сестра брат","Батько, мати, сестра, брат","Baba Anne Kız Kardeş Erkek Kardeş","אבא אמא אח אחות","Баща майка сестра брат","父母姐弟","Tēvs māte māsa brālis","Otec Matka Sestra Bratr","Tėvas Motina Sesuo Brolis","Pai Mãe Irmã Irmão","Padre madre hermana hermano","Father Mother Sister Brother"]', 1784690324133);
