INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-na-da-nguoi', 'Mặt Nạ Da Người', 'Danyang Wingit Jumat Kliwon', 'https://phimimg.com/upload/vod/20260505-1/000e4d4c060a456759402972f308e5e4.jpg', 'https://phimimg.com/upload/vod/20260505-1/12bee643289f16a85ef7ad25c260e00f.jpg', '<p>Ki Mangun Suroto là một nghệ nhân múa rối Wayang nổi tiếng và đầy tham vọng, ông khao khát nắm giữ tà thuật cổ xưa để đạt được sự giàu có và bất tử. Năm 2021, ông mời Citra làm nghệ sĩ hát Sinden trong một buổi lễ, nhưng thực chất là muốn cô trở thành vật tế cuối cùng. Trong khi cố gắng kiếm tiền chữa bệnh cho em gái, Citra dần bị cuốn vào những nghi lễ kinh hoàng và phải tìm cách thoát khỏi số phận đáng sợ của mình.</p>', 'Trailer', 1, 'single', 'ongoing', 26, 2025, 'Vietsub', 'FHD', 'Indonesia', 0, '[{"name":"Celine Evangelista","avatar":""},{"name":"Fajar Nugra","avatar":""},{"name":"Djenar Maesa Ayu","avatar":""},{"name":"Whani Darmawan","avatar":""},{"name":"Nathalie Holscher","avatar":""},{"name":"Aisyah Kanza","avatar":""},{"name":"Norma Cinta","avatar":""},{"name":"Dimas Tedjo Blangkon","avatar":""},{"name":"Keona Cinta","avatar":""},{"name":"Putri Maya Rumanti","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Danyang Wingit Jumat Kliwon"]', 1784690324133);
