INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bat-khuat-2025', 'Bất khuất', 'Untamable / Indomptables', 'https://phimimg.com/upload/vod/20260504-1/724117e560df97effcbdfdca7b9e4bb9.jpg', 'https://phimimg.com/upload/vod/20260504-1/2f3f38c96fb5ffb07246be88c4a648fe.jpg', '<p>Tại Yaounde, Cảnh sát trưởng Billong đang điều tra vụ sát hại một sĩ quan cảnh sát. Trên đường phố và trong nước, ông phải vật lộn để duy trì trật tự. Là một người đàn ông trọng nguyên tắc và truyền thống, ông đang đến giới hạn chịu đựng.</p>', 'Full', 1, 'single', 'completed', 19, 2025, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Thomas Ngijol","avatar":""},{"name":"Danilo Melande","avatar":""},{"name":"Bienvenu Roland Mvoe","avatar":""},{"name":"Thérèse Ngono","avatar":""},{"name":"Ariane Ntomba","avatar":""},{"name":"Junior Bessala","avatar":""},{"name":"Dimitri Amougou","avatar":""},{"name":"Christol le Prince Djomo","avatar":""},{"name":"Terrence Samba Amougou","avatar":""},{"name":"Olivier Fomedjo","avatar":""},{"name":"Gaston Tsinapi","avatar":""},{"name":"Janvier Paul Nwind","avatar":""},{"name":"Alain Zé","avatar":""},{"name":"Moussa Sindjah","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Indomptables"]', 1784690324133);
