INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-cua-tinh-yeu', 'Thế giới của tình yêu', 'The World of Love', 'https://phimimg.com/upload/vod/20260504-1/4f996391b61473cca358ca23813833de.jpg', 'https://phimimg.com/upload/vod/20260504-1/eaf5b3393723e11e097174af2afb36ef.jpg', '<p>Jooin, một nữ sinh 17 tuổi đang bối rối vì tình yêu, đã gây ra hỗn loạn bằng vài lời nói trong lúc tức giận. Những lá thư nặc danh chất vấn hành động của cô bắt đầu xuất hiện, làm đảo lộn cuộc sống yên bình của cô.</p>', 'Full', 1, 'single', 'completed', 18, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Seo Su-bin","avatar":""},{"name":"Jang Hye-jin","avatar":""},{"name":"Kim Jeong-sik","avatar":""},{"name":"Kang Chae-yun","avatar":""},{"name":"Lee Jae-hee","avatar":""},{"name":"Park Ji-yun","avatar":""},{"name":"Kim Ye-chang","avatar":""},{"name":"Go Min-si","avatar":""},{"name":"Lee Sang-hee","avatar":""},{"name":"Lee Dae-yeon","avatar":""},{"name":"Kim Suk-hoon","avatar":""},{"name":"Baek Hyun-joo","avatar":""},{"name":"Byun Joong-hee","avatar":""},{"name":"Moon Hye-in","avatar":""},{"name":"Kim Min-ji","avatar":""},{"name":"O Jung-won","avatar":""},{"name":"Kim Yun-jeong","avatar":""},{"name":"Choi Ga-in","avatar":""},{"name":"Son Seung-b","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["세계의 주인"]', 1784690324133);
