INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nua-kia-cua-toi-va-ban', 'Nửa kia của tôi và bạn', 'The Other Half of Me and You', 'https://phimimg.com/upload/vod/20260504-1/da3500737757193f10aa6a74a8eebec2.jpg', 'https://phimimg.com/upload/vod/20260504-1/5c304c65899761c0adb5c6ca97866d27.jpg', '<p>Một tai nạn trong phòng thí nghiệm ngầm đã gây ra sự biến dạng về thời gian và không gian, từ đó đưa sóng não của phi công Gao Zirui đến một thế giới song song, nơi mọi thứ đều đi ngược lại logic mà anh từng biết. Trong xã hội này, phụ nữ là người đứng đầu và đàn ông phải sống theo những giá trị nhất định. Họ phải dịu dàng, lịch sự và đức hạnh. Họ phải đặt hôn nhân và chăm sóc con cái lên hàng đầu. Vì vậy, Gao Zirui phát hiện ra thư ký Xiao Xiao, người từng thầm yêu anh, giờ đã trở thành một nhà khoa học nữ đầy triển vọng và quyền lực tên là Jacky. Gao Zirui đến làm việc cho Jacky và cuộc chiến giữa hai giới bắt đầu. Để trở về nhà, anh phải bắt đầu cuộc hành trình theo đuổi tình yêu.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["另一半的我和你"]', 1784690324133);
