INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-nguoi-nhu-toi', 'Một người như tôi', 'Someone Like Me', 'https://phimimg.com/upload/vod/20260504-1/9e59f97ca419f925edb638bbf022c401.jpg', 'https://phimimg.com/upload/vod/20260504-1/eaf92e9cf889399856ee84ebf27948bb.jpg', '<p>Một phụ nữ trẻ mắc chứng bại não đã tìm thấy sự độc lập và chấp nhận bản thân mới mẻ thông qua những trải nghiệm với một tổ chức chuyên giúp đỡ người khuyết tật khám phá đời sống tình dục của họ.</p>', 'Full', 1, 'single', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Fish Liew Chi-Yu","avatar":""},{"name":"Carlos Chan Ka-Lok","avatar":""},{"name":"Alice Lau Nga-Lai","avatar":""},{"name":"Kate Yeung Kei","avatar":""},{"name":"Polly Lau","avatar":""},{"name":"Lam Tze-Yuen","avatar":""},{"name":"Lam Hon-Wing","avatar":""},{"name":"Heyo","avatar":""},{"name":"Margaret Lain Enriquez","avatar":""},{"name":"Fonnie Ng","avatar":""},{"name":"John Ho","avatar":""},{"name":"Karry Tsui","avatar":""},{"name":"Josephine Lam Kei-Yan","avatar":""},{"name":"Ng Yi-Cho","avatar":""},{"name":"Justin Chu","avatar":""},{"name":"Lai Chai-Ming","avatar":""},{"name":"Water Hung","avatar":""},{"name":"Fung Si","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["像我這樣的愛情"]', 1784690324133);
