INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('agon', 'Agon', 'Agon', 'https://phimimg.com/upload/vod/20260504-1/9a1d45e4c493ccabd4e97314bb8031c6.jpg', 'https://phimimg.com/upload/vod/20260504-1/58d64463bc067bec19357eb3d22915bb.jpg', '<p>Ba vận động viên ưu tú đang luyện tập cho Thế vận hội mùa hè Ludoj 2024. Đối mặt với sự chú ý của báo chí, chấn thương và sự kiệt sức, họ luyện tập các bộ môn bắn súng, đấu kiếm và judo. Các nữ vận động viên làm việc với huấn luyện viên để tối ưu hóa phong độ trước khi thi đấu dưới áp lực cao tại Thế vận hội.</p>', 'Full', 1, 'single', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Yle Vianello","avatar":""},{"name":"Alice Bellandi","avatar":""},{"name":"Sofija Zobina","avatar":""},{"name":"Michela Cescon","avatar":""},{"name":"Francesco Acquaroli","avatar":""},{"name":"Chiara Caselli","avatar":""},{"name":"Louis Hofmann","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Agon"]', 1784690324133);
