INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('agon', 'Agon', 'Agon', 'agon agon yle vianello alice bellandi sofija zobina michela cescon francesco acquaroli chiara caselli louis hofmann agon', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('boc-dan', 'Bộc Đạn', 'Suzuki=Bakudan', 'https://phimimg.com/upload/vod/20260504-1/10245db2f3748fc1f01497d3c8468740.jpg', 'https://phimimg.com/upload/vod/20260504-1/847a94ec8da64c9613d07687f551d432.jpg', '<p>Một người đàn ông thất nghiệp tên là Suzuki bị cảnh sát bắt giữ sau khi đập phá một máy bán rượu tự động. Khi anh ta dự đoán chính xác hai vụ nổ bom và khẳng định vẫn còn nhiều quả bom khác, cảnh sát bắt đầu điều tra anh ta như một kẻ khủng bố. Tuy nhiên, Suzuki ban đầu tuyên bố mình biết về những quả bom thông qua khả năng ngoại cảm, sau đó lại khẳng định mình đã bị thôi miên để quên đi sự việc. Anh ta đưa ra những gợi ý về các quả bom bằng những câu đố trong khi chọc tức những người thẩm vấn, đặc biệt là thám tử kỳ cựu Kiyomiya và cấp dưới của ông là Ruike. Mọi chuyện dường như có liên quan đến một cảnh sát bị thất sủng tên là Hasebe, người đã tự sát sau một vụ bê bối nhiều năm trước. Nhưng liệu Suzuki thực sự là thủ phạm đứng sau những vụ nổ bom hay không?</p>', 'Full', 1, 'single', 'completed', 13, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuki Yamada","avatar":""},{"name":"Sairi Ito","avatar":""},{"name":"Shota Sometani","avatar":""},{"name":"Atsuro Watabe","avatar":""},{"name":"Jiro Sato","avatar":""},{"name":"Kanichiro Sato","avatar":""},{"name":"Ryota Bando","avatar":""},{"name":"Sennosuke Kataoka","avatar":""},{"name":"Seina Nakata","avatar":""},{"name":"Masaya Katō","avatar":""},{"name":"Bokuzo Masana","avatar":""},{"name":"Yui Natsukawa","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Suzuki=Bakudan","爆弾","爆彈","Bomb"]', 1784690324133);
