INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-giet-nguoi-2025', 'Kẻ Giết Người', 'He Kills at Night', 'https://phimimg.com/upload/vod/20260504-1/3c672acfa498a166c652307d83d9ee2b.jpg', 'https://phimimg.com/upload/vod/20260504-1/002d07255611d055db43a3d1006ef4c5.jpg', '<p>Đêm Giáng Sinh, Fern đang lái xe về nhà nghỉ lễ. Nhưng khi dừng lại nghỉ ngơi, cô bị một người đàn ông bí ẩn, người đầy máu, sát hại. Ngay sau đó, kẻ giết người tình cờ gặp một du khách khác và một cuộc rượt đuổi mèo vờn chuột bắt đầu. Liệu mọi chuyện có đúng như vẻ bề ngoài?</p>', 'Full', 1, 'single', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Levi Heaton","avatar":""},{"name":"Richard Galloway","avatar":""},{"name":"Isabella Percival","avatar":""},{"name":"Damian McNeilly","avatar":""},{"name":"Eleanor May Blackburn","avatar":""},{"name":"Madeline Percival","avatar":""},{"name":"Detroya Angelé","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["He Kills at Night"]', 1784690324133);
