INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-hai-chu', 'Nhà Hai Chủ', 'Whispering Spirit', 'https://phimimg.com/upload/vod/20260505-1/d61a4b0301e8760c64092cf01798aee4.jpg', 'https://phimimg.com/upload/vod/20260505-1/4c29c1c9b3b5d893b35719977e5d22bc.jpg', '<p>Một gia đình nhỏ vì không đủ điều kiện đã phải mua một căn nhà mà người dân xung quanh đồn đoán rằng có nhiều điều kỳ lạ tâm linh liệu gia đình sẽ đối mặt với ngôi nhà nhiều chủ sẽ như thế nào?</p>', 'Full', 1, 'single', 'completed', 37, 2025, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Kim Phương","avatar":""},{"name":"Trâm Anh","avatar":""},{"name":"Kim Hải","avatar":""},{"name":"Tạ Lâm","avatar":""},{"name":"Thụy Mười","avatar":""},{"name":"Mộc Trà","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Nhà Hai Chủ"]', 1784690324133);
