INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ly-hon-tuoi-60', 'Ly Hôn Tuổi 60', 'Divorce At 60', 'https://phimimg.com/upload/vod/20260504-1/71b23db83f4e2b203b22b6347fd37195.jpg', 'https://phimimg.com/upload/vod/20260504-1/54481c2237c66b9844eb382930f670ec.jpg', '<p>Ở tuổi 60, khi mái đầu đã bạc, bà Sáu chọn cách rời bỏ cuộc hôn nhân hàng chục năm để tìm lại chính mình. Quyết định &quot;gây bão&quot; này vô tình bóc trần những rạn nứt giấu kín, buộc mỗi thành viên phải học lại cách yêu thương trước khi quá muộn. Hành trình cuối đời không phải là kết thúc, mà là sự bắt đầu của một tình thân đích thực.</p>', 'Hoàn Tất (120/120)', 120, 'series', 'completed', 20, 2025, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Lan Hương","avatar":""},{"name":"Việt Anh","avatar":""},{"name":"Quang Thảo","avatar":""},{"name":"Kim Đào","avatar":""},{"name":"Hoài Trang","avatar":""},{"name":"Linh Tý","avatar":""},{"name":"Bích Trâm","avatar":""},{"name":"Nguyệt Ánh","avatar":""},{"name":"NSƯT Mỹ Duyên","avatar":""},{"name":"NSND Kim Xuân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324133);
