INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-duong-dung-dan', 'Con Đường Đúng Đắn', 'Buen Camino', 'https://phimimg.com/upload/vod/20260502-1/e0cf1ecc091cbdde2bbb6fec8211329e.jpg', 'https://phimimg.com/upload/vod/20260502-1/6674fc8c7b19ce69d0115aec4f4d1d46.jpg', '<p>Cuộc sống của Checco rất thoải mái và xa hoa, điều này cũng dễ hiểu vì anh là con trai duy nhất của Eugenio Zalone, một nhà sản xuất ghế sofa giàu có. Sống thoải mái bên hồ bơi trong biệt thự sang trọng của mình, với một số lượng người Philippines không xác định phục vụ, một cô bạn gái là người mẫu Mexico trẻ tuổi, và đi nghỉ mát trên du thuyền cùng những người bạn cùng chung sở thích không muốn làm việc; dường như đó là một cuộc sống đáng ghen tị, vì anh không thiếu thứ gì, hoàn toàn không thiếu thứ gì. Thực ra, không. Có một điều còn thiếu. Đó là cô con gái chưa đủ tuổi của anh, Cristal, được đặt tên theo loại rượu vang sủi nổi tiếng của Pháp, người đột nhiên biến mất không dấu vết. Được vợ cũ, Linda, triệu tập khẩn cấp đến Rome, anh thấy mình phải đối mặt với trách nhiệm làm cha lần đầu tiên, cố gắng tìm kiếm cô gái – một nhiệm vụ rất phức tạp, vì anh hoàn toàn không biết gì về Cristal và cuộc sống của cô.</p>', 'Full', 1, 'single', 'completed', 22, 2025, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Checco Zalone","avatar":""},{"name":"Beatriz Arjona","avatar":""},{"name":"Letizia Arnò","avatar":""},{"name":"Martina Colombari","avatar":""},{"name":"Hossein Taheri","avatar":""},{"name":"Alfonso Santagata","avatar":""},{"name":"Mariana Rodríguez","avatar":""},{"name":"Cecilia Gragnani","avatar":""},{"name":"Beatrice Abbro","avatar":""},{"name":"Maurizio Bousso","avatar":""},{"name":"Andrea Cosentino","avatar":""},{"name":"Claudia Ferri","avatar":""},{"name":"Davide Cornacchia","avatar":""},{"name":"Isnaba Na Montche","avatar":""},{"name":"Alessio Genchi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Good Road","Счастливого пути","Buen Camino"]', 1784690324133);
