INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuy-long-ngam', 'Thủy Long Ngâm', 'Whispers Of Fate', 'https://phimimg.com/upload/vod/20251024-1/260919d2479aaaf19ce6ed9e70810683.jpg', 'https://phimimg.com/upload/vod/20251024-1/3507894ec4571721a2ca503cf1b78623.jpg', '<p>Thủy Long Ngâm xoay quanh Đường Lệ Từ, một cao thủ nổi tiếng thông minh tuyệt đỉnh nhưng đã sống ẩn dật nhiều năm. Một vụ thảm sát đã buộc chàng phải tái xuất giang hồ vì hung thủ chính là Liễu Nhãn, vị sư huynh mà chàng đã tìm kiếm suốt nhiều năm. Lấy giang hồ làm bàn cờ, dùng các thế lực lớn làm quân cờ, Đường Lệ Từ đối đầu với các thế lực đen tối để truy tìm sự thật và hóa giải những hiểu lầm trong quá khứ.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 25, 2025, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"La Vân Hi","avatar":""},{"name":"Tiêu Thuận Diêu","avatar":""},{"name":"Ngạo Tử Dật","avatar":""},{"name":"Phương Dật Luân","avatar":""},{"name":"Bao Thượng Ân","avatar":""},{"name":"Trần Diêu","avatar":""},{"name":"Lâm Thuận","avatar":""},{"name":"Từ Chính Khê","avatar":""},{"name":"Vương Dĩ Luân","avatar":""},{"name":"Tạ Bân Bân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Qian Jie Mei","千劫眉","水龍吟","Shui Long Yin","Les murmures du destin","수배령","อสิธารา ชะตามังกร","The Dragon Chant","Whispers of Fate","水龙吟"]', 