INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoc-minh-tra-cot', 'Ngọc Minh Trà Cốt', 'Glory', 'https://phimimg.com/upload/vod/20251229-1/747bc0d00205e545bee24238fe61c041.jpg', 'https://phimimg.com/upload/vod/20251229-1/eee9d32e9124e689f36c94b0403b6540.jpg', '<p>Trạng nguyên trẻ Lục Giang Lai từ quan viên triển vọng trở thành kẻ bị truy nã vì dính líu vụ án giết vợ bí ẩn. Được Vinh Thiện Bảo - con gái Trà Vương cứu mạng, nhưng vì mất trí nhớ nên bị cô lợi dụng làm chăn ngựa để trả thù gia tộc.

Khi Vinh gia tổ chức kén rể, Lục Giang Lai bất đắc dĩ trở thành quân cờ của Thiện Bảo. Giữa những màn đấu trí, cặp đôi từ thù địch dần sinh tình cảm, cùng nhau phá giải án cũ, tìm hung thủ thật và mở ra kỷ nguyên mới cho trà đạo.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 24, 2025, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Hầu Minh Hạo","avatar":""},{"name":"Cổ Lực Na Trát","avatar":""},{"name":"Trần Nhược Hiên","avatar":""},{"name":"Triệu Dịch Khâm","avatar":""},{"name":"Mã Văn Viễn","avatar":""},{"name":"Lý Phi","avatar":""},{"name":"Thư Đồng","avatar":""},{"name":"Trương Nam","avatar":""},{"name":"Triệu Gia Mẫn","avatar":""},{"name":"Trương Uyển Oánh","avatar":""},{"name":"Triệu Chiêu Nghi","avatar":""},{"name":"Trương Huệ Văn","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["茗门世家之玉茗茶骨","茗门世家","Yu Ming Cha Gu","Glory","玉茗茶骨"]', 1784690324133);
