INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoc-vien-sieu-anh-hung-mua-8', 'Học Viện Siêu Anh Hùng (Mùa 8)', 'My Hero Academia (Season 8)', 'học viện siêu anh hùng (mùa 8) my hero academia (season 8) daiki yamashita मेरा नायक एकेडेमिया माई हीरो एकेडेमिया ヒロアカ boku no hero academia bnha 僕のヒーローアカデミア memories 僕のヒーローアカデミア no. 170+1 more boku no hero academia: more boku no hero academia no. 170+1: more boku no hero academia: i am a hero too 나의 히어로 아카데미아 أكاديمية بطلي 我的英雄學院 final season моя геройська академія mha my hero academia: more my hero academia: i am a hero too anh hùng học viện 僕のヒーローアカデミア', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-hinh-thu', 'Dị Hình Thú', 'Special Monster', 'https://phimimg.com/upload/vod/20260502-1/0496c1a5a6d27ea727950ceccfd79e9b.jpg', 'https://phimimg.com/upload/vod/20260502-1/22dadac14c87721504fedc69151e3f3c.jpg', '<p>Hơn 700 năm sau từ thời Nam Tống đến nay, Cao Thành cùng đồng đội ra khơi tìm kiếm con tàu buôn &quot;Cuồng Phong&quot;, con tàu chở vô số báu vật đã biến mất một cách bí ẩn. Tuy nhiên, họ vô tình đặt chân lên một hòn đảo kỳ bí, nơi có một bộ lạc nguyên thủy và bị một bầy sinh vật dị hình truy sát, nuốt chửng. Những quả trứng khổng lồ trên đảo nở ra ấu trùng quái vật, đe dọa mạng sống của cả nhóm. Sau nhiều lần thoát chết trong gang tấc, họ tìm thấy kho báu trên con tàu cổ nhưng lại một lần nữa bị bầy quái vật bao vây, không còn đường thoát.</p>', 'Full', 1, 'single', 'completed', 10, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Cốc Phong","avatar":""},{"name":"Mã Giai Vĩ","avatar":""},{"name":"Quách Mỹ Lâm Tử","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["异形兽"]', 1784690324133);
