INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-cua-anh-ngay-cua-em', 'Năm Của Anh, Ngày Của Em', 'Measure in Love', 'https://phimimg.com/upload/vod/20260501-1/a016d0b57519b597066ee5ead9f3d8d4.jpg', 'https://phimimg.com/upload/vod/20260501-1/4cd0e99bf839f92ebe1861a56e81ae96.jpg', '<p>Khi thế giới bị chia cắt thành hai chiều không gian song song, tình yêu giữa Hứa Quang Hán và Viên Lễ Lâm cũng bị cuốn trôi theo những nhịp sống khác biệt.
 Dẫu ở hai thế giới cách xa, họ vẫn níu giữ sợi dây mong manh của định mệnh, khát khao tìm đến điểm giao nhau để viết tiếp câu chuyện tình còn dang dở.
 Một bản tình ca lặng lẽ, day dứt — nơi Hứa Quang Hán mang đến những nốt trầm da diết, gợi lên câu hỏi: Liệu tình yêu có đủ sức vượt qua giới hạn của không gian và thời gian?</p>', 'Full', 1, 'single', 'completed', 25, 2025, 'Vietsub', 'FHD', 'Hồng Kông', 1, '[{"name":"Greg Hsu","avatar":""},{"name":"Angela  Yuen Lai-Lam","avatar":""},{"name":"Jack Tan","avatar":""},{"name":"Stephen Tung Wai","avatar":""},{"name":"Chan Fai-Hung","avatar":""},{"name":"Han Pui-yiu","avatar":""},{"name":"Thor Lok","avatar":""},{"name":"Natalie Hsu","avatar":""},{"name":"Yoyo Tse Wing-yan","avatar":""},{"name":"Ho Sai-Man","avatar":""},{"name":"Lee Sheung-Ching","avatar":""},{"name":"Wong Yau-Nam","avatar":""},{"name":"Jayden Wong Tsz-Hin","avatar":""},{"name":"Wesley Wong","avatar":""},{"name":"Hong Tang","avatar":""},{"name":"Marquis Oakes","avatar":""},{"name":"Una Yuen","avatar":""},{"name":"Sherring Ng","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["他年．她日","他年她日"]', 1784690324133);
