INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nam-cua-anh-ngay-cua-em', 'Năm Của Anh, Ngày Của Em', 'Measure in Love', 'năm của anh, ngày của em measure in love greg hsu angela  yuen lai-lam jack tan stephen tung wai chan fai-hung han pui-yiu thor lok natalie hsu yoyo tse wing-yan ho sai-man lee sheung-ching wong yau-nam jayden wong tsz-hin wesley wong hong tang marquis oakes una yuen sherring ng 他年．她日 他年她日', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-trong-thuong-nho', 'Hoa Trong Thương Nhớ', 'Petals and Memories', 'https://phimimg.com/upload/vod/20260501-1/382e911dcbf6320532707515a2cc712d.jpg', 'https://phimimg.com/upload/vod/20260501-1/cab217ca664bec5db56392ac69419a2b.jpg', '<p>Lấy bối cảnh tại Osaka, câu chuyện theo chân hai anh em Toshiki và Fumiko, những đứa trẻ mồ côi cha mẹ từ khi còn nhỏ. Là anh cả, Toshiki đã hứa với người cha quá cố rằng anh sẽ luôn bảo vệ Fumiko. Gánh trên vai cả vai trò người anh lẫn người cha, Toshiki bỏ học trung học để làm việc tại một nhà máy địa phương nuôi cả hai anh em.</p>', 'Full', 1, 'single', 'completed', 21, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 1, '[{"name":"Ryohei Suzuki","avatar":""},{"name":"Kasumi Arimura","avatar":""},{"name":"Ouji Suzuka","avatar":""},{"name":"First Summer Uika","avatar":""},{"name":"Rokkaku Seiji","avatar":""},{"name":"Midoriko Kimura","avatar":""},{"name":"Yoshi Sakō","avatar":""},{"name":"Tamae Ando","avatar":""},{"name":"Oru Kyojin","avatar":""},{"name":"Shunya Itabashi","avatar":""},{"name":"Kotona Minami","avatar":""},{"name":"Azusa Babazono","avatar":""},{"name":"Ryunosuke Shimamura","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Hana Manma","花便當的記憶","花まんま"]', 1784690324133);
