INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoa-trong-thuong-nho', 'Hoa Trong Thương Nhớ', 'Petals and Memories', 'hoa trong thương nhớ petals and memories ryohei suzuki kasumi arimura ouji suzuka first summer uika rokkaku seiji midoriko kimura yoshi sakō tamae ando oru kyojin shunya itabashi kotona minami azusa babazono ryunosuke shimamura hana manma 花便當的記憶 花まんま', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-an-thit-nguoi-phan-2', 'Làng Ăn Thịt Người (Phần 2)', 'Gannibal (Season 2)', 'https://phimimg.com/upload/vod/20250320-1/b016ae67838547cde4c06d32fb63984a.jpg', 'https://phimimg.com/upload/vod/20250320-1/cf605d3e8725f167fea9c7b9399b0dfc.jpg', '<p>Daigo Agawa và gia đình đóng quân tại một ngôi làng miền núi cách xa thành phố. Tuy nhiên, có một tin đồn ở ngôi làng xinh đẹp rằng mọi người sẽ bị ăn thịt trong ngôi làng này... Daigo tìm kiếm sự thật với niềm tin là một sĩ quan cảnh sát, nhưng chẳng bao lâu sau, cuộc sống hàng ngày bình lặng của ngôi làng bắt đầu lộ ra một bộ mặt &quot;đáng sợ&quot;. Những sự kiện bí ẩn nối tiếp nhau, những người dân làng thân thiện nhưng hơi kỳ quái... Daigo trở nên nghi ngờ mọi thứ và bị đẩy đến bờ vực của sự điên loạn. Tôi hay họ xa lạ?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuya Yagira","avatar":""},{"name":"Show Kasamatsu","avatar":""},{"name":"Riho Yoshioka","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Канибал","狩猎","Ганнибал","噬亡村","ガンニバル"]', 1784690324133);
