INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lang-an-thit-nguoi-phan-2', 'Làng Ăn Thịt Người (Phần 2)', 'Gannibal (Season 2)', 'làng ăn thịt người (phần 2) gannibal (season 2) yuya yagira show kasamatsu riho yoshioka канибал 狩猎 ганнибал 噬亡村 ガンニバル', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-den-mat', 'Mắt đền mắt', 'Eye for an Eye', 'https://phimimg.com/upload/vod/20260501-1/4a30952d774938f840087c678371debb.jpg', 'https://phimimg.com/upload/vod/20260501-1/de04bec5a696240bcc809d7fb1b1e659.jpg', '<p>Anna, đau buồn trước cái chết đột ngột của cha mẹ, chuyển từ New York đến một thị trấn nhỏ ở Florida để sống với người bà mà cô chưa từng gặp. Cô đơn, dễ bị tổn thương và cần bạn bè, cô tìm thấy chút an ủi ngắn ngủi trong vòng bạn bè của hai thiếu niên địa phương. Nhưng khi cô vô tình tiếp tay cho hành vi bạo lực không thể tha thứ của họ, cô bị mắc kẹt bởi Ông Sandman – linh hồn méo mó của một đứa trẻ bị dày vò, kẻ ám ảnh giấc mơ của những kẻ bắt nạt trước khi ăn thịt nhãn cầu của chúng khi chúng tỉnh dậy – Anna phải sửa chữa lỗi lầm của mình trước khi trở thành nạn nhân của lời nguyền khủng khiếp này.</p>', 'Full', 1, 'single', 'completed', 19, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Whitney Peak","avatar":""},{"name":"Golda Rosheuvel","avatar":""},{"name":"Finn Bennett","avatar":""},{"name":"Laken Giles","avatar":""},{"name":"S. Epatha Merkerson","avatar":""},{"name":"Carson Minniear","avatar":""},{"name":"Wynn Reichert","avatar":""},{"name":"Ben Bladon","avatar":""},{"name":"Oliver J Green","avatar":""},{"name":"Zariah Boyles","avatar":""},{"name":"Jessica A''Zora","avatar":""},{"name":"Michika McClinton","avatar":""},{"name":"Natalie Cline","avatar":""},{"name":"Elisa Victoria","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Somewhere in Dreamland","Night Terror","Olho por Olho","Eye for an Eye"]', 1784690324133);
