INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hau-due-ke-ke-thua', 'Hậu Duệ (Kẻ Kế Thừa)', 'Descendent', 'https://phimimg.com/upload/vod/20260428-1/a60ae5c25bf7b822de70519e509fdb3c.jpg', 'https://phimimg.com/upload/vod/20260428-1/ee61a10065e1b87d17f9e79f5c2a1ff2.jpg', '<p>Sau một chấn thương sọ não nghiêm trọng gây ra những ảo giác kinh hoàng về người ngoài hành tinh và một tài năng vẽ tranh mới bộc phát, một người sắp làm cha bắt đầu nghi ngờ thực tại của chính mình. Anh trở nên ám ảnh với việc phải bảo vệ gia đình khỏi một mối đe dọa vô hình.</p>', 'Full', 1, 'single', 'completed', 14, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ross Marquand","avatar":""},{"name":"Sarah Bolger","avatar":""},{"name":"Susan Wilder","avatar":""},{"name":"Charlene Amoia","avatar":""},{"name":"Dan O''Brien","avatar":""},{"name":"Brandon Scott","avatar":""},{"name":"Alexandra Barreto","avatar":""},{"name":"Aisha Kabia","avatar":""},{"name":"Peter Cilella","avatar":""},{"name":"Clare Cooney","avatar":""},{"name":"Emily Pendergast","avatar":""},{"name":"Martin Garcia","avatar":""},{"name":"Parvesh Cheena","avatar":""},{"name":"Andre Hyland","avatar":""},{"name":"Ramiz Monsef","avatar":""},{"name":"Alex Ruiz","avatar":""},{"name":"Madelynn Joy S","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Josiah Road","Descendent"]', 1784690324133);
