INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ha-dong-mi-lan-quai-dam', 'Hà Đồng: Mi Lan Quái Đàm', 'Underwater Ghost', 'https://phimimg.com/upload/vod/20260402-1/08ce89a64290aeb2a103b7beb0276990.jpg', 'https://phimimg.com/upload/vod/20260402-1/39b097c3f39c300babc08a219be70119.jpg', '<p>Chuyên gia sinh hóa Minh Hàn hỗ trợ cảnh sát điều tra một loạt vụ án giết người liên quan đến sinh vật thủy sinh bí ẩn, và phát hiện hung thủ lại chính là cha ruột Minh Trí, người đã mất tích nhiều năm. Hóa ra năm xưa, cộng sự của ông là giáo sư Walker đã tiến hành thí nghiệm trái phép trên cơ thể người, khiến Minh Trí bị nhiễm biến dị, hóa thành thủy quái Kappa. Ông rồi bị giam cầm để phục vụ thí nghiệm suốt thời gian dài. Cuối cùng, hai cha con nhận lại nhau. Họ cùng nhau vạch trần tội ác của Walker, phối hợp cùng cảnh sát đập tan tổ chức tội phạm đứng sau những thí nghiệm phi nhân tính ấy.</p>', 'Full', 1, 'single', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hoàng Bách Quân","avatar":""},{"name":"Trương Sa Sa","avatar":""},{"name":"Trịnh Hiểu Dân","avatar":""},{"name":"Hà Dũng Sinh","avatar":""},{"name":"Mẫn Chính","avatar":""},{"name":"Hoàng Ích Long","avatar":""},{"name":"Ngô Xuân Di","avatar":""},{"name":"Tằng Thần","avatar":""},{"name":"Nhạc Đông Phong","avatar":""},{"name":"Lý Quân","avatar":""},{"name":"Tất Siêu","avatar":""},{"name":"Lữ Dương","avatar":""},{"name":"Bàng Ngọc Long","avatar":""},{"name":"Ngọc Khiếu Tây Lệ","avatar":""},{"name":"Vương Vịnh","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["河童之湄澜怪谈"]', 1784690324133);
