INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-boonie-phan-3', 'Biệt Đội Boonie (Phần 3)', 'Boonie Squad (Season 3)', 'https://phimimg.com/upload/vod/20260429-1/2b8410abe514e826bc57aad619ff82b6.jpg', 'https://phimimg.com/upload/vod/20260429-1/27a830b38d03e989f7254d3d1d02ff62.jpg', '<p>Biệt Đội Boonie gồm bốn bạn nhỏ Bramble, Briar, Neva và Vick luôn xuất hiện kịp thời mỗi khi người dân trong thị trấn gặp khó khăn. Dù là chỗ dựa đáng tin cậy cho mọi người nhưng đôi khi Biệt Đội Boonie cũng phải đối mặt với những thử thách lớn. Sát cánh bên nhau, nhóm bạn có thêm nhiều người bạn mới, biết thêm các kiến thức kỳ diệu về động vật và thiên nhiên, đặc biệt các bạn ấy còn học được vô số bài học quý giá để trở thành những em bé ngoan.</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 33, 2025, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["Boonie Squad","熊熊帮帮团"]', 1784690324133);
