INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vu-thanh-xuan', 'Điệp Vụ Thanh Xuân', 'Undercover High School', 'https://phimimg.com/upload/vod/20250222-1/ee63b21e3a29e7a64a2b50e7fb00824b.jpg', 'https://phimimg.com/upload/vod/20250222-1/766117a9a994b533eb515dc7b84f92d7.jpg', '<p>&quot;Điệp vụ thanh xuân&quot; là bộ phim hài hành động kể về Jung Hae Sung (Seo Kang Joon), đặc vụ xuất sắc của Cơ quan Tình báo Quốc gia Hàn Quốc (NIS). Sau một sự cố nghiêm trọng, anh bị giáng chức và nhận nhiệm vụ đặc biệt: giả dạng học sinh trung học để điều tra về kho vàng thất lạc của Hoàng đế Gojong.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 23, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Seo Kang-joon","avatar":""},{"name":"Jin Ki-joo","avatar":""},{"name":"Kim Shin-rock","avatar":""},{"name":"Kim Min-ju","avatar":""},{"name":"Yoon Ga-i","avatar":""},{"name":"Kim Young-ah","avatar":""},{"name":"Lee Hyeon-so","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["언더커버 하이스쿨"]', 1784690324133);
