INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-re-ngoc', 'Chàng Rể Ngốc', 'Royal Upstart', 'https://phimimg.com/upload/vod/20250710-1/035126db317ba1b01658f7377da99056.jpg', 'https://phimimg.com/upload/vod/20250710-1/a841db75260f7cfcceaab40d505e1562.jpg', '<p>Một tai nạn bất ngờ đưa Tiêu Ninh xuyên không đến triều Đại Cảnh, trở thành con rể ở rể nhà họ Tô. Chàng dùng cổ pháp biến hóa cho trà và rượu thêm phần thơm ngon, khiến mọi người đua nhau giành giật. Chàng còn sáng tạo báo giấy, chiêu mộ anh tài, giúp công chúa tung hoành triều đường. Đối mặt với sự gây khó dễ của con gái thương nhân, sự khinh thường của vợ cũ, chàng vẫn điềm nhiên bày binh bố trận, dùng việc kinh doanh làm vũ khí lật đổ thành kiến thế tục. Giữa những lời lẽ khinh bỉ, chàng viết nên truyền kỳ vượt qua nghịch cảnh.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Phan Nghị Hồng","avatar":""},{"name":"Chu Dung Quân","avatar":""},{"name":"Phạm Mộng","avatar":""},{"name":"Cô Chỉ Vân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Xian Xu","憨婿","贤婿之憨婿","贤婿2","贤婿2之憨婿","贤婿"]', 1784690324133);
