INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-do', 'Mưa Đỏ', 'Red Rain', 'https://phimimg.com/upload/vod/20251118-1/76eca7ea1349c90e5796c8b167d11a4e.jpg', 'https://phimimg.com/upload/vod/20251118-1/4d1c4fef91410badb2dcb3d675888d39.jpg', '<p>Bộ phim&nbsp;lấy cảm hứng và hư cấu từ sự kiện 81 ngày đêm chiến đấu anh dũng, kiên cường của nhân dân và cán bộ, chiến sĩ bảo vệ Thành Cổ Quảng Trị năm 1972. Tiểu đội 1 gồm toàn những thanh niên trẻ tuổi và đầy nhiệt huyết là một trong những đơn vị chiến đấu, bám trụ tại trận địa khốc liệt này. Bộ phim là khúc tráng ca bằng hình ảnh, là nén tâm nhang tri ân và tưởng nhớ những người con đã dâng hiến tuổi thanh xuân cho đất nước, mang âm hưởng của tình yêu, tình đồng đội thiêng liêng, là khát vọng hòa bình, hoà hợp dân tộc của nhân dân Việt Nam.</p>', 'Full', 1, 'single', 'completed', 56, 2025, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Đỗ Nhật Hoàng","avatar":""},{"name":"Steven Nguyễn","avatar":""},{"name":"Phương Nam","avatar":""},{"name":"Lâm Thanh Nhã","avatar":""},{"name":"Đình Khang","avatar":""},{"name":"Hoàng Long","avatar":""},{"name":"Nguyễn Hùng","avatar":""},{"name":"Hứa Vĩ Văn","avatar":""},{"name":"Mai Thế Hiệp","avatar":""},{"name":"Châu Hà Yến Nhi","avatar":""},{"name":"Trần Lực","avatar":""},{"name":"Le Ha Anh","avatar":""},{"name":"Lương Gia Huy","avatar":""},{"name":"Le Minh Thuan","avatar":""},{"name":"Nguyễn Trọng Hải","avatar":""},{"name":"Lê Mạnh Phương","avatar":""},{"name":"Đinh Thuý Hà","avatar":""},{"name":"Thân Thúy Hà","avatar":""},{"name":"Ngô T","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5e