INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dia-dao-mat-troi-trong-bong-toi', 'Địa Đạo: Mặt Trời Trong Bóng Tối', 'Tunnels: Sun In The Dark', 'https://phimimg.com/upload/vod/20250519-1/d041b7d764329efdbb5222010f0f1796.jpg', 'https://phimimg.com/upload/vod/20250519-1/9877afe853d8484edcbe040cb3221ced.jpg', '<p>Năm 1967, giữa lúc Chiến tranh Việt Nam đang ở đỉnh điểm, đội du kích cách mạng 21 người trở thành mục tiêu “tìm và diệt” số 1 của quân đội Mỹ khi nhận nhiệm vụ bằng mọi giá phải bảo vệ một nhóm thông tin tình báo chiến lược mới đến ẩn náu tại căn cứ.</p>', 'Full', 1, 'single', 'completed', 43, 2025, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Thái Hòa","avatar":""},{"name":"Ngô Quang Tuấn","avatar":""},{"name":"Hồ Thu Anh","avatar":""},{"name":"Diễm Hằng Lamoon","avatar":""},{"name":"Anh Tú Wilson","avatar":""},{"name":"Hoàng Minh Triết","avatar":""},{"name":"Nhật Ý","avatar":""},{"name":"Khanh Ly","avatar":""},{"name":"A Tới","avatar":""},{"name":"Cao Sang Lê","avatar":""},{"name":"Cao Minh","avatar":""},{"name":"Bùi Thạc Phong","avatar":""},{"name":"Karel Granat","avatar":""},{"name":"Albert Kalimullin","avatar":""},{"name":"Dustin Phuc Nguyen","avatar":""},{"name":"Trần Gia Bảo","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["Địa đạo: Mặt trời trong bóng tối"]', 1784690324133);
