INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tri-tue-tiem-nang-phan-2', 'Trí Tuệ Tiềm Năng (Phần 2)', 'High Potential (Season 2)', 'https://phimimg.com/upload/vod/20250920-1/ce3f9b795730a823cd263e0d9c255c34.jpg', 'https://phimimg.com/upload/vod/20250920-1/f16c378dd0aee85dee2e9ba0dd9ad6e2.jpg', '<p>&quot;High Potential&quot; là một bộ phim truyền hình mới tập trung vào câu chuyện của Morgan, một bà mẹ đơn thân trí tuệ hơn người và óc phán đoán sắc sảo, có ba người con. Morgan làm việc tại sở cảnh sát với vai trò là nhân viên vệ sinh, nhưng nhờ vào trí tuệ và khả năng quan sát phi thường, cô vô tình phát hiện ra các chi tiết quan trọng bị bỏ lỡ trong một vụ án. Trong quá trình sắp xếp bằng chứng trong ca làm việc, Morgan nhận ra manh mối mà các điều tra viên đã bỏ qua, và nhờ vậy, cô có cơ hội hỗ trợ cảnh sát trong việc tìm ra thủ phạm.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 22, 2025, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Kaitlin Olson","avatar":""},{"name":"Daniel Sunjata","avatar":""},{"name":"Judy Reyes","avatar":""},{"name":"Steve Howey","avatar":""},{"name":"Javicia Leslie","avatar":""},{"name":"Deniz Akdeniz","avatar":""},{"name":"Amirah J","avatar":""},{"name":"Matthew Lamb","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["拂尘奇探","潜能探案组","高度潜力","HPI USA","Великий потенціал","High Potential"]', 1784690324133);
