INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('5-centimet-tren-giay-live-action', '5 Centimet Trên Giây (Live Action)', '5 Centimeters per Second', 'https://phimimg.com/upload/vod/20260428-1/347878d26eb4c205e33247c5d74e6197.jpg', 'https://phimimg.com/upload/vod/20260428-1/0eb6381f0044bdde5a22a4c113964f7a.jpg', '<p>Mùa xuân năm 1991. Takaki và Akari gặp nhau ở trường tiểu học và tiếp tục trao đổi thư từ ngay cả sau khi cô chuyển đi. Họ hứa với nhau lần cuối sẽ gặp lại. Giờ là năm 2008. Họ sống cuộc sống riêng của mình, con đường không bao giờ giao nhau. Những kỷ niệm vẫn còn mãi và một linh cảm về ngày đã hứa. Ngay cả bây giờ, những lời họ nói từ ngày đó vẫn lặng lẽ trôi nổi, vượt qua thời gian và khoảng cách. Một câu chuyện phù du về lời hứa tái ngộ với một người thân yêu.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hokuto Matsumura","avatar":""},{"name":"Mitsuki Takahata","avatar":""},{"name":"Yuzu Aoki","avatar":""},{"name":"Nana Mori","avatar":""},{"name":"Mai Kiryu","avatar":""},{"name":"Haruto Ueda","avatar":""},{"name":"Noa Shiroyama","avatar":""},{"name":"Aoi Miyazaki","avatar":""},{"name":"Hidetaka Yoshioka","avatar":""},{"name":"Takashi Okabe","avatar":""},{"name":"Seina Nakata","avatar":""},{"name":"Kentaro Tamura","avatar":""},{"name":"Junki Tozuka","avatar":""},{"name":"Naoki Matayoshi","avatar":""},{"name":"Keiko Horiuchi","avatar":""},{"name":"Himi Sato","avatar":""},{"name":"Ayana Shiramoto","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["劇場用実写映画『秒速5センチメートル』","Byousoku 5 Centimeter","Byōsoku 5 Centimeter","초속 5cm","5 Sentimetro kada Segundo","5 Centimeters per Second","5 Centimetros por segundo","秒速五厘米","秒速5センチメートル"]', 1784690324133);
