INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('5-centimet-tren-giay-live-action', '5 Centimet Trên Giây (Live Action)', '5 Centimeters per Second', '5 centimet trên giây (live action) 5 centimeters per second hokuto matsumura mitsuki takahata yuzu aoki nana mori mai kiryu haruto ueda noa shiroyama aoi miyazaki hidetaka yoshioka takashi okabe seina nakata kentaro tamura junki tozuka naoki matayoshi keiko horiuchi himi sato ayana shiramoto 劇場用実写映画『秒速5センチメートル』 byousoku 5 centimeter byōsoku 5 centimeter 초속 5cm 5 sentimetro kada segundo 5 centimeters per second 5 centimetros por segundo 秒速五厘米 秒速5センチメートル', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phien-nao-cua-cong-chua-ma-phap', 'Phiền Não Của Công Chúa Ma Pháp', 'The Fated Magical Princess: Who Made Me A Princess', 'https://phimimg.com/upload/vod/20260428-1/8e42786a3a49629b021df3d7beaa759f.jpg', 'https://phimimg.com/upload/vod/20260428-1/df0ce5a396d33c0c404b6d23139a5e51.jpg', '<p>Cô nàng công chúa Hy Á của vương quốc ma thuật sở hữu đôi mắt đá quý độc đáo. Cô phát hiện ra rằng những giấc mơ của mình dường như có thể tiên đoán tương lai. Ngày sinh nhật 18 tuổi, cô bị cuốn vào một âm mưu kinh hoàng, cha cô suýt mất mạng vì ma thuật hắc ám và cô cũng bị đày ải đến phương xa. Khi Hy Á lớn lên, những nhân vật của số phận lần lượt xuất hiện: vị vua cha nội tâm và lạnh lùng, vị pháp sư tự phụ và chua ngoa, kỵ sĩ trung thành, chàng công tử nhà công tước dịu dàng và hay e thẹn, cùng một cô gái khát khao tình thân… Liệu Hy Á dũng cảm và tốt bụng có thể đảo ngược số phận, bảo vệ mình và tất cả những người cô yêu quý không?</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tao Dian","avatar":""},{"name":"Zhao Lu","avatar":""},{"name":"Ma Zhengyang","avatar":""},{"name":"Zhang Qi","avatar":""},{"name":"Sun Ye","avatar":""},{"name":"Xu Hui","avatar":""},{"name":"Chen Yiwen","avatar":""},{"name":"Yang Chaoran","avatar":""},{"name":"Mu Xueting","avatar":""},{"name":"Zhang Pei","avatar":""},{"name":"Du Qingqing","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mofa Gongzhu De Xiao Fannao","Mo Fa Gong Zhu De Xiao Fan Nao","魔法公主的小烦恼动画片","某天成为公主","ناگهان یک روز تبدیل به یک پرنسس شدم","あるひ、おひめさまになってしまったけんについて","Aru Hi, Ohimesama ni Natte Shimatta Ken ni Tsuite","ある姫","Aruhime","Aru Hi, Ohime-sama ni Natteshimatta Ken ni Tsuite","Eoneu Nal Gongjuga Doeeobeoryeotda","Eoneu Nal Gongjuga Doeeo Beoryeotda","من جعلني أميرة","Kim Beni Prenses Yaptı","某天成為公主","Suddenly Became a Princess One Day","One Day, I Became a Princess","Suddenly, I Became a Princess","WMMAP","Who Made Me a Princess","Who Make Me A Princess","魔法公主的小烦恼"]', 1784690324133);
