INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phien-nao-cua-cong-chua-ma-phap', 'Phiền Não Của Công Chúa Ma Pháp', 'The Fated Magical Princess: Who Made Me A Princess', 'phiền não của công chúa ma pháp the fated magical princess: who made me a princess tao dian zhao lu ma zhengyang zhang qi sun ye xu hui chen yiwen yang chaoran mu xueting zhang pei du qingqing mofa gongzhu de xiao fannao mo fa gong zhu de xiao fan nao 魔法公主的小烦恼动画片 某天成为公主 ناگهان یک روز تبدیل به یک پرنسس شدم あるひ、おひめさまになってしまったけんについて aru hi, ohimesama ni natte shimatta ken ni tsuite ある姫 aruhime aru hi, ohime-sama ni natteshimatta ken ni tsuite eoneu nal gongjuga doeeobeoryeotda eoneu nal gongjuga doeeo beoryeotda من جعلني أميرة kim beni prenses yaptı 某天成為公主 suddenly became a princess one day one day, i became a princess suddenly, i became a princess wmmap who made me a princess who make me a princess 魔法公主的小烦恼', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-cuu-roi', 'Kẻ Cứu Rỗi', 'The Favor', 'https://phimimg.com/upload/vod/20260425-1/9c72e57666e2ad1e67957f584a5b829f.jpg', 'https://phimimg.com/upload/vod/20260425-1/24ca1b41ced5f7fa8163cba9d540f10a.jpg', '<p>Young-beom và Seon-hee từng có một cuộc sống hoàn hảo như trong tranh. Nhưng sau một vụ tai nạn xe hơi thảm khốc khiến cậu con trai đang tuổi thiếu niên của họ không thể đi lại được, họ thấy mình khao khát hy vọng vào một phép màu. Một ngày nọ, khi Young-beom tình cờ gặp một ông lão bí ẩn trong khu phố, những phép màu kỳ lạ bắt đầu xảy ra tại nhà họ. Tin đồn lan nhanh, và cả dân làng đều tìm đến gia đình họ với hy vọng được chia sẻ những phước lành này. Trong khi ông lão có vẻ như là vị cứu tinh thầm lặng, gia đình sớm nhận ra rằng mỗi phước lành đều để lại một bóng đen: phép màu này không phải là món quà hay ân huệ — đó là một lời nguyền đe dọa sẽ xé nát gia đình họ.</p>', 'Full', 1, 'single', 'completed', 18, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Byong-chul","avatar":""},{"name":"Song Ji-hyo","avatar":""},{"name":"Kim Hieora","avatar":""},{"name":"Jung Jae-eun","avatar":""},{"name":"Ahn Se-ho","avatar":""},{"name":"Kim Yeon-kyo","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Одолжение","The favor","El Favor","구원자"]', 1784690324133);
