INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-tay-golf-chuyen-nghiep-phan-3', 'Những Tay Golf Chuyên Nghiệp (Phần 3)', 'Full Swing (Season 3)', 'https://phimimg.com/upload/vod/20250226-1/7f8ad8b0304617d6f3cf597a20c82c6d.jpg', 'https://phimimg.com/upload/vod/20260422-1/366a1528d59c4f8efebaac9d2953b506.jpg', '<p>Loạt phim tài liệu chân thực này theo chân một nhóm các tay golf chuyên nghiệp gồm nhiều thành phần – cả trong và ngoài sân cỏ – trong suốt mùa giải tranh tài khốc liệt.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Amanda Balionis","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["全力挥杆：高尔夫大满贯之路","풀스윙","Full Swing"]', 1784690324133);
