INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-tan-cong-2025', 'Cuộc tấn công', 'Attack Of The Machine', 'https://phimimg.com/upload/vod/20260420-1/eaba3c69b4184486fc1951e5f463e509.jpg', 'https://phimimg.com/upload/vod/20260420-1/0b76ec17ece8b04035cf5922c57c512b.jpg', '<p>Số phận của nhân loại nằm trong tay một số ít nhà thám hiểm vũ trụ dũng cảm được chọn lọc, những người đang thực hiện một nhiệm vụ quan trọng là đối đầu với Cỗ máy.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Manuela Vellés","avatar":""},{"name":"Adam Quintero","avatar":""},{"name":"Paul Haapaniemi","avatar":""},{"name":"James Hayward Brinkley","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Attack Of The Machine"]', 1784690324133);
