INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-dai-cuong-da', 'Thời Đại Cuồng Dã', 'Resurrection', 'https://phimimg.com/upload/vod/20260420-1/f76772404897f8261b27da5eb38a9a78.jpg', 'https://phimimg.com/upload/vod/20260420-1/80faa8332cec26b8da2bf574044834bd.jpg', '<p>Trong tương lai xa, khi con người đã đánh đổi khả năng mơ mộng để đổi lấy sự bất tử, thế giới trở nên hoàn hảo đến mức lạnh lẽo. Mọi giấc mơ bị xóa sổ, mọi cảm xúc được lập trình phẳng lặng như mặt hồ không gợn sóng. Giữa thời đại ấy, một kẻ bị xã hội ruồng bỏ (Dịch Dương Thiên Tỉ) bắt đầu nhìn thấy những ảo ảnh — những mảnh vụn của giấc mơ, vừa đẹp đẽ vừa kinh hoàng. Anh dấn sâu vào thế giới do chính tâm trí mình tạo ra, nơi ranh giới giữa thực và ảo tan chảy, nơi Thư Kỳ và Lý Canh Hy xuất hiện như những bóng hình vừa cứu rỗi vừa đe dọa.
 Bi Gan, với phong cách hình ảnh trôi nổi và nhịp điệu thôi miên, dẫn người xem bước vào một không gian viễn tưởng đầy chất thơ, nơi câu hỏi “liệu ta còn là con người nếu không thể mơ?” vang lên ám ảnh giữa ánh sáng và bóng tối của một thời đại cuồng dã.</p>', 'Full', 1, 'single', 'completed', 21, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jackson Yee","avatar":""},{"name":"Shu Qi","avatar":""},{"name":"Mark Chao You-Ting","avatar":""},{"name":"Li Gengxi","avatar":""},{"name":"Huang Jue","avatar":""},{"name":"Chen Yongzhong","avatar":""},{"name":"Zhang Zhijian","avatar":""},{"name":"Chloe Maayan","avatar":""},{"name":"Nan Yan","avatar":""},{"name":"Guo Mucheng","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Kuang ye shi dai","Kuangye shidai","Résurrection","القيامة","رستاخیز","Resurrection","Възкресение","Resurrección","광야시대","Zmartwychwstanie","Воскрешение","狂野時代","Prisikėlimas","Vzkříšení","狂野时代"]', 1784690324133);
