INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-nhi-co-gai', 'Nữ Nhi (Cô Gái)', 'Girl', 'https://phimimg.com/upload/vod/20260420-1/1f327d428d6bfd142b6ec6a898480c36.jpg', 'https://phimimg.com/upload/vod/20260420-1/1b71f9997fa3b3a9587fad68a2bd24f7.jpg', '<p>Tiểu Lợi, một cô gái trẻ, tìm thấy niềm an ủi trong tình bạn với Lệ Lệ — người hiện thân cho những giấc mơ mà Tiểu Lợi từng kìm nén. Tuy nhiên, khát vọng của Tiểu Lợi bị thử thách bởi quá khứ của mẹ mình, một quá khứ phản chiếu chính những đấu tranh của nàng và giam cầm nàng trong một vòng xoáy tuyệt vọng.</p>', 'Full', 1, 'single', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Roy Chiu","avatar":""},{"name":"9m88","avatar":""},{"name":"Bai Xiao-Ying","avatar":""},{"name":"Audrey Lin","avatar":""},{"name":"Lai Yu-fei","avatar":""},{"name":"Esther Liu","avatar":""},{"name":"Bamboo Chen","avatar":""},{"name":"Liu Kuan-ting","avatar":""},{"name":"Peggy Tseng","avatar":""},{"name":"Cherry Hsieh","avatar":""},{"name":"Danny Liang","avatar":""},{"name":"Brando Huang","avatar":""},{"name":"Tiffany Anais Lin","avatar":""},{"name":"Sherry Chen","avatar":""},{"name":"Yang Xin-hua","avatar":""},{"name":"Chen Hsing-huan","avatar":""},{"name":"Hsiao Yu-han","avatar":""},{"name":"Song Ming-Chung","avatar":""},{"name":"Alex Hsu","avatar":""},{"name":"L","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["걸","여해","女孩"]', 1784690324133);
