INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-doi-mo-xam', 'Cảnh đồi mờ xám', 'A Pale View of Hills', 'https://phimimg.com/upload/vod/20260420-1/77c2118d1243d416572ac4f2d7ca8006.jpg', 'https://phimimg.com/upload/vod/20260420-1/6fe57e0f433056167e9d9c72f126efce.jpg', '<p>Câu chuyện được kể theo hai dòng thời gian song song, khám phá ký ức của một góa phụ người Nhật Bản trải dài từ Nagasaki thời hậu chiến những năm 1950 đến nước Anh trong thời kỳ Chiến tranh Lạnh những năm 1980, hé lộ những bí mật đan xen giữa quá khứ và hiện tại của bà ở hai biên giới.</p>', 'Full', 1, 'single', 'completed', 27, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 1, '[{"name":"Suzu Hirose","avatar":""},{"name":"Fumi Nikaido","avatar":""},{"name":"Yoh Yoshida","avatar":""},{"name":"Camilla Aiko","avatar":""},{"name":"Kouhei Matsushita","avatar":""},{"name":"Tomokazu Miura","avatar":""},{"name":"Lynette Edwards","avatar":""},{"name":"Rie Shibata","avatar":""},{"name":"Daichi Watanabe","avatar":""},{"name":"Romain Danna","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["Tooi Yamanami no Hikari","远山淡影","ลางรักที่กลางเขา","群山淡影","群山淡景","Pálida luz en las colinas","羣山淡影","Tôi yama-nami no hikari","遠い山なみの光"]', 1784690324133);
