INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('black-showman', 'Black Showman', 'Black Showman', 'https://phimimg.com/upload/vod/20260420-1/cfb409a8bf78943005a37b0e6c66a189.jpg', 'https://phimimg.com/upload/vod/20260420-1/e2d2ec51d7ef929049e56267d7398f02.jpg', '<p>Fukuyama vào vai Kamio Takeshi, một nhân vật chính vô cùng độc đáo, sở hữu tài năng ảo thuật xuất chúng đã giúp anh nổi tiếng ở Las Vegas và khả năng quan sát con người tinh tế, nhưng cũng rất keo kiệt với tiền bạc và nói dối dễ như thở. Hơn nữa, Kamio Mayo, cháu gái của Kamio Takeshi do Fukuyama thủ vai, người hợp tác với Takeshi sau khi cha cô bị sát hại và nỗ lực giải quyết vụ án mạng, sẽ do nữ diễn viên hàng đầu Arimura Kasumi đảm nhận. Cô đã xuất sắc thể hiện nhiều vai diễn đa dạng từ phim tình cảm đến phim hài và phim cổ trang, và khả năng diễn xuất chắc chắn của cô đã chinh phục trái tim khán giả!</p>', 'Full', 1, 'single', 'completed', 13, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Masaharu Fukuyama","avatar":""},{"name":"Kasumi Arimura","avatar":""},{"name":"Ryo Narita","avatar":""},{"name":"Toru Nakamura","avatar":""},{"name":"Erika Ikuta","avatar":""},{"name":"Win Morisaki","avatar":""},{"name":"Katsuhisa Namase","avatar":""},{"name":"Sae Okazaki","avatar":""},{"name":"Atsuhiro Inukai","avatar":""},{"name":"Atsushi Ito","avatar":""},{"name":"Subaru Kimura","avatar":""},{"name":"Yuki Morinaga","avatar":""},{"name":"Hiroki Akiyama","avatar":""},{"name":"Mari Hamada","avatar":""},{"name":"Tomomi Maruyama","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["ブラック・ショーマン"]', 1784690324133);
