INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rac-duong-pho', 'Rác đường phố', 'Street Trash', 'https://phimimg.com/upload/vod/20260420-1/2db21931cf7ef31a010aaf8abe9c069f.jpg', 'https://phimimg.com/upload/vod/20260420-1/83226315a4de0a96b041f2175c6e42c9.jpg', '<p>Một nhóm người vô gia cư lạc loài phải chiến đấu để sinh tồn khi họ phát hiện ra một âm mưu nhằm tiêu diệt tất cả những người vô gia cư trong thành phố.</p>', 'Full', 1, 'single', 'completed', 30, 2025, 'Vietsub', 'FHD', 'Nam Phi', 0, '[{"name":"Sean Cameron Michael","avatar":""},{"name":"Donna Cormack Thomson","avatar":""},{"name":"Joe Vaz","avatar":""},{"name":"Lloyd Martinez Newkirk","avatar":""},{"name":"Shuraigh Meyer","avatar":""},{"name":"Jonathan Pienaar","avatar":""},{"name":"Sidwell Ralitsoele","avatar":""},{"name":"Ryan Kruger","avatar":""},{"name":"Gary Green","avatar":""},{"name":"Warrick Grier","avatar":""},{"name":"Andrew Roux","avatar":""},{"name":"Colin Moss","avatar":""},{"name":"Carel Nel","avatar":""},{"name":"Suraya-Rose Santos","avatar":""},{"name":"Tuks Tad Lungu","avatar":""},{"name":"Grant Swanb","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["街头废物","Street Trash"]', 1784690324133);
