INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-bong-tuyet-nao-trong-sach', 'Không Bông Tuyết Nào Trong Sạch', 'The Woman in the White Car', 'https://phimimg.com/upload/vod/20260416-1/04c1483d482dcf26693a067074d9c1a0.jpg', 'https://phimimg.com/upload/vod/20260416-1/94b71174cb422a9c30e133f9282bd3e6.jpg', '<p>Ai rồi cũng nói dối… Một rạng sáng sau đêm bão tuyết, Do Kyung (Jung Ryeo-won) hốt hoảng lái xe đưa chị gái mình đến bệnh viện trong tình trạng đẫm máu. Ngay sau đó, nữ cảnh sát Hyun Joo (Lee Jung-eun) có mặt tại hiện trường và nhanh chóng cảm nhận được rằng sau những lời khai rối ren của Do-kyung là một sự thật đang bị che giấu. Khi mỗi người kể lại vụ việc theo một góc nhìn khác nhau, ranh giới giữa sự thật và dối trá dần tan biến – để lộ một bức tranh tâm lý u tối, rùng mình. Đêm tuyết phủ khiến mọi dấu vết đều biến mất, vậy ai mới thực sự là kẻ thủ ác?</p>', 'Full', 1, 'single', 'completed', 26, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 1, '[{"name":"Jung Ryeo-won","avatar":""},{"name":"Lee Jung-eun","avatar":""},{"name":"Jang Jin-hee","avatar":""},{"name":"Kang Jeong-woo","avatar":""},{"name":"Lee Hwi-jong","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["하얀 차를 탄 여자"]', 1784690324133);
