INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuot-yeu-meo', 'Chuột Yêu Mèo', 'Catch Me If You Love Me', 'https://phimimg.com/upload/vod/20260420-1/8fcb2e35075291e17f8fd4ffbdbaec6e.jpg', 'https://phimimg.com/upload/vod/20260420-1/4602aa3da6f3b5005277ea0b5135c226.jpg', '<p>Daniel, con nuôi của trùm xã hội đen, trong một vụ giao dịch quan trọng đã cưỡng đoạt cảnh sát Louis vốn sắp bị xử tử, khiến giao dịch thất bại. Để chuộc tội, Daniel lấy danh nghĩa theo đuổi, ngày ngày bám lấy Louis. Nhưng Louis cũng dần phát hiện ra Daniel không phải là kẻ &quot;xấu xa&quot; như vẻ bề ngoài. Ông trùm xã hội đen và viên cảnh sát ngày càng lún sâu trong những thăm dò và giằng co, còn những hiểm họa âm thầm phía sau cũng dần lộ diện…</p>', 'Hoàn Tất (53/53)', 53, 'series', 'completed', 35, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Weeravich Bumpensawat","avatar":""},{"name":"Krit Songdechakraiwut","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phim Ngắn","slug":"phim-ngan","id":"4f02d28224c0747511790d57fbb63a62"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["เกมรักซ่อนหา"]', 1784690324133);
