INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-duoc-lam-nam-chinh-trong-trai-tim-nam-chinh', 'Xin Được Làm Nam Chính Trong Trái Tim Nam Chính', 'Let Me Into Your Heart', 'https://phimimg.com/upload/vod/20260418-1/7b741919c9841f5b20059b67af800efc.jpg', 'https://phimimg.com/upload/vod/20260418-1/08ec9ce459c28c769bebc549ddcf9583.jpg', '<p>Hai chàng trai trẻ quyết định vượt qua ranh giới của bản thân để tham gia vào một vở Likay (một loại hình nghệ thuật sân khấu dân gian truyền thống của Thái Lan). Trong quá trình luyện tập và biểu diễn, họ không chỉ học hỏi về nghệ thuật mà còn khám phá những cảm xúc sâu kín trong lòng, dần dần phát triển một mối quan hệ đặc biệt vượt qua tình bạn.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 24, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Pitchathee Klaymongkon","avatar":""},{"name":"Krittapod Bunyamanee","avatar":""},{"name":"Tanutcha Taikham","avatar":""},{"name":"Patpasit Na Songkhla","avatar":""},{"name":"Puttiwat Sathanthoranin","avatar":""},{"name":"Thitisan Goodburn","avatar":""},{"name":"Jarasrawee Thiemrat","avatar":""},{"name":"Jirat Klaimongkol","avatar":""},{"name":"Nathaphop Kanjanteak","avatar":""},{"name":"Joseph Gorach","avatar":""},{"name":"Gig Irada Boonmee","avatar":""},{"name":"Sayapa Singchoo","avatar":""},{"name":"Sitthinon Ro","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["LIKAY THE SERIES","Let Me Into Your Heart","Likay Hero The Series","ขอเป็นพระเอกในหัวใจ...พระเอก?","Phra-ek Likay The Series","ลิเกเดอะซีรีส์","พระเอกลิเก The Series","Kho Pen Phra-ek Nai Huajai Phra-ek","让我进入你的心","ขอเป็นพระเอกในหัวใจพระเอก"]', 1784690324133);
