INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('xin-duoc-lam-nam-chinh-trong-trai-tim-nam-chinh', 'Xin Được Làm Nam Chính Trong Trái Tim Nam Chính', 'Let Me Into Your Heart', 'xin được làm nam chính trong trái tim nam chính let me into your heart pitchathee klaymongkon krittapod bunyamanee tanutcha taikham patpasit na songkhla puttiwat sathanthoranin thitisan goodburn jarasrawee thiemrat jirat klaimongkol nathaphop kanjanteak joseph gorach gig irada boonmee sayapa singchoo sitthinon ro likay the series let me into your heart likay hero the series ขอเป็นพระเอกในหัวใจ...พระเอก? phra-ek likay the series ลิเกเดอะซีรีส์ พระเอกลิเก the series kho pen phra-ek nai huajai phra-ek 让我进入你的心 ขอเป็นพระเอกในหัวใจพระเอก', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-canh-bao-hay-than-trong', 'Có Cảnh Báo, Hãy Thận Trọng', 'Love Alert', 'https://phimimg.com/upload/vod/20260418-1/5076ac853fbae81bbb9b50ab80150d72.jpg', 'https://phimimg.com/upload/vod/20260418-1/cd3b2d3ae990b2634db81b3e066b8c1a.jpg', '<p>Jimmy, một tay đào hoa khét tiếng, muốn tìm cách đến gần Plaifah nên chủ động đưa Teh về nhà. Nhưng trớ trêu thay, khi gặp Toh, Jimmy lại bất ngờ rung động với anh. Mọi chuyện càng rối ren hơn khi trong một chuyến đi chung, Teh bắt đầu hẹn hò với Plaifah. Trái tim tan vỡ, Jimmy vì tức tối mà lao vào mối quan hệ với Toh, nhưng rồi sớm nhận ra rằng những cảm xúc cậu dành cho Toh là thật lòng.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"James Prescott","avatar":""},{"name":"Kad Ploysupa","avatar":""},{"name":"David Matthew Roberts","avatar":""},{"name":"Thanuphat Poungsuwan","avatar":""},{"name":"Jiramate Srinonghang","avatar":""},{"name":"Anakin Nontiprasit","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["心动警告","Mi Kham Tuean Prot Ramatrawang","มีคำเตือน โปรดระมัดระวัง","มีคำเตือนโปรดระมัดระวัง"]', 1784690324133);
