INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-hinh-cua-cha', 'Bóng Hình Của Cha', 'My Father''s Shadow', 'https://phimimg.com/upload/vod/20260413-1/bd915f3099b40ed8540c56decb7d1b0b.jpg', 'https://phimimg.com/upload/vod/20260413-1/676c546b49168d2f8b086375f848f3fd.jpg', '<p>Bộ phim xoay quanh một người con trưởng thành sống trong sự ám ảnh về người cha đã mất — một người đàn ông bí ẩn, nghiêm khắc và mang nhiều bí mật chưa từng được tiết lộ. Sau khi cha qua đời, anh phát hiện ra những dấu vết kỳ lạ liên quan đến quá khứ của ông: những bức thư cũ, các mối quan hệ bị che giấu, và một sự kiện đau thương mà gia đình chưa bao giờ nhắc tới.</p>', 'Full', 1, 'single', 'completed', 23, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Ṣọpẹ́ Dìrísù","avatar":""},{"name":"Efon Wini","avatar":""},{"name":"Godwin Egbo","avatar":""},{"name":"Chibuike Marvellous Egbo","avatar":""},{"name":"Tosin Adeyemi","avatar":""},{"name":"Adesina McCoy Babalola","avatar":""},{"name":"Lawrence Chu","avatar":""},{"name":"Patrick Diabuah","avatar":""},{"name":"Paul Edobor","avatar":""},{"name":"Martha Ehinome Orhiere","avatar":""},{"name":"Ayo Lijadu","avatar":""},{"name":"Greg ''Teddybear'' Ojeufa","avatar":""},{"name":"Uzoamaka Power","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Mano tėvo šešėlis","A Sombra do Meu Pai","爸爸的背影","My Father''s Shadow"]', 1784690324133);
