INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vu-cuop-omro', 'Vụ cướp Omro', 'The Omro Heist', 'vụ cướp omro the omro heist simon phillips anthony crivello damir kovic heather arendt nick biskupek ken bressers alcides dias cali felix justin gordon tony lee gratz alicia hinson mackenzie jones kristen mccabe adam huel potter the omro heist', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hay-de-toi-toa-sang', 'Hãy Để Tôi Tỏa Sáng', 'Love''s Ambition', 'https://phimimg.com/upload/vod/20250926-1/294c27497ba9f1959d12039d1722836a.jpg', 'https://phimimg.com/upload/vod/20250926-1/772c2d2292ce0389f77b212c7704f2d6.jpg', '<p>Nữ MC đình đám Hứa Nghiên và tinh anh chốn thành thị Thẩm Hạo Minh là cặp vợ chồng khiến ai nấy đều ngưỡng mộ. Bề ngoài, hai người dường như vô cùng xứng đôi, nhưng vì khác biệt về môi trường xuất thân, cả hai luôn khó lòng hòa hợp vào thế giới của nhau. Hứa Nghiên dựa vào thân phận MC hào nhoáng cùng một &quot;lai lịch được tô vẽ kỹ lưỡng&quot;, thuận lợi bước vào cuộc hôn nhân với Thẩm Hạo Minh. Song, tất cả vốn đều nằm trong suy tính của anh. Khi mâu thuẫn nổ ra, Hứa Nghiên quyết định dứt khoát rời đi, thoát khỏi sự khống chế của Thẩm Hạo Minh. Lúc này, anh mới nhận ra mình đã thật sự yêu Hứa Nghiên và quyết tâm giành lại trái tim cô. Trải qua muôn vàn thử thách, cả hai cuối cùng cũng gỡ bỏ lớp vỏ bọc ngụy trang, một lần nữa lại gần nhau, nhìn thấy nội tâm thật sự của đối phương và cũng tìm lại được chính mình.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 16, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Lộ Tư","avatar":""},{"name":"Trần Vỹ Đình","avatar":""},{"name":"Vạn Bằng","avatar":""},{"name":"Đường Hiểu Thiên","avatar":""},{"name":"Chung Nhất Đình","avatar":""},{"name":"Vương Y Dao","avatar":""},{"name":"Hứa Á Quân","avatar":""},{"name":"Ôn Tranh Vanh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ambição do amor","大喬小喬","大乔小乔",