INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duc-me-ho-quarry', 'Đức Mẹ Hồ Quarry', 'The Virgin of the Quarry Lake', 'https://phimimg.com/upload/vod/20260408-1/306417cee050457607fa5c87603abab2.jpg', 'https://phimimg.com/upload/vod/20260408-1/d177b2d26802d99579ebaf09bf634186.jpg', '<p>Vào một mùa hè nóng nực đầu thiên niên kỷ mới, ngay trước thềm cuộc khủng hoảng kinh tế lớn năm 2001, một nhóm nữ sinh tuổi teen đem lòng yêu một chàng trai tên Diego. Mối tình lãng mạn bị gián đoạn khi Diego bắt đầu qua lại với Silvia, một người phụ nữ 30 tuổi mà anh quen trong phòng chat. Lúc này, Natalia, một trong những cô gái trẻ, quyết định tìm đến kiến thức của bà ngoại Rita, và nhờ đó xua tan nỗi thất vọng bằng cách sử dụng một sức mạnh hắc ám cổ xưa.</p>', 'Full', 1, 'single', 'completed', 29, 2025, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Dolores Oliverio","avatar":""},{"name":"Fernanda Echevarría del Rivero","avatar":""},{"name":"Agustín Sosa","avatar":""},{"name":"Luisa Merelas","avatar":""},{"name":"Isabel Bracamonte","avatar":""},{"name":"Candela Flores","avatar":""},{"name":"Dady Brieva","avatar":""},{"name":"Víctor López","avatar":""},{"name":"Marcelo Antonio Diaz","avatar":""},{"name":"Alejandra Peralta Ramos","avatar":""},{"name":"Maicol Orihuela","avatar":""},{"name":"Willy Olarte","avatar":""},{"name":"Matheo Falbo","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["La virgen de la tosquera"]', 1784690324133);
