INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-lon', 'Đồi Lợn', 'Pig Hill', 'https://phimimg.com/upload/vod/20260408-1/d217e1d76167e094e5c53b31e7b98b11.jpg', 'https://phimimg.com/upload/vod/20260408-1/e24cd753e20c28e73a4dd4f5a39b5e54.jpg', '<p>Carrie bị cuốn hút bởi truyền thuyết địa phương về những người lợn ở Đồi Lợn, những sinh vật gớm ghiếc sinh sôi nảy nở và gây ra hỗn loạn trong khu vực. Khi người phụ nữ thứ mười mất tích, Carrie không ngừng nghĩ rằng có thể còn nhiều điều bí ẩn hơn nữa đằng sau những câu chuyện này.</p>', 'Full', 1, 'single', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rainey Qualley","avatar":""},{"name":"Shane West","avatar":""},{"name":"Shiloh Fernandez","avatar":""},{"name":"Isabella Brenza","avatar":""},{"name":"R.A. Mihailoff","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Pig Hill"]', 1784690324133);
