INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-dam-ruc-lua', 'Nắm đấm rực lửa', 'Blazing Fists', 'https://phimimg.com/upload/vod/20260409-1/0e9e56d133a6e30e45a443cef23ea4ea.jpg', 'https://phimimg.com/upload/vod/20260409-1/49fc60d3b9c7e526a4e3ecf55fbce6da.jpg', '<p>Ikuto và Ryoma trở nên thân thiết sau khi gặp nhau trong trại giam dành cho vị thành niên. Được khích lệ bởi những lời nói của Mikuru Asakura, họ đặt mục tiêu tham gia sự kiện võ thuật Breaking Down, nhưng những đối thủ tiềm tàng đe dọa phá vỡ giấc mơ của họ.</p>', 'Full', 1, 'single', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Danhi Kinoshita","avatar":""},{"name":"Kaname Yoshizawa","avatar":""},{"name":"GACKT","avatar":""},{"name":"Mariko Shinoda","avatar":""},{"name":"Anna Tsuchiya","avatar":""},{"name":"Chikashi Kuon","avatar":""},{"name":"Kyosuke Yabe","avatar":""},{"name":"Wataru Ichinose","avatar":""},{"name":"Konatsu Kato","avatar":""},{"name":"On Nakano","avatar":""},{"name":"Karuma","avatar":""},{"name":"Shoki Nakayama","avatar":""},{"name":"Shuzo Ohira","avatar":""},{"name":"Miku Tanaka","avatar":""},{"name":"Nobuaki Kaneko","avatar":""},{"name":"Susumu Terajima","avatar":""},{"name":"Katsunori Takahashi","avatar":""},{"name":"Takayuk","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Blue Fight: The Breaking Down of Young Blue Warriors","BLUE FIGHT 蒼き若者たちのブレイキングダウン"]', 1784690324133);
