INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-tay', 'Đông Tây', 'Eastern Western', 'https://phimimg.com/upload/vod/20260409-1/d2c2339f8374afd6b9d5cf3e57c888f8.jpg', 'https://phimimg.com/upload/vod/20260409-1/d3e2839c3730ee070ae76abc8196e590.jpg', '<p>Bộ phim miền Tây đầy tinh tế này kể về câu chuyện của một người con trai được nuôi dưỡng bởi hai người cha, một người đến từ Đông Âu và một người đến từ miền Tây nước Mỹ. Vào thời điểm chuyển giao thế kỷ 20, ở đâu đó trên vùng biên giới nước Mỹ, Igor, một người nhập cư và góa vợ gần đây, phải vật lộn để nuôi dạy cậu con trai hai tuổi Ivo một mình. Khi người bạn và người thầy người Mỹ của anh, Duncan, quyết định chuyển công việc kinh doanh chăn nuôi ngựa và gia đình nhỏ của mình đến California, Igor và Ivo đã cùng đoàn xe ngựa hướng về phía Tây.</p>', 'Full', 1, 'single', 'completed', 36, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Duncan Vezain","avatar":""},{"name":"Igor Galijasevic","avatar":""},{"name":"Walter Runningcrane Jr.","avatar":""},{"name":"Shawn Perkins","avatar":""},{"name":"Zdravko Strkalj","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '["Eastern Western"]', 1784690324133);
