INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('avatar-lua-va-tro-tan', 'Avatar: Lửa và Tro Tàn', 'Avatar: Fire And Ash', 'https://phimimg.com/upload/vod/20251221-1/6ac9fcafbe963ce8fbae6aaffb3d642e.jpg', 'https://phimimg.com/upload/vod/20251221-1/687373bb9894616507f27c74c0eaa598.jpg', '<p>Sau cuộc chiến tàn khốc với RDA và nỗi mất mát to lớn khi đứa con trai cả hy sinh, Jake Sully và Neytiri phải đối mặt với một mối đe dọa mới trên Pandora: tộc Tro Tàn — một nhóm Na&quot;vi hung bạo và khát khao quyền lực, do thủ lĩnh tàn nhẫn Varang dẫn dắt. Gia đình Jake buộc phải chiến đấu để sinh tồn và bảo vệ tương lai của Pandora, trong một cuộc xung đột đẩy họ đến giới hạn cuối cùng cả về thể xác lẫn tinh thần.</p>', 'Full', 1, 'single', 'completed', 29, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Sam Worthington","avatar":""},{"name":"Zoe Saldaña","avatar":""},{"name":"Sigourney Weaver","avatar":""},{"name":"Stephen Lang","avatar":""},{"name":"Oona Chaplin","avatar":""},{"name":"Jack Champion","avatar":""},{"name":"Kate Winslet","avatar":""},{"name":"Cliff Curtis","avatar":""},{"name":"Joel David Moore","avatar":""},{"name":"CCH Pounder","avatar":""},{"name":"Edie Falco","avatar":""},{"name":"Brendan Cowell","avatar":""},{"name":"Jemaine Clement","avatar":""},{"name":"Giovanni Ribisi","avatar":""},{"name":"David Thewlis","avatar":""},{"name":"Britain Dalton","avatar":""},{"name":"Trinity Jo-L","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch"