INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-an-vien-kim-cuong-chet', 'Bí Ẩn Viên Kim Cương Chết', 'Reflection in a Dead Diamond', 'https://phimimg.com/upload/vod/20260307-1/0ce65bc6a0ce4b493bff012b2069ee03.jpg', 'https://phimimg.com/upload/vod/20260307-1/c5f8294df7a445349b11b19407dac34b.jpg', '<p>Reflection in a Dead Diamond kể về một cựu điệp viên già sống ẩn dật bên bờ biển, nhưng khi một người phụ nữ bí ẩn đột nhiên biến mất, ông nghi ngờ quá khứ đầy bạo lực của mình đã quay lại. Bị cuốn vào những ký ức rối loạn về thời làm điệp viên và các vụ kim cương đẫm máu, ông phải đối mặt với sự thật rằng kẻ thù cũ vẫn đang săn …</p>', 'Full', 1, 'single', 'completed', 21, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Pháp', 0, '[{"name":"Fabio Testi","avatar":""},{"name":"Yannick Renier","avatar":""},{"name":"Koen De Bouw","avatar":""},{"name":"Maria de Medeiros","avatar":""},{"name":"Thi-Mai Nguyen","avatar":""},{"name":"Céline Camara","avatar":""},{"name":"Kézia Quental","avatar":""},{"name":"Manon Beuchot","avatar":""},{"name":"Hervé Sogne","avatar":""},{"name":"Sylvia Camarda","avatar":""},{"name":"Barbara Hellemans","avatar":""},{"name":"Sébastien Landry","avatar":""},{"name":"Aline Stevens","avatar":""},{"name":"Sophie Mousel","avatar":""},{"name":"Olivier Bisback","avatar":""},{"name":"Nilton Martins","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Reflection in A Dead Diamond","Reflet dans un diamant mort","Błysk diamentu śmierci","리플렉션"]', 1784690324133);
