INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chon-sau', 'Chôn sâu', 'Bury ''Em Deep', 'https://phimimg.com/upload/vod/20260409-1/7f9b484acaa2ac27d5beb1de3384c325.jpg', 'https://phimimg.com/upload/vod/20260409-1/ff2d0c630e6c517020a03582d5640a1f.jpg', '<p>Một tay súng hung bạo nhìn thấy những ảo ảnh về Địa ngục và quyết định rằng để chuộc lỗi, hắn sẽ dùng số tiền bất chính kiếm được để cứu lấy trại trẻ mồ côi của một nữ tu xinh đẹp. Nhưng khi bị phục kích và bỏ mặc cho chết, hắn bắt đầu cuộc hành trình báo thù.</p>', 'Full', 1, 'single', 'completed', 33, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Robert Bronzi","avatar":""},{"name":"Michael Paré","avatar":""},{"name":"Rosanna Wyant","avatar":""},{"name":"Kevin Karrick","avatar":""},{"name":"Gabriella Goldstein","avatar":""},{"name":"Allan Lazo","avatar":""},{"name":"Nico Abiera","avatar":""},{"name":"Bryan Hurd","avatar":""}]', '[{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Bury ''Em Deep"]', 1784690324133);
