INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luat-le-cua-jenny-pen', 'Luật Lệ của Jenny Pen', 'The Rule of Jenny Pen', 'https://phimimg.com/upload/vod/20260409-1/73b4bb7e19f3158b6722b9b1cd66c606.jpg', 'https://phimimg.com/upload/vod/20260409-1/cdaad4334ad5e693b4f0b6998c31c656.jpg', '<p>Một cựu thẩm phán sống trong viện dưỡng lão biệt lập, liệt toàn phần sau đột quỵ. Khi một gã tâm thần bắt đầu dùng con rối trẻ em để tra tấn và hãm hại người khác, ông là người duy nhất nhận ra điều đó — và phải tìm cách ngăn chặn thảm kịch, dù đang bị mắc kẹt trong chính cơ thể mình.</p>', 'Full', 1, 'single', 'completed', 28, 2025, 'Vietsub', 'FHD', 'Quốc Gia Khác', 0, '[{"name":"John Lithgow","avatar":""},{"name":"Geoffrey Rush","avatar":""},{"name":"Nathaniel Lees","avatar":""},{"name":"Maaka Pohatu","avatar":""},{"name":"Thomas Sainsbury","avatar":""},{"name":"Ian Mune","avatar":""},{"name":"Ginette McDonald","avatar":""},{"name":"Holly Shanahan","avatar":""},{"name":"Bruce Phillips","avatar":""},{"name":"Yvette Parsons","avatar":""},{"name":"Irene Wood","avatar":""},{"name":"Hannah Lynch","avatar":""},{"name":"Paolo Rotondo","avatar":""},{"name":"George Henare","avatar":""},{"name":"Nikki MacDonnell","avatar":""},{"name":"Fiona Collins","avatar":""},{"name":"Richard Chapm","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["珍妮潘的规则","The Rule of Jenny Pen"]', 1784690324134);
