INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-be-vang', 'Cậu Bé Vàng', 'Golden Boy', 'https://phimimg.com/upload/vod/20260409-1/b1d21053d40ed66f18d77d9e02cb8ace.jpg', 'https://phimimg.com/upload/vod/20260409-1/70676731969a3976003dfd27763e36b4.jpg', '<p>Mười năm trước, Cheung Lek là ngôi sao quyền anh triển vọng nhất – được mệnh danh là “Cậu bé vàng” – cho đến khi một biến cố bi thảm cướp đi tự do của anh. Mười năm sau, được thả khỏi tù, anh đối mặt với Fong Yuen, người con trai mà anh chưa từng gặp. Để giành được gia sản thừa kế từ mẹ của Fong Yuen, Cheung phải học cách sống chung và chăm sóc cậu bé. Bị đẩy vào vai trò làm cha và đối mặt với những hối tiếc trong quá khứ, cuộc sống của Cheung lại một lần nữa bị đảo lộn. Qua những xung đột và sự hòa giải dần dần với con trai, anh bắt đầu hiểu được mục đích thực sự của mình. Đối mặt với những bóng ma trong quá khứ, Cheung quyết định trở lại sàn đấu – không chỉ để lấy lại giấc mơ của mình, mà còn để trở thành hình mẫu mà con trai anh xứng đáng có được.</p>', 'Full', 1, 'single', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Louis Cheung","avatar":""},{"name":"Leander Lau","avatar":""},{"name":"Rosa Maria Velasco","avatar":""},{"name":"Eric Tsang Chi-Wai","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Tommy Chu Pak-Hong","avatar":""},{"name":"Dough-Boy","avatar":""},{"name":"Gladys Li","avatar":""},{"name":"Anna Ueyama","avatar":""},{"name":"Lawrence Cheng Tan-Shui","avatar":""},{"name":"Ben Yuen Foo-Wah","avatar":""},{"name":"Mars","avatar":""},{"name":"Ali Lee","avatar":""},{"name":"Ricky Chan Chun-Wah","avatar":""},{"name":"April Leung Ho-Yan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["金童"]', 1784690324134);
