INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hao-quang-lac-loi', 'Hào Quang Lạc Lối', 'Opus', 'https://phimimg.com/upload/vod/20260409-1/c2f7b9988f68c33e7d35e66e5caac41e.jpg', 'https://phimimg.com/upload/vod/20260409-1/18750c4d87ddbe79ccd9f96c2178d2fb.jpg', '<p>Một nhà văn trẻ tuổi được mời đến khu biệt lập xa xôi của một ngôi sao nhạc pop huyền thoại – người đã biến mất đầy bí ẩn suốt ba mươi năm. Tại đây, cô bị cuốn vào thế giới kỳ quái được bao quanh bởi những kẻ nịnh hót tôn sùng và các nhà báo say mê quyền lực. Khi càng dấn sâu, cô dần nhận ra mình chỉ là một phần trong kế hoạch méo mó, u tối của ông ta.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ayo Edebiri","avatar":""},{"name":"John Malkovich","avatar":""},{"name":"Juliette Lewis","avatar":""},{"name":"Murray Bartlett","avatar":""},{"name":"Melissa Chambers","avatar":""},{"name":"Tony Hale","avatar":""},{"name":"Stephanie Suganami","avatar":""},{"name":"Mark Sivertsen","avatar":""},{"name":"Amber Midthunder","avatar":""},{"name":"Tatanka Means","avatar":""},{"name":"Aspen Martinez","avatar":""},{"name":"Peter Diseth","avatar":""},{"name":"Tamera Tomakili","avatar":""},{"name":"Rose Marley Meizlesh","avatar":""},{"name":"Jasper Keen","avatar":""},{"name":"Young Mazino","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["致命著作","Opus"]', 1784690324134);
