INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-hoa-cuong-phong-tu-dia', 'Đạo Hoả Cuồng Phong Tử Địa', 'Relentless Fury', 'https://phimimg.com/upload/vod/20260409-1/753938b93bb9ccc98788e7fe77ae3d58.jpg', 'https://phimimg.com/upload/vod/20260409-1/cd5d1dc14ce610dda9580b070698cde0.jpg', '<p>Đội trưởng Lâm Lang – một người lính dày dạn kinh nghiệm, bản lĩnh và lạnh lùng – là thủ lĩnh của “Shadow”, một biệt đội lính đánh thuê tinh nhuệ, gồm bốn thành viên có kỹ năng chiến đấu và phối hợp chiến thuật bậc thầy. Nhóm này nổi tiếng trong giới ngầm với những phi vụ được thực hiện hoàn hảo đến mức gần như không để lại dấu vết – không có tổn thất, không thương vong, không thất bại. Chính sự kín đáo và hiệu quả tàn nhẫn ấy khiến tên tuổi &quot;Shadow&quot; trở thành nỗi ám ảnh với bất kỳ ai có ý định đối đầu.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Vanness Wu","avatar":""},{"name":"Andy On Chi-Kit","avatar":""},{"name":"Sammy Hung Tin-Chiu","avatar":""},{"name":"Zhao Renjie","avatar":""},{"name":"Zhao Xixi","avatar":""},{"name":"Cathryn Li","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Fearlessness of Hardship","Relentless Fury"]', 1784690324134);
