INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dam-thu-666', 'Dặm thứ 666', 'Mile 666', 'https://phimimg.com/upload/vod/20260409-1/cce61dcf21895292bd961087df74ae38.jpg', 'https://phimimg.com/upload/vod/20260409-1/0cfef46e6ef616649f555c54cbf16005.jpg', '<p>Trốn chạy khỏi quá khứ, một người leo núi gặp nhiều rắc rối cùng chú chó của mình vượt qua Đường mòn Appalachian, chỉ để rồi rơi vào bẫy của một người đàn ông nguy hiểm. Khi nỗi ám ảnh và ảo giác ngày càng gia tăng, cô bị cuốn hút về phía Cột mốc 666, nơi dục vọng, cái chết và một điều gì đó cổ xưa đang chờ đợi.</p>', 'Full', 1, 'single', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kinisha Crawford","avatar":""},{"name":"Gracie Gillam","avatar":""},{"name":"Ruby Chappelle Millstein","avatar":""},{"name":"Talmadge Ragan","avatar":""},{"name":"Erick L Rhodes","avatar":""},{"name":"Kalie''e L Rhodes","avatar":""},{"name":"Ellsworth Sullivan","avatar":""},{"name":"Nat Zang","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Mile 666"]', 1784690324134);
