INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-anacondas', 'The Anacondas', 'The Anacondas', 'https://phimimg.com/upload/vod/20260409-1/ab7b2256f49f7e936694d158ec878ea4.jpg', 'https://phimimg.com/upload/vod/20260409-1/ad11a23797b16cfe6a77f88ccb58a5fb.jpg', '<p>Các nhà thám hiểm ở Mexico đã phát hiện ra tàn tích của một nền văn minh cổ đại thờ rắn. Niềm vui biến thành nỗi kinh hoàng khi họ đánh thức một con trăn khổng lồ không ngừng lớn lên, con vật đã bị bỏ đói vì thiếu lễ vật hiến tế người trong nhiều thế kỷ. Giờ đây, cả nhóm phải đoàn kết để sống sót.</p>', 'Full', 1, 'single', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Hannah Hueston","avatar":""},{"name":"Jordan Iverach","avatar":""},{"name":"Philipp Karner","avatar":""},{"name":"Dominic Keating","avatar":""},{"name":"Maureen Kedes","avatar":""},{"name":"Bix Krieger","avatar":""},{"name":"Giselle Garci","avatar":""},{"name":"Marcus Mannis","avatar":""},{"name":"Brian Russell","avatar":""},{"name":"Danielle Titus","avatar":""},{"name":"Andrew Tong","avatar":""},{"name":"Michael James Vargas","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["The Anacondas"]', 1784690324134);
