INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tron-thoat-khoi-dao-ran', 'Trốn Thoát Khỏi Đảo Rắn', 'Snake Island Survival', 'https://phimimg.com/upload/vod/20250526-1/34b8e5a96ddcd0b444dd85128f6e9082.jpg', 'https://phimimg.com/upload/vod/20250526-1/8fb45c515b4be24a51f27450cb6a4ce3.jpg', '<p>Trương Dũng từng mất vợ khi cố bảo vệ một thiết bị giám sát đại dương. Nhiều năm sau, một trận bão lớn đưa anh tái ngộ với trạm trưởng già. Cũng từ đây, họ phát hiện ra một vụ ô nhiễm biển nghiêm trọng. Dưới sự dẫn dắt của trạm trưởng, họ cùng một nhóm người mạo hiểm tiến vào hòn đảo bí ẩn nhằm điều tra và phơi bày bí mật đằng sau vụ việc. Cuối cùng, họ đã bảo vệ thành công môi trường sống của các sinh vật biển. Đồng thời, Trương Dũng một lần nữa đảm nhận trách nhiệm bảo vệ đại dương.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Yu Lei","avatar":""},{"name":"王飞乔","avatar":""},{"name":"Zhu Haijun","avatar":""},{"name":"Wu Hao","avatar":""},{"name":"于雷","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["蛇岛求生"]', 1784690324134);
