INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bat-kha-chien-bai-phan-3', 'Bất Khả Chiến Bại (Phần 3)', 'Invincible (Season 3)', 'https://phimimg.com/upload/vod/20260322-1/a89905bc1ec8a34d5c2ff2a4b97fdd57.jpg', 'https://phimimg.com/upload/vod/20260322-1/9e26425c4f1adf4d1704755ae0c267f6.jpg', '<p>Invincible là series hoạt hình siêu anh hùng dành cho người lớn được chuyển thể từ truyện tranh cùng tên của Skybound/Image Comic do Robert Kirkman sáng tác. Phim được lên kế hoạch kéo dài trong 3 mùa và sẽ phát sóng thông qua nền tảng Amazon Prime Video.

Invincible là câu chuyện xoay quanh Mark Grayson, con trai của anh hùng mạnh nhất hành tinh - Omni-Man. Sau khi vừa tròn 17 tuổi, Mark bắt đầu thức tỉnh sức mạnh của riêng mình. Dưới sự giám hộ của Omni-Man, Mark dấn thân vào con đường trở thành siêu anh hùng và đối đầu với thử thách cam go.</p>', 'Hoàn Tất (8/8)', 8, 'hoathinh', 'completed', 22, 2025, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Steven Yeun","avatar":""},{"name":"Sandra Oh","avatar":""},{"name":"J.K. Simmons","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["无敌小子","无敌少侠","Unbesiegbar","Invencible","დაუმარცხებელი","無敵少俠","インビンシブル","O Invencivel","Неуязвимый","Nepremožiteľný","Невколупний","Непереможний","Невразливий","Invincible: Atom Eve","Invincible","INVINCIBLE"]', 1784690324134);
