INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vi-vua-manh-nhat-lam-gi-o-kiep-thu-hai-phan-1', 'Vị Vua Mạnh Nhất Làm Gì Ở Kiếp Thứ Hai (Phần 1)', 'The Beginning After The End (Season 1)', 'https://phimimg.com/upload/vod/20250403-1/1c54bc61de7a358e6d2699fae8f6f929.jpg', 'https://phimimg.com/upload/vod/20260407-1/a85cf6856cdcb0d6d1e470b17675053c.jpg', '<p>Grey, vị vua mạnh nhất trong lịch sử, là nhân vật chính của câu chuyện. Bất chấp danh tiếng, tài sản và quyền lực vô song, không ai ủng hộ anh ta... và anh ta không tin tưởng bất cứ ai. Một ngày nọ, Gray bất ngờ qua đời và tái sinh ở một thế giới phép thuật với cái tên Arthur, một đứa bé bất lực. Arthur bắt đầu khám phá những niềm vui trong cuộc sống mới này mà anh không hề biết đến ở cuộc sống cũ, được bao bọc bởi một gia đình và bạn bè yêu thương. Nhưng gia đình anh bị bọn cướp tấn công khi đang đi du lịch...</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Natsumi Fujiwara","avatar":""},{"name":"Makoto Furukawa","avatar":""},{"name":"Kana Ichinose","avatar":""},{"name":"Chiaki Omigawa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["三岁开始做王者","终末起点","最强的王者，在第二次的人生能做什么？","最强王者，第二人生要做什么？","El comienzo después del fin","Saikyou no Ousama, Nidome no Jinsei wa Nani o Suru?","Saikyô no Ôsama, Nidome no Jinsei wa Nani wo Suru?","Saikyo2dome","Saikyou no Ousama Nidome no Jinsei wa Nani wo Suru","끝이 아닌 시작","최강의 왕, 두번째 인생에는 무엇을 하는가?","Начало после конца","البداية بعد النهاية","三歲開始做王者","最強的王者，在第二次的人生能做什麼？","終末起點 第 2 季","Що зробить найсильніший коро