INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vi-vua-manh-nhat-lam-gi-o-kiep-thu-hai-phan-1', 'Vị Vua Mạnh Nhất Làm Gì Ở Kiếp Thứ Hai (Phần 1)', 'The Beginning After The End (Season 1)', 'vị vua mạnh nhất làm gì ở kiếp thứ hai (phần 1) the beginning after the end (season 1) natsumi fujiwara makoto furukawa kana ichinose chiaki omigawa 三岁开始做王者 终末起点 最强的王者，在第二次的人生能做什么？ 最强王者，第二人生要做什么？ el comienzo después del fin saikyou no ousama, nidome no jinsei wa nani o suru? saikyô no ôsama, nidome no jinsei wa nani wo suru? saikyo2dome saikyou no ousama nidome no jinsei wa nani wo suru 끝이 아닌 시작 최강의 왕, 두번째 인생에는 무엇을 하는가? начало после конца البداية بعد النهاية 三歲開始做王者 最強的王者，在第二次的人生能做什麼？ 終末起點 第 2 季 що зробить найсильніший король у другому житті? tbate the beginning after the end ánh sáng cuối con đường 最強の王様、二度目の人生は何をする？', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-nong-trong-mat', 'Tình Nồng Trong Mắt (Đôi Mắt Thâm Tình)', 'Deep Affection Eyes', 'https://phimimg.com/upload/vod/20250722-1/86a19e96f62114d193d99b27329c967c.jpg', 'https://phimimg.com/upload/vod/20250722-1/f3501205cdd8e5c2815483be95e6824b.jpg', '<p>Sau khi bước qua tuổi 30, Diệp Mông gặp nhiều trắc trở trong công việc. Cô quyết định nghỉ việc và mang theo toàn bộ số tiền tích góp trở về quê để bắt đầu một cuộc sống yên bình nơi thị trấn nhỏ. Tình cờ, cô gặp được Lý Cận Vũ – một người đàn ông có đôi mắt sâu thẳm đầy tình cảm, và bị cuốn hút bởi vẻ lạnh lùng, bí ẩn của anh. Hai tâm hồn xa lạ dần chạm đến nhau. Diệp Mông cảm động trước cuộc sống khó khăn của Lý Cận Vũ, chủ động giúp đỡ với tấm lòng đầy nhiệt thành. Nhờ sự theo đuổi chân thành của cô, anh dần mở lòng, trở nên tự tin và vui vẻ hơn. Họ cùng nhau sưởi ấm tâm hồn, chữa lành vết thương, và nỗ lực vun đắp cho tình yêu quý giá này.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Dư Hi","avatar":""},{"name":"Bách Vân Quân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shen Qing Yan","สายตารัก สัมผัสหัวใจ","Deep Eyes","Deep Affectionate Eyes","深情眼"]', 1784690324134);
