INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-ty-gia-dinh-bat-dong-san-hang-sang-phan-6', 'Công Ty Gia Đình Bất Động Sản Hạng Sang (Phần 6)', 'The Parisian Agency Exclusive Properties (Season 6)', 'https://phimimg.com/upload/vod/20260406-1/723a15fae5536a3783407e263cdc8bc3.jpg', 'https://phimimg.com/upload/vod/20260406-1/f1126ab8ab87bc7f35f247fb095883d1.jpg', '<p>Series thực tế này theo chân gia đình Kretz và công việc kinh doanh bất động sản xa xỉ của họ, khi họ giúp đỡ các khách hàng mua và bán những dinh thự tuyệt mỹ tại Pháp cũng như trên toàn thế giới.</p>', 'Hoàn Tất (9/9)', 9, 'tvshows', 'completed', 23, 2025, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Olivier Kretz","avatar":""},{"name":"Sandrine Kretz","avatar":""},{"name":"Martin Kretz","avatar":""},{"name":"Valentin Kretz","avatar":""},{"name":"Louis Kretz","avatar":""},{"name":"Raphaël Kretz","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["巴黎地产家族：热门豪宅","L''Agence - L''immobilier de luxe en famille"]', 1784690324134);
