INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cong-ty-gia-dinh-bat-dong-san-hang-sang-phan-6', 'Công Ty Gia Đình Bất Động Sản Hạng Sang (Phần 6)', 'The Parisian Agency Exclusive Properties (Season 6)', 'công ty gia đình bất động sản hạng sang (phần 6) the parisian agency exclusive properties (season 6) olivier kretz sandrine kretz martin kretz valentin kretz louis kretz raphaël kretz 巴黎地产家族：热门豪宅 l''agence - l''immobilier de luxe en famille', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phat-toi-2', 'Phạt Tội 2', 'The Punishment', 'https://phimimg.com/upload/vod/20251226-1/68a92730a6f1d000e096459e641606c7.jpg', 'https://phimimg.com/upload/vod/20251226-1/62220f1484fc8cba15766f944a50b42a.jpg', '<p>Bộ phim kể về cuộc đấu trí và đấu lực đầy gay cấn giữa cảnh sát Tần Phong và các băng nhóm tội phạm. Kịch bản lựa chọn những vụ án đặc biệt nghiêm trọng trong bối cảnh phát triển của thành phố Hán Châu, khắc họa mối quan hệ phức tạp giữa người cảnh sát với gia đình và các tập đoàn lợi ích. Mạch phim chính xoay quanh hai anh em khác họ là Tần Phong và Lưu Thiên Dã, qua đó hé lộ chiều sâu của nhân tính và những xung đột đạo đức gay gắt. Với tình tiết dồn dập và những nút thắt đầy kịch tính, bộ phim thể hiện sức mạnh của niềm tin vào pháp trị cũng như sự lựa chọn giữa thiện và ác.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 12, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hoàng Cảnh Du","avatar":""},{"name":"Vương Truyền Quân","avatar":""},{"name":"Lương Kiệt","avatar":""},{"name":"Lý You Bân","avatar":""},{"name":"Sa Nhật Na","avatar":""},{"name":"Tăng Vũ","avatar":""},{"name":"Tác Tân Minh","avatar":""},{"name":"Tôn Nhất Minh","avatar":""},{"name":"Trương Đồng","avatar":""},{"name":"Mai Hồng Siêu","avatar":""},{"name":"Hứa Tiểu Thụy","avatar":""},{"name":"Vương Tú","avatar":""},{"name":"Lưu Thiên Diễm","avatar":""},{"name":"Phùng Thanh Ninh","avatar":""},{"name":"Diệp Kiệt Thành","avatar":""},{"name":"La Bác","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Fa Zui Zhi