INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phat-toi-2', 'Phạt Tội 2', 'The Punishment', 'phạt tội 2 the punishment hoàng cảnh du vương truyền quân lương kiệt lý you bân sa nhật na tăng vũ tác tân minh tôn nhất minh trương đồng mai hồng siêu hứa tiểu thụy vương tú lưu thiên diễm phùng thanh ninh diệp kiệt thành la bác fa zui zhi ying xiong jian shi 罚罪之英雄简史 罚罪 ii 罚罪2', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-linh-cuu-hoa-phan-3', 'Biệt Đội Lính Cứu Hỏa (Phần 3)', 'Fire Force (Season 3)', 'https://phimimg.com/upload/vod/20250411-1/f628491ea49b3da90473487260e1e9fb.jpg', 'https://phimimg.com/upload/vod/20250411-1/26e2e526501396c2b3c4758761eb926a.jpg', '<p>Năm 198 của kỷ nguyên Thái Dương ở Tokyo, các đội cứu hỏa đặc thù chiến đấu chống lại Hiện tượng nhân thể bộc hỏa, khi cơ thể con người đột nhiên biến thành quái vật lửa được gọi Viêm Nhân. Shinra Kusakabe là một chàng trai trẻ bị gắn biệt danh là Dấu chân ác quỷ, vì chân của cậu ấy có thể bốc cháy theo ý muốn. Sau khi cậu gia nhập Đội lính cứu hỏa đặc thù số 8, cậu đã cùng những đồng đội trong đội ngũ chiến đấu chống lại các Viêm Nhân với sức mạnh lính cứu hỏa thế hệ thứ 3 của mình. Khi tiếp xúc với kẻ tạo ra Viêm Nhân, Shinra bắt đầu biết được bí mật của cuộc hỏa hoạn đã gây ra cái chết thương vong cho cả gia đình cậu 12 năm trước...</p>', 'Hoàn Tất (25/25)', 25, 'hoathinh', 'completed', 18, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Gakuto Kajiwara","avatar":""},{"name":"Yusuke Kobayashi","avatar":""},{"name":"Saeko Kamijo","avatar":""},{"name":"Mao Ichimichi","avatar":""},{"name":"Kazuya Nakai","avatar":""},{"name":"Kenichi Suzumura","avatar":""},{"name":"Aoi Yuki","avatar":""},{"name":"Daisuke Sakaguchi","avatar":""},{"name":"Taku Yashiro","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["炎炎消防队 叁之章","炎炎消防队 贰之章","炎炎消防队 壹之章","Fire Force","En''en no Shouboutai","Enn Enn no Shōbōtai","Enen no Shouboutai","Enen no Shouboutai: Ni no Shou","Enen no shôbôtai","En''en no Shouboutai Ni no Shou","Enn Enn no Shouboutai","Enen no Shōbōtai","Enen No Shouboutai - Ni no Shou","炎炎ノ消防隊 弐ノ章","炎炎ノ消防隊 参ノ章","Enen no Shouboutai San","Пламенная бригада пожарных","Пламенный отряд","Огненная бригада пожарных!","Огненная бригада","炎炎消防隊 貳之章","炎炎消防隊 參之章","Fire Brigade of Flames","Fireforce","Blazing Fire Brigade","Bộc Hỏa Nhân Tượng","炎炎ノ消防隊"]', 1784690324134);
