INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-la-vo-than-phan-2', 'Tu La Võ Thần (Phần 2)', 'Martial God Asura (Season 2)', 'https://phimimg.com/upload/vod/20260310-1/5c50ef5c9bcb92a52d4665015fa59649.jpg', 'https://phimimg.com/upload/vod/20260310-1/5b56e675bd0548eb2de184a0c3e139f3.jpg', '<p>Luận tiềm lực, không tính thiên tài, nhưng huyền công vũ kỹ, đều có thể vô sư tự thông. Luận mị lực, thiên kim tiểu thư tính toán là cái gì, yêu nữ thánh nữ, đều yêu ta, muốn ngừng mà không được. Luận thực lực, mặc kệ ngươi có ngàn vạn chí bảo, nhưng cũng không địch lại linh giới đại quân của ta. Ta là ai? Thiên hạ chúng sinh xem ta là Tu La, lại không biết, ta dùng Tu La thành võ thần… Đi đến đỉnh phong.</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 13, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Xiuluo Wu Shen","Xiuluo Wushen","Xiu Luo Wu Shen","Dios Marcial Asura","Martial God Asura","MGA","Shura Valkyrie","修罗武神"]', 1784690324134);
