INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tu-la-vo-than-phan-2', 'Tu La Võ Thần (Phần 2)', 'Martial God Asura (Season 2)', 'tu la võ thần (phần 2) martial god asura (season 2)  xiuluo wu shen xiuluo wushen xiu luo wu shen dios marcial asura martial god asura mga shura valkyrie 修罗武神', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-watson-phan-1', 'Bác Sĩ Watson (Phần 1)', 'Watson (Season 1)', 'https://phimimg.com/upload/vod/20260316-1/6b07f4108231db797f78498eefa2d3e2.jpg', 'https://phimimg.com/upload/vod/20260316-1/87921721aff41922d201f5ebcd6e79e3.jpg', '<p>Bộ phim kể về hành trình của Bác sĩ John Watson - người bạn và cộng sự trung thành của Sherlock Holmes, lấy bối cảnh sáu tháng sau cái chết của Thám tử lừng danh Sherlock Holmes. Sau khi mất đi người bạn đồng hành thân thiết, bác sĩ John Watson quyết định từ bỏ sự nghiệp thám tử tư vấn, quay trở lại với chuyên môn y khoa của mình để trở thành người đứng đầu một phòng khám y tế, thay vì giải quyết các vụ án giết người, Watson giờ đây tập trung vào việc giải mã những &quot;bí ẩn y khoa&quot; - những căn bệnh hiếm gặp, khó chẩn đoán mà các bác sĩ thông thường đều bó tay. Tuy nhiên, anh không dùng các phương pháp xét nghiệm truyền thống mà áp dụng kỹ năng quan sát và suy luận kiểu Sherlock Holmes để tìm ra nguyên nhân bệnh lý. Khác với nhiều phiên bản trước đây khi Watson chỉ đóng vai trò &quot;người ghi chép&quot; hay trợ lý, series này đưa anh lên làm nhân vật trung tâm, thể hiện sự độc lập và tài năng thiên bẩm của mình. Phim được so sánh với series y khoa nổi tiếng House M.D. ở chỗ tập trung vào các ca bệnh khó tin, đòi hỏi sự suy luận logic cực cao khiến bộ phim được đánh giá là một làn gió mới cho dòng phim trinh thám - y khoa, đặc biệt dành cho những ai yêu thích vũ trụ Sherlock Holmes nhưng muốn tìm kiếm một góc nhìn khác biệt.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Morris Chestnut","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["华生","华生后记","Watson"]', 1784690324134);
