INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ke-xau-xa-phan-1', 'Những Kẻ Xấu Xa (Phần 1)', 'The Bad Guys: The Series (Season 1)', 'https://phimimg.com/upload/vod/20251107-1/6ecb1b3c30c8aae3773c6445d30cf9dc.jpg', 'https://phimimg.com/upload/vod/20260404-1/5a21922b09faeed04f95aecab795d1b0.jpg', '<p>Băng Kẻ Xấu bước chân vào con đường tội phạm bằng cách nào? Hãy cùng tìm hiểu trong loạt phim tiền truyện hài hước này, lấy bối cảnh trước các bộ phim đình đám.</p>', 'Hoàn Tất (9/9)', 9, 'hoathinh', 'completed', 26, 2025, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 0, '[{"name":"Michael Godere","avatar":""},{"name":"Ezekiel Ajeigbe","avatar":""},{"name":"Raul Ceballos","avatar":""},{"name":"Chris Diamantopoulos","avatar":""},{"name":"Mallory Low","avatar":""},{"name":"Zehra Fazal","avatar":""},{"name":"Patton Oswalt","avatar":""},{"name":"Kate Mulgrew","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Los tipos malos: La serie","Los tipos malos: Malos comienzos","לא רעים בכלל: הפריצה הגדולה","배드 가이즈: 악당들은 변신 중","The Bad Guys: Breaking In","The Bad Guys: The Series"]', 1784690324134);
