INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhung-ke-xau-xa-phan-1', 'Những Kẻ Xấu Xa (Phần 1)', 'The Bad Guys: The Series (Season 1)', 'những kẻ xấu xa (phần 1) the bad guys: the series (season 1) michael godere ezekiel ajeigbe raul ceballos chris diamantopoulos mallory low zehra fazal patton oswalt kate mulgrew los tipos malos: la serie los tipos malos: malos comienzos לא רעים בכלל: הפריצה הגדולה 배드 가이즈: 악당들은 변신 중 the bad guys: breaking in the bad guys: the series', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-phi-khong-giang-vo-duc', 'Hoàng Phi Không Giảng Võ Đức', 'Princess''s Venture', 'https://phimimg.com/upload/vod/20250207-1/9a47bb4459b6a62ee83cca4df32487f2.jpg', 'https://phimimg.com/upload/vod/20250207-1/91c8d6de86de5b446e2aa14c13b68a1a.jpg', '<p>Đường Diệu Tâm tham gia trải nghiệm một trò chơi giải đố với nhiệm vụ cốt lõi là tìm ra bí mật của Tần Vương Ninh Cô Chu. Ngay khi vừa bước vào thế giới game, cô đã bị cuốn vào vòng xoáy của một vụ tráo dâu (thế gả) và trở thành Vương phi của Ninh Cô Chu. Tại Tần Vương phủ, dù đối mặt với muôn vàn khó khăn, cô vẫn kiên quyết tìm cách thấu hiểu con người thật của vị Vương gia này. Để làm được điều đó, Đường Diệu Tâm đã theo chân Ninh Cô Chu vào Đại Yến Học Phủ, dùng sự nhạy bén và khả năng thích nghi tuyệt vời để nhanh chóng khẳng định vị thế. Tại đây, cô kết giao cùng Tô Lạc Thiên ôn nhu lãng tử và Giang Hoa Đồng mang nội tâm kiên cường, tạo thành bộ ba tri kỷ. Đường Diệu Tâm không chỉ tỏa sáng trong các kỳ thi học thuật mà còn dần bóc tách lớp vỏ bọc lạnh lùng để chạm đến nỗi cô đơn và đau khổ của Ninh Cô Chu. Cô phát hiện ra thân mẫu của anh — Vu Tần — từng bị hãm hại, và đó chính là căn nguyên cho sự tàn độc của anh. Đường Diệu Tâm đã cổ vũ Giang Hoa Đồng dũng cảm phản kháng lại cuộc hôn nhân ép buộc của Hoàng hậu, đồng thời giúp bạn mình giành danh hiệu Nguyệt Quang Thần Nữ trong lễ hội Sóc Nguyệt. Tuy nhiên, những hành động nghĩa hiệp này cũng khiến cô trở thành cái gai trong mắt Hoàng hậu và Thái tử.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 21, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngô Quý Phong","avatar":""},{"name":"Kim Lộ Oánh","avatar":""},{"name":"Thôi Húc Vũ","avatar":""},{"name":"Ngô Linh Vy","avatar":""},{"name":"Triệu Sở Hàm","avatar":""},{"name":"Vương Lôi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Huang Fei Ta Bu Jiang Wu De","皇妃她不讲武德"]', 1784690324134);
