INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuc-vang-cua-ngoai', 'Cục Vàng Của Ngoại', 'My Little Grandma', 'https://phimimg.com/upload/vod/20260403-1/8a92b96e2654e74c7ca3beee085e1c18.jpg', 'https://phimimg.com/upload/vod/20260403-1/302beeb411b719a89f3678638ab48fe7.jpg', '<p>Lấy cảm hứng từ những ký ức tuổi thơ ngọt ngào, “Cục Vàng Của Ngoại” kể câu chuyện ấm áp về tình bà cháu trong một xóm nhỏ đầy nghĩa tình. Bà Hậu – người phụ nữ cả đời tần tảo – trở thành chỗ dựa duy nhất của cháu ngoại khi con gái bỏ đi. Dẫu cuộc sống còn nhiều nhọc nhằn, tình thương bà dành cho cháu vẫn trọn vẹn, đưa khán giả trở về những khoảnh khắc đời thường: nụ cười hồn nhiên của trẻ, vòng tay chở che của bà, và sự đùm bọc của hàng xóm. Một bức tranh tuổi thơ bình yên, ấm áp và chan chứa tình người.</p>', 'Full', 1, 'single', 'completed', 36, 2025, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Hồng Đào","avatar":""},{"name":"Hữu Châu","avatar":""},{"name":"Việt Hương","avatar":""},{"name":"Lê Khánh","avatar":""},{"name":"Băng Di","avatar":""},{"name":"Gia Yến","avatar":""},{"name":"Lam Thanh My","avatar":""},{"name":"Thư Đan","avatar":""},{"name":"Hoang Anh Panda","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Cục Vàng Của Ngoại"]', 1784690324134);
