INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thinh-quan-nhap-mong', 'Thỉnh Quân Nhập Mộng', 'Everlasting Love', 'https://phimimg.com/upload/vod/20250505-1/302fd037f83c41ae22c4bc25cc0745ca.jpg', 'https://phimimg.com/upload/vod/20250505-1/83b77b84d849ed07a02019920183aa5b.jpg', '<p>Câu chuyện bắt đầu với Diệp Kim An, một nữ sinh ngành khảo cổ học, trong một lần tham gia khai quật đã vô tình chạm vào một hộp sọ cổ và bị cuốn vào một thế giới cổ đại. Tại đây, cô nhập hồn vào Phong Tri Lê, một &quot;yêu phi&quot; nổi tiếng trong lịch sử, và trở thành vợ của Phong Tri Lê, một vị &quot;bạo quân&quot; lạnh lùng nhưng ẩn chứa nhiều bí mật. Ban đầu, cả hai đều che giấu thân phận và mục đích thật sự, dẫn đến những màn đấu trí đầy kịch tính. Tuy nhiên, qua thời gian, họ dần hiểu và cảm thông cho nhau, phát triển một mối quan hệ đầy lãng mạn và sâu sắc.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 19, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ôn Mạc Ngôn","avatar":""},{"name":"Ngô Kỷ Phong","avatar":""},{"name":"Lưu Giả Hỉ","avatar":""},{"name":"Viên Tử Minh","avatar":""},{"name":"Tùy Danh Dương","avatar":""},{"name":"Trần Hoàn","avatar":""},{"name":"Trương Hán Phương","avatar":""},{"name":"Vương Lệ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["请君入梦"]', 1784690324134);
