INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tinh-yeu-tren-pho-tu-ky-phan-3', 'Tình Yêu Trên Phổ Tự Kỷ (Phần 3)', 'Love On The Spectrum (Season 3)', 'tình yêu trên phổ tự kỷ (phần 3) love on the spectrum (season 3)  amor no espectro: eua láska ve spektru: usa liebe im spektrum: usa el amor en el espectro autista: ee.uu. histoires d''amour et d''autisme : états-unis στο φάσμα του έρωτα: ηπα szerelem az autizmus spektrumban usa l''amore nello spettro usa 러브 온 더 스펙트럼: 미국 amor en el espectro: ee. uu. kjærlighet på spekteret – usa кохання в спектрі: сша love on the spectrum u.s. tình yêu trên phổ tự kỷ love on the spectrum', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-trai-dau', 'Gia Đình Trái Dấu', 'The Opposite Family', 'https://phimimg.com/upload/vod/20251211-1/5e5dddfa6907ecf7ff6efd83331a71ca.jpg', 'https://phimimg.com/upload/vod/20251211-1/b5ed1fbb94055adad30efb0266d4514f.jpg', '<p>Câu chuyện phim xoay quanh gia đình ông Phi (NSƯT Hoàng Hải), một trưởng phòng cấp huyện bất ngờ mất chức và phải nghỉ hưu non sau một cuộc sáp nhập, tinh giản biên chế. Lo sợ vợ con lo lắng và làm thất vọng dòng họ, ông Phi quyết định che giấu sự thật. Tuy nhiên, hàng loạt rắc rối ập đến cùng lúc, đẩy gia đình ông vào tâm bão. Mối quan hệ giữa ông và con trai lớn, Đức (Thừa Tuấn Anh), ngày càng căng thẳng khi ông một mực phản đối chuyện hôn nhân của con. Cùng lúc đó, vợ ông, bà Ánh (NSƯT Kiều Anh), gặp khó khăn với các khoản đầu tư và nợ ngân hàng. Áp lực tài chính từ gia đình ở quê cũng đè nặng lên vai ông. Đỉnh điểm của khủng hoảng là sự xuất hiện của bé Nhi, người được cho là &quot;con rơi&quot; của ông Phi. Sự việc này đã phá vỡ niềm tin và hạnh phúc mà gia đình ông đã xây dựng, buộc ông phải đối mặt với nguy cơ sụp đổ hoàn toàn.</p>', 'Hoàn Tất (33/33)', 33, 'series', 'completed', 20, 2025, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Việt Anh","avatar":""},{"name":"Hồng Diễm","avatar":""},{"name":"Doãn Quốc Đam","avatar":""},{"name":"Lãnh Thanh","avatar":""},{"name":"Quỳnh Kool","avatar":""},{"name":"Anh Thư","avatar":""},{"name":"Quang Thắng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324134);
