INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sarah-millican-bong-hoa-no-muon', 'Sarah Millican: Bông Hoa Nở Muộn', 'Sarah Millican: Late Bloomer', 'https://phimimg.com/upload/vod/20260402-1/6508bb9e6aac69c043169e0030431529.jpg', 'https://phimimg.com/upload/vod/20260402-1/f9040f4c3d585c8df9b33327c3c116bb.jpg', '<p>Khi Sarah Millican còn là một đứa trẻ, cô ấy nhút nhát đến mức &quot;chẳng dám ho hen gì với một con ngỗng&quot; (không dám lên tiếng). Hồi đi học thì lầm lì, ít bạn bè, đến tận năm 16 tuổi vẫn &quot;màn hình phẳng&quot;. Còn bây giờ thì sao? BÂY GIỜ cô ấy cực kỳ ồn ào, vây quanh là những người bạn tốt, sở hữu một &quot;vòng một&quot; nảy nở và sẵn sàng &quot;cà khịa&quot; lũ ngỗng ở khắp mọi nơi. Trong buổi diễn hài độc thoại thứ bảy này, Sarah sẽ cùng khán giả khám phá hành trình lột xác từ cô bé nhút nhát năm xưa thành người phụ nữ tự tin hiện tại. Ngoài ra, cô cũng chia sẻ vô số chuyện &quot;trên trời dưới đất&quot; về những bữa ăn và cả những chuyện thầm kín về &quot;khu vườn bí mật&quot; của phái đẹp.</p>', 'Full', 1, 'single', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sarah Millican","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sarah Millican: Late Bloomer"]', 1784690324134);
