INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sarah-millican-bong-hoa-no-muon', 'Sarah Millican: Bông Hoa Nở Muộn', 'Sarah Millican: Late Bloomer', 'sarah millican: bông hoa nở muộn sarah millican: late bloomer sarah millican sarah millican: late bloomer', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mai-nha-sau-song-sat', 'Mái Nhà Sau Song Sắt', 'Home Behind Bars', 'https://phimimg.com/upload/vod/20260402-1/2d13c3fa8d2fccbfb1e176519280e027.jpg', 'https://phimimg.com/upload/vod/20260402-1/ac2d4574d2670dc58299f9b83e499eb1.jpg', '<p>Trong bức tường lạnh lẽo của một trại giam nữ, Tae Jeo (Song Ji Hyo) đã làm cai ngục suốt 15 năm. Cô quen với sự im lặng, những ánh nhìn dè chừng và nhịp sống khép kín nơi đây. Mọi thứ tưởng như không thể lay chuyển cho đến khi một nữ phạm nhân mới chuyển đến, mang theo cô con gái tên Do Eun (Do Yeong Seo) – người Tae Jeo được giao trông coi.
 Giữa những quy tắc nghiêm ngặt, mối quan hệ kỳ lạ giữa người giám ngục và cô gái ấy dần hình thành. Tae Jeo bắt đầu nhận ra những góc tối trong chính công việc mình gắn bó, còn Do Eun lại tìm thấy nơi cô một hình ảnh khác của tình mẫu tử. Những bí mật về quá khứ, về người mẹ đang chịu án, bắt đầu hé lộ, đẩy cả hai vào vòng xoáy cảm xúc giữa trách nhiệm, tội lỗi và sự cảm thông.</p>', 'Full', 1, 'single', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Song Ji-hyo","avatar":""},{"name":"Do Yeong-seo","avatar":""},{"name":"Ok Ji-young","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["UN HOGAR TRAS LAS REJAS","만남의 집"]', 1784690324134);
