INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dinh-dinh-phuong-hoang-dai', 'Đình Đình Phượng Hoàng Đài', 'The Towering Phoenix Mountain (The Graceful Phoenix Terrace)', 'https://phimimg.com/upload/vod/20260402-1/d659d7653cec7125dace534ae9ea5d8c.jpg', 'https://phimimg.com/upload/vod/20260402-1/97a726f84b6cec4f1a24a82182d02a24.jpg', '<p>Ba người thành đạt xuất thân từ Thành Châu, Cam Túc cùng lúc nhận được thiệp mời tham dự đại hội Hương Hiền sắp được tổ chức tại quê nhà. Họ trở lại quê hương sau nhiều năm xa cách. Khi họ chuẩn bị nhân cơ hội này mà thể hiện vẻ vang thì một câu chuyện cũ đã bị chôn vùi suốt nhiều năm bất ngờ bị khơi lại. Một sự cố xảy ra trước kỳ thi đại học năm ấy đã thay đổi vận mệnh của mỗi người. Giờ đây, lời hứa, trách nhiệm và sự gánh vác một lần nữa được đặt trước mặt họ…</p>', 'Full', 1, 'single', 'completed', 20, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Thu Ca","avatar":""},{"name":"Trần Hữu Vượng","avatar":""},{"name":"Vương Hãn Bang","avatar":""},{"name":"Văn Đông Tuấn","avatar":""},{"name":"Thang Thanh Tùng","avatar":""},{"name":"An Hiểu Tuyền","avatar":""},{"name":"Quách Lập Khôn","avatar":""},{"name":"Đỗ Nham","avatar":""},{"name":"Từ Dịch Cảnh","avatar":""},{"name":"Quách Vũ Kiệt","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The.Towering.Phoenix.Mountain","亭亭凤凰台"]', 1784690324134);
