INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chay-dua-voi-thoi-gian', 'Chạy Đua Với Thời Gian', 'Strike Against Time', 'https://phimimg.com/upload/vod/20260402-1/477bc4f41e524db3a103a91a1a89d1ca.jpg', 'https://phimimg.com/upload/vod/20260402-1/8aa7363a05d7ef8533a91d5f1b152aa9.jpg', '<p>Sau khi phá thành công một vụ trọng án xuyên quốc gia, hai cảnh sát hình sự Thẩm Gia Minh và Ngô Diễm lại bất ngờ bị cuốn vào một chuỗi án mạng liên hoàn. Cái chết bí ẩn của Tôn Thành Cương và Khổng Tư Tư dần hé lộ những manh mối, tất cả đều hướng về hệ thống hiến tạng của một bệnh viện. Điều phối viên Mi Phương, bác sĩ Mã Ngọc Như, cùng hai anh em La Vĩnh Quân đang chờ ghép tạng đều bị cuốn vào vòng xoáy này. Trong quá trình truy tìm hung thủ, nạn nhân thứ ba suýt bị sát hại bằng cách đẩy từ trên cao xuống. Nhưng điều đáng sợ là kẻ sát nhân thật sự lại ở ngay trước mắt họ.</p>', 'Full', 1, 'single', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Thao","avatar":""},{"name":"Ngụy Tiểu Hoan","avatar":""},{"name":"Giang Giai Đồng","avatar":""},{"name":"Lý Giang Dao","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["STRIKE AGAINST TIME","竞时出击"]', 1784690324134);
