INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-nguoi-duyen-ma-nham-mak-yeu-luon', 'Tình Người Duyên Ma: Nhắm Mak Yêu Luôn', 'Nak Loves Mak Sooo Much!', 'https://phimimg.com/upload/vod/20260401-1/82f35770a851843be4c394f5b68a7328.jpg', 'https://phimimg.com/upload/vod/20260401-1/d0e1baf8012aa148596077958e758b42.jpg', '<p>Lấy cảm hứng từ truyền thuyết dân gian Thái Lan về hồn ma Mae Nak, Tình Người Duyên Ma: Nhắm Mak Yêu Luôn kể câu chuyện tình vượt thời gian giữa nàng Nak và chàng Mak. Xuyên không đến 200 năm sau, Nak bất ngờ được vào vai nữ chính trong chính bộ phim về truyền thuyết của mình. Tình cờ thay, vai nam chính lại được thủ bởi Mak - lúc này đã là một nam diễn viên nổi tiếng toàn quốc. Ở đây, Nak phải chinh phục lại trái tim Mak trong vòng 30 ngày mà không được dùng đến ma lực, để có thể ở bên anh trọn đời trọn kiếp.</p>', 'Full', 1, 'single', 'completed', 33, 2025, 'Vietsub', 'FHD', 'Thái Lan', 1, '[{"name":"Narilya Gulmongkolpech","avatar":""},{"name":"Perawat Sangpotirat","avatar":""},{"name":"Choosak Iamsuk","avatar":""},{"name":"Pongsak Pongsuwan","avatar":""},{"name":"Petchtai Wongkamlao","avatar":""},{"name":"Passakorn Ponlaboon","avatar":""},{"name":"Rusameekae Fagerlund","avatar":""},{"name":"Chookiat Iamsook","avatar":""},{"name":"Wongsatorn Somsri","avatar":""},{"name":"Chonpipat Choosang","avatar":""},{"name":"Mongkol Saaadboonyapat","avatar":""},{"name":"Janphen Khongprakob","avatar":""},{"name":"Werawat J","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Nak Rak Mak Mak Mak","นากรักมาก ม๊ากมาก"]', 1784690324134);
