INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-tuong', 'Thiên Tướng', 'Divine Manifestation', 'https://phimimg.com/upload/vod/20251016-1/2a923fb8548dce03226efe8829acbf0e.jpg', 'https://phimimg.com/upload/vod/20251016-1/c967089ca411a66fe76ef9f47090a34d.jpg', '<p>Đinh Hiểu - người từng bị coi là &quot;phế tương&quot; và phải làm công việc khiêng quan tài trong suốt tám năm. Cho đến khi cậu thức tỉnh năng lực “tương lực” để bảo vệ thế giới khỏi linh sát khiến hỗn loạn, đồng thời đi tìm cách cứu em gái mắc bệnh bí ẩn. Cũng trong quá trình đó, Đinh Hiểu bị cuốn vào một âm mưu lớn hơn liên quan đến số phận nhân loại.</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["天相","Divine Manifestation","The Divine Manifestation"]', 1784690324134);
