INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chitose-trong-chai-ramune', 'Chitose Trong Chai Ramune', 'Chitose Is In The Ramune Bottle', 'https://phimimg.com/upload/vod/20251008-1/8f77258dbfcdfbc106793331faabb124.jpg', 'https://phimimg.com/upload/vod/20251008-1/20bb877d15cccb1784990a3e5033d1b1.jpg', '<p>Saku Chitose, được mệnh danh là “tên sở khanh của lớp 5”, nổi tiếng khắp trường dù thường xuyên bị chỉ trích trên mạng. Khi bước vào năm hai, thầy giáo giao cho cậu một nhiệm vụ đặc biệt: thuyết phục Kenta Yamazaki, một học sinh sống khép kín và căm ghét Saku, quay lại lớp học. Giờ đây, để bảo toàn hình tượng hoàn hảo của mình, Saku buộc phải tìm cách giành được lòng tin của Kenta — dù điều đó có thể khiến cậu đối mặt với chính những mâu thuẫn trong con người mình.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 244, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shogo Sakata","avatar":""},{"name":"Manaka Iwami","avatar":""},{"name":"Hina Youmiya","avatar":""},{"name":"Rumi Okubo","avatar":""},{"name":"Ikumi Hasegawa","avatar":""},{"name":"Chika Anzai","avatar":""},{"name":"Yohei Azakami","avatar":""},{"name":"Masaya Miyazaki","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chitose-kun wa Ramune Bin no Naka","チラムネ","ちとせくんはラムネびんのなか","Chitose-kun ha Ramune Bin no Naka","Chiramune","Chitose Kun wa Ramunebin no Naka","Chitose kun ha Ramune Bin no Naka","Chitose Kun wa Ramune Bin no Naka","弾珠汽水瓶裡的千歲同學","Chitose is in Ramune Bottle","千歳くんはラムネ瓶のなか"]', 1784690324134);
