INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gon-song', 'Gợn Sóng', 'Ripple', 'https://phimimg.com/upload/vod/20260401-1/876223a3e84186289452ab4ee8c84d88.jpg', 'https://phimimg.com/upload/vod/20260401-1/301066264447325aff98099e393448d7.jpg', '<p>Giữa thành phố New York hoa lệ, bốn người xa lạ cùng đối mặt với những thử thách nghiệt ngã của cuộc đời. Những con đường riêng biệt của họ tình cờ giao nhau theo những cách không ngờ tới, thay đổi số phận của mỗi người mãi mãi.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 26, 2025, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Frankie Faison","avatar":""},{"name":"Julia Chan","avatar":""},{"name":"Ian Harding","avatar":""},{"name":"Sydney Agudong","avatar":""},{"name":"Isabella Astbury","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ripple"]', 1784690324134);
