INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gon-song', 'Gợn Sóng', 'Ripple', 'gợn sóng ripple frankie faison julia chan ian harding sydney agudong isabella astbury ripple', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sivis-tieng-vong-cua-anh-hung', 'SI-VIS: Tiếng Vọng Của Anh Hùng', 'SI-VIS: The Sound Of Heroes', 'https://phimimg.com/upload/vod/20251012-1/025a04f41e2e0b7c2f1cec6df4d3ecb6.jpg', 'https://phimimg.com/upload/vod/20251012-1/f6e14e937f422646d867cc63535bc9d6.jpg', '<p>SI-VIS là một nhóm nhạc hỗn hợp nam nữ do Yosuke dẫn dắt, đang làm chấn động làng nhạc toàn cầu với giọng hát và màn trình diễn không ai sánh kịp. Tuy nhiên, họ thực ra là những anh hùng cải trang, âm thầm chiến đấu chống lại các thế lực bí ẩn đang đe dọa thế giới. Năng lượng mà khán giả tạo ra trong các buổi biểu diễn được họ chuyển hóa thành sức mạnh chiến đấu. May mắn thay, trong mắt công chúng, những trận chiến ấy chỉ giống như các buổi hòa nhạc bình thường, giúp họ giữ kín thân phận thật của mình.</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 13, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Nobunaga Shimazaki","avatar":""},{"name":"Akari Kito","avatar":""},{"name":"Daisuke Namikawa","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Soma Saito","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["希维斯：英雄之声","シーヴィス","SIーVIS： The Sound of Heroes","SI-VIS: The Sound of Heroes"]', 1784690324134);
