INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ao-no-miburo-phan-2', 'Ao no Miburo (Phần 2)', 'Blue Miburo (Season 2)', 'https://phimimg.com/upload/vod/20251223-1/f08247a88309e8566077f19389d474a5.jpg', 'https://phimimg.com/upload/vod/20251223-1/f7807e71d414227b43d57cdf1a5fe679.jpg', '<p>Lấy bối cảnh tại Kyoto vào năm 1863, câu chuyện theo chân Nio — một thiếu niên lương thiện, tử tế và luôn hết lòng quan tâm đến gia đình. Tuy nhiên, ẩn sâu bên trong cậu là một khát vọng rực cháy công lý. Kể từ khoảnh khắc tình cờ gặp gỡ Hijikata Toshizou và Okita Souji, thành viên của nhóm lãng nhân bị người đời ghét bỏ mang tên Miburo, cuộc đời cậu đã rẽ sang một hướng đi mới xanh thẳm và rõ ràng hơn. Nio cùng với những người đàn ông mang trái tim dũng cảm và chân thành, đã cùng nhau bước tới con đường chính nghĩa, với ý chí xanh thẳm khắc ghi trong tim!</p>', 'Tập 14', 24, 'hoathinh', 'ongoing', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ao no Miburo","푸른미부로","青之壬生浪 第二季 芹澤暗殺篇","The Blue Wolves of Mibu","青のミブロ"]', 1784690324134);
