INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-qua-ho-so-den-phan-1', 'Cô Gái Quạ: Hồ Sơ Đen (Phần 1)', 'The Crow Girl (Season 1)', 'https://phimimg.com/upload/vod/20260319-1/befa25f8067c9a8b98fde2b9c187fe30.jpg', 'https://phimimg.com/upload/vod/20260319-1/97cca1de39ab158cd9c2b90c13252f6c.jpg', '<p>Thanh tra cao cấp Jeanette Kilburn và nhà tâm lý học lỗi lạc, Tiến sĩ Sophia Craven, đã hợp sức để truy lùng kẻ sát nhân chuyên nhắm vào những nam thanh niên. Cuộc điều tra đã đưa Jeanette và Sophia dấn thân vào một thế giới nguy hiểm của những vụ lạm dụng và giết người trong quá khứ.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Eve Myles","avatar":""},{"name":"Katherine Kelly","avatar":""},{"name":"Clara Rugaard","avatar":""},{"name":"Elliot Edusah","avatar":""},{"name":"Dougray Scott","avatar":""},{"name":"Victoria Hamilton","avatar":""},{"name":"Raphael Sowole","avatar":""},{"name":"Chloe Sweetlove","avatar":""},{"name":"Michael Lumsden","avatar":""},{"name":"Karen Ascoe","avatar":""},{"name":"Isabella Astbury","avatar":""},{"name":"Roger Jean Nsengiyumva","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Crow Girl"]', 1784690324134);
