INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gui-em-nguoi-bat-tu-phan-3', 'Gửi Em, Người Bất Tử (Phần 3)', 'To Your Eternity (Season 3)', 'gửi em, người bất tử (phần 3) to your eternity (season 3) reiji kawashima kenjiro tsuda tomori kusunoki megumi han yumiri hanamori aya uchida fukushi ochiai chiharu sawashiro aoi koga shouto kashii rumi okubo shizuka itoh shin-ichiro miki tasuku hatanaka fumetsu no anata e para a sua eternidade uma vida imortal 致不灭的你 para ti, el inmortal 不滅のあなたへ 第2シリーズ fumetsu no anata e season 2 إلى أبديتك 給不滅的你 to you, the immortal 不滅のあなたへ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-nhu-anh-duong-ruc-ro', 'Tôi Như Ánh Dương Rực Rỡ', 'Shine On Me', 'https://phimimg.com/upload/vod/20251223-1/215c129b7c2ecf488d281a9f09b54118.jpg', 'https://phimimg.com/upload/vod/20251223-1/eade202f69bdcbf3c57b064362923a67.jpg', '<p>Phim chuyển thể từ tiểu thuyết cùng tên của Cố Mạn, kể về câu chuyện tình yêu lãng mạn và hành trình trưởng thành. Bác sĩ phẫu thuật Lâm Dữ Sâm buộc phải từ bỏ sự nghiệp yêu thích sau một tai nạn, chuyển sang lĩnh vực kinh doanh. Trong quá trình tiếp xúc với cô gái có tính cách vui vẻ hòa đồng Nhiếp Hi Quang, hai người dần gỡ bỏ hiểu lầm và nảy sinh tình cảm. Tình yêu và sự ủng hộ vô điều kiện của Lâm Dữ Sâm giúp Nghê Hi Quang vượt qua mối tình đơn phương thời đại học. Cuối cùng, cả hai cùng nhau vượt qua mọi trở ngại, trưởng thành và tìm thấy hạnh phúc bên nhau.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tống Uy Long","avatar":""},{"name":"Triệu Kim Mạch","avatar":""},{"name":"Lâm Y Luân","avatar":""},{"name":"Lai Vĩ Minh","avatar":""},{"name":"Bạch Băng Khả","avatar":""},{"name":"Phạm Thi Nhiên","avatar":""},{"name":"Ngô Khởi Hoa","avatar":""},{"name":"Khổng Lệnh Mỹ","avatar":""},{"name":"Đồng Lôi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["驕陽似我","Jiao Yang Si Wo","Sinarilah Aku","교양사아: 날 닮은 태양","Солнце, похожее на меня","ดั่งตะวันฉายฉาน","Shine on Me","骄阳似我"]', 1784690324134);
