INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('toi-nhu-anh-duong-ruc-ro', 'Tôi Như Ánh Dương Rực Rỡ', 'Shine On Me', 'tôi như ánh dương rực rỡ shine on me tống uy long triệu kim mạch lâm y luân lai vĩ minh bạch băng khả phạm thi nhiên ngô khởi hoa khổng lệnh mỹ đồng lôi 驕陽似我 jiao yang si wo sinarilah aku 교양사아: 날 닮은 태양 солнце, похожее на меня ดั่งตะวันฉายฉาน shine on me 骄阳似我', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('180-ngay-tai-khoi-dong-ke-hoach', '180 Ngày Tái Khởi Động Kế Hoạch', 'Me And My Family', 'https://phimimg.com/upload/vod/20250219-1/58716fdf5fe3f5f6a3ba0b5026981954.jpg', 'https://phimimg.com/upload/vod/20250219-1/f004fb2636ab674d7cee4211ca6534e6.jpg', '<p>Cố Vân Tô 28 tuổi (do Châu Vũ Đồng thủ vai) cùng lúc bị thất tình và thất nghiệp bất đắc dĩ lựa chọn về nhà và dự định nương nhờ mẹ mình là Ngô Lệ Mai (do Ngô Việt thủ vai), kết quả cô phát hiện người mẹ 48 tuổi đột nhiên tái hôn vậy mà mang thai khi tuổi đã cao. Cố Vân Tô vốn có ý tốt như mình muốn để giúp đỡ bảo hộ người mẹ lớn tuổi đang mang thai dù không hề chuẩn bị trước tình huống này, cô ấy sống cùng một mái nhà với người mẹ dũng cảm, người cha dượng không quen biết và người em trai không có quan hệ huyết thống. Câu chuyện dở khóc dở cười, ấm áp và chữa lành về tình thân được trình diễn giữa hai bên. Trong quá trình này, Cố Vân Tô đã làm quen với vị bác sĩ điều trị của mẹ là Từ Văn Bân (do Lưu Sướng thủ vai), cả hai từ kẻ thù trở thành cộng sự của nhau. Hai mẹ con cùng nhau trải qua 180 ngày bồi sản đặc biệt, Cố Vân Tô dần dần cảm nhận được sự nương tựa và trân quý sâu sắc của mẹ, Ngô Lệ Mai cũng có trải nghiệm thực tế về con gái mình như một “áo bông nhỏ (ám chỉ con gái của mình cũng rất ấm áp)”. Cố Vân Tô đã trải qua tâm lý đau bụng sinh và tìm ra hướng đi mới trong sự nghiệp và cuộc sống cùng với tình thân gia đình và tình yêu ngọt ngào, hai mẹ con cũng ngày càng hiểu nhau và hỗ trợ lẫn nhau, nhận thức được sức mạnh của tình thân.</p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Châu Vũ Đồng","avatar":""},{"name":"Ngô Việt","avatar":""},{"name":"Lưu Sướng","avatar":""},{"name":"Cảnh Lạc","avatar":""},{"name":"Hà Lạc Lạc","avatar":""},{"name":"Trần Minh Hạo","avatar":""},{"name":"Chu Nhân","avatar":""},{"name":"Thẩm Mộng Thần","avatar":""},{"name":"Ô Lập Bằng","avatar":""},{"name":"Hàn Mạch","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["180天陪产计划","180 Days, A New Beginning","Me And My Family","180天重启计划"]', 1784690324134);
