INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-co-khi', 'Cô Gái Cơ Khí', 'VIRGIN PUNK Clockwork Girl', 'https://phimimg.com/upload/vod/20260329-1/a2e6bac24f6037fca9c62ad0ee9a4921.jpg', 'https://phimimg.com/upload/vod/20260329-1/371ac116f4e204c5897a079d471462a8.jpg', '<p>Trong một thế giới tàn khốc, Ubu Kamigori mưu sinh bằng nghề săn tiền thưởng, chuyên truy quét những tên tội phạm nguy hiểm. Thế nhưng một ngày nọ, chờ đợi cô ngay tại nhà lại là người đàn ông có chung một quá khứ đen tối với mình — Mr. Elegance. Kể từ giây phút đó, định mệnh của cô bắt đầu rơi vào vòng xoáy đảo lộn.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Saki Miyashita","avatar":""},{"name":"Katsuyuki Konishi","avatar":""},{"name":"Taku Yashiro","avatar":""},{"name":"Rui Tanabe","avatar":""},{"name":"Norio Wakamoto","avatar":""},{"name":"Fuka Izumi","avatar":""},{"name":"Sumire Uesaka","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["维珍朋克：发条女孩","纯洁庞克：发条少女","处女朋克：发条女孩","纯净朋克：发条少女","处女朋克：发条少女","ヴァージン・パンク Clockwork Girl"]', 1784690324134);
