INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-quyen-phong-bao', 'Kỳ Quyền Phong Bạo', 'Hybrid Storm', 'https://phimimg.com/upload/vod/20260320-1/c02f4635e698e640d38f94b80291f8ea.jpg', 'https://phimimg.com/upload/vod/20260320-1/88ef81c52274c8b1824b2dee6ac5b2c5.jpg', '<p>Một nhân viên ICAC điều tra vụ án buôn lậu và bắt giữ một cựu võ sĩ quyền Anh. Nhưng rồi chính anh lại bị điều tra khi những khoản tiền hối lộ bí ẩn xuất hiện trong tài khoản của bố mình.</p>', 'Full', 1, 'single', 'completed', 19, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Trịnh Gia Dĩnh","avatar":""},{"name":"Huỳnh Tông Trạch","avatar":""},{"name":"Hồ Hồng Quân","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["棋拳風暴"]', 1784690324134);
