INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thap-bang', 'Tháp Băng', 'The Ice Tower', 'https://phimimg.com/upload/vod/20260326-1/6c56ca0fcc4a17f5c5284bd810c82983.jpg', 'https://phimimg.com/upload/vod/20260326-1/3c2719398ee1ae5a3ed2680058d9b908.jpg', '<p>Jeanne, một cô bé mồ côi 15 tuổi, chứng kiến cảnh quay cho bộ phim chuyển thể từ truyện cổ tích Nữ hoàng Tuyết, và cô bé bị cuốn hút bởi ngôi sao của bộ phim, Cristina, một nữ diễn viên bí ẩn và quyến rũ không kém gì Nữ hoàng mà cô thủ vai.</p>', 'Full', 1, 'single', 'completed', 20, 2025, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Marion Cotillard","avatar":""},{"name":"Clara Pacini","avatar":""},{"name":"August Diehl","avatar":""},{"name":"Marine Gesbert","avatar":""},{"name":"Lila-Rose Gilberti","avatar":""},{"name":"Gaspar Noé","avatar":""},{"name":"Dounia Sichov","avatar":""},{"name":"Valentina Vezzoso","avatar":""},{"name":"Cassandre Louis Urbain","avatar":""},{"name":"Aurélia Petit","avatar":""},{"name":"Raphael Reboul","avatar":""},{"name":"Carmen Haidacher","avatar":""},{"name":"Wilhelm Bonnelle","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["La Reine des neiges","Der Eisturm","Wieża z lodu","La torre de hielo","La Tour de glace"]', 1784690324134);
