INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('a-town-called-purgatory', 'A Town Called Purgatory', 'A Town Called Purgatory', 'https://phimimg.com/upload/vod/20260326-1/f0ede4b0e22add78617378a9633268e2.jpg', 'https://phimimg.com/upload/vod/20260326-1/597c008646a420cf9a0174f2e8333259.jpg', '<p>Trong đống tro tàn của Nội chiến, hai tay súng dày dạn kinh nghiệm - một thuộc Liên bang, một thuộc Liên minh miền Nam - truy đuổi một băng đảng vào một thị trấn ma ám với quá khứ nhuốm máu. Nhưng không chỉ có những tên tội phạm ẩn náu ở Địa ngục. Một thứ gì đó cổ xưa. Một thứ gì đó tà ác. Và nó muốn trả thù. Hãy sẵn sàng, kẻ tội lỗi - chuyến đi này sẽ thẳng tiến xuống địa ngục.</p>', 'Full', 1, 'single', 'completed', 37, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Matt Servitto","avatar":""},{"name":"Jeff Ricketts","avatar":""},{"name":"Ken Arnold","avatar":""},{"name":"Dan De Luca","avatar":""},{"name":"Maria Lohn","avatar":""},{"name":"Kevin Jiggetts","avatar":""},{"name":"Claudius von Stolzmann","avatar":""},{"name":"Sam Kozeluh","avatar":""},{"name":"Zach Steffey","avatar":""},{"name":"Florentino Gregorio","avatar":""},{"name":"Oliver Kasiske","avatar":""},{"name":"Cat Jimenez","avatar":""},{"name":"Monica Gregorio","avatar":""},{"name":"Marco Valenta","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["A Town Called Purgatory"]', 1784690324134);
