INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-troi-day-cua-ma-ca-rong', 'Sự trỗi dậy của ma cà rồng', 'Dracula: Rise of the Vampire', 'https://phimimg.com/upload/vod/20260326-1/33482b1fd539cbee5672474925803f34.jpg', 'https://phimimg.com/upload/vod/20260326-1/d321def2f1bac54ec93740c0dcd3fc2c.jpg', '<p>Khi một giáo phái thờ quỷ quyết tâm hồi sinh Bá tước Dracula huyền thoại gây ra một vụ thảm sát đẫm máu trong một nhà thờ ở London, cựu thám tử bị thất sủng, Gabriel Lee, phải trở lại nhiệm vụ cùng với người cộng sự cũ để chiến đấu với thây ma và ngăn chặn ngày tận thế ma cà rồng. Kết hợp giữa kinh dị và hành động hiện đại với kịch tính hấp dẫn và vô số nhân vật kinh điển, Dracula: Rise Of The Vampire mở ra một chương mới trong dòng phim kinh dị Anh Quốc đồng thời mang đến một sự tri ân sâu sắc đối với các tác phẩm kinh điển của Hammer.</p>', 'Full', 1, 'single', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Eileen Daly","avatar":""},{"name":"Tayah Kansik","avatar":""},{"name":"Emma Fletcher","avatar":""},{"name":"Dean Meadows","avatar":""},{"name":"Nathan Head","avatar":""},{"name":"Pauline Peart","avatar":""},{"name":"Kurt Dirt","avatar":""},{"name":"Peter Jakeson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Dracula: Rise of the Vampire"]', 1784690324134);
