INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha', 'Ngôi Nhà', 'The Home', 'https://phimimg.com/upload/vod/20260326-1/acf92701685885eafe05628fcb84f107.jpg', 'https://phimimg.com/upload/vod/20260326-1/a66009e6bd6e1e96202f475775ec4863.jpg', '<p>Một người đàn ông gặp nhiều rắc rối bắt đầu làm việc tại một viện dưỡng lão và nhận ra rằng cư dân và người chăm sóc ở đó đang che giấu những bí mật đen tối. Khi điều tra tòa nhà và tầng bốn bị cấm, anh bắt đầu phát hiện ra những mối liên hệ với quá khứ và tuổi thơ của chính mình khi còn là một đứa trẻ mồ côi.</p>', 'Full', 1, 'single', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Pete Davidson","avatar":""},{"name":"John Glover","avatar":""},{"name":"Mugga","avatar":""},{"name":"Adam Cantor","avatar":""},{"name":"Bruce Altman","avatar":""},{"name":"Denise Burse","avatar":""},{"name":"Stuart Rudin","avatar":""},{"name":"Ethan Phillips","avatar":""},{"name":"Nathalie Schmidt","avatar":""},{"name":"Mary Beth Peil","avatar":""},{"name":"Victor Williams","avatar":""},{"name":"Marilee Talkington","avatar":""},{"name":"Jessica Hecht","avatar":""},{"name":"Michael Donaldson","avatar":""},{"name":"Cali DeMonaco","avatar":""},{"name":"Linder Sutton","avatar":""},{"name":"Jagger Nelson","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Home","Наглядач","老詭之家","Domov","Mājas","The Home"]', 1784690324134);
