INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-chay-ky-uc', 'Dòng Chảy Ký Ức', 'The Chronology of Water', 'https://phimimg.com/upload/vod/20260326-1/1b22b469c0a22cceb79aa5a796d3b746.jpg', 'https://phimimg.com/upload/vod/20260326-1/7e465fcbc939c48190b78c3b644f5146.jpg', '<p>Một nữ vận động viên bơi lội mang học bổng dần đối diện với tuổi thơ đầy tổn thương và những ký ức đau đớn, trải qua các mối quan hệ độc hại và lạc lối trong cuộc sống trước khi tìm thấy sự chữa lành và tiếng nói của bản thân thông qua việc viết lách.</p>', 'Full', 1, 'single', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Imogen Poots","avatar":""},{"name":"Thora Birch","avatar":""},{"name":"Jim Belushi","avatar":""},{"name":"Tom Sturridge","avatar":""},{"name":"Earl Cave","avatar":""},{"name":"Michael Epp","avatar":""},{"name":"Charlie Carrick","avatar":""},{"name":"Susannah Flood","avatar":""},{"name":"Kim Gordon","avatar":""},{"name":"Esmé Creed-Miles","avatar":""},{"name":"Jeremy Ang Jones","avatar":""},{"name":"Peter Rundle","avatar":""},{"name":"Eleanor Hahn","avatar":""},{"name":"Anna Wittowsky","avatar":""},{"name":"Georgie Dettmer","avatar":""},{"name":"Marlēna Sniega","avatar":""},{"name":"Esme Allen","avatar":""},{"name":"Jeffre","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["水物语","流年似水","숨을 참던 나날","Vandens chronologija","The Chronology of Water"]', 1784690324134);
