INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-manh-liet', 'Tình Yêu Mãnh Liệt', 'Tere Ishk Mein', 'https://phimimg.com/upload/vod/20260326-1/f3c2638e4549b151fbe270866cf7340e.jpg', 'https://phimimg.com/upload/vod/20260326-1/e91efa1408217c4d6dbdc7fc42f7fcb6.jpg', '<p>Câu chuyện tình yêu mãnh liệt của Shankar và Mukti diễn ra trên nền khung cảnh Benaras, khám phá sự buông bỏ và chuyển hóa thông qua một mối tình say đắm, chữa lành, làm tổn thương và thay đổi họ.</p>', 'Full', 1, 'single', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Dhanush","avatar":""},{"name":"Kriti Sanon","avatar":""},{"name":"Prakash Raj","avatar":""},{"name":"Tota Roy Chowdhury","avatar":""},{"name":"Priyanshu Painyuli","avatar":""},{"name":"Paramvir Singh Cheema","avatar":""},{"name":"Vineet Kumar Singh","avatar":""},{"name":"Mohammed Zeeshan Ayyub","avatar":""},{"name":"Sushil Dahiya","avatar":""},{"name":"Chittaranjan Tripathy","avatar":""},{"name":"Jaya Bhattacharya","avatar":""},{"name":"Ashish Verma","avatar":""},{"name":"Viren Barman","avatar":""},{"name":"Kamal Batra","avatar":""},{"name":"Shivraj Walveka","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Tere Ishq Mein","तेरे इश्क़ में"]', 1784690324134);
