INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chau-bia-gin-cuoi', 'Chầu Bia Gin Cuối', 'The Last Beergin', 'https://phimimg.com/upload/vod/20260327-1/c0bb1afd6e2926d120be9978d30d552c.jpg', 'https://phimimg.com/upload/vod/20260327-1/6860b552a98416c94c7017495af42425.jpg', '<p>Cuộc đời của 5 người lạ mặt tình cờ giao nhau tại một cửa hàng tiện lợi: Hilo – một người đàn ông của gia đình nhưng đang tìm cách trốn chạy khỏi chính tổ ấm của mình; RG – một người đàn ông đang đứng trước những ngã rẽ cuộc đời; Tere – một người vợ mệt mỏi vì phải chăm sóc người chồng tàn tật; Sandy – một cô nàng tiểu thư kiêu kỳ với những rắc rối vụn vặt; và Isaac – một chàng trai trẻ đem lòng yêu Sandy nhưng lại hoàn toàn vô hình trong mắt cô.</p>', 'Full', 1, 'single', 'completed', 32, 2025, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"JC Santos","avatar":""},{"name":"Xyriel Manabat","avatar":""},{"name":"Zaijian Jaranilla","avatar":""},{"name":"Cherry Pie Picache","avatar":""},{"name":"Pepe Herrera","avatar":""},{"name":"Mercedes Cabral","avatar":""},{"name":"Nikki Valdez","avatar":""},{"name":"Soliman Cruz","avatar":""},{"name":"Ketchup Eusebio","avatar":""},{"name":"Jojit Lorenzo","avatar":""},{"name":"Miggy Jimenez","avatar":""},{"name":"Temi Cruz Abad - Dup","avatar":""},{"name":"Paula Biluan","avatar":""},{"name":"Mischa Clark","avatar":""},{"name":"Carl Barreiro","avatar":""},{"name":"EJ Barreiro","avatar":""},{"name":"Rober","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Last Beergin"]', 1784690324134);
