INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tojima-muon-tro-thanh-kamen-rider-toujima-tanzaburou-wa-kamen-rider-ni-naritai', 'Tojima Muốn Trở Thành Kamen Rider (Toujima Tanzaburou wa Kamen Rider ni Naritai)', 'Tojima Wants to Be a Kamen Rider', 'https://phimimg.com/upload/vod/20251012-1/713fa72d94ec3ccc5d50d8498aba149d.jpg', 'https://phimimg.com/upload/vod/20251012-1/ab37bc050815973d60ffa23caf1008b6.jpg', '<p>Ngay cả khi đã bước sang tuổi 40, Tojima Tanzaburo vẫn tha thiết muốn trở thành một Kamen Rider. Đúng lúc giấc mơ tưởng chừng như không bao giờ thành hiện thực, anh lại vướng vào một loạt vụ cướp khét tiếng lấy cảm hứng từ Shocker... Shibata Yokusaru, tác giả của Air Master và 81 Diver, kể về câu chuyện của những người trưởng thành yêu thích Kamen Rider quá mức, và bắt đầu chơi trò giả vờ... thật!</p>', 'Tập 24', 24, 'hoathinh', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Katsuyuki Konishi","avatar":""},{"name":"Ai Kayano","avatar":""},{"name":"Kenichi Suzumura","avatar":""},{"name":"Soma Saito","avatar":""},{"name":"Fairouz Ai","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Tōjima Tanzaburō wa Kamen Rider ni Naritai","Tojima Tanzaburo Wants to Be a Masked Rider","Tôjima Tanzaburô wa Kamen Raidâ ni Naritai","Toujima Tanzaburou wa Kamen Rider ni Naritai","Tanzaburo Tojima Wants to Be a Kamen Rider","東島丹三郎は仮面ライダーになりたい"]', 1784690324134);
