INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-giet-nguoi-hoan-hao', 'Kẻ giết người hoàn hảo', 'The Perfect Killer', 'https://phimimg.com/upload/vod/20260312-1/24916eb896b98b9fe71f61befcd594df.jpg', 'https://phimimg.com/upload/vod/20260312-1/13c1fc6c20ea92d8d9ebc6c10eeaeb8e.jpg', '<p>Sau khi cha của một cô gái tuổi teen bị giết bởi một kẻ gọi điện thoại lạ mặt giả giọng cô, cô và mẹ kế nghi ngờ rằng ai đó thân thiết với họ đứng sau hành động độc ác này.</p>', 'Full', 1, 'single', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Kirsten Comerford","avatar":""},{"name":"David Pinard","avatar":""},{"name":"JaNae Armogan","avatar":""},{"name":"Sayla de Goede","avatar":""},{"name":"Erica Deutschman","avatar":""},{"name":"Jean Paul Najm","avatar":""},{"name":"Lora Burke","avatar":""},{"name":"Tonjha Richardson","avatar":""},{"name":"Tomas Chovanec","avatar":""},{"name":"Laura Provenzano","avatar":""},{"name":"Ben Steele Caldwell","avatar":""},{"name":"Jason Reilly","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Perfect Killer"]', 1784690324134);
