INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-gezhi', 'Thị Trấn Gezhi', 'Gezhi Town', 'https://phimimg.com/upload/vod/20260312-1/cabd063d2e834fbc2d0307a332abce8c.jpg', 'https://phimimg.com/upload/vod/20260312-1/0de21b6d85efa158781fd24584503dad.jpg', '<p>Một nhóm người tị nạn và binh lính lạc ngũ Trung Quốc, do một thợ máy dẫn đầu, đã bảo vệ thị trấn miền núi &quot;Gezhi&quot; của họ trước cuộc tấn công bất ngờ của quân trinh sát Nhật Bản trong một cuộc chiến tuyệt vọng, sử dụng sự khéo léo của thường dân để chống lại một lực lượng quân sự được huấn luyện bài bản.</p>', 'Full', 1, 'single', 'completed', 18, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xiao Zhan","avatar":""},{"name":"Peng Yuchang","avatar":""},{"name":"Zhou Yiran","avatar":""},{"name":"Yin Zheng","avatar":""},{"name":"Yang Xinming","avatar":""},{"name":"Alan Aruna","avatar":""},{"name":"Gan Yunchen","avatar":""},{"name":"Zhou Siyu","avatar":""},{"name":"Yan Zhidu","avatar":""},{"name":"Liao Fan","avatar":""},{"name":"Ni Dahong","avatar":""},{"name":"Zu Feng","avatar":""},{"name":"Duan Yihong","avatar":""},{"name":"Minowa Yasufumi","avatar":""},{"name":"Xu Juncong","avatar":""},{"name":"Jiang Qilin","avatar":""},{"name":"Ren Chengwei","avatar":""},{"name":"Gao Xuanming","avatar":""},{"name":"Yu Baishui","avatar":""},{"name":"Li Yue","avatar":""},{"name":"Zhuang Yuan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["De Xian Jin Zhi","Gezhi Town","得闲谨制"]', 1784690324134);
