INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('arco', 'Arco', 'Arco', 'https://phimimg.com/upload/vod/20260312-1/1028d717c4b3dfc3e3092fd8c5e1ea88.jpg', 'https://phimimg.com/upload/vod/20260312-1/e5118f8dbda751f6377c93733ac3a632.jpg', '<p>Chuyện phim kể về Arco, một cậu bé 10 tuổi sống ở năm 2932, vô tình xuyên không qua một dải cầu vồng và lạc đến năm 2075 – thời kỳ Trái Đất đang đối mặt với khủng hoảng môi trường trầm trọng. Tại đây, cậu gặp gỡ và kết bạn với Iris, một cô bé cô đơn đang sống cùng một robot bảo mẫu. Cả hai đã cùng nhau trải qua một hành trình đầy cảm xúc để tìm cách đưa Arco trở về nhà, đồng thời thắp lên hy vọng về một tương lai tươi sáng và sự gắn kết giữa con người với thiên nhiên.</p>', 'Full', 1, 'hoathinh', 'completed', 16, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Pháp', 0, '[{"name":"Margot Ringard Oldra","avatar":""},{"name":"Oscar Tresanini","avatar":""},{"name":"Nathanaël Perrot","avatar":""},{"name":"Alma Jodorowsky","avatar":""},{"name":"Swann Arlaud","avatar":""},{"name":"Vincent Macaigne","avatar":""},{"name":"Louis Garrel","avatar":""},{"name":"William Lebghil","avatar":""},{"name":"Sophie Mas","avatar":""},{"name":"Frédérique Cantrel","avatar":""},{"name":"Oxmo Puccino","avatar":""},{"name":"Joséphine Mancini","avatar":""},{"name":"Jean Boucault","avatar":""},{"name":"Johnny Rasse","avatar":""},{"name":"Audrey Tondre","avatar":""},{"name":"Félix de","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id"