INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('63-gio-doi-dau', '63 Giờ Đối Đầu', 'Dead Man''s Wire', 'https://phimimg.com/upload/vod/20260312-1/7846ee596add856a6dbdcb0099d42cc2.jpg', 'https://phimimg.com/upload/vod/20260312-1/bb7b6167b5e7585290845065dfd0611b.jpg', '<p>Năm 1977, giữa không khí căng thẳng của Indianapolis, Tony Kiritsis (Bill Skarsgård) – một cựu nhà phát triển bất động sản đang kiệt quệ – bất ngờ làm điều chẳng ai ngờ tới: ông trói chặt mình với viên giám đốc ngân hàng đã khiến ông mất tất cả, gắn trên tay một cơ chế kích nổ “chết cùng nhau” và tuyên bố chỉ có hai thứ ông muốn – 5 triệu đô và một lời xin lỗi. Trong suốt 63 giờ, cả nước Mỹ bị cuốn vào tình huống con tin kỳ quái này, nơi ranh giới giữa nạn nhân và tội phạm trở nên mờ nhòe. Khi cảnh sát, giới truyền thông và công chúng chen nhau theo dõi từng giây, câu chuyện dần hé lộ những lớp tâm lý méo mó, nỗi phẫn uất của một con người bị dồn đến đường cùng. Một cuộc đối đầu vừa là cuộc chiến sinh tồn, vừa là bức chân dung trần trụi về sự tuyệt vọng và khát khao được lắng nghe trong thời đại bạo lực và bất công.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Bill Skarsgård","avatar":""},{"name":"Colman Domingo","avatar":""},{"name":"Al Pacino","avatar":""},{"name":"Dacre Montgomery","avatar":""},{"name":"Myha''la","avatar":""},{"name":"Cary Elwes","avatar":""},{"name":"Kelly Lynch","avatar":""},{"name":"Jordan Claire Robbins","avatar":""},{"name":"John Robinson","avatar":""},{"name":"Katie Kinman","avatar":""},{"name":"Mark Helms","avatar":""},{"name":"Kyle Rankin","avatar":""},{"name":"Vinh Nguyen","avatar":""},{"name":"Stephanie Bertoni","avatar":""},{"name":"Danielle Munday","avatar":""},{"name":"Daniel R. Hill","avatar":""},{"name":"Todd Gable","avatar":""},{"name":"N","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["La Corde au cou","Viela ant kaklo","63 Horas de Pânico","Dead Man''s Wire"]', 1784690324135);
