INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('63-gio-doi-dau', '63 Giờ Đối Đầu', 'Dead Man''s Wire', '63 giờ đối đầu dead man''s wire bill skarsgård colman domingo al pacino dacre montgomery myha''la cary elwes kelly lynch jordan claire robbins john robinson katie kinman mark helms kyle rankin vinh nguyen stephanie bertoni danielle munday daniel r. hill todd gable n la corde au cou viela ant kaklo 63 horas de pânico dead man''s wire', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tram-gac-trong-suong', 'Trạm Gác Trong Sương', 'Lookout', 'https://phimimg.com/upload/vod/20260312-1/f62ad82e9a0cf22594bad00dbccb103e.jpg', 'https://phimimg.com/upload/vod/20260312-1/50f8e875f2fac9baef9efb7324bcbc33.jpg', '<p>Tìm kiếm sự bình yên khỏi cuộc sống đầy sóng gió, một phụ nữ trẻ nhận công việc canh gác phòng cháy chữa cháy tại một tòa tháp hoang dã hẻo lánh. Khi cô ổn định với vai trò mới, những xáo trộn kỳ lạ và những sự việc kỳ lạ bắt đầu diễn ra, và cô phải khám phá những bí mật rùng rợn đang phá vỡ sự cô lập của mình trước khi quá muộn.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Meghan Carrasquillo","avatar":""},{"name":"Trent Culkin","avatar":""},{"name":"John Marrs","avatar":""},{"name":"Mitch Tellez","avatar":""},{"name":"Robert Clark","avatar":""},{"name":"Jim Round","avatar":""},{"name":"Braden McCawley","avatar":""},{"name":"Cara Leoni","avatar":""},{"name":"Ryan Ellerbe","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Lookout"]', 1784690324135);
