INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-chay-ngam', 'Dòng Chảy Ngầm', 'Under Current', 'https://phimimg.com/upload/vod/20260312-1/4b43547da864e3b4d4851719639de035.jpg', 'https://phimimg.com/upload/vod/20260312-1/12cbf9a930abebbdafd0e66f91e114c9.jpg', '<p>Giữa không khí sang trọng của buổi tiệc từ thiện thường niên do Quỹ Ko tổ chức, khi mọi ánh đèn đều hướng về bài phát biểu của chủ tịch Ko Shing-man (Alex Fong), một cú sốc xảy ra: Yeung To (Simon Yam), giám đốc tài chính của quỹ, bất ngờ treo cổ ngay trên sân khấu. Cái chết gây chấn động ấy nhanh chóng kéo theo tin đồn về khoản tiền quyên góp 200 triệu đô la biến mất không dấu vết. &nbsp;Luật sư Ma Ying-fung (Quách Phú Thành) và cảnh sát Orr Ting-bong (Ngô Trấn Vũ) bị cuốn vào vòng xoáy điều tra, nơi từng lớp bí mật trong quỹ từ thiện tưởng chừng mẫu mực dần bị bóc trần. Càng tiến sâu, họ càng nhận ra phía sau vẻ hào nhoáng là cả một mạng lưới quyền lực, tiền bạc và tội lỗi đang ngầm vận hành. Một sai lầm nhỏ cũng có thể khiến tất cả sụp đổ, và ranh giới giữa công lý và tội ác trở nên mong manh hơn bao giờ hết.</p>', 'Full', 1, 'single', 'completed', 22, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Aaron Kwok","avatar":""},{"name":"Simon Yam","avatar":""},{"name":"Francis Ng Chun-Yu","avatar":""},{"name":"Alex Fong Chung-Sun","avatar":""},{"name":"Niki Chow Lai-Kei","avatar":""},{"name":"Kathy Tong Yee","avatar":""},{"name":"Power Chan Kwok-Pong","avatar":""},{"name":"Gladys Li","avatar":""},{"name":"Felix Lok Ying-Kwan","avatar":""},{"name":"David Chiang Da-Wei","avatar":""},{"name":"Nina Paw Hei-Ching","avatar":""},{"name":"Henry Fong Ping","avatar":""},{"name":"German Cheung Man-Kit","avatar":""},{"name":"Peter Chan Charm-Man","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["廉政风云·内幕","The Outsider","廉政風雲 內幕","內幕"]', 1784690324135);
