INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('akaal-the-unconquered', 'Akaal: The Unconquered', 'Akaal: The Unconquered', 'null', 'https://phimimg.com/upload/vod/20260316-1/6c96ef47ba75412ea893da88af2848d0.jpg', '<p>Lấy bối cảnh Punjab những năm 1840, Sardar Akaal Singh và dân làng của ông phải đối mặt với cuộc tấn công trả thù của Jangi Jahan và quân đội của hắn sau cái chết của Maharaja Ranjeet Singh. Giữa những thỏa thuận ngừng bắn bị phá vỡ và căng thẳng leo thang, những vị Sardar dũng cảm phải đứng lên chống lại những khó khăn chồng chất để bảo vệ vùng đất của mình. Liệu họ có chiến thắng được kẻ thù đáng gờm này?</p>', 'Full', 1, 'single', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Apindereep Singh","avatar":""},{"name":"Gippy Grewal","avatar":""},{"name":"Nimrat Khaira","avatar":""},{"name":"Nikitin Dheer","avatar":""},{"name":"Gurpreet Ghuggi","avatar":""},{"name":"Mita Vashisht","avatar":""},{"name":"Prince Kanwaljit Singh","avatar":""},{"name":"Shinda Grewal","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["ਅਕਾਲ: ਅਣਜਿੱਤ"]', 1784690324135);
