INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-pha-vo-the-gioi', 'Kẻ Phá Vỡ Thế Giới', 'Worldbreaker', 'https://phimimg.com/upload/vod/20260316-1/85e84b6817e47f33c9f7875160c50257.jpg', 'https://phimimg.com/upload/vod/20260316-1/9cf24ab5f8e10b940c0ba16211021369.jpg', '<p>Năm năm trước, một vết nứt trong kết cấu thực tại đã mở ra cánh cổng đưa những sinh vật từ chiều không gian khác tràn vào thế giới của chúng ta với mục đích hủy diệt. Để bảo vệ con gái, một người cha đưa cô bé ẩn náu trên một hòn đảo biệt lập, vừa che chở vừa rèn luyện cô cho cuộc sống sinh tồn và những trận chiến sắp tới. Nhưng khi thế giới đứng bên bờ sụp đổ, không còn nơi nào thực sự an toàn.</p>', 'Full', 1, 'single', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Milla Jovovich","avatar":""},{"name":"Luke Evans","avatar":""},{"name":"Billie Boullet","avatar":""},{"name":"Meadow Williams","avatar":""},{"name":"Mila Harris","avatar":""},{"name":"Kevin Glynn","avatar":""},{"name":"Chris Finlayson","avatar":""},{"name":"Charis Agbonlahor","avatar":""},{"name":"Laura Dee","avatar":""},{"name":"Steven Calvert","avatar":""},{"name":"Nathan Ward","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Worldbreaker: The Demonic Invasion","월드 브레이커","Worldbreaker"]', 1784690324135);
