INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-trong-mo', 'Câu chuyện trong mơ', 'Dream Story / Traumnovelle', 'https://phimimg.com/upload/vod/20260316-1/cf0731755da8a835ff4361ceb87a1ace.jpg', 'https://phimimg.com/upload/vod/20260316-1/77ff83f1759ddfbd5c0b12a461f17088.jpg', '<p>Cuộc hôn nhân của một cặp vợ chồng thượng lưu bị thử thách khi người chồng phát hiện ra một hội kín về tình dục và tham dự một buổi dạ hội hóa trang, bất chấp những lời cảnh báo về hậu quả có thể xảy ra, sau khi vợ anh thừa nhận có những tưởng tượng về một người đàn ông khác.</p>', 'Full', 1, 'single', 'completed', 18, 2025, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Nikolai Kinski","avatar":""},{"name":"Laurine Price","avatar":""},{"name":"Nicole Nagel","avatar":""},{"name":"Bruno Eyron","avatar":""},{"name":"Nike Martens","avatar":""},{"name":"Detlev Buck","avatar":""},{"name":"Patrick Mölleken","avatar":""},{"name":"Nora Islei","avatar":""},{"name":"Rodney Charles","avatar":""},{"name":"Sharon Kovacs","avatar":""},{"name":"Sharon Brauner","avatar":""},{"name":"Katharina Gerhardt","avatar":""},{"name":"Christoph Moreno","avatar":""},{"name":"Chelsea von Holst","avatar":""},{"name":"Clara Tekampe","avatar":""},{"name":"Can Bilgic","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Dream Story","Traumnovelle"]', 1784690324135);
