INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-dau-sung-cuoi-cung', 'Cuộc Đấu Súng Cuối Cùng', 'The Last GunFight', 'https://phimimg.com/upload/vod/20260316-1/b9a994a2e00778e7f0d1b2f174a8dd47.jpg', 'https://phimimg.com/upload/vod/20260316-1/f1a26d6c55a412c5210ccfb28cf4c769.jpg', '<p>Trong một giải đấu ngầm tàn bạo, những sát thủ hàng đầu thế giới chiến đấu đến chết. Nhưng ẩn giữa họ là một nhóm bí ẩn với kế hoạch nguy hiểm riêng: thâm nhập vào giải đấu, sống sót qua biển máu, và hạ gục kẻ đứng sau giật dây mọi chuyện.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jon Voight","avatar":""},{"name":"Adam Woodward","avatar":""},{"name":"Charlotte Vega","avatar":""},{"name":"Eloise Lovell Anderson","avatar":""},{"name":"Daniel Bernhardt","avatar":""},{"name":"Brock Pierce","avatar":""},{"name":"Shaina West","avatar":""},{"name":"Alix Villaret","avatar":""},{"name":"Skyler Shaye","avatar":""},{"name":"Rade Šerbedžija","avatar":""},{"name":"Lewis Jamison","avatar":""},{"name":"Max Kraus","avatar":""},{"name":"Andy Lister","avatar":""},{"name":"Sam Symons","avatar":""},{"name":"Dearbhla Molloy","avatar":""},{"name":"Pancho Moler","avatar":""},{"name":"Gen Seto","avatar":""},{"name":"Zacha","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["La ultima batalla","Dueli i fundit me armë","The Last GunFight"]', 1784690324135);
