INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-dau-sung-cuoi-cung', 'Cuộc Đấu Súng Cuối Cùng', 'The Last GunFight', 'cuộc đấu súng cuối cùng the last gunfight jon voight adam woodward charlotte vega eloise lovell anderson daniel bernhardt brock pierce shaina west alix villaret skyler shaye rade šerbedžija lewis jamison max kraus andy lister sam symons dearbhla molloy pancho moler gen seto zacha la ultima batalla dueli i fundit me armë the last gunfight', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-david', 'Vua David', 'David', 'https://phimimg.com/upload/vod/20260316-1/02774b886f66f7b551dd875bae5d0d99.jpg', 'https://phimimg.com/upload/vod/20260316-1/cbdfc9df0190aa3440b4b0b486e46d9d.jpg', '<p>Phim tái hiện cuộc đời của vị vua huyền thoại David, từ khi còn là một cậu bé chăn cừu khiêm tốn với tài năng âm nhạc thiên bẩm đến lúc trở thành anh hùng dân tộc. Với đức tin không lay chuyển, David đã đối đầu và hạ gục gã khổng lồ Goliath chỉ bằng một chiếc ná và vài viên sỏi. Hành trình của cậu không chỉ là cuộc chiến giành vương quyền mà còn là bài học về sự dũng cảm, lòng trung thành và sức mạnh của niềm tin trước những thử thách nghiệt ngã nhất.</p>', 'Full', 1, 'single', 'completed', 31, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Brandon Engman","avatar":""},{"name":"Brian Stivale","avatar":""},{"name":"Shahar Taboch","avatar":""},{"name":"Aaron Tavaler","avatar":""},{"name":"Hector","avatar":""},{"name":"Miri Mesika","avatar":""},{"name":"Jack Wagman","avatar":""},{"name":"Jonathan Shaboo","avatar":""},{"name":"Sloan Lucas Muldown","avatar":""},{"name":"Mike Ciporkin","avatar":""},{"name":"Katie Bernstein","avatar":""},{"name":"Lauren Daigle","avatar":""},{"name":"Mark Jacobson","avatar":""},{"name":"Nitzan Sitzer","avatar":""},{"name":"Adam Meir","avatar":""},{"name":"Adam Michael Gold","avatar":""},{"name":"Asim Chaudhry","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Davi","大衛：王者降臨","Давид","David: Una aventura gegant","David. Una aventura gegant","David"]', 1784690324135);
