INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-xay-ra-tren-dao', 'Chuyện Xảy Ra Trên Đảo', 'Islands', 'https://phimimg.com/upload/vod/20260316-1/ee264fda9e5313716e06c967c373a028.jpg', 'https://phimimg.com/upload/vod/20260316-1/7ea98e3a8b3ce39e9ce26b766c6f2e99.jpg', '<p>Trên hòn đảo thiên đường với vẻ ngoài hoàn hảo, Tom – huấn luyện viên tennis của khu nghỉ dưỡng xa hoa – sống những ngày trống rỗng bằng men rượu và những mối tình thoáng qua. Nhưng khi gia đình Maguire xuất hiện, nhịp sống của anh bị đảo lộn. Giữa Tom và Anne dần hình thành một sợi dây khó lý giải, khiến anh ám ảnh với cảm giác đã từng quen biết cô từ trước. Rồi một đêm định mệnh, Dave – người chồng – đột ngột mất tích. Trong khi sự thật bị che giấu sau những lời dối trá, tất cả mũi nhọn nghi ngờ lại hướng về Anne… và Tom.</p>', 'Full', 1, 'single', 'completed', 19, 2025, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Sam Riley","avatar":""},{"name":"Stacy Martin","avatar":""},{"name":"Jack Farthing","avatar":""},{"name":"Dylan Torrell","avatar":""},{"name":"Agnes Lindström Bolmgren","avatar":""},{"name":"Bruna Cusí","avatar":""},{"name":"Pep Ambròs","avatar":""},{"name":"Fatima Adoum","avatar":""},{"name":"Maya Unger","avatar":""},{"name":"Ahmed Boulane","avatar":""},{"name":"Fernando Navas","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["忘情度假村","Islands"]', 1784690324135);
