INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('palestine-36', 'Palestine 36', 'Palestine 36', 'https://phimimg.com/upload/vod/20260318-1/f7e877258b4e56174181ffa829c82c31.jpg', 'https://phimimg.com/upload/vod/20260318-1/1a1be955ea6d70b15cda0d0ef9f3eb5b.jpg', '<p>Năm 1936, khi các làng mạc Palestine nổi dậy chống lại ách cai trị thuộc địa của Anh và làn sóng nhập cư của người Do Thái từ châu Âu tăng tốc hướng tới việc thanh lọc sắc tộc người Palestine, Yusuf di chuyển giữa Jerusalem và quê nhà ở vùng nông thôn trong bối cảnh bất ổn leo thang và thời điểm quyết định đối với Đế quốc Anh.</p>', 'Full', 1, 'single', 'completed', 20, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Anh', 0, '[{"name":"Karim Daoud Anaya","avatar":""},{"name":"Hiam Abbass","avatar":""},{"name":"Robert Aramayo","avatar":""},{"name":"Yasmine Al Massri","avatar":""},{"name":"Billy Howle","avatar":""},{"name":"Dhafer L''Abidine","avatar":""},{"name":"Ward Helou","avatar":""},{"name":"Yafa Bakri","avatar":""},{"name":"Wardi Eilabouni","avatar":""},{"name":"Saleh Bakri","avatar":""},{"name":"Jalal Altawil","avatar":""},{"name":"Jeremy Irons","avatar":""},{"name":"Kamel El Basha","avatar":""},{"name":"Joanna Arida","avatar":""},{"name":"Sofia Asir","avatar":""},{"name":"Eid Aziz","avatar":""},{"name":"Samer Bisharat","avatar":""},{"name":"L","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["Palestina 36","Παλαιστίνη 36","Palestine 36","Palästina 36","Palestine ‘36","فلسطين ٣٦"]', 1784690324135);
