INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vang', 'Vàng', 'Golden', 'https://phimimg.com/upload/vod/20260318-1/626d69c693ac096538d749b3279aa607.jpg', 'https://phimimg.com/upload/vod/20260318-1/111fad7552beb9b28f3b6e6fc8c62282.jpg', '<p>Trong một thế giới đầy rẫy sự phản bội và những vụ cướp táo bạo, một bậc thầy làm tiền giả phải đối mặt với những tên tội phạm tàn nhẫn, một thám tử đa nghi và một âm mưu chết người. Anh ta phải chiến đấu với lòng tham, dục vọng và sự cám dỗ để đánh bại kẻ thù và trốn thoát cùng...</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Brian Austin Green","avatar":""},{"name":"Glenn Plummer","avatar":""},{"name":"Robert Miano","avatar":""},{"name":"Massi Furlan","avatar":""},{"name":"Alena Savostikova","avatar":""},{"name":"Josh Gilmer","avatar":""},{"name":"Marilyn Uribe","avatar":""},{"name":"Patricio Doren","avatar":""},{"name":"David Fernandez Jr.","avatar":""},{"name":"Lamondo Hill II","avatar":""},{"name":"Rafael Siegel","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["O Mestre do Golpe","Golden - Counterfeit","Golden"]', 1784690324135);
