INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ut-lan-oan-linh-giu-cua', 'Út Lan: Oán Linh Giữ Của', 'The Guardian Demon / Ut Lan: The Vengeful Guardian Spirit', 'https://phimimg.com/upload/vod/20260320-1/fd56a886f27d89df210415dd33f2ab6e.jpg', 'https://phimimg.com/upload/vod/20260320-1/8da22e7ddd10639ab76bba823b7a743b.jpg', '<p>Sau sự ra đi của cha, Lan (Phương Thanh) về một vùng quê và ở đợ cho nhà ông Danh (Mạc Văn Khoa) - một người đàn ông góa vợ, không con cái. Ngay sau khi bước chân vào căn nhà, Lan phải đối mặt với hàng loạt hiện tượng kỳ dị và những cái chết bí ẩn liên tục xảy ra. Cùng với Sơn (Quốc Trường) - một nhà văn chuyên viết truyện kinh dị, Lan bắt đầu lật mở những bí mật kinh hoàng, khám phá lịch sử đen tối của căn nhà.</p>', 'Full', 1, 'single', 'completed', 34, 2025, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Phương Thanh","avatar":""},{"name":"Quốc Trường","avatar":""},{"name":"Mạc Văn Khoa","avatar":""},{"name":"Mai Cát Vi","avatar":""},{"name":"Thanh Thức","avatar":""},{"name":"Thụy Mười","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Út Lan: Oán Linh Giữ Của"]', 1784690324135);
