INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-cong-chua-bao-thu-scarlet', 'Khi Công Chúa Báo Thù (SCARLET)', 'Scarlet', 'https://phimimg.com/upload/vod/20260320-1/2afe04aca51c401737254df619f2364d.jpg', 'https://phimimg.com/upload/vod/20260320-1/66602495c5fa60dfc9103027d93ae546.jpg', '<p>Lạc vào vùng đất tử thần và gặp một chàng trai từ thế giới hiện đại, Scarlet được thấy viễn cảnh tương lai yên bình. Nhưng điều đó có đủ để cô buông bỏ hận thù khi lần nữa đối mặt với kẻ đã giết cha?</p>', 'Full', 1, 'hoathinh', 'completed', 19, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 1, '[{"name":"Mana Ashida","avatar":""},{"name":"Masaki Okada","avatar":""},{"name":"Yutaka Matsushige","avatar":""},{"name":"Kotaro Yoshida","avatar":""},{"name":"Koji Yakusho","avatar":""},{"name":"Masachika Ichimura","avatar":""},{"name":"Yuki Saito","avatar":""},{"name":"Shota Sometani","avatar":""},{"name":"Munetaka Aoki","avatar":""},{"name":"Kazuhiro Yamaji","avatar":""},{"name":"Tokio Emoto","avatar":""},{"name":"Kayoko Shiraishi","avatar":""},{"name":"Noa Shiroyama","avatar":""},{"name":"Michio Hazama","avatar":""},{"name":"Mamoru Miyano","avatar":""},{"name":"Kenjiro Tsuda","avatar":""},{"name":"Toshio F","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hateshi naki Scarlet","Hateshinaki Scarlet","Scarlet Without Limits","Scarlet永無止盡的史嘉蕾","無盡的施嘉莉","Hateshinaki Sukāretto","Endless Scarlet","Scarlet et l''éternité","สก