INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khi-cong-chua-bao-thu-scarlet', 'Khi Công Chúa Báo Thù (SCARLET)', 'Scarlet', 'khi công chúa báo thù (scarlet) scarlet mana ashida masaki okada yutaka matsushige kotaro yoshida koji yakusho masachika ichimura yuki saito shota sometani munetaka aoki kazuhiro yamaji tokio emoto kayoko shiraishi noa shiroyama michio hazama mamoru miyano kenjiro tsuda toshio f hateshi naki scarlet hateshinaki scarlet scarlet without limits scarlet永無止盡的史嘉蕾 無盡的施嘉莉 hateshinaki sukāretto endless scarlet scarlet et l''éternité สการ์เล็ต скарлет 果てしなきスカーレット', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dot-pha-vong-vay', 'Đột Phá Vòng Vây', 'Blood-Forged Breakout', 'https://phimimg.com/upload/vod/20250704-1/d131ddef6bcde78502660abff391362a.jpg', 'https://phimimg.com/upload/vod/20250704-1/1114df097df2822e0fe9a55bc6303ea0.jpg', '<p>Vào mùa đông năm 1939, một trung đoàn Bát Lộ Quân thuộc khu quân sự Sơn Đông bị quân Nhật bao vây nghiêm ngặt. Đại đội trinh sát chịu tổn thất hơn một nửa, liều chết tấn công trận địa Tam Điện; lấy hiệu lệnh tập kết làm tín hiệu, yểm trợ lực lượng chủ lực phá vòng vây, thề sống chết không lùi. Đại đội trưởng Lưu Thượng Trí dẫn theo 48 chiến sĩ phản kích trong tuyệt cảnh, chiến đấu sinh tử với quân Nhật, đẩy lùi nhiều đợt tấn công, cuối cùng làm thất bại âm mưu của quân địch; cả 48 chiến sĩ đều anh dũng hy sinh, không ai sống sót.</p>', 'Full', 1, 'single', 'completed', 16, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Huy","avatar":""},{"name":"Ai Khê","avatar":""},{"name":"Đặng Khải Vân","avatar":""},{"name":"Du Hữu Xuyên","avatar":""},{"name":"Tống Vân Tân","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yu Xue Tu Wei","浴血突围"]', 1784690324135);
