INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-an-karawek', 'Bí Ẩn Karawek', 'Krong Karawek', 'https://phimimg.com/upload/vod/20250211-1/1cc828c3c5e33c97a82ad53208f87547.jpg', 'https://phimimg.com/upload/vod/20250211-1/0cc04040f18a0bed9040a3b67636ef53.jpg', '<p>Bí Ẩn Karawek là hành trình đi tìm sự thật của Khwanta để lấy lại công bằng, gột rửa oan khuất. Khi bảo vật gia truyền của cả gia tộc biến mất, bố của Khwanta bị vu oan và phải gánh hết mọi tội lỗi. Nhiều năm sau, với quyết tâm giải oan cho bố, Khwanta quay trở lại căn biệt thự của gia đình, nơi chứa đựng nhiều bí mật đen tối và những âm mưu chưa từng được phơi bày.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 14, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Tiewhui Pechpachaya Luangdechanurak","avatar":""},{"name":"Cookie Yada Suwanpattana","avatar":""},{"name":"Phutanate Hongmanop","avatar":""},{"name":"Puri Hiranprueck","avatar":""},{"name":"Ornjira Lamwilai","avatar":""},{"name":"Arisara Wongchalee","avatar":""},{"name":"Chinaradee Anupongpichat","avatar":""},{"name":"Parattakorn Kaiyanan","avatar":""},{"name":"Poom Kaewfajarroen","avatar":""},{"name":"Gumpuns Koravich Sarasin","avatar":""},{"name":"PingPing Sorrawee Tan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["เรือนการเวก","Ruean Karawek","The Cage of Karawek","กรงการเวก"]', 1784690324135);
