INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yen-ngo-vinh-an', 'Yến Ngộ Vĩnh An', 'Yummy Yummy Yummy', 'https://phimimg.com/upload/vod/20251009-1/44fd44943710e2033ac17310e48324bc.jpg', 'https://phimimg.com/upload/vod/20251009-1/8d04d99d628f392127e0cea52640c5f7.jpg', '<p>Bộ phim kể về gia đình nhà họ Thẩm, trong một lần tình cờ, vô tình xuyên không đến thành Vĩnh An. Tại đây, họ gặp gỡ Lâm Diệm, vị thiếu doãn phủ Kinh Triệu, và cùng nhau bắt đầu một hành trình thú vị đậm hương vị ẩm thực, sắc màu dân gian, xen lẫn một chuyện tình “đượm sắc hương” dần dần nảy nở.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 28, 2025, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Ảnh Lộ","avatar":""},{"name":"Lý Quân Nhuệ","avatar":""},{"name":"Xướng Long","avatar":""},{"name":"Phùng Gia Di","avatar":""},{"name":"Tùy Tuấn Ba","avatar":""},{"name":"Đổng Tư Di","avatar":""},{"name":"Hộ Duy","avatar":""},{"name":"Hàn Mạch","avatar":""},{"name":"Lưu Quân","avatar":""},{"name":"Nghê Hồng Khiết","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["长安小饭馆","Yan Yu Yong An","Yummy Yummy Yummy","Yummy, Yummy? Yummy!","宴遇永安"]', 1784690324135);
