INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('yen-ngo-vinh-an', 'Yến Ngộ Vĩnh An', 'Yummy Yummy Yummy', 'yến ngộ vĩnh an yummy yummy yummy vương ảnh lộ lý quân nhuệ xướng long phùng gia di tùy tuấn ba đổng tư di hộ duy hàn mạch lưu quân nghê hồng khiết 长安小饭馆 yan yu yong an yummy yummy yummy yummy, yummy? yummy! 宴遇永安', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuu-duong-vo-than', 'Cửu Dương Võ Thần', 'Ascendants Of The Nine Suns', 'https://phimimg.com/upload/vod/20251122-1/13dd059f3fe0c2a9f1c1f8d10701dbfd.jpg', 'https://phimimg.com/upload/vod/20251122-1/25d3b2c273e828dfa4dd7add68313711.jpg', '<p>Cửu Dương Võ Thần khắc họa lại hành trình trở thành một Thiên Đế đầy gian khổ và dài đằng đẵng của Diệp Vân Phi, anh chàng phải trải qua mọi cung bậc cảm xúc của sự đau khổ và phản bội trên cuộc đời này. Phải trải qua tới hai kiếp người mà Diệp Vân Phi mới đạt đến ngôi vị của Thiên Đế, đạp lên tất cả nhưng quả thật quá nhiều chông gai. Từng được biết đến mà một thiếu niên sở hữu những tài năng và thiên phú thiên bẩm nhưng những biến cố cứ thay nhau bủa vây lấy anh chàng khốn khổ ấy, gia tộc bị chèn ép, cha của anh thì bị giết, vợ thì phản bội mà quay đi, ngay cả võ mạch cũng không còn dùng để tu luyện được nữa. Vô tình lúc đó Diệp Vân đã gặp được thánh nhân tên là Tử Thánh Chân Quân, được ngài nhận là đệ tử và đưa anh trở lại con đường tu luyện, một bước trở thành vị Thiên Đế có một không hai trẻ nhất trong lịch sử.</p>', 'Hoàn Tất (20/20)', 20, 'hoathinh', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["第1季","九阳武神","九阳武神 Jiu Yang Wu Shen","Jiu Yang Wu Shen","Боевой мастер чистого ян","The Divine Warrior of Jiuyang","Nine Suns Martial God"]', 1784690324135);
