INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gnosia', 'GNOSIA', 'GNOSIA', 'https://phimimg.com/upload/vod/20251026-1/0bedf0714c632435933247791c2ab3e4.jpg', 'https://phimimg.com/upload/vod/20251026-1/e247756d7e997f20cc3687e7d1d12d08.jpg', '<p>Khi một kẻ thù biến hình mang tên Gnosia xâm nhập vào một con tàu vũ trụ đơn độc, phi hành đoàn chỉ có một cách duy nhất để sống sót: nhận dạng kẻ mạo danh mỗi ngày và đưa chúng vào trạng thái ngủ đông. Nhưng với Yuri, ngày đó không bao giờ kết thúc. Bị mắc kẹt trong một vòng lặp thời gian, cô liên tục sống lại ngày đầu tiên của cuộc khủng hoảng. Để thoát khỏi, Yuri phải khám phá sự thật đằng sau Gnosia và chính vòng lặp thời gian đó—trước khi quá muộn.</p>', 'Tập 21', 24, 'hoathinh', 'ongoing', 14, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Chika Anzai","avatar":""},{"name":"Ikumi Hasegawa","avatar":""},{"name":"Akari Kito","avatar":""},{"name":"Hiroki Nanami","avatar":""},{"name":"Asami Seto","avatar":""},{"name":"Tomokazu Seki","avatar":""},{"name":"Saori Hayami","avatar":""},{"name":"Aoi Yuuki","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Yuichi Nakamura","avatar":""},{"name":"Kenjiro Tsuda","avatar":""},{"name":"Kana Hanazawa","avatar":""},{"name":"Takeo Otsuka","avatar":""},{"name":"Takuya Eguchi","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Gunōshia","グノーシア"]', 1784690324135);
