INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-tim-xac-dem-cuoi-cung', 'Trò Chơi Tìm Xác: Đêm Cuối Cùng', 'Re/Member: The Last Night', 'https://phimimg.com/upload/vod/20260309-1/f3fb2bc05f5de56cd1426a02f3e6b662.jpg', 'https://phimimg.com/upload/vod/20260309-1/4f955a0b41f1abfd60fc3171f1124df6.jpg', '<p>Ba năm sau khi hoàn thành một trò chơi chết người, các học giả cấp cao bị mắc kẹt trong một cơn ác mộng luẩn quẩn phải sống sót qua những cuộc chạm trán tàn khốc và giải mã một lời nguyền kinh hoàng.</p>', 'Full', 1, 'single', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kanna Hashimoto","avatar":""},{"name":"Gordon Maeda","avatar":""},{"name":"Kaito Sakurai","avatar":""},{"name":"Marin Honda","avatar":""},{"name":"Seira Anzai","avatar":""},{"name":"Fuku Suzuki","avatar":""},{"name":"Yoshino Kimura","avatar":""},{"name":"Takeaki Yoshida","avatar":""},{"name":"Fuju Kamio","avatar":""},{"name":"Kotaro Daigo","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Karada Sagashi THE LAST NIGHT","Re/Member: The Last Night","Karada Sagashi: The Last Night","カラダ探し THE LAST NIGHT"]', 1784690324135);
