INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-the-tien-y-bat-nhiem-tran', 'Phù Thế Tiên Y Bất Nhiễm Trần', 'Immortal Beyond Dust', 'https://phimimg.com/upload/vod/20260309-1/0f108a5ef08751b89a044e340e2c4aaf.jpg', 'https://phimimg.com/upload/vod/20260309-1/bc90e34946e54f30eaa071754c95f33b.jpg', '<p>Vạn năm trước, thần khí tam giới là Gương Phù Thế bị vỡ, Tà Vân thoát ra và nhập vào cơ thể một thiếu niên người phàm tên là Diệu Dương. Thượng tiên Bạch Hy Âm đã nhận Diệu Dương làm đệ tử để thanh tẩy Tà Vân, nhưng cuối cùng Bạch Hy Âm phải hy sinh, dùng chính tiên phách của mình truyền vào cơ thể Diệu Dương để trấn áp tà khí. Diệu Dương sử dụng bí thuật của Ảnh tộc cùng sức mạnh của Tà Vân để hồi sinh Bạch Hy Âm (khi đó đã hồn phi phách tán), nhưng cậu cần phải tìm lại được những mảnh nguyên thần thất lạc của nàng. Nhờ cơ duyên đưa đẩy, Diệu Dương đồng hành cùng một thiếu niên Ảnh tộc, một tiểu hồ ly Thanh Khâu và một cây nấm nhỏ Yêu tộc. Họ cùng nhau bước lên con đường cứu sống Bạch Hy Âm, đồng thời dần hé lộ những bí mật ẩn giấu phía sau Gương Phù Thế và Tà Vân.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hàn Tiêu Dao","avatar":""},{"name":"Trương Ngọc Hàn","avatar":""},{"name":"Châu Tử Tuấn","avatar":""},{"name":"Vương Nghệ Tuyển","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Fu Shi Xian Yi Bu Ran Chen","浮世仙衣不染塵","浮世决","浮世決","浮世仙衣不染尘"]', 1784690324135);
