INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-nhan-sam', 'Vua Nhân Sâm', 'Ginseng King', 'https://phimimg.com/upload/vod/20260308-1/6bb3a09b564f49fe92ae2a083a86eb26.jpg', 'https://phimimg.com/upload/vod/20260308-1/e0b041af6f0e215de0ffca0356403948.jpg', '<p>Chàng trai dẫn núi Lâm Diệu Sơn, từ nhỏ được lão bá đầu Long Nhị Khuê cứu mạng trên núi Thánh Nữ và thu nhận làm đồ đệ. Lâm Diệu Sơn tuy thân thủ linh hoạt, tính tình láu cá tham tiền, nhưng ẩn sâu bên trong lại là một tấm lòng lương thiện. Vụ án nhân sâm biến mất kéo anh vào những bí ẩn chốn rừng sâu liên quan đến chuyện cũ ở trại phong và truyền thuyết về nhục linh chi. Trải qua bao biến cố cùng sự ra đi của sư phụ Long Nhị Khuê, cuối cùng anh trở thành thế hệ người dẫn núi mới.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Trác Văn","avatar":""},{"name":"Củng Hán Lâm","avatar":""},{"name":"Lưu Giao Tâm","avatar":""},{"name":"Văn Tình","avatar":""},{"name":"Lữ Hâm","avatar":""},{"name":"Triệu Tử Xác","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Gan Shan Ren Chuan Qi","赶山人传奇"]', 1784690324135);
