INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuyet-trung-huyet-dao-hanh', 'Tuyết Trung Huyết Đao Hành', 'Bloodblade In The Snow', 'https://phimimg.com/upload/vod/20250530-1/a4fec1e106a3bbf641ae57c12d77cbaf.jpg', 'https://phimimg.com/upload/vod/20250530-1/c7ffb1ef4df1f6e5ab94c324682be316.jpg', '<p>Vào năm Vạn Lịch thứ 23 triều Minh, tướng biên ải Triển Tòng Văn bị gian thần vu cáo cấu kết với người Nhật, cả nhà bị xử trảm. Con trai ông, Triển Hồng trốn thoát, lưu lạc đến trấn Tần Xuyên, tại đây anh gặp gỡ và đem lòng yêu Hạ Dĩnh. Tuy nhiên, anh phát hiện cha của Hạ Dĩnh là Hạ Hầu Bá Thiên từng tham gia vào vụ án của ccha mình. Sự thật dần dần hé lộ. Cuối cùng, Triển Hồng rửa được mối thù, được phong làm Chỉ huy sứ Cẩm y vệ, tiếp tục ra tay chỉnh đốn triều cương.</p>', 'Full', 1, 'single', 'completed', 19, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Kháp","avatar":""},{"name":"Vương Lạc Gia","avatar":""},{"name":"Dương Quân","avatar":""},{"name":"Lý Bác","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["雪中血刀行"]', 1784690324135);
