INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('be-ghe-ma-cung', 'Bé Ghệ Ma Cưng', 'My Boo 2', 'https://phimimg.com/upload/vod/20260307-1/305c10bf355ea15dec5300283524b3f6.jpg', 'https://phimimg.com/upload/vod/20260307-1/f57a7c5f0ba19967a920749a1c72f3d5.jpg', '<p>Khép lại những trang hồi ức của &quot;My Boo&quot;, Jo trở về tiếp quản ngôi nhà cổ - nơi từng chứng kiến cuộc gặp gỡ định mệnh giữa anh và bé ma Anong, linh hồn vẫn luôn vương vấn sau những bức tường cũ kỹ. Tình yêu của họ từng chớm nở rực rỡ nhưng lại kết thúc với sự cách biệt âm dương. Tưởng chừng mọi chuyện đã ngủ yên dưới lớp bụi thời gian, cho đến khi một kẻ lạ mặt đầy bí ẩn xuất hiện. Hắn trao cho Jo cơ hội ngược dòng luân hồi, để anh tận mắt chứng kiến những tiền kiếp xa xăm mà mình và Anong từng chung bước. Kiếp yêu đầu tiên, Anong là một nữ chiến binh quả cảm. Kiếp yêu thứ hai, họ lại kề vai sát cánh giữa những vụ án tâm linh đầy rẫy hiểm nguy. Dẫu thời đại xoay vần, hình hài thay đổi, họ vẫn tìm thấy nhau, vẫn yêu và cùng nhau đối diện với định mệnh nghiệt ngã. Bởi giữa Jo và Anong là một sợi dây nhân duyên bền chặt, đan dệt qua hàng thế kỷ, kết nối họ xuyên qua mọi kiếp nhân sinh.</p>', 'Full', 1, 'single', 'completed', 20, 2025, 'Vietsub', 'FHD', 'Thái Lan', 1, '[{"name":"Sutthirak Subvijitra","avatar":""},{"name":"Maylada Susri","avatar":""},{"name":"Timethai","avatar":""},{"name":"Chaleumpol Tikumpornteerawong","avatar":""},{"name":"Tatchaya Supatanyasatit","avatar":""},{"name":"Puang Kaewprasert","avatar":""},{"name":"Fon Thanasoonthorn","avatar":""},{"name":"Itkron Pungkiatrussamee","avatar":""},{"name":"Narttida Pitakwararat","avatar":""},{"name":"Punyawee Jungcharoen","avatar":""},{"name":"Kittiphong Boonprakhom","avatar":""},{"name":"Arunphong Naraphan","avatar":""}]',