INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tren-bai-cat-mua-he', 'Trên Bãi Cát Mùa Hè', 'On Summer Sand (Natsu no Suna no Ue)', 'https://phimimg.com/upload/vod/20260307-1/c6a8c7d1b330239e8548fdd47d4d5744.jpg', 'https://phimimg.com/upload/vod/20260307-1/789e9b3d79a4872ca429d6d01d910039.jpg', '<p>Cuộc đời của Koura Osamu (Odagiri Joe) như ngừng lại kể từ ngày ông mất đi cậu con trai nhỏ. Bị nhấn chìm trong cảm giác mất mát, ông dần xa cách và rồi ly thân với vợ mình, Koura Keiko (Matsu Takako). Xưởng đóng tàu nơi Koura làm việc cũng bị phá sản, nhưng ông vẫn không thể tìm được một công việc mới.</p>', 'Full', 1, 'single', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Joe Odagiri","avatar":""},{"name":"Akari Takaishi","avatar":""},{"name":"Takako Matsu","avatar":""},{"name":"Naotaro Moriyama","avatar":""},{"name":"Fumiya Takahashi","avatar":""},{"name":"Yukiko Shinohara","avatar":""},{"name":"Hikari Mitsushima","avatar":""},{"name":"Ken Mitsuishi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Natsu no Suna no Ue","夏日沙石之上","夏の砂の上"]', 1784690324135);
