INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tren-bai-cat-mua-he', 'Trên Bãi Cát Mùa Hè', 'On Summer Sand (Natsu no Suna no Ue)', 'trên bãi cát mùa hè on summer sand (natsu no suna no ue) joe odagiri akari takaishi takako matsu naotaro moriyama fumiya takahashi yukiko shinohara hikari mitsushima ken mitsuishi natsu no suna no ue 夏日沙石之上 夏の砂の上', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-cam-ngu-mieu-phong', 'Tử Cấm Ngự Miêu Phòng', 'Forbidden City: Imperial Cats (Paw & Palaces)', 'https://phimimg.com/upload/vod/20251221-1/b267c7b58d2e1bcb4621d0972d46bd90.jpg', 'https://phimimg.com/upload/vod/20251221-1/50d393dd4701de0d722bae33ff0fe8bd.jpg', '<p>Trong Tử Cấm Thành cổ kính với bề dày lịch sử và văn hóa sâu sắc, có rất nhiều chú mèo đáng yêu đang sinh sống. Trong mắt con người, chúng có một cuộc sống thong dong đầy ngưỡng mộ. Thế nhưng, trong số đó có sáu chú &quot;Ngự miêu&quot; khác biệt, mang trên mình trọng trách bảo vệ ký ức của các văn vật — gọi là &quot;Vật Hoa&quot;. Chúng tiến vào thế giới của Vật Hoa, hết lần này đến lần khác chiến thắng kẻ phá hoại Hắc Kiêu, đưa thế giới ấy trở lại quỹ đạo đúng đắn, từ đó bảo vệ các báu vật quốc gia. Sáu chú Ngự miêu này bao gồm: Ban Thúc, Ma Ma (thuộc lớp Văn) và Sương Mi, A Bái, Bình An, Tiểu Tử (thuộc lớp Võ). Với trí tuệ, lòng dũng cảm và sự phối hợp ăn ý, chúng đã cùng nhau tạo nên &quot;Tử Cấm Ngự Miêu Phòng&quot; — đội quân bảo vệ thế giới Vật Hoa của quốc bảo.</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 19, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Siwangzhi","avatar":""},{"name":"Liu Shishi","avatar":""},{"name":"Li Jiaxiang","avatar":""},{"name":"Shuiyu Tang","avatar":""},{"name":"Jinwen Chen","avatar":""},{"name":"Zhang Huilin","avatar":""},{"name":"Lu Lifeng","avatar":""},{"name":"Bai Xuecen","avatar":""},{"name":"Shi Zekun","avatar":""},{"name":"Li Lanling","avatar":""},{"name":"Su Yushan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Zi Jin · Yu Miao Fang","자금어묘방: 고양이 수사 일지","Forbidden City: Imperial Cats","The Forbidden City: Cat Imperial study","紫禁·御喵房"]', 1784690324135);
