INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tu-cam-ngu-mieu-phong', 'Tử Cấm Ngự Miêu Phòng', 'Forbidden City: Imperial Cats (Paw & Palaces)', 'tử cấm ngự miêu phòng forbidden city: imperial cats (paw & palaces) zhang siwangzhi liu shishi li jiaxiang shuiyu tang jinwen chen zhang huilin lu lifeng bai xuecen shi zekun li lanling su yushan zi jin · yu miao fang 자금어묘방: 고양이 수사 일지 forbidden city: imperial cats the forbidden city: cat imperial study 紫禁·御喵房', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-duong-thua-phong-luc', 'Đại Đường Thừa Phong Lục', 'Wind Driver In Tang Dynasty', 'https://phimimg.com/upload/vod/20251009-1/137248e69dac83158d98343551c96f1c.jpg', 'https://phimimg.com/upload/vod/20251009-1/cb26aaba629c262c548b24e81d9e05e5.jpg', '<p>Một biến cố lớn xảy ra khi sư phụ Mục Thiên Hậu, bậc Thánh Thủ lừng danh giang hồ, bất ngờ bị kẻ gian hãm hại. Từ đó, giang hồ dậy sóng, mở ra hành trình đầy bi hài của hai huynh đệ vừa mới kết giao: Tổ Bi Thu và Trịnh Đông Đình. Đông Đình quyết định cùng sư đệ truy tìm tung tích người vợ mất tích và manh mối kẻ đã ra tay sát hại sư phụ. Nhưng trên đường đi, họ lại bị vu oan là hung thủ trong một vụ thảm sát, trở thành mục tiêu truy đuổi của nhiều môn phái. Càng tìm cách minh oan, mọi hiểu lầm càng chồng chất. Cuối cùng, nhờ thần kiếm Mãn Thiên Tinh, cả hai đánh bại được Cung Thiên Ảnh - kẻ chủ mưu đứng sau tất cả. Minh oan cho bản thân, họ tiếp tục dấn thân vào con đường trả thù, hướng về Côn Luân tìm Đốc Hồng Hoa.</p>', 'Tập 26', 26, 'hoathinh', 'ongoing', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xinran Yang","avatar":""},{"name":"Li Lanling","avatar":""},{"name":"Lin Maomao","avatar":""},{"name":"Chang Rongshan","avatar":""},{"name":"Ye Zhiqiu","avatar":""},{"name":"Sheng Feng","avatar":""},{"name":"Wu Feng Chun","avatar":""},{"name":"Peng Yao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Da Tang Cheng Feng Lu","The Tang Dynasty Chengfeng Record","Wind Driver in Tang Dynasty","Rise In The Wind of Great Tang","Records of the Tang Dynasty","大唐乘风录"]', 1784690324135);
