INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-tim-long-dien-huong', 'Truy Tìm Long Diên Hương', 'Fish, Fists And Ambergris', 'https://phimimg.com/upload/vod/20260305-1/0ed392d57a9e67bce3fee7955a903441.jpg', 'https://phimimg.com/upload/vod/20260305-1/f27e602f78ac25f30a12c985e91ede32.jpg', '<p>Một hành trình tìm lại bảo vật Long Diên Hương siêu quậy và siêu lầy lội đang chờ bạn ở phía trước. &nbsp;Quang Tuấn, Ma Ran Đô, Nguyên Thảo, Hoàng Tóc Dài, Doãn Quốc Đam,... đã sẵn sàng lên đường Truy Tìm Long Diên Hương.</p>', 'Full', 1, 'single', 'completed', 30, 2025, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Quang Tuấn","avatar":""},{"name":"Ma Ran Đô","avatar":""},{"name":"Nguyên Thảo","avatar":""},{"name":"Thanh Nam","avatar":""},{"name":"Hoàng Tóc Dài","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Fish, Fists and Ambergris","ปลา กำปั้น อำพันอลวน","Truy Tìm Long Diên Hương","Chase for Amber"]', 1784690324135);
