INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hon-bac-ty', 'Nụ Hôn Bạc Tỷ', 'Money Kisses', 'https://phimimg.com/upload/vod/20260305-1/edeff022ca9b19a349f3b899467df1f5.jpg', 'https://phimimg.com/upload/vod/20260305-1/277fff3f8a3f09efd03218b2ba176e5e.jpg', '<p>Câu chuyện xoay quanh Thúy Vân (Thiên Ân) và người chị &quot;trời đánh&quot; Thúy Kiều (Thu Trang) đang phải đối mặt với món nợ lớn do người tình gây ra. Đứng trước nguy cơ mất trắng, cả hai buộc phải vạch kế hoạch chinh phục &quot;Nụ Hôn Bạc Tỷ&quot; từ hai chàng thiếu gia Quang (Lê Xuân Tiền) và Tú (Ma Ran Đô).</p>', 'Full', 1, 'single', 'completed', 24, 2025, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Đoàn Thiên Ân","avatar":""},{"name":"Thu Trang","avatar":""},{"name":"Tiến Luật","avatar":""},{"name":"Lê Xuân Tiền","avatar":""},{"name":"Võ Tấn Phát","avatar":""},{"name":"Ma Ran Đô","avatar":""},{"name":"Huy Khánh","avatar":""},{"name":"Oanh Kiều","avatar":""},{"name":"Huỳnh Phương","avatar":""},{"name":"Tuyết Thu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Nụ Hôn Bạc Tỷ"]', 1784690324135);
