INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-trong-ban-nhac-ngan-vang-bat-tan', 'Bí Mật Trong Bản Nhạc Ngân Vang Bất Tận', 'Melody of Secrets', 'https://phimimg.com/upload/vod/20251209-1/ed59b9c7368b6b7a4a6cf0d644d11f80.jpg', 'https://phimimg.com/upload/vod/20251209-1/643b7a066d5afe3ceab401a128e977ae.jpg', '<p>Một điều gì đó thôi thúc phóng viên tội phạm Botpleng lên đường tìm kiếm người yêu của mình là Tankhun. Thế nhưng ký ức của cậu lại méo mó một cách kỳ lạ, khiến cậu không thể nhớ nổi gương mặt của anh ấy. Liệu Tankhun, nhà tội phạm học khẳng định mình chính là người yêu của Botpleng, có thật sự là con người mà anh ta nói?</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Jiratchapong Srisang","avatar":""},{"name":"Kasidet Plookphol","avatar":""},{"name":"Ployshompoo Supasap","avatar":""},{"name":"Noppanut Guntachai","avatar":""},{"name":"Patchatorn Thanawat","avatar":""},{"name":"Juthapich Indrajundra","avatar":""},{"name":"Piyamas Monayakul","avatar":""},{"name":"Kate Thiyada Phanbua","avatar":""},{"name":"Tawan Jarujinda","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["秘密旋律","Secrets in a Neverending Melody","ความลับในบทเพลงที่บรรเลงไม่รู้จบ"]', 1784690324135);
