INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-toai-tinh-ha', 'Võ Toái Tinh Hà', 'Shattering The Galaxy (Martial Conqueror Of The Cosmo)', 'https://phimimg.com/upload/vod/20250818-1/71f6369e317d9f8fcc9596b6ef8fcc82.jpg', 'https://phimimg.com/upload/vod/20250818-1/fd931c0b12a2dcce7021e37eae1c6129.jpg', '<p>Chàng thiếu niên nơi núi rừng tên Giang Hàn lên đường tu luyện để tìm cha mẹ, bất ngờ kích hoạt Thiên Thú Đỉnh mà mẹ để lại và thức tỉnh thần thông vô thượng! Từ đây, cậu nghịch thiên cải mệnh, chiến đấu cùng trời đất! Trên chiến trường nơi chư thần ngã xuống, Giang Hàn lấy máu mình mà quyết chiến với vạn tộc, dùng thân phận phàm nhân mở ra một con đường thông thiên! Thề vì nhân tộc mà giành lấy một tương lai huy hoàng!</p>', 'Tập 60', 80, 'hoathinh', 'ongoing', 20, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Martial Conqueror of the Cosmos","武碎星河"]', 1784690324135);
