INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-uong-sai', 'Tai Ương (Sai)', 'SAI: Disaster', 'https://phimimg.com/upload/vod/20260228-1/d3f7b95012fa624af76d8a51b6b2602e.jpg', 'https://phimimg.com/upload/vod/20260228-1/3572eee90ebba9a2083bab1ac065834e.jpg', '<p>Một người đàn ông bí ẩn xuất hiện trước sáu cá nhân, mỗi người trong số họ đều đang phải vật lộn với những vấn đề riêng của bản thân. Ngay lúc đó, một thảm họa sắp ập đến làm đảo lộn hoàn toàn cuộc sống của họ, dần mở ra những tình tiết treo lơ lửng và sự căng thẳng tột độ về mặt tâm lý.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Teruyuki Kagawa","avatar":""},{"name":"Anne Nakamura","avatar":""},{"name":"Pistol Takehara","avatar":""},{"name":"Ryuhei Matsuda","avatar":""},{"name":"Sena Nakajima","avatar":""},{"name":"Chika Uchida","avatar":""},{"name":"Miyachika Kaito","avatar":""},{"name":"Jiro","avatar":""},{"name":"Maki Sakai","avatar":""},{"name":"Yumi Adachi","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["連続ドラマW 災","Sai","災"]', 1784690324135);
