INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('quoc-bao', 'Quốc Bảo', 'Kokuho', 'quốc bảo kokuho ryo yoshizawa ryusei yokohama mitsuki takahata shinobu terajima soya kurokawa keitatsu koshiyama min tanaka ken watanabe nana mori takahiro miura ai mikami masatoshi nagase kyūsaku shimada emma miyazawa kumi takiuchi misa wada nagiko tsuji kokuho 國寶 kokuhō le maître du kabuki كوكوهو 국보 קוקוהו สมบัติชาติ національне надбання kokuho. nacionalinė vertybė 国宝', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-tan-ky-2025', 'Tầm Tần Ký', 'Back To The Past', 'https://phimimg.com/upload/vod/20260224-1/4ea4fdf8207637bc536915f13b873475.jpg', 'https://phimimg.com/upload/vod/20260224-1/5cc9d98eda5f989e06eb0fe1f6a2f64c.jpg', '<p>Sau khi Tần Thuỷ Hoàng đã thống nhất 6 nước, màn tái ngộ sau nhiều thập kỷ và cuộc xuyên không đi vào lịch sử hứa hẹn sẽ tạo nên cơn địa chấn tại rạp Việt. Một án oan từ nhiều năm trước đã châm ngòi cho cuộc khủng hoảng làm thay đổi vận mệnh lịch sử! Ken (do Miêu Kiều Vĩ thủ vai) thề sẽ xuyên không trở về thời nhà Tần để xưng vương, bù đắp cho cuộc đời đã bị cướp mất vì oan ngục. Ở thời Tần, gia đình Hạng Thiếu Long (do Cổ Thiên Lạc thủ vai) tuy đã lui về ẩn cư, nhưng mọi hành động vẫn không thể qua mắt đồ đệ của mình – Tần Vương (do Lâm Phong thủ vai). Đúng lúc Tần Vương tưởng rằng mình đã thống nhất lục quốc, xưng bá thiên hạ, thì bất ngờ đối mặt với cuộc tập kích của Ken.</p>', 'Full', 1, 'single', 'completed', 21, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 1, '[{"name":"Cổ Thiên Lạc","avatar":""},{"name":"Lâm Phong","avatar":""},{"name":"Bạch Bách Hà","avatar":""},{"name":"Tuyên Huyên","avatar":""},{"name":"Quách Thiện Ni","avatar":""},{"name":"Đằng Lệ Minh","avatar":""},{"name":"Miêu Kiều Vỹ","avatar":""},{"name":"Trương Kế Thông","avatar":""},{"name":"Chu Bá Hào","avatar":""},{"name":"Ngô Việt","avatar":""},{"name":"Hồng Thiên Minh","avatar":""},{"name":"Chris Collins","avatar":""},{"name":"Lưu Khải Trí","avatar":""},{"name":"Đặng Nhất Quân","avatar":""},{"name":"Michelle Saram","avatar":""},{"name":"Âu Thụy Vỹ","avatar":""},{"name":"Hoàng Văn Tiêu","avatar":""},{"name":"Trần Quốc Bằng","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["寻秦记","影版寻秦记","Back to the Past","尋秦記"]', 1784690324135);
