INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tam-tan-ky-2025', 'Tầm Tần Ký', 'Back To The Past', 'tầm tần ký back to the past cổ thiên lạc lâm phong bạch bách hà tuyên huyên quách thiện ni đằng lệ minh miêu kiều vỹ trương kế thông chu bá hào ngô việt hồng thiên minh chris collins lưu khải trí đặng nhất quân michelle saram âu thụy vỹ hoàng văn tiêu trần quốc bằng 寻秦记 影版寻秦记 back to the past 尋秦記', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-duong-luan-hoi', 'Ba Đường Luân Hồi', 'Under the Three Rivers', 'https://phimimg.com/upload/vod/20251207-1/d360d7630f92c0b4e106f6fd3f162b3f.jpg', 'https://phimimg.com/upload/vod/20251207-1/c4bba4c2126eb72d88a6f538bb85b265.jpg', '<p>Ba con sông Hoàng Hà, Trường Giang và Lan Thương có cùng chung một nguồn. Nhà họ Đinh, nhà họ Khương và nhà họ Dịch, ba gia tộc Thủy Quỷ sinh sống dọc theo những con sông ấy. Họ được trời phú cho khả năng tự do di chuyển dưới nước, lại tinh thông phong thuỷ, long mạch và thuật tìm báu vật. Dịch Táp là Thủy Quỷ cuối cùng của nhà họ Dịch, hiện đang quản lý “ngân hàng dưới nước” trên dòng sông Lan Thương. Trong một lần mở “Kim Thang”, kho báu dưới nước, cô bất ngờ cứu được Tông Hàng. Để phơi bày chân tướng vụ án năm xưa và bảo toàn mạng sống, Dịch Táp đã huấn luyện Tông Hàng trở thành một Thủy Quỷ thực thụ. Hai người họ cùng Thủy Quỷ Đinh Ngọc Điệp của nhà họ Đinh đã xông pha xuống dòng nước sâu để tiến vào &quot;Tổ Nguyên Kim Thang&quot;, kho báu của tổ tiên.</p>', 'Hoàn Tất (18/18)', 18, 'hoathinh', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["三线轮回","San Xian Lun Hui","Under the Three Rivers","三线轮洄"]', 1784690324135);
