INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ket-thuc-con-duong-tan-cung', 'Kết Thúc (Con Đường Tận Cùng)', 'It Ends', 'https://phimimg.com/upload/vod/20260224-1/bdea89f76777e1f6ed93a471ab78deed.jpg', 'https://phimimg.com/upload/vod/20260224-1/bdb8e2eff1b8137650dcc65167a9641a.jpg', '<p>Một nhóm sinh viên mới tốt nghiệp lái xe đi ăn khuya, với hy vọng có một buổi tụ tập cuối cùng trước khi mỗi người đi theo con đường riêng. Thay vào đó, họ vô tình rẽ vào một con đường hai làn xe dài vô tận, bao quanh bởi những nỗi kinh hoàng và thế lực vũ trụ vượt quá tầm hiểu biết của họ. Bị nhồi nhét vào trong chiếc Jeep Cherokee và với quãng đường phía trước trải dài vô tận, họ phải đối mặt với một lựa chọn: chấp nhận cuộc sống mới hay chiến đấu để thoát khỏi nó.</p>', 'Full', 1, 'single', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Phinehas Yoon","avatar":""},{"name":"Akira Jackson","avatar":""},{"name":"Noah Toth","avatar":""},{"name":"Mitchell Cole","avatar":""},{"name":"Jenny Doyle","avatar":""},{"name":"Jon Linstad","avatar":""},{"name":"Ian Weir","avatar":""},{"name":"Alexander Ullom","avatar":""},{"name":"Antonio Andrés Rosello","avatar":""},{"name":"Dakota Shiver","avatar":""},{"name":"Dennis Brewer","avatar":""},{"name":"Ethan Tramel","avatar":""},{"name":"Grace Wu","avatar":""},{"name":"Connor Flynn","avatar":""},{"name":"Helena Sadvary","avatar":""},{"name":"Jack McClellan","avatar":""},{"name":"John M. Maiers","avatar":""},{"name":"Kane B","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Всё заканчивается","It Ends"]', 1784690324135);
