INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('giao-lo-sullivan-phan-3', 'Giao Lộ Sullivan (Phần 3)', 'Sullivan''s Crossing (Season 3)', 'giao lộ sullivan (phần 3) sullivan''s crossing (season 3) morgan kohan chad michael murray scott patterson tom jackson andrea menard amalia williamson joel oulette lindura reid price 苏利文的十字路口 sullivan''s crossing', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-tieu-thu-va-chang-ve-si-ojo-to-bankenkun', 'Nàng Tiểu Thư Và Chàng Vệ Sĩ (Ojo to Banken-kun)', 'A Girl & Her Guard Dog', 'https://phimimg.com/upload/vod/20260222-1/8ca36aa6be791ac133762b14b861195b.jpg', 'https://phimimg.com/upload/vod/20260222-1/aafb9323c3baddce1967d2379dc1baf6.jpg', '<p>Senagaki Isaku gặp rắc rối trong việc kết bạn và không thể sống một cách &quot;bình thường&quot; vì mọi người e ngại xuất thân cháu gái ông trùm yakuza của cô. Isaku đăng ký vào học tại một trường cấp ba xa nhà với hi vọng sẽ có được cuộc sống học đường bình thường và để tiện cho việc che giấu tình cảm với chàng phó thủ lĩnh Uto Keiya, đồng thời cũng là vệ sĩ của cô. Tuy nhiên, Keiya lại cố tình trở thành bạn cùng lớp của cô vì bản tính chăm sóc quá mức trong anh khiến anh không yên tâm về cô. Cuộc sống học đường của hai người từ nay sẽ ra sao đây?</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Riko Fukumoto","avatar":""},{"name":"Jesse","avatar":""},{"name":"Kaito Sakurai","avatar":""},{"name":"Kanon","avatar":""},{"name":"Haruna Matsui","avatar":""},{"name":"Inoue Sora","avatar":""},{"name":"Gumpy","avatar":""},{"name":"Yo Aoi","avatar":""},{"name":"Yoji Iwase","avatar":""},{"name":"Nozomi Sasaki","avatar":""},{"name":"Kisuke Iida","avatar":""},{"name":"Tetta Sugimoto","avatar":""},{"name":"Asumi Miwa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ojo to Banken-kun","お嬢と番犬くん"]', 1784690324136);
