INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-cua-nhung-vi-vua-vua-cua-cac-vua', 'Vua Của Những Vị Vua (Vua Của Các Vua)', 'The King Of Kings', 'https://phimimg.com/upload/vod/20250708-1/8dd3eeb5d1ebb5d45fce1b2ec27bf166.jpg', 'https://phimimg.com/upload/vod/20250708-1/89473a8b979b437b2b176d539c894622.jpg', '<p>Trong một đêm yên bình, Charles Dickens kể cho con trai mình – cậu bé Walter – nghe câu chuyện vĩ đại nhất mọi thời đại. Nhưng câu chuyện ấy không chỉ dừng lại ở lời kể. Với trí tưởng tượng bay bổng, Walter bước vào thế giới của Chúa Giê-su – tận mắt chứng kiến những phép màu, cảm nhận nỗi đau của Ngài, và học được bài học sâu sắc nhất về tình yêu và sự hy sinh. Một câu chuyện về đức tin, sự cảm thông, và hành trình trưởng thành bắt đầu… từ chính trái tim của một người cha.</p>', 'Full', 1, 'hoathinh', 'completed', 27, 2025, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Hàn Quốc', 1, '[{"name":"Oscar Isaac","avatar":""},{"name":"Kenneth Branagh","avatar":""},{"name":"Uma Thurman","avatar":""},{"name":"Pierce Brosnan","avatar":""},{"name":"Roman Griffin Davis","avatar":""},{"name":"Forest Whitaker","avatar":""},{"name":"Ben Kingsley","avatar":""},{"name":"Mark Hamill","avatar":""},{"name":"Ava Sanger","avatar":""},{"name":"Jim Cummings","avatar":""},{"name":"Dee Bradley Baker","avatar":""},{"name":"Fred Tatasciore","avatar":""},{"name":"James Arnold Taylor","avatar":""},{"name":"Vanessa Marshall","avatar":""},{"name":"Mick Wingert","avatar":""},{"name":"Imari Williams","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu",