INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vua-cua-nhung-vi-vua-vua-cua-cac-vua', 'Vua Của Những Vị Vua (Vua Của Các Vua)', 'The King Of Kings', 'vua của những vị vua (vua của các vua) the king of kings oscar isaac kenneth branagh uma thurman pierce brosnan roman griffin davis forest whitaker ben kingsley mark hamill ava sanger jim cummings dee bradley baker fred tatasciore james arnold taylor vanessa marshall mick wingert imari williams the life of our lord el rey de reyes el rey de reyes der könig der könige királyok királya царь царей 萬王之王 예수의 생애 die koning van konings the king of kings', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nui-te-vong', 'Núi Tế Vong', 'Haunted Mountains: The Yellow Taboo', 'https://phimimg.com/upload/vod/20260221-1/c92baddae949c01a82fa6918bec36af0.jpg', 'https://phimimg.com/upload/vod/20260221-1/ea4a7062337e87df9ee416a5d6cd6578.jpg', '<p>Ở Đài Loan có một câu nói truyền miệng nổi tiếng về khu rừng dưới Núi Ngọc Sơn, rằng: “Nếu chẳng may lạc trong rừng mà thấy bóng người mặc áo mưa màu vàng thì tuyệt đối đừng đi theo.” Gia Minh (Lưu Dĩ Hào đóng), Ngọc Hân (Viên Lễ Lâm đóng) và An Vĩ (Tào Hựu Ninh đóng) là những người bạn thân trong câu lạc bộ leo núi ở trường đại học. Trong một chuyến leo núi, thay vì đi theo lộ trình ban đầu thì cả 3 lại liều lĩnh bước vào khu vực cấm đã được cảnh báo trong rừng và bị lạc đường. Mặc dù đã buộc những dải vải trắng dọc đường làm ký hiệu, nhưng họ vẫn cứ loanh quanh trở về nơi cũ như thể bị mắc kẹt trong một vòng lặp vô tận. Giữa lúc hỗn loạn, một bóng người mặc áo mưa màu vàng xuất hiện mơ hồ trong sương mù dày đặc mang lại hy vọng cho ba người. Không ngờ, những hiện tượng kỳ lạ liên tiếp xảy ra sau đó mới là bị kịch thật sự.</p>', 'Full', 1, 'single', 'completed', 19, 2025, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Tào Hựu Ninh","avatar":""},{"name":"Trần Nghiên Hy","avatar":""},{"name":"Tăng Kính Hoa","avatar":""},{"name":"Lưu Dĩ Hào","avatar":""},{"name":"Phó Mạnh Bách","avatar":""},{"name":"Lâm Triết Hy","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["黃衣小飛俠","Trapped in Yellow","Shan Chi Huang I Hsiao Fei Hsia","鬼指路","山忌 黃衣小飛俠"]', 1784690324136);
