INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-hon-dai-luc', 'Võ Hồn Đại Lục', 'The Legend Of Wuhun Continent', 'https://phimimg.com/upload/vod/20250924-1/b2df0a0af83d380c6f645ff02f52652e.jpg', 'https://phimimg.com/upload/vod/20250924-1/595bca41232c867b6a112857b97bb961.jpg', '<p>Bộ phim là một câu chuyện về hành trình xuyên không từ hiện đại đến với một đại lục bí ẩn có tên gọi là Võ Hồn của nhà bác học Sở Phong. Anh ta vốn dĩ thuộc về thế giới hiện đại của thế kỷ 21, nhưng vì quá tò mò với một viên thiên thạch mà được đặt tên là Kim Ô Lệnh, nên đã vô tình đánh thức được sức mạnh to lớn bên trong viên thiên thạch ấy và bị kéo đến với đại lục thần bí kia. Vậy đại lục thần bí ấy tại sao lại gọi là Võ Hồn ? Phải chăng con người nơi đây rèn luyện và chiến đấu bằng chính võ hồn hay là sử dụng cái gì ? Một con người thời hiện đại yếu ớt như Sở Phong sẽ phải làm sao để tồn tại được ở nơi xa lạ thần bí này ?&nbsp;</p>', 'Tập 48', 60, 'hoathinh', 'ongoing', 11, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["武魂大陆","Wuhun Dalu","The Legend of Wuhun Continent"]', 1784690324136);
