INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-doi-nao-toi-co-the-co-nguoi-yeu-hoac-co-the-la-co-watashi-ga-koibito-ni-nareru-wake-nai-jan-muri-muri', 'Không Đời Nào Tôi Có Thể Có Người Yêu! Hoặc Có Thể Là Có... (Watashi ga Koibito ni Nareru Wake Nai jan, Muri Muri!)', 'There''s No Freaking Way I''ll Be Your Lover! Unless...', 'https://phimimg.com/upload/vod/20251210-1/9ea61f89169d030e50a9944822af1d84.jpg', 'https://phimimg.com/upload/vod/20251210-1/f8dd5edc50a7c2e723ffb6fb442d1ccf.jpg', '<p>Renako Amaori quyết tâm bỏ lại cuộc sống trung học cô đơn, vụng về phía sau để trở thành một cô gái bình thường với những người bạn bình thường khi lên cấp ba.Mai Ouzuka xinh đẹp, tự tin, hoàn toàn trái ngược với Renako: giàu có, hướng ngoại và là một người mẫu thời trang thực thụ. Bất chấp sự khác biệt, hai cô gái nhanh chóng hình thành một mối liên kết tức thời.Renako nghĩ rằng cô có thể đã tìm thấy người bạn thân trong mơ của mình... cho đến khi lời tỏ tình lãng mạn của Mai khiến cô hoàn toàn bối rối.Renako muốn chứng minh với Mai rằng làm bạn thân (BFF) tốt hơn là làm bạn gái, nhưng Mai lại kiên quyết thuyết phục Renako rằng họ được định mệnh sắp đặt để trở thành người yêu.</p>', 'Hoàn Tất (17/17)', 17, 'hoathinh', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kanna Nakamura","avatar":""},{"name":"Saori Onishi","avatar":""},{"name":"Yukari Anzai","avatar":""},{"name":"Kana Ichinose","avatar":""},{"name":"Takako Tanaka","avatar":""},{"name":"Mayu Sagara","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["我怎么可能成为你的恋人，不行不行！(※不是不可能！？)","我们不可能成为恋人！绝对不行。 (※似乎可行？)","Watashi.ga.Koibito.ni.Nareru.Wake.Naijan.Murimuri.Muri.ja.Nakatta","Watashi ga Koibito ni Nareru Wakenai jan, Muri Muri！（Muri ja Nakatta！？）","我们不可能成为恋人！绝对不行。(※似乎可行!?)","Watashi ga Koibito ni Nareru Wakenaijan, Muri Muri","Watanare","Watashi ga Koibito ni Nareru Wake Naijan, Muri Muri! (※Muri Janakatta!?)","Watashi ga Koibito ni Nareru Wake Naijan, Muri Muri! Muri Janakatta!?","わたなれ","ให้เป็นแฟนได้ไง ไม่เอาไม่ไหวหรอก (หรือจะไหวนะ!?)","There''s No Way I Can Have a Lover! (※Or Maybe There Is?!)","わたしが恋人になれるわけないじゃん、ムリムリ！（※ムリじゃなかった!?）"]', 1784690324136);
