INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dep-tiem-ca-phe', 'Dẹp Tiệm Cà Phê', 'Close Ur Kopitiam', 'https://phimimg.com/upload/vod/20260219-1/e386776176e8019dee1c3d437ca4e5d2.jpg', 'https://phimimg.com/upload/vod/20260219-1/9256d4690178fd905a8b72733695ac92.jpg', '<p>Sau một lần chạm trán không vui với một người có ảnh hưởng gây bão truyền thông cho quán ăn gia đình, Bill và Yuriko phải bảo vệ danh tiếng của quán – và cả cuộc hôn nhân của họ.</p>', 'Full', 1, 'single', 'completed', 27, 2025, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Mayjune Tan","avatar":""},{"name":"Alvin Wong","avatar":""},{"name":"Mark Lee","avatar":""},{"name":"Jaspers Lai","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["关你茶室"]', 1784690324136);
