INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('badak', 'Badak', 'Badak', 'https://phimimg.com/upload/vod/20260219-1/1422280b108b684c51610dca10fd328e.jpg', 'https://phimimg.com/upload/vod/20260219-1/3ee7e4e8632c1c2ebb820fa85d25739b.jpg', '<p>Mirah mơ ước trở thành ngôi sao hip-hop, nhưng vấp phải rào cản từ người cha khiếm thính luôn che chở cho cô – người không hiểu được sức hút của dòng nhạc này.</p>', 'Full', 1, 'single', 'completed', 35, 2025, 'Vietsub', 'FHD', 'Singapore', 0, '[{"name":"Shaheizy Sam","avatar":""},{"name":"Aida Amron","avatar":""},{"name":"Wan Hanafi Su","avatar":""},{"name":"Hon Kahoe","avatar":""},{"name":"Tony Eusoff","avatar":""},{"name":"Alvin Wong","avatar":""},{"name":"Amanda Ang","avatar":""},{"name":"Joe Flizzow","avatar":""},{"name":"Theia Ela Yusnita","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["荣耀嘻哈","Badak"]', 1784690324136);
