INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('badak', 'Badak', 'Badak', 'badak badak shaheizy sam aida amron wan hanafi su hon kahoe tony eusoff alvin wong amanda ang joe flizzow theia ela yusnita 荣耀嘻哈 badak', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-de-tro-ve', 'Tiên Đế Trở Về', 'Back As Immortal Lord', 'https://phimimg.com/upload/vod/20251028-1/bc440421d8def2f8d5a3800429ff21eb.jpg', 'https://phimimg.com/upload/vod/20251028-1/7a5f722529d7a41363bed542095d47e1.jpg', '<p>Thực lực vi tôn, nhưng khi không còn thực lực nào nữa thì tự nhiên mọi bi kịch cứ vậy mà ập đến, đó cũng là điều dĩ nhiên xảy đến khi mà con người ta không còn sức mạnh để khẳng định lời nói và sức mạnh nữa. Đó cũng là đôi nét sơ qua về câu chuyện Tiên Đế Trở Về, với anh chàng Vân Thanh Nham đầy thú vị. Xuất phát là một người dân hết sức bình thường, chẳng qua là mang trong mình một chút thiên phú mà đã vô tình bị cuốn đến thế giới khác gọi là Tiên Giới. Tại đó, Vân Thanh Nham trở thành một trong 10 vị Tiên Đế lừng danh, sống một cuộc sống an nhàn đến phát chán, thêm với những điều phiền muộn của nơi đây và nỗi nhớ nhà không nguôi, sau 3000 năm dài đằng đẵng thì anh đã quyết định quay trở lại nhân gian, tìm lại gia đình và người thân của mình. Nhưng trên đường xuyên không trở về, vô vàn gian khó cứ luôn xảy đến, rồi lại bị đuổi đánh dữ dội, những tu vi và thần khí của Vân Thanh Nham bỗng chốc trở về con số 0.</p>', 'Tập 16', 24, 'hoathinh', 'ongoing', 12, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yang Chaoran","avatar":""},{"name":"Li Chanfei","avatar":""},{"name":"静宸","avatar":""},{"name":"黄进泽","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92