INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lenh-truy-na-giang-ho', 'Lệnh Truy Nã Giang Hồ', 'Wanted', 'https://phimimg.com/upload/vod/20250502-1/81f6b948b222b776344846c7d0b4e677.jpg', 'https://phimimg.com/upload/vod/20250502-1/4b164f44c3ea0bef442de6fc3b9fb333.jpg', '<p>Ba huynh đệ kết nghĩa nay trở mặt thành thù. Nhị ca Long Bất Nhiễm vì lòng tham và đố kỵ đã phản bội và tàn sát cả gia tộc Thẩm Nhất Diệp. Tam đệ Diệp Lương, sau khi rơi vào bước đường cùng đã quyết liệt phản kháng, liều mình giải cứu cháu gái duy nhất của đại ca. Anh dốc toàn lực chiến đấu để bảo vệ cô thoát khỏi vòng vây, chỉ vì một lời hứa năm xưa: &quot;Ngày sau nếu có việc cần nhờ, dù núi đao biển lửa, ta nhất định sẽ đến&quot;. Diệp Lương từ cõi chết trở về, cuối cùng tung đòn chí mạng, chấm dứt mọi ân oán với Long Bất Nhiễm.</p>', 'Full', 1, 'single', 'completed', 10, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Tử Hùng","avatar":""},{"name":"Hà Gia Kính","avatar":""},{"name":"Trương Mẫn","avatar":""},{"name":"Lưu Tích Minh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["江湖通缉令"]', 1784690324136);
