INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-tu-bi-giam-cam', 'Người Tù Bị Giam Cầm', 'The Captive', 'https://phimimg.com/upload/vod/20260213-1/05eda0c9946de07f660a4b12af3006a0.jpg', 'https://phimimg.com/upload/vod/20260213-1/486ad74183c6048c5738ca21b189ed83.jpg', '<p>Lấy bối cảnh năm 1575, bộ phim theo chân Miguel de Cervantes thời trẻ khi ông bị bắt làm tù binh và bán cho Hassan, Bá tước xứ Algiers, trong quãng thời gian chờ tiền chuộc giữa cảnh giam cầm khắc nghiệt, Cervantes tìm thấy nơi trú ẩn tinh thần trong nghệ thuật kể chuyện, dùng sức mạnh của trí tưởng tượng để nuôi dưỡng hy vọng sống sót</p>', 'Full', 1, 'single', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Julio Peña","avatar":""},{"name":"Alessandro Borghi","avatar":""},{"name":"Miguel Rellán","avatar":""},{"name":"Fernando Tejero","avatar":""},{"name":"Luis Callejo","avatar":""},{"name":"José Manuel Poga","avatar":""},{"name":"Roberto Álamo","avatar":""},{"name":"Albert Salazar","avatar":""},{"name":"Juanma Muniagurria","avatar":""},{"name":"César Saratxu","avatar":""},{"name":"Jorge Asín","avatar":""},{"name":"Mohamed Said","avatar":""},{"name":"Walid Charaf","avatar":""},{"name":"Luna Berroa","avatar":""},{"name":"Khaled Kouka","avatar":""},{"name":"Julien Paschal","avatar":""},{"name":"Thomas King","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["El cautivo"]', 1784690324136);
