INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-tu-bi-giam-cam', 'Người Tù Bị Giam Cầm', 'The Captive', 'người tù bị giam cầm the captive julio peña alessandro borghi miguel rellán fernando tejero luis callejo josé manuel poga roberto álamo albert salazar juanma muniagurria césar saratxu jorge asín mohamed said walid charaf luna berroa khaled kouka julien paschal thomas king el cautivo', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-chu', 'Vu Chú', 'Cursed Village', 'https://phimimg.com/upload/vod/20260213-1/2bd9e1a86c0250d546e74ea84978eb28.jpg', 'https://phimimg.com/upload/vod/20260213-1/dc94e66cfbb623e3f46b92cc809206e0.jpg', '<p>Bộ phim chuyển thể từ bí ẩn có thật về “Âm hôn hiến tế”. Tôi theo chân một phóng viên tới vùng đất đen để điều tra “lời nguyền Sơn Thần”, nhưng lại bị cuốn vào điều cấm kỵ kinh hoàng. Quan tài hỷ, chuông thầy cúng thường vang lên giữa đêm, nửa đêm thấy người giấy chuyển động; tỉnh dậy, tôi nằm trong quan tài, đối diện thi thể mở trừng mắt. Cuối cùng, sự thật lộ diện: những cô gái bị trúng tà đều là “cô dâu giấy”. Và tôi đã sớm bị chọn làm vật hiến tế. Khi mặt nạ quỷ của pháp sư áp sát, một tiếng thì thầm lạnh sống lưng vang lên: “Đến lượt ngươi rồi!”</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Nan Nan","avatar":""},{"name":"Điền Thi Vũ","avatar":""},{"name":"Trương Hạn Văn","avatar":""},{"name":"Lưu Vũ Phong","avatar":""},{"name":"Giang Cảnh Trung","avatar":""},{"name":"Hoàng Khuynh","avatar":""},{"name":"Quan Bằng","avatar":""},{"name":"Sinh Sinh","avatar":""},{"name":"Lưu Đệ","avatar":""},{"name":"Tống Trác Nhiên","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Cursed Village","巫咒"]', 1784690324136);
