INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vu-chu', 'Vu Chú', 'Cursed Village', 'vu chú cursed village vương nan nan điền thi vũ trương hạn văn lưu vũ phong giang cảnh trung hoàng khuynh quan bằng sinh sinh lưu đệ tống trác nhiên cursed village 巫咒', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-hanh-thien-ha-tro-lai-tam-ngan-dam-may-va-trang', 'Long Hành Thiên Hạ: Trở Lại Tám Ngàn Dặm Mây Và Trăng', 'Long''s Journey Of Poetic China', 'https://phimimg.com/upload/vod/20250929-1/d0ff12cc47da27c33bdaf350719e5421.jpg', 'https://phimimg.com/upload/vod/20250929-1/0af12d957d636f3329d5e9b543d1d8c8.jpg', '<p>Ba mươi năm trước, chương trình <em>Tám Ngàn Dặm Mây và Trăng</em> là chương trình Đài Loan đầu tiên hệ thống và toàn diện giới thiệu về phong cảnh, văn hóa và con người của Trung Quốc đại lục. Chương trình đã khắc họa hình ảnh núi sông hùng vĩ, phong tục tập quán cùng số phận con người, qua đó đem đến cho thế giới một Trung Quốc chân thật, sinh động và đầy sức sống. Ba mươi năm sau, <em>Long Hành Thiên Hạ: Trở Lại Tám Ngàn Dặm Mây và Trăng</em> tiếp tục hành trình xưa, mong muốn để đông đảo khán giả trong và ngoài nước hiểu rõ sự thay đổi to lớn của Trung Quốc đại lục trong hơn ba thập kỷ qua. Chương trình tái hiện chặng đường cũ với góc nhìn từ đồng bào hai bờ eo biển, tìm kiếm cội nguồn văn hóa chung và tình cảm dân tộc gắn kết hai bên.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Long Xing Tian Xia Zhi Chong Zou Ba Qian Li Lu Yun He Yue","隆行天下之重走八千里路云和月"]', 1784690324136);
