INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-bep-nha-ho-nguyen-dans-la-cuisine-des-nguyen', 'Căn Bếp Nhà Họ Nguyễn (Dans la cuisine des Nguyen)', 'In The Nguyen Kitchen', 'https://phimimg.com/upload/vod/20260213-1/c97055e774066649a3ec18fe0268e310.jpg', 'https://phimimg.com/upload/vod/20260213-1/56b18af948119208e12adcd667555f61.jpg', '<p>Yvonne Nguyen ấp ủ ước mơ theo đuổi sân khấu nhạc kịch nhưng luôn vấp phải sự phản đối của mẹ. Sự mâu thuẫn càng lúc càng khiến hai mẹ con đánh mất kết nối. Thông qua việc cùng nhau nấu những món ăn truyền thống, cả hai dần tìm được sự thấu hiểu lẫn nhau.</p>', 'Full', 1, 'single', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Clotilde Chevalier","avatar":""},{"name":"Camille Japy","avatar":""},{"name":"Leanna Chea","avatar":""},{"name":"Linh-Dan Pham","avatar":""},{"name":"Anh Tran-Nghia","avatar":""},{"name":"Marie-Thérèse Priou","avatar":""},{"name":"Gaël Kamilindi","avatar":""},{"name":"Thomas Jolly","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Dans la cuisine des Nguyen","In the Nguyen Kitchen"]', 1784690324136);
