INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-du-2025', 'Quỷ Dữ', 'Diablo', 'https://phimimg.com/upload/vod/20250619-1/1561a4b1b5befc1e9c9168b66ad65049.jpg', 'https://phimimg.com/upload/vod/20250619-1/2b7cfac7392c471df83e058348c7c80d.jpg', '<p>Một cựu tù nhân tên Kris Chaney bắt cóc con gái của một tay trùm tội phạm Colombia để thực hiện lời hứa cao cả với mẹ của cô bé. Khi người cha này huy động cả thế giới ngầm và một tên sát nhân tâm thần để trả thù, Kris buộc phải vận dụng tất cả kỹ năng và kinh nghiệm từng có để giữ mạng sống và thực hiện trọn lời hứa của mình.</p>', 'Full', 1, 'single', 'completed', 11, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Scott Adkins","avatar":""},{"name":"Marko Zaror","avatar":""},{"name":"Alanna de la Rosa","avatar":""},{"name":"Diana Hoyos","avatar":""},{"name":"Lucho Velasco","avatar":""},{"name":"María del Rosario","avatar":""},{"name":"Jason Gurvitz","avatar":""},{"name":"Juan Camilo Castillo","avatar":""},{"name":"Jason Gurvitz","avatar":""},{"name":"Jaime Correa","avatar":""},{"name":"Hedras Urrego","avatar":""},{"name":"Hamilton Casas","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["破坏神","迪亚波罗的复仇","Diablo"]', 1784690324136);
