INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-mau-co-the-gay-chet-nguoi', 'Dòng máu có thể gây chết người', 'Sons of the Neon Night', 'https://phimimg.com/upload/vod/20260210-1/e15ee164660c456a9e5ea9216691419a.jpg', 'https://phimimg.com/upload/vod/20260210-1/1fc2df2ff8a2dfc9e3de5812d9535986.jpg', '<p>Một vụ nổ lớn và cuộc đấu súng dữ dội ở Causeway Bay phủ đầy tuyết, Hồng Kông, đã hé lộ âm mưu của một người thừa kế tập đoàn dược phẩm. &nbsp;Cái chết của cha anh ta trong bệnh viện đã châm ngòi cho một cuộc chiến chống ma túy, &nbsp;làm bất ổn cả thế giới hợp pháp và tội phạm.</p>', 'Full', 1, 'single', 'completed', 16, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Takeshi Kaneshiro","avatar":""},{"name":"Sean Lau Ching-Wan","avatar":""},{"name":"Tony Leung Ka-fai","avatar":""},{"name":"Louis Koo","avatar":""},{"name":"Gao Yuanyuan","avatar":""},{"name":"Alex To","avatar":""},{"name":"Nina Paw Hei-Ching","avatar":""},{"name":"Wilson Lam Chun-Yin","avatar":""},{"name":"Lowell Lo Koon-Ting","avatar":""},{"name":"Jiang Peiyao","avatar":""},{"name":"Michelle Wai Si-Nga","avatar":""},{"name":"Kam Kwok-Leung","avatar":""},{"name":"Lo Hoi-Pang","avatar":""},{"name":"Tony Liu Tian-jue","avatar":""},{"name":"Carl Ng Ka-Lung","avatar":""},{"name":"C","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["霓虹夜之子","風林火山","Sons of the Neon Night"]', 1784690324136);
