INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-do-sieu-tran', 'Đụng Độ Siêu Trăn', 'Anaconda', 'https://phimimg.com/upload/vod/20260127-1/d323f98664ff74e5230d4568f40231d5.jpg', 'https://phimimg.com/upload/vod/20260127-1/77dcf424f5036b99140a47e16c23989a.jpg', '<p>Một nhóm bạn thân đang khủng hoảng tuổi trung niên quyết định lên đường vào rừng rậm để làm lại bộ phim yêu thích thời trẻ. Nhưng hành trình hoài niệm nhanh chóng biến thành cuộc chiến sinh tồn dữ dội, khi họ phải đối mặt với thiên tai, rắn khổng lồ, và cả những tên tội phạm nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 14, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Jack Black","avatar":""},{"name":"Paul Rudd","avatar":""},{"name":"Steve Zahn","avatar":""},{"name":"Thandiwe Newton","avatar":""},{"name":"Daniela Melchior","avatar":""},{"name":"Selton Mello","avatar":""},{"name":"Ice Cube","avatar":""},{"name":"Ione Skye","avatar":""},{"name":"Rui Ricardo Diaz","avatar":""},{"name":"John Billingsley","avatar":""},{"name":"Sebastian Sero","avatar":""},{"name":"Diego Arnary","avatar":""},{"name":"Dan Silveira","avatar":""},{"name":"Anna Francesca Armenia","avatar":""},{"name":"Jarred Blakiston","avatar":""},{"name":"John Voce","avatar":""},{"name":"Lisa Kay","avatar":""},{"name":"Ron Smy","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["อนาคอนดา เลื้อยสยองโลก","大蟒蛇","Anakonda","Anaconda"]', 1784690324136);
