INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('exit-8-ga-tau-vo-tan', 'Exit 8: Ga Tàu Vô Tận', 'Exit 8', 'https://phimimg.com/upload/vod/20250920-1/d351f8267126bc6f79be595b85c808dd.jpg', 'https://phimimg.com/upload/vod/20250920-1/4e2bc5fdd894c9c3faea0bbabf99666c.jpg', '<p>Bộ phim xoay quanh một chàng trai trẻ bị mắc kẹt trong một hành lang tàu điện ngầm vô tận và lạnh lẽo. Tại đây, anh chàng bất đắc dĩ phải tham gia vào một trò chơi tìm kiếm “lối ra số 8”. Vòng đầu tiên sẽ bắt đầu từ “lối ra số 0”, luật chơi tưởng chừng rất đơn giản: Đừng bỏ qua bất kỳ điều gì bất thường ở hành lang của mỗi lối ra. Nếu phát hiện điều gì sai, hãy lập tức quay đầu. Nếu không thấy gì thay đổi, cứ đi tiếp. Nhưng chỉ một lần lơ là, người chơi lập tức trở về điểm xuất phát. Giữa mê cung vô tận với những cơn ảo giác ập đến, liệu anh chàng có thể giành chiến thắng và trở về với thực tại?</p>', 'Full', 1, 'single', 'completed', 25, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 1, '[{"name":"Kazunari Ninomiya","avatar":""},{"name":"Yamato Kochi","avatar":""},{"name":"Naru Asanuma","avatar":""},{"name":"Kotone Hanase","avatar":""},{"name":"Nana Komatsu","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["8-ban Deguchi","8號出口","The Exit 8","8번 출구","Exit 8: Ga Tàu Vô Tận","A Saída 8","Hachiban Deguchi","Exit Eight","The Exit Eight","８番出口"]', 1784690324136);
