INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-2025', 'Điệp Viên', 'Dhurandhar', 'https://phimimg.com/upload/vod/20260210-1/0866f3daedd217f137dcf2bf527efc22.jpg', 'https://phimimg.com/upload/vod/20260210-1/3a3d75d03468e73ce8ef5e0c9b4c3ae3.jpg', '<p>Ajit Doval, điệp viên hàng đầu của Ấn Độ, thâm nhập vào lãnh thổ địch, liều lĩnh mọi thứ để thu thập thông tin tình báo và ngăn chặn một cuộc khủng hoảng lớn, củng cố vị thế của ông như &quot;James Bond của Ấn Độ&quot;.</p>', 'Full', 1, 'single', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Ranveer Singh","avatar":""},{"name":"Akshaye Khanna","avatar":""},{"name":"R. Madhavan","avatar":""},{"name":"Arjun Rampal","avatar":""},{"name":"Sanjay Dutt","avatar":""},{"name":"Sara Arjun","avatar":""},{"name":"Rakesh Bedi","avatar":""},{"name":"Danish Pandor","avatar":""},{"name":"Gaurav Gera","avatar":""},{"name":"Naveen Kaushik","avatar":""},{"name":"Saumya Tandon","avatar":""},{"name":"Manav Gohil","avatar":""},{"name":"Akash Khurana","avatar":""},{"name":"Aliraza Namdar","avatar":""},{"name":"Ankit Sagar","avatar":""},{"name":"Bimal Oberoi","avatar":""},{"name":"Asif Ali Haider Khan","avatar":""},{"name":"Ashwin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["征服者","黑境行者","Vankumatu","Patriotismo","دھرندھر","धुरंधर"]', 1784690324136);
