INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phien-toa-nuremberg', 'Phiên Tòa Nuremberg', 'Nuremberg', 'https://phimimg.com/upload/vod/20251226-1/8f7432051cbbd841126e2563fb8e452b.jpg', 'https://phimimg.com/upload/vod/20251226-1/1ba44d01a6ea25ad87c4a8637cb0c285.jpg', '<p>Một bác sĩ tâm thần Mỹ tại Đức sau chiến tranh phải thẩm định năng lực chịu trách nhiệm pháp lý của các tội phạm Quốc xã, đồng thời đối mặt với cuộc đấu trí căng thẳng và đầy mâu thuẫn đạo đức với Hermann Göring, cánh tay phải của Hitler.</p>', 'Full', 1, 'single', 'completed', 18, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Russell Crowe","avatar":""},{"name":"Rami Malek","avatar":""},{"name":"Michael Shannon","avatar":""},{"name":"Leo Woodall","avatar":""},{"name":"John Slattery","avatar":""},{"name":"Richard E. Grant","avatar":""},{"name":"Colin Hanks","avatar":""},{"name":"Mark O''Brien","avatar":""},{"name":"Lotte Verbeek","avatar":""},{"name":"Wrenn Schmidt","avatar":""},{"name":"Lydia Peckham","avatar":""},{"name":"Andreas Pietschmann","avatar":""},{"name":"Steven Pacey","avatar":""},{"name":"Peter Jordan","avatar":""},{"name":"Dan Cade","avatar":""},{"name":"Paul Antony-Barber","avatar":""},{"name":"Ralph Ber","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["纽伦堡","Nuremberg"]', 1784690324136);
