INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-dieu-cua-tinh-ban-di-roi-se-den', 'Giai Điệu Của Tình Bạn (Đi Rồi Sẽ Đến)', 'Merrily We Roll Along', 'https://phimimg.com/upload/vod/20260210-1/e2942c290544f0336452b61af19f1294.jpg', 'https://phimimg.com/upload/vod/20260210-1/01f370fa6f80a6ae0c3a27c11856ceeb.jpg', '<p>Tác phẩm kể về hành trình của Franklin Shepard theo cấu trúc thời gian đảo ngược: từ đỉnh cao thành công ở Hollywood trở về những ngày đầu tại Broadway. Qua từng mảnh ký ức, câu chuyện phơi bày cái giá của tham vọng, những mối quan hệ và lựa chọn đã định hình con người Frank. Phiên bản này là bản ghi hình trực tiếp của vở nhạc kịch Broadway đoạt giải Tony 2024.</p>', 'Full', 1, 'single', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jonathan Groff","avatar":""},{"name":"Lindsay Mendez","avatar":""},{"name":"Daniel Radcliffe","avatar":""},{"name":"Krystal Joy Brown","avatar":""},{"name":"Katie Rose Clarke","avatar":""},{"name":"Reg Rogers","avatar":""},{"name":"Sherz Aletaha","avatar":""},{"name":"Leana Rae Concepcion","avatar":""},{"name":"Coby Getzug","avatar":""},{"name":"Corey Mach","avatar":""},{"name":"Talia Simone Robinson","avatar":""},{"name":"Jamila Sabares-Klemm","avatar":""},{"name":"Evan Alexander Smith","avatar":""},{"name":"Brianna Stoute","avatar":""},{"name":"Christian","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["A Vida em Três Acordes","Merrily We Roll Along"]', 1784690324136);
