INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhu-thuo-ban-dau', 'Như Thuở Ban Đầu', 'Reloved', 'https://phimimg.com/upload/vod/20251201-1/8801bd8b054269525b157fdf3dd486a7.jpg', 'https://phimimg.com/upload/vod/20251201-1/9e9310b0cec7058d4fd9dbf32556f6c4.jpg', '<p>Một ông bố đơn thân đang cố gắng cân bằng cuộc sống với vai trò làm cha vừa mới mẻ đã tình cờ gặp lại người yêu cũ thất lạc bấy lâu.&nbsp; Cuộc tái ngộ này không chỉ hâm nóng lại những cảm xúc cũ mà còn hé lộ sự thật đằng sau mối tình tan vỡ của họ trong quá khứ.</p>', 'Tập 10', 10, 'series', 'ongoing', 18, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Kunavut Jirattikorn","avatar":""},{"name":"Paratthakorn Duangsawang","avatar":""},{"name":"Apisit Sangming","avatar":""},{"name":"Chotritud Jettamrongchai","avatar":""},{"name":"Tanatcha Devahastin","avatar":""},{"name":"Kittaya Iemnopmanee","avatar":""},{"name":"Paraphat Phaennapakanok","avatar":""},{"name":"Chattiwut Rungrojsuporn","avatar":""},{"name":"Rusameekae Fagerlund","avatar":""},{"name":"Chulkiat Arathorn Chitvarodom","avatar":""},{"name":"Leia Lalinda Tanpras","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["เริ่มใหม่หัวใจเดิม"]', 1784690324136);
