INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-duyen-manbo', 'Kỳ Duyên Manbo', 'Manbo Destiny', 'https://phimimg.com/upload/vod/20251223-1/ccafbbdc3588f088ccb2e543a766ffb1.jpg', 'https://phimimg.com/upload/vod/20251223-1/8efb12fb69cb0071e8e644c3f1acdc48.jpg', '<p>Quan Manh Manh là một cô gái Trung Quốc mang trong mình khao khát khởi nghiệp trong lĩnh vực thương mại điện tử xuyên biên giới. Cô mang theo ước mơ ấy đặt chân đến nước Manbo, nhưng rồi lại bị người yêu phản bội. Bao nhiêu thành quả vất vả gây dựng được tiêu tan thành mây khói. Tình cờ thay, khi mưu tính trả thù, cô cùng với Đại hoàng tử Song Pai của Manbo đã bị sát thủ truy đuổi và buộc phải bỏ trốn.</p>', 'Tập 8', 24, 'series', 'ongoing', 19, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Từ Chí Hiền","avatar":""},{"name":"Nguyên Nghệ Triển","avatar":""},{"name":"Trần Tuệ Nghiên","avatar":""},{"name":"Đổng Tử Minh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wang Fei Ri Ji","王妃日记","Princess'' Diary","曼波奇缘"]', 1784690324136);
