INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('911-nashville', '9-1-1: Nashville', '9-1-1: Nashville', 'https://phimimg.com/upload/vod/20251013-1/9aa5f46225abda60361622e69f523750.jpg', 'https://phimimg.com/upload/vod/20251013-1/9c28c9a095a1af4a4d210dfa055eb57d.jpg', '<p>Hãy theo chân những nhân viên cứu hộ anh hùng, cùng câu chuyện gia đình của họ đầy quyền lực và hào nhoáng, diễn ra tại một trong những thành phố đa dạng và sôi động nhất nước Mỹ — Nashville, Tennessee.</p>', 'Tập 10', 12, 'series', 'ongoing', 19, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Chris O''Donnell","avatar":""},{"name":"Jessica Capshaw","avatar":""},{"name":"Kimberly Williams-Paisley","avatar":""},{"name":"LeAnn Rimes","avatar":""},{"name":"Michael Provost","avatar":""},{"name":"Juani Feliz","avatar":""},{"name":"Hailey Kilgore","avatar":""},{"name":"Hunter McVey","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["911 - Nashville","9-1-1 Nashville","9-1-1: Nashville"]', 1784690324136);
