INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tru-ac-nhan-gian', 'Trừ Ác Nhân Gian', 'Purge The World Of Evil', 'https://phimimg.com/upload/vod/20260208-1/8f08fc2a9fa5c9354da9a051edddf9d2.jpg', 'https://phimimg.com/upload/vod/20260208-1/cf33acbbb79e98260eaea61d605c9362.jpg', '<p>Vào những năm đầu thời Dân Quốc, thổ phỉ hoành hành khắp nơi. Đao khách Ngô Tân sau khi tận mắt chứng kiến người thân bị thổ phỉ sát hại đã chìm trong tuyệt vọng. Vài tháng sau, anh đã giết Hổ Tử, con trai thủ lĩnh bọn chúng để cứu thiếu nữ A Kha bị bọn thổ phỉ hành hạ dã man. Điều đó đã châm ngòi cho cuộc tàn sát cả ngôi làng. Trong giờ phút sinh tử, Ngô Tân một lần nữa cầm lại đao cung, hóa thành chiến thần trừ ác, dẫn dắt những người dân đang ở bước đường cùng phát động phản kháng quyết liệt chống lại thế lực tàn ác. Cuối cùng, trong trận chiến đẫm máu ở ngõ hẻm, anh đã kết liễu Diêm Bá Thiên, chấm dứt nỗi thống khổ của dân làng.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tuệ Kính Nguyên","avatar":""},{"name":"Tiết Thiên Thiên","avatar":""},{"name":"Trương Lâm","avatar":""},{"name":"Mao Dịch Mộc","avatar":""},{"name":"Đào Hành Ngư","avatar":""},{"name":"Khưu Tử Hinh","avatar":""},{"name":"Cao Gia Kỳ","avatar":""},{"name":"Vương Hải Nghiên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324136);
