INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tru-ac-nhan-gian', 'Trừ Ác Nhân Gian', 'Purge The World Of Evil', 'trừ ác nhân gian purge the world of evil tuệ kính nguyên tiết thiên thiên trương lâm mao dịch mộc đào hành ngư khưu tử hinh cao gia kỳ vương hải nghiên ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thai-binh-tran-ky-dam', 'Thái Bình Trấn Kỳ Đàm', 'Strange Tales Of Taiping Town', 'https://phimimg.com/upload/vod/20260208-1/5f460679259143e9c647c16ab9197592.jpg', 'https://phimimg.com/upload/vod/20260208-1/688644c62b41bf93e98d3f39e5c01720.jpg', '<p>Vào những năm Dân Quốc, tại trấn Thái Bình liên tiếp xảy ra các vụ án mạng kỳ quái, khiến dân chúng hoang mang tột độ. Trong dân gian lan truyền lời đồn rằng ác quỷ đòi mạng. Thám tử ngoại cảm Tần Mục cùng Tiểu Thần Bà lần theo manh mối và phát hiện kẻ đứng sau mọi chuyện chính là Kim Yến Tử trong truyền thuyết. Bằng kinh nghiệm phá án sâu rộng và khả năng phân tích xuất sắc, họ lần lượt phá giải chuỗi án mạng quỷ dị ở trấn Thái Bình, đồng thời lật mở thảm án xảy ra năm năm trước, trả lại công lý cho người đã khuất và bình yên cho bách tính.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ứng Hạo Minh","avatar":""},{"name":"Thị Tuyên Như","avatar":""},{"name":"Lý Mục Tư","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324136);
