INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-chu-kim-co-nui-bat-phap', 'Tân Chú Kim Cô: Núi Bất Pháp', 'The Real Monkey King: Bufashan', 'https://phimimg.com/upload/vod/20260208-1/a0a70842144bc20eb9aa1a75681080da.jpg', 'https://phimimg.com/upload/vod/20260208-1/1be7b15b1ae0415d698c2991ca03cd8a.jpg', '<p>Năm trăm năm trước, Tề Thiên Đại Thánh bị lòng bàn tay Như Lai chia làm hai nửa: phần Phật tính của Ngộ Không bị đè dưới núi Ngũ Hành, còn phần Ma tính lại trốn thoát đến vùng đại mạc và bị các lộ thần tiên truy sát. Quan Âm đã dùng bát vàng hóa thành một quán trọ để phong ấn Yêu hầu bên trong, pháp ấn tạo thành dãy núi Bất Pháp Sơn. Trong vòng năm trăm dặm quanh đây, bất kể thần tiên hay yêu quái khi đặt chân tới đều sẽ bị mất sạch pháp lực. Quan Âm đại sĩ báo cho Yêu hầu biết, năm trăm năm sau, khi hoa nở cũng là ngày hắn được giải phong. Năm trăm năm sau, Tôn Ngộ Không phò tá Đường Tăng đi thỉnh kinh, trừ yêu diệt ma, danh tiếng lẫy lừng. Yêu hầu trong quán trọ nghe tin thế gian còn có một Tề Thiên Đại Thánh khác sắp đi ngang qua đây, liền quyết tâm phải phân định thắng thua với Ngộ Không này. Cùng lúc đó, thầy trò Đường Tăng biết rõ không thể dùng pháp lực tại Bất Pháp Sơn nên đã chia nhau cải trang, lẻn vào quán trọ. Những lộ yêu ma thèm khát thịt Đường Tăng cũng tấp nập kéo đến, quyết định ra tay tại đây. Một trận huyết chiến sắp bắt đầu, tất cả mọi người bị kẹt lại trong quán trọ, và thế là một ván bài &#39;Ma Sói&#39; phiên bản Tây Du chính thức bắt đầu!</p>', 'Full', 1, 'single', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đi-lan","avatar":""},{"name":"Rồi-i","avatar":""},{"name":"Diên Kiệt","avatar":""},{"name":"Nam Phúc Long","avatar":""},{"name":"Công Hải Bân","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["jin gu zhou zhi bu fa shan","jin.gu.zhou.zhi.bu.fa.shan","紧箍咒之不法山"]', 1784690324136);
