INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-nu-truyen', 'Ma Nữ Truyện', 'Witch Legend', 'https://phimimg.com/upload/vod/20260208-1/f37c3aede7da6cb68ce0fa00cdecb3b8.jpg', 'https://phimimg.com/upload/vod/20260208-1/5313a1e2d8d8b7f3e39d92ff6b681898.jpg', '<p>Vào đầu triều Minh, đám người chưởng môn Động Đình Môn là Hàn Băng cùng Lưu Bằng Cử, Hoàng Thực Hiên kết nghĩa thành Sở Thiên Thất Nghĩa, trong đó Hàn Băng đứng thứ bảy. Hàn Băng đem lòng yêu nữ đệ tử phái Dược Tiên là Thủy Tiên Hồng. Khi bàn tính chuyện hôn sự, sáu vị đại ca của Sở Thiên Thất Nghĩa lại vì thành kiến môn phái đối với Dược Tiên mà nhất mực phản đối hôn sự này. Cũng từ đây, một câu chuyện bi thương thấu trời đất được mở ra…</p>', 'Full', 1, 'single', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cẩn Tuyết","avatar":""},{"name":"Vương Vũ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["魔女传"]', 1784690324136);
