INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-ran-khong-lo', 'Đảo Rắn Khổng Lồ', 'Island Python', 'https://phimimg.com/upload/vod/20250204-1/c52d14f7b43119f4974543af492d4aee.jpg', 'https://phimimg.com/upload/vod/20250204-1/4a2bea191ffbdf6af6c67d1a42b82695.jpg', '<p>Tập đoàn Lam Sơn muốn biến con phố Hướng Dương tĩnh mịch và yên bình thành một khu du lịch nghỉ dưỡng, lấy danh nghĩa phục hồi hệ sinh thái tự nhiên để ép buộc người dân di dời. Tuy nhiên, các mẫu sinh vật từ cơ sở nghiên cứu đã thoát ra ngoài, gây ra thảm họa sinh học. Nam chính Hàn Kiệt, trong hoàn cảnh nguy hiểm, không hề nao núng mà bảo vệ hai cô con gái và những người hàng xóm. Bằng hành động thực tế của mình, anh dần dần thay đổi những người xung quanh. Cuối cùng, tập đoàn Lam Sơn đã phải chịu hình phạt thích đáng.</p>', 'Full', 1, 'single', 'completed', 13, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 1, '[{"name":"Dương Phàm","avatar":""},{"name":"Tưởng Vận Tây","avatar":""},{"name":"Lý La Oa","avatar":""},{"name":"Vương An Kỳ","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["海岛巨蟒"]', 1784690324136);
