INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-cua-no-le-gia-toc-ashur', 'Cuộc Chiến Của Nô Lệ: Gia Tộc Ashur (Spartacus: Gia Tộc Ashur)', 'Spartacus: House Of Ashur', 'https://phimimg.com/upload/vod/20251207-1/1acb47556012c3221ae401f5e4251b28.jpg', 'https://phimimg.com/upload/vod/20251207-1/8a900bde610a19233c4be6cdf613e48c.jpg', '<p>Trong một thế giới mà hắn đã sống sót sau sự kiện Spartacus (2010), Ashur đã giành được quyền lực, sở hữu chính đấu trường Ludus mà hắn từng sở hữu. Liên minh với một nữ đấu sĩ hung dữ, Ashur tạo ra một màn trình diễn mới khiến giới thượng lưu phải phẫn nộ.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 11, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Nick E. Tarabay","avatar":""},{"name":"Graham McTavish","avatar":""},{"name":"Tenika Davis","avatar":""},{"name":"Jamaica Vaughan","avatar":""},{"name":"Ivana Baquero","avatar":""},{"name":"Jordi Webber","avatar":""},{"name":"Claudia Black","avatar":""},{"name":"India Shaw-Smith","avatar":""},{"name":"Leigh Gill","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["斯巴达克斯：亚述家族","Spartacus Das Haus Ashur","سبارتاكوس: بيت آشور","Spartacus: House of Ashur"]', 1784690324136);
