INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ai-cung-biet-juan', 'Ai Cũng Biết Juan', 'Everyone Knows Every Juan', 'https://phimimg.com/upload/vod/20260207-1/ca9272f8a3f3cfb2dbfd92626512e314.jpg', 'https://phimimg.com/upload/vod/20260207-1/087cbb3d999a8179d8f1667b5eb7d207.jpg', '<p>Anh chị em nhà Sevilla đoàn tụ tại ngôi nhà tổ tiên một năm sau sự ra đi của người mẹ (người đứng đầu gia đình). Những gì bắt đầu như một cuộc gặp mặt bắt buộc đã nhanh chóng biến thành một cơn bão của những tiết lộ, sự hận thù và cả những tiếng cười, phơi bày những sợi dây liên kết mong manh đang ràng buộc họ với nhau.</p>', 'Full', 1, 'single', 'completed', 32, 2025, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Edu Manzano","avatar":""},{"name":"Joel Torre","avatar":""},{"name":"Gina Alajar","avatar":""},{"name":"Alessandra de Rossi","avatar":""},{"name":"JM de Guzman","avatar":""},{"name":"Ronnie Lazaro","avatar":""},{"name":"Ruby Ruiz","avatar":""},{"name":"Angeli Bayani","avatar":""},{"name":"Kelvin Miranda","avatar":""},{"name":"Liza Lorena","avatar":""},{"name":"Empoy Marquez","avatar":""},{"name":"Jaime Fabregas","avatar":""},{"name":"Kim Molina","avatar":""},{"name":"Jerald Napoles","avatar":""},{"name":"Atasha Muhlach","avatar":""},{"name":"Geraldine Villamil","avatar":""},{"name":"Charlize Ruth Rey","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324136);
