INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ta-o-thien-dinh-thu-phe-pham-toi-thu-mua-phe-lieu-o-thien-dinh', 'Ta Ở Thiên Đình Thu Phế Phẩm (Tôi Thu Mua Phế Liệu Ở Thiên Đình)', 'Recycling Scrap in the Celestial Court (Heaven Scrap Master)', 'https://phimimg.com/upload/vod/20250928-1/0bd472f83f52bc4fddc60af748681252.jpg', 'https://phimimg.com/upload/vod/20250928-1/fc897b8d00a63c3a24f65f279424298e.jpg', '<p>Trong thế giới võ đạo đương thời, Triệu Tín tình cờ được thừa kế Trạm Tái Chế Thiên Đình, từ kẻ bị coi thường trở thành nhân vật được chư tiên giúp đỡ, mỹ nhân vây quanh, từ đó bước lên đỉnh cao võ đạo, trảm yêu trừ ma, danh chấn thiên hạ.</p>', 'Hoàn Tất (40/40)', 40, 'hoathinh', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["我在天庭收废品"]', 1784690324136);
