INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ta-o-thien-dinh-thu-phe-pham-toi-thu-mua-phe-lieu-o-thien-dinh', 'Ta Ở Thiên Đình Thu Phế Phẩm (Tôi Thu Mua Phế Liệu Ở Thiên Đình)', 'Recycling Scrap in the Celestial Court (Heaven Scrap Master)', 'ta ở thiên đình thu phế phẩm (tôi thu mua phế liệu ở thiên đình) recycling scrap in the celestial court (heaven scrap master)  我在天庭收废品', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuy-trieu-tinh-yeu-phan-1', 'Thủy Triều Tình Yêu (Phần 1)', 'Tide Of Love (Season 1)', 'https://phimimg.com/upload/vod/20251117-1/39ea5e9d11c66d9ceaa5e806446d300f.jpg', 'https://phimimg.com/upload/vod/20251117-1/efc234e8d5dbf8fa3002a61d6815792a.jpg', '<p>Han Jae-hoon là một người thừa kế giàu có, che giấu nỗi đau của mình sau vẻ ngoài lạnh lùng và thờ ơ. Trong khi đó, Kim Hae-jun là một sinh viên nghệ thuật tươi sáng nhưng lại nặng gánh bởi áp lực cuộc sống.Mối quan hệ của họ bắt đầu như một giao dịch, nhưng dần dần biến thành một mối liên kết dịu dàng. Trong sự cô độc sẻ chia và sự quan tâm không lời, họ từ từ xích lại gần nhau. Tuy nhiên, chính điều ràng buộc họ lại ngăn cản họ đối diện với cảm xúc thật của mình.Khi sóng gió nổi lên và những bí mật được phơi bày, họ phải đưa ra quyết định: Liệu họ sẽ tiếp tục bị giới hạn bởi những luật lệ, hay sẽ dám yêu thương?</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Hyun-seo","avatar":""},{"name":"Jung Myeong-cheol","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["타이드오브러브 시즌2","漲潮時接吻第二季","Tide of Love S2","타이드 오브 러브"]', 1784690324136);
