INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sup-do-phan-2', 'Sụp Đổ (Phần 2)', 'Fallout (Season 2)', 'https://phimimg.com/upload/vod/20251218-1/edf322e64d437755bd03623d7c8298a5.jpg', 'https://phimimg.com/upload/vod/20251218-1/97fcfb8cfdae35b08e3b22a7e3fd3b5a.jpg', '<p>Dựa trên một trong những loạt trò chơi điện tử ăn khách nhất mọi thời đại, Sụp đổ là câu chuyện về những thứ người ta có và không có trong một thế giới gần như chẳng còn lại gì. 200 năm sau ngày tận thế, một cư dân ôn hòa sống trong hầm tránh phóng xạ ấm cúng buộc phải quay trở lên mặt đất – và bị sốc khi phát hiện vùng hoang tàn này đang chờ đợi cô.</p>', 'Tập 8', 11, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ella Purnell","avatar":""},{"name":"Aaron Moten","avatar":""},{"name":"Moisés Arias","avatar":""},{"name":"Walton Goggins","avatar":""},{"name":"Frances Turner","avatar":""},{"name":"Kyle MacLachlan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["辐射","Fallout"]', 1784690324136);
