INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-chung-kiet-suc', 'Hội Chứng Kiệt Sức', 'Burnout Syndrome', 'https://phimimg.com/upload/vod/20251128-1/367240597573d003c0612eeacbbe42ad.jpg', 'https://phimimg.com/upload/vod/20251128-1/605ebd89ca08a5810e3f91f2985c0813.jpg', '<p>Sau khi mất đi công việc mơ ước, một họa sĩ kiệt sức rơi vào mối quan hệ tay ba với hai người đàn ông: một người là anh chàng IT quyến rũ, và người còn lại là một ông trùm ẩn dật, người đã thuê anh làm &quot;bộ mặt đại diện&quot; cho mình trước công chúng.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 19, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Atthaphan Phunsawat","avatar":""},{"name":"Jumpol Adulkittiporn","avatar":""},{"name":"Jirawat Sutivanichsak","avatar":""},{"name":"Thasorn Klinnium","avatar":""},{"name":"Thinnaphan Tantui","avatar":""},{"name":"Chayapol Jutamas","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["燃情竭爱","เบิร์นเอาท์ ซินโดรม","倦怠综合征","Burnout Syndrome","ภาวะรักคนหมดไฟ"]', 1784690324136);
