INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-trai-cua-shakespeare', 'Con trai của Shakespeare', 'Hamnet', 'https://phimimg.com/upload/vod/20260204-1/f0b711c6e845cb4b6fa777636f242422.jpg', 'https://phimimg.com/upload/vod/20260204-1/a12980fc990c828ef77091e25698bf50.jpg', '<p>Câu chuyện mạnh mẽ về tình yêu và mất mát đã truyền cảm hứng cho sự ra đời của kiệt tác bất hủ Hamlet của Shakespeare.</p>', 'Full', 1, 'single', 'completed', 22, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Jessie Buckley","avatar":""},{"name":"Paul Mescal","avatar":""},{"name":"Emily Watson","avatar":""},{"name":"Joe Alwyn","avatar":""},{"name":"Jacobi Jupe","avatar":""},{"name":"Noah Jupe","avatar":""},{"name":"Bodhi Rae Breathnach","avatar":""},{"name":"Olivia Lynes","avatar":""},{"name":"David Wilmot","avatar":""},{"name":"Justine Mitchell","avatar":""},{"name":"Faith Delaney","avatar":""},{"name":"Smylie Bradwell","avatar":""},{"name":"El Simons","avatar":""},{"name":"Freya Hannan-Mills","avatar":""},{"name":"Dainton Anderson","avatar":""},{"name":"Sam Woolf","avatar":""},{"name":"Jack Shalloo","avatar":""},{"name":"Lau","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Хамнет","햄닛","Хэмнет","Гамнет","แฮมเน็ต","ハムネット","Hamnet"]', 1784690324136);
