INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-nay-dau-tinh-yeu-nay-bien-mat-khoi-the-gian-2025', 'Đêm Nay Dẫu Tình Yêu Này Biến Mất Khỏi Thế Gian', 'Even If This Love Disappears Tonight', 'https://phimimg.com/upload/vod/20260204-1/eb87122248a7305d2b5eb86a48bc5014.jpg', 'https://phimimg.com/upload/vod/20260204-1/46596119a12881859c77a748449c10e7.jpg', '<p>Một chàng trai có bí mật kinh hoàng. Một cô gái có trí nhớ bị xóa sạch mỗi ngày. Khi họ bước vào mối quan hệ không ngờ tới, liệu tình yêu có thể giúp họ vượt qua nghịch cảnh?</p>', 'Full', 1, 'single', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Choo Young-woo","avatar":""},{"name":"Shin Sia","avatar":""},{"name":"Cho Yu-jung","avatar":""},{"name":"Jin Ho-eun","avatar":""},{"name":"Cho Han-cheul","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324136);
