INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dem-nay-dau-tinh-yeu-nay-bien-mat-khoi-the-gian-2025', 'Đêm Nay Dẫu Tình Yêu Này Biến Mất Khỏi Thế Gian', 'Even If This Love Disappears Tonight', 'đêm nay dẫu tình yêu này biến mất khỏi thế gian even if this love disappears tonight choo young-woo shin sia cho yu-jung jin ho-eun cho han-cheul ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-hau-gai-2025', 'Cô Hầu Gái', 'The Housemaid', 'https://phimimg.com/upload/vod/20260203-1/907cb7ebef814b452b41c8e6bf2373cf.jpg', 'https://phimimg.com/upload/vod/20260203-1/485188e8b453f8f227cb0bcc663e2700.jpg', '<p>Từ đạo diễn Paul Feig, một thế giới hỗn loạn sẽ mở ra, nơi sự hoàn hảo chỉ là ảo giác và mọi thứ dường như đều đang che đậy một bí mật đằng sau. Để chạy trốn khỏi quá khứ, Millie (Sydney Sweeney) trở thành bảo mẫu cho gia đình Nina (Amanda Seyfried) và Andrew (Brandon Sklener), một cặp đôi giàu có. Nhưng ngay khi cô chuyển vào sống chung và bắt đầu công việc &quot;trong mơ&quot;, sự thật dần được hé lộ - đằng sau vẻ ngoài xa hoa lộng lẫy là mối nguy lớn hơn bất cứ thứ gì Millie có thể tưởng tượng. Một trò chơi đầy cám dỗ của bí mật và quyền lực sắp bắt đầu.</p>', 'Full', 1, 'single', 'completed', 31, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Sydney Sweeney","avatar":""},{"name":"Amanda Seyfried","avatar":""},{"name":"Brandon Sklenar","avatar":""},{"name":"Michele Morrone","avatar":""},{"name":"Indiana Elle","avatar":""},{"name":"Sarah Cooper","avatar":""},{"name":"Elizabeth Perkins","avatar":""},{"name":"Ellen Tamaki","avatar":""},{"name":"Megan Ferguson","avatar":""},{"name":"Amanda Joy Erickson","avatar":""},{"name":"Alaina Surgener","avatar":""},{"name":"Peter Colandro","avatar":""},{"name":"Alexandra Seal","avatar":""},{"name":"Lamar Baucom-Slaughter","avatar":""},{"name":"Don DiPetta","avatar":""},{"name":"Kath","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["La asistenta