INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-hau-gai-2025', 'Cô Hầu Gái', 'The Housemaid', 'cô hầu gái the housemaid sydney sweeney amanda seyfried brandon sklenar michele morrone indiana elle sarah cooper elizabeth perkins ellen tamaki megan ferguson amanda joy erickson alaina surgener peter colandro alexandra seal lamar baucom-slaughter don dipetta kath la asistenta a empregada горничная 女佣 女仆 ความลับแม่บ้านร้าย una di famiglia la femme de ménage الخادمة خدمتکار 하우스메이드 кућна помоћница служниця the housemaid – wenn sie wüsste la empleada neskamea a criada kotiapulainen עוזרת הבית прислужницата 家弑服务 家弒服務 美傭誘罪 kućna pomoćnica მოახლე η αγγελία the housemaid: a téboly otthona mājkalpotāja tarnaitė pomoc domowa menajera hišna pomočnica pomocnice hizmetçi cô hầu gái pembantu the housemaid', '');
