INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngao-the-dan-than', 'Ngạo Thế Đan Thần', 'World Defying Dan God (The Alchemist''s Rise)', 'https://phimimg.com/upload/vod/20251211-1/080116ae369c3b088d3d3992b232682b.jpg', 'https://phimimg.com/upload/vod/20251211-1/2a40b5cf98c8efe66ac8dd89684f6d56.jpg', '<p>Trên đại lục Thần Khải, Thẩm Tường bị coi là phế vật vì sinh ra đã mang khiếm khuyết không có linh mạch. Quyết tâm khai thông linh mạch, hắn một mình dấn thân vào hiểm địa tìm thuốc, nào ngờ lại ngã xuống vực sâu Tiên Ma Nhai, tình cờ cứu được hai nữ tử thần bí là Thần nữ Bạch U U và Ma nữ Tô Mị Dao. Hai nàng lập khế ước máu cùng Thẩm Tường, giúp hắn thức tỉnh thần mạch nghịch thiên, đồng thời truyền thụ thần công vô thượng và tuyệt kỹ luyện đan siêu phàm. Nhờ đó, Thẩm Tường nhanh chóng quật khởi trên con đường võ đạo.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 13, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yang Tianxiang","avatar":""},{"name":"Shuang Zhao","avatar":""},{"name":"Nie Xiying","avatar":""},{"name":"沈依杭","avatar":""},{"name":"Haiting Cai","avatar":""},{"name":"Shuai Guan","avatar":""},{"name":"Hu Yajie","avatar":""},{"name":"李逸","avatar":""},{"name":"张雪敏","avatar":""},{"name":"Xing Chao","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ao Shi Dan Shen","Aoshi Dan Shen","Aoshi DanShen","Àoshì Dān Shén","Ào Shì Dān Shén","The Alchemis''t Rise","Transcending Alchemy God","World Defying Dan God","The Alchemist''s Rise","The Proud God of Alchemy","傲世丹神"]', 1784690324136);
