INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngao-the-dan-than', 'Ngạo Thế Đan Thần', 'World Defying Dan God (The Alchemist''s Rise)', 'ngạo thế đan thần world defying dan god (the alchemist''s rise) yang tianxiang shuang zhao nie xiying 沈依杭 haiting cai shuai guan hu yajie 李逸 张雪敏 xing chao ao shi dan shen aoshi dan shen aoshi danshen àoshì dān shén ào shì dān shén the alchemis''t rise transcending alchemy god world defying dan god the alchemist''s rise the proud god of alchemy 傲世丹神', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-tro-lai-cua-nu-hoang', 'Sự Trở Lại Của Nữ Hoàng', 'Return Of The Queen', 'https://phimimg.com/upload/vod/20250917-1/5ad929d81def8af9e47f4944be6b3c6f.jpg', 'https://phimimg.com/upload/vod/20250917-1/0782552574f8c82440057bda92ce794f.jpg', '<p>Thừa kế của Tập đoàn Vân Hải, Từ Hải Mộng, kết hôn với trưởng tử của gia tộc Lộ. Sau khi cưới, hai vợ chồng lên đường đi hưởng tuần trăng mật ở nước ngoài, nhưng họ bất ngờ gặp phải tai nạn và chết đuối. Vào ngày tổ chức cuộc họp cổ đông của Tập đoàn Vân Hải, Từ Hải Mộng đột ngột quay trở lại, không chỉ phục sinh từ cõi chết mà còn mạnh mẽ xoay chuyển tình thế, chiếm lại quyền lực và giành lại Tập đoàn Vân Hải. Nhà họ Lộ vì sự kiện này mà trở mặt với Từ Hải Mộng, và cậu hai nhà họ Lộ Tư Vũ đối đầu từng bước một với cô, từ việc tìm hiểu thân phận thật sự đến nguyên nhân cái chết của anh trai. Sau nhiều lần đối đầu, dưới sự đan xen nguy hiểm của sự thật và kẻ sát nhân, Lộ Tư Du cuối cùng cũng khám phá ra sự thật về “tuần trăng mật chết chóc” — Từ Hải Mộng chính là người bị anh trai đẩy xuống vách núi, sống sót qua bao lần hiểm nguy, chỉ để đấu tranh giành lấy sự sống.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Nghệ Thượng","avatar":""},{"name":"Ngô Tuấn Trinh","avatar":""},{"name":"Lương Kính Hiền","avatar":""},{"name":"Khúc Dật Thành","avatar":""},{"name":"Trương Diêu","avatar":""},{"name":"Tào Ân Tề","avatar":""},{"name":"Trương Sở Hàn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yi Ta Zhi Ming","以她之名"]', 1784690324136);
