INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-trai-say-xe', 'Anh Trai Say Xe', 'The First Ride', 'https://phimimg.com/upload/vod/20251208-1/4d466b18eaaac0bf28cac405ba22b4e7.jpg', 'https://phimimg.com/upload/vod/20251208-1/84eb1a74d6a6eabbb83e99d93b3edc47.jpg', '<p>Sau 24 năm “nói miệng” mà chưa bao giờ làm được, bốn người bạn chí cốt Tae Jung, Do Jin, Yeon Min và Geum Bok cuối cùng cũng thực hiện ước mơ lớn nhất đời mình: một chuyến du lịch nước ngoài đầu tiên cùng nhau. Nhưng đời không như mơ, ngay ngày khởi hành, một “vị khách bí ẩn” tên Ok Shim bất ngờ nhập hội, kéo cả nhóm vào chuỗi tình huống dở khóc dở cười khiến chuyến đi trở thành… ký ức có 1-0-2.</p>', 'Full', 1, 'single', 'completed', 17, 2025, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Hàn Quốc', 1, '[{"name":"Kang Ha-neul","avatar":""},{"name":"Kim Young-kwang","avatar":""},{"name":"Cha Eun-woo","avatar":""},{"name":"Kang Young-suk","avatar":""},{"name":"Han Seon-hwa","avatar":""},{"name":"Kim Kang-hyun","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["ทริปแรก ทริปรั่ว ทัวร์ไทยแลนด์","The First Ride","El primer viaje","퍼스트 라이드"]', 1784690324136);
