INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-tai-quynh-do', 'Thần Tại Quýnh Đồ', 'Oh My God!', 'https://phimimg.com/upload/vod/20250930-1/bbd2b56539b5b4a1370489d83fe47f57.jpg', 'https://phimimg.com/upload/vod/20250930-1/a89221b116e957e2c7b13bd7cdb0ee7d.jpg', '<p>Thần Tôn bất ngờ rơi xuống phàm giới, mất hết pháp lực. Chỉ vì ngài đã phá giải được bí mật phi thăng suốt ngàn năm, không ngờ bước đầu tiên lại là hoá tiên thành phàm, bắt đầu lại từ đầu! Thần Tôn vốn định học theo những tu sĩ khác, từ đó khổ cực tu luyện, nào ngờ một nữ đầu bếp từ trên trời rơi xuống, vô tình mở ra cho ngài một con đường mới – “ăn cũng có thể thăng cấp”. Vị Thần Tôn cao quý của Cửu Trùng Thiên từ nhỏ đã ăn linh lực thay cơm, uống sương sớm thay nước, đã bao giờ được thưởng thức hương vị nhân gian bình dị này đâu! Ngài thích ăn, ăn nhiều, còn phải giành lấy mà ăn! Cho đến khi ăn hết mỹ vị nhân gian, tiện thể thu phục được vô số kẻ quỳ dưới chân, Thần Tôn mới bừng tỉnh nhận ra rằng mình ăn thôi mà cũng thành người vô địch thiên hạ.</p>', 'Tập 40', 60, 'hoathinh', 'ongoing', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324136);
