INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oan-gia-duyen-troi', 'Oan Gia Duyên Trời', 'Shuffle Of Hearts', 'https://phimimg.com/upload/vod/20251220-1/df09c10a631b73196e80e9829c6c2fcf.jpg', 'https://phimimg.com/upload/vod/20251220-1/34cad75f967ae96e0c72ff7d9cfa1d41.jpg', '<p>Từ ngày anh vươn tay ra để kéo cô lên khỏi mặt nước và thoát khỏi tử thần, cô biết rằng cuộc đời mình, trái tim mình đã thuộc về anh kể từ đó. Nhưng trong mắt anh, cô chỉ là cô em gái nhỏ trong gia đình. Là một cô bé tinh nghịch và non nớt. Ánh mắt anh, trái tim anh chỉ để ý tới người chị gái xinh đẹp của cô. Còn cô, với tấm lòng yêu thương chân thành, một lòng dốc sức giúp anh và chị gái thành đôi. Nhưng duyên trời ngang ngược, luôn kéo cô và anh về bên nhau.</p>', 'Tập 18', 24, 'series', 'ongoing', 16, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Mik Thongraya","avatar":""},{"name":"Chayissara Wattananawin","avatar":""},{"name":"Chakrit Boonsing","avatar":""},{"name":"Sipatrada Phiuthong","avatar":""},{"name":"Chanoknun Seanpin","avatar":""},{"name":"Pheerawas Khunlanunthwatn","avatar":""},{"name":"Gatesara Watthanasang","avatar":""},{"name":"Nasamon Niyomdecha","avatar":""},{"name":"Ponpaj Phunnin","avatar":""},{"name":"Natthapat Jiraphawasut","avatar":""},{"name":"Wasu Saengsingkaeo","avatar":""},{"name":"Namthip Siamthong","avatar":""},{"name":"Surasak","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Phrom Phayot","พรหมพยศ"]', 1784690324136);
