INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-vu-will-trent-phan-3', 'Đặc Vụ Will Trent (Phần 3)', 'Will Trent (Season 3)', 'https://phimimg.com/upload/vod/20260201-1/9b9569b3f6a99b1ad5c694bb42d05bfe.jpg', 'https://phimimg.com/upload/vod/20260201-1/5ff574acad1d6f436e818ba2bc707f4d.jpg', '<p>Đặc vụ Will Trent bị bỏ rơi khi mới ra đời và phải trải qua tuổi thơ khắc nghiệt trong hệ thống chăm sóc nuôi dưỡng quá tải của Atlanta. Quyết tâm đảm bảo rằng không ai phải trải qua quảng thời gian kinh khủng đó, anh đã lên làm người có quyền hành cao nhất trong Cục điều tra.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ramón Rodríguez","avatar":""},{"name":"Erika Christensen","avatar":""},{"name":"Iantha Richardson","avatar":""},{"name":"Jake McLaughlin","avatar":""},{"name":"Sonja Sohn","avatar":""},{"name":"Kevin Daniels","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Уил Трент","Will Trent"]', 1784690324136);
