INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-dam-boc', 'Tay Đấm Bốc', 'I Am Boxer', 'https://phimimg.com/upload/vod/20251203-1/d591505d2fe31b0a18d7a2ba5b42c2ac.jpg', 'https://phimimg.com/upload/vod/20251203-1/441bde7c196896e19d4072b87917ef56.jpg', '<p>Chương trình truyền hình thực tế sinh tồn về đấm bốc cực kỳ đặc biệt của Don Lee. Ai sẽ chiến đấu và trở thành Tay Đấm Vô Địch cuối cùng còn đứng trên sàn đấu?</p>', 'Hoàn Tất (10/10)', 10, 'tvshows', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Don Lee","avatar":""},{"name":"Dex","avatar":""},{"name":"Kim Jong-kook","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["I Am Boxer","아이 엠 복서"]', 1784690324136);
