INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tay-dam-boc', 'Tay Đấm Bốc', 'I Am Boxer', 'tay đấm bốc i am boxer don lee dex kim jong-kook i am boxer 아이 엠 복서', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-vang-son', 'Thời Vàng Son', 'Our Golden Days', 'https://phimimg.com/upload/vod/20250811-1/e5abdfeeeeb9de6dc66f65a0cf8eb92b.jpg', 'https://phimimg.com/upload/vod/20250811-1/cf8aded73a79cd81817fd43f0b71cc2b.jpg', '<p>Ai cũng có những tháng ngày huy hoàng của riêng mình. Dù là hiện tại, quá khứ hay tương lai.&quot; Một bộ phim tâm lý gia đình chạm đến nhiều thế hệ, kể về những tháng ngày vàng son mang ý nghĩa khác nhau với mỗi người. Ji Hyuk có tất cả phẩm chất của “người chồng trong mơ”: thông minh, thành đạt và điển trai. Nhưng anh tin rằng độc thân mới là cuộc sống lý tưởng. Ngày thường, anh cống hiến trọn vẹn cho công việc; cuối tuần, anh tự thưởng cho mình những thú vui bằng chính đồng lương kiếm được. Mọi thứ đảo lộn khi Eun Oh - cô đàn em rạng rỡ và kiên cường thời đại học, từng một lần tỏ tình nhưng bị anh từ chối - bất ngờ quay lại. Sự xuất hiện của cô không chỉ khiến trái tim Ji Hyuk rung động trở lại, mà còn buộc anh đối diện với mối quan hệ gia đình mà anh đã cố quên. Trong khi đó, người bạn thân Seong Jae - sinh ra đã ngậm thìa vàng và tưởng chừng nắm trong tay tất cả - lại đang âm thầm chiến đấu với những nỗi niềm riêng. Cả ba, mỗi người mang một vết thương, cùng bước vào hành trình đối diện với tình thân, cuộc sống và tình yêu theo cách của riêng mình.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 12, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jung In-sun","avatar":""},{"name":"Jung Il-woo","avatar":""},{"name":"Lee Tae-ran","avatar":""},{"name":"Yoon Hyun-min","avatar":""},{"name":"Cheon Ho-jin","avatar":""},{"name":"Kim Hee-jung","avatar":""},{"name":"Park Seong-geun","avatar":""},{"name":"Ban Hyo-jung","avatar":""},{"name":"Kim Jung-young","avatar":""},{"name":"Yang Hyuk","avatar":""},{"name":"Yoon Joo-Sang","avatar":""},{"name":"Son Sang-yeon","avatar":""},{"name":"Shin Su-hyun","avatar":""},{"name":"Park Jung-yeon","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["화려한 날들"]', 1784690324136);
