INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('96-phut-sinh-tu', '96 Phút Sinh Tử', '96 Minutes', 'https://phimimg.com/upload/vod/20260130-1/151e055fd6bbd13a479c1a285449de1f.jpg', 'https://phimimg.com/upload/vod/20260130-1/ef0fab3fb8aa7df67b329386747c4f28.jpg', '<p>Ba năm sau thảm kịch tại trung tâm mua sắm, trên chuyến tàu cao tốc định mệnh, nữ cảnh sát Huỳnh Hân (Tống Vân Hoa) và chồng cô là cựu chuyên gia gỡ bom - Tống Khang Nhân (Lâm Bách Hoành), cùng đội trưởng Lý Kiệt (Lý Lý Nhân) bất ngờ nhận được tin nhắn thông báo một quả bom đã được cài sẵn trên tàu. Vụ việc lần này còn phức tạp hơn khi kẻ khủng bố dường tính toán vô cùng tinh vi. Khi thời gian cạn dần, Tống Khang Nhân buộc phải ngăn thảm kịch xảy ra bằng mọi giá, đồng thời đối mặt với những ám ảnh kinh hoàng từ vụ nổ năm xưa.</p>', 'Full', 1, 'single', 'completed', 18, 2025, 'Vietsub', 'FHD', 'Đài Loan', 1, '[{"name":"Austin Lin","avatar":""},{"name":"Vivian Sung","avatar":""},{"name":"Edison Wang","avatar":""},{"name":"Lee Lee-Zen","avatar":""},{"name":"Eleven Yao","avatar":""},{"name":"Kent Tsai Fan-Hsi","avatar":""},{"name":"Frederick Lee","avatar":""},{"name":"Lu Hsueh-Feng","avatar":""},{"name":"Ki-pin Ng","avatar":""},{"name":"Cheng Chih-wei","avatar":""},{"name":"Vera Chen","avatar":""},{"name":"Wu Chien-Ho","avatar":""},{"name":"Ling Yuan Kung","avatar":""},{"name":"Flora Gu","avatar":""},{"name":"Yeh Ching Han","avatar":""},{"name":"Linda Lin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["96分鐘"]', 1784690324136);
