INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trong-cai-rui-co-cai-xui', 'Trong Cái Rủi có Cái Xui', 'Untitled Home Invasion Romance', 'https://phimimg.com/upload/vod/20260130-1/91f52ad4b2d9cf849829903a2ef5d472.jpg', 'https://phimimg.com/upload/vod/20260130-1/9dac38cff74e5eccb354873e6917c6df.jpg', '<p>Một diễn viên hết thời, nổi tiếng vì vai diễn lố bịch, tìm cách cứu vãn hôn nhân bằng một màn dàn dựng anh hùng giả. Nhưng trò lừa tình cảm nhanh chóng vượt tầm kiểm soát, đẩy anh và vợ vào tình huống một vụ án mạng thật sự.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jason Biggs","avatar":""},{"name":"Meaghan Rath","avatar":""},{"name":"Anna Konkle","avatar":""},{"name":"Justin H. Min","avatar":""},{"name":"Arturo Castro","avatar":""},{"name":"Chris Young","avatar":""},{"name":"René Escobar Jr.","avatar":""},{"name":"Steven Vlahos","avatar":""},{"name":"Tianna SwamiNathan","avatar":""},{"name":"Neil Crone","avatar":""},{"name":"Kevin Hoffman","avatar":""},{"name":"Austen Alexander","avatar":""},{"name":"Tony Nappo","avatar":""},{"name":"Carrie Schiffler","avatar":""},{"name":"Nicky Guadagni","avatar":""},{"name":"Peter Millard","avatar":""},{"name":"Emily Strange","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Getaway","Plan cambriolage romantique","Untitled Home Invasion Romance"]', 1784690324136);
