INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-nhap-trang', 'Quỷ Nhập Tràng', 'The Corpse', 'https://phimimg.com/upload/vod/20260129-1/3558b82723d946ca1a0fa9e36197ec70.jpg', 'https://phimimg.com/upload/vod/20260129-1/4d420dcef0d8f183b115788140d02614.jpg', '<p>Phim lấy cảm hứng từ &quot;truyền thuyết kinh dị nhất về người chết sống lại&quot;, kể về vợ chồng Quang và Như sống bằng nghề mai táng ở một ngôi làng vùng cao. Cuộc sống yên bình của họ bị xáo trộn khi phát hiện một cỗ quan tài vô chủ trên mảnh đất nhà mình. Từ đây, những hiện tượng kỳ lạ bắt đầu xảy ra và ám ảnh cả ngôi làng.</p>', 'Full', 1, 'single', 'completed', 20, 2025, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Quang Tuấn","avatar":""},{"name":"Khả Như","avatar":""},{"name":"Thanh Nam","avatar":""},{"name":"Tân Chề","avatar":""},{"name":"Vân Dung","avatar":""},{"name":"Phú Đôn","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Quỷ Nhập Tràng"]', 1784690324136);
