INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-nho-nui-lang-lang-tieu-yeu-quai-nui-lang-lang', 'Quái Vật Nhỏ Núi Lãng Lãng (Tiểu Yêu Quái Núi Lãng Lãng)', 'Nobody', 'https://phimimg.com/upload/vod/20250907-1/2276a43ce7ac15b0954d772aac7d9e8f.jpg', 'https://phimimg.com/upload/vod/20250907-1/4074dc1b02219548fd890c1a948dac70.jpg', '<p>Tiểu Yêu Heo quyết định rời núi Lãng Lãng để tham gia cuộc hành hương. Trên hành trình về phương Tây, những chú tiểu quái vật sẽ phải đối mặt với những thử thách nào? Cuối cùng, liệu chúng có đạt được ước mơ và sống như mong muốn?</p>', 'Full', 1, 'hoathinh', 'completed', 15, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 1, '[{"name":"Meng Li","avatar":""},{"name":"劉琮","avatar":""},{"name":"Tom Fu","avatar":""},{"name":"陈子平","avatar":""},{"name":"路扬","avatar":""},{"name":"董汶亮","avatar":""},{"name":"Lin Qiang","avatar":""},{"name":"张闻天","avatar":""},{"name":"陳喆","avatar":""},{"name":"王上斌","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["小妖怪的夏天：从前有座浪浪山","랑랑산꼬마요괴","小妖怪的夏天","랑랑산 작은 요괴","Lang Lang Shan Xiao Yao Guai","สัตว์ประหลาดตัวน้อยแห่งภูเขาหลางหลาง","Маленькие монстры с горы Ланлан","Nobody","Langlang shan xiao yao guai","Lang, o Pequeno Monstro da Montanha do Lobo","O Verão do Pequeno Monstro: Era uma vez uma montanha chamada Montanha Langlang.","Маленькие демоны путешествуют на Запад","Langlang Shan Xiao Yaoguai","Lang Lang Shan Xiao Yaoguai","浪浪山小