INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('quai-vat-nho-nui-lang-lang-tieu-yeu-quai-nui-lang-lang', 'Quái Vật Nhỏ Núi Lãng Lãng (Tiểu Yêu Quái Núi Lãng Lãng)', 'Nobody', 'quái vật nhỏ núi lãng lãng (tiểu yêu quái núi lãng lãng) nobody meng li 劉琮 tom fu 陈子平 路扬 董汶亮 lin qiang 张闻天 陳喆 王上斌 小妖怪的夏天：从前有座浪浪山 랑랑산꼬마요괴 小妖怪的夏天 랑랑산 작은 요괴 lang lang shan xiao yao guai สัตว์ประหลาดตัวน้อยแห่งภูเขาหลางหลาง маленькие монстры с горы ланлан nobody langlang shan xiao yao guai lang, o pequeno monstro da montanha do lobo o verão do pequeno monstro: era uma vez uma montanha chamada montanha langlang. маленькие демоны путешествуют на запад langlang shan xiao yaoguai lang lang shan xiao yaoguai 浪浪山小妖怪', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('de-che-dai-han', 'Đế Chế Đại Hàn', 'Made In Korea', 'https://phimimg.com/upload/vod/20251225-1/5324797b5d87f7ef15f13ccdd0a17366.jpg', 'https://phimimg.com/upload/vod/20251225-1/5108a3b34f49f98a21c7bd49f4437232.jpg', '<p>Lấy bối cảnh những năm 1970, Baek Gi Tae là một người đàn ông đầy tham vọng, khao khát giàu sang và quyền lực. Jang Gun Yeong là một công tố viên với bản năng hoang dã và sự ngoan cường đáng sợ. Đối mặt với một vụ án lớn, Jang Gun Yeong dốc toàn lực để ngăn chặn Baek Gi Tae. Những người xung quanh họ bao gồm nhà vận động hành lang Choi Yu Ji, điều tra viên O Ye Jin, Bae Geum Ji và Chánh văn phòng Cheon Seok Jeong.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 12, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Hyun Bin","avatar":""},{"name":"Jung Woo-sung","avatar":""},{"name":"Woo Do-hwan","avatar":""},{"name":"Cho Yeo-jeong","avatar":""},{"name":"Seo Eun-soo","avatar":""},{"name":"Won Ji-an","avatar":""},{"name":"Jung Sung-il","avatar":""},{"name":"Kang Gil-woo","avatar":""},{"name":"Roh Jae-won","avatar":""},{"name":"Park Yong-woo","avatar":""},{"name":"Lily Franky","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Made in Korea","Me-i-deu.in.Ko-ri-a","صنع في كوريا","메이드 인 코리아"]', 1784690324136);
