INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-vu-dong-troi-2', 'Phi Vụ Động Trời 2', 'Zootopia 2', 'https://phimimg.com/upload/vod/20251223-1/7154384c306c73664e46942f2477e574.jpg', 'https://phimimg.com/upload/vod/20251223-1/6bc1d549b86e490274d93bab66a3654d.jpg', '<p>Trong bộ phim &quot;Zootopia 2 - Phi Vụ Động Trời 2&quot; từ Walt Disney Animation Studios, hai thám tử Judy Hopps (lồng tiếng bởi Ginnifer Goodwin) và Nick Wilde (lồng tiếng bởi Jason Bateman) bước vào hành trình truy tìm một sinh vật bò sát bí ẩn vừa xuất hiện tại Zootopia và khiến cả vương quốc động vật bị đảo lộn. Để phá được vụ án, Judy và Nick buộc phải hoạt động bí mật tại những khu vực mới lạ của thành phố – nơi mối quan hệ đồng nghiệp của họ bị thử thách hơn bao giờ hết.</p>', 'Full', 1, 'hoathinh', 'completed', 20, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Ginnifer Goodwin","avatar":""},{"name":"Jason Bateman","avatar":""},{"name":"Ke Huy Quan","avatar":""},{"name":"Fortune Feimster","avatar":""},{"name":"Andy Samberg","avatar":""},{"name":"David Strathairn","avatar":""},{"name":"Idris Elba","avatar":""},{"name":"Shakira","avatar":""},{"name":"Patrick Warburton","avatar":""},{"name":"Quinta Brunson","avatar":""},{"name":"Danny Trejo","avatar":""},{"name":"Nate Torrence","avatar":""},{"name":"Bonnie Hunt","avatar":""},{"name":"Don Lake","avatar":""},{"name":"Michelle Gomez","avatar":""},{"name":"David Fane","avatar":""},{"name":"Joe Anoa''i","avatar":""},{"name":"Phil Br","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Bí Ẩn","slug":"bi-an","id":"2f