INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doc-nhat-vo-nhi', 'Độc Nhất Vô Nhị', 'The One', 'https://phimimg.com/upload/vod/20260128-1/abaeb762cb0518e0ae4e1b73526b636f.jpg', 'https://phimimg.com/upload/vod/20260128-1/33b7b970cea206b525a3892e49962bd4.jpg', '<p>Cô gái 17 tuổi Dụ Duyên sống với cha, mẹ và anh trai tại một quán ăn do tổ tiên họ gây dựng. Là người duy nhất có thể nghe được trong một gia đình khiếm thính, cô đã lang thang giữa thế giới im lặng của gia đình và thế giới âm thanh bên ngoài kể từ khi còn nhỏ, và đã quen với vai trò là cầu nối và phiên dịch. Tình yêu thương và sự phụ thuộc của gia đình quấn chặt lấy cô như dây leo, nhưng ngọn lửa khao khát được nhìn thấy thế giới rộng lớn hơn cũng đang bùng cháy trong tim cô. Sự thay đổi đột ngột buộc Dụ Duyên phải đối mặt với tình thế tiến thoái lưỡng nan giữa việc theo đuổi ước mơ và bảo vệ gia đình. Trong những lựa chọn khi lớn lên, cô bé cố gắng tìm kiếm chính mình và những bài hát mà cô có thể chia sẻ với gia đình.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Jingyi","avatar":""},{"name":"Chen Minghao","avatar":""},{"name":"Jiang Qinqin","avatar":""},{"name":"Xin Yunlai","avatar":""},{"name":"Zhang Yu","avatar":""},{"name":"White-K","avatar":""},{"name":"Edward Chen","avatar":""},{"name":"Ouyang Nana","avatar":""},{"name":"Zhang Baiqiao","avatar":""},{"name":"Dong Hao","avatar":""},{"name":"Yi Lijing","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["健听女孩