INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-troi-chieu-roi-thanh-xuan', 'Mặt Trời Chiếu Rọi Thanh Xuân', 'The Way Out', 'https://phimimg.com/upload/vod/20260128-1/592d923e2b56f2b391caf8cc37b8ed0c.jpg', 'https://phimimg.com/upload/vod/20260128-1/44d948ec5a636ebbe286fedd00affb26.jpg', '<p>Hà Lập Vy, một lập trình viên trẻ tài năng, làm việc cho Công ty phần mềm Homeland và tự mình phát triển một trò chơi. Chứng hoang tưởng và hành động của anh đã phá vỡ kế hoạch tài chính của công ty và sau đó đã bị đưa đến bệnh viện phục hồi chức năng tâm thần &quot;Thanh Xuân Lý&quot;. Tại trung tâm phục hồi chức năng, Hà Lập Vy đã gặp nhiều bệnh nhân và trải qua nhiều câu chuyện buồn cười. Trong số đó, bệnh nhân nữ Lâm Xuân Xuân.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xiao Yang","avatar":""},{"name":"Jessie Li","avatar":""},{"name":"Chen Minghao","avatar":""},{"name":"Jiang Qiming","avatar":""},{"name":"Wang Xun","avatar":""},{"name":"Wang Zichuan","avatar":""},{"name":"Zhao Zichong","avatar":""},{"name":"Yang Yi","avatar":""},{"name":"Li Luqi","avatar":""},{"name":"Guo Yiqian","avatar":""},{"name":"郑磊","avatar":""},{"name":"赵成哲","avatar":""},{"name":"Zhao Ziqi","avatar":""},{"name":"Shi Liang","avatar":""},{"name":"Yu Mingjia","avatar":""},{"name":"Huang Yao","avatar":""},{"name":"Ren Luomin","avatar":""},{"name":"Chen Xixu","avatar":""},{"name":"Wang Shengdi","avatar":""},{"name":"Huang Xiaoming","avatar":""},{"name":"Chunyu Shanshan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["逃出青春里","以梦为马","The