INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buoc-vao-tim-em', 'Bước Vào Tim Em', 'Love Me', 'https://phimimg.com/upload/vod/20251221-1/d0773e4142c7f245cdc32ce80fd7bc9c.jpg', 'https://phimimg.com/upload/vod/20251221-1/11352defef012cabcfc2a7e6161f7348.jpg', '<p>Bộ phim&nbsp;xoay quanh Seo Jun Gyeong, một nữ bác sĩ phụ khoa xinh đẹp và thành công, nhưng không ai biết phía sau bề ngoài tưởng chừng như hoàn hảo đó lại ẩn chứa một tâm hồn vô cùng cô đơn. Sau khi bỏ trốn khỏi gia đình đã tan vỡ sau một tai nạn bất ngờ cách đây bảy năm, cô ôm trong mình một bí mật không dám thổ lộ cùng ai. Để bảo vệ bí mật đó, Jun Gyeong luôn phải cố gắng tỏ ra mạnh mẽ, cho đến khi một người đàn ông bước vào đời cô và nhìn thấu nỗi cô đơn mà cô giấu kín suốt bấy lâu nay.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 11, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Seo Hyun-jin","avatar":""},{"name":"You Chea-myung","avatar":""},{"name":"Lee Si-woo","avatar":""},{"name":"Yoon Se-a","avatar":""},{"name":"Chang Ryul","avatar":""},{"name":"DAHYUN","avatar":""},{"name":"Chang Hyae-jin","avatar":""},{"name":"Oh Dong-min","avatar":""},{"name":"Kong Seong-ha","avatar":""},{"name":"Kim Shana","avatar":""},{"name":"Park Seong-yeon","avatar":""},{"name":"Jung Seung-kil","avatar":""},{"name":"Kim Ki-doo","avatar":""},{"name":"Kang Chae-young","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["爱我","أحبني","러브 미"]', 1784690324136);
