INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ong-bo-cua-marrie', 'Những Ông Bố Của Marrie', 'Marie And Her Three Daddies', 'https://phimimg.com/upload/vod/20251027-1/24dab0fe584f5ecd5640f5b5e677f54a.jpg', 'https://phimimg.com/upload/vod/20251027-1/99664ba2ff38b218f9568d2d439188af.jpg', '<p>Phim xoay quanh hành trình của Kang Ma Ri trong cuộc kiếm tìm người cha ruột và khát vọng tìm lại một gia đình thực sự. Thế nhưng, càng đi sâu vào quá khứ, cô càng nhận ra rằng gia đình không chỉ là sự kết nối về huyết thống, mà còn là tình yêu, sự chấp nhận và những vòng tay luôn dang rộng chờ đón mình. Từ đó, Kang Ma-ri học cách trân trọng những người đã âm thầm đồng hành và yêu thương cô vô điều kiện suốt bao năm qua.</p>', 'Tập 70', 100, 'series', 'ongoing', 10, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ha Seung-lee","avatar":""},{"name":"Ryu Jin","avatar":""},{"name":"Hyun Woo","avatar":""},{"name":"Park Eun-hye","avatar":""},{"name":"Kong Jeong-hwan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["마리와 별난 아빠들"]', 1784690324136);
