INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-ngot-chet-ruoi', 'Mật Ngọt Chết Ruồi', 'A Graceful Liar', 'https://phimimg.com/upload/vod/20251002-1/3a4bd37f9a52221e5573a52eacaaae56.jpg', 'https://phimimg.com/upload/vod/20251002-1/7a26d994bb2583fb46a085d6bcca9292.jpg', '<p>Câu chuyện xoay quanh hai người phụ nữ đầy tham vọng, vốn gắn kết bằng huyết thống, nay lại đối đầu trong vai mẹ chồng – nàng dâu. Giữa cuộc chiến dối trá và toan tính, họ lao vào trận chiến khốc liệt để giành lấy &#39;hoàng cung vàng&#39; quyền lực.</p>', 'Tập 80', 100, 'series', 'ongoing', 15, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Shi-a","avatar":""},{"name":"Lee Il-hwa","avatar":""},{"name":"Seol Jung-hwan","avatar":""},{"name":"Han Ki-woong","avatar":""},{"name":"Lee Hyo-na","avatar":""},{"name":"Lee Seung-yun","avatar":""},{"name":"Choi Jong-hwan","avatar":""},{"name":"Choi Da-eum","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Intimate Ripley","A Graceful Liar","Kẻ Nói Dối Duyên Dáng","친밀한 리플리"]', 1784690324136);
