INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('medalist-phan-1', 'Medalist (Phần 1)', 'Medalist (Season 1)', 'https://phimimg.com/upload/vod/20260126-1/47e072d1ee206fb77aaf4e261b33d72d.jpg', 'https://phimimg.com/upload/vod/20260126-1/5c5127d41caf3e25e6fa1a3dc5c1c3eb.jpg', '<p>Tsukasa Akeuraji, một vận động viên trượt băng luôn mang trong mình nỗi thất vọng vì sự nghiệp dang dở, đã gặp gỡ Inori Yuitsuka — một cô bé khao khát cháy bỏng được trở thành vận động viên trượt băng nghệ thuật. Bị lay động bởi sự ám ảnh và quyết tâm của Inori trên sân băng, Tsukasa bắt đầu dẫn dắt và huấn luyện cô bé. Tài năng của Inori dần nở rộ, còn Tsukasa cũng trở thành một người thầy xuất sắc. Cùng nhau, họ hướng tới mục tiêu biến cô bé trở thành một chủ nhân lộng lẫy của tấm huy chương vàng!</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Natsumi Haruse","avatar":""},{"name":"Takeo Otsuka","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["舞冰的祈愿","金牌得主","Medarisuto","メダリスト"]', 1784690324136);
