INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-la-mu-quang-duc-phan-1', 'Yêu Là Mù Quáng: Đức (Phần 1)', 'Love Is Blind: Germany (Season 1)', 'https://phimimg.com/upload/vod/20260125-1/7efd8a3c98c8c5f6973fc0a380910a36.jpg', 'https://phimimg.com/upload/vod/20260125-1/99475bbfa54cc723f7918a633bfaee8d.jpg', '<p>Chương trình thử nghiệm này đã đến Đức, mang đến cơ hội cho những người độc thân nơi đây tìm kiếm tình yêu đích thực và cam kết gắn bó trọn đời, trước cả khi họ gặp mặt trực tiếp.</p>', 'Hoàn Tất (10/10)', 10, 'tvshows', 'completed', 19, 2025, 'Vietsub', 'FHD', 'Đức', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Love Is Blind: Germany"]', 1784690324136);
