INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cach-em-1-milimet', 'Cách Em 1 Milimet', '1 Millimeter From You', 'https://phimimg.com/upload/vod/20250914-1/ba8562f85b79c72cfa88a0b99f94d004.jpg', 'https://phimimg.com/upload/vod/20250914-1/7967bc86331fbdd3b6efbb1af802c908.jpg', '<p>Bộ phim kể về câu chuyện của một nhóm bạn thân lớn lên ở Làng Mây. Phim khắc họa những kỷ niệm tuổi thơ hồn nhiên, những rung động đầu đời và những biến cố khiến họ rời xa nhau. Khi trưởng thành, họ quay trở lại quê hương để tìm lại tình bạn và chữa lành những tổn thương trong quá khứ.</p>', 'Tập 42', 50, 'series', 'ongoing', 29, 2025, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Minh Huyền","avatar":""},{"name":"Hà Việt Dũng","avatar":""},{"name":"Huỳnh Anh","avatar":""},{"name":"Trọng Lân","avatar":""},{"name":"Quỳnh Châu","avatar":""},{"name":"Thục Phương","avatar":""},{"name":"Gia Long","avatar":""},{"name":"Minh Xíu","avatar":""},{"name":"Đức Phong","avatar":""},{"name":"Quỳnh Trang","avatar":""},{"name":"Sơn Tùng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324136);
