INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cach-em-1-milimet', 'Cách Em 1 Milimet', '1 Millimeter From You', 'cách em 1 milimet 1 millimeter from you minh huyền hà việt dũng huỳnh anh trọng lân quỳnh châu thục phương gia long minh xíu đức phong quỳnh trang sơn tùng ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-dao-2025', 'Tiêu Dao', 'The Unclouded Soul', 'https://phimimg.com/upload/vod/20251227-1/42f341936e497453584e12fbbdf02e0f.jpg', 'https://phimimg.com/upload/vod/20251227-1/fc90138c15a005826ad7b14d8a0075f1.jpg', '<p>Nhân tộc và yêu tộc đều vì tham vọng cá nhân mà săn lùng Thần Tuyền Ngọc Lễ, suốt hàng trăm năm gây ra vô số tranh chấp. Tiêu Dao - cô gái phóng khoáng với khả năng ứng biến thiên phú, vô tình mở ra hành trình kỳ ảo xuyên Vạn Yêu Cốc, làm đảo điên cả giới yêu ma. Hồng Diệp - vua vạn yêu được yêu tộc tôn sùng một lần nữa xuất hiện để bảo vệ Vạn Yêu Cốc. Trải qua bao thăng trầm, chàng đã thấu hiểu bản chất tham lam của vạn vật, nhận ra Ngọc Lễ Tuyền chính là hiện thân của vô số dục vọng. Qua những lần tiếp xúc, Hồng Diệp cũng phát hiện ra bản thân đã nảy sinh tình cảm với cô gái nhỏ Tiêu Dao, người có linh hồn thuần tuý đáng quý, không bị ảnh hưởng bởi dục niệm. Cả hai cùng nhau dấn bước, liên tiếp vướng vào những vụ án kỳ lạ và đối đầu với những đối thủ bí ẩn đầy thách thức...</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 16, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Đàm Tùng Vận","avatar":""},{"name":"Hầu Minh Hạo","avatar":""},{"name":"Uông Đạc","avatar":""},{"name":"Huang Jiajing","avatar":""},{"name":"Trương Tiểu Uyển","avatar":""},{"name":"Quách Vân Kỳ","avatar":""},{"name":"Triệu Lệ Dĩnh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Xiao Yao","逍遙","소요: 억겁의 시간을 건너 너에게","Unfettered","The Unclouded Soul","逍遥"]', 1784690324136);
