INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-ga-nuot-nguoi-dang-xuat', 'Nhà Ga Nuốt Người: Đăng Xuất', 'Kisaragi Station Re:', 'https://phimimg.com/upload/vod/20260123-1/b64765063802fb72c1c054993dd6d6d0.jpg', 'https://phimimg.com/upload/vod/20260123-1/720bb3a25dcfd2b7fd499db362c89f2c.jpg', '<p>Ba năm trước, Asuka Miyazaki đã trở về một cách kỳ diệu từ nhà ga bí ẩn, kỳ lạ &quot;Kisaragi&quot;. Tuy nhiên, dáng vẻ cô vẫn trông như khi vừ mới mất tích vào thờ điểm 20 năm trước, điều đó khiến người ta nghi ngờ và xa lánh cô. Khi gặp một đạo diễn phim tài liệu đầy nhiệt huyết, cô quyết tâm cứu Haruna Tsutsumi - người từng liều mạng vì cô - và những người khác vẫn còn mắc kẹt ở đó. Asuka lên tàu một lần nữa và đoàn tụ với Haruna, vẫn không thay đổi so với ba năm trước, và bước trở lại Ga Kisaragi.</p>', 'Full', 1, 'single', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 1, '[{"name":"Miyu Honda","avatar":""},{"name":"Yuri Tsunematsu","avatar":""},{"name":"Eriko Sato","avatar":""},{"name":"Megumi Okina","avatar":""},{"name":"Tateto Serizawa","avatar":""},{"name":"Taki Nanami","avatar":""},{"name":"Raiga Terasaka","avatar":""},{"name":"Okawa Taiga","avatar":""},{"name":"Akiyoshi Shibata","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["きさらぎ駅 Re:"]', 1784690324136);
