INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quet-trung-tu-than', 'Quẹt Trúng Tử Thần', 'Match', 'https://phimimg.com/upload/vod/20260123-1/a9acf803f90e6072d481b656dba3e066.jpg', 'https://phimimg.com/upload/vod/20260123-1/290ed3f9e37442f3c17f55ae8a7bd201.jpg', '<p>Một buổi hẹn đầu tiên tưởng như lãng mạn nhanh chóng biến thành cơn ác mộng khi Paola bước vào ngôi nhà của người đàn ông cô quen qua mạng, nơi những bí mật đáng sợ đang chờ được phơi bày.</p>', 'Full', 1, 'single', 'completed', 24, 2025, 'Vietsub', 'FHD', 'Nam Phi', 0, '[{"name":"Humberly González","avatar":""},{"name":"Shaeane Jimenez","avatar":""},{"name":"Dianne Simpson","avatar":""},{"name":"Jacques Adriaanse","avatar":""},{"name":"Luke Volker","avatar":""},{"name":"Nikita Faber","avatar":""},{"name":"Dean Goldblum","avatar":""},{"name":"Peter Butler","avatar":""},{"name":"Alex McGregor","avatar":""},{"name":"Cassiel Eatock-Winnik","avatar":""},{"name":"Brett Williams","avatar":""},{"name":"Michael Everson","avatar":""},{"name":"Troydan Berg","avatar":""},{"name":"Nicole Nel","avatar":""},{"name":"Katelyn Barnard","avatar":""},{"name":"Tayla Greef","avatar":""},{"name":"K","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["مسابقه","Match"]', 1784690324136);
