INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-thu-vo-hinh-vung-dat-chet-choc', 'Quái Thú Vô Hình: Vùng Đất Chết Chóc', 'Predator: Badlands', 'https://phimimg.com/upload/vod/20251120-1/94305c2dc18cfbce0567b2926dbff907.jpg', 'https://phimimg.com/upload/vod/20251120-1/2cddf29e6493b079efaa8d1f4094c1a6.jpg', '<p>Trong tương lai, tại một hành tinh hẻo lánh, một Predator non nớt - kẻ bị chính tộc của mình ruồng bỏ - tìm thấy một đồng minh không ngờ tới là Thia và bắt đầu hành trình sinh tử nhằm truy tìm kẻ thù tối thượng. Bộ phim do Dan Trachtenberg - đạo diễn của Prey chỉ đạo và nằm trong chuỗi thương hiệu Quái Thú Vô Hình Predator.</p>', 'Full', 1, 'single', 'completed', 19, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Elle Fanning","avatar":""},{"name":"Dimitrius Schuster-Koloamatangi","avatar":""},{"name":"Rohinal Nayaran","avatar":""},{"name":"Michael Homick","avatar":""},{"name":"Stefan Grube","avatar":""},{"name":"Reuben De Jong","avatar":""},{"name":"Cameron Brown","avatar":""},{"name":"Alison Wright","avatar":""},{"name":"Matt Duffer","avatar":""},{"name":"Ross Duffer","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["المفترس: الأراضي القاحلة","Predator: Strefa zagrożenia","Predador: Terras Selvagens","铁血战士：杀戮之地","Predator - Badlands","Predator Badlands","Predator, Badlands","Prédateur: Badlands","Predator: Vahşi Topraklar","Predator: Badlands"]', 1784690324136);
