INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('quai-thu-vo-hinh-vung-dat-chet-choc', 'Quái Thú Vô Hình: Vùng Đất Chết Chóc', 'Predator: Badlands', 'quái thú vô hình: vùng đất chết chóc predator: badlands elle fanning dimitrius schuster-koloamatangi rohinal nayaran michael homick stefan grube reuben de jong cameron brown alison wright matt duffer ross duffer المفترس: الأراضي القاحلة predator: strefa zagrożenia predador: terras selvagens 铁血战士：杀戮之地 predator - badlands predator badlands predator, badlands prédateur: badlands predator: vahşi topraklar predator: badlands', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rat-may-man-khi-gap-duoc-em', 'Rất May Mắn Khi Gặp Được Em', 'Love Island', 'https://phimimg.com/upload/vod/20260123-1/89155cfa0ee308eb2f8f5c938c8bc213.jpg', 'https://phimimg.com/upload/vod/20260123-1/f8e4cb9db78a9a6f0bed1a7ec1eae97e.jpg', '<p>Giáo viên âm nhạc An Nhiên và võ sĩ Song Ân chọn dạy tại cùng một trường học vào những thời điểm khác nhau. Trong ngôi trường giống như thiên đường trên mặt đất này, hai người trẻ tuổi bắt đầu giao tiếp xuyên thời gian và không gian thông qua một cuốn nhật ký ma thuật. Tuy nhiên, người ta nói rằng tình yêu không thể vượt qua mọi khó khăn chỉ khi hai người phù hợp với nhau. Cuộc gặp gỡ định mệnh của hai người sẽ dẫn đến một tương lai tươi sáng hay sự chia ly? Phim chuyển thể từ tác phẩm &#39;The Teacher’s Diary&#39; của Thái Lan</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lyric Lan","avatar":""},{"name":"Liu Yichang","avatar":""},{"name":"Peter Sheng","avatar":""},{"name":"Lexuan Lin","avatar":""},{"name":"Jia Bing","avatar":""},{"name":"Fan Tiantian","avatar":""},{"name":"Huang Xiaolei","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["吹过你吹过的风","教师日记 中国版","The Wind That You Blew","คิดถึงวิทยา","A Teacher''s Diary","多幸运遇见你"]', 1784690324136);
