INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-roi-se-den', 'Đi Rồi Sẽ Đến', 'Merrily We Roll Along', 'https://phimimg.com/upload/vod/20260122-1/0d6fef8967ba39e510b041c78e6d2066.jpg', 'https://phimimg.com/upload/vod/20260122-1/bdb89b2a2d278fc434972ed57acb2924.jpg', '<p>Tác phẩm kể về hành trình của Franklin Shepard theo cấu trúc thời gian đảo ngược: từ đỉnh cao thành công ở Hollywood trở về những ngày đầu tại Broadway. Qua từng mảnh ký ức, câu chuyện phơi bày cái giá của tham vọng, những mối quan hệ và lựa chọn đã định hình con người Frank. Phiên bản này là bản ghi hình trực tiếp của vở nhạc kịch Broadway đoạt giải Tony 2024.</p>', 'Full', 1, 'single', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jonathan Groff","avatar":""},{"name":"Lindsay Mendez","avatar":""},{"name":"Daniel Radcliffe","avatar":""},{"name":"Krystal Joy Brown","avatar":""},{"name":"Katie Rose Clarke","avatar":""},{"name":"Reg Rogers","avatar":""},{"name":"Sherz Aletaha","avatar":""},{"name":"Leana Rae Concepcion","avatar":""},{"name":"Coby Getzug","avatar":""},{"name":"Corey Mach","avatar":""},{"name":"Talia Simone Robinson","avatar":""},{"name":"Jamila Sabares-Klemm","avatar":""},{"name":"Evan Alexander Smith","avatar":""},{"name":"Brianna Stoute","avatar":""},{"name":"Christian","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '["A Vida em Três Acordes","Merrily We Roll Along"]', 1784690324136);
