INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thay-giao-so-nho', 'Thầy Giáo Số Nhọ', 'Straf', 'https://phimimg.com/upload/vod/20260122-1/47f7f9afb9d5f29db108563a5bac8f04.jpg', 'https://phimimg.com/upload/vod/20260122-1/067aafcf147f55476fda4061f3d9bfe7.jpg', '<p>Một giáo viên trung niên nhút nhát, bị xem thường cả trong gia đình lẫn nơi làm việc, đứng trước ngã rẽ khi giấc mơ thăng tiến bị dập tắt vì thiếu quyền uy. Với sự trợ giúp “tai hại” từ đồng nghiệp trái ngược hoàn toàn về tính cách, anh bước vào hành trình thay đổi bản thân, đầy hài hước, hỗn loạn và không ít hậu quả khó lường.</p>', 'Full', 1, 'single', 'completed', 22, 2025, 'Vietsub', 'FHD', 'Hà Lan', 0, '[{"name":"Rutger de Bekker","avatar":""},{"name":"Ruben van der Meer","avatar":""},{"name":"Sezgin Güleç","avatar":""},{"name":"Kylian de Pagter","avatar":""},{"name":"Raymonde de Kuyper","avatar":""},{"name":"Noëlle Simson","avatar":""},{"name":"Estefanio Pinas","avatar":""},{"name":"Yannick van de Velde","avatar":""},{"name":"Daniël Kolf","avatar":""},{"name":"Yari van der Linden","avatar":""},{"name":"Steef Cuijpers","avatar":""},{"name":"Lisa Zweerman","avatar":""},{"name":"Alex Ploeg","avatar":""},{"name":"Janice Blok","avatar":""},{"name":"Bobbie Mulder","avatar":""},{"name":"Yuani","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["After School","Straf"]', 1784690324136);
