INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-duong-trong-dem', 'Ánh Dương Trong Đêm', 'Midnight Sun', 'https://phimimg.com/upload/vod/20260122-1/433dff0c657c6f0d337e7a2164578d42.jpg', 'https://phimimg.com/upload/vod/20260122-1/66d38b21cd564b7eeb45b239aa8f0b58.jpg', '<p>Bộ phim xoay quanh một cô gái 17 tuổi mắc chứng dị ứng ánh nắng mặt trời, buộc phải sống khép kín và chỉ có thể ra ngoài vào ban đêm, nơi cô tìm thấy niềm vui khi chơi guitar và tình cờ gặp một chàng trai mà mình thầm ngưỡng mộ, mối quan hệ dần nảy nở trong những khoảnh khắc lãng mạn dưới màn đêm nhưng cũng đầy căng thẳng khi cô che giấu căn bệnh</p>', 'Full', 1, 'single', 'completed', 13, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jung Ji-so","avatar":""},{"name":"Cha Hak-yeon","avatar":""},{"name":"Jung Woong-in","avatar":""},{"name":"Jin Kyung","avatar":""},{"name":"Kim Sang-ho","avatar":""},{"name":"Kwon Han-sol","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["กลางคืนตลอดกาล กลางใจตลอดไป","Taeyang-ui norae","Midnight Sun","태양의 노래"]', 1784690324136);
