INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('anh-duong-trong-dem', 'Ánh Dương Trong Đêm', 'Midnight Sun', 'ánh dương trong đêm midnight sun jung ji-so cha hak-yeon jung woong-in jin kyung kim sang-ho kwon han-sol กลางคืนตลอดกาล กลางใจตลอดไป taeyang-ui norae midnight sun 태양의 노래', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bach-dao-co-dai-my-thuc-100-mon-my-vi-co-dai', 'Bách Đạo Cổ Đại Mỹ Thực (100 Món Mỹ Vị Cổ Đại)', '100 Ancient Delicacies (Ancient Recipes)', 'https://phimimg.com/upload/vod/20251130-1/04c5cb0051eb4cf230fe232fd31bebf6.jpg', 'https://phimimg.com/upload/vod/20251130-1/97e68f138f1d52961b72e1da62404f30.jpg', '<p>Thực phẩm là một dòng chảy lịch sử sống động, mang theo sự thay đổi của các thời đại và cũng ghi lại những chi tiết tinh tế nhất trong cuộc sống của người xưa.Bộ phim tài liệu 《100 Món Mỹ Vị Cổ Đại》 sẽ mở khóa mật mã vị giác của người xưa một cách nhẹ nhàng. Qua những cuộc trò chuyện vui vẻ, bộ phim tìm kiếm những hương vị đã thất truyền từ lâu, dùng ẩm thực để dẫn dắt người xem khám phá lịch sử và câu chuyện đằng sau chúng.Chương trình có sự tham gia của nhà văn, học giả văn hóa Đài Loan yêu thích văn hóa truyền thống Trung Quốc là Cao Văn Kỳ&nbsp; trong vai trò &quot;Chủ bếp chính&quot;. Ông sẽ cùng các khách mời nổi tiếng trong lĩnh vực ẩm thực và văn hóa trao đổi, khám phá, thử nghiệm, giải mã, và tái hiện những món ăn từ hàng ngàn năm trước trong một không khí hài hước, dí dỏm.Qua đó, bộ phim cũng tái hiện lại những văn hóa truyền thống và trí tuệ cuộc sống ẩn chứa trong ẩm thực cổ đại.</p>', 'Hoàn Tất (25/25)', 25, 'tvshows', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cao Văn Kỳ","avatar":""},{"name":"Trần Hiểu Khanh","avatar":""},{"name":"Đái Quân","avatar":""},{"name":"Chu Hiếu Thiên","avatar":""},{"name":"Phù Hạ · Đặng Lạc Phổ","avatar":""},{"name":"Tào Vũ","avatar":""},{"name":"Đái Quân","avatar":""},{"name":"Lâm Vệ Huy","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["100道古代美食"]', 1784690324137);
