INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bach-dao-co-dai-my-thuc-100-mon-my-vi-co-dai', 'Bách Đạo Cổ Đại Mỹ Thực (100 Món Mỹ Vị Cổ Đại)', '100 Ancient Delicacies (Ancient Recipes)', 'bách đạo cổ đại mỹ thực (100 món mỹ vị cổ đại) 100 ancient delicacies (ancient recipes) cao văn kỳ trần hiểu khanh đái quân chu hiếu thiên phù hạ · đặng lạc phổ tào vũ đái quân lâm vệ huy 100道古代美食', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-xinh-tinh-quai', 'Em Xinh Tinh Quái', 'Pretty Crazy', 'https://phimimg.com/upload/vod/20250919-1/a411be29d10f55b5a12d4bcbf536f4a8.jpg', 'https://phimimg.com/upload/vod/20250919-1/41084afc0b52fd447a989fdab5d54817.jpg', '<p>Cô ấy hóa quỷ khi trời rạng sáng! Gil Gu (Ahn Bo Hyun) – một chàng trai trẻ thất nghiệp, sống vật vờ trong căn hộ nhỏ sau khi từ bỏ công việc, bất ngờ bị cuốn hút bởi Sun Ji (Im Yoon Ah), cô hàng xóm xinh đẹp vừa chuyển đến tầng dưới. Một ánh nhìn, một nhịp tim lỡ, anh ngỡ đã tìm thấy tia sáng giữa cuộc sống tẻ nhạt. Nhưng rồi sáng hôm sau, trong thang máy, Gil Gu đối mặt với một Sun Ji hoàn toàn khác – ánh mắt dữ tợn, diện mạo kỳ quái, khiến anh bàng hoàng. Cô gái dịu dàng ban ngày dường như mang theo một mặt tối đáng sợ mỗi khi rạng sáng về. Lần theo những dấu hiệu lạ lùng, Gil Gu tìm đến cha của Sun Ji – ông Jang Su (Seong Dong Il) và phát hiện ra một bí mật kinh hoàng: Sun Ji là người bình thường vào ban ngày, nhưng khi trời sắp sáng… một con quỷ trong cô sẽ tỉnh giấc. Jang Su đề nghị Gil Gu một công việc nguy hiểm: trở thành người giám hộ cho Sun Ji mỗi khi bình minh cận kề. Tình yêu và nỗi sợ đan xen, liệu Gil Gu có thể vượt qua lời nguyền quỷ dữ trước khi mọi thứ vượt khỏi tầm kiểm soát?</p>', 'Full', 1, 'single', 'completed', 14, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 1, '[{"name":"Yoona","avatar":""},{"name":"Ahn Bo-hyun","avatar":""},{"name":"Sung Dong-il","avatar":""},{"name":"Joo Hyun-young","avatar":""},{"name":"Shin Hyun-soo","avatar":""},{"name":"Ko Gun-han","avatar":""},{"name":"Song Duk-ho","avatar":""},{"name":"Lee Hyo-bi","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":