INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-dan-loi', 'Người Dẫn Lối', 'The Wayfinders', 'https://phimimg.com/upload/vod/20260108-1/7f2a848c0f1cc85ee480273f7d1df2c6.jpg', 'https://phimimg.com/upload/vod/20260108-1/dd5b56027d449a0033985358b35ea7e3.jpg', '<p>Ba học sinh trung học vô tình bị đưa nhầm đến một thế giới trung cổ tàn khốc. Giữa cuộc nội chiến đẫm máu, họ kết giao với những đồng minh không ngờ tới và buộc phải chiến đấu để sinh tồn, đồng thời tìm cách quay trở về nhà.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Issy Knopfler","avatar":""},{"name":"Sam Buchanan","avatar":""},{"name":"Tamara Smart","avatar":""},{"name":"Rowan Robinson","avatar":""},{"name":"Mackenzie Crook","avatar":""},{"name":"Wes Chatham","avatar":""},{"name":"Andrew Liner","avatar":""},{"name":"Vince Mattis","avatar":""},{"name":"Nimmi Harasgama","avatar":""},{"name":"Filipe Cates","avatar":""},{"name":"Lawrence Walker","avatar":""},{"name":"Mimi Slinger","avatar":""},{"name":"Coulter Dittman","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Wayfinders"]', 1784690324137);
