INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dia-nguc-doc-than-phan-4', 'Địa Ngục Độc Thân (Phần 4)', 'Single''s Inferno (Season 4)', 'địa ngục độc thân (phần 4) single''s inferno (season 4) lee da-hee cho kyu-hyun hong jin-kyung hanhae dex solteiros, ilhados e desesperados single''s inferno solo hell 솔로지옥', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('zombie-cung-cua-ba', 'Zombie Cưng Của Ba', 'My Daughter is a Zombie', 'https://phimimg.com/upload/vod/20250927-1/a78cc05861f16028e314f1f9f3b26a7c.jpg', 'https://phimimg.com/upload/vod/20250927-1/d95d5531b3e25c78438ae09f57d4aad2.jpg', '<p>Zombie Cưng Của Ba đánh dấu sự trở lại của nam diễn viên Cho Jung Seok trên màn ảnh rộng năm nay. Cho Jung Seok hóa thân thành Lee Jung Hwan, một huấn luyện viên động vật đầy nhiệt huyết quyết tâm bảo vệ cô con gái tuổi teen bị nhiễm virus zombie bằng cách “thuần hóa” cô bé. Trải qua hành trình Jung Hwan đưa cô con gái nhiễm virus zombie Soo Ah đến ngôi làng ven biển, với nỗ lực bảo vệ cô bé khỏi sự truy quét của chính quyền. Tại đây, anh phát hiện Soo Ah vẫn còn giữ được ý thức con người, đặc biệt là niềm đam mê nhảy múa. Ngoài ra, cô bé vẫn nhận ra và vô cùng yêu thương bà của mình. Từ đó, Jung Hwan đưa ra quyết định quan trọng, đó là áp dụng kinh nghiệm huấn luyện động vật của chính mình để “thuần hóa” con gái, mở ra cuộc hành trình vừa hài hước vừa cảm động. Zombie Cưng Của Ba có đầy đủ yếu tố trở thành “bữa tiệc hè” đặc sắc từ xứ kim chi dịp hè 2025 khi đầy đủ các yếu tố cảm xúc HÀI - TÌNH - LỆ</p>', 'Full', 1, 'single', 'completed', 13, 2025, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Hàn Quốc', 1, '[{"name":"Cho Jung-seok","avatar":""},{"name":"Lee Jung-eun","avatar":""},{"name":"Cho Yeo-jeong","avatar":""},{"name":"Yoon Kyung-ho","avatar":""},{"name":"Choi Yu-ri","avatar":""},{"name":"Geumdong-i","avatar":""},{"name":"Kim Byung-choon","avatar":""},{"name":"Jo Han-sun","avatar":""},{"name":"Jung Hyung-suk","avatar":""},{"name":"Jeon Su-ji","avatar":""},{"name":"Lee Yun-chang","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a18