INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-trum-dau-mo-phan-2', 'Ông Trùm Dầu Mỏ (Phần 2)', 'Landman (Season 2)', 'https://phimimg.com/upload/vod/20251121-1/875f5f03198e2fd4f6c868deaad868e1.jpg', 'https://phimimg.com/upload/vod/20251121-1/c4982f2af013e3d9c0571073ff44a5c4.jpg', '<p><span style="text-wrap-mode: wrap;">Lấy bối cảnh tại những thị trấn bùng nổ của Tây Texas, bộ phim kể về cuộc săn tìm vận may trong thế giới giàn khoan dầu thời hiện đại. Đây là câu chuyện đối lập giữa tầng lớp lao động khắc khổ và các tỷ phú táo bạo, những người đang thổi bùng cơn sốt dầu mỏ khổng lồ – một làn sóng đủ mạnh để định hình lại khí hậu, nền kinh tế và cục diện chính trị toàn cầu.</span></p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Billy Bob Thornton","avatar":""},{"name":"Demi Moore","avatar":""},{"name":"Andy Garcia","avatar":""},{"name":"Ali Larter","avatar":""},{"name":"Jacob Lofland","avatar":""},{"name":"Michelle Randolph","avatar":""},{"name":"Paulina Chávez","avatar":""},{"name":"Kayla Wallace","avatar":""},{"name":"Mark Collie","avatar":""},{"name":"James Jordan","avatar":""},{"name":"Sam Elliott","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Човек на земята","Землевладелец","Землевласник","Землянин","Land Man","Landman"]', 1784690324137);
