INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bai-kiem-tra-copenhagen-phim-thi-nghiem-copenhagen', 'Bài Kiểm Tra Copenhagen (Phim Thí Nghiệm Copenhagen)', 'The Copenhagen Test', 'https://phimimg.com/upload/vod/20260105-1/7a2626e01e1ed6102ddbe126c84282b8.jpg', 'https://phimimg.com/upload/vod/20260105-1/3785f5d5335cdca7d769fd32fe7495dd.jpg', '<p>Phim xoay quanh nhân vật Alexander Hale (do Simu Liu thủ vai), một cựu lính bắn tỉa thuộc Lực Lượng Đặc Biệt, hiện đang làm chuyên viên phân tích cấp thấp cho một cơ quan tình báo bí mật có tên là &quot;The Orphanage&quot;. Cuộc sống của Alexander bị đảo lộn hoàn toàn khi anh phát hiện bộ não và các giác quan của mình đã bị “hack”, và một thế lực vô hình có thể nhìn thấy, nghe thấy và cảm nhận thế giới thông qua chính những gì anh trải nghiệm mỗi ngày. Alexander buộc phải giữ bình tĩnh, tiếp tục cuộc sống như không có chuyện gì xảy ra trong khi âm thầm tìm cách lật lại tình thế, khám phá ai là kẻ đứng sau vụ hack, đồng thời phải chứng minh sự trung thành với chính tổ chức của mình.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Simu Liu","avatar":""},{"name":"Melissa Barrera","avatar":""},{"name":"Sinclair Daniel","avatar":""},{"name":"Brian d''Arcy James","avatar":""},{"name":"Mark O''Brien","avatar":""},{"name":"Kathleen Chalfant","avatar":""},{"name":"Saul Rubinek","avatar":""},{"name":"Marnie McPhail","avatar":""},{"name":"Sara Amini","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144e