INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khe-uoc-ban-dau', 'Khế Ước Bán Dâu', 'Bride Of The Covenant', 'https://phimimg.com/upload/vod/20260118-1/490d98873185f55f8be905ee3f01baf1.jpg', 'https://phimimg.com/upload/vod/20260118-1/9876156c3ce357e76504844eea7fb38a.jpg', '<p>Lấy cảm hứng từ tiểu thuyết tâm linh của nhà văn Thục Linh kể về Nhài, một cô dâu trẻ xuất thân nghèo khó, được gả vào gia tộc họ Vũ giàu có tại vùng Kinh Bắc với hy vọng đổi đời.&nbsp; Tuy nhiên, cuộc hôn nhân sắp đặt nhanh chóng trở nên đáng sợ khi cô bị cuốn vào “khế ước” kinh hoàng nghi liên quan đến quỷ dữ và những nghi lễ tâm linh tăm tối. Dưới vẻ hào nhoáng, gia tộc che giấu bí mật đen tối, dẫn đến chuỗi sự kiện kỳ bí và sinh tử chờ Nhài đối mặt.&nbsp;</p>', 'Full', 1, 'single', 'completed', 24, 2025, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Lam Thanh My","avatar":""},{"name":"Hữu Vi","avatar":""},{"name":"Lãnh Thanh","avatar":""},{"name":"Trung Anh","avatar":""},{"name":"Minh Châu","avatar":""},{"name":"Phương Trà My","avatar":""},{"name":"Lê Tuyết Anh","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Khế Ước Bán Dâu"]', 1784690324137);
