INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-thoi-gian', 'Không Thời Gian', 'Space/Time', 'https://phimimg.com/upload/vod/20260117-1/36c4cff2e8d485223dd74fe447eeb4d7.jpg', 'https://phimimg.com/upload/vod/20260117-1/2e4382a5cacce3984085da5cb13af77b.jpg', '<p>Khi một nhóm các nhà khoa học đang phát triển động cơ du hành giữa các vì sao bị cắt giảm kinh phí sau một thảm họa chết người, nhóm này buộc phải chuyển sang hoạt động tội phạm để tài trợ cho hoạt động của mình trong khi họ xây dựng lại thiết bị du hành xuyên không gian và thời gian.</p>', 'Full', 1, 'single', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"Ashlee Lollback","avatar":""},{"name":"Hugh Parker","avatar":""},{"name":"Pacharo Mzembe","avatar":""},{"name":"Haroon Jafarey-Hall","avatar":""},{"name":"Shaun King","avatar":""},{"name":"Craig Gaffney","avatar":""},{"name":"Rob Horton","avatar":""},{"name":"Sophia Emberson-Bain","avatar":""},{"name":"Gareth Harris","avatar":""},{"name":"Robin Darch","avatar":""},{"name":"Erin Connor","avatar":""},{"name":"Damien Campagnolo","avatar":""},{"name":"Madison Sturgess","avatar":""},{"name":"Loretta Kung","avatar":""},{"name":"Cate Feldmann","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Пространство/Время","Space/Time"]', 1784690324137);
