INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ultraman-omega', 'Ultraman Omega', 'Ultraman Omega', 'https://phimimg.com/upload/vod/20250705-1/fc4d32801c5acc9cd83f9bde967200b5.jpg', 'https://phimimg.com/upload/vod/20250705-1/c136845c971bd31ec74a88c955db3457.jpg', '<p>Lấy bối cảnh Trái Đất chưa từng có siêu anh hùng hay quái thú, một người ngoài hành tinh bị mất trí nhớ, bất ngờ rơi xuống từ bầu trời. Anh lấy tên Sorato và bắt đầu khám phá thế giới loài người đầy cảm xúc lẫn mâu thuẫn. Khi những con quái thú khổng lồ lần đầu xuất hiện, Sorato vô thức nhớ lại sứ mệnh của mình và biến thân thành Ultraman Omega, sử dụng vũ khí đặc trưng Omega Slugger để chiến đấu bảo vệ Trái Đất.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 15, 2025, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Kondo Shori","avatar":""},{"name":"Yoshida Haruto","avatar":""},{"name":"Kudo Ayano","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ultra.B","奥美迦奥特曼","超人奧米加","Urutoraman Omega","超人力霸王奧米加","ウルトラマンオメガ"]', 1784690324137);
