INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-nu-diep-vu-tho-xu-ly-vuong-mien-4', 'Năm Nữ Điệp Vụ: Thợ Xử Lý Vương Miện 4', 'Princess Principal Crown Handler: Chapter 4', 'https://phimimg.com/upload/vod/20260117-1/11e14384f6a491cecaa555749df595dc.jpg', 'https://phimimg.com/upload/vod/20260117-1/a4b20f17535c027cb1369282fb04eb2c.jpg', '<p>Trong lúc tang lễ của Hoàng tử Edward — người đứng đầu hàng kế vị vừa bị ám sát — đang diễn ra, các quý tộc của Vương quốc Albion đang ráo riết bàn tán về việc ai sẽ là người kế thừa ngai vàng: Công chúa Mary (hàng kế vị thứ hai) hay Công tước xứ Arkham - Hoàng tử Richard (hàng kế vị thứ ba), cũng như động thái tiếp theo của Đại công tước Normandy sẽ là gì?Công tước xứ Arkham đã trực tiếp chất vấn Công chúa (Princess), buộc cô phải chọn phe. Mặc dù khao khát sửa đổi thế giới thành một nơi bình đẳng cho mọi dân tộc, nhưng Công tước xứ Arkham lại chính là kẻ chủ mưu đứng sau vụ ám sát Hoàng tử Edward, điều này khiến nội tâm Công chúa dao động dữ dội.Giữa bối cảnh đó, tổ chức tình báo của Cộng hòa đã ra lệnh cho Ange và Dorothy thực hiện nhiệm vụ thâm nhập dưới danh nghĩa hầu gái của Mary để dò xét tình hình hoàng gia. Gánh nặng của người đứng đầu hàng kế vị mới đã khiến Mary kiệt sức. Trong cuộc chiến giành ngai vàng này, âm mưu của Công tước xứ Arkham cuối cùng cũng chính thức bắt đầu. Bóng tối ẩn khuất trong Vương quốc Albion đang chực chờ nuốt chửng Đội Bồ Câu Trắng.</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Aoi Koga","avatar":""},{"name":"Akira Sekine","avatar":""},{"name":"You Taichi","avatar":""},{"name":"Akari Kageyama","avatar":""},{"name":"Nozomi Furuki","avatar":""},{"name":"Takayuki Sugo","avatar":""},{"name":"Miyuki Sawashiro","avatar":""},{"name":"Takumi Yamazaki","avatar":""},{"name":"Takaya Hashi","avatar":""},{"name":"Yuuko Iida","avatar":""},{"name":"Hiroyuki Honda","avatar":""},{"name":"Rina Endou","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["プリンセス・プリンシパル Crown Handler 第4章"]', 1784690324137);
