INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-thanh-ho-ngam', 'Thanh Thanh Hồ Ngâm', 'The Fox''s Chant', 'https://phimimg.com/upload/vod/20260110-1/f754187c2b33d26dffb1a7e0b735cddf.jpg', 'https://phimimg.com/upload/vod/20260110-1/ce266ca25f791db49472e769fda71161.jpg', '<p>Mấy nghìn năm trước, thần bếp thao thiết của tộc tiên là Dao Linh Nhi độ kiếp thất bại ở vùng đất cực hàn. Lôi hỏa độ kiếp vô tình giải phong ấn cho hồ yêu Thanh Khâu, hắn lấy lại được tự do sau nhiều năm bị giam cầm, đồng thời cứu được Dao Linh Nhi đang thoi thóp hơi tàn. Để tránh sự truy đuổi của tộc tiên, Dao Linh Nhi đưa hồ yêu Thanh Khâu về nhà dưỡng thương, nhiều năm sau hai người âm thầm nảy sinh tình cảm. Đại sư huynh của Dao Linh Nhi là thượng tiên Mặc Nam phát hiện ra mối tình này, mới bày kế khiến hai người hiểu lầm và trở mặt nhau, hồ yêu ôm hận mà chết, Dao Linh Nhi muốn hóa giải hận thù nên cũng xuống trần gian lịch kiếp. Dưới phàm trần, hồ yêu hóa thân thành Hạ Tiêu Dao, chịu cảnh tan cửa nát nhà từ khi còn nhỏ nên một lòng muốn báo thù, Dao Linh Nhi giúp đỡ hắn điều tra ra sự thật.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hàn Tiêu Dao","avatar":""},{"name":"Tôn Yến Ân","avatar":""},{"name":"Tiền Tiền Di","avatar":""},{"name":"Phương Nghi Ân","avatar":""},{"name":"Vương Di Xuân","avatar":""},{"name":"Từ Lệ Sa","avatar":""},{"name":"Triệu Văn Văn","avatar":""},{"name":"Chu Tử Tuấn","avatar":""},{"name":"Trương Ngọc Hàn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Qing Qing Hu Yin","炊烟袅袅夏雨来","青青狐吟"]', 1784690324137);
