INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('top-form-the-series', 'Top Form The Series', 'Top Form', 'https://phimimg.com/upload/vod/20250321-1/2ddbcf571f34c794c2f9e610fbe77fca.jpg', 'https://phimimg.com/upload/vod/20250321-1/56976051d34dcac987bd77347cb33c04.jpg', '<p>Akin, 28 tuổi, là một siêu sao hàng đầu trong ngành giải trí Thái Lan. Anh bước chân vào làng giải trí từ năm 8 tuổi, dần khẳng định bản thân và trở thành một siêu sao hàng đầu. Với khả năng diễn xuất tuyệt vời và ngoại hình điển trai, Akin liên tục giữ vững danh hiệu &quot; người đàn ông được khao khát nhất&quot; trong năm năm liền. Tuy nhiên vào một ngày nọ, Jin - một diễn viên trẻ mới nổi, bắt đầu xuất hiện và tạo dấu ấn trong làng giải trí cũng như trong cuộc đời Akin.</p>', 'Full', 11, 'series', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Raweewit Jiraphongkanon","avatar":""},{"name":"Chisanupong Paungmanee","avatar":""},{"name":"Pongsakorn Mettarikanon","avatar":""},{"name":"Peeranat Veeranipitkul","avatar":""},{"name":"Waratthip Kittiphaisan","avatar":""},{"name":"Kannaporn Puangtong","avatar":""},{"name":"Nantawat Palakawongsna Ayudhya","avatar":""},{"name":"Thanakorn Thipsuk","avatar":""},{"name":"Thititat Wattanamethachaipat","avatar":""},{"name":"Kongkiat Khomsiri","avatar":""},{"name":"Worawat Kojh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["抱かれたい男1位に脅されています。","Dakaichi: I''m Being Harassed by the Sexiest Man of the Year","กอดกันมั้ย นายตัวท็อป"]', 1784690324137);
