INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('top-form-the-series', 'Top Form The Series', 'Top Form', 'top form the series top form raweewit jiraphongkanon chisanupong paungmanee pongsakorn mettarikanon peeranat veeranipitkul waratthip kittiphaisan kannaporn puangtong nantawat palakawongsna ayudhya thanakorn thipsuk thititat wattanamethachaipat kongkiat khomsiri worawat kojh 抱かれたい男1位に脅されています。 dakaichi: i''m being harassed by the sexiest man of the year กอดกันมั้ย นายตัวท็อป', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rong-ngam-ngoc-quy-thuo-nao-ve', 'Rồng Ngậm Ngọc Quý Thuở Nào Về', 'Love After Eternity', 'https://phimimg.com/upload/vod/20260110-1/ad8b63ab3d6859170b8ed01ae9871dc4.jpg', 'https://phimimg.com/upload/vod/20260110-1/963c4233337ab47f80c38c82e1571e8b.jpg', '<p>Thiên tôn thống trị Thiên tộc bằng thủ đoạn sắt đá, vạn năm trước khơi mào trận chiến Tru Tiên Đài, khiến thiếu chủ Long tộc Long Hàm và chiến thần Thiên tộc Anh Lạc chết chung. Nào ngờ Long Hàm lại chính là cháu ngoại ruột của mình, mang trong mình huyết thống Thiên tộc, vạn năm sau lại tái sinh với thân xác bất tử. Thiên Tôn dựa trên nguyên tắc tối đa hóa tỷ lệ thành công, phái nữ chiến thần Anh Lạc cũng vừa tái sinh một lần nữa đến Long tộc để thu phục Long Hàm. Nào ngờ lần này Long Hàm không còn cứng rắn đối đầu, mà dâng lên vị trí hộ pháp Long tộc, dùng sự chân thành đổi lấy tình cảm thực sự, tự dấn thân vào cuộc chơi lôi kéo Anh Lạc. Trong cuộc đọ sức đầy rẫy âm mưu, hai người dần thấu hiểu và yêu thương nhau. Thiên Tôn không thể dung thứ cho sự phản bội của kẻ dưới, bèn phong ấn thần lực của Anh Lạc.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hàn Tiêu Dao","avatar":""},{"name":"Trương Ngọc Hàn","avatar":""},{"name":"Chu Tử Tuần","avatar":""},{"name":"Sui Min Dương","avatar":""},{"name":"Đái Thiệu Đông","avatar":""},{"name":"Vương Diệp Xuân","avatar":""},{"name":"Hàn Tiểu Dao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387e