INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('rong-ngam-ngoc-quy-thuo-nao-ve', 'Rồng Ngậm Ngọc Quý Thuở Nào Về', 'Love After Eternity', 'rồng ngậm ngọc quý thuở nào về love after eternity hàn tiêu dao trương ngọc hàn chu tử tuần sui min dương đái thiệu đông vương diệp xuân hàn tiểu dao long xian ying luo ji shi gui love after eternity 龙衔璎珞几时归', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khinh-nien', 'Khinh Niên', 'Forever Young', 'https://phimimg.com/upload/vod/20260101-1/209bdac4d647ea17ac6964c2522f7e02.jpg', 'https://phimimg.com/upload/vod/20260101-1/68ad76e4a412f9254a71eade9e05488d.jpg', '<p>Vào những năm 80, Mã Đinh và ba người bạn thân thiết như anh em ruột thịt cùng nhau lớn lên trong một con ngõ nhỏ ở Bắc Kinh. Trước ngày tốt nghiệp cấp ba, Mã Đinh gây ra một biến cố khiến tình bạn của họ tan vỡ, mỗi người một ngả. Thanh xuân qua đi, Mã Đinh đi nước ngoài, kể từ đó bặt vô âm tín. Nhiều năm sau, Mã Đinh - nay đã trở thành phó tổng một công ty niêm yết - bỗng dưng phát hiện mình bị u não, anh cứ thế đơn độc bình tĩnh chờ đợi cái chết. Tuy nhiên, trong lòng Mã Đinh vẫn có nỗi day dứt khôn nguôi khiến anh không thể nào từ bỏ. Anh muốn trước khi rời khỏi thế giới này tháo gỡ khúc mắc xưa, hàn gắn lại tình bạn. Bốn người trung niên cùng nhau gây dựng sự nghiệp, cuộc sống của cả bốn người đều thay đổi, tình bạn giữa họ cũng dần dần được hàn gắn, và Mã Đinh cũng một lần nữa dấy lên hy vọng về cuộc sống.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hoắc Kiến Hoa","avatar":""},{"name":"Điền Vũ","avatar":""},{"name":"Trương Tuyết Nghênh","avatar":""},{"name":"Kiều Chấn Vũ","avatar":""},{"name":"Lưu Đoan Đoan","avatar":""},{"name":"Tùy Tuấn Ba","avatar":""},{"name":"Trương Dao","avatar":""},{"name":"Tiết Hạo Tịnh","avatar":""},{"name":"Chúc Tử Kiệt","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["轻年"]', 1784690324137);
