INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khinh-nien', 'Khinh Niên', 'Forever Young', 'khinh niên forever young hoắc kiến hoa điền vũ trương tuyết nghênh kiều chấn vũ lưu đoan đoan tùy tuấn ba trương dao tiết hạo tịnh chúc tử kiệt 轻年', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-kien-anh-sang-nui-voi', 'Sự Kiện Ánh Sáng Núi Voi', 'Illuminant Object', 'https://phimimg.com/upload/vod/20260116-1/c556a790d65b8db9bee0995ccc22d88f.jpg', 'https://phimimg.com/upload/vod/20260116-1/d912f8d7d92bf0d6c9b7b8ca863c8be7.jpg', '<p>Mười năm trước, một sự kiện phát sáng siêu nhiên đã khiến người bạn thân của Trương Bằng mất tích một cách bí ẩn. Mười năm sau, một đoàn làm phim tìm đến Trương Bằng và đề nghị anh cùng quay trở lại hiện trường vụ việc năm xưa tại Tượng Sơn để thực hiện một bộ phim tìm kiếm sự thật. Tuy nhiên, những mô tả khác nhau từ những người được phỏng vấn tại Tượng Sơn về sự kiện năm đó đã khiến cuộc điều tra rơi vào vô vàn bí ẩn.Khi họ vượt qua nhiều gian nan để tiến vào một hang động nhân tạo bí mật, họ bàng hoàng phát hiện ra rằng mọi cái gọi là &#39;ẩn đố&#39; thực chất đều là sự dàn dựng có ý đồ của đạo diễn. Nhưng liệu sự thật chỉ đơn giản là như vậy? Trong hang động kỳ quái như một mê cung này, ranh giới giữa kẻ thao túng và người bị thao túng đã không còn thể xác định. Khi cánh cửa xi măng bám đầy bụi thời gian được đẩy ra, mọi chuyện diễn ra trước mắt đã vượt xa khỏi trí tưởng tượng của tất cả bọn họ...</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tiểu Thẩm Dương","avatar":""},{"name":"Vương Duy","avatar":""},{"name":"Trương Đăng Bình","avatar":""},{"name":"Nghi Cảnh Dương","avatar":""},{"name":"Điền Lý","avatar":""},{"name":"Đông Chí Di","avatar":""},{"name":"Hồ Đồ","avatar":""},{"name":"Lý Âu","avatar":""},{"name":"Mạnh Hòa Ô Lực Cập","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["象山发光事件"]', 1784690324137);
