INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-anh-huong-xau-cau-chuyen-jodi-hildebrandt', 'Người Ảnh Hưởng Xấu: Câu Chuyện Jodi Hildebrandt', 'Evil Influencer: The Jodi Hildebrandt Story', 'https://phimimg.com/upload/vod/20260116-1/6f405680321e667397db927706be3a57.jpg', 'https://phimimg.com/upload/vod/20260116-1/6417568f56b4bf13ef8cbea1cfe9bcb5.jpg', '<p>Cùng bóc tách vụ án về nhà trị liệu tâm lý Jodi Hildebrandt tại bang Utah, người bị bắt giữ vì tội bạo hành trẻ em cùng với YouTuber chuyên về nuôi dạy con cái Ruby Franke, qua đó phơi bày một câu chuyện đầy đen tối về sự thao túng và kiểm soát.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jodi Hildebrandt","avatar":""},{"name":"Ruby Franke","avatar":""},{"name":"Jessica Bate","avatar":""},{"name":"Eric Clarke","avatar":""},{"name":"Ethan Prete","avatar":""},{"name":"Valerie Jackson","avatar":""},{"name":"Natasha Helfer","avatar":""},{"name":"Laura Howells Leavitt","avatar":""},{"name":"Kathy Kinghorn","avatar":""},{"name":"Christi Judd","avatar":""},{"name":"James E. Faust","avatar":""},{"name":"Chad Franke","avatar":""},{"name":"Kevin Franke","avatar":""},{"name":"Shari Franke","avatar":""},{"name":"Jessi Hildebrandt","avatar":""},{"name":"Dallin H. Oaks","avatar":""},{"name":"John J","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Evil Influencer: The Jodi Hildebrandt Story"]', 1784690324137);
