INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-lang-nhan-sinh', 'Lãng Lãng Nhân Sinh', 'Row To Win', 'https://phimimg.com/upload/vod/20260116-1/95f029aa8b0afe0ae049371d314204d1.jpg', 'https://phimimg.com/upload/vod/20260116-1/04b3f2b7024162856ef7653db15407a1.jpg', '<p>Từng một thời hô mưa gọi gió ở thị trấn, “đại ca” Hoàng Vinh Phát nay đã miệng cứng nhưng chân run, bước vào giai đoạn khó khăn của cuộc đời. Thế nhưng, anh cùng gia đình vẫn không để số phận vùi dập. Cậu con trai Hoàng Viễn Đạt bề ngoài tưởng như là người “nhạt nhòa” nhất trong nhà họ Hoàng, nhưng thực chất lại âm thầm toan tính cách làm giàu và “trị cha”. Người vợ Trần Lê Trân thì toàn năng, vượt qua mọi trở ngại, nổi tiếng khắp thị trấn là “mẹ siêu nhân” không dễ động vào. Cô con Hoàng Kiều Kiều liều lĩnh, còn bà cố A Thái lại “thần thông quảng đại”, mỗi người đều tung chiêu riêng mang đến không ít tình huống dở khóc dở cười.</p>', 'Full', 1, 'single', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Huang Bo","avatar":""},{"name":"Adam Fan","avatar":""},{"name":"Yin Tao","avatar":""},{"name":"Chang Yuan","avatar":""},{"name":"Jackie Li","avatar":""},{"name":"Leanne Liu","avatar":""},{"name":"Fu Hang","avatar":""},{"name":"Sun Yizhou","avatar":""},{"name":"Zhang Benyu","avatar":""},{"name":"Yi Xiaoxing","avatar":""},{"name":"Xiao Ai","avatar":""},{"name":"Deng Enxi","avatar":""},{"name":"Li Zhiliang","avatar":""},{"name":"Andy Lau","avatar":""},{"name":"Hao Han","avatar":""},{"name":"Zhuang Yuan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["浪浪人生"]', 1784690324137);
