INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chan-dung-nguoi-nghe-si', 'Chân Dung Người Nghệ Sĩ', 'Peter Hujar''s Day', 'https://phimimg.com/upload/vod/20260116-1/005ef8d8438c155a79a23917a65f3bd9.jpg', 'https://phimimg.com/upload/vod/20260116-1/ac1ca4ccebb071fc84653299a07f8a29.jpg', '<p>Một cuộc trò chuyện giữa nhiếp ảnh gia Peter Hujar và người bạn Linda Rosenkrantz vào năm 1974 hé lộ một lát cắt của giới nghệ thuật downtown New York, cùng những đấu tranh cá nhân và khoảnh khắc khai sáng định hình nên cuộc đời của một nghệ sĩ.</p>', 'Full', 1, 'single', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ben Whishaw","avatar":""},{"name":"Rebecca Hall","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Peter Hujar''s Day"]', 1784690324137);
