INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-co-an-cuu-luc-pha-phong', 'Hoang Cổ Ân Cừu Lục: Phá Phong', 'Chronicles of Grace and Grudges in the Primordial Age / Enmity in the Primordial Wasteland: The Wind-Breaking Chapter', 'https://phimimg.com/upload/vod/20250930-1/f11f0b3e77f2bbd6bdbc29ee75a8eaae.jpg', 'https://phimimg.com/upload/vod/20250930-1/b152d95b7f11513dd9194f0da3290cb2.jpg', '<p>Từ những kỳ vọng được đặt vào bản thân nhiều nhất cho đến khi bị dồn nén đến cùng cực, sức chịu đựng đạt đến giới hạn thì mọi thứ sẽ trở nên bộc phát một cách dữ dội. Đó cũng chính là hoàn cảnh đầy khắc nghiệp của cậu thiếu niên Tân Phong, người đã phải trải qua đủ mọi cung bậc cảm xúc của cuộc đời này, từ hy vọng cho đến tuyệt vọng, để rồi phải kiên cường vượt lên chính bản thân mình. Sinh ra trong một gia tộc có tiếng tăm trong kinh đô nhưng họa diệt tộc ập đến đầy ngang trái, những thiên phú đầy tự hào cũng dần mất đi, Tân Phong phải dạt đến một tông môn vô danh để ẩn náu và âm thầm rèn luyện bản thân. Tưởng như làm vậy thì đã là tạm thời yên phận nhưng người vị sư tỷ đồng cảnh ngộ ra, mọi người đều coi thường và luôn mang Tân Phong ra để làm trò cười. Bị dìm hàng như vậy nhưng Tân Phong vẫn luôn nhẫn nhịn để thầm lặng rèn luyện trong khổ cực, che giấu thực lực ngày một trỗi dậy của mình.</p>', 'Tập 40', 80, 'hoathinh', 'ongoing', 28, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zezong Tang","avatar":""},{"name":"Fabiao De Woniu","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Chronicles of Grace and Grudges in the Primordial Age","荒古恩仇录"]', 1784690324137);
