INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-sinh-vo-hon', 'Song Sinh Võ Hồn', 'The Rise Of Twin Souls', 'https://phimimg.com/upload/vod/20250725-1/4ca116d416f7e7b621bc5cbe8f03df98.jpg', 'https://phimimg.com/upload/vod/20250725-1/c8f465cee0f9ff68ac8425e55add699d.jpg', '<p>Lâm Phàm, xuất thân từ thế gia tại Đại Lâm quận, vốn là thiên tài tuyệt thế sở hữu Thiên Kiêu Lệnh, nhưng lại bị vị hôn thê đoạt mất võ hồn, trở thành phế vật. Khi một Ma Vương lai lịch thần bí ký sinh trên người, hắn khôi phục được võ hồn đã bị phế và trở thành người mang thể chất song võ hồn hiếm có. Từ đây, Lâm Phàm chính thức bước lên con đường quật khởi, từ một tiểu thành của quận nhỏ, tung hoành chư thiên vạn giới.</p>', 'Tập 60', 60, 'hoathinh', 'ongoing', 10, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Wang Qiuhao","avatar":""},{"name":"Liu Man","avatar":""},{"name":"Li Min","avatar":""},{"name":"Shi Zekun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Shuang Sheng Wu Hun","Shuangsheng Wu Hun","至尊武魂","Dual Martial Soul","Twin Martial Souls","TheRiseOfTwinSouls","Twin Martial Spirits","双生武魂"]', 1784690324137);
