INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-upshaw-phan-6', 'Gia Đình Upshaw (Phần 6)', 'The Upshaws (Season 6)', 'https://phimimg.com/upload/vod/20260115-1/b0796b1be1e123af89484cfaa90f44b0.jpg', 'https://phimimg.com/upload/vod/20260115-1/d9772c02d90e02b8e312e64f4a98f729.jpg', '<p>Gia đình người da đen thuộc tầng lớp lao động tại Indiana phấn đấu vì cuộc sống tốt hơn và mái ấm hạnh phúc, và cả xoay xở với khó khăn hàng ngày trong loạt phim hài này.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mike Epps","avatar":""},{"name":"Kim Fields","avatar":""},{"name":"Wanda Sykes","avatar":""},{"name":"Khali Spraggins","avatar":""},{"name":"Journey Christine","avatar":""},{"name":"Jermelle Simon","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Upshaws"]', 1784690324137);
