INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-ky-than-yeu-cua-toi', 'Thư Ký Thân Yêu Của Tôi', 'Dear Secretary', 'https://phimimg.com/upload/vod/20260109-1/fa6e0af55f3ff8dd13997e8f0fc14e91.jpg', 'https://phimimg.com/upload/vod/20260109-1/70dfa827baacc3e918ec8d8947703561.jpg', '<p>Bộ phim kể về câu chuyện giữa sếp nữ xinh đẹp, quyền lực và nam thư ký điển trai từng du học nước ngoài. Trong môi trường công sở khắc nghiệt, hai người đã cùng nhau phối hợp công tác. Từ chỗ không ưa nhau lúc đầu, họ dần nảy sinh tình cảm, cuối cùng quyết định gắn bó và cùng nhau đi hết quãng đời còn lại.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Bao Hàm","avatar":""},{"name":"Từ Tử Tuyền","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wo Qin Ai De Mi Shu","Jin Mi Shu Wei He Na Yang Zhong Guo Ban","我親愛的秘書","金秘书为何那样中国版","金秘書為何那樣中國版","Что случилось с секретарём Цзинь?","My Dear Secretary","我亲爱的秘书"]', 1784690324137);
