INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-thien-doc-ton', 'Lăng Thiên Độc Tôn', 'Overlord Of The Sky', 'https://phimimg.com/upload/vod/20250719-1/9d75341ac87b3cee68b2c02e8726bb0e.jpg', 'https://phimimg.com/upload/vod/20250719-1/b5864c72d2f3811c4a81cffcd67eaa4d.jpg', '<p>Nổi tiếng khắp giang hồ như một vị cao thủ kiếm thánh nhưng vì để bảo vệ người tình trong mộng của mình mà Lăng Thiên đã phải làm những việc đi ngược với đạo trời, chính vì vậy mà anh chàng đã bị Thiên Đạo nhắm đến và nổ ra một trận chiến kinh thiên động địa. Trong thời khắc quyết định, Lăng Thiên đã nằm xuống cùng với Thiên Đạo. Nhưng tưởng như vậy là đã đăng xuất thì Lăng Thiên lại bị đưa ngược trở lại thời điểm 300 năm về trước, đó là lúc mà mọi thứ còn đang dang dở, người yêu đang bên cạnh hắn, nhưng kẻ thù cũng vẫn còn đó, thậm chí là hắn lại phải tu luyện một lần nữa để quay trở lại đỉnh cao của kiếm thánh. Con đường tu luyện dài đằng đẵng một lần nữa mở ra, thách thức và đợi chờ Lăng Thiên chinh phục.</p>', 'Tập 60', 80, 'hoathinh', 'ongoing', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Ling Tian Du Zun","Ling Tian Duzun","Lingtian Duzun","Ling Tian Du Zu","Ling Tian Duzu","Lingtian Duzu","Ling Tian Supremacy","Líng Tiān Dú Zūn","Líng Tiān Dúzūn","Lingtian Dominates","Suprématie de Ling Tian","Supreme Over the Sky","Lăng Thiên Độc Tôn","凌天独尊"]', 1784690324137);
