INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-cho-thanh-vien-palm-beach', 'Chỉ Cho Thành Viên: Palm Beach', 'Members Only: Palm Beach', 'https://phimimg.com/upload/vod/20260114-1/21a523795a39119be42f06192780665b.jpg', 'https://phimimg.com/upload/vod/20260114-1/0703c45b21c989fccc86f2f0bb201d3e.jpg', '<p>Bên trong những khu biệt lập dành riêng cho giới thượng lưu tại Quận Palm Beach, hãy cùng theo chân một nhóm phụ nữ đang chèo lái giữa những quy tắc ngầm, những truyền thống kế thừa và hệ thống thứ bậc đầy khốc liệt của những vòng tròn xã hội tinh hoa nhất nước Mỹ. Trong thế giới của đặc quyền và những câu lạc bộ tư nhân vốn được chăm chút tỉ mỉ này, danh tiếng được xây dựng bên những bữa ăn trưa (brunch), các liên minh thay đổi theo từng ly sâm panh, và dù sự giàu có là thứ có mặt ở khắp mọi nơi, thì quyền lực, tầm ảnh hưởng và sự kết nối mới chính là loại tiền tệ thực sự.</p>', 'Hoàn Tất (8/8)', 8, 'tvshows', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Taja Abitbol","avatar":""},{"name":"Maria Cozamanis","avatar":""},{"name":"Hilary Musser","avatar":""},{"name":"Ro-mina Ustayev","avatar":""},{"name":"Rosalyn Yellin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Üyelere Özel Palm Plajı","Members Only: Palm Beach"]', 1784690324137);
