INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-tich-2025', 'Kỳ Tích', 'The Miracles', 'https://phimimg.com/upload/vod/20251223-1/c4e64a0bfc65b599700f812f04b0526d.jpg', 'https://phimimg.com/upload/vod/20251223-1/f6c8a753a026d35f699436a16e7f7c5c.jpg', '<p>Vở kịch lấy việc khắc họa &quot;kỳ tích&quot; làm ý tưởng trung tâm, tập trung vào những thành tựu rực rỡ và tầm nhìn phát triển tương lai của Thâm Quyến trong 45 năm cải cách mở cửa. Thông qua cách kể chuyện nghệ thuật, tác phẩm thể hiện tinh thần đô thị độc đáo và khí chất thanh xuân tràn đầy của thành phố này.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hồ Ca","avatar":""},{"name":"Tống Giai","avatar":""},{"name":"Lôi Giai Âm","avatar":""},{"name":"Diêm Ni","avatar":""},{"name":"Trương Tụng Văn","avatar":""},{"name":"Bạch Vũ","avatar":""},{"name":"Trần Hiểu","avatar":""},{"name":"Đồng Dao","avatar":""},{"name":"Vương An Vũ","avatar":""},{"name":"Vu Thích","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Qi Ji","奇蹟","The Miracles","Red Dust Odyssey","Wing Chun Rhythm","The Keyboard of Dreams","A Mother''s Venture","The Missing Head","Niuniu the Yak","The Spark","Echoes of Tomorrow","Life In a Lift","Tides of the Mangrove","The Summer We Met","The Road Back to Love","Family 2.0","奇迹"]', 1784690324137);
