INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ky-tich-2025', 'Kỳ Tích', 'The Miracles', 'kỳ tích the miracles hồ ca tống giai lôi giai âm diêm ni trương tụng văn bạch vũ trần hiểu đồng dao vương an vũ vu thích qi ji 奇蹟 the miracles red dust odyssey wing chun rhythm the keyboard of dreams a mother''s venture the missing head niuniu the yak the spark echoes of tomorrow life in a lift tides of the mangrove the summer we met the road back to love family 2.0 奇迹', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-ma-nha-xi-hanako-phan-2', 'Cậu Ma Nhà Xí Hanako (Phần 2)', 'Toilet-Bound Hanako-kun (Season 2)', 'https://phimimg.com/upload/vod/20250401-1/a2fd041e426605d25f5233bf17b19dba.jpg', 'https://phimimg.com/upload/vod/20250401-1/2a70d136a88b90f1df605e66f83d138e.jpg', '<p>Tại Học viện Kamome, có một lời đồn rằng đâu đó trong khuôn viên trường hiện hữu một chiếc đồng hồ cai quản dòng chảy thời gian của toàn học viện. Chiếc đồng hồ đó được trông coi bởi ba người gác đồng hồ — mỗi người đại diện cho quá khứ, hiện tại và tương lai. Thế nhưng, một sự cố không lường trước đã gây ra sự hỗn loạn: các học sinh đột ngột già đi nhanh chóng và cơ sở vật chất của học viện thì mục nát, đổ nát.Nene Yashiro và Kou Minamoto đã tìm đến sự trợ giúp từ Hanako-kun, dấn thân vào một cuộc phiêu lưu mới để tìm ra kẻ chịu trách nhiệm cho mớ hỗn độn này. Tuy nhiên, thứ họ khám phá ra còn nhiều hơn cả danh tính của thủ phạm. Khi những sự thật ẩn giấu dần được hé lộ và những lời thề mới được thiết lập, các học sinh và những linh hồn trong học viện thấy mình bị cuốn vào một trò chơi của định mệnh — nơi những người sống phải chiến đấu để thoát khỏi vòng vây của nó.</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Megumi Ogata","avatar":""},{"name":"Akari Kito","avatar":""},{"name":"Shoya Chiba","avatar":""},{"name":"Yuma Uchida","avatar":""},{"name":"Takahiro Mizushima","avatar":""},{"name":"Chika Anzai","avatar":""},{"name":"Chitose Morinaga","avatar":""},{"name":"Megumi Ogata","avatar":""},{"name":"Shunichi Toki","avatar":""},{"name":"Yukana","avatar":""},{"name":"Yu-ri Yoshida","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hanako-kun: El fantasma del lavabo","Jibaku Shounen Hanako-kun","Jibaku Shōnen Hanako-kun","地縛少年花子くん２","Hanako, duch ze szkolnej toalety","ฮานาโกะคุง วิญญาณติดที่","Туалетний хлопчина Ханако","地縛少年花子くん"]', 1784690324137);
