INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nukitashi-the-animation', 'Nukitashi The Animation', 'Nukitashi The Animation', 'https://phimimg.com/upload/vod/20250822-1/a3f09c8a535f4b8ca9c846f3c34bf467.jpg', 'https://phimimg.com/upload/vod/20250822-1/1d1ecfe8be323ca8ab36ddfc879ed87d.jpg', '<p>Trên đảo Seiran, tổ chức bí mật NLNS được tập hợp dưới sự dẫn dắt của Junnosuke Tachibana, người quyết tâm phá bỏ một đạo luật. Họ đã tìm được một nhà tài trợ — một người đàn ông giàu có bí ẩn — người cung cấp cho họ một căn cứ bí mật và tiền bạc. Nhiệm vụ của họ là tìm ra một cô gái thần bí và ngăn chặn đạo luật, đồng thời tránh bị SHO lần theo dấu vết.</p>', 'Full', 11, 'hoathinh', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kouhei Yanagi","avatar":""},{"name":"Shizuka Ishigami","avatar":""},{"name":"Minori Ozawa","avatar":""},{"name":"Rie Okamoto","avatar":""},{"name":"Ako Koaki","avatar":""},{"name":"Masumi Tazawa","avatar":""},{"name":"Nanami Aiba","avatar":""},{"name":"Nana Inoue","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["拔作岛","Nukitashi - Welcome to Love Island!","ぬきたし","ぬきアニ","NukiAni","抜きゲーみたいな島に住んでる貧乳はどうすりゃいいですか？","ぬきゲーみたいなしまにすんでるわたしはどうすりゃいいですか？","NUKITASHI","Is the island Utopia or Dystopia","ぬきたし the Animation"]', 1784690324137);
