INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nukitashi-the-animation', 'Nukitashi The Animation', 'Nukitashi The Animation', 'nukitashi the animation nukitashi the animation kouhei yanagi shizuka ishigami minori ozawa rie okamoto ako koaki masumi tazawa nanami aiba nana inoue 拔作岛 nukitashi - welcome to love island! ぬきたし ぬきアニ nukiani 抜きゲーみたいな島に住んでる貧乳はどうすりゃいいですか？ ぬきゲーみたいなしまにすんでるわたしはどうすりゃいいですか？ nukitashi is the island utopia or dystopia ぬきたし the animation', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-menh-dai-than-hoang', 'Thiên Mệnh Đại Thần Hoàng', 'The Divine Emperor Of Destiny', 'https://phimimg.com/upload/vod/20250912-1/ede693609916776d4937921f5ba115e4.jpg', 'https://phimimg.com/upload/vod/20250912-1/f11ddc46cee226cbd7591b687d15916b.jpg', '<p>Thiên Mệnh Đại Thần Hoàng – câu chuyện về hành trình lột xác đầy lý thú của một nam thanh niên từ kẻ bị coi là vô dụng cho đến khi trở thành một Đại thần hoàng cai trị toàn cõi thế gian lừng lẫy. Số là một anh chàng vô cùng bình thường, chẳng có một chút gì đặc biệt hoặc khá khẩm để mà người khác để mắt đến, đã vậy cũng chẳng có nghị lực vươn lên gì cả, Tuyên Khởi chỉ mong sống một cuộc đời an nhiên nhàn hạ, nhưng số phận đã là nam chính thì mọi thứ đều có thể thay đổi đến chóng mặt. Vô tình bị cuốn vào một trận chiến sống còn của một ma thần và một nữ đế, Tuyên Khởi đã được đánh thức Thiên Tú ẩn giấu bên trong, và cũng từ đó đã lột xác, bước vào hành trình tu luyện đầy gian nan nhưng cũng rất đáng mong chờ.</p>', 'Hoàn Tất (40/40)', 40, 'hoathinh', 'completed', 10, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["天命大神皇","The Divine emperor of Destiny"]', 1784690324137);
