INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cay-sung', 'Cậy Sủng', 'His Chosen Favor', 'https://phimimg.com/upload/vod/20260101-1/e2010767a09f7163d8decdd7fbf8d031.jpg', 'https://phimimg.com/upload/vod/20260101-1/c3017a4b19c2cdf710940203c279b8a4.jpg', '<p>Sinh viên mới tốt nghiệp Lộc Trinh Nhi xuyên không trở thành phi tần tuẫn táng. Cô tình cờ phát hiện vị hoàng đế bù nhìn Tiêu Văn Cảnh hóa ra lại là đồng hương của mình. Đối mặt với vận mệnh đầy rẫy hiểm nguy đã được định sẵn, cô không chịu khuất phục, thề sẽ thay đổi vận mệnh của mình. Thế nhưng, cô lại phát hiện ra rằng Tiêu Văn Cảnh mới chính là kẻ đang đặt bút viết nên định mệnh của đời mình...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cao Dung Phương","avatar":""},{"name":"Châu Hạo Sam","avatar":""},{"name":"Vạn Tử Lân","avatar":""},{"name":"Kiều Nhất","avatar":""},{"name":"Ngưu Hân Hân","avatar":""},{"name":"Vương Tịnh Văn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Shi Chong","The Spoiled Favorite","恃宠"]', 1784690324137);
