INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cay-sung', 'Cậy Sủng', 'His Chosen Favor', 'cậy sủng his chosen favor cao dung phương châu hạo sam vạn tử lân kiều nhất ngưu hân hân vương tịnh văn shi chong the spoiled favorite 恃宠', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuyet-the-than-hoang', 'Tuyệt Thế Thần Hoàng', 'The Death-Defying Divine Emperor', 'https://phimimg.com/upload/vod/20250921-1/6dd37653bfa37b486e723edb43b6995a.jpg', 'https://phimimg.com/upload/vod/20250921-1/6af42581e2589833f2c55ab0f4b1fe36.jpg', '<p>Tuyệt Thế Thần Hoàng, một câu chuyện về cậu thiếu niên gồng gánh những trọng trách và hy vọng lớn lao của gia tộc trên đôi vai gầy gò của mình. Từng là một vị Đại Đế oai phong lẫm liệt ở kiếm trước, chỉ khinh địch và bị kẻ gian gài bẫy để rồi phải trọng sinh vào một cậu bé có tên Cảnh Vân Tiêu của Cảnh gia, giờ đây hành trình vươn lên và bảo vệ gia tộc là một điều vô cùng khó khăn, bởi lẽ những kẻ thù đến từ phủ Chiến Thần và đám sát thủ được thuê là Ám Vũ Điện vẫn không chịu buông tha cho cậu và cả Cảnh gia. Gia Gia của cậu là Cảnh Ngự Phong lại bị thương nặng trong một lần chiến đấu, nên cậu buộc phải đi tìm thuốc để cứu chữa cho ông và những người khác nữa. Sẵn có kỹ ức của vị Đại Đế của kiếp trước, Cảnh Vân Tiêu sớm lĩnh ngộ được võ công và không khó để dần trở thành một thanh niên võ nghệ cao cường, chinh phục luôn cả cô nàng xinh đẹp Mục Thi Thi.</p>', 'Tập 40', 80, 'hoathinh', 'ongoing', 10, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["绝世神皇"]', 1784690324137);
