INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('robin-hood', 'Robin Hood', 'Robin Hood', 'https://phimimg.com/upload/vod/20251102-1/a6b384ddfceaf4340ffa525021358180.jpg', 'https://phimimg.com/upload/vod/20251102-1/ee364c67f40e6015076b4d704fd75ee2.jpg', '<p>Sau cuộc xâm lược của người Norman vào nước Anh, Rob — con trai của một người tiều phu Saxon — và Marian, con gái của một lãnh chúa Norman, đem lòng yêu nhau và cùng chiến đấu vì công lý và tự do.&nbsp; Khi Rob trở thành thủ lĩnh của nhóm nghĩa sĩ ngoài vòng pháp luật, Marian lại thâm nhập vào tầng lớp quyền lực trong triều đình. Cả hai phối hợp để chống lại sự thối nát của hoàng quyền, với hy vọng mang lại hòa bình cho đất nước.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 10, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jack Patten","avatar":""},{"name":"Sean Bean","avatar":""},{"name":"Lauren McQueen","avatar":""},{"name":"Lydia Peckham","avatar":""},{"name":"Steven Waddington","avatar":""},{"name":"Marcus Fraser","avatar":""},{"name":"Angus Castle-Doughty","avatar":""},{"name":"Erica Ford","avatar":""},{"name":"Henry Rowley","avatar":""},{"name":"Connie Nielsen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Robin Hood"]', 1784690324137);
