INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ai-noi-bon-no-khong-ua-nhau', 'Ai Nói Bọn Nó Không Ưa Nhau', 'Head 2 Head', 'https://phimimg.com/upload/vod/20251104-1/3be6ee1cb82d2288ee1075fa453ec789.jpg', 'https://phimimg.com/upload/vod/20251104-1/d3373b5d047caa775fecba5f7e7bf36d.jpg', '<p>Mối oan gia hoàn toàn thay đổi khi Jerome phát hiện ra một khả năng lạ lùng hé lộ một tương lai kinh ngạc—rằng kẻ thù không đội trời chung của anh lại chính là người bạn đời (hoặc định mệnh) của mình.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Dechchart Tasilp","avatar":""},{"name":"Suvijak Piyanopharoj","avatar":""},{"name":"Patchara Silapasoonthorn","avatar":""},{"name":"Bhobdhama Hansa","avatar":""},{"name":"Chayakorn Jutamas","avatar":""},{"name":"Sujira Arunpipat","avatar":""},{"name":"Vichuda Pindum","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324137);
