INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ai-noi-bon-no-khong-ua-nhau', 'Ai Nói Bọn Nó Không Ưa Nhau', 'Head 2 Head', 'ai nói bọn nó không ưa nhau head 2 head dechchart tasilp suvijak piyanopharoj patchara silapasoonthorn bhobdhama hansa chayakorn jutamas sujira arunpipat vichuda pindum ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tooisan-wa-seishun-shitai-baka-to-smartphone-to-romance-to', 'Tooi-san wa Seishun Shitai! Baka to Smartphone to Romance to', '遠井さんは青春したい！『バカとスマホとロマンスと』', 'https://phimimg.com/upload/vod/20260112-1/f26318c7e873fd225b76775322473d5c.jpg', 'https://phimimg.com/upload/vod/20260112-1/c91e2aa385b030154caeca401b488838.jpg', '<p>Mở đầu bằng khát khao về một cuộc đời học sinh bình lặng, Akane Tooi không ngờ rằng sự xuất hiện của cậu bạn Jel đầy năng lượng sẽ biến ngày đầu nhập học của cô thành một mớ hỗn độn. Bị ép tham gia vào &quot;Câu lạc bộ Lãng mạn Thanh xuân&quot;, Tooi liên tục phải đóng vai &quot;người tỉnh táo&quot; duy nhất giữa những trò đùa tai quái của các thành viên khác, trong khi mọi khoảnh khắc xấu hổ của cô đều bị phát trực tiếp lên mạng xã hội. Sự hài hước lên đến đỉnh điểm khi những tình huống ngớ ngẩn này bỗng chốc dẫn đến một vụ án bí ẩn tại trường học, buộc Tooi phải dấn thân vào một cuộc hành trình thanh xuân vừa lãng mạn, vừa điên rồ mà cô chưa từng tưởng tượng tới.</p>', 'Full', 1, 'hoathinh', 'completed', 28, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Jel","avatar":""},{"name":"Aki Toyosaki","avatar":""},{"name":"Yuma Uchida","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Junta Terashima","avatar":""},{"name":"Manaka Iwami","avatar":""},{"name":"Takehito Koyasu","avatar":""}]', '[{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["遠井さん","Toi-san wa Seishun Shitai! \"Baka to SmaPho to Romance to\"","Toi-san Wants to Live in Her Youth! \"A Fool, a Smartphone, and Romance\"","遠井さんは青春したい！『バカとスマホとロマンスと』"]', 1784690324137);
