INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-chi-so', 'Nhân Chi Sơ', 'Light Of Dawn', 'https://phimimg.com/upload/vod/20251231-1/633ca16e1f983f647c354024393ca5a4.jpg', 'https://phimimg.com/upload/vod/20251231-1/704739aa947c806a7f724146e741ddaa.jpg', '<p>Một tai nạn bất ngờ, một bộ xương khô bị che giấu nhiều năm, đã gắn kết chặt chẽ cuộc đời của hai người trẻ tuổi lại với nhau. Để giải mã bí ẩn về thân thế của chính mình, họ đã bắt tay hợp tác, phối hợp cùng cảnh sát bóc trần những góc khuất đen tối bị chôn vùi bấy lâu của thành phố, phá giải tầng tầng lớp lớp những bí ẩn bủa vây.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Nhược Quân","avatar":""},{"name":"Mã Tư Thuần","avatar":""},{"name":"Vương Cảnh Xuân","avatar":""},{"name":"Đường Yên","avatar":""},{"name":"Dương Lặc","avatar":""},{"name":"Tát Nhật Na","avatar":""},{"name":"Nhậm Bân","avatar":""},{"name":"Vương Cúc","avatar":""},{"name":"Từ Bạch Huệ","avatar":""},{"name":"Trình Tiêu","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["血缘相对论","Blood Problem","人之初"]', 1784690324137);
