INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tua-nhu-bang-mau', 'Tựa Như Bảng Màu', 'Like A Palette', 'https://phimimg.com/upload/vod/20251201-1/7dd3a83291a3f77ea29644852927b7b3.jpg', 'https://phimimg.com/upload/vod/20251201-1/d4b3a35d9f7bc137d860c003a408c249.jpg', '<p>Cuộc sống của Jin, tân sinh viên năm nhất vốn yên bình và trọn vẹn, cho đến khi cô phát hiện &quot;đàn chị&quot; Dao, hoa khôi năm ngoái của trường dường như lại vô cớ có địch ý với mình. Ánh nhìn sắc bén, làm lòng người thấy không yên ấy làm cho mọi thứ như dừng lại. Điều khiến Jin phiền não hơn nữa là cô lại vô tình trở thành hoa khôi mới ở trường, còn đàn chị Dao thì được phân công làm cố vấn hướng dẫn cho cô. Từ đó, hai người bị số phận ràng buộc lại với nhau, không tài nào trốn thoát.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Alicha Sriprathak","avatar":""},{"name":"Sureeyares Yakares","avatar":""},{"name":"Chanyapuk Numprasop","avatar":""},{"name":"Pim Khajonvekin","avatar":""},{"name":"Khamin Manipa","avatar":""},{"name":"Taeun Pawida","avatar":""},{"name":"Ko Teerasak Puntujariya","avatar":""},{"name":"Amornrat Charoenpornrungsakul","avatar":""},{"name":"Pok Nitigorn Leearamwat","avatar":""},{"name":"Kitawat Chaodi","avatar":""},{"name":"Tang-oh Natthavat Trisomboon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["เจนจะเป็นดาวสินกำ","Like (a) Palette","เจน(จะ)เป็นดาวสินกำ"]', 1784690324137);
