INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pha-ken-2025', 'Phá Kén', 'The Truth Within', 'https://phimimg.com/upload/vod/20251230-1/01191fa784f1156d220a70a0965c22a0.jpg', 'https://phimimg.com/upload/vod/20251230-1/0c5fe54a141713f75b3518590abb5e4d.jpg', '<p>Tề Tư Triết (La Vân Hi đóng) – pháp y trẻ tuổi nhất của Cục Công an Lệ Thành, đã mất đi người bạn gái Du Phi trong một vụ tai nạn xe hơi. Tuy nhiên, anh nhận ra đằng sau vụ tai nạn ấy dường như ẩn chứa một bàn tay thao túng đầy bí ẩn. Để điều tra chân tướng, Tề Tư Triết chuyển công tác đến Cục Công an thành phố Hà Thành với tư cách pháp y hình sự, nhưng tại đây, anh bị cuốn vào hàng loạt vụ án kỳ quái và rùng rợn: những nạn nhân tử vong đã lâu bị bao phủ trong lớp lớp tơ nhện, hay những thi thể mất tích đột nhiên xuất hiện trong bình Formalin tại phòng mẫu... Trong quá trình phá án, anh đã cùng Chúc Thanh Việt (Lưu Nhã Sắt đóng) và Hàn Phong (Giang Kỳ Lâm đóng) tạo thành liên minh &#39;cường cường&#39;, bóc tách từng lớp sương mù để phá giải những kỳ án. Cùng lúc đó, vụ án ma túy &#39;Kim cương thô&#39; có liên quan đến cái chết của Du Phi năm xưa cũng dần dần lộ ra phần nổi của tảng băng chìm...</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"La Vân Hi","avatar":""},{"name":"Lưu Nhã Tắc","avatar":""},{"name":"Giang Kỳ Lâm","avatar":""},{"name":"Phí Khải Minh","avatar":""},{"name":"Lưu Hoan","avatar":""},{"name":"Lưu Thiên Tỏa","avatar":""},{"name":"Lý Gia Hào","avatar":""},{"name":"Vương Thiên Quả","avatar":""},{"name":"Vương Chí Phi","avatar":""},{"name":"Triệu Tử Kỳ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bao Jian","剥茧","The Truth Within"]', 1784690324138);
