INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-ma-ca-rong-nho-be-khong-the-hut-dung-cach-chanto-suenai-kyuuketsukichan', 'Cô Ma Cà Rồng Nhỏ Bé Không Thể Hút Đúng Cách (Chanto Suenai Kyuuketsuki-chan)', 'Li''l Miss Vampire Can''t Suck Right', 'https://phimimg.com/upload/vod/20251018-1/cce5c9ef3c45e9559a0d426cc830dba0.jpg', 'https://phimimg.com/upload/vod/20251018-1/50708fe22037e0432de5390102c0f0d8.jpg', '<p>Với vẻ ngoài lạnh lùng và bí ẩn, Ishikawa Luna – cô học sinh chuyển trường – nhanh chóng trở thành nữ sinh nổi tiếng nhất lớp. Trái lại, Ohtori lại bình thường đến mức như một nhân vật nền. Cậu thậm chí chưa từng nghĩ sẽ có cơ hội nói chuyện với Luna — cho đến khi vô tình phát hiện bí mật của cô: Luna thực ra là một ma cà rồng… nhưng lại cực kỳ vụng về trong việc hút máu!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Minami Tanaka","avatar":""},{"name":"Kensho Ono","avatar":""},{"name":"Mao Ichimichi","avatar":""},{"name":"Ikumi Hasegawa","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["不擅长吸血的吸血鬼","超萌吸血鬼不能好好吸血","Chanto Suenai Kyuuketsuki-chan","Vampires Chan Can''t Suck Properly","Chanto Suenai Kyūketsuki-chan","제대로 빨지 못하는 흡혈귀짱","Li''l Miss Vampire Can''t Suck Right","Vampire-chan Can''t Suck Properly","ちゃんと吸えない吸血鬼ちゃん"]', 1784690324138);
