INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-thi-baahubali-3', 'Sử Thi Baahubali 3', 'Bāhubali: The Epic', 'https://phimimg.com/upload/vod/20260109-1/e6aacc1113c207971f944b8dc61b10e5.jpg', 'https://phimimg.com/upload/vod/20260109-1/e447330abf39fa039fe7c6404588e5d1.jpg', '<p>Khi một đứa trẻ bí ẩn được một cặp vợ chồng bộ lạc tìm thấy bên dòng thác đổ cuồn cuộn, họ đã nuôi nấng cậu như con đẻ của mình. Lớn lên, Sivudu luôn khao khát khám phá thế giới phía sau những vách đá dựng đứng, nơi anh tìm thấy vương quốc Mahishmati cổ xưa — một vùng đất đang bị thống trị bởi tên bạo chúa tàn ác, bị bủa vây bởi các cuộc nổi loạn và gắn liền với quá khứ của chính anh. Điều bắt đầu từ một cuộc hành trình theo đuổi tình yêu đã sớm hé lộ một di sản của sự phản bội, hy sinh và hình bóng của một vị hoàng tử bị lãng quên.</p>', 'Full', 1, 'single', 'completed', 20, 2025, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Prabhas","avatar":""},{"name":"Rana Daggubati","avatar":""},{"name":"Anushka Shetty","avatar":""},{"name":"Ramya Krishnan","avatar":""},{"name":"Sathyaraj","avatar":""},{"name":"Nassar","avatar":""},{"name":"Subbaraju","avatar":""},{"name":"Tamannaah Bhatia","avatar":""},{"name":"Rohini","avatar":""},{"name":"Tanikella Bharani","avatar":""},{"name":"Prabhakar","avatar":""},{"name":"Sudeepa","avatar":""},{"name":"Adivi Sesh","avatar":""},{"name":"Ramakrishna Meka","avatar":""},{"name":"Charandeep","avatar":""},{"name":"Rakesh Varre","avatar":""},{"name":"Bharani Shankar","avatar":""},{"name":"Teja Kakumanu","avatar":""},{"name":"John Kokken","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065