INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cho-den-thoi-tan-the', 'Chợ Đen Thời Tận Thế', 'Concrete Market', 'https://phimimg.com/upload/vod/20251225-1/7d2595b9d3d57b74091c44e39fc8ceec.jpg', 'https://phimimg.com/upload/vod/20251225-1/5b1903e5f16b8aab2c1e3d34db208957.jpg', '<p>Sau đại địa chấn xóa sổ thế giới, hy vọng mong manh len lỏi giữa toà chung cư cuối cùng biến thành “chợ đen”- Nơi mạng đổi mạng và niềm tin là món đồ xa xỉ.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Jae-in","avatar":""},{"name":"Hong Kyung","avatar":""},{"name":"Jeong Man-sik","avatar":""},{"name":"Yoo Su-bin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["콘크리트 마켓","콘크리트마켓"]', 1784690324138);
