INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-di-nhan-thon-bich-du', 'Thế Giới Dị Nhân: Thôn Bích Du', 'I Am Nobody The Showdown Between Yin & Yang', 'https://phimimg.com/upload/vod/20250118-1/4990fa879367ff62073d8b9051d7b168.jpg', 'https://phimimg.com/upload/vod/20250118-1/2286bfede886fbfee1e7af59ab9265de.jpg', '<p>Trương Sở Lam bị buộc bước vào thế giới dị nhân, trải qua nhiều khó khăn, trưởng thành thành một anh hùng dị nhân mang tinh thần chính nghĩa và trách nhiệm. Anh và Phùng Bảo Bảo có một sợi dây gắn kết định mệnh, một sự kiện bất ngờ khiến cả hai rơi vào tình thế khó khăn. Trần Đóa, nhân viên đặc nhiệm của Đi Muôn Nơi sát hại cấp trên và chạy trốn, bảy nhân viên đặc nhiệm sở hữu năng lực siêu phàm, thân phận bí ẩn và hành tung khó lường, họ đã bị nghi ngờ. Sáu người còn lại phải hợp tác để hoàn thành nhiệm vụ truy bắt Trần Đóa, Phùng Bảo Bảo cũng là một trong số đó. Đồng thời, thôn Bích Du liên quan đến hành tung của Trần Đóa dần lộ diện. Trưởng thôn Mã Tiên Hồng và “tám kỹ năng đặc biệt” mà Trương Sở Lam đang điều tra có mối liên hệ mật thiết...</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 17, 2025, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Bành Dục Sướng","avatar":""},{"name":"Vương Ảnh Lộ","avatar":""},{"name":"Hầu Minh Hạo","avatar":""},{"name":"Văn Kỳ","avatar":""},{"name":"Doãn Phưởng","avatar":""},{"name":"Nghiêm Khoan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["异人","异人之下真人版","剧版一人之下","I Am Nobody 2","I Am Nobody: The Showdown Between Yin & Yang","异人之下·新篇","异人之下之决战！碧游村","异人之下之血战！唐门","စည်းအပြင်ဘက်ကလူ","I am nobody","Один из отвергнутых","Под властью нелюдей","Yi Ren Zhi Xia","The Outcast","I Am Nobody","Thế Giới Dị Nhân","异人之下"]', 1784690324138);
