INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-gioi-di-nhan-thon-bich-du', 'Thế Giới Dị Nhân: Thôn Bích Du', 'I Am Nobody The Showdown Between Yin & Yang', 'thế giới dị nhân: thôn bích du i am nobody the showdown between yin & yang bành dục sướng vương ảnh lộ hầu minh hạo văn kỳ doãn phưởng nghiêm khoan 异人 异人之下真人版 剧版一人之下 i am nobody 2 i am nobody: the showdown between yin & yang 异人之下·新篇 异人之下之决战！碧游村 异人之下之血战！唐门 စည်းအပြင်ဘက်ကလူ i am nobody один из отвергнутых под властью нелюдей yi ren zhi xia the outcast i am nobody thế giới dị nhân 异人之下', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('no-phong', 'Nộ Phong', 'Angry Wind', 'https://phimimg.com/upload/vod/20251230-1/7a6ad2c009b6139040ed33ec55549010.jpg', 'https://phimimg.com/upload/vod/20251230-1/7c2bb45bcea793c6961d8ef608398749.jpg', '<p>Sếp tổng quyền lực Trịnh Nam Phong sau khi bị phản bội bất ngờ xuyên không trở về năm 1990. Thân phận của anh bỗng chốc bị đảo lộn, trở thành quản lý vũ trường kiêm &quot;đàn em&quot; của vợ mình Chu Tri Ý. Giữa thời đại giản đơn nhưng đầy biến động ấy, anh đã vận dụng trí tuệ đi trước thời đại để xoay chuyển cục diện, biến thù thành bạn, ngăn chặn các hoạt động buôn lậu. Trong quá trình cùng vợ kề vai sát cánh, anh dần thấu hiểu trái tim mình. Hai người cùng nhau chiến đấu và viết nên một câu chuyện tình yêu &quot;song cường&quot; trở thành huyền thoại của thời đại.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chân Tử Kỳ","avatar":""},{"name":"Tôn Nghệ Nhiên","avatar":""},{"name":"Ngô Mỹ Tuệ","avatar":""},{"name":"Kim Bác","avatar":""},{"name":"Cẩn Nhan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["怒风"]', 1784690324138);
