INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khung-canh-ay-van-la-em', 'Khung Cảnh Ấy Vẫn Là Em', 'The Love Never Sets', 'https://phimimg.com/upload/vod/20251015-1/4bbea7eabfb38a1295829a60dba748e2.jpg', 'https://phimimg.com/upload/vod/20251015-1/0c8fdb93c00ab432365a6aeb8fa1f7a8.jpg', '<p>Sau khi bị Mint tổn thương, Ice bỏ học nhưng bị ép bước chân vào ngành phim người lớn. Giờ đây, cậu trở lại trường và chuẩn bị tham gia một bộ phim đồng tính, bạn diễn của cậu không ai khác chính là Saint, người mà Ice từng tuyệt giao. Khi hai người gặp lại, Ice dồn nén oán hận đối mặt với Saint, nhưng trong quá trình quay phim, họ lại cùng nhau diễn những cảnh thân mật như thể chỉ có những người gần gũi nhất mới có thể làm.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Phachara Suansri","avatar":""},{"name":"Weerapat Toemmaneerat","avatar":""},{"name":"Domon Kitmongkhon Phontad","avatar":""},{"name":"Atom Piyawat Kunrapankanrayakon","avatar":""},{"name":"Nutthawat Eamchuen","avatar":""},{"name":"Jutarat Thanaphan","avatar":""},{"name":"Nikita Parkin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["ฉากนั้น…ยังเป็นเธอ"]', 1784690324138);
