INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ai-da-giet-chim-hoa-mi', 'Ai Đã Giết Chim Hoạ Mi?', 'To Kill A Songbird', 'https://phimimg.com/upload/vod/20251230-1/4ee1429d29ad4d2b27bb3bcb02f425c1.jpg', 'https://phimimg.com/upload/vod/20251230-1/a719aa68f6890f0d585dd019192eb658.jpg', '<p>Mười ba năm sau khi gia đình gặp phải biến cố, Lý Phù Diên quay trở lại huyện Hoa Xương để báo thù cho người huynh trưởng bị chết oan. Tại đây, nàng tình cờ gặp gỡ Lục Nham Sùng, một vị tri huyện với vẻ ngoài phóng túng, vô dụng. Thế nhưng, khi thân phận thực sự và mục đích sâu xa của Lục Nham Sùng dần sáng tỏ, cả hai từ chỗ dè chừng, nghi kỵ lẫn nhau đã trở thành đồng minh, cùng nhau phá giải hàng loạt vụ án hóc búa. Cuối cùng, sự thật về &quot;Kỳ án chim họa mi&quot; từ mười ba năm trước cũng được đưa ra ánh sáng.</p>', 'Tập 20', 20, 'series', 'ongoing', 13, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Phương Hiểu Đông","avatar":""},{"name":"Triệu Tịch Tịch","avatar":""},{"name":"Đồ Hiển Trí","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shei Sha Le Hua Mie Niao","Shei Sha Le Hua Mei Niao","Who Killed the Mockingbird?","谁杀了画眉鸟"]', 1784690324138);
