INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ai-da-giet-chim-hoa-mi', 'Ai Đã Giết Chim Hoạ Mi?', 'To Kill A Songbird', 'ai đã giết chim hoạ mi? to kill a songbird phương hiểu đông triệu tịch tịch đồ hiển trí shei sha le hua mie niao shei sha le hua mei niao who killed the mockingbird? 谁杀了画眉鸟', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muteluv-sim-so-doi-menh', 'Muteluv: Sim Số Đổi Mệnh', 'MuTeLuv: Hello, Is This Luck?', 'https://phimimg.com/upload/vod/20251225-1/113c1f83c45f4c85b9fcff3c4f4cff68.jpg', 'https://phimimg.com/upload/vod/20251225-1/61921be25f78cc6c42e013d69496ab3a.jpg', '<p>Na, sinh viên y năm cuối, có năng lực nhưng luôn kém may mắn. Cô từng tin rằng chỉ cần nỗ lực là sẽ thành công, nhưng những biến cố liên tiếp xảy ra khiến cô bắt đầu nghi ngờ rằng mọi thứ thực chất đều do vận may quyết định. Đặc biệt, Na phải lòng Nine — tiền bối điển trai, thông minh và dường như ngoài tầm với. Với mong muốn xoay chuyển số phận, Na quyết định đổi sang một số điện thoại “may mắn”. Cũng từ khoảnh khắc đó, cô gặp Leemhai, và cuộc sống của Na bắt đầu đổi hướng: cô không còn là người bị Nine bỏ qua, mà dần trở thành người không thể không chú ý đến.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Ployshompoo Supasap","avatar":""},{"name":"Prariyapit Yu","avatar":""},{"name":"Thanaphon U-sinsap","avatar":""},{"name":"Panachkorn Rueksiriaree","avatar":""},{"name":"Samantha Melanie Coates","avatar":""},{"name":"Mantra Thamonchita Namkool","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324138);
