INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-vien-anh-hung-vigilantes-phan-1', 'Học Viện Anh Hùng: Vigilantes (Phần 1)', 'My Hero Academia: Vigilantes (Season 1)', 'https://phimimg.com/upload/vod/20250408-1/ec73711fdeac2325898c25cf20150139.jpg', 'https://phimimg.com/upload/vod/20260105-1/bf17a51b6acc928e51b4cead12333f6a.jpg', '<p>Học Viện Anh Hùng: Vigilantes là một góc nhìn khác về thế giới anh hùng, nơi những người hùng không giấy phép, những &quot;&quot;vệ binh&quot;&quot; đường phố, chiến đấu để bảo vệ thành phố. Koichi Haimawari, với năng lực khiêm tốn, khoác lên mình bộ trang phục lấy cảm hứng từ All Might, dấn thân vào hành trình hành hiệp bất hợp pháp. Bộ phim là cuộc phiêu lưu đầy thử thách, nơi ranh giới giữa chính nghĩa và tội ác trở nên mong manh, và những góc khuất của xã hội siêu anh hùng được phơi bày.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shuichiro Umeda","avatar":""},{"name":"Ikumi Hasegawa","avatar":""},{"name":"Yasuhiro Mamiya","avatar":""},{"name":"Kenta Miyake","avatar":""},{"name":"Junichi Suwabe","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["正义使者 -我的英雄学院之非法英雄-","My Hero Academia Vigilantes","אקדמיית הגיבורים שלי: פורעי חוק","ヴィジランテ 僕のヒーロ