INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('neu-the-gioi-la-san-khau-vay-hau-truong-o-dau', 'Nếu Thế Giới Là Sân Khấu, Vậy Hậu Trường Ở Đâu? (Dưới Ánh Đèn Sân Khấu)', 'Pray Speak What Has Happened', 'https://phimimg.com/upload/vod/20251019-1/e2c810d436e0bbf3f587143c37506fcc.jpg', 'https://phimimg.com/upload/vod/20251019-1/8a354476b2e7dd7828d40f4e8843e773.jpg', '<p>Lấy bối cảnh Shibuya năm 1984, một đạo diễn sân khấu trẻ bị đuổi khỏi đoàn kịch cũ lang thang vào nhà hát WS mờ ám. Liệu anh sẽ thắp lại ngọn lửa đam mê hay ước mơ sẽ lụi tàn?</p>', 'Full', 11, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Masaki Suda","avatar":""},{"name":"Fumi Nikaido","avatar":""},{"name":"Ryunosuke Kamiki","avatar":""},{"name":"Minami Hamabe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["もしがく","Pray Speak What Has Happened","If the world were a stage, where would the dressing room be","Moshigaku","Moshimo Kono Sekai ga Butai nara, Gakuya wa Doko ni Aru no Darou","もしもこの世が舞台なら、楽屋はどこにあるのだろう"]', 1784690324138);
