INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('neu-the-gioi-la-san-khau-vay-hau-truong-o-dau', 'Nếu Thế Giới Là Sân Khấu, Vậy Hậu Trường Ở Đâu? (Dưới Ánh Đèn Sân Khấu)', 'Pray Speak What Has Happened', 'nếu thế giới là sân khấu, vậy hậu trường ở đâu? (dưới ánh đèn sân khấu) pray speak what has happened masaki suda fumi nikaido ryunosuke kamiki minami hamabe もしがく pray speak what has happened if the world were a stage, where would the dressing room be moshigaku moshimo kono sekai ga butai nara, gakuya wa doko ni aru no darou もしもこの世が舞台なら、楽屋はどこにあるのだろう', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phieu-mieu-kiem-tien-truyen', 'Phiêu Miểu Kiếm Tiên Truyện', 'Legend Of The Misty Sword Immortal', 'https://phimimg.com/upload/vod/20250811-1/631a67d6788ab55ec6765ed359a96254.jpg', 'https://phimimg.com/upload/vod/20250811-1/8d69b8d19589c20002a676d17e5cc071.jpg', '<p>Câu chuyện được bắt đầu từ anh chàng có tên Đông Phương Thiếu Hồng, một anh chàng hiện lên trong mắt của mọi người với những sự giễu cợt hết lần này đến lần khác, nhưng thật sự thì anh ấy lại đáng mến hơn là đáng cười, bởi đôi khi chỉ thiếu may mắn một chút thôi, hoặc có chăng là may mắn quá, hoặc cũng là may mắn chưa đủ nên rơi vào những tình huống cười ra nước mắt, chứ nếu mà đỏ thì quên đi nhé. Số là mang trong mình tới hai loại thể chất của đại đạo, nhưng chính 2 thứ ấy lại bài xích lẫn nhau nên Đông Phương Thiếu Hồng không thể mở ra linh thể cho việc tu luyện bản thân. Đã đen thì chớ, cha của anh chàng lại bị bọn Tiên Minh bắt đi vì ông ấy biết được nhiều bí mật trong việc đi vào Thương Ngọc Tiên Phủ, nơi mà ẩn chứa rất nhiều điều bí mật khác mà bao người vẫn luôn tò mò. Chưa hết, bọn Tiên Minh và những gia tộc khác lại đang cố chèn ép để đưa gia tộc của anh đến mức diệt vong. Uất hận vì tình cảnh ngặt nghèo vậy, Thiếu Hồng đã dùng máu của mình để tạo nên sức mạnh từ Tiên Nguyên Đạo Thạch, đánh lui được bọn Tiên Minh và các gia tộc khác, bảo vệ cho gia tộc mình tạm thời an toàn, nhưng cha của anh thì đã bị bọn khốn Tiên Minh mang đi rồi, buộc anh phải tìm cách để cứu thoát ông ấy. Một vị cố nhân của ông ấy là Quý Dận đã cứu giúp anh, đưa anh đến một miếu tông của ông để tu luyện, phát triển sức mạnh, bởi đó là cách duy nhất anh có thể làm để cứu cha mình.</p>', 'Hoàn Tất (40/40)', 40, 'hoathinh', 'completed', 10, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Piao Miao Jian Xian Zhuan","Piaomiao Jianxian Zhuan","縹緲劍仙傳","縹緲劒僊傳","Legend of the Ethereal Sword-Immortal","缥缈剑仙传"]', 1784690324138);
