INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-choi-khac-kim', 'Người Chơi Khắc Kim', 'Wealth And Wonder', 'https://phimimg.com/upload/vod/20250722-1/068f3ab12c33dd4e9f4a5c877eda0b72.jpg', 'https://phimimg.com/upload/vod/20250722-1/552eb43b6bf886499a2437b515abbb36.jpg', '<p>Trong thế giới tương lai, trò chơi thực tế ảo &quot;Kỷ Nguyên&quot; do Tập đoàn Sở thị phát triển đã thu hút sự chú ý của toàn thế giới nhờ trải nghiệm nhập vai hoàn hảo. Thế nhưng ngay trước ngày trò chơi chính thức ra mắt, cặp vợ chồng nhà phát triển, cha mẹ của thiếu gia Sở Dịch, lại mất tích một cách bí ẩn. Để truy tìm tung tích cha mẹ, Sở Dịch dưới sự chỉ dẫn của trí tuệ nhân tạo hình người tên Chaos, đã &quot;nạp&quot; 30 tỷ để bước vào trò chơi và bắt đầu hành trình thăng cấp, mạo hiểm. Trong quá trình đó, cậu dần tập hợp được một nhóm bạn đồng hành, cùng chiến đấu, cùng khám phá. Trải qua nhiều sóng gió, họ phát hiện ra sự mất tích của cha mẹ có liên quan đến một tổ chức thần bí mang tên Ảo Thế. Để tìm lại cha mẹ, chống lại tổ chức Ảo Thế và “giải cứu” thế giới Kỷ Nguyên, Sở Dịch không ngừng tung ra những màn &quot;nạp tiền phá game&quot; vừa buồn cười vừa bất ngờ, bắt đầu hành trình giả heo ăn hổ của một thần tài bá đạo.</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 8, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Yajing Tang","avatar":""},{"name":"Huang Ying","avatar":""},{"name":"Danni Pan","avatar":""},{"name":"Liang Dawei","avatar":""},{"name":"Kaiyin Sun","avatar":""},{"name":"Chengyuan Li","avatar":""},{"name":"伍凯立","avatar":""},{"name":"Xiyue Chen","avatar":""},{"name":"Zhang Pei","avatar":""},{"name":"Xie Ying","avatar":""},{"name":"KIYO","avatar":""},{"name":"Sang Yuze","avatar":""},{"name":"Chaoran Yang","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["氪金玩家","Ke Jin Wanjia","Wealth and Wonder","The Rich Player","Rich Player","The Richest Player","Waelth and Wonder","克金玩家"]', 1784690324138);
