INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-choi-khac-kim', 'Người Chơi Khắc Kim', 'Wealth And Wonder', 'người chơi khắc kim wealth and wonder yajing tang huang ying danni pan liang dawei kaiyin sun chengyuan li 伍凯立 xiyue chen zhang pei xie ying kiyo sang yuze chaoran yang 氪金玩家 ke jin wanjia wealth and wonder the rich player rich player the richest player waelth and wonder 克金玩家', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-kiem-vuong-toa', 'Vạn Kiếm Vương Tọa', 'Throne Of The Sword Master', 'https://phimimg.com/upload/vod/20250819-1/39b4d454ce2239e60e84bfa83aef627d.jpg', 'https://phimimg.com/upload/vod/20250819-1/67b65c67ad6d6bb74b1eb875ff36e094.jpg', '<p>Ở vương triều Khương Á rộng lớn, văn hóa kiếm đạo đã được lưu truyền hàng vạn năm, người dân đều lấy việc tu luyện kiếm đạo làm niềm vinh dự. Thế nhưng những người có thể tu luyện thành công đến cảnh giới đỉnh cao “Kiếm Thần cảnh” lại vô cùng hiếm hoi. Mười mấy năm trước, Vô Cực Kiếm Thần, lúc bấy giờ đang ở đỉnh cao danh vọng, thì bị Trường Sinh Kiếm Thần hãm hại, trọng thương và từ đó ở ẩn nơi núi rừng, không màng thế sự. Nay, đệ tử duy nhất của ông là Triển Nhất Bạch đã trưởng thành và đến thời điểm thực hiện lời hứa với sư phụ để ra ngoài rèn luyện. Trước khi khởi hành, để tăng khả năng tự vệ cho Nhất Bạch, Vô Cực Kiếm Thần tặng cho cậu bội kiếm của ông, đồng thời căn dặn phải nhanh chóng tu luyện lên Kiếm Thần cảnh.</p>', 'Hoàn Tất (40/40)', 40, 'hoathinh', 'completed', 6, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"来磊","avatar":""},{"name":"赵文慧","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["萬劍王座","Throne of Ten Thousand Swords","Throne of the Sword Master","万剑王座"]', 1784690324138);
