INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ban-nhac-tinh', 'Những Bản Nhạc Tình', 'Love: Track', 'https://phimimg.com/upload/vod/20251220-1/716a48f3dec22e7d0d1d7f1f5b42d171.jpg', 'https://phimimg.com/upload/vod/20251220-1/8369375682e9a38d51df2448315aeb4d.jpg', '<p>Một tuyển tập phim lãng mạn gồm 10 câu chuyện tình yêu khác nhau, mỗi câu chuyện mang sắc thái và sức hút riêng. Phim quy tụ dàn diễn viên đông đảo.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yang Dae-hyeok","avatar":""},{"name":"Lee Dong-hwi","avatar":""},{"name":"Bang Hyo-rin","avatar":""},{"name":"Han Ji-hyeon","avatar":""},{"name":"Ong Seong-wu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["러브: 트랙"]', 1784690324138);
