INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-quan-ly-cua-toi-oi', 'Người Quản Lý của Tôi Ơi', 'Will You Be My Manager?', 'https://phimimg.com/upload/vod/20251222-1/86f5a33442071cfeaa2960c7080caa88.jpg', 'https://phimimg.com/upload/vod/20251222-1/14ec019b823dcdce1b293d13fd5f2570.jpg', '<p>Một nữ sinh tại học viện nghệ thuật hàng đầu đang nỗ lực theo đuổi ước mơ trở thành quản lý nghệ sĩ nổi tiếng. Liệu đối thủ của cô có phát hiện ra bí mật trong quá khứ và khiến mọi kế hoạch của cô đổ bể?</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kanon","avatar":""},{"name":"Ahn Jun-won","avatar":""},{"name":"Yoon Do-jin","avatar":""},{"name":"Yang Jun-beom","avatar":""},{"name":"Nam Min-su","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["되어줄래? 나의 매니저"]', 1784690324138);
