INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hoang-parttime-la-toi', 'Nữ Hoàng Part-time Là Tôi', 'Money Honey Brainy', 'https://phimimg.com/upload/vod/20251226-1/c1e3b49f34c12c28b2f6f1b9ae8a41dd.jpg', 'https://phimimg.com/upload/vod/20251226-1/773eea93b97e00596622ef7e8a4ee50b.jpg', '<p>&quot;Nữ hoàng làm thêm&quot; Tân Đồng là cô nàng không từ chối bất cứ công việc làm thêm nào. Một lần, cô đã đồng ý với cô bạn chí cốt, giúp bạn mình đi xem mắt để phá hỏng buổi gặp gỡ đó. Thế nhưng, cô chẳng thể ngờ đối tượng xem mắt lại chính là Văn Bùi An, người thừa kế của tập đoàn Tứ Hải. Bị cha mẹ thúc ép kết hôn, Văn Bùi An thuận nước đẩy thuyền thuê luôn Tân Đồng làm người yêu hợp đồng của anh. Từ đây, cả hai phải bắt tay đấu trí đấu dũng với &quot;đặc vụ giám sát tình yêu&quot; do bố Văn Bùi An phái đến và bắt đầu chuỗi ngày sống chung dở khóc dở cười đầy hài hước.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tôn Nghệ Vũ","avatar":""},{"name":"Trình Vũ Phong","avatar":""},{"name":"Châu Nghi","avatar":""},{"name":"Thiệu Hoằng Phi","avatar":""},{"name":"Vương Tử Viên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wo Jian Zhi Nv Wang","Part Time Queen","Money Honey Brainy","我，兼职女王"]', 1784690324138);
