INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trung-gian-gioi', 'Trung Gian Giới', 'Run To The West', 'https://phimimg.com/upload/vod/20260105-1/5a072eda7c5097f3d9fca9a54d9c0009.jpg', 'https://phimimg.com/upload/vod/20260105-1/84f7090f3868c1f80674f96802aa8aec.jpg', '<p>Bộ phim kể về một nhóm người vô tình lạc vào chiều không gian bí ẩn nằm giữa ranh giới sinh tử. Để tìm đường trở về thế giới thực, họ buộc phải dấn thân vào một cuộc rượt đuổi nghẹt thở về phía Tây, đối mặt với những thực thể siêu nhiên và những cạm bẫy chết người. Với sự dẫn dắt của Kim Kang-woo và Kwon Yu-ri, hành trình này không chỉ là cuộc chiến sinh tồn mà còn là sự đối diện với những góc tối trong chính tâm hồn mỗi người.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"Byun Yo-han","avatar":""},{"name":"Kim Kang-woo","avatar":""},{"name":"Bang Hyo-rin","avatar":""},{"name":"Lim Hyung-jun","avatar":""},{"name":"Yang Se-jong","avatar":""},{"name":"Lee Mu-saeng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["중간계"]', 1784690324138);
