INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-bac-si-dang-yeu-nay-la-cua-toi', 'Chàng Bác Sĩ Đáng Yêu Này Là Của Tôi', 'Doctor''s Mine', 'https://phimimg.com/upload/vod/20250731-1/dbbc5f5d8504c4a715a29be4b8372150.jpg', 'https://phimimg.com/upload/vod/20250731-1/21a4f6f325d2a6c87ee52ad927044894.jpg', '<p>Phim xoay quanh ba cặp sinh viên từ hai trường khác nhau — ngành Y và ngành Kỹ thuật — mỗi người mang trong mình những cảm xúc riêng vốn được che giấu lâu nay. Họ phải đối mặt với tình yêu giả tạo, thân mật tình cờ, và những rung động sâu kín khi tìm cách vượt qua ranh giới giữa các khoa để kết nối thật sự. Suốt hành trình đó, họ sẽ trải qua những va chạm, hiểu lầm, đồng thời học cách chấp nhận bản thân và người khác — tình cảm không chỉ đơn thuần là cảm xúc mà còn là thử thách để trưởng thành</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Lee Long Shi","avatar":""},{"name":"Arm Chaiyapat Jampasin","avatar":""},{"name":"Mon Taechin Phaisanwan","avatar":""},{"name":"Varayu Pusomjitsakul","avatar":""},{"name":"Top Sumethee Mettaworakun","avatar":""},{"name":"Thanawat Sutthijaroen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["甜心醫生","Mo Narak Khon Ni Pen Khong Phom","醫科戀愛實習","This Cute Doctor Is Mine","หมอน่ารักคนนี้เป็นของผม"]', 1784690324138);
