INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tau-tinh-yeu', 'Chuyến Tàu Tình Yêu', 'Roller Coaster', 'https://phimimg.com/upload/vod/20250912-1/fb1b7ec20a6934bd186b3a2ec0757194.jpg', 'https://phimimg.com/upload/vod/20250912-1/f53c4d9dfbc402cdafae29d08290c1d4.jpg', '<p>Pure từng yêu sâu đậm Air, nhưng Air buộc phải kết hôn vì gia đình, nên hai người chia tay. Pure vẫn không thể quên được tình cũ và luôn giữ liên lạc với Air. Một năm sau, tình cờ Pure gặp lại Air trong quán bar, và cũng gặp được Loft, em chồng của Air. Loft yêu Pure ngay từ cái nhìn đầu tiên, chủ động tấn công bất chấp mối quan hệ phức tạp. Từ đó, Pure rơi vào vòng xoáy giữa người cũ và người mới, đau đầu vì bất kỳ sự lựa chọn nào cũng sẽ khiến một người tổn thương.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Aom Pundao Panyabaramee","avatar":""},{"name":"Shelly Phetsai Chanruenang","avatar":""},{"name":"Naerunchara Lertprasert","avatar":""},{"name":"Kimmy Thitisan Goodburn","avatar":""},{"name":"Kanta Danao","avatar":""},{"name":"Vacharakiat Boonphakdee","avatar":""},{"name":"Natsinee Charoensitthisap","avatar":""},{"name":"Duangjai Hiransri","avatar":""},{"name":"Dusit Witooteerasan","avatar":""},{"name":"Rachanee Siralert","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Roller Coaster The Series","รักขบวนนี้หัวใจเกือบวาย"]', 1784690324138);
