INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vien-tham-my-cuu-kim-son', 'Viện Thẩm Mỹ Cựu Kim Sơn', 'The Good, The Bad, And The Ugly', 'https://phimimg.com/upload/vod/20251020-1/c325a01e48ded66605c155d249fc0601.jpg', 'https://phimimg.com/upload/vod/20251020-1/1630006980914b8597077f2482330d59.jpg', '<p>Bộ phim xoay quanh ba gia đình điều hành tiệm làm đẹp, quán ăn sáng và xưởng đồ chơi. Trong ba gia đình ấy, có người bị hãm hại dẫn đến mất việc, có người luôn bị xem nhẹ và coi thường, và cũng có kẻ muốn lợi dụng người khác để hạ bệ người anh/chị cùng cha khác mẹ. Trên con đường trả thù đầy toan tính của mỗi người, dần hé lộ mối ràng buộc giữa hai thế hệ, để rồi những ân oán của đời trước lại trở thành nguyên nhân gây tổn thương cho tình cảm của thế hệ sau.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Lưu Phẩm Ngôn","avatar":""},{"name":"Liên Thần Tường","avatar":""},{"name":"Chương Quảng Trần","avatar":""},{"name":"Phương Chí Hữu","avatar":""},{"name":"Dương Minh Uy","avatar":""},{"name":"Dương Thanh","avatar":""},{"name":"Kiểm Trường","avatar":""},{"name":"Trần Tiêu Huyền","avatar":""},{"name":"Tưởng Vĩ Văn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["舊金山美容院"]', 1784690324138);
