INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thi-truong-kingstown-phan-4', 'Thị Trưởng Kingstown (Phần 4)', 'Mayor Of Kingstown (Season 4)', 'thị trưởng kingstown (phần 4) mayor of kingstown (season 4) jeremy renner hugh dillon tobi bamtefa taylor handley derek webster hamish allan-headley edie falco lennie james laura benanti necar zadegan nishi munshi o dono de kingstown el jefe de kingstown mayor of kingstown', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lieu-trai-lan-nhuoc-tu', 'Liêu Trai Lan Nhược Tự', 'Curious Tales Of A Temple', 'https://phimimg.com/upload/vod/20251023-1/95f86b386d5c2213fa61ff9fe3e37af7.jpg', 'https://phimimg.com/upload/vod/20251023-1/ea6c7ec67aadcde44fdf6575436baaa2.jpg', '<p>Một thư sinh mê hóng hớt lên chùa gặp 2 con yêu quái nhiều chuyện và bắt đầu câu chuyện đầy quỷ dị này. Thư sinh Bồ Tùng Linh qua đêm tại Lan Nhược Tự, bị hai yêu quái là cóc và rùa bắt xuống đáy giếng cổ để phán xét hay dở của các câu chuyện nơi đây. Giữa một ngôi chùa, một cái giếng và một gốc cây, các thiên truyện kinh điển như Đạo Sĩ Núi Lao, Công Chúa Liên Hoa, Nhiếp Tiểu Thiến, Họa Bì, Con Gái Họ Lỗ… dần dần hiện ra, vượt qua thời gian không gian. Sáu phong cách kể chuyện đan xen tạo nên một bữa kể lại những câu chuyện đầy kỳ quái, cảm động về duyên phận.&nbsp;</p>', 'Full', 1, 'single', 'completed', 10, 2025, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Lô Lực Phong","avatar":""},{"name":"Lâm Cường","avatar":""},{"name":"Trương Hách","avatar":""},{"name":"Trần Tử Bình","avatar":""},{"name":"Phó Bác Hàm","avatar":""},{"name":"Cam Ly","avatar":""},{"name":"Lưu Hiệu Vũ","avatar":""},{"name":"Cốc Giang Sơn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["聊斋志异","Strange Tales from a Chinese Studio","เรื่องพิศวง ตำนานลึกลับ","聊斋：兰若寺"]', 1784690324138);
