INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lieu-trai-lan-nhuoc-tu', 'Liêu Trai Lan Nhược Tự', 'Curious Tales Of A Temple', 'liêu trai lan nhược tự curious tales of a temple lô lực phong lâm cường trương hách trần tử bình phó bác hàm cam ly lưu hiệu vũ cốc giang sơn 聊斋志异 strange tales from a chinese studio เรื่องพิศวง ตำนานลึกลับ 聊斋：兰若寺', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tren-dinh-dong-son', 'Trên Đỉnh Đông Sơn', 'Holy Light', 'https://phimimg.com/upload/vod/20260104-1/cce1c4ece1890ba8728cd50a535b7ab1.jpg', 'https://phimimg.com/upload/vod/20260104-1/2ea6528cd33e782ab821cf982cfa9c03.jpg', '<p>Nội dung chính của bộ phim xoay quanh hành trình gặp gỡ, thấu hiểu tại vùng đất Tây Tạng rồi nảy sinh tình yêu tại Trường Công học Tây Tạng giữa chàng thư sinh Di Cao Viễn và thiếu nữ thuần khiết người Tây Tạng Cách Tang Mai Đóa. Bộ phim khắc họa quá trình hình thành và phát triển của Trường Công học Tây Tạng - ngôi trường đại học đầu tiên do Đảng Cộng sản Trung Quốc thành lập tại Tây Tạng. Qua đó, bộ phim tái hiện những biến chuyển to lớn mà công cuộc giải phóng mang lại cho Tây Tạng và người dân nơi đây, đồng thời khắc họa quá trình phát triển đầy gian nan nhưng kiên định của một Tây Tạng mới.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đinh Nhiên","avatar":""},{"name":"Lý Cảnh Nghệ","avatar":""},{"name":"Đổng Thiên Vũ","avatar":""},{"name":"Trang Đạt Phi","avatar":""},{"name":"Đỗ Mạnh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Dong Shan Ding Shang","On the Top of Dongshan Mountain","东山顶上"]', 1784690324138);
