INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ca-do-ca-xanh-phan-1', 'Cá Đỏ Cá Xanh (Phần 1)', 'Dr. Seuss''s Red Fish Blue Fish (Season 1)', 'https://phimimg.com/upload/vod/20250909-1/5a3112176acc9ac90d8dd31e9ec6a1bb.jpg', 'https://phimimg.com/upload/vod/20250909-1/5a7e3aef4f21e6cff19d36465e85f772.jpg', '<p>Một con cá, hai con cá, gặp ngay Cá Đỏ và Cá Xanh! Từ đây sang đó – từ đó về đây – đôi bạn này tìm thấy những cặp đối nghĩa ở khắp mọi nơi!</p>', 'Hoàn Tất (5/5)', 5, 'hoathinh', 'completed', 18, 2025, 'Vietsub + Lồng Tiếng', 'FHD', 'Canada', 0, '[{"name":"Brian Drummond","avatar":""},{"name":"Andrea Libman","avatar":""},{"name":"Naomi Tan","avatar":""}]', '[{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Dr. Seuss''s Red Fish, Blue Fish"]', 1784690324138);
