INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('100-dem-cua-hero', '100 Đêm Của Hero', '100 Nights of Hero', 'https://phimimg.com/upload/vod/20260104-1/41b06fe2835d2a68af401b750790b24c.jpg', 'https://phimimg.com/upload/vod/20260104-1/953c798c343898392274b4ef73f5544f.jpg', '<p>Khi một vị khách quyến rũ bất ngờ ghé thăm tòa lâu đài hẻo lánh, mối quan hệ mong manh giữa người chồng thờ ơ, cô dâu ngây thơ Cherry và người hầu trung thành Hero bị xáo trộn, đẩy tất cả vào vòng xoáy hỗn loạn.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Emma Corrin","avatar":""},{"name":"Nicholas Galitzine","avatar":""},{"name":"Maika Monroe","avatar":""},{"name":"Amir El-Masry","avatar":""},{"name":"Charli xcx","avatar":""},{"name":"Richard E. Grant","avatar":""},{"name":"Felicity Jones","avatar":""},{"name":"Safia Oakley-Green","avatar":""},{"name":"Josh Cowdery","avatar":""},{"name":"Markella Kavenagh","avatar":""},{"name":"Clare Perkins","avatar":""},{"name":"Christopher Fairbank","avatar":""},{"name":"Bijan Daneshmand","avatar":""},{"name":"Michael Keogh","avatar":""},{"name":"Jordan Coulson","avatar":""},{"name":"Olivia D","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The One Hundred Nights of Hero","Сто ночей героя","Qəhrəmanın 100 Günü","As 100 noites de Hero","100 Nights of Hero"]', 1784690324138);
