INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-dinh-coc-vi', 'Nam Đình Cốc Vi', 'The Last Dynasty (The Chosen One)', 'https://phimimg.com/upload/vod/20251001-1/c6cde532e4fd1a951a1c6bbbe22ea1a2.jpg', 'https://phimimg.com/upload/vod/20251001-1/0ae28cf36937e4156c0104cc1aecf2ca.jpg', '<p>Một bộ phim hoạt hình trinh thám bí ẩn mang đậm sắc màu dân gian Trung Hoa và phong vị Quảng Đông, vừa &quot;kinh&quot; vừa &quot;hỉ&quot;, khiến người xem không thể dừng lại! Cao Ảnh, chàng tân sinh viên đại học vô tình ở trọ nhầm tại khách sạn Nam Đình, từ đó liên tiếp gặp phải những sự việc kỳ quái. Không những không thể rời khỏi khách sạn để đi nhập học, lại còn chạm trán với Vương gia Dận Đình bí ẩn đã sống hơn ba trăm năm… Cao Ảnh không chỉ phải đối phó với biết bao tai họa do Thái Tuế mang đến, mà còn phải đối diện với nỗi sợ trong chính tâm hồn mình, để rồi đứng lên chiến đấu, bảo vệ những người quan trọng!</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 13, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Gu Wei Nan Ting","The Last Dynasty","谷围南亭"]', 1784690324138);
