INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-an-24-ke', 'Trường An 24 Kế', 'The Vendetta Of An', 'https://phimimg.com/upload/vod/20251213-1/a9783786f068e2a83bfef1a6f9a3b989.jpg', 'https://phimimg.com/upload/vod/20251213-1/61804fdb735c8069a7d9fdc05b1140f7.jpg', '<p>Bộ phim kể về Tạ Hoài An, con trai của Lưu Tử Ôn – người sáng lập ra Hổ Bôn Vệ. Mang trong mình mối thù diệt môn, chàng ẩn nhẫn suốt hơn mười năm để mưu tính, cuối cùng trở lại Trường An với thân phận chủ bạ nha môn Hoài Nam. Giữa những tranh chấp giang hồ và âm mưu chốn triều đình, Tạ Hoài An thận trọng từng bước, mở ra một cuộc đấu trí và hành trình bảo vệ giang sơn đầy kịch tính.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 13, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Thành Nghị","avatar":""},{"name":"Lưu Nghệ Quân","avatar":""},{"name":"Vương Cảnh Tùng","avatar":""},{"name":"Châu Kì","avatar":""},{"name":"Đổng Mộng Thực","avatar":""},{"name":"Từ Lộ","avatar":""},{"name":"Nghi Đại Hồng","avatar":""},{"name":"Trương Hán Nhu","avatar":""},{"name":"Dương Túc Tân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Os 24 Estratagemas de Chang''an","Chang An Er Shi Si Ji","長安二十四計","The 24 Strategies of Chang''an","장안이십사계","The Vendetta of An","长安二十四计"]', 1784690324138);
