INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('truong-an-24-ke', 'Trường An 24 Kế', 'The Vendetta Of An', 'trường an 24 kế the vendetta of an thành nghị lưu nghệ quân vương cảnh tùng châu kì đổng mộng thực từ lộ nghi đại hồng trương hán nhu dương túc tân os 24 estratagemas de chang''an chang an er shi si ji 長安二十四計 the 24 strategies of chang''an 장안이십사계 the vendetta of an 长安二十四计', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chua-dien-ha-co-tri', 'Công Chúa Điện Hạ Cơ Trí', 'The Royal Highness Of The Princess', 'https://phimimg.com/upload/vod/20251226-1/8a96980f19ebd18ca84a937aaa8048d7.jpg', 'https://phimimg.com/upload/vod/20251226-1/4485346fa7c9b2e7780ff590dbf189ea.jpg', '<p>An Nhiên – một diễn viên vô danh – trong lúc đi thăm đoàn phim đã tình cờ xuyên không vào chính kịch bản mình đang đóng. Để tìm cách quay trở về thời hiện đại, &quot;thánh diễn&quot; An Nhiên quyết định giả ngây ngô để đánh lừa kẻ địch. Thế nhưng, trên hành trình giải cứu những nhân vật phụ xấu số, cô lại vô tình bị cuốn vào kế hoạch trả thù của Vũ Văn Duệ. Cặp đối tác bất đắc dĩ này trông thì có vẻ là tổ hợp giữa một nữ tử trung thành, dẻo miệng và một chàng Thủ phụ thâm sâu khó lường, nhưng thực chất, cả hai đều đang âm thầm có những tính toán riêng. Cùng lúc đó, một âm mưu nhằm hủy diệt nước Vân Di cũng đang lặng lẽ bắt đầu...</p>', 'Tập 26', 26, 'series', 'ongoing', 13, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hàn Mộc Ngôn","avatar":""},{"name":"Dương Đình Đông","avatar":""},{"name":"Vương Ngạn Hâm","avatar":""},{"name":"Bộ Tử Dĩnh","avatar":""},{"name":"Trương Thuỵ","avatar":""},{"name":"Phòng Tịnh Hàm","avatar":""},{"name":"Lý Thị Nghiêu","avatar":""},{"name":"Lý Giai Hân","avatar":""},{"name":"Doãn Nhất Bác","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["The Strange Princess","The Witty Princess","The Royal Highness of the Princess","机智的公主殿下"]', 1784690324138);
