INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vong-nhi-cup-be', 'Vong Nhi Cúp Bế', 'Dollhouse', 'https://phimimg.com/upload/vod/20260103-1/1c6cce7105d19fd617b039f40dcc9259.jpg', 'https://phimimg.com/upload/vod/20260103-1/d353c0c84231ca7e66a35d1e3f49eead.jpg', '<p>Suzuki Yoshie bỗng tìm thấy một con búp bê giống với đứa con gái đã mất của mình, vì quá đau buồn mà vợ chồng cô đã chăm sóc con búp bê trong suốt nhiều năm. Sự việc kinh hoàng xảy ra khi cô phát hiện mình đã có thai, và dường như con búp bê của cô không muốn chia sẻ tình thương với “đứa em” sơ sinh đó.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 1, '[{"name":"Masami Nagasawa","avatar":""},{"name":"Koji Seto","avatar":""},{"name":"Tetsushi Tanaka","avatar":""},{"name":"Aoi Ikemura","avatar":""},{"name":"Naomi Nishida","avatar":""},{"name":"Hiroki Konno","avatar":""},{"name":"Totoka Honda","avatar":""},{"name":"Tōru Shinagawa","avatar":""},{"name":"Ken Yasuda","avatar":""},{"name":"Jun Fubuki","avatar":""},{"name":"Hirotaro Honda","avatar":""},{"name":"Kintarô Hara","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Dooruhausu","娃鬼人形","詭娃娃","Dollhouse: Muñeca Maldita","Dollhouse: A Boneca da Casa","Dollhouse","Dollhouse: Muñeca maldita","ドールハウス"]', 1784690324138);
