INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tiem-do-co-a-xa-2025', 'Tiệm Đồ Cổ Á Xá', 'The Company', 'https://phimimg.com/upload/vod/20251219-1/fa9fcf1f6819b4be73ef717865e5092d.jpg', 'https://phimimg.com/upload/vod/20251219-1/9428ead5a78ae4fa80839ebe2c9dbb6f.jpg', '<p>Ông chủ tiệm đồ cổ Tất Chi Hòa đến từ tương lai và bác sĩ thú y sống ở thời hiện tại Tô Bắc Lục trở thành cộng sự, cùng nhau du hành xuyên thời gian để tìm lại những cổ vật bị thất lạc. Phong tục, tập quán của các thời kỳ khác nhau cùng những thăng trầm, biến động của số phận con người được hai người khéo léo kết nối và kể lại một cách chậm rãi, tinh tế. Trong hành trình ấy, họ đã nuôi dưỡng được một tình bạn đẹp vượt qua cả không gian và thời gian. Cuối cùng, hai người đều có được sự lạc quan để đối diện với cuộc đời của chính mình.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cao Vỹ Quang","avatar":""},{"name":"Lương Tĩnh Khang","avatar":""},{"name":"Trương Miểu Di","avatar":""},{"name":"Mao Hiểu Tuệ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Ya She","Yashe","哑舍网剧电视剧","哑舍网络剧","Yǎ Shè","Dumb House","Silent House","Silence House","Mute House","The Company","哑舍"]', 1784690324138);
