INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xuan-tieu-2025', 'Xuân Tiêu', 'Spring Night', 'https://phimimg.com/upload/vod/20251223-1/1b7acb0bab7c93623c04b924f60a50fb.jpg', 'https://phimimg.com/upload/vod/20251223-1/995b47067410e07ea9f9305ef53847ab.jpg', '<p>Mạch Điềm – hậu duệ còn sót lại của Thẩm gia – trong một lần tình cờ đã cứu sống Thái tử Cẩn Xuyên khi anh đang bị trọng thương và mất trí nhớ. Để trốn tránh thánh chỉ hoàng gia, cô đã mượn cơ hội này để kết hôn giả với anh. Không ngờ rằng, một tờ hôn ước giao kèo lại nảy sinh tình cảm chân thật theo mô-típ &quot;cưới trước yêu sau&quot;. Cuối cùng, hai người đã cùng nhau hợp sức vạch trần bức màn đen tối của vụ đại án gian lận thi cử, đồng thời giải oan và lấy lại danh dự cho Thẩm gia.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Trạch","avatar":""},{"name":"Mã Thu Nguyên","avatar":""},{"name":"Bao Hàm","avatar":""},{"name":"Hàn Cửu Nặc","avatar":""},{"name":"Tông Phong Nham","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["春宵"]', 1784690324138);
