INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giac-quan-thu-sau-vong-quanh-thanh-pho-phan-2', 'Giác Quan Thứ Sáu: Vòng Quanh Thành Phố (Phần 2)', 'Sixth Sense: City Tour (Season 2)', 'https://phimimg.com/upload/vod/20251101-1/877ff87f6e8b4c6e1b594deea206107d.jpg', 'https://phimimg.com/upload/vod/20251101-1/30cd6c8fa3f9a6c239d9d3e72b52914b.jpg', '<p>Giác Quan Thứ Sáu tiếp tục chuyến khám phá vòng quanh thành phố, truy tìm sự giả mạo giữa những địa điểm hot nhất, những xu hướng thịnh hành nhất. MC quốc dân Yoo Jae Suk tái hợp bạn diễn kỳ cựu Ji Suk Jin, cùng tài tử Go Kyung Pyo và Mimi (Oh My Girl) khuấy động không khí thành phố trong tiết trời mùa thu mát mẻ.</p>', 'Hoàn Tất (10/10)', 10, 'tvshows', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yoo Jae-suk","avatar":""},{"name":"Go Kyung-pyo","avatar":""},{"name":"Mimi","avatar":""},{"name":"Song Eun-yi","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["第六感·城市观光","식스센스: 시티투어"]', 1784690324138);
