INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('giac-quan-thu-sau-vong-quanh-thanh-pho-phan-2', 'Giác Quan Thứ Sáu: Vòng Quanh Thành Phố (Phần 2)', 'Sixth Sense: City Tour (Season 2)', 'giác quan thứ sáu: vòng quanh thành phố (phần 2) sixth sense: city tour (season 2) yoo jae-suk go kyung-pyo mimi song eun-yi 第六感·城市观光 식스센스: 시티투어', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-sang-thien-thu-2025', 'Ánh Sáng Thiên Thư', 'Treasure At Dawn', 'https://phimimg.com/upload/vod/20251201-1/303948e69098b244bb088c716d0f4cec.jpg', 'https://phimimg.com/upload/vod/20251201-1/87a707b42360a28ef215c6348b719770.jpg', '<p>Chàng trai trẻ Hoa Phù Sinh không màng chuyện đời, chỉ đam mê y học. Phương pháp hành nghề độc đáo khiến dân chúng trong thành vừa yêu mến vừa sợ hãi. Sau cái chết của Bách Y, Hoa Phù Sinh bị hiểu nhầm là hung thủ. Những manh mối trong bức di thư mà sư phụ để lại dường như hướng về bức &quot;Thiên Thư&quot; thần bí. Tình cờ, Văn Giác, con gái thành chủ Lương Châu, và Cố Thiên, người kế thừa tạp kỹ, cũng bị cuốn vào. Cả ba cùng nhau đến Lương Châu để điều tra. Văn Giác mượn thế lực của thành chủ giúp Phù Sinh mở một y quán ở Lương Châu, còn Cố Thiên lanh lợi hỗ trợ thu thập thông tin. Hoa Phù Sinh ở Lương Châu chữa bệnh cho dân nghèo đồng thời tìm kiếm sự thật. Tuy nhiên, những chuyện kỳ bí liên tiếp xảy ra, khiến câu đố càng trở nên phức tạp. Hoa Phù Sinh không hề hay biết rằng sự xuất hiện của mình đã âm thầm tạo ra một đợt sóng ngầm ở Lương Châu.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 14, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Hồng Nghị","avatar":""},{"name":"Tô Hiểu Đồng","avatar":""},{"name":"Dư Thành Ân","avatar":""},{"name":"Vương Tử Huyên","avatar":""},{"name":"Vu Tưởng","avatar":""},{"name":"Bành Dã Kỳ","avatar":""},{"name":"Tống Gia Đằng","avatar":""},{"name":"Đại Diễm Ni","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Tian Shu Li Ming","천서여명 : 괴짜 의원 수사록","天书黎明"]', 1784690324138);
