INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('potion-wagami-wo-tasukeru', 'Potion, Wagami wo Tasukeru', 'I Saved Myself with a Potion!: Life in Another World', 'https://phimimg.com/upload/vod/20251011-1/ea076c917be1bf3b6943a0ee47dea6cd.jpg', 'https://phimimg.com/upload/vod/20251011-1/7df1e0f21316b116444e7b5bff4d3b4d.jpg', '<p>Kaede, một nữ sinh trung học bình thường, đột nhiên tỉnh dậy trong một con hẻm xa lạ—và nhận ra mình đã bị dịch chuyển đến một thế giới bí ẩn, nơi sinh sống của thú nhân, yêu tinh và rồng. Trong số đồ đạc của mình, cô phát hiện ra một cuốn sách kỳ lạ mà trước đây chưa từng có. Thật bất ngờ, nó cho phép cô tạo ra thuốc chỉ bằng cách niệm từ &quot;tạo&quot;. Dựa vào những loại thuốc này để sinh tồn, Kaede vượt qua những thử thách của thế giới kỳ ảo này trong khi bám víu vào hy vọng một ngày nào đó sẽ được trở về Nhật Bản. Hành trình đấu tranh và khám phá của cô trong thế giới siêu nhiên này mới chỉ bắt đầu...</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kaede Hondo","avatar":""},{"name":"Yu Kobayashi","avatar":""},{"name":"Takeo Otsuka","avatar":""},{"name":"Miharu Hanai","avatar":""},{"name":"Yurika Moriyama","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Potion, Wagami wo Tasukeru","Potion, waga mi wo tasukeru","Potion, Waga Mi o Tasukeru","Potions Will Save Me","I Saved Myself with a Potion!： Life in Another World","ポーション、わが身を助ける"]', 1784690324138);
