INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('potion-wagami-wo-tasukeru', 'Potion, Wagami wo Tasukeru', 'I Saved Myself with a Potion!: Life in Another World', 'potion, wagami wo tasukeru i saved myself with a potion!: life in another world kaede hondo yu kobayashi takeo otsuka miharu hanai yurika moriyama potion, wagami wo tasukeru potion, waga mi wo tasukeru potion, waga mi o tasukeru potions will save me i saved myself with a potion!： life in another world ポーション、わが身を助ける', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('egao-no-taenai-shokuba-desu', 'Egao no Taenai Shokuba desu.', 'A Mangaka''s Weirdly Wonderful Workplace', 'https://phimimg.com/upload/vod/20251023-1/6399ce40093c6789648341357062b48b.jpg', 'https://phimimg.com/upload/vod/20251023-1/cf4798bc05f603dfdc9aa55abf163829.jpg', '<p>Futami — một họa sĩ manga shoujo mới vào nghề — cuối cùng cũng sắp ra mắt tác phẩm mà cô hằng ấp ủ: “Dear Subaru”, bộ manga về cờ tướng Nhật (shogi) mà cô rất tâm huyết.Tuy nhiên, áp lực công việc khiến cô đau dạ dày triền miên, buộc phải trì hoãn thời hạn nộp chương đầu tiên, trong khi bản vẽ storyboard vẫn dậm chân tại chỗ. Không chỉ thế, cô còn tăng cân do thói quen ăn đêm, và bắt đầu mơ mộng hoang tưởng đủ chuyện!Liệu Futami có thể vừa theo đuổi giấc mơ trở thành họa sĩ manga, vừa tận hưởng cuộc sống một cách vui vẻ, hay sẽ bị cuốn vào vòng xoáy của stress và sáng tạo?</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuko Natsuyoshi","avatar":""},{"name":"Sora Amamiya","avatar":""},{"name":"Miku Ito","avatar":""},{"name":"Yu Kobayashi","avatar":""},{"name":"Eriko Matsui","avatar":""},{"name":"Iori Saeki","avatar":""},{"name":"Miharu Hanai","avatar":""},{"name":"Mamiko Noto","avatar":""},{"name":"Kikuko Inoue","avatar":""},{"name":"Saori Hayami","avatar":""},{"name":"Sumire Uesaka","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["欢迎来到笑容不断的职场。","這裡是充滿笑容的職場。","Egao no Taenai Shokuba desu.","A Workplace Where You Can''t Help But Smile","笑顔のたえない職場です。"]', 1784690324138);
