INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('egao-no-taenai-shokuba-desu', 'Egao no Taenai Shokuba desu.', 'A Mangaka''s Weirdly Wonderful Workplace', 'egao no taenai shokuba desu. a mangaka''s weirdly wonderful workplace yuko natsuyoshi sora amamiya miku ito yu kobayashi eriko matsui iori saeki miharu hanai mamiko noto kikuko inoue saori hayami sumire uesaka 欢迎来到笑容不断的职场。 這裡是充滿笑容的職場。 egao no taenai shokuba desu. a workplace where you can''t help but smile 笑顔のたえない職場です。', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kaguyasama-wa-kokurasetai-otona-e-no-kaidan', 'Kaguya-sama wa Kokurasetai: Otona e no Kaidan', 'かぐや様は告らせたい 大人への階段', 'https://phimimg.com/upload/vod/20260102-1/32975a17f8cf6ce636c6fc98bf530a3c.jpg', 'https://phimimg.com/upload/vod/20260102-1/ad12c5b14db7a5c734bee0234fea399e.jpg', '<p>Cốt truyện của tập đặc biệt này lấy bối cảnh sau khi các sự kiện chính tại Học viện Shuchiin đã trôi qua một thời gian. Nội dung phim xoay quanh việc Kaguya Shinomiya ngồi một mình trong phòng và xem lại cuốn album ảnh cũ. Những kỷ niệm về quãng thời gian đầy ắp tiếng cười và những trận &quot;chiến tranh tâm não&quot; với Miyuki Shirogane cùng các thành viên Hội học sinh ùa về. Đúng như tên gọi &quot;Nấc thang tiến tới trưởng thành&quot;, tập phim sẽ tập trung vào sự phát triển và thay đổi của các nhân vật khi họ bước dần vào thế giới người lớn, đồng thời nhìn lại những ký ức không thể thay thế tại trường học.</p>', 'Hoàn Tất (2/2)', 2, 'hoathinh', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324138);
