INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luyen-luyen-phong-lang-do', 'Luyến Luyến Phong Lăng Độ', 'A Vow In The Dark', 'https://phimimg.com/upload/vod/20251223-1/25765beac3c6d2dfc38782431bd31afd.jpg', 'https://phimimg.com/upload/vod/20251223-1/77c03a371a77a335d47b48dee573005b.jpg', '<p>Ba trăm năm trước, Tiên Cơ Cẩm Lễ đã đóng băng Ma Tôn Giới Xuyên. Ba trăm năm sau, tiểu tiên thú Kim Lý vô tình giải trừ phong ấn, vì có khả năng hấp thụ ma lực của Giới Xuyên nên bị bắt về Ma giới. Hai người trải qua mối quan hệ &quot;oan gia ngõ hẹp&quot;, vừa yêu vừa hận rồi dần nảy sinh tình cảm. Tuy nhiên, vết rạn nứt bắt đầu xuất hiện khi sự thật lộ ra: Kim Lý chính là do linh hồn của Cẩm Lễ hóa thân thành. Từ đây, cả hai bị cuốn vào vòng xoáy yêu hận tình thù đầy ngang trái.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lăng Mỹ Sĩ","avatar":""},{"name":"Hoàng Hựu Thiên","avatar":""},{"name":"Hà Thiện Khải","avatar":""},{"name":"Triệu Dục Kiệt","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Lian Lian Feng Ling Du","恋恋风陵渡"]', 1784690324138);
