INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('luyen-luyen-phong-lang-do', 'Luyến Luyến Phong Lăng Độ', 'A Vow In The Dark', 'luyến luyến phong lăng độ a vow in the dark lăng mỹ sĩ hoàng hựu thiên hà thiện khải triệu dục kiệt lian lian feng ling du 恋恋风陵渡', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-em-214-lan-o-shangrila', 'Yêu Em 214 Lần Ở Shangri-La', 'Love 214 Times In Shangrila', 'https://phimimg.com/upload/vod/20260101-1/a060d2525b9abd908428d6167691e866.jpg', 'https://phimimg.com/upload/vod/20260101-1/4c5aab1c39105df7ad95f637dca62d43.jpg', '<p>Tô Niệm – một blogger video ngắn – đã một mình tìm đến Shangri-La để thực hiện di nguyện tìm kiếm loài &#39;Chim Cầu Vồng&#39; huyền thoại của người cha vốn là một nhiếp ảnh gia về chim. Trong hành trình đó, cô tình cờ gặp gỡ Nông Bố, một nhân viên giám sát chim chóc người Tạng. Hai tâm hồn thuần khiết và chân thành dần nảy sinh tình cảm với nhau, nhưng ngay khi Nông Bố định bày tỏ lòng mình thì một tiếng súng vang lên ngắt quãng, anh đột ngột biến mất.Tô Niệm rơi vào vòng lặp thời gian vô tận, kiên trì tìm kiếm dấu vết của Nông Bố. Qua những lần tái ngộ rồi lại chia ly, cả hai đã cùng nhau thực hiện sự cứu rỗi từ hai phía. Trong hành trình này, họ dùng hành động thực tế để thực hiện sứ mệnh bảo vệ hệ sinh thái. Bộ phim lồng ghép khung cảnh hùng vĩ của Shangri-La cùng nét văn hóa đa dân tộc, với những di sản văn hóa phi vật thể như gốm đen Ni Tây hay điệu múa Guozhuang (Quả Trang)... Không chỉ kể về một tình yêu chữa lành băng qua phố thị và cao nguyên, bộ phim còn thể hiện trách nhiệm, niềm tin của thanh niên thời đại mới, phác họa nên bức tranh tươi đẹp về sự chung sống hài hòa giữa con người và thiên nhiên.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Tuấn Bút","avatar":""},{"name":"Tống Kỳ","avatar":""},{"name":"Dương Chính Di","avatar":""},{"name":"Lô Hương Sơn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["今生情定214"]', 1784690324138);
