INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-le-toan-khai', 'Hỏa Lệ Toàn Khai', 'Full Firepower', 'https://phimimg.com/upload/vod/20260101-1/3133c675a3e0603e790449b4f855c546.jpg', 'https://phimimg.com/upload/vod/20260101-1/360d0057991943df0851d2df9093eaf8.jpg', '<p>Dương Lệ Lệ vừa mới bước chân vào xã hội, làm một công việc sáng tạo đầy thú vị. Thế nhưng, đằng sau cuộc sống tưởng chừng như thong dong, tươi đẹp ấy lại là vô vàn áp lực bủa vây cùng lúc. Trong phút chốc nản lòng và giận dữ, Lệ Lệ đã leo lên sân thượng, và từ đó một cuộc kỳ ngộ chốn thành thị bắt đầu. Tại đây, cô tình cờ gặp gỡ Miêu Vương (Vua Mèo) bí ẩn, mở ra chuyến phiêu lưu trải nghiệm đa dạng thân phận để chạm tới cuộc đời hoàn mỹ.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Trí Nam","avatar":""},{"name":"Cao Khả Tân","avatar":""},{"name":"Lạc Uy","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Lychees in Full Bloom","Fully Openfire","火荔全开"]', 1784690324138);
