INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('voi-em-tinh-yeu-cua-chung-ta-se-vuot-qua', 'Với Em, Tình Yêu Của Chúng Ta Sẽ Vượt Qua', 'With You, Our Love Will Make It Through', 'https://phimimg.com/upload/vod/20251024-1/797b9fe9e9ccbb168b7a16d6bcf47d51.jpg', 'https://phimimg.com/upload/vod/20251024-1/317ff0dad1c7b41b206dfc469aae1913.jpg', '<p>Khi nữ sinh trung học Mari vội vã đến trường vì trễ học, cô không ngờ rằng mình lại phải lòng Tsunagu — một chàng nhân thú dịu dàng và tinh tế! Trong một thế giới nơi nhân thú bị ngăn cách sau những bức tường, Mari và Tsunagu đã chứng minh rằng sự khác biệt có thể trở thành những nhịp cầu nối liền hai thế giới. Liệu tình yêu của họ có đủ sức vượt qua ranh giới giữa loài người và nhân thú?&nbsp;</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Manaka Iwami","avatar":""},{"name":"Takuya Eguchi","avatar":""},{"name":"Koutaro Nishiyama","avatar":""},{"name":"Ai Kakuma","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Kimi to Koete Koi ni Naru","Kimito Koete Koininaru","Crossing the Walls of Love with You","Cross Race and Love You","Beyond Border, in Love We Are","キミと越えて恋になる"]', 1784690324138);
