INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('100-met', '100 MÉT', '100 METERS', 'https://phimimg.com/upload/vod/20251231-1/675036d2af8d6db7589b1aa2a6c9f1e2.jpg', 'https://phimimg.com/upload/vod/20251231-1/31aba441fb29c8f67a2615b414d7349f.jpg', '<p>ĐẠT 8.1 TRÊN IMDb - TRỞ THÀNH MOVIE ANIME THỂ THAO ĐƯỢC GIỚI PHÊ BÌNH QUỐC TẾ CA NGỢI LÀ “ĐỈNH CAO HOẠT HÌNH” “Kiệt Tác Rotoscoping” (vẽ lại dựa trên cảnh quay người thật) khi tạo nên những phân cảnh chi tiết với độ chân thực đáng kinh ngạc - Bộ Phim 100 MÉT là câu chuyện kéo dài hơn 15 năm, xoay quanh hai vận động viên chạy nước rút có xuất phát điểm trái ngược nhau:Togashi: Một &quot;thiên tài&quot; bẩm sinh về chạy bộ. Ngay từ khi còn nhỏ, cậu đã luôn chiến thắng mọi cuộc đua 100m một cách dễ dàng mà không cần nỗ lực nhiều.Komiya: Một học sinh chuyển trường, người có thừa sự quyết tâm và đam mê nhưng lại thiếu kỹ thuật.Khi còn học lớp 6, Togashi đã gặp và truyền cảm hứng cho Komiya. Nhiều năm trôi qua, họ gặp lại nhau trên đường đua với tư cách là đối thủ lớn nhất của nhau. Bộ phim đào sâu vào sự cạnh tranh, áp lực tâm lý, những chấn thương, và hành trình đầy khắc nghiệt của các vận động viên chuyên nghiệp để tìm ra ý nghĩa thực sự của việc chạy.</p>', 'Full', 1, 'single', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 1, '[{"name":"Tori Matsuzaka","avatar":""},{"name":"Shota Sometani","avatar":""},{"name":"Koki Uchiyama","avatar":""},{"name":"Kenjiro Tsuda","avatar":""},{"name":"Jun Kasama","avatar":""},{"name":"Rie Takahashi","avatar":""},{"name":"Yuki Tanaka","avatar":""},{"name":"Atsumi Tanezaki","avatar":""},{"name":"Aoi Yuuki","avatar":""},{"name":"Yuma Uchida","avatar":""},{"name":"Junya Enoki","avatar":""},{"name":"Haruki Ishiya","avatar":""},{"name":"Hiiro Ishibashi","avatar":""},{"name":"Tomokazu Sugita","avatar":""},{"name":"Haruki Ishiya","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Hyakuemu","100미터.","100Метровка","100M.","100 mètres","百米。","百米","ひゃくえむ。"]', 1784690324138);
