INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('taylor-swift-chuong-ket-cua-mot-ky-nguyen', 'Taylor Swift: Chương Kết của một Kỷ Nguyên', 'Taylor Swift: The End of an Era', 'https://phimimg.com/upload/vod/20251213-1/e3f765590b818fee537339dbb93bc946.jpg', 'https://phimimg.com/upload/vod/20251213-1/f2955e9562d4ed9f86bb08795557a420.jpg', '<p>The End of an Era do Don Argott thực hiện, mang đến cái nhìn về cuộc sống của Taylor Swift trong suốt quá trình lưu diễn kéo dài gần hai năm. Bộ phim ghi lại câu chuyện hậu trường, những lần ca sĩ tập luyện cùng ban nhạc, quy mô sân khấu. Ba mẹ Taylor, bạn trai Travis Kelce cùng các ca sĩ Gracie Abrams, Sabrina Carpenter, Ed Sheeran và Florence Welch cũng góp mặt trong tác phẩm.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Taylor Swift","avatar":""},{"name":"Travis Kelce","avatar":""},{"name":"Andrea Swift","avatar":""},{"name":"Ed Sheeran","avatar":""},{"name":"Florence Welch","avatar":""},{"name":"Sabrina Carpenter","avatar":""},{"name":"Gracie Abrams","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["泰勒·斯威夫特：时代巡回演唱会，一个时代的结束","泰勒·斯威夫特：时代巡回演唱会 时代终章","Taylor Swift: The End of an Era","Taylor Swift: The Eras Tour - The End of an Era","Taylor Swift | The Eras Tour | The End of an Era","The End of an Era"]', 1784690324138);
