INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-dem-kinh-hoang-2', 'Năm Đêm Kinh Hoàng 2', 'Five Nights at Freddy''s 2', 'https://phimimg.com/upload/vod/20251224-1/4e07f16d1802064c5170b4ec4d55432d.jpg', 'https://phimimg.com/upload/vod/20251224-1/19bd1d17add0685b3a437160f5406c46.jpg', '<p>Một năm sau cơn ác mộng siêu nhiên tại tiệm Pizza Freddy Fazbear, những câu chuyện xoay quanh sự kiện ấy đã bị bóp méo thành một huyền thoại kỳ quặc tại địa phương, truyền cảm hứng cho lễ hội Fazfest đầu tiên của thị trấn. Không hề biết sự thật bị che giấu, Abby lén trốn ra ngoài để gặp lại Freddy, Bonnie, Chica và Foxy — khởi đầu cho chuỗi sự kiện kinh hoàng, hé lộ bí mật đen tối về nguồn gốc thật sự của Freddy’s, và đánh thức một nỗi kinh hoàng bị chôn vùi suốt hàng thập kỷ.</p>', 'Full', 1, 'single', 'completed', 13, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Josh Hutcherson","avatar":""},{"name":"Piper Rubio","avatar":""},{"name":"Elizabeth Lail","avatar":""},{"name":"Matthew Lillard","avatar":""},{"name":"Freddy Carter","avatar":""},{"name":"Wayne Knight","avatar":""},{"name":"Mckenna Grace","avatar":""},{"name":"David Andrew Calvillo","avatar":""},{"name":"Teo Briones","avatar":""},{"name":"Audrey Lynn-Marie","avatar":""},{"name":"Miriam Spumpkin","avatar":""},{"name":"Han Soto","avatar":""},{"name":"Grant Feely","avatar":""},{"name":"Gavin Borders","avatar":""},{"name":"Bentley Cooper","avatar":""},{"name":"Carl Palmer","avatar":""},{"name":"Ann Mahon","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6