INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chon-chong-noi-chin-suoi', 'Chọn Chồng Nơi Chín Suối', 'Eternity', 'https://phimimg.com/upload/vod/20251223-1/daf0adc85607f244404540cdc61cda80.jpg', 'https://phimimg.com/upload/vod/20251223-1/426c3b61db382a8668fb2995d368403a.jpg', '<p>Trong thế giới bên kia, nơi các linh hồn chỉ có một tuần để quyết định nơi họ sẽ sống đời đời, Joan phải đối mặt với lựa chọn không thể: người đàn ông đã cùng cô đi hết cuộc đời, hay mối tình đầu chết trẻ — người đã chờ đợi cô suốt hàng thập kỷ.</p>', 'Full', 1, 'single', 'completed', 11, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Elizabeth Olsen","avatar":""},{"name":"Miles Teller","avatar":""},{"name":"Callum Turner","avatar":""},{"name":"Da''Vine Joy Randolph","avatar":""},{"name":"John Early","avatar":""},{"name":"Barry Primus","avatar":""},{"name":"Betty Buckley","avatar":""},{"name":"Darryl Scheelar","avatar":""},{"name":"Danny Mac","avatar":""},{"name":"Damon Scott Johnson","avatar":""},{"name":"Lucy Turnbull","avatar":""},{"name":"Christie Burke","avatar":""},{"name":"Sebastian Billingsley-Rodriguez","avatar":""},{"name":"Patrick Freyne","avatar":""},{"name":"Angela Galan","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["이터니티","Navždy s tebou?","สามรัก หนึ่งนิรันดร์","저세상 로맨스","‎''저세상 로맨스'' - Eternity","Tình Yêu Vĩnh Cửu - Eternity","Wieczność","Вечность","Eternity"]', 1784690324138);
