INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chon-chong-noi-chin-suoi', 'Chọn Chồng Nơi Chín Suối', 'Eternity', 'chọn chồng nơi chín suối eternity elizabeth olsen miles teller callum turner da''vine joy randolph john early barry primus betty buckley darryl scheelar danny mac damon scott johnson lucy turnbull christie burke sebastian billingsley-rodriguez patrick freyne angela galan 이터니티 navždy s tebou? สามรัก หนึ่งนิรันดร์ 저세상 로맨스 ‎''저세상 로맨스'' - eternity tình yêu vĩnh cửu - eternity wieczność вечность eternity', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('wicked-phan-2', 'Wicked: Phần 2', 'Wicked: For Good', 'https://phimimg.com/upload/vod/20251207-1/d2970945a2a7ab4651933198fb8b4f7c.jpg', 'https://phimimg.com/upload/vod/20251207-1/0cd8f75c34d22bfd69ad8b0c19272032.jpg', '<p>Chương cuối của câu chuyện bắt đầu khi Elphaba và Glinda đã xa cách, mỗi người đang sống với hậu quả từ những lựa chọn của riêng mình. Elphaba giờ đây bị cả xứ Oz xem như Phù thủy độc ác phương Tây, trong khi đó Glinda đã trở thành biểu tượng quyến rũ của Lòng tốt đối với toàn bộ xứ Oz. Và mọi thứ thay đổi khi một cô gái đến từ Kansas bất ngờ xuất hiện, khiến cuộc sống của xứ Oz bị đảo lộn. Glinda và Elphaba buộc phải cùng nhau đối mặt lần cuối, họ phải thật sự thấu hiểu nhau, bằng sự trung thực và đồng cảm, nếu muốn thay đổi chính mình và cả vận mệnh của xứ Oz. Liệu Elphaba và Glinda có thể vượt qua số phận đã được định sẵn để viết lại tương lai cho xứ sở phép màu này?&nbsp;</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Ariana Grande","avatar":""},{"name":"Cynthia Erivo","avatar":""},{"name":"Jonathan Bailey","avatar":""},{"name":"Jeff Goldblum","avatar":""},{"name":"Michelle Yeoh","avatar":""},{"name":"Ethan Slater","avatar":""},{"name":"Marissa Bode","avatar":""},{"name":"Colman Domingo","avatar":""},{"name":"Bowen Yang","avatar":""},{"name":"Bronwyn James","avatar":""},{"name":"Bethany Weaver","avatar":""},{"name":"Sharon D. Clarke","avatar":""},{"name":"Scarlett Spears","avatar":""},{"name":"Alice Fearn","avatar":""},{"name":"Adam James","avatar":""},{"name":"Keala Settle","avatar":""},{"name":"Dee Bradley Baker","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wicked: Part Two","Wicked: Parte 2","מרשעת: חלק 2","Злая: Часть вторая","Malvada: Para Sempre","魔法坏女巫2","Zlica 2. dio","Phù Thủy Xứ Oz: Phần 2","Wicked: Pour de bon","Злая: Навсегда","Wicked 2","Wicked: Parte II","Wicked 2 - For Good","Čarodejka: Druhá časť","ウィキッド 永遠の約束","Wicked: For Good"]', 1784690324138);
