INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ke-dam-len-danh-thuc-nguoi-chet', 'Kẻ Đâm Lén: Đánh Thức Người Chết', 'Wake Up Dead Man: A Knives Out Mystery', 'kẻ đâm lén: đánh thức người chết wake up dead man: a knives out mystery daniel craig josh o''connor glenn close josh brolin mila kunis jeremy renner kerry washington andrew scott cailee spaeny daryl mccormack thomas haden church jeffrey wright annie hamilton james faulkner bridget everett noah segan jamie knives out 3 wake up dead man 나이브스 아웃 3 достать ножи 3 puñales por la espalda 3 利刃出鞘3 利刃出鞘：亡者归来 knives out 3 - wake up dead man wake up dead man - knives out mystery wake up dead man - une histoire à couteaux tirés wake up dead man, une histoire à couteaux tirés wake up dead man une histoire à couteaux tirés ฆาตกรรมหรรษา ปาฏิหาริย์คนบาป wake up dead man：a knives out mystery de entre los muertos: un misterio de entre navajas y secretos wake up dead man: a knives out mystery', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('10dance', '10DANCE', '10DANCE', 'https://phimimg.com/upload/vod/20251218-1/27878b814ae97fff7860d5ce527eae92.jpg', 'https://phimimg.com/upload/vod/20251218-1/2a394d36586aeba9b93fa4d4e48e3474.jpg', '<p>Câu chuyện kể về hai vũ công có tính cách hoàn toàn trái ngược nhưng lại có chung niềm đam mê mãnh liệt với nghệ thuật. Họ quyết định bắt tay cùng nhau luyện tập để chuẩn bị cho một cuộc thi lớn.&nbsp; Dù ban đầu giữa hai người liên tục xảy ra những va chạm và xung đột do khác biệt về quan điểm, nhưng qua quá trình luyện tập, họ dần thấu hiểu và nảy sinh tình cảm mãnh liệt với đối phương.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Nhật Bản', 0, '[{"name":"Ryoma Takeuchi","avatar":""},{"name":"Keita Machida","avatar":""},{"name":"Shiori Doi","avatar":""},{"name":"Anna Ishii","avatar":""},{"name":"Shinya Hamada","avatar":""},{"name":"Oshirō Maeda","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["10 Dance","テンダンス","10DANCE"]', 1784690324138);
