INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-khac-qua-cam', 'Thời Khắc Quả Cảm', 'A Time For Bravery', 'https://phimimg.com/upload/vod/20251220-1/74655867e0c4b17ef3545c0abe842509.jpg', 'https://phimimg.com/upload/vod/20251220-1/47eaa998f04d8403309b35c57b2dbc74.jpg', '<p>Một nhà phân tích tâm lý đang lao động công ích giúp đỡ một đặc vụ đang suy sụp vì vợ ngoại tình. Cùng nhau, họ sẽ đối mặt với hiểm nguy và khám phá cơ hội thứ hai.</p>', 'Full', 1, 'single', 'completed', 19, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Mexico', 0, '[{"name":"Luis Gerardo Méndez","avatar":""},{"name":"Memo Villegas","avatar":""},{"name":"Christian Tappán","avatar":""},{"name":"Verónica Bravo","avatar":""},{"name":"Noé Hernández","avatar":""},{"name":"Fernando Cuautle","avatar":""},{"name":"Santiago Sandoval","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Die Stunde der Mutigen","Eroi cercasi","Thérapie de choc","La hora de los valientes"]', 1784690324138);
