INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ultraman-arc-anh-sang-va-ac-quy-doi-dau', 'Ultraman Arc: Ánh Sáng Và Ác Quỷ Đối Đầu', 'Ultraman Arc the Movie: The Clash of Light and Evil', 'https://phimimg.com/upload/vod/20251230-1/4c98713649487e5335c5a4eb01758ecc.jpg', 'https://phimimg.com/upload/vod/20251230-1/b92fcad988db601919bd1ca6f0b2d319.jpg', '<p>Trái Đất đang đứng trước hiểm họa khi một thế lực bóng tối cổ xưa trỗi dậy, gieo rắc hủy diệt trên diện rộng. Ultraman Arc xuất hiện kịp thời để ngăn chặn âm ưu ấy, nhưng càng chiến đấu anh càng phát hiện kẻ thù không chỉ nhắm vào nhân loại mà còn muốn phá vỡ cân bằng giữa các chiều không gian. Những trận đối đầu khốc liệt liên tiếp đẩy Arc vào lựa chọn khó khăn, buộc anh phải khai mở sức mạnh mới để bảo vệ Trái Đất trước cuộc va chạm định mệnh giữa ánh sáng và bóng tối.</p>', 'Full', 1, 'single', 'completed', 11, 2025, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 1, '[{"name":"Yuki Totsuka","avatar":""},{"name":"Sho Kaneta","avatar":""},{"name":"Kaho Mizutani","avatar":""},{"name":"Kouichiro Nishi","avatar":""},{"name":"Shoki Nakayama","avatar":""},{"name":"Hinako Tanaka","avatar":""},{"name":"Naoto Takenaka","avatar":""},{"name":"Yuya Hirose","avatar":""},{"name":"Miki Mizuno","avatar":""},{"name":"Masato Hagiwara","avatar":""},{"name":"Juki Suetsugu","avatar":""},{"name":"Toshihide Onitsuka","avatar":""},{"name":"Yûki Ôhara","avatar":""},{"name":"Emi Soma","avatar":""},{"name":"Keita Rikimaru","avatar":""},{"name":"Hajime Tomine","avatar":""},{"name":"Daima Matsushita","avatar":""},{"name":"K","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Urutoraman Āku THE MOVIE Chō Jigen Daikessen! Hikari to Yami no Āku","亚刻奥特曼大电影：超次元大决战！光与暗的亚刻","亚刻奥特曼 大电影 超次元大决战！ 光与暗的亚刻","ウルトラマンアークTHE MOVIE 超次元大決戦！光と闇のアーク"]', 1784690324138);
