INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ultraman-arc-anh-sang-va-ac-quy-doi-dau', 'Ultraman Arc: Ánh Sáng Và Ác Quỷ Đối Đầu', 'Ultraman Arc the Movie: The Clash of Light and Evil', 'ultraman arc: ánh sáng và ác quỷ đối đầu ultraman arc the movie: the clash of light and evil yuki totsuka sho kaneta kaho mizutani kouichiro nishi shoki nakayama hinako tanaka naoto takenaka yuya hirose miki mizuno masato hagiwara juki suetsugu toshihide onitsuka yûki ôhara emi soma keita rikimaru hajime tomine daima matsushita k urutoraman āku the movie chō jigen daikessen! hikari to yami no āku 亚刻奥特曼大电影：超次元大决战！光与暗的亚刻 亚刻奥特曼 大电影 超次元大决战！ 光与暗的亚刻 ウルトラマンアークthe movie 超次元大決戦！光と闇のアーク', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-hang-luu-do', 'Nhà Hàng Lựu Đỏ', 'Fragrance Of The Pomegranates', 'https://phimimg.com/upload/vod/20251023-1/af0c6c0613d561af012e7b3b1be7754f.jpg', 'https://phimimg.com/upload/vod/20251023-1/9b1796aa73d63328f5325610719d663b.jpg', '<p>Minh Lượng, một sinh viên tốt nghiệp học viện mỹ thuật, vì mẹ nuôi bị bệnh nặng nên đã từ bỏ cơ hội tiếp tục học lên cao, thay mẹ gánh vác việc kinh doanh nhà hàng Lựu Đỏ. Minh Lượng tháo vát giải quyết những vấn đề phát sinh và đưa Lựu Đỏ trở thành một nhà hàng cực kỳ chất lượng. Trong quá trình ấy, anh không chỉ trưởng thành, chững chạc hơn, mà còn tích lũy được thêm sức mạnh để phát triển trên con đường nghệ thuật. Trong thời gian ấy, anh tình cờ gặp lại Cổ Lệ Na Nhĩ - cô bạn thanh mai trúc mã độc lập, mạnh mẽ thời thơ ấu. Hai người đã chữa lành những tổn thương cho nhau, cùng nhau trưởng thành, và cuối cùng trở thành người yêu, tri kỷ của nhau trong hành trình tiếp theo của cuộc đời.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Bạch Vũ Phàm","avatar":""},{"name":"Gia Nại Na","avatar":""},{"name":"Đồ Tùng Nham","avatar":""},{"name":"Lưu Nhuế Lân","avatar":""},{"name":"Vương Hoà","avatar":""},{"name":"Cao Chí Đình","avatar":""},{"name":"Khổng Đô Tư Tháp Tây","avatar":""},{"name":"A Lệ Mã","avatar":""},{"name":"Abdukerim Abliz","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["飘香的日子","ئانارنىڭ تەمى","Fragrance of the Pomegranates","Sun-kissed Days","Fragrance of Pomegranates","红石榴餐厅"]', 1784690324138);
