INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('do-ngot-thai-lan', 'Đồ Ngọt Thái Lan', 'Thai Sweet', 'https://phimimg.com/upload/vod/20251224-1/48ba759a7ff3970c7149c60a57a3dd08.jpg', 'https://phimimg.com/upload/vod/20251224-1/7b3ba99bca062a5ad178a7ae97220a91.jpg', '<p>Đây là một chương trình thực tế về du lịch dành cho các cặp đôi (CP), kết hợp lãng mạn giữa cốt truyện trong phim và hành trình trải nghiệm thực tế. Cặp đôi &quot;Mộ Mộ Triêu Triêu&quot; (Ngu Thư Hân, Hà Dữ) trong bộ phim Song Quỹ sẽ cùng nhau quay trở lại nơi định tình trong phim là Thái Lan, bắt đầu chuyến hành trình lãng mạn kéo dài 5 ngày 4 đêm. Chương trình hứa hẹn mang đến cho người hâm mộ một &quot;bữa tiệc đường mật&quot; mãn nhãn, tạo nên một phần ngoại truyện cực kỳ ngọt ngào cho bộ phim Song Quỹ.</p>', 'Hoàn Tất (12/12)', 12, 'tvshows', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngu Thư Hân","avatar":""},{"name":"Hà Dữ","avatar":""},{"name":"Phí Khải Minh","avatar":""},{"name":"Patrick Nattawat Finkler","avatar":""},{"name":"Mike Angelo","avatar":""},{"name":"Trương Bích Thần","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Thai Sweet","泰甜啦"]', 1784690324138);
