INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-nhay-mua-diec-vu-chi-thanh', 'Thành Phố Nhảy Múa (Diệc Vũ Chi Thành)', 'Second Chance Romance', 'https://phimimg.com/upload/vod/20251202-1/217b462f3fc26bdcc03816261e1e3c40.jpg', 'https://phimimg.com/upload/vod/20251202-1/f6aa34ee8a652b5a72152f420bae618b.jpg', '<p>Nghệ sĩ ba lê Đàm Tư Đình giải nghệ trở về nước, mong muốn nối lại tình xưa với Phùng Duệ, người yêu năm xưa bị buộc phải chia tay. Thế nhưng, những hiểu lầm trong quá khứ lại như vực sâu chia cắt hai người. Phùng Duệ hiện tại sống lặng lẽ như mặt hồ yên tĩnh, một mình nuôi con. Sự trở về của Đàm Tư Đình giống như một hòn đá ném xuống hồ nước, khuấy đảo tất cả. Bên cạnh Đàm Tư Đình vẫn luôn có một người âm thầm yêu cô suốt mười năm, lần này quyết tâm theo đuổi, không rời bỏ cô. Phùng Duệ và Đàm Tư Đình cố gắng trốn tránh nhau, nhưng vòng xoáy số phận lại liên tục cuốn họ vào cùng một chỗ, khiến họ yêu hận khó xử, khó buông.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 15, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Chung Hàn Lương","avatar":""},{"name":"Tần Lạn","avatar":""},{"name":"Bạch Băng","avatar":""},{"name":"Vương Quán Dị","avatar":""},{"name":"Vương Chân Nhi","avatar":""},{"name":"Vương Nhất Chu","avatar":""},{"name":"Trương Vân Kỳ","avatar":""},{"name":"Lý Gia Hạo","avatar":""},{"name":"Trần Cẩm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["谁在时间的彼岸","Second Chance Romance","亦舞之城"]', 1784690324138);
