INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thanh-pho-nhay-mua-diec-vu-chi-thanh', 'Thành Phố Nhảy Múa (Diệc Vũ Chi Thành)', 'Second Chance Romance', 'thành phố nhảy múa (diệc vũ chi thành) second chance romance chung hàn lương tần lạn bạch băng vương quán dị vương chân nhi vương nhất chu trương vân kỳ lý gia hạo trần cẩm 谁在时间的彼岸 second chance romance 亦舞之城', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-bat-tri', 'Quân Bất Tri', 'The Ultimate Vow Unknown To You', 'https://phimimg.com/upload/vod/20251221-1/3cbbb2f9bcb3f95e01f7f3df00ac45da.jpg', 'https://phimimg.com/upload/vod/20251221-1/aa9499abd0f170097a924a757c5c4253.jpg', '<p>Gia tộc của Thẩm Thanh Như thảm bại trước họa diệt môn, cô lầm tưởng Vũ Văn Khuyết là kẻ thủ ác nên đã dấn thân vào hành trình trả thù. Cô gả vào phủ Tướng quân, bị giam cầm nơi cung cấm, cùng Vũ Văn Khuyết dằn vặt lẫn nhau trong vòng xoáy yêu hận tình thù. Cuối cùng, khi chân tướng đại bạch, Vũ Văn Khuyết vì bảo vệ cô mà sẵn sàng hy sinh tất cả, hai người mới hóa giải hận thù. Thẩm Thanh Như sau đó nhận tổ quy tông, trở thành Công chúa Thương Châu và tìm thấy sự cứu rỗi giữa những cuộc đấu tranh quyền lực.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hứa Hiểu Nặc","avatar":""},{"name":"Lý Nghiên","avatar":""},{"name":"Trương Ý Nguyệt","avatar":""},{"name":"Hà Diệc Khả","avatar":""},{"name":"Khương Ngọc Giai","avatar":""},{"name":"Vương Cương","avatar":""},{"name":"Mẫn Chính","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["君不知"]', 1784690324138);
