INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('quan-bat-tri', 'Quân Bất Tri', 'The Ultimate Vow Unknown To You', 'quân bất tri the ultimate vow unknown to you hứa hiểu nặc lý nghiên trương ý nguyệt hà diệc khả khương ngọc giai vương cương mẫn chính 君不知', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-ngay-no-minh-bong-dung-tro-thanh-cong-chua', 'Một Ngày Nọ, Mình Bỗng Dưng Trở Thành Công Chúa', 'The Fated Magical Princess: Who Made Me a Princess', 'https://phimimg.com/upload/vod/20250930-1/a96244ad98c166b4c4913c7766118a55.jpg', 'https://phimimg.com/upload/vod/20250930-1/5559ffa9513a9e738e1daaaa2957a54c.jpg', '<p>Mấu chốt để tránh khỏi Bad End là chiếm được trái tim của người cha lạnh lùng? Công chúa Anthanasia sinh ra tại Đế quốc Phép thuật Obelia sở hữu một năng lực kỳ lạ: cô có thể thấy trước được tương lai. Từ khi mới sinh, cô đã bị cha mình là Hoàng đế Claude ghẻ lạnh, phải lớn lên một mình trong cung điện Hồng Ngọc. Một ngày nọ, cô mơ thấy tương lai mình sẽ bị chính cha ruột trục xuất ra khỏi cung điện vào sinh nhật 18 tuổi. Để thay đổi vận mệnh, Athanasia đã đứng lên, quyết tâm tràn ngập trong cơ thể bé nhỏ. &quot;&quot;Mình không muốn chấp nhận một tương lai như thế!&quot;&quot; Và thế là câu chuyện kỳ ảo về một cô công chúa nhỏ tìm cách thay đổi định mệnh bắt đầu!</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tao Dian","avatar":""},{"name":"Zhao Lu","avatar":""},{"name":"Ma Zhengyang","avatar":""},{"name":"Zhang Qi","avatar":""},{"name":"Sun Ye","avatar":""},{"name":"Xu Hui","avatar":""},{"name":"Chen Yiwen","avatar":""},{"name":"Yang Chaoran","avatar":""},{"name":"Mu Xueting","avatar":""},{"name":"Zhang Pei","avatar":""},{"name":"Du Qingqing","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Mofa Gongzhu De Xiao Fannao","Mo Fa Gong Zhu De Xiao Fan Nao","魔法公主的小烦恼动画片","某天成为公主","ناگهان یک روز تبدیل به یک پرنسس شدم","あるひ、おひめさまになってしまったけんについて","Aru Hi, Ohimesama ni Natte Shimatta Ken ni Tsuite","ある姫","Aruhime","Aru Hi, Ohime-sama ni Natteshimatta Ken ni Tsuite","Eoneu Nal Gongjuga Doeeobeoryeotda","Eoneu Nal Gongjuga Doeeo Beoryeotda","من جعلني أميرة","Kim Beni Prenses Yaptı","某天成為公主","Suddenly Became a Princess One Day","One Day, I Became a Princess","Suddenly, I Became a Princess","WMMAP","Who Made Me a Princess","Who Make Me A Princess","魔法公主的小烦恼"]', 1784690324138);
