INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-quy-khach', 'Vô Quy Khách', 'The Man With No Return', 'https://phimimg.com/upload/vod/20251229-1/697578b2142b05c6446fc91b3d18504b.jpg', 'https://phimimg.com/upload/vod/20251229-1/fa14993f294fce376958e8a05ce56d8b.jpg', '<p>Tống Ẩn nhận lệnh điều tra vụ án sản xuất và buôn bán &quot;Cực Lạc Cao&quot;. Trong quá trình phá án, anh nhận được sự giúp đỡ của hiệp khách Dạ Sát, đại phu Yến Vân Thăng và dược sư Tố Nga. Nhờ vào những trận chiến ngoan cường và sự hy sinh dũng cảm, họ đã xé toang tấm bình phong che chở cho tên tội phạm cầm đầu Bạch Khải Niên, mang lại sự bình yên cho người dân.</p>', 'Full', 1, 'single', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tống Dương","avatar":""},{"name":"Trần Lập Nông","avatar":""},{"name":"Khương Bội Dao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Irrevocable Bladesman","无归客"]', 1784690324138);
