INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('undead-unluck-winterhen', 'Undead Unluck: Winter-hen', 'Undead Unluck: Winter-hen', 'https://phimimg.com/upload/vod/20251229-1/f0ec990bb6539b1029819bfae3f6b653.jpg', 'https://phimimg.com/upload/vod/20251229-1/a01c4004315ab616a784ab840d69effa.jpg', '<p>Giữa trận bão tuyết do UMA Winter gây ra, Billy nhận được báo cáo về trận chiến với Autumn và biết rằng Undead cùng Unluck đang không ngừng tiến hóa. Juiz xuất hiện, tiết lộ với anh rằng các cổ vật (Artifacts) thực chất là những vũ khí được tạo ra để tiêu diệt Chúa và con tàu Ark (Vòng xoay) chỉ còn đủ năng lượng cho đúng một lần du hành thời gian cuối cùng. Cô thúc giục Billy hãy hợp lực một lần nữa, đặt cược tất cả vào Unluck để đạt được mục tiêu chung: &quot;tiêu diệt Chúa&quot;.Tuy nhiên, Billy tuyên bố rằng họ không thể cùng chung đường. Juiz nhận ra ý định thực sự của Billy là chiếm đoạt Ark và Apocalypse — nhưng trước khi cô kịp hành động, Billy đã kéo tất cả vào một cuộc giao tranh tàn khốc với sự tham gia của các UMA từ cả hai phía. Kiên định với &quot;chính nghĩa&quot; của riêng mình, Juiz tiến về phía trước với lưỡi kiếm trên tay, trong khi Billy đáp trả bằng cách sử dụng súng lục và năng lực của các Negator (Người phủ định) khác.Mục tiêu thực sự của Billy là gì? Trong khi đó, Andy và Fuko, sau khi thu thập được lõi của Autumn, đang trên đường di chuyển bằng đường hàng không để tiêu diệt Summer. Nhưng Billy đã dự đoán được việc Juiz giao phó Apocalypse cho Andy, và hắn đã cử sát thủ đến để tấn công cặp đôi ngay trên bầu trời!</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Moe Kahara","avatar":""},{"name":"Yuichi Nakamura","avatar":""},{"name":"Mariya Ise","avatar":""},{"name":"Rikiya Koyama","avatar":""},{"name":"Kensho Ono","avatar":""},{"name":"Hiroki Yasumoto","avatar":""},{"name":"Natsuki Hanae","avatar":""},{"name":"Koji Yusa","avatar":""},{"name":"Tomokazu Sugita","avatar":""},{"name":"Takehito Koyasu","avatar":""},{"name":"Toshiyuki Morikawa","avatar":""},{"name":"Nobuo Tobita","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324138);
