INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuong-gia-thien-ha-phan-6', 'Vương Giả Thiên Hạ (Phần 6)', 'Kingdom (Season 6)', 'https://phimimg.com/upload/vod/20251006-1/6016016e7fc346f80c74f016ff1ab879.jpg', 'https://phimimg.com/upload/vod/20251006-1/f1c452a23038b9a8b30773791a6346de.jpg', '<p>Vào thời Chiến Quốc của Trung Hoa cổ đại, chiến tranh đã gây nên vô số những điều thảm khốc khiến cho nhiều người mất đi gia đình, người thân. Tín là một trong số đó, cậu có ước mơ trở thành đại tướng quân thống lĩnh binh lính xung trận. Để rồi cuộc đời đưa đẩy Tín trở thành người phò tá dưới trướng đương kim thánh thượng Doanh Chính - người có gương mặt giống hệt bạn thân Phiêu của Tín.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yutaka Nakano","avatar":""},{"name":"Rie Kugimiya","avatar":""},{"name":"Masakazu Morita","avatar":""},{"name":"Jun Fukuyama","avatar":""},{"name":"Yoko Hikasa","avatar":""},{"name":"Toshiyuki Morikawa","avatar":""},{"name":"Junichi Suwabe","avatar":""},{"name":"Tessyo Genda","avatar":""},{"name":"Akio Kato","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Kingdom: the animation","战国英雄","Kingudamu","Kingdom","킹덤 3기","킹덤 2기","킹덤 1기","킹덤 5기","킹덤 4기","Королевство","كينقدوم","كينجدوم","王者天下第四季","王者天下第五季","王者天下 第五季","王者天下","Legend","Vương Giả Thiên Hạ","キングダム"]', 1784690324138);
