INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vuong-gia-thien-ha-phan-6', 'Vương Giả Thiên Hạ (Phần 6)', 'Kingdom (Season 6)', 'vương giả thiên hạ (phần 6) kingdom (season 6) yutaka nakano rie kugimiya masakazu morita jun fukuyama yoko hikasa toshiyuki morikawa junichi suwabe tessyo genda akio kato kingdom: the animation 战国英雄 kingudamu kingdom 킹덤 3기 킹덤 2기 킹덤 1기 킹덤 5기 킹덤 4기 королевство كينقدوم كينجدوم 王者天下第四季 王者天下第五季 王者天下 第五季 王者天下 legend vương giả thiên hạ キングダム', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuu-long-mang-dao-khu-bach-ma', 'Cửu Long Mang Đao Khử Bạch Mã', 'Bound By A Promise', 'https://phimimg.com/upload/vod/20251229-1/bf37f490c32f7936e2d66f0ab5ccc366.jpg', 'https://phimimg.com/upload/vod/20251229-1/389f6d8e523f65d838ec1eedde48dc4a.jpg', '<p>Trần Thập Tam là cựu binh quân Lũng Hữu năm xưa, nay là một nông phu bị tàn tật chân phải. Để trả món nợ mười lăm lạng bạc mà gia đình đang nợ một phú hào địa phương, anh buộc phải nhận nhiệm vụ từ kẻ bất lương Trương Vị giao phó: áp giải hiệp đạo giang hồ Tô Hoán đến Bạch Mã Quan. Hành trình áp giải đầy rẫy hiểm nguy, nhiều thế lực liên tiếp rình rập, tìm cách cướp người. Trần Thập Tam dựa vào võ nghệ và mưu lược tích lũy trong những năm chinh chiến, lần lượt ứng biến, hóa giải từng đợt tập kích. Cuối cùng, trong trận chiến kéo dài đến giây phút sau cùng, chính tinh thần hiệp nghĩa giữ chữ tín nặng ngàn vàng của Trần Thập Tam đã khiến thủ lĩnh trùm cướp Tô Hoán kinh sợ, tự nguyện cúi đầu chịu trói.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"La Lợi Quần","avatar":""},{"name":"Đào Hoàng","avatar":""},{"name":"Cao Tân Thắng","avatar":""},{"name":"Michael Mao","avatar":""},{"name":"Vệ Tiểu Huyền","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["구룡고도거백마","九龙挎刀去白马"]', 1784690324138);
