INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-tim-que-quat', 'Trái Tim Què Quặt', 'Crooked Heart', 'https://phimimg.com/upload/vod/20251228-1/334226be504001bd56d0c586bf5d96e0.jpg', 'https://phimimg.com/upload/vod/20251228-1/01c581e13dff7d2430f5857ae0753aa7.jpg', '<p>Một vụ án mạng tàn bạo làm chấn động thị trấn yên bình. Khi thi thể người phụ nữ bị sát hại dã man được phát hiện, mọi nghi ngờ đổ dồn vào Sơn — có thể là người tình của nạn nhân. Triết, một nhà điêu khắc danh tiếng, rơi vào giằng xé giữa nghi ngờ và tình thân khi anh cùng vợ mình cố gắng tìm cách minh oan cho em trai. Rốt cuộc, Sơn là kẻ giết người, nạn nhân của định mệnh nghiệt ngã, hay một trái tim lạc lối bị cuốn vào tình yêu đến mức tự hủy diệt.</p>', 'Full', 1, 'single', 'completed', 19, 2025, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Quách Ngọc Ngoan","avatar":""},{"name":"Xuan Van Nguyen","avatar":""},{"name":"Nhật Linh","avatar":""},{"name":"Việt Hưng","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Trái Tim Què Quặt"]', 1784690324138);
