INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-ca-ha-ha-ha', 'Đại Ca Ha Ha Ha', 'Boss', 'https://phimimg.com/upload/vod/20251228-1/f96dd9087576fbb5ad79800cb4546d7c.jpg', 'https://phimimg.com/upload/vod/20251228-1/2fe8766632c86e7f6e56f296438d5fd4.jpg', '<p>Soon Tae nuôi mộng mở chuỗi nhà hàng tiếng tăm, quyết rửa tay gác kiếm nhưng bất đắc dĩ bị chỉ định làm đại ca xã đoàn. Anh nhanh chóng tìm cách đẩy trách nhiệm này cho Kang Pyo, cháu trai của ông trùm quá cố, nhưng đời không như mơ, Kang Pyo lại ôm ấp giấc mơ trở thành vũ công tango, chẳng buồn ngó lại nghiệp giang hồ. Chỉ riêng Pan Ho, kẻ chuyên gây rối lại là người duy nhất tha thiết muốn làm đại ca… nhưng tréo ngoe là chẳng ai tin tưởng. Thế là một cuộc &quot;đại chiến né chức&quot; nổ ra với mục tiêu tối thượng: Thua đường vote là thắng đường đời!</p>', 'Full', 1, 'single', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"Jo Woo-jin","avatar":""},{"name":"Jung Kyung-ho","avatar":""},{"name":"Park Ji-hwan","avatar":""},{"name":"Lee Kyoo-hyung","avatar":""},{"name":"Oh Dal-su","avatar":""},{"name":"Hwang Woo-seul-hye","avatar":""},{"name":"Jung Yoo-jin","avatar":""},{"name":"Lee Sung-min","avatar":""},{"name":"Ko Chang-seok","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["谁想当老大","보스"]', 1784690324138);
