INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuong-menh', 'Chưởng Mệnh', 'The Architect', 'https://phimimg.com/upload/vod/20251211-1/7f885c9e5ad9cf3b63a5c934d57ca7ad.jpg', 'https://phimimg.com/upload/vod/20251211-1/80dd3bc665a3bf2e995f62ac37eeb019.jpg', '<p>Thương nhân hàng hải Thẩm Trường Ninh bị thảm sát diệt môn và ném xác xuống sông vào đêm tân hôn. Cô đã tái sinh một cách kỳ diệu thành Tịch Nhan, một vũ cơ trong phủ Đô đốc Bùi Dục.&nbsp; Mang trong mình mối thù sâu đậm, cô lấy sắc đẹp làm mồi nhử và trí tuệ làm lá chắn, từng bước tính toán. Cô liên thủ với Bùi Dục, người nắm giữ quyền lực khuynh đảo triều đình, để cùng nhau bày bố trong ván cờ báo thù này, quyết giành lại số phận và công bằng thuộc về mình...</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Niệm","avatar":""},{"name":"Vu Hiên Thần","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Zhang Ming","Controlling Fate","The Architect","掌命"]', 1784690324138);
