INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-tinh-ca-diu-dang', 'Bản Tình Ca Dịu Dàng', 'Love Me Tender', 'https://phimimg.com/upload/vod/20251219-1/418721cb22931a43f6d042f371f113b1.jpg', 'https://phimimg.com/upload/vod/20251219-1/21e935a840b1f4ba8af944f3a4bbfdee.jpg', '<p>Kha Vũ Nhu từ bỏ đam mê múa để kết hôn với Từ Tử Sâm, nhưng sau 7 năm cô phát hiện chồng ngoại tình và quyết định chấm dứt cuộc hôn nhân thương mại này. Mẹ chồng là Từ Lan vì muốn chiếm đoạt tài sản nhà họ Kha nên đã thuê Lý Hạo Thanh để hãm hại cô.Tuy nhiên, Hạo Thanh vốn là đồng đội cũ luôn yêu thầm Vũ Nhu từ lâu, nên anh đã giả vờ làm việc cho mẹ chồng nhưng thực chất lại âm thầm bảo vệ cô. Cuối cùng, với sự giúp đỡ của bạn bè, Vũ Nhu đã đánh bại được mẹ chồng, lấy lại tài sản gia đình và tìm thấy hạnh phúc đích thực bên Hạo Thanh.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Tử Đồng","avatar":""},{"name":"Hứa Khải Tân","avatar":""},{"name":"Cốc Phong","avatar":""},{"name":"Vương Đình Vũ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Love Me Tender","柔情史"]', 1784690324138);
