INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-tha-huong', 'Bác Sĩ Tha Hương', 'The Outlaw Doctor', 'https://phimimg.com/upload/vod/20250315-1/771160a77b1f5f92f003eb39a75ca139.jpg', 'https://phimimg.com/upload/vod/20250315-1/55b165226209d95a3880a13b63ed8062.jpg', '<p>Nội dung phim xoay quanh Phạm Văn Ninh (Liên Bỉnh Phát) - bác sĩ có tiếng tại Việt Nam, gác lại mọi dự án đến Đài Loan chăm sóc mẹ bệnh nặng. Không thể hành nghề y nơi xứ người, một mặt Ninh chấp nhận công việc tạp vụ ở bệnh viện, mặt khác làm bác sĩ &quot;chui&quot;, tích góp từng đồng. Chàng trai Việt và bác sĩ gốc Hoa Trịnh Uyển Bình (Trương Quân Ninh) chạm mặt trong những tình huống cấp bách, đồng hành cô cứu người. Hai con người đơn độc xích lại gần nhau nhờ đồng quan điểm sống, nhiệt huyết với nghề.</p>', 'Full', 11, 'series', 'completed', 22, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Đài Loan', 0, '[{"name":"Liên Bỉnh Phát","avatar":""},{"name":"Janine Chang Chun-Ning","avatar":""},{"name":"Weber Yang","avatar":""},{"name":"Hsia Teng Hung","avatar":""},{"name":"Hsu An-Chih","avatar":""},{"name":"Ina Tsai","avatar":""},{"name":"Chang-Ying Hsieh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bác Sĩ Tha Hương","化外之醫"]', 1784690324138);
