INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('shabake', 'Shabake', 'Shabake', 'https://phimimg.com/upload/vod/20251005-1/d8750e22c9b823246a4ce2c82119963f.jpg', 'https://phimimg.com/upload/vod/20251005-1/cebdf0747febab4a7b79c2658cb84312.jpg', '<p>Ichitaro, chủ nhân yếu ớt nhưng thông tuệ của gia tộc Nagasakiya, hiếm khi rời khỏi dinh thự của mình — nhưng anh không hề cô đơn. Sở hữu năng lực nhìn thấy linh hồn, anh được bảo vệ bởi những người bạn ma quái như Hakutaku và Inugami. Một đêm nọ, Ichitaro lén ra ngoài và chứng kiến một vụ án mạng tàn bạo. Ngay sau đó, thành Edo bị bao trùm bởi hàng loạt vụ giết người kỳ lạ. Khi nỗi sợ hãi lan khắp thành phố, Ichitaro cùng các linh hồn của mình phải vạch trần hung thủ đứng sau tất cả.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 167, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Daiki Yamashita","avatar":""},{"name":"Koji Okino","avatar":""},{"name":"Taku Yashiro","avatar":""},{"name":"Daisuke Namikawa","avatar":""},{"name":"Seiichiro Yamashita","avatar":""},{"name":"Shimba Tsuchiya","avatar":""},{"name":"Shion Wakayama","avatar":""},{"name":"Akira Sekine","avatar":""},{"name":"Shinya Takahashi","avatar":""},{"name":"Misako Tomioka","avatar":""},{"name":"Akane Matsunaga","avatar":""},{"name":"Aika Wakuno","avatar":""},{"name":"Takako Tanaka","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["しゃばけ"]', 1784690324138);
