INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-chuyen-nhan-cuoi-phan-2', 'Câu Chuyện Nhẫn Cưới (Phần 2)', 'Tales Of Wedding Rings (Season 2)', 'https://phimimg.com/upload/vod/20251005-1/d06100fc2100e73636a03d1a2a8c1781.jpg', 'https://phimimg.com/upload/vod/20251005-1/665f3fe29ccc68d7bde5db5c36a17380.jpg', '<p>Satou đã yêu đương với người bạn thời thơ ấu và hàng xóm của mình, Hime, từ khi cô và ông nội của cô xuất hiện đột ngột cách đây 10 năm. Bây giờ, Hime trở thành một cô gái xinh đẹp rực rỡ nhưng bí ẩn, khiến cho việc thổ lộ tình cảm của anh trở nên khó khăn hơn. Khi ngày kỷ niệm của cuộc gặp gỡ đầu tiên của họ đang đến gần, liệu anh ấy có đủ can đảm để biến mối quan hệ bạn bè của họ thành một điều gì đó hơn? Hay một số số phận hoàn toàn khác đang chờ đợi đôi bạnc mặc kết nối chặt chẽ này?</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Gen Sato","avatar":""},{"name":"Akari Kito","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["婚戒故事","Kekkon Yubiwa Monogatari II","Kekkon Yubiwa Monogatari","結婚指輪物語"]', 1784690324138);
