INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-cau-cua-toi', 'Ông Cậu Của Tôi', 'Uncle', 'https://phimimg.com/upload/vod/20251218-1/dbdbcc4f978293578fd9f7517e81dd3c.jpg', 'https://phimimg.com/upload/vod/20251218-1/b90d5feffe27b782f2f6a60ae3cde99e.jpg', '<p>Người mà cậu bé Nhị Bàn ngưỡng mộ nhất chính là cậu của mình. Từ nhỏ, cậu của Nhị Bàn đã có thành tích học tập xuất sắc, tốt nghiệp Đại học Công nghiệp Cáp Nhĩ Tân. Với tất cả những điều mới lạ, anh đều tiếp thu thần tốc, tự học thành tài. Trong thập niên 90, khi nền kinh tế Trung Quốc có những bước chuyển đổi toàn diện, với tài năng đầy mình, anh luôn ấp ủ những lý tưởng mới và liên tục khởi nghiệp. Mặc dù cuộc đời bôn ba, lăn lộn ấy phải trải qua vô vàn khó khăn, nhưng chính trong quá trình liên tục thử sức ấy, anh đã cảm nhận được sâu sắc sức mạnh từ sự đồng hành của người thân và bạn bè. Cuối cùng, với thái độ sống lạc quan, anh đã thực hiện được ước mơ của mình.</p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Quách Kính Phi","avatar":""},{"name":"Vương Giai Giai","avatar":""},{"name":"Trần Minh Hạo","avatar":""},{"name":"Trương Hâm Nghệ","avatar":""},{"name":"Lưu Dịch Thiết","avatar":""},{"name":"Lưu Bội Kỳ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["老舅"]', 1784690324138);
