INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ong-cau-cua-toi', 'Ông Cậu Của Tôi', 'Uncle', 'ông cậu của tôi uncle quách kính phi vương giai giai trần minh hạo trương hâm nghệ lưu dịch thiết lưu bội kỳ 老舅', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-tuong-uc-dang-da-vi-uong', 'Trường Tương Ức: Đăng Dã Vị Ương', 'Phoenix''s Homecoming', 'https://phimimg.com/upload/vod/20251219-1/ba9b3ae7bbb10bb19be36153c209947c.jpg', 'https://phimimg.com/upload/vod/20251219-1/afdb9f91b3eafea3384a48cad0167f15.jpg', '<p>Vốn là Trưởng công chúa quyền nghiêng thiên hạ, nhưng lại bị chính người yêu thương nhất là Thái phó và Hoàng đệ phản bội, thiêu chết trong biển lửa. Trở về từ tro tàn, Thái phó – &quot;ánh trăng sáng&quot; năm nào – giờ đây phải quỳ dưới chân cô làm hạ thần, hoàng tử nước địch tình nguyện trở thành lưỡi đao trong bóng tối cho cô sai khiến. Đối mặt với Hoàng hậu vốn coi mình là kẻ thù định mệnh, thứ cô muốn giành lại đâu chỉ có giang sơn! Thuở trước dùng tình làm quân cờ, nay lấy quyền làm ván cục, yêu hận thấu trời sẽ là món quà cho ngày cô lên ngôi!</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Kim Tử Tuyền","avatar":""},{"name":"Phan Nghi Hồng","avatar":""},{"name":"La Mại Nhất","avatar":""},{"name":"Trương Tử Tân","avatar":""},{"name":"Lý Mộ Vũ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Ben Gong Jin Ri Bu Yi Qing","长相忆","本宫今日不宜卿","Zhang Xiang Yi Zhi Deng Ye Wei Yang","长相忆之灯冶未央"]', 1784690324138);
