INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-nhan-guong-mat-doi-tra', 'Hoang Nhan (Gương Mặt Dối Trá)', 'Under The Surface', 'https://phimimg.com/upload/vod/20251214-1/2b7ec8e7b673e95b608a065660228b1a.jpg', 'https://phimimg.com/upload/vod/20251214-1/36ba9a4e523377bf0e3cacdb26aa42a8.jpg', '<p>Lãnh Tiêu Tiêu đổ hết mọi tội lỗi về sự phá sản của gia đình lên người chồng cũ Hướng Dương. Cô đã lợi dụng lòng tốt của cô bạn thân Tạ Vũ Hiên, sử dụng việc phẫu thuật thẩm mỹ làm công cụ để dệt nên một kế hoạch trả thù.Trong quá trình thực hiện, cô gặp phải nhiều sự cản trở khác nhau. Tạ Vũ Hiên lương thiện dần dần khám phá ra con người thật của Hướng Dương, thậm chí còn nảy sinh tình cảm với anh.Cuối cùng, kế hoạch trả thù bị phá sản, nhưng mỗi người trong số họ đều tìm thấy được sự cứu rỗi cho riêng mình...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Cửu Lâm","avatar":""},{"name":"Triệu Tân","avatar":""},{"name":"Ân Kinh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["谎颜"]', 1784690324139);
