INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-tu-phia-sau-vet-mau', 'Thám Tử Tư: Phía Sau Vết Máu', 'Behind The Shadows', 'https://phimimg.com/upload/vod/20250730-1/1c08e70a5ab3ee188a4dda684c1f69ef.jpg', 'https://phimimg.com/upload/vod/20250730-1/72a6cd0683cb5a541328e1cc7e5fbbcf.jpg', '<p>5 vụ án mạng rúng động, một &quot;trò chơi&quot; sinh tử đầy uẩn khúc - và Cổ Thiên Lạc, trong vai thám tử tư, vô tình bị cuốn vào vòng xoáy kinh hoàng đó. Bí ẩn nối tiếp bí ẩn, ai sẽ là con mồi, ai mới là kẻ săn? Câu trả lời đang chờ được hé lộ…</p>', 'Full', 1, 'single', 'completed', 28, 2025, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Cổ Thiên Lạc","avatar":""},{"name":"Lưu Quản Đình","avatar":""},{"name":"Chu Tử Na","avatar":""},{"name":"Vương Hạo Ân","avatar":""},{"name":"Vương Du Mi","avatar":""},{"name":"Dương Ni Tri Âm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["尾隨","Behind The Shadows","私家偵探"]', 1784690324139);
