INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghi-luc-chay-bong-tai-sinh-ruc-lua', 'Nghị Lực Cháy Bỏng (Tái Sinh Rực Lửa)', 'Soul On Fire', 'https://phimimg.com/upload/vod/20251116-1/cfce6760318f12bf3c7c1ac96cbd00dd.jpg', 'https://phimimg.com/upload/vod/20251116-1/48fdff52b846f60cca103cad85abb9ca.jpg', '<p>Từ thảm kịch thổi bùng nghị lực sống, cậu bé vùng dậy nhờ tình thân, niềm tin và cả một thành phố đứng sau lưng. Một hành trình chứng minh rằng phép màu có thật, khi cả cộng đồng cùng nâng đỡ.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Joel Courtney","avatar":""},{"name":"William H. Macy","avatar":""},{"name":"John Corbett","avatar":""},{"name":"DeVon Franklin","avatar":""},{"name":"Stephanie Szostak","avatar":""},{"name":"Masey McLain","avatar":""},{"name":"Natalie Buck","avatar":""},{"name":"James McCracken","avatar":""},{"name":"Erik Audé","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["On Fire","Suflet în flăcări","Soul on Fire"]', 1784690324139);
