INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-sinh-doi-mang', 'Song Sinh Đổi Mạng', 'Paradise', 'https://phimimg.com/upload/vod/20251227-1/19fba9f6d2a3bd7ac963339c8ee53abe.jpg', 'https://phimimg.com/upload/vod/20251227-1/6a368fb601160f561b1d519b11bc54dc.jpg', '<p>&quot;Chẳng lẽ tất cả chúng ta không thể cùng nhau chung sống hay sao?&quot; Đó là một mong ước tốt đẹp, nhưng đối với hai anh em sinh đôi Il-do và Yi-do, điều đó chỉ là suy nghĩ hão huyền. Mang trong mình lời nguyền nghiệt ngã do tội lỗi của cha mẹ để lại, một trong hai người phải chết thì người kia mới có thể tồn tại. Để tránh khỏi định mệnh này, họ đã chủ động cắt đứt mọi liên lạc. Thế nhưng, khi Yi-do — người đang làm việc cho một băng đảng — bị đâm trọng thương, Il-do bằng cách nào đó đã hay tin và vội vã đến hiến máu để cứu sống em trai mình. Vậy mà, thay vì lòng biết ơn, Yi-do đã lao vào tấn công anh trai ngay khoảnh khắc họ vừa chạm mặt.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Jung-pyo","avatar":""},{"name":"Lee Ho-won","avatar":""},{"name":"Jeong Min-sung","avatar":""},{"name":"Hwang Seok-jeong","avatar":""},{"name":"An So-jin","avatar":""},{"name":"Lee Jae-gu","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["천국","천국은 없다"]', 1784690324139);
