INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muon-ruou-day-keo', 'Mượn Rượu Đẩy Kèo', 'Big Deal', 'https://phimimg.com/upload/vod/20250705-1/5b6e58fdecc706d206b932f6801ca845.jpg', 'https://phimimg.com/upload/vod/20250705-1/fcfca0887f26ade9f95dc528d86472d1.jpg', '<p>Mượn Rượu Đẩy Kèo lấy bối cảnh Hàn Quốc vào năm 1997, khi cuộc khủng hoảng kinh tế tài chính đang hoành hành khắp châu Á khiến Gukbo - công ty sản xuất Soju số 1 đất nước rơi vào tình trạng cận kề phá sản. In-beom (Lee Je-hoon) - chàng trai trẻ đầy tham vọng đại diện cho tập đoàn đầu tư toàn cầu Solquin đã trở về quê hương với quyết tâm thâu tóm Gukbo. Để thực hiện âm mưu này, In-beom đội lốt một chuyên gia tư vấn ngây thơ, tiếp cận Jong-rok (Yoo Hai-jin) - giám đốc vô cùng trung thành với Gukbo, đang khao khát đưa công ty quay lại thời hoàng kim. Nhưng càng đào sâu vào đế chế Gukbo, In-beom càng nhận ra đây thực sự là một cuộc chiến xảo quyệt với rất nhiều “cú twist”, dẫn đến kết cục không ngờ dành cho tất cả.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Hàn Quốc', 1, '[{"name":"Yoo Hai-jin","avatar":""},{"name":"Lee Je-hoon","avatar":""},{"name":"Son Hyun-joo","avatar":""},{"name":"Choi Young-jun","avatar":""},{"name":"Byron Mann","avatar":""},{"name":"Kim Ki-hae","avatar":""},{"name":"Yoon Ji-hye","avatar":""},{"name":"Stefanie Michova","avatar":""},{"name":"Lee Seo-hwan","avatar":""},{"name":"Lee Chang-ho","avatar":""},{"name":"Park Ji-il","avatar":""},{"name":"Kim Da-huin","avatar":""},{"name":"Jung Hyung-suk","avatar":""},{"name":"Sim Woo-sung","avatar":""},{"name":"Choi Hee-jin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca59