INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-trung-gian-mat-lenh-ke-moi-gioi', 'Người Trung Gian (Mật Lệnh Kẻ Môi Giới)', 'Relay', 'https://phimimg.com/upload/vod/20250921-1/77c4a2cf47a3fa97f9c42b26e080b108.jpg', 'https://phimimg.com/upload/vod/20250921-1/b51d611d6c293f4a9773e68d9470a5cd.jpg', '<p>Tom — một “người trung gian” đẳng cấp quốc tế — chuyên dàn xếp những khoản tiền bịt miệng béo bở giữa các tập đoàn tham nhũng và những cá nhân đe dọa sẽ phơi bày họ. Anh luôn giấu kín danh tính bằng sự chuẩn bị kỹ lưỡng và một bộ quy tắc nghiêm ngặt. Nhưng khi nhận được tin nhắn từ Sarah — một khách hàng tiềm năng đang cần anh bảo vệ mạng sống — những quy tắc của Tom bắt đầu dần bị phá vỡ.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Riz Ahmed","avatar":""},{"name":"Lily James","avatar":""},{"name":"Sam Worthington","avatar":""},{"name":"Willa Fitzgerald","avatar":""},{"name":"Jared Abrahamson","avatar":""},{"name":"Pun Bandhu","avatar":""},{"name":"Eisa Davis","avatar":""},{"name":"Matthew Maher","avatar":""},{"name":"Seth Barrish","avatar":""},{"name":"Victor Garber","avatar":""},{"name":"Reed Northrup","avatar":""},{"name":"Aaron Roman Weiner","avatar":""},{"name":"Jessica Garza","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["L''intermédiaire","传话人","转达","紐約暗煞","รหัสลับซ่อนตาย","릴레이","玩命中繼站","Relay"]', 1784690324139);
