INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('elway', 'Elway', 'Elway', 'https://phimimg.com/upload/vod/20251227-1/2fd0aa687102fe58abf8511d32969107.jpg', 'https://phimimg.com/upload/vod/20251227-1/a1ad992c766dace69857e5f1271636c6.jpg', '<p>Được kể lại qua lời tự thuật của chính nhân vật chính, đây là câu chuyện chân thực nhất về John Elway – tiền vệ huyền thoại của đội Denver Broncos. Bộ phim đi sâu vào những giấc mơ chinh phục NFL, những nỗi đau thắt lòng và hành trình tìm lại vinh quang đầy cảm xúc tại Super Bowl.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"John Elway","avatar":""},{"name":"Adam Schefter","avatar":""},{"name":"Terrell Davis","avatar":""},{"name":"Mike Shanahan","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Elway"]', 1784690324139);
