INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('so-canh-sat-boston', 'Sở Cảnh Sát Boston', 'Boston Blue', 'https://phimimg.com/upload/vod/20251020-1/a1cc1afd5d4a676abb2de33ac3f9ca1c.jpg', 'https://phimimg.com/upload/vod/20251020-1/d85bf3532a2fa3e7abe27d413c3d5a21.jpg', '<p>Thanh tra Danny Reagan của Sở Cảnh sát New York (NYPD) chuyển sang làm việc cho Sở Cảnh sát Boston (BPD) và được phân công hợp tác với Thanh tra Lena Silver, thành viên của một gia đình có truyền thống làm trong ngành luật: Công tố viên Mae Silver, Cảnh sát trưởng Sarah Silver, tân binh Jonah Silver, và Mục sư Edwin Peters. Trong khi bắt đầu công việc mới, Reagan cũng hy vọng có thể hàn gắn mối quan hệ với con trai mình, Sean, hiện đang sống tại Boston.</p>', 'Tập 9', 12, 'series', 'ongoing', 10, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Donnie Wahlberg","avatar":""},{"name":"Sonequa Martin-Green","avatar":""},{"name":"Ernie Hudson","avatar":""},{"name":"Maggie Lawson","avatar":""},{"name":"Gloria Reuben","avatar":""},{"name":"Marcus Scribner","avatar":""},{"name":"Mika Amonsen","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jamaica Plain","Boston Blue"]', 1784690324139);
