INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyet-quy-hon-chien', 'Huyết Quỷ Hỗn Chiến', 'Tougen Anki', 'https://phimimg.com/upload/vod/20250713-1/a079fb1c44f1bfb42f7eb0a01a2acb15.jpg', 'https://phimimg.com/upload/vod/20250713-1/2c3c7db71c2ff172083e8e0c77768f8a.jpg', '<p>Rất lâu sau khi Momotaro huyền thoại chiến đấu với Oni, một thiếu niên nổi loạn phát hiện ra cuộc xung đột vẫn chưa kết thúc — và dòng máu nguy hiểm vẫn chảy trong huyết quản cậu.</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 161, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kazuki Ura","avatar":""},{"name":"Hiroshi Kamiya","avatar":""},{"name":"Koutaro Nishiyama","avatar":""},{"name":"Manaka Iwami","avatar":""},{"name":"Shogo Sakata","avatar":""},{"name":"Natsuki Hanae","avatar":""},{"name":"Kaito Miura","avatar":""},{"name":"Aimi","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Tōgen Anki","桃源暗記 極楽の闇魔","Tougen Anki","Тёмный демон","Tougen Anki: Dark Demon of Paradise","Demon’s Shangri-La","Demon’s Arcadia","Demon’s Utopia","Togen Demon","Togen Memorization","Togen Memorization: Dark Demon of Paradise","Togen Memorization: Legend of the Cursed Blood","桃源暗鬼"]', 1784690324139);
