INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('huyet-quy-hon-chien', 'Huyết Quỷ Hỗn Chiến', 'Tougen Anki', 'huyết quỷ hỗn chiến tougen anki kazuki ura hiroshi kamiya koutaro nishiyama manaka iwami shogo sakata natsuki hanae kaito miura aimi tōgen anki 桃源暗記 極楽の闇魔 tougen anki тёмный демон tougen anki: dark demon of paradise demon’s shangri-la demon’s arcadia demon’s utopia togen demon togen memorization togen memorization: dark demon of paradise togen memorization: legend of the cursed blood 桃源暗鬼', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-tro-bach-quy-kakuriyo-no-yadomeshi-phan-2', 'Quán Trọ Bách Quỷ (Kakuriyo no Yadomeshi) (Phần 2)', 'Kakuriyo: Bed & Breakfast For Spirits (Season 2)', 'https://phimimg.com/upload/vod/20251002-1/4dc4bb5afe268d9371a018ce7ca77038.jpg', 'https://phimimg.com/upload/vod/20251002-1/efca6d6d58e7a111c2e6a39446e9f4c0.jpg', '<p>Series xoay quanh một cô sinh viên tên là Aoi. Cô đã được thừa hưởng từ người ông quá cố của mình năng lực thấy được linh hồn. Không những thế, cô còn là một nữ công gia chánh chính hiệu với tài nghệ nấu bếp siêu hạng. Một ngày nọ, Aoi bị một vị thần và cũng là chủ của nhà trọ Tenshinya bắt cóc. Hắn ta nói rằng vì món nợ của ông cô, cô phải trở thành vợ của hắn. Đương nhiên Aoi không hề chấp nhận điều này, và cô quyết định sẽ trả món nợ thay ông mình bằng cách làm việc tại Tenshiya.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 161, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Kakuriyo no Yadomeshi","かくりよの宿飯 弐","Kakuriyo no Yadomeshi Ni","かくりよの宿飯第２期","Чем кормят в ином мире","妖怪旅館營業中 貳","Kakuriyo -Bed & Breakfast for Spirits- 2","かくりよの宿飯"]', 1784690324139);
