INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-the-ngan-tinh', 'Chẳng Thể Ngăn Tình', 'Player (UNCUT)', 'https://phimimg.com/upload/vod/20251004-1/b20c4cb37c21978e8207e133a5f610be.jpg', 'https://phimimg.com/upload/vod/20251004-1/08b94804fa26d4902eb3dc01f8a8c8ba.jpg', '<p>“Pun” – Một cô gái trẻ sang Mỹ với hy vọng định cư tại đó, đã thuê một người đàn ông để kết hôn giả. Thế nhưng, cô bị phản bội khi hắn ta trốn mất cùng số tiền 1 triệu baht mà cô trả. Giờ đây, khi bị các băng nhóm mafia bí ẩn truy đuổi, Pun buộc phải trở về Thái Lan và truy tìm kẻ phản bội để tìm câu trả lời.Pun phải moi thông tin từ “Ploy” – nữ diễn viên phản diện xinh đẹp của làng giải trí Thái Lan, cũng chính là em gái của kẻ đã lừa cô. Hy vọng rằng sự gần gũi sẽ khiến Ploy tiết lộ bí mật về anh trai mình, Pun bắt đầu một nhiệm vụ đầy quyến rũ và đớn đau. Nhưng càng giả vờ khiến Ploy yêu mình, Pun lại càng sa vào lưới tình thật sự. Càng giăng bẫy, cô lại càng bị mắc kẹt trong chính cảm xúc của mình.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Muanfun Baesakul","avatar":""},{"name":"Grace Harper","avatar":""},{"name":"Amena Gul","avatar":""},{"name":"Marika Paekiatchalorn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Player: Unstoppable Love","Player ไม่อาจห้ามรัก"]', 1784690324139);
