INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-tien-mat', 'Anh Hùng Tiền Mặt', 'Cashero', 'https://phimimg.com/upload/vod/20251226-1/9e3906a7c3e3be25cd0c494d3a7e0968.jpg', 'https://phimimg.com/upload/vod/20251226-1/2c8f6e0fff520fbe77bbdb731cf81f46.jpg', '<p>Một người đàn ông bình thường thừa hưởng siêu năng lực rồi phát hiện một thế lực hiểm ác đang tìm cách cướp sức mạnh đó. Nhưng mỗi lần anh ra tay là tiền bay khỏi ví.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 14, 2025, 'Vietsub + Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Jun-ho","avatar":""},{"name":"Kim Hye-jun","avatar":""},{"name":"Kim Byong-chul","avatar":""},{"name":"Kim Hyang-gi","avatar":""},{"name":"Kang Hanna","avatar":""},{"name":"Lee Chae-min","avatar":""},{"name":"Jang Hyun-sung","avatar":""},{"name":"Cha Si-won","avatar":""},{"name":"Shin Su-hyun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ca$hero","金钱侠","قهرمان نقدی","Денежный герой","캐셔로"]', 1784690324139);
