INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-luc-moi-noi-phan-3', 'Mọi Lúc Mọi Nơi (Phần 3)', 'Whenever Possible (Season 3)', 'https://phimimg.com/upload/vod/20251226-1/7971ad91a187a69cbc9f4f49aa774560.jpg', 'https://phimimg.com/upload/vod/20251226-1/e5bfe2e3751ca2fb38919173590566a0.jpg', '<p>&quot;Whenever Possible&quot; là chương trình tạp kỹ nơi các MC Yoo Jae Suk và Yoo Yeon Seok đến thăm những người bình thường trong những khoảnh khắc rảnh rỗi ngắn ngủi của họ, với mong muốn mang đến một chút may mắn cho cuộc sống của họ. Chương trình là sự hợp tác giữa PD Choi Bo Pil của &quot; Running Man &quot; và biên kịch Chae Jin Ah của &quot;Siren: Survive the Island&quot;.</p>', 'Hoàn Tất (15/15)', 15, 'tvshows', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yoo Jae-suk","avatar":""},{"name":"Yoo Yeon-seok","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Kapanpun memungkinkan.","틈만나면,","틈만 나면,","Whenever Possible","只要有空，"]', 1784690324139);
