INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tue-tue-hieu-long-toi', 'Tuế Tuế Hiểu Lòng Tôi', 'More Than I Can Say', 'https://phimimg.com/upload/vod/20251226-1/1ff8a3d7883386997425255bf22b600c.jpg', 'https://phimimg.com/upload/vod/20251226-1/4da446b8ad5584214a813bb802c7bccc.jpg', '<p>Bộ phim kể về Trần Chi Ý, một học đồ Kinh kịch, nhờ mối duyên với hí khúc mà gặp gỡ Nguyễn Tuế Khanh — con trai của chủ một tòa soạn báo có tiếng tại địa phương. Sau đó, cô phải trải qua hàng loạt thăng trầm từ sự lụi tàn của gánh hát cho đến những cuộc sinh ly tử biệt với những người thân yêu nhất. Sự tàn khốc của số phận và những biến động của thời đại đã khiến Trần Chi Ý phải đấu tranh để lột xác. Cho đến khi thực sự thức tỉnh, cô đã cùng Nguyễn Tuế Khanh sát cánh chống lại cái ác. Cuối cùng, Trần Chi Ý trở thành nữ bầu gánh (Ban chủ) đầu tiên của Hải Thành, nỗ lực gìn giữ và phát huy tinh hoa văn hóa hí khúc.</p>', 'Tập 21', 38, 'series', 'ongoing', 13, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Hy Quân","avatar":""},{"name":"Khương Chi Nam","avatar":""},{"name":"Trát Kiệt","avatar":""},{"name":"Lưu Hạo Vũ","avatar":""},{"name":"Vương Tử Tô","avatar":""},{"name":"Trịnh Anh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["岁岁知我意"]', 1784690324139);
