INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tue-tue-hieu-long-toi', 'Tuế Tuế Hiểu Lòng Tôi', 'More Than I Can Say', 'tuế tuế hiểu lòng tôi more than i can say trần hy quân khương chi nam trát kiệt lưu hạo vũ vương tử tô trịnh anh 岁岁知我意', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('wandance', 'Wandance', 'Wandance', 'https://phimimg.com/upload/vod/20251009-1/9323088bf09e6f07c6e04d8027f4a4dd.jpg', 'https://phimimg.com/upload/vod/20251009-1/d276acbb72f852571e6f83e41cd5f4ae.jpg', '<p>Kaboku luôn sống thuận theo dòng đời — bước đi đều đặn theo nhịp trống của những kỳ vọng đến từ cha mẹ, nhà trường và cả kế hoạch tương lai. Cuộc sống ấy có vẻ an toàn, ổn định… nhưng trống rỗng. Cho đến một đêm, khi ở lại trường muộn, Kaboku tình cờ bắt gặp một cô gái đang một mình nhảy múa điên cuồng, biến khoảng sân bê tông trống trải thành một bức tranh sống động. Đó là Hikari Wanda, thành viên của câu lạc bộ nhảy hip-hop. Ngay khoảnh khắc ấy, Kaboku bị cuốn hút hoàn toàn. Thế nhưng con đường để cậu bước ra khỏi vỏ bọc của chính mình không hề dễ dàng — câu lạc bộ hầu như toàn là con gái, và ai cũng… giỏi hơn cậu rất nhiều. Phía trước là điều chưa biết, đáng sợ, nhưng đồng thời, lần đầu tiên trong đời Kaboku cảm nhận được hương vị của tự do.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Koki Uchiyama","avatar":""},{"name":"Hina Youmiya","avatar":""},{"name":"Ayaka Suwa","avatar":""},{"name":"Toshiki Masuda","avatar":""},{"name":"Yuma Uchida","avatar":""},{"name":"Yuu Hayashi","avatar":""},{"name":"Chikahiro Kobayashi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["WonDance","Wandance The Animation","Wandansu","WONDANCE—熱舞青春—","ワンダンス"]', 1784690324139);
