INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuong-lan-quyet-ban-hoat-hinh-phan-2', 'Thương Lan Quyết (Bản Hoạt Hình) (Phần 2)', 'Love Between Fairy And Devil (Season 2)', 'https://phimimg.com/upload/vod/20250803-1/eb1dd7e0cd1e718b8bade0327b81df47.jpg', 'https://phimimg.com/upload/vod/20250803-1/124d7fa9873b76aa5fe7c33d0ea89ff2.jpg', '<p>Sau đại chiến long trời lở đất, Đông Phương Thanh Thương trở về biển Thương Viêm, nhưng không ngờ lại rơi vào cái bẫy đã được giăng sẵn của quân sư Khổng Tước. Sóng gió chưa kịp lắng xuống, một biến cố khác lại ập đến. Ở bên kia, Chiến thần Xích Địa liên tục xuất hiện trong những giấc mơ của Tiểu Lan Hoa. Ẩn ý phía sau là gì? Hành trình “oan gia” giữa Đông Phương và Tiểu Lan Hoa mới đi được nửa chặng thì Ảnh Tam Giới - một thế lực thần bí nằm ngoài Tam giới – bắt đầu bước ra ánh sáng, và một bí mật to lớn vốn bị chôn vùi từ lâu dần hé lộ...</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 241, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ajie","avatar":""},{"name":"Nie Xiying","avatar":""},{"name":"Yang Tianxiang","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["苍兰诀动画版","Cang Lan Jue","蒼蘭訣","Love Between Fairy and Devil","Love Between Fairy and Devil (Animation)","苍兰诀"]', 1784690324139);
