INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-mien-bao-thu', 'Thôi Miên Báo Thù', 'Hypnotic', 'https://phimimg.com/upload/vod/20251106-1/de6ecf597a8f83c534483c48894950b7.jpg', 'https://phimimg.com/upload/vod/20251106-1/b3667456ebb14e1df4b58f4dcecb751f.jpg', '<p>Ôm trong mình một nỗi căm hận khôn nguôi từ khi còn bé, chuyên gia tâm lý trẻ em Sara từ lâu đã ấp ủ kế hoạch Thôi Miên Báo Thù. Trầm lặng và khép kín, cô luôn che giấu mọi cảm xúc thật sau vẻ bình thản, khó đoán. Cô tìm cách tiếp cận gia đình của kẻ thù rồi sử dụng thuật thôi miên và thao túng tâm lý để từng bước đẩy họ vào vòng xoáy ám ảnh, sợ hãi và cả sự thật khốc liệt nhất.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 14, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Nuttanicha Dungwattanawanich","avatar":""},{"name":"Norraphat Vilaiphan","avatar":""},{"name":"Wannarot Sonthichai","avatar":""},{"name":"Petch Boranin","avatar":""},{"name":"Phutanate Hongmanop","avatar":""},{"name":"Maprang Alrisa Kunkwaeng","avatar":""},{"name":"Chawallakorn Wanthanapisitkul","avatar":""},{"name":"Penpak Sirikul","avatar":""},{"name":"Cindy Sirinya Bishop","avatar":""},{"name":"Iang Sittha Sapanuchart","avatar":""},{"name":"Nutthacha Padovan","avatar":""},{"name":"Meepooh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["จิตสะกดแค้น"]', 1784690324139);
