INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ke-kieu-hung', 'Những Kẻ Kiêu Hùng', 'The Mighty Nein', 'https://phimimg.com/upload/vod/20251126-1/9eb3bf7cbf4e8172e18a0f870908a0ac.jpg', 'https://phimimg.com/upload/vod/20251126-1/555cd3096915041631dd80132a13bf1a.jpg', '<p>“Ngọn Hải Đăng” bị đánh cắp. Thực tại lung lay. Một nhóm kẻ trốn chạy mang đầy bí mật phải đứng cùng nhau, hoặc chứng kiến cả thế giới tan rã. Một cuộc phiêu lưu kỳ ảo nơi số phận được viết lại bởi những kẻ không ai tin tưởng.</p>', 'Hoàn Tất (8/8)', 8, 'hoathinh', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Laura Bailey","avatar":""},{"name":"Marisha Ray","avatar":""},{"name":"Liam O''Brien","avatar":""},{"name":"Ashley Johnson","avatar":""},{"name":"Taliesin Jaffe","avatar":""},{"name":"Sam Riegel","avatar":""},{"name":"Travis Willingham","avatar":""},{"name":"Matthew Mercer","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["九巨头","Potężna Dziewiątka","Майти Найн","Mighty Nein","Critical Role: The Mighty Nein","The Mighty Nein"]', 1784690324139);
