INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-con-quai-vat-muon-an-thit-toi', 'Một Con Quái Vật Muốn Ăn Thịt Tôi', 'This Monster Wants To Eat Me', 'https://phimimg.com/upload/vod/20251003-1/8c2a0eeb404b6ca6b529e63c105b2990.jpg', 'https://phimimg.com/upload/vod/20251003-1/d878c6fa77d729178c60f5ce89a12fa2.jpg', '<p>Hinako sống một mình bên bờ biển, lặng lẽ trôi qua những ngày tháng sau khi mất đi gia đình nhiều năm trước. Một ngày nọ, một nàng tiên cá tên Shiori cứu cô khỏi quái vật và nói rằng mình đến để ăn thịt cô — nhưng chưa phải lúc này. Cho đến khi ấy, Shiori sẽ ở bên cạnh và bảo vệ cô. Khoảnh khắc đó, trong Hinako dâng lên một niềm hy vọng sâu thẳm: Có lẽ cô gái này cuối cùng có thể mang đến cho cô kết thúc mà cô vẫn hằng chờ đợi.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Reina Ueda","avatar":""},{"name":"Yui Ishikawa","avatar":""},{"name":"Fairouz Ai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["对我垂涎欲滴的非人少女","Watashi wo tabetai, Hitodenashi","Watashi o Tabetai, Hito de nashi","わたたべ","WataTabe","對我垂涎欲滴的非人少女","私を喰べたい、ひとでなし"]', 1784690324139);
