INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-than-tham-doc', 'Bạn Thân Thâm Độc', 'Friendshit Forever', 'https://phimimg.com/upload/vod/20251105-1/0ebe5c14c740fa33b1f8befd19e7231b.jpg', 'https://phimimg.com/upload/vod/20251105-1/342332873a0afc7f75122a213aabbd97.jpg', '<p>Nhìn bề ngoài, Tulip và Baikhao có vẻ là đôi bạn vô cùng thân thiết, nhưng ít ai biết rằng giữa họ lại có một mối nợ máu. Bố của Tulip chính là kẻ đã khiến gia đình Baikhao tan nhà nát cửa: cha tự sát, mẹ hóa điên, em gái chết trong bụng mẹ. Baikhao chưa từng xem Tulip là bạn mà chỉ muốn lợi dụng cô để trả thù cho người thân của mình. Tulip sẽ phản ứng thế nào khi biết được sự thật về người Bạn Thân Thâm Độc của mình? Giữa tình bạn giả dối và những âm mưu nhuốm máu, liệu họ có thể thoát khỏi bi kịch?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 10, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Chayanit Chansangavej","avatar":""},{"name":"Thasorn Klinnium","avatar":""},{"name":"Thitipoom Techa-apaikhun","avatar":""},{"name":"Noppanut Guntachai","avatar":""},{"name":"Arisara Wongchalee","avatar":""},{"name":"Juthapich Indrajundra","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324139);
