INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-viking-cuoi-cung', 'Người Viking Cuối Cùng', 'The Last Viking', 'https://phimimg.com/upload/vod/20251226-1/b543e04f11d1372374798ef7e4317530.jpg', 'https://phimimg.com/upload/vod/20251226-1/ca69846fabb2ab6464afc903789e8c20.jpg', '<p>Sau mười bốn năm thụ án vì tội cướp, Anker được trả tự do và đoàn tụ với người em trai mắc bệnh tâm thần, Manfred, kẻ duy nhất biết số tiền bị đánh cắp được giấu ở đâu nhưng lại quên mất vị trí. Điều đó đẩy hai anh em vào một hành trình truy tìm chiến lợi phẩm, đồng thời buộc họ phải đối diện với chính con người mình.</p>', 'Full', 1, 'single', 'completed', 29, 2025, 'Vietsub', 'FHD', 'Đan Mạch', 0, '[{"name":"Mads Mikkelsen","avatar":""},{"name":"Nikolaj Lie Kaas","avatar":""},{"name":"Sofie Gråbøl","avatar":""},{"name":"Bodil Jørgensen","avatar":""},{"name":"Lars Brygmann","avatar":""},{"name":"Nicolas Bro","avatar":""},{"name":"Søren Malling","avatar":""},{"name":"Kardo Razzazi","avatar":""},{"name":"Lars Ranthe","avatar":""},{"name":"Anette Støvelbæk","avatar":""},{"name":"Rikke Louise Andersson","avatar":""},{"name":"Nomi Bodnia","avatar":""},{"name":"Alfred Røssel Læsø","avatar":""},{"name":"Torben Svendsen","avatar":""},{"name":"Susanne Breuning","avatar":""},{"name":"Klaus Til","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Back to Reality","Pēdējais vikings","The Last Viking","Poslední viking","Therapie für Wikinger","Den sidste viking"]', 1784690324139);
