INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-uc-truy-hanh', 'Ký Ức Truy Hành', 'The Things You Kill', 'https://phimimg.com/upload/vod/20251226-1/ab5280b425f4e259c9bca50266096cb0.jpg', 'https://phimimg.com/upload/vod/20251226-1/f5f958e94b5556da1d42d24f23ebae8d.jpg', '<p>Một giáo sư đại học điều tra cái chết đáng ngờ của mẹ mình, đồng hành cùng người làm vườn bí ẩn. Cuộc truy tìm sự thật kéo họ vào những ký ức méo mó và bí mật gia đình, dẫn đến sự đối mặt tàn khốc với bóng tối nội tâm.</p>', 'Full', 1, 'single', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Ekin Koç","avatar":""},{"name":"Erkan Kolçak Köstendil","avatar":""},{"name":"Hazar Ergüçlü","avatar":""},{"name":"Selen Kurtaran","avatar":""},{"name":"İdil Engindeniz","avatar":""},{"name":"Ercan Kesal","avatar":""},{"name":"Güliz Şirinyan","avatar":""},{"name":"Aysan Sümercan","avatar":""},{"name":"Doğa Dörtdoğan","avatar":""},{"name":"Serhat Nalbantoğlu","avatar":""},{"name":"İpek Türktan","avatar":""},{"name":"Sertan Müsellim","avatar":""},{"name":"Mert Karacabey","avatar":""},{"name":"Onur Tanyeri","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["你杀死的东西","Öldürdüyün Şeylər","Öldürdüğün Şeyler"]', 1784690324139);
