INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ky-uc-truy-hanh', 'Ký Ức Truy Hành', 'The Things You Kill', 'ký ức truy hành the things you kill ekin koç erkan kolçak köstendil hazar ergüçlü selen kurtaran i̇dil engindeniz ercan kesal güliz şirinyan aysan sümercan doğa dörtdoğan serhat nalbantoğlu i̇pek türktan sertan müsellim mert karacabey onur tanyeri 你杀死的东西 öldürdüyün şeylər öldürdüğün şeyler', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('366-ngay', '366 Ngày', '366 Days', 'https://phimimg.com/upload/vod/20251226-1/6c8c4dd7e4ae99bd080e1d908b39ba64.jpg', 'https://phimimg.com/upload/vod/20251226-1/c5ba6b32fac5c2a890b4dbf4ca78b7f5.jpg', '<p>Năm 2003, Miu — một nữ sinh trung học ở Okinawa — bắt đầu để ý đến Minato, đàn anh vừa mất cả cha lẫn mẹ. Để động viên anh, cô cùng anh trao đổi những băng nhạc mix trên MiniDisc. Khi Minato tốt nghiệp và chuyển lên Tokyo, họ bước vào mối quan hệ yêu xa, và sau đó Miu cũng lên Tokyo học đại học để ở bên anh. Vài năm sau, trong lúc Miu chật vật tìm việc, Minato bất ngờ chia tay cô, khiến Miu quay về Okinawa. Mười lăm năm trôi qua, vào năm 2024, Miu đã kết hôn với người bạn thanh mai trúc mã Ryusei và đang mang bệnh nan y. Con gái cô, Himari, được gửi đến Tokyo để trao một thông điệp được lưu trong chiếc MiniDisc cho người đàn ông mà mẹ cô từng yêu.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Eiji Akaso","avatar":""},{"name":"Moka Kamishiraishi","avatar":""},{"name":"Yuto Nakajima","avatar":""},{"name":"Tina Tamashiro","avatar":""},{"name":"Junpei Mizobata","avatar":""},{"name":"Kurumi Inagaki","avatar":""},{"name":"Jun Saito","avatar":""},{"name":"Ryoko Kuninaka","avatar":""},{"name":"Hikari Ishida","avatar":""},{"name":"Tetta Sugimoto","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["366 วัน","366⽇"]', 1784690324139);
