INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('366-ngay', '366 Ngày', '366 Days', '366 ngày 366 days eiji akaso moka kamishiraishi yuto nakajima tina tamashiro junpei mizobata kurumi inagaki jun saito ryoko kuninaka hikari ishida tetta sugimoto 366 วัน 366⽇', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xa-thu-kich-chien', 'Xạ Thủ: Kích Chiến', 'Sniper Battle', 'https://phimimg.com/upload/vod/20251226-1/f110d9abee7125ae3a243feb6b73a61b.jpg', 'https://phimimg.com/upload/vod/20251226-1/2692eaf68ca57e2aa5fc4f411bcbc6b3.jpg', '<p>Đội lính đánh thuê Cao Chiêm nhận một nhiệm vụ đắt giá - đột nhập khu lừa đảo qua điện thoại Kim Quan Viên, trà trộn vào lực lượng vũ trang của trùm lừa đảo La Lý, nhằm giải cứu thành viên đội đặc vụ Zavrania Trần Nhạc đang hoạt động bí mật. Đội Cao Chiêm gặp mật báo Johnson, cải trang thâm nhập vào khu bếp và thuận lợi giải cứu Trần Nhạc. Thế nhưng trong quá trình rút lui, họ liên tục rơi vào các ổ phục kích và bị đánh chặn dữ dội. Lúc này sự thật mới bị phơi bày: Trần Nhạc thực chất là sát thủ đỉnh cấp mang mật danh “Bóng Ma”, do chính khu lừa đảo thuê đóng giả làm đặc vụ bị giam giữ. Bị “Bóng Ma” thâm nhập nội bộ, đội Cao Chiêm chịu tổn thất nặng nề. Các thành viên Kỹ Sư, Đầu Cua và Bàng Kiếm lần lượt hy sinh. May mắn thay, Cao Chiêm giả chết trốn thoát được. Cuối cùng, anh cứu được mật báo Johnson, giăng bẫy thành công tiêu diệt “Bóng Ma”, hoàn thành nhiệm vụ.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Viên Phúc Phúc","avatar":""},{"name":"Ngụy Lỗ","avatar":""},{"name":"Mã Thiết Mô","avatar":""},{"name":"A Di Hạ","avatar":""},{"name":"Vương Tiêu","avatar":""},{"name":"Trương Tân Minh","avatar":""},{"name":"Tôn Nhất Minh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["저격수: 격전","狙击手：激战"]', 1784690324139);
