INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-da-vinh-ninh', 'Trường Dạ Vĩnh Ninh', 'Long Night Eternal Peace', 'https://phimimg.com/upload/vod/20251226-1/aad48c56bf1c5d61b73a43803312bf2e.jpg', 'https://phimimg.com/upload/vod/20251226-1/7acf23f7c051f18e94ecebdf9cf08317.jpg', '<p>Cảnh sát Ngụy Tư luôn canh cánh trong lòng về vụ án nữ sinh đại học bị sát hại cách đây 15 năm mà anh chưa thể phá giải. Giờ đây, em gái của nạn nhân năm xưa thi đỗ vào chính ngôi trường mà chị mình từng học, với hy vọng tìm thấy manh mối năm đó. Một cảnh sát mới cũng đặc biệt hứng thú với vụ án cũ. Dưới sự tiếp sức của hai thế hệ, chân tướng năm xưa cuối cùng cũng được phơi bày, hung thủ độc ác bị đưa ra trước pháp luật, và vụ án bị chôn vùi 15 năm nay cuối cùng đã được phá giải.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đa Hòa","avatar":""},{"name":"Trần Bân","avatar":""},{"name":"Tôn Lan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["长夜永宁"]', 1784690324139);
