INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-biet-thang-sau', 'Tạm Biệt Tháng Sáu', 'Goodbye June', 'https://phimimg.com/upload/vod/20251226-1/02107db266d8c37cd95377def749fe9f.jpg', 'https://phimimg.com/upload/vod/20251226-1/52ef37114a2338f5f0656a0e717938a1.jpg', '<p>Helen Mirren đóng chính trong vai người mẹ ốm yếu nhưng sắc sảo, tự mình sắp đặt màn từ biệt cuối. Đây là bộ phim đầu tay cảm động của Kate Winslet trong vai trò đạo diễn.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Helen Mirren","avatar":""},{"name":"Kate Winslet","avatar":""},{"name":"Toni Collette","avatar":""},{"name":"Johnny Flynn","avatar":""},{"name":"Andrea Riseborough","avatar":""},{"name":"Timothy Spall","avatar":""},{"name":"Stephen Merchant","avatar":""},{"name":"Fisayo Akinade","avatar":""},{"name":"Jeremy Swift","avatar":""},{"name":"Raza Jaffrey","avatar":""},{"name":"Dan Li","avatar":""},{"name":"Michelle Parker","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["굿바이 준","再见六月","再见妈妈","Goodbye June"]', 1784690324139);
