INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyet-nhiem-phuong-hoang', 'Huyết Nhiễm Phượng Hoàng', 'Bloodstained Phoenix', 'https://phimimg.com/upload/vod/20251225-1/e4496ea599853f9bddea36410df291fe.jpg', 'https://phimimg.com/upload/vod/20251225-1/d0732cc403e6b1baee365486d8cd86df.jpg', '<p>Vào thời Dân Quốc, tướng lĩnh cuối triều Thanh Bành Phi cùng thầy giáo Ba Đặc Lỗ đã dũng cảm quyết chiến với sát thủ ninja Nhật Bản để bảo vệ quốc bảo “Chén Phụng Hoàng Lưu Ly”. Trong quá trình ấy, họ nhận được sự trợ giúp của Lam Thiên Long, Lam Phượng Hoàng, A Tứ cùng nhiều nghĩa sĩ chính trực khác, họ tiêu diệt kẻ thù hùng mạnh và bảo toàn quốc bảo. Cũng qua trận chiến đầy máu lửa này, Bành Phi và các anh hùng giang hồ đã tìm thấy con đường tươi sáng để thực sự cống hiến cho đất nước.</p>', 'Full', 1, 'single', 'completed', 36, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Tuấn Bằng","avatar":""},{"name":"Châu Hạo Đông","avatar":""},{"name":"Vương Cửu Thắng","avatar":""},{"name":"Ôn Đông Tuấn","avatar":""},{"name":"Tô Tư Kinh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bloodstained Phoenix","血染凤凰"]', 1784690324139);
