INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('huyet-nhiem-phuong-hoang', 'Huyết Nhiễm Phượng Hoàng', 'Bloodstained Phoenix', 'huyết nhiễm phượng hoàng bloodstained phoenix vương tuấn bằng châu hạo đông vương cửu thắng ôn đông tuấn tô tư kinh bloodstained phoenix 血染凤凰', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tang-huong-ky', 'Tàng Hương Ký', 'The Glory Of Queen', 'https://phimimg.com/upload/vod/20251219-1/f565e83ee3fa98512b9690a308da3274.jpg', 'https://phimimg.com/upload/vod/20251219-1/6f4d8cacabc8de9c7902a86eca4fc590.jpg', '<p>Tại nước Nguyệt Tôn, nơi có tư tưởng trọng nữ khinh nam và luật thép về quyền thừa kế là &quot;truyền nữ không truyền nam&quot;. Bùi gia là danh gia vọng tộc trăm năm về nghề chế hương, sở hữu một cuốn hương phổ gia truyền vô giá, bao năm qua là thứ mà vô số người khao khát nhưng không thể có được. &quot;Nữ tặc&quot; Tống Tri Dao bị ép phải đến Bùi gia đánh cắp hương phổ, nhưng lại bị Nhị công tử Bùi Cảnh Hành bắt tại trận. Để ngăn bí mật hương phổ lọt ra ngoài, Bùi Cảnh Hành đã ép Tống Tri Dao phải ở lại bên cạnh mình. Sớm tối bên nhau, hai người dần nảy sinh tình cảm. Tống Tri Dao cũng dần nhớ lại ký ức bi thảm về vụ án diệt môn của gia đình mình, đồng thời phát hiện ra nhiều sự thật tàn khốc chưa ai biết đến của Bùi gia. Cuối cùng, cả hai đã cùng nhau hóa giải mọi hiểu lầm.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 10, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Kim Tử Huyền","avatar":""},{"name":"Lý Vũ Hạo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["红袖篆","Cang Xiang Ji","장향기","藏香记"]', 1784690324139);
