INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lech-mui-gio-mot-van-cay-so', 'Lệch Múi Giờ Một Vạn Cây Số', 'Back To The Origin', 'https://phimimg.com/upload/vod/20251202-1/8c52789566c43f3614db0fb13b430059.jpg', 'https://phimimg.com/upload/vod/20251202-1/51465baec63f48f80b8011c5aaf2261b.jpg', '<p>Trương Nhiễm, từng là một MC tài chính, không cam lòng với cuộc sống làm đại lý mua hàng ở nước ngoài nên đã nắm trong tay một lời đề nghị từ công ty MCN (Multi-Channel Network) trong nước, kéo chồng là Phó Ngọc Đông về nước để trở thành một &quot;hot Tiktoker&quot; chuyên về nội dung hài hước.Nào ngờ, người chồng làm thợ trang trí lại đi trước cô một bước, đón đầu xu hướng và trở thành &quot;CEO linh vật&quot; của công ty khởi nghiệp.Hai vợ chồng họ lần lượt bắt đầu hành trình &quot;thăng cấp đánh quái&quot; một cách dí dỏm, để rồi trong cơn lạc lối, họ tìm lại được tấm lòng ban đầu và tình yêu của mình.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"La Tấn","avatar":""},{"name":"Nhâm Tố Tư","avatar":""},{"name":"Chu Du","avatar":""},{"name":"Hồ Hạnh Nhi","avatar":""},{"name":"Chu Du","avatar":""},{"name":"Vương Tử Xuyên","avatar":""},{"name":"Tôn An Khả","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shi cha yi wan gong li","时差一万公里"]', 1784690324139);
