INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('qua-trung-vang', 'Quả Trứng Vàng', 'The Golden Egg', 'https://phimimg.com/upload/vod/20251010-1/43d9f0a68e420f03597089071c5eb062.jpg', 'https://phimimg.com/upload/vod/20251010-1/2c1531e51e66529ef132c07d12c902c2.jpg', '<p>Sau khi đột ngột bị điều chuyển đến phòng ban mà cô sợ nhất, Hinako săn lùng tin lá cải sốt dẻo cho một tuần san và tìm kiếm ý nghĩa trong công việc của mình.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Aoi Okuyama","avatar":""},{"name":"Kou Maehara","avatar":""},{"name":"Takato Okura","avatar":""},{"name":"Yusuke Sato","avatar":""},{"name":"Tasuku Nagaoka","avatar":""},{"name":"Atom Shukugawa","avatar":""},{"name":"Eiji Takigawa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["独家新闻的雏鸟","The Golden Egg","Scoop no Tamago","Scoop''s Egg","スクープのたまご"]', 1784690324139);
