INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-phu-nu-nuot-chung-mat-troi', 'Người Phụ Nữ Nuốt Chửng Mặt Trời', 'A Woman Who Swallowed The Sun', 'https://phimimg.com/upload/vod/20251023-1/290dbc5547d4388282d8f93f06226cb0.jpg', 'https://phimimg.com/upload/vod/20251023-1/b35bf561c3e56adbaf5368af25f9344e.jpg', '<p>Baek Seol Hui, một người mẹ đơn thân kiên cường, vừa gánh vác quán ăn nhỏ vừa chăm sóc con gái. Nhưng khi bi kịch ập đến với con, Seol Hui buộc phải dấn thân vào cuộc chiến không khoan nhượng với một gia đình tài phiệt, để đòi lại công bằng.</p>', 'Hoàn Tất (125/125)', 125, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jang Shin-young","avatar":""},{"name":"Seo Ha-jun","avatar":""},{"name":"Yoon A-jung","avatar":""},{"name":"Oh Chang-seok","avatar":""},{"name":"Jeon No-min","avatar":""},{"name":"Park Cheol-min","avatar":""},{"name":"Kim Nan-hee","avatar":""},{"name":"Lee Kan-hee","avatar":""},{"name":"Luda","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Günəşi Udan Qadın","The Woman Who Swallowed the Sun","Người Phụ Nữ Nuốt Chửng Mặt Trời","태양을 삼킨 여자"]', 1784690324139);
