INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngam-ban-ho-diep', 'Ngắm Bắn Hồ Điệp', 'Sniper Butterfly', 'https://phimimg.com/upload/vod/20251204-1/e0daedd64b3d70b776c62c5bce6f6322.jpg', 'https://phimimg.com/upload/vod/20251204-1/ff85d591e1b48249d1b34e7eb938c96e.jpg', '<p>Một cô gái mạnh mẽ, lạnh lùng, quyến rũ, từng trải qua đau đớn để lột xác trưởng thành và một chàng trai kém tuổi hơn, dễ bảo, phóng khoáng, thẳng thắn theo đuổi điều mình muốn. Hai người đã cứu rỗi, chữa lành cho nhau và cùng viết nên một chuyện tình định mệnh vừa ngọt ngào vừa cuốn hút.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 22, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Nghiên Hy","avatar":""},{"name":"Châu Kha Vũ","avatar":""},{"name":"Lưu Nhuế Lân","avatar":""},{"name":"Trần Tiểu Vân","avatar":""},{"name":"Tạ Hưng Dương","avatar":""},{"name":"Trình Nhã Chiêu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Marcas do amor","Ju Ji Hu Die","Juji Hudie","Jujihudie","저격호접9","저격수 나비：피할 수 없는 사랑","Sniper Butterfly","狙击蝴蝶"]', 1784690324139);
