INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-chay-cung-chet', 'Có Chạy Cũng Chết', 'Runaway', 'https://phimimg.com/upload/vod/20251225-1/5f3b2d6e5832d8b09081b2d18f43dc7c.jpg', 'https://phimimg.com/upload/vod/20251225-1/d6261d992e91aa18e00df52b2d9e879b.jpg', '<p>Chỉ còn 168 giờ trước khi chết, Winrawi bị ám bởi một linh hồn thù hận luôn rình rập quanh cô. Trong tuyệt vọng, cô tìm đến một người phụ nữ lạnh lùng – người duy nhất có thể cứu cô, nhưng lại bị từ chối phũ phàng. Khi thời gian dần cạn, Winrawi buộc phải đối mặt với quá khứ tăm tối và bí mật kinh hoàng đang chờ đợi phía sau…</p>', 'Tập 8', 10, 'series', 'ongoing', 17, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Praewa Suthamphong","avatar":""},{"name":"Plaifah Siraacha","avatar":""},{"name":"Nichapat Numsapanan","avatar":""},{"name":"Saran Anantasetthakul","avatar":""},{"name":"Nutthasid Panyangarm","avatar":""},{"name":"Patitta Attayatamavitaya","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["หนีไปก็ตายเปล่า"]', 1784690324139);
