INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-du-trieu', 'Phong Dữ Triều', 'Silent Tides', 'https://phimimg.com/upload/vod/20251211-1/d6a8f0f931605474974796b8d3305a36.jpg', 'https://phimimg.com/upload/vod/20251211-1/77408ad1d6a00950aec9d5daf4792d1d.jpg', '<p>Trong những năm tháng chiến tranh khốc liệt, Ma Cao trở thành &quot;hòn đảo cô lập&quot; duy nhất không bị chiếm đóng ở Đông Á. Trên mảnh đất đầy sóng gió ngầm này, ông trùm ngân hàng Hà Hiền đã cùng bắt tay với những người yêu nước khác, âm thầm mở ra một chiến trường không tiếng súng. Đây không chỉ là một thành phố không bị chiếm đóng, mà là một cuộc chiến bí mật, những anh hùng này đã chiến đấu trong bóng tối với vũ khí đặc biệt: tình báo, tiền tệ và lòng dũng cảm phi thường.</p>', 'Hoàn Tất (31/31)', 31, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Nhậm Gia Luân","avatar":""},{"name":"Lam Doanh Oánh","avatar":""},{"name":"Lý Thuần","avatar":""},{"name":"Thẩm Khải","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["澳门往事","Once Upon a Time in Macao","Silent Tides","风与潮"]', 1784690324139);
