INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ninja-to-gokudou', 'Ninja to Gokudou', 'Ninja vs. Gokudo', 'https://phimimg.com/upload/vod/20251028-1/3eea4810138d74c287bddc3ed7506705.jpg', 'https://phimimg.com/upload/vod/20251028-1/12cf30d61a16b759d9b9eb9f8a3478da.jpg', '<p>Các ninja trừ tà trong bóng tối. Giới gokudo (yakuza) tập hợp những kẻ cô độc bị xã hội ruồng bỏ và sa vào tội lỗi. Mối hận thù mà họ gây dựng suốt nhiều thế kỷ trước nay lại bùng cháy trong thời hiện đại. Ninja Shinoha tình cờ gặp Kiwami, một thành viên gokudo mang vẻ ngoài của một doanh nhân. Không biết thân phận thật của nhau, họ kết nối qua niềm đam mê anime — nhưng cuộc chiến giữa ninja và gokudo ngày càng khốc liệt. Liệu ai sẽ sống sót và ai sẽ ngã xuống — ninja hay gokudo?</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Chiaki Kobayashi","avatar":""},{"name":"Katsuyuki Konishi","avatar":""},{"name":"Sumire Uesaka","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["忍者与极道","Ninja to Gokudou","Ninja to Gokudō","닌자와 야쿠자","Ninja Vs. Gokudo","忍者と極道"]', 1784690324139);
