INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-trang-hoan-menh', 'Sông Trăng Hoán Mệnh', 'Moon River', 'https://phimimg.com/upload/vod/20251109-1/83be47686162e7745c78a728067904bd.jpg', 'https://phimimg.com/upload/vod/20251109-1/dc76caa9206777cc65d6c49e67a6ab33.jpg', '<p>Bộ phim là câu chuyện hoán thân đổi xác giữa một thế tử cao quý và một cô gái bán hàng rong. Từ khi thế tử phi qua đời, Thế tử Yi Gang mất đi nụ cười và chỉ một lòng muốn báo thù cho người thương. Thế nhưng, ngay khi kế hoạch trả thù đã tính toán từ lâu vừa có bước tiến đầu tiên thì Yi Gang gặp được Park Dal Yi, một cô gái bán hàng rong bị mất trí nhớ có dung mạo y hệt thế tử phi quá cố. Hai người bị hoán đổi linh hồn, buộc phải sống trong thân xác của nhau, mở ra chuỗi tình huống dở khóc dở cười khiến cuộc đời cả hai đảo lộn.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 12, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kang Tae-oh","avatar":""},{"name":"Kim Se-jeong","avatar":""},{"name":"Lee Sin-young","avatar":""},{"name":"Hong Su-zu","avatar":""},{"name":"Jin Goo","avatar":""},{"name":"Kim Nam-hee","avatar":""},{"name":"Park Ah-in","avatar":""},{"name":"Im Gi-hong","avatar":""},{"name":"Park Bo-kyung","avatar":""},{"name":"Nam Kee-ae","avatar":""},{"name":"Choi Deok-moon","avatar":""},{"name":"Ji Il-ju","avatar":""},{"name":"Song Ji-hyun","avatar":""},{"name":"Han Sang-jo","avatar":""},{"name":"Tak Yi-on","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Moon Flows Through the River","نهر القمر","Ay, Nehrin içinden akıyor","月亮在江邊流淌","The Moon Flows Over the River","The Moon Flows in This River","이강에는 달이 흐른다"]', 1784690324139);
