INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('song-trang-hoan-menh', 'Sông Trăng Hoán Mệnh', 'Moon River', 'sông trăng hoán mệnh moon river kang tae-oh kim se-jeong lee sin-young hong su-zu jin goo kim nam-hee park ah-in im gi-hong park bo-kyung nam kee-ae choi deok-moon ji il-ju song ji-hyun han sang-jo tak yi-on the moon flows through the river نهر القمر ay, nehrin içinden akıyor 月亮在江邊流淌 the moon flows over the river the moon flows in this river 이강에는 달이 흐른다', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dien-thoai-den-2', 'Điện Thoại Đen 2', 'Black Phone 2', 'https://phimimg.com/upload/vod/20251105-1/ddc8c21445d8ff8e65b421d6a0e0a205.jpg', 'https://phimimg.com/upload/vod/20251105-1/f1423145ecbe873711b1498da402190c.jpg', '<p>Bốn năm trước, Finn khi mới 13 tuổi đã giết chết kẻ bắt cóc mình và trốn thoát thành công, trở thành người duy nhất sống sót sau vụ án của The Grabber - một kẻ sát nhân khét tiếng. Nhưng cái ác thực sự không chết đi… và chiếc điện thoại đen lại một lần nữa đổ chuông. Khi Finn nay đã 17 tuổi và vẫn vật lộn với hậu chấn tâm lý sau vụ bắt cóc, còn cô em gái 15 tuổi Gwen bắt đầu nhận được các cuộc gọi trong giấc mơ từ chiếc điện thoại đen kỳ lạ, cùng với những hình ảnh rùng rợn. Quyết tâm khám phá sự thật và chấm dứt cơn ác mộng cho cả bản thân lẫn anh trai, Gwen thuyết phục Finn cùng đến trại trong lúc có bão tuyết. Tại đây, cô phát hiện ra một bí mật kinh hoàng liên quan đến The Grabber và cả quá khứ của gia đình mình. Giờ đây, 2 anh em buộc phải đối đầu với một kẻ sát nhân không chỉ mạnh mẽ hơn sau khi chết, mà còn có mối liên hệ sâu sắc với họ hơn những gì họ từng tưởng tượng.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Ethan Hawke","avatar":""},{"name":"Mason Thames","avatar":""},{"name":"Madeleine McGraw","avatar":""},{"name":"Demián Bichir","avatar":""},{"name":"Miguel Mora","avatar":""},{"name":"Jeremy Davies","avatar":""},{"name":"Arianna Rivas","avatar":""},{"name":"Maev Beaty","avatar":""},{"name":"Graham Abbey","avatar":""},{"name":"James Ransone","avatar":""},{"name":"Anna Lore","avatar":""},{"name":"Simon Webster","avatar":""},{"name":"Shepherd Munroe","avatar":""},{"name":"Chase B. Robertson","avatar":""},{"name":"Dexter Bolduc","avatar":""},{"name":"Jazlyn Wong-Lee","avatar":""},{"name":"Julien Norman","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Untitled \"The Black Phone\" Sequel","闇黑電話 2","黑色电话2","The Black Phone 2","接駁靈聲2","Điện thoại đen 2","สายหลอน ซ่อนวิญญาณ 2","Qara Telefon 2","ブラック・フォン 2","O Telefone Preto 2","Black Phone 2"]', 1784690324139);
