INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dai-hong-thuy', 'Đại Hồng Thủy', 'The Great Flood', 'đại hồng thủy the great flood kim da-mi park hae-soo kwon eun-seong yuna lee dong-chan kim kang-bin kim su-kyung kim kyu-na kim byung-nam daehongsu el gran diluvio el gran diluvio the great flood submersion böyük daşqın 대홍수', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-la-sat-thu-nhung-chi-so-manh-hon-han-dung-si', 'Tôi Là Sát Thủ Nhưng Chỉ Số Mạnh Hơn Hẳn Dũng Sĩ', 'My Status As An Assassin Obviously Exceeds The Hero''s', 'https://phimimg.com/upload/vod/20251007-1/f850f8285810f9161d5a2d6aaf6ba93b.jpg', 'https://phimimg.com/upload/vod/20251007-1/2645b2ae78b4df861a2bc0b1a350ee8a.jpg', '<p>Oda Akira, một nam sinh trung học, cùng các bạn cùng lớp được triệu hồi đến một thế giới khác. Trong khi tất cả các bạn cùng lớp đều được ban cho những năng lực bá đào thì cậu lại chỉ nhận được năng lực “”Sát thủ”” tầm thường, có lẽ do sự hiện diện mờ nhạt bẩm sinh của mình.

Tuy nhiên, dù chỉ là một “”Sát thủ”” bình thường, chỉ số của cậu lại dễ dàng vượt qua cả nghề nghiệp mạnh nhất là “”Dũng sĩ””!?

Nghi ngờ hành động của quốc vương, người chủ trì cuộc triệu hồi, Akira đã che giấu sự tồn tại của mình để vạch trần âm mưu. Nhưng không ngờ, cậu lại bị gán tội danh oan uổng và bị truy đuổi. Thề sẽ trả thù quốc vương, cậu chạy trốn vào tầng sâu của một mê cung chưa từng có ai đặt chân đến và gặp gỡ Amelia, một cô gái Elf.

Đây là câu chuyện về một chàng trai nhận được năng lực “”sát thủ””, gặp gỡ một cô gái Elf và trở thành một “”sát thủ”” thực thụ.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 396, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Takeo Otsuka","avatar":""},{"name":"Saku Mizuno","avatar":""},{"name":"Junichi Suwabe","avatar":""},{"name":"Sanae Kobayashi","avatar":""},{"name":"Konomi Tamura","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["身为暗杀者的我明显比勇者还强","Ansatsusha de Aru Ore no Status ga Yuusha yori mo Akiraka ni Tsuyoi no da ga","ステつよ","Sutetsuyo","Мой статус ассасина очевидно превосходит геройский","暗殺者である俺のステータスが勇者よりも明らかに強いのだが"]', 1784690324139);
