INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sieu-cam-me-cung', 'Siêu Cảm Mê Cung', 'Supersensory Maze', 'siêu cảm mê cung supersensory maze đoạn dịch hoành đậu kiêu vương giai giai lữ tinh thần mã ngâm ngâm yên duyệt khê lý thạnh mã bá toàn triệu nhuận nam trương triệu huy lưu kim sơn chao gan mi gong sense labyrinth 超感迷宫', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-quy-ky-dam', 'Đường Quỷ Kỳ Đàm', 'Strange Chronicles Of Tang', 'https://phimimg.com/upload/vod/20251219-1/272c92ebe087ab131e9ea05e06da7520.jpg', 'https://phimimg.com/upload/vod/20251219-1/cf5b4cd10da8cdf6dc444fe8254dfdaa.jpg', '<p>Vào đầu thời nhà Đường, thời kỳ thịnh vượng và huy hoàng, Trường An chìm trong bóng tối và đầy rẫy những câu chuyện đen tối. Ẩn sau vẻ hào nhoáng rực rỡ ấy là những sự kiện kỳ quái. Giữa cảnh đổ máu và hỗn loạn, một cuộc săn đuổi nguy hiểm đang rình rập. Câu chuyện về một thời đại thịnh vượng và một vụ án bí ẩn dần được hé lộ.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 12, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Tử Văn","avatar":""},{"name":"Dương Chí Cương","avatar":""},{"name":"Cao Tư Văn","avatar":""},{"name":"Trần Sáng","avatar":""},{"name":"Tôn Tuệ Ninh","avatar":""},{"name":"Thạch Nguyệt An Tâm","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["唐朝诡事录","唐朝诡事录之长安","唐朝诡事录之西行","唐朝诡事录之蜀道","唐诡奇谭","唐诡","唐诡2","唐诡3","唐诡4","داستان‌های ترسناک سلسله تانگ","قصه‌های عجیب سلسله تانگ","唐朝詭事録：西へ","唐朝詭事録","唐朝詭事録：長安へ","당조궤사록 : 장안","ปริศนาลับราชวงศ์ถัง ณ​ ฉางอัน","唐朝詭事錄之長安","Strange Tales of Tang Dynasty","Horror Stories of Tang Dynasty","Strange Legend of Tang Dynasty","Tang chao gui shi lu","Strange Tales of Tang Dyn