INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('renoir-tinh-tho', 'Renoir: Tình Thơ', 'Renoir', 'https://phimimg.com/upload/vod/20251223-1/85e526978de4002716fe7249ce5ec922.jpg', 'https://phimimg.com/upload/vod/20251223-1/c82b9bc3f1c17f1bba7d953744d57f1f.jpg', '<p>Một cô bé 11 tuổi ở Tokyo năm 1987 trải qua tuổi thơ nhiều biến động khi phải đối mặt với bệnh tình của cha và áp lực của mẹ, đồng thời chứng kiến những mảnh đời trưởng thành đầy tổn thương xung quanh.</p>', 'Full', 1, 'single', 'completed', 33, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yui Suzuki","avatar":""},{"name":"Hikari Ishida","avatar":""},{"name":"Lily Franky","avatar":""},{"name":"Ayumu Nakajima","avatar":""},{"name":"Yuumi Kawai","avatar":""},{"name":"Ryota Bando","avatar":""},{"name":"Charlie St. Cyr","avatar":""},{"name":"Jeffrey Rowe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Điển","slug":"kinh-dien","id":"268385d0de78827ff7bb25c35036ee2a"}]', '["雷诺阿","印象派女孩","風葵的夏日物語","Renuaras","ルノワール"]', 1784690324139);
