INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuc-quai-ky-dam', 'Thực Quái Kỳ Đàm', 'Strange Tale of Consumption', 'https://phimimg.com/upload/vod/20251223-1/136c02d0c51f0bd7e1d976f337549e3c.jpg', 'https://phimimg.com/upload/vod/20251223-1/679786da55c5e50b4c4c3de5663ce9c6.jpg', '<p>Năm nhà văn. Một khu sáng tác biệt lập. Và một trí tuệ cổ xưa bị đánh thức. Khi “Dokkaebi Dumbung” mở ra cánh cổng xuyên thời gian, thực tại bắt đầu sụp đổ. Một lính đặc nhiệm phải chiến đấu để phong ấn cổng kết nối quá khứ và hiện tại.</p>', 'Full', 1, 'single', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Cho Seong-ha","avatar":""},{"name":"Baek Sung-hyun","avatar":""},{"name":"Ye Su-jeong","avatar":""},{"name":"Kim Hong-pyo","avatar":""},{"name":"Seo Han-gyeol","avatar":""},{"name":"Lee Chang-won","avatar":""},{"name":"Han Si-an","avatar":""},{"name":"Park No-gyeong","avatar":""},{"name":"Yoon Su-jin","avatar":""},{"name":"Jeong Dae-gyo","avatar":""},{"name":"Lee Jong-geun","avatar":""},{"name":"Jeon Seung-ho","avatar":""},{"name":"Ryu Geun-hong","avatar":""},{"name":"Choi Yu-yeong","avatar":""},{"name":"Son Kwang-Eop","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["흡식기담"]', 1784690324139);
