INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-yeu-los-angeles', 'Tôi Yêu Los Angeles', 'I Love LA', 'https://phimimg.com/upload/vod/20251208-1/bd691fbc86ca325f6c8a3d17311d8bfd.jpg', 'https://phimimg.com/upload/vod/20251208-1/8528f239c40d8bbdf3688bf9e6d615a7.jpg', '<p>Một nhóm bạn thân thiết tái hợp sau nhiều năm xa cách, đối mặt với những phức tạp của tham vọng, các mối quan hệ và cách mà thời gian đã thay đổi họ.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rachel Sennott","avatar":""},{"name":"Odessa A''zion","avatar":""},{"name":"Jordan Firstman","avatar":""},{"name":"True Whitaker","avatar":""},{"name":"Josh Hutcherson","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["I Love LA"]', 1784690324139);
