INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('toi-yeu-los-angeles', 'Tôi Yêu Los Angeles', 'I Love LA', 'tôi yêu los angeles i love la rachel sennott odessa a''zion jordan firstman true whitaker josh hutcherson i love la', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-cuoc-phieu-luu-tinh-ai-cua-nguoi-ngoai-co', 'Những Cuộc Phiêu Lưu Tình Ái Của Người Ngoại Cỡ!', 'Plus-sized Misadventures In Love!', 'https://phimimg.com/upload/vod/20251007-1/161947ecb6269519abcf98d45d5cc271.jpg', 'https://phimimg.com/upload/vod/20251007-1/4c382d94751891b74788a5a7274a67e3.jpg', '<p>“Đây là sự trừng phạt của tôi — một kẻ xấu xí như tôi lại dám phải lòng một người đẹp như anh...” Yumeko luôn mang trong mình vô vàn mặc cảm về bản thân. Rồi một tai nạn khủng khiếp bất ngờ xảy ra với cô. Dù được cứu thoát khỏi lằn ranh sinh tử, nhưng khi tỉnh lại, Yumeko phát hiện mình đã trở thành một con người hoàn toàn khác. “Đây... là tôi sao?! Mình... DỄ THƯƠNG QUÁ TRỜI!!” Mọi người xung quanh đều kinh ngạc trước sự thay đổi 180 độ này. Nhưng không chỉ ngoại hình, tinh thần lạc quan rạng rỡ của Yumeko cũng bắt đầu làm thay đổi những người bên cạnh cô. Dù là trong tình yêu, công việc, hay tình bạn... Yumeko sẽ mạnh mẽ vượt qua mọi lo lắng và mặc cảm — của chính mình và cả của những người khác! Và rồi giữa tất cả những thay đổi đó… lại xuất hiện một vụ mưu sát bí ẩn?!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Aya Endo","avatar":""},{"name":"Yuma Uchida","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["胖子、爱情和错误！","Debu to Love to Ayamachi to!","デブとラブと過ちと!"]', 1784690324139);
