INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thong-linh-phi-phan-2-ban-anime', 'Thông Linh Phi (Phần 2) (Bản Anime)', 'Psychic Princess (Season 2)', 'https://phimimg.com/upload/vod/20251001-1/0f908ebb8064c490e2f472bc73c7deee.jpg', 'https://phimimg.com/upload/vod/20251001-1/4655bfc58af9adfcbec0d6385ab06c85.jpg', '<p>Câu chuyện kể về Thiên Vân Hy, đại tiểu thư phủ Thừa Tướng. Ngay từ nhỏ nàng đã mang dị năng, bị coi là điềm gở nên bị đưa lên núi Linh Vân nuôi dưỡng. Năm 16 tuổi, nàng phải thay em gái Thiên Vân Thường gả vào Dạ Vương phủ. Tương truyền Dạ U Mị có tính tình quái lạ, lạnh lùng và tàn bạo. Liệu Thiên Vân Hy sẽ phải trải qua những biến cố gì trong cuộc hôn nhân đầy bí ẩn này?</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 243, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Sone Wakana","avatar":""},{"name":"Lu Lifeng","avatar":""},{"name":"Xing Chao","avatar":""},{"name":"唐策","avatar":""},{"name":"kinsen","avatar":""},{"name":"Guo Haoran","avatar":""},{"name":"Fan Xinyuan","avatar":""},{"name":"Yun Hezhui","avatar":""},{"name":"He Wenxiao","avatar":""},{"name":"Rong Zeng","avatar":""},{"name":"Zhao Xi","avatar":""},{"name":"Wang Cong","avatar":""},{"name":"Peng Sun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Tong Ling Fei","通灵妃2","通灵妃 第二季","Psychic Princess","Psychic Princess 2","通灵妃"]', 1784690324139);
