INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('merteuil-my-nhan-ke', 'Merteuil: Mỹ Nhân Kế', 'The Seduction', 'https://phimimg.com/upload/vod/20251117-1/e413e745e7b7cb9d563ed83e37cf5b30.jpg', 'https://phimimg.com/upload/vod/20251117-1/f600cb809d19fe99abc63c625dbecfe2.jpg', '<p>Hầu tước phu nhân de Merteuil, sau khi bị Valmont phản bội, bắt đầu một hành trình táo bạo để trở thành kỹ nữ hàng đầu Paris.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Anamaria Vartolomei","avatar":""},{"name":"Diane Kruger","avatar":""},{"name":"Vincent Lacoste","avatar":""},{"name":"Lucas Bravo","avatar":""},{"name":"Noée Abita","avatar":""},{"name":"Julien de Saint Jean","avatar":""},{"name":"Fantine Harduin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["梅尔特伊","危险关系前传","诱惑","危险诱惑","Merteuil"]', 1784690324139);
