INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('theo-dau-yeu-thuong-da-lang-quen-tam-ha-rak-thi-thoe-luem', 'Theo Dấu Yêu Thương Đã Lãng Quên (Tam Ha Rak Thi Thoe Luem)', 'Searching For The Love She Forgot', 'https://phimimg.com/upload/vod/20251220-1/fa3233da9ac466c8eba0de9835cbeb7f.jpg', 'https://phimimg.com/upload/vod/20251220-1/654e1056f0b89c9eb42821df70d2fbab.jpg', '<p>Khwannet (Best Rakwanee), cô gái hiếu thảo, giàu nghị lực, lớn lên ở Sri Racha và luôn tin rằng mình là đứa trẻ được nhặt về nuôi. Cho đến một ngày, cô phát hiện sự thật rằng Hiran (Captain Phutanate) – cha ruột của cô – vẫn còn sống nhưng đang bệnh nặng. Để tìm cha, Khwannet quyết định lên Bangkok và xin làm việc tại siêu thị Big C vì cô nghe tin rằng “Bếp Premchan”, doanh nghiệp của cha cô, sắp mở chi nhánh mới tại đây. Sự nghi ngờ khiến cô quyết định cải trang, vào làm ở vị trí gần gũi với cha để điều tra mọi sự thật. Nhưng việc tiếp cận cha không hề dễ! Khi gặp lại, cô sốc khi có một chàng trai khác cũng gọi người đàn ông ấy là “cha”! Đó là Phakhin (Jam Rachata) – người con trai còn lại của Hiran – kẻ luôn tìm cách ngăn cản vì lo Khwannet đến lợi dụng người cha đang lâm bệnh. Từ đó cả hai trở thành “kẻ thù không đội trời chung”. Mọi chuyện càng rối ren hơn khi Khwannet phát hiện manh mối quan trọng về cái c//h/ế/t của Kaew (Pim Pimmada), mẹ cô. Có khả năng phía sau đó là một âm mưu! Cô quyết tâm tìm hiểu sự thật về quá khứ và những bí mật bị che giấu bấy lâu nay. Lần trở về này không chỉ mang theo nỗi nhớ mà còn đưa cô đối mặt với nguy hiểm và những bí mật có thể thay đổi cuộc đời cô mãi mãi. Và giữa hành trình tìm kiếm sự thật, Khwannet lại tìm thấy “tình yêu” mà chính cô đã quên từ rất lâu.</p>', 'Tập 3', 30, 'series', 'ongoing', 12, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Rachata Hampanont","avatar":""},{"name":"Rakwanee Kamsing","avatar":""},{"name":"Wittaya Teptip","avatar":""},{"name":"Chanidapa Singhaseni","avatar":""},{"name":"Chalisa Chayasunthorn","avatar":""},{"name":"Nubtong Whankaew","avatar":""},{"name":"Jeeranan Jamjuksu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Tam Ha Rak Thi Thoe Luem","The Forgotten Love","ตามหารักที่เธอลืม"]', 1784690324139);
