INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('theo-dau-yeu-thuong-da-lang-quen-tam-ha-rak-thi-thoe-luem', 'Theo Dấu Yêu Thương Đã Lãng Quên (Tam Ha Rak Thi Thoe Luem)', 'Searching For The Love She Forgot', 'theo dấu yêu thương đã lãng quên (tam ha rak thi thoe luem) searching for the love she forgot rachata hampanont rakwanee kamsing wittaya teptip chanidapa singhaseni chalisa chayasunthorn nubtong whankaew jeeranan jamjuksu tam ha rak thi thoe luem the forgotten love ตามหารักที่เธอลืม', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-dao-tau-2025', 'Kẻ Đào Tẩu', 'ESCAPE', 'https://phimimg.com/upload/vod/20251020-1/2246c1155128daf5d34ab2728857570a.jpg', 'https://phimimg.com/upload/vod/20251020-1/0e759364a52cf3bd5374e045dd277e34.jpg', '<p>Con gái của một giám đốc điều hành tập đoàn dược phẩm giàu có bị bắt cóc vào đúng ngày sinh nhật thứ 20 của cô. Tuy nhiên, khi vụ bắt cóc thất bại khiến một trong những kẻ bắt giữ choáng váng, cô tiểu thư tưởng chừng ngoan ngoãn ấy lại khiến tất cả sửng sốt khi cầu xin hắn hãy cùng cô bỏ trốn. Từ đó khởi đầu một cuộc truy lùng hỗn loạn, dần hé lộ những bí mật nguy hiểm về thân phận thật sự của cô — và buộc cả hai kẻ đào tẩu phải đối mặt với số phận méo mó mà họ không thể trốn thoát.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hiyori Sakurada","avatar":""},{"name":"Hayato Sano","avatar":""},{"name":"Kazuki Kitamura","avatar":""},{"name":"Yasuko Tomita","avatar":""},{"name":"Makiya Yamaguchi","avatar":""},{"name":"Satoru Matsuo","avatar":""},{"name":"Kousei Yuki","avatar":""},{"name":"First Summer Uika","avatar":""},{"name":"Yū Kamio","avatar":""},{"name":"Kisuke Iida","avatar":""},{"name":"Shunsuke Tanaka","avatar":""},{"name":"Cent Chihiro Chittiii","avatar":""},{"name":"Hiromu Takatsuk","avatar":""},{"name":"Mirai Shida","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Escape Sore wa Yukai no Hazudatta","ESCAPE それは誘拐のはずだった"]', 1784690324139);
