INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-gia-lam-me', 'Đóng Giả Làm Mẹ', 'Fake Mommy', 'https://phimimg.com/upload/vod/20251021-1/aab83dafe7a54b2a1748b3f99f1a9378.jpg', 'https://phimimg.com/upload/vod/20251021-1/045c130b5b14409b70b87fcd64dac5bf.jpg', '<p>Một cựu sinh viên ưu tú của Đại học Tokyo, đang chật vật tìm việc làm, bất ngờ hợp tác với một nữ doanh nhân bỏ học giữa chừng — người mạnh mẽ và gai góc — để giả làm hai mẹ con hoàn hảo trong kỳ thi tuyển sinh vào một trường tiểu học danh giá. Cả hai lao vào kế hoạch liều lĩnh này, đối mặt với nguy cơ phạm pháp và sụp đổ đạo đức, chỉ để đánh cược tất cả cho tương lai của đứa trẻ.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Haru","avatar":""},{"name":"Rina Kawaei","avatar":""},{"name":"Koji Mukai","avatar":""},{"name":"Aoi Nakamura","avatar":""},{"name":"Aoi Ikemura","avatar":""},{"name":"Kayo Noro","avatar":""},{"name":"Manami Hashimoto","avatar":""},{"name":"Kurumi Nakada","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["フェイクマミー"]', 1784690324139);
