INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dong-gia-lam-me', 'Đóng Giả Làm Mẹ', 'Fake Mommy', 'đóng giả làm mẹ fake mommy haru rina kawaei koji mukai aoi nakamura aoi ikemura kayo noro manami hashimoto kurumi nakada フェイクマミー', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-chi-song-mot-lan', 'Đời Chỉ Sống Một Lần', 'Don''t Call Me Ma''am', 'https://phimimg.com/upload/vod/20251111-1/ac11d4650aa3f90862b2c3b6132c0be3.jpg', 'https://phimimg.com/upload/vod/20251111-1/5aab1b480ef7c20c19d61d22692abc00.jpg', '<p>Câu chuyện về ba người bạn 41 tuổi. Cho Na Jeong (Kim Hee Sun) từng là người dẫn chương trình mua sắm tại nhà trên truyền hình và kiếm được hàng trăm triệu won từ công việc của mình. Giờ đây, cô là một bà nội trợ toàn thời gian và là mẹ của hai cậu con trai. Cô cố gắng quay trở lại với công việc với mức lương cao ngất ngưởng mà cô từng có. Koo Ju Yeong (Han Hye Jin) làm quản lý kế hoạch tại một trung tâm nghệ thuật, nơi trưng bày những màn trình diễn chất lượng cao. Cô dường như có một cuộc sống hoàn hảo cả về đời tư lẫn sự nghiệp. Nhưng thực tế, cô phải chịu đựng nỗi đau khi cố gắng sinh con với người chồng vô tính của mình. Lee Il Ri (Jin Seo Yun) độc thân và làm phó tổng biên tập cho một tạp chí thời trang. Cô bắt đầu sự nghiệp với tư cách là biên tập viên thời trang và đã nỗ lực hết mình để trở thành phó tổng biên tập. Cô vẫn ấp ủ một giấc mơ về hôn nhân, một giấc mơ mà cô vẫn chưa thực hiện được.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Hee-seon","avatar":""},{"name":"Han Hye-jin","avatar":""},{"name":"Jin Seo-yeon","avatar":""},{"name":"Yoon Park","avatar":""},{"name":"Heo Joon-seok","avatar":""},{"name":"Jang In-sub","avatar":""},{"name":"Moon You-kang","avatar":""},{"name":"Han Ji-hye","avatar":""},{"name":"Kim Young-ah","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["因为没有来生","لا تدعني سيدتي","No Next Life","다음생은 없으니까"]', 1784690324139);
