INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-quy', 'Song Quỹ', 'Speed And Love', 'https://phimimg.com/upload/vod/20251214-1/a1eeff4565e08bb8e8f31599d8cd266c.jpg', 'https://phimimg.com/upload/vod/20251214-1/ce49bd08edb91c937516a7d27bb08ccd.jpg', '<p>Trước 9 tuổi, Khương Mộ là cô em gái được yêu chiều, còn Cận Triều là anh trai tài năng. Sau khi cha mẹ ly hôn, Cận Triều theo cha sang Thái Lan, và Khương Mộ phát hiện anh chỉ là con nuôi. Quyết tâm tìm anh, cô đến Thái Lan, nơi Cận Triều giờ sống trong thế giới nguy hiểm. Khương Mộ không từ bỏ, hòa nhập vào cuộc sống của gia đình và giúp Cận Triều vượt qua khó khăn. Cô trở thành người đồng hành lý tưởng của anh. Sau một biến cố, họ chia xa, nhưng nhiều năm sau, họ tái ngộ ở Nam Kinh và tiếp tục hành trình song song đầy ý nghĩa. Cả hai cùng tỏa sáng, không còn xa cách.</p>', 'Hoàn Tất (29/29)', 29, 'series', 'completed', 10, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngu Thư Hân","avatar":""},{"name":"Hà Dữ","avatar":""},{"name":"Phí Khải Minh","avatar":""},{"name":"Patrick Nattawat Finkler","avatar":""},{"name":"Châu Hạo Kỳ","avatar":""},{"name":"Loan Nguyên Huệ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Corridas do coração","Shuang Gui","Amor y velocidad","쌍궤: 스피드 & 러브","Двойной трек","Тропы звёзд","雙軌","Double Track","Star Trails","Speed and Love","双轨"]', 1784690324139);
