INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('song-quy', 'Song Quỹ', 'Speed And Love', 'song quỹ speed and love ngu thư hân hà dữ phí khải minh patrick nattawat finkler châu hạo kỳ loan nguyên huệ corridas do coração shuang gui amor y velocidad 쌍궤: 스피드 & 러브 двойной трек тропы звёзд 雙軌 double track star trails speed and love 双轨', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('shuumatsu-touring', 'Shuumatsu Touring', 'Touring After The Apocalypse', 'https://phimimg.com/upload/vod/20251012-1/c5de0b3ae33166494f9a81308be5d063.jpg', 'https://phimimg.com/upload/vod/20251012-1/9dd8d3bc91911dfe11805bf2abf6e694.jpg', '<p>Hai cô gái trẻ, Yoko và Airi, cùng nhau rong ruổi khắp thế giới trống vắng của Nhật Bản hậu tận thế. Họ chụp ảnh phong cảnh ở những địa điểm nổi tiếng và cắm trại trong các thị trấn đã bị thiên nhiên nuốt chửng. Cả hai cưỡi trên chiếc xe địa hình Serow, tận hưởng một cảm giác tự do mới mẻ — không còn kẹt xe, không còn đèn giao thông. Giờ đây, thế giới đã kết thúc rồi, vậy thì hãy lên xe và cùng nhau bắt đầu chuyến hành trình thôi!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Konomi Inagaki","avatar":""},{"name":"Miyu Tomita","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["末世二轮之旅","终末摩托游","Shūmatsu Touring","Shuumatsu Touring","Riding a motorbike at the end of the world...","末世二輪之旅","Постапокаліптичний туризм","Тур після кінця світу","Touring After the Apocalypse","終末ツーリング"]', 1784690324139);
