INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phap-su-trieu-dinh-bi-truc-xuat-quyet-chi-tro-thanh-manh-nhat-mikata-ga-yowasugite-hojo-mahou-ni-tesshiteita-kyuutei-mahoushi-tsuihou-sarete-saikyou-wo-mezashimasu', 'Pháp Sư Triều Đình Bị Trục Xuất Quyết Chí Trở Thành Mạnh Nhất (Mikata ga Yowasugite Hojo Mahou ni Tesshiteita Kyuutei Mahoushi, Tsuihou sarete Saikyou wo Mezashimasu)', 'The Banished Court Magician Aims To Become The Strongest', 'https://phimimg.com/upload/vod/20251006-1/51a7e47039a3fe3457d6d206dd2ebc79.jpg', 'https://phimimg.com/upload/vod/20251006-1/74d7f8e46a8532ddf4bb7329af465a38.jpg', '<p>Từng là một pháp sư trung thành, âm thầm hỗ trợ thái tử từ phía sau hậu trường, Alec Ygret bị ruồng bỏ và lưu đày chỉ vì anh chỉ biết dùng ma pháp hỗ trợ. Nhưng ngay khi rơi xuống tận đáy cuộc đời, anh tình cờ gặp lại Yorha Eisentz — đồng đội cũ trong nhóm huyền thoại <strong>Lasting Period</strong>. Được mời tái gia nhập đội từng làm nên lịch sử, Alec quay trở lại con đường thám hiểm hầm ngục — và bắt đầu một chương mới trong cuộc đời mình!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 395, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shuichiro Umeda","avatar":""},{"name":"Yurika Kubo","avatar":""},{"name":"Masumi Tazawa","avatar":""},{"name":"Masaaki Mizunaka","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["贯彻辅助魔法支援弱小队友的宫廷魔法师，惨遭驱逐后目标成为最强冒险者","Mikata ga Yowasugite Hojo Mahō ni Tesshiteita Kyūtei Mahōshi","Mikata ga Yowasugite Hojo Mahō ni Tesshiteita Kyūtei Mahōshi, Tsuihō Sarete Saikyō o Mezasu","Mikata ga Yowasugite Hojo Mahō ni Tesshiteita Kyūtei Mahōshi, Tsuihō Sarete Saikyō wo Mezasu","補助魔法","Mikata ga Yowa Sugite Hojo Mahou ni Toushite Ita Kyuutei Mahoushi, Tsuihou Sarete Saikyou wo Mezasu","Mikata ga Yowasugite Hojo Mahou ni Tesshiteita Kyuutei Mahoushi, Tsuihou sarete Saikyou wo Mezashimasu","Mikata ga Yowasugite Hojo Mahou ni Tesshiteita Kyuutei Mahoushi, Tsuihou sarete Saikyou o Mezashimasu","Mikata ga Yowa Sugite Hojo Mahou ni Toushite Ita Kyuutei Mahoushi, Tsuihou Sarete Saikyou o Mezasu","The Court Magician Was So Weak That He Was Dedicated To Supporting Magic, And Was Exiled And Aimed To Become The Strongest","みかたがよわすぎてほじょまほうにてっしていたきゅうていまほうしついほうされてさいきょうをめざす","Mikata ga Yowasugite Hojo Maho ni Tesshite ita Kyutei Mahoshi","Banished Court Magician Aims to Become the Strongest","味方が弱すぎて補助魔法に徹していた宮廷魔法師、追放されて最強を目指す"]', 1784690324139);
