INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phap-su-trieu-dinh-bi-truc-xuat-quyet-chi-tro-thanh-manh-nhat-mikata-ga-yowasugite-hojo-mahou-ni-tesshiteita-kyuutei-mahoushi-tsuihou-sarete-saikyou-wo-mezashimasu', 'Pháp Sư Triều Đình Bị Trục Xuất Quyết Chí Trở Thành Mạnh Nhất (Mikata ga Yowasugite Hojo Mahou ni Tesshiteita Kyuutei Mahoushi, Tsuihou sarete Saikyou wo Mezashimasu)', 'The Banished Court Magician Aims To Become The Strongest', 'pháp sư triều đình bị trục xuất quyết chí trở thành mạnh nhất (mikata ga yowasugite hojo mahou ni tesshiteita kyuutei mahoushi, tsuihou sarete saikyou wo mezashimasu) the banished court magician aims to become the strongest shuichiro umeda yurika kubo masumi tazawa masaaki mizunaka 贯彻辅助魔法支援弱小队友的宫廷魔法师，惨遭驱逐后目标成为最强冒险者 mikata ga yowasugite hojo mahō ni tesshiteita kyūtei mahōshi mikata ga yowasugite hojo mahō ni tesshiteita kyūtei mahōshi, tsuihō sarete saikyō o mezasu mikata ga yowasugite hojo mahō ni tesshiteita kyūtei mahōshi, tsuihō sarete saikyō wo mezasu 補助魔法 mikata ga yowa sugite hojo mahou ni toushite ita kyuutei mahoushi, tsuihou sarete saikyou wo mezasu mikata ga yowasugite hojo mahou ni tesshiteita kyuutei mahoushi, tsuihou sarete saikyou wo mezashimasu mikata ga yowasugite hojo mahou ni tesshiteita kyuutei mahoushi, tsuihou sarete saikyou o mezashimasu mikata ga yowa sugite hojo mahou ni toushite ita kyuutei mahoushi, tsuihou sarete saikyou o mezasu the court magician was so weak that he was dedicated to supporting magic, and was exiled and aimed to become the strongest みかたがよわすぎてほじょまほうにてっしていたきゅうていまほうしついほうされてさいきょうをめざす mikata ga yowasugite hojo maho ni tesshite ita kyutei mahoshi banished court magician aims to become the strongest 味方が弱すぎて補助魔法に徹していた宮廷魔法師、追放されて最強を目指す', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lo-ban-di-van-luc', 'Lỗ Ban Dị Văn Lục', 'Lu Ban: Records Of Unusual Tales', 'https://phimimg.com/upload/vod/20251207-1/27f6c1555afaa67d51744ab1ed4b4d35.jpg', 'https://phimimg.com/upload/vod/20251207-1/345dd3a86b1eb26d9a0210f132f6d9f5.jpg', '<p>Vào thời Dân quốc, dân chúng còn u mê, mê tín những chuyện quỷ thần hoang đường. Lý Mộc Đôn là thợ mộc giỏi nhất Vụ Thành, tinh thông cổ thư “Lỗ Ban Bí Thuật”. Tương truyền cuốn sách này chia thành hai quyển thượng và hạ: quyển thượng nghiên cứu nghệ thuật làm mộc, còn quyển hạ lại ghi chép những tà thuật kỳ bí khó lường. Vụ Thành bất ngờ xảy ra án cô dâu mất tích, nguyên nhân cái chết quái dị khiến dư luận xôn xao, nhiều người nghi ngờ chính Lý Mộc Đôn đã dùng tà thuật làm điều ác. Để chứng minh sự trong sạch của mình, Lý Mộc Đôn cùng cảnh thám Dương Tông và pháp y Tô Thanh Vân đã điều tra rõ ngọn ngành, cuối cùng phát hiện hung thủ chẳng qua chỉ lợi dụng bí thuật bố trí cơ quan để ngụy tạo hiện tượng thần bí đánh lừa thiên hạ. Ba người phối hợp hết sức ăn ý, liên tiếp phá thành công các vụ án: vụ án trụ sống, vụ án con rối gỗ giết người, vụ án phu xe,... Tất cả các vụ án này đều có mối liên hệ rắc rối với Vu Hàm, sư đệ của Lý Mộc Đôn. Khi Đốc quân qua đời, Vụ Thành lại xuất hiện chuỗi án mạng liên hoàn, gây chấn động toàn thành. Lý Mộc Đôn cùng hai người bạn được giao trọng trách, đấu trí đấu dũng với Vu Hàm, cuối cùng vạch trần toàn bộ chân tướng. Họ dùng hành động để chứng minh rằng chính nghĩa nhất định chiến thắng sự ngu muội và bóng tối, đồng thời kế thừa và phát huy tinh thần coi trọng sự thật, bài trừ mê tín trong văn hóa truyền thống Trung Hoa.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lai Hỉ","avatar":""},{"name":"Bành Nhã Kỳ","avatar":""},{"name":"Lý Tích Thần","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Lu Ban: Records of Unusual Tales","鲁班异闻录"]', 1784690324139);
