INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kashiwada-vo-cam-va-oota-bieu-cam', 'Kashiwada Vô Cảm Và Oota Biểu Cảm', 'Inexpressive Kashiwada And Expressive Oota', 'https://phimimg.com/upload/vod/20251006-1/38ac212cd7ae7905d755f5e3d44375d1.jpg', 'https://phimimg.com/upload/vod/20251006-1/1eba40ee6a8364fc39f52983dbbfd695.jpg', '<p>Khuôn mặt của Kashiwada-san là một kiệt tác của sự điềm tĩnh. Còn bạn cùng lớp của cô, Oota-kun, lại là một “quả bom cảm xúc” luôn cố gắng phá vỡ vẻ bình thản ấy bằng những trò lố hết mức. (Tiết lộ nhỏ: cậu ta chưa thành công đâu.) Nhưng giữa những lần gây bất ngờ thất bại của Oota và những nụ cười lén của Kashiwada, hai người bạn học trái ngược này dường như lại có chút tình cảm với nhau! Hãy cùng chứng kiến một câu chuyện rom-com nơi tình yêu được thể hiện mạnh mẽ hơn cả lời nói.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Akane Fujita","avatar":""},{"name":"Kyouhei Natsume","avatar":""},{"name":"Yuya Hirose","avatar":""},{"name":"Souhei Horikane","avatar":""},{"name":"Yumiri Hanamori","avatar":""},{"name":"Mayu Mineda","avatar":""},{"name":"Shiori Mikami","avatar":""},{"name":"Daisuke Kishio","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["无口的柏田小姐与元气的太田君","Expressionless Face Girl and Emotional Face Boy","Kao ni Denai Kashiwada-san to Kao ni Deru Oota-kun","Kao ni Denai Kashiwada-san to Kao ni Deru Ōta-kun","Expressionless Face Girl & Emotional Face Boy","Expressionless Face Girl Kashiwada and Emotional Face Boy Oota","顔に出ない柏田さんと顔に出る太田君"]', 1784690324139);
