INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('kashiwada-vo-cam-va-oota-bieu-cam', 'Kashiwada Vô Cảm Và Oota Biểu Cảm', 'Inexpressive Kashiwada And Expressive Oota', 'kashiwada vô cảm và oota biểu cảm inexpressive kashiwada and expressive oota akane fujita kyouhei natsume yuya hirose souhei horikane yumiri hanamori mayu mineda shiori mikami daisuke kishio 无口的柏田小姐与元气的太田君 expressionless face girl and emotional face boy kao ni denai kashiwada-san to kao ni deru oota-kun kao ni denai kashiwada-san to kao ni deru ōta-kun expressionless face girl & emotional face boy expressionless face girl kashiwada and emotional face boy oota 顔に出ない柏田さんと顔に出る太田君', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-gai-cua-ban-toi-dang-choc-tuc-toi', 'Em Gái Của Bạn Tôi Đang Chọc Tức Tôi!', 'My Friend''s Little Sister Has It In For Me!', 'https://phimimg.com/upload/vod/20251005-1/0c32ca94926b4a394c394a11cf742c3a.jpg', 'https://phimimg.com/upload/vod/20251005-1/46556f2a07eac735db12e88f1d01e76c.jpg', '<p>Với học sinh trung học Akiteru Oboshi, tất cả những thứ gọi là “trải nghiệm tuổi trẻ” — như vui chơi, tình bạn, hay thậm chí là có bạn gái — đều chỉ là lãng phí thời gian. Vì vậy, khi em gái của bạn thân cậu, Iroha Kohinata, cứ liên tục trêu chọc mình, Akiteru tự nhiên cảm thấy vô cùng phiền phức. Cô ấy hầu như sống trong phòng của cậu, luôn nằm trên giường cậu, là một cơn bão bám dính không dứt! Nhưng tại sao cô ấy chỉ trở nên phiền toái khi ở cạnh cậu thôi chứ?!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Haruki Ishiya","avatar":""},{"name":"Sayumi Suzushiro","avatar":""},{"name":"Tomori Kusunoki","avatar":""},{"name":"Soma Saito","avatar":""},{"name":"Kana Hanazawa","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["朋友的妹妹只喜欢烦我","朋友的妹妹只缠着我","Tomodachi no Imōto ga Ore ni Dake Uzai","Imouza","Tomodachi no Imouto ga Ore ni dake Uzai","いもウザ","Imouza!","My Friend’s Little Sister is Annoying Only to Me","My Friend''s Little Sister is Annoying Only Towards Me","友達の妹が俺にだけウザい"]', 1784690324139);
