INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-hau-may-marie', 'Cô Hầu Máy Marie', 'Mechanical Marie', 'https://phimimg.com/upload/vod/20251008-1/cfa1ec5d7e9b3d4d8552f0bbb0f640a7.jpg', 'https://phimimg.com/upload/vod/20251008-1/048fadb3cbf11a3395b22b87df8c1611.jpg', '<p>Huyền thoại võ thuật Marie đã nhận một công việc mới là &quot;người hầu máy móc&quot;... ngoại trừ việc cô là người thật 100%, và Arthur, sếp mới của cô, lại khinh miệt con người. May mắn thay, khuôn mặt vô cảm bẩm sinh của Marie giúp cô tiếp tục vai diễn robot trong khi âm thầm bảo vệ Arthur khỏi những âm mưu ám sát liên miên. Nhưng khi Arthur phải lòng cô hầu gái &quot;hoàn hảo&quot; của mình, mọi thứ nhanh chóng vượt khỏi tầm kiểm soát!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 164, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Nao Toyama","avatar":""},{"name":"Haruki Ishiya","avatar":""},{"name":"Chiaki Kobayashi","avatar":""},{"name":"Yuuichirou Umehara","avatar":""},{"name":"Ami Koshimizu","avatar":""},{"name":"Daishi Kajita","avatar":""},{"name":"Saima Nakano","avatar":""},{"name":"You Taichi","avatar":""},{"name":"Shuntaro Hara","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Rieko Takahashi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["人形机器人玛丽","机械女仆·玛丽","机械女仆玛丽","Kikaijikake no Marie","คิไคจิคาเกะ โนะ มารี","機械女僕‧瑪麗","機械じかけのマリー"]', 1784690324139);
