INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-toi-la-anh-hung-me-toi-la-tinh-linh-con-toi-la-co-gai-chuyen-sinh', 'Bố Tôi Là Anh Hùng, Mẹ Tôi Là Tinh Linh, Còn Tôi Là Cô Gái Chuyển Sinh', 'Dad Is A Hero, Mom Is A Spirit, I''m A Reincarnator', 'https://phimimg.com/upload/vod/20251006-1/193c664574c7c9f070049993aae8efeb.jpg', 'https://phimimg.com/upload/vod/20251006-1/ad76f020597bbcc039aa135bd9e5949f.jpg', '<p>Ellen, một cô bé 8 tuổi mang dòng máu nửa người nửa linh hồn, từng là một nhà khoa học ở Nhật Bản thời hiện đại. Giờ đây, cô được đầu thai vào một gia đình mới: cha cô là Rovel — vị anh hùng huyền thoại của vương quốc, còn mẹ cô là Origin — nữ hoàng của các linh hồn. Không chỉ vậy, bản thân Ellen còn sở hữu năng lực điều khiển các nguyên tố hóa học! Nhưng liệu sức mạnh ấy có đủ để bảo vệ hạnh phúc của gia đình cô hay không?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 164, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Seria Fukagawa","avatar":""},{"name":"Kazuyuki Okitsu","avatar":""},{"name":"Mai Nakahara","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["父亲是英雄，母亲是精灵，身为女儿的我是转生者。","爹猛妈强我无敌","爹强妈猛我无敌","转生后的我成了英雄爸爸和精灵妈妈的女儿","Chichi wa Eiyū, Haha wa Seirei, Musume no Watashi wa Tenseisha","Chichi wa Eiyuu, Haha wa Seirei, Musume no Watashi wa Tenseisha","Hahanoha","Мой Отец - Герой, моя Мать - Королева духов, Я - Перерождённая их дочерью","轉生後的我成了英雄爸爸和精靈媽媽的女兒","My Father Is a Hero, My Mother Is a Spirit and the Daughter (Me) Is a Reincarnator","父は英雄、母は精霊、娘の私は転生者"]', 1784690324139);
