INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-co-kiem-de', 'Vạn Cổ Kiếm Đế', 'The Sword Emperor Of Eternity', 'https://phimimg.com/upload/vod/20250823-1/1388f92d8dc699c924b94f68131b5a14.jpg', 'https://phimimg.com/upload/vod/20250823-1/8c5156e8121aacee7750e0701d18988d.jpg', '<p>Trên đại lục Thần Di, bầu trời cuồn cuộn mây xanh, trăm tộc tranh bá, khói lửa chiến loạn chưa từng ngừng nghỉ. Võ giả được coi trọng, lưỡi phong nhuốm máu, bánh xe vận mệnh đều phải bắt đầu bằng kiếm. Khương Vân từng là vầng dương rực rỡ của võ phủ Thiên Nhất, danh xưng Võ Thủ vang dội khắp hoàng đô. Nhưng hắn lại bị Dạ Thiên hãm hại, võ mạch bị phế, hào quang thiên tài tan thành tro bụi. Thế nhưng thực chất bên trong hắn vẫn có ý chí kiên cường, giúp hắn vươn lên từ nghịch cảnh, Vạn Cổ Kiếm Mạch thức tỉnh, con đường kiếm tu siêu phàm mở ra từ đây.</p>', 'Hoàn Tất (40/40)', 40, 'hoathinh', 'completed', 10, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Wan Gu Jian Di","Древний император меча","万古剑帝"]', 1784690324139);
