INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-tham-bat-tri-mong', 'Vân Thâm Bất Tri Mộng', 'Eclipse Of Illusion', 'https://phimimg.com/upload/vod/20250705-1/113abc54b469d91d1fc4f9e0dbeffed0.jpg', 'https://phimimg.com/upload/vod/20250705-1/d9b4c7bf7cd7c0314e86e8d0ea065519.jpg', '<p>Hôn lễ xa hoa của Vân Vọng Thư bỗng chốc hóa thành một thảm kịch, cả môn phái và gia tộc nàng đều bị tiêu diệt do một âm mưu đã được giăng sẵn. Nàng lết tấm thân rướm máu chạy trốn. Trên bờ vực sinh tử, nàng ký giao ước đổi tim với thế lực bí ẩn “La Dị Các”. 60 năm mai danh ẩn tích, thiếu nữ năm nào giờ hóa thành La Sát đẫm máu, mang danh &quot;Hi Hòa&quot;. Vân Vọng Thư thề sẽ dùng máu kẻ thù cúng tế cho oan hồn môn phái!</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 11, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["云深不知梦","Yun Shen Buzhi Meng","Yun Shen Bu Zhi Meng","운심부지처","Veiled Dreams"]', 1784690324139);
