INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ao-anh-2025', 'Ảo Ảnh', 'The Mirage', 'https://phimimg.com/upload/vod/20251221-1/6365eac49ec903926af8347ce5054980.jpg', 'https://phimimg.com/upload/vod/20251221-1/a48e4ca23f7b59f93db81a7c6d582e0f.jpg', '<p>Trên bầu trời thành Đăng Châu thường xuyên xuất hiện những ảo ảnh hải thị thận lâu thần bí. Nữ tróc đao nhân (người săn tiền thưởng) Tằng Thiến cùng đệ đệ Tằng Tín đang trên đường áp giải phạm nhân đi ngang qua đây, vì gỡ tờ lệnh truy nã &quot;hiệp đạo&quot; Dạ Tiêu mà vô tình bị cuốn vào vòng xoáy thị phi. Trong thành liên tiếp xảy ra những chuyện kỳ quái. Để điều tra chân tướng, Tằng Thiến buộc phải liên thủ cùng Tào Thịnh — một người mưu lược hơn người, Dạ Tiêu — kẻ có thân phận bí ẩn, và Tạ Cảnh Đường — một công tử kiêu ngạo nhưng sở hữu tuyệt kỹ. Trong quá trình hợp tác, cả nhóm đã cùng nhau hóa giải hiểu lầm, tìm kiếm sự thật; họ vừa phải đối đầu với thế lực ẩn danh, vừa phải lựa chọn giữa tình thân, tình bạn và đại nghĩa để vén màn bí mật huyền ảo bao quanh hiện tượng hải thị thận lâu này.</p><p><br/></p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Fei Qiming","avatar":""},{"name":"Lv Xiaoyu","avatar":""},{"name":"Shao Zhuang","avatar":""},{"name":"An Ning","avatar":""},{"name":"Yang Yu","avatar":""},{"name":"Jin Zixuan","avatar":""},{"name":"Bao Zhiqiang","avatar":""},{"name":"Wang Xiaoyi","avatar":""},{"name":"Yu Weini","avatar":""},{"name":"Zheng Qi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["天方夜谭","Mirage Where Illusion Meets Truth","Sky Mirage","The Mirage Where Illusion Meets Truth","海市蜃楼"]', 1784690324139);
