INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-co-the-thinh-cau-mot-dieu-cuoi-cung-khong', 'Tôi Có Thể Thỉnh Cầu Một Điều Cuối Cùng Không?', 'May I Ask for One Final Thing?', 'https://phimimg.com/upload/vod/20251004-1/4e1e1793bb0d43c8dbe259e38b63d05c.jpg', 'https://phimimg.com/upload/vod/20251004-1/95f8d2d4e75da705ea875ec6d3aad0b0.jpg', '<p>Vị hôn phu của Scarlet hủy hôn tại vũ hội rồi vu khống cô. Quá tức giận, cô đưa ra yêu cầu cuối: đấm bay tất cả mọi người.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Asami Seto","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["最后再拜托您一件事可以吗？","最后可以再拜托您一件事吗","さいひと","SaiHito","Saigo ni Hitotsu dake Onegai shitemo Yoroshī Deshō ka","Saigo ni Hitotsu dake Onegai Shite mo Yoroshii Deshou ka","สุดท้ายนี้ขอเพียงอย่างหนึ่งได้ไหมคะ?","Можу попрохати дещо наостанок?","May I Please Ask You Just One Last Thing?","最後にひとつだけお願いしてもよろしいでしょうか"]', 1784690324139);
