INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('toi-co-the-thinh-cau-mot-dieu-cuoi-cung-khong', 'Tôi Có Thể Thỉnh Cầu Một Điều Cuối Cùng Không?', 'May I Ask for One Final Thing?', 'tôi có thể thỉnh cầu một điều cuối cùng không? may i ask for one final thing? asami seto 最后再拜托您一件事可以吗？ 最后可以再拜托您一件事吗 さいひと saihito saigo ni hitotsu dake onegai shitemo yoroshī deshō ka saigo ni hitotsu dake onegai shite mo yoroshii deshou ka สุดท้ายนี้ขอเพียงอย่างหนึ่งได้ไหมคะ? можу попрохати дещо наостанок? may i please ask you just one last thing? 最後にひとつだけお願いしてもよろしいでしょうか', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('taiyou-yori-mo-mabushii-hoshi', 'Taiyou yori mo Mabushii Hoshi', 'A Star Brighter Than The Sun', 'https://phimimg.com/upload/vod/20251011-1/1af82b015df339201063e3ac5efe933d.jpg', 'https://phimimg.com/upload/vod/20251011-1/3da453d1118985d058f0862da029e415.jpg', '<p>Sae Iwata, một cô gái mạnh mẽ hơn mức trung bình một chút, đã phải lòng Koki Kamishiro, cậu bé dịu dàng với nụ cười ấm áp, từ khi còn học tiểu học. Đến khi cả hai bước vào trung học cơ sở, Koki đã trở thành một thiếu niên quyến rũ và nổi tiếng, dường như đã trở nên xa vời với Sae. Khi họ được phân công cùng nhau trong ban tổ chức đại hội thể thao, tình yêu đầu được giấu kín bấy lâu trong lòng Sae bắt đầu trỗi dậy một lần nữa.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Minori Fujidera","avatar":""},{"name":"Yuki Ono","avatar":""},{"name":"Hina Youmiya","avatar":""},{"name":"Taito Ban","avatar":""},{"name":"Mutsumi Tamura","avatar":""},{"name":"Ryota Osaka","avatar":""},{"name":"Haruka Shiraishi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Taiyō Yori mo Mabushii Hoshi","Taiyou Yori mo Mabushii Hoshi","A Star Brighter Than the Sun","太陽よりも眩しい星"]', 1784690324139);
