INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sanda', 'SANDA', 'SANDA', 'https://phimimg.com/upload/vod/20251005-1/10c3c130c797b8fa3a036def9eefac99.jpg', 'https://phimimg.com/upload/vod/20251005-1/76fc3f6c6f3222fd7d2fed2c423fb976.jpg', '<p>Ở Nhật Bản trong tương lai gần, với tỷ lệ sinh cực thấp, trẻ em được trân trọng nhưng bị giám sát chặt chẽ. Ông già Noel bị cấm vì nguy hiểm. Một ngày tuyết rơi dày đặc ngày 25 tháng 12, Kazushige Sanda, học sinh trung học, hậu duệ của Ông già Noel, bị Fuyumura, bạn cùng lớp, tấn công. Fuyumura muốn cậu tìm người bạn mất tích của cô, Ono. &quot;Ông già Noel, làm ơn tìm bạn cháu.&quot; Để bảo vệ trẻ em khỏi người lớn, Sanda quyết định trở thành Ông già Noel và chiến đấu với người lớn.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ayumu Murase","avatar":""},{"name":"Hiroki Touchi","avatar":""},{"name":"Umeka Shouji","avatar":""},{"name":"Anna Nagase","avatar":""},{"name":"Yuuki Shin","avatar":""},{"name":"Misato Matsuoka","avatar":""},{"name":"Toshihiko Seki","avatar":""},{"name":"Hiroaki Hirata","avatar":""},{"name":"Masako Nozawa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["SANDA","サンダ","ซันดะ"]', 1784690324139);
