INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-nua-ranma-phan-2', 'Một Nửa Ranma (Phần 2)', 'Ranma1/2 (Season 2)', 'https://phimimg.com/upload/vod/20251006-1/29313e624c6b831b76fb0a5ce35d2680.jpg', 'https://phimimg.com/upload/vod/20251006-1/6aac8f887bb3084e05408d4c072f30b6.jpg', '<p>Tendo Akane gặp vị hôn phu mới của mình, Saotome Ranma, một thần đồng võ thuật có một bất ngờ: cậu có thể biến thành con gái một cách kỳ diệu khi chạm vào nước lạnh.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 164, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kappei Yamaguchi","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Noriko Hidaka","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ranma ½","乱马½","Nekomoe Kissaten Ranma ½","乱马1/2","Ranma ½ (2024)","Ranma 1-2 (2024)","Ranma 1-2","らんま1／2","Ranma Nibun-no-Ichi","らんま½ (2024)","란마12","란마½","란마1／2","란마 1/2","란마 ½","란마 1／2","Ranma 1/2","Ranma 1/2 (2024)","Ранма 1/2","Ранма 1/2: Ремейк","รันม่า ½","รันม่า 1/2","รันม่าไอ้หนุ่มกังฟู","亂馬 1/2","亂馬½","Ranma One Half","Ranma Half","Ranma One-Half","らんま1/2"]', 1784690324139);
