INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trong-tam-mat', 'Trong Tầm Mắt', 'Beloved', 'https://phimimg.com/upload/vod/20250830-1/449673c7a95ad3281c537e4e35ee6930.jpg', 'https://phimimg.com/upload/vod/20250830-1/a1a9689a2bda6e91c7b373a0343cb201.jpg', '<p>Vào thời điểm giao thoa của thế kỷ, do yêu cầu tích nước của công trình thủy lợi, một thị trấn ven sông sắp bị nhấn chìm. Người dân hối hả tiến hành xây dựng thành phố mới và di dời dân cư. Mùa hè năm 2002, tại thành phố Đông Giang, mưa lớn trút xuống như thác. Một vụ án mạng ly kỳ bất ngờ lọt vào tầm ngắm của cảnh sát: một người tình đã chết, người chồng biến mất rồi lại xuất hiện, họ vừa là “hung thủ” vừa là “người chết”. Cuối cùng, dưới sự truy tra bền bỉ của cảnh sát, một câu chuyện bị chôn vùi suốt nhiều năm dần hé lộ. Sự phức tạp của nhân tính khiến nhiều người bị che mờ đôi mắt, nhưng sự thật sẽ không bao giờ bị nhấn chìm — trong tầm mắt, tất cả đều là ánh sáng.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"La Tấn","avatar":""},{"name":"Vương Tử Văn","avatar":""},{"name":"Dư Nam","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["目之所及"]', 1784690324139);
