INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('o-ben-em-tinh-quang-2025', 'Ở Bên Em (Tinh Quang)', 'Be With You', 'https://phimimg.com/upload/vod/20251221-1/19d4181f0779d6655eb85919f95d5041.jpg', 'https://phimimg.com/upload/vod/20251221-1/4f17060fa3ce0492df2ca150c0efe17e.jpg', '<p>Nữ diễn viên trẻ Doãn San San vốn có sự nghiệp thuận lợi và tình yêu ngọt ngào, nhưng chỉ trong một ngày, cô liên tiếp gặp phải hàng loạt biến cố: hình tượng sụp đổ, khủng hoảng dư luận và bị bạn trai chia tay. Sau một tai nạn ngã lầu, cô kinh ngạc phát hiện mình liên tục quay trở lại buổi sáng ngày hôm đó, rơi vào một vòng lặp thời gian vô tận.Trong nỗ lực phá vỡ vòng lặp, cô đã tìm cách &quot;chinh phục&quot; Thẩm Gia Khâm — ông chủ khách sạn đầy bí ẩn. Cuối cùng, cô không chỉ thoát khỏi vòng lặp thời gian mà còn khám phá ra một sự thật chấn động đằng sau tất cả...</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Mộc Thần","avatar":""},{"name":"Lưu Dực Sướng","avatar":""},{"name":"Ngô Sùng Hiên","avatar":""},{"name":"Lữ Tiểu Vũ","avatar":""},{"name":"Vương Nhất Phi","avatar":""},{"name":"La Sở Phàm","avatar":""},{"name":"Hạ Tuấn Hùng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Xing Guang","星光予你","Starlight to You","星光"]', 1784690324139);
