INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('o-ben-em-tinh-quang-2025', 'Ở Bên Em (Tinh Quang)', 'Be With You', 'ở bên em (tinh quang) be with you lý mộc thần lưu dực sướng ngô sùng hiên lữ tiểu vũ vương nhất phi la sở phàm hạ tuấn hùng xing guang 星光予你 starlight to you 星光', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-chua-muon-thang-tien', 'Quận Chúa Muốn Thăng Tiến', 'Princess Level Up!', 'https://phimimg.com/upload/vod/20251221-1/bc7d47c856c5f6ff47b51b4fa5624666.jpg', 'https://phimimg.com/upload/vod/20251221-1/e6cd9ae459280f9a51583921eaedeef2.jpg', '<p>Đây là bản dịch tiếng Việt cho cốt truyện phim (hoặc tiểu thuyết) của bạn, sử dụng văn phong kịch tính và phù hợp với thể loại xuyên không:Bản dịch:Trợ lý nhỏ Tang Hạ vốn luôn bị đại minh tinh Yến Sở Đình hành hạ đủ đường, bỗng tình cờ xuyên không vào bộ phim đang quay. Cô trở thành Trường quận chúa thời cổ đại và phải tìm ra kẻ thủ ác ẩn nấp trong số năm ứng cử viên phu quân trước ngày đại hôn, nếu không cô sẽ mất mạng và rơi vào vòng lặp cốt truyện vô tận.Dù mang tư duy hiện đại, Tang Hạ vẫn phải đối phó với sự thúc giục hôn sự từ Mẫu hậu và lòng đố kỵ của Nhị quận chúa Tang Nhã. Đồng thời, cô luôn đầy nghi hoặc và tìm cách thử thách người bạn học Yến Sở Đình — người có dung mạo giống hệt bạn trai cũ của cô.Trong quá trình đó, Tang Hạ buộc phải xoay xở giữa năm ứng cử viên đầy dã tâm như Mộ Hàn và Phó Vận Tây. Một mặt, cô hóa thân thành &quot;đóa hoa sen đen&quot; tìm cách loại bỏ từng người; mặt khác, cô cùng Yến Sở Đình chuyển từ nghi kỵ sang hợp tác, vạch trần tội ác của Mộ Hàn và hóa giải những cạm bẫy của các ứng cử viên khác.Tuy nhiên, cục diện ngày càng phức tạp: Phó Vận Tây bị Lưu Nghĩa Thủ sát hại, thế lực của tộc họ Lưu bắt đầu đe dọa hoàng quyền. Lúc này, sự thật chấn động được hé lộ: Mẫu hậu không phải mẹ ruột của Tang Hạ, bà ta đang âm mưu đoạt vị cho con gái ruột là Tang Nhã. Cuối cùng, với sự trợ giúp của Đế sư Tiêu Vũ, Tang Hạ và Yến Sở Đình đã dẹp loạn do Tang Nhã gây ra và cùng nhau trở về thế giới hiện đại.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Liu Yiqi","avatar":""},{"name":"Han Xiaoyao","avatar":""},{"name":"Deng Zhihao","avatar":""},{"name":"Deng Qingzhou","avatar":""},{"name":"Li Dongyang","avatar":""},{"name":"Chen Peisu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["这个郡主不简单","This Princess Is Not Simple","The County Lord Is About to Get Promoted","Princess Level Up!","郡主要升咖"]', 1784690324139);
