INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('quan-chua-muon-thang-tien', 'Quận Chúa Muốn Thăng Tiến', 'Princess Level Up!', 'quận chúa muốn thăng tiến princess level up! liu yiqi han xiaoyao deng zhihao deng qingzhou li dongyang chen peisu 这个郡主不简单 this princess is not simple the county lord is about to get promoted princess level up! 郡主要升咖', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lua-chay-tren-song', 'Lửa Cháy Trên Sông', 'River Accompanies Fire', 'https://phimimg.com/upload/vod/20251221-1/b0f05c846ec4d4d4161fa022584eeb95.jpg', 'https://phimimg.com/upload/vod/20251221-1/f9d6409507cff76e8652155f0b515a9c.jpg', '<p>Để tìm kiếm người chị mất tích là Khương Thư Vãn, sinh viên y khoa Khương Nguyện Nguyệt đã đổi tên thành Yến Nhiễm và tiếp cận nhị thiếu gia nhà họ Tằng là Tằng Nguyên Khải, thành công bước chân vào Tằng phủ với thân phận nha hoàn của anh ta. Sau nhiều lần tìm kiếm, Khương Yến Nhiễm phát hiện ra thi thể của chị gái bị chôn vùi tại một viện hoang trong nhà họ Tằng, cô liền khoanh vùng nghi phạm vào hai anh em nhà họ Tằng. Thông qua cái chết của Trần Thục Lâm, Yến Nhiễm và Tằng Nguyên Khải đã phát hiện ra bộ mặt thật độc ác, tàn tận của gia chủ Tằng Thiếu Tông, cũng như sự thật rằng ông ta chính là kẻ đã hại chết Khương Vận Văn và mẹ ruột của Tằng Nguyên Khải là Cố Mạn Thanh, đồng thời ông ta cũng không phải cha ruột của Tằng Nguyên Khải.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Ruipin","avatar":""},{"name":"Huang Bangjun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jiang Huo Cheng Ran","江火澄燃"]', 1784690324139);
