INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hao-quang-cua-co-ay', 'Hào Quang Của Cô Ấy', 'Her Radiance', 'https://phimimg.com/upload/vod/20251221-1/0ceefba1883da931ddf0697d60092a92.jpg', 'https://phimimg.com/upload/vod/20251221-1/abb161abf1b916a96be22d4ee02df636.jpg', '<p>Sinh viên y khoa Khương Nguyện Nguyệt vì muốn tìm kiếm người chị gái mất tích là Khương Thư Vãn, đã đổi tên thành Yến Nhiễm và tiếp cận nhị thiếu gia nhà họ Tăng là Tăng Nguyên Khải. Cô thành công thâm nhập vào Tăng gia với thân phận nha hoàn của Nguyên Khải.Sau nhiều lần tìm kiếm, Yến Nhiễm bàng hoàng phát hiện thi thể của chị gái bị chôn vùi trong một khu viện bỏ hoang của nhà họ Tăng. Ban đầu, cô đưa hai anh em nhà họ Tăng vào tầm ngắm nghi vấn. Tuy nhiên, thông qua cái chết của Trần Thục Lâm, Yến Nhiễm và Tăng Nguyên Khải đã cùng nhau vạch trần bộ mặt thật tàn ác của gia chủ Tăng Thiếu Tông. Họ phát hiện ra chính ông ta là hung thủ hại chết Khương Vận Văn và mẹ ruột của Tăng Nguyên Khải là Cố Mạn Thanh. Đồng thời, một sự thật chấn động khác cũng được hé lộ: Tăng Thiếu Tông hoàn toàn không phải cha ruột của Tăng Nguyên Khải.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cheng Jinming","avatar":""},{"name":"Xu Nuoyan","avatar":""},{"name":"Liu Xuancheng","avatar":""},{"name":"Cao Xiyue","avatar":""},{"name":"Yi Daqian","avatar":""},{"name":"Hao Zejia","avatar":""},{"name":"You Jiawei","avatar":""},{"name":"Xu Yijia","avatar":""},{"name":"Yuan Liuzhe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["诱宠","誘寵","Love Ardently","她的光芒"]', 1784690324139);
