INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hao-quang-cua-co-ay', 'Hào Quang Của Cô Ấy', 'Her Radiance', 'hào quang của cô ấy her radiance cheng jinming xu nuoyan liu xuancheng cao xiyue yi daqian hao zejia you jiawei xu yijia yuan liuzhe 诱宠 誘寵 love ardently 她的光芒', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-khau-tai-ho-gap-go-tai-van-khau', 'Vân Khâu Tái Hộ (Gặp Gỡ Tại Vân Khâu)', 'Rendezvous At Yunqiu Mountain', 'https://phimimg.com/upload/vod/20251221-1/f8c8aace169e6eace3ae6ff6e7205245.jpg', 'https://phimimg.com/upload/vod/20251221-1/5d3a221cce83d10e4df01c330d48dd88.jpg', '<p>Lâm Tịnh là người thừa kế của tập đoàn Lục Diệp, tính cách cương nghị nhưng lại bị phản bội ngay khi đang ở đỉnh cao sự nghiệp. Tô Hiểu Mộng là nhân viên của một homestay, tính tình dịu dàng nhưng lại đang lún sâu vào vũng bùn rắc rối của gia đình. Một sự cố tình cờ liên quan đến vật phẩm thần kỳ &quot;Định Động Thần Châm&quot; đã khiến hai người hoán đổi cuộc đời cho nhau.Lâm Tịnh biến thành một nhân viên phục vụ bình thường, nhưng bằng tầm nhìn nhạy bén và sự quyết đoán, cô đã giúp homestay lột xác hoàn toàn. Trong khi đó, Tô Hiểu Mộng vụt sáng thành tinh anh thương trường, dùng sự chân thành và quan tâm để giúp tập đoàn Lục Diệp tràn đầy sức sống.Trong hành trình này, Lâm Tịnh gặp gỡ nghệ nhân nấu rượu Lục Tiêu, còn Tô Hiểu Mộng nhận được sự bảo vệ từ thuộc cấp Hàn Tử Minh. Sau khi trải qua nhiều sóng gió, cả hai hoàn toàn thoát khỏi những kẻ tồi tệ và xiềng xích của gia đình. Khi gặp lại vật phẩm thần kỳ, họ trở về vị trí cũ nhưng đều đã trưởng thành, tìm thấy tình yêu đích thực và tìm lại được sơ tâm đã mất của mình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ma Li","avatar":""},{"name":"Sun Yanqing","avatar":""},{"name":"Chen Minghao","avatar":""},{"name":"Rong Zicheng","avatar":""},{"name":"Wang Xi","avatar":""},{"name":"Anna","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yunqiu Encounter","云丘邂逅"]', 1784690324139);
