INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phien-cho-cua-quy', 'Phiên Chợ Của Quỷ', 'The Cursed: Insatiable Desires', 'https://phimimg.com/upload/vod/20251220-1/0b7449948edc2dd900127611fa8f2dbe.jpg', 'https://phimimg.com/upload/vod/20251220-1/558deebe9306d507b6b9ccfce65a93aa.jpg', '<p>Phiên chợ của quỷ - Nơi linh hồn trở thành những món hàng để thỏa mãn tham vọng của con người. Mỗi đêm, cổng chợ âm sẽ mở, quỷ sẽ bắt hồn. Một khi đã dám bán rẻ linh hồn, cái giá phải trả có thể là máu, là thịt, hoặc chính sự tồn tại của những kẻ dám liều mạng. Nỗi ám ảnh không lối thoát với phim tâm linh - kinh dị hợp tác Việt - Hàn quỷ dị nhất dịp cuối năm!</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"Moon Chae-won","avatar":""},{"name":"Won Hyun-jun","avatar":""},{"name":"You Chea-myung","avatar":""},{"name":"Cha Sun-woo","avatar":""},{"name":"Seo Young-hee","avatar":""},{"name":"Sumin","avatar":""},{"name":"Solar","avatar":""},{"name":"Seo Ji-soo","avatar":""},{"name":"Son Ju-yeon","avatar":""},{"name":"Choi Bo-min","avatar":""},{"name":"Ngọc Xuân","avatar":""},{"name":"Emma Lê","avatar":""},{"name":"Hứa Vĩ Văn","avatar":""},{"name":"Đinh Y Nhung","avatar":""},{"name":"Sophie Tường Vy","avatar":""},{"name":"Ngọc Khoa","avatar":""},{"name":"Trần Hữu Thiện","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["고리: 어 호러 테일","Gory: A Horror Tale","Phiên Chợ Của Quỷ","귀시: 확장판","THE CURSED","귀시"]', 1784690324139);
