INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phien-cho-cua-quy', 'Phiên Chợ Của Quỷ', 'The Cursed: Insatiable Desires', 'phiên chợ của quỷ the cursed: insatiable desires moon chae-won won hyun-jun you chea-myung cha sun-woo seo young-hee sumin solar seo ji-soo son ju-yeon choi bo-min ngọc xuân emma lê hứa vĩ văn đinh y nhung sophie tường vy ngọc khoa trần hữu thiện 고리: 어 호러 테일 gory: a horror tale phiên chợ của quỷ 귀시: 확장판 the cursed 귀시', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-cach-bua-trua-cua-hiroshi-nohara', 'Phong Cách Bữa Trưa Của Hiroshi Nohara', 'Style Of Hiroshi Nohara''s Lunch', 'https://phimimg.com/upload/vod/20251012-1/97ed100310e04e4ef8cb2889dd571fff.jpg', 'https://phimimg.com/upload/vod/20251012-1/7974bcf1de05ab08bab84f994495cf71.jpg', '<p>Bắc Di dùng mưu kế tập kích bất ngờ vào Bạch Thành – trọng trấn biên giới phía bắc của Đại Tề quốc. Tướng thủ thành Đường Nghiêu dẫn quân tử chiến chống địch, nhưng vì lực lượng quá chênh lệch, toàn quân hy sinh, chỉ còn lại nhị tiểu thư Đường Anh may mắn sống sót. Điều khiến Đường Anh càng thêm bi phẫn là cha nàng hy sinh vì nước, nhưng đổi lại lại bị mang tội thông đồng với địch. Để minh oan cho cha, Đường Anh một mình xông vào kinh đô, song phát hiện mọi chuyện không hề đơn giản như tưởng tượng. Liệu hoàng tử thứ hai của Đại Tề quốc – Nguyên Lăng – có liên quan đến Bắc Di hay không? Tại sao lại có một cô gái giả mạo nàng với dung mạo giống hệt mình một cách kỳ lạ? “Người từ thế giới khác” mà Yêu Nương của Ảnh Bộ nhắc đến là ai? Và những ký ức vừa xa lạ vừa quen thuộc luôn ám ảnh nàng rốt cuộc là gì?... Quá nhiều bí ẩn đang chờ Đường Anh từng bước vén màn giải đáp.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 163, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Toshiyuki Morikawa","avatar":""},{"name":"Takuya Masumoto","avatar":""},{"name":"Kana Ichinose","avatar":""},{"name":"Mahiro Takasugi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["野原广志 午餐的流派","Nohara Hiroshi: Hiru Meshi no Ryugi","Nohara Hiroshi Hirumeshi no Ryuugi","Nohara Hiroshi Hirumeshi no Ryūgi","Style of Hiroshi Nohara LUNCH","野原ひろし 昼メシの流儀"]', 1784690324139);
