INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuoc-phim-ma-quai', 'Thước Phim Ma Quái', 'Posthouse', 'https://phimimg.com/upload/vod/20251211-1/f6d631af310b12dc5f9dd169e8ae3e17.jpg', 'https://phimimg.com/upload/vod/20251211-1/5050bfc964a2aa61a30445e2f79c6b88.jpg', '<p>Một biên tập viên và con gái dốc sức khôi phục một vật gia truyền – một cuốn phim câm kinh dị cũ – nào ngờ mỗi khung hình lại đưa họ đến gần hơn với một linh hồn đen tối.</p>', 'Full', 1, 'single', 'completed', 25, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Philippines', 0, '[{"name":"Sid Lucero","avatar":""},{"name":"Bea Binene","avatar":""},{"name":"Rafa Siguion-Reyna","avatar":""},{"name":"Rob Rownd","avatar":""},{"name":"Carlos Siguion-Reyna","avatar":""},{"name":"DMs Boongaling","avatar":""},{"name":"Ryza Cenon","avatar":""},{"name":"John Patrick Petilo","avatar":""},{"name":"Andrea Del Rosario","avatar":""},{"name":"John Christopher Ventura","avatar":""},{"name":"Hasna Cabral","avatar":""},{"name":"Katrina Villarin","avatar":""},{"name":"Bobby Bonifacio","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Posthouse"]', 1784690324139);
