INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-dang-2025', 'Mật Đắng', 'Bitter Honeymoon', 'https://phimimg.com/upload/vod/20251220-1/42cbdcf15de48009449111885f026fd6.jpg', 'https://phimimg.com/upload/vod/20251220-1/bbf359707f9cec53734f50e2492a46e2.jpg', '<p>Khi tình yêu giữa Purim và Rose biến từ đóa hồng ngọt ngào của vị tình, trở thành đóa hồng đầy gai nhọn của nỗi đau, anh đã giữ nỗi dày vò do những chiếc gai ấy đâm vào tim suốt nhiều năm trời. Từng ngày, anh nuôi dưỡng nỗi đau ấy, để nó kết tinh thành phấn hoa của sự tổn thương, hòa tan thành mật đắng – thứ mật sẵn sàng dùng để hủy hoại kẻ thù. Cho đến khi Purim gặp Kangsadan, con gái của Rose, anh không chần chừ mang những chiếc gai thấm mật đắng trong quá khứ ra làm vũ khí báo thù hai mẹ con. Thế nhưng cuối cùng, Purim lại thất bại trước chính con tim mình – anh thua trước sự chân thành, trong sáng và tốt bụng của Kangsadan, cô gái là con của người phụ nữ từng để lại vết thương sâu trong lòng anh.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Pakorn Lam","avatar":""},{"name":"Preeyakarn Jaikanta","avatar":""},{"name":"Katreeya English","avatar":""},{"name":"Rinlanee Sripen","avatar":""},{"name":"Passin Reungwoot","avatar":""},{"name":"Ekkaphong Jongkesakorn","avatar":""},{"name":"Jintanutda Lummakanon","avatar":""},{"name":"Tadsapon Wiwitawan","avatar":""},{"name":"Kamonchanok Rodsatien","avatar":""},{"name":"Sansanee Wattananukul","avatar":""},{"name":"Daraneenute Pasutanavin","avatar":""},{"name":"Deejai Dididi","avatar":""},{"name":"Parnlekha Wanmua","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Nam Phueng Khom","Bitter Honey","น้ำผึ้งขม"]', 1784690324139);
