INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mat-dang-2025', 'Mật Đắng', 'Bitter Honeymoon', 'mật đắng bitter honeymoon pakorn lam preeyakarn jaikanta katreeya english rinlanee sripen passin reungwoot ekkaphong jongkesakorn jintanutda lummakanon tadsapon wiwitawan kamonchanok rodsatien sansanee wattananukul daraneenute pasutanavin deejai dididi parnlekha wanmua nam phueng khom bitter honey น้ำผึ้งขม', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-han-gacha', 'Vô Hạn Gacha', 'My Gift Lvl 9999 Unlimited Gacha: Backstabbed In A Backwater Dungeon, I''m Out For Revenge!', 'https://phimimg.com/upload/vod/20251004-1/9becdbc1026fd26dbff4fe1076a09877.jpg', 'https://phimimg.com/upload/vod/20251004-1/34fa41b21a6beb9aa5dbcf377c9c6e88.jpg', '<p>Ngày xưa, Nữ thần đã tạo ra chín chủng tộc. Trong số đó, loài người là chủng tộc yếu nhất và bị chế giễu. Cậu bé loài người Light đã may mắn được chào đón vào một nhóm mạo hiểm giả được thành lập từ chín chủng tộc, mang tên &quot;&quot;Chủng Tộc Tụ Hội&quot;&quot;, và đã có một khoảng thời gian vui vẻ. Tuy nhiên, đó chỉ là một ảo mộng phù du. Điều chờ đợi cậu là sự phản bội tại &quot;&quot;Vực Thẳm&quot;&quot; - hầm ngục lớn nhất và tồi tệ nhất thế giới.

Sống sót ở tận cùng Vực Thẳm, Light đã khám phá ra sức mạnh thật sự của thiên phú &quot;&quot;Vô Hạn Gacha&quot;&quot; của mình. Vươn lên từ vực sâu của tuyệt vọng, Light sẽ xây dựng vương quốc mạnh nhất. Với ân huệ độc nhất vô nhị là &quot;&quot;Vô Hạn Gacha&quot;&quot; trong tay, câu chuyện trả thù của cậu chính thức bắt đầu!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Nina Tamaki","avatar":""},{"name":"Ikumi Hasegawa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["差点在迷宫深处被信任的伙伴杀掉，但靠着天赐技能“无限扭蛋”获得等级9999的伙伴，我要向前队友和世界展开复仇&“给他们好看！”","遭队友背叛，靠“无限扭蛋”复仇","无限抽卡","差点在迷宫深处被信任的伙伴杀掉，但靠着天赐技能「无限扭蛋」获得等级9999的伙伴，我要向前队友和世界展开复仇&「给他们好看！」","无限扭蛋","Sono stato quasi ammazzato in fondo al dungeon dai compagni in cui credevo tanto, ma grazie al dono ''gacha infinito'' ho ottenuto compagne di livello 9999 e ora mi vendicherò sugli ex membri del party e sul mondo & dicendogli \"ben vi sta!\"","Shinjiteita Nakama-tachi ni Dungeon Okuchi de Korosarekaketa ga Gift \"Mugen Gacha\" de Level 9999 no Nakama-tachi o Te ni Irete Moto Party Member to Sekai ni Fukushuu & \"Zamaa!\" Shimasu!","しんじていたなかまたちにだんじょんおくちでころされかけたがぎふとむげんがちゃでれべるきゅうせんきゅうひゃくきゅうじゅうきゅうのなかまたちをてにいれてもとぱーてぃーめんばーとせかいにふくしゅうあんどざまぁします","Mugen Gacha","無限ガチャ","Shinjiteita Nakamatachi ni Dungeon Okuchi de Korosarekaketa ga Gift \"Mugen Gacha\" de Level 9999 no Nakamatachi wo Te ni Irete Moto Party Member to Sekai ni Fukushuu & \"Zamaa!\" Shimasu!","Shinjiteita Nakama-tachi ni Dungeon Okuchi de Korosarekaketa ga Gift \"Mugen Gacha\" de Level 9999 no Nakama-tachi wo Te ni Irete Moto Party Member to Sekai ni Fukushuu & \"Zamaa!\" Shimasu!","ギフト無限ガチ","믿었던 동료들에게 던전 오지에서 살해당할 뻔했지만 기프트 『무한 가챠』로 레벨 9999의 동료들을 손에 넣어 전 파티 멤버와 세계에 복수& 『참교육!』합니다!","Мене зрадили товариші в глибині підземелля, але завдяки своїй навичці «Нескінченна ґача» я здобув союзників 9999 рівня, щоб помститися колишнім соратникам і всьому світу!","Backstabbed in a Backwater Dungeon","Backstabbed in a Backwater Dungeon: My Trusted Companions Tried to Kill Me, But Thanks to the Gift of an Unlimited Gacha I Got LVL 9999 Friends and Am Out For Revenge on My Former Party Members and the World","My Gift Lvl 9999 Unlimited Gacha","My Gift Lvl 9999 Unlimited Gacha: Backstabbed in a Backwater Dungeon, I''m Out for Revenge!","Gacha Vô Hạn Cấp 9999","Gacha Vô Hạn","Vô Hạn Gacha","信じていた仲間達にダンジョン奥地で殺されかけたがギフト『無限ガチャ』でレベル9999の仲間達を手に入れて元パーティーメンバーと世界に復讐＆『ざまぁ！』します！"]', 1784690324139);
