INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vo-han-gacha', 'Vô Hạn Gacha', 'My Gift Lvl 9999 Unlimited Gacha: Backstabbed In A Backwater Dungeon, I''m Out For Revenge!', 'vô hạn gacha my gift lvl 9999 unlimited gacha: backstabbed in a backwater dungeon, i''m out for revenge! nina tamaki ikumi hasegawa 差点在迷宫深处被信任的伙伴杀掉，但靠着天赐技能“无限扭蛋”获得等级9999的伙伴，我要向前队友和世界展开复仇&“给他们好看！” 遭队友背叛，靠“无限扭蛋”复仇 无限抽卡 差点在迷宫深处被信任的伙伴杀掉，但靠着天赐技能「无限扭蛋」获得等级9999的伙伴，我要向前队友和世界展开复仇&「给他们好看！」 无限扭蛋 sono stato quasi ammazzato in fondo al dungeon dai compagni in cui credevo tanto, ma grazie al dono ''gacha infinito'' ho ottenuto compagne di livello 9999 e ora mi vendicherò sugli ex membri del party e sul mondo & dicendogli "ben vi sta!" shinjiteita nakama-tachi ni dungeon okuchi de korosarekaketa ga gift "mugen gacha" de level 9999 no nakama-tachi o te ni irete moto party member to sekai ni fukushuu & "zamaa!" shimasu! しんじていたなかまたちにだんじょんおくちでころされかけたがぎふとむげんがちゃでれべるきゅうせんきゅうひゃくきゅうじゅうきゅうのなかまたちをてにいれてもとぱーてぃーめんばーとせかいにふくしゅうあんどざまぁします mugen gacha 無限ガチャ shinjiteita nakamatachi ni dungeon okuchi de korosarekaketa ga gift "mugen gacha" de level 9999 no nakamatachi wo te ni irete moto party member to sekai ni fukushuu & "zamaa!" shimasu! shinjiteita nakama-tachi ni dungeon okuchi de korosarekaketa ga gift "mugen gacha" de level 9999 no nakama-tachi wo te ni irete moto party member to sekai ni fukushuu & "zamaa!" shimasu! ギフト無限ガチ 믿었던 동료들에게 던전 오지에서 살해당할 뻔했지만 기프트 『무한 가챠』로 레벨 9999의 동료들을 손에 넣어 전 파티 멤버와 세계에 복수& 『참교육!』합니다! мене зрадили товариші в глибині підземелля, але завдяки своїй навичці «нескінченна ґача» я здобув союзників 9999 рівня, щоб помститися колишнім соратникам і всьому світу! backstabbed in a backwater dungeon backstabbed in a backwater dungeon: my trusted companions tried to kill me, but thanks to the gift of an unlimited gacha i got lvl 9999 friends and am out for revenge on my former party members and the world my gift lvl 9999 unlimited gacha my gift lvl 9999 unlimited gacha: backstabbed in a backwater dungeon, i''m out for revenge! gacha vô hạn cấp 9999 gacha vô hạn vô hạn gacha 信じていた仲間達にダンジョン奥地で殺されかけたがギフト『無限ガチャ』でレベル9999の仲間達を手に入れて元パーティーメンバーと世界に復讐＆『ざまぁ！』します！', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-sat-bien-tokyo', 'Cảnh Sát Biển Tokyo', 'Tokyo Water Police', 'https://phimimg.com/upload/vod/20251203-1/6269267c1da7b03ca96b2d1a5a00ffd5.jpg', 'https://phimimg.com/upload/vod/20251203-1/134ed3443abc857700483ee9320d7f99.jpg', '<p>Lực lượng Cảnh sát Biển Tokyo được thành lập nhằm đối phó với tình trạng tội phạm trên biển ngày càng gia tăng ở những khu vực ít được tuần tra — trái ngược với sự giám sát nghiêm ngặt trên đất liền. Đội ngũ này quy tụ những con người khác biệt: một chỉ huy kỳ cựu, một thám tử chuyển công tác đầy tham vọng, và một kỹ sư hàng hải tài năng. Giữa những mâu thuẫn ban đầu, họ dần tìm thấy sức mạnh trong sự đoàn kết, cùng nhau phá án các vụ tội phạm ven biển và bảo vệ vùng nước của Tokyo.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ryuta Sato","avatar":""},{"name":"Shigeaki Kato","avatar":""},{"name":"Mizuki Yamashita","avatar":""},{"name":"Akiyoshi Nakao","avatar":""},{"name":"Ryu Saito","avatar":""},{"name":"Leo Matsumoto","avatar":""},{"name":"Sayaka Yamaguchi","avatar":""},{"name":"Hayato Kakizawa","avatar":""},{"name":"Jun Hasegawa","avatar":""},{"name":"Ayumi Tanida","avatar":""},{"name":"Takashi Kobayashi","avatar":""},{"name":"Sarutoki Minagawa","avatar":""},{"name":"Kippei Shiina","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shin Tokyo Suijo Keisatsu","신도쿄 수상 경찰","New Tokyo Water Police","新東京水上警察"]', 1784690324139);
