INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('canh-sat-bien-tokyo', 'Cảnh Sát Biển Tokyo', 'Tokyo Water Police', 'cảnh sát biển tokyo tokyo water police ryuta sato shigeaki kato mizuki yamashita akiyoshi nakao ryu saito leo matsumoto sayaka yamaguchi hayato kakizawa jun hasegawa ayumi tanida takashi kobayashi sarutoki minagawa kippei shiina shin tokyo suijo keisatsu 신도쿄 수상 경찰 new tokyo water police 新東京水上警察', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-thu-tham-an-va-cong-tuoc-ma-ca-rong', 'Tiểu Thư Tham Ăn Và Công Tước Ma Cà Rồng', 'Pass The Monster Meat, Milady!', 'https://phimimg.com/upload/vod/20251003-1/c90ae366a8ab0690adbe00849096b9c5.jpg', 'https://phimimg.com/upload/vod/20251003-1/276b461808d8e71a1c6f0042458f7b6c.jpg', '<p>Bất kỳ tiểu thư quý tộc đúng mực nào cũng phải nuôi dưỡng những sở thích tinh tế, và món khoái khẩu của tiểu thư Melphiera lại là… quái vật! Thật không may, xã hội coi thường những ham muốn chẳng đoan trang này và gán cho nàng danh hiệu “Nữ phản diện háu đói.” Trong một buổi yến tiệc, nàng bị quái vật tấn công, nhưng lại được cứu bởi “Công tước Cuồng Huyết” đáng sợ. Hắn tàn nhẫn, bí ẩn nhưng cuốn hút. Liệu hắn có phải là người có thể thấu hiểu cơn thèm khát quái dị của nàng?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 400, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kanna Nakamura","avatar":""},{"name":"Taito Ban","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Akujiki Reijou to Kyouketsu Koushaku: Sono Mamono, Watashi ga Oishiku Itadakimasu!","The Gluttonous Daughter and the Mad-Blooded Duke ~I''ll make that monster delicious!~","悪食令嬢と狂血公爵 ～その魔物、私が美味しくいただきます!～"]', 1784690324139);
