INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tieu-thu-tham-an-va-cong-tuoc-ma-ca-rong', 'Tiểu Thư Tham Ăn Và Công Tước Ma Cà Rồng', 'Pass The Monster Meat, Milady!', 'tiểu thư tham ăn và công tước ma cà rồng pass the monster meat, milady! kanna nakamura taito ban akujiki reijou to kyouketsu koushaku: sono mamono, watashi ga oishiku itadakimasu! the gluttonous daughter and the mad-blooded duke ~i''ll make that monster delicious!~ 悪食令嬢と狂血公爵 ～その魔物、私が美味しくいただきます!～', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-van-phong-vu', 'Lôi Vân Phong Vũ', 'Thundercloud Rainstorm', 'https://phimimg.com/upload/vod/20251130-1/92fa803e7779fcbc46c19529d68ba586.jpg', 'https://phimimg.com/upload/vod/20251130-1/2b907377690e4f52e4ef0cfa8be24f0b.jpg', '<p>Bị ràng buộc bởi một món nợ, một người con ngoài giá thú chuyển đến sống chung với người anh họ lạnh lùng của mình.&nbsp; Anh không hề hay biết rằng thỏa thuận miễn cưỡng ban đầu của họ sẽ dần dần phát triển thành một mối ám ảnh sâu sắc và nguy hiểm.</p>', 'Tập 8', 8, 'series', 'ongoing', 14, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yoon Ji-sung","avatar":""},{"name":"Jeong Ri-u","avatar":""},{"name":"Jang Won-hyuk","avatar":""},{"name":"Lee Dong-ju","avatar":""},{"name":"Hwang Seong-yun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["雷云风雨","雷雲と雨風","Chondunggureum Bibaram","เมฆครึ้มและลมฝน","雷雲風雨","천둥구름 비바람"]', 1784690324139);
