INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('loi-van-phong-vu', 'Lôi Vân Phong Vũ', 'Thundercloud Rainstorm', 'lôi vân phong vũ thundercloud rainstorm yoon ji-sung jeong ri-u jang won-hyuk lee dong-ju hwang seong-yun 雷云风雨 雷雲と雨風 chondunggureum bibaram เมฆครึ้มและลมฝน 雷雲風雨 천둥구름 비바람', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuong-thuong-te-mi', 'Chưởng Thượng Tề Mi', 'Aligned Reverence', 'https://phimimg.com/upload/vod/20251211-1/cd65958b10acff6f9c7a795bbdf65ec8.jpg', 'https://phimimg.com/upload/vod/20251211-1/3be6877c59eae59adc44c6f9f94b78f5.jpg', '<p>Cô nhi Tô Cẩm Nguyên tin lầm kẻ gian, bỏ trốn khỏi hôn lễ và gây ra họa lớn. Khi trở về, cô kinh hoàng chứng kiến gia đình ân nhân là nhà họ Tiêu gặp thảm họa diệt môn.&nbsp; Để chuộc lại tội lỗi, cô và Tạ Vân Yến, con nuôi nhà họ Tiêu, người đã thay anh trai kết hôn, bị vận mệnh cuốn lấy nhau. Họ cùng nhau sinh tồn trong tuyệt cảnh, phá vỡ xiềng xích thế tục, lật mặt kẻ thù, và viết nên một thiên tình sử đẫm máu, nghịch thiên cải mệnh.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 13, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đặng Hiểu Tư","avatar":""},{"name":"Tôn Nghệ Nhiên","avatar":""},{"name":"Lê Thánh Huyên","avatar":""},{"name":"Âu Tịnh Kiêu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["掌上齐眉"]', 1784690324139);
