INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-nha-ben', 'Biệt Đội Nhà Bên', 'Heroes Next Door', 'https://phimimg.com/upload/vod/20251118-1/f74e8fdad8f21291ecaf4b1416cf410b.jpg', 'https://phimimg.com/upload/vod/20251118-1/8df208822581a9dae6e43c5aaf7e7042.jpg', '<p>Bộ phim xoay quanh một nhóm các cựu quân nhân đặc biệt (UDT, chống khủng bố...) đang cố gắng sống một cuộc đời bình dị như những người hàng xóm bình thường. Tuy nhiên, khi gia đình và khu phố của họ bị đe dọa, bản năng anh hùng &quot;ngủ quên&quot; của họ trỗi dậy. Một tổ đội &quot;bất đắc dĩ&quot; được thành lập, bao gồm cựu đặc nhiệm Choi Kang (Yoon Kye Sang), cựu lính chống khủng bố Kwak Byeong Nam (Jin Sun Kyu), bà chủ siêu thị &quot;hổ báo&quot; Jung Nam Yeon (Kim Ji Hyun), võ sư &quot;nửa mùa&quot; Lee Yong Hee (Go Gyu Pil) và thiên tài kỹ thuật Park Jung Hwan (Lee Jung Ha). Họ cùng nhau chiến đấu để bảo vệ những gì thân yêu nhất.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 10, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yoon Kye-sang","avatar":""},{"name":"Jin Sun-kyu","avatar":""},{"name":"Kim Ji-hyun","avatar":""},{"name":"Ko Kyu-phil","avatar":""},{"name":"Lee Jung-ha","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["UDT：我们小区特工队","UDT","الأبطال بجوارنا","UDT：我們社區特攻隊","Heroes Next Door","UDT: 우리 동네 특공대"]', 1784690324139);
