INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('senpai-vung-ve-cua-toi', 'Senpai Vụng Về Của Tôi', 'My Awkward Senpai', 'https://phimimg.com/upload/vod/20251003-1/dec6a811a2e17348dbefda4beb6016a5.jpg', 'https://phimimg.com/upload/vod/20251003-1/6773aa35d0fa05486dc064ff505a8434.jpg', '<p>Kannawa-senpai được coi là rất nhiều thứ, nhưng chắc chắn không phải là người khéo léo. Rồi cô gặp Kamegawa, cậu Kouhai mới của mình. Cậu ấy dễ thương, hơi mọt sách và rất dễ bắt chuyện. Liệu một Senpai vụng về như cô sẽ phải đối mặt với những cảm xúc mới mẻ này thế nào đây?!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 243, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Lynn","avatar":""},{"name":"Shogo Sakata","avatar":""},{"name":"Ami Maeshima","avatar":""},{"name":"Mitsuki Saiga","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["不中用的前辈","笨拙的前辈。","笨拙至极的前辈","笨拙之极的前辈","Bukiyou na Senpai.","Bukiyou na Senpai","Awkward Senpai","不器用な先輩。"]', 1784690324139);
