INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('senpai-vung-ve-cua-toi', 'Senpai Vụng Về Của Tôi', 'My Awkward Senpai', 'senpai vụng về của tôi my awkward senpai lynn shogo sakata ami maeshima mitsuki saiga 不中用的前辈 笨拙的前辈。 笨拙至极的前辈 笨拙之极的前辈 bukiyou na senpai. bukiyou na senpai awkward senpai 不器用な先輩。', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-hon-noi-tan-cung-the-gioi', 'Hoàng Hôn Nơi Tận Cùng Thế Giới', 'Dusk Beyond The End Of The World', 'https://phimimg.com/upload/vod/20251012-1/a82b2402e0f81c008b1e83521ceb8fbc.jpg', 'https://phimimg.com/upload/vod/20251012-1/88422d695c035ba1c8cca3d7efa54db6.jpg', '<p>Thế giới đang trên bờ vực chuyển mình từ một xã hội lỗi thời sang một thế giới mới, do những vấn đề như giới tính, chủng tộc và sự tuân thủ, cùng với những đổi mới công nghệ như AI đang phát triển. Ngay cả trong thế giới mà trắng đen giờ đây đã trở thành xám xịt, chúng ta vẫn tin rằng &quot;tình yêu&quot; sẽ luôn tồn tại, nhưng dưới muôn hình vạn trạng, chứ không chỉ giữa con người với nhau. Điều này bao gồm tình yêu giữa con người và robot, cùng những biểu hiện độc đáo của nó. Vẻ đẹp của những cảm xúc này sẽ được thể hiện đôi khi đẹp đẽ, đôi khi tàn khốc, và đôi khi hài hước. Liệu tình yêu này có thể kéo dài được bao lâu? Khi một robot sống lâu hơn người bạn đời của mình, liệu tình yêu của họ có thể bền vững?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shuichiro Umeda","avatar":""},{"name":"Yui Ishikawa","avatar":""},{"name":"Ai Kayano","avatar":""},{"name":"Miyu Tomita","avatar":""},{"name":"Miyuki Sawashiro","avatar":""},{"name":"Tomori Kusunoki","avatar":""},{"name":"Yohei Azakami","avatar":""},{"name":"Saki Kobari","avatar":""},{"name":"Toshiyuki Morikawa","avatar":""},{"name":"Taito Ban","avatar":""},{"name":"Ami Koshimizu","avatar":""},{"name":"Maki Kawase","avatar":""},{"name":"Haruka Shiraishi","avatar":""},{"name":"Tetsu Inada","avatar":""},{"name":"Rina Sato","avatar":""},{"name":"Satoshi Tsuruoka","avatar":""},{"name":"Takehito Koyasu","avatar":""},{"name":"Y","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["永远的黄昏","永恒余晖","永久的黄昏","Towa no Yugure","Towa no Yūgure","Towa no Yuugure","永遠的黃昏","Dusk Beyond the End of the World","永久のユウグレ"]', 1784690324139);
