INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoang-hon-noi-tan-cung-the-gioi', 'Hoàng Hôn Nơi Tận Cùng Thế Giới', 'Dusk Beyond The End Of The World', 'hoàng hôn nơi tận cùng thế giới dusk beyond the end of the world shuichiro umeda yui ishikawa ai kayano miyu tomita miyuki sawashiro tomori kusunoki yohei azakami saki kobari toshiyuki morikawa taito ban ami koshimizu maki kawase haruka shiraishi tetsu inada rina sato satoshi tsuruoka takehito koyasu y 永远的黄昏 永恒余晖 永久的黄昏 towa no yugure towa no yūgure towa no yuugure 永遠的黃昏 dusk beyond the end of the world 永久のユウグレ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-ngoai-mot-minh-cung-nhau', 'Dã Ngoại Một Mình Cùng Nhau', 'Solo Camping For Two', 'https://phimimg.com/upload/vod/20250810-1/f937e8cb0b8dc1e3987e54ab2af3f76d.jpg', 'https://phimimg.com/upload/vod/20250810-1/e92a2d01408ed639962d3d1331373358.jpg', '<p>Gen, người đàn ông yêu thích sự cô đơn giữa thiên nhiên, chỉ muốn tận hưởng những chuyến cắm trại một mình. Thế nhưng, một cuộc gặp gỡ tình cờ với Shizuku, cô nàng mới toanh trong thế giới cắm trại, đã khiến mọi thứ thay đổi. Từ hai kẻ xa lạ, họ bắt đầu một hành trình độc đáo: &quot;cắm trại một mình… cùng nhau.&quot;</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Daiki Hamano","avatar":""},{"name":"Mizuki Niizaki","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["双人单身露营","Futari.Daka","双人独自露营","雙人單身露營 [動畫版]","Futari Soro Kyanpu","Futari Solo Camp","二人ソロキャンプ","FUTARI SOLOCAMP","ふたりソロキャンプ(アニメ)","ふたりソロキャンプ"]', 1784690324139);
