INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cung-choi-nao', 'Cùng Chơi Nào', 'Let''s Play', 'https://phimimg.com/upload/vod/20251003-1/a768856f50ca4858a75d07472a3b1553.jpg', 'https://phimimg.com/upload/vod/20251003-1/07df84c741b6d2084ee1a90aeea1c8db.jpg', '<p>Samara “Sam” Young là một nhà phát triển game ở Los Angeles, đang chuẩn bị chạm tới ước mơ khi ra mắt trò chơi đầu tay Ruminate. Thế nhưng, mọi chuyện sụp đổ khi một streamer nổi tiếng đã dành cho game một bài đánh giá gay gắt. Tệ hơn nữa, Sam phát hiện ra người phê bình rắc rối này lại chính là… người hàng xóm mới của cô!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 162, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kana Hanazawa","avatar":""},{"name":"Shimba Tsuchiya","avatar":""},{"name":"Yuichi Nakamura","avatar":""},{"name":"Tomokazu Sugita","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Let''s Play: Minha Vida Cheia de Missões","Let’s Play: Quest Darake no My Life","Let''s Play: Quest-darake no My Life","Let''s Play クエストだらけのマイライフ"]', 1784690324139);
