INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('alma-muon-co-mot-gia-dinh', 'Alma Muốn Có Một Gia Đình', 'Alma-chan Wants to Be A Family!', 'https://phimimg.com/upload/vod/20251013-1/a1a3d26b2d2dcbca7b5f078ba9795ecc.jpg', 'https://phimimg.com/upload/vod/20251013-1/2f39b9885211696f6694a9b14917f821.jpg', '<p>Cô ấy nhỏ bé. Cô ấy ngọt ngào. Nhưng… cô ấy có thể phá hủy một chiếc xe tăng chỉ trong ba giây sao?! Được tạo ra bởi Enji và Suzume — hai nhà khoa học thiên tài nhưng ít được công nhận — Alma là trí tuệ nhân tạo tự học tối thượng. Chỉ có một vấn đề: cô ấy nghĩ họ là cha mẹ của mình! Giờ đây, trong vai trò những “bậc phụ huynh bất đắc dĩ”, Enji và Suzume phải vừa che giấu tình cảm đang nảy nở giữa họ, vừa đối mặt với thí nghiệm hỗn loạn nhất trong đời: cuộc sống gia đình!</p>', 'Tập 11', 12, 'hoathinh', 'ongoing', 161, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hika Tsukishiro","avatar":""},{"name":"Ryota Suzuki","avatar":""},{"name":"Mao Ichimichi","avatar":""},{"name":"Rika Nagae","avatar":""},{"name":"Hinaki Yano","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["小阿尔玛想要成为家人","少女型兵器想要成为家人","阿尔玛酱想成为家人","Alma-chan wa Kazoku ni Naritai","Alma-chan Wants to Have a family!","아르마는 가족이 되고 싶어","少女型兵器想要成為家人","アルマちゃんは家族になりたい"]', 1784690324140);
