INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-mang-o-monaco', 'Án Mạng Ở Monaco', 'Murder In Monaco', 'https://phimimg.com/upload/vod/20251218-1/66fefd903aab64903e84b324d9ca993a.jpg', 'https://phimimg.com/upload/vod/20251218-1/3936dafb00d9220abc7dc347e905fe09.jpg', '<p>Ở Monaco, năm 1999. Một trong những người giàu nhất thế giới mất mạng trong căn hộ áp mái của mình. Bộ phim tài liệu này hé lộ vụ án mạng bí ẩn của tỷ phú ngân hàng Edmond Safra.</p>', 'Full', 1, 'single', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Murder in Monaco"]', 1784690324140);
