INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-giu-tre-phan-3', 'Chàng Giữ Trẻ (Phần 3)', 'The Manny (Season 3)', 'https://phimimg.com/upload/vod/20251218-1/b2310e118159adb1fc19b55b20284ca2.jpg', 'https://phimimg.com/upload/vod/20251218-1/bdcd21921225e5b995a7bfb7bfa859ca.jpg', '<p>Trong hoảng loạn, một giám đốc bận rộn thuê một chủ trang trại chăm sóc các con của mình. Cô nào ngờ anh sẽ thách thức quan điểm của cô về vai trò của các giới và cả tình yêu.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 29, 2025, 'Vietsub', 'FHD', 'Mexico', 0, '[{"name":"Sandra Echeverría","avatar":""},{"name":"Iván Amozurrutia","avatar":""},{"name":"Diana Bovio","avatar":""},{"name":"Alexander Tavizón","avatar":""},{"name":"Anthony Giuletti","avatar":""},{"name":"Cassandra Iturralde","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Manny","曼尼酒店","El niñero"]', 1784690324140);
