INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chang-giu-tre-phan-3', 'Chàng Giữ Trẻ (Phần 3)', 'The Manny (Season 3)', 'chàng giữ trẻ (phần 3) the manny (season 3) sandra echeverría iván amozurrutia diana bovio alexander tavizón anthony giuletti cassandra iturralde the manny 曼尼酒店 el niñero', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuong-nguyet-vo-tan', 'Thương Nguyệt Vô Tẫn', 'Reborn From The Ashes', 'https://phimimg.com/upload/vod/20251204-1/9c7b13eb1a54f97ccef71f6652b18438.jpg', 'https://phimimg.com/upload/vod/20251204-1/115cd2ae43f3fc415e28597cf348ecc5.jpg', '<p>Vào ngày đại hôn, Ôn Nguyệt Thiển tận mắt chứng kiến phụ thân bị chém đầu oan ngay trước mắt. Trong đêm động phòng hoa chúc, cô còn thấy phu quân mình lén lút tư thông với nữ tử khác ngay trong phòng tân hôn. Cô chất vấn không thành, còn bị hắn giết hại tàn nhẫn rồi ném xuống vách núi. Dưới vách núi, Ôn Nguyệt Thiển lại sống lại một cách kỳ diệu. Cùng lúc đó, ở đầu bên kia, còn một người nữa sống lại là Tiêu Tẫn, một người không cam lòng chết đi. Không ngờ số phận của cả hai lại được gắn kết với nhau.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 11, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Ôn Mặc Ngôn","avatar":""},{"name":"Tôn Tranh Tiêu","avatar":""},{"name":"Cam Vọng Tinh","avatar":""},{"name":"Vương Trạch Tuyên","avatar":""},{"name":"Trần Khiết Di","avatar":""},{"name":"Lý Nghiên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Cang Yue Wu Jin","蒼月無燼","苍月无烬"]', 1784690324140);
