INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thuong-nguyet-vo-tan', 'Thương Nguyệt Vô Tẫn', 'Reborn From The Ashes', 'thương nguyệt vô tẫn reborn from the ashes ôn mặc ngôn tôn tranh tiêu cam vọng tinh vương trạch tuyên trần khiết di lý nghiên cang yue wu jin 蒼月無燼 苍月无烬', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('disney-the-gioi-dao-nguoc-ban-hoat-hinh', 'Disney: Thế Giới Đảo Ngược (Bản Hoạt Hình)', 'Disney Twisted-Wonderland: The Animation', 'https://phimimg.com/upload/vod/20251030-1/1a39bb0dc90c26c0c124d4dca746d67d.jpg', 'https://phimimg.com/upload/vod/20251030-1/aecf9b72208af24500a96697cc40dd97.jpg', '<p>Học sinh trung học Yu bất ngờ bị cuốn vào Twisted-Wonderland — một thế giới huyền bí đầy phép thuật và điều kỳ diệu. Tại đây, cậu phải đối mặt với những con quái vật, các pháp sư tập sự lập dị, và hàng loạt sự cố bí ẩn xảy ra liên tiếp.Thế nhưng, Yu không hề có phép thuật, buộc phải dựa vào trí thông minh, lòng dũng cảm và tình bạn để sinh tồn trong ngôi trường phép thuật kỳ quái này. Giữa những thử thách đó, cậu không ngừng tìm kiếm con đường trở về thế giới thực, đồng thời khám phá bí mật đen tối ẩn giấu trong Twisted-Wonderland.</p>', 'Hoàn Tất (8/8)', 8, 'hoathinh', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yohei Azakami","avatar":""},{"name":"Natsuki Hanae","avatar":""},{"name":"Seiichiro Yamashita","avatar":""},{"name":"Chiaki Kobayashi","avatar":""},{"name":"Ryota Suzuki","avatar":""},{"name":"Tatsuyuki Kobayashi","avatar":""},{"name":"Mitsuru Miyamoto","avatar":""},{"name":"Noriaki Sugiyama","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Disney: Twisted-Wonderland","Disney Twisted-Wonderland","Dizunī Tsuisuteddo Wandārando","ディズニー ツイステッドワンダーランド ザ アニメーション エピソード オブ ハーツラビュル","ディズニー ツイステッドワンダーランド ザ アニメーション エピソード オブ サバナクロー","ディズニー ツイステッドワンダーランド ザ アニメーション エピソード オブ オクタヴィネル","Disney: Twisted-Wonderland - The Animation - Episode of Heartslabyul","Disney: Twisted-Wonderland - The Animation - Episode of Savanaclaw","Disney: Twisted-Wonderland - The Animation - Episode of Octavinelle","ディズニー ツイステッドワンダーランド ザ アニメーション"]', 1784690324140);
