INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('disney-the-gioi-dao-nguoc-ban-hoat-hinh', 'Disney: Thế Giới Đảo Ngược (Bản Hoạt Hình)', 'Disney Twisted-Wonderland: The Animation', 'disney: thế giới đảo ngược (bản hoạt hình) disney twisted-wonderland: the animation yohei azakami natsuki hanae seiichiro yamashita chiaki kobayashi ryota suzuki tatsuyuki kobayashi mitsuru miyamoto noriaki sugiyama disney: twisted-wonderland disney twisted-wonderland dizunī tsuisuteddo wandārando ディズニー ツイステッドワンダーランド ザ アニメーション エピソード オブ ハーツラビュル ディズニー ツイステッドワンダーランド ザ アニメーション エピソード オブ サバナクロー ディズニー ツイステッドワンダーランド ザ アニメーション エピソード オブ オクタヴィネル disney: twisted-wonderland - the animation - episode of heartslabyul disney: twisted-wonderland - the animation - episode of savanaclaw disney: twisted-wonderland - the animation - episode of octavinelle ディズニー ツイステッドワンダーランド ザ アニメーション', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-lam-an-lon', 'Người Làm Ăn Lớn', 'Legend Of The Magnate', 'https://phimimg.com/upload/vod/20251126-1/ccc315edba0c5ee9462f1b27aed43013.jpg', 'https://phimimg.com/upload/vod/20251126-1/3d551cb91ec880ca0fab4e8036f914a1.jpg', '<p>Câu chuyện kể về Cổ Bình Nguyên - một nho sinh bị hàm oan và lưu đày, đã dùng cái chết để tìm đường sống. Giữa những khe hẹp của số phận, Bình Nguyên biết mượn thế lực để tạo cục diện, lấy tiệm ngân phiếu làm nền tảng, dùng trà để phát gia, lấy muối lập nghiệp, dùng lương thực cứu giúp muôn dân. Với cách chơi riêng, anh đã lật ngược tình thế trên thương trường, trở thành &quot;đại thương nhân&quot; mang phúc lợi cho cả một vùng.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 13, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Hiểu","avatar":""},{"name":"Tôn Thiên","avatar":""},{"name":"La Nhất Chu","avatar":""},{"name":"Thành Thái Thần","avatar":""},{"name":"Hoàng Chí Trung","avatar":""},{"name":"Lý Thuần","avatar":""},{"name":"Chu Á Văn","avatar":""},{"name":"Từ Ân Chiếu","avatar":""},{"name":"Ngô Duyệt","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["The Tycoon","Legend of the Magnate","Легенда о магнате","大生意人"]', 1784690324140);
