INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-lam-an-lon', 'Người Làm Ăn Lớn', 'Legend Of The Magnate', 'người làm ăn lớn legend of the magnate trần hiểu tôn thiên la nhất chu thành thái thần hoàng chí trung lý thuần chu á văn từ ân chiếu ngô duyệt the tycoon legend of the magnate легенда о магнате 大生意人', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phuong-hoang-dai-thuong', 'Phượng Hoàng Đài Thượng', 'Love And Crown', 'https://phimimg.com/upload/vod/20251115-1/6de7ff42bbede5b0d2b8dfa5b9215bac.jpg', 'https://phimimg.com/upload/vod/20251115-1/ba88e3f37bfb0a7c40e286b3948fecf1.jpg', '<p>Bộ phim&nbsp;xoay quanh cuộc đời Lăng Thương Thương, nữ hiệp nổi danh giang hồ với võ công cao cường và tấm lòng chính nghĩa, cùng Tiêu Hoán – hoàng đế trẻ tuổi của triều Nam Kỳ. Trong bối cảnh quyền lực cung đình và âm mưu giang hồ chằng chịt, cả hai gặp nhau khi Tiêu Hoán cải trang thành dân thường để thấu hiểu nỗi khổ của dân chúng. Sự đồng điệu về lý tưởng và lòng nhân nghĩa khiến họ sát cánh cùng nhau trừ gian diệt ác, đồng thời nảy sinh tình cảm sâu đậm. Tuy nhiên, mối tình của họ bị thử thách khi Thương Thương là con gái của gian thần thủ phụ, kẻ đối nghịch với Tiêu Hoán, đồng thời là vị hôn thê hoàng hậu tương lai.</p>', 'Hoàn Tất (35/35)', 35, 'series', 'completed', 12, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Nhậm Gia Luân","avatar":""},{"name":"Bành Tiểu Nhiên","avatar":""},{"name":"Trương Diệu","avatar":""},{"name":"Trần Ý Hân","avatar":""},{"name":"Vương Trạch Thành","avatar":""},{"name":"Hạc Nam","avatar":""},{"name":"Lưu Mộng Nhụy","avatar":""},{"name":"Lạc Minh Kiệt","avatar":""},{"name":"Lâm Tĩnh","avatar":""},{"name":"Tuyết Ỷ Luân","avatar":""},{"name":"Vệ Nhiên","avatar":""},{"name":"Lý Khang","avatar":""},{"name":"Vương Diệp Tranh","avatar":""},{"name":"Tống Văn","avatar":""},{"name":"Cao Thự Quang","avatar":""},{"name":"Phó Phương Tuấn","avatar":""},{"name":"Triệu Kha","avatar":""},{"name":"Thư Diệu Hiên","avatar":""},{"name":"Lý Dục","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Feng Huang Tai Shang","我的皇后","Phoenix Stage","鳳凰臺上","Phoenix Fly","Love and Crown","凤凰台上"]', 1784690324140);
