INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ngay-binh-thuong-cua-yanokun', 'Những Ngày Bình Thường Của Yano-Kun', 'Yano-kun''s Ordinary Days', 'https://phimimg.com/upload/vod/20251001-1/678bcd4ec6e45a8bab81420300fd5079.jpg', 'https://phimimg.com/upload/vod/20251001-1/e806a015b35ad05f15ad4e57f23ea4c2.jpg', '<p>Yoshida Kiyoko là một lớp trưởng hay lo lắng thái quá, luôn để tâm đến Yano Tsuyoshi, cậu bạn ngồi cạnh mình. Ngày nào Tsuyoshi cũng đến trường với đầy vết bầm tím, và Kiyoko lại kiên nhẫn chăm sóc cho cậu. Dần dần, cả hai trở nên gần gũi hơn. Liệu tình cảm của Kiyoko sẽ dẫn dắt cô đến đâu? Và cuộc sống của Tsuyoshi có bao giờ trở lại bình thường được không?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kohei Amasaki","avatar":""},{"name":"Yuka Nukui","avatar":""},{"name":"Atsumi Tanezaki","avatar":""},{"name":"Taito Ban","avatar":""},{"name":"Rie Takahashi","avatar":""},{"name":"Ryota Iwasaki","avatar":""},{"name":"Satoshi Hino","avatar":""},{"name":"Takuya Eguchi","avatar":""},{"name":"Konomi Kohara","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["矢野同学的普通日常","矢野同学观察日记","Yano-kun no Futsuu no Hibi","Yano-kun''s Ordinary Days","Yano-kun no Futsū no Hibi","矢野くんの普通の日々"]', 1784690324140);
