INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gieo-gi-gat-nay-ngoai-truyen-mexico', 'Gieo Gì Gặt Nấy: Ngoại Truyện Mexico', 'GBRB: Joy Pops Laugh Pops', 'https://phimimg.com/upload/vod/20251018-1/605fe8fd0db36aa6f5b0f221a350d5ad.jpg', 'https://phimimg.com/upload/vod/20251018-1/1d035a171a115e44c24aae91a6377f81.jpg', '<p>Mùa trước, các nhân viên công ty thực phẩm KKPP đã hoàn thành nhiệm vụ xuất sắc hơn cả mong đợi. Kỳ này, họ quyết định xuất ngoại để tìm kiếm những hướng đi mới giúp công ty phát triển hơn. CEO Lee Kwang Soo, giám đốc Doh Kyung Soo và kế toán Kim Woo Bin cùng nhau lên lịch trình đến Mexico trong khi phải vật lộn với ngân sách eo hẹp và gần như phải đàm phán suốt chuyến đi, liệu họ có giữ được hòa khí?</p>', 'Hoàn Tất (9/9)', 9, 'tvshows', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Kwang-soo","avatar":""},{"name":"Kim Woo-bin","avatar":""},{"name":"Doh Kyung-soo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["种豆得豆2","콩콩팡팡","콩콩팡팡 콩 심은 데 콩 나서 웃음팡 행복팡 해외탐방","种豆得豆充满笑声又幸福满满的海外探访","種豆得豆2","콩 심은 데 콩 나서 웃음팡 행복팡 해외탐방"]', 1784690324140);
