INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-cung-cua-chung-ta', 'Cố Cung Của Chúng Ta', 'Our Palace Museum', 'https://phimimg.com/upload/vod/20251014-1/bc1a87f00a387b3299aaacb29ed6d3d8.jpg', 'https://phimimg.com/upload/vod/20251014-1/23bd2f68839a3ef16f17abbe25a6aa19.jpg', '<p>Bộ phim tài liệu “Trăm năm Cố Cung – Một hành trình mãn nhãn” do phóng viên Trương Dương của Tân Hoa Xã thực hiện, kể về hành trình 100 năm của Bảo tàng Cố Cung, từ cung điện vua chúa 605 năm tuổi trở thành bảo tàng của nhân dân, kết nối 5.000 năm văn minh với thời hiện đại. Bộ phim tài liệu khắc họa sự đổi mới mạnh mẽ: ứng dụng công nghệ số, phục chế cổ vật, truyền lửa văn hóa qua nhiều thế hệ và khẳng định sức sống của một biểu tượng lịch sử hướng đến tương lai.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Our Palace Museum","我们的故宫"]', 1784690324140);
