INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-cuc-thai-lai', 'Bĩ Cực Thái Lai', 'Bugonia', 'https://phimimg.com/upload/vod/20251127-1/25cb9092aec71a597b9c139826e7204d.jpg', 'https://phimimg.com/upload/vod/20251127-1/def5e5a2aa634636793e495959926f01.jpg', '<p>Hai thanh niên ám ảnh với thuyết âm mưu đã bắt cóc nữ CEO quyền lực của một tập đoàn lớn, tin chắc rằng bà ta thực chất là một sinh vật ngoài hành tinh đang âm thầm lên kế hoạch hủy diệt Trái Đất. Nhưng khi kế hoạch diễn ra, sự thật họ khám phá ra còn vượt xa mọi tưởng tượng.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Emma Stone","avatar":""},{"name":"Jesse Plemons","avatar":""},{"name":"Aidan Delbis","avatar":""},{"name":"Stavros Halkias","avatar":""},{"name":"Alicia Silverstone","avatar":""},{"name":"J. Carmen Galindez Barrera","avatar":""},{"name":"Marc T. Lewis","avatar":""},{"name":"Vanessa Eng","avatar":""},{"name":"Cedric Dumornay","avatar":""},{"name":"Charita Momma Cherri Jones","avatar":""},{"name":"Fredricka Whitfield","avatar":""},{"name":"Rafael Lopez Bravo","avatar":""},{"name":"Yaisa","avatar":""},{"name":"Teneise Mitchell Ellis","avatar":""},{"name":"Roge","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Save the Green Planet!","Բուգոնիա","Буґонія","拯救地球","부고니아","Βουγονία","La Bugonia","暴蜂尼亞","บูโกเนีย","Бугония","Бугонија","Bugonija","بوغونيا","بوگونیا","בוגוניה","بوجونيا","ბუგონია","Bĩ Cực Thái Lai","Bugonia"]', 1784690324140);
