INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-tri-tinh-cam-affeksjonsverdi', 'Giá Trị Tình Cảm (Affeksjonsverdi)', 'Sentimental Value', 'https://phimimg.com/upload/vod/20251207-1/363a0a74812e4b8bd361776ffb3137a7.jpg', 'https://phimimg.com/upload/vod/20251207-1/d16ad3532e60f155f05adaa54b5b0a49.jpg', '<p>Câu chuyện xoay quanh hai chị em Nora và Agnes, bất ngờ đoàn tụ với người cha xa cách Gustav – một đạo diễn kỳ cựu, nay muốn tái xuất bằng dự án mới và mời Nora đóng vai chính. Khi bị từ chối, ông mời một ngôi sao Hollywood trẻ thế chỗ, đẩy hai chị em vào tình huống căng thẳng khi vừa phải đối mặt với cha, vừa ứng xử với “kẻ ngoài cuộc” xen vào mối quan hệ vốn đã phức tạp.</p>', 'Full', 1, 'single', 'completed', 21, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Renate Reinsve","avatar":""},{"name":"Stellan Skarsgård","avatar":""},{"name":"Inga Ibsdotter Lilleaas","avatar":""},{"name":"Elle Fanning","avatar":""},{"name":"Andreas Stoltenberg Granerud","avatar":""},{"name":"Øyvind Hesjedal Loven","avatar":""},{"name":"Anders Danielsen Lie","avatar":""},{"name":"Cory Michael Smith","avatar":""},{"name":"Catherine Cohen","avatar":""},{"name":"Jesper Christensen","avatar":""},{"name":"Lena Endre","avatar":""},{"name":"Lars Väringer","avatar":""},{"name":"Pia Borgli","avatar":""},{"name":"Jonas Jaco","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sentimental Value","Valeur sentimentale","Érzelmi érték","Căn Nhà Ký Ức","Mənəvi Dəyər","Manevi Değer","Sentimentali vertė","Affektionsværdi","Affeksjonsverdi","Citová hodnota"]', 17846903