INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('merv', 'Merv', 'Merv', 'https://phimimg.com/upload/vod/20251216-1/85624ecd0175edba5c14c680860eb415.jpg', 'https://phimimg.com/upload/vod/20251216-1/7e06f2f4fe90b5c246bc67c998a64f6d.jpg', '<p>Sau khi Anna và Russ chia tay, chú chó Merv trở nên buồn bã. Cả hai buộc phải cùng chăm sóc Merv, và trong chuyến đi Florida, khi Merv dần hồi phục, mối quan hệ giữa họ cũng bắt đầu nhen nhóm trở lại.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Zooey Deschanel","avatar":""},{"name":"Charlie Cox","avatar":""},{"name":"Ellyn Jameson","avatar":""},{"name":"Patricia Heaton","avatar":""},{"name":"David Hunt","avatar":""},{"name":"Chris Redd","avatar":""},{"name":"Jasmine Mathews","avatar":""},{"name":"Victoria Blade","avatar":""},{"name":"Wynn Everett","avatar":""},{"name":"Jason Burkey","avatar":""},{"name":"Jake Berne","avatar":""},{"name":"Jordan Cox","avatar":""},{"name":"Andrea Laing","avatar":""},{"name":"Nancy Ticotin","avatar":""},{"name":"Kelly Tippens","avatar":""},{"name":"Michelle Mary Schaefer","avatar":""},{"name":"Kevin Patrick Mu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Merv"]', 1784690324140);
