INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chainsaw-man-the-movie-chuong-reze', 'Chainsaw Man - The Movie: Chương Reze', 'Chainsaw Man - The Movie: Reze Arc', 'https://phimimg.com/upload/vod/20251209-1/c3096886a37e19947c1b6758f7b8829f.jpg', 'https://phimimg.com/upload/vod/20251209-1/69d2d97349877280293f7c1ccc9efdb4.jpg', '<p>Tiếp nối series anime chuyển thể đình đám, Chainsaw Man lần đầu tiên oanh tạc màn ảnh rộng trong một cuộc phiêu lưu hoành tráng, ngập tràn các phân cảnh hành động. Ở phần trước, ta đã biết Denji từng làm Thợ Săn Quỷ cho yakuza để trả món nợ của cha mẹ nhưng bị họ phản bội và trừ khử. Trong khoảnh khắc hấp hối, chú chó quỷ cưa máy Pochita (người bạn đồng hành trung thành của Denji) đã đưa ra một khế ước, cứu sống cậu và hợp thể cùng cậu. Từ đó, một Quỷ Cưa bất khả chiến bại ra đời. Giờ đây ở Chainsaw Man – The Movie: Chương Reze, trong cuộc chiến tàn khốc giữa quỷ dữ, thợ săn quỷ và những kẻ thù trong bóng tối, một cô gái bí ẩn tên Reze xuất hiện trong thế giới của Denji. Denji buộc phải đối mặt với trận chiến sinh tử khốc liệt nhất của mình, một trận chiến được tiếp sức bởi tình yêu trong một thế giới nơi mọi người phải sinh tồn mà không biết bất kỳ luật lệ nào.</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Nhật Bản', 1, '[{"name":"Kikunosuke Toya","avatar":""},{"name":"Reina Ueda","avatar":""},{"name":"Tomori Kusunoki","avatar":""},{"name":"Shogo Sakata","avatar":""},{"name":"Maaya Uchida","avatar":""},{"name":"Natsuki Hanae","avatar":""},{"name":"Karin Takahashi","avatar":""},{"name":"Fairouz Ai","avatar":""},{"name":"Yuuya Uchida","avatar":""},{"name":"Shiori Izawa","avatar":""},{"name":"Kenjiro Tsuda","avatar":""},{"name":"Marina Inoue","avatar":""},{"name":"Hidenori Takahashi","avatar":""},{"name":"Kenji Akabane","avatar":""},{"name":"Kenji Nomura","avatar":""},{"name":"Eri Kitamura","avatar":""},{"name":"Kenichi Ono","avatar":""},{"name":"Yuhk","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Chainsaw Man Movie: Reze-hen","Gekijouban Chainsaw Man: Reze-hen","Gekijōban Chainsaw Man: Reze-hen","チェンソーマン レゼ篇","Chainsaw Man: Reze-hen","劇場版『チェンソーマン レゼ篇』","Chainsaw Man – The Movie: Reze Arc","链锯人 - 剧场版：蕾塞篇","电锯人 - 剧场版：蕾塞篇","CSM – The Movie: Reze Arc","Gekijô-ban Chensô Man Reze-hen","鏈鋸人 - 劇場版：蕾潔篇","צ’יינסו מן - הסרט: רזה ארק","เชนซอว์ แมน - เดอะ มูฟวี่: เรื่องราวของเรเซ่","איש המסור - הסרט: ארק רזה","Chainsaw Man: Rezina Priča","Chainsaw Man - O Filme: Arco da Reze","电锯人 剧场版：蕾塞篇","Chainsaw Man Le Film - L''arc de Reze","Chainsaw Man Le Film, L''arc de Reze","Chainsaw Man - The Movie: Reze Arc","Человек-бензопила. Фильм: История Резе","Chainsaw Man - Film: Reze Arc","劇場版 チェンソーマン レゼ篇"]', 1784690324140);
