INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tron-chay-tu-than-2025', 'Trốn Chạy Tử Thần', 'The Running Man', 'https://phimimg.com/upload/vod/20251123-1/5d689acfccc3bdc341a81dd9371e2664.jpg', 'https://phimimg.com/upload/vod/20251123-1/e287c1d6f5dde2b36839999aae901eeb.jpg', '<p>Trong bối cảnh xã hội tương lai gần, Trốn Chạy Tử Thần là chương trình truyền hình ăn khách nhất, một cuộc thi sinh tồn khốc liệt nơi các thí sinh, được gọi là “Runners”, phải trốn chạy suốt 30 ngày khỏi sự truy đuổi của các sát thủ chuyên nghiệp. Mọi bước đi của họ đều được phát sóng công khai cho khán giả theo dõi và phần thưởng tiền mặt sẽ tăng lên sau mỗi ngày sống sót. Vì cần tiền cứu chữa cho cô con gái bệnh nặng, Ben Richards (do Glen Powell thủ vai), một người lao động nghèo, chấp nhận lời mời từ Dan Killian (do Josh Brolin thủ vai), nhà sản xuất chương trình bảnh bao nhưng tàn nhẫn, để tham gia cuộc chơi như một lựa chọn cuối cùng. Tuy nhiên, sự gan lì, nhạy bén và ý chí sinh tồn mãnh liệt của Ben lại khiến anh bất ngờ trở thành nhân vật được khán giả yêu thích nhất và là mối đe dọa với cả hệ thống. Khi lượng người xem tăng vọt, hiểm nguy cũng ngày càng bủa vây. Giờ đây, Ben không chỉ phải đối mặt với toán sát thủ mà còn cả một đất nước đang nghiện cảm giác chứng kiến anh gục ngã.</p>', 'Full', 1, 'single', 'completed', 12, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Glen Powell","avatar":""},{"name":"Josh Brolin","avatar":""},{"name":"Michael Cera","avatar":""},{"name":"Colman Domingo","avatar":""},{"name":"Lee Pace","avatar":""},{"name":"Jayme Lawson","avatar":""},{"name":"William H. Macy","avatar":""},{"name":"Emilia Jones","avatar":""},{"name":"David Zayas","avatar":""},{"name":"Katy O''Brian","avatar":""},{"name":"Daniel Ezra","avatar":""},{"name":"Karl Glusman","avatar":""},{"name":"Sean Hayes","avatar":""},{"name":"Martin Herlihy","avatar":""},{"name":"Sandra Dickinson","avatar":""},{"name":"Shelley Conn","avatar":""},{"name":"James Austin Johnson","avatar":""},{"name":"Deb","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["런닝맨","Переслідуваний","Running Man","逃亡遊戲","Qaçan Adam","O Sobrevivente","เดอะรันนิ่งแมน","Le jeu du défi","Trkač","الرجل الراكض","Бягащият човек","Бегущий человек","Тркач","Людина, що біжить","Ο Άτρωτος","Skrienošais cilvēks","A menekülő ember","الهارب","مرد فراری","הנרדף","ランニング・マン","猎杀游戏","Põgenev mees","მორბენალი ადამიანი","Uciekinier","Fugarul: Vânătoare de oameni","Muž na úteku","Tekač","Běžící muž","Ölüme Koşan Adam","Trốn Chạy Tử Thần","Vrapi i mbijetesës","The Running Man"]', 1784690324140);
