INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tron-chay-tu-than-2025', 'Trốn Chạy Tử Thần', 'The Running Man', 'trốn chạy tử thần the running man glen powell josh brolin michael cera colman domingo lee pace jayme lawson william h. macy emilia jones david zayas katy o''brian daniel ezra karl glusman sean hayes martin herlihy sandra dickinson shelley conn james austin johnson deb 런닝맨 переслідуваний running man 逃亡遊戲 qaçan adam o sobrevivente เดอะรันนิ่งแมน le jeu du défi trkač الرجل الراكض бягащият човек бегущий человек тркач людина, що біжить ο άτρωτος skrienošais cilvēks a menekülő ember الهارب مرد فراری הנרדף ランニング・マン 猎杀游戏 põgenev mees მორბენალი ადამიანი uciekinier fugarul: vânătoare de oameni muž na úteku tekač běžící muž ölüme koşan adam trốn chạy tử thần vrapi i mbijetesës the running man', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tong-tinh', 'Tống Tình', 'Ekis', 'https://phimimg.com/upload/vod/20251216-1/1159bbae172e652f5a863e9a073f2ec0.jpg', 'https://phimimg.com/upload/vod/20251216-1/799b70c77a34d20fdae0daa4447faf30.jpg', '<p>Bộ phim kinh điển Ekis của Erik Matti được làm mới táo bạo với dàn diễn viên toàn nữ do Angela Morena, Cheena Dizon và Aliya Raymundo thủ vai chính. Một nhóm nữ côn đồ lên kế hoạch bắt cóc tống tiền, nhưng khi mọi chuyện đi sai hướng, việc thoát khỏi hỗn loạn trở nên bất khả thi.</p>', 'Full', 1, 'single', 'completed', 32, 2025, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Angela Morena","avatar":""},{"name":"Cheena Dizon","avatar":""},{"name":"Aliya Raymundo","avatar":""},{"name":"Astrid Lee","avatar":""},{"name":"Arnold Reyes","avatar":""},{"name":"Cess Garcia","avatar":""},{"name":"Yda Manzano","avatar":""},{"name":"Ralph Engle","avatar":""},{"name":"Mark Dionisio","avatar":""},{"name":"Jio Yoshida","avatar":""},{"name":"Stanley Frank","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"}]', '["Ekis"]', 1784690324140);
