INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-xa-dao-chich', 'Hoả Xa Đạo Chích', 'The Return Of The Lame Hero', 'https://phimimg.com/upload/vod/20251214-1/cff471923b79e8140fb9f0e40bc774c5.jpg', 'https://phimimg.com/upload/vod/20251214-1/d4870b5fa5b8485562b84653d2982fbb.jpg', '<p>Ẩn mình giữa giới giang hồ chẳng khác nào bước trên lớp băng mỏng, liệu những người trẻ đầy nhiệt huyết có thể giữ vững lý tưởng ban đầu và chứng minh giá trị của mình? Khi bánh xe thời gian lăn đi, sự lộng hành và những “màn trình diễn” của giới giang hồ dần phai nhạt. Sự bình yên và an toàn của ngày hôm nay chính là minh chứng rõ ràng nhất.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương An Vũ","avatar":""},{"name":"Trương Thiên Ái","avatar":""},{"name":"Vương Nghiêm","avatar":""},{"name":"Niên Viễn","avatar":""},{"name":"Phùng Băng","avatar":""},{"name":"Ngô Gia Khải","avatar":""},{"name":"Khổng Lệnh Mỹ","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bi Zhengming''s Proof","毕正明的证明"]', 1784690324140);
