INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dinh-thu-downton-hoi-ket-huy-hoang', 'Dinh Thự Downton: Hồi Kết Huy Hoàng', 'Downton Abbey: The Grand Finale', 'https://phimimg.com/upload/vod/20251008-1/bf6ab6e69daa44724ab1d94b720d2e7d.jpg', 'https://phimimg.com/upload/vod/20251008-1/daa27fcd030e268d17d9820b4f33165b.jpg', '<p>Khi Mary rơi vào tâm điểm của một vụ bê bối gây chấn động dư luận và gia đình đối mặt với khủng hoảng tài chính, cả dinh thự Crawley phải gồng mình trước nguy cơ mất danh dự và địa vị xã hội. Giữa thời khắc chuyển giao, những người thừa kế và tầng lớp phục vụ buộc phải thích nghi với thời đại mới – nơi truyền thống, quyền lực và tình thân đều bị thử thách. Một chương mới đang mở ra cho Downton Abbey, khi thế hệ kế tiếp đứng lên dẫn dắt ngôi nhà biểu tượng này bước vào tương lai.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Anh', 0, '[{"name":"Michelle Dockery","avatar":""},{"name":"Joanne Froggatt","avatar":""},{"name":"Elizabeth McGovern","avatar":""},{"name":"Laura Carmichael","avatar":""},{"name":"Dominic West","avatar":""},{"name":"Paul Giamatti","avatar":""},{"name":"Hugh Bonneville","avatar":""},{"name":"Alessandro Nivola","avatar":""},{"name":"Allen Leech","avatar":""},{"name":"Michael Fox","avatar":""},{"name":"Joely Richardson","avatar":""},{"name":"Sophie McShera","avatar":""},{"name":"Robert James-Collier","avatar":""},{"name":"Phyllis Logan","avatar":""},{"name":"Brendan Coyle","avatar":""},{"name":"Raque","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Абатство Даунтон 3","唐顿庄园3","唐頓莊園：盛世終章","Downton Abbey: Das große Finale","Downton Abbey: Den store finale","Downton Abbey: A nagy finálé","Аббатство Даунтон 3","Dauntonska Opatija: Veliko Finale","Downton Abbey: El gran final","Абатство Даунтон: Величний фінал","Tu Viện Downton: Hồi Kết","Downton Abbey: O Grande Final","Аббатство Даунтон 3: Грандиозный финал","Downton Abbey - Das große Finale","Downton Abbey: The Grand Finale"]', 1784690324140);
