INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-nhieu-dong', 'Vùng Nhiễu Động', 'Turbulence', 'https://phimimg.com/upload/vod/20251216-1/0dc4d1735cc511e92da8e21595bb1df1.jpg', 'https://phimimg.com/upload/vod/20251216-1/b95a69007d5dca8745f6dd0039d7e11a.jpg', '<p>Zịach và Emmy thực hiện chuyến khinh khí cầu băng qua dãy Dolomites của Ý nhằm hâm nóng lại mối quan hệ. Khi họ cùng phi công Harry đón thêm một hành khách thứ ba, Julia, mọi chuyện bắt đầu diễn ra theo những cách không ai có thể lường trước, ở độ cao 5000 mét trên không.</p>', 'Full', 1, 'single', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Hera Hilmar","avatar":""},{"name":"Jeremy Irvine","avatar":""},{"name":"Kelsey Grammer","avatar":""},{"name":"Olga Kurylenko","avatar":""},{"name":"Lionel Robert Blanc","avatar":""},{"name":"Stuart Whelan","avatar":""},{"name":"Elena Bushueva","avatar":""},{"name":"Kevin Jarvis","avatar":""},{"name":"Alessandro De Cominato","avatar":""},{"name":"Trish Williams","avatar":""},{"name":"Mike Ray","avatar":""},{"name":"Jon Wennington","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Turbulencias","Turbulencia: Pánico en el aire","Turbulence - Fear takes flight","Turbulence"]', 1784690324140);
