INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-du-hanh-di-gioi-cua-nha-thu-thap-nguyen-lieu', 'Nhật Ký Du Hành Dị Giới Của Nhà Thu Thập Nguyên Liệu', 'A Gatherer''s Adventure In Isekai', 'https://phimimg.com/upload/vod/20251001-1/3ba23a2c75afd8600d913fdc9687bbe8.jpg', 'https://phimimg.com/upload/vod/20251001-1/01b2de7374a95d06196669c8446520c6.jpg', '<p>Câu chuyện xoay quanh Takeru Kamishiro, một nhân viên văn phòng bình thường, bỗng bị triệu hồi đến &quot;Madeus&quot;, một thế giới đầy rầy kiếm và ma thuật. Tại đây, anh được sở hữu nhiều kỹ năng đặc biệt, bao gồm sức mạnh thể chất vượt trội, khả năng ma thuật đặc biệt và &quot;tìm kiếm&quot; kho báu quý giá. Với những kỹ năng này, Takeru bắt đầu cuộc phiêu lưu mới đầy thú vị ở dị giới!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 244, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Nobunaga Shimazaki","avatar":""},{"name":"Makoto Koichi","avatar":""},{"name":"Ayasa Ito","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Souzai Saishuka no Isekai Ryokouki","Sozai Saishuka no Isekai Ryokouki","Sozai Saishuka no Isekai Ryokoki","A Gatherers Adventure in Isekai","素材採取家の異世界旅行記"]', 1784690324140);
