INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('binh-ngung-huu-lenh', 'Bình Ngưng Hữu Lệnh', 'The Princess Decree', 'https://phimimg.com/upload/vod/20251203-1/5014e160141b39dd0e5a89258e12cfae.jpg', 'https://phimimg.com/upload/vod/20251203-1/9f4a85f1fd9977da9aee2bb34f4f7f65.jpg', '<p>Một cuộc báo thù nảy sinh từ hôn nhân hòa thân đã khiến trưởng công chúa trở về phải yêu hận đan xen với người yêu cũ trên triều đình. Cuối cùng, họ nhận ra rằng chính đối phương mới là cứu rỗi duy nhất của nhau. Họ đã cùng nhau lấy giang sơn làm bàn cờ, chung tay tạo nên một thời kỳ thịnh thế.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Khương Trinh Vũ","avatar":""},{"name":"Tần Hiểu Hiên","avatar":""},{"name":"Lưu Yến Kiều","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["An Order From Pingning","平凝有令"]', 1784690324140);
