INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-sat-tieu-thuyet-gia-2', 'Ám Sát Tiểu Thuyết Gia 2', 'A Writer''s Odyssey 2', 'https://phimimg.com/upload/vod/20251216-1/aced3fece2e33b5c7a55d1bcab62a799.jpg', 'https://phimimg.com/upload/vod/20251216-1/2b9cfa25fea46b0d373de9087f04f6bd.jpg', '<p>Nhà văn Lộ Khổng Văn, đang ở thời điểm khó khăn nhất trong cuộc đời, bị cuốn hút bởi một cám dỗ lớn, dẫn ông và các nhân vật trong cuốn sách của ông vào một cuộc khủng hoảng không thể đảo ngược. Cuối cùng, nhà văn lấy lại được niềm tin của mình và cùng với các nhân vật trong cuốn sách của ông, cứu thế giới song song khỏi khủng hoảng.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Đặng Siêu","avatar":""},{"name":"Đổng Tử Kiện","avatar":""},{"name":"Lôi Giai Âm","avatar":""},{"name":"Vương Thánh Địch","avatar":""},{"name":"Đinh Trình Hâm","avatar":""},{"name":"Vương Nghiêm Lâm","avatar":""},{"name":"Đặng Phi","avatar":""},{"name":"Trương Chấn","avatar":""},{"name":"Tân Chỉ Lôi","avatar":""},{"name":"Quách Kinh Phi","avatar":""},{"name":"Thường Viễn","avatar":""},{"name":"Trần Hạo Vũ","avatar":""},{"name":"Quách Phàm","avatar":""},{"name":"Nhiêu Hiểu Chí","avatar":""},{"name":"Phần Hàn","avatar":""},{"name":"Tả Lăng Phong","avatar":""},{"name":"Lưu Đồng","avatar":""},{"name":"Dương Dật","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Assassin in Red 2","Ci Sha Xiao shuo jia 2","刺殺小說家2","刺杀小说家2","A Writer''s Odyssey Ⅱ",