INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-toc-huy-hoang', 'Gia Tộc Huy Hoàng', 'The Royal Family', 'https://phimimg.com/upload/vod/20251013-1/04736f37c3ec481379ca4313df81a350.jpg', 'https://phimimg.com/upload/vod/20251013-1/768af16e154b1c99bcef2b4c5ec43750.jpg', '<p>Ước ao được làm việc tại công ty của bố mình nhưng không thành, kế toán thuế nọ gặp người chủ ngựa giàu có rồi bị cuốn vào thế giới đua ngựa.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Satoshi Tsumabuki","avatar":""},{"name":"Koichi Sato","avatar":""},{"name":"Ren Meguro","avatar":""},{"name":"Wakana Matsumoto","avatar":""},{"name":"Hitomi Kuroki","avatar":""},{"name":"Kotaro Koizumi","avatar":""},{"name":"Ikki Sawamura","avatar":""},{"name":"Masanobu Ando","avatar":""},{"name":"Mahiro Takasugi","avatar":""},{"name":"Hisashi Yoshizawa","avatar":""},{"name":"Kenjiro Tsuda","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["皇家","荣耀家族","幸せの道","日曜劇場 ザ・ロイヤルファミリー","The Royal Family","Passing the Reins","ザ・ロイヤルファミリー"]', 1784690324140);
