INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chad-powers', 'Chad Powers', 'Chad Powers', 'https://phimimg.com/upload/vod/20251010-1/bf286266629a43d56e42211366579685.jpg', 'https://phimimg.com/upload/vod/20251010-1/b8eee31350c8d3654682d9001b11d653.jpg', '<p>Tám năm sau sai lầm không thể tha thứ đã hủy hoại sự nghiệp bóng bầu dục đại học đầy triển vọng, Russ Holliday, một tiền vệ tài năng nhưng kiêu ngạo, cố gắng làm lại cuộc đời. Với mái tóc giả và danh tính mới – Chad Powers, anh gia nhập đội bóng yếu thế South Georgia Catfish, hy vọng hồi sinh giấc mơ tưởng chừng đã tắt.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Glen Powell","avatar":""},{"name":"Steve Zahn","avatar":""},{"name":"Perry Mattfeld","avatar":""},{"name":"Frankie A. Rodriguez","avatar":""},{"name":"Quentin Plair","avatar":""},{"name":"Wynn Everett","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chad Powers"]', 1784690324140);
