INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chad-powers', 'Chad Powers', 'Chad Powers', 'chad powers chad powers glen powell steve zahn perry mattfeld frankie a. rodriguez quentin plair wynn everett chad powers', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trum-cuoi-hoang-da-gia-lam', 'Trùm Cuối Hoang Dã Giá Lâm!', 'A Wild Last Boss Appeared!', 'https://phimimg.com/upload/vod/20251001-1/08cd2de5a804f2d7e7b8069988c5d227.jpg', 'https://phimimg.com/upload/vod/20251001-1/e5cca753c78b4c1c3b49b5813c8428d7.jpg', '<p>Một game thủ MMO bất ngờ tỉnh dậy trong thân phận Bạo Quân Hắc Dực – Lufas Maphaahl, người từng bị phong ấn bởi số mệnh. Nhưng lần này, tất cả lại là thế giới thật. Thất bại của cô 200 năm trước đã mở đường cho những quái vật chết chóc tràn ra, và truyền thuyết về cô chỉ còn là nỗi kinh hoàng. Giờ đây, bị mắc kẹt trong thân thể của kẻ chinh phạt đáng sợ nhất lịch sử, Lufas phải tìm cách sinh tồn giữa một thế giới coi mình là kẻ thù… đồng thời khám phá lý do tại sao bản thân lại có mặt ở nơi này.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ami Koshimizu","avatar":""},{"name":"Yuri Usui","avatar":""},{"name":"Yukina Shuto","avatar":""},{"name":"Naoya Uchida","avatar":""},{"name":"Hisako Tojo","avatar":""},{"name":"Cocoro Omori","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["野生的LAST BOSS出现了!","野生的最终BOSS出现了！","Yasei no Last Boss ga Arawareta!","Yasei no Rasu Bosu ga Arawareta!","野生のラスボスが現れた!"]', 1784690324140);
