INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('trum-cuoi-hoang-da-gia-lam', 'Trùm Cuối Hoang Dã Giá Lâm!', 'A Wild Last Boss Appeared!', 'trùm cuối hoang dã giá lâm! a wild last boss appeared! ami koshimizu yuri usui yukina shuto naoya uchida hisako tojo cocoro omori 野生的last boss出现了! 野生的最终boss出现了！ yasei no last boss ga arawareta! yasei no rasu bosu ga arawareta! 野生のラスボスが現れた!', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-pham', 'Phi Phàm', 'Extraordinary', 'https://phimimg.com/upload/vod/20251202-1/18f8149dd7b09893a286e1fb9e818509.jpg', 'https://phimimg.com/upload/vod/20251202-1/ad3b60ef40f1b89d956a83a3f9b276d4.jpg', '<p>Thạch Phi Phàm, một chàng trai mê lịch sử sống ở thời hiện đại, bất ngờ xuyên qua giấc mộng đến Đại Nam Triều, trở thành công tử trùng tên trứ danh ăn chơi lêu lổng. Để giữ vững cơ nghiệp nhà họ Thạch, hắn bề ngoài ngông cuồng tiêu tiền như nước, nhưng sau lưng lại âm thầm vận dụng kiến thức hiện đại để xoay chuyển thời cuộc. Từ khuấy đảo thị trường tơ lụa để trở thành phú hộ khét tiếng, phá giải âm mưu của người Khương, cứu Trưởng Công chúa khỏi hiểm cảnh, đến trừ khử thân vương tâm địa độc ác, vì thế mà hắn dần được Hoàng đế ngầm tín nhiệm. Khi được điều tới Tây Sơn để chấn chỉnh quân đội, kẻ từng bị coi thường năm ấy lại chậm rãi lột xác, âm thầm nắm giữ binh quyền.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Phó Vĩ Luân","avatar":""},{"name":"Viên Y","avatar":""},{"name":"Hồ Vân Hào","avatar":""},{"name":"Cao Quảng Trạch","avatar":""},{"name":"Phan Duyệt","avatar":""},{"name":"Triệu Húc An Sinh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Extraordinary","非凡"]', 1784690324140);
