INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phi-pham', 'Phi Phàm', 'Extraordinary', 'phi phàm extraordinary phó vĩ luân viên y hồ vân hào cao quảng trạch phan duyệt triệu húc an sinh extraordinary 非凡', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-trieu-thanh-danh', 'Nhất Triều Thành Danh', 'Genesis', 'https://phimimg.com/upload/vod/20251210-1/612d9b742579a04f1a19117b121ebd5c.jpg', 'https://phimimg.com/upload/vod/20251210-1/10e1212c3e4dd2278899814ee198656e.jpg', '<p>Thiếu niên thiên tài Lâm Đông Phong và thiên kim tiểu thư giàu có Trịnh Uyển Chi là một cặp đôi trong trường học, đang cố gắng cứu vãn tình thế &quot;tốt nghiệp là chia tay&quot;.Đúng lúc đó, Cố Băng Khanh, người phụ trách một tập đoàn công nghệ lớn trong nước, gửi lời mời làm việc đến Lâm Đông Phong.Trong khi Lâm Đông Phong còn đang do dự, những phát ngôn của anh trên mạng về công nghệ phản ứng tổng hợp hạt nhân có thể kiểm soát đã thu hút sự chú ý lớn từ trong và ngoài nước.Thái Đẩu vật lý học Ngô Văn Dũng phát hiện ra tài năng thiên bẩm của Lâm Đông Phong, và dưới sự dẫn dắt của Bộ trưởng Bộ Khoa học Công nghệ Dương Chính Đạo, nhóm &quot;Truy Nhật Tiểu Tổ&quot; (Nhóm Đuổi Bắt Mặt Trời) được thành lập, do Lâm Đông Phong lãnh đạo để chinh phục công nghệ này.Ở các giai đoạn thí nghiệm khác nhau, Lâm Đông Phong phải đối mặt với nhiều thử thách như: sự đánh cắp từ đối thủ, lựa chọn tình cảm, và sự kiểm tra nội bộ.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Giai Huyên","avatar":""},{"name":"Thiên Thiên Di","avatar":""},{"name":"An Kỳ","avatar":""},{"name":"Mạnh Thiên Ân","avatar":""},{"name":"Trương Vân Khánh","avatar":""},{"name":"Trịnh Tiểu Mao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["一朝成名"]', 1784690324140);
