INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhat-trieu-thanh-danh', 'Nhất Triều Thành Danh', 'Genesis', 'nhất triều thành danh genesis vương giai huyên thiên thiên di an kỳ mạnh thiên ân trương vân khánh trịnh tiểu mao 一朝成名', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-sinh-ton-cua-nhung-nguoi-dan-ong-o-nha-tu', 'Nhật Ký Sinh Tồn Của Những Người Đàn Ông Ở Nhà Tù', 'Oops! I''m In Jail', 'https://phimimg.com/upload/vod/20251117-1/66a048b16910364c4544dbdc03343d4d.jpg', 'https://phimimg.com/upload/vod/20251117-1/51d74aaa45d73326fc338de0b6cacd60.jpg', '<p>Một ngôi sao taekwondo trẻ — A-Yao (do Trần Trạch Diêu đóng) — vì chấn thương phải giải nghệ, rồi sa vào cờ bạc để trả nợ. Để trả nợ, anh bị ép vào làm nhân viên quản lý trại giam, chăm sóc “ông trùm” trong tù, Gi-Wa-Wa (do Dương Dự Nhân đóng). Tưởng rằng công việc trong trại sẽ dễ chịu, A-Yao mới nhận ra rằng đồng nghiệp của mình cũng “thảm”: có người là kẻ thi trượt mãi, có người là cha trẻ nhút nhát. Họ phải trải qua những “buổi đào tạo” cực kỳ lố và hài hước: đánh trấn áp vũ trang, kiểm tra toàn thân bị bẩn, tù nhân tự tử… Mặc dù là quản giáo, nhưng thực tế vị trí của họ thấp đến mức nhiều khi “không hơn gì tù nhân”.&nbsp; Trong khi đó, Giáo huấn viên Jiang Yijie (do Lưu Dĩ Hào đóng) để ý rất kỹ đến mối quan hệ “đặc biệt” giữa A-Yao và Gi-Wa-Wa, khiến A-Yao luôn cảm thấy như mình đang “chơi một canh bạc sinh tử”. Dần dần, giữa hỗn loạn và khổ cực, A-Yao và đồng nghiệp xây dựng được sự thấu hiểu, tình bạn và thậm chí tình cảm. Họ cùng nhau sinh tồn trong môi trường “giống như bị giam cầm hơn cả tù nhân”, và tìm thấy ý nghĩa thật sự của công việc này.&nbsp;</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Lưu Dĩ Hào","avatar":""},{"name":"Trần Trạch Diêu","avatar":""},{"name":"Thẩm Minh Sài","avatar":""},{"name":"Trương Hiên Rui","avatar":""},{"name":"Khưu Dĩ Thái","avatar":""},{"name":"Thất Danh Suất","avatar":""},{"name":"Dạ Tư Oánh","avatar":""},{"name":"Mộc Mỹ","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["監所男子求生記","監所男子囚生記"]', 1784690324140);
