INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhat-ky-sinh-ton-cua-nhung-nguoi-dan-ong-o-nha-tu', 'Nhật Ký Sinh Tồn Của Những Người Đàn Ông Ở Nhà Tù', 'Oops! I''m In Jail', 'nhật ký sinh tồn của những người đàn ông ở nhà tù oops! i''m in jail lưu dĩ hào trần trạch diêu thẩm minh sài trương hiên rui khưu dĩ thái thất danh suất dạ tư oánh mộc mỹ 監所男子求生記 監所男子囚生記', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mang-me-di-bo', 'Mang Mẹ Đi Bỏ', 'Leaving Mom', 'https://phimimg.com/upload/vod/20251202-1/7747d4679d743d8552b22c5709cc4e49.jpg', 'https://phimimg.com/upload/vod/20251202-1/b4e2708b399a01527a25eab36d52ad96.jpg', '<p>Rời Xa Mẹ kể về câu chuyện của Hoan (Tuấn Trần), một chàng trai trẻ kiếm sống bằng nghề cắt tóc &quot;gã hề đường phố&quot; để chăm sóc mẹ. Mẹ anh, Lê Thị Hạnh (Hồng Đào), mắc bệnh Alzheimer và cư xử như một đứa trẻ. Căn bệnh của bà không chỉ là gánh nặng tài chính mà còn tước đi cuộc sống tự do và những ước mơ mà anh vẫn đang theo đuổi. Một ngày nọ, Hoan đưa ra một quyết định định mệnh - &quot;gửi mẹ&quot; cho anh trai mình ở Hàn Quốc, một người mà anh thậm chí chưa từng gặp mặt...</p>', 'Full', 1, 'single', 'completed', 19, 2025, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Tuấn Trần","avatar":""},{"name":"Hồng Đào","avatar":""},{"name":"Juliet Bảo Ngọc Doling","avatar":""},{"name":"Jung Il-woo","avatar":""},{"name":"Quốc Khánh","avatar":""},{"name":"Hải Triều","avatar":""},{"name":"Vinh Râu","avatar":""},{"name":"Lâm Vỹ Dạ","avatar":""},{"name":"Go Kyung-pyo","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mang Mẹ Đi Bỏ"]', 1784690324140);
