INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mang-me-di-bo', 'Mang Mẹ Đi Bỏ', 'Leaving Mom', 'mang mẹ đi bỏ leaving mom tuấn trần hồng đào juliet bảo ngọc doling jung il-woo quốc khánh hải triều vinh râu lâm vỹ dạ go kyung-pyo mang mẹ đi bỏ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('treo-deo-loi-suoi-den-ben-ong', 'Trèo Đèo Lội Suối Đến Bên Ông', 'Walking To You', 'https://phimimg.com/upload/vod/20251214-1/e481a0b13ac51a48974dbec6b1a54ad5.jpg', 'https://phimimg.com/upload/vod/20251214-1/5121aed561b7751359e595002e5bf3f0.jpg', '<p>Biệt Khắc, một cậu bé 12 tuổi sống ở khu vực chăn nuôi A Lặc Thái, Tân Cương, đã mang theo một con lạc đà mẹ trắng, bắt đầu chuyến hành trình dài từ Tân Cương đến Thành Đô để gửi sữa lạc đà tươi cho &quot;Ông nội Lạc đà&quot;&nbsp; đang bị bệnh.Trên đường đi, cậu bé tình cờ gặp gỡ Thanh Thanh , một nhân viên văn phòng ở thành phố đang mắc bệnh nan y. Hai người xa lạ đã cùng nhau chữa lành cho nhau trong suốt chuyến đi, cùng nhau hoàn thành một cuộc phiêu lưu về tình yêu và sự kiên định.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Uyển Lộ","avatar":""},{"name":"Tang Tông Trung","avatar":""},{"name":"Ba La Sa Thất","avatar":""},{"name":"Á Ây Khất Thất","avatar":""},{"name":"A Kế Thái","avatar":""},{"name":"Hạp Tư Thiết Nhĩ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Across Mountains & Seas to Reach You","The Mysterious White-Camel Adventure","穿越山海走向你"]', 1784690324140);
