INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('treo-deo-loi-suoi-den-ben-ong', 'Trèo Đèo Lội Suối Đến Bên Ông', 'Walking To You', 'trèo đèo lội suối đến bên ông walking to you lưu uyển lộ tang tông trung ba la sa thất á ây khất thất a kế thái hạp tư thiết nhĩ across mountains & seas to reach you the mysterious white-camel adventure 穿越山海走向你', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-sot-tro-ve', 'Sống Sót Trở Về', 'Survival', 'https://phimimg.com/upload/vod/20251214-1/fbc4e798f6aeb685d6dafd0df734297a.jpg', 'https://phimimg.com/upload/vod/20251214-1/09ce9970ec0570945c1e44d308c81eed.jpg', '<p>Bộ phim tái hiện câu chuyện có thật về Đoàn Trú Thủ (gồm nữ binh và thương binh) của Quân đoàn 6 Liên quân Kháng Nhật từ năm 1938 đến 1945.&nbsp; Sau khi lực lượng chủ lực rút đi, họ kiên trì bám trụ để kìm chân quân địch. Họ đã đột phá thành công vòng vây, rút vào Liên Xô để chỉnh huấn, sau đó được biên chế thành Lữ đoàn Huấn luyện 88 và quay trở lại Đông Bắc.&nbsp; Toàn bộ hành trình gian khổ, từ sự hy sinh đến sự sinh tồn của các chiến sĩ, được kể lại qua góc nhìn của nữ chiến sĩ 12 tuổi Lý Đồng.</p>', 'Full', 1, 'single', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Thiệu Chính Nhất","avatar":""},{"name":"Chu Tư Vũ","avatar":""},{"name":"Chu Vân Bằng","avatar":""},{"name":"Bành Du Tư","avatar":""},{"name":"Hứa Lợi","avatar":""},{"name":"Hầu Kỷ Âm","avatar":""},{"name":"Lưu Địch","avatar":""},{"name":"Lương Tống Thanh","avatar":""},{"name":"Đoàn Khưu Vũ","avatar":""},{"name":"Chu Hồng Gia","avatar":""},{"name":"Cao Uy Vũ","avatar":""},{"name":"Mã Quốc Vĩ","avatar":""},{"name":"Dương Kỳ Minh","avatar":""},{"name":"Lộ Trường Ân","avatar":""},{"name":"Miêu Bá","avatar":""},{"name":"Trịnh Hạo","avatar":""},{"name":"Trương Hồng Vĩ","avatar":""},{"name":"Dã Phúc Thăng","avatar":""},{"name":"Hà Giáo Thụ","avatar":""},{"name":"Vương Ki","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e