INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('song-sot-tro-ve', 'Sống Sót Trở Về', 'Survival', 'sống sót trở về survival thiệu chính nhất chu tư vũ chu vân bằng bành du tư hứa lợi hầu kỷ âm lưu địch lương tống thanh đoàn khưu vũ chu hồng gia cao uy vũ mã quốc vĩ dương kỳ minh lộ trường ân miêu bá trịnh hạo trương hồng vĩ dã phúc thăng hà giáo thụ vương ki 生还', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-thap-anh-hung', 'Song Tháp Anh Hùng', 'Chi Yan 1945 (Heroes Of The Twin Towers)', 'https://phimimg.com/upload/vod/20251214-1/8533f8f63d5a7154fd5b18752f267049.jpg', 'https://phimimg.com/upload/vod/20251214-1/1f4c47bf210e37ea20037425175f881e.jpg', '<p>Bộ phim lấy bối cảnh cuối cuộc Chiến tranh kháng chiến chống Nhật năm 1945. Để phối hợp với Hồng quân Liên Xô phản công tại Thừa Đức, Khu Quân sự Ký Nhiệt Liêu đã cử đại đội trưởng Trương Tuấn đến nhậm chức đội trưởng khu du kích Song Tháp Sơn, triển khai chiến thuật nội ứng ngoại hợp.Trước khi Trương Tuấn đến nhậm chức, đội du kích liên tục bị tổn thất nặng nề do địa chủ Nghiêm Thế Xương cấu kết với quân Nhật và ngụy quyền. Đội trưởng tiền nhiệm Triệu Sơn Lâm đã hy sinh, và căn cứ địa đứng trước nguy cơ thất thủ.Trên đường đi, Trương Tuấn đã mưu trí bắt sống Ngô Đức Toàn, đội trưởng ngụy quân, buộc hắn phải nộp vũ khí tại cứ điểm. Số vũ khí thu được đã giải quyết phần nào tình trạng thiếu thốn trang bị của đội du kích.Sau đó, anh liên kết với trưởng thôn Lâm Giang, chủ nhiệm hội phụ nữ Xuân Linh và những người khác để chấn chỉnh lại đội ngũ, đồng thời kết giao với Phùng Giai Cát, cựu thủ lĩnh núi Kê Quan. Phùng có mối thù cũ với Nghiêm Thế Xương và một lòng muốn báo thù, sau đó đã hợp tác với Trương Tuấn để tiêu diệt kẻ địch.Trương Tuấn đã lợi dụng cơ hội Nghiêm Thế Xương cưỡng ép cưới con gái của Triệu Sơn Lâm là Triệu Giai Huệ để bố trí phục kích, tiêu diệt nhiều tên Nhật và ngụy quân. Giai Huệ tự tay bắn chết Tiểu Lâm, tên sĩ quan Nhật đã giết cha mình, còn Phùng Giai Cát cũng tự tay báo thù Nghiêm Thế Xương.</p>', 'Full', 1, 'single', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hồ Tiểu Cương","avatar":""},{"name":"Quách Lệ Vũ","avatar":""},{"name":"Phó Tử Hảo","avatar":""},{"name":"Triệu Vũ Minh","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["双塔英雄"]', 1784690324140);
