INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('song-thap-anh-hung', 'Song Tháp Anh Hùng', 'Chi Yan 1945 (Heroes Of The Twin Towers)', 'song tháp anh hùng chi yan 1945 (heroes of the twin towers) hồ tiểu cương quách lệ vũ phó tử hảo triệu vũ minh 双塔英雄', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-ngoai-hanh-tinh-loi-hai', 'Người Ngoài Hành Tinh Lợi Hại', 'The Amazing Alien', 'https://phimimg.com/upload/vod/20251214-1/f66cf82ca4a727f9a638c514300e2983.jpg', 'https://phimimg.com/upload/vod/20251214-1/ec11281f49688a5970614ea849cfeda2.jpg', '<p>Đội thám hiểm trong một hang động dưới nước đã vô tình chạm vào một thiết bị mà người ngoài hành tinh để lại trên Trái Đất, từ đó gây ra một loạt sự kiện kỳ lạ. Người ngoài hành tinh tìm đến Lý Thần Long, mong muốn anh giúp họ trở về hành tinh Zero bởi tổ tiên của Lý Thần Long đã từng nhận từ tổ tiên của người ngoài hành tinh một chiếc chìa khóa có thể mở ra thiết bị &quot;Thiên Quốc Cấm Thư&quot;. Vì vậy, Lý Thần Long và người ngoài hành tinh bắt đầu một cuộc hành trình kỳ lạ và mạo hiểm để tìm &quot;chìa khóa&quot;.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ken Lok","avatar":""},{"name":"Lộ Tuấn Dao","avatar":""},{"name":"Đỗ Tông Hoa","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["了不起的外星人"]', 1784690324140);
