INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lac-trong-hao-quang', 'Lạc Trong Hào Quang', 'Lost In The Spotlight', 'https://phimimg.com/upload/vod/20251214-1/c570303a2d82a64cfd61a9746bb3e116.jpg', 'https://phimimg.com/upload/vod/20251214-1/3162128167468d9d1a18b1c42a50a536.jpg', '<p>Ngay khi giành được vai diễn danh giá, nam diễn viên nổi tiếng nọ bỗng mất đi khả năng diễn xuất một cách bí ẩn, mở ra hành trình tự khám phá bản thân giữa áp lực dư luận.</p>', 'Full', 1, 'single', 'completed', 30, 2025, 'Vietsub', 'FHD', 'Indonesia', 0, '[{"name":"Vino G. Bastian","avatar":""},{"name":"Dea Panendra","avatar":""},{"name":"Agus Kuncoro","avatar":""},{"name":"Emil Kusumo","avatar":""},{"name":"Sadha Triyudha","avatar":""},{"name":"Mike Lucock","avatar":""},{"name":"Sheila Dara Aisha","avatar":""},{"name":"Morgan Oey","avatar":""},{"name":"Lukman Sardi","avatar":""},{"name":"Arswendy Bening Swara","avatar":""},{"name":"Nadine Alexandra","avatar":""},{"name":"Aci Resti","avatar":""},{"name":"Fico Fachriza","avatar":""},{"name":"Yudha Brajamusti","avatar":""},{"name":"Priska Baru Segu","avatar":""},{"name":"Guzman Sige","avatar":""},{"name":"Mega Sa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Actor","Lupa Daratan"]', 1784690324140);
