INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-hoach-bat-coc-vo', 'Kế Hoạch Bắt Cóc Vờ', 'The Fakenapping', 'https://phimimg.com/upload/vod/20251214-1/7340eb524ba2c472a422eee22aa590d4.jpg', 'https://phimimg.com/upload/vod/20251214-1/fdc51ad696fec5f4ae491d48be7241df.jpg', '<p>Sattam – một doanh nhân thất bại và là người bố đang túng quẫn – bị cuốn vào một âm mưu điên rồ khi anh quyết định trả nợ bằng cách bắt cóc chính bố mình.</p>', 'Full', 1, 'single', 'completed', 22, 2025, 'Vietsub', 'FHD', 'Ả Rập Xê Út', 0, '[{"name":"Mohammed Aldokhei","avatar":""},{"name":"Abdullah alDaris","avatar":""},{"name":"Yazeed Almajyul","avatar":""},{"name":"Khaled Ahamd Hwijan","avatar":""},{"name":"Saeed Alewiran","avatar":""},{"name":"Abdulaziz Al-Sokayreen","avatar":""},{"name":"Saeed Al-Owairan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["رهين"]', 1784690324140);
