INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyet-chien-den-cung', 'Huyết Chiến Đến Cùng', 'Fight To The Death', 'https://phimimg.com/upload/vod/20251214-1/256616f92b41f31c6840bb980a2c90b4.jpg', 'https://phimimg.com/upload/vod/20251214-1/ad9d25de9a6514cd248a4ce93d95ab5c.jpg', '<p>Trong trận chiến bảo vệ Phồn Xương năm 1939, trung đội trưởng của Tân Tứ Quân Chu Chấn dẫn dắt đội hộ tống nữ phóng viên Lục Anh. Cô là người nắm giữ bằng chứng tội ác của quân Nhật tại Nam Kinh và kế hoạch tác chiến của chúng. Trên đường đi, họ liên tục bị quân Nhật truy đuổi và chặn đánh, đồng đội lần lượt hy sinh. Trải qua phục kích trên cánh đồng tuyết, chiến đấu sinh tử trong hang núi và vô số thử thách khác, cuối cùng Chu Chấn anh dũng hy sinh. Lục Anh thành công đưa bằng chứng về căn cứ, giúp Tân Tứ Quân giành thắng lợi và phơi bày tội ác của quân Nhật.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Quốc Khôn","avatar":""},{"name":"Phàn Thiếu Hoàng","avatar":""},{"name":"Trương Tấn","avatar":""},{"name":"Lý Khải Hinh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["血战到底"]', 1784690324140);
