INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('huyet-chien-den-cung', 'Huyết Chiến Đến Cùng', 'Fight To The Death', 'huyết chiến đến cùng fight to the death trần quốc khôn phàn thiếu hoàng trương tấn lý khải hinh 血战到底', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngot-ngao-vua-van-tuoi-ba-muoi', 'Ngọt Ngào Vừa Vặn Tuổi Ba Mươi', 'Bestie Rivals', 'https://phimimg.com/upload/vod/20251214-1/625faea5d0373b9c38591484ef1dc3dc.jpg', 'https://phimimg.com/upload/vod/20251214-1/6a120e5a38fdfc7e9e3d299f014c1553.jpg', '<p>Hai người phụ nữ bị cùng một người đàn ông lừa dối – Mạnh Hạ (quản lý giỏi, mạnh mẽ) và Thang Linh (kỹ thuật viên SPA, yếu đuối) – trở thành &quot;bạn thân giả&quot; sau một đám tang. Họ vừa đấu khẩu vừa thân thiết hơn. Sự xuất hiện của nhiếp ảnh gia trẻ Kim Triết khiến cả hai tranh giành, nhưng anh không đáp lại. Cuối cùng, họ nhận ra sự vô nghĩa của việc cạnh tranh tình ái, tìm thấy giá trị bản thân và xây dựng được tình bạn chân thật.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Văn Kỳ","avatar":""},{"name":"Dương Nguyệt Tâm","avatar":""},{"name":"Trần Đức Dung","avatar":""},{"name":"Chung Tuấn Thắng","avatar":""},{"name":"Hoàng Bác Quân","avatar":""},{"name":"Kỷ Vũ Điện","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["甜蜜恰好也三十"]', 1784690324140);
