INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loc-du-ky', 'Lộc Du Ký', 'Deer Travel Notes', 'https://phimimg.com/upload/vod/20251214-1/b958c60ba195b9b80bee4a1d29d68d77.jpg', 'https://phimimg.com/upload/vod/20251214-1/c537932353b2a4bec5c08ca173e6a698.jpg', '<p>Truyền thuyết kể rằng, rất lâu trước đây, ở hạ lưu Âu Giang có hai con yêu tinh rùa và yêu tinh rắn tạo nghiệp. Thiền sư Thanh Liễu được chỉ thị đến đây để tiêu diệt yêu ma, trấn yểm hai con yêu tinh này ở cạnh núi La Phù, biến chúng thành núi Rùa và núi Rắn. Thời gian trôi qua, vùng đất Nguyệt Sắc Cảnh của Âu Giang dần bị tàn phá và mất đi pháp lực. Hai con yêu tinh rùa và rắn muốn nhân cơ hội này để phá vỡ phong ấn. Lúc này, Tiểu Lộc cùng Tiểu Âu bắt đầu con đường trấn yêu, bước vào Nguyệt Sắc Cảnh của Âu Giang, tái tạo lại &quot;Thanh Huy Dục Quang.&quot;</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["鹿游记"]', 1784690324140);
