INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-nuong-the-than-2025', 'Tân Nương Thế Thân', 'Marry Him In Her Place', 'https://phimimg.com/upload/vod/20251201-1/e6fccf52969c07e88df1027cf1850cfb.jpg', 'https://phimimg.com/upload/vod/20251201-1/cfbc3f34bdde51604a1161d3d27cb4d1.jpg', '<p>Trong đêm tân hôn, thiên kim tiểu thư nhà giàu Lương Ý bị chính người chồng là Tống Chi Sơ hủy hoại dung nhan và ném xuống sông. Bất ngờ, cô được cứu sống, nhưng buộc phải thay đổi khuôn mặt và trở thành Từ Nhân—một kỹ nữ.&nbsp; &quot;Mặt nạ tốt nhất trên đời này, chính là một khuôn mặt đang sống khác.&quot;&nbsp; Vì vậy, được tái sinh, cô lợi dụng thân phận Từ Nhân để tiếp cận Lâm Vân, một ông trùm băng đảng, và từ đó khởi động con đường báo thù của mình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Nhâm Thế Hào","avatar":""},{"name":"Lưu Niệm","avatar":""},{"name":"Vương Trạch Huyền","avatar":""},{"name":"Văn Tình","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Qu Er Dai Zhi","娶而代之"]', 1784690324140);
