INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-an-toan-cua-em', 'Vùng An Toàn Của Em', 'My Safe Zone', 'https://phimimg.com/upload/vod/20251026-1/4f57d0d6ffec0bc3067b60139dc61384.jpg', 'https://phimimg.com/upload/vod/20251026-1/f5387e7686a4a4e164c893c3d1cc3896.jpg', '<p>Alin rời xa người bạn thân Jane để đi du học. Nhiều năm sau, một cuộc hôn nhân tan vỡ đưa cô trở về nhà, nơi họ đối mặt với những cảm xúc giấu kín từ lâu.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Lorena Schuett","avatar":""},{"name":"Natsha Taechamongkalapiwat","avatar":""},{"name":"Anada Prakobkit","avatar":""},{"name":"Pareena Busayasiri","avatar":""},{"name":"Peerakrit Phacharaboonyakiat","avatar":""},{"name":"Supranee Charoenpol","avatar":""},{"name":"Arisara Wongchalee","avatar":""},{"name":"Janjira Janpitakchai","avatar":""},{"name":"Worawat Boonchuen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["My Safe Zone Series","รักสุดท้าย"]', 1784690324140);
