INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hoang-tin-tuc-phan-2', 'Nữ Hoàng Tin Tức (Phần 2)', 'The Queen Of News (Season 2)', 'https://phimimg.com/upload/vod/20251114-1/4057c234b493167eae1e50321697f1ea.jpg', 'https://phimimg.com/upload/vod/20251114-1/488247d3e51217b189e30fbd3774776d.jpg', '<p>Sau khi rời khỏi đài truyền hình SNK, nữ hoàng tin tức Văn Tuệ Tâm quyết định lui về hậu trường. Cùng lúc đó, SNK xảy ra biến cố lớn khi phóng viên Lương Cảnh Nhân hy sinh trong lúc làm tin. Dưới sự quản lý của Tổng giám đốc Cổ Triệu Hoa và Phó tổng giám đốc Trương Gia Nghiên, SNK dần đánh mất lý tưởng báo chí khi Cổ Triệu Hoa xem tin tức như công cụ kiếm tiền. Trong khi đó, Tuệ Tâm tái xuất, thu mua công ty truyền thông số của Lưu Diễm để thách thức truyền thông truyền thống. Cuộc chiến giữa hai thế giới - truyền thông số và truyền thông cũ - trở nên khốc liệt khi mỗi bên đều có những toan tính và bí mật riêng. Khi tham vọng quyền lực vượt qua giới hạn đạo đức, Tuệ Tâm buộc phải đứng lên, mở màn cho cuộc phản công quyết liệt giữa “nữ hoàng” và “ông hoàng” tin tức.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 21, 2025, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Xa Thi Mạn","avatar":""},{"name":"Huỳnh Tông Trạch","avatar":""},{"name":"Mã Quốc Minh","avatar":""},{"name":"Lý Thi Hoa","avatar":""},{"name":"Cao Hải Ninh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["新闻女王","新闻女王2","The.Queen.of.NEWS","The QUEEN of News 2","The Queen of NEWS","新聞女王","新聞女王Ⅱ","The Queen of News"]', 1784690324140);
