INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-dam-boc-christy', 'Vua Đấm Bốc Christy', 'Christy', 'https://phimimg.com/upload/vod/20251213-1/1089b31a1ebabecd098dd141a3eb37ce.jpg', 'https://phimimg.com/upload/vod/20251213-1/ae9e9dc106147c42a799764663d5c9d8.jpg', '<p>Christy Martin rời khỏi cuộc sống thị trấn nhỏ để bước vào làng quyền Anh nhờ tài năng và quyết tâm mạnh mẽ. Dưới sự dẫn dắt của Jim, người sau này trở thành chồng cô, Christy tỏa sáng trong võ đài nhưng đồng thời phải đối mặt với những cuộc chiến cá nhân còn nguy hiểm hơn: gia đình, danh tính bản thân và một mối quan hệ có thể đe dọa tất cả.</p>', 'Full', 1, 'single', 'completed', 19, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sydney Sweeney","avatar":""},{"name":"Ben Foster","avatar":""},{"name":"Merritt Wever","avatar":""},{"name":"Katy O''Brian","avatar":""},{"name":"Ethan Embry","avatar":""},{"name":"Jess Gabor","avatar":""},{"name":"Chad L. Coleman","avatar":""},{"name":"Tony Cavalero","avatar":""},{"name":"Miles Mussenden","avatar":""},{"name":"Gilbert Cruz","avatar":""},{"name":"James Self","avatar":""},{"name":"Bill Kelly","avatar":""},{"name":"Walter ''Buddy'' Carter","avatar":""},{"name":"Coleman Pedigo","avatar":""},{"name":"Tamara Hopkins","avatar":""},{"name":"Bryan Hibbard","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Christy"]', 1784690324140);
