INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lan-ranh-do', 'Lằn Ranh Đỏ', 'Frontier Crucible', 'https://phimimg.com/upload/vod/20251213-1/0ea4bcbc89a6297a57e48e66c9df2b65.jpg', 'https://phimimg.com/upload/vod/20251213-1/086e36f87ffa36e00cd5798e8c2ec8ce.jpg', '<p>Merrick Beckford phải hộ tống một xe vật tư y tế bị tấn công bởi người Apache. Anh hợp tác với ba kẻ bất hợp pháp để vượt qua vùng đất chết, nhưng khi nhóm vô tình giết một trinh sát Apache, họ trở thành mục tiêu săn đuổi và phải chiến đấu để sống sót.</p>', 'Full', 1, 'single', 'completed', 20, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Myles Clohessy","avatar":""},{"name":"Mary Stickley","avatar":""},{"name":"Armie Hammer","avatar":""},{"name":"William H. Macy","avatar":""},{"name":"Thomas Jane","avatar":""},{"name":"Ryan Masson","avatar":""},{"name":"Eli Brown","avatar":""},{"name":"Zane Holtz","avatar":""},{"name":"Eddie Spears","avatar":""},{"name":"Joshua Odjick","avatar":""},{"name":"Jonah Kagen","avatar":""}]', '[{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Испытания на фронтире","Frontier Crucible"]', 1784690324140);
