INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('simon-cowell-hoi-ke-tiep', 'Simon Cowell: Hồi Kế Tiếp', 'Simon Cowell: The Next Act', 'https://phimimg.com/upload/vod/20251212-1/aac1eb0af156c4b8c49d13c779b82b82.jpg', 'https://phimimg.com/upload/vod/20251212-1/84241d2f2eb340240aee6ea4de0c2044.jpg', '<p>Simon Cowell đang tìm kiếm ban nhạc nam đình đám tiếp theo. Ông sẵn sàng đánh cược tất cả để tìm ra họ. Liệu những ca sĩ trẻ này có chứng minh được ông vẫn còn giữ &quot;bàn tay vàng&quot;?</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Simon Cowell","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["西蒙·考威尔：再创传奇男团","Simon Cowell: The Next Act"]', 1784690324140);
