INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-ve-coi-chet', 'Đường Về Cõi Chết', 'Down Cemetery Road', 'https://phimimg.com/upload/vod/20251030-1/aed603082da818588441063c18b093d3.jpg', 'https://phimimg.com/upload/vod/20251030-1/31cdaf71d55056e898796545d14e23a8.jpg', '<p>Khi một đứa trẻ mất tích sau vụ nổ nhà, người hàng xóm sốt sắng hợp tác cùng một thám tử tư để đi tìm bé. Khi những bí mật dần hé lộ cùng một âm mưu quân sự, cả vùng ngoại ô Nam Oxford im lìm như choàng tỉnh giấc.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Emma Thompson","avatar":""},{"name":"Ruth Wilson","avatar":""},{"name":"Adeel Akhtar","avatar":""},{"name":"Nathan Stewart-Jarrett","avatar":""},{"name":"Tom Goodman-Hill","avatar":""},{"name":"Darren Boyd","avatar":""},{"name":"Tom Riley","avatar":""},{"name":"Adam Godley","avatar":""},{"name":"Sinead Matthews","avatar":""},{"name":"Ken Nwosu","avatar":""},{"name":"Fehinti Balogun","avatar":""},{"name":"Aiysha Hart","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["走向坟墓","坟场回路","למטה דרך בית הקברות","במורד דרך בית הקברות","Down Cemetery Road"]', 1784690324140);
