INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('duong-ve-coi-chet', 'Đường Về Cõi Chết', 'Down Cemetery Road', 'đường về cõi chết down cemetery road emma thompson ruth wilson adeel akhtar nathan stewart-jarrett tom goodman-hill darren boyd tom riley adam godley sinead matthews ken nwosu fehinti balogun aiysha hart 走向坟墓 坟场回路 למטה דרך בית הקברות במורד דרך בית הקברות down cemetery road', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dat-xanh-sinh-cu', 'Đất Xanh Sinh Cú', 'Love On The Turquoise Land', 'https://phimimg.com/upload/vod/20251122-1/35c0a7b76b0e0eabac88b98992d482cb.jpg', 'https://phimimg.com/upload/vod/20251122-1/a8e84ce04b37d1e9d881506fba4fd58b.jpg', '<p>Nhà văn Nhiếp Tịch, sau khi tham dự một buổi triển lãm lấy cảm hứng từ Sơn Hải Kinh, đã nảy ra ý tưởng và sáng tác nên một cuốn tiểu thuyết kỳ ảo mang đậm màu sắc phương Đông, đặt trong bối cảnh đô thị hiện đại. Câu chuyện xoay quanh “Nam Sơn Liệp Nhân” — một tổ chức bí mật tồn tại giữa dân gian. Tại đây, cô gái tinh thông đao pháp Nhiếp Cửu La và chàng trai chính trực, lạc quan nhưng mang trong mình bao oan khuất suốt nhiều năm — Viêm Thác — từ những va chạm ban đầu đã dần thấu hiểu nhau qua những lần kề vai sát cánh, cùng đối diện với muôn vàn hiểm nguy. Từ đó, sự tin tưởng và tình cảm giữa họ từng bước được vun đắp. Cuối cùng, cả hai hợp lực chống lại thế lực Địa Kiêu, bảo vệ tình yêu, gìn giữ bình yên cho thế gian và cùng nhau viết nên một cái kết hạnh phúc.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Địch Lệ Nhiệt Ba","avatar":""},{"name":"Trần Tinh Húc","avatar":""},{"name":"Trương Lệ","avatar":""},{"name":"Đổng Sướng","avatar":""},{"name":"Trương Diệc Trì","avatar":""},{"name":"Tô Hâm","avatar":""},{"name":"Nhan Trác Linh","avatar":""},{"name":"Lương Tụng Tinh","avatar":""},{"name":"Triệu Hân","avatar":""},{"name":"Phan Mỹ Diệp","avatar":""},{"name":"Điền Tiểu Khiết","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Xiao Qi Qing Rang","枭起青壤","Cinta Di Tanah Giok","효기청양: 터키옥 땅의 사랑","터키옥 땅의 사랑","Love on the Turquoise Land"]', 1784690324140);
