INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dat-xanh-sinh-cu', 'Đất Xanh Sinh Cú', 'Love On The Turquoise Land', 'đất xanh sinh cú love on the turquoise land địch lệ nhiệt ba trần tinh húc trương lệ đổng sướng trương diệc trì tô hâm nhan trác linh lương tụng tinh triệu hân phan mỹ diệp điền tiểu khiết xiao qi qing rang 枭起青壤 cinta di tanah giok 효기청양: 터키옥 땅의 사랑 터키옥 땅의 사랑 love on the turquoise land', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-vo-chuc-thuc-ra-cung-chang-can-ky-nang-gi-ca', 'Anh Hùng Vô Chức: Thực Ra Cũng Chẳng Cần Kỹ Năng Gì Cả?!', 'Hero Without A Class: Who Even Needs Skills?', 'https://phimimg.com/upload/vod/20250925-1/98dc95448a0c5b3b92851ff6922b6cd7.jpg', 'https://phimimg.com/upload/vod/20250925-1/444f7e3619acaa6afc51e0e0bee94081.jpg', '<p>Trong thế giới nơi nữ thần ban cho mỗi người một chức nghiệp và kỹ năng định đoạt cả đời, Arel – con trai của Kiếm Công Chúa và Đại Pháp Sư – lại không nhận được gì. Không có chức nghiệp, không có kỹ năng, Arel buộc phải dựa vào ý chí, nghị lực và tài năng thiên bẩm của mình để vươn tới vinh quang. Anh trở thành một kiểu anh hùng mới – anh hùng vô chức nghiệp.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 243, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kensho Ono","avatar":""},{"name":"Saori Hayami","avatar":""},{"name":"Sumire Uesaka","avatar":""},{"name":"Rumi Okubo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["无职英雄 ～技能什么的毫无用处～","Mushoku no Eiyuu: Betsu ni Skill Nanka Iranakatta n da ga","無職の英雄 別にスキルなんか要らなかったんだが","Mushoku no Eiyuu","Hero Without a Class: Who Even Needs Skills?!"]', 1784690324140);
