INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('anh-hung-vo-chuc-thuc-ra-cung-chang-can-ky-nang-gi-ca', 'Anh Hùng Vô Chức: Thực Ra Cũng Chẳng Cần Kỹ Năng Gì Cả?!', 'Hero Without A Class: Who Even Needs Skills?', 'anh hùng vô chức: thực ra cũng chẳng cần kỹ năng gì cả?! hero without a class: who even needs skills? kensho ono saori hayami sumire uesaka rumi okubo 无职英雄 ～技能什么的毫无用处～ mushoku no eiyuu: betsu ni skill nanka iranakatta n da ga 無職の英雄 別にスキルなんか要らなかったんだが mushoku no eiyuu hero without a class: who even needs skills?!', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ai-o-trong-guong', 'Ai Ở Trong Gương', 'Mystique In The Mirror', 'https://phimimg.com/upload/vod/20251026-1/f98ef094d5eb5e2f6630dac18dca82dc.jpg', 'https://phimimg.com/upload/vod/20251026-1/1c57e8aff66827392d54a44822a29ea6.jpg', '<p>Alan luôn cố gắng tìm hiểu rốt cuộc quá khứ và hiện tại của mình là ai. Mỗi lần soi gương, anh đều thấy hình bóng của một ông lão xuất hiện. Cho đến một ngày, anh gặp Win, một chàng trai trẻ dường như ở căn phòng bên cạnh trong bệnh viện tâm thần nơi Alan đang điều trị. Ngay từ lần đầu gặp mặt, Win đã thích Alan.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Sedthawut Anusit","avatar":""},{"name":"Jeerapat Pimanprom","avatar":""},{"name":"Buntawit Tragulpanich","avatar":""},{"name":"Nat Sakdatorn","avatar":""},{"name":"Danai Charuchinta","avatar":""},{"name":"Teachapat Pinrat","avatar":""},{"name":"Sahatchai Chumrum","avatar":""},{"name":"Kamonrat Pruethong","avatar":""},{"name":"Rudklao Amratisha","avatar":""},{"name":"Zijie Zong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mirror Reflection","ใครในกระจก"]', 1784690324140);
