INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-thuyet-thanh-thach-tran', 'Truyền Thuyết Thanh Thạch Trấn', 'Legend Of Qingshi Town', 'https://phimimg.com/upload/vod/20251211-1/d4b4aedf5447ff719b70f22d031d6053.jpg', 'https://phimimg.com/upload/vod/20251211-1/3f20c8089e037bba5c7981669455db77.jpg', '<p>Vì Thanh Lan, con gái mình, liên tục phát tác chứng bệnh kỳ quái và không ngừng lặp lại những câu đồng dao rùng rợn, thầy phong thủy Hào Ca (do Tào Vệ Vũ thủ vai) cùng công nhân bến tàu A Khôn và phóng viên Đại Vĩ đã lên đường tới trấn Thanh Thạch để điều tra. Tại thị trấn nhỏ có bố cục phong thủy tinh vi nhưng bầu không khí đầy quỷ dị này, họ không chỉ tìm ra số phận của Hồng Liên, chị gái của Thanh Lan, mà còn vén màn một bí mật kinh thiên động địa ẩn giấu nơi đây…</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cao Vinh Vũ","avatar":""},{"name":"Lý Bỉnh","avatar":""},{"name":"Hồ Di Nhiêu","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["青石镇传说"]', 1784690324140);
