INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bo-bien-mau-phan-2', 'Bờ Biển Máu (Phần 2)', 'Blood Coast (Season 2)', 'bờ biển máu (phần 2) blood coast (season 2) tewfik jallab jeanne goursaud nicolas duvauchelle olivier barthelemy lani sogoyou idir azougli samir boitard moussa maaskri florence thomassin diouc koma bilal ben osmane adel fellous 血红海岸 pax massilia marseille-freden blood coast', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-duoi-vuot-quyen', 'Kẻ Dưới Vượt Quyền', 'The Palace Gambit', 'https://phimimg.com/upload/vod/20251130-1/528f1d8de637310ab7a9333df5c49f66.jpg', 'https://phimimg.com/upload/vod/20251130-1/ddd139a160aa5434834380cbd8f9d849.jpg', '<p>Hai tỷ muội cùng bị đưa vào cung. Tỷ tỷ dung mạo khuynh quốc khuynh thành, muội muội lanh lợi khéo léo. Vốn chỉ muốn sống yên ổn qua ngày, nhưng hết lần này đến lần khác, hai người lại phải đối mặt với những âm mưu chí mạng, bị dồn ép đến đường cùng tuyệt lộ. Hai tỷ muội hợp sức, kề vai chiến đấu, và chỉ trong vài tháng ngắn ngủi đã giành được trái tim của đế vương. Thế nhưng đúng lúc vinh sủng đạt đến tột đỉnh, tỷ tỷ đang mang long thai lại bất ngờ chết thảm. Chỉ sau một đêm, ân sủng hóa thành hư vô. Từ đó, muội muội Lục Cửu Ninh ôm mối thù trong lòng, lấy thân phận cung nữ mà đơn độc thách thức cả hậu cung. Nàng khéo léo xoay chuyển giữa các phi tần, đối mặt với long uy của hoàng đế, từng bước bày ra ván cờ báo thù. Trận chiến của nàng không vì sủng ái, chỉ để đòi lại món nợ máu!</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trịnh Tưu Hoằng","avatar":""},{"name":"Trương Uyển Oánh","avatar":""},{"name":"Thẩm Chi Dịch","avatar":""},{"name":"Đặng Siêu Nguyên","avatar":""},{"name":"Triệu Khởi Nguyệt","avatar":""},{"name":"La Dư Điềm","avatar":""},{"name":"Chu Vân Long","avatar":""},{"name":"Dương Tiếu","avatar":""},{"name":"Hầu Mộng Dao","avatar":""},{"name":"Lãnh Luyến Nhu","avatar":""},{"name":"Lý Hân Vũ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["九宁扶上","以下犯上"]', 1784690324140);
