INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-doc-mieng', 'Gia Đình Độc Miệng', 'Sarcastic Family', 'https://phimimg.com/upload/vod/20251130-1/61d3e06a9a8cde7ec31c8371e9bf5879.jpg', 'https://phimimg.com/upload/vod/20251130-1/1d34165f204ccfb7416ef1a4bc710aa9.jpg', '<p>Thái Hiểu Oanh và Lý Lị Lê là hai mẹ con đến từ chòm sao Tiên Nữ xa xôi. Người Tiên Nữ vốn là một chủng tộc không có cảm xúc; dù đã gắn bó với nhau suốt cả ngàn năm trời, hai mẹ con vẫn xung khắc và mâu thuẫn không dứt.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Tuyết Cầm","avatar":""},{"name":"Mạnh Hạc Đường","avatar":""},{"name":"Thái Minh","avatar":""},{"name":"Dương Hạo Vũ","avatar":""},{"name":"Lý Tông Hằng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["毒舌家庭"]', 1784690324140);
