INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-sao-dai-kiep-an', 'Vận Sao Đại Kiếp Án', 'The Sixth Robber', 'https://phimimg.com/upload/vod/20251207-1/df39c80f389f9588ae96951c3f293bf4.jpg', 'https://phimimg.com/upload/vod/20251207-1/8b9861849c65b2f55082af388cc1a88c.jpg', '<p>Sau 7 năm, thành phố Trấn Hải lại một lần nữa xảy ra một vụ cướp xe chở tiền. Đội trưởng cảnh sát hình sự Khương Tử Đào nhanh chóng khoanh vùng được nghi phạm là tên cướp khét tiếng Võ Thắng Lợi, vừa mãn hạn tù.&nbsp; Trong quá trình điều tra, kẻ chủ mưu đứng sau vụ cướp là Tiểu Bảo cũng bị đưa ra ánh sáng. Cuộc đối đầu giữa thiện và ác của ba người—một cảnh sát và hai tên cướp—từ đó được triển khai.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngô Việt","avatar":""},{"name":"Bao Bối Nhĩ","avatar":""},{"name":"Ngô Vân Long","avatar":""},{"name":"Viên Tiêu","avatar":""},{"name":"An Trí Giới","avatar":""},{"name":"Lôi Mục","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Armorded","运钞大劫案"]', 1784690324140);
