INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('uoc-gi-anh-ta-bi-set-danh', 'Ước Gì Anh Ta Bị Sét Đánh', 'I Wish He''d Been Struck', 'https://phimimg.com/upload/vod/20251210-1/85829acea8f97d7016cf8730f1d65993.jpg', 'https://phimimg.com/upload/vod/20251210-1/a1cd893847f14b4dcc5be82d0096105b.jpg', '<p>Ông chồng đào hoa bỗng… bị sét đánh rồi đổi tính đổi nết? Park Hyun Ji vì thói trăng hoa và âm mưu của người chồng tưởng như soái ca tình trường ấy mà rơi vào cảnh hiểm nguy. Để thoát khỏi vòng vây âm mưu của chồng, mẹ chồng và cả cô bồ nhí, Hyun Ji bắt tay với luật sư Choi Joo Sung, người từng làm việc với cha cô để cùng nhau lập kế hoạch trả thù.</p>', 'Hoàn Tất (51/51)', 51, 'series', 'completed', 30, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phim Ngắn","slug":"phim-ngan","id":"4f02d28224c0747511790d57fbb63a62"}]', '[]', 1784690324140);
