INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-la-thu-cua-yeon', 'Những Lá Thư Của Yeon', 'Your Letter', 'https://phimimg.com/upload/vod/20251209-1/c9590a38c43b0f0e3ada0ccd0f2dd897.jpg', 'https://phimimg.com/upload/vod/20251209-1/483c649618008810f1d25feb8f1eac40.jpg', '<p>Giữa tháng ngày trung học u tối, khi Sori phải chịu đựng sự cô lập và bạo lực học đường, cô bất ngờ tìm thấy lá thư bí ẩn từ Yeon để lại trong ngăn bàn. Hành trình tìm kiếm những lá thư bắt đầu, mỗi lá thư mỗi dòng chữ dịu dàng không chỉ sưởi ấm trái tim đang tổn thương, mà còn dẫn lối Sori đến một tình bạn chân thành, một ký ức trong trẻo và cả sự can đảm để đối diện với chính mình.</p>', 'Full', 1, 'single', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"Lee Soo-hyun","avatar":""},{"name":"Kim Min-ju","avatar":""},{"name":"Min Seung-woo","avatar":""},{"name":"Nam Doh-hyeong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Yeon-ui Pyeonji","Sənin Məktubun","Your Letter","연의 편지"]', 1784690324140);
