INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-phu-uu-ai', 'Nhân Phù Ưu Ái', 'Adrift In Love', 'https://phimimg.com/upload/vod/20251121-1/e00e730da3eac27f665dc536f155f74f.jpg', 'https://phimimg.com/upload/vod/20251121-1/5d4aa7e96a5f5ca0f3797ec83d011f16.jpg', '<p>Chu Hiểu Kỳ và doanh nhân giàu có Chiêm Đổng —người vừa mất đi người thân yêu nhất—là một cặp tình nhân. Tuy nhiên, trong một buổi tư vấn tâm lý, cô đã gặp bác sĩ Cố Hậu Trạch. Mặc dù đang trong một mối quan hệ ổn định, Cố Hậu Trạch đã khơi dậy những khao khát chôn sâu trong cô.Cùng lúc đó, Phan Tâm Đồng, người có số phận khác biệt hoàn toàn, liên tục gặp những cú sốc trong cuộc sống và gần như suy sụp. Cô bất ngờ gặp được Tân Nghị Phu – một người đàn ông đẹp trai, giàu có và hài hước. Mối tình kỳ diệu này khiến cô lần nữa nhen nhóm hy vọng vào cuộc đời.Hai mối quan hệ đầy vướng mắc này đan xen nhau, tạo nên một hành trình tình ái xoay quanh chủ đề &quot;Lựa Chọn&quot;.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 18, 2025, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Tiêu Vũ Vi","avatar":""},{"name":"Tống Vân Hoa","avatar":""},{"name":"Giản Mạn Thư","avatar":""},{"name":"Dương Hựu Ninh","avatar":""},{"name":"Phạm Thiếu Huân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["人浮於愛"]', 1784690324140);
