INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-troi-treo-giua-bau-troi', 'Mặt Trời Treo Giữa Bầu Trời', 'The Sun Rises On Us All', 'https://phimimg.com/upload/vod/20251208-1/2fc37e9ba6a7344bad4646e302216b9f.jpg', 'https://phimimg.com/upload/vod/20251208-1/28f7e9bd1b95bda7f34c0c986a45b48b.jpg', '<p>Mặt Trời Treo Giữa Bầu Trời kể về cuộc tái ngộ sau bảy năm xa cách giữa Mỹ Vân (Tân Chỉ Lôi) và mối tình đầu Bảo Thụ (Trương Tụng Văn). Lần gặp gỡ này diễn ra trong bối cảnh éo le: Mỹ Vân đang mang thai, còn Bảo Thụ vừa mãn hạn tù và mang trong mình căn bệnh ung thư. Từ đó, phim khơi dậy những xung đột, khát vọng tha thứ và sự mong manh của tình yêu. Ngoài ra, tác phẩm cũng phác họa bức tranh đô thị Trung Quốc đương đại, nơi con người dễ trở nên lạc lõng giữa đám đông hối hả, còn những mối quan hệ tưởng chừng bền chặt cũng có thể tan vỡ và để lại khoảng trống khó lấp đầy.</p>', 'Full', 1, 'single', 'completed', 13, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xin Zhilei","avatar":""},{"name":"Zhang Songwen","avatar":""},{"name":"William Feng","avatar":""},{"name":"Xue Yuanyuan","avatar":""},{"name":"Qiao Linkai","avatar":""},{"name":"Yi Xinyun","avatar":""},{"name":"Ye Peishi","avatar":""},{"name":"Shan Baozhong","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ri Gua Zhong Tian","일괘중천","The Sun Rises on Us All","日掛中天"]', 1784690324140);
