INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mat-troi-treo-giua-bau-troi', 'Mặt Trời Treo Giữa Bầu Trời', 'The Sun Rises On Us All', 'mặt trời treo giữa bầu trời the sun rises on us all xin zhilei zhang songwen william feng xue yuanyuan qiao linkai yi xinyun ye peishi shan baozhong ri gua zhong tian 일괘중천 the sun rises on us all 日掛中天', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('son-ha-cham', 'Sơn Hà Chẩm', 'Fight For Love', 'https://phimimg.com/upload/vod/20251031-1/1a406739694459675a62c8fb48f631c8.jpg', 'https://phimimg.com/upload/vod/20251031-1/f4e47ece885b4c1caea891e56e0a7ef5.jpg', '<p>Cha của Sở Du tử trận nơi sa trường, huynh trưởng bị trọng thương đã tiết lộ với cô rằng vụ việc này không hề đơn giản, cô lập tức thề sẽ điều tra chân tướng rõ ràng. Nhà họ Vệ thất bại thảm hại trong một trận chiến, chỉ còn duy nhất con trai út Vệ Uẩn sống sót. Sở Du gả vào nhà họ Vệ, tiến hành điều tra dưới thân phận góa phụ của huynh trưởng đã khuất. Ban đầu Vệ Uẩn còn cảnh giác, nhưng sau khoảng thời gian tiếp xúc đã dần cảm động trước Sở Du. Tình cảm nảy nở giữa hai người, thân phận &quot;em chồng-chị dâu&quot; ngụy tạo lại trở thành trở ngại. Trải qua bao thử thách sống còn, họ cùng đồng lòng chống ngoại địch, điều tra kỹ càng sự thật và chung tay bảo vệ giang sơn.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 10, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tống Thiến","avatar":""},{"name":"Đinh Vũ Hề","avatar":""},{"name":"Phó Tân Bác","avatar":""},{"name":"Trần Kiều Ân","avatar":""},{"name":"Lương Tuyết Phong","avatar":""},{"name":"Tào Tuấn","avatar":""},{"name":"Chu Khiết Quỳnh","avatar":""},{"name":"Châu Đại Vi","avatar":""},{"name":"Đinh Gia Văn","avatar":""},{"name":"Lý Hoan","avatar":""},{"name":"Hoàng Nhật Oánh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["山河枕","ภูผาอิงนที","Fight for Love"]', 1784690324140);
