INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('son-ha-cham', 'Sơn Hà Chẩm', 'Fight For Love', 'sơn hà chẩm fight for love tống thiến đinh vũ hề phó tân bác trần kiều ân lương tuyết phong tào tuấn chu khiết quỳnh châu đại vi đinh gia văn lý hoan hoàng nhật oánh 山河枕 ภูผาอิงนที fight for love', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-trong-mo-cua-ong-kim', 'Cuộc Sống Trong Mơ Của Ông Kim', 'The Dream Life Of Mr. Kim', 'https://phimimg.com/upload/vod/20251026-1/9517134fd5b31de053da66201f3e7d53.jpg', 'https://phimimg.com/upload/vod/20251026-1/043471199080589b7f41288758a36b14.jpg', '<p>Sau khi làm tròn vai trò quản lý doanh nghiệp, người đàn ông trung niên nọ bắt đầu hành trình tự khám phá sau biến cố bất ngờ – học lại những điều mang cho ông niềm vui thực sự.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ryu Seung-ryong","avatar":""},{"name":"Myung Se-bin","avatar":""},{"name":"Cha Kang-yoon","avatar":""},{"name":"Jung Eun-chae","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Dream Life of Mr. Kim","金部长的梦想人生","Kim úr tökéletes élete","서울 자가에 대기업 다니는 김부장 이야기","حياة كيم المثالية","The Story of Manager Kim, Who Works for a Large Company in Seoul","서울 자가에 대기업 다니는 김 부장 이야기"]', 1784690324140);
