INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-dong-can-khon-phan-6', 'Vũ Động Càn Khôn (Phần 6)', 'Martial Universe (Season 6)', 'https://phimimg.com/upload/vod/20251124-1/12c011a621041829de5b5c595fa11af8.jpg', 'https://phimimg.com/upload/vod/20251124-1/746df843815c8fac0f62604a54097394.jpg', '<p>Vũ Động Càn Khôn là câu chuyện nói về cuộc đời của chàng thanh niên trẻ Lâm Động, từ ngày người cha của mình đại bại bởi kẻ thù, anh đã lên quyết tâm một ngày nào đó mình sẽ phải trở thành cao thủ đệ nhất võ lâm, để xứng danh thiên hạ.

Và rồi điều đó ngày càng tới gần khi mà ông trời có mắt đã không phụ người có lòng, mang đến cho anh những may mắn, Lâm Động khi đó đã gặp được kỳ ngộ, anh nhặt được một viên đá kỳ lạ, mang một nguồn sức mạnh bí ẩn, mà công dụng của nó nếu lọt ra ngoài thì chắc chắn sẽ khiến thế gian điên cuồng, vì những gì mà viên đá này sẽ mang đến, rốt cuộc viên đá đó có tác dụng gì? Và xuất xứ từ đâu và khiến võ lâm điên cuồng vì nó như thế?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Muqing Ke","avatar":""},{"name":"KIYO","avatar":""},{"name":"Shujun Lv","avatar":""},{"name":"Guo Hongbo","avatar":""},{"name":"Du Qingqing","avatar":""},{"name":"Liu Shisi","avatar":""},{"name":"Wan Suwan","avatar":""},{"name":"Yang Ou","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["武动乾坤动画版","Wu Dong Qian Kun","Wu Dong Qian Kun (Donghua)","武動乾坤","Martial Universe","Earth-Shattering Martial Arts","Martial Movement Upheaval","武动乾坤"]', 1784690324140);
