INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-thao-tung', 'Trò Chơi Thao Túng', 'The Manipulated', 'https://phimimg.com/upload/vod/20251106-1/bce75c5c5f518693cd1905f8bb92fcf4.jpg', 'https://phimimg.com/upload/vod/20251106-1/f3e2f2a3e1ccb10144eb3242121e1076.jpg', '<p>Tae Joong là một người đàn ông bình thường, đang sống cuộc đời yên ổn nhưng tất cả bỗng đảo lộn khi anh bị kết án tù oan với tội danh nghiêm trọng. Ở trong tù, anh phát hiện ra mọi thứ đều đã bị sắp đặt bởi Yo Han – kẻ giật dây phía sau. Vì vậy khi được trả tự do, Tae Joong bắt đầu con đường báo thù, trả lại công lý cho bản thân và đối mặt với kẻ đã thao túng cuộc đời anh.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 15, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ji Chang-wook","avatar":""},{"name":"Doh Kyung-soo","avatar":""},{"name":"Lee Kwang-soo","avatar":""},{"name":"Jo Yoon-soo","avatar":""},{"name":"Yang Dong-geun","avatar":""},{"name":"Pyo Ye-jin","avatar":""},{"name":"Kim Jong-soo","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["碎片都市","조각도시","المظلوم","The Manipulated"]', 1784690324140);
