INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-bao-to-2025', 'Gia Đình Bão Tố', 'Typhoon Family', 'https://phimimg.com/upload/vod/20251012-1/a9db72672fdad74eb490d763bd92ecfa.jpg', 'https://phimimg.com/upload/vod/20251012-1/d4699ed181d717215a974193527143e4.jpg', '<p>Một vị sếp mới thừa kế công việc kinh doanh của bố. Một kế toán viên tham vọng mơ ước thành công. Cùng nhau, họ học hỏi tinh thần kinh doanh và trưởng thành giữa khủng hoảng.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Jun-ho","avatar":""},{"name":"Kim Min-ha","avatar":""},{"name":"Kim Ji-young","avatar":""},{"name":"Kim Min-seok","avatar":""},{"name":"Moo Jin-sung","avatar":""},{"name":"Kim Yeong-ok","avatar":""},{"name":"Jin Sun-kyu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Typhoon Boss","台风商社","飓风商社","Typhoon Family","Typhoon Company","태풍상사"]', 1784690324140);
