INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trang-om-canh-nhan-ve-tay', 'Trăng Ôm Cánh Nhạn Về Tây', 'The Cross-Dressed Union', 'https://phimimg.com/upload/vod/20251201-1/7908631475292fb59b7b0a156da5a2c0.jpg', 'https://phimimg.com/upload/vod/20251201-1/3991437b69485709397bf92fb91945a8.jpg', '<p>Do bị Tiên đế chèn ép, giới võ tướng trong triều suy yếu, căn cơ triều đình lung lay, tân đế Yến Lâm phải đối đầu với thù trong giặc ngoài. Nam Thần Tiểu, con trai danh tướng đương triều buộc phải giả làm phận gái để tránh họa. Yến Lâm ra chỉ ban hôn cho Nam Thần Tiểu với Nhuế Dũ - nữ tử cải nam trang để vào triều làm quan - nhằm bảo vệ hai người họ và tính toán thế cục sau này. Trong tình thế nguy hiểm, cả hai bôn ba khắp nơi, cùng nhau vượt qua bao phen sinh tử. Về sau, họ tiết lộ bí mật về thân phận cho nhau, tình cảm giữa đôi bên dần nảy nở. Cuối cùng, hai người họ đã cùng nhau giúp Yến Lâm xoay vần thế cục, kiến tạo nên một thời kỳ thái bình thịnh trị.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Dã","avatar":""},{"name":"Đàm Hiểu Phàm","avatar":""},{"name":"Đại Giai Lị","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["天下第一良配","指夫为妻","月拢雁西归"]', 1784690324140);
