INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-ngon-tay-dieu-ky', 'Năm Ngón Tay Diệu Kỳ', 'Spirit Fingers', 'https://phimimg.com/upload/vod/20251031-1/abf4a712eac0070444ddb247b8680365.jpg', 'https://phimimg.com/upload/vod/20251031-1/fd8fba19e7d4e995dcc2885e43eadc5e.jpg', '<p>Song Woo Yeon (Park Ji Hu), một nữ sinh trung học nhút nhát và sống khép kín, không rõ mục đích sống cũng như khó thể hiện cảm xúc. Cuộc đời cô thay đổi khi được mời làm người mẫu cho câu lạc bộ vẽ “Spirit Fingers”, nơi cô gặp những con người chân thành và cởi mở. Nhờ sự khích lệ của phó chủ tịch Nam Geu Rin, Woo Yeon gia nhập câu lạc bộ. Tại đây, cô gặp Nam Ki Jeong (Jo Joon Young thủ vai) – em trai Geu Rin, một người mẫu có ngoại hình nổi bật nhưng bối rối về giá trị bản thân. Gặp Woo Yeon, Ki Jeong bắt đầu nuôi dưỡng những giấc mơ và cảm xúc mới mẻ về tình yêu.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 11, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Ji-hu","avatar":""},{"name":"Cho Jun-young","avatar":""},{"name":"Choi Bo-min","avatar":""},{"name":"Park You-na","avatar":""},{"name":"Kwon So-hyun","avatar":""},{"name":"Kim Seul-gi","avatar":""},{"name":"Lee Jin-hyuk","avatar":""},{"name":"Lim Cheol-soo","avatar":""},{"name":"No Min-woo","avatar":""},{"name":"Cha Woo-min","avatar":""},{"name":"Kang Hye-won","avatar":""},{"name":"Gi Eun-you","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Dedos Espirituais","Seupirit Pinggeoseu","Пальцы духа","أصابع الروح","스피릿 