INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-vuong-lenh-phi-khanh-mac-thuoc', 'Long Vương Lệnh: Phi Khanh Mạc Thuộc', 'Dragon King''s Decree', 'https://phimimg.com/upload/vod/20251121-1/711d97faa720e3c6f71b11517833909a.jpg', 'https://phimimg.com/upload/vod/20251121-1/d81cba206c7e635dd0a79ca13461b2b5.jpg', '<p>Phượng Chỉ Lâu là một thứ nữ phải chịu nhiều khinh miệt, nhưng cô không hề khuất phục, luôn mơ ước được sát cánh chiến đấu cùng Long tộc.Ban đầu, Long tộc Thái tử Sở Mặc Thương cần kết duyên với Thánh nữ để cùng chiến đấu với Ma tộc. Tuy nhiên, chàng thà một mình chống lại Ma tộc chứ không muốn liên kết đại sự thiên hạ với một cuộc hôn nhân.Hai cá thể ngược dòng số phận này đã định mệnh gặp nhau. Họ không chỉ phá vỡ những quan niệm cũ kỹ, cùng nhau vượt qua mọi chông gai, mà còn trở thành phiên bản tốt hơn của chính mình, và cuối cùng, xoay chuyển càn khôn.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Mộc Thần","avatar":""},{"name":"Diệp Thịnh Gia","avatar":""},{"name":"Quản Lặc","avatar":""},{"name":"Hướng Tĩnh Di","avatar":""},{"name":"Lý Bính Trần","avatar":""},{"name":"La Vũ Thiên","avatar":""},{"name":"Đông Thiệu Huy","avatar":""},{"name":"Quách Nghệ Khả","avatar":""},{"name":"Dương Lâm","avatar":""},{"name":"Bôi Chính Chính","avatar":""},{"name":"Tuệ Khải","avatar":""},{"name":"Vương Lâm","avatar":""},{"name":"Trương Tử Hàn","avatar":""},{"name":"Đỗ Vũ Minh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387