INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('long-vuong-lenh-phi-khanh-mac-thuoc', 'Long Vương Lệnh: Phi Khanh Mạc Thuộc', 'Dragon King''s Decree', 'long vương lệnh: phi khanh mạc thuộc dragon king''s decree lý mộc thần diệp thịnh gia quản lặc hướng tĩnh di lý bính trần la vũ thiên đông thiệu huy quách nghệ khả dương lâm bôi chính chính tuệ khải vương lâm trương tử hàn đỗ vũ minh 龙王令：妃卿莫属 long wang ling ​龙王令之妃卿莫属 long wang ling zhi fei qing mo shu 용왕령 龍王令：妃卿莫屬 dragon king''s decree 龙王令之妃卿莫属', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-sao-anh-ay-van-doc-than', 'Tại Sao Anh Ấy Vẫn Độc Thân?', 'Why Is He Still Single?', 'https://phimimg.com/upload/vod/20251117-1/429109655d103a5fde478ff2f013363e.jpg', 'https://phimimg.com/upload/vod/20251117-1/230df1cc364d3991553c166def95549c.jpg', '<p>Đây là câu chuyện về một người đàn ông có vẻ ngoài kỳ quặc, nhưng thực chất lại rất tốt bụng, và cuối cùng đã cả thế giới bao dung đón nhận. Thông qua việc khắc họa một người đàn ông có những thói quen vô cùng kỳ quặc, bộ phim không chỉ tạo ra vô số tình huống dở khóc dở cười, mà còn mang đến những suy ngẫm về mối quan hệ giữa con người và thế giới xung quanh. Một người đàn ông yêu đời đã đến tuổi 40 nhưng lại tuyên bố &quot;không kết hôn&quot;. Rốt cuộc anh ta là nam thần được vạn người theo đuổi, hay là một người cứng nhắc khiến phụ nữ phải tránh xa? Là anh ta &quot;không muốn kết hôn&quot; hay là &quot;không thể kết hôn&quot;? Khi cuối cùng ông chú độc thân kỳ quặc này cũng gặp được nữ thần trong mộng của mình, anh ta sẽ phải làm sao để chinh phục được người đẹp?Thức ăn có muôn vàn hương vị, hợp khẩu vị mới là đáng quý! Không có người đàn ông nào không kết hôn, chỉ là họ chưa tìm được đúng người phù hợp với mình mà thôi.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hoắc Kiến Hoa","avatar":""},{"name":"Chu Châu","avatar":""},{"name":"Phí Khải Minh","avatar":""},{"name":"Lý Khải Hinh","avatar":""},{"name":"Phạm Tĩnh Y","avatar":""},{"name":"Trương Dao","avatar":""},{"name":"Lưu Giai","avatar":""},{"name":"Đổng Tư Di","avatar":""},{"name":"Lý Dịch Tường","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["不能结婚的男人","中国版不能结婚的男人","他為甚麼依然單身","結婚できない男","他为什么依然单身"]', 1784690324140);
