INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tai-sao-anh-ay-van-doc-than', 'Tại Sao Anh Ấy Vẫn Độc Thân?', 'Why Is He Still Single?', 'tại sao anh ấy vẫn độc thân? why is he still single? hoắc kiến hoa chu châu phí khải minh lý khải hinh phạm tĩnh y trương dao lưu giai đổng tư di lý dịch tường 不能结婚的男人 中国版不能结婚的男人 他為甚麼依然單身 結婚できない男 他为什么依然单身', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cho-quay-ray-ta-phi-thang', 'Chớ Quấy Rầy Ta Phi Thăng', 'Flying Up Without Disturb', 'https://phimimg.com/upload/vod/20251116-1/387f76daf27f3664b8af826e7937204a.jpg', 'https://phimimg.com/upload/vod/20251116-1/e18043a65afb0bedaa8090b3eea308df.jpg', '<p>Khổng Hầu, một công chúa vong quốc bị lạnh nhạt ở phàm trần, vô tình có cơ duyên bước vào thế giới tu tiên và ngay lập tức mở chế độ được tất cả mọi người cưng chiều.Từ sư phụ, sư huynh cho đến các môn phái lân cận, cả giới tu tiên đều hết lòng yêu thương cô. Để tự mình rèn luyện tâm chí, Khổng Hầu chủ động bước ra khỏi vùng an toàn, xin xuống núi rèn luyện.Tại đây, cô tình cờ gặp được Hoàn Tông , một chàng trai bệnh tật yếu đuối. Hai người cùng nhau nâng cấp, đánh quái và xông pha khắp giới tu tiên.Nào ngờ, Hoàn Tông chính là &quot;đại thần&quot; (tác giả nổi tiếng) viết nên bộ thoại bản tu tiên mà cô luôn say mê, đồng thời cũng là thiên tài lừng danh trong giới tu tiên. Khổng Hầu đã thành công &quot;bắt cóc&quot; được tác giả đại thần về môn phái làm rể.Hai người cũng từ những lần lịch luyện mà vượt qua tâm ma, đột phá tu vi, song song trở thành bậc tông sư của một thế hệ.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 11, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Hồng Nghị","avatar":""},{"name":"Lục Đình Ngọc","avatar":""},{"name":"Hứa Gia Kỳ","avatar":""},{"name":"Trương Chí Hạo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["승천중, 방해 사절","勿扰飞升"]', 1784690324140);
