INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tuyet-dau-mua-o-hang-fraggle-rock', 'Tuyết Đầu Mùa Ở Hang Fraggle Rock', 'The First Snow Of Fraggle Rock', 'tuyết đầu mùa ở hang fraggle rock the first snow of fraggle rock john tartaglia karen prell donna kimball jordan lockhart dave goelz frank meschkuleit lilli cooper lele pons kanja chen aymee garcia kira hall ingrid hansen dan garza ben durocher andy hayward ali eisner kevin clash أول تساقط للثلوج في فراجل روك ha llegado la nieve a fraggle rock : 2025 the first snow of fraggle rock', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuy-dao-khach-2025', 'Túy Đao Khách', 'The Killer Of Swordsmen', 'https://phimimg.com/upload/vod/20251207-1/e5623b61eed40ed65b62e31e8fbd22e3.jpg', 'https://phimimg.com/upload/vod/20251207-1/201de28479bba0f7417d644aa5271fec.jpg', '<p>Bộ phim kể về Hàn Nguyệt Nhận, một &quot;Đao Khách Lạnh Lùng&quot; vang danh giang hồ. Vì một ân huệ cơm nước, anh trở lại trấn Bào Hãn.Lúc này, trấn Bào Hãn đang phải chịu đựng sự chèn ép và bắt nạt của cường quyền ác bá. Hàn Nguyệt Nhận quyết định ra tay giúp đỡ, nhưng lại kinh hoàng nhận ra sự yếu đuối và nỗi sợ hãi trong lòng người còn đáng sợ hơn bạo lực rất nhiều...Mối quan hệ phức tạp giữa anh và Mạn Đà La day dứt như lưỡi đao độc cứa vào tim, giằng xé giữa rung động và sự phản bội.Khi cường quyền vô đạo đức, kẻ yếu không có công lý, nhất định sẽ có một thanh đao, chém tan cái thời đại quỳ gối.</p>', 'Full', 1, 'single', 'completed', 32, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Bính Viễn","avatar":""},{"name":"Tôn Nghệ Nhiên","avatar":""},{"name":"Lam Mạn Dư","avatar":""},{"name":"Triệu Tĩnh Thụy","avatar":""},{"name":"Lý Trường Hồng","avatar":""},{"name":"Long Vũ","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Zui Dao Ke","취도객","醉刀客"]', 1784690324140);
