INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-gian-toi', 'Vô Gian Tội', 'Blood Brothers', 'https://phimimg.com/upload/vod/20251207-1/bbfdbb14f7283a967bfec6452e03dbee.jpg', 'https://phimimg.com/upload/vod/20251207-1/dea8c95c7056fa03ee42dae5ca9df851.jpg', '<p>Bộ phim kể về câu chuyện của cảnh sát Chu Hiếu. Vì truy lùng vụ án đầu độc và vứt xác 721, bạn gái anh, người đang mắc chứng trầm cảm, đã tự sát. Sự kiện này khiến Chu Hiếu mất đi niềm tin vào nghề cảnh sát và rơi vào bế tắc. Tuy nhiên, anh vẫn kiên cường tiến về phía trước, cuối cùng vượt qua sự hoang mang, điều tra rõ sự thật đằng sau cái chết của người yêu, từ đó tự chữa lành và tự cứu rỗi bản thân, tìm lại được niềm tin vào công việc cảnh sát.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tôn Kiện Khi","avatar":""},{"name":"Thái Tâm","avatar":""},{"name":"Giang Xuyên","avatar":""},{"name":"Nghi Mỹ Thị","avatar":""},{"name":"Cố Du","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Wu Jian Zui","Unforgivable Sin","无间罪"]', 1784690324140);
