INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vi-mieu-nhan-sinh-tai-sinh-thanh-meo', 'Vì Miêu Nhân Sinh (Tái Sinh Thành Mèo)', 'Reborn As A Cat', 'https://phimimg.com/upload/vod/20251207-1/6e8e0bffe6a9007f1abad7b513844e1e.jpg', 'https://phimimg.com/upload/vod/20251207-1/6c57a0a1f3db87fdb7b2c11bbadc9a98.jpg', '<p>Kỷ Miêu Miêu, một cô gái trẻ mới bắt đầu sự nghiệp, bị bạn bè phản bội và phải gánh trên vai một núi nợ nần. Trong lúc chạy trốn khỏi những kẻ đòi nợ thuê tàn nhẫn, cô vô tình ngã từ trên cao xuống. Giữa lúc cận kề cái chết, một nhân vật bí ẩn đã biến cô thành một con mèo. Số phận trớ trêu, cô được nhận nuôi - không ai khác chính là ông chủ của mình, Lục Thừa Trạch. Từ đó, cuộc sống kỳ lạ và kỳ diệu kéo dài 100 ngày của cô... như một con mèo bắt đầu.</p>', 'Tập 5', 16, 'hoathinh', 'ongoing', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ajie","avatar":""},{"name":"Li Shimeng","avatar":""},{"name":"Qiu Qiu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wei Miao Rensheng","Wei Miao Ren Sheng","Just for a Meowment","For the Meow Life","为喵人生"]', 1784690324141);
