INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nuoi-day-mot-chien-binh-cengjing-you-yongshi', 'Nuôi Dạy Một Chiến Binh (Cengjing You Yongshi)', 'So You''re Raising A Warrior', 'https://phimimg.com/upload/vod/20251123-1/7ea71f54e27a34b909ab99361642347f.jpg', 'https://phimimg.com/upload/vod/20251123-1/5907bc6afc94bc64f55c6c69da12fd4e.jpg', '<p>Con rồng Al dễ thương trái ngược hẳn, kẻ giết vua đầu tiên của thế giới quỷ, sở hữu thành tích chiến đấu xuất sắc nhưng sẵn sàng chết và khao khát một cuộc sống hưu trí hạnh phúc, tình cờ gặp pháp sư loài người xảo quyệt Le Fei, và vô tình trở thành một người cha siêu phàm nuôi dạy con trai Le Fei là Dino. Liệu Dino sẽ là một đứa trẻ bình thường và hạnh phúc, hay anh sẽ dũng cảm cầm lấy Thánh Kiếm Chiến Binh và đối mặt với số phận của chính mình...</p>', 'Tập 7', 12, 'hoathinh', 'ongoing', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["曾经有勇士 / 용사가 있었는데요","Ceng Jing You Yong Shi","So You''re Raising a Warrior","曾经有勇士"]', 1784690324141);
