INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-gai-dai-trinh-tham', 'Bạn Gái Đại Trinh Thám', 'The Girlfriend Detective', 'https://phimimg.com/upload/vod/20251207-1/a1d76870a8e9e4c285e45d129aba569c.jpg', 'https://phimimg.com/upload/vod/20251207-1/cd74ea2a140dcb8e7065c55b85096d1d.jpg', '<p>Bộ phim là câu chuyện về một vụ án trinh thám do phụ nữ điều tra diễn ra trong thời kỳ Dân Quốc.Phùng Thiên Thiên, bạn gái của Trương Thám Trưởng, là một thám tử du học từ nước ngoài trở về. Sau khi về nước, hai người hợp tác cùng nhau bắt đầu hành trình tìm kiếm hung thủ thật sự.Vụ án mở màn bằng cái chết của trùm bất động sản Vương Cường khi ông bị sát hại trước gương. Câu chuyện diễn ra với nhiều tình tiết móc nối, và ẩn sau những điều kỳ lạ luôn là những âm mưu không thể tiết lộ. Phùng Thiên Thiên đã lần lượt bóc tách từng lớp bí ẩn để tìm ra sự thật cuối cùng.Cốt truyện lấy pháp luật làm trọng tâm, thể hiện tinh thần kiên trì không bỏ cuộc tìm kiếm chân lý của nữ thám tử trong thời đại đen tối đó!</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đổng Tân Vân","avatar":""},{"name":"Dương Thừa Hàn","avatar":""},{"name":"Viên Thiếu Yến","avatar":""},{"name":"Tào Ức","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["大侦探女友"]', 1784690324141);
