INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoc-dong-thoi-gian-ma-den', 'Ngược Dòng Thời Gian Mà Đến', 'Back For You', 'https://phimimg.com/upload/vod/20251120-1/359c08dc16fb4a58d4634468994ed7d9.jpg', 'https://phimimg.com/upload/vod/20251120-1/1ba7e38107ffec1fec55ffa07281b6ba.jpg', '<p>Giữa đêm khuya mệt mỏi chốn thị thành, Dư Tinh Thần tình cờ gặp lại Tô Nhược – người con gái anh từng thầm thương thuở thiếu thời – nhưng ngay sau đó lại bàng hoàng hay tin cô đã qua đời. Một người đàn ông áo đen thần bí xuất hiện, kéo anh vào vòng xoáy thời gian và đưa anh trở về thời cấp ba, khi Tô Nhược vừa tròn mười tám tuổi. Một lần nữa sống lại quãng đời mười lăm năm, anh lần theo những dấu vết ẩn giấu trong khung cảnh quen thuộc. Liệu mối tình thầm lặng năm xưa có thể hé mở bí ẩn cái chết? Cuộc gặp gỡ này là sự bù đắp của số mệnh, hay chỉ là manh mối dẫn anh đến sự thật cuối cùng?</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hứa Trác Luân","avatar":""},{"name":"Từ Viên Viên","avatar":""},{"name":"Đổng Nhan","avatar":""},{"name":"Lư Mễ Lạc","avatar":""},{"name":"Hà Thiện Khải","avatar":""},{"name":"Hoàng Ân Như","avatar":""},{"name":"Vương Trọng Vĩ","avatar":""},{"name":"Cao Hồng Khải","avatar":""},{"name":"Lý Tư Nam","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ni Shi Er Lai De Ni","Reversing Time","逆时而来的你"]', 1784690324141);
