INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoc-dong-thoi-gian-ma-den', 'Ngược Dòng Thời Gian Mà Đến', 'Back For You', 'ngược dòng thời gian mà đến back for you hứa trác luân từ viên viên đổng nhan lư mễ lạc hà thiện khải hoàng ân như vương trọng vĩ cao hồng khải lý tư nam ni shi er lai de ni reversing time 逆时而来的你', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cach-mang-tinh-yeu-40', 'Cách Mạng Tình Yêu 4.0', 'The 4th Love Revolution (LOVE.exe)', 'https://phimimg.com/upload/vod/20251114-1/458228de8fefa269fbb1e4b899003a27.jpg', 'https://phimimg.com/upload/vod/20251114-1/856059aa749a5292fee1ed83657bdd3e.jpg', '<p>Sau khi trường đại học sáp nhập hai khoa người mẫu và kỹ thuật máy tính, chàng người mẫu cuốn hút Min-hak và cô lập trình viên cầu toàn Yeon-san – hai con người hoàn toàn đối lập – lại bất ngờ phải lòng nhau. Khi sàn catwalk gặp màn hình máy tính, khi sự quyến rũ chạm trán với sự chính xác — định mệnh đã viết nên một câu chuyện tình không ai ngờ tới.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Yo-han","avatar":""},{"name":"Hwang Bo-reum-byeol","avatar":""},{"name":"Kwon Young-eun","avatar":""},{"name":"Heo Jeong-do","avatar":""},{"name":"Lim Sung-kyun","avatar":""},{"name":"Kang Sin","avatar":""},{"name":"Woo Ji-hyeon","avatar":""},{"name":"Lee Ji-hye","avatar":""},{"name":"Min-seo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["第四次爱情革命","Je-4-Cha Sa-lang Hyeog-myeong","The 4th Love Revolution","제4차 사랑혁명"]', 1784690324141);
