INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rock-and-soul', 'Rock And Soul', 'Rock And Soul', 'https://phimimg.com/upload/vod/20251102-1/2cb74a653d908697387a9cf5489f896c.jpg', 'https://phimimg.com/upload/vod/20251102-1/a3e85f376dffbd3e1568698ede4377ff.jpg', '<p>Sau thảm kịch kinh hoàng, hai nhạc sĩ gặp một thiên sứ tử thần đầy bí ẩn. Vị thiên sứ trao cho họ một cơ hội có thể thay đổi số phận.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Luke Ishikawa Plowden","avatar":""},{"name":"Setthapong Eosuk","avatar":""},{"name":"Kunjiranut Intarasin","avatar":""},{"name":"Pharunrit Sarutsitphon","avatar":""},{"name":"Tiradet Warapapong","avatar":""},{"name":"Noodee Bunyaporn","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["จังหวะร็อกปาฏิหาริย์รัก"]', 1784690324141);
