INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-tot-co-thang-duoc-tinh-yeu', 'Lòng Tốt Có Thắng Được Tình Yêu?', 'Club Friday Theory of Love: Merit Wins the Soul', 'https://phimimg.com/upload/vod/20251122-1/14785b1c1d3f7bc28ee59fdb1edb7dad.jpg', 'https://phimimg.com/upload/vod/20251122-1/ce3499b9f5e634cbbab52689428b1e29.jpg', '<p>Một nữ tác giả web thành công trong sự nghiệp nhưng thất bại trong tình yêu, gặp lại rung động khi quen một người mẫu xinh đẹp. Dù bị cảnh báo về quá khứ tai tiếng của cô gái ấy, cô vẫn tin rằng tình yêu và lòng tốt có thể thay đổi mọi thứ. Nhưng khi mối quan hệ dần rạn nứt và sự thật đau lòng bị phơi bày, cô nhận ra — đôi khi, lòng tốt không đủ để giữ lấy tình yêu.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Sawanya Paisarnpayak","avatar":""},{"name":"Chutima Teepanat","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Club Friday Theory of Love: Merit Wins the Soul","Khwam Di Chana Chai","ความดีชนะใจ"]', 1784690324141);
