INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-boc-2025', 'Vỏ Bọc', 'The Sparrow''s Gambit', 'https://phimimg.com/upload/vod/20251130-1/000a24c7855f08a87d7a4d8389da1ca1.jpg', 'https://phimimg.com/upload/vod/20251130-1/5a93b6a9b1c1ee522d9962a5709c152d.jpg', '<p>Nữ sát thủ tuyệt sắc Thanh Miêu sát phạt quyết đoán bị chính cha nuôi của mình bán rẻ. Trong khoảnh khắc cận kề cái chết, cô phát hiện hung thủ sát hại cả gia tộc lại chính là kẻ bên cạnh mình. Để báo thù cho người thân, Thanh Miêu ẩn nhẫn suốt năm năm, hóa thân thành Liễu Như Mộng, trở thành ca cơ vang danh một thời, từng bước bắt đầu thực hiện kế hoạch báo thù...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Chu Cận Đồng","avatar":""},{"name":"Kim Bằng Bác","avatar":""},{"name":"Kim Thu","avatar":""},{"name":"Vương Tử Quyền","avatar":""},{"name":"Vương Tuấn Bằng","avatar":""},{"name":"Lưu Gia Bằng","avatar":""},{"name":"Đoạn Tiêu Phẫn","avatar":""},{"name":"Tôn Tiểu Mỹ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Gu Yuan","孤鸢"]', 1784690324141);
