INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thiet-ke-tinh-yeu', 'Thiết Kế Tình Yêu', 'Love Design (Uncut Ver.)', 'https://phimimg.com/upload/vod/20251003-1/3e50264027782a6043b5d55f5ffffa5c.jpg', 'https://phimimg.com/upload/vod/20251003-1/fc546e38fb4e2dc27b2e78a8caa8502d.jpg', '<p>Aokbab là một kiến trúc sư trẻ, cô khao khát trả thù Mind – đàn chị từng đánh cắp công trình của cô. Để thách thức Mind, cô đã mở một công ty riêng. Nhưng con đường cô phải đối mặt phía trước lại tràn đầy thử thách: cạnh tranh khốc liệt, sự phản bội và cả mối tình bất ngờ với Rin - một kiến trúc sư tài năng. Bị áp lực bủa vây, Aokbab buộc phải lựa chọn giữa mối hận thù ăn sâu và tình yêu mới này. Liệu Aokbab có thể vượt qua mọi chướng ngại, khẳng định bản thân và thành công chinh phục trái tim của Rin?</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Supassara Thanachart","avatar":""},{"name":"Ramida Jiranorraphat","avatar":""},{"name":"Matira Tantiprasut","avatar":""},{"name":"Paramee Luengnaruemitchai","avatar":""},{"name":"Torfan Taweema","avatar":""},{"name":"Nalinthip Phoemphattharasakun","avatar":""},{"name":"Ratchapong Anomakiti","avatar":""},{"name":"Elisha Triwiwatkul","avatar":""},{"name":"Sarut Nawapraditkul","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["契约心房","设计爱情","รับ(รัก)ออกแบบ","REAL ESTATE AGENCY","รับ (รัก) ออกแบบ"]', 1784690324141);
