INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('matt-rife-mo-boc-hai-kich-doi-thoai-voi-khan-gia', 'Matt Rife: Mở Bọc Hài Kịch Đối Thoại Với Khán Giả', 'Matt Rife: Unwrapped - A Christmas Crowd Work Special', 'https://phimimg.com/upload/vod/20251206-1/adb5fd70d4dd6f5396f80f344c5a0a43.jpg', 'https://phimimg.com/upload/vod/20251206-1/8d8bf9e121497ef5fd089c9bd35f9cb6.jpg', '<p>Từ những món quà thất bại cho đến những truyền thống gia đình đi chệch hướng, nghệ sĩ hài Matt Rife biến một khán giả không thể đoán trước thành một chương trình hài độc thoại về ngày lễ không kịch bản.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Matt Rife","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Matt Rife: Unwrapped - A Christmas Crowd Work Special"]', 1784690324141);
