INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-dai-chi-thuong', 'Lôi Đài Chi Thượng', 'On The Ring', 'https://phimimg.com/upload/vod/20251206-1/713db3ed85858e91a756e2ba418a92ed.jpg', 'https://phimimg.com/upload/vod/20251206-1/cd9e0f47953fc3f5b51dd66e9f10c8da.jpg', '<p>Bao Dũng từng là nhà vô địch quyền anh, giờ đây trở thành một giáo viên chủ nhiệm trường cấp ba không tuân theo quy tắc thông thường. Để hỗ trợ học sinh nghèo, anh trở lại sàn đấu quyền anh, hợp tác với Cao Hồng Đức, người điều hành một phòng tập quyền anh đang nợ nần chồng chất, để chuẩn bị cho giải đấu có thưởng. Đồng thời, thiếu niên cứng đầu Dương Phàm tình cờ phát hiện ra bí mật của Bao Dũng. Cuộc chiến đầy nhiệt huyết, trách nhiệm và trưởng thành này chỉ mới bắt đầu…</p>', 'Full', 1, 'single', 'completed', 40, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Anh Long","avatar":""},{"name":"Vương Thần Húc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"}]', '["擂台之上"]', 1784690324141);
