INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('david-letterman-vi-khach-tiep-theo-la-adam-sandler', 'David Letterman Vị Khách Tiếp Theo Là Adam Sandler', 'My Next Guest With David Letterman And Adam Sandler', 'https://phimimg.com/upload/vod/20251206-1/3f640419f1d976c3035942a247a6280e.jpg', 'https://phimimg.com/upload/vod/20251206-1/4f3d860a8b8c3993e65891add8b33ce9.jpg', '<p>Adam Sandler mời Dave vào hậu trường trong chuyến lưu diễn hài của mình, sau đó họ ngồi lại tại NYU để trò chuyện về stand-up, những vai diễn nổi tiếng và cây đàn Stratocaster mà anh ấy yêu thích.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"David Letterman","avatar":""},{"name":"Adam Sandler","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["My Next Guest Needs No Introduction with David Letterman and Adam Sandler","My Next Guest with David Letterman and Adam Sandler"]', 1784690324141);
