INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-van-sat-nhan', 'Phỏng Vấn Sát Nhân', 'Murderer Report', 'https://phimimg.com/upload/vod/20251031-1/d7c02873c8a95e699e5393af3fd4f9c2.jpg', 'https://phimimg.com/upload/vod/20251031-1/651e2b41fa94dfffce9d32c9fca8f495.jpg', '<p>Baek Sun-ju (CHO Yeo-jeong) – một nữ phóng viên đang tuyệt vọng tìm kiếm một tin độc quyền, nhận được lời đề nghị phỏng vấn rùng rợn từ bác sĩ tâm thần Lee Young-hoon (JUNG Sung-il), người tự nhận mình là một kẻ giết người hàng loạt và cảnh báo rằng một vụ án mạng khác sắp xảy ra. Sau nhiều do dự, Sun-ju bắt đầu buổi phỏng vấn với tên sát nhân trong một phòng khách sạn. Trong cuộc trò chuyện căng thẳng đó, Young-hoon tiết lộ một sự thật gây sốc: những vụ giết người của hắn bắt đầu như một cách để “chữa trị” cho bệnh nhân của mình. Khi cuộc phỏng vấn tiếp diễn, Sun-ju cảm nhận có điều gì đó vô cùng sai trái và cố gắng bỏ chạy. Nhưng hắn lại tung ra một “quả bom” khác: nếu cô dừng buổi phỏng vấn lại, sẽ có thêm một người chết. “Nếu cuộc phỏng vấn này dừng lại, sẽ có người mất mạng.” Liệu cuộc chạm trán định mệnh này sẽ kết thúc như thế nào?</p>', 'Full', 1, 'single', 'completed', 11, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 1, '[{"name":"Cho Yeo-jeong","avatar":""},{"name":"Jung Sung-il","avatar":""},{"name":"Kim Tae-han","avatar":""},{"name":"Choi Su-im","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Murder Report","谋杀报告","گزارش قتل","살인자 리포트"]', 1784690324141);
