INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('y-mong-lenh-2025', 'Ỷ Mộng Lệnh', 'Gorgeous Dream', 'https://phimimg.com/upload/vod/20251124-1/160a0e8515523b33c94ad4ec474e5f8a.jpg', 'https://phimimg.com/upload/vod/20251124-1/f55266e55afd001445958ae624d67c75.jpg', '<p>Bị phản bội và hủy hoại, nàng trở lại với gương mặt mới và kế hoạch trả thù tuyệt đối. Khi cha con họ Lưu rơi vào bẫy, hiểm nguy cũng siết chặt quanh nàng, cho đến khi kẻ bí ẩn trong bóng tối bước ra thay đổi tất cả.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tăng Hựu Trân","avatar":""},{"name":"Thôi Vũ Hâm","avatar":""},{"name":"Vương Tinh Khải","avatar":""},{"name":"Vu Lôi","avatar":""},{"name":"Uông Lô Vân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["毒妃撩人：禁欲冷王宠上身","绮梦令"]', 1784690324141);
