INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-cua-trai-tim', 'Trò Chơi Của Trái Tim', 'Hearts In Play', 'https://phimimg.com/upload/vod/20251205-1/2823530896ca5cac43db94f75dbec52e.jpg', 'https://phimimg.com/upload/vod/20251205-1/ab0373a3d04cdc388bd721e3a12282a8.jpg', '<p>Nữ sinh trung học sáng sủa, hoạt bát Hạ Phồn Tinh có biệt danh là &quot;Bạn Học Kho Báu&quot; vì cô có khả năng an ủi và chữa lành bất kỳ trái tim tổn thương nào.Thịnh Dương, một học sinh chuyển trường, từng là quán quân &quot;Giải Vô Địch Bóng Bàn Thiếu Niên Toàn Quốc&quot; nhưng buộc phải từ bỏ bóng bàn cho đến khi anh gặp được cô.Để giúp Thịnh Dương thoát khỏi bóng tối, Hạ Phồn Tinh đã dùng mọi cách—cả cứng rắn lẫn mềm mỏng—gây ra hàng loạt tình huống dở khóc dở cười.Trong quá trình tiếp xúc, Thịnh Dương dần phát hiện ra rằng &quot;Bạn Học Kho Báu&quot; này, người luôn tỏ ra lạc quan, thực chất lại che giấu một nỗi đau không thể nói với ai. Cô thích dùng vẻ ngoài rạng rỡ để bao bọc vết thương lòng; rõ ràng là một người I (hướng nội) nhưng lại giả vờ làm người E (hướng ngoại).Sau khi hiểu được điều đó, Thịnh Dương quyết định: &quot;Hãy để cô ấy tiếp tục làm mặt trời của người khác, còn anh sẽ là mặt trời của riêng cô.&quot; Một câu chuyện ngọt ngào, ấm áp về sự chữa lành lẫn nhau từ đó bắt đầu...</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Kim Tử Toàn","avatar":""},{"name":"Tiêu Kiệt Văn","avatar":""},{"name":"Chu Thể Thuận","avatar":""},{"name":"Đái Mạc Dã","avatar":""},{"name":"Điền Kinh Phàm","avatar":""},{"name":"Diệp Vịnh Tú","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ta Zai Zhang Xin Hu Xiao Er Guo","盛夏弧光","它在掌心，呼啸而过"]', 1784690324141);
