INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cha-duong-2025', 'Cha Dượng', 'Balahibong Pusa', 'https://phimimg.com/upload/vod/20251204-1/0ee4fb11cef9c2e23a3c98e44471ed35.jpg', 'https://phimimg.com/upload/vod/20251204-1/dad926dccb9777d85cd9691c99a21607.jpg', '<p>Một cô gái trẻ phát hiện ra nỗi ám ảnh đen tối của cha dượng, dẫn cô vào một mạng lưới quyến rũ và bí mật khiến cô phải đối đầu với mẹ mình trong một cuộc xung đột giữa ham muốn và phản bội. Một cô gái trẻ bắt đầu khám phá nỗi ám ảnh nguy hiểm của cha dượng, kéo cô vào một mạng lưới bí mật quyến rũ khiến cô phải đối đầu với chính mẹ mình và rơi vào một cuộc chiến căng thẳng giữa ham muốn và phản bội trong phiên bản làm lại của bộ phim kinh điển năm 2001 này.</p>', 'Full', 1, 'single', 'completed', 34, 2025, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Margaret Diaz","avatar":""},{"name":"Christine Bermas","avatar":""},{"name":"Itan Magnaye","avatar":""},{"name":"Mark Anthony Fernandez","avatar":""},{"name":"Yda Manzano","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"}]', '["猫女郎","Balahibong Pusa"]', 1784690324141);
