INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('buoc-duong-cung-2025', 'Bước Đường Cùng', 'No Other Choice', 'bước đường cùng no other choice lee byung-hun son ye-jin park hee-soon lee sung-min yeom hye-ran cha seung-won kim woo-seung choi so-yul kim hyeong-mook woo jeong-won yoo yeon-seok yoon ga-i oh dal-su lee suk-hyeong oh kwang-rok lee yong-nyeo kim hae-sook im tae-poong eojjeolsugaeopda aucun autre choix لا خيار آخر 无可奈何 งานนี้..ฆ่าเอา 徵人啟弒 選擇有罪 o método de exclusão sem outra opção sem outra alternativa a única saída sem outra escolha başqa seçim yoxdur nėra kitos išeities しあわせな選択 eojjeolsuga eobsda non c''è altra scelta 어쩔수가없다', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tram-dam-tu-than', 'Trăm Dặm Tử Thần', 'The Long Walk', 'https://phimimg.com/upload/vod/20251023-1/e6a5d4af9a6a2eacf2f49a248c112410.jpg', 'https://phimimg.com/upload/vod/20251023-1/e1aa7154c5182404e00a296c2b920cfe.jpg', '<p>Mỗi năm, năm mươi thiếu niên nam được chọn tham gia một sự kiện được cả đất nước biết đến với cái tên “Trăm Dặm Tử Thần.” Trong nhóm năm nay có Ray Garraty, 16 tuổi. Cậu biết rõ luật chơi: nếu đi dưới tốc độ quy định, vấp ngã hay ngồi xuống sẽ bị cảnh cáo. Sau ba lần cảnh cáo… bạn sẽ nhận “vé” của mình. Và điều xảy ra sau đó là lời nhắc nhở rùng rợn rằng trong cuộc thi này — chỉ có một người chiến thắng: người duy nhất còn sống.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Cooper Hoffman","avatar":""},{"name":"David Jonsson","avatar":""},{"name":"Garrett Wareing","avatar":""},{"name":"Tut Nyuot","avatar":""},{"name":"Charlie Plummer","avatar":""},{"name":"Ben Wang","avatar":""},{"name":"Roman Griffin Davis","avatar":""},{"name":"Jordan Gonzalez","avatar":""},{"name":"Joshua Odjick","avatar":""},{"name":"Josh Hamilton","avatar":""},{"name":"Judy Greer","avatar":""},{"name":"Mark Hamill","avatar":""},{"name":"Noah de Mel","avatar":""},{"name":"Daymon Wrightly","avatar":""},{"name":"Jack Giffin","avatar":""},{"name":"Thamela Mpumlwana","avatar":""},{"name":"Keenan Lehmann","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Camina o muere","La larga marcha"