INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-lung-danh-conan-28-du-anh-cua-doc-nhan', 'Thám Tử Lừng Danh Conan 28: Dư Ảnh Của Độc Nhãn', 'Detective Conan: One-Eyed Flashback', 'https://phimimg.com/upload/vod/20250827-1/eddefbf4813488f89a6f0c766f69f82f.jpg', 'https://phimimg.com/upload/vod/20250827-1/aabb76a70d8afd21ddf2be37381c7587.jpg', '<p>Trên những ngọn núi tuyết của Nagano, một vụ án bí ẩn đã đưa Conan và các thám tử quay trở lại quá khứ. Thanh tra Yamato Kansuke - người đã bị thương nặng trong một trận tuyết lở nhiều năm trước - bất ngờ phải đối mặt với những ký ức đau thương của mình trong khi điều tra một vụ tấn công tại Đài quan sát Nobeyama. Cùng lúc đó, Mori Kogoro nhận được một cuộc gọi từ một đồng nghiệp cũ, tiết lộ mối liên hệ đáng ngờ giữa anh ta và vụ án đã bị lãng quên từ lâu. Sự xuất hiện của Morofushi Takaaki, cùng với những nhân vật chủ chốt như Amuro Tooru, Kazami và cảnh sát Tokyo, càng làm phức tạp thêm cuộc điều tra. Khi quá khứ và hiện tại đan xen, một bí ẩn rùng rợn dần dần được hé lộ - và ký ức của Kansuke nắm giữ chìa khóa cho mọi thứ.</p>', 'Full', 1, 'hoathinh', 'completed', 31, 2025, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Nhật Bản', 1, '[{"name":"Minami Takayama","avatar":""},{"name":"Kappei Yamaguchi","avatar":""},{"name":"Wakana Yamazaki","avatar":""},{"name":"Rikiya Koyama","avatar":""},{"name":"Yuji Takada","avatar":""},{"name":"Ami Koshimizu","avatar":""},{"name":"Show Hayami","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Takayuki Yamada","avatar":""},{"name":"Mizuki Yamashita","avatar":""},{"name":"Yukimasa Kishino","avatar":""},{"name":"Takeshi Kusao","avatar":""},{"name":"Nobuo Tobita","avatar":""},{"name":"Chafurin","avatar":""},{"name":"Wataru Takagi","avatar":""},{"name":"Atsuko Yuya","avatar":""},{"name":"Kenichi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Thám Tử Lừng Danh Conan: Hồi Ức Của Độc Nhãn","Meitantei Conan: Sekigan no Flashback","Meitantei Conan Movie 28","Detective Conan Movie 28: One-Eyed Flashback","Case Closed Movie 28","Meitantei Conan Movie 28: Sekigan no Flashback","名探偵コナン 隻眼の残像(せきがんのフラッシュバック)","獨眼的殘像","名偵探柯南 獨眼的殘像","名探偵コナン 隻眼のフラッシュバック","Детектив Конан Фильм 28","名侦探柯南剧场版28：独眼的残像","Thám Tử Lừng Danh Conan 28","Thám Tử Lừng Danh Conan Điện Ảnh 28","Thám Tử Lừng Danh Conan Movie 28","名偵探柯南 M28 獨眼的殘像","Detectiu Conan: One-eyed flashback","名探偵コナン 隻眼の残像"]', 1784690324141);
