INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chiec-hop-den-2025', 'Chiếc Hộp Đen', 'The Black Box', 'https://phimimg.com/upload/vod/20251114-1/33f1af2aec99c8286383a7048dcf0159.jpg', 'https://phimimg.com/upload/vod/20251114-1/f36d3cd102f2df0727579f1c5d63555b.jpg', '<p>Bản chất con người giống như hộp đen trên máy bay. Dù va đập, cháy bỏng hay rơi vào vực sâu, vẻ ngoài vẫn nguyên vẹn. Chỉ có bên trong, nơi cất giấu mọi bí mật, là thứ không ai có thể chạm tới. Mười ngàn năm trước, Kỳ Kỳ suýt chết vì một mũi tên, một người bí ẩn có thân thể phát sáng đã đến bên cô, dùng chiếc hộp đen có khả năng trao đổi thời gian với người khác để kéo dài tuổi thọ, nhờ đó cô sống đến thời hiện đại...</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Mạc Vận Vân","avatar":""},{"name":"Lý Lập Nhân","avatar":""},{"name":"Phó Mạnh Bác","avatar":""},{"name":"Tạ Triển Vinh","avatar":""},{"name":"Hứa An Thực","avatar":""},{"name":"Hạ Thiếu Hạ","avatar":""},{"name":"Trương Hiên Nhụy","avatar":""},{"name":"Lục Hạ","avatar":""},{"name":"Khâu Tư Khâm","avatar":""},{"name":"Trịnh Nhân Thạc","avatar":""},{"name":"Giản Mạn Thư","avatar":""},{"name":"Hồng Quân Hạo","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["黑盒子：造物獄","黑盒子：星際救援","黑盒子：豬人","黑盒子：黑白盒子","The Black Box: Creation Hell","The Black Box: Space Journey","The Black Box: Pig Family","The Black Box: The White Box","黑盒子"]', 1784690324141);
