INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chiec-hop-den-2025', 'Chiếc Hộp Đen', 'The Black Box', 'chiếc hộp đen the black box mạc vận vân lý lập nhân phó mạnh bác tạ triển vinh hứa an thực hạ thiếu hạ trương hiên nhụy lục hạ khâu tư khâm trịnh nhân thạc giản mạn thư hồng quân hạo 黑盒子：造物獄 黑盒子：星際救援 黑盒子：豬人 黑盒子：黑白盒子 the black box: creation hell the black box: space journey the black box: pig family the black box: the white box 黑盒子', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-dung-luc-gap-dung-nguoi', 'Yêu Đúng Lúc Gặp Đúng Người', 'Love Is Always Online', 'https://phimimg.com/upload/vod/20251120-1/242a2218c5bee606ea6aad9bb1ba2911.jpg', 'https://phimimg.com/upload/vod/20251120-1/0142cf2e7d15d4834bfbd45fe433b05b.jpg', '<p>Doanh nhân điển trai Giang An Lan vì muốn tìm lại mối tình đầu Diêu Viễn mà âm thầm bước vào thế giới trò chơi điện tử, quyết liệt theo đuổi người trong lòng. Cuối cùng, hai người đã cùng nhau bước vào thế giới thật và nắm tay đi tiếp. Khi họ đang chuẩn bị cho lễ cưới, ân oán giữa hai gia đình bất ngờ dậy sóng, khiến tình cảm của họ gặp phải sóng gió. Vượt qua những hiểu lầm và thử thách bệnh tật, cuối cùng họ cũng gương vỡ lại lành, trọn vẹn bên nhau.</p>', 'Hoàn Tất (37/37)', 37, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hùng Tử Kỳ","avatar":""},{"name":"Thái Văn Tịnh","avatar":""},{"name":"Chu Tiển","avatar":""},{"name":"Tiền Hiểu Dĩnh","avatar":""},{"name":"Mã Chấn Hoàn","avatar":""},{"name":"Hàn Trung Vũ","avatar":""},{"name":"Kha Giai Yến","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["对的时间对的人"]', 1784690324141);
