INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('yeu-dung-luc-gap-dung-nguoi', 'Yêu Đúng Lúc Gặp Đúng Người', 'Love Is Always Online', 'yêu đúng lúc gặp đúng người love is always online hùng tử kỳ thái văn tịnh chu tiển tiền hiểu dĩnh mã chấn hoàn hàn trung vũ kha giai yến 对的时间对的人', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-bay', 'Nhà Bẫy', 'Trap House', 'https://phimimg.com/upload/vod/20251204-1/6e6d472bc687307004fc5a78736af831.jpg', 'https://phimimg.com/upload/vod/20251204-1/594e35b67185fda5a6df70892cfdcf2a.jpg', '<p>Một đặc vụ DEA chìm và cộng sự của anh ta bắt đầu cuộc rượt đuổi mèo vờn chuột với một nhóm trộm táo tợn và đáng ngạc nhiên – chính là những đứa con tuổi teen nổi loạn của họ, những kẻ đã bắt đầu cướp bóc từ một băng đảng ma túy nguy hiểm, sử dụng chiến thuật và thông tin tình báo tối mật của cha mẹ chúng để thực hiện điều đó.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Dave Bautista","avatar":""},{"name":"Bobby Cannavale","avatar":""},{"name":"Kate del Castillo","avatar":""},{"name":"Jack Champion","avatar":""},{"name":"Sophia Lillis","avatar":""},{"name":"Whitney Peak","avatar":""},{"name":"Tony Dalton","avatar":""},{"name":"Inde Navarrette","avatar":""},{"name":"Zaire Adams","avatar":""},{"name":"Blu del Barrio","avatar":""},{"name":"Zijah Graca","avatar":""},{"name":"Danny Vinson","avatar":""},{"name":"Sarah Melissa Barker","avatar":""},{"name":"Manny Rubio","avatar":""},{"name":"Ammie Masterson","avatar":""},{"name":"Alfredo Quiroz","avatar":""},{"name":"Kelsey","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Traphouse","کمینگاه","A Casa da Armadilha","Trap House"]', 1784690324141);
