INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kaiju-no8-nhiem-vu-trinh-sat', 'Kaiju No.8: Nhiệm Vụ Trinh Sát', 'Kaiju No. 8: Mission Recon', 'https://phimimg.com/upload/vod/20251124-1/869af69fe505721d64945334c0431b07.jpg', 'https://phimimg.com/upload/vod/20251124-1/6b93ca7df1454d421e06f8a8553075f2.jpg', '<p>Kaiju No.8: Nhiệm Vụ Trinh Sát là một phần ngoại truyện của bộ manga Kaiju No.8 (Kaijuu 8-gou). Câu chuyện tập trung vào Kafka Hibino, người có khả năng biến hình thành quái vật (Kaiju) và phải giữ bí mật về năng lực này khi gia nhập Lực lượng Phòng vệ Nhật Bản, một tổ chức chuyên tiêu diệt quái vật. Nhiệm vụ của anh là vừa chiến đấu với quái vật, vừa che giấu thân phận thực sự của mình.</p>', 'Full', 1, 'single', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 1, '[{"name":"Masaya Fukunishi","avatar":""},{"name":"Wataru Katoh","avatar":""},{"name":"Fairouz Ai","avatar":""},{"name":"Tessyo Genda","avatar":""},{"name":"Kengo Kawanishi","avatar":""},{"name":"Keisuke Komoto","avatar":""},{"name":"Kenta Miyake","avatar":""},{"name":"Sayaka Senbongi","avatar":""},{"name":"Asami Seto","avatar":""},{"name":"Yuuki Shin","avatar":""},{"name":"Shunsuke Takeuchi","avatar":""},{"name":"Hiroyuki Yoshino","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Kaijuu 8-gou Movie","Kaiju No.8 Compilation Movie","Kaijuu 8-gou Recap","『怪獣８号』第１期総集編／同時上映「保科の休日」","Kaiju No. Eight Season 1 Compilation / Hoshi