INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('kaiju-no8-nhiem-vu-trinh-sat', 'Kaiju No.8: Nhiệm Vụ Trinh Sát', 'Kaiju No. 8: Mission Recon', 'kaiju no.8: nhiệm vụ trinh sát kaiju no. 8: mission recon masaya fukunishi wataru katoh fairouz ai tessyo genda kengo kawanishi keisuke komoto kenta miyake sayaka senbongi asami seto yuuki shin shunsuke takeuchi hiroyuki yoshino kaijuu 8-gou movie kaiju no.8 compilation movie kaijuu 8-gou recap 『怪獣８号』第１期総集編／同時上映「保科の休日」 kaiju no. eight season 1 compilation / hoshina''s day off 怪獣８号　第１期総集編 ／「保科の休日」 kaiju no. 8: misión de reconocimiento kaiju no. 8: mission recon 怪獣８号 第1期総集編／同時上映「保科の休日」', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-duong-dai-nao', 'Võ Đường Đại Náo', 'Hit N Fun', 'https://phimimg.com/upload/vod/20251127-1/03dd96d570e714904f8888836d71f011.jpg', 'https://phimimg.com/upload/vod/20251127-1/67ceae186a8c09ae7345780f57217d4a.jpg', '<p>Chung Lỗi - nhà cựu vô địch Muay Thái hết thời đang đứng trên bờ vực phá sản vì phòng tập võ của anh ế ẩm quá mức. Khách hàng chủ yếu là các cô gái muốn giữ dáng để tìm bạn trai hoặc các công nhân lớn tuổi tìm chỗ ngủ trưa. Tuy vậy, cái nghèo không đeo bám lâu khi Chung Lỗi tìm được khách hàng tiềm năng tên Elsa - người phụ nữ bí ẩn giàu có nhất Hong Kong. Cô đăng ký võ đường của anh với quyết tâm tu luyện để xử lý &quot;tiểu tam&quot;. Từ đây dẫn đến hàng loạt tình huống dở khóc dở cười. Liệu trận đấu giữa hai nữ nhi chân yếu tay mềm kia sẽ có kết quả ra sao?</p>', 'Full', 1, 'single', 'completed', 22, 2025, 'Vietsub', 'FHD', 'Hồng Kông', 1, '[{"name":"Cổ Thiên Lạc","avatar":""},{"name":"Lương Vịnh Kỳ","avatar":""},{"name":"Vương Đan Ni","avatar":""},{"name":"Hồ Tử Đồng","avatar":""},{"name":"Chu Tú Na","avatar":""},{"name":"Trương Văn Kiệt","avatar":""},{"name":"Trần Tâm Văn","avatar":""},{"name":"Ngô Dận Long","avatar":""},{"name":"Dương Thi Si","avatar":""},{"name":"Kiều Tịnh Phu","avatar":""},{"name":"Vương Ỷ Tinh","avatar":""},{"name":"Vương Tụng Ân","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hit N Fun","临时决斗","臨時決鬥"]', 1784690324141);
