INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vo-duong-dai-nao', 'Võ Đường Đại Náo', 'Hit N Fun', 'võ đường đại náo hit n fun cổ thiên lạc lương vịnh kỳ vương đan ni hồ tử đồng chu tú na trương văn kiệt trần tâm văn ngô dận long dương thi si kiều tịnh phu vương ỷ tinh vương tụng ân hit n fun 临时决斗 臨時決鬥', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-sau-bua-tiec-2025', 'Bí Mật Sau Bữa Tiệc', 'Anniversary', 'https://phimimg.com/upload/vod/20251127-1/53f05e8f5632d54dfffaaed2faff9fd9.jpg', 'https://phimimg.com/upload/vod/20251127-1/0fa06f97bb6372362f53fe21925d1151.jpg', '<p>Một gia đình gắn bó khăng khít bất ngờ bị cuốn vào vòng xoáy của phong trào xã hội gây nhiều tranh cãi mang tên “Sự Thay Đổi”. Ellen và Paul (Diane Lane và Kyle Chandler) phải đối diện với biến cố khi Liz (Phoebe Dynevor) – cựu học trò của Ellen – bất ngờ trở lại và nảy sinh quan hệ tình cảm với con trai họ (Dylan O’Brien). Sự hiện diện của Liz trong gia đình Taylor nhanh chóng làm gia tăng căng thẳng và thử thách các mối quan hệ vốn mong manh. Khi vai trò của Liz trong “Sự Thay Đổi” ngày càng rõ rệt, những mâu thuẫn âm ỉ dần bùng phát, đe dọa phá vỡ sự gắn kết của gia đình, trong bối cảnh cả quốc gia đang chao đảo trước thời kỳ đầy bất ổn và lo âu.</p>', 'Full', 1, 'single', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Diane Lane","avatar":""},{"name":"Kyle Chandler","avatar":""},{"name":"Madeline Brewer","avatar":""},{"name":"Zoey Deutch","avatar":""},{"name":"Mckenna Grace","avatar":""},{"name":"Phoebe Dynevor","avatar":""},{"name":"Dylan O''Brien","avatar":""},{"name":"Daryl McCormack","avatar":""},{"name":"Rebecca O''Mara","avatar":""},{"name":"Flavia Watson","avatar":""},{"name":"Sky Yang","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["ระลึกวันลวง","The Change","Anniversary"]', 1784690324141);
