INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-ga-ngoc-o-kenya', 'Ba Gã Ngốc Ở Kenya', 'Three Idiots In Kenya', 'https://phimimg.com/upload/vod/20251127-1/a43240b106c118ccde62f6dc72b3030b.jpg', 'https://phimimg.com/upload/vod/20251127-1/23529de8eb28eef0a6b236419c2fae50.jpg', '<p>Trong series do nhà sản xuất series thực tế huyền thoại Na Yeong Seok sáng tạo, ba người bạn nổi tiếng đến Kenya – nơi mà mọi cuộc phiêu lưu đều đi kèm với thử thách hoặc trò chơi.</p>', 'Hoàn Tất (6/6)', 6, 'tvshows', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Su-geun","avatar":""},{"name":"Eun Ji-won","avatar":""},{"name":"Cho Kyu-hyun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["케냐 간 세끼"]', 1784690324141);
