INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bau-nghe-si-thoi-loan', 'Bau Nghệ Sĩ Thời Loạn', 'Bau, Artist At War', 'https://phimimg.com/upload/vod/20251203-1/a8900cc5e19b745496e99b9f64c9519e.jpg', 'https://phimimg.com/upload/vod/20251203-1/a7c3961af17fa39166f2feec4e28db4f.jpg', '<p>Giữa địa ngục trại tập trung, Joseph Bau dùng tài nghệ để sống sót và cứu người, và tìm thấy tình yêu. Nhiều năm sau, khi được gọi ra làm nhân chứng quan trọng trong phiên tòa xét xử tên sĩ quan Phát xít tàn bạo đã tra tấn anh và giết cha anh, Joseph buộc phải đối mặt với những ký ức sống động của Holocaust.</p>', 'Full', 1, 'single', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Emile Hirsch","avatar":""},{"name":"Inbar Lavi","avatar":""},{"name":"Yan Tual","avatar":""},{"name":"Adam Tsekhman","avatar":""},{"name":"Edward Foy","avatar":""},{"name":"Chris Cope","avatar":""},{"name":"Josh Blacker","avatar":""},{"name":"Josh Zuckerman","avatar":""},{"name":"Michael Benyaer","avatar":""},{"name":"Ian Rozylo","avatar":""},{"name":"Eugene Lipinski","avatar":""},{"name":"Tori Griffith","avatar":""},{"name":"Aias Dalman","avatar":""},{"name":"Pam Kearns","avatar":""},{"name":"Petar Gatsby","avatar":""},{"name":"Robert Leaf","avatar":""},{"name":"Craig Erickson","avatar":""},{"name":"Leslie Hopps","avatar":""},{"name":"Dalias","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["BAU","באו – האמן במלחמה","יוסף בא