INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-trung-2025', 'Song Trùng', 'Decalcomania', 'https://phimimg.com/upload/vod/20251104-1/1247aad551fb6a08bb01c4bd9fd321c2.jpg', 'https://phimimg.com/upload/vod/20251104-1/6dca64d80ea37834238e1aa55a5b2b97.jpg', '<p>Bộ phim là câu chuyện về hai người phụ nữ có ngoại hình giống hệt nhau nhưng lại sống hai cuộc đời hoàn toàn khác biệt. Nuengdiao Ananthikhun là chủ một hộp đêm ở Bangkok với quá khứ đen tối. Còn Lea Wu là một cô gái Singapore giàu có sống dưới sự bảo vệ của một ông trùm dược phẩm. Họ vô tình gặp nhau trong một tai nạn bí ẩn và linh hồn hoán đổi cho nhau. Một người phải bắt đầu học cách sinh tồn trong thế giới thượng lưu đầy mưu mô, người kia phải đối mặt sự nguy hiểm của thế giới ngầm mà cô chưa từng biết đến. Trong quá trình cả hai học cách thích nghi với cuộc sống mới, những bí mật được chôn giấu bấy lâu dần dần được hé lộ.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Mookda Narinrak","avatar":""},{"name":"Hussawee Pakrapongpisan","avatar":""},{"name":"Chartayodom Hiranyatithi","avatar":""},{"name":"Thaneth Warakulnukroh","avatar":""},{"name":"Cynthia Koh","avatar":""},{"name":"Chayanit Chansangavej","avatar":""},{"name":"Hong Huifang","avatar":""},{"name":"Pierre Png","avatar":""},{"name":"Amy Cheng","avatar":""},{"name":"Gladys Ng","avatar":""},{"name":"Regina Lim","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324141);
