INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-na-cua-vo', 'Mặt Nạ Của Vợ', 'Vengeful Wife', 'https://phimimg.com/upload/vod/20251117-1/65b55c7b89b9c2114065381ca0dbac17.jpg', 'https://phimimg.com/upload/vod/20251117-1/0c7a485742cac9e53a1a3fc2de1245c7.jpg', '<p>Diệp Đông ở rể nhà họ Lâm, đã đóng vai một người chồng hoàn hảo với âm mưu chiếm đoạt mọi thứ của gia đình họ Lâm. Người vợ là Lâm Hạ bị anh ta hãm hại đến mức mù lòa. Diệp Đông ngang nhiên ngoại tình với thư ký và sát hại cha vợ ngay trước mặt người vợ mù của mình; Tuy nhiên, khi đôi mắt của Lâm Hạ bất ngờ sáng trở lại do sự ngược đãi của mẹ Diệp Đông, cô đã nhìn thấu tất cả hận thù và tội ác. Cô như phượng hoàng tái sinh, trở lại để báo thù gã đàn ông cặn bã. Ác giả rồi sẽ gặp ác báo.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Thường Triết Khoan","avatar":""},{"name":"Lý Nghệ","avatar":""},{"name":"Tống Giai Âm","avatar":""},{"name":"Thôi Vĩnh Huyễn","avatar":""},{"name":"Lạt Đạt Hoa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["妻子的面具"]', 1784690324141);
