INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-can-phong-trong', 'Những Căn Phòng Trống', 'All The Empty Rooms', 'https://phimimg.com/upload/vod/20251202-1/1439ba918f74020b58cf7742dac1560c.jpg', 'https://phimimg.com/upload/vod/20251202-1/d23fb993983bce1bfbb2d65e018d847f.jpg', '<p>Trong bộ phim tài liệu ngắn cảm động này, một nhà báo và một nhiếp ảnh gia bắt đầu tưởng niệm những phòng ngủ bị bỏ lại của những đứa trẻ thiệt mạng trong vụ xả súng ở trường học.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Steve Hartman","avatar":""},{"name":"Meryl Hartman","avatar":""},{"name":"Bryan Muehlberger","avatar":""},{"name":"Gloria Cazares","avatar":""},{"name":"Javier Cazares","avatar":""},{"name":"Lou Bopp","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["All the Empty Rooms"]', 1784690324141);
