INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-lam-ngoai-su', 'Võ Lâm Ngoại Sử', 'Fated In The Martial World', 'https://phimimg.com/upload/vod/20251201-1/c528e38c0f1e855e0df4aa59fafa78b8.jpg', 'https://phimimg.com/upload/vod/20251201-1/980effbd09cac57d4e31898b7cf6772b.jpg', '<p>Giang hồ dậy sóng vì bí kíp Vô Địch Bảo Giám. Bạch Tĩnh, Cung chủ U Linh Cung, bị chính người chồng là Sài Ngọc Quan phản bội.Sài Ngọc Quan lợi dụng Bạch Tĩnh để trừ khử Cửu Châu Vương, rồi liên kết với Năm Đại Môn Phái vây quét U Linh Cung, khiến Bạch Tĩnh chết thảm.Cô bé Bạch Phi Phi khi còn nhỏ đã chứng kiến cái chết của mẹ, từ đó lập lời thề sẽ báo thù cha ruột cùng những kẻ thù liên quan.Mười năm sau, Bạch Phi Phi dùng bí kíp làm mồi nhử khuấy động giang hồ. Cô gặp gỡ Thẩm Lãng, đại hiệp được ủy thác bảo vệ bí kíp; Chu Thất Thất, thiên kim thủ phủ Trung Châu với lòng lương thiện; và Vương Liên Hoa, công tử Vân Mộng Sơn Trang với trí tuệ sâu sắc.Bốn người họ từng bước bị cuốn sâu vào vòng xoáy ân oán tình thù trên chốn giang hồ...</p>', 'Hoàn Tất (34/34)', 34, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Quan Thường","avatar":""},{"name":"Ngô Sùng Hiên","avatar":""},{"name":"Trần Phương Đồng","avatar":""},{"name":"Hoàng Tiêu","avatar":""},{"name":"Tôn Tử Tuấn","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wu Lin Wai Shi","武林外史"]', 1784690324141);
