INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trang-nguyen-phu-nhan-lai-gay-chuyen-roi', 'Trạng Nguyên Phu Nhân Lại Gây Chuyện Rồi', 'Top Scholar Your Wife''s At It Again', 'https://phimimg.com/upload/vod/20251201-1/0285906d9dc936885cb8fe3c706629cb.jpg', 'https://phimimg.com/upload/vod/20251201-1/176d894d79f30a5344345c16fb5d9caf.jpg', '<p>Vì muốn trả ơn bữa cơm ba năm trước, Tân khoa Trạng nguyên Tần Vũ đã quyết định cưới Trương Quỳnh – người phụ nữ đanh đá nổi tiếng khắp vùng. Nào ngờ, cuộc hôn nhân này lại vô tình mở ra một ván cờ sinh tử đan xen giữa những cuộc đấu đá trong gia tộc và sóng gió trên triều đình. Bề ngoài nhu mì yếu đuối nhưng thực chất Tần Vũ lại là một quân cờ bí mật của hoàng gia, gánh vác trọng trách điều tra vụ án tham ô tiền cứu trợ thiên tai. Trương Quỳnh với tính cách nóng nảy, mạnh mẽ và quả cảm, luôn phải đấu trí với đại bá đang âm mưu chiếm đoạt tài sản để bảo vệ muội muội. Hai phu thê họ đã cùng đồng tâm hiệp lực để mang lại hạnh phúc cho bá tính.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 29, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phim Ngắn","slug":"phim-ngan","id":"4f02d28224c0747511790d57fbb63a62"}]', '[]', 1784690324141);
