INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-anh-trinh-tham-trinh-tham-bong-dem', 'Ám Ảnh Trinh Thám (Trinh Thám Bóng Đêm)', 'Shadow Detective', 'https://phimimg.com/upload/vod/20251130-1/5ddb00aedd0e6ccbbbd804ad85c2843a.jpg', 'https://phimimg.com/upload/vod/20251130-1/6d2fc0e85954358ba74f4ab34f0de355.jpg', '<p>Đầu thập niên 1930, xảy ra một vụ cái chết bí ẩn trong ký túc xá nữ sinh đại học tại bến Thượng Hải. Trưởng phòng cảnh sát trung ương Quan Sầm nhờ đó quen biết cô nữ sinh yêu thích tiểu thuyết trinh thám Lục Dĩ Chân, và vụ việc này vô tình liên quan đến một vụ bắt cóc bé gái 17 năm trước. Hai năm sau, Lục Dĩ Chân tham gia kỳ tuyển chọn nữ cảnh sát đầu tiên tại Thượng Hải, còn Quan Sầm trở thành cấp trên trực tiếp của cô. Trong đồn cảnh sát nhiều vụ án phức tạp, hai người hợp tác điều tra lại vụ bắt cóc bé gái, từ từ xua tan màn sương mù và cơn ác mộng bao trùm trên đầu họ.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Tinh Việt","avatar":""},{"name":"Ngô Giai Di","avatar":""},{"name":"Thiệu Vĩ Đồng","avatar":""},{"name":"Trương Mộc Hy","avatar":""},{"name":"Mỹ Na","avatar":""},{"name":"Nhược Vĩ Hàng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["An Ying Zhen Tan","暗影侦探"]', 1784690324141);
