INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-tich-da-chet-hay-con-song-phan-2', 'Mất Tích Đã Chết Hay Còn Sống (Phần 2)', 'Missing: Dead Or Alive (Season 2)', 'https://phimimg.com/upload/vod/20251130-1/8bcf3cf201804fd3002768696eff9d07.jpg', 'https://phimimg.com/upload/vod/20251130-1/edc790490830aa0abcf0105410957b6c.jpg', '<p>Theo chân các sĩ quan của Sở Cảnh Sát Nam Carolina khi họ khẩn trương tìm kiếm nhiều cá nhân mất tích trong những hoàn cảnh đáng ngại.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Desapariciones Vivos o muertos","Savnet: Død eller levende?","Missing: Dead or Alive?"]', 1784690324141);
