INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mat-tich-da-chet-hay-con-song-phan-2', 'Mất Tích Đã Chết Hay Còn Sống (Phần 2)', 'Missing: Dead Or Alive (Season 2)', 'mất tích đã chết hay còn sống (phần 2) missing: dead or alive (season 2)  desapariciones vivos o muertos savnet: død eller levende? missing: dead or alive?', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-uc-ngo-sat', 'Ký Ức Ngộ Sát', 'Manslaughter Memory', 'https://phimimg.com/upload/vod/20251130-1/859a953f34d60e7af145b3287885e74f.jpg', 'https://phimimg.com/upload/vod/20251130-1/b28421063a65a187d5c3e5a2c0065328.jpg', '<p>Trong phim, hai nhân vật chính là Tô Nhuyễn và Hứa Chung Ôn luôn kề vai sát cánh, không rời bỏ nhau ngay cả trong lúc nguy nan. Họ kiên quyết giữ vững niềm tin, không bị những kẻ có ý đồ xấu xa uy hiếp, và cuối cùng đã khiến kẻ ác phải nhận sự trừng phạt thích đáng.Toàn bộ bộ phim thể hiện quyết tâm không ngại gian nan, hiểm nguy của hai nhân vật chính trong cuộc đấu tranh với các thế lực xấu xa.Bộ phim ca ngợi sự theo đuổi không ngừng nghỉ của họ đối với chân lý và tinh thần kiên định giữ vững chính nghĩa ngay cả khi đối mặt với nghịch cảnh. Cuối cùng, các nhân vật chính đã học được cách hòa giải với chính mình, gạt bỏ hận thù và dũng cảm bước tới một cuộc sống mới.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'ongoing', 14, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Đạt Nguyên","avatar":""},{"name":"Lạc Thư Kỳ","avatar":""},{"name":"Nguyên Toàn","avatar":""},{"name":"Nhâm Minh Minh","avatar":""},{"name":"Chung Dục Lâm","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["误杀记忆"]', 1784690324141);
