INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-tan-de-quoc-khoi-nguyen', 'Đại Tần Đế Quốc Khởi Nguyên', 'The Rise Of The Qin Empire', 'https://phimimg.com/upload/vod/20251130-1/52913b423be208c9b1cd9c814bb51102.jpg', 'https://phimimg.com/upload/vod/20251130-1/8df24296cfa4a5bb93c2ec35e41a717b.jpg', '<p>Khi Phụ vương tuẫn quốc và đất nước rơi vào cảnh bị tàn phá, Tần Văn Công Doanh Thạc đã lên ngôi trong lúc nguy nan!Việc tranh cãi về việc dời đô xé nát triều đình; anh em ruột thịt quay lưng, gươm tuốt trần và căng thẳng tột độ; những mối tình tuyệt vọng đan xen với mối thù nước nợ nhà.Ông đã ban hành luật, rèn binh khí, thu nạp những tàn dư của nhà Chu, dùng hôn nhân để phá vỡ cục diện. Trải qua mười sáu năm mở rộng lãnh thổ và mài sắc gươm kiếm, cuối cùng, ông đã đưa Tần từ một bộ lạc man di ở biên giới phía Tây vươn lên, trở thành một thế lực được các nước kính nể, đặt nền móng vững chắc cho sự quật khởi của Đại Tần!</p>', 'Full', 11, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Lộ","avatar":""},{"name":"Từ Tiễn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Rise of the Qin Empire","Đại Tần Đế Quốc Khởi Nguyên","大秦帝国起源"]', 1784690324141);
