INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-ca-nhi-long-ho-vo-lai-thien-ha', 'Đại Ca Nhị Long Hồ: Vô Lại Thiên Hạ', 'The Haoge Of Erlonghu: No Rogues Under Heaven', 'https://phimimg.com/upload/vod/20251130-1/3fb058aaad5e43bf6d0ef67750fb10d5.jpg', 'https://phimimg.com/upload/vod/20251130-1/3d0f125cd20691a5c137fb817b81ce94.jpg', '<p>Trương Thiên Bá cùng nhóm đòi nợ &quot;Thiên Hạ Vô Lại&quot; chuyên trị những con nợ chây ì, sau đó kết nạp thêm cô gái lừa đảo Tiểu Vy.&nbsp; Họ thực hiện nhiều vụ đòi nợ khó nhằn. Quá khứ nợ nần của Tiểu Vy bị phơi bày, liên quan đến trùm cho vay nặng lãi Lâm Tổng.&nbsp; Trương Thiên Bá phải đấu trí và đấu lực với Lâm Tổng. Cuối cùng, anh dấn thân vào nguy hiểm để giải cứu Tiểu Vy và phối hợp với cảnh sát bắt trọn băng nhóm tội phạm của Lâm Tổng.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Mai Bảo Lại","avatar":""},{"name":"Trương Hào","avatar":""},{"name":"Vương Đông Đống","avatar":""},{"name":"Thôi Học Vũ","avatar":""},{"name":"Đỗ Húc Đông","avatar":""},{"name":"Vu Vinh Quang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["二龙湖之天下无赖","Er Long Hu Hao Ge Zhi Tian Xia Wu Lai","Hao Ge of Erlonghu: The Unruly Scoundrel","The Underworld","二龙湖浩哥之天下无赖"]', 1784690324141);
