INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-that-chet-nguoi-2025', 'Sự Thật Chết Người', 'Truth Or Death', 'https://phimimg.com/upload/vod/20251130-1/f2951b631b50e4ff51df5a48f2a1c7fc.jpg', 'https://phimimg.com/upload/vod/20251130-1/65f853501631c7b29acd38d09bcf1cd1.jpg', '<p>Để cứu vợ mình, Dư Nhị Lưỡng đã trộm tiền tiết kiệm của người bạn thân là Lão Ba. Lão Ba truy đuổi món nợ, vô tình dẫn đến cái chết bất ngờ của vợ Dư Nhị Lưỡng. Lão Ba bị pháp luật trừng phạt vì tội ngộ sát. Con gái của Lão Ba là Dương Hinh lầm tưởng rằng cả gia đình Dư Nhị Lưỡng đã hãm hại cha cô. Kể từ đó, Dương Hinh ôm mối thù hận trong lòng và khởi động một trò chơi Sát Cơ (giết chóc) bằng &quot;Lời Nói Thật Lòng&quot; với mục đích trả thù và chuộc tội.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tần Phẫn","avatar":""},{"name":"Trương Ý Duệ","avatar":""},{"name":"Kim Mỹ Thần","avatar":""},{"name":"Trần Truyền Khải","avatar":""},{"name":"Đồng Gia Hào","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["真心话杀机"]', 1784690324141);
