INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('su-that-chet-nguoi-2025', 'Sự Thật Chết Người', 'Truth Or Death', 'sự thật chết người truth or death tần phẫn trương ý duệ kim mỹ thần trần truyền khải đồng gia hào 真心话杀机', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-dau-dai-chien-2025', 'Cô Dâu Đại Chiến', 'Bride War', 'https://phimimg.com/upload/vod/20251130-1/85fd763a49ca6de0920be6104508f8fe.jpg', 'https://phimimg.com/upload/vod/20251130-1/9c692332993a938eba34efccc99b4c0c.jpg', '<p>Ba cô bạn thân: Eun Ju bị bạn trai hủy hôn, Anna cá tính mạnh mẽ tin vào tình yêu mở, và nữ thần kế hoạch Byung Hee sống cuộc đời chuẩn mực như bảng Excel. Cả ba từng chuyền tay nhau &quot;Tuyển tập truyện 19+&quot; ở lớp học thêm, được mệnh danh là &quot;bộ ba chị em 19+&quot;,&nbsp; giờ chính thức bước vào đấu trường hôn nhân để săn lùng chú rể hoàn hảo. Vì sao ư? Phụ nữ 37 tuổi chỉ riêng chống đỡ cơn lũ áp lực hôn nhân đã đủ khiến người ta kiệt sức. May thay, ứng cử viên hoàn hảo là chú rể Ryan xuất hiện như phép màu. Để giành được chàng trai của số phận này, ba người bước vào trò chơi tình yêu bốn người. Nhưng rồi, sự thật chấn động dần hé lộ, người đàn ông được tung hô là “chú rể trong mơ” ấy hóa ra chỉ là kẻ lừa đảo hôn nhân với đầy mặc cảm tự ti. Phát hiện ra âm mưu, Eun Ju bật chế độ phản công, quyết đập nát lớp vỏ ngọt ngào mà gã đàn ông khốn kia dựng lên.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 32, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phim Ngắn","slug":"phim-ngan","id":"4f02d28224c0747511790d57fbb63a62"}]', '[]', 1784690324141);
