INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-sat-thu-cua-kanako-hanh-phuc-shiawase-kanako-no-koroshiya-seikatsu', 'Cuộc Sống Sát Thủ Của Kanako Hạnh Phúc (Shiawase Kanako no Koroshiya Seikatsu)', 'Happy Kanako''s Killer Life', 'https://phimimg.com/upload/vod/20251129-1/dfabb645eaa7ca6a0bc345613d7ee6b9.jpg', 'https://phimimg.com/upload/vod/20251129-1/ab5dd50a62987a8b949dcb545f29902d.jpg', '<p>Sau ba năm bị bóc lột ở công ty đen, Nishino Kanako (Non) nghỉ việc. Chật vật mãi mới tìm được công việc mới thì không ngờ đây lại là công ty sát thủ. Nhờ giám đốc đãi ngộ tốt, có tiền bối Sakurai (Fujigaya) tận tình chỉ bảo, Kanako dần phát hiện ra mình hợp công việc mới đến không ngờ...</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Non","avatar":""},{"name":"Taisuke Fujigaya","avatar":""},{"name":"Yuma Yamoto","avatar":""},{"name":"Hirona Yamazaki","avatar":""},{"name":"Yuuka Sugai","avatar":""},{"name":"Shun Sugata","avatar":""},{"name":"Tae Kimura","avatar":""},{"name":"Atsuro Watabe","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["幸福伽菜子的快乐杀手生活","Shiawase Kanako no Koroshiya Seikatsu","Cuộc Sống Sát Thủ Của Kanako Hạnh Phúc","幸せカナコの殺し屋生活"]', 1784690324141);
