INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mau-thoi-gian-la-venue-de-lavenir', 'Màu Thời Gian (La Venue de l''avenir)', 'Colours Of Time', 'https://phimimg.com/upload/vod/20251129-1/9d480884dfe7c782629e32ded09be242.jpg', 'https://phimimg.com/upload/vod/20251129-1/81edf4c9fbb3fd7214c3b402a9d102b1.jpg', '<p>Bốn anh em họ xa cách đoàn tụ nhờ một di sản bất ngờ và cùng hành trình khám phá lịch sử gia đình mình bằng cách lần theo dấu chân của tổ tiên.</p>', 'Full', 1, 'single', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Suzanne Lindon","avatar":""},{"name":"Abraham Wapler","avatar":""},{"name":"Vincent Macaigne","avatar":""},{"name":"Julia Piaton","avatar":""},{"name":"Zinedine Soualem","avatar":""},{"name":"Paul Kircher","avatar":""},{"name":"Vassili Schneider","avatar":""},{"name":"Sara Giraudeau","avatar":""},{"name":"Cécile de France","avatar":""},{"name":"Olivier Gourmet","avatar":""},{"name":"Claire Pommet","avatar":""},{"name":"Fred Testot","avatar":""},{"name":"François Chattot","avatar":""},{"name":"Raïka Hazanavicius","avatar":""},{"name":"Angèle Garnier","avatar":""},{"name":"Valenti","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Colours of time","从前的光景","Los colores del tiempo","Цвета́ вре́мени","Перетин часів","Die Farben der Zeit","I colori del tempo","塑造未來","從前的光景","Τα Χρώματα του Χρόνου","צבעי הזמן","Rokonidők","Pewnego razu w Paryżu","Cores do Tempo","Gelecek de Gelecek","Barvy času","La Venue de l''avenir"]', 1784690324141);
