INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-dao-no', 'Hoa Đào Nở', 'Peach Trap', 'https://phimimg.com/upload/vod/20251107-1/ba0c1470ccf7976838280e6b629831ef.jpg', 'https://phimimg.com/upload/vod/20251107-1/838fa053b5c6e79e5d9dda3636837388.jpg', '<p>Vào khoảnh khắc Yoo Do Ha rơi vào khủng hoảng lớn nhất cuộc đời, ba chàng trai bất ngờ xuất hiện bên cạnh anh! Từ đó, Do Ha bị cuốn vào cơn lốc “tín hiệu tình yêu” với cả ba người cùng lúc!&nbsp; Một vòng xoáy định mệnh xoay quanh Do Ha — liệu mũi tên tình yêu cuối cùng sẽ hướng về ai?&nbsp; Đây là một bộ phim hài lãng mạn vui tươi, tràn đầy năng lượng, kể về hành trình tìm kiếm người bạn trai đích thực của Do Ha.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jung Su-bin","avatar":""},{"name":"Cha Se-jin","avatar":""},{"name":"Lee Do-han","avatar":""},{"name":"Cha Yu-hyun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["桃花开好了","桃花開","桃花盛開","桃花開了","桃花開好了","복숭아 꽃이 피었습니다"]', 1784690324141);
