INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-mang-o-toa-dai-su', 'Án Mạng ở Tòa Đại Sứ', 'Murder At The Embassy', 'https://phimimg.com/upload/vod/20251128-1/3de043376298452d4a8cac0836073a58.jpg', 'https://phimimg.com/upload/vod/20251128-1/737750c78a7870eb31b06f4e7e1430f8.jpg', '<p>Cairo, 1934. Một án mạng trong Đại sứ quán Anh, một tài liệu tuyệt mật biến mất và danh sách nghi phạm kéo dài từ nhiếp ảnh gia Mỹ đến chính vị Đại sứ. Khi Miranda Green lần theo dấu vết, một âm mưu phát xít dần hiện hình, đe dọa Buckingham Palace và cả hòa bình thế giới.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Mischa Barton","avatar":""},{"name":"Richard Dillane","avatar":""},{"name":"Mido Hamada","avatar":""},{"name":"Antonia Bernath","avatar":""},{"name":"Kojo Attah","avatar":""},{"name":"Raha Rahbari","avatar":""},{"name":"Kathryn McGarr","avatar":""},{"name":"Nick Harris","avatar":""},{"name":"Yassine Mkhichen","avatar":""},{"name":"Josh Burdett","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["An Invitation to Murder: A Death in Cairo","Asesinato En La Embajada","רצח בשגרירות","Murder at the Embassy"]', 1784690324141);
