INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('an-mang-o-toa-dai-su', 'Án Mạng ở Tòa Đại Sứ', 'Murder At The Embassy', 'án mạng ở tòa đại sứ murder at the embassy mischa barton richard dillane mido hamada antonia bernath kojo attah raha rahbari kathryn mcgarr nick harris yassine mkhichen josh burdett an invitation to murder: a death in cairo asesinato en la embajada רצח בשגרירות murder at the embassy', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cu-ghi-diem-ngay-giang-sinh-chuyen-tinh-doi-bills', 'Cú Ghi Điểm Ngày Giáng Sinh: Chuyện Tình Đội Bills', 'Holiday Touchdown: A Bills Love Story', 'https://phimimg.com/upload/vod/20251128-1/b3215801b01c0e2ccdd2de8dc43f2961.jpg', 'https://phimimg.com/upload/vod/20251128-1/84b482c6e65817f15a32b7345a57abab.jpg', '<p>Bác sĩ nhi Morgan Quinn và Gabe DeLuca, Phó Chủ tịch Phát triển Sân vận động của đội Bills, luôn là đôi bạn thân thiết, nhưng Gabe thì từ lâu vẫn âm thầm dành tình cảm cho cô. Điều đó rõ ràng với gia đình họ… và hầu như bất kỳ ai đi ngang qua cũng nhận ra. Khi Morgan biết được từ chú Tommy rằng có ai đó đã âm thầm giúp đỡ gia đình cô sau khi ông được tuyển vào đội hơn sáu mươi năm trước, và rằng người đó vẫn gửi cho ông một món quà Giáng Sinh mỗi năm cho đến tận bây giờ, cô quyết định tìm ra ân nhân bí ẩn ấy để tặng chú một mùa Giáng Sinh thật đáng nhớ. Với sự giúp đỡ của những người bạn trong Bills Mafia, Morgan và Gabe cùng nhau lần theo dấu vết để tìm ra người gửi quà. Trên hành trình đó, tình cảm của Gabe dành cho Morgan càng sâu đậm, và đổi lại, cô cũng bắt đầu nhìn anh bằng ánh mắt khác… dù cả hai vẫn chưa đủ can đảm để thổ lộ.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Holland Roden","avatar":""},{"name":"Matthew Daddario","avatar":""},{"name":"Joe Pantoliano","avatar":""},{"name":"Tracy Pollan","avatar":""},{"name":"Caroline Aaron","avatar":""},{"name":"Steve Schirripa","avatar":""},{"name":"Patti Murin","avatar":""},{"name":"Patrick Mulvey","avatar":""},{"name":"Abraham Benrubi","avatar":""},{"name":"Ugo Chukwu","avatar":""},{"name":"Joey Palestina","avatar":""},{"name":"Mariand Torres","avatar":""},{"name":"Eve Gordon","avatar":""},{"name":"Meghann Garmany","avatar":""},{"name":"Ray Davis","avatar":""},{"name":"Kristopher Charles","avatar":""},{"name":"Mary Stou","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Holiday Touchdown: A Bills Love Story"]', 1784690324141);
