INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-kamitsubaki-dang-duoc-xay-dung', 'Thành Phố Kamitsubaki Đang Được Xây Dựng', 'Kamitsubaki City Under Construction', 'https://phimimg.com/upload/vod/20251127-1/7ab4283b14ae8e9b70eaf05c8b3627ef.jpg', 'https://phimimg.com/upload/vod/20251127-1/0c5c7df5da0f3c66fc17281e17a68b5d.jpg', '<p>Bảy năm sau khi nhân loại bị tàn phá bởi một thảm họa lớn, một ngọn hải đăng của khoa học và thịnh vượng đã trỗi dậy tại Thành phố Kamitsubaki. Nhưng ẩn núp trong bóng tối của nó là Tesseractor, những con quái vật sinh ra từ bóng tối của loài người. Chỉ có Witchling, năm cô gái sở hữu giọng nói ma thuật, mới có thể chống lại chúng. Với mỗi nốt nhạc, họ chiến đấu, không chỉ để bảo vệ hòa bình của thành phố, mà còn để hàn gắn một thế giới tan vỡ.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 4, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"KAF","avatar":""},{"name":"RIM","avatar":""},{"name":"Harusaruhi","avatar":""},{"name":"Isekaijoucho","avatar":""},{"name":"Koko","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Miyu Tomita","avatar":""},{"name":"Yohei Azakami","avatar":""},{"name":"Shuichiro Umeda","avatar":""},{"name":"Mai Toudoh","avatar":""},{"name":"Shizuka Itoh","avatar":""},{"name":"Hikaru Midorikawa","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Kamitsubaki-Shi Kensetsu-chuu.","Kamitsubaki-Shi Kensetsu-chū.","Kamitsubaki-shi Kensetsuchuu.","神椿市建設中。"]', 1784690324141);
