INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thanh-pho-kamitsubaki-dang-duoc-xay-dung', 'Thành Phố Kamitsubaki Đang Được Xây Dựng', 'Kamitsubaki City Under Construction', 'thành phố kamitsubaki đang được xây dựng kamitsubaki city under construction kaf rim harusaruhi isekaijoucho koko ayane sakura miyu tomita yohei azakami shuichiro umeda mai toudoh shizuka itoh hikaru midorikawa kamitsubaki-shi kensetsu-chuu. kamitsubaki-shi kensetsu-chū. kamitsubaki-shi kensetsuchuu. 神椿市建設中。', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bon-chuyen-vui', 'Bốn Chuyện Vui', 'Those Days', 'https://phimimg.com/upload/vod/20251109-1/b14c5dba2fafd667609f965d754c879d.jpg', 'https://phimimg.com/upload/vod/20251109-1/ee0304d80f40ae782efc5969ab9af8be.jpg', '<p>Minh Châu, một người phụ nữ có gia đình hạnh phúc và tình yêu ngọt ngào, vừa mới đăng ký kết hôn và biết mình có thai thì chồng cô, Kiến Kỳ, không may qua đời khi xả thân cứu người. Giữa muôn lời bàn tán, Minh Châu vẫn kiên định sẽ sinh đứa bé. Trong thời gian đó, cô đã tìm lại được bố mẹ ruột, nhờ có tình yêu thương vô bờ bến của bố mẹ, cô đã dần thoát khỏi đau thương. Nhưng bi kịch chưa dừng lại ở đó, bố chồng cô đột ngột qua đời, để lại khoản nợ khổng lồ khiến nhà chồng cô rơi vào cảnh kiệt quệ. Minh Châu không gục ngã, cô đứng ra gánh vác, làm rõ nợ nần, nhận thầu kinh doanh, đoàn kết các thành viên trong gia đình lại với nhau. Cuối cùng, gia đình nhà Minh Châu lại một lần nữa ngẩng cao đầu, dùng nghị lực phi thường bắt đầu gây dựng cuộc sống mới.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đồng Dao","avatar":""},{"name":"Tưởng Hân","avatar":""},{"name":"Hoàng Minh Hạo","avatar":""},{"name":"Hứa Đệ","avatar":""},{"name":"Lâm Hiểu Kiệt","avatar":""},{"name":"Hầu Nham Tùng","avatar":""},{"name":"Nhạc Hồng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Si Xi","十月人生","有喜","四喜"]', 1784690324141);
