INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bon-chuyen-vui', 'Bốn Chuyện Vui', 'Those Days', 'bốn chuyện vui those days đồng dao tưởng hân hoàng minh hạo hứa đệ lâm hiểu kiệt hầu nham tùng nhạc hồng si xi 十月人生 有喜 四喜', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-ha-truyen-2025', 'Ám Hà Truyện', 'Blood River', 'https://phimimg.com/upload/vod/20251020-1/5534575d408cef42e969a0b3031e396b.jpg', 'https://phimimg.com/upload/vod/20251020-1/0cc6b80564682aa1f32f45ed83d0d562.jpg', '<p>Ám Hà, tổ chức sát thủ hàng đầu giang hồ do ba gia tộc Tô, Mộ, Tạ thành lập, vừa ám sát hoàng thân trong triều vừa trấn áp các phe phái lớn. Trong nhiệm vụ ám sát nhị lão gia Đường Môn, đại gia trưởng trúng độc, ba gia tộc rục rịch tranh đoạt kiếm Miên Long và chức vị mới. Tô Mộ Vũ, thủ lĩnh Chu Ảnh Đoàn, dẫn Mộ Vũ Mặc và đồng đội bảo vệ đại gia trưởng, gặp trở ngại từ tiền bối Tô Triết và bạn Tô Xương Hà, đồng thời quen biết thần y Bạch Hạc Hoài. Sau loạt đọ sức, Tô Xương Hà trở thành đại gia trưởng, Tô Mộ Vũ làm gia chủ Tô gia, và họ triển khai “Kế hoạch Bỉ Ngạn” nhằm biến Ám Hà thành tổ chức quang minh, không còn là lưỡi dao trong tay bất kỳ ai, xoay giữa giang hồ và hoàng thất tìm lối thoát mới.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 13, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Cung Tuấn","avatar":""},{"name":"Bành Tiểu Nhiễm","avatar":""},{"name":"Kiều Chấn Vũ","avatar":""},{"name":"Thường Hoa Sâm","avatar":""},{"name":"Dương Dự Đồng","avatar":""},{"name":"Khổng Tuyết Nhi","avatar":""},{"name":"Trương Thời An","avatar":""},{"name":"Canh Lỗi","avatar":""},{"name":"Trương Đa","avatar":""},{"name":"Hầu Xương Vinh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["暗河传剧版","Fleuve de sang","ตำนานนทีมืด","Blood River","Tales of Dark River","暗河传"]', 1784690324141);
