INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('am-ha-truyen-2025', 'Ám Hà Truyện', 'Blood River', 'ám hà truyện blood river cung tuấn bành tiểu nhiễm kiều chấn vũ thường hoa sâm dương dự đồng khổng tuyết nhi trương thời an canh lỗi trương đa hầu xương vinh 暗河传剧版 fleuve de sang ตำนานนทีมืด blood river tales of dark river 暗河传', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhap-thanh-van', 'Nhập Thanh Vân', 'Love In The Clouds', 'https://phimimg.com/upload/vod/20251008-1/180a6d54413d9030e671b8e005c69753.jpg', 'https://phimimg.com/upload/vod/20251008-1/f4bf1435f0902fa174149a3ec890656c.jpg', '<p>Tại Đại hội Thanh Vân được tổ chức hằng năm ở Hợp Hư Lục Cảnh, kẻ xuất thân tù nhân Kỷ Bá Tể (do Hầu Minh Hạo thủ vai) chỉ trong một đòn đã đánh bại Minh Ý (do Lư Dục Hiểu thủ vai), nữ chiến thần lạnh lùng đã giữ vững chuỗi chiến thắng suốt bảy năm liền. Chỉ sau một đêm, hắn trở thành ngôi sao sáng giá nhất của vực Cực Tinh.Thế rồi, Minh Ý che giấu con người thật của mình, cải trang thành vũ cơ để tiếp cận Kỷ Bá Tể. Hai người đều &quot;mang mặt nạ&quot;, cuốn vào trận chiến vừa kịch tính vừa đắm say, cùng bảo vệ lẽ phải và cuối cùng đón nhận tình yêu chân thành.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 17, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hầu Minh Hạo","avatar":""},{"name":"Lư Dục Hiểu","avatar":""},{"name":"Dư Thừa Ân","avatar":""},{"name":"Hạc Nam","avatar":""},{"name":"Toàn Y Luân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["入青云","Amor en las nubes","입청운","Любовь в облаках","สู่ห้วงเมฆา","Love in the Clouds"]', 1784690324141);
