INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhap-thanh-van', 'Nhập Thanh Vân', 'Love In The Clouds', 'nhập thanh vân love in the clouds hầu minh hạo lư dục hiểu dư thừa ân hạc nam toàn y luân 入青云 amor en las nubes 입청운 любовь в облаках สู่ห้วงเมฆา love in the clouds', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-dia-kiem-tam', 'Thiên Địa Kiếm Tâm', 'Sword And Beloved', 'https://phimimg.com/upload/vod/20251025-1/a17e30d8c9c2e9fb049ab676a100a3ae.jpg', 'https://phimimg.com/upload/vod/20251025-1/792ccb0d628f620a68987f5745a79461.jpg', '<p>Vương Quyền Phú Quý từ nhỏ đã được huấn luyện như một vũ khí tối thượng để trừ yêu diệt quái của Nhất Khí Minh. Trong một lần tình cờ, chàng gặp được Thanh Đồng - một nữ yêu giả dạng người xâm nhập vào Sơn Trang Vương Quyền để làm gián điệp. Sự xuất hiện của Thanh Đồng đã thay đổi dần cách nhìn của Phú Quý về yêu quái, đồng thời mở ra trước mắt chàng một thế giới rộng lớn hơn. Niềm khát khao tự do và ước mơ về một thế giới đại đồng trong lòng Phú Quý dần được thắp lên. Sau khi trải qua kiếp nạn vạn kiếm xuyên tâm, chàng quyết định rời bỏ Sơn Trang Vương Quyền, cùng Thanh Đồng bước đi trên con đường chính đạo do mình giác ngộ.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 10, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Thành Nghệ","avatar":""},{"name":"Lý Nhất Đồng","avatar":""},{"name":"Quách Tuấn Thần","avatar":""},{"name":"Chiêu Trí Diêu","avatar":""},{"name":"Tầm Khải","avatar":""},{"name":"Phạm Minh","avatar":""},{"name":"Thường Hoa Sâm","avatar":""},{"name":"Trương Khải Anh","avatar":""},{"name":"Hà Thụy Hiên","avatar":""},{"name":"Đổng Mộng Thực","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["涂山小红娘王权篇","Fox Spirit Matchmaker: Wang Quan","狐妖小红娘·王权篇","狐妖小红娘之王权篇","狐妖小红娘王权篇","縁結びの妖狐ちゃん 王权篇","천지검심 (호요소홍랑 왕권편)","สื่อรักปีศาจจิ้งจอก ภาคเล่ห์รักเพลงดาบ","Fox Spirit Matchmaker 3","Fox Spirit Matchmaker: Sword and Beloved","Hồ Yêu Tiểu Hồng Nương: Vương Quyền Thiên","天地剑心"]', 1784690324141);
