INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-nang-2025', 'Dị Năng', 'Altered', 'https://phimimg.com/upload/vod/20251127-1/f058dc5a747d017ae2d4a14c887412fc.jpg', 'https://phimimg.com/upload/vod/20251127-1/031459bf58145b0653792d3a138f7ceb.jpg', '<p>Trong một thế giới nơi công nghệ chỉnh sửa gene tạo ra hai tầng lớp — người được “nâng cấp” và kẻ bị bỏ lại — Leon và cô bé Chloe thuộc nhóm thiểu số yếu thế. Khi bị vu oan và dồn vào đường cùng, họ đứng lên chống lại hệ thống phân biệt di truyền.</p>', 'Full', 1, 'single', 'completed', 21, 2025, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Tom Felton","avatar":""},{"name":"Aggy K. Adams","avatar":""},{"name":"Elizaveta Bugulova","avatar":""},{"name":"Igor Jijikine","avatar":""},{"name":"Richard Brake","avatar":""},{"name":"Aleksey Filimonov","avatar":""},{"name":"Daniyar Alshinov","avatar":""},{"name":"Atamura Mussakhanov","avatar":""},{"name":"Linda Nigmatulina","avatar":""},{"name":"Yelzhas Rakhim","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Project Darwin","Modificado","Projeto Darwin","Altered"]', 1784690324141);
