INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-loc-tai-chinh', 'Cơn Lốc Tài Chính', 'Bull Run', 'https://phimimg.com/upload/vod/20251127-1/14bcfa7a397e214c6b1dafc3d9dac2ef.jpg', 'https://phimimg.com/upload/vod/20251127-1/d9445ee3b3047c76e6cc77ace178f525.jpg', '<p>Theo chân Bobby Sanders, cựu vận động viên khúc côn cầu chuyên nghiệp nay trở thành nhân viên ngân hàng tập sự. Anh bước vào thế giới tài chính đầy kỳ lạ và có phần siêu thực, đối mặt với câu hỏi về ý nghĩa cuộc đời trong chiếc lồng mạ vàng này.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Blyth","avatar":""},{"name":"Helena Mattsson","avatar":""},{"name":"Chris Diamantopoulos","avatar":""},{"name":"Jay Mohr","avatar":""},{"name":"Zach Villa","avatar":""},{"name":"Alyshia Ochse","avatar":""},{"name":"Sam Daly","avatar":""},{"name":"John Lacy","avatar":""},{"name":"Meredith VanCuyk","avatar":""},{"name":"Brett Robert Culbert","avatar":""},{"name":"Vera Myers","avatar":""},{"name":"Ashwin Gore","avatar":""},{"name":"Brandon Engman","avatar":""},{"name":"Emil Beheshti","avatar":""},{"name":"Brian Dare","avatar":""},{"name":"Kash Hovey","avatar":""},{"name":"David Bickford","avatar":""},{"name":"Jordyn Denn","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bull Run"]', 1784690324141);
