INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhap-mong-su-phat-y-va-a-that', 'Nhập Mộng Sư: Phất Y Và A Thất', 'The Dreamwalker', 'https://phimimg.com/upload/vod/20251116-1/09a770fd5383384bac41fb0e20ede42d.jpg', 'https://phimimg.com/upload/vod/20251116-1/2d5fb1914036a017537e9d5132111e17.jpg', '<p>Tiểu thư tiêu cục Hà Phất Y phải chứng kiến cảnh gia tộc mình bị sát hại. Khi đang mang trên mình thần khí thượng cổ Thất Tinh Đăng, cô bị rơi xuống vực. Máu của cô đã vô tình đánh thức linh hồn đèn A Thất, khiến cả hai bắt đầu mối quan hệ cộng sinh. Để báo thù, truy tìm hung thủ, đồng thời cũng dùng sức mạnh của ngọn đèn kéo dài mạng sống, Hà Phất Y và A Thất dấn thân vào hành trình &quot;giải mộng, phá bỏ chấp niệm&quot;. Trên đường đi, họ bị cuốn vào cơn biến loạn cuối triều Thanh và đồng hành cùng Bối Lặc Tiểu Ngũ Gia. Sau khi chứng kiến vô vàn nhân tình thế thái của thế gian, cuối cùng họ cũng vén màn được sự thật.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Kính Y","avatar":""},{"name":"Uông Giai Huy","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["入梦师之拂衣与阿七","Ru Meng Shi Fu Yi Yu A Qi","入梦师：拂衣与阿七"]', 1784690324141);
