INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-tung-gia', 'Truy Tung Giả', 'The Finder', 'https://phimimg.com/upload/vod/20251126-1/c96b53ce5cdbe76eaafb7d2edec886e5.jpg', 'https://phimimg.com/upload/vod/20251126-1/8c59af2dfab0b49592ed197c0c3fe45a.jpg', '<p>Lưu Tiểu Mỹ bị ép tự sát do vay nặng lãi. Để trả thù cho bạn, Nghiêm Minh đã dùng biện pháp phi pháp để bắt cóc Tiền Tĩnh&nbsp; – con gái của Vương Dũng , quản lý băng nhóm cho vay nặng lãi—và Châu Tình – con gái của đội trưởng cảnh sát hình sự Châu Vĩ Cường.Để giải cứu con gái mình và Tiền Tĩnh, Châu Vĩ Cường đã đấu trí với băng nhóm tội phạm, thâm nhập vào hang ổ của chúng. Cuối cùng, anh đã thành công giải cứu con tin và đưa tội phạm ra trước ánh sáng công lý.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Mậu Phong Bân","avatar":""},{"name":"Mạnh Chân","avatar":""},{"name":"Vương Tân Quân","avatar":""},{"name":"Tôn Đại Xung","avatar":""},{"name":"Lưu Phong Siêu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["追踪者"]', 1784690324141);
