INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trum-huong-cang-bao-to-liem-chinh', 'Trùm Hương Cảng: Bão Tố Liêm Chính', 'Extras For Chasing The Dragon', 'https://phimimg.com/upload/vod/20250214-1/de7015f9ef587f352cb13f0dc3099c50.jpg', 'https://phimimg.com/upload/vod/20250214-1/850fd820563a738797d4cc6d53dcd61f.jpg', '<p>Bộ phim kể về câu chuyện của Ngũ Quốc Hào, một người gan dạ và dám nghĩ dám làm, cùng hai người bạn thân từ nhỏ là Đại Uy và Tiểu Uy vượt biên từ Quảng Đông sang Hồng Kông để mưu sinh. Họ được viên thanh tra mưu lược Từ Lạc trọng dụng và sau này từng bước thống trị cả giới hắc bạch Hồng Kông. Từ Lạc ban đầu chỉ là một thanh niên đầy hoài bão, gia nhập lực lượng cảnh sát với mong muốn phục vụ người dân và gìn giữ công lý, nhưng rồi anh phát hiện ra toàn bộ lực lượng cảnh sát đều mục nát và thối nát đến cực điểm.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Tiểu Xuân","avatar":""},{"name":"Vương Hạo Tín","avatar":""},{"name":"Từ Đông Đông","avatar":""},{"name":"Vân Thiên Thiên","avatar":""},{"name":"Trịnh Tắc Sĩ","avatar":""},{"name":"Lâm Tử Thiện","avatar":""},{"name":"Hòa Hạo Văn","avatar":""},{"name":"Lý Gia Kỳ","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chasing.The.Dragon","追龙番外篇之廉政大风暴"]', 1784690324141);
