INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kevin-hart-hanh-xu-cho-phai-lua', 'Kevin Hart: Hành Xử Cho Phải Lứa', 'Kevin Hart: Acting My Age', 'https://phimimg.com/upload/vod/20251126-1/4eb667b7db5dda3e14c61e10f2de119f.jpg', 'https://phimimg.com/upload/vod/20251126-1/3794de0ddb18c451dac75225d2212fe1.jpg', '<p>Già dặn hơn, khôn ngoan hơn – và vẫn cực kỳ hài hước. Kevin Hart chia sẻ về những sự cố tuổi trung niên của mình, từ thuốc cường dương đến rắc rối do chấn thương không ngờ tới.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kevin Hart","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Kevin Hart: Acting My Age"]', 1784690324141);
