INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-yeu-cua-queen', 'Người Yêu Của Queen', 'Dangerous Queen', 'https://phimimg.com/upload/vod/20251006-1/dded3d82728338febcf0779805840951.jpg', 'https://phimimg.com/upload/vod/20251006-1/923cb849f2743a310850770369d9e491.jpg', '<p>Bonita là một cô gái trẻ sống trong nghèo khó, bị mẹ bạo hành và không có lối thoát. Cuộc đời cô thay đổi khi gặp Queen – một người phụ nữ quyền lực, lạnh lùng nhưng giàu lòng trắc ẩn. Queen đưa Bonita về sống cùng và thuê cô làm người chăm sóc cá nhân. Từ mối quan hệ hợp đồng, cả hai dần nảy sinh tình cảm. Nhưng tình yêu của họ bị thử thách bởi quá khứ đau thương, định kiến xã hội và những áp lực từ gia đình và quyền lực.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Desoraya Techapaibul","avatar":""},{"name":"Phinyanech Aungsuwan","avatar":""},{"name":"Akrabhaj Bunnag","avatar":""},{"name":"Tan Buranrat Hombut","avatar":""},{"name":"Arisara Wongchalee","avatar":""},{"name":"Iang Sittha Sapanuchart","avatar":""},{"name":"Papassara Teychapaiboon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Dangerous Queen","คนโปรดของควีน"]', 1784690324141);
