INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-yeu-cua-queen', 'Người Yêu Của Queen', 'Dangerous Queen', 'người yêu của queen dangerous queen desoraya techapaibul phinyanech aungsuwan akrabhaj bunnag tan buranrat hombut arisara wongchalee iang sittha sapanuchart papassara teychapaiboon dangerous queen คนโปรดของควีน', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xuyen-khong-toi-la-hoan-chau-ti-nu', 'Xuyên Không Tôi Là Hoàn Châu... Tì Nữ', 'Returning Pearl', 'https://phimimg.com/upload/vod/20251121-1/53ef95bed47652224c4f34fbcfd99332.jpg', 'https://phimimg.com/upload/vod/20251121-1/fd44e0cdd131ef7afd0a7d8c42aa426e.jpg', '<p>Nữ chính Lâm Tuế Tuế vô tình xuyên không vào thế giới trong nguyên tác &quot;Hoàn Châu Cách Cách&quot; – một thế giới mà cốt truyện đã bị sụp đổ (bung bét).Cô trở thành một cung nữ quét dọn trong cung của Hoàng hậu, thuộc &quot;phe phản diện&quot;. Cô nhận ra rằng, muốn thoát khỏi thế giới này, cô phải khôi phục và hoàn thành cốt truyện nguyên tác đã bị lệch lạc.Ai ngờ, giữa đường lại xuất hiện một thị vệ của Thận Hình Tư (cơ quan chuyên trách hình phạt) quấn lấy cô không dứt. Hiệu ứng cánh bướm mà nam chính này tạo ra đã dẫn đến hàng loạt sự cố bất ngờ.Liệu Lâm Tuế Tuế sẽ làm cách nào để dựa vào những ký ức vụn vặt về nguyên tác &quot;Hoàn Châu Cách Cách&quot;, kéo theo cả nhóm nhân vật chính để duy trì sự phát triển của cốt truyện ban đầu?</p>', 'Hoàn Tất (31/31)', 31, 'series', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hồ Liên Hinh","avatar":""},{"name":"La Nhất Chu","avatar":""},{"name":"Nghiên Hử Gia","avatar":""},{"name":"Kim Tử Tuyên","avatar":""},{"name":"Viên Tử Minh","avatar":""},{"name":"Từ Viện Dật Na","avatar":""},{"name":"Ngụy Ngụy","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["还珠格格","还珠"]', 1784690324141);
