INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-gap-hoang-tu-ben-bo-bien', 'Tôi Gặp Hoàng Tử Bên Bờ Biển', 'That Summer', 'https://phimimg.com/upload/vod/20250922-1/c8ea3aea5fc95299bd070847c21ff72f.jpg', 'https://phimimg.com/upload/vod/20250922-1/8a42779de80bb6fcbc312c3fa188de65.jpg', '<p>Bị gửi đến một hòn đảo hẻo lánh để chịu kỷ luật, một kẻ gây rắc rối đã gặp gỡ một người trôi dạt mất trí nhớ. Sự xuất hiện của người ấy đã biến mùa hè tẻ nhạt của anh trở thành một câu chuyện tình yêu.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Thanawin Pholcharoenrat","avatar":""},{"name":"Kittiphop Sereevichayasawat","avatar":""},{"name":"Tanutchai Wijitvongtong","avatar":""},{"name":"Phudtripart Bhudthonamochai","avatar":""},{"name":"Trai Nimtawat","avatar":""},{"name":"Thishar Thurachon","avatar":""},{"name":"Teeradech Vitheepanich","avatar":""},{"name":"Tipnaree Weerawatnodom","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["夏日 沙滩 我的王子","我在沙滩上遇见了王子","那个夏日","That Summer I Met a Prince on the Beach","ผมเจอเจ้าชายบนชายหาด"]', 1784690324141);
