INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('toi-gap-hoang-tu-ben-bo-bien', 'Tôi Gặp Hoàng Tử Bên Bờ Biển', 'That Summer', 'tôi gặp hoàng tử bên bờ biển that summer thanawin pholcharoenrat kittiphop sereevichayasawat tanutchai wijitvongtong phudtripart bhudthonamochai trai nimtawat thishar thurachon teeradech vitheepanich tipnaree weerawatnodom 夏日 沙滩 我的王子 我在沙滩上遇见了王子 那个夏日 that summer i met a prince on the beach ผมเจอเจ้าชายบนชายหาด', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ti-nu-2025', 'Tì Nữ', 'The Maid', 'https://phimimg.com/upload/vod/20250910-1/7c8d58071596b4d0b7d455838a5b66a3.jpg', 'https://phimimg.com/upload/vod/20250910-1/123501cee3fcdd5e4f009656cf37bd0e.jpg', '<p>Thẩm Ngọc Thanh là con thứ của phủ Quốc công, chịu bắt nạt đến cùng cực, mẹ ruột Tần tiểu nương bị hại. Vì để báo thù, nàng hóa thân thành Tịch Nhan - kỹ nữ của Mị Hương Lâu, tiếp cận nhiếp chính vương Bùi Tịch. Tịch Nhan dựa vào nhan sắc xinh đẹp và sự thông minh của mình, dần dà giành được sự tin tưởng và cưng chiều của Bùi Tịch. Nàng âm thầm đặt bẫy, vạch trần âm mưu của thái hậu và phủ Quốc công, đồng thời bảo vệ Bùi Chiêu - con trai của mình. Tịch Nhan và Bùi Tịch đã bắt tay chống lại thế lực của thái hậu và phủ Quốc công, trải qua bao thử thách sống chết. Bùi Tịch vì bảo vệ Tịch Nhan và Chiêu Nhi, không tiếc lấy thân mình làm mồi nhử, thâm nhập sâu vào phía địch. Bùi Tịch &quot;chết&quot;, Tịch Nhan đưa Chiêu Nhi đi mai danh ẩn tích, mở y quán tại nơi biên ải. Bùi Tịch giả chết thoát thân, trùng phùng cùng mẹ con Tịch Nhan, cả ba người cùng sống hạnh phúc, bình yên bên nhau.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đặng Khải","avatar":""},{"name":"Triệu Tịch Tịch","avatar":""},{"name":"Dương Văn Huyến","avatar":""},{"name":"Diêu Nặc","avatar":""},{"name":"Vu Hân Ngật","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bi Nv","婢女"]', 1784690324141);
