INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-an-quy-su-truyen-than-do', 'Trường An Quỷ Sự Truyện: Thần Đô', 'Treacherous Cases In Shendu', 'https://phimimg.com/upload/vod/20251117-1/77d01851619691426bac9e1ac3699f56.jpg', 'https://phimimg.com/upload/vod/20251117-1/4d89cd8fe1433c3aa40c11fc83cf6798.jpg', '<p>Trong đêm Lý Nha Nhi đi đón dâu thay cha, tân nương bỗng tự thiêu một cách đầy bí ẩn, bản thân lại bị thích khách tấn công, mất hết kí ức và rơi vào cảnh nô lệ. Khi màn sương đẫm máu vén lộ bí mật thân thế, mối tình nghiệt ngã giữa chủ và tớ buộc họ phải đứng ở hai đầu lưỡi kiếm. Dưới lớp mặt nạ là một tấm chân tình, phía sau vụ án quỷ dị lại ẩn giấu tình cảm cuộn trào. Hãy cùng dõi theo vị quận chúa hai mặt nắm tay sát thần lạnh lùng phá vỡ cục diện, gìn giữ giang sơn trong đêm tối Đại Đường ra sao.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ôn Mạt Ngôn","avatar":""},{"name":"Trình Vũ Phong","avatar":""},{"name":"Vương Ngạn Hâm","avatar":""},{"name":"Châu Nghi","avatar":""},{"name":"Trương Duyệt","avatar":""},{"name":"Lý Chỉ Hân","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Man s Secret","The Man''s Secret","长安诡事传之神都"]', 1784690324141);
