INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-lam-bao-mau-o-lanh-cung', 'Tôi Làm Bảo Mẫu Ở Lãnh Cung', 'Babysitter', 'https://phimimg.com/upload/vod/20251116-1/83c7886a0557eb9b7f03a6922a21f1c0.jpg', 'https://phimimg.com/upload/vod/20251116-1/6f4327f5cfa3a7ae0abad184a91497fd.jpg', '<p>Trương Tiểu Tuyết vô tình rơi xuống hố, tỉnh dậy đã thấy mình ở lãnh cung thời cổ đại! Dựa vào kỹ năng chăm sóc sau sinh chuyên nghiệp, cô giúp phi tần thất sủng lật ngược tình thế, mở ra hành trình ngoạn mục gây dựng sự nghiệp!</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Tử Khê","avatar":""},{"name":"Lý Bái Dương","avatar":""},{"name":"Tôn Thái Luân","avatar":""},{"name":"Tạ Dịch Chân","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Maternity Matron in the Cold Palace","我在冷宫做月嫂"]', 1784690324141);
