INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-bat-dao-tac', 'Truy Bắt Đạo Tặc', 'Never A Thief', 'https://phimimg.com/upload/vod/20251122-1/aa3821cb0dcb57f15b79aeaca93f75a6.jpg', 'https://phimimg.com/upload/vod/20251122-1/c28058b402f79ddc15a657ae36f3b158.jpg', '<p>Bộ phim kể về Triệu Cát – một chàng trai gốc Hoa – nhờ vào kỹ năng mở khóa siêu phàm đã gia nhập vào một băng nhóm trộm cổ vật do “Ông Tượng” cầm đầu. Cùng với những người đồng đội, mỗi người một sở trường, họ thực hiện hàng loạt phi vụ trộm táo bạo và nghẹt thở. Sau tất cả những biến cố, Triệu Cát cuối cùng cũng khám phá ra sự thật đằng sau vụ mất tích bí ẩn của cha mình.</p>', 'Full', 1, 'single', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Nhậm Đạt Hoa","avatar":""},{"name":"Mạch Hằng Lợi","avatar":""},{"name":"Clara","avatar":""},{"name":"Tiền Giai Lạc","avatar":""},{"name":"Viên Phú Hoa","avatar":""},{"name":"Hoàng Đức Bân","avatar":""},{"name":"Vu Bách Lâm","avatar":""},{"name":"Lữ Thần Duyệt","avatar":""},{"name":"Tôn Dục Hàn","avatar":""},{"name":"Liên Khải","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Catch Thieves Catch Theft","缉盗"]', 1784690324142);
