INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('truy-bat-dao-tac', 'Truy Bắt Đạo Tặc', 'Never A Thief', 'truy bắt đạo tặc never a thief nhậm đạt hoa mạch hằng lợi clara tiền giai lạc viên phú hoa hoàng đức bân vu bách lâm lữ thần duyệt tôn dục hàn liên khải catch thieves catch theft 缉盗', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-tuong-6h30-biet-hieu-dien-cuong', 'Trần Tường 6h30: Biệt Hiệu Điên Cuồng', 'Namesake', 'https://phimimg.com/upload/vod/20251122-1/8ef70b580bbb19cad2c7b4db6304f439.jpg', 'https://phimimg.com/upload/vod/20251122-1/d37f572b17e8764b20a521bb6259bbc2.jpg', '<p>Phim kể về một sự hiểu lầm kỳ lạ bắt nguồn từ việc ba người trùng tên, kéo theo hàng loạt người bị cuốn vào vòng xoáy rắc rối. Trong tình huống thông tin không đồng nhất, họ phải trải qua nhiều gian truân, nhưng vẫn luôn giữ niềm tin vào cuộc sống và không ngừng theo đuổi điều tốt đẹp. Cuối cùng, kẻ xấu bị trừng trị, người tốt thực hiện được ước mơ. Tác phẩm không chỉ khẳng định “ác giả ác báo, chính nghĩa tất thắng”, mà còn dùng những tình tiết hài hước nhưng hợp lý để truyền tải năng lượng tích cực, khơi gợi lòng nhân ái và sự yêu đời nơi khán giả.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Mao Đài","avatar":""},{"name":"Trư Tiểu Minh","avatar":""},{"name":"Mộc Câu Đầu","avatar":""},{"name":"Nhuận Thổ","avatar":""},{"name":"Vương Trác","avatar":""},{"name":"Lãnh Mông","avatar":""},{"name":"Ứng Bảo Lâm","avatar":""},{"name":"Kỷ Văn Quân","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Name Sake","陈翔六点半之疯狂代号"]', 1784690324142);
