INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hay-lay-em-di-anh-co-muon-cuoi-em-khong', 'Hãy Lấy Em Đi (Anh Có Muốn Cưới Em Không?)', 'Would You Marry Me?', 'https://phimimg.com/upload/vod/20251011-1/0104efe6e144dc802ba4d74ebb2df3e6.jpg', 'https://phimimg.com/upload/vod/20251011-1/ce7496f6ba1a4d6024d804813c226bc1.jpg', '<p>Một người đàn ông và một người phụ nữ cùng bước vào cuộc hôn nhân giả kéo dài 90 ngày để giành được một ngôi nhà tân hôn sang trọng .</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 10, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Choi Woo-shik","avatar":""},{"name":"Jung So-min","avatar":""},{"name":"Shin Seul-ki","avatar":""},{"name":"Bae Na-ra","avatar":""},{"name":"Seo Bum-june","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["宇宙Marry Me？","宇宙嫁给我","Marry Me in the Universe","هل تتزوجني؟","宇宙MARRY ME","Would You Marry Me?","우주메리미"]', 1784690324142);
