INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hay-lay-em-di-anh-co-muon-cuoi-em-khong', 'Hãy Lấy Em Đi (Anh Có Muốn Cưới Em Không?)', 'Would You Marry Me?', 'hãy lấy em đi (anh có muốn cưới em không?) would you marry me? choi woo-shik jung so-min shin seul-ki bae na-ra seo bum-june 宇宙marry me？ 宇宙嫁给我 marry me in the universe هل تتزوجني؟ 宇宙marry me would you marry me? 우주메리미', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuyet-canh-ba', 'Tuyết Canh Ba', 'The Tower Of Whispers', 'https://phimimg.com/upload/vod/20250927-1/4dd250c337a73616eb33e97e04f32829.jpg', 'https://phimimg.com/upload/vod/20250927-1/9324ead7f5f79f05685269c249d2d0a4.jpg', '<p>Câu chuyện kể về Lục Oanh Oanh, con gái của Lễ bộ Thượng thư, vốn có một gia đình hạnh phúc ấm êm. Nhưng sau khi cha mẹ bị kẻ ác hãm hại, nàng rơi vào cảnh sa sút, trở thành phi tần của bạo quân Quân Triệt. Vì bảo vệ nghĩa huynh Yến Hồi, nàng bị Quân Triệt hiểu lầm mà giết chết. Mang theo nỗi oán hận và tiếc nuối, Lục Oanh Oanh may mắn được trọng sinh về trước khi bi kịch xảy ra. Trong kiếp này, để thay đổi số mệnh, nàng từ một tiểu thư mềm yếu trở nên kiên cường, quyết đoán, lần lượt vượt qua những nguy nan từng gặp phải. Tưởng rằng có thể nắm giữ vận mệnh, nhưng nàng bất ngờ tái ngộ Quân Triệt — lúc này vẫn chỉ là một nô lệ. Mang thù xưa, Lục Oanh Oanh mua hắn về để trả thù, song dần phát hiện Quân Triệt có lai lịch bí ẩn, không hề tầm thường. Khi gia đình tiếp tục lâm nguy, nàng quyết định giữ Quân Triệt bên cạnh, lợi dụng hắn để phục thù. Trong quá trình đồng hành, hai người từ đối địch trở thành bạn đồng hành, cùng vào sinh ra tử. Quân Triệt bị sự quả cảm và nhân hậu của nàng chinh phục, dần nảy sinh tình cảm. Còn Lục Oanh Oanh, bất ngờ rung động trước kẻ mà kiếp trước mình hận đến thấu xương. Từ đây, số phận của cả hai gắn chặt vào nhau, yêu và hận đan xen, mở ra một đoạn tình duyên đầy kịch tính.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hà Lãng Đậu","avatar":""},{"name":"Đặng Hiếu Tư","avatar":""},{"name":"Chung Thần Dao","avatar":""},{"name":"Hạ Dịch","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["风满楼","ささやきの塔","หิมะยามเที่ยงคืน","The Tower of Whispers","三更雪"]', 1784690324142);
