INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('summer-pockets', 'Summer Pockets', 'Summer Pockets', 'https://phimimg.com/upload/vod/20250423-1/8fe528b591540f01391de45798506a9c.jpg', 'https://phimimg.com/upload/vod/20250423-1/c2541708fdd9f9bd0f4ead5d6e2bf2a0.jpg', '<p>Hairi Takahara không bao giờ mong đợi mùa hè sẽ giống như một giấc mơ. Được gửi đến Torishirojima để sắp xếp đồ đạc của người bà quá cố, anh đã gặp biển cả mênh mông, nỗi nhớ yên bình và những cô gái bí ẩn, mỗi người đều theo đuổi một thứ gì đó ngoài tầm với. Khi anh ổn định cuộc sống trên đảo, những ký ức đã mất bắt đầu xuất hiện và anh tìm thấy thứ mà anh chưa từng biết mình đã mất.</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shoya Chiba","avatar":""},{"name":"Konomi Kohara","avatar":""},{"name":"Natsumi Takamori","avatar":""},{"name":"Nene Hieda","avatar":""},{"name":"Emiri Iwai","avatar":""},{"name":"Saku Ichimiya","avatar":""},{"name":"Sahomi Koyama","avatar":""},{"name":"Aimi Tanaka","avatar":""},{"name":"Megumi Takamoto","avatar":""},{"name":"Minoru Shiraishi","avatar":""},{"name":"Konomi Suzuki","avatar":""},{"name":"Kentaro Kumagai","avatar":""},{"name":"Youhei Hamada","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Кішэні лета","サマーポケッツ","サマポケ","SUMMER POCKETS","Summer Pockets"]', 1784690324142);
