INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuong-tay-kinh-hon-luc', 'Tương Tây Kinh Hồn Lục', 'The Horror Story Of Xiangxi (The King''s Reasure)', 'https://phimimg.com/upload/vod/20251121-1/4ee9126acdbad4aa093efcf12022138f.jpg', 'https://phimimg.com/upload/vod/20251121-1/ce12cf64c8c099ff883ed196bc7bfdf3.jpg', '<p>Đầu thời Dân Quốc, tên đào ngũ Bì Tứ lần theo dấu một đạo sĩ giả đến trấn Thiên Môn ở Tương Tây, vạch trần âm mưu buôn bán thiếu nữ và vận chuyển xác chết của hắn. Không ngờ, vụ việc ấy lại kéo theo truyền thuyết về kho báu của Sấm Vương, khiến nhiều người dòm ngó. Trong hành trình ấy, Bì Tứ và tiểu thư quân phiệt Dương Bội Như trở thành oan gia vui vẻ, cùng với sự giúp đỡ của thiếu gia thổ ty và thiếu nữ dân tộc Miêu, họ dần giải mã bí mật kho báu, mở ra một chuỗi phi vụ tranh đoạt ly kỳ và hài hước.</p>', 'Full', 1, 'single', 'completed', 4, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Diệp Đình","avatar":""},{"name":"Trần Phi","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["湘西惊魂录"]', 1784690324142);
