INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hon-cua-ke-giang-luoi', 'Nụ Hôn Của Kẻ Giăng Lưới', 'Kiss Of The Spider Woman', 'https://phimimg.com/upload/vod/20251121-1/b4f08ef548a1ee105b9e4a83625a063a.jpg', 'https://phimimg.com/upload/vod/20251121-1/4e2acea588910e16bd44859a7b087726.jpg', '<p>Trong một nhà tù ở Buenos Aires, hai người đàn ông cùng chung phòng giam: Molina — một người đồng tính ám ảnh với các bộ phim tình cảm và giả tưởng, và Valentín — một nhà hoạt động cách mạng chính trị. Giữa không gian ngột ngạt ấy, Molina kể cho Valentín nghe về bộ phim “Người Đàn Bà Nhện,” dần dần xóa nhòa khoảng cách giữa họ. Qua tình bạn, lòng trắc ẩn và một nụ hôn bất ngờ, cả hai phải đối diện với tình yêu, sự phản bội, và những câu hỏi sâu sắc về tự do cũng như ý nghĩa tồn tại.</p>', 'Full', 1, 'single', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Diego Luna","avatar":""},{"name":"Tonatiuh","avatar":""},{"name":"Jennifer Lopez","avatar":""},{"name":"Bruno Bichir","avatar":""},{"name":"Josefina Scaglione","avatar":""},{"name":"Aline Mayagoitia","avatar":""},{"name":"Driton ''Tony'' Dovolani","avatar":""},{"name":"Lucila Gandolfo","avatar":""},{"name":"Federico Repetto","avatar":""},{"name":"Lucas Barreiro","avatar":""},{"name":"Augusto Gordillo","avatar":""},{"name":"Fabio Aste","avatar":""},{"name":"Graciela Daniele","avatar":""},{"name":"Federico Salles","avatar":""},{"name":"Alejandro Ernes","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["O Beijo da Mulher-