INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('do-ki-phan-3', 'Đố Kị (Phần 3)', 'Envious (Season 3)', 'https://phimimg.com/upload/vod/20251120-1/8f26f5e0359af3c5fc9ca1cc9b71785b.jpg', 'https://phimimg.com/upload/vod/20251120-1/bf6f8dccfdd696256542609714a95eef.jpg', '<p>Sau cuộc chia tay đau lòng, Vicky, giờ đã gần 40 tuổi, bắt đầu tìm kiếm tình yêu mới mà không biết rằng việc này sẽ dẫn cô vào hành trình tự khám phá đầy sâu sắc và hài hước.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Griselda Siciliani","avatar":""},{"name":"Esteban Lamothe","avatar":""},{"name":"Pilar Gamboa","avatar":""},{"name":"Violeta Urtizberea","avatar":""},{"name":"Marina Bellati","avatar":""},{"name":"Bárbara Lombardo","avatar":""},{"name":"Martín Garabal","avatar":""},{"name":"Lorena Vega","avatar":""},{"name":"Susana Pampín","avatar":""},{"name":"Leonora Balcarce","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["나만 빼고 다 잘살아","Envidiosa"]', 1784690324142);
