INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-co-dong-2025', 'Đội Cơ Động', 'Police Tactical Unit', 'https://phimimg.com/upload/vod/20251113-1/7e0c0f784ead9bad53eb64075d9bd8f5.jpg', 'https://phimimg.com/upload/vod/20251113-1/a0da2bb447f07d35a29b8ad2952cb624.jpg', '<p>Bộ phim xoay quanh hành trình phá án ly kỳ của Tổ Cơ động, Đội Đặc nhiệm Hình sự thuộc Tổng đội Cảnh sát Điều tra Hình sự Thành phố Dung Thành. Từ vụ “tự sát” được dàn dựng tinh vi của nữ minh tinh, vụ trộm đột nhập được tính toán kỹ lưỡng, vụ giấu ma túy kín kẽ trong căn biệt thự xa hoa, cho đến vụ nhóm tội phạm buôn ma túy giăng bẫy tấn công cảnh sát… Dù tội phạm có tung hỏa mù, giở trăm phương nghìn kế, cũng không thể thoát khỏi con mắt tinh anh của lực lượng cảnh sát hình sự.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Tăng Vũ","avatar":""},{"name":"Kim Mạn","avatar":""},{"name":"Lý Tích Thần","avatar":""},{"name":"Trần Nam","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["机动组 第一季","Ji Dong Zu","Police Tactical Unit Season 1","机动组"]', 1784690324142);
