INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kho-bau-escobar', 'Kho Báu Escobar', 'Escobank', 'https://phimimg.com/upload/vod/20251120-1/a645fb76fbe3ecbf4b8a46384607a243.jpg', 'https://phimimg.com/upload/vod/20251120-1/956eb6d983417d9951b8d53eaf07ad01.jpg', '<p>Một nhóm tội phạm liều lĩnh kéo đến rừng Colombia để săn kho tiền mặt mà Pablo Escobar từng chôn giấu. Khi càng tiến sâu, tham vọng biến thành nghi kỵ, những bí mật của từng người lộ ra, và hành trình truy tìm kho báu nhanh chóng trở thành cuộc đấu sinh tử giữa chính các thành viên trong nhóm.</p>', 'Full', 1, 'single', 'completed', 4, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Zohar Liba","avatar":""},{"name":"Dana Frider","avatar":""},{"name":"Angel Bonanni","avatar":""},{"name":"George Iskandar","avatar":""},{"name":"Rodrigo Poisón","avatar":""},{"name":"Harlys Becerra","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["אסקובנק"]', 1784690324142);
