INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-phong-truy-anh', 'Bổ Phong Truy Ảnh', 'The Shadow''s Edge', 'https://phimimg.com/upload/vod/20251120-1/1ddbc9e5d0ac32ecdaa3531dcc531d6e.jpg', 'https://phimimg.com/upload/vod/20251120-1/0b40c87a1d88f39aaa19fbef6da4ece8.jpg', '<p>Wong Tak-Chung, một cựu chuyên gia giám sát được biết đến với khả năng phân tích dữ liệu và truy vết bậc thầy, bị cảnh sát Ma Cao mời trở lại hợp tác điều tra sau khi xuất hiện hàng loạt vụ cướp quy mô lớn do một tổ chức tội phạm công nghệ cao thực hiện.</p>', 'Full', 1, 'single', 'completed', 14, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Thành Long","avatar":""},{"name":"Trương Tử Phong","avatar":""},{"name":"Lương Gia Huy","avatar":""},{"name":"Văn Tuấn Huy","avatar":""},{"name":"Châu Chánh Kiệt","avatar":""},{"name":"Vương Tử Dị","avatar":""},{"name":"Lâm Thu Thuần","avatar":""},{"name":"Vương Trấn Vĩ","avatar":""},{"name":"Lý Triết Khôn","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["捕風追影","极盗跟踪","捕风追影","The Shadow''s Edge","A Sombra do Perigo","لبه سایه","Shadow Chase - Im Netz der Diebe","Operación: Sombra","Bǔ fēng zhuī yǐng","Край тіні"]', 1784690324142);
