INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bo-phong-truy-anh', 'Bổ Phong Truy Ảnh', 'The Shadow''s Edge', 'bổ phong truy ảnh the shadow''s edge thành long trương tử phong lương gia huy văn tuấn huy châu chánh kiệt vương tử dị lâm thu thuần vương trấn vĩ lý triết khôn jackie chan 捕風追影 极盗跟踪 捕风追影 the shadow''s edge a sombra do perigo لبه سایه shadow chase - im netz der diebe operación: sombra bǔ fēng zhuī yǐng край тіні', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-hung-2025', 'Truy Hung', 'Chase The Murderer (Chase The Culprit)', 'https://phimimg.com/upload/vod/20251120-1/3103566acbff8de65304d5a03f5c723d.jpg', 'https://phimimg.com/upload/vod/20251120-1/ff6be3e2e7bd43e417d642decc9850e4.jpg', '<p>Vì bạn mà truy tìm hung thủ, dùng võ chứng đạo. Nữ cảnh sát Giang Mẫn có người bạn thân Trương Như bị tên tài phiệt Từ Phi xâm hại, sau đó còn bị vu oan là “tự sát” và mang tiếng xấu. Giang Mẫn thề phải điều tra đến cùng, từ chối hối lộ, đối đầu sát thủ, trải qua nhiều lần cận kề cái chết để tìm ra nhân chứng then chốt. Cuối cùng, cô một mình xông vào sào huyệt, bắt sống Từ Phi đang định bỏ trốn, buộc hắn phải chịu pháp luật, đồng thời rửa sạch nỗi oan cho bạn mình.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Zhui.Xiong","Zhui Xiong","追凶"]', 1784690324142);
