INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-trai-cua-ngan-nguoi-cha', 'Con Trai Của Ngàn Người Cha', 'The Son Of A Thousand Men', 'https://phimimg.com/upload/vod/20251120-1/6d032c5594d034ac1d371493b9ba799c.jpg', 'https://phimimg.com/upload/vod/20251120-1/11503a050afa1b371fdce379dc22e087.jpg', '<p>Ở một ngôi làng nhỏ, ngư dân cô đơn nọ khao khát có một đứa con trai rồi bị thứ ánh sáng siêu nhiên thu hút, kết nối anh với những người khác và bí mật chôn giấu từ lâu của họ.</p>', 'Full', 1, 'single', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Brazil', 0, '[{"name":"Rodrigo Santoro","avatar":""},{"name":"Rebeca Jamir","avatar":""},{"name":"Miguel Martines","avatar":""},{"name":"Johnny Massaro","avatar":""},{"name":"Marcello Escorel","avatar":""},{"name":"Lívia Silva","avatar":""},{"name":"Antonio Haddad","avatar":""},{"name":"Juliana Caldas","avatar":""},{"name":"Inez Viana","avatar":""},{"name":"Tuna Dwek","avatar":""},{"name":"Grace Passô","avatar":""},{"name":"Carlos Francisco","avatar":""},{"name":"Teka Romualdo","avatar":""},{"name":"Duda Sampaio","avatar":""},{"name":"Gabriel Corasini","avatar":""},{"name":"Augusto Madeira","avatar":""},{"name":"Fernão Zob","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["O Filho de Mil Homens","The Son of a Thousand Men","El hijo de mil hombres","Le Fils de mille hommes","Der Sohn von tausend Männern","Il figlio di mille uomini"]', 1784690324142);
