INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('oan-hon-trong-vali', 'Oán Hồn Trong Vali', 'Rhapsody For The Dead', 'https://phimimg.com/upload/vod/20251120-1/633b70c313df3a227047dc3247794392.jpg', 'https://phimimg.com/upload/vod/20251120-1/7f33402f364d216ac0b752c578ba077c.jpg', '<p>Soo-ah được tìm thấy lạnh lẽo trong chiếc vali…Cái cái chết bất thường tưởng là sự kết thúc nhưng lại là khởi đầu cho một cơn ác mộng kinh hoàng hơn. Linh hồn phẫn uất của cô bị mắc kẹt trong chiếc vali trở về hòng đòi lại công bằng từ hai kẻ thủ ác. Pháp sư trừ tà bí ẩn Anuat có thể ngăn chặn lời nguyền chết chóc này, hay bí mật đen tối của tình yêu, sự phản bội và cái chết sẽ kéo tất cả xuống địa ngục?</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Anupam Tripathi","avatar":""},{"name":"Im Do-hwa","avatar":""},{"name":"Song Seung-hyun","avatar":""},{"name":"Kim Hye-na","avatar":""},{"name":"Gwak Su-jin","avatar":""},{"name":"Seo Dong-won","avatar":""},{"name":"Yoon Jun-won","avatar":""},{"name":"Kim Byung-choon","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["창혼: 구원의 밤","Dark Whispers","검은 령"]', 1784690324142);
