INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('oan-hon-trong-vali', 'Oán Hồn Trong Vali', 'Rhapsody For The Dead', 'oán hồn trong vali rhapsody for the dead anupam tripathi im do-hwa song seung-hyun kim hye-na gwak su-jin seo dong-won yoon jun-won kim byung-choon 창혼: 구원의 밤 dark whispers 검은 령', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('son-than-di-van-luc', 'Sơn Thần Dị Văn Lục', 'Mountain Deity (Vengeance Of The Mountain God)', 'https://phimimg.com/upload/vod/20251106-1/08501427f4ac3290ad55466988352770.jpg', 'https://phimimg.com/upload/vod/20251106-1/746ada70eccfae53be16312a0cf5fe61.jpg', '<p>Kim Thập Tam là con nuôi của lão sơn trưởng Kim Bất Hoán, từ nhỏ đã học được tuyệt kỹ tìm và nhận biết nhân sâm. Ba năm trước, trong Đại hội tìm nhân sâm, toàn bộ gia tộc họ Kim bị kẻ gian bày mưu hãm hại, chết thảm dưới tay đối thủ. Kim Thập Tam may mắn sống sót, nhưng trọng thương và bị bắt làm “huyết nô”. Sau những năm tháng chịu đựng tra tấn tàn khốc, anh cuối cùng cũng trốn thoát khỏi địa ngục trần gian. Ba năm sau, Kim Thập Tam quay lại dãy núi Quan Đông, âm thầm bày mưu tính kế, thề phải tự tay giết hết kẻ thù để rửa mối huyết hận năm xưa...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hoàng Tuấn Tiệp","avatar":""},{"name":"Đinh Tiếu Oánh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Shan Shen Yi Wen Lu","山神","Mountain Deity","山神异闻录"]', 1784690324142);
