INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-chat-chau-a', 'Thể Chất: Châu Á', 'Physical: Asia', 'https://phimimg.com/upload/vod/20251030-1/4e49fc2dbf48de955afefc015b7df0c8.jpg', 'https://phimimg.com/upload/vod/20251030-1/413c9587bd01f63470b1355f2887accf.jpg', '<p>Các vận động viên xuất sắc nhất châu Á tham gia vào một cuộc tranh tài đầy kịch tính, nơi sức mạnh thể chất, ý chí và niềm tự hào dân tộc được đẩy lên đến đỉnh điểm. Họ chiến đấu hết mình vì vinh quang quốc gia, và cuối cùng — chỉ có một lá cờ được tung bay chiến thắng.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Robert Whittaker","avatar":""},{"name":"Dominic Di Tommaso","avatar":""},{"name":"Eloni Vunakece","avatar":""},{"name":"Katelin van Zyl","avatar":""},{"name":"Eddie Williams","avatar":""},{"name":"Alexandra Milne","avatar":""},{"name":"Manny Pacquiao","avatar":""},{"name":"Mark Mugen","avatar":""},{"name":"Ray Jefferson Querubin","avatar":""},{"name":"Justin Coveney","avatar":""},{"name":"Robyn Lauren Brown","avatar":""},{"name":"Lara Lorraine Daeng Liwanag","avatar":""},{"name":"Kim Dong-Hyun","avatar":""},{"name":"Kim Min-Jae","avatar":""},{"name":"Amotti","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Physical: 100 3 , Physical: 100 Season 3 , Pijikeol: 100 3 , Pijikeol: 100 Sijeun 3 , 피지컬: 100 시즌3","En Güçlü: Asya","Physical: Asia","피지컬: 아시아"]', 1784690324142);
