INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-tien-len-cua-nu-y', 'Hành Trình Tiến Lên Của Nữ Y', 'Rise Of Her Lady Physician', 'https://phimimg.com/upload/vod/20251102-1/a0438d00a2794f4771dccea5d0b5b6ff.jpg', 'https://phimimg.com/upload/vod/20251102-1/374a8d19880074f3c0619849d8037083.jpg', '<p>Vì một vụ án oan, Dung Trạch Lan đơn độc bước chân vào chốn hoàng cung, thề rằng sẽ mở ra con đường sống trong Thái Y Viện – nơi vốn do đàn ông thống trị. Đối mặt với sự khinh thường và chế giễu của các ngự y nam giới, nàng dùng y thuật làm vũ khí, kiên cường tiến bước nghịch cảnh: chữa bệnh cho Thái tử, cứu sống Thái hậu, dập tắt dịch bệnh. Với công lao cứu dân, Dung Trạch Lan trở thành nữ quan đầu tiên trong triều đình, buộc những kẻ từng khinh miệt phải cúi đầu thán phục — viết nên huyền thoại truyền cảm hứng về người phụ nữ “bước lên bàn tiệc của quyền lực”.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hồng Tiêu","avatar":""},{"name":"Dương Trạch","avatar":""},{"name":"Thẩm Chi Dịch","avatar":""},{"name":"Từ Tử Tuyền","avatar":""},{"name":"Triệu Khởi Nguyệt","avatar":""},{"name":"Tô Kỳ An","avatar":""},{"name":"Từ Tử Nhân","avatar":""},{"name":"Dương Thư Diệc","avatar":""},{"name":"Lãnh Luyến Nhu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Doctor''s Attack","女医进击录"]', 1784690324142);
