INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hay-hen-ho-voi-ban-toi-di', 'Hãy Hẹn Hò với Bạn Tôi Đi!', 'Date My Friend', 'https://phimimg.com/upload/vod/20250815-1/3876aaa3410d244e4825f61f6045f6ab.jpg', 'https://phimimg.com/upload/vod/20250815-1/f8e9fba9afc919da6ee160f9355eea59.jpg', '<p>Một chương trình hẹn hò “có một không hai” khi chính các ngôi sao vào vai mai mối, giới thiệu bạn bè thật của mình để tìm kiếm tình yêu. Hãy cùng chứng kiến những khoảnh khắc ngượng ngùng, những cú “thả thính” bất ngờ và những tín hiệu tình cảm lẫn lộn khiến cả người trong cuộc lẫn khán giả phải thót tim. Liệu bạn có hẹn hò với… bạn của tôi?</p>', 'Hoàn Tất (8/8)', 8, 'tvshows', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jo Se-ho","avatar":""},{"name":"Kang So-ra","avatar":""},{"name":"Kim Nam-hee","avatar":""},{"name":"Heo Young-ji","avatar":""},{"name":"Lee Mi-joo","avatar":""},{"name":"Ji Ye-eun","avatar":""},{"name":"김영광","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["真的是很不错的人","Date My Friend","진짜 괜찮은 사람"]', 1784690324142);
