INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khmer-do', 'Khmer Đỏ', 'Red Khmer', 'https://phimimg.com/upload/vod/20250702-1/9f0429257af6e70d645a8dba33a89354.jpg', 'https://phimimg.com/upload/vod/20250702-1/4197fba9cd1ad05d5ec61753221c0f6c.jpg', '<p>Có những lằn ranh được vẽ trên bản đồ, và có những lằn ranh trong tâm hồn. Năm 1977, tại biên giới Tây Nam, cả hai lằn ranh đó đều bị xé toạc bởi máu. Một cuộc thảm sát man rợ của quân Khmer Đỏ biến một ngôi làng yên bình thành địa ngục trần gian chỉ trong một đêm. Từ đống tro tàn, thầy giáo Lâm, người chứng kiến vợ con bị sát hại, đã phải chôn cất trái tim của một nhà giáo để khơi dậy bản năng của một kẻ đi săn. Cùng với Út, chàng nông dân trẻ buộc phải cầm súng để bảo vệ những gì cuối cùng còn sót lại, họ trở thành những người sống sót không mong muốn trong cuộc chiến không thuộc về mình.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Tonny Việt","avatar":""},{"name":"Lê Minh Thuấn","avatar":""},{"name":"Nguyễn Gia Bảo","avatar":""},{"name":"Tống Yến Nhi","avatar":""},{"name":"Nguy. Đức Huy","avatar":""},{"name":"Hoa Thảo","avatar":""},{"name":"Cao Thùy Linh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324142);
