INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tay-hanh-ky-dai-vien-hon', 'Tây Hành Kỷ: Đại Viên Hồn', 'The Westward: Wukong', 'tây hành kỷ: đại viên hồn the westward: wukong chang xu 灯果 yang ou huang ji bu yi zhu jun fu gui ajie da yuan hun 西行纪之大猿魂 wu kong 西行纪: 大猿魂 xi xing ji: da yuan hun xixing ji: wukong journey to the west: great ape soul xixing ji: da yuan hun xi xing ji - da yuan hun xi xing ji zhi da yuan hun 西行纪系列 西行纪大猿魂漫画 西行纪之妖怪道 西游3：妖怪道 西行纪之大猿魂_系列 the westward: wukong the westward: da yuan hun 大猿魂', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ta-la-dao-tong', 'Ta Là Đao Tông', 'I Am The Blade', 'https://phimimg.com/upload/vod/20250725-1/98fde2db0a6d463590924d0c401ccfe3.jpg', 'https://phimimg.com/upload/vod/20250725-1/8e383a9e0066ee11ffc1d8aa745cb57a.jpg', '<p>Trong một âm mưu giang hồ, Tông chủ Đao Tông – võ lâm chí tôn – bị sát hại, các thủ lĩnh bang phái lớn hoặc bỏ mạng, hoặc rơi vào vòng lao ngục, khiến giang hồ rơi vào hỗn loạn. Để tái lập trật tự võ lâm, Yến Ký Vũ – các chủ Trường Phong Các – cử sứ giả đến các môn phái, mưu đồ xây dựng một võ lâm “chính khí” do hắn đứng đầu. Trong lúc đó, Dương Nhận – một kẻ vừa bước chân vào giang hồ – nhận ủy thác đưa đi bức thư do Đao Tông để lại. Dọc đường, kẻ địch rình rập, hiểm nguy trùng trùng, nhưng anh nhờ nhiệt huyết và nghĩa hiệp mà không ngừng vượt qua bản thân, đánh bại đối thủ, võ công tiến bộ vượt bậc, đồng thời kết giao được nhiều người hào hiệp chính nghĩa. Giang hồ nên là nơi như thế nào? Dương Nhận không có câu trả lời, nhưng anh biết chắc chắn đó không phải là thứ giang hồ “chính khí” mà Yến Ký Vũ tạo ra. Dương Nhận dựng lá cờ “Thừa Phong Bang”, nhanh chóng quy tụ những người phản đối Yến Ký Vũ. Đại chiến sắp nổ ra, không ai có thể đứng ngoài. Sau cái chết của Đao Tông, giang hồ đã chia cắt bấy lâu, nay sẽ được khâu lại với sự xuất hiện của tân Đao Tông.</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 11, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Wo Wei Dao Zong","天下刀宗","我为刀宗动画","The Blade Master","I am the Blade","我为刀宗"]', 1784690324142);
