INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thai-co-chien-hon', 'Thái Cổ Chiến Hồn', 'Ancient War Soul / Tai Gu Zhan Hun', 'https://phimimg.com/upload/vod/20250520-1/49aa1d4a07451b524c3d6d82f3e6b40f.jpg', 'https://phimimg.com/upload/vod/20250520-1/8fc321e71315997e7d07d0e9892efdfb.jpg', '<p>Võ Đế một thời bị kẻ xấu hại nên đã bỏ mạng. Vạn năm sau trùng sinh vào một thiếu niên tên Tần Phong, một thiếu niên bình thường nhưng lại có số mệnh gian truân nghiệt ngã. Thức tỉnh thần hồn vô thượng, tu luyện võ đạo vô thượng. Sóng gió ập tới, hắn trai tài cùng vô số thiên kiêu. Một thời gian sau Tần Phong trở thành một huyền thoại anh hùng, chư thiên vạn giới đều phải run rẩy vì sợ trở lại của hắn.</p>', 'Hoàn Tất (40/40)', 40, 'hoathinh', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Yi Qiu","avatar":""},{"name":"Tang Yuhe","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Tai Gu Zhan Hun","太古战魂","神魂武尊","太古戰魂","จิตวิญญาณการต่อสู้บรรพกาล","Ancient War Soul","Thái Cổ Chiến Hồn"]', 1784690324142);
