INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thai-co-chien-hon', 'Thái Cổ Chiến Hồn', 'Ancient War Soul / Tai Gu Zhan Hun', 'thái cổ chiến hồn ancient war soul / tai gu zhan hun yi qiu tang yuhe tai gu zhan hun 太古战魂 神魂武尊 太古戰魂 จิตวิญญาณการต่อสู้บรรพกาล ancient war soul thái cổ chiến hồn', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-huynh-cua-ta-qua-manh', 'Sư Huynh Của Ta Quá Mạnh', 'My Senior Brother is Too Strong', 'https://phimimg.com/upload/vod/20250413-1/2b0f01521e0763f272c5c672d433fb48.jpg', 'https://phimimg.com/upload/vod/20250413-1/fc59b97bb739a6dbf325f0e151b4b202.jpg', '<p>Trong thế giới tu chân đầy tranh đấu, Lữ Thiếu Khanh vô tình có được nhẫn Xuân Thu – một tiên bảo khiến hắn bị liên minh tiên chính đạo gán cho danh ma đầu diệt thế và truy sát đến cùng. Hắn mang ý chí kiên định, bất ngờ xuyên không về ngàn năm trước, nhập vào thân xác kẻ từng hạ sát anh, buộc phải sống sót giữa hang ổ địch. Để tồn tại, hắn vừa đấu trí giành quyền kiểm soát cơ thể, vừa lén lút thu thập dị bảo trước mũi kẻ thù. Cuối cùng, qua những trận chiến khốc liệt và mưu mẹo tài tình, Lữ Thiếu Khanh trở thành tay chơi đệ nhất chính đạo mà ai cũng ghét, đồng thời mở ra những bí ẩn sâu xa của giới tu chân.</p>', 'Hoàn Tất (48/48)', 48, 'hoathinh', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yang Jinhan","avatar":""},{"name":"Yi Qiu","avatar":""},{"name":"Wang Xiaoyue","avatar":""},{"name":"Li Hanlin","avatar":""},{"name":"Zhang Wenjie","avatar":""},{"name":"沈话桑","avatar":""},{"name":"Sun Xihe","avatar":""},{"name":"薄棠","avatar":""},{"name":"Zhengjian Hu","avatar":""},{"name":"赵哲豪","avatar":""},{"name":"张胡子","avatar":""},{"name":"阮伊菲","avatar":""},{"name":"翁家明","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["我的师兄太强了之波云诡谲篇","我的师兄太强了之群雄逐鹿篇","Wo De Shi Xiong Tai Qiang Le","我的师兄太强了","My Senior Brother is Too Strong"]', 17846