INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('su-huynh-cua-ta-qua-manh', 'Sư Huynh Của Ta Quá Mạnh', 'My Senior Brother is Too Strong', 'sư huynh của ta quá mạnh my senior brother is too strong yang jinhan yi qiu wang xiaoyue li hanlin zhang wenjie 沈话桑 sun xihe 薄棠 zhengjian hu 赵哲豪 张胡子 阮伊菲 翁家明 我的师兄太强了之波云诡谲篇 我的师兄太强了之群雄逐鹿篇 wo de shi xiong tai qiang le 我的师兄太强了 my senior brother is too strong', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-menh-dai-chua-te', 'Thiên Mệnh Đại Chúa Tể', 'The Destiny Ruler', 'https://phimimg.com/upload/vod/20250411-1/64cbeb1669cdb78a6d348f01988e0a33.jpg', 'https://phimimg.com/upload/vod/20250224-1/b9795e242ef5396835ea66e31de62410.jpg', '<p>Khám phá bộ phim Thiên Mệnh Đại Chúa Tể, một tác phẩm đầy hấp dẫn với câu chuyện về cuộc đối đầu giữa Đại Hạ Thần Châu và chính tà từ thời khai thiên lập địa. Trải qua hàng trăm năm, thế lực ma môn ngày càng mạnh mẽ, khiến cho các tông môn chính đạo phải gồng mình để chống lại. Lý Vạn Niên, một thiếu niên bình thường nhưng sở hữu sức mạnh bất tử, đã bắt đầu hành trình tu luyện và trở thành người có tu vi vô cùng cao cả. Hãy cùng theo dõi peripeteia của nhân vật này trong cuộc chiến giữa ác và thiện, với sự tham gia của dàn diễn viên xuất sắc và kịch tính.</p>', 'Hoàn Tất (40/40)', 40, 'hoathinh', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Tian Ming Da Zhu Zai","Tinming Da Zhuzhai","Tianming Da Zhuzhai","天命大主宰","Lord of Destiny","God of Destiny","The Destiny Lord","The Destiny Ruler"]', 1784690324142);
