INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gau-truc-va-ban-lan-den-day', 'Gấu Trúc Và Bạn, Lăn Đến Đây!', 'Panda & You Rolling In', 'https://phimimg.com/upload/vod/20251027-1/b468446f14f18657e2117718b127d8da.jpg', 'https://phimimg.com/upload/vod/20251027-1/68928c2511a0ce76923be79beb32476d.jpg', '<p>&quot;Gấu Trúc Và Bạn, Lăn Đến Đây!&quot; là bộ phim ngắn nhẹ nhàng, hài hước, giúp giải tỏa căng thẳng đầu tiên lấy bối cảnh tại căn cứ gấu trúc. Bộ phim kể về cô gái 27 tuổi tên Lưu Liễu, sau khi bị công ty lớn cắt giảm nhân sự, trong lúc chán nản đã bất ngờ nhận được một công việc tạm thời trong ba tháng tại căn cứ gấu trúc với vị trí nhân viên truyền thông mới. Ban đầu cô chỉ định &quot;nằm im nghỉ ngơi&quot; cho qua giai đoạn, nhưng lại gặp phải nhà nghiên cứu lạnh lùng Tạ Đạo Uẩn, mở đầu cho chuỗi &quot;kiếp nạn chốn công sở&quot;. Rời xa ồn ào đô thị, giữa núi rừng yên tĩnh, dưới sức chữa lành đáng yêu của &quot;Bão Bão&quot; (tên gấu trúc, tên gốc là &quot;Nhất Gia&quot;, được đặt trong lễ đặt tên của đoàn giao lưu thanh niên &quot;Bốn Biển Một Nhà·Xuyên Cảng Đồng Hành&quot;, mang ý nghĩa tinh thần bao dung và hòa hợp), cả hai từ cặp thầy trò thiếu ăn ý dần trở thành những cộng sự hợp rơ nhất. Cuối cùng, Lưu Liễu cũng nhận ra rằng cuộc sống luôn nở hoa trong những khoảnh khắc ta không ngờ tới.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hoàng Tinh Tinh","avatar":""},{"name":"Vương Hưng Vy","avatar":""},{"name":"Triệu Viên Viên","avatar":""},{"name":"Nhậm Vũ","avatar":""},{"name":"Tạ Bội Phi","avatar":""},{"name":"La Kỳ Mộc Dĩ","avatar":""},{"name":"Từ Dương","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Xiong Mao Yu Ni Gun Gun Er Lai","Panda & You Rolling in","熊猫与你，滚滚而来！"]', 1784690324142);
