INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phuong-hoang-truyen', 'Phượng Hoàng Truyện', 'Her Phoenix Majesty', 'https://phimimg.com/upload/vod/20251106-1/b685cde56d6f8765fbe2773762c70a69.jpg', 'https://phimimg.com/upload/vod/20251106-1/91edac10bd2a3133473dbb103cabdced.jpg', '<p>Thư sinh Tạ Uyên trong chuyến du ngoạn thiên hạ, tình cờ lạc vào một quốc gia theo chế độ nhất thê đa phu, nơi nữ tử nắm quyền tuyệt đối. Do sở hữu dung mạo xuất chúng, chàng lọt vào mắt xanh của Trưởng công chúa và bị cưỡng ép đưa vào cung, bắt phải thành hôn và trở thành nam sủng của nàng. Không chịu khuất phục, Tạ Uyên bày mưu trốn chạy, nhưng trên đường chạy trốn lại được Nhị công chúa xinh đẹp và lương thiện ra tay giúp đỡ. Tưởng rằng đó chỉ là một cuộc gặp gỡ tình cờ, nào ngờ chàng lại bị cuốn vào vòng xoáy âm mưu và tranh đấu chốn cung đình...</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Hác","avatar":""},{"name":"Quan Tâm","avatar":""},{"name":"Ngô Dạ Lộ","avatar":""},{"name":"Hồ Thải Hồng","avatar":""},{"name":"Dương Đào","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Feng Huang Zhuan","Phoenix Legend","凤皇传"]', 1784690324142);
