INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phuong-hoang-truyen', 'Phượng Hoàng Truyện', 'Her Phoenix Majesty', 'phượng hoàng truyện her phoenix majesty trương hác quan tâm ngô dạ lộ hồ thải hồng dương đào feng huang zhuan phoenix legend 凤皇传', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-nguyet-lenh', 'Cẩm Nguyệt Lệnh', 'Moonlit Order', 'https://phimimg.com/upload/vod/20251028-1/54c5c8fa9127aa22fc5f7cd3ae174ef2.jpg', 'https://phimimg.com/upload/vod/20251028-1/e36daa622f6cad5b004b800d727c33aa.jpg', '<p>Thủ lĩnh của cơ quan mật vụ Tuyết Y Vệ, Phượng Tác Nhân, nhận lệnh của Hoàng đế Gia thâm nhập vào phủ Định Viễn Hầu để truy tìm thái tử tiền triều, với mục đích “nhổ cỏ tận gốc”.&nbsp; Tuy nhiên, trong quá trình điều tra, Phượng Tác Nhân dần phát hiện ra rằng — phía sau Hoàng đế còn có một thế lực khác đang giăng bẫy, che giấu một âm mưu to lớn hơn rất nhiều…</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hà Ni Kỳ","avatar":""},{"name":"Hoàng Tuấn Kiệt","avatar":""},{"name":"Nghiêm Tử Hiền","avatar":""},{"name":"Vương Minh Dương","avatar":""},{"name":"Chu Dung Quân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jin Yue Ling","锦月令"]', 1784690324142);
