INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cam-nguyet-lenh', 'Cẩm Nguyệt Lệnh', 'Moonlit Order', 'cẩm nguyệt lệnh moonlit order hà ni kỳ hoàng tuấn kiệt nghiêm tử hiền vương minh dương chu dung quân jin yue ling 锦月令', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngu-tien-quy-su-luc', 'Ngũ Tiên Quỷ Sự Lục', 'Tales Of Five Immortals', 'https://phimimg.com/upload/vod/20251026-1/4c9273d06b51ce4aa3eb5f01bcb25749.jpg', 'https://phimimg.com/upload/vod/20251026-1/6a3249cdc34d3fbdb7bffa42b3672a7a.jpg', '<p>Thời dân quốc loạn lạc, cậu bé mồ côi Lai Phúc phải lưu lạc chốn giang hồ vì gia tộc bị Hồ tiên tàn sát. Trong thời gian nương náu ở ngôi miếu đổ nát, cậu học được dị thuật và trở thành một thuật sĩ ngao du bốn bể. Mười năm sau, Lai Phúc bắt đầu kế hoạch báo thù bằng cách việc phá giải vụ án “Hoàng tiên rước dâu”. Nhưng từ đây, cậu lại bị cuốn vào vòng xoáy ân oán chốn hào môn của vị hôn phu bí ẩn Bạch tiểu thư. Thành phố Cáp Nhĩ Tân xảy ra hàng loạt vụ án kì bí, nghi hoặc trùng trùng. Lai Phúc phối hợp cùng cảnh sát Cố để phá án. Không ngờ, khi nhận người thân ở Bạch phủ đã phanh phui một bí mật chấn động: Kẻ chủ mưu đứng sau vụ án “Hôi tiên đoạt xác” lại chính là kẻ phản đồ ở Chu phủ đã sát hại sư phụ năm xưa! Lai Phúc liên thủ cùng cảnh sát Cố phá tan pháp trận tà ác “Bạch tiên cải vận”. Trong trận quyết chiến sinh tử, cậu đã vạch trần âm mưu phản quốc của ông chủ đoàn xiếc ảo thuật thông đồng với quân Nhật, dùng tà linh ngũ hành để giúp quân địch gia tăng vận khí.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cao Khải","avatar":""},{"name":"Trần Mỹ Diên","avatar":""},{"name":"Trương Uyển Lâm","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wu Xian Gui Shi Lu","The Strange Stories of the Five Immortals","五仙诡事录"]', 1784690324142);
