INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngu-tien-quy-su-luc', 'Ngũ Tiên Quỷ Sự Lục', 'Tales Of Five Immortals', 'ngũ tiên quỷ sự lục tales of five immortals cao khải trần mỹ diên trương uyển lâm wu xian gui shi lu the strange stories of the five immortals 五仙诡事录', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-the-cuc-cu-phan-2', 'Hôn Thê Cúc Cu (Phần 2)', 'A Couple Of Cuckoos (Season 2)', 'https://phimimg.com/upload/vod/20250824-1/de3e35108db96508b9e72d4331f93835.jpg', 'https://phimimg.com/upload/vod/20250824-1/65ccd3c9a4b8388d6a102973f995c804.jpg', '<p>Mùa 2 của Cặp Đôi Cuckoo (2025) tiếp tục câu chuyện tình cảm rắc rối giữa Nagi và Erika khi họ vừa là hôn phu sắp đặt vừa sống chung một nhà. Sự trở lại của bạn thuở nhỏ Mochizuki Ai và sự xuất hiện của những tình địch mới khiến mối quan hệ biến thành “ngũ giác tình yêu”, đầy hiểu lầm, cạnh tranh và cả những khoảnh khắc ngọt ngào khó đoán.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kaito Ishikawa","avatar":""},{"name":"Akari Kito","avatar":""},{"name":"Nao Toyama","avatar":""},{"name":"Konomi Kohara","avatar":""},{"name":"Hina Youmiya","avatar":""},{"name":"Ryohei Kimura","avatar":""},{"name":"Yoko Hikasa","avatar":""},{"name":"Toshiyuki Morikawa","avatar":""},{"name":"Yukiko Aruga","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Cuckoo no Iinazuke","杜鹃婚约","Kakkō no Iinazuke","Kakkou no Iinazuke","Kakkou no Iinazuke (A Couple of Cuckoos)","뻐꾸기 약혼자","A Couple of Cuckoos","カッコウの許嫁"]', 1784690324142);
