INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hon-the-cuc-cu-phan-2', 'Hôn Thê Cúc Cu (Phần 2)', 'A Couple Of Cuckoos (Season 2)', 'hôn thê cúc cu (phần 2) a couple of cuckoos (season 2) kaito ishikawa akari kito nao toyama konomi kohara hina youmiya ryohei kimura yoko hikasa toshiyuki morikawa yukiko aruga cuckoo no iinazuke 杜鹃婚约 kakkō no iinazuke kakkou no iinazuke kakkou no iinazuke (a couple of cuckoos) 뻐꾸기 약혼자 a couple of cuckoos カッコウの許嫁', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-cam-do-moi-tinh-bao-thu', 'Trò Chơi Cám Dỗ: Mối Tình Báo Thù', 'The Infidelity Queen', 'https://phimimg.com/upload/vod/20251118-1/956364183c4ac39dd7ab5afe2b5b3dfd.jpg', 'https://phimimg.com/upload/vod/20251118-1/1be72cad9243ba9de5e41feb8fc883f4.jpg', '<p>Sarang, một người phụ nữ chuyên quyến rũ chồng người khác để phá hoại gia đình, nhận nhiệm vụ từ một luật sư để quyến rũ chồng của Jin Kyung, con gái độc nhất Tập đoàn Daejin.Sarang nhận lời vì Jin Kyung chính là người đã đánh tráo và cướp đi thân phận giàu có của cô 15 năm trước.Sarang giả làm người giúp việc để tiếp cận Young Won (chồng Jin Kyung), nhưng cô dần nảy sinh tình cảm thật sự với anh, trong khi phát hiện Jin Kyung đang ngược đãi Young Won.Bị mắc kẹt giữa âm mưu trả thù, tình yêu chân thật và luật lệ thừa kế, Sarang quyết định hành động để lấy lại cuộc đời mình và giải thoát cho Young Won.</p>', 'Hoàn Tất (47/47)', 47, 'series', 'completed', 29, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phim Ngắn","slug":"phim-ngan","id":"4f02d28224c0747511790d57fbb63a62"}]', '[]', 1784690324142);
