INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('de-linh-yeu-mac-thuy-linh-lung', 'Đế Linh Yêu Mặc Thuỷ Linh Lung', 'Divine Love Deep Blue', 'https://phimimg.com/upload/vod/20250802-1/4f7f04c688a3d3e2bfb6bde6eb796296.jpg', 'https://phimimg.com/upload/vod/20250802-1/30f12e6c13f801fd2146913879f4409b.jpg', '<p>Câu chuyện bắt đầu từ thuở xa xưa, khi mà vạn vật trên đời này đều sở hữu những nguồn sức mạnh và ý thức của riêng mình, dù là nhỏ nhoi và ít ỏi, nhưng gộp chung lại thì chúng tạo ra những thực thể với sức mạnh và ý thức vô cùng to lớn, có thể gọi đó là những tiên tử. Nhưng tiên tử cũng đang bị đe dọa bởi sự cuồng vọng của con người, và thêm với việc lớp phong ấn của một thứ sinh mạnh kỳ bí đang dần bị phá hỏng, các tiên tử dần chịu cảnh thương tổn không ít. Trong khi đó thì một nữ nhân lại vô tình gặp được một tiên tử, họ nảy sinh rất nhiều thứ tình cảm với nhau, mà ta có thể gọi đó chính là tình yêu, nhưng rào cản giữa tiên và người đã dần ngăn cách họ. Vô cùng đau buồn vì sự thực nghiệt ngã ấy, nữ nhân kia đã quyết tâm lên đường để chinh phục những thứ sức mạnh mới cho bản thân, tìm ra bản ngã cho riêng mình, bởi cô luôn có một chấp niệm rằng con người cũng là một phần của tự nhiên, cũng như việc cô và tiên tử vẫn có thể tìm ra cách thức để chung sống với thứ tình cảm thiêng liêng của mình.</p>', 'Tập 20', 24, 'hoathinh', 'ongoing', 10, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["缔灵爱之默水玲珑"]', 1784690324142);
