INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-cam-ky-2025', 'Tình Yêu Cấm Kỵ', 'A Love That Shouldn''t Be', 'https://phimimg.com/upload/vod/20251118-1/803d71e97b19e9255d9bd832e3e9eac0.jpg', 'https://phimimg.com/upload/vod/20251118-1/f06e458f440229059d38291f0cffa4e7.jpg', '<p>Sau cái chết đột ngột của chồng, Seoah đóng cửa ru rú trong nhà, đoạn tuyệt với thế giới bên ngoài. Một ngày nọ, Taejun, nhà đầu tư cũ của chồng cô tìm đến, đòi cô trả một khoản nợ khổng lồ. Seoah tức giận lên án đùn đẩy nợ nần cho người đã khuất là hành động đê tiện, nhưng Taejun không buồn để tâm, vẫn xuất hiện hết lần này đến lần khác, cứu giúp cô khỏi tình trạng suy sụp. Thực ra, Taejun là anh trai của người tình của chồng Seoah. Tất cả đều là kế hoạch trả thù của Taejun: trả thù chồng Seoah vì đã hủy hoại cuộc đời em gái mình. Gánh trên mình vô số lý do &quot;không nên yêu&quot;, đôi nam nữ vẫn bị thu hút bởi nhau, không tài nào cưỡng lại.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 31, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phim Ngắn","slug":"phim-ngan","id":"4f02d28224c0747511790d57fbb63a62"}]', '[]', 1784690324142);
