INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-nho-theo-gio-bac', 'Nỗi Nhớ Theo Gió Bắc', 'Yi Yi Xiang Bei Feng', 'https://phimimg.com/upload/vod/20251027-1/754719e6ed5f7acf96e5b1bc20f3f104.jpg', 'https://phimimg.com/upload/vod/20251027-1/dfcc191f80148ab421be1e79af6237ce.jpg', '<p>Những năm 1970, tại thành phố Lương Xuyên, một nhóm thanh niên trí thức đã gắn bó sâu sắc với nhau trong thời gian đi lao động ở nông thôn. Sau khi trở về thành phố, họ cùng nhau trải qua những làn sóng lớn của thời đại, từ kỳ thi đại học đến công cuộc cải cách mở cửa. Mỗi người đã bước đi trên một con đường đời khác nhau. Hai nhân vật chính, Du Nhạc Sơn và Thịnh Tuyết Trúc, bằng ý chí và nỗ lực không ngừng, đã vượt qua muôn vàn thử thách để cuối cùng đạt được lý tưởng của cuộc đời mình.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Quan Nhận Tư","avatar":""},{"name":"Lỗ Nô","avatar":""},{"name":"Hà Minh Hán","avatar":""},{"name":"Trương Khả Anh","avatar":""},{"name":"Lâm Gia Xuyên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yi Yi Xiang Bei Feng","依依向北风"]', 1784690324142);
