INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('noi-nho-theo-gio-bac', 'Nỗi Nhớ Theo Gió Bắc', 'Yi Yi Xiang Bei Feng', 'nỗi nhớ theo gió bắc yi yi xiang bei feng quan nhận tư lỗ nô hà minh hán trương khả anh lâm gia xuyên yi yi xiang bei feng 依依向北风', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phao-hoa-huong-toi-cac-vi-sao', 'Pháo Hoa Hướng Tới Các Vì Sao', 'Fireworks Stars', 'https://phimimg.com/upload/vod/20251117-1/8c76b629a587025e49acbbc08076b97c.jpg', 'https://phimimg.com/upload/vod/20251117-1/eebe1b1eea34dea91869f4384260d80a.jpg', '<p>Câu chuyện kể về Lý Thượng (người thừa kế nổi loạn của một gia tộc làm pháo hoa) và Lật Tử (cô chủ quán cà phê trở về quê hương khởi nghiệp), từ mối tình đầu ngây thơ đến những xung đột với thực tế.Lý Thượng rời bỏ gia tộc để đến thành phố tìm kiếm tự do nhưng liên tiếp thất bại. Lật Tử, sau khi bị bắt nạt nơi công sở, quyết định về quê mở quán cà phê nổi tiếng trên mạng xã hội.Khi họ tái ngộ, Lý Thượng đang đối mặt với nguy cơ phá sản của nhà máy pháo hoa, còn Lật Tử tập trung phát triển sự nghiệp livestream. Giữa sự giao thoa của nghệ thuật truyền thống và xu hướng hiện đại, họ cùng nhau gánh vác sứ mệnh bảo tồn văn hóa pháo hoa ngàn năm tuổi.Sau khi trải qua hàng loạt thử thách như nghiên cứu gặp bế tắc, đứt gãy vốn, và cám dỗ hôn nhân môn đăng hộ đối, Lý Thượng đã lấy cảm hứng từ núi Dương Kỳ để thiết kế loại pháo hoa văn hóa gây chấn động giới chuyên môn. Trong khi đó, Lật Tử dùng sức mạnh của livestream để giúp ngành công nghiệp này vươn ra thế giới.Cuối cùng, khi những chùm pháo hoa rực rỡ khắc họa lời cầu hôn lên bầu trời đêm, cặp đôi này đã hòa quyện sự trưởng thành cá nhân, sự kế thừa gia tộc và tình yêu nồng cháy thành những đốm lửa tuyệt đẹp, chiếu sáng quê hương huyện Thượng Lật.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Giang Lăng Vân","avatar":""},{"name":"Lạc Tư Thước","avatar":""},{"name":"Lý Minh Hoàn","avatar":""},{"name":"Chu Dương Vũ Lộ","avatar":""},{"name":"Lưu Tuấn Du","avatar":""},{"name":"Trương Hạo Đình","avatar":""},{"name":"Lý Nghiên Từ","avatar":""},{"name":"Trần Nghiêm Hạo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yan Huo Xiang Xing Chen","烟火向星辰"]', 1784690324142);
