INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phao-hoa-huong-toi-cac-vi-sao', 'Pháo Hoa Hướng Tới Các Vì Sao', 'Fireworks Stars', 'pháo hoa hướng tới các vì sao fireworks stars giang lăng vân lạc tư thước lý minh hoàn chu dương vũ lộ lưu tuấn du trương hạo đình lý nghiên từ trần nghiêm hạo yan huo xiang xing chen 烟火向星辰', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('colorful-stage-mot-miku-khong-the-hat', 'Colorful Stage!: Một Miku Không Thể Hát', 'COLORFUL STAGE! The Movie: A Miku Who Can''t Sing', 'https://phimimg.com/upload/vod/20251117-1/a8b15f7e2db757c60a31cfaa1092c765.jpg', 'https://phimimg.com/upload/vod/20251117-1/abecbfa6f16187a1da3d5c2452effd68.jpg', '<p>Phim xoay quanh Ichika Hoshino, người nghe được một bài hát của Miku mà cô chưa bao giờ được nghe cũng như nhìn thấy một Hatsune Miku mà cô chưa từng được thấy. Ngay lúc này, Ichika đã gọi Miku và khi Miku nghe được giọng nói thì cô ấy đã biến mất ngay sau khi hai người chạm mắt. Từ lúc này, Miku bắt đầu xuất hiện trên điện thoại của Ichika và mong muốn truyền đạt bài hát của mình đến với mọi người, nhưng dù Miku có hát bao nhiêu, những bài hát ấy vẫn không thể được truyền tải. Sau khi thấy Ichika chạm đến trái tim mọi người qua một màn trình diễn trên đường phố, Miku đã quyết định nhờ Ichika giúp đỡ.&nbsp;</p>', 'Full', 1, 'single', 'completed', 21, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 1, '[{"name":"Saki Fujita","avatar":""},{"name":"Asami Shimoda","avatar":""},{"name":"Yuu Asakawa","avatar":""},{"name":"Meiko Haigou","avatar":""},{"name":"Naoto Fuuga","avatar":""},{"name":"Ruriko Noguchi","avatar":""},{"name":"Karin Isobe","avatar":""},{"name":"Reina Ueda","avatar":""},{"name":"Yuki Nakashima","avatar":""},{"name":"Yui Ogura","avatar":""},{"name":"Mayu Yoshioka","avatar":""},{"name":"Ai Furihata","avatar":""},{"name":"Rina Honnizumi","avatar":""},{"name":"Akina","avatar":""},{"name":"Tomomi Jiena Sumi","avatar":""},{"name":"Fumiya Imai","avatar":""},{"name":"Kent Ito","avatar":""},{"name":"Daisuke Hirose","avatar":""},{"name":"Hina Kino","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Gekijōban Project Sekai: Kowareta Sekai to Utaenai Miku","Gekijouban Project Sekai: Kowareta Sekai to Utaenai Miku","The Broken World and a Miku Who Can''t Sing","Kowareta SEKAI To Utaenai MIKU","Colorful Stage la película: Miku no puede cantar","剧场版 世界计划 崩坏的世界与无法歌唱的初音未来","劇場版 世界計畫 崩壞的世界與無法歌唱的初音未來","Project Sekai: Kowareta Sekai to Utaenai Miku","Project Sekai Movie: Kowareta Sekai to Utaenai Miku","剧场版 世界计划 破碎的世界与唱不出歌的未来","电影世界计划初音未来","Gekijoban Purojekuto Sekai: Kowareta Sekai To Utaenai Miku","劇場版プロジェクトセカイ 壊れたセカイと歌えないミク"]', 1784690324142);
