INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuong-quyen-david-phan-2', 'Vương Quyền David (Phần 2)', 'House Of David (Season 2)', 'https://phimimg.com/upload/vod/20251006-1/33f94020a01584ceb79ebf6018a6a8f8.jpg', 'https://phimimg.com/upload/vod/20251006-1/dbb26468387799613897615a86e14d20.jpg', '<p>Kể câu chuyện về sự đi lên của nhân vật Kinh thánh, David, người trở thành vị vua nổi tiếng nhất của Israel. Loạt phim theo sau Vua Saul Saul khi anh ta trở thành nạn nhân của chính mình. Theo sự chỉ đạo của Thiên Chúa, nhà tiên tri Samuel xức dầu cho một thiếu niên khó có, bị ruồng bỏ là Vua mới.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Michael Iskander","avatar":""},{"name":"Ali Suliman","avatar":""},{"name":"Ayelet Zurer","avatar":""},{"name":"Alexander Uloom","avatar":""},{"name":"Stephen Lang","avatar":""},{"name":"Martyn Ford","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["בית דוד","בית דויד","House of David"]', 1784690324142);
