INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giu-chat-van-may', 'Giữ Chặt Vận May', 'Protect Your Luck (Catch Your Luck)', 'https://phimimg.com/upload/vod/20251027-1/4d5bc9669e13afe5384551f7645be6d7.jpg', 'https://phimimg.com/upload/vod/20251027-1/20bc69429d13b3d28067f09a538dd700.jpg', '<p>Ba người bạn: một người có nhiều tiền, một người không có tiền và một người muốn có thật nhiều tiền. Trong vòng xoay số mệnh, người có nhiều tiền bỗng trở thành kẻ cháy túi. Người không có tiền trở thành nhà giàu xổi. Người muốn có thật nhiều tiền thì giấu diếm tiền đen. Có người phải bất hạnh, có người được hạnh phúc. Tình thân gia đình tưởng chừng chỉ cần có tiền là đủ, nhưng lại rạn nứt. Gia đình mà trước đây tưởng như sẽ chết nếu không có tiền thì từng người một bắt đầu trưởng thành. Hai gia đình bỗng hoán đổi vị trí cho nhau. Để rồi cuối cùng, thứ hiện hữu quan trọng nhất không phải tiền, mà là &quot;con người&quot; trong cuộc sống kim tiền ấy. Rốt cuộc đã xảy ra chuyện gì với những người bạn thân trung niên bụng phệ này?</p>', 'Full', 121, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Son Chang-min","avatar":""},{"name":"Sunwoo Jae-duk","avatar":""},{"name":"Park Sang-myeon","avatar":""},{"name":"Lee Ah-hyeon","avatar":""},{"name":"Oh Young-shil","avatar":""},{"name":"Ahn Yeon-hong","avatar":""},{"name":"Lee Seung-Hyung","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Catch the Big Fortune","대운을 지켜라","Береги свою удачу","Держи свою удачу","Сорви куш","Поймай свою удачу","Catch Daewoon","Keep Your Luck","Catch Your Luck","Good Luck!","대운을 잡아라"]', 1784690324142);
