INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-ac-delhi-phan-3', 'Tội Ác Delhi (Phần 3)', 'Delhi Crime', 'https://phimimg.com/upload/vod/20251116-1/35e314c4706f713aba8692e6b113a37a.jpg', 'https://phimimg.com/upload/vod/20251116-1/1dfa124b40b4c2cc708df151fcc67268.jpg', '<p>Theo chân lực lượng cảnh sát khi họ điều tra các vụ phạm tội khét tiếng ở Delhi, các mùa của loạt phim này được dựa trên cả sự kiện có thật lẫn hư cấu.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Shefali Shah","avatar":""},{"name":"Rasika Dugal","avatar":""},{"name":"Avijit Dutt","avatar":""},{"name":"Adil Hussain","avatar":""},{"name":"Yashaswini Dayama","avatar":""},{"name":"Rajesh Tailang","avatar":""},{"name":"Jaya Bhattacharya","avatar":""},{"name":"Gopal Datt","avatar":""},{"name":"Denzil Smith","avatar":""},{"name":"Sidharth Bhardwaj","avatar":""},{"name":"Huma Qureshi","avatar":""},{"name":"Mita Vashisht","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Delhi Crime Story","दिल्ली क्राइम"]', 1784690324142);
