INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-an-mat-nau', 'Bí Ẩn Mắt Nâu', 'Blemish Flaw', 'https://phimimg.com/upload/vod/20251106-1/3820b00a4d1e3c40133e382138be5af3.jpg', 'https://phimimg.com/upload/vod/20251106-1/bb0588a5a90d4bb0659b2638e5964205.jpg', '<p>Blogger chuyên về video trinh thám Dương Chính Huy phát hiện bạn gái cũ Lưu Vi mất tích đã lâu, và dường như chuyện này có liên quan đến một nghệ nhân gốm tên là Tăng Kiệt. Một năm trước, vụ cháy tại xưởng gốm của Tăng Kiệt đã làm bí mật về Lưu Vi bị vùi lấp. Giờ đây, Tăng Kiệt lại tiếp tục âm mưu giết vợ đoạt tài sản. Khi Dương Chính Huy dấn sâu vào điều tra, bí ẩn đằng sau sự thật dần dần được hé lộ…</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tần Tuấn Kiệt","avatar":""},{"name":"Hoàng Mộng Oánh","avatar":""},{"name":"Uông Đạc","avatar":""},{"name":"Hỏa tiễn Thiếu nữ 101 Phó Tĩnh","avatar":""},{"name":"Trương Minh Ân","avatar":""},{"name":"Bàng Hạn Thần","avatar":""},{"name":"Vu Huệ","avatar":""},{"name":"Trần Tư Triệt","avatar":""},{"name":"Lý Mộc Thần","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324142);
