INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hay-nhin-toi-duoi-anh-sang-dep-nhat', 'Hãy Nhìn Tôi Dưới Ánh Sáng Đẹp Nhất', 'Come See Me In The Good Light', 'https://phimimg.com/upload/vod/20251115-1/d74ebb3c4260769a5d9685e006d4e76c.jpg', 'https://phimimg.com/upload/vod/20251115-1/ee1302b9805ac7530fbe822f82beb8ae.jpg', '<p>Trong câu chuyện đầy cảm xúc và niềm vui về tình yêu giữa mất mát, hai nhà thơ nổi tiếng Andrea Gibson và Megan Falley tìm thấy sức mạnh và cả niềm vui bất ngờ trong năm có thể là năm cuối cùng họ được bên nhau.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Andrea Gibson","avatar":""},{"name":"Megan Falley","avatar":""},{"name":"Tig Notaro","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Come See Me in the Good Light"]', 1784690324142);
