INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('binh-yeu-truyen-su-menh-trieu-hoan', 'Bình Yêu Truyện: Sứ Mệnh Triệu Hoán', 'The Demon Wardens: Convergence Of Souls', 'https://phimimg.com/upload/vod/20251115-1/7dc87d90f7325d81f7e2421eaf9e6561.jpg', 'https://phimimg.com/upload/vod/20251115-1/5a0d605a7b315399bc6a19cea1946e01.jpg', '<p>Câu chuyện kể về Địa Ma, thủ lĩnh tà ác của yêu tộc, cấu kết cùng Thái tử Long tộc Ngao Hạ, mưu đồ gây họa nhân gian. Trong lúc ấy thằn lằn tinh lương thiện, được tiên nhân giao cho sứ mệnh tìm kiếm tám dũng sĩ truyền thuyết. Trên hành trình đó, A Định gặp gỡ Hà Hương, một trong tám dũng sĩ chuyển thế. Để bảo vệ cô, A Định hy sinh mạng mình, đánh thức trách nhiệm và lòng can đảm của Hà Hương, giúp cô tiếp tục con đường giải cứu nhân loại.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Từ Phương Chử","avatar":""},{"name":"Lý Gia Hân","avatar":""},{"name":"Phổ Ba Giác","avatar":""},{"name":"Hoàng Tiểu Lôi","avatar":""},{"name":"Hoàng Duy Đức","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["平妖传之使命召唤"]', 1784690324142);
