INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-chien-1931-bach-at-hoa', 'Ám Chiến 1931: Bạch Ất Hóa', '1931 Hidden War The Hero Bai Yihua', 'https://phimimg.com/upload/vod/20251115-1/562a16781a03c7b8126cf8e3e1558c3e.jpg', 'https://phimimg.com/upload/vod/20251115-1/f0bc6c399a85df3cd689805dcaef12a0.jpg', '<p>Sau sự kiện Ngày 18 tháng 9 năm 1931, quân Nhật xâm chiếm vùng Đông Bắc Trung Quốc. Bạch Ất Hóa, một thanh niên đại học Trung Quốc yêu nước, nhận lệnh bí mật trở về quê hương Liêu Dương, lấy danh nghĩa một giáo viên để che giấu thân phận, âm thầm tổ chức lực lượng kháng Nhật. Tuy nhiên, hành động của anh liên tục bị đe dọa, trong cuộc đấu trí ngầm giữa ta và địch, thân phận của Bạch Ất Hóa đứng trước nguy cơ bị bại lộ, sống còn trong gang tấc. Liệu anh có thể vạch trần nội gián, phá vòng vây, và xoay chuyển cục diện nguy nan không?</p>', 'Full', 1, 'single', 'completed', 18, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Tử Thụy","avatar":""},{"name":"Tả Kim Châu","avatar":""},{"name":"Vương Lỗ","avatar":""},{"name":"Ai Giai Ni","avatar":""},{"name":"Đỗ Dục Minh","avatar":""},{"name":"Trương Lôi","avatar":""},{"name":"Lưu Trác","avatar":""},{"name":"Kim Lương","avatar":""},{"name":"Lang Anh Bác","avatar":""},{"name":"Mong Vũ","avatar":""},{"name":"Vu Khiếu","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["暗战1931之白乙化"]', 1784690324142);
