INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chim-cuc-cu-pha-le-el-cuco-de-cristal', 'Chim Cúc Cu Pha Lê (El cuco de cristal)', 'The Crystal Cuckoo', 'https://phimimg.com/upload/vod/20251115-1/d0bcfadd70c28f2f5bc4742598362cb2.jpg', 'https://phimimg.com/upload/vod/20251115-1/42ba1bfb0c3ef143173b581f02f63e69.jpg', '<p>Muốn biết thêm về người hiến tim cho mình, vị bác sĩ trẻ nọ đến một ngôi làng miền núi. Cộng đồng nhỏ ấy đã nhiều thập kỷ chìm trong bi kịch bí ẩn.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Catalina Sopelana","avatar":""},{"name":"Itziar Ituño","avatar":""},{"name":"Álex García","avatar":""},{"name":"Ivan Massagué","avatar":""},{"name":"Tomás del Estal","avatar":""},{"name":"Alfons Nieto","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Der Kristallkuckuck","ბროლის გუგული","შუშის გუგული","კრისტალის გუგული","El cuco de cristal"]', 1784690324142);
