INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chim-cuc-cu-pha-le-el-cuco-de-cristal', 'Chim Cúc Cu Pha Lê (El cuco de cristal)', 'The Crystal Cuckoo', 'chim cúc cu pha lê (el cuco de cristal) the crystal cuckoo catalina sopelana itziar ituño álex garcía ivan massagué tomás del estal alfons nieto der kristallkuckuck ბროლის გუგული შუშის გუგული კრისტალის გუგული el cuco de cristal', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-uyen', 'Thanh Uyên', 'Sonic Judgement', 'https://phimimg.com/upload/vod/20251114-1/69dafec346dbffef92957cd1e5cd6ddc.jpg', 'https://phimimg.com/upload/vod/20251114-1/cad60f92d599657a386e28731a4fb5cc.jpg', '<p>Bộ phim kể về câu chuyện hợp tác phá án và cùng nhau trưởng thành giữa đội trưởng đội cảnh sát hình sự giàu kinh nghiệm Tô Lăng Vũ và giám đốc phòng âm thanh hình ảnh Khương Thành.Các vụ án bắt đầu từ việc phát hiện một xác chết nam giới bị lạm dụng tại một nhà máy thép. Manh mối duy nhất là một đoạn ghi âm được cho là do chính nạn nhân tự biên tự diễn, cùng với vụ việc 50 cân vàng và một người bị bắt cóc đột nhiên bốc hơi.Khi điều tra sâu hơn, cảnh sát phát hiện ra vô số tội ác của nạn nhân, bao gồm bắt nạt học đường, lừa đảo, hối lộ tình dục và cho vay nặng lãi. Đồng thời, một vụ án thảm sát diệt môn nhiều năm trước cũng dần được hé lộ.Cùng lúc đó, bạn gái cũ của nạn nhân chứng kiến người yêu cũ của mình thất khiếu chảy máu và đang trong tình trạng nguy kịch, và một &quot;góa phụ đen&quot; liên tiếp ra tay giết bốn người bằng cả tình sát và đầu độc. Tại bệnh viện Hân Sinh, thi thể trong nhà xác đột nhiên biến mất, trong khi xác của phó viện trưởng lại nằm ngang trong đó.Cảnh sát điều tra sâu hơn và phát hiện ra đằng sau những vụ việc này là một mạng lưới tội phạm khổng lồ và một kẻ chủ mưu không ngờ tới.Với sự phối hợp ăn ý của Tô Lăng Vũ và Khương Thành, cùng với nỗ lực không ngừng của lực lượng cảnh sát, họ đã thành công bắt giữ tội phạm, giải đáp bí ẩn về cái chết bất ngờ của bố mẹ Khương Thành, và cuối cùng là tiêu diệt băng nhóm tội phạm.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Hác","avatar":""},{"name":"Kim Hán Chính","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["声渊"]', 1784690324142);
