INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hong-sung-vo-hinh-2025', 'Họng Súng Vô Hình', 'The Naked Gun', 'https://phimimg.com/upload/vod/20250904-1/0feaa1bcfe0fa135f815f7784f8f6885.jpg', 'https://phimimg.com/upload/vod/20250904-1/36c2c917ecc991782afe21eabdb47fb9.jpg', '<p>Họng Súng Vô Hình là phần tiếp theo của thương hiệu hài giả tội phạm đình đám The Naked Gun, lần này nhân vật trung úy Frank Drebin Jr. – do Liam Neeson thủ vai – tiếp bước cha mình để điều tra một vụ ám sát liên quan đến anh trai của quý cô Beth. Bộ phim mang phong cách hài hành động châm biếm, kết hợp giữa các tình huống đối kháng kịch tính và cú lừa đảo đầy hài hước đậm chất “ngơ ngơ nhưng cực quyết liệt.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Liam Neeson","avatar":""},{"name":"Pamela Anderson","avatar":""},{"name":"Paul Walter Hauser","avatar":""},{"name":"Danny Huston","avatar":""},{"name":"CCH Pounder","avatar":""},{"name":"Kevin Durand","avatar":""},{"name":"Liza Koshy","avatar":""},{"name":"Eddie Yu","avatar":""},{"name":"Michael Beasley","avatar":""},{"name":"Moses Jones","avatar":""},{"name":"Chase Steven Anderson","avatar":""},{"name":"Cody Rhodes","avatar":""},{"name":"Busta Rhymes","avatar":""},{"name":"Eddie DuPriest","avatar":""},{"name":"Carl Gilliard","avatar":""},{"name":"Elliott Grey","avatar":""},{"name":"Wilbur Fitzgerald","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["총알탄 사나이","Çılpaq Silah","L''agent fait la farce","Una pallottola spuntata","Agarralo como puedas","Corra Que a Polícia Vem Aí!","裸の銃を持つ男","Die Nackte Kanone","神探零零甩","Arma e zhveshur","The Naked Gun"]', 1784690324142);
