INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ikusagami-chien-than-samurai', 'Ikusagami: Chiến Thần Samurai', 'Last Samurai Standing', 'ikusagami: chiến thần samurai last samurai standing junichi okada yumia fujisaki kaya kiyohara masahiro higashide shota sometani taichi saotome yuya endo yasushi fuchikami kairi jo takayuki yamada wataru ichinose riho yoshioka kazunari ninomiya hiroshi tamaki hideaki ito até o último samurai ikusagami 라스트 사무라이 스탠딩 последний выживший самурай イクサガミ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-van-vuong', 'Đêm Vấn Vương', 'One Night Meant For Pure Love', 'https://phimimg.com/upload/vod/20251114-1/37ed360818f0364446c1deef69636c3b.jpg', 'https://phimimg.com/upload/vod/20251114-1/6af7dbc89cb8c4a1a41fc53c2ca76838.jpg', '<p>Tận mắt chứng kiến bạn trai và bạn thân quấn quýt bên nhau, Na Young trong cơn say đã qua đêm với Jung Woo, đàn em cùng bộ phận. Cô muốn coi đêm buông thả ấy như một giấc mơ, nhưng Jung Woo lại đưa ra một giao dịch: “Tôi có thể giả làm người yêu của cô, giúp cô trả thù tên bạn trai cũ kia.” Cứ như vậy, hai người bắt đầu một mối tình hợp đồng. Đây vốn dĩ chỉ là một cuộc trao đổi nhẹ nhàng, nhưng Na Young dần đắm chìm trong sự dịu dàng của Jung Woo. Đến khi lớp mặt nạ bị xé bỏ, sự thật được phơi bày - hoá ra Jung Woo là con trai nhà tài phiệt, anh tiếp cận cô là có mục đích riêng! Khi chân thành và lợi dụng đan xen lẫn nhau, mối tình bắt đầu bằng lời nói dối ấy liệu có thể đi đến một cái kết chân thật hay không?</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 29, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phim Ngắn","slug":"phim-ngan","id":"4f02d28224c0747511790d57fbb63a62"}]', '[]', 1784690324142);
