INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-than-lop-e', 'Nữ Thần Lớp E', 'Ang Mutya ng Section E', 'https://phimimg.com/upload/vod/20251113-1/4e01be2741d85012018df7eeb230f11c.jpg', 'https://phimimg.com/upload/vod/20251113-1/00c9da80cd74f29c43f7dfb860b05f85.jpg', '<p>Jay-jay, cô gái duy nhất trong lớp học nghịch ngợm Section E (Lớp E), hy vọng có một khởi đầu mới ở trường cấp ba nhưng nhanh chóng trở thành mục tiêu của những trò đùa và kế hoạch quấy phá từ các nam sinh ồn ào trong lớp nhằm khiến cô phải bỏ đi. Được đặt biệt danh là &quot;Mutya&quot; (một từ tiếng Tagalog có nghĩa là Nữ thần/Viên ngọc), cô nàng đáp trả bằng sự thông minh và duyên dáng, lật ngược tình thế khiến những kẻ bắt nạt phải bẽ mặt. Giữa mớ hỗn loạn, những tình bạn bất ngờ nảy nở, và những hiểu lầm dở khóc dở cười lại dẫn đến những khoảnh khắc rung động trái tim. Liệu Jay-jay có thể sống sót qua sự điên rồ của Section E, hay cô sẽ chinh phục được trái tim của tất cả bọn họ?</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 31, 2025, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Andres Muhlach","avatar":""},{"name":"Ashtine Olviga","avatar":""},{"name":"Rabin Angeles","avatar":""},{"name":"Charles Law","avatar":""},{"name":"Andre Yllana","avatar":""},{"name":"Frost Sandoval","avatar":""},{"name":"Keagan De Jesus","avatar":""},{"name":"Nic Galvez","avatar":""},{"name":"Axel Torres","avatar":""},{"name":"Yayo Aguila","avatar":""},{"name":"Nanette Inventor","avatar":""},{"name":"Lander Vera Perez","avatar":""},{"name":"Katya Santos","avatar":""},{"name":"Heart Ryan","avatar":""},{"name":"Yanyan de Jesus","avatar":""},{"name":"Ethan David","avatar":""},{"name":"Rafa Victorino","avatar":""},{"name":"S","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca8