INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-anh-kinh-hoang-nghi-le-cuoi-cung', 'Ám Ảnh Kinh Hoàng: Nghi Lễ Cuối Cùng', 'The Conjuring: Last Rites', 'https://phimimg.com/upload/vod/20250907-1/e23ee28ef8afb8586c3f5aba9fa96e7a.jpg', 'https://phimimg.com/upload/vod/20250907-1/1c0c9f21c64a58b6b7706018e289ebb7.jpg', '<p>Hai nhà điều tra hiện tượng siêu nhiên Ed và Lorraine Warren đối mặt với một vụ án kinh hoàng cuối cùng — nơi họ buộc phải đối đầu với những thực thể bí ẩn đầy đe dọa, thách thức tất cả những gì họ từng tin tưởng.</p>', 'Full', 1, 'single', 'completed', 10, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Vera Farmiga","avatar":""},{"name":"Patrick Wilson","avatar":""},{"name":"Mia Tomlinson","avatar":""},{"name":"Ben Hardy","avatar":""},{"name":"Rebecca Calder","avatar":""},{"name":"Elliot Cowan","avatar":""},{"name":"Shannon Kook","avatar":""},{"name":"Steve Coulter","avatar":""},{"name":"Kíla Lord Cassidy","avatar":""},{"name":"Beau Gadsdon","avatar":""},{"name":"Tilly Walker","avatar":""},{"name":"Molly Cartwright","avatar":""},{"name":"Leigh Jones","avatar":""},{"name":"John Brotherton","avatar":""},{"name":"Peter Wight","avatar":""},{"name":"Kate Fahy","avatar":""},{"name":"Orion Smith","avatar":""},{"name":"Madison","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Conjuring 4","الشعوذة: الطقوس الأخيرة","الشعوذة 4","الشعوذة ٤","詭屋驚凶實錄4：最後的儀式","เดอะ คอนเจอริ่ง คนเรียกผี พิธีกรรมครั้งสุดท้าย","THE CONJURING: NGHI LỄ CUỐI CÙNG","컨저링 4","Prizivanj