INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thay-giao-dia-nguc-nube-jigoku-sensei-nube', 'Thầy Giáo Địa Ngục Nube (Jigoku Sensei Nube)', 'Hell Teacher: Jigoku Sensei Nube', 'https://phimimg.com/upload/vod/20250919-1/af0b9d3ee5a87f004f733ece86d0429e.jpg', 'https://phimimg.com/upload/vod/20250919-1/9e09340f2b482cae3fa480ae6862e98c.jpg', '<p>Một loạt hiện tượng khó lý giải liên tục xảy ra ở thị trấn Domori. Để bảo vệ bọn trẻ trong thị trấn, một giáo viên chủ nhiệm mới, được gọi là “Nube”, đã đến. Bình thường anh hiền hòa, có phần hoạt bát, nhưng lại che giấu một bí mật: anh chính là giáo viên tâm linh duy nhất ở Nhật Bản. Người ta còn đồn rằng bàn tay trái của anh bị quỷ ám! Sứ giả công lý từ địa ngục nay xuất hiện để đối đầu với bảy bí ẩn trong trường học, những hồn ma và ác linh đang tấn công học trò của mình.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ryotaro Okiayu","avatar":""},{"name":"Ryoko Shiraishi","avatar":""},{"name":"Aya Suzaki","avatar":""},{"name":"Aya Endo","avatar":""},{"name":"Ryota Iwasaki","avatar":""},{"name":"Shiho Kokido","avatar":""},{"name":"Tomoyo Kurosawa","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jigoku Sensei Nube 2025","ぬーべーアニメ","じごくせんせいぬーべー","Jigoku Sensei Nube","지옥선생 누베","靈異教師神眉","Hell Teacher Nube","HellTeacher","地獄先生ぬ～べ～"]', 1784690324142);
