INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-dong-nhu-that', 'Sống Động Như Thật', 'Life Like', 'https://phimimg.com/upload/vod/20251031-1/f6be123b0fded72352b03fb78b23c75b.jpg', 'https://phimimg.com/upload/vod/20251031-1/ebf9d85e630ebc47061dbc6b44389fee.jpg', '<p>Nữ sát thủ Chân Hủ cải trang thành đệ nhất danh ca, trong một lần tình cờ đã gặp Chu Mộ Thăng, thành viên của Thương hội Bắc Thành đang thực hiện nhiệm vụ. Ban đầu, hai người chỉ lợi dụng lẫn nhau, nhưng giữa hoàn cảnh đầy rẫy hiểm nguy, họ dần nảy sinh tình cảm. Chân Hủ và Mộ Thăng cùng nhau trải qua biết bao thử thách sinh tử. Cuối cùng, họ đã phối hợp ngăn chặn âm mưu phi pháp của Thương hội Bắc Thành và cùng nhau đón chào cuộc sống mới.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Nhược Thiên","avatar":""},{"name":"Triệu An Đệ","avatar":""},{"name":"Châu Ngữ Đình","avatar":""},{"name":"Trương Hân Khải","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["栩栩如昇"]', 1784690324142);
