INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-quan-do-truong-hoan', 'Dữ Quân Độ Trường Hoan', 'Eternal Joy With You', 'https://phimimg.com/upload/vod/20251029-1/addcdac8b3ebefb5828e97d7c85dd57a.jpg', 'https://phimimg.com/upload/vod/20251029-1/0e00e9513fcf45882f6d43389c92c36a.jpg', '<p>Kiếp trước, Hứa Uyển Ninh bị gã chồng tệ bạc lừa dối — đứa con mà cô hết lòng nuôi dưỡng hóa ra lại là con của “tiểu tam” giả ngây thơ, còn con ruột của chính cô thì đã chết thảm từ lâu. Lần này được tái sinh trở lại, cô vừa trừng trị kẻ phản bội, vừa bảo vệ con mình, và trong quá trình điều tra vụ “Hồng Trẫm Hương” cùng Bùi Hành, hai người nhiều lần chạm trán. Đến lúc ấy, Hứa Uyển Ninh mới nhận ra rằng, sợi dây nhân duyên giữa họ đã bắt đầu từ kiếp trước…</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hà Tuyên Lâm","avatar":""},{"name":"Nghiêm Tử Hiền","avatar":""},{"name":"La Dư Điềm","avatar":""},{"name":"Trần Hoàn","avatar":""},{"name":"Hoàng Phủ Bạc Nguyên","avatar":""},{"name":"Klaudia","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["宠妾灭妻？主母携崽二嫁权宦","Yu Jun Du Chang Huan","与君渡长欢"]', 1784690324142);
