INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-bang', 'Bang Bang', 'Bang Bang', 'https://phimimg.com/upload/vod/20251111-1/acae44d488375127085930b1d704d079.jpg', 'https://phimimg.com/upload/vod/20251111-1/5543f3ad52607576955e6d3d64c9c153.jpg', '<p>Một huyền thoại quyền anh đã gác găng tay. Một cháu trai xa cách thắp lại ngọn lửa xưa. Giữa quá khứ hào quang, mối thù cũ và những nghi ngờ đan xen, Bang Bang phải đối mặt với sự ngờ vực của những người xung quanh: ông đang truyền lại di sản… hay chỉ là cơn giận không bao giờ tắt?</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tim Blake Nelson","avatar":""},{"name":"Glenn Plummer","avatar":""},{"name":"Andrew Liner","avatar":""},{"name":"Kevin Corrigan","avatar":""},{"name":"Nina Arianda","avatar":""},{"name":"Erica Gimpel","avatar":""},{"name":"Daniella Pineda","avatar":""},{"name":"Will Janowitz","avatar":""},{"name":"Dana Namerode","avatar":""},{"name":"Clayton LaDue","avatar":""},{"name":"Mirlande Amazan","avatar":""},{"name":"KJ Dullen","avatar":""},{"name":"Celina Lamon","avatar":""},{"name":"Nathan Todd","avatar":""},{"name":"Josh Kelling","avatar":""},{"name":"Eric Haas","avatar":""},{"name":"Josh Gleberman","avatar":""},{"name":"Daphne","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bang Bang"]', 1784690324142);
