INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duoi-lop-vo-boc-ben-duoi-lop-thuong-phuc', 'Dưới Lớp Vỏ Bọc (Bên Dưới Lớp Thường Phục)', 'Plainclothes', 'https://phimimg.com/upload/vod/20251111-1/d0e77f778cda1a10ba3980f35f67c511.jpg', 'https://phimimg.com/upload/vod/20251111-1/27591b733d69106c6d2119e038b0efa6.jpg', '<p>Một sĩ quan cảnh sát trẻ đầy triển vọng được giao nhiệm vụ hoạt động chìm nhằm dụ dỗ và bắt giữ những người đồng tính. Nhưng mọi thứ thay đổi khi anh bất chấp mệnh lệnh và đem lòng yêu chính mục tiêu của mình.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Tom Blyth","avatar":""},{"name":"Russell Tovey","avatar":""},{"name":"Amy Forsyth","avatar":""},{"name":"Maria Dizzia","avatar":""},{"name":"Christian Cooke","avatar":""},{"name":"Gabe Fazio","avatar":""},{"name":"John Bedford Lloyd","avatar":""},{"name":"Sam Asa Brownstein","avatar":""},{"name":"Darius Fraser","avatar":""},{"name":"Alessandra Ford Balazs","avatar":""},{"name":"Joseph Emmi","avatar":""},{"name":"Luke Burke","avatar":""},{"name":"Marlene Mancini","avatar":""},{"name":"Henry Stockwell","avatar":""},{"name":"Ben Anderson","avatar":""},{"name":"Jason Ngo","avatar":""},{"name":"Charli Emm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["В штатском","Plainclothes"]', 1784690324142);
