INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khieu-vu-cung-brando', 'Khiêu Vũ Cùng Brando', 'Waltzing With Brando', 'https://phimimg.com/upload/vod/20251111-1/5e15ce134ac01b8a21ba00f2f3f9d6ad.jpg', 'https://phimimg.com/upload/vod/20251111-1/822c65b25443c6d20bd85c04a8ba780e.jpg', '<p>Câu chuyện về cách Marlon Brando đã phát hiện ra Bernard Judge — một kiến trúc sư ít tên tuổi nhưng đầy lý tưởng ở Los Angeles — và thuyết phục ông từ bỏ cuộc sống ổn định để xây dựng khu nghỉ dưỡng sinh thái hoàn hảo đầu tiên trên thế giới, nằm trên một hòn đảo nhỏ hoang vu ở Tahiti.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Billy Zane","avatar":""},{"name":"Jon Heder","avatar":""},{"name":"Camille Razat","avatar":""},{"name":"Alaina Huffman","avatar":""},{"name":"Rob Corddry","avatar":""},{"name":"Tia Carrere","avatar":""},{"name":"Richard Dreyfuss","avatar":""},{"name":"James Jagger","avatar":""},{"name":"Sofia Masson","avatar":""},{"name":"James Mackie","avatar":""},{"name":"Tanna Frederick","avatar":""},{"name":"Mark Canjar","avatar":""},{"name":"David Gueriera","avatar":""},{"name":"Patrick McLain","avatar":""},{"name":"Charles Venturi","avatar":""},{"name":"Heiae Touniou","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Waltzing with Brando"]', 1784690324142);
