INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-tan-2025', 'Băng Tan', 'Icefall', 'https://phimimg.com/upload/vod/20251111-1/1908644f4648069255f839cd0e347b51.jpg', 'https://phimimg.com/upload/vod/20251111-1/a32f4530db4d2ad86d55bb8a1c15bedf.jpg', '<p>Một kiểm lâm viên trẻ người bản địa bắt giữ một tay săn trộm khét tiếng, nhưng rồi phát hiện ra rằng hắn biết vị trí của một chiếc máy bay chở hàng triệu đô la bị rơi xuống một hồ băng. Khi một nhóm tội phạm và cảnh sát biến chất biết được tung tích của tay săn trộm, kiểm lâm viên và hắn buộc phải hợp tác để chống trả và tìm cách trốn thoát qua mặt hồ nguy hiểm trước khi băng tan.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Joel Kinnaman","avatar":""},{"name":"Cara Jade Myers","avatar":""},{"name":"Danny Huston","avatar":""},{"name":"Graham Greene","avatar":""},{"name":"Martin Sensmeier","avatar":""},{"name":"Oliver Trevena","avatar":""},{"name":"DeVaughn Nixon","avatar":""},{"name":"Frida Gustavsson","avatar":""},{"name":"Will Fletcher","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["冰湖行动","سقوط یخ","Icefall: Botín En El Hielo","Icefall"]', 1784690324142);
