INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-mat-lenh', 'Cẩm Mật Lệnh', 'A Mission Of The Heart', 'https://phimimg.com/upload/vod/20251106-1/e8fc7cbc2b30a20255499443c1dcf092.jpg', 'https://phimimg.com/upload/vod/20251106-1/cb75313537aadf9235748a3c5339c23d.jpg', '<p>Tại Hiệp Phượng Lâu, cô gái mạnh mẽ Hoàng Ngọc chỉ là một tạp dịch bình thường, nhưng một lần vô tình xông vào hiện trường truy bắt tội phạm trong vụ án trộm bạc do Cẩm y vệ đang mật tra, cô lại trở thành nghi phạm trong mắt chỉ huy Lộ Trảm.Dù cuối cùng được rửa oan, Hoàng Ngọc vì sở hữu năng lực đặc biệt nên bị Lộ Trảm uy hiếp và dụ dỗ gia nhập Bắc Trấn Phủ Ty, trở thành một tiểu bộ khoái bất đắc dĩ.Cô chỉ muốn làm việc kiếm tiền để sống an ổn, nhưng lại thường xuyên bị ông sếp lạnh lùng Lộ Trảm bóc lột.Nhờ tài năng khám nghiệm thi thể, Hoàng Ngọc liên tiếp phá giải nhiều vụ án ly kỳ, dần dần phát hiện bí ẩn thân thế của chính mình — cha cô từng bị quyền thần Giang Ninh hãm hại và tru di cả nhà.Ngọn lửa báo thù trong cô âm thầm bùng cháy.Trong khi đó, Lộ Trảm dù ngoài mặt lạnh lùng sắt đá nhưng ẩn chứa tình cảm sâu sắc, cùng Thẩm Phán – Thị lang Bộ Hình – hình thành mối tình tay ba phức tạp.Ba người hợp sức chống lại âm mưu quyền lực chốn triều đình.Trong hành trình truy tìm sự thật, giữa đao kiếm và hiểm nguy, Hoàng Ngọc và Lộ Trảm nảy sinh tình cảm, cùng nhau minh oan cho gia tộc, vạch trần tội ác tày trời của Triệu Ngọc Đường.Phía sau vụ án là mạng lưới âm mưu chằng chịt, nơi quyền mưu và tình cảm đan xen, chứng kiến Hoàng Ngọc từ một cô gái dân dã nhỏ bé vươn mình trở thành người phá thế cục, cùng Lộ Trảm sát cánh bảo vệ công lý, viết nên bản anh hùng ca của sự cứu chuộc trong thời loạn.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Môn Ân","avatar":""},{"name":"Kỳ Mỹ Hàm","avatar":""},{"name":"Khúc Tĩnh","avatar":""},{"name":"Trịnh Thác Cương","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324143);
