INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cam-mat-lenh', 'Cẩm Mật Lệnh', 'A Mission Of The Heart', 'cẩm mật lệnh a mission of the heart môn ân kỳ mỹ hàm khúc tĩnh trịnh thác cương ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-niem-cam-ki-ban-giao-huong-dinh-menh', 'Nỗi Niềm Cấm Kị: Bản Giao Hưởng Định Mệnh', 'Love Psychedelic', 'https://phimimg.com/upload/vod/20251108-1/19036f2616e676fd1d569c8b2db6946a.jpg', 'https://phimimg.com/upload/vod/20251108-1/879ed3922f487bfc5061d9d2c333e990.jpg', '<p>Thiếu nữ và tội ác hoàn hảo Kang Dan Jo, một nữ sinh trung học mang khí chất u buồn như một thang âm thứ, đơn phương yêu Jung Joo Won, một chàng trai rạng rỡ và kiên định như một thang âm trưởng. Nếu cưỡng ép hòa quyện những quãng âm không hòa hợp, sẽ chỉ tạo ra tạp âm chói tai... Dan Jo chọn cách yêu một mình, đau khổ một mình, triền miên một mình, chôn sâu Joo Won tận đáy lòng. Kỳ nghỉ hè, tại một phòng học trống—— &quot;Pằng!&quot; Một tiếng súng vang lên từ đâu đó trong trường. Dan Jo lần theo âm thanh chạy đến phòng thực hành in 3D, và cảnh tượng cô chứng kiến chính là... nam sinh Oh Hyun Min đang đẫm máu! Cùng với Joo Won đang đứng sững bên cạnh, chìm trong hoảng loạn! Giây phút này, trong đầu Dan Jo chỉ có một suy nghĩ: &quot;Phải bảo vệ Joo Won!&quot; Cô run rẩy lau đi vết máu trên mặt Joo Won và bắt đầu dọn dẹp hiện trường. Joo Won xem Dan Jo, người đột ngột xuất hiện, như một vị cứu tinh, còn Dan Jo, để bảo vệ anh, đã lên kế hoạch cho một tội ác hoàn hảo. Trong bí mật đan xen, một dòng khí lưu màu hồng mờ ám lặng lẽ nảy sinh giữa hai người...</p>', 'Hoàn Tất (47/47)', 47, 'series', 'completed', 34, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phim Ngắn","slug":"phim-ngan","id":"4f02d28224c0747511790d57fbb63a62"}]', '[]', 1784690324143);
