INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-ac-ke-lam-ngo', 'Tội Ác Kẻ Làm Ngơ', 'As You Stood By', 'https://phimimg.com/upload/vod/20251107-1/7bb8995b48ec6ba18619b44ca9eef0e1.jpg', 'https://phimimg.com/upload/vod/20251107-1/7407856e63687002f12340cae2086a12.jpg', '<p>Khi hai người phụ nữ âm mưu chấm dứt cuộc hôn nhân đầy bạo lực bằng cách giết người, một vị khách không ngờ tới xuất hiện và đe dọa phá vỡ mọi kế hoạch họ chuẩn bị.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2025, 'Vietsub + Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jeon So-nee","avatar":""},{"name":"Lee You-mi","avatar":""},{"name":"Jang Seung-jo","avatar":""},{"name":"Lee Mu-saeng","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324143);
