INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xuc-xac-sinh-tu', 'Xúc Xắc Sinh Tử', 'The Dark Dice', 'https://phimimg.com/upload/vod/20250918-1/96929f3ae73a42ae967fd03ed2f3f301.jpg', 'https://phimimg.com/upload/vod/20250918-1/6bc5a333d75ba05fc82691748694e9cf.jpg', '<p>Là một học sinh trung học xuất sắc, Samut thường đại diện trường tham gia các cuộc thi học thuật. Thế nhưng, tương lai xán lạn của Samut lại bị hủy hoại vì một sự cố khiến cậu bị đuổi học. Sau khi chuyển đến một ngôi trường mới, Samut vô tình tìm thấy một con xúc xắc cổ và bị nó cuốn vào thế giới trò chơi bí ẩn cùng bảy học sinh khác. Tám cô cậu học trò phải cạnh tranh, đấu trí và phản bội nhau để có thể sinh tồn trong thế giới khắc nghiệt của Xúc Xắc Sinh Tử.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 10, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Norawit Titicharoenrak","avatar":""},{"name":"Chanikarn Tangkabodee","avatar":""},{"name":"Ochiris Suwanacheep","avatar":""},{"name":"Nichapha Phraephirakun","avatar":""},{"name":"Promsakha Na Sakolnakron","avatar":""},{"name":"Theepakorn Kwanboon","avatar":""},{"name":"Nannaphas Loetnamchoetsakun","avatar":""},{"name":"Poon Mitpakdee","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Kem Thoi Thalu Miti","Game Toy Talu Miti","เกมทอยทะลุมิติ"]', 1784690324143);
