INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuon-toi-mat-trang', 'Vươn Tới Mặt Trăng', 'To The Moon', 'https://phimimg.com/upload/vod/20250920-1/039f3797187cd3c422ad0656c96888d0.jpg', 'https://phimimg.com/upload/vod/20250920-1/8a8cbd011b0dd30c1b1a22eef7b6c3eb.jpg', '<p>Vươn Tới Mặt Trăng (To The Moon) xoay quanh những nỗ lực kiếm tiền để đổi đời của ba nữ nhân viên văn phòng Da Hae, Eun Sang và Ji Song. Xuất thân nghèo khó và sống dựa vào đồng lương eo hẹp, họ quyết định đầu tư vào tiền ảo với hy vọng có thể thay đổi số phận. Trong hành trình đó, họ gặp Ham Ji U, một anh chàng giàu có và thành công, nhưng lại luôn cảm thấy cô đơn trong thế giới xa hoa. Cuộc gặp gỡ đã đánh thức nơi anh niềm tin và những ước mơ tưởng chừng đã lãng quên từ lâu.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 9, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Sun-bin","avatar":""},{"name":"Ra Mi-ran","avatar":""},{"name":"Jo A-ram","avatar":""},{"name":"Kim Young-dae","avatar":""},{"name":"Um Mun-suk","avatar":""},{"name":"Hong Seung-hee","avatar":""},{"name":"Kim Mi-kyeong","avatar":""},{"name":"Seo Hyun-chul","avatar":""},{"name":"Lee Sang-jin","avatar":""},{"name":"Cha Si-won","avatar":""},{"name":"Oh Seung-ah","avatar":""},{"name":"Ahn Dong-gu","avatar":""},{"name":"Seo Ji-soo","avatar":""},{"name":"Kim Seon Gyeong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["我们去月球吧","نحو القمر","走到月亮為止","달까지 가자"]', 1784690324143);
