INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('don-gian-la-alice-simplemente-alicia', 'Đơn Giản Là Alice (Simplemente Alicia)', 'Just Alice', 'https://phimimg.com/upload/vod/20251107-1/0e7588cba32154264e60546f8641c993.jpg', 'https://phimimg.com/upload/vod/20251107-1/48cf323ee68735f0d4ddeffcba51ecb6.jpg', '<p>Bị giằng xé giữa hai mối tình, Alicia bí mật cưới cả nhà văn nổi tiếng và cựu linh mục. Liệu cô có thể xoay xở giữa tình yêu, dối trá và cuộc sống hai mặt của mình trong bao lâu?</p>', 'Hoàn Tất (19/19)', 19, 'series', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Verónica Orozco","avatar":""},{"name":"Cony Camelo","avatar":""},{"name":"Sebastián Carvajal","avatar":""},{"name":"Michel Brown","avatar":""},{"name":"Julián Román","avatar":""},{"name":"Leo Deluglio","avatar":""},{"name":"Ana María Medina","avatar":""},{"name":"Daniela Tapia","avatar":""},{"name":"Fernando Arévalo","avatar":""},{"name":"Biassini Segura","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324143);
