INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoi-nghiep-lun-bai-tu-ty-phu-toi-toi-pham', 'Khởi Nghiệp, Lụn Bại Từ Tỷ Phú Tới Tội Phạm', 'Start Up, Fall Down: From Billionaire To Convict', 'https://phimimg.com/upload/vod/20251106-1/a7c20ba0c045f894f859cbb795295ecb.jpg', 'https://phimimg.com/upload/vod/20251106-1/92873735ab9183e098fcc937d90b275c.jpg', '<p>Một trong những bữa tiệc xa hoa nhất Milan gặp bước ngoặt đen tối khi một người phụ nữ trình báo bị tấn công tình dục. Loạt phim tài liệu này ghi lại cuộc điều tra diễn ra sau đó.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Terrazza Sentimento Del esplendor al horror","Start Up, Fall Down: From Billionaire to Convict","Terrazza Sentimento"]', 1784690324143);
