INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khoi-nghiep-lun-bai-tu-ty-phu-toi-toi-pham', 'Khởi Nghiệp, Lụn Bại Từ Tỷ Phú Tới Tội Phạm', 'Start Up, Fall Down: From Billionaire To Convict', 'khởi nghiệp, lụn bại từ tỷ phú tới tội phạm start up, fall down: from billionaire to convict  terrazza sentimento del esplendor al horror start up, fall down: from billionaire to convict terrazza sentimento', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-khanh-y', 'Thị Khanh Y', 'In The Name Of Loyalty', 'https://phimimg.com/upload/vod/20251026-1/232f18f8479292ba4fcdf8f89b1aade8.jpg', 'https://phimimg.com/upload/vod/20251026-1/5e797d798e61a7eabcf67cfe11b75edc.jpg', '<p>Những thợ săn giỏi nhất thường xuất hiện dưới lốt con mồi. Thị y quan Thành Ca, để hoàn thành nhiệm vụ ám sát hoàng đế Thời Dự, đã chủ động dấn thân vào cuộc chơi, tiến cung trở thành thị y quan thân cận bên cạnh Thời Dự. Thế nhưng trong quá trình ám sát, nàng lại bị cuốn vào vòng xoáy tranh đấu quyền lực nơi triều đình, và những bí ẩn tăm tối của triều đại trước cũng dần bị khơi lại. Tiến hay thoái — nàng sẽ lựa chọn con đường nào?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Mông Ân","avatar":""},{"name":"Lâm Thử Dự","avatar":""},{"name":"Từ Dương Hạo","avatar":""},{"name":"Ngô Tĩnh Hân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shi Qing Yi","侍卿衣"]', 1784690324143);
