INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hinh-bong-chong-cheo', 'Hình Bóng Chồng Chéo', 'Persona', 'https://phimimg.com/upload/vod/20251026-1/7411fb6ca64086ddb635bcebcda15604.jpg', 'https://phimimg.com/upload/vod/20251026-1/cb78ab93745dc0aa7665b9beaa563415.jpg', '<p>&quot;Một vụ án mạng không có thi thể, một cuộc bỏ trốn không có điểm dừng…&quot; Một năm trước, tại thị trấn nhỏ miền Bắc mang tên Thần Thương, đã xảy ra một vụ án trả thù giết người. Hung thủ Tần Hồng đã bỏ trốn. Một năm sau, khi cảnh sát “phát hiện” Tần Hồng ở miền Nam, thì cô ta đã bị bạn trai ném xác xuống biển, không tìm được thi thể. Đây là một vụ án có đầy đủ nhân chứng và vật chứng, thậm chí hung thủ cũng đã thú nhận hành vi phạm tội. Thế nhưng, việc thi thể biến mất hoàn toàn khiến cảnh sát phụ trách vụ án Lưu Vọng cảm thấy bất an. “Tần Hồng thật sự đã chết chưa?”</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cao Diệp","avatar":""},{"name":"Trần Tịnh Khả","avatar":""},{"name":"Trịnh Khải","avatar":""},{"name":"Đường Tăng","avatar":""},{"name":"Tiết Hạo Tịnh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chong Ying","Ghosting","Persona","重影"]', 1784690324143);
