INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cai-tinh-trong-tiem-ca-phe', 'Cái Tình Trong Tiệm Cà Phê', 'Kopitiam Days', 'https://phimimg.com/upload/vod/20251105-1/221ddeb217bfaed72d594bc77a89c2ce.jpg', 'https://phimimg.com/upload/vod/20251105-1/36fa9e38d760914332b31f0385873162.jpg', '<p>Kỷ niệm 60 năm ngày độc lập của Singapore, Kopitiam Days là một bộ phim tuyển tập đầy cảm xúc, đan xen sáu câu chuyện liên kết với nhau về tình người, sự hòa giải và tinh thần bền bỉ của Singapore. Không chỉ là một bối cảnh, quán cà phê Kopitiam mộc mạc trở thành biểu tượng sống động của cộng đồng và ký ức, phản chiếu quá khứ, neo giữ hiện tại, và hướng đến tương lai của chúng ta.</p>', 'Full', 1, 'single', 'completed', 13, 2025, 'Vietsub', 'FHD', 'Singapore', 0, '[{"name":"Richie Koh","avatar":""},{"name":"Xenia Tan","avatar":""},{"name":"Tay Ping-Hui","avatar":""},{"name":"Jasmine Sim","avatar":""},{"name":"Chen Tian Wen","avatar":""},{"name":"Hong Huifang","avatar":""},{"name":"Zhu Houren","avatar":""},{"name":"Zaleha Hamid","avatar":""},{"name":"Siti Khalijah Zainal","avatar":""},{"name":"Iris Li","avatar":""},{"name":"Stephen Zechariah","avatar":""},{"name":"Keerthana","avatar":""},{"name":"Yang Shi Bin","avatar":""},{"name":"Yvonne Lim","avatar":""},{"name":"Jennifer Wilkinson","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b