INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ha-gom-bong-toi-cua-tam-hon', 'Ha Gom: Bóng Tối Của Tâm Hồn', 'Ha Gom: The Darkness Of The Soul', 'https://phimimg.com/upload/vod/20251105-1/d70f97d8f685c1e16b42845d88cbdc9d.jpg', 'https://phimimg.com/upload/vod/20251105-1/0ba01ca5f2c00104763d2640b0b15d99.jpg', '<p>Sau cái chết tàn khốc của cha và người bạn thân, một chàng trai trẻ bắt đầu tin rằng **một người phụ nữ trong làng bị ác linh nhập xác** chính là kẻ đứng sau những vụ giết người đó.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Kunkanit Khumkrong","avatar":""},{"name":"Worawit Chantasane","avatar":""},{"name":"Chamaiporn Sitthiworanang","avatar":""},{"name":"Jirawat Puttaramma","avatar":""},{"name":"Phanthakan Thasisang","avatar":""},{"name":"Nattarika Faodan","avatar":""},{"name":"Raksitsaraphap Sriwarasan","avatar":""},{"name":"Yasaka Chaisorn","avatar":""},{"name":"Wayne Falconer","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324143);
