INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ha-gom-bong-toi-cua-tam-hon', 'Ha Gom: Bóng Tối Của Tâm Hồn', 'Ha Gom: The Darkness Of The Soul', 'ha gom: bóng tối của tâm hồn ha gom: the darkness of the soul kunkanit khumkrong worawit chantasane chamaiporn sitthiworanang jirawat puttaramma phanthakan thasisang nattarika faodan raksitsaraphap sriwarasan yasaka chaisorn wayne falconer ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tap-kich-luc-binh-minh', 'Tập Kích Lúc Bình Minh', 'Dawn Sniper', 'https://phimimg.com/upload/vod/20251105-1/f13aa1689268d7fd20be96c2dac8a0d6.jpg', 'https://phimimg.com/upload/vod/20251105-1/63d14d1954858a26f73b3fad1a2d7ab8.jpg', '<p>Chiến hỏa xé toạc thành Ôn Châu, một cặp song sinh bước vào hai con đường đối nghịch.Diệp Ninh sa vào vòng khống chế của chủ nghĩa quân phiệt,còn Diệp Thanh lại trưởng thành thành một xạ thủ du kích huyền thoại.Khi huyết thống ruột thịt đối đầu nơi chiến trường, giữa nghĩa lớn với đất nước và tình thân cốt nhục, liệu họ sẽ lựa chọn ra sao?Bộ phim với quy mô hoành tráng tái hiện cuộc kháng chiến anh dũng, mưu trí của quân dân Ôn Châu, đồng thời đối diện sâu sắc với sự giằng xé và hy sinh trong nhân tính.Một bản anh hùng ca đẫm máu và lửa, khắc ghi lòng trung liệt, nhắc nhở giá trị của hòa bình và nỗi nhục quốc gia không bao giờ quên!</p>', 'Full', 1, 'single', 'completed', 13, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Mạch Đồng","avatar":""},{"name":"Tạ Kính Vân","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324143);
