INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngu-ngon-cua-tien-si-seuss-giong-chim-sneetch', 'Ngụ Ngôn Của Tiến Sĩ Seuss: Giống Chim Sneetch', 'Dr. Seuss''s The Sneetches', 'https://phimimg.com/upload/vod/20251105-1/c8a1941e6a780c436446c5a935030d47.jpg', 'https://phimimg.com/upload/vod/20251105-1/f3edfb517c1e5ceeda8435851ce9191c.jpg', '<p>Trong bộ phim ca nhạc đặc biệt dễ thương lấy bối cảnh vũ trụ của Seuss, hai bé chim Sneetch tạo dựng tình bạn không ngờ tới trên hòn đảo bốn bề là bãi biển.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2025, 'Vietsub + Lồng Tiếng', 'FHD', 'Ireland', 0, '[{"name":"Amari McCoy","avatar":""},{"name":"Sophie Petersen","avatar":""},{"name":"Christopher Fitzgerald","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["الدكتور سوس ذا سنيتشز","Dr Seuss Die Schnipfen","Dr. Seuss''s The Sneetches"]', 1784690324143);
