INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-thua-ke-an-danh', 'Người Thừa Kế Ẩn Danh', 'The Heiress Who Undercover', 'https://phimimg.com/upload/vod/20251105-1/d697109689eb2d95e0bf5f9a9478c343.jpg', 'https://phimimg.com/upload/vod/20251105-1/fa43cccce55946eeb88b40384ce8eaf5.jpg', '<p>Là người thừa kế duy nhất của tập đoàn tài phiệt hàng đầu Hàn Quốc, Min-ha quyết định che giấu thân phận, trải nghiệm cuộc sống công sở của người bình thường. Tuy nhiên, thứ đang chờ đợi cô lại là hàng loạt bất công và tình trạng bắt nạt nơi công sở.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 31, 2025, '', 'FHD', 'Hàn Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phim Ngắn","slug":"phim-ngan","id":"4f02d28224c0747511790d57fbb63a62"}]', '[]', 1784690324143);
