INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mon-an-thay-doi-thoi-van', 'Món Ăn Thay Đổi Thời Vận', 'Food For Lucking', 'https://phimimg.com/upload/vod/20251105-1/2948ef946bad9ffdca62e5be3931da1c.jpg', 'https://phimimg.com/upload/vod/20251105-1/9a578fdfb71fb5adcb0b2a2beb73af5d.jpg', '<p>Gần trạm dịch có một sơn trang mang tên Lạc Hoạt Sơn Trang, nơi âm thầm thu thập tin tức.Nữ chưởng quầy Điền Tân Tân thông minh, lanh lợi và hay giúp đỡ người khác;người chạy bàn Điền Đại Tráng võ công cao cường;người đánh đàn Phác Đảo Nghị từng trải, hiểu biết rộng;còn Điền Đại Nương – người giữ sổ sách – thì tinh mắt và có trí nhớ tuyệt vời.Bốn người, mỗi người đều có bí mật riêng, nhưng lại tụ họp cùng nhau.Tướng quân trẻ tuổi Phúc Tướng Quân vì đắc tội quyền quý mà bị giáng chức về trạm dịch Trung Khu,nhưng thực ra là để điều tra một vụ án trọng đại.Khi hai người dần nảy sinh tình cảm, một bức thư khẩn từ biên ải bị thất lạc,người đưa thư bị sát hại thảm thương, khiến sóng gió nổi lên trong thành Trung Khu.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cung Chính Diệp","avatar":""},{"name":"Trịnh Sơ Thần","avatar":""},{"name":"Phạm Thụy Tuyết","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324143);
