INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-tre-bi-danh-cap', 'Đứa Trẻ Bị Đánh Cắp', 'Stolen Girl', 'https://phimimg.com/upload/vod/20251007-1/097d6a3056a8f1a8c2318f2085c58b33.jpg', 'https://phimimg.com/upload/vod/20251007-1/9a64ea3aefd31eefd424ed665d5b6a48.jpg', '<p>Năm 1993, cô bé Amina, 6 tuổi, bị cha ruột là Karim bí mật đưa ra khỏi đất nước, để lại mẹ cô – Maureen – trong tuyệt vọng. Suốt nhiều năm, Maureen tìm kiếm con trong vô vọng. Cho đến khi cô gặp một người đàn ông tự xưng là “truy tìm chuyên nghiệp” — kẻ chuyên giải cứu những đứa trẻ bị bắt cóc xuyên quốc gia. Hắn hứa sẽ giúp Maureen đoàn tụ với con gái, với điều kiện cô phải hợp tác trong một phi vụ khác...</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Anh', 0, '[{"name":"Kate Beckinsale","avatar":""},{"name":"Scott Eastwood","avatar":""},{"name":"Arvin Kananian","avatar":""},{"name":"Matt Craven","avatar":""},{"name":"Ana Golja","avatar":""},{"name":"Talia Asseraf","avatar":""},{"name":"Robert Farrior","avatar":""},{"name":"Alejandra Howard","avatar":""},{"name":"Jordan Duvigneau","avatar":""},{"name":"Nowar Yusuf","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Stolen Girl"]', 1784690324143);
