INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('de-che-bao-thu', 'Đế Chế Báo Thù', 'L2: Empuraan', 'https://phimimg.com/upload/vod/20251104-1/f5c653345a273bed27e11c0fa7295de2.jpg', 'https://phimimg.com/upload/vod/20251104-1/0e64cb82472a5cc25ea29f1856ff162e.jpg', '<p>Sau nhiều năm ẩn danh, Stephen Nedumpally – kẻ hai mặt giữa chính trị gia và trùm tội phạm quốc tế Khureshi Ab’raam – buộc phải trở lại quê nhà Kerala khi thế lực mới trỗi dậy đe dọa cả chính quyền lẫn nhân dân.</p>', 'Full', 1, 'single', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Mohanlal","avatar":""},{"name":"Prithviraj Sukumaran","avatar":""},{"name":"Manju Warrier","avatar":""},{"name":"Tovino Thomas","avatar":""},{"name":"Abhimanyu Singh","avatar":""},{"name":"Sukant Goel","avatar":""},{"name":"Indrajith Sukumaran","avatar":""},{"name":"Jerome Flynn","avatar":""},{"name":"Andrea Tivadar","avatar":""},{"name":"Kishore","avatar":""},{"name":"Ériq Ebouaney","avatar":""},{"name":"Saikumar","avatar":""},{"name":"Suraj Venjaramoodu","avatar":""},{"name":"Nandhu","avatar":""},{"name":"Baiju Santhosh","avatar":""},{"name":"Karthikeya Dev","avatar":""},{"name":"Sachin Khedekar","avatar":""},{"name":"F","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["L2E","E.M.P.U.R.A.A.N","Lucifer 2","Empuraan","L2: എമ്പുരാൻ"]', 1784690324143);
