INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-thu-sau-sieu-ky-quai-2025', 'Ngày Thứ Sáu Siêu Kỳ Quái', 'Freakier Friday', 'https://phimimg.com/upload/vod/20251104-1/f027dcced97d842542fb840178f88dc8.jpg', 'https://phimimg.com/upload/vod/20251104-1/9ed5643a8a1437c2f0fb519ffd9b6a0e.jpg', '<p>Sau 22 năm, phim teen đình đám một thời “Freaky Friday” sẵn sàng trở lại với phần tiếp theo mang tên “Freakier Friday”. Giờ đây Anna đã trở thành một người mẹ, cô có một cô con gái tên Harper. Anna cũng có một cô con gái là con riêng của chồng, tên Lily, người sẽ gọi cô là mẹ kế. Lần này, phép màu không chỉ hoán đổi Anna và mẹ Tess, mà hai cô con gái cũng “nhập cuộc”. Cụ thể, Anna hoán đổi cơ thể với Harper, còn mẹ Tess hoán đổi với Lily.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Lindsay Lohan","avatar":""},{"name":"Jamie Lee Curtis","avatar":""},{"name":"Julia Butters","avatar":""},{"name":"Sophia Hammons","avatar":""},{"name":"Mark Harmon","avatar":""},{"name":"Manny Jacinto","avatar":""},{"name":"Maitreyi Ramakrishnan","avatar":""},{"name":"Christina Vidal","avatar":""},{"name":"Haley Hudson","avatar":""},{"name":"Chad Michael Murray","avatar":""},{"name":"X Mayo","avatar":""},{"name":"Lucille Soong","avatar":""},{"name":"Rosalind Chao","avatar":""},{"name":"Vanessa Bayer","avatar":""},{"name":"Jordan E. Cooper","avatar":""},{"name":"June Diane Raphae","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Freaky Friday 2","שישי הפוך 2","Sexta-Feira Muito Louca 2","Уврнути петак 2","Shuffle Friday","Nem férek a bőrödbe 2.","错位星期五","Freakier Friday"]', 1784690324143);
