INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-chuot-cau-chuyen-tho-san-quai-vat', 'Băng Chuột: Câu Chuyện Thợ Săn Quái Vật', 'The Rats: A Witcher Tale', 'https://phimimg.com/upload/vod/20251031-1/4d914f7ac794538f52c2845fddb6e395.jpg', 'https://phimimg.com/upload/vod/20251031-1/8fc83b74035151155e5217bee00677b4.jpg', '<p>Một băng nhóm gồm sáu tên trộm tuổi teen toan tính vụ trộm nguy hiểm. Nhưng khi bí mật trong quá khứ hé lộ mục đích ẩn giấu, họ nhận ra công việc này không đơn giản như bề ngoài.</p>', 'Full', 1, 'single', 'completed', 28, 2025, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dolph Lundgren","avatar":""},{"name":"Christelle Elwin","avatar":""},{"name":"Ben Radcliffe","avatar":""},{"name":"Fabian McCallum","avatar":""},{"name":"Aggy K. Adams","avatar":""},{"name":"Connor Crawford","avatar":""},{"name":"Juliette Alexandra","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Rats - A Witcher Tale","猎魔人：老鼠盗贼团","The Rats: A Witcher Tale"]', 1784690324143);
