INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-phi-xung-thien', 'Dị Phỉ Xung Thiên', 'Search For Soul Stone', 'https://phimimg.com/upload/vod/20251103-1/81eb690b54b7d2a1c191809279047983.jpg', 'https://phimimg.com/upload/vod/20251015-1/52f410e8dff2409ef23da1aa6fdfdc4c.jpg', '<p>Trong một đêm nọ vào nửa thế kỷ trước, ngọc phỉ thúy bỗng nhiên tỏa ra linh khí kỳ lạ, mở ra kỷ nguyên của những dị nhân và các gia tộc dị nhân. Gia tộc nhà họ Mạnh với khả năng cảm ứng được linh khí ngọc phỉ thúy đã bị giết sạch chỉ trong một đêm. Chàng trai trẻ Mạnh Diễm, người duy nhất còn sống sót của nhà họ Mạnh, đã cùng cô gái thần bí Tiểu Đóa nương tựa vào nhau để sinh tồn. Sáu năm sau, khi đã hoàn toàn làm chủ dị năng, Mạnh Diễm bắt đầu hành trình báo thù, khơi mào trận chiến xuyên hai thế hệ giữa những dị nhân – nơi máu, thù hận và sức mạnh giao thoa.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hạ Chí Viễn","avatar":""},{"name":"Bàn Khởi Ngôn","avatar":""},{"name":"Tôn Cảnh Tâm","avatar":""},{"name":"Tôn Dật Nghiệp","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["异翡冲天"]', 1784690324143);
