INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-nghin-ty-2025', 'Trò Chơi Nghìn Tỷ', 'Trillion Game The Movie', 'https://phimimg.com/upload/vod/20251103-1/96f2a5aa1a29345d649994836bbc2335.jpg', 'https://phimimg.com/upload/vod/20251103-1/df876cd3a8c1b00daaf19bffb516929b.jpg', '<p>Haru Tennoji và Manabu “Gaku” Taira lại một lần nữa bắt đầu hành trình chinh phục mục tiêu điên rồ — kiếm 1 nghìn tỷ đô la và sở hữu mọi thứ trên thế giới. Lần này, Haru hướng ánh nhìn tới một lĩnh vực hoàn toàn mới: xây dựng khu nghỉ dưỡng sòng bạc đầu tiên tại Nhật Bản. Liệu những chiến lược khó lường và những màn “bluff” đỉnh cao của Haru và Gaku có đủ để họ chạm tới con số 1 nghìn tỷ đô, hay đây sẽ là ván cược khiến tất cả sụp đổ?</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ren Meguro","avatar":""},{"name":"Hayato Sano","avatar":""},{"name":"Mio Imada","avatar":""},{"name":"Riko Fukumoto","avatar":""},{"name":"Koji Kikkawa","avatar":""},{"name":"Kosuke Suzuki","avatar":""},{"name":"Kenjiro Tsuda","avatar":""},{"name":"Terunosuke Takezai","avatar":""},{"name":"Yoshitaka Hara","avatar":""},{"name":"Akari Akase","avatar":""},{"name":"Jun Kunimura","avatar":""},{"name":"Kavka Shishido","avatar":""},{"name":"Seiichi Tanabe","avatar":""},{"name":"Ryo Ishibashi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Gekijou Ban Toririon Geemu","劇場版 トリリオンゲーム"]', 1784690324143);
