INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tro-choi-nghin-ty-2025', 'Trò Chơi Nghìn Tỷ', 'Trillion Game The Movie', 'trò chơi nghìn tỷ trillion game the movie ren meguro hayato sano mio imada riko fukumoto koji kikkawa kosuke suzuki kenjiro tsuda terunosuke takezai yoshitaka hara akari akase jun kunimura kavka shishido seiichi tanabe ryo ishibashi gekijou ban toririon geemu 劇場版 トリリオンゲーム', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lich-su-am-thanh', 'Lịch Sử Âm Thanh', 'The History Of Sound', 'https://phimimg.com/upload/vod/20251103-1/0be61ac12089baffe24e340be628bc6d.jpg', 'https://phimimg.com/upload/vod/20251103-1/26af7dda606cf25acecc9a65c5253c43.jpg', '<p>Boston, năm 1917. Giữa tiếng đàn ngân vang trong hành lang nhạc viện, hai tâm hồn trẻ tìm thấy nhau qua những giai điệu dân gian mộc mạc. Nhiều năm sau, định mệnh đưa họ tái ngộ, lần này, không phải trong phòng học, mà trên những con đường phủ sương miền Maine. Một trái tim đầy nhiệt thành với âm nhạc, họ lên đường tìm lại âm thanh nguyên sơ của nước Mỹ trong dòng chảy thời gian — một hành trình âm nhạc, ký ức và tình cảm vượt thời gian.</p>', 'Full', 1, 'single', 'completed', 27, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Paul Mescal","avatar":""},{"name":"Josh O''Connor","avatar":""},{"name":"Molly Price","avatar":""},{"name":"Alison Bartlett","avatar":""},{"name":"Michael Schantz","avatar":""},{"name":"Chris Cooper","avatar":""},{"name":"Raphael Sbarge","avatar":""},{"name":"Hadley Robinson","avatar":""},{"name":"Peter Mark Kendall","avatar":""},{"name":"Emma Canning","avatar":""},{"name":"Gary Raymond","avatar":""},{"name":"Alessandro Bedetti","avatar":""},{"name":"Michael D. Xavier","avatar":""},{"name":"Aidan Redmond","avatar":""},{"name":"Aedin Moloney","avatar":""},{"name":"Leo Cocovin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["บันทึกเสียงร้องก้องโลก","The History of Sound"]', 1784690324143);
