INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-tau-ho-yeu', 'Hoàng Tẩu Hồ Yêu', 'My Foxfoe Queen', 'https://phimimg.com/upload/vod/20251024-1/458cee99f8aaf666544eb40890334999.jpg', 'https://phimimg.com/upload/vod/20251024-1/d0d556870ef52df0a25bccb7ac43a4b2.jpg', '<p>Toàn tộc Hồ bị Dực Vương Tây Lăng – Tây Lăng Hiên tàn sát. Thánh nữ của Hồ tộc, Đồ Sơn Nguyệt, giữ lại được một tia tàn hồn, đuổi theo đến hoàng cung Tây Lăng để tìm Tây Lăng Hiên báo thù. Tàn hồn của Đồ Sơn Nguyệt nhập vào thân thể của Hoàng hậu Khương Hinh Nhi – người vừa qua đời ngoài ý muốn. Khi kế hoạch báo thù dần tiến triển, Đồ Sơn Nguyệt phát hiện ra một sự thật kinh hoàng.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Từ Chẩn Chẩn","avatar":""},{"name":"Cảnh Nghiệp Đình","avatar":""},{"name":"Trương Vân Khánh","avatar":""},{"name":"Ngô Tịnh Hâm","avatar":""},{"name":"Ngải Dịch","avatar":""},{"name":"Lý Thuần Nhĩ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hu Yao Huang Sao","Fox Demon Queen","狐妖皇嫂"]', 1784690324143);
