INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoang-tau-ho-yeu', 'Hoàng Tẩu Hồ Yêu', 'My Foxfoe Queen', 'hoàng tẩu hồ yêu my foxfoe queen từ chẩn chẩn cảnh nghiệp đình trương vân khánh ngô tịnh hâm ngải dịch lý thuần nhĩ hu yao huang sao fox demon queen 狐妖皇嫂', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thai-hau-co-hy', 'Thái Hậu Có Hỷ', 'The Empress Dowager on a Second Spring', 'https://phimimg.com/upload/vod/20251018-1/aacd429db92a833de3d7c048b7a7be3f.jpg', 'https://phimimg.com/upload/vod/20251018-1/36ba9c74ea4bbff54c5498ceb840d023.jpg', '<p>Câu chuyện kể về Giang Dung, một sản phụ trong lúc sinh con gặp nguy kịch và bất ngờ hôn mê. Khi tỉnh dậy, cô phát hiện mình đã xuyên không trở thành Hoàng Thái hậu và vừa hạ sinh một bé trai. Tuy nhiên, do mất trí nhớ, cô không biết cha của đứa trẻ là ai, mà việc một góa phụ sinh con lại là điều đại kỵ trong cung đình.Để bảo toàn mạng sống và tìm ra sự thật, Giang Dung buộc phải khéo léo đối phó với ba người đàn ông — đều là nghi phạm có thể là cha của đứa trẻ. Trong quá trình đó, cô dần phát hiện bí mật đằng sau mọi chuyện, đồng thời nảy sinh nhiều tình cảm rối ren và những tình huống dở khóc dở cười, tạo nên một câu chuyện xuyên không hài hước nhưng cũng đầy ấm áp và cảm động.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Duyệt Nam","avatar":""},{"name":"Vương Hiên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Tai Hou You Xi","太后有喜"]', 1784690324143);
