INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-hoan-hao', 'Tình Yêu Hoàn Hảo', 'Perfect Love', 'https://phimimg.com/upload/vod/20251102-1/c0402647f410fe1f0f1a83fba1b27b08.jpg', 'https://phimimg.com/upload/vod/20251102-1/2a4c7aa631e16bc8573c66b6dd0f464a.jpg', '<p>Trong thời đại mà bạn trai hoàn hảo không tự nhiên xuất hiện, cô chủ quán cà phê Yoo Jin chưa tìm thấy mẫu hình lý tưởng đã quyết định tự tay tạo ra mẫu hình lý tưởng đó và đặt hàng một AI người ảo tùy chỉnh trên một trang web. Mặc dù đã trải qua khoảng thời gian ngọt ngào với &quot;Jay&quot;, người bạn trai AI lý tưởng hoàn hảo, nhưng cô dần cảm thấy nhàm chán vì tính cách cứng nhắc quá mức hoàn hảo, và cuối cùng đã ruồng bỏ anh. Khi nỗi nhớ lan dần, với sự giúp đỡ của cặp đôi bạn mình, Yoo Jin đã phát hiện ra bí mật rằng &quot;Jay&quot; có một nguyên mẫu là con người thật. Sau khi gặp gỡ Woo Joon, một người đàn ông có ngoại hình hoàn toàn giống hệt Jay, hai người nhanh chóng rút ngắn khoảng cách và bắt đầu một mối tình mới. Tuy nhiên, khi Woo Joon tình cờ biết được rằng &quot;người yêu cũ&quot; của Yoo Jin chính là &quot;Jay&quot;, bản sao của mình, mối quan hệ này lại một lần nữa đứng trước nguy cơ tan vỡ.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 26, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phim Ngắn","slug":"phim-ngan","id":"4f02d28224c0747511790d57fbb63a62"}]', '[]', 1784690324143);
