INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vampirina-ma-ca-rong-tuoi-teen', 'Vampirina: Ma Cà Rồng Tuổi Teen', 'Vampirina: Teenage Vampire', 'https://phimimg.com/upload/vod/20251010-1/942c9a3eb3d597c3d3f36281be89c9a3.jpg', 'https://phimimg.com/upload/vod/20251010-1/61ed9de76bc92e88b8e2e9821d49a9ab.jpg', '<p>Một cô bé ma cà rồng tuổi tween rời khỏi vùng an toàn ở Transylvania để theo học tại trường nội trú nghệ thuật biểu diễn dành cho con người. Lần đầu sống giữa thế giới loài người, cô vừa theo đuổi đam mê âm nhạc, vừa phải giấu kín thân phận ma cà rồng của mình. Mọi chuyện càng thêm rắc rối khi người cha quá bảo bọc cử một hồn ma nhiệt tình thái quá đến sống cùng cô ở trường — biến mỗi ngày thành một chuỗi hỗn loạn giữa bí mật, âm nhạc và tình bạn.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kenzie Richardson","avatar":""},{"name":"Jiwon Lee","avatar":""},{"name":"Faith Hedley","avatar":""},{"name":"Shaun Dixon","avatar":""},{"name":"Milo Maharlika","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Vampirina: Tini vámpír","Vampirina","Vampirina: Teenage Vampire"]', 1784690324143);
