INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vampirina-ma-ca-rong-tuoi-teen', 'Vampirina: Ma Cà Rồng Tuổi Teen', 'Vampirina: Teenage Vampire', 'vampirina: ma cà rồng tuổi teen vampirina: teenage vampire kenzie richardson jiwon lee faith hedley shaun dixon milo maharlika vampirina: tini vámpír vampirina vampirina: teenage vampire', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lenh-truy-na-sinh-tu-2025', 'Lệnh Truy Nã Sinh Tử', 'Desperate Warrant', 'https://phimimg.com/upload/vod/20251031-1/02a058fdf80f3f1874f7cedf87ce3bbe.jpg', 'https://phimimg.com/upload/vod/20251031-1/4afa96fc849cf58542a9d92675fef64c.jpg', '<p>Trong khung cảnh đậm chất Đông Nam Á tại Sumanlai, ẩn giấu những dòng chảy ngầm nguy hiểm của tội phạm xuyên quốc gia và thế giới ngầm của các sòng bạc. Kỹ sư mạng Tô Tiểu Đường vốn có cuộc sống bình dị, nhưng khi em gái Bạch Băng Vũ mất tích ở nước ngoài, cô quyết định lên đường truy tìm tung tích. Trong hành trình sang nước ngoài điều tra, Tô Tiểu Đường đã thâm nhập vào khách sạn Âu Sa – nơi em gái từng xuất hiện lần cuối – và vô tình bị cuốn vào vòng xoáy trả thù điên cuồng. Giữa hiểm nguy cận kề, cô vẫn giữ lòng nhân hậu, và chính sự thiện lương ấy đã trở thành lá bùa hộ mệnh giúp cô nhiều lần thoát chết, đồng thời khơi dậy năng lực đặc biệt – khả năng dự đoán đường đi nước bước của đối phương. Từ việc vạch trần âm mưu rửa tiền tại khách sạn – sòng bạc, lần theo manh mối em gái bị bán đến Trang viên Hoa Hồng, cho đến khi xâm nhập vào tổng hành dinh trùm ma túy, Tô Tiểu Đường luôn kiên định với chính nghĩa. Trong lúc bị Thoát Na truy sát và Kim Gia dụ dỗ, cô vẫn không lùi bước. Cuối cùng, Tô Tiểu Đường hợp tác cùng Interpol, triệt phá tổ chức tội phạm quốc tế và giải cứu em gái thành công.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngô Thiên Ngữ","avatar":""},{"name":"Đỗ Hải Thao","avatar":""},{"name":"Huái Văn","avatar":""},{"name":"Dược Nhất Tùng","avatar":""},{"name":"Vương Miên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["绝境通缉令"]', 1784690324143);
