INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-ballad-cua-tay-bac-nho', 'Bản Ballad Của Tay Bạc Nhỏ', 'Ballad Of A Small Player', 'https://phimimg.com/upload/vod/20251030-1/9a37052165f488dd4661b5f8be6be438.jpg', 'https://phimimg.com/upload/vod/20251030-1/8f26356970837ee7a1fabf9aa7abc1aa.jpg', '<p>Giữa những sòng bạc hào nhoáng ở Macau, con bạc đang trốn chạy khỏi quá khứ – và nợ nần – bỗng si mê người phụ nữ bí ẩn tại bàn chơi bài baccarat.</p>', 'Full', 1, 'single', 'completed', 11, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Đức', 0, '[{"name":"Colin Farrell","avatar":""},{"name":"Fala Chen","avatar":""},{"name":"Tilda Swinton","avatar":""},{"name":"Deanie Ip","avatar":""},{"name":"Alex Jennings","avatar":""},{"name":"Jason Tobin","avatar":""},{"name":"Adrienne Lau","avatar":""},{"name":"Anthony Wong Chau-Sang","avatar":""},{"name":"Jessica Lai","avatar":""},{"name":"Margaret Cheung","avatar":""},{"name":"Alan K. Chang","avatar":""},{"name":"Selena Fong","avatar":""},{"name":"Christina Yong","avatar":""},{"name":"Suen Tsz-Wai","avatar":""},{"name":"Suki Wong","avatar":""},{"name":"Kwok Wai-Yan","avatar":""},{"name":"Willy Wong","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Ballad of a Small Player","Maldita suerte : 2025","Ballad of a Small Player"]', 1784690324143);
