INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoai-tam-truy-vet', 'Ngoài Tầm Truy Vết', 'Off The Grid', 'https://phimimg.com/upload/vod/20250709-1/1667243a1f8942325b91f7f40cdcc2eb.jpg', 'https://phimimg.com/upload/vod/20250709-1/7b8402c64b2b888e345e2c2228a0372a.jpg', '<p>Sau khi một tập đoàn vô đạo đức cố gắng biến công nghệ mang tính cách mạng của một nhà khoa học thiên tài thành vũ khí, anh quyết định &quot;ẩn mình&quot; để bảo vệ nhân loại. Nhưng khi tập đoàn này cử một đội truy bắt tinh nhuệ để tìm anh, họ đã phạm sai lầm lớn nhất: biến chính người họ muốn bắt thành thứ vũ khí nguy hiểm nhất.</p>', 'Full', 1, 'single', 'completed', 17, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Ý', 0, '[{"name":"Josh Duhamel","avatar":""},{"name":"Peter Stormare","avatar":""},{"name":"Greg Kinnear","avatar":""},{"name":"Michael Papajohn","avatar":""},{"name":"Ana Golja","avatar":""},{"name":"Talia Asseraf","avatar":""},{"name":"David Lipper","avatar":""},{"name":"María Elisa Camargo","avatar":""},{"name":"Ricky Russert","avatar":""},{"name":"Joe Bucaro III","avatar":""},{"name":"Michael Zapesotsky","avatar":""},{"name":"Paul Sampson","avatar":""},{"name":"Kipp Tribble","avatar":""},{"name":"Monya Tebji","avatar":""},{"name":"Calvin Williams","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["מתחת לרדאר","Off the Grid"]', 1784690324143);
