INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hung-thoi-tan-the', 'Người Hùng Thời Tận Thế', 'Afterburn', 'https://phimimg.com/upload/vod/20251024-1/d0e08620eba2690019434888cd4d7fa4.jpg', 'https://phimimg.com/upload/vod/20251024-1/52013200358dab421e8ca1fcd7e6d920.jpg', '<p>Sau một trận bão mặt trời tàn phá bán cầu Đông của Trái Đất, nhân loại rơi vào hỗn loạn. Giữa đống đổ nát, một thợ săn kho báu liều lĩnh lên đường đến châu Âu để truy tìm bức tranh Mona Lisa. Nhưng hành trình nhanh chóng vượt khỏi mục tiêu ban đầu – giờ đây, anh phải trở thành người hùng mà thế giới đang tuyệt vọng cần đến.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dave Bautista","avatar":""},{"name":"Olga Kurylenko","avatar":""},{"name":"Kristofer Hivju","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Daniel Bernhardt","avatar":""},{"name":"Eden Epstein","avatar":""},{"name":"George Somner","avatar":""},{"name":"Sergio Freijo","avatar":""},{"name":"Lukáš Frlajs","avatar":""},{"name":"Phil Zimmerman","avatar":""},{"name":"Robert Holik","avatar":""},{"name":"Paula Argüelles","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Cazadores Del Fin Del Mundo","Aardekütid","Világvége után","Истлевшее","Luka Bakar Setelahnya","Afterburn"]', 1784690324143);
