INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mo-amer-the-gioi-hung-bao', 'Mo Amer: Thế Giới Hung Bạo', 'Mo Amer: Wild World', 'https://phimimg.com/upload/vod/20251101-1/ba2e65e8243e70a64bc7709e7d101a77.jpg', 'https://phimimg.com/upload/vod/20251101-1/8f97038f08b576a4c0ef4a3b7a3722e4.jpg', '<p>Trong chương trình hài đặc biệt đầy chân thật này, Mo Amer tôn vinh nguồn gốc Palestine của mình, kể lại những cuộc chạm trán trên đường lưu diễn và hồi tưởng hành trình trở thành một người cha.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mo Amer","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Mo Amer: Wild World"]', 1784690324143);
