INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ua-suyt-chia-tay-roi', 'Ủa? Suýt Chia Tay Rồi!', 'Oops! Almost Broke Up', 'https://phimimg.com/upload/vod/20251029-1/eac008c5bafeb8312f94d586cb0a5674.jpg', 'https://phimimg.com/upload/vod/20251029-1/99c75c2eda4cb788ce5585e937313dba.jpg', '<p>Bộ phim kể về Trần Gia Vân và Thẩm Mộng, một cặp đôi đã yêu nhau bốn năm nhưng lại chia tay đúng vào ngày 20 tháng 5. Tuy nhiên, sau khi tỉnh dậy, họ phát hiện mình bị mắc kẹt trong một vòng lặp thời gian vô tận — ngày chia tay cứ lặp đi lặp lại.Họ cố gắng mọi cách để thoát ra nhưng đều thất bại, cho đến khi kích hoạt được một “nhiệm vụ ẩn”. Những lời thề non hẹn biển từng nói trong quá khứ giờ trở thành chuỗi thử thách cảm xúc và niềm tin: từ việc không thể chia xa, hoán đổi công việc, đến việc đối mặt với người yêu cũ.Trong quá trình đó, những mâu thuẫn và vấn đề sâu kín trong mối quan hệ dần được phơi bày. Cuối cùng, họ nhận ra giá trị thật sự của tình yêu và nắm tay nhau bước ra khỏi vòng lặp, mở ra một khởi đầu mới cho mối tình của mình.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hani Kyzy","avatar":""},{"name":"Tiếu Khải Trung","avatar":""},{"name":"Vu Dương","avatar":""},{"name":"Tăng Mộng Tuyết","avatar":""},{"name":"Vương Y Dao","avatar":""},{"name":"Đái Yên Ni","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ei Cha Dian Zhen Fen Le","We Almost Broke Up","Oops, We Almost Broke Up","That Was A Close Call We Almost Broke Up","Oops! Almost Broke Up","诶？差点真分了！"]', 1784690324143);
