INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ua-suyt-chia-tay-roi', 'Ủa? Suýt Chia Tay Rồi!', 'Oops! Almost Broke Up', 'ủa? suýt chia tay rồi! oops! almost broke up hani kyzy tiếu khải trung vu dương tăng mộng tuyết vương y dao đái yên ni ei cha dian zhen fen le we almost broke up oops, we almost broke up that was a close call we almost broke up oops! almost broke up 诶？差点真分了！', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kieu-the-phuong-nien-ky', 'Kiều Thê Phương Niên Kỷ', 'Keeping Up With Beauty', 'https://phimimg.com/upload/vod/20251021-1/9ade48db7d9b6b6619dd267dc94180e8.jpg', 'https://phimimg.com/upload/vod/20251021-1/2dd333e1575c789a00404597810d5eee.jpg', '<p>Sau khi vị tướng dũng cảm tên là Phó Vân Vân xuyên vào cơ thể của một nữ thừa kế giàu có, cô bị vướng vào một mạng lưới tình yêu và lừa dối. Trong hành trình tìm kiếm sự thật đằng sau một lời hứa cổ xưa, Phó Vân Vân phải dựa vào sức mạnh và trí tuệ của mình để tìm thấy vị trí của mình trong một thế giới vừa quen thuộc vừa xa lạ.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Quách Già Nam","avatar":""},{"name":"Tống Phương Viên","avatar":""},{"name":"Từ Mưu Tuấn","avatar":""},{"name":"Ổ Thiến","avatar":""},{"name":"Văn Uy Đăng","avatar":""},{"name":"Cát Vị Ngâm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["娇妻芳龄几许"]', 1784690324143);
