INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-ay-trong-dem-toi', 'Cô Ấy Trong Đêm Tối', 'Queen Of Darkness', 'https://phimimg.com/upload/vod/20251023-1/08b7db687d2138dec09afa7da5f635ba.jpg', 'https://phimimg.com/upload/vod/20251023-1/2efec9b241031e67762fd2d38e81239a.jpg', '<p>Sau một tai nạn xe hơi khiến nữ thừa kế Diệp Oánh bị mất trí nhớ, cô bị nhầm là một bà nội trợ tên An Ninh và buộc phải sống với một gia đình xa lạ. Dựa vào bản năng sinh tồn, cô dần bị thu hút bởi thanh tra Hoắc Tiêu, ngay cả khi những bí mật và sự lừa dối bủa vây họ. Khi ký ức trở lại, Diệp Oánh phải lựa chọn giữa sự an toàn của cuộc sống giả tạo và sự thật nguy hiểm đang chờ được khám phá.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Phương Cẩn","avatar":""},{"name":"Nghiêm Tử Hiền","avatar":""},{"name":"Phổ Vũ Đồng","avatar":""},{"name":"Lý Trạch Vũ","avatar":""},{"name":"Diệm Diễn","avatar":""},{"name":"Hành Văn Kiệt","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hei Ye Zhong De Ta","黑夜中的她"]', 1784690324143);
