INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ncis-tony-ziva', 'NCIS: Tony & Ziva', 'NCIS: Tony & Ziva', 'https://phimimg.com/upload/vod/20250909-1/f1c0ab647d1f3f2ef3c697d53c7c64b3.jpg', 'https://phimimg.com/upload/vod/20250909-1/e6156c5c1f14b1182a2e36f3d4a333fb.jpg', '<p>Khi công ty an ninh của Tony bị tấn công, anh và Ziva buộc phải chạy trốn khắp châu Âu, vừa tìm cách truy ra kẻ đứng sau, vừa học cách tin tưởng nhau một lần nữa — để có thể chạm tới cái kết hạnh phúc đầy khác biệt của riêng họ.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Michael Weatherly","avatar":""},{"name":"Cote de Pablo","avatar":""},{"name":"Isla Gie","avatar":""},{"name":"Amita Suman","avatar":""},{"name":"Maximilian Osinski","avatar":""},{"name":"Anne-Marie Waldeck","avatar":""},{"name":"Nassima Benchicou","avatar":""},{"name":"Julian Ovenden","avatar":""},{"name":"Terence Maynard","avatar":""},{"name":"Lara Rossi","avatar":""},{"name":"James D''Arcy","avatar":""},{"name":"Emmanuel Bonami","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["NCIS - Tony und Ziva","NCIS: Tony & Ziva","NCIS: טוני וזיוה","NCIS: Europe","NCIS: Trust No One","NCIS: Tony and Ziva"]', 1784690324143);
