INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-lanh-cua-eun-soo', 'Ngày Lành Của Eun Soo', 'Walking On Thin Ice', 'https://phimimg.com/upload/vod/20250922-1/1bb6126af6f261bd8a58f2f5c83bbb10.jpg', 'https://phimimg.com/upload/vod/20250922-1/b64c3cd486edda0bf9f0aa63094031f0.jpg', '<p>Eun-soo là một người nội trợ, chật vật xoay xở để trang trải chi phí chữa bệnh cho người chồng mắc bệnh nan y. Trong lúc tuyệt vọng, cô vô tình dính líu đến một túi ma túy cùng với Yi-kyeong – một thầy giáo bí ẩn. Từ đó, Eun-soo và Yi-kyeong bị truy đuổi gắt gao bởi Tae-gu, một viên cảnh sát kỳ cựu.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 9, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Young-ae","avatar":""},{"name":"Kim Young-kwang","avatar":""},{"name":"Park Yong-woo","avatar":""},{"name":"Lee Soo-bin","avatar":""},{"name":"Jo Yeon-hee","avatar":""},{"name":"Hwang Jae-yeol","avatar":""},{"name":"Do Sang-woo","avatar":""},{"name":"Won Hyun-jun","avatar":""},{"name":"Oh Yeon-ah","avatar":""},{"name":"Kim Dong-won","avatar":""},{"name":"Lee Kyu-sung","avatar":""},{"name":"Kim Si-a","avatar":""},{"name":"Kwon Ji-woo","avatar":""},{"name":"Son Bo-seung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Eunsoo Joeun Nal","은수 좋은 날","Удачный день Ын Су","المشي على الجليد الرقيق","Walking on Thin Ice"]', 1784690324143);
