INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('keo-tay-ba', 'Kèo Tay Ba', 'The Threesome', 'https://phimimg.com/upload/vod/20251031-1/2babef995082984610293fcd93f9c8eb.jpg', 'https://phimimg.com/upload/vod/20251031-1/9ad1ae577502891b70c5cbe769e6b8e4.jpg', '<p>Connor và cô bạn thân mà anh thầm thương bấy lâu, Olivia, bất ngờ có một đêm ân ái cùng Jenny - một cô gái xa lạ ngọt ngào và cuốn hút. Cuộc gặp gỡ táo bạo ấy mở đầu cho mối quan hệ tình cảm giữa Connor và Olivia, đưa họ đến kế hoạch xây dựng một tương lai chung. Thế nhưng, khi Jenny bất ngờ quay trở lại, ba người bị cuốn vào hành trình đầy thử thách về trách nhiệm, tình yêu và sự trưởng thành.</p>', 'Full', 1, 'single', 'completed', 4, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Zoey Deutch","avatar":""},{"name":"Jonah Hauer-King","avatar":""},{"name":"Ruby Cruz","avatar":""},{"name":"Jaboukie Young-White","avatar":""},{"name":"Josh Segarra","avatar":""},{"name":"Robert Longstreet","avatar":""},{"name":"Arden Myrin","avatar":""},{"name":"Kristin Slaysman","avatar":""},{"name":"Allan McLeod","avatar":""},{"name":"Julia Sweeney","avatar":""},{"name":"Tommy Do","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Beso de Tres","Entre Nós","Plan à Trois","The Threesome"]', 1784690324143);
