INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hedda', 'Hedda', 'Hedda', 'https://phimimg.com/upload/vod/20251031-1/89956d5ceffcf3f4446dd8d2e82d413b.jpg', 'https://phimimg.com/upload/vod/20251031-1/33146c17c32477b616096b786c8f8394.jpg', '<p>Hedda Gabler giằng xé giữa nỗi đau còn vương của mối tình xưa và sự ngột ngạt âm thầm trong cuộc sống hiện tại. Trong suốt một đêm đầy kịch tính, những khao khát bị dồn nén và các bí mật bị chôn giấu bùng nổ, cuốn cô – và cả những người quanh mình – vào vòng xoáy của mưu toan, đam mê và phản bội.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tessa Thompson","avatar":""},{"name":"Nina Hoss","avatar":""},{"name":"Imogen Poots","avatar":""},{"name":"Nicholas Pinnock","avatar":""},{"name":"Tom Bateman","avatar":""},{"name":"Finbar Lynch","avatar":""},{"name":"Mirren Mack","avatar":""},{"name":"Jamael Westman","avatar":""},{"name":"Saffron Hocking","avatar":""},{"name":"Kathryn Hunter","avatar":""},{"name":"Michelle Crane","avatar":""},{"name":"Sam Hoare","avatar":""},{"name":"Stacey Gough","avatar":""},{"name":"Mark Oosterveen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Хедда","Hedda : 2025","Hedda"]', 1784690324143);
