INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-tren-bo-vuc', 'Cô Gái Trên Bờ Vực', 'Girl On Edge', 'https://phimimg.com/upload/vod/20251031-1/c0204a8274249e95e9c370e9926c3f29.jpg', 'https://phimimg.com/upload/vod/20251031-1/edd7beab60c6abef81e052a91a34e24b.jpg', '<p>Giang Ninh (Trương Tử Phong), một thiếu nữ trượt băng nghệ thuật tài năng thiên bẩm, dần mất kiểm soát dưới sự khống chế của kế hoạch bệnh hoạn từ người mẹ Vương Sương (Mã Y Lợi). Sự xuất hiện của Chung Linh (Đinh Tương Nguyên), một thiên tài trượt băng khác, trở thành ngòi nổ phá vỡ sự bình yên giả tạo trong mối quan hệ mẹ con Giang Ninh. Một kế hoạch trả thù điên cuồng bắt đầu diễn ra.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Tử Phù","avatar":""},{"name":"Đinh Tương Nguyên","avatar":""},{"name":"Mã Y Lý","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["花滑少女","Life on Edge","花漾少女杀人事件"]', 1784690324143);
