INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mac-kim-quyet-thien-tinh-lang', 'Mạc Kim Quyết: Thiên Tinh Lăng', 'Tomb Raiders: Secrets Of Tianxing Tomb', 'https://phimimg.com/upload/vod/20251031-1/03121989bd38bb49d76f921576082205.jpg', 'https://phimimg.com/upload/vod/20251031-1/fcf0f5ab47f0ad52d560b0773baa2ec7.jpg', '<p>Giữa thời Liêu, Đoàn Xương Vũ được phong làm Kim Viện vương, chuyên phụ trách việc đào vàng cho Chư Tuyên vương để cung ứng quân lương, nhờ đó mà được xưng là “Hoàng Kim Đại tướng quân”. Cuối đời Liêu, năm ngôi sao tụ hội, một thiên thạch tím rơi xuống nhân gian, hóa thành đá cát tường Đại Tiên Sơn, bị Đoàn Xương Vũ chiếm giữ. Sau khi ông qua đời, thi thể được đặt trong Thiên Tinh Quan, tương truyền có năng lực cải tử hoàn sinh. Hồ Bát Nhất, Vương mập và Giáo sư Kim lên núi Đại Tiên khảo sát Thiên Tinh Lăng, vô tình chạm trán ngôi mộ tà ngàn năm cùng Tứ Quỷ Đà Quan, từ đó vén màn bí mật bị chôn vùi suốt nhiều năm…</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Thiên Văn","avatar":""},{"name":"Từ Hồng Khiết","avatar":""},{"name":"Dương Nãi Thanh","avatar":""},{"name":"Lưu Chiêm Khuê","avatar":""},{"name":"Tôn Giao Long","avatar":""},{"name":"Tân Nguyên Chu","avatar":""},{"name":"Phó Nam","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Golden Talisman: Star Tomb","摸金玦之鬼门天师","摸金玦电影","摸金玦之天星陵"]', 1784690324143);
