INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-noi-tru-ngoai-khoa', 'Bác Sĩ Nội Trú Ngoại Khoa', 'Road To Surgeon', 'https://phimimg.com/upload/vod/20251031-1/49a7feea2015f67f5904da4125c0b5a1.jpg', 'https://phimimg.com/upload/vod/20251031-1/0f2dcee48d69dfe885ec3a7f418ba631.jpg', '<p>Bộ phim kể về hành trình của một bác sĩ nội trú năm nhất bất ngờ mất tích. Một người anh đồng nghiệp quyết định lên đường tìm kiếm người em này. Trên hành trình đó, họ đối mặt với những khó khăn giữa lý tưởng và thực tế trong môi trường y khoa khắc nghiệt. Qua đó, câu chuyện khắc họa quá trình trưởng thành, tình bạn và sự đồng cảm giữa những người trẻ tuổi đang theo đuổi ước mơ trở thành bác sĩ.</p>', 'Hoàn Tất (2/2)', 2, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Gun-woo","avatar":""},{"name":"Lee Won-jeong","avatar":""},{"name":"Jeong Sin-hye","avatar":""},{"name":"Kim Nam-hee","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["O''PENing(오프닝) - 로드 투 외과의사"]', 1784690324143);
