INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('shin-cam-chao-pha-dao-khu-pho-bac-thay-hoa-giai', 'Shin Cầm Chảo, Phá Đảo Khu Phố (Bậc Thầy Hòa Giải)', 'Shin''s Project', 'https://phimimg.com/upload/vod/20250916-1/a38524bf4460c59088116e0e9e1fc059.jpg', 'https://phimimg.com/upload/vod/20250916-1/6f13a503a95efdbdd1413e8668a4413b.jpg', '<p>Bậc Thầy Hòa Giải (Shin&#39;s Project) theo chân một chuyên gia đàm phán tiếng tăm lẫy lừng nhưng hiện đã giải nghệ về làm chủ một quán gà rán bình dân. Dù đã giấu kín thân phận và quá khứ, ông vẫn liên tục bị cuốn vào đủ loại tranh chấp trong khu phố, từ những người hàng xóm ồn ào, các vụ kiện phiền toái đến cả xung đột tình cảm. Với tài ăn nói điêu luyện, ông hóa giải mọi mâu thuẫn và còn đứng lên chống lại những bất công, mang đến nguồn năng lượng tích cực cho cộng đồng.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Han Suk-kyu","avatar":""},{"name":"Bae Hyeon-seong","avatar":""},{"name":"Lee Re","avatar":""},{"name":"Kim Seung-o","avatar":""},{"name":"Woo Mi-hwa","avatar":""},{"name":"Kim Sang-ho","avatar":""},{"name":"Jung Eun-pyo","avatar":""},{"name":"Woo Hyeon","avatar":""},{"name":"Jo Hyun-sik","avatar":""},{"name":"Lee Ji-ha","avatar":""},{"name":"Jeon Kuk-hwan","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["پروژه شین","Shin''s Project","New President Project","신사장 프로젝트"]', 1784690324143);
