INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-dien', 'Nhân Diện', 'The Ugly', 'https://phimimg.com/upload/vod/20251030-1/d356f12e06f1977d3eba2ef8811f5491.jpg', 'https://phimimg.com/upload/vod/20251030-1/8054fab9c57958ab8911519d740650aa.jpg', '<p>Im Dong-hwan, chàng trai chưa từng biết mặt mẹ mình, bàng hoàng khi cảnh sát thông báo đã tìm thấy hài cốt của bà – người mất tích suốt 40 năm – với nghi ngờ bị sát hại. Anh quyết tâm đi tìm sự thật cùng nữ đạo diễn Kim Soo-jin, người đang thực hiện phim tài liệu về cha anh – nghệ nhân làm dấu mù lòa từ khi sinh ra. Họ lần theo ký ức của những người từng làm việc với bà tại xưởng may năm xưa, để dần vén màn bí mật được chôn giấu suốt bốn thập kỷ.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Jeong-min","avatar":""},{"name":"Kwon Hae-hyo","avatar":""},{"name":"Shin Hyun-been","avatar":""},{"name":"Han Ji-hyeon","avatar":""},{"name":"Im Sung-jae","avatar":""},{"name":"Kim Jae-rok","avatar":""},{"name":"Cha Mi-kyeong","avatar":""},{"name":"Joo Hae-eun","avatar":""},{"name":"Won Mi-won","avatar":""},{"name":"Park Myung-shin","avatar":""},{"name":"Lee Hyun-kyun","avatar":""},{"name":"Go Seo-hee","avatar":""},{"name":"Go Dong-eop","avatar":""},{"name":"Hong Seok-bin","avatar":""},{"name":"Kim Hye-jung","avatar":""},{"name":"Lee Han-sol","avatar":""},{"name":"Seo Suk-kyu","avatar":""},{"name":"Ha Si-yeon","avatar":""},{"name":"Han S","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["丑得要命","얼굴"]', 1784690324143);
