INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-la-tieu-hac-2-la-tieu-hac-chien-ky-2', 'Huyền Thoại La Tiểu Hắc 2 (La Tiểu Hắc Chiến Ký 2)', 'The Legend Of Hei 2', 'https://phimimg.com/upload/vod/20251028-1/82f4d549bd8e7076b79e796f3372e252.jpg', 'https://phimimg.com/upload/vod/20251028-1/4fffac6b86e70ee723508a83b14945c0.jpg', '<p>Tiểu Hắc cùng sư phụ sống những ngày yên bình tại một thị trấn nhỏ. Thế nhưng khi phân hội bị tấn công, sự kiện ấy đã phá vỡ nền hòa bình giữa các yêu giới được gìn giữ suốt bao năm. Nhiệm vụ “hoàn toàn mới” từ Yêu Linh Hội Quán không chỉ đẩy hai thầy trò vào bờ vực chia cắt, mà còn khiến vận mệnh của sư phụ thay đổi một cách dữ dội. Trước những bí ẩn chồng chéo và hiểm nguy rình rập, Tiểu Hắc cùng sư tỷ Lộc Dã bước vào một cuộc phiêu lưu mới để tìm ra sự thật. Lần này, liệu Tiểu Hắc có đủ sức vượt qua thử thách, bảo vệ sư phụ và hóa giải nguy cơ?</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Shan Xin","avatar":""},{"name":"Liu Mingyue","avatar":""},{"name":"Zhu Jing","avatar":""},{"name":"Luan Lisheng","avatar":""},{"name":"Fu Chen Yang","avatar":""},{"name":"Yan Ling","avatar":""},{"name":"Chen Qigang","avatar":""},{"name":"Wang Zhen","avatar":""},{"name":"Li Lu","avatar":""},{"name":"Chen Siyu","avatar":""},{"name":"Jingxing Ren","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["La Leyenda de Hei 2","罗小黑战记2","Luo Xiaohei Zhan Ji 2","The Legend of Hei Ⅱ","The Legend o