INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-nhan-giua-troi-dong', 'Sát Nhân Giữa Trời Đông', 'Dead Of Winter', 'https://phimimg.com/upload/vod/20251026-1/9c7f36633c148b21417dc4159550652c.jpg', 'https://phimimg.com/upload/vod/20251026-1/a73988411f39ae6d2e74980d4e794f2e.jpg', '<p>Một người phụ nữ, đang đi một mình qua miền bắc Minnesota phủ đầy tuyết trắng, đã ngăn chặn vụ bắt cóc một cô gái tuổi teen. Cách thị trấn gần nhất hàng giờ đồng hồ và không có sóng điện thoại, cô nhận ra rằng mình là hy vọng duy nhất của cô gái trẻ.</p>', 'Full', 1, 'single', 'completed', 12, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Đức', 0, '[{"name":"Emma Thompson","avatar":""},{"name":"Judy Greer","avatar":""},{"name":"Marc Menchaca","avatar":""},{"name":"Laurel Marsden","avatar":""},{"name":"Gaia Wise","avatar":""},{"name":"Cúán Hosty-Blaney","avatar":""},{"name":"Paul Hamilton","avatar":""},{"name":"Dalton Leeb","avatar":""},{"name":"Lloyd Hutchinson","avatar":""},{"name":"Brían F. O''Byrne","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Fisherwoman","The Dead of Winter","عَزّ الشِتاء","زمستان مرگبار","Zemheri","Dead of Winter"]', 1784690324143);
