INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-quy-an-hon', 'Ác Quỷ Ăn Hồn', 'It Feeds', 'https://phimimg.com/upload/vod/20250510-1/00a2a7d52ff192244b208a1d2c541bfc.jpg', 'https://phimimg.com/upload/vod/20250510-1/18ce047df824bb44bc79afe504a43716.jpg', '<p>Sau khi một cô gái trẻ xông vào phòng khám tâm thần tại nhà của họ và tuyên bố rằng có một thực thể đang ăn thịt cô, Jordan và người mẹ có năng lực thấu thị của cô phải tìm cách ngăn chặn thế lực đó trước khi cô gái bị bắt đi hoàn toàn.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Ashley Greene","avatar":""},{"name":"Ellie O''Brien","avatar":""},{"name":"Juno Rinaldi","avatar":""},{"name":"Mark Taylor","avatar":""},{"name":"Shawn Ashmore","avatar":""},{"name":"Julian Richings","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["心魔","It Feeds"]', 1784690324143);
