INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-san-2025', 'Báo Săn', 'The Cheetah', 'https://phimimg.com/upload/vod/20251015-1/6f1accf7d76e5ad3d067f08b8310ed5e.jpg', 'https://phimimg.com/upload/vod/20251015-1/ddcc8843adda86f1ae4ad0920fb1751b.jpg', '<p>Câu chuyện kể về Trần Hán Sinh, một sinh viên tốt nghiệp trường quân sự ấp ủ ước mơ trở thành &#39;Đặc chiến&#39;. Nhờ nỗ lực không ngừng, anh đã được sự công nhận của Lăng Tranh Vinh&nbsp; – quyền Đại đội trưởng đội Báo Săn, Cố vấn chính trị Khâu Thiên và đội trưởng đội sửa chữa Trương Lan, đồng thời gia nhập thành công Đội Đặc nhiệm Báo Săn. Cùng với các thành viên khác, anh đối diện với thử thách sinh tử, trưởng thành và được tôi luyện qua vô số nhiệm vụ gian khổ. Tác phẩm đã khắc họa tinh thần nhiệt huyết và trách nhiệm của người lính trong thời đại mới, qua quá trình trưởng thành và cả sự hy sinh.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Sử Bành Nguyên","avatar":""},{"name":"Dương Thược","avatar":""},{"name":"Tưởng Lộ Hà","avatar":""},{"name":"Vũ Cường","avatar":""},{"name":"Viên Văn Khang","avatar":""},{"name":"Chu Huệ Lâm","avatar":""},{"name":"Bạch Uy","avatar":""},{"name":"Liên Dịch Danh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["猎豹突击队","Lie Bao","猎豹"]', 1784690324143);
