INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-kiem-soi-hoa-dao', 'Nâng Kiếm Soi Hoa Đào', 'Blades Amid Blossoms', 'https://phimimg.com/upload/vod/20250729-1/68f5717246b597402e2f521d24df4051.jpg', 'https://phimimg.com/upload/vod/20250729-1/3d06fadcacf2c0f1684626fefd52c16f.jpg', '<p>Hoàng phi về Đào Hoa sơn trang thăm người thân, rồi chết một cách bí ẩn ở rừng hoa đào trong sơn trang. Kiếm khách lang thang Yên Thập Nhất là người bị tình nghi nhiều nhất. Hàn Đao, người phụ trách bảo vệ hoàng phi đã ra lệnh phong tỏa Đào Hoa sơn trang, ngăn cấm mọi người ra vào. Càng điều tra sâu, những bí mật của Đào Hoa sơn trang càng được hé lộ, chân tướng càng trở nên mơ hồ khó hiểu...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hoàn Nhan Lạc Nhung","avatar":""},{"name":"Lưu Hạo Quần","avatar":""},{"name":"Hàn Hân Dư","avatar":""},{"name":"Khương Nghệ Thanh","avatar":""},{"name":"Bộ Tử Dĩnh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ti Jian Ying Tao Hua","제검영도화: 칼끝으로 진실을 좇다","提剑映桃花"]', 1784690324143);
