INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nang-kiem-soi-hoa-dao', 'Nâng Kiếm Soi Hoa Đào', 'Blades Amid Blossoms', 'nâng kiếm soi hoa đào blades amid blossoms hoàn nhan lạc nhung lưu hạo quần hàn hân dư khương nghệ thanh bộ tử dĩnh ti jian ying tao hua 제검영도화: 칼끝으로 진실을 좇다 提剑映桃花', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-anh-sao-roi-xuong-bien-hoa', 'Khi Ánh Sao Rơi Xuống Biển Hoa', 'When the Stars Fall into the Sea of Flowers (Starlit Bloom)', 'https://phimimg.com/upload/vod/20251012-1/1e5640bb3c7ec62cfc1a0beadfafbae4.jpg', 'https://phimimg.com/upload/vod/20251012-1/139c4d959952ab5a07f12c0743f99b8c.jpg', '<p>Cố Lưu Tô, nhà sáng lập một thương hiệu trang sức, là người mạnh mẽ quyết đoán trong công việc, đồng thời cũng nghiêm túc thận trọng trong cuộc sống thường ngày. Do phát sinh &quot;sự cố&quot;, cô bất ngờ trải qua tình một đêm với chàng &quot;thiếu gia&quot; Lục Tinh Thần cô mới chỉ gặp một lần, từ đó dẫn đến hiểu lầm nghiêm trọng! Tệ hơn là ngay sau đó Lục Tinh Thần được nhận vào công ty, trở thành thư ký thân cận của Cố Lưu Tô. Cặp đôi oan gia không thể ngờ rằng, người từng đối đầu gay gắt lại có thể dần thay đổi theo thời gian. Lục Tinh Thần nảy sinh lòng mến mộ không thể nói rõ với Cố Lưu Tô. Tài năng thiết kế của cậu cũng được một người tỉ mỉ kĩ tính như Cố Lưu Tô công nhận. Sự hòa hợp về tâm hồn khiến họ ngày càng say mê trong tỉnh táo, đắm chìm trong những phút giây bình yên mà rạo rực sóng ngầm.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tống Mỹ Na","avatar":""},{"name":"Kha Thuần","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["When the Stars Fall into the Sea of Flowers","当星光坠入花海"]', 1784690324143);
