INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-lech-pha-2025', 'Tình Yêu Lệch Pha', 'Unbalanced Love', 'https://phimimg.com/upload/vod/20251029-1/ec4218f30c1589034f2ab66d052b0bd6.jpg', 'https://phimimg.com/upload/vod/20251029-1/ceebec3159c946181df603dc29221db4.jpg', '<p>Một câu chuyện tình yêu và trưởng thành về hành trình vượt qua mặc cảm và tìm lại chính mình. Yeong Seon, cô gái 27 tuổi tưởng chừng bình thường và thực tế, nhưng lại mang trong lòng những tổn thương và mặc cảm khó nói, quyết định đứng lên đối diện với thế giới để giành lại vai chính trong cuộc đời mình — “chính cô ấy”.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324143);
