INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tinh-yeu-lech-pha-2025', 'Tình Yêu Lệch Pha', 'Unbalanced Love', 'tình yêu lệch pha unbalanced love  ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-linh-do', 'Vạn Linh Độ', 'Ferry Of Souls', 'https://phimimg.com/upload/vod/20251028-1/eeec4fdcd6ed7af5e127f151839e3df8.jpg', 'https://phimimg.com/upload/vod/20251028-1/dfca5f0ef4b94da387c1ba8c2095be3d.jpg', '<p>Giữa đô thị phồn hoa, có một quán trọ thần bí của yêu quái ẩn mình — chỉ những người có duyên mới có thể bước vào. Thầy trừ yêu Thượng Quan Phi Dạ vì giết chóc quá nhiều mà bị oán khí của yêu ma phản phệ, bị nguyền rủa sống bất lão bất tử suốt nghìn năm trong quán trọ đó. Để hóa giải lời nguyền, anh buộc phải đưa Đông Phương Chiếu Bạch, chủ nhân cũ của quán trọ đã mất trí nhớ, trở lại nơi đây. Trong khi ấy, nhiều vị khách từng có mối liên hệ với họ cũng lần lượt tìm đến — mỗi người mang trong lòng những nút thắt, tiếc nuối và oán hận chưa buông. Trong hành trình giúp họ hóa giải tâm kết, Thượng Quan dần cảm nhận lại những xúc cảm nhân tính đã ngủ quên, còn Đông Phương thì bắt đầu thay đổi cái nhìn cực đoan của mình về yêu quái. Cuối cùng, hai người hợp lực đánh bại yêu vương – kẻ đứng sau mọi tội ác, mang lại bình yên cho thế gian, đồng thời hóa giải hiểu lầm nghìn năm và một lần nữa tìm lại tình yêu dành cho nhau.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Cửu Lâm","avatar":""},{"name":"Lục Diên Kỳ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wan Ling Du","妖怪客栈","Wanling Ferry","万灵渡"]', 1784690324143);
