INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('van-linh-do', 'Vạn Linh Độ', 'Ferry Of Souls', 'vạn linh độ ferry of souls lý cửu lâm lục diên kỳ wan ling du 妖怪客栈 wanling ferry 万灵渡', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huong-phai', 'Hương Phai', 'No More Fragrance!', 'https://phimimg.com/upload/vod/20251028-1/9a18510aa9616958c954f72496796b93.jpg', 'https://phimimg.com/upload/vod/20251028-1/f44b926f8c68b03c0fa31dafbf463d18.jpg', '<p>Ae Jin vô cùng tức giận với chồng mình - Sung Gi, vì thói trăng hoa của anh ta. Mùi nước hoa trên người Sung Gi mỗi ngày đều khác nhau, nhưng gần đây lại luôn là cùng một mùi. Lần theo dấu vết, Ae Jin phát hiện ra nguồn gốc của chuyện này là một quán thịt nướng do một bà cô 50 tuổi sành điệu tên Jeong Rye làm chủ! Ae Jin giận dữ đến chất vấn Jeong Rye, nhưng rồi phát hiện ra Jeong Rye có một người chồng trẻ đẹp trai - Jeon Rip, kém cô 20 tuổi. Khi đó, Ae Jin nảy ra một ý nghĩ: muốn trả thù - cô phải quyến rũ được anh chàng phi công trẻ này! Trong lúc cuộc chiến tình ái đang diễn ra căng thẳng, Ae Jin bất chấp mọi nỗ lực, vẫn không thể chinh phục được trái tim Jeon Rip, khiến cô vô cùng lo lắng. Sau đó, bốn người họ gặp nhau và tranh cãi không ngừng, cho đến khi một người đề nghị: &quot;Đã vậy thì sao không thử đổi người sống cùng xem sao?&quot; Vậy là Ae Jin bắt đầu sống cùng Jeon Rip, còn Jeong Rye chuyển đến sống cùng Sung Gi. Nhưng liệu bốn người này cuối cùng có tìm thấy tình yêu đích thực?</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324143);
