INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-bao-ve-2025', 'Những Người Bảo Vệ', 'The Guardians', 'https://phimimg.com/upload/vod/20250925-1/5e4a4c53938592c47830c1051cbea7f6.jpg', 'https://phimimg.com/upload/vod/20250925-1/0c684aedeeaa36c578813cc96f695d1c.jpg', '<p>Thượng Hải thập niên 1940, nam diễn viên nghèo khổ Đinh Dịch buộc phải giả mạo một chuyên gia mật mã mù sau khi đặc vụ Cố Ẩn Sơn lỡ tay giết nhầm người thật. Cố Ẩn Sơn cải trang thành trợ lý của Đinh Dịch, cùng anh thâm nhập vào cơ quan tình báo Nhật dưới sự giúp đỡ của nữ chủ rạp hát Tiên Bích Vân. Trong hành trình đầy hiểm nguy, bộ đôi bất đắc dĩ dần hình thành tình huynh đệ sâu sắc, nhưng sự khác biệt về lòng trung thành đã đẩy họ đến thử thách niềm tin và sự hy sinh không thể tránh khỏi.</p>', 'Hoàn Tất (35/35)', 35, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Nhất Sơn","avatar":""},{"name":"Hàn Đông Quân","avatar":""},{"name":"Trương Thiên Ái","avatar":""},{"name":"Lưu Hoan","avatar":""},{"name":"Bào Đại Chí","avatar":""},{"name":"Tiêu Cương","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Shou Hu Zhe Men","守护者们"]', 1784690324143);
