INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-xau-2025', 'Kẻ Xấu', 'Bad Man', 'https://phimimg.com/upload/vod/20251028-1/ec5d00c28f5e96043d876b014eeae2a7.jpg', 'https://phimimg.com/upload/vod/20251028-1/cf9b71a8a8d7ae705523774d24d919f4.jpg', '<p>Tại thị trấn Colt Lake, bang Tennessee, Sam Evans đang nỗ lực đối phó với nạn ma túy đá hoành hành. Tuy nhiên, khi điệp viên ngầm Bobby Gaines xuất hiện, Evans bị gạt sang một bên. Dù Evans có mối quan hệ sâu sắc với dân địa phương, Gaines lại được ca ngợi như một anh hùng. Nhưng rồi, những nghi ngờ quanh con người thật của Gaines bắt đầu xuất hiện, dần hé lộ một câu chuyện phức tạp và đầy uẩn khúc phía sau.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Seann William Scott","avatar":""},{"name":"Johnny Simmons","avatar":""},{"name":"Lovi Poe","avatar":""},{"name":"Rob Riggle","avatar":""},{"name":"Chance Perdomo","avatar":""},{"name":"Ethan Suplee","avatar":""},{"name":"Jack Conley","avatar":""},{"name":"Marcelle LeBlanc","avatar":""},{"name":"Andre Hyland","avatar":""},{"name":"John Patrick Jordan","avatar":""},{"name":"Kai Caster","avatar":""},{"name":"Jett Wilder","avatar":""},{"name":"Loren Dunn","avatar":""},{"name":"Wade Hammond","avatar":""},{"name":"Leslie Sides","avatar":""},{"name":"Ryan Dempsey","avatar":""},{"name":"Dylan Friedman","avatar":""},{"name":"Derri","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bad Man"]', 1784690324143);
