INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-hai-cot', 'Hồ Hài Cốt', 'Bone Lake', 'https://phimimg.com/upload/vod/20251028-1/c226b829fc54b58758c20e69f89b51e9.jpg', 'https://phimimg.com/upload/vod/20251028-1/d3062bc822a1f2f4bc272d61aa92f4af.jpg', '<p>Kỳ nghỉ lãng mạn của một cặp đôi tại biệt thự ven hồ hẻo lánh bỗng trở nên hỗn loạn khi họ buộc phải chia sẻ căn nhà với một cặp đôi khác đầy bí ẩn và quyến rũ. Trong câu chuyện kinh dị vừa đen tối vừa đầy mê hoặc này, chuyến nghỉ dưỡng trong mơ nhanh chóng trượt dài thành cơn ác mộng — một mê cung của dục vọng, dối trá và thao túng, nơi những bí mật kinh hoàng bị phơi bày, dẫn đến cuộc chiến đẫm máu để giành lấy sự sống còn.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Maddie Hasson","avatar":""},{"name":"Alex Roe","avatar":""},{"name":"Marco Pigossi","avatar":""},{"name":"Andra Nechita","avatar":""},{"name":"Eliane Reis","avatar":""},{"name":"Clayton Spencer","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["죽음의 호수","دریاچه استخوان","Bone Lake"]', 1784690324143);
