INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-gianh-quyen-nuoi-meo', 'Cuộc Chiến Giành Quyền Nuôi Mèo', 'Cat Custody War', 'https://phimimg.com/upload/vod/20251028-1/1ba2bc30ae4fac439479898f8713b069.jpg', 'https://phimimg.com/upload/vod/20251028-1/7a0869fc2de21587de81adc80ce7f3ba.jpg', '<p>Phim kể về câu chuyện của một cặp vợ chồng đang ở năm thứ 5 của cuộc hôn nhân, sắp ly hôn, và cuộc xung đột của họ về &quot;quyền nuôi mèo&quot; của một chú mèo mà họ coi như con ruột. Họ gặp khó khăn trong việc thụ thai nhưng đã nhận nuôi một chú mèo hoang và sống như một gia đình, nhưng cuối cùng quyết định ly hôn.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Seul-gi","avatar":""},{"name":"Yoon Doo-joon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324143);
