INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-dai-nhiet-huyet', 'Thời Đại Nhiệt Huyết', 'The Age Of Passion', 'https://phimimg.com/upload/vod/20251019-1/a4b1e1f38bdbf46fc7219123b4129e26.jpg', 'https://phimimg.com/upload/vod/20251019-1/e03cbbb794e8041f7553b2160b63d272.jpg', '<p>Để bảo vệ mối tình đầu, Chu Minh Duệ quyết định nghỉ học và cùng hai người anh em Hứa Gia Minh, Phan Bác Văn bắt đầu hành trình khởi nghiệp trong lĩnh vực trò chơi điện tử – niềm đam mê mà cả ba luôn ấp ủ. Họ khởi đầu từ con số không, gồng mình vượt qua muôn vàn khó khăn: thiếu vốn, gặp rào cản kỹ thuật và phải đối mặt với ánh mắt nghi ngờ từ thị trường. Thế nhưng, bằng sự kiên trì và nỗ lực không ngừng, họ đã miệt mài ngày đêm hoàn thiện sản phẩm. Cuối cùng, ba chàng trai trẻ mang trong tim ước mơ đã cùng nhau viết nên câu chuyện thành công rực rỡ.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Bá Dung","avatar":""},{"name":"Ngô Lạc Hàm","avatar":""},{"name":"Vạn Quốc Bằng","avatar":""},{"name":"Trương Tuyền","avatar":""},{"name":"Tôn Duy Tung","avatar":""},{"name":"Nghê Du Khôn","avatar":""},{"name":"MC Nông Dân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["热血年代"]', 1784690324143);
