INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-nuoc-duc', 'Dòng Nước Đục', 'The Murky Stream', 'https://phimimg.com/upload/vod/20250926-1/c77c4855471f095d9f8d541fc7163d50.jpg', 'https://phimimg.com/upload/vod/20250926-1/b5c5d96d9661a1a31726e32b07d49108.jpg', '<p>Joseon, thời kỳ mà Gyeonggang vốn yên bình, nay lại chìm trong hỗn loạn. Câu chuyện xoay quanh ba nhân vật chính với số phận đan xen: Si Yul, một người đàn ông che giấu quá khứ và thể hiện sự bất lương; Choi Eun, một thương gia chính trực và sắc sảo; và Jeong Cheon, thể hiện hình tượng một viên quan chính trực. Niềm tin, khát vọng và số phận khác biệt đã kéo ba nhân vật chính vào một vòng xoáy xung đột trong bối cảnh thời đại đầy biến động.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Rowoon","avatar":""},{"name":"Shin Ye-eun","avatar":""},{"name":"Park Seo-ham","avatar":""},{"name":"Park Ji-hwan","avatar":""},{"name":"Jeon Bae-soo","avatar":""},{"name":"Choi Won-young","avatar":""},{"name":"Choi Gwi-hwa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Takryu","The Murky Stream","MURKY WATER","The.Murky.Stream","탁류"]', 1784690324143);
