INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vach-toi-2025', 'Vạch Tội', 'No Mercy', 'https://phimimg.com/upload/vod/20250926-1/d38f85140bd5dff7f6b5852acb85f9f8.jpg', 'https://phimimg.com/upload/vod/20250926-1/9616f9e88b7ec44e177deb35b0c51d7b.jpg', '<p>Han So Min – một nữ diễn viên vô danh chỉ còn lại ý chí để bám trụ. Bi kịch ập đến khi cô mất cả cha lẫn mẹ trong một vụ lừa đảo qua điện thoại. Nuốt nước mắt vào trong, So Min quyết tâm thâm nhập vào tập đoàn tội phạm khổng lồ đứng sau, dùng chính công nghệ deepfake để đánh lừa chúng… và hủy diệt cả đường dây từ bên trong.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 11, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Joo-young","avatar":""},{"name":"Ji Seung-hyun","avatar":""},{"name":"Koo Jun-hoe","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["بلا رحمة","No Mercy","Conviction","단죄"]', 1784690324144);
