INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ninja-an-than', 'Ninja Ẩn Thân', 'Under Ninja', 'https://phimimg.com/upload/vod/20251026-1/2c244597b8af64a6bee7a769c2526c21.jpg', 'https://phimimg.com/upload/vod/20251026-1/d6aed99a16822ce53abf0262cfa9a550.jpg', '<p>Sau khi Chiến tranh Thái Bình Dương kết thúc, mệnh lệnh đầu tiên do GHQ, đơn vị chiếm đóng Nhật Bản, đưa ra là &quot;giải tán các tổ chức ninja.&quot; Điều này khiến mọi người có cảm giác như tất cả các ninja đã biến mất, nhưng thực ra họ vẫn tiếp tục bí mật hoạt động trong nhiều tổ chức khác nhau trên khắp thế giới. Một ngày nọ, Kumogakure Kuro (Yamazaki), một ninja cấp thấp thuộc tổ chức ninja NIN và đang cảm thấy buồn chán, bỗng được giao một &quot;nhiệm vụ ninja&quot; quan trọng là điều tra các hoạt động của tổ chức bí ẩn Under Ninja. Cô nữ sinh trung học phổ thông Noguchi Ayaka (Hamabe) cũng bị cuốn vào trận chiến ninja.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kento Yamazaki","avatar":""},{"name":"Minami Hamabe","avatar":""},{"name":"Amane Okayama","avatar":""},{"name":"Chihiro Yamamoto","avatar":""},{"name":"Ryubi Miyase","avatar":""},{"name":"Ryotaro Sakaguchi","avatar":""},{"name":"Mitsuru Hirata","avatar":""},{"name":"Shinobu Hasegawa","avatar":""},{"name":"Jiro Sato","avatar":""},{"name":"Tsuyoshi Muro","avatar":""},{"name":"Mai Shiraishi","avatar":""},{"name":"Shotaro Mamiya","avatar":""},{"name":"Haruka Kinami","avatar":""},{"name":"Kou Maehara","avatar":""},{"name":"Reiya Masaki","avatar":""},{"name":"Hinami Mori","avatar":""},{"name":"Nihi","avatar":""},{"name":"Maru N","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3