INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-quy-no-hoa', 'Hải Quỳ Nở Hoa', 'Anemone', 'https://phimimg.com/upload/vod/20251026-1/758372d0d93cc141fb0683c22ee2607d.jpg', 'https://phimimg.com/upload/vod/20251026-1/8c78a325ca710e1bf98272804faec54c.jpg', '<p>Jem, một người đàn ông trung niên, rời khỏi ngôi nhà ngoại ô và lên đường vào khu rừng hẻo lánh, nơi anh gặp lại người anh trai Ray — kẻ đã sống ẩn dật nhiều năm qua. Gắn kết bởi một quá khứ bí ẩn và rối ren, hai anh em chia sẻ mối quan hệ đầy căng thẳng nhưng cũng thoáng qua sự dịu dàng, một mối dây từng bị thay đổi mãi mãi bởi biến cố tàn khốc xảy ra hàng chục năm trước.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Daniel Day-Lewis","avatar":""},{"name":"Sean Bean","avatar":""},{"name":"Samantha Morton","avatar":""},{"name":"Samuel Bottomley","avatar":""},{"name":"Safia Oakley-Green","avatar":""},{"name":"Lewis Ian Bray","avatar":""},{"name":"Paul Butterworth","avatar":""},{"name":"Karl Cam","avatar":""},{"name":"JP Conway","avatar":""},{"name":"Angus Cooper","avatar":""},{"name":"Adam Fogerty","avatar":""},{"name":"Richard Graham","avatar":""},{"name":"Mark Holgate","avatar":""},{"name":"Holly Rhys","avatar":""},{"name":"Jag Sanghera","avatar":""},{"name":"Sid Akbar Ali","avatar":""},{"name":"Eve Townsend","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Avelyne","شقائق","Anemone"]', 1784690324144);
