INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-soi-hoang', 'Bầy Sói Hoang', 'Coyotes', 'https://phimimg.com/upload/vod/20251026-1/4e0df860e9c54c0cb0476aa178e24c96.jpg', 'https://phimimg.com/upload/vod/20251026-1/c0161afa903678aaf4b952f9a2642d37.jpg', '<p>Một gia đình bị mắc kẹt trong ngôi nhà ở Hollywood Hills, phải chiến đấu để sinh tồn giữa trận cháy rừng dữ dội và bầy chó sói hoang dã.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Justin Long","avatar":""},{"name":"Mila Harris","avatar":""},{"name":"Brittany Allen","avatar":""},{"name":"Kate Bosworth","avatar":""},{"name":"Norbert Leo Butz","avatar":""},{"name":"Kevin Glynn","avatar":""},{"name":"Katherine McNamara","avatar":""},{"name":"Norma Nivia","avatar":""},{"name":"Judith O''Dea","avatar":""},{"name":"Keir O''Donnell","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Coyotes"]', 1784690324144);
