INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bay-soi-hoang', 'Bầy Sói Hoang', 'Coyotes', 'bầy sói hoang coyotes justin long mila harris brittany allen kate bosworth norbert leo butz kevin glynn katherine mcnamara norma nivia judith o''dea keir o''donnell coyotes', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-long-mon-khach-san-2025', 'Tân Long Môn Khách Sạn', 'New Dragon Gate Inn', 'https://phimimg.com/upload/vod/20250604-1/7c18633af8f93f44237ecf334acc6551.jpg', 'https://phimimg.com/upload/vod/20250604-1/b3d310474b108ef3b2fb44274454ee5f.jpg', '<p>Vào cuối triều đại Minh, đất nước phải đối mặt với những mối lo nội bộ và ngoại xâm. Trong triều đình, cuộc tranh giành quyền lực giữa các hoàng tử không ngừng leo thang, trong khi vùng Đông Nam có hải tặc hoành hành, còn Tây Bắc thì có sự trỗi dậy của quân Wala. Chu Hoài An - một người trong Cấm Vệ Quân, tuy không quan tâm đến những cuộc tranh đấu chính trị, nhưng lại vô cùng ghét Đông Xưởng. Mặc dù sư phụ khuyên can, anh không trực tiếp đối đầu với Đông Xưởng, nhưng lại chọn đứng về phía những người chính nghĩa, bảo vệ người con trai duy nhất của Lão Anh Vương, là Anh Quan Trấn, khỏi sự tấn công của Đông Xưởng. Sau đó, anh cũng trở thành người đầu tiên đứng lên chống lại thế lực đen tối của Đông Xưởng, vì danh dự của Lão Anh Vương. Sau những cuộc phiêu lưu nguy hiểm ở các quần đảo, Chu Hoài An không chỉ nâng cao võ công mà còn trở thành một người được các thế lực ở 36 đảo kính trọng. Đồng thời, anh cũng mở rộng tầm mắt, nhận ra rằng mình không chỉ chiến đấu vì bản thân mà còn vì nước, vì dân, trở thành một hiệp khách thực thụ, luôn chiến đấu vì công lý và chính nghĩa. Cuối cùng, Kính Vương – người đã sử dụng những thủ đoạn tàn nhẫn để lên ngôi vua, sau khi nắm giữ quyền lực, đã hiểu được rằng làm vua không chỉ là việc nắm quyền mà còn là trách nhiệm. Ông quyết định minh oan cho Lão Anh Vương, bình định các cuộc nổi loạn, và dũng cảm mở cửa thương mại với các nước ngoài, khôi phục lại con đường tơ lụa trên biển, hình thành lại “Con đường tơ lụa trên biển”. Đồng thời, ông cũng mở lại các cửa khẩu biên giới Tây Bắc, khôi phục con đường tơ lụa cổ xưa.</p>', 'Hoàn Tất (48/48)', 48, 'series', 'completed', 9, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Mã Khắc","avatar":""},{"name":"Từ Tư Uy","avatar":""},{"name":"Thẩm Mộng Trân","avatar":""},{"name":"Bảo Kiếm Phong","avatar":""},{"name":"Đỗ Tuấn Tước","avatar":""},{"name":"Từ Trần","avatar":""},{"name":"Trần Hiểu Đông","avatar":""},{"name":"Diệp Hy Khởi","avatar":""},{"name":"Vương Ba","avatar":""},{"name":"Dương Minh Na","avatar":""},{"name":"Tông Phong Nham","avatar":""},{"name":"Tiêu Kiếm","avatar":""},{"name":"Lô Châu","avatar":""},{"name":"Mã Hách","avatar":""},{"name":"Nhuyễn Thánh Văn","avatar":""},{"name":"Phú Ảnh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Xin Long Men Ke Zhan","新龙门客栈电视剧版","新龙门客栈"]', 1784690324144);
