INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tan-long-mon-khach-san-2025', 'Tân Long Môn Khách Sạn', 'New Dragon Gate Inn', 'tân long môn khách sạn new dragon gate inn mã khắc từ tư uy thẩm mộng trân bảo kiếm phong đỗ tuấn tước từ trần trần hiểu đông diệp hy khởi vương ba dương minh na tông phong nham tiêu kiếm lô châu mã hách nhuyễn thánh văn phú ảnh xin long men ke zhan 新龙门客栈电视剧版 新龙门客栈', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-thuyet-lang-hac-kim', 'Truyền Thuyết Làng Hắc Kim', 'The Legend Of Heijin Village', 'https://phimimg.com/upload/vod/20251026-1/5aa92b555472e5d7f23ad1f5ee5b7c5a.jpg', 'https://phimimg.com/upload/vod/20251026-1/da3b94a6cd319508b7b34983cdfc4e61.jpg', '<p>Đoàn kịch Cát Tường rong ruổi giang hồ bao năm, trong một chuyến phiêu lưu cùng người yêu là Khổng Vũ, học trò trong đoàn – Trác Nhiên – gặp phải tai nạn bất ngờ khiến Khổng Vũ mất mạng. Quá thất vọng, Trác Nhiên rời bỏ đoàn. Nhiều năm sau, để cứu đồng môn bị trúng độc lạ, Trác Nhiên quay lại đoàn kịch cũ, dẫn dắt mọi người lên đường mạo hiểm tìm thuốc giải. Hành trình gian nan trùng điệp, bao chuyện kỳ dị xảy ra, Trác Nhiên cũng dần phát hiện ra cả nhóm đang bị cuốn vào một âm mưu khủng khiếp. Cuối cùng, dưới sự dẫn dắt của Trác Nhiên, mọi người liều chết chiến đấu, tìm được thuốc giải và thoát khỏi cơn hiểm nguy. Trác Nhiên cũng tái lập đoàn kịch Tân Cát Tường, cùng mọi người mở ra một cuộc sống mới.</p>', 'Full', 1, 'single', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ứng Hạo Minh","avatar":""},{"name":"Vương Vận Hàn","avatar":""},{"name":"Bào Tiểu Bình","avatar":""},{"name":"Lưu Tĩnh Di","avatar":""},{"name":"Vương Chí Bằng","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Legend Of Heijin Village","黑金村传说"]', 1784690324144);
