INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-tim-quan-tai', 'Truy Tìm Quan Tài', 'Search For Coffin', 'https://phimimg.com/upload/vod/20251026-1/e459f98fd445d67109690314b21941fb.jpg', 'https://phimimg.com/upload/vod/20251026-1/49dba2425e27e78137061e23db671559.jpg', '<p>Mùa đông năm 1939, quân Nhật hoành hành. Ở thôn Hà Hoa, Tần Xuyên và Nhị Hổ vì cứu dân làng đói kém đã lẻn vào lò mổ trong doanh trại địch trộm thịt, bất ngờ phát hiện dưới thớt giấu &quot;Huyết Mãng&quot; và đoạt được bảo vật hiếm có &quot;Định Phong Châu&quot;. Hai người đem lên huyện thành để bán nhưng bị Lão Bàn Tính - truyền nhân Tiêu Khí Môn - phản bội, khiến quân Nhật thảm sát cả thôn. Cuối cùng, thuật sĩ ngàn năm Khương Thái Cổ tỉnh lại; Tần Xuyên và Liễu Thanh cùng nhau phản kháng và trong một vụ nổ đã thoát khỏi cõi chết.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Hách","avatar":""},{"name":"Thạch Tuyết Kính","avatar":""},{"name":"Chu Thiết Hòa","avatar":""},{"name":"Đinh Văn Bác","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["寻棺"]', 1784690324144);
