INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-thuoc-no', 'Ngôi Nhà Thuốc Nổ', 'A House Of Dynamite', 'https://phimimg.com/upload/vod/20251026-1/f866be80d4f44811c62115f6421676b4.jpg', 'https://phimimg.com/upload/vod/20251026-1/f7266547cb01d03c7bd316d983af56a3.jpg', '<p>Khi một tên lửa không rõ nguồn gốc được phóng vào lãnh thổ Hoa Kỳ, một cuộc chạy đua bắt đầu nhằm truy tìm thủ phạm và quyết định phương án ứng phó.</p>', 'Full', 1, 'single', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Idris Elba","avatar":""},{"name":"Rebecca Ferguson","avatar":""},{"name":"Gabriel Basso","avatar":""},{"name":"Jared Harris","avatar":""},{"name":"Tracy Letts","avatar":""},{"name":"Anthony Ramos","avatar":""},{"name":"Moses Ingram","avatar":""},{"name":"Jonah Hauer-King","avatar":""},{"name":"Greta Lee","avatar":""},{"name":"Jason Clarke","avatar":""},{"name":"Malachi Beasley","avatar":""},{"name":"Brian Tee","avatar":""},{"name":"Brittany O''Grady","avatar":""},{"name":"Gbenga Akinnagbe","avatar":""},{"name":"Willa Fitzgerald","avatar":""},{"name":"Renée Elise Goldsberry","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["炸药屋","Dinamit Evi","炸裂白宫","A House of Dynamite"]', 1784690324144);
