INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngoi-nha-thuoc-no', 'Ngôi Nhà Thuốc Nổ', 'A House Of Dynamite', 'ngôi nhà thuốc nổ a house of dynamite idris elba rebecca ferguson gabriel basso jared harris tracy letts anthony ramos moses ingram jonah hauer-king greta lee jason clarke malachi beasley brian tee brittany o''grady gbenga akinnagbe willa fitzgerald renée elise goldsberry 炸药屋 dinamit evi 炸裂白宫 a house of dynamite', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-u-minh-no-ro', 'Hoa U Minh Nở Rộ', 'Bloom In The Shadows', 'https://phimimg.com/upload/vod/20251026-1/2608dc4226b9b070b078d0c9707044d4.jpg', 'https://phimimg.com/upload/vod/20251026-1/c2b3c5c3dbd156ffc91b33cd0553473b.jpg', '<p>Năm 1917, Viên Thế Khải xưng đế, tướng Thái Ngạc phát động phong trào vệ quốc. Chàng thanh niên yêu nước Trịnh Thiếu Khanh du học trở về, bàng hoàng phát hiện cả gia đình đã bị sát hại thảm khốc. Sau khi điều tra, anh phát hiện mọi dấu vết đều liên quan đến đại quân phiệt Mã đại soái. Trịnh Thiếu Khanh liền trà trộn vào phủ đại soái để tìm chân tướng, nhưng lại vô tình nảy sinh tình cảm với con gái đại soái là Mã Doanh Doanh. Đêm tân hôn, hồn ma người vợ quá cố khoác áo đỏ trở lại, mang theo huyết chú đòi mạng. Sau hôn lễ, trong phủ liên tiếp xảy ra những chuyện kỳ dị, nhiều người chết thảm. Liệu đó là hồn ma báo thù hay lòng người hiểm ác? Kẻ đứng sau mọi bi kịch rốt cuộc là ai?</p>', 'Full', 1, 'single', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Thư Hàng","avatar":""},{"name":"Châu Hạo Đông","avatar":""},{"name":"Miêu Thanh","avatar":""},{"name":"Tô Đức Giang","avatar":""},{"name":"Du Lạc Nhi","avatar":""},{"name":"Thời Hiểu Phi","avatar":""},{"name":"Lô Trước Kiệt","avatar":""},{"name":"Vương Nhất Bác","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["You.Ming.Hua.Kai","幽冥花开"]', 1784690324144);
