INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-vo-gia-dai-pha-thanh-long-hoi', 'Ẩn Võ Giả: Đại Phá Thanh Long Hội', 'Silent Warrior', 'https://phimimg.com/upload/vod/20251026-1/dda6d638e76dc048efd16fe5cc2395a5.jpg', 'https://phimimg.com/upload/vod/20251026-1/dce16c2342d99ff486d547248c374413.jpg', '<p>Khi Tăng Duyên sang nước ngoài dự tang lễ của cha, anh vô tình phát hiện ra người em gái cùng cha khác mẹ Tăng Quang và một chiếc nhẫn mà cha để lại, có liên quan đến một kho báu bí ẩn. Không lâu sau, một tên tội phạm tên Thanh Long bắt cóc Tăng Quang nhằm cướp lấy chiếc nhẫn đó. Để hoàn thành tâm nguyện cuối cùng của cha, Tăng Duyên buộc phải đối đầu với Thanh Long, mở ra một cuộc chiến đầy trí tuệ và mưu lược, nơi thiện – ác đan xen, và bí mật về “kho báu” dần được hé lộ.</p>', 'Full', 1, 'single', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Tịnh Đông","avatar":""},{"name":"Lý Mật Nhĩ","avatar":""},{"name":"Hoàng Gia Lạc","avatar":""},{"name":"Lương Thần Vũ","avatar":""},{"name":"Kim Cường","avatar":""},{"name":"Lưu Tịch Hiền","avatar":""},{"name":"Vương Cương","avatar":""},{"name":"Trịnh Văn Tôn","avatar":""},{"name":"Trương Hành","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Silent Warrior","Hidden Warrior: The Fall of the Azure Dragon Society","隐武者：大破青龙会"]', 1784690324144);
