INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('an-vo-gia-dai-pha-thanh-long-hoi', 'Ẩn Võ Giả: Đại Phá Thanh Long Hội', 'Silent Warrior', 'ẩn võ giả: đại phá thanh long hội silent warrior trương tịnh đông lý mật nhĩ hoàng gia lạc lương thần vũ kim cường lưu tịch hiền vương cương trịnh văn tôn trương hành silent warrior hidden warrior: the fall of the azure dragon society 隐武者：大破青龙会', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-truoc-hoang-hon', 'Yêu Trước Hoàng Hôn', 'Love Before Sunset', 'https://phimimg.com/upload/vod/20251026-1/e22a85b1c7dcf0ec10ff59588366abf3.jpg', 'https://phimimg.com/upload/vod/20251026-1/d003cf29a9e435255fc52ae4234632b4.jpg', '<p>Bộ phim kể về Lục Dã, tổng giám đốc của một tập đoàn đầu tư vừa du học trở về nước. Mong muốn được cha công nhận, anh vội vàng nhận một dự án phát triển du lịch nông thôn đầy khó khăn. Để thuyết phục người dân ký hợp đồng bán vườn trà, Lục Dã giả dạng thành người quay phim tài liệu, âm thầm sử dụng nhiều thủ đoạn để đối phó với những người dân không muốn bán đất, khiến hàng loạt tình huống dở khóc dở cười xảy ra.Trong quá trình tiếp xúc với dân làng, Lục Dã dần bị cảm động bởi sự chân thành và lương thiện của họ, đồng thời gặp được cô gái lạc quan, kiên cường Lâm An Đóa, và tìm thấy tình yêu của mình. Từ mục đích ban đầu mang tính vụ lợi, anh bắt đầu suy ngẫm lại hành động của bản thân, nhận ra giá trị đích thực nằm ở việc cống hiến cho người khác và xã hội. Lục Dã hiểu rằng thành công thật sự không chỉ là thành tựu thương mại, mà còn là tạo ra giá trị xã hội và bảo tồn di sản văn hóa. Câu chuyện tình yêu giữa Lục Dã và Lâm An Đóa trở thành động lực để cả hai cùng thay đổi và trưởng thành.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Biên Nhất Minh","avatar":""},{"name":"Tôn Diễm Thanh","avatar":""},{"name":"Ma Gia Minh","avatar":""},{"name":"Lữ Diễm Bối","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["晓看南山暮看云"]', 1784690324144);
