INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luoi-dao-ngot-ngao-vong-xoay-hon-uoc-chi-mang', 'Lưỡi Dao Ngọt Ngào: Vòng Xoáy Hôn Ước Chí Mạng', 'Kindness With A Twist', 'https://phimimg.com/upload/vod/20251026-1/a8db649983e8e7e122f1437d5621e432.jpg', 'https://phimimg.com/upload/vod/20251026-1/f0f0498a09d698ad36e5607ca8adb12a.jpg', '<p>Joon Hwi, tổng giám đốc trẻ tuổi của một khách sạn lớn, vô cùng căm thù một người phụ nữ tên Eun Hee. Nhiều năm trước, bà ta đã có quan hệ bất chính với cha anh, khiến mẹ anh rơi vào tuyệt vọng và tìm đến cái chết. Vì muốn trả thù, Joon Hwi cố tình tiếp cận Baek Jin Joo, con gái bà ta với một kế hoạch tàn nhẫn: “Đến ngày cưới, tôi sẽ vứt bỏ con gái bà như vứt một túi rác.” Thế nhưng, tình yêu vốn dĩ không đi theo bất cứ kịch bản nào cả. Người đàn ông lạnh lùng ấy lại dần thật lòng rung động trước Jin Joo, khiến kế hoạch báo thù bắt đầu rơi vào vòng xoáy cảm xúc. Bị giằng xé giữa thù hận và tình yêu, liệu họ có thể đi đến một cái kết hạnh phúc?</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 29, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phim Ngắn","slug":"phim-ngan","id":"4f02d28224c0747511790d57fbb63a62"}]', '[]', 1784690324144);
