INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dam-chim-2025', 'Đắm Chìm', 'Redemption', 'https://phimimg.com/upload/vod/20251026-1/bca8ae7caec2c4ded366bab95576323f.jpg', 'https://phimimg.com/upload/vod/20251026-1/3d52e0914e04c06892f6e09440444072.jpg', '<p>Trong thời kỳ loạn lạc Dân Quốc, Tần Mạn Chi (tiểu thư giới hắc đạo) và vệ sĩ Lục Hoài nảy sinh tình cảm ngầm, nhưng không ngờ tất cả chỉ là một cái bẫy chồng chất bẫy.&nbsp; Anh mang theo ca nữ Chu Liễu trà trộn vào Tần gia để báo thù, nhưng lại khó lòng kìm nén tình yêu dành cho Tần Mạn Chi. Trong khi đó, cô giằng xé giữa mối thù sâu đậm và tình yêu, đồng thời còn phát hiện ra người anh trai cưng chiều mình lại chính là kẻ đứng sau giật dây.&nbsp; Dưới nòng súng đối đầu, sự thật năm xưa dần hé lộ.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đoạn Hiểu Vi","avatar":""},{"name":"Mã Tiểu Vũ","avatar":""},{"name":"Viên Minh Trắc","avatar":""},{"name":"Đông Vũ Phi","avatar":""},{"name":"Vương Tân Chính","avatar":""},{"name":"Châu Thiên Tiểu","avatar":""},{"name":"Lưu Vệ Sâm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["悬溺"]', 1784690324144);
