INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dam-chim-2025', 'Đắm Chìm', 'Redemption', 'đắm chìm redemption đoạn hiểu vi mã tiểu vũ viên minh trắc đông vũ phi vương tân chính châu thiên tiểu lưu vệ sâm 悬溺', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-vo-nho-chon-nha-tranh', 'Cô Vợ Nhỏ Chốn Nhà Tranh', 'A Farmer''s Fortune', 'https://phimimg.com/upload/vod/20251008-1/eb80c2f58ea46abff1633c003c0c8795.jpg', 'https://phimimg.com/upload/vod/20251008-1/520cd56c31a50e4966e648422d95f456.jpg', '<p>Blogger ẩm thực Hà Thanh Thanh vô ý trượt ngã, xuyên về nơi thôn dã thời cổ đại, bắt đầu con đường dài kiếm tiền trả nợ, kết hôn trước yêu sau, nuôi dạy bảo bối đáng yêu để từng bước trưởng thành thành nữ chính mạnh mẽ. Cô liều mình mở lối làm giàu, đồng thời gặt hái tình cảm chân thành, yêu thương lẫn nhau với Phó Thanh Hoài. Ngay khi sự nghiệp, tình yêu và tình thân đều trọn vẹn, cô lại phải đối mặt với lựa chọn khó khăn: Rời đi hay ở lại...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Mã Thu Quyên","avatar":""},{"name":"Phao Dĩ Hồng","avatar":""},{"name":"Kim Vĩnh Tam","avatar":""},{"name":"Tiêu Uyên Hy","avatar":""},{"name":"Lý Đĩnh Hư","avatar":""},{"name":"Lưu An Kỳ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chai Men Xiao Fu Qi","柴门小福妻"]', 1784690324144);
