INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-thua-ke-so-1', 'Người Thừa Kế Số 1', 'The Successor', 'https://phimimg.com/upload/vod/20250821-1/42b42365015dbc8fecc2ecf3bf9487b9.jpg', 'https://phimimg.com/upload/vod/20250821-1/c0b9428e2f68972ef6104b2609716cea.jpg', '<p>Khi bà Thara quyết định nghỉ hưu và giao lại trung tâm thương mại cho những người em và con cái của họ, cuộc chiến thừa kế bùng nổ giữa các thành viên gia tộc. Ai cũng có tham vọng tiếp quản chiếc ghế quyền lực của bà Thara: từ người em trai thân tín, cô em gái ngoài giá thú đến cả những đứa cháu ôm tham vọng lớn lao cùng nhiệt huyết sáng tạo của tuổi trẻ. Mâu thuẫn, âm mưu và tham vọng biến cả gia đình thành chiến trường không khoan nhượng trong cuộc chiến tranh giành vị trí Người Thừa Kế Số 1.</p>', 'Hoàn Tất (20/20)', 14, 'series', 'completed', 11, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Sinjai Plengpanich","avatar":""},{"name":"Kathaleeya McIntosh","avatar":""},{"name":"Saksit Tangthong","avatar":""},{"name":"Tonkhao Chayuth Nitichakorn","avatar":""},{"name":"New Akaravin Nanthipat","avatar":""},{"name":"Porapat Srikajorn","avatar":""},{"name":"Son Pannathorn Anankittilert","avatar":""},{"name":"Pow Pawarada Viravan","avatar":""},{"name":"Sanya Kunakorn","avatar":""},{"name":"Khunakon Puraso","avatar":""},{"name":"Amarin Nitipon","avatar":""},{"name":"Vasin Asvanarunat","avatar":""},{"name":"Puma","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Thayat Mai Lek 1","Descendant Number 1","ทายาทหมายเลข 1"]', 1784690324144);
