INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-thua-ke-so-1', 'Người Thừa Kế Số 1', 'The Successor', 'người thừa kế số 1 the successor sinjai plengpanich kathaleeya mcintosh saksit tangthong tonkhao chayuth nitichakorn new akaravin nanthipat porapat srikajorn son pannathorn anankittilert pow pawarada viravan sanya kunakorn khunakon puraso amarin nitipon vasin asvanarunat puma thayat mai lek 1 descendant number 1 ทายาทหมายเลข 1', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khemjira-phai-song-sot', 'Khemjira Phải Sống Sót', 'Khemjira', 'https://phimimg.com/upload/vod/20250811-1/daac30998bc3ef0062d960eca2c0cc85.jpg', 'https://phimimg.com/upload/vod/20250811-1/9cb9cc1e14ad256d42c4e523fe220760.jpg', '<p>Sinh ra trong một gia đình bị nguyền rủa, mẹ của Khem đã đặt cho anh một cái tên con gái – Khemjira – để bảo vệ anh khỏi cái chết trước tuổi 20. Anh luôn tin vào điều đó cho đến khi bước sang tuổi 19, sự thật mới dần hé lộ.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Napatsakorn Pingmuang","avatar":""},{"name":"Harit Buayoi","avatar":""},{"name":"Wannakorn Reungrat","avatar":""},{"name":"Matimun Sreeboonrueang","avatar":""},{"name":"Ausadaporn Siriwattanakul","avatar":""},{"name":"Janistar Phomphadungcheep","avatar":""},{"name":"Natthamon Jantraviphart","avatar":""},{"name":"Jennis Oprasert","avatar":""},{"name":"Phirunwat Promrat","avatar":""},{"name":"Krittanai Arsalprakit","avatar":""},{"name":"Kanticha Chumma","avatar":""},{"name":"Manita Chobchuen","avatar":""},{"name":"H","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["灵魂重生","撞邪少年柯美","Khemjira Must Survive","Spirit Reborn","Khemjira The Series","켐지라 : 운명을 거스르는 소년","Кхемджира","Kemjira Will Survive","Khemjira Tong Rot","เขมจิราต้องรอด"]', 1784690324144);
