INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khemjira-phai-song-sot', 'Khemjira Phải Sống Sót', 'Khemjira', 'khemjira phải sống sót khemjira napatsakorn pingmuang harit buayoi wannakorn reungrat matimun sreeboonrueang ausadaporn siriwattanakul janistar phomphadungcheep natthamon jantraviphart jennis oprasert phirunwat promrat krittanai arsalprakit kanticha chumma manita chobchuen h 灵魂重生 撞邪少年柯美 khemjira must survive spirit reborn khemjira the series 켐지라 : 운명을 거스르는 소년 кхемджира kemjira will survive khemjira tong rot เขมจิราต้องรอด', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-chua-ke-ve-ke-bat-tu', 'Chuyện Chưa Kể Về Kẻ Bất Tử', 'Revamp: The Undead Story', 'https://phimimg.com/upload/vod/20250824-1/8a2eb83491ee2233ac45bfc6bd823b81.jpg', 'https://phimimg.com/upload/vod/20250824-1/c8ae3c7de8597c88ae3dfb852a087460.jpg', '<p>Chàng trai 24 tuổi Punn (do Prem Warut thủ vai), là chủ một tiệm đồ cổ. Một ngày nọ, theo lời nhờ vả của người bạn làm chủ phòng tranh, cậu nhận lời vụ phục chế một bức tranh bị hủy hoại trong hoàn cảnh kỳ lạ. Trong lúc phục chế lại bức tranh, Punn vô tình bị một mảnh kính vỡ làm bị thương, máu của cậu thấm vào bức tranh. Hành động ấy đánh thức Ramil (do Boun Noppanut thủ vai), hậu duệ cuối cùng của một dòng máu ma cà rồng, người đã bị phong ấn trong tranh hơn một thế kỷ. Nhưng Ramil hiện tại đã mất sức mạnh, trở thành mục tiêu săn đuổi không khoan nhượng của những “thợ săn”. Punn được giao sứ mệnh giúp Ramil khôi phục sức mạnh. Cả hai cùng bắt đầu cuộc hành trình truy tìm những người hầu cũ của Ramil - những kẻ đang ẩn mình trong thế giới loài người. Trong thời gian hợp tác, mối quan tình bạn giữa Punn và Ramil dần trở nên sâu sắc, rồi nảy sinh tình yêu và tin tưởng.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 13, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Noppanut Guntachai","avatar":""},{"name":"Warut Chawalitrujiwong","avatar":""},{"name":"Jiruntanin Trairattanayon","avatar":""},{"name":"Tinnasit Isarapongporn","avatar":""},{"name":"Napat Patcharachavalit","avatar":""},{"name":"Kay Lertsittichai","avatar":""},{"name":"Ploynira Hiruntaveesin","avatar":""},{"name":"Chayapol Jutamas","avatar":""},{"name":"Chayakorn Jutamas","avatar":""},{"name":"Stamp Panachkorn Rueksiriaree","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b