INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ta-la-ngai-khun-xinh-dep-nhat', 'Ta Là Ngài Khun Xinh Đẹp Nhất', 'The Most Beautiful Count', 'https://phimimg.com/upload/vod/20250803-1/523c40eda740a1c715b191a704b757e4.jpg', 'https://phimimg.com/upload/vod/20250803-1/ddf54a097d11a8123182b38590bde4e4.jpg', '<p>Sau khi tỉnh dậy trong một kiếp trước, một biểu tượng đồng tính đầy kiêu hãnh phát hiện mình tái sinh thành một quý tộc trong vương quốc hà khắc, nơi tình yêu đồng giới bị cấm đoán và quyền lực có thể giết người. Để sinh tồn, anh buộc phải che giấu con người thật và đối mặt với những âm mưu chốn hoàng cung.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Supanut Lourhaphanich","avatar":""},{"name":"Obrnithi Leelavetchabutr","avatar":""},{"name":"Asre Wattanayakul","avatar":""},{"name":"Pataraphol Wanlopsiri","avatar":""},{"name":"Thanakorn Techawicha","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Soy el Conde Más Bello","It''s Me, The Most Beautiful Khun in Siam","I''m The Most Beautiful Count","ฉันนี่แหละท่านขุนที่สวยที่สุด"]', 1784690324144);
