INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ta-la-ngai-khun-xinh-dep-nhat', 'Ta Là Ngài Khun Xinh Đẹp Nhất', 'The Most Beautiful Count', 'ta là ngài khun xinh đẹp nhất the most beautiful count supanut lourhaphanich obrnithi leelavetchabutr asre wattanayakul pataraphol wanlopsiri thanakorn techawicha soy el conde más bello it''s me, the most beautiful khun in siam i''m the most beautiful count ฉันนี่แหละท่านขุนที่สวยที่สุด', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lo-hong-bao-mat-2025', 'Lỗ Hổng Bảo Mật', 'Zero Day Attack', 'https://phimimg.com/upload/vod/20250906-1/06331c107949309502738137a4fb6118.jpg', 'https://phimimg.com/upload/vod/20250906-1/00cb0901743ceb60a4362f6d8f357c4c.jpg', '<p>Bộ phim lấy bối cảnh giả tưởng về một cuộc xâm lược Đài Loan của Quân Giải phóng Nhân dân Trung Quốc. Cốt truyện tập trung vào một cuộc chiến tranh mạng quy mô lớn, khai thác các lỗ hổng zero-day để tấn công hệ thống cơ sở hạ tầng của Đài Loan. Mục tiêu là làm tê liệt mọi hoạt động của hòn đảo, từ hệ thống điện, giao thông, viễn thông cho đến tài chính, từ đó mở đường cho một cuộc tấn công quân sự toàn diện. Trong bối cảnh căng thẳng leo thang, các nhân vật chính, bao gồm một chuyên gia an ninh mạng và một chỉ huy quân đội, phải chạy đua với thời gian để xác định nguồn gốc của cuộc tấn công, khắc phục các lỗ hổng bảo mật và chống lại âm mưu xâm lược. Bộ phim làm nổi bật bản chất của chiến tranh lai (hybrid warfare) hiện đại, nơi mà chiến tranh không chỉ diễn ra trên chiến trường mà còn cả trong không gian mạng và tâm lý. Nó cho thấy cách các quốc gia có thể sử dụng công nghệ để gây ra hỗn loạn và phá hoại từ bên trong, thay vì chỉ dựa vào sức mạnh quân sự truyền thống.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Tạ Hân Dĩnh","avatar":""},{"name":"Takahashi Issei","avatar":""},{"name":"Đỗ Vấn Trạch","avatar":""},{"name":"Trang Khải Huân","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["零日網路戰","Zero Day","零日攻擊"]', 1784690324144);
