INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khac-tinh-trong-anh-trang', 'Khắc Tình Trong Ánh Trăng', 'Love In The Moonlight', 'https://phimimg.com/upload/vod/20250924-1/5a98a4a3b989660fe86428b91dc01319.jpg', 'https://phimimg.com/upload/vod/20250924-1/b529011a0183a5c0afb6794bbbf1b042.jpg', '<article><p>Năm 1963 tại Bangkok, một vị hoàng tử được sắp đặt hôn nhân lại đem lòng yêu người em họ của vị hôn thê. Giữa tình yêu và nghĩa vụ, anh buộc phải đưa ra lựa chọn định đoạt cả số phận và tương lai của mình.</p></article>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Peemapol Panichtamrong","avatar":""},{"name":"Satjakorn Chalard","avatar":""},{"name":"Veerinsara Tangkitsuvanich","avatar":""},{"name":"Willie McIntosh","avatar":""},{"name":"Chatchai Plengpanich","avatar":""},{"name":"Dom Haetrakul","avatar":""},{"name":"Rhatha Phongam","avatar":""},{"name":"Duangta Toongkamanee","avatar":""},{"name":"Nut Devahastin Na Ayutthaya","avatar":""},{"name":"Suzana Renaud","avatar":""},{"name":"Wattana Kumthorntip","avatar":""},{"name":"Pympan Chalayanacupt","avatar":""},{"name":"Natha","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["刻在月光里的爱","月光挚情","月下刻爱","Engrave Love in the Moonlight","Salak Rak Nai Saengjan","Love Carved in the Moonlight","Under the Moonlight","สลักรักในแสงจันทร์"]', 1784690324144);
