INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khac-tinh-trong-anh-trang', 'Khắc Tình Trong Ánh Trăng', 'Love In The Moonlight', 'khắc tình trong ánh trăng love in the moonlight peemapol panichtamrong satjakorn chalard veerinsara tangkitsuvanich willie mcintosh chatchai plengpanich dom haetrakul rhatha phongam duangta toongkamanee nut devahastin na ayutthaya suzana renaud wattana kumthorntip pympan chalayanacupt natha 刻在月光里的爱 月光挚情 月下刻爱 engrave love in the moonlight salak rak nai saengjan love carved in the moonlight under the moonlight สลักรักในแสงจันทร์', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hau-cung-linh-van-truyen', 'Hậu Cung Linh Vân Truyện', 'The Ascent Of Ling Yun', 'https://phimimg.com/upload/vod/20251013-1/1a2e79aac2a0f29f0ed16428f5922d65.jpg', 'https://phimimg.com/upload/vod/20251013-1/40b0b5fa31c10d65e49e99d52beeda45.jpg', '<p>Cung nữ Lăng Vân lặng lẽ tiến vào hoàng cung, lấy thân mình làm mồi, từng bước mưu toan và tính toán cẩn trọng. Cuối cùng, nàng leo lên long sàng, trở thành sủng phi nghịch tập, xé toang bộ mặt xấu xa và tàn độc của vị hoàng phi quyền thế nhất chốn hậu cung.Thế nhưng, cũng chính vì vậy mà Lăng Vân rơi vào cảnh vạn kiếp bất phục.Giữa âm mưu, máu và nước mắt chốn thâm cung, liệu nàng có thể toàn mạng thoát thân, và có thể tìm thấy tia hy vọng trong mối tình cấm kỵ đầy đau khổ với người em trai mà nàng không thể yêu?</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Kha Dĩnh","avatar":""},{"name":"Thường Bân","avatar":""},{"name":"Thẩm Chi Dịch","avatar":""},{"name":"Vương Tranh Duệ","avatar":""},{"name":"Cô Chỉ Vân","avatar":""},{"name":"Lãnh Luyến Nhu","avatar":""},{"name":"Hác Trạch Gia","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hou Gong Ling Yun Chuan","宫墙两自知","The Legend of the Concubine Lingyun","后宫凌云传"]', 1784690324144);
