INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-dao-kiem-ton-nghich-thien-nhi-hanh', 'Vạn Đạo Kiếm Tôn: Nghịch Thiên Nhi Hành', 'Sword Sovereign: Heavenbreaker', 'https://phimimg.com/upload/vod/20251024-1/211f4e7f41b6ad71db911be10dd6b961.jpg', 'https://phimimg.com/upload/vod/20251024-1/0267d4dc7fb538600c6b3952f7c77337.jpg', '<p>Nhiều năm trước, để bảo vệ Kiếm Các, Kiếm Nam Thiên đã bị Huyết Vũ Lâu bắt đi. Nhiều năm sau, Huyết Vũ Lâu lại một lần nữa tấn công Kiếm Các nhằm bắt con trai của ông - Kiếm Vô Song. Trong lúc nguy cấp, Hắc Cung Chủ đã cứu Kiếm Vô Song và đưa chàng về Linh Tiêu Cung. Để cứu cha và báo thù cho tông môn, Kiếm Vô Song bắt đầu tu luyện tại đây, đồng thời kết giao với Vương Nguyên, Dương Tái Huyền và Tô Nhu. Thế nhưng, Linh Tiêu Cung - nơi tưởng chừng như là thánh địa - lại ẩn chứa vô vàn nguy cơ. Những thử thách sinh tử đang từng bước cận kề…</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Guo Xingye","avatar":""},{"name":"Zaimire Aheiti","avatar":""},{"name":"Jasper","avatar":""},{"name":"Liu Chenglong","avatar":""},{"name":"郭星治","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Sword Sovereign: Defying the Heavens","万道剑尊之逆天而行"]', 1784690324144);
