INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-xe-giao-hang', 'Tài Xế Giao Hàng', 'The Delivery Rider', 'https://phimimg.com/upload/vod/20251024-1/67ac4533389a0cb573e6b5113bcd0e15.jpg', 'https://phimimg.com/upload/vod/20251024-1/8ee121ecb84626e7a29ee13c2a8b5110.jpg', '<p>Khi đang đi làm cùng cậu con trai nuôi tám tuổi, tài xế giao hàng nọ vô tình chứng kiến một tội ác. Giờ đây, anh phải bảo vệ con mình khỏi những thế lực hung bạo.</p>', 'Full', 1, 'single', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Baron Geisler","avatar":""},{"name":"Euwenn Mikaell","avatar":""},{"name":"Jake Cuenca","avatar":""},{"name":"Jennica Garcia","avatar":""},{"name":"JC Alcantara","avatar":""},{"name":"Malou de Guzman","avatar":""},{"name":"Christian Vasquez","avatar":""},{"name":"Joem Bascon","avatar":""},{"name":"Richard Quan","avatar":""},{"name":"Soliman Cruz","avatar":""},{"name":"Robbie Wachtel","avatar":""},{"name":"Chastity Dizon","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Delivery Rider"]', 1784690324144);
