INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-la-diep-chi-mai', 'Tôi Là Diệp Chi Mai', 'Diep Chi Mai', 'https://phimimg.com/upload/vod/20251001-1/b62fa2459ec3d4b4ee1f6a144b46cb29.jpg', 'https://phimimg.com/upload/vod/20251001-1/b1de193dd6bf3a77ac7009bdb2c00350.jpg', '<p>Diệp Chi Mai là hành trình cảm động và đầy thử thách của Mai, một cô gái tỉnh lẻ có ước mơ trở thành nhà văn nổi tiếng. Là một nhân viên biên tập bị coi thường trong nhà xuất bản, Mai chấp nhận làm người viết thuê cho Tuyết Vân, một nhà văn danh tiếng mất khả năng sáng tác vì bệnh tật. Ban đầu bị lợi dụng, Mai dần chứng minh được tài năng và bản lĩnh của mình qua từng trang viết. Nhưng khi tình yêu, danh vọng, và sự phản bội cùng lúc ập đến, Mai buộc phải lựa chọn giữa danh lợi và tình nghĩa.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 18, 2025, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Phan Thị Mơ","avatar":""},{"name":"Đinh Y Nhung","avatar":""},{"name":"Lương Gia Huy","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324144);
