INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('suyt-nua-thi', 'Suýt Nữa Thì', 'Almost Popular', 'https://phimimg.com/upload/vod/20251024-1/dede5161fa18bbc86a08949630575b19.jpg', 'https://phimimg.com/upload/vod/20251024-1/7c5a88231f36f038b8c2d22ca9e0be92.jpg', '<p>Susie và Bobbie, hai nữ sinh năm hai trung học, quyết tâm theo đuổi ước mơ trở thành thành viên của nhóm POP Girls — hội “nữ hoàng” thống trị ngôi trường. Sau hàng loạt nỗ lực thất bại và những tình huống bẽ bàng, cuối cùng cơ hội lớn nhất đời họ cũng đến.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ruby Rose Turner","avatar":""},{"name":"Reid Miller","avatar":""},{"name":"Isabella Ferreira","avatar":""},{"name":"Ellodee Carpenter","avatar":""},{"name":"Arden Myrin","avatar":""},{"name":"Kathleen Rose Perkins","avatar":""},{"name":"Elijah M. Cooper","avatar":""},{"name":"Avi Angel","avatar":""},{"name":"Victoria Caro","avatar":""},{"name":"Sharlize True","avatar":""},{"name":"Sarah Dorothy Little","avatar":""},{"name":"Sir Cornwell","avatar":""},{"name":"Holden Anderson","avatar":""},{"name":"Jimmy Smagula","avatar":""},{"name":"Allison She","avatar":""},{"name":"Connor Fin","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Nice Girls Not","Almost Popular"]', 1784690324144);
