INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('suyt-nua-thi', 'Suýt Nữa Thì', 'Almost Popular', 'suýt nữa thì almost popular ruby rose turner reid miller isabella ferreira ellodee carpenter arden myrin kathleen rose perkins elijah m. cooper avi angel victoria caro sharlize true sarah dorothy little sir cornwell holden anderson jimmy smagula allison she connor fin nice girls not almost popular', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quang-doi-con-lai-co-ben-ve', 'Quãng Đời Còn Lại Có Bến Về', 'Light Beyond The Reed', 'https://phimimg.com/upload/vod/20251017-1/3786cc62431fa7d84f04cf2b3e9ee0da.jpg', 'https://phimimg.com/upload/vod/20251017-1/2ea184c66d99e25e9a8363a1f8a471f9.jpg', '<p>Diệp Tư Bắc từ nhỏ đã phải nhẫn nhịn, thỏa hiệp và trốn tránh vì bố mẹ cô mang tư tưởng trọng nam khinh nữ nặng nề. Chính sự cam chịu ấy đã khiến Tần Nam, người chồng yêu cô sâu sắc phải giận cô vì không chịu lên tiếng cho bản thân mình. Cuối cùng, Tần Nam không thể tiếp tục chịu đựng được nữa và đề nghị ly hôn. Vào lúc đó, Diệp Tư Bắc lại trở thành nạn nhân của một vụ xâm hại, hoàn toàn rơi vào tuyệt vọng. Khi biết được sự thật, Tần Nam quyết định ở bên cạnh cô, động viên cô tìm tới sự giúp đỡ của pháp luật để đòi lại sự công bằng. Dưới sự can thiệp của cơ quan tư pháp, kẻ gây án bị bắt giam, sự thật được phơi bày. Diệp Tư Bắc và Tần Nam nương tựa lẫn nhau, cùng vượt qua đau thương, hóa giải khúc mắc với gia đình và bắt đầu một cuộc sống mới.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Bân Bân","avatar":""},{"name":"Mao Hiểu Đồng","avatar":""},{"name":"Lưu Đan","avatar":""},{"name":"Thiệu Phong","avatar":""},{"name":"Thạch Vân Bằng","avatar":""},{"name":"Dương Vũ Hy","avatar":""},{"name":"Vu Tân","avatar":""},{"name":"Lục Trung","avatar":""},{"name":"Trần Nhã Hy","avatar":""},{"name":"Mã Tiểu Thiến","avatar":""},{"name":"Mã Nhã Thư","avatar":""},{"name":"Vương Nghệ Thiền","avatar":""},{"name":"Phùng Huy","avatar":""},{"name":"Đồng Việt","avatar":""},{"name":"Vương Quán","avatar":""},{"name":"Phạm Cận Luân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yu Sheng You Ya","余生有涯"]', 1784690324144);
