INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-loi-3', 'Tội Lỗi 3', 'Our Fault', 'https://phimimg.com/upload/vod/20251023-1/3c188da961a3f207118ef7b3ec95f96d.jpg', 'https://phimimg.com/upload/vod/20251023-1/2e736b58e3b666a3ab35af214dce25d2.jpg', '<p>Đám cưới của Jenna và Lion vô tình trở thành chất xúc tác cho cuộc hội ngộ định mệnh giữa Noah và Nick – hai người từng yêu nhau say đắm nhưng chia tay trong tổn thương. Nick, người thừa kế một đế chế kinh doanh lừng lẫy, vẫn chưa thể tha thứ cho quá khứ. Còn Noah, cô gái đang chập chững trên con đường sự nghiệp, cố gắng chôn giấu cảm xúc chưa từng nguôi. Khi ánh mắt họ chạm nhau lần nữa, quá khứ và hiện tại hòa vào nhau – liệu tình yêu có đủ sức xóa nhòa những vết thương cũ, hay hận thù sẽ lại chia cách họ một lần nữa?</p>', 'Full', 1, 'single', 'completed', 20, 2025, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Nicole Wallace","avatar":""},{"name":"Gabriel Guevara","avatar":""},{"name":"Gabriela Andrada","avatar":""},{"name":"Marta Hazas","avatar":""},{"name":"Goya Toledo","avatar":""},{"name":"Iván Sánchez","avatar":""},{"name":"Felipe Londoño","avatar":""},{"name":"Fran Berenguer","avatar":""},{"name":"Alex Bejar","avatar":""},{"name":"Javier Morgade","avatar":""},{"name":"Sergi Mateu","avatar":""},{"name":"Gary Anthony Stennette","avatar":""},{"name":"Noah Casas","avatar":""},{"name":"Vianessa Castaños","avatar":""},{"name":"Eva Ruiz","avatar":""},{"name":"Mariano Venancio","avatar":""},{"name":"Víctor V","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Culpa Nuestra","우리의 잘못","Our Fault","Mūsų