INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('baby-bandito-phan-2', 'Baby Bandito (Phần 2)', 'Baby Bandito (Season 2)', 'https://phimimg.com/upload/vod/20251023-1/556bae208dd810a570adeab642041922.jpg', 'https://phimimg.com/upload/vod/20251023-1/0b84889aa730e2a3f1fd2bd7bbbc12ac.jpg', '<p>Tên anh là Kevin Tapia. Nhưng ở châu Âu, anh được gọi là &quot;IL Baby Bandito&quot;. Đây là câu chuyện về tay trượt ván tiến hành vụ cướp thế kỷ ở Chile.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Chile', 0, '[{"name":"Nicolás Contreras","avatar":""},{"name":"Francisca Armstrong","avatar":""},{"name":"Pablo Macaya","avatar":""},{"name":"Marcelo Alonso","avatar":""},{"name":"Carmen Zabala","avatar":""},{"name":"Lukas Vergara","avatar":""},{"name":"Mauricio Pesutic","avatar":""},{"name":"Paulina Urrutia","avatar":""},{"name":"Mariana Loyola","avatar":""},{"name":"Amparo Noguera","avatar":""},{"name":"Florencia Berner","avatar":""},{"name":"Simón Pesutic","avatar":""},{"name":"Antonia Zegers","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Baby Bandito"]', 1784690324144);
