INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('baby-bandito-phan-2', 'Baby Bandito (Phần 2)', 'Baby Bandito (Season 2)', 'baby bandito (phần 2) baby bandito (season 2) nicolás contreras francisca armstrong pablo macaya marcelo alonso carmen zabala lukas vergara mauricio pesutic paulina urrutia mariana loyola amparo noguera florencia berner simón pesutic antonia zegers baby bandito', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-tuong-bao-thu-cua-toi-hoi-ngot-ngao', 'Đối Tượng Báo Thù Của Tôi Hơi Ngọt Ngào', 'Broken Marriage', 'https://phimimg.com/upload/vod/20251023-1/0c00cf45394cccb2d3107e0c38c21785.jpg', 'https://phimimg.com/upload/vod/20251023-1/aaf581f33359d51a8893547965412f23.jpg', '<p>Trì Hàn là một chủ tịch thành đạt, theo chủ nghĩa kế hoạch hoàn hảo. Với anh, hôn nhân chỉ là một công cụ. Thế nhưng trong ngày cưới, một cô gái bất ngờ hét lớn đã phá hỏng kế hoạch hoàn hảo của anh. &quot;Mọi người nghe đây! Người phụ nữ này không xứng đáng trao lời thề nguyện hôn nhân!&quot; Hóa ra vợ sắp cưới của anh lại chính là kẻ thứ ba quyến rũ người đã có gia đình. Trì Hàn bước ra phản đối thì bị cô gái kia đá một cú, ngã lăn ra đất một cách thảm hại. &quot;Chỉ cần tìm được cô ta... tôi nhất định sẽ trả thù tàn nhẫn.&quot; Hai năm sau, Trì Hàn chuyển văn phòng làm việc, tình cờ gặp lại cô gái ấy - Hàn Mỹ Lộ, ở võ đường Taekwondo cũ kỹ ngay bên cạnh. Hóa ra cô ta còn là võ sư có đẳng cấp? Càng hay! Để trả thù, Trì Hàn liền đăng ký làm học viên của võ đường. Anh tự nhủ phải khiến Hàn Mỹ Lộ yêu mình trước, sau đó sẽ làm tổn thương cô. Nhưng mọi chuyện lại không như mong muốn. Anh nhận ra mình luôn bất giác bị cuốn hút bởi cô, chuyện này khiến anh cảm thấy vô cùng kỳ lạ...</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324144);
