INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-bang-dang-philadelphia', 'Cuộc Chiến Băng Đảng Philadelphia', 'Mob War: Philadelphia Vs. the Mafia', 'https://phimimg.com/upload/vod/20251023-1/6502519efd4f6ed9efbcb29150d4d9af.jpg', 'https://phimimg.com/upload/vod/20251023-1/c9b34a5145bae314b8dd4ad2e4cde6cc.jpg', '<p>Cuộc chiến băng đảng tàn bạo giữa John Stanfa và Joey Merlino đẩy Philadelphia vào cảnh hỗn loạn và đổ máu những năm 1990 trong loạt phim tội phạm có thật hấp dẫn này.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"John Alite","avatar":""},{"name":"Charlotte Lang","avatar":""},{"name":"Angelo Lutz","avatar":""},{"name":"Barry Gross","avatar":""},{"name":"Stephen Lapenta","avatar":""},{"name":"George Anastasiades","avatar":""},{"name":"Joey Merlino","avatar":""},{"name":"John Stanfa","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["黑帮战争：费城黑手党瓦解实录","Guerra al hampa Filadelfia contra la mafiab","Mob War: Philadelphia vs. the Mafia"]', 1784690324144);
