INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-chien-bang-dang-philadelphia', 'Cuộc Chiến Băng Đảng Philadelphia', 'Mob War: Philadelphia Vs. the Mafia', 'cuộc chiến băng đảng philadelphia mob war: philadelphia vs. the mafia john alite charlotte lang angelo lutz barry gross stephen lapenta george anastasiades joey merlino john stanfa 黑帮战争：费城黑手党瓦解实录 guerra al hampa filadelfia contra la mafiab mob war: philadelphia vs. the mafia', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-nang-tokyo-mo-mong-phan-2', 'Cô Nàng Tokyo Mơ Mộng (Phần 2)', 'Tokyo Tarareba Girls (Season 2)', 'https://phimimg.com/upload/vod/20251023-1/c699f0eadb34c046b63e8e38e2fa4bf1.jpg', 'https://phimimg.com/upload/vod/20251023-1/18a363a4bc59294aa3ddcb0cdbfbe640.jpg', '<p>Một phụ nữ 30 tuổi tên Kamata Rinko vẫn độc thân và đang chật vật với nghề biên kịch. Không có bạn trai, cô thường ra ngoài uống rượu với hai người bạn thân là Kaori và Koyuki. Họ thường an ủi nhau bằng những giả định như: “Nếu mình trở nên xinh đẹp hơn, chắc sẽ có chàng trai tốt hơn xuất hiện!” hay “Nếu chúng ta thật lòng yêu nhau, chắc chắn sẽ cưới được!”. Thế nhưng, một ngày nọ, một chàng trai trẻ, điển trai với mái tóc vàng nói thẳng: “Mấy cô toàn là những phụ nữ giả định thôi!”. Ba người bạn buộc phải đối diện với sự thật phũ phàng rằng họ đã không còn là những cô gái trẻ nữa. Rinko bước vào tuổi 30, vẫn chưa trưởng thành trong cảm xúc, vừa tìm kiếm hạnh phúc, vừa vật lộn với chuyện tình cảm và công việc.</p>', 'Tập 1', 10, 'series', 'ongoing', 13, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuriko Yoshitaka","avatar":""},{"name":"Nana Eikura","avatar":""},{"name":"Yuko Oshima","avatar":""},{"name":"Kentaro Sakaguchi","avatar":""},{"name":"Ryohei Suzuki","avatar":""},{"name":"Kei Tanaka","avatar":""},{"name":"Yuta Hiraoka","avatar":""},{"name":"Mokomichi Hayami","avatar":""},{"name":"Eri Murakawa","avatar":""},{"name":"Ren Ishikawa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["東京タラレバ娘"]', 1784690324144);
