INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-thanh-florence', 'Quái Vật Thành Florence', 'The Monster Of Florence', 'https://phimimg.com/upload/vod/20251023-1/8168ad6e7e9bcdec9d9370d4ce6bf08d.jpg', 'https://phimimg.com/upload/vod/20251023-1/799b9387032aa283c746f4cdc4081296.jpg', '<p>Khi kẻ giết người hàng loạt nhắm vào các cặp đôi và gieo rắc kinh hoàng tại Ý, chính quyền lần theo một vụ án từ năm 1968 có thể là chìa khóa để tìm ra Quái Vật Florence.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Marco Bullitta","avatar":""},{"name":"Valentino Mannias","avatar":""},{"name":"Francesca Olia","avatar":""},{"name":"Liliana Bottone","avatar":""},{"name":"Giacomo Fadda","avatar":""},{"name":"Antonio Tintis","avatar":""},{"name":"Giordano Mannu","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["佛罗伦萨的恶魔","佛罗伦萨杀人魔","怪物 Il Mostro","佛罗伦萨的怪物","The Monster of Florence","Il Mostro"]', 1784690324144);
