INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-ngot-ngao', 'Bí Mật Ngọt Ngào', 'Sweet Secrets', 'https://phimimg.com/upload/vod/20251014-1/6ee4cf3c78f4c12691028b24dd5e3dd6.jpg', 'https://phimimg.com/upload/vod/20251014-1/ea35573113af8017004e02686be0cefa.jpg', '<p>Lục Hoa Yến, ngôi sao hàng đầu của Paramount, đến để báo thù cho chị gái mình và gặp Lý Mạc Đồng từ thế giới khác gọi là &quot;Vô Kiếm&quot;. Để tìm ra thần khí giúp &quot;Vô Kiếm&quot; trường tồn, anh phải giết chết nữ ca sĩ phàm trần Lục Hoa Yến, nhưng bất ngờ phát hiện ra cô chính là người yêu kiếp trước của mình. Mối quan hệ yêu hận, yêu và giết bắt đầu.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Thân Hạo Nam","avatar":""},{"name":"Triệu Tử Lạc","avatar":""},{"name":"Dương Tử Nghệ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Whose Secret","甜秘密"]', 1784690324144);
