INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-tao-mua', 'Kẻ Tạo Mưa', 'The Rainmaker', 'https://phimimg.com/upload/vod/20250817-1/a733015464129847b78b3e33bee338d5.jpg', 'https://phimimg.com/upload/vod/20250817-1/f7ee0ea91cc73cbdeb8de822128fe048.jpg', '<p>Vừa tốt nghiệp trường luật, Rudy Baylor phải đối mặt với hai đối thủ nặng ký: “con sư tử tòa án” lão luyện Leo Drummond và cả bạn gái cũ thời đại học, Sarah. Cùng với ông thầy “máu mặt” Bruiser và anh chàng phụ tá luật vụ luộm thuộm Deck, Rudy bất ngờ lật mở hai âm mưu đen tối có mối liên hệ với nhau — tất cả xoay quanh cái chết bí ẩn của con trai khách hàng họ đang đại diện.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Milo Callaghan","avatar":""},{"name":"John Slattery","avatar":""},{"name":"Madison Iseman","avatar":""},{"name":"Lana Parrilla","avatar":""},{"name":"P.J. Byrne","avatar":""},{"name":"Robyn Cara","avatar":""},{"name":"Dan Fogler","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Rainmaker"]', 1784690324144);
