INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-nhan-giau-mat-chuong-2', 'Sát Nhân Giấu Mặt: Chương 2', 'The Strangers: Chapter 2', 'https://phimimg.com/upload/vod/20251023-1/b3c86d997fefe3fc62ccc1eee2621f38.jpg', 'https://phimimg.com/upload/vod/20251023-1/bc5951b0f04959ea8c623978e23f9cf1.jpg', '<p>Sau những sự kiện kinh hoàng ở phần trước, Maya bị mắc kẹt tại một thị trấn nhỏ không lối thoát. Khi màn đêm buông xuống, ba kẻ sát nhân đeo mặt nạ lại xuất hiện, biến nơi đây thành địa ngục trần gian. Maya không chỉ phải chạy trốn mà còn phải đối mặt với quá khứ và nỗi sợ hãi sâu thẳm nhất của mình.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Madelaine Petsch","avatar":""},{"name":"Froy Gutierrez","avatar":""},{"name":"Gabriel Basso","avatar":""},{"name":"Ema Horvath","avatar":""},{"name":"Brooke Lena Johnson","avatar":""},{"name":"Richard Brake","avatar":""},{"name":"Pedro Leandro","avatar":""},{"name":"Rachel Shenton","avatar":""},{"name":"Florian Clare","avatar":""},{"name":"Janis Ahern","avatar":""},{"name":"Pablo Sandstrom","avatar":""},{"name":"JR Esposito","avatar":""},{"name":"Sara Freedland","avatar":""},{"name":"Noah Pierre","avatar":""},{"name":"Jamie Taylor Ballesta","avatar":""},{"name":"Ben Cartwright","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Незнакомцы: Часть вторая","Os Estranhos: Capítulo 2","Os Estranhos - Capítulo 2","The Strangers","Cizinci: Kapitola 2","Les Intrus Chapitre 2","Les Intrus - Chapitre 2","Les Intrus, Chapitre 2","The Strangers: Chapter 2"]', 1784690324144);
