INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mui-sung-va-duc-tin', 'Mũi Súng Và Đức Tin', 'Guns & Moses', 'https://phimimg.com/upload/vod/20251023-1/7d61b51acab9080cd65a59bcf91b5b01.jpg', 'https://phimimg.com/upload/vod/20251023-1/efbfca9204a9d1150ecac414779d5a22.jpg', '<p>Mo Zaltzman, một rabbi Do Thái Hasidic được kính trọng, sống tại một thị trấn nhỏ giữa sa mạc. Khi giáo đoàn của ông bị tấn công dã man, cảnh sát nhanh chóng bắt giữ một thiếu niên da trắng cực đoan từng đe dọa họ trước đó. Tuy nhiên, Rabbi Mo không tin cậu bé là kẻ sát nhân. Không ai chịu điều tra, ông buộc phải tự mình trở thành thám tử. Khi số nạn nhân ngày càng tăng, Rabbi Mo phải học cách cầm súng đối đầu với kẻ thù thật sự — trong một cuộc chiến vừa nguy hiểm vừa đầy thử thách đức tin.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mark Feuerstein","avatar":""},{"name":"Neal McDonough","avatar":""},{"name":"Dermot Mulroney","avatar":""},{"name":"Christopher Lloyd","avatar":""},{"name":"Alona Tal","avatar":""},{"name":"Paulo Costanzo","avatar":""},{"name":"Michael B. Silver","avatar":""},{"name":"Jake Busey","avatar":""},{"name":"Craig Sheffer","avatar":""},{"name":"Zach Villa","avatar":""},{"name":"Ed Quinn","avatar":""},{"name":"Mark Ivanir","avatar":""},{"name":"Gabrielle Ruiz","avatar":""},{"name":"Mercedes Mason","avatar":""},{"name":"Jackson A. Dunn","avatar":""},{"name":"Mila Brener","avatar":""},{"name":"Juju Journey Bre","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Man in the Long Black Coat","Guns and Moses","البنادق و موسي","Guns & Moses"]', 1784690324144);
