INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bua-toi-o-goc-khuat-the-gioi', 'Bữa Tối Ở Góc Khuất Thế Giới', 'The Corner Of The World Is Dinner', 'https://phimimg.com/upload/vod/20251017-1/85b82890c2016b2ad98c5a08c3144ed2.jpg', 'https://phimimg.com/upload/vod/20251017-1/82d7e8667507622233d287244bfe8422.jpg', '<p>Ba cô gái với nghề nghiệp, tính cách và nhịp sống hoàn toàn khác nhau cùng thuê nhà sống chung dưới một mái nhà. Tuy nhiên, họ có một điểm chung — dù trong cuộc sống, tình yêu hay công việc gặp phải bao nhiêu mâu thuẫn hay khó khăn, thì khi màn đêm buông xuống, họ đều vào bếp nấu ăn. Cả ba cùng ngồi lại, nghiêm túc thưởng thức bữa tối. Đối với họ, mọi rắc rối trong ngày dường như đều được giải tỏa sau bữa ăn ấy.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lỗ Dương Dương","avatar":""},{"name":"Lý Khải Hinh","avatar":""},{"name":"Trương Toàn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["世界的角落是晚餐"]', 1784690324144);
