INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-van', 'Già Vân', 'Silver Lining', 'https://phimimg.com/upload/vod/20251018-1/bac6ad55db3d8b4900271c6331e6499d.jpg', 'https://phimimg.com/upload/vod/20251018-1/bcf747d96ec7d610c3640d6557ca61f1.jpg', '<p>Bộ phim kể về Trì Hạ, một nữ cảnh sát trẻ vì muốn điều tra chân tướng vụ án cái chết của cha mẹ nuôi nên đã xin chuyển công tác đến tổ chuyên án thành phố Đông Châu. Tại đây, cô dần quen biết và thấu hiểu Lạc Tầm, tổ trưởng tổ chuyên án. Cả hai cùng phát huy sở trường của mình — kết hợp lý thuyết tâm lý tội phạm xuất sắc và khả năng quan sát tinh tế — để phá giải hàng loạt vụ án bí ẩn. Cuối cùng, họ vạch trần và triệt phá tập đoàn tội phạm đứng sau mọi âm mưu, trả lại sự bình yên và công lý cho thành phố Đông Châu.</p>', 'Hoàn Tất (35/35)', 35, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Võ Giai Di","avatar":""},{"name":"Vương Quảng Nguyên","avatar":""},{"name":"Doãn Tử Vi","avatar":""},{"name":"Triệu Nham Tùng","avatar":""},{"name":"Trần Chấn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Zhe Yun","遮云"]', 1784690324144);
