INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-giao-hang-sinh-tu', 'Chuyến Giao Hàng Sinh Tử', 'Delivery Run', 'https://phimimg.com/upload/vod/20251021-1/cd10a581b3a6a3b42a186a9786aa8a65.jpg', 'https://phimimg.com/upload/vod/20251021-1/0117274ff9b210ed56b57d09e17f4d28.jpg', '<p>Một tài xế giao đồ ăn bị cuốn vào cuộc rượt đuổi chết người giữa vùng hoang dã băng giá của Minnesota, khi anh bị truy đuổi bởi một người lái xe ủi tuyết điên loạn không rõ lí do. Bị cô lập giữa giá rét và hiểm nguy, anh buộc phải tự mình đấu trí và sinh tồn, thoát khỏi kẻ săn đuổi không biết mệt mỏi đang bám theo từng bước.</p>', 'Full', 1, 'single', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Phần Lan', 0, '[{"name":"Alexander Arnold","avatar":""},{"name":"Liam James Collins","avatar":""},{"name":"Arthur Sylense","avatar":""},{"name":"Nadine Higgin","avatar":""},{"name":"Jussi Lampi","avatar":""},{"name":"Joey Palmroos","avatar":""},{"name":"Darren McStay","avatar":""},{"name":"Thom Chacon","avatar":""},{"name":"Jeremiah Crosby","avatar":""},{"name":"Celin El Azizi","avatar":""},{"name":"Thomas Dellinger","avatar":""},{"name":"Alistair Logan","avatar":""},{"name":"Hannu Oikarinen","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Delivery Run"]', 1784690324144);
