INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ga-quan-tro', 'Gã Quản Trò', 'Your Host', 'https://phimimg.com/upload/vod/20251021-1/dbaa687474b086766a0d18efc50de0af.jpg', 'https://phimimg.com/upload/vod/20251021-1/ccabca66f4a0d9f25bce9114d1eb7608.jpg', '<p>Bốn người bị mắc kẹt trong một chương trình trò chơi tàn bạo, nơi họ buộc phải đấu trí với một tên sát nhân hàng loạt biến thái trong cuộc đua nghẹt thở với thời gian. Mỗi bước đi có thể đưa họ đến tự do — hoặc đến một cái kết kinh hoàng.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ella-Rae Smith","avatar":""},{"name":"Jamie Flatters","avatar":""},{"name":"David Angland","avatar":""},{"name":"Joelle Rae","avatar":""},{"name":"Jackie Earle Haley","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Your Host"]', 1784690324144);
