INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-khong-phai-nguoi-de-dai', 'Tôi Không Phải Người Dễ Dãi', 'I''m Not A Casual Person', 'https://phimimg.com/upload/vod/20251018-1/bb7c07b4cd2fb72afe72bb3052f94ce0.jpg', 'https://phimimg.com/upload/vod/20251018-1/9c3ee3ae03119046bdb1243131f3f1a9.jpg', '<p>Trịnh Dĩnh, một nữ diễn viên hạng mười tám bị cả mạng xã hội tẩy chay, lại có châm ngôn sống “tùy tiện mà sống”. Mãi cho đến khi cô vô tình cứu được Thẩm Nhất Phàm — một thiên tài đầu tư mắc bệnh tim, lạnh lùng, độc miệng và luôn muốn kiểm soát mọi thứ, nhưng lại không cho phép cô sống tùy tiện! Trong khi Thẩm Nhất Phàm chỉ còn lại quãng thời gian ngắn ngủi, Trịnh Dĩnh “buông xuôi” thì anh lại “phá game”; cô “nằm im mặc kệ đời” thì anh lại “lật bài phản công”. Một món nợ ân tình trước cái chết dần biến thành ván cược của con tim... Khi nữ hoàng thị phi bất ngờ lội ngược dòng, còn thiên tài lạnh lùng lại sa vào lưới tình, cả hai cùng nhau dùng thái độ “không tùy tiện sống” để làm chấn động cả giới giải trí!</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Thần Tiêu","avatar":""},{"name":"Lưu Hạo Vũ","avatar":""},{"name":"Vương Trạch Hiên","avatar":""},{"name":"Trương Phối Hàn","avatar":""},{"name":"Tôn Đình Hạo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wo Bu Shi Sui Bian De Ren","You''re the Only One","我不是随便的人"]', 1784690324144);
