INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-ban-ac', 'Tính Bản Ác', 'Vicious', 'https://phimimg.com/upload/vod/20251020-1/3c5d2a1adc65b39f6f99278b91f6de6c.jpg', 'https://phimimg.com/upload/vod/20251020-1/6a098eb7ab191767fd498129713c5552.jpg', '<p>Khi Polly nhận được một chiếc hộp bí ẩn, đi kèm với nó là một quy tắc duy nhất: phải đặt vào trong hộp một thứ cô cần, một thứ cô ghét, và một thứ cô yêu. Nếu không tuân theo, chiếc hộp sẽ nuốt chửng mọi thứ — và mọi người — mà cô từng biết.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dakota Fanning","avatar":""},{"name":"Kathryn Hunter","avatar":""},{"name":"Mary McCormack","avatar":""},{"name":"Rachel Blanchard","avatar":""},{"name":"Devyn Nekoda","avatar":""},{"name":"Klea Scott","avatar":""},{"name":"Emily Mitchell","avatar":""},{"name":"Karen Cliche","avatar":""},{"name":"Bauston Camilleri","avatar":""},{"name":"Drew Moore","avatar":""},{"name":"Michael Abbott Jr.","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Vicious"]', 1784690324144);
