INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chua-lanh', 'Chữa Lành', 'The Healing', 'https://phimimg.com/upload/vod/20251020-1/6d9f6595530b85059cff444c41d2db01.jpg', 'https://phimimg.com/upload/vod/20251020-1/4a52202d3bbe2730eae47830541a4c84.jpg', '<p>Lyuba trốn chạy khỏi người chồng bạo hành và tìm đến một khu ẩn dật bí ẩn cùng bạn bè. Tại đó, những nghi lễ siêu thực và ảo giác ám ảnh dần hé lộ những bí mật đen tối, buộc cô phải đối mặt với một lựa chọn kinh hoàng: trốn thoát — hay chấp nhận một số phận lạnh lẽo đang chờ đợi.</p>', 'Full', 1, 'single', 'completed', 23, 2025, 'Vietsub', 'FHD', 'Slovenia', 0, '[{"name":"Alena Mitroshina","avatar":""},{"name":"Wolfgang Cerny","avatar":""},{"name":"Ekaterina Solomatina","avatar":""},{"name":"Vyacheslav Chepurchenko","avatar":""},{"name":"Maxim Khanzhov","avatar":""},{"name":"Victoria Skitskaya","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324144);
