INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-vach-mach-dung', 'Tai Vách Mạch Dừng', 'Other', 'https://phimimg.com/upload/vod/20251020-1/0e3ae94abaad586762019cf5d783d002.jpg', 'https://phimimg.com/upload/vod/20251020-1/b02fa0659507a170f4dacdbaaeb62aec.jpg', '<p>Alice miễn cưỡng trở về ngôi nhà thời thơ ấu sau cái chết đột ngột của người mẹ đã xa cách bấy lâu. Nhưng nơi ấy — dường như bị đóng băng trong thời gian — lại ẩn chứa một bí mật rùng rợn: một hệ thống giám sát công nghệ cao đang theo dõi từng cử động của cô, trong khi một bóng tối bí ẩn luôn rình rập quanh nhà, dần đẩy Alice đến một sự thật kinh hoàng mà cô không thể trốn thoát.</p>', 'Full', 1, 'single', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Olga Kurylenko","avatar":""},{"name":"Jean Schatz","avatar":""},{"name":"Lola Bonaventure","avatar":""},{"name":"Jacqueline Ghaye","avatar":""},{"name":"Sasha Nugent","avatar":""},{"name":"Philip Schurer","avatar":""},{"name":"Ange Nawasadio","avatar":""},{"name":"Julie Maes","avatar":""},{"name":"Milton Riche","avatar":""},{"name":"Anne-Pascale Clairembourg","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Cachés","O.T.H.E.R","Other"]', 1784690324144);
