INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luoi-dao-cua-niem-tin', 'Lưỡi Đao Của Niềm Tin', 'Blade Of Faith', 'https://phimimg.com/upload/vod/20251018-1/7cfdbb3a58df3144fcd40461e2bb0227.jpg', 'https://phimimg.com/upload/vod/20251018-1/1f1c0ad0a84172ebbf2c29246b2a1bf5.jpg', '<p>Năm 1937, thành phố Thiên Tân rơi vào tay quân Nhật, nằm dưới sự kiểm soát của chính quyền bù nhìn. Diệp Thanh Huyền bề ngoài là một công tử phong lưu, nhưng thực chất lại là “Sát thủ thư sinh” khiến bọn Hán gian khiếp sợ. Khi người thầy đáng kính Hồng Đức Minh bị Hán gian sát hại, anh quyết tâm báo thù. Diệp Thanh Huyền hợp tác với đội trừ gian kháng Nhật, tiêu diệt tên phản bội Phương Quý và lôi ra ánh sáng kẻ đứng sau vụ “Trái phiếu Liên Ngân” — tên người Nhật Suzuki. Sau đó, anh gia nhập tổ chức trừ gian. Trong cuộc đối đầu sinh tử với quân Nhật và tay sai, Diệp Thanh Huyền cùng đồng đội đã dùng trí tuệ và lòng dũng cảm phá tan nhiều âm mưu, tiêu diệt các tổ chức Hán gian như Đinh Văn Hội, Tề Khắc Mẫn, đồng thời lập nên đài phát thanh bí mật hỗ trợ lực lượng kháng chiến ở hậu phương Hoa Bắc, góp phần đập tan âm mưu xâm lược của quân Nhật.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Thịnh Thiếu","avatar":""},{"name":"Trình Kim Minh","avatar":""},{"name":"Dương Kỳ Như","avatar":""},{"name":"Triệu Tần","avatar":""},{"name":"Lâu Vũ Kiện","avatar":""},{"name":"San Tịch Kính Nhứt","avatar":""},{"name":"Vương Trắc Tông","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["怒刺"]', 1784690324144);
