INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoai-tinh-tot-dinh', 'Ngoại Tình Tột Đỉnh', 'Perfect Adultery: The Beauty Of Concealment', 'https://phimimg.com/upload/vod/20250709-1/d2e5cbc0d2d50ebe27b15d3a18a17377.jpg', 'https://phimimg.com/upload/vod/20250709-1/06100fc1d5f226ac0a8a2ddf8d458d19.jpg', '<p>Một người chồng tận tụy bắt đầu nghi ngờ sự thủy chung của vợ. Nhưng khi lần theo dấu vết của những bí mật sau cánh cửa hôn nhân, anh dần rơi vào mê cung của dối trá, nơi mọi niềm tin đều có thể bị phản bội và sự thật có cái giá đắt hơn cả tình yêu.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Nimura Sawa","avatar":""},{"name":"Goki Maeda","avatar":""},{"name":"Shuhei Nomura","avatar":""},{"name":"Ayaka Onishi","avatar":""},{"name":"Kaya Soya","avatar":""},{"name":"Miona Hori","avatar":""},{"name":"Naenano","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["完全不伦―隐藏的美学、暴露的觉悟","Our Perfect Deception","完全不倫 ― 隠す美学、暴く覚悟 ―"]', 1784690324144);
