INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lop-hoc-cua-thay-mikami', 'Lớp Học Của Thầy Mikami', 'Mr. Mikami''s Classroom', 'https://phimimg.com/upload/vod/20251020-1/71860cb4910bd86a3ef81a67ee13cd54.jpg', 'https://phimimg.com/upload/vod/20251020-1/6a24a00d0356cfc25a87bc7897fa5d92.jpg', '<p>Takashi Mikami, tốt nghiệp Đại học Tokyo, gia nhập Bộ Giáo dục để cải cách nền giáo dục Nhật Bản nhưng lại thất vọng trước thực tế. Được chuyển đến một trường trung học tư thục, anh đứng lên phản đối chính quyền, sử dụng vai trò giáo viên của mình để thúc đẩy sự thay đổi.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Tori Matsuzaka","avatar":""},{"name":"Riho Yoshioka","avatar":""},{"name":"Masaki Okada","avatar":""},{"name":"Aju Makita","avatar":""},{"name":"Daiken Okudaira","avatar":""},{"name":"Airu Kubozuka","avatar":""},{"name":"Sakura Kiryu","avatar":""},{"name":"Yudai Toyoda","avatar":""},{"name":"Juri Kosaka","avatar":""},{"name":"Akari Takaishi","avatar":""},{"name":"Rintaro Hachimura","avatar":""},{"name":"Yamashita Coki","avatar":""},{"name":"Omi Natsuki","avatar":""},{"name":"Yuka Kageyama","avatar":""},{"name":"Riko Nagase","avatar":""},{"name":"Shoot Mori","avatar":""},{"name":"Seira Anzai","avatar":""},{"name":"Nako Yab","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["御上老师","圣上老师","TBS日曜劇場「御上先生」","Mikami Sensei","御上先生","Mr. Mikami''s Classroom"]', 1784690324144);
