INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-dau-cun-cung', 'Tình Đầu Cún Cưng', 'Love Is For The Dogs', 'https://phimimg.com/upload/vod/20251020-1/c61740a83602b5bbca32cb65bd7c9597.jpg', 'https://phimimg.com/upload/vod/20251020-1/cb6b54550da4efb084ced5456dc51d61.jpg', '<p>Một luật sư ly hôn tên Aiko và bác sĩ thú y Kai tình cờ gắn kết với nhau nhờ... những chú chó cưng. Trong khi đó, Seo-ha – người thừa kế một tập đoàn Hàn Quốc – bất ngờ tìm đến Kai với một nhiệm vụ bí ẩn. Ba con người, ba cuộc sống khác biệt, dần giao nhau qua những mối dây liên kết tưởng như nhỏ bé: tình yêu dành cho thú cưng, sự đồng cảm và khao khát chữa lành. Một câu chuyện tình nhẹ nhàng nhưng sâu sắc, nơi những chú chó trở thành chất xúc tác cho sự kết nối và trưởng thành.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kaya Kiyohara","avatar":""},{"name":"Ryo Narita","avatar":""},{"name":"Na In-woo","avatar":""},{"name":"Riku Hagiwara","avatar":""},{"name":"Emma Miyazawa","avatar":""},{"name":"Kyoko Fukada","avatar":""},{"name":"Goro Kishitani","avatar":""},{"name":"Takeshi Nadagi","avatar":""},{"name":"Kayo Noro","avatar":""},{"name":"Riko Nagase","avatar":""},{"name":"Wan Marui","avatar":""},{"name":"Maki Sakai","avatar":""},{"name":"Noa Kazama","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hatsukoi Dogs","初恋DOGs"]', 1784690324144);
