INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-ngoai-vong-phap-luat', 'Kẻ Ngoài Vòng Pháp Luật', 'Ignite', 'https://phimimg.com/upload/vod/20251020-1/8d754be683477e1fe458199ab077ec3a.jpg', 'https://phimimg.com/upload/vod/20251020-1/d09fbc8c26d90f397b0305b741bdb25f.jpg', '<p>Ryo Uzaki, với khát vọng trở thành luật sư sau cái chết của cha mình, gia nhập một hãng luật nơi các luật sư — vì tiền bạc hoặc công lý — chủ động tìm kiếm và khơi mào các vụ kiện tụng.</p>', 'Full', 11, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shotaro Mamiya","avatar":""},{"name":"Toru Nakamura","avatar":""},{"name":"Moka Kamishiraishi","avatar":""},{"name":"Ryoki Miyama","avatar":""},{"name":"Mitsuhiro Oikawa","avatar":""},{"name":"Ryo","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["IGNITE -法之无法者-","法外狂徒","点燃：法之无法者","点燃 -法之无法者-","IGNITE","イグナイト –法の無法者–"]', 1784690324144);
