INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chong-a-lam-on-chet-di', 'Chồng À, Làm Ơn Chết Đi', 'Please Die My Beloved', 'https://phimimg.com/upload/vod/20251020-1/b77e447abbcc494cc6f7615c00bdcc69.jpg', 'https://phimimg.com/upload/vod/20251020-1/faff804440850e49fb857abc81bd619e.jpg', '<p>Ba người bạn đại học—Maya, Riko và Yurika—đối mặt với những cuộc hôn nhân không hạnh phúc và sự nghiệp đang bị đình trệ ở độ tuổi cuối 30. Khi Yurika thừa nhận đã giết chồng và chồng của Maya biến mất ngay sau đó, cả ba người bắt đầu một hành trình đen tối để tìm lại hạnh phúc...</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yumi Adachi","avatar":""},{"name":"Saki Aibu","avatar":""},{"name":"Sayaka Isoyama","avatar":""},{"name":"Terunosuke Takezai","avatar":""},{"name":"Mitsuomi Takahashi","avatar":""},{"name":"Takashi Tsukamoto","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Por Favor, Muere, Amor Mío","남편이여, 죽어주지 않을래","老公怎麼還不去死","Please Die My Beloved","夫よ、死んでくれないか"]', 1784690324144);
