INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-xa-kiem-son-phuc-ma-truyen', 'Song Xà Kiếm Sơn: Phục Ma Truyện', 'Twin Serpents: Demon Drive', 'https://phimimg.com/upload/vod/20251020-1/d4eb786438c8f95472d95653cee82734.jpg', 'https://phimimg.com/upload/vod/20251020-1/1e57b6173078e2e4be1d1ffd091f4f32.jpg', '<p>Chúa Tể Cửu U làm loạn, bị thầy trò Hứa Thanh đánh trọng thương và trốn thoát. Hứa Thanh nhận lệnh tìm tàn hồn của hắn cùng Nữ Oa Thạch. Anh kết giao với yêu xà Bạch Mộng Sanh. Cửu U mượn xác kẻ khác, nuốt chửng Nữ Oa Thạch và hấp thu yêu lực của Bạch Mộng Sanh, sức mạnh tăng lên gấp bội. Hứa Thanh và Bạch Mộng Sanh hợp hồn tiến vào thân thể Cửu U, Hứa Thanh hi sinh bản thân để cùng hắn đồng quy vu tận, tàn hồn bị phong ấn trong đá. Năm mươi năm sau, sư phụ giúp Hứa Thanh hồi sinh để anh đoàn tụ cùng Bạch Mộng Sanh.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trác Kiệt","avatar":""},{"name":"Phùng Tân Đoạt","avatar":""},{"name":"Tuyết Tường Vân","avatar":""},{"name":"Từ Thơ Kỳ","avatar":""},{"name":"Tôn Nghĩa","avatar":""},{"name":"Lưu Đồng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324144);
