INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mayumi', 'Mayumi', 'Mayumi', 'https://phimimg.com/upload/vod/20251020-1/ad4eaf7724a59a21850e525fc0f30622.jpg', 'https://phimimg.com/upload/vod/20251020-1/af6eb108901d9d2e7baefaee381c7058.jpg', '<p>Một cô gái trẻ khơi dậy trong người bạn của mình cảm giác ham muốn đầu tiên, mở ra hành trình thức tỉnh tình dục cho anh. Nhưng khi cảm xúc dần trở nên sâu sắc, mối liên kết giữa họ lại dẫn đến những tổn thương bất ngờ và hành trình tự khám phá bản thân.</p>', 'Full', 1, 'single', 'completed', 19, 2025, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Aliya Raymundo","avatar":""},{"name":"Marco Mora","avatar":""},{"name":"Salome Salvi","avatar":""},{"name":"Gboy Pablo","avatar":""},{"name":"Maria Denice Valeda","avatar":""},{"name":"Maria Fe Maquiniana","avatar":""},{"name":"Herald Chavez","avatar":""},{"name":"Dave Adrian Uy Panis","avatar":""},{"name":"Roy Mabazza","avatar":""},{"name":"Jessie Reyes","avatar":""},{"name":"Lilia Reyes","avatar":""},{"name":"Jhon Michel Enginares","avatar":""},{"name":"Chester Ibanez","avatar":""},{"name":"Anita Ibanez","avatar":""},{"name":"Jasmine Lopez","avatar":""},{"name":"Jessica Bea","avatar":""},{"name":"P","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mayumi"]', 1784690324144);
