INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-da-thuc-tinh-he-thong-linh-hon-nba', 'Tôi Đã Thức Tỉnh Hệ Thống Linh Hồn NBA', 'Game On! I Just Unlocked The NBA System!', 'https://phimimg.com/upload/vod/20251019-1/791ee261e7c90100be98bf26ae24710e.jpg', 'https://phimimg.com/upload/vod/20251019-1/d3ffd49399697cb42c092da662edec00.jpg', '<p>Vũ Nam tình cờ kích hoạt &quot;Hệ thống Linh Hồn Bóng Rổ”. Để theo đuổi giấc mơ bóng rổ, cô rủ nhóm bạn thân lập nên đội “Búp Bê Barbie Cuồng Nhiệt” để thách đấu các đội bóng rổ nam. Nhờ sự trợ giúp của hệ thống, họ đánh đâu thắng đó. Thế nhưng, trong một trận đấu, hệ thống bất ngờ dừng hoạt động. Dưới sự chỉ dẫn của huấn luyện viên Lưu Vũ, Vũ Nam đã không còn phụ thuộc vào hệ thống, tập hợp sức mạnh của cả đội, cuối cùng giành chức vô địch và nhận được lời mời từ Hiệp hội Bóng rổ Nữ Nhà nghề Mỹ.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 33, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phim Ngắn","slug":"phim-ngan","id":"4f02d28224c0747511790d57fbb63a62"}]', '[]', 1784690324144);
