INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoan-doi-trai-tim', 'Hoán Đổi Trái Tim', 'Queendom (Uncut Ver.)', 'https://phimimg.com/upload/vod/20250817-1/789545b05d2bf7a978d0b86a98924ebc.jpg', 'https://phimimg.com/upload/vod/20250817-1/c9518b9e5ba290ecf93c32f73f2f85e6.jpg', '<p>Rey và Print là kỳ phùng địch thủ từ khi còn ngồi trên ghế giảng đường cho đến khi bước vào ngành giải trí. Họ gặp lại nhau lần nữa khi được chọn để đóng vai chính trong bộ phim hoành tráng của năm. Nhưng trước khi khai máy một tuần, hai cô gái thức dậy và phát hiện ra bị hoán đổi thân xác cho nhau. Các sự kiện kỳ lạ dẫn đến vô vàn rắc rối khiến Rey và Print phải đóng giả làm người kia và không để ai phát hiện. Quan trọng là, cảm xúc trái tim rung động mãnh liệt bắt đầu xuất hiện giữa Rey và Print có nghĩa là gì?</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Nattawadee Pipobpornchai","avatar":""},{"name":"Tarradee Watancharoen","avatar":""},{"name":"Mashannoad Suvanamas","avatar":""},{"name":"Chermawee Suwanpanuchoke","avatar":""},{"name":"Pimolrat Pisolyabutr","avatar":""},{"name":"Jiraphat Sodjam","avatar":""},{"name":"Chinnawat Phattharathanachot","avatar":""},{"name":"Supoj Janjareonborn","avatar":""},{"name":"Karint Aongchum","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["女神之境: 换魂游戏","女王互换记","Королевство","Sonchai Wai Thi Thoe","Sonjai Wai Thi Thoe","Queendom","ซ่อนใจไว้ที่เธอ"]', 1784690324144);
