INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoan-doi-trai-tim', 'Hoán Đổi Trái Tim', 'Queendom (Uncut Ver.)', 'hoán đổi trái tim queendom (uncut ver.) nattawadee pipobpornchai tarradee watancharoen mashannoad suvanamas chermawee suwanpanuchoke pimolrat pisolyabutr jiraphat sodjam chinnawat phattharathanachot supoj janjareonborn karint aongchum 女神之境: 换魂游戏 女王互换记 королевство sonchai wai thi thoe sonjai wai thi thoe queendom ซ่อนใจไว้ที่เธอ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-tinh-xa-la-2025', 'Người Tình Xa Lạ', 'My Beloved Stranger', 'https://phimimg.com/upload/vod/20251019-1/b84598b029c9a15c70c690789f54d02c.jpg', 'https://phimimg.com/upload/vod/20251019-1/6fca18931c1e8af2b369f2af5e4415a0.jpg', '<p>Nội dung phim kể về Riku Kambayashi (Kento Nakajima) người muốn trở thành một nhà văn tiểu thuyết. Minami Maezono (Milet) người muốn trở thành ca sĩ. Họ yêu nhau ngay từ cái nhìn đầu tiên và kết hôn khi còn là sinh viên đại học. Giờ đây, Riku Kambayashi đã đạt được ước mơ trở thành một nhà văn bán chạy nhất, nhưng Minami Maezono vẫn chưa đạt được ước mơ trở thành ca sĩ. Mối quan hệ của cả hai bỗng trở nên có chút xa cách và một cuộc cãi vã lớn đã diễn ra. Một ngày kia, sau khi tỉnh dậy, Riku Kambayashi bỗng nhiên thấy mình chỉ là một biên tập nhỏ trong khi vợ anh trở thành một ca sĩ, nhà soạn nhạc tài năng, người mà anh không thể chạm đến.</p>', 'Full', 1, 'single', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kento Nakajima","avatar":""},{"name":"milet","avatar":""},{"name":"Kenta Kiritani","avatar":""},{"name":"Jun Fubuki","avatar":""},{"name":"Hidekazu Mashima","avatar":""},{"name":"Yurika Nakamura","avatar":""},{"name":"Norito Yashima","avatar":""},{"name":"Wan Marui","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Love at Second Sight","Shiranai Kanojo","知らないカノジョ"]', 1784690324144);
