INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-tinh-xa-la-2025', 'Người Tình Xa Lạ', 'My Beloved Stranger', 'người tình xa lạ my beloved stranger kento nakajima milet kenta kiritani jun fubuki hidekazu mashima yurika nakamura norito yashima wan marui love at second sight shiranai kanojo 知らないカノジョ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-ma-am-ac-linh-tro-lai', 'Ngôi Nhà Ma Ám: Ác Linh Trở Lại', 'Stigmatized Properties: Possession', 'https://phimimg.com/upload/vod/20251019-1/fae9e9b092d689eaa446ff354bcf8496.jpg', 'https://phimimg.com/upload/vod/20251019-1/59f7f08ef5897987ac5f77bc5a1c0b3f.jpg', '<p>Yahiro Kuwata, một chàng trai mang tham vọng trở thành người nổi tiếng, chuyển đến Tokyo và bắt đầu sự nghiệp với vai trò “ngôi sao cư trú trong nhà ma” — sống tại những địa điểm bị ám để ghi hình cho truyền hình và mạng xã hội. Khi liên tục chuyển qua các căn hộ rùng rợn, một quán trọ cũ và ngôi nhà chung đầy buổi cầu hồn, Yahiro dần khám phá ra những bí ẩn tăm tối ẩn giấu bên trong. Thế nhưng, khả năng cảm nhận linh hồn quá nhạy lại khiến anh trở thành mục tiêu của những thế lực siêu nhiên không ngừng truy đuổi. Cho đến khi anh đặt chân vào một ngôi nhà bị nguyền rủa đặc biệt, nơi ẩn chứa nỗi kinh hoàng không thể tưởng tượng cùng sự thật chấn động sẽ thay đổi tất cả.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shota Watanabe","avatar":""},{"name":"Mei Hata","avatar":""},{"name":"Kotaro Yoshida","avatar":""},{"name":"Kenichi Takitoh","avatar":""},{"name":"Tarō Suwa","avatar":""},{"name":"Jiro","avatar":""},{"name":"Maho Yamada","avatar":""},{"name":"Bokuzo Masana","avatar":""},{"name":"Ryo Kato","avatar":""},{"name":"Sho Kaneta","avatar":""},{"name":"Hinako Saeki","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Stigmatized Properties 2","凶宅：附身","事故物件ゾク 恐い間取り"]', 1784690324144);
