INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-san-nguoi-ban-thai', 'Kẻ Săn Người (Bản Thái)', 'Mouse', 'https://phimimg.com/upload/vod/20250802-1/04ccf49f399145251c27a39cdc5e9958.jpg', 'https://phimimg.com/upload/vod/20250802-1/f79b2def4323efacb4b54dfe88d49995.jpg', '<p>Bộ phim lấy bối cảnh khi con người có thể xác định những kẻ rối loạn đa nhân cách thông qua xét nghiệm ADN khi vẫn còn là bào thai. Mang trong người loại gen hiếm này, cảnh sát trẻ tuổi Pacharawit luôn phải tìm cách kiềm chế bản thân để không phạm phải sai lầm không thể cứu vãn. Cuộc sống của Pacharawit lại càng thêm phức tạp khi anh tham gia vào cuộc lùng bắt một tên sát nhân biến thái cùng với Ramil, một cảnh sát vốn rất căm ghét những kẻ mang gen rối loạn nhân cách như anh.<span style="color: rgb(210, 210, 210); font-family: SFProDisplay, Arial, sans-serif; font-size: 14px; text-align: justify; text-wrap-mode: wrap; background-color: rgb(19, 19, 20);"></span></p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 9, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Chanon Santinatornkul","avatar":""},{"name":"Shahkrit Yamnarm","avatar":""},{"name":"Raviyanun Takerd","avatar":""},{"name":"Thasorn Klinnium","avatar":""},{"name":"Chonlathorn Kongyingyong﻿","avatar":""},{"name":"Dhanyabhorn Sondhikandha","avatar":""},{"name":"Gift Wattana Kumthorntip","avatar":""},{"name":"Penpetch Benyakul","avatar":""},{"name":"Kajornsak Rattananissai","avatar":""},{"name":"Yarinda Bunnag","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad3563