INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-sau-dem-toi-vinh-dieu-tram-mac', 'Biển Sâu Đêm Tối (Vinh Diệu Trầm Mặc)', 'Silent Honor', 'https://phimimg.com/upload/vod/20251003-1/5907ce02c86f430ed1e721f43b5bef00.jpg', 'https://phimimg.com/upload/vod/20251003-1/28ea181c0566d374259bdcd518d947f4.jpg', '<p>Năm 1949, trong bối cảnh Đài Loan chìm trong “khủng bố trắng”, tướng Ngô Thạch – Phó Tham mưu trưởng Bộ Quốc phòng Quốc dân đảng và đồng thời là điệp viên ngầm cao cấp nhất của Đảng Cộng sản – đã liều mình thu thập và truyền đạt tin tình báo quân sự tuyệt mật nhằm góp phần vào sự nghiệp thống nhất đất nước. Tuy nhiên, một vụ phản bội đã khiến ông cùng đồng đội rơi vào tay kẻ thù. Dù chịu tra tấn dã man, Ngô Thạch vẫn giữ vững khí tiết, và cuối cùng cùng đồng chí hy sinh anh dũng, để lại huyết mạch trung thành vĩnh viễn trên mảnh đất Đài Loan.</p>', 'Hoàn Tất (39/39)', 39, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dư Hòa Vĩ","avatar":""},{"name":"Ngô Việt","avatar":""},{"name":"Vệ Thần","avatar":""},{"name":"Tăng Lê","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["沉默的荣耀","chen mo de rong  yao","Menyelam Gelap 1950","Silent Honor"]', 1784690324144);
