INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-rieng-minh-ban', 'Chỉ Riêng Mình Bạn', 'Only You', 'https://phimimg.com/upload/vod/20250719-1/7d9520e031e5c840d34a4972758b3230.jpg', 'https://phimimg.com/upload/vod/20250719-1/ba17a90bd6d66640525d080ff679e736.jpg', '<p>Nhiệm vụ bảo vệ người bạn học cũ – nay đã trở thành nghệ sĩ nổi tiếng – dần vượt khỏi khuôn khổ công việc, khi giữa họ nảy sinh tình cảm không ngờ tới.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Sirilak Kwong","avatar":""},{"name":"Kornnaphat Sethratanapong","avatar":""},{"name":"Khemapsorn Sirisukha","avatar":""},{"name":"Nisachon Tuamsoongnuen","avatar":""},{"name":"Paswitch Boorananut","avatar":""},{"name":"Marilyn Kate Gardner","avatar":""},{"name":"Thanchanok Yutthasarnsiri","avatar":""},{"name":"Supoj Janjareonborn","avatar":""},{"name":"Apinun Prasertwattanakul","avatar":""},{"name":"Krittakan Prasitpanit","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["只有你","Only You The Series","Phiang Thoe","เพียงเธอ"]', 1784690324144);
