INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('scandal-chon-cong-so', 'Scandal Chốn Công Sở', 'Office Scandal', 'https://phimimg.com/upload/vod/20251018-1/46b8089cc9af21f2d9ba0683c1f5d07f.jpg', 'https://phimimg.com/upload/vod/20251018-1/cdbc08296568e348b34d7f06cbbe986c.jpg', '<p>Là một nhân viên giỏi giang trong công ty quảng cáo, Won Ha-kyung có vẻ ngoài thành đạt nhưng cuộc sống riêng lại đau khổ: cô kết hôn vội vàng vì có thai trước, sau khi sảy thai, chồng cô là Ahn Jun lại trở nên lạnh nhạt, gia đình chồng thì không ngừng giục cô sinh con. Tám năm qua, những tổn thương đó khiến cô không thở nổi. Vào lúc Ha-kyung sắp sụp đổ, nhân viên thực tập Yoon Jung-woo đã xuất hiện. Jung-woo không hỏi về quá khứ, chỉ lặng lẽ ở bên cạnh ủng hộ cô, khiến Ha-kyung dần tìm lại được sức sống. Sự thay đổi của cô khiến Ahn Jun nghi ngờ, anh cho rằng hai người vượt giới hạn nên đã không duyệt cho Jung-woo trở thành nhân viên chính thức, đồng thời ép Ha-kyung cắt đứt liên lạc với cậu. Nhưng thật ra Ahn Jun chưa bao giờ ngừng yêu Ha-kyung. Giữa chồng và người đàn ông mới, liệu Won Ha-kyung có thể tìm lại tình yêu thật sự và hạnh phúc thuộc về mình không?</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 25, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phim Ngắn","slug":"phim-ngan","id":"4f02d28224c0747511790d57fbb63a62"}]', '[]', 1784690324144);
