INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-phan-sinh-tu', 'Thẩm Phán Sinh Tử', 'Justice Is Mine', 'https://phimimg.com/upload/vod/20250929-1/85209fc585f5c63a45388775ed35bef3.jpg', 'https://phimimg.com/upload/vod/20250929-1/aa703ce349a672b4685f1086d7e2c3e1.jpg', '<p>Con trai của thẩm phán Tần Dự liêm khiết chính trực gây tai nạn khiến con trai của trùm xã hội đen bị thương mà anh đã chọn che giấu sự thật. Trùm xã hội đen vì muốn trả thù cho con nên đã gây ra một trận gió tanh mưa máu. Nữ cảnh sát Đường Huyên kiên trì bảo vệ chính nghĩa, quyết tâm truy tìm sự thật đến cùng.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 10, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hồng Kông', 0, '[{"name":"Trương Gia Huy","avatar":""},{"name":"Hồ Hạnh Nhi","avatar":""},{"name":"Tằng Thuận Hỷ","avatar":""},{"name":"Bào Khởi Tĩnh","avatar":""},{"name":"Trương Triệu Huy","avatar":""},{"name":"Tạ Thiên Hoa","avatar":""},{"name":"Lâm Gia Hoa","avatar":""},{"name":"Hứa Thiệu Hùng","avatar":""},{"name":"Trương Quốc Cường","avatar":""},{"name":"Vương Thức Thanh","avatar":""},{"name":"Vệ La Sa","avatar":""},{"name":"Chu Bách Khang","avatar":""},{"name":"Cốc Tổ Lâm","avatar":""},{"name":"Chu Hàn Ninh","avatar":""},{"name":"Lạc Trấn Vĩ","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Chu Gou Zhi Xue","刍狗之血","芻狗之血","Justice is Mine","Kvodo Chinese Remake","絕命法官"]', 1784690324144);
