INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('menh-huyen-nhat-sinh', 'Mệnh Huyền Nhất Sinh', 'The Hunt', 'https://phimimg.com/upload/vod/20251012-1/71db20c616fbf58cf06089d262b7663e.jpg', 'https://phimimg.com/upload/vod/20251012-1/c3e12738de0b304110e89ff73a91d305.jpg', '<p>Nghê Hướng Đông nhận được lời nhờ vả của người bạn thân Tào Tiểu Quân, mang một chiếc thùng gỗ đến căn nhà hoang trên núi vắng. Thế nhưng anh lại bất ngờ phát hiện trong thùng gỗ ấy lại chính là thi thể của Tào Tiểu Quân. Vợ của Tào Tiểu Quân là Ngô Tế Muội báo cảnh sát để tìm chồng mất tích, đồng thời ám chỉ rằng mọi chuyện đều có liên quan đến Nghê Hướng Đông. Nhưng với tư cách là nhân chứng, lời khai của Ngô Tế Muội trước sau lại...</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hoàng Hiên","avatar":""},{"name":"Lý Canh Hy","avatar":""},{"name":"Trương Triết Hoa","avatar":""},{"name":"Bạch Vũ Phàm","avatar":""},{"name":"Doãn Phưởng","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["一生悬命","The Hunt","命悬一生"]', 1784690324144);
