INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-lung-trum-khung-bo-2', 'Truy Lùng Trùm Khủng Bố 2', 'War 2', 'https://phimimg.com/upload/vod/20251018-1/9cdad9294dc66c49e9982645a45bd943.jpg', 'https://phimimg.com/upload/vod/20251018-1/118e75af2af032c670996a844dfff383.jpg', '<p>Kabir, từng là biểu tượng của lực lượng đặc nhiệm Ấn Độ, nay trở thành kẻ phản bội nguy hiểm nhất. Để ngăn chặn anh ta, quốc gia cử Vikram – một đặc vụ tinh nhuệ, lạnh lùng và đầy ám ảnh – người duy nhất có thể đối đầu Kabir trong trận chiến không khoan nhượng.</p>', 'Full', 1, 'single', 'completed', 19, 2025, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"N.T. Rama Rao Jr.","avatar":""},{"name":"Hrithik Roshan","avatar":""},{"name":"Kiara Advani","avatar":""},{"name":"Ashutosh Rana","avatar":""},{"name":"Anil Kapoor","avatar":""},{"name":"Bobby Deol","avatar":""},{"name":"K.C. Shankar","avatar":""},{"name":"Varun Badola","avatar":""},{"name":"Hearty Singh","avatar":""},{"name":"Soni Razdan","avatar":""},{"name":"Arista Mehta","avatar":""},{"name":"Reshma Bombaywala","avatar":""},{"name":"Vijay Vikram Singh","avatar":""},{"name":"Karan Kishore","avatar":""},{"name":"Imroz Maur","avatar":""},{"name":"Anupam Bhattacharya","avatar":""},{"name":"Benedict","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["War 2","వార్ 2","வார் 2","War 2 (Telugu)","वॉर 2"]', 1784690324144);
