INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-trieu-doi-van-cau-chuyen-sieu-thuc-ve-rabo-de', 'Sóng Triều Đổi Vận: Câu Chuyện Siêu Thực Về Rabo De', 'Turn Of The Tide: The Surreal Story Of Rabo de Peixe', 'https://phimimg.com/upload/vod/20251018-1/ef33f524bda53321ef6dadb93cd1503a.jpg', 'https://phimimg.com/upload/vod/20251018-1/0d0c52c5938f2eca394e5f2079702f30.jpg', '<p>Tháng 6 năm 2001, hàng trăm kg cocain dạt vào một ngôi làng ở Bồ Đào Nha. Bộ phim tài liệu hấp dẫn này cho thấy tác động lâu dài của vụ việc đối với cộng đồng.</p>', 'Full', 1, 'single', 'completed', 30, 2025, 'Vietsub', 'FHD', 'Bồ Đào Nha', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Maré Branca: A Surreal História de Rabo de Peixe"]', 1784690324144);
