INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-nhi-karate-nhung-huyen-thoai', 'Siêu Nhí Karate: Những Huyền Thoại', 'Karate Kid: Legends', 'https://phimimg.com/upload/vod/20250709-1/1cf7b767c500603783e324086284d896.jpg', 'https://phimimg.com/upload/vod/20250709-1/49c2829ec006ae22f834ae519f77fbf4.jpg', '<p>Sau một bi kịch gia đình, thiên tài võ thuật Lý Phong buộc phải rời quê hương Bắc Kinh để chuyển đến New York cùng mẹ. Tại nơi ở mới, khi một người bạn gặp rắc rối và cần giúp đỡ, Lý quyết định tham gia một giải đấu karate. Tuy nhiên, chỉ với kỹ năng kungfu thôi thì chưa đủ. Thầy dạy kungfu của Lý – ông Hàn – đã tìm đến Daniel LaRusso, huyền thoại Karate Kid, để hỗ trợ. Từ đó, Lý học được một cách chiến đấu hoàn toàn mới, kết hợp giữa kungfu và karate để bước vào trận chiến đỉnh cao của võ thuật.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jackie Chan","avatar":""},{"name":"Ben Wang","avatar":""},{"name":"Ralph Macchio","avatar":""},{"name":"Joshua Jackson","avatar":""},{"name":"Sadie Stanley","avatar":""},{"name":"Ming-Na Wen","avatar":""},{"name":"Aramis Knight","avatar":""},{"name":"Wyatt Oleff","avatar":""},{"name":"Shaunette Renée Wilson","avatar":""},{"name":"William Zabka","avatar":""},{"name":"Olivia Yang Avis","avatar":""},{"name":"Aaron Wang","avatar":""},{"name":"Nicholas Carella","avatar":""},{"name":"Tim Rozon","avatar":""},{"name":"Mig Buenacruz","avatar":""},{"name":"Li Li","avatar":""},{"name":"Henri Forget","avatar":""},{"name":"Noé Poblete","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b61