INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hang-xom-hoan-hao', 'Người Hàng Xóm Hoàn Hảo', 'The Perfect Neighbor', 'https://phimimg.com/upload/vod/20251018-1/e604ea5563fefe341e40ea07f1a75265.jpg', 'https://phimimg.com/upload/vod/20251018-1/9ed744c934fec69e8853e7903d3b7bb6.jpg', '<p>Cảnh quay từ camera gắn trên người cảnh sát hé lộ cách một mâu thuẫn dai dẳng giữa hàng xóm biến thành bi kịch chết người trong bộ phim tài liệu về nỗi sợ, định kiến và Luật tự vệ.</p>', 'Full', 1, 'single', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["השכנה המושלמת","La vecina perfecta","The Perfect Neighbor","A Vizinha Perfeita","La Voisine idéale","完美鄰居：美國社區槍擊悲劇","완벽한 이웃","パーフェクト・ネイバー 正当防衛法は どこへ向かうのか","The Perfect Neighbor - Ein Gesetz und seine Folgen","完美鄰居：鄰里衝突悲劇實錄"]', 1784690324145);
