INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-tinh-an-danh', 'Người Tình Ẩn Danh', 'Romantics Anonymous', 'người tình ẩn danh romantics anonymous shun oguri han hyo-joo yuri nakamura ryo narita ayumi ito shima ise keiichiro azuma koya fukuda shiori akita ikuho akiya takato yonemoto sayaka yamaguchi mieko harada eiji okuda meiko kaji jin akanishi koichi sato 匿名的恋人们 浪漫匿名者 ロマンチックアノニマス 로맨틱 어나니머스 匿名の恋人たち', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khai-tu-duc-tin', 'Khai Tử Đức Tin', 'Killing Faith', 'https://phimimg.com/upload/vod/20251017-1/fcc8feb6a4c3b3f9068cde980d49d468.jpg', 'https://phimimg.com/upload/vod/20251017-1/716be842fb9db46c30f6d744b6733006.jpg', '<p>Mùa hè năm 1859, một bác sĩ góa vợ miễn cưỡng đồng ý đưa một người phụ nữ nô lệ vừa được tự do cùng đứa con gái lai da trắng bí ẩn của cô đi trong hành trình năm ngày băng qua miền Tây đẫm máu, để tìm đến một người chữa bệnh bằng đức tin ở thị trấn xa xôi. Người mẹ tin rằng con gái mình bị quỷ ám, còn vị bác sĩ cho rằng cô bé chỉ mắc một căn bệnh lạ. Nhưng dù là lời nguyền hay dịch bệnh, sự thật vẫn không thay đổi: mọi sinh vật mà cô bé chạm vào đều chết một cách bí ẩn.</p>', 'Full', 1, 'single', 'completed', 24, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Guy Pearce","avatar":""},{"name":"DeWanda Wise","avatar":""},{"name":"Bill Pullman","avatar":""},{"name":"Raoul Max Trujillo","avatar":""},{"name":"Ryan de Quintal","avatar":""},{"name":"Emily Katherine Ford","avatar":""},{"name":"Jack Alcott","avatar":""},{"name":"Charlie Talbert","avatar":""},{"name":"Joanna Cassidy","avatar":""},{"name":"Josh McDermitt","avatar":""},{"name":"Keith Jardine","avatar":""},{"name":"Andrew J. West","avatar":""},{"name":"Jamie Neumann","avatar":""},{"name":"Gail Cronauer","avatar":""},{"name":"Teagan Ireland","avatar":""},{"name":"Jimmy E. Jones","avatar":""},{"name":"C","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Devil in the Dust","Ölümcül Dokunuş","İnancı Öldürmek","Проклятие пустоши","Killing Faith"]', 1784690324145);
