INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huong-vi-ky-uc', 'Hương Vị Ký Ức', 'Oishikute Naku Toki', 'https://phimimg.com/upload/vod/20251017-1/57f81ae751621250936f654b0634a13c.jpg', 'https://phimimg.com/upload/vod/20251017-1/868b1c11133fb80ca31f4ed2143f4eef.jpg', '<p>Shinya mất mẹ từ khi còn nhỏ, trong khi Yuka, bạn cùng lớp của cậu, luôn cảm thấy lạc lõng ngay trong chính ngôi nhà của mình. Có lẽ vì cùng mang nỗi cô đơn, cả hai dần trở nên thân thiết khi cùng làm việc cho tờ báo của trường. Thế nhưng, một biến cố bất ngờ xảy ra khiến Yuka đột ngột biến mất, để lại Shinya trong trống trải và chờ đợi, bám víu vào lời hứa cô từng nói. Ba mươi năm sau, sự thật về quá khứ của Yuka cuối cùng cũng được hé lộ.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kento Nagao","avatar":""},{"name":"Ami Touma","avatar":""},{"name":"Rintaro Mizusawa","avatar":""},{"name":"Haruka Imou","avatar":""},{"name":"Ryo Ikeda","avatar":""},{"name":"Kentaro Tamura","avatar":""},{"name":"Yukiko Shinohara","avatar":""},{"name":"Tamae Ando","avatar":""},{"name":"Machiko Ono","avatar":""},{"name":"Mimura","avatar":""},{"name":"Ken Yasuda","avatar":""},{"name":"Dean Fujioka","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Oishikute Naku Toki","Oishikute Nakutoki","When It''s So Delicious You Cry","Sabor y lágrimas","おいしくて泣くとき"]', 1784690324145);
