INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('huong-vi-ky-uc', 'Hương Vị Ký Ức', 'Oishikute Naku Toki', 'hương vị ký ức oishikute naku toki kento nagao ami touma rintaro mizusawa haruka imou ryo ikeda kentaro tamura yukiko shinohara tamae ando machiko ono mimura ken yasuda dean fujioka oishikute naku toki oishikute nakutoki when it''s so delicious you cry sabor y lágrimas おいしくて泣くとき', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-bup-be-cua-gabby-phim-dien-anh', 'Nhà Búp Bê Của Gabby: Phim Điện Ảnh', 'Gabby''s Dollhouse: The Movie', 'https://phimimg.com/upload/vod/20251017-1/782a93884f386715f62395289059eb70.jpg', 'https://phimimg.com/upload/vod/20251017-1/aeca7c1e3157dd05ba19c0b8992bd8a9.jpg', '<p>Gabby cùng bà ngoại Gigi lên đường cho một chuyến đi thú vị đến thành phố mèo rực rỡ Cat Francisco. Nhưng rắc rối ập đến khi ngôi nhà búp bê — vật báu quý giá nhất của Gabby — rơi vào tay Vera, một bà cô kỳ quặc mê mèo. Quyết tâm giành lại, Gabby bước vào cuộc phiêu lưu xuyên thế giới thực, tập hợp lại những chú mèo Gabby Cats và cứu ngôi nhà búp bê trước khi quá muộn.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Laila Lockhart Kraner","avatar":""},{"name":"Gloria Estefan","avatar":""},{"name":"Kristen Wiig","avatar":""},{"name":"Logan Bailey","avatar":""},{"name":"Eduardo Franco","avatar":""},{"name":"Juliet Donenfeld","avatar":""},{"name":"Donovan Patton","avatar":""},{"name":"Sainty Nelsen","avatar":""},{"name":"Maggie Lowe","avatar":""},{"name":"Carla Tassara","avatar":""},{"name":"Tara Strong","avatar":""},{"name":"Kellan Tetlow","avatar":""},{"name":"Secunda Wood","avatar":""},{"name":"Thomas Lennon","avatar":""},{"name":"Jason Mantzoukas","avatar":""},{"name":"Matty Matheson","avatar":""},{"name":"Ego","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5e