INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nha-bup-be-cua-gabby-phim-dien-anh', 'Nhà Búp Bê Của Gabby: Phim Điện Ảnh', 'Gabby''s Dollhouse: The Movie', 'nhà búp bê của gabby: phim điện ảnh gabby''s dollhouse: the movie laila lockhart kraner gloria estefan kristen wiig logan bailey eduardo franco juliet donenfeld donovan patton sainty nelsen maggie lowe carla tassara tara strong kellan tetlow secunda wood thomas lennon jason mantzoukas matty matheson ego a casa mágica da gabby: o filme gabby''s poppenhuis de film la casa de muñecas de gabby - la película : 2025 gabby''s dollhouse: the movie', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pha-ken-hoa-buom', 'Phá Kén Hoá Bướm', 'Long Planned Love', 'https://phimimg.com/upload/vod/20250930-1/947985b14d5db76045beb97ff23439a0.jpg', 'https://phimimg.com/upload/vod/20250930-1/1461c2ddc48ebe218459e9547468ab00.jpg', '<p>Tiểu thư kiêu ngạo Giản Tranh, sau khi bị vị hôn phu phản bội, trong cơn giận dữ đã hủy hôn và kết hôn chớp nhoáng với Châu Đình Yến – chú của vị hôn phu. Giữa những mối quan hệ gia tộc phức tạp và những cuộc đấu trí thương trường, cuộc hôn nhân khởi đầu từ &quot;ơn cứu mạng&quot; này dần biến thành sự cứu rỗi và tình yêu chân thành. Dưới sự che chở của Châu Đình Yến, Giản Tranh từng bước hé mở bí mật vụ bắt cóc thời trung học, đồng thời trưởng thành từ một “vầng trăng điên dại” kiêu kỳ, bướng bỉnh thành một “nữ hoàng” độc lập và sáng suốt. Còn Châu Đình Yến, sự yêu chiều dưới danh nghĩa báo ơn của anh thực ra là tình cảm thầm kín nhiều năm cuối cùng cũng được toại nguyện. Hành trình từ hôn nhân hợp đồng đến tình yêu thật sự, hướng về phía nhau đầy kiên định của cả hai trái tim.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Minh Gia Gia","avatar":""},{"name":"Tôn Tử Hàng","avatar":""},{"name":"Chu Tiêu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["繭成蝶","Jian Cheng Die","Долгожданная любовь","茧成蝶"]', 1784690324145);
