INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khong-ai-thay-chung-ta-roi-di-nadie-nos-vio-partir', 'Không Ai Thấy Chúng Ta Rời Đi (Nadie nos vio partir)', 'No One Saw Us Leave', 'không ai thấy chúng ta rời đi (nadie nos vio partir) no one saw us leave tessa ía natasha dupeyrón emiliano zurita juan manuel bernal flavio medina gustavo bassani alexander varela pavlov caro darman no one saw us leave nadie nos vio partir', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-tieu-tuy-ca', 'Nhất Tiếu Tùy Ca', 'Fated Hearts', 'https://phimimg.com/upload/vod/20251002-1/963a9b6ba509920c19fab7dcc04a06e0.jpg', 'https://phimimg.com/upload/vod/20251002-1/f010d59727852f13d7d75b5de68ee01b.jpg', '<p>Nhất Tiếu Tùy Ca là bộ phim cổ trang tình cảm do ba đạo diễn Chu Duệ Bân (Hương Mật Tựa Khói Sương, Ninh An Như Mộng), Lam Chí Vĩ (Bạch Nguyệt Phạn Tinh) và Cổ Chí Uy (Ninh An Như Mộng) đồng chỉ đạo. Phim quy tụ dàn diễn viên nổi tiếng gồm: Lý Thấm (Trường Phong Phá Lãng, Thất Dạ Tuyết, Quân Trang Thân Yêu), Trần Triết Viễn (Bạn Trai Phản Diện Của Tôi, Đêm Tối Và Bình Minh, Cây Ô Liu Màu Trắng), Hạ Mộng (Thanh Xuân Trong Chiến Hỏa) và Trần Hạc Nhất (Cửu Tiêu Hàn Dạ Noãn). Phim kể về trận chiến tại Bình Lăng, khi nước Cẩm Tú sắp bại trận, nữ xạ thủ áo đỏ Phó Nhất Tiếu bất ngờ bắn trúng đại hoàng tử nước Túc Sa - Phượng Tùy Ca, xoay chuyển cục diện trận chiến. Thế nhưng, ngay sau trận Bình Lăng, Nhất Tiếu lại rơi xuống vực và mất toàn bộ ký ức. Cô được gia đình họ Lăng ở Chính Niệm Sơn Trang cứu sống. Tại đây, cô vô tình gặp lại kẻ địch của mình, Phượng Tùy Ca. Nhìn thấy một Phó Nhất Tiếu hoàn toàn khác, Phượng Tùy Ca linh cảm chuyện này có liên quan đến âm mưu ẩn sau trận chiến năm xưa. Hắn muốn lợi dụng cô để lần ra sự thật, còn Nhất Tiếu cũng buộc phải dựa vào hắn để sống sót giữa vòng vây truy sát. Từ hai địch thủ sống còn, họ trở thành đồng minh bắt buộc, cùng nhau tìm đường sống trong chốn kinh thành ngập tràn âm mưu. Giữa những khoảnh khắc sinh tử, tình yêu dần nảy nở nhưng tiền căn đã trồng xuống oán hận, phụ bạc, dối trá, tiếc nuối, không buông bỏ được. Ai cũng là người chơi cờ, và cũng là quân cờ trong ván cờ số mệnh. Phó Nhất Tiếu và Phượng Tùy Ca chỉ còn cách nắm chặt tay nhau giữa sóng gió, cùng nhau phá giải âm mưu đen tối, đập tan xiềng xích định mệnh - không phụ lòng thiên hạ, cũng không phụ người thương.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 27, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Thẩm","avatar":""},{"name":"Trần Triết Viễn","avatar":""},{"name":"Hạ Mộng","avatar":""},{"name":"Trần Hạc Nhất","avatar":""},{"name":"Tả Diệp","avatar":""},{"name":"Tần Thiên Vũ","avatar":""},{"name":"Tân Khải Lệ","avatar":""},{"name":"Trương Tráng Lang","avatar":""},{"name":"Thịnh Anh Hào","avatar":""},{"name":"Vương Tử Đằng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["绾心记","一笑","笑歌行‎","Corazones destinados","宿敵契約","Судьбоносные сердца","อริรักลิขิตใจ","Fated Hearts","一笑随歌"]', 1784690324145);
