INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hoang-lua-dao-2025', 'Nữ Hoàng Lừa Đảo', 'Confidence Queen', 'https://phimimg.com/upload/vod/20250908-1/0638358d6ca046838cc5fc7fa345027f.jpg', 'https://phimimg.com/upload/vod/20250908-1/0522ebb7143b6468be95a4650bd04e16.jpg', '<p>Phim xoay quanh ba kẻ lừa đảo với kỹ năng siêu việt, chuyên thực hiện các phi vụ tinh vi nhắm vào những kẻ giàu có và tham lam. Yoon Yi Rang – thủ lĩnh của nhóm, sở hữu IQ 165 và tư duy thiên tài. Cô lập một đội với James và Gu-ho để tước đoạt tiền bất hợp pháp của những kẻ xấu và xây dựng sự giàu có cho riêng mình.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Min-young","avatar":""},{"name":"Park Hee-soon","avatar":""},{"name":"Joo Jong-hyuk","avatar":""},{"name":"Hyun Bong-sik","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["信用欺诈师KR","컨피던스맨KR","行騙天下KR","The Confidence Man KR","The Confidence Man","Confidence Queen","컨피던스 맨 KR"]', 1784690324145);
