INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-ky-ao-cua-gumball', 'Thế Giới Kỳ Ảo Của Gumball', 'The Wonderfully Weird World Of Gumball', 'https://phimimg.com/upload/vod/20251015-1/ec5ca6c502bbc00f2f36327809b1d1bc.jpg', 'https://phimimg.com/upload/vod/20251015-1/c3c6bd56ba320a42e2395a696aebd4d0.jpg', '<p>Gumball, một chú mèo xanh tinh nghịch 12 tuổi, và em Darwin, một chú cá vàng biết… đi, tiếp tục kéo theo cô em gái thông minh Anais, mẹ Nicole, bố Richard và cả thị trấn Elmore vào những chuyến phiêu lưu kỳ quặc. Những tình tiết như chiến đấu với đế chế thức ăn nhanh, đối đầu AI si tình, hay ngăn Banana Joe mặc quần đều diễn ra với phong cách hài hước đặc trưng.</p>', 'Hoàn Tất (20/20)', 20, 'hoathinh', 'completed', 22, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Anh', 0, '[{"name":"Alkaio Thiele","avatar":""},{"name":"Hero Hunter","avatar":""},{"name":"Kinza Khan","avatar":""},{"name":"Teresa Gallagher","avatar":""},{"name":"Dan Russell","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["Дивовижний дивний світ Гамболла","The Amazing World of Gumbal","El Maravillosamente Extraño Mundo de Gumball","The Wonderfully Weird World of Gumball"]', 1784690324145);
