INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-cot-nu-ngo-tac-da-o-quai-dam', 'Họa Cốt Nữ Ngỗ Tác: Dạ Ô Quái Đàm', 'Painted Bone Woman', 'https://phimimg.com/upload/vod/20251015-1/7d49261e896406f7abfa9feb406ae002.jpg', 'https://phimimg.com/upload/vod/20251015-1/7c4233c570b36427c800eca8c2071391.jpg', '<p>Câu chuyện được mở ra dưới góc nhìn của nữ pháp y Bắc Tề Kỷ Vân Thư cùng Vương gia Cảnh Vinh khi họ trở thành cộng sự điều tra những vụ án kỳ bí. Trong hành trình phá án, vô số điểm lạ lùng và kịch tính dần hiện rõ, đồng thời khắc họa nên một giang hồ đầy sắc thái “võ lâm”, nơi ân oán tình thù đan xen. Nam nữ chính vừa mang phong thái quả cảm của “cảnh sát hình sự”, vừa có khí chất quyết liệt của “đặc công”, cùng nhau viết nên những thiên truyện kỳ diệu trong một thế giới quan độc đáo.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ứng Hạo Minh","avatar":""},{"name":"Nam Thanh","avatar":""},{"name":"Tiền Địch Địch","avatar":""},{"name":"Hòa Vân Uy","avatar":""},{"name":"Tống Tinh Hàn","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Skeleton Painting","画骨女仵作"]', 1784690324145);
