INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghich-thien-thanh-tien-phan-1', 'Nghịch Thiên Thành Tiên (Phần 1)', 'Be Yourself (Season 1)', 'https://phimimg.com/upload/vod/20250530-1/84126444a7c3ef42ca302e94f2921826.jpg', 'https://phimimg.com/upload/vod/20250530-1/fb266fd2e65b0888e76a24211d532f02.jpg', '<p>Tu luyện trăm năm thành lão quái vật, một ngày ứng kiếp phi thăng, tưởng đâu công đức viên mãn, nào ngờ bị hàng trăm lôi kiếp đánh cho hồn bay phách tán, cuối cùng dung hợp với Triệu Phi Dương, tên vô dụng Triệu gia, vừa mở màn đã có ba mối hôn ước kéo đến hỏi cưới, từ đó bắt đầu cuộc đời anh dũng.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Phan Lộc Vũ","avatar":""},{"name":"Cao Mạn Nhĩ","avatar":""},{"name":"Triệu Mộ Nhan","avatar":""},{"name":"Trần Vũ Linh","avatar":""},{"name":"Dương Tử Nghệ","avatar":""},{"name":"Hác Vận","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ni Tian Cheng Xian","逆天成仙"]', 1784690324145);
