INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuong-xuan-son', 'Thượng Xuân Sơn', 'The Spring Avenger', 'https://phimimg.com/upload/vod/20251015-1/377d49087c7b29970297e59a23009d51.jpg', 'https://phimimg.com/upload/vod/20251015-1/4cb35633ef8bbdd001477407c92d3f78.jpg', '<p>Khương Xuân Vũ (17 tuổi) phải chịu đựng sự hành hạ tàn nhẫn của đội bắt nạt do Cố Niệm cầm đầu, khiến người mẹ nương tựa duy nhất của cô bị rơi lầu tử vong. Thiên thần báo thù Khương Xuân Vũ, người đã trải qua sự tôi luyện trong lửa địa ngục, sắp tái sinh và trở lại. Trong trò chơi báo thù nghẹt thở này, mỗi người sẽ phải trả một cái giá vô cùng đau đớn.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'ongoing', 14, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Mậu Lạc Ân","avatar":""},{"name":"Vu Dương","avatar":""},{"name":"Khương Hiểu Đồng","avatar":""},{"name":"Vương Duệ Tử","avatar":""},{"name":"Từ Anh Lạc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shang Chun Shan","上春山"]', 1784690324145);
