INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thuong-xuan-son', 'Thượng Xuân Sơn', 'The Spring Avenger', 'thượng xuân sơn the spring avenger mậu lạc ân vu dương khương hiểu đồng vương duệ tử từ anh lạc shang chun shan 上春山', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-trom-chiec-vuong-mien-thanh', 'Siêu Trộm: Chiếc Vương Miện Thánh', 'Suspicious Minds', 'https://phimimg.com/upload/vod/20250628-1/324deaca6b835990e6885e61d3333b75.jpg', 'https://phimimg.com/upload/vod/20250628-1/d876a0766c9479ddb81eb06a877b305f.jpg', '<p>Amber – nữ siêu trộm lừng danh – đến Isla Esperanza với một mục tiêu táo bạo: đánh cắp chiếc vương miện thiêng liêng của Santa Águeda, báu vật vô giá đang được canh giữ nghiêm ngặt. Nhưng mọi thứ trở nên rối ren khi Rui, cộng sự cũ từng phản bội cô trong quá khứ, bất ngờ xuất hiện trở lại. Trong cuộc đối đầu giữa lòng tham, lòng tin và những cảm xúc chưa từng dứt, Amber và Rui buộc phải hợp tác một lần nữa. Và rồi, họ nhận ra: kho báu thật sự không nằm trong chiếc vương miện lấp lánh, mà chính là tình yêu tưởng chừng đã mất.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Silvia Alonso","avatar":""},{"name":"Álex González","avatar":""},{"name":"Asier Etxeandia","avatar":""},{"name":"Antonio Pagudo","avatar":""},{"name":"Olga Hueso","avatar":""},{"name":"Albert Baró","avatar":""},{"name":"Alicia Jaziz Zapién","avatar":""},{"name":"Jan Buxaderas","avatar":""},{"name":"Eduardo Gómez","avatar":""},{"name":"Cumelén Sanz","avatar":""},{"name":"Oliver Ruano","avatar":""},{"name":"Milena Radulović","avatar":""},{"name":"Saibon Wang","avatar":""},{"name":"Ainhoa Santamaría","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]