INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sieu-trom-chiec-vuong-mien-thanh', 'Siêu Trộm: Chiếc Vương Miện Thánh', 'Suspicious Minds', 'siêu trộm: chiếc vương miện thánh suspicious minds silvia alonso álex gonzález asier etxeandia antonio pagudo olga hueso albert baró alicia jaziz zapién jan buxaderas eduardo gómez cumelén sanz oliver ruano milena radulović saibon wang ainhoa santamaría thieves: the tiara of st. agatha ladrones: la tiara de santa águeda', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-ben-nong-sung', 'Ngồi Bên Nòng Súng', 'She Rides Shotgun', 'https://phimimg.com/upload/vod/20250906-1/6a78ea70b7034acb254eed645f3a9b54.jpg', 'https://phimimg.com/upload/vod/20250906-1/20ed27f322177b4615dba6f774654388.jpg', '<p>Vừa ra tù và bị kẻ thù truy sát đến cùng, Nate buộc phải bảo vệ Polly — cô con gái 11 tuổi xa cách bấy lâu — bằng mọi giá. Không có gì trong tay và cũng chẳng thể tin ai, Nate và Polly dần hình thành một sợi dây gắn kết giữa lửa đạn. Anh dạy con cách chiến đấu để sinh tồn, còn Polly dạy anh ý nghĩa thật sự của tình yêu vô điều kiện.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Taron Egerton","avatar":""},{"name":"Ana Sophia Heger","avatar":""},{"name":"Odessa A''zion","avatar":""},{"name":"John Carroll Lynch","avatar":""},{"name":"David Lyons","avatar":""},{"name":"Rob Yang","avatar":""},{"name":"Keith Jardine","avatar":""},{"name":"Jamie Bernadette","avatar":""},{"name":"Goldie Tom","avatar":""},{"name":"Kiko Sanchez","avatar":""},{"name":"Loren Anthony","avatar":""},{"name":"Travis Hammer","avatar":""},{"name":"Rebecca Hill Casey","avatar":""},{"name":"Conrad R. Padilla","avatar":""},{"name":"Edgar Damatian","avatar":""},{"name":"Matt Roszak","avatar":""},{"name":"Sa","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["הנוסעת שליד הנהג","La place du mort","Fuga Fatal","She Rides Shotgun","Die Rache der Polly McClusky","Ο τιμωρός","Детка на драйве","我的殺手爸爸","Втікачі","Ela Vai de Copiloto"]', 1784690324145);
