INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-khung-long-tai-sinh', 'Thế Giới Khủng Long: Tái Sinh', 'Jurassic World: Rebirth', 'https://phimimg.com/upload/vod/20250717-1/8cbdfb269ca3805d0f2705f7ea22a2c5.jpg', 'https://phimimg.com/upload/vod/20250717-1/f0b3a51863368ae2706f0844c9bf3226.jpg', '<p>Phim lấy bối cảnh 5 năm sau phần phim Thế Giới Khủng Long: Lãnh Địa (Jurassic World: Dominion). Thế Giới Khủng Long: Tái Sinh mở ra một chương mới đầy tính hành động, chứng kiến một đội khai thác chạy đua đến nơi nguy hiểm nhất trên Trái Đất. Dàn nhân vật chính là bộ ba Scarlett Johansson, Mahershala Ali và Jonathan Bailey dấn thân vào một nhiệm vụ cực kỳ hiểm nguy, đó chính là cố gắng lấy DNA có thể dẫn đến một bước đột phá y học cho nhân loại. Chìa khóa của nó tình cờ lại là DNA của ba con khủng long khổng lồ nhất trên cạn, biển và không trung trong sinh quyển nhiệt đới. Hành trình này sẽ đưa nhóm nhân vật chính băng rừng, vượt biển, đối mặt với nhiều loài khủng long kỳ lạ, nguy hiểm nhưng cũng đầy lý thú, từ đó hé mở nhiều điều bí ẩn mà tạo hóa đã giấu khỏi con người suốt bấy lâu nay.</p>', 'Full', 1, 'single', 'completed', 11, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Scarlett Johansson","avatar":""},{"name":"Jonathan Bailey","avatar":""},{"name":"Mahershala Ali","avatar":""},{"name":"Rupert Friend","avatar":""},{"name":"Manuel Garcia-Rulfo","avatar":""},{"name":"Luna Blaise","avatar":""},{"name":"David Iacono","avatar":""},{"name":"Audrina Miranda","avatar":""},{"name":"Bechir Sylvain","avatar":""},{"name":"Philippine Velge","avatar":""},{"name":"Ed Skrein","avatar":""},{"name":"Adam Loxley","avatar":""},{"name":"Niamh Finlay","avatar":""},{"name":"Julian Edgar","avatar":""},{"name":"Lucy Thackeray","avatar":""},{"name":"Billy Smith","avatar":""},{"name":"Jonny L","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jurassic World 4","Jurassic City","Jurassic World: Rebirth","Jurassic World - Die Wiedergeburt","Jurassic World Renaissance","Jurassic World, Renaissance","Jurassic World - Renaissance","Jurassic World: El Renacer","Jurassic World: Recomeço","Jurassic.World:Rebirth","Jurassic World Rebirth"]', 1784690324145);
