INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-gioi-khung-long-tai-sinh', 'Thế Giới Khủng Long: Tái Sinh', 'Jurassic World: Rebirth', 'thế giới khủng long: tái sinh jurassic world: rebirth scarlett johansson jonathan bailey mahershala ali rupert friend manuel garcia-rulfo luna blaise david iacono audrina miranda bechir sylvain philippine velge ed skrein adam loxley niamh finlay julian edgar lucy thackeray billy smith jonny l jurassic world 4 jurassic city jurassic world: rebirth jurassic world - die wiedergeburt jurassic world renaissance jurassic world, renaissance jurassic world - renaissance jurassic world: el renacer jurassic world: recomeço jurassic.world:rebirth jurassic world rebirth', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xi-trum-2025', 'Xì Trum', 'Smurfs', 'https://phimimg.com/upload/vod/20250814-1/4145f17d7205246578b97ef17a138597.jpg', 'https://phimimg.com/upload/vod/20250814-1/948a6c56cab042a85c7f747c7ed5e8a4.jpg', '<p>Câu chuyện trở lại với ngôi làng Xì Trum, nơi mà mỗi ngày đều là lễ hội. Bỗng một ngày, sự yên bình của ngôi làng bị phá vỡ khi Tí Vua bị bắt cóc một cách bí ẩn bởi hai phù thủy độc ác Gà Mên và Cà Mên. Từ đây, Tí Cô Nương phải dẫn dắt các Tí đi vào thế giới thực để giải cứu ông. Với sự giúp đỡ của những người bạn mới, các Tí sẽ bước vào cuộc phiêu lưu khám phá định mệnh của mình để cứu lấy vũ trụ.</p>', 'Full', 1, 'single', 'completed', 13, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Rihanna","avatar":""},{"name":"James Corden","avatar":""},{"name":"Nick Offerman","avatar":""},{"name":"JP Karliak","avatar":""},{"name":"Dan Levy","avatar":""},{"name":"Amy Sedaris","avatar":""},{"name":"Natasha Lyonne","avatar":""},{"name":"Sandra Oh","avatar":""},{"name":"Jimmy Kimmel","avatar":""},{"name":"Octavia Spencer","avatar":""},{"name":"Nick Kroll","avatar":""},{"name":"Hannah Waddingham","avatar":""},{"name":"Alex Winter","avatar":""},{"name":"Maya Erskine","avatar":""},{"name":"Billie Lourd","avatar":""},{"name":"Xolo Mariduena","avatar":""},{"name":"Kurt Russell","avatar":""},{"name":"John Goodman","avatar":""},{"name":"Chris Mi","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Smerfy","蓝精灵大电影","De Smurfen","Smølferne Filmen","スマーフ／おどるキノコ","სმურფები","Die Schlümpfe - Der große Kinofilm (2025