INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lilo-va-stitch-2025', 'Lilo Và Stitch', 'Lilo & Stitch', 'https://phimimg.com/upload/vod/20250601-1/0d53fd6bad5f669719a67bbc36de366d.jpg', 'https://phimimg.com/upload/vod/20250601-1/8788aef591e34c2d7b3ee86ae2c6d852.jpg', '<p>Bộ phim live-action Lilo và Stitch đưa câu chuyện kinh điển của Disney năm 2002 trở lại với một diện mạo mới, vừa hài hước vừa đầy cảm xúc. Phim theo chân Lilo, một cô bé người Hawaii cô đơn, và Stitch, sinh vật ngoài hành tinh tinh nghịch đang chạy trốn, khi cả hai vô tình tìm thấy nhau và cùng nhau hàn gắn những tan vỡ trong gia đình của Lilo.</p>', 'Full', 1, 'single', 'completed', 11, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Maia Kealoha","avatar":""},{"name":"Sydney Agudong","avatar":""},{"name":"Chris Sanders","avatar":""},{"name":"Zach Galifianakis","avatar":""},{"name":"Billy Magnussen","avatar":""},{"name":"Courtney B. Vance","avatar":""},{"name":"Amy Hill","avatar":""},{"name":"Tia Carrere","avatar":""},{"name":"Kaipo Dudoit","avatar":""},{"name":"Hannah Waddingham","avatar":""},{"name":"Jason Scott Lee","avatar":""},{"name":"Celia Kenney","avatar":""},{"name":"Brutus LaBenz","avatar":""},{"name":"Skyler Bible","avatar":""},{"name":"Judy Nguyen","avatar":""},{"name":"Christian Yeung","avatar":""},{"name":"Courtney","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id"