INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lilo-va-stitch-2025', 'Lilo Và Stitch', 'Lilo & Stitch', 'lilo và stitch lilo & stitch maia kealoha sydney agudong chris sanders zach galifianakis billy magnussen courtney b. vance amy hill tia carrere kaipo dudoit hannah waddingham jason scott lee celia kenney brutus labenz skyler bible judy nguyen christian yeung courtney lilo and stitch ลีโลแอนด์สติทช์ לילו וסטיץ'' lilo et stitch lilo e stitch liloja dhe stiçikmj k disney''s lilo & stitch ليلو وستيتش 史迪仔 stitch lilo és stitch - a csillagkutya リロ&スティッチ лило и стич 星際寶貝：史迪奇 ліло і стіч lilo và stitch lilo i stitch lilo og stitch lilo och stitch lilo & stitch', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vai-tien-truong-an', 'Vải Tiến Trường An', 'The Litchi Road', 'https://phimimg.com/upload/vod/20250607-1/8385ecd20d3b76ef246235b052c0eb5a.jpg', 'https://phimimg.com/upload/vod/20250607-1/8b9aeb9563d575eb184bfdabf018d88e.jpg', '<p>Phim kể về nhân vật chính Lý Thiện Đức bị đồng liêu lừa gạt, từ một giám sự đã biến thành &quot;sứ giả vải thiều&quot;. Ông buộc phải nhận một nhiệm vụ &quot;tử thần&quot;: vận chuyển vải tươi từ Lĩnh Nam đến Trường An để mừng sinh nhật quý phi. Vấn đề là vải thiều &quot;một ngày thay đổi màu, hai ngày đổi mùi hương, ba ngày thay đổi vị&quot;, trong khi Lĩnh Nam cách Trường An hơn năm ngàn dặm, đường sá xa xôi. Làm thế nào để hoàn thành nhiệm vụ trong điều kiện thời gian khắc nghiệt và thiếu thốn như vậy?</p>', 'Hoàn Tất (35/35)', 35, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lôi Giai Âm","avatar":""},{"name":"Nhạc Vân Bằng","avatar":""},{"name":"Na Nhĩ Na Thiến","avatar":""},{"name":"An Điền","avatar":""},{"name":"Lữ Lương","avatar":""},{"name":"Công Lỗi","avatar":""},{"name":"Phùng Gia Di","avatar":""},{"name":"Lô Phương Sinh","avatar":""},{"name":"Triệu Nguỵ","avatar":""},{"name":"Thái Lộ","avatar":""},{"name":"Diêm Tất Quả","avatar":""},{"name":"Chu Mỹ Quân","avatar":""},{"name":"Quách Đào","avatar":""},{"name":"Hàn Đồng Sinh","avatar":""},{"name":"Đậu Kiêu","avatar":""},{"name":"Trương Thiên Ái","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["长安的荔枝剧版","The Litchi Road","长安的荔枝"]', 1784690324145);
