INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-tai-cua-nguoi-chet', 'Gia Tài Của Người Chết', 'Everybody Loves Me When I''m Dead', 'https://phimimg.com/upload/vod/20251014-1/6333b71cd4fb5a33fef099e722eb79fa.jpg', 'https://phimimg.com/upload/vod/20251014-1/3f4604584f8a0eec85d75966353c4cc7.jpg', '<p>Hai nhân viên ngân hàng trộm tiền từ tài khoản của một người phụ nữ quá cố và vô tình vướng vào thế giới tội phạm ngầm ở Pattaya.</p>', 'Full', 1, 'single', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Theeradej Wongpuapan","avatar":""},{"name":"Vachirawich Aranthanawong","avatar":""},{"name":"Chulachak Chakrabongse","avatar":""},{"name":"Fatima Dechawaleekul","avatar":""},{"name":"Kullanat Preeyawat","avatar":""},{"name":"Jirayut Paloprakarn","avatar":""},{"name":"Pitipat Kootrakul","avatar":""},{"name":"Alissa Intusmith","avatar":""},{"name":"Khomsan Nanthajit","avatar":""},{"name":"Naracha Chanthasin","avatar":""},{"name":"Chatcharit Wanitpoonphon","avatar":""},{"name":"Pakapol Srirongmu","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["死后人人爱","ลักกันวันตาย"]', 1784690324145);
