INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gia-tai-cua-nguoi-chet', 'Gia Tài Của Người Chết', 'Everybody Loves Me When I''m Dead', 'gia tài của người chết everybody loves me when i''m dead theeradej wongpuapan vachirawich aranthanawong chulachak chakrabongse fatima dechawaleekul kullanat preeyawat jirayut paloprakarn pitipat kootrakul alissa intusmith khomsan nanthajit naracha chanthasin chatcharit wanitpoonphon pakapol srirongmu 死后人人爱 ลักกันวันตาย', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-nui-sap-qua-gio-tran-ngap-lau', 'Mưa Núi Sắp Qua Gió Tràn Ngập Lầu', 'Storm Upon the Inn', 'https://phimimg.com/upload/vod/20251014-1/36999394b3f33e60b21270022ba5b5c9.jpg', 'https://phimimg.com/upload/vod/20251014-1/180b7ee689330b551fba950c07d7e091.jpg', '<p>Vào cuối triều đại nhà Minh, hoạn quan chuyên quyền, triều chính hiểm ác. Sau một trận thảm sát, gia đình Thị lang Lễ bộ Tạ Hy Quang tan nát, chỉ có con trai út Định Ca không rõ tung tích. Cô gái Bạch Thi Nhi và hiệp khách Dương Thần vì tìm người đã đến Dương Châu và trọ tại khách sạn Phong Mãn Lâu, nhưng không biết rằng mình đã rơi vào tử cục. Các vụ án mạng trong khách sạn liên tiếp xảy ra, người bên cạnh khó phân biệt bạn thù: Tú tài mặt lạnh Lưu Tuấn, rất giống cố nhân đã khuất của nàng, nhưng hắn không từ thủ đoạn loại bỏ từng đối thủ để đoạt lấy vị trí tiên sinh tọa quán; Phản đồ Đông Xưởng Cố Vĩnh Hy mang đến bí mật kinh hoàng của Vô Gian Môn, nhưng cũng mang dã tâm khó lường. Khách sạn vốn là nơi nghỉ chân trên đường tìm người, nay lại trở thành bãi chiến trường (Tu La Tràng) không lối thoát. Trong cục lại có cục, trong án lại có án, ân nhân ngày xưa có thể là đao phủ, đồng minh tưởng chừng thân thiết cũng có thể là kẻ săn mồi. Khi sự thật đến gần, nàng mới giật mình nhận ra, bản thân mình mới chính là con mồi cuối cùng của trò chơi săn đầu người này.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Phong Tuấn Hi","avatar":""},{"name":"Vương Khang","avatar":""},{"name":"Huỳnh Đình","avatar":""},{"name":"Shine","avatar":""},{"name":"Trần Lâm Dư","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shan Yu Yu Lai Feng Man Lou","The Storm is Coming","山雨欲来风满楼"]', 1784690324145);
