INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mo-kim-quyet-thien-tinh-lang', 'Mộ Kim Quyết: Thiên Tinh Lăng', 'Tomb Raiders: Secrets Of Tianxing Tomb', 'https://phimimg.com/upload/vod/20251014-1/d60a57d0ff4269a5b65ee0a0c93a4d1b.jpg', 'https://phimimg.com/upload/vod/20251014-1/c2512c739328984019516d173a75d8e2.jpg', '<p>Phim kể về Hồ Bát Nhất, người quyết tâm tìm lại di cốt của tổ tiên. Anh cùng những người bạn thân là Vương Béo và Đại Kim Nha lên đường tiến vào núi Đại Tiên, nơi ẩn chứa nhiều hiểm nguy khôn lường. Trên hành trình, họ liên tiếp gặp phải những ngôi mộ cổ nghìn năm, hiện tượng kỳ bí “Tứ Quỷ Đà Quan” cùng hàng loạt cơ quan, bẫy chết người. Tuy nhiên, nhờ kinh nghiệm phong phú và sự phối hợp ăn ý, ba người dũng cảm vượt qua mọi thử thách, cuối cùng vạch trần âm mưu đen tối ẩn sau ngôi mộ thiên tinh.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tôn Giao Long","avatar":""},{"name":"Lưu Chiêm Khuê","avatar":""},{"name":"Trương Thiên Văn","avatar":""},{"name":"Từ Hoằng Kiệt","avatar":""},{"name":"Dương Nãi Tình","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Golden Talisman: Star Tomb","摸金玦之鬼门天师","摸金玦电影","摸金玦之天星陵"]', 1784690324145);
