INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mo-kim-quyet-thien-tinh-lang', 'Mộ Kim Quyết: Thiên Tinh Lăng', 'Tomb Raiders: Secrets Of Tianxing Tomb', 'mộ kim quyết: thiên tinh lăng tomb raiders: secrets of tianxing tomb tôn giao long lưu chiêm khuê trương thiên văn từ hoằng kiệt dương nãi tình the golden talisman: star tomb 摸金玦之鬼门天师 摸金玦电影 摸金玦之天星陵', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lau-ngay-moi-biet-long-quan-nhat-cuu-kien-quan-tam', 'Lâu Ngày Mới Biết Lòng Quân (Nhật Cửu Kiến Quân Tâm)', 'Time Reveals The Prince''s Heart', 'https://phimimg.com/upload/vod/20251013-1/472b5f62356b86129cee6ab11e4da4e2.jpg', 'https://phimimg.com/upload/vod/20251013-1/94b40f3793f2e48e592ea849e56c3d59.jpg', '<p>Vào đầu thời Dân Quốc, đại thương gia họ Lưu nổi tiếng khắp vùng. Con gái nuôi của quản gia Lưu gia — Thiên Nhất Vũ — vốn là thanh mai trúc mã với Nhị thiếu gia Lưu Tư Nam, hai người từng đính hôn từ thuở nhỏ. Thế nhưng, ngay trong đêm thành hôn, Nhất Vũ lại bị ép gả cho người anh trai điên loạn của Tư Nam — Lưu Tư Lâm. Mang trong lòng oán hận vì bị cướp mất hạnh phúc, Nhất Vũ vẫn phải giả vờ bình thản, bởi nàng mang theo một nhiệm vụ bí mật — giúp Tư Nam giám sát người anh “điên” của mình. Không ngờ, sự thật dần hé lộ: chính Tư Nam mới là kẻ đứng sau âm mưu hãm hại anh trai, nhằm độc chiếm toàn bộ gia sản. Trong khi đó, Lưu Tư Lâm lại luôn nhẫn nhịn và bao dung trước sự châm chọc, lạnh lùng của Nhất Vũ. Dần dần, nàng bị cảm hóa bởi lòng nhân hậu của người chồng mà mình từng căm ghét. Tình cảm giữa hai người lặng lẽ nảy nở, nhưng lại liên tục bị kẻ khác ly gián, và còn vô tình kéo theo bí mật cái chết của cha mẹ ruột Nhất Vũ, hé mở một âm mưu đen tối ẩn sâu nhiều năm.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lôi Nghệ Hạo","avatar":""},{"name":"Tinh Tĩnh Dương","avatar":""},{"name":"Dương Húc Trạch","avatar":""},{"name":"Tiêu Đĩnh","avatar":""},{"name":"Lưu Tịch Minh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ri Jiu Jian Jun Xin","Time Reveals Your Heart","日久见君心"]', 1784690324145);
