INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ga-baltimore-ngoc-nghech', 'Gã Baltimore Ngốc Nghếch', 'The Baltimorons', 'https://phimimg.com/upload/vod/20251014-1/2ccf01f6d18fbcb594829ab4e601b9d1.jpg', 'https://phimimg.com/upload/vod/20251014-1/0abe4bae0dd476f40d98ee5bc545932a.jpg', '<p>Một người đàn ông vừa cai rượu phải đối mặt với cơn đau răng bất ngờ vào đêm Giáng Sinh — sự cố ấy dẫn anh đến cuộc gặp gỡ định mệnh với nữ nha sĩ lớn tuổi hơn, và cả hai cùng nhau khám phá thành phố Baltimore trong hành trình nảy nở một mối tình ngoài dự kiến.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Michael Strassner","avatar":""},{"name":"Liz Larsen","avatar":""},{"name":"Olivia Luccardi","avatar":""},{"name":"Chris Strassner","avatar":""},{"name":"Lewis Peterson","avatar":""},{"name":"Rob Phoenix","avatar":""},{"name":"Jessie Cohen","avatar":""},{"name":"Zoe Strassner","avatar":""},{"name":"Brian Mendes","avatar":""},{"name":"Mary Catherine Garrison","avatar":""},{"name":"Morgan Dixon","avatar":""},{"name":"Drew Limon","avatar":""},{"name":"Stacy Caspari","avatar":""},{"name":"David Strassner","avatar":""},{"name":"Marina Erickson","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Baltimorons"]', 1784690324145);
