INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-thu-chien-tranh', 'Quái Thú Chiến Tranh', 'Beast of War', 'https://phimimg.com/upload/vod/20251014-1/932697e29ebffc17d3db7cfe4c9f81c2.jpg', 'https://phimimg.com/upload/vod/20251014-1/8fcd6ebd4530dca999b6659717ee87c3.jpg', '<p>Một nhóm lính trẻ người Úc bị đắm tàu khi vượt qua biển Timor trong Thế chiến II. Họ phải sinh tồn trên một chiếc bè nhỏ giữa đại dương, đối mặt với xung đột nội bộ, tấn công từ kẻ thù và một con cá mập trắng khổng lồ, đói khát.</p>', 'Full', 1, 'single', 'completed', 15, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Úc', 0, '[{"name":"Mark Coles Smith","avatar":""},{"name":"Joel Nankervis","avatar":""},{"name":"Lee Tiger Halley","avatar":""},{"name":"Lauren Grimson","avatar":""},{"name":"Steve Le Marquand","avatar":""},{"name":"Masa Yamaguchi","avatar":""},{"name":"Sam Delich","avatar":""},{"name":"Sam Parsonson","avatar":""},{"name":"Maximillian Johnson","avatar":""},{"name":"Tristan McKinnon","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["Terreur en haute mer","Beast of War"]', 1784690324145);
