INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('quai-thu-chien-tranh', 'Quái Thú Chiến Tranh', 'Beast of War', 'quái thú chiến tranh beast of war mark coles smith joel nankervis lee tiger halley lauren grimson steve le marquand masa yamaguchi sam delich sam parsonson maximillian johnson tristan mckinnon terreur en haute mer beast of war', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-cuu-dong-cuc-dao', 'Giải cứu Đông Cực Đảo', 'Dongji Rescue', 'https://phimimg.com/upload/vod/20251014-1/71f97fbcf4ded24fe3f026f6401b13fd.jpg', 'https://phimimg.com/upload/vod/20251014-1/8d20478b906974a9d6524ab08b2e2437.jpg', '<p>Trong Thế chiến II, tại vùng biển gần Chu Sơn, Trung Quốc, một tàu chở hàng Nhật Bản chở tù binh chiến tranh Anh đã bị đánh chìm, khiến hàng ngàn người bị quân đội Nhật Bản mắc kẹt bên trong. Trong tình thế tuyệt vọng này, một nhóm ngư dân từ đảo Đông Tế đã không ngần ngại tiến lên. Được thúc đẩy bởi lòng tốt, lòng dũng cảm và tinh thần kiên cường, họ đã dũng cảm vượt qua biển cả dữ dội để mở ra con đường sống sót cho những tù binh bị mắc kẹt.</p>', 'Full', 1, 'single', 'completed', 19, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhu Yilong","avatar":""},{"name":"Leo Wu","avatar":""},{"name":"Ni Ni","avatar":""},{"name":"Yang Haoyu","avatar":""},{"name":"Chen Minghao","avatar":""},{"name":"Ni Dahong","avatar":""},{"name":"William Franklyn-Miller","avatar":""},{"name":"Li Jiuxiao","avatar":""},{"name":"Wang Yiquan","avatar":""},{"name":"Kevin Lee","avatar":""},{"name":"Soji Arai","avatar":""},{"name":"Rovaif Babar","avatar":""},{"name":"Elaija Chekhov","avatar":""},{"name":"Barret Coates","avatar":""},{"name":"Kei Gambit","avatar":""},{"name":"Austin Hunza","avatar":""},{"name":"Vincent Matile","avatar":""},{"name":"Tommy Shanahan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["东极大营救","Dongji Island","Dongji Rescue","东极岛"]', 1784690324145);
