INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('giai-cuu-dong-cuc-dao', 'Giải cứu Đông Cực Đảo', 'Dongji Rescue', 'giải cứu đông cực đảo dongji rescue zhu yilong leo wu ni ni yang haoyu chen minghao ni dahong william franklyn-miller li jiuxiao wang yiquan kevin lee soji arai rovaif babar elaija chekhov barret coates kei gambit austin hunza vincent matile tommy shanahan 东极大营救 dongji island dongji rescue 东极岛', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-muoi-chua-phai-la-het-ban-thai', 'Ba Mươi Chưa Phải Là Hết (Bản Thái)', 'The Thirsty Thirty', 'https://phimimg.com/upload/vod/20250830-1/8c2cde4688fa94452eaecbe3960bee79.jpg', 'https://phimimg.com/upload/vod/20250830-1/83e6cd324943b985faf83ad79b8092b7.jpg', '<p>Phetploy, Chidchan và Busaba là ba người phụ nữ tuổi 30 với hoàn cảnh và tính cách khác nhau. Phetploy, con dâu của một nữ chính trị gia, luôn phải vật lộn với vô vàn áp lực vô hình để duy trì hình ảnh một gia đình hoàn hảo. Trợ lý biên kịch Chidchan lại thường xuyên xích mích với mẹ chồng vì đã kết hôn nhiều năm mà vẫn chưa có con. Còn Busaba là một nhân viên bán hàng xa xỉ được nhiều người đàn ông giàu có theo đuổi. Ba Mươi Chưa Phải Là Hết (Bản Thái) hé lộ những góc khuất trong sự nghiệp, tình yêu, hôn nhân của họ cũng như những thách thức mà họ phải đối mặt ở ngưỡng tuổi 30 quan trọng.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Rasri Balenciaga","avatar":""},{"name":"Mookda Narinrak","avatar":""},{"name":"Chalida Vijitvongtong","avatar":""},{"name":"Puttichai Kasetsin","avatar":""},{"name":"Arak Amornsupasiri","avatar":""},{"name":"Chaiyapol Poupart","avatar":""},{"name":"Piamchon Damrongsunthornchai","avatar":""},{"name":"Nattaraht Maurice Legrand","avatar":""},{"name":"Ananda Everingham","avatar":""},{"name":"Sushar Manaying","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["三十而已·曼谷篇","30 เพิ่งเริ่มต้น"]', 1784690324145);
