INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngot-ngao-trong-toan-tinh', 'Ngọt Ngào Trong Toan Tính', 'Love Conspiracy', 'https://phimimg.com/upload/vod/20250922-1/e21432da666f7176e3cdf55804a18502.jpg', 'https://phimimg.com/upload/vod/20250922-1/e3655710504fd70b9f9e7ecee242dd07.jpg', '<p>Tiểu thư Tống Tri Chi có gia đình sung túc, cuộc sống hạnh phúc, đem lòng yêu Dịch Ôn Hàn, một chàng trai xuất thân nghèo khó. Nhưng cô lại bị phản bội tàn nhẫn, vướng vào vô số tai tiếng. Trong cơn tuyệt vọng, cô mất hết tất cả và rơi xuống cầu bỏ mạng. Không ngờ số phận cho cô cơ hội sống lại. Ở kiếp này, Tống Tri Chi quyết tâm bảo vệ người thân, trả thù kẻ phản bội, đồng thời bắt tay với Quý Bạch Gian, người nắm quyền của tập đoàn Quý Hoằng, vạch trần bí mật kinh thiên động địa đã bị che giấu nhiều năm. Lần này, cô nhất định sẽ đoạt lại tất cả những gì vốn thuộc về mình!</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 13, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Đái Yên Ni","avatar":""},{"name":"Quách Gia Nam","avatar":""},{"name":"Thái Tường Vũ","avatar":""},{"name":"Phạm Hiểu Đông","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["夫人虐渣要趁早","Xu Yi Chong Ai","蓄意宠爱"]', 1784690324145);
