INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-bac-phu-hoa', 'Canh Bạc Phù Hoa', 'A Gilded Game', 'https://phimimg.com/upload/vod/20250702-1/ac7a886ce2e6f19b2897d2f97ab7a4b6.jpg', 'https://phimimg.com/upload/vod/20250702-1/f494bdec7ca15f0d8c627127bd0fb8fd.jpg', '<p>Phim kể về Cao Hàn (do Âu Hào thủ vai), một sinh viên xuất sắc ngành tài chính, có đạo đức ngay thẳng và khát vọng lớn trong sự nghiệp tài chính. Nhờ mối quan hệ bạn học với Sở Phong, người thừa kế tập đoàn Trác Thông đang chuẩn bị niêm yết, Cao Hàn bất ngờ có được cơ hội thực tập tại ngân hàng đầu tư quốc tế Lam Thạch. Tại đây, anh phải đối mặt với áp lực từ những thực tập sinh khác đều đến từ các trường danh tiếng, có xuất thân quyền quý hoặc được giới thiệu bởi các lãnh đạo cấp cao. So với họ, Cao Hàn trở nên lạc lõng và kém thế. May mắn thay, anh được Trương Thác Đức (do Lưu Đức Hoa thủ vai), chuyên gia phân tích hàng đầu, nhìn trúng và dẫn dắt. Dưới sự chỉ dạy của Trương Thác Đức, Cao Hàn nhanh chóng thích nghi với môi trường làm việc tốc độ cao và áp lực lớn, rèn luyện kỹ năng chuyên môn lẫn đàm phán. Thế nhưng anh dần nhận ra rằng, thành tích trong giới tài chính không đơn thuần là nhờ thực lực, mà còn liên quan đến quyền lực, quan hệ và những luật chơi ngầm đầy khắc nghiệt.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Đức Hoa","avatar":""},{"name":"Âu Hào","avatar":""},{"name":"Nghi Ninh","avatar":""},{"name":"Huỳnh Dịch","avatar":""},{"name":"Tưởng Mộng Kiệt","avatar":""},{"name":"Trịnh Tắc Sĩ","avatar":""},{"name":"Lưu Dĩ Hào","avatar":""},{"name":"Trịnh Tắc Sĩ","avatar":""},{"name":"Trương Thần Quang","avatar":""},{"name":"Thiên Lệ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["猎金之旅","Money Hunt","东方华尔街","東方華爾街","The Trading Floor","獵金·遊戲","Lie jin you xi","獵金．遊戲"]', 1784690324145);
