INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('canh-bac-phu-hoa', 'Canh Bạc Phù Hoa', 'A Gilded Game', 'canh bạc phù hoa a gilded game lưu đức hoa âu hào nghi ninh huỳnh dịch tưởng mộng kiệt trịnh tắc sĩ lưu dĩ hào trịnh tắc sĩ trương thần quang thiên lệ 猎金之旅 money hunt 东方华尔街 東方華爾街 the trading floor 獵金·遊戲 lie jin you xi 獵金．遊戲', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-luu-nien', 'Thí Lưu Niên', 'Rescued The Lost Times', 'https://phimimg.com/upload/vod/20251010-1/8d18244301ca7d68110dd9e2c48cc4b5.jpg', 'https://phimimg.com/upload/vod/20251010-1/65a97feb9291b703b7d3d89f5389ba3f.jpg', '<p>Vào năm thứ mười bốn niên hiệu Đường Thiên Bảo, loạn An Sử bùng nổ, hoàng đế phải chạy về phía tây lánh nạn. Thái giám Trần Tĩnh Biên nắm quyền kiểm soát Trường An, trong tay y giữ “Bức đồ Lưu Doanh trong đêm tối” — bí mật chứa đựng thông tin hậu trường của các nhân vật quyền lực trong thiên hạ. Nhiều phe gián điệp ngấm ngầm nổi dậy tranh đoạt. Lúc này, Phong Ân Nương – tiểu thư xuất thân tướng môn – đơn độc tiến vào Trường An, giả dạng thành nữ y để tiếp cận Trần Tĩnh Biên, tìm cơ hội đoạt lấy “Lưu Doanh Đồ” và truy tìm kẻ đứng sau âm mưu khiến gia tộc Phong bị vu oan diệt môn.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tống Mỹ Na","avatar":""},{"name":"Thường Bân","avatar":""},{"name":"Tần Ngưu Chính Uy","avatar":""},{"name":"Lục Tư Hằng","avatar":""},{"name":"Hạ Vân Khánh","avatar":""},{"name":"Lý Hi Khản","avatar":""},{"name":"Na Phi Sa","avatar":""},{"name":"Khảm Vũ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["弑流年"]', 1784690324145);
