INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thi-luu-nien', 'Thí Lưu Niên', 'Rescued The Lost Times', 'thí lưu niên rescued the lost times tống mỹ na thường bân tần ngưu chính uy lục tư hằng hạ vân khánh lý hi khản na phi sa khảm vũ 弑流年', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-hong', 'Thâm Hồng', 'See The Light', 'https://phimimg.com/upload/vod/20251010-1/396827bdb844fa9a34354ee76173677e.jpg', 'https://phimimg.com/upload/vod/20251010-1/d9c754f8a802bd5fd89fa2af772be514.jpg', '<p>Bộ phim lấy bối cảnh thời Dân Quốc, xoay quanh một nhóm phụ nữ dũng cảm, kể lại câu chuyện về lòng can đảm, tình bạn và công lý dưới một góc nhìn đầy mới mẻ. Trong thời kỳ Dân Quốc – nơi mười dặm phồn hoa, ánh đèn rực rỡ, cuộc sống xa hoa, giữa thành thị tấp nập tồn tại một tiệm cầm đồ mang tên “Thâm Hồng”. Ẩn mình trong góc khuất của đô thị, tiệm chỉ mở cửa khi có phụ nữ bị tổn thương, và mỗi lần như thế, họ sẽ thay mặt công lý để trừng phạt kẻ gây ra đau khổ cho họ. Đứng đầu là chủ tiệm Tư Gia Lệ cùng các cộng sự như Lộ Kinh Tân, nhóm người của tiệm cầm đồ Thâm Hồng trở thành những nghĩa hiệp trong màn đêm, thực thi công lý ngoài vòng pháp luật, giúp đỡ những người phụ nữ đang chìm trong tuyệt vọng. Tuy nhiên, hành động của họ sớm thu hút sự chú ý của Trưởng phòng cảnh sát Chu Mục. Cuộc đối đầu giữa nghĩa cảnh và pháp luật, giữa công lý thực tế và công lý theo quy trình, bắt đầu nổ ra. Và khi Chu Mục truy đuổi nhóm người của Thâm Hồng, một vụ án cũ chấn động từng bị chôn vùi nhiều năm dần dần được phơi bày — vụ án ấy lại liên quan mật thiết đến tất cả những người trong cuộc…</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Hạch","avatar":""},{"name":"Tan Diệm Diệm","avatar":""},{"name":"Phan Khởi Ngôn","avatar":""},{"name":"Chu Hạo Sam","avatar":""},{"name":"Vũ Văn Giác","avatar":""},{"name":"Lưu Kiệt Hỉ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shen Hong Zhi Ming","深红之名"]', 1784690324145);
