INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('old-money-enfes-bir-akam', 'Old Money (Enfes Bir Akşam)', 'Old Money', 'https://phimimg.com/upload/vod/20251012-1/648818a83e8dcac6cdfa8e36a6633669.jpg', 'https://phimimg.com/upload/vod/20251012-1/2796a37d3957f98cc2a8b5d9e6f266de.jpg', '<p>Cuộc sống giàu sang của Nihal bị đe dọa khi một tài phiệt tự thân với khả năng kiếm tiền nhạy bén – và giác quan tình ái còn bén nhạy hơn – khuấy động giới thượng lưu Istanbul.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 26, 2025, 'Vietsub', 'FHD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Engin Akyürek","avatar":""},{"name":"Aslı Enver","avatar":""},{"name":"Dolunay Soysert","avatar":""},{"name":"İsmail Demirci","avatar":""},{"name":"Serkan Altunorak","avatar":""},{"name":"Taro Emir Tekin","avatar":""},{"name":"Selin Şekerci","avatar":""},{"name":"Zeynep Oymak","avatar":""},{"name":"Sedef Avci","avatar":""},{"name":"Ahmet Utlu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Altes Geld, neue Liebe","المال القديم","Enfes Bir Akşam"]', 1784690324145);
