INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('them-muon', 'Thèm Muốn', 'ABO Desire', 'https://phimimg.com/upload/vod/20250713-1/946adfb2326a5198e87904c6677c5275.jpg', 'https://phimimg.com/upload/vod/20250713-1/908b598da98da72515239372be028b85.jpg', '<p>Thịnh Thiếu Du, một Alpha cấp S, trong quá trình thâm nhập công ty đối thủ, đã gặp và bị thu hút bởi Hoa Vịnh — một Omega xinh đẹp nhưng thực chất là Enigma giả Omega để bẫy anh. Trong khi đó, Thẩm Văn Lang, một Alpha khác, phát hiện thư ký Cao Đồ — người luôn giả Beta để che giấu thân phận Omega — đã mang thai con của mình.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 16, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Huang Xing","avatar":""},{"name":"Qiu Dingjie","avatar":""},{"name":"Li Peien","avatar":""},{"name":"Jiang Heng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Chui Xian","垂涎Desire","Deseo: La Serie","Hasrat Duniawi","ไฟเสน่หาเดอะซีรีส์","เกมร้ายใคร่รัก","Desire","Desire The Series","Thèm Muôn","垂涎"]', 1784690324145);
