INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-dung-hong-thoat-khoi-toi', 'Cô Đừng Hòng Thoát Khỏi Tôi', 'You Can''t Escape Me', 'https://phimimg.com/upload/vod/20250714-1/006a41e479323b95d0204d9a289e8a38.jpg', 'https://phimimg.com/upload/vod/20250714-1/11559382817d7a7611945c04c1537825.jpg', '<p>Bộ phim&nbsp;khai thác chủ đề buôn người, lừa đảo trực tuyến và điều tra tội phạm xuyên biên giới. Không chỉ khắc họa cuộc đối đầu căng thẳng giữa lực lượng cảnh sát ngầm và đường dây tội phạm tinh vi, phim còn đan xen nhiều mối quan hệ phức tạp giữa yêu – hận – thù – lý tưởng.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Thúy Ngân","avatar":""},{"name":"Võ Cảnh","avatar":""},{"name":"Lê Phương","avatar":""},{"name":"Lê Hải","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324145);
