INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-tri-trai-tim', 'Bảo Trì Trái Tim', 'Maintenance Required', 'https://phimimg.com/upload/vod/20251011-1/393eceb6e21ceb8244df0b52e02f7373.jpg', 'https://phimimg.com/upload/vod/20251011-1/fa63468f0c4441e324550de844353177.jpg', '<p>Charlie, cô chủ mạnh mẽ của một gara toàn nữ, buộc phải xem lại tương lai của mình khi một đối thủ lớn mang phong cách hào nhoáng mở cửa hàng ngay đối diện. Tìm kiếm sự an ủi, cô tâm sự với một người bạn ẩn danh qua mạng — mà không biết rằng đó chính là Beau, kẻ đang đe dọa công việc kinh doanh của cô. Khi cảm xúc bắt đầu nảy sinh cả trên mạng lẫn ngoài đời, sự thật được phơi bày có thể phá vỡ tất cả.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Madelaine Petsch","avatar":""},{"name":"Jacob Scipio","avatar":""},{"name":"Katy O''Brian","avatar":""},{"name":"Naomi J. Ogawa","avatar":""},{"name":"Madison Bailey","avatar":""},{"name":"Jim Gaffigan","avatar":""},{"name":"Inanna Sarkis","avatar":""},{"name":"Matteo Lane","avatar":""},{"name":"Kerim Hassan","avatar":""},{"name":"Rob Rausch","avatar":""},{"name":"Julee Cerda","avatar":""},{"name":"James Dryden","avatar":""},{"name":"Freddie Pearson","avatar":""},{"name":"Luke Carroll","avatar":""},{"name":"Mimi Slinger","avatar":""},{"name":"Laura Lakshmi","avatar":""},{"name":"Lorena Andrea","avatar":""},{"name":"Le","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["需要维护的爱","Maintenance Required","保养提醒","维修情缘"]', 1784690324145);
