INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bao-tri-trai-tim', 'Bảo Trì Trái Tim', 'Maintenance Required', 'bảo trì trái tim maintenance required madelaine petsch jacob scipio katy o''brian naomi j. ogawa madison bailey jim gaffigan inanna sarkis matteo lane kerim hassan rob rausch julee cerda james dryden freddie pearson luke carroll mimi slinger laura lakshmi lorena andrea le 需要维护的爱 maintenance required 保养提醒 维修情缘', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vong-am-noi-co-do-da-mat-phadaeng-nang-ai', 'Vọng Âm Nơi Cố Đô Đã Mất (Phadaeng Nang Ai)', 'Echoes Of The Lost City', 'https://phimimg.com/upload/vod/20250717-1/ee986c9fac2f9a3f6e67d84af97ad194.jpg', 'https://phimimg.com/upload/vod/20250717-1/c808b7ce358a3ffbf7f47fe3217dad7e.jpg', '<p>Khi còn nhỏ, Airada thường mơ về một thành phố bị chìm xuống hồ. Cô đã được nghe kể về câu chuyện tình tay ba giữa công chúa, hoàng tử và Naga(thần rắn) dẫn đến sự sụp đổ của thành phố. Giờ đây, những giấc mơ đã trở lại và cô bắt đầu tìm hiểu truyền thuyết về Phadaeng Nang Ai. Cô đã gặp Korawit, người trông giống hệt một người đàn ông mà cô chỉ biết trong mơ. Khi nghe tin về việc nhìn thấy một Thần rắn như trong truyền thuyết Phadaeng Nang Ai, Korawit quyết định điều tra. Khi Airada bắt đầu đặt câu hỏi về mối liên hệ của mình với quá khứ, một hành trình chung để khám phá sự thật và phá bỏ lời nguyền cổ xưa của thành phố bắt đầu.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Diana Flipo","avatar":""},{"name":"Yuttana Puangklang","avatar":""},{"name":"Wittaya Teptip","avatar":""},{"name":"Kimmy Thitisan Goodburn","avatar":""},{"name":"Mike Piromporn","avatar":""},{"name":"Orly Tatiya Sonsagun","avatar":""},{"name":"Chalita Suansane","avatar":""},{"name":"Candy Rakkaen","avatar":""},{"name":"Atirutt Singhaaumpol","avatar":""},{"name":"Vattcharachai Sunthornsiri","avatar":""},{"name":"Nut Pasuth Pongpasuth","avatar":""},{"name":"Wayne Falconer","avatar":""},{"name":"Dan Chupong","avatar":""},{"name":"Keng Cha","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9