INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kim-chieu-ngoc-tuy', 'Kim Chiêu Ngọc Túy', 'Gemini', 'https://phimimg.com/upload/vod/20250930-1/3b310972817f8753be690ce34385aed6.jpg', 'https://phimimg.com/upload/vod/20250930-1/db535ced334523dfcd00d8977e14f90f.jpg', '<p>Bộ phim kể về Tiêu Cẩm Ngọc, môn chủ của Tuần Thiên Môn, bị hãm hại thảm khốc nhưng bất ngờ trọng sinh trong thân xác của Lục Chiêu, vương phi yếu đuối và mù lòa của Sở Vương. Dựa vào trí tuệ và dũng khí của mình, nàng cùng người “đệ đệ song sinh trên danh nghĩa” là Tiêu Nhậm, từng bước trả thù cho cả Lục Chiêu và bản thân. Câu chuyện đan xen nhiều yếu tố như cấm kỵ giả mạo thân phận, thế thân, phản sát kịch liệt, mưu quyền tranh đấu, với dàn nhân vật đầy mưu kế và những màn phản chuyển liên tục, kịch tính cao.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chu Tuấn Vỹ","avatar":""},{"name":"Châu Lệ Lan","avatar":""},{"name":"Quyền Bồi Luân","avatar":""},{"name":"Tào Tái Á","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jin Zhao Yu Zui","金昭玉醉"]', 1784690324145);
