INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ham-muon', 'Ham Muốn', 'Kirot', 'https://phimimg.com/upload/vod/20251010-1/6c8535133c0b3e57dccd2e92bb6681b5.jpg', 'https://phimimg.com/upload/vod/20251010-1/82c22fc9f87cb3a1e83eeb71aa379ee8.jpg', '<p>Một người phụ nữ bảo thủ, đính hôn với người yêu thời trung học, được ghép tim cứu sống. Nhưng khi cô hồi phục, những đam mê và ham muốn bất ngờ bắt đầu trỗi dậy, kéo cô vào một thế giới đe dọa cuộc sống và danh tính mà cô từng mong muốn.</p>', 'Full', 1, 'single', 'completed', 20, 2025, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Jenn Rosa","avatar":""},{"name":"Ashley Lopez","avatar":""},{"name":"JC Tan","avatar":""},{"name":"Dio De Jesus","avatar":""},{"name":"Rinoa Halili","avatar":""},{"name":"Arjay Bautista","avatar":""},{"name":"Giovanni Baldisseri","avatar":""},{"name":"Malou Canzana","avatar":""},{"name":"Angel Durango","avatar":""},{"name":"Angelique Maglinao","avatar":""},{"name":"Janzeil Siachongco","avatar":""},{"name":"Lucky Jay De Guzman","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phim 18+","slug":"phim-18","id":"4b4457a1af8554c282dc8ac41fd7b4a1"}]', '["Kirot"]', 1784690324145);
