INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-di-2025', 'Đừng Đi', 'Stay', 'https://phimimg.com/upload/vod/20251010-1/d742d5d8bab795cfa8549b882417073a.jpg', 'https://phimimg.com/upload/vod/20251010-1/f1b86f05375f677d55d5cd9d8a6040d9.jpg', '<p>Kiara — một tiến sĩ chuyên nghiên cứu tâm linh châu Phi, và Miles — cựu võ sĩ MMA nay là huấn luyện viên, đang đứng bên bờ tan vỡ hôn nhân. Nhưng khi họ vô tình chạm trán với những thế lực siêu nhiên, cả hai phải chuyển từ việc chống lại nhau sang chiến đấu vì mạng sống.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Megalyn Echikunwoke","avatar":""},{"name":"Mo McRae","avatar":""},{"name":"Brandon Firla","avatar":""},{"name":"Dominic Stephens","avatar":""},{"name":"Patrick Cloud","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["门禁 Stay","Stay"]', 1784690324145);
