INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-an-ngo-tuong-vien', 'Huyền Án Ngõ Tương Viên', 'She''s Got No Name', 'https://phimimg.com/upload/vod/20251010-1/6f3ed13aa7e61ce2ee034a51cae47d48.jpg', 'https://phimimg.com/upload/vod/20251010-1/5d55c885a71f25da8ef813681a2535c0.jpg', '<p>Bộ phim được chuyển thể từ một trong bốn vụ án ly kỳ nhất thời Dân Quốc: Một người phụ nữ bị bắt vì giết chồng và phân xác. Liệu cô ta hành động một mình hay có người giúp đỡ? Bằng chứng sắt đá, làm sao để lật ngược tình thế? Hung thủ thật sự có phải là một người khác? Năm 1945, tại ngõ Tương Viên, Thượng Hải, một vụ án kinh hoàng xảy ra. Người phụ nữ gầy yếu Chiêm Chu Thị (Chương Tử Di đóng) ra tay sát hại chồng mình — Đại Khối Đầu và phân xác thành 16 mảnh! Trong phút chốc, lòng người xôn xao, dư luận dậy sóng. Bánh xe của thời đại chậm rãi lăn. Sự thật về vụ án từng lớp từng lớp dần dần được hé lộ. Số phận của mọi người bị cuốn vào vụ án ly kỳ này sẽ thay đổi, và số phận của Chiêm Chu Thị cũng sẽ đón nhận những biến chuyển bất ngờ…</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chương Tử Di","avatar":""},{"name":"Vương Truyền Quân","avatar":""},{"name":"Dịch Dương Thiên Tỉ","avatar":""},{"name":"Mạch Đình","avatar":""},{"name":"Triệu Lệ Dĩnh","avatar":""},{"name":"Lôi Gia Âm","avatar":""},{"name":"Dương Mịch","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["酱园弄杀夫案","酱园弄 (上)","She Has No Name","She''s Got No Name: Part One","酱园弄·悬案"]', 1784690324145);
