INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('huyen-an-ngo-tuong-vien', 'Huyền Án Ngõ Tương Viên', 'She''s Got No Name', 'huyền án ngõ tương viên she''s got no name chương tử di vương truyền quân dịch dương thiên tỉ mạch đình triệu lệ dĩnh lôi gia âm dương mịch 酱园弄杀夫案 酱园弄 (上) she has no name she''s got no name: part one 酱园弄·悬案', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-xuan-an-minh', 'Hoa Xuân Ẩn Mình', 'Spring Fever', 'https://phimimg.com/upload/vod/20250921-1/ae39e41d739139b9c3a1d61900c1085c.jpg', 'https://phimimg.com/upload/vod/20250921-1/ec19afb24cfd19b744bfb2c9fdaada6b.jpg', '<p>Bộ phim xoay quanh câu chuyện tình yêu và những toan tính quyền lực trong bối cảnh rối ren của thời loạn. Nữ chính Xuân Hoa vốn là tiểu thư khuê các, thông minh, kiên cường nhưng gặp nhiều biến cố khiến gia tộc suy bại. Trong hành trình tìm lại công bằng và bảo vệ những người mình yêu thương, nàng vô tình bị cuốn vào vòng xoáy tranh đoạt giữa triều đình và thế lực giang hồ. Bên cạnh nàng là những con người vừa là tri kỷ vừa là thử thách: một anh hùng trọng nghĩa khinh tài, một công tử ôn nhu nhưng giấu kín âm mưu, và những kẻ thù trong bóng tối luôn rình rập. Trải qua bao hiểm nguy, Xuân Hoa dần tìm ra chân tình và cũng mạnh mẽ đứng lên nắm giữ vận mệnh của chính mình.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Châu Lệ Nhạn","avatar":""},{"name":"Cảnh Nghiệp Đình","avatar":""},{"name":"Trần Minh Hào","avatar":""},{"name":"Tống Chiêu Dị","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["暗渡春华"]', 1784690324145);
