INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khe-uoc-song-sinh', 'Khế Ước Song Sinh', 'Twin Fates', 'https://phimimg.com/upload/vod/20250923-1/dc68224598a55eff013b25c5216251f8.jpg', 'https://phimimg.com/upload/vod/20250923-1/e1dba207a49a0d0df3cd52b94cacf8e3.jpg', '<p>Câu chuyện kể về Xích Vũ – thần thú Phượng Hoàng của tộc Xích Diễm, mang trong mình trái tim phong tỏa tình yêu. Trong một lần tình cờ, chàng gặp gỡ Mục Linh Tuyết – một thiếu nữ phàm trần có gia tộc bị kẻ gian hãm hại. Vào đêm trăng tròn, hai người lập nên khế ước song sinh giữa người và thần thú. Từ đó, họ cùng trải qua muôn vàn gian khổ, trưởng thành bên nhau, cuối cùng tiêu diệt kẻ gian nịnh, cứu vớt chúng sinh.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Akilyar","avatar":""},{"name":"A Lý Nha","avatar":""},{"name":"Ương Bối Hạ","avatar":""},{"name":"Lý Vịnh Hào","avatar":""},{"name":"Đặng Vận Sơ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shuang Sheng Qi","双生契"]', 1784690324145);
