INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-so-phan-1', 'Chuyển Số (Phần 1)', 'Shifting Gears (Season 1)', 'https://phimimg.com/upload/vod/20251010-1/c5cf827bbfa53eaf8100e0c8c9659213.jpg', 'https://phimimg.com/upload/vod/20251010-1/577db96b03a6dd7b66720962cd3b7524.jpg', '<p>Matt là một gã cứng đầu, bảo thủ, chủ một xưởng bảo dưỡng phục chế xe cổ. Khi cô con gái lạnh nhạt lâu ngày cùng mấy đứa con tuổi ẩm ương của cô ấy chuyển đến ở cùng ông ấy, một cuộc phục chế tình thân gia đình thực sự đã bắt đầu.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tim Allen","avatar":""},{"name":"Kat Dennings","avatar":""},{"name":"Seann William Scott","avatar":""},{"name":"Daryl Mitchell","avatar":""},{"name":"Maxwell Simkins","avatar":""},{"name":"Barrett Margolis","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shifting Gears"]', 1784690324145);
