INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuon-bang-halloween', 'Cuốn Băng Halloween', 'V/H/S/HALLOWEEN', 'https://phimimg.com/upload/vod/20251006-1/2094474bdea85885d3a8892706294256.jpg', 'https://phimimg.com/upload/vod/20251006-1/d34923bf2b0771989891af53c96f7ec6.jpg', '<p>Một bộ sưu tập V/H/S mang chủ đề Halloween vô tình được mở ra, giải phóng hàng loạt câu chuyện rùng rợn nhuốm máu. Khi tiếng cười “trick-or-treat” vang lên trong đêm, những trò đùa hóa thành cơn ác mộng thật sự — nơi mỗi khung hình là một cánh cửa dẫn đến địa ngục, và việc sống sót đến bình minh trở thành trò cá cược cuối cùng.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lawson Greyson","avatar":""},{"name":"Sarah Nicklin","avatar":""},{"name":"Jenna Hogan","avatar":""},{"name":"Isabella Feliciana","avatar":""},{"name":"Sean Berube","avatar":""},{"name":"Riley Nottingham","avatar":""},{"name":"Lily Speiser","avatar":""},{"name":"Samantha Cochran","avatar":""},{"name":"Stephen Gurewitz","avatar":""},{"name":"Juliana Danielle Ferreira","avatar":""},{"name":"Bianca Thomson","avatar":""},{"name":"Layton Khan","avatar":""},{"name":"Natalia Montgomery Fernandez","avatar":""},{"name":"Jake Ellsworth","avatar":""},{"name":"Carl Gar","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["V/H/S/8","V/H/S/HA//OWEEN","Diet Phantasma","Coochie Coochie Coo","Ut Supra Sic Infra","Fun Size","Kidprint","Home Haunt","VHS Halloween","V/H/S/Halloween"]', 1784690324145);
