INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('f1-phim-dien-anh', 'F1 Phim Điện Ảnh', 'F1 The Movie', 'https://phimimg.com/upload/vod/20250821-1/0ae9dea7a7ac10f01ae438a7de4ab857.jpg', 'https://phimimg.com/upload/vod/20250821-1/0f6921e399320d2f405c0e56efa42af5.jpg', '<p>Phim kể về Sonny Hayes (do Brad Pitt thủ vai), một cựu tay đua F1 lão làng, người đã rời xa đường đua sau một tai nạn kinh hoàng. Anh được thuyết phục quay trở lại thế giới tốc độ để cố vấn cho một tay đua trẻ tuổi, đầy triển vọng nhưng cũng rất liều lĩnh. Cùng nhau, họ phải đối mặt với những thách thức khốc liệt của giải đấu F1, cạnh tranh với những tay đua hàng đầu thế giới và khám phá lại niềm đam mê, đồng thời tìm cách vượt qua những giới hạn của bản thân. Phim hứa hẹn sẽ mang đến những cảnh quay chân thực và những pha đua xe mãn nhãn, được quay ngay trên các đường đua F1 thật sự.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Brad Pitt","avatar":""},{"name":"Damson Idris","avatar":""},{"name":"Javier Bardem","avatar":""},{"name":"Kerry Condon","avatar":""},{"name":"Tobias Menzies","avatar":""},{"name":"Kim Bodnia","avatar":""},{"name":"Sarah Niles","avatar":""},{"name":"Will Merrick","avatar":""},{"name":"Joseph Balderrama","avatar":""},{"name":"Abdul Salis","avatar":""},{"name":"Callie Cooke","avatar":""},{"name":"Samson Kayo","avatar":""},{"name":"Simon Kunz","avatar":""},{"name":"Liz Kingsman","avatar":""},{"name":"Simone Ashley","avatar":""},{"name":"Ramona Von Pusch","avatar":""},{"name":"Barney Smith","avatar":""},{"name":"Poppy Smith","avatar":""},{"name":"L","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c4