INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoi-hon-ke', 'Hồi Hồn Kế', 'The Resurrected', 'hồi hồn kế the resurrected thư kỳ lý tâm khiết phó mạnh bách giả tịnh văn sukollawat kanaros chung hân lăng phương úc đình lâm đình ức lưu chủ bình trần hân uy trịnh nhân thạc patrick nattawat finkler 회혼계 hui hun ji the resurrected 回魂計', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-vong-o-phia-chan-troi', 'Cầu Vồng Ở Phía Chân Trời', 'The Rainbow At The Horizon', 'https://phimimg.com/upload/vod/20250914-1/a959cdb80ed4f9093018b3bc61d37921.jpg', 'https://phimimg.com/upload/vod/20250914-1/dc4b252b5cb3b0b3de6af4df9c2e4b36.jpg', '<p>“Cầu vồng ở phía chân trời” là câu chuyện xoay quanh hai gia đình đơn thân sống cạnh nhau trong cùng một khu chung cư. Cuộc sống vốn đã chật vật của họ thêm đảo lộn khi bà giúp việc lâu năm của gia đình xin nghỉ, người giúp việc mới làm bùng nổ những tình huống bất ngờ, hài hước và cảm động. Phim là câu chuyện tình yêu muộn màng nhưng sâu sắc, nơi những người tưởng đã không còn cần yêu lại một lần nữa dám tin, dám mở lòng.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"NSƯT Thanh Bình","avatar":""},{"name":"NSƯT Linh Huệ","avatar":""},{"name":"Tú Oanh","avatar":""},{"name":"Khánh Linh","avatar":""},{"name":"Trọng Lân","avatar":""},{"name":"Anh Đào","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324145);
