INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cau-vong-o-phia-chan-troi', 'Cầu Vồng Ở Phía Chân Trời', 'The Rainbow At The Horizon', 'cầu vồng ở phía chân trời the rainbow at the horizon nsưt thanh bình nsưt linh huệ tú oanh khánh linh trọng lân anh đào ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phan-phuong-hi-su', 'Phân Phương Hỉ Sự', 'Hilarious Family 2', 'https://phimimg.com/upload/vod/20250922-1/151e59b6fba3bbc0d0816990f907c5fe.jpg', 'https://phimimg.com/upload/vod/20250922-1/cf8cdaf398fb9283a99d692d085b78d9.jpg', '<p>Ngải Tứ Hỷ, cô chủ quán trọ là người kiên quyết theo đuổi &quot;chủ nghĩa độc thân&quot;, nhưng vì một vụ kiện trời ơi đất hỡi, nàng bất ngờ trở thành &quot;trường hợp điểm&quot; của quan phủ trong chiến dịch dẹp bỏ chủ nghĩa này. Là người từng chịu ơn Tứ Hỷ, Kinh Khảm buộc phải cưới nàng để giúp nàng thoát khỏi rắc rối. Tưởng rằng sau khi thành thân, hai người có thể &quot;đường ai nấy đi&quot; êm đẹp, nhưng ai ngờ cặp phu thê bất đắc dĩ này lại bị cuốn vào cuộc đấu đá giành quyền lực trong nhà họ Kinh, một gia tộc chuyên làm trà cống cho triều đình. Nhà họ Kinh mỗi người một vẻ: Lão tổ mẫu Ngụy Quân Nhất thoạt nhìn trông chẳng để ý sự đời, bên trong lại âm thầm hiểu hết mọi chuyện. Đích mẫu của Kinh Khảm, La Chu Tứ đam mê quyền lực, âm hiểm, độc ác, vô tình. Đại tỷ Kinh Trân Châu kiêu kỳ, đỏng đảnh, tự cho mình là nhất. Tỳ nữ Lã Kiều Nga ham hư vinh, miệng ngọt chết ruồi, vô cùng giả tạo. Đệ đệ La A Cát, gã công tử bột ngạo mạn, coi trời bằng vung.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lạt Mục Dương Tử","avatar":""},{"name":"Hà Trại Phi","avatar":""},{"name":"Nhậm Hào","avatar":""},{"name":"Xướng Long","avatar":""},{"name":"Tào Thúy Vân","avatar":""},{"name":"Phạm Soái Kỳ","avatar":""},{"name":"Chùy Na Lệ Sa","avatar":""},{"name":"Trương Nhã Manh","avatar":""},{"name":"Vương Sơn Thủy","avatar":""},{"name":"Vương Hâm Đình","avatar":""},{"name":"Lý Điện Tôn","avatar":""},{"name":"Lý Hải Ngân","avatar":""},{"name":"Lưu Lâm","avatar":""},{"name":"Lý Giai Hàng","avatar":""},{"name":"Ngô Giai Di","avatar":""},{"name":"Lưu Khôn","avatar":""},{"name":"Lưu Tiểu Bắc","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Fen Fang Xi Shi","芬芳喜事"]', 1784690324145);
