INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-khong-gian-trai-dat', 'Quái Vật Không Gian: Trái Đất', 'Alien: Earth', 'https://phimimg.com/upload/vod/20250814-1/25f55d99db29cc484890b696bf506d01.jpg', 'https://phimimg.com/upload/vod/20250814-1/4b400fb1136638894c6849aa45a9d889.jpg', '<p>Alien: Earth (2025) là phần tiền truyện Alien, lấy bối cảnh Trái Đất năm 2120 – nơi các tập đoàn lớn kiểm soát mọi thứ. Sau khi tàu vũ trụ rơi, một hybrid trẻ tên Wendy cùng nhóm đồng minh phải đối đầu loài Xenomorph ngoài hành tinh. Phim pha trộn kinh dị sinh học, chính trị công nghệ và triết lý về ý thức.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 9, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sydney Chandler","avatar":""},{"name":"Alex Lawther","avatar":""},{"name":"Essie Davis","avatar":""},{"name":"Samuel Blenkin","avatar":""},{"name":"Babou Ceesay","avatar":""},{"name":"Adarsh Gourav","avatar":""},{"name":"Erana James","avatar":""},{"name":"Lily Newmark","avatar":""},{"name":"Jonathan Ajayi","avatar":""},{"name":"David Rysdahl","avatar":""},{"name":"Diêm Camille","avatar":""},{"name":"Moe Bar-El","avatar":""},{"name":"Adrian Edmondson","avatar":""},{"name":"Timothy Olyphant","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Alien: Earth","Alien : planète Terre","에일리언: 어스1","الفضائي: الأرض","Yaratık: Dünya"]', 1784690324145);
