INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('quai-vat-khong-gian-trai-dat', 'Quái Vật Không Gian: Trái Đất', 'Alien: Earth', 'quái vật không gian: trái đất alien: earth sydney chandler alex lawther essie davis samuel blenkin babou ceesay adarsh gourav erana james lily newmark jonathan ajayi david rysdahl diêm camille moe bar-el adrian edmondson timothy olyphant alien: earth alien : planète terre 에일리언: 어스1 الفضائي: الأرض yaratık: dünya', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muoi-hai-con-giap', 'Mười Hai Con Giáp', 'Twelve', 'https://phimimg.com/upload/vod/20250824-1/f8856156968db912c1b011edc2c975ba.jpg', 'https://phimimg.com/upload/vod/20250824-1/ea3decaa64872d14f5e165bcd139beca.jpg', '<p>Lấy cảm hứng từ truyền thuyết 12 con giáp phương Đông, “Twelve” kể về 12 thiên thần – mỗi người tượng trưng cho một con giáp – sống dưới lốt người giữa thế giới loài người, với sứ mệnh bảo vệ bán đảo Triều Tiên khỏi ác linh cổ xưa. Từ hàng ngàn năm trước, những thiên thần này đã hy sinh để phong ấn tà khí trong Cánh Cổng Địa Ngục. Nhưng khi ác linh bắt đầu tỉnh giấc, hỗn loạn quay trở lại – và các thiên thần buộc phải tái hợp để chiến đấu một lần nữa.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 10, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Don Lee","avatar":""},{"name":"Park Hyung-sik","avatar":""},{"name":"Seo In-guk","avatar":""},{"name":"Lee Ju-bin","avatar":""},{"name":"Ko Kyu-phil","avatar":""},{"name":"Kang Mi-na","avatar":""},{"name":"Sung Yu-been","avatar":""},{"name":"Ahn Ji-hye","avatar":""},{"name":"Regina Lei","avatar":""},{"name":"Sung Dong-il","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["十二使者","12","Двенадцать","Дюжина","اثنا عشر","Twe12ve","트웰브"]', 1784690324146);
