INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tua-nhu-tinh-dau-them-mot-lan-yeu', 'Tựa Như Tình Đầu (Thêm Một Lần Yêu)', 'Love, Take Two', 'https://phimimg.com/upload/vod/20250806-1/a0c0ae28a5d528d7eaf806769950d12b.jpg', 'https://phimimg.com/upload/vod/20250806-1/aecadc284bf0abe59b752cac66913846.jpg', '<p>Lee Ji An - một bà mẹ đơn thân mạnh mẽ, cùng Lee Hyo Ri - con gái đang học ngành y, cùng chuyển về vùng quê để bắt đầu cuộc sống mới. Tại đây, họ vô tình gặp lại mối tình đầu của Ji An – Ryu Jeong Seok, một ông bố đơn thân sống cùng con trai Ryu Bo Hyun, người điều hành một trang trại hoa. Những va chạm đời thường, sự thay đổi trong mối quan hệ mẹ con, và cảm xúc mới chớm nở giữa thế hệ trẻ mở ra một hành trình nhẹ nhàng nhưng sâu sắc về tình thân, tình yêu và sự trưởng thành.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 9, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yum Jung-ah","avatar":""},{"name":"Park Hae-joon","avatar":""},{"name":"Choi Yoon-ji","avatar":""},{"name":"Kim Min-kyu","avatar":""},{"name":"Kim Sun-young","avatar":""},{"name":"Yang Kyung-won","avatar":""},{"name":"Kim Mi-kyeong","avatar":""},{"name":"Kang Ae-sim","avatar":""},{"name":"Jung Young-ju","avatar":""},{"name":"Park Soo-young","avatar":""},{"name":"Seo Young-hee","avatar":""},{"name":"Yang Hyun-min","avatar":""},{"name":"Jung Hoe-ryn","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["الحب، محاولة ثانية","初次，為了愛","첫, 사랑을 위하여"]', 1784690324146);
