INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-vo-cung-cuc-hai', 'Sát Thủ Vô Cùng Cực Hài', 'Hitman 2', 'https://phimimg.com/upload/vod/20250318-1/595fdbe77533d28ac2de81dccb606339.jpg', 'https://phimimg.com/upload/vod/20250302-1/15c292b047c774caf49bf14936621a84.jpg', '<p>Phim xoay quanh Jun (Kwon Sang Woo), cựu điệp viên hiện đang là hoạ sĩ truyện tranh - trở thành mục tiêu kép của cả Cơ quan Tình báo Quốc gia (NIS) và bọn khủng bố trên toàn cầu sau khi đăng tải webtoon (truyện tranh mạng) lấy cảm hứng từ chính quá khứ điệp viên của mình. Sở dĩ, hành động này của Jun không chỉ làm lộ bí mật quốc gia mà còn khiến bọn khủng bố tìm cách “trả thù”.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Hàn Quốc', 1, '[{"name":"Kwon Sang-woo","avatar":""},{"name":"Jeong Jun-ho","avatar":""},{"name":"Lee Yi-kyung","avatar":""},{"name":"Hwang Woo-seul-hye","avatar":""},{"name":"Lee Ji-won","avatar":""},{"name":"Kim Seung-o","avatar":""},{"name":"Lee Soon-won","avatar":""},{"name":"Lee Jun-hyeok","avatar":""},{"name":"Han Ji-eun","avatar":""},{"name":"Park Kwang-jae","avatar":""},{"name":"Choi Dong-goo","avatar":""},{"name":"Ryu Yeon-seok","avatar":""},{"name":"Choi Ji-woo","avatar":""},{"name":"Jo Soo-bin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["히트맨2","هیتمن  2","Hitman 2","히트맨 2"]', 1784690324146);
