INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-lai-khinh-khi-cau', 'Người Lái Khinh Khí Cầu', 'The Balloonist', 'https://phimimg.com/upload/vod/20251008-1/0daef820b7292d1e782ab8c59a4875b9.jpg', 'https://phimimg.com/upload/vod/20251008-1/f5ee25ca889fca16f2f1478d94a0b8eb.jpg', '<p>Gaby – người phụ nữ sống yên bình với trang trại gà giống cổ truyền – bỗng thấy cuộc đời mình đảo lộn khi một phi công khinh khí cầu ngạo mạn rơi thẳng xuống chuồng gà của cô. Tai nạn kỳ quái ấy bất ngờ khơi lại những rạn nứt trong gia đình, buộc Gaby phải đối mặt không chỉ với kẻ “xâm lấn bầu trời” kia, mà còn với chính quá khứ mà cô đã cố chôn giấu bấy lâu. Một câu chuyện hài hước nhưng ấm áp về sự va chạm, hàn gắn và hành trình tìm lại chính mình giữa những cánh đồng và… tiếng gà trưa.</p>', 'Full', 1, 'single', 'completed', 32, 2025, 'Vietsub', 'FHD', 'Hà Lan', 0, '[{"name":"Sallie Harmsen","avatar":""},{"name":"Pieter Embrechts","avatar":""},{"name":"Beau Minnaert","avatar":""},{"name":"Frieda Pittoors","avatar":""},{"name":"Nazanin Taheri","avatar":""},{"name":"Thomas Höppener","avatar":""},{"name":"René Groothof","avatar":""},{"name":"Leòn Ali Çifteci","avatar":""},{"name":"Jack Wouterse","avatar":""},{"name":"Esther Scheldwacht","avatar":""},{"name":"Conny Wilhelmus","avatar":""},{"name":"Felix-Jan Kuypers","avatar":""},{"name":"Josse Colsoul","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Balloonist","De Ballonvaarder"]', 1784690324146);
