INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-cot-tham-thi', 'Hài Cốt Thầm Thì', 'Queen Of Bones', 'https://phimimg.com/upload/vod/20251008-1/69b3b0ae4fbeeee1e8b043b7a4f497fb.jpg', 'https://phimimg.com/upload/vod/20251008-1/5ba8eb6ddfcb2ac5d10e515bfdda151c.jpg', '<p>Cặp song sinh chuyển đến sống cùng người cha trên một trang trại hẻo lánh ở Oregon năm 1931. Giữa vùng đất mù sương và cô tịch, họ bắt đầu lần tìm sự thật về cái chết bí ẩn của người mẹ — và mối liên hệ rùng rợn của bà với thế giới siêu nhiên. Càng tiến sâu vào bí mật gia đình, ranh giới giữa thực và ảo, giữa người sống và kẻ chết, dần trở nên mong manh đáng sợ.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Julia Butters","avatar":""},{"name":"Jacob Tremblay","avatar":""},{"name":"Martin Freeman","avatar":""},{"name":"Taylor Schilling","avatar":""},{"name":"Christopher Heyerdahl","avatar":""},{"name":"Kyle Breitkopf","avatar":""},{"name":"Clare Coulter","avatar":""},{"name":"Adam Moryto","avatar":""},{"name":"Will Coombs","avatar":""},{"name":"Gavin Rodger","avatar":""},{"name":"Martin Julien","avatar":""},{"name":"Patricia Phillips","avatar":""},{"name":"Vincent Volpe","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Queen of Bones"]', 1784690324146);
