INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-den-con-lam-long', 'Đã Đen Còn Lắm Lông', 'Ain''t This A B', 'https://phimimg.com/upload/vod/20251008-1/7df42e763965ea681921d2842dc5001a.jpg', 'https://phimimg.com/upload/vod/20251008-1/6598a2344bd6dc36d4967a357fc35fe8.jpg', '<p>Một gã hề làm thuê chật vật mưu sinh bỗng rơi vào tình thế vượt quá tầm kiểm soát, khi mánh lới nhỏ nhằm lừa tiền khách hàng bất ngờ leo thang thành cuộc đối đầu chết người với bọn tội phạm máu lạnh. Giữa những màn kịch, lớp hóa trang và những nụ cười giả tạo, hắn buộc phải dùng mưu mẹo để sống sót – biến trò hề thành cuộc chiến sinh tồn thực sự.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Giovanni Watson","avatar":""},{"name":"Juliah Cheree Taylor","avatar":""},{"name":"Brian Britt","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ain''t This a B"]', 1784690324146);
