INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tien-len-chien-doi-that-sung-sentai-daishikkaku-phan-2', 'Tiến Lên! Chiến Đội Thất Sủng! (Sentai Daishikkaku) (Phần 2)', 'Go! Go! Loser Ranger! (Season 2)', 'tiến lên! chiến đội thất sủng! (sentai daishikkaku) (phần 2) go! go! loser ranger! (season 2) daishi kajita ranger reject 战队大失格 戰隊大失格 no longer rangers ריינג’ר לוזר go! go! go! go! לוזר רינג''ר! גו גו ריינג''ר לוזר squalificati - ranger reject sentai daishikkaku sentai dai shikkaku 전대대실격 ขบวนการกำมะลอ go! go! loser ranger! (2025) go! go! loser ranger! season 2 戦隊大失格', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-vo-thuong-luu', 'Người Vợ Thượng Lưu', 'The New City Wives', 'https://phimimg.com/upload/vod/20251008-1/b6b985bd6d03bca0f92e0daa6f1be239.jpg', 'https://phimimg.com/upload/vod/20251008-1/30ab55985371a85e91df513e4bfaacd3.jpg', '<p>Một cô dâu mới chuyển đến thành phố cùng chồng, nhưng nhanh chóng nhận ra mình bị mắc kẹt trong một xã hội đầy phân cấp, nơi địa vị quyết định vị trí của mỗi người. Khi cố gắng hòa nhập, cô trở thành mục tiêu của một người phụ nữ quyền lực đứng đầu nấc thang xã hội. Trong cơn tuyệt vọng, cô tìm đến cầu xin sự giúp đỡ từ chính người đó — nhưng lại bị ép buộc trở thành kẻ hầu hạ, phải dọn dẹp hậu quả cho những mối quan hệ vụng trộm của bà ta.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 18, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phim Ngắn","slug":"phim-ngan","id":"4f02d28224c0747511790d57fbb63a62"}]', '[]', 1784690324146);
