INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dot-kich-dai-truyen-hinh', 'Đột Kích Đài Truyền Hình', 'Hoso Kyoku Senkyo', 'https://phimimg.com/upload/vod/20251008-1/7218a4922bce4e1ef6d35797e142b544.jpg', 'https://phimimg.com/upload/vod/20251008-1/33b7c33e5004e57feb74f5cd490e0fc6.jpg', '<p>Saburo Musashi, một điều tra viên kỳ cựu của BCCT, được giao nhiệm vụ mới đầy nguy hiểm: cùng đồng đội đối đầu với một nhóm vũ trang đeo mặt nạ vừa đánh chiếm một đài truyền hình và bắt giữ 500 con tin. Cuộc chiến cân não bắt đầu, nơi mỗi phút trôi qua đều có thể là sinh tử — không chỉ với con tin, mà cả với những bí mật bị chôn giấu trong bóng tối.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Sho Sakurai","avatar":""},{"name":"Manami Higa","avatar":""},{"name":"Sonim","avatar":""},{"name":"Kumi Takiuchi","avatar":""},{"name":"Fuma Kikuchi","avatar":""},{"name":"Gunpee","avatar":""},{"name":"Katsunori Takahashi","avatar":""},{"name":"Seishirou Katou","avatar":""},{"name":"Ryosuke Sota","avatar":""},{"name":"Mebuki Yoshida","avatar":""},{"name":"Shigeyuki Totsugi","avatar":""},{"name":"Akira Fukuzawa","avatar":""},{"name":"Reiko Kataoka","avatar":""},{"name":"Nagisa Saito","avatar":""},{"name":"Daichi Yamaguchi","avatar":""},{"name":"Shōji Mayama","avatar":""},{"name":"Yoshiaki Kameda","avatar":""},{"name":"Taka","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hosokyoku Senkyo","The Broadcasting Station Occupation","Hoso Kyoku Senkyo",