INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toan-tri-doc-gia', 'Toàn Trí Độc Giả', 'Omniscient Reader: The Prophecy', 'https://phimimg.com/upload/vod/20251003-1/fe75cf7576a605ddfcf78bdcfbf002db.jpg', 'https://phimimg.com/upload/vod/20251003-1/0d8be5cfefb5ef6690e36d3ea7ce4730.jpg', '<p>Khi thế giới diệt vong trong cuốn tiểu thuyết yêu thích bỗng biến thành hiện thực, Kim Dokja (Ahn Hyo-seop) - 1 nhân viên văn phòng bình thường cũng là người duy nhất biết được kết truyện phải bắt tay vào cuộc hành trình đến phân cảnh cuối cùng. Cùng những đồng đội ngẫu nhiên và người hùng Yu Jeong-hyeok (Lee Min-ho) tập hợp thành 1 nhóm, Kim Dokja cần vượt qua mọi thử thách để sống sót trong thế giới bộ truyện mà anh yêu thích.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 1, '[{"name":"Ahn Hyo-seop","avatar":""},{"name":"Lee Min-ho","avatar":""},{"name":"Chae Soo-bin","avatar":""},{"name":"Shin Seung-ho","avatar":""},{"name":"Nana","avatar":""},{"name":"JISOO","avatar":""},{"name":"Park Ho-san","avatar":""},{"name":"Choi Young-jun","avatar":""},{"name":"Jung Sung-il","avatar":""},{"name":"Cho Hyun-jung","avatar":""},{"name":"Kwon Eun-seong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Omniscient Reader''s Viewpoint","全知的な読者の視点から","Zenchiteki na Dokusha no Shiten kara","전지적 독자 시점","Jeonjijeok Dokja Sijeom","Omniscient Reader","Всезнаещият гадател: Пророчеството","อ่านชะตาวันสิ้นโลก","全知讀者視角：滅世預言","Omniscient Reader: The Prophecy","Omniscient Reader The Prophecy","Omniscient, Reader The Prophecy","Omniscient - Reader The Prophecy","全知读者视角：灭世预言","La Profecía: Lector Omnisciente"]', 1784690324146);
