INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('toan-tri-doc-gia', 'Toàn Trí Độc Giả', 'Omniscient Reader: The Prophecy', 'toàn trí độc giả omniscient reader: the prophecy ahn hyo-seop lee min-ho chae soo-bin shin seung-ho nana jisoo park ho-san choi young-jun jung sung-il cho hyun-jung kwon eun-seong omniscient reader''s viewpoint 全知的な読者の視点から zenchiteki na dokusha no shiten kara 전지적 독자 시점 jeonjijeok dokja sijeom omniscient reader всезнаещият гадател: пророчеството อ่านชะตาวันสิ้นโลก 全知讀者視角：滅世預言 omniscient reader: the prophecy omniscient reader the prophecy omniscient, reader the prophecy omniscient - reader the prophecy 全知读者视角：灭世预言 la profecía: lector omnisciente', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-2025', 'Quái Vật', 'Zombie Warfare', 'https://phimimg.com/upload/vod/20250927-1/732f442796cbbff82d602ff717ee1f08.jpg', 'https://phimimg.com/upload/vod/20250927-1/da93e57028855e98376954680f103ae5.jpg', '<p>Pháp sư Đông Thanh hạ sơn, quyết tâm giải cứu Huyên Thành đang chìm trong hỗn loạn bởi lũ xác sống ghê rợn. Khi diện kiến thành chủ Nam Phong uy nghiêm, chính trực cùng đại thiếu gia Nam Chính Từ ôn hòa, lễ độ, Đông Thanh lại cảm thấy có điểm gì đó bất thường. Tai họa này rốt cuộc là thiên tai trời giáng, hay là nhân họa do con người tạo nên? Đông Thanh quyết tâm vạch trần sự thật, phá tan màn sương nghi hoặc!</p>', 'Tập 20', 20, 'series', 'ongoing', 12, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Trí Dương","avatar":""},{"name":"Ôn Mạt Ngôn","avatar":""},{"name":"Lý Giai Văn","avatar":""},{"name":"Trương Nhã Mộng","avatar":""},{"name":"Diệp Khai","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Guai Wu","Zombie Warfare","怪物"]', 1784690324146);
