INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoai-le-cua-em', 'Ngoại Lệ của Em', 'My Special One', 'https://phimimg.com/upload/vod/20251007-1/8b3a824f5816fa9e64a7f8e7ce817391.jpg', 'https://phimimg.com/upload/vod/20251007-1/907251a10a85d3c20169df1c8974d70b.jpg', '<p>Sahoko – một nữ sinh bình thường chẳng có gì nổi bật – luôn căm ghét những chàng trai bảnh bao và đã thề sẽ không bao giờ yêu nữa, sau khi mang trong mình vết thương lòng sâu sắc. Nhưng mọi thứ thay đổi khi cô gặp Kouta – một ngôi sao thần tượng rực rỡ ánh hào quang. Khi dần hiểu được niềm đam mê chân thành của anh dành cho âm nhạc và người hâm mộ, cũng như sự ấm áp phía sau vẻ ngoài hoàn hảo ấy, Sahoko nhận ra anh khác hẳn với những kẻ từng khiến cô tổn thương. Dù cố kìm lòng, cô vẫn không thể ngăn trái tim mình rung động. Thế nhưng, Sahoko sớm phát hiện Kouta cũng mang một quá khứ đau buồn – và anh đã tự hứa sẽ không bao giờ để bản thân rơi vào một mối ràng buộc đặc biệt nào nữa. Hai con người từng sợ hãi tình yêu, liệu có thể mở lòng để tìm lại niềm tin nơi nhau?</p>', 'Full', 1, 'single', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Mei Hata","avatar":""},{"name":"Kazuya Ohashi","avatar":""},{"name":"Keito Kimura","avatar":""},{"name":"Jyutaro Yamanaka","avatar":""},{"name":"Okubo Nalu","avatar":""},{"name":"Kida Naoya","avatar":""},{"name":"Yuna Hoshino","avatar":""},{"name":"Kenichi Endo","avatar":""},{"name":"Taiki Sato","avatar":""},{"name":"Nako Yabuki","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Kimi ga Tokubetsu","My Special One","Mi persona especial","君がトクベツ"]', 1784690324146);
