INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngoai-le-cua-em', 'Ngoại Lệ của Em', 'My Special One', 'ngoại lệ của em my special one mei hata kazuya ohashi keito kimura jyutaro yamanaka okubo nalu kida naoya yuna hoshino kenichi endo taiki sato nako yabuki kimi ga tokubetsu my special one mi persona especial 君がトクベツ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-con-song-sinh-nua-bong-co-lieu', 'Không Còn Song Sinh (Nửa Bóng Cô Liêu)', 'Twinless', 'https://phimimg.com/upload/vod/20251007-1/1685e6e9940ee3b82931432747ea9aa9.jpg', 'https://phimimg.com/upload/vod/20251007-1/1fbf63d1e686a61330643e5de2ef979e.jpg', '<p>Roman trở về quê nhà để dự tang lễ của người anh em song sinh, Rocky. Rocky là người hướng ngoại, thông minh, đồng tính, và được mọi người yêu quý — hoàn toàn trái ngược với Roman. Khi không còn một nửa của mình, Roman tìm thấy sự an ủi tại một nhóm hỗ trợ những người mất anh/chị em song sinh. Tại đây, anh nhanh chóng kết nối với Dennis — người mang hình bóng của Rocky. Giữa họ nảy sinh một tình bạn sâu sắc, nhưng thứ cảm xúc ấy lại mang màu sắc… gần như quá thân thuộc.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dylan O''Brien","avatar":""},{"name":"James Sweeney","avatar":""},{"name":"Lauren Graham","avatar":""},{"name":"Aisling Franciosi","avatar":""},{"name":"Arkira Chantaratananond","avatar":""},{"name":"Tasha Smith","avatar":""},{"name":"François Arnaud","avatar":""},{"name":"Chris Perfetti","avatar":""},{"name":"Cree Cicchino","avatar":""},{"name":"Crystal Anne Muñoz","avatar":""},{"name":"Kody Harvard","avatar":""},{"name":"Katie Findlay","avatar":""},{"name":"Susan Park","avatar":""},{"name":"Pauline Dorsey","avatar":""},{"name":"Jack Clevenger","avatar":""},{"name":"Jannett","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Um Gêmeo a Menos","Rozdzieleni","Twinless"]', 1784690324146);
