INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-ma-ma-ma-ca-rong-ban-dien-anh', 'Ma Ma Ma Ma Cà Rồng: Bản Điện Ảnh', 'Baban Baban Ban Vampire', 'https://phimimg.com/upload/vod/20251007-1/8e71ad54dae5138fd10229076ab9d554.jpg', 'https://phimimg.com/upload/vod/20251007-1/9bf41cdf7736630bf6a396f0d28c2f38.jpg', '<p>Ranmaru – một ma cà rồng đã sống hơn 450 năm – hiện làm việc trong một nhà tắm công cộng. Là sinh vật kén chọn đến mức cực đoan, mục tiêu duy nhất của anh là được nếm dòng máu thuần khiết của một thiếu niên 18 tuổi còn trinh. Từ ngày được cứu sống bởi chủ nhà tắm, Ranmaru đã để mắt đến con trai của ông – cậu bé 15 tuổi Rihito. Để đạt được “bữa tiệc” hoàn hảo ấy, Ranmaru phải đảm bảo Rihito vẫn giữ nguyên sự trong trắng cho đến sinh nhật thứ 18. Nhưng khi Rihito bắt đầu rung động trước một bạn cùng lớp, cuộc chiến tuyệt vọng và hài hước của Ranmaru nhằm “bảo vệ” cậu khỏi tình yêu đầu đời chính thức bắt đầu.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ryo Yoshizawa","avatar":""},{"name":"Rihito Itagaki","avatar":""},{"name":"Nanoka Hara","avatar":""},{"name":"Gordon Maeda","avatar":""},{"name":"Shinnosuke Mitsushima","avatar":""},{"name":"Mandy Sekiguchi","avatar":""},{"name":"Shinichi Tsutsumi","avatar":""},{"name":"Takuma Otoo","avatar":""},{"name":"Kurara Emi","avatar":""},{"name":"Takashi Sasano","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Baban Baban Ban Vampire","Babanba Banban Vampire","ババンババンバンバンパイア"]', 1784690324146);
