INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-chua-noi', 'Lời Chưa Nói', 'Family Secret', 'https://phimimg.com/upload/vod/20251007-1/77a31d14404b71b29777df29cfa0f41b.jpg', 'https://phimimg.com/upload/vod/20251007-1/86cda45b53401392773248b788ea503c.jpg', '<p>Gia đình của Yeon Jung dần tan vỡ sau cú sốc mất đi người con trai cả. Khi mỗi thành viên đều giấu diếm mục đích sống thật sự của mình, những lời nói dối bắt đầu khiến họ rạn nứt. Sau những phản bội và thất vọng bị phơi bày, họ dần tìm lại tình yêu thương dành cho nhau khi cùng nhau nỗ lực hoàn thành lời hứa với người con trai quá cố.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Pub-lae","avatar":""},{"name":"Kim Hye-eun","avatar":""},{"name":"Kim Bo-yoon","avatar":""},{"name":"Choi Hong-il","avatar":""},{"name":"Kim Hyun-jae","avatar":""},{"name":"Kim I-on","avatar":""},{"name":"Yoon Ki-won","avatar":""},{"name":"Kim Hyeong-mook","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["가족의 비밀"]', 1784690324146);
