INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giong-to-2025', 'Giông Tố', 'Tempest', 'https://phimimg.com/upload/vod/20250911-1/f9f35296b642427f98ca00ec5cc0b4d5.jpg', 'https://phimimg.com/upload/vod/20250911-1/8d16cd2e8916a8c8985d48e275860550.jpg', '<p>Moon Ju, một nhà ngoại giao từng là đại sứ tại Hoa Kỳ, và San Ho, một đặc vụ bí ẩn với quá khứ không rõ ràng. Baek San Ho từng là lính đánh thuê và mọi điều liên quan đến quá khứ của anh ta đều bị che giấu. Cả hai cùng nhau truy tìm sự thật về một vụ án cực lớn.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jun Ji-hyun","avatar":""},{"name":"Gang Dong-won","avatar":""},{"name":"John Cho","avatar":""},{"name":"Lee Mi-sook","avatar":""},{"name":"Park Hae-joon","avatar":""},{"name":"Christopher Gorham","avatar":""},{"name":"Michael Gaston","avatar":""},{"name":"Spencer Garrett","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["暴风圈","Tempest","Polaris","북극성"]', 1784690324146);
