INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sat-thu-ve-vuon', 'Sát Thủ Về Vườn', 'Sakamoto Days', 'https://phimimg.com/upload/vod/20250112-1/fbf0edd755fb8be213f1d59ab1497202.jpg', 'https://phimimg.com/upload/vod/20250112-1/19e480c57fc804cdcebfb39f409ffa31.jpg', '<p>Thời gian trôi qua thật yên bình đối với Sakamoto kể từ khi anh ấy rời khỏi thế giới ngầm. Anh ấy đang điều hành một cửa hàng nhỏ trong khu phố với người vợ xinh đẹp và đứa con của mình, và có vẻ hơi... phát tướng rồi. Nhưng một ngày nọ, một nhân vật từ quá khứ của anh ấy đến thăm và đưa ra một lời đề nghị mà anh ấy không thể từ chối: quay trở lại thế giới sát thủ hoặc là chết!</p>', 'Hoàn Tất (22/22)', 22, 'hoathinh', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Tomokazu Sugita","avatar":""},{"name":"Nobunaga Shimazaki","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Nao Toyama","avatar":""},{"name":"Hina Kino","avatar":""},{"name":"Ryota Suzuki","avatar":""},{"name":"Miyari Nemoto","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["坂本DAYS","SAKAMOTO DAYS","सकामोटो के दिन","サカモト デイズ","サカモトデイズ","ซาคาโมโตะเดส์"]', 1784690324146);
