INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-du-an-minh-2025', 'Quỷ Dữ Ẩn Mình', 'All The Devils Are Here', 'https://phimimg.com/upload/vod/20251006-1/4c88e7c1e05a54686caa1f093e0914ba.jpg', 'https://phimimg.com/upload/vod/20251006-1/4a2080a82e5808d213f5c4a31cc46764.jpg', '<p>Sau một vụ cướp táo bạo, bốn tên tội phạm rút về một căn nhà an toàn nằm biệt lập, chờ đợi chỉ thị tiếp theo. Tuy nhiên, khi sự nghi ngờ và căng thẳng ngày càng gia tăng, họ dần nhận ra rằng mối nguy hiểm thật sự không phải ở bên ngoài — mà có thể đang ẩn mình ngay trong chính nhóm của họ.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Eddie Marsan","avatar":""},{"name":"Sam Claflin","avatar":""},{"name":"Burn Gorman","avatar":""},{"name":"Suki Waterhouse","avatar":""},{"name":"Tienne Simon","avatar":""},{"name":"Rory Kinnear","avatar":""},{"name":"Benjamin Dilloway","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Şeytanlar Aramızda","Tous les démons sont ici","魔鬼在人间","万鬼齐聚","Të gjithë djajtë janë këtu","All the Devils Are Here"]', 1784690324146);
