INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sieu-anh-hung-ba-do', 'Siêu Anh Hùng Bá Dơ', 'The Toxic Avenger Unrated', 'siêu anh hùng bá dơ the toxic avenger unrated peter dinklage jacob tremblay taylour paige julia davis jonny coyne elijah wood kevin bacon david yow sarah niles shaun dooley luisa guerreiro spencer wilding atanas srebrev abraham lewis lee eddy annette badland sunil patel rebecca o&#03 cheetah the toxic avenger токсичный мститель токсичний месник toxic le ravageur the toxic avenger uncut 悪魔の毒々モンスター vinġador toxico el vengador toxico เดอะ ท็อกซิก อเวนเจอร์ הנוקם הרעיל 毒魔复仇者 톡식 어벤저 the toxic avenger unrated', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuong-quyen-david-phan-1', 'Vương Quyền David (Phần 1)', 'House Of David (Season 1)', 'https://phimimg.com/upload/vod/20250304-1/f0e7473ff730bc0a4571e47b6f072db9.jpg', 'https://phimimg.com/upload/vod/20250304-1/5a576273f83ac61f4e10cab8691d8792.jpg', '<p>Bộ phim tái hiện sự trỗi dậy của David, từ một chàng trai trẻ trở thành vị vua được tôn kính nhất của Israel, đồng thời khắc họa sự suy tàn của Vua Saul, người bị chính lòng kiêu hãnh nhấn chìm. Theo ý chỉ của Thượng Đế, nhà tiên tri Samuel đã chọn và xức dầu cho một thiếu niên bị xã hội ruồng bỏ, trao cho cậu vương quyền.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Michael Iskander","avatar":""},{"name":"Ali Suliman","avatar":""},{"name":"Ayelet Zurer","avatar":""},{"name":"Alexander Uloom","avatar":""},{"name":"Stephen Lang","avatar":""},{"name":"Martyn Ford","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["בית דוד","בית דויד","House of David"]', 1784690324146);
