INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('necronomico-va-chuong-trinh-kinh-di-vu-tru', 'Necronomico Và Chương Trình Kinh Dị Vũ Trụ', 'Necronomico And The Cosmic Horror Show', 'https://phimimg.com/upload/vod/20250811-1/064c612f7b68003a23d5ac11069dfc7e.jpg', 'https://phimimg.com/upload/vod/20250811-1/a956a1e5dc3cb80044d49ecbc8bdff15.jpg', '<p>Câu chuyện kể về Miko Kurono (biệt danh Necronomico), sau khi tốt nghiệp trung học cơ sở, quyết định theo đuổi ước mơ trở thành một streamer. Một ngày nọ, cùng với cô bạn thời thơ ấu Mayu Mayusaka và đối thủ Kanna Kagurasaka, Miko nhận lời tham gia một trò chơi VR mới. Trong thế giới ảo này, cô có cơ hội tham gia những thử thách bí ẩn cùng nhiều streamer độc đáo khác mà mình gặp gỡ, mở ra hàng loạt trải nghiệm vừa kỳ lạ vừa hấp dẫn.</p>', 'Tập 11', 12, 'hoathinh', 'ongoing', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Riho Sugiyama","avatar":""},{"name":"Nana Hasumi","avatar":""},{"name":"Manaka Iwami","avatar":""},{"name":"Reiji Kawashima","avatar":""},{"name":"Hiroki Yasumoto","avatar":""},{"name":"Kazuyuki Okitsu","avatar":""},{"name":"Katsuyuki Konishi","avatar":""},{"name":"Ayasa Ito","avatar":""},{"name":"Zhar","avatar":""},{"name":"Lloigor","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["黑乃美子的宇宙恐怖秀","死灵之子的宇宙恐怖秀","涅库罗诺美子的宇宙恐怖秀","死灵书巫女的宇宙恐怖秀","涅庫羅諾美子的宇宙恐怖秀","Necronomico no Cosmic Horror Show","死靈之子的宇宙恐怖秀","ネクロノミ子のコズミックホラーショウ"]', 1784690324146);
