INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giao-luu-van-hoa-voi-co-gai-o-trung-tam-tro-choi', 'Giao Lưu Văn Hóa Với Cô Gái Ở Trung Tâm Trò Chơi', 'Cultural Exchange With A Game Centre Girl', 'https://phimimg.com/upload/vod/20250810-1/9a774ed76865d41f85c9ea72043bdcbd.jpg', 'https://phimimg.com/upload/vod/20250810-1/3a8aadac5baf9f230cdd992d9add3739.jpg', '<p>Câu chuyện kể về Kusakabe Renji, một chàng trai trẻ làm việc tại trung tâm trò chơi, tình cờ thấy cô gái người Anh tên Lily Baker chơi máy gắp thú vào ngày Valentine. Thấy cô liên tục thất bại, Renji không kiềm được mà ra tay giúp đỡ. Ngày hôm sau, khi Lily cuối cùng cũng nhận được thú nhồi bông, Renji bất ngờ nhận được tin nhắn từ cô: “Hãy làm Valentine của em nhé!”. Từ một sự hiểu lầm, cả hai bắt đầu một hành trình giao lưu văn hóa đầy thú vị.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Sally Amaki","avatar":""},{"name":"Shoya Chiba","avatar":""},{"name":"Reo Osanai","avatar":""},{"name":"Kaori Ishihara","avatar":""},{"name":"Asaki Yuikawa","avatar":""},{"name":"Ai Kayano","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["与游戏中心的少女异文化交流的故事","游乐场少女的异文化交流","GaCen de Shōjo to Ibunka Kōryū Suru Banashi","Gēsen Shōjo to Ibunka Kōryū","GaCen de Shoujo to Ibunka Kouryuu Suru Banashi","Game Center Shōjo to Ibunka Kōryū","Game Center Shoujo to Ibunka Kouryuu","Geesen Shoujo to Ibunka Kouryuu","GaCen Shoujo to Ibunka Kouryuu","Межкультурный обмен с девушкой у игровых автоматов","與遊戲中心的少女異文化交流的故事","遊樂場少女的異文化交流","Cross-Cultural Exchange With the Girl at the Arcade","Cultural Exchange With Game Center Girl","ゲーセン少女と異文化交流"]', 1784690324146);
