INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('truong-hoc-tinh-yeu', 'Trường Học Tình Yêu', 'Learning To Love', 'trường học tình yêu learning to love fumino kimura raul minami tanaka ayumu nakajima ryo mariko tsutsui yoshi sakō ikki sawamura ryotaro sakaguchi ryosuke mikata maho nonami miu hayasaka keishi arai yuuki beppu 爱的学校。 爱的，学校。 aprendiendo a amar ai no, gakko learning love 愛の、がっこう。', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sac-xuan-treu-nguoi-2025', 'Sắc Xuân Trêu Người', 'The Crush', 'https://phimimg.com/upload/vod/20250925-1/c7144105ec2d6357e498ac9894fd84a8.jpg', 'https://phimimg.com/upload/vod/20250925-1/15848abbae81644f348425cb370ceaf5.jpg', '<p>Ý thức của tổng giám đốc thời hiện đại Lâm Vũ Hào xuyên không vào trò chơi thương nhân buôn trà do chính mình tự phát triển, hoá thân thành cô vợ mới Nguỵ Tiểu Đường. Chỉ khi hoàn thành nhiệm vụ trong trò chơi, giành được danh hiệu “trà số một thiên hạ” mới có thể trở về thế giới của mình. Nguỵ Tiểu Đường nắm tay phu quân mình là Lý Tử Hiên cùng nhau mở ra chuyến hành trình giành giải nhất, cùng đấu trí đấu dũng nhưng vẫn giữ trái tim lương thiện của mình.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Ca Dương","avatar":""},{"name":"Tôn Nghệ Vũ","avatar":""},{"name":"Tôn Nghệ Chân","avatar":""},{"name":"Vu Hân Hòa","avatar":""},{"name":"Vương Hoằng Hâm","avatar":""},{"name":"Mã Nham","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chun Se Liao Ren","宅心仁斗​","Spring is Alluring","Courtyard Drama","春色撩人"]', 1784690324146);
