INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-thom-kieu-hanh', 'Hoa Thơm Kiêu Hãnh', 'The Fragrant Flower Blooms With Dignity', 'https://phimimg.com/upload/vod/20250715-1/e4331f5d3dd71c45cf0f703d85111ade.jpg', 'https://phimimg.com/upload/vod/20250715-1/0c646a8e697502885296168b1ef95a6a.jpg', '<p>Khi Rintaro đáng sợ gặp Kaoruko cởi mở, cặp đôi trái ngược này dần thân thiết hơn. Trớ trêu thay, hai ngôi trường trung học láng giềng của họ lại là &quot;kẻ thù không đội trời chung&quot;.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yoshinori Nakayama","avatar":""},{"name":"Honoka Inoue","avatar":""},{"name":"Kikunosuke Toya","avatar":""},{"name":"Koki Uchiyama","avatar":""},{"name":"Hiiro Ishibashi","avatar":""},{"name":"Aya Yamane","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["花开凛凛满薰香","花熏凛然","Kusuma Sekar Anggun","Kaoru Hana wa Rin to Saku","KaoruHana","Kaoru Hana","Ару Қыз Абыроймен Гүлдейді","Fragrant Flower Blooms","薫る花は凛と咲く"]', 1784690324146);
