INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoi-chung-tuoi-thanh-xuan-phan-2', 'Hội Chứng Tuổi Thanh Xuân (Phần 2)', 'Rascal Does Not Dream Of Santa Claus', 'hội chứng tuổi thanh xuân (phần 2) rascal does not dream of santa claus kaito ishikawa asami seto sora amamiya nao toyama atsumi tanezaki aya yamane maaya uchida konomi kohara yurika kubo manaka iwami inori minase reina ueda 青春期笨蛋不做兔女郎学姐的梦 青春猪头少年不会梦到兔女郎学姐 青春期笨蛋不会梦到兔女郎学姐 青春豬頭少年不會夢到兔女郎學姊 青春笨蛋少年不做兔女郎学姐的梦 青春猪头少年不会梦到圣诞服女郎 青春豬頭少年不會夢到聖誕服女郎 seishun buta yarou wa bunny girl-senpai no yume wo minai seishun buta yarō wa bunny girl-senpai no yume wo minai aobuta seishun buta yarou wa bunny girl senpai no yume wo minai puberty syndrome: abnormal experiences during adolescence due to sensitivity and instability. 青春ブタ野郎はサンタクロースの夢を見ない seishun buta yarou wa santa claus no yume wo minai 청춘 돼지는 산타클로스의 꿈을 꾸지 않는다 негодник, которому не снилась девушка-кролик эта глупая свинья не понимает мечту девочки-зайки! этот глупый свин не понимает мечту девочки-зайки rascal does not dream of santa claus 青春ブタ野郎はバニーガール先輩の夢を見ない', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuoc-chuoc-thieu-hoa', 'Chước Chước Thiều Hoa', 'Wild Ambition Bloom', 'https://phimimg.com/upload/vod/20250913-1/e340d45fdb6c19ab69c7f787223dc53d.jpg', 'https://phimimg.com/upload/vod/20250913-1/b1ac495cfdb3da91ef0a4e7789115a48.jpg', '<p>Năm 1916, để cứu anh trai là Chử Thiều Trung, Chử Thiều Hoa đã gả cho Trần Đại Thuận – cậu cả của hiệu thuốc Trần Ký. Bằng sự thành tín và tài năng kinh doanh xuất sắc, cô đã nhận được sự coi trọng của cha chồng và trở thành người quản lý hiệu thuốc. Sau khi cha chồng và Trần Đại Thuận bất ngờ qua đời, Trần Nhị Thuận kế thừa hiệu thuốc nhưng đã phung phí hết gia sản, khiến hiệu thuốc rơi vào cảnh khốn cùng. Chử Thiều Hoa đã gắng gượng vượt qua gian khổ, mở hiệu thuốc Hoa Thuận để nuôi sống cả gia đình. Cô quyết định cùng mối tình đầu Hạ Sơ bắt đầu một cuộc sống mới, nhưng lại bị Trần Nhị Thuận và mẹ chồng ngăn cản. Sau đó, nhà họ Trần bị thổ phỉ cướp sạch, trong kiếp nạn này, Chử Thiều Hoa cũng mất đi con gái, đau lòng tột độ, cô một mình đến Thượng Hải.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 9, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Nhiệt Y Tạ","avatar":""},{"name":"Dương Hựu Ninh","avatar":""},{"name":"Mao Tử Tuấn","avatar":""},{"name":"Chái Bích Vân","avatar":""},{"name":"Đường Tằng","avatar":""},{"name":"Tuyên Ngôn","avatar":""},{"name":"Chương Gia Duyệt","avatar":""},{"name":"Đồ Tùng Nham","avatar":""},{"name":"Thiệu Phong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Zhuo Zhuo Shao Hua Feng He Qi","野心家","灼灼韶华风禾起","Wild Ambition Bloom","The Uncaged Flame","灼灼韶华"]', 1784690324146);
