INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuoc-chuoc-thieu-hoa', 'Chước Chước Thiều Hoa', 'Wild Ambition Bloom', 'chước chước thiều hoa wild ambition bloom nhiệt y tạ dương hựu ninh mao tử tuấn chái bích vân đường tằng tuyên ngôn chương gia duyệt đồ tùng nham thiệu phong zhuo zhuo shao hua feng he qi 野心家 灼灼韶华风禾起 wild ambition bloom the uncaged flame 灼灼韶华', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-cua-phu-thuy-tinh-lang', 'Bí Mật Của Phù Thủy Tĩnh Lặng', 'Secrets Of The Silent Witch', 'https://phimimg.com/upload/vod/20250705-1/80111763a3c22f5c4c77d6a9bb9ebdce.jpg', 'https://phimimg.com/upload/vod/20250705-1/0eac34475ca78761aed40ad8ef04fd8f.jpg', '<p>Monica Everett được mệnh danh là &quot;phù thủy im lặng&quot; - thiên tài duy nhất có thể sử dụng phép thuật mà không cần niệm chú, thậm chí từng một mình hạ gục rồng đen huyền thoại. Nhưng đằng sau sức mạnh phi thường đó lại là một cô gái siêu nhút nhát, sợ hãi khi phải nói trước đám đông. Giờ đây, cô được giao một nhiệm vụ không chỉ nguy hiểm vì kẻ thù tàn độc mà còn đáng sợ bởi những cuộc trò chuyện xã giao, đó là bí mật bảo vệ hoàng tử thứ hai. Trong thế giới nơi lời nói chính là sức mạnh, liệu sự im lặng của cô có đủ để cứu lấy mọi người và chính bản thân mình?</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Saya Aizawa","avatar":""},{"name":"Hitomi Nabatame","avatar":""},{"name":"Junichi Suwabe","avatar":""},{"name":"Atsumi Tanezaki","avatar":""},{"name":"Shogo Sakata","avatar":""},{"name":"Kanna Nakamura","avatar":""},{"name":"Yoshiki Nakajima","avatar":""},{"name":"Ryohei Kimura","avatar":""},{"name":"Yuki Sakakihara","avatar":""},{"name":"Yoko Hikasa","avatar":""},{"name":"Mao Ichimichi","avatar":""},{"name":"Hina Suguta","avatar":""},{"name":"Shunichi Toki","avatar":""},{"name":"Ai Kayano","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Silent Witch 沉默魔女的秘密","沉默·魔女 沉默魔女的秘密","沉默魔女 沉默魔女的秘密","Silent Witch: Chinmoku no Majo no Kakushigoto","Sairento Uitchi: Chinmoku no Majo no Kakushigoto","サイレント・ウィッチ 沈黙の魔女の隠しごと","Silent Witch 沉默魔女的祕密","Мовчазна відьма","Безмовна відьма","Silent Witch"]', 1784690324146);
