INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-so-benh-an-thu-19', 'Hồ Sơ Bệnh Án Thứ 19', 'The 19th Medical Chart', 'https://phimimg.com/upload/vod/20250727-1/5033a5acbed2d443966eab727f804fbd.jpg', 'https://phimimg.com/upload/vod/20250727-1/9a5f859def5fc5e887e892f1f0c70946.jpg', '<p>Trong ngành y khoa tổng quát mới nổi ở Nhật Bản, bác sĩ Tokushige Akira sử dụng các kỹ năng tư vấn nhạy bén để điều trị cho những bệnh nhân có bệnh lý phức tạp hoặc khó chẩn đoán.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Jun Matsumoto","avatar":""},{"name":"Fuka Koshiba","avatar":""},{"name":"Mackenyu","avatar":""},{"name":"Yoshino Kimura","avatar":""},{"name":"Min Tanaka","avatar":""},{"name":"Hiroya Shimizu","avatar":""},{"name":"Taiiku Okazaki","avatar":""},{"name":"Nobue Iketani","avatar":""},{"name":"Chikara Honda","avatar":""},{"name":"Haruna Matsui","avatar":""},{"name":"First Summer Uika","avatar":""},{"name":"Kanji Tsuda","avatar":""},{"name":"Narushi Ikeda","avatar":""},{"name":"Katsuhisa Namase","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["第19份病历簿 德重晃的问诊","19 Banme no Karte: Tokushige Akira no Monshin","19番目のカルテ 徳重晃の問診","19 Banme no Karte","日曜劇場『19番目のカルテ』","19th Medical Record","The Medical Chart","19番目のカルテ"]', 1784690324146);
