INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuot-tam-kiem-soat-2025', 'Vượt Tầm Kiểm Soát', 'Out Of Order', 'https://phimimg.com/upload/vod/20251003-1/0ced58e78c3817999326aaf06072ad30.jpg', 'https://phimimg.com/upload/vod/20251003-1/771e9ec7a4ca376fcaa11e4e0d1bd5b3.jpg', '<p>Một luật sư túng quẫn có cơ hội đổi đời khi người cha xa cách nhờ anh hỗ trợ pháp lý sau khi bị đưa ra tòa vì tội giết người mà ông không hề nhớ đã gây ra.</p>', 'Full', 1, 'single', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Alden Richards","avatar":""},{"name":"Nonie Buencamino","avatar":""},{"name":"Heaven Peralejo","avatar":""},{"name":"Soliman Cruz","avatar":""},{"name":"Nicco Manalo","avatar":""},{"name":"Joyce Ching","avatar":""},{"name":"Andrea Del Rosario","avatar":""},{"name":"Francine Garcia","avatar":""},{"name":"Yayo Aguila","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Out of Order"]', 1784690324146);
