INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khong-so-hai-phan-2', 'Không Sợ Hãi (Phần 2)', 'The Fearless (Season 2)', 'không sợ hãi (phần 2) the fearless (season 2) nhiệt y trát vương dương chuốt ni thẩm vũ kiệt phùng huy trần cẩm chu thời mạc 你好生活 无所畏惧2 无所畏惧之永不放弃 ザ・フィアレス 무소외구 เกรงไม่กลัว 無所畏懼 unspoken the fearless fearless 2 unbreakable ⅱ unbreakable 无所畏惧', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khuc-tu-biet-truoc-guong', 'Khúc Từ Biệt Trước Gương', 'Echoes Of The Self', 'https://phimimg.com/upload/vod/20250921-1/a3fecf59627620c4f79879354be8d6ca.jpg', 'https://phimimg.com/upload/vod/20250921-1/d0b150c300424223c6124bb4c1526fff.jpg', '<p>Chu Nhược Hề từ bỏ tình yêu với Lý Yến để theo đuổi tham vọng và kết hôn với Thái tử, nhưng mưu mô cung đình dẫn đến cái chết của cả hai. Khi cuộc sống quay trở lại điểm khởi đầu, Chu Nhược Hề quyết tâm sửa sai và bảo vệ Lý Yến, chỉ để nhận ra kẻ thù lớn nhất chính là bản thân mình ba năm trước.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Dao","avatar":""},{"name":"Toàn Y Luân","avatar":""},{"name":"Hòa Phụng Thiên","avatar":""},{"name":"Thái Trác Âm","avatar":""},{"name":"Diêu Trác Quân","avatar":""},{"name":"Lý Khải Văn","avatar":""},{"name":"Trương Viện Ngọc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Zhao Jing Ci","照镜辞","ชะตาในเงาสะท้อน","เปลี่ยนชะตาราชินี","Echoes of the Self"]', 1784690324146);
