INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luc-luong-moi-skiftet', 'Lực Lượng Mới (Skiftet)', 'The New Force', 'https://phimimg.com/upload/vod/20251004-1/e725dd79dff1ad8e7e394868df202a13.jpg', 'https://phimimg.com/upload/vod/20251004-1/fb989d4255c7eb33bb914e8d96c6b3e5.jpg', '<p>Tại Thụy Điển thập niên 1950, một phân khu cảnh sát thiếu nhân sự triển khai thử nghiệm táo bạo: thành lập đội nữ cảnh sát đầu tiên. Loạt phim lấy cảm hứng từ sự kiện có thật.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 25, 2025, 'Vietsub', 'FHD', 'Thụy Điển', 0, '[{"name":"Josefin Asplund","avatar":""},{"name":"Agnes Westerlund Rase","avatar":""},{"name":"Malin Persson","avatar":""},{"name":"Christopher Wagelin","avatar":""},{"name":"Rasmus Luthander","avatar":""},{"name":"Cilla Thorell","avatar":""},{"name":"Hannes Fohlin","avatar":""},{"name":"Jimmy Lindström","avatar":""},{"name":"Peter Eriksson","avatar":""},{"name":"Pablo Leiva Wenger","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Skiftet"]', 1784690324146);
