INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoai-tinh-sau-lung-chong', 'Ngoại Tình Sau Lưng Chồng', 'Cheating On My Husband', 'https://phimimg.com/upload/vod/20251004-1/2bd41a78c41b9019b58032275b489eae.jpg', 'https://phimimg.com/upload/vod/20251004-1/2dd32b551009dd7ece828a799696c20a.jpg', '<p>Nữ chính Min-seo sống những ngày tháng hôn nhân bình thường cho đến khi vô tình phát hiện gã chồng Dong-uk ngoại tình. Để trả thù, Min-seo dùng tới các ứng dụng hẹn hò Dong-uk thường xuyên sử dụng để tiếp cận anh ta. Thu thập được càng nhiều bằng chứng, Min-seo càng đau đớn vì sự phản bội của chồng. Đồng thời việc anh đồng nghiệp Seong-han ở công ty tìm cách tiếp cận cô cũng khiến cô bối rối. Càng sốc hơn là Dong-uk lại ngoại tình với bạn thân nhất của cô, Jung-eun. Bị đả kích nặng nề, Min-seo với sự giúp đỡ của &quot;anh đồng nghiệp&quot;, cuối cùng đã trả thù được Dong-uk và &quot;bạn thân&quot;, ly hôn thành công và bắt đầu mối tình mới với &quot;anh đồng nghiệp&quot;...</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324146);
