INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-tu-lenh', 'Cẩm Tú Lệnh', 'Beyond The Loop', 'https://phimimg.com/upload/vod/20250927-1/e6bd552167b5d8e3cbc4c8d9d672ab2c.jpg', 'https://phimimg.com/upload/vod/20250927-1/0bcfeab1a4bc68c5a9343191b5e7f988.jpg', '<p>Vợ chồng Mục Vân Thanh và Dư Ánh Vãn bị sát hại khi bảo vệ thành chủ Lệnh Song Song. Dư Ánh Vãn tỉnh lại và phát hiện mình đã sống lại, nhưng Mục Vân Thanh lại tỏ ra vô cùng ghét bỏ cô. Để tìm ra kẻ thủ ác, Dư Ánh Vãn quyết định ở lại phủ thành chủ tùy cơ ứng biến, nhưng rồi cô phát hiện, Mục Vân Thanh cũng được sống lại. Kẻ chủ mưu đang lăm le hành động, liệu họ có thể thay đổi số phận?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vu Hiên Thần","avatar":""},{"name":"Lý Giai Khiết","avatar":""},{"name":"Hầu Đồng Giang","avatar":""},{"name":"Ngô Tịnh Hâm","avatar":""},{"name":"Vu Phi Phàm","avatar":""},{"name":"Nhung Tử Thừa","avatar":""},{"name":"Long Hinh Duyệt","avatar":""},{"name":"Thẩm Bác Hoài","avatar":""},{"name":"Trương Hằng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jin Xiu Ling","The Legend of Jinxiu","锦绣令"]', 1784690324146);
