INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vay-bat', 'Vây Bắt', 'Hunting', 'https://phimimg.com/upload/vod/20250927-1/2c07ff0fb756e49d5eb645a70604d666.jpg', 'https://phimimg.com/upload/vod/20250927-1/ab520c54c5614307a4500ad6e0fe9d4f.jpg', '<p>Câu chuyện xoay quanh chiến dịch “truy quét toàn diện” của cảnh sát. Cảnh sát phòng chống ma túy Dương Nhất Bằng lấy tên tội phạm cầm đầu Mưu Hải Đông – kẻ dù đã sa lưới nhưng vẫn ngoan cố chống trả – làm điểm đột phá. Với sự phối hợp của nữ cảnh sát trẻ Chi An và sự hỗ trợ từ gián điệp Đa Tử, họ lần theo manh mối về nguồn chế tạo loại ma túy mới của Mưu Sâm, từ đó phát hiện ra chuỗi buôn bán ma túy trải dài ở Hương Giang, Tương Nam, Điền Xuyên cùng nhiều địa bàn khác. Thế nhưng, kẻ đứng sau thao túng tất cả dường như vẫn chưa chính thức lộ diện…</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Dương","avatar":""},{"name":"Trương Ứu Hào","avatar":""},{"name":"Vu Hạo Minh","avatar":""},{"name":"Đặng Ân Hy","avatar":""},{"name":"Lý Thành Như","avatar":""},{"name":"Hứa Thiệu Hùng","avatar":""},{"name":"Dương Hạo Vũ","avatar":""},{"name":"Dư Ngải Lỗi","avatar":""},{"name":"Hoàng Lộ","avatar":""},{"name":"Phùng Binh","avatar":""},{"name":"Hạo Bình","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hunting","围猎"]', 1784690324146);
