INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vay-bat', 'Vây Bắt', 'Hunting', 'vây bắt hunting vương dương trương ứu hào vu hạo minh đặng ân hy lý thành như hứa thiệu hùng dương hạo vũ dư ngải lỗi hoàng lộ phùng binh hạo bình hunting 围猎', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuc-ban-phat-tai', 'Chúc Bạn Phát Tài', 'Money Money Come', 'https://phimimg.com/upload/vod/20250925-1/2a3360d6fc002b5a2724c5f636e8a898.jpg', 'https://phimimg.com/upload/vod/20250925-1/cb07327b3186c813e613bad708fd7a40.jpg', '<p>Trần Cung Hỷ, ông chủ một quán trà bình dị nằm trong con ngõ nhỏ ở phố Bắc Môn, hóa ra lại là &quot;thần mạt chược&quot; ẩn cư. Trong bối cảnh hai tập đoàn lớn đang đối đầu gay gắt, ba cô gái lần lượt tìm đến, thuyết phục anh tái xuất giang hồ. Để bảo vệ sự bình yên của khu phố cổ, anh đã cùng bóng hồng kề vai sát cánh, chiến đấu chống lại những âm mưu hiểm độc của giới tài phiệt. Trên bàn mạt chược nhỏ bé ngập tràn những âm mưu và sự lọc lừa, nhưng vị &quot;thần mạt chược&quot; trẻ tuổi đã liên tiếp hóa nguy thành an, giải cứu cả một vùng. Khi sắp có được con tim người đẹp, bí mật thân thế bị chôn vùi nhiều năm bất ngờ được hé lộ...</p>', 'Tập 22', 22, 'series', 'ongoing', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngô Phi","avatar":""},{"name":"Trịnh Nam Tịch","avatar":""},{"name":"Lưu Tuyết Phàm","avatar":""},{"name":"Vương Đường Đường","avatar":""},{"name":"Lý Giai Hinh","avatar":""},{"name":"Trần Nặc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Gong Xi Ni Fa Cai","恭喜你发财"]', 1784690324146);
