INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuc-ban-phat-tai', 'Chúc Bạn Phát Tài', 'Money Money Come', 'chúc bạn phát tài money money come ngô phi trịnh nam tịch lưu tuyết phàm vương đường đường lý giai hinh trần nặc gong xi ni fa cai 恭喜你发财', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('but-ky-tu-gia-cua-ngo-ta', 'Bút Ký Tư Gia Của Ngô Tà', 'Time Raiders', 'https://phimimg.com/upload/vod/20250920-1/4b41d870ea4a3ba5e3515e2e2dc4653c.jpg', 'https://phimimg.com/upload/vod/20250920-1/add6ec331a4510d5b2755f370be7a793.jpg', '<p>Ngô Tà, chủ một tiệm đồ cổ, tình cờ tìm được một cuộn sách lụa bí ẩn. Chú Ba của Ngô Tà là Ngô Tam Tỉnh, phát hiện trong đó ẩn giấu một tấm bản đồ thần bí. Để tìm tung tích chủ nhân đã mất tích của cuộn sách lụa, chú Ba dẫn theo Ngô Tà, Phan Tử, Tiểu ca Trương Khởi Linh và Đại Khuê lập thành một đội thám hiểm, cùng lên đường đến những địa điểm trên bản đồ để giải mã bí ẩn. Trong hành trình này, Ngô Tà làm quen với Vương Bàn Tử, người cũng đến để thăm dò bí mật. Đối mặt với muôn vàn hiểm nguy, thậm chí bị những sinh vật thần bí tấn công, cả nhóm đã đoàn kết, dùng trí tuệ và lòng dũng cảm để hóa giải nguy nan. Sâu dưới lòng đất, thứ họ phát hiện được, một con Xà Mi Đồng Ngư, đã bất ngờ hé mở quá khứ bị chôn vùi của chú Ba. Sau cuộc gặp gỡ với người phụ nữ bí ẩn A Ninh, ông đột nhiên biến mất không dấu vết. Để điều tra rõ sự thật và tìm kiếm người chú mất tích, Ngô Tà cùng các bạn lại dấn thân vào một cuộc hành trình mới...</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngô Trấn Vũ","avatar":""},{"name":"Tào Lỗi","avatar":""},{"name":"Từ Chấn Hiên","avatar":""},{"name":"Trình Tương","avatar":""},{"name":"Tôn Cát Xuyên Dã","avatar":""},{"name":"Lý Mộc Thần","avatar":""},{"name":"Mã Kinh Kinh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Wu Xie Si Jia Bi Ji","Personal Notes of Wu Xie","吴邪私家笔记"]', 1784690324146);
