INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-tinh-alphamnnchen', 'Nam Tính (Alphamännchen)', 'Dudes', 'https://phimimg.com/upload/vod/20251003-1/6e905d0ce3ba36d64dd6351203be6de4.jpg', 'https://phimimg.com/upload/vod/20251003-1/becc9efa495c15f5b521b63927aa48a0.jpg', '<p>Bốn người bạn thân thiết ở độ tuổi 40 cố gắng hết sức để thích nghi với chuẩn mực nam tính thời hiện đại – nhưng càng cố, họ lại càng khiến mọi thứ tệ hơn.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Tom Beck","avatar":""},{"name":"Moritz Führmann","avatar":""},{"name":"Serkan Kaya","avatar":""},{"name":"David Rott","avatar":""},{"name":"Franziska Machens","avatar":""},{"name":"Valentina Leone","avatar":""},{"name":"Marleen Lohse","avatar":""},{"name":"Mona Pirzad","avatar":""},{"name":"Jaela Probst","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Alphamännchen"]', 1784690324146);
