INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thiet-huyet-kim-thuan', 'Thiết Huyết Kim Thuẫn', 'Operation Golden Shield', 'https://phimimg.com/upload/vod/20251003-1/841f0bf6a44a498e968d49cd2e7666d6.jpg', 'https://phimimg.com/upload/vod/20251003-1/555940f562b7bf1e57f5b23370142d98.jpg', '<p>Phim kể về cảnh sát Lô Bành nhận nhiệm vụ từ cấp trên, trải qua hiểm nguy sinh tử, lần lượt hoạt động nằm vùng trong đường dây ma túy của tên buôn nội địa Chư Lạt Vọng và tên buôn ngoại quốc Nạp Oa. Cùng đồng đội phối hợp trong ngoài, triệt phá hai tập đoàn ma túy đóng lâu năm gần biên giới, làm nổi bật tinh thần hy sinh quên mình và dũng cảm của đội viên phòng chống ma túy công an.</p>', 'Full', 1, 'single', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"La Lập Quần","avatar":""},{"name":"Hoàng Dương Tử Hỷ","avatar":""},{"name":"Trương Anh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["铁血金盾"]', 1784690324146);
