INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('earthquake-cong-viec-ke-chuyen-cuoi', 'Earthquake: Công Việc Kể Chuyện Cười', 'Earthquake: Joke Telling Business', 'https://phimimg.com/upload/vod/20251003-1/845695bc7a4f7931c2b2af583e4f08b4.jpg', 'https://phimimg.com/upload/vod/20251003-1/e11a52b43ca659cd880a2e05c1dcdd0d.jpg', '<p>ChatGPT đã nói: Từ việc bóc tách những scandal của giới sao cho đến những quan điểm táo bạo về tình yêu, danh hài huyền thoại Earthquake khuấy đảo sân khấu trong một suất diễn stand-up bùng nổ.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Earthquake","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Earthquake: Joke Telling Business"]', 1784690324146);
