INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-on-vi-yeu-em-2025', 'Cảm Ơn Vì Yêu Em', 'Thank You For Loving Me', 'https://phimimg.com/upload/vod/20251003-1/131012c0191f3ab61e53b63d00c45e5b.jpg', 'https://phimimg.com/upload/vod/20251003-1/4a794662119e4377494fa34b58174553.jpg', '<p>Lâm Quả Quả và Tiền Bân vốn là người yêu, nhưng sa vào cạm bẫy của bọn buôn ma túy, cả hai dính nghiện và không thể tự thoát ra. Người đồng nghiệp Phùng Hiểu Nam, thầm yêu Lâm Quả Quả, đã kiên quyết đưa cô đi cai nghiện. Sau khi cai thành công, Lâm Quả Quả trở lại sân khấu, tiếp tục luyện tập những điệu múa mới. Trong khi đó, Tiền Bân trở thành cảnh sát ngầm, xâm nhập vào đường dây buôn ma túy. Cuối cùng, anh đã lấy chính mạng sống của mình để phá tan tập đoàn tội phạm, hoàn mỹ thực hiện lời hứa năm xưa.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Tử Huyền","avatar":""},{"name":"Lý Cường","avatar":""},{"name":"Minh Tiếu Lượng","avatar":""},{"name":"Vu Kiệm","avatar":""},{"name":"Trương Linh Nhi","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["谢谢你爱我"]', 1784690324146);
