INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-vu-ban', 'Phi Vụ Bẩn', 'Play Dirty', 'https://phimimg.com/upload/vod/20251003-1/d9903bcbad77788b345a88f7f2a375d7.jpg', 'https://phimimg.com/upload/vod/20251003-1/449f78ffa82c0f71e74450a4ef42c874.jpg', '<p>Một siêu trộm mang tên Parker bước vào phi vụ táo bạo nhất đời mình – một vụ cướp có thể thay đổi tất cả. Để thành công, anh phải vượt qua những kẻ thù nguy hiểm nhất: một nhà độc tài khét tiếng Nam Mỹ, băng mafia New York tàn nhẫn, và một tỷ phú quyền lực thao túng cả thế giới.Giữa mê cung của lừa lọc, phản bội và những màn đấu trí nghẹt</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mark Wahlberg","avatar":""},{"name":"LaKeith Stanfield","avatar":""},{"name":"Rosa Salazar","avatar":""},{"name":"Keegan-Michael Key","avatar":""},{"name":"Chukwudi Iwuji","avatar":""},{"name":"Nat Wolff","avatar":""},{"name":"Thomas Jane","avatar":""},{"name":"Tony Shalhoub","avatar":""},{"name":"Gretchen Mol","avatar":""},{"name":"Hemky Madera","avatar":""},{"name":"Alejandro Edda","avatar":""},{"name":"Yvonne Zima","avatar":""},{"name":"Nicole da Silva","avatar":""},{"name":"Saskia Archer","avatar":""},{"name":"Claire Lovering","avatar":""},{"name":"Chai Hansen","avatar":""},{"name":"Sebastian Car","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["玩得很脏","脏局","盗亦有道","Jogo Sujo","Juego sucio","Нечесна гра","بازی کثیف","Play Dirty"]', 1784690324146);
