INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cay-cau-sirt', 'Cây Cầu Sirāt', 'Sirāt', 'https://phimimg.com/upload/vod/20251003-1/a7596bb979bfad870df110aed0e99ee5.jpg', 'https://phimimg.com/upload/vod/20251003-1/f28a78e5f4a805d61473a666e376fd9f.jpg', '<p>Một người cha và con trai lang thang giữa một lễ hội rave cuồng nhiệt, ẩn mình sâu trong vùng núi miền nam Maroc. Họ đang tìm Mar — người con gái, người chị đã biến mất không dấu vết tại một bữa tiệc như thế, nhiều tháng trước. Giữa thế giới hỗn loạn của nhạc điện tử và thứ tự do kỳ lạ, gần như siêu thực, họ lặng lẽ giơ tấm ảnh của cô ra, hỏi từng người. Hy vọng ngày một mong manh, nhưng họ vẫn bám theo một nhóm dân chơi đang hướng về bữa tiệc cuối cùng nơi sa mạc. Khi hành trình dẫn họ ngày càng xa khỏi thế giới quen thuộc, họ buộc phải đối mặt với chính bản thân — và những giới hạn tận cùng của tình thân, thể xác và niềm tin.</p>', 'Full', 1, 'single', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Sergi López","avatar":""},{"name":"Bruno Núñez","avatar":""},{"name":"Stefania Gadda","avatar":""},{"name":"Joshua Liam Herderson","avatar":""},{"name":"Richard Bellamy","avatar":""},{"name":"Tonin Javier","avatar":""},{"name":"Jade Oukid","avatar":""},{"name":"Ahmed Abbou","avatar":""},{"name":"Abdellilah Madrari","avatar":""},{"name":"Mohamed Madrari","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Sirat. Trance en el desierto","Sirat","Sirât","Siratas","Sirāt"]', 1784690324146);
