INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rung-vang-2025', 'Rừng Vàng', 'Golden Forest (The Fading Gold)', 'https://phimimg.com/upload/vod/20250918-1/a103548a654398d508a53df4fab3811b.jpg', 'https://phimimg.com/upload/vod/20250918-1/08bdc8dc791ab424d9ce63bfd579e033.jpg', '<p>Rừng Vàng xoay quanh hành trình bảo vệ danh dự và gia sản của Phương Ngưỡng Thiên, người đứng đầu đế chế thương mại Phương Thị có trị giá hàng tỷ. May mắn sống sót sau một tai nạn xe hơi, tỷ phú Phương Ngưỡng Thiên khiến cả gia đình bàng hoàng khi tuyên bố sẽ tái hôn với một cô gái trẻ hơn mình ba mươi tuổi và chuyển hết toàn bộ tài sản vào một quỹ tín thác do đối thủ của gia đình họ Phương quản lý. Khi ba người con trai xúi giục bà nội kiện ra tòa, Chủ tịch Phương thà kiện cáo với mẹ và trở mặt với con cái chứ không chịu khuất phục. Động cơ thật sự phía sau sự thay đổi đột ngột và bất thường này của Chủ tịch Phương là gì?</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 8, 2025, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Quách Tấn An","avatar":""},{"name":"Trần Hiểu Hoa","avatar":""},{"name":"La Tử Dật","avatar":""},{"name":"Cung Từ Ân","avatar":""},{"name":"Tưởng Gia Mẫn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Golden Forest","金式森林"]', 1784690324146);
