INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('rung-vang-2025', 'Rừng Vàng', 'Golden Forest (The Fading Gold)', 'rừng vàng golden forest (the fading gold) quách tấn an trần hiểu hoa la tử dật cung từ ân tưởng gia mẫn golden forest 金式森林', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-ve-mien-co-nang', 'Đi Về Miền Có Nắng', 'Going To The Sunny Land', 'https://phimimg.com/upload/vod/20251002-1/4ac4467419bf78d100d3d9468841c798.jpg', 'https://phimimg.com/upload/vod/20251002-1/d1e65e6fb5a04090a9e444c2bc9eb9b5.jpg', '<p>Câu chuyện xoay quanh nhân vật chính Ánh Dương - một người mẹ đơn thân trẻ tuổi. Sau khi rời xa cuộc hôn nhân không hạnh phúc, cô cùng con đến Bảo Lộc và trở thành trợ lý tại công ty của ông Phan. Cuộc sống của Ánh Dương bắt đầu có nhiều biến động khi Đình Phong - con trai ông Phan từ nước ngoài trở về để tiếp quản công ty gia đình. Lịch chiếu và nội dung phim Đi về miền có nắng Mối quan hệ giữa Ánh Dương và Đình Phong trở nên phức tạp bởi những hiểu lầm và sự xuất hiện của Tường Vân - cô gái say đắm Đình Phong. Tường Vân liên tục tìm cách gây khó dễ cho Ánh Dương, khiến mối quan hệ giữa ba người ngày càng căng thẳng. Tình huống càng trở nên khó khăn khi những bí mật từ quá khứ của các bậc phụ huynh dần được hé lộ. Chỉ khi ông Phan ngã bệnh, Đình Phong mới có cơ hội nhìn nhận đúng về con người thật của Ánh Dương. Qua những thử thách, cả hai dần học được cách đối diện với những tổn thương của bản thân và trân trọng tình yêu đích thực.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Lam Tuyền","avatar":""},{"name":"Đức Sơn","avatar":""},{"name":"Bình An","avatar":""},{"name":"Khánh Ly","avatar":""},{"name":"Yên Đan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324146);
