INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vang-menh-tra-ngoc', 'Vâng Mệnh Trả Ngọc', 'The Mission Is To Return the Pearl', 'https://phimimg.com/upload/vod/20250918-1/406ae81d3565d04a994fe9f89f5db5e1.jpg', 'https://phimimg.com/upload/vod/20250918-1/e4e2cadcd916b10beda012e524a55ee5.jpg', '<p>Bộ phim kể về Lý Lăng, một công tử nổi danh sống vào thời Đông Hán, thời đại mà ngọc trai, đặc biệt là Nam Châu cực kỳ có giá trị. Lúc này, trò chơi cá cược ngọc trai đang rất phổ biến. Lý Lăng bị cuốn vào cuộc chơi ngọc trai do Thái thú sắp đặt, cuối cùng phá sản, trở thành con rối bị thao túng, phải đứng mũi chịu sào về sự biến động của giá ngọc trai. Sau đó, Lý Lăng bị hãm hại và chết thảm. Tuy nhiên, sau khi chết, Lý Lăng đã được trùng sinh, sống lại vào thời điểm trước khi phá sản và phát hiện mình sở hữu một năng lực đặc biệt, đó là khả năng nhìn xuyên thấu và cảm nhận đối với các con sò biển. Kết hợp với ký ức kiếp trước, anh bắt đầu sử dụng khả năng này để chiến thắng trong những cuộc cá cược ngọc trai, qua đó không những báo được thù mà còn bắt đầu một hành trình đầy kịch tính đưa ngọc trai vật hoàn cố chủ, mở ra một cuộc đời huyền thoại.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Phù Khiên Văn","avatar":""},{"name":"Trương Tinh Dao","avatar":""},{"name":"Quách Tĩnh","avatar":""},{"name":"A Bỉ Đạt","avatar":""},{"name":"Thượng Na","avatar":""},{"name":"Lý Giai Bàn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["奉命还珠"]', 1784690324146);
