INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-ban-thuan-khiet-phan-2', 'Tình Bạn Thuần Khiết (Phần 2)', 'Platonic (Season 2)', 'https://phimimg.com/upload/vod/20250814-1/de8ef833b8167f62166fec9b6eb019eb.jpg', 'https://phimimg.com/upload/vod/20250814-1/8f727035fc69a44ebb00bcc8bfda8be9.jpg', '<p>Seth Rogen và Rose Byrne vào vai đôi bạn thân cũ sắp bước sang tuổi trung niên kết nối lại sau thời gian dài rạn nứt. Khi tình bạn của họ trở nên gắn bó hơn, nó khiến cuộc sống của họ hỗn loạn theo một cách vui nhộn.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rose Byrne","avatar":""},{"name":"Seth Rogen","avatar":""},{"name":"Luke Macfarlane","avatar":""},{"name":"Carla Gallo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["柏拉图氏关系","אפלטוני","플라토닉","Platonic"]', 1784690324146);
