INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngu-tru-cua-bao-chua', 'Ngự Trù Của Bạo Chúa', 'Bon Appétit, Your Majesty', 'https://phimimg.com/upload/vod/20250823-1/a3e5e347cfb12b8b836670069dd5b777.jpg', 'https://phimimg.com/upload/vod/20250823-1/6cecd0755934def609b834127974dab8.jpg', '<p>Xuyên không về thời Joseon, đầu bếp tài năng nọ gặp vị quân chủ bạo chúa. Các món ăn hiện đại của cô chinh phục khẩu vị của ngài, song thử thách chốn hoàng cung cũng đang chờ đợi.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 12, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yoona","avatar":""},{"name":"Lee Chae-min","avatar":""},{"name":"Kang Hanna","avatar":""},{"name":"Choi Gwi-hwa","avatar":""},{"name":"Oh Eui-sik","avatar":""},{"name":"Seo Yi-sook","avatar":""},{"name":"Park Young-woon","avatar":""},{"name":"Yoon Seo-ah","avatar":""},{"name":"Lee Joo-Ahn","avatar":""},{"name":"Kim Hyeon-mok","avatar":""},{"name":"Kim Kwang-kyu","avatar":""},{"name":"Jeong Gyu-su","avatar":""},{"name":"Jang Kwang","avatar":""},{"name":"Park Jun-myun","avatar":""},{"name":"Shin Eun-jung","avatar":""},{"name":"Nam Kyung-eup","avatar":""},{"name":"Son Jong-hak","avatar":""},{"name":"Cho Seung-yeon","avatar":""},{"name":"Jo Young-","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["폭군의 셰프"]', 1784690324146);
