INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-sinh-thanh-de-that-hoang-tu-toi-quyet-dinh-trau-doi-ma-thuat-phan-2', 'Chuyển Sinh Thành Đệ Thất Hoàng Tử, Tôi Quyết Định Trau Dồi Ma Thuật (Phần 2)', 'I Was Reincarnated As The 7th Prince So I Can Take My Time Perfecting My Magical Ability (Season 2)', 'chuyển sinh thành đệ thất hoàng tử, tôi quyết định trau dồi ma thuật (phần 2) i was reincarnated as the 7th prince so i can take my time perfecting my magical ability (season 2) makoto koichi fairouz ai lynn akira sekine rie takahashi shun horie yuya hirose akane kumada eriko matsui tomokazu sugita satomi akesaka shunichi toki takuma nagatsuka nobunaga shimazaki 随心所欲的魔法学习之路 转生七王子的魔法全解 转生为第七王子 tensei shitara dainana ōji datta no de, kimamani majutsu o kiwamemasu tensei shitara dainana ouji datta no de, kimamani majutsu o kiwamemasu dainana ouji 第七王子 tensei shitara dainana ouji datta node, kimama ni majutsu wo kiwamemasu tensei shitara dai nana ouji datta no de, kimamani majutsu o kiwamemasu dainanaoji tensei shitara dai nana ouji datta node, kimamani majutsu wo kiwamemasu tensei shitara dai nana ōji datta no de, kimamani majutsu o kiwamemasu tensei shitara dai nana ōji datta node, kimamani majutsu wo kiwamemasu tensei shitara dai nana ouji dattanode kimamani majutsu wo kiwamemasu てんせいしたらだいななおうじだったので、きままにまじゅつをきわめます tensei shitara dai nana ōji datta no de, kimama ni majutsu o kiwamemasu dainanaouji tensei shitara dainana ouji 환생했는데 제7왕자라 내맘대로 마술을 연마합니다 환생했는데 제7왕자라 내 맘대로 마술을 연마합니다 轉生為第七王子，隨心所欲的魔法學習之路 轉生為第七王子隨心所欲的魔法學習之路第二季 i was reincarnated as the 7th prince so i can take my time perfecting my magical ability i can take my time perfecting my magical ability i was reincarnated as the 7th prince chuyển sinh thành đệ thất hoàng tử, tôi quyết định trau dồi ma thuật chuyển sinh thành đệ thất hoàng tử 転生したら第七王子だったので、気ままに魔術を極めます', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-sau-tram-trieu-lan-gap-go', 'Yêu Sau Trăm Triệu Lần Gặp Gỡ', 'The Beauty Billionaire', 'https://phimimg.com/upload/vod/20251001-1/7f8c2f6968423731ea22777ad4ea924b.jpg', 'https://phimimg.com/upload/vod/20251001-1/aa18b6d258022537a007ec1a5392000c.jpg', '<p>Sau một tai nạn xe bất ngờ, gương mặt của nữ công nhân thời vụ Su Ah vô tình bị hoán đổi thành gương mặt của cô chủ tài phiệt Hye Mi. Từ giây phút ấy, cô buộc phải bước vào cuộc sống xa hoa nhưng đầy dối trá với một thân phận không thuộc về mình. Mang trên mình diện mạo mới, Su Ah nung nấu ý định trả thù Jeong Min - kẻ đã từng đẩy cô xuống tận cùng tuyệt vọng. Thế nhưng trớ trêu thay, số phận lại gắn kết cô với Se Ju - vị hôn phu của Hye Mi, khiến mối quan hệ vốn đã phức tạp nay càng trở nên rối ren. Giữa hận thù và những cảm xúc chồng chéo, tình yêu của họ dần nảy nở. Liệu Su Ah - người vô tình trở thành “cô chủ nhà giàu” nhờ một ca phẫu thuật định mệnh sẽ có cái kết như thế nào?</p>', 'Hoàn Tất (54/54)', 54, 'series', 'completed', 18, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phim Ngắn","slug":"phim-ngan","id":"4f02d28224c0747511790d57fbb63a62"}]', '[]', 1784690324146);
