INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khach-quan-moi-thuong-toa', 'Khách Quan Mời Thượng Tọa', 'Misty Rain Jiangnan Drunk Shaoxing', 'https://phimimg.com/upload/vod/20251001-1/de7521669e0b89621a17f7dd1b544527.jpg', 'https://phimimg.com/upload/vod/20251001-1/000b682c9dabc28f91231f60451e5d31.jpg', '<p>Nhà thám hiểm du lịch bụi Tạ Tiểu Vận sau tám năm phiêu bạt cuối cùng cũng trở về quê hương. Trên đường đi ngang Túy Tiên Lâu, anh tình cờ tiếp quản quán rượu trăm năm tuổi này đang cần người kế nhiệm. Ban đầu, anh chỉ định bán đi để đổi lấy tiền, nhưng không ngờ lại bị cuốn vào những phong ba giang hồ. Đối diện quán rượu còn có Đậu Hũ Tây Thi, vị hôn thê chưa kịp thành thân của anh. Trong quá trình điều hành, Tạ Tiểu Vận quen biết và kết giao với nhiều bằng hữu giang hồ tính cách khác nhau. Dưới sự giúp đỡ của họ, anh đã dùng Túy Tiên Lâu để che chở nữ hiệp Hoa Hồ Điệp xứ Hội Kê, khuyên nhủ Lý Tứ, chỉ huy Cẩm Y Vệ, trở lại phục vụ đất nước, bắt giữ gian thương A Cửu chuyên sản xuất rượu giả, cưu mang đứa trẻ mồ côi Tiểu Thụ Miêu, đấu kiếm cùng võ sĩ Nhật Bản tại Thiên Mẫu Sơn, và còn có cơ duyên luận đàm cùng bậc hiền triết Vương Dương Minh tại Đại Phật Tự. Muôn hình muôn vẻ khách nhân ghé qua Túy Tiên Lâu, mang theo những câu chuyện kỳ lạ và huyền thoại. Trong lúc giúp đỡ họ tìm lại chính mình, quán rượu cũng trở thành nơi để Tạ Tiểu Vận trải qua quá trình trưởng thành và tự chữa lành. Nhưng ngay lúc này, sóng gió tạo phản của Ninh Vương ập đến, anh sẽ lại chọn trốn chạy, hay dũng cảm đối diện?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngô Minh Hiên","avatar":""},{"name":"Trương Dịch Tâm","avatar":""},{"name":"Châu Thiên Phúc","avatar":""},{"name":"Lý Minh Lôi","avatar":""},{"name":"Dương Bác","avatar":""},{"name":"Triệu Bác Á","avatar":""},{"name":"Lục Thần Lâm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Ke Guan Qing Shang Zuo","Sir, Please Take a Seat","客官请上座"]', 1784690324146);
