INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('g4nh-dua-riv4li', 'G4nh Đua (RIV4LI)', 'RIV4LRIES', 'https://phimimg.com/upload/vod/20251001-1/91e62638ab45905a4379dbca4ee9712c.jpg', 'https://phimimg.com/upload/vod/20251001-1/8d9f4f5a24a9df79c6409401b90dd8d1.jpg', '<p>Tại một trường cấp hai ở Pisa, chưa từng có ai thách thức nhóm học sinh cộm cán – cho đến khi cô nàng Terry chuyển đến với những ý tưởng táo bạo, khơi mào hàng loạt cuộc ganh đua.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Andrea Arru","avatar":""},{"name":"Samuele Carrino","avatar":""},{"name":"Edoardo Miulli","avatar":""},{"name":"Joseph Figueroa","avatar":""},{"name":"Lorenzo Ciamei","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["תחרויות","RIVALRIES","RIV4LI"]', 1784690324146);
