INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('la-gio-lay-hay-tim-rung-dong', 'Là Gió Lay Hay Tim Rung Động', 'The Wind, It''s The Heartbeat', 'https://phimimg.com/upload/vod/20250929-1/d624bdd276e64ff54ab22dcd2402b15a.jpg', 'https://phimimg.com/upload/vod/20250929-1/a4e615b84b4c7eaf186d0453d7553172.jpg', '<p>Câu chuyện kể về Đỉnh cấp ca sĩ Đồng Tâm, trong một sự kiện đã bắt được kẻ bám đuôi mình – hóa ra đó lại là người bạn thân từng như chị em, An Ninh. An Ninh tố cáo cô đã “cướp đi cuộc đời” của mình rồi tự cứa tay, khiến Đồng Tâm sốc nặng và không thể tiếp tục ca hát. Trong quá trình điều trị, Đồng Tâm tình cờ gặp lại mối tình đầu Giang Dẫn Xuyên, nay đã trở thành bác sĩ thiên tài. Anh che giấu thân phận thật, đóng giả làm hôn phu để chăm sóc cô, điều này khiến ca sĩ Tuyên Trạch, người luôn thầm yêu Đồng Tâm, không hài lòng. Trong khi đó, An Ninh liên tục bày mưu hãm hại, còn Đồng Tâm trong quá trình tìm chứng cứ đã phát hiện Giang Dẫn Xuyên năm xưa từ chối mình là vì mặc cảm tự ti. Hiểu lầm được hóa giải, nhưng Đồng Tâm lại phát hiện kẻ chủ mưu thực sự phía sau là Tuyên Trạch. Cuối cùng, Đồng Tâm làm sáng tỏ tất cả, trở lại sân khấu và chấp nhận lời cầu hôn của Giang Dẫn Xuyên.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Mông Ân","avatar":""},{"name":"Lâm Thất Dự","avatar":""},{"name":"Vương Tinh Vĩ","avatar":""},{"name":"Trương Dĩ Khả","avatar":""},{"name":"Vương Lược Đào","avatar":""},{"name":"Lưu Gia Vân","avatar":""},{"name":"Lữ Mạnh Gia","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shi Feng Dong, Shi Xin Dong","The Wind, It''s the Heart","Is the Wind, Is the Heart","是风动、是心动"]', 1784690324146);
