INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('marvel-zombies', 'Marvel Zombies', 'Marvel Zombies', 'https://phimimg.com/upload/vod/20250924-1/33922de46ec1e71e59c705ec316589e6.jpg', 'https://phimimg.com/upload/vod/20250924-1/df6f49387bd279265fc99385dc2747aa.jpg', '<p>Sau khi các Avengers bị dịch bệnh xác sống xâm chiếm, một nhóm người sống sót tuyệt vọng đã phát hiện ra chìa khóa để chấm dứt đội quân siêu anh hùng thây ma. Họ phải liều mạng băng qua vùng đất loạn lạc, đối mặt hiểm nguy khắp nơi để cứu lấy thế giới.</p>', 'Hoàn Tất (4/4)', 4, 'hoathinh', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Elizabeth Olsen","avatar":""},{"name":"Iman Vellani","avatar":""},{"name":"David Harbour","avatar":""},{"name":"Simu Liu","avatar":""},{"name":"Awkwafina","avatar":""},{"name":"Todd Williams","avatar":""},{"name":"Robin Atkin Downes","avatar":""},{"name":"David Boat","avatar":""},{"name":"Terri Douglas","avatar":""},{"name":"Kari Wahlgren","avatar":""},{"name":"Fred Tatasciore","avatar":""},{"name":"Debra Wilson","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["מארוול זומבים","마블 좀비즈","Марвел Зомби","Marvel Зомби","Зомби Марвел","Marvel Зомбі","Зомбі Marvel","Marvel Studios'' Marvel Zombies","Marvel Animation''s Marvel Zombies","Marvel Zombies"]', 1784690324146);
