INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-kiem-cua-tho-san-quy', 'Thanh Kiếm Của Thợ Săn Quỷ', 'Sword Of The Demon Hunter: Kijin Gentosho', 'https://phimimg.com/upload/vod/20250401-1/15ab468833d55309ed5399a96fdd5ca2.jpg', 'https://phimimg.com/upload/vod/20250401-1/8970956374a769e0892875c61b29ff3a.jpg', '<p>Ngôi làng Kadono, nơi ngự trị ngôi đền cổ kính cùng lời nguyền về Quỷ Thần trỗi dậy. Jinta, người bảo hộ Itsukihime, đối mặt với lời tiên tri đen tối. Bị ám ảnh bởi tương lai diệt vong, Jinta dấn thân vào cuộc săn lùng xuyên không gian và thời gian. Anh tìm kiếm công lý, giải mã quá khứ, và chiến đấu để thay đổi số phận. Một hành trình nghẹt thở, nơi quá khứ và tương lai giao tranh, và định mệnh được viết lại bằng máu và nước mắt.</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Taku Yashiro","avatar":""},{"name":"Saori Hayami","avatar":""},{"name":"Reina Ueda","avatar":""},{"name":"Hiroshi Shirokuma","avatar":""},{"name":"Yui Kondou","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Sword of the Demon Hunter","Kijin Gentoushou","Хроники людей и демонов","سيف صائد الشياطين","Меч демоноборця","Sword of the Demon Hunter: Demon God Gento Chao","Sword of the Demon Hunter: Demon Phantom Chao","Sword of the Demon Hunter: Kijin Gentoushou","Sword of the Demon Hunter: Kijin Gentōshō","Sword of the Demon Hunter: Kijin Gentosho","鬼人幻燈抄"]', 1784690324146);
