INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('city-the-animation', 'CITY THE ANIMATION', 'CITY THE ANIMATION', 'https://phimimg.com/upload/vod/20250909-1/48f9c66ef8f910107edfae1f6840628c.jpg', 'https://phimimg.com/upload/vod/20250909-1/2d6e985a75e99173ec9c6643fedfd3e2.jpg', '<p>Thị trấn này không chỉ là một thị trấn bình thường. Ở đây có tiếng cười, tình yêu và những khoảnh khắc xúc động. Cuộc sống thường nhật đầy bất ngờ được khắc họa qua những cư dân! Những điều thú vị liên tiếp xảy đến. Chào mừng bạn đến với CITY.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Mikako Komatsu","avatar":""},{"name":"Aki Toyosaki","avatar":""},{"name":"Yui Ishikawa","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["小城日常","시티 디 애니메이션","시티 더 애니메이션","City the Animation","CITY THE ANIMATION"]', 1784690324146);
