INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bach-da-than-duyen-khoi-tam-sinh', 'Bạch Dạ Thần Duyên Khởi Tam Sinh', 'The Sun In The Dark', 'https://phimimg.com/upload/vod/20250915-1/49258418154f8c673a5bdec4e2abb11d.jpg', 'https://phimimg.com/upload/vod/20250915-1/68947ac2e1115cca6cfae6a946020be0.jpg', '<p>Bạch Tiểu Huỳnh từ nhỏ đã bị xem là ác ma, đã tu luyện thành tiên để báo thù cho cái chết của cha. Cô bị ràng buộc linh hồn với Dạ Thần - Dạ Thần Uyên, và dần nảy sinh tình cảm với anh. Dạ Thần Uyên đã hy sinh bản thân để giúp cô thức tỉnh, vạch trần âm mưu thao túng Dạ Thần của Tiên Vương. Với sự giúp đỡ của mọi người, Bạch Tiểu Huỳnh đã giết chết Tiên Chúa và kết liễu mạng sống của Dạ Thần. Dạ Thần Uyên hóa thành kiếm linh và tan biến, để lại Bạch Tiểu Huỳnh chờ đợi ngàn năm để được trọng sinh.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Tử Dị","avatar":""},{"name":"Tất Dục Thần","avatar":""},{"name":"Hướng Hân","avatar":""},{"name":"Trữ Tự Thuyên","avatar":""},{"name":"Quách Hinh Ngọc","avatar":""},{"name":"Vương Sóc","avatar":""},{"name":"Tăng Hi Đường","avatar":""},{"name":"Doãn Nhuỵ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bai Ye Chen Yuan Qi San Sheng","白夜宸缘起三生"]', 1784690324146);
