INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-gio-o-costiera-hotel', 'Sóng Gió Ở Costiera Hotel', 'Hotel Costiera', 'https://phimimg.com/upload/vod/20250927-1/ba7e031f7618a89c5a66bfc5eb2cea38.jpg', 'https://phimimg.com/upload/vod/20250927-1/65f0894a942477f8211b94427672d22e.jpg', '<p>Daniel De Luca, cựu lính thủy đánh bộ mang hai dòng máu Ý – Mỹ, trở về quê hương tuổi thơ và nhận công việc đặc biệt tại một trong những khách sạn xa hoa bậc nhất thế giới, tọa lạc bên bờ biển Positano tráng lệ. Ở nơi thiên đường ấy, anh trở thành người chuyên giải quyết những rắc rối không ai ngờ tới.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 13, 2025, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Jesse Williams","avatar":""},{"name":"Jordan Alexandra","avatar":""},{"name":"Alejandra Onieva","avatar":""},{"name":"Maria Chiara Giannetta","avatar":""},{"name":"Antonio Gerardi","avatar":""},{"name":"Tommaso Ragno","avatar":""},{"name":"Amanda Campana","avatar":""},{"name":"Pierpaolo Spollon","avatar":""},{"name":"Sam Haygarth","avatar":""},{"name":"Jean-Hugues Anglade","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Costiera","Hotel Costiera"]', 1784690324146);
