INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-sao-rac-roi-cua-toi', 'Ngôi Sao Rắc Rối của Tôi', 'My Troublesome Star', 'https://phimimg.com/upload/vod/20250820-1/28de650a8c7d3015fa5adedc2981aeaa.jpg', 'https://phimimg.com/upload/vod/20250820-1/5fd72123615ee6b9c6f08e6327fc76ea.jpg', '<p>Nếu một ngày bạn vô tình đánh mất 25 năm đời người, liệu bạn còn có thể nhận ra chính mình trong gương? Im Se Ra (Jang Da Ah thủ vai) là một ngôi sao đình đám, từng chạm đến đỉnh cao danh vọng. Thế nhưng, khi ánh hào quang vẫn đang rực rỡ, cô bất ngờ biến mất không dấu vết. Hai mươi lăm năm sau, Se Ra tỉnh dậy với một thân phận hoàn toàn xa lạ: một người phụ nữ trung niên mang tên Bong Cheong Ja (Uhm Jung Hwa thủ vai), không còn ký ức, không danh tiếng, thậm chí không còn biết mình là ai. Giữa một thế giới giải trí vốn khắc nghiệt với phụ nữ ngoài bốn mươi, cô không chỉ đối diện với nỗi sợ bị lãng quên mà còn phải học cách định nghĩa lại bản thân từ những mảnh vỡ của quá khứ.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 9, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Uhm Jung-hwa","avatar":""},{"name":"Song Seung-heon","avatar":""},{"name":"Lee El","avatar":""},{"name":"Oh Dae-hwan","avatar":""},{"name":"Jang Da-a","avatar":""},{"name":"Lee Min-jae","avatar":""},{"name":"Cha Chung-hwa","avatar":""},{"name":"Hyun Bong-sik","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["금쪽같은 내 스타"]', 1784690324146);
