INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giac-mo-nguoi-luat-su', 'Giấc Mơ Người Luật Sư', 'Beyond The Bar', 'https://phimimg.com/upload/vod/20250805-1/ad1fa9dca5dc55e80133c9653ffa3f37.jpg', 'https://phimimg.com/upload/vod/20250805-1/11331d30aec05eaaa914acb35d6b3a7e.jpg', '<p>Một luật sư trẻ mới vào nghề có tinh thần công lý mạnh mẽ gia nhập một hãng luật hàng đầu, xoay xở trong giới pháp lý phức tạp dưới sự dẫn dắt của người cố vấn lạnh lùng, khắt khe.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 11, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Jin-uk","avatar":""},{"name":"Jung Chae-yeon","avatar":""},{"name":"Jeon Hye-bin","avatar":""},{"name":"Lee Hak-ju","avatar":""},{"name":"Kang Sang-jun","avatar":""},{"name":"Kwon Ah-reum","avatar":""},{"name":"Kim Yeo-jin","avatar":""},{"name":"Hong Seo-jun","avatar":""},{"name":"Kim Kang-min","avatar":""},{"name":"Kil Eun-sung","avatar":""},{"name":"Lee Sang-yeob","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["梦想成为律师的律师们","Esquire","За пределами бара","محامون تحت التدريب","Esquire: Lawyers Dreaming of Becoming Lawyers","Esquire: Beyond The Bar","에스콰이어: 변호사를 꿈꾸는 변호사들"]', 1784690324146);
