INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('giac-mo-nguoi-luat-su', 'Giấc Mơ Người Luật Sư', 'Beyond The Bar', 'giấc mơ người luật sư beyond the bar lee jin-uk jung chae-yeon jeon hye-bin lee hak-ju kang sang-jun kwon ah-reum kim yeo-jin hong seo-jun kim kang-min kil eun-sung lee sang-yeob 梦想成为律师的律师们 esquire за пределами бара محامون تحت التدريب esquire: lawyers dreaming of becoming lawyers esquire: beyond the bar 에스콰이어: 변호사를 꿈꾸는 변호사들', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danh-sach-tu-thu-soi-hac-am', 'Danh Sách Tử Thù: Sói Hắc Ám', 'The Terminal List: Dark Wolf', 'https://phimimg.com/upload/vod/20250829-1/66364212e2c4d5d6bef202e4e9b86970.jpg', 'https://phimimg.com/upload/vod/20250829-1/023b33a57976df734f8fa62163ccf9c5.jpg', '<p>Trước sự kiện The Terminal List, đặc nhiệm SEAL Ben Edwards bị cuốn vào thế giới ngầm của các chiến dịch tuyệt mật CIA. Càng dấn sâu vào “vùng xám”, anh càng khó thoát khỏi bóng tối trong chính bản thân. Trong mỗi con người đều tồn tại hai con sói – ánh sáng và bóng tối – luôn tranh giành quyền kiểm soát. Ben Edwards sẽ nuôi dưỡng con sói nào?</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Taylor Kitsch","avatar":""},{"name":"Chris Pratt","avatar":""},{"name":"Tom Hopper","avatar":""},{"name":"Dar Salim","avatar":""},{"name":"Rona-Lee Shim''on","avatar":""},{"name":"Raha Rahbari","avatar":""},{"name":"LaMonica Garrett","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["终极名单：黑狼","The Terminal List: Dark Wolf เดอะ เทอร์มินอล ลิสต์: ดับมือสังหาร หมาป่าทมิฬ","The Terminal List: Dark Wolf"]', 1784690324146);
