INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('danh-sach-tu-thu-soi-hac-am', 'Danh Sách Tử Thù: Sói Hắc Ám', 'The Terminal List: Dark Wolf', 'danh sách tử thù: sói hắc ám the terminal list: dark wolf taylor kitsch chris pratt tom hopper dar salim rona-lee shim''on raha rahbari lamonica garrett 终极名单：黑狼 the terminal list: dark wolf เดอะ เทอร์มินอล ลิสต์: ดับมือสังหาร หมาป่าทมิฬ the terminal list: dark wolf', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thinh-doat', 'Thịnh Đoạt', 'Gilded Bond', 'https://phimimg.com/upload/vod/20250929-1/723b1ab56954948bcfea2ac90cec9774.jpg', 'https://phimimg.com/upload/vod/20250929-1/29a2ad99de3177cfc308bac1cc770393.jpg', '<p>Bộ phim kể về cuộc tranh đấu khốc liệt trong gia tộc giàu có bậc nhất Đông Nam Á – tập đoàn Thịnh Dã. Sau cái chết bí ẩn của người em trai Thịnh An, người thừa kế Thịnh Trạch trở về dự tang lễ và tin chắc rằng em mình bị hại bởi cô hầu gái thân cận Kiều Vãn. Anh thề phải đoạt lại quyền lực và trả thù. Trong khi đó, người đứng đầu gia tộc – Thịnh Hoài Cảnh cũng bắt đầu nghi ngờ, thử thách cậu cháu trai trở về với nhiều bí mật. Kiều Vãn có thực sự là kẻ được sai khiến để hại Thịnh An? Cái chết của Thịnh An rốt cuộc ẩn giấu sự thật gì? Một cuộc chiến gia tộc đầy âm mưu và phản bội, giằng co và đối kháng, khát vọng và dục vọng bùng nổ. Giữa vòng xoáy quyền lực, Kiều Vãn sẽ chọn phe nào? Và Thịnh Trạch liệu có thể thành công đoạt quyền?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Chính Dương","avatar":""},{"name":"Trương Hàn Văn","avatar":""},{"name":"Hà Trạch Viễn","avatar":""},{"name":"Châu Thư Du","avatar":""},{"name":"Thôi Trường Tồn","avatar":""},{"name":"Đậu Nghệ Khôn","avatar":""},{"name":"Vương Tố Thanh","avatar":""},{"name":"Bồi Thanh Hựu","avatar":""},{"name":"Trương Hân Nguyệt","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sheng Duo","盛夺"]', 1784690324146);
