INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thinh-doat', 'Thịnh Đoạt', 'Gilded Bond', 'thịnh đoạt gilded bond trần chính dương trương hàn văn hà trạch viễn châu thư du thôi trường tồn đậu nghệ khôn vương tố thanh bồi thanh hựu trương hân nguyệt sheng duo 盛夺', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-ve-chinh-dang', 'Phòng Vệ Chính Đáng', 'Justifiable Defense', 'https://phimimg.com/upload/vod/20250710-1/05a545819f31eca4a7dfea70639e0f7c.jpg', 'https://phimimg.com/upload/vod/20250710-1/f93e2e3eede1563b92728ebde9d63449.jpg', '<p>Công tố viên kỳ cựu của Viện Kiểm sát thành phố Đoàn Hồng Sơn được giao xử lý vụ án “người phụ nữ giết chồng do bị bạo hành gia đình”. Trong quá trình điều tra, anh được hỗ trợ bởi công tố viên trẻ của Viện Kiểm sát tỉnh Phương Linh Uyên. Trong quá trình hợp tác, hai người phát hiện vụ án hiện tại có liên quan chặt chẽ đến một vụ án xảy ra mười bốn năm trước mà Đoàn Hồng Sơn từng phụ trách: “Vụ án phòng vệ quá mức trong trường học” liên quan đến Lý Mộc Phong, Mai Tranh và Giang Đình. Dựa trên sự thật và nguyên tắc pháp luật, họ đã cùng nhau phân tích và cân nhắc kỹ lưỡng giữa “công lý, tình người và pháp luật”, từ đó đưa ra phán quyết công bằng và chuẩn xác cho vụ án.</p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 6, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Lỗ Dung","avatar":""},{"name":"Cao Diệp","avatar":""},{"name":"Bạch Kính Đình","avatar":""},{"name":"Trương Tân Nghị","avatar":""},{"name":"Diệp Thanh","avatar":""},{"name":"Trương Bác Giác","avatar":""},{"name":"Dương Khánh Y","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Zheng dang fang wei","正当防卫"]', 1784690324146);
