INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phong-ve-chinh-dang', 'Phòng Vệ Chính Đáng', 'Justifiable Defense', 'phòng vệ chính đáng justifiable defense trương lỗ dung cao diệp bạch kính đình trương tân nghị diệp thanh trương bác giác dương khánh y zheng dang fang wei 正当防卫', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuong-mien-cua-nguoi-thong-tri', 'Vương Miện Của Người Thống Trị', '9-nine- Ruler''s Crown', 'https://phimimg.com/upload/vod/20250924-1/9070d8830b4f120284821da47bea02cd.jpg', 'https://phimimg.com/upload/vod/20250924-1/ebde05dd60ca4cea04af92b49d85962a.jpg', '<p>“9-nine” kể về thị trấn Shiromitsugawa, nơi tồn tại những Cổ Vật bí ẩn ban cho Người Sở Hữu sức mạnh siêu nhiên. Câu chuyện xoay quanh sự gắn kết và tình yêu chớm nở giữa nam chính và nữ chính, đồng thời là hành trình truy tìm kẻ đứng sau hàng loạt vụ án mạng siêu nhiên.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Atsushi Abe","avatar":""},{"name":"Misato Fukuen","avatar":""},{"name":"Atsumi Tanezaki","avatar":""},{"name":"Yuri Yamaoka","avatar":""},{"name":"Akane Fujita","avatar":""},{"name":"Kazutomi Yamamoto","avatar":""},{"name":"Satomi Arai","avatar":""},{"name":"Hana Takeda","avatar":""},{"name":"Tomokazu Sugita","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["支配者的王冠","9-nine- Shihaisha no Oukan","ナイン ルーラーズクラウン","ナインしはいしゃのおうかん","アニメナイン","9-nine- Shihaisha no Ôkan","9-nine- 支配者の王冠","9-Nine Ruler''s Crown","9-nine- Ruler''s Crown"]', 1784690324146);
