INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vuong-mien-cua-nguoi-thong-tri', 'Vương Miện Của Người Thống Trị', '9-nine- Ruler''s Crown', 'vương miện của người thống trị 9-nine- ruler''s crown atsushi abe misato fukuen atsumi tanezaki yuri yamaoka akane fujita kazutomi yamamoto satomi arai hana takeda tomokazu sugita 支配者的王冠 9-nine- shihaisha no oukan ナイン ルーラーズクラウン ナインしはいしゃのおうかん アニメナイン 9-nine- shihaisha no ôkan 9-nine- 支配者の王冠 9-nine ruler''s crown 9-nine- ruler''s crown', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kien-tri-nhu-co-ay-di-tha-chi-nhan', 'Kiên Trì Như Cô Ấy (Dĩ Tha Chi Nhẫn)', 'Be Her Resilience', 'https://phimimg.com/upload/vod/20250914-1/a3f67e780262d67dbe192bb6a36522cd.jpg', 'https://phimimg.com/upload/vod/20250914-1/83d7a73e6d89c02206b283ed1d780a0a.jpg', '<p>Lấy bối cảnh tại Vân Thành thời Dân Quốc, câu chuyện xoay quanh hai chị em có thân thế khác biệt là Tống Gia Ngư và Hoắc Nhiễm, bị buộc cuốn vào vòng xoáy âm mưu gia tộc và phải vật lộn để sinh tồn. Từ đối đầu, hai người dần trở thành đồng minh, dùng mưu lược thương trường để đấu trí với thế lực hùng mạnh, dùng thủ đoạn giang hồ để từng bước phản kích. Cuối cùng, họ không chỉ vạch trần bộ mặt thật của người cha, mà còn giành lại gia sản do mẹ để lại, biến Hoắc trạch – nơi từng như ngục tù – thành trường học và bệnh viện cứu giúp phụ nữ. Bằng sức mạnh nữ giới, họ xé toang bóng tối, viết lại số phận trong ánh bình minh của thời đại mới.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Nhất Phi","avatar":""},{"name":"Bành Á Di","avatar":""},{"name":"Mã Tiểu Vũ","avatar":""},{"name":"Triệu Sùng Việt","avatar":""},{"name":"Vương Tân Chính","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["以她之韧"]', 1784690324146);
