INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('kien-tri-nhu-co-ay-di-tha-chi-nhan', 'Kiên Trì Như Cô Ấy (Dĩ Tha Chi Nhẫn)', 'Be Her Resilience', 'kiên trì như cô ấy (dĩ tha chi nhẫn) be her resilience vương nhất phi bành á di mã tiểu vũ triệu sùng việt vương tân chính 以她之韧', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-tham-thinh-the-thieu-nien', 'Đường Thám: Thịnh Thế Thiếu Niên', 'Tang Detective: The Broken Mirror Conspiracy', 'https://phimimg.com/upload/vod/20250923-1/d12da1b6628ce47e9e2d10a53d4bbcfe.jpg', 'https://phimimg.com/upload/vod/20250923-1/79a8c4a7fd9b9bbe6a3ad06fd14fe3a9.jpg', '<p>Câu chuyện diễn ra vào thời Đường Phong niên, xoay quanh một thiếu niên pháp quan tên là Vô Danh. Trong lúc phá án, cậu bị hiểu lầm là kẻ giết người và buộc phải tự chứng minh sự trong sạch của mình. Trên hành trình điều tra, Vô Danh vô tình bị cuốn vào vụ án “Huyết Đằng”, đồng hành cùng Lê Xung – một cao thủ võ nghệ, và Ngọc Kiếm Anh – thiếu nữ từ Tây Vực, tinh thông kỳ môn dị thuật. Ban đầu, cả ba người đề phòng, kiềm chế lẫn nhau. Nhưng trước những manh mối rối rắm, họ buộc phải tạm thời lập thành đội thám án. Qua nhiều hiểm nguy, từ đối địch rồi mỗi người mang một mục đích riêng, cuối cùng họ bỏ qua thành kiến, cùng nhau trưởng thành, giải khai chân tướng vụ án. Trong chuyến phiêu lưu đầy thăng trầm ấy, họ không chỉ tìm thấy chính mình mà còn kết giao được tri kỷ suốt đời.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Quản Lạc","avatar":""},{"name":"Vương Gia Ân","avatar":""},{"name":"Hạ Trần Nhất","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Tang Tan Zhi Sheng Shi Shao Nian","Tang Detective: The Prosperous Youth","唐探之盛世少年"]', 1784690324146);
