INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('the-gioi-khong-loi-thoat-phan-3', 'Thế Giới Không Lối Thoát (Phần 3)', 'Alice In Borderland (Season 3)', 'thế giới không lối thoát (phần 3) alice in borderland (season 3) kento yamazaki tao tsuchiya এলিস ইন বর্ডারল্যান্ড 今际之国的闯关者 彌留之國的愛麗絲 弥留之国的爱丽丝 alice in borderland η αλίκη στη χώρα των εσχάτων 今际之国的有栖 אליס בבורדרלנד آلیس در منطقه مرزی imawa no kuni no alice imawa no kuni no arisu 아리스 인 보더랜드 аліса в бордерленді аліса в ігрокраї ajal o''yini alisa chegara ortida thế giới không lối thoát 今際の国のアリス', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mogura-ke-lac-giua-hai-the-gioi', 'Mogura: Kẻ Lạc Giữa Hai Thế Giới', 'Dekin no Mogura: The Earthbound Mole', 'https://phimimg.com/upload/vod/20250720-1/0ce49f4215379d6ed0c089139384c253.jpg', 'https://phimimg.com/upload/vod/20250720-1/5c7d38415518f4825d9fb35286124aae.jpg', '<p>Một kẻ tự xưng là ẩn sĩ mờ ám tên là Momoyuki Mogura, hay còn gọi là Mogura, đã bị cấm bước vào cõi âm do một sự cố trong quá khứ. Giờ đây, hắn thu thập những linh hồn bị ám trong các đốm lửa ma trơi và nhốt chúng trong chiếc đèn lồng của mình, với hy vọng có thể trở lại một lần nữa.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuichi Nakamura","avatar":""},{"name":"Genki Okawa","avatar":""},{"name":"Yukiyo Fujii","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["禁止入內的鼹鼠","出入 禁止的鼹鼠","Dekin no Mogura","الخلد المرتبط بالأرض","出入禁止的鼴鼠","The Banned Mole","The Banned Mogura","The Forbidden Mole","出禁のモグラ"]', 1784690324146);
