INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khach-san-inhumans', 'Khách Sạn Inhumans', 'Hotel Inhumans', 'https://phimimg.com/upload/vod/20250711-1/111b2b7653d7ff5fa530f96d73fb84a0.jpg', 'https://phimimg.com/upload/vod/20250711-1/6e2b103940b09203fab8a79e53565d33.jpg', '<p>Các khách sạn tốt nhất phải đáp ứng một số tiêu chuẩn nhất định, bao gồm ẩm thực hảo hạng, các phương pháp thư giãn và giải trí. Tất nhiên, chúng cũng cần có kho vũ khí tốt nhất, cách làm giả danh tính đáng tin cậy và phương thức phi tang bằng chứng. Tại một khách sạn nằm ở ranh giới giữa sự sống và cái chết, có hai nhân viên lễ tân là Ikuro Hoshi và Sara Haizaki. Những sát thủ sẽ đưa ra yêu cầu gì cho họ tiếp theo?</p>', 'Tập 13', 24, 'hoathinh', 'ongoing', 6, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yusuke Kobayashi","avatar":""},{"name":"Hinano Shirahama","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["异人旅馆","杀手旅店","ホテル・インヒューマンズ","فندق اللابشريين","فندق غير الآدميين","فندق اللاإنسانيين"]', 1784690324146);
