INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-hon-nhan-cua-ho', 'Cuộc Hôn Nhân Của Họ', 'Their Marriage', 'https://phimimg.com/upload/vod/20250725-1/3a888b101d040ad32a695dd47068395c.jpg', 'https://phimimg.com/upload/vod/20250725-1/70f6251bb620af4a40c65fcf8bc508c8.jpg', '<p>Sau nhiều năm sống cô độc, luật sư nọ tìm được tri kỷ là một giáo viên mỹ thuật. Nhưng đằng sau mối quan hệ bình yên ấy là một bí mật có thể thay đổi mọi chuyện.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Sadawo Abe","avatar":""},{"name":"Takako Matsu","avatar":""},{"name":"Rihito Itagaki","avatar":""},{"name":"Yasunori Danta","avatar":""},{"name":"Takashi Okabe","avatar":""},{"name":"Reo Tamaoki","avatar":""},{"name":"Satoshi Kanada","avatar":""},{"name":"Toru Baba","avatar":""},{"name":"Nagiko Tsuji","avatar":""},{"name":"Yosuke Sugino","avatar":""},{"name":"Keiko Horiuchi","avatar":""},{"name":"Kazushige Komatsu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shiawasena Kekkon","Their.Marriage","しあわせな結婚"]', 1784690324146);
