INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khai-huyen-di-gioi-mynoghra-chinh-phuc-the-gioi-tu-nen-van-minh-suy-tan', 'Khải Huyền Dị Giới Mynoghra: Chinh Phục Thế Giới Từ Nền Văn Minh Suy Tàn', 'Apocalypse Bringer Mynoghra: World Conquest Starts with the Civilization of Ruin', 'https://phimimg.com/upload/vod/20250714-1/33d8913b363b40d5005f5fbf551e6bd9.jpg', 'https://phimimg.com/upload/vod/20250714-1/6cf3d03b7c9db021ff2d5f9d238bdff5.jpg', '<p>Trong Eternal Nations, một trò chơi chiến lược giả tưởng nơi người chơi quản lý một đế chế, Takuto Ira là một người chơi huyền thoại đứng đầu bảng xếp hạng. Takuto bất tỉnh trong thời gian nằm viện và tỉnh dậy trên lục địa Idoragya, trông giống hệt như trong trò chơi. Takuto gặp Sludge Atou, đơn vị yêu thích của anh trong trò chơi, và quyết định xây dựng Mynoghra, một đế chế độc ác.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Toshiki Kumagai","avatar":""},{"name":"Tomori Kusunoki","avatar":""},{"name":"Kikuko Inoue","avatar":""},{"name":"Rico Sasaki","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["异世界默示录米诺戈拉 ～从灭亡的文明开始的世界征服～","异世界默示录麦诺格拉","异世界默示录米诺戈拉～从灭亡的文明开始的世界征服～","异世界默示录麦诺格拉～从毁灭文明开始征服世界～","異世界默示錄麥諾格拉～從毀滅文明開始征服世界～","异世界默示录麦诺格拉͏～从毁灭文明开始征服世界～","Mynoghra - Annonciateur de l''Apocalypse","Isekai Mokushiroku Mynoghra ~Hametsu no Bunmei de Hajimeru Sekai Seifuku~","異世界黙示録マイノグーラ","マイノグーラ","Isekai Mokushiroku Mynoghra","Isekai Mokushiroku Mynoghra Hametsu no Bunmei de Hajimeru Sekai Seifuku","마이노그라","Apocalypse Bringer Mynoghra: World Conquest Starts with the Civilization of Ruin","I Reincarnated As The Evil God Of My Favorite Civilization","Mynoghra","Khải Huyền Dị Giới Mynoghra: Chinh Phục Thế Giới Từ Nền Văn Minh Suy Tàn","Khải Huyền Dị Giới Mynoghra","異世界黙示録マイノグーラ ～破滅の文明で始める世界征服～"]', 1784690324146);
