INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nua-thanh-gio-trang-nua-thanh-tuyet', 'Nửa Thành Gió Trăng Nửa Thành Tuyết', 'Between Love And Frost', 'https://phimimg.com/upload/vod/20250917-1/512cb72f5ace7334b28b48e7d3652f3f.jpg', 'https://phimimg.com/upload/vod/20250917-1/b147252a33aeaec3f9767436519561f3.jpg', '<p>Sở Minh Huy bị cha dượng - một gã &quot;phượng hoàng nam&quot; cướp đoạt tài sản, tàn sát cả gia đình. May mắn thoát chết, cô thay tên đổi họ lên kế hoạch báo thù. Để trả thù cha dượng, cô đã ký hợp đồng giả làm người yêu của đại thiếu soái, giúp hắn ám sát em trai - Cố Đồng Bái. Qua nhiều lần đối đầu, mối tình cấm kỵ &quot;chị dâu - em chồng&quot; nảy sinh. Khi Sở Minh Huy báo thù thành công, người yêu lại trở thành kẻ thù. Trải qua bao phen sóng gió, cuối cùng hai người đã tháo gỡ hiểu lầm, chung tay trừng trị kẻ chủ mưu thực sự, chính là đại thiếu soái.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hàn Lệ Dao","avatar":""},{"name":"Vương Tuấn Hạo","avatar":""},{"name":"Lý Diên Phong","avatar":""},{"name":"Trác Nghệ Trần","avatar":""},{"name":"Trương Tế","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ban Cheng Feng Yue Ban Cheng Xue","半城风月半城雪"]', 1784690324146);
