INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nua-thanh-gio-trang-nua-thanh-tuyet', 'Nửa Thành Gió Trăng Nửa Thành Tuyết', 'Between Love And Frost', 'nửa thành gió trăng nửa thành tuyết between love and frost hàn lệ dao vương tuấn hạo lý diên phong trác nghệ trần trương tế ban cheng feng yue ban cheng xue 半城风月半城雪', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-nghia-hiep-2025', 'Bác Sĩ Nghĩa Hiệp', 'Heroes In White', 'https://phimimg.com/upload/vod/20250925-1/f2cb7efbeb0756d7a7776d6ec5053983.jpg', 'https://phimimg.com/upload/vod/20250925-1/6e2b48b9fd8c028f07d7f4ddef10c435.jpg', '<p>Bộ phim kể về Lăng Vi Dân (Trần Hào), một bác sĩ Đông y chính trực, giàu lòng nhân ái, quyết tâm chứng minh giá trị y học cổ truyền giữa thời đại hiện đại. Sau khi rời khỏi xưởng thuốc gia tộc, anh lập nên thương hiệu Mạch Mạch Thông để giúp đỡ người nghèo và truyền bá y lý từ &quot;Hoàng Đế Nội Kinh&quot;. Anh gặp và chữa trị cho La Dĩnh Thâm (Trương Hy Văn), từ đó nảy sinh tình cảm. Tuy nhiên, mối quan hệ này gây nên sự ghen tuông từ Thẩm Ỷ Đình (Lưu Bội Nguyệt), người bạn thân của Dĩnh Thâm, cũng là &quot;tiểu tam&quot; trong gia đình Vi Dân. Bị vây quanh bởi thù hận và âm mưu từ người thân, Vi Dân cùng Dĩnh Thâm kiên trì vượt qua thử thách, bảo vệ niềm tin vào Đông y.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 8, 2025, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Trần Hào","avatar":""},{"name":"Trương Hy Văn","avatar":""},{"name":"Đinh Tử Lãng","avatar":""},{"name":"Đàm Khải Kỳ","avatar":""},{"name":"Lưu Bội Nguyệt","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["俠醫"]', 1784690324146);
