INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-so-8-phan-2', 'Quái Vật Số 8 (Phần 2)', 'Kaiju No. 8 (Season 2)', 'https://phimimg.com/upload/vod/20250707-1/cf9ab616a9d2dc2c7bf4ad3121c639e2.jpg', 'https://phimimg.com/upload/vod/20250707-1/0e2c976cd696d8dd2a37878bc0f3a703.jpg', '<p>Những con &quot;kaiju&quot; (quái vật khổng lồ) bất ngờ xuất hiện và hoành hành khắp Nhật Bản trong nhiều năm. Một đơn vị tinh nhuệ được gọi là Quân đoàn Phòng vệ phải liều mạng hàng ngày để bảo vệ dân thường. Anh chàng Kafka Hibino mang ước mơ gia nhập Quân đoàn từ nhỏ nhưng lại bị dòng đời đưa đẩy, phải làm công việc chuyên xử lý xác quái vật. Sau một tai nạn kỳ lạ, anh có được khả năng biến hình, được mệnh danh là &quot;Kaiju số 8&quot;. Từ đây, Kafka bắt đầu hiện thực hóa ước mơ thuở nhỏ của mình, gia nhập Quân đoàn và giấu kín năng lực vừa có được.</p>', 'Tập 12', 24, 'hoathinh', 'ongoing', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["怪兽八号","怪兽8号","怪獸8號","aiju.No.8","Kaijuu 8-gou","Kaijū 8-gō","Kaiju No.Eight","Kaijuu 8 gou","괴수8호","Кайдзю номер восемь","怪獸 8 號","Monster #8","Kaiju No.8","Quái Vật Số 8","怪獣８号"]', 1784690324147);
