INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-thuc-cua-fermat-2025', 'Ẩm Thực Của Fermat', 'Fermat Kitchen', 'https://phimimg.com/upload/vod/20250809-1/11241adf1cd1a214b3771f9daf4fd202.jpg', 'https://phimimg.com/upload/vod/20250809-1/2e4374d04dd7358c6572bb339aa39fa1.jpg', '<p>Từng nuôi mộng chinh phục thế giới bằng toán học, Kitada Gaku giờ đây sống vô định sau khi đánh mất ước mơ. Cho đến khi một đầu bếp bí ẩn xuất hiện, kéo cậu vào hành trình nơi toán học và ẩm thực giao thoa, mở ra một thế giới mới đầy cảm hứng và bất ngờ.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ryosuke Tomita","avatar":""},{"name":"Taito Ban","avatar":""},{"name":"Daichi Endo","avatar":""},{"name":"Takuma Nagatsuka","avatar":""},{"name":"Natsu Yorita","avatar":""},{"name":"Haruna Ikezawa","avatar":""},{"name":"Tatsumaru Tachibana","avatar":""},{"name":"Makoto Furukawa","avatar":""},{"name":"Shion Wakayama","avatar":""},{"name":"Anna Nagase","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["费马的料理","Fermat’s Cuisine","Fermat no Ryori","Fermat no Ryouri","Fermat no Ryōri","Fermat no Ryouri (2025)","페르마의 요리 (2025)","페르마의 요리","Fermat''s Cuisine","Fermat no Ryouri Anime (2025)","フェルマーの料理"]', 1784690324147);
