INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anne-shirley', 'Anne Shirley', 'Anne Shirley', 'https://phimimg.com/upload/vod/20250419-1/4cbb90dddd3cd910557154e055a8e44b.jpg', 'https://phimimg.com/upload/vod/20250419-1/c3d8cc4c8e6f1aa4f343edd0ebe02e3c.jpg', '<p>Từ trại trẻ mồ côi đến ngôi nhà Cuthbert, cuộc đời Anne Shirley, cô bé 11 tuổi đầy cá tính, rẽ sang một trang mới đầy bất ngờ. Marilla và Matthew tìm kiếm một cậu bé, nhưng lại nhận được Anne, một cô bé với trí tưởng tượng vô bờ. Anne Shirley không chỉ là câu chuyện về tuổi thơ, mà còn là hành trình trưởng thành đầy cảm xúc, nơi những cuộc gặp gỡ và chia ly định hình số phận. Liệu Anne sẽ viết nên câu chuyện cuộc đời mình như thế nào?</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Honoka Inoue","avatar":""},{"name":"Aya Nakamura","avatar":""},{"name":"Yasunori Matsumoto","avatar":""},{"name":"Naoya Miyase","avatar":""},{"name":"Yume Miyamoto","avatar":""},{"name":"Hikari Ota","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["新 红发少女安妮","Akage no Anne","Anne Shirley","赤毛のアン","An Shārī","Энн Ширли","Anne of Green Gables","アン・シャーリー"]', 1784690324147);
