INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-thang-tu-mang-toi-hoa-thang-nam-busu-ni-hanataba-wo', 'Mưa Tháng Tư Mang Tới Hoa Tháng Năm (Busu ni Hanataba wo)', 'April Showers Bring May Flowers', 'https://phimimg.com/upload/vod/20250927-1/873dfaaa309218ea2c5e91738fca5d21.jpg', 'https://phimimg.com/upload/vod/20250927-1/521a963c89c33f98521570ca245f3bfb.jpg', '<p>Bộ phim kể về hành trình trưởng thành của những người trẻ khi mùa mưa tháng Tư mang theo những ký ức, day dứt và cả nỗi đau cũ. Trong cơn mưa ấy, họ tìm thấy sự chữa lành, học cách tha thứ cho quá khứ và dũng cảm đối diện với tình yêu, giống như những bông hoa tháng Năm nở rộ sau mưa, mang đến hy vọng và khởi đầu mới.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Saori Hayami","avatar":""},{"name":"Shimba Tsuchiya","avatar":""},{"name":"Yoshino Aoyama","avatar":""},{"name":"Yoshimasa Hosoya","avatar":""},{"name":"Tasuku Hatanaka","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Un ramo de flores para la chica fea.","为丑女献上花束。","为丑女献上花束","Busu ni Hanataba wo.","Busu ni Hanataba o.","A Bouquet for an Ugly Girl","April Showers Bring Forth May Flowers","ブスに花束を。"]', 1784690324147);
