INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chihayafuru-vong-lap-moi', 'Chihayafuru: Vòng Lặp Mới', 'Chihayafuru: Full Circle', 'https://phimimg.com/upload/vod/20250725-1/bff850e475a8d48aa180a6e74e4fbaa6.jpg', 'https://phimimg.com/upload/vod/20250725-1/c1b71599cabd1fb346f29a0a1b1d62ef.jpg', '<p>Meguru, nữ sinh năm hai trung học, chỉ muốn tập trung cho tương lai. Thế nhưng khi bị buộc phải tham gia câu lạc bộ Karuta đầy cạnh tranh của trường, cô bỗng tìm được đam mê mới.</p>', 'Tập 10', 12, 'series', 'ongoing', 12, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ami Touma","avatar":""},{"name":"Jun Saitō","avatar":""},{"name":"Soma Santoki","avatar":""},{"name":"Lina Arashi","avatar":""},{"name":"Kaito Takamura","avatar":""},{"name":"Manato Sakamoto","avatar":""},{"name":"Mone Kamishiraishi","avatar":""},{"name":"Nanoka Hara","avatar":""},{"name":"Taiyu Fujiwara","avatar":""},{"name":"Raizou Ishikawa","avatar":""},{"name":"Seto Kotoka","avatar":""},{"name":"Takahashi Yutaro","avatar":""},{"name":"Riku Onishi","avatar":""},{"name":"Yuki Tachibana","avatar":""},{"name":"Fujieda Yoshiki","avatar":""},{"name":"Kazuki Ōtomo","avatar":""},{"name":"Urushiyama Takum","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["ちはやふる－めぐり－"]', 1784690324147);
