INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('boys-ii-planet', 'Boys II Planet', 'Boys II Planet', 'https://phimimg.com/upload/vod/20250720-1/fd1e6542bea919df388eb257aace59cd.jpg', 'https://phimimg.com/upload/vod/20250720-1/dd6bd15dfe49187018cdded46342cb22.jpg', '<p>Nơi năng lượng tuyệt vời của 154 chàng trai hội tụ cùng sự vận hành song song của Planet K (Hàn Quốc) và Planet C (Trung Quốc), Boys II Planet sẽ kiến tạo nên một nhóm nhạc thần tượng toàn cầu thế hệ mới. Đặng Hồng Hải - thực tập sinh đến từ Việt Nam mang đến một visual bừng sáng và đầy sự quyết tâm, liệu cậu có giành được cơ hội debut?</p>', 'Hoàn Tất (13/13)', 13, 'tvshows', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Seok Hoon","avatar":""},{"name":"Kim Jae Joong","avatar":""},{"name":"Hyolyn","avatar":""},{"name":"Kany Diabate","avatar":""},{"name":"Im Han Byul","avatar":""},{"name":"Xiaoting (Kep1er)","avatar":""},{"name":"Justhis","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '["ボイプラ","플래닛 B","Planet B","보이즈 2 플래닛"]', 1784690324147);
