INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-sung', 'Tiên Sủng', 'Celestial Bonds', 'https://phimimg.com/upload/vod/20250614-1/b92183b741b237dd4227ff358361da51.jpg', 'https://phimimg.com/upload/vod/20250614-1/06713b7378411d0836c6c774924f84cd.jpg', '<p>Một trăm năm trước, Tiên nữ Thiên Quyển đã chém Thận quân khiến Thận yêu biến mất khỏi Thương Sóc, nhưng cô cũng mất đi ký ức về trận chiến. Sau chiến tranh, Thiên Quyển hạ phàm làm Thổ Địa, nuôi chim Ly Kiêu — sinh vật hóa thành người với dung mạo giống người tình đã khuất Thiệu Vị Ly. Khi Ly Kiêu đi khỏi nhiều ngày, Thiên Quyển đến trấn La Y và phát hiện toàn bộ dân làng bị sát hại, Thận yêu tái xuất hiện. Thiên Quyển cùng Ly Kiêu hợp lực chống lại yêu quái, giải cứu trấn La Y. Trong lúc ký ức dần hồi phục, Thiên Quyển nhận ra mối liên hệ sâu sắc giữa Thiệu Vị Ly, Ly Kiêu và Thận quân mà cô từng giết.</p>', 'Hoàn Tất (18/18)', 18, 'hoathinh', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Liu Xiaoyu","avatar":""},{"name":"Qian Chen","avatar":""},{"name":"Liu Sanmu","avatar":""},{"name":"Yang Kaiqi","avatar":""},{"name":"Ajie","avatar":""},{"name":"Chen Zhangtaikang","avatar":""},{"name":"Shuang Zhao","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["仙宠奶凶","Xian Chong","Xian Chong Nai Xiong","Celestial Bonds","仙宠"]', 1784690324147);
