INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sinh-van-vat', 'Sinh Vạn Vật', 'This Thriving Land', 'https://phimimg.com/upload/vod/20250814-1/373d5e4b63dee75d176a7dcf01e27770.jpg', 'https://phimimg.com/upload/vod/20250814-1/8cba7eab03986a60779e8615d70a2e9b.jpg', '<p>Bộ phim kể về câu chuyện tại vùng nông thôn Lỗ Nam, khắc họa hành trình biến động của mảnh đất và số phận con người trong giai đoạn lịch sử đầy sóng gió. Trọng tâm là câu chuyện trưởng thành đầy nghị lực của người phụ nữ, xen lẫn những mối tình sâu nặng, tạo nên bản anh hùng ca xúc động về tình yêu và lòng kiên cường. Giữa ách thống trị phong kiến khắc nghiệt, những người nông dân vật lộn từng ngày để sinh tồn, để vươn lên tìm ánh sáng tự do. Nhưng trên hết, phim đặc biệt khắc họa mối gắn bó máu thịt giữa con người và mảnh đất quê hương – thứ tình cảm thiêng liêng truyền từ thế hệ này sang thế hệ khác, như một lời thề không bao giờ dứt.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 12, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Gia Thành","avatar":""},{"name":"Dương Mịch","avatar":""},{"name":"Âu Hào","avatar":""},{"name":"Nê Đại Hồng","avatar":""},{"name":"Tần Hải Lộ","avatar":""},{"name":"Hành Phi","avatar":""},{"name":"Trương Thiên Dương","avatar":""},{"name":"Trương Hải Vũ","avatar":""},{"name":"Trì Mộng","avatar":""},{"name":"Lâm Vĩnh Kiện","avatar":""},{"name":"Lam Doanh Doanh","avatar":""},{"name":"Tạ Trạch","avatar":""},{"name":"Phan Chi Lâm","avatar":""},{"name":"Vu Trấn","avatar":""},{"name":"Thẩm Đan Bình","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee6