INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phon-hoan', 'Phồn Hoan', 'Lust And Lies', 'https://phimimg.com/upload/vod/20250918-1/1680349e9e930cd309f55f2c55ae543a.jpg', 'https://phimimg.com/upload/vod/20250918-1/90dc8152c348edd33489bc802021a189.jpg', '<p>Nguyễn Phi Phi là một cô gái lang bạt đầu đường xó chợ, do một sự nhầm lẫn đã thay thế đào hát nổi danh bước vào nhà họ Hoắc, trở thành cô chủ hào môn Hoắc Thanh Uyển, phải đọ sức với nhiều thế lực để trả thù, đồng thời cũng bước vào một mối tình rối ren, đan xen ân oán hào môn với thiếu soái ngang ngược Hoắc Tu.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Kha Dĩnh","avatar":""},{"name":"Trương Đình Duệ","avatar":""},{"name":"Giang Vũ Thuận","avatar":""},{"name":"Lê Vân","avatar":""},{"name":"Hà Diệc Khả","avatar":""},{"name":"Tư Lực Canh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Fan Huan","替弈","繁欢"]', 1784690324147);
