INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phon-hoan', 'Phồn Hoan', 'Lust And Lies', 'phồn hoan lust and lies kha dĩnh trương đình duệ giang vũ thuận lê vân hà diệc khả tư lực canh fan huan 替弈 繁欢', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-phap-su-thuoc-tinh-nuoc-mizu-zokusei-no-mahoutsukai', 'Ma Pháp Sư Thuộc Tính Nước (Mizu Zokusei no Mahoutsukai)', 'The Water Magician', 'https://phimimg.com/upload/vod/20250715-1/9c7ed7ed476d1ca7ebcab80ae9d2cd1c.jpg', 'https://phimimg.com/upload/vod/20250715-1/a48b2bdf0d07db4cb473ec345888eb0b.jpg', '<p>Sau khi qua đời và được chuyển sinh sang thế giới khác, chàng trai tên Ryō bắt đầu cuộc sống mới với phép thuật nước đơn giản:

“Nước ơi, hãy đến!”

Tưởng rằng sẽ có một cuộc sống nhàn hạ, bình yên kiểu &quot;slow life&quot;, nhưng thực tế lại hoàn toàn ngược lại. Ryō là con người duy nhất sống ở một vùng đất biệt lập – lục địa Rondo – nơi đầy rẫy quái vật nguy hiểm và chiến đấu chết người xảy ra như cơm bữa.

Dù gặp phải kỵ sĩ không đầu, chim sát thủ, hay cả rồng, Ryō vẫn sống ung dung như chẳng có gì. Phải chăng là vì cậu có tính cách vô tư... hay là nhờ kỹ năng bí mật “bất lão”, không hề già đi suốt hàng chục năm?

Cứ thế, 20 năm trôi qua, Ryō – từ một người bình thường – đã trở thành pháp sư nước mạnh nhất loài người lúc nào không hay.

Mọi chuyện bắt đầu thay đổi khi cậu gặp Abel, một kiếm sĩ thiên tài. Cuộc gặp gỡ ấy kéo Ryō ra khỏi cuộc sống ẩn dật và bước vào trung tâm lịch sử của thế giới.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ayumu Murase","avatar":""},{"name":"Kazuki Ura","avatar":""},{"name":"Kaede Hondo","avatar":""},{"name":"Genki Muro","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["水属性的魔法使","水属性魔法使","水属性的魔法师","みずぞくせいのまほうつかい","水属性","Mizu Zokusei no Mahou Tsukai","Mizuzokusei no Mahōtsukai","Mizuzokusei no Mahoutsukai","มิซึโซคุเซ โนะ มาโฮสึไก","Ma Pháp Sư Thuộc Tính Nước","Thủy Ma Pháp Sư","水属性の魔法使い"]', 1784690324147);
