INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ma-phap-su-thuoc-tinh-nuoc-mizu-zokusei-no-mahoutsukai', 'Ma Pháp Sư Thuộc Tính Nước (Mizu Zokusei no Mahoutsukai)', 'The Water Magician', 'ma pháp sư thuộc tính nước (mizu zokusei no mahoutsukai) the water magician ayumu murase kazuki ura kaede hondo genki muro 水属性的魔法使 水属性魔法使 水属性的魔法师 みずぞくせいのまほうつかい 水属性 mizu zokusei no mahou tsukai mizuzokusei no mahōtsukai mizuzokusei no mahoutsukai มิซึโซคุเซ โนะ มาโฮสึไก ma pháp sư thuộc tính nước thủy ma pháp sư 水属性の魔法使い', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duoi-theo-canh-buom-truy-diep', 'Đuổi Theo Cánh Bướm (Truy Điệp)', 'Chasing Butterfly', 'https://phimimg.com/upload/vod/20250924-1/3280b79c317562cbd2e61a18997bcc6e.jpg', 'https://phimimg.com/upload/vod/20250924-1/57b503eff6b1061ec60e41b51799ad3d.jpg', '<p>Lâm Du và Đinh Sùng Hy từ thời cấp ba đã mang mối tình mập mờ cho đến khi vào đại học. Một vụ tai nạn giao thông khiến Lâm Du rơi vào hôn mê bất tỉnh. Đinh Sùng Hy đã dùng trí tuệ nhân tạo để tải ý thức của cô vào thế giới ảo, hy vọng có thể thông qua việc tạo mộng mà đánh thức cô dậy. Trong thế giới ảo, anh nhiều lần gặp lại Lâm Du dưới vai trò người dẫn đường. Thế nhưng, Lâm Du liên tục chạm phải những ký ức đau thương, khiến kịch bản trong thế giới ảo nhiều lần sụp đổ. Khi thể trạng Lâm Du dần cạn kiệt, định mệnh đã an bài hai người phải chia xa vĩnh viễn. Trước lúc ra đi, Lâm Du lần lượt nói lời tạm biệt với những người mình từng yêu thương.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wang Xingwei","avatar":""},{"name":"Gong Fangni","avatar":""},{"name":"Jin Pengbo","avatar":""},{"name":"Peng Yihang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Zhui Die","追蝶"]', 1784690324147);
