INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pho-son-hai', 'Phó Sơn Hải', 'The Journey Of Legend', 'https://phimimg.com/upload/vod/20250911-1/99573d009a71f055ea5708a547b7f959.jpg', 'https://phimimg.com/upload/vod/20250911-1/73625f73aeb9ce7e396f796b994b684a.jpg', '<p>Bộ phim kể về Tiêu Minh Minh, một chàng trai từng say mê tiểu thuyết võ hiệp nhưng bị hiện thực làm mai một đi nhiệt huyết. Qua góc nhìn của nhân vật chính Tiêu Thu Thủy trong tiểu thuyết, anh có cơ hội trải nghiệm thế giới võ lâm. Từ một thiếu niên kiếm khách non nớt, bồng bột và có võ công thấp kém, anh dần trưởng thành, trở thành một đại hiệp có nghĩa khí, sẵn sàng bảo vệ gia đình và đất nước. Sau hành trình này, Tiêu Minh Minh tiếp tục sáng tác trong thời gian rảnh rỗi, gửi gắm niềm tin vào tinh thần nghĩa hiệp trong từng trang sách.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 16, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Thành Nghị","avatar":""},{"name":"Cổ Lực Na Trát","avatar":""},{"name":"Lý Khải Hinh","avatar":""},{"name":"Trương Trí Lâm","avatar":""},{"name":"Từ Chấn Hiên","avatar":""},{"name":"Lữ Tụng Hiền","avatar":""},{"name":"Trần Ngọc Kỳ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["神州奇侠","Fu Shan Hai","부산해 : 신주기협","สู่ภูผามหาสมุทร","Go to the Mountains and Sea","The Journey of Legend","赴山海"]', 1784690324147);
