INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('pho-son-hai', 'Phó Sơn Hải', 'The Journey Of Legend', 'phó sơn hải the journey of legend thành nghị cổ lực na trát lý khải hinh trương trí lâm từ chấn hiên lữ tụng hiền trần ngọc kỳ 神州奇侠 fu shan hai 부산해 : 신주기협 สู่ภูผามหาสมุทร go to the mountains and sea the journey of legend 赴山海', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-ngan-han-dau-dai-lau', 'Yêu Ngắn Hạn, Đau Dài Lâu', 'Oh, Hi!', 'https://phimimg.com/upload/vod/20250926-1/1c32ced99f979185a8cb35aea06bf212.jpg', 'https://phimimg.com/upload/vod/20250926-1/9f90364d908e02249407dbc133320ce1.jpg', '<p>Chuyến du lịch cuối tuần của Iris và Isaac vốn lãng mạn và vui vẻ, đến khi Iris bắt đầu có những hành động và suy nghĩ phi lý trí để chứng minh cho Isaac thấy họ là định mệnh của nhau.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Molly Gordon","avatar":""},{"name":"Logan Lerman","avatar":""},{"name":"Geraldine Viswanathan","avatar":""},{"name":"John Reynolds","avatar":""},{"name":"David Cross","avatar":""},{"name":"Polly Draper","avatar":""},{"name":"Desmin Borges","avatar":""},{"name":"Diana Irvine","avatar":""},{"name":"Jimmy Gary Jr.","avatar":""},{"name":"Ruben Ortiz","avatar":""},{"name":"Tabitha Lawing","avatar":""},{"name":"Sabina Friedman-Seitz","avatar":""},{"name":"Jessie Nelson","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["אה, היי!","噢，嗨！","Ah, Oi!","Ehi Tu","Oh, Hi!"]', 1784690324147);
