INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('yeu-ngan-han-dau-dai-lau', 'Yêu Ngắn Hạn, Đau Dài Lâu', 'Oh, Hi!', 'yêu ngắn hạn, đau dài lâu oh, hi! molly gordon logan lerman geraldine viswanathan john reynolds david cross polly draper desmin borges diana irvine jimmy gary jr. ruben ortiz tabitha lawing sabina friedman-seitz jessie nelson אה, היי! 噢，嗨！ ah, oi! ehi tu oh, hi!', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sap-toang', 'Sắp Toang', 'Splitsville', 'https://phimimg.com/upload/vod/20250926-1/72448775b3d76e82883a7bef20e34f6c.jpg', 'https://phimimg.com/upload/vod/20250926-1/788d18b2e0ba6b031697c6c4669420fd.jpg', '<p>Sau khi Ashley đòi ly hôn, Carey – một anh chàng hiền lành – tìm đến vợ chồng bạn thân Julie và Paul để nương tựa. Nhưng anh sững sờ khi phát hiện bí mật giữ cho hôn nhân của họ bền chặt lại là một cuộc hôn nhân mở. Và rồi, chỉ một bước lỡ giới hạn, Carey đã đẩy cả ba người vào trạng thái sắp toang đến nơi rồi.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dakota Johnson","avatar":""},{"name":"Adria Arjona","avatar":""},{"name":"Kyle Marvin","avatar":""},{"name":"Michael Angelo Covino","avatar":""},{"name":"Simon Webster","avatar":""},{"name":"Charlie Gillespie","avatar":""},{"name":"David Castañeda","avatar":""},{"name":"O-T Fagbenle","avatar":""},{"name":"Nahéma Ricci","avatar":""},{"name":"Tyrone Benskin","avatar":""},{"name":"Nicholas Braun","avatar":""},{"name":"Leo Hennely","avatar":""},{"name":"Robin Guillen","avatar":""},{"name":"Letitia Brookes","avatar":""},{"name":"Tyler Hall","avatar":""},{"name":"Emily O''Connor","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Amores Compartidos","Avatud abielu","Libre échange","Páratlan párosok","Skomplikowani","Нескромные","طلاقستان","Splitsville: Una comedia poco romántica","Splitsville"]', 1784690324147);
