INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sap-toang', 'Sắp Toang', 'Splitsville', 'sắp toang splitsville dakota johnson adria arjona kyle marvin michael angelo covino simon webster charlie gillespie david castañeda o-t fagbenle nahéma ricci tyrone benskin nicholas braun leo hennely robin guillen letitia brookes tyler hall emily o''connor amores compartidos avatud abielu libre échange páratlan párosok skomplikowani нескромные طلاقستان splitsville: una comedia poco romántica splitsville', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-he-kinh-hai-4', 'Mùa Hè Kinh Hãi 4', 'I Know What You Did Last Summer', 'https://phimimg.com/upload/vod/20250829-1/6b3fb8f651c92b770f28457792ac1975.jpg', 'https://phimimg.com/upload/vod/20250827-1/b0758e7f29f882d1ffe62affef852ce8.jpg', '<p>Khi năm người bạn vô tình gây ra một vụ tai nạn xe hơi chết người, họ quyết định che giấu và lập một giao ước giữ bí mật thay vì phải đối mặt với hậu quả. Một năm sau, quá khứ trở lại ám ảnh họ, buộc họ phải đối diện với một sự thật khủng khiếp: có ai đó biết những gì họ đã làm vào mùa hè năm ngoái… và quyết tâm trả thù họ. Khi từng người trong nhóm bị một kẻ sát nhân truy đuổi, họ phát hiện ra rằng điều này đã xảy ra trước đây, và họ tìm đến hai người sống sót từ vụ thảm sát huyền thoại ở Southport năm 1997 để cầu cứu.</p>', 'Full', 1, 'single', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Madelyn Cline","avatar":""},{"name":"Chase Sui Wonders","avatar":""},{"name":"Jonah Hauer-King","avatar":""},{"name":"Tyriq Withers","avatar":""},{"name":"Sarah Pidgeon","avatar":""},{"name":"Jennifer Love Hewitt","avatar":""},{"name":"Freddie Prinze Jr.","avatar":""},{"name":"Billy Campbell","avatar":""},{"name":"Gabbriette","avatar":""},{"name":"Sarah Michelle Gellar","avatar":""},{"name":"Austin Nichols","avatar":""},{"name":"Todd Giebenhain","avatar":""},{"name":"Joshua Orpin","avatar":""},{"name":"Georgia Flood","avatar":""},{"name":"Simone Annan","avatar":""},{"name":"Nico","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["I Know What You Did Last Summer","Souviens-toi... l''été dernier","Nikada ne zaboravljam što si radila prošlog ljeta","Le Pacte du silence","Vem, kaj ste zakrivili lansko poletje","Tajemství loňského léta","Keçən Yay Neylədiyini Bilirəm","E di çfarë ke bërë verën e kaluar"]', 1784690324147);
