INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mua-he-kinh-hai-4', 'Mùa Hè Kinh Hãi 4', 'I Know What You Did Last Summer', 'mùa hè kinh hãi 4 i know what you did last summer madelyn cline chase sui wonders jonah hauer-king tyriq withers sarah pidgeon jennifer love hewitt freddie prinze jr. billy campbell gabbriette sarah michelle gellar austin nichols todd giebenhain joshua orpin georgia flood simone annan nico i know what you did last summer souviens-toi... l''été dernier nikada ne zaboravljam što si radila prošlog ljeta le pacte du silence vem, kaj ste zakrivili lansko poletje tajemství loňského léta keçən yay neylədiyini bilirəm e di çfarë ke bërë verën e kaluar', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mau-nhuom-nui-song', 'Máu Nhuộm Núi Sông', 'For My Country', 'https://phimimg.com/upload/vod/20250926-1/91a6c7b1af59f65c55590d315427c872.jpg', 'https://phimimg.com/upload/vod/20250926-1/fe3799b78a30b1f90e388595281d811b.jpg', '<p>Mùa thu năm 1938, quân Nhật chiếm đóng huyện An, khu vực Hoa Bắc. Ngay sau đó, quân Nhật nhanh chóng bố trí lực lượng bao vây, truy quét căn cứ kháng Nhật của Bát Lộ Quân xung quanh huyện An. Để bảo vệ an toàn cho quân dân trong căn cứ kháng Nhật, trung đội trưởng Bát Lộ Quân – Lã Trường Thuận – nhận lệnh trong tình thế nguy cấp, dẫn dắt các chiến sĩ cùng tàn binh của Quốc Dân Đảng, dùng vũ khí thô sơ đối đầu với quân Nhật trang bị tinh nhuệ, mở ra một trận huyết chiến khốc liệt nhất…</p>', 'Full', 1, 'single', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngô Thừa Hiên","avatar":""},{"name":"Giang Thủy","avatar":""},{"name":"Hắc Tử","avatar":""},{"name":"Vương Hồng Thiên","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["For My Country","浴血山河"]', 1784690324147);
