INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mahavatar-narsimha', 'Mahavatar Narsimha', 'Mahavatar Narsimha', 'https://phimimg.com/upload/vod/20250926-1/a2f224d3b8cb019f8d7af9fa25d8d87d.jpg', 'https://phimimg.com/upload/vod/20250926-1/ea0eb8859cf262c7dd4a961fab753c0f.jpg', '<p>Trong huyền thoại Ấn Độ, quỷ vương tàn bạo Hiranyakashyap ngạo mạn tự xưng thần, thách thức cả Vishnu. Trái ngược với phụ vương, hoàng tử Prahlad vẫn kiên định niềm tin vào thần linh. Khi bóng tối ngập tràn, Vishnu giáng thế trong hình hài Narsimha – nửa người nửa sư tử – để chấm dứt bạo quyền và viết nên khúc ca bất diệt về đức tin và công lý.</p>', 'Full', 1, 'hoathinh', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Harjeet Walia","avatar":""},{"name":"Aditya Raj Sharma","avatar":""},{"name":"Haripriya Matta","avatar":""},{"name":"Sanket Jaiswal","avatar":""},{"name":"Priyanka Bhandari","avatar":""},{"name":"Vasundhra Bose","avatar":""},{"name":"Sachit Wartak","avatar":""},{"name":"Saanwari Yagnik","avatar":""},{"name":"Dinesh Varma","avatar":""},{"name":"Uplaksh Kochhar","avatar":""},{"name":"Akshayy Joshi","avatar":""},{"name":"Harish Molly","avatar":""},{"name":"Ajay Singhal","avatar":""},{"name":"Sankalp Jaiswal","avatar":""},{"name":"Karan Trivedi","avatar":""},{"name":"Abhishek Sharma","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mahavatar Narsimha","นรสิงหาวตาร","महावतार नरसिम्हा"]', 1784690324147);
