INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-luan-truyen', 'Côn Luân Truyện', 'The Legend Of Qingcheng', 'https://phimimg.com/upload/vod/20250926-1/c563a79a708224490b137ab0e3b12680.jpg', 'https://phimimg.com/upload/vod/20250926-1/5dbc20ef4b3e618ecd38f8415045991c.jpg', '<p>Bộ phim kể về hành trình tranh đoạt và bảo vệ bí ẩn nơi núi Côn Lôn – vùng đất linh thiêng gắn liền với truyền thuyết thần thoại. Trong bối cảnh chính – tà đối đầu, những anh hùng trẻ tuổi phải vượt qua hiểm nguy, âm mưu và thử thách để tìm kiếm chân lý, bảo vệ chính nghĩa và khám phá thân phận cùng sứ mệnh thực sự của mình.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lương Tĩnh Hiền","avatar":""},{"name":"Lưu Tử Thụy","avatar":""},{"name":"Mạch Trường Thanh","avatar":""},{"name":"Lương Thanh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["昆仑传"]', 1784690324147);
