INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('conmom', 'ConMom', 'ConMom', 'https://phimimg.com/upload/vod/20250926-1/e55688560fb517b880562e44bdf1bd8b.jpg', 'https://phimimg.com/upload/vod/20250926-1/6f00caa11e78b5a7223060abee2a37b3.jpg', '<p>Sau khi rời bỏ gã chồng phản bội, Pinky tìm cách giữ liên lạc với người con duy nhất bằng cách sử dụng một loạt trang phục cầu kỳ để dàn dựng những cuộc gặp bí mật.</p>', 'Full', 1, 'single', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Kaye Abad","avatar":""},{"name":"Paolo Contis","avatar":""},{"name":"Patrick Garcia","avatar":""},{"name":"Empoy Marquez","avatar":""},{"name":"Kit Thompson","avatar":""},{"name":"Valerie Talion","avatar":""},{"name":"Isay Alvarez","avatar":""},{"name":"Kate Alejandrino","avatar":""},{"name":"Gabe Mercado","avatar":""},{"name":"Polo Ravales","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["ConMom"]', 1784690324147);
