INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('conmom', 'ConMom', 'ConMom', 'conmom conmom kaye abad paolo contis patrick garcia empoy marquez kit thompson valerie talion isay alvarez kate alejandrino gabe mercado polo ravales conmom', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-xa-dieu-truyen-hiep-chi-dai-gia', 'Anh Hùng Xạ Điêu Truyện: Hiệp Chi Đại Giả', 'Legends Of The Condor Heroes: The Gallants', 'https://phimimg.com/upload/vod/20250412-1/f0f454bd324af2f9786ecd6a65afefc1.jpg', 'https://phimimg.com/upload/vod/20250412-1/4c00065f76596a168a60263d0eefcbc4.jpg', '<p>Trong giang hồ đầy ân oán tình thù, giữa thời đại chiến loạn quyền lực tranh giành, Quách Tĩnh (do Tiêu Chiến thủ vai) từ nhỏ đã rời xa quê hương, dần rèn luyện nên một sức mạnh to lớn có thể thay đổi cả cục diện và vận mệnh. Dù được các cao nhân xem trọng và truyền dạy những tuyệt học võ công như “Cửu Âm Chân Kinh” và “Giáng Long Thập Bát Chưởng”, nhưng chính điều đó cũng khiến anh trở thành mục tiêu đố kỵ của nhiều thế lực. Quách Tĩnh, khiêm nhường nhưng kiên định, giữ trọn tấm lòng trong sáng. Cùng Hoàng Dung (do Trang Đạt Phi thủ vai), anh dũng cảm xông pha giữa khói lửa chiến trường và mưa tên ngựa sắt, gánh vác sứ mệnh bảo vệ biên ải nhà Nam Tống. Giữa biển trời và chim điêu, người anh hùng không biết sợ hãi – người đại hiệp chân chính, xoay chuyển cả giang sơn, lập nên truyền thuyết võ lâm. Bộ phim chủ yếu được chuyển thể từ chương 34 đến chương 40 trong tiểu thuyết kinh điển cùng tên của Kim Dung.</p>', 'Full', 1, 'single', 'completed', 19, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 1, '[{"name":"Tiêu Chiến","avatar":""},{"name":"Trang Đạt Phỉ","avatar":""},{"name":"Hồ Quân","avatar":""},{"name":"Thái Thiếu Phân","avatar":""},{"name":"Lương Gia Huy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["射雕三部曲1","The Legends of Condor Heroes: The Gallants","The Legend of the Condor Heroes: The Great Hero","افسانه عقاب های مبارز: دلیران","Lendas dos Heróis do Condor: Os Valentes","Legend Of The Condor Heroes: Die Legende der Adlerkrieger","射雕英雄传：侠之大者"]', 1784690324147);
