INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-don-doc-2025', 'Anh Hùng Đơn Độc', 'Lone Hero (The Lonely Warrior)', 'https://phimimg.com/upload/vod/20250926-1/4747af0cc5b0109ad777ce425790fd0a.jpg', 'https://phimimg.com/upload/vod/20250926-1/a96fec52ff222766c77d3a18616e9843.jpg', '<p>Bộ phim&nbsp;xoay quanh hành trình một người trẻ đơn độc đối diện nghịch cảnh, vượt qua thử thách hiểm nguy và đấu tranh giữa tình thân, tình yêu cùng trách nhiệm, để cuối cùng tìm ra sức mạnh thật sự của lòng can đảm và sự hy sinh.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Thanh Đình","avatar":""},{"name":"Vương Vũ Huyên","avatar":""},{"name":"Lâm Uyên","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["营救进行时","怒火","孤勇者"]', 1784690324147);
