INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-hat-karaoke-di', 'Đi Hát Karaoke Đi!', 'Let''s Go Karaoke!', 'https://phimimg.com/upload/vod/20250809-1/275268921f73eb5ea4ddadc477cbcc58.jpg', 'https://phimimg.com/upload/vod/20250809-1/41168c4ef4128714911d46a99f5c02a0.jpg', '<p>Hayashi – cậu học sinh kỳ lạ với thói quen đếm bậc thang, chụp biển báo đường phố và phơi khoai lang trên ban công lớp học – luôn sống thật với chính mình, bất chấp mọi ánh nhìn. Trong khi đó, Nikaidou lại cố giấu mình sau vẻ lạnh lùng, u ám khiến ai cũng dè chừng. Nhưng khi một người bắt đầu nhìn thấy điều khác lạ phía sau lớp mặt nạ ấy, mọi khoảng cách dần bị thu hẹp…</p>', 'Tập 5', 12, 'hoathinh', 'ongoing', 9, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shun Horie","avatar":""},{"name":"Daisuke Ono","avatar":""},{"name":"Shinnosuke Tokudome","avatar":""},{"name":"Hidenobu Kiuchi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Karaoke Iko!","カラオケ行こ!"]', 1784690324147);
