INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-toc-guinness', 'Gia Tộc Guinness', 'House Of Guinness', 'https://phimimg.com/upload/vod/20250926-1/3674b690766715dc26cf4cd72e74e613.jpg', 'https://phimimg.com/upload/vod/20250926-1/59fd9a9e09fa93ccd3f375ef82346732.jpg', '<p>Bốn anh chị em của gia tộc Guinness gánh vác đế chế sản xuất bia, gia tài và di sản của người bố quá cố ở Ireland đầy biến động vào thế kỷ 19.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Anthony Boyle","avatar":""},{"name":"Louis Partridge","avatar":""},{"name":"Emily Fairn","avatar":""},{"name":"Fionn O''Shea","avatar":""},{"name":"James Norton","avatar":""},{"name":"Niamh McCormack","avatar":""},{"name":"Seamus O''Hara","avatar":""},{"name":"Jack Gleeson","avatar":""},{"name":"Dervla Kirwan","avatar":""},{"name":"Michael McElhatton","avatar":""},{"name":"Danielle Galligan","avatar":""},{"name":"David Wilmot","avatar":""},{"name":"Hilda Fay","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Дом Гиннесса","House of Guinness"]', 1784690324147);
