INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gia-toc-guinness', 'Gia Tộc Guinness', 'House Of Guinness', 'gia tộc guinness house of guinness anthony boyle louis partridge emily fairn fionn o''shea james norton niamh mccormack seamus o''hara jack gleeson dervla kirwan michael mcelhatton danielle galligan david wilmot hilda fay дом гиннесса house of guinness', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-cam', 'Tự Cẩm', 'Si Jin', 'https://phimimg.com/upload/vod/20250301-1/dfab47527ab7f9314a3556ee05e1c021.jpg', 'https://phimimg.com/upload/vod/20250301-1/8ec9e93a86081fa82af429d8b696aa81.jpg', '<p>Bộ phim kể về tứ tiểu thư Khương Tự của phủ Đông Bình bá, người được tái sinh sau khi chết dưới tay người thương Úc Cẩm. Lần này, Khương Tự dũng cảm từ hôn, đấu trí với thẩm thẩm ác độc, mở tiệm hương liệu, giúp đỡ bạn tốt, và điều tra vụ án nhiều thiếu nữ bị giết hại... dần dần thay đổi kết cục bi thảm trước đây. Khi Khương Tự và tướng quân thiếu niên Úc Cẩm gặp lại, tuy mỗi người đều có toan tính riêng nhưng vẫn vương vấn nhau như trước. Cùng nhau, họ nỗ lực cứu ca ca Khương Trạm khỏi chết đuối, ngăn tỷ tỷ Khương Y treo cổ tự tử và cũng thay đổi kết cục phụ thân bị trưởng công chúa giá họa chém đầu. Hai người cùng vượt qua khó khăn nguy hiểm, thái độ của Khương Tự dành cho Úc Cẩm dần thay đổi, đồng ý yêu Úc Cẩm một lần nữa. Hai người nắm tay nhau bảo vệ Đại Chu thái bình, cùng hưởng một kiếp phồn hoa.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 9, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Cảnh Điềm","avatar":""},{"name":"Trương Vãn Ý","avatar":""},{"name":"Quách Đào","avatar":""},{"name":"Trương Thỉ","avatar":""},{"name":"Từ Hảo","avatar":""},{"name":"Tào Phỉ Nhiên","avatar":""},{"name":"Huỳnh Dịch","avatar":""},{"name":"Mã Tô","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Si Jin","SiJin","사금","Сы Цзинь","ซื่อจิ่น หวนรักประดับใจ","Tự Cẩm","似锦"]', 1784690324147);
