INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-quan-ao-lo-lem', 'Tủ Quần Áo Lọ Lem', 'Cinderella Closet', 'https://phimimg.com/upload/vod/20250703-1/f654d7ba1109286a882a8c12956123e7.jpg', 'https://phimimg.com/upload/vod/20250703-1/e7985bfc1587bd01009c9c0235f7763d.jpg', '<p>Cô sinh viên Haruka được người mình thầm mến rủ đi uống rượu. Trong khi cô đang tự hỏi cách để trở nên duyên dáng hơn, Hikaru cực kỳ xinh đẹp xuất hiện.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ichika Osaki","avatar":""},{"name":"Matsumoto Leo","avatar":""},{"name":"Karuma","avatar":""},{"name":"Yuna Mito","avatar":""},{"name":"Rintaro Hachimura","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["シンデレラ クロゼット"]', 1784690324147);
