INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-troi-day-cua-khien-hiep-si-phan-4', 'Sự Trỗi Dậy Của Khiên Hiệp Sĩ (Phần 4)', 'The Rising Of The Shield Hero (Season 4)', 'https://phimimg.com/upload/vod/20250715-1/adad146856eaf3791c577aea8680885e.jpg', 'https://phimimg.com/upload/vod/20250715-1/0d246b70f317eac6961aaa10de13f3fa.jpg', '<p>Naofumi tiếp tục hành trình bảo vệ thế giới với tấm khiên huyền thoại, đối mặt với những thế lực ngày càng nguy hiểm sau cuộc chiến tàn khốc. Khi bí ẩn về các vũ khí huyền thoại và thế giới song song dần được hé lộ, cậu buộc phải vượt qua giới hạn bản thân. Sự gắn kết giữa Naofumi và các đồng đội như Raphtalia, Filo trở nên quan trọng hơn bao giờ hết. Mùa 4 hứa hẹn đưa khán giả đến với vô vàn trận chiến mới khốc liệt cùng những bước ngoặt bất ngờ trong số phận của “anh hùng khiên”.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Rina Hidaka","avatar":""},{"name":"Kaito Ishikawa","avatar":""},{"name":"Asami Seto","avatar":""},{"name":"Yoshitsugu Matsuoka","avatar":""},{"name":"Konomi Kohara","avatar":""},{"name":"Kouhei Amasaki","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Tate no Yuusha no Nariagari","盾の勇者の成り上がり Season3","盾の勇者の成り上がり Season2","盾の勇者の成り上がり Season4","방패용사성공담","방패용사 성공담","방패 용사 성공담","انتفاضة بطل التّرس","El ascenso del Héroe del Escudo","Восхождение Героя Щита","Становление героя щита","نهوض بطل الدرع","盾之勇者成名錄第二季","盾之勇者成名錄Season3","盾之勇者成名錄 Season 3","盾之勇者成名錄 Season 4","Shield Hero","The Rising of the Shield Hero","Qalqon qahramoni","盾の勇者の成り上がり"]', 1784690324147);
