INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('su-troi-day-cua-khien-hiep-si-phan-4', 'Sự Trỗi Dậy Của Khiên Hiệp Sĩ (Phần 4)', 'The Rising Of The Shield Hero (Season 4)', 'sự trỗi dậy của khiên hiệp sĩ (phần 4) the rising of the shield hero (season 4) rina hidaka kaito ishikawa asami seto yoshitsugu matsuoka konomi kohara kouhei amasaki tate no yuusha no nariagari 盾の勇者の成り上がり season3 盾の勇者の成り上がり season2 盾の勇者の成り上がり season4 방패용사성공담 방패용사 성공담 방패 용사 성공담 انتفاضة بطل التّرس el ascenso del héroe del escudo восхождение героя щита становление героя щита نهوض بطل الدرع 盾之勇者成名錄第二季 盾之勇者成名錄season3 盾之勇者成名錄 season 3 盾之勇者成名錄 season 4 shield hero the rising of the shield hero qalqon qahramoni 盾の勇者の成り上がり', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-hoang-cu-thap', 'Bà Hoàng Cự Tháp', 'The Queen Of Castle', 'https://phimimg.com/upload/vod/20250827-1/20d3fcac9627d96eb48124dea878d44d.jpg', 'https://phimimg.com/upload/vod/20250827-1/99afb6b3daa902d80a54bd0d6746d39a.jpg', '<p>Ngay sau đám cưới xa hoa ở châu Âu, chủ tịch Vương Tấn Đào của tập đoàn Minh Lãng cùng hai con trai và cháu của ông bất ngờ qua đời trong một vụ tai nạn, khiến cả nhà họ Vương rơi vào cảnh hỗn loạn. Bên ngoài thì kẻ thù giở đủ trò để phá hoại, bên trong thì nội bộ gia đình đấu đá nhau để tranh giành quyền lực. Trước tình cảnh đó, người vợ mới cưới của chủ tịch Vương - bác sĩ phẫu thuật tim nổi tiếng Đổng Nhất Nghiên - phải tìm cách thu phục hai cô con dâu của Tấn Đào để bảo vệ vị thế của mình ở tập đoàn. Bà Hoàng Cự Tháp xoay quanh trận chiến khốc liệt chốn thương trường khốc liệt giữa Nhất Nghiên và những thế lực muốn rắp tâm độc chiếm Minh Lãng.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 7, 2025, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Tuyên Huyên","avatar":""},{"name":"Trần Triển Bằng","avatar":""},{"name":"Trần Vĩ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["巨塔之后"]', 1784690324147);
