INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vi-khach-2025', 'Vị Khách', 'The Guest', 'https://phimimg.com/upload/vod/20250925-1/018bd00057fa81818bbfd3527a9d6509.jpg', 'https://phimimg.com/upload/vod/20250925-1/8fbc49a83e8df128439c4ad31d1e6b94.jpg', '<p>Sau vụ ngoại tình, cặp đôi nọ cố gắng cứu vãn cuộc hôn nhân của họ. Nhưng mọi chuyện rơi vào hỗn loạn khi người phụ nữ bí ẩn, từng quen biết người vợ, xuất hiện tại nhà họ.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 13, 2025, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Laura Londoño","avatar":""},{"name":"Carmen Villalobos","avatar":""},{"name":"Jason Day","avatar":""},{"name":"Víctor Mallarino","avatar":""},{"name":"Juan Fernando Sánchez","avatar":""},{"name":"Margarita Muñoz","avatar":""},{"name":"Jairo Camargo","avatar":""},{"name":"Miguel González","avatar":""},{"name":"Ariel Sierra","avatar":""},{"name":"Kami Zea","avatar":""},{"name":"Andrés Suárez","avatar":""},{"name":"Rami Herrera","avatar":""},{"name":"Bryan Zorrilla","avatar":""},{"name":"Laura García","avatar":""},{"name":"Katherine Vélez","avatar":""},{"name":"Álvaro García","avatar":""},{"name":"Natha","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["La huésped"]', 1784690324147);
