INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-cam-lua-chay-trong-dem', 'Hoa Cấm: Lửa Cháy Trong Đêm', 'The Forbidden Bloom', 'https://phimimg.com/upload/vod/20250925-1/e2d959ceb30057830bf446504a4edbfb.jpg', 'https://phimimg.com/upload/vod/20250925-1/b303b8bad36810ad72667fea362f56b3.jpg', '<p>Để bảo vệ cuộc sống đang trên bờ vực sụp đổ của mình, Go Eun càng ngày càng trở nên cực đoan. Trong khi đó, chồng cô, Ju Hyeok lại bị giắng xé giữa sự thật mà Go Eun đang che giấu và sự quyến rũ của Hwa Yeon. Bao nhiêu dục vọng và sự cố chấp đan xen giữa ba người, cuối cùng đã đẩy cuộc sống hào nhoáng của Go Eun đến bờ vực của sự sụp đổ và kết thúc trong bi kịch.</p>', 'Hoàn Tất (47/47)', 47, 'series', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phim Ngắn","slug":"phim-ngan","id":"4f02d28224c0747511790d57fbb63a62"}]', '[]', 1784690324147);
