INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-doi-van-hanh-phuc', 'Cuộc Đời Vẫn Hạnh Phúc', 'A Lifetime Of Happiness', 'https://phimimg.com/upload/vod/20250925-1/e5e78a68a46749216504c441d8532bf8.jpg', 'https://phimimg.com/upload/vod/20250925-1/08e8f9f9877282551c2b09af37849635.jpg', '<p>Câu chuyện kể về một tai nạn xe hơi đã khiến Kim Đại Hỉ bị nhận nhầm thành người anh song sinh mất trí nhớ Đồng Sinh, từ đó hai anh em hoán đổi cuộc đời. Kim Đại Hỉ chìm đắm trong vinh hoa của nhà họ Đồng, trong khi Kim Đại Hoan cùng Đồng Sinh dần nảy sinh tình cảm trong quá trình chung sống. Khi sự thật được phơi bày, họ cùng nhau vạch trần âm mưu của Thường Minh, cuối cùng hóa giải hiểu lầm, thu hoạch được cả tình yêu lẫn tình thân, để hai gia đình đoàn tụ.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hồ Bác Văn","avatar":""},{"name":"Tống Chiêu Nghệ","avatar":""},{"name":"Đồng Hoài Châu","avatar":""},{"name":"Đỗ Dung Nhất","avatar":""},{"name":"Tô Thần","avatar":""},{"name":"Tôn Lộ Lỗ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ci Sheng Jie Huan Xi","此生皆欢喜"]', 1784690324147);
