INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('turkey', 'Turkey!', 'Turkey! Time To Strike', 'https://phimimg.com/upload/vod/20250919-1/06619ed5cb5ffc8f90461784e70aeaee.jpg', 'https://phimimg.com/upload/vod/20250919-1/996b6cae7d1d20fb0ca0b9893dc242f0.jpg', '<p>Mai Otonashi là học sinh năm hai và là đội trưởng Câu lạc bộ Bowling trường trung học Ikkokukan, nhưng gần đây cô gặp khó khăn trong việc giành chiến thắng. Mỗi khi ghi được một “Turkey” – ba cú strike liên tiếp – thì ngay sau đó cô lại vấp phải một thế khó không thể đánh gỡ, gọi là “Snake Eyes”. Đây là câu chuyện về Mai, Rina, Sayuri, Nozomi và Nanase – những cô gái chiến đấu, vấp ngã rồi lại đứng lên, cùng nhau theo đuổi chiến thắng trong những ngày cuối cùng của mùa hè.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hana Hishikawa","avatar":""},{"name":"Kana Ichinose","avatar":""},{"name":"Haruki Iwata","avatar":""},{"name":"Yuuki Temma","avatar":""},{"name":"Ayasa Ito","avatar":""},{"name":"Noriko Hidaka","avatar":""},{"name":"Yuko Minaguchi","avatar":""},{"name":"Kikuko Inoue","avatar":""},{"name":"Miki Ito","avatar":""},{"name":"Rei Sakuma","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["ターキー!","터키!","保齡球少女！","Turkey! Time to Strike","Turkey!"]', 1784690324147);
