INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-niem-tin', 'Bẫy Niềm Tin', 'Trust', 'https://phimimg.com/upload/vod/20250924-1/96c0efbbf629fdb523d0d07df49be7dd.jpg', 'https://phimimg.com/upload/vod/20250924-1/f15145a000074cc95df5f3cd9aad9f7a.jpg', '<p>Sau một bê bối chấn động ở Hollywood, một ngôi sao điện ảnh trẻ tìm đến một căn Airbnb hẻo lánh để ẩn náu. Nhưng nơi tưởng như an toàn ấy nhanh chóng trở thành cơn ác mộng, khi cô rơi vào tay những tên tội phạm máu lạnh đang săn lùng một phi vụ lớn.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sophie Turner","avatar":""},{"name":"Rhys Coiro","avatar":""},{"name":"Billy Campbell","avatar":""},{"name":"Peter Mensah","avatar":""},{"name":"Forrest Goodluck","avatar":""},{"name":"Gianni Paolo","avatar":""},{"name":"Renata Vaca","avatar":""},{"name":"Katey Sagal","avatar":""},{"name":"Milton Darnell Smith","avatar":""},{"name":"Victor Oliveira","avatar":""},{"name":"Kariana Karhu","avatar":""},{"name":"Cal Butler","avatar":""},{"name":"Katie Barberi","avatar":""},{"name":"Diego Guzmán","avatar":""},{"name":"Donagh Gordon","avatar":""},{"name":"Lucía Gómez-Robledo","avatar":""},{"name":"Dylan Hal","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Besimi","Trust"]', 1784690324147);
