INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('batman-aztec-de-che-huyet-chien', 'Batman Aztec: Đế Chế Huyết Chiến', 'Aztec Batman: Clash Of Empires', 'https://phimimg.com/upload/vod/20250924-1/d4248a45bb568961ac921c364cd7d445.jpg', 'https://phimimg.com/upload/vod/20250924-1/ede19fa45c2cddb3180bf74e12b6fe3d.jpg', '<p>Thời đế chế Aztec. Thảm kịch giáng xuống khi Yohualli Coatl tận mắt chứng kiến cha mình bị sát hại bởi những kẻ chinh phạt Tây Ban Nha. Mang trong tim nỗi đau và lời thề báo thù, anh vượt qua hiểm nguy để đến Tenochtitlán, cảnh báo vua Moctezuma và đại tư tế Yoka về mối đe dọa cận kề. Tại ngôi đền thờ thần dơi Tzinacan, Yohualli được tôi luyện và trang bị vũ khí để trở thành chiến binh, quyết đối đầu quân xâm lược và trả món nợ máu. Trên hành trình định mệnh ấy, anh chạm trán những nhân vật huyền thoại: Nữ Chiến binh Báo dữ dội và chính Hernán Cortés – kẻ dẫn đầu cuộc chinh phục.</p>', 'Full', 1, 'hoathinh', 'completed', 18, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Horacio García Rojas","avatar":""},{"name":"Álvaro Morte","avatar":""},{"name":"Omar Chaparro","avatar":""},{"name":"Humberto Busto","avatar":""},{"name":"Jorge R. Gutierrez","avatar":""},{"name":"Jesús Guzmán","avatar":""},{"name":"José Carlos Illanes","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Бэтмен Ацтек","Batman Azteca: Choque de Impérios","Batman Azteca: Choque de imperios"]', 1784690324147);
