INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhi-long-ho-giac-mong-thon-que-phan-2', 'Nhị Long Hồ: Giấc Mộng Thôn Quê (Phần 2)', 'Erlong Lake Blossoms Of Hometown Dreams (Season 2)', 'nhị long hồ: giấc mộng thôn quê (phần 2) erlong lake blossoms of hometown dreams (season 2) trương hạo châu lệ lan quách thiết thành hoàng hiểu quyên lai hỉ trương đào trác nghĩ âm tích đại trang viện hàng minh quan hạo vương thông địa lôi 二龙湖村暖花开 er long hu cun nuan hua kai cun nuan hua kai 村暖花开 二龙湖·村暖花开 二龙湖·“村”暖花开2 erlong lake blossoms of hometown dreams 二龙湖·“村”暖花开', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoanh-lai-gap-duoc-em', 'Ngoảnh Lại Gặp Được Em', 'Encounter With You', 'https://phimimg.com/upload/vod/20250910-1/d868693e2acf2bc74a8f1b01e9159ca7.jpg', 'https://phimimg.com/upload/vod/20250910-1/0923572dbc8164b51df4e6682998d40a.jpg', '<p>Nữ chính Vạn Tân Tân – một bà mẹ trẻ nóng bỏng – kết hôn chớp nhoáng với Tần Cương, một thiếu gia nhà giàu, và nhanh chóng sinh con. Nhưng cuộc hôn nhân lại tan vỡ khi cô phát hiện Tần Cương ngoại tình với bạn gái cũ Lưu Vi. Trong cơn tuyệt vọng, Vạn Tân Tân quyết định ly hôn, ôm con rời khỏi nhà chồng. Trên đường rời đi, cô tình cờ quen biết với Hoa Minh, một người đàn ông từng trải, tốt bụng. Cuộc gặp gỡ ngoài ý muốn đã khiến cuộc sống của anh đảo lộn, thậm chí còn bị thiệt hại về nhà cửa và tài sản. Hai người buộc phải “ở chung” để chăm sóc con, từ đó nảy sinh nhiều mâu thuẫn, nhưng cũng dần dần phát triển thành những rung động khó nói. Trong khi đó, Tần Cương vì muốn kế thừa gia nghiệp, dưới sự thúc ép của mẹ, đã tìm cách giành lại vợ con. Mẹ Tần và Lưu Vi cũng lao vào vòng xoáy tranh chấp. Cùng lúc, vợ cũ của Hoa Minh – Hạ Tình – mang theo con gái tuổi dậy thì quay về, mong muốn tái hợp, kéo theo những bí mật trong quá khứ của anh dần được phơi bày. Tình yêu, hôn nhân và gia đình bị cuốn vào vòng xoáy của dối trá, lựa chọn và tha thứ. Cuối cùng, tương lai của Vạn Tân Tân vẫn đầy bất định…</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đồng Dao","avatar":""},{"name":"Vu Dịch","avatar":""},{"name":"Trì Soái","avatar":""},{"name":"Phùng Quốc Cường","avatar":""},{"name":"Dương Khôn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Zhuan Shen Yu Dao Ni","My Spicy Girlfriend","转身遇到你"]', 1784690324147);
