INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuot-song-2025', 'Vượt Sông', 'Crossing The River', 'https://phimimg.com/upload/vod/20250922-1/c77afb73f6c589c07496e57534061d01.jpg', 'https://phimimg.com/upload/vod/20250922-1/131559b369d9eaab28f1cd113a77d57b.jpg', '<p>Năm 1948, các sĩ quan thuộc Quân đoàn Dã chiến số 3 đã xâm nhập Nam Kinh và phối hợp với cán bộ của Đảng Cộng sản bí mật thực hiện các hoạt động bảo vệ hệ thống tình báo, thu thập vật tư, bảo vệ nhà máy, bảo vệ người dân và làm tan rã lực lượng địch. Họ đã thành công trong việc thuyết phục sư đoàn trưởng đồn trú Quốc dân đảng đào ngũ, góp phần quan trọng vào thắng lợi của Chiến dịch vượt sông Dương Tử và công cuộc giải phóng dân tộc.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 18, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngô Anh Đông","avatar":""},{"name":"Phạm Thuỵ Tuyết","avatar":""},{"name":"Lưu Thế Hoa","avatar":""},{"name":"Trần Thị","avatar":""},{"name":"Lý Bác","avatar":""},{"name":"Lục Hoan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["Du Jiang","Crossing the River","渡江"]', 1784690324147);
