INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hai-hon-hanh-phan-2', 'Hải Hôn Hành (Phần 2)', 'Voyage To Haihun (Season 2)', 'https://phimimg.com/upload/vod/20250912-1/bdd81bd2d182d2c053db947f0763fbb7.jpg', 'https://phimimg.com/upload/vod/20250912-1/d8c4f9fffbca0ce831ceb9640750ffd4.jpg', '<p>Thanh niên Vương Hoành bất ngờ xuyên vào thời Tây Hán, gặp gỡ nữ hiệp Đắc Cửu giống hệt người yêu cũ của mình, đồng thời trở thành bạn tốt của Lưu Hạ có tính cách phóng khoáng. Họ quyết tâm bắt tay với nhau khiêu chiến lịch sử, thay đổi số phận của hoàng đế Lưu Hạ đoản mệnh chỉ tại vị 27 ngày, khởi đầu một hành trình vượt thời gian, thay đổi số phận đầy mạo hiểm.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Mao Tử Tuấn","avatar":""},{"name":"Hoàng Nhật Oánh","avatar":""},{"name":"Cảnh Nghiệp Đình","avatar":""},{"name":"Trần Xu Quân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["海昏行 第二季","Marquis of Haihun","海昏行"]', 1784690324147);
