INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('shine-orchestric-ver', 'Shine (Orchestric Ver.)', 'Shine (Orchestric Ver.)', 'shine (orchestric ver.) shine (orchestric ver.) nattawin wattanagitiphat phakphum romsaithong yuke songpaisan yotsawat tawapee oabnithi wiwattanawarang thanawat shinawatra patiphan fueangfunuwat athens werapatanakul pawat akkradetsakul peter deriy sataporn nakwilairoj sutatta udomsilp thana 许他闪耀 照耀之光 chai chai (acoustic ver.) ชาย (orchestric ver.) shine: the series shine acoustic version shine (orchestric ver.) ชาย', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-do-bo-cua-idol-kpop', 'Cuộc Đổ Bộ Của Idol K-pop', 'K-Idol Invasion', 'https://phimimg.com/upload/vod/20250922-1/91fa028ad467f08e877ac9859ccbfd6a.jpg', 'https://phimimg.com/upload/vod/20250922-1/dff63cd9ab67f704c0c257f1140cd598.jpg', '<p>Vì truyền tay trái phép các video K-pop, con gái của một quan chức cấp cao ở Triều Tiên bị bắt và phải đối mặt với án tử hình. Nhờ sự giúp đỡ của mẹ, cô trốn thoát sang Hàn Quốc và bất ngờ chạm mặt với trưởng nhóm một nhóm nhạc thần tượng. Khi mối liên kết kỳ lạ giữa họ lớn dần, cả hai phải đối mặt với các thử thách từ gián điệp, truyền thông và quá khứ của cô, buộc họ phải chiến đấu vì tình yêu trước muôn vàn trở ngại.</p>', 'Hoàn Tất (53/53)', 53, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Min Do-hee","avatar":""},{"name":"Lee Sun","avatar":""},{"name":"Choi Sang-min","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["偶像，南侵！","爱豆南侵","Aidol, Namchin!","偶像入侵中","Idol, Boyfriend!","아이돌, 남친!"]', 1784690324147);
