INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('puniru-la-mot-be-slime-de-thuong-phan-2', 'Puniru Là Một Bé Slime Dễ Thương (Phần 2)', 'Puniru Is A Cute Slime (Season 2)', 'https://phimimg.com/upload/vod/20250707-1/2d2c15791dc7d2b60858788af0bd7f38.jpg', 'https://phimimg.com/upload/vod/20250707-1/613f068f42683df122a57af28718cf7a.jpg', '<p>Sau nhiều năm làm bạn với bé slime Puniru, nam sinh cấp hai Kotaro vật lộn đối mặt với sức hút biến đổi hình dạng của cô và cả cảm xúc của mình.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yu Sasahara","avatar":""},{"name":"Shuichiro Umeda","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["可爱史莱姆噗尼露","Puniru wa Kawaii Slime","Puniru wa Kawaī Suraimu","푸니르는 귀여운 슬라임 2기","Милий слиз Пуніру","Пуніру — милий слайм","Puniru Is a Cute Slime","ぷにるはかわいいスライム"]', 1784690324147);
