INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-den-cung-mua-ame-to-kimi-to', 'Em Đến Cùng Mưa (Ame to Kimi to)', 'With You And The Rain', 'https://phimimg.com/upload/vod/20250714-1/391f4c3213686e2afa70b21beba19bfe.jpg', 'https://phimimg.com/upload/vod/20250714-1/82a6ca63a42fdda490292f1284b5af12.jpg', '<p>Vào một ngày mưa, một người phụ nữ tình cờ gặp một con vật lạ đang chờ bên vệ đường. Con vật nài nỉ được nhận nuôi, đưa cho người phụ nữ một chiếc ô để cố gắng thể hiện sự hấp dẫn của nó. Bị hấp dẫn bởi bản tính thông minh của nó, cô mang sinh vật giống chó này về nhà và từ đó bắt đầu cuộc sống chung của họ.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Saori Hayami","avatar":""},{"name":"Anna Mugiho","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["和雨和你","雨天遇见狸","Ame to Kimi to","雨と君と"]', 1784690324147);
