INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('em-den-cung-mua-ame-to-kimi-to', 'Em Đến Cùng Mưa (Ame to Kimi to)', 'With You And The Rain', 'em đến cùng mưa (ame to kimi to) with you and the rain saori hayami anna mugiho 和雨和你 雨天遇见狸 ame to kimi to 雨と君と', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-dem-lam-co-ngay-gap-meo', 'Đi Đêm Lắm Có Ngày Gặp Mèo', 'Nyaight Of The Living Cat', 'https://phimimg.com/upload/vod/20250708-1/0e062518b4ebb5d7c96425e9ebc5ed7d.jpg', 'https://phimimg.com/upload/vod/20250708-1/b9a350aaaa58b10dcf164c57d66660ad.jpg', '<p>Khi một loại virus kỳ quái biến con người thành... mèo lông lá chỉ bằng những cái ôm, thế giới nhanh chóng rơi vào hỗn loạn. Kunagi - người đàn ông mất trí nhớ nhưng hiểu mèo đến lạ thường, phải đấu tranh sinh tồn trong khi cố cưỡng lại sức hấp dẫn khó tả của những chú mèo đáng yêu chết người. Ẩn mình giữa đống đổ nát, anh cùng những người sống sót chống lại đại dịch &quot;ôm là hóa mèo&quot;. Hài hước, kịch tính và không kém phần quái đản, đây là cuộc chiến sinh tồn kỳ lạ nhất bạn từng thấy!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Masaaki Mizunaka","avatar":""},{"name":"Reina Ueda","avatar":""},{"name":"Hiroki Yasumoto","avatar":""},{"name":"Reiji Kawashima","avatar":""},{"name":"Ryota Takeuchi","avatar":""},{"name":"Subaru Kimura","avatar":""},{"name":"Yoshiki Nakajima","avatar":""},{"name":"Yu Serizawa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["NYAIGHT OF THE LIVING CAT 活尸猫之夜","活死喵之夜","Nyaito obu za Ribingu Kyatto","ニャイリビ","Nyailivi","Nyairibi","NYAIGHT OF THE LIVING CAT","Ночь живых кошаков","NYAIGHT OF THE LIVING CAT 活屍貓之夜","Night of the Living Cat","ニャイト・オブ・ザ・リビングキャット"]', 1784690324147);
