INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('di-dem-lam-co-ngay-gap-meo', 'Đi Đêm Lắm Có Ngày Gặp Mèo', 'Nyaight Of The Living Cat', 'đi đêm lắm có ngày gặp mèo nyaight of the living cat masaaki mizunaka reina ueda hiroki yasumoto reiji kawashima ryota takeuchi subaru kimura yoshiki nakajima yu serizawa nyaight of the living cat 活尸猫之夜 活死喵之夜 nyaito obu za ribingu kyatto ニャイリビ nyailivi nyairibi nyaight of the living cat ночь живых кошаков nyaight of the living cat 活屍貓之夜 night of the living cat ニャイト・オブ・ザ・リビングキャット', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-xau-xi-dung-si-otaku-beo', 'Chiến Binh Xấu Xí (Dũng Sĩ Otaku Béo)', 'Uglymug, Epicfighter', 'https://phimimg.com/upload/vod/20250711-1/1e7467e1b906267ca5fc38cead7be8e4.jpg', 'https://phimimg.com/upload/vod/20250711-1/2983de8cafb87d02ea4ce760301dc176.jpg', '<p>Bị vu cáo phạm tội, Shigeru Yoshioka 34 tuổi mất tất cả mọi thứ—tự do, lòng tin vào phụ nữ và vị trí của mình trong xã hội. Sống như một người khép kín, anh phát hiện ra một màn hình trạng thái bí ẩn trên máy tính của mình, cho anh cơ hội tái sinh ở một thế giới khác. Để đổi lấy ngoại hình của mình, anh có được sức mạnh không thể tưởng tượng nổi, với các thông số lên tới 100 nghìn tỷ và hơn thế nữa. Giờ đây được tái sinh thành một &quot;Thần tuyệt đối&quot;, Shigeru bắt đầu một cuộc sống mới trong một thế giới giả tưởng, nơi sức mạnh ngự trị tối cao.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Junichi Suwabe","avatar":""},{"name":"Konomi Inagaki","avatar":""},{"name":"Kento Shiraishi","avatar":""},{"name":"Maaya Uchida","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["丑男真战士","肥宅勇者","Busa-men Gachi-Fighter","Busamen Gachi Fighter","Всё тот же уродливый боец","Боєць Бусамен Гачі","Потворний епічний боєць","ブサメンガチファイター"]', 1784690324147);
