INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kontinental-25', 'Kontinental ''25', 'Kontinental ''25', 'https://phimimg.com/upload/vod/20250922-1/1eed00cf42738a015515eaf116b9732e.jpg', 'https://phimimg.com/upload/vod/20250922-1/879dd37a4ac4fc1aab25f66c1611de31.jpg', '<p>Orsolya là một chấp hành viên ở Cluj, thành phố trung tâm của Transylvania. Một ngày nọ, cô phải thực hiện việc trục xuất một người vô gia cư đang sống dưới tầng hầm của một tòa nhà. Một biến cố bất ngờ xảy ra khiến Orsolya rơi vào khủng hoảng đạo đức, buộc cô phải tìm cách giải quyết trong khả năng tốt nhất của mình.</p>', 'Full', 1, 'single', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Romania', 0, '[{"name":"Eszter Tompa","avatar":""},{"name":"Gabriel Spahiu","avatar":""},{"name":"Adonis Tanța","avatar":""},{"name":"Oana Mardare","avatar":""},{"name":"Șerban Pavlu","avatar":""},{"name":"Annamária Biluska","avatar":""},{"name":"Ilinca Manolache","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Continental ’25","歐陸慈航2025","Kontinentaal 25","Kontinental ''25"]', 1784690324147);
