INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-khong-ngu', 'Ngày Không Ngủ', 'Mobius', 'https://phimimg.com/upload/vod/20250917-1/dfeb65890571435ad901de5b942ef022.jpg', 'https://phimimg.com/upload/vod/20250917-1/ecd6c98af023631ca789a87fbdac5b53.jpg', '<p>Bộ phim kể về một vị “thần thám” tại Cục cảnh sát thành phố Hoa Áo, nổi tiếng thông minh và dũng cảm, nhiều lần phá giải những vụ án kỳ bí. Thế nhưng, khi hàng loạt vụ án giết người hoàn mỹ liên tiếp xảy ra, anh phải đối mặt với những thử thách chưa từng có, trong một thành phố đầy biến động và hiểm nguy rình rập ở khắp nơi.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 9, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Bạch Kính Đình","avatar":""},{"name":"Văn Vịnh San","avatar":""},{"name":"Tống Dương","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["逆时侦查组","Bu Mian Ri","Бессонные дни","Mobius","เวียน ว่าย ตาย ฆ่า","不眠日"]', 1784690324147);
