INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghich-tien-ma-tien', 'Nghịch Tiên Mà Tiến', 'Go Up Against The Immortals', 'https://phimimg.com/upload/vod/20250911-1/8ca7b82cf5f1442489ec8066c66e29a0.jpg', 'https://phimimg.com/upload/vod/20250911-1/382b95cf11224689f811039193270b6b.jpg', '<p>Chàng trai nghèo Trần Nguyên Khởi nuôi người tình bái sư học đạo, nhưng bị phản bội và rơi xuống vực, sức mạnh thần thánh được thức tỉnh, anh thề sẽ thay đổi vận mệnh của mình. Đồng hành trên con đường báo thù còn có thánh nữ lạnh lùng, ngự tỷ của Yêu tộc, cô nàng đáng yêu của Linh tộc, Trần Nguyên Khởi chém quý tộc thế gia, tiêu diệt Ma giáo, đấu với đạo trời, thách thức quy tắc của Tiên môn bằng thân xác phàm trần. Trong thời khắc nguy nan, anh đã tự phá vỡ xiềng xích của số phận và giành lấy cơ duyên nghịch thiên cải mệnh cho chúng sinh.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hướng Hân","avatar":""},{"name":"Trương Hồng Minh","avatar":""},{"name":"Quách Hinh Ngọc","avatar":""},{"name":"Tiền Tư Di","avatar":""},{"name":"Chương Khải Nguyệt","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ni Xian Er Shang","역선이상 : 천명을 거스르는 자","Going Against the Immortals","逆仙而上"]', 1784690324147);
