INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-co-trang-den-hac-bach-cuc', 'Ván Cờ Trắng Đen (Hắc Bạch Cục)', 'Double Track Puzzle', 'https://phimimg.com/upload/vod/20250908-1/6234fc78f37115533c824ad3e41702c8.jpg', 'https://phimimg.com/upload/vod/20250908-1/7a7383fd476d47c11a4a24b93aec235e.jpg', '<p>Bộ phim&nbsp;xoay quanh cuộc chiến căng thẳng giữa chính nghĩa và tội ác. Trong bối cảnh thành phố chìm trong mạng lưới ngầm phức tạp, cảnh sát và tội phạm đối đầu nhau như trong một ván cờ đen trắng, nơi mỗi bước đi đều mang tính sống còn. Bộ phim khắc họa quá trình điều tra, đấu trí và cả những lựa chọn khó khăn của con người trước ranh giới trắng – đen, thiện – ác, đồng thời hé lộ sự thật ẩn giấu sau hàng loạt vụ án bí ẩn.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Tả Văn","avatar":""},{"name":"Vương Nghiâm Huy","avatar":""},{"name":"Hứa Thi Siệt","avatar":""},{"name":"Đái Văn Bác","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Black and White Bureau","黑白局"]', 1784690324147);
