INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-pho-voi-chi-em-nha-mikadono-that-de-dang', 'Đối Phó Với Chị Em Nhà Mikadono Thật Dễ Dàng', 'Dealing With Mikadono Sisters Is A Breeze', 'https://phimimg.com/upload/vod/20250921-1/431696f7d88949f891923db65bf27edd.jpg', 'https://phimimg.com/upload/vod/20250921-1/225d729a6973f543840c181e9355bcb7.jpg', '<p>Yu Ayase, con trai của một nữ diễn viên huyền thoại quá cố, lại là một người tầm thường đến mức khó tin. Khi được mời đến ở cùng bạn của mẹ, Yu vô cùng sửng sốt khi biết mình sẽ sống cùng ba chị em thần đồng, vừa xinh đẹp vừa tài năng… và là những người cai quản ngôi trường mới của cậu với danh hiệu Tam Hoàng. Liệu Yu có thể làm tan chảy trái tim băng giá của hai chị em và thực hiện được ước nguyện cuối cùng của mẹ cậu là xây dựng một gia đình hạnh phúc?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Minami Hinata","avatar":""},{"name":"Yurina Amami","avatar":""},{"name":"Aoi Koga","avatar":""},{"name":"Yoshino Aoyama","avatar":""},{"name":"Masaya Matsukaze","avatar":""},{"name":"Ai Kayano","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["帝乃三姐妹意外地容易相处","帝乃三姐妹原来很好搞定","帝乃三姐妹原来很好搞定。","Mikadono San Shimai wa Angai, Choroi.","帝乃三姊妹意外地容易相处","帝乃三姉妹は案外、チョロい。"]', 1784690324147);
