INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phap-su-trang-bi-loai-khoi-to-doi-duoc-mao-hiem-gia-cap-s-don-nhan', 'Pháp Sư Trắng Bị Loại Khỏi Tổ Đội, Được Mạo Hiểm Giả Cấp S Đón Nhận', 'Scooped Up By An S-Ranked Adventurer', 'https://phimimg.com/upload/vod/20250714-1/0f2c95c52a5cfe6eebc47b9fd71ca370.jpg', 'https://phimimg.com/upload/vod/20250714-1/64fefb83970849d918ea05ea1ee97304.jpg', '<p>Bị trục xuất khỏi nhóm anh hùng, Lloyd - một pháp sư hỗ trợ khiêm tốn cứ ngỡ mình chỉ là người tầm thường. Thế nhưng khi đồng hành cùng nhóm mạo hiểm giả hạng S trong một nhiệm vụ định mệnh, anh dần bộc lộ năng lực vượt xa tưởng tượng. Trong lúc nhóm anh hùng cũ rơi vào khủng hoảng, Lloyd lại vô tình bước vào con đường vinh quang, trở thành một nhà thám hiểm huyền thoại. Với tính cách giản dị nhưng sức mạnh vô song, câu chuyện của anh là hành trình thay đổi số phận đầy cuốn hút và bất ngờ.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Gakuto Kajiwara","avatar":""},{"name":"Rina Hidaka","avatar":""},{"name":"Haruka Shiraishi","avatar":""},{"name":"Daisuke Hirose","avatar":""},{"name":"Yuuichirou Umehara","avatar":""},{"name":"Ryohei Kimura","avatar":""},{"name":"Yui Ishikawa","avatar":""},{"name":"Mizuki Mano","avatar":""},{"name":"Ayaka Nanase","avatar":""},{"name":"Saeko Oki","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["El mago blanco que fue expulsado del grupo de héroes","El mago blanco que fue expulsado del grupo de héroes es recogido por un aventurero de rango S","被驱逐出勇者队伍的白魔导师，被S级冒险者捡到～这个白魔导师超规格～","被勇者队伍开除的白魔导师，被S级冒险者捡到","被驱逐出勇者队伍的白魔导师，被S级冒险者捡到","被驅逐出勇者隊伍的白魔導師，被 S 級冒險者撿到","被驱逐开勇者派对的白魔导师，被S级冒险者捡到 ～这个白魔导师超规格～","Yuusha Party wo Tsuihou sareta Shiromadoushi, S-Rank Boukensha ni Hirowareru ~Kono Shiromadoushi ga Kikakugai Sugiru~","Yūsha Party o Tsuihō Sareta Shiro Madōshi","White Magician Exiled From the Hero Party, Picked Up by S-Rank Adventurer","Yuusha Party wo Tsuihousareta Shiro Madoushi S Rank Boukensha ni Hirowareru","Yuusha Party wo Tsuihou Sareta Shiro Madoushi S Rank Boukensha ni Hirowareru Kono Shiro Madoushi ga Kikakugaisugiru","被驅逐出勇者隊伍的白魔導師，被S級冒險者撿到","被勇者隊伍驅逐的白魔導師，被S級冒險者撿走","The White Mage Who Was Banished From the Hero''s Party Is Picked Up by an S-Rank Adventurer: This White Mage Is Too Out of the Ordinary!","The White Mage Who Was Banished From the Hero''s Party Is Picked Up by an S Rank Adventurer","勇者パーティーを追放された白魔導師、Sランク冒険者に拾われる ～この白魔導師が規格外すぎる～"]', 1784690324147);
