INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phap-su-trang-bi-loai-khoi-to-doi-duoc-mao-hiem-gia-cap-s-don-nhan', 'Pháp Sư Trắng Bị Loại Khỏi Tổ Đội, Được Mạo Hiểm Giả Cấp S Đón Nhận', 'Scooped Up By An S-Ranked Adventurer', 'pháp sư trắng bị loại khỏi tổ đội, được mạo hiểm giả cấp s đón nhận scooped up by an s-ranked adventurer gakuto kajiwara rina hidaka haruka shiraishi daisuke hirose yuuichirou umehara ryohei kimura yui ishikawa mizuki mano ayaka nanase saeko oki el mago blanco que fue expulsado del grupo de héroes el mago blanco que fue expulsado del grupo de héroes es recogido por un aventurero de rango s 被驱逐出勇者队伍的白魔导师，被s级冒险者捡到～这个白魔导师超规格～ 被勇者队伍开除的白魔导师，被s级冒险者捡到 被驱逐出勇者队伍的白魔导师，被s级冒险者捡到 被驅逐出勇者隊伍的白魔導師，被 s 級冒險者撿到 被驱逐开勇者派对的白魔导师，被s级冒险者捡到 ～这个白魔导师超规格～ yuusha party wo tsuihou sareta shiromadoushi, s-rank boukensha ni hirowareru ~kono shiromadoushi ga kikakugai sugiru~ yūsha party o tsuihō sareta shiro madōshi white magician exiled from the hero party, picked up by s-rank adventurer yuusha party wo tsuihousareta shiro madoushi s rank boukensha ni hirowareru yuusha party wo tsuihou sareta shiro madoushi s rank boukensha ni hirowareru kono shiro madoushi ga kikakugaisugiru 被驅逐出勇者隊伍的白魔導師，被s級冒險者撿到 被勇者隊伍驅逐的白魔導師，被s級冒險者撿走 the white mage who was banished from the hero''s party is picked up by an s-rank adventurer: this white mage is too out of the ordinary! the white mage who was banished from the hero''s party is picked up by an s rank adventurer 勇者パーティーを追放された白魔導師、sランク冒険者に拾われる ～この白魔導師が規格外すぎる～', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-su-cua-cong-tuoc-tieu-thu', 'Gia Sư Của Công Tước Tiểu Thư', 'Private Tutor To The Duke''s Daughter', 'https://phimimg.com/upload/vod/20250629-1/673257248244e9be47dafa2a3e7ab942.jpg', 'https://phimimg.com/upload/vod/20250629-1/8fc9d517e9af6b32deb62ac19046d97e.jpg', '<p>Sau khi trượt kỳ thi cuối cùng để gia nhập triều đình, phù thủy trẻ Allen buộc phải từ bỏ giấc mơ và tìm kiếm việc làm để sống sót. Cơ hội duy nhất đến từ Công tước Howard - người cần một gia sư cho cô con gái Tina, một tiểu thư thông minh nhưng không thể sử dụng phép thuật. Trong khi kỳ thi vào Học viện Hoàng gia đang cận kề, Allen phải tìm cách giúp Tina vượt qua giới hạn tưởng chừng không thể phá bỏ. Thế nhưng, những bí ẩn phép thuật và âm mưu từ chính gia đình công tước lại khiến công việc tưởng đơn giản này trở nên nguy hiểm hơn bao giờ hết...</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuto Uemura","avatar":""},{"name":"Hime Sawada","avatar":""},{"name":"Kyoka Moriya","avatar":""},{"name":"Ikumi Hasegawa","avatar":""},{"name":"Inori Minase","avatar":""},{"name":"Ami Maeshima","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Koujo Denka no Kateikyoushi","Kōjo Denka no Kateikyōshi","Koujo Denka no Katei Kyoushi","โคโจ เด็งกะ โนะ คาเทอิเกียวชิ","Tutor of the His Imperial Highness Princess","公女殿下の家庭教師"]', 1