INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-xau-tinh', 'Cô Gái Xấu Tính', 'Bad Girl', 'https://phimimg.com/upload/vod/20250810-1/b1eb9c782ee6bd00f4e30ef4d9007575.jpg', 'https://phimimg.com/upload/vod/20250810-1/a7ece6ba601bbab0a8b6e6cdd3ee451c.jpg', '<p>Yuu, cô nàng năm nhất với mái tóc nổi bật và vẻ ngoài “hổ báo” – thực ra lại là một học sinh gương mẫu… đang cố gắng hết sức để trở nên hư hỏng!? Tất cả chỉ để gây ấn tượng với hội trưởng kỷ luật Mizutori – người mà cô luôn thầm thương. Một câu chuyện học đường hài hước, ngốc nghếch và đầy dễ thương sắp bắt đầu!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Azusa Tachibana","avatar":""},{"name":"Nina Hanamiya","avatar":""},{"name":"Misato Matsuoka","avatar":""},{"name":"Miharu Hanai","avatar":""},{"name":"Kaori Maeda","avatar":""},{"name":"Lynn","avatar":""},{"name":"Yui Horie","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["坏女孩","不良少女","BADGIRL","ばっどがーる"]', 1784690324147);
