INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-bat-tinh-va-cong-chua-am-sat', 'Anh Hùng Bất Tỉnh Và Công Chúa Ám Sát', 'The Shy Hero And The Assassin Princesses', 'https://phimimg.com/upload/vod/20250715-1/d21368a59ba5d33cb58936d28060d5d2.jpg', 'https://phimimg.com/upload/vod/20250715-1/847964896eac815c9b8fdb9f8c843cfc.jpg', '<p>Trong một thế giới nơi quỷ dữ đang dần xâm lấn nhân loại, một &quot;Anh hùng được chọn&quot; xuất hiện để cứu lấy vương quốc. Nhưng trớ trêu thay, vị anh hùng ấy – Rein – lại là một chàng trai cực kỳ nhút nhát, ngại giao tiếp và... ngất xỉu mỗi khi gặp nguy hiểm!

Lo ngại tương lai của nhân loại, hoàng gia quyết định cử những sát thủ giỏi nhất của họ để &quot;giải quyết sớm&quot; vấn đề. Nhưng các sát thủ ấy lại chính là những công chúa hoàng tộc, mỗi người đều mang trong mình kỹ năng giết người siêu việt – và tính cách kỳ quặc không kém.

Thế nhưng thay vì giết Rein, các công chúa sát thủ lại... bị thu hút bởi sự chân thành, ngây ngô và lòng dũng cảm thầm lặng của cậu. Từ đây bắt đầu hành trình dở khóc dở cười giữa một anh hùng &quot;yếu tim&quot; và dàn công chúa &quot;mạnh tay&quot; – khi mà kẻ định giết lại trở thành người bảo vệ.

Liệu Rein có vượt qua nỗi sợ của mình để thực sự trở thành anh hùng? Và liệu các công chúa có giữ vững lệnh ám sát... hay sẽ bị chính trái tim mình phản bội?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shunsuke Takeuchi","avatar":""},{"name":"Iori Saeki","avatar":""},{"name":"Hitomi Ueda","avatar":""},{"name":"Haruka Shiraishi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["失神勇者与暗杀公主","气绝勇者与暗杀公主","Kizetsu Yūsha to Ansatsu Hime","Kizetsu Yuusha to Ansatsu Hime","The Stunned Hero and the Assassin Princesses","The Faint Hero and the Assassin Princesses","The Shy Hero and the Assassin Princesses","Anh Hùng Bất Tỉnh Và Công Chúa Ám Sát","気絶勇者と暗殺姫"]', 1784690324147);
