INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tehran-2025', 'Tehran', 'Tehran', 'https://phimimg.com/upload/vod/20250920-1/91e637898ef764a6880ec59c386ec009.jpg', 'https://phimimg.com/upload/vod/20250920-1/b460cfcb3c0b1131a033d9a9a9076bcf.jpg', '<p>Ngày 13 tháng 2 năm 2012, một quả bom từ trường phát nổ, phá hủy chiếc xe của đại sứ quán Israel tại Delhi. Thanh tra ACP Rajeev Kumar, người chỉ huy cuộc điều tra, nghi ngờ đằng sau sự việc còn nhiều uẩn khúc. Giữa áp lực chính trị và nghi vấn về mối liên hệ với Iran, ông bước vào hành trình nguy hiểm nhằm phơi bày sự thật, phải đối mặt với những kẻ thù vô cùng đáng gờm.</p>', 'Full', 1, 'single', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"John Abraham","avatar":""},{"name":"Neeru Bajwa","avatar":""},{"name":"Manushi Chhillar","avatar":""},{"name":"Dinker Sharma","avatar":""},{"name":"Hadi Khanjanpour","avatar":""},{"name":"Madhurima Tuli","avatar":""},{"name":"Alyy Khan","avatar":""},{"name":"Qaushiq Mukherjee","avatar":""},{"name":"Elnaaz Norouzi","avatar":""},{"name":"Adam Karst","avatar":""},{"name":"Derek Horsham","avatar":""},{"name":"Sushil Khatri","avatar":""},{"name":"Ashwin Kaushal","avatar":""},{"name":"Farshad Kholgi","avatar":""},{"name":"Amir Sabir Tabirzi","avatar":""},{"name":"Pathy Aiyar","avatar":""},{"name":"Toby Osm","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["तेहरान"]', 1784690324147);
