INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('acapulco-phan-4', 'Acapulco (Phần 4)', 'Acapulco (Season 4)', 'https://phimimg.com/upload/vod/20250724-1/6fc3e867278639df36635e0fe9cacd22.jpg', 'https://phimimg.com/upload/vod/20250724-1/ff134faa1dfd8e5aa950b9dadb6ff61c.jpg', '<p>Năm 1984, mong ước của Maximo Gallardo trở thành hiện thực khi anh nhận được công việc trong mơ ở khu nghỉ mát hấp dẫn hàng đầu, Las Colinas. Thế nhưng, anh sớm nhận ra rằng công việc ở đây phức tạp hơn nhiều so với những gì anh tưởng tượng.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Eugenio Derbez","avatar":""},{"name":"Enrique Arrizon","avatar":""},{"name":"Raphael Alejandro","avatar":""},{"name":"Camila Perez","avatar":""},{"name":"Chord Overstreet","avatar":""},{"name":"Fernando Carsa","avatar":""},{"name":"Jessica Collins","avatar":""},{"name":"Vanessa Bauche","avatar":""},{"name":"Regina Reynoso","avatar":""},{"name":"Rafael Cebrian","avatar":""},{"name":"Bianca Marroquín","avatar":""},{"name":"Regina Orozco","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["阿卡普尔科","אקפולקו","Acapulco"]', 1784690324147);
