INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-den-2025', 'Thỏ Đen', 'Black Rabbit', 'https://phimimg.com/upload/vod/20250919-1/9d0afff62a5055bab6289224d3cff079.jpg', 'https://phimimg.com/upload/vod/20250919-1/1f1c433baaaadf60b377e00d8f037d1f.jpg', '<p>Một chủ nhà hàng đang ăn nên làm ra bỗng bị cuốn vào thế giới ngầm tội phạm ở New York khi người anh trai tai quái trở về thị trấn cùng những kẻ cho vay nặng lãi bám đuổi.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Jason Bateman","avatar":""},{"name":"Jude Law","avatar":""},{"name":"Chris Coy","avatar":""},{"name":"Troy Kotsur","avatar":""},{"name":"Abbey Lee","avatar":""},{"name":"Odessa Young","avatar":""},{"name":"Robin de Jesús","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Iepurele negru","Black Rabbit"]', 1784690324147);
