INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dan-da-dan-phan-2', 'Dan Da Dan (Phần 2)', 'Dan Da Dan (Season 2)', 'https://phimimg.com/upload/vod/20250704-1/69a3b7a6f3369a96b99930ba0be0bedd.jpg', 'https://phimimg.com/upload/vod/20250704-1/7b759d5356cd982a45eb812ddfbeec2b.jpg', '<p>Dan Da Dan (Phần 2) tiếp tục theo chân Momo và Okarun trong hành trình khám phá thế giới siêu nhiên đầy biến động. Khi các thế lực mới ngày càng mạnh mẽ và nguy hiểm hơn xuất hiện, cả nhóm buộc phải đối mặt với những bí ẩn rùng rợn và quá khứ chưa từng được hé lộ. Thế giới càng trở nên kỳ quái, dữ dội nhưng cũng đầy cuốn hút. Xen giữa những trận chiến sinh tồn nghẹt thở là loạt khoảnh khắc &quot;lầy lội&quot; làm nên hành trình trưởng thành của cặp đôi bá đạo cùng nhóm bạn thân.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 11, 2025, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Shion Wakayama","avatar":""},{"name":"Natsuki Hanae","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Nana Mizuki","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["丹达丹","超自然武装当哒当","膽大黨","داندادان","DanDaDan","Dandadan","ДанДаДан","Dan da dan","ダンダダン"]', 1784690324147);
