INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('uchuujin-muumuu', 'Uchuujin MuuMuu', 'Me and the Alien MuMu / 宇宙人ムームー', 'https://phimimg.com/upload/vod/20250425-1/af03ec998910f569f7989b90ef68ead7.jpg', 'https://phimimg.com/upload/vod/20250425-1/f09431aaa5a47579c8f25081efd7f3e4.jpg', '<p>Một người ngoài hành tinh giống như mèo từ một thiên hà xa xôi, muumuu, đến trên trái đất. Mục tiêu của anh là tìm hiểu về công nghệ thiết bị gia dụng trên trái đất để phục hồi công nghệ mà loài của anh đã mất. Nhân vật chính, Sakurako, có một cuộc sống đại học điển hình, nhưng mọi thứ thay đổi với sự xuất hiện của Muumuu! Những gì bắt đầu như một sự sống chung bất ngờ nhanh chóng biến thành một cơn lốc của các sự kiện hỗn loạn. Hóa học giữa Sakurako và Muumuu dẫn đến một cuộc phiêu lưu hài kịch siêu, đầy đủ thiết bị và mèo. (Nguồn: Hẻm núi Pony)</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Momo Harumi","avatar":""},{"name":"Etsuko Kozakura","avatar":""},{"name":"Yasuyuki Kase","avatar":""},{"name":"Gakuto Kajiwara","avatar":""},{"name":"Yuriko Hibi","avatar":""},{"name":"Hidenobu Kiuchi","avatar":""},{"name":"Kentaro Kumagai","avatar":""},{"name":"Yukiyo Fujii","avatar":""},{"name":"Karin Takahashi","avatar":""},{"name":"Katsuyuki Konishi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["外星人沐沐","外星人姆姆","外星人MuuMuu","Uchūjin MūMū","Uchuujin MuuMuu","Me and the Alien MuuMuu","宇宙人ムームー"]', 1784690324147);
