INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trang-si-anh-hung', 'Tráng Sĩ Anh Hùng', 'The Hero', 'https://phimimg.com/upload/vod/20250919-1/b23739d0dd26e64f93d308dddddf2250.jpg', 'https://phimimg.com/upload/vod/20250919-1/0cbac949158037e3ad162d1489768d9b.jpg', '<p>Đổng Lộ (do Tần Hạo thủ vai) bị vợ đuổi khỏi nhà, được bạn học Đa Thụ (do Văn Tùng thủ vai) giới thiệu làm quản lý tầng hầm. Trong lúc dọn dẹp cho cư dân, anh bất ngờ phát hiện tin tức về khoản tiền khổng lồ chôn dưới đất. Em vợ của một quan chức tham nhũng vừa bị bãi chức trong thành phố cũng đang lẩn trốn tại đây. Sau khi làm quen với người hàng xóm Cửu Thiên (do Tạ Nam thủ vai), Đổng Lộ dần nhận được sự công nhận của mọi người và xác định được vị trí khoản tiền. Khi tiền mặt bị phát hiện, nguy hiểm ập đến, buộc mọi người phải giải quyết mọi chuyện trong một trận đối đầu dưới tầng hầm.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tần Hạo","avatar":""},{"name":"Văn Tùng","avatar":""},{"name":"Hiệp Nan","avatar":""},{"name":"Lãnh Trung Dịch","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Hero","这位壮士"]', 1784690324147);
