INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-kiem-cua-vua-nguoi-lun', 'Thanh Kiếm Của Vua Người Lùn', 'Dwarf King Middle Earth Sword', 'https://phimimg.com/upload/vod/20250919-1/d89e4e6b58d4badb518b44fdf02481bd.jpg', 'https://phimimg.com/upload/vod/20250919-1/0e6601da5d13b94189fbfd75ca847fb4.jpg', '<p>Mục Hâm (con nuôi của vua nước Người Lùn) đi tìm kiếm kiếm Thượng Cổ để cứu bộ lạc và con tin A Thanh. Trên đường đi, anh cứu được Mỹ Thần, cha cô là Vu Phong hy sinh để mở phong ấn Bạch Phù của cô. Khi mọi người tranh đoạt bảo kiếm, cha nuôi của Mỹ Thần là Vu Ẩn hóa thân thành ma kiếm, mưu đồ thống trị thiên hạ. Nhờ máu hi sinh của Ha Cát, ma tính mới bị phá tan. Để ngăn Man Vương Cự Thiên đoạt được bảo kiếm, A Thanh đã tự vẫn, lấy máu chân ái giải phong ấn của kiếm. Cuối cùng, Mục Hâm phong ấn Cự Thiên, trở về đất nước Người Lùn và đăng cơ làm vua.</p>', 'Full', 1, 'single', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Điền Tân Vũ","avatar":""},{"name":"Văn Hi","avatar":""},{"name":"Trương Lượng Lượng","avatar":""},{"name":"Vương Sùng Kiệt","avatar":""},{"name":"Trần Tam Mộc","avatar":""},{"name":"Đỗ Ngọc Minh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["矮人王中土之剑"]', 1784690324147);
