INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-phong-an-nau-la-vie-devant-moi', 'Căn Phòng Ẩn Náu (La Vie devant moi)', 'The Future Awaits', 'https://phimimg.com/upload/vod/20250919-1/5e11507412abb43713976042a5eb77a4.jpg', 'https://phimimg.com/upload/vod/20250919-1/1159d0fb3ce8f5fb2e0242b481aa941f.jpg', '<p>Năm 1942, gia đình cô bé Tauba 13 tuổi phải trốn ở căn gác bé tí vì là người Do Thái. Sự ngột ngạt và sợ hãi dần đánh bại bố mẹ, nhưng một Tauba lạc quan vẫn vững niềm tin chờ ánh dương xuất hiện.</p>', 'Full', 1, 'single', 'completed', 21, 2025, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Violette Guillon","avatar":""},{"name":"Guillaume Gallienne","avatar":""},{"name":"Adeline D''Hermy","avatar":""},{"name":"Sandrine Bonnaire","avatar":""},{"name":"Laurent Bateau","avatar":""},{"name":"Claude Mathieu","avatar":""},{"name":"Zoé Richard","avatar":""},{"name":"Bernard Le Coq","avatar":""},{"name":"Rod Paradot","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["La Guerre à 13 ans","La Vie devant moi"]', 1784690324147);
