INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-hoi-sinh', 'Bẫy Hồi Sinh', 'The Ghost Game', 'https://phimimg.com/upload/vod/20250919-1/fe2138e44b4deeac1b96a5e9b73eb977.jpg', 'https://phimimg.com/upload/vod/20250919-1/e40aa16196e52670c2a1cd758e48e48a.jpg', '<p>Một nhóm học sinh quyết định quay video dự thi với chủ đề “gọi hồn” tại một bể chứa nước ngầm bỏ hoang. Ban đầu chỉ là một trò đùa mang tính câu view, nhưng mọi thứ nhanh chóng vượt khỏi tầm kiểm soát khi một thành viên bất ngờ nôn ra nước đen và gục ngã giữa nghi lễ.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"YERI","avatar":""},{"name":"Lee Chan-hyeong","avatar":""},{"name":"Suh Dong-hyun","avatar":""},{"name":"Oh So-hyun","avatar":""},{"name":"Kim Eun-bi","avatar":""},{"name":"Park Seo-yeon","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["넥스트","Next","The Ghost Game","강령: 귀신놀이"]', 1784690324147);
