INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-cuon-hut-boi-ban-muchuu-sa-kimi-ni', 'Bị Cuốn Hút Bởi Bạn (Muchuu sa, Kimi ni.)', 'Captivated, By You', 'https://phimimg.com/upload/vod/20250822-1/09ec4e659048e6b02421920276fd1ae2.jpg', 'https://phimimg.com/upload/vod/20250822-1/bf360c0c7eba9821bc8f38f8e5924f0f.jpg', '<p>Joji Ema theo học tại một trường nam sinh. Sau lễ hội thể thao của trường, người bạn cùng lớp lập dị Miyoshi Hayashi bắt đầu có những hành động kỳ lạ đối với cậu. Yuichi Medaka lại học ở một trường trung học hỗn hợp. Cậu tình cờ ngồi phía sau Akira Nikaido, một học sinh đáng ngại mà hầu hết mọi người trong trường đều không thích. Bộ phim là một tuyển tập những câu chuyện khám phá trải nghiệm tuổi trẻ và những cung bậc cảm xúc khi trưởng thành.</p>', 'Tập 5', 12, 'hoathinh', 'ongoing', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kensho Ono","avatar":""},{"name":"Koki Uchiyama","avatar":""},{"name":"Yuki Ono","avatar":""},{"name":"Nobuhiko Okamoto","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Muchu-sa, Kimi ni.","Muchuu sa Kimi ni","夢中さ、きみに。"]', 1784690324147);
