INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-dau-tuong-lai-cua-bao-quan', 'Cô Dâu Tương Lai Của Bạo Quân', 'The Tyrant''s Bride-to-be', 'https://phimimg.com/upload/vod/20250918-1/4703a33a7b9fc1ae33c9436b7d5a2cc9.jpg', 'https://phimimg.com/upload/vod/20250918-1/b275dd57cb004fc9205d107b4dcd689e.jpg', '<p>Mang gánh nặng nợ nần của bố, cô gái trẻ than phiền về cái kết phi thực tế của một tiểu thuyết mạng. Nhưng ngay sau khi trút bực bội, cô lại bất ngờ tỉnh dậy trong chính cuốn tiểu thuyết đó và trở thành vị hôn thê đầu tiên phải chết. Không cam chịu số phận bi thảm, cô quyết tâm viết lại câu chuyện, tiếp cận kẻ phản diện khét tiếng, bạo chúa khiến ai cũng khiếp sợ, để đề nghị một cuộc hôn nhân hợp đồng.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 20, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phim Ngắn","slug":"phim-ngan","id":"4f02d28224c0747511790d57fbb63a62"}]', '[]', 1784690324147);
