INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('matchroom-nhung-ong-bau-dang-cap', 'Matchroom: Những Ông Bầu Đẳng Cấp', 'Matchroom: The Greatest Showmen', 'https://phimimg.com/upload/vod/20250918-1/280142a94edb36069c0afb4be8e5d372.jpg', 'https://phimimg.com/upload/vod/20250918-1/63a19b075ca2392712a31f7ebce2abd1.jpg', '<p>Matchroom là mái nhà của những tên tuổi lớn nhất trong làng thể thao – từ bi-a, phi tiêu, câu cá cho đến quyền anh – và cũng là trung tâm của nhiều thương vụ cùng sự kiện thể thao sinh lợi bậc nhất toàn cầu. Với quyền tiếp cận chưa từng có đối với Barry Hearn, con trai ông là Eddie cùng toàn bộ đội ngũ Matchroom tại trụ sở chính ở Essex, loạt phim tài liệu này sẽ đi sâu vào những kịch tính phía sau đế chế gia đình đã trở thành biểu tượng gắn liền với văn hóa thể thao Anh quốc.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Barry Hearn","avatar":""},{"name":"Eddie Hearn","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Matchroom: Lendas do esporte","Matchroom：体坛大娱乐家","Matchroom: Die größten Sport-Showmaster","Matchroom: A legnagyobb showmanek","Matchroom: The Greatest Showmen"]', 1784690324147);
