INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-vuong-cung-ta-tam-dau-y-hop', 'Quân Vương Cùng Ta Tâm Đầu Ý Hợp', 'A Naughty Princess', 'https://phimimg.com/upload/vod/20250918-1/74a5aae3477ea7b09ebc9bdd37f103ec.jpg', 'https://phimimg.com/upload/vod/20250918-1/bebf73889c3d1814790269ed7da1abf6.jpg', '<p>Câu chuyện kể về Liên Hương – một cô gái không biết thân thế của mình, tìm đến Trại Cảnh Vũ để nương nhờ họ hàng. Sau khi sơn trang bị hủy diệt, nàng bất đắc dĩ phải lưu lạc nơi đất khách, may mắn được Quận vương Bạch Ức Hàn thu nhận vào phủ làm tùy tùng. Bạch Ức Hàn nhận lệnh bí mật điều tra tung tích công chúa đang ẩn thân trong dân gian, nhưng không hề hay biết người tùy tùng kề cận chính là người mình cần tìm. Trải qua một quá trình điều tra đầy kịch tính, Bạch Ức Hàn phát hiện thân phận công chúa của Liên Hương, đồng thời vạch trần kẻ luôn ngấm ngầm cản trở nàng nhận lại thân phận thật sự – chính là Công chúa Vịnh Di. Đối diện với sự hãm hại từ chính chị gái ruột, Liên Hương vẫn liều mình cứu nguy cho chị trong lúc hoạn nạn. Máu mủ tình thâm khiến hai chị em hòa giải, và cuối cùng Liên Hương được mọi người chúc phúc, nên duyên thành thân cùng Bạch Ức Hàn.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đặng Linh Thư","avatar":""},{"name":"Trần Thụy Phong","avatar":""},{"name":"Na Hinh","avatar":""},{"name":"Trịnh Minh Dương","avatar":""},{"name":"Lý Thụy Phương","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jun Wang Yu Wo Xin Xiang Zhao","郡王与我心相照"]', 1784690324147);
