INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('quan-vuong-cung-ta-tam-dau-y-hop', 'Quân Vương Cùng Ta Tâm Đầu Ý Hợp', 'A Naughty Princess', 'quân vương cùng ta tâm đầu ý hợp a naughty princess đặng linh thư trần thụy phong na hinh trịnh minh dương lý thụy phương jun wang yu wo xin xiang zhao 郡王与我心相照', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-phong-thieu-nien-tu', 'Trường Phong Thiếu Niên Từ', 'The Dauntless Youths', 'https://phimimg.com/upload/vod/20250828-1/b8e332453b5132923208de8174c96785.jpg', 'https://phimimg.com/upload/vod/20250828-1/85a9ed4c10fffc2d4495f79446d23577.jpg', '<p>Vua Thương Sơn lâm bệnh nặng, hoang tưởng muốn tìm được “tiên dược trường sinh” trong truyền thuyết, nên ra lệnh cho các chư hầu đưa con trai đến triều đình để thành lập Doanh Thế Tử, cùng nhau tìm thuốc. Trong số đó, có bốn thiếu niên tính cách khác biệt: “Ma vương loạn thế” Giang Văn Hoán, nô lệ sa cơ nhưng ẩn giấu thân phận bí mật Khôn Ngô, chiến sĩ thảo nguyên Sùng Nghĩa Bưu, và chàng công tử phong lưu Tân Giáp. Họ cùng nhau tập hợp thành một đội. Trên hành trình, các thiếu niên liên tiếp gặp phải gian nguy, vừa bị kẻ địch bao vây vừa phải đối diện thử thách sinh tử. Sau những biến cố, họ dần dần từ đối thủ trở thành bạn bè chí cốt, cùng nhau sát cánh để vén mở âm mưu khủng khiếp ẩn sau “tiên dược trường sinh”. Cuối cùng, vì ngăn chặn đại họa, họ dũng cảm chiến đấu, bảo vệ dân chúng, trở thành một nhóm “thiếu niên anh hùng” gánh vác sứ mệnh bảo gia vệ quốc.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Trác Chước","avatar":""},{"name":"Trương Khương Lạc","avatar":""},{"name":"Vu Tế Vĩ","avatar":""},{"name":"Tống Phương Viên","avatar":""},{"name":"Lý Gia Hào","avatar":""},{"name":"Tô Mộng Địch","avatar":""},{"name":"Tằng Hựu Trân","avatar":""},{"name":"Kỳ Tâm Nhuệ","avatar":""},{"name":"Lý Khiết","avatar":""},{"name":"Kỷ Lý","avatar":""},{"name":"Vương Minh Dương","avatar":""},{"name":"Vương Hội Xuân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["朝歌少年行","朝歌·少年行","Changfeng Youth Ci","长风少年词"]', 1784690324147);
