INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tsuyokute-new-saga', 'Tsuyokute New Saga', 'New Saga', 'https://phimimg.com/upload/vod/20250720-1/a06e506cb853131687fe90b87916f84c.jpg', 'https://phimimg.com/upload/vod/20250720-1/3e79546d23e577ca51a5e8dcd1c0edbe.jpg', '<p>Sau một cuộc chiến tàn khốc, kiếm sĩ ma pháp Kyle đánh bại Ma Vương nhưng bị thương nặng sắp chết. Một tinh thể đỏ đưa anh quay về quá khứ bốn năm trước, đến quê hương từng bị hủy diệt, nơi anh tìm thấy những người thân yêu đã mất vẫn còn sống. Với kiến thức từ tương lai, Kyle thề sẽ ngăn chặn bi kịch sắp tới và viết lại định mệnh.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuma Uchida","avatar":""},{"name":"Hiro Shimono","avatar":""},{"name":"Fairouz Ai","avatar":""},{"name":"Asami Seto","avatar":""},{"name":"Minami Takahashi","avatar":""},{"name":"Hiroki Yasumoto","avatar":""},{"name":"Kaori Maeda","avatar":""},{"name":"Rie Hikisaka","avatar":""},{"name":"Riho Sugiyama","avatar":""},{"name":"Tetsu Inada","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["强者的新传说","Tsuyokute New Saga","Be Stronger! New Saga","強くてニューサーガ"]', 1784690324147);
