INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-duong-luan-hoi', 'Âm Dương Luân Hồi', 'Onmyo Kaiten Re:Birth Verse', 'https://phimimg.com/upload/vod/20250720-1/5417c961381a7339034234ee93290d39.jpg', 'https://phimimg.com/upload/vod/20250720-1/5a73b38e3678bbb6ae65bad2c8a453c7.jpg', '<p>Narihira Takeru là một tên du côn thường xuyên mơ về Tsukimiya – cô gái xuất hiện trong giấc mơ của anh. Sau một tai nạn bất ngờ, Takeru thấy mình lạc vào một vũ trụ song song – thế giới mà Tsukimiya đang sống. Khi cả hai bị quái vật giết chết, Takeru lại tỉnh dậy và nhận ra mình đã nhảy qua dòng thời gian. Từ đây, Takeru phải tu luyện cùng Abe Seimei để chiến đấu bảo vệ mạng sống của Tsukimiya!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Taihi Kimura","avatar":""},{"name":"Maaya Uchida","avatar":""},{"name":"Ryohei Kimura","avatar":""},{"name":"Kaito Ishikawa","avatar":""},{"name":"Anna Nagase","avatar":""},{"name":"Marina Inoue","avatar":""},{"name":"Chihaya Yoshitake","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["阴阳回天 Re:Birth","阴阳回天","陰陽迴天","Onmyo Kaiten Re:verse","Onmyou Kaiten Re:verse","Onmyō Kaiten Re:verse","Onmyou Kaiten Re:Birth","Onmyō Kaiten Re:Birth","Onmyō Kaiten Re:Bāsu","Onmyo Kaiten ReBirth","陰陽廻天 Re：バース","Onmyo Kaiten Reverse","陰陽廻天 Re:バース"]', 1784690324147);
