INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('forgive-us-all', 'Lòng Trắc Ẩn', 'Forgive Us All', 'https://phimimg.com/upload/vod/20250917-1/9f5420998abc37b2db2a74f6988a0c5f.jpg', 'https://phimimg.com/upload/vod/20250917-1/eeba9afb67b627e4054ae3516bbe7fdd.jpg', '<p>Thế giới sụp đổ sau đại dịch, loài người biến thành những con quái vật khát máu. Giữa nỗi đau mất mát, một người mẹ đơn độc ẩn náu trong căn lều heo hút nơi núi cao. Nhưng khi một người đàn ông trọng thương gõ cửa, mang theo tin tức về một lối thoát mong manh.</p>', 'Full', 1, 'single', 'completed', 18, 2025, 'Vietsub', 'FHD', 'New Zealand', 0, '[{"name":"Lily Sullivan","avatar":""},{"name":"Callan Mulvey","avatar":""},{"name":"Richard Roxburgh","avatar":""},{"name":"Lance Giles","avatar":""},{"name":"Bree Peters","avatar":""},{"name":"Lawrence Makoare","avatar":""},{"name":"Dean O''Gorman","avatar":""},{"name":"Bonnie Filer","avatar":""},{"name":"Travis Luke","avatar":""},{"name":"Zack McCracken","avatar":""},{"name":"Luke Hawker","avatar":""},{"name":"Andre Gwilliam","avatar":""},{"name":"Freddy Okyere","avatar":""},{"name":"Jodie Glinster","avatar":""},{"name":"Marie Dorin","avatar":""},{"name":"Kim Coll","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"}]', '["Forgive Us All"]', 1784690324147);
