INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('forgive-us-all', 'Lòng Trắc Ẩn', 'Forgive Us All', 'lòng trắc ẩn forgive us all lily sullivan callan mulvey richard roxburgh lance giles bree peters lawrence makoare dean o''gorman bonnie filer travis luke zack mccracken luke hawker andre gwilliam freddy okyere jodie glinster marie dorin kim coll forgive us all', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuong-quan-phu-nhan-co-sao-lai-the', 'Tướng Quân Phu Nhân Cớ Sao Lại Thế', 'Destiny Of The General''s Bride', 'https://phimimg.com/upload/vod/20250906-1/e37b3f3a56f36a50907431a2891e61d5.jpg', 'https://phimimg.com/upload/vod/20250906-1/4a9bacb99fb8c54158b58183a74c0ca9.jpg', '<p>Thiếu nữ Tô Họa đem lòng yêu và cùng tướng quân Tiêu Doãn bỏ trốn, nhưng lại bị chính tỷ tỷ hãm hại, bị nhị thiếu gia Tiêu Diệp cưỡng bức rồi chôn sống. Tô Họa &quot;sống lại&quot;, biến thành hoa khôi Thanh Yên, giao dịch với Tiêu Doãn, thành hôn với nhau để vào Tiêu phủ báo thù. Trong hành trình đó, nàng vượt qua bao gian nan để cứu giúp những tỷ muội bị hại cùng cảnh ngộ, cuối cùng khiến Tiêu gia phải chịu trừng phạt, khôi phục thân phận thật sự và đoàn tụ cùng Tiêu Doãn.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hà Thích","avatar":""},{"name":"Hà Thiện Khải","avatar":""},{"name":"Kim Thu","avatar":""},{"name":"Trần Hoàn","avatar":""},{"name":"Vu Hân Ngật","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jiang Jun Fu Ren Wei He Na Yang","Why is the General''s Wife Like That?","将军夫人为何那样"]', 1784690324147);
