INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tuong-quan-phu-nhan-co-sao-lai-the', 'Tướng Quân Phu Nhân Cớ Sao Lại Thế', 'Destiny Of The General''s Bride', 'tướng quân phu nhân cớ sao lại thế destiny of the general''s bride hà thích hà thiện khải kim thu trần hoàn vu hân ngật jiang jun fu ren wei he na yang why is the general''s wife like that? 将军夫人为何那样', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-ngay-nay-that-dien-ro-mattaku-saikin-no-tantei-to-kitara', 'Thám Tử Ngày Nay Thật Điên Rồ! (Mattaku Saikin no Tantei to Kitara)', 'Detectives These Days Are Crazy!', 'https://phimimg.com/upload/vod/20250720-1/e377804abe2d64d2c7f95af4ec523271.jpg', 'https://phimimg.com/upload/vod/20250720-1/f30f6ae0e0bbb96c43a1e6b50cb091ab.jpg', '<p>Từng là một thám tử huyền thoại, Nagumo Keiichiro giờ đây loạng choạng bước vào tuổi trung niên, bối rối trước điện thoại thông minh và cuộc sống hiện đại. Sự suy yếu thầm lặng của anh bị phá vỡ khi Mashiro, một nữ sinh trung học táo bạo, xông vào văn phòng anh đòi làm học việc. Mặc dù anh đã rỉ sét và cứng nhắc, nhưng sự nhiệt tình không ngừng nghỉ của cô đã kéo anh trở lại với công việc thám tử. Giờ đây, cặp đôi thám tử bắc cầu đã vào cuộc!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Junichi Suwabe","avatar":""},{"name":"Kana Hanazawa","avatar":""},{"name":"Kengo Kawanishi","avatar":""},{"name":"Tomokazu Sugita","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["最近的侦探真没用","Mattaku Saikin no Tantei Tokitara","Mattaku Saikin no Tantei to Kitara","المحققون هذه الأيام مجانين","Detectives These Days, Really","Detectives These Days...","Detectives These Days Are Crazy!","まったく最近の探偵ときたら"]', 1784690324147);
