INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tham-tu-ngay-nay-that-dien-ro-mattaku-saikin-no-tantei-to-kitara', 'Thám Tử Ngày Nay Thật Điên Rồ! (Mattaku Saikin no Tantei to Kitara)', 'Detectives These Days Are Crazy!', 'thám tử ngày nay thật điên rồ! (mattaku saikin no tantei to kitara) detectives these days are crazy! junichi suwabe kana hanazawa kengo kawanishi tomokazu sugita 最近的侦探真没用 mattaku saikin no tantei tokitara mattaku saikin no tantei to kitara المحققون هذه الأيام مجانين detectives these days, really detectives these days... detectives these days are crazy! まったく最近の探偵ときたら', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-quan-he-bi-mat', 'Mối Quan Hệ Bí Mật', 'Secret Lover', 'https://phimimg.com/upload/vod/20250724-1/01596802d9317d949f3dd1e2ad7b3a7d.jpg', 'https://phimimg.com/upload/vod/20250724-1/3f50cbe2058292145057de9131105ede.jpg', '<p>Tuấn Hy và A Thác là bạn thân từ thuở nhỏ. Trong một buổi diễn kịch ở trường đại học, A Thác đã nhân cơ hội tỏ tình và bất ngờ, cả hai đã trở thành người yêu. A Thác thực chất đã thầm yêu Tuấn Hy từ lâu và đã sử dụng nhiều &quot;bài tập hẹn hò&quot;, như giả vờ hẹn hò hay các trò chơi hôn, để dần xóa mờ ranh giới bạn bè, khiến Tuấn Hy cuối cùng cũng xiêu lòng và chấp nhận mối quan hệ này. Cả hai đã bí mật hẹn hò, nhưng sau đó phải đối mặt với nhiều thử thách: sự phản đối từ gia đình, sự theo đuổi của Vincent - sếp của Tuấn Hy, và áp lực từ cha của A Thác khi ông ép A Thác từ bỏ ước mơ kiến trúc sư để tiếp quản công việc kinh doanh của gia đình. Khi gần tốt nghiệp, Tuấn Hy cũng bận rộn với trách nhiệm gia đình vì cha anh lâm bệnh. Mối quan hệ của họ rơi vào bế tắc và đứng trước một lựa chọn khó khăn: công khai tình yêu hay chia tay.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Vương Quân Hào","avatar":""},{"name":"Thành Hi","avatar":""},{"name":"Lâm Diễm Từ","avatar":""},{"name":"Viên Tử Chúc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mi Mi Guan Xi","イッて终わりなわけがない！","Itte Owarina Wake ga nai!","Mi Mi Kuan Hsi","Secret Relationship","秘密關係(台版)","秘密關係"]', 1784690324147);
