INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('moi-quan-he-bi-mat', 'Mối Quan Hệ Bí Mật', 'Secret Lover', 'mối quan hệ bí mật secret lover vương quân hào thành hi lâm diễm từ viên tử chúc mi mi guan xi イッて终わりなわけがない！ itte owarina wake ga nai! mi mi kuan hsi secret relationship 秘密關係(台版) 秘密關係', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nu-chien-dau-voi-so-phan', 'Thiếu Nữ Chiến Đấu Với Số Phận', 'Girls Fighting Fate', 'https://phimimg.com/upload/vod/20250917-1/fa10d6801e1d576d948c572797fa179e.jpg', 'https://phimimg.com/upload/vod/20250917-1/f0b5445b45436fc6715f670d0bc5f80b.jpg', '<p>Thiếu nữ Tú Cúc sinh ra trong một gia cảnh nghèo khó, mẹ lại nằm liệt giường, còn chị dâu thì trăm bề ức hiếp. Với đôi bàn tay khéo léo, mỗi sáng cô đều ra gần học đường vừa bán những món đồ nhỏ kiếm tiền thuốc cho mẹ, vừa lén nghe giảng bài. Tại đây, cô gặp gỡ Thẩm Diện Châu – lục gia nhà họ Thẩm, một người thẳng thắn, chân thành – và nảy sinh tình cảm. Thế nhưng, để cứu mẹ và trả ơn, Tú Cúc buộc phải gả cho đại gia nhà họ Thẩm là Thẩm Diện Thanh, từ đó rơi vào vòng xoáy tình cảm rối ren giữa hai anh em nhà họ Thẩm…</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hoàng Duy Đức","avatar":""},{"name":"Vương Thụy Xương","avatar":""},{"name":"Quan Trướng","avatar":""},{"name":"Trần Tử Hàm","avatar":""},{"name":"Hổ Vi","avatar":""},{"name":"Ngô Tư Vũ","avatar":""},{"name":"Trương Hinh Nguyệt","avatar":""},{"name":"Trương Bác Chi","avatar":""},{"name":"Thẩm Tư Viên","avatar":""},{"name":"A Kỳ Lực","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ju Xiang Ru Yi","江南橘事","橘子红了","橘祥如意"]', 1784690324147);
