INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thieu-nu-chien-dau-voi-so-phan', 'Thiếu Nữ Chiến Đấu Với Số Phận', 'Girls Fighting Fate', 'thiếu nữ chiến đấu với số phận girls fighting fate hoàng duy đức vương thụy xương quan trướng trần tử hàm hổ vi ngô tư vũ trương hinh nguyệt trương bác chi thẩm tư viên a kỳ lực ju xiang ru yi 江南橘事 橘子红了 橘祥如意', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('na-tra-2-ma-dong-nao-hai', 'Na Tra 2: Ma Đồng Náo Hải', 'Ne Zha 2', 'https://phimimg.com/upload/vod/20250206-1/51d98f9d8a4bdc053173b0925924c616.jpg', 'https://phimimg.com/upload/vod/20250206-1/064c6f42c1fccb7ef286ec367ff95212.jpg', '<p>Sau kiếp nạn, mặc dù linh hồn của Na Tra và Ngao Bính được bảo toàn, nhưng thân xác của họ sẽ sớm bị hủy hoại hoàn toàn. Thái Ất Chân Nhân dự định sử dụng Thất Sắc Bảo Liên (Bông Sen Bảy Màu) để tái tạo thân xác cho họ. Tuy nhiên, trong quá trình tái tạo, họ đã gặp phải vô vàn khó khăn. Thân Công Báo quyết định thả &quot;Tứ Đại Long Vương&quot; bị giam cầm dưới biển sâu. Ngao Quảng nói rằng: &quot;Nếu con trai ta chết, ta sẽ không để một ai sống sót ở ải Trần Đường.&quot; Để bảo vệ ải Trần Đường, Na Tra sẽ phải chiến đấu với &quot;Tứ Đại Long Vương&quot; mà Thân Công Báo đã thả ra.</p>', 'Full', 1, 'hoathinh', 'completed', 14, 2025, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 1, '[{"name":"Lữ Diễm Đình","avatar":""},{"name":"Sâm Sắt Phu","avatar":""},{"name":"Hãn Mặc","avatar":""},{"name":"Trần Hạo","avatar":""},{"name":"Lục Khỉ","avatar":""},{"name":"Trương Già Minh","avatar":""},{"name":"Dương Vệ Thanh","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["哪吒2之魔童闹海","Na Tra: Ma Đồng Náo Hải","哪吒2","Nézhā zhī Mótóng nào hǎi","Nézhā èr","Nezha: The demon child churns the sea","哪吒贰之魔童闹海","哪吒之魔童鬧海","ناچا٢","נה ז''א 2","Ne Zha II","نژا 2","Né Zhā zhī Mó tóng nào hǎi","나타 2","나타지마동요해","ណាចា ២","哪吒之魔童闹海"]', 1784690324147);
