INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trao-nham-trai-tim', 'Trao Nhầm Trái Tim', 'A Fleeting Dream', 'https://phimimg.com/upload/vod/20250911-1/257ee2994faf76edb8793a6e26206898.jpg', 'https://phimimg.com/upload/vod/20250911-1/b6fd90bcc47b5db9ba40757c06738ce3.jpg', '<p>Liên Tâm Nhược, con gái của một thương nhân, đang sống hạnh phúc trong một gia đình giàu có thì gặp biến cố lớn, mất đi tất cả. Cô cố gắng kêu oan nhưng không thành, còn bị chôn sống. May mắn được Bùi Ngọc Trạch, nhị gia nhà họ Bùi cứu sống, cô quyết tâm phải tìm ra sự thật và tìm thời cơ trả thù. Năm năm sau, cô trở về dưới thân phận ca sĩ Đỗ U Mộng, hợp tác với Bùi Ngọc Trạch để giăng bẫy, bắt đầu cuộc chơi trả thù đầy hoành tráng và mãn nhãn...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Nghiêm Tử Hiền","avatar":""},{"name":"Hàn Hân Dư","avatar":""},{"name":"Hàn Tiêu Diêu","avatar":""},{"name":"Dương Thư Diệc","avatar":""},{"name":"Hoàng Văn Khanh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["一品名媛","错心"]', 1784690324148);
