INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-bao', 'Thời Báo', 'The Paper', 'https://phimimg.com/upload/vod/20250909-1/c210e8252a160c9ff10cf23858d5f0b4.jpg', 'https://phimimg.com/upload/vod/20250909-1/b288ea98addd4d524d6b075ecd814ab2.jpg', '<p>Sau khi khắc họa thành công đời sống tại văn phòng Scranton của Dunder Mifflin, ê-kíp làm phim tài liệu lại lên đường tìm kiếm một câu chuyện mới. Hành trình ấy dẫn họ đến Toledo, nơi tồn tại một tờ báo cổ kính mang tên The Truth Teller. Giữa thời đại báo in lụi tàn, một nhà xuất bản đầy nhiệt huyết vẫn nuôi giấc mơ thổi bùng sức sống cho nó — và đó chính là câu chuyện mới mà ống kính của họ đang chờ đợi.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Domhnall Gleeson","avatar":""},{"name":"Sabrina Impacciatore","avatar":""},{"name":"Chelsea Frei","avatar":""},{"name":"Melvin Gregg","avatar":""},{"name":"Gbemisola Ikumelo","avatar":""},{"name":"Alex Edelman","avatar":""},{"name":"Ramona Young","avatar":""},{"name":"Tim Key","avatar":""},{"name":"Oscar Nuñez","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Soom Soom","The Paper"]', 1784690324148);
