INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-thoi-den-nam-hai-quy-hu-hoat-hinh', 'Ma Thổi Đèn: Nam Hải Quy Hư (Hoạt Hình)', 'Candle In The Tomb: South Sea Tomb', 'https://phimimg.com/upload/vod/20250909-1/74d7e1695aad385505e887f1a5f5d7b0.jpg', 'https://phimimg.com/upload/vod/20250909-1/7878be82a9ca871d33a00efde9e6975d.jpg', '<p>Ma Thổi Đèn: Nam Hải Quy Hư là câu chuyện về công cuộc tìm kiếm một bảo vật xưa cũ của Tần Vương có tên là Chiếu Cốt Kính, cũng là một hành trình đầy rẫy những biến số mà những tiên liệu của Giáo sư Trần cùng mọi người bị rơi vào lạc lối. Khi nắm bắt được tin tức liên quan đến vị trí của Chiếu Cốt Kính, mọi người và thầy trò Hắc Nguyễn đã lên đường ngay tới vòng xoáy san hô. Nhưng mọi việc trở nên khó khăn hơn khi tất cả cùng rơi vào Quy Hư, một nơi đang ẩn chưa con tàu đắm kỳ lạ. Sau khi tìm kiếm được Chiếu Cốt Kinh đó thì tất cả mọi người đều té ngửa, hóa ra thầy trò Hắc Nguyễn lại chính là kẻ thù cũ của Đa Linh, từ đó nảy sinh ra những điều mà khó tránh khỏi. Chưa kể, từ phía xa, một kẻ lạ mặt thần bí đang dần xuất hiện với chiếc gậy trong tay đang tiến đến.</p>', 'Hoàn Tất (17/17)', 17, 'hoathinh', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["南海归墟","鬼吹灯之南海归墟","鬼吹灯","鬼吹灯之南海归墟-2025","鬼吹灯之南海归墟动画","鬼吹灯动画","South Sea Tomb","Candle in the Tomb：South Sea Tomb","Gui Chui Deng-South Sea Tomb"]', 1