INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-than-mat', 'Biển Thân Mật', 'Islanders', 'https://phimimg.com/upload/vod/20250915-1/b85f595f4af259461f8685e4b19a5c61.jpg', 'https://phimimg.com/upload/vod/20250915-1/929dfb85b93c7fb403b4e81e747cde98.jpg', '<p>Một doanh nhân giàu có sống giữa vòng xoáy tình ái với vợ, nhân tình và người yêu. Suốt bốn thập kỷ, mối quan hệ chằng chịt ấy kéo dài qua nhiều thế hệ. Nhưng khi một scandal trên mạng xã hội khiến ông mất tất cả, từng người trong họ phải đối mặt với sự thật về giá trị, tình yêu và niềm tin mà mình thực sự theo đuổi.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Christopher Lee Ming-Shun","avatar":""},{"name":"Wu Kang-ren","avatar":""},{"name":"Rima Zeidan","avatar":""},{"name":"Sara Yu","avatar":""},{"name":"Ina Tsai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["群岛","群島","親密之海"]', 1784690324148);
