INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vet-chan-tuoc-tich', 'Vết Chân (Tước Tích)', 'Footprints Of Change', 'https://phimimg.com/upload/vod/20250906-1/50070c7dbe3ec9caf0da64fb0b23d176.jpg', 'https://phimimg.com/upload/vod/20250906-1/5660043a5a22be9cd5e023bed4d7190c.jpg', '<p>Bộ phim kể lại hành trình đấu tranh cách mạng của nhiều thế hệ đảng viên Cộng sản Trung Quốc, tái hiện những dấu ấn lịch sử trọng đại từ thời kỳ chiến tranh giải phóng cho đến sau khi thành lập nước. Thông qua câu chuyện của từng nhân vật, phim khắc họa sự hy sinh, kiên định và niềm tin sắt đá của họ trên con đường vì lý tưởng.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đồng Dao","avatar":""},{"name":"Thừa Lỗi","avatar":""},{"name":"Lưu Dật Quân","avatar":""},{"name":"Lâm Vân","avatar":""},{"name":"Vương Hà Nhũ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Zu Ji","足迹"]', 1784690324148);
