INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('to-trong-an-dai-duong', 'Tổ Trọng Án Đại Đường', 'The Crime Unit Of Tang Dynasty', 'https://phimimg.com/upload/vod/20250904-1/b4e840b001c8018750444088173dfdd4.jpg', 'https://phimimg.com/upload/vod/20250904-1/18360132ee32db4c25c8404c30e6ce8e.jpg', '<p>Vào những năm cuối của thời Đường, thành Trường An đột nhiên xảy ra những vụ án kỳ lạ. Hàng loạt vụ án đan xen giữa cái đẹp và kinh hoàng - thi ca giữa tử thi, vụ án oán linh sơn trang với bóng ma chập chờn, vụ án ma kỹ nữ Lạc Dương với bức họa da người lúc nửa đêm, vụ án quỷ binh làng hoang với những âm binh mặc giáp mục nát, vụ án sòng bạc địa ngục - người sống đánh cược mạng sống hay vụ án Trường An trong gương&quot; với yêu vật hoành hành! Sáu vụ án kỳ lạ này tựa như những dây leo độc quấn chặt lấy vận mệnh của cả đất quốc. Lý Cảnh Niên của Đại Lý Tự, cùng với Lâm Tiêu Nhiên – chuyên phá các vụ án kỳ bí trong dân gian và nữ hiệp Thẩm Thu Vãn, đã lấy thân mình làm ngọn đuốc, quyết tâm thắp lại ngọn đèn bất diệt của thành Trường An...</p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Quản Lặc","avatar":""},{"name":"Viên Hạo","avatar":""},{"name":"Lưu Tâm Dư","avatar":""},{"name":"Lương Dịch Mộc","avatar":""},{"name":"Trần Khải","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Da Tang Zhong An Zu","大唐重案组"]', 1784690324148);
