INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-ha-anh-dai', 'Tại Hạ Anh Đài', 'In The Name Of Ying Tai', 'https://phimimg.com/upload/vod/20250728-1/e8a7b93d454408534fd65ed88492fa8e.jpg', 'https://phimimg.com/upload/vod/20250728-1/0b6252d3c6534f5f086dd6a856821a19.jpg', '<p>Bộ phim mang phong cách kiếm hiệp kết hợp tranh đấu triều đình, theo chân nữ chính Anh Đài cùng nhóm học viên học viện chống lại loạn đảng trong triều, giải quyết các bí ẩn và rối ren nơi cung đình. Trong suốt 12 tập, câu chuyện phát triển đi từ hành trình tu tài đến đối đầu thế lực lớn, với tinh thần “nữ chủ mạnh mẽ” và cái nhìn chiến lược về giang hồ và chính trị.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["在下英台","ZAIXIA YINGTAI","Zai Xia Ying Tai","Zai Xia \"Ying Tai\"","Liang Zhu","梁祝","Sampek Engtay","En Nombre de YingTai","Demi Nama \"Ying Tai\"","Demi Nama YingTai","Liang Shanbo Yu Zhu Yingtai","Nio Sampek dan Ciok Engtay","りょうざんぱくとしゅくえいだい","梁山伯と祝英台","En Nombre de Ying Tai","ข้านี่แหละจู้อิงไถ","ม่านประเพณี","เหลียงชานปั๋ว-ยฺหวี่จู้อิงไถ","คู่รักผีเสื้อ","เหลียงจู้","梁山伯與祝英台","在下英臺","梁祝傳說","In the Name of Ying Tai","I am Yingtai","I''m YingTai","Butterfly Lovers","在下“英台”"]', 1784690324148);
