INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tai-ha-anh-dai', 'Tại Hạ Anh Đài', 'In The Name Of Ying Tai', 'tại hạ anh đài in the name of ying tai  在下英台 zaixia yingtai zai xia ying tai zai xia "ying tai" liang zhu 梁祝 sampek engtay en nombre de yingtai demi nama "ying tai" demi nama yingtai liang shanbo yu zhu yingtai nio sampek dan ciok engtay りょうざんぱくとしゅくえいだい 梁山伯と祝英台 en nombre de ying tai ข้านี่แหละจู้อิงไถ ม่านประเพณี เหลียงชานปั๋ว-ยฺหวี่จู้อิงไถ คู่รักผีเสื้อ เหลียงจู้ 梁山伯與祝英台 在下英臺 梁祝傳說 in the name of ying tai i am yingtai i''m yingtai butterfly lovers 在下“英台”', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-thien-ky', 'Ma Thiên Ký', 'Demon''s Ascension', 'https://phimimg.com/upload/vod/20250617-1/134ca1412a01f92f1b69c9d9cc8cf2cb.jpg', 'https://phimimg.com/upload/vod/20250617-1/9159ab7268a534668e1d4266df7c8f69.jpg', '<p>Khi một thiếu niên lưu lạc lớn lên giữa vòng xoáy của kẻ ác bước vào thế giới tu tiên, điều gì sẽ xảy ra? Tiên – Ma chỉ cách nhau một niệm, sống chết chẳng do trời định. Hãy cùng theo dõi hành trình của cậu – người nghịch dòng số mệnh trong một thế giới nơi người và ma cùng tồn tại, yêu quái hoành hành, để vươn lên đỉnh cao và trở thành truyền thuyết.</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"路扬","avatar":""},{"name":"Qing Liu","avatar":""},{"name":"Liangwei Hu","avatar":""},{"name":"Zhao Chengchen","avatar":""},{"name":"魏茹晨","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Mo Tian Ji","Mó Tiān Jì","魔天记动画","魔天记 动画","Mo Tianji","魔天记动画片","Demon''s Diary","Demonic Records","魔天记"]', 1784690324148);
