INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-hung-dot-bien-x', 'Anh Hùng Đột Biến X', 'TO BE HERO X', 'https://phimimg.com/upload/vod/20250427-1/db91e7a052fa4665a32edc912f938707.jpg', 'https://phimimg.com/upload/vod/20250427-1/98e883179225c98418f7e1f519580875.jpg', '<p>Đây là một thế giới mà anh hùng được tạo ra bởi lòng tin của mọi người, và anh hùng nhận được nhiều lòng tin nhất được gọi là – X. Trong thế giới này, lòng tin của mọi người có thể được tính toán bằng dữ liệu và những giá trị này sẽ được phản ánh trên cổ tay của mọi người. Chỉ cần đạt được đủ điểm tin cậy, những người bình thường cũng có thể có siêu năng lực và trở thành siêu anh hùng cứu thế giới. Tuy nhiên, giá trị lòng tin luôn thay đổi khiến con đường của anh hùng đầy rẫy những điều chưa biết…</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wei Chao","avatar":""},{"name":"Liu Xiaoyu","avatar":""},{"name":"Zhangtaikang Chen","avatar":""},{"name":"Wentao Chang","avatar":""},{"name":"Jinwen Chen","avatar":""},{"name":"Qian Chen","avatar":""},{"name":"Shuang Zhao","avatar":""},{"name":"Zhang Fuzheng","avatar":""},{"name":"Yang Kaiqi","avatar":""},{"name":"Gu Jiangshan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Tu Bian Ying Xiong X","Tu Bian Yingxiong X","凸变英雄X","トゥー・ビー・ヒーローX","TBHX","トゥー・ビー・ヒーローイクス","투 비 히어로 X"]', 1784690324148);
