INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('anh-hung-dot-bien-x', 'Anh Hùng Đột Biến X', 'TO BE HERO X', 'anh hùng đột biến x to be hero x wei chao liu xiaoyu zhangtaikang chen wentao chang jinwen chen qian chen shuang zhao zhang fuzheng yang kaiqi gu jiangshan tu bian ying xiong x tu bian yingxiong x 凸变英雄x トゥー・ビー・ヒーローx tbhx トゥー・ビー・ヒーローイクス 투 비 히어로 x', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-thu-khuc', 'Thiên Thu Khúc', 'Adventure For Love', 'https://phimimg.com/upload/vod/20250607-1/df8f1209ff5f5c5cd72ecc8d3b8a1dbb.jpg', 'https://phimimg.com/upload/vod/20250607-1/ec01e5b8ec019cf3926654f425ea9b9e.jpg', '<p>Cô gái hiện đại Mã Thiên Thu xuyên không trở thành công chúa thời cổ đại, vô tình bị cuốn vào cuộc tranh đấu quyền lực. Cô và vị tướng quân mưu lược Tần Triệt từ nghi kỵ lẫn nhau dần trở thành đồng minh, cùng chống lại bạo quân Mã Dương Phi và thế lực Bắc Dự. Cả hai giả làm tình nhân để ứng phó với dư luận, đồng thời khám phá bí mật thân thế của Tần Triệt và vụ án oan của mẹ anh. Tuy nhiên, họ bị Hoàng tử Khang Hòa Na của Bắc Dự ly gián. Trải qua các biến cố như ám sát, trúng độc, hôn ước sắp đặt..., Mã Thiên Thu đau đớn nhận ra Tần Triệt từng lợi dụng mình để trả thù. Khi trái tim tan vỡ, hệ thống bất ngờ thông báo nhiệm vụ hoàn thành. Sau khi hóa giải mọi hiểu lầm, Mã Thiên Thu được phép ở lại Huy Âm thành trong ba ngày cuối cùng. Cô lựa chọn ở lại vì tình yêu, cùng Tần Triệt đứng giữa mưu đồ chính trị và tình cảm sâu đậm — để lại một mối tình vượt thời không đầy bi thương.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hei Ze","avatar":""},{"name":"Tan Yanyan","avatar":""},{"name":"Bai Yangzi","avatar":""},{"name":"Zhang Haozhe","avatar":""},{"name":"Bao Han","avatar":""},{"name":"Huang Panpan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Thousand Autumn Ode","Dream Come True","千秋赋"]', 1784690324148);
