INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-lai-do-dua-tien-linh-hon', 'Người Lái Đò Đưa Tiễn Linh Hồn', 'Folk Soul Ferryman', 'https://phimimg.com/upload/vod/20250914-1/e0b23984c800dfaffa20dbabd91d364c.jpg', 'https://phimimg.com/upload/vod/20250914-1/30187fd50fa545aa49f322f6fe68e18b.jpg', '<p>Câu chuyện kể về thầy Tiểu Thẩm, một người “dẫn hồn” trong dân gian, được cho là có thể đi lại giữa âm dương, thấu hiểu quỷ thần. Từ lúc bái sư học đạo cho đến khi thành nghề, anh đã trải qua ba sự kiện linh dị: mẹ ma con quỷ, thế thân gánh nạn, và nhập hồn cách thế hệ. Nhờ vào bản lĩnh “dẫn hồn” của mình, anh đã lần lượt hóa giải những sự việc kỳ bí ấy. Trong quá trình đó, thầy Tiểu Thẩm cũng tháo gỡ được nỗi băn khoăn từ thuở bái sư, và thấu hiểu chân lý: “Con người vừa được tình cảm che chở, cũng vừa bị tình cảm ràng buộc.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Bành Vu Tư","avatar":""},{"name":"Dương Tân Minh","avatar":""},{"name":"Trần Sáng","avatar":""},{"name":"Trình Phàm","avatar":""},{"name":"Chái Viên Lạc","avatar":""},{"name":"Cộng Kim Quốc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["民间摆渡人"]', 1784690324148);
