INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-nhai-tieu-nuong-nha-2', 'Thiên Nhai Tiểu Nương Nhạ 2', 'Miss Tanya 2', 'https://phimimg.com/upload/vod/20250914-1/d75f8909320606e907be57def50ab29b.jpg', 'https://phimimg.com/upload/vod/20250914-1/8beaa0dc719e801beed311c0e16bd6ed.jpg', '<p>Một “nhân loại thông minh” đến từ Singapore tên là Nương Nhiễm Thiên Nhai sở hữu siêu năng lực có thể nhìn thấy linh hồn của đồ vật và trích xuất ký ức. Sau cuộc phiêu lưu xuyên suốt trăm năm lịch sử Singapore cùng người bạn thân A Hồng, họ lần theo manh mối ký ức để đến Diên Đài – một thành phố ven biển cổ kính nhưng đặc biệt. Tại đây, họ thông qua những vật phẩm như bút lông, ảnh cũ, hoa cưới, giày giấy, khóa đồng tâm… để tìm ra những bí mật và chấp niệm ẩn chứa trong đó, đồng thời tháo gỡ những mối ràng buộc tình cảm. Nhờ vậy, họ bù đắp lại những cảm xúc đẹp đẽ đã thất lạc trong dòng chảy thời gian và không gian.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chu Chủ Ái","avatar":""},{"name":"Vu Phi Phàm","avatar":""},{"name":"Lý Khôn Miên","avatar":""},{"name":"Thiện Vi Quần","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Tian Ya Xiao Niang Re","天涯小娘惹2","天涯小娘惹II","Miss Tanya 2","天涯小娘惹"]', 1784690324148);
