INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-ban-gai', 'Cô Bạn Gái', 'The Girlfriend', 'https://phimimg.com/upload/vod/20250914-1/d570cab121d654419ae4eb513e3d8bf5.jpg', 'https://phimimg.com/upload/vod/20250914-1/06186c0ab1f36e9d472f2c286a3ac529.jpg', '<p>Laura có tất cả: một sự nghiệp rực rỡ, người chồng yêu thương và cậu con trai quý giá Daniel. Nhưng cuộc sống hoàn hảo ấy bắt đầu sụp đổ khi Daniel đưa về Cherry — cô bạn gái đã thay đổi mọi thứ. Sau màn ra mắt đầy căng thẳng, Laura tin rằng Cherry đang che giấu một bí mật. Liệu Cherry là kẻ cơ hội đầy toan tính, hay chỉ là Laura quá hoang tưởng? Sự thật nằm ở góc nhìn của mỗi người.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Robin Wright","avatar":""},{"name":"Olivia Cooke","avatar":""},{"name":"Laurie Davidson","avatar":""},{"name":"Waleed Zuaiter","avatar":""},{"name":"Tanya Moodie","avatar":""},{"name":"Shalom Brune-Franklin","avatar":""},{"name":"Karen Henthorn","avatar":""},{"name":"Anna Chancellor","avatar":""},{"name":"Leo Suter","avatar":""},{"name":"Francesca Corney","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["女友","女朋友","Chương trình TV","The Girlfriend"]', 1784690324148);
