INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoa-thuan-bi-mat', 'Thỏa Thuận Bí Mật', 'Harmony Secret', 'https://phimimg.com/upload/vod/20250729-1/cc3927f82f3d3c452e2906d75de696bb.jpg', 'https://phimimg.com/upload/vod/20250729-1/e33271bf17ee975eecf7ad131ab85f0d.jpg', '<p>Hai tiểu thư thừa kế – Aiwarin của đế chế khách sạn và Mewika của gia tộc trung tâm thương mại – cạnh tranh nhau để giành thầu cho dự án Duty-Free quốc gia. Nhưng ngay từ khoảnh khắc gặp gỡ, giữa họ đã nảy sinh một sức hút không thể chối từ.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Punyapat Wangpongsathaporn","avatar":""},{"name":"Saranphat Pedersen","avatar":""},{"name":"Nichapalak Thongkham","avatar":""},{"name":"Jiratchaya Kittavornsakul","avatar":""},{"name":"Akalavut Mankalasut","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["하모니 시크릿","ดีลลับฉบับเล่นเล่ห์"]', 1784690324148);
