INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('my-kieu-nuong-tra-an', 'Mỹ Kiều Nương Tra Án', 'The Beautiful Lady Detective Agency', 'https://phimimg.com/upload/vod/20250913-1/b1a3ec756405abf5c32ba0d37914c47d.jpg', 'https://phimimg.com/upload/vod/20250913-1/a2087434b5398e56bf253d4cf2085046.jpg', '<p>Trần Băng Băng, Ái Mỹ Lệ và Lâm Nguyệt Sơ là ba người bạn thân, đều đã lập gia đình và sống cuộc sống bà nội trợ bình lặng. Khi tụ họp, cả ba đều cảm thấy sau hôn nhân, cuộc sống trở nên tẻ nhạt, mất đi giá trị của bản thân với tư cách là phụ nữ. Một ngày nọ, họ tình cờ đi ngang một cửa hàng tạp hóa và phát hiện đây không phải là cửa tiệm bình thường, mà chính là một văn phòng thám tử. Chủ tiệm có năng lực đặc biệt: có thể dùng những món đồ cũ đưa người khác quay về quá khứ để khám phá những bí mật chưa từng được biết đến. Dù đã là vợ, cả ba vẫn mong muốn khẳng định giá trị riêng. Vì thế, họ quyết định ở lại cửa hàng, đổi tên thành “Mỹ Kiều Nương Thám Án Xã”, chuyên giúp đỡ người khác giải quyết những vụ việc khó khăn. Từ đó, ba người bắt đầu một cuộc sống song song độc đáo: ban ngày điều tra phá án, ban đêm trở về làm những người vợ hiền trong gia đình.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chu Gia Hy","avatar":""},{"name":"Lý Thánh Dụ","avatar":""},{"name":"Vũ Kim Trì","avatar":""},{"name":"Quách Thường Huy","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mei Jiao Niang Tan An She","Beautiful Girl Detective Agency","美娇娘探案社"]', 1784690324148);
