INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuot-tam-kiem-soat', 'Vượt Tầm Kiểm Soát', 'Out Of Control', 'https://phimimg.com/upload/vod/20250913-1/2304f1aaca62ffcee4568b831e30ee9a.jpg', 'https://phimimg.com/upload/vod/20250913-1/c1d9a7dce7fb96903af62cdb1dd46c4b.jpg', '<p>Bộ phim kể về những năm đầu thời Dân Quốc, khi một “cảnh sát tạm thời” tên Phạm Cát An muốn tìm cơ hội được chính thức bổ nhiệm nên đã hợp tác với “kẻ lưu manh đường phố” Tiểu Lãng Đầu để dựng nên một vụ án giả. Không ngờ họ lại rơi vào vòng xoáy của hàng loạt vụ giết người liên hoàn, trong đó có cả vụ sát hại vị cảnh trưởng già. Trong quá trình điều tra của cảnh sát, Phạm Cát An không chỉ mất hy vọng thăng chức mà anh cùng Tiểu Lãng Đầu còn ngày càng bị tình nghi là hung thủ. Những vụ án mạng liên tiếp đã phá vỡ sự yên bình của Bào Tử Lĩnh. Sau muôn vàn gian khó, hai người cuối cùng đã vạch trần bí ẩn của vụ án giết người liên hoàn và bắt được hung thủ thực sự.</p>', 'Hoàn Tất (56/56)', 56, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Thụ Lâm","avatar":""},{"name":"Văn Tùng","avatar":""},{"name":"Mao Lâm Lâm","avatar":""},{"name":"Châu Vân Bằng","avatar":""},{"name":"Điền Nga","avatar":""},{"name":"Vương Tiểu Hổ","avatar":""},{"name":"Lâm Uy","avatar":""},{"name":"Triệu Chấn Đình","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["一本正经.Out.of.Control","Out of Control","一本正经"]', 1784690324148);
