INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-lai-nam-1938', 'Trở Lại Năm 1938', 'The Blazing Path: Back To 1938', 'https://phimimg.com/upload/vod/20250913-1/52377bdf2fce627f2710f19c58fa2f44.jpg', 'https://phimimg.com/upload/vod/20250913-1/05222c55f3419bdc0e5ca5172f0bd9fc.jpg', '<p>Nam thanh niên Mã Soái – một người mê thể nghiệm kịch nói, trong quá trình tham gia trải nghiệm vở kịch “Liêu Nguyên”, đã bất ngờ mơ thấy mình quay trở lại thời Dân Quốc, bước vào chính câu chuyện của vở kịch. Ban đầu, anh tưởng rằng lịch sử chân thực cũng giống như một trò chơi, chỉ cần chọn đúng vài phương án là có thể dễ dàng vượt qua. Nhưng không ngờ anh liên tiếp thất bại, bị mắc kẹt trong vòng lặp của giấc mơ. Trong khoảng thời gian đó, Mã Soái tận mắt chứng kiến những câu chuyện bi tráng phía sau các anh hùng kháng Nhật năm 1938, và cuối cùng anh cũng thấu hiểu sâu sắc rằng cuộc sống hòa bình, hạnh phúc hiện tại chính là được đổi lấy bằng sinh mạng và sự hy sinh của biết bao liệt sĩ cách mạng.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cảnh Nghiên Tuấn","avatar":""},{"name":"Viên Minh Trạch","avatar":""},{"name":"Diễm Đan Thần","avatar":""},{"name":"Lưu Đằng Viễn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["燎原之重回1938"]', 1784690324148);
