INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bua-yeu-o-quan-bar-hongsi', 'Bùa Yêu Ở Quán Bar Hongsi', 'Love Magic At Hongsi Bar', 'https://phimimg.com/upload/vod/20250913-1/dd7ec7cf1eb71b9bf266bdf6f8e6af65.jpg', 'https://phimimg.com/upload/vod/20250913-1/1dc64043d10e470539da8f988a81c176.jpg', '<p>Hong-shi, nữ chính của bộ phim được thừa hưởng từ bà ngoại một loại tình dược, chỉ cần uống vào sẽ khiến người ta say đắm trong tình yêu. Sau cuộc chia tay đầy đau khổ, Hong-shi đã bước vào một chuyện tình đầy sóng gió và đam mê.</p>', 'Hoàn Tất (55/55)', 55, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324148);
