INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mr-robot', 'Mr. Robot', 'Mr.Robot', 'https://phimimg.com/upload/vod/20250913-1/107031eef3adc4c383c3e27d14c18f3f.jpg', 'https://phimimg.com/upload/vod/20250913-1/86cc20bb3977fdb41f966b5ccad4c86c.jpg', '<p>Trong một thế giới tương lai nơi robot trở nên phổ biến, Tae-pyeong vô tình bị nhập vào thân xác robot sau một tai nạn bất ngờ. Anh gặp Nana – cô bé đang bị đe dọa tính mạng bởi người chú độc ác, kẻ đã giết anh trai cô để chiếm đoạt công ty. Đây là câu chuyện về một robot hy sinh toàn bộ cơ thể mình để bảo vệ một đứa trẻ đang gặp nguy hiểm.</p>', 'Full', 1, 'hoathinh', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Sung-young","avatar":""},{"name":"Kim Yeon-woo","avatar":""},{"name":"Lee Ho-san","avatar":""},{"name":"An Young-mi","avatar":""},{"name":"Lee Dal-lae","avatar":""},{"name":"Hwang Dong-hyun","avatar":""},{"name":"Kim Dong-hyun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Miseuteo robot","Mr. Robot","미스터 로봇"]', 1784690324148);
