INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-giai-dich-vuong-phi', 'Tấn Giai Đích Vương Phi', 'The Queen Of Attack', 'https://phimimg.com/upload/vod/20250830-1/d367379c6e3893c7148b92d279d1a554.jpg', 'https://phimimg.com/upload/vod/20250830-1/9257385327db7e9cc6108ea65818c889.jpg', '<p>Người thừa kế tước vị vương gia Tiêu Hiển tình cờ gặp người thương ở dân gian là Lâm Hồng Nhi, bèn sai người đi tìm, nhưng Từ Tử Nghi có dung mạo giống hệt Lâm Hồng Nhi đã mạo danh cô. Để giữ bí mật, Từ gia đã sát hại cả nhà Lâm Hồng Nhi, đồng thời khiến cô bị hủy hoại dung nhan. Được thần y bí ẩn Thân Đồ Vũ cứu giúp, Lâm Hồng Nhi thay đổi diện mạo, lấy tên là Hồng Lâm Lang, bắt đầu con đường báo thù.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Úc Thông","avatar":""},{"name":"Đại Cao Chính","avatar":""},{"name":"Tào Tuấn Tường","avatar":""},{"name":"Hoa Văn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Queen Takedown","进阶的王妃"]', 1784690324148);
