INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-nao-cung-co-ngay-nay', 'Năm Nào Cũng Có Ngày Này', 'The Circle Of Life', 'https://phimimg.com/upload/vod/20250911-1/ce9feee6a92018f6b08825d80c253349.jpg', 'https://phimimg.com/upload/vod/20250911-1/ba9c8751d9db93b98977d78ac0f42f69.jpg', '<p>Kiếp trước, Khương Tuế bị Tống Nghiên đẩy từ sân thượng xuống và thiệt mạng. Mười năm sau, cô trùng sinh và trở thành Hứa Kim Hạ, con gái sáu tuổi của chính Tống Nghiên. Âm thầm nhẫn nhịn và chờ đợi thời cơ, cô quyết tâm xé toạc bộ mặt đạo đức giả của giới hào môn, truy tìm tung tích của mẹ ruột và bắt kẻ thù phải trả nợ máu. Hãy cùng xem vị tiểu thư trùng sinh này sẽ đảo ngược vận mệnh của kiếp trước như thế nào nhé!</p>', 'Hoàn Tất (75/75)', 75, 'series', 'completed', 20, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phim Ngắn","slug":"phim-ngan","id":"4f02d28224c0747511790d57fbb63a62"}]', '[]', 1784690324148);
