INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-loi-lo-dung-phai-em-roi', 'Xin Lỗi, Lỡ Đụng Phải Em Rồi', 'Sorry I Love You', 'https://phimimg.com/upload/vod/20250911-1/ceab0b7ae9bc118df4b6ec42ee78f58d.jpg', 'https://phimimg.com/upload/vod/20250911-1/0cac1a14c12ed39508149d2c9f4e0895.jpg', '<p>Bộ phim kể về câu chuyện một nhân viên văn phòng bình thường, tin rằng thực lực mới là trên hết, trong một thế giới coi trọng ngoại hình đã từng bước trưởng thành. Nhân vật chính Dịch Phong có ngoại hình bình thường, ăn mặc xuề xòa, thậm chí hơi lôi thôi. Vì hoàn cảnh gia đình, cô chưa bao giờ quan tâm đến vẻ bề ngoài, chỉ tin rằng nhờ chăm chỉ nỗ lực thì sẽ đạt được thành công. Với những người bóng bẩy, đẹp đẽ, Dịch Phong luôn giữ thái độ phủ định. Thế nhưng sau một lần thất bại, cô bất ngờ có được siêu năng lực nhìn thấy điểm số nhan sắc. Từ đó, cô bắt đầu sùng bái và theo đuổi vẻ đẹp bề ngoài, nhưng lại vô tình đi lạc hướng. Cuối cùng, sau nhiều biến cố, cô dần trở về với bản tâm, nhận ra giá trị thật sự của bản thân.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhou Yuhang","avatar":""},{"name":"Jocelyn Choi","avatar":""},{"name":"Zaidan Tayir","avatar":""},{"name":"Chou Ziyi","avatar":""},{"name":"Yongli Qiu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Dui Bu Qi, Wo Ke Dao Ni Le","对不起，我磕到你了"]', 1784690324148);
