INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-trong-bi-mat', 'Yêu Trong Bí Mật', 'Love Lurking', 'https://phimimg.com/upload/vod/20250722-1/e5ed4521535f44bcb45ed0a7462a60de.jpg', 'https://phimimg.com/upload/vod/20250722-1/b10655c9bec4d54a4cdbbdb9ed0e7970.jpg', '<p>Nữ bác sĩ ngoại khoa Cố Niệm đã cứu sống K, một tên buôn ma túy, nhưng sau đó lại rơi vào hang ổ của trùm ma túy. Để giữ mạng sống, Cố Niệm đã nhanh trí thương lượng với kẻ bí ẩn K. Trong những lần kề cận ranh giới sống chết, cả hai dần nảy sinh tình cảm. Vì bảo vệ Cố Niệm, K đã liều mạng với trùm ma túy Bành Lợi, không rõ sống chết Nửa năm sau, Cố Niệm bất ngờ gặp được Tống Tiềm, người có ngoại hình giống hệt K, nhưng anh ta lại lạnh lùng phủ nhận mình là K mà là tổng giám đốc của tập đoàn Ngụy Thị và đã có vợ chưa cưới. Cố Niệm dây dưa rối rắm với anh ta, cuối cùng thất vọng rời đi. Nhưng khi Cố Niệm rơi vào nguy hiểm trong lúc điều tra sự thật về cái chết của mẹ, Tống Tiềm, người tưởng như đối đầu với cô lại bao lần cứu cô khỏi hiểm nguy. Cũng chính lúc đó, Cố Niệm mới biết được thân phận thực sự của Tống Tiềm…</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Binh Trác","avatar":""},{"name":"Triệu Tịch Tịch","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["逆风之恋","Love Against the Gale","恋爱潜伏"]', 1784690324148);
