INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuoc-tam', 'Chước Tâm', 'Fall In You', 'https://phimimg.com/upload/vod/20250817-1/afd7eb51738e71155fe5a5eef52d1d03.jpg', 'https://phimimg.com/upload/vod/20250817-1/8d161a9e13d09c27146f3978fd70be72.jpg', '<p>Kiều Ngôn trở thành trẻ mồ côi sau cái chết đột ngột của cha mẹ và quay trở lại nhà họ Cố để điều tra vụ việc. Cô tiếp cận Cố Tĩnh Uyên, con nuôi của ông nội, bằng cách giả vờ yếu đuối, nhưng anh vẫn lạnh lùng và thông minh, dẫn đến cuộc đấu trí giữa hai người. Khi anh liều mạng cứu cô khỏi đám cháy và bày tỏ mong muốn bảo vệ cô và gia tộc, tình cảm nảy sinh. Mối tình cấm kỵ của họ đối mặt với âm mưu và thử thách, buộc họ phải giấu kín trái tim và bảo vệ nhau bằng mọi giá giữa sóng gió và nguy hiểm.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Mục Thần","avatar":""},{"name":"Phàn Trị Hân","avatar":""},{"name":"Lý Nghệ Đồng","avatar":""},{"name":"Cốc Lam Đế","avatar":""},{"name":"Vương Tịch Duyệt","avatar":""},{"name":"Thái Tân Dương","avatar":""},{"name":"Do Lập Bình","avatar":""},{"name":"Ngô Thuần Nhất","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["再说一次我爱你","身陷","灼心"]', 1784690324148);
