INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuoc-tam', 'Chước Tâm', 'Fall In You', 'chước tâm fall in you lý mục thần phàn trị hân lý nghệ đồng cốc lam đế vương tịch duyệt thái tân dương do lập bình ngô thuần nhất 再说一次我爱你 身陷 灼心', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ve-doi-2025', 'Về Đội', 'The Long Way Back', 'https://phimimg.com/upload/vod/20250827-1/63c5ef721628ff0444e90213f7773579.jpg', 'https://phimimg.com/upload/vod/20250827-1/dc17372aec8e0752329316261ef5edf2.jpg', '<p>Nhận được sự chỉ đạo trọng điểm từ Tổng cục Phát thanh và Truyền hình Quốc gia, bộ phim nhằm hướng tới kỷ niệm 80 năm ngày thắng lợi của Cuộc kháng chiến Nhân dân Trung Quốc chống Nhật và Chiến tranh thế giới chống Phát xít. Phim do Cao Mãn Đường, Lý Lập, Nhữ Thịnh và Lý Châu làm biên kịch, với sự chỉ đạo của hai đạo diễn Tang Khê Xuyên và Triệu Dương. Kịch bản phim được thể hiện qua góc nhìn trưởng thành của những người lính bình thường trong quân đội, lấy cái nhỏ để phản ánh cái lớn, tái hiện lại quá trình kháng chiến toàn dân kéo dài suốt mười bốn năm kể từ &quot;Sự kiện ngày 18 tháng 9&quot;. Nội dung phim tập trung khắc họa một giai đoạn lịch sử đấu tranh gian khổ và khốc liệt nhất của quân kháng chiến Đông Bắc và nhân dân vùng Đông Bắc dưới sự lãnh đạo của Đảng Cộng sản trong cuộc chiến chống lại ách xâm lược của đế quốc Nhật Bản.</p>', 'Hoàn Tất (34/34)', 34, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hồ Quân","avatar":""},{"name":"Lí Nại Văn","avatar":""},{"name":"Trần Tịnh Khả","avatar":""},{"name":"Viên San San","avatar":""},{"name":"Nhậm Bân","avatar":""},{"name":"Tống Gia Đằng","avatar":""},{"name":"Tưởng Hân","avatar":""},{"name":"Lâm Vĩnh Kiện","avatar":""},{"name":"Nghê Đại Hồng","avatar":""},{"name":"Lưu Bội Kỳ","avatar":""},{"name":"Ngải Lệ Á","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["八十八国际旅","Gui Dui","The Long Way Back","归队"]', 1784690324148);
