INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ve-doi-2025', 'Về Đội', 'The Long Way Back', 'về đội the long way back hồ quân lí nại văn trần tịnh khả viên san san nhậm bân tống gia đằng tưởng hân lâm vĩnh kiện nghê đại hồng lưu bội kỳ ngải lệ á 八十八国际旅 gui dui the long way back 归队', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vinh-barron', 'Vịnh Barron', 'Barron''s Cove', 'https://phimimg.com/upload/vod/20250911-1/e80b56fea176b45152b1124cf3ddbc37.jpg', 'https://phimimg.com/upload/vod/20250911-1/a9bb7091f1c0bd399cb62025f18d131a.jpg', '<p>Khi cậu con trai nhỏ bị một bạn học sát hại dã man, người cha đau khổ với quá khứ bạo lực đã bắt cóc chính đứa trẻ gây tội. Hành động này châm ngòi cho một cuộc truy lùng điên cuồng, dẫn đầu bởi một chính trị gia đầy quyền lực — cũng chính là cha của cậu bé bị bắt cóc.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Garrett Hedlund","avatar":""},{"name":"Hamish Linklater","avatar":""},{"name":"Brittany Snow","avatar":""},{"name":"Christian Convery","avatar":""},{"name":"Tramell Tillman","avatar":""},{"name":"Raúl Castillo","avatar":""},{"name":"Stephen Lang","avatar":""},{"name":"Marc Menchaca","avatar":""},{"name":"Guy Lockard","avatar":""},{"name":"Peter McRobbie","avatar":""},{"name":"Danny Mastrogiorgio","avatar":""},{"name":"Elia Monte-Brown","avatar":""},{"name":"Kristina Klebe","avatar":""},{"name":"Jonathan Holtzman","avatar":""},{"name":"Veracity Butcher","avatar":""},{"name":"May","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Barron''s Cove"]', 1784690324148);
