INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-giau-2025', 'Ẩn Giấu', 'What We Hide', 'https://phimimg.com/upload/vod/20250911-1/e884910e19a5ac21932df7bdc10fde87.jpg', 'https://phimimg.com/upload/vod/20250911-1/57959cabfacc2071b053b3fc084ee1d3.jpg', '<p>Sau khi người mẹ qua đời vì dùng thuốc quá liều, hai chị em gái lo sợ sẽ bị hệ thống nuôi dưỡng chia cắt nên quyết định giấu xác. Nhưng lời nói dối ấy có nguy cơ bị phơi bày, và họ buộc phải đối mặt với câu hỏi: sẵn sàng đi bao xa để giữ kín bí mật này?</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mckenna Grace","avatar":""},{"name":"Jojo Regina","avatar":""},{"name":"Jesse Williams","avatar":""},{"name":"Dacre Montgomery","avatar":""},{"name":"Forrest Goodluck","avatar":""},{"name":"Fernanda Andrade","avatar":""},{"name":"Malia Baker","avatar":""},{"name":"Shellita Boxie","avatar":""},{"name":"Cronin Cullen","avatar":""},{"name":"Layne Harper","avatar":""},{"name":"Lily Jane","avatar":""},{"name":"Lennon Blue","avatar":""},{"name":"Quinn Blue","avatar":""},{"name":"Brad Beyer","avatar":""},{"name":"Rita Buchan","avatar":""},{"name":"Abigail Dolan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Spider & Jessie","What We Hide"]', 1784690324148);
