INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('an-giau-2025', 'Ẩn Giấu', 'What We Hide', 'ẩn giấu what we hide mckenna grace jojo regina jesse williams dacre montgomery forrest goodluck fernanda andrade malia baker shellita boxie cronin cullen layne harper lily jane lennon blue quinn blue brad beyer rita buchan abigail dolan spider & jessie what we hide', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('roi-vao-luoi-tinh-2025', 'Rơi Vào Lưới Tình', 'Fall In Love', 'https://phimimg.com/upload/vod/20250910-1/04981f19c6bf926d7068e6c9affe2b61.jpg', 'https://phimimg.com/upload/vod/20250910-1/febe2622578d77b030553254a87ade76.jpg', '<p>Nội dung xoay quanh câu chuyện gặp gỡ định mệnh giữa một cô gái trẻ hoạt bát và một chàng trai trầm lặng. Từ một sự kiện bất ngờ, hai người bị cuốn vào vòng xoáy vừa hiểu lầm vừa rung động, dần dần cùng nhau vượt qua những khác biệt tính cách và hoàn cảnh. Trong quá trình đó, họ học cách trân trọng từng khoảnh khắc quý giá, khám phá ý nghĩa thật sự của tình yêu và sự đồng hành.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Kỳ Mỹ Hàn","avatar":""},{"name":"Vương Hiên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yi Ke Qian Jin","送你一颗小桃心","一刻千金"]', 1784690324148);
