INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-trong-mot-ngay-suot-tram-nghin-nam', 'Sống Trong Một Ngày Suốt Trăm Nghìn Năm', 'The Time Of Rebirth', 'https://phimimg.com/upload/vod/20250828-1/507e3d2fb1a536e2b26232e6fd6da2af.jpg', 'https://phimimg.com/upload/vod/20250828-1/38070d4e92a63cf906c22b0edac24b7a.jpg', '<p>Bộ phim kể về nhân vật Lâm Việt bị mắc kẹt trong một vòng lặp thời gian, sống đi sống lại cùng một ngày suốt mười vạn năm. Anh chỉ có thể thoát ra khỏi vòng lặp này sau khi vô tình cứu được tiểu thánh nữ của Vong Tiên Tông. Kể từ đó, với kinh nghiệm và kiến thức tích lũy trong mười vạn năm, Lâm Việt bắt đầu hành trình phiêu lưu của mình tại đại lục Hồng Mông. Cùng lúc đó, những đối thủ mà anh đã không thể đánh bại trong suốt mười vạn năm qua cũng dần thức tỉnh từ trong bóng tối của thế giới này.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Hạo Hiên","avatar":""},{"name":"Lỗ Chiếu Hoa","avatar":""},{"name":"Vương Chi Nhất","avatar":""},{"name":"Loan Lôi Anh","avatar":""},{"name":"Mạnh Thiên Âm","avatar":""},{"name":"Trần Thiên Hoa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["我被困在同一天十万年"]', 1784690324148);
