INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-tam-biet-de-nghe', 'Lời Tạm Biệt Dễ Nghe', 'The Shore Of Life', 'https://phimimg.com/upload/vod/20250910-1/37678413ba04c339b5664982d14f2d7f.jpg', 'https://phimimg.com/upload/vod/20250910-1/db0ff84841fef07eee7e5ebbbf3bdd1d.jpg', '<p>Người mẹ đơn thân Ứng Nặc thân mang trọng bệnh, dự định gửi gắm con gái cho người cha đã nhiều năm xa cách là Ứng Đại Hải. Trong quãng thời gian cuối cùng của đời mình, cô gắng gượng vượt qua nỗi sợ cái chết, dồn hết tâm lực để bảo vệ con. Còn người cha Ứng Đại Hải mang nỗi lòng phức tạp đối với con gái Ứng Nặc cũng đã diễn giải trọn vẹn hình hài ấm áp của tình phụ tử Trung Hoa. Giữa khung cảnh chăm sóc cuối đời, một câu chuyện đan xen bi thương và ấm áp đã bắt đầu…</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chung Tân Đồng","avatar":""},{"name":"Lâm Động Phủ","avatar":""},{"name":"Đào Huệ Mẫn","avatar":""},{"name":"Trần Y Thi","avatar":""},{"name":"Hầu Đổng Giang","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["完美告别","好好说再见"]', 1784690324148);
