INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('loi-tam-biet-de-nghe', 'Lời Tạm Biệt Dễ Nghe', 'The Shore Of Life', 'lời tạm biệt dễ nghe the shore of life chung tân đồng lâm động phủ đào huệ mẫn trần y thi hầu đổng giang 完美告别 好好说再见', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-nhan-kiet-chu-tru-ma-giang-ma-chu', 'Địch Nhân Kiệt: Chú Trừ Ma (Giáng Ma Chú)', 'The Descent Curse Of Di Renjie', 'https://phimimg.com/upload/vod/20250828-1/fa64bdafe635aca7fc39dfbedcb72016.jpg', 'https://phimimg.com/upload/vod/20250828-1/af2251c7e4bef8cf952147b83c48fb6f.jpg', '<p>Năm Thiên Thụ Nguyên Niên, trong dân gian yêu quái quấy phá, dị sự liên tiếp xảy ra. Địch Nhân Kiệt nhận lệnh bí mật điều tra những vụ án kỳ quái. Gần đây, ông nghe tin có tà chú hàng ma triệu hồi vong linh trở lại nhân gian, gây hại cho một vùng, liền nhanh chóng bắt tay vào điều tra. Khi chân tướng vụ án đầy biến hóa dần hiện ra, Địch Nhân Kiệt lại bị dẫn dắt đến một sự thật đáng sợ hơn — thì ra trên đời này thực sự tồn tại “vong linh”…</p>', 'Full', 1, 'single', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Hạo Dân","avatar":""},{"name":"Ân Tịnh","avatar":""},{"name":"Cận Ninh","avatar":""},{"name":"Lại Hi","avatar":""},{"name":"Lưu Cẩn","avatar":""},{"name":"Thạch Tuyên Như","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Địch Nhân Kiệt: Giáng Ma Chú","The Descent Curse of Di Renjie","狄仁杰之降魔咒"]', 1784690324148);
