INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('honey-dung', 'Honey Đừng!', 'Honey Don''t!', 'https://phimimg.com/upload/vod/20250827-1/dc5cb6690ce017766ed4fa2f6cf50682.jpg', 'https://phimimg.com/upload/vod/20250827-1/80620d8f8df1ea452fc74128232bb97c.jpg', '<p>Honey O’Donahue, một nữ thám tử tư ở thị trấn nhỏ, bắt đầu điều tra hàng loạt cái chết kỳ lạ có liên quan đến một nhà thờ bí ẩn.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Margaret Qualley","avatar":""},{"name":"Aubrey Plaza","avatar":""},{"name":"Chris Evans","avatar":""},{"name":"Charlie Day","avatar":""},{"name":"Lera Abova","avatar":""},{"name":"Jacnier","avatar":""},{"name":"Gabby Beans","avatar":""},{"name":"Talia Ryder","avatar":""},{"name":"Kristen Connolly","avatar":""},{"name":"Josh Pafchek","avatar":""},{"name":"Don Swayze","avatar":""},{"name":"Lena Hall","avatar":""},{"name":"Alexander Carstoiu","avatar":""},{"name":"Kale Browne","avatar":""},{"name":"Christian Antidormi","avatar":""},{"name":"Billy Eichner","avatar":""},{"name":"Kinna McInroe","avatar":""},{"name":"Sean J. Dil","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Honey, non!","Милая, не надо!","Szivi ne!","Honey Don''t!"]', 1784690324148);
