INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-hay-la-chet', 'Hôn Hay Là Chết', 'Kiss Or Die', 'https://phimimg.com/upload/vod/20250909-1/0451e047c3139a2bc64487fa6f4601a0.jpg', 'https://phimimg.com/upload/vod/20250909-1/bb84812e5381549364d049c3c0a3a109.jpg', '<p>Những nam danh hài đối đầu trong một vở kịch ứng biến nóng bỏng, nơi họ phải chống lại sự quyến rũ khó cưỡng của các bạn diễn gợi cảm và cuối cùng trao nụ hôn định mệnh.”</p>', 'Hoàn Tất (6/6)', 6, 'tvshows', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Gekidan Hitori","avatar":""},{"name":"Ken Yahagi","avatar":""},{"name":"Ryota Yamasato","avatar":""},{"name":"Miyū Ikeda","avatar":""},{"name":"Mamoru Miyano","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["デスキスゲーム いいキスしないと死んじゃうドラマ"]', 1784690324148);
