INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-mach-hong-tran', 'Tử Mạch Hồng Trần', 'Kill To Love', 'https://phimimg.com/upload/vod/20250826-1/586569d583bf512c8ad003e73a9fc110.jpg', 'https://phimimg.com/upload/vod/20250826-1/c36e723def793196d2444169d5510beb.jpg', '<p>Trong thời loạn lạc, hoàng tử Nam quốc Tiêu Vân Trạch và thích khách Triệu Tử Ngạc tình cờ gặp gỡ, nảy sinh tình yêu. Thế nhưng một cuộc biến động quyền lực đã buộc họ phải chia ly. Nhiều năm sau, Triệu Tử Ngạc trở thành hoàng đế Bắc quốc. Trên con đường chinh phạt để thống nhất Trung Nguyên, y phải đối diện với tình nhân năm xưa – để rồi tình yêu và số mệnh một lần nữa đối đầu khốc liệt.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Đĩnh","avatar":""},{"name":"Trình Phóng","avatar":""},{"name":"Mi Kim","avatar":""},{"name":"Trương Triết Tú","avatar":""},{"name":"Dương Thư Vĩ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["山河永寂","Zi Mo Hong Chen","ม่านหมอกกลางทางแดง","紫陌红尘"]', 1784690324148);
