INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hien-ngu', 'Hiến Ngư', 'When Destiny Brings The Demon', 'https://phimimg.com/upload/vod/20250816-1/9d2f4ee7f4f131f23a8de09669648ca2.jpg', 'https://phimimg.com/upload/vod/20250816-1/0cf65fc65804a01c9c35155750e7672f.jpg', '<p>Bộ phim xoay quanh Trâu Nhạn – một “nô lệ công sở” điển hình thời hiện đại – vô tình xuyên không đến thế giới tu tiên, trở thành Liêu Đình Nhạn, đệ tử của Thanh Cốc Thiên, đồng thời bị tuyển chọn vào hàng ngũ một trăm đệ tử hầu hạ sư tổ Tư Mã Tiêu. Bề ngoài, Tư Mã Tiêu được cho là đang bế quan ở núi Tam Thánh, nhưng thực chất hắn đã bị phong ấn suốt 500 năm, hình thành nên tính cách u ám, lầm lì, cáu kỉnh dễ nổi nóng. Hắn vô cùng căm hận Tiên Phủ Canh Thần và luôn nuôi ý định trả thù. Liêu Đình Nhạn thực chất là thân phận của một thích khách do Ma Vực cài vào, nhưng Trâu Nhạn không hề biết &quot;bản thân&quot; còn che giấu thiết lập này nên ngay từ lần đầu chạm mặt, cô suýt nữa đã mất mạng dưới tay Tư Mã Tiêu. Sau thời gian tiếp xúc, nhờ năng lực “lời thề nói thật”, Tư Mã Tiêu dần nhận ra cô không hề có ý định ám sát hay lợi dụng mình. Thái độ này khiến hắn cảm thấy tò mò, nảy sinh hứng thú, từ đó bắt đầu chuyện tình dây dưa nhiều kiếp giữa ma vương phản diện và cô gái lười hệ chữa lành.</p>', 'Hoàn Tất (33/33)', 33, 'series', 'completed', 12, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Phi Vũ","avatar":""},{"name":"Vương Ảnh Lộ","avatar":""},{"name":"Vương Ý Đình","avatar":""},{"name":"Cao Hàn","avatar":""},{"name":"Ngô Vũ Hằng","avatar":""},{"name":"Vương Á Gia","avatar":""},{"name":"Bảo Kiếm Phong","avatar":""},{"name":"Hà Trung Hoa","avatar":""},{"name":"Trần Thư Quân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Xian Yu","向师祖献上咸鱼","Xiang Shi Zu Xian Shang Xian Yu","Quand le destin réveille le démon","Когда судьба преподносит демона","วาสนาของปลาเค็ม","向師祖獻上咸魚","Offering Salted Fish","Fish Offer","Offering Fish","Offering Salted Fish to Master","Long for Fish","When Destiny Brings the Demon","献鱼"]', 1784690324148);
