INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hien-ngu', 'Hiến Ngư', 'When Destiny Brings The Demon', 'hiến ngư when destiny brings the demon trần phi vũ vương ảnh lộ vương ý đình cao hàn ngô vũ hằng vương á gia bảo kiếm phong hà trung hoa trần thư quân xian yu 向师祖献上咸鱼 xiang shi zu xian shang xian yu quand le destin réveille le démon когда судьба преподносит демона วาสนาของปลาเค็ม 向師祖獻上咸魚 offering salted fish fish offer offering fish offering salted fish to master long for fish when destiny brings the demon 献鱼', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-cung-ke', 'Thanh Cung Kế', 'The Imperial Concubine''s Plan', 'https://phimimg.com/upload/vod/20250908-1/5291e9c32fbbc27138b7cd3235a417e6.jpg', 'https://phimimg.com/upload/vod/20250908-1/7769a590899a0d5d097b2dfe3303f8cd.jpg', '<p>Nữ nhi của thợ săn, Ngọc Lan, vì cứu giá mà được hoàng đế đưa vào cung, đồng thời bí mật điều tra vụ án oan khuất khiến cha nàng – Cơ Nghiêm Luân bị hại. Nhờ manh mối từ ngọc bội Thanh Long của thích khách để lại, Ngọc Lan từng bước khoanh vùng nghi phạm trong cung nhưng liên tiếp rơi vào bẫy hãm hại. Bằng trí tuệ và mưu lược, nàng hóa giải nguy nan, dần thăng tiến thành Lan phi, được Thái hậu tín nhiệm giao quyền quản lý lục cung. Khi chân tướng hé lộ, Ngọc Lan mới biết cái chết của cha thực chất là kế hoạch tự hiến thân, do cha nàng và Hoàng đế hợp mưu để thanh trừng triều đình. Cuối cùng, Hoàng hậu hối cải, Tể tướng bị trừng phạt. Ngọc Lan lựa chọn cùng Hoàng đế nắm tay trị vì thiên hạ, chung tình nghĩa, kiến tạo thịnh thế.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dư Âm","avatar":""},{"name":"Liễu Ninh","avatar":""},{"name":"Diệp Hạo Nhiên","avatar":""},{"name":"Lý Hựu Lâm","avatar":""},{"name":"Dương Hồng","avatar":""},{"name":"Ngô Mộng Nguyên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Qing Gong Ji","Tales of Palace Schemes","清宫计"]', 1784690324148);
