INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-tan-truong-an', 'Dữ Tấn Trường An', 'Shadow Love', 'https://phimimg.com/upload/vod/20250824-1/6987e7f2148df2bedbece8c7600141ee.jpg', 'https://phimimg.com/upload/vod/20250824-1/f88e0e6be73d6ff477f72ad725ffc464.jpg', '<p>Câu chuyện kể về vị nữ tướng Lê Sương nhà Thái Tấn, trong một lần tình cờ nhặt được một người đàn ông mất trí nhớ, đặt tên là Tấn An. Tấn An hết lòng hết dạ bên cạnh Lê Sương, hai người dần nảy sinh tình cảm. Không ngờ tới một ngày Tấn An dần nhớ lại thân phận thật sự của mình, hóa ra chàng chính là vương gia nước địch, hai người từng hẹn ước bạc đầu giờ đành phải đối đầu nhau trên chiến trường. Vốn đã chán ghét chiến tranh, họ quyết định cùng nhau tìm cách hóa giải nguy cơ, bảo vệ lẽ phải trong tim.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tống Di","avatar":""},{"name":"Thừa Lôi","avatar":""},{"name":"Bất Văn Quân","avatar":""},{"name":"Sử Trác","avatar":""},{"name":"Quan Hồng","avatar":""},{"name":"Kỷ Tiểu Băng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["与晋长安","ปีศาจราตรี","Shadow Love"]', 1784690324148);
