INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-vu-phu-ho', 'Mật Vụ Phụ Hồ', 'A Working Man', 'https://phimimg.com/upload/vod/20250406-1/834abb05b10d032c2589fcd39625ca2a.jpg', 'https://phimimg.com/upload/vod/20250406-1/7c28ab6d499bc41ee5ba9e33f265a7cc.jpg', '<p>Levon Cade - cựu biệt kích tinh nhuệ thuộc lực lượng Thủy quân Lục chiến Hoàng gia Anh. Sau khi nghỉ hưu, anh sống cuộc đời yên bình là một công nhân xây dựng tại Chicago (Mỹ). Levon có mối quan hệ rất tốt với gia đình ông chủ Joe Garcia (Michael Peña). Một ngày nọ, cô con gái tuổi teen Jenny (Arianna Rivas) của Joe bị bắt cóc khiến chàng cựu quân nhân phải sử dụng lại các kỹ năng giết chóc của mình để giúp đỡ.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Anh', 1, '[{"name":"Jason Statham","avatar":""},{"name":"David Harbour","avatar":""},{"name":"Michael Peña","avatar":""},{"name":"Jason Flemyng","avatar":""},{"name":"Arianna Rivas","avatar":""},{"name":"Noemi Gonzalez","avatar":""},{"name":"Emmett Scanlan","avatar":""},{"name":"Eve Mauro","avatar":""},{"name":"Maximilian Osinski","avatar":""},{"name":"Kristina Poli","avatar":""},{"name":"Andrej Kaminsky","avatar":""},{"name":"Isla Gie","avatar":""},{"name":"Chidi Ajufo","avatar":""},{"name":"Alana Boden","avatar":""},{"name":"Sophie-Louise Craig","avatar":""},{"name":"David Witts","avatar":""},{"name":"Daniel Lundh","avatar":""},{"name":"Pi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Levon''s Trade","打工汉","莱文的交易","İşləyən Adam","Rescate implacable","Trabajador","重裝制裁","Ağır İşçi","La parole d''un homme","A Working Man"]', 1784690324148);
