INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-dinh-cao-den-vuc-sau', 'Từ Đỉnh Cao Đến Vực Sâu', 'Highest 2 Lowest', 'https://phimimg.com/upload/vod/20250907-1/07afbb79768974782af98eae3a4f102d.jpg', 'https://phimimg.com/upload/vod/20250907-1/7d3cebe39961e8661652b0a3ea94c5be.jpg', '<p>Sau khi bị nhắm tới trong một âm mưu tống tiền, một ông trùm âm nhạc quyền lực buộc phải chiến đấu vì gia đình và di sản của mình, đồng thời mắc kẹt trong lựa chọn đạo đức giữa sự sống và cái chết.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Denzel Washington","avatar":""},{"name":"Jeffrey Wright","avatar":""},{"name":"Ilfenesh Hadera","avatar":""},{"name":"Elijah Wright","avatar":""},{"name":"Aubrey Joseph","avatar":""},{"name":"A$AP Rocky","avatar":""},{"name":"John Douglas Thompson","avatar":""},{"name":"LaChanze","avatar":""},{"name":"Dean Winters","avatar":""},{"name":"Wendell Pierce","avatar":""},{"name":"Michael Potts","avatar":""},{"name":"Frederick Weller","avatar":""},{"name":"Rick Fox","avatar":""},{"name":"Rod Strickland","avatar":""},{"name":"Rosie Perez","avatar":""},{"name":"Anthony Ramos","avatar":""},{"name":"Nicholas Tu","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["천국부터 지옥까지","Highest to Lowest","Yüksəkdən Alçağa","כופר לא לו","Рай и Ад","З вершин до низин","З Небес на Землю","Highest 2 Lowest"]', 1784690324148);
