INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-nguoc-canelo-vs-crawford', 'Đếm Ngược: Canelo Vs Crawford', 'Countdown: Canelo vs. Crawford', 'https://phimimg.com/upload/vod/20250907-1/6aa6386fd31dcf07b33dd03eedf8f79f.jpg', 'https://phimimg.com/upload/vod/20250907-1/ee1406f9d302692c3990e8225ec78af2.jpg', '<p>Họ là những võ sĩ quyền Anh xuất sắc nhất thời đại này, nhưng ai sẽ trở thành người vĩ đại nhất? Cùng xem Canelo Álvarez và Terence Crawford chuẩn bị cho trận đấu không thể bỏ lỡ.</p>', 'Hoàn Tất (2/2)', 2, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Canelo Álvarez","avatar":""},{"name":"Terence Crawford","avatar":""},{"name":"Josh Brolin","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["倒计时：卡内洛·阿尔瓦雷斯 vs 特伦斯·克劳福德","Countdown: Canelo vs. Crawford"]', 1784690324148);
