INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-thu', 'Kẻ Thù', 'Enemigos', 'https://phimimg.com/upload/vod/20250907-1/86073476e5158d56aeee202158635a6d.jpg', 'https://phimimg.com/upload/vod/20250907-1/eba4cc4d2020f12732e741d9bac76622.jpg', '<p>Chimo tròn 18 tuổi và xuất thân từ một gia đình khiêm tốn và luôn ủng hộ cậu. Từ nhỏ, cậu đã bị bắt nạt, và ngay cả bây giờ, dù làm nhiều công việc khác nhau và mơ ước khởi nghiệp, cậu vẫn tiếp tục đối mặt với kẻ bắt nạt mình: El Rubio. Khi Chimo có cơ hội trả thù, cậu không bao giờ ngờ rằng hành động trả thù ban đầu lại có thể trở thành một tình bạn bất ngờ, thay đổi cuộc đời cả hai.</p>', 'Full', 1, 'single', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Christian Checa","avatar":""},{"name":"Hugo Welzel","avatar":""},{"name":"Estefanía de los Santos","avatar":""},{"name":"Luna Pamiés","avatar":""},{"name":"José María Peinado","avatar":""},{"name":"Sara Vidorreta","avatar":""},{"name":"José Manuel Poga","avatar":""},{"name":"Inma Sancho","avatar":""},{"name":"Belén Alghero","avatar":""},{"name":"María José Mariscal","avatar":""},{"name":"Natalia Braceli","avatar":""},{"name":"Tato Loché","avatar":""},{"name":"Adrián Hernández","avatar":""},{"name":"Jonathan Salmerón","avatar":""},{"name":"Carlos Medina","avatar":""},{"name":"Fel","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Enemigos"]', 1784690324148);
