INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-sat-1932', 'Ám Sát: 1932', 'Assassination: 1932', 'https://phimimg.com/upload/vod/20250907-1/597bb4c2fdeed1a3fc65cb2a27018154.jpg', 'https://phimimg.com/upload/vod/20250907-1/786df5623ed6b64d5811c5700f6181ca.jpg', '<p>Năm 1932, sau sự kiện “Nhất Nhị Bát Thượng Hải” (28/1/1932), Trung Quốc rơi vào khói lửa chiến tranh, Thượng Hải trở thành nơi giao tranh giữa thế lực Nhật Bản và các lực lượng cách mạng. Trong bối cảnh rối ren ấy, một nhóm chiến sĩ cảm tử nhận nhiệm vụ ám sát quan chức tay sai thân Nhật để phá tan âm mưu thôn tính. Họ vừa phải đối mặt với kẻ thù tàn bạo, vừa chống chọi với phản bội và thử thách lòng tin trong nội bộ. Âm mưu, tình cảm, lý tưởng và sinh mạng đều đặt lên bàn cân, viết nên một bản anh hùng ca đẫm máu nhưng hào hùng.</p>', 'Full', 1, 'single', 'completed', 20, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Lương Vĩ","avatar":""},{"name":"Lữ Lương Vĩ","avatar":""},{"name":"Trình Kỳ","avatar":""},{"name":"Cẩm Lãng","avatar":""},{"name":"Đường Hạo Uyên","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["An sha 1932","暗杀1932"]', 1784690324148);
