INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('so-u-bi-canh', 'Sở U Bí Cảnh', 'Tomb Of King Chu You', 'https://phimimg.com/upload/vod/20250616-1/97836c97fe96421e9e38aa7f451470d9.jpg', 'https://phimimg.com/upload/vod/20250616-1/9547c89eefca379948ef755932e1e039.jpg', '<p>Vào những năm đầu thời Dân Quốc, Ngô Kỳ - người thừa kế duy nhất của môn phái Phát Khâu chuyên về kỳ môn dị thuật, đã bị quân phiệt độc ác và thương hội Nhật Bản lợi dụng khi đi tìm tung tích sư phụ, bước vào cuộc hành trình mạo hiểm đầy chông gai. Dưới áp lực của cuộc chiến sinh tử và thế lực hắc ám, Ngô Kỳ đã khám phá ra truyền thuyết về &quot;Chúc Lộc Nhãn&quot; của nước Sở cổ đại và thành công đánh bại thương hội Nhật Bản.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Khố Đề Lai","avatar":""},{"name":"Văn Thanh","avatar":""},{"name":"Vương Khuê Vinh","avatar":""},{"name":"Thị Tuyên Nhi","avatar":""},{"name":"Đường Tân","avatar":""},{"name":"Nguyệt Đông Phong","avatar":""},{"name":"Cao Tử Cương","avatar":""},{"name":"Mai Gia Kỳ","avatar":""},{"name":"Điềm Nữu","avatar":""},{"name":"Viên Tường Nhân","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Гробница правителя Чу Ю","楚幽秘境"]', 1784690324148);
