INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pit-babe-2', 'Pit Babe 2', 'Pit Babe 2', 'https://phimimg.com/upload/vod/20250504-1/6fa9816ff2aa5109112e26fa0b6dc4bc.jpg', 'https://phimimg.com/upload/vod/20250504-1/a30a5bb8b11a2f74582cff6564529fb8.jpg', '<p>Phim kể về mối quan hệ phức tạp giữa Babe-tay đua xe nổi tiếng với danh hiệu, vua đường đua, và Charlie- một mọt sách gợi cảm với ước mơ được gia nhập một đội đua. Charlie muốn tham gia đội đua đến mức đồng ý với lời đề nghị kỳ lạ của Babe để là trở thành nô lệ của cậu. Khi Babe đánh mất trái tim của mình cho Charlie, cậu ta liên tục phát hiện ra rằng mối quan hệ không như cậu mong đợi, và mục đích thực sự của Charlie khi tiếp cận cậu là để tiêu diệt cậu.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 8, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Naret Promphaopun","avatar":""},{"name":"Krittin Kitjaruwannakul","avatar":""},{"name":"Nut Supanut Lourhaphanich","avatar":""},{"name":"Ping Obrnithi Leelavetchabutr","avatar":""},{"name":"Atthanin Thaninphanuwiwat","avatar":""},{"name":"Lee Asre Wattanayakul","avatar":""},{"name":"Thanapon Aiemkumchai","avatar":""},{"name":"Hemmawich Kwanamphaiphan","avatar":""},{"name":"Pantach Kankham","avatar":""},{"name":"Supakorn Saokhor","avatar":""},{"name":"Vorarit Vaijairanai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["霹雳情人","极速爱情","极速爱人","坑宝贝","PitBabe The Series"