INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-nguoc', 'Đếm Ngược', 'Countdown', 'https://phimimg.com/upload/vod/20250704-1/0d6f57521e994f6efe9c3dfa2cc0cdd9.jpg', 'https://phimimg.com/upload/vod/20250704-1/7a7dcd2ce6e32c865a334a4d4e4a1269.jpg', '<p>Khi một sĩ quan thuộc Bộ An ninh Nội địa bị sát hại giữa ban ngày, thám tử Mark Meachum của Sở Cảnh sát Los Angeles được điều động vào một lực lượng đặc nhiệm bí mật, phối hợp cùng các đặc vụ chìm đến từ nhiều cơ quan thực thi pháp luật khác nhau để điều tra vụ án. Tuy nhiên, cuộc truy lùng hung thủ nhanh chóng hé lộ một âm mưu đen tối hơn nhiều so với những gì họ tưởng tượng, khởi đầu cho một cuộc chạy đua với thời gian nhằm cứu lấy hàng triệu sinh mạng trong thành phố.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jensen Ackles","avatar":""},{"name":"Jessica Camacho","avatar":""},{"name":"Eric Dane","avatar":""},{"name":"Violett Beane","avatar":""},{"name":"Uli Latukefu","avatar":""},{"name":"Elliot Knight","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Contagem Regressiva","Countdown: เคาท์ดาวน์ ขีดเส้นตายสู่หายนะ","Countdown"]', 1784690324148);
