INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-vua-va-ke-chinh-phat', 'Nhà Vua và Kẻ Chinh Phạt', 'King & Conqueror', 'https://phimimg.com/upload/vod/20250826-1/8a68b44d263eaf47cf5362f856687109.jpg', 'https://phimimg.com/upload/vod/20250826-1/95ae970988ac8ff804eabc5b0b4bc324.jpg', '<p>Một cuộc chạm trán đã viết lại số phận của cả một đế chế – và vang vọng suốt thiên niên kỷ. Năm 1066, Trận Hastings, Harold của xứ Wessex và William xứ Normandy, hai cựu đồng minh nay thành kẻ thù, lao vào trận chiến không khoan nhượng. Họ vốn chẳng khao khát ngai vàng, nhưng bị định mệnh, lòng kiêu hãnh và ám ảnh quyền lực cuốn đi. Và từ cuộc đụng độ ấy, lịch sử nước Anh – và cả châu Âu – vĩnh viễn đổi thay.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Iceland', 0, '[{"name":"James Norton","avatar":""},{"name":"Nikolaj Coster-Waldau","avatar":""},{"name":"Clémence Poésy","avatar":""},{"name":"Emily Beecham","avatar":""},{"name":"Eddie Marsan","avatar":""},{"name":"Juliet Stevenson","avatar":""},{"name":"Jean-Marc Barr","avatar":""},{"name":"Luther Ford","avatar":""},{"name":"Geoff Bell","avatar":""},{"name":"Elliot Cowan","avatar":""},{"name":"Bo Bragason","avatar":""},{"name":"Bjarne Henriksen","avatar":""},{"name":"Clare Holman","avatar":""},{"name":"Oliver Masucci","avatar":""},{"name":"Ingvar E. Sigurðsson","avatar":""},{"name":"Indy Lewis","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["King and Conqueror","王与征服者","King & Conqueror"]', 17846903