INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luc-vi-nhan-gian', 'Lục Vị Nhân Gian', 'Live My Own Life', 'https://phimimg.com/upload/vod/20250906-1/97f5fae565a275cec38284591cc32c82.jpg', 'https://phimimg.com/upload/vod/20250906-1/3f4b6dd34078624e1c30e0c77c86a5d8.jpg', '<p>Lấy cảm hứng từ “sáu vị” trong ẩm thực (ngọt, chua, cay, đắng, mặn, nhạt), bộ phim khắc họa sáu mảnh đời với những trải nghiệm khác nhau trong tình yêu, tình thân và cuộc sống. Mỗi nhân vật đều phải nếm trải những cung bậc cảm xúc đối nghịch – hạnh phúc và khổ đau, hy vọng và tuyệt vọng – để rồi dần hiểu ra ý nghĩa đích thực của “vị đời”.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Mộng Dao","avatar":""},{"name":"Cao Ất Nham","avatar":""},{"name":"Loan Khả Hân","avatar":""},{"name":"Mã Việt Dã","avatar":""},{"name":"Vương Chí Cần","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ren Jian Liu Wei","Six Flavors of Life","人间六味"]', 1784690324148);
