INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-uoc-dinh-cua-linh-hon', 'Lời Ước Định Của Linh Hồn', 'The Promise Of The Soul', 'https://phimimg.com/upload/vod/20250719-1/ad204c8ab06206338feba5f0464f2d92.jpg', 'https://phimimg.com/upload/vod/20250719-1/c0d060ca4a2f1d16654b22a7a260aa3c.jpg', '<p>Sau một tai nạn, ông Hạ Trà hoán đổi linh hồn với cháu trai Hạ Trạch Phương và buộc phải sống tiếp trong cơ thể cháu để duy trì cuộc sống của cậu. Trong hành trình tìm cách trả lại cơ thể, ông cùng người bạn cùng phòng Diệp Hải Uyên bắt đầu khám phá một mối quan hệ định mệnh, từ đó mở ra câu chuyện về tình thân, định mệnh và sự kết nối giữa các thế hệ.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 13, 2025, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Martin Wong","avatar":""},{"name":"Kenji Fan","avatar":""},{"name":"Yaron Qiu","avatar":""},{"name":"Hong Wei","avatar":""},{"name":"Li Ting","avatar":""},{"name":"Kelly Liao","avatar":""},{"name":"Mariko Okubo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["灵魂约定","영혼약정: 영혼의 약속","A Pact Between Souls","靈魂的約定","VBL系列《靈魂約定》","VBL Series - The Promise of the Soul","靈魂約定"]', 1784690324148);
