INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-tan-hanh-gia', 'Dư Tẫn Hành Giả', 'Embers', 'https://phimimg.com/upload/vod/20250613-1/b25e831b5d2c543493c9615588efcc13.jpg', 'https://phimimg.com/upload/vod/20250613-1/bd352eebc9d159abc450757aa14c70f4.jpg', '<p>Đoan Mộc Dạ Vũ, thiếu niên mang ước mơ trở thành thợ săn địa ngục, vô tình cứu một người máy cải tạo và lấy đi vật dụng quan trọng trong nhiệm vụ tuyệt mật. Hành động vô ý ấy châm ngòi cho cuộc truy lùng quy mô lớn của phe phản diện, đẩy thành Dư Tẫn vào cuộc chiến sinh tử khởi nguồn từ lòng tốt ngây thơ của một cậu bé.</p>', 'Hoàn Tất (15/15)', 15, 'hoathinh', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Yu Jin Xing Zhe","Embers","SOOT WANDERER","余烬行者"]', 1784690324148);
