INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giao-uoc-quy-du', 'Giao Ước Quỷ Dữ', 'The Pact', 'https://phimimg.com/upload/vod/20250906-1/a6f26e9da7e4e10fe1d04ed7d9f6ab95.jpg', 'https://phimimg.com/upload/vod/20250906-1/edfb409f193649d7bc376322edfb7caa.jpg', '<p>Từ trò chơi cầu cơ ngây dại thuở ấu thơ, Yoon Ji-hee lớn lên thành kẻ bị ám ảnh bởi quyền năng huyền bí. Với những nghi thức cấm kỵ, cô thay đổi diện mạo, uốn nắn số phận, mê hoặc lòng người… tất cả để thực hiện giấc mộng thống trị Hàn Quốc. Trong khi đó, Jung Hyun Soo, nhà báo điều tra những bí mật đen tối phía sau hậu trường chính trị.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Gyu-ri","avatar":""},{"name":"Ahn Nae-sang","avatar":""},{"name":"Joo Sung-hwan","avatar":""},{"name":"Dong Bang-woo","avatar":""},{"name":"Shin Sun-hee","avatar":""},{"name":"Kim In-woo","avatar":""},{"name":"Choi Ji-hyeon","avatar":""},{"name":"Park Ji-seo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["권력의 화신 신명","앉은뱅이 주술사 \"쥴리\"","신명"]', 1784690324148);
