INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-buc-ve-ky-dieu', 'Những Bức Vẽ Kỳ Diệu', 'Sketch', 'https://phimimg.com/upload/vod/20250906-1/a8c9eb9c43b061c0d6c66f4b195bf215.jpg', 'https://phimimg.com/upload/vod/20250906-1/73dba89e34366e0a2dad32ba01dd11e6.jpg', '<p>Khi cuốn sổ phác thảo của một cô bé rơi xuống một ao nước kỳ lạ, những bức vẽ trong đó bất ngờ sống dậy — hỗn loạn, có thật và thoát ra ngoài. Khi cả thị trấn chìm vào cơn hỗn loạn, gia đình cô bé buộc phải đoàn kết để ngăn chặn những con quái vật mà họ chưa bao giờ định giải thoát.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tony Hale","avatar":""},{"name":"D''Arcy Carden","avatar":""},{"name":"Bianca Belle","avatar":""},{"name":"Kue Lawrence","avatar":""},{"name":"Kalon Cox","avatar":""},{"name":"Jaxen Kenner","avatar":""},{"name":"Genesis Rose Brown","avatar":""},{"name":"Randa Newman","avatar":""},{"name":"Allie McCulloch","avatar":""},{"name":"Nadia Benavides","avatar":""},{"name":"Dajanae Cole","avatar":""},{"name":"Josh Inocalla","avatar":""},{"name":"Tamiko Robinson Steele","avatar":""},{"name":"Mitch Miller","avatar":""},{"name":"Arielle Prepetit","avatar":""},{"name":"Jesse Santoyo","avatar":""},{"name":"Lei","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Dibujos imaginarios","Sketch: Attention à ce que tu dessines","Sketch. Cuidado con lo que dibujas","Firkák","Ужастики