INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luat-su-phuong-seocho', 'Luật Sư Phường Seocho', 'Law And The City', 'https://phimimg.com/upload/vod/20250706-1/50ee8e5f860954232514ab58f0a4a79d.jpg', 'https://phimimg.com/upload/vod/20250706-1/25d37f86d24cd7a0dbe466dc857476d3.jpg', '<p>Law and the city kể về cuộc sống của năm luật sư là cộng sự với nhau Ahn Ju Hyeong (Lee Jong Suk), Kang Hui Ji (Moon Ga Young), Cho Chang Won (Kang You Seok), Bae Mun Jeong (Ryu Hye Young) và Ha Sang Gi (Im Seong Jae). Họ cùng nhau trải qua những thử thách và thành công trong đời thường, làm việc tại các công ty luật và mỗi ngày đều đến khu vực pháp lý nhộn nhịp ở Seocho để làm việc.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Jong-suk","avatar":""},{"name":"Mun Ka-young","avatar":""},{"name":"Kang You-seok","avatar":""},{"name":"Ryu Hye-young","avatar":""},{"name":"Im Sung-jae","avatar":""},{"name":"Yeom Hye-ran","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["瑞草洞","Seocho-Dong","서초동"]', 1784690324148);
