INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('luat-su-phuong-seocho', 'Luật Sư Phường Seocho', 'Law And The City', 'luật sư phường seocho law and the city lee jong-suk mun ka-young kang you-seok ryu hye-young im sung-jae yeom hye-ran 瑞草洞 seocho-dong 서초동', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muoi-hai-la-thu-2025', 'Mười Hai Lá Thư', 'Twelve Letters', 'https://phimimg.com/upload/vod/20250830-1/e97ccc8e56c3f84a8d934c56ee921f31.jpg', 'https://phimimg.com/upload/vod/20250830-1/c191a082db96ab090f088d59b7be37ba.jpg', '<p>Mười hai bức thư bí ẩn, ba mươi lăm năm chờ đợi. Bộ phim tập trung khắc họa số phận và tình yêu của thiếu niên nơi thị trấn nhỏ, vỏ bọc là yếu tố kỳ ảo, bên trong chứa đựng sự hồi hộp bí ẩn, cảm xúc chân thành. Phá vỡ lối kể chuyện truyền thống, sáng tạo cơ chế liên kết hai thời không độc đáo, sự biến đổi khôn lường của thời tiết cùng tấm bảng đen trong lớp học bỏ hoang đã mở ra cánh cổng kết nối song song hai thời không, khiến khán giả hồi hộp không ngừng. Người yêu đột ngột mất tích và sự truyền tin thần bí của thời không đã để lại cho nam chính một câu đố rối rắm, trong quá trình lần ghép theo từng manh mối, anh dần vén màn sương mờ để tìm ra sự thật.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 13, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chu Dực Nhiên","avatar":""},{"name":"Vương Ảnh Lộ","avatar":""},{"name":"Trịnh Hợp Huệ Tử","avatar":""},{"name":"Nhậm Hựu Luân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["后会有期","十二封信"]', 1784690324148);
