INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-ky-cua-rati', 'Hồi Ký Của Rati', 'Memoir Of Rati', 'https://phimimg.com/upload/vod/20250621-1/98e059b3d4870059bae21ae97e54df5b.jpg', 'https://phimimg.com/upload/vod/20250621-1/245d559c59a4417a4e2f2070cd0d50f0.jpg', '<p>Năm 1915, Rati trở về Xiêm và tìm thấy sự gắn kết với Thee — người thừa kế của một gia đình giàu có và quyền lực, nhưng mối quan hệ của họ lại bị chính gia đình đó tìm cách phá hoại.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Sarin Ronnakiat","avatar":""},{"name":"Sapol Assawamunkong","avatar":""},{"name":"Kapook Ploynira Hiruntaveesin","avatar":""},{"name":"Thanaboon Kiatniran","avatar":""},{"name":"Tharatorn Jantharaworakarn","avatar":""},{"name":"Sivakorn Lertchuchot","avatar":""},{"name":"David Asavanond","avatar":""},{"name":"Allan Asawasuebsakul","avatar":""},{"name":"Thanik Kamontharanon","avatar":""},{"name":"Tarika Thidathit","avatar":""},{"name":"Penpetch Benyakul","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["暹羅情緣","Jaruekraticha","Charuekraticha","Memories of Rati","Hồi Ký Của Rati","จาฤกรติชา"]', 1784690324148);
