INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-em-den-chet', 'Yêu Em Đến Chết', 'Love Me To Death', 'https://phimimg.com/upload/vod/20250906-1/e5a7bbb6622e31a6ffd5ef1a6efac410.jpg', 'https://phimimg.com/upload/vod/20250906-1/65edc540db5167a85e969de3b4edec0e.jpg', '<p>Người chồng lý tưởng – Kamishiro Makoto – một người đàn ông hết lòng tận tụy vì vợ. Người vợ, Mio, cũng dành cho anh một tình yêu chân thành, trọn vẹn. Thế nhưng, ẩn sau cuộc hôn nhân hạnh phúc lại bùng nổ vụ án mạng “nữ phóng viên bị sát hại”, cuốn cả hai vào vòng xoáy nghiệt ngã, làm đảo lộn số phận. “ Tình yêu tối thượng ” rồi sẽ đi về đâu? Một bản tình ca tràn đầy yêu thương và điên loạn, nơi mối quan hệ giữa ái tình và kẻ sát nhân cuốn hút được khắc họa trong bầu không khí suspense thuần túy.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Miori Takimoto","avatar":""},{"name":"Hiroki Narimiya","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Love You To Death","Shinuhodo Aishite","Dead or Love","死ぬほど愛して"]', 1784690324148);
