INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-lai-tu-dau-2025', 'Yêu Lại Từ Đầu', 'Restarted Love', 'https://phimimg.com/upload/vod/20250830-1/e726612b110fbbfcb19f4178dfe8f1ba.jpg', 'https://phimimg.com/upload/vod/20250830-1/c364b334a2d3827d7503f8faffe5f9e1.jpg', '<p>Bộ phim kể về câu chuyện của Lục Minh – một nghệ sĩ trẻ, và người vợ Hứa Hân. Tình cảm giữa hai người dần rạn nứt, khoảng cách ngày một xa. Trong một vụ tai nạn giao thông nghiêm trọng, Hứa Hân bị thương nặng và rơi vào hôn mê kéo dài. Ở nhà, Lục Minh tình cờ phát hiện một cuốn tiểu thuyết được viết theo dòng ý thức của Hứa Hân. Anh nhận ra trong từng trang viết là những tâm tư thần kín và tình yêu sâu đậm mà cô dành cho anh. Đọc xong cuốn tiểu thuyết, Lục Minh vô cùng hối hận, và đã viết tiếp phần kết bằng tình yêu của chính mình. Cuối cùng, trong tiếng gọi tha thiết của Lục Minh, Hứa Hân dần dần tỉnh lại…</p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"La Chính","avatar":""},{"name":"Triệu Nghiêu Kha","avatar":""},{"name":"Tôn Nhất Kiệt","avatar":""},{"name":"Vương Dữ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chong Qi De Ai Qing","她从未来过","重启的爱情"]', 1784690324148);
