INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-tri-ky-uc', 'Đấu Trí Ký Ức', 'Hide Games', 'https://phimimg.com/upload/vod/20250824-1/609da06e23697cd4b427e716534b9d7b.jpg', 'https://phimimg.com/upload/vod/20250824-1/970a6945ab0106ff5021ec5728c1bf6e.jpg', '<p>&quot;Đấu Trí Ký Ức&quot; lấy bối cảnh tưởng tượng, mà trung tâm xuyên suốt bộ phim là vụ án một cảnh sát phòng chống ma túy bị sát hại. Các tập phim từ đầu đến cuối đầy căng thẳng, tập trung vào hai mặt thiện-ác của bản chất con người. Khi mọi chuyện dần dần sáng tỏ, khán giả không chỉ hồi hộp khi khám phá sự thật, mà còn khám phá ra bản chất con người.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hoắc Kiến Hoa","avatar":""},{"name":"Huỳnh Tông Trạch","avatar":""},{"name":"Hám Thanh Tử","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bo Yi","搏憶","搏忆"]', 1784690324148);
