INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thon-thien-ky', 'Thôn Thiên Ký', 'Tun Tian Ji', 'https://phimimg.com/upload/vod/20250519-1/9c9b169a8e5674ac68aaaa8bad9ff103.jpg', 'https://phimimg.com/upload/vod/20250519-1/277b550dcc3088ad438f18e8bc45d57e.jpg', '<p>Tác phẩm được chuyển thể từ tiểu thuyết cùng tên, tác giả: Phong Thanh Dương. &quot;Thôn Thiên Ký&quot; kể lại hành trình huyền thoại của thiếu niên Ngô Dục từ một phàm nhân trở thành tiên Phật.</p>', 'Tập 40', 50, 'hoathinh', 'ongoing', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jiang Qiuzai","avatar":""},{"name":"Haiting Cai","avatar":""},{"name":"Huang Wei Zhong","avatar":""},{"name":"Zhixiao Liu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["I Devour the World Alone","Tun Tian Ji","Swallowing the Heavens","Heaven Swallowing Chronicle","Tragándose el cielo","Heaven Swallowing Record","I Devour The Heaven And Earth","吞天记"]', 1784690324148);
