INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-con-thoi-gian-the-girl-who-stole-time', 'Đứa Con Thời Gian (The Girl Who Stole Time)', 'Endless Journey Of Love', 'https://phimimg.com/upload/vod/20250905-1/aa0b6b77b8ecd95b0dc7ced972c9dcf7.jpg', 'https://phimimg.com/upload/vod/20250905-1/7e500e40c0067834afb403162bf11ccf.jpg', '<p>Thập Thất và thiếu nữ làng chài Thiên Hiểu vì bánh xe thời gian bí ẩn mà kết duyên, một người muốn &quot;nghỉ việc&quot; tìm tự do, một người muốn &quot;rời đảo&quot; tìm kiếm điều những điều mới mẻ tuyệt vời hơn. Họ quyết định tạm thời hợp tác trở thành &quot;đối tác bánh xe thời gian - một ngày&quot;, mở ra một cuộc phiêu lưu lãng mạn đầy bất ngờ và thú vị tại đô thị phồn hoa. Trong hành trình này, mối quan hệ giữa Thập Thất và Thiên Hiểu âm thầm thay đổi, từ oan gia đối đầu ban đầu dần trở thành đối tác ăn ý, hai trái tim vô tình xích lại gần nhau, mà không hề hay biết rằng bí mật đằng sau bánh xe thời gian cũng đang lặng lẽ ảnh hưởng đến vận mệnh của cả hai ...</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Tuấn Khải","avatar":""},{"name":"Lưu Hiệu Dư","avatar":""},{"name":"Châu Thâm","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Endless Journey of Love","Shi Jian Zhi Zi","The Girl Who Stole Time","时间之子"]', 1784690324148);
