INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toa-nha-mau-den-kinh-hoang', 'Tòa Nhà Màu Đen Kinh Hoàng', 'The Black Building', 'https://phimimg.com/upload/vod/20250905-1/bfa643b1ad26880a1976d7b5e2007110.jpg', 'https://phimimg.com/upload/vod/20250905-1/f70245c7bd239ffa1f8af93e0bd247a2.jpg', '<p>Một đoàn làm phim đến một biệt thự hoang bị nguyền rủa để quay bộ phim &quot;Huyết Chú&quot;. Vì yêu cầu của kịch bản, họ đã tiến hành nghi lễ mời Điệp Tiên vào lúc 12 giờ đêm. Sau đó, những người tham gia nghi lễ mời Diệp Tiên lần lượt chết một cách kỳ lạ và đáng sợ. Nữ chính Âu Dương Hiểu Đồng có khả năng nhìn thấy âm hồn đã nhìn thấy những bóng ma thật sự. Trong đoàn làm phim có người nghi ngờ rằng họ đã mạo phạm Diệp Tiên và bị nguyền rủa, khiến mọi người bắt đầu sợ hãi...</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tiết Trân Châu","avatar":""},{"name":"Tống Vũ","avatar":""},{"name":"Tô Tô","avatar":""},{"name":"Lý Khải Long","avatar":""},{"name":"Từ Kính Khải","avatar":""},{"name":"Đường Mẫn","avatar":""},{"name":"Triệu Nguyên","avatar":""},{"name":"Vu Hạ","avatar":""},{"name":"Thẩm Minh Hạ","avatar":""},{"name":"Hằng Lạc","avatar":""},{"name":"Vương Chí Cương","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["黑楼惊魂"]', 1784690324148);
