INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('28-nam-sau-hau-tan-the', '28 Năm Sau: Hậu Tận Thế', '28 Years Later', 'https://phimimg.com/upload/vod/20250730-1/bdd74070051b2c4b8bdd935736e52f8e.jpg', 'https://phimimg.com/upload/vod/20250730-1/50d46f10a6860e2ff3f7258b39fc43ed.jpg', '<p>Cơn ác mộng chưa kết thúc. Virus trở lại, kéo theo bóng tối bao trùm nước Anh. Một hành trình sinh tử: cậu bé tìm kiếm bác sĩ để cứu mẹ mình, băng qua vùng đất chết chóc đầy xác sống tiến hóa và những kẻ nguy hiểm ẩn sau gương mặt tử tế. Liệu niềm hy vọng cuối cùng có đủ để cứu họ khỏi vực thẳm tuyệt vọng?</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Jodie Comer","avatar":""},{"name":"Aaron Taylor-Johnson","avatar":""},{"name":"Alfie Williams","avatar":""},{"name":"Ralph Fiennes","avatar":""},{"name":"Edvin Ryding","avatar":""},{"name":"Jack O''Connell","avatar":""},{"name":"Christopher Fulford","avatar":""},{"name":"Stella Gonet","avatar":""},{"name":"Chi Lewis-Parry","avatar":""},{"name":"Rocco Haynes","avatar":""},{"name":"Kim Allan","avatar":""},{"name":"Sandy Batchelor","avatar":""},{"name":"Amy Cameron","avatar":""},{"name":"Geoffrey Newland","avatar":""},{"name":"Joe Blakemore","avatar":""},{"name":"Celi Crossland","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["28 Days Later 3","28 İl Sonra","עשרים ושמונה שנים אחרי","بعد 28 سنة","Extermínio: A Evolução","٢٨ عاما لاحقا","28 שנים אחרי","Exterminio: La evolución","28 vuotta myöhemmin","28 ans plus tard","28 évvel később","28 anni dopo","28年後...","28 лет спустя","28 ปีให้หลัง เชื้อเขมือบคน","28 Yıl Sonra","28 Años Después","Extermínio 3: A Evolução","Extermínio 3","28年毁灭倒数","28 let poté","28 Years Later Part 1","28 vite më vonë","28 Years Later"]', 1784690324148);
