INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('28-nam-sau-hau-tan-the', '28 Năm Sau: Hậu Tận Thế', '28 Years Later', '28 năm sau: hậu tận thế 28 years later jodie comer aaron taylor-johnson alfie williams ralph fiennes edvin ryding jack o''connell christopher fulford stella gonet chi lewis-parry rocco haynes kim allan sandy batchelor amy cameron geoffrey newland joe blakemore celi crossland 28 days later 3 28 i̇l sonra עשרים ושמונה שנים אחרי بعد 28 سنة extermínio: a evolução ٢٨ عاما لاحقا 28 שנים אחרי exterminio: la evolución 28 vuotta myöhemmin 28 ans plus tard 28 évvel később 28 anni dopo 28年後... 28 лет спустя 28 ปีให้หลัง เชื้อเขมือบคน 28 yıl sonra 28 años después extermínio 3: a evolução extermínio 3 28年毁灭倒数 28 let poté 28 years later part 1 28 vite më vonë 28 years later', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-tieu-ngao-giang-ho-dong-phuong-bat-bai', 'Tân Tiếu Ngạo Giang Hồ: Đông Phương Bất Bại', 'Invincible Swordsman', 'https://phimimg.com/upload/vod/20250208-1/1d718567e1def17ceac36f4b6132a81b.jpg', 'https://phimimg.com/upload/vod/20250208-1/99df2ff431b429344a79ee49cbcaa304.jpg', '<p>Tân Tiếu Ngạo Giang Hồ: Đông Phương Bất Bại Invincible Swordsman 2025 dựa trên tiểu thuyết Tiếu Ngạo Giang Hồ của nhà văn Kim Dung, 1 bản làm lại và vẫn tập trung vào nhân vật Lệnh Hồ Xung, đại đệ tử phái Hoa Sơn. Anh là người phóng khoáng, yêu tự do và vô tình bị cuốn vào những âm mưu tranh đoạt quyền lực trong giang hồ. Đặc biệt phim khai thác sâu mối quan hệ giữa Lệnh Hồ Xung và Đông Phương Bất Bại giáo chủ Nhật Nguyệt Thần Giáo, một nhân vật bí ẩn với võ công cao cường.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 1, '[{"name":"Trương Vũ Kì","avatar":""},{"name":"Hoàng Hy Diễn","avatar":""},{"name":"Hồng Kim Bảo","avatar":""},{"name":"Doãn Tử Duy","avatar":""},{"name":"Tuyên Lộ","avatar":""},{"name":"Vân Thiên Thiên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["笑傲江湖之东方不败","笑傲江湖之风云再起","Invincible Swordsman","笑傲江湖 2025","Espadachim Invencível","笑傲江湖"]', 1784690324148);
