INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('viet-chau-di-van-luc', 'Việt Châu Dị Văn Lục', 'Yuezhou Phantom Tales', 'https://phimimg.com/upload/vod/20250604-1/36fe295848f203dc1d89398cef717b29.jpg', 'https://phimimg.com/upload/vod/20250604-1/180327df71278c8e415eeda47dd70800.jpg', '<p>Đời Đường, năm Tái Sơ. Tại Tây phường thành Việt Châu xảy ra một vụ tự sát kỳ quái, tựa như một nghi thức chiêu hồn. Sau khi điều tra, thiếu doãn Việt phủ Tư Văn đã phát hiện người chết chính là người phụ nữ mà mình từng yêu sâu đậm – Liễu Chiêu Đệ, một &quot;hoa khôi&quot; lừng danh một thời. Kể từ ngày thứ bảy sau vụ án mạng, một đứa trẻ bị bỏ rơi đã hóa thành sơn thần dã quỷ, bắt đầu một cuộc báo thù được mưu tính từ lâu…</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vu Hiên Thần","avatar":""},{"name":"Lý Hoan","avatar":""},{"name":"Lưu Yến Kiều","avatar":""},{"name":"Khổng Vũ Xung","avatar":""},{"name":"Đoàn Thu Ngọc","avatar":""},{"name":"Dương Vũ Tranh","avatar":""},{"name":"Vương Tiểu Hàm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yue Zhou Yi Wen Lu","월주이문록: 월주잔혹사","Strange Tales from Yuezhou","越州异闻录"]', 1784690324148);
