INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('viet-chau-di-van-luc', 'Việt Châu Dị Văn Lục', 'Yuezhou Phantom Tales', 'việt châu dị văn lục yuezhou phantom tales vu hiên thần lý hoan lưu yến kiều khổng vũ xung đoàn thu ngọc dương vũ tranh vương tiểu hàm yue zhou yi wen lu 월주이문록: 월주잔혹사 strange tales from yuezhou 越州异闻录', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bua-tiec-cua-co-ay', 'Bữa Tiệc Của Cô Ấy', 'Her Feast', 'https://phimimg.com/upload/vod/20250818-1/904d12e7982267ffe8085366781cffc0.jpg', 'https://phimimg.com/upload/vod/20250818-1/390b0a0462291d27014ee48e9bbcec26.jpg', '<p>Sau khi bị hãm hại và chịu đủ giày vò, Chương Quán Ca bất ngờ quay về thời điểm ba năm trước khi chết. Mang theo ký ức về kiếp trước, Chương Quán Ca tiếp cận đội trưởng cục cảnh sát Lục Dã để truy tìm sự thật. Đồng thời, những giấc mơ của Lục Dã tiếp tục hé lộ nhiều manh mối cho cô. Khi màn sương trong mơ tan dần, Lục Dã sẵn sàng dấn thân vào nguy hiểm để tìm ra sự thật. Trong mơ, khi viên đạn xuyên qua hai trái tim, một trái tim dừng lại ở quá khứ, một trái tim hướng đến tương lai...</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hà Hoằng San","avatar":""},{"name":"Tạ Bân Bân","avatar":""},{"name":"Lâm Trạch Huy","avatar":""},{"name":"Trịnh Thuần Cảnh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Ta De Sheng Yan","昼夜之间","她的盛宴"]', 1784690324148);
