INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-bo-senh-hoan', 'Bộ Bộ Sênh Hoan', 'Dangerous Love', 'https://phimimg.com/upload/vod/20250827-1/fd4f95db3dfe84a890bb281fd85c132e.jpg', 'https://phimimg.com/upload/vod/20250827-1/deea000876886b909e5cba1268e482f0.jpg', '<p>Hứa Bắc Sanh vì báo thù cho cha, đã nhận giặc làm cha, ẩn mình bên cạnh Đốc quân. Khi biết tin hai nhà Hứa - Châu liên hôn, anh đã lên kế hoạch tiếp cận Châu Mộng Hoan nhằm phá hoại cuộc hôn nhân này, không ngờ lại &quot;kịch giả thành thật&quot; và nảy sinh tình cảm với cô. Khi sự thật bại lộ, Châu Mộng Hoan thay đổi và quyết định gả vào nhà họ Hứa để trả thù. Yêu hận đan xen trong cuộc chiến tranh giành quyền lực của gia tộc hào môn, cuối cùng tất cả bị cuốn vào dòng chảy loạn lạc của thời đại.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cao Minh Thần","avatar":""},{"name":"Hàn Hân Dư","avatar":""},{"name":"Từ Anh Lạc","avatar":""},{"name":"Mục Lạc Ân","avatar":""},{"name":"Sài Hạo Vĩ","avatar":""},{"name":"Vương Duệ Tử","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bu Bu Sheng Huan","贪欢","算计","步步笙欢"]', 1784690324148);
