INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-xe-ban-sung-phan-2', 'Đua Xe Bắn Súng (Phần 2)', 'Twisted Metal (Season 2)', 'https://phimimg.com/upload/vod/20250812-1/b1a070354119eefebda91c385c2a4c26.jpg', 'https://phimimg.com/upload/vod/20250812-1/ebe0d758b1db8c43aa0935174d2bbf30.jpg', '<p>Một người ngoài cuộc mồm mép và không có ký ức về quá khứ của mình sẽ có cơ hội có một cuộc sống tốt hơn, nhưng chỉ khi anh ta có thể chuyển thành công một gói hàng bí ẩn xuyên qua vùng đất hoang hậu tận thế. Với sự giúp đỡ của một tên trộm xe cầm rìu hung hãn, anh ta sẽ phải đối mặt với những tên cướp man rợ lái những phương tiện hủy diệt và những mối nguy hiểm khác trên con đường rộng mở, bao gồm cả một chú hề loạn trí lái chiếc xe bán kem quá quen thuộc.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Anthony Mackie","avatar":""},{"name":"Stephanie Beatriz","avatar":""},{"name":"Nuufolau Joel Seanoa","avatar":""},{"name":"Will Arnett","avatar":""},{"name":"Anthony Carrigan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Twisted Metal: Сериалът","Искорёженный металл","Поплавлений метал","Покручений метал","Twisted Metal Live Action","Twisted Metal"]', 1784690324148);
