INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lu-trinh-thanh-xuan', 'Lữ Trình Thanh Xuân', 'My Lovely Journey', 'https://phimimg.com/upload/vod/20250803-1/ae23cb05860cbd01966646ee5b05b638.jpg', 'https://phimimg.com/upload/vod/20250803-1/8114e973a1df9dcb14330d8aa45c76bf.jpg', '<p>Kang Yeo Reum, cựu thành viên một nhóm nhạc thần tượng hiện đang làm phóng viên chương trình du lịch. Cô hợp tác với Lee Yeon Seok, người tốt nghiệp đại học lớn và đã nghỉ việc ở 1 công ty danh giá, hiện đang làm biên tập viên cho chương trình du lịch của cô. Lee Yeon Seok trở thành nhà sản xuất, đồng thời ấp ủ và theo đuổi ước mơ trở thành đạo diễn phim. Thông qua những chuyến đi do yêu cầu công việc, cả Kang Yeo Reum và Lee Yeon Seok dần nhận ra được thành công thực sự là gì và ý nghĩa của cuộc sống là như thế nào.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Gong Seung-yeon","avatar":""},{"name":"Yu Jun-sang","avatar":""},{"name":"Kim Jae-young","avatar":""},{"name":"Hong Soo-hyun","avatar":""},{"name":"Baekho","avatar":""},{"name":"Oh Hyun-Joong","avatar":""},{"name":"Park Bo-yeon","avatar":""},{"name":"Dong Hyun-bae","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["代替旅行","Yeohaengeul Daesinhae Deuribnida","여행을 대신해드립니다","여행을 대신 해드립니다","رحلتي الجميلة","I Will Take the Trip for You","I Will Travel for You","Travel Agency Summer","My Lovely Journey","I''ll Take the Trip for You","여행을 대신해 드립니다"]', 1784690324148);
