INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lu-trinh-thanh-xuan', 'Lữ Trình Thanh Xuân', 'My Lovely Journey', 'lữ trình thanh xuân my lovely journey gong seung-yeon yu jun-sang kim jae-young hong soo-hyun baekho oh hyun-joong park bo-yeon dong hyun-bae 代替旅行 yeohaengeul daesinhae deuribnida 여행을 대신해드립니다 여행을 대신 해드립니다 رحلتي الجميلة i will take the trip for you i will travel for you travel agency summer my lovely journey i''ll take the trip for you 여행을 대신해 드립니다', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-kho-do-2025', 'Chuyện Tình Khó Đỡ', 'History Of Scruffiness', 'https://phimimg.com/upload/vod/20250827-1/7280852ae17298efeb70cf9fa2ee47e9.jpg', 'https://phimimg.com/upload/vod/20250827-1/84bf857a458af25483ae9b081f786032.jpg', '<p>Đây sẽ là một bộ phim hài lãng mạn chạm đến những khía cạnh vụng về, yếu đuối nhất của con người, đồng thời khắc họa những phút giây ngọt ngào, nghẹt thở mà tình yêu mang lại. Giữa nỗi xấu hổ, bối rối và cả sự thất vọng, khán giả sẽ tìm thấy tiếng cười, sự đồng cảm – và chính mình. Nhân vật trung tâm là Seo Min Gi, sinh viên năm nhất ngành Văn học Hàn Quốc. 20 tuổi, cậu vừa nhút nhát vừa bốc đồng, luôn mắc hết sai lầm này đến sai lầm khác. Min Gi suy tư nhiều, hay tự vấn bản thân, nhưng thực chất chỉ là một chàng trai bình thường, ước mong giản dị: được tụ tập nhậu nhẹt cùng bạn bè và đắm chìm trong game ở quán net. Một “kẻ ngoài lề” vụng về, vô tình trở thành nhân vật chính trong hành trình tình yêu đầy chông chênh và buồn cười của chính mình.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Cho Byeong-kyu","avatar":""},{"name":"Ryeoun","avatar":""},{"name":"Jeong Jae-kwang","avatar":""},{"name":"Jung Yong-ju","avatar":""},{"name":"Song Ha-yoon","avatar":""},{"name":"Bang Min-ah","avatar":""},{"name":"Lee Min-ji","avatar":""},{"name":"Hwang Bo-reum-byeol","avatar":""},{"name":"Jo Yoon-seo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["History of Losers","찌질의 역사"]', 1784690324148);
