INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hoang-mat-chuoc-2025', 'Nữ Hoàng Mạt Chược', 'Queen Of Cards', 'https://phimimg.com/upload/vod/20250902-1/1992e89cf36e545067dd5bf42544f3a6.jpg', 'https://phimimg.com/upload/vod/20250902-1/4963f4ae41ebada82fd020aa054e3ebf.jpg', '<p>Tước vương, cha của thiếu nữ thiên tài Lâm Tước bị hại chết. Khi trưởng thành, Lâm Tước quyết tâm trả thù cho cha. Cô cố tình tiếp cận và lợi dụng Cửu Gia, một nhân vật tiếng tăm lẫy lừng để trả thù. Vừa hay, Cửu Gia lại đang tìm kiếm một thiên tài mạt chược để tham gia “Giải thi đấu Thần Mạt Chược” thay mình. Ban đầu, cả hai chỉ lợi dụng lẫn nhau, nhưng dần dần tình cảm lại nảy sinh tự lúc nào. Thế nhưng, Lâm Tước lại hiểu lầm rằng Cửu Gia chính là kẻ đã giết cha mình, khiến hai người rơi vào vòng xoáy giữa yêu và hận…</p>', 'Hoàn Tất (60/60)', 60, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324148);
