INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huu-yeu-2025', 'Hữu Yểu', 'The Demon', 'https://phimimg.com/upload/vod/20250824-1/b5c461cfc77d145d30c6196bd53cdf88.jpg', 'https://phimimg.com/upload/vod/20250824-1/b0ff3b242aca7ccbaedf784aba6b8026.jpg', '<p>Phàn Đại Yêu là “hổ yêu vương” vạn ác của núi Thiên Xuân, pháp lực mạnh mẽ và tuyệt đối uy quyền. Thẩm Vọng Trần là con trai thành chủ Mặc Uyên Thành, từ khi sinh ra đã ốm yếu, tính cách lạnh lùng, xa cách. Khi trưởng thành, để chữa bệnh, Thẩm Vọng Trần lên đường tìm kiếm yêu miêu. Trong hành trình ấy, anh tình cờ gặp Phàn Đại Yêu, và từ đó một cuộc sống “người – yêu cùng chung mái nhà” vừa dở khóc dở cười vừa lãng mạn bắt đầu…</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hồ Đan Đan","avatar":""},{"name":"Dương Trạch","avatar":""},{"name":"Lưu Gia Kì","avatar":""},{"name":"Lưu Dung Dung","avatar":""},{"name":"Lý Mộ Vũ","avatar":""},{"name":"Trương Dương","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["You Yao","Faith","有夭"]', 1784690324148);
