INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bat-tuong-quan-ve-lam-ap-trai-phu-quan', 'Bắt Tướng Quân Về Làm Áp Trại Phu Quân', 'Recruit A General To Lead The Troops', 'https://phimimg.com/upload/vod/20250824-1/258e1a6215d95a9bb25d949758b4c79f.jpg', 'https://phimimg.com/upload/vod/20250824-1/07fbc5b5397ac48c5ea0f5c2ae099bba.jpg', '<p>Chàng trai giao đồ ăn Lý Thừa Ngự bất ngờ xuyên không về thời xưa, trở thành vị đại tướng quân lừng lẫy. Để điều tra chuyện phản loạn, Lý Thừa Ngự cải trang thành nông dân, trà trộn vào trại Thanh Phong và trở thành chồng ở rể của trại chủ Trần Tâm Nhu. Với tư duy hiện đại sắc bén, Lý Thừa Ngự từng bước xoay chuyển tình thế, đồng thời vô tình nảy sinh mối duyên tình cảm sâu nặng với Trần Tâm Nhu…</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Viên Tử Minh","avatar":""},{"name":"Tôn Diễm Thanh","avatar":""},{"name":"Hồ Chung Đình","avatar":""},{"name":"Cẩn Nhan","avatar":""},{"name":"Lý Giai Bàn","avatar":""},{"name":"Tống Hải Hiệt","avatar":""},{"name":"A Bỉ Đạt","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Qiang Ge Jiang Jun Lai Ya Zhai","Rob the General to Defend the Village","抢个将军来压寨"]', 1784690324148);
