INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-tac-hac-nguyet-quang', 'Quy Tắc Hắc Nguyệt Quang', 'Princess Revenge', 'https://phimimg.com/upload/vod/20250820-1/4ef09dfebf7b1b2dcabbed2346595f0c.jpg', 'https://phimimg.com/upload/vod/20250820-1/c8551d22d12c295422cced89eb0af75c.jpg', '<p>Thiên kim tiểu thư Đông Phương Hi vì tình yêu mà mai danh ẩn tích, đi làm nuôi trai đểu Diệp Vân Châu nhưng lại bị hắn phản bội, sau đó cô đã thức tỉnh. Khi nhận ra mình là nữ phụ độc ác trong tiểu thuyết, cô đánh cược với hệ thống để thay đổi vận mệnh. Cuối cùng, tại bữa tiệc trở về, cô đã vạch trần bộ mặt thật của Diệp Vân Châu. Khi Diệp Vân Châu lại đến dây dưa, cô phát hiện ra người anh trai yêu thầm mình bấy lâu nay, Đông Phương Yến, lại là hóa thân của hệ thống. Trước bước ngoặt định mệnh, cô cố ý thua cược, vạch trần chân tình anh đã giấu kín bao năm.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Bành Nhã Kỳ","avatar":""},{"name":"Mễ Nhiệt","avatar":""},{"name":"Lý Gia Tường","avatar":""},{"name":"Phù Tông","avatar":""},{"name":"Lý Thị Hiệu","avatar":""},{"name":"Phó Ngư Thư","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hei Yue Guang Fa Ze","黑月光法则"]', 1784690324148);
