INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phai-long-cun-con', 'Phải Lòng Cún Con', 'DogBro', 'https://phimimg.com/upload/vod/20250729-1/f33729b37338a679e21576313124d9b9.jpg', 'https://phimimg.com/upload/vod/20250729-1/a990626748617e165c23793bd2a38be1.jpg', '<p>Một ngày nọ Meen gặp một chú chó Samoyed trắng thoát khỏi trận lũ và bị lạc vào nhà. Chú chó này đã thay đổi thế giới tẻ nhạt của cậu ấy và khiến nó trở nên tươi sáng hơn. Và rồi cuộc sống yên bình của Meen sắp kết thúc thì mẹ anh bất ngờ gửi Tul, con trai của bạn mẹ, đến sống cùng trong một ngôi nhà ở Chiang Mai. Meen rất lo lắng cho chú chó mà mình yêu mến và không muốn cho ai sống cùng trong ngôi nhà này. Vì vậy, cậu ấy đã tìm mọi cách để đuổi Tul trai này ra khỏi nhà...Nhưng bản tính tình cảm của Tul đã khiến trái tim Meen, vốn chưa từng rung động với ai, càng thêm rung động...</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Sky Chaithawat Manophasthanapha","avatar":""},{"name":"Kong Kongphom Farwaeroj","avatar":""},{"name":"Parnupat Anomakiti","avatar":""},{"name":"Tiger Rachaporn Prechadet","avatar":""},{"name":"First Worasak Sriboonwong","avatar":""},{"name":"Net Latthaphon Teepak","avatar":""},{"name":"Best Phadungsak Autthiya","avatar":""},{"name":"Kim Wichwisit Maphicharn","avatar":""},{"name":"Natsinee Charoensitthisap","avatar":""},{"name":"Chatchapon Pranotphon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["What the Nong","What''s the Nong?",