INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-di-vat-ta-am-that-can-tam-gian', 'Bảy Di Vật Tà Ám (Thất Căn Tâm Giản)', 'The Seven Relics Of ill Omen', 'https://phimimg.com/upload/vod/20250608-1/8c8897d5839b4ba966a788afa340eb27.jpg', 'https://phimimg.com/upload/vod/20250608-1/df9d707ea1e0ee03fe5f1a1c058be7a6.jpg', '<p>Giới thiệu Bảy Di Vật Tà Ám Bảy Di Vật Tà Ám Giới thiệu Cải biên từ nguyên tác &quot;Thất Căn Hung Giản&quot; của Vỹ Ngư. Thời thượng cổ, một vật chất bí ẩn không rõ nguồn gốc xuất hiện ở Phượng Tử Lĩnh, có khả năng ký sinh lên cơ thể người, thay đổi tâm trí và dụ dẫn con người làm điều ác. Giờ đây, &quot;Tâm Giản&quot; tái xuất hiện, kéo theo hàng loạt vụ án kỳ lạ. Mộc Đại, La Nhận, Nhất Vạn Tam, Viêm Hồng Sa và Tào Nghiêm Hoa – năm bạn trẻ bình thường nhưng nhiệt huyết – vì những tình huống bất ngờ trong cuộc đời, họ lần lượt vướng vào sự kiện liên quan đến Tâm Giản. Họ cùng nhau thành lập đội Phượng Hoàng, bắt đầu hành trình thu phục hung giản đầy mạo hiểm. Trong chuyến phiêu lưu sinh tử này, La Nhận và Mộc Đại dần chữa lành vết thương lòng cho nhau, trao gửi trái tim chân thành. Năm người vượt qua ngàn dặm gian khó, khắc phục muôn vàn hiểm trở, sau những thử thách đó, tình bạn của họ càng thêm gắn bó và thăng hoa.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 9, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Hà Tồn","avatar":""},{"name":"Tống Uy Long","avatar":""},{"name":"Ao Thuỵ Bằng","avatar":""},{"name":"Vương Dật Đình","avatar":""},{"name":"Trương Dực Trí","avatar":""},{"name":"Tả Tiểu Thanh","avatar":""},{"name":"Dương Hạo Vũ","avatar":""},{"name":"Phùng Binh","avatar":""},{"name":"Nghiêm Ất Khoan","avatar":""},{"name":"Sa Bảo Lượng","avatar":""},{"name":"Nhạc Việt Lợi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["七根凶简","Qi Gen Xin Jian","七根迷简","The Seven Relics of ill Omen","七根心简"]', 1784690324148);
