INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-dich-san-cao', 'Chiến Dịch Săn Cáo', 'Fox Hunt', 'https://phimimg.com/upload/vod/20250901-1/bd27ae694ea7a60ddfdbd7a624174e9d.jpg', 'https://phimimg.com/upload/vod/20250901-1/a90ac240719669d7ca37e4570aa4288d.jpg', '<p>Bộ phim&nbsp;là tác phẩm đầu tiên của điện ảnh Trung Quốc đưa đề tài “truy bắt tội phạm ở nước ngoài” lên màn ảnh rộng. Phim kể về câu chuyện tổ chuyên án “Săn Cáo” của Cục Kinh tế – Bộ Công an Trung Quốc tiến hành truy bắt xuyên biên giới các nghi phạm tội phạm tài chính nằm trong danh sách truy nã quốc tế “Red Notice” (lệnh truy nã đỏ).</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đoạn Dực Hồng","avatar":""},{"name":"Lương Triều Vỹ","avatar":""},{"name":"Hạ Hầu Vân Sơn","avatar":""},{"name":"Trương Áo Nguyệt","avatar":""},{"name":"Thành Hiểu Tinh","avatar":""},{"name":"Trương Chí Kiên","avatar":""},{"name":"Hề Mỹ Quyên","avatar":""},{"name":"Bạch Chí Địch","avatar":""},{"name":"Ngô Cương","avatar":""},{"name":"Nhâm Chính Bân","avatar":""},{"name":"Phổ Dương Ân","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Fox Hunt","Lie Hu Xing Dong","猎狐·行动","围猎","獵狐行動","The Fox Hunt"]', 1784690324148);
