INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('man-dinh-phuong', 'Mãn Đình Phương', 'Luminosity Behind The Palace', 'https://phimimg.com/upload/vod/20250821-1/c5c49f11545a856e538f5aa6591cfab1.jpg', 'https://phimimg.com/upload/vod/20250821-1/1fe84773c6972724aaaf5ec440a6bb5b.jpg', '<p>Tô Nhạc Ngu, tiểu thư xuất thân thế gia, bị ép gả cho hoàng đế Ân Trường Diễm, người từng là thanh mai trúc mã của cô, cùng nhau cô nỗ lực cải cách triều đình, mở đường cho phụ nữ thi cử và làm quan, đồng thời thách thức quyền lực áp bức của các đại thế gia.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hồ Liên Hân","avatar":""},{"name":"Phạm Trí Tân","avatar":""},{"name":"Trương Chi Cẩm","avatar":""},{"name":"Trương Bá Chi","avatar":""},{"name":"Tùy Minh Dương","avatar":""},{"name":"Đinh Tử Ân","avatar":""},{"name":"Hàn Tử Phàm","avatar":""},{"name":"Hàn Dự Khê","avatar":""},{"name":"Giang Ngọc Giai","avatar":""},{"name":"Lý Bân","avatar":""},{"name":"Lý Thiên Lạc","avatar":""},{"name":"Lưu Tư Thần","avatar":""},{"name":"Lưu Vĩnh Cương","avatar":""},{"name":"Hướng Nguyên","avatar":""},{"name":"Trương Hoài Công","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Man Ting Fang","满庭芳"]', 1784690324148);
