INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hong-tho-dia', 'Hồng Thổ Địa', 'Red Land', 'https://phimimg.com/upload/vod/20250831-1/70ea276ad771a7d42a7ba1885d35ebd8.jpg', 'https://phimimg.com/upload/vod/20250831-1/0e8e94e19d392197debaea343384a1d5.jpg', '<p>Bộ phim&nbsp;kể về một trận chiến bất ngờ mang tên “Trận Thiên Dương”, trận chiến này đã hủy diệt toàn bộ thế giới trên mặt đất. Những người sống sót buộc phải tập trung tại ga tàu điện ngầm Hồng Đất (Chongqing), chôn sâu dưới lòng đất, lay lắt tồn tại suốt hơn 20 năm. Trong thế giới ngầm ấy, con người phải đối mặt và chiến đấu với tộc Chuột. Câu chuyện khoa học viễn tưởng này đặt ra câu hỏi: loài người sẽ đi về đâu?</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Á Lợi Á","avatar":""},{"name":"Lưu Kiếm Vu","avatar":""},{"name":"La Lập Quần","avatar":""},{"name":"Hoàng Cách Tuyển","avatar":""},{"name":"Trương Xuân Trung","avatar":""},{"name":"Vương Diễn Tô","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["红土地"]', 1784690324148);
