INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duong-den-trai-tim-em', 'Đường Đến Trái Tim Em', 'The Map That Leads To You', 'https://phimimg.com/upload/vod/20250830-1/42b7e0c340f60e06ab396eec47899621.jpg', 'https://phimimg.com/upload/vod/20250830-1/fc208b83ff292a6cb20416c4dfc1a49a.jpg', '<p>Trước khi bước vào cuộc sống hoàn hảo đã được định sẵn, Heather cùng bạn bè rong ruổi khắp châu Âu, tận hưởng những ngày tháng tự do cuối cùng. Nhưng chỉ một cuộc gặp gỡ thoáng qua với Jack đã xoay chuyển tất cả – từ những rung động đầu đời cho đến hành trình tìm lại chính mình. Khi bí mật dần hé lộ và những ngã rẽ cuộc đời buộc họ phải lựa chọn, Heather nhận ra: tương lai của cô sẽ không bao giờ còn như trước.</p>', 'Full', 1, 'single', 'completed', 29, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Madelyn Cline","avatar":""},{"name":"K.J. Apa","avatar":""},{"name":"Sofia Wylie","avatar":""},{"name":"Madison Thompson","avatar":""},{"name":"Orlando Norman","avatar":""},{"name":"Josh Lucas","avatar":""},{"name":"JR Esposito","avatar":""},{"name":"Marilyn Cutts","avatar":""},{"name":"Joseph William Evans","avatar":""},{"name":"Diego Ross","avatar":""},{"name":"Ana Hernández-Sanchíz","avatar":""},{"name":"Javier Barandiarán","avatar":""},{"name":"Emilio Linder","avatar":""},{"name":"Albar Cirarda","avatar":""},{"name":"Clara Viñals","avatar":""},{"name":"Álvaro Cobas González","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["จุดหมายสุดท้ายคือเธอ","Sənə Gətirən Yollar","通往你的地图","The Map That Leads to You"]', 1784690324149);
