INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luc-luong-chap-phap', 'Lực Lượng Chấp Pháp', 'Prism Breaker', 'https://phimimg.com/upload/vod/20250516-1/88c56bdfc145b37b1b01ce9d7e96b9d1.jpg', 'https://phimimg.com/upload/vod/20250516-1/ee68daf6954be303805c7cf2734849e4.jpg', '<p>&quot;Lực Lượng Chấp Pháp&quot; thể hiện sự hợp tác của ba cơ quan chấp pháp bao gồm: Cảnh sát, Ủy ban độc lập chống tham nhũng ICAC và sở Tư pháp. Giữa cuộc chơi quyền lực mù mịt trùng trùng, những người chấp pháp làm việc tỉ mỉ, cuối cùng đã đưa bọn tội phạm đứng trước vành móng ngựa. Bằng tiết tấu nhanh và gay cấn, bộ phim khắc họa một cuộc đấu tranh tàn khốc và sự phức tạp của tình người, biểu dương giá trị vĩnh hằng của công bằng và chính nghĩa, đồng thời cho chúng ta nhiều suy nghĩ trong quá trình chấp pháp…</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 9, 2025, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngô Khải Hoa","avatar":""},{"name":"Trần Hào","avatar":""},{"name":"Huỳnh Tông Trạch","avatar":""},{"name":"Mã Quốc Minh","avatar":""},{"name":"Tuyên Huyên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["執法者們"]', 1784690324149);
