INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-dieu-cua-dinh-menh', 'Giai Điệu Của Định Mệnh', 'Heavenly Hand', 'https://phimimg.com/upload/vod/20250729-1/9ae951c96af20e99f57f09fda0e6ff35.jpg', 'https://phimimg.com/upload/vod/20250729-1/1678d7bda21d7d63433e912a85a02128.jpg', '<p>Thừa kế quán mạt chược Đại Long Phụng từ khi còn trẻ, Tư Đồ Cửu luôn được mọi người tin tưởng vì cách làm việc điềm tĩnh, kiên định. Một ngày nọ, anh bất ngờ mua lại một ban nhạc sắp phá sản vì một động cơ bí mật mà chỉ mình anh biết. Cùng lúc đó, Âu Dương Tông, một chủ tịch tập đoàn và từng là bại tướng trên bàn mạt chược của bố Tư Đồ Cửu, bỗng quay trở lại và rắp tâm đối phó với quán Đại Long Phụng. Giai Điệu Của Định Mệnh xoay quanh những nỗ lực của Tư Đồ Cửu để gìn giữ sản nghiệp gia đình trước những biến cố liên tục ập đến.</p>', 'Tập 25', 25, 'series', 'ongoing', 12, 2025, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Đàm Tuấn Ngạn","avatar":""},{"name":"Lý Giai Tâm","avatar":""},{"name":"Khương Đại Vệ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["麻雀乐团","麻雀樂團","Hevenly Hand"]', 1784690324149);
