INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hinh-mau', 'Hình Mẫu', 'Ordinary Fireworks', 'https://phimimg.com/upload/vod/20250829-1/229cb23b968c8d2b35fbc92708006a84.jpg', 'https://phimimg.com/upload/vod/20250829-1/34e45ffa7952de2d8d6377fb0a578a10.jpg', '<p>Bộ phim được chuyển thể từ câu chuyện có thật về đồng chí Bào Vệ Trung – người đã khuất, được vinh danh là “Tấm gương thời đại”, “Thẩm phán mẫu mực toàn quốc”. Tác phẩm kể lại hành trình ông dốc hết tâm sức và tình cảm để hóa giải mâu thuẫn, tranh chấp trong nhân dân, bảo vệ sự tôn nghiêm của pháp luật, đồng thời làm nổi bật sự ấm áp và nhân văn của nền tư pháp.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wen Jiang","avatar":""},{"name":"Wang Xiaobai","avatar":""},{"name":"Zhu Yan","avatar":""},{"name":"Ye Mingming","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Kai Mo","楷模"]', 1784690324149);
