INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('soi-chi-tu-than', 'Sợi Chỉ Tử Thần', 'S Line', 'https://phimimg.com/upload/vod/20250711-1/01b78e478e9fa792e896233306f4a1bb.jpg', 'https://phimimg.com/upload/vod/20250711-1/cfb68212ac2707a518824fd13d1ec618.jpg', '<p>Bộ phim kể về một hiện tượng kỳ bí: một sợi dây đỏ xuất hiện phía trên đầu của mỗi người, kết nối họ với những người mà họ đã từng có quan hệ tình dục. Han Ji Uk là một thám tử quyết tâm tìm ra sự thật đằng sau hiện tượng kỳ lạ này. Gyu Jin là một giáo viên trung học lập dị, còn Hyun Heup là một học sinh trung học đã có khả năng nhìn thấy sợi dây đỏ này từ khi mới sinh ra. Cả ba cùng bị cuốn vào một hành trình khám phá sự thật, hé lộ những mối liên kết phức tạp và đầy bất ngờ giữa con người với nhau.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 12, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Soo-hyuk","avatar":""},{"name":"Lee Da-hee","avatar":""},{"name":"Choi Ye-won","avatar":""},{"name":"Lee Kwang-hee","avatar":""},{"name":"Lee Han-joo","avatar":""},{"name":"Lee Eun-saem","avatar":""},{"name":"Nam Kyu-hee","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["S-line","S Line","Sライン","Линии С","الخط إس","S LINE","S Rain","S라인"]', 1784690324149);
