INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-o-dinh-cao-doi-cau', 'Tôi Ở Đỉnh Cao Đợi Cậu', 'Summit Of Our Youth', 'https://phimimg.com/upload/vod/20250808-1/21951072ec5eb53106763f1b1cf90073.jpg', 'https://phimimg.com/upload/vod/20250808-1/941272f6220478c357bebc8e1852018c.jpg', '<p>Bộ phim kể về Cố Tuyết Giao – một cô gái vừa là nhân viên văn phòng dưới đáy xã hội vừa yêu đương mù quáng – trong lúc đối mặt với nguy cơ bị sa thải đã bất ngờ quay về thời trung học. Để bù đắp những tiếc nuối trong đời, cô quyết tâm biến trái tim si tình thành lý trí sự nghiệp, mượn tri thức và tài năng của học sinh giỏi Lận Chi Hoa để làm lại cuộc đời. Cũng từ đó, một mối tình ngọt ngào, cùng nỗ lực, cùng trở thành biến số trong đời nhau, đã dần dần nảy nở.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 8, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tôn Chân Ni","avatar":""},{"name":"Trần Tĩnh Khải","avatar":""},{"name":"Cát Thu Cúc","avatar":""},{"name":"Đồ Chất Anh","avatar":""},{"name":"Ngô Sùng Hiên","avatar":""},{"name":"Viên Đại Tần","avatar":""},{"name":"Điền Nghi Đồng","avatar":""},{"name":"Quải Gia Lạc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["谈恋爱不如上清华","Wo Zai Ding Feng Deng Ni","我在顶峰等你"]', 1784690324149);
