INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-gai-toi-tro-thanh-con-trai-roi', 'Bạn Gái Tôi Trở Thành Con Trai Rồi!', 'My Girlfriend Is The Man!', 'https://phimimg.com/upload/vod/20250724-1/3cd946db86eeec1a30f8784511dbe2cf.jpg', 'https://phimimg.com/upload/vod/20250724-1/9f03904e9f23c99660581f6980160150.jpg', '<p>Một phép màu bất ngờ xảy ra biến cô nàng Ji Eun xinh đẹp trở thành chàng trai Ji Hun, đẩy mối tình với Yun Jae vào thử thách. Họ phải vật lộn tìm cách trở lại, trong khi tình địch xuất hiện, chen vào mối quan hệ của cả hai. Tuy nhiên, tình yêu đích thực có thể vượt qua mọi giới hạn và biến cố bất ngờ, đòi hỏi sự chấp nhận và kiên cường.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yoon San-ha","avatar":""},{"name":"Choi Ye-won","avatar":""},{"name":"Yoo Jung-hoo","avatar":""},{"name":"CHUU","avatar":""},{"name":"Choi Yun-la","avatar":""},{"name":"Do Ji-won","avatar":""},{"name":"Cho Eun-sook","avatar":""},{"name":"Lee Yoon-geon","avatar":""},{"name":"Kim Kwang-shik","avatar":""},{"name":"Park Ju-won","avatar":""},{"name":"Lee So-won","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["我的女友比我帅","حبيبتي رجل!","我的女友比我帥","My Girlfriend is a Hot Guy","My Girlfriend is a Tough Guy","내 여자친구는 상남자"]', 1784690324149);
