INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-tuyen-tai-xuat', 'Hỏa Tuyến Tái Xuất', 'A Line Of Fire', 'https://phimimg.com/upload/vod/20250828-1/27514fec5f57de446edc4df2aefd16d5.jpg', 'https://phimimg.com/upload/vod/20250828-1/cce3bef94a701a906f7a12605405f64b.jpg', '<p>Jack &quot;Cash&quot;, đặc vụ FBI đã từ bỏ tất cả vì gia đình. Dù đã có cuộc sống trọn vẹn nhưng Cash vẫn luôn tiếc nuối công việc cũ. Và cuộc gọi cầu cứu của Jamie đã đưa anh về lại thế giới đầy nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"David A.R. White","avatar":""},{"name":"Cuba Gooding Jr.","avatar":""},{"name":"Jason Patric","avatar":""},{"name":"Katrina Bowden","avatar":""},{"name":"Scott Baio","avatar":""},{"name":"Gabriel ''G-Rod'' Rodriguez","avatar":""},{"name":"Samantha Lockwood","avatar":""},{"name":"Tommy Snider","avatar":""},{"name":"Vincent De Paul","avatar":""},{"name":"Mehdi Merali","avatar":""},{"name":"Eve Richards","avatar":""},{"name":"Dana Anderwald","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["火线","A Line of Fire"]', 1784690324149);
