INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lot-xac', 'Lột Xác', 'The Switch', 'https://phimimg.com/upload/vod/20250828-1/da5be85104c208c603ba44ca88e0abfa.jpg', 'https://phimimg.com/upload/vod/20250828-1/2a4d3449d55b5b6c89fdc86662413e98.jpg', '<p>Trước khi chết ở kiếp trước, Phương Tư Vũ phát hiện ra chồng mình là Châu Khải đã âm mưu cùng cô bạn thân Tưởng Y Nhất tráo đổi con của cô, thậm chí còn sát hại Tống Thành, chồng của Tưởng Y Nhất. Sống lại một kiếp, cô quyết định hợp tác với Tống Thành để cùng vạch trần âm mưu thâm độc và thay đổi vận mệnh bi thảm. Trong quá trình báo thù, tình cảm giữa họ dần nảy sinh. Cuối cùng, cả hai đã lật tẩy thành công kế hoạch của kẻ xấu, nghịch thiên cải mệnh và cùng xây dựng cuộc sống mới.</p>', 'Hoàn Tất (60/60)', 60, 'series', 'completed', 19, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phim Ngắn","slug":"phim-ngan","id":"4f02d28224c0747511790d57fbb63a62"}]', '[]', 1784690324149);
