INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-ra-the-thong-gi-nua-2025', 'Còn Ra Thể Thống Gì Nữa', 'How Dare You!?', 'https://phimimg.com/upload/vod/20250828-1/1d0177c65327b9c37f96e040907f7e3b.jpg', 'https://phimimg.com/upload/vod/20250828-1/8c4746cc2702d8840dde1df8f041b5d9.jpg', '<p>Một nhân viên văn phòng bình thường tên Vương Thúy Hoa tình cờ xuyên không vào một cuốn tiểu thuyết &quot;xuyên không não tàn&quot; và trở thành nữ phụ phản diện Dữu Vãn Âm. Để thoát khỏi số phận bị nữ chính xuyên không gốc là Tạ Vĩnh Nhi tiêu diệt, Dữu Vãn Âm quyết định tìm đường sống mới bằng cách nương tựa vào bạo quân Hạ Hầu Đạm, vốn cũng là một nhân vật phản diện. Bất ngờ thay, bạo quân cũng là một người xuyên không. Hai kẻ phản diện &quot;đồng cảnh ngộ&quot; quyết định hợp tác chiến lược để sinh tồn. Tuy nhiên, nữ chính Tạ Vĩnh Nhi lại tự coi mình là &quot;thiên mệnh chi nữ&quot; và không ngần ngại về phe nam chính Hạ Hầu Bạc, đối đầu với Dữu Vãn Âm và Hạ Hầu Đạm. Vừa phải đối phó với những màn đấu đá chốn cung cấm với nữ chính cũng là người xuyên không, vừa phải đề phòng những tính toán của nam chính, liệu cặp đôi phản diện này có thể thay đổi được số phận?</p>', 'Hoàn Tất (89/89)', 89, 'series', 'completed', 25, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Niệm","avatar":""},{"name":"Hạ Tùng Thụy","avatar":""},{"name":"Giả Nghị Tuyên","avatar":""},{"name":"Trịnh Trung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phim Ngắn","slug":"phim-ngan","id":"4f02d28224c0747511790d57fbb63a62"}]', '["Cheng He Ti Tong","成何体统！","微剧成何体统","ทะลุมิติ ตะลุยวังหลวง","成何体统"]', 1784690324149);
