INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-bao-tam-tung', 'Hộ Bảo Tầm Tung', 'The Lost National Treasure', 'https://phimimg.com/upload/vod/20250521-1/8167bd3c80d7944f1e3e68bf52ba7ea6.jpg', 'https://phimimg.com/upload/vod/20250521-1/d2d70ea36d966acddd127939dec8b076.jpg', '<p>Phương Khôn, nghiên cứu sinh ngành Khảo cổ tại Đại học Tần Xuyên, trong quá trình hỗ trợ truy tìm cổ vật thất lạc ở nước ngoài, phát hiện một lăng mộ tại làng Ấn, Bình Lộc Nguyên có thể chính là lăng hoàng đế cấp cao chưa được biết đến. Thầy hướng dẫn Trẩn Mậu Xương dẫn cô đến thực địa khảo sát tại Bình Lộc Nguyên, nhưng không ngờ đã hy sinh nơi đây. Mang theo di nguyện của thầy, Phương Khôn trưởng thành và trở thành thành viên của đội khảo cổ. Việc phát hiện lăng mộ bí ẩn ở làng Ấn nhanh chóng thu hút sự quan tâm của giới khảo cổ. Phương Khôn được mời tham gia đợt khảo sát mới và tại đây cô tái ngộ Lạc Thanh, người yêu cũ đã lên chức đội trưởng khảo cổ. Khi Phương Khôn khơi lại những giả thuyết năm xưa, không chỉ gây tranh cãi trong giới học thuật, mà còn đánh thức tham vọng của các bọn tội phạm trộm bán cổ vật. Phương Khôn, Lạc Thanh cùng Đội trưởng Đội Trinh sát Cổ vật Cục Công an Tề Đại Thương — những chiến sĩ bảo vệ di sản văn hóa tuyến đầu — đã huy động người dân địa phương tham gia bảo vệ di tích, phối hợp đấu trí đấu dũng với băng nhóm tội phạm do Mộc Kiến Huy cầm đầu, bảo vệ vững chắc di sản quý báu của Bình Lộc Nguyên.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Bai Yufan","avatar":""},{"name":"Xin Baiqing","avatar":""},{"name":"Wang Herun","avatar":""},{"name":"Fu Dalong","avatar":""},{"name":"You Yongzhi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["国宝耀世","国宝迷踪","护宝寻踪","The Lost National Treasure"]', 1784690324149);
