INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('guilty-gear-strive-dual-rulers', 'Guilty Gear Strive: Dual Rulers', 'Guilty Gear Strive: Dual Rulers', 'https://phimimg.com/upload/vod/20250420-1/d01fcd43df4b3568e35465faff5f83af.jpg', 'https://phimimg.com/upload/vod/20250420-1/fa83475e18c570ff30784362df5e3b53.jpg', '<p>Sau khi các lĩnh vực khoa học và công nghệ từng rất hùng mạnh sụp đổ, một nguồn năng lượng mới gọi là ma thuật trở thành nền tảng cho thời đại hiện đại. Nhân loại đã tạo ra các vũ khí sinh học bị cấm gọi là Gear. Những Gear này cuối cùng nổi dậy chống lại loài người trong một cuộc nổi loạn. Dù nhân loại đã chiến thắng trong cuộc chiến sống còn được gọi là Thập tự chinh (Crusades), nhưng tổn thất của họ lớn đến mức nhiều thập kỷ sau đó, những vết thương lòng vẫn chưa thể hoàn toàn lành lại. Sin Kiske, đứa trẻ sinh ra từ một con người và một Gear, đang trên đường tới dự lễ cưới của cha mình là Ky và mẹ là Dizzy. Hôn lễ này đã phá vỡ điều cấm kỵ lớn nhất: sự kết hợp giữa con người và Gear. Dù thế giới đang trong hòa bình, nhưng phải mất rất nhiều năm mới có thể tổ chức được lễ cưới này. Mặc dù có những cảm xúc phức tạp vây quanh, buổi lễ vẫn diễn ra với nhiều lời chúc phúc. Đột nhiên, một cô gái bí ẩn xuất hiện... Một đứa trẻ mang trong mình dòng máu Gear định mệnh, và cô gái bí ẩn có lòng căm ghét sâu sắc đối với Gear. Cuộc gặp gỡ của họ sẽ làm rung chuyển cả thế giới.</p>', 'Tập 8', 12, 'hoathinh', 'ongoing', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Issei Miyazaki","avatar":""},{"name":"Jouji Nakata","avatar":""},{"name":"Yui Ishikawa","avatar":""},{"name":"Takeshi Kusao","avatar":""},{"name":"Kazue Fujita","avatar":""},{"name":"Manaka Iwami","avatar":""},{"name":"Megumi Han","avatar":""},{"name":"Aya Suzaki","avatar":""},{"name":"Hiromi Igarashi","avatar":""},{"name":"Mayumi Asano","avatar":""},{"name":"Norio Wakamoto","avatar":""},{"name":"Tetsu Inada","avatar":""},{"name":"Junichi Endo","avatar":""},{"name":"Yasuhiro Mamiya","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["ギルティギア ストライヴ：デュアル ルーラーズ","GUILTY GEAR -STRIVE- DUAL RULERS","길티기어 스트라이브: 듀얼 룰러스","聖騎士之戰 奮戰：DUAL RULERS","GUILTY GEAR STRIVE: DUAL RULERS"]', 1784690324149);
