INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-ma-hon-loan', 'Mật Mã Hỗn Loạn', 'Serial Homicide', 'https://phimimg.com/upload/vod/20250818-1/8021c398b8c778d18f5f8914a794150e.jpg', 'https://phimimg.com/upload/vod/20250818-1/2781b8d34221c3b09d90ee42238ed0e7.jpg', '<p>Sự yên bình của thành phố Lộc Châu bị phá vỡ bởi một vụ án giết người hàng loạt được cho là nhằm &quot;trừng trị cái ác, đề cao cái thiện&quot;. Cơ quan công an đã thành lập &quot;Tổ chuyên án 909&quot; để điều tra. Trải qua muôn vàn khó khăn, tổ chuyên án đã từng bước bóc tách, lật mở từng lớp sự thật kinh hoàng đằng sau kế hoạch trả thù bằng cách trao đổi giết người mang tên &quot;Erinyes&quot;.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"gưu Tuấn Phong","avatar":""},{"name":"Gia Nghệ","avatar":""},{"name":"Lư Sam","avatar":""},{"name":"Đổng Dũng","avatar":""},{"name":"Yiding Lv","avatar":""},{"name":"Triệu Kha","avatar":""},{"name":"Qianwei Su","avatar":""},{"name":"Túc Vũ Kiệt","avatar":""},{"name":"Trần Di Trinh","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Messy Code","乱码迷局"]', 1784690324149);
