INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-sat-sieu-nang', 'Cảnh Sát Siêu Năng', 'Thunderstruck Cop', 'https://phimimg.com/upload/vod/20250827-1/ad0c33ebc80aaa6fab3e43479f054f3b.jpg', 'https://phimimg.com/upload/vod/20250827-1/4fab35dcd4231aca13c7b23d2b76e0e6.jpg', '<p>Một ngày nọ, Hyun-joon – một cảnh sát sống cùng mẹ và cô con gái nhỏ – bất ngờ có được siêu năng lực sau khi bị sét đánh. Sau biến cố ấy, anh phát hiện ra rằng còn có những người khác cũng trải qua tình huống giống mình, và dần bị cuốn vào hàng loạt sự việc ngoài mong đợi. Giữa vai trò của một người cha đang chật vật hàn gắn mối quan hệ với con gái và một cảnh sát mang sức mạnh siêu nhiên quyết tâm truy bắt kẻ tội phạm tàn ác, liệu Hyun-joon có thể cùng lúc làm tròn cả hai?</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Soo-mi","avatar":""},{"name":"Shin Hyun-joon","avatar":""},{"name":"Chae Si-yeon","avatar":""},{"name":"Jung Jun-ho","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Молниеносный полицейский","Ghost Police","Gwisin Kyeongchal","Thunderstruck Cop","Policía atónito","귀신경찰"]', 1784690324149);
