INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('my-melody-va-kuromi', 'My Melody Và Kuromi', 'My Melody & Kuromi', 'https://phimimg.com/upload/vod/20250725-1/bbb97507d4ed1a2bade78f5846d163c5.jpg', 'https://phimimg.com/upload/vod/20250725-1/1cd3ba4e7f02af1fdc4317cbc3c5eee6.jpg', '<p>Khi chuyến thăm Vương quốc Mây của My Melody dẫn đến hàng loạt rắc rối, liệu cô, Kuromi và bạn bè có thể cứu được quê nhà của họ trước khi quá muộn?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Rei Sakuma","avatar":""},{"name":"Junko Takeuchi","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["美乐蒂&库洛米","Μάι Μέλοντι & Κουρόμι","Maimerodi to Kuromi","マイメロディとクロミ","My Melody and Kuromi","My Melody & Kuromi"]', 1784690324149);
