INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('my-melody-va-kuromi', 'My Melody Và Kuromi', 'My Melody & Kuromi', 'my melody và kuromi my melody & kuromi rei sakuma junko takeuchi 美乐蒂&库洛米 μάι μέλοντι & κουρόμι maimerodi to kuromi マイメロディとクロミ my melody and kuromi my melody & kuromi', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-vien', 'Học Viện', 'The Institute', 'https://phimimg.com/upload/vod/20250718-1/e052fd8c641832a04b026785d39a2743.jpg', 'https://phimimg.com/upload/vod/20250718-1/a82c915db45c04e1f45cc4b35c5b8779.jpg', '<p>Luke Ellis là một thần đồng nhí mười hai tuổi với dự định theo học tại hai trường đại học cùng một lúc. Nhưng vào một đêm ngay sau khi hoàn thành kì thi SAT, có những kẻ đột nhập vào nhà, sát hại bố mẹ cậu và bắt cậu đi. Cậu tỉnh dậy trong một căn phòng giống hệt phòng ngủ của mình, nhưng nơi này là vùng nơi hẻo lánh nằm giữa vùng rừng già Bắc Maine. Ở đây có những đứa trẻ đặc biệt giống như cậu, sinh sống ở Khu nửa trước. Giám đốc của Học viện, bà Sigsby, và các nhân viên của bà ta hằng ngày tàn nhẫn khai thác sức mạnh từ những đứa trẻ này, những món quà đặc biệt của chúng. Nếu bạn vâng lời, bạn sẽ nhận được mã để mua bất kì thứ gì từ các máy bán hàng tự động. Nếu bạn không làm vậy, hình phạt rất tàn bạo. Mỗi khi một đứa trẻ bị đưa tới Khu nửa sau và không bao giờ trở lại, Luke ngày càng trở nên tuyệt vọng với việc trốn thoát ra ngoài và tìm sự giúp đỡ. Chưa từng có ai trốn thoát khỏi Học Viện. Sự thật đằng sau nơi được gọi là Học Viện này là gì? Và cái kết nào cho những đứa trẻ bị bắt tới Học Viện?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ben Barnes","avatar":""},{"name":"Joe Freeman","avatar":""},{"name":"Simone Miller","avatar":""},{"name":"Fionn Laird","avatar":""},{"name":"Hannah Galway","avatar":""},{"name":"Julian Richings","avatar":""},{"name":"Robert Joy","avatar":""},{"name":"Martin Roach","avatar":""},{"name":"Mary-Louise Parker","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["异能研究所","L''Istituto","المعهد","The Institute"]', 1784690324149);
