INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoc-vien', 'Học Viện', 'The Institute', 'học viện the institute ben barnes joe freeman simone miller fionn laird hannah galway julian richings robert joy martin roach mary-louise parker 异能研究所 l''istituto المعهد the institute', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phe-pham', 'Phế Phẩm', 'The Defects', 'https://phimimg.com/upload/vod/20250722-1/4afcc49697db4f99db5121db2576f23c.jpg', 'https://phimimg.com/upload/vod/20250722-1/858a10e22e39274be836438d69080933.jpg', '<p>Kim Se Hui là giám đốc của một bệnh viện lớn và là người điều hành một quỹ từ thiện, được công chúng vô cùng kính trọng với tư cách một bác sĩ tài năng. Tuy nhiên, đằng sau vỏ bọc hoàn hảo đó, cô ta chính là kẻ cầm đầu một tổ chức nhận con nuôi bất hợp pháp, do Jung Hyeon điều hành. Kim Se Hui mang một niềm tin lệch lạc rằng chỉ những gen ưu việt mới xứng đáng tồn tại. Tổ chức này cung cấp chính sách &quot;hoàn trả miễn phí&quot; trong một khoảng thời gian nhất định cho những đứa trẻ được nhận nuôi bất hợp pháp nhưng không đáp ứng được kỳ vọng của cha mẹ nuôi. Khi một đứa trẻ bị &quot;hoàn trả&quot;, nhóm của Kim Se Hui sẽ sát hại đứa trẻ đó để phi tang chứng cứ phạm tội. Kim A Hyeon là một trong những đứa trẻ bị &quot;hoàn trả&quot; nhưng đã sống sót một cách thần kỳ. Giờ đây, cô bé trở thành người lãnh đạo và là chỗ dựa tinh thần cho những đứa trẻ sống sót khác. Kim A Hyeon quyết tâm đối đầu với Kim Se Hui để giành lấy sự sống và báo thù.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yum Jung-ah","avatar":""},{"name":"Won Jin-ah","avatar":""},{"name":"Choi Young-jun","avatar":""},{"name":"Dex","avatar":""},{"name":"Ahn Ji-ho","avatar":""},{"name":"Lee Na-eun","avatar":""},{"name":"Oh Seung-jun","avatar":""},{"name":"Kang Ji-yong","avatar":""},{"name":"Son Jong-hak","avatar":""},{"name":"Song Young-gyu","avatar":""},{"name":"Kim Soo-ro","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["المَعيبون","The Defects","Child Shopping","아이쇼핑"]', 1784690324149);
