INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pham-nhan-tu-tien-truyen', 'Phàm Nhân Tu Tiên Truyện', 'The Immortal Ascension', 'https://phimimg.com/upload/vod/20250724-1/8ac37168234fcdee704b2e60e3f8a2a2.jpg', 'https://phimimg.com/upload/vod/20250724-1/3acd42b880b9afc0e80ce1b3b66f4825.jpg', '<p>Phàm Nhân Tu Tiên Truyện là hành trình tu luyện khốc liệt của Hàn Lập, một thiếu niên nghèo có ước mơ trở thành tiên nhân. Với xuất thân bình thường, Hàn Lập gia nhập một môn phái nhỏ rồi dựa vào nỗ lực cùng mưu trí của bản thân để vượt qua vô số nghịch cảnh trên con đường tu tiên đầy hiểm nguy. Với tạo hình đẹp mắt, kỹ xảo ấn tượng cùng loạt cảnh chiến đấu mãn nhãn, đây là tác phẩm tiên hiệp hứa hẹn sẽ mang đến trải nghiệm thị giác vượt trội cho người xem.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 41, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Dương","avatar":""},{"name":"Kim Thần","avatar":""},{"name":"Vương Thác","avatar":""},{"name":"Triệu Tiểu Đường","avatar":""},{"name":"Triệu Thanh","avatar":""},{"name":"Kim Gia Diệp","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Thần Thoại","slug":"than-thoai","id":"2276b29204c46f75064735477890afd6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Fan Ren Xiu Xian Zhuan","凡人修仙传剧版","Fanren Xiu Xian Chuan","Fanren Xiu Xian Zhuan","범인수선전(드라마)","학사신공(드라마)","凡人脩僊傳","The Immortal Ascension","Phàm Nhân Tu Tiên Truyện","凡人修仙传"]', 1784690324149);
