INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('minh-nguyet-nhap-khanh-hoai', 'Minh Nguyệt Nhập Khanh Hoài', 'A Forbidden Marriage', 'https://phimimg.com/upload/vod/20250818-1/2a93a8aef35cd8d338a36a4634e4e33d.jpg', 'https://phimimg.com/upload/vod/20250818-1/4cd3a49c059dc4c67f70e757469b269a.jpg', '<p>Bộ phim được chuyển thể từ tiểu thuyết &quot;Sư Thúc, Người Cứ Vậy Là Mất Ta Như Chơi Đó&quot; của tác giả Y Nhân Khuê Khuê, kể về câu chuyện của nữ sĩ ma giáo Vọng Nguyệt (do Chu Khiết Quỳnh thủ vai), tái sinh sau cái chết và phải lòng nam chính trong chính đạo. Vọng Nguyệt (do Chu Khiết Quỳnh thủ vai), một thánh nữ của Thánh Hỏa giáo tàn độc, thoát khỏi cảnh chỉ treo mành chuông bèn phiêu bạt trông khốn đốn và cô độc, quyết tâm hoàn thành ước nguyện mà cô không thể hoàn thành trước đây: có được tình yêu của Trưởng lão Chính đạo - Dương Thanh. Mang .Vọng Nguyệt tái sinh, tình cờ tương ngộ với Dương Thanh, cuối cùng cả hai cùng nhau lang bạt giang hồ, hợp sức tiêu diệt thủ lĩnh thực sự của Ma giáo, tạo sự hòa giải giữa Thánh Hỏa và Chính phái, và đem lại hòa bình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Tân","avatar":""},{"name":"Châu Khiết Cường","avatar":""},{"name":"Mao Tử Tuấn","avatar":""},{"name":"Lý Cửu Lâm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["师叔你这样很容易失去我","명월입경회 : 그대 품에 안긴 밝은 달","Senior, You Will Lose Me Easily Like This","A Forbidden Marriage","明月入卿怀"]', 1784690324149);
