INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('minh-nguyet-nhap-khanh-hoai', 'Minh Nguyệt Nhập Khanh Hoài', 'A Forbidden Marriage', 'minh nguyệt nhập khanh hoài a forbidden marriage trương tân châu khiết cường mao tử tuấn lý cửu lâm 师叔你这样很容易失去我 명월입경회 : 그대 품에 안긴 밝은 달 senior, you will lose me easily like this a forbidden marriage 明月入卿怀', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-giam', 'Lồng Giam', 'Lock Her', 'https://phimimg.com/upload/vod/20250817-1/8128df552918671686fc54af683de987.jpg', 'https://phimimg.com/upload/vod/20250817-1/b1c994db96ae8483f9d974240d04f189.jpg', '<p>Đêm Trung Thu cả nhà bị sát hại, Tần Thời Nguyệt của nhà họ Tần được đốc quân Đới Thế Nghiêu cưu mang. Để điều tra án oan của cha, cô rơi vào vòng xoáy giữa hai anh em, em trai Sênh từ cướp đoạt đến yêu đậm sâu, anh trai Đới Thế Nghiêu từ nghi ngờ đến rung động. Khi chiến tranh bùng lên lần nữa, ba người đã phá vỡ số phận của mình. Sênh bỏ kiếm vì tình, Đới Thế Nghiêu từ bỏ tình yêu vì thành, trong máu lửa Tần Thời Nguyệt cuối cùng cũng tìm được chân tướng và cuộc sống mới.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Bách Huệ","avatar":""},{"name":"Hà Sưởng Hy","avatar":""},{"name":"Trần Kiến Vũ","avatar":""},{"name":"Vu Hân Ngật","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Lao Long","Lock Her","牢笼"]', 1784690324149);
