INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('com-nua-mua', 'Cớm Nửa Mùa', 'Cop & A Half', 'https://phimimg.com/upload/vod/20250826-1/34d58e504c645e5702923070d23c869c.jpg', 'https://phimimg.com/upload/vod/20250826-1/302ea790d0c6e62e9ce8588868ae40ce.jpg', '<p>Giữa lòng Johannesburg náo nhiệt, hai con người trái ngược buộc phải trở thành đồng đội bất đắc dĩ: một cảnh sát nguyên tắc đến cứng nhắc và một gã chỉ điểm dẻo miệng chẳng mấy đáng tin. Khi cả hai bị ném vào cuộc săn lùng đường dây ma túy khét tiếng, những mâu thuẫn dở khóc dở cười nhanh chóng biến thành một thứ đồng đội kỳ lạ. Và trên hành trình vừa nghẹt thở vừa tràn ngập tiếng cười ấy, họ gây ra không ít hỗn loạn — nhưng cũng có thể là hy vọng duy nhất để hạ gục băng nhóm tàn bạo nhất thành phố.</p>', 'Full', 1, 'single', 'completed', 26, 2025, 'Vietsub', 'FHD', 'Nam Phi', 0, '[{"name":"Jonathan Boynton-Lee","avatar":""},{"name":"Trevor Gumbi","avatar":""},{"name":"Noxolo Dlamini","avatar":""},{"name":"Jack Devnarain","avatar":""},{"name":"Bouwer Bosch","avatar":""},{"name":"Thulani Mtsweni","avatar":""},{"name":"Nthati Moshesh","avatar":""},{"name":"Nadine Theron","avatar":""},{"name":"Kabelo Tsotetsi","avatar":""},{"name":"Stevel Marc","avatar":""},{"name":"Mbasa Jongisizwe Msongelo","avatar":""},{"name":"Simphiwe Ngema","avatar":""},{"name":"Kaseran Pillay","avatar":""},{"name":"Laré Birk","avatar":""},{"name":"Mpho ''El Chyna''","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Cop & a Half"]', 1784690324149);
