INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('com-nua-mua', 'Cớm Nửa Mùa', 'Cop & A Half', 'cớm nửa mùa cop & a half jonathan boynton-lee trevor gumbi noxolo dlamini jack devnarain bouwer bosch thulani mtsweni nthati moshesh nadine theron kabelo tsotetsi stevel marc mbasa jongisizwe msongelo simphiwe ngema kaseran pillay laré birk mpho ''el chyna'' cop & a half', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-quai-xe', 'Nữ Quái Xế', 'Eenie Meanie', 'https://phimimg.com/upload/vod/20250826-1/331e376a25e9793046f94818452400a7.jpg', 'https://phimimg.com/upload/vod/20250826-1/518dd32ae9c8f5cfd9ab5773e9e65f2c.jpg', '<p>Ngày xưa, cô từng là tay lái bỏ trốn tuổi teen lẫy lừng. Giờ đây, khi tưởng đã chôn vùi quá khứ tội lỗi, cô lại bị kéo trở lại thế giới ngầm. Một ông chủ cũ xuất hiện, đưa ra lời đề nghị: cứu lấy mạng sống của gã bạn trai cũ — kẻ vừa quen thuộc, vừa nguy hiểm, nhưng chưa bao giờ biết giữ chữ tín. Trước ngã rẽ sinh tử, cô buộc phải tăng tốc lần nữa, không chỉ để thoát hiểm, mà còn để quyết định liệu tình yêu cũ có xứng đáng với một cú lái định mệnh.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Samara Weaving","avatar":""},{"name":"Karl Glusman","avatar":""},{"name":"Andy García","avatar":""},{"name":"Steve Zahn","avatar":""},{"name":"Jermaine Fowler","avatar":""},{"name":"Marshawn Lynch","avatar":""},{"name":"Randall Park","avatar":""},{"name":"Mike O''Malley","avatar":""},{"name":"Elle Graham","avatar":""},{"name":"Kyanna Simone Simpson","avatar":""},{"name":"Chris Bauer","avatar":""},{"name":"Chelsey Crisp","avatar":""},{"name":"Phuong Kubacki","avatar":""},{"name":"Rob Grant","avatar":""},{"name":"Davis Aguila","avatar":""},{"name":"Jon Elliott","avatar":""},{"name":"Sarah Alaina","avatar":""},{"name":"T","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["이니미니","Velocidad salvaje","La conductora","Эники-Беники","Eenie Meanie"]', 1784690324149);
