INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nu-quai-xe', 'Nữ Quái Xế', 'Eenie Meanie', 'nữ quái xế eenie meanie samara weaving karl glusman andy garcía steve zahn jermaine fowler marshawn lynch randall park mike o''malley elle graham kyanna simone simpson chris bauer chelsey crisp phuong kubacki rob grant davis aguila jon elliott sarah alaina t 이니미니 velocidad salvaje la conductora эники-беники eenie meanie', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-nhan-gian', 'Tại Nhân Gian', 'What A Wonderful World', 'https://phimimg.com/upload/vod/20250528-1/023ba24ff14f28c550ea03926fc28312.jpg', 'https://phimimg.com/upload/vod/20250528-1/0e087a5c43789d3209e3089449f2f17a.jpg', '<p>Thế giới của người trưởng thành đầy những điều tầm thường, cuộc sống cứ thế lặng lẽ bào mòn tâm hồn. Người ta vừa sụp đổ vừa tự chữa lành, cứ thế mà chắp vá những vết thương lòng. Cô đơn theo nhịp phồn hoa của đô thị, cuốn con người vào khu rừng bê tông cốt thép vô tận, nơi không thể tìm thấy ánh sáng hay một bầu trời thuộc về chính mình. Nhưng trong ánh mắt phản chiếu qua gương chiếu hậu, hai con người dần buông bỏ lớp vỏ bọc, hạ xuống mọi phòng bị. Họ tìm thấy sự cứu rỗi trong tình yêu, để linh hồn có thể ôm lấy nhau. Giữa thực và ảo, giữa bí ẩn và giải mã, giữa tổn thương và cứu chuộc, đích đến cuối cùng chính là bản thân ta. Khi nhìn lại nhân gian, không còn thấy cô đơn nữa...</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Lệ Dĩnh","avatar":""},{"name":"Doãn Phương","avatar":""},{"name":"Trương Nhất Sơn","avatar":""},{"name":"Chu Nhất Vi","avatar":""},{"name":"Đổng Tử Kiện","avatar":""},{"name":"Tôn Thiên","avatar":""},{"name":"Cát Tranh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["What A Wonderful World","在人间"]', 1784690324149);
