INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-hien-moi-ac', 'Vợ Hiền Mới Ác', 'The Good Wife''s Secret', 'https://phimimg.com/upload/vod/20250814-1/55ea2879c9e722656a10e9a66fac25fa.jpg', 'https://phimimg.com/upload/vod/20250814-1/62bfeb164918ff4fc9c3bdc74a20a06e.jpg', '<p>Đối mặt cú sốc chồng ngoại tình với cháu ruột của mình, bà Trang không làm ầm ĩ gì mà lấy nhu thắng cương để đáp trả. Nhưng đóa hồng xinh đẹp, đằm thắm dễ làm ta quên đi một thân gai nhọn của nó.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 13, 2025, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Syni Diễm Trang","avatar":""},{"name":"Thanh Thức","avatar":""},{"name":"NSƯT Kim Tuyến","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324149);
