INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vo-hien-moi-ac', 'Vợ Hiền Mới Ác', 'The Good Wife''s Secret', 'vợ hiền mới ác the good wife''s secret syni diễm trang thanh thức nsưt kim tuyến ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-tac-dang-ngo-ban-nhat', 'Đối Tác Đáng Ngờ (Bản Nhật)', 'Ayashii Partner', 'https://phimimg.com/upload/vod/20250501-1/f547120a5ea8833ecefbcdd65d39cebb.jpg', 'https://phimimg.com/upload/vod/20250501-1/f24a919a22927387fe523d9015ca5331.jpg', '<p>Tateishi Haruto, một công tố viên tài giỏi, bị Miyashita Sakura hiểu lầm là kẻ quấy rối trên xe buýt và trải qua một tình huống tồi tệ. Sau đó, anh tình cờ gặp lại Sakura khi cô đang cãi nhau vì bị bạn trai phản bội, và không hiểu sao anh lại giúp cô một cách vô thức... Điều này dẫn đến việc Haruto bị cuốn vào buổi nhậu say xỉn với Sakura, và khi anh hoàn toàn say mèm, cô đã đẩy anh ngã xuống! Vài ngày sau, Haruto tái ngộ với Sakura — lần này cô đến để tham gia kỳ thực tập công tố viên. Haruto nghiêm khắc với Sakura, nhưng chẳng hiểu sao anh lại không thể bỏ mặc cô. Hai người họ đã bắt đầu bằng một cuộc gặp gỡ tồi tệ nhất có thể. Liệu cuộc gặp này là sự trùng hợp? Hay là định mệnh? Một câu chuyện tình cảm hài hước vừa ngọt ngào vừa cay đắng giữa hai con người vụng về trong tình yêu, sẽ khiến bạn tin vào duyên phận.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yusei Yagi","avatar":""},{"name":"Kyoko Saito","avatar":""},{"name":"Takuya Kusakawa","avatar":""},{"name":"Kokoro Morita","avatar":""},{"name":"Kuu Izima","avatar":""},{"name":"Kazunari Tosa","avatar":""},{"name":"Koh Takasugi","avatar":""},{"name":"Ikkei Watanabe","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["あやしいパートナー"]', 1784690324149);
