INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-tu-trach-tam', 'Cẩm Tú Trạch Tâm', 'Threads Of Destiny', 'https://phimimg.com/upload/vod/20250810-1/b000ab6a8bf9e775671352db9dc77623.jpg', 'https://phimimg.com/upload/vod/20250810-1/47efc9a829d1b87322c642bda650911e.jpg', '<p>Phim kể về tỷ tỷ Khương Tuyết Doanh và muội muội Khương Vũ Nhi cùng sống lại. Sau khi đổi hôn sự, tỷ tỷ trở thành thế tử phi, đấu trí với nữ quyến chốn hậu viện, đồng thời chinh phục phu quân giả làm công tử ăn chơi. Hai vợ chồng cùng kề vai vạch trần âm mưu của kẻ phản diện.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chu Lệ Nham","avatar":""},{"name":"Tần Thiên Vũ","avatar":""},{"name":"Mục Lạc Ân","avatar":""},{"name":"Vương Trạch Hiên","avatar":""},{"name":"Mã Quân Kha","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jin Xiu Zhai Xin","锦绣宅心"]', 1784690324149);
