INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cam-tu-trach-tam', 'Cẩm Tú Trạch Tâm', 'Threads Of Destiny', 'cẩm tú trạch tâm threads of destiny chu lệ nham tần thiên vũ mục lạc ân vương trạch hiên mã quân kha jin xiu zhai xin 锦绣宅心', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ot-nho-thap-nien-80', 'Ớt Nhỏ Thập Niên 80', 'Spice Up The 80''s', 'https://phimimg.com/upload/vod/20250816-1/93cc985c4c444b58712cde2af5bc6fc6.jpg', 'https://phimimg.com/upload/vod/20250816-1/154a68bf6c56c9331e70ffc123b11f31.jpg', '<p>Cuối thập niên 80, cô gái mồ côi Lâm Hiểu Tiêu bị người cô ép gả chồng để lấy tiền sính lễ. Trong lúc tuyệt vọng, cô vùng lên phản kháng để viết lại số phận của mình. Cô dũng cảm đến Dương Thành, từ một nhân viên phục vụ nhà hàng, cô đã nhận thấy cơ hội kinh doanh và kiếm được đồng vốn đầu tiên. Sau đó, cô bước chân vào ngành thời trang, chống chọi với sự gây khó dễ của côn đồ, chịu đựng những âm mưu hãm hại từ đối thủ cạnh tranh và cùng với thiếu gia Lương Khác Thanh phá tan từng âm mưu. Từ một cô gái mồ côi ở Mai Giang trở thành một ngôi sao mới trong giới kinh doanh, hành trình lội ngược dòng của cô ẩn chứa nhiệt huyết và ánh hào quang của tất cả những người theo đuổi ước mơ!</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tông Nguyên Viên","avatar":""},{"name":"Ngô Trúc Hi","avatar":""},{"name":"Khương Ngọc Giai","avatar":""},{"name":"Vương Nhân Khả","avatar":""},{"name":"Lưu Dĩ Hạt","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ba Ling Xiao La Jiao","八零小辣椒"]', 1784690324149);
