INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ot-nho-thap-nien-80', 'Ớt Nhỏ Thập Niên 80', 'Spice Up The 80''s', 'ớt nhỏ thập niên 80 spice up the 80''s tông nguyên viên ngô trúc hi khương ngọc giai vương nhân khả lưu dĩ hạt ba ling xiao la jiao 八零小辣椒', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-tien-chi-dao-xiao-xian-zhi-yao', 'Tiểu Tiên Chi Dao (Xiao Xian Zhi Yao)', 'Little Fairy Yao', 'https://phimimg.com/upload/vod/20250804-1/6c567708ab7a3a6e1c26a23ef5b5f705.jpg', 'https://phimimg.com/upload/vod/20250804-1/f1e285897d82bc7b5ee42f88042aa898.jpg', '<p>Giữa cơn gió lạnh thổi qua chín tầng trời, vị nữ chúa của Ẩn tộc, kẻ khiến tam giới kinh hãi được biết đến với cái tên Hòa Uyển đã bất ngờ dẫn quân xâm lấn Thiên Đình. Không hề nao núng, Nam Trạch, vị thượng thần uy dũng, đứng lên nghênh chiến, được trợ giúp bởi Ngu Chi Dao, một tiên nữ chăm sóc ngọc lan giản dị, liều mình bảo vệ ngài. Giữa thời khắc định mệnh ngàn cân treo sợ bún đồng sinh cộng tử của Nam Trạch và Hòa Uyển, Chi Dao đã chẳng may chết đi nhưng đã được gửi trở lại, và cũng kỳ diệu thay, sự tái sinh này đã đưa cô cộng sinh trong nhục thể của Hoà Uyển. Sức mạnh Ẩn tộc trong cô gần như tan biến. Cùng lúc đó thì Thính Chiêu, một ẩn vệ từ vùng biển Tây Hải đã xuất hiện để hỗ trợ nữ chúa của mình lấy lại thần lực. Từ đó, Chi Dao sống hai cuộc đời: trước bá tánh, cô giữ vẻ uy nghiêm của bậc tôn chủ, nhưng bên người thân thiết, cô hóa thành thiếu nữ nhu mì, nết na.</p>', 'Tập 40', 60, 'hoathinh', 'ongoing', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Liangwei Hu","avatar":""},{"name":"Li Ai","avatar":""},{"name":"王宁","avatar":""},{"name":"Jiang Qiuzai","avatar":""},{"name":"姜贺","avatar":""},{"name":"Zhang Enze","avatar":""},{"name":"Yuantao Zhang","avatar":""},{"name":"Yu Minglu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1