INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tieu-tien-chi-dao-xiao-xian-zhi-yao', 'Tiểu Tiên Chi Dao (Xiao Xian Zhi Yao)', 'Little Fairy Yao', 'tiểu tiên chi dao (xiao xian zhi yao) little fairy yao liangwei hu li ai 王宁 jiang qiuzai 姜贺 zhang enze yuantao zhang yu minglu xiao xian zhi yao la pequeña hada del jade little fairy yao tiểu tiên chi dao 小仙之瑶', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieng-on-quy-di-2025', 'Tiếng Ồn Quỷ Dị', 'Noise', 'https://phimimg.com/upload/vod/20250825-1/4892d0d25a9d267f0ac5b550d45a1628.jpg', 'https://phimimg.com/upload/vod/20250825-1/c19b22932efaaeff3e03002b0917ecf3.jpg', '<p>TIẾNG ỒN QUỶ DỊ là câu chuyện về hai chị em Joo Young và Joo Hee. Sau khi dọn vào căn hộ mới, cả hai liên tục bị quấy nhiễu bởi những tiếng động kỳ quái phát ra từ giữa các tầng – thứ âm thanh âm ỉ, vặn vẹo như thể có ai đó… hoặc thứ gì đó đang sống giữa các bức tường. Rồi một ngày, Joo Hee biến mất không dấu vết. Joo Young cùng bạn trai của em gái lao vào cuộc truy tìm trong vô vọng – khi càng đào sâu, họ càng tiến gần đến một bí mật đen tối bị chôn vùi sau những bức tường cách âm. Cùng lúc đó, người đàn ông sống tầng dưới cũng bị tra tấn bởi chính thứ âm thanh đó và tin rằng, con quái vật nằm ngay trong căn hộ của hai chị em.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 1, '[{"name":"Lee Sun-bin","avatar":""},{"name":"Kim Min-seok","avatar":""},{"name":"Jeon Ik-ryoung","avatar":""},{"name":"Ryu Kyung-soo","avatar":""},{"name":"Han Su-ah","avatar":""},{"name":"Baek Joo-hee","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Noijeu","噪声","Noise - Hörst du es auch","Noise","노이즈"]', 1784690324149);
