INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tieng-on-quy-di-2025', 'Tiếng Ồn Quỷ Dị', 'Noise', 'tiếng ồn quỷ dị noise lee sun-bin kim min-seok jeon ik-ryoung ryu kyung-soo han su-ah baek joo-hee noijeu 噪声 noise - hörst du es auch noise 노이즈', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-dai-co-cay', 'Tiên Đài Có Cây', 'Love Of The Divine Tree', 'https://phimimg.com/upload/vod/20250207-1/cfca86e74599a803c437a7c0f0755758.jpg', 'https://phimimg.com/upload/vod/20250207-1/1799d614967528f3931cb133bd5bf398.jpg', '<p>Thần đạo thiên tài Tô Dịch Thủy và sư phụ của anh, Mục Thanh Ca . Mười tám năm trước, sư phụ Mục Thanh Ca đã thay đổi số phận của Tô Dịch Thủy, nhưng việc này đã đẩy cô trở thành &quot;Nữ Ma Đầu&quot; và khiến cô phải chịu án oan và qua đời. Mười tám năm sau, Mục Thanh Ca đã biến thành Tiết Nhiễm Nhiễm, trong khi Tô Dịch Thủy đã trở thành Trưởng môn phái Tây Sơn. Tô Dịch Thủy quyết định đón Tiết Nhiễm Nhiễm, người đang đối mặt với nguy cơ chết vì bệnh tật, vào môn phái của mình và tuyên thệ sẽ bảo vệ cô suốt đời. Khi đó, vai trò giữa sư phụ và đồ đệ của họ đã hoán đổi. Câu chuyện của họ sẽ đầy bi hài và đầy cảm động về những thử thách và trải nghiệm mà họ phải đối mặt trong tình thầy trò đầy đặc biệt này.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 6, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Đặng Uy","avatar":""},{"name":"Tương Hãn Chi","avatar":""},{"name":"Trần Tân Hải","avatar":""},{"name":"Trương Vệ Na","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["仙台有树","Xian Tai You Shu","Xiantai You Shu","XianTaiYouShu","仙臺有樹","仙台有樹","อาจารย์มารหวนภพ","僊臺有樹","僊台有樹","𠑗臺有樹"]', 1784690324149);
