INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tien-dai-co-cay', 'Tiên Đài Có Cây', 'Love Of The Divine Tree', 'tiên đài có cây love of the divine tree đặng uy tương hãn chi trần tân hải trương vệ na 仙台有树 xian tai you shu xiantai you shu xiantaiyoushu 仙臺有樹 仙台有樹 อาจารย์มารหวนภพ 僊臺有樹 僊台有樹 𠑗臺有樹', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-nhan', 'Song Nhẫn', 'Higher', 'https://phimimg.com/upload/vod/20250814-1/98e24cdf76d0471323683220db31562e.jpg', 'https://phimimg.com/upload/vod/20250814-1/024076eab707e49aebcb32870fb74a78.jpg', '<p>Khương Chấn, huấn luyện viên của “Trại huấn luyện Cuồng Phong”, vì cái chết của em gái Tiểu Đồng mà cải trang nằm vùng trong Tập đoàn Tử Tinh để điều tra vụ tai nạn xe tự hành gây chết người. Trong quá trình thực hiện nhiệm vụ, anh tình cờ gặp lại Bạch Phàm – người từng là cộng sự nhưng nay là kẻ thù. Từ những màn thăm dò lẫn nhau, cả hai dần hợp tác, làm sáng tỏ sự thật vụ tai nạn năm xưa và còn tìm ra bằng chứng Tập đoàn Tử Tinh lợi dụng công nghệ giao diện não - máy để làm điều ác. Sau đó, họ liên thủ với Nông Thiên Nhã - người cũng từng chịu sự áp bức của nhà họ Nông - và cùng nhau đập tan âm mưu của Nông Thương Khâm, chủ tịch Tập đoàn Tử Tinh.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Tập Tuấn","avatar":""},{"name":"Mã Tiểu Vũ","avatar":""},{"name":"Châu Tử Hâm","avatar":""},{"name":"Vu Khiêm","avatar":""},{"name":"Nghiệp Văn","avatar":""},{"name":"Triệu Nghĩa","avatar":""},{"name":"Tùng Hâm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["双刃"]', 1784690324149);
