INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-thoat-mua-5', 'Đào Thoát (Mùa 5)', 'The Great Escape : The Story', 'https://phimimg.com/upload/vod/20250727-1/78d044a3d5b5e7d6bc9ab916fcb102d3.jpg', 'https://phimimg.com/upload/vod/20250727-1/6746b06b17ea97f6e2be0d155c64e22d.jpg', '<p>Tiếp nối danh tiếng của chương trình với những thử thách thoát hiểm phức tạp và những câu đố hấp dẫn, mùa thứ 5 trở lại với những gương mặt quen thuộc: Kang Ho Dong, Kim Dong Hyun, Yoo Byung Jae, đồng thời kết nạp thêm các thành viên mới là Go Kyung Pyo, Byun Baek Hyun và Yeo Jin Goo. Liệu họ có tìm ra manh mối để đào thoát?</p>', 'Hoàn Tất (10/10)', 10, 'tvshows', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kang Ho-dong","avatar":""},{"name":"Kim Dong-hyun","avatar":""},{"name":"Yoo Byung-jae","avatar":""},{"name":"Go Kyung-pyo","avatar":""},{"name":"Baekhyun","avatar":""},{"name":"Yeo Jin-goo","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Great Escape : The Story Special","대탈출 : 더 스토리 특별판"]', 1784690324149);
