INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-thanh-doi-san-quy', 'Đêm Thánh: Đội Săn Quỷ', 'Holy Night: Demon Hunters', 'https://phimimg.com/upload/vod/20250520-1/75069cdc357e5a2e40224c65e85be55d.jpg', 'https://phimimg.com/upload/vod/20250520-1/eb74244b20279a883f5100975835c6a1.jpg', '<p>Đêm Thánh Đội Săn Quỷ là bộ phim Hàn mới nhất với sự góp mặt của ông chú Ma Dong Seok. Seoul chìm trong hỗn loạn khi một mạng lưới tội phạm tôn thờ ma quỷ xuất hiện. Trong sự cầu xin tuyệt vọng để được cứu rỗi, cảnh sát buộc phải nhờ đến ‘Đêm Thánh’, một bộ ba thợ săn quỷ được trang bị sức mạnh siêu nhiên. Liệu ‘Đêm Thánh’ có thể chinh phục ách thống trị của quỷ dữ và khôi phục trật tự cho thành phố?</p>', 'Full', 1, 'single', 'completed', 10, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 1, '[{"name":"Don Lee","avatar":""},{"name":"Seohyun","avatar":""},{"name":"David Lee","avatar":""},{"name":"Gyeong Su-jin","avatar":""},{"name":"Jung Ji-so","avatar":""},{"name":"Lee Da-il","avatar":""},{"name":"Cha Woo-jin","avatar":""},{"name":"Kim Do-gun","avatar":""},{"name":"Jeon Ik-ryoung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Geo-rok-han: de-mun heon-teo-seu","Georukhan bam: demon heonteoseu","聖夜：惡魔都市","거룩한 밤: 데몬 헌터스"]', 1784690324149);
