INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dem-thanh-doi-san-quy', 'Đêm Thánh: Đội Săn Quỷ', 'Holy Night: Demon Hunters', 'đêm thánh: đội săn quỷ holy night: demon hunters don lee seohyun david lee gyeong su-jin jung ji-so lee da-il cha woo-jin kim do-gun jeon ik-ryoung geo-rok-han: de-mun heon-teo-seu georukhan bam: demon heonteoseu 聖夜：惡魔都市 거룩한 밤: 데몬 헌터스', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-la-dai-luc-kiem-dao-tran-tam', 'Đấu La Đại Lục: Kiếm Đạo Trần Tâm', 'Soul Land Movie: Sword Dao Chenxin', 'https://phimimg.com/upload/vod/20250714-1/0ea9c5b3f342801aad8739c5197ee914.jpg', 'https://phimimg.com/upload/vod/20250714-1/f8ce1578d2e4a901d0784575a04534f1.jpg', '<p>Hai mươi năm trước trận chiến cuối cùng ở Đấu La Đại Lục, Vũ Hồn Điện từng âm mưu thống nhất toàn bộ giới Hồn Sư, thôn tính tất cả các tông môn. Thất Bảo Lưu Ly Tông là mục tiêu đầu tiên, rơi vào hiểm cảnh. Cốt Đấu La đã đưa thiếu chủ của tông môn - Ninh Vinh Vinh năm tuổi - đến mời Kiếm Đấu La ra tay tương trợ. Thế là, Kiếm Đấu La Trần Tâm mang theo tiểu Vinh Vinh dấn thân vào một con đường chạy trốn sinh tử. Tuy nhiên, điều họ không hề hay biết là đằng sau con đường này lại là một âm mưu to lớn, sẽ ảnh hưởng đến toàn bộ Đấu La Đại Lục...</p>', 'Full', 1, 'hoathinh', 'completed', 6, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Sang Yuze","avatar":""},{"name":"Huang Xiangyu","avatar":""},{"name":"Liu Beichen","avatar":""},{"name":"Li Chanfei","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["斗罗剧场剑道尘心","斗罗大陆剧场版：剑道尘心","Douluo Dalu Movie: Kendo Dust Heart","斗罗大陆之剑道尘心","Douluo Dalu Jiandao Chen Xin","Soul Land The Movie Sword Of Dust","Soul Land Movie Sword Master","斗羅大陸劇場版：劍道塵心","鬥羅大陸劇場版：劍道塵心","Douluo Dalu Movie: Sword of Dust","Soul Land Movie: Sword of Dust","斗罗大陆剧场版 剑道尘心"]', 1784690324149);
