INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dau-la-dai-luc-kiem-dao-tran-tam', 'Đấu La Đại Lục: Kiếm Đạo Trần Tâm', 'Soul Land Movie: Sword Dao Chenxin', 'đấu la đại lục: kiếm đạo trần tâm soul land movie: sword dao chenxin sang yuze huang xiangyu liu beichen li chanfei 斗罗剧场剑道尘心 斗罗大陆剧场版：剑道尘心 douluo dalu movie: kendo dust heart 斗罗大陆之剑道尘心 douluo dalu jiandao chen xin soul land the movie sword of dust soul land movie sword master 斗羅大陸劇場版：劍道塵心 鬥羅大陸劇場版：劍道塵心 douluo dalu movie: sword of dust soul land movie: sword of dust 斗罗大陆剧场版 剑道尘心', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-quai-song-ngu-menh', 'Yêu Quái Sông Ngũ Mệnh', 'Strange Stories Of Five Lives River', 'https://phimimg.com/upload/vod/20250823-1/7fd1308c7b7c23edeeb4d94ce9824304.jpg', 'https://phimimg.com/upload/vod/20250823-1/0f8b0607c8a70677c322e6faeb1aa284.jpg', '<p>Vào đầu thời Dân Quốc, ở phía Bắc sông Dương Tử có một con sông mà hằng năm đều có người chết đuối một cách kỳ lạ. Số người chết không nhiều cũng không ít, đúng tròn năm người. Lâu dần, dân chúng gọi con sông ấy là “Ngũ Mệnh Hà”. Tương truyền trong dân gian: “Trăng không lộ, người không đi. Trên sông quỷ nhỏ rập rình.” Ngũ Mệnh Hà, mỗi năm ít nhất phải có năm người chết. Năm nay đã có ba người rồi… cho đến khi Bát Gia xuất hiện, những chuyện kỳ dị ấy mới dần có chuyển biến.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Bành Vu Khư","avatar":""},{"name":"Thành Siêu Việt","avatar":""},{"name":"Vương Song Bảo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Ghost Story The River of Five Lives","深河迷案","怪谈五命河"]', 1784690324149);
