INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-khong-the-mat-di', 'Tình Yêu Không Thể Mất Đi', 'Everlasting Love', 'https://phimimg.com/upload/vod/20250823-1/ab10e3ea82b9cb3b52643d34499ff777.jpg', 'https://phimimg.com/upload/vod/20250823-1/a4450dae60fb9a5937144650e5e5ccc5.jpg', '<p>Cái gọi là số mệnh chính là “ban đầu là em, cuối cùng vẫn là em”. Lâm Thất Thất, sau khi trải qua biến cố lớn trong cuộc đời, tình cờ cứu được Lâm Nam Nhất và từ đó hai người đem lòng yêu nhau. Người bạn thân Đinh Chân đã chứng kiến vô số khoảnh khắc khó quên của họ. Khi mọi điều tốt đẹp đang dần mở ra, những hiểu lầm lại khiến đôi tình nhân đi đến bờ vực chia ly. Thế nhưng, một lần tái ngộ tưởng chừng như ngẫu nhiên đã giúp họ nhận ra rằng: chúng ta có thể bỏ lỡ bất kỳ ai, nhưng duy chỉ không thể bỏ lỡ nhau. Dù có lạc mất nhau, anh cũng sẽ liều mình để tìm lại em.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Quách Tuấn Thần","avatar":""},{"name":"Tôn Dật Hàm","avatar":""},{"name":"Chu Văn","avatar":""},{"name":"Cốc Tân Nghi","avatar":""},{"name":"Đinh Chân Chân","avatar":""},{"name":"Ông Hồng","avatar":""},{"name":"Hàn Đổng","avatar":""},{"name":"Lữ Nhất","avatar":""},{"name":"Đoạn Áo Quyên","avatar":""},{"name":"Trần Bác Hào","avatar":""},{"name":"Thẩm Vũ","avatar":""},{"name":"Dương Mạn Lãnh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["永不失聯的愛","小妖的金色城堡","Xiao Yao De Jin Se Cheng Bao","Yong Bu Shi Lian De Ai","永不失联的爱"]', 1784690324149);
