INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tinh-yeu-khong-the-mat-di', 'Tình Yêu Không Thể Mất Đi', 'Everlasting Love', 'tình yêu không thể mất đi everlasting love quách tuấn thần tôn dật hàm chu văn cốc tân nghi đinh chân chân ông hồng hàn đổng lữ nhất đoạn áo quyên trần bác hào thẩm vũ dương mạn lãnh 永不失聯的愛 小妖的金色城堡 xiao yao de jin se cheng bao yong bu shi lian de ai 永不失联的爱', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('in-the-hand-of-dante', 'Thần Khúc Dante', 'In The Hand Of Dante', 'https://phimimg.com/upload/vod/20250823-1/ea386e5447ebb0b004128e6dfa0ee620.jpg', 'https://phimimg.com/upload/vod/20250823-1/ffeedbc69e88599a78d33f9052df0499.jpg', '<p>Một bản thảo viết tay quý giá của kiệt tác Thần khúc do Dante Alighieri sáng tác vô tình rơi vào tay một ông trùm mafia khét tiếng ở New York, sau khi được truyền qua tay một vị linh mục bí ẩn. Khi nhà văn Nick Tosches được mời xác minh tính thật giả của bản thảo, anh đã bị cuốn vào một hành trình đầy uẩn khúc.</p>', 'Full', 1, 'single', 'completed', 19, 2025, 'Vietsub', 'FHD', 'Chile', 0, '[{"name":"Oscar Isaac","avatar":""},{"name":"Gerard Butler","avatar":""},{"name":"John Malkovich","avatar":""},{"name":"Louis Cancelmi","avatar":""},{"name":"Jason Momoa","avatar":""},{"name":"Gal Gadot","avatar":""},{"name":"Sabrina Impacciatore","avatar":""},{"name":"Martin Scorsese","avatar":""},{"name":"Al Pacino","avatar":""},{"name":"Franco Nero","avatar":""},{"name":"Benjamin Clémentine","avatar":""},{"name":"Paolo Bonacelli","avatar":""},{"name":"Ibrahim Elouahabi","avatar":""},{"name":"Gavin Weingarten","avatar":""},{"name":"Dario Samac","avatar":""},{"name":"Duke Nicholson","avatar":""},{"name":"Deni","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Dante''nin Əlindən","در دست دانته","Dantův rukopis","In the Hand of Dante"]', 1784690324149);
