INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuong-an-giai-hoan', 'Thường An Giai Hoan', 'Everbloom Dynasty', 'https://phimimg.com/upload/vod/20250823-1/369f0d76809460201efaa2645a20aa8a.jpg', 'https://phimimg.com/upload/vod/20250823-1/73277cad15cdf315addb8be8fa9f7807.jpg', '<p>17 năm trước, do bị mẹ kế ghét bỏ, Yến Giai Hoan bị đưa lên núi để vừa dưỡng bệnh vừa học y thuật. 17 năm sau, nàng vui vẻ xuống núi để mừng thọ phụ thân, nhưng vừa trở về phủ đã lại bị hãm hại: tận mắt chứng kiến cha mình bị sát hại, còn bản thân thì bị vu oan là kẻ giết cha. Bằng trí tuệ và sự bình tĩnh, nàng lần lượt hóa giải các cuộc thẩm vấn, chứng minh sự trong sạch và phát hiện kẻ đứng sau âm mưu này ẩn náu trong triều đình. Sau đó, Yến Giai Hoan tìm cách tiến cung, tại đây nàng gặp Cảnh Vương gia, người cũng từng chịu cảnh oan khiên. Hai người quyết tâm hợp lực điều tra chân tướng, trừng trị kẻ thủ ác, diệt trừ gian thần và lật lại triều cục. Câu chuyện khắc họa một bản tình ca bi tráng giữa chốn nhân gian đầy hiểm nguy: “Có chàng, ta luôn hoan hỉ”.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tôn Tử Hàng","avatar":""},{"name":"Hoàng Ức Tử","avatar":""},{"name":"Lý Nghệ","avatar":""},{"name":"Trần Phẩm Diên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chang An Jie Huan","常安皆欢"]', 1784690324149);
