INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-tuong-chi-thanh', 'Vô Tướng Chi Thành', 'The Formless City', 'https://phimimg.com/upload/vod/20250812-1/05794cf0ccf716a27207ef7e77c572bb.jpg', 'https://phimimg.com/upload/vod/20250812-1/2964385ed86a33b91b14f702a54246d4.jpg', '<p>Câu chuyện kể về Hứa Lâm Lang, một nữ pháp y trẻ tuổi, vì một vụ án mạng mà bị cuốn vào vòng xoáy giang hồ. Cô cùng với Lộc Cửu và Tư Mã Không tạo thành bộ ba nhiệt huyết, cùng nhau phá án trong một &quot;thế giới ngầm của giang hồ&quot; đan xen giữa các thế lực như Vô Tướng Thành. Trên hành trình đó, họ đã vạch trần sự thật, trưởng thành và có những mối duyên tình cảm đầy ý nghĩa.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Tuấn Thần","avatar":""},{"name":"Đới Giai Mẫn","avatar":""},{"name":"Huỳnh Dịch Bân","avatar":""},{"name":"Tiêu Chính Nam","avatar":""},{"name":"Thi Nam","avatar":""},{"name":"Huỳnh Trí Hiền","avatar":""},{"name":"Trần Trinh Di","avatar":""},{"name":"Hác Di Lâm","avatar":""},{"name":"Lý Phong Càn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wu Xiang Zhi Cheng","无相之城"]', 1784690324149);
