INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-mang-trong-con-say', 'Án Mạng Trong Cơn Say', 'The Tipsy Mystery', 'https://phimimg.com/upload/vod/20250723-1/139576ef44e6f8a697f72ae135b0e562.jpg', 'https://phimimg.com/upload/vod/20250723-1/ad4303b483c04c71dc35b5fcfedaed53.jpg', '<p>Tỉnh dậy sau một đêm ăn chơi trác táng, bà đồng Phing cùng bốn tay sát gái khét tiếng Pi, Ter, Jock và Dung phát hiện thi thể lạnh ngắt của Bam, cô gái đã cùng tiệc tùng với họ đêm hôm trước. Phing cố gắng dùng năng lực của mình để liên lạc với hồn ma của Bam và tìm ra hung thủ. Trớ trêu thay, lúc bị sát hạt Bam lại say đến mức ngay cả hồn ma của cô cũng không nhớ chuyện gì đã xảy ra. Phing sẽ phải làm thế nào để vạch trần sự thật phía sau vụ Án Mạng Trong Cơn Say này?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 9, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Engfa Waraha","avatar":""},{"name":"Porapat Srikajorn","avatar":""},{"name":"Rachata Hampanont","avatar":""},{"name":"Sarun Naraprasertkul","avatar":""},{"name":"Nichaphat Chatchaipholrat","avatar":""},{"name":"Cholawit Meetongcom","avatar":""},{"name":"Supathat Opas","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["ฆาตกรรมจำไม่ได้"]', 1784690324149);
