INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-xuan-tuoi-tre', 'Mùa Xuân Tuổi Trẻ', 'Spring Of Youth', 'https://phimimg.com/upload/vod/20250508-1/9de3bd636a0184bf6b6154aa15c1a56c.jpg', 'https://phimimg.com/upload/vod/20250508-1/dddb177534301578b494a59ede35d6ea.jpg', '<p>Bị loại khỏi ban nhạc của một ngôi sao K-pop, chàng trai nọ đi học đại học rồi phải lòng một cô sinh viên âm nhạc – người có thể mở ra cánh cửa cho dự án âm nhạc tiếp theo của anh.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 9, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ha Yu-jun","avatar":""},{"name":"Park Ji-hu","avatar":""},{"name":"Lee Seung-hyub","avatar":""},{"name":"Jo Han-chul","avatar":""},{"name":"Kim Jong-tae","avatar":""},{"name":"Cha Chung-hwa","avatar":""},{"name":"Seo Hye-won","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["青春之春","四季之春","사계의 봄"]', 1784690324149);
