INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-chen-say-tinh', 'Một Chén Say Tình', 'Second Shot At Love', 'https://phimimg.com/upload/vod/20250514-1/aef68160fd7995a9c49619c207884947.jpg', 'https://phimimg.com/upload/vod/20250514-1/feafeb5a7672829a1c920d11c6d46f4f.jpg', '<p>Một người phụ nữ luôn tự nhận mình là người &quot;yêu&quot; rượu rất mực “hợp lý”. Nhưng mọi thứ đảo lộn khi cô tình cờ gặp lại mối tình đầu — một người đàn ông hoàn toàn bài xích rượu bia. Muốn giữ hình tượng hoàn hảo trước crush, cô quyết tâm bắt đầu hành trình... cai rượu! Từ những buổi tiệc thiếu men say đến những cuộc hẹn đầy ngượng ngùng khi tỉnh táo, cô nhận ra: cai rượu thì khó, nhưng giữ vững con tim trước người cũ còn khó hơn.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 9, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Sooyoung Choi","avatar":""},{"name":"Gong Myoung","avatar":""},{"name":"Jo Yoon-hee","avatar":""},{"name":"Kim Sung-ryung","avatar":""},{"name":"Kim Sang-ho","avatar":""},{"name":"Kang Hyung-suk","avatar":""},{"name":"Kim Tae-oh","avatar":""},{"name":"Yeom Seung-e","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["戒酒吧拜托了","拜托戒酒吧","금주를 부탁해","فرصة ثانية للحب","Extremely Common Sense Alcoholic","Please Stop Drinking","Extremely Sensible Alcoholic"]', 1784690324149);
