INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luu-manh', 'Lưu Manh (Đáy Xã Hội)', 'Low Life', 'https://phimimg.com/upload/vod/20250717-1/5df03886518387cbc7757adb4bb37afc.jpg', 'https://phimimg.com/upload/vod/20250717-1/e30082cb9c1022b1524c45c50638e621.jpg', '<p>Chuyển thể từ webtoon Fine của tác giả Yoon Tae Ho dựa trên những sự kiện có thật trong thập niên 1970, Low Life kể về những con người sống bằng bản năng và toan tính trên hành trình truy tìm kho báu từ con tàu chở nhiều vật phẩm quý bị chìm ngoài khơi Shinan vào năm 1977. Trung tâm của câu chuyện là Oh Gwan Sok (Ryu Seung Ryong), kẻ đầu sỏ kiếm tiền bất chấp, sống dựa vào các mánh khóe vặt cùng đứa cháu Oh Hee Dong (Yang Se Jong). Khi nghe tin đồn về đồ gốm cổ bị chôn vùi dưới biển Shinan, ông quyết tâm đến Mokpo với hy vọng đổi đời.</p>', 'Full', 11, 'series', 'completed', 8, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ryu Seung-ryong","avatar":""},{"name":"Yang Se-jong","avatar":""},{"name":"Lim Soo-jung","avatar":""},{"name":"Kim Eui-sung","avatar":""},{"name":"Kim Seung-o","avatar":""},{"name":"Kim Jong-soo","avatar":""},{"name":"Lee Dong-hwi","avatar":""},{"name":"U-KNOW","avatar":""},{"name":"Kim Min","avatar":""},{"name":"Jang Kwang","avatar":""},{"name":"Hong Gi-jun","avatar":""},{"name":"Woo Hyeon","avatar":""},{"name":"Lim Hyung-jun","avatar":""},{"name":"Lee Sang-jin","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Low Life","巴人","حياة وضيعة","Pain","Pain: chontteugideul","파인: 촌뜨기들"]', 1784690324149);
