INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-san-dao-mo', 'Thợ Săn Dao Mổ', 'Hunter With A Scalpel', 'https://phimimg.com/upload/vod/20250616-1/2ace9121403b8d6b5bf74d73b7dec50c.jpg', 'https://phimimg.com/upload/vod/20250616-1/db6ea08729ce1b6fedb5acc231e22012.jpg', '<p>Bác sĩ pháp y thiên tài Seo Se-Hyun (Park Ju-Hyun), người mang rối loạn nhân cách chống đối xã hội. Cô phát hiện dấu vết tội ác của cha mình, Yoon Jo-Kyun (Park Yong Woo), một kẻ sát nhân hàng loạt tưởng chừng đã chết, qua những vụ án mới với phương pháp giết người đặc trưng. Cuộc đối đầu giữa hai cha con trở thành trò chơi trí tuệ đẫm máu, nơi Se-Hyun vừa che giấu quá khứ, vừa truy lùng cha để bảo vệ bản thân. Bộ phim khắc họa mối quan hệ cha-con độc hại, đặt câu hỏi về ranh giới thiện-ác trong huyết thống.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 11, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Ju-hyun","avatar":""},{"name":"Park Yong-woo","avatar":""},{"name":"Kang Hoon","avatar":""},{"name":"Ryu Seung-su","avatar":""},{"name":"Bin Chan-uk","avatar":""},{"name":"Ryu Hae-jun","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["صياد بمشرط","Dark Legacy","메스를 든 사냥꾼"]', 1784690324149);
