INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-dai-hoc-duong-phan-2', 'Chị Đại Học Đường (Phần 2)', 'Bitch And Rich (Season 2)', 'https://phimimg.com/upload/vod/20250703-1/1806a101043f1364ca923dade456e7da.jpg', 'https://phimimg.com/upload/vod/20250703-1/9c13e31cc9f962028de6284cfc755aa1.jpg', '<p>Chị Đại Học Đường - Bitch Rich xoay quanh cuộc chiến tâm lý giữa hai nữ sinh liên quan đến một vụ án mạng. Nội dung kể về Kim Hye In, cô gái được chuyển đến trường trung học quốc tế Cheongdam để đối lấy sự im lặng trước những sự thật chỉ có cô mới biết liên quan tới một vụ sát hại nữ sinh trung học. Tại đây, cô gặp Baek Je Na - nghi phạm lớn nhất trong vụ án và cũng là nữ sinh quyền lực nhất trường trung học Cheongdam đồng thời là tiểu thư của một tập đoàn lớn tại Hàn Quốc. Cơn ác mộng của Kim Hye In từ đó bắt đầu.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 39, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Eun-saem","avatar":""},{"name":"YERI","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["청담국제고등학교"]', 1784690324149);
