INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yandere-dark-elf-co-ay-duoi-theo-toi-tu-di-gioi', 'Yandere Dark Elf: Cô ấy đuổi theo tôi từ dị giới!', 'Yandere Dark Elf: She Chased Me All the Way from Another World!', 'https://phimimg.com/upload/vod/20250421-1/0ffc6f925361214c2559f5c105aebb55.jpg', 'https://phimimg.com/upload/vod/20250421-1/52a3bed2060582971c2a07ca6e0598bd.jpg', '<p>Hinata đã làm được. Cậu ấy đã được tái sinh sang một thế giới khác, nhận lấy danh hiệu Anh hùng và tiêu diệt Chúa quỷ đáng sợ cùng với nhóm bạn đồng hành của mình. Như một phần thưởng, cậu ấy được trở lại Trái Đất để tiếp tục cuộc sống bình thường. Hoặc đáng lẽ sẽ là như vậy nếu không phải vì sự thật là người bạn đồng hành Dark Elf Mariabelle của cậu ấy đã quyết định đến Trái Đất để sống cùng cậu ấy! Giờ đây, cô ấy sử dụng tài năng ma thuật của mình để xua đuổi bất kỳ đối thủ tình cảm tiềm năng nào và chiếm được tình cảm của Hinata.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Rie Kawamura","avatar":""},{"name":"Minami Takahashi","avatar":""},{"name":"Kyouka Maruyama","avatar":""},{"name":"Hinako Takahashi","avatar":""},{"name":"Ayumi Mano","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["爱有些沉重的黑暗精灵从异世界追过来了","爱有点沉重的暗黑精灵从异世界紧追不放","爱有点沉重的暗黑精灵从异世界紧追不放(无修版)","קצת יותר מדי אהבה! אלפית אפלה רודפת אחרי מעולם אחר","Chotto dake Ai ga Omoi Dark Elf ga Isekai kara Oikakete Kita","Chotto dake Ai ga Omoi Dark Elf ga Isekai kara Oikaketekita","愛重ダークエルフ","AiomoDarkElf","ชตโตะ ดาเกะ ไอ งะ โอโมอิ ดาร์กเอลฟ์ งะ อิเซไก การะ โออิกาเกเตะ คิตะ","愛有點沉重的暗黑精靈從異世界緊追不放","愛有些沉重的黑暗精靈從異世界追過來了","Темна ельфійка-яндере. Вона переслідувала мене аж із іншого світу!","A Slightly Pushy Dark Elf Chased Me From Another World","yandere dark elf","Yandere Dark Elf She Chased Me All the Way From Another World!","ちょっとだけ愛が重いダークエルフが異世界から追いかけてきた"]', 1784690324149);
