INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-the-ly-giai-noi-aharensan-phan-2', 'Chẳng Thể Lý Giải Nổi Aharen-san (Phần 2)', 'Aharen-san Wa Hakarenai (Season 2)', 'https://phimimg.com/upload/vod/20250430-1/48ed61825dfcd1458a03b7d5ae073610.jpg', 'https://phimimg.com/upload/vod/20250430-1/10ad29973f6da63e53b85c5756881103.jpg', '<p>Aharen-san, cô nữ sinh vụng về trong giao tiếp xã hội, gặp khó khăn trong việc giữ khoảng cách cá nhân – lúc thì quá gần, lúc lại quá xa với bạn bè. Một ngày nọ, khi cậu bạn cùng lớp Raido nhặt giúp cô chiếc gôm, cô lập tức xem họ là bạn thân. Từ đó, hai người gắn bó với nhau mọi lúc mọi nơi: học bài, chơi game, ăn trưa… Mối quan hệ ngẫu nhiên ấy dần nở hoa, chứng minh rằng tình cảm có thể bắt đầu từ những khoảnh khắc bất ngờ nhất.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 27, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Inori Minase","avatar":""},{"name":"Takuma Terashima","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Aharen-san, a harmonia nunca morre","不会拿捏距离的阿波连同学","Aharen-san wa Hakarenai","阿波連さんは測れない","Aharen Is Indecipherable","阿波連さんははかれない"]', 1784690324149);
