INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-son-luan-kiem-ngu-tuyet-tranh-phong', 'Hoa Sơn Luận Kiếm: Ngũ Tuyệt Tranh Phong', 'The Five', 'https://phimimg.com/upload/vod/20250810-1/75a0159fd1038df4ad1b42c5da04763d.jpg', 'https://phimimg.com/upload/vod/20250810-1/d2cb9d7de0ac99a6976e50b701ca671c.jpg', '<p>Dựa trên nền tảng là các tác phẩm kinh điển của Kim Dung cùng tinh thần nghĩa hiệp ẩn chứa trong đó, dùng một hình thức mới mẻ để viết nên một áng văn về giang hồ Kim Dung đầy hùng tráng. Lấy kinh điển làm điểm khởi đầu, tiếp nối tiền truyện của Ngũ Tuyệt, đồng thời bổ sung những chuyện cũ trên giang hồ vào những khoảng trống trong nguyên tác.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chu Nhất Vi","avatar":""},{"name":"Cao Vỹ Quang","avatar":""},{"name":"Hà Nhuận Đông","avatar":""},{"name":"Minh Đạo","avatar":""},{"name":"Vu Tiểu Vĩ","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["金庸武侠世界·华山论剑","金庸武侠世界第2季","华山论剑之九阴真经","华山论剑之东邪西毒","华山论剑之南帝北丐","华山论剑之五绝争锋","Duel on Mount Hua: Nine Yin True Sutra","Duel on Mount Hua: Eastern Heretic and Western Venom","Duel on Mount Hua: Southern Emperor and Northern Beggar","Duel on Mount Hua: Five Great Masters","华山论剑","金庸武侠世界","金庸武侠世界之华山论剑","김용무협세계: 화산논검","사조영웅전: 화산논검","ศึกประลองยุทธบนเขาฮว่าซาน เดชมารคัมภีร์นพเก้า","Nine Yin True Sutra","Huashan Swords.The Nine Yin Scriptures","Huashan Swords.The Eastern Heretic and Western Venom","Huashan Swords.The Southern Emperor and Northern Beggar","Huashan Swords.Clash of the Five Greats"]', 1784690324149);
