INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoa-son-luan-kiem-ngu-tuyet-tranh-phong', 'Hoa Sơn Luận Kiếm: Ngũ Tuyệt Tranh Phong', 'The Five', 'hoa sơn luận kiếm: ngũ tuyệt tranh phong the five chu nhất vi cao vỹ quang hà nhuận đông minh đạo vu tiểu vĩ 金庸武侠世界·华山论剑 金庸武侠世界第2季 华山论剑之九阴真经 华山论剑之东邪西毒 华山论剑之南帝北丐 华山论剑之五绝争锋 duel on mount hua: nine yin true sutra duel on mount hua: eastern heretic and western venom duel on mount hua: southern emperor and northern beggar duel on mount hua: five great masters 华山论剑 金庸武侠世界 金庸武侠世界之华山论剑 김용무협세계: 화산논검 사조영웅전: 화산논검 ศึกประลองยุทธบนเขาฮว่าซาน เดชมารคัมภีร์นพเก้า nine yin true sutra huashan swords.the nine yin scriptures huashan swords.the eastern heretic and western venom huashan swords.the southern emperor and northern beggar huashan swords.clash of the five greats', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ken-chong-quy-toc-phan-2', 'Kén Chồng Quý Tộc (Phần 2)', 'The Buccaneers (Season 2)', 'https://phimimg.com/upload/vod/20250626-1/337159a0787b067974086495f5895aa7.jpg', 'https://phimimg.com/upload/vod/20250626-1/f3696273e192a6d8f8fdd01bef7c7a1a.jpg', '<p>Một nhóm các cô gái Mỹ ham vui tới London năm 1870 thời phong kiến gò bó, khơi mào cuộc xung đột văn hóa Anh-Mỹ. Đến để tìm kiếm chồng và địa vị, trái tim của những cô nàng này mong nhiều điều hơn thế.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Kristine Froseth","avatar":""},{"name":"Alisha Boe","avatar":""},{"name":"Matthew Broome","avatar":""},{"name":"Josh Dylan","avatar":""},{"name":"Barney Fishwick","avatar":""},{"name":"Aubri Ibrag","avatar":""},{"name":"Guy Remmers","avatar":""},{"name":"Mia Threapleton","avatar":""},{"name":"Josie Totah","avatar":""},{"name":"Imogen Waterhouse","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Авантюристките","海盗佳丽","上流海盗","浮华年代","上流恋爱家","הבאקנירס","הבוקנירים","The Buccaneers"]', 1784690324149);
