INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lan-theo-vet-khoi', 'Lần Theo Vết Khói', 'Smoke', 'https://phimimg.com/upload/vod/20250627-1/e9dc3173f87d4d3a41eaf32311d2c2a6.jpg', 'https://phimimg.com/upload/vod/20250627-1/13a060af2e3a9a8898b44ff1725ccdcb.jpg', '<p>Khi một điều tra viên hỏa hoạn miễn cưỡng hợp tác với một thanh tra cảnh sát, cuộc đua ngăn chặn hai kẻ phóng hỏa châm ngòi cho một trò chơi rối rắm đầy bí mật và nghi ngờ.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Taron Egerton","avatar":""},{"name":"Jurnee Smollett","avatar":""},{"name":"John Leguizamo","avatar":""},{"name":"Rafe Spall","avatar":""},{"name":"Greg Kinnear","avatar":""},{"name":"Ntare Guma Mbaho Mwine","avatar":""},{"name":"Hannah Emily Anderson","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["烟火寻凶","עשן","Firebug","Smoke"]', 1784690324149);
