INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('golf-thu-ky-tai', 'Golf Thủ Kỳ Tài', 'Stick', 'https://phimimg.com/upload/vod/20250704-1/59b137cf9a3fa8cbdb196c2d60afcf58.jpg', 'https://phimimg.com/upload/vod/20250704-1/9bc39a6734e9d816d5d7f877b8fb90e7.jpg', '<p>Pryce Cahill đang trên đà trở thành huyền thoại làng golf thì một khủng hoảng ngay trên sân đấu đã khiến sự nghiệp anh trật bánh. Giờ đây, trong nỗ lực bấu víu để tiếp tục tồn tại, anh dốc toàn lực để huấn luyện Santi - một thần đồng tuổi teen với tiềm năng to lớn - và có lẽ cũng để cứu lấy chính mình.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Owen Wilson","avatar":""},{"name":"Peter Dager","avatar":""},{"name":"Marc Maron","avatar":""},{"name":"Mariana Treviño","avatar":""},{"name":"Lilli Kay","avatar":""},{"name":"Judy Greer","avatar":""},{"name":"Timothy Olyphant","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["סטיק","Rambler","Rambler & the Birdie Machine","Stick"]', 1784690324149);
