INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-sinh', 'Hồi Sinh', 'Revival', 'https://phimimg.com/upload/vod/20250626-1/5e2997ec37211f951b9a316478fd5f1e.jpg', 'https://phimimg.com/upload/vod/20250626-1/9222c3b7c55411e9d4dfe6d970447fe0.jpg', '<p>Một ngày nọ tại vùng quê Wisconsin, điều kỳ lạ xảy ra: những người mới qua đời bỗng dưng sống lại, nhưng không phải là xác sống — họ trông vẫn như xưa, với ký ức và cảm xúc nguyên vẹn. Cảnh sát Dana Cypress, mẹ đơn thân, bất ngờ vướng vào một vụ án mạng kinh hoàng giữa lúc cả thị trấn chìm trong hỗn loạn và sợ hãi. Trong nơi chốn mà kẻ tình nghi có thể là người sống... hoặc kẻ đã chết, liệu Dana có thể lần ra sự thật?</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Melanie Scrofano","avatar":""},{"name":"Romy Weltman","avatar":""},{"name":"David James Elliott","avatar":""},{"name":"Andy McQueen","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Відродження","Пробудження","Revival"]', 1784690324149);
