INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('retro', 'Retro', 'Retro', 'https://phimimg.com/upload/vod/20250822-1/a37ab3574683677423595a083ac46b47.jpg', 'https://phimimg.com/upload/vod/20250822-1/d7f9c0a2ca645d43f8eacb50964f3909.jpg', '<p>Paari mồ côi, lớn lên trong thế giới tội phạm. Quyết tâm hoàn lương để sống bên người yêu cũ, Rukmini. Nhưng quá khứ đen tối khiến anh rơi vào vòng xoáy bạo lực và âm mưu chết chóc. Phim đậm chất hành động, có chiều sâu tâm lý và được đánh giá cao.</p>', 'Full', 1, 'single', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Suriya","avatar":""},{"name":"Pooja Hegde","avatar":""},{"name":"Joju George","avatar":""},{"name":"Jayaram","avatar":""},{"name":"Vidhu","avatar":""},{"name":"Nassar","avatar":""},{"name":"Prakash Raj","avatar":""},{"name":"Sujith Sankar","avatar":""},{"name":"Singampuli","avatar":""},{"name":"Swasika","avatar":""},{"name":"Karunakaran","avatar":""},{"name":"Avinash Raghudevan","avatar":""},{"name":"Gajaraj","avatar":""},{"name":"Tamizh","avatar":""},{"name":"Prem Kumar","avatar":""},{"name":"Ramachandran Durairaj","avatar":""},{"name":"Remya Suresh","avatar":""},{"name":"Udhayabanu Mageswaran","avatar":""},{"name":"Sandeep Raj","avatar":""},{"name":"Murugavel","avatar":""},{"name":"Ka","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Suriya 44","Cult","Dhammam","Retro","誓约归隐","ரெட்ரோ"]', 1784690324149);
