INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-nhan-2025', 'Siêu Nhân', 'Superman', 'https://phimimg.com/upload/vod/20250717-1/9db34f2c6ae544a645e5d8662afdbadc.jpg', 'https://phimimg.com/upload/vod/20250717-1/0f52ee982b3b734555934ea2198b8511.jpg', '<p>Mùa hè tới đây, Warner Bros. Pictures sẽ mang “Superman” - phim điện ảnh đầu tiên của DC Studios đến các rạp chiếu trên toàn cầu. Với phong cách riêng biệt của mình, James Gunn sẽ khắc họa người hùng huyền thoại trong vũ trụ DC hoàn toàn mới, với sự kết hợp độc đáo của các yếu tố hành động đỉnh cao, hài hước và vô cùng cảm xúc. Một Superman với lòng trắc ẩn và niềm tin vào sự thiện lương của con người sẽ xuất hiện đầy hứa hẹn trên màn ảnh.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"David Corenswet","avatar":""},{"name":"Rachel Brosnahan","avatar":""},{"name":"Nicholas Hoult","avatar":""},{"name":"Edi Gathegi","avatar":""},{"name":"Anthony Carrigan","avatar":""},{"name":"Nathan Fillion","avatar":""},{"name":"Isabela Merced","avatar":""},{"name":"María Gabriela de Faría","avatar":""},{"name":"Skyler Gisondo","avatar":""},{"name":"Sara Sampaio","avatar":""},{"name":"Mikaela Hoover","avatar":""},{"name":"Zlatko Burić","avatar":""},{"name":"Pruitt Taylor Vince","avatar":""},{"name":"Neva Howell","avatar":""},{"name":"Wendell Pierce","avatar":""},{"name":"Christ","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Superman: Legacy","סופרמן: מורשת","超人","سوبرمان"