INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-khac-nguy-nan', 'Thời Khắc Nguy Nan', 'Times Of Peril', 'https://phimimg.com/upload/vod/20250821-1/4b043444b4002021570242f3fed73f69.jpg', 'https://phimimg.com/upload/vod/20250821-1/b5c812e3f82e248124299c9c83c98cae.jpg', '<p>Một nhóm tội phạm quốc tế bí mật vận chuyển ma túy qua đường biển. Trong quá trình truy bắt, lực lượng cảnh sát đặc nhiệm rơi vào tình thế hiểm nguy khi đối mặt với các thế lực tàn bạo, âm mưu phức tạp và nhiều vòng vây chết chóc. Giữa bão tố mịt mùng, những người lính kiên cường phải dùng trí tuệ, lòng quả cảm và tinh thần đồng đội để phá vỡ âm mưu buôn lậu, bảo vệ công lý và sự bình yên cho nhân dân.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Phàn Thiếu Hoàng","avatar":""},{"name":"Đồng Nhất Đan","avatar":""},{"name":"Lý Bính Lôi","avatar":""},{"name":"Vương Uyển Trung","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["危情风云"]', 1784690324149);
