INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhiem-vu-bat-kha-thi-nghiep-bao-phan-2', 'Nhiệm Vụ: Bất Khả Thi - Nghiệp Báo (Phần 2)', 'Mission: Impossible - The Final Reckoning', 'https://phimimg.com/upload/vod/20250520-1/93b6f1f8e35b763a61a92a8c10558e96.jpg', 'https://phimimg.com/upload/vod/20250520-1/4897205e466f093e268e5e0336f667a6.jpg', '<p>Sau khi thoát khỏi vụ tai nạn tàu hỏa thảm khốc, Ethan nhận ra The Entity đang được giấu trên một chiếc tàu ngầm cũ của Nga, nhưng một kẻ thù trong quá khứ của anh tên là Gabriel cũng đang truy đuổi.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Tom Cruise","avatar":""},{"name":"Hayley Atwell","avatar":""},{"name":"Ving Rhames","avatar":""},{"name":"Simon Pegg","avatar":""},{"name":"Esai Morales","avatar":""},{"name":"Pom Klementieff","avatar":""},{"name":"Henry Czerny","avatar":""},{"name":"Holt McCallany","avatar":""},{"name":"Janet McTeer","avatar":""},{"name":"Nick Offerman","avatar":""},{"name":"Hannah Waddingham","avatar":""},{"name":"Tramell Tillman","avatar":""},{"name":"Shea Whigham","avatar":""},{"name":"Greg Tarzan Davis","avatar":""},{"name":"Charles Parnell","avatar":""},{"name":"Mark Gatiss","avatar":""},{"name":"Rolf Saxon","avatar":""},{"name":"Lu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Mission: Impossible - Dead Reckoning Part Two","มิชชั่น:อิมพอสซิเบิ้ล ล่าพิกัดมรณะ ตอนที่สอง","Mission: Impossible Odplata - Druhá část","Немогућа мисија: Одмазда - Други део","Mission: Impossible Odplata - Druhá časť","Nhiệm Vụ Bất Khả Thi: Nghiệp Báo - Phần 2","Mission : Impossible - Dead Reckoning Partie 2","משימה בלתי אפשרית: נקמת מוות - חלק שני","משימה בלתי אפשרית 8: חשבון סופי","碟中谍8：致命清算（下）","Mission: Impossible 8","मिशन: इम्पॉसिबल - द फाइनल रेकनिंग","ミッション：インポッシブル／デッドレコニング PART TWO","Миссия невыполнима: Финальная расплата","Misiune: Imposibilă. Răfuială finală","Mission Impossible - The Final Reckoning","Mission Impossible The Final Reckoning","Mission Impossible, The Final Reckoning","Mission Impossible 8","Mission: Impossible - Bilan Final","Mission Impossible 8 - Dead Reckoning Partie 2","碟中谍8","Mission Impossible 8 - The Final Reckoning","Mission : Impossible – The Final Reckoning","職業特工隊 8 ：最終清算","Mission ː Impossible 8 - The Final Reckoning","职业特工队：最终清算","Mision i pamundur: Llogaria e fundit","Mission: Impossible - The Final Reckoning"]', 1784690324149);
