INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhiem-vu-bat-kha-thi-nghiep-bao-phan-2', 'Nhiệm Vụ: Bất Khả Thi - Nghiệp Báo (Phần 2)', 'Mission: Impossible - The Final Reckoning', 'nhiệm vụ: bất khả thi - nghiệp báo (phần 2) mission: impossible - the final reckoning tom cruise hayley atwell ving rhames simon pegg esai morales pom klementieff henry czerny holt mccallany janet mcteer nick offerman hannah waddingham tramell tillman shea whigham greg tarzan davis charles parnell mark gatiss rolf saxon lu mission: impossible - dead reckoning part two มิชชั่น:อิมพอสซิเบิ้ล ล่าพิกัดมรณะ ตอนที่สอง mission: impossible odplata - druhá část немогућа мисија: одмазда - други део mission: impossible odplata - druhá časť nhiệm vụ bất khả thi: nghiệp báo - phần 2 mission : impossible - dead reckoning partie 2 משימה בלתי אפשרית: נקמת מוות - חלק שני משימה בלתי אפשרית 8: חשבון סופי 碟中谍8：致命清算（下） mission: impossible 8 मिशन: इम्पॉसिबल - द फाइनल रेकनिंग ミッション：インポッシブル／デッドレコニング part two миссия невыполнима: финальная расплата misiune: imposibilă. răfuială finală mission impossible - the final reckoning mission impossible the final reckoning mission impossible, the final reckoning mission impossible 8 mission: impossible - bilan final mission impossible 8 - dead reckoning partie 2 碟中谍8 mission impossible 8 - the final reckoning mission : impossible – the final reckoning 職業特工隊 8 ：最終清算 mission ː impossible 8 - the final reckoning 职业特工队：最终清算 mision i pamundur: llogaria e fundit mission: impossible - the final reckoning', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-dang-quai-kiet-2', 'Băng Đảng Quái Kiệt 2', 'The Bad Guys 2', 'https://phimimg.com/upload/vod/20250820-1/50896df2de8b0c565bf4fedbc33b370a.jpg', 'https://phimimg.com/upload/vod/20250820-1/572c244ad49a26072c08a8602dd258c6.jpg', '<p>Biệt đội Bad Guys đang cố gắng lấy lại sự tin tưởng của mọi người sau khi hoàn lương, nhưng mọi nỗ lực sụp đổ khi họ bị kéo vào &quot;phi vụ cuối cùng&quot; do nhóm Bad Girls cầm đầu. Liệu họ sẽ giữ vững lý tưởng chính nghĩa, hay lại bị cuốn vào con đường tội phạm đã từng cố gắng rời bỏ?</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Sam Rockwell","avatar":""},{"name":"Marc Maron","avatar":""},{"name":"Craig Robinson","avatar":""},{"name":"Anthony Ramos","avatar":""},{"name":"Awkwafina","avatar":""},{"name":"Danielle Brooks","avatar":""},{"name":"Maria Bakalova","avatar":""},{"name":"Natasha Lyonne","avatar":""},{"name":"Zazie Beetz","avatar":""},{"name":"Richard Ayoade","avatar":""},{"name":"Alex Borstein","avatar":""},{"name":"Lilly Singh","avatar":""},{"name":"Omid Djalili","avatar":""},{"name":"Colin Jost","avatar":""},{"name":"Jaime Camil","avatar":""},{"name":"Jorge R. Gutierrez","avatar":""},{"name":"Joey Naber","avatar":""},{"name":"Monia Ayac","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Pan Wilk i spółka. Bad Guys 2","الأشرار 2","Băng Đảng Quái Kiệt 2","Troppo cattivi 2","Bad Guys 2 - De er super barske","Loši Momci 2","Pahalased 2","Os Caras Malvados 2","The Bad Guys 2"]', 1784690324149);
