INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bang-dang-quai-kiet-2', 'Băng Đảng Quái Kiệt 2', 'The Bad Guys 2', 'băng đảng quái kiệt 2 the bad guys 2 sam rockwell marc maron craig robinson anthony ramos awkwafina danielle brooks maria bakalova natasha lyonne zazie beetz richard ayoade alex borstein lilly singh omid djalili colin jost jaime camil jorge r. gutierrez joey naber monia ayac pan wilk i spółka. bad guys 2 الأشرار 2 băng đảng quái kiệt 2 troppo cattivi 2 bad guys 2 - de er super barske loši momci 2 pahalased 2 os caras malvados 2 the bad guys 2', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-khong-phai-nguoi-tot-quan-phi-luong-nhan', 'Chàng Không Phải Người Tốt (Quân Phi Lương Nhân)', 'Be Not Meant To Be', 'https://phimimg.com/upload/vod/20250806-1/00974cde5b6cf5a66ef35d78e436e7d9.jpg', 'https://phimimg.com/upload/vod/20250806-1/0071ed25637754228140a9d7f0b020b8.jpg', '<p>Vào thời Dân Quốc, Diệp Nam Chiêu bị chồng cũ phản bội và mất đi con gái ruột. Trên đường đi báo quan, cô bị bọn buôn người bắt cóc. Trong tình thế tuyệt vọng, cô buộc phải mạo danh thân phận của một phụ nữ đã chết để trở thành nhị phu nhân nhà họ Lục. Trớ trêu thay, người chồng cũ phản bội cô lại chính là tân cô gia của gia đình này, còn thân phận mà cô mạo danh thì để lại cho cô một đống rắc rối khó lường.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Mặc Chí","avatar":""},{"name":"Đại Cao Chính","avatar":""},{"name":"Trương Hinh Nguyệt","avatar":""},{"name":"Lưu Yến Kiều","avatar":""},{"name":"La Sở Phàm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["君非良人"]', 1784690324149);
