INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chang-khong-phai-nguoi-tot-quan-phi-luong-nhan', 'Chàng Không Phải Người Tốt (Quân Phi Lương Nhân)', 'Be Not Meant To Be', 'chàng không phải người tốt (quân phi lương nhân) be not meant to be lý mặc chí đại cao chính trương hinh nguyệt lưu yến kiều la sở phàm 君非良人', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-vu-nam-vung-in-da-house-3-in-korea', 'Mật Vụ Nằm Vùng (In Da House 3: In Korea)', 'Undercover Police', 'https://phimimg.com/upload/vod/20250820-1/1c2beebe87ae95f02aa2bbea9281fcd4.jpg', 'https://phimimg.com/upload/vod/20250820-1/496246a3a19b2ba43ab4f54878757d49.jpg', '<p>Năm thanh tra từng được gọi là “huyền thoại của lực lượng nằm vùng”. Nhưng sau vài phi vụ vượt quá giới hạn cùng mâu thuẫn nội bộ, đội tan rã, mỗi người rẽ sang một ngả đời riêng. Nhiều năm sau, tại đám cưới của một đồng đội, cả nhóm lần đầu tái ngộ trên đất Hàn. Chưa kịp tận hưởng niềm vui hội ngộ, họ bất ngờ bị cuốn vào một vụ bắt cóc chấn động. Bản năng nghề nghiệp bùng lên, năm con người ấy lại một lần nữa hành động. Những màn giả dạng liều lĩnh, thân phận bấp bênh khó lường! Từ công trường lao động tay chân cho tới sân khấu ban nhạc Trot, mỗi người bằng cách riêng của mình lần theo dấu vết sự thật. Nhưng lần này, trước mặt họ là một kẻ thù vượt xa mọi tưởng tượng. Phi vụ này – hoặc thành công, hoặc mất mạng. Liệu họ có thể viết tiếp huyền thoại của mình trên đất Hàn Quốc?</p>', 'Full', 1, 'single', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Sukhbold Ragchaabazar","avatar":""},{"name":"Lkhagvatseren Ganbayar","avatar":""},{"name":"Bayasaa Nyamdamba","avatar":""},{"name":"Batzorig Sukhbaatar","avatar":""},{"name":"Tsogtbayar Urantsogt","avatar":""},{"name":"Yoon Je-moon","avatar":""},{"name":"Ki Joo-bong","avatar":""},{"name":"Seo Eun-ji","avatar":""},{"name":"Manlaibaatar Khurelbaatar","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["In Da House 3: In Korea"]', 1784690324149);
