INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('elio-cau-be-den-tu-trai-dat', 'Elio: Cậu Bé Đến Từ Trái Đất', 'Elio', 'https://phimimg.com/upload/vod/20250820-1/022261b87b7de5ded98370a44d314998.jpg', 'https://phimimg.com/upload/vod/20250820-1/718b5ba60d0b5dec1852e00ce8822665.jpg', '<p>Gặp Elio, một cậu bé có khả năng dịch chuyển xuyên vũ trụ và bị nhận nhầm thành Đại sứ thiên hà của Trái đất. Phim có America Ferrera đảm nhận lồng tiếng cho nhân vật Olga Solis, Yonas Kibreab lồng tiếng cho Elio. Phim được đạo diễn bởi Adrian Molina và sản xuất bởi Mary Alice Drumm. Elio từ Disney và Pixar dự kiến khởi chiếu vào mùa xuân 2024.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Yonas Kibreab","avatar":""},{"name":"Zoe Saldaña","avatar":""},{"name":"Remy Edgerly","avatar":""},{"name":"Brandon Moon","avatar":""},{"name":"Brad Garrett","avatar":""},{"name":"Jameela Jamil","avatar":""},{"name":"Young Dylan","avatar":""},{"name":"Jake T. Getman","avatar":""},{"name":"Matthias Schweighöfer","avatar":""},{"name":"Ana de la Reguera","avatar":""},{"name":"Atsuko Okatsuka","avatar":""},{"name":"Shirley Henderson","avatar":""},{"name":"Naomi Watanabe","avatar":""},{"name":"Brendan Hunt","avatar":""},{"name":"Anissa Borrego","avatar":""},{"name":"Shelby Young","avatar":""},{"name":"Bob","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Disney and Pixar''s Elio","地球特派員"