INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-dua-giam-can-su-that-ve-the-biggest-loser', 'Cuộc Đua Giảm Cân: Sự Thật Về The Biggest Loser', 'Fit for TV: The Reality Of The Biggest Loser', 'https://phimimg.com/upload/vod/20250819-1/6ec875c9b0f741d7817809a731d16648.jpg', 'https://phimimg.com/upload/vod/20250819-1/d23f9aae8c223cc53241ac0b4709494d.jpg', '<p>Trong loạt phim tài liệu gây tranh cãi này, các thí sinh và nhà sản xuất từng tham gia tiết lộ sự thật khắc nghiệt và hậu quả nặng nề đằng sau thành công của &quot;The Biggest Loser&quot;.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Alison Sweeney","avatar":""},{"name":"Bob Harper","avatar":""},{"name":"Jillian Michaels","avatar":""},{"name":"Rob Huizenga","avatar":""},{"name":"J.D. Roth","avatar":""},{"name":"Caroline Rhea","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Fit for TV: The Reality of the Biggest Loser"]', 1784690324149);
