INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-dua-giam-can-su-that-ve-the-biggest-loser', 'Cuộc Đua Giảm Cân: Sự Thật Về The Biggest Loser', 'Fit for TV: The Reality Of The Biggest Loser', 'cuộc đua giảm cân: sự thật về the biggest loser fit for tv: the reality of the biggest loser alison sweeney bob harper jillian michaels rob huizenga j.d. roth caroline rhea fit for tv: the reality of the biggest loser', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-bi-che-giau', 'Tình Yêu Bị Che Giấu', 'Hidden Love', 'https://phimimg.com/upload/vod/20250819-1/8ecf94b7c4b395b295b7d26e82d3f9d9.jpg', 'https://phimimg.com/upload/vod/20250819-1/07468ec5ffee26fceef1de992ab04973.jpg', '<p>Vào những năm đầu thời Dân Quốc, nghệ nhân biểu diễn Thư Nhan bị kẻ xấu đánh ngất và bắt cóc. Khi tỉnh lại, cô bỗng chốc trở thành phu nhân của hội trưởng thương hội Nghiêm Kỳ Chiêu. Người chồng quyền thế, địa vị hiển hách, vàng bạc châu báu không thiếu, gia nhân ngoan ngoãn nghe lệnh — tất cả chứng cứ đều xác thực thân phận phu nhân thương hội của cô. Thế nhưng, Thư Nhan ngày càng cảm thấy mọi chuyện bí ẩn khó lường. Trong khi đó, sự quan tâm ân cần của Nghiêm Kỳ Chiêu lại khiến cô vô thức chìm đắm... Chỉ là chẳng bao lâu sau, cô phát hiện ra đây vốn là cái bẫy chí mạng mà Nghiêm Kỳ Chiêu đã sắp đặt từ lâu!</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wen Yuan","avatar":""},{"name":"Lu Menglin","avatar":""},{"name":"Shi Nan","avatar":""},{"name":"Guo Xiang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ni Ai","匿爱"]', 1784690324149);
