INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thiet-huyet-anh-hon', 'Thiết Huyết Anh Hồn', 'Iron-willed Souls', 'https://phimimg.com/upload/vod/20250819-1/e75bcb11e5ec1ea39ff0bd3bf8a9d40e.jpg', 'https://phimimg.com/upload/vod/20250819-1/779c6d39e70d8420f9730136691a1fd1.jpg', '<p>Bộ phim gồm 5 câu chuyện: “Tuyết táng”, “Quyết Trạch”, “Viên đạn cuối cùng”, “Lá cờ”, và “Tìm cha”. Nội dung làm nổi bật vị trí chiến lược quan trọng của tỉnh Cát Lâm – nơi trở thành cái nôi thành lập Đông Bắc Kháng Nhật Liên quân. Bộ phim ca ngợi tinh thần kháng chiến của các đảng viên Cộng sản Trung Quốc tiêu biểu như Dương Tĩnh Vũ cùng đông đảo cán bộ, chiến sĩ của Đông Bắc Kháng Nhật Liên quân, những người đã lấy máu và sinh mệnh của mình để hun đúc nên tinh thần kháng liệt của Đông Bắc trong cuộc kháng chiến vũ trang chống lại sự xâm lược của đế quốc Nhật Bản.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Xinghao","avatar":""},{"name":"Wang Peng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Tie Xie Ying Hun","铁血英魂"]', 1784690324149);
