INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-tuong-con-thu', 'Thần Tướng Con Thứ', 'Bastard Wargod', 'https://phimimg.com/upload/vod/20250804-1/73d6edb47352da8bf2798b140c6c8df7.jpg', 'https://phimimg.com/upload/vod/20250804-1/2bf24a35fc9ec7f8679c4b3e48a8b28c.jpg', '<p>Thần tướng Côn Lôn Sở Bắc Trì vì cứu chúng sinh mà rơi vào hôn mê, sau khi tỉnh lại liền che giấu thân phận, trở thành con trai thứ trong Sở phủ. Trên hành trình lật ngược tình thế chỉnh đốn gia phong, quét sạch cường đạo, Sở Bắc Trì không chỉ được trưởng công chúa, nữ đế, nữ phú thương, nữ tướng đem lòng yêu và tranh giành, anh còn phá giải được thế trận Càn Khôn, chém kẻ phản quốc, trấn áp vạn bang, cuối cùng khiến thiên hạ phải quy phục!</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Hoằng Hâm","avatar":""},{"name":"Hàn Hân Dư","avatar":""},{"name":"Trương Địch","avatar":""},{"name":"Từ Anh Lạc","avatar":""},{"name":"Tô Hàng","avatar":""},{"name":"Chu Thiên Tiêu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shu Zi Shen Jiang","庶子神将"]', 1784690324149);
