INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-vu-canh-buom', 'Đặc Vụ Cánh Bướm', 'Butterfly', 'https://phimimg.com/upload/vod/20250815-1/4b5ab78aff6908bd081e17a6fbca2e72.jpg', 'https://phimimg.com/upload/vod/20250815-1/e6d79892d8128d032acb48f12f859fa2.jpg', '<p>David Jung — cựu đặc vụ tình báo Mỹ, ẩn mình nhiều năm trên đất Hàn Quốc, sống lặng lẽ giữa bóng tối. Nhưng quá khứ không bao giờ ngủ yên. Một quyết định bất khả thi mà anh từng đưa ra đã quay trở lại, thổi tung cuộc sống hiện tại thành từng mảnh. Giờ đây, David trở thành con mồi của hai kẻ săn tàn nhẫn: Rebecca - sát thủ trẻ đẹp nhưng chết chóc, và Caddis - tổ chức gián điệp ngầm với những móng vuốt vươn khắp nơi.&nbsp;</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Daniel Dae Kim","avatar":""},{"name":"Reina Hardesty","avatar":""},{"name":"Piper Perabo","avatar":""},{"name":"Louis Landau","avatar":""},{"name":"Kim Tae-hee","avatar":""},{"name":"Sean Dulake","avatar":""},{"name":"Charles Parnell","avatar":""},{"name":"Kim Ji-hoon","avatar":""},{"name":"Park Hae-soo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["蝴蝶杀机","蝴蝶风暴","មេអំបៅ","ปีกสังหาร","Butterfly"]', 1784690324149);
