INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dac-vu-canh-buom', 'Đặc Vụ Cánh Bướm', 'Butterfly', 'đặc vụ cánh bướm butterfly daniel dae kim reina hardesty piper perabo louis landau kim tae-hee sean dulake charles parnell kim ji-hoon park hae-soo 蝴蝶杀机 蝴蝶风暴 មេអំបៅ ปีกสังหาร butterfly', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-hoa', 'Biển Hoa', 'Flower Sea', 'https://phimimg.com/upload/vod/20250808-1/7edc49ad772e555be5cfba208a51986b.jpg', 'https://phimimg.com/upload/vod/20250808-1/d09d22cd2042d7cd211b87b656abe5d0.jpg', '<p>Vào một buổi sáng nọ, Trần Tĩnh An và Chúc Niên Niên hoán đổi linh hồn với nhau. Trần Tĩnh An trở thành “cô công chúa nhà giàu”, còn Chúc Niên Niên lại thành “em gái” của người cô thầm thích. Nhưng khi cả hai cùng Trần Trường Ninh – người đã phát hiện ra sự thật – điều tra nguyên nhân vụ hoán đổi, thì ngày càng nhiều sự việc khiến tình hình trở nên rối rắm hơn, và mọi chuyện bắt đầu phát triển theo một hướng khó lường…</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Xu Quân","avatar":""},{"name":"Vương Nguyệt Đình","avatar":""},{"name":"Tào Ân Tề","avatar":""},{"name":"Triệu Bá Tùng","avatar":""},{"name":"Ân Thấm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["偶然交换的初恋","Hua Hai","花海"]', 1784690324150);
