INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieng-vong-cua-nguoi-song-sot-tham-an-tai-han-quoc', 'Tiếng Vọng Của Người Sống Sót: Thảm Án Tại Hàn Quốc', 'The Echoes Of Survivors: Inside Korea''s Tragedies', 'https://phimimg.com/upload/vod/20250817-1/b9854bd980287430bc9cdc2c2322ed15.jpg', 'https://phimimg.com/upload/vod/20250817-1/e977dbedbd739274d4bc680dc9a720c4.jpg', '<p>Từ các trại giam tàn bạo đến các giáo phái lợi dụng đức tin, những người sống sót đã phá vỡ sự im lặng để tiết lộ những thảm kịch đau lòng mà ít ai tin là có thể xảy ra ở Hàn Quốc.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["In the Name of God: A Holy Betrayal Chapter Two - The Echoes of Survivors: Inside Korea''s Tragedies","나는 생존자다"]', 1784690324150);
