INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tieng-vong-cua-nguoi-song-sot-tham-an-tai-han-quoc', 'Tiếng Vọng Của Người Sống Sót: Thảm Án Tại Hàn Quốc', 'The Echoes Of Survivors: Inside Korea''s Tragedies', 'tiếng vọng của người sống sót: thảm án tại hàn quốc the echoes of survivors: inside korea''s tragedies  in the name of god: a holy betrayal chapter two - the echoes of survivors: inside korea''s tragedies 나는 생존자다', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duc-tin', 'Đức Tin', 'Shaman', 'https://phimimg.com/upload/vod/20250817-1/64f7d2558d09d547629d29b041be3c6c.jpg', 'https://phimimg.com/upload/vod/20250817-1/4b3fa3a0ab1ff42256ac2cba5f370425.jpg', '<p>Giữa lòng một ngọn núi lửa hẻo lánh ở Ecuador, một nữ truyền giáo miệt mài cải đạo cho cộng đồng bản địa xa xôi. Nhưng khi con trai của cô bị ám bởi thế lực hắc ám cổ xưa — còn tồn tại lâu hơn cả tôn giáo mà cô đang rao giảng — đức tin của cô bị đẩy đến bờ vực sụp đổ. Để cứu con, cô buộc phải đối diện với một sự thật kinh hoàng: có những sức mạnh vượt ngoài mọi lời kinh cầu.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Ecuador', 0, '[{"name":"Sara Canning","avatar":""},{"name":"Daniel Gillies","avatar":""},{"name":"Jett Klyne","avatar":""},{"name":"Lisandro Morales","avatar":""},{"name":"Alejandro Fajardo","avatar":""},{"name":"Segundo Fuérez","avatar":""},{"name":"Dylan Tacuri","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Shaman: The Final Exorcism","Xamã: O Exorcista Pagão","Shaman"]', 1784690324150);
