INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('man-dem-luon-toi', 'Màn Đêm Luôn Tới', 'Night Always Comes', 'https://phimimg.com/upload/vod/20250815-1/3efcb84616175bac9f7a33b738f5dcd1.jpg', 'https://phimimg.com/upload/vod/20250815-1/6b7fa8329465aa7fd5a4cf49e4672504.jpg', '<p>Từng giờ trôi qua trong tuyệt vọng, giấc mơ sở hữu ngôi nhà lâu đời của gia đình tại Portland ngày càng xa vời, và màn đêm ngày càng u ám hơn khi cô phải truy tìm 25.000 đô la.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Vanessa Kirby","avatar":""},{"name":"Jennifer Jason Leigh","avatar":""},{"name":"Zack Gottsagen","avatar":""},{"name":"Stephan James","avatar":""},{"name":"Julia Fox","avatar":""},{"name":"Eli Roth","avatar":""},{"name":"Randall Park","avatar":""},{"name":"Michael Kelly","avatar":""},{"name":"J. Claude Deering","avatar":""},{"name":"Dana Millican","avatar":""},{"name":"Curtis McGann","avatar":""},{"name":"Jake McDorman","avatar":""},{"name":"Jennifer Lanier","avatar":""},{"name":"Jason Rouse","avatar":""},{"name":"Smack Louis","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ночь всегда наступает","Night Always Comes"]', 1784690324150);
