INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-lap', 'Cô Lập', 'Isolated', 'https://phimimg.com/upload/vod/20250815-1/25e9bab8542c8de76fb71e275b2d2917.jpg', 'https://phimimg.com/upload/vod/20250815-1/cb4a6292756226995a118c95805eae16.jpg', '<p>Sau khi nhận công việc chăm sóc một ông cụ kỳ lạ tại một ngôi nhà hẻo lánh, cô y tá nọ bắt đầu có những ảo giác đáng lo ngại và linh cảm kỳ lạ rằng trong nhà không chỉ có mình họ.</p>', 'Full', 1, 'single', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Yassi Pressman","avatar":""},{"name":"Joel Torre","avatar":""},{"name":"Candy Pangilinan","avatar":""},{"name":"Yayo Aguila","avatar":""},{"name":"Wilbert Ross","avatar":""},{"name":"Rafa Siguion-Reyna","avatar":""},{"name":"TJ Valderrama","avatar":""},{"name":"Denise Esteban","avatar":""},{"name":"Andrea Babierra","avatar":""},{"name":"Gwen Garci","avatar":""},{"name":"Keizer Prince","avatar":""},{"name":"Daena Lagdameo","avatar":""},{"name":"Ruslan Jacob Asumbrado","avatar":""},{"name":"Maru Delgado","avatar":""},{"name":"Liz Gonzales","avatar":""},{"name":"Zel Fernandez","avatar":""},{"name":"Zsa","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Isolated"]', 1784690324150);
