INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-gat', 'Mùa Gặt', 'Harvest', 'https://phimimg.com/upload/vod/20250815-1/b1ba8a8ac8eee31521f72e7366d28d0d.jpg', 'https://phimimg.com/upload/vod/20250815-1/a0599938ea710e2b51d7e2c93eee6b14.jpg', '<p>Trong bảy ngày mơ hồ như ảo giác, một ngôi làng vô danh một thời và nơi chốn không xác định dần biến mất. Walter Thirsk – một dân làng trở thành nông dân – và Charles Kent – vị lãnh chúa ngơ ngác của trang viên – là đôi bạn từ thuở nhỏ, nay cùng đối mặt với cuộc xâm lăng từ thế giới bên ngoài: cú sốc của thời hiện đại.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Caleb Landry Jones","avatar":""},{"name":"Harry Melling","avatar":""},{"name":"Rosy McEwen","avatar":""},{"name":"Arinzé Kene","avatar":""},{"name":"Thalissa Teixeira","avatar":""},{"name":"Frank Dillane","avatar":""},{"name":"Stephen McMillan","avatar":""},{"name":"Mitchell Robertson","avatar":""},{"name":"Grace Jabbari","avatar":""},{"name":"Gordon Brown","avatar":""},{"name":"Neil Leiper","avatar":""},{"name":"Emma Hindle","avatar":""},{"name":"Gary Maitland","avatar":""},{"name":"Noor Dillan-Night","avatar":""},{"name":"Antonia Quirke","avatar":""},{"name":"Logan Buchanan","avatar":""},{"name":"R","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Harvest"]', 1784690324150);
