INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuon-dia-dang-2025', 'Vườn Địa Đàng', 'Eden', 'https://phimimg.com/upload/vod/20250717-1/aa888a223ea8d31522acd5cbf0cf579a.jpg', 'https://phimimg.com/upload/vod/20250717-1/5abad920814f42f40e2df5f4033e755d.jpg', '<p>Vì khao khát thay đổi sâu sắc, một nhóm người đã rời bỏ xã hội để tự kiến tạo tương lai mới giữa vùng đất khắc nghiệt của quần đảo Galápagos.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jude Law","avatar":""},{"name":"Vanessa Kirby","avatar":""},{"name":"Ana de Armas","avatar":""},{"name":"Daniel Brühl","avatar":""},{"name":"Sydney Sweeney","avatar":""},{"name":"Felix Kammerer","avatar":""},{"name":"Toby Wallace","avatar":""},{"name":"Jonathan Tittel","avatar":""},{"name":"Ignacio Gasparini","avatar":""},{"name":"Richard Roxburgh","avatar":""},{"name":"Paul Gleeson","avatar":""},{"name":"Thiago Moraes","avatar":""},{"name":"Nicholas Denton","avatar":""},{"name":"Tim Ross","avatar":""},{"name":"Antonio Alvarez","avatar":""},{"name":"Benjamín Gorroño","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Origin of Species","Edenas","Eden","Рай земной","伊甸","สวรรค์คนบาป"]', 1784690324150);
