INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-ngu-cu-2025', 'Kẻ Ngụ Cư', 'The Occupant', 'https://phimimg.com/upload/vod/20250813-1/e04d4b0546b4a77ed0c3c9788cea2dbf.jpg', 'https://phimimg.com/upload/vod/20250813-1/8dd329225a4b3662007f59d99b7cf844.jpg', '<p>Vì tuyệt vọng muốn cứu em gái, Abby nhận một công việc nguy hiểm ở vùng hoang dã hẻo lánh của Georgia. Khi trực thăng gặp nạn và cô bị mắc kẹt giữa núi rừng, Abby tìm thấy tia hy vọng qua giọng nói của John – một người bí ẩn liên lạc qua radio từ gần đó. Khi anh hướng dẫn cô vượt qua điều kiện khắc nghiệt, Abby vừa chiến đấu để sinh tồn vừa dần mất đi sự tỉnh táo, cho đến khi phải đối mặt với một lựa chọn không thể ngờ tới.</p>', 'Full', 1, 'single', 'completed', 24, 2025, 'Vietsub', 'FHD', 'Georgia', 0, '[{"name":"Ella Balinska","avatar":""},{"name":"Rob Delaney","avatar":""},{"name":"Vanessa Ifediora","avatar":""},{"name":"Stuart Graham","avatar":""},{"name":"George Lasha","avatar":""},{"name":"Konstantine Roinishvili","avatar":""},{"name":"Armin Karima","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Occupant"]', 1784690324150);
