INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-trong-con-dich', 'Thị Trấn Trong Cơn Dịch', 'Eddington', 'https://phimimg.com/upload/vod/20250815-1/351c0a69600ba6b68caf4fdab73787f6.jpg', 'https://phimimg.com/upload/vod/20250815-1/d6f998d963f3ae4fd9f21e51706cb3c1.jpg', '<p>Giữa đại dịch COVID-19, thị trấn nhỏ Eddington, New Mexico chìm trong hỗn loạn khi cuộc tranh chấp giữa cảnh sát trưởng Joe Cross phản đối đeo khẩu trang và thị trưởng Ted Garcia ủng hộ xây trung tâm dữ liệu AI leo thang thành chiến tuyến chính trị, cuốn cả gia đình, cộng đồng vào vòng xoáy cực đoan, bạo lực và tan rã – phản chiếu một nước Mỹ chia rẽ</p>', 'Full', 1, 'single', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Joaquin Phoenix","avatar":""},{"name":"Pedro Pascal","avatar":""},{"name":"Luke Grimes","avatar":""},{"name":"Deirdre O''Connell","avatar":""},{"name":"Micheal Ward","avatar":""},{"name":"Austin Butler","avatar":""},{"name":"Emma Stone","avatar":""},{"name":"Cameron Mann","avatar":""},{"name":"Matt Gomez Hidaka","avatar":""},{"name":"Amélie Hoeferle","avatar":""},{"name":"Clifton Collins Jr.","avatar":""},{"name":"William Belleau","avatar":""},{"name":"Landall Goolsby","avatar":""},{"name":"Elise Falanga","avatar":""},{"name":"King Orba","avatar":""},{"name":"Rachel de la To","avatar":""}]', '[{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Еддінгтон","Eddington: Regresamos a 2020","Eddington"]', 1784690324150);
