INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thi-tran-trong-con-dich', 'Thị Trấn Trong Cơn Dịch', 'Eddington', 'thị trấn trong cơn dịch eddington joaquin phoenix pedro pascal luke grimes deirdre o''connell micheal ward austin butler emma stone cameron mann matt gomez hidaka amélie hoeferle clifton collins jr. william belleau landall goolsby elise falanga king orba rachel de la to еддінгтон eddington: regresamos a 2020 eddington', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kiem-sac-hoa-hong', 'Kiếm Sắc: Hoa Hồng', 'Sword Rose', 'https://phimimg.com/upload/vod/20250729-1/07e040ca9d9aebb91e7a6027822e9525.jpg', 'https://phimimg.com/upload/vod/20250729-1/f8ea3feae674f59b4898fc086ee00722.jpg', '<p>Trong một lần vô tình can thiệp vào một vụ việc khẩn cấp, Đặng Nghiên đã góp công giải cứu một cô gái bị bắt cóc. Tuy nhiên, hành động này lại vô tình làm gián đoạn kế hoạch truy bắt tội phạm mà Phòng Phòng, chống Mua bán người đã dày công chuẩn bị. Sau sự cố đó, cô bất ngờ được bổ nhiệm làm Trưởng phòng mới của đơn vị này. Quyết định bổ nhiệm khiến Thường Duệ – một cảnh sát từng nằm vùng trong các chuyên án chống ma túy – cảm thấy bất mãn. Trong mắt anh, Đặng Nghiên là một Trưởng phòng “nhảy dù”, thiếu kinh nghiệm thực chiến. Thế nhưng, sau khi nhậm chức, Đặng Nghiên đã nhanh chóng khẳng định năng lực chuyên môn, tham gia tích cực vào công tác điều tra phá án và đóng vai trò chủ chốt trong nhiều vụ việc phức tạp. Nhờ vậy, cô dần giành được sự tin tưởng từ các đồng nghiệp và từng bước thay đổi hoàn toàn cách nhìn của Thường Duệ qua quá trình hợp tác. Về phía Thường Duệ, trong quá trình điều tra, anh nhiều lần bị giằng xé giữa tình cảm cá nhân và trách nhiệm nghề nghiệp, khiến bản thân rơi vào bế tắc. Tuy nhiên, nhờ sự động viên từ những người xung quanh, anh dần thức tỉnh và nhận ra trọng trách thiêng liêng của một chiến sĩ chống buôn người, từ đó quyết tâm tiếp tục cống hiến cho sứ mệnh cao cả này. Riêng Đặng Nghiên, cô luôn mang trong mình ngọn lửa căm phẫn với tội ác buôn người – một cảm xúc xuất phát từ nỗi đau khi người bạn thân thuở nhỏ mất tích. Chính điều đó đã thôi thúc cô không ngừng đào sâu điều tra, ứng dụng các công nghệ hiện đại để phá giải hàng loạt vụ án tồn đọng. Khi từng vụ án lần lượt được làm sáng tỏ, một mạng lưới buôn người khổng lồ dần lộ diện. Trong mỗi chiến dịch, Đặng Nghiên ngày càng thấm thía hơn trách nhiệm nặng nề mà cô đang gánh vác. Đối mặt với tình hình phức tạp và những biến cố bất ngờ, dù bản thân rơi vào nguy hiểm, thậm chí có nguy cơ bị hãm hại, cô vẫn kiên trì theo đuổi sự thật đến cùng. Sau khi được minh oan, Đặng Nghiên đã dẫn dắt cả đội bước vào cuộc đối đầu quyết liệt với thế lực ngầm đứng sau những đường dây buôn người.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Địch Lệ Nhiệt Ba","avatar":""},{"name":"Kim Thế Giai","avatar":""},{"name":"Vưu Dũng Trí","avatar":""},{"name":"Lý Trí","avatar":""},{"name":"Vương Nghệ Triết","avatar":""},{"name":"Cao Cơ Tài","avatar":""},{"name":"Hạ Tinh","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["利劍玫瑰","Li Jian Mei Gui","利剑·玫瑰"]', 1784690324150);
