INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-an-cua-luong-tam-ke-bi-nguyen-rua', 'Bản Án Của Lương Tâm (Kẻ Bị Nguyền Rủa)', 'The Damned', 'https://phimimg.com/upload/vod/20250526-1/18b53247a7ebb57f9cc18c3ece9cc731.jpg', 'https://phimimg.com/upload/vod/20250526-1/22a9990fd0b43a0df82d6798d1e1c502.jpg', '<p>Vào thế kỷ 19, một người phụ nữ góa chồng phải đối mặt với một lựa chọn không thể khi, giữa mùa đông khắc nghiệt, một con tàu bị đắm ngoài khơi ngôi làng chài nghèo đói của cô ở Iceland. Bất kỳ nỗ lực nào để cứu những người sống sót đều có nguy cơ làm cạn kiệt nguồn lương thực ít ỏi mà dân làng đang cố gắng cầm cự để sống sót qua mùa đông.</p>', 'Full', 1, 'single', 'completed', 13, 2025, 'Vietsub', 'FHD', 'Ireland', 0, '[{"name":"Odessa Young","avatar":""},{"name":"Joe Cole","avatar":""},{"name":"Siobhan Finneran","avatar":""},{"name":"Rory McCann","avatar":""},{"name":"Turlough Convery","avatar":""},{"name":"Lewis Gribben","avatar":""},{"name":"Francis Magee","avatar":""},{"name":"Mícheál Óg Lane","avatar":""},{"name":"Andrean Sigurgeirsson","avatar":""},{"name":"Arnar Gray","avatar":""},{"name":"Guillermo Uria","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["ארור","더 댐드","המקוללים","The Damned"]', 1784690324150);
