INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dinh-phong-ba', 'Định Phong Ba', 'The Wanted Detective', 'https://phimimg.com/upload/vod/20250801-1/3beeeb6837ba8ff55a97d4dde5cb813a.jpg', 'https://phimimg.com/upload/vod/20250801-1/3a2492bca0dc47297b037024fbaccc3a.jpg', '<p>Phim kể về Tiểu Bắc Minh, thần thám số một Đại Tề bị gài bẫy mang tội danh giết thầy, phản quốc nên phải bỏ trốn. Ba năm sau, cậu trở lại kinh thành, cùng sư muội Chung Tuyết Mạn và nhóm đồng đội mưu trí, dũng cảm liên tiếp phá giải hàng loạt kỳ án. Trong hành trình ấy, họ dần vén màn bí ẩn về Dạ Sát, dẹp yên sóng gió ở Đại Tề, bảo vệ bình yên cho trăm họ.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 9, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Tinh Việt","avatar":""},{"name":"Hướng Hàn Chi","avatar":""},{"name":"Trần Hựu Vĩ","avatar":""},{"name":"Trương Nam","avatar":""},{"name":"Hạ Lạc Lạc","avatar":""},{"name":"Đặng Khải","avatar":""},{"name":"Hứa Giai Kỳ","avatar":""},{"name":"Bảo Kiếm Phong","avatar":""},{"name":"Tôn Giai Ninh","avatar":""},{"name":"Lý Hạo Phi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["定风波","The Wanted Detective","คลื่นลมปมปริศนา","Calming Waves"]', 1784690324150);
