INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('washington-black', 'Washington Black', 'Washington Black', 'https://phimimg.com/upload/vod/20250727-1/f9bc6a6878280dd33ccf0d254773a128.jpg', 'https://phimimg.com/upload/vod/20250727-1/290a453c35e16141f19bbaf7d3404207.jpg', '<p>Cậu bé George Washington &quot;Wash&quot; Black, 11 tuổi, bắt đầu chuyến hành trình vòng quanh thế giới để tìm kiếm danh tính bản thân, sau khi trốn thoát khỏi đồn điền mía ở Barbados bằng một cỗ máy bay kỳ lạ cùng người anh trai lập dị của chủ nô — một nhà phát minh.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ernest Kingsley Jr.","avatar":""},{"name":"Sterling K. Brown","avatar":""},{"name":"Iola Evans","avatar":""},{"name":"Edward Bluemel","avatar":""},{"name":"Sharon Duncan-Brewster","avatar":""},{"name":"Eddie Karanja","avatar":""},{"name":"Tom Ellis","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Washington Black"]', 1784690324150);
