INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ga-tu-than-2025', 'Ga Tử Thần', 'Ghost Train', 'https://phimimg.com/upload/vod/20250813-1/91642ac68854efc43ef37ec70a2cbd44.jpg', 'https://phimimg.com/upload/vod/20250813-1/ac93509330da4b880a96d81130914b5d.jpg', '<p>Bước vào thế giới của Ghost Train, khán giả theo chân Da Gyeong (Joo Hyun Young) – một YouTuber trẻ tuổi đang tuyệt vọng cứu vãn tài khoản đang &quot;flop&quot; của mình bằng những câu chuyện kỳ bí. Với khát khao phá kỷ lục lượt xem, cô quyết định khám phá ga tàu điện ngầm Gwanglim – nơi phủ đầy truyền thuyết đô thị và nổi tiếng với hàng loạt vụ mất tích bí ẩn. Được dẫn lối bởi người gác ga kỳ lạ (Jeon Bae Soo), Da Gyeong không ngờ rằng chuyến đi liều lĩnh này lại đẩy cô vào vòng xoáy tâm linh rùng rợn, nơi mà chỉ khi chạm đến “đích cuối” của chuyến tàu định mệnh, cô mới mong tìm được lối thoát.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"Joo Hyun-young","avatar":""},{"name":"Jeon Bae-soo","avatar":""},{"name":"Choi Bo-min","avatar":""},{"name":"Kim Ji-in","avatar":""},{"name":"Kim Woo-kyum","avatar":""},{"name":"Jung Han-bit","avatar":""},{"name":"Han Dong-hee","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Tren Fantasma: Estación Maldita","La Estación del Terror","Ghost Train","Tren Fantasma","Trem Fantasma","괴기열차"]', 1784690324150);
