INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-thu-thu-chuong-ke-tiep', 'Người Thủ Thư: Chương Kế Tiếp', 'The Librarians: The Next Chapter', 'https://phimimg.com/upload/vod/20250628-1/8f7a916115daaa63a30ecc022fce33ff.jpg', 'https://phimimg.com/upload/vod/20250628-1/32d45956c04f26923ce2952f641432d8.jpg', '<p>Một Thủ thư cổ đại bất ngờ du hành đến thời hiện đại và bị kẹt lại nơi đây. Trở về lâu đài xưa — nay chỉ còn là một viện bảo tàng lạnh lẽo — anh vô tình đánh thức một nguồn ma thuật cổ xưa, khiến phép thuật lan tràn khắp châu lục. Để khắc phục hậu quả, anh buộc phải hợp tác cùng một nhóm người mới — những gương mặt trẻ trung, tài năng nhưng đầy khác biệt. Và thế là, một thế hệ Thủ thư hoàn toàn mới được khai sinh, bắt đầu hành trình phiêu lưu kỳ ảo giữa thế giới hiện đại và huyền bí.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Callum McGowan","avatar":""},{"name":"Jessica Green","avatar":""},{"name":"Olivia Morris","avatar":""},{"name":"Bluey Robinson","avatar":""},{"name":"Caroline Loncq","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["图书馆员：下一章","The Librarians: The Next Chapter"]', 1784690324150);
