INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xuan-muon', 'Xuân Muộn', 'Spring Rewritten', 'https://phimimg.com/upload/vod/20250801-1/41d711d0a7e50a458a6a2715077daf7b.jpg', 'https://phimimg.com/upload/vod/20250801-1/4f9223748b801646dc37bf1b6276842c.jpg', '<p>Tiểu thư Triệu Xuân Mạn của thương hội trà trộn vào rạp hát Ngọc Xuân để trả thù cho cha, nhưng không may lại chết dưới tay của Chu Trì, nhị đương gia của Nghĩa Bang. Khi thời gian được quay trở về, Triệu Xuân Mạn phát hiện mọi chuyện dường như đã thay đổi. Để làm sáng tỏ chân tướng cái chết của cha và thay đổi kết cục của mình, Xuân Mạn không ngừng đối mặt với những lựa chọn của vận mệnh, từng bước cẩn trọng, cũng dần đoạt lấy tình cảm của Chu Trì.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Biên Thiên Dương","avatar":""},{"name":"Thiệu Vũ Thất","avatar":""},{"name":"Trần Bằng Vạn Lý","avatar":""},{"name":"Cảnh Nghệ Triển","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chun Chi","有风栖悟","Be Addicted to Love","Late Spring","Hestating Spring","春迟"]', 1784690324150);
