INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ket-hon-voi-nguoi-ma-toi-ghet-nhat', 'Kết Hôn Với Người Mà Tôi Ghét Nhất', 'I''m Getting Married To A Girl I Hate In My Class', 'https://phimimg.com/upload/vod/20250111-1/d5789874b99d2a0942ce21791360a7f0.jpg', 'https://phimimg.com/upload/vod/20250111-1/f68d40c762ea37ee50f1b29470edccd8.jpg', '<p>Dù là đối thủ &quot;không đội trời chung&quot; trong lớp, cặp đôi học sinh trung học Saito và Akane bất ngờ bị hai bên gia đình ép phải kết hôn với nhau. Cuộc sống mới mẻ và đầy thử thách với những tình huống dở khóc dở cười của đôi trẻ bắt đầu khi họ phải sống chung dưới một mái nhà. Tuy không thể hòa hợp nhưng cả hai đã tạo ra vô vàn khoảnh khắc hài hước, cảm động và tạo dựng cho nhau những bài học về tình yêu cũng như sự thấu hiểu trong đời sống hôn nhân.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 9, 2025, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Shogo Sakata","avatar":""},{"name":"Hinaki Yano","avatar":""},{"name":"Sayumi Suzushiro","avatar":""},{"name":"Nene Hieda","avatar":""},{"name":"Kaori Maeda","avatar":""},{"name":"Hochu Otsuka","avatar":""},{"name":"Fumi Hirano","avatar":""},{"name":"Asaki Yuikawa","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["和班上最讨厌的女生结婚了。","我决定和班上最讨厌的女生结婚了。","Je vais me marier avec une fille que je déteste dans ma classe","Class no Dai Kirai na Joshi to Kekkon suru Koto ni Natta.","Kurasu no Daikirai na Joshi to Kekkon Suru Koto ni Natta.","KuraKon","クラ婚","クラスのだいきらいなじょしとけっこんすることになった","Kurasu no Dai Kirai na Joshi to Kekkon suru Koto ni Natta.","Class no Daikirai na Joshi to Kekkon suru Koto ni Natta.","CLA-KON","CLAKON","I Ended Up Marrying the Girl in My Class I Hated the Most","I Got Married to the Girl I Hate Most in Class","I''m Getting Married to a Girl I Hate in My Class","クラスの大嫌いな女子と結婚することになった。"]', 1784690324150);
