INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-tu-biet-cuoi-cung', 'Lời Từ Biệt Cuối Cùng', 'The Last Goodbye', 'https://phimimg.com/upload/vod/20250813-1/4ee5430fad664e38d952abd60abaf73d.jpg', 'https://phimimg.com/upload/vod/20250813-1/eea74c196598076a066801dd2a7eeaf2.jpg', '<p>Lấy bối cảnh đầu những năm 2000, hai thiếu niên từ những gia đình tan vỡ tìm thấy niềm an ủi nơi nhau, nhưng rồi một biến cố thay đổi cuộc đời thử thách sợi dây gắn kết giữa họ.</p>', 'Full', 1, 'single', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Daniela Stranner","avatar":""},{"name":"Matt Lozano","avatar":""},{"name":"Esnyr","avatar":""},{"name":"Karina Bautista","avatar":""},{"name":"Troy Regis","avatar":""},{"name":"Arlene Muhlach","avatar":""},{"name":"Bodjie Pascua","avatar":""},{"name":"Lui Villaruz","avatar":""},{"name":"Joe D'' Mango","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Last Goodbye"]', 1784690324150);
