INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-vu-kim-cuong-the-ky', 'Phi Vụ Kim Cương Thế Kỷ', 'Stolen: Heist Of The Century', 'https://phimimg.com/upload/vod/20250813-1/11fa7cdb120bf12fdbd275dd6d7d3dce.jpg', 'https://phimimg.com/upload/vod/20250813-1/46b414db8e1a12bdc85f48759f4b9459.jpg', '<p>Antwerp, năm 2003. Một băng trộm ra tay cướp Trung tâm Kim cương bất khả xâm phạm. Ai đứng sau một trong những vụ trộm lớn nhất thế giới và làm sao chúng có thể thực hiện trót lọt?</p>', 'Full', 1, 'single', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["不翼而飞：世纪大劫案","Stolen: Heist of the Century"]', 1784690324150);
