INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phi-vu-kim-cuong-the-ky', 'Phi Vụ Kim Cương Thế Kỷ', 'Stolen: Heist Of The Century', 'phi vụ kim cương thế kỷ stolen: heist of the century  不翼而飞：世纪大劫案 stolen: heist of the century', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('halabala-rung-ma-te-xac', 'Halabala: Rừng Ma Tế Xác', 'Halabala (Survival Cut)', 'https://phimimg.com/upload/vod/20250813-1/a6d8846f1466a45654dea239b4897494.jpg', 'https://phimimg.com/upload/vod/20250813-1/d4338f3a48a12ac9ed9cbea0ab13f1c9.jpg', '<p>&quot;Thanh tra Dan – kẻ mang biệt danh rùng rợn “Dan Trăm Xác” – là một cảnh sát liều mạng, nổi tiếng với quá khứ đẫm máu và những phi vụ bất chấp luật lệ. Sau một sai lầm kinh hoàng trong lúc thực hiện nhiệm vụ, Dan bị giáng chức và chuyển công tác về vùng hẻo lánh. Với nổ lực để có cơ hội trở lại Bangkok – anh cần bắt được Tup Ta Fai: tên trùm tội phạm loạn trí vừa trốn khỏi ngục, hiện đang ẩn náu trong khu rừng cấm Halabala. Thế nhưng, Halabala không phải một khu rừng bình thường. Nơi đây bị nguyền rủa bởi truyền thuyết quỷ Bataya và Batow – tộc người ăn thịt từng sống trong rừng sâu và đang nuôi dưỡng con quỷ Bataya bằng hận thù và xác người. Trong cuộc truy đuổi đẫm máu giữa rừng thiêng, Dan không chỉ phải đối đầu với Ta Fai, mà còn bị ám ảnh bởi những tiếng gọi ma quái, những ám ảnh dị dạng và nỗi sợ sâu kín nhất của chính anh.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Chantavit Dhanasevi","avatar":""},{"name":"Nuttanicha Dungwattanawanich","avatar":""},{"name":"Anon Saisangcharn","avatar":""},{"name":"Yasaka Chaisorn","avatar":""},{"name":"Sirat Intarachote","avatar":""},{"name":"Piphatkorn Kedkaew","avatar":""},{"name":"Thanatphong Charurangsimes","avatar":""},{"name":"Pakapol Srirongmuang","avatar":""},{"name":"Peerawat Sareewong","avatar":""},{"name":"Kwanchai Yenpayap","avatar":""},{"name":"Pongpat Pathumsuwan","avatar":""},{"name":"Carl Anan Langenski","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Hala Bala","ฮาลาบาลา ป่าจิตหลุด"]', 1784690324150);
