INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghich-tap-nghich-ai', 'Nghịch Tập (Nghịch Ái)', 'Revenged Love', 'https://phimimg.com/upload/vod/20250630-1/4de465401cf6311592137e78806870b2.jpg', 'https://phimimg.com/upload/vod/20250630-1/3d08edf95b181fc2a88070d6107f442f.jpg', '<p>Phim được chuyển thể từ tiểu thuyết của nữ nhà văn Sài Kê Đản và được chính mẹ đẻ đầu tư sản xuất. Phim do cặp đôi Vương Thanh và Phùng Kiến Vũ đóng chính kể về Ngô Sở Úy một thanh niên khờ khạo bị bạn gái đá nên quyết tâm trả thù bằng cách tán tỉnh bạn trai mới của ả ta là tên thiếu gia ăn chơi Trì Sính.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tử Du","avatar":""},{"name":"Điền Túc Ninh","avatar":""},{"name":"Triển Hiên","avatar":""},{"name":"Lưu Hiên Thừa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["逆袭之爱上情敌","逆袭","Отомщённая любовь","逆襲","Counter Attack","Falling in Love With a Rival","Counterattack","逆爱"]', 1784690324150);
