INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hen-gap-cau-ngay-mai-o-khu-am-thuc-fudo-koto-de-mata-ashita', 'Hẹn Gặp Cậu Ngày Mai Ở Khu Ẩm Thực (Fudo Koto de, Mata Ashita)', 'See You Tomorrow At The Food Court', 'https://phimimg.com/upload/vod/20250810-1/5515b8c3169bdc0ce94094f69acf5737.jpg', 'https://phimimg.com/upload/vod/20250810-1/828d25a63bcbb3427980f60417351db0.jpg', '<p>Wada, một cô gái toát ra vẻ khó gần, và Yamamoto, người khiến những người xung quanh e dè vì vẻ ngoài đáng sợ. Dù học ở hai trường cấp ba khác nhau, nhưng họ gần như ngày nào cũng gặp nhau tại khu ẩm thực của một trung tâm mua sắm. Hãy cùng nhìn thoáng qua những buổi chiều thư thả của Wada và Yamamoto, khi họ cùng nhau chia sẻ và suy ngẫm về những thăng trầm trong cuộc sống học đường.</p>', 'Tập 6', 12, 'hoathinh', 'ongoing', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hiyori Miyazaki","avatar":""},{"name":"Yoshino Aoyama","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["美食广场里的女高中生们在说啥","美食广场明天见","明天，美食广场见。","Food Court de, Mata Ashita.","フドあす","Fūdo Kōto de, Mata Ashita.","See You Tomorrow, at the Food Court.","Food Court de Mata Ashita","フードコートで、また明日。"]', 1784690324150);
