INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-than-de-nhi-bo-chien-hoa-tay-ky', 'Phong Thần Đệ Nhị Bộ: Chiến Hoả Tây Kỳ', 'Creation Of The Gods II: Demon Force', 'https://phimimg.com/upload/vod/20250806-1/67d0cf7741fb9ca2657012083cf95bac.jpg', 'https://phimimg.com/upload/vod/20250806-1/b295605ac8cfdd012f503ba135bae6c7.jpg', '<p>Tiếp nối phần 1, phim kể về cuộc chiến ác liệt giữa Tây Kỳ do Cơ Phát lãnh đạo và triều Thương của Trụ Vương nhằm giành Bảng Phong Thần. Trong khi Vãn Trung dẫn đại quân và bày “Thập tuyệt trận” tấn công, Đặng Thiên Nữ dần cảm động trước tinh thần của dân Tây Kỳ và hy sinh để phá trận. Trận chiến kết thúc với thất bại của triều Thương, nhưng âm mưu của Đát Kỷ và sự biến đổi của Tử Giáp mở ra xung đột mới cho phần tiếp theo.</p>', 'Full', 1, 'single', 'completed', 17, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 1, '[{"name":"Ô Nhĩ Thiện","avatar":""},{"name":"Hoàng Bột","avatar":""},{"name":"Vu Thích","avatar":""},{"name":"Nha Nhi","avatar":""},{"name":"Phạm Tuấn","avatar":""},{"name":"Phí Tường","avatar":""},{"name":"Lý Tuyết Kiện","avatar":""},{"name":"Trần Mục Trì","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["封神第二部","Criação dos Deuses 2: Confronto Demoníaco","封神：魔道争锋","Creation of the Gods II: Demon Force","Creation of the Gods II: Demonic Confrontation","Criação dos Deuses 2","Investidura dos Deuses Parte 2","封神第二部：戰火西岐","Feng Shen 2: Zhan huo xi qi","Feng shen di er bu: zhan huo xi qi","Творение богов: Битва с