INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-san-quy-ba', 'Thợ Săn Quý Bà', 'The Hunting Wives', 'https://phimimg.com/upload/vod/20250727-1/aabacccc9e6f0b70a41171eb9fe4b712.jpg', 'https://phimimg.com/upload/vod/20250727-1/be683343836da100d2fcc4f41b703590.jpg', '<p>Từ bỏ ánh đèn thành phố, Sophie chuyển đến miền Đông Texas yên ả để bắt đầu cuộc sống mới. Tại đây, cô nhanh chóng bị cuốn vào thế giới hào nhoáng của một nữ xã hội thượng lưu và nhóm bạn nội trợ xinh đẹp, sang trọng. Nhưng đằng sau vẻ ngoài hoàn hảo ấy là những bí mật đen tối đến chết người.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Brittany Snow","avatar":""},{"name":"Malin Åkerman","avatar":""},{"name":"Jaime Ray Newman","avatar":""},{"name":"Katie Lowes","avatar":""},{"name":"Chrissy Metz","avatar":""},{"name":"George Ferrier","avatar":""},{"name":"Evan Jonigkeit","avatar":""},{"name":"Dermot Mulroney","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["猎艳娇妻","猎艳的娇妻","猎艳的娇妻们","狩猎的妻子们","捕猎者","猎妻","狩猎之妻","狩猎娇妻","Жены на охоте","Жены-охотницы","The Hunting Wives"]', 1784690324150);
