INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-em-den-su-xuat-hien-cua-cau', 'Khi Em Đến (Sự Xuất Hiện Của Cậu)', 'Fell Upon Me', 'https://phimimg.com/upload/vod/20250808-1/7f697869dba41207adeefd75f1fbb45e.jpg', 'https://phimimg.com/upload/vod/20250808-1/36c383abb2167c62b25368727d43f24a.jpg', '<p>An Chân Chân, nữ sinh 17 tuổi sống ở năm 2011, bất ngờ nhận được một cuộc gọi kỳ lạ đến từ năm 2024, nói rằng 12 năm sau cô sẽ t.ự s.á.t và rơi vào hôn mê. Ban đầu cô tưởng chỉ là trò đùa, nhưng dần dần những “lời tiên tri” trong điện thoại liên tục trở thành sự thật. Đầu dây bên kia là Giang Lăng — đại ca học đường cùng trường với An Chân Chân. Cậu nhờ cô quay về tìm chính bản thân mình của năm đó, cùng nhau giải mã những điều kỳ lạ đang xảy ra, thay đổi tương lai và viết lại số phận của chính mình. Tương lai, thế giới song song, đã bắt đầu thay đổi. Câu chuyện do thời gian xoay chuyển cũng sắp được viết lại.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hoàng Tuấn Tiệp","avatar":""},{"name":"Doãn Nhụy","avatar":""},{"name":"Đông Hạo","avatar":""},{"name":"Hoàng Hân Việt","avatar":""},{"name":"Vương Dực","avatar":""},{"name":"Hồ Tử Hiên","avatar":""},{"name":"Diêu Y Thiêm","avatar":""},{"name":"Hà Chí Long","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ni De Jiang Lin","拯救我的世界末日","Help Me Please","你的降临"]', 1784690324150);
