INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khi-em-den-su-xuat-hien-cua-cau', 'Khi Em Đến (Sự Xuất Hiện Của Cậu)', 'Fell Upon Me', 'khi em đến (sự xuất hiện của cậu) fell upon me hoàng tuấn tiệp doãn nhụy đông hạo hoàng hân việt vương dực hồ tử hiên diêu y thiêm hà chí long ni de jiang lin 拯救我的世界末日 help me please 你的降临', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lat-nguoc-21-gam', 'Lật Ngược 21 Gam', 'Reverse 21 Grams', 'https://phimimg.com/upload/vod/20250811-1/c00c963a0f5a88ab7f6779124d8eadcf.jpg', 'https://phimimg.com/upload/vod/20250811-1/ca0549e1fc1a3502670fa4c2830089ff.jpg', '<p>Điều tra viên của Sở An Ninh là Tống Tinh Dã bị nữ cảnh sát xinh đẹp Thượng Vi ngăn cản khi đang điều tra một vụ án mạng ở khu phố cổ. Anh bất ngờ phát hiện đồng đội cũ của mình là Hoàng Hải đang bị truy sát. Để tìm ra sự thật, Tống Tinh Dã cùng trợ lý Chiêm Na đã phá giải các dữ liệu, đồng thời phối hợp với Thượng Vi để tiến hành một cuộc đột kích bất ngờ, cuối cùng đã vạch trần được âm mưu đen tối và đập tan một cuộc đảo chính. Nhờ sự trợ giúp âm thầm của tiểu thư nhà giàu Triệu Tình Vân, anh đã thành công đưa sự thật ra ánh sáng.</p>', 'Hoàn Tất (19/19)', 19, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Kinh Mộc","avatar":""},{"name":"Mai Bảo Lai","avatar":""},{"name":"Trần Bằng Vạn Lý","avatar":""},{"name":"Lưu Chỉ Vi","avatar":""},{"name":"Tào Uyển Cẩn","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Fan Zhuan 21 Ke","反转21克"]', 1784690324150);
