INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('shoshimin-cach-de-tro-nen-binh-thuong-phan-2-tieu-thi-dan', 'SHOSHIMIN: Cách Để Trở Nên Bình Thường (Phần 2) (Tiểu Thị Dân)', 'How To Become Ordinary (Season 2)', 'https://phimimg.com/upload/vod/20250811-1/4bb18b3ddcab5dc3309a075a17ae1957.jpg', 'https://phimimg.com/upload/vod/20250811-1/28e8543c8561d7ecb5bb685de2369a0a.jpg', '<p>Kobato quyết định trở thành một công dân trung thực, khiêm tốn sau khi trải qua một trải nghiệm cay đắng được gọi là &quot;công việc trí tuệ&quot;. Anh lập giao ước với Osanai, bạn cùng lớp có cùng mục tiêu, và họ dự định vào trường trung học để sống cuộc sống bình lặng. Nhưng vì một lý do nào đó, những sự kiện và thảm họa không thể giải thích được cứ liên tục xảy ra xung quanh họ. Liệu Kobato và Osanai có bao giờ có thể sống cuộc sống bình thường, yên bình không?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shuichiro Umeda","avatar":""},{"name":"Hina Youmiya","avatar":""},{"name":"Makoto Furukawa","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shōshimin Shirīzu","소시민 시리즈 2기","Как стать обычным","โชชิมิง ซีรีส์","Shoshimin: How to Become Ordinary","Shoushimin Series","Shōshimin Series","The Petit Bourgeois Series","How to Become Ordinary","小市民シリーズ"]', 1784690324150);
