INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-nguoi-bao-ho-wakanda', 'Những Người Bảo Hộ Wakanda', 'Eyes Of Wakanda', 'https://phimimg.com/upload/vod/20250811-1/26378f0bb3dde40b08da8261450eec47.jpg', 'https://phimimg.com/upload/vod/20250811-1/892c15a08af2c54c4e4eefeb09002057.jpg', '<p>Theo chân những chiến binh Wakanda dũng cảm xuyên suốt chiều dài lịch sử trong hành trình vòng quanh thế giới, khi họ thực hiện những nhiệm vụ nguy hiểm nhằm thu hồi các cổ vật Vibranium từ tay kẻ thù của Wakanda. Họ chính là Hatut Zaraze — và đây là câu chuyện của họ.</p>', 'Hoàn Tất (4/4)', 4, 'hoathinh', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Глаза Ваканды","Marvel Animation''s Eyes of Wakanda","Eyes of Wakanda"]', 1784690324150);
