INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhung-nguoi-bao-ho-wakanda', 'Những Người Bảo Hộ Wakanda', 'Eyes Of Wakanda', 'những người bảo hộ wakanda eyes of wakanda  глаза ваканды marvel animation''s eyes of wakanda eyes of wakanda', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-may-kien-tao-wataru', 'Người Máy Kiến Tạo Wataru', 'Mashin Creator Wataru', 'https://phimimg.com/upload/vod/20250421-1/c6d5c3544f83b5b105479b502e3d48a1.jpg', 'https://phimimg.com/upload/vod/20250421-1/4f5a01ebf763bd8e9b0f003d4da668c2.jpg', '<p>Mashin Souzouden Wataru là một series anime Nhật Bản nổi tiếng, kể về câu chuyện của một cậu bé tên là Wataru, người được triệu hồi từ thế giới hiện thực đến thế giới Maou để chiến đấu chống lại các thế lực độc ác. Trên hành trình phiêu lưu của mình, Wataru gặp được nhiều người bạn đồng hành và chiến đấu bằng các robot Mashin để bảo vệ thế giới khỏi sự hủy diệt. Phim Mashin Souzouden Wataru thường kết hợp giữa yếu tố hành động, phiêu lưu và tình bạn, mang đến cho khán giả những trải nghiệm đầy kịch tính và cảm động. Đồng thời, phim cũng nhấn mạnh giá trị của sự đoàn kết và tinh thần chiến đấu chống lại ác quỷ, tạo nên một câu chuyện có sức hấp dẫn đặc biệt đối với khán giả trẻ.</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Mutsumi Tamura","avatar":""},{"name":"Tomokazu Sugita","avatar":""},{"name":"Atsumi Tanezaki","avatar":""},{"name":"Katsuyuki Konishi","avatar":""},{"name":"Megu Umezawa","avatar":""},{"name":"Rie Kugimiya","avatar":""},{"name":"Aoi Ichikawa","avatar":""},{"name":"Shunichi Toki","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}