INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giong-hat-moi-chau-a', 'Giọng Hát Mới Châu Á', 'Sing! Asia', 'https://phimimg.com/upload/vod/20250529-1/5d9253cdc2e64a5dea144d6f22866cb5.jpg', 'https://phimimg.com/upload/vod/20250529-1/8ed4c082ba1ecff7854f06a92803df80.jpg', '<p>Sing! Asia - Cuộc tranh tài của 32 giọng ca xuất sắc đến từ khắp châu Á được diễn ra trên du thuyền, đi qua nhiều địa danh nổi tiếng như Okinawa (Nhật Bản), Vịnh Hạ Long (Việt Nam), Klang (Malaysia), Singapore, Thượng Hải và Hồng Kông. Ca sĩ Đan Trường sẽ &quot;ngồi ghế nóng&quot; cùng các minh tinh: Tô Hữu Bằng, Lâm Chí Dĩnh, Cổ Cự Cơ, Trương Trí Lâm, Jessie J... Đặc biệt, Phương Mỹ Chi sẽ là thí sinh đại diện Việt Nam tham gia cuộc thi này.</p>', 'Hoàn Tất (10/10)', 10, 'tvshows', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đan Trường","avatar":""},{"name":"Tô Hữu Bằng","avatar":""},{"name":"Cổ Cự Cơ","avatar":""},{"name":"Lâm Chí Dĩnh","avatar":""},{"name":"Trương Trí Lâm","avatar":""},{"name":"Jessie J","avatar":""},{"name":"Phương Mỹ Chi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '["Sing Asia","亚洲新声"]', 1784690324150);
