INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truyen-thuyet-tran-ho-li', 'Truyền Thuyết Trấn Hồ Lí', 'The Curse Of Huli Town', 'https://phimimg.com/upload/vod/20250801-1/a3d8e03b00610d741b673e61a27f847b.jpg', 'https://phimimg.com/upload/vod/20250801-1/f657a4dd81e050e8430e0cc47cdf8e53.jpg', '<p>Một thị trấn yên bình bỗng kinh hoàng bởi những sự việc kỳ quái, một cảnh tượng rùng rợn từ trăm năm trước tái hiện. Nối tiếp đó, lời nguyền bằng máu của người đàn bà điên để lại càng đẩy thị trấn đến bờ vực của sự diệt vong. Tuy nhiên, giữa màn sương mù trùng điệp này, thứ ẩn hiện là tâm ma của con người hay là một âm mưu được dàn dựng công phu?</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tăng Vũ Kiệt","avatar":""},{"name":"Quan Ngọc Triết","avatar":""},{"name":"Triệu Đại Khê","avatar":""},{"name":"Trâu Đức Giang","avatar":""},{"name":"Trịnh Thác Cương","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hu Li Zhen Chuan Shuo","Legend of Huli Town","胡李镇传说"]', 1784690324150);
