INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('truyen-thuyet-tran-ho-li', 'Truyền Thuyết Trấn Hồ Lí', 'The Curse Of Huli Town', 'truyền thuyết trấn hồ lí the curse of huli town tăng vũ kiệt quan ngọc triết triệu đại khê trâu đức giang trịnh thác cương hu li zhen chuan shuo legend of huli town 胡李镇传说', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-xua-dong-bac-thoi-dai-lon', 'Chuyện Xưa Đông Bắc: Thời Đại Lớn', 'Northeast Stories: The Rising Era', 'https://phimimg.com/upload/vod/20250722-1/22a3126e0d73519987a2fb6d7227e1b7.jpg', 'https://phimimg.com/upload/vod/20250722-1/8d5967f9cd24340e74e878bd6b39e594.jpg', '<p>Chủ tịch tập đoàn Tập Xuân, Mã Như Long, bị tấn công trọng thương và mất trí nhớ. Sau khi được Trần Hồng cưu mang, anh trở thành lao công trong một cửa hàng quần áo. Trong quá trình này, anh đắc tội với tay anh chị địa phương, nhận di ngôn nuôi dưỡng con của Tần Thúc và khi đem cầm ngọc bội lấy tiền, trí nhớ dần hồi phục. Trong cuộc nội đấu của tập đoàn Tập Xuân, anh vực dậy tinh thần, tái cơ cấu Tân Tập Xuân để đối đầu với công ty đối thủ là tập đoàn Vĩnh Minh.</p>', 'Hoàn Tất (42/42)', 42, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Từ Dương","avatar":""},{"name":"An Đông","avatar":""},{"name":"Ni Khả Hân","avatar":""},{"name":"Triệu Nghĩa","avatar":""},{"name":"Ngô Lai","avatar":""},{"name":"Lý Siêu Long","avatar":""},{"name":"Lý Đồng","avatar":""},{"name":"Trịnh Bàng","avatar":""},{"name":"Từ Tư Du","avatar":""},{"name":"Chu Hạo Đông","avatar":""},{"name":"Mã Diên","avatar":""},{"name":"Trương Tuấn Hân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["东北往事","东北往事之黑道风云20年","A Story in Northeast China","东北往事之大时代"]', 1784690324150);
