INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-tai-sinh-cua-ngoi-sao', 'Sự Tái Sinh Của Ngôi Sao', 'Reset', 'https://phimimg.com/upload/vod/20250604-1/5b79b357f5a225732baf5db0b51cf2e2.jpg', 'https://phimimg.com/upload/vod/20250604-1/33621bfe39f899111d3a0459ff9c834c.jpg', '<p>Vào đêm của thành tựu lớn nhất cuộc đời, nam diễn viên Armin bị chính người anh yêu thương nhất phản bội – và mất mạng. Nhưng cái chết không phải là dấu chấm hết. Tái sinh trong hình hài tuổi trẻ của chính mình, Armin được trao cơ hội thứ hai: để viết lại số phận, gặp gỡ người hâm mộ bí ẩn mang tên T.D., và đối mặt với kẻ đã đẩy anh vào bi kịch. Liệu Armin sẽ tìm thấy sự cứu rỗi, sự trả thù – hay một điều gì đó còn vượt xa hơn thế? Đã đến lúc RESET tất cả.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Ponlawit Ketprapakorn","avatar":""},{"name":"Tadsapon Wiwitawan","avatar":""},{"name":"Thanawat Uthaikitwanit","avatar":""},{"name":"Chalongrat Nobsamrong","avatar":""},{"name":"Tanatat Kunaneksin","avatar":""},{"name":"Worawat Boonchuen","avatar":""},{"name":"Shell Thakrit Chaiwut","avatar":""},{"name":"Christopher Tyler Chindapol","avatar":""},{"name":"Dangpan Mikael Thomsen","avatar":""},{"name":"Indy Thanadol Hem-aiyara","avatar":""},{"name":"Alexander Ty Manoiu","avatar":""},{"name":"Roj","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["明星的重生","Reset: The Rebirth of a Star","การเกิดใหม่ของดวงดาว"]', 1784690324150);
