INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-son-luan-kiem-nam-de-bac-cai', 'Hoa Sơn Luận Kiếm: Nam Đế Bắc Cái', 'Southern Emperor And Northern Beggar', 'https://phimimg.com/upload/vod/20250806-1/035b2b600965a618133566b077053396.jpg', 'https://phimimg.com/upload/vod/20250806-1/09617f482adff6e6118f1fc820246d29.jpg', '<p>Thế tử Đại Lý Đoàn Trí Hưng đào hôn rời cung và đệ tử Cái Bang Hồng Thất vừa gặp như đã quen thân. Thiếu nữ Ô Man, Y Hỏa, lầm tưởng Hồng Thất là đối tượng hòa thân, một sự nhầm lẫn lại làm nên lương duyên trời định. Hồng Thất nhờ có cơ duyên mà học được thần công, trở thành bang chủ Cái Bang. Nhưng mối thù sâu nặng từ đời cha ông lại khiến huynh đệ trở mặt, Nhất Dương Chỉ đối đầu Hàng Long Thập Bát Chưởng, long trời lở đất!</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hà Nhuận Đông","avatar":""},{"name":"Cáp Ni Khắc Tư","avatar":""},{"name":"Minh Đạo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["金庸武侠世界·华山论剑","金庸武侠世界第2季","华山论剑之九阴真经","华山论剑之东邪西毒","华山论剑之南帝北丐","华山论剑之五绝争锋","Duel on Mount Hua: Nine Yin True Sutra","Duel on Mount Hua: Eastern Heretic and Western Venom","Duel on Mount Hua: Southern Emperor and Northern Beggar","Duel on Mount Hua: Five Great Masters","华山论剑","金庸武侠世界","金庸武侠世界之华山论剑","김용무협세계: 화산논검","사조영웅전: 화산논검","ศึกประลองยุทธบนเขาฮว่าซาน เดชมารคัมภีร์นพเก้า","Nine Yin True Sutra","Huashan Swords.The Nine Yin Scriptures","Huashan Swords.The Eastern Heretic and Western Venom","Huashan Swords.The Southern Emperor and Northern Beggar","Huashan Swords.Clash of the Five Greats"]', 1784690324150);
