INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoa-son-luan-kiem-nam-de-bac-cai', 'Hoa Sơn Luận Kiếm: Nam Đế Bắc Cái', 'Southern Emperor And Northern Beggar', 'hoa sơn luận kiếm: nam đế bắc cái southern emperor and northern beggar hà nhuận đông cáp ni khắc tư minh đạo 金庸武侠世界·华山论剑 金庸武侠世界第2季 华山论剑之九阴真经 华山论剑之东邪西毒 华山论剑之南帝北丐 华山论剑之五绝争锋 duel on mount hua: nine yin true sutra duel on mount hua: eastern heretic and western venom duel on mount hua: southern emperor and northern beggar duel on mount hua: five great masters 华山论剑 金庸武侠世界 金庸武侠世界之华山论剑 김용무협세계: 화산논검 사조영웅전: 화산논검 ศึกประลองยุทธบนเขาฮว่าซาน เดชมารคัมภีร์นพเก้า nine yin true sutra huashan swords.the nine yin scriptures huashan swords.the eastern heretic and western venom huashan swords.the southern emperor and northern beggar huashan swords.clash of the five greats', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhiem-vu-toi-thuong-2025', 'Nhiệm Vụ Tối Thượng', 'Ultimate Mission', 'https://phimimg.com/upload/vod/20250808-1/24b69d0b08181467ce39f394ec3ad5ab.jpg', 'https://phimimg.com/upload/vod/20250808-1/1dd5b551cbc87ce1cab2ebbafbf0c1a1.jpg', '<p>Trên hòn đảo Ather nằm giữa Thái Bình Dương bất ngờ bùng phát một loại virus chết người. Trước mối đe dọa sinh hóa từ lực lượng vũ trang trên đảo, Liên minh An ninh Sinh hóa Quốc tế đã cử một biệt đội bí mật gồm 3 người đến Ather, thực hiện nhiệm vụ giải cứu trong thời gian giới hạn.</p>', 'Full', 1, 'single', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngô Chấn Vũ","avatar":""},{"name":"An Chí Kiệt","avatar":""},{"name":"Lệ Mã Tịch Đan","avatar":""},{"name":"Hùng Đại Lâm","avatar":""},{"name":"Cố Quân","avatar":""},{"name":"Vương Mẫn Đức","avatar":""},{"name":"Lâm Lặc Tuyền","avatar":""},{"name":"Lý Thừa Duẫn","avatar":""},{"name":"Tiền Gia Lạc","avatar":""},{"name":"Vi Trân","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Ultimate Mission","终极拯救"]', 1784690324150);
