INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhiem-vu-toi-thuong-2025', 'Nhiệm Vụ Tối Thượng', 'Ultimate Mission', 'nhiệm vụ tối thượng ultimate mission ngô chấn vũ an chí kiệt lệ mã tịch đan hùng đại lâm cố quân vương mẫn đức lâm lặc tuyền lý thừa duẫn tiền gia lạc vi trân ultimate mission 终极拯救', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-phan-sinh-huong', 'Cố Phán Sinh Hương', 'Blend Feelings', 'https://phimimg.com/upload/vod/20250806-1/c695a5bbf16cdb6ac0d8674b827eafcd.jpg', 'https://phimimg.com/upload/vod/20250806-1/2d41c548dd71ff75dac0fa89265db31b.jpg', '<p>Giản Hương Hương, một nữ nghệ nhân chế hương cổ truyền, bị bạn trai Cố Gia Thành phản bội cả tình yêu lẫn sự nghiệp. Đúng lúc tuyệt vọng, cô bất ngờ thấy những “dòng bình luận” xuất hiện trong không trung, chế giễu mình. Ban đầu tưởng là ảo giác, nhưng nhiều sự việc liên tiếp chứng minh điều đó có thật, và chúng còn “tiết lộ” rằng ba tháng sau cô sẽ bị Cố Gia Thành đưa vào bệnh viện tâm thần. Quyết tâm thay đổi số phận và trả thù kẻ phản bội, Hương Hương lên kế hoạch tiếp cận Cố Cảnh Thì – tam thúc của Cố Gia Thành. Dù ngồi xe lăn, Cảnh Thì là người lạnh lùng, thông minh, và thực sự nắm quyền trong gia tộc họ Cố. Hương Hương hiểu rằng khóc lóc chỉ là hành động của kẻ yếu; muốn khiến Cố Gia Thành phải quỳ xuống cầu xin, cô phải trở thành tam thẩm của anh ta, trở thành người phụ nữ của Cố Cảnh Thì. Từ đó, một trò chơi tình ái bắt đầu với toan tính nhưng lại kết thúc bằng sự đắm chìm thực sự.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hà Sảng Hi","avatar":""},{"name":"Trương Chú Hàn","avatar":""},{"name":"Miêu Vũ Kiêu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["唯有暗香来","顾盼生香"]', 1784690324150);
