INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thammudu', 'Thammudu', 'Thammudu', 'https://phimimg.com/upload/vod/20250808-1/b6f72098964455ad8f3d4abeb7b33ecf.jpg', 'https://phimimg.com/upload/vod/20250808-1/0ac58683aac69b6f2b9c07ee3fb0c356.jpg', '<p>Bộ phim kể về một người đàn ông mang nhiều tổn thương trong quá khứ, bất ngờ tái ngộ với người em gái của mình. Khi phát hiện em gái và dân làng đang bị đe dọa bởi âm mưu tàn bạo của một doanh nhân tội phạm hung hãn, anh quyết định sát cánh cùng cô để bảo vệ mọi người. Cuộc chiến khốc liệt giữa chính nghĩa và tội ác buộc anh phải đối mặt với cả những bóng tối trong tâm hồn mình.</p>', 'Full', 1, 'single', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Nithiin","avatar":""},{"name":"Sapthami Gowda","avatar":""},{"name":"Laya","avatar":""},{"name":"Varsha Bollamma","avatar":""},{"name":"Swasika","avatar":""},{"name":"Saurabh Sachdeva","avatar":""},{"name":"Hari Teja","avatar":""},{"name":"Srikanth Iyengar","avatar":""},{"name":"Temper Vamsi","avatar":""},{"name":"Chammak Chandra","avatar":""},{"name":"Deetya Sriram","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["తమ్ముడు"]', 1784690324150);
