INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lac-loi-tren-dinh-con-luan-di-sinh', 'Lạc Lối Trên Đỉnh Côn Luân: Dị Sinh', 'Hidden In The Kunlun', 'https://phimimg.com/upload/vod/20250808-1/68e91b2fd384335293f9c2e4a902b4d7.jpg', 'https://phimimg.com/upload/vod/20250808-1/0467390ea7592117b99462ba63bec879.jpg', '<p>Theo truyền thuyết, Tây Vương Mẫu sở hữu bí thuật trường sinh, Mạc Kim Hiệu Úy Hoắc An được phái đi tìm kiếm tiên nhân, nhưng lại gặp phải cuộc tấn công của những con côn trùng kỳ lạ. Hoắc An vô tình có được bình Côn Lôn, nhưng bị năng lượng của nó giam cầm, trở thành một khối băng tinh thể nghìn năm không tan. Nghìn năm sau, Trương Tiêu Hàng, người thành thạo Ngũ Hành, vì muốn tìm kiếm cha mình đã vào mộ Hoắc An, nhưng vô tình khiến anh ta sống lại. Bình Côn Lôn xuất hiện trở lại trên thế gian, và nền văn minh bí ẩn cũng theo đó mà hiện diện.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xie Mingyu","avatar":""},{"name":"Chen Zihan","avatar":""},{"name":"Ying Zhuang","avatar":""},{"name":"Sun Jiaolong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Lạc Lối Trên Đỉnh Côn Luân: Dị Sinh","Hidden in the Kulun","迷航昆仑墟：异生"]', 1784690324150);
