INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguu-lang-chuc-nu', 'Ngưu Lang Chức Nữ', 'Head Over Heels', 'https://phimimg.com/upload/vod/20250624-1/93e56e4419410c589a127345fb0c0379.jpg', 'https://phimimg.com/upload/vod/20250624-1/6295cf08845cf14b511410c7547d336a.jpg', '<p>Cô gái Seong Ah, ban ngày làm nữ sinh, đêm đến sẽ trở thành một pháp sư với số mệnh kết nối dương thế với thế giới linh hồn. Dù không được sống một cuộc đời bình thường, Seong Ah đã học cách đối mặt kiên cường và không bao giờ bỏ cuộc. Cô vô tình gặp Gyeon Woo – cậu thiếu niên với vẻ ngoài hoàn hảo đến phi thực nhưng lại sống dưới lời nguyền của vận xui mãn kiếp. Cuộc đời cậu chỉ là những lần phải đối diện với vận rủi, kỳ vọng dành cho một vận động viên, cô độc đến mức chẳng còn tin vào tình yêu. Lần đầu gặp mặt, Gyeon Woo hiện lên trong mắt Seong Ah với hình hài lộn ngược – dấu hiệu cho thấy cái chết đang cận kề. Hoá ra anh chỉ còn sống được 21 ngày. Với cô, đó không phải kết thúc cho anh mà là khởi đầu của một cuộc chiến chống lại số phận được viết sẵn.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 27, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Cho Yi-hyun","avatar":""},{"name":"Choo Young-woo","avatar":""},{"name":"Cha Kang-yoon","avatar":""},{"name":"Choo Ja-hyun","avatar":""},{"name":"Kim Mi-kyeong","avatar":""},{"name":"Yoon Byung-hee","avatar":""},{"name":"Park Jung-pyo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '["牵牛和仙女","牽牛和仙女","Gyeon U and Fairy","견우와 선녀"]', 1