INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-chinh-la-cao-phong', 'Tôi Chính Là Cao Phong', 'My CEO In Disguise', 'https://phimimg.com/upload/vod/20250719-1/f8d4f8340d4d04a073ad247e35cee9d0.jpg', 'https://phimimg.com/upload/vod/20250719-1/18af511bd57d1ce2bdb4440a843df090.jpg', '<p>Cao Phong, người đứng đầu một tập đoàn tài chính hàng đầu, đã lui về ở ẩn và làm nghề giao hàng. Anh được nữ tổng giám đốc Tô Thanh Nhan thuê làm chồng giả, nhưng cô không hề hay biết anh chính là ông chủ của tập đoàn Quân Thịnh mà cô yêu cầu anh đóng giả. Hai người kết hôn theo hợp đồng, Cao Phong âm thầm dùng năng lực thật sự của mình để giúp vợ giải quyết khó khăn. Cặp đôi oan gia dần nảy sinh tình cảm, và Tô Thanh Nhan cũng dần dần phát hiện ra thân phận thực sự của Cao Phong...</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Quan Tâm","avatar":""},{"name":"Kim Hiền Chính","avatar":""},{"name":"Từ Viên Viên","avatar":""},{"name":"Lữ Tấn Nguyên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wo Ben Shi Gao Feng","我本是高峰"]', 1784690324150);
