INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-tra-ballard', 'Thanh Tra Ballard', 'Ballard', 'https://phimimg.com/upload/vod/20250717-1/8d8746a733870ebb5a13da9b578e6eea.jpg', 'https://phimimg.com/upload/vod/20250717-1/6fa1759cc57f240b50b26298f4cd4cbd.jpg', '<p>Thanh tra Renée Ballard lao vào ma trận của những vụ giết người và tham nhũng khi cô truy lùng một kẻ giết người hàng loạt tàn nhẫn, đồng thời phát hiện ra một âm mưu đen tối trong nội bộ cảnh sát – điều có thể phá hủy tất cả những gì cô đang đấu tranh gìn giữ. Khi những bóng ma quá khứ liên tục bám riết, Ballard buộc phải vượt mặt cả tội phạm lẫn đồng nghiệp để mang lại công lý vốn bị chôn vùi quá lâu cho các nạn nhân và gia đình họ.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Maggie Q","avatar":""},{"name":"Courtney Taylor","avatar":""},{"name":"John Carroll Lynch","avatar":""},{"name":"Michael Mosley","avatar":""},{"name":"Rebecca Field","avatar":""},{"name":"Victoria Moroles","avatar":""},{"name":"Amy Hill","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["巴拉德","밸러드","Ballard"]', 1784690324150);
