INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danh-cap-trai-tim', 'Đánh Cắp Trái Tim', 'Stealing Heart', 'https://phimimg.com/upload/vod/20250724-1/7b1346eec88df9a4d67bb26827e268ab.jpg', 'https://phimimg.com/upload/vod/20250724-1/5953531353dc8c01ff0c2d1d1a137616.jpg', '<p>Kể về thiếu nữ mồ côi Lâm Sơ Ninh sống ở thời Dân Quốc, do hiểu lầm chị em tốt của mình là Tiểu Nhu bị công tử nhà giàu Lục Tư Yến giết hại, nên đã giả danh thân phận tiểu thư nhà họ Lục, trở thành chị em sinh đôi của Lục Tư Yến, xâm nhập nhà họ Lục để trả thù.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Dật Kiệt","avatar":""},{"name":"Chung Lệ Lệ","avatar":""},{"name":"Quyền Phái Luân","avatar":""},{"name":"Tạ An Nhiên","avatar":""},{"name":"Bành Ất Hàng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Qie Xin","窃心"]', 1784690324150);
