INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-doi-cua-chuck', 'Cuộc Đời Của Chuck', 'The Life Of Chuck', 'https://phimimg.com/upload/vod/20250807-1/e8109131eae3a9f78efd7aff67810cdc.jpg', 'https://phimimg.com/upload/vod/20250807-1/3dbf0ce6b2d97db72d6144a15dd912f7.jpg', '<p>Đây là câu chuyện phi thường về một con người tưởng chừng rất đỗi bình thường - Charles “Chuck” Krantz. Trong hành trình đời mình, ông chạm đến vẻ đẹp ngọt ngào của tình yêu, nếm trải nỗi đau tột cùng của mất mát, và khám phá những chiều sâu đa dạng ẩn giấu bên trong mỗi chúng ta. Một câu chuyện đầy cảm xúc về tình yêu, sự mất mát, và bản chất con người.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Hiddleston","avatar":""},{"name":"Benjamin Pajak","avatar":""},{"name":"Nick Offerman","avatar":""},{"name":"Chiwetel Ejiofor","avatar":""},{"name":"Karen Gillan","avatar":""},{"name":"Mia Sara","avatar":""},{"name":"Mark Hamill","avatar":""},{"name":"Annalise Basso","avatar":""},{"name":"Jacob Tremblay","avatar":""},{"name":"Cody Flanagan","avatar":""},{"name":"Samantha Sloyan","avatar":""},{"name":"Trinity Bliss","avatar":""},{"name":"David Dastmalchian","avatar":""},{"name":"Matthew Lillard","avatar":""},{"name":"Kate Siegel","avatar":""},{"name":"Rahul Kohli","avatar":""},{"name":"Harvey Guil","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["La Vida De Chuck","Życie Chucka","Жизнь Чака","A Vida de Chuck","查克的一生","Chucki elu","Η ζωή του Τσάκ","Kha''y