INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gio-tha-mau', 'Giờ Thả Máu', 'Dangerous Animals', 'https://phimimg.com/upload/vod/20250806-1/f25faa9dbefb593b14dce18430d1dd99.jpg', 'https://phimimg.com/upload/vod/20250806-1/133bae8f3382a0d3e5a50afbe2b1ae17.jpg', '<p>Gã thuyền trưởng cuồng cá mập bắt cóc các nạn nhân trẻ để biến họ thành mồi đàn cá, hắn ghi lại những khoảnh khắc tuyệt vọng của nạn nhân để hưởng thụ. Trên con thuyền lênh đênh giữa đại dương, không ai nghe thấy tiếng kêu cứu, họ phải đấu với gã thuyền trưởng điên loạn nếu không muốn trở thành thức ăn cho cá mập.</p>', 'Full', 1, 'single', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Úc', 1, '[{"name":"Hassie Harrison","avatar":""},{"name":"Jai Courtney","avatar":""},{"name":"Josh Heuston","avatar":""},{"name":"Ella Newton","avatar":""},{"name":"Liam Greinke","avatar":""},{"name":"Rob Carlton","avatar":""},{"name":"Ali Basoka","avatar":""},{"name":"Michael Goldman","avatar":""},{"name":"Carly Haynes","avatar":""},{"name":"Dylan Eastland","avatar":""},{"name":"Jon Quested","avatar":""},{"name":"James Munn","avatar":""},{"name":"Ryland Pearson-McManus","avatar":""},{"name":"Giorgia Stawaruk","avatar":""},{"name":"Lucas Crawford","avatar":""},{"name":"Nathan Gordon","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Animales Peligrosos","危险动物","Prédateurs en eaux troubles","حيوانات خطيرة","鲨人魔","Dangerous Animals","O žralocích a lidech"]', 1784690324151);
