INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-dao-ho-phach', 'Anh Đào Hổ Phách', 'Our Generation', 'https://phimimg.com/upload/vod/20250714-1/142b36ad3c341eb65d7055c470f01343.jpg', 'https://phimimg.com/upload/vod/20250714-1/460865f448855b74863ab11f8d9bc961.jpg', '<p>Lâm Anh Đào là một cô gái có tính cách tươi sáng, hồn nhiên, lớn lên trong tình yêu thương vô bờ bến của gia đình và nhóm bạn thời niên thiếu. Tuổi thơ giản dị và hạnh phúc đó bắt đầu rẽ sang hướng khác khi thần đồng Toán học Tưởng Kiều Tây chuyển đến học cùng trường với cô. Ngay lần đầu gặp gỡ, vẻ lạnh lùng, cô độc của Kiều Tây đã thu hút sự chú ý của Anh Đào và từ đó, cuộc sống của họ cũng dần dà có sự gắn kết ngày một sâu đậm. Không chỉ xoay quanh mối quan hệ giữa Anh Đào và Kiều Tây, Anh Đào Hổ Phách còn là câu chuyện của nhiều bạn trẻ thế hệ 9x giữa những biến chuyển của thời đại.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Kim Mạch","avatar":""},{"name":"Trương Lăng Hách","avatar":""},{"name":"Đổng Khiết","avatar":""},{"name":"Bảo Kiếm Phong","avatar":""},{"name":"Đổng Tuyền","avatar":""},{"name":"Trương Đạc","avatar":""},{"name":"Thẩm Giai Ngọc","avatar":""},{"name":"Ngọ Thánh","avatar":""},{"name":"Mã Khải Việt","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Cherry Amber","Oceans Time","Oceans of Time","앵도호박","앵도호박: 앵두빛 시절","Аромат вишни","Наше поколение","Our Generation","樱桃琥珀"]', 1784690324151);
