INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('anh-dao-ho-phach', 'Anh Đào Hổ Phách', 'Our Generation', 'anh đào hổ phách our generation triệu kim mạch trương lăng hách đổng khiết bảo kiếm phong đổng tuyền trương đạc thẩm giai ngọc ngọ thánh mã khải việt cherry amber oceans time oceans of time 앵도호박 앵도호박: 앵두빛 시절 аромат вишни наше поколение our generation 樱桃琥珀', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-trieu-tap-hung', 'Ám Triều Tập Hung', 'Beneath The Undertow', 'https://phimimg.com/upload/vod/20250801-1/58a76151c35a03dcfd651ced83d3fea8.jpg', 'https://phimimg.com/upload/vod/20250801-1/b5dc83526a1445c643cea352d90cb2ab.jpg', '<p>Tại nhà máy quốc doanh Húc Nhật từng sầm uất, một xác nữ bị mất chân được phát hiện tại hồ nước thải bỏ hoang. Nạn nhân là Thẩm Tiểu Chu - con của một công nhân trong nhà máy. Viên cảnh sát trung niên điềm đạm Liên Hải Bình và cảnh sát trẻ nóng nảy Thạch Cường Phong vô tình trở thành đồng đội, dù có nhiều mâu thuẫn nhưng buộc phải hợp tác để tìm ra hung thủ thực sự. Trong quá trình điều tra, hàng loạt nghi phạm lần lượt xuất hiện, hai người dần phát hiện rằng phía sau cô sinh viên đại học tưởng chừng &quot;trắng trong như tuyết&quot; này lại ẩn giấu nhiều góc khuất của xã hội. Đồng thời, một vụ án cũ liên quan mật thiết đến cả hai cũng dần dần lộ diện, khiến mối quan hệ giữa Liên Hải Bình và Thạch Cường Phong trở nên phức tạp. Khi vụ án còn chưa có lời giải, hàng loạt án mạng nữ bị mất chân tiếp tục xảy ra, bao trùm lên nhà máy Húc Nhật một bầu không khí u ám.</p>', 'Hoàn Tất (19/19)', 19, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chen Jianbin","avatar":""},{"name":"Chen Ruoxuan","avatar":""},{"name":"Sierra Li","avatar":""},{"name":"Cheng Taishen","avatar":""},{"name":"Mei Ting","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["暗潮","Beneath The Undertow","暗潮缉凶"]', 1784690324151);
