INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-nam-tin-nu', 'Thiện Nam Tín Nữ', 'The Best Couple', 'https://phimimg.com/upload/vod/20250805-1/321aa9a3469cb5aa1d19bf9e776b0aa7.jpg', 'https://phimimg.com/upload/vod/20250805-1/82a575905e163644ebac571982231b60.jpg', '<p>Trong hẻm tối tù mù ánh đèn neon có &quot;Phòng khám Nhân Tâm&quot; của bác sĩ chui Mộc Vãn máu lạnh và tham tiền. Nhưng thật ra cô đã ẩn mình suốt 5 năm để nhắm đến mục tiêu là thái tử đế quốc hắc ám Mã Duật Đình. Khi anh bước vào phòng khám với cơ thể bị thương trầm trọng, cũng là lúc ván cờ chết chóc của cô chính thức bắt đầu. Nhưng anh đã nhìn thấu kế hoạch trả thù của cô từ rất lâu. Vừa chăm sóc vừa thăm dò, những tính toán và chinh phục của hai thợ săn tài giỏi đan xen vào nhau, ham muốn mãnh liệt đến ăn mòn xương tủy bùng lên giữa những rối rắm chí mạng. Cô là định mệnh của anh, cũng là kiếp nạn anh không thể tránh khỏi...</p>', 'Hoàn Tất (80/80)', 80, 'series', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Khải Mộc","avatar":""},{"name":"Mã Lạc Tiệp","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324151);
