INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-hi-phong-van', 'Thiên Hi Phong Vân', 'Millennium Storm', 'https://phimimg.com/upload/vod/20250729-1/9aadad9fdfe5a92ea61f8ad30073fb7b.jpg', 'https://phimimg.com/upload/vod/20250729-1/c3ed9af7cd88bf30d498f96733d0adbd.jpg', '<p>Thiên tài công nghệ thông tin Lý Thiên và người bạn thân Trương Lượng bất ngờ quay trở về những năm 2000. Lý Thiên biến thành một anh chàng nghèo khó, nợ nần chồng chất và ngỡ ngàng hơn khi phát hiện mình có thêm một người vợ xa lạ. Để trả nợ, với sự giúp đỡ của người bạn tri kỷ, anh đã tay trắng bắt đầu hành trình khởi nghiệp. Thế nhưng, anh lại bị chính người anh em tốt năm xưa của mình chèn ép, buộc phải lao vào một cuộc chiến trên thương trường. Cùng lúc đó, sự thật đằng sau việc anh xuyên không cũng dần dần được hé lộ.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lữ Quân Phong","avatar":""},{"name":"Mã Tâm Dư","avatar":""},{"name":"Bộ Tử Dĩnh","avatar":""},{"name":"Quách Tường","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["千禧风云"]', 1784690324151);
