INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghenh-phuong-quy', 'Nghênh Phượng Quy', 'She Is The Phoenix', 'https://phimimg.com/upload/vod/20250722-1/2acb683a4b6e6050583600484c58f661.jpg', 'https://phimimg.com/upload/vod/20250722-1/46d88cf4cd32d10fda8ec48136259393.jpg', '<p>Khương Lạc Dao, một cô gái xuất thân bần hàn làm dâu nhà giàu, bị bạn thân bắt tay với con nhà quyền quý hành hạ đến chết. Cô sống lại quay về, lại phát hiện cô bạn thân cũng đã tái sinh, hơn nữa lần này cô ta đã thay thế cô làm dâu nhà giàu. Ngay khi Khương Lạc Dao thực hiện kế hoạch báo thù, cô phát hiện đằng sau người bạn thân còn có nhân vật quyền lực...</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Mã Thu Nguyên","avatar":""},{"name":"Hà Kiện Kỳ","avatar":""},{"name":"Thường Triết Khoan","avatar":""},{"name":"Lý Gia Đồng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ying Feng Gui","迎凤归"]', 1784690324151);
