INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-son-luan-kiem-dong-ta-tay-doc', 'Hoa Sơn Luận Kiếm: Đông Tà Tây Độc', 'Eastern Heretic And Western Venom', 'https://phimimg.com/upload/vod/20250801-1/8f5af6974e53b3b030030fab7005a18f.jpg', 'https://phimimg.com/upload/vod/20250801-1/e719685db54ac7994aa76e1bff229b8e.jpg', '<p>Hoàng Dược Sư, Âu Dương Phong, hai quái nhân mới bước chân vào giang hồ, một người tiêu dao tựa thần tiên, một người ngây thơ như trẻ nhỏ, vừa là địch vừa là bạn, châm ngòi một cuộc loạn thế phân tranh đầy âm mưu khôn lường.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chu Nhất Vi","avatar":""},{"name":"Cao Vỹ Quang","avatar":""},{"name":"Trần Đô Linh","avatar":""},{"name":"La Thu Vận","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["金庸武侠世界·华山论剑","金庸武侠世界第2季","华山论剑之九阴真经","华山论剑之东邪西毒","华山论剑之南帝北丐","华山论剑之五绝争锋","Duel on Mount Hua: Nine Yin True Sutra","Duel on Mount Hua: Eastern Heretic and Western Venom","Duel on Mount Hua: Southern Emperor and Northern Beggar","Duel on Mount Hua: Five Great Masters","华山论剑","金庸武侠世界","金庸武侠世界之华山论剑","김용무협세계: 화산논검","사조영웅전: 화산논검","ศึกประลองยุทธบนเขาฮว่าซาน เดชมารคัมภีร์นพเก้า","Nine Yin True Sutra","Huashan Swords.The Nine Yin Scriptures","Huashan Swords.The Eastern Heretic and Western Venom","Huashan Swords.The Southern Emperor and Northern Beggar","Huashan Swords.Clash of the Five Greats"]', 1784690324151);
