INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoa-son-luan-kiem-dong-ta-tay-doc', 'Hoa Sơn Luận Kiếm: Đông Tà Tây Độc', 'Eastern Heretic And Western Venom', 'hoa sơn luận kiếm: đông tà tây độc eastern heretic and western venom chu nhất vi cao vỹ quang trần đô linh la thu vận 金庸武侠世界·华山论剑 金庸武侠世界第2季 华山论剑之九阴真经 华山论剑之东邪西毒 华山论剑之南帝北丐 华山论剑之五绝争锋 duel on mount hua: nine yin true sutra duel on mount hua: eastern heretic and western venom duel on mount hua: southern emperor and northern beggar duel on mount hua: five great masters 华山论剑 金庸武侠世界 金庸武侠世界之华山论剑 김용무협세계: 화산논검 사조영웅전: 화산논검 ศึกประลองยุทธบนเขาฮว่าซาน เดชมารคัมภีร์นพเก้า nine yin true sutra huashan swords.the nine yin scriptures huashan swords.the eastern heretic and western venom huashan swords.the southern emperor and northern beggar huashan swords.clash of the five greats', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoi-nguon-led-zeppelin', 'Khởi Nguồn Led Zeppelin', 'Becoming Led Zeppelin', 'https://phimimg.com/upload/vod/20250804-1/516bfcb5b22476c789cc7474d4a72f09.jpg', 'https://phimimg.com/upload/vod/20250804-1/61bc8fe872d0eeffdb8930d3baa04eca.jpg', '<p>Với cuộc phỏng vấn mới, thước phim và màn trình diễn chưa từng công bố, bộ phim tài liệu này kể câu chuyện khởi nguồn của Led Zeppelin qua lời kể của chính ban nhạc biểu tượng này.</p>', 'Full', 1, 'single', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Jimmy Page","avatar":""},{"name":"John Paul Jones","avatar":""},{"name":"John Bonham","avatar":""},{"name":"Robert Plant","avatar":""},{"name":"Peter Grant","avatar":""},{"name":"Little Richard","avatar":""},{"name":"Eddie Kramer","avatar":""},{"name":"Glyn Johns","avatar":""},{"name":"Donovan","avatar":""},{"name":"Lonnie Donegan","avatar":""},{"name":"Sonny Boy Williamson","avatar":""},{"name":"Jeff Beck","avatar":""},{"name":"Shirley Bassey","avatar":""},{"name":"Lulu","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '["Untitled Led Zeppelin Documentary","Becoming Led Zeppelin: Los inicios","Introducing Led Zeppelin","לד זפלין: מדרגות אל הפסגה","Becoming Led Zeppelin"]', 1784690324151);
