INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khoi-nguon-led-zeppelin', 'Khởi Nguồn Led Zeppelin', 'Becoming Led Zeppelin', 'khởi nguồn led zeppelin becoming led zeppelin jimmy page john paul jones john bonham robert plant peter grant little richard eddie kramer glyn johns donovan lonnie donegan sonny boy williamson jeff beck shirley bassey lulu untitled led zeppelin documentary becoming led zeppelin: los inicios introducing led zeppelin לד זפלין: מדרגות אל הפסגה becoming led zeppelin', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-chua-ke', 'Điều Chưa Kể', 'Untold', 'https://phimimg.com/upload/vod/20250804-1/5c9f12f447de43ce297d00491fbc36a7.jpg', 'https://phimimg.com/upload/vod/20250804-1/2a703869c25be035e1e66f39c9e7cbe8.jpg', '<p>Hành trình nổi tiếng bất chính của một nhà báo tàn nhẫn quay lại ám ảnh cô khi cô đối mặt với sự thật về những gì mình đã gây ra và những người cô từng làm tổn thương để tiến xa.</p>', 'Full', 1, 'single', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Jodi Sta. Maria","avatar":""},{"name":"Juan Karlos Labajo","avatar":""},{"name":"Kaori Oinuma","avatar":""},{"name":"Lianne Valentin","avatar":""},{"name":"Gloria Diaz","avatar":""},{"name":"Joem Bascon","avatar":""},{"name":"Mylene Dizon","avatar":""},{"name":"Sarah Edwards","avatar":""},{"name":"Gian Magdangal","avatar":""},{"name":"Miggs Cuaderno","avatar":""},{"name":"Carlos San Juan","avatar":""},{"name":"Geraldine Villamil","avatar":""},{"name":"Lui Manansala","avatar":""},{"name":"Frances Ignacio","avatar":""},{"name":"Angel Raymundo","avatar":""},{"name":"Francis Mata","avatar":""},{"name":"T","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Untold"]', 1784690324151);
