INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-nhan-kiet-quy-tran-u-hon', 'Địch Nhân Kiệt: Quỷ Trấn U Hồn', 'Detective Dee: The Ghosts In Weird Town', 'https://phimimg.com/upload/vod/20250804-1/901d3bce6be0159be8ae7a704447fa0c.jpg', 'https://phimimg.com/upload/vod/20250804-1/3ae239dd46a6865811beb8d54b8fee6b.jpg', '<p>Trấn U Minh đột nhiên biến loạn, người sống hóa xác, nanh dài nhỏ máu biến thành cương thi. Địch Nhân Kiệt vào cuộc điều tra và phát hiện: U Minh giáo dùng cổ trùng để điều khiển xác chết, mà kẻ đứng sau lại là Việt Vương Lý Trinh! Hắn âm mưu luyện đại quân cương thi để tạo phản. Trong thời khắc ngàn cân treo sợi tóc, Địch Nhân Kiệt dùng hoàng hùng liệt hỏa ngăn cản đám cương thi, vung Kháng Long giản chém chết vua cương thi. Cuối cùng, cổ mẫu nổ tung, xác sống hóa thành máu, đập tan âm mưu kinh thiên động địa, khó phân người hay quỷ.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jason Chu Wing-Tong","avatar":""},{"name":"Shen Baoping","avatar":""},{"name":"Tong Xiaohu","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Detective Dee: The Ghosts in Weird Town","Địch Nhân Kiệt: Quỷ Trấn U Hồn","狄仁杰之诡镇幽魂"]', 1784690324151);
