INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dich-nhan-kiet-quy-tran-u-hon', 'Địch Nhân Kiệt: Quỷ Trấn U Hồn', 'Detective Dee: The Ghosts In Weird Town', 'địch nhân kiệt: quỷ trấn u hồn detective dee: the ghosts in weird town jason chu wing-tong shen baoping tong xiaohu detective dee: the ghosts in weird town địch nhân kiệt: quỷ trấn u hồn 狄仁杰之诡镇幽魂', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-xuoi-duoi-dut-lot', 'Đầu Xuôi Đuôi Đút Lót', 'Lobby', 'https://phimimg.com/upload/vod/20250502-1/82faca088cf1c400a766486ea0fc2f8c.jpg', 'https://phimimg.com/upload/vod/20250502-1/35052c11f73521f4e244bda9e27ff59b.jpg', '<p>Yoon Chang Wook - CEO một công ty công nghệ nhỏ, giỏi nghiên cứu nhưng mù tịt chuyện thương trường. Khi công ty sắp sập tiệm vì bị “bạn thân” cũ Son Gwang-woo đâm sau lưng bằng chiêu trò đút lót để giành lấy dự án quốc gia, Chang-wook buộc phải bước vào một cuộc chơi hoàn toàn xa lạ: đút lót bằng golf - “môn thể thao quyền lực” của giới làm ăn. Một trận đấu thầu có một không hai, nơi những cú đánh trượt là chiến lược, còn đút lót là kỹ năng, tạo nên trận đấu vừa hài hước, vừa châm biếm về thương trường thời hiện đại.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 1, '[{"name":"Ha Jung-woo","avatar":""},{"name":"Kim Eui-sung","avatar":""},{"name":"Kang Hae-lim","avatar":""},{"name":"Lee Dong-hwi","avatar":""},{"name":"Park Byung-eun","avatar":""},{"name":"Kang Mal-geum","avatar":""},{"name":"Choi Si-won","avatar":""},{"name":"Cha Joo-young","avatar":""},{"name":"Park Hae-soo","avatar":""},{"name":"Kwak Sun-young","avatar":""},{"name":"Hyun Bong-sik","avatar":""},{"name":"Uhm Ha-neul","avatar":""},{"name":"Lee Soo-in","avatar":""},{"name":"Park Kyung-hye","avatar":""},{"name":"Son Byeong-uk","avatar":""},{"name":"Lee Sang-won","avatar":""},{"name":"Kim Min","avatar":""},{"name":"Kim Jong-soo","avatar":""},{"name":"Yoo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b0