INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-loc-tru-doc', 'Cơn Lốc Trừ Độc', 'War On Drug', 'https://phimimg.com/upload/vod/20250804-1/03eeeae165fd96672462d5183cec6c8d.jpg', 'https://phimimg.com/upload/vod/20250804-1/4f61b93ee1a70fe1fa29b5be9972f8d0.jpg', '<p>Cảnh sát phòng chống ma túy Khang Miêu trong hành trình truy bắt tên trùm khét tiếng &quot;Lão Diêu&quot; đã bàng hoàng phát hiện ra kẻ đứng sau đường dây ma túy chính là người anh trai đã thất lạc suốt 12 năm Lôi Đình! Ân oán quá khứ dần được hé lộ. Lôi Đình vì cứu Phong Linh mà buộc phải bán mạng cho ông trùm ma túy. Cuộc chơi mèo vờn chuột ngày càng căng thẳng, hai anh em đối địch nơi đầu súng. Khi chính nghĩa và tình thân đụng nhau, Lôi Đình lựa chọn hy sinh tính mạng để chuộc lỗi, còn Khang Miêu vẫn giữ vững niềm tin, thề phải xóa sạch mạng lưới ma túy. Đằng sau con đường chống ma túy là máu, nước mắt và sự giằng xé tận cùng của nhân tính.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Gao Ge","avatar":""},{"name":"Mou Fengbin","avatar":""},{"name":"Zhao Shunran","avatar":""},{"name":"Wang Wanzhong","avatar":""},{"name":"Xiu Ge","avatar":""},{"name":"Zhu Yuanyuan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sao Du Feng Bao","扫毒风暴"]', 1784690324151);
