INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bach-van-trai-quai-thoai', 'Bạch Vân Trai Quái Thoại', 'Baiyun Ghost House', 'https://phimimg.com/upload/vod/20250804-1/d8ebeb2c4883a683dc79a5a60643af47.jpg', 'https://phimimg.com/upload/vod/20250804-1/ec5f007b03a8027c0fca9dbacd433ef0.jpg', '<p>Có một tiệm quan tài tên là Bạch Vân Trai, dân gian đồn rằng: ai dính dáng đến nơi đó đều sẽ gặp “ngũ bại tam thiếu”. Gần đây, trong trấn liên tục xảy ra những chuyện kỳ dị. Trước là Lưu Ma Tử chết thảm dưới giếng, bị thủy quỷ đoạt mệnh. Sau là một người đồ tể bị quỷ sai câu hồn, giết chết cả nhà. Sự việc kỳ bí lạ lùng. Lúc này, một đạo sĩ giang hồ Mã tiên sinh quyết định ra tay bắt quỷ trừ tà, lần theo manh mối đến Bạch Vân Trai.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Eric Wan Tin-Chiu","avatar":""},{"name":"Cheng Chaoyue","avatar":""},{"name":"Ziwen Zhang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["白云斋怪话"]', 1784690324151);
