INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('11-moi-tinh-truoc-em-11-cinta-sebelum-kamu', '11 Mối Tình Trước Em (11 Cinta Sebelum Kamu)', '11 Hearts Before You', 'https://phimimg.com/upload/vod/20250804-1/e7539ed804537279ecc813a83dd2506c.jpg', 'https://phimimg.com/upload/vod/20250804-1/5107e777261645c389b39d0512f3e803.jpg', '<p>Để cưới được vị hôn thê, Ray phải thực hiện một nhiệm vụ gần như bất khả thi nhằm được mẹ vợ chấp thuận: xin lỗi toàn bộ 11 người yêu cũ trong quá khứ trăng hoa của anh.</p>', 'Full', 1, 'single', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Fattah Amin","avatar":""},{"name":"Liyana Jasmay","avatar":""},{"name":"Megat Shahrizal","avatar":""},{"name":"Maisarah Sufia","avatar":""},{"name":"Atoi Tohet","avatar":""},{"name":"Maria Farida","avatar":""},{"name":"Ahirine Ahirudin","avatar":""},{"name":"Afifah Nasir","avatar":""},{"name":"Elizabeth Tan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["11 Cinta Sebelum Kamu"]', 1784690324151);
