INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('11-moi-tinh-truoc-em-11-cinta-sebelum-kamu', '11 Mối Tình Trước Em (11 Cinta Sebelum Kamu)', '11 Hearts Before You', '11 mối tình trước em (11 cinta sebelum kamu) 11 hearts before you fattah amin liyana jasmay megat shahrizal maisarah sufia atoi tohet maria farida ahirine ahirudin afifah nasir elizabeth tan 11 cinta sebelum kamu', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('minh-moi-thien-thu', 'Minh Môi Thiện Thú', 'Better Halves', 'https://phimimg.com/upload/vod/20250725-1/68920108cf835791cb2768d5db75c97c.jpg', 'https://phimimg.com/upload/vod/20250725-1/06da737f5a69f0979850d29a211c06b3.jpg', '<p>Phim về câu chuyện của cô nàng thiên kim được nuông chiều của quan môi (mai mối) thế gia Thi Phạt Kha chạm trán &quot;phỉ nhị đại&quot; Lục Trì xuống núi tìm&quot;Tiểu muội muội&quot;. Thi Phạt Kha một lòng muốn đoạt vinh dự Thiên Hạ Đệ Nhất Mai Mối, Lục Trì chỉ có thể hoá thân &quot;sứ giả hộ thê&quot;, bước lên con đường theo đuổi thê tử gian nan. Hai người trải qua nhiều trắc trở, hợp lực giải quyết nhiều vụ cưới hỏi nan giản. Cuối cùng Thi Phạt Kha viết lên danh dự cho gia tộc, Lục Trì cũng trợ giúp hoàng đế bảo vệ thiên hạ thái bình. Sau cùng hoàng đế ban hôn cho Thiên Hạ Đệ Nhất Mai Mối Thi Phạt Kha và tiểu ca ca Lục Trì của cô.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Sư Phạt Khắc","avatar":""},{"name":"Lục Trì","avatar":""},{"name":"Hạ Khả Thành","avatar":""},{"name":"Hồ Đan Đan","avatar":""},{"name":"Quản Lạp","avatar":""},{"name":"Trần Tử Hàm","avatar":""},{"name":"Khổng Liên Thuận","avatar":""},{"name":"Triệu Phẩm Lâm","avatar":""},{"name":"Lưu Mỹ Đồng","avatar":""},{"name":"Hà Phụng Thiên","avatar":""},{"name":"Hà Minh Hàn","avatar":""},{"name":"Vương Tử Vi","avatar":""},{"name":"Trịnh Thư Hoàn","avatar":""},{"name":"Lý Tông Lâm","avatar":""},{"name":"Lâm Mộng Kỳ","avatar":""},{"name":"Mã Khiêm Khiêm","avatar":""},{"name":"Tô Mộng Vân","avatar":""},{"name":"Mông Ân","avatar":""},{"name":"Lý Tư Kỳ","avatar":""},{"name":"Kiều","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7