INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-duong-sinh-ton-cua-co-ay', 'Con Đường Sinh Tồn Của Cô Ấy', 'HER', 'https://phimimg.com/upload/vod/20250722-1/83c387cbc21e82b067aa3de22afba00f.jpg', 'https://phimimg.com/upload/vod/20250722-1/92c7e99991d7e6b95eb4d1500de8ed56.jpg', '<p>Thiếu nữ quyền anh Lưu Diêm đánh mất sự nghiệp sau một trận đấu tai tiếng và sang nước ngoài lo hậu sự cho người mẹ đã bỏ rơi mình, chỉ để phát hiện ra khoản nợ lớn và trách nhiệm với cậu em trai xa lạ; tại đây, cô từng bước làm lại cuộc đời trong ngành ẩm thực, đối mặt với quá khứ, tình thân và lựa chọn con đường riêng để làm chủ số phận.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Leah Dou","avatar":""},{"name":"Vương Truyền Quân","avatar":""},{"name":"Nhan Bính Yến","avatar":""},{"name":"Tống Nghiên Phi","avatar":""},{"name":"Hạ Khai Lãng","avatar":""},{"name":"Ngưu Siêu","avatar":""},{"name":"Ổ Gia Giai","avatar":""},{"name":"Điền Tráng Tráng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ta De Sheng Cun Zhi Dao","Her","Her Way of Survival","Existence","她的生存之道"]', 1784690324151);
