INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cua-tu', 'Cửa Tử', 'Hell Motel', 'https://phimimg.com/upload/vod/20250618-1/5d3ad3eb0ca1d17c4f1566916fdc178b.jpg', 'https://phimimg.com/upload/vod/20250618-1/bf6788efe2747fcf8cc260181e2d7695.jpg', '<p>10 tín đồ mê phá án được mời đến dự đêm khai trương khu nghỉ Cold River Motel, nơi từng xảy ra vụ thảm sát nghi lễ Satan rúng động trước đó 30 năm. Nhưng khi các vị khách bị kẹt lại, lịch sử đẫm máu bắt đầu tái hiện. Lần lượt từng người bị sát hại trong một chuỗi tội ác ngày càng man rợ, vượt xa những gì từng được ghi chép trong hồ sơ vụ án cũ...</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Eric McCormack","avatar":""},{"name":"Paula Brancati","avatar":""},{"name":"Shaun Benson","avatar":""},{"name":"Atticus Mitchell","avatar":""},{"name":"Genevieve DeGraves","avatar":""},{"name":"Emmanuel Kabongo","avatar":""},{"name":"Jim Watson","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Мотель жаху","Мотель \"Пекло\"","Hell Motel"]', 1784690324151);
