INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-thoai-voi-ke-sat-nhan-thuoc-phim-ve-con-trai-cua-sam', 'Đối Thoại Với Kẻ Sát Nhân: Thước Phim Về Con Trai Của Sam', 'Conversations With A Killer: The Son Of Sam Tapes', 'https://phimimg.com/upload/vod/20250802-1/f07a44babe1238267429dcb5a2583dba.jpg', 'https://phimimg.com/upload/vod/20250802-1/34ea82757da37155c9122e323c476d33.jpg', '<p>Kết hợp các cuộc phỏng vấn hiện tại với những đoạn ghi âm chưa từng công bố, loạt phim về tội phạm này khám phá dấu ấn của tên sát nhân David Berkowitz tại New York thập niên 1970.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jack Jones","avatar":""},{"name":"Mary Murphy","avatar":""},{"name":"Joseph Borrelli","avatar":""},{"name":"Lawrence Klausner","avatar":""},{"name":"Manny Grossman","avatar":""},{"name":"Marlin Hopkins","avatar":""},{"name":"Richard Edmonds","avatar":""},{"name":"John Comparetto","avatar":""},{"name":"Dick Belsky","avatar":""},{"name":"William Gardella","avatar":""},{"name":"Gloria Zonghetti","avatar":""},{"name":"Carl Denaro","avatar":""},{"name":"Charles Lomino","avatar":""},{"name":"Vinny Minutolo","avatar":""},{"name":"Kevin Breslin","avatar":""},{"name":"Robert Violante","avatar":""},{"name":"St","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["对话杀人魔：山姆之子访谈录","Conversations with a Killer: The Son of Sam Tapes"]', 1784690324151);
