INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doi-thoai-voi-ke-sat-nhan-thuoc-phim-ve-con-trai-cua-sam', 'Đối Thoại Với Kẻ Sát Nhân: Thước Phim Về Con Trai Của Sam', 'Conversations With A Killer: The Son Of Sam Tapes', 'đối thoại với kẻ sát nhân: thước phim về con trai của sam conversations with a killer: the son of sam tapes jack jones mary murphy joseph borrelli lawrence klausner manny grossman marlin hopkins richard edmonds john comparetto dick belsky william gardella gloria zonghetti carl denaro charles lomino vinny minutolo kevin breslin robert violante st 对话杀人魔：山姆之子访谈录 conversations with a killer: the son of sam tapes', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-son-luan-kiem-cuu-am-chan-kinh', 'Hoa Sơn Luận Kiếm: Cửu Âm Chân Kinh', 'Nine Yin True Sutra', 'https://phimimg.com/upload/vod/20250801-1/e11eb483c62757138cc864fd2c2eb6d1.jpg', 'https://phimimg.com/upload/vod/20250801-1/baa6625d5e29ff75fed46caf56974b0e.jpg', '<p>Dựa trên nền tảng là các tác phẩm kinh điển của Kim Dung cùng tinh thần nghĩa hiệp ẩn chứa trong đó, dùng một hình thức mới mẻ để viết nên một áng văn về giang hồ Kim Dung đầy hùng tráng. Lấy kinh điển làm điểm khởi đầu, tiếp nối tiền truyện của Ngũ Tuyệt, đồng thời bổ sung những chuyện cũ trên giang hồ vào những khoảng trống trong nguyên tác.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chu Nhất Vi","avatar":""},{"name":"Mạnh Tử Nghĩa","avatar":""},{"name":"Nick-Hà Dư","avatar":""},{"name":"Trần Đô Linh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["金庸武侠世界·华山论剑","金庸武侠世界第2季","华山论剑之九阴真经","华山论剑之东邪西毒","华山论剑之南帝北丐","华山论剑之五绝争锋","Duel on Mount Hua: Nine Yin True Sutra","Duel on Mount Hua: Eastern Heretic and Western Venom","Duel on Mount Hua: Southern Emperor and Northern Beggar","Duel on Mount Hua: Five Great Masters","华山论剑","金庸武侠世界","金庸武侠世界之华山论剑","김용무협세계: 화산논검","사조영웅전: 화산논검","ศึกประลองยุทธบนเขาฮว่าซาน เดชมารคัมภีร์นพเก้า","Nine Yin True Sutra","Huashan Swords.The Nine Yin Scriptures","Huashan Swords.The Eastern Heretic and Western Venom","Huashan Swords.The Southern Emperor and Northern Beggar","Huashan Swords.Clash of the Five Greats"]', 1784690324151);
