INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoa-son-luan-kiem-cuu-am-chan-kinh', 'Hoa Sơn Luận Kiếm: Cửu Âm Chân Kinh', 'Nine Yin True Sutra', 'hoa sơn luận kiếm: cửu âm chân kinh nine yin true sutra chu nhất vi mạnh tử nghĩa nick-hà dư trần đô linh 金庸武侠世界·华山论剑 金庸武侠世界第2季 华山论剑之九阴真经 华山论剑之东邪西毒 华山论剑之南帝北丐 华山论剑之五绝争锋 duel on mount hua: nine yin true sutra duel on mount hua: eastern heretic and western venom duel on mount hua: southern emperor and northern beggar duel on mount hua: five great masters 华山论剑 金庸武侠世界 金庸武侠世界之华山论剑 김용무협세계: 화산논검 사조영웅전: 화산논검 ศึกประลองยุทธบนเขาฮว่าซาน เดชมารคัมภีร์นพเก้า nine yin true sutra huashan swords.the nine yin scriptures huashan swords.the eastern heretic and western venom huashan swords.the southern emperor and northern beggar huashan swords.clash of the five greats', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trieu-trieu-nhu-niem', 'Triều Triều Như Niệm', 'In The Name Of Dawn', 'https://phimimg.com/upload/vod/20250725-1/8b9bbd5976be07028f5ed4b606664a7b.jpg', 'https://phimimg.com/upload/vod/20250725-1/1a124d97b7e60806f9b82d9b5299c98c.jpg', '<p>Bộ phim kể về Cố Triêu Triêu, cô dâu bị chồng và bạn thân hãm hại rơi xuống vực trong đêm tân hôn. Năm năm sau, cô tái sinh thành Kỷ Vân Triêu, dùng năng lực tiên đoán tương lai để đối đầu “người xuyên sách” Khâu Hiền Nhi – kẻ điều khiển cốt truyện và hỗ trợ kẻ thù của cô. Trên hành trình trả thù, Cố Triêu Triêu liên minh cùng Hầu gia Bùi Yến, từng bước phá vỡ âm mưu của đối phương và viết lại số phận chính mình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hà Tuyên Lâm","avatar":""},{"name":"Trương Đình Duy","avatar":""},{"name":"Lý Diệm Mạn","avatar":""},{"name":"Trương Huyên Vũ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Zhao Zhao Ru Nian","In the Name of Dawn","The Silent Quill","朝朝如念"]', 1784690324151);
