INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('trieu-trieu-nhu-niem', 'Triều Triều Như Niệm', 'In The Name Of Dawn', 'triều triều như niệm in the name of dawn hà tuyên lâm trương đình duy lý diệm mạn trương huyên vũ zhao zhao ru nian in the name of dawn the silent quill 朝朝如念', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-tieu-thu-ngay-nao-cung-don-valentine', 'Đổng Tiểu Thư Ngày Nào Cũng Đón Valentine', 'Miss Dong Spends Valentine''s Day Every Day', 'https://phimimg.com/upload/vod/20250801-1/9f6f4310e28b50e7f29b95c4772e4bec.jpg', 'https://phimimg.com/upload/vod/20250801-1/0b65153c3d8d02d425407a460f802a37.jpg', '<p>Sau khi bị chế giễu nơi công sở và tổn thương vì thất tình, cô nàng mắc chứng sợ xã hội – tiểu thư họ Đổng – đã ước một Valentine ngọt ngào khi nhìn thấy sao băng. Không ngờ, cô lại rơi vào một vòng lặp vô tận của những tình tiết lãng mạn. Ban đầu, cô say mê với những màn theo đuổi ngọt ngào đầy cưng chiều, nhưng nhanh chóng cảm thấy ngột ngạt. Cô cố gắng thoát ra nhưng liên tục thất bại. Sau khi điều tra, cô phát hiện ra mọi thứ chỉ là một trò chơi yêu đương trong vũ trụ ảo do tổng tài công nghệ Lâm Mặc Thần tạo ra. Cả hai cùng bị mắc kẹt trong vòng lặp đó, vừa yêu vừa đối đầu, đồng thời dần khám phá ra một âm mưu lớn hơn – và cuối cùng cùng nhau tìm cách thoát khỏi thế giới ảo.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Sun Qianxun","avatar":""},{"name":"Yao Rui","avatar":""},{"name":"Zhang Yiqian","avatar":""},{"name":"Xie Yutong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Dong Xiao Jie Mei Tian Du Guo Qing Ren Jie","董小姐每天都过情人节"]', 1784690324151);
