INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dinh-menh-cua-sun', 'Định Mệnh Của Sun', 'Suntiny', 'https://phimimg.com/upload/vod/20250619-1/95952b962be18db20fb8b64ab891890b.jpg', 'https://phimimg.com/upload/vod/20250619-1/de29778db6d4d216179c2a212b569232.jpg', '<p>Sau một khoảng cách ngày càng lớn, Sun và Nuea tỉnh dậy trong cơ thể của nhau. Điều bắt đầu như một lời nguyền lại trở thành cơ hội để thấu hiểu – và có thể là kết nối lại với nhau.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Kornthas Rujeerattanavorapan","avatar":""},{"name":"Natasit Uareksit","avatar":""},{"name":"PP Phumipat Saelim","avatar":""},{"name":"Vivit Pharunrit Sarutsitphon","avatar":""},{"name":"Seoul Weeramethachai","avatar":""},{"name":"Piyangkull Saohin","avatar":""},{"name":"Wave Nuttapol Assawasereenond","avatar":""},{"name":"Pech Kritchanat Boonteeralert","avatar":""},{"name":"Katsamonnat Namwirote","avatar":""},{"name":"Talay Sanguandikul","avatar":""},{"name":"Peerawich P","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["หรือ…อลวนที่พรหมลิขิต"]', 1784690324151);
