INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-chien-thien-ha', 'Đấu Chiến Thiên Hạ', 'Fight For The Throne', 'https://phimimg.com/upload/vod/20250219-1/79688a5b194f4ed806ccc78986321d98.jpg', 'https://phimimg.com/upload/vod/20250219-1/664b9aec66e005d6d76b2aa104fc6404.jpg', '<p>Thiếu niên thần bí Đại Phong đã cứu Lý Họa Mi, người lâm trọng bệnh sau khi bị kẻ gian ám hại. Đại Phong dự định lên kinh đô tìm sư tỷ, tình cờ đồng hành cùng Lý Họa Mi. Trên đường đi, Lý Họa Mi kinh ngạc phát hiện sư tỷ của chàng chính là Nữ hoàng Tần Chiêu, người liên tục phái thích khách truy sát họ. Để làm rõ nguyên do, Đại Phong và Lý Họa Mi quyết định nương tựa lẫn nhau, cùng chung sức chống lại kẻ địch. Khi giang hồ dậy sóng, triều đình tranh đấu càng thêm khốc liệt. Hai người vô tình bị cuốn vào một âm mưu đầy toan tính và hiểm ác. Đại Phong chính là chìa khóa để giải mã tất cả những bí ẩn đó…</p>', 'Hoàn Tất (48/48)', 48, 'hoathinh', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Dou Zhan Tianxia","Dou Zhan Tian Xia","鬥戰天下","Fighting the World","Fight For The Throne","斗战天下"]', 1784690324151);
