INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sua-nong', 'Sữa Nóng', 'Hot Milk', 'https://phimimg.com/upload/vod/20250731-1/bc322f887cc75d8260a5ef4d65d13ab1.jpg', 'https://phimimg.com/upload/vod/20250731-1/2c5581984804a681487baa260189b927.jpg', '<p>Rose và con gái cô, Sofia, đến thị trấn ven biển Almería của Tây Ban Nha để gặp bác sĩ Gomez – một thầy lang có thể nắm giữ phương thuốc chữa căn bệnh bí ẩn khiến Rose phải ngồi xe lăn. Nhưng trong bầu không khí nồng nàn của thị trấn ngập nắng này, Sofia – người đã bị trói buộc suốt cuộc đời bởi căn bệnh của mẹ – cuối cùng bắt đầu thoát khỏi những rào cản của bản thân, bị cuốn hút bởi sức hấp dẫn lôi cuốn của nữ du khách bí ẩn tên Ingrid.</p>', 'Full', 1, 'single', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Emma Mackey","avatar":""},{"name":"Fiona Shaw","avatar":""},{"name":"Electra Sarri","avatar":""},{"name":"Yorgos Tsiantoulas","avatar":""},{"name":"Patsy Ferran","avatar":""},{"name":"Vincent Perez","avatar":""},{"name":"Elena Casablanca","avatar":""},{"name":"Nikos Kardonis","avatar":""},{"name":"Vasilis Tsigristaris","avatar":""},{"name":"Vicky Krieps","avatar":""},{"name":"Dimitris Oikonomidis","avatar":""},{"name":"Maria Vlachopoulou","avatar":""},{"name":"Yann Gael","avatar":""},{"name":"Paraskevi Argyriadou","avatar":""},{"name":"Paris Thomopoulos","avatar":""},{"name":"Va","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hot Milk"]', 1784690324151);
