INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truoc-khi-bo-tim-thay-chung-ta', 'Trước Khi Bố Tìm Thấy Chúng Ta', 'Before Your Father Finds Us', 'https://phimimg.com/upload/vod/20250731-1/df4301b2ddce0fa4c15098e1d221d248.jpg', 'https://phimimg.com/upload/vod/20250731-1/8b77bd8cdc91235dfda20e013aca1b7f.jpg', '<p>Sophia và cô con gái nhỏ Emily buộc phải tham gia chương trình bảo vệ nhân chứng sau khi cô phải ra làm chứng chống lại người chồng cũ – Mason – vì những tội ác của hắn. Sau nhiều năm sống một cuộc đời tưởng chừng như bình thường với bạn bè và các mối quan hệ mới, Sophia phát hiện Mason đã trốn thoát khỏi nhà tù an ninh tối đa. Biết rõ sức mạnh và mối quan hệ của hắn, Sophia buộc phải nói sự thật với cô con gái hiện đã là một thiếu niên về thân phận thật sự của cha mình – và một lần nữa phải từ bỏ tất cả để chạy trốn. Cùng nhau trốn đến một căn cabin hẻo lánh giữa rừng, Sophia và Emily phải làm mọi cách để sống sót trước Mason và ý đồ tàn nhẫn của hắn nhằm &quot;đoàn tụ&quot; gia đình bằng bất cứ giá nào.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Alexa PenaVega","avatar":""},{"name":"Tahmoh Penikett","avatar":""},{"name":"Jaeda Lily Miller","avatar":""},{"name":"Yobdee  Marazzi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Before Your Father Finds Us"]', 1784690324151);
