INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-ngoai-giao-2025', 'Nhà Ngoại Giao', 'The Diplomat', 'https://phimimg.com/upload/vod/20250731-1/e8ed1699895e681ccc0ed33e4e812e38.jpg', 'https://phimimg.com/upload/vod/20250731-1/21e776dfaf30380a4e89ce572362379e.jpg', '<p>Một nhà ngoại giao Ấn Độ xoay xở giữa những căng thẳng chính trị và đạo đức để giải cứu một cô gái trẻ tuyên bố bị ép cưới ở Pakistan. Dựa trên sự kiện có thật.</p>', 'Full', 1, 'single', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"John Abraham","avatar":""},{"name":"Sadia Khateeb","avatar":""},{"name":"Kumud Mishra","avatar":""},{"name":"Sharib Hashmi","avatar":""},{"name":"Ashwath Bhatt","avatar":""},{"name":"Ram Gopal Bajaj","avatar":""},{"name":"Vidhatri Bandi","avatar":""},{"name":"Jagjeet Sandhu","avatar":""},{"name":"Jeet Raidutt","avatar":""},{"name":"Bhawani Muzamil","avatar":""},{"name":"Revathi","avatar":""},{"name":"Suman Rana","avatar":""},{"name":"Amitoj Mann","avatar":""},{"name":"Darius Chinoy","avatar":""},{"name":"Farheen","avatar":""},{"name":"Vishal Vashishtha","avatar":""},{"name":"Manoj Dutt","avatar":""},{"name":"Shriswara","avatar":""},{"name":"Sh","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["राजनयिक"]', 1784690324151);
