INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kien-tuong', 'Kiện Tướng', 'Good Boy', 'https://phimimg.com/upload/vod/20250601-1/89524a3a031fbfa2f29eb7b81cff489f.jpg', 'https://phimimg.com/upload/vod/20250601-1/f3bbb466904489c0eb475f89bf6e3166.jpg', '<p>“Good Boy” kể về câu chuyện của Yoon Dong Joo (Park Bo Gum thủ vai), một cựu vận động viên quyền anh quốc gia từng giành huy chương vàng quốc tế, trở thành cảnh sát thông qua một chương trình tuyển dụng đặc biệt dành cho các vận động viên giành huy chương. Cuộc sống của cậu rẽ sang một hướng đầy kịch tính khi Min Joo Young (Oh Jung Se) - một nhân vật phản diện tàn nhẫn cai trị thành phố Inseong từ trong bóng tối - xuất hiện như kẻ thù cuối cùng. Với sự hiện diện nham hiểm và sự khinh thường luật pháp, trật tự, ngay cả hình bóng của hắn cũng khiến người ta rùng mình.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 9, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Bo-gum","avatar":""},{"name":"Kim So-hyun","avatar":""},{"name":"Oh Jung-se","avatar":""},{"name":"Lee Sang-yi","avatar":""},{"name":"Heo Sung-tae","avatar":""},{"name":"Tae Won-seok","avatar":""},{"name":"Seo Hyun-chul","avatar":""},{"name":"Jeong Man-sik","avatar":""},{"name":"Park Cheol-min","avatar":""},{"name":"Seo Jeong-yeon","avatar":""},{"name":"Seo Jae-hee","avatar":""},{"name":"Kang Gil-woo","avatar":""},{"name":"Choi Woo-jin","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184