INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuon-phim-cua-doi-ta', 'Cuốn Phim của Đôi Ta', 'Our Movie', 'https://phimimg.com/upload/vod/20250616-1/68b994a3a78781777aa56f467dc66b8a.jpg', 'https://phimimg.com/upload/vod/20250616-1/11b0185241bd407e409859459e0ef807.jpg', '<p>Our Movie là một bộ phim thuộc thể loại lãng mạn trầm buồn - melodrama, kể câu chuyện tình yêu ngọt ngào nhưng cũng bi thương của cặp đôi Lee Je Ha và Lee Da Eum. Lee Da Eum, một cô gái xinh đẹp, đam mê diễn xuất nhưng không may mắc căn bệnh hiểm nghèo. Dù thời gian sống còn lại chỉ tính bằng ngày, thế nhưng Lee Da Eum vẫn sống một cách mãnh liệt và can đảm hơn bất kỳ ai. Bất chấp số phận nghiệt ngã, cô luôn giữ tinh thần lạc quan, vui vẻ theo đuổi ước mơ, không ngừng hướng về ngày mai. Lee Da Eum gặp được Lee Je Ha (Nam Goong Min) khi anh đang đi tìm chất liệu cho dự án nghệ thuật mới của mình. Anh là một đạo diễn tài năng, từng được công nhận rộng rãi sau tác phẩm đầu tay nhưng chưa ra phim mới trong suốt 5 năm. Lee Je Ha muốn bộ phim thứ hai của mình kể về chuyện tình của một người không còn nhiều thời gian và Lee Da Eum trở thành đối tác hoàn hảo. Họ cùng nhau thực hiện bộ phim, đồng thời viết nên một câu chuyện tình yêu cho chính mình.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Namkoong Min","avatar":""},{"name":"Jeon Yeo-been","avatar":""},{"name":"Seo Hyun-woo","avatar":""},{"name":"Lee Sul","avatar":""},{"name":"Seo Yi-seo","avatar":""},{"name":"Jang Jae-ho","avatar":""},{"name":"Kwon Hae-hyo","avatar":""},{"name":"Seo Jeong-yeon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["我们的电影","فيلمنا","우리영화"]', 1784690324151);
