INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-di-ma-lay-chong-toi-ban-nhat', 'Cô Đi Mà Lấy Chồng Tôi (Bản Nhật)', 'Marry My Husband (Japan Version)', 'https://phimimg.com/upload/vod/20250705-1/fca915af3572f2f90114d8d9291378ed.jpg', 'https://phimimg.com/upload/vod/20250705-1/2747679502397282ef919328236f7bf9.jpg', '<p>Kanbe Misa luôn sống cuộc đời của “vai phụ”, lúc nào cũng đặt người khác lên trước bản thân. Cô dành trọn niềm tin vào chồng và cô bạn thân nhất, thế nhưng họ đáp lại Misa bằng sự phản bội cay nghiệt và cướp đi cả mạng sống của cô. Tưởng chừng mọi thứ đã kết thúc, Misa bất ngờ tỉnh dậy và nhận ra mình đã quay về quá khứ, trở lại mốc thời gian 10 năm trước. Lần này, cô không còn là người phụ nữ cam chịu như trước. Quyết tâm trả thù, Misa bắt đầu lên kế hoạch hủy hoại hai kẻ từng đâm sau lưng mình. Nhưng sự xuất hiện của cấp trên Suzuki Wataru - người mà cô chưa từng có mối liên hệ nào trong “kiếp trước” - lại khiến trái tim của Misa bắt đầu rung động. Ở cuộc đời thứ hai này, Misa không còn là vai phụ mà sẽ là nhân vật chính trong câu chuyện của chính mình, tự mình quyết định hạnh phúc.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 25, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Fuka Koshiba","avatar":""},{"name":"Takeru Satoh","avatar":""},{"name":"Sei Shiraishi","avatar":""},{"name":"You Yokoyama","avatar":""},{"name":"Tomoko Tabata","avatar":""},{"name":"Reina Kurosaki","avatar":""},{"name":"Ryuya Shimekake","avatar":""},{"name":"Kanji Tsuda","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["和我老公結婚吧","请和我的老公结婚","同我的丈夫结婚吧","和我老公结婚吧：日本版","Watashi no Otto to Kekkon Shite","내 남편과 결혼해줘","Marry My Husband","私の夫と結婚して"]', 1784690324151);
