INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-tieng-hao-mon', 'Tai Tiếng Hào Môn', 'Outrageous', 'https://phimimg.com/upload/vod/20250718-1/5cc168c05d74e6d58888a1ae644261c9.jpg', 'https://phimimg.com/upload/vod/20250718-1/06ad6bf126218acdcfbc29be8d060623.jpg', '<p>Dựa trên câu chuyện có thật về gia đình Mitford, bộ phim kể về sáu chị em gái nổi tiếng trong xã hội thượng lưu Anh quốc, những người đã thách thức chuẩn mực xã hội thời bấy giờ. Bối cảnh thập niên 1930 là sân khấu cho hàng loạt biến cố chấn động: từ phản bội, tai tiếng, đau khổ, đến tù đày.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Bessie Carter","avatar":""},{"name":"Zoe Brough","avatar":""},{"name":"Orla Hill","avatar":""},{"name":"Isobel Jesper Jones","avatar":""},{"name":"Joanna Vanderham","avatar":""},{"name":"James Purefoy","avatar":""},{"name":"Anna Chancellor","avatar":""},{"name":"Joshua Sasse","avatar":""},{"name":"Toby Regbo","avatar":""},{"name":"Jamie Blackley","avatar":""},{"name":"Calam Lynch","avatar":""},{"name":"Shannon Watson","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["蛮横六姐妹","Outrageous - Das Leben der Mitford-Schwestern","Outrageous"]', 1784690324151);
