INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tai-tieng-hao-mon', 'Tai Tiếng Hào Môn', 'Outrageous', 'tai tiếng hào môn outrageous bessie carter zoe brough orla hill isobel jesper jones joanna vanderham james purefoy anna chancellor joshua sasse toby regbo jamie blackley calam lynch shannon watson 蛮横六姐妹 outrageous - das leben der mitford-schwestern outrageous', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-hoa', 'Dã Hoả', 'Wild Fire', 'https://phimimg.com/upload/vod/20250725-1/042cdb0c2a96e4138d0b3f714f8fafcd.jpg', 'https://phimimg.com/upload/vod/20250725-1/95d41dec2d5de7e40d45f534adaef528.jpg', '<p>Giữa thời buổi loạn lạc, một công tử nhà giàu đem lòng yêu một ca nữ hèn kém. Bất chấp ranh giới địa vị, người đời rèm pha, người thân quay lưng, hai trái tim đầy vết thương vẫn thận trọng tiến lại gần nhau. Thành phố phồn hoa cũng chìm trong khói bụi, đứng trên sân khấu cao ba thước có thể nhìn thấy sơn hà rối ren. Dù khó khăn trập trùng, họ vẫn phải yêu nhau say đắm giữa thế giới hỗn loạn này.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hà Tuyên Lâm","avatar":""},{"name":"Cao Minh Thần","avatar":""},{"name":"Ngô Minh Tinh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["野火"]', 1784690324151);
