INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diu-dang-mau-nang', 'Dịu Dàng Màu Nắng', 'Gentle Sunlight', 'https://phimimg.com/upload/vod/20250608-1/2ee9512306a6f1894651ad00337e3dec.jpg', 'https://phimimg.com/upload/vod/20250608-1/8ae7ac92bdd0f747c9a0f520727605e1.jpg', '<p>Bộ phim không chỉ là câu chuyện về tình yêu và cuộc sống của mỗi cá nhân, mà còn là hành trình xây dựng hạnh phúc, vượt qua khó khăn và gắn kết giữa những con người xa lạ trong một xóm trọ công nhân. Ở đó, cuộc sống mưu sinh và những toan tính không làm con người ta quay lưng, lạnh nhạt với nhau, ngược lại, họ càng xích lại gần nhau và lan toả năng lượng tích cực, lòng tốt và niềm tin.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Duy Hưng","avatar":""},{"name":"Lương Thu Trang","avatar":""},{"name":"Nguyễn Ngọc Huyền","avatar":""},{"name":"B Trần","avatar":""},{"name":"Lan Hương","avatar":""},{"name":"Nguyệt Hằng","avatar":""},{"name":"Cù Thị Trà","avatar":""},{"name":"Mai Huê","avatar":""},{"name":"Lưu Duy Khánh","avatar":""},{"name":"Thái Dương","avatar":""},{"name":"Quốc Anh","avatar":""},{"name":"Bình An","avatar":""},{"name":"Phương Hạnh","avatar":""},{"name":"Đỗ Kỷ","avatar":""},{"name":"Bùi Minh Phương","avatar":""},{"name":"Thanh Hoa","avatar":""},{"name":"Minh Cúc","avatar":""},{"name":"Xuân Hồng","avatar":""},{"name":"Tuyết Trinh","avatar":""},{"name":"Khôi Nguyên","avatar":""},{"name":"Hoàng Huy","avatar":""},{"name":"Hồng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":