INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moc-sung-hay-moc-canh', 'Mọc Sừng Hay Mọc Cánh', 'Horns Or Wings', 'https://phimimg.com/upload/vod/20250728-1/381416fc4db21b0fadcfb35c0e95c0c1.jpg', 'https://phimimg.com/upload/vod/20250728-1/59a3954988bc1d70aa692b00ad7a3e7f.jpg', '<p>Bị người yêu phản bội, ép nghỉ việc, cô gái văn phòng uất ức trả đũa, vờ yêu thực tập sinh đẹp trai, nào ngờ anh &quot;hồng hài nhi&quot; này lại giúp cô từ nạn nhân bị cắm sừng, trở thành hổ mọc cánh.</p>', 'Hoàn Tất (31/31)', 31, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Đỗ Diễm","avatar":""},{"name":"Nhật Hào","avatar":""},{"name":"Mạnh Lân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324151);
