INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phuong-trinh-tinh-yeu', 'Phương Trình Tình Yêu', 'Love Formula', 'https://phimimg.com/upload/vod/20250717-1/8c29a52923da356b68bb9936931ac031.jpg', 'https://phimimg.com/upload/vod/20250717-1/4e32098d3fc13908e2452c6083d245fd.jpg', '<p>Cô gái thôn quê Giản Đan và thiên tài toán học Hàn Đàm Thánh gặp nhau ở trường đại học. Hàn Đàm Thánh vô tình mắc chứng rối loạn căng thẳng khi bơi. Với tấm lòng lương thiện, Giản Đan kiên trì đồng hành cùng anh, cuối cùng đã giúp anh vượt qua chướng ngại trong lòng. Được bạn bè ủng hộ, hai người đã cùng nhau trưởng thành, gặt hái được tình yêu và lòng dũng cảm.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 30, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tống Y Nhân","avatar":""},{"name":"Quách Tử Phàm","avatar":""},{"name":"Trương Gia Thạc","avatar":""},{"name":"Vương Lệ Na","avatar":""},{"name":"Lý Chi Phồn","avatar":""},{"name":"Đinh Nhiên","avatar":""},{"name":"Lâm Ngải Gia","avatar":""},{"name":"Đổng Tử Phàm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '["Ai De Fang Cheng Shi","亲爱的希帕蒂娅","Dear Miss Hypatia","爱的方程式"]', 1784690324151);
