INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phuong-trinh-tinh-yeu', 'Phương Trình Tình Yêu', 'Love Formula', 'phương trình tình yêu love formula tống y nhân quách tử phàm trương gia thạc vương lệ na lý chi phồn đinh nhiên lâm ngải gia đổng tử phàm ai de fang cheng shi 亲爱的希帕蒂娅 dear miss hypatia 爱的方程式', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-minh-huyen-an-giam-anh-thien', 'Đại Minh Huyền Án: Giám Ảnh Thiên', 'Mirrored Souls A Ming Dynasty Mystery', 'https://phimimg.com/upload/vod/20250725-1/b2d87bf81b7bb475db6e9f7da02f844e.jpg', 'https://phimimg.com/upload/vod/20250725-1/56f295bdb9dae52921b502c44151f12d.jpg', '<p>Thiếu niên hiệp khách Sở Bất Phàm lấy danh nghĩa hiệp nghĩa mà nổi danh giang hồ. Trên đường đến Thông Châu thăm bạn là Vương Tế An, anh chứng kiến Thạch Gia chết thảm tại tiệm rèn, từ đó bị cuốn vào hàng loạt vụ án kỳ bí. Qua những hành trình khám phá sự thật: Từ trái tim bị thù hận thiêu đốt của Doãn Thanh Mặc, khát vọng tự do của Lan Hinh, tranh đấu lạnh lẽo vì tiền tài của Triệu Nhược Đình, sự hy sinh cao cả của Tư Đồ Trầm Vân cho đến ánh sáng tình thân từ bảo vật “Khổng Tước Linh”, Sở Bất Phàm nhận ra rằng chỉ có tình yêu, trách nhiệm và thiện lương mới giúp con người vượt thoát khỏi bóng tối, tìm thấy ánh sáng và hy vọng.</p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chen Minghao","avatar":""},{"name":"Yu Zhihui","avatar":""},{"name":"Zeng Huaiyi","avatar":""},{"name":"An Long","avatar":""},{"name":"Bu Ziying","avatar":""},{"name":"Wang Leifang","avatar":""},{"name":"Yu Xiaodong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Da Ming Xuan An Lu Zhi Jian Ying Pian","大明悬案录之鉴影篇"]', 1784690324151);
