INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dai-minh-huyen-an-giam-anh-thien', 'Đại Minh Huyền Án: Giám Ảnh Thiên', 'Mirrored Souls A Ming Dynasty Mystery', 'đại minh huyền án: giám ảnh thiên mirrored souls a ming dynasty mystery chen minghao yu zhihui zeng huaiyi an long bu ziying wang leifang yu xiaodong da ming xuan an lu zhi jian ying pian 大明悬案录之鉴影篇', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trieu-tuyet-luc', 'Triều Tuyết Lục', 'Coroner''s Diary', 'https://phimimg.com/upload/vod/20250713-1/49c56c1f733ed8a328dc7984df495075.jpg', 'https://phimimg.com/upload/vod/20250713-1/464d72c09e1e3934b2bf37d7e6afdf4c.jpg', '<p>Bị nghi ngờ có liên quan đến một vụ án tham ô, cả nhà họ Thẩm phải chịu án tử, chỉ có Thẩm Hoản sống sót. Nàng trà trộn vào Tần gia, giả danh tiểu thư Tần Hoản, dùng khả năng y thuật tinh thông để cứu người và tham gia giải phẫu thi thể, giúp quan phủ phá án. Nhờ vậy mà Thẩm Hoản gặp gỡ Thế tử Yến Trì, người cũng đang tìm hiểu sự thật về vụ án khiến cả nhà nàng chết oan. Triều Tuyết Lục theo chân Thẩm Hoản và Yến Trì trong quá trình điều tra các vụ án ly kỳ và qua đó lần theo manh mối để phơi bày bí mật động trời trong hoàng cung.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 14, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Lan Địch","avatar":""},{"name":"Ngao Thụy Bằng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["权宠之仵作医妃","Zhao Xue Lu","บันทึกหิมะแห่งรุ่งอรุณ","The Powerful and Favored Coroner Imperial Concubine","Coroner’s Diary","朝雪录"]', 1784690324151);
