INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-cua-nu-chien-binh-duong-pho', 'Thế Giới Của Nữ Chiến Binh Đường Phố', 'World Of Street Woman Fighter', 'https://phimimg.com/upload/vod/20250529-1/5d81849c634c0044e71aedd796961259.jpg', 'https://phimimg.com/upload/vod/20250529-1/1a58ba0a4e2ab360b1e4eb7ed6d0496f.jpg', '<p>&quot;Thế chiến&quot; Street Woman Fighter chính thức bùng nổ với sự đối đầu của 6 đội quân siêu cường: OSAKA Ojo Gang và RHTokyo (Nhật), AG SQUAD (Úc), BUMSUP (Hàn Quốc), MOTIV (Mỹ) và ROYAL FAMILY (New Zealand). Nhà sản xuất huyền thoại J.Y. Park, biên đạo múa nổi tiếng thế giới Aliya Janell cùng vũ công Mike Song sẽ đảm nhận vai trò cầm cân nảy mực bên cạnh MC của chương trình là Sung Han Bin.</p>', 'Tập 9', 10, 'tvshows', 'ongoing', 10, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Mike Song","avatar":""},{"name":"J.Y. Park","avatar":""},{"name":"Aliya Janell","avatar":""},{"name":"Sung Han Bin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["월드 오브 스트릿 우먼 파이터"]', 1784690324151);
