INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('11-moi-tinh-truoc-em', '11 mối tình trước em', '11 Cinta Sebelum Kamu', 'https://phimimg.com/upload/vod/20250727-1/f73a5cb31fd338f3cdbb9ac69186e8cf.jpg', 'https://phimimg.com/upload/vod/20250727-1/922f3aa3f52e002d7bbe6ac63c5831f3.jpg', '<p>Để cưới được vị hôn thê, Ray phải thực hiện một nhiệm vụ gần như bất khả thi nhằm được mẹ vợ chấp thuận: xin lỗi toàn bộ 11 người yêu cũ trong quá khứ trăng hoa của anh.</p>', 'Full', 1, 'single', 'completed', 22, 2025, 'Vietsub', 'FHD', 'Quốc Gia Khác', 0, '[{"name":"Fattah Amin","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["11 Cinta Sebelum Kamu"]', 1784690324151);
