INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-hanh-phuc-bi-choi-tu', 'Khi Hạnh Phúc Bị Chối Từ', 'Denied Love (Uncut Ver.)', 'https://phimimg.com/upload/vod/20250717-1/61a1c923f9909b40f4a48c27492bba0f.jpg', 'https://phimimg.com/upload/vod/20250717-1/445589db8fae82e63c892db512c493a5.jpg', '<p>Đây là một câu chuyện về một tình yêu bị từ chối trong bối cảnh năm 2025, khi con người đối diện với những thách thức mới từ công nghệ, xã hội, và cảm xúc. Câu chuyện xoay quanh nhân vật chính, người đã đặt tất cả hy vọng vào tình yêu nhưng lại phải đối mặt với sự từ chối của người mình yêu. Cùng với sự phát triển của xã hội hiện đại, những giá trị truyền thống về tình yêu, sự hy sinh, và niềm tin đang bị thử thách. Liệu nhân vật chính có thể vượt qua nỗi đau và tìm lại sự bình yên trong cuộc sống? Cảm xúc trong câu chuyện là sự giằng xé giữa niềm hy vọng và thực tế phũ phàng. Mỗi quyết định và sự thay đổi trong cuộc sống đều ảnh hưởng sâu sắc đến hành trình của tình yêu này. Câu chuyện này không chỉ là về tình yêu mà còn là hành trình trưởng thành và khám phá bản thân trong một thế giới đầy biến động.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 18, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Thidarut Pruethong","avatar":""},{"name":"Natthamon Jantraviphart","avatar":""},{"name":"Teeratee Buddeehong","avatar":""},{"name":"Elisha Triwiwatkul","avatar":""},{"name":"Praptpadol Suwanbang","avatar":""},{"name":"Kewalin Wetkama","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["รินไม่มีวันรัก"]', 1784690324151);
