INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('knock-out', 'Knock Out', 'Knock Out', 'https://phimimg.com/upload/vod/20250517-1/af35cee6d00946bc89af16ce06957e06.jpg', 'https://phimimg.com/upload/vod/20250517-1/1ef0aa912dcaf60d79bcceb1bf7716c3.jpg', '<p>Keen phát hiện ra bố mình vẫn đang gánh một khoản nợ khổng lồ, trong khi bản thân anh cũng không có cách nào xoay xở để trả món nợ của chính mình. Sau đó Keen tình cờ gặp Thun, một võ sĩ quyền anh có biệt danh là “Đại Bác”. Mối quan hệ giữa hai người dần trở nên thân thiết và cuối cùng phát triển thành một tình yêu đẹp, giúp họ cùng nhau vượt qua khó khăn và giải quyết được vấn đề nợ nần của Keen. Thế nhưng trong lúc không hay biết, họ lại bị cuốn vào thế giới quyền anh của thế lực đen tối, dẫn đến rắc rối lớn sau này.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Natsakan Chairote","avatar":""},{"name":"Boripat Jamsat","avatar":""},{"name":"Thanakrit Talasopon","avatar":""},{"name":"Kantapon Chompupan","avatar":""},{"name":"Narongdet Rungarun","avatar":""},{"name":"Wi Wiset","avatar":""},{"name":"Jakarin Puribhat","avatar":""},{"name":"Rawipa Srisanguan","avatar":""},{"name":"Ploiyukhon Rojanakatanyoo","avatar":""},{"name":"Samart Payakaroon","avatar":""},{"name":"Napassakorn Mitiam","avatar":""},{"name":"Malys Choeysobhon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["一拳锁心","击拳锁心","一拳定爱","拳爱锁心","Knock out","擂臺戀人","หมัดน็อกล็อกหัวใจ"]', 1784690324151);
