INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('knock-out', 'Knock Out', 'Knock Out', 'knock out knock out natsakan chairote boripat jamsat thanakrit talasopon kantapon chompupan narongdet rungarun wi wiset jakarin puribhat rawipa srisanguan ploiyukhon rojanakatanyoo samart payakaroon napassakorn mitiam malys choeysobhon 一拳锁心 击拳锁心 一拳定爱 拳爱锁心 knock out 擂臺戀人 หมัดน็อกล็อกหัวใจ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-chong-ma-tuy', 'Cuộc Chiến Chống Ma Tuý', 'The Narcotic Operation', 'https://phimimg.com/upload/vod/20250714-1/582b8bbe731ee6fd26b914c086a65e6e.jpg', 'https://phimimg.com/upload/vod/20250714-1/fde549fd27081213de2b6c8cb9b1c38a.jpg', '<p>Năm 1995, một tay buôn lậu tên là Lô Thiếu Hoa đã mất hết tất cả tài sản trong một đêm. Tuy nhiên, nhờ đó hắn nhận ra lợi nhuận khổng lồ mà một loại ma túy mới – ma túy đá – có thể mang lại. Từ đó, lòng tham trỗi dậy và hắn quyết định trở thành một kẻ sản xuất ma túy. Cùng thời điểm đó, cảnh sát phòng chống ma túy Lâm Cường Phong kết thúc nhiệm vụ nằm vùng của mình. Để tiếp tục truy lùng manh mối về đường dây ma túy, anh được điều động đến đội phòng chống ma túy của thành phố Tây Cảng. Trong nhiều năm sau đó, Lâm Cường Phong đã dẫn dắt đội của mình dấn thân vào cơn bão quét sạch ma túy này. Trong khi đó, Lô Thiếu Hoa thì ngược xuôi trong và ngoài nước, kết giao với một loạt trùm ma túy khét tiếng, tham vọng của hắn ngày càng lớn... Cuối cùng, Lâm Cường Phong, người đại diện cho đội cảnh sát phòng chống ma túy đã không phụ sứ mệnh, dốc toàn lực để phá tan âm mưu và mạng lưới ma túy quỷ quyệt của Lô Thiếu Hoa.</p>', 'Hoàn Tất (33/33)', 33, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đoạn Dịch Hoành","avatar":""},{"name":"Tần Hạo","avatar":""},{"name":"Vu Văn Văn","avatar":""},{"name":"Ngô Hạnh Kiện","avatar":""},{"name":"Lưu Hoan","avatar":""},{"name":"Hầu Nham Tùng","avatar":""},{"name":"Lý Đông Hằng","avatar":""},{"name":"Trương Thế","avatar":""},{"name":"Hồ Minh","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["THE NARCOTIC OPERATION","War on Drug","扫毒风暴"]', 1784690324151);
