INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-trai-ut-nha-tuong-quan', 'Con Trai Út Nhà Tướng Quân', 'Returned Master', 'https://phimimg.com/upload/vod/20250718-1/38c90e40a7ff349c60bc90d210f06fd5.jpg', 'https://phimimg.com/upload/vod/20250718-1/fb81d3920343bd124994aa1d051805a7.jpg', '<p>Cả nhà Lý tướng quân cáo lão về quê bị người thần bí giết chết cả nhà vào đêm giao thừa. Con trai út Lý gia là Lý Kiến Vi thoát chết, mai danh ẩn tích ở Quỷ Cốc tính toán kế hoạch trả thù cho cả nhà. Trần Tiểu Hi - thiếu chủ Quỷ Cốc tính cách hoạt bát, ương bướng, hao tổn không ít tâm sức để ngày một thân thiết với Lý Kiến Vi hơn. Khi mọi thứ đều đang tiến triển theo kế hoạch của Lý Kiến Vi, hắn phát hiện đằng sau chuyện này là những bí mật đan xen. Kẻ thù thật sự là binh lính trung thành đã vào rừng làm cướp từ 20 năm trước, danh vọng công thần của Lý gia đã không còn trong sạch. Người trung thành - kẻ gian ác, cái thiện - cái ác đan xen lẫn nhau, khi chân tướng 20 năm trước dần lộ ra, khi thân phận thật sự của Lý Kiến Vi và Trần Tiểu Hi bị vạch trần, hai chàng thiếu niên phải giải quyết thế nào đây? Phải gánh vác cuộc đời bản thân thế nào đây...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đổng Tử Phàm","avatar":""},{"name":"Lý Giai Văn","avatar":""},{"name":"Quan Dục Tịch","avatar":""},{"name":"Đổng Tiểu Bạch","avatar":""},{"name":"Tiết Dực","avatar":""},{"name":"Ngạo Lôi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jiang Jun Jia De Xiao Er Zi","장군가적소아자 : 장군댁 막내아들","將軍家的小兒子","The General''s Son","The General''s Youngest Son","将军家的小儿子"]', 1784690324151);
