INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gilmore-tay-golf-cu-khoi-2', 'Gilmore Tay Golf Cừ Khôi 2', 'Happy Gilmore 2', 'https://phimimg.com/upload/vod/20250725-1/9191c867a93f4e36c6504498ffabd302.jpg', 'https://phimimg.com/upload/vod/20250725-1/d6d8c8d718461c08c77d510c93ec69b3.jpg', '<p>Được các con cổ vũ, huyền thoại làng golf được yêu mến của Adam Sandler tái xuất sân cỏ, một lần nữa vung gậy để chạm tới vinh quang. Chỉ cần nhớ: nằm hết ở cái hông.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Adam Sandler","avatar":""},{"name":"Sunny Sandler","avatar":""},{"name":"Julie Bowen","avatar":""},{"name":"Christopher McDonald","avatar":""},{"name":"Ben Stiller","avatar":""},{"name":"Benny Safdie","avatar":""},{"name":"Bad Bunny","avatar":""},{"name":"Travis Kelce","avatar":""},{"name":"Margaret Qualley","avatar":""},{"name":"Haley Joel Osment","avatar":""},{"name":"Eric André","avatar":""},{"name":"Conor Sherry","avatar":""},{"name":"Ethan Cutkosky","avatar":""},{"name":"Maxwell Jacob Friedman","avatar":""},{"name":"Philip Fine Schneider","avatar":""},{"name":"Rory McIlroy","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chàng Happy Gilmore 2","Happy Gilmore 2"]', 1784690324151);
