INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sunday-best-chuyen-chua-ke-cua-ed-sullivan', 'Sunday Best: Chuyện Chưa Kể Của Ed Sullivan', 'Sunday Best: The Untold Story Of Ed Sullivan', 'https://phimimg.com/upload/vod/20250725-1/6310fda18688aac98b7488867edd8f0a.jpg', 'https://phimimg.com/upload/vod/20250725-1/eb63f89ab5bf16dd5928e75b7be64b83.jpg', '<p>Ed Sullivan phá vỡ rào cản khi mời nghệ sĩ da đen đến chương trình tạp kỹ tối Chủ Nhật. Phim tài liệu này tôn vinh di sản thúc đẩy bình đẳng của người tiên phong ngành truyền hình.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Smokey Robinson","avatar":""},{"name":"Berry Gordy","avatar":""},{"name":"Harry Belafonte","avatar":""},{"name":"Dionne Warwick","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '[]', 1784690324151);
