INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lilim', 'Lilim', 'Lilim', 'https://phimimg.com/upload/vod/20250725-1/85ba067bf62d1005c33927df91867f02.jpg', 'https://phimimg.com/upload/vod/20250725-1/e57ba83aa28dd00da97ca448bf04c483.jpg', '<p>Bị pháp luật truy lùng vì tội giết cha, một cô gái trẻ cùng em chạy trốn đến một trại trẻ mồ côi hẻo lánh – nhưng rồi phát hiện những bí mật kinh hoàng ở đó.</p>', 'Full', 1, 'single', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Heaven Peralejo","avatar":""},{"name":"Eula Valdez","avatar":""},{"name":"Ryza Cenon","avatar":""},{"name":"Skywalker David","avatar":""},{"name":"Mon Confiado","avatar":""},{"name":"Rafa Siguion-Reyna","avatar":""},{"name":"Nicole Omillo","avatar":""},{"name":"Phoebe Walker","avatar":""},{"name":"Gold Aceron","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Lilim"]', 1784690324151);
