INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-son-kinh-hon', 'Hoang Sơn Kinh Hồn', 'Wilderness Fright (Abandoned Mountain Soul-Chilling)', 'https://phimimg.com/upload/vod/20250725-1/76e075ebbaa456951f43b6dd584008ee.jpg', 'https://phimimg.com/upload/vod/20250725-1/544c1861c431141b69ba1ef34bf8c3b5.jpg', '<p>Phim kể về câu chuyện của chị gái Quách Gia vì lý do bất đắc dĩ phải đưa em gái lái xe lên đường giữa đêm khuya. Trên đường đi qua vùng núi hoang vắng, hai chị em gặp phải hàng loạt những mối đe dọa chết chóc kỳ dị, thật giả khó phân. Câu chuyện là sự đan xen và giằng xé giữa bản tính con người và bản năng thú tính, tạo nên một hành trình ly kỳ với những nút thắt bất ngờ và tầng nghĩa sâu sắc.</p>', 'Full', 1, 'single', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"石凯仁","avatar":""},{"name":"张星涵","avatar":""},{"name":"Andy Wu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["荒山惊魂"]', 1784690324151);
