INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-nhan-kiet-me-an-thong-thien', 'Địch Nhân Kiệt: Mê Án Thông Thiên', 'Detective Dee: The Celestial Mystery', 'https://phimimg.com/upload/vod/20250725-1/4b6b07a3b89fa3a88525967c9b090b8b.jpg', 'https://phimimg.com/upload/vod/20250725-1/e796848b1fc850943da4bc00703f02df.jpg', '<p>Thời Võ Chu, tại thành Dương Châu bỗng xảy ra một loạt án mạng kỳ dị. Bảy thi thể chết thảm bị vặn xoắn thành tư thế chuộc tội khiến Địch Nhân Kiệt cảm nhận áp lực chưa từng có. Sự thật như đang ẩn náu trong từng mạch máu ấm nóng của các nạn nhân hiến tế. Trời đất xoay vần, một vụ án cũ bị vùi lấp suốt nhiều năm bất ngờ bị đào lại. Mạng lưới trừng phạt được dàn dựng tinh vi ấy lại chính là chiếc bóng phản chiếu từ một quá khứ cấm kỵ cổ xưa…</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Han Dong","avatar":""},{"name":"Luo Liqun","avatar":""},{"name":"Shen Zhiyi","avatar":""},{"name":"Tan Limin","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Detective Dee und das Geheimnis des Himmels","狄仁杰之通天谜案"]', 1784690324151);
