INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('goc-bep-ky-tai-phan-4', 'Góc Bếp Kỳ Tài (Phần 4)', 'The Bear (Season 4)', 'https://phimimg.com/upload/vod/20250704-1/a02fcc3134778b8955666a8b4661c9b3.jpg', 'https://phimimg.com/upload/vod/20250704-1/7c5f01873001239b27ce9656027fa45d.jpg', '<p>Carmen “Carmy” Berzatto, một đầu bếp trẻ đến từ thế giới ẩm thực cao cấp, trở về nhà ở Chicago để điều hành cửa hàng bánh sandwich của gia đình sau cái chết đau lòng. Khi Carmy chiến đấu để biến đổi nhà hàng và chính bản thân mình, cuối cùng đội ngũ bếp thô lỗ của anh ấy cũng tiết lộ họ là gia đình mà anh ấy đã chọn.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jeremy Allen White","avatar":""},{"name":"Ebon Moss-Bachrach","avatar":""},{"name":"Ayo Edebiri","avatar":""},{"name":"Lionel Boyce","avatar":""},{"name":"Abby Elliott","avatar":""},{"name":"Matty Matheson","avatar":""},{"name":"Liza Colón-Zayas","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["熊家餐馆","Medvěd","The Bear : Sur place ou à emporter","El Oso (The Bear)","Misiek","Medveď","大熊餐館","Bear","FX''s The Bear","Kubelik","Windy City Law","The Bear"]', 1784690324151);
