INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-dao-phong-nguyet', 'Nhất Đao Phong Nguyệt', 'The Blade Of Romance', 'https://phimimg.com/upload/vod/20250722-1/ae829f63765e40e6917823461f6cfecf.jpg', 'https://phimimg.com/upload/vod/20250722-1/570adfef970a31fd5382f09f290ba68e.jpg', '<p>Tống Vi Vi là con gái của đại tướng số một nước Trần. Vì muốn báo thù cho cha và rửa mối hận mất nước, cô cải trang thành Ôn Nhu - em gái được sủng ái nhất của hoàng tử Ôn Tri Uyên nước Lương, chỉ để tiếp cận và trả thù hắn. Thế nhưng trong quá trình ở bên nhau, cô dần chiếm được lòng tin của Ôn Tri Uyên, thậm chí khiến hắn thật lòng yêu cô. Với sự trợ giúp của Ôn Tri Bạch - người đang tranh đoạt ngôi vị với Ôn Tri Uyên, nàng từng bước phá vỡ toàn bộ thế cục do Ôn Tri Uyên sắp đặt, cuối cùng thành công ngăn chặn con đường xưng đế của hắn và tự tay báo thù cho cha mình. Thế nhưng, chính lúc đó nàng mới nhận ra Ôn Tri Uyên thực sự đã yêu nàng chân thành, còn &quot;bạch nguyệt quang&quot; trong lòng nàng thì vẫn luôn âm thầm bảo vệ nàng từ đầu đến cuối…</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Thường Ninh","avatar":""},{"name":"Đặng Siêu Nguyên","avatar":""},{"name":"Lê Minh Húc","avatar":""},{"name":"Thượng Toán","avatar":""},{"name":"Dương Hạc Lân","avatar":""},{"name":"Mã Diễm Đình","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yi Dao Feng Yue","一刀风月"]', 1784690324151);
