INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-cam-do-nong-bong-y', 'Sự Cám Dỗ Nóng Bỏng: Ý', 'Too Hot To Handle: Italy', 'https://phimimg.com/upload/vod/20250724-1/00da7c0f267f21365abfe856391c2b53.jpg', 'https://phimimg.com/upload/vod/20250724-1/82d2b11d841ebd2bf3121bc518a61dc2.jpg', '<p>Một nhóm những người độc thân quyến rũ tụ hội tại thiên đường, nhưng để giành được giải thưởng tiền mặt, có một điều kiện: không được quan hệ tình dục. Liệu họ có thể cưỡng lại sự cám dỗ hay để cho ham muốn chi phối?</p>', 'Hoàn Tất (8/8)', 8, 'tvshows', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Federico Palana","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Too Hot to Handle: Italia"]', 1784690324151);
