INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguy-cap-lan-ranh-sinh-mang', 'Nguy Cấp: Lằn Ranh Sinh Mạng', 'Critical: Between Life And Death', 'https://phimimg.com/upload/vod/20250724-1/f1794d8bb70b59834b7343efd6e62a02.jpg', 'https://phimimg.com/upload/vod/20250724-1/75350b9e2c7feb480fd40271bb8f3a7c.jpg', '<p>Từ ca cấp cứu nguy kịch đến phòng phẫu thuật, loạt phim tài liệu này theo chân các trung tâm điều trị chấn thương của London khi họ cứu chữa những bệnh nhân bị thương nặng nhất.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Estado Crítico: Vida ou Morte","命悬一线：伦敦重症急救实录","Wenn jede Sekunde zählt: Londons Trauma-Netzwerk","Estado Crítico: Entre la vida y la muerte","État critique: Entre la vie et la mort","Critical","Kritikus pillanatok: Élet és halál között","Critical: Codice rosso","Londons akuttjeneste: Liv eller død","Urgências: Vida ou Morte","Critical: Between Life and Death"]', 1784690324151);
