INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguy-cap-lan-ranh-sinh-mang', 'Nguy Cấp: Lằn Ranh Sinh Mạng', 'Critical: Between Life And Death', 'nguy cấp: lằn ranh sinh mạng critical: between life and death  estado crítico: vida ou morte 命悬一线：伦敦重症急救实录 wenn jede sekunde zählt: londons trauma-netzwerk estado crítico: entre la vida y la muerte état critique: entre la vie et la mort critical kritikus pillanatok: élet és halál között critical: codice rosso londons akuttjeneste: liv eller død urgências: vida ou morte critical: between life and death', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-tuoi-dep-cuoc-doi-tuoi-dep', 'Cuộc Sống Tươi Đẹp (Cuộc Đời Tươi Đẹp)', 'A Better Life', 'https://phimimg.com/upload/vod/20250419-1/f912e6b5f01453786b07607bbaef857f.jpg', 'https://phimimg.com/upload/vod/20250419-1/3cc1f28530d776577c5752aee3ce55ae.jpg', '<p>Bộ phim kể về cuộc đời của Tống Giai Ninh, một người phụ nữ bình thường sống trong thời đại đầy biến động. Từ những năm tháng tuổi trẻ nhiệt huyết cho đến khi trưởng thành và đối mặt với bao thăng trầm cuộc sống, cô luôn giữ vững niềm tin, sự lương thiện và lòng kiên định với lựa chọn của mình. Trong hành trình ấy, Giai Ninh từng trải qua tình yêu tan vỡ, áp lực công việc, gia đình rạn nứt và cả những mất mát sâu sắc. Nhưng nhờ nghị lực phi thường, cô không ngừng vươn lên, tạo dựng được sự nghiệp, hàn gắn tình thân và cuối cùng tìm lại được chính mình. Phim không chỉ là câu chuyện của một người phụ nữ mà còn là bức tranh chân thực về cuộc sống, tình cảm gia đình, tình bạn và giá trị kiên cường giữa xã hội hiện đại. &quot;Một Cuộc Đời Tuyệt Vời&quot; truyền tải thông điệp sâu sắc: Dù đời có bao nhiêu thử thách, chỉ cần giữ được bản thân tử tế và không ngừng cố gắng, chúng ta vẫn có thể sống một cuộc đời thật đẹp.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 9, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tôn Lệ","avatar":""},{"name":"Đổng Tử Kiện","avatar":""},{"name":"Hồ Hạnh Nhi","avatar":""},{"name":"Cao Tân","avatar":""},{"name":"Đồng Lôi","avatar":""},{"name":"Diệp Thanh","avatar":""},{"name":"Khang Ninh","avatar":""},{"name":"Từ Uy La","avatar":""},{"name":"Trần Thiên Minh","avatar":""},{"name":"Lưu Quân","avatar":""},{"name":"Trương Thần Quang","avatar":""},{"name":"Triệu Long Hạo","avatar":""},{"name":"Ô Quân Mai","avatar":""},{"name":"Phùng Lôi","avatar":""},{"name":"Chu Dã Mang","avatar":""},{"name":"Ngô Ngọc Phương","avatar":""},{"name":"Phạm Thế Kỳ","avatar":""},{"name":"Khúc Triết Minh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["保险人生","三十九二十八","蠻好的人生","Man Hao De Ren Sheng","保險人生","Bao Xian Ren Sheng","San Shi Jiu Er Shi Ba","A Better Life","蛮好的人生"]', 1784690324151);
