INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-song-tuoi-dep-cuoc-doi-tuoi-dep', 'Cuộc Sống Tươi Đẹp (Cuộc Đời Tươi Đẹp)', 'A Better Life', 'cuộc sống tươi đẹp (cuộc đời tươi đẹp) a better life tôn lệ đổng tử kiện hồ hạnh nhi cao tân đồng lôi diệp thanh khang ninh từ uy la trần thiên minh lưu quân trương thần quang triệu long hạo ô quân mai phùng lôi chu dã mang ngô ngọc phương phạm thế kỳ khúc triết minh 保险人生 三十九二十八 蠻好的人生 man hao de ren sheng 保險人生 bao xian ren sheng san shi jiu er shi ba a better life 蛮好的人生', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kapil-sharma-hai-kich-sieu-an-do-phan-3', 'Kapil Sharma: Hài Kịch Siêu Ấn Độ (Phần 3)', 'The Great Indian Kapil Show (Season 3)', 'https://phimimg.com/upload/vod/20250627-1/df9f853b92179f9348e6782ce589feff.jpg', 'https://phimimg.com/upload/vod/20250627-1/92a2f4403a7f2288d8342d0d0c667368.jpg', '<p>Danh hài Kapil Sharma dẫn dắt một chương trình hài tổng hợp, nơi anh phỏng vấn các khách mời nổi tiếng (diễn viên, ca sĩ, vận động viên...), xen lẫn là các tiểu phẩm vui nhộn cùng dàn diễn viên phụ quen thuộc như Sunil Grover, Kiku Sharda, Bharti Singh...</p>', 'Tập 5', 13, 'tvshows', 'ongoing', 18, 2025, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Kapil Sharma","avatar":""},{"name":"Sunil Grover","avatar":""},{"name":"Krishna Abhishek","avatar":""},{"name":"Archana Puran Singh","avatar":""},{"name":"Kiku Sharda","avatar":""},{"name":"Navjot Singh Sidhu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["द ग्रेट इंडियन कपिल शो"]', 1784690324151);
