INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-mua-sam-online-cua-ong-chu-u40-o-di-gioi', 'Cuộc Sống Mua Sắm Online Của Ông Chú U40 Ở Dị Giới', 'The Daily Life Of A Middle-Aged Online Shopper In Another World', 'https://phimimg.com/upload/vod/20250307-1/9ca7c37e8ce44a917c82c0dae5fd9c06.jpg', 'https://phimimg.com/upload/vod/20250307-1/d8de349f22b12b1f1a03b51da283c1f7.jpg', '<p>Kenichi, một người đàn ông độc thân gần 40 tuổi, đột nhiên bị chuyển đến một thế giới khác. Khi tìm đường xuyên qua những khu rừng nguy hiểm của thế giới đó, anh nhận ra rằng mình có thể sử dụng một trang mua sắm trực tuyến khổng lồ. Kenichi muốn sử dụng khả năng gian lận của mình để sống một cuộc sống chậm rãi ở một thế giới khác!</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Junichi Suwabe","avatar":""},{"name":"Misaki Kuno","avatar":""},{"name":"Miyu Tomita","avatar":""},{"name":"Yu Kobayashi","avatar":""},{"name":"Kaede Hondo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["中年男的异世界网购生活","The Daily Life of a Middle-Aged Online Shopper in Another World","Arafo Otoko No Isekai Tsuhan Seikatsu","Around 40 Otoko no Isekai Tsuuhan","Arafou Otoko no Isekai Tsuuhan","Arafou Otoko no Isekai Tsuuhan Seikatsu","사십 줄 남자의 이세계 통판","아라포 남자의 이세계 통판","Online Shopper in Another World","The Mail Order Life of a Man Around 40 in Another World","アラフォー男の異世界通販"]', 1784690324151);
