INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-bao-ve-chan-ly', 'Người Bảo Vệ Chân Lý', 'Homeland Guardian', 'https://phimimg.com/upload/vod/20250704-1/ee6b8175fe9d32ff2f060ad12ea05c75.jpg', 'https://phimimg.com/upload/vod/20250704-1/79de88e35a95e125af79df700d9daca2.jpg', '<p>Lấy cảm hứng từ các vụ án có thật, Người Bảo Vệ Chân Lý xoay quanh hành trình bảo vệ quê hương của cảnh sát ưu tú Hà Hạo Huy thuộc lực lượng cảnh sát Hồng Kông. Sau một nhiệm vụ thất bại, Hà Hạo Huy bị thuyên chuyển về bộ phận mới và gặp gỡ hai đồng đội trẻ Thiệu Tử Tuấn và Triệu Thiệu Đường. Kể từ đó, ba người luôn sát cánh bên nhau từng bước triệt phá âm mưu phá hoại của các thế lực ngoại bang.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2025, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Tiểu Xuân","avatar":""},{"name":"Lý Trị Đình","avatar":""},{"name":"Hàn Tuyết","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["守城者","守誠者","Homeland Guardian","守诚者"]', 1784690324151);
