INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lazarus', 'Lazarus', 'Lazarus', 'https://phimimg.com/upload/vod/20250413-1/41d96e69a3f3676b7df3b29af3f94fe9.jpg', 'https://phimimg.com/upload/vod/20250413-1/c1c13e67951f976493e0f4d0bcef8721.jpg', '<p>Vào năm 2052, một nhà thần kinh học từng đoạt giải Nobel đã phát triển một loại thuốc mang tên Hapuna — một phương thuốc chữa bách bệnh, nhưng lại có tác dụng phụ không ngờ: gây tử vong sau ba năm sử dụng. Trước mối đe dọa này, một lực lượng đặc nhiệm đặc biệt — có biệt danh là &quot;Lazarus&quot; — đã được thành lập để đối đầu với kẻ phản diện mang tên Skinner.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Mamoru Miyano","avatar":""},{"name":"Makoto Furukawa","avatar":""},{"name":"Maaya Uchida","avatar":""},{"name":"Yuma Uchida","avatar":""},{"name":"Manaka Iwami","avatar":""},{"name":"Megumi Hayashibara","avatar":""},{"name":"Koichi Yamadera","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["LAZARUS Razaro","ラザロ","Lazarus"]', 1784690324151);
