INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kham-thien-ky-dam', 'Khâm Thiên Kỳ Đàm', 'Heavenly Secrets Bureau', 'https://phimimg.com/upload/vod/20250710-1/ee5ba1082e41082f2e83c9adc8ce110e.jpg', 'https://phimimg.com/upload/vod/20250710-1/e8c17c8c20fc379e249f7e611c705c2a.jpg', '<p>Con trai của tội thần Khâm Thiên giám, lần theo manh mối từ ghi chép do phụ thân để lại, cùng Cửu Công Chúa tinh thông y đạo hợp lực phá án. Họ lần lượt bóc trần những kỳ án liên quan đến bí thuật cổ xưa: vu cổ tác loạn, Lôi Công hiển linh, trời long đất lở... Mỗi bước đi càng đưa họ tiến gần đến một chân tướng chấn động – tất cả đều dẫn về lời tiên tri trong Thiên Thư thần bí: &quot;Song Ngư họa quốc&quot;.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Hạo Hiên","avatar":""},{"name":"Mã Thu Nguyên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Qin Tian Qi Tan","钦天奇谭"]', 1784690324151);
