INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-tu-phuong-hoa-2025', 'Cẩm Tú Phương Hoa', 'In The Name Of Blossom', 'https://phimimg.com/upload/vod/20250630-1/863168f61424453fe79f3267a1441b41.jpg', 'https://phimimg.com/upload/vod/20250630-1/a3eff7c50f230917754487368c7f0905.jpg', '<p>Tiếp nối phần đầu Quốc Sắc Phương Hoa, Cẩm Tú Phương Hoa theo chân nữ thương nhân trồng hoa mẫu đơn Hà Duy Phương trong một bước ngoặt lớn của sự nghiệp lẫn cuộc đời. Cơ ngơi do cô vất vả xây dựng từ bàn tay trắng nay đã đứng vững, còn tài trồng hoa của cô thì càng ngày càng được nhiều người biết đến. Thế nhưng, ngay khi vừa chạm tay vào giấc mơ giàu có, một biến cố lớn lại xảy ra khiến cô quyết định rẽ sang con đường mới để mang đến lợi ích lớn lao hơn cho dân chúng và đồng thời tiếp tục bí mật giúp đỡ Tưởng Trường Dương chống lại âm mưu phản loạn của Ninh Vương.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Tử","avatar":""},{"name":"Lý Hiện","avatar":""},{"name":"Ngụy Triết Minh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["锦绣芳华","국색방화","금수방화","錦繡芳華","Flourished Peony","In The Name of Blossom","国色芳华"]', 1784690324151);
