INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-thay-doi-tu-menh', 'Ngày Thay Đổi Tử Mệnh', 'Leap Day', 'https://phimimg.com/upload/vod/20250403-1/c982ec6ef49bcf7891d94c97ffffad20.jpg', 'https://phimimg.com/upload/vod/20250403-1/9a2162b43e3665449395cea1b8fe6087.jpg', '<p>Sinh ra vào ngày và đêm của ngày 29 tháng 2, Day và Night đều bị nguyền rủa bởi một lời nguyền khủng khiếp: cứ mỗi bốn năm, họ sẽ mất đi người mà họ yêu thương nhất. Nỗi sợ hãi về lời nguyền khiến họ phải sống cô lập, tránh xa mọi người. Cho đến một ngày, Night gặp Dream, cô gái trở thành niềm vui và ánh sáng trong cuộc đời anh. Trong khi đó, Day lại phải chăm sóc Ozone, cậu bé tự kỷ – con trai của một người họ hàng xa sau khi cô ấy qua đời. Khi sinh nhật lần thứ hai mươi đến gần, nỗi lo sợ mất đi người thân yêu lại càng lớn hơn...</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Jirawat Sutivanichsak","avatar":""},{"name":"Atthaphan Phunsawat","avatar":""},{"name":"Naravit Lertratkosum","avatar":""},{"name":"Pathitta Pornchumroenrut","avatar":""},{"name":"Siripon Sirininatthakul","avatar":""},{"name":"Gandhi​ Wasuvitchayagit","avatar":""},{"name":"Kirati Puangmalee","avatar":""},{"name":"Preeyaphat Lawsuwansiri","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wan Kae Tai - Día bisiesto","LEAP DAY","LEAP DAY SERIES","Wan Kae Tai","วันแก้ตาย"]', 1784690324151);
