INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-vu-chia-tay', 'Dịch Vụ Chia Tay', 'Break Up Service', 'https://phimimg.com/upload/vod/20250426-1/db6bdffdc03f527cd11e9ada1db2f0a4.jpg', 'https://phimimg.com/upload/vod/20250426-1/18eecea3ff561f5d83cf79813896d47f.jpg', '<p>Túng quẫn, Jued sẵn sàng làm bất cứ điều gì để kiếm tiền, kể cả làm việc với Boss — một người chuyên kiếm sống bằng cách phá hoại các mối quan hệ. Sau lần gặp nhau đầy trớ trêu, Boss — một tay chuyên nghiệp quen làm việc một mình — không bỏ lỡ cơ hội nào để gây khó dễ cho Jued. Tuy nhiên, Jued rất kiên cường và dần chứng tỏ bản thân giỏi hơn những gì cả hai từng nghĩ.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Jumpol Adulkittiporn","avatar":""},{"name":"Jorin Khumpiraphan","avatar":""},{"name":"Tachakorn Boonlupyanun","avatar":""},{"name":"Thanakrit Panichawid","avatar":""},{"name":"Patara Eksangkul","avatar":""},{"name":"Ploynira Hiruntaveesin","avatar":""},{"name":"Prariyapit Yu","avatar":""},{"name":"Tawan Vihokratana","avatar":""},{"name":"Nipaporn Thititanakarn","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["บริษัทลดรักเลิก"]', 1784690324151);
