INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('holmes-cua-khu-pho', 'Holmes Của Khu Phố', 'Salon De Holmes', 'https://phimimg.com/upload/vod/20250619-1/ef0ff96657b6f0b0c364d0c22af78b7a.jpg', 'https://phimimg.com/upload/vod/20250619-1/833e56c67e754fbe721deca1a52b6be1.jpg', '<p>Phim kể về 4 bà nội trợ bị quá tải với công việc nhà, bị người khác phớt lờ, và đôi khi phải gác lại ước mơ của mình vì gia đình, giải quyết các vụ án bằng cách lắng nghe câu chuyện của những nạn nhân bị bỏ qua và truy tìm bằng chứng trong cuộc sống hàng ngày của họ.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 5, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Si-young","avatar":""},{"name":"Jung Young-ju","avatar":""},{"name":"Kim Da-som","avatar":""},{"name":"Nam Kee-ae","avatar":""},{"name":"Jung Sang-hoon","avatar":""},{"name":"Oh Dae-hwan","avatar":""},{"name":"Lee Su-ji","avatar":""},{"name":"Kim Si-hyeon","avatar":""},{"name":"Kang Ji-woo","avatar":""},{"name":"Lee Jae-kyoon","avatar":""},{"name":"Lee Hwa-Kyum","avatar":""},{"name":"Park Ji-a","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["主妇侦探社","沙龙福尔摩斯","صالون هولمز","살롱 드 홈즈"]', 1784690324151);
