INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-kip-luyen-rong-2025', 'Bí Kíp Luyện Rồng', 'How To Train Your Dragon', 'https://phimimg.com/upload/vod/20250701-1/a59ae5adace0d10f46f9b9c3ec68d727.jpg', 'https://phimimg.com/upload/vod/20250701-1/fec7dad91c4192a3e7821ad93f2334d1.jpg', '<p>Câu chuyện về một chàng trai trẻ với ước mơ trở thành thợ săn rồng, nhưng định mệnh lại đưa đẩy anh đến tình bạn bất ngờ với một chú rồng. Giống như bộ phim hay gốc từ năm 2010, Bí Kíp Luyện Rồng phiên bản live-action lần này diễn ra trên Đảo Berk, nơi người Viking và rồng đã là kẻ thù không đội trời chung trong nhiều thế hệ. Nhưng khi Hiccup (Mason Thames) – con trai của Tù trưởng Stoick the Vast đi ngược lại truyền thống hàng thế kỷ để kết bạn với Toothless - một con rồng Night Fury, chính giây phút đó anh ấy đã phá vỡ quy tắc vốn có của cộng đồng và mở ra sự căng thẳng tột cùng cho cả người Viking và rồng.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Mason Thames","avatar":""},{"name":"Nico Parker","avatar":""},{"name":"Gerard Butler","avatar":""},{"name":"Nick Frost","avatar":""},{"name":"Gabriel Howell","avatar":""},{"name":"Julian Dennison","avatar":""},{"name":"Bronwyn James","avatar":""},{"name":"Harry Trevaldwyn","avatar":""},{"name":"Murray McArthur","avatar":""},{"name":"Peter Serafinowicz","avatar":""},{"name":"Naomi Wirthner","avatar":""},{"name":"Ruth Codd","avatar":""},{"name":"Andrea Ware","avatar":""},{"name":"Anna Leong Brophy","avatar":""},{"name":"Marcus Onilude","avatar":""},{"name":"Pete Selwood","avatar":""},{"name":"Daniel-Jo","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["مربی اژدها","Sådan træner du din drage","Näin koulutat lohikäärmeesi","Dragetreneren","Como Treinar o Seu Dragão","How to Train Your Dragon"]', 1784690324151);
