INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bi-kip-luyen-rong-2025', 'Bí Kíp Luyện Rồng', 'How To Train Your Dragon', 'bí kíp luyện rồng how to train your dragon mason thames nico parker gerard butler nick frost gabriel howell julian dennison bronwyn james harry trevaldwyn murray mcarthur peter serafinowicz naomi wirthner ruth codd andrea ware anna leong brophy marcus onilude pete selwood daniel-jo مربی اژدها sådan træner du din drage näin koulutat lohikäärmeesi dragetreneren como treinar o seu dragão how to train your dragon', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-dau-hanh-dong', 'Cô Dâu Hành Động', 'Bride Hard', 'https://phimimg.com/upload/vod/20250722-1/f13a169fafed99d0b973b3695cc3801e.jpg', 'https://phimimg.com/upload/vod/20250722-1/c75adab52422d5192068d473c1900697.jpg', '<p>Sam là một đặc vụ bí mật, và nhiệm vụ khó khăn nhất của cô cho đến nay chính là làm hài lòng người bạn thân sắp làm cô dâu trong một đám cưới xa hoa ở nơi nghỉ dưỡng. Khi một nhóm lính đánh thuê bất ngờ ập đến, phá hỏng buổi tiệc và bắt giữ các vị khách làm con tin, Sam bị cuốn vào một trận chiến chưa từng có — nơi cô không thể để lộ thân phận hay làm hỏng ngày trọng đại. Khi đối đầu với bọn xấu trong trận chiến căng thẳng được ngụy trang như một câu chuyện cổ tích, Sam nhận ra mối đe dọa thực sự có thể đang ở gần hơn cô tưởng.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Rebel Wilson","avatar":""},{"name":"Anna Camp","avatar":""},{"name":"Anna Chlumsky","avatar":""},{"name":"Da''Vine Joy Randolph","avatar":""},{"name":"Gigi Zumbado","avatar":""},{"name":"Sherry Cola","avatar":""},{"name":"Sam Huntington","avatar":""},{"name":"Michael O''Neill","avatar":""},{"name":"Colleen Camp","avatar":""},{"name":"Stephen Dorff","avatar":""},{"name":"Justin Hartley","avatar":""},{"name":"Mark Valley","avatar":""},{"name":"Jeff Chase","avatar":""},{"name":"David Lengel","avatar":""},{"name":"Craig Anton","avatar":""},{"name":"Dhruv Uday Singh","avatar":""},{"name":"Johnno W","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id"