INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-nua-hoan-hao', 'Một Nửa Hoàn Hảo', 'Materialists', 'https://phimimg.com/upload/vod/20250722-1/82858bae822793c7e013b6efcbd9d182.jpg', 'https://phimimg.com/upload/vod/20250722-1/3aa1d9ae03093b2b972a4680630e1998.jpg', '<p>Lucy (Dakota Johnson), một cô gái xinh đẹp làm công việc mai mối ở New York. “Mát tay” trong chuyện mai mối giúp người khác, nhưng trớ trêu Lucy lại “lạc lối” trong câu chuyện tình cảm của chính mình. Bất ngờ đối mặt với ngã rẽ tình cảm khi gặp lại người yêu cũ &quot;không hoàn hảo&quot; (Chris Evans) và một người đàn ông &quot;hoàn hảo&quot; (Pedro Pascal). Cô nàng bị đẩy vào tình thế khó xử. Đứng giữa những lựa chọn cảm xúc đầy mâu thuẫn, lúc này đây, Lucy mới nhận ra việc tìm kiếm tình yêu đích thực chưa bao giờ là điều dễ dàng.</p>', 'Full', 1, 'single', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Phần Lan', 0, '[{"name":"Dakota Johnson","avatar":""},{"name":"Chris Evans","avatar":""},{"name":"Pedro Pascal","avatar":""},{"name":"Zoë Winters","avatar":""},{"name":"Marin Ireland","avatar":""},{"name":"Louisa Jacobson","avatar":""},{"name":"Dasha Nekrasova","avatar":""},{"name":"Emmy Wheeler","avatar":""},{"name":"Eddie Cahill","avatar":""},{"name":"Sawyer Spielberg","avatar":""},{"name":"Joseph Lee","avatar":""},{"name":"John Magaro","avatar":""},{"name":"Nedra Marie Taylor","avatar":""},{"name":"Sietzka Rose","avatar":""},{"name":"Halley Feiffer","avatar":""},{"name":"Madeline Wise","avatar":""},{"name":"Ian Stuart","avatar":""},{"name":"Da","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["مادی‌گرایان","Material Love","รักแบบไหนที่ใจตามหา","Materialistlər","Çifti i përkryer","Materialists"]', 1784690324151);
