INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-vu', 'Anh Vũ', 'Faith & Fire', 'https://phimimg.com/upload/vod/20250705-1/4691e6b776da46a3819603340f230972.jpg', 'https://phimimg.com/upload/vod/20250705-1/3d86dc3603aece699c4013c377ea580b.jpg', '<p>Vì tận mắt chứng kiến người anh em của mình chết nên Trần Thiên Sảng đã lựa chọn rời khỏi hệ thống An ninh Quốc gia để làm một người bán cá bình thường. Sau khi được triệu tập trở lại, anh đến tỉnh Đài Loan, Trung Quốc, trà trộn vào một băng đảng xã hội đen để tìm hiểu rõ các đường dây buôn lậu. Đến đây, anh nhanh chóng hòa nhập vào cuộc sống và các mối quan hệ tại đó. Tuy nhiên, những cuộc tranh đấu đẫm máu của các băng đảng và sự tàn khốc của nhiệm vụ nằm vùng đang âm thầm chờ đợi anh phía trước…</p>', 'Hoàn Tất (44/44)', 44, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Diệp Lưu","avatar":""},{"name":"Ngô Kiến Hào","avatar":""},{"name":"Vu Văn Văn","avatar":""},{"name":"Dịch An Tỉ","avatar":""},{"name":"Cao Tiệp","avatar":""},{"name":"Từ Đông Đông","avatar":""},{"name":"Khưu Sĩ Luân","avatar":""},{"name":"Thường Nhung","avatar":""},{"name":"Thỏa Tông Hoa","avatar":""},{"name":"Chu Lạc","avatar":""},{"name":"Bạch Nhất Hoằng","avatar":""},{"name":"Trương Thừa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Faith And Fire","鹦鹉"]', 1784690324151);
