INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-da-cuop-mat-dem-dau-tien-cua-nam-chinh', 'Tôi Đã Cướp Mất Đêm Đầu Tiên Của Nam Chính', 'The First Night With The Duke', 'https://phimimg.com/upload/vod/20250612-1/6572024bc5c28e4faa974daac0f499a9.jpg', 'https://phimimg.com/upload/vod/20250612-1/d18cd181c5f37cf56cd022b0ef115cd8.jpg', '<p>Lấy mô-típ &quot;xuyên sách&quot;, Tôi Đã Cướp Mất Đêm Đầu Tiên Của Nam Chính (The First Night With The Duke) xoay quanh một nữ sinh viên bị cuốn vào tiểu thuyết cô yêu thích và trở thành tiểu thư quý tộc Cha Seon Chaek, nữ phụ trong sách. Chỉ mong được sống yên bình, không màng đấu đá với ai, Seon Chaek cố gắng làm mọi thứ để giữ đúng cốt truyện ban đầu. Trớ trêu thay, những nỗ lực của Seon Chaek lại vô tình khiến nam chính nguyên tác, Lee Beon, ngày càng yêu cô say đắm.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 11, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Seohyun","avatar":""},{"name":"Ok Taec-yeon","avatar":""},{"name":"Kwon Han-sol","avatar":""},{"name":"Seo Bum-june","avatar":""},{"name":"Ji Hye-won","avatar":""},{"name":"Lee Tae-seon","avatar":""},{"name":"Seo Hyun-chul","avatar":""},{"name":"Yun Yoo-sun","avatar":""},{"name":"Lee Sang-un","avatar":""},{"name":"Kim Shin-bi","avatar":""},{"name":"Yoon Jung-hoon","avatar":""},{"name":"Song Yeong-jae","avatar":""},{"name":"Ju Seok-tae","avatar":""},{"name":"Nam Kee-ae","avatar":""},{"name":"Jung Hee-tae","avatar":""},{"name":"Jung Ho-bin","avatar":""},{"name":"Kim Young-woong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["الليلة الأولى مع الدوق","ตื่นมาอีกทีก็มีพระเอกนอนอยู่ข้าง ๆ","我奪走了公爵的初夜","Taking the Male Lead''s First Night","I Took the Male Lead","My First Night With the Male Lead","남주의 첫날밤을 가져버렸다"]', 1784690324151);
