INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-dua-tre-gen-z', 'Những Đứa Trẻ Gen Z', 'Taste', 'https://phimimg.com/upload/vod/20250627-1/6ebc5f827008e1bcf0a9e7371e340953.jpg', 'https://phimimg.com/upload/vod/20250627-1/3b3c72d80621eee95caaf8b228d162d1.jpg', '<p>Những Đứa Trẻ Gen Z lấy bối cảnh học đường, khai thác câu chuyện đầy màu sắc của giới trẻ thế hệ 2000. Được nhào nặn bởi những nhà sản xuất của loạt phim Tuổi Nổi Loạn đình đám, phim hứa hẹn sẽ mang đến một góc nhìn mới mẻ, cá tính, sâu sắc, thậm chí là đen tối về cuộc sống và tình yêu của tuổi trẻ.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Suchada Sonpan","avatar":""},{"name":"Anthony Buisseret","avatar":""},{"name":"Phuwin Tangsakyuen","avatar":""},{"name":"Charlette Wasita Hermenau","avatar":""},{"name":"Saharat Thiempan","avatar":""},{"name":"Punnavich Sirikiatvanit","avatar":""},{"name":"Prudtichai Ruayfupant","avatar":""},{"name":"Yanin Opassathaworn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["เด็กเจนแซ่บ","เทสต์ เด็กเจนแซ่บ","Dek Gen Saep"]', 1784690324151);
