INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-dieu-chung-doi', 'Giai Điệu Chung Đôi', 'Double Fugue', 'https://phimimg.com/upload/vod/20250710-1/1ea1e041f549ca0316695e79a1b549c4.jpg', 'https://phimimg.com/upload/vod/20250710-1/538fd47a124b7d6e62b12fb9fe35ef2e.jpg', '<p>Thiên tài hội họa Lục Lê vì muốn điều tra vụ án đẫm máu của cha mẹ mình năm xưa nên đã thâm nhập vào tập đoàn Thức Luân, tiếp cận cô con gái riêng Tần Nguyệt Bạch. Hai người hợp tác, lợi dụng lẫn nhau, từng bước khám phá ra bí mật và thân phận thật sự của đối phương. Từ đối đầu đến thấu hiểu, từ lợi dụng nhau đến hoạn nạn có nhau, dùng tình yêu chữa lành những tổn thương và khuyết thiếu trong tâm hồn nhau.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Di Đồng","avatar":""},{"name":"Thẩm Vũ Khiết","avatar":""},{"name":"Hoàn Nhan Lạc Nhung","avatar":""},{"name":"Lý Áo","avatar":""},{"name":"Trương Lũy","avatar":""},{"name":"Lưu Vĩnh Hy","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["이중부격 : 두 개의 선율","二重赋格"]', 1784690324151);
