INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-hay-mac-no-vao-takaminesan', 'Xin Hãy Mặc Nó Vào, Takamine-san', 'Please Put Them On, Takamine-san', 'https://phimimg.com/upload/vod/20250429-1/0e378791ec0a77289ca4df29e1e05c47.jpg', 'https://phimimg.com/upload/vod/20250429-1/d4a6cbbca2af5622c79adfb16b3e96bb.jpg', '<p>Chủ tịch hội học sinh, Takane Takamine, là một người đẹp không gì sánh bằng, và cô ấy thường không bao giờ kết giao với một người vô danh không bạn bè như Koushi Shirota. Tuy nhiên, sau khi nhìn thấy cô ấy cởi đồ, anh ấy buộc phải trở thành &quot;tủ quần áo&quot; di động của cô ấy khi cô ấy thay đồ lót suốt cả ngày. Nhưng việc Takamine cởi đồ không chỉ để trêu chọc—mà còn là chìa khóa để giải phóng sức mạnh bẻ cong thời gian của cô ấy.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yurika Kubo","avatar":""},{"name":"Daisuke Kasuya","avatar":""},{"name":"Sumire Uesaka","avatar":""},{"name":"Miyu Tomita","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["拜托请穿上 鹰峰同学","鹰峰同学请穿上衣服","请穿上内衣吧，鹰峰同学","בבקשה תלבשי אותם, טאקאמין-סן","Haite Kudasai, Takamine-san","鷹峰さん","Please Put These On, Takamine","はいてください、たかみねさん","Пожалуйста, оденьтесь, Такаминэ","Прошу, вдягнися, Такаміне","Let Me Put Your Panties On, Takamine-san","Please Put These On, Takamine-san","履いてください、鷹峰さん"]', 1784690324151);
