INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('xin-hay-mac-no-vao-takaminesan', 'Xin Hãy Mặc Nó Vào, Takamine-san', 'Please Put Them On, Takamine-san', 'xin hãy mặc nó vào, takamine-san please put them on, takamine-san yurika kubo daisuke kasuya sumire uesaka miyu tomita 拜托请穿上 鹰峰同学 鹰峰同学请穿上衣服 请穿上内衣吧，鹰峰同学 בבקשה תלבשי אותם, טאקאמין-סן haite kudasai, takamine-san 鷹峰さん please put these on, takamine はいてください、たかみねさん пожалуйста, оденьтесь, такаминэ прошу, вдягнися, такаміне let me put your panties on, takamine-san please put these on, takamine-san 履いてください、鷹峰さん', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vi-thanh-qua-hoan-hao', 'Vị Thánh Quá Hoàn Hảo', 'The Too-Perfect Saint: Tossed Aside by My Fiancé And Sold To Another Kingdom', 'https://phimimg.com/upload/vod/20250418-1/8cc6032d85f7cd39463cb0339d9ce497.jpg', 'https://phimimg.com/upload/vod/20250418-1/fe5696a7c5299fdb8540cfa8cf8734cd.jpg', '<p>Philia xuất thân từ một gia đình nổi tiếng vì đã sản sinh ra nhiều thế hệ thánh nhân, và cô cũng không ngoại lệ. Trên thực tế, bà được mệnh danh là vị thánh quyền lực nhất mọi thời đại, có tài năng phi thường đến mức nhiều người thấy bà không thể chịu nổi. Khi ngay cả vị hôn phu của cô cũng quyết định rằng anh không thể chịu đựng được cô, anh đột nhiên hủy bỏ hôn ước của họ. Anh ta háo hức không bao giờ gặp lại cô đến nỗi đã bán cô cho một quốc gia láng giềng đang rất cần một vị thánh của riêng họ. Giờ đây, Philia sẵn sàng đối mặt với những điều chưa biết, hoàn toàn mong đợi sự đối xử khốn khổ hơn. Rốt cuộc, cô ấy thật ngu ngốc khi mong đợi bất cứ ai chào đón cô ấy với vòng tay rộng mở...phải không?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yui Ishikawa","avatar":""},{"name":"Kaede Hondo","avatar":""},{"name":"Takuya Sato","avatar":""},{"name":"Kohei Amasaki","avatar":""},{"name":"Shinnosuke Tachibana","avatar":""},{"name":"Sora Tokui","avatar":""},{"name":"Ken Narita","avatar":""},{"name":"Kanna Nakamura","avatar":""},{"name":"Shu Uchida","avatar":""},{"name":"Kazuyuki Okitsu","avatar":""},{"name":"Miki Ito","avatar":""},{"name":"Kentaro Ito","avatar":""},{"name":"Sayaka Ohara","avatar":""},{"name":"Yuya Murakami","avatar":""},{"name":"Ikue Otani","avatar":""},{"name":"KENN","avatar":""},{"name":"Natsumi Murakami","avatar":""},{"name":"Aina Suzuki","avatar":""},{"name":"Ayaka Su","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["圣女因太过完美不够可爱而被废除婚约并卖到邻国","完美到難以接近的聖女遭到解除婚約後被賣到鄰國","完美到难以接近的圣女遭到解除婚约后被卖到邻国","Kanpekiseijo","Kanpekisugite Kawaige ga Nai to Konyaku Haki sareta Seijo wa Ringoku ni Urareru","Kanpeki Sugite Kawaige ga Nai to Konyaku Haki Sareta Seijo wa Ringoku ni Urareru","聖女因太過完美不夠可愛而被廢除婚約並賣到鄰國","完璧すぎて可愛げがないと婚約破棄された聖女は隣国に売られる"]', 1784690324151);
