INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vi-thanh-qua-hoan-hao', 'Vị Thánh Quá Hoàn Hảo', 'The Too-Perfect Saint: Tossed Aside by My Fiancé And Sold To Another Kingdom', 'vị thánh quá hoàn hảo the too-perfect saint: tossed aside by my fiancé and sold to another kingdom yui ishikawa kaede hondo takuya sato kohei amasaki shinnosuke tachibana sora tokui ken narita kanna nakamura shu uchida kazuyuki okitsu miki ito kentaro ito sayaka ohara yuya murakami ikue otani kenn natsumi murakami aina suzuki ayaka su 圣女因太过完美不够可爱而被废除婚约并卖到邻国 完美到難以接近的聖女遭到解除婚約後被賣到鄰國 完美到难以接近的圣女遭到解除婚约后被卖到邻国 kanpekiseijo kanpekisugite kawaige ga nai to konyaku haki sareta seijo wa ringoku ni urareru kanpeki sugite kawaige ga nai to konyaku haki sareta seijo wa ringoku ni urareru 聖女因太過完美不夠可愛而被廢除婚約並賣到鄰國 完璧すぎて可愛げがないと婚約破棄された聖女は隣国に売られる', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('teogonia', 'Teogonia', 'Teogonia', 'https://phimimg.com/upload/vod/20250421-1/546b0e6a962b50a94a43b387eae00dad.jpg', 'https://phimimg.com/upload/vod/20250421-1/83262ce27707ba909fb4151a1006d017.jpg', '<p>Trong một thế giới loạn lạc bởi chiến tranh giữa loài người và các bộ tộc á nhân, Kai – một cậu bé bình thường ở làng Rag – ngày ngày chiến đấu để bảo vệ quê hương. Giữa những trận chiến khốc liệt, cậu bất ngờ nhớ lại ký ức về một thế giới hiện đại mà mình chưa từng sống. Từ đó, Kai bị cuốn vào những biến cố lớn, bắt đầu hành trình trưởng thành giữa một thế giới đầy thử thách và hiểm nguy.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Mutsumi Tamura","avatar":""},{"name":"Kana Hanazawa","avatar":""},{"name":"Yoshitsugu Matsuoka","avatar":""},{"name":"Atsushi Miyauchi","avatar":""},{"name":"Masaya Fukunishi","avatar":""},{"name":"Manaka Iwami","avatar":""},{"name":"Hana Tamegai","avatar":""},{"name":"Hiroshi Naka","avatar":""},{"name":"Banjo Ginga","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["טאוגוניה","テオゴニア","신통기","테오고니아","신통기 <테오고니아>","Thông Thần Ký","Thần Thông Ký","神統記"]', 1784690324151);
