INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('teogonia', 'Teogonia', 'Teogonia', 'teogonia teogonia mutsumi tamura kana hanazawa yoshitsugu matsuoka atsushi miyauchi masaya fukunishi manaka iwami hana tamegai hiroshi naka banjo ginga טאוגוניה テオゴニア 신통기 테오고니아 신통기 <테오고니아> thông thần ký thần thông ký 神統記', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-tho-may-vo-danh', 'Người Thợ May Vô Danh', 'The Unaware Atelier Meister', 'https://phimimg.com/upload/vod/20250421-1/75c6d3a8d10b414c2d3ccca0778e349a.jpg', 'https://phimimg.com/upload/vod/20250421-1/d75629fd24ae00a69eba1f45df231eb5.jpg', '<p>Một ngày nọ, Kurt, một cậu bé tốt bụng, bất ngờ bị đuổi khỏi Đảng Anh hùng vì &quot;vô dụng&quot;. Anh ta nhận thấy rằng năng khiếu về vũ khí, phép thuật và tất cả các kỹ năng liên quan đến chiến đấu khác của mình là thấp nhất, vì vậy anh ta nhận những công việc lặt vặt là sửa chữa các bức tường lâu đài và đào khoáng sản, nơi khả năng đặc biệt của anh ta ngay lập tức được bộc lộ. Anh ta tỏ ra khéo léo trong việc nấu nướng, xây dựng, khai thác mỏ, chế tạo các công cụ ma thuật—trên thực tế, khả năng của anh ta đối với mọi kỹ năng không liên quan đến chiến đấu đều có cấp độ SSS! Tuy nhiên, Kurt dường như hoàn toàn không nhận thức được tài năng của mình và cuối cùng đã cứu được mọi người, thị trấn và thậm chí cả đất nước thông qua những hành động thiếu hiểu biết của mình!?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Mikako Komatsu","avatar":""},{"name":"Minami Tanaka","avatar":""},{"name":"Asami Seto","avatar":""},{"name":"Hisako Kanemoto","avatar":""},{"name":"Rie Tanaka","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["干杂活我乃最强～关于原英雄队伍的杂役人员，实际上除了战斗能力外全是SSS的故事～","使人误解的工房主 (干杂活我乃最强)","使人误解的工房主","干杂活我乃最强","Kanchigai no Atelier Meister: Eiyuu Party no Moto Zatsuyougakari ga, Jitsu wa Sentou Igai ga SSS Rank Datta to Iu Yoku Aru Hanashi","Kanchigai no Atorie Maisutā: Eiyū Pāti no Moto Zatsuyōgakari ga, Jitsu wa Sentō Igai ga SSS Ranku Datta to Iu Yoku Aru Hanashi","Kanchigai no Atelier Meister","착각하는 공방주","使人誤解的工房主關於原英雄隊伍的雜役人員實際上除了戰鬥能力外全是SSS的故事","Misunderstood Workshop Owner ~ A Common Story of a former Miscellaneous Worker in a Heroic Party who Actually had an SSS Rank for things other than Combat","The Unaware Atelier Master","勘違いの工房主～英雄パーティの元雑用係が、実は戦闘以外がSSSランクだったというよくある話～"]', 1784690324151);
