INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-tho-may-vo-danh', 'Người Thợ May Vô Danh', 'The Unaware Atelier Meister', 'người thợ may vô danh the unaware atelier meister mikako komatsu minami tanaka asami seto hisako kanemoto rie tanaka 干杂活我乃最强～关于原英雄队伍的杂役人员，实际上除了战斗能力外全是sss的故事～ 使人误解的工房主 (干杂活我乃最强) 使人误解的工房主 干杂活我乃最强 kanchigai no atelier meister: eiyuu party no moto zatsuyougakari ga, jitsu wa sentou igai ga sss rank datta to iu yoku aru hanashi kanchigai no atorie maisutā: eiyū pāti no moto zatsuyōgakari ga, jitsu wa sentō igai ga sss ranku datta to iu yoku aru hanashi kanchigai no atelier meister 착각하는 공방주 使人誤解的工房主關於原英雄隊伍的雜役人員實際上除了戰鬥能力外全是sss的故事 misunderstood workshop owner ~ a common story of a former miscellaneous worker in a heroic party who actually had an sss rank for things other than combat the unaware atelier master 勘違いの工房主～英雄パーティの元雑用係が、実は戦闘以外がsssランクだったというよくある話～', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gap-toi-o-san-bong-chay', 'Gặp Tôi Ở Sân Bóng Chày!', 'Catch Me At The Ballpark!', 'https://phimimg.com/upload/vod/20250530-1/60486c7341cab2b3b6feb3907cf71661.jpg', 'https://phimimg.com/upload/vod/20250530-1/323af7953ee78637f51744fcb5a818db.jpg', '<p>Dưới đây là bản dịch tiếng Việt của đoạn mô tả: --- Để trốn khỏi công việc mệt mỏi, Murata – một người đàn ông uể oải – tìm thấy sự giải thoát tại sân bóng chày gần đó. Những trận đấu thì kịch tính, nhưng điều thực sự níu chân anh chính là Ruriko – cô nàng gyaru lạnh lùng như ly bia cô phục vụ, nhưng lại là người có trái tim ấm áp. Là vị khách quen đầu tiên của cô, Murata dần khám phá ra sự dịu dàng đằng sau vẻ ngoài lạnh lẽo ấy. Những cuộc gặp gỡ vừa hài hước vừa ấm lòng của họ không chỉ làm bừng sáng sân bóng mà có lẽ còn thắp sáng cả trái tim họ.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Fairouz Ai","avatar":""},{"name":"Satoshi Inomata","avatar":""},{"name":"Ikumi Hasegawa","avatar":""},{"name":"Maaya Uchida","avatar":""},{"name":"Mayu Sagara","avatar":""},{"name":"Momoko Seto","avatar":""},{"name":"Yoji Ueda","avatar":""},{"name":"Satoshi Tanaka","avatar":""},{"name":"Chiharu Sawashiro","avatar":""},{"name":"Jin Urayama","avatar":""},{"name":"Rika Tachibana","avatar":""},{"name":"Wakana Kuramochi","avatar":""},{"name":"Kiyono Yasuno","avatar":""},{"name":"Ayumi Mano","avatar":""},{"name":"Hiroki Touchi","avatar":""},{"name":"Chiaki Kobayashi","avatar":""},{"name":"Daiki Yamashita","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["阳光马达棒球场","Ballpark de Tsukamaete!","The Catcher in the Ballpark!","Ловец бейсбольного поля!","ボールパークでつかまえて！"]', 1784690324151);
