INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gap-toi-o-san-bong-chay', 'Gặp Tôi Ở Sân Bóng Chày!', 'Catch Me At The Ballpark!', 'gặp tôi ở sân bóng chày! catch me at the ballpark! fairouz ai satoshi inomata ikumi hasegawa maaya uchida mayu sagara momoko seto yoji ueda satoshi tanaka chiharu sawashiro jin urayama rika tachibana wakana kuramochi kiyono yasuno ayumi mano hiroki touchi chiaki kobayashi daiki yamashita 阳光马达棒球场 ballpark de tsukamaete! the catcher in the ballpark! ловец бейсбольного поля! ボールパークでつかまえて！', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-xuyen-quang-minh-vuong', 'Tử Xuyên: Quang Minh Vương', 'Eternal Brotherhood 2', 'https://phimimg.com/upload/vod/20250530-1/853913dff7125e77a52d8573b94b9eea.jpg', 'https://phimimg.com/upload/vod/20250530-1/e5f75bdff635f53d0fd209c0de46da90.jpg', '<p>Tây Xuyên đại lục, tứ phương phân tranh, chiến loạn liên miên. Hai đại gia tộc Tử Xuyên và Bắc tộc mỗi bên chiếm cứ một phương, ngoài ra còn có hai đại gia tộc khác là Lưu Phong và Lâm gia luôn rình rập dòm ngó Tử Xuyên. Dã tâm của Bắc tộc ngày càng lớn, liền phát động tấn công Tử Xuyên. Trong gia tộc Tử Xuyên, thiếu niên tài ba Tử Xuyên Tú cùng hai huynh đệ kết nghĩa là Đế Lâm và Tư Nghị Lâm xông pha ra tiền tuyến ở Viễn Châu để chống lại ngoại địch. Thế công của Bắc tộc dữ dội, trong khi Tử Xuyên vì nhiều năm chinh chiến mà gốc rễ đã suy yếu, buộc phải cầu hòa, cắt nhường Viễn Châu để dập tắt chiến loạn. Nào ngờ, trên đường trở về, Tử Xuyên Tú lại bị vu oan do kế ly gián của Bắc tộc, bị tộc chủ Tử Xuyên Tham Tinh tước bỏ họ tộc và trục xuất khỏi lãnh thổ. Trong bước đường cùng, Tử Xuyên Tú dẫn theo binh sĩ trung thành thuộc Tú Tự Doanh, phiêu bạt nơi đất Viễn Châu, tự lập thế lực, đồng thời giúp người dân khôi phục cuộc sống, chống lại ách thống trị tàn bạo của Bắc tộc. Nhờ đó, Tử Xuyên Tú được dân chúng yêu mến và phong làm Quang Minh Vương xứ Viễn Châu. Dù lưu lạc bao năm, chàng chưa từng quên thân phận của mình. Trải qua muôn vàn khó khăn, cuối cùng cũng thu phục toàn bộ Viễn Châu. Các dân tộc nơi đây từ đó vĩnh viễn thoát khỏi kiếp nô lệ, thực sự giành lại tự do và hòa bình. Cùng lúc ấy, kinh đô liên tiếp truyền về tin mừng: Quang Minh Vương Tử Xuyên Tú đại phá Bắc tộc, thu hồi Viễn Châu, rửa sạch nỗi oan suốt bao năm. Trải qua bao sương gió, chàng thiếu niên nhiệt huyết vô ưu năm nào, Tử Xuyên Tú cuối cùng đã lột xác thành một vị lãnh tụ huyền thoại, mang trong tim tình yêu đất nước sâu sắc và tấm lòng bao dung với muôn dân. Những chiến tích chính nghĩa, anh dũng, khiến người người kính ngưỡng của chàng đã vang danh khắp đại lục Tây Xuyên.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Húc Văn","avatar":""},{"name":"Lưu Vũ Ninh","avatar":""},{"name":"Trương Minh Ân","avatar":""},{"name":"Lý Mặc Chí","avatar":""},{"name":"Thái Trác Âm","avatar":""},{"name":"Mã Thiếu Hoa","avatar":""},{"name":"Hoàng Hạo Nguyệt","avatar":""},{"name":"Lý Quả","avatar":""},{"name":"Trần Tư Triệt","avatar":""},{"name":"Ngô Hách Luân","avatar":""},{"name":"Trần Gia Văn","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The King of Light in Zichuan","紫川·光明王","Zi Chuan","Zi Chuan Guang Ming San Jie","Zi Chuan Guang Ming Wang","紫川 (网络剧)","紫川","紫川之光明王","紫川之光明三杰","紫川·光明三杰","Zichuan","网剧紫川","Los Tres Héroes de Zichuan Bright","紫川〜光明王〜","자천·광명삼걸","자천·광명왕","Цзы Чуань","สามสงครามสหาย","สามสงครามสหาย ราชันแห่งแสง","紫川·光明三傑","Eternal Brotherhood","Purple River","Tử Tuyền - Quang Minh Tam Kiệt","Tử Xuyên: Quang Minh Vương"]', 1784690324151);
