INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tu-xuyen-quang-minh-vuong', 'Tử Xuyên: Quang Minh Vương', 'Eternal Brotherhood 2', 'tử xuyên: quang minh vương eternal brotherhood 2 dương húc văn lưu vũ ninh trương minh ân lý mặc chí thái trác âm mã thiếu hoa hoàng hạo nguyệt lý quả trần tư triệt ngô hách luân trần gia văn the king of light in zichuan 紫川·光明王 zi chuan zi chuan guang ming san jie zi chuan guang ming wang 紫川 (网络剧) 紫川 紫川之光明王 紫川之光明三杰 紫川·光明三杰 zichuan 网剧紫川 los tres héroes de zichuan bright 紫川〜光明王〜 자천·광명삼걸 자천·광명왕 цзы чуань สามสงครามสหาย สามสงครามสหาย ราชันแห่งแสง 紫川·光明三傑 eternal brotherhood purple river tử tuyền - quang minh tam kiệt tử xuyên: quang minh vương', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('84-met-vuong', '84 Mét Vuông (84m²)', 'Wall To Wall', 'https://phimimg.com/upload/vod/20250719-1/393f69a97792febd14bea63f78ccc04d.jpg', 'https://phimimg.com/upload/vod/20250719-1/f6d514430f90917264f83f91e751884f.jpg', '<p>Dốc hết tiền tiết kiệm cả đời để mua một căn hộ mới, người đàn ông nọ phát hiện ra các bức tường trong căn hộ này đầy những tiếng ồn đáng sợ, hàng xóm thù địch và bí mật ghê rợn.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kang Ha-neul","avatar":""},{"name":"Yeom Hye-ran","avatar":""},{"name":"Seo Hyun-woo","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["84㎡","84 Jegopmiteo","墙外之音","84㎡ (84제곱미터)","Mis 84 m²","من الجدار إلى الجدار","84m²","Wall to Wall","84 m2","84m2","84제곱미터"]', 1784690324151);
