INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('84-met-vuong', '84 Mét Vuông (84m²)', 'Wall To Wall', '84 mét vuông (84m²) wall to wall kang ha-neul yeom hye-ran seo hyun-woo 84㎡ 84 jegopmiteo 墙外之音 84㎡ (84제곱미터) mis 84 m² من الجدار إلى الجدار 84m² wall to wall 84 m2 84m2 84제곱미터', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-sac-xanh-bien-ca', 'Yêu Sắc Xanh Biển Cả', 'Rose And Gun', 'https://phimimg.com/upload/vod/20250703-1/551636f20b0dbcc847a9c7655f182874.jpg', 'https://phimimg.com/upload/vod/20250703-1/651c51830e9404a0d09590337420e19a.jpg', '<p>Đường Hâm là một người cuồng công việc, không bao giờ cho rằng kết hôn là việc bắt buộc trong đời, nhưng trong lòng lại khao khát một người anh hùng thực sự. Đối tượng xem mắt của cô, Ngũ Tứ, là một sĩ quan quân đội ưu tú. Hai người trẻ tuổi vốn được người ngoài xem là xứng đôi vừa lứa, sau khi trải qua những câu chuyện dở khóc dở cười đã trở thành người yêu. Trong khi đó, Lam Dương Dương vừa tốt nghiệp trường y đã phải lòng chàng sĩ quan đẹp trai Tông Khanh ngay từ cái nhìn đầu tiên. Sự khác biệt về nghề nghiệp, quan điểm giá trị sống trái ngược, và thậm chí cả sự hy sinh và nhẫn nhịn do tính chất đặc thù trong nghề nghiệp của người yêu đã khiến hai cô gái trẻ có lúc do dự. Nhưng sau khi thực sự hiểu rõ về tập thể những người vợ lính, họ đã thấu hiểu từ tận đáy lòng về thứ tình cảm cao cả và mạnh mẽ, kiên cường hơn này. Hai cặp đôi trẻ đã kiên định nắm tay nhau đi hết quãng đời còn lại, và tình yêu trong quân ngũ vẫn tiếp tục.</p>', 'Hoàn Tất (34/34)', 34, 'series', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Kim Hãn","avatar":""},{"name":"Tuyên Lộ","avatar":""},{"name":"Từ Dương","avatar":""},{"name":"Thiên Ái","avatar":""},{"name":"Trâu Đình Uy","avatar":""},{"name":"Vương Dục","avatar":""},{"name":"Lạc Ngôn","avatar":""},{"name":"Trần Khang","avatar":""},{"name":"Đường Húc","avatar":""},{"name":"Phòng Tử Bân","avatar":""},{"name":"Dương Tử Yên","avatar":""},{"name":"Mã Lệ","avatar":""},{"name":"Diêm Cần","avatar":""},{"name":"Lưu Uy","avatar":""},{"name":"Trương Đạc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["许你岁月静好","Ai Shang Hai Lan Jun","ROSE AND GUN","爱上海军蓝"]', 1784690324151);
