INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-cua-cac-ba-thim', 'Thế Giới Của Các Bà Thím', 'Got Old Recently', 'https://phimimg.com/upload/vod/20250715-1/27b963a81e86ba67506910c66585cf52.jpg', 'https://phimimg.com/upload/vod/20250715-1/c52e77e20757cf8203e3b1df3a766490.jpg', '<p>Sau khi tốt nghiệp trường đại học dành cho người cao tuổi, bà Vương Vu Điền quay trở lại chốn công sở. Tại đây, bà đã gặp gỡ một vị lãnh đạo tự luyến nhưng lại rất hay bao che cho người khác, một &quot;chuyên gia nịnh bợ&quot; thâm niên, thế hệ Gen Z với tính cách thẳng thắn. Không chỉ vậy, bà còn nhận được sự ưu ái của vị chủ tịch hội đồng quản trị, người đang &quot;vi hành&quot; dưới thân phận một nhân viên vệ sinh. Đối mặt với vô số thử thách, bà Vương cùng các đồng nghiệp đồng lòng vượt qua, định hình lại môi trường làm việc tại đây.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Linh Ngọc","avatar":""},{"name":"La Tập","avatar":""},{"name":"Đường Nhân Tiểu Ca","avatar":""},{"name":"Sử Nghiên","avatar":""},{"name":"Trương Hạo Thừa","avatar":""},{"name":"Lưu Hạo Nguyên","avatar":""},{"name":"A Vĩ Đơn Thuần","avatar":""},{"name":"Trữ Mộng Na","avatar":""},{"name":"Môn Khang","avatar":""},{"name":"Triệu Hiểu Hủy","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Da Ma De Shi Jie","大妈的世界 贺岁篇","大妈的世界","大妈的世界3 大妈闯职场"]', 1784690324151);
