INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-than-2025', 'Bán Thân', 'Sell Yourself', 'https://phimimg.com/upload/vod/20250702-1/eb6ca34461feb064695be50cc3f18985.jpg', 'https://phimimg.com/upload/vod/20250702-1/563ff938a08641ba15fe248853681a81.jpg', '<p>Phim Tâm Lý Tội Phạm Kịch Tính Việt Nam. Những nội dung trong phim là các hành động giả tưởng, được diễn viên chuyên nghiệp thực hiện, vui lòng không thực hiện theo.</p>', 'Tập 3', 24, 'series', 'ongoing', 17, 2025, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Bùi Tấn Hảo","avatar":""},{"name":"Tonny Việt","avatar":""},{"name":"Hoàng Trâm Anh","avatar":""},{"name":"Nguyễn Trung Tín","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324152);
