INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ban-than-2025', 'Bán Thân', 'Sell Yourself', 'bán thân sell yourself bùi tấn hảo tonny việt hoàng trâm anh nguyễn trung tín ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-hoan-the-toi', 'Nha Hoàn Thế Tội', 'Guilty Maid', 'https://phimimg.com/upload/vod/20250710-1/04c41033d94eaa85dfc371264a6242d5.jpg', 'https://phimimg.com/upload/vod/20250710-1/c0ee759a9315837796aaf2a451fc95bb.jpg', '<p>Tô Vân Thanh che giấu thân phận lẻn vào nhà họ Thẩm để điều tra sự mất tích bí ẩn của chị gái sau khi được gả vào đây, nhưng cô đã nhanh chóng bị cuốn vào những cuộc đấu đá nơi đây. Cô tìm đủ mọi cách để điều tra vụ án nhưng lại nhiều lần bất ngờ bị xuyên hồn vào thân xác của những kẻ ác độc đang hấp hối. Mỗi khi xuất hiện manh mối vụ án, Tô Vân Thanh lại bị xuyên hồn biến thành kẻ ác, khiến cô liên tục đối mặt tử thần. Trong hành trình gian nan ấy, tình cảm giữa Tô Vân Thanh và thiếu gia Thẩm Hưng Ngôn dần dần nảy nở. Khả năng xuyên hồn kỳ lạ này lại giúp cô tiến gần hơn tới sự thật. Nhưng cuối cùng, một âm mưu kinh thiên động địa cùng mối thù truyền kiếp giữa hai gia tộc Tô - Thẩm đã bị phơi bày. Liệu cô có bảo vệ được tính mạng và tình yêu của mình hay không?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hạ Linh Lạp","avatar":""},{"name":"Lý Cảnh Ngạch","avatar":""},{"name":"Ngô Tĩnh Tâm","avatar":""},{"name":"Tôn Mỹ Nan","avatar":""},{"name":"Đỗ Gia Hiên","avatar":""},{"name":"Giả Thư Di","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["替罪丫环"]', 1784690324152);
