INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-troi-cua-em', 'Mặt Trời Của Em', 'Your Sunshine', 'https://phimimg.com/upload/vod/20250715-1/76f631c94c5d42cd2788850f3b57b194.jpg', 'https://phimimg.com/upload/vod/20250715-1/58aa8d46c5bd0d9dad090cffaf6d86f8.jpg', '<p><span style="text-wrap-mode: wrap;">Vào đầu thế kỷ 20 tại thành phố Tường Thành, hai gia tộc Doãn và Lục cùng nhau tạo nên thời kỳ phồn thịnh. Sau đó, gia tộc Lục suy tàn, gia tộc Doãn rơi vào cảnh nội loạn. Lục Dã – con gái út của nhà họ Lục – vì muốn tránh né nợ nần nên giả chết và ra nước ngoài. Còn Lục Ý – chị cả – để bảo vệ gia tộc đã kết hôn với con trai thứ nhà họ Doãn, Doãn Chước Phong. Vài năm sau, Lục Ý bất ngờ qua đời. Lục Dã trở về nước để dự tang lễ chị gái, vô tình tái ngộ anh rể Doãn Chước Phong, đồng thời phát hiện cái chết của Lục Ý có liên quan đến một tổ chức bí ẩn tên là “Nhất Tâm Hội”. Lục Dã bái Doãn Chước Phong làm sư phụ và gia nhập tổ chức ngầm “Thanh Đồng Diệp” do anh dẫn dắt, quyết tâm trở thành lưỡi dao báo thù cho chị gái. Trong quá trình kề cận ngày đêm, giữa thầy trò dần nảy sinh tình cảm, và một mối tình đơn phương bị chôn giấu cũng dần lộ rõ... Khi thân phận thật sự của Lục Ý cùng bí mật giữa hai nhà Doãn – Lục được hé lộ, cả hai cùng nhau từng bước vén màn chân tướng về “Nhất Tâm Hội”. Trải qua bao lần sinh tử, Phong và Dã cuối cùng cũng có thể nên duyên, cùng nhau bước trên con đường chính nghĩa.</span></p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Khang Chi Nam","avatar":""},{"name":"Dương Binh Trác","avatar":""},{"name":"Từ Trấn Trấn","avatar":""},{"name":"Vương Trạch Huy","avatar":""},{"name":"Quách Gia Ngữ","avatar":""},{"name":"Tây Chính Kiệt","avatar":""},{"name":"Trình Thanh","avatar":""},{"name":"Triệu An Đệ","avatar":""},{"name":"Bành Cảnh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ni De Tai Yang","风也温柔","她似风野","Be Your Monster","你的太阳"]', 1784690324152);
