INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-am-anh-2025', 'Nỗi Ám Ảnh', 'Obsesyon', 'https://phimimg.com/upload/vod/20250717-1/c8806376fafd3dd0178631a5ab2b477c.jpg', 'https://phimimg.com/upload/vod/20250717-1/2001e846d3ea34f5adc25be6e09a152d.jpg', '<p>Một người phụ nữ trung niên trở nên ám ảnh với một nam sinh – người đang thầm yêu con gái riêng của bà. Mỗi khi chàng trai trẻ thân mật với cô con gái, người phụ nữ lại tưởng tượng rằng chính mình đang ở bên anh ta.</p>', 'Full', 1, 'single', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Yda Manzano","avatar":""},{"name":"Christy Imperial","avatar":""},{"name":"Itan Magnaye","avatar":""},{"name":"Armani Hector","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Obsesyon"]', 1784690324152);
