INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dao-hoa-anh-giang-son', 'Đào Hoa Ánh Giang Sơn', 'The Princess''s Gambit', 'https://phimimg.com/upload/vod/20250625-1/2ee8faad9354284ba4c7564094a279bc.jpg', 'https://phimimg.com/upload/vod/20250625-1/c5b66b7615fc927b53e05153c2fb82c4.jpg', '<p>Lúc bấy giờ, thiên hạ chia ba. Ngụy quốc hùng mạnh nhưng tranh đoạt ngôi thái tử căng thẳng. Ở Triệu quốc, Lữ Hậu nắm quyền, công chúa Khương Đào Hoa quyết định gả sang Ngụy để tìm đường sống cho mình và đệ đệ. Vừa đến nơi, nàng bị sói tấn công và bị bắt gặp trên giường cùng Thừa tướng Thẩm Tại Dã, đành xin làm thiếp để ở lại. Dù trúng độc, nàng vẫn phải hoàn thành nhiệm vụ lật đổ thái tử do Lữ Hậu giao phó. Thẩm Tại Dã ngoài lạnh trong nóng, một lòng muốn phò tá minh quân, nhưng lại vô tình có “một đêm xuân sắc” với nàng trong khi điều tra vụ án. Sau đó, vì muốn loại bỏ kẻ địch và trừ Khương Đào Hoa, Thẩm Tại Dã bày mưu giết nàng, nhưng nàng tự vẫn để thoát thân, khiến hắn thay đổi cách nhìn. Hai người vừa đấu trí vừa dần nảy sinh tình cảm. Phát hiện thái tử là kẻ thù của Thẩm Tại Dã, nàng chủ động hỗ trợ hắn thanh trừng hậu viện nội gián. Sau cùng, hai người cùng đưa bằng chứng khiến thái tử thất thế, nhưng tranh đoạt ngôi vị lại càng gay gắt hơn.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 6, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Học Nghĩa","avatar":""},{"name":"Mạnh Tử Nghĩa","avatar":""},{"name":"Cao Hàn","avatar":""},{"name":"Lưu Lệnh Tư","avatar":""},{"name":"Biên Trình","avatar":""},{"name":"Phạm Cảnh Văn","avatar":""},{"name":"Đại Tư","avatar":""},{"name":"Vương Nghệ Cẩn","avatar":""},{"name":"Y Vân Hạc","avatar":""},{"name":"Hoàng Mộng Oánh","avatar":""},{"name":"Chu Tiển","avatar":""},{"name":"Vương Nhã Giai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Tao Hua Zhe Jiang Shan","Tao Hua Ying Jiang Shan","桃花折江山","桃花映江山","ลวงเล่ห์เสน่ห์ดอกท้อ"]', 1784690324152);
