INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dao-hoa-anh-giang-son', 'Đào Hoa Ánh Giang Sơn', 'The Princess''s Gambit', 'đào hoa ánh giang sơn the princess''s gambit lưu học nghĩa mạnh tử nghĩa cao hàn lưu lệnh tư biên trình phạm cảnh văn đại tư vương nghệ cẩn y vân hạc hoàng mộng oánh chu tiển vương nhã giai tao hua zhe jiang shan tao hua ying jiang shan 桃花折江山 桃花映江山 ลวงเล่ห์เสน่ห์ดอกท้อ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-danh-phap-luat', 'Nhân Danh Pháp Luật', 'In The Name Of Justice', 'https://phimimg.com/upload/vod/20250626-1/f9ebd442e7895532395427ab9f97c01d.jpg', 'https://phimimg.com/upload/vod/20250626-1/e2b65fe945a833f9474b597ab14ed1a9.jpg', '<p>Bộ phim kể về các công tố viên Hồng Lượng và Trịnh Nhã Bình của Viện Kiểm sát tỉnh Hải Đông, trong quá trình xem xét lại vụ án “Tổ chức xã hội đen Vạn Hải” tại thành phố Đông Bình, đã phát hiện ra hành vi tư lợi, làm sai lệch pháp luật của một số nhân viên tư pháp liên quan đến vụ án. Họ đã lấy đầu mối từ các manh mối tố giác, làm điểm đột phá để triệt phá hoàn toàn thế lực đen đứng sau vụ án, đồng thời điều tra và xử lý các hành vi phạm tội chức vụ của cán bộ tư pháp, nhằm thực thi công lý và bảo vệ pháp luật.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Dịch","avatar":""},{"name":"Lý Quang Khiết","avatar":""},{"name":"Tưởng Tâm","avatar":""},{"name":"Lưu Gia","avatar":""},{"name":"Phùng Gia Nghi","avatar":""},{"name":"Dương Thạc","avatar":""},{"name":"Thẩm Kinh Minh","avatar":""},{"name":"Đổng Thanh","avatar":""},{"name":"Đinh Vĩnh Đại","avatar":""},{"name":"Từ Phan Tê","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["In The Name Of Justice","以法之名"]', 1784690324152);
