INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhan-danh-phap-luat', 'Nhân Danh Pháp Luật', 'In The Name Of Justice', 'nhân danh pháp luật in the name of justice trương dịch lý quang khiết tưởng tâm lưu gia phùng gia nghi dương thạc thẩm kinh minh đổng thanh đinh vĩnh đại từ phan tê in the name of justice 以法之名', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gio-dong-dua-mua-xuan-tro-lai', 'Gió Đông Đưa Mùa Xuân Trở Lại', 'Spring''s Gentle Return', 'https://phimimg.com/upload/vod/20250715-1/b9571ef6b2ec8bd2adfd5675cd0f07d5.jpg', 'https://phimimg.com/upload/vod/20250715-1/50197f3bb557c6a7bc87072a18896752.jpg', '<p>Trong thời đại Đại Thành, nha dịch Trần Nghi Khúc và đại phu Dương Đào quyết định ly hôn đúng vào ngày kỷ niệm ba năm kết hôn. Khi cả hai chuẩn bị lấy ra giấy ly hôn để chia tay trong hòa bình, thì bất ngờ Hầu Vệ của Giám sát ty xông vào, bắt giữ họ và ép buộc giao nộp thư thông đồng với kẻ địch. Cặp vợ chồng vốn luôn sống yên ổn nay bỗng chốc bị gán cho tội danh là “đôi gián điệp tình nhân thông đồng với ngoại bang”! Không còn lựa chọn nào khác, hai người buộc phải bước vào hành trình chạy trốn đầy nguy hiểm.</p><p><br/></p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wanyan Luorong","avatar":""},{"name":"Xiang Xin","avatar":""},{"name":"Shi Zhaoqi","avatar":""},{"name":"Ai Rui Ba Di","avatar":""},{"name":"Yuan Hongyang","avatar":""},{"name":"Qiao Xin","avatar":""},{"name":"Yuan Dabao","avatar":""},{"name":"Li Yi","avatar":""},{"name":"Sun Hao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Dong Feng Song Chun Gui","东风送春归"]', 1784690324152);
