INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dang-toi-cao', 'Đấng Tối Cao', 'Sovereign', 'https://phimimg.com/upload/vod/20250717-1/5811f8f20278f93bcb135f93771d5213.jpg', 'https://phimimg.com/upload/vod/20250717-1/032f107b643dbacbaee91ec59b01ffb2.jpg', '<p>Jerry – một ông bố đơn thân đầy bất ổn – dạy con trai mình rằng luật pháp chỉ là ảo ảnh và tự do là thứ phải giành lấy, không xin ai cả. Dần bị cuốn vào hệ tư tưởng cực đoan của phong trào &quot;công dân tối thượng&quot;, cha con Jerry lún sâu vào con đường chống đối xã hội. Nhưng khi họ chạm trán với một vị trưởng cảnh sát cả đời bảo vệ pháp luật, cuộc đối đầu giữa hai thế giới quan – một bên là trật tự, một bên là hỗn loạn – trở nên không thể tránh khỏi.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Nick Offerman","avatar":""},{"name":"Jacob Tremblay","avatar":""},{"name":"Dennis Quaid","avatar":""},{"name":"Kezia Dacosta","avatar":""},{"name":"Terry J. Nelson","avatar":""},{"name":"Bobby Gilchrist","avatar":""},{"name":"Megan Mullally","avatar":""},{"name":"Ruby Wolf","avatar":""},{"name":"Buddy Campbell","avatar":""},{"name":"Tommy Kramer","avatar":""},{"name":"Jared Carter","avatar":""},{"name":"Jennifer Nesbitt-Eck","avatar":""},{"name":"Mike L. Thomas","avatar":""},{"name":"Cheryl Vanwinkle","avatar":""},{"name":"Jason Cochrane","avatar":""},{"name":"Chris Greene","avatar":""},{"name":"Jade","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sovereign"]', 1784690324152);
