INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-nuoi', 'Con Nuôi', 'The Other', 'https://phimimg.com/upload/vod/20250717-1/0e32e4dd989dd10bda1a30449b4ab5ae.jpg', 'https://phimimg.com/upload/vod/20250717-1/bbcba1b0e9f8a9cca7de5429a3afea2e.jpg', '<p>Họ muốn cứu một đứa trẻ. Không ngờ, chính điều đó sẽ hủy diệt họ. Khao khát làm cha mẹ, một cặp đôi nhận nuôi một bé mồ côi mang quá khứ bi kịch. Nhưng hành động xuất phát từ tình yêu ấy nhanh chóng biến thành cơn ác mộng khi họ nhận ra: quá khứ đầy bạo lực của đứa trẻ đang quay trở lại, đe dọa phá hủy tất cả khiến cho mái ấm họ cố gắng xây dựng dần bị bóp nghẹt bởi sự kinh hoàng mà họ chưa từng tưởng tượng.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Olivia Macklin","avatar":""},{"name":"Dylan McTee","avatar":""},{"name":"Avangeline Friedlander","avatar":""},{"name":"Shawnee Smith","avatar":""},{"name":"Lily D. Moore","avatar":""},{"name":"Morgana Shaw","avatar":""},{"name":"Denise Lee","avatar":""},{"name":"Laurence Pete","avatar":""},{"name":"Aly Mawji","avatar":""},{"name":"Indiana Arnold","avatar":""},{"name":"Morgan Boss-Maltais","avatar":""},{"name":"Jessica Culaciati","avatar":""},{"name":"Colin Haag Jr.","avatar":""},{"name":"Elijah Johnson-Thiam","avatar":""},{"name":"Phuong Kubacki","avatar":""},{"name":"Kinley Moo","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Psychopomp","Другая","The Other (aka Psychopomp)","The Other"]', 1784690324152);
