INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-em', 'Yêu Em', 'The Best Thing', 'https://phimimg.com/upload/vod/20250225-1/9f329ffa86a6864c723ff4b843e0fc1a.jpg', 'https://phimimg.com/upload/vod/20250225-1/b99a2232b64a0692c456f2476c317f59.jpg', '<p>Phim kể về mối quan hệ giữa Thẩm Tích Phàm, một quản lý khách sạn đam mê công việc, và Hà Tô Diệp, một bác sĩ Đông y điềm đạm. Vì chứng mất ngủ, cô tìm đến Đông y và tình cờ gặp anh. Ban đầu chỉ là bác sĩ và bệnh nhân, nhưng những lần chạm mặt bất ngờ dần kéo họ lại gần nhau. Khi tình cảm nảy nở, cả hai phải đối mặt với những do dự từ quá khứ và dần tìm thấy ý nghĩa thực sự của tình yêu và đam mê của mình.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 6, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Lăng Hách","avatar":""},{"name":"Từ Nhược Hàm","avatar":""},{"name":"Đường Cửu Châu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Най-хубавото нещо в живота ми","爱你是我做过最好的事","Ai Ni","Ai Ni Shi Wo Zuo Guo Zui Hao De Shi","爱你","爱你，是我做过最好的事","爱上你是我做过最好的事","รักเธอที่สุดเลย","Loving You is the Best Thing I Have Ever Done","For Love","Loving You is the Best Thing I Have Done","The Best Thing"]', 1784690324152);
