INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('m3gan-20', 'M3GAN 2.0', 'M3GAN 2.0', 'https://phimimg.com/upload/vod/20250703-1/028ccaec4c6b3e5f7fe6d5307bc4194f.jpg', 'https://phimimg.com/upload/vod/20250703-1/0d02468942825692f37b9d9a4722254c.jpg', '<p>MEGAN 2.0 lấy bối cảnh 2 năm sau các sự kiện ở phần 1. Lúc này, Gemma phát hiện công nghệ sản xuất MEGAN đã bị đánh cắp. Kẻ gian đã tạo ra một robot AI khác với chức năng tương tự MEGAN, nhưng được trang bị sức mạnh chiến đấu &quot;khủng&quot; hơn mang tên Amelia. Để &quot;đối đầu&quot; với Amelia, Gemma buộc phải &quot;hồi sinh&quot; và cải tiến MEGAN, hứa hẹn một trận chiến &quot;nảy lửa&quot; trên màn ảnh vào năm 2025.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jenna Davis","avatar":""},{"name":"Allison Williams","avatar":""},{"name":"Violet McGraw","avatar":""},{"name":"Ivanna Sakhno","avatar":""},{"name":"Amie Donald","avatar":""},{"name":"Brian Jordan Alvarez","avatar":""},{"name":"Jen Van Epps","avatar":""},{"name":"Aristotle Athari","avatar":""},{"name":"Timm Sharp","avatar":""},{"name":"Jemaine Clement","avatar":""},{"name":"Mayen Mehta","avatar":""},{"name":"Mike Edward","avatar":""},{"name":"Ara Raad","avatar":""},{"name":"Simon Eskow","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["M3GAN 2","Megan 2","窒友梅根 2.0","ミーガン 2.0","人工殺姬 2.0","М3ГАН 2.0","MΞGAN 2.0","მეგანი 2","მ3განი 2","梅根2","megan 2.0","M3GAN 2.0"]', 1784690324152);
