INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-le-yeu-em-2025', 'Lặng Lẽ Yêu Em', 'Secretly Loving You', 'https://phimimg.com/upload/vod/20250715-1/5de63e63aeb9a24676b15c4fc1d6dfdb.jpg', 'https://phimimg.com/upload/vod/20250715-1/624b388c402b571ac219b93043e0705c.jpg', '<p>Hạ Lăng Phi, một cô gái nhà giàu tiêu tiền như nước, đã phải chia tay đột ngột với bạn trai sinh viên sau khi gia đình cô phá sản. Nhưng thực tế, Lục Diệc Thần lại là người con hào môn bị ruồng bỏ, sau khi bị đuổi đi đã vươn lên trở thành một tổng tài lạnh lùng, quyết đoán. Nhiều năm sau, họ tái ngộ tại một bữa tiệc rượu. Lúc này, Hạ Lăng Phi đã trở thành một tiểu thư sa cơ, đang bận rộn lo cho vị hôn phu của mình. Trong đáy mắt Lục Diệc Thần, tình và hận cuộn trào - khi cô quyết liệt rời đi năm đó, liệu cô có từng nghĩ đến anh, người đã bị cô vứt bỏ hay không.</p>', 'Hoàn Tất (65/65)', 65, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Khưu Hồng Khải","avatar":""},{"name":"Hàn Vũ Đồng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324152);
