INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muoi-nam-khuynh-thanh', 'Mười Năm Khuynh Thành', 'Ten Years Of Unrequited Love', 'https://phimimg.com/upload/vod/20250704-1/d9363c24299214ebd99e50c340ef375b.jpg', 'https://phimimg.com/upload/vod/20250704-1/b8a8d6cf2ac367640b5288e859d9681a.jpg', '<p>Mười năm trước, Lâm Miểu Miểu đau đớn buông tay Sầm Tư Viễn vì khoảng cách giai tầng gia đình. Mười năm sau, Sầm Tư Viễn đã trở thành tổng giám đốc tập đoàn cà phê, sắp cưới minh tinh Tô Bái Bái; còn Lâm Miểu Miểu lại trở thành thư kí đắc lực của mẹ anh. Một cuộc khủng hoảng thương mại khiến cả hai lại cùng nhau hợp tác, chân tướng và tình cũ đồng thời lộ ra. Họ cùng nhau vượt qua trở ngại và cuối cùng tái hợp.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hà Sưởng Hy","avatar":""},{"name":"Thiệu Vũ Thất","avatar":""},{"name":"Phan Tử Kiếm","avatar":""},{"name":"Quách Gia Ngữ","avatar":""},{"name":"Vương Trạch Hiên","avatar":""},{"name":"Nguỵ Thần Phi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shi Nian Qing Cheng","십년경성: 10년의 기다림","十年倾城"]', 1784690324152);
