INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('muoi-nam-khuynh-thanh', 'Mười Năm Khuynh Thành', 'Ten Years Of Unrequited Love', 'mười năm khuynh thành ten years of unrequited love hà sưởng hy thiệu vũ thất phan tử kiếm quách gia ngữ vương trạch hiên nguỵ thần phi shi nian qing cheng 십년경성: 10년의 기다림 十年倾城', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-than-bien-phan-6', 'Tinh Thần Biến (Phần 6)', 'Stellar Transformation (Season 6)', 'https://phimimg.com/upload/vod/20250224-1/54ff622eb290901067c6496ce99b410e.jpg', 'https://phimimg.com/upload/vod/20250224-1/bbc943b61e298d81026844e864256f49.jpg', '<p>Tần Vũ cùng ba huynh đệ phi thăng lên Thần Giới. Sau khi dần tìm hiểu quy tắc nơi đây, để có thể cưới được Khương Lập – thiên kim của Khương gia, một trong bát đại gia tộc của Thần Giới, có thân phận chênh lệch rất lớn so với mình – Tần Vũ quyết chí trở thành Tượng Thần. Từ việc tiêu diệt sơn tặc, hắn từng bước tích lũy thực lực, trở thành Thần Nhân Thượng Cấp, được Thánh Hoàng coi trọng, trở thành tân quý trong Thần Giới. Sau bao năm nỗ lực không ngừng, cuối cùng hắn cũng đạt được thân phận xứng đáng để quang minh chính đại cầu hôn Lập Nhi. Nhưng đúng lúc này, đối diện với hàng loạt cường giả theo đuổi Khương Lập, Khương gia không thể đưa ra quyết định nên đã tổ chức chiêu thân. Bất kỳ ai có thể dâng lên ba món sính lễ áp đảo toàn bộ đối thủ khác sẽ giành được Khương Lập. Tần Vũ dốc lòng nghiên cứu, vượt qua muôn vàn gian nan, cuối cùng luyện chế ra một món Hồng Mông linh bảo tuyệt thế chưa từng xuất hiện, dùng làm sính lễ để dâng lên Khương gia. Những tưởng đã nắm chắc phần thắng, không ngờ vào phút cuối, Khương gia lại lật kèo, tuyên bố Chu Hiển thắng cuộc.</p>', 'Hoàn Tất (28/28)', 28, 'hoathinh', 'completed', 8, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Yuan Weng","avatar":""},{"name":"Shen Dawei","avatar":""},{"name":"Jingxia Liu","avatar":""},{"name":"Liu Yuxuan","avatar":""},{"name":"Muqing Ke","avatar":""},{"name":"Ming Zhao","avatar":""},{"name":"Xia Lei","avatar":""},{"name":"Hongbo Guo","avatar":""},{"name":"Qingqing Du","avatar":""},{"name":"Jackwin","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Stellar Transformations","Legend of Immortals","Xingchen Bian","Xing Chen Bian","Stellar Transformation","星辰變","星辰变"]', 1784690324152);
