INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-tan-the-vung-nhiet-doi', 'Ngày Tận Thế Vùng Nhiệt Đới', 'Apocalypse In The Tropics', 'https://phimimg.com/upload/vod/20250715-1/4f0ee650ee93eda297f09d55cc025c88.jpg', 'https://phimimg.com/upload/vod/20250715-1/9cb129c76b8d96b1f3c2f19363bb1f85.jpg', '<p>Bộ phim tài liệu này của Petra Costa – nữ đạo diễn từng được đề cử giải Oscar – đi sâu khám phá tác động mạnh mẽ của đạo Tin Lành đến bối cảnh chính trị của Brazil.</p>', 'Full', 1, 'single', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Brazil', 0, '[{"name":"Silas Malafaia","avatar":""},{"name":"Elizete Malafaia","avatar":""},{"name":"Jair Bolsonaro","avatar":""},{"name":"Luiz Inácio Lula da Silva","avatar":""},{"name":"Petra Costa","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Apocalipse nos Trópicos"]', 1784690324152);
