INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-pho-tau-1900', 'Thám Tử Phố Tàu 1900', 'Detective Chinatown 1900', 'https://phimimg.com/upload/vod/20250514-1/5aaded25f85c5232d12f9aab72bb55db.jpg', 'https://phimimg.com/upload/vod/20250514-1/1f8c50b1bda33f64bf6e3757eb6d6cf8.jpg', '<p>Từ lần ra manh mối tới né hiểm nguy, hai thám tử bất đắc dĩ chạy đua với thời gian để phá vụ án mạng của con gái ngài nghị sĩ trước khi ông ra tay xóa sổ Phố người Hoa.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Bảo Cường","avatar":""},{"name":"Lưu Hạo Nhiên","avatar":""},{"name":"Châu Nhuận Phát","avatar":""},{"name":"Bạch Khách","avatar":""},{"name":"Trương Tân Thành","avatar":""},{"name":"Nhạc Vân Bằng","avatar":""},{"name":"John Cusack","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["唐人街探案1900","唐人街探案前传","唐探前传","Detective Chinatown 1900","Tang Ren Jie Tan an 1900","唐探1900","Детектив из Чайнатауна, 1900 год"]', 1784690324152);
