INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tham-tu-pho-tau-1900', 'Thám Tử Phố Tàu 1900', 'Detective Chinatown 1900', 'thám tử phố tàu 1900 detective chinatown 1900 vương bảo cường lưu hạo nhiên châu nhuận phát bạch khách trương tân thành nhạc vân bằng john cusack 唐人街探案1900 唐人街探案前传 唐探前传 detective chinatown 1900 tang ren jie tan an 1900 唐探1900 детектив из чайнатауна, 1900 год', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-chao-the-gioi-cua-toi', 'Xin Chào Thế Giới Của Tôi', 'Dream Beyond', 'https://phimimg.com/upload/vod/20250711-1/2660d1519cfe4a76660bba1f14e2efe8.jpg', 'https://phimimg.com/upload/vod/20250711-1/ec0ad4fc7b9cef89f7475bd5487e5bdd.jpg', '<p>Cố Niệm vì muốn được ở bên bạn trai người nước ngoài nên quyết định du học. Cô đăng ký qua một công ty tư vấn du học tên “LZ” trên mạng, nhưng lại phát sinh mâu thuẫn với bà chủ công ty Lâm Dao và bạn trai của bà – Trác Bằng. Nguyên nhân là do Lâm Dao, dù công ty đang thiếu nhân lực, vẫn nhận đơn hàng của Cố Niệm. Trác Bằng – vốn là người đại diện pháp lý nhưng không trực tiếp làm việc – buộc phải trở thành gia sư tạm thời cho Cố Niệm. Nhờ sự giúp đỡ của anh, cô đã thành công trở thành du học sinh của trường Đại học A. Không lâu sau đó, Lâm Dao và Trác Bằng chia tay. Trác Bằng được mời làm chuyên gia tư vấn tâm lý cho du học sinh tại Đại học A. Anh nhận ra rằng, nhóm sinh viên quốc tế gặp không ít vấn đề về tâm lý, cuộc sống và học tập do không thích nghi được với môi trường mới. Vì vậy, anh quyết định thành lập một tổ chức tư vấn du học phi lợi nhuận, thực sự giúp đỡ sinh viên tìm được ngôi trường phù hợp với bản thân, học thành tài và quay về xây dựng quê hương. Mục tiêu này tình cờ cũng trùng hợp với lý tưởng của Cố Niệm. Cuối cùng, hai người không chỉ trở thành bạn đồng hành trong công việc, mà còn nên duyên làm người yêu.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Aarif Rahman","avatar":""},{"name":"Xu Lu","avatar":""},{"name":"Chen Miqi","avatar":""},{"name":"Hu Rongrong","avatar":""},{"name":"Cai Die","avatar":""},{"name":"Gan Yunchen","avatar":""},{"name":"Liu Qiushi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["藤科动物也凶猛","Ivy Monsters","Hi My World","我的世界你好"]', 1784690324152);
