INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('xin-chao-the-gioi-cua-toi', 'Xin Chào Thế Giới Của Tôi', 'Dream Beyond', 'xin chào thế giới của tôi dream beyond aarif rahman xu lu chen miqi hu rongrong cai die gan yunchen liu qiushi 藤科动物也凶猛 ivy monsters hi my world 我的世界你好', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-trai-bang-coc', 'Chàng Trai Băng Cốc', 'The Bangkokboy Series (Uncut Ver.)', 'https://phimimg.com/upload/vod/20250505-1/6e9dbf70735842c04abd88688f8213f3.jpg', 'https://phimimg.com/upload/vod/20250505-1/7e3f6bdf49ad444f5efd620f1795da6b.jpg', '<p>Sun mãn hạn tù, mang theo lòng căm hận ngút trời đối với kẻ thù đã giết cha và bạn mình. Tại Bangkok, anh thành lập một tổ chức tên là &quot;Thiếu Niên Bangkok&quot;, vừa mở rộng thế lực, vừa tích cực tìm kiếm manh mối về kẻ thù năm xưa.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Worrachai Sirikongsuwan","avatar":""},{"name":"Cho Sihyun","avatar":""},{"name":"Choi Seung-ho","avatar":""},{"name":"Top Piyawat Phongkanittanon","avatar":""},{"name":"Aton Thanakorn Techawicha","avatar":""},{"name":"Dom Petchtamrongchai","avatar":""},{"name":"Praphoom Vasuratna","avatar":""},{"name":"Paythai Ploymeeka","avatar":""},{"name":"Jinjutha Siripheng","avatar":""},{"name":"Truly Phuntipa Pongruangrong","avatar":""},{"name":"Khongkhwan Woraphat","avatar":""},{"name":"Mai Bodinphat","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["บางกอกบอย"]', 1784690324152);
