INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huong-vi-cua-bien-mua-2', 'Hương Vị Của Biển (Mùa 2)', 'Fresh Off The Sea (Season 2)', 'https://phimimg.com/upload/vod/20250415-1/bec18f85c04cfddb6245b430771d3e71.jpg', 'https://phimimg.com/upload/vod/20250415-1/1f3dc849f9cd12e9014e5ced9c0f774b.jpg', '<p>Mùa thứ hai trở lại với chị đẹp Yum Jung Ah, &quot;cây hài&quot; Park Jun Myun cùng hai thành viên mới là diễn viên Lim Ji Yeon và Lee Jae Wook. Họ sẽ cùng khám phá những điểm đến mới, tự tay khai thác những nguyên liệu tươi ngon theo mùa và quây quần bên những bữa ăn ấm cúng.</p>', 'Hoàn Tất (13/13)', 13, 'tvshows', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Jun Myun","avatar":""},{"name":"Lim Ji Yeon","avatar":""},{"name":"Yum Jung Ah","avatar":""},{"name":"Lee Jae Wook","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["언니네 산지직송 in 칼라페","姐姐們的產地直送","Direct delivery from my sister’s place","Fresh of the Sea","언니네 산지직송"]', 1784690324152);
