INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('huong-vi-cua-bien-mua-2', 'Hương Vị Của Biển (Mùa 2)', 'Fresh Off The Sea (Season 2)', 'hương vị của biển (mùa 2) fresh off the sea (season 2) park jun myun lim ji yeon yum jung ah lee jae wook 언니네 산지직송 in 칼라페 姐姐們的產地直送 direct delivery from my sister’s place fresh of the sea 언니네 산지직송', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-than-tuong', 'Trò Chơi Thần Tượng', 'The Idol Game', 'https://phimimg.com/upload/vod/20250519-1/83924bbce30105cac47c276d8052f0cc.jpg', 'https://phimimg.com/upload/vod/20250519-1/8ae088acdb4fa13652e1e5c3d037b109.jpg', '<p>Trong ngành phẫu thuật thẩm mỹ đang bùng nổ tại Thái Lan, một gia đình bác sĩ danh giá nắm giữ quyền lực tối thượng. Thành công và ảnh hưởng to lớn mang lại cho họ khối tài sản khổng lồ — nhưng cũng thổi bùng những mâu thuẫn sâu sắc trong nội bộ. Ở trung tâm của cuộc đấu tranh là bác sĩ Thicha, người chị cả đầy tham vọng và toan tính, quyết tâm mở rộng di sản gia đình bằng mọi giá. Đối đầu với cô là bác sĩ Tan, cậu em út đang chật vật tìm kiếm chỗ đứng và bản sắc riêng giữa những kỳ vọng đè nặng từ gia tộc. Khi mâu thuẫn nội bộ chưa kịp lắng xuống, một mối đe dọa còn lớn hơn xuất hiện từ không gian mạng. Itthichai, hay còn gọi là “It,” một lập trình viên thiên tài làm việc cho cơ quan chính phủ, bị cuốn vào một cuộc điều tra rùng rợn. Từ một vụ án tội phạm mạng, anh dần phát hiện ra mối liên hệ đáng sợ giữa thế giới ngầm công nghệ và mặt tối của ngành phẫu thuật thẩm mỹ. Những bí mật bị phơi bày đe dọa không chỉ tương lai của gia đình mà còn cả sự minh bạch của toàn bộ ngành công nghiệp này.</p>', 'Tập 4', 12, 'series', 'ongoing', 12, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Bee Namthip Jongrachatawiboon","avatar":""},{"name":"James Ma","avatar":""},{"name":"Woonsen Virithipa Pakdeeprasong","avatar":""},{"name":"Pei Panward Hemmanee","avatar":""},{"name":"Pei Panward Hemmanee","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324152);
