INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-lai-thoi-muromachi', 'Vô Lại Thời Muromachi', 'Muromachi Burai', 'https://phimimg.com/upload/vod/20250714-1/ae65ce855b153f7828d8101302c2104f.jpg', 'https://phimimg.com/upload/vod/20250714-1/df3b4a0d0f073a416dac271d651ff86d.jpg', '<p>Trong khung cảnh hỗn loạn của Kyoto thế kỷ 15, khi chiến tranh Onin đang cận kề, một nhóm thảo khấu do kiếm khách lừng danh Hyoe lãnh đạo đã nổi dậy chống lại chế độ Mạc phủ mục nát. Đứng đầu chiến tuyến, Hyoe không chỉ phải đối mặt với binh lính triều đình mà còn phải chạm trán với kẻ thù nguy hiểm nhất: Doken – người bạn cũ từng vào sinh ra tử, nay trở thành đối thủ khốc liệt nhất.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yo Oizumi","avatar":""},{"name":"Kento Nagao","avatar":""},{"name":"Wakana Matsumoto","avatar":""},{"name":"Yuya Endo","avatar":""},{"name":"Tomoya Maeno","avatar":""},{"name":"Ami201","avatar":""},{"name":"Hannya","avatar":""},{"name":"Rina Takeda","avatar":""},{"name":"Shingo Mizusawa","avatar":""},{"name":"Joey Iwanaga","avatar":""},{"name":"Miyu Yoshimoto","avatar":""},{"name":"Donpei Tsuchihira","avatar":""},{"name":"Tateto Serizawa","avatar":""},{"name":"Takuo Inari","avatar":""},{"name":"Aoi Nakamura","avatar":""},{"name":"Kenichi Yajima","avatar":""},{"name":"Hiroki Miyake","avatar":""},{"name":"Akira Emoto","avatar":""},{"name":"Kazuk","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["무로마치 무뢰","متمردو موروماتشي","Muromachi Burai","Muromachi Outsiders","Bunt","Samurai Fury","Отступники Мурома