INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('zombies-4-binh-minh-ma-ca-rong', 'ZOMBIES 4: Bình Minh Ma Cà Rồng', 'Z-O-M-B-I-E-S 4: Dawn Of The Vampires', 'https://phimimg.com/upload/vod/20250714-1/7c143d94760e5ab7c111066397be0d89.jpg', 'https://phimimg.com/upload/vod/20250714-1/7b6015c02e40df79259533b297c6634f.jpg', '<p>Một cuộc phiêu lưu mới bắt đầu với Zed và Addison khi chuyến đi chơi hè của họ bất ngờ rẽ hướng, đưa họ rơi vào giữa một cuộc đối đầu giữa hai thế lực quái vật: Daywalker và Ma cà rồng. Căng thẳng leo thang khi Zed và Addison bị cuốn vào vai trò làm cố vấn trại hè cho hai phe siêu nhiên đối địch. Với sự giúp sức của Eliza và Willa, họ phải thuyết phục hai kẻ thù truyền kiếp Nova và Victor hợp tác, trước khi một mối đe dọa còn lớn hơn khiến cả hai thế giới bị hủy diệt.</p>', 'Full', 1, 'single', 'completed', 18, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Milo Manheim","avatar":""},{"name":"Meg Donnelly","avatar":""},{"name":"Chandler Kinney","avatar":""},{"name":"Kylee Russell","avatar":""},{"name":"Freya Skye","avatar":""},{"name":"Malachi Barton","avatar":""},{"name":"Julian Lerner","avatar":""},{"name":"Swayam Bhatia","avatar":""},{"name":"Mekonnen Knife","avatar":""},{"name":"Jonno Roberts","avatar":""},{"name":"Lisa Chappell","avatar":""},{"name":"Mana Tatafu","avatar":""},{"name":"Lilac Encina","avatar":""},{"name":"Karlton Laing","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b