INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duoi-tang-y-thuc', 'Dưới Tầng Ý Thức', 'Destiny Switch', 'https://phimimg.com/upload/vod/20250704-1/8149f75ade82f62bf810c63106ff1c47.jpg', 'https://phimimg.com/upload/vod/20250704-1/a762dddf9b7249db8ac9065febd5def2.jpg', '<p>Pháp sư thời không La Kiếp vô tình xuyên không, trở thành A Lãng - con riêng của nhà tài phiệt, năng lực ý thức của anh biến thành đồng hồ bỏ túi thời gian. Để tìm ra sự thật về cái chết của mình, anh bị cuốn vào cuộc đấu tranh quyền của Càn Bang, quen biết cảnh sát Diệp Tư Gia và Tiểu Thất tinh ranh, nhưng bị nhiều thế lực truy đuổi. La Kiếp phát hiện ra rằng kẻ chủ mưu đằng sau có mối liên hệ chặt chẽ với &quot;Một Lời Khiêm Tốn&quot; và thảm họa tương lai...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đại Cao Chính","avatar":""},{"name":"Hà Tử Di","avatar":""},{"name":"Phạm Vi","avatar":""},{"name":"Vương Húc Đông","avatar":""},{"name":"Hướng Hân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yi Neng Zhi Xia","我主此劫","意能之下"]', 1784690324152);
