INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-tim-nam-chinh', 'Truy Tìm Nam Chính', 'Lead Male Character Search (Nam Joo Search)', 'https://phimimg.com/upload/vod/20250629-1/a1f2f4c56440aa12f550b393c602b19c.jpg', 'https://phimimg.com/upload/vod/20250629-1/42c96eb4516c0fdc1bbd21c79069cb1b.jpg', '<p>Oh Seol-Rem từng là học sinh đứng đầu khối tại trường cấp ba. Nhưng sau khi nghiện game, cô trượt đại học. Seol-Rem quyết tâm học lại để thi vào trường đại học. Trong game, cô làm quen với một nhân vật nam có tên Tarakexcali và đem lòng yêu anh — dù chưa từng gặp mặt, chỉ biết rằng anh học ở Đại học Ganghan. Hai người thậm chí còn hứa sẽ kết hôn. Thế nhưng, một ngày nọ, Tarakexcali đột nhiên biến mất khỏi game. Seol-Rem quyết định ngắt kết nối với thế giới ảo, chuyên tâm học tập. Cuối cùng, cô thi đỗ vào chính ngôi trường mà Tarakexcali theo học ngoài đời. Giờ đây, Seol-Rem bắt đầu hành trình đi tìm chàng trai bí ẩn năm xưa...</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kal So‑won","avatar":""},{"name":"Lee Jin‑woo","avatar":""},{"name":"Cha Jun‑ho","avatar":""},{"name":"Seong Tae","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324152);
