INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-anh-trai-7-chau-1-kakak-7-ponakan', 'Một Anh Trai 7 Cháu (1 Kakak 7 Ponakan)', 'A Brother And 7 Siblings', 'https://phimimg.com/upload/vod/20250712-1/f008d70a43e87fee5e3bb3e07b1c263c.jpg', 'https://phimimg.com/upload/vod/20250712-1/e483458fb92178e3dfc51b8be9bdcd48.jpg', '<p>Sau cái chết đột ngột của các anh chị mình, một kiến trúc sư trẻ đang gặp khó khăn bất ngờ trở thành &quot;người cha đơn thân&quot; của các cháu trai. Khi cơ hội cho một cuộc sống tốt đẹp hơn đến, anh phải lựa chọn giữa tình yêu, sự nghiệp, hay những đứa cháu của mình.</p>', 'Full', 1, 'single', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Indonesia', 0, '[{"name":"Chicco Kurniawan","avatar":""},{"name":"Amanda Rawles","avatar":""},{"name":"Fatih Unru","avatar":""},{"name":"Freya Jayawardana","avatar":""},{"name":"Ahmad Nadif","avatar":""},{"name":"Kawai Labiba","avatar":""},{"name":"Niken Anjani","avatar":""},{"name":"Ringgo Agus Rahman","avatar":""},{"name":"Kiki Narendra","avatar":""},{"name":"Maudy Koesnaedi","avatar":""},{"name":"Ence Bagus","avatar":""},{"name":"Tahlia Motik","avatar":""},{"name":"Sarah Mawla","avatar":""},{"name":"Sheila Dara","avatar":""},{"name":"David Brendi","avatar":""},{"name":"Chandra Satria","avatar":""},{"name":"Reza Nangin","avatar":""},{"name":"Kar","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Satu Kakak Tujuh Ponakan","A Brother and Seven Siblings","SaKaTuPo","1K7P","One Brother Seven Nephews and Nieces","ខ្សែរជីវិតក