INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-goi-khan-cap-911-ngoi-sao-don-doc-phan-5', 'Cuộc Gọi Khẩn Cấp 9-1-1: Ngôi Sao Đơn Độc (Phần 5)', '9-1-1: Lone Star (Season 5)', 'https://phimimg.com/upload/vod/20250711-1/a8c8599df83d07e1575abb7aae87c0ca.jpg', 'https://phimimg.com/upload/vod/20250711-1/ac6b72969e85ab0bf0c650beeff33f2e.jpg', '<p>Gần 20 năm trước, Owen Strand là người sống sót duy nhất trong đội cứu hỏa Manhattan sau vụ tấn công ngày 11/9. Sau thảm kịch đó, Owen phải gánh vác trọng trách tái xây dựng trạm cứu hỏa của mình. Khi một bi kịch tương tự xảy ra với một trạm cứu hỏa ở Austin, Owen cùng cậu con trai T.K. – một lính cứu hỏa gặp nhiều vấn đề tâm lý – chuyển đến Texas, mang theo những triết lý tiến bộ về cuộc sống và công việc để giúp đội ngũ nơi đây bắt đầu lại từ đầu. Bề ngoài, Owen là hình mẫu của phong cách thành thị hiện đại và sự tự tin, nhưng ẩn sâu bên trong, anh đang che giấu một bí mật có thể đe dọa đến tính mạng của mình.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rob Lowe","avatar":""},{"name":"Gina Torres","avatar":""},{"name":"Ronen Rubinstein","avatar":""},{"name":"Jim Parrack","avatar":""},{"name":"Natacha Karam","avatar":""},{"name":"Brian Michael Smith","avatar":""},{"name":"Rafael L. Silva","avatar":""},{"name":"Julian Works","avatar":""},{"name":"Brianna Baker","avatar":""},{"name":"Skyler Yates","avatar":""},{"name":"Kelsey Yates","avatar":""},{"name":"Jackson Pace","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["911: Тексас","911 - Lone Star","911 : Texas","9-1-1：ローンスター","9‐1‐1 – Teksas","9-1-1 – Teksas","9-1-1: Одинокая звезда","9-1-1: Lone Star"]', 1784690324152);
