INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-goi-khan-cap-911-ngoi-sao-don-doc-phan-5', 'Cuộc Gọi Khẩn Cấp 9-1-1: Ngôi Sao Đơn Độc (Phần 5)', '9-1-1: Lone Star (Season 5)', 'cuộc gọi khẩn cấp 9-1-1: ngôi sao đơn độc (phần 5) 9-1-1: lone star (season 5) rob lowe gina torres ronen rubinstein jim parrack natacha karam brian michael smith rafael l. silva julian works brianna baker skyler yates kelsey yates jackson pace 911: тексас 911 - lone star 911 : texas 9-1-1：ローンスター 9‐1‐1 – teksas 9-1-1 – teksas 9-1-1: одинокая звезда 9-1-1: lone star', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-quyen-nhat-mong', 'Thư Quyển Nhất Mộng', 'A Dream Within A Dream', 'https://phimimg.com/upload/vod/20250626-1/d8330de82092ada5f31c243407995b3d.jpg', 'https://phimimg.com/upload/vod/20250626-1/3fbbea7d1583b917b930b11f28972a1a.jpg', '<p>Phim kể về Tống Tiểu Ngư, một cô gái hiện đại vô tình xuyên không vào thế giới kịch bản, trở thành nữ chính bị nam phản diện “dùng xong là vứt”, hành hạ đến chết. Không cần suy nghĩ, cô chọn cách duy nhất: chạy càng xa càng tốt! Kế hoạch nghe thì hoàn hảo, nhưng hiện thực lại đầy tàn khốc. Mỗi lần cô cố thay đổi cốt truyện để kết hôn với nam phụ, hệ thống lại lập tức đưa cô vào vòng lặp vô hạn, mắc kẹt trong những lỗ hổng kịch bản, khiến cô trải qua 108 kiểu chết không trùng nhau, đúng nghĩa vừa vào game là toi mạng. Cuối cùng, Tống Tiểu Ngư buộc phải chấp nhận sự thật dù có cố gắng thế nào, cốt truyện vẫn sẽ đẩy cô về bên nam chính Nam Hành, và ép cô tái hiện từng cảnh trong kịch bản. Trong thế giới kịch bản này còn có vô số nhân vật bị định sẵn kết cục. Có người mắc kẹt trong cung cấm, có người bị trói buộc bởi danh gia vọng tộc, có người bị mệt mỏi vì tranh giành nam nhân, có người sống chết vì quyền thế, có người khao khát yêu và tự do nhưng lại chỉ có thể bị trói buộc bất an bước tiếp, có người ôm giấc mộng bay cao như đại bàng cưỡi gió nhưng lại bị những ràng buộc và tầm thường lặp đi lặp lại mỗi ngày bào mòn ý chí và đam mê. Đây không đơn thuần là cuộc đối đầu giữa Tống Tiểu Ngư, kẻ chỉ muốn nằm im sống qua ngày và Nam Hành, kẻ máu lạnh chỉ biết tranh đấu, mà còn là cuộc chiến của mỗi “cái tôi nhỏ bé” trong thế giới hư cấu chống lại định mệnh được lập định sẵn.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 12, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Nhất Đồng","avatar":""},{"name":"Lưu Vũ Ninh","avatar":""},{"name":"Chúc Tứ Đan","avatar":""},{"name":"Vương Dĩ Luân","avatar":""},{"name":"Vương Hựu Thác","avatar":""},{"name":"Sung Long","avatar":""},{"name":"Lữ Hành","avatar":""},{"name":"Trương Lễ","avatar":""},{"name":"Hoàng Vĩ Đức","avatar":""},{"name":"Vương Diện Nhi","avatar":""},{"name":"Trịnh Quốc Lâm","avatar":""},{"name":"Trần Tử Hàm","avatar":""},{"name":"Giả Cảnh Huy","avatar":""},{"name":"Vương Thành Tư","avatar":""},{"name":"Tô Mộng Vân","avatar":""},{"name":"Vương Lệ Na","avatar":""},{"name":"Lý Khinh","avatar":""},{"name":"Quách Tiếu Thiên","avatar":""},{"name":"Lăng Mỹ Sĩ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["书卷一梦","서권일몽: 악덕 남주를 사랑하게 되었다","Книга грёз","Сон во сне","คัมภีร์ร่วมฝัน","A Dream Within a Dream"]', 1784690324152);
