INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thu-quyen-nhat-mong', 'Thư Quyển Nhất Mộng', 'A Dream Within A Dream', 'thư quyển nhất mộng a dream within a dream lý nhất đồng lưu vũ ninh chúc tứ đan vương dĩ luân vương hựu thác sung long lữ hành trương lễ hoàng vĩ đức vương diện nhi trịnh quốc lâm trần tử hàm giả cảnh huy vương thành tư tô mộng vân vương lệ na lý khinh quách tiếu thiên lăng mỹ sĩ 书卷一梦 서권일몽: 악덕 남주를 사랑하게 되었다 книга грёз сон во сне คัมภีร์ร่วมฝัน a dream within a dream', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-tuoc-duong', 'Chu Tước Đường', 'Rosefinch', 'https://phimimg.com/upload/vod/20250704-1/43e96d8c1ae458ab92c74d5354b2e5e4.jpg', 'https://phimimg.com/upload/vod/20250704-1/a8c98155774441da78602fd9b8a31f7b.jpg', '<p>Phong vân tụ hội, Thượng Hải đại lục ngầm cuồn cuộn sóng. Những chí sĩ nhiệt huyết, tập hợp tại Chu Tước Đường, so tài đối quyết, điều tra chân tướng. Liệu họ có thể xoay chuyển càn khôn giữa thế lực cuồng phong?</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wan Qian","avatar":""},{"name":"Qin Junjie","avatar":""},{"name":"Lexuan Lin","avatar":""},{"name":"Guo Dongwen","avatar":""},{"name":"Rui Zhao","avatar":""},{"name":"Cheng Zi","avatar":""},{"name":"Zhang Cheng","avatar":""},{"name":"Wang Ting","avatar":""},{"name":"He Minghan","avatar":""},{"name":"Wang Qiang","avatar":""},{"name":"Zeng Yongti","avatar":""},{"name":"Chen Siche","avatar":""},{"name":"Tu Bing","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Zhu Que Tang","Rose Finch","朱雀堂"]', 1784690324152);
