INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chiec-xe-duster-phan-1', 'Chiếc Xe Duster (Phần 1)', 'Duster (Season 1)', 'https://phimimg.com/upload/vod/20250525-1/aff7f0d28e2f39291b17c2652f83abf9.jpg', 'https://phimimg.com/upload/vod/20250525-1/98c7ab07efc32955ce94e4e090d9e7fd.jpg', '<p>Lấy bối cảnh những năm 1970 ở vùng Tây Nam, bộ phim xoay quanh một tay lái xe đào tẩu cho một tổ chức tội phạm đang nổi lên, khi cuộc sống của anh chàng dần dần lún sâu vào vòng xoáy điên rồ và nguy hiểm qua mỗi phi vụ.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Josh Holloway","avatar":""},{"name":"Rachel Hilson","avatar":""},{"name":"Asivak Koostachin","avatar":""},{"name":"Sydney Elisabeth","avatar":""},{"name":"Benjamin Charles Watson","avatar":""},{"name":"Camille Guaty","avatar":""},{"name":"Adriana Aluna Martinez","avatar":""},{"name":"Greg Grunberg","avatar":""},{"name":"Keith David","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["风尘车手","Duster"]', 1784690324152);
