INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chiec-xe-duster-phan-1', 'Chiếc Xe Duster (Phần 1)', 'Duster (Season 1)', 'chiếc xe duster (phần 1) duster (season 1) josh holloway rachel hilson asivak koostachin sydney elisabeth benjamin charles watson camille guaty adriana aluna martinez greg grunberg keith david 风尘车手 duster', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-than-yeu', 'Bạn Thân Yêu', 'The Wonderful World', 'https://phimimg.com/upload/vod/20250630-1/fcadbc1baeb58ef22ed992bcf470caa2.jpg', 'https://phimimg.com/upload/vod/20250630-1/f54a76f8260541bcad2a6243a17a3c88.jpg', '<p>Chàng thanh niên Hàng Châu tên Từ Thiên từ nhỏ đã mất mẹ, từ bé anh đã tin rằng trên đời này tồn tại thế giới song song. Một ngày nọ, anh tình cờ lướt qua một người thanh niên Bắc Kinh tên Chu Đồng có gương mặt giống hệt mình, từ đó Từ Thiên bắt đầu hành trình tìm kiếm người lạ giống mình ấy. Nhờ buổi xem mắt, anh quen được Thạch Điển Điển, một cô gái thẳng thắn, và cô vui vẻ đồng ý giúp anh tìm kiếm Chu Đồng. Trong khi đó, Chu Đồng trên đường đi xem buổi biểu diễn của bạn gái Văn Tiểu Dao thì bất ngờ gặp tai nạn giao thông. Vào chính ngày hôm ấy, tình yêu của hai cặp đôi đã có bước ngoặt lớn. Trải qua những lần hội ngộ rồi chia ly, những cung bậc ngọt ngào lẫn cay đắng của tình yêu, Từ Thiên và Thạch Điển Điển dần tháo gỡ những khúc mắc trong lòng, cùng nhau chữa lành vết thương. Trong chuyện tình song phương của Chu Đồng và Văn Tiểu Dao, Văn Tiểu Dao cũng dần bước vào thời khắc huy hoàng của cuộc đời mình, trở thành một nghệ sĩ múa ba lê thực thụ.</p>', 'Hoàn Tất (29/29)', 29, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Nhất Sơn","avatar":""},{"name":"Lý Thấm","avatar":""},{"name":"Ruan Ju","avatar":""},{"name":"Liên Dật Minh","avatar":""},{"name":"Ngưu Lệ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Darling You","The Wonderful World","亲爱的你"]', 1784690324152);
