INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuot-moi-dia-hinh', 'Vượt Mọi Địa Hình', 'Off Road', 'https://phimimg.com/upload/vod/20250711-1/735a6f160e682342aec87c369f172c9e.jpg', 'https://phimimg.com/upload/vod/20250711-1/57babf23b0407061e415b43b302d24ba.jpg', '<p>Hai diễn viên Lior Raz (&quot;Hỗn loạn&quot;) và Rotem Sela (&quot;Đứa con và người thứ ba&quot;) khám phá văn hóa và vẻ đẹp của Trung Á – một hành trình thử thách tình bạn giữa họ.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Israel', 0, '[{"name":"Lior Raz","avatar":""},{"name":"Rotem Sela","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Off Road"]', 1784690324152);
