INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-chau-cua-moc-nhat-lam', 'Trân Châu Của Mộc Nhất Lâm', 'Mu Yilin''s Pearl', 'https://phimimg.com/upload/vod/20250711-1/6ebee49f5547ca4418f78762d3a1f43c.jpg', 'https://phimimg.com/upload/vod/20250711-1/28ba4ac767883f1e0d8ff745f36dfb6a.jpg', '<p>Bộ phim xoay quanh Mộc Nhất Lâm – một nhân viên trong ngành du lịch – đang chuẩn bị bước sang tuổi 30. Đối mặt với một tuổi &quot;tam thập nhi lập&quot; đầy bất ổn cả trong sự nghiệp lẫn tình cảm, cô cố gắng tìm kiếm ý nghĩa thật sự của cuộc đời. Một cuộc điện thoại bất ngờ khiến Mộc Nhất Lâm một mình đến Huo&#39;er Guo Si (Hoắc Nhĩ Quả Tư), Tân Cương, nơi cô phát hiện ra mối liên hệ sâu sắc giữa người mẹ đã mất và vùng đất này. Trên hành trình đó, cô gặp Lục Hồi – một thanh niên khởi nghiệp trong lĩnh vực ngoại thương. Hai con người tưởng như không có điểm chung lại vô tình trở thành định mệnh của nhau. Cùng nhau phấn đấu trong lĩnh vực riêng, họ không chỉ hỗ trợ nhau tìm hướng đi cho cuộc sống mà còn khám phá ra câu chuyện tình yêu đặc biệt của thế hệ cha mẹ mình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chen Bohao","avatar":""},{"name":"Sun Yining","avatar":""},{"name":"Akezhuli Zhuguli","avatar":""},{"name":"Jiang Yihao","avatar":""},{"name":"Chen Meilin","avatar":""},{"name":"Wang Yichun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mu Yi Lin De Zhen Zhu","木一林的珍珠"]', 1784690324152);
