INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-cam-thanh', 'Tử Cấm Thành', 'The Forbidden City', 'https://phimimg.com/upload/vod/20250710-1/9ab97e783d62d6e7b99de721fe65dae1.jpg', 'https://phimimg.com/upload/vod/20250710-1/9a2d5598388abbbf0166894c91dbe936.jpg', '<p>Mei, một cô gái Trung Quốc, sang Ý tìm chị gái bị thất lạc từ nhỏ. Cuộc tìm kiếm dẫn cô vào thế giới ngầm tăm tối giữa lòng khu phố Hoa ở Roma. Cùng Marcello – chàng trai Ý đang truy tìm cha mất tích – Mei lần theo dấu vết quá khứ, khám phá những bí mật bị chôn vùi và đối mặt với sự thật cay đắng.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yaxi Liu","avatar":""},{"name":"Enrico Borello","avatar":""},{"name":"Marco Giallini","avatar":""},{"name":"Sabrina Ferilli","avatar":""},{"name":"Chunyu Shanshan","avatar":""},{"name":"Luca Zingaretti","avatar":""},{"name":"Tomal Islam","avatar":""},{"name":"Miki Yeung Oi-Gan","avatar":""},{"name":"Claudio Pallitto","avatar":""},{"name":"Daniele Mosca","avatar":""},{"name":"Sheena Hao","avatar":""},{"name":"Abdoulaye Seck","avatar":""},{"name":"Paolo Buglioni","avatar":""},{"name":"Dan Ke","avatar":""},{"name":"Guo Qiang Xu","avatar":""},{"name":"Elisa Wong","avatar":""},{"name":"Jia Yimin","avatar":""},{"name":"Isabel H","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Kung Fu all''amatriciana","紫禁城","La Città Proibita","Forbidden City","禁忌之城","La città proibita"]', 1784690324152);
