INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuc-am-co-thanh', 'Chúc Âm Cổ Thành', 'The Guardians of Zhu Yin', 'https://phimimg.com/upload/vod/20250710-1/f7f50d6adca29b5db39c8cc905254f06.jpg', 'https://phimimg.com/upload/vod/20250710-1/ea4f75b77ad82cc3407da24e5c69d001.jpg', '<p>Thiếu nữ Doãn Phùng An tinh thông thiên văn lịch pháp, vì cứu mẹ mà không ngại nguy hiểm, dấn thân vào địa cung Chúc Âm. Tại đây, cô vô tình hé lộ bí ẩn về sự diệt vong của vương quốc cổ Chúc Âm bị chôn vùi suốt hàng vạn năm. Để bảo vệ nền văn minh Chúc Âm và hoàn thành sứ mệnh gia tộc “chỉnh lại tinh tượng, hóa giải đại nạn”, Doãn Phùng An bước vào hành trình hiểm nguy, truy tìm Cửu Thải Lưu Ly Thiên Châu Nghi, bảo vật trong truyền thuyết có thể xoay chuyển vận mệnh tinh tú, nhằm ngăn chặn thảm họa thiên thạch sắp giáng xuống.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dong Siyi","avatar":""},{"name":"Wesley Wong","avatar":""},{"name":"Zhang Jingwei","avatar":""},{"name":"Han Congcong","avatar":""},{"name":"Kai Li","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Zhu Yin Gu Cheng","The Guardians of Zhu Yin","Chúc Âm Cổ Thành","烛阴古城"]', 1784690324152);
