INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-tam', 'Câu Tâm', 'Loving The Lie', 'https://phimimg.com/upload/vod/20250613-1/27c54bcf7c4fa5e777bf383d829461df.jpg', 'https://phimimg.com/upload/vod/20250613-1/2a0ee1438e7ca07e957a24068f4c6a91.jpg', '<p>Thiên tài họa sĩ quốc họa Tân Ý trở về thị trấn quê hương nơi có với phong cảnh hữu tình. Cô bày mưu tính kế, muốn trở thành họa sĩ được nhà sưu tầm nổi tiếng Quan Sơn Hải thuê dùng. Tân Ý tìm mọi cách tiếp cận nhà họ Quan để điều tra vụ thảm án mười mấy năm trước: Cha cô bị lừa vào xưởng sản xuất hàng giả rồi chết bất đắc kỳ tử, em gái Nùng bị lăng nhục dã man dẫn đến suy sụp tinh thần. Tân Ý lấy thân mình làm mồi nhử hòng dụ kẻ chủ mưu đứng sau thảm án năm xưa lộ mặt. Vào thời khắc mấu chốt, Quan Hoài, con trai của Quan Sơn Hải, đã đưa ra đề nghị hợp tác, muốn mượn tay cô để đoạt quyền. Kể từ đó, hai người với những mưu đồ riêng đã bắt tay nhau, khuấy động một cơn bão lớn trong thị trấn yên bình và thanh tịnh...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Tuấn Bút","avatar":""},{"name":"Mã Hạo Đông","avatar":""},{"name":"Vương Nhất Châu","avatar":""},{"name":"An Đông","avatar":""},{"name":"Trần Chấn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Gou Xin","勾心"]', 1784690324152);
