INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giac-mong-ban-so', 'Giấc Mộng Ban Sơ', 'A Dream Like The True Love', 'https://phimimg.com/upload/vod/20250629-1/5c1df3fd4d6bbfc165b57d9bb49f01e5.jpg', 'https://phimimg.com/upload/vod/20250629-1/595b65bf1f0a3394f84c3f9bbad4243e.jpg', '<p>Thiếu nữ Trần Phán Nhi vì gia cảnh khốn cùng, bị tri huyện lấy cớ tế thần sông để ép đưa vào thanh lâu. Phán Nhi dũng cảm trốn thoát, đổi tên thành Bảo Ngân, bán thân để rời khỏi chốn cũ. Sau đó, nàng tình cờ gặp lại Ôn Túc - đại công tử nhà họ Ôn, người từng cứu mạng nàng, thế nhưng Ôn Túc nay đã trở thành nam sủng bên cạnh trưởng công chúa. Đối mặt với bất công, Bảo Ngân cùng Ôn Túc cùng chung tay, từng bước phản công, cuối cùng rửa sạch nỗi oan, tái ngộ nơi đỉnh cao danh vọng.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Húc Uy","avatar":""},{"name":"Nayi","avatar":""},{"name":"Kì Ức","avatar":""},{"name":"Sinh Cảng Soái","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yi Meng Ru Chu","A Dream Like the Beginning","一梦如初"]', 1784690324152);
