INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('giac-mong-ban-so', 'Giấc Mộng Ban Sơ', 'A Dream Like The True Love', 'giấc mộng ban sơ a dream like the true love lưu húc uy nayi kì ức sinh cảng soái yi meng ru chu a dream like the beginning 一梦如初', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngon-nui-cam', 'Ngọn Núi Cấm', 'Forbidden Mountain', 'https://phimimg.com/upload/vod/20250711-1/6288ec8f9815cdfbb07f4db967c3e77d.jpg', 'https://phimimg.com/upload/vod/20250711-1/04b6c3aa84abe6b8b6c6427076f0a74a.jpg', '<p>Hậu duệ của người canh núi – Lâm Thần – vì một bức ảnh thần bí mà trở thành người dẫn đường lên núi cho thiên kim tiểu thư nhà giàu – Từ Bội Du. Từ Bội Du bị ám ảnh bởi một cơn ác mộng kỳ quái suốt một năm trời: bóng lưng không ngũ quan, chiếc đầu rắn gào thét “quay về”... Chỉ có thần dược trên núi Đồng Bạt mới có thể cứu mạng cô. Lâm Thần kiên quyết đồng hành, vì muốn làm sáng tỏ bí mật cái chết của cụ cố trong núi sâu. Anh luôn nghi ngờ rằng gia tộc của cô cháu gái trưởng nhà họ Từ này có mối liên hệ sâu sắc với sự mất tích kỳ bí của tổ tiên mình. Đường vào núi tràn đầy sát cơ. Bác sĩ tâm lý Trương Khuê Hạo luôn tỏ ra quan tâm ân cần nhưng lại ẩn giấu âm mưu. Đạo sĩ Hạng Vân Kiếm thì thần bí cảnh báo “người đến không lành”. Chiếc la bàn xoay chuyển như thể bánh răng số phận đang bắt đầu vận hành. Khi Từ Bội Du nhìn thấy sự thật trong cơn ác mộng giữa lúc tuyệt vọng, Lâm Thần cũng phát hiện ra rằng cụ cố năm xưa đã chết để bảo vệ quốc bảo. Ân oán trăm năm như màn sương tan dần, giữa thử thách sinh tử, tình cảm dần nảy sinh. Nhưng họ lại phải đối mặt với những ân oán đẫm máu của thế hệ trước — liệu đó sẽ là xiềng xích mới, hay là chìa khóa phá giải toàn cục?</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chen Kaixin","avatar":""},{"name":"Zhao Shuai","avatar":""},{"name":"Ye Zijing","avatar":""},{"name":"Ye Miaomiao","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["封禁山"]', 1784690324152);
