INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-em-em-cam-on', 'Yêu Em... Em Cảm Ơn!', 'My Love Will Make You Disappear', 'https://phimimg.com/upload/vod/20250710-1/f0077bf1716ad7622f15522320b1f077.jpg', 'https://phimimg.com/upload/vod/20250710-1/a58fcb5af662fa361c64d523a6c72f50.jpg', '<p>Một người phụ nữ tin rằng mình bị nguyền rủa đã gặp một chủ nhà gặp rắc rối trong khi đấu tranh chống lại sự di dời của cộng đồng. Khi họ trở nên gần gũi hơn, nỗi sợ hãi của cô rằng tất cả những người yêu của cô sẽ biến mất đe dọa mối quan hệ của họ.</p>', 'Full', 1, 'single', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Philippines', 1, '[{"name":"Kim Chiu","avatar":""},{"name":"Paulo Avelino","avatar":""},{"name":"Wilma Doesnt","avatar":""},{"name":"Lovely Abella","avatar":""},{"name":"Benj Manalo","avatar":""},{"name":"Nico Antonio","avatar":""},{"name":"Miguel Almendras","avatar":""},{"name":"Martin Escudero","avatar":""},{"name":"Karina Bautista","avatar":""},{"name":"Jeremiah Lisbo","avatar":""},{"name":"Melai Cantiveros","avatar":""},{"name":"Peewee O''Hara","avatar":""},{"name":"Bart Guingona","avatar":""},{"name":"Frenchie Dy","avatar":""},{"name":"Charm Aranton","avatar":""},{"name":"Marnie Lapus","avatar":""},{"name":"Brian Sy","avatar":""},{"name":"A","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["حبي سيجعلك تختفي","Meine Liebe Wird Dich Verschwinden Lassen","愛清咀咀咒","Mon Amour, Te Ferai Disparaître","Il Mio Amore, Ti Farà Sparire","Rakkauteni Saa Sinut Katoamaan","My Love Wi