INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quarterback-phan-2', 'Quarterback (Phần 2)', 'Quarterback (Season 2)', 'https://phimimg.com/upload/vod/20250710-1/079631bc0742cf2933c56d9df42f3586.jpg', 'https://phimimg.com/upload/vod/20250710-1/20f99574bb5ebc1aae76665677790dea.jpg', '<p><span style="text-wrap-mode: wrap;">Theo chân những cơ thể bầm dập, những cú trượt ngã khiến tinh thần suy sụp, những trận thua đau đớn và niềm vui thuần khiết của ba tiền vệ NFL trong suốt một mùa giải.</span></p>', 'Hoàn Tất (7/7)', 7, 'tvshows', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kirk Cousins","avatar":""},{"name":"Joe Burrow","avatar":""},{"name":"Jared Goff","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["四分卫","Quarterback"]', 1784690324152);
