INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-gia-tien', 'Nhà Gia Tiên', 'The Ancestral Home', 'https://phimimg.com/upload/vod/20250710-1/3024e503f4c8cecdb0578c20c77e4cdf.jpg', 'https://phimimg.com/upload/vod/20250710-1/5af1cd558e89eb88b67d72181906edac.jpg', '<p>Nhà Gia Tiên xoay quanh câu chuyện đa góc nhìn về các thế hệ khác nhau trong một gia đình, có hai nhân vật chính là Gia Minh (Huỳnh Lập) và Mỹ Tiên (Phương Mỹ Chi). Trở về căn nhà gia tiên để quay các video “triệu view” trên mạng xã hội, Mỹ Tiên - một nhà sáng tạo nội dung thuộc thế hệ Z vốn không tin vào chuyện tâm linh, hoàn toàn mất kết nối với gia đình, bất ngờ nhìn thấy Gia Minh - người anh trai đã mất từ lâu. Để hồn ma của Gia Minh có thể siêu thoát và không tiếp tục làm phiền mình, Mỹ Tiên bắt tay cùng Gia Minh lên kế hoạch giữ lấy căn nhà gia tiên đang bị họ hàng tranh chấp, đòi ông nội chia tài sản. Đứng trước hàng loạt bí mật động trời trong căn nhà gia tiên, liệu Mỹ Tiên có vượt qua được tất cả để hoàn thành di nguyện của Gia Minh?</p>', 'Full', 1, 'single', 'completed', 25, 2025, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Huỳnh Lập","avatar":""},{"name":"Phương Mỹ Chi","avatar":""},{"name":"Ngô Phạm Hạnh Thúy","avatar":""},{"name":"Puka","avatar":""},{"name":"Huỳnh Đông","avatar":""},{"name":"Kiều Linh","avatar":""},{"name":"Trung Dân","avatar":""},{"name":"Thanh Hiền","avatar":""},{"name":"Đào Anh Tuấn","avatar":""},{"name":"Mai Thế Hiệp","avatar":""},{"name":"Trác Thuý Miêu","avatar":""},{"name":"Thanh Thức","avatar":""},{"name":"Lê Nam","avatar":""},{"name":"NS Mạnh Dung","avatar":""},{"name":"Nguyễn Anh Tú","avatar":""},{"name":"NS Thanh Dậu","avatar":""},{"name":"Chí Tâm","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Nhà Gia Tiên"]', 1784690324152);
