INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-chet-phan-2', 'Vùng Đất Chết (Phần 2)', 'No Man''s Land (Season 2)', 'https://phimimg.com/upload/vod/20250710-1/2a4d1d66bcb68a435b2b2d77f4576fad.jpg', 'https://phimimg.com/upload/vod/20250710-1/70c1f2870c94684878da42c8426b4ca2.jpg', '<p>Đi sâu vào cuộc nội chiến ở Syria qua con mắt của Antoine, một chàng trai trẻ người Pháp, để tìm kiếm người em gái bị ghẻ lạnh, được cho là đã chết của anh. Trong khi làm sáng tỏ bí ẩn, từng phần một, cuộc hành trình của Antoine đi qua những con đường với những nhà thám hiểm và những kẻ vô chính phủ, gián điệp và những nạn nhân vô tội, đồng thời mang đến cái nhìn độc đáo về những sự kiện bi thảm ở Syria và cách chúng ảnh hưởng đến toàn thế giới.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 18, 2025, 'Vietsub', 'FHD', 'Bỉ', 0, '[{"name":"Félix Moati","avatar":""},{"name":"Mélanie Thierry","avatar":""},{"name":"Souheila Yacoub","avatar":""},{"name":"James Floyd","avatar":""},{"name":"Joe Ben Ayed","avatar":""},{"name":"James Purefoy","avatar":""},{"name":"Céline Samie","avatar":""},{"name":"Julia Faure","avatar":""},{"name":"Nadia Benzakour","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["No Man''s Land","新月沃土","無人之地"]', 1784690324152);
