INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tho-san-quai-vat-nhan-ngu-duoi-bien-sau', 'Thợ Săn Quái Vật: Nhân Ngư Dưới Biển Sâu', 'The Witcher: Sirens Of The Deep', 'thợ săn quái vật: nhân ngư dưới biển sâu the witcher: sirens of the deep doug cockle anya chalotra joey batey christina wren emily carey camrus johnson simon templeman ray chase mallory jansen cynthia kaye mcwilliams ramon tikaram 猎魔人：深渊海妖 ведьмак: зов морской бездны вядзьмар: русалкі з глыбінь the witcher: sirens of the deep', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-duong-bang-gia-tra-dua', 'Con Đường Băng Giá: Trả Đũa', 'Ice Road: Vengeance', 'https://phimimg.com/upload/vod/20250703-1/5001a05d9e6494f6eb951976b4039696.jpg', 'https://phimimg.com/upload/vod/20250703-1/74a4ba32c29e7f69a2ef37fc0adfcd82.jpg', '<p>Tài xế xe tải đường băng huyền thoại Mike McCann đến Nepal để hoàn thành tâm nguyện cuối cùng của người anh trai quá cố: rải tro cốt trên đỉnh Everest. Nhưng hành trình tưởng như bình yên lại trở thành ác mộng khi chiếc xe buýt chở đầy du khách mà anh đi cùng bị tấn công trên cung đường “Tiến về bầu trời” – một trong những tuyến đường nguy hiểm nhất thế giới. Trên vùng núi cao hiểm trở, McCann và người hướng dẫn leo núi buộc phải chiến đấu với nhóm lính đánh thuê bí ẩn, bảo vệ những người dân vô tội – và một ngôi làng đang đứng bên bờ vực bị xóa sổ.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Liam Neeson","avatar":""},{"name":"Fan Bingbing","avatar":""},{"name":"Marcus Thomas","avatar":""},{"name":"Grace O''Sullivan","avatar":""},{"name":"Saksham Sharma","avatar":""},{"name":"Bernard Curry","avatar":""},{"name":"Geoff Morrell","avatar":""},{"name":"Mahesh Jadu","avatar":""},{"name":"Amelia Bishop","avatar":""},{"name":"Shivantha Wijesinha","avatar":""},{"name":"CJ. Bloomfield","avatar":""},{"name":"Michala Banas","avatar":""},{"name":"Salim Fayad","avatar":""},{"name":"Kaden Hartcher","avatar":""},{"name":"Seth Kannof","avatar":""},{"name":"Kaivu Suvarna","avatar":""},{"name":"Glen Ol","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5eb