INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguyen-thu-doi-dau-nguyen-thu-quoc-gia', 'Nguyên Thủ Đối Đầu (Nguyên Thủ Quốc Gia)', 'Heads Of State', 'https://phimimg.com/upload/vod/20250708-1/b9367f1f149caebba896452f77bc4808.jpg', 'https://phimimg.com/upload/vod/20250708-1/d7eff5448de409988466ff0c3f48bcaf.jpg', '<p>Hai nhà lãnh đạo – Tổng thống Mỹ (John Cena) và Thủ tướng Anh (Idris Elba) – bị rơi vào âm mưu khủng bố khi tham dự hội nghị NATO. Bị lạc ở Belarus, họ buộc phải bắt tay để sinh tồn, dù tính cách trái ngược. Cùng với đặc vụ MI6 (Priyanka Chopra), họ đối đầu kẻ thù quốc tế, qua chuỗi hành động–hài hước kịch tính xuyên châu Âu.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Idris Elba","avatar":""},{"name":"John Cena","avatar":""},{"name":"Priyanka Chopra Jonas","avatar":""},{"name":"Paddy Considine","avatar":""},{"name":"Carla Gugino","avatar":""},{"name":"Stephen Root","avatar":""},{"name":"Jack Quaid","avatar":""},{"name":"Sarah Niles","avatar":""},{"name":"Richard Coyle","avatar":""},{"name":"Aleksandr Kuznetsov","avatar":""},{"name":"Katrina Durden","avatar":""},{"name":"Wade Briggs","avatar":""},{"name":"Clare Foster","avatar":""},{"name":"Robyn Pennington","avatar":""},{"name":"Adrian Lukis","avatar":""},{"name":"Sharlto Copley","avatar":""},{"name":"Steven Cree","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["国家元首","Heads of State: ผู้นำสายบู๊กู้วิกฤต","Глави держав","Heads of State"]', 1784690324152);
