INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-ba-bat-hanh', 'Bộ Ba Bất Hạnh', 'The Unholy Trinity', 'https://phimimg.com/upload/vod/20250709-1/779c747806bdbc74e10f64660d1beb7c.jpg', 'https://phimimg.com/upload/vod/20250709-1/012480013de6ac7cb159a3141fc40f3b.jpg', '<p>Lấy bối cảnh Montana đầy biến động những năm 1870, trong khoảnh khắc trước khi bị hành quyết, Isaac Broadway giao cho người con trai đã xa cách bấy lâu – Henry – một nhiệm vụ bất khả thi: giết kẻ đã vu oan cho ông một tội danh mà ông không hề gây ra. Quyết thực hiện lời hứa, Henry lên đường đến thị trấn hẻo lánh Trinity. Nhưng một sự kiện bất ngờ khiến anh mắc kẹt tại đây, bị cuốn vào cuộc đối đầu giữa Gabriel Dove – vị cảnh trưởng mới chính trực – và một nhân vật bí ẩn tên là St. Christopher.</p>', 'Full', 1, 'single', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Pierce Brosnan","avatar":""},{"name":"Samuel L. Jackson","avatar":""},{"name":"Brandon Lessard","avatar":""},{"name":"Veronica Ferres","avatar":""},{"name":"Gianni Capaldi","avatar":""},{"name":"Q''orianka Kilcher","avatar":""},{"name":"Tim Daly","avatar":""},{"name":"Ethan Peck","avatar":""},{"name":"Katrina Bowden","avatar":""},{"name":"David Arquette","avatar":""},{"name":"Anthony J. Sharpe","avatar":""},{"name":"Beau Linnell","avatar":""},{"name":"Isabella Ruby","avatar":""},{"name":"Eadie Gray","avatar":""},{"name":"Stephanie Hernandez","avatar":""},{"name":"Dylan Brosn","avatar":""}]', '[{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Salted Earth","The Unholy Trinity"]', 1784690324152);
