INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('9-nam-1-tinh-yeu', '9 Năm 1 Tình Yêu', '9 Years Of You', 'https://phimimg.com/upload/vod/20250610-1/7f88af4a2a7c76fca4fa8dcdc10e0bf6.jpg', 'https://phimimg.com/upload/vod/20250610-1/8a3c68267f1cc945d77dc6281655906f.jpg', '<p>9 Năm 1 Tình Yêu theo chân hành trình từ tình bạn đến tình yêu của đôi bạn thân Dao và Ran. Là bạn bè tri kỷ lâu năm, nhưng trên thực tế Dao và Ran đã bắt đầu yêu nhau tự lúc nào không hay. Suốt chín năm trời, họ cùng nhau trải qua mọi thăng trầm trong sự nghiệp, những khó khăn trong gia đình lẫn các mối quan hệ đổ vỡ. Cũng nhờ thế mà Dao và Ran từ từ trưởng thành hơn trong cuộc sống lẫn tình yêu và dần dần nhận ra tình cảm thực sự dành cho đối phương.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 9, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Sanpetch Kunakorn","avatar":""},{"name":"Cherprang Areekul","avatar":""},{"name":"Korn Sirisorn","avatar":""},{"name":"Lapassalan Jiravechsoontornkul","avatar":""},{"name":"Sawanya Paisarnpayak","avatar":""},{"name":"Jinnaphop Prattranasanti","avatar":""},{"name":"Atchareeya Potipipittanakorn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Tae La Pi Mi Thoe","แต่ละปีมีเธอ"]', 1784690324152);
