INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('den-dui-khi-co-nghe-giam-dinh-si-nhung-toi-lai-la-nguoi-manh-nhat', 'Đen Đủi Khi Có Nghề Giám Định Sĩ Nhưng Tôi Lại Là Người Mạnh Nhất', 'Even Given the Worthless "Appraiser" Class, I''m Actually the Strongest', 'đen đủi khi có nghề giám định sĩ nhưng tôi lại là người mạnh nhất even given the worthless "appraiser" class, i''m actually the strongest kikunosuke toya hikaru tono sayumi suzushiro yu serizawa minami tsuda kana ichinose aimi takeo otsuka daisuke namikawa kana hanazawa 不幸职业【鉴定士】实则最强 不幸职业【鉴定士】其实是最强的 fuguushoku "kanteishi" ga jitsu wa saikyou datta: naraku de kitaeta saikyou no "shingan" de musou suru fuguushoku [kanteishi] ga jitsu wa saikyou datta: naraku de kitaeta saikyou no [shingan] de musou suru fugukan fugūshoku "kanteishi" ga jitsu wa saikyō datta: naraku de kitaeta saikyō no "shingan" de musō suru 不遇職【鑑定士】が実は最強だった fuguu-shoku ''''kanteishi'''' ga jitsu wa saikyou datta fuguu-shoku kanteishi ga jitsu wa saikyou datta 不幸職業【鑑定士】其實是最強的 the unfavorable job "appraiser" is actually the strongest even given the worthless "appraiser" class, i''m actually the strongest 不遇職【鑑定士】が実は最強だった～奈落で鍛えた最強の【神眼】で無双する～', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('roi-se-on-thoi', 'Rồi Sẽ Ổn Thôi', 'It''s Okay!', 'https://phimimg.com/upload/vod/20250708-1/4cd6e598f7e7fcfe0a6386c7c0871f21.jpg', 'https://phimimg.com/upload/vod/20250708-1/802c4ba43c11d772285994caa0df75e8.jpg', '<p>In-young, một nữ sinh trung học sống đơn độc sau cái chết đột ngột của cha mẹ, bị đuổi ra khỏi nhà vì không trả nổi tiền thuê. Không còn chỗ nương tựa, cô lén sống trong phòng tập của Đoàn Nghệ thuật Múa Truyền thống Hàn Quốc – nơi mình từng sinh hoạt. Dù hoàn cảnh bi thương, In-young vẫn cố gắng sống tích cực và kiên cường. Một ngày, cô bị phát hiện bởi vị đạo diễn nổi tiếng nghiêm khắc của đoàn. Tuy ban đầu không thể giữ In-young trong đoàn, cuối cùng chính ông lại trở thành người cưu mang cô, và cả hai bắt đầu sống chung một mái nhà.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Re","avatar":""},{"name":"Jin Seo-yeon","avatar":""},{"name":"Chung Su-bin","avatar":""},{"name":"Shim Yi Young","avatar":""},{"name":"Lee Jung-ha","avatar":""},{"name":"Jang Yi-jung","avatar":""},{"name":"Kim Hae-sook","avatar":""},{"name":"Son Suk-ku","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["没关系 没关系 没关系！","没事，没事，没事！","드림즈","괜찮아? 괜찮아, 괜찮아!","괜찮아 괜찮아 괜찮아!"]', 1784690324153);
