INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('roi-se-on-thoi', 'Rồi Sẽ Ổn Thôi', 'It''s Okay!', 'rồi sẽ ổn thôi it''s okay! lee re jin seo-yeon chung su-bin shim yi young lee jung-ha jang yi-jung kim hae-sook son suk-ku 没关系 没关系 没关系！ 没事，没事，没事！ 드림즈 괜찮아? 괜찮아, 괜찮아! 괜찮아 괜찮아 괜찮아!', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-dieu-gian-don', 'Những Điều Giản Đơn', 'Things Like This', 'https://phimimg.com/upload/vod/20250708-1/0af3e763777c57cf137e9bf2ad7f6b1e.jpg', 'https://phimimg.com/upload/vod/20250708-1/e5688020442a9cc7d06fb5cb1b14f2fe.jpg', '<p>Nhà văn trẻ Zack Anthony đang chật vật với sự nghiệp thì gặp gỡ Zack Mandel – trợ lý của một đại lý tài năng. Mối liên hệ của họ bắt đầu từ một hành động tử tế nhỏ và nhanh chóng phát triển sau một buổi hẹn đầu tiên… thảm họa nhưng đầy tiếng cười. Khi dành nhiều thời gian bên nhau, họ phát hiện ra một quá khứ bất ngờ gắn kết cả hai – như thể số phận đã sắp đặt từ trước. Dù phải đối mặt với những hiểu lầm và khó khăn cá nhân, mối quan hệ của họ ngày càng sâu sắc, mở ra hy vọng về một tình yêu đầy ý nghĩa.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Max Talisman","avatar":""},{"name":"Joey Pollari","avatar":""},{"name":"Jackie Cruz","avatar":""},{"name":"Margaret Berkowitz","avatar":""},{"name":"Danny Chavarriaga","avatar":""},{"name":"Charlie Tahan","avatar":""},{"name":"Cara Buono","avatar":""},{"name":"Eric Roberts","avatar":""},{"name":"Taylor Trensch","avatar":""},{"name":"Romy Reiner","avatar":""},{"name":"Barbara Barrie","avatar":""},{"name":"Bridget Regan","avatar":""},{"name":"Nicholas Hamilton","avatar":""},{"name":"Crawford Horton","avatar":""},{"name":"Jake Reiner","avatar":""},{"name":"Drea Berg","avatar":""},{"name":"Amelia Campbel","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Things Like This"]', 1784690324153);
