INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-anh-dep-xinh', 'Ám Ảnh Đẹp Xinh', 'Pretty Thing', 'https://phimimg.com/upload/vod/20250708-1/b9135db59c43df345599acac4c4af0e8.jpg', 'https://phimimg.com/upload/vod/20250708-1/c935b7ecfaf220ce36bbea7824e70d87.jpg', '<p>Một giám đốc điều hành thành đạt buộc phải chống trả khi người tình trẻ, vì bị từ chối, đã để nỗi ám ảnh đi quá giới hạn.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Alicia Silverstone","avatar":""},{"name":"Karl Glusman","avatar":""},{"name":"Catherine Curtin","avatar":""},{"name":"Britne Oldford","avatar":""},{"name":"Tammy Blanchard","avatar":""},{"name":"Esteban Benito","avatar":""},{"name":"Sorika Horng","avatar":""},{"name":"John Wollman","avatar":""},{"name":"Paul McCallion","avatar":""},{"name":"Nicole Annunziata","avatar":""},{"name":"Sergi Martos","avatar":""},{"name":"Monica Rae Summers Gonzalez","avatar":""},{"name":"Kyle Bary","avatar":""},{"name":"Mike Rob","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["The Bird and the Bee","Pretty Thing"]', 1784690324153);
