INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-hiep-di-lam-thoi-dai-hiep-thinh-thuong-cong', 'Đại Hiệp, Đi Làm Thôi! (Đại Hiệp Thỉnh Thượng Công)', 'GoWest: Overworked', 'https://phimimg.com/upload/vod/20250513-1/584c78d019d27d7fc713bcda9a18e40b.jpg', 'https://phimimg.com/upload/vod/20250513-1/1a2d06bbb3ce61bb905ba070d9a1be4e.jpg', '<p>Năm mươi năm trước, giang hồ đột nhiên bị &quot;Hỗn Độn&quot; xâm chiếm. Mộ Dung Khung thành lập tổ chức ma giáo để đối đầu, chiến đấu vô cùng gian nan nhưng vẫn không thắng. Lúc ấy, Thần sứ Dịch Chi Hoa xuất hiện, truyền dạy cho mọi người công pháp Yêu Hoá giúp họ thành công đánh bại Hỗn Độn. Nhưng sau khi thần sứ rời đi, công pháp này lan truyền khắp giang hồ và dần mất kiểm soát. Mộ Dung Khung thất vọng và lui về ở ẩn. Dư Hoá Băng vốn là thuộc hạ của hắn, thừa cơ lên nắm quyền. Hắn cải tiến công pháp Yêu Hoá và tạo ra thời đại chân khí bùng nổ giúp giang hồ bước vào thời kỳ hoàng kim. Tuy nhiên cái giá phải trả chính là tất cả những hiệp khách giang hồ đều biến thành &quot;quái vật làm việc&quot;. Đông Phương Thắng - một thiếu niên thuần khiết xuất hiện. Hắn tìm đến Mộ Dung Khung đang quy ẩn trong Tiệm cơm Hướng Tây với hi vọng khôi phục được thời đại giang hồ như trước đây.</p>', 'Tập 10', 24, 'hoathinh', 'ongoing', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ling Qi","avatar":""},{"name":"Liang Sheng","avatar":""},{"name":"Yuze Han","avatar":""},{"name":"Cui Kai","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Da Xia Qing Shang Gong","Dà Xiá Qǐng Shàng Gōng","Westward：Overcooked","Go West: Overworked","大侠请上功"]', 1784690324153);
