INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sao-anh-bao-khong-thich-tre-con', 'Sao Anh Bảo Không Thích Trẻ Con', 'My Stubborn', 'https://phimimg.com/upload/vod/20250422-1/85073f8d9387853050db3408c4cd4489.jpg', 'https://phimimg.com/upload/vod/20250422-1/956611b742c5a20d3a516913521f486b.jpg', '<p>Jun sống chỉ để chọc tức Sorn. Sorn thì không thể chịu nổi Jun. Nhưng định mệnh đã an bài — và có lẽ cả những cảm xúc mà họ không ngờ tới.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Boat Yongyut Termtuo","avatar":""},{"name":"Pasakorn Sanrattana","avatar":""},{"name":"Phusanu Wongsavanischakorn","avatar":""},{"name":"Punn Chirathanaphat","avatar":""},{"name":"Michelle Behrmann","avatar":""},{"name":"Llouis Kitawat Chaodi","avatar":""},{"name":"Nathapong Sing-on","avatar":""},{"name":"Pangpond Potchana Lertchanachomphu","avatar":""},{"name":"Minty Chuthikan Chawasathienphong","avatar":""},{"name":"Intad Leowrakwong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["执爱","मेरा ज़िद्दी","Nai Hia Bok Mai Chop Dek","ไหนเฮียบอกไม่ชอบเด็ก"]', 1784690324153);
