INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sao-anh-bao-khong-thich-tre-con', 'Sao Anh Bảo Không Thích Trẻ Con', 'My Stubborn', 'sao anh bảo không thích trẻ con my stubborn boat yongyut termtuo pasakorn sanrattana phusanu wongsavanischakorn punn chirathanaphat michelle behrmann llouis kitawat chaodi nathapong sing-on pangpond potchana lertchanachomphu minty chuthikan chawasathienphong intad leowrakwong 执爱 मेरा ज़िद्दी nai hia bok mai chop dek ไหนเฮียบอกไม่ชอบเด็ก', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khai-giang-trai-tim-hoc-cach-yeu', 'Khai Giảng, Trái Tim Học Cách Yêu', 'Boys In Love', 'https://phimimg.com/upload/vod/20250421-1/efa1bdeead2e32daeb62c3ecfb2b38da.jpg', 'https://phimimg.com/upload/vod/20250421-1/da161acefe75c14301b78ef327d37c62.jpg', '<p>Shane là một học sinh thông minh, luôn nổi bật trong học tập và các hoạt động của trường, nhưng lại chẳng mấy quan tâm đến cuộc sống tuổi teen. Mọi chuyện bắt đầu thay đổi khi cậu gặp Kit – một học sinh vô tư, hoàn toàn trái ngược với mình. Hai người bị buộc phải dành thời gian bên nhau, và từ đó, những cảm xúc bất ngờ bắt đầu nảy nở. Cùng lúc đó, Kim – bạn cùng lớp của Shane – là một người mơ mộng và tin vào tình yêu. Cậu quyết tâm phải tìm được tình yêu đích thực trước khi tốt nghiệp. Khi gặp Mon – một học sinh chuyển trường mới, Kim đã quyết tâm làm mọi cách để chinh phục trái tim cậu ấy. Bộ phim là một hành trình thanh xuân đầy cảm xúc, lãng mạn và nhẹ nhàng.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Peemsan Sotangkur","avatar":""},{"name":"Metas Opas-iamkajorn","avatar":""},{"name":"Puttipong Jitbut","avatar":""},{"name":"Ratiphat Luengvoraphan","avatar":""},{"name":"Kanthee Limpitkranon","avatar":""},{"name":"Tanan Lohawatanakul","avatar":""},{"name":"Suphakorn Sriphothong","avatar":""},{"name":"Phromphiriya Thongputtaruk","avatar":""},{"name":"Rutricha Phapakithi","avatar":""},{"name":"Napat Patcharachavalit","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["纯爱满校园","戀愛學園","New Term, Learn to Love","Boys in Love Series","เปิดเทอมใหม่ หัวใจหัดรัก"]', 1784690324153);
