INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-bao-thu', 'Đêm Báo Thù', 'Stand Your Ground', 'https://phimimg.com/upload/vod/20250707-1/1bdae64671e33e3ab6cf2a01a43c8f1d.jpg', 'https://phimimg.com/upload/vod/20250707-1/026aa5dcace65b507866face77890bda.jpg', '<p>Jack Johnson – cựu đặc nhiệm Lực lượng Đặc biệt, sống hạnh phúc cùng vợ đang mang thai. Một đêm, căn nhà của anh bị tấn công dã man bởi bọn đàn em của trùm xã hội đen Bastion, dẫn đến cái chết thảm khốc của vợ. Trong cơn phẫn nộ, Jack giết một kẻ tấn công ngay tại hiện trường và phải chịu án tù 6 năm.Sau khi ra tù, Jack phát hiện hung thủ là con trai của Bastion. anh âm thầm bắt giữ Leon – con trưởng Bastion và khiến hắn hôn mê. Không chấp nhận thất bại, Bastion tung đội sát thủ đến quấy phá, biến ngôi nhà của Jack thành chiến trường. Cuộc đối đầu khốc liệt cuối cùng nổ ra giữa Jack và cả binh đoàn của Bastion.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Daniel Stisen","avatar":""},{"name":"Peter Stormare","avatar":""},{"name":"Eric Roberts","avatar":""},{"name":"Adam Basil","avatar":""},{"name":"Akie Kotabe","avatar":""},{"name":"Beau Fowler","avatar":""},{"name":"Isobel Laidler","avatar":""},{"name":"Megan Lockhurst","avatar":""},{"name":"Blair London","avatar":""},{"name":"Patrick Regis","avatar":""},{"name":"Laila Pyne","avatar":""},{"name":"Michael Billington","avatar":""},{"name":"Phillip Ray Tommy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Stand Your Ground"]', 1784690324153);
