INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-ta-la-nhung-ke-doi-tra', 'Chúng Ta Là Những Kẻ Dối Trá', 'We Were Liars', 'https://phimimg.com/upload/vod/20250624-1/c47ac7e1699a810c04545e25235a5d87.jpg', 'https://phimimg.com/upload/vod/20250624-1/caf34f55c6f4ab38cab7e5dc789afbca.jpg', '<p>Một năm sau vụ tai nạn bí ẩn khiến mất trí nhớ, Cadence (17 tuổi) trở về đảo Beechwood — thiên đường mùa hè của gia đình Sinclair quyền quý — để tìm lời giải. Nhưng giữa không gian ngỡ như yên bình ấy, cả ba thế hệ trong gia tộc đều im lặng, còn nhóm bạn thân &quot;Những Kẻ Dối Trá&quot; cùng mối tình đầu Gat cũng tránh né sự thật. Không còn cách nào khác, Cadence phải tự mình vén màn bí mật đã chôn giấu suốt một năm qua.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Emily Alyn Lind","avatar":""},{"name":"Shubham Maheshwari","avatar":""},{"name":"Joseph Zada","avatar":""},{"name":"Esther-Rose McGregor","avatar":""},{"name":"David Morse","avatar":""},{"name":"Caitlin FitzGerald","avatar":""},{"name":"Candice King","avatar":""},{"name":"Mamie Gummer","avatar":""},{"name":"Rahul Kohli","avatar":""},{"name":"Wendy Crewson","avatar":""},{"name":"Brady Droulis","avatar":""},{"name":"Emerson MacNeil","avatar":""},{"name":"Manaia Wall","avatar":""},{"name":"Dylan Bruce","avatar":""},{"name":"Leandro Vigueras","avatar":""},{"name":"Raewynn Martel","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Nous, les menteurs","We Were Liars"]', 17846903241