INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-thien-chi-thuong', 'Vân Thiên Chi Thượng', 'Above The Clouds', 'https://phimimg.com/upload/vod/20250626-1/fa03a3337754f991dee4dcd7e4329922.jpg', 'https://phimimg.com/upload/vod/20250626-1/7259290b9b620275cd23b66dfe0f106b.jpg', '<p>Lộ An Ngưng và Lăng Thương trải qua mối tình nghiệt ngã kéo dài nghìn kiếp, bị mệnh trời thao túng. Từ hai người mạnh mẽ đối đầu, họ dần dần thức tỉnh, quyết tâm xoay chuyển mệnh trời. Để không còn bị số phận sắp đặt, cả hai cùng nhau tu tiên, thăng cấp đối đầu với mệnh trời.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Từ Chẩn Chẩn","avatar":""},{"name":"Trương Cảnh Vân","avatar":""},{"name":"Trương Sí","avatar":""},{"name":"Ninh Nguyệt","avatar":""},{"name":"Triệu Viên Hữu","avatar":""},{"name":"Lý Khanh Nhĩ","avatar":""},{"name":"Trương Duệ Di","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yun Tian Zhi Shang","云天之上","เหนือเมฆา"]', 1784690324153);
