INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-giu-sinh-menh-ban-thai', 'Nắm Giữ Sinh Mệnh (Bản Thái)', 'Happiness', 'https://phimimg.com/upload/vod/20250531-1/aa7f572c1cb5c7b2ef4caf4370542e21.jpg', 'https://phimimg.com/upload/vod/20250531-1/8ccda2f75f39d711ad544dce9258ac65.jpg', '<p>Được làm lại từ bộ phim Hàn Quốc cùng tên, Nắm Giữ Sinh Mệnh (Bản Thái) tiếp tục khai thác những phản ứng đáng sợ của con người trước cánh cửa sinh tử. Khi một căn bệnh lạ khiến người bị nhiễm bệnh trở nên khát máu người bùng phát tại một chung cư, chính phủ ra lệnh phong tỏa, không để bất kì ai thoát ra ngoài. Đối mặt với hiểm họa chết người, các cư dân chung cư bắt đầu khuất phục bản năng sinh tồn, không từ bất kì thủ đoạn nào để có thể sống sót.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Orn Patchanan Jiajirachote","avatar":""},{"name":"Saint Suppapong Udomkaewkanjana","avatar":""},{"name":"Dom Hetrakul","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Happiness"]', 1784690324153);
