INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoan-vu', 'Hoán Vũ', 'Reborn', 'https://phimimg.com/upload/vod/20250619-1/4d29632d99d901f16dba88310f52dd6f.jpg', 'https://phimimg.com/upload/vod/20250619-1/86a353c3c4a760c649d343eee6870701.jpg', '<p>Chuyện kể về cô học sinh chuyển trường 16 tuổi Kiều Thanh Vũ, dưới sự giúp đỡ của hotboy nổi loạn Minh Thịnh để tìm hiểu nguyên nhân cái chết của chị gái mình. Dần dần, cô khám phá ra sự thật việc sáu năm trước chị mình bị người cả thôn \&quot;mưu sát\&quot;, trong quá trình điều tra, cô nhận ra nhiều điều mới mẻ về chị gái và mẹ mình, đồng thời tìm ra cách nhìn nhận thế giới một cách đúng đắn, từ đó tự chữa lành bản thân và giúp đỡ người khác. Hai người trong hành trình này đã cứu rỗi nhau và cùng nhau trưởng thành.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 13, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Tịnh Nghi","avatar":""},{"name":"Chu Dực Nhiên","avatar":""},{"name":"Ngô Ưu","avatar":""},{"name":"Hoàng Hi Ngạn","avatar":""},{"name":"Lưu Đan","avatar":""},{"name":"Vương Nghệ Địch","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Huan Yu","煥羽","환우: 찬란히 빛나는","Возрождённая","Reborn","焕羽"]', 1784690324153);
