INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cung-duong-ve-nha', 'Cung Đường Về Nhà', 'Long Way Home', 'https://phimimg.com/upload/vod/20250513-1/7e76de3921523471e94a86b7021866c8.jpg', 'https://phimimg.com/upload/vod/20250513-1/482a75549a2c29960d80aa242d201400.jpg', '<p>Đôi bạn thân Ewan McGregor và Charley Boorman chuẩn bị cho hành trình thứ tư trong loạt phim Cung Đường — lần này từ quê nhà của Ewan ở Scotland đến nhà của Charley ở Anh. Tất nhiên, họ sẽ chọn cung đường đẹp nhất, đi qua 17 quốc gia châu Âu trên chiếc mô tô cũ khó chiều.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Ewan McGregor","avatar":""},{"name":"Charley Boorman","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["דרך ארוכה הביתה","롱 웨이 홈","长路绵绵","Long Way Home"]', 1784690324153);
