INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thang-cap-manh-nhat', 'Thăng Cấp Mạnh Nhất', 'The Strongest Upgrade, The Mightiest Level Up', 'https://phimimg.com/upload/vod/20250308-1/8afb345e4dfd00972423029ea7d9cc95.jpg', 'https://phimimg.com/upload/vod/20250308-1/02bc24a35b294ea2ddc6d7240f5ef27d.jpg', '<p>Triệu Phóng mang theo hệ thống trò chơi xuyên đến dị giới, phát hiện mình lại là một thiếu gia phế vật bị phế võ công, bên cạnh chỉ có một thị nữ đi theo. Đối mặt với nghịch cảnh, Triệu Phóng không hề nản lòng, mà ngược lại, cảm thấy đây chính là cơ hội để thể hiện bản thân. Dựa vào kinh nghiệm chơi game dày dặn, hắn thành công tìm ra &quot;Bug&quot; của hệ thống, liều mạng cày cấp. Vượt qua vô số hiểm cảnh, tiến vào vô vàn bí cảnh, hoàn thành hàng loạt nhiệm vụ do hệ thống sắp đặt…</p>', 'Hoàn Tất (40/40)', 40, 'hoathinh', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"清殇","avatar":""},{"name":"Ying Shuai","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Zuì Qiáng Shēngjí","Zui Qiang Shengji","Zuiqiang Shengji","Zuì Qiáng Shēng Jí","La Mejora Más Poderosa","ゲーム世界で最強レベルアップ","이세계의 최강레벨업","The Strongest Upgrade","TheStrongestSupgrade","Mightiest Leveling Up System","The Great Level Up","TheStrongestUpgrade","Action Level-up","Strongest Leveling","The Mightiest Level Up","The Strongest Update","Thăng Cấp Mạnh Nhất","最强升级"]', 1784690324153);
