INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duoc-su-tu-su-phan-2', 'Dược Sư Tự Sự (Phần 2)', 'The Apothecary Diaries (Season 2)', 'https://phimimg.com/upload/vod/20250111-1/5a0da2a01045e079c85515ffb8d0581c.jpg', 'https://phimimg.com/upload/vod/20250111-1/8207a9e5ea27b9079f36ca5b61e32ee6.jpg', '<p>Trong triều đình phong kiến Trung Quốc, một vài tháng đã trôi qua kể từ khi bé gái 17 tuổi có tên Miêu Miêu bị bắt cóc và bị buộc làm người hầu cấp thấp trong cung điện hoàng gia. Tuy nhiên, cô bé vẫn giữ tinh thần tích cực và cứ làm việc cho đến mãn hạn. Một ngày nọ, cô đã nghe tin hai đứa con của hoàng đế bị mắc bệnh nặng. Tại đây, cô đã quyết định hành động bí mật dựa vào những kinh nghiệm có sẵn từ phố đèn đỏ nghèo để cứu chữa.

Mặc dù đã cố gắng ở ẩn nhưng Miêu Miêu lại nhanh chóng gây sự chú ý với Jinshi, một người có quyền lực nhận ra tài năng của cô. Từ đây, thân phận thực sự của Miêu Miêu được tiết lộ với những bí ẩn về y học đa dạng.</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 13, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Aoi Yuki","avatar":""},{"name":"Takeo Otsuka","avatar":""},{"name":"Katsuyuki Konishi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["药屋少女的呢喃","Zápisky lékárnice","Deníky Apatykářky","Les Carnets de l''apothicaire","The Apothecary Diaries","药师少女的独语","خاطرات دختر داروساز","خاطرات داروساز","خاطرات پزشک دختر","Kusuriya no Hitorigoto","Kusuriya no Hitorigoto 2nd Season","Записки аптекаря","Монолог фармацевта","Щоденник аптекарки","Монолог травниці","Apothecary''s Soliloquy","薬屋のひとりごと"]', 1784690324153);
