INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-dua-rodeo-cuoi-cung', 'Cuộc Đua Rodeo Cuối Cùng', 'The Last Rodeo', 'https://phimimg.com/upload/vod/20250703-1/632caf0a2ebc14d79644b9e4b7daf8a9.jpg', 'https://phimimg.com/upload/vod/20250703-1/b9913db3bcf2f02816be62d776fe4d4f.jpg', '<p>Một huyền thoại cưỡi bò đã giải nghệ chấp nhận mạo hiểm tất cả để cứu cháu trai của mình. Đối mặt với quá khứ đầy đau thương và nỗi lo sợ của gia đình, ông quyết định tham gia một cuộc thi cưỡi bò mạo hiểm với tư cách là thí sinh lớn tuổi nhất từ trước đến nay. Trên hành trình đó, ông hàn gắn những vết thương cũ với cô con gái đã xa cách và chứng minh rằng lòng dũng cảm thực sự được thể hiện khi ta chiến đấu vì gia đình.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Neal McDonough","avatar":""},{"name":"Mykelti Williamson","avatar":""},{"name":"Sarah Jones","avatar":""},{"name":"Christopher McDonald","avatar":""},{"name":"Daylon Swearingen","avatar":""},{"name":"Graham Harvey","avatar":""},{"name":"Ruve McDonough","avatar":""},{"name":"Kamen Casey","avatar":""},{"name":"Mollie Milligan","avatar":""},{"name":"Kendall Cavener","avatar":""},{"name":"Kaden Wittig","avatar":""},{"name":"Irene Bedard","avatar":""},{"name":"Matt West","avatar":""},{"name":"Clint Adkins","avatar":""},{"name":"Gabriel Sousa","avatar":""},{"name":"Kaden Taylor","avatar":""},{"name":"Brook","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["The Last Rodeo","Последнее родео","O Último Rodeio","El último rodeo","ザ・ラスト・ロデオ","El veterano"]', 1784690324153