INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-tan-cong-london-san-lung-thu-pham-danh-bom-77', 'Cuộc Tấn Công London: Săn Lùng Thủ Phạm Đánh Bom 7/7', 'Attack On London: Hunting The 7/7 Bombers', 'https://phimimg.com/upload/vod/20250703-1/f1b5d1cc5ddd94068a3bcf556010e112.jpg', 'https://phimimg.com/upload/vod/20250703-1/837575e206abf51b148f5a4570abc235.jpg', '<p>Lời kể của người trong cuộc cùng thước phim chưa từng công bố vén màn câu chuyện về vụ đánh bom ngày 7/7 vào mạng lưới giao thông của London năm 2005 và hậu quả kinh hoàng sau đó.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Atentado en Londres","7/7: Hunting the London Bombers","Attack on London: Hunting the 7/7 Bombers"]', 1784690324153);
