INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phat-truc-tuyen', 'Phát Trực Tuyến', 'Streaming', 'https://phimimg.com/upload/vod/20250626-1/cd4326de111d2e1216c8676a20c47a25.jpg', 'https://phimimg.com/upload/vod/20250626-1/88caee80b8c521719d4e018840225848.jpg', '<p>Woo Sang là một streamer nổi tiếng trên mạng. Trong các video của mình, anh chuyên phân tích tâm lý tội phạm và là người có lượng người theo dõi cao nhất trên nền tảng trực tuyến mà anh sử dụng. Trong một lần livestream, Woo Sang bắt đầu điều tra các manh mối liên quan đến một vụ án mạng liên hoàn chưa có lời giải. Quá trình điều tra của anh được phát sóng trực tiếp trên mạng, khiến sự thật dần được hé lộ trước mắt hàng triệu khán giả.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kang Ha-neul","avatar":""},{"name":"Ha Seo-yoon","avatar":""},{"name":"Kang Ha-kyung","avatar":""},{"name":"Ha Hyun-soo","avatar":""},{"name":"Kim Ki-doo","avatar":""},{"name":"Park Tae-san","avatar":""},{"name":"Choo Suk-young","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Streaming","流播","스트리밍"]', 1784690324153);
