INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoi-ma-hien-me-cho-quy-pengantin-iblis', 'Cưới Ma: Hiến Mẹ Cho Quỷ (Pengantin Iblis)', 'The Demon''s Bride', 'https://phimimg.com/upload/vod/20250703-1/b82a642da3b27136623b83532f8704c5.jpg', 'https://phimimg.com/upload/vod/20250703-1/6e7dc71c86288e6275d92597a6c5d7d1.jpg', '<p>Khi con gái bị thương nặng, một người mẹ tuyệt vọng đã thỏa thuận với một con quỷ để cứu lấy mạng sống của con — nhưng cái giá phải trả sẽ được định đoạt bằng máu.</p>', 'Full', 1, 'single', 'completed', 19, 2025, 'Vietsub', 'FHD', 'Indonesia', 1, '[{"name":"Taskya Namya","avatar":""},{"name":"Wafda Saifan Lubis","avatar":""},{"name":"Arla Ailani","avatar":""},{"name":"Givina Lukita","avatar":""},{"name":"Bukie B. Mansyur","avatar":""},{"name":"Ratna Riantiarno","avatar":""},{"name":"Shaqueena Medina","avatar":""},{"name":"Elly D. Luthan","avatar":""},{"name":"Andi Bersama","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Cưới Ma: Hiến Mẹ Cho Quỷ","รันตี แต่งผี ปลุกปีศาจ","កូនក្រមុំបិសាចសណ្ឋិត","Pengantin Iblis"]', 1784690324153);
