INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoi-ma-hien-me-cho-quy-pengantin-iblis', 'Cưới Ma: Hiến Mẹ Cho Quỷ (Pengantin Iblis)', 'The Demon''s Bride', 'cưới ma: hiến mẹ cho quỷ (pengantin iblis) the demon''s bride taskya namya wafda saifan lubis arla ailani givina lukita bukie b. mansyur ratna riantiarno shaqueena medina elly d. luthan andi bersama cưới ma: hiến mẹ cho quỷ รันตี แต่งผี ปลุกปีศาจ កូនក្រមុំបិសាចសណ្ឋិត pengantin iblis', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-thu-2025', 'Báo Thù', 'Tornado', 'https://phimimg.com/upload/vod/20250703-1/ecf02da71f559d6b5c1f979944ec058a.jpg', 'https://phimimg.com/upload/vod/20250703-1/1d0d2f213f44c2c6437446e9f761d741.jpg', '<p>Sau khi chứng kiến cha bị sát hại bởi một băng cướp tàn bạo, một cô gái trẻ – con của một samurai – buộc phải lẩn trốn và che giấu danh tính trong một đoàn xiếc. Nhưng nỗi đau không cho phép cô lùi bước. Với thanh kiếm trong tay và cơn giận trong tim, cô lần lượt truy lùng và tiêu diệt từng kẻ thù trong hành trình báo thù đẫm máu giữa miền hoang dã.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Kōki","avatar":""},{"name":"Tim Roth","avatar":""},{"name":"Jack Lowden","avatar":""},{"name":"Takehiro Hira","avatar":""},{"name":"Rory McCann","avatar":""},{"name":"Ian Hanmore","avatar":""},{"name":"Jamie Michie","avatar":""},{"name":"Jack Morris","avatar":""},{"name":"Sammy Hayman","avatar":""},{"name":"Nathan Malone","avatar":""},{"name":"Dennis Okwera","avatar":""},{"name":"Raphaël Thiéry","avatar":""},{"name":"Joanne Whalley","avatar":""},{"name":"Alex Macqueen","avatar":""},{"name":"Douglas Russell","avatar":""},{"name":"Bryan Michael Mills","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["トルネード","Tornado"]', 1784690324153);
