INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-thua-ke-tam-duc', 'Người Thừa Kế Tâm Đức', 'The Heir Of Tâm Đức', 'https://phimimg.com/upload/vod/20250530-1/bfa3b7e065222e702ad66db35a5c0e0c.jpg', 'https://phimimg.com/upload/vod/20250530-1/4bea22c4412aff391dfcec11f0969622.jpg', '<p>Bước vào tuổi thất tuần, khi có trong tay tất cả, ông Tâm vẫn ngày đêm day dứt với đam mê làm Mì Quảng năm nào đã bị chính bản thân chối bỏ dẫn đến tâm bệnh. Để giúp ông nội vượt qua gánh nặng tâm lý, Thảo Nhi đã thuê chàng trai không ước mơ, không nghề ngỗng là Hoàng Trung trở thành nhân vật chính trong vở kịch tái hiện lại cuộc đời năm nào của ông Tâm và khơi gợi lại nơi ông khát vọng được sống để tiếp tục hành trình gầy dựng lại thương hiệu mì quảng Tâm Đức. Từ đó mở ra những thước phim về tinh hoa ẩm thực của mì Quảng truyền thống qua những nỗ lực, kiên trì của người trẻ trên con đường mang hương vị mì Quảng Việt đi khắp mọi nơi.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Mi Lan","avatar":""},{"name":"Trần Phong","avatar":""},{"name":"Ngọc Thuận","avatar":""},{"name":"Ngô Thành Tá","avatar":""},{"name":"Hoàng Như Mỹ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324153);
