INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('marvels-ironheart', 'Marvel''s Ironheart', 'Ironheart', 'https://phimimg.com/upload/vod/20250625-1/ce0e1cbcc54be7bcf67a9eb0dfa9c708.jpg', 'https://phimimg.com/upload/vod/20250625-1/affb242195ba90a9d8b976b7d61e2d0b.jpg', '<p>Lấy bối cảnh sau các sự kiện của “Black Panther: Wakanda Forever”, Riri trở lại Chicago và tiếp tục theo đuổi lý tưởng của mình. Song hành trình này không hề dễ dàng, khi Riri sớm bị cuốn vào một cuộc đối đầu gây cấn với Parker Robbins, hay còn gọi là The Hood (Anthony Ramos thủ vai), một phản diện bí ẩn sử dụng phép thuật. Cuộc đối đầu giữa công nghệ và ma thuật hứa hẹn là trục xung đột chính, tạo nên màu sắc riêng cho loạt phim.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dominique Thorne","avatar":""},{"name":"Anthony Ramos","avatar":""},{"name":"Lyric Ross","avatar":""},{"name":"Alden Ehrenreich","avatar":""},{"name":"Regan Aliyah","avatar":""},{"name":"Manny Montana","avatar":""},{"name":"Matthew Elam","avatar":""},{"name":"Anji White","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["钢铁之心","Marvels - Ironheart","القلب الحديدي","Marvel Studios'' Ironheart","Marvel Television''s Ironheart","Iron Heart","Ironheart"]', 1784690324153);
