INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muon-hon-doat-xac', 'Mượn Hồn Đoạt Xác', 'Bring Her Back', 'https://phimimg.com/upload/vod/20250702-1/3f4cdf15e864623e39d1b126aaac1cea.jpg', 'https://phimimg.com/upload/vod/20250702-1/793f59266c833ca9828a36ea1b4a529f.jpg', '<p>Sự trở lại của bộ óc sáng tạo đằng sau Talk to Me, Danny và Michael Philippou cùng A24 với một bộ phim kinh dị mới nhất Mượn Hồn Đoạt Xác. Nhiều người tin rằng linh hồn vẫn sẽ ở lại trong thân xác một thời gian trước khi rời đi, đây cũng là niềm tin đáng sợ cho nghi lễ ám ảnh nhất tháng 5.</p>', 'Full', 1, 'single', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"Sally Hawkins","avatar":""},{"name":"Sora Wong","avatar":""},{"name":"Billy Barratt","avatar":""},{"name":"Jonah Wren Phillips","avatar":""},{"name":"Mischa Heywood","avatar":""},{"name":"Stephen Phillips","avatar":""},{"name":"Sally-Anne Upton","avatar":""},{"name":"Kathryn Adams","avatar":""},{"name":"Brian Godfrey","avatar":""},{"name":"Brendan Bacon","avatar":""},{"name":"Olga Miller","avatar":""},{"name":"Liam Damons","avatar":""},{"name":"Nicola Tiele","avatar":""},{"name":"Frances Cassar","avatar":""},{"name":"Asha O''Connell","avatar":""},{"name":"Arianny Ross","avatar":""},{"name":"Amya","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Faça Ela Voltar","滿血復活","Haz que regrese","還魂","Haz Que Regrese","Oddaj ją","Верни её из мёртвых","Mượn Hồn Đoạt Xác","Reviens-moi","להחזיר אותו","Onu Geri Getir","Vrati mi je","Too ta tagasi","Φέρ'' την Πίσω","Hozd vissza őt","Volta Para Mim","Devuélvemela","Bring Her Back"]', 1784690324153);
