INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('muon-hon-doat-xac', 'Mượn Hồn Đoạt Xác', 'Bring Her Back', 'mượn hồn đoạt xác bring her back sally hawkins sora wong billy barratt jonah wren phillips mischa heywood stephen phillips sally-anne upton kathryn adams brian godfrey brendan bacon olga miller liam damons nicola tiele frances cassar asha o''connell arianny ross amya faça ela voltar 滿血復活 haz que regrese 還魂 haz que regrese oddaj ją верни её из мёртвых mượn hồn đoạt xác reviens-moi להחזיר אותו onu geri getir vrati mi je too ta tagasi φέρ'' την πίσω hozd vissza őt volta para mim devuélvemela bring her back', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-nap-noi-vuc-sau', 'Ẩn Nấp Nơi Vực Sâu', 'Abyss Dweller', 'https://phimimg.com/upload/vod/20250610-1/33117a6e31eb5f3fc7b8c5652c120454.jpg', 'https://phimimg.com/upload/vod/20250610-1/53e2553724894375b2b92fe7e3e08c60.jpg', '<p>Phim lấy bối cảnh Thượng Hải năm 1940, Lương Sóc – một chiến sĩ tình báo bị mất trí nhớ sau chấn thương – vô tình rơi vào vòng xoáy giữa quân Nhật và Sở Mật vụ 76 của chính quyền Uông Ngụy. Khi đại hội do Nhật tổ chức sắp diễn ra và âm mưu đẩy công nhân Trung Quốc ra chiến trường được triển khai, kế hoạch giải cứu mang tên “Tiềm Uyên” của Đảng Cộng sản bước vào giai đoạn quyết định. Trong lúc truy tìm danh sách điệp viên Nhật bị niêm phong, Lương Sóc dần khôi phục ký ức và nhận ra mình chính là đặc vụ “Thanh Sương” – người nắm giữ chìa khóa để hoàn thành nhiệm vụ.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 19, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Huỳnh Hiểu Minh","avatar":""},{"name":"Trương Giai Ninh","avatar":""},{"name":"Vu Tiểu Vĩ","avatar":""},{"name":"Gian Nhân Tư","avatar":""},{"name":"Nghệ Hiểu Kì","avatar":""},{"name":"Li Qiang","avatar":""},{"name":"Vũ Dương","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["Qian Yuan","Deep Undercover","潜渊"]', 1784690324153);
