INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyet-an-truy-hanh', 'Huyết Án Truy Hành', 'Beyond the Sin', 'https://phimimg.com/upload/vod/20250324-1/1a8f225f8cc76947cc6e11f51e4163e8.jpg', 'https://phimimg.com/upload/vod/20250324-1/6db9f73843cc667d69ab821ef288a01e.jpg', '<p>Vào một đêm mưa, thi thể Gia Kỳ - con gái của cảnh sát Lạc Nhất Ngôn phát hiện tử vong. Vì không đủ bằng chứng kết tội, Khâu Tuấn Văn (nghi phạm) được thả tự do. Lạc Nhất Ngôn rời khỏi lực lượng cảnh sát. Thế nhưng, những cái chết không hề dừng lại, Lạc Nhất Ngôn nhận ra nhiều cô gái khác cũng bị sát hại dã man với cách thức giống nhau khiến ông tin rằng hung thủ thực sự vẫn còn đang nhởn nhơ ngoài vòng pháp luật. Qua quá trình điều tra, ông dần tìm ra nhân chứng duy nhất chứng kiến cảnh phạm tội của hung thủ. Đáng tiếc thay, nhân chứng lại là một cô bé thiểu năng trí tuệ. Bao nhiêu biến cố dần ập đến khiến người cha, người chồng, Lạc Nhất Ngôn gần như ngã quỵ… Liệu rằng Lạc Nhất Ngôn sẽ buông bỏ hiện thực hay ông sẽ vùng lên giành lại công lý cho con gái bị sát hại thảm thương?</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 1, '[{"name":"Louis Koo","avatar":""},{"name":"Gordon Lam Ka-Tung","avatar":""},{"name":"Louis Cheung","avatar":""},{"name":"Venus Wong Man-Yik","avatar":""},{"name":"Stephanie Che Yuen-Yuen","avatar":""},{"name":"Karena Lam Kar-Yan","avatar":""},{"name":"Larine Tang Yue-Ping","avatar":""},{"name":"Paulyn Sun","avatar":""},{"name":"Locker Lam Ka-Hei","avatar":""},{"name":"Renci Yeung","avatar":""},{"name":"Summer Chan","avatar":""},{"name":"Angel Lam Chin-Ting","avatar":""},{"name":"Timothy Cheng Chi-Sing","avatar":""},{"name":"Terry Zou Wen-Zheng","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["惡行之外"]', 1784690324153);
