INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tu-vu-tru-john-wick-ballerina', 'Từ Vũ Trụ John Wick: Ballerina', 'Ballerina', 'từ vũ trụ john wick: ballerina ballerina ana de armas keanu reeves ian mcshane anjelica huston gabriel byrne catalina sandino moreno ava mccarthy juliet doherty norman reedus lance reddick sharon duncan-brewster david castañeda victoria comte robert maaser sooyoung choi jung doo-h ballerina john wick presents: ballerina john wicki maailmast: baleriin ballerina: from the world of john wick de l''univers de john wick : ballerina bailarina: do universo de john wick bailarina ballerina : de l''univers de john wick john wick - ballerina - from the world of john wick 발레리나 バレリーナ john wick dünyasından ballerina balerin', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-trom-khong-the-giau-hua-hen', 'Vụng Trộm Không Thể Giấu: Hứa Hẹn', 'Hidden Love For You', 'https://phimimg.com/upload/vod/20250626-1/c94335a6fdbd94c3288fe325c43eb769.jpg', 'https://phimimg.com/upload/vod/20250626-1/62f5c4285be3a2e6eec406a08618427e.jpg', '<p>Đoàn Gia Hứa và Tang Trĩ bén duyên từ một lần Tang Trĩ nhờ người đến trường họp phụ huynh. Từ đó, Đoàn Gia Hứa cũng coi Tang Trĩ như em gái ruột mà yêu thương hết lòng. Sau khi Đoàn Gia Hứa tốt nghiệp đại học, hai người xa cách hai nơi, lại vì một số hiểu lầm mà quan hệ trở nên xa cách. Mãi đến khi Tang Trĩ trưởng thành thi đậu vào thành phố Đoàn Gia Hứa đang ở như ước muốn, hai người mới gặp lại. Qua những lần tiếp xúc ngày càng thân mật, Tang Trĩ dần nhận ra nguồn cơn áp lực bấy lâu nay của Đoàn Gia Hứa. Cô muốn bảo vệ người anh trai luôn đối xử tốt với mình này, tình cảm thầm kín chôn giấu trong lòng lại bùng cháy. Dưới sự đồng hành của Tang Trĩ, Đoàn Gia Hứa dần cởi bỏ khúc mắc trong lòng, anh thật lòng yêu thích Tang Trĩ trưởng thành, mối tình thầm kín thuần khiết cuối cùng cũng đơm hoa kết trái, cùng nhau trải qua quá trình trưởng thành tuổi thanh xuân, khích lệ và giúp đỡ nhau.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Điền Hồng Kiệt","avatar":""},{"name":"Hoàng Bảo Bảo","avatar":""},{"name":"Mã Trác","avatar":""},{"name":"Tăng Khánh Thịnh","avatar":""},{"name":"Lưu Bác Hựu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["偷偷藏不住","偷偷藏不住之許你","Tou Tou Cang Bu Zhu Zi Xu Ni","Secretly, Secretly","But Unable to Hide It","偷偷藏不住之许你"]', 1784690324153);
