INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cua-cam-thieu-chu-lanh-lung', 'Cưa Cẩm Thiếu Chủ Lạnh Lùng', 'To Get Master', 'https://phimimg.com/upload/vod/20250620-1/842d6c9239710c476dc86510785bfcd9.jpg', 'https://phimimg.com/upload/vod/20250620-1/ab7f06c73ad365f370883831970fc177.jpg', '<p>Phim kể về Lê Tụng Nhi, quận chúa của nước Túy Mộng, từ nhỏ sống trong nhung lụa, được nuông chiều hết mực, bất ngờ xuyên không vào cuốn tiểu thuyết &quot;Duy Ngã Độc Tôn&quot;. Trong một tình huống trớ trêu, nàng gặp phải &quot;đại ma đầu&quot; Cố Uyên. Lê Tụng Nhi tìm mọi cách để thoát khỏi tay tên &quot;đại ma đầu&quot; đó, nhưng trớ trêu thay, điểm then chốt để trở về nước Túy Mộng lại chính là Cố Uyên. Vì vậy, nàng buộc phải ở lại bên cạnh hắn, từ đó mở ra một mối quan hệ giằng xé, vừa yêu vừa hận.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Tuấn Ninh","avatar":""},{"name":"Bao Thượng Ân","avatar":""},{"name":"Thôi Thiệu Dương","avatar":""},{"name":"Lưu Tư Thần","avatar":""},{"name":"Lý Gia Tường","avatar":""},{"name":"Thang Duy Văn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["书中公子世无双","攻略冷少主"]', 1784690324153);
