INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-ban-cua-ca-map', 'Người Bạn Của Cá Mập', 'Shark Whisperer', 'https://phimimg.com/upload/vod/20250701-1/2021056da82b18f1e768b26a12215c15.jpg', 'https://phimimg.com/upload/vod/20250701-1/ea6ac668fc7c4e7ccfc6de96ad45b3a9.jpg', '<p>Nhà bảo tồn biển kiêm nhà hoạt động trên mạng xã hội Ocean Ramsey dũng cảm bơi cùng cá mập trong bộ phim tài liệu khám phá sâu sứ mệnh của cô nhằm bảo vệ loài sinh vật này.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ocean Ramsey","avatar":""},{"name":"Juan Oliphant","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Shark Whisperer"]', 1784690324153);
