INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quoc-sac-phuong-hoa', 'Quốc Sắc Phương Hoa', 'Flourished Peony', 'https://phimimg.com/upload/vod/20250108-1/79efa1a4c6ae41c8a787fc996bd05bf0.jpg', 'https://phimimg.com/upload/vod/20250108-1/8520f30d266240d2aa6bd0f97476b212.jpg', '<p>Quốc Sắc Phương Hoa là hành trình lập nghiệp của mỹ nhân Hà Duy Phương ở thời nhà Đường. Sau khi từ bỏ cuộc hôn nhân không hạnh phúc, Hà Duy Phương một mình lên kinh thành để làm lại cuộc đời. Ở đây, bằng khả năng ươm trồng hoa mẫu đơn quý hiếm và óc kinh doanh nhạy bén, nàng bắt đầu tạo dựng nên thương hiệu “Hoa Tưởng Dung” nổi tiếng bậc nhất. Không chỉ có thế, nàng còn ra tay giúp đỡ những người phụ nữ có số phận gian truân và cùng Tưởng Trường Dương, quan cận thần của hoàng đế, chung tay chống lại thế lực xấu xa để bảo vệ đất nước.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 10, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Tử","avatar":""},{"name":"Lý Hiện","avatar":""},{"name":"Ngụy Triết Minh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["锦绣芳华","국색방화","금수방화","錦繡芳華","Flourished Peony","In The Name of Blossom","国色芳华"]', 1784690324153);
