INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-ma-coi-mang', 'Bóng Ma Cõi Mạng', 'Horror Express', 'https://phimimg.com/upload/vod/20250701-1/f3eae105144188a47b91d80745a7ee2a.jpg', 'https://phimimg.com/upload/vod/20250701-1/cc986f96790d1a9f8ac4249e271d400e.jpg', '<p>Trong nỗ lực cứu vãn kênh Youtube tâm huyết, Jyujuring quyết định tổ chức livestream ngay tại một ngôi nhà hoang bí ẩn, nơi mà chưa ai từng dám đặt chân đến. Giây phút cánh cửa mở ra cũng là lúc trò &quot;câu view&quot; hóa thành cơn ác mộng tồi tệ nhất cho những kẻ phạm phải điều cấm kỵ.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Go I-gyoung","avatar":""},{"name":"Lee Tae-ri","avatar":""},{"name":"Oh Ha-ni","avatar":""},{"name":"Lee Ki-chang","avatar":""},{"name":"A-in","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["공포특급"]', 1784690324153);
