INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luoi-dao-gay', 'Lưỡi Đao Gãy', 'Blade In The Shadows', 'https://phimimg.com/upload/vod/20250630-1/5b1347070f379138704730ece0bee847.jpg', 'https://phimimg.com/upload/vod/20250630-1/45c261567e0426558f97f350fbd654bf.jpg', '<p>Tại Bến Thượng Hải thời Dân Quốc, những cuộc chiến ngầm diễn ra không ngớt. Những người Đảng Cộng sản đã dùng chính sinh mệnh của mình để viết nên từng câu chuyện cảm động. Họ tựa như những vì sao, tự đốt cháy mình để soi đường cho nhân dân trong đêm dài tăm tối. Đảng viên ngầm Tiêu Khách nhận lệnh trong lúc lâm nguy, nhận lấy chiếc trâm cài áo chứa mật mã rút lui từ tay đồng đội có mật danh &quot;Chim Sẻ&quot;, nhưng vì sự phản bội của nội gián mà rơi vào vòng vây truy sát của kẻ địch. Nhân sĩ giang hồ Lưu Vân Sơn đã xả thân bảo vệ. Từ việc giải mã ở chợ quỷ, truyền tin bằng khúc nhạc, cho đến cuộc đọ sức tại các điểm rút lui thật giả, trong chuỗi đấu trí và truy sát sinh tử đan xen, không chỉ có những con sóng ngầm của nhân tính khi bạn học trở mặt, kẻ phản bội đội lốt, mà còn nổi bật lên niềm tin sục sôi, sẵn sàng lấy tính mạng để đổi lấy ánh bình minh. Qua những lần lưu chuyển của chiếc trâm cài áo là sự căng thẳng hồi hộp muôn trùng, và còn là bản trường ca về tinh thần của hàng vạn con người dũng cảm đơn độc, đã dùng máu xương của mình để trải đường cho cách mạng.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Lôi Phương","avatar":""},{"name":"Dương Thịnh Nghiệp","avatar":""},{"name":"Đặng Lị","avatar":""},{"name":"Trương Trác Y","avatar":""},{"name":"Lý Hạo Nam","avatar":""},{"name":"Chu Tường","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Blade of Faith","破刃"]', 1784690324153);
