INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('zatsu-tabi-do-la-cuoc-hanh-trinh', 'Zatsu Tabi: Đó Là Cuộc Hành Trình', 'Zatsu Tabi: That''s Journey', 'https://phimimg.com/upload/vod/20250416-1/747b9b073a7721e9889bca017f653cf2.jpg', 'https://phimimg.com/upload/vod/20250416-1/6a1247f90d7fed3a88bd2d1f2b1b05de.jpg', '<p>Chika Suzugamori, một họa sĩ truyện tranh mới vào nghề, đã bị từ chối mỗi lần cô nộp bản thảo mới. Khi đang trên bờ vực bỏ cuộc, cô đột nhiên nảy ra ý tưởng thực hiện một chuyến đi—một chuyến đi chữa lành chính xác vì nó khó khăn. Đây là truyện tranh du lịch tuyệt đỉnh!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hika Tsukishiro","avatar":""},{"name":"Sayumi Suzushiro","avatar":""},{"name":"Sae Hiratsuka","avatar":""},{"name":"Satomi Sato","avatar":""},{"name":"Yoko Hikasa","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["随兴旅 -That''s Journey-","杂旅 -That''s Journey-","Zatsu Tabi: That''s Journey","隨興旅－That′s Journey","Miscellaneous Journey","Zatsu Tabi -That''s Journey-","ざつ旅 -That''s Journey-"]', 1784690324153);
