INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('shirohiyo-dau-thai-thanh-quy-toc-map-u-toi-dung-ky-uc-kiep-truoc-de-nuoi-day-em-trai', 'SHIROHIYO: Đầu Thai Thành Quý Tộc Mập Ú, Tôi Dùng Ký Ức Kiếp Trước Để Nuôi Dạy Em Trai', 'SHIROHIYO: Reincarnated As A Neglected Noble Raising My Baby Brother With Memories From My Past Life', 'https://phimimg.com/upload/vod/20250421-1/8d729b51bfd50958e54235650c45adcd.jpg', 'https://phimimg.com/upload/vod/20250421-1/5ceefa65d2082a5bdf500990f69e370a.jpg', '<p>Trong thế giới lấp lánh, huyền ảo này, có rất nhiều sự sang trọng và kỳ diệu! Những yêu tinh xinh đẹp và duyên dáng, những vị thần vượt quá tầm hiểu biết của con người, sức mạnh của phép thuật—mọi thứ đều giống như một giấc mơ. Và quan trọng nhất, còn có &quot;gà con&quot; lông bông và cậu em trai đáng yêu, Regulus, người yêu quý anh cả của mình hơn bất cứ thứ gì. Nhưng bên dưới bề mặt rực rỡ này, những căng thẳng tiềm ẩn vẫn âm ỉ trong gia đình quý tộc Kikunoi, trong khi sự thối nát của tầng lớp quý tộc hoàng gia vẫn tiếp tục lan rộng…</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Mariya Ise","avatar":""},{"name":"Misaki Kuno","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["觉醒前世记忆的白豚贵族决定培养弟弟","转生为白猪贵族的我，运用前世记忆养育雏鸟般的弟弟","Shirobuta Kizoku desu ga Zense no Kioku ga Haeta node Hiyoko na Otouto Sodatemasu","Shirobuta Kizokudesuga Zensenokiokuga Haetanode Hiyokonaotoutosodatemasu","しろひよ","Аристократ с лишним весом","雖然是白豬貴族但因為擁有前世記憶所以要養育雛鳥般的弟弟","轉生為白豬貴族的我，運用前世記憶養育雛鳥般的弟弟","I''m the White Pig Nobleman, but With the Memories of My Previous Life, I''ll Raise My Little Brother","I''m a White Pig of an Aristocrat, but I Developed Memories of My Previous Life, So I''m Raising My Younger Brother to Be Like a Small Chick","SHIROHIYO - Reincarnated as a Neglected Noble","白豚貴族ですが前世の記憶が生えたのでひよこな弟育てます"]', 1784690324153);
