INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('shirohiyo-dau-thai-thanh-quy-toc-map-u-toi-dung-ky-uc-kiep-truoc-de-nuoi-day-em-trai', 'SHIROHIYO: Đầu Thai Thành Quý Tộc Mập Ú, Tôi Dùng Ký Ức Kiếp Trước Để Nuôi Dạy Em Trai', 'SHIROHIYO: Reincarnated As A Neglected Noble Raising My Baby Brother With Memories From My Past Life', 'shirohiyo: đầu thai thành quý tộc mập ú, tôi dùng ký ức kiếp trước để nuôi dạy em trai shirohiyo: reincarnated as a neglected noble raising my baby brother with memories from my past life mariya ise misaki kuno 觉醒前世记忆的白豚贵族决定培养弟弟 转生为白猪贵族的我，运用前世记忆养育雏鸟般的弟弟 shirobuta kizoku desu ga zense no kioku ga haeta node hiyoko na otouto sodatemasu shirobuta kizokudesuga zensenokiokuga haetanode hiyokonaotoutosodatemasu しろひよ аристократ с лишним весом 雖然是白豬貴族但因為擁有前世記憶所以要養育雛鳥般的弟弟 轉生為白豬貴族的我，運用前世記憶養育雛鳥般的弟弟 i''m the white pig nobleman, but with the memories of my previous life, i''ll raise my little brother i''m a white pig of an aristocrat, but i developed memories of my previous life, so i''m raising my younger brother to be like a small chick shirohiyo - reincarnated as a neglected noble 白豚貴族ですが前世の記憶が生えたのでひよこな弟育てます', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tranh-cu-hoc-duong', 'Tranh Cử Học Đường', 'I Am A Running Mate', 'https://phimimg.com/upload/vod/20250619-1/045e4ac000c394b2821f6c7458f96a79.jpg', 'https://phimimg.com/upload/vod/20250619-1/7714f3a92b9413d1a797e2c93671fc63.jpg', '<p>Sau một sự cố, học sinh gương mẫu No Se Hun trở thành trò cười của cả trường. Để lấy lại danh tiếng, Se Hun đồng ý làm ứng cử viên phó chủ tịch hội học sinh, cùng tranh cử với Yang Won Dae. Tuy nhiên, khi biết mình chỉ là lựa chọn thứ 12 của Won Dae, Se Hun quyết định hợp tác với Kwak Sang Hyun, một nam sinh được rất nhiều bạn bè trong trường quý mến. Không chỉ xoay quanh các cuộc đối đầu kịch tính, Tranh Cử Học Đường (I Am A Running Mate) còn khai thác góc khuất của đời sống học sinh và những áp lực tuổi trưởng thành.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 33, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yoon Hyun-soo","avatar":""},{"name":"Lee Jung-sic","avatar":""},{"name":"Kim Ji-woo","avatar":""},{"name":"Choi Woo-sung","avatar":""},{"name":"Hong Hwa-yeon","avatar":""},{"name":"Lee Bong-joon","avatar":""},{"name":"Ok Jin-uk","avatar":""},{"name":"Yoon Do-gun","avatar":""},{"name":"Hwang Sung-bin","avatar":""},{"name":"Kim Ji-hoon","avatar":""},{"name":"Jo Yoon","avatar":""},{"name":"Park Keun-rok","avatar":""},{"name":"Kwon Han-sol","avatar":""},{"name":"Han Hyeon-jun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '["러닝 메이트","런닝메이트","런닝 메이트","Напарник","انا رفيق الركض","I Am a Running Mate","Running Mate","러닝메이트"]', 1784690324153);
