INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tranh-cu-hoc-duong', 'Tranh Cử Học Đường', 'I Am A Running Mate', 'tranh cử học đường i am a running mate yoon hyun-soo lee jung-sic kim ji-woo choi woo-sung hong hwa-yeon lee bong-joon ok jin-uk yoon do-gun hwang sung-bin kim ji-hoon jo yoon park keun-rok kwon han-sol han hyeon-jun 러닝 메이트 런닝메이트 런닝 메이트 напарник انا رفيق الركض i am a running mate running mate 러닝메이트', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ngoi-sao-nhac-co-dien', 'Những Ngôi Sao Nhạc Cổ Điển', 'Classic Stars', 'https://phimimg.com/upload/vod/20250407-1/b04f5e321f28ee2d17d35abc2e9f1765.jpg', 'https://phimimg.com/upload/vod/20250407-1/6517e015b88e3e276d13996b4b3f5a9a.jpg', '<p>Tại Học viện Tư thục Gloria – nơi quy tụ những tài năng trẻ được kỳ vọng trong tương lai trong các lĩnh vực âm nhạc, nghệ thuật, thể thao và giải trí – một dự án đặc biệt đang diễn ra. Tại khoa Âm nhạc, những học sinh có mức độ tương thích cao với “tài năng (tiềm năng)” của các nhà soạn nhạc vĩ đại trong quá khứ sẽ được cấy ghép “Gift” (món quà), và từ đó được gọi bằng tên của chính nhà soạn nhạc đó. Beethoven, một chàng trai trẻ tình cờ được phát hiện có mức độ tương thích sau một chấn thương, cũng trở thành một trong số họ. Cậu chuyển vào học viện và bắt đầu làm quen với những người bạn mang các “Gift” khác nhau. Cùng nhau, họ trải nghiệm sức hấp dẫn của âm nhạc và hướng tới chiến thắng trong các cuộc thi âm nhạc lớn. Một bản giao hưởng kỳ diệu nơi âm nhạc (Emotion) và không gian thực tế ảo (Visualize) hòa quyện – một **dự án mộng mơ nối tiếp ý chí của những nhạc sĩ vĩ đại tới tương lai – chính thức bắt đầu!</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["古典乐★之星","Звёзды ★ классики","Звёзды классики","Classic Stars","CLASSICSTARS","クラシック★スターズ"]', 1784690324153);
