INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truc-dien-thoai-phan-1', 'Trực Điện Thoại (Phần 1)', 'On Call (Season 1)', 'https://phimimg.com/upload/vod/20250629-1/21ad279e4c79c68bca40e71adb7f9bb0.jpg', 'https://phimimg.com/upload/vod/20250629-1/2bb69f288d46bacf84ba76cace43d345.jpg', '<p>Traci Harmon, một nữ sĩ quan huấn luyện kỳ cựu, cùng với tân binh nam Alex Diaz – người đang thực tập đi tuần – phải đối mặt với nỗi mất mát sau cái chết của một đồng nghiệp. Đồng thời, cả hai cũng phải vật lộn với những rối ren và chính trị trong môi trường cảnh sát hiện đại — cả trong nội bộ sở và ngoài đường phố tại Long Beach.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Troian Bellisario","avatar":""},{"name":"Brandon Larracuente","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["En Service","待命警察","热线警报","Al Filo del Deber","On Call","На дежурстве"]', 1784690324153);
