INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('toi-roi-to-doi-hang-a-de-giup-hoc-tro-cu-tien-sau-vao-ham-nguc', 'Tôi Rời Tổ Đội Hạng A Để Giúp Học Trò Cũ Tiến Sâu Vào Hầm Ngục', 'I Left My A-Rank Party to Help My Former Students Reach the Dungeon Depths!', 'tôi rời tổ đội hạng a để giúp học trò cũ tiến sâu vào hầm ngục i left my a-rank party to help my former students reach the dungeon depths! hiromu mineta hana inami natsumi kawaida nene hieda sekai tsuyoshi koyama yoshino nanjou hisako kanemoto satoshi hino mao ichimichi 脱离了a级队伍的我，和从前的徒弟们前往迷宫深处。 离开 a 级队伍的我，和从前的弟子往迷宫深处迈进 a-rank party wo ridatsu shita ore wa, moto oshiegotachi to meikyuu shinbu wo mezasu. aparida aランクパーティを離脱した俺は、元教え子たちと迷宮深部を目指す。 離開 a 級隊伍的我，和從前的弟子往迷宮深處邁進 after leaving the a-rank party, i aim for the deep part of the labyrinth with my former students i left my a-rank party to help my students reach the dungeon depths i left my a-rank party i left my arank party to help my former students reach the dungeon depths', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-cuu-long', 'Chuyện Tình Cửu Long', 'Kowloon Generic Romance', 'https://phimimg.com/upload/vod/20250406-1/776198b2dc9cfae2fd0b1e6398638b94.jpg', 'https://phimimg.com/upload/vod/20250406-1/ff65aefe44a5fe50885374a436cb8b5e.jpg', '<p>Cửu Long Thành Trại: Nơi quá khứ, hiện tại và tương lai giao thoa. Giữa những con hẻm tấp nập, một bí ẩn đen tối đang dần hé lộ. Kujirai, tưởng chừng tìm thấy tình yêu với Kudo, bỗng phát hiện ra một tấm ảnh kỳ lạ: Kudo và một cô gái giống hệt cô, nhưng cô không hề có ký ức về điều đó. Liệu đây là điềm báo gì? Sự thật nào đang ẩn sau bức ảnh, và quá khứ bị lãng quên của Kujirai?</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Haruka Shiraishi","avatar":""},{"name":"Tomokazu Sugita","avatar":""},{"name":"Ryotaro Okiayu","avatar":""},{"name":"Taito Ban","avatar":""},{"name":"Aoi Koga","avatar":""},{"name":"Sayumi Suzushiro","avatar":""},{"name":"Kengo Kawanishi","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["九龍GR","Kūron Jenerikku Romansu","クーロンジェネリックロマンス","九龍ジェネリックロマンス"]', 1784690324153);
