INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-dich', 'Quý Đích', 'The Fallen Lady Returns', 'https://phimimg.com/upload/vod/20250617-1/cc799780579a44a5a79544db319dce9f.jpg', 'https://phimimg.com/upload/vod/20250617-1/20a8729f0579d0c3586d984d4598f42a.jpg', '<p>Kiếp trước sau khi bị nhà họ Chu sát hại thê thảm, quận phu nhân Trương Tịch Âm lại bất ngờ sống lại. Để trả thù phu quân Định An Hầu Chu Dịch Hồng và bình thê Lý Duyệt Uyển, Trương Tịch Âm đã chủ động tiếp cận và liên minh với Tế Vương Đoàn Tiệm Ly. Thế nhưng sau bao biến cố, mối quan hệ vốn dĩ chỉ có lợi ích của hai người lại nảy sinh những điều khác lạ...</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đằng Trạch Văn","avatar":""},{"name":"Chiến Vũ","avatar":""},{"name":"Vương Duệ Tử","avatar":""},{"name":"Tôn Tiêu Hàm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Gui Di","귀적: 정실의 역습","贵嫡"]', 1784690324153);
