INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-thuy-maebashi', 'Phù Thủy Maebashi', 'Maebashi Witches', 'https://phimimg.com/upload/vod/20250421-1/d01b6f7b68f0a394e02293987c290790.jpg', 'https://phimimg.com/upload/vod/20250421-1/61f5fe78b580e6267f0d63e239ec7a0d.jpg', '<p>Trở thành một phù thủy Maebashi—nghe có vẻ siêu thẩm mỹ không!? Đây là thành phố Maebashi, tỉnh Gunma. Đối với học sinh trung học năm nhất Yuina Akagi, cuộc sống chỉ là &quot;bình thường, tôi đoán vậy&quot;, hơi quá bình thường... Cho đến một ngày... &quot;Vậy thì sao bạn không thử trở thành một phù thủy?&quot; Với sự xuất hiện đột ngột của một con ếch bí ẩn tên là Keroppe, mọi thứ thay đổi! Cánh cửa tủ quần áo của cô giờ dẫn đến một không gian kỳ lạ và kỳ diệu…</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Sakura Kasuga","avatar":""},{"name":"Hinano Sakikawa","avatar":""},{"name":"Rena Motomura","avatar":""},{"name":"Haruka Minami","avatar":""},{"name":"Honami Momose","avatar":""},{"name":"Tomokazu Sugita","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["前橋ウィッチーズ"]', 1784690324153);
