INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-bai-giang-ky-quai-cua-thay-chuzenji', 'Nhật Ký Bài Giảng Kỳ Quái Của Thầy Chuzenji', 'The Mononoke Lecture Logs of Chuzenji-sensei: He Just Solves All the Mysteries', 'https://phimimg.com/upload/vod/20250429-1/4f0c84e4ba7280ea7cff28466f9e3948.jpg', 'https://phimimg.com/upload/vod/20250429-1/70aa822c07904b98427e2d9eda12897a.jpg', '<p>Tokyo, 1948, tàn dư chiến tranh và những bí ẩn siêu nhiên trỗi dậy. Kanna, nữ sinh trung học, tìm đến Chuzenji-sensei, giáo viên khó tính, để giải mã những hiện tượng kỳ lạ. Họ cùng nhau dấn thân vào một cuộc phiêu lưu đen tối. Trường học trở thành sân khấu cho những bí ẩn siêu nhiên, nơi sự thật ẩn sau những lời nguyền và bóng tối. Liệu họ có thể vén màn bí mật, hay sẽ bị nuốt chửng bởi những thế lực siêu nhiên?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kaori Maeda","avatar":""},{"name":"Katsuyuki Konishi","avatar":""},{"name":"Shinnosuke Tachibana","avatar":""},{"name":"Shuuya Nishiji","avatar":""},{"name":"Takanori Hoshino","avatar":""},{"name":"Ai Furihata","avatar":""},{"name":"Ai Kayano","avatar":""},{"name":"Kaoru Sakura","avatar":""},{"name":"Mitsuru Miyamoto","avatar":""},{"name":"Saki Ogasawara","avatar":""},{"name":"Yukiyo Fujii","avatar":""},{"name":"Hikaru Akao","avatar":""},{"name":"Wataru Hatano","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["中禪寺老師的靈怪講義實錄~老師會把謎題全都解開的","中禅寺老师的灵怪讲义实录~老师会把谜题全都解开的","中禅寺老师的灵怪讲义实录 老师会把谜题全都解开的。","Chūzenji-sensei Mononoke Kōgiroku: Sensei ga Nazo wo Toite Shimaukara.","Chuuzenji-sensei Mononoke Kougiroku: Sensei ga Nazo wo Toite Shimaukara.","Chuuzenjisensei Mononoke Kougiroku Sensei ga Nazo wo Toiteshimau kara","中禅寺先生物怪講義録 先生が謎を解いてしまうから。"]', 1784690324153);
