INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhat-ky-bai-giang-ky-quai-cua-thay-chuzenji', 'Nhật Ký Bài Giảng Kỳ Quái Của Thầy Chuzenji', 'The Mononoke Lecture Logs of Chuzenji-sensei: He Just Solves All the Mysteries', 'nhật ký bài giảng kỳ quái của thầy chuzenji the mononoke lecture logs of chuzenji-sensei: he just solves all the mysteries kaori maeda katsuyuki konishi shinnosuke tachibana shuuya nishiji takanori hoshino ai furihata ai kayano kaoru sakura mitsuru miyamoto saki ogasawara yukiyo fujii hikaru akao wataru hatano 中禪寺老師的靈怪講義實錄~老師會把謎題全都解開的 中禅寺老师的灵怪讲义实录~老师会把谜题全都解开的 中禅寺老师的灵怪讲义实录 老师会把谜题全都解开的。 chūzenji-sensei mononoke kōgiroku: sensei ga nazo wo toite shimaukara. chuuzenji-sensei mononoke kougiroku: sensei ga nazo wo toite shimaukara. chuuzenjisensei mononoke kougiroku sensei ga nazo wo toiteshimau kara 中禅寺先生物怪講義録 先生が謎を解いてしまうから。', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-the-la-nha-gia-kim-vi-dai-nhat-moi-thoi-dai', 'Có Thể Là Nhà Giả Kim Vĩ Đại Nhất Mọi Thời Đại?', 'Possibly The Greatest Alchemist Of All Time', 'https://phimimg.com/upload/vod/20250628-1/79dd5cc94203dd540e4dbe8b34e0dcba.jpg', 'https://phimimg.com/upload/vod/20250628-1/e90bb90054079f9d2f2ffae23359a7a1.jpg', '<p>Iruma Takumi thấy mình bị cuốn vào một buổi triệu hồi anh hùng, mặc dù anh ấy không phải là anh hùng. Bị triệu hồi nhầm đến Mildgard, một thế giới giả tưởng của kiếm và phép thuật, Takumi được trao cơ hội để bắt đầu lại. Mặc dù anh ấy mơ về một cuộc sống bình yên, nữ thần Nolyn ban cho anh ấy &quot;giả kim thuật&quot;, một kỹ năng siêu mạnh cho phép anh ấy tạo ra bất cứ thứ gì từ thánh kiếm đến tàu bay. Cuộc phiêu lưu bất đắc dĩ của anh ấy bắt đầu!</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shogo Sakata","avatar":""},{"name":"Ai Kayano","avatar":""},{"name":"Nao Toyama","avatar":""},{"name":"Afumi Hashi","avatar":""},{"name":"Sora Amamiya","avatar":""},{"name":"Nene Hieda","avatar":""},{"name":"Nobuo Tobita","avatar":""},{"name":"Kikuko Inoue","avatar":""},{"name":"Moeka Koizumi","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["终将成为最强炼金术师？","终有一天会成为最强的炼金术师？","迟早是最强的炼金术师？","Possibly the Greatest Alchemist of All Time","Izure Saikyô no Renkinjutsushi?","Izure Saikyou no Renkinjutsushi","Someday Will I Be the Greatest Alchemist?","終將成為最強鍊金術師？","遲早是最強的鍊金術師？","The Strongest Alchemist in Another World","いずれ最強の錬金術師？"]', 1784690324153);
