INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-the-la-nha-gia-kim-vi-dai-nhat-moi-thoi-dai', 'Có Thể Là Nhà Giả Kim Vĩ Đại Nhất Mọi Thời Đại?', 'Possibly The Greatest Alchemist Of All Time', 'có thể là nhà giả kim vĩ đại nhất mọi thời đại? possibly the greatest alchemist of all time shogo sakata ai kayano nao toyama afumi hashi sora amamiya nene hieda nobuo tobita kikuko inoue moeka koizumi 终将成为最强炼金术师？ 终有一天会成为最强的炼金术师？ 迟早是最强的炼金术师？ possibly the greatest alchemist of all time izure saikyô no renkinjutsushi? izure saikyou no renkinjutsushi someday will i be the greatest alchemist? 終將成為最強鍊金術師？ 遲早是最強的鍊金術師？ the strongest alchemist in another world いずれ最強の錬金術師？', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-lac-bo-am-thuc-cua-toi', 'Câu Lạc Bộ Ẩm Thực Của Tôi', 'Food For The Soul', 'https://phimimg.com/upload/vod/20250415-1/c1701136a915cf8e007fbb6f6c916b94.jpg', 'https://phimimg.com/upload/vod/20250415-1/f7e7d84a73036b3ef5b9e53040281b9f.jpg', '<p>Phim kể về cuộc sống hàng ngày của năm cô gái vừa trở thành sinh viên đại học. Họ yêu thích những món ăn ngon, muốn có nhiều niềm vui với mọi người, và học tập khó khăn hơn một chút để tận hưởng cuộc sống đại học một cách trọn vẹn!</p>', 'Tập 11', 12, 'hoathinh', 'ongoing', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hana Shimano","avatar":""},{"name":"Ai Kakuma","avatar":""},{"name":"Yoshino Aoyama","avatar":""},{"name":"Natsune Inui","avatar":""},{"name":"Saya Aizawa","avatar":""},{"name":"Azuki Moeno","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["时光流逝 饭菜依旧美味","Hibi wa Sugiredo Meshi Umashi","ひびめし","Hibimeshi","歲月流逝飯菜依舊美味","Days Go By but Food Is Delicious","日々は過ぎれど飯うまし"]', 1784690324153);
