INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cau-lac-bo-am-thuc-cua-toi', 'Câu Lạc Bộ Ẩm Thực Của Tôi', 'Food For The Soul', 'câu lạc bộ ẩm thực của tôi food for the soul hana shimano ai kakuma yoshino aoyama natsune inui saya aizawa azuki moeno 时光流逝 饭菜依旧美味 hibi wa sugiredo meshi umashi ひびめし hibimeshi 歲月流逝飯菜依舊美味 days go by but food is delicious 日々は過ぎれど飯うまし', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-duong-lo', 'Âm Dương Lộ', 'The Hitchhiker', 'https://phimimg.com/upload/vod/20250627-1/2cb1650856ea766b21df3d6f86ccdd07.jpg', 'https://phimimg.com/upload/vod/20250627-1/8db220cf033fde5a5929b285fe3789ba.jpg', '<p>Vì mưu sinh, Trọng Nhân lén cha nửa đêm chở xác một cô gái về Tây Nguyên. Trên chuyến đi, anh đã đối mặt với đầy rẫy vong hồn, người anh thầm yêu và cả sự thật về chiếc xe cứu thương anh đang lái.</p>', 'Full', 1, 'single', 'completed', 20, 2025, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Bạch Công Khanh","avatar":""},{"name":"Đại Nghĩa","avatar":""},{"name":"Ngô Phạm Hạnh Thúy","avatar":""},{"name":"Phạm Nguyễn Lan Thy","avatar":""},{"name":"Minh Hoàng","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["搭车客","The Hitchhiker","Âm Dương Lộ"]', 1784690324153);
