INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghi-pham-hoan-hao', 'Nghi Phạm Hoàn Hảo', 'The Perfect Suspect', 'https://phimimg.com/upload/vod/20250619-1/a42a7b81ddf4848f03cba00d397933c6.jpg', 'https://phimimg.com/upload/vod/20250619-1/5c82f61ffd4e021e8a3091fdd482c507.jpg', '<p>Bộ phim được chuyển thể từ tiểu thuyết trinh thám xã hội mới &quot;Hoàn Mỹ Nghi Phạm&quot; của tác giả Trần Nghiên Nhất, bắt đầu từ một vụ án tưởng chừng hoàn hảo, từng bước hé lộ sự &quot;bệnh lý&quot; trong bản chất con người ẩn sau vẻ bề ngoài. Xen lẫn với những sự kiện liên quan đến trẻ em, câu chuyện phản chiếu muôn mặt của nhân sinh.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ou Hao","avatar":""},{"name":"Wang Herun","avatar":""},{"name":"Cheng Taishen","avatar":""},{"name":"Wang Ting","avatar":""},{"name":"Zhang Fengyi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["完美嫌疑人","완미적구속: 완벽한 속죄","The Perfect Suspect","完美的救赎"]', 1784690324153);
