INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-xuyen-nhap-mong', 'Thanh Xuyên Nhập Mộng', 'Qingchuan''s Veil Of Vengeance', 'https://phimimg.com/upload/vod/20250616-1/fb886c236ac7e383b12450fbe4f44cfc.jpg', 'https://phimimg.com/upload/vod/20250616-1/0edf62b767a496e8e95a98ceca1396ef.jpg', '<p>Năm Chương Hòa thứ 10, trong một cơ duyên tình cờ, Hạ Kỳ Quang được cha là Cảnh vương sắp xếp cho bái sư học nghệ với người được mệnh danh là “thiên hạ đệ nhất danh sư” Mạc Vong. Thế tử chẳng mấy coi trọng danh xưng ấy, nhưng lại luôn ngưỡng mộ nữ tướng quân bảo vệ giang sơn Mặc Thanh Xuyên. Thế tử không biết, Mạc Vong chính là Thanh Xuyên. Trên hành trình đồng hành, hai sư đồ dần trở thành chốn cứu rỗi cho nhau, bảo vệ lẫn nhau, tập hợp lại Mặc gia quân, mở ra con đường lấy lại danh dự cho những anh hùng.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Quách Hiểu Đình","avatar":""},{"name":"Châu Lịch Kiệt","avatar":""},{"name":"Dương Phúc Vũ","avatar":""},{"name":"Viên Minh Trạch","avatar":""},{"name":"Triệu Sùng Việt","avatar":""},{"name":"Hung Dị Phàm","avatar":""},{"name":"Viên Tường Nhân","avatar":""},{"name":"Điền Miêu","avatar":""},{"name":"Lưu Vệ Tăng","avatar":""},{"name":"An Tuấn Kỳ","avatar":""},{"name":"Tạ Kính Chi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Qing Chuan Ru Meng","青川","青川入梦"]', 1784690324153);
