INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thanh-xuyen-nhap-mong', 'Thanh Xuyên Nhập Mộng', 'Qingchuan''s Veil Of Vengeance', 'thanh xuyên nhập mộng qingchuan''s veil of vengeance quách hiểu đình châu lịch kiệt dương phúc vũ viên minh trạch triệu sùng việt hung dị phàm viên tường nhân điền miêu lưu vệ tăng an tuấn kỳ tạ kính chi qing chuan ru meng 青川 青川入梦', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-con-muc-phan-3', 'Trò chơi con mực (Phần 3)', 'Squid Game (Season 3)', 'https://phimimg.com/upload/vod/20250627-1/d5d6027b96a3145442ae28753db855d5.jpg', 'https://phimimg.com/upload/vod/20250627-1/95df698d6732124181f47c85b5f1a475.jpg', '<p>Tiếp nối ngay sau phần 2 với cú twist đẫm máu: Gi-hun (Seong Gi-hun) – Player 456 – trở lại trong tình trạng bị đẩy trở lại trò chơi sau khi cuộc nổi dậy thất bại, cùng sự phản bội từ The Front Man (Hwang In-ho) và cái chết đáng tiếc của bạn thân Jung‑bae Mục tiêu của Gi-hun: Anh chiến đấu không chỉ để sống sót, mà là để chấm dứt hoàn toàn tổ chức trò chơi này. Mâu thuẫn chính sẽ là cuộc đối đầu căng thẳng giữa Gi‑hun và Front Man Chủ đề mới: Phần này tập trung sâu vào nội tâm của các nhân vật, đặt con người vào trạng thái cận đáy của sự bức thiết – những trò chơi mới mang tính tâm lý cực đoan, liên quan đến nỗi sợ độ cao và hành động bóc trần bản chất tăm tối của con người .</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 9, 2025, 'Vietsub + Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Jung-jae","avatar":""},{"name":"Lee Byung-hun","avatar":""},{"name":"Wi Ha-jun","avatar":""},{"name":"Yang Dong-geun","avatar":""},{"name":"Kang Ae-sim","avatar":""},{"name":"Yim Si-wan","avatar":""},{"name":"Jo Yu-ri","avatar":""},{"name":"Kang Ha-neul","avatar":""},{"name":"Park Gyu-young","avatar":""},{"name":"Park Sung-hoon","avatar":""},{"name":"Lee Jin-uk","avatar":""},{"name":"David Lee","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Squid Game","विद्रूप खेल","بازی مرکب","بازی ماهی مرکب","イカゲーム","Ojingeo Geim","Ojingeo Game","오징어 게임","오징어게임","Ojing-eo geim","Kalamar Oyunu","魷魚遊戲","Гра у кальмара"]', 1784690324153);
