INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngon-hai-dang-ben-kia-bo', 'Ngọn Hải Đăng Bên Kia Bờ', 'Fancy Land', 'https://phimimg.com/upload/vod/20250617-1/d26d2ce3fdb63ec2a1905009342dbaab.jpg', 'https://phimimg.com/upload/vod/20250617-1/6bcbf2c1576516a1728c8b1e2a5e9312.jpg', '<p>Hai vụ án mạng kỳ lạ liên tiếp xảy ra tại một thị trấn nhỏ ven biển, phá vỡ cuộc sống yên bình của người mẹ đơn thân Lý Tú Lan và con gái Lý Nghiên khi cảnh sát ập đến...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Từ Mộng Khiết","avatar":""},{"name":"Tôn Mỹ Lâm","avatar":""},{"name":"Trương Lộ","avatar":""},{"name":"Lan Hải Mông","avatar":""},{"name":"Trương Tùng","avatar":""},{"name":"Lý Thần Đào","avatar":""},{"name":"Châu Khải","avatar":""},{"name":"Chu Thần Hạo","avatar":""},{"name":"Trần Sơn","avatar":""},{"name":"Tôn Thái Luân","avatar":""},{"name":"Tôn Phong Nham","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bi An Deng Ta","The Lighthouse on the Other Shore","彼岸灯塔"]', 1784690324153);
