INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giu-kin-nhe-makina-san', 'Giữ Kín Nhé!  Makina San!!', 'Kakushite! Makina San!! / Makina-san''s a Love Bot?!', 'https://phimimg.com/upload/vod/20250429-1/936b96ef4d60ab27bf9d4691f34c6f2a.jpg', 'https://phimimg.com/upload/vod/20250429-1/2a0f3d59a0f7c0d7fb6316754814b9ab.jpg', '<p>Eita, một otaku mê cơ khí, phát hiện ra rằng Makina, thần tượng của trường mà cậu ấy thầm thích, thực ra lại là một robot được chế tạo cho mục đích tình dục. Giờ đây, cậu ấy phải vừa xoay xở trước những hành động tấn công táo bạo của cô ấy, vừa phải giúp cô ấy giữ bí mật thân phận của mình trong câu chuyện hài lãng mạn đầy hỗn loạn này.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Tomoyo Takayanagi","avatar":""},{"name":"You Taichi","avatar":""},{"name":"Yuuki Kuwahara","avatar":""},{"name":"Hina Natsume","avatar":""},{"name":"Eriko Matsui","avatar":""},{"name":"Ryoko Shintani","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Esconda-se! Makina-san!!","快藏起来 玛琪娜同学","快藏好！玛琪娜同学!!","Makina-san''s a Love Bot?!","Copriti, Makina!","Kakushite! Makina-san!!","マキナさん","Makinasan","Прячься, Макина!","คาคุชิเตะ! มาคินะซัง!!","快藏好！瑪奇娜同學！！","快藏好！！瑪琪娜同學！！","Hide it! Makina!","Hide! Makina-san!!","かくして！ マキナさん!!"]', 1784690324153);
