INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('giu-kin-nhe-makina-san', 'Giữ Kín Nhé!  Makina San!!', 'Kakushite! Makina San!! / Makina-san''s a Love Bot?!', 'giữ kín nhé!  makina san!! kakushite! makina san!! / makina-san''s a love bot?! tomoyo takayanagi you taichi yuuki kuwahara hina natsume eriko matsui ryoko shintani esconda-se! makina-san!! 快藏起来 玛琪娜同学 快藏好！玛琪娜同学!! makina-san''s a love bot?! copriti, makina! kakushite! makina-san!! マキナさん makinasan прячься, макина! คาคุชิเตะ! มาคินะซัง!! 快藏好！瑪奇娜同學！！ 快藏好！！瑪琪娜同學！！ hide it! makina! hide! makina-san!! かくして！ マキナさん!!', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('compass20-he-thong-phan-tich-thong-tin-chien-dau', '#COMPASS2.0 HỆ THỐNG PHÂN TÍCH THÔNG TIN CHIẾN ĐẤU', '#COMPASS2.0 ANIMATION PROJECT / #Compass 2.0: Sentou Setsuri Kaiseki System', 'https://phimimg.com/upload/vod/20250416-1/37ae02285ad7ec9b379a37444fb682ca.jpg', 'https://phimimg.com/upload/vod/20250416-1/01cd08c4e75dcf2d7c6f11433afc503a.jpg', '<p>Trong &quot;Hệ Thống Phân Tích Thông Tin Chiến Đấu #COMPASS2.0&quot;, các anh hùng tập hợp cùng với cộng sự là con người trong một không gian như mơ. Các anh hùng phải liên tục chiến đấu để tạo ra đủ năng lượng nhằm duy trì hoạt động của hệ thống. Một anh hùng tên là 13 là một kẻ hay gây rối, từ chối tìm cộng sự cho mình. Khi 13 gần như bị loại khỏi hệ thống, một người chơi mới tên là Jin đã đồng ý hợp tác cùng cậu ấy. Liệu họ có thể mang lại hòa bình cho thế giới của #COMPASS2.0 không?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Daisuke Ono","avatar":""},{"name":"Sora Amamiya","avatar":""},{"name":"Soma Saito","avatar":""},{"name":"Sakura Tange","avatar":""},{"name":"Yoshitaka Yamaya","avatar":""},{"name":"Yasuhiro Mamiya","avatar":""},{"name":"Shiki Aoki","avatar":""},{"name":"Reina Kondo","avatar":""},{"name":"Tetsuya Kakihara","avatar":""},{"name":"Hiro Shimono","avatar":""},{"name":"Rikiya Koyama","avatar":""},{"name":"Marina Inoue","avatar":""},{"name":"Kazuhiro Yamaji","avatar":""},{"name":"Ayumu Murase","avatar":""},{"name":"Atsuko Tanaka","avatar":""},{"name":"Kokoa Amano","avatar":""},{"name":"Yu Shimamura","avatar":""},{"name":"Yoshitsu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["#COMPASS 2.0 - Sentō Setsuri Kaiseki System","#COMPASS 2.0 - Sentou Setsuri Kaiseki System","#Compass 2.0 Combat Providence Analysis System","#コンパス2.0 戦闘摂理解析システム"]', 1784690324153);
