INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-tinh-ban', 'Hành Trình Tình Bạn', 'Friendship', 'https://phimimg.com/upload/vod/20250627-1/495c94231065f1867114f0e89ffdec02.jpg', 'https://phimimg.com/upload/vod/20250627-1/ea140a523a31a3dcd08bba462cba60e6.jpg', '<p>Ông bố vùng ngoại ô Craig nhanh chóng bị cuốn hút bởi anh hàng xóm mới, Austin. Nhưng khi những nỗ lực ngây ngô để kết bạn của Craig ngày càng vượt quá giới hạn, cả hai rơi vào tình thế trớ trêu có thể phá vỡ cuộc sống vốn yên bình của họ.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tim Robinson","avatar":""},{"name":"Paul Rudd","avatar":""},{"name":"Kate Mara","avatar":""},{"name":"Jack Dylan Grazer","avatar":""},{"name":"Rick Worthy","avatar":""},{"name":"Whitmer Thomas","avatar":""},{"name":"Daniel London","avatar":""},{"name":"Eric Rahill","avatar":""},{"name":"Jacob Ming-Trent","avatar":""},{"name":"Billy Bryk","avatar":""},{"name":"Meredith Garretson","avatar":""},{"name":"Ari Dalbert","avatar":""},{"name":"Josh Segarra","avatar":""},{"name":"Raphael Sbarge","avatar":""},{"name":"Omar Torres","avatar":""},{"name":"Jason Veasey","avatar":""},{"name":"Jon Glaser","avatar":""},{"name":"Carmen Chri","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Between Friends","Dostluq","Miqësia","Amistad Toxica","Friendship"]', 1784690324153);
