INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-giet-toi-la-chong-toi', 'Kẻ Giết Tôi Là Chồng Tôi', 'My Husband Murdered Me', 'https://phimimg.com/upload/vod/20250626-1/acfe5e55b906460b9bc6c1fe37609215.jpg', 'https://phimimg.com/upload/vod/20250626-1/d9a561807f6a38a529d8622ce736dea8.jpg', '<p>Một người phụ nữ tên Hyangmi, mất cả gia đình vì chồng ngoại tình với tình nhân, và Jaeha, người đang tìm cách trả thù cho cha mình, cùng hợp tác để thực hiện kế hoạch trả thù. Tuy nhiên, trong câu chuyện tình yêu giữa họ, cả hai buộc phải đối diện với một sự thật tàn khốc.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 37, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324153);
