INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ke-giet-toi-la-chong-toi', 'Kẻ Giết Tôi Là Chồng Tôi', 'My Husband Murdered Me', 'kẻ giết tôi là chồng tôi my husband murdered me  ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-gio-va-doi-em', 'Đợi Gió Và Đợi Em', 'Waiting For You', 'https://phimimg.com/upload/vod/20250624-1/79fa72bd8efc43bc858370905d169b62.jpg', 'https://phimimg.com/upload/vod/20250624-1/3f126029d56a64332a35b5c23122597c.jpg', '<p>Sau khi tốt nghiệp, Thẩm Chi Ý trở về quê hương làng Lĩnh Nam để mở một nhà nghỉ. Với sự giúp đỡ của những người bạn thân là Mạnh Kiều Kiều và Mã Dật, công việc kinh doanh dần dần khởi sắc. Nhà thiên văn học Giang Trừng, sau khi tính toán kỹ lưỡng, dự đoán rằng một thiên thạch nhỏ sắp rơi xuống làng Lĩnh Nam. Trong hành trình cảnh báo và bảo vệ dân làng, anh tình cờ quen biết với Mạnh Kiều Kiều, Lâm Ngạn Cẩm, Giang Sở Dương cùng những người trẻ tuổi khác. Lúc đó, cuộc sống và công việc của họ đều đang rơi vào bế tắc. Họ cảm thấy mệt mỏi với sự cạnh tranh khốc liệt nơi thành thị và các mối quan hệ xã hội phức tạp. Ban đầu, những người bạn trong nhà nghỉ thường xuyên xảy ra mâu thuẫn, nhưng trong quá trình chung sống, họ dần thấu hiểu những câu chuyện và hoàn cảnh của nhau, trở thành bạn thân tri kỷ. Trong khung cảnh yên bình, xa rời phố xá ồn ào, họ cùng nhau đồng hành và trưởng thành. Mỗi người đều học cách nhìn nhận lại quá khứ, giúp đỡ lẫn nhau, tìm lại tinh thần trong gió để có thể bắt đầu lại. Mọi người cùng tụ hội tại làng Lĩnh Nam, vượt qua khó khăn, dần hoà hợp và nỗ lực hết mình để xây dựng nhà nghỉ thành công. Không chỉ vậy, họ còn góp phần thúc đẩy sự phát triển mạnh mẽ của ngành du lịch tại quê hương.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Roada Xu","avatar":""},{"name":"Guo Jianan","avatar":""},{"name":"Zhang Bingqian","avatar":""},{"name":"Huo Xingyu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Deng Feng Ye Deng Ni","Wait Breeze Also Wait You","等风也等你"]', 1784690324153);
