INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-nua-su-that-2025', 'Một Nửa Sự Thật', 'Half Truth', 'https://phimimg.com/upload/vod/20250626-1/6f2aa07811718664cc6a600970529a28.jpg', 'https://phimimg.com/upload/vod/20250626-1/ec0d62e987bbd9e7dcd3717a5641124a.jpg', '<p>Đội trưởng đội cảnh sát hình sự La Phi nhận được một vụ án bắt cóc tống tiền. Theo lời người báo án là Mạnh Thắng Nam, chồng cô là Lý Tuấn Tùng do vướng vào một sự cố y tế nên đã buộc phải từ chức. Một tuần trước, anh ta rời khỏi nhà và mất liên lạc. Gần đây, kẻ bắt cóc đã gửi một ngón tay bị chặt làm bằng chứng, yêu cầu tiền chuộc một triệu tệ, nếu không sẽ giết con tin. Cuộc đối đầu “mèo vờn chuột” bắt đầu, nhưng rất nhanh chóng bị cắt ngang — đầu của Lý Tuấn Tùng bị vứt giữa khu phố sầm uất. Cùng với cái đầu là một mảnh giấy — là lời cảnh báo hay là đe dọa? La Phi cùng người học trò Mục Kiếm Vân bắt tay điều tra, lần theo từng lớp màn sương mờ để tìm ra sự thật về cái chết của Lý Tuấn Tùng. Khi những ẩn tình phía sau vụ án dần hiện rõ, những con người và sự việc tưởng chừng không liên quan lại dần đan xen vào nhau, tạo nên một mạng lưới dày đặc và chặt chẽ…</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Bo","avatar":""},{"name":"Cao Xiwen","avatar":""},{"name":"Ji Chen","avatar":""},{"name":"Wang Ning","avatar":""},{"name":"Li Sibo","avatar":""},{"name":"Yu Hongzhou","avatar":""},{"name":"Liu Chuang","avatar":""},{"name":"Dong Qi","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["暗黑者外传:惩罚","Zhen Xiang Ban Bai","The Truth is Half White","真相半白"]', 1784690324153);
