INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mot-nua-su-that-2025', 'Một Nửa Sự Thật', 'Half Truth', 'một nửa sự thật half truth zhang bo cao xiwen ji chen wang ning li sibo yu hongzhou liu chuang dong qi 暗黑者外传:惩罚 zhen xiang ban bai the truth is half white 真相半白', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dap-tuyet-tam-hung', 'Đạp Tuyết Tầm Hùng', 'The Most Eastern Love', 'https://phimimg.com/upload/vod/20250626-1/3583cf9ebecf59778e4fb187a9c5ad22.jpg', 'https://phimimg.com/upload/vod/20250626-1/6e34b550912f9bdcf6f0e0081b2e70e9.jpg', '<p>Bộ phim lấy cảm hứng từ câu chuyện &quot;Cam Nam - Dâu Bắc&quot;, kể về nhiếp ảnh gia động vật hoang dã ở Quảng Tây tên là Sa Đường, khi đến thành phố Phú Viễn thì tình cờ quen biết cô gái dân tộc Hắc Trĩ tên Lâm Mạn Duệ qua một cuộc “không đánh không quen”, từ đó trở thành cặp oan gia hài hước, vừa đấu khẩu vừa gây rối cho nhau. Lâm Mạn Duệ muốn thoát khỏi rắc rối của bản thân nên buộc phải &quot;thuê&quot; Sa Đường làm bạn trai hợp đồng. Trong khi đó, Sa Đường muốn quay được hình ảnh gấu trắng bạch tạng quý hiếm ở vùng Đông Cực cũng phải nhờ đến sự giúp đỡ của Lâm Mạn Duệ. Vì vậy, cả hai không còn cách nào khác ngoài việc cùng nhau bắt đầu hành trình tìm gấu. Trên hành trình đó, Lâm Mạn Duệ dần bị sự kiên trì của Sa Đường làm cảm động, và hai trái tim trẻ bắt đầu xích lại gần nhau. Đồng thời, cả hai cũng nhận được những lời chúc tốt đẹp từ thành phố Phú Viễn. Một tình yêu thắp sáng cả thành phố, một thành phố chứng kiến một mối tình. Một người từ phương Nam, một người từ phương Bắc, họ dùng câu chuyện đẹp như cổ tích để tái hiện lại sự lãng mạn nơi cực Đông Phú Viễn. Khi họ ôm chặt nhau trong quảng trường Đông Cực, cuối cùng cũng hiểu rằng: Chỉ cần trong tim có thơ, thì nơi bên cạnh chính là viễn phương.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xu Yizhen","avatar":""},{"name":"Han Donglin","avatar":""},{"name":"Mao Kuanren","avatar":""},{"name":"Lv Yihao","avatar":""},{"name":"Shi Tiangeng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ta Xue Xun Xiong","踏雪寻熊"]', 1784690324153);
