INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loan-the-giang-ho-than-binh-quyet', 'Loạn Thế Giang Hồ: Thần Binh Quyết', 'Chaotic Jianghu: Divine Weapons Rivalry', 'https://phimimg.com/upload/vod/20250626-1/b564ec4076d23bcd034a51c9138e21a3.jpg', 'https://phimimg.com/upload/vod/20250626-1/e6c1a71fdc23eed8798a6f25f989f6a5.jpg', '<p>Giang hồ lại dậy sóng khi có tin đồn rằng trong Tứ đại thần binh, thanh vũ khí thần bí nhất Bỉ Ngạn Hoa một lần nữa xuất hiện tại Trung Nguyên. Tin tức này tựa cơn gió xuân thổi qua mặt nước tĩnh lặng, khơi dậy từng đợt sóng ngầm, khiến anh hùng khắp nơi rục rịch hành động, đua nhau lên đường truy tìm thần binh với tham vọng xưng bá võ lâm. Nào ngờ, ẩn sau cuộc tranh đoạt tưởng chừng chỉ vì vũ khí là một bí mật kinh thiên động địa, một âm mưu được giấu kín bấy lâu, kéo theo vô số cuộc tranh đấu đẫm máu trong chốn giang hồ.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Y Mặc","avatar":""},{"name":"Lý Cảnh Ngạch","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["乱世江湖：神兵决"]', 1784690324153);
