INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('marvels-hitmonkey-phan-2', 'Marvel''s Hit-Monkey (Phần 2)', 'Marvel''s Hit-Monkey (Season 2)', 'marvel''s hit-monkey (phần 2) marvel''s hit-monkey (season 2) fred tatasciore jason sudeikis olivia munn ally maki eric roberts leslie jones מארוול: היט מאנקי マーベル ヒット・モンキー 마블 히트 멍키 히트멍키 hit-monkey marvel''s hit-monkey', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gio-thang-bay-ngot-ngao', 'Gió Tháng Bảy Ngọt Ngào', 'Love Blossoms With The Wind', 'https://phimimg.com/upload/vod/20250618-1/b9fe6d5a8a06e241cfbe8c77db4f30a1.jpg', 'https://phimimg.com/upload/vod/20250618-1/f9849aa7ec262363b323d77bf22ee223.jpg', '<p>Tống Thất Nguyệt – một cô gái tràn đầy mơ ước – đã đến khu Huệ Sơn, Vô Tích, tiếp quản nhà nghỉ “Thất Nguyệt Tiểu Ốc” mà cô cùng bạn trai đồng sáng lập. Nào ngờ, cô vô tình bắt gặp bạn trai đang phản bội mình. Sau nỗi đau, cô quyết tâm giành lại nhà nghỉ và bắt đầu lại từ đầu. Trong lúc khó khăn, cô tình cờ quen biết Tổng tài Cố Từ An – người không chỉ ra tay giúp đỡ, mà còn cùng cô hợp tác cải tạo nhà nghỉ và đổi tên thành “Tề Mộng Cư”. Trong quá trình cùng nhau giải quyết các khó khăn kinh doanh và tái hiện hương vị bánh đào hoa thuở ấu thơ, hai người dần nảy sinh tình cảm. Tuy nhiên, Cố Từ An lại giấu diệm thân phận thật của mình – Phó Tổng giám đốc tập đoàn Cố thị, đơn vị đang thực hiện dự án cải tạo thương mại trong khu vực và đe dọa sự tồn tại của “Tề Mộng Cư”. Khi sự thật phơi bày, Tống Thất Nguyệt cảm thấy bị phản bội sâu sắc. Cuối cùng, vì tình yêu, Cố Từ An quyết định đối đầu với gia tộc, toàn tâm toàn ý bảo vệ nhà nghỉ. Trong một đám cưới cảm động được tổ chức cho một cô bé mắc bệnh nan y, những hiểu lầm được hóa giải, cha của Cố Từ An cũng bị cảm động và công nhận giá trị văn hóa của nhà nghỉ. Tống Thất Nguyệt không những bảo vệ được “Tề Mộng Cư” – ước mơ của mình, mà còn có được một tình yêu chân thành với Cố Từ An, tìm thấy một chốn bình yên ngọt ngào nơi sông nước Giang Nam.</p>', 'Tập 18', 18, 'series', 'ongoing', 14, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cheng Guo","avatar":""},{"name":"Bao Han","avatar":""},{"name":"Deng Xizi","avatar":""},{"name":"Li Minglei","avatar":""},{"name":"Ju Ping","avatar":""},{"name":"Li Zhexu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Qi Yue De Feng Shi Tian De","The Wind in July Is Sweet","七月的风是甜的"]', 1784690324153);
