INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('one-nguoi-hung-trung-hoc', 'ONE: Người Hùng Trung Học', 'ONE: High School Heroes', 'https://phimimg.com/upload/vod/20250531-1/5a2a0032432a9608408990643d0a5926.jpg', 'https://phimimg.com/upload/vod/20250531-1/691fe453ec31dbf35bd1d94e08ac68ec.jpg', '<p>Dựa trên webtoon cùng tên, kể về câu chuyện của một học sinh gương mẫu từng dành toàn bộ sự chú ý của mình cho việc học nhưng bị vướng vào bạo lực gia đình và bắt nạt ở trường, buộc anh phải đưa ra quyết định mang tính thay đổi. One: High School Heroes kể về hành trình nhóm học sinh dũng cảm chống bạo lực học đường, kết hợp hành động mãn nhãn và drama sâu sắc, truyền tải thông điệp đoàn kết.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 19, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Jung-ha","avatar":""},{"name":"Kim Do-wan","avatar":""},{"name":"Kim Sang-ho","avatar":""},{"name":"Kim Joo-ryoung","avatar":""},{"name":"Lim Sung-kyun","avatar":""},{"name":"Yuk Jun-seo","avatar":""},{"name":"Yoo Hee-je","avatar":""},{"name":"Lim Hyun-tae","avatar":""},{"name":"Shin Jae-hwi","avatar":""},{"name":"Hong Min-gi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["원: 하이스쿨 히어로즈","원 하이스쿨 히어로즈","ONE: 하이스쿨 히어로즈"]', 1784690324153);
