INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('one-nguoi-hung-trung-hoc', 'ONE: Người Hùng Trung Học', 'ONE: High School Heroes', 'one: người hùng trung học one: high school heroes lee jung-ha kim do-wan kim sang-ho kim joo-ryoung lim sung-kyun yuk jun-seo yoo hee-je lim hyun-tae shin jae-hwi hong min-gi 원: 하이스쿨 히어로즈 원 하이스쿨 히어로즈 one: 하이스쿨 히어로즈', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-dua-tre-nha-shiunji', 'Những Đứa Trẻ Nhà Shiunji', 'The Shiunji Family Children', 'https://phimimg.com/upload/vod/20250416-1/fd4024d3f577e41df2065860a5db90da.jpg', 'https://phimimg.com/upload/vod/20250416-1/56724e0256e5aa99db6686c30726b2dd.jpg', '<p>Hai người con trai và năm người con gái của gia đình danh giá Shiunji &quot;tỏa sáng&quot; như những viên ngọc quý, mỗi người đều thông minh và xinh đẹp, trở thành tâm điểm chú ý của cả thị trấn. Người anh cả Arata luôn bị các cô em gái cá tính trêu chọc, nhưng anh luôn đặt gia đình lên trên hết. Tuy nhiên, khi cô em gái út tròn mười lăm tuổi, người cha tiết lộ một bí mật động trời, vốn đã được chôn giấu từ lâu. Sự thật về mối quan hệ anh chị em đảo lộn hoàn toàn thế giới của Arata và hé lộ những mối quan hệ vượt trên cả tình thân ruột thịt sau này.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuuichirou Umehara","avatar":""},{"name":"Chika Anzai","avatar":""},{"name":"Marika Kouno","avatar":""},{"name":"Rie Takahashi","avatar":""},{"name":"Hana Hishikawa","avatar":""},{"name":"Kana Ichinose","avatar":""},{"name":"Chiaki Kobayashi","avatar":""},{"name":"Masaki Terasoma","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["紫云寺家的兄弟姐妹","紫云寺家的孩子们","Shiunji-ke no Kodomotachi","Shiunji-ke no Kodomo-tachi","しうんじけのこどもたち","紫雲寺家","The Children of Shiunji Family","Shiunzi-ke no Kodomo-tachi","Shiunzi-ke no Kodomotachi","The Children ofShiunji Family","Shiunjike no Kodomotachi","Дети семьи Сиундзи","The Shiunji Siblings","The Children of the Shiunji Family","紫雲寺家の子供たち"]', 1784690324153);
