INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khach-san-apocalypse', 'Khách Sạn Apocalypse', 'Apocalypse Hotel', 'https://phimimg.com/upload/vod/20250416-1/dfe17014998a181f65db9f520aa8a2a3.jpg', 'https://phimimg.com/upload/vod/20250416-1/514f3ae0d67b030419fb149b78aa47b2.jpg', '<p>Nhiều năm đã trôi qua kể từ khi loài người biến mất khỏi Trái đất, nhưng khách sạn Galaxy Tower ở Ginza, Tokyo, vẫn tiếp tục hoạt động. Tại trung tâm nhân viên của nó là Yachiyo, một robot chủ khách sạn chuyên dụng, cùng với các robot nhân viên khác làm việc không mệt mỏi trong các bộ phận khác nhau. Cùng nhau, họ dành những gì cảm thấy như một sự vĩnh cửu duy trì khách sạn, mặc dù không có khách. Khi họ chờ đợi sự trở lại của chủ sở hữu của họ và ngày nhân loại xuất hiện trở lại. Bây giờ, một phép lạ nhỏ sắp thay đổi mọi thứ cho Yachiyo và các đồng nghiệp robot của cô.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Saho Shirasu","avatar":""},{"name":"Sumire Morohoshi","avatar":""},{"name":"Hiroki Touchi","avatar":""},{"name":"Shin-ichiro Miki","avatar":""},{"name":"Hiroyuki Kinoshita","avatar":""},{"name":"Cho","avatar":""},{"name":"Takako Honda","avatar":""},{"name":"Mutsumi Tamura","avatar":""},{"name":"Yoshiko Sakakibara","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["末日后酒店","启示录酒店","Apocalypse Hotel","末日後酒店","Khách Sạn Tận Thế","アポカリプスホテル"]', 1784690324153);
