INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-ban-be-be', 'Bạn Bạn Bè Bè', 'Friendly Rivalry', 'https://phimimg.com/upload/vod/20250209-1/8b352f3bdf7127e6e4cbb21ec089e605.jpg', 'https://phimimg.com/upload/vod/20250209-1/5e8b177251de0d57dc271e8b533f341c.jpg', '<p>Woo Seul Gi, một nữ sinh tỉnh lẻ, bất ngờ chuyển đến học ở ngôi trường trung học danh giá chỉ dành riêng cho những học sinh xuất sắc nhất nước. Ở trường mới, cô nhận được sự quan tâm đặc biệt của Yoo Je Yi, nữ sinh tài năng đến từ gia đình quyền thế và nổi tiếng nhất trường. Tuy nhiên, tình bạn tưởng chừng đẹp đẽ lúc ban đầu dần dần biến thành một cuộc cạnh tranh đầy nguy hiểm. Bạn Bạn Bè Bè khắc họa mặt tối của môi trường học đường, nơi mà áp lực thành tích và sự ganh đua có thể đẩy con người đến những hành động cực đoan.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 16, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Hye-ri","avatar":""},{"name":"Chung Su-bin","avatar":""},{"name":"Kang Hye-won","avatar":""},{"name":"Oh Woo-ri","avatar":""},{"name":"Kim Tae-hun","avatar":""},{"name":"Choi Young-jae","avatar":""},{"name":"Yoo Jung-Rae","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["善意的竞争","Seonuiui Gyeongjaeng","Friendly Rivalry","التنافس الودي","善意的競爭","Cạnh Tranh Thân Thiện","선의의 경쟁"]', 1784690324153);
