INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-menh', 'Tam Mệnh', 'What If', 'https://phimimg.com/upload/vod/20250619-1/917c11e5154f0da6e8bc6079c6363066.jpg', 'https://phimimg.com/upload/vod/20250619-1/a1724ee28dbfd96adce6ccc6b70a9cc2.jpg', '<p>Một người đàn ông sống ba số phận khác nhau do chính lựa chọn của mình tạo nên. Sinh non ở Hồng Kông những năm 1960, anh lớn lên với niềm đam mê truyện tranh. Một trò đùa nghịch ngợm ở trường đưa anh gặp một cô gái bí ẩn, nhưng một cánh diều đứt dây đã làm rung chuyển dòng thời gian, tách cuộc đời anh thành ba ngả rẽ khác biệt.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Ernesto de Sousa","avatar":""},{"name":"Power Chan","avatar":""},{"name":"Ng Wing-Sze","avatar":""},{"name":"Ashley Lam","avatar":""},{"name":"Chrissie Chau","avatar":""},{"name":"Ben Yuen","avatar":""},{"name":"Tony Wu","avatar":""},{"name":"Tsui Ho-Cheong","avatar":""},{"name":"Kevin Chu","avatar":""},{"name":"DeeGor Ho","avatar":""},{"name":"Johnny Hui","avatar":""},{"name":"German Cheung Man-Kit","avatar":""},{"name":"Alan Luk","avatar":""},{"name":"Tony Ho","avatar":""},{"name":"Aaron Chow","avatar":""},{"name":"Johnson Yuen Tak-Cheung","avatar":""},{"name":"Jay Fung","avatar":""},{"name":"Stanley Yau","avatar":""},{"name":"Emotion Cheung","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["What If","Three Destinies","Saam ming","三命"]', 1784690324153);
