INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-nguyet', 'Hoa Nguyệt', 'Bloom Once More', 'https://phimimg.com/upload/vod/20250619-1/e62a5256acedc0677b20ba3b8b28ee89.jpg', 'https://phimimg.com/upload/vod/20250619-1/ca42eb874f2159a75895696d6308a3dc.jpg', '<p>Năm Thiên Nguyên thứ tám, Nguyệt Thiên Tuyết bị gián điệp của nước Tịch Mộ là Lục Thiên Thiên và Lục Ly hãm hại, chết ở thành Lạc Nhật. Một năm sau khi Nguyệt Thiên Tuyết chết, Hoa Tinh Minh cũng không bảo vệ được Trường Bình Kinh, từ đó thiên hạ chịu cảnh sinh linh lầm than. Gia Cát Nhân Phong không đành lòng nhìn chúng sinh chịu kiếp nạn này nên đã dùng tuổi thọ của mình, lấy chuông Đông Hoàng làm vật kết nối đưa hai người trở về năm Thiên Nguyên thứ sáu. Từ đó, vận mệnh cứu vớt chúng sinh của Nguyệt Thiên Tuyết và Hoa Tinh Minh đã gắn chặt với nhau...</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hoàng Đình Đình","avatar":""},{"name":"Quyền Phái Luân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["花月若知何时圆","Hua Yue","花月"]', 1784690324153);
