INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-hanh-phap-y', 'Dạ Hành Pháp Y', 'Forensic After Dark', 'https://phimimg.com/upload/vod/20250621-1/83dc5a22978411ac013618b135f8b50c.jpg', 'https://phimimg.com/upload/vod/20250621-1/828a638882741040113a002c1468294f.jpg', '<p>Lưới trời lồng lộng, tuy thưa nhưng không lọt, không tội ác nào có thể thoát khỏi con mắt của công lý. Bộ phim theo chân pháp y Dương Minh và chuyên gia giám định dấu vết Diêu Gia Kiện, cùng nhau khám phá hàng loạt bí ẩn và phá giải nhiều vụ án phức tạp. Hai người vừa là đối thủ vừa là cộng sự, nhờ vào chuyên môn xuất sắc của mình, họ đã liên tục phá giải các vụ án khó nhằn.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ai Hongchen","avatar":""},{"name":"Wei Xiaoxuan","avatar":""},{"name":"Gao Kai","avatar":""},{"name":"Cui Shiyi","avatar":""},{"name":"Sun Yun","avatar":""},{"name":"He Yutong","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ye Xing Fa Yi","夜行法醫","Судебная экспертиза после наступления темноты","Ночной судебный медик","Night Walker","夜行法医"]', 1784690324153);
