INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dam-me-toc-do-2025', 'Đam Mê Tốc Độ', 'Motorheads', 'https://phimimg.com/upload/vod/20250620-1/c01a9cddebcbbe8525d6d93e5502a533.jpg', 'https://phimimg.com/upload/vod/20250620-1/aa7a273bbb58e84c3f9a1c8e9374cd41.jpg', '<p>Khi chuyển đến thị trấn Ironwood, anh em Caitlyn và Zac Torres nhanh chóng bị cuốn vào văn hóa xe độ đầy phấn khích, nơi những cuộc đua đường phố quyết định vị thế học đường. Mang theo bóng đen từ quá khứ của người cha, họ hợp sức với Curtis – chàng trai cô độc và Marcel – kẻ bị gạt ra bên lề, cùng nhau khôi phục lại chiếc xe huyền thoại, mở đầu cho hành trình chinh phục tốc độ và số phận.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 33, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ryan Phillippe","avatar":""},{"name":"Nathalie Kelley","avatar":""},{"name":"Michael Cimino","avatar":""},{"name":"Melissa Collazo","avatar":""},{"name":"Uriah Shelton","avatar":""},{"name":"Drake Rodger","avatar":""},{"name":"Nicolas Cantu","avatar":""},{"name":"Johnna Dias-Watson","avatar":""},{"name":"Mia Healey","avatar":""},{"name":"Josh MacQueen","avatar":""},{"name":"Matt Lanter","avatar":""},{"name":"Audrey Gerthoffer","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Thể Thao","slug":"the-thao","id":"591bbb2abfe03f5aa13c08f16dfb69a2"}]', '["Motorheads"]', 1784690324153);
