INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-phi-hong-hac-nha-mon', 'Hoàng Phi Hồng: Hắc Nha Môn', 'Huang Feihong The Black Yamen', 'https://phimimg.com/upload/vod/20250624-1/94cc199e1258ced97908b6ee50f0512e.jpg', 'https://phimimg.com/upload/vod/20250624-1/183f68802150a5ee8c1b2ebc969e067f.jpg', '<p>Cuối triều Thanh, thế lực ngoại quốc hoành hành, triều đình nhà Thanh ngày một suy yếu. Nha môn Quảng Châu cấu kết với phản loạn và người Tây dưới sự bảo kê của Tào công công, bán nước cầu vinh, vơ vét của cải phi pháp. Hoàng Phi Hồng, người luôn mang trong mình tấm lòng vì dân biết được sự đen tối của quan phủ, đã đứng ra đòi lại công lý cho dân, đại náo nha môn đen. Sau những trận chiến sống còn đầy khốc liệt, cuối cùng anh đã quét sạch thế lực ngoại bang, tiêu diệt phản loạn, trừng trị cái ác, bảo vệ quê hương và chính nghĩa!</p>', 'Full', 1, 'single', 'completed', 37, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Hạo Nan","avatar":""},{"name":"Quách Đình Đình","avatar":""},{"name":"Tào Húc","avatar":""},{"name":"Đỗ Khương","avatar":""},{"name":"Lý Thánh Hùng","avatar":""},{"name":"Trương Băng","avatar":""},{"name":"Hoàng Nhất Sơn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324153);
