INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('marshmallow', 'Marshmallow', 'Marshmallow', 'https://phimimg.com/upload/vod/20250623-1/f5ef845be88db2fb3f7c9e5e6b86680d.jpg', 'https://phimimg.com/upload/vod/20250623-1/63cebcb857ea0cac92f2babd4105b926.jpg', '<p>Tại một trại hè hẻo lánh, cậu bé Morgan 12 tuổi nhút nhát và sống nội tâm bất ngờ rơi vào cơn ác mộng giữa ban ngày khi một truyền thuyết lửa trại tưởng chừng chỉ là chuyện kể lại trở thành sự thật. Khi một nhân vật bí ẩn xuất hiện tại trại, Morgan cùng những người bạn mới quen phải bước vào một hành trình nguy hiểm để khám phá sự thật đen tối đang bị chôn giấu phía sau vẻ ngoài yên bình của trại hè.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Corbin Bernsen","avatar":""},{"name":"Giorgia Whigham","avatar":""},{"name":"Alysia Reiner","avatar":""},{"name":"Pierson Fodé","avatar":""},{"name":"Miya Cech","avatar":""},{"name":"Paul Soter","avatar":""},{"name":"Kue Lawrence","avatar":""},{"name":"Amanda Clayton","avatar":""},{"name":"Kai Cech","avatar":""},{"name":"Jordyn Raya James","avatar":""},{"name":"Max Malas","avatar":""},{"name":"Maxwell Whittington-Cooper","avatar":""},{"name":"Samantha Neyland","avatar":""},{"name":"Sutton Johnston","avatar":""},{"name":"Geoffrey James","avatar":""},{"name":"Winston Vengapally","avatar":""},{"name":"D","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Marshmallow"]', 1784690324153);
