INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('frozen-the-hit-broadway-musical', 'Frozen: The Hit Broadway Musical', 'Frozen: The Hit Broadway Musical', 'https://phimimg.com/upload/vod/20250623-1/2a603c537ca29e5769ab566817ffea94.jpg', 'https://phimimg.com/upload/vod/20250623-1/0165a7e6e2d1ec41f13fdb6e058bfa45.jpg', '<p>Công chúa trẻ Anna của vương quốc Arendelle mơ ước tìm được tình yêu đích thực trong ngày lễ đăng quang của chị gái mình, Elsa. Số phận đưa cô vào một hành trình nguy hiểm nhằm chấm dứt mùa đông vĩnh cửu đang bao trùm vương quốc. Đồng hành cùng cô là chàng trai giao băng Kristoff, chú tuần lộc Sven và người tuyết Olaf. Trên chuyến phiêu lưu ấy, Anna sẽ khám phá ý nghĩa thực sự của tình bạn, lòng dũng cảm, gia đình và tình yêu đích thực.</p>', 'Full', 1, 'single', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Laura Dawkes","avatar":""},{"name":"Samantha Barks","avatar":""},{"name":"Jammy Kasongo","avatar":""},{"name":"Craig Gallivan","avatar":""},{"name":"Oliver Ormson","avatar":""},{"name":"Richard Frame","avatar":""},{"name":"Ashley Birchall","avatar":""},{"name":"Mikayla Jade","avatar":""},{"name":"Justin-Lee Jones","avatar":""},{"name":"Dominic Adam Griffin","avatar":""},{"name":"Ben Irish","avatar":""},{"name":"Oliver Brenin","avatar":""},{"name":"George Hinson","avatar":""},{"name":"Rhianne Alleyn","avatar":""},{"name":"Jemal Felix","avatar":""},{"name":"Ashley J. Daniels","avatar":""},{"name":"Lizz","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Disney''s Frozen: The Hit Broadway Musical","冰雪奇缘：音乐剧","Frozen: 