INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('alma-va-con-soi', 'Alma Và Con Sói', 'Alma & The Wolf', 'https://phimimg.com/upload/vod/20250623-1/28d2add1f2646a63d9c715a676a4fcac.jpg', 'https://phimimg.com/upload/vod/20250623-1/abaa038cb1dd099f282a0a90d93c2dc2.jpg', '<p>Bộ phim này kể về một thị trấn nhỏ tên Spiral Creek rơi vào trạng thái hoảng loạn sau một cuộc tấn công dã man của một sinh vật bí ẩn. Phó cảnh sát trưởng Ren Accord bắt đầu điều tra và dấn sâu vào bí ẩn này, nhưng khi con trai anh đột ngột biến mất, mọi thứ trở nên kỳ quái và ranh giới giữa thực tại và ảo giác bắt đầu sụp đổ.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ethan Embry","avatar":""},{"name":"Li Jun Li","avatar":""},{"name":"Mather Zickel","avatar":""},{"name":"Jeremie Harris","avatar":""},{"name":"Alexandra Doke","avatar":""},{"name":"Kevin Allison","avatar":""},{"name":"Lukas Jann","avatar":""},{"name":"Dana Millican","avatar":""},{"name":"Beth Malone","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Alma and the Wolf","Alma und der Wolf","Alma & the Wolf"]', 1784690324153);
