INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-nu-than-khi-dot-gia-nhap-ky-si-doan', 'Thánh Nữ Thần Khỉ Đột Gia Nhập Kỵ Sĩ Đoàn', 'The Gorilla God''s Go-To Girl', 'https://phimimg.com/upload/vod/20250414-1/b5d2833baf0c266a6849679638100697.jpg', 'https://phimimg.com/upload/vod/20250414-1/ed70e8255d6773b69291bf3a80250d05.jpg', '<p>Trong một thế giới kỳ lạ, Sophia Leeler, con gái của vị bá tước nhút nhát bất ngờ nhận được phước lành từ Thần Khỉ Đột, vốn nổi tiếng với sức mạnh vô địch. Hơn thế nữa, cô còn được chọn làm Thánh Nữ, nhận nhiệm vụ gia nhập đoàn kỵ sĩ để bảo vệ vương quốc. Dù khao khát cuộc sống yên bình, nhưng sức mạnh phi thường của cô đã thu hút sự chú ý của các Hiệp sĩ Hoàng gia và họ quyết định chiêu mộ cô. Cuộc sống của một Thánh Nữ không hề dễ dàng như Sophia tưởng tượng, nhất là khi thần bảo hộ của cô lại là một chú khỉ đột cơ bắp với những sở thích và hành động khó đoán.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kanna Nakamura","avatar":""},{"name":"Takeo Otsuka","avatar":""},{"name":"Reiji Kawashima","avatar":""},{"name":"Takuma Nagatsuka","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Gorilla no Kami Kara Kago Sareta Reijō wa Ōritsu Kishidan de Kawaiigareru","Gorilla no Kami kara Kago sareta Reijou wa Ouritsu Kishidan de Kawaigarareru","Gorilla no Kami","Пані, благословенна Богом горили, улюблениця лицарського ордену","The Young Noblewoman Blessed by the Gorilla God Is Spoiled by the Royal Knights","The young lady, who was blessedby the Gorilla God, is adored in the Royal Knight Order","The Lady Blessed by the Gorilla God Is Adored by the Royal Knights","ゴリラの神から加護された令嬢は王立騎士団で可愛がられる"]', 1784690324153);
