INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-von-vo-danh', 'Tôi Vốn Vô Danh', 'I''m Nobody', 'https://phimimg.com/upload/vod/20250613-1/dfc65c51924847cb30b3025278eed357.jpg', 'https://phimimg.com/upload/vod/20250613-1/2085efcf36846b00115e8fc0b06d4b48.jpg', '<p>Diệp Vô Danh, truyền nhân chính tông của Bát Tiên Quyền, trên đường xuống núi tu luyện thì gặp tai nạn xe bất ngờ dẫn đến mất trí nhớ. Ba năm sau, Diệp Vô Danh trở thành tài xế lái xe hộ, tình cờ gặp nữ minh tinh đình đám Tống Y Nhiên và trở thành vệ sĩ riêng kiêm tài xế cho cô. Cả hai cùng nhau chống lại thế lực ngầm đầy quyền lực phía sau, đồng thời từng bước vén màn sự thật năm xưa.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tiêu Vũ","avatar":""},{"name":"Hàn Đông","avatar":""},{"name":"Vương Nhất Châu","avatar":""},{"name":"Phùng Nhược Hàng","avatar":""},{"name":"Bành Ất Hàng","avatar":""},{"name":"Trương Sa Sa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wo Ben Wu Ming","我本无名"]', 1784690324153);
