INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ta-la-quan-chu-ta-ac-cua-quoc-gia-o-giua-muon-vi-sao', 'Ta Là Quân Chủ Tà Ác Của Quốc Gia Ở Giữa Muôn Vì Sao', 'I''m The Evil Lord Of An Intergalactic Empire', 'https://phimimg.com/upload/vod/20250411-1/171863a98466894a2f067a17ae39bb25.jpg', 'https://phimimg.com/upload/vod/20250411-1/4da86307ef9145ae7dd7985ee7227bdd.jpg', '<p>Liam là một người chuyển sinh vào gia tộc bá tước cai quản một hành tinh nơi biên cảnh của Đế quốc thiên hà Algrand và đã trở thành gia chủ từ khi còn nhỏ. Vì phẫn uất với kiếp trước sống lương thiện nhưng bị chà đạp, Liam đã hạ quyết tâm kiếp này sẽ làm một quân chủ tà ác để chà đạp kẻ khác! &nbsp;Đây là một thế giới khoa học viễn tưởng nên Liam muốn được lái rô-bốt! Cậu thậm chí muốn học kiếm thuật mạnh nhất để tung hoành ngang dọc! Muốn xây dựng hậu cung và đắm chìm trong tửu sắc!

Tuy nhiên, dù những việc làm của Liam có chủ đích là &quot;&quot;trở thành quân chủ tà ác&quot;&quot; nhưng vì nhiều lý do, người người lại cảm ơn cậu và danh tiếng cứ vậy tăng lên...

Lấy vũ đài là quốc gia ở giữa muôn vì sao, câu chuyện sai lệch về sự quản lý lãnh thổ ở quy mô thiên hà sẽ bắt đầu!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Natsuki Hanae","avatar":""},{"name":"Reina Ueda","avatar":""},{"name":"Takehito Koyasu","avatar":""},{"name":"Mikako Komatsu","avatar":""},{"name":"Ayana Taketatsu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["我是星际国家的恶德领主","Ore.wa.Seikan.Kokka.no.Akutoku.Ryoushu","Je suis le méchant seigneur d''un empire intergalactique!","Ore wa Seikan Kokka no Akutoku Ryoushu!","I''m the Heroic Knight of an Intergalactic Empire!","I am the Villainous Lord of the Interstellar Nation","Ta Là Quân Chủ Tà Ác Của Quốc Gia Ở Giữa Muôn Vì Sao!","俺は星間国家の悪徳領主！"]', 1784690324153);
