INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bat-niem', 'Bất Niệm', 'Falling for Divinity', 'bất niệm falling for divinity zhang chuhan hu bowen lu xi ye yi arthur su bu nian 불념 : 부러진 인연 不念', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diet-slime-suot-300-nam-toi-level-max-luc-nao-chang-hay-phan-2', 'Diệt Slime Suốt 300 Năm, Tôi Level Max Lúc Nào Chẳng Hay (Phần 2)', 'I''ve Been Killing Slimes For 300 Years And Maxed Out My Level (Season 2)', 'https://phimimg.com/upload/vod/20250410-1/46e4b13763445937844635b8e0be8577.jpg', 'https://phimimg.com/upload/vod/20250410-1/164e6e40406d1e732b86b7c56ceeabdb.jpg', '<p>Aizawa Azusa là một kẻ “cuồng công việc”, không yêu đương, không bạn bè, không niềm vui và sở thích, cô cống hiến cuộc đời mình cho công việc. Và kết quả là Azusa chết vì làm việc quá sức. Nhờ phép màu, cô được tái sinh trong dáng hình của một phù thủy 17 tuổi trường sinh bất lão. Quyết tâm sống thật khác kiếp trước, Azusa nhàn nhã diệt slime suốt 300 năm và đã vô tình đạt max level. Sức mạnh đi đôi với những phiêu lưu mạo hiểm mới mà Azusa chưa từng đối mặt trong đời. Nhưng cũng nhờ đó mà cô có được niềm vui, có bạn vè và gia đình mới…</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Aoi Yuki","avatar":""},{"name":"Kaede Hondo","avatar":""},{"name":"Sayaka Senbongi","avatar":""},{"name":"Minami Tanaka","avatar":""},{"name":"Sayaka Harada","avatar":""},{"name":"Manami Numakura","avatar":""},{"name":"Riho Sugiyama","avatar":""},{"name":"Azumi Waki","avatar":""},{"name":"Yukari Tamura","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Slime Taoshite 300-nen","打了三百年的史莱姆，不知不觉就练到了满等","持续狩猎史莱姆三百年，不知不觉就练到LV MAX","打了三百年的史莱姆，不知不觉就练到了满级","打了300年的史莱姆，不知不觉就练到了满级 ～其二～","Slime300","La Sorcière invincible tueuse de Slime depuis 300 ans","Tanpa Sadar Levelku Mentok Setelah Membasmi Slime Selama 300 Tahun","Slime Taoshite 300-nen, Shiranai Uchi ni Level Max ni Nattemashita","Slime Taoshite 300","Slime Taoshite 300Nen Shiranai Uchi Ni Level Max Ni Nattemashita Sono Ni","슬라임을 잡으면서 300년, 모르는 사이에 레벨MAX가 되었습니다","Я 300 лет убивала слизь и прокачалась на максимум","Убивая слизней триста лет, сама того не заметив, я достигла максимального уровня","Убивая слизней 300 лет, сама того не заметив, я достигла максимального уровня","Diệt Slime Suốt 300 Năm, Tôi Level MAX Lúc Nào Chẳng Hay","スライム倒して300年、知らないうちにレベルMAXになってました"]', 1784690324153);
