INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('diet-slime-suot-300-nam-toi-level-max-luc-nao-chang-hay-phan-2', 'Diệt Slime Suốt 300 Năm, Tôi Level Max Lúc Nào Chẳng Hay (Phần 2)', 'I''ve Been Killing Slimes For 300 Years And Maxed Out My Level (Season 2)', 'diệt slime suốt 300 năm, tôi level max lúc nào chẳng hay (phần 2) i''ve been killing slimes for 300 years and maxed out my level (season 2) aoi yuki kaede hondo sayaka senbongi minami tanaka sayaka harada manami numakura riho sugiyama azumi waki yukari tamura slime taoshite 300-nen 打了三百年的史莱姆，不知不觉就练到了满等 持续狩猎史莱姆三百年，不知不觉就练到lv max 打了三百年的史莱姆，不知不觉就练到了满级 打了300年的史莱姆，不知不觉就练到了满级 ～其二～ slime300 la sorcière invincible tueuse de slime depuis 300 ans tanpa sadar levelku mentok setelah membasmi slime selama 300 tahun slime taoshite 300-nen, shiranai uchi ni level max ni nattemashita slime taoshite 300 slime taoshite 300nen shiranai uchi ni level max ni nattemashita sono ni 슬라임을 잡으면서 300년, 모르는 사이에 레벨max가 되었습니다 я 300 лет убивала слизь и прокачалась на максимум убивая слизней триста лет, сама того не заметив, я достигла максимального уровня убивая слизней 300 лет, сама того не заметив, я достигла максимального уровня diệt slime suốt 300 năm, tôi level max lúc nào chẳng hay スライム倒して300年、知らないうちにレベルmaxになってました', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('minh-mau', 'Minh Mậu', 'Bright Eyes', 'https://phimimg.com/upload/vod/20250621-1/887751bb61d9dd0dc9612fa5504fb467.jpg', 'https://phimimg.com/upload/vod/20250621-1/e9e920ec675294602fcd380e9f7fcfed.jpg', '<p>Bộ phim kể về Lý Tri An, con gái của một vị tướng nước Bắc Tấn, do mắc bệnh về mắt nên được gả cho Chu Hoài Sâm, một con tin của nước Nam Lương. Tuy nhiên, cô lại bị hắn phản bội. Sau một biến cố, Lý Tri An trọng sinh và khôi phục thị lực. Cô quyết định giả mù để báo thù. Trong hành trình ấy, cô nhận được sự giúp đỡ từ Chu Hoài Cẩn, thế tử của Nam Lương. Cả hai cùng nhau vạch trần âm mưu, chỉnh đốn triều cục, và cuối cùng gặt hái được tình yêu đích thực.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Khương Trinh Vũ","avatar":""},{"name":"Vương Giai Tuyền","avatar":""},{"name":"Dương Kỳ Nguyên","avatar":""},{"name":"Trần Khiết Di","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ming Mou","明眸"]', 1784690324153);
