INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-giang-tien', 'Lâm Giang Tiên', 'FEUD', 'https://phimimg.com/upload/vod/20250606-1/5df03af2cff81dd6fdb63bae3382cf12.jpg', 'https://phimimg.com/upload/vod/20250606-1/2d67c4714c03028196a8e3d93bdf6999.jpg', '<p>Lâm Giang Tiên kể về mối tình bi đát giữa Lý Thanh Nguyệt và Bạch Cửu Tư. Từng quen biết nhau thuở khai thiên lập địa, nhưng sau khi trải qua nhiều biến cố đau thương, tình yêu biến thành thù hận, Lý Thanh Nguyệt chỉ muốn giết Bạch Cửu Tư, để rồi cuối cùng lại tan biến thành tro bụi. Nhiều năm sau, Bạch Cửu Tư cưới vợ mới là Lý Thanh Nguyệt, một cô gái đáng yêu, hoạt bát và đặc biệt nhất là có gương mặt giống hệt Hoa Như Nguyệt.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 10, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Bạch Lộc","avatar":""},{"name":"Tăng Thuấn Hy","avatar":""},{"name":"Hà Thụy Hiền","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Lin Jiang Xian","Heng Men You Hu","衡门有狐","衡门有狐-临江仙","临江仙","임강선: 당신에게 스며든 진한 그리움","เคราะห์สวรรค์ทัณฑ์รัก","FEUD","Lament of the River Immortal","There Is a Fox in Hengmen"]', 1784690324153);
