INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-ban-traigai-lieu-co-ben-lau', 'Tình Bạn Trai-Gái Liệu Có Bền Lâu?', 'Can a Boy-Girl Friendship Survive?', 'https://phimimg.com/upload/vod/20250411-1/908c484b45f41d05f959bd5aa876362b.jpg', 'https://phimimg.com/upload/vod/20250411-1/39cb8c263dc1a9b425e80bb8f92057d1.jpg', '<p>Tại một thị trấn nhỏ, Yuuki - chàng trai yêu cây cỏ và Rina - cô gái sôi nổi chưa biết đến tình yêu, đã thề nguyện làm ban thân suốt đời. Bước vào cấp ba, ranh giới giữa tình bạn và tình yêu bắt đầu trở nên mơ hồ khi những rung động đầu đời xuất hiện. Những hiểu lầm, sự ghen tuông và những lời trêu chọc từ bạn bè liên tục thử thách mối quan hệ tưởng chừng bền vững của họ. Liệu Yuuki và Rina có thể tiếp tục tình bạn khi đối mặt với những cảm xúc phức tạp, hay một trong hai người sẽ vượt qua giới hạn?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kikunosuke Toya","avatar":""},{"name":"Sayumi Suzushiro","avatar":""},{"name":"Yuka Nukui","avatar":""},{"name":"Ko Bonkobara","avatar":""},{"name":"Masaaki Mizunaka","avatar":""},{"name":"Hisako Kanemoto","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["男女之间存在纯友情吗？（不，不存在！!）","男女之间的友情存在吗？（不，不存在!!）","Danjo no Yuujou wa Seiritsu suru? (Iya, Shinai!!)","Danjo no Yūjō wa Seiritsu Suru? (Iya, Shinai!!)","だんじょのゆうじょうはせいりつする いや しないっ","だんじょる？","Danjoru","男女の友情は成立する？ （いや、しないっ!!）","だんじょる","Danjo no Yuujou wa Seiritsu suru Iya Shinai","男女之間存在純友情嗎？（不，不存在！）","Can a Boy–Girl Friendship Hold Up? (No, It Can''t!!)","Will Friendship Be Established Between Men and Women? (No, It Won''t!!)","Danjoru - Is This Friendship Between Man & Woman? (No Way!)","Can Friendship Between Men and Women Exist? (No, It Doesn''t!)","Can a Boy and Girl Friendship Hold Up? (No, It Can''t!!)","Can a Boy and Girl Friendship Hold Up? (No It Can''t)","Can a Boy-Girl Friendship Survive? (No It Can''t!!)","Can a Boy and Girl Friendship Hold Up? (No It Won''t!!)","Can a Boy-Girl Friendship Survive? (No It Won''t!!)","男女の友情は成立する？（いや、しないっ!!）"]', 1784690324153);
