INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-moc-hong', 'Ma Móc Họng', 'Haunting Of Mount Gede', 'https://phimimg.com/upload/vod/20250621-1/a7aa820144f914f764fa5b1a4347b1b8.jpg', 'https://phimimg.com/upload/vod/20250621-1/353f048b3ef9716493e0d2b96c921eb7.jpg', '<p>Câu chuyện kể về chuyến leo núi của nhóm bạn Ita và Maya trong kỳ nghỉ lễ. Vì phạm phải điều kỵ, Ita trở thành con mồi của lũ quỷ trong rừng, chúng thay phiên nhập vào xác cô để khiến linh hồn cô bị giam cầm nơi đây. Tuy nhiên, con ma sống tại căn nhà của Ita cũng chớp thời cơ để đoạt lấy cơ thể cô. Cơ thể Ita chứa quá nhiều linh hồn ác độc mà mà tổn hại, khiến cho sinh mạng của cô chỉ được tính bằng ngày. Maya giờ đây cố tìm cách cứu lấy bạn mình khỏi bầy quỷ dữ.</p>', 'Full', 1, 'single', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Indonesia', 1, '[{"name":"Arla Ailani","avatar":""},{"name":"Adzana Shaliha","avatar":""},{"name":"Endy Arfian","avatar":""},{"name":"Raihan Khan","avatar":""},{"name":"Moh Iqbal Sulaiman","avatar":""},{"name":"Jeremie Moeremans","avatar":""},{"name":"Razan Zu","avatar":""},{"name":"Teuku Rifnu Wikana","avatar":""},{"name":"Mieke Amalia","avatar":""},{"name":"Umar Lubis","avatar":""},{"name":"Meisya Siregar","avatar":""},{"name":"Ruth Marini","avatar":""},{"name":"Derry Oktami","avatar":""},{"name":"Ratna Riantiarno","avatar":""},{"name":"Andi Bersama","avatar":""},{"name":"Endy Tha","avatar":""},{"name":"Agus Firmansyah","avatar":""},{"name":"Faj","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075