INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trinh-sat-hinh-su-12', 'Trinh Sát Hình Sự 12', 'D.I.D 12', 'https://phimimg.com/upload/vod/20250522-1/b3698cc3c9880bdcec27e6f1c737cb69.jpg', 'https://phimimg.com/upload/vod/20250522-1/9d758bbaa21d17621702a23c8604cbe9.jpg', '<p>Một loạt án mạng liên hoàn, đã tập hợp lại Đinh Lạc Phong (Lâm Bảo Di) sỹ quan cảnh sát tổ trọng án và thanh tra cấp cao Hình Khải (Trương Chấn Lãng). Trong quá trình truy bắt hung thủ, Hình Khải buộc phải tìm sự trợ giúp của Dương Chỉ Phi (Phó Gia Lê), một nhà tâm lý học đồng thời là bạn gái cũ của Khải. Ba người nghiên cứu tỉ mỉ, phát hiện hung thủ là một tổ chức sát thủ, bằng cách cung cấp bố cục “Tân Bảy Mối Tội” qua trang web thần bí, xử tử người nào đã phạm phải “Tân Bảy Mối Tội”; và cũng khẳng định hung thủ có mối liên quan với tập đoàn Hy Nghiệp đang nắm giữ mạch máu kinh tế của thành phố này... Hình Khải không bao giờ ngờ rằng, cái mà chờ đón anh còn có một thời quá khứ anh rất muốn quên nhưng không được, đó làm cho anh ta khốn khó. Chị ruột của Lạc Phong là Đinh Thiếu Vân (Trần Pháp Dung) từ nước ngoài về lai ôm ấp một âm mưu đen tối, làm cho công việc điều tra thêm rắc rối...</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 7, 2025, 'Vietsub + Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Lâm Bảo Di","avatar":""},{"name":"Trần Pháp Dung","avatar":""},{"name":"Trương Chấn Lãng","avatar":""},{"name":"Tào Vĩnh Liêm","avatar":""},{"name":"Trần Tự Dao","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["D.I.D. 12","One-twelfth","刑偵12"]', 1784690324154);
