INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cho-den-ngay-phu-thuy-lia-doi', 'Cho Đến Ngày Phù Thủy Lìa Đời', 'Once Upon A Witch''s Death', 'https://phimimg.com/upload/vod/20250416-1/ed5a699590fae7e959ca65996ca12cf4.jpg', 'https://phimimg.com/upload/vod/20250416-1/d54db1fa2dc72cfd25444cea22f20fe1.jpg', '<p>Vào sinh nhật thứ mười bảy của mình, phù thủy tập sự Meg biết rằng cô chỉ còn sống được một năm nữa. Thầy của cô, phù thủy trường thọ Faust, giải thích rằng cách duy nhất để hóa giải lời nguyền chết chóc là thu thập những giọt nước mắt vui mừng và gieo trồng hạt giống sự sống. Để tìm thấy họ, Meg sẽ phải rời bỏ cuộc sống được che chở mà cô luôn biết đến và tiến ra thế giới. Sẽ có những cuộc gặp gỡ, những cuộc chia ly, nhiều tình bạn và tất nhiên là nhiều nước mắt. Meg sẽ học được những bài học quan trọng nhất đối với một phù thủy là sự trong sáng, ngọt ngào và có phần đau lòng.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yoshino Aoyama","avatar":""},{"name":"Yoshiko Sakakibara","avatar":""},{"name":"Miharu Hanai","avatar":""},{"name":"Aina Suzuki","avatar":""},{"name":"Rumi Okubo","avatar":""},{"name":"Hina Youmiya","avatar":""},{"name":"Atsumi Tanezaki","avatar":""},{"name":"Shizuka Itoh","avatar":""},{"name":"Yoko Hikasa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["直到某魔女死去","直至魔女消逝","直到魔女消逝","Aru Majo ga Shinu Made","ある魔女が死ぬまで -終わりの言葉と始まりの涙-","Aru Majo ga Shinu Made: Owari no Kotoba to Hajimari no Namida","Once Upon a Witch''s Death: The Tale of the One Thousand Tears of Joy","ある魔女が死ぬまで"]', 1784690324154);
