INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cho-den-ngay-phu-thuy-lia-doi', 'Cho Đến Ngày Phù Thủy Lìa Đời', 'Once Upon A Witch''s Death', 'cho đến ngày phù thủy lìa đời once upon a witch''s death yoshino aoyama yoshiko sakakibara miharu hanai aina suzuki rumi okubo hina youmiya atsumi tanezaki shizuka itoh yoko hikasa 直到某魔女死去 直至魔女消逝 直到魔女消逝 aru majo ga shinu made ある魔女が死ぬまで -終わりの言葉と始まりの涙- aru majo ga shinu made: owari no kotoba to hajimari no namida once upon a witch''s death: the tale of the one thousand tears of joy ある魔女が死ぬまで', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-moi-trong-bong-toi-cua-tri-lieu-su-tai-ba', 'Cuộc Sống Mới Trong Bóng Tối Của Trị Liệu Sư Tài Ba', 'The Brilliant Healer''s New Life In The Shadows', 'https://phimimg.com/upload/vod/20250404-1/558c14a0fead4d1e6434556b38764efb.jpg', 'https://phimimg.com/upload/vod/20250404-1/e08dae28bfe0a80e5217269dcb80cb72.jpg', '<p>Sinh ra trong khu ổ chuột nghèo khó, Zenos chưa bao giờ có cơ hội trong đời. Zenos vươn lên thành trị liệu sư tài ba, nhưng bị đồng đội phản bội. Bị đẩy vào bóng tối, anh mở phòng khám bất hợp pháp, trở thành trị liệu sư &quot;trong bóng tối&quot; huyền thoại. Danh tiếng lan truyền, nhưng cũng kéo theo nguy hiểm. Liệu anh có thể thoát khỏi vòng xoáy quyền lực đen tối, hay số phận đã định sẵn một kết cục nghiệt ngã?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shogo Sakata","avatar":""},{"name":"Miharu Hanai","avatar":""},{"name":"Yoko Hikasa","avatar":""},{"name":"Mashiro Hitaka","avatar":""},{"name":"Anna Nagase","avatar":""},{"name":"Masaaki Mizunaka","avatar":""},{"name":"Sayaka Kikuchi","avatar":""},{"name":"Taku Yashiro","avatar":""},{"name":"Yuki Nakashima","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["瞬间治疗却被视为无用而被流放的天才治疗师，以暗黑治疗师的身份幸福地生活着","一瞬间完成治疗的天才治疗师因为没用被逐出队伍，作为地下医师开始快乐生活","被放逐的天才治愈师，转为地下医生的快乐生活","瞬间治疗却被视为无用而被流放的天才治疗师，以暗黑治疗师的身份幸福地生活","瞬间治愈却被当成废物踢出队伍的天才治疗师，改当无照治疗师快乐过活","Isshun de Chiryou shiteita noni Yakutatazu to Tsuihou sareta Tensai Chiyushi, Yami Healer toshite Tanoshiku Ikiru","Isshun de Chiryō Shiteita no ni Yakutatazu to Tsuihō Sareta Tensai Chiyushi, Yami Healer to Shite Tanoshiku Ikiru","Isshun de Chiryô Shiteita no ni Yakudatazu to Tsuihô Sareta Tensai Chiyushi, Yami Hîrâ Toshite Tanoshiku Ikiru","Yami Healer","Yamihealer","闇ヒーラー","Isshun de Chiryō Shiteita no ni Yakudatazu to Tsuihō Sareta Tensai Chiyushi, Yami Hīrā Toshite Tanoshiku Ikiru","いっしゅんでちりょうしていたのにやくたたずとついほうされたてんさいちゆしやみひーらーとしてたのしくいきる","Isshun de Chiryou Shiteita noni, Nani mo Shitenai to Party wo Tsuihou Sareta Tensai Chiyushi ~ Imasara Modotte Koi to Iwaretemo, Yami Healer toshite Tanoshiku Yatteiru node Chiryou wa Kougaku ni Naru kedo Otakura Haraemasu ka? ~","天才治疗师退队作为无照治疗师快乐生活","Талановитий цілитель, що обрав шлях темного лікаря","Dark Healer","A Genius Healer Who Can Treat Instantly but Was Banished From Party Considered Doing Nothing ~ Even if They Told Him to Come Back Now, He Is Now Having Fun as a Dark Healer Now, So the Treatment Will Be Expensive, but Can You Pay for It? ~","A Genius Healer Who Can Treat Instantly but Was Banished From Party Considered Doing Nothing ~ Even if They Told Him to Come Back Now, He Is Now Having Fun as a Dark Healer Now, So the Treatment Will","一瞬で治療していたのに役立たずと追放された天才治癒師、闇ヒーラーとして楽しく生きる"]', 1784690324154);
