INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-ke-nghiep', 'Trò Chơi Kế Nghiệp', 'Game Of Succession', 'https://phimimg.com/upload/vod/20250412-1/67f54b3b32dd5b7bbd8ada63078cabd3.jpg', 'https://phimimg.com/upload/vod/20250412-1/8782027a445f9c9220591499eb76b0a4.jpg', '<p>Cái chết của mẹ, di chúc biến mất và những bí mật bị chôn vùi thôi thúc Mekhin thực hiện nhiệm vụ tìm kiếm công lý và giành lại vị trí thừa kế của mình.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Teeradetch Metawarayut","avatar":""},{"name":"Gina Yeena Salas","avatar":""},{"name":"Paswitch Boorananut","avatar":""},{"name":"Gap Chanoksuda Raksanaves","avatar":""},{"name":"Thuchapon Koowongbundit","avatar":""},{"name":"Chanidapa Pongsilpipat","avatar":""},{"name":"Rhatha Phongam","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Game of Succession","Sai Rak Sai Lueat","สายรักสายเลือด"]', 1784690324154);
