INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tro-choi-ke-nghiep', 'Trò Chơi Kế Nghiệp', 'Game Of Succession', 'trò chơi kế nghiệp game of succession teeradetch metawarayut gina yeena salas paswitch boorananut gap chanoksuda raksanaves thuchapon koowongbundit chanidapa pongsilpipat rhatha phongam game of succession sai rak sai lueat สายรักสายเลือด', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-tham-may-phan', 'Tình Thâm Mấy Phần', 'Where Love Dares', 'https://phimimg.com/upload/vod/20250618-1/40e9dc3089fee10520230ed589977ecc.jpg', 'https://phimimg.com/upload/vod/20250618-1/82b5bf58f4136c3f03ec455e95a954c3.jpg', '<p>Tại trấn Vân Thủy, nữ y sư Trần Thanh Ngôn tình cờ cứu được một chàng trai mất trí nhớ, số phận éo le. Trong quá trình cùng nhau chữa lành vết thương lòng, cả hai dần nảy sinh tình cảm. Nhưng Trần Thanh Ngôn không hề hay biết, chàng trai hiền lành ngày ngày gánh nước, hái thuốc giúp mình ấy – lại chính là Lạnh Tư Niên, vị thiếu soái lạnh lùng nổi tiếng với tin đồn muốn cưỡng chiếm trấn nhỏ này và trục xuất dân làng. Không ai ngờ, khi sống cùng Trần Thanh Ngôn, Lạnh Tư Niên đã quên đi những âm mưu quyền lực, chỉ đắm chìm trong sự dịu dàng và bình yên nơi cô. Anh từng muốn âm thầm bảo vệ cô và cả thị trấn, nhưng lại bị em trai đầy tham vọng – Lạnh Tử Xuyên – hãm hại, trở thành kẻ bị đổ oan là đã gây ra cái chết của ông nội Trần. Trần Thanh Ngôn hận anh, càng hận bản thân vì đã trót yêu anh quá sâu đậm. Cô muốn dứt bỏ mối tình nghiệt duyên này, nhưng Lạnh Tư Niên lại không cho phép, ngang ngược nhốt cô trong dinh thự của mình. Họ giằng co giữa yêu và hận, cố gắng đẩy nhau ra xa nhưng lại không ngừng bị cuốn vào nhau, rơi sâu vào vòng xoáy đầy giằng xé của tình yêu và thù hận.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Ruotian","avatar":""},{"name":"Ding Ran","avatar":""},{"name":"Eva Shang","avatar":""},{"name":"Lu Ming","avatar":""},{"name":"Jerry Tan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["求尽欢","情深几许"]', 1784690324154);
