INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lanh-chua', 'Lãnh Chúa', 'Warlord', 'https://phimimg.com/upload/vod/20250619-1/103acbb3956d8c4d37141ab164901fb1.jpg', 'https://phimimg.com/upload/vod/20250619-1/d105ed2dd5172c2f40789f9cb5249704.jpg', '<p>Cuộc nổi dậy đang manh nha trong thành phố cổ đại Lloris.Tin rằng sức mạnh thần bí của các yêu tinh có thể giúp giải phóng người dân khỏi sự áp bức, một chàng trai loài người trẻ tuổi tìm đến sự giúp đỡ của tộc yêu tinh ẩn dật và vị chiến thần huyền thoại của họ. Tuy nhiên, cả hai phe đều che giấu bí mật và động cơ thật sự, khiến liên minh mong manh giữa loài người và yêu tinh có thể dẫn đến sự diệt vong cho tất cả.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Stuart Brennan","avatar":""},{"name":"Jennifer English","avatar":""},{"name":"Aliona Baranova","avatar":""},{"name":"Ryan Gage","avatar":""},{"name":"Billy Boyd","avatar":""},{"name":"Richard Goss","avatar":""},{"name":"Devora Wilde","avatar":""},{"name":"Kerry Norton","avatar":""},{"name":"Mark Paul Wake","avatar":""},{"name":"Terry Deary","avatar":""},{"name":"Gwyneth Evans","avatar":""},{"name":"Genna Loskutnikov","avatar":""},{"name":"Ellie-Rose Mackinlay","avatar":""},{"name":"Edmund C. Short","avatar":""},{"name":"Joanna Strafford","avatar":""},{"name":"Felicity Houlbrooke","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Warlord"]', 1784690324154);
