INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-san-khi', 'Kẻ Săn Khỉ', 'Monkey Killer', 'https://phimimg.com/upload/vod/20250619-1/1a0a50ba362aa544430537983e974380.jpg', 'https://phimimg.com/upload/vod/20250619-1/418555fddb3a4b7a8a00ec9ad620f02f.jpg', '<p>Tại thị trấn u ám Old Town, một bí mật đen tối ràng buộc một nhóm bạn thuở nhỏ – những người năm xưa đã gây nên một tội ác kinh hoàng: sát hại chính một người trong số họ. Giờ đây, khi đã trưởng thành, bóng ma quá khứ quay trở lại ám ảnh họ, đe dọa phơi bày sự thật tàn nhẫn mà họ từng nghĩ đã chôn vùi mãi mãi.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Geovanni Molina","avatar":""},{"name":"Deanna Rashell","avatar":""},{"name":"Debra Cohen","avatar":""},{"name":"Lisa Arcaro","avatar":""},{"name":"Coleman Nelson","avatar":""},{"name":"Nadie Bayonne","avatar":""},{"name":"Joseph Delarosa","avatar":""},{"name":"Victor Hernandez","avatar":""},{"name":"Todd Mitchell","avatar":""},{"name":"Jonathan G. Rodriguez","avatar":""},{"name":"Atta Shatara","avatar":""},{"name":"Kiki Solomon","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Monkey Killer"]', 1784690324154);
