INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ke-san-khi', 'Kẻ Săn Khỉ', 'Monkey Killer', 'kẻ săn khỉ monkey killer geovanni molina deanna rashell debra cohen lisa arcaro coleman nelson nadie bayonne joseph delarosa victor hernandez todd mitchell jonathan g. rodriguez atta shatara kiki solomon monkey killer', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuu-thuc-chung-quy-tro-lai', 'Cửu Thúc Chung Quỳ Trở Lại', 'Uncle Nine ZhongKui Returns', 'https://phimimg.com/upload/vod/20250619-1/66301a97887cb40c5bba9add6046c8d1.jpg', 'https://phimimg.com/upload/vod/20250619-1/984889802ff9c0782b762c6e0354885a.jpg', '<p>Vào thời Dân Quốc, tại trấn Hưng Ô, thầy thuốc Đông y Cửu Thúc đến phủ họ Tiền dự lễ tế tổ thì tiểu thư nhà họ Tiền bất ngờ bị siết cổ đến chết. Tại hiện trường, Cửu Thúc phát hiện một miếng ngọc bội hình Chung Quỳ, nghi ngờ hung thủ có mối thù sâu đậm với Tiền lão gia. Không lâu sau, hung thủ lại tiếp tục gây án. Cửu Thúc cùng đội trưởng cảnh sát Lương Liên Sinh âm thầm điều tra. Cuối cùng phát hiện ra hung thủ chính là Đinh Mục. Hắn giết người để tế vong linh người em trai Đinh Viễn đã chết vì tự vẫn. Sau khi Đinh Mục bị pháp luật trừng trị, Cửu Thúc cũng kịp thời cứu Tiền Xảo Vân khỏi tay kẻ bắt cóc. Trấn nhỏ Hưng Ô từ đó trở lại những ngày yên bình.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"董一泽","avatar":""},{"name":"Yue Dongfeng","avatar":""},{"name":"Han Mengwu","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["九叔之钟馗归来"]', 1784690324154);
