INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-mau-latinh-ban-ballad-cua-ney-matogrosso', 'Dòng Máu Latinh: Bản Ballad Của Ney Matogrosso', 'Latin Blood: The Ballad Of Ney Matogrosso', 'https://phimimg.com/upload/vod/20250618-1/a858708e3348debe264ee13dfd0e9d5b.jpg', 'https://phimimg.com/upload/vod/20250618-1/892042c554918587973a631789819ba4.jpg', '<p>Từ tuổi thơ bị kìm hãm đến cách mạng nghệ thuật, Ney Matogrosso biến đổi các sân khấu của Brazil và chính bản thân mình thông qua âm nhạc, óc sáng tạo và nhiệt huyết.</p>', 'Full', 1, 'single', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Brazil', 0, '[{"name":"Jesuíta Barbosa","avatar":""},{"name":"Rômulo Braga","avatar":""},{"name":"Hermila Guedes","avatar":""},{"name":"Davi Malizia","avatar":""},{"name":"Jullio Reis","avatar":""},{"name":"Bruno Montaleone","avatar":""},{"name":"Mauro Soares","avatar":""},{"name":"Bruno Parmera","avatar":""},{"name":"Jef Lyrio","avatar":""},{"name":"Augusto Trainotti","avatar":""},{"name":"Danilo Grangheia","avatar":""},{"name":"Artur Volpi","avatar":""},{"name":"Caroline Abras","avatar":""},{"name":"Lara Tremouroux","avatar":""},{"name":"Bela Leindecker","avatar":""},{"name":"Céu","avatar":""},{"name":"Sarah Oliveira","avatar":""},{"name":"Du","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '["拉丁血与泪：巴西歌王的不羁星途","Un homme avec un grand H","Latin Blood: The Ballad of Ney Matogrosso","Homem com H"]', 1784690324154);
