INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dong-mau-latinh-ban-ballad-cua-ney-matogrosso', 'Dòng Máu Latinh: Bản Ballad Của Ney Matogrosso', 'Latin Blood: The Ballad Of Ney Matogrosso', 'dòng máu latinh: bản ballad của ney matogrosso latin blood: the ballad of ney matogrosso jesuíta barbosa rômulo braga hermila guedes davi malizia jullio reis bruno montaleone mauro soares bruno parmera jef lyrio augusto trainotti danilo grangheia artur volpi caroline abras lara tremouroux bela leindecker céu sarah oliveira du 拉丁血与泪：巴西歌王的不羁星途 un homme avec un grand h latin blood: the ballad of ney matogrosso homem com h', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-khong-the-noi-ban-han', 'Bí Mật Không Thể Nói (Bản Hàn)', 'Secret: Untold Melody', 'https://phimimg.com/upload/vod/20250319-1/cb3de205feff005cc36c8fb5950ef9f4.jpg', 'https://phimimg.com/upload/vod/20250319-1/452c564e8dc7ec702ef717bba4d739b7.jpg', '<p>Bí Mật Không Thể Nói theo chân một nghệ sĩ piano phải đột ngột chấm dứt sự nghiệp do chấn thương. Tại một học viện âm nhạc ở Hàn Quốc, anh đã phải lòng một cô gái bí ẩn, người truyền cảm hứng để anh theo đuổi âm nhạc một lần nữa. Đoạn tình cảm này mới chởm nở thì cô gái bỗng nhiên biến mất, khiến anh bối rối, đồng thời phát hiện bí mật ẩn giấu bao lâu nay.</p>', 'Full', 1, 'single', 'completed', 18, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 1, '[{"name":"Doh Kyung-soo","avatar":""},{"name":"Won Jin-ah","avatar":""},{"name":"Shin Ye-eun","avatar":""},{"name":"Bae Sung-woo","avatar":""},{"name":"Ahn Seung-gyun","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '["不能说的秘密","Secret Untold Melody","给我一首琴的时间","말할 수 없는 비밀"]', 1784690324154);
