INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kaulitz-va-kaulitz-phan-2', 'Kaulitz Và Kaulitz (Phần 2)', 'Kaulitz & Kaulitz (Season 2)', 'https://phimimg.com/upload/vod/20250619-1/b8821b9f91e9dc22bd9fca069cb2f9c4.jpg', 'https://phimimg.com/upload/vod/20250619-1/7c664aba26986b656434feede87551d2.jpg', '<p>Hai anh em siêu sao sinh đôi Tom và Bill Kaulitz hé lộ cuộc sống riêng tư của họ ở Los Angeles và Đức trong chương trình thực tế hài hước và gần gũi này.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Bill Kaulitz","avatar":""},{"name":"Tom Kaulitz","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Kaulitz & Kaulitz"]', 1784690324154);
