INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('your-forma', 'Your Forma', 'Your Forma', 'https://phimimg.com/upload/vod/20250412-1/06d9c00fc50a6ea00e0765bdc8129de2.jpg', 'https://phimimg.com/upload/vod/20250412-1/e9f55c6d6bef3e7440ebe37272bcbbbc.jpg', '<p>Vào năm 1992, một đại dịch viêm não do virus đã làm rúng động toàn thế giới. Công nghệ y học cứu sống nhân loại từ thảm họa đó đã tiến hóa thành “Your Forma” — một thiết bị lưu trữ thông tin mang tính xâm lấn, được cấy trực tiếp vào não bộ. Trong thế giới mà mọi hình ảnh, âm thanh, thậm chí cả cảm xúc đều được ghi lại, việc điều tra các vụ án nghiêm trọng đồng nghĩa với việc phải đắm mình trong dữ liệu tập thể — một công việc chỉ dành cho những điều tra viên đặc biệt, được gọi là “Điều tra viên Điện tử.” Echika Hieda, một thiên tài trong hàng ngũ Điều tra viên Điện tử, được giao nhiệm vụ từ khi còn rất trẻ, nhưng cũng vì tài năng xuất chúng đó mà cô luôn sống trong sự cô lập. Đối tác mới được chỉ định cho cô là Harold, một “Amicus” — người máy hình người với mái tóc vàng và đôi mắt xanh. Cặp đôi không đối thủ này sẽ cùng nhau phơi bày mọi bí mật được che giấu.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kana Hanazawa","avatar":""},{"name":"Kensho Ono","avatar":""},{"name":"Nao Toyama","avatar":""},{"name":"Aya Endo","avatar":""},{"name":"Nobuhiko Okamoto","avatar":""},{"name":"Ayaka Nanase","avatar":""},{"name":"Chiwa Saito","avatar":""},{"name":"Yuu Hayashi","avatar":""},{"name":"Koichi Yamadera","avatar":""},{"name":"Tomokazu Sugita","avatar":""},{"name":"Jun Fukuyama","avatar":""},{"name":"Hisako Tojo","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["你的形式","记忆缝线 YourForma","Yua Foruma","YOUR FORMA","ユア・フォルマ"]', 1784690324154);
