INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quyen-sung', 'Quyền Sủng', 'Dominion And Devotion', 'https://phimimg.com/upload/vod/20250417-1/8478aea02a48b7e2dcbcded65a9d5559.jpg', 'https://phimimg.com/upload/vod/20250417-1/9217bac92d9f4da1c8b2e33f9dc28565.jpg', '<p>Triều đại nhà Đại Ninh đang trong tình trạng hỗn loạn. Bùi Thận Chi thay đổi chiếu chỉ của hoàng đế và ủng hộ hoàng đế bù nhìn Ninh Cẩm Nhất lên ngôi. Ninh Cẩm Nhất bề ngoài thì tỏ ra thuận theo, nhưng âm thầm tụ tập sức mạnh để thúc đẩy chính sách mới. Bùi Thận Chi âm thầm giúp đỡ và bị trí tuệ của cô hấp dẫn. Cuối cùng, Ninh Cẩm Nhất đã thanh lọc chiều trính và trở thành nữ đế một thời.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Ca Dương","avatar":""},{"name":"Hoàng Hạo Nguyệt","avatar":""},{"name":"Bạch Hải Đào","avatar":""},{"name":"Trương Viên Ngọc","avatar":""},{"name":"Trịnh Phong","avatar":""},{"name":"Vương Học Tập","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Quan Chong","Господство и преданность","Власть и благосклонность","Власть и преданность","Могущество и красота","权宠"]', 1784690324154);
