INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-hach-dao', 'Vân Hách Dao', 'The Antidote To Love', 'https://phimimg.com/upload/vod/20250606-1/742f659eda4a3e5f9ebb72c0e47e5c34.jpg', 'https://phimimg.com/upload/vod/20250606-1/5bf3bf4707996c9a0768892d826ed72d.jpg', '<p>Thời kỳ Đại Vị, xã tắc hỗn loạn, Ninh vương Triệu Hách dẫn binh xuất trận, tính mạng ngàn cân treo sợi tóc. Thái bốc thự phụng chỉ, dâng dược nô giúp hắn giải độc. Dược nô Nhất Cửu che dấu thân phận là thánh nữ Nguyệt tộc, tự lấy mình làm mồi nhử để dấn thân vào nguy hiểm. Cuối cùng, Triệu Hách và Vân Dao cùng nhau làm sáng tỏ chân tướng về vụ thảm sát Nguyệt tộc, trải qua sinh tử, giữ vững tâm niệm ban đầu, bảo vệ thiên hạ thái bình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Cửu Lâm","avatar":""},{"name":"Chu Lệ Nham","avatar":""},{"name":"Trần Thiêm Tường","avatar":""},{"name":"Phó Dư Thư","avatar":""},{"name":"Mã Lệ Á","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["云赫谣"]', 1784690324154);
