INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luat-phap-va-trat-tu-toi-pham-co-to-chuc-phan-5', 'Luật Pháp Và Trật Tự: Tội Phạm Có Tổ Chức (Phần 5)', 'Law & Order: Organized Crime (Season 5)', 'https://phimimg.com/upload/vod/20250618-1/9dec3711fbf0ab962252f1c94e4942ae.jpg', 'https://phimimg.com/upload/vod/20250618-1/ed8e081b956cb058124038ef395d68c0.jpg', '<p>Một thanh tra cảnh sát trở lại New York để triệt phá tổ chức tội phạm đã gây ra cái chết cho vợ ông.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Christopher Meloni","avatar":""},{"name":"Danielle Moné Truitt","avatar":""},{"name":"Rick Gonzalez","avatar":""},{"name":"Dean Norris","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Lei & Ordem: Crime Organizado","法网游龙：组织犯罪","Law and Order Organized Crime","New York : Crime organisé","Law & Order: OC","Law & Order: Organized Crime"]', 1784690324154);
