INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('luat-phap-va-trat-tu-toi-pham-co-to-chuc-phan-5', 'Luật Pháp Và Trật Tự: Tội Phạm Có Tổ Chức (Phần 5)', 'Law & Order: Organized Crime (Season 5)', 'luật pháp và trật tự: tội phạm có tổ chức (phần 5) law & order: organized crime (season 5) christopher meloni danielle moné truitt rick gonzalez dean norris lei & ordem: crime organizado 法网游龙：组织犯罪 law and order organized crime new york : crime organisé law & order: oc law & order: organized crime', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-mau', 'Đại Mẫu', 'The Old Woman With The Knife', 'https://phimimg.com/upload/vod/20250617-1/f3f99c52a8fb9effa06ce186e7b81bda.jpg', 'https://phimimg.com/upload/vod/20250617-1/f07863e78e7669655efbc85625cea756.jpg', '<p>Hornclaw, một sát thủ già từng trải, tưởng chừng đã nhìn thấu mọi mặt của thế giới ngầm, nhưng bà không ngờ rằng mình sẽ trở thành người dẫn dắt cho một tay lính mới liều lĩnh tên Bullfight. Khi mối quan hệ kỳ lạ giữa hai người dần sâu sắc, những rạn nứt trong thế giới ngầm mà họ hoạt động cũng bắt đầu lộ ra. Mọi thứ càng trở nên nguy hiểm khi Hornclaw phát hiện có kẻ đang muốn lấy mạng mình. Giữa vòng vây của kẻ thù và sự phản bội rình rập, để sống sót, bà buộc phải giữ cho lưỡi dao – và cả đầu óc – luôn sắc bén.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Hye-young","avatar":""},{"name":"Kim Sung-cheol","avatar":""},{"name":"Yeon Woo-jin","avatar":""},{"name":"Kim Moo-yul","avatar":""},{"name":"Shin Sia","avatar":""},{"name":"Kim Kang-woo","avatar":""},{"name":"Choi Moo-seong","avatar":""},{"name":"Ok Ja-yeon","avatar":""},{"name":"Lee Hyun-gul","avatar":""},{"name":"Lee Yong-nyeo","avatar":""},{"name":"Cho Han-cheul","avatar":""},{"name":"Nam Myung-ryeol","avatar":""},{"name":"Hyun Bong-sik","avatar":""},{"name":"Jung Hyeon-jun","avatar":""},{"name":"Yoon Chae-na","avatar":""},{"name":"Kil Hae-yeon","avatar":""},{"name":"Park Ji-a","avatar":""},{"name":"Park Myung-shi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Pagwa","Bıçaqlı Qoca Qadın","Старуха с ножом","پیرزن چاقو به دست","L''Ombre, la Femme et le Couteau","The Old Woman with the Knife","파과"]', 1784690324154);
