INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dai-mau', 'Đại Mẫu', 'The Old Woman With The Knife', 'đại mẫu the old woman with the knife lee hye-young kim sung-cheol yeon woo-jin kim moo-yul shin sia kim kang-woo choi moo-seong ok ja-yeon lee hyun-gul lee yong-nyeo cho han-cheul nam myung-ryeol hyun bong-sik jung hyeon-jun yoon chae-na kil hae-yeon park ji-a park myung-shi pagwa bıçaqlı qoca qadın старуха с ножом پیرزن چاقو به دست l''ombre, la femme et le couteau the old woman with the knife 파과', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('san-lung-toi-ac', 'Săn Lùng Tội Ác', 'Crime Hunt', 'https://phimimg.com/upload/vod/20250617-1/204db2073d469ee1529384ecc60c0298.jpg', 'https://phimimg.com/upload/vod/20250617-1/f76895f4b7cfdacf56a21532c8e5883b.jpg', '<p>Khi tên tội phạm chính của “Vụ án thuốc thử CH” cách đây 24 năm – Đinh Kiều – bị bắt ở nước ngoài và bị áp giải về nước cùng với mẫu thuốc thử quan trọng “CH3”, thành phố Hải Châu bắt đầu liên tiếp xảy ra các vụ án mạng. Điều kỳ lạ là: ai bị cảnh sát điều tra, người đó đều chết một cách bí ẩn, khiến đội trưởng đội hình sự Tôn Chính Dương hoàn toàn không hiểu nổi chuyện gì đang diễn ra. Anh bắt đầu nghi ngờ những vụ án này có liên quan đến vụ án cũ cách đây hơn 20 năm. Quan trọng hơn, anh nghi ngờ đồng đội mới nhậm chức – Sở Bạch – có liên quan đến tổ chức tội phạm, bởi vì cha của Sở Bạch, chính là Sở Giang Hà – người chịu trách nhiệm chính trong vụ án năm xưa. Năm đó, Sở Giang Hà đã nổ súng làm trọng thương cha của Tôn Chính Dương – Tôn Vĩnh An, khi ông đang là đội trưởng đội hình sự, sau đó thì Sở Giang Hà biến mất không dấu vết. Càng điều tra sâu, sự nghi ngờ của Tôn Chính Dương đối với Sở Bạch càng tăng, cho đến một ngày, Sở Bạch chĩa súng vào lưng Tôn Chính Dương. Nhưng Tôn Chính Dương không ngờ rằng, tất cả chỉ là một phần trong kế hoạch của Cục trưởng Cao Bình, người đã giăng ra một cái bẫy lớn nhằm vạch trần sự thật về vụ án cũ đã bị chôn vùi suốt hàng chục năm…</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Liu Yitong","avatar":""},{"name":"Zhang Xiaoqian","avatar":""},{"name":"Miao Tingru","avatar":""},{"name":"Wang Jinsong","avatar":""},{"name":"Mao Cheng","avatar":""},{"name":"Zhang Dabao","avatar":""},{"name":"Cao Wanjin","avatar":""},{"name":"Zhang Boyu","avatar":""},{"name":"Hu Shiwen","avatar":""},{"name":"Su Xunlun","avatar":""},{"name":"Liu Nayu","avatar":""},{"name":"Huang Jingxin","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["幕后真凶","法网缉凶"]', 1784690324154);
