INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('san-lung-toi-ac', 'Săn Lùng Tội Ác', 'Crime Hunt', 'săn lùng tội ác crime hunt liu yitong zhang xiaoqian miao tingru wang jinsong mao cheng zhang dabao cao wanjin zhang boyu hu shiwen su xunlun liu nayu huang jingxin 幕后真凶 法网缉凶', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-yeu-bi-mat-tich', 'Người Yêu Bị Mất Tích', 'Missing Lover', 'https://phimimg.com/upload/vod/20250617-1/2ac72e747f99d714811ac3740d693041.jpg', 'https://phimimg.com/upload/vod/20250617-1/cefae3c8c99c4bf23518b2b74ab4f6e5.jpg', '<p>Nữ cường nhân Hứa Hy – người sáng lập công ty bằng chính đôi tay mình – đã rơi vào lưới tình với một anh chàng đẹp trai nhưng là “trai ngoan của mẹ”, Lưu Khải An. Bị cuốn hút bởi những lời đường mật của anh ta, cô không chỉ trao trái tim mà còn tặng anh một nửa cổ phần công ty. Khi công việc làm ăn ngày càng phát đạt, Lưu Khải An lấy cớ gọi vốn để chuyển toàn bộ cổ phần ra ngoài, rồi bắt tay với mẹ mình, ép Hứa Hy phải về nhà an tâm dưỡng thai. Trong trận chiến mẹ chồng – nàng dâu đầy căng thẳng, Hứa Hy bất hạnh sảy thai. Tưởng chừng người bạn thân duy nhất nơi thành phố lớn – Trần Nhã Lộ – sẽ là chỗ dựa, nhưng hóa ra cô ta đã ngoại tình với Lưu Khải An từ trước đám cưới, thậm chí còn đang mang thai con của hắn. Tuyệt vọng, Hứa Hy tự sát nhưng không thành. Sau khi thay tên đổi mặt, cô gia nhập lại công ty – nơi chồng cũ và bạn thân giờ đã kết hôn – với quyết tâm giành lại tất cả những gì thuộc về mình, và khiến những kẻ đã phản bội phải trả giá đắt!</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ni Songyang","avatar":""},{"name":"Wang Xingchen","avatar":""},{"name":"Zi Fuer","avatar":""},{"name":"Yan Jiaying","avatar":""},{"name":"An Yu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Xiao Shi De Ai Ren","消失的愛人","Gone Lover","消失的爱人"]', 1784690324154);
