INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-bep-careme', 'Đầu Bếp Carême', 'Carême', 'https://phimimg.com/upload/vod/20250617-1/2733d4b181f4188c2ad66bed6ed2901f.jpg', 'https://phimimg.com/upload/vod/20250617-1/5142d3a32c6f246b322798488189a021.jpg', '<p>Đi theo sự vươn lên của đầu bếp tên tuổi đầu tiên trên thế giới, Antonin Carême và quá trình dấn thân vào cuộc sống gián điệp ở nước Pháp thời Napoleon, nơi sự thao túng lên ngôi. Tài năng về ẩm thực và quyến rũ biến anh trở thành vũ khí hoàn hảo trong cuộc chiến quyền lực.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Benjamin Voisin","avatar":""},{"name":"Jérémie Renier","avatar":""},{"name":"Lyna Khoudri","avatar":""},{"name":"Sigrid Bouaziz","avatar":""},{"name":"Alice da Luz","avatar":""},{"name":"Pablo Cobo","avatar":""},{"name":"Micha Lescot","avatar":""},{"name":"Juliette Armanet","avatar":""},{"name":"Arthur Mazet","avatar":""},{"name":"Lily Taïeb","avatar":""},{"name":"Maud Wyler","avatar":""},{"name":"Dimitri Doré","avatar":""},{"name":"Clotilde Mollet","avatar":""},{"name":"Gabriel Donzelli","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["קארם","Careme","Carême"]', 1784690324154);
