INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dau-bep-careme', 'Đầu Bếp Carême', 'Carême', 'đầu bếp carême carême benjamin voisin jérémie renier lyna khoudri sigrid bouaziz alice da luz pablo cobo micha lescot juliette armanet arthur mazet lily taïeb maud wyler dimitri doré clotilde mollet gabriel donzelli קארם careme carême', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chiec-vong-ngoc-bich', 'Chiếc Vòng Ngọc Bích', 'The Jade Bracelet', 'https://phimimg.com/upload/vod/20250516-1/5ad06a97dbb502ba71520a05c2286a85.jpg', 'https://phimimg.com/upload/vod/20250516-1/310c5e61b2546acd218ccef6228170eb.jpg', '<p>“Chiếc vòng ngọc bích” kể về câu chuyện tình dang dở của cô gái nghèo côi cút tên Lụa. Vì trót trao tình cho Thành Danh, cậu ba nhà họ Lê nổi tiếng trăng hoa, Lụa đã phải nhận kết cục bi thảm. Sông, kết tinh của tình yêu oan trái cũng trở thành hòn máu rơi vô thừa nhận. Không thể thực hiện di nguyện của cô bạn vắn số, Tâm, chàng trai cùng cảnh ngộ với Lụa quyết định sẽ cưu mang đứa bé bất hạnh ấy. Tám năm sau, Thành Danh vì muốn được thừa hưởng tài sản Lê gia đã bất chấp thủ đoạn cướp lại đứa con trai mà anh ta từng nhẫn tâm chối bỏ khi xưa. Trước quyền thế của cậu ba Danh, Tâm đành bất lực rời con. Trong khi đó, Nhung, người chị gái song sinh thất lạc từ nhỏ của Lụa vì muốn trả thù cho em gái và bảo vệ cháu mình đã tìm mọi cách bước chân vào nhà họ Lê trong thân phận của Lụa. Đó cũng là lúc hào môn dậy sóng vì oán thù xưa sống lại…</p>', 'Hoàn Tất (54/54)', 54, 'series', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Hạ Anh","avatar":""},{"name":"Anh Tài","avatar":""},{"name":"Huỳnh Trường Thịnh","avatar":""},{"name":"Lê Bê La","avatar":""},{"name":"Đàm Phương Linh","avatar":""},{"name":"Võ Thành Tâm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324154);
