INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rana-naidu-phan-2', 'Rana Naidu (Phần 2)', 'Rana Naidu (Season 2)', 'https://phimimg.com/upload/vod/20250615-1/b861cc8a150513e56e4e7b2b8e9a9211.jpg', 'https://phimimg.com/upload/vod/20250615-1/1b713b45df569cfcb6bdd0dd87db1c25.jpg', '<p>Khi bê bối sắp nổ ra, các ngôi sao, giới trùm và triệu phú tại Mumbai luôn nghĩ đến Rana Naidu đầu tiên – miễn là họ đồng ý ngó lơ những việc anh làm.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 18, 2025, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Rana Daggubati","avatar":""},{"name":"Venkatesh","avatar":""},{"name":"Arjun Rampal","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Rana Nayudu","พยัคฆ์บอมเบย์","Rana Naidu","राणा नायडू"]', 1784690324154);
