INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luoi-hai-tu-than-huyet-thong', 'Lưỡi hái tử thần: Huyết thống', 'Final Destination Bloodlines', 'https://phimimg.com/upload/vod/20250519-1/872f6d309a41198178ccfa786a09b23f.jpg', 'https://phimimg.com/upload/vod/20250519-1/a2d2f2834b4b34f20b0c3bb7e26a9e73.jpg', '<p>Thương hiệu kinh dị đình đám Hollywood Final Destination sẽ trở lại với phần phim mới, hứa hẹn khuấy đảo phòng vé mùa hè 2025. Final Destination: Bloodlines là phần thứ 6 trong series, và cho đến hiện tại, các thông tin về nội dung phần phim này vẫn đang được giữ kín. Bộ đôi Zach Lipovsky và Adam Stein được chọn từ hơn 200 ứng viên để ngồi ghế đạo diễn, trong khi Guy Busick - biên kịch của Ready or Not sẽ chấp bút cho bộ phim. Tony Todd - gương mặt quen thuộc của series cũng sẽ trở lại trong phần 6 với vai diễn William Bludworth.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Kaitlyn Santa Juana","avatar":""},{"name":"Teo Briones","avatar":""},{"name":"Rya Kihlstedt","avatar":""},{"name":"Richard Harmon","avatar":""},{"name":"Owen Patrick Joyner","avatar":""},{"name":"Anna Lore","avatar":""},{"name":"Brec Bassinger","avatar":""},{"name":"Tony Todd","avatar":""},{"name":"Andrew Tinpo Lee","avatar":""},{"name":"Gabrielle Rose","avatar":""},{"name":"Alex Zahara","avatar":""},{"name":"April Telek","avatar":""},{"name":"Max Lloyd-Jones","avatar":""},{"name":"Brenna Llewellyn","avatar":""},{"name":"Natasha Burnett","avatar":""},{"name":"Jayden Oniah","avatar":""},{"name":"Mark","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["파이널 데스티네이션 6","Destination ultime liens de sang","Premonição 6: Laços de Sangue","Destino final: Lazos de sangre","फाइनल डेस्टिनेशन: ब्लडलाइन्स","Пункт назначения: Узы крови","Пункт назначения: Кровные узы","絕命終結站 血脈","Destino Final 6: Lazos De Sangre","අවසාන ගමනාන්තය 6: රුධිර රේඛා","الوجهة النهائية 6: خطوط الدم","Final Destination: Bloodlines","ไฟนอลเดสติเนชั่น ทายาทโกงตาย","Final Destination 6","ファイナル・デスティネーション：ブラッドライン","死神来了6","死神来了6：血脉诅咒","Destination finale 6","Final Destination 6: Bloodlines","死神來了：血脈","絕命終結站：血脈","Final Destination 6 - Bloodlines","Final Destination Bloodlines"]', 1784690324154);
