INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bach-lac-mon', 'Bách Lạc Môn', 'Paramount', 'https://phimimg.com/upload/vod/20250607-1/7b6d978000ca12a814c7933ba21e07c0.jpg', 'https://phimimg.com/upload/vod/20250607-1/80b959041571aa85ec9b98771382d8e3.jpg', '<p>Bạch Lạc mất đi người thân, lại bị hôn phu hào môn là Tiền Mục Thần vứt bỏ. Sống lại từ địa ngục, cô hóa thân thành ca kĩ Bách Lạc Môn, thực hiện kế hoạch báo thù của mình một cách gọn ghẽ. Lần này, cô muốn biến tất cả mọi người thành vật trong tay của mình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Viên Tử Minh","avatar":""},{"name":"Kiều Tịnh Văn","avatar":""},{"name":"Lý Thạc","avatar":""},{"name":"Từ Tử Tuyền","avatar":""},{"name":"An Đông","avatar":""},{"name":"Lưu Mỹ Luân","avatar":""},{"name":"Trịnh Vũ Thừa","avatar":""},{"name":"Trì Tiểu Đồng","avatar":""},{"name":"Vương Vũ Tranh","avatar":""},{"name":"Triệu Khoa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bai Le Men","百乐门"]', 1784690324154);
