INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuong-gia-vinh-dieu', 'Vương Giả Vinh Diệu', 'Honor Of Kings', 'https://phimimg.com/upload/vod/20250531-1/ee6e5bf9d9babc19496684182bd6e91f.jpg', 'https://phimimg.com/upload/vod/20250531-1/8265934789045e796f327b2c94368ac8.jpg', '<p>Trên lục địa Vương Giả rộng lớn vô tận, những vị anh hùng rực rỡ như những vì sao, vượt qua hiểm nguy, theo đuổi ước mơ. Thế nào là anh hùng? Là vượt qua chính mình, kiếm tìm sự hoàn mỹ tuyệt đối; là tiến bước về phía trước với trọng trách trên vai, tìm ra chân lý của tình yêu; là không ngừng trở nên mạnh mẽ hơn, không bao giờ từ bỏ. Chúng ta viết nên truyền kỳ cho những anh hùng, mở ra chương mới của tình yêu và lòng dũng cảm.</p>', 'Hoàn Tất (8/8)', 8, 'hoathinh', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jiajie Wang","avatar":""},{"name":"Lu Zhao","avatar":""},{"name":"Zhou Shuai","avatar":""},{"name":"Mace","avatar":""},{"name":"Yuting Luo","avatar":""},{"name":"Zhang Fuzheng","avatar":""},{"name":"Haiting Cai","avatar":""},{"name":"Shuang Zhao","avatar":""},{"name":"Shuai Guan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Wang Zhe Rongyao","Wang Zhe Rong Yao Rong Yao Zhi Zhang","王者荣耀：荣耀之章命运篇","王者荣耀：荣耀之章碎月篇","王者荣耀：荣耀之章宝藏篇","王者荣耀：荣耀之章 第1季","王者荣耀：荣耀之章 第2季","Honor of Kings: Chapter of Glory","King of Glory","王者荣耀：荣耀之章"]', 1784690324154);
