INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muon-duoc-o-gan-em', 'Muốn Được Ở Gần Em', 'Close To You', 'https://phimimg.com/upload/vod/20250520-1/b7b8ac6a083e968796064d7be83d74c7.jpg', 'https://phimimg.com/upload/vod/20250520-1/d2829c38d70b83b4ed55d3472dbdc19f.jpg', '<p>Minh Hy - một cô gái bình thường bất ngờ nhận được cơ hội vào học tại Học viện Tinh Anh. Để hoàn thành kỳ vọng của người cha đã khuất, cô quyết tâm phát huy tài năng thể thao thiên bẩm tại ngôi trường danh giá này. Trong khi đó, Giang Bạc Hãn - chàng trai tài năng xuất chúng nhưng mang trong lòng nỗi đau mất em trai, đã cố tình khoác lên mình vỏ bọc của một học sinh cá biệt ngỗ ngược để chống lại sự xa cách với mẹ. Hai con người mang những lớp vỏ ngụy trang ấy bỗng chốc vướng vào cuộc đời nhau. Họ giằng xé, đối đầu, rồi lại cứu rỗi lẫn nhau. Những vết sẹo trong lòng dần được phơi bày, và cũng chính họ lại trở thành liều thuốc dịu dàng nhất chữa lành cho nhau.</p>', 'Hoàn Tất (31/31)', 31, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Liu Xiaobei","avatar":""},{"name":"Bubble Zhu","avatar":""},{"name":"Li Ruotian","avatar":""},{"name":"Wu Bowei","avatar":""},{"name":"Chen Jianing","avatar":""},{"name":"Chen Siyu","avatar":""},{"name":"Hu Xiaolong","avatar":""},{"name":"Lv Yihao","avatar":""},{"name":"Liu Haoyuan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["狼少年们","偏愛靠近你","Pian Ai Kao Jin Ni","狼少年們","Lang Shao Nian Men","편애고근니 : 너에게 가까이","Рык","Growl","偏爱靠近你"]', 1784690324154);
