INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vong-xoay-duc-vong', 'Vòng Xoáy Dục Vọng', 'I Would Rather Kill You', 'https://phimimg.com/upload/vod/20250614-1/b5ed6a8f5215a12db1c83fdbce255eb6.jpg', 'https://phimimg.com/upload/vod/20250614-1/917c2c7e5b10be128199fb33bdca71de.jpg', '<p>Hai chị em Seon-yeong và Ji-yeong rời bỏ thành phố ồn ào náo nhiệt để chuyển đến một ngôi làng hẻo lánh yên bình. Sự xuất hiện của họ nhanh chóng làm dấy lên làn sóng cảm xúc trong ngôi làng nhỏ. Chủ tịch thanh niên Dae-geun và trưởng làng Bong-sam, những người luôn hết mình vì hạnh phúc và sự thịnh vượng của làng, đều phải lòng hai chị em xinh đẹp này. Không chỉ có họ, một người đàn ông khả nghi luôn dõi theo hai chị em một cách ám ảnh, cùng với một tên tội phạm bị truy nã xuất hiện gây náo loạn cả làng! Từng người đàn ông trong làng dường như đều rơi vào chiếc bẫy ham muốn đầy điên loạn. Và rồi, những điều không thể tưởng tượng nổi bắt đầu xảy ra trong ngôi nhà của hai chị em đã bị cuốn vào vòng xoáy dục vọng nguy hiểm...</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Do Yeon","avatar":""},{"name":"Kim Ju-eun","avatar":""},{"name":"Ahn Jeong-gyun","avatar":""},{"name":"Kim Ki-doo","avatar":""},{"name":"Yoon Se-woong","avatar":""},{"name":"Kang Dong-gyun","avatar":""},{"name":"Ban Min-jeong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Just Kill Me","Charari Jukyeo","2024-MF03194","你还不如杀了我","차라리 죽여"]', 1784690324154);
