INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lanh-dia-tu-chien', 'Lãnh Địa Tử Chiến', 'MobLand', 'https://phimimg.com/upload/vod/20250407-1/cecfcb01fd54714a38c7e1d48b999a16.jpg', 'https://phimimg.com/upload/vod/20250407-1/ddc83aefe923808865af0b344d91e7ff.jpg', '<p>Hai gia tộc tội phạm khét tiếng ở London, nhà Harrigan và nhà Stevenson, lao vào cuộc chiến sống còn để giành quyền kiểm soát thế giới ngầm. Trong khi bạo lực leo thang, Harry Da Souza – một &quot;fixer&quot; đầy mưu mô – bị cuốn vào cuộc chiến quyền lực tàn khốc này. Khi các thế lực đối đầu, lòng trung thành bị thử thách và mạng sống trở thành thứ để đặt cược. Trong thế giới mà ranh giới thiện - ác bị xóa nhòa, chỉ có một quy tắc duy nhất: Gia đình là trên hết.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 5, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Hardy","avatar":""},{"name":"Pierce Brosnan","avatar":""},{"name":"Paddy Considine","avatar":""},{"name":"Joanne Froggatt","avatar":""},{"name":"Lara Pulver","avatar":""},{"name":"Anson Boon","avatar":""},{"name":"Jasmine Jobson","avatar":""},{"name":"Mandeep Dhillon","avatar":""},{"name":"Daniel Betts","avatar":""},{"name":"Helen Mirren","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["黑帮领地","黑帮之地","Мобленд","أرض العصابات","The Donovans","The Associate","Guy Ritchie''s The Associate","MobLand"]', 1784690324154);
