INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('aniela', 'Aniela', 'An!ela', 'https://phimimg.com/upload/vod/20250613-1/5ca180bb14576f4c1e98b04ad3fd2a07.jpg', 'https://phimimg.com/upload/vod/20250613-1/827c51e9fcf697d9db362f9fcfd70bd2.jpg', '<p>Sau khi người chồng giàu có bỏ cô mà không chia chút tài sản nào, người phụ nữ thượng lưu nọ ở Warsaw buộc phải sử dụng kỹ năng sinh tồn duy nhất còn lại của mình: trí tuệ sắc sảo.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Ba Lan', 0, '[{"name":"Małgorzata Kożuchowska","avatar":""},{"name":"Jacek Poniedziałek","avatar":""},{"name":"Lila Vasina","avatar":""},{"name":"Cezary Pazura","avatar":""},{"name":"Gabriela Muskała","avatar":""},{"name":"Pitry Pitry","avatar":""},{"name":"Anita Szepelska","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Aniela","An!ela"]', 1784690324154);
