INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('va-nguoi-kiem-tien-chinh-la', 'Và Người Kiếm Tiền Chính Là...', 'And The Breadwinner Is...', 'https://phimimg.com/upload/vod/20250613-1/892574df2d33e1eef646f84efe3f773a.jpg', 'https://phimimg.com/upload/vod/20250613-1/902ac36c6e19470b1d311ef4d69c6f2e.jpg', '<p>Một sự nhầm lẫn danh tính đã mở ra cơ hội đầy hứa hẹn khi người trụ cột gia đình – Bambi – trở về nhà và phát hiện mình… đang được tổ chức tang lễ. Thay vì đính chính sự nhầm lẫn hài hước đó, Bambi cùng với gia đình &quot;rối ren&quot; của mình quyết định tiếp tục duy trì màn kịch lố bịch này để nhận số tiền bảo hiểm nhân thọ trị giá 10 triệu peso – với hy vọng cuối cùng có thể biến giấc mơ cuộc sống lý tưởng của họ thành hiện thực.</p>', 'Full', 1, 'single', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Vice Ganda","avatar":""},{"name":"Eugene Domingo","avatar":""},{"name":"Joel Torre","avatar":""},{"name":"Malou de Guzman","avatar":""},{"name":"Gladys Reyes","avatar":""},{"name":"Jhong Hilario","avatar":""},{"name":"Maris Racal","avatar":""},{"name":"Kokoy de Santos","avatar":""},{"name":"Anthony Jennings","avatar":""},{"name":"Via Antonio","avatar":""},{"name":"MC Muah","avatar":""},{"name":"Lassy Marquez","avatar":""},{"name":"Kulot Caponpon","avatar":""},{"name":"Argus Aspiras","avatar":""},{"name":"Petite","avatar":""},{"name":"Kiko Matos","avatar":""},{"name":"Coco Martin","avatar":""},{"name":"Jhoanna San Juan","avatar":""},{"name":"Ne","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324154);
