INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-hoa-toan-tap-bi-kich-astroworld', 'Thảm Họa Toàn Tập: Bi Kịch Astroworld', 'Trainwreck: The Astroworld Tragedy', 'https://phimimg.com/upload/vod/20250613-1/e1bd686ad9c47c6662c9a2df0cb867a3.jpg', 'https://phimimg.com/upload/vod/20250613-1/47fed7f096d738a81f351c91dcfcb92a.jpg', '<p>Vào ngày 5 tháng 11 năm 2021, Travis Scott đã bước lên sân khấu để biểu diễn tại Astroworld: đêm đáng lẽ là đêm tuyệt vời nhất trong cuộc đời của những người tham dự lễ hội đã nhanh chóng trở thành thảm họa khiến 10 người trong số họ tử vong. The Astroworld Tragedy có cái nhìn độc quyền về đêm đó, được kể từ góc nhìn của những người sống sót, nhân viên y tế và nhân viên an ninh là trung tâm của thảm họa này. Với các cuộc phỏng vấn độc quyền với những người sống sót, nhân viên y tế và nhân viên lễ hội, bộ phim tài liệu này xem xét thảm kịch Astroworld năm 2021 và hậu quả của nó.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Travis Scott","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Trainwreck: The Astroworld Tragedy"]', 1784690324154);
