INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('titan-tham-hoa-oceangate', 'Titan: Thảm họa OceanGate', 'Titan: The OceanGate Submersible Disaster', 'https://phimimg.com/upload/vod/20250613-1/66ec9184b07826af18d14f9d05adb562.jpg', 'https://phimimg.com/upload/vod/20250613-1/1682406669c4a477a7a378035c4c306d.jpg', '<p>Tàu lặn du lịch Titan của OceanGate bị nổ tung năm 2023 trong chuyến lặn sâu thám hiểm tàu Titanic. Bộ phim tài liệu này thuật lại cách một tầm nhìn táo bạo kết thúc trong bi kịch.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Stockton Rush","avatar":""},{"name":"Paul-Henri Nargeolet","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324154);
