INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lap-doc-phong-bao', 'Lạp Độc Phong Bạo', 'Drug Bust Storm', 'https://phimimg.com/upload/vod/20250613-1/d5aab275c3077a18edb1ed22e8c58803.jpg', 'https://phimimg.com/upload/vod/20250613-1/7c1ed4049696aa28bf249adafc338e6b.jpg', '<p>Nơi biên giới, các trùm ma túy lộng hành ngang ngược, cảnh sát phòng chống ma túy phải bước vào cuộc chiến sống còn! Trong chiến dịch vây bắt tội phạm ma túy, phó đội trưởng Tiêu Nhược Lan không may rơi vào bẫy, sống chết chưa rõ. Đúng lúc đó, một “người thay thế” mang diện mạo giống hệt cô đã âm thầm trà trộn vào lực lượng cảnh sát. Tên trùm ma túy Trần Cường đã âm mưu từ lâu, chuẩn bị tiến hành một phi vụ buôn bán ma túy với quy mô lớn hơn nữa. Cuộc đối đầu giữa Tiêu Nhược Lan thật và giả, những màn đấu đá ngầm trong nội bộ bọn buôn ma túy, cùng những pha đấu súng nghẹt thở trong tuyệt cảnh! Khi sự thật dần được hé lộ, ai mới là người chiến thắng cuối cùng?</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Dong","avatar":""},{"name":"Huang Haibing","avatar":""},{"name":"Waise Lee","avatar":""},{"name":"Wang Hui","avatar":""},{"name":"Xiaoxue Chen","avatar":""},{"name":"Zi Fuer","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Poison Hunting Storm","猎毒风暴"]', 1784690324154);
