INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lap-doc-phong-bao', 'Lạp Độc Phong Bạo', 'Drug Bust Storm', 'lạp độc phong bạo drug bust storm zhang dong huang haibing waise lee wang hui xiaoxue chen zi fuer poison hunting storm 猎毒风暴', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoang-cach-giua-doi-ta', 'Khoảng Cách Giữa Đôi Ta', 'Flat Girls', 'https://phimimg.com/upload/vod/20250613-1/712ffd81bf3307ace859e2ffe1e1018c.jpg', 'https://phimimg.com/upload/vod/20250613-1/123cd6396460f6c99a39b164231ed66d.jpg', '<p>Trong khu chung cư của cảnh sát – nơi có hàng trăm gia đình cảnh sát cùng sinh sống – có Jane, một cô gái đến từ gia đình của một sĩ quan cấp cao. Mẹ cô là “bà trùm” cho vay nặng lãi trong khu chung cư, khiến ai cũng phải nể sợ. Trong khi đó, Ann là cô gái có cha đã hy sinh khi đang làm nhiệm vụ, khiến cô phải giúp mẹ làm việc kiếm sống và chăm sóc ba em nhỏ. Jane và Ann luôn chia sẻ mọi khoảnh khắc với nhau, lúc nào cũng kề vai sát cánh. Sau giờ tan học, họ thường cùng nhau chơi cầu lông ở sân giữa khu nhà, cùng với người bạn thân thiết là Nice. Jane luôn mong muốn được sống mãi trong khu chung cư này, với Ann luôn ở bên cạnh. Thế nhưng, mọi chuyện bắt đầu thay đổi khi Tong – một chàng cảnh sát trẻ mới chuyển đến – xuất hiện. Sự có mặt của anh không chỉ làm lung lay tình bạn giữa Jane và Ann, mà còn buộc cả hai phải đối mặt với sự thật cay đắng: Gia đình của Ann – một gia đình cảnh sát không còn người cha – có thể không còn nhiều thời gian để tiếp tục sống trong khu chung cư này.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Thái Lan', 1, '[{"name":"Fatima Dechawaleekul","avatar":""},{"name":"Kirana Pipityakorn","avatar":""},{"name":"Pakorn Chatborirak","avatar":""},{"name":"Wachirakon Raksasuwan","avatar":""},{"name":"Namfon Pakdee","avatar":""},{"name":"Suraphan Chaopaknam","avatar":""},{"name":"Kornpassorn Ratanameathanont","avatar":""},{"name":"Neennara Boonnithipaisit","avatar":""},{"name":"Alina M. Chang","avatar":""},{"name":"Pananyakorn Limvilairattana","avatar":""},{"name":"Punyanan Limvilairattana","avatar":""},{"name":"Phichai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["แฟลต เกิร์ล ชั้นห่างระหว่างเรา","Chan Hang Rawang Rao","Flat Girls: គម្លាតរវាងយើង","団地少女","平行青春的我们","แฟลตเกิร์ล ชั้นห่างระหว่าง เ ร า"]', 1784690324154);
