INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-bao-ve-cong-ly', 'Người Bảo Vệ Công Lý', 'Jaat', 'https://phimimg.com/upload/vod/20250613-1/9c35b850c3be45d5df14b0dfd106d246.jpg', 'https://phimimg.com/upload/vod/20250613-1/b5eddbcdddea6baf7704e89cf7f161b9.jpg', '<p>Phim xoay quanh cuộc chiến giữa thiện và ác. Một bên là Ranatunga: tội phạm khét tiếng, tàn nhẫn, lợi dụng quyền lực và vàng để đàn áp dân lành. Bên kia là “Jaat”, vị khách bí ẩn sắt đá, đến để đòi một lời xin lỗi và đem lại hy vọng cho người dân bị áp bức.</p>', 'Full', 1, 'single', 'completed', 18, 2025, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Sunny Deol","avatar":""},{"name":"Randeep Hooda","avatar":""},{"name":"Saiyami Kher","avatar":""},{"name":"Regina Cassandra","avatar":""},{"name":"Vineet Kumar Singh","avatar":""},{"name":"Ramya Krishnan","avatar":""},{"name":"Jagapati Babu","avatar":""},{"name":"Vinay Varma","avatar":""},{"name":"Zarina Wahab","avatar":""},{"name":"Upendra Limaye","avatar":""},{"name":"Urvashi Rautela","avatar":""},{"name":"Inaya Sultana","avatar":""},{"name":"Divi Vadthya","avatar":""},{"name":"Bandhavi Sridhar","avatar":""},{"name":"Ayesha Khan","avatar":""},{"name":"Makrand Deshpande","avatar":""},{"name":"Pranee","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["无敌贾特","贾特傲骨","开挂老大爷","正义秘密客","正义过客","Дерзкий","जाट"]', 1784690324154);
