INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-dai-cua-chung-ta', 'Thời đại của chúng ta', 'Our Times', 'https://phimimg.com/upload/vod/20250613-1/443016620043c12b773ffabb9b03b68c.jpg', 'https://phimimg.com/upload/vod/20250613-1/75e93e143fc95d42178a597e0b2586e0.jpg', '<p>Bước đột phá khoa học của vợ chồng Nora và Héctor cho phép họ du hành thời gian từ năm 1966 đến 2025. Trong khi Héctor chật vật thì Nora phát triển rực rỡ, nhưng với cái giá nào?</p>', 'Full', 1, 'single', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Mexico', 0, '[{"name":"Lucero","avatar":""},{"name":"Benny Ibarra","avatar":""},{"name":"Renata Vaca","avatar":""},{"name":"Ofelia Medina","avatar":""},{"name":"Alejandro Ávila","avatar":""},{"name":"Lore Graniewicz","avatar":""},{"name":"Mario Alberto Monroy","avatar":""},{"name":"Ana Ortizharo","avatar":""},{"name":"Claudia Lobo","avatar":""},{"name":"Enrique Singer","avatar":""},{"name":"Berenice Jonguitud","avatar":""},{"name":"Hugo Albores","avatar":""},{"name":"Guadalupe Damián","avatar":""},{"name":"Carolina Villamil","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Les temps changent","Nuestros tiempos - Il futuro è ora","Nuestros tiempos"]', 1784690324154);
