INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoe-truoc-yeu-sau', 'Khỏe Trước Yêu Sau', 'Pump Up The Healthy Love', 'https://phimimg.com/upload/vod/20250501-1/6f53fc626c96026938a105dc4bd07dd3.jpg', 'https://phimimg.com/upload/vod/20250501-1/62e0f5b557cd8c498d838fc171e8b9b4.jpg', '<p>Từng là một vận động viên thể hình nổi tiếng, Do Hyun Joong hiện nay đã trở thành quản lý của một phòng gym nhỏ với quyết tâm lan tỏa tinh thần tập luyện đến mọi người. Còn Lee Mi Ran là một nhân viên công ty du lịch có tâm hồn ăn uống. Sau khi chia tay với bạn trai, cô bắt đầu đến tập luyện ở phòng tập của Hyun Joong và giữa hai người dần dần nảy sinh tình cảm. Bộ phim hứa hẹn sẽ mang đến những thông điệp ý nghĩa và tích cực về sự tự tin và khởi đầu mới.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Jun-young","avatar":""},{"name":"Jung Eun-ji","avatar":""},{"name":"Kim Kwon","avatar":""},{"name":"Lee Mi-do","avatar":""},{"name":"Lee Seung-woo","avatar":""},{"name":"Park Seong-yeon","avatar":""},{"name":"Hong Yun-hwa","avatar":""},{"name":"Jung Wook-jin","avatar":""},{"name":"Nam Kyu-hee","avatar":""},{"name":"Lee Sang-jin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["24小时健身房","24小时健身俱乐部","24小時健身俱樂部","24-Hour Health Club","Pump Up the Healthy Love","24시 헬스클럽"]', 1784690324154);
