INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('do-danh-vo-yeu', 'Dỗ Dành Vợ Yêu', 'Coaxing My Beloved Wife', 'https://phimimg.com/upload/vod/20250516-1/9c4243b249d8c02cb5ed31177d24ccb4.jpg', 'https://phimimg.com/upload/vod/20250516-1/e27dea3744024d943ef3dacc78937f88.jpg', '<p>Ngọc Diệp - mẹ đơn thân nuôi con sau khi tình một đêm với người đàn ông lạ mặt. Cô không hề hay biết rằng người đó chính là Tùng Lâm, tổng giám đốc lạnh lùng. Khi số phận đưa họ gặp lại, tình yêu dần nhen nhóm nhưng cũng đầy rẫy âm mưu từ kẻ thứ ba – Nhã Đan, người không từ thủ đoạn kể cả hại cả con của Ngọc Diệp. Vì để có tiền cứu con, Ngọc Diệp chấp nhận làm trợ lý cho Tùng Lâm, bất chấp hiểm nguy luôn rình rập. Liệu tình yêu có đủ lớn để vượt qua tất cả khi sự thật dần được phơi bày?</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Nhâm Phương Nam","avatar":""},{"name":"Đàm Phương Linh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324154);
