INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mong-me-doi-doi', 'Mong Mẹ Đổi Đời', 'Threading Mom''s Wings', 'https://phimimg.com/upload/vod/20250602-1/8825fb1a1aef557124663fefc07fa4ee.jpg', 'https://phimimg.com/upload/vod/20250602-1/53319aca4dc6f16dc4ccb32cdf80400d.jpg', '<p>Cận Hiểu Vãn bị bạn trai phản bội và gặp tai nạn xe, trọng sinh trở về năm 1999, hóa thân thành một thần đồng năm tuổi. Nhờ vào ký ức từ thời hiện đại, cô bé đã giúp mẹ mình là Lâm Hàm thoát khỏi gã đàn ông tồi tệ, thành công giúp mẹ trở thành phú bà, đồng thời còn tác thành cho tình cảm của mẹ với Ưng Huy Minh. Sau một vài lần tiếp xúc, cô bé kinh ngạc phát hiện ra mẹ mình cũng là người trọng sinh, bèn quyết định phải mang lại một cuộc sống tốt đẹp hơn cho mẹ, nào ngờ từ lâu mẹ cô đã có kế hoạch của riêng mình…</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tuyên Lộ","avatar":""},{"name":"Kim Trạch","avatar":""},{"name":"Kiều Họa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wang Mu Cheng Feng","望母成凤"]', 1784690324154);
