INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('va-cham-2025', 'Va Chạm', 'Clash', 'https://phimimg.com/upload/vod/20250611-1/614147b96e968698717c26f73b267cff.jpg', 'https://phimimg.com/upload/vod/20250611-1/9926a88386c84320dd71ff169330b688.jpg', '<p>Anh giao hàng Lưu Dũng Cảm, người được mệnh danh là “Bolt của Sa Bình Bá”, đã tập hợp 30 anh em cùng chí hướng, lập nên một đội bóng bầu dục nghiệp dư mang tên “Công Nhân Bến Cảng”. Từ những kẻ bị coi thường, họ từng bước lội ngược dòng, vượt qua mọi khó khăn và cuối cùng đánh bại đội mạnh Liên Quân Quốc Tế Dũng Sĩ, xuất sắc giành chức vô địch Cúp Vĩnh Hằng.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Jiuxiao","avatar":""},{"name":"Wang Qianyuan","avatar":""},{"name":"Pan Binlong","avatar":""},{"name":"Yang Haoyu","avatar":""},{"name":"Liang Chao","avatar":""},{"name":"Shang Yuxian","avatar":""},{"name":"Zuo Ye","avatar":""},{"name":"Pierre Bourdaud","avatar":""},{"name":"Su Jinyuan","avatar":""},{"name":"Liang Jing","avatar":""},{"name":"Li Xueqin","avatar":""},{"name":"Liang Long","avatar":""},{"name":"Matt William Knowles","avatar":""},{"name":"Dai Lele","avatar":""},{"name":"Hu Xiaoguang","avatar":""},{"name":"Jiang Shimeng","avatar":""},{"name":"Zhang Baiqiao","avatar":""},{"name":"Ye Tian","avatar":""},{"name":"Wang Tianfang","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["冲撞","冲·撞"]', 1784690324154);
