INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xa-nu-2025', 'Xà Nữ', 'Snake Woman', 'https://phimimg.com/upload/vod/20250611-1/2d42ea5d69a50f5c894161da395380c1.jpg', 'https://phimimg.com/upload/vod/20250611-1/db7bc3e3d28d759fd375628454316dc9.jpg', '<p>Tại một thị trấn Đông Nam Á, rừng thiêng đồn đại có Xà Nữ nuốt chửng kẻ dám xâm phạm. Ông trùm xưởng rắn Xà Gia bất chấp cảnh báo, tự mình dẫn đoàn vào rừng và gặp phải sự tấn công của Xà Nữ. Anh trai Trần Sổ hy sinh thảm khốc trong chuyến đi này. Để thay anh trai bái thù, Trần Sổ gia nhập đội của Xà Gia, lại lần nữa vào núi, hiểm nguy rình rập. Trong chuyến đi này, Trần Sổ dần phát hiện ra kẻ giết anh không phải Xà Nữ, mà sự thật lại là...</p>', 'Full', 1, 'single', 'completed', 4, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Liu Lincheng","avatar":""},{"name":"Jin Yangyang","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["She Nv","الفتاة الثعبان","The Snake Girl","Maotüdruk","사녀","蛇女"]', 1784690324154);
