INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-nghiep-du', 'Tay Nghiệp Dư', 'The Amateur', 'https://phimimg.com/upload/vod/20250611-1/1e047c434e0adec363f3911973437b4e.jpg', 'https://phimimg.com/upload/vod/20250611-1/79a036ecc9a8aa63dbd0043bd1d7b942.jpg', '<p>Theo chân một nhà mật mã học của CIA, người đã tống tiền cơ quan của anh ta để thả anh ta ra truy đuổi một nhóm khủng bố đã giết vợ anh ta ở London.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Rami Malek","avatar":""},{"name":"Holt McCallany","avatar":""},{"name":"Danny Sapani","avatar":""},{"name":"Rachel Brosnahan","avatar":""},{"name":"Michael Stuhlbarg","avatar":""},{"name":"Laurence Fishburne","avatar":""},{"name":"Julianne Nicholson","avatar":""},{"name":"Caitríona Balfe","avatar":""},{"name":"Jon Bernthal","avatar":""},{"name":"Adrian Martinez","avatar":""},{"name":"Evan Milton","avatar":""},{"name":"Nick Mills","avatar":""},{"name":"Tiffany Gray","avatar":""},{"name":"Kate Sumpter","avatar":""},{"name":"David Mills","avatar":""},{"name":"Anita Anand","avatar":""},{"name":"Ryan Chil","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Amateur","アマチュア","ร้ายสมัครเล่น","L''amateur","//:THEAMATEUR/","Amatori","The Amateur"]', 1784690324154);
