INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-hoa-kien-dot-bien', 'Thảm Họa Kiến Đột Biến', 'Ant Mutation Crisis', 'https://phimimg.com/upload/vod/20250610-1/3e87efc84afdcd142b0f631784e33fba.jpg', 'https://phimimg.com/upload/vod/20250610-1/699134697f03879d4cdb0d3011a4f797.jpg', '<p>Nhà sinh vật học Hồ Sóc vì muốn cứu con trai khiếm khuyết gen, đã nghiên cứu cách cải thiện gen người bằng gen kiến, nhưng bị tất cả mọi người phản đối, ngay cả vợ anh, Lưu Hạnh Chi, cũng rời bỏ anh. Hoàng Cẩm Hùng, vì mắc bệnh, đã tài trợ cho nghiên cứu này. Trong một lần tham quan phòng thí nghiệm, kiến chúa bất ngờ trốn thoát và biến dị, dẫn đàn kiến tấn công mọi người. Cơ thể của Hồ Sóc và Hoàng Cẩm Hùng cũng bắt đầu biến hóa thành kiến. Cuối cùng, Lưu Hạnh Chi đã phong tỏa và cho nổ phòng thí nghiệm, ngăn chặn thảm họa lan rộng.</p>', 'Full', 1, 'single', 'completed', 4, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xing Yu","avatar":""},{"name":"Peng Jing","avatar":""},{"name":"Thomas Fiquet","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["蚁型危机"]', 1784690324154);
