INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-do-ho-tham', 'Thần Đô Hồ Thám', 'Shendu Fox Detective', 'https://phimimg.com/upload/vod/20250523-1/4f2e58ead1fa9af2b3eaf1b800546cd7.jpg', 'https://phimimg.com/upload/vod/20250523-1/ff93013d79b6b699bcd35a78f3d936d7.jpg', '<p>Thành Lạc Dương liên tiếp xảy ra nhiều vụ án giết người hàng loạt, nạn nhân đều là những thiếu nữ xuân thì. Trong phút chốc, cả thành bao trùm trong nỗi sợ hãi. Đại Lý Tự Thừa Hồ Chính Nghĩa nhận lệnh lúc nguy nan để truy tìm chân tướng. Thiếu niên giang hồ Lý Kiếm Tinh, vì muốn tìm ra sự thật của vụ án gia tộc bị diệt môn nên cố ý tiếp cận Hồ Chính Nghĩa... Phượng hoàng giết người, cô dâu hình nhân gỗ, từng vụ án kỳ lạ khó lường nối tiếp nhau. Một nhóm bằng hữu cùng kề vai sát cánh phiêu lưu, từ chỗ nghi ngờ lẫn nhau đến chỗ cùng chung hoạn nạn, sống chết có nhau.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ấn Tiểu Thiên","avatar":""},{"name":"Dương Nghiệp Minh","avatar":""},{"name":"Vương Tử Phi","avatar":""},{"name":"Phạm Mộng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["신도호탐: 가면속의 진실","神都狐探"]', 1784690324154);
