INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-dong-vat-phan-5', 'Thám Tử Động Vật (Phần 5)', 'The Creature Cases (Season 5)', 'https://phimimg.com/upload/vod/20250610-1/0d30161302389112696eb6465a3b58d2.jpg', 'https://phimimg.com/upload/vod/20250610-1/62897087c9910c1787f8b00cb71a71b0.jpg', '<p>Các đặc vụ Sam và Kit vi vu khắp thế giới cùng kỹ năng trinh thám, kiến thức khoa học và thiết bị hay ho để phá giải vô số bí ẩn của vương quốc động vật.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Nneka Okoye","avatar":""},{"name":"Shash Hira","avatar":""}]', '[{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["动物谜案","동물 탐정단","동물탐정단","The Creature Cases"]', 1784690324154);
