INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-thu-vo-hinh-sat-thu-diet-sat-thu', 'Quái Thú Vô Hình: Sát Thủ Diệt Sát Thủ', 'Predator: Killer of Killers', 'https://phimimg.com/upload/vod/20250608-1/d9778f414cd5b51b32799c33e1063875.jpg', 'https://phimimg.com/upload/vod/20250608-1/eb44ad3e4a1b63467d83024081a84d86.jpg', '<p>Predator: Killer of Killers là phim hoạt hình viễn tưởng hành động, gồm ba câu chuyện riêng biệt ở ba thời kỳ khác nhau, nơi các chiến binh huyền thoại đối đầu với loài Predator: Viking: Nữ chiến binh Ursa cùng con trai trả thù cho cái chết của người thân, nhưng bị Predator tấn công. Cô tiêu diệt được quái vật, nhưng mất con.Nhật Bản thời phong kiến: Hai anh em ninja Kenji và Kiyoshi từ đối đầu trở thành đồng minh để cùng hạ sát một Predator. Kiyoshi hy sinh.Thế chiến II: Phi công Torres khám phá ra tàu vũ trụ Predator giữa Đại Tây Dương và dùng chính công nghệ của chúng để tiêu diệt con tàu.Sau đó, cả ba được Predator bắt đưa đến hành tinh của chúng, nơi họ bị buộc chiến đấu sinh tồn trong đấu trường. Họ hợp sức giết Predator Warlord, nhưng Ursa hy sinh để cứu hai người còn lại.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lindsay LaVanchy","avatar":""},{"name":"Louis Ozawa","avatar":""},{"name":"Rick Gonzalez","avatar":""},{"name":"Michael Biehn","avatar":""},{"name":"Doug Cockle","avatar":""},{"name":"Damien C. Haas","avatar":""},{"name":"Lauren Holt","avatar":""},{"name":"Jeff Leach","avatar":""},{"name":"Cherami Leigh","avatar":""},{"name":"Alessa Luz Martinez","avatar":""},{"name":"Piotr Michael","avatar":""},{"name":"Andrew Morgado","avatar":""},{"name":"Brock Powell","avatar":""},{"name":"Felix Solis","avatar":""},{"name":"Britton Watkins","avatar":""},{"name":"Alex Albrecht","avatar":""},{"name":"James Bannon","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["المفترس: قاتل القتلة","Predátor: Zabiják zabijáků","Predator - Killer of Killers","Սպանողներին սպանողը","Predator Killer of Killers","Predator, Killer of Killers","Predador: Assassino de Assassinos","Predator: Killer of Killers"]', 1784690324154);
