INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-hoa-nhuoc-cam', 'Thiều Hoa Nhược Cẩm', 'Youthful Glory', 'https://phimimg.com/upload/vod/20250519-1/5a11177fe7bf3d9e7a40c3aa0c21e5e6.jpg', 'https://phimimg.com/upload/vod/20250519-1/168d93b4029d4038e06d38c0ec25164a.jpg', '<p>Thiều Hoa Nhược Cẩm kể về câu chuyện tình yêu của Minh Đàn, con gái của Tĩnh An hầu phủ và Giang Tự - chiến thần của Đại Hiển. Minh Đàn được ban hôn cho Giang Tự, nhưng sợ chàng là kẻ thô tục nên mới tìm cách lẻn vào quân doanh để xem mặt phu quân tương lai. Thế nhưng nàng không ngờ bản thân vừa gặp đã yêu. Giang Tự và Minh Đàn sau khi thành hôn bắt đầu trải qua mối tình nhiều ngọt ngào nhưng cũng lắm hoạn nạn, cuối cùng từ trong gian khó bồi đắp nên chân tình, cảm nhận được thế nào là hạnh phúc đích thực.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 9, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tống Uy Long","avatar":""},{"name":"Bao Thượng Ân","avatar":""},{"name":"Đại Lộ Oa","avatar":""},{"name":"Kha Oánh","avatar":""},{"name":"Bạch Thự","avatar":""},{"name":"Tần Hiểu Huyên","avatar":""},{"name":"Vương Khả","avatar":""},{"name":"Toàn Y Luân","avatar":""},{"name":"Dương Bác Tiêu","avatar":""},{"name":"Tôn Tổ Quân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Glória da Juventude","小豆蔻","Shao Hua Ruo Jin","韶华若锦","กระวานน้อยแรกรัก","Youthful Beauty"]', 1784690324154);
