INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ga-nham-the-tu-phi', 'Gả Nhầm Thế Tử Phi', 'Destiny Of Love', 'https://phimimg.com/upload/vod/20250528-1/e4f719a01269d21fccdee1480f7e707c.jpg', 'https://phimimg.com/upload/vod/20250528-1/b7fee4ddf996e75e27eb7af3711eebec.jpg', '<p>Kiều Man Man, chưởng quầy Vạn Sự Phường tinh quái, được giao nhiệm vụ phá hoại hôn sự với nước Tây Lân. Giữa cô và Phó Thừa Cẩn, người giả vờ què để tránh cuộc tranh giành ngôi vị thái tử liên tục xảy ra hiểu lầm dở khóc dở cười, tình cảm âm thầm nảy nở, nhưng lại gặp cản trở về thân thế và cuộc chiến tranh giành ngôi vua, liệu tình cảm của họ sẽ đi về đâu?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Quan Hồng","avatar":""},{"name":"Hoàng Nhật Oánh","avatar":""},{"name":"Uông Trác Thành","avatar":""},{"name":"Tống Tiêu Anh Tử","avatar":""},{"name":"Lưu Niệm","avatar":""},{"name":"Lưu Dận Quân","avatar":""},{"name":"Lý Minh Tuấn","avatar":""},{"name":"Lý Canh Vân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["착가세자비 : 어쩌다 천생연분","错嫁世子妃"]', 1784690324154);
