INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cach-tao-ra-phep-thuat-o-the-gioi-khac', 'Cách Tạo Ra Phép Thuật Ở Thế Giới Khác', 'Magic Maker: How To Make Magic In Another World', 'https://phimimg.com/upload/vod/20250608-1/a6d754c8098938122ebe285438d65629.jpg', 'https://phimimg.com/upload/vod/20250608-1/718bfa7f9009b5e6b2f82968e48fd4d7.jpg', '<p>Vào đêm sinh nhật lần thứ 30, một người đàn ông bất ngờ qua đời — và ước mơ cả đời được sử dụng phép thuật của anh cuối cùng cũng thành hiện thực. Anh tỉnh dậy trong hình hài của Sion, một cậu bé ở một thế giới khác. Anh và người chị gái Marie là con của một gia đình quý tộc cấp thấp, cai quản một vùng đất nhỏ. Sau khi nhận được những lời dặn dò mâu thuẫn từ người cha, Sion và Marie đã cùng nhau bắt đầu chuyến phiêu lưu nhằm khám phá sức mạnh phép thuật và những bí ẩn đang bị che giấu.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Megumi Han","avatar":""},{"name":"Ai Kakuma","avatar":""},{"name":"Sora Amamiya","avatar":""},{"name":"Yu Serizawa","avatar":""},{"name":"Aoi Koga","avatar":""},{"name":"Naoya Miyase","avatar":""},{"name":"Mitsuru Miyamoto","avatar":""},{"name":"Megumi Toyoguchi","avatar":""},{"name":"Masayuki Akasaka","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["魔法制造者 ～异世界魔法的制作方法～","魔法制造者","Magic Maker: Isekai Mahou no Tsukurikata","Majikku Meikā: Isekai Mahō no Tsukurikata","Magic Maker","매직·메이커 -이세계 마법을 만드는 법-","How to Perform Alternate World Magic","マジック・メイカー ～異世界魔法の作り方～"]', 1784690324154);
