INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('barracuda-queens-phan-2', 'Barracuda Queens (Phần 2)', 'Barracuda Queens (Season 2)', 'https://phimimg.com/upload/vod/20250608-1/eef310fff0c538452418baa1a1729f23.jpg', 'https://phimimg.com/upload/vod/20250608-1/071b2a70cd0e9a1cee424d9855a0389c.jpg', '<p>Lâm vào cảnh nợ nần chồng chất, một nhóm phụ nữ trẻ ở vùng ngoại ô Stockholm giàu có bèn cướp các nhà hàng xóm. Loạt phim dựa trên sự kiện có thật.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 23, 2025, 'Vietsub', 'FHD', 'Thụy Điển', 0, '[{"name":"Alva Bratt","avatar":""},{"name":"Tindra Monsen","avatar":""},{"name":"Sandra Zubovic","avatar":""},{"name":"Sarah Gustafsson","avatar":""},{"name":"Tea Stjärne","avatar":""},{"name":"Mirja Turestedt","avatar":""},{"name":"Johannes Kuhnke","avatar":""},{"name":"Izabella Scorupco","avatar":""},{"name":"Carsten Bjørnlund","avatar":""},{"name":"Max Ulveson","avatar":""},{"name":"Michaela Thorsén","avatar":""},{"name":"Laila Khalil","avatar":""},{"name":"Gino Estéra","avatar":""},{"name":"Christian Fandango Sundgren","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Barracuda Queens"]', 1784690324154);
