INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-than-tuyet-voi-nhat-cua-nu-than', 'Bạn Thân Tuyệt Vời Nhất Của Nữ Thần', 'Best Goddess BFF', 'https://phimimg.com/upload/vod/20250608-1/813c051439339ee79ce83909a1a39de1.jpg', 'https://phimimg.com/upload/vod/20250608-1/5cd885083214cee38718fb43cc81e699.jpg', '<p>Bạch Hiểu Phi, một người phụ nữ thông minh, bản lĩnh trong giới công sở, bị trả thù sau khi tố giác một vụ lừa đảo tài chính. Tằng Thanh Thanh, cô gái trẻ mới bước chân vào môi trường làm việc, bị khách hàng chuốc rượu và quấy rối trong một buổi tiệc tiếp khách. Khi tuyệt vọng muốn kết liễu cuộc đời, cô đã được Bạch Hiểu Phi cứu sống. Từ đó, hai người trở thành tri kỷ và quyết định cùng nhau khởi nghiệp, sát cánh vượt qua sóng gió thương trường. Họ không chỉ giúp Công ty Giải trí Phổ Hoa giải quyết khủng hoảng truyền thông, mà còn vạch trần chân tướng vụ lừa đảo tài chính, giành được niềm tin và sự tôn trọng từ khách hàng. Tuy nhiên, con đường khởi nghiệp của họ không hề bằng phẳng. Bạch Hiểu Phi bị người chú của mình – vốn có ân oán cũ – gây khó dễ, thậm chí đập phá công ty. Tằng Thanh Thanh cũng đối mặt với nhiều thử thách và vấp ngã. Trải qua bao sóng gió, cả hai dần trưởng thành, trở thành những người phụ nữ kiên cường và chín chắn hơn.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hu Yue","avatar":""},{"name":"He Yunwei","avatar":""},{"name":"Dong Xuanyu","avatar":""},{"name":"Li Yimu","avatar":""},{"name":"Yuan Mingze","avatar":""},{"name":"Tang Duo''er","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Zui Jia Nv Shen Gui Mi","最佳女神闺蜜"]', 1784690324154);
