INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khom-lung', 'Khom Lưng', 'The Prisoner Of Beauty', 'https://phimimg.com/upload/vod/20250513-1/edc97b789edd9c655c8d3d485cd43816.jpg', 'https://phimimg.com/upload/vod/20250513-1/9c9253d007ed14c446daf7e39d240104.jpg', '<p>Khom Lưng khắc họa chuyện tình &quot;cưới trước yêu sau&quot; giữa tướng quân dũng mãnh Ngụy Thiệu và tiểu thư yếu thế Kiều Mạn. Dù luôn đau đáu mối thù diệt tộc, Ngụy Thiệu vẫn vì kế sinh nhai của muôn dân mà miễn cưỡng liên hôn với Kiều Mạn, con gái út của gia tộc trước kia từng phản bội Ngụy gia. Biết rõ đây chỉ là cuộc hôn nhân hữu danh vô thực, Kiều Mạn luôn sống vô cùng thận trọng và dè dặt ở Ngụy gia. Nhưng sau khi cùng nhau trải qua nhiều sóng gió, Kiều Mạn và Ngụy Thiệu dần bị thu hút bởi tài năng của nhau và nảy sinh tình cảm thật sự.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 15, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tống Tổ Nhi","avatar":""},{"name":"Lưu Vũ Ninh","avatar":""},{"name":"Tuyên Lộ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Prisioneiros da beleza","Zhe Yao","折腰","电视剧折腰","ปรปักษ์จำนน","The Prisoner Of Beauty"]', 1784690324154);
