INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-dung-thu', 'Không Dung Thứ', 'Mercy for None', 'https://phimimg.com/upload/vod/20250607-1/576158a9b33a9a4845e93c208c488b8a.jpg', 'https://phimimg.com/upload/vod/20250607-1/26b59ff087c2a72dae47e153c3b05d36.jpg', '<p>Sau khi cắt đứt quan hệ với băng đảng, tay giang hồ gác kiếm nọ quay lại để khám phá sự thật đằng sau cái chết của em trai – bước vào con đường báo thù không khoan nhượng.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 34, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"So Ji-sub","avatar":""},{"name":"Huh Joon-ho","avatar":""},{"name":"Gong Myoung","avatar":""},{"name":"Choo Young-woo","avatar":""},{"name":"An Kil-kang","avatar":""},{"name":"Cho Han-cheul","avatar":""},{"name":"Lee Jun-hyuk","avatar":""},{"name":"Cha Seung-won","avatar":""},{"name":"Lee Beom-soo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["광장"]', 1784690324154);
