INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-kham-chi', 'Thanh Khâm Chí', 'A Prime Minister''s Disguise', 'https://phimimg.com/upload/vod/20250527-1/5bb897af1c962f376213c2f4c9547e67.jpg', 'https://phimimg.com/upload/vod/20250527-1/5571d408880015c0a2cf28aa300f7ac0.jpg', '<p>Sau khi hậu Ninh vừa định đô, tân đế Hoắc Cảnh Hành tuyển chọn phi tần, triệu em gái của cựu thừa tướng tiền triều Nhạc Trì (đã mất tích hai năm) là Nhạc Linh Nhi vào cung. Lo lắng em gái bị o ép, Nhạc Trì không nỡ để cô vào cung. Đồng thời, do Hoắc Cảnh Hành gần đây thường xuyên để ý đến người và sự kiện tiền triều, ông sợ Hoắc Cảnh Hành sẽ thanh trừng cựu thần, nên quyết định thay em gái vào cung dò xét tình hình. Tuy nhiên, tất cả đều là kế hoạch của Nhạc Linh Nhi và Hoắc Cảnh Hành, mượn danh nghĩa tuyển phi để dụ Nhạc Trì vào cung, giúp ông trở lại chính trường. Trong cung, Nhạc Trì dùng trí tuệ vượt qua mọi hiểm nguy, còn Hoắc Cảnh Hành thông qua các mưu kế như vu tội quốc cữu thất trách, từng bước đưa vị trọng thần tài năng Nhạc Trì lên chức Hữu tướng. Dù hai người vì sự ly gián của công chúa Giang Vân Khinh tiền triều mà sinh hiềm khích, nhưng sau đó lại cùng nhau chống lại âm mưu của thái tử Ly Quốc Dịch Thanh Vân, trải qua sinh tử và giải quyết được loạn trong giặc ngoài.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Duệ Xương","avatar":""},{"name":"Lý Tử Huyên","avatar":""},{"name":"Tạ Hưng Dương","avatar":""},{"name":"Cung Uyển Di","avatar":""},{"name":"Vương Giai Huệ","avatar":""},{"name":"Ngao Bác","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["青今志","青衿志"]', 1784690324154);
