INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-biet-trai-dat-phan-2', 'Tạm Biệt, Trái Đất (Phần 2)', 'Bye Bye, Earth (Season 2)', 'https://phimimg.com/upload/vod/20250421-1/9139c52dc6badfdacf8ebb5615a858c2.jpg', 'https://phimimg.com/upload/vod/20250421-1/6ee74b004ce3a55b19cdfbb056f80ee2.jpg', '<p>Trong thế giới tồn tại những động vật hình người, Belle Lablac là con người duy nhất được sinh ra. Không có răng nanh, lông, hay vảy, cậu bị gọi là &quot;Faceless&quot; và sống một cuộc đời cô độc vì không có ai có thể đồng cảm với mình. &quot;Tôi muốn trở thành một phần của thế giới này...&quot; Với niềm khao khát đó trong lòng, cậu quyết định lên đường tìm kiếm nguồn gốc của mình, mang theo một thanh đại kiếm cao bằng cô, Runding. Không biết có bao nhiêu thử thách đang chờ đợi cô trên hành trình này...</p>', 'Tập 10', 12, 'hoathinh', 'ongoing', 5, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324154);
