INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('goc-khuat-phim-le-2025', 'Góc Khuất', 'Sharp Corner', 'https://phimimg.com/upload/vod/20250606-1/648763a851cb29ad6b0d5905d23ad91b.jpg', 'https://phimimg.com/upload/vod/20250606-1/a352b95f2cf321329026ffced300cb76.jpg', '<p>Josh McCall, một người đàn ông tận tụy với gia đình, cùng vợ Rachel và con trai Max chuyển đến ngôi nhà mơ ước ở vùng nông thôn. Tuy nhiên, niềm vui nhanh chóng tan biến khi họ phát hiện ngôi nhà nằm gần một khúc cua nguy hiểm, nơi thường xuyên xảy ra tai nạn chết người.
 Bị ám ảnh bởi những vụ tai nạn, Josh dần trở nên ám ảnh với việc cứu giúp các nạn nhân. Anh tham gia các khóa học sơ cứu, mua thiết bị y tế và thậm chí đến dự đám tang của các nạn nhân. Sự ám ảnh này khiến anh xa cách vợ con và dần mất kiểm soát bản thân.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Ben Foster","avatar":""},{"name":"Cobie Smulders","avatar":""},{"name":"William Kosovic","avatar":""},{"name":"Gavin Drea","avatar":""},{"name":"Alexandra Castillo","avatar":""},{"name":"Jonathan Watton","avatar":""},{"name":"Reid Price","avatar":""},{"name":"Andrew Shaver","avatar":""},{"name":"Mark A. Owen","avatar":""},{"name":"Dan Lett","avatar":""},{"name":"Julia Dyan-Porter","avatar":""},{"name":"Leah Johnston","avatar":""},{"name":"Allison Wilson-Forbes","avatar":""},{"name":"Wayne Burns","avatar":""},{"name":"Bob Mann","avatar":""},{"name":"Sam Vigneault","avatar":""},{"name":"Alexandra McDon","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Sharp Corner"]', 1784690324154);
