INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bai-hoc-tu-chu-chim-canh-cut', 'Bài Học Từ Chú Chim Cánh Cụt', 'The Penguin Lessons', 'https://phimimg.com/upload/vod/20250607-1/f4630a08021aa224d1bb61242a437572.jpg', 'https://phimimg.com/upload/vod/20250607-1/0a950dc47f8df2a7cb72002fe4f1933a.jpg', '<p>Tom Michell đến dạy học ở Argentina, khi quê nhà ông đang đảo chính quân sự. Ông vô tình cứu chú chim cánh cụt và đặt tên Juan Salvador. Nhờ Juan, Tom dần kết nối lại với mọi người và cả chính mình.</p>', 'Full', 1, 'single', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Steve Coogan","avatar":""},{"name":"Jonathan Pryce","avatar":""},{"name":"Vivian El Jaber","avatar":""},{"name":"Björn Gustafsson","avatar":""},{"name":"Alfonsina Carrocio","avatar":""},{"name":"David Herrero","avatar":""},{"name":"Micaela Breque","avatar":""},{"name":"Tomás Pozzi","avatar":""},{"name":"Ramiro Blas","avatar":""},{"name":"Juan Barreiro","avatar":""},{"name":"Aimar Miranda","avatar":""},{"name":"Nicanor Fernandez","avatar":""},{"name":"Hugo Fuertes","avatar":""},{"name":"Bruno Blas","avatar":""},{"name":"Julia Fossi","avatar":""},{"name":"Brendan McNamee","avatar":""},{"name":"Joaquín","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Lecciones De Un Pingüino","Lecciones de un pingüino","Der Pinguin meines Lebens","Mig og pingvinen","Minä ja pingviini","Pingvinen og professoren","Школа мистера Пингвина","Penguen Dersleri","企鹅课","我的企鹅老师","企鹅教我的事","ペンギン・レッスン","The Penguin Lessons"]', 1784690324154);
