INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-yeu-ma-cac-nha-si-khuyen-dung', 'Người Yêu Mà Các Nha Sĩ Khuyên Dùng', 'Sweet Tooth, Good Dentist', 'https://phimimg.com/upload/vod/20250324-1/899044209cf16474ce88172b7865f9c5.jpg', 'https://phimimg.com/upload/vod/20250324-1/bb3baff0d79119bdbd99b30a22a281b6.jpg', '<p>&quot;Sont&quot; (Ohm Thipakorn), một sinh viên đại học có niềm đam mê bất tận với đồ ngọt, đã trải qua cú sốc lớn nhất đời mình khi phát hiện ra mình bị sâu răng! Điều này buộc cậu phải tìm đến nha sĩ &quot;Jay&quot; (Mark Pakin), một chàng bác sĩ điển trai với vẻ ngoài lạnh lùng nhưng lại có tính cách kỳ quặc. Ban đầu, cả hai như nước với lửa, chẳng hòa hợp. Tuy nhiên, khi Sont tiếp tục điều trị, cậu dần tự hỏi liệu sự quan tâm của Jay chỉ đơn thuần là trách nhiệm của một nha sĩ, hay đằng sau đó còn ẩn chứa điều gì đặc biệt hơn?</p>', 'Tập 11', 12, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Pakin Kunaanuwit","avatar":""},{"name":"Thiphakorn Thitathan","avatar":""},{"name":"Jitaraphol Potiwihok","avatar":""},{"name":"Poon Mitpakdee","avatar":""},{"name":"Benyapa Jeenprasom","avatar":""},{"name":"Thitiwatchapol Suthabunditphong","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["甜蜜的牙医","牙医情人","Sweet Tooth, Good Dentist","The Boyfriend Recommended by Most Dentists","แฟนที่ทันตแพทย์ส่วนใหญ่แนะนำ"]', 1784690324154);
