INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-moi', 'Không Mời', 'Uninvited', 'https://phimimg.com/upload/vod/20250606-1/6fa84542d15c54c5ed90e032da74de0a.jpg', 'https://phimimg.com/upload/vod/20250606-1/008dd554c8340de4b730ae3bf49bf613.jpg', '<p>Âm mưu hạ bệ tên tỷ phú gây ra cái chết của con gái mình, người phụ nữ nọ cải trang thành một nhà tài trợ giàu có quyến rũ để tham dự bữa tiệc xa hoa của hắn.</p>', 'Full', 1, 'single', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Vilma Santos","avatar":""},{"name":"Aga Muhlach","avatar":""},{"name":"Nadine Lustre","avatar":""},{"name":"Tirso Cruz III","avatar":""},{"name":"Mylene Dizon","avatar":""},{"name":"Lotlot De Leon","avatar":""},{"name":"Elijah Canlas","avatar":""},{"name":"Gabby Padilla","avatar":""},{"name":"RK Bagatsing","avatar":""},{"name":"Ketchup Eusebio","avatar":""},{"name":"Gio Alvarez","avatar":""},{"name":"Cholo Barretto","avatar":""},{"name":"Ron Angeles","avatar":""},{"name":"Nonie Buencamino","avatar":""},{"name":"Dylan Ray Talon","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Uninvited"]', 1784690324155);
