INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-cuu-trong-con-thinh-no-giai-cuu-khan-cap', 'Giải Cứu Trong Cơn Thịnh Nộ (Giải Cứu Khẩn Cấp)', 'Angry Rescue', 'https://phimimg.com/upload/vod/20250606-1/03f40e0ef8c9c81a5e1223864df86fc0.jpg', 'https://phimimg.com/upload/vod/20250606-1/3e58178f32183f786db701f0ab1d3f56.jpg', '<p>Một công ty an ninh quốc tế cử Long Khiếu Hổ và đồng đội Cao Phong vận chuyển một sinh vật bí ẩn. Trên đường trở về, họ bất ngờ bị băng nhóm vũ trang chặn đánh. Trong hỗn loạn, tai nạn xảy ra, và Long Khiếu Hổ bị gán tội bắt cóc. Anh phải đối mặt với hiểu lầm chồng chất từ gia đình lẫn đồng nghiệp. Buộc phải ẩn thân suốt ba năm, cuối cùng anh cũng lần ra được manh mối của kẻ chủ mưu thực sự. Nhưng lúc này, anh lại bị truy đuổi ráo riết, bắt đầu hành trình truy tìm sự thật.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tiger Chen Hu","avatar":""},{"name":"Miya Muqi","avatar":""},{"name":"Basa","avatar":""},{"name":"Wu Jin Xi","avatar":""},{"name":"Bingo Zhou","avatar":""},{"name":"Yuan Zhong Yuan","avatar":""},{"name":"Qi Yujia","avatar":""},{"name":"Arbi Khasaev","avatar":""},{"name":"Sergey Panasyuk","avatar":""},{"name":"Dmytro Shypin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["怒火营救"]', 1784690324155);
