INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-danh-ke-toan-2', 'Mật Danh: Kế Toán 2', 'The Accountant 2', 'https://phimimg.com/upload/vod/20250605-1/d2c6c3d36b7b1541961a1543ba0f0075.jpg', 'https://phimimg.com/upload/vod/20250605-1/6c454fe03603c6539bec9fb601877f02.jpg', '<p>Khi một người quen cũ bị sát hại, Wolff buộc phải giải quyết vụ án. Nhận ra các biện pháp cực đoan hơn là cần thiết, Wolff tuyển dụng người anh trai ghẻ lạnh và rất nguy hiểm của mình, Brax, để giúp đỡ. Hợp tác với Đặc vụ Kho bạc Marybeth Medina, họ phát hiện ra một âm mưu chết người, trở thành mục tiêu của một mạng lưới những kẻ giết người tàn nhẫn, những người sẽ không dừng lại ở bất cứ điều gì để giữ bí mật của họ bị chôn vùi.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ben Affleck","avatar":""},{"name":"Jon Bernthal","avatar":""},{"name":"Cynthia Addai-Robinson","avatar":""},{"name":"J.K. Simmons","avatar":""},{"name":"Allison Robertson","avatar":""},{"name":"Alison Wright","avatar":""},{"name":"Daniella Pineda","avatar":""},{"name":"Robert Morgan","avatar":""},{"name":"Grant Harvey","avatar":""},{"name":"Andrew Howard","avatar":""},{"name":"Yael Ocasio","avatar":""},{"name":"Lombardo Boyar","avatar":""},{"name":"Michael Tourek","avatar":""},{"name":"Fernando Chien","avatar":""},{"name":"Abner Lozano","avatar":""},{"name":"Talia Thiesfield","avatar":""},{"name":"Pr","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Solomon","The Accountant 2","El contable²","El contable 2","רואה החשבון²","ดิ แอคเคาท์แทนต์ 2  อัจฉริยะคนบัญชีเพชฌฆาต","O Contador 2","The Accountant²"]', 1784690324155);
