INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-thien-kim-tai-ba', 'Lâm Thiên Kim Tài Ba', 'The Great Lin Qian Jin', 'https://phimimg.com/upload/vod/20250530-1/62aa7e055596adfe09621eecb407216e.jpg', 'https://phimimg.com/upload/vod/20250530-1/86819e0b82740ecd70af3fc24ec584d5.jpg', '<p>Lâm Thiên Kim xuyên không vào một cuốn sách cổ, trở thành hung thủ hạ độc. Dù cô có cố gắng minh oan cho mình thế nào, kẻ thù không đội trời chung là Lý Yến vẫn luôn đối đầu gay gắt. Bất đắc dĩ, cô phải khởi động chế độ &quot;cưa cẩm&quot; nhiệt tình, vừa điều tra vụ án vừa tán tỉnh Lý Yến. Nào ngờ, vụ án đầu độc lại vô cùng rối rắm, ai ai cũng có động cơ muốn giết cô! Dần dần, Lâm Thiên Kim đem lòng yêu Lý Yến, và hành trình tình yêu đầy éo le nhưng cũng không kém phần hài hước của cô gái này bắt đầu từ đó...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Húc Văn","avatar":""},{"name":"Vương Bội","avatar":""},{"name":"Nhiếp Tử Hạo","avatar":""},{"name":"Quan Sướng","avatar":""},{"name":"Khương Nhất Đoá","avatar":""},{"name":"Lưu Thừa Lâm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["了不起的林千金"]', 1784690324155);
