INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lam-thien-kim-tai-ba', 'Lâm Thiên Kim Tài Ba', 'The Great Lin Qian Jin', 'lâm thiên kim tài ba the great lin qian jin dương húc văn vương bội nhiếp tử hạo quan sướng khương nhất đoá lưu thừa lâm 了不起的林千金', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-giang-ho-chi-bat-luong-nhan-phan-7', 'Họa giang hồ chi bất lương nhân (Phần 7)', 'A Portrait of Jianghu: Bad Guys (Season 7) / The Degenerate-Drawing Jianghu 7', 'https://phimimg.com/upload/vod/20250412-1/cc39c6db04e2a58a121e89a1a0cb721e.jpg', 'https://phimimg.com/upload/vod/20250412-1/808531c4aabf0b86bc9948916ab7d5f3.jpg', '<p>Mạc Bắc thoạt nhìn yên ả, nhưng bên trong sóng ngầm cuộn trào. Vương hậu Thuật Lý Đoá âm thầm chuẩn bị một đại hội lớn. Bất Lương Soái dò la tin tức, dẫn Bất Lương Nhân đến đây. Cùng lúc, Tứ Đại Thi Tổ do Hàng Thần dẫn đầu mở quán lẩu ở Mạc Bắc. Một kẻ sát nhân bí ẩn gây hoang mang, buộc các thế lực phải vạch kế hoạch đối phó riêng.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jiang Bian","avatar":""},{"name":"Mengmeng Yan","avatar":""},{"name":"Zhao Yi","avatar":""},{"name":"Qiuxiang Shen","avatar":""},{"name":"Jun Chu","avatar":""},{"name":"Shuren Zhao","avatar":""},{"name":"Xuecen Bai","avatar":""},{"name":"Lu Zhixing","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["画江湖之不良人动画版","Huajianghu Bu Liang Ren","Buliang Ren VI","画江湖之不良人Ⅴ","Buliang Ren II","Buliang Ren V","Buliang Ren III","Buliang Ren IV","Buliang Ren","Drawing Jianghu Of Bu Liang Ren Ⅵ","Drawing Jianghu of Bu Liang Ren","Hua Jiang Hu Zhi Bu Liang Ren","The Degenerate-Drawing Jianghu","画江湖之不良人II","画江湖之不良人第七季：九幽玄天","画江湖之不良人","畫江湖之不良人","A Portrait of Jianghu Bad Guys","A Portrait of Jianghu : Bad Guys"]', 1784690324155);
