INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoa-giang-ho-chi-bat-luong-nhan-phan-7', 'Họa giang hồ chi bất lương nhân (Phần 7)', 'A Portrait of Jianghu: Bad Guys (Season 7) / The Degenerate-Drawing Jianghu 7', 'họa giang hồ chi bất lương nhân (phần 7) a portrait of jianghu: bad guys (season 7) / the degenerate-drawing jianghu 7 jiang bian mengmeng yan zhao yi qiuxiang shen jun chu shuren zhao xuecen bai lu zhixing 画江湖之不良人动画版 huajianghu bu liang ren buliang ren vi 画江湖之不良人ⅴ buliang ren ii buliang ren v buliang ren iii buliang ren iv buliang ren drawing jianghu of bu liang ren ⅵ drawing jianghu of bu liang ren hua jiang hu zhi bu liang ren the degenerate-drawing jianghu 画江湖之不良人ii 画江湖之不良人第七季：九幽玄天 画江湖之不良人 畫江湖之不良人 a portrait of jianghu bad guys a portrait of jianghu : bad guys', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ve-thoi-nao-thieu-nu-truyen-tranh', 'Vẽ Thôi Nào! Thiếu Nữ Truyện Tranh', 'The Comic Bang', 'https://phimimg.com/upload/vod/20250522-1/f213fa6002387a040d855e7c1b1b1e3e.jpg', 'https://phimimg.com/upload/vod/20250522-1/a61136ffc21889eac7f04e1a37f40b28.jpg', '<p>Tả Thiên Đại tỏ tình với nam sinh Diệp Kỳ, ai ngờ anh ta lại tặng cô một bản ký tay và dụ cô nàng trở thành trợ lý vẽ nét cho mình. Hóa ra Diệp Kỳ, vị học bá lạnh lùng lại là một họa sĩ truyện tranh nổi tiếng! Những ngày bị nhầm thành fan, Tả Thiên Đại đã bước chân vào thế giới truyện tranh của Diệp Kỳ, gặp gỡ một nhóm bạn đặc biệt và đầy sự nổi bật. Cùng với họ, cô đã trải qua những tình huống hài hước, đôi khi rơi vào những tình huống tiêu cực nhưng đầy sức mạnh. Giữa những thăng trầm của mối quan hệ của hai người, cả nhóm cũng dần tiến gần hơn đến ước mơ về việc vẽ truyện tranh của mình.</p>', 'Hoàn Tất (33/33)', 33, 'series', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Thẩm Nguyệt","avatar":""},{"name":"Vương Kính Huyền","avatar":""},{"name":"Chu Diễn Thần","avatar":""},{"name":"Tăng Khả Ni","avatar":""},{"name":"Ngô Vũ Hằng","avatar":""},{"name":"Triệu Dịch Khâm","avatar":""},{"name":"Vương Nhược Thiện","avatar":""},{"name":"Hác Thiệu Văn","avatar":""},{"name":"Trần Bách Dung","avatar":""},{"name":"Nhạc Dược Lợi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["月刊少女","夏日烟火","月刊少女野崎君","Yue Kan Shao Nv","Kai Hua Shao Nv Man","月刊少女野崎くん","Gekkan Shoujo Nozaki-kun","개화! 소녀만 : 그리자! 순정만화","Monthly Girls'' Nozaki-kun","Comic Girl Romance","开画！少女漫"]', 1784690324155);
