INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tang-hai-truyen', 'Tàng Hải Truyện', 'Legend Of Zang Hai', 'https://phimimg.com/upload/vod/20250518-1/5f941a7a41c7c14a0479f78145139d3d.jpg', 'https://phimimg.com/upload/vod/20250518-1/6c801c4a6ef5d709a47220f71a31dac6.jpg', '<p>&quot;Tàng Hải Truyện&quot; kể về con trai của quan Giám chính Khâm Thiên Giám Khoái Đạc, mang mối thù sâu như biển máu. Sau mười năm khổ luyện, anh lấy tên là Tàng Hải, vào kinh tìm kiếm sự thật, cuối cùng rửa được mối hận, trừng trị kẻ ác, bảo vệ lẽ phải và kiên trì theo đuổi công lý.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 8, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tiêu Chiến","avatar":""},{"name":"Trương Tịnh Nghi","avatar":""},{"name":"Châu Kỳ","avatar":""},{"name":"Hoàng Giác","avatar":""},{"name":"Dư Nam","avatar":""},{"name":"Trần Nghiên Hy","avatar":""},{"name":"Trương Quốc Cường","avatar":""},{"name":"Kiều Chấn Vũ","avatar":""},{"name":"Điền Tiểu Kiệt","avatar":""},{"name":"Sa Bảo Lượng","avatar":""},{"name":"Chung Hán Lương","avatar":""},{"name":"Hình Mẫn Sơn","avatar":""},{"name":"Lương Siêu","avatar":""},{"name":"Dương Vũ Đồng","avatar":""},{"name":"Thiệu Văn","avatar":""},{"name":"Dương Phàm","avatar":""},{"name":"Lưu Triều","avatar":""},{"name":"Vương Vận Chi","avatar":""},{"name":"Tống Nguyê","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["藏海戏麟","Zang Hai Zhuan","藏海传","ตำนานจั้งไห่","Legend of Zang Hai"]', 1784690324155);
