INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tang-hai-truyen', 'Tàng Hải Truyện', 'Legend Of Zang Hai', 'tàng hải truyện legend of zang hai tiêu chiến trương tịnh nghi châu kỳ hoàng giác dư nam trần nghiên hy trương quốc cường kiều chấn vũ điền tiểu kiệt sa bảo lượng chung hán lương hình mẫn sơn lương siêu dương vũ đồng thiệu văn dương phàm lưu triều vương vận chi tống nguyê 藏海戏麟 zang hai zhuan 藏海传 ตำนานจั้งไห่ legend of zang hai', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cat-vang-ngap-troi', 'Cát Vàng Ngập Trời', 'An Abundance of Dunes', 'https://phimimg.com/upload/vod/20250604-1/1983252e90f27437b08aadf0a348d6fe.jpg', 'https://phimimg.com/upload/vod/20250604-1/9abcbf685a0325b79dde51bbb5285c24.jpg', '<p>Tên lừa đảo Giả Nghị Chinh bị nhầm thành &quot;Đặc phái viên&quot; Quốc Dân đảng đến thị sát huyện Đồng Quan, sa vào âm mưu &quot;phản quốc đầu hàng Nhật&quot; của huyện trưởng Tạ Thiên Lý. Sau một hồi đấu trí đấu dũng đầy mưu mô và phản trắc, Tạ Thiên Lý bị chính Giả Nghị Chinh phản đòn và hạ gục. Đúng lúc đó, quân Nhật tràn đến sát biên giới. Giả Nghị Chinh dẫn theo một đội quân tàn tạ, binh lực mỏng manh, nhưng đã kiên cường đánh lui quân địch và cuối cùng trở thành anh hùng.</p>', 'Full', 1, 'single', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xiao Shenyang","avatar":""},{"name":"Zhou Dayong","avatar":""},{"name":"Lexuan Lin","avatar":""},{"name":"Liu Hua","avatar":""},{"name":"Cao Rui","avatar":""},{"name":"Su Jinyuan","avatar":""},{"name":"Zhang Jintiao","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["黄沙漫天"]', 1784690324155);
