INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-ve-thap-nien-80-de-cung-nhau-bac-dau', 'Trở Về Thập Niên 80 Để Cùng Nhau Bạc Đầu', 'Back To The ''80s, Again', 'https://phimimg.com/upload/vod/20250604-1/3703598fe0ac7a892113d803b4fb0dc3.jpg', 'https://phimimg.com/upload/vod/20250604-1/127d54631f3fa872a656ae5da0495000.jpg', '<p>Kiếp trước, Lục Chiêu Nghiên gả cho anh chàng nghèo Quảng Nhạc nhưng bất ngờ trở thành phú bà. Trong khi đó, em gái Lục Thấm Ninh gả cho sĩ quan Lăng Nhạc lại trở nên điên loạn sau khi chồng mới cưới qua đời đột ngột. Mang lòng oán hận, Lục Thấm Ninh hại chết Lục Chiêu Nghiên nhưng cũng bị giết. Cả hai cùng trùng sinh, Lục Thấm Ninh lựa chọn cướp đi Quảng Nhạc, nhưng không hề biết rằng, Lục Chiêu Nghiên cũng đã trùng sinh và kiếp này vẫn sống tốt hơn cô ta...</p>', 'Hoàn Tất (61/61)', 61, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324155);
