INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-kim-nhat-trich', 'Thiên Kim Nhất Trịch', 'All In', 'https://phimimg.com/upload/vod/20250518-1/1d297f02b8b71d60abc1c78bdc77f264.jpg', 'https://phimimg.com/upload/vod/20250518-1/cec6e99314fa939eae06bc9218cdcff1.jpg', '<p>Vưu Hạo Uẩn, học trò của một thần bài, bị mất trí nhớ và được gia đình Hách Kim Kim cưu mang. Việc anh vô tình bộc lộ kỹ năng cờ bạc đã cuốn anh vào một loạt rắc rối: Tôn Ức Thiên tìm cách lôi kéo anh nhằm tranh giành quyền lực gia tộc; Hách Kim Kim, vốn căm ghét cờ bạc, lại hiểu lầm anh; trong khi đó, Nặc Nhấtliên tục ép anh tham gia vào các ván độ. Sự xuất hiện của Hạ Trĩ, một góa phụ đang một mình nuôi con, đã vô tình làm bại lộ thân phận thực sự của Vưu Hạo Uẩn, đồng thời dẫn đến việc tìm ra hung thủ của một vụ án mạng nghiêm trọng. Vưu Hạo Uẩn buộc phải vận dụng tài năng cờ bạc của mình để phá giải bế tắc, qua đó vạch trần sự thật đằng sau những mánh khóe lừa đảo tinh vi trong xã hội.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Kiếm Vũ","avatar":""},{"name":"Minh Duyệt","avatar":""},{"name":"Lý Tụng Từ","avatar":""},{"name":"Thượng Na","avatar":""},{"name":"Vương Lý Đan Ni","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Qian Jin Yi Zhi","千金一掷"]', 1784690324155);
