INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xich-ho', 'Xích Hồ', 'Red Fox', 'https://phimimg.com/upload/vod/20250603-1/45a0cda0c35b8f57d1c7135cb39f13d2.jpg', 'https://phimimg.com/upload/vod/20250603-1/e1e6d55bc28318137aded8c4ac19ffa2.jpg', '<p>Tại Ibana, vùng đất được mệnh danh là &quot;Quốc gia Đỏ&quot;, tồn tại một sinh vật huyền thoại đáng sợ: Cáo Đỏ. Tương truyền, nó có khả năng biến hóa thành người và cướp đoạt gan người. Dù câu chuyện về Cáo Đỏ tưởng chừng đã lùi vào dĩ vãng, sự trỗi dậy bất ngờ của nó đã gieo rắc hỗn loạn trở lại thế giới. Giữa cơn hỗn loạn ấy, công chúa Sana của Quốc gia Đỏ trở thành tâm điểm.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["붉은 여우","Bulgeun Yeou"]', 1784690324155);
