INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trieu-duong-chi-vu-da', 'Triêu Dương Chi Vu Dạ', 'The Dawn To The Night', 'https://phimimg.com/upload/vod/20250521-1/2701f79a79941bb3564430c7288b352a.jpg', 'https://phimimg.com/upload/vod/20250521-1/cc277bd459ae0ad5bd018b8b8b134007.jpg', '<p>Hoa Triêu Dương, một tu sĩ của phái Cổ Nguyệt nhân tộc đã bế quan năm trăm năm, đột phá cảnh giới thiên nhân, giết chết kẻ thù không đội trời chung là Tu La Dạ Thiên và bước vào ảo cảnh thang lên thiên đường. Nếu Hoa Triêu Dương muốn trở thành tiên nhân thực sự, phải thực hiện nguyện vọng cuối cùng của Dạ Thiên - cứu và ngăn cản hắn trở thành Tu La. Hoa Triêu Dương vì thế đã phong ấn linh hồn mình vào trong ngọc, luân hồi đi tìm Dạ Thiên kiếp trước, tiêu trừ tà niệm và đánh thức Dạ Thiên.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngụy Thiên Hạo","avatar":""},{"name":"Dụ Chung Lê","avatar":""},{"name":"Hà Tử Di","avatar":""},{"name":"Phan Mân Vĩnh","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Zhao Yang Zhi Yu Ye","朝阳之于夜"]', 1784690324155);
