INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-toi-sau-anh-hao-quang', 'Bóng Tối Sau Ánh Hào Quang', 'Diva Futura', 'https://phimimg.com/upload/vod/20250601-1/9871894529819059a23f6093672a8896.jpg', 'https://phimimg.com/upload/vod/20250601-1/b62d00499f89c5e76627520da6e70106.jpg', '<p>Bối cảnh phim diễn ra tại Ý vào cuối thập niên 1980 và đầu thập niên 1990, khi Debora Attanasio, một phụ nữ trẻ đang vật lộn để trả nợ thế chấp, tìm được công việc thư ký tại Diva Futura — một công ty chuyên sản xuất phim khiêu dâm. Tại đây, cô gặp gỡ những nhân vật nổi tiếng như Riccardo Schicchi, Ilona Staller (Cicciolina), Moana Pozzi và Éva Henger. Debora dần bị cuốn vào thế giới đầy mâu thuẫn, ghen tuông và những bí mật đằng sau ánh hào quang của ngành công nghiệp phim người lớn Ý. Câu chuyện phản ánh sự thăng trầm của Diva Futura, từ thời kỳ hoàng kim đến lúc suy tàn, kết thúc bằng cái chết của Schicchi.</p>', 'Full', 1, 'single', 'completed', 13, 2025, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Pietro Castellitto","avatar":""},{"name":"Barbara Ronchi","avatar":""},{"name":"Denise Capezza","avatar":""},{"name":"Tesa Litvan","avatar":""},{"name":"Lidija Kordić","avatar":""},{"name":"Davide Iachini","avatar":""},{"name":"Marco Iermanò","avatar":""},{"name":"Beatrice Puccilli","avatar":""},{"name":"Paolo Ricci","avatar":""},{"name":"Jennifer Caroletti","avatar":""},{"name":"Alessandro Paniccià","avatar":""},{"name":"Fulvio Calderoni","avatar":""},{"name":"Alessandro Moser","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Sex Diva","디바 푸투라","Diva Futura"]', 1784690324155);
