INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-san-ma-quai', 'Di Sản Ma Quái', 'Rosario', 'https://phimimg.com/upload/vod/20250531-1/1f3c350457d67fb45097985b11865cf8.jpg', 'https://phimimg.com/upload/vod/20250531-1/2d740afbf2df98253a0de27ecb78d22c.jpg', '<p>Rosario Fuentes, một nhà môi giới chứng khoán thành đạt ở New York, buộc phải quay về căn hộ cũ của bà ngoại sau khi bà qua đời. Khi một trận bão tuyết khiến cô bị mắc kẹt qua đêm cùng thi thể bà, Rosario bắt đầu phát hiện ra những bí mật đen tối liên quan đến tín ngưỡng huyền bí Palo mà bà Griselda từng theo đuổi.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Emeraude Toubia","avatar":""},{"name":"David Dastmalchian","avatar":""},{"name":"Paul Ben-Victor","avatar":""},{"name":"Diana Lein","avatar":""},{"name":"Emilia Faucher","avatar":""},{"name":"Luna Baxter","avatar":""},{"name":"Constanza Guitérrez","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Rosario: Herencia Maldita","Rosario: Herencia maldita","Rosario","Rosario: Herança Maldita","Сущность. Семейный кошмар","禁夜屍"]', 1784690324155);
