INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('san-duoi-tren-khong', 'Săn Đuổi Trên Không', 'Fight or Flight', 'https://phimimg.com/upload/vod/20250531-1/c9f292a13647a3d0354937ac28252657.jpg', 'https://phimimg.com/upload/vod/20250531-1/da6396b67e2decc4188ebfc3ced8e146.jpg', '<p>Cựu đặc vụ FBI Lucas Reyes (do Josh Hartnett thủ vai) hiện đang làm lính đánh thuê sau khi mất việc. Anh được cấp trên cũ, Katherine Brunt, giao nhiệm vụ bắt giữ một tội phạm quốc tế được gọi là &quot;Ghost&quot; trên chuyến bay từ Singapore đến San Francisco. &quot;Ghost&quot; thực chất là Isha Mallik (do Charithra Chandran thủ vai), một nạn nhân của bọn buôn người, hiện đang trộm cắp của giới tội phạm giàu có để giúp đỡ người nghèo. Trên chuyến bay, ngoài Lucas, còn có nhiều sát thủ và thợ săn tiền thưởng khác cũng nhắm đến Isha. Lucas phải bảo vệ Isha khỏi những mối đe dọa này.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Josh Hartnett","avatar":""},{"name":"Katee Sackhoff","avatar":""},{"name":"Marko Zaror","avatar":""},{"name":"Julian Kostov","avatar":""},{"name":"Charithra Chandran","avatar":""},{"name":"JuJu Chan","avatar":""},{"name":"Sanjeev Kohli","avatar":""},{"name":"Rebecka Johnston","avatar":""},{"name":"Nóra Trokán","avatar":""},{"name":"Sarah Lam","avatar":""},{"name":"Irén Bordán","avatar":""},{"name":"Hughie O''Donnell","avatar":""},{"name":"Danny Ashok","avatar":""},{"name":"Jyuddah Jaymes","avatar":""},{"name":"Willem van der Vegt","avatar":""},{"name":"Sanjeev Kohli","avatar":""},{"name":"Declan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b9