INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-nghich-than-lam-chi-chien', 'Tiên Nghịch: Thần Lâm Chi Chiến', 'Renegade Immortal: Battle Of The God', 'https://phimimg.com/upload/vod/20250531-1/521a8e9abb1770fb5f4bab3ea5d1a707.jpg', 'https://phimimg.com/upload/vod/20250531-1/c8ed81b0ed99cdae72b19f80e235db5c.jpg', '<p>Sau khi rời khỏi vùng đất của Cổ Thần, Ma Thành Vĩnh Dạ trong nội hải Tu Ma bất ngờ trỗi dậy chỉ sau một đêm. Để mở rộng lãnh thổ, Ma Thành liên tục tấn công các môn phái xung quanh khu vực Tu Ma Hải, trong đó bao gồm cả Vân Thiên Tông – nơi Lý Mục Uyển tu luyện. Trong trận chiến bảo vệ môn phái, Lý Mục Uyển trúng phải kịch độc, tính mạng như ngàn cân treo sợi tóc. Vương Lâm, khi hay tin, lập tức cùng nàng xông vào nội hải Tu Ma. Với tu vi hóa thần sơ kỳ, Vương Lâm liều mình chiến đấu chống lại ba vị thành chủ, làm chấn động toàn bộ nội hải Tu Ma. Sau cùng, chàng mang được giải dược trở về và cứu sống Lý Mục Uyển. Tuy nhiên, họ nhanh chóng phát hiện ra rằng nguy cơ vẫn chưa chấm dứt – một âm mưu kéo dài ngàn năm dần hiện rõ. Cuối cùng, nhờ vào tình cảm sâu đậm giữa hai người cùng với việc Vương Lâm lần đầu tiên dung hợp với thân thể Cổ Thần sau khi đột phá hậu kỳ hóa thần, họ đã liên thủ và tiêu diệt hoàn toàn Ma Tôn.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Shi Zekun","avatar":""},{"name":"Huilin Zhang","avatar":""},{"name":"Liu Cong","avatar":""},{"name":"Chen Zhangtaikang","avatar":""},{"name":"Li Haojia","avatar":""},{"name":"Zhuang Miao","avatar":""},{"name":"Ling Jun","avatar":""},{"name":"Sicen Liu","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["仙逆剧场版 神临之战","Xian Ni: Shenlin Zhi Zhan","Renegade Immortal: Battle of the Gods","Xian Ni Ju Chang Ban: Shenlin Zhi Zhan","Renegade Immortal Movie","Renegade Immortal the Movie Battle of the God","仙逆劇場版：神臨之戰","Renegade Immortal The Movie Battle of God''s Arrival","Renegade Immortal Movie Shen Lin Zhi Zhan","仙逆剧场版：神临之战"]', 1784690324155);
