INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-bien', 'Mẹ Biển', 'Mother Sea', 'https://phimimg.com/upload/vod/20250320-1/16437675bb1e9e64dc1d6175f9282965.jpg', 'https://phimimg.com/upload/vod/20250320-1/6b87f2ab4d57558e489ca34b1f2d39c0.jpg', '<p>Mẹ Biển khai thác sâu sắc cuộc sống của người dân làng chài miền biển, nơi họ mưu sinh bằng nghề đánh cá, ngày ngày bám víu vào những con thuyền lênh đênh giữa sóng nước. Cuộc sống tưởng chừng bình yên ấy đột nhiên tan vỡ khi một cơn bão lớn ập đến, cuốn trôi những người đàn ông ra khơi, để lại bờ biển ngập trong mất mát và đau thương. Làng quê vốn hiếm hoi đối mặt thiên tai giờ đây trở thành đống hoang tàn, với những người phụ nữ góa bụa và những đứa trẻ mồ côi cha.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Cao Minh Đạt","avatar":""},{"name":"Cao Thái Hà","avatar":""},{"name":"Lily Chen","avatar":""},{"name":"NSND Việt Anh","avatar":""},{"name":"NSƯT Trương Minh Quốc Thái","avatar":""},{"name":"NSƯT Kim Tuyến","avatar":""},{"name":"Thanh Hiền","avatar":""},{"name":"Hiếu Hiền","avatar":""},{"name":"Thanh Thức","avatar":""},{"name":"Trúc Mây","avatar":""},{"name":"Quang Thái","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324155);
