INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-ban-trai-cua-bunny', 'Hội Bạn Trai Của Bunny', 'Crushology 101', 'https://phimimg.com/upload/vod/20250412-1/4fab0c5138078b67c9cd769fdf4d7412.jpg', 'https://phimimg.com/upload/vod/20250412-1/d419f5a92d42da8be1a49741bffa9fea.jpg', '<p>&quot;Hội bạn trai của Bunny&quot; lấy bối cảnh tại một trường đại học và kể về hành trình trưởng thành của Ban Hee-jin (Roh Jeong-eui). Là người không quá quan tâm đến ngoại hình, cô chỉ hẹn hò dựa trên tính cách. Vì vậy, cô quyết định yêu một chàng trai không quá điển trai nhưng lại có tính cách tốt. Tuy nhiên, sau một thời gian, Ban Hee-jin phát hiện ra rằng anh ta thực chất đã che giấu một bản chất không mấy tốt đẹp đằng sau vẻ ngoài bình thường ấy. Chịu tổn thương sâu sắc từ mối tình đầu đầy cay đắng, cô đưa ra quyết định: từ nay, cô sẽ chỉ hẹn hò với những chàng trai đẹp trai.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Roh Jeong-eui","avatar":""},{"name":"Lee Chae-min","avatar":""},{"name":"Cho Jun-young","avatar":""},{"name":"Kim Hyun-jin","avatar":""},{"name":"Choi Ji-su","avatar":""},{"name":"Hong Min-gi","avatar":""},{"name":"Nam Kyu-hee","avatar":""},{"name":"Lee Ji-hoon","avatar":""},{"name":"Kim Jae-hwa","avatar":""},{"name":"Kim Min-cheol","avatar":""},{"name":"Wang Bit-na","avatar":""},{"name":"Kim Hyeon-mok","avatar":""},{"name":"Jo Hyun-ah","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["바니와 오빠들"]', 1