INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tat-tat-ve-vo-toi', 'Tất Tật Về Vợ Tôi', 'Everything About My Wife', 'https://phimimg.com/upload/vod/20250530-1/449a9be6c0b8b5f9e721b0a0255f487f.jpg', 'https://phimimg.com/upload/vod/20250530-1/1d75d9cd2416fe5700cce46d83e1b824.jpg', '<p>Rất muốn bỏ vợ, người đàn ông nọ thuê một chàng đẹp trai để quyến rũ cô ấy. Nhưng rốt cuộc anh lại phạm sai lầm lớn khi phải lòng cô ấy lần nữa.</p>', 'Full', 1, 'single', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Dennis Trillo","avatar":""},{"name":"Sam Milby","avatar":""},{"name":"Jennylyn Mercado","avatar":""},{"name":"Carmi Martin","avatar":""},{"name":"Alex San Agustin","avatar":""},{"name":"Joyce Glorioso","avatar":""},{"name":"Polo Laurel","avatar":""},{"name":"Nova Villa","avatar":""},{"name":"Ruby Ruiz","avatar":""},{"name":"Donna Cariaga","avatar":""},{"name":"Isay Alvarez","avatar":""},{"name":"Romnick Sarmenta","avatar":""},{"name":"Annette Gozon-Valdes","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Everything About My Wife"]', 1784690324155);
