INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dau-hang', 'Đầu Hàng', 'The Surrender', 'đầu hàng the surrender kate burton colby minifie neil sandilands vaughn armstrong mia ellis pete ploszek chelsea alden riley rose critchlow lola kelly alaina pollack judith foster thompson richard b. larimore hal perry invocación the surrender', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-tim-y-duc-long-can-dam', 'Trái Tim Y Đức: Lòng Can Đảm', 'The Secret Of Chivalrous Courage And Medical Heart', 'https://phimimg.com/upload/vod/20250530-1/4147da3468e81af8bfd4b333bb85b360.jpg', 'https://phimimg.com/upload/vod/20250530-1/f04ebf47f1acef62090bf70bcd3f669c.jpg', '<p>Tại một bữa tiệc gia đình, doanh nhân giàu có Khang Thành - Thẩm Sướng bất ngờ đột tử. Cảnh sát Kiều Thanh Thanh vào cuộc điều tra và nghi ngờ Cao Đại Long là nghi phạm giết người. Trong quá trình truy bắt, Cao Đại Long bị thương. Anh buộc phải đến tìm bác sĩ Phương Gia Minh ở phòng khám Tế Thế Đường để chữa trị. Sau đó, anh lại rơi vào bẫy của kẻ xấu, may mắn được Phương Gia Minh cứu giúp. Cảm động trước ân tình đó, Cao Đại Long tiết lộ một vụ án cũ cách đây 10 năm. Cuối cùng, đã tìm được hung thủ thực sự đứng sau cái chết của Thẩm Sướng và vu oan cho Cao Đại Long.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Hạo Tường","avatar":""},{"name":"Trương Chấn Hiên","avatar":""},{"name":"Hồ Quốc Hùng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["侠胆医心之暗潮汹涌"]', 1784690324155);
