INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mau-em-la-hoi-tho-cua-toi', 'Máu Em Là Hơi Thở Của Tôi', 'My Golden Blood', 'https://phimimg.com/upload/vod/20250314-1/39a639fab6fb7f8ce038207b6edf7b55.jpg', 'https://phimimg.com/upload/vod/20250314-1/8d60d549678f276478fa964f23c2e20e.jpg', '<p>Mark, một ma cà rồng 200 tuổi, tìm thấy mục đích mới sau khi gặp Tong, chàng trai 20 tuổi có dòng máu hiếm và mạnh mẽ đến mức các ma cà rồng không thể cưỡng lại. Khi Tong trở thành mục tiêu của những ma cà rồng khác, Mark buộc phải bảo vệ cậu khỏi các mối đe dọa từ bên ngoài cũng như cả bản năng của chính mình.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Way-ar Sangngern","avatar":""},{"name":"Gawin Caskey","avatar":""},{"name":"Apasiri Nitibhon","avatar":""},{"name":"Tanutchai Wijitvongtong","avatar":""},{"name":"Janya Thanasawaangkoun","avatar":""},{"name":"Panadda Ruangwut","avatar":""},{"name":"Trai Nimtawat","avatar":""},{"name":"Chayapol Jutamas","avatar":""},{"name":"Napapat Sattha-atikom","avatar":""},{"name":"Panachai Sriariyarungruang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["血色之恋","Darah Suci","Lueat Nai Lom Haijai Chan","噬血欲情","My Golden Blood","เลือดนายลมหายใจฉัน"]', 1784690324155);
