INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pho-mai-chinh-phu-tro-cap', 'Phô Mai Chính Phủ Trợ Cấp', 'Government Cheese', 'https://phimimg.com/upload/vod/20250416-1/41203f8316d9ec7945f42259780c3f48.jpg', 'https://phimimg.com/upload/vod/20250416-1/2e503b8759b1600ee0c9dab16c4579a6.jpg', '<p>Khi Hampton được phóng thích khỏi nhà tù, buổi đoàn tụ gia đình được mong đợi từ lâu không diễn ra như anh hy vọng. Vợ và hai con của Hampton đã tạo thành một gia đình kỳ lạ, và việc anh trở lại đã khiến họ bị cuốn vào vòng xoáy.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"David Oyelowo","avatar":""},{"name":"Simone Missick","avatar":""},{"name":"Jahi Di''Allo Winston","avatar":""},{"name":"Evan Ellison","avatar":""},{"name":"Bokeem Woodbine","avatar":""},{"name":"Jeremy Bobb","avatar":""},{"name":"Louis Cancelmi","avatar":""},{"name":"Adam Beach","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["גבינה ממשלתית","Government Cheese"]', 1784690324155);
