INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cha-toi-nguoi-o-lai', 'Cha Tôi, Người Ở Lại', 'My Father, Who Stayed Behind', 'https://phimimg.com/upload/vod/20250309-1/ca1645bac2d4172a525b711b97f2f83c.jpg', 'https://phimimg.com/upload/vod/20250309-1/e2afe3bc417b72199af9366e88c8fee5.jpg', '<p>Bộ phim kể về câu chuyện gia đình có tới hai ông bố cùng nuôi dưỡng ba đứa con không cùng huyết thống, nhưng tràn ngập tình yêu thương và ấm áp. Được làm lại từ phim truyền hình Trung Quốc đình đám Lấy danh nghĩa người nhà.</p>', 'Hoàn Tất (45/45)', 45, 'series', 'completed', 18, 2025, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"NSƯT Bùi Như Lai","avatar":""},{"name":"NSƯT Thái Sơn","avatar":""},{"name":"Ngọc Huyền","avatar":""},{"name":"Trần Nghĩa","avatar":""},{"name":"Thái Vũ Ngọc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324155);
