INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-biet-anh-se-doi-em-o-tuong-lai', 'Em Biết Anh Sẽ Đợi Em Ở Tương Lai', 'Love Through Time', 'https://phimimg.com/upload/vod/20250527-1/a32061514d5e731ba5cdf00503d8392c.jpg', 'https://phimimg.com/upload/vod/20250527-1/0d1184c28b26a0631361445ad835c5aa.jpg', '<p>&quot;Người Du Hành Thời Gian&quot; Thanh Không đến Trái Đất để tìm kiếm lõi năng lượng bị thất lạc, tại đây anh đã gặp Dễ Tâm Nhiên, một nữ sinh đại học nhiệt tình và đơn thuần. Trong một lần tình cờ, Dễ Tâm Nhiên đã nhận được lõi năng lượng và bắt đầu du hành xuyên thời gian, giúp đỡ nhiều người bạn, đồng thời nảy sinh tình cảm với Thanh Không. Thế nhưng, Tâm Nhiên không hề hay biết rằng, mỗi lần cô xuyên không đều tiêu hao năng lượng sống của Thanh Không. Cơ thể anh ngày càng yếu đi, và đối mặt với nguy cơ tan biến. Khi Tâm Nhiên phát hiện sự thật, cô vô cùng đau lòng và xin lỗi anh, quyết định giúp anh quay trở về thế giới của mình. Nhưng Thanh Không từ chối – bởi khoảng thời gian cuối cùng, anh muốn được ở bên Tâm Nhiên và cùng cô tận hưởng niềm vui. Khi cả hai đang giằng xé giữa lựa chọn ở lại hay chia xa, Tâm Nhiên bị Bạch Tiên Vũ, cô bạn học luôn ghen ghét cô, đẩy xuống từ tầng cao. Để cứu cô, Thanh Không đã xuyên không trở về thời điểm trước khi họ quen nhau, đổi lấy việc xóa sạch ký ức của Tâm Nhiên về anh. Thanh Không rời khỏi Trái Đất, rời xa Tâm Nhiên – nhưng anh không hề biết rằng, ký ức về tình yêu ấy đã âm thầm cắm rễ trong tim Tâm Nhiên mãi mãi.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 33, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chen Ziyou","avatar":""},{"name":"Sun Yanqing","avatar":""},{"name":"Li Xiwen","avatar":""},{"name":"Tang Geyuan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '["Wo Zhi Dao Ni Hui Zai Wei Lai Deng Wo","I Know You Will Be Waiting For Me in the Future","我知道你会在未来等我"]', 1784690324155);
