INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chieu-chieu-nhu-nguyen', 'Chiêu Chiêu Như Nguyện', 'My Unpredictable Lover', 'https://phimimg.com/upload/vod/20250505-1/8243a6eb3f3056a6f93bc85108aad2bd.jpg', 'https://phimimg.com/upload/vod/20250505-1/44747d212f842a17562797c01b814e38.jpg', '<p>Lấy bối cảnh vào năm thứ 23 của triều đại Đại Tề, bộ phim kể về Tô Tiểu Tiên, một cô gái xuất thân bình dân nhưng sở hữu tài năng nấu nướng xuất sắc. Trong một lần đi hái nguyên liệu, cô vô tình lạc vào khu săn bắn hoàng gia và cứu sống Tam hoàng tử Triệu Hàn khỏi một cuộc ám sát. Để bảo vệ cô khỏi những rắc rối chính trị, Triệu Hàn đưa cô về phủ dưới danh nghĩa đầu bếp tạm thời. Tuy nhiên, Tô Tiểu Tiên không muốn bị giam cầm và luôn tìm cách rời khỏi phủ để theo đuổi ước mơ mở quán ăn riêng. Sau nhiều lần thất bại trong việc trốn thoát, cô quyết định nấu một bữa ăn tệ hại để bị đuổi đi. Nhưng món &quot;rượu hoa đào&quot; của cô lại khiến Triệu Hàn say mê. Trong cơn say, Triệu Hàn phát tác chứng bệnh kỳ lạ, khiến anh xuất hiện một nhân cách thứ hai – Triệu Nhiên. Từ đây, mối quan hệ giữa Tô Tiểu Tiên, Triệu Hàn và Triệu Nhiên trở nên phức tạp, đồng thời hé lộ những bí mật liên quan đến một loại độc dược thần bí từ phương Nam.</p>', 'Tập 11', 16, 'series', 'ongoing', 29, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Vũ Hân","avatar":""},{"name":"Tạ Xương Phong","avatar":""},{"name":"Mạc Mộng Thần","avatar":""},{"name":"Phó Tử Dương","avatar":""},{"name":"Trương Khải Trình","avatar":""},{"name":"Ngô Hạo","avatar":""},{"name":"Quách Tĩnh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2