INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-tranh-giua-cac-vi-sao-andor-phan-2', 'Chiến Tranh Giữa Các Vì Sao: Andor (Phần 2)', 'Star Wars: Andor (Season 2)', 'https://phimimg.com/upload/vod/20250427-1/52ddf64f9ab170c18b832b4b1114fa3d.jpg', 'https://phimimg.com/upload/vod/20250427-1/7acf0b50e6f9372e12ab6fc335cbd4af.jpg', '<p>Đặt bối cảnh 5 năm trước các sự kiện trong Rogue One (2016), bộ phim xoay quanh dàn nhân vật chính trong giai đoạn Liên minh Nổi dậy non trẻ mới hình thành chống lại Đế chế Thiên hà. Một trong những nhân vật đó là Cassian Andor, vốn mang thân phận trộm cắp hèn mọn song về sau anh ta đã trở thành một chiến sĩ cách mạng gia nhập phe Nổi dậy.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Diego Luna","avatar":""},{"name":"Stellan Skarsgård","avatar":""},{"name":"Kyle Soller","avatar":""},{"name":"Denise Gough","avatar":""},{"name":"Adria Arjona","avatar":""},{"name":"Genevieve O''Reilly","avatar":""},{"name":"Faye Marsay","avatar":""},{"name":"Anton Lesser","avatar":""},{"name":"Elizabeth Dulau","avatar":""},{"name":"Alastair Mackenzie","avatar":""},{"name":"Muhannad Bhaier","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Andor: Uma História Star Wars","星球大战：安多","安多","Star Wars - Andor","ვარსკვლავური ომები: ანდორი","ვარსკვლავური ომები: უბოროტო","סטאר וורס: אנדור","אנדור: סיפור מלחמת הכוכבים","מלחמת הכו