INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cang-gong-cang-gay', 'Càng Gồng Càng Gãy', 'Overcompensating', 'https://phimimg.com/upload/vod/20250524-1/589bc84b23965853937f8b6ea399db75.jpg', 'https://phimimg.com/upload/vod/20250524-1/93e68df5d61e1eab29861aece8593e69.jpg', '<p>Benny – chàng cựu hot boy kiêm ngôi sao bóng bầu dục của trường – đang cố gắng che giấu giới tính thật. Cậu bất ngờ thân thiết với Carmen, một cô gái lập dị chỉ mong được công nhận và &quot;hòa nhập&quot; bằng mọi giá. Dưới sự chỉ dẫn “bất chấp” của chị gái Benny cùng anh bạn trai lắm chiêu của cô, bộ đôi mới lớn dấn thân vào thế giới của những cuộc tình tệ hại, rượu vodka và những chiếc thẻ căn cước giả.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Benito Skinner","avatar":""},{"name":"Wally Baram","avatar":""},{"name":"Mary Beth Barone","avatar":""},{"name":"Adam DiMarco","avatar":""},{"name":"Rish Shah","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Overcompensating"]', 1784690324155);
