INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-co-the-thay-truoc-ti-le-thanh-cong', 'Tôi Có Thể Thấy Trước Tỉ Lệ Thành Công', 'Success Rate', 'https://phimimg.com/upload/vod/20250413-1/4233d5dee00c305d38b3bee750a62a61.jpg', 'https://phimimg.com/upload/vod/20250413-1/7616a5630a428db158a5107252cc2dbc.jpg', '<p>Bạch Vũ, nhân viên tiệm đấu giá cổ vật bị chèn ép và bắt nạt tình cờ kích hoạt siêu năng lực có thể đo lường tỉ lệ thành công của sự việc. Nhờ vào năng lực đặc biệt này, anh đã trải qua bao phen mạo hiểm nơi đô thị, không ngừng trưởng thành và lội ngược dòng.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Tích Thần","avatar":""},{"name":"Phan Khải Ngôn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["我能看见成功率","我能看見成功率","Wo Neng Kan Jian Cheng Gong Lv","Wo Neng Kan Jian Cheng Gong Lu","我能预见成功率"]', 1784690324155);
