INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-sinh-giong-nhu-thuo-dau-gap-go', 'Nhân Sinh Giống Như Thuở Đầu Gặp Gỡ', 'A Love Never Lost', 'https://phimimg.com/upload/vod/20250513-1/79a7020d1056c51b7be1daa319b0625b.jpg', 'https://phimimg.com/upload/vod/20250513-1/274f18059898496c3dc17d4f531474f8.jpg', '<p>Bộ phim tập trung vào năm thanh niên đầy khát vọng vươn lên cứu đất nước thoát khỏi hiểm họa sau thất bại trong Chiến tranh Trung-Nhật, bộ phim miêu tả những chiến binh cách mạng đã chiến đấu trong những trận chiến đẫm máu để lật đổ trật tự cũ đã tồn tại hàng nghìn năm, và cuối cùng là dẫn đường để phục hưng Trung Quốc và trẻ hóa quốc gia.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Hiện","avatar":""},{"name":"Xuân Hạ","avatar":""},{"name":"Nguỵ Đại Huân","avatar":""},{"name":"Chu Du","avatar":""},{"name":"Chu Á Văn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["人生若如初见","人生若如初見","A Love Nerver Lost"]', 1784690324155);
