INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-than-toi-la-tai-phiet', 'Bạn Thân Tôi Là Tài Phiệt', 'My Guy Friend Is A Chaebol', 'https://phimimg.com/upload/vod/20250527-1/830ae065613a43f27e1456f27f5c95fe.jpg', 'https://phimimg.com/upload/vod/20250527-1/f71b88319ec75d1bcd0fc5d40581db22.jpg', '<p>Người phụ nữ phát hiện bạn trai ngoại tình và còn để lại một khoản nợ khổng lồ. Cô tìm đến người bạn cũ để nhờ giúp đỡ, lại bất ngờ phát hiện đối phương chính là người thừa kế của một tập đoàn tài chính lớn. Trong quá trình cùng đối mặt với khó khăn, một mối tình lãng mạn thầm kín đã lặng lẽ nảy nở giữa hai người.</p>', 'Hoàn Tất (41/41)', 41, 'series', 'completed', 29, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kang Yul","avatar":""},{"name":"Choi Ha-seul","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324155);
