INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-lan-ga-cho-ma-quan', 'Ba Lần Gả Cho Ma Quân', 'Just Wanna Be With You', 'https://phimimg.com/upload/vod/20250513-1/8ba73414fdf31fa11006f32e5bbc1c4c.jpg', 'https://phimimg.com/upload/vod/20250513-1/9a9e048c68b7fd95b922d85205631ce6.jpg', '<p>Thần nữ của tộc Thương Vân – Giang Trĩ Ngư và thiếu niên ly tộc – Giang Cảnh Hoài, tình cờ gặp gỡ và nảy sinh tình cảm. Tình yêu của họ bị ngăn cấm bởi tộc trưởng Nam Cung Tiêu do khác biệt giai cấp. Không chỉ phản đối, ông còn giăng bẫy khiến cả hai hiểu lầm sâu sắc, từ yêu hóa hận.

Thế nhưng qua những hiểu lầm và đau khổ, họ dần khám phá ra sự thật bị che giấu. Tình yêu chân thành đã giúp họ vượt qua định kiến, hóa giải thù hận, và cùng nhau cứu lấy chúng sinh khỏi tai họa diệt vong.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Mã Thu Nguyên","avatar":""},{"name":"Hà Kiện Kỳ","avatar":""},{"name":"Trương Sí","avatar":""},{"name":"Tôn Nghiên Ân","avatar":""},{"name":"Triệu Tử Lạc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["San Jia Mo Jun","一念三千","Yi Nian San Qian","Solo Quiero Estar Contigo","삼가마군: 마군의 신부","Apenas Quero Estar Contigo","Трижды невеста повелителя тьмы","三嫁魔君"]', 1784690324155);
