INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('2099', '2099', '2099', 'https://phimimg.com/upload/vod/20250516-1/577957f6c1e956824f7b056606fe0d57.jpg', 'https://phimimg.com/upload/vod/20250516-1/0184a38c6e68602dc7a043614dc3c1f6.jpg', '<p>Nhờ sự giúp đỡ của ái phi người máy sinh học 2099, vị vua vô dụng Trần Tiểu Hoa đã lột xác từ một người bỏ bê bản thân đến dũng cảm gánh vác trách nhiệm. Tuy nhiên, tất cả đều chỉ xảy ra trong thế giới ảo. Trần Tiểu Hoa ở thế giới thực đang sắp chết não. Người yêu Khương Đào của anh đánh đổi cả mạng sống để giúp anh tỉnh lại, giúp anh hoàn thành nhiệm vụ lội ngược dòng. Sau khi tỉnh lại, Trần Tiểu Hoa đối mặt với người yêu đang hôn mê. Lần này, đến lượt anh cứu cô ấy.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Khê Nhuế","avatar":""},{"name":"Tôn Trạch Nguyên","avatar":""},{"name":"Lâm Gia Xuyên","avatar":""},{"name":"Trương Khả Doanh","avatar":""},{"name":"Chu Hạo Kỳ","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["2099","Goodbye My Love"]', 1784690324155);
