INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-tu-vo-tat', 'Quân Tử Vô Tật', 'Everything Is Fine With The Emperor', 'https://phimimg.com/upload/vod/20250224-1/bee91c3a5c1b9214a52914ce6c188746.jpg', 'https://phimimg.com/upload/vod/20250224-1/8fcf862cb00eefe8c76847b216d6752a.jpg', '<p>Tam hoàng tử Lưu Lăng, lớn lên trong lãnh cung, mang một bí mật không ai hay biết: đôi mắt của chàng có thể nhìn thấy “thần tiên”! Một thiếu niên sa cơ lỡ vận như Lưu Lăng bất ngờ gặp gỡ Diêu Tế, một nữ thần tiên mạnh mẽ từ trên trời giáng xuống. Dưới sự giúp đỡ của các thái phi tiền triều sở hữu tuyệt kỹ phi phàm, chàng bắt đầu hành trình trưởng thành đầy nhiệt huyết và lãng mạn để xoay chuyển vận mệnh.

Tình cảm giữa Lưu Lăng và Diêu Tế, hai con người đến từ hai thế giới khác biệt, dần trở nên sâu sắc. Nhưng cả hai lại bất ngờ bị cuốn vào một cuộc đấu đá cung đình đầy mưu mô và khói mù. Những bí mật về thần tiên và những ẩn tình của các thái phi cũng lần lượt được hé lộ…</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Jun Zi Wu Ji","寡人无疾","君子无疾之天降姚霁","Gua Ren Wu Ji","Guǎrén Wú Jí","Jūnzǐ Wú Jí","Junzi Wu Ji","Guaren Wu Ji","Everything is Fine with the Emperor","君子无疾"]', 1784690324155);
