INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chay-tron-giua-dem', 'Cuộc Chạy Trốn Giữa Đêm', 'The Accidental Getaway Driver', 'https://phimimg.com/upload/vod/20250527-1/792f93269c82a4649f309efad3c510d6.jpg', 'https://phimimg.com/upload/vod/20250527-1/514e663fa9168ce78cde8123e6bd967f.jpg', '<p>Một cuốc taxi đêm kỳ lạ khi tài xế Hoàng Long lại thành con tin trên chính chiếc xe của mình. Với bao tâm sự đầy cảm thông với kẻ tù tội trẻ, ông đã thuyết phục cậu ta trở về với bản ngã lương thiện.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Hiep Tran-Nghia","avatar":""},{"name":"Dustin Nguyễn","avatar":""},{"name":"Phi Vu","avatar":""},{"name":"Dali Benssalah","avatar":""},{"name":"Gabrielle Chan","avatar":""},{"name":"Vivien Ngô","avatar":""},{"name":"Sharon Sharth","avatar":""},{"name":"Travon McCall","avatar":""},{"name":"Edward Singletary","avatar":""},{"name":"Valeria Sweet","avatar":""},{"name":"Cathy Vu","avatar":""},{"name":"Tiffany Rothman","avatar":""},{"name":"Ray Kam","avatar":""},{"name":"Nhu Quynh Nguyen Linh","avatar":""},{"name":"Kestrel Riegel","avatar":""},{"name":"Maximus Riegel","avatar":""},{"name":"Ezra Samson","avatar":""},{"name":"Luc","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["意外逃亡","The Accidental Getaway Driver"]', 1784690324155);
