INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-bong-toi', 'Trò Chơi Bóng Tối', 'Game Of Shadows', 'https://phimimg.com/upload/vod/20250504-1/8f87baf2a6f221f2cd2dd9657ab37cf4.jpg', 'https://phimimg.com/upload/vod/20250504-1/cfcaedab9f7c32e282655933de752ec3.jpg', '<p>Ái Phương là một doanh nhân xinh đẹp, tài năng nhưng luôn cô độc. Từ khi Linh Đan giúp đưa tro cốt của cha mẹ Ái Phương về nước, cả hai từ từ bắt đầu thân thiết như chị em ruột. Bất ngờ một hôm Linh Đan bị giết hại một cách bí ẩn. Không đưa ra được bằng chứng thuyết phục với Công An, Ái Phương quyết định tự mình điều tra.</p>', 'Hoàn Tất (31/31)', 31, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Chu Anh","avatar":""},{"name":"Quang Sự","avatar":""},{"name":"Karen Nguyễn","avatar":""},{"name":"Nguyễn Xuân Hiệp","avatar":""},{"name":"Dương Cường","avatar":""},{"name":"Trần Anh Huy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '[]', 1784690324155);
