INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pha-mat-bong-cua-huan-luyen-vien', 'Pha Mất Bóng của Huấn Luyện Viên', 'A Head Coach''s Turnover', 'https://phimimg.com/upload/vod/20250526-1/bc75e7596bf3f81a17e37106e51162eb.jpg', 'https://phimimg.com/upload/vod/20250526-1/cea754f7226c9e1dcc3e7cd67467be66.jpg', '<p>Huấn luyện viên bóng rổ chuyên nghiệp Maeng Gong đứng trước nguy cơ bị sa thải do thành tích kém. Để cải thiện phong độ đội bóng, ông bất ngờ bắt tay với Hwa Jin, một antifan thường xuyên để lại bình luận ác ý về ông. Từ đó, một cuộc “song đấu” đầy hài hước bắt đầu.</p>', 'Hoàn Tất (2/2)', 2, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Sung-woong","avatar":""},{"name":"Park Soo-oh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["맹감독의 악플러"]', 1784690324155);
