INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dep-hon-thien-duong', 'Đẹp Hơn Thiên Đường', 'Heavenly Ever After', 'https://phimimg.com/upload/vod/20250420-1/0a423a2a972cc43907579c345881851c.jpg', 'https://phimimg.com/upload/vod/20250420-1/1b015fa3fbe54eabdfba406dcb6f76b7.jpg', '<p>Sau bao thăng trầm của cuộc đời, một cặp uyên ương từng bị cái chết chia lìa nay đoàn tụ trên thiên đường – nhưng chàng vẫn ở độ tuổi ba mươi, còn nàng thì đã ngoài tám mươi.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Hye-ja","avatar":""},{"name":"Son Suk-ku","avatar":""},{"name":"Han Ji-min","avatar":""},{"name":"Lee Jung-eun","avatar":""},{"name":"Cheon Ho-jin","avatar":""},{"name":"Ryu Deok-hwan","avatar":""},{"name":"Jeong Ji-an","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["천국보다 아름다운"]', 1784690324155);
