INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-tham-tu-takao-ameku', 'Bác Sĩ Thám Tử Takao Ameku', 'Ameku M.D. Doctor Detective', 'https://phimimg.com/upload/vod/20250403-1/918ca2388f18db0b85a4e2f849b812b6.jpg', 'https://phimimg.com/upload/vod/20250403-1/0f29c850c3c5bcc13cad9c758b1ff02b.jpg', '<p>Khoa Giám sát Giải phẫu Bệnh lý của Bệnh viện Đa khoa Ten’ikai chuyên xử lý những ca bệnh mà các bác sĩ khác cho là quá khó để điều trị. Đây cũng là nơi xuất hiện những bí ẩn kỳ lạ, từ căn bệnh không rõ nguyên nhân cho đến những vụ án mạng bí ẩn mà ngay cả cảnh sát cũng bó tay. Đứng ở trung tâm của mọi chuyện là Takao Ameku, một bác sĩ thiên tài quyết tâm vạch trần sự thật chấn động đằng sau những hiện tượng dị thường này.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ayane Sakura","avatar":""},{"name":"Kensho Ono","avatar":""},{"name":"Manaka Iwami","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["天久鹰央的事件病历簿","Ameku Takao no Suiri Karte","Ameku Takao''s Detective Karte","Ameku Takao no Suiri Karute","「天久鷹央」シリーズ","天久鷹央 シリーズ","「あめくたかお」シリーズ","あめくたかおのすいりカルテ","Ameku Takao''s Mystery Medical Record","天久鷹央の推理カルテ"]', 1784690324155);
