INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bac-si-tham-tu-takao-ameku', 'Bác Sĩ Thám Tử Takao Ameku', 'Ameku M.D. Doctor Detective', 'bác sĩ thám tử takao ameku ameku m.d. doctor detective ayane sakura kensho ono manaka iwami 天久鹰央的事件病历簿 ameku takao no suiri karte ameku takao''s detective karte ameku takao no suiri karute 「天久鷹央」シリーズ 天久鷹央 シリーズ 「あめくたかお」シリーズ あめくたかおのすいりカルテ ameku takao''s mystery medical record 天久鷹央の推理カルテ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-thu-than-yeu', 'Kẻ Thù Thân Yêu', 'Dear Enemy', 'https://phimimg.com/upload/vod/20250508-1/676ac92c8335dcf23d3a4aca96ebc182.jpg', 'https://phimimg.com/upload/vod/20250508-1/17d0878ff2f507eab9ab61e76765de29.jpg', '<p>Câu chuyện kể về La Mạn và Trần Khải Tây, hai người bạn thân từng có xuất phát điểm tương đồng và ngang tài ngang sức. Vài năm sau khi tốt nghiệp, họ gặp lại nhau nhưng hoàn cảnh lại hoàn toàn trái ngược. La Mạn, một biên kịch đã có chút danh tiếng, không hài lòng với thành tựu sự nghiệp, hy vọng thông qua hôn nhân để nâng tầm cuộc sống, đạt được địa vị ngang hàng với Trần Khải Tây. Trong khi đó, Trần Khải Tây, làm dâu hào môn lại phải đối mặt với sự chế nhạo, mỉa mai của La Mạn. Dù cũng có phản kháng nhưng cô lại đang mắc kẹt sâu trong vũng lầy hôn nhân, và việc cứu vãn tình yêu cùng cuộc hôn nhân trở nên cấp bách hơn bao giờ hết. Vào lúc mối quan hệ giữa hai người đầy sóng ngầm, Chung Khuynh Thành trẻ trung xinh đẹp xuất hiện và trở thành nhân vật mấu chốt trong cuộc cạnh tranh giữa họ...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cao Diệp","avatar":""},{"name":"Trần Nghiên Hy","avatar":""},{"name":"Viên Hoằng","avatar":""},{"name":"Vạn Bằng","avatar":""},{"name":"Lô Phương Sinh","avatar":""},{"name":"Lư Đông Húc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Querida Inimiga","Qin Ai De Chou Di","Dear Haters","亲爱的仇敌"]', 1784690324155);
