INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ke-thu-than-yeu', 'Kẻ Thù Thân Yêu', 'Dear Enemy', 'kẻ thù thân yêu dear enemy cao diệp trần nghiên hy viên hoằng vạn bằng lô phương sinh lư đông húc querida inimiga qin ai de chou di dear haters 亲爱的仇敌', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-danh-cap-trai-tim-toi', 'Người Đánh Cắp Trái Tim Tôi', 'Took My Heart Away', 'https://phimimg.com/upload/vod/20250523-1/74791e94994d3e4390e48a23408bc1c2.jpg', 'https://phimimg.com/upload/vod/20250523-1/cc708eb0c3c1a3b37d804fc282849d1d.jpg', '<p>Phim kể về thủ lĩnh Ảnh Thám – Phương Nhàn, buộc phải che giấu thân phận để kết hôn gả vào hào môn họ Khám. Anh tình cờ kết hôn với Khám Mỹ Viện – người con gái mà anh đã thầm yêu từ lâu nhưng cô lại luôn chống đối cuộc hôn nhân sắp đặt này. Một nụ hôn bất ngờ đã kích hoạt hiện tượng hoán đổi linh hồn, khiến hai người phải miễn cưỡng hợp tác trong hoàn cảnh trớ trêu khi bị hoán đổi thân xác. Khám Mỹ Viện ban đầu cố tình bày mưu gây khó dễ để thoát khỏi cuộc hôn nhân, nhưng Phương Nhàn lại dùng những chiêu trò kỳ lạ như mở tiệc cưới kiểu &quot;dòng nước chảy&quot;, liệu pháp trị liệu bằng cá để vực dậy ngành kinh doanh nhà tắm của gia tộc, khiến cô bắt đầu nhìn anh bằng con mắt khác. Đặc biệt, khi gặp nguy hiểm, cô tận mắt chứng kiến Phương Nhàn không ngại nguy hiểm, hy sinh cứu mình, từ đó tình cảm dần nảy sinh.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wang Luqing","avatar":""},{"name":"Samuel Liu","avatar":""},{"name":"Gao Xiaoyu","avatar":""},{"name":"Ye Yi","avatar":""},{"name":"Wang Miaomiao","avatar":""},{"name":"Zhou Liaoke","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Qing Xin Dang Yang","Who Took My Heart Away","卿心荡漾"]', 1784690324155);
