INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-danh-cap-trai-tim-toi', 'Người Đánh Cắp Trái Tim Tôi', 'Took My Heart Away', 'người đánh cắp trái tim tôi took my heart away wang luqing samuel liu gao xiaoyu ye yi wang miaomiao zhou liaoke qing xin dang yang who took my heart away 卿心荡漾', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-kinh-hoang', 'Bí Mật Kinh Hoàng', 'Until Dawn', 'https://phimimg.com/upload/vod/20250524-1/8a43e0b4c459cac0439ed4b1f795b70f.jpg', 'https://phimimg.com/upload/vod/20250524-1/a26f77d13ef543f1d92bdba602b145ee.jpg', '<p>Bí Mật Kinh Hoàng diễn ra sau khi em gái Melanie mất tích một cách bí ẩn, Clover cùng bạn bè quyết định vào một thung lũng nơi cuối cùng nhìn thấy em gái để tìm kiếm câu trả lời. Khi lạc vào một khu nhà bỏ hoang, họ bị một kẻ giết người đeo mặt nạ theo dõi và bị sát hại một cách kinh hoàng từng người một... cho đến khi họ tỉnh dậy và phát hiện mình quay ngược lại vào buổi tối đầu tiên. Bị mắc kẹt trong một vòng lặp thời gian bí ẩn, họ buộc phải sống lại cơn ác mộng đó mỗi đêm, nhưng mỗi lần lại phải đối mặt với những mối đe dọa mới và những cách chết khác nhau, ngày càng đáng sợ hơn. Khi hy vọng dần tắt, nhóm bạn nhận ra họ chỉ còn 13 mạng sống trước khi biến mất mãi mãi. Cách duy nhất để thoát khỏi là sống sót cho đến khi bình minh.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Ella Rubin","avatar":""},{"name":"Michael Cimino","avatar":""},{"name":"Odessa A''zion","avatar":""},{"name":"Ji-young Yoo","avatar":""},{"name":"Belmont Cameli","avatar":""},{"name":"Maia Mitchell","avatar":""},{"name":"Peter Stormare","avatar":""},{"name":"Zsófia Temesvári","avatar":""},{"name":"Tibor Szauerwein","avatar":""},{"name":"Lotta Losten","avatar":""},{"name":"Mariann Hermányi","avatar":""},{"name":"Willem van der Vegt","avatar":""},{"name":"Ádám Bot","avatar":""},{"name":"Ádám Kocsis","avatar":""},{"name":"Adrienn Mész","avatar":""},{"name":"Ádám Zambryzcki","avatar":""},{"name":"Bog","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981