INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('antoinette-cua-mississippi', 'Antoinette Của Mississippi', 'She The People', 'https://phimimg.com/upload/vod/20250525-1/65a5491e5a1dfa2a2e547d8452c09bd8.jpg', 'https://phimimg.com/upload/vod/20250525-1/4b1d8df67ea0ab3b88c3dccab2e1320e.jpg', '<p>Nỗ lực tỏa sáng trong chính trường, vị phó thống đốc da đen đầu tiên của Mississippi phải quản lý gia đình lập dị của mình và đối đầu với một ông sếp mắc kẹt trong quá khứ.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Terri J. Vaughn","avatar":""},{"name":"Jade Novah","avatar":""},{"name":"Drew Olivia Tillman","avatar":""},{"name":"Dyon Brooks","avatar":""},{"name":"Jo Marie Payton","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["L''élue du peuple","Žena z lidu","Rouva varakuvernööri","為民服務的她","Žena iz naroda","נבחרת העם","Wicegubernatorka","Ea e vocea poporului","Guvernatoarea","هي صوت الشعب","为民服务的她","นางฟ้าประชาชี","Жінка від народу","She the People","Tyler Perry''s Miss Governor","Tyler Perry''s She the People","Antoinette của Mississippi","Miss Governor"]', 1784690324155);
