INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('antoinette-cua-mississippi', 'Antoinette Của Mississippi', 'She The People', 'antoinette của mississippi she the people terri j. vaughn jade novah drew olivia tillman dyon brooks jo marie payton l''élue du peuple žena z lidu rouva varakuvernööri 為民服務的她 žena iz naroda נבחרת העם wicegubernatorka ea e vocea poporului guvernatoarea هي صوت الشعب 为民服务的她 นางฟ้าประชาชี жінка від народу she the people tyler perry''s miss governor tyler perry''s she the people antoinette của mississippi miss governor', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngu-uyen-lenh', 'Ngự Uyên Lệnh', 'Love Rewritten', 'https://phimimg.com/upload/vod/20250519-1/3cf902d8bb1a366a317acad90c076ec1.jpg', 'https://phimimg.com/upload/vod/20250519-1/1a9f621e4b09507c457e4d412624251d.jpg', '<p>Một vụ ám sát bất ngờ đã khiến Tiêu Cảnh Dương và Lâm Minh Huyên – cặp đôi vốn đã định ly hôn – không chỉ bị hoán đổi linh hồn cho nhau mà còn trùng sinh trở về thời điểm trước khi họ thành hôn. Cả hai buộc phải cùng nhau tìm cách để hoán đổi thân xác trở lại. Ngay khi vừa trở lại thân xác của mình và mọi hiểu lầm tưởng chừng sắp được hóa giải, Tiêu Cảnh Dương lại chọn cách đẩy Lâm Minh Huyên ra xa. Tuy nhiên, cô vẫn phát hiện ra bí mật mà anh cố gắng che giấu. Vì vậy, đứng trước ranh giới sinh tử và giữa lúc các thế lực đen tối đang ngấm ngầm trỗi dậy, lần này, Lâm Minh Huyên quyết tâm sẽ cùng Tiêu Cảnh Dương nắm chặt tay nhau, đối mặt với mọi chuyện.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Việt","avatar":""},{"name":"Đới Cảnh Diệu","avatar":""},{"name":"Lý Nhược Gia","avatar":""},{"name":"Lâm Á Đông","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yu Yuan Ling","皇后不可能这么可爱","어연령: 운명을 가르는 령","御渊令"]', 1784690324155);
