INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-hoa-roi-gap-lai-chang', 'Mùa Hoa Rơi Gặp Lại Chàng', 'Love Never Fails', 'https://phimimg.com/upload/vod/20250428-1/8ddc08cc5c27bc4c6f12a4990d2e0666.jpg', 'https://phimimg.com/upload/vod/20250428-1/1908024d2b0d0b738f32485770020c7e.jpg', '<p>Bộ phim được chuyển thể từ tiểu thuyết cùng tên “Yêu Không Bao Giờ Thất Bại” của tác giả Thục Khách, kể về chuyện thượng thần Cẩm Tú mong muốn giúp đỡ yêu tinh hoa trà Hồng Ngưng thành tiên. Nhưng hai người đã kết thành duyên phận nghìn năm, cuối cùng Hồng Ngưng đã giúp Cẩm Tú trở thành câu chuyện của loài người.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Học Nghĩa","avatar":""},{"name":"Hồ Ý Hoàn","avatar":""},{"name":"Ngao Thụy Bằng","avatar":""},{"name":"Hứa Hiểu Nặc","avatar":""},{"name":"Dương Lâm","avatar":""},{"name":"Cảnh Nghiên Tuấn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["落花時節又逢君","Luo Hua Shi Jie You Feng Jun","พานพบอีกครายามบุปผาโปรยปราย","The Season of Falling Flowers","When the Flowers Fall, We Meet Again","I Find You Alone Under Falling Petals","Mùa Hoa Rơi Gặp Lại Chàng","落花时节又逢君"]', 1784690324155);
