INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mua-hoa-roi-gap-lai-chang', 'Mùa Hoa Rơi Gặp Lại Chàng', 'Love Never Fails', 'mùa hoa rơi gặp lại chàng love never fails lưu học nghĩa hồ ý hoàn ngao thụy bằng hứa hiểu nặc dương lâm cảnh nghiên tuấn 落花時節又逢君 luo hua shi jie you feng jun พานพบอีกครายามบุปผาโปรยปราย the season of falling flowers when the flowers fall, we meet again i find you alone under falling petals mùa hoa rơi gặp lại chàng 落花时节又逢君', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-huong-duong-2025', 'Hoa Hướng Dương', 'We Girls', 'https://phimimg.com/upload/vod/20250524-1/b77e121027d2fbd02984144e4e23ec6b.jpg', 'https://phimimg.com/upload/vod/20250524-1/7f7b0093582ce01ab09a5aaee87b6633.jpg', '<p>Vì muốn mua thiết bị cấy ghép ốc tai điện tử trị giá 200.000 tệ cho con gái, Cao Nguyệt Hương (do Triệu Lệ Dĩnh thủ vai) đã liều lĩnh phạm pháp và bị kết án tù. Tuy nhiên, chính trong khoảng thời gian bị giam giữ đó, cô đã kết bạn với Hắc Muội (do Lan Tây Á thủ vai), Đặng Hồng (Chuỵết Ni), Hồ Bình (Vương Cúc), và Quách Ái Mỹ (Thành Tiêu). Dù mỗi người một tính cách, họ đều có chung một tinh thần không khuất phục trước số phận, dũng cảm đối mặt với hiện thực nghiệt ngã. Trên hành trình vượt qua nghịch cảnh, họ luôn sát cánh bên nhau, cùng nhau vươn lên, sống như những bông hoa luôn hướng về phía mặt trời.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Lệ Dĩnh","avatar":""},{"name":"Lan Tây Á","avatar":""},{"name":"Chuỵết Ni","avatar":""},{"name":"Vương Cúc","avatar":""},{"name":"Thành Tiêu","avatar":""},{"name":"Vương Khiếu Vũ","avatar":""},{"name":"Tiền Y","avatar":""},{"name":"Dương Thần Tịch","avatar":""},{"name":"Lý Huệ Quân","avatar":""},{"name":"Trần Chấp Âm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["出狱女子的故事","We Girls","向阳·花"]', 1784690324155);
