INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('siren-2025', 'Siren', 'Sirens', 'https://phimimg.com/upload/vod/20250524-1/056fecaf46ff6ae8ea212d375ac24e68.jpg', 'https://phimimg.com/upload/vod/20250524-1/7e6a596f51312b61fe696343eaebfc81.jpg', '<p>Lo lắng về mối quan hệ quá mức thân thiết của em gái với vị sếp tỷ phú, cô gái đầy bản lĩnh nọ tìm kiếm câu trả lời tại một khu điền trang xa hoa bên bờ biển.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Julianne Moore","avatar":""},{"name":"Meghann Fahy","avatar":""},{"name":"Milly Alcock","avatar":""},{"name":"Kevin Bacon","avatar":""},{"name":"Glenn Howerton","avatar":""},{"name":"Bill Camp","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["夭惑心計","Sirens"]', 1784690324155);
