INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-nang-lap-phuong-sieu-pham', 'Siêu Năng Lập Phương: Siêu Phàm', 'Super Cube', 'https://phimimg.com/upload/vod/20250324-1/ce7d987b2e78887a2d2d26ed8a742e1b.jpg', 'https://phimimg.com/upload/vod/20250324-1/2392932232977da78bc4e68e542fea59.jpg', '<p>Cậu thiếu niên bình thường Vương Tiểu Tu trong một sự cố bất ngờ đã nhận được &quot;Siêu Năng Lập Phương&quot; - hệ thống không gian từ văn minh vũ trụ chiều không gian tiên tiến, từ đó sở hữu năng lực phi phàm. Vì được cô gái mình yêu thầm đã lâu, cũng là hoa khôi của trường Thẩm Dao tỏ tình, Vương Tiểu Tu đã khiến tên côn đồ Tôn Tuấn, kẻ cũng theo đuổi Thẩm Dao tức giận. Nhờ sự thông minh và năng lực siêu nhiên, Vương Tiểu Tu đã hóa giải nguy hiểm, nhưng đồng thời cũng chuốc thêm nhiều rắc rối khác. Thẩm Dao bị một kẻ bí ẩn đưa đến thế giới của những người siêu phàm, Vương Tiểu Tu quyết tâm dấn thân vào hành trình cứu cô. Hãy đồng hành cùng Tiểu Tu chiến đấu trong thế giới kỳ ảo, và diễn giải sự công bằng và chính nghĩa trên con đường trở thành cường giả tuyệt thế !</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ye Zhiqiu","avatar":""},{"name":"Jiang Yingjun","avatar":""},{"name":"Zhangtaikang Chen","avatar":""},{"name":"Zhenyan Liu","avatar":""},{"name":"Tong Yin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Chao Neng Lifang","Chao Neng Li Fang","超能立方动画","超能立方 超凡篇","Chaoneng Lifang","超能立方","超能立方超凡篇","Chao Neng Lifang: Chaofan Pian","超能立方：超凡篇","Super Cube","スーパーキューブ","슈퍼 큐브: 최강 고딩이 되는 법","슈퍼 큐브","Супер Куб","The Super Cube","Siêu Năng Lập Phương: Siêu Phàm"]', 1784690324155);
