INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sieu-nang-lap-phuong-sieu-pham', 'Siêu Năng Lập Phương: Siêu Phàm', 'Super Cube', 'siêu năng lập phương: siêu phàm super cube ye zhiqiu jiang yingjun zhangtaikang chen zhenyan liu tong yin chao neng lifang chao neng li fang 超能立方动画 超能立方 超凡篇 chaoneng lifang 超能立方 超能立方超凡篇 chao neng lifang: chaofan pian 超能立方：超凡篇 super cube スーパーキューブ 슈퍼 큐브: 최강 고딩이 되는 법 슈퍼 큐브 супер куб the super cube siêu năng lập phương: siêu phàm', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chan-tuong-trong-duong-net', 'Chân Tướng Trong Đường Nét', 'The Long Way Home', 'https://phimimg.com/upload/vod/20250513-1/ba75a45f35c9a0d40244394770a1b6eb.jpg', 'https://phimimg.com/upload/vod/20250513-1/e33792790e4f402f0133c9ac6805707a.jpg', '<p>Sau một chiến dịch vây bắt tổ chức buôn người, cảnh sát hình sự Cố Tân Hà cùng họa sĩ phác họa chân dung Tề Sở đã gia nhập đội đặc nhiệm chống buôn người của Triệu Thực. Qua hàng loạt vụ án ngày càng rối rắm, phức tạp, tổ chuyên án đã khoanh vùng được băng nhóm tội phạm do &quot;Quế Di&quot; cầm đầu. Tề Sở đích thân dấn thân vào nguy hiểm, cuối cùng tổ chuyên án đã triệt phá thành công tổ chức tội phạm gieo rắc tội ác suốt nhiều năm này, đồng thời phanh phui bí mật kinh hoàng của Quế Di là &quot;nuôi dưỡng trẻ bị bắt cóc để làm công cụ cho những vụ bắt cóc&quot;.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Thánh Nhạc","avatar":""},{"name":"Giang Dịch Hiên","avatar":""},{"name":"Dương Bác Tiêu","avatar":""},{"name":"Lí Ninh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Lun Kuo Zhong De Zhen Xiang","The Truth in the Outline","轮廓中的真相"]', 1784690324155);
