INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('suoi-nguon-tuoi-tre', 'Suối Nguồn Tươi Trẻ', 'Fountain Of Youth', 'https://phimimg.com/upload/vod/20250524-1/8bb5f76ca7c0b31e0204d40630851cf8.jpg', 'https://phimimg.com/upload/vod/20250524-1/07e24b99850adaa0e5c29542fe9e134f.jpg', '<p>Một kẻ săn kho báu đại tài lập ra một đội để bước vào một chuyến phiêu lưu sinh tử. Nhưng để luôn đi trước một bước các mối đe dọa, anh cần một người còn thông minh hơn mình: cô em gái xa cách.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"John Krasinski","avatar":""},{"name":"Natalie Portman","avatar":""},{"name":"Eiza González","avatar":""},{"name":"Domhnall Gleeson","avatar":""},{"name":"Carmen Ejogo","avatar":""},{"name":"Arian Moayed","avatar":""},{"name":"Stanley Tucci","avatar":""},{"name":"Laz Alonso","avatar":""},{"name":"Benjamin Chivers","avatar":""},{"name":"Daniel de Bourg","avatar":""},{"name":"Steve Tran","avatar":""},{"name":"Michael Epp","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Bimini","젊음의 샘","מעיין הנעורים","מעיין נעורים","Η πηγή της νεότητας","파운틴 오브 유스","La Fontaine de Jouvence","Vodnjak Mladosti","Jaunības Avots","இளைஞர்களின் நீரூற்று","ఫౌంటెన్ ఆఫ్ యూత్","چشمه ی جوانی","Gençlik Çeşmesi","Fântâna tinereții","Az ifjúság forrása","Fontana mladosti","Jaunystės šaltinis","ახალგაზრდობის შადრევანი","La fuente de la eterna juventud","Fountain of Youth"]', 