INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('suoi-nguon-tuoi-tre', 'Suối Nguồn Tươi Trẻ', 'Fountain Of Youth', 'suối nguồn tươi trẻ fountain of youth john krasinski natalie portman eiza gonzález domhnall gleeson carmen ejogo arian moayed stanley tucci laz alonso benjamin chivers daniel de bourg steve tran michael epp bimini 젊음의 샘 מעיין הנעורים מעיין נעורים η πηγή της νεότητας 파운틴 오브 유스 la fontaine de jouvence vodnjak mladosti jaunības avots இளைஞர்களின் நீரூற்று ఫౌంటెన్ ఆఫ్ యూత్ چشمه ی جوانی gençlik çeşmesi fântâna tinereții az ifjúság forrása fontana mladosti jaunystės šaltinis ახალგაზრდობის შადრევანი la fuente de la eterna juventud fountain of youth', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-nuoc-ngam', 'Dòng Nước Ngầm', 'Undercurrent', 'https://phimimg.com/upload/vod/20250524-1/cfafc1d6d0969c5bd794a113aad579e3.jpg', 'https://phimimg.com/upload/vod/20250524-1/f894fb3b4481997f65867b92a705a5b8.jpg', '<p>Một loại ma túy mới xuất hiện ở Cảng Thành, hé lộ vụ buôn lậu vũ trang ma túy xảy ra hai năm trước, với manh mối hướng đến Tập đoàn Hoành Đồ. Sau khi chuyển ngành, Lục Vân Long nhận nhiệm vụ nằm vùng điều tra, cứu được Chủ tịch tập đoàn Lý Hoành và giành được sự tin tưởng. Anh phát hiện Trần Bưu, người đứng thứ hai trong tập đoàn chính là hung thủ đã sát hại đồng đội năm xưa. Anh cùng đặc vụ nằm vùng Từ Lệ phối hợp hành động, trải qua nhiều lần đối đầu sinh tử với bọn buôn ma túy, cuối cùng đã thành công triệt phá tổ chức này.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wang Ting","avatar":""},{"name":"Tang Wang","avatar":""},{"name":"Hei Zi","avatar":""},{"name":"Wang Hongxiang","avatar":""},{"name":"Shao Bing","avatar":""},{"name":"黄子耀","avatar":""},{"name":"Yang Qingwen","avatar":""},{"name":"Yang Jianping","avatar":""},{"name":"Liu Hui","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["暗涌"]', 1784690324155);
