INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cha-quen-con-nho', 'Cha Quên Con Nhớ', 'Forget You Not', 'https://phimimg.com/upload/vod/20250524-1/3f8d3fa74d45a2e8d4d6cf71680f76e0.jpg', 'https://phimimg.com/upload/vod/20250524-1/c349126e5a4f6e0ef4c8eac56b6f0e9f.jpg', '<p>Một cây hài độc thoại đầy hoài bão biến những khó khăn của mình thành tiếng cười thấm thía khi cô cân bằng giữa công việc và các mối quan hệ trong khi chăm sóc người cha già.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Hsieh Ying-shiuan","avatar":""},{"name":"Ronald Chin Han","avatar":""},{"name":"Tracy Chou","avatar":""},{"name":"Esther Liu","avatar":""},{"name":"Wallace Huo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["忘了我记得","تَنسى لكنني أتذكر","忘了我記得"]', 1784690324155);
