INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-thanh-son-hai', 'Sư Thành Sơn Hải', 'Contenders', 'https://phimimg.com/upload/vod/20250502-1/ab626d33ab9ddde6d009e793af1f84d8.jpg', 'https://phimimg.com/upload/vod/20250502-1/dcdf67108a6973b891d33c48c642d07a.jpg', '<p>Cuối thập niên 40 thế kỷ 20, dọc bờ sông Malacca tập trung nhiều cộng đồng người Hoa đến mưu sinh. Trải qua năm tháng gian truân, đồng hương giúp đỡ lẫn nhau, kiên cường phấn đấu. Sau khi có chỗ đứng, một bang hội đầy huyền thoại là &quot;Sơn Hải Bang&quot; dần trở thành trung tâm phát triển của người Hoa nơi đây.</p>', 'Hoàn Tất (48/48)', 48, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Nguy Tử","avatar":""},{"name":"Dương Húc Văn","avatar":""},{"name":"Vương Tử Vy","avatar":""},{"name":"Nhạc Lệ Na","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["狮城山海"]', 1784690324155);
