INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-thuong-giai-te', 'Bảng Thượng Giai Tế', 'Serendipity', 'https://phimimg.com/upload/vod/20250425-1/8bcc977603884adde71ce30d80d1f3d1.jpg', 'https://phimimg.com/upload/vod/20250425-1/a8a17267760c77de2cb08e2e043ab06e.jpg', '<p>Giản Minh Thư, thiên kim Giản phủ ở Giang Ninh, vô tình rơi xuống vực và mất trí nhớ, nhưng cô đã thoát khỏi thảm kịch gia đình bị xóa sổ và được người cô yêu là Lục Thường cứu thoát. Hai người cùng nhau đến kinh đô để dự thi. Cô luôn nghi ngờ về danh tính của mình, bước vào ngôi nhà để điều tra và giải quyết bí ẩn, và bất ngờ có được manh mối về trải nghiệm sống của mình. Tuy nhiên, cuộc điều tra của Giản Minh Thư dần rơi vào thế khó. Cô nghĩ rằng mình đang bước đi một mình trong nguy hiểm, nhưng thực ra Lục Thường đang âm thầm bảo vệ cô. Sự dịu dàng và tình cảm của Lục Thường càng làm tan chảy trái tim Minh Thư. Hai người đã cùng nhau trải qua nhiều nguy hiểm, cùng nhau chống chọi với mưa gió. Cuối cùng, họ đã xác nhận tình cảm của mình và dành phần đời còn lại bên nhau.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Tử Kỳ","avatar":""},{"name":"Lư Dực Hiểu","avatar":""},{"name":"Vương Hoằng Nghị","avatar":""},{"name":"Khổng Tuyết Nhi","avatar":""},{"name":"Hạc Thu","avatar":""},{"name":"Dương Sĩ Trạch","avatar":""},{"name":"Uông Tịch Triều","avatar":""},{"name":"Liêu Tuệ Giai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["榜下贵婿","운명 재회 로맨스 <방상가서>","ราชบุตรเขยที่รัก","Serendipity","榜上佳婿"]', 1784690324155);
