INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-nham-ban-than', 'Yêu Nhầm Bạn Thân', 'Friendzone', 'https://phimimg.com/upload/vod/20250523-1/4064be55ed57ee223fe4e40fb4f38bd2.jpg', 'https://phimimg.com/upload/vod/20250523-1/9e90d5e45abb30f79b340985a2b16f14.jpg', '<p>“Yêu Nhầm Bạn Thân” nói về tình cảm giữa hai người bạn thân khác giới là An (Kaity Nguyễn) và Toàn (Trần Ngọc Vàng) đã luôn bỏ lỡ những cơ hội để ở bên nhau. Bối cảnh phim trải dài khắp Việt Nam từ Bắc vào Nam với những thắng cảnh và địa danh nổi tiếng.</p>', 'Full', 1, 'single', 'completed', 18, 2025, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Kaity Nguyễn","avatar":""},{"name":"Trần Ngọc Vàng","avatar":""},{"name":"Thanh Sơn","avatar":""},{"name":"Phương Nam","avatar":""},{"name":"Quốc Khánh","avatar":""},{"name":"Sơn Huy","avatar":""},{"name":"Đông My","avatar":""},{"name":"Emma Lê","avatar":""},{"name":"Stephen Vũ","avatar":""},{"name":"Trương Minh Cường","avatar":""},{"name":"Quyên Qui","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Yêu Nhầm Bạn Thân"]', 1784690324155);
