INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-on-moi-nguoi-tiep-theo-phan-2', 'Cảm Ơn, Mời Người Tiếp Theo (Phần 2)', 'Thank You, Next (Season 2)', 'https://phimimg.com/upload/vod/20250523-1/43cf68a6e014bccace452450f477ea77.jpg', 'https://phimimg.com/upload/vod/20250523-1/9637c4d223d54ecfd1a18599ae97305c.jpg', '<p>Sau cuộc chia tay đau lòng, nữ luật sư trẻ nọ lao vào thế giới hẹn hò thời hiện đại đầy phức tạp, với sự ủng hộ hết mực của hội bạn thân.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 24, 2025, 'Vietsub', 'FHD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Serenay Sarıkaya","avatar":""},{"name":"Metin Akdülger","avatar":""},{"name":"Hakan Kurtaş","avatar":""},{"name":"Boran Kuzum","avatar":""},{"name":"Ahmet Rıfat Şungar","avatar":""},{"name":"Bade İşçil","avatar":""},{"name":"Esra Ruşan️️️️","avatar":""},{"name":"Meriç Aral","avatar":""},{"name":"Efe Tunçer","avatar":""},{"name":"Kamil Güler","avatar":""},{"name":"Cem Güler","avatar":""},{"name":"Fatih Artman","avatar":""},{"name":"Batuhan Bayar","avatar":""},{"name":"Ege Aydan","avatar":""},{"name":"Perihan Savaş","avatar":""},{"name":"Seray Sever","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Спасибо. Следующий!","Thank You, Next","Kimler Geldi Kimler Geçti"]', 1784690324155);
