INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-thoai-ochi', 'Huyền Thoại Ochi', 'The Legend Of Ochi', 'https://phimimg.com/upload/vod/20250522-1/3bcd63754aacd3556f2db0c44342e58f.jpg', 'https://phimimg.com/upload/vod/20250522-1/ec288b1efb231f0b73e88603a8ab43ed.jpg', '<p>Ở một ngôi làng xa xôi trên đảo Carpathia, Yuri – cô gái nông dân rụt rè – từ nhỏ đã được dạy phải sợ loài sinh vật huyền bí mang tên ochi. Nhưng khi tình cờ phát hiện một chú ochi con bị thương bị bỏ rơi, trái tim nhân hậu trong Yuri trỗi dậy. Cô liều mình bỏ trốn khỏi nơi an toàn, bắt đầu chuyến hành trình phi thường xuyên qua rừng sâu núi thẳm để đưa sinh vật nhỏ bé trở về vùng đất bí ẩn mà nó thuộc về.</p>', 'Full', 1, 'single', 'completed', 13, 2025, 'Vietsub', 'CAM', 'Phần Lan', 1, '[{"name":"Helena Zengel","avatar":""},{"name":"Finn Wolfhard","avatar":""},{"name":"Emily Watson","avatar":""},{"name":"Willem Dafoe","avatar":""},{"name":"Razvan Stoica","avatar":""},{"name":"Carol Bors","avatar":""},{"name":"David Andrei Baltatu","avatar":""},{"name":"Andrei Antoniu Anghel","avatar":""},{"name":"Eduard Mihail Oancea","avatar":""},{"name":"Tomas Otto Ghela","avatar":""},{"name":"Eduard Ionut Cucu","avatar":""},{"name":"Stefan Burlacu","avatar":""},{"name":"Andreea Mustata","avatar":""},{"name":"Gabriel Spahiu","avatar":""},{"name":"Puiu-Mircea Lăscu","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["오치의 전설","奥奇传说","奥奇传奇","Очи","OCHI！-オチ-","The Legend of Ochi"]', 1784690324155);
