INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-hai-vui-ve', 'Thứ Hai Vui Vẻ', 'Happy Monday(s)', 'https://phimimg.com/upload/vod/20250522-1/b9ef5fb045c57fa4656f36eb9aa9dd60.jpg', 'https://phimimg.com/upload/vod/20250522-1/028af5ba072afab1374ee2f29dea7298.jpg', '<p>Bị mắc kẹt trong vòng lặp thời gian và liên tục trải qua ngày hôm đó hết lần này đến lần khác, cậu sinh viên đại học nọ đã nắm bắt cơ hội để cưa đổ người mình thầm thương.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Oabnithi Wiwattanawarang","avatar":""},{"name":"Punpreedee Khumprom Rodsawat","avatar":""},{"name":"Poon Mitpakdee","avatar":""},{"name":"Chatchawit Techarukpong","avatar":""},{"name":"Warisara Jitpreedasakul","avatar":""},{"name":"Intira Jaroenpura","avatar":""},{"name":"Khomkrit Treewimol","avatar":""},{"name":"Apinya Sakuljaroensuk","avatar":""},{"name":"Achita Sikamana","avatar":""},{"name":"Jakkrit Yompayorm","avatar":""},{"name":"Nathasit Kotimanuswanich","avatar":""},{"name":"Nichaphat","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sawaddee Wan Jan(s)","สวัสดีวันจันทร์(ส)"]', 1784690324155);
