INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thu-hai-vui-ve', 'Thứ Hai Vui Vẻ', 'Happy Monday(s)', 'thứ hai vui vẻ happy monday(s) oabnithi wiwattanawarang punpreedee khumprom rodsawat poon mitpakdee chatchawit techarukpong warisara jitpreedasakul intira jaroenpura khomkrit treewimol apinya sakuljaroensuk achita sikamana jakkrit yompayorm nathasit kotimanuswanich nichaphat sawaddee wan jan(s) สวัสดีวันจันทร์(ส)', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khue-nu-rat-phien-nao', 'Khuê Nữ Rất Phiền Não', 'Girls Troubles', 'https://phimimg.com/upload/vod/20250522-1/0e6cf21ab9d98c4152e6c67ed0856ad2.jpg', 'https://phimimg.com/upload/vod/20250522-1/682871e420d90e70c67cf99741021772.jpg', '<p>Chu Tiểu Bạch là một nữ đạo diễn trẻ nghèo khó. Cô bôn ba bên ngoài nhiều năm nên mối quan hệ của cô với người cha tên Chu Cường rất căng thẳng. Một lần tình cờ, cô xuyên không về thời cha mình còn trẻ và phát hiện tính cách ông hoàn toàn khác biệt. Cô quyết tâm khám phá bí ẩn về sự thay đổi tính cách của cha mình. Hai người trở thành bạn sau những chuyến phiêu lưu. Cô giúp cha cô theo đuổi tình yêu và cha cô giúp cô thực hiện ước mơ trở thành đạo diễn. Cuối cùng, Chu Tiểu Bạch khám phá ra bí mật về thân thế của mình, hóa giải hiểu lầm và hàn gắn tình cảm cha con.</p>', 'Full', 1, 'single', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yang Junhan","avatar":""},{"name":"Bing Chen","avatar":""},{"name":"Wu Yingzhe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["闺女特烦恼"]', 1784690324155);
