INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ca-map-con-bao', 'Cá Mập: Cơn Bão', 'Shark: The Storm', 'https://phimimg.com/upload/vod/20250516-1/573f2ef62b3ee2fa4fcd5f68f350f78f.jpg', 'https://phimimg.com/upload/vod/20250516-1/9b78cc6a0d6205f2b5f156a4976c63f3.jpg', '<p>Bộ phim là phần tiếp theo của &quot;Shark: The Beginning&quot; (2021), tiếp tục câu chuyện về Cha Woo-sol (do Kim Min-seok thủ vai), một nạn nhân của bạo lực học đường, sau khi ra tù đã trở thành võ sĩ MMA chuyên nghiệp. Trong phần mới này, anh đối đầu với Hyun Woo-yong (do Lee Hyun-wook thủ vai), một nhân vật phản diện nguy hiểm.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 11, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Min-seok","avatar":""},{"name":"Lee Hyun-wook","avatar":""},{"name":"Bae Myeong-jin","avatar":""},{"name":"Lee Jung-hyun","avatar":""},{"name":"Park Jin","avatar":""},{"name":"Wi Ha-jun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["샤크: 더 스톰"]', 1784690324155);
