INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mua-lac-trong-rung', 'Mùa Lạc Trong Rừng', 'Lost In The Woods', 'https://phimimg.com/upload/vod/20250327-1/a48bfac69072b460b305fbc7cc301c09.jpg', 'https://phimimg.com/upload/vod/20250327-1/c06eee169c11cf3613fbeb80a764f3a5.jpg', '<p>Fifa 18 tuổi và mơ ước được đến Nhật Bản, nhưng đơn xin của cậu bị từ chối. Bà của cậu đề nghị giúp đỡ với điều kiện cậu phải làm việc tại trang trại gia đình trong ba tháng. Cậu chấp nhận, và tại đây, cậu gặp Hem, một kiểm lâm 30 tuổi. Giữa khung cảnh thiên nhiên tuyệt đẹp, một mối quan hệ dần nảy nở...</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Tonhon Tantivejakul","avatar":""},{"name":"Varot Makaduangkeo","avatar":""},{"name":"Krittanai Arsalprakit","avatar":""},{"name":"Rudklao Amratisha","avatar":""},{"name":"Nat Natchanan Khantharat","avatar":""},{"name":"Pimpatchara Vajrasevee","avatar":""},{"name":"Nepal Jitranon","avatar":""},{"name":"Nontach Thanawatyanyong","avatar":""},{"name":"Patrarin Punyanutatam","avatar":""},{"name":"Chuerchart Wongsawat","avatar":""},{"name":"Chatkrit Permpanich","avatar":""},{"name":"Narumon Phongsu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["爱在森林里","林中爱季","林間迷情","愛在森林裡","ฤดูหลงป่า"]', 1784690324155);
