INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cap-doi-dinh-menh', 'Cặp Đôi Định Mệnh', 'Heart Pairing', 'https://phimimg.com/upload/vod/20250309-1/9d2af6abc70a1d3115c7c6cb844097bf.jpg', 'https://phimimg.com/upload/vod/20250309-1/28b927427c3fe7abb6858fd211268aea.jpg', '<p>Tình yêu bắt đầu từ những rung động. Nhưng để đi đến hôn nhân, những người đang yêu cần điều gì? Những bạn trẻ khát khao kết hôn cùng tụ hội trong một ngôi nhà. Trong vòng một tháng, họ sẽ di chuyển giữa Ý và Seoul, trải qua ba lần &quot;ghép đôi định mệnh&quot; để tìm ra người bạn đời lý tưởng. Liệu đâu sẽ là cặp đôi hoàn hảo nhất? Những cuộc gặp gỡ đầu tiên đầy hồi hộp, những tâm hồn đồng điệu, cảm xúc chênh vênh và những tiêu chí thực tế – mà không cần hỏi một lời nào – liệu họ có thể tìm thấy tình yêu đích thực qua hành trình này? Lơ lửng giữa lãng mạn và hiện thực, đây chính là cuộc thí nghiệm tình yêu tiền hôn nhân vừa kịch tính, vừa chân thật nhất dành cho những ai đã sẵn sàng bước vào hôn nhân!</p>', 'Tập 10', 15, 'tvshows', 'ongoing', 9, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yoon Jong-shin","avatar":""},{"name":"Lee Chung-ah","avatar":""},{"name":"Choi Si-won","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324155);
