INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khe-uoc-bi-mat-cua-phu-thuy', 'Khế Ước Bí Mật Của Phù Thủy', 'The Secret Contract Of The Witch', 'https://phimimg.com/upload/vod/20250505-1/e08640646c25c321e6776f772d63cee6.jpg', 'https://phimimg.com/upload/vod/20250505-1/abace89184cc4066be0c735bb062a121.jpg', '<p>Vì dây chuyền phù thủy bị thất lạc, tộc trưởng phù thủy Hạ Mạt phải chịu nỗi đau thấu tim gan và không còn sống được bao lâu. Để lấy lại sợi dây chuyền, cô buộc phải ký kết khế ước với giáo sư vật lý Mộ Hàn Vũ, người đến để trả thù và hứa sẽ giúp anh thực hiện ước nguyện. Trong quá trình chung sống, hai người dần nảy sinh tình cảm, nhưng số phận trớ trêu lại đẩy họ vào hai chiến tuyến đối lập...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Phương Đồng","avatar":""},{"name":"Nhậm Vận Kiệt","avatar":""},{"name":"Trần Kiến Vũ","avatar":""},{"name":"Tống Chiêu Nghệ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mo Nv De Mi Mi Qi Yue","Witch''s Secret Contract","魔女的秘密契约"]', 1784690324155);
