INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tang-chau', 'Tàng Châu', 'Hidden Love', 'https://phimimg.com/upload/vod/20250503-1/ab33a3c27938bf807023b1354c87518c.jpg', 'https://phimimg.com/upload/vod/20250503-1/9cf927fa0c4e7ec0e3771968bda22c66.jpg', '<p>Thứ nữ phủ quốc công Lý Sở Sở từ nhỏ đã bị mẹ cả chèn ép tàn nhẫn hơn mười năm, khi biến cố đột ngột trong đời ập tới, cô tình cờ biết được đằng sau cái chết của mẹ ruột còn có kẻ chủ mưu khác, quyết định báo thù cho mẹ. Trong quá trình đó, cô rơi vào vòng xoáy yêu hận với đích huynh Lý Chẩn. Hai người cùng nhau tìm kiếm chân tướng và công lý trong khi kìm nén tình cảm sâu sắc dành cho nhau.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Tịch Tịch","avatar":""},{"name":"Trương Sí","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["嫡兄","Cang Zhu","藏珠"]', 1784690324155);
