INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('yeu-sinh-tu-va-nguoi-may-phan-4', 'Yêu, Sinh Tử Và Người Máy (Phần 4)', 'Love, Death & Robots (Season 4)', 'yêu, sinh tử và người máy (phần 4) love, death & robots (season 4) joe manganiello rosario dawson seth green michael b. jordan élodie yung joe dempsie topher grace mary elizabeth winstead gary cole samira wiley tsuji daisuke maurice lamarche rebecca riedy helen sadler hayley mclaughlin time amor, morte & robôs 爱，死亡和机器人 爱死亡与机器人 爱、死亡 & 机器人 愛死亡與機器人 szerelem, halál és robotok אהבה מוות & רובוטים ラブ、デス&ロボット meilė, mirtis ir robotai любовь, смерть и роботы láska, smrť & roboti любов, смерть та роботи любов, смерть + роботи love, death + robots love death + robots love, death and robots love death robots sevgi, o''lim va robotlar love, death & robots', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dinh-menh-tinh-yeu', 'Định Mệnh Tình Yêu', 'A Stolen Life', 'https://phimimg.com/upload/vod/20250520-1/50029463091e8978d4d7144e25b9dc9e.jpg', 'https://phimimg.com/upload/vod/20250520-1/98309e6a42ed8f9ce53afd371fdd5c98.jpg', '<p>Năm 2002, tại thị trấn ven biển Đức Ninh, một vụ án mạng liên hoàn đã xảy ra. Một con bạc bị sát hại, sau đó là Phó giám đốc chợ Đông Hồ và người em kết nghĩa của ông ta, cũng lần lượt bị giết. Cả ba vụ án đều có phương thức gây án giống nhau. Tất cả bằng chứng và nghi vấn đều hướng về Giang Tứ Minh, đại ca kết nghĩa của Chu Chí Hồng và Chu Lượng. Khi cảnh sát chuẩn bị bắt giữ Giang Tứ Minh, anh bất ngờ bị truy sát. Trong tình huống nguy cấp, cảnh sát ra tay bắt giữ được hung thủ thật sự. Tưởng như vụ án đã khép lại, nhưng đó mới chỉ là phần nổi của tảng băng chìm. Sóng gió vận mệnh bắt đầu ập đến với Giang Tứ Minh và người vợ Ngô Yến…</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Jingchu","avatar":""},{"name":"Lu Fangsheng","avatar":""},{"name":"Yu Ailei","avatar":""},{"name":"Dong Chang","avatar":""},{"name":"Gao Dongping","avatar":""},{"name":"Zhang Ninghao","avatar":""},{"name":"Li Xiaochuan","avatar":""},{"name":"Fu Guanming","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["命中罪爱"]', 1784690324155);
