INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-xe-dem', 'Tài Xế Đêm', 'The Accidental Getaway Driver', 'https://phimimg.com/upload/vod/20250520-1/b930dfb2312f3365b9c186283800454f.jpg', 'https://phimimg.com/upload/vod/20250520-1/81caffa4a03a31f374340fa6dcbd1b4c.jpg', '<p>The Accidental Getaway Driver (Tài Xế Đêm) là một bộ phim tội phạm Mỹ năm 2023 dựa trên câu chuyện có thật về vụ bắt cóc có thật năm 2016. tài xế taxi Mã Hoàng Long, một tài xế taxi gốc Việt tại Quận Cam, bị bắt cóc bởi ba tù nhân vượt ngục. Phim có sự tham gia của Hiệp Trần Nghĩa, Phi Vũ, Dali Benssalah và Dustin Nguyễn. Bộ phim ra mắt tại Liên hoan phim Sundance 2023 vào ngày 23 tháng 1 và đã giúp Lee giành được Giải thưởng Đạo diễn xuất sắc tại hạng mục phim Mỹ. Sau đó, phim được phát hành vào ngày 28 tháng 2 năm 2025 bởi Utopia. Bộ phim nhận được nhiều đánh giá tích cực với 85% trên Rotten Tomatoes và 69 điểm trên Metacritic.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Hiep Tran-Nghia","avatar":""},{"name":"Dustin Nguyen","avatar":""},{"name":"Phi Vu","avatar":""},{"name":"Dali Benssalah","avatar":""},{"name":"Gabrielle Chan","avatar":""},{"name":"Vivien Ngô","avatar":""},{"name":"Sharon Sharth","avatar":""},{"name":"Travon McCall","avatar":""},{"name":"Edward Singletary","avatar":""},{"name":"Valeria Sweet","avatar":""},{"name":"Cathy Vu","avatar":""},{"name":"Tiffany Rothman","avatar":""},{"name":"Ray Kam","avatar":""},{"name":"Nhu Quynh Nguyen Linh","avatar":""},{"name":"Kestrel Riegel","avatar":""},{"name":"Maximus Riegel","avatar":""},{"name":"Ezra Samson","avatar":""},{"name":"Luc","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["意外逃亡","The Accidental Getaway Driver"]', 1784690324155);
