INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tai-xe-dem', 'Tài Xế Đêm', 'The Accidental Getaway Driver', 'tài xế đêm the accidental getaway driver hiep tran-nghia dustin nguyen phi vu dali benssalah gabrielle chan vivien ngô sharon sharth travon mccall edward singletary valeria sweet cathy vu tiffany rothman ray kam nhu quynh nguyen linh kestrel riegel maximus riegel ezra samson luc 意外逃亡 the accidental getaway driver', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-cay-son-tra', 'Chuyện Tình Cây Sơn Tra', 'When The Hawthorn Blooms', 'https://phimimg.com/upload/vod/20250513-1/41a174b54fc5d44366fba629ab73da6c.jpg', 'https://phimimg.com/upload/vod/20250513-1/da10c19712659ec6440a6501520d9de8.jpg', '<p>Đầu những năm 70 của thế kỷ 20, Tịnh Thu, một cô gái có hoàn cảnh gia đình không tốt đã hưởng ứng lời kêu gọi của phong trào lên núi về nông thôn. Cô đến làng Tây Thôn Bình để đi thực tế sưu tầm tư liệu biên soạn lịch sử làng và tại đây, cô đã gặp Lão Tam – một chàng trai khôi ngô, tài hoa. Quá trình tiếp xúc đã khiến hai người dần nảy sinh tình cảm. Tuy nhiên, sự chênh lệch lớn về hoàn cảnh gia đình và địa vị xã hội đã đẩy mối tình của họ vào muôn vàn sóng gió. Liệu lời hẹn ước cùng nhau ngắm cây sơn tra nở hoa của họ có thành sự thật?</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Gia Thạc","avatar":""},{"name":"Từ Tiểu Thư","avatar":""},{"name":"Cao Vũ Hàng","avatar":""},{"name":"Triệu An Đệ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shan Zha Shu Zhi Lian","Under the Hawthorn Tree","山楂树之恋"]', 1784690324155);
