INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-hiem-ly-hon', 'Bảo Hiểm Ly Hôn', 'The Divorce Insurance', 'https://phimimg.com/upload/vod/20250401-1/4ba0b35083da4ae7dbb609e875598591.jpg', 'https://phimimg.com/upload/vod/20250401-1/593553a8757222f9e65ec390af54cff0.jpg', '<p>Bộ phim lột tả một cách trần trụi quá trình đặt ra một mức giá cho việc ly hôn, hé lộ những góc khuất, toan tính và những khía cạnh thực dụng đằng sau một mô hình kinh doanh táo bạo, nơi tình yêu, hôn nhân và sự chia ly bị biến thành những con số lạnh lùng.&nbsp;<span style="text-wrap-mode: wrap;">Câu chuyện xoay quanh đội ngũ phát triển sản phẩm sáng tạo của một công ty bảo hiểm danh tiếng, nơi chỉ quy tụ những bộ óc xuất sắc nhất. Họ đang nghiên cứu và phát triển một loại bảo hiểm ly hôn mới, biến tất cả các khía cạnh liên quan đến ly hôn thành những con số cụ thể, từ đó định giá và tính toán mức chi trả bảo hiểm phù hợp.</span></p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Dong-wook","avatar":""},{"name":"Lee Kwang-soo","avatar":""},{"name":"Lee Ju-bin","avatar":""},{"name":"Lee Da-hee","avatar":""},{"name":"Kim Won-hae","avatar":""},{"name":"Exy","avatar":""},{"name":"Jo Jae-yun","avatar":""},{"name":"Lee Seo-yi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Seguro para Divorciados","Divorce avec assurance","離婚保険","이혼보험","التأمين على الطلاق","The Divorce Insurance"]', 1784690324155);
