INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('1923-phan-2', '1923 (Phần 2)', '1923 (Season 2)', 'https://phimimg.com/upload/vod/20250304-1/26fad012db0fa759232b33239aefa65b.jpg', 'https://phimimg.com/upload/vod/20250304-1/69bf4c56df2a493710d5572b3c85d964.jpg', '<p><span style="text-wrap-mode: wrap;">Duttons phải đối mặt với một loạt các thách thức mới vào đầu thế kỷ 20, bao gồm sự gia tăng của sự mở rộng phương Tây, cấm và cuộc Đại suy thoái.</span></p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Helen Mirren","avatar":""},{"name":"Harrison Ford","avatar":""},{"name":"Brandon Sklenar","avatar":""},{"name":"Julia Schlaepfer","avatar":""},{"name":"Jerome Flynn","avatar":""},{"name":"Darren Mann","avatar":""},{"name":"Isabel May","avatar":""},{"name":"Brian Geraghty","avatar":""},{"name":"Aminah Nieves","avatar":""},{"name":"Michelle Randolph","avatar":""},{"name":"Timothy Dalton","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["黄石：1923","黄石前传","Йеллоустоун: 1923","Yellowstone: 1932","1932","Yellowstone: 1923","1923: A Yellostone Origin Story","1923"]', 1784690324155);
