INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-bo-phim-minecraft', 'Một Bộ Phim Minecraft', 'A Minecraft Movie', 'https://phimimg.com/upload/vod/20250513-1/7c40c5e1c5f88fdff52d54b03d084497.jpg', 'https://phimimg.com/upload/vod/20250508-1/d43ada4cb5f9a1dbdb9d614406726a53.jpg', '<p>Chào mừng bạn đến với thế giới của Minecraft, nơi sự sáng tạo không chỉ giúp bạn chế tạo mà còn là yếu tố quan trọng để sống sót! Bốn kẻ lạc lõng - Garrett “The Garbage Man” Garrison (Momoa), Henry (Hansen), Natalie (Myers) và Dawn (Brooks) - bất ngờ gặp rắc rối khi họ bị kéo qua cánh cửa bí ẩn dẫn đến Overworld: một thế giới kỳ lạ được tạo bởi những khối lập phương và phát triển nhờ vào trí tưởng tượng. Để trở về nhà, họ cần phải làm chủ được thế giới này (và bảo vệ nó khỏi những thực thể tà ác như Piglins và Thây Ma) trong khi dấn thân vào chuyến phiêu lưu màu nhiệm với một thợ chế tạo chuyên nghiệp và khó lường - Steve (Black). Chuyến hành trình này sẽ thách thức sự can đảm của cả năm người, thúc đẩy họ tìm lại với những phẩm chất làm nên sự đặc biệt của riêng mình,… đồng thời là những kỹ năng cần thiết để trở lại với thế giới thật.</p>', 'Full', 1, 'single', 'completed', 25, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Thụy Điển', 1, '[{"name":"Jason Momoa","avatar":""},{"name":"Jack Black","avatar":""},{"name":"Sebastian Eugene Hansen","avatar":""},{"name":"Emma Myers","avatar":""},{"name":"Danielle Brooks","avatar":""},{"name":"Jennifer Coolidge","avatar":""},{"name":"Rachel House","avatar":""},{"name":"Allan Henry","avatar":""},{"name":"Bram Scott-Breheny","avatar":""},{"name":"Moana Williams","avatar":""},{"name":"Jemaine Clement","avatar":""},{"name":"Mark Wright","avatar":""},{"name":"Yvette Parsons","avatar":""},{"name":"Hiram Garcia","avatar":""},{"name":"Bret McKenzie","avatar":""},{"name":"Jared Hess","avatar":""},{"name":"Batanai","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Minecraft","Bir Minecraft Filmi","Մայնքրաֆթ","En Minecraftfilm","마인크래프트 무비","Minecraft: Фільм","Minecraft, Le Film","A Minecraft Movie: Block Party Edition!","A Minecraft Movie: The Block Party Edition","A Minecraft Movie: Block Party Edition","Minecraft: Филм","Minecraft филм","A Minecraft Movie: Minecraft Block Party","A Minecraft Movie - ASL Version","Майнкрафт. Кіно","A Minecraft Movie"]', 1784690324155);
