INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-gen-z', 'Bí Mật Gen Z', 'The Secret Of Gen Z', 'https://phimimg.com/upload/vod/20250518-1/32e2d57ae877e8ce133d7a28a344bef0.jpg', 'https://phimimg.com/upload/vod/20250518-1/c6c9fbf4761f2055339202584e68a0a3.jpg', '<p>Bộ phim sitcom nói về một cô bé Gen Z đi tìm Bố và trải qua nhiều câu chuyện dỡ khóc dỡ cười khi một mình bước chân vào Sài Gòn. Trải qua nhiều sự việc và nhận được sự giúp đỡ từ những người xa lạ, cô bé càng hiểu thêm được tình cảm gia đình, tình yêu thương của những người thân yêu và quý trọng hơn mảnh đất nghĩa tình.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Phương Dung","avatar":""},{"name":"Hòa Hiệp","avatar":""},{"name":"Phúc An","avatar":""},{"name":"Trần Thu","avatar":""},{"name":"Ngọc Tưởng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324155);
