INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-doi-dau-sinh-tu', 'Cuộc Đối Đầu Sinh Tử', 'Confrontation Peak', 'https://phimimg.com/upload/vod/20250518-1/8a0ea93526f2068b86f1dcdab3e31ebf.jpg', 'https://phimimg.com/upload/vod/20250518-1/be4aa126ba0387feb7e82c04db77b21c.jpg', '<p>Sở Thiên Khoát, một tên du côn xuất thân từ tầng lớp thấp, bị người khác gài bẫy tham gia một giải đấu để giành lấy mặt nạ vàng. Trong cuộc thi, anh bị hãm hại nhưng may mắn được công chúa của dị tộc cứu giúp, đồng thời tình cờ có được manh mối về chiếc mặt nạ vàng. Không ngờ rằng tin tức về mặt nạ đã thu hút nhiều thế lực khác nhau, ai cũng muốn tranh đoạt. Một cuộc đối đầu đỉnh cao giữa các phe phái bắt đầu nổ ra. Trong quá trình chiến đấu, Sở Thiên Khoát bất ngờ phát hiện ra sự thật về biến cố của cha mình năm xưa.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Huafeng Chen","avatar":""},{"name":"Xin Yue","avatar":""},{"name":"Vincent Wan Yeung-Ming","avatar":""},{"name":"Andrew Lin Hoi","avatar":""},{"name":"Cica Zhou","avatar":""},{"name":"Kang Xuan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Confrontation Peak","尖峰对决"]', 1784690324155);
