INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vini-jr', 'Vini Jr.', 'Vini Jr.', 'https://phimimg.com/upload/vod/20250518-1/2d06c91b71ba35e6cb8947e2308eaa49.jpg', 'https://phimimg.com/upload/vod/20250518-1/8c12dea3f391a72afd90a873cee0b4a9.jpg', '<p>&quot;Vini Jr.&quot;, một bộ phim tài liệu về câu chuyện cuộc đời của Vinícius Júnior, một trong những tiền đạo triển vọng nhất trong làng bóng đá. Với những con số ấn tượng, Vini Jr là ngôi sao của đội tuyển quốc gia Brazil, và cốt truyện theo chân anh vào năm quyết định 2024. Nhà vô địch UEFA Champions League và có khả năng giành giải thưởng FIFA The Best. Cũng được công nhận vì lòng dũng cảm trong cuộc chiến chống phân biệt chủng tộc, bộ phim cho thấy những khó khăn mà anh đã trải qua trong giải vô địch Tây Ban Nha. Với sự góp mặt của một số thần tượng thể thao, chẳng hạn như Neymar, Karim Benzema, Jude Bellingham và Tony Kroos, bộ phim tài liệu phân tích tác động của cầu thủ này trên và ngoài sân cỏ.</p>', 'Full', 1, 'single', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Brazil', 0, '[{"name":"Vini Jr.","avatar":""},{"name":"Fernanda Nascimento","avatar":""},{"name":"Luana Paixão","avatar":""},{"name":"Nilza Paixão","avatar":""},{"name":"Ulysses Paixão","avatar":""},{"name":"Vinicius Paixão","avatar":""},{"name":"Douglonez","avatar":""},{"name":"Julien Laurens","avatar":""},{"name":"Eduardo Peixoto","avatar":""},{"name":"Felipe Eduardo","avatar":""},{"name":"Fred Pena","avatar":""},{"name":"Lucas Mineiro","avatar":""},{"name":"Menegate","avatar":""},{"name":"Najib","avatar":""},{"name":"Tatá Soares","avatar":""},{"name":"Thiago Lobo","avatar":""},{"name":"Wesley Menezes","avatar":""},{"name":"Antonio Rüdiger","avatar":""},{"name":"A","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Baila, Vini"]', 1784690324155);
