INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dac-vu-vo-hinh-2', 'Đặc Vụ Vô Hình 2', 'The Grey Men 2', 'https://phimimg.com/upload/vod/20250219-1/d4a5e346620165f7615ee3ffd3035bd8.jpg', 'https://phimimg.com/upload/vod/20250219-1/aaf32363f3580494d253cf731927789f.jpg', '<p>Khi chế độ Laika đang thay đổi, những người dưới mặt đen và trắng đang tăng lên. Một số người muốn kiếm được rất nhiều tiền, một số người muốn sử dụng việc này để minh oan, một số người muốn trốn thoát khỏi Laika, và một số người muốn thiết lập một chỗ đứng ở Laika ... cảnh sát đã đặt một sĩ quan cảnh sát bí mật, Zheng Zha, ẩn nấp trong số những người lớn nhất Black Force ở Laika, bài hát Boss, nhưng họ không biết rằng có những người khác muốn nhân cơ hội này để trả thù bài hát Boss.</p>', 'Full', 1, 'single', 'completed', 29, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Andy On Chi-Kit","avatar":""},{"name":"Eric Tsang Chi-Wai","avatar":""},{"name":"Jiro Wang","avatar":""},{"name":"Leni Lan","avatar":""},{"name":"Ben Yuen Foo-Wah","avatar":""},{"name":"Jazz Lam Tsz-Sin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["The Grey Men Ⅱ","黑白潜行2"]', 1784690324155);
