INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-lam-vuon-grosse-pointe', 'Hội Làm Vườn Grosse Pointe', 'Grosse Pointe Garden Society', 'https://phimimg.com/upload/vod/20250518-1/336933b2c491a15a8b6c964bc62a9058.jpg', 'https://phimimg.com/upload/vod/20250518-1/fc492d844ffa34d2a8cabaf4cc80803e.jpg', '<p>Khi bốn thành viên của một hội làm vườn bị vướng vào một vụ giết người tai tiếng, họ buộc phải chôn xác... trong những luống hoa được chăm sóc cẩn thận của chính mình. Ai cũng có bí mật… nhưng một số bí mật thì không bao giờ được chôn vùi.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Melissa Fumero","avatar":""},{"name":"AnnaSophia Robb","avatar":""},{"name":"Ben Rappaport","avatar":""},{"name":"Aja Naomi King","avatar":""},{"name":"Nancy Travis","avatar":""},{"name":"Matthew Davis","avatar":""},{"name":"Alexander Hodge","avatar":""},{"name":"Felix Avitia","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Grosse Pointe Garden Society"]', 1784690324156);
