INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-gia-tao', 'Tình Yêu Giả Tạo', 'Kill Lover', 'https://phimimg.com/upload/vod/20250504-1/936cc301de56a847852f406c9a94187a.jpg', 'https://phimimg.com/upload/vod/20250504-1/3c1b0e320bdb203d97700b3e2da43a9c.jpg', '<p>Vưu Vưu mất mẹ và cha bị tù vì âm mưu của An Quốc Hiên. Cô vô tình làm Tề Đông, con trai An Quốc Hiên, bị mù và vứt xuống biển. Sau khi được cứu, Tề Đông tự lập công ty đối đầu với Tập đoàn Tinh Diệu. Năm năm sau, Vưu Vưu trở lại với danh tính mới, Tề Cách Cách, tiếp cận Tề Đông để trả thù, nhưng phát hiện anh cũng muốn báo thù An Quốc Hiên. Hai người hợp tác, nhưng một mối đe dọa lớn hơn đang rình rập.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wanyan Luorong","avatar":""},{"name":"Sun Jiaqi","avatar":""},{"name":"Yu Yifu","avatar":""},{"name":"Fan Wei","avatar":""},{"name":"Zhang Guansen","avatar":""},{"name":"Liu Shuai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Matar o Amante","Jia Mian Mi Qing","假面之下","Тайная любовь","Hidden Love","Beneath the Mask","假面迷情"]', 1784690324156);
