INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-khong-the-noi-thanh-loi', 'Tình Yêu Không Thể Nói Thành Lời', 'Mumu', 'https://phimimg.com/upload/vod/20250517-1/5b5018c8a024acd6c8b9d1f2db21d8b5.jpg', 'https://phimimg.com/upload/vod/20250517-1/0fa3bbedc75cceb29e75e23017dd8c77.jpg', '<p>Bộ phim xoay quanh cuộc sống của Tiểu Mã (Trương Nghệ Hưng thủ vai) – một người cha khiếm thính sống cùng con gái Mộc Mộc. Trong suốt thời thơ ấu, Mộc Mộc trở thành cầu nối giúp cha giao tiếp và hòa nhập với xã hội. Tuy nhiên, khi cô bé trưởng thành, mong muốn được bước ra thế giới bình thường của người nghe khiến mối quan hệ cha con bắt đầu đối diện với khoảng cách và mâu thuẫn. Một biến cố bất ngờ xảy ra, buộc cả hai phải đưa ra những lựa chọn quan trọng để tìm lại nhau...</p>', 'Full', 1, 'single', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Yixing","avatar":""},{"name":"Li Luo''an","avatar":""},{"name":"Huang Yao","avatar":""},{"name":"Vivienne Tien","avatar":""},{"name":"Zhang Ruonan","avatar":""},{"name":"Yuan Wenkang","avatar":""},{"name":"Ai Liya","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["不说话的爱","Mumu","Муму"]', 1784690324156);
