INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tinh-yeu-khong-the-noi-thanh-loi', 'Tình Yêu Không Thể Nói Thành Lời', 'Mumu', 'tình yêu không thể nói thành lời mumu zhang yixing li luo''an huang yao vivienne tien zhang ruonan yuan wenkang ai liya 不说话的爱 mumu муму', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-tinh-ao', 'Người Tình Ảo', 'Love Virtually', 'https://phimimg.com/upload/vod/20250504-1/7127eebac0a87e753f902a923ba1d7a1.jpg', 'https://phimimg.com/upload/vod/20250504-1/49a453ae4ea37af1f4e1804063981fb1.jpg', '<p>Trình Trình - nữ sinh viên xuất sắc, từng tạo ra một &quot;người tình ảo&quot; hoàn hảo trong mơ mang tên Adam. 10 năm sau, cô trở thành quản lý cấp cao trong công ty công nghệ, cùng bạn trai hiện tại kiêm đối tác Tỉnh Tuấn Nhị phát triển Adam 6.0 – một phiên bản AI khiến hàng ngàn cô gái say đắm. Khi Tuấn Nhị đề nghị nâng cấp Adam 7.0 với nhiều cải tiến mới thì bị lỗi chương trình. Adam 7.0 đột nhiên biến mất khỏi hệ thống và xuất hiện giữa đời thực. Trình Trình bất ngờ nên tìm cách che giấu Adam. Từ một chương trình ảo, Adam trở thành một người đàn ông thật sự – thuần khiết, ấm áp và tràn đầy yêu thương. Sống chung một nhà, hai người dần có tình cảm với nhau. Đến một ngày, Tuấn Nhị phát hiện sự tồn tại của Adam thì muốn đối phó anh ta. Liệu chuyện tình yêu với người tình ảo Adam có kết thúc tốt đẹp?</p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 7, 2025, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Vương Mẫn Dịch","avatar":""},{"name":"Chu Mẫn Hãn","avatar":""},{"name":"Huỳnh Tử Hằng","avatar":""},{"name":"Dương Trác Na","avatar":""},{"name":"Đặng Trí Kiên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["虛擬情人"]', 1784690324156);
