INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-tinh-ao', 'Người Tình Ảo', 'Love Virtually', 'người tình ảo love virtually vương mẫn dịch chu mẫn hãn huỳnh tử hằng dương trác na đặng trí kiên 虛擬情人', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-song-cua-hinh-canh', 'Cuộc Sống Của Hình Cảnh', 'Into The Heat', 'https://phimimg.com/upload/vod/20250506-1/b7fc1e7e421c913b7d133b2b28038e5c.jpg', 'https://phimimg.com/upload/vod/20250506-1/81afb9b0ed4831a63f7c0749d09ed768.jpg', '<p>Để đấu tranh chống tội phạm và thực hiện ước mơ làm cảnh sát, chàng trai trẻ Lưu Tử Minh mang trong mình nhiệt huyết đã đến làm việc tại một đội cảnh sát hình sự thuộc Cục Công an thành phố. Tuy nhiên, công việc rà soát vụn vặt và nhàm chán khiến anh cảm thấy khô khan. Trong quá trình phá án thực tế tại hiện trường, Lưu Tử Minh ngày càng trở nên điềm tĩnh và dày dạn kinh nghiệm, dẫn dắt các học trò của mình tiếp tục phá giải các loại vụ án. Sau khi trải qua sự tôi luyện và mài giũa từ hàng loạt vụ án lớn, trọng án, Lưu Tử Minh đã có cái nhìn sâu sắc hơn về thiện và ác trong bản tính con người, trưởng thành thành một đội trưởng cảnh sát hình sự xuất sắc. Sự chỉ dạy tận tình không giấu giếm của sư phụ, lòng tin được vun đắp qua những lần vào sinh ra tử cùng đồng đội đã giúp anh thực sự nhận thức được trọng trách trên vai người cảnh sát hình sự. Anh cảm thấy vô cùng vinh dự khi được làm công việc cảnh sát hình sự, góp phần bảo vệ sự ổn định xã hội.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Âu Hào","avatar":""},{"name":"Trương Giai Ninh","avatar":""},{"name":"Hà Băng","avatar":""},{"name":"Vương Giai Giai","avatar":""},{"name":"Lưu Thiên Tá","avatar":""},{"name":"Lưu Bội Kỳ","avatar":""},{"name":"Trịnh Hiểu Ninh","avatar":""},{"name":"Tào Bỉnh Côn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f69792608