INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-dinh-bong-da', 'Gia Đình Bóng Đá', 'Football Parents', 'https://phimimg.com/upload/vod/20250516-1/2180f3e3696085fc121b5802790166ae.jpg', 'https://phimimg.com/upload/vod/20250516-1/e0ca6cacf4e06b8bbe6ffc614031c978.jpg', '<p>Khi nói đến sự nghiệp bóng đá nghiệp dư của con mình, nhóm phụ huynh này không hề xấu hổ, chẳng hề ngại ngần mà còn có tinh thần đồng đội đặc biệt.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 29, 2025, 'Vietsub', 'FHD', 'Hà Lan', 0, '[{"name":"Ilse Warringa","avatar":""},{"name":"Eva van Gessel","avatar":""},{"name":"Mariana Aparicio Torres","avatar":""},{"name":"Michiel Nooter","avatar":""},{"name":"Edwin Jonker","avatar":""},{"name":"Bas Hoeflaak","avatar":""},{"name":"Guido Pollemans","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Voetbalouders"]', 1784690324156);
