INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-san-muc-nat', 'Di Sản Mục Nát', 'Rotten Legacy', 'https://phimimg.com/upload/vod/20250516-1/383e3f6f002707edeb21ab05438914f2.jpg', 'https://phimimg.com/upload/vod/20250516-1/9a936cc39f0ea7a459c25de7071c6bb5.jpg', '<p>Sau cơn bạo bệnh, ông trùm truyền thông nọ nhận ra thủ đoạn của các con mình đang đe dọa đế chế mà ông dày công xây dựng – và ông sẽ làm mọi cách để cứu lấy nó.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Jose Coronado","avatar":""},{"name":"Belén Cuesta","avatar":""},{"name":"Diego Martín","avatar":""},{"name":"Natalia Huarte","avatar":""},{"name":"Gustavo Salmerón","avatar":""},{"name":"Nico Romero","avatar":""},{"name":"Iván Pellicer","avatar":""},{"name":"Maria Morera Colomer","avatar":""},{"name":"Mireia Portas","avatar":""},{"name":"Susi Sánchez","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Legado"]', 1784690324156);
