INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-duyen-2025', 'Kỵ Duyên', 'Riding Into Love', 'https://phimimg.com/upload/vod/20250516-1/a2dd34ced31f22356dbf25d233c036b8.jpg', 'https://phimimg.com/upload/vod/20250516-1/66bf00140e1d92a5c73253459c710ce2.jpg', '<p>Câu chuyện tình yêu ngược tâm, hài hước và đầy cấm kỵ giữa lòng Bắc Kinh cuối cùng cũng ra mắt. Bộ phim kể về chuyện tình của Nhâm Hạo Minh và Nguyễn Thanh Thiêm. Nam chính là ông chủ trại ngựa, một tổng tài lạnh lùng trong những chuyện tình yêu ngược tâm đỉnh cao. Nữ chính là một bà chủ tiệm hoa cá tính, mạnh mẽ. Cả hai đều theo đuổi một tình yêu cuồng nhiệt, chấn động lòng người – nhưng tình yêu giữa họ lại là một cuộc hành trình vừa kịch tính, vừa nghẹt thở. Đây là một bộ phim hiện đại, ngôn tình, thuộc thể loại hiện đại đô thị.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wen Yuan","avatar":""},{"name":"Wang Xinting","avatar":""},{"name":"Wang Jingjing","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yi Qi Ding Qing Yuan","A Ride to Love","一骑定情缘"]', 1784690324156);
