INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pernille-phan-5', 'Pernille (Phần 5)', 'Pernille (Season 5)', 'https://phimimg.com/upload/vod/20250516-1/f9439c4f05f366a5961b7f2649eb5421.jpg', 'https://phimimg.com/upload/vod/20250516-1/d45a9299f16e2901ce0eed72380612b2.jpg', '<p>Các con gái tuổi teen. Một công việc trong mảng phúc lợi trẻ em. Một mất mát lớn gần đây. Pørni xoay xở với cuộc sống tất bật, đơn giản và tươi đẹp bằng sự quan tâm và óc hài hước.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 24, 2025, 'Vietsub', 'FHD', 'Na Uy', 0, '[{"name":"Henriette Steenstrup","avatar":""},{"name":"Jon Ranes","avatar":""},{"name":"Ebba Jacobsen Öberg","avatar":""},{"name":"Nils Ole Oftebro","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Pernille","Poerni","Suck It Up","Pørni"]', 1784690324156);
