INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-vien-van-phong-duoc-trieu-hoi-thanh-tu-dai-thien-vuong-o-the-gioi-khac', 'Nhân Viên Văn Phòng Được Triệu Hồi Thành Tứ Đại Thiên Vương Ở Thế Giới Khác', 'Headhunted to Another World: From Salaryman to Big Four!', 'https://phimimg.com/upload/vod/20250515-1/1d77871cec9cd776e22b0c7f0953c8c3.jpg', 'https://phimimg.com/upload/vod/20250515-1/1b345aa4a748e675192c0b919f665c87.jpg', '<p>Trong một thế giới giả tưởng khác, Quỷ Vương cai trị với một đội quân hùng mạnh do Tứ Thiên Vương chỉ huy. Một người tình cờ là Uchimura Denosuke, một nhân viên văn phòng bình thường bất ngờ bị chính Quỷ Vương kéo ra khỏi cuộc sống trần tục của mình. Nhưng ngay cả trong thế giới mới này, Uchimura không được ban cho bất kỳ sức mạnh đặc biệt nào. Liệu anh ta có thể sống sót qua những nhiệm vụ nguy hiểm chỉ với kiến thức của một nhân viên văn phòng không?</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuki Ono","avatar":""},{"name":"Konomi Kohara","avatar":""},{"name":"Akio Otsuka","avatar":""},{"name":"Takanori Hoshino","avatar":""},{"name":"Nene Hieda","avatar":""},{"name":"Chitose Morinaga","avatar":""},{"name":"Ayami Tsukui","avatar":""},{"name":"Takaya Kuroda","avatar":""},{"name":"Tetsuo Komura","avatar":""},{"name":"Mitsuki Saiga","avatar":""},{"name":"Hidenobu Kiuchi","avatar":""},{"name":"Kengo Kawanishi","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["平凡上班族到異世界當上了四天王的故事","平凡上班族到异世界当上了四天王的故事","上班族去了异世界后成了四天王","Sararyman ga Isekai ni Ittara Shitennou ni Natta Hanashi","Sararīman ga Isekai ni Ittara Shitennō ni Natta Hanashi","サラリーマン四天王","Salaryman Big 4","Salaryman ga Isekai ni Ittara Shitennou ni Natta Hanashi","salaryman shitennou","Office Worker Has Become \"Big Four\" in the Different World.","サラリーマンが異世界に行ったら四天王になった話"]', 1784690324156);
