INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhan-vien-van-phong-duoc-trieu-hoi-thanh-tu-dai-thien-vuong-o-the-gioi-khac', 'Nhân Viên Văn Phòng Được Triệu Hồi Thành Tứ Đại Thiên Vương Ở Thế Giới Khác', 'Headhunted to Another World: From Salaryman to Big Four!', 'nhân viên văn phòng được triệu hồi thành tứ đại thiên vương ở thế giới khác headhunted to another world: from salaryman to big four! yuki ono konomi kohara akio otsuka takanori hoshino nene hieda chitose morinaga ayami tsukui takaya kuroda tetsuo komura mitsuki saiga hidenobu kiuchi kengo kawanishi 平凡上班族到異世界當上了四天王的故事 平凡上班族到异世界当上了四天王的故事 上班族去了异世界后成了四天王 sararyman ga isekai ni ittara shitennou ni natta hanashi sararīman ga isekai ni ittara shitennō ni natta hanashi サラリーマン四天王 salaryman big 4 salaryman ga isekai ni ittara shitennou ni natta hanashi salaryman shitennou office worker has become "big four" in the different world. サラリーマンが異世界に行ったら四天王になった話', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('farmagia', 'Farmagia', 'Farmagia', 'https://phimimg.com/upload/vod/20250125-1/3ff96fb4aa1e62e02512d39d97002ccd.jpg', 'https://phimimg.com/upload/vod/20250125-1/63c7ade5879a748b1fcbffd2d41e5a64.jpg', '<p>Sau khi vị vua Felicidad băng hà, tên bạo chúa Glaza đã lãnh đạo một chế độ áp bức, khiến cư dân thế giới rơi vào cảnh thống khổ. Lãnh đạo cùng những người bạn Farmagia, Ten sẽ chỉ huy một đội quân quái vật, khám phá và chiến đấu qua những vùng đất hiểm nguy của Thế Giới Ngầm. Hãy thu thập tài nguyên để trở về trang trại, nơi bạn có thể nâng cao kỹ năng Farmagia, nuôi dưỡng thêm quái vật và phát triển các đặc điểm mới để chống lại Glaza và Oración Seis.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Takuya Sato","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Inori Minase","avatar":""},{"name":"Hiro Shimono","avatar":""},{"name":"Yuki Ishikari","avatar":""},{"name":"Reiou Tsuchida","avatar":""},{"name":"Kohei Amasaki","avatar":""},{"name":"Hiromichi Tezuka","avatar":""},{"name":"Shigeru Chiba","avatar":""},{"name":"Tetsu Inada","avatar":""},{"name":"Kenjiro Tsuda","avatar":""},{"name":"Ryusei Nakao","avatar":""},{"name":"Yoko Hikasa","avatar":""},{"name":"Koki Uchiyama","avatar":""},{"name":"Mikako Komatsu","avatar":""},{"name":"Atsumi Tanezaki","avatar":""},{"name":"Sayaka Ohara","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Farmagia","ファーマギア","FARMAGIA (ファーマギア)"]', 1784690324156);
