INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('farmagia', 'Farmagia', 'Farmagia', 'farmagia farmagia takuya sato ayane sakura inori minase hiro shimono yuki ishikari reiou tsuchida kohei amasaki hiromichi tezuka shigeru chiba tetsu inada kenjiro tsuda ryusei nakao yoko hikasa koki uchiyama mikako komatsu atsumi tanezaki sayaka ohara farmagia ファーマギア farmagia (ファーマギア)', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nuot-vang', 'Nuốt Vàng', 'Dear Hongrang', 'https://phimimg.com/upload/vod/20250516-1/f8277905a4a8731dc9c7f6b589fb7f12.jpg', 'https://phimimg.com/upload/vod/20250516-1/cb38f797ece91f4a5370b9c47ac1bb30.jpg', '<p>Vào cuối triều đại Joseon, một gia đình trở nên giàu có nhờ buôn bán đồ mỹ nghệ. Tuy nhiên, một biến cố bí ẩn xảy ra khi người con trai – Hong Rang – trở về sau mười năm mất tích, hoàn toàn không nhớ gì về thời thơ ấu. Jae I, người em gái cùng cha khác mẹ từng thân thiết với anh từ nhỏ, giờ đây quyết tâm tìm ra sự thật đằng sau sự biến mất bất ngờ này. Jae I, xinh đẹp và thông minh nhưng mang trong mình tính cách bất ổn, sống cùng mẹ kế bạo hành và người cha thờ ơ. Cô từng dựa dẫm vào Hong Rang, nhưng cuộc sống cô rơi vào bế tắc sau khi anh biến mất. Trong khi đó, Hong Rang – người từng sống trong nhung lụa – nay trở về để tìm kiếm danh tính thật sự của mình, một điều vẫn còn là ẩn số đối với tất cả mọi người.</p>', 'Full', 11, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Jae-wook","avatar":""},{"name":"Jo Bo-ah","avatar":""},{"name":"Jung Ga-ram","avatar":""},{"name":"Uhm Ji-won","avatar":""},{"name":"Park Byung-eun","avatar":""},{"name":"Kim Jae-wook","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Tangeum","탄금"]', 1784690324156);
