INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-vien-do-den', 'Học Viện Đỏ Đen', 'Bet', 'https://phimimg.com/upload/vod/20250516-1/b9d676bb8d72f0a44908fda4ad92d400.jpg', 'https://phimimg.com/upload/vod/20250516-1/a051bada065673ef180d7985b99aa964.jpg', '<p>Tại một trường tư thục nơi cờ bạc quyết định địa vị xã hội, một học sinh mới tài năng có quá khứ bí ẩn đang khuấy động mọi chuyện và quyết tâm trả thù.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2025, 'Vietsub + Lồng Tiếng', 'FHD', 'Canada', 0, '[{"name":"Miku Martineau","avatar":""},{"name":"Ayo Solanke","avatar":""},{"name":"Eve Edwards","avatar":""},{"name":"Clara Alexandrova","avatar":""},{"name":"Hunter Cardinal","avatar":""},{"name":"Anwen O''Driscoll","avatar":""},{"name":"Aviva Mongillo","avatar":""},{"name":"Ryan Sutherland","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["賭ケグルイ","Kakegurui","ベット","BET (ドラマ)","狂賭之淵","Kakegurui – Compulsive Gambler","Bet"]', 1784690324156);
