INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-doi-day-song', 'Cuộc Đời Dậy Sóng', 'Lost', 'https://phimimg.com/upload/vod/20250516-1/8c6721a128342b7296060140650a4e6a.jpg', 'https://phimimg.com/upload/vod/20250516-1/9b2ddfedde63f0477643c4f472df5327.jpg', '<p>Tae-hwa được ghép phổi từ người cha của mình — người vừa gây ra một vụ tai nạn bỏ trốn vào đêm trước ca phẫu thuật. Mang trong lòng cảm giác tội lỗi nặng nề, Tae-hwa quyết định tìm gặp con gái của nạn nhân, Mi-ji. Khi cuối cùng cũng tìm được cô, anh đề nghị đưa tiền như một cách bù đắp cho tội lỗi của cha mình. Nhưng Mi-ji lại đưa ra một yêu cầu khác: cô muốn anh giúp tìm người mẹ đã mất tích.</p>', 'Full', 1, 'single', 'completed', 41, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Soo-hyuk","avatar":""},{"name":"Ha Yoon-kyung","avatar":""},{"name":"Kwon Da-ham","avatar":""},{"name":"Lim Young-joo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["스토커","로스트","파란"]', 1784690324156);
