INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-chi-ke-xau-xi', 'Người Chị Kế Xấu Xí', 'The Ugly Stepsister', 'https://phimimg.com/upload/vod/20250516-1/30eb7f3c8d01d016603e70686155660e.jpg', 'https://phimimg.com/upload/vod/20250516-1/703a08630d17e4f33dfb158bb64552e1.jpg', '<p>The Ugly Stepsister (2025) là một bộ phim kinh dị lấy cảm hứng từ câu chuyện Cinderella, nhưng với góc nhìn đen tối và sâu sắc hơn. Phim xoay quanh Elvira, cô gái luôn bị xem là xấu xí và sống dưới cái bóng của người chị kế xinh đẹp Agnes. Khi mẹ kế Rebekka tìm cách lợi dụng con gái để đạt được quyền lực, Elvira bị ép phải thay đổi ngoại hình bằng những phương pháp tàn nhẫn. Trong cuộc đấu tranh giành sự chú ý của Hoàng tử Julian, cô trở nên ám ảnh với sắc đẹp, dần mất đi bản chất và bị cuốn vào những góc khuất của tham vọng.</p>', 'Full', 1, 'single', 'completed', 28, 2025, 'Vietsub', 'FHD', 'Đan Mạch', 0, '[{"name":"Lea Myren","avatar":""},{"name":"Ane Dahl Torp","avatar":""},{"name":"Thea Sofie Loch Næss","avatar":""},{"name":"Flo Fagerli","avatar":""},{"name":"Isac Calmroth","avatar":""},{"name":"Malte Gårdinger","avatar":""},{"name":"Ralph Carlsson","avatar":""},{"name":"Cecilia Forss","avatar":""},{"name":"Katarzyna Herman","avatar":""},{"name":"Adam Lundgren","avatar":""},{"name":"Willy Ramnek Petri","avatar":""},{"name":"Kyrre Hellum","avatar":""},{"name":"Isac Aspberg","avatar":""},{"name":"Albin Weidenbladh","avatar":""},{"name":"Oksana Czerkasyna","avatar":""},{"name":"Richard Fors","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Ha''Akhot Ha''Mekho''eret","Çirkin Ögey Bacı","Гадкая сестра","アグリーシスター","Ošklivá sestra","Den stygge stesøsteren"]', 1784690324156);
