INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-chi-ke-xau-xi', 'Người Chị Kế Xấu Xí', 'The Ugly Stepsister', 'người chị kế xấu xí the ugly stepsister lea myren ane dahl torp thea sofie loch næss flo fagerli isac calmroth malte gårdinger ralph carlsson cecilia forss katarzyna herman adam lundgren willy ramnek petri kyrre hellum isac aspberg albin weidenbladh oksana czerkasyna richard fors ha''akhot ha''mekho''eret çirkin ögey bacı гадкая сестра アグリーシスター ošklivá sestra den stygge stesøsteren', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-an-biet-thu-ma', 'Bí Ẩn Biệt Thự Ma', 'Aghathiyaa', 'https://phimimg.com/upload/vod/20250515-1/e0cedc618229faf6199f38bbc68c1d42.jpg', 'https://phimimg.com/upload/vod/20250515-1/1a00ea5b7d937b0bf5be7b540abe485f.jpg', '<p>Aghathiyan, một đạo diễn trẻ đang chật vật trong sự nghiệp và phải lo chữa bệnh cho mẹ, quyết định biến một biệt thự cổ ở Puducherry thành ngôi nhà ma để thu hút du khách. Trong quá trình cải tạo, anh phát hiện một cây đàn piano cổ và cuộn phim 8mm, hé lộ bí mật về một chuyện tình đau thương và cuộc chiến giữa cái thiện và cái ác thời thuộc địa.Aghathiyan dần nhận ra mình là hiện thân của Nanjilan, một chiến sĩ đã bị sát hại trong quá khứ. Cùng với bạn gái Veena và sự giúp đỡ của các linh hồn, anh đánh bại kẻ thù siêu nhiên Edwin Duplex và tìm ra phương pháp chữa bệnh cho mẹ bằng y học cổ truyền Siddha.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Jiiva","avatar":""},{"name":"Raashii Khanna","avatar":""},{"name":"Arjun Sarja","avatar":""},{"name":"Edward Sonnenblick","avatar":""},{"name":"Matilda","avatar":""},{"name":"Yogi Babu","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Methavi","Medhaavi","Methaavi","Medhavi","Agathiyaa","அகத்தியா"]', 1784690324156);
