INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('odessa-ban-tinh-ca-cua-so-phan', 'O''Dessa: Bản Tình Ca Của Số Phận', 'O''Dessa', 'https://phimimg.com/upload/vod/20250515-1/017df359631a90426951843e95c9c0fb.jpg', 'https://phimimg.com/upload/vod/20250515-1/15b87d2229d4f73ffd7a3698a078b321.jpg', '<p>Một cô gái nông thôn bước vào hành trình sử thi để tìm lại báu vật gia truyền quý giá. Cuộc phiêu lưu đưa cô đến một thành phố xa lạ và đầy hiểm nguy, nơi cô gặp được tình yêu đích thực của đời mình. Nhưng để cứu lấy linh hồn của anh, cô phải đối mặt với thử thách lớn nhất: đặt niềm tin vào định mệnh – và sức mạnh của âm nhạc.</p>', 'Full', 1, 'single', 'completed', 18, 2025, 'Vietsub', 'FHD', 'Brazil', 0, '[{"name":"Sadie Sink","avatar":""},{"name":"Kelvin Harrison","avatar":""},{"name":"Jr.","avatar":""},{"name":"Murray Bartlett","avatar":""},{"name":"Regina Hall","avatar":""},{"name":"Pokey LaFarge","avatar":""},{"name":"Mark Boone Junior","avatar":""},{"name":"Bree Elrod","avatar":""},{"name":"Dora Dimić Rakar","avatar":""},{"name":"Cora Sabo","avatar":""},{"name":"Luka Barešić","avatar":""},{"name":"Luca Anic","avatar":""},{"name":"Harry Cadby","avatar":""},{"name":"Bill Bekele","avatar":""},{"name":"Gea Erjavec","avatar":""},{"name":"Jimmy Mehs","avatar":""},{"name":"Marinko Prga","avatar":""},{"name":"Rithvik Andugula","avatar":""},{"name":"Aurora K","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["奥德萨","O''Dessa"]', 1784690324156);
