INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-la-trieu-giap-de-phong-mang', 'Tôi Là Triệu Giáp Đệ: Phong Mang', 'The Rise Of Zhao Jiadi', 'https://phimimg.com/upload/vod/20250502-1/390c4b9ab37311f6d15d7ed93f89d6f3.jpg', 'https://phimimg.com/upload/vod/20250502-1/e0a4166dc363595c020bfa5d9ebcc8a2.jpg', '<p>Triệu Giáp Đệ, cậu chủ tập đoàn Kim Hải vì không chấp nhận cách làm độc đoán và ngang ngược của bố nên đã từ bỏ suất tuyển thẳng vào hai trường Đại học Thanh Hoa và Đại học Bắc Kinh, chọn theo học một trường hạng ba vô danh. Không chỉ vậy, anh còn tuyên bố cược cả chục triệu, quyết tâm tự tay gây dựng nên đế chế kinh doanh của riêng mình! Tuy nhiên thành công của anh lại khiến đối thủ Trần Hồng Hùng trả thù, một trận phong ba chốn thương trường đang âm thầm kéo đến...</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đổng Hạo Nhiên","avatar":""},{"name":"Nguỵ Lộ","avatar":""},{"name":"Chung Lôi","avatar":""},{"name":"Trần Diệp Linh","avatar":""},{"name":"Dạ Dật","avatar":""},{"name":"Dương Lỗi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wo Jiao Zhao Jia Di Zhi Feng Mang","老子是癞蛤蟆","我叫赵甲第之锋芒"]', 1784690324156);
