INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('toi-la-trieu-giap-de-phong-mang', 'Tôi Là Triệu Giáp Đệ: Phong Mang', 'The Rise Of Zhao Jiadi', 'tôi là triệu giáp đệ: phong mang the rise of zhao jiadi đổng hạo nhiên nguỵ lộ chung lôi trần diệp linh dạ dật dương lỗi wo jiao zhao jia di zhi feng mang 老子是癞蛤蟆 我叫赵甲第之锋芒', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-nhan', 'Phu Nhân', 'Madam', 'https://phimimg.com/upload/vod/20250507-1/12321e1c7f2d06145a72f64d85d1074a.jpg', 'https://phimimg.com/upload/vod/20250507-1/3271c1194ba810362c8fbadc43f75c4c.jpg', '<p>Vào những năm Dân Quốc, tiểu thư hào môn gặp họa cả nhà bị giết sạch, hai mươi năm sau trở thành đệ nhất phu nhân Mặc Thành. Trong quá trình báo thù, cô lập khế ước máu với Long Thái tử kiêu ngạo và giao long lắm mưu mô, hai người trở thành vệ sĩ và nảy sinh tình cảm thầm kín với cô. Sau đó lại có thám tử đẹp trai gia nhập, tranh giành trái tim phu nhân. Cô được ba anh chàng tranh nhau theo đuổi, đồng thời khởi động lại cuộc điều tra vụ án cả nhà bị giết, mở ra câu chuyện truyền kỳ yêu hận đan xen thời Dân Quốc.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tiêu Vũ","avatar":""},{"name":"Trần Kiến Vũ","avatar":""},{"name":"Phổ Phổ","avatar":""},{"name":"Liu Shanglin","avatar":""},{"name":"Tất Thiếu Nham","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Fu Ren","Lady","夫人"]', 1784690324156);
