INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-tra-bosch-ke-thua-phan-3', 'Thanh Tra Bosch: Kế Thừa (Phần 3)', 'Bosch Legacy (Season 3)', 'https://phimimg.com/upload/vod/20250515-1/03c414be0f336338745c5372477583eb.jpg', 'https://phimimg.com/upload/vod/20250515-1/5c093d01cbe429232d93d02b164be10d.jpg', '<p>Hai năm sau khi rời khỏi Sở Cảnh sát Los Angeles (LAPD), Bosch hiện đang kiếm sống với công việc thám tử tư và bất ngờ hợp tác với kẻ từng là đối thủ – luật sư tài giỏi Honey “Money” Chandler. Trong khi đó, con gái của Bosch – Maddie – bắt đầu bước chân vào thế giới cảnh sát LAPD.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 22, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Titus Welliver","avatar":""},{"name":"Mimi Rogers","avatar":""},{"name":"Madison Lintz","avatar":""},{"name":"Stephen A. Chang","avatar":""},{"name":"Denise G. Sanchez","avatar":""},{"name":"Paul Calderon","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bosch: Legacy","Bosch: O Legado - A Temporada Final","博斯：传承","博斯：最终遗产","Bosch - Legacy","Bosch: Örökség","بوش: میراث","ボッシュ: 受け継がれるもの","보쉬: 레거시","Bosch: Dziedzictwo","Босх: Наследие","Untitled ''Bosch'' Spinoff","Kế Thừa"]', 1784690324156);
