INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ga-nham-nguoi', 'Gả Nhầm Người', 'Reborn In Vengeance', 'https://phimimg.com/upload/vod/20250515-1/73d3a7438ad1d4a4c3e2f7db61180763.jpg', 'https://phimimg.com/upload/vod/20250515-1/c8200e9c894e1f51c0243030c93be5b9.jpg', '<p>Goá phụ trẻ tuổi Lục Ninh An hết lòng chăm lo gia đình phu quân Tạ Vân Vọng, giúp con nuôi Tạ Tử Thần công thành danh toại. Nào ngờ đến lúc sắp xuống suối vàng, nàng mới phát hiện ra Tạ Vân Vọng chỉ giả chết, Tạ Tử Thần giả vờ nhân nghĩa, tình nhân Lâm Uyển Nhi thì ngang ngược lộng hành. Sống lại kiếp này, Lục Ninh An trở nên mạnh mẽ hơn bao giờ hết. Nàng đứng lên đấu trí với đôi gian phu dâm phụ, trừng trị Tạ gia để tự cứu lấy chính mình.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 33, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Sở Hiên","avatar":""},{"name":"Khổng Kỳ Lực","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324156);
