INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-la-trieu-giap-de-2', 'Tôi Là Triệu Giáp Đệ 2', 'Zhao Jiadi 2', 'https://phimimg.com/upload/vod/20250428-1/d9823d7fa92f638a420949efbea2e0e5.jpg', 'https://phimimg.com/upload/vod/20250428-1/5fc363bb231bdf92b0cbf4a01ce40cbc.jpg', '<p>Trong phần 1, sau bao gian nan, Triệu Giáp Đệ đã hòa giải với cha là Triệu Hâm, bất ngờ đến Kim Hải, tràn đầy nhiệt huyết cải cách Kim Hải rầm rộ. Thế nhưng, Triệu Hâm không hề thực sự muốn nhường lại quyền lực, hai cha con đấu đá công khai lẫn ngấm ngầm, mở ra nhiều cuộc đối đầu gay gắt cả trong lẫn ngoài Kim Hải. Cùng lúc đó, kẻ thù cũ của Triệu Hâm từ phía Nam cũng phái người âm thầm hành động, những vết thương mới và hận thù cũ đồng loạt bùng phát. Triệu Giáp Đệ một lần nữa xa cách cha mình kiên quyết rời khỏi Kim Hải, cố ý chọn Hàng Thành, nơi đối đầu gay gắt không đội trời chung với Triệu Hâm, tay trắng lập nghiệp, rũ bỏ sự hào nhoáng, hòa mình vào cõi đời, ẩn mình giấu tài trưởng thành mạnh mẽ, tự tay viết nên huyền thoại cho riêng mình, cho đến khi leo lên đỉnh cao mà cả Triệu Hâm cũng khó bề với tới. Cuối cùng anh đã có thể nói ra câu mà khi rời đi đã chôn sâu trong lòng: &quot;Tuy không thể lựa chọn cách mình sinh ra, nhưng sống ra sao thì có thể.&quot;</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 32, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hà Bằng","avatar":""},{"name":"Đinh Tiểu Anh","avatar":""},{"name":"Linh Trác","avatar":""},{"name":"Thường Địch","avatar":""},{"name":"Dương Kỳ Nhu","avatar":""},{"name":"Quách Tưởng Bằng","avatar":""},{"name":"Dương Vũ Tâm","avatar":""},{"name":"Vương Chính","avatar":""},{"name":"Bành Tĩnh","avatar":""},{"name":"Trương Hạo Nguyệt","avatar":""},{"name":"Chu Tĩnh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Wo Jiao Zhao Jia Di","我叫赵甲第2","老子是癞蛤蟆","My Name Is Zhao Jiadi","My Name is Zhao Jia Di","我叫赵甲第"]', 1784690324156);
