INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ran-va-thang', 'Rắn Và Thang', 'Snakes and Ladders', 'https://phimimg.com/upload/vod/20250515-1/a3150d4c1013e8b2060c8318e82cafc5.jpg', 'https://phimimg.com/upload/vod/20250515-1/af890a7f21e229b73f97c09576dfc11f.jpg', '<p>Muốn trở thành hiệu trưởng ngôi trường danh tiếng, vị giáo viên đầy tham vọng nhưng bị phớt lờ nọ phải leo lên những nấc thang đầy dối trá và tham nhũng để đạt đến đỉnh cao.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Mexico', 0, '[{"name":"Cecilia Suárez","avatar":""},{"name":"Juan Pablo Medina","avatar":""},{"name":"Martiño Rivas","avatar":""},{"name":"Marimar Vega","avatar":""},{"name":"Benny Emmanuel","avatar":""},{"name":"Loreto Peralta","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Snakes & Ladders","Serpientes y escaleras"]', 1784690324156);
