INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ran-va-thang', 'Rắn Và Thang', 'Snakes and Ladders', 'rắn và thang snakes and ladders cecilia suárez juan pablo medina martiño rivas marimar vega benny emmanuel loreto peralta snakes & ladders serpientes y escaleras', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mui-huong-cua-bi-mat', 'Mùi Hương Của Bí Mật', 'Scent Of Secrets', 'https://phimimg.com/upload/vod/20250515-1/31d8e18661b219e76d3a54b2d9705a5a.jpg', 'https://phimimg.com/upload/vod/20250515-1/e56a20c56aeafc74799bbe6539a1167c.jpg', '<p>Thanh Đại và Hồng Quả cùng điều hành một trà lâu độc đáo mang tên Tam Hương, một người quyến rũ bí ẩn, một người đáng yêu kỳ quặc. Thế nhưng, khi màn đêm buông xuống, họ lại hóa thân thành những tên &quot;siêu đạo chích&quot;, chuyên trộm cắp – nhưng mục tiêu không phải vàng bạc, mà là các cổ vật liên quan đến vụ án “Thanh Quỷ đại đạo” mười năm trước: bức bình phong Tứ Mỹ và trấn chỉ thanh đồng. Phía quan phủ, hai vị tham tướng của nha môn tuần bộ doanh – Mặc Trạch và Tiêu Úy – được giao nhiệm vụ truy bắt nhóm đạo tặc này. Một người chính trực, mạnh mẽ; người kia trung hậu, hơi ngốc nhưng đầy nghĩa khí. Mặc Trạch dần phải lòng Thanh Đại, còn Tiêu Úy và Hồng Quả cũng trở thành cặp đôi oan gia đầy thú vị. Việc bức Tứ Mỹ bình phong liên tục bị đánh cắp đã khiến Hỏa khí doanh Đề đốc Hà Tiêu và Chỉ huy sứ Phùng Thần của Củng Vệ Ty chú ý. Hai thế lực âm thầm nhập cuộc, âm mưu giăng bẫy – nhưng cũng chính nhờ đó mà mọi bí mật dần được phơi bày, từ thân phận thật của từng người cho đến sự thật chấn động bị chôn giấu suốt mười năm trước.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cheng Zixin","avatar":""},{"name":"He Ziyi","avatar":""},{"name":"Gao Kai","avatar":""},{"name":"Shang Xuan","avatar":""},{"name":"Pang Zhenqi","avatar":""},{"name":"Ma Jianxun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["暗香浮动月黄昏"]', 1784690324156);
