INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('fred-va-rose-west-noi-kinh-hoang-nuoc-anh', 'Fred Và Rose West: Nỗi Kinh Hoàng Nước Anh', 'Fred and Rose West: A British Horror Story', 'https://phimimg.com/upload/vod/20250515-1/d04a1c021e9abaace49a8d1993738d51.jpg', 'https://phimimg.com/upload/vod/20250515-1/1742d0a294a9f8a2853a153dc2750805.jpg', '<p>Bản ghi âm của cảnh sát mới khám phá gần đây và lời kể của người trong cuộc hé lộ chuyện về Fred và Rose West, hai trong số những sát nhân hàng loạt khét tiếng nhất Vương quốc Anh.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Fred West","avatar":""},{"name":"Rose West","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Fred and Rose West: A British Horror Story"]', 1784690324156);
