INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('fred-va-rose-west-noi-kinh-hoang-nuoc-anh', 'Fred Và Rose West: Nỗi Kinh Hoàng Nước Anh', 'Fred and Rose West: A British Horror Story', 'fred và rose west: nỗi kinh hoàng nước anh fred and rose west: a british horror story fred west rose west fred and rose west: a british horror story', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-hoa-hong', 'Cuộc Chiến Hoa Hồng', 'War Of The Roses', 'https://phimimg.com/upload/vod/20250515-1/f737da0ad418c3adb3031b1a64ba0d57.jpg', 'https://phimimg.com/upload/vod/20250515-1/72e35d514ffdd40d2a9d5a7e1e7601b6.jpg', '<p>Hai mươi năm trước, Lý Kiệt – một sinh viên ưu tú của trường Luật – bị tước quyền học tiếp cao học vì từ chối giao dịch tình dục với giáo sư Triệu Chính Hoa. Không những thế, cô còn bị bạn cùng phòng là Trịnh Nam vu khống gian lận học thuật và bị đuổi học. Mang theo bí mật, cô đổi tên thành Lý Nhất Minh, một mình nuôi con gái Lý An Lạc khôn lớn. Hai mươi năm sau, Lý An Lạc gia nhập công ty truyền thông Hồ Quang và bị tổng tài Tôn Thiện Quân quấy rối. Hành động livestream nhảy cầu tố cáo của cô đã đánh thức ký ức đau thương mà mẹ cô đã chôn giấu suốt hai thập kỷ. Trong quá trình điều tra sự thật, Lý Nhất Minh phát hiện Tôn Thiện Quân có mối quan hệ lợi ích mờ ám với Triệu Chính Hoa. Đồng thời, cô cũng bất ngờ biết được những góc khuất của hai người bạn cũ: – Trịnh Nam, nay là luật sư tại một công ty luật danh tiếng, đang rơi vào vòng xoáy tình cảm và đạo đức; – Văn San, người đang duy trì một cuộc hôn nhân giả vì lợi ích thương mại.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Shuyan","avatar":""},{"name":"Xiao Ranxin","avatar":""},{"name":"Wang Xi","avatar":""},{"name":"Chen Meilin","avatar":""},{"name":"Bai Yu","avatar":""},{"name":"Guan Mingyang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["披荆斩棘的姐姐","玫瑰的战争","Mei Gui De Zhan Zheng","Up Sisters"]', 1784690324156);
