INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-mang-chui', 'Làng Mắng Chửi', 'Welcome, Now Get Lost', 'https://phimimg.com/upload/vod/20250515-1/efda312190ef0cfcb2bf68c232769c99.jpg', 'https://phimimg.com/upload/vod/20250515-1/0d61a2ff9774ef6b82b6aa25baffae2b.jpg', '<p>Đối mặt với cơn lốc cảm xúc, các cây hài chịu sự lăng mạ không ngừng từ dân làng đang tức giận. Liệu họ có thể biến sự thù địch thành tiếng cười? Higashino Koji dẫn chương trình.</p>', 'Full', 1, 'tvshows', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Koji Higashino","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324156);
