INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-hong-thep', 'Hoa Hồng Thép', 'Steel Rose', 'https://phimimg.com/upload/vod/20250515-1/8ad33f81411537d024aed9422d7b08a9.jpg', 'https://phimimg.com/upload/vod/20250515-1/3832277b6f259a3e2887452ee251b9f7.jpg', '<p>Bản phim kể về các thành viên đội đặc nhiệm nữ của thành phố Lĩnh Bắc thâm nhập vào một tổ chức tội phạm đánh bạc xuyên quốc gia. Tiêu Thần đã thành công xâm nhập vào &quot;Cách Lỗ Tây Ban&quot; và phối hợp với nhóm chuyên án từ trong ra ngoài, một mẻ lưới triệt phá ổ tội phạm này, đồng thời bắt giữ thành công thủ lĩnh Tiêu Dương. Tuy nhiên, lúc này Tiêu Thần phát hiện ra rằng, đằng sau mọi tội ác còn ẩn giấu một nhân vật bí ẩn được gọi là &quot;anh Hổ&quot;.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"许月庆","avatar":""},{"name":"An Zehao","avatar":""},{"name":"卢鑫","avatar":""},{"name":"Ai Lin","avatar":""},{"name":"He Yongsheng","avatar":""},{"name":"Su Guotao","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["霹雳玫瑰"]', 1784690324156);
