INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-gioi-the-thao-vua-gan-song', 'Bí Mật Giới Thể Thao: Vua Gan Sống', 'Untold: The Liver King', 'https://phimimg.com/upload/vod/20250515-1/34546bdb9f34c524f22b088d76f45720.jpg', 'https://phimimg.com/upload/vod/20250515-1/a8e9fad54ecba1ff00d338c04e298a0e.jpg', '<p>Anh xây dựng đế chế thực phẩm chức năng bằng cách ăn sống trên mạng xã hội. Và anh có cơ bắp để chứng minh điều đó. Nhưng thực sự thì Vua Gan sống trở thành &quot;tay to&quot; bằng cách nào?</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Brian Johnson","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Untold: The Liver King"]', 1784690324156);
