INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truot-doc-2025', 'Trượt Dốc', 'Crypto Man', 'https://phimimg.com/upload/vod/20250515-1/74f8f3170bf003aa068002146f4f92ad.jpg', 'https://phimimg.com/upload/vod/20250515-1/3dc6f41b4fd095c6fa62cdec3171dc2b.jpg', '<p>Ok Ja và con trai Do Hyun giả đăng ký hộ khẩu tại phường Daechi (Seoul) để mong con được học trường tốt, dù hoàn cảnh tài chính eo hẹp. Tại trường, Do Hyun ghen tị với bạn học Sang Su – người được hưởng trợ cấp khuyết tật dù thực tế không bị tật nguyền, từ đó phơi bày những kẽ hở trong chính sách phúc lợi nhà nước. Khi vào đại học, Do Hyun cùng bạn mới Ji Woo tiếp tục lợi dụng các chính sách hỗ trợ khởi nghiệp, cố tình thất bại để trục lợi từ sự dễ dãi của hệ thống chính sách hỗ trợ tín dụng. Tham vọng lớn dần, Do Hyun hợp tác với nhà đầu tư Kevin để bước chân vào thế giới tiền mã hóa đầy rủi ro, gạt Ji Woo sang một bên. Trong chốc lát, họ nếm mùi thành công, nhưng nhanh chóng bị bóc trần bởi các cơ quan quản lý. Họ cố &quot;dùng tiền lớn để kiếm tiền lớn hơn&quot;, nhưng cuối cùng lại tạo ra một &quot;doanh nghiệp tử thần&quot;.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Song Jae-rim","avatar":""},{"name":"An Woo-yeon","avatar":""},{"name":"Min Sung-wook","avatar":""},{"name":"So Hee-jung","avatar":""},{"name":"Cha Jung-won","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["사업만 6번 망한 남자","폭락: 사업 망한 남자","Death Business","加密男","폭락"]', 1784690324156);
