INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-dam-lay', 'Quái Vật Đầm Lầy', 'The Bayou', 'https://phimimg.com/upload/vod/20250515-1/6c947d61a4cf11a1660b03ed016e302d.jpg', 'https://phimimg.com/upload/vod/20250515-1/5787cec877bf6d532bfa6486468f914c.jpg', '<p>Kyle, một sinh viên sinh học vừa tốt nghiệp, cùng nhóm bạn của mình thực hiện chuyến đi đến Florida để rải tro cốt của người anh trai quá cố. Tuy nhiên, chuyến đi trở thành thảm họa khi chiếc máy bay nhỏ chở họ gặp sự cố và rơi xuống vùng đầm lầy hoang vu của Louisiana. Tại đây, họ phải đối mặt với mối đe dọa từ những con cá sấu bị biến đổi do tiếp xúc với chất hóa học từ một phòng thí nghiệm ma túy bị DEA triệt phá. Những con cá sấu này trở nên hung dữ và nguy hiểm hơn bao giờ hết, khiến cuộc chiến sinh tồn của nhóm người sống sót trở nên khốc liệt.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Elisha Applebaum","avatar":""},{"name":"Madalena Aragão","avatar":""},{"name":"David Newman","avatar":""},{"name":"Sarah Priddy","avatar":""},{"name":"Andonis Anthony","avatar":""},{"name":"Athena Strates","avatar":""},{"name":"Isabelle Bonfrer","avatar":""},{"name":"Tayla Kovacevic-Ebong","avatar":""},{"name":"Mohammed Mansaray","avatar":""},{"name":"Flynn Barnard","avatar":""},{"name":"Evan Sokol","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Gator Creek","بايو","باتلاق","沼泽之地","Infierno en el Pantano","Smrtonosno močvirje","The Bayou"]', 1784690324156);
