INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoai-thuy-truc-dinh', 'Hoài Thủy Trúc Đình', 'Love In Pavilion', 'https://phimimg.com/upload/vod/20250428-1/f08ef7298b7fcf7bfa367ab76d36c1a2.jpg', 'https://phimimg.com/upload/vod/20250428-1/223ac4ea48489c5ea7c12b35a788c837.jpg', '<p>Đông Phương Hoài Trúc người đứng đầu gia tộc Đông Phương và Vương Quyền Bá Nguyệt người đứng đầu gia tộc Vương Quyền cùng nhau nỗ lực ổn định lại tình hình và thiết lập lại liên minh hợp nhất. Ngày mùng 7 tháng 7 âm lịch tại ngôi đền bên sông Hoài, hai người nương tựa vào nhau, hứa rằng tình cảm của họ sẽ vượt qua được mọi khó khăn, viết nên câu chuyện dài lâu.</p>', 'Hoàn Tất (37/37)', 37, 'series', 'completed', 9, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Thi Thi","avatar":""},{"name":"Trương Vân Long","avatar":""},{"name":"Ngô Tuyên Nghi","avatar":""},{"name":"Thẩm Nguyệt","avatar":""},{"name":"Đinh Vũ Hề","avatar":""},{"name":"Trác Tiêu Văn","avatar":""},{"name":"Chương Nhược Nam","avatar":""},{"name":"Mạnh Tử Nghĩa","avatar":""},{"name":"Chu Khiết Quỳnh","avatar":""},{"name":"Triệu Nhất Bác","avatar":""},{"name":"Hầu Minh Hạo","avatar":""},{"name":"Trần Hựu Duy","avatar":""},{"name":"Từ Dực Hiên","avatar":""},{"name":"Triệu Tân Bân","avatar":""},{"name":"Trần Nhược Hiên","avatar":""},{"name":"Bành Tiểu Nhiễm","avatar":""},{"name":"Trần Ngọc Kỳ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d8539