INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoai-thuy-truc-dinh', 'Hoài Thủy Trúc Đình', 'Love In Pavilion', 'hoài thủy trúc đình love in pavilion lưu thi thi trương vân long ngô tuyên nghi thẩm nguyệt đinh vũ hề trác tiêu văn chương nhược nam mạnh tử nghĩa chu khiết quỳnh triệu nhất bác hầu minh hạo trần hựu duy từ dực hiên triệu tân bân trần nhược hiên bành tiểu nhiễm trần ngọc kỳ fox spirit matchmaker: zhu ye 狐妖小红娘·竹业篇 竹业篇 淮水竹亭 狐妖小红娘竹业篇 縁結びの妖狐ちゃん 竹業篇 호요소홍란 죽엽편 เรือนรักป่าไผ่ fox spirit matchmaker 2 fox spirit matchmaker: love in pavilion hồ yêu tiểu hồng nương nguyệt hồng thiên hồ yêu tiểu hồng nương: trúc nghiệp thiên', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-em-tranh-dau', 'Chị Em Tranh Đấu', 'The Twin Gambit', 'https://phimimg.com/upload/vod/20250320-1/b8285c511c0389f7b521b93c99105107.jpg', 'https://phimimg.com/upload/vod/20250320-1/1193efc8e32e6134155593b467699a3e.jpg', '<p>Chị Em Tranh Đấu là câu chuyện về hai chị em sinh đôi có tính cách trái ngược nhưng lại buộc phải đổi danh tính cho nhau. Cream và Cake tuy là song sinh nhưng tính tình lại khác biệt: một người mạnh mẽ, cá tính, còn người kia thì lại dịu dàng, nữ tính. Cuộc sống của cả hai bị đảo lộn khi họ phải đổi danh tính cho người kia để phát triển sự nghiệp. Tuy nhiên, kế hoạch của Cream và Cake bắt đầu trở nên rối ren khi cả hai cùng đem lòng yêu một chàng trai.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 8, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Pooklook Fonthip Watcharatrakul","avatar":""},{"name":"Mew Suppasit Jongcheveevat","avatar":""},{"name":"Bank Artit Tangwiboonpanit","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Gimme a Break!"]', 1784690324156);
