INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-thep', 'Chiến Binh Thép', 'Tin Soldier', 'https://phimimg.com/upload/vod/20250513-1/fe7676ab727a3e6d6b6e1c3a50ee3938.jpg', 'https://phimimg.com/upload/vod/20250513-1/930a520156695783081ea1d377cc56e4.jpg', '<p>&quot;Tin Soldier&quot; kể về một tổ chức bán quân sự bí ẩn do một thủ lĩnh có sức lôi cuốn tên là Bokushi (Jamie Foxx) đứng đầu. Ông ta chiêu mộ các cựu binh bị xã hội bỏ rơi, hứa hẹn cho họ một cuộc sống mới và đầy mục đích — nhưng thực chất đang thao túng họ cho những mục tiêu nguy hiểm.Một người lính từng bị tổ chức này cuốn vào (Scott Eastwood) quyết định đứng lên chống lại, hợp tác với một đặc vụ kỳ cựu (Robert De Niro) được chính phủ cử đi truy quét Bokushi. Cả hai lao vào một cuộc chiến cam go, không chỉ với kẻ thù bên ngoài, mà còn với những tổn thương tâm lý chiến tranh và niềm tin bị bóp méo.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Scott Eastwood","avatar":""},{"name":"Robert De Niro","avatar":""},{"name":"Jamie Foxx","avatar":""},{"name":"John Leguizamo","avatar":""},{"name":"Nora Arnezeder","avatar":""},{"name":"Shamier Anderson","avatar":""},{"name":"Yul Vazquez","avatar":""},{"name":"Rita Ora","avatar":""},{"name":"Saïd Taghmaoui","avatar":""},{"name":"Eire Farrell","avatar":""},{"name":"Alexa Feinstein","avatar":""},{"name":"Xen Sams","avatar":""},{"name":"Laurence Mason","avatar":""},{"name":"Joey Bicicchi","avatar":""},{"name":"Christian George","avatar":""},{"name":"Melanie Benz","avatar":""},{"name":"Julanne Chidi Hill","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Cínový vojáček","Оловянный солдатик","Código Venganza","Tin Soldier","Soldado de Chumbo","The Tin Soldier","Tinasõdur","Ólomkatona","Игры возмездия","Tin Soldier: Agente Infiltrado","Agente infiltrado","Kurşun Asker"]', 1784690324156);
