INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-tam-man-che', 'Bảy Tấm Màn Che', 'Seven Veils', 'https://phimimg.com/upload/vod/20250513-1/1bdd3fc58bb05c76bfa5769cbe01a45e.jpg', 'https://phimimg.com/upload/vod/20250513-1/624fe96e5c1ee9587696565b6b288935.jpg', '<p>Jeanine là một đạo diễn sân khấu nghiêm túc và tận tâm. Khi được mời dàn dựng lại vở opera Salome nổi tiếng của người thầy cũ, cô phải đối mặt với những ký ức u ám từng bị chôn giấu. Trở lại với thế giới sân khấu sau nhiều năm rút lui, Jeanine dần nhận ra quá khứ đau thương vẫn còn đè nặng, và bắt đầu ảnh hưởng đến mọi thứ cô đang làm.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Amanda Seyfried","avatar":""},{"name":"Rebecca Liddiard","avatar":""},{"name":"Douglas Smith","avatar":""},{"name":"Mark O''Brien","avatar":""},{"name":"Vinessa Antoine","avatar":""},{"name":"Ambur Braid","avatar":""},{"name":"Michael Kupfer-Radecky","avatar":""},{"name":"Tara Nicodemo","avatar":""},{"name":"Maia Jae Bastidas","avatar":""},{"name":"Lynne Griffin","avatar":""},{"name":"Lanette Ware","avatar":""},{"name":"Maya Misaljevic","avatar":""},{"name":"Joey Klein","avatar":""},{"name":"Aliya Kanani","avatar":""},{"name":"Siobhan Richardson","avatar":""},{"name":"Michae","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Seven Veils"]', 1784690324156);
