INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-bach-tuyet', 'Nàng Bạch Tuyết', 'Snow White', 'https://phimimg.com/upload/vod/20250513-1/550dbe6c84d50f68ab393e6a998c9a86.jpg', 'https://phimimg.com/upload/vod/20250513-1/c25ef0bee338353d052354d7ca12c12f.jpg', '<p>Câu chuyện của Nàng Bạch Tuyết ban đầu cũng giống như cổ tích, khi nàng công chúa mới chào đời, mang niềm vui và sự ấm áp tới cả vương quốc xinh đẹp. Mẹ mất sớm, cha bao bọc nàng bằng tất cả tình yêu thương, dạy nàng phải sống không sợ hãi, công bằng, dũng cảm và chân thành. Bạch Tuyết càng lớn lên càng lay động lòng người, với vẻ đẹp thuần khiết như ánh nắng ban mai và một trái tim thiện lương, nhân hậu. Thế nhưng, những ngày tháng vui vẻ không kéo dài lâu khi cha cô cũng qua đời. Ngày hoàng hậu mới lên ngôi, bóng tối bao trùm cả vương quốc. Độc ác và đầy dã tâm, ả không có lòng khoan dung, sẵn sàng trừng phạt bất cứ ai dám làm trái lệnh. Sự ghen ghét, đố kỵ của mẹ kế đẩy Bạch Tuyết vào cảnh nguy hiểm. Nàng phải chạy trốn vào rừng sâu, nơi cuộc phiêu lưu của nàng bắt đầu với những người bạn tốt bụng mới.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Rachel Zegler","avatar":""},{"name":"Gal Gadot","avatar":""},{"name":"Andrew Burnap","avatar":""},{"name":"Jeremy Swift","avatar":""},{"name":"Jason Kravits","avatar":""},{"name":"Martin Klebba","avatar":""},{"name":"George Salazar","avatar":""},{"name":"Tituss Burgess","avatar":""},{"name":"Andy Grotelueschen","avatar":""},{"name":"Andrew Barth Feldman","avatar":""},{"name":"Ansu Kabia","avatar":""},{"name":"Patrick Page","avatar":""},{"name":"Emilia Faucher","avatar":""},{"name":"Hadley Fraser","avatar":""},{"name":"Lorena Andrea","avatar":""},{"name":"George Appleby","avatar":""},{"name":"Colin Mi","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Disney''s Snow White","Borëbardha","שלגיה ושבעת הגמדים","白雪公主真人版","سنووايت","Snow White","Սպիտակաձյունիկը","Spitakadzyuniky","Biancaneve","Da Disney Branca de Neve","Branca de Neve da Disney","Disney''s Snow White Sing-Along"]', 1784690324156);
