INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xuyen-khong-ve-co-dai-lam-phap-y', 'Xuyên Không Về Cổ Đại Làm Pháp Y', 'Coroner''s Time Trial', 'https://phimimg.com/upload/vod/20250424-1/c71ce503f63710a16e00028b41c3db27.jpg', 'https://phimimg.com/upload/vod/20250424-1/e20b0f011f95ec99e4ff67d983266af2.jpg', '<p>Một nữ pháp y tài ba của thế kỷ 21 bất ngờ xuyên không khi đang đi khám nghiệm hiện trường, mà trớ trêu thay lại xuyên đến... giữa một đống xác chết. Cô tỉnh dậy đúng lúc bị nghi ngờ là hung thủ đang dùng dao rạch thi thể các cô gái tại hiện trường. Sau nhiều hiểu lầm và biến cố, cô – Lục Nhất Nam, hợp tác cùng thiếu khanh Đại Lý Tự Nhâm Chi Sơ và hiệp khách giang hồ thần bí Nhiếp Kỳ Huyền lập thành tổ phá án ba người. Cả nhóm cùng nhau điều tra những vụ án ly kỳ, minh oan cho người sống và tìm lại công lý cho người đã khuất...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 25, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tân Ngọc","avatar":""},{"name":"Trần Tư Vũ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324156);
