INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-la-nang-am-ban-trua-cua-em', 'Anh Là Nắng Ấm Ban Trưa Của Em', 'Marry To The Enemy Of My Enemy', 'https://phimimg.com/upload/vod/20250428-1/9571582839d719e98ccb52b1abfa8efa.jpg', 'https://phimimg.com/upload/vod/20250428-1/7528dd0caf5583245fb7b7821faf5fbf.jpg', '<p>Cô gái tốt bụng Hạ Noãn đã tìm được người hiến thận ở Nam Á cho người chị cùng cha khác mẹ đang mắc bệnh thận của mình. Sau khi đến nơi, cô phát hiện ra rằng quả thận của cô chính là quả thận mà chị gái cùng cha khác mẹ của cô muốn có. Khi biết sự thật, cuối cùng cô cũng nhìn thấu được cha dượng và chị gái cùng cha khác mẹ bề ngoài có vẻ hiền lành nhưng thực chất lại có ý đồ xấu. Với sự giúp đỡ của tên côn đồ ngầm Nam Á Trung Hân Dương, Hạ Noãn đã bất ngờ trở về tại đám tang mà cha dượng cô đã “cẩn thận” tổ chức cho cô…</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hàn Đông","avatar":""},{"name":"Điền Hiên Ninh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ni Shi Wo De Zheng Wu Nuan Yang","你是我的正午暖陽","我的正午暖阳","我的正午暖陽","Wo De Zheng Wu Nuan Yang","你是我的正午暖阳"]', 1784690324156);
