INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jane-phan-3', 'Jane (Phần 3)', 'Jane (Season 3)', 'https://phimimg.com/upload/vod/20250512-1/fe3fb12f3de818b054da6e8b8e729246.jpg', 'https://phimimg.com/upload/vod/20250512-1/4314abc61584544498dbd0136799e921.jpg', '<p>Nhà bảo vệ môi trường đầy hứa hẹn Jane là một cô bé 9 tuổi đang thực hiện nhiệm vụ cứu các động vật đang bị đe dọa. Sử dụng trí tưởng tượng mạnh mẽ của mình, Jane đưa những người bạn thân nhất của mình là David và chú tinh tinh Greybeard vào các cuộc phiêu lưu kì thú để giúp bảo vệ động vật hoang dã trên toàn thế giới.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Ava Louise Murchison","avatar":""},{"name":"Mason Blomberg","avatar":""},{"name":"Dan Abramovici","avatar":""}]', '[{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["珍爱地球大冒险","珍要救地球","ג''יין","Jane"]', 1784690324156);
