INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-thanh-thuy-ha-trung-sinh', 'Thám Thanh Thủy Hà: Trùng Sinh', 'Predestination', 'https://phimimg.com/upload/vod/20250512-1/71659a8612ab3707846edf1845e40257.jpg', 'https://phimimg.com/upload/vod/20250512-1/daa5562fa1175d0e0048e12f0184f66e.jpg', '<p>Chuyện xảy ra vào thời Dân Quốc, cậu học trò xiếc hài lêu lổng Tông Tiểu Lục quyết tâm giải cứu Đại Liên khỏi cuộc hôn nhân ép buộc. Hành trình giải cứu đầy rẫy nguy hiểm, Tiểu Lục thông minh đối đầu với thế lực quyền quý, tưởng chừng sắp vượt ải thành công thì lại vô tình rơi vào mê cung thời không, vất vả tìm cách xuyên không trở lại. Cùng lúc đó, một âm mưu giết người được ấp ủ từ lâu sắp sửa diễn ra, và bí mật được Đại Liên che giấu bấy lâu cũng dần lộ diện.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Liu Siwei","avatar":""},{"name":"Jing Ruyang","avatar":""},{"name":"Zhang Qi","avatar":""},{"name":"Liang Tian","avatar":""},{"name":"Chen Jianan","avatar":""},{"name":"Shang Tielong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Exploring the Clear Water River: Rebirth","Tan Qingshui River: Rebirth","探清水河：重生"]', 1784690324156);
