INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sieu-canh-khuyen', 'Siêu Cảnh Khuyển', 'Dog Man', 'https://phimimg.com/upload/vod/20250512-1/0b3b6767532eda0429ba8fc48c4b81b9.jpg', 'https://phimimg.com/upload/vod/20250512-1/8fc7e83b01f3513e1a4221f1209377ac.jpg', '<p>Câu chuyện bắt đầu khi sĩ quan cảnh sát Knight và chú chó nghiệp vụ Greg bị thương nặng trong một vụ nổ do âm mưu của mèo ác nhân Petey. Để cứu cả hai, các bác sĩ quyết định thực hiện một ca phẫu thuật ghép đôi, kết hợp đầu của Greg với thân thể của Knight, tạo nên Dog Man – một anh hùng nửa người nửa chó. Với bản năng trung thành của loài chó và trí tuệ của con người, Dog Man phải đối mặt với những kế hoạch xấu xa của Petey. Tình tiết trở nên phức tạp khi Petey tạo ra bản sao của mình, Lil Petey, nhưng Lil Petey lại hình thành mối quan hệ đặc biệt với Dog Man. Khi Lil Petey bị bắt cóc, Dog Man và Petey buộc phải hợp tác để giải cứu chú mèo con, dẫn đến những tình huống hài hước và cảm động.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Peter Hastings","avatar":""},{"name":"Pete Davidson","avatar":""},{"name":"Lil Rel Howery","avatar":""},{"name":"Isla Fisher","avatar":""},{"name":"Lucas Hopkins Calderon","avatar":""},{"name":"Ricky Gervais","avatar":""},{"name":"Poppy Liu","avatar":""},{"name":"Stephen Root","avatar":""},{"name":"Billy Boyd","avatar":""},{"name":"Luenell","avatar":""},{"name":"Laraine Newman","avatar":""},{"name":"Melissa Villaseñor","avatar":""},{"name":"Cheri Oteri","avatar":""},{"name":"Kate Micucci","avatar":""},{"name":"Maggie Wheeler","avatar":""},{"name":"Pearce Bunting","avatar":""},{"name":"Max Koch","avatar":""},{"name":"Rahnu","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{