INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('de-quoc-maratha-cuoc-chien-cuoi-cung', 'Đế Quốc Maratha: Cuộc Chiến Cuối Cùng', 'Chhaava', 'https://phimimg.com/upload/vod/20250511-1/1783dfd5d006c2be398cd70fdc23e952.jpg', 'https://phimimg.com/upload/vod/20250511-1/8f392bf391d64129004f4878489c2b49.jpg', '<p>Chhaava là phim hành động - lịch sử Ấn Độ kể về Chhatrapati Sambhaji Maharaj, con trai của Shivaji, người tiếp tục lãnh đạo Đế quốc Maratha sau khi cha ông qua đời. Khi hoàng đế Mughal Aurangzeb muốn thôn tính Maratha, Sambhaji đáp trả bằng chiến thuật du kích, giành chiến thắng vang dội nhưng cũng đối mặt với phản bội trong nội bộ. Dù bị bắt và tra tấn, ông không khuất phục, trở thành biểu tượng của lòng quả cảm. Sau cái chết của ông, vợ ông là Yesubai tiếp tục cuộc kháng chiến, dẫn đến sự sụp đổ của Đế quốc Mughal sau đó.</p>', 'Full', 1, 'single', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Vicky Kaushal","avatar":""},{"name":"Rashmika Mandanna","avatar":""},{"name":"Akshaye Khanna","avatar":""},{"name":"Ashutosh Rana","avatar":""},{"name":"Divya Dutta","avatar":""},{"name":"Pradeep Ram Singh Rawat","avatar":""},{"name":"Vineet Kumar Singh","avatar":""},{"name":"Neil Bhoopalam","avatar":""},{"name":"Santosh Juvekar","avatar":""},{"name":"Rajiv Kachroo","avatar":""},{"name":"Ashish Pathode","avatar":""},{"name":"Diana Penty","avatar":""},{"name":"Kiran Karmarkar","avatar":""},{"name":"Balaji Manohar","avatar":""},{"name":"Neelkantee Patekar","avatar":""},{"name":"Ne","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Chaava",