INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-dang-luan-don-phan-3', 'Băng Đảng Luân Đôn (Phần 3)', 'Gangs Of London (Season 3)', 'https://phimimg.com/upload/vod/20250510-1/f2b521d02d332addf3f7851f9024550a.jpg', 'https://phimimg.com/upload/vod/20250510-1/58310f82dae95ab8bf2c5cbb7859791e.jpg', '<p>Kể câu chuyện về London bị xé nát bởi các cuộc đấu tranh quyền lực hỗn loạn của các băng đảng quốc tế và khoảng trống quyền lực bất ngờ được tạo ra khi người đứng đầu gia đình tội phạm quyền lực nhất London bị ám sát.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 26, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Sope Dirisu","avatar":""},{"name":"Michelle Fairley","avatar":""},{"name":"Orli Shuka","avatar":""},{"name":"Lucian Msamati","avatar":""},{"name":"Jasmine Armando","avatar":""},{"name":"Narges Rashidi","avatar":""},{"name":"Brian Vernel","avatar":""},{"name":"Pippa Bennett-Warner","avatar":""},{"name":"Richard Dormer","avatar":""},{"name":"Andrew Koji","avatar":""},{"name":"T''Nia Miller","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Gangues de Londres","伦敦黑帮","Gangs of London"]', 1784690324156);
