INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-co-ay-ra-khoi-rac-roi', 'Dụ Cô Ấy Ra Khỏi Rắc Rối', 'Tempting Her Fall', 'https://phimimg.com/upload/vod/20250510-1/58f3515a1d2034f778ab3f200a90ac9f.jpg', 'https://phimimg.com/upload/vod/20250510-1/c30a509a151764de50cb0a465ba8096a.jpg', '<p>Hai gia tộc giàu có liên hôn, đúng hôm tổ chức tiệc đính hôn thì một người đàn ông bí ẩn đột nhiên xuất hiện và có những cử chỉ thân mật với cô dâu trước mặt mọi người. Cô dâu tương lai bị cuốn vào vòng xoáy của gia đình, tình cảm và các mưu mô thủ đoạn. Khi mục đích thật sự của người đàn ông bí ẩn dần sáng tỏ, cũng là lúc bức màn che giấu vở kịch gia tộc xoay quanh yêu-hận-trả thù lặng lẽ được vén lên.</p>', 'Hoàn Tất (60/60)', 60, 'series', 'completed', 24, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Tập Tuấn","avatar":""},{"name":"Trần Tư Triệt","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324156);
