INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-bac-si-do-thi', 'Nữ Bác Sĩ Đô Thị', 'Metro Medico', 'https://phimimg.com/upload/vod/20250510-1/874503b28d97a17650cb417e8eb38ef7.jpg', 'https://phimimg.com/upload/vod/20250510-1/cf2b73d508b7d3626aae67100af2306c.jpg', '<p>Vào năm Thiên Khải tại đại lục Cửu Châu, thần y Cổ Tiểu Phong được hoàng đế giao nhiệm vụ đến Hải Thành để chữa trị bệnh dịch. Tuy nhiên, cô bị một kẻ thần bí tấn công và bị ném xuống hồ. Trong lúc mơ hồ, cô nhìn thấy bóng dáng của Nhậm Dực. Khi tỉnh lại, cô phát hiện mình đang ở trong một thế giới hiện đại hoàn toàn xa lạ. Để điều tra sự thật, Cổ Tiểu Phong quyết định bám theo Nhậm Dực – một bác sĩ thực tập tại khoa cấp cứu. Từ đây, một câu chuyện tình yêu kỳ ảo vượt thời gian và không gian, bắt đầu từ một cuốn truyện tranh, cũng dần hé mở. Ban đầu, Nhậm Dực tỏ ra bài xích, nhưng cuối cùng lại bị y thuật cao siêu và tính cách lương thiện của Cổ Tiểu Phong chinh phục. Hai người cùng nhau chữa bệnh cứu người, và hẹn ước tiến vào lễ đường hôn nhân. Thế nhưng, vì đến từ hai thế giới khác nhau, họ vốn dĩ đã định sẵn chỉ có thể là khách qua đường trong đời nhau.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Huang Youtian","avatar":""},{"name":"Wu Jingxin","avatar":""},{"name":"Huang Panpan","avatar":""},{"name":"Li Ningyuan","avatar":""},{"name":"Yu Yanan","avatar":""},{"name":"Yang Dinghe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Du Shi Nv Yi Guan","都市女醫倌","Metro Medica","都市女医倌"]', 1784690324156);
