INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-an-khong-gian', 'Bí Ẩn Không Gian', 'Ash', 'https://phimimg.com/upload/vod/20250510-1/00e77f552239cb7eb072719dce73eb6c.jpg', 'https://phimimg.com/upload/vod/20250510-1/2bdbaa8225d23a12f4e7b0d073a63445.jpg', '<p>Trên một hành tinh xa xôi, nữ phi hành gia Riya tỉnh dậy và phát hiện toàn bộ phi hành đoàn của trạm vũ trụ đã bị sát hại dã man. Cô bị mất trí nhớ, chỉ còn những ký ức rời rạc về đồng đội và nhiệm vụ. Khi một người đàn ông tên Brion xuất hiện, tự nhận là người được cử đến cứu cô, Riya phải đối mặt với sự nghi ngờ và không biết liệu có thể tin tưởng anh ta hay không. Trong khi đó, nguồn cung cấp oxy của cô đang cạn kiệt, buộc cô phải đưa ra những quyết định sinh tử.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Eiza González","avatar":""},{"name":"Aaron Paul","avatar":""},{"name":"Iko Uwais","avatar":""},{"name":"Kate Elliott","avatar":""},{"name":"Beulah Koale","avatar":""},{"name":"Flying Lotus","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["الصدى الصامت","Ash","アッシュ 孤独の惑星"]', 1784690324156);
