INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chay-tron-cai-chet', 'Chạy Trốn Cái Chết', 'Rust', 'https://phimimg.com/upload/vod/20250510-1/329c712fe4b82d0222d72eec5a9a7ab3.jpg', 'https://phimimg.com/upload/vod/20250510-1/9e1d6e5cfacfbd04d34e41759deeca6f.jpg', '<p>&quot;Rust&quot; là phim cao bồi lấy bối cảnh năm 1882 tại Wyoming. Nhân vật chính là Harland Rust (Alec Baldwin), một tay súng sống ngoài vòng pháp luật, tìm cách cứu đứa cháu trai Lucas Hollister, 13 tuổi, khỏi án tử hình sau khi cậu bé vô tình bắn chết một người. Họ cùng nhau chạy trốn về phía Mexico, bị truy đuổi bởi cảnh sát trưởng và thợ săn tiền thưởng. Trên đường đi, cả hai phải đối mặt với những bóng ma trong quá khứ và mối liên kết gia đình được xây dựng lại trong nghịch cảnh.</p>', 'Full', 1, 'single', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Alec Baldwin","avatar":""},{"name":"Josh Hopkins","avatar":""},{"name":"Patrick Scott McDermott","avatar":""},{"name":"Travis Fimmel","avatar":""},{"name":"Frances Fisher","avatar":""},{"name":"Rhys Coiro","avatar":""},{"name":"Devon Werkheiser","avatar":""},{"name":"Xander Berkeley","avatar":""},{"name":"Jake Busey","avatar":""},{"name":"Abraham Benrubi","avatar":""},{"name":"Travis Hammer","avatar":""},{"name":"Aria Alpert Adjani","avatar":""},{"name":"Sean J. Dillingham","avatar":""},{"name":"Todd Bryant","avatar":""},{"name":"Luce Rains","avatar":""},{"name":"Bryant Carroll","avatar":""}]', '[{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["锈烂","Ржавчина","Раст","Rust"]', 1784690324156);
