INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-mua-hi-vong', 'Cơn Mưa Hi Vọng', 'Fair Rain', 'https://phimimg.com/upload/vod/20250510-1/f9c4e8f40ca1966a9f6f525a5201375a.jpg', 'https://phimimg.com/upload/vod/20250510-1/f571af6d3e519944a746c6d5ae655d0a.jpg', '<p>Khi một chính phủ thế giới mới nổi lên sau những vụ mất tích bí ẩn của người dân trên toàn thế giới, một nhóm người kháng chiến được gọi là Remnant sống và chết để bảo vệ một tài sản có giá trị sẽ mang lại hy vọng cho những người sống sót sau thảm họa này.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Michael J. Patterson","avatar":""},{"name":"Suzanne R. Neff","avatar":""},{"name":"Patrick Vann","avatar":""},{"name":"Malcolm Simmons","avatar":""},{"name":"Dean Michaels","avatar":""},{"name":"Aubree Bravo","avatar":""},{"name":"Kolapo Olarinde","avatar":""},{"name":"Mozella Place","avatar":""},{"name":"Crayton Spade","avatar":""},{"name":"Chris Wilson","avatar":""},{"name":"Shauron Lee","avatar":""},{"name":"Kym Starks","avatar":""},{"name":"Alycia Ocampo","avatar":""},{"name":"Ken Stancil Jr.","avatar":""},{"name":"Jakarra Howard","avatar":""},{"name":"Kayla Goggans","avatar":""},{"name":"James J","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["مطر العدالة","Fair Rain"]', 1784690324156);
