INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-phan-xet', 'Ngày Phán Xét', 'Day of Reckoning', 'https://phimimg.com/upload/vod/20250510-1/35971f84ebd32672660e98e57dfc02b1.jpg', 'https://phimimg.com/upload/vod/20250510-1/ff4425a7fd01ba8e61a7a98ac58b71cd.jpg', '<p>Câu chuyện xoay quanh John Dorsey (Zach Roerig), một cảnh sát trưởng đang đối mặt với nguy cơ mất việc và tan vỡ hôn nhân. Anh buộc phải hợp tác với Butch Hayden (Billy Zane), một đặc vụ liên bang cứng rắn, để bắt giữ nữ tội phạm nguy hiểm Emily Rusk (Cara Jade Myers). Tuy nhiên, Emily không phải là một tù nhân dễ kiểm soát; cô ta khéo léo thao túng nhóm áp giải, gây ra mâu thuẫn nội bộ. Khi băng đảng do chồng của Emily dẫn đầu tiến đến để giải cứu cô, John và Emily buộc phải hợp tác để sinh tồn.</p>', 'Full', 1, 'single', 'completed', 19, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Zach Roerig","avatar":""},{"name":"Billy Zane","avatar":""},{"name":"Cara Jade Myers","avatar":""},{"name":"Scott Adkins","avatar":""},{"name":"Trace Adkins","avatar":""},{"name":"Travis Hammer","avatar":""},{"name":"Yelawolf","avatar":""},{"name":"Struggle Jennings","avatar":""},{"name":"Edward Crowe","avatar":""},{"name":"Gus Langley","avatar":""},{"name":"Britton Webb","avatar":""},{"name":"Caroline Avery Granger","avatar":""},{"name":"Mike Wolfe","avatar":""},{"name":"Josh Plasse","avatar":""},{"name":"Brad Carter","avatar":""},{"name":"Max Bickelhaup","avatar":""},{"name":"Tim Casper","avatar":""},{"name":"Leticia Cl","avatar":""}]', '[{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Ajuste de cuentas","Dia de Acerto de Contas","Day of Reckoning"]', 1784690324156);
