INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-toi-loi-2025', 'Tình Yêu Tội Lỗi', 'The Sinful Game Of Love', 'https://phimimg.com/upload/vod/20250509-1/852b3aaf1cb7eb73ea966363d5bd9519.jpg', 'https://phimimg.com/upload/vod/20250509-1/7e82c6b133e7e7a751dab9f6b341c4ff.jpg', '<p>Vì dây chuyền phù thủy bị thất lạc, tộc trưởng phù thủy Hạ Mạt phải chịu nỗi đau thấu tim gan và không còn sống được bao lâu. Để lấy lại sợi dây chuyền, cô buộc phải ký kết khế ước với giáo sư vật lý Mộ Hàn Vũ, người đến để trả thù và hứa sẽ giúp anh thực hiện ước nguyện. Trong quá trình chung sống, hai người dần nảy sinh tình cảm, nhưng số phận trớ trêu lại đẩy họ vào hai chiến tuyến đối lập...</p>', 'Hoàn Tất (59/59)', 59, 'series', 'completed', 24, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Ninh","avatar":""},{"name":"Vương Minh Dương","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324156);
