INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-menh-chi-nu', 'Thiên Mệnh Chi Nữ', 'The Chosen Queen', 'https://phimimg.com/upload/vod/20250509-1/8aef082299dbdfcc70947c53f38508f1.jpg', 'https://phimimg.com/upload/vod/20250509-1/3880fb4bd40388513ddb963131c8646a.jpg', '<p>Ái nữ duy nhất của nhà họ Lục là Lục Lê đem lòng yêu Thẩm Thế Mỹ, một thư sinh đang trên đường vào kinh dự thi. Vì tình yêu mù quáng, nàng sẵn sàng cắt đứt quan hệ với cha, khăng khăng muốn nên duyên cùng Thẩm Thế Mỹ. Lục Lê sở hữu dị năng trời ban, không tiếc ngọc dung, hy sinh nhan sắc để cứu mạng người thương, đồng thời giúp chàng thi đỗ trạng nguyên, vang danh thiên hạ. Những tưởng cuộc đời sắp tốt đẹp hơn, nhưng Lục Lê không ngờ chồng nàng đã lén lút qua lại với Trưởng công chúa từ lâu… Họ đâu biết người con gái được thiên mệnh lựa chọn có thể mượn số mệnh tốt cho phu quân, nhưng một khi phụ bạc nàng, kẻ ấy ắt sẽ gánh lấy nghiệp báo, lưới trời tuy thưa mà chẳng lọt!</p>', 'Hoàn Tất (55/55)', 55, 'series', 'completed', 26, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đàm Diêm Diêm","avatar":""},{"name":"Lâm Thi Hàm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324156);
