INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mai-mai-2025', 'Mãi Mãi', 'FOREVER', 'https://phimimg.com/upload/vod/20250509-1/94883cd16699f6d056264edc17ec2caa.jpg', 'https://phimimg.com/upload/vod/20250509-1/28f1c96064eaa979ac19eab58daa155b.jpg', '<p>Gặp lại nhau ở tuổi thiếu niên, hai người bạn thời thơ ấu chìm đắm trong tình yêu, trải qua niềm vui và nỗi đau của một mối tình đầu sẽ thay đổi cuộc đời họ mãi mãi.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lovie Simone","avatar":""},{"name":"Michael Cooper Jr.","avatar":""},{"name":"Wood Harris","avatar":""},{"name":"Karen Pittman","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["FOREVER"]', 1784690324156);
