INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mai-mai-2025', 'Mãi Mãi', 'FOREVER', 'mãi mãi forever lovie simone michael cooper jr. wood harris karen pittman forever', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('manh-sat', 'Manh Sát', 'The Blind Reaper', 'https://phimimg.com/upload/vod/20250509-1/a3a98a1a7916a9d256706e958696d810.jpg', 'https://phimimg.com/upload/vod/20250509-1/405dd70af7398e2376c806520fb20810.jpg', '<p>Cố Bắc là một kẻ ăn mày mù. Một ngày nọ, anh tình cờ chứng kiến thảm án tàn sát cả trấn Thanh Thạch. Nhớ ơn bát cháo từng được thiên kim tiểu thư Lan Thu Dao ban cho trong lúc đói khát, Cố Bắc quyết định giúp đỡ cô thoát nạn. Thế nhưng, anh lại bị kẻ gian Nam Chúc Lang sát hại để diệt khẩu, còn Lan Thu Dao cũng bị hại chết thảm thương. Cái chết của Thu Dao khiến ngọn lửa trong lòng Cố Bắc bùng cháy dữ dội. Anh lột bỏ thân phận ăn mày, trở lại làm &quot;Dạ Bất Thu&quot; - một sát thần từng vang danh giang hồ. Mang theo tinh thần nghĩa hiệp và sự căm phẫn tột cùng, Cố Bắc bắt đầu hành trình trả thù, lấy lại công bằng cho trăm họ bị giết hại và ba mươi mạng người nhà họ Lan.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wang Hui","avatar":""},{"name":"Li Qia","avatar":""},{"name":"Qi Cai","avatar":""},{"name":"李博","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Blind Fury","Blind Murder","盲杀"]', 1784690324156);
