INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xe-quai-vat-sieu-cap-phan-2', 'Xe Quái Vật Siêu Cấp (Phần 2)', 'Mighty Monsterwheelies (Season 2)', 'https://phimimg.com/upload/vod/20250509-1/0a2b058f1afd1c1a0afacb196f4c32fe.jpg', 'https://phimimg.com/upload/vod/20250509-1/76cc10d930a2753197a145a55f3efae1.jpg', '<p>Lấy cảm hứng từ những quái vật kinh điển trong phim như Dracula và Xác ướp, nhưng pha chút Frankenstein: Những anh hùng xe cộ này ở đây để giúp đỡ, chứ không phải để dọa nạt!</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tru Valentino","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["Os Invencíveis Carros-Monstros","Les Méga MonsterBolides","Megamonstruos sobre ruedas","Mighty Monsterwheelies: mostri a quattro ruote","المركبات المتوحشة الرائعة","Mäktiga monsterrullarna","无敌怪物车","Muhteşem Tekerler","Mighty Monsterwheelies"]', 1784690324156);
