INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nascar-het-toc-luc-phan-2', 'NASCAR: Hết Tốc Lực (Phần 2)', 'NASCAR: Full Speed (Season 2)', 'https://phimimg.com/upload/vod/20250509-1/99d7440e51548918072c2781f40812fc.jpg', 'https://phimimg.com/upload/vod/20250509-1/92f0a8c0233171dba369cb9121ff5916.jpg', '<p>Vì đam mê và vinh quang tại Cúp NASCAR, các tay đua và đội của họ cạnh tranh giành chức vô địch cũng như cơ hội làm nên lịch sử trong loạt phim tài liệu về thể thao này.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ryan Blaney","avatar":""},{"name":"William Byron","avatar":""},{"name":"Ross Chastain","avatar":""},{"name":"Denny Hamlin","avatar":""},{"name":"Bubba Wallace","avatar":""},{"name":"Kyle Larson","avatar":""},{"name":"Christopher Bell","avatar":""},{"name":"Joey Logano","avatar":""},{"name":"Tyler Reddick","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["NASCAR Full Speed","NASCAR: Full Speed","Full Speed: The Daytona 500","NASCAR: Hết tốc lực","Full Speed"]', 1784690324156);
