INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khach-san-tasokare', 'Khách Sạn Tasokare', 'Tasokare Hotel', 'https://phimimg.com/upload/vod/20250125-1/b8e83bc0f56103a6446268ca2335e8b6.jpg', 'https://phimimg.com/upload/vod/20250125-1/c76efe2c9aa981829f761b2cc5299909.jpg', '<p>Khách sạn Tasokare là một nơi luôn chìm trong ánh hoàng hôn, không phân biệt ngày hay đêm. Khách sạn này nằm giữa ranh giới sự sống và cái chết, là chốn tạm dừng cho những linh hồn chưa quyết định sẽ sang thế giới bên kia hay trở lại trần gian. Nữ chính, Neko Tsukahara, vô tình bước vào nơi này mà quên mất bản thân mình là ai và tại sao lại xuất hiện ở đây. Được nhân viên khách sạn hướng dẫn, cô đến phòng của mình, nơi có thể chứa đựng những món đồ liên quan đến ký ức của cô. Khi cố gắng tìm cách quay lại thế giới thực và khôi phục ký ức, Neko vô tình vướng vào một sự việc bí ẩn...</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Rika Momokawa","avatar":""},{"name":"Koudai Sakai","avatar":""},{"name":"Yusuke Shirai","avatar":""},{"name":"Kanehira Yamamoto","avatar":""},{"name":"Yuki Nagano","avatar":""},{"name":"Takashi Narumi","avatar":""},{"name":"Natsue Sasamoto","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Tasokare Hoteru","Tasokare Hotel","황혼호텔","ทาโซกาเระโฮเทล","誰ソ彼ホテル"]', 1784690324156);
