INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('com-ngoan-com-hu', 'Cớm Ngoan, Cớm Hư', 'Good Cop, Bad Cop', 'https://phimimg.com/upload/vod/20250406-1/828e63ad30411328f152312a1fd0afce.jpg', 'https://phimimg.com/upload/vod/20250406-1/371361560a014bde0d60bcbfcac9b24a.jpg', '<p>Cặp chị em quái đản cùng làm việc trong Sở cảnh sát hẻo lánh ở vùng Tây Bắc Thái Bình Dương. Những cư dân đầy màu sắc cùng điều kiện vật chất thiếu thốn gây nên những tình huống dở khóc dở cười. Đặc biệt là mối quan hệ oan trái giữa họ và người bố người mình, ông Big Hank, cũng là cảnh sát trưởng ở đó.</p>', 'Tập 8', 10, 'series', 'ongoing', 17, 2025, 'Vietsub', 'FHD', 'Úc', 0, '[{"name":"Leighton Meester","avatar":""},{"name":"Luke Cook","avatar":""},{"name":"Devon Terrell","avatar":""},{"name":"Clancy Brown","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Good Cop+Bad Cop","Good Cop/Bad Cop"]', 1784690324156);
