INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mau-cua-zeus-phan-3', 'Máu Của Zeus (Phần 3)', 'Blood Of Zeus (Season 3)', 'https://phimimg.com/upload/vod/20250508-1/6cee9e51d70788925fe4f0caf74f06ce.jpg', 'https://phimimg.com/upload/vod/20250508-1/0030a3fdd9521a1ac891faff887de943.jpg', '<p>Heron, một thường dân ở Hy Lạp cổ đại, khám phá ra di sản đích thực của mình với danh phận là con trai của Zeus cùng lẽ sống: cứu thế giới khỏi đội quân quỷ dữ.</p>', 'Hoàn Tất (8/8)', 8, 'hoathinh', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Derek Phillips","avatar":""},{"name":"Jessica Henwick","avatar":""},{"name":"Elias Toufexis","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Το Αίμα του Δία","خون زئوس","Krew Zeusa","Sangue de Zeus","มหาศึก โลหิตเทพ","Gods & Heroes","Gods and Heroes","Blood of Zeus"]', 1784690324156);
