INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-uc-chien-tranh', 'Ký Ức Chiến Tranh', 'Warfare', 'https://phimimg.com/upload/vod/20250508-1/5a0e70fffdd8457c6495640ad761f9b2.jpg', 'https://phimimg.com/upload/vod/20250508-1/7bb5d606196568f90829d0ca3bf86efa.jpg', '<p>Warfare (2025) tái hiện nhiệm vụ sinh tử của đội đặc nhiệm Navy SEAL tại Iraq vào ngày 19 tháng 11 năm 2006, khi họ chiếm giữ một ngôi nhà để giám sát khu vực. Phiến quân nhanh chóng bao vây, đẩy các binh sĩ vào cuộc giao tranh ác liệt với súng máy và lựu đạn. Bộ phim khai thác sự khắc nghiệt của chiến tranh, những hy sinh và tổn thương tâm lý mà người lính phải gánh chịu. Với cách kể chuyện chân thực, Warfare đem lại cảm giác nghẹt thở đầy ám ảnh.</p>', 'Full', 1, 'single', 'completed', 13, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"D''Pharaoh Woon-A-Tai","avatar":""},{"name":"Will Poulter","avatar":""},{"name":"Cosmo Jarvis","avatar":""},{"name":"Kit Connor","avatar":""},{"name":"Finn Bennett","avatar":""},{"name":"Taylor John Smith","avatar":""},{"name":"Michael Gandolfini","avatar":""},{"name":"Adain Bradley","avatar":""},{"name":"Noah Centineo","avatar":""},{"name":"Evan Holtzman","avatar":""},{"name":"Henry Zaga","avatar":""},{"name":"Joseph Quinn","avatar":""},{"name":"Charles Melton","avatar":""},{"name":"Aaron Mackenzie","avatar":""},{"name":"Alex Brockdorff","avatar":""},{"name":"Joe Macaulay","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["战·争","Tiempo de guerra","Warfare","Под огнём","Warfare: Tiempo de guerra","حرب","Válka"]', 1784690324156);
