INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danh-bat-hu-truyen', 'Danh Bất Hư Truyền', 'He Kills It', 'https://phimimg.com/upload/vod/20250424-1/9ef1177e1f0f09c0e9a861eab73096a0.jpg', 'https://phimimg.com/upload/vod/20250424-1/e44d2df37b4bb610acb980c71eba3b30.jpg', '<p>Ngô Minh, người thừa kế của một gia tộc y học cổ truyền Trung Quốc, đã xuống núi để kéo dài sự sống cho vị hôn thê của mình, nhưng không ngờ lại gặp chủ tịch tập đoàn Dương thị đang bị bệnh nặng và treo giải thưởng 100 triệu nhân dân tệ để tìm bác sĩ điều trị. Ngô Minh vô tình dấn thân vào một cuộc hành trình đầy thử thách và cơ hội, và thu hút được sự chú ý của nhiều mỹ nhân. Đứng trước đủ loại cám dỗ, Ngô Minh sẽ lựa chọn thế nào?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Uông Giai Huy","avatar":""},{"name":"Hướng Hân","avatar":""},{"name":"Tiền Tư Di","avatar":""},{"name":"Lý Nghệ","avatar":""},{"name":"Nhiếp Tân Nguyên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ming Bu Xu Chuan","名不虛傳","名不虚传"]', 1784690324156);
