INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('an-chay-yeu', 'Ăn, Chạy, Yêu', 'Eat Run Love', 'https://phimimg.com/upload/vod/20250408-1/fdf78ecc9d6464685359307f78d40ede.jpg', 'https://phimimg.com/upload/vod/20250408-1/74ef5198bfcf5c93a682a9e650841db3.jpg', '<p>Ăn, Chạy, Yêu là hành trình tình yêu sâu đậm nhưng đầy sóng gió giữa Cam Dương và Đinh Chi Đồng. Xuất thân từ gia đình có điều kiện, Cam Dương rất ngưỡng mộ đàn chị khóa trên Đinh Chi Đồng, một sinh viên nghèo khó nhưng có thành tích học tập xuất sắc. Bất chấp khoảng cách giai cấp, họ đã có một tình yêu đẹp trong những năm tháng đại học. Thế nhưng, đến khi vào đời, hiện thực nghiệt ngã khiến họ phải chia xa. Nhiều năm sau, khi gặp lại nhau trong cương vị mới, liệu họ có thể hóa giải hiểu lầm để yêu lại lần nữa?</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 6, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Phi Vũ","avatar":""},{"name":"Trang Đạt Phi","avatar":""},{"name":"Lâm Bác Dương","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chi Fan Pao Bu He Lian Ai","Chīfàn Pǎobù Hé Liàn''ài","拜金罗曼史","吃飯跑步和戀愛","拜金羅曼史","Bai Jin Luo Man Shi","흘반포보화연애 : 런 잇 러브","Eat Run Love","吃饭跑步和恋爱"]', 1784690324156);
