INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-thu-lenh', 'Thiên Thu Lệnh', 'Destiny And Saving', 'https://phimimg.com/upload/vod/20250409-1/554c233d7bb7d1b16d774bb09f9545c7.jpg', 'https://phimimg.com/upload/vod/20250409-1/9a9597d83925e17b560ba88b2c4bfbc2.jpg', '<p>Cuộc chiến giữa chính đạo và ma đạo kéo dài hàng nghìn năm. Khi lãnh tụ hai phe quyết chiến, hậu duệ của họ — Thẩm Thiếu Du và Phụng Ly Tuyết — lại trở thành bằng hữu nhờ cơ duyên. Một biến cố khiến Ly Tuyết rơi xuống vực và được ma giáo cứu, rồi trở thành tân giáo chủ, còn Thiếu Du được định sẵn trở thành minh chủ chính đạo. Số phận đặt họ vào thế đối đầu, nhưng sau bao thử thách, họ nhận ra tình cảm thật sự trong tim mình. Cuối cùng, cả hai cùng nắm tay vượt qua ranh giới chính – tà, gìn giữ chính nghĩa và tình yêu không đổi.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Dư Hy","avatar":""},{"name":"Đồng Mộng Thực","avatar":""},{"name":"Hàn Đống","avatar":""},{"name":"Phó Phương Tuấn","avatar":""},{"name":"Hoàng Nghệ","avatar":""},{"name":"Trần Tử Hàn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["O decreto de mil anos","Qian Qiu Ling","Clash of the Titans","Destiny and Saving","千秋令"]', 1784690324156);
