INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thien-thu-lenh', 'Thiên Thu Lệnh', 'Destiny And Saving', 'thiên thu lệnh destiny and saving trương dư hy đồng mộng thực hàn đống phó phương tuấn hoàng nghệ trần tử hàn o decreto de mil anos qian qiu ling clash of the titans destiny and saving 千秋令', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-duong-to-lua-huyen-an-tay-han', 'Con Đường Tơ Lụa: Huyền Án Tây Hán', 'The Mystery of the Silk', 'https://phimimg.com/upload/vod/20250420-1/42d5fcb7e51aa5d933f91cc2207820ba.jpg', 'https://phimimg.com/upload/vod/20250420-1/1b3d10015c9b329448ebc652f7a0dc03.jpg', '<p>Vào những năm đầu của triều đại Tây Hán, một trận hỏa hoạn kinh hoàng đã thiêu rụi số lụa hoàng gia được định làm cống phẩm cho Hung Nô—một thảm họa đã thổi bùng lên sự hỗn loạn trên khắp Tây Vực. Giang Du, một sứ giả ưu tú của triều đình, được phái đi theo sắc lệnh bí mật để điều tra vụ đốt phá và ngăn chặn một cuộc khủng hoảng ở biên giới. Trong khi đó, Cannu yêu dấu của anh, một thợ dệt lụa trở thành anh hùng dân gian, tập hợp người dân Shiquan để bổ sung số cống phẩm đã mất và cứu đế chế khỏi sự ô nhục. Khi Giang Du một mình mạo hiểm vào Tây Vực đầy hiểm nguy, anh phải đối mặt với một lựa chọn bất khả thi: trung thành với số phận của nhà Hán… hay lời thì thầm của trái tim mình</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Du Yiheng","avatar":""},{"name":"Shi Xuanru","avatar":""},{"name":"En Jing","avatar":""},{"name":"Yu Xiaowan","avatar":""},{"name":"Zhong Lei","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Mystery Of The Silk","绣衣使·西汉迷案"]', 1784690324156);
