INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tru-ta-ky-khoi-nguyen-hac-am', 'Trừ Tà Ký: Khởi Nguyên Hắc Ám', 'Exorcism Chronicles: The Beginning', 'https://phimimg.com/upload/vod/20250506-1/e8f1117c1fd1768b7fb86394a8d400a6.jpg', 'https://phimimg.com/upload/vod/20250506-1/d6e2ac8f5deb2266dbd0447ac4db6e00.jpg', '<p>Cha sứ Park – một linh mục vốn là bác sĩ đã bị khai trừ sau khi thực hiện những nghi lễ trừ tà mà Giáo hội cho là cực đoan, bởi những người trong Giáo hội từ chối tin rằng những thế lực vô hình đang rình rập các linh hồn vô tội. Những tưởng cha Park an phận giải nghệ, một nhà sư đến từ ngôi chùa bí ẩn cất giữ những bí thuật bất ngờ tìm tới ông với một lời khẩn cầu: Bảo vệ một đứa trẻ tên Joon Hoo khỏi vị sư phụ đã hắc hóa của cậu bé. Cha Park buộc phải đối mặt với bóng ma quá khứ để giải cứu đứa trẻ và ngăn chặn bi kịch lặp lại.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Choi Han","avatar":""},{"name":"Nam Doh-hyeong","avatar":""},{"name":"Jung Yoo-jung","avatar":""},{"name":"Kim Yeon-woo","avatar":""},{"name":"Hong Seung-hyo","avatar":""},{"name":"Hwang Chang-yung","avatar":""},{"name":"Kim Min-ju","avatar":""},{"name":"Pyo Yeong-jae","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Toemarok","退魔录","驱魔编年史：起源之战","퇴마록"]', 1784690324156);
