INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('san-dien-cua-nu-hoang', 'Sàn Diễn Của Nữ Hoàng', 'A Queens Runway', 'https://phimimg.com/upload/vod/20250506-1/113b58ac7cd2b7bf1f22fbf0e6b0b47e.jpg', 'https://phimimg.com/upload/vod/20250506-1/ea76a1f198bdb73278c19aacb22f5544.jpg', '<p>Đằng sau vương miện và ánh hào quang, những cô gái đầy tham vọng theo đuổi giấc mơ trở thành Hoa hậu Hoàn vũ Philippines, đối mặt với sự cạnh tranh khốc liệt và những hy sinh to lớn.</p>', 'Full', 1, 'single', 'completed', 13, 2025, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Voltaire Tayag","avatar":""},{"name":"Shamcey Supsup-Lee","avatar":""},{"name":"Christi McGarry","avatar":""},{"name":"Kris Tiffany Janson","avatar":""},{"name":"Lia Ramos","avatar":""},{"name":"Selena Antonio Reyes","avatar":""},{"name":"R''Bonney Gabriel","avatar":""},{"name":"Michelle Marquez Dee","avatar":""},{"name":"Alexandra Rosales","avatar":""},{"name":"Mario Garcia","avatar":""},{"name":"Matea Mahal Smith","avatar":""},{"name":"Jonas Gaffud","avatar":""},{"name":"Chelsea Manalo","avatar":""},{"name":"Stacey Daniella Gabri","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["A Queen’s Runway"]', 1784690324156);
