INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-thinh-cau-bi-an-2', 'Lời Thỉnh Cầu Bí Ẩn 2', 'Another Simple Favor', 'https://phimimg.com/upload/vod/20250506-1/a8018591c6d91146c1918dbd6d310bac.jpg', 'https://phimimg.com/upload/vod/20250506-1/a6a9c3d39cb02dfa8f688ea30beb35f8.jpg', '<p>Stephanie và Emily tái ngộ trên hòn đảo Capri xinh đẹp của Ý để tham dự đám cưới xa hoa của Emily với một doanh nhân người Ý giàu có. Bên cạnh những vị khách lộng lẫy, hãy chuẩn bị cho sự góp mặt của ám sát và phản bội, trong một đám cưới đầy những khúc quanh bất ngờ hơn cả con đường từ bến Marina Grande đến quảng trường trung tâm thị trấn Capri.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Anna Kendrick","avatar":""},{"name":"Blake Lively","avatar":""},{"name":"Michele Morrone","avatar":""},{"name":"Henry Golding","avatar":""},{"name":"Allison Janney","avatar":""},{"name":"Elizabeth Perkins","avatar":""},{"name":"Elena Sofia Ricci","avatar":""},{"name":"Alex Newell","avatar":""},{"name":"Andrew Rannells","avatar":""},{"name":"Taylor Ortega","avatar":""},{"name":"Bashir Salahuddin","avatar":""},{"name":"Lorenzo de Moor","avatar":""},{"name":"Joshua Satine","avatar":""},{"name":"Ian Ho","avatar":""},{"name":"Kelly McCormack","avatar":""},{"name":"Aparna Nancherla","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["A Simple Favor 2","부탁 하나만 들어줘 2","Um Pequeno Favor 2","Another Simple Favour","Nur noch ein kleiner Gefallen","Another Simple Favor"]', 1784690324156);
