INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('menh-huyen-nhat-thuong', 'Mệnh Huyền Nhất Thương', 'The Old Way', 'https://phimimg.com/upload/vod/20250506-1/9ad58d76b104820c006a200f437576f3.jpg', 'https://phimimg.com/upload/vod/20250506-1/ad64a31c5b4659ad123dfb2e6270315a.jpg', '<p>Bề ngoài lạnh lùng nhưng mang trong tim lòng hiệp nghĩa, Bành Nhất Nam trong một lần giải cứu vụ bắt cóc trên sông đã gặp được Trang Nguyệt — một cô gái chạy nạn sau khi ngôi làng của cô bị cướp phá. Qua lời kể của cô, anh dần hiểu rõ nguyên nhân sâu xa của sự việc. Sau nhiều đấu tranh nội tâm, cuối cùng anh quyết định cùng các huynh đệ Mã Minh và Lôi Ngũ chống lại bọn cướp, giải cứu dân làng. Một trận chiến khốc liệt sắp sửa bắt đầu.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Jin","avatar":""},{"name":"Cheng Yi","avatar":""},{"name":"Han Yanbo","avatar":""},{"name":"Michael Tong Man-Lung","avatar":""},{"name":"Guo Yiqian","avatar":""},{"name":"Ning Huan Yu","avatar":""},{"name":"Zhan Ni","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["命悬一枪"]', 1784690324156);
