INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-de-thuong-cua-toi-khong-co-tac-dung-voi-kuroiwa-medaka', 'Sự Dễ Thương Của Tôi Không Có Tác Dụng Với Kuroiwa Medaka', 'Medaka Kuroiwa Is Impervious To My Charms', 'https://phimimg.com/upload/vod/20250506-1/cbcf553e72a67f139b297410a5a4124a.jpg', 'https://phimimg.com/upload/vod/20250506-1/24917f08e4a7c3f08309eafa7b135520.jpg', '<p>Xinh đẹp từ đầu đến chân! Vóc dáng hoàn hảo! Với Kawai Mona, việc chinh phục trái tim đàn ông dễ dàng như hơi thở... nhưng sự xuất hiện của Kuroiwa Medaka, một nam sinh mới chuyển trường, người thậm chí không thèm liếc nhìn cô lấy một lần, đã đảo lộn hoàn toàn cuộc sống học đường của cô! Cô đã quen với việc được mọi người vây quanh và tán dương, vậy tại sao cậu ta lại khác biệt? Mona thử mọi cách có thể để chinh phục Medaka, thậm chí đôi khi còn hơi quá trớn!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 25, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ryota Iwasaki","avatar":""},{"name":"Yu Serizawa","avatar":""},{"name":"Sora Amamiya","avatar":""},{"name":"Kana Hanazawa","avatar":""},{"name":"Hinaki Yano","avatar":""},{"name":"Kaori Maeda","avatar":""},{"name":"Tasuku Hatanaka","avatar":""},{"name":"Daiki Yamashita","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Kuroiwa Medaka ni Watashi no Kawaii ga Tsuujinai","Kuroiwa Medaka ni Watashi no Kawaii ga Tsūjinai","黒岩メダカに私の可愛いが通じない"]', 1784690324156);
