INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-bi-chiem-huu-phan-2', 'Tình Yêu Bị Chiếm Hữu (Phần 2)', 'Possessed Love (Season 2)', 'https://phimimg.com/upload/vod/20250227-1/6c7f30d7a33514f4f8a9aefdd02e580a.jpg', 'https://phimimg.com/upload/vod/20250227-1/b101f86fe53d8afb5c3e367ba054905d.jpg', '<p>Những nhà tiên tri của số phận rơi vào lưới tình. Những nhà tiên tri Gen Z huyền bí và cuốn hút tụ hội để tìm kiếm người thương của mình. Dù có thể nhìn thấu tương lai, nhưng tình yêu lại là thứ duy nhất họ không thể đoán trước. Liệu họ có chấp nhận số phận đã an bài, hay sẽ để bản năng dẫn lối? Những mối quan hệ lãng mạn của họ dần trở nên rắc rối, cảm xúc khó định nghĩa cũng đan xen vào nhau. Một sự hỗn loạn đầy rung động con tim, nhưng tình yêu của họ lại mãnh liệt và đầy biến động. Ngay cả các vị thần cũng không thể tiên đoán được những màn tán tỉnh táo bạo giữa họ.Câu chuyện tình yêu kỳ lạ của những thầy bói lại bắt đầu lần nữa—liệu trái tim họ sẽ hướng về đâu?</p><p><br/></p>', 'Hoàn Tất (10/10)', 10, 'tvshows', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Shin Dong Yeob","avatar":""},{"name":"Yoo In Na","avatar":""},{"name":"Gabee Yoo","avatar":""},{"name":"Seon Ho","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mo Shen S01","신들린 연애"]', 1784690324156);
