INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-the-nguyen-anh-trang', 'Lời Thề Nguyện Ánh Trăng', 'I''m Your Moon', 'https://phimimg.com/upload/vod/20250324-1/c92a40a2765dbeb2d5537e954a3c11a8.jpg', 'https://phimimg.com/upload/vod/20250324-1/d6f205fe161abe0138c80d5e65bd2265.jpg', '<p>Pray, người thừa kế cao quý của cung điện Ussanakorn, đem lòng yêu nữ bá tước của cung điện Sitalaras — một quý cô thanh lịch và hoàn hảo. Thế nhưng, tình yêu của họ là điều không thể, bởi mối thù truyền kiếp giữa hai gia tộc đã khiến họ không thể đến bên nhau. Pray sống trong dày vò, đau khổ bởi tình yêu đích thực vẫn luôn khắc khoải trong tim. Cho đến khi số phận ban cho họ một cơ hội thứ hai — Pray và nữ bá tước được tái sinh. Liệu kiếp này, họ có thể nắm tay nhau và chứng minh tình yêu chân thành vượt qua hận thù hay không?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Wachariya Jarupungomon","avatar":""},{"name":"Pronyanee Pornpishayawasin","avatar":""},{"name":"Dena Sathonghon","avatar":""},{"name":"Phadtraruengrid Namwongyot","avatar":""},{"name":"Warodom Khemmonta","avatar":""},{"name":"Wannasa Thongviset","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["กัษธิษฐาน"]', 1784690324156);
