INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-tich-chi', 'Phong Tịch Chí', 'Legacy Of The Storm', 'https://phimimg.com/upload/vod/20250214-1/2402aa84ebd0ee50f2e4e75aca63f441.jpg', 'https://phimimg.com/upload/vod/20250214-1/2c8817949dd89aae7afc9d53b5d08c79.jpg', '<p>Vào những năm đầu triều Minh, trong cơn phong ba của võ lâm, các môn phái vì muốn giành lấy sức mạnh của bốn thần khí mà bị lòng tham che mờ mắt, dẫn đến cảnh binh đao tương tàn. Giữa kiếp nạn này, hiệp khách Cao Lăng Phong đã gặp gỡ Tôn Trầm Tịch khi đang khám phá sự thật về vụ tàn sát cả thành và bí ẩn thân thế của mình. Với tinh thần dũng cảm và chính nghĩa, cả hai đã cùng nhau hợp lực c tiêu diệt kẻ xấu, ngăn chặn âm mưu của Huyền Hỏa Môn. Cuối cùng họ đã thành công tìm được một trong bốn thần khí là Thanh Long Đảm. Sau khi thân thế được sáng tỏ, Cao Lăng Phong cùng Tôn Trầm Tịch tiếp tục gánh vác trọng trách tìm kiếm thần khí, bảo vệ thiên hạ thái bình.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đỗ Tuấn Trạch","avatar":""},{"name":"Cao Quảng Trạch","avatar":""},{"name":"Từ Chẩn Chẩn","avatar":""},{"name":"Trương Giai Lâm","avatar":""},{"name":"Vu Bằng","avatar":""},{"name":"Thượng Na","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Feng Xi Zhi","风汐志"]', 1784690324156);
