INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tao-huyen-huyen-tai-ba', 'Tào Huyên Huyên Tài Ba', 'Cao Xuanxuan''s Love Journey', 'https://phimimg.com/upload/vod/20250113-1/f937310cbc5c600659c7fbb8af7ef94f.jpg', 'https://phimimg.com/upload/vod/20250113-1/cf5e08ce328bf965210b73caf9fea9fe.jpg', '<p>Câu chuyện kể về Châu Na, nhà văn trinh thám hiện đại trong một cơ duyên tình cờ đã đến Diêm Thành thời cổ đại, trở thành vị hôn thê của huyện lệnh Quách Tử Kiệt. Cả hai cùng nhau phá giải nhiều vụ án kỳ lạ. Khi hai người dần phải lòng nhau, tình cảm ngày càng sâu đậm thì một âm mưu quỷ quyệt chết người cũng âm thầm xuất hiện...</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chúc Tự Đan","avatar":""},{"name":"R1SE Trạch Tiêu Văn","avatar":""},{"name":"Quách Thừa","avatar":""},{"name":"Từ Mộc Thiền","avatar":""},{"name":"Lý Tử Tuyền","avatar":""},{"name":"Tống Hân Nhiễm","avatar":""},{"name":"Vu Tân Thông","avatar":""},{"name":"Ứng Hạo Minh","avatar":""},{"name":"Ngụy Nguy","avatar":""},{"name":"Mông Ân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Liao Bu Qi De Cao Xuan Xuan","了不起的曹萱萱"]', 1784690324156);
