INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-thay-dam-phan', 'Bậc Thầy Đàm Phán', 'The Art Of Negotiation', 'https://phimimg.com/upload/vod/20250309-1/5daef7673fff8e7390fea128cef435d2.jpg', 'https://phimimg.com/upload/vod/20250309-1/3b8d5ba42378f03cd29d2e0d959506cf.jpg', '<p>Yun Ju No, một nhân vật chủ chốt trong đội M&amp;A của Tập đoàn Sanin, đột ngột biến mất một ngày nọ và rời đến Hawaii với lý do không được tiết lộ. Tin đồn lan truyền rằng anh ta đã bị giáng chức, nhưng sự thật vẫn là một ẩn số. Ba năm sau, khi Tập đoàn Sanin đứng bên bờ vực phá sản với khoản nợ khổng lồ 11 tỷ đô la, anh được triệu hồi trở lại Hàn Quốc như hy vọng cuối cùng của công ty. Nhiệm vụ của anh rất rõ ràng: cứu Sanin Group. Nhưng giải pháp của anh lại không hề đơn giản. Với sự ủng hộ của CEO Song Jae Sik, Ju No tái lập đội M&amp;A và tập hợp những nhà đàm phán xuất sắc nhất để dấn thân vào cuộc chơi đầy rủi ro của những thương vụ trị giá hàng tỷ đô. Lần này, anh đặt cược tất cả. Liệu Ju No có thể huy động được 11 tỷ đô để cứu công ty, hay ngay cả &quot;vị thần đàm phán&quot; cũng sẽ gục ngã?</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 11, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Je-hoon","avatar":""},{"name":"Kim Dae-myung","avatar":""},{"name":"Sung Dong-il","avatar":""},{"name":"Jang Hyun-sung","avatar":""},{"name":"Oh Man-seok","avatar":""},{"name":"Ahn Hyun-ho","avatar":""},{"name":"차강윤","avatar":""},{"name":"Lee Chae-won","avatar":""},{"name":"Lee Kyu-sung","avatar":""},{"name":"Kim Jong-tae","avatar":""},{"name":"Lee Suk-hyeong","avatar":""},{"name":"Yang Jo-a","avatar":""},{"name":"Nanami Sakuraba","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["협상의 기술","فن التفاوض","The Art of Negotiation"]', 1784690324156);
