INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-san-yeu', 'Thợ Săn Yêu', 'The Demon Hunter', 'https://phimimg.com/upload/vod/20250502-1/cdffe7d13a287bf9ae595ee24ccb547b.jpg', 'https://phimimg.com/upload/vod/20250502-1/4e5acd1593ab4efb25705e921b9f8dc6.jpg', '<p>Vì cứu người vợ yêu thương là A Nhược, Lãng Vô Tích đã bước lên con đường săn yêu đầy hiểm ác. Không ngờ lại rơi vào bẫy của đạo sĩ Bạch Vân và bị biến thành yêu thú. Trong khoảnh khắc sinh tử, linh hồn của A Nhược thức tỉnh, hai người hợp lực đánh bại Bạch Vân đạo trưởng. Sau trận chiến, A Nhược đưa Lãng Vô Tích đến ẩn náu tại núi Thiên Ngu, còn bản thân lên đường tìm cách giải trừ cổ hóa yêu, mong một ngày có thể hóa giải lời nguyền.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Heng Cai","avatar":""},{"name":"Sheng Nan","avatar":""},{"name":"Feng Lijun","avatar":""},{"name":"Li Ruoxi","avatar":""},{"name":"Shi Xuanru","avatar":""},{"name":"Shen Baoping","avatar":""},{"name":"Zhang Jiawenhan","avatar":""},{"name":"Zong Fengyan","avatar":""},{"name":"Yue Dongfeng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Lie Hun Ren","Soul Hunter","猎魂人"]', 1784690324157);
