INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('fan-nu-so-mot', 'Fan Nữ Số Một', 'The Biggest Fan', 'https://phimimg.com/upload/vod/20250502-1/caca5c4d407c84d3a59cb0c5598b1f4a.jpg', 'https://phimimg.com/upload/vod/20250502-1/314d756a1a7e0681ec52a0854fd0a295.jpg', '<p>Bị tẩy chay ở Hollywood, Lana Cruz về quê tìm cơ hội tái xuất. Nhưng Polly, người hâm mộ năm nào nay hóa kẻ thù, xuất hiện. Liệu Lana có tránh được thị phi và lấy lại danh tiếng?</p>', 'Full', 1, 'single', 'completed', 18, 2025, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Kate del Castillo","avatar":""},{"name":"Diana Bovio","avatar":""},{"name":"Daniel Raymont","avatar":""},{"name":"Gabriel Nuncio","avatar":""},{"name":"Hugo Catalán","avatar":""},{"name":"Ana Gonzalez Bello","avatar":""},{"name":"Ricardo Esquerra","avatar":""},{"name":"Amaranta Ruiz","avatar":""},{"name":"Emma Ramos","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Fã ou Hater?","Ihr grösster Fan","La más fan"]', 1784690324157);
