INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('fan-nu-so-mot', 'Fan Nữ Số Một', 'The Biggest Fan', 'fan nữ số một the biggest fan kate del castillo diana bovio daniel raymont gabriel nuncio hugo catalán ana gonzalez bello ricardo esquerra amaranta ruiz emma ramos fã ou hater? ihr grösster fan la más fan', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('coi-chung-hang-xom', 'Coi Chừng Hàng Xóm', 'Neighborhood Watch', 'https://phimimg.com/upload/vod/20250502-1/9723298c02dd374104a1a1a356e969e2.jpg', 'https://phimimg.com/upload/vod/20250502-1/cc8c0eb8bb9ccbbfb59f27712fa7a1d8.jpg', '<p>Neighborhood Watch (2025) là một bộ phim giật gân đầy kịch tính, xoáy sâu vào những bí ẩn trong khu phố tưởng chừng bình yên. Simon, một thanh niên đang vật lộn với chứng rối loạn tâm lý, tình cờ chứng kiến một vụ mất tích bí ẩn. Khi cảnh sát bác bỏ lời khai của anh, Simon quyết định tự mình điều tra, tìm đến Ed, người hàng xóm từng là nhân viên an ninh. Cả hai bắt đầu khám phá những bí mật đen tối đang bị che giấu trong cộng đồng của họ, dẫn đến một cuộc săn đuổi căng thẳng giữa sự thật và nguy hiểm. Bộ phim không chỉ đem lại cảm giác hồi hộp mà còn đặt ra câu hỏi sâu sắc về niềm tin, trí óc và thực tế. Một hành trình đầy bất ngờ, nơi mọi ánh mắt đều có thể che giấu điều gì đó.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jack Quaid","avatar":""},{"name":"Jeffrey Dean Morgan","avatar":""},{"name":"Malin Åkerman","avatar":""},{"name":"Krishna Sistla Ward","avatar":""},{"name":"Cecile Cubiló","avatar":""},{"name":"Nicole Cyrille","avatar":""},{"name":"Harrison Stone","avatar":""},{"name":"Jim Klock","avatar":""},{"name":"Derrick Goodman Jr.","avatar":""},{"name":"Charles Arthur Berg","avatar":""},{"name":"Creek Wilson","avatar":""},{"name":"Visionz2turnt","avatar":""},{"name":"Jonathan Fuller","avatar":""},{"name":"Curtis Lyons","avatar":""},{"name":"Leslie Sides","avatar":""},{"name":"Melanie Jeff","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Nowhere Men","Сусідський нагляд","Соседский дозор","Neighborhood Watch"]', 1784690324157);
