INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buoi-hen-ho-kinh-hoang', 'Buổi Hẹn Hò Kinh Hoàng', 'Drop', 'https://phimimg.com/upload/vod/20250502-1/4bcb9854930fa2168f10853776a35729.jpg', 'https://phimimg.com/upload/vod/20250502-1/3300c76d40876bb8b7c875572f74e115.jpg', '<p>Violet, một người mẹ góa vợ trong cuộc hẹn đầu tiên trong nhiều năm, đến một nhà hàng cao cấp, nơi cô cảm thấy nhẹ nhõm vì ngày hẹn hò của mình, Henry, quyến rũ và đẹp trai hơn cô mong đợi. Nhưng hóa học của họ bắt đầu cong khi Violet bắt đầu bị kích thích và sau đó khủng bố bởi một loạt các giọt ẩn danh vào điện thoại của cô.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Meghann Fahy","avatar":""},{"name":"Brandon Sklenar","avatar":""},{"name":"Violett Beane","avatar":""},{"name":"Jacob Robinson","avatar":""},{"name":"Reed Diamond","avatar":""},{"name":"Gabrielle Ryan","avatar":""},{"name":"Jeffery Self","avatar":""},{"name":"Ed Weeks","avatar":""},{"name":"Travis Nelson","avatar":""},{"name":"Fiona Browne","avatar":""},{"name":"Tara Mae","avatar":""},{"name":"Stephanie Karam","avatar":""},{"name":"Saoirse Hayden","avatar":""},{"name":"Jordon-Dion Scanlon","avatar":""},{"name":"Ellen Reidy","avatar":""},{"name":"Benjamin Pelletier","avatar":""},{"name":"Niamh McHenry","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Trollée","Igra straha","Date Katlani","Przyjmij/odrzuć","Drop"]', 1784690324157);
