INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-kinh', 'Huyền Kính', 'Hanging Mirrors', 'https://phimimg.com/upload/vod/20250416-1/364ff922cfe38cade79162b9090a6733.jpg', 'https://phimimg.com/upload/vod/20250416-1/c87655f0753488e7867a5a168f96dfd8.jpg', '<p>Một vụ án phân xác đã đưa Từ Kiêu và Lâm Quốc Cường, hai cảnh sát với phong cách làm việc hoàn toàn trái ngược làm việc chung với nhau, tạo thành nên một cộng sự già-trẻ, vừa là thầy vừa là bạn. Họ phát hiện ra đằng sau vụ án lại có mối liên hệ với một nghi lễ tà ác cổ xưa nào đó nhằm mục đích trường sinh bất lão, và kẻ chủ mưu đứng sau lại chính là một phụ nữ trẻ có học thức cao, nhìn bề ngoài tưởng chừng vô hại...</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Nhậm Đạt Hoa","avatar":""},{"name":"Chu Vũ Thần","avatar":""},{"name":"Trương Linh Tâm","avatar":""},{"name":"Hoàng Nghệ","avatar":""},{"name":"Lưu Kim Sơn","avatar":""},{"name":"Tôn Hạo","avatar":""},{"name":"Lưu Lâm","avatar":""},{"name":"Vương Khuê Vinh","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Xuan Jing","悬镜","Висящие зеркала","Подвешенные зеркала","Hanging Mirrors"]', 1784690324157);
