INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xoa-toi', 'Xóa Tội', 'The Abyss', 'https://phimimg.com/upload/vod/20250502-1/6d8cf5cb0f372d719f846c78b81b9396.jpg', 'https://phimimg.com/upload/vod/20250502-1/b1749313a19c6f23616d0fe09516cc61.jpg', '<p>Câu chuyện kể về Ninh Chân, người từng chứng kiến cha mình bị sát hại ngay từ thời thơ ấu, còn mẹ thì mất tích một cách kỳ lạ. Đội trưởng đội cảnh sát hình sự – Lục Trinh, trong quá trình điều tra sự thật cũng bị giết hại một cách thảm khốc. Tại hiện trường, một ký hiệu bí ẩn mang tên &quot;Vực Sâu&quot; được để lại, từ đó gắn chặt số phận của Ninh Chân, con gái của Lục Trinh là Lục Phàm, và người học trò Tào Tiến vào một vòng xoáy định mệnh. Nhiều năm sau, biểu tượng &quot;Vực Sâu&quot; lại xuất hiện, đi kèm với những vụ án mạng liên hoàn, những bí ẩn chồng chất, khiến tất cả như rơi vào một định mệnh không thể thoát khỏi…</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Fei Qiming","avatar":""},{"name":"Wang Xiaoyunzi","avatar":""},{"name":"Ye Zuxin","avatar":""},{"name":"Yu Yi","avatar":""},{"name":"Mao Linlin","avatar":""},{"name":"Liu Yitong","avatar":""},{"name":"Cao Xiyue","avatar":""},{"name":"Wang Hanwen","avatar":""},{"name":"Bei Le","avatar":""},{"name":"Jia Hongwei","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Mie Zui","Fighting Crime","灭罪"]', 1784690324157);
