INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('xoa-toi', 'Xóa Tội', 'The Abyss', 'xóa tội the abyss fei qiming wang xiaoyunzi ye zuxin yu yi mao linlin liu yitong cao xiyue wang hanwen bei le jia hongwei mie zui fighting crime 灭罪', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('uoc-nguyen-thanh-hien-thuc', 'Ước Nguyện Thành Hiện Thực', 'May All Your Wishes Come True', 'https://phimimg.com/upload/vod/20250502-1/5ae388c18de3d6d632b04f4f97fa82ed.jpg', 'https://phimimg.com/upload/vod/20250502-1/8d53d7d4e06707973f4beb9135c4b5eb.jpg', '<p>Truyền thuyết về &quot;Đạo Thánh&quot; Hứa Như Nguyện – vì một sự nhầm lẫn mà thay thế thân phận, bị ép gả vào vương phủ làm vợ của người con trai thứ hai. Ban đầu, nàng chỉ định đánh cắp sính lễ khổng lồ rồi cao chạy xa bay, nhưng lại bị thế tử thâm sâu khó lường và người em trai bệnh tật vạch trần thân phận ký sinh ngay từ cái nhìn đầu tiên. Từ đó, nàng bị cuốn vào cuộc đấu đá trong phủ vương gia như một quân cờ. Cả gia tộc đạo chích cải trang thành người hầu theo chân nàng tiến vào phủ, mở màn cho vở kịch &quot;đánh cắp gia đình và đánh cắp trái tim&quot; với hai mặt song song: ban ngày tỏ ra ngoan ngoãn đáng yêu để lấy lòng tin, ban đêm lại trèo tường lẻn vào dò thám tình báo. Không chỉ thế, họ còn khuấy động cục diện triều chính, dấn thân vào cơn sóng ngầm của quyền lực và mưu mô. Khi một nữ hiệp mạnh mẽ, thẳng thắn gặp phải một &quot;em chồng&quot; bệnh tật nhưng ẩn giấu nội tâm, hàng loạt hiểu lầm dở khóc dở cười vì hoán đổi giới tính và những tương tác ngọt ngào trao gửi chân tình sẽ liên tục diễn ra. Một trải nghiệm đỉnh cao khiến bạn cười đến đau bụng rồi khóc ướt gối, bộ phim hứa hẹn trở thành chuẩn mực mới cho thể loại cổ trang hài nhẹ nhàng.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Roada Xu","avatar":""},{"name":"Meng En","avatar":""},{"name":"Han Haotian","avatar":""},{"name":"Chen Chuqi","avatar":""},{"name":"Jin Wang","avatar":""},{"name":"Yang Jun","avatar":""},{"name":"Tan Limin","avatar":""},{"name":"Guo Chang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Suo Nian Jie Ru Yuan","所念皆如願","所念皆如愿"]', 1784690324157);
