INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('uoc-nguyen-thanh-hien-thuc', 'Ước Nguyện Thành Hiện Thực', 'May All Your Wishes Come True', 'ước nguyện thành hiện thực may all your wishes come true roada xu meng en han haotian chen chuqi jin wang yang jun tan limin guo chang suo nian jie ru yuan 所念皆如願 所念皆如愿', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ong-chu-chuyen-sinh-thanh-tieu-thu-doc-ac', 'Ông Chú Chuyển Sinh Thành Tiểu Thư Độc Ác', 'From Bureaucrat To Villainess: Dad''s Been Reincarnated!', 'https://phimimg.com/upload/vod/20250502-1/a51e7fdbf9285b2b581c8200c894a6bb.jpg', 'https://phimimg.com/upload/vod/20250502-1/cbfc7fa71f00467a975d90c7c2bdff87.jpg', '<p>Ở kiếp trước, Kenzaburou Tondabayashi là một công chức 52 tuổi tại Nhật Bản hiện đại. Và giờ đây, ông ta đã trở nữ phản diện! Tái sinh thành Grace Auvergne, một tiểu thư độc ác trong otome game mà con gái anh từng chơi. Điều này khiến ông vô cùng bối rối.

Với lượng thông tin ít ỏi có được, Kenzaburou biết mình nên là một tiểu thư quý tộc kiêu ngạo, nhưng người đàn ông có kỷ luật và trưởng thành này lại không thể hành xử theo cách đó. Thay vào đó, sự điềm tĩnh và tốt bụng đã giúp ông kết bạn với nữ chính và còn khiến toàn thể học sinh thêm yêu mến ông như hình mẫu của sự thanh lịch. Trong khi cố gắng giữ câu chuyện đi đúng hướng, Kenzaburou sẽ phải dựa vào nhiều năm kinh nghiệm làm việc, phong cách lịch sự chuẩn Nhật Bản và những nguyên tắc gia đình để hòa nhập với đám trẻ trong học viện.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kazuhiko Inoue","avatar":""},{"name":"Mao Ichimichi","avatar":""},{"name":"Akira Sekine","avatar":""},{"name":"Kaito Ishikawa","avatar":""},{"name":"Ryota Suzuki","avatar":""},{"name":"Yuuichirou Umehara","avatar":""},{"name":"Takuma Nagatsuka","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["中年上班族转生恶役","大叔转生恶役大小姐","中年大叔转生反派千金","Akuyaku Reijou Tensei Oji-san","Middle-Aged Man''s Noble Daughter Reincarnation","Villain Daughter","Tensei Ojisan","Akuyaku Reijō Tensei Oji-san","Akuyaku Reijou Tensei Ojisan","転生おじさん","The Middle-Aged Man That Reincarnated as a Villainess","The Old Man Reincarnated as a Villainess","From Bureaucrat to Villainess: Dad''s Been Reincarnated!","悪役令嬢転生おじさん"]', 1784690324157);
