INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-cua-bep-truong-cac-huyen-thoai', 'Bàn Của Bếp Trưởng: Các Huyền Thoại', 'Chef''s Table: Legends', 'https://phimimg.com/upload/vod/20250502-1/c7a9034357d83c601ecad95aae322249.jpg', 'https://phimimg.com/upload/vod/20250502-1/f0f333446e06d38ed3c80eb248f4de69.jpg', '<p>Loạt phim được đề cử giải Emmy này tôn vinh bốn tên tuổi lớn ngành ẩm thực – Jamie Oliver, José Andrés, Alice Waters và Thomas Keller – những người thay đổi nền ẩm thực toàn cầu.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"David Gelb","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Chef''s Table: Legends"]', 1784690324157);
