INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diem-nong-2025', 'Điểm Nóng', 'The Hot Spot', 'https://phimimg.com/upload/vod/20250228-1/4c3723cc8f2c0ebcb1f0dd39b79b081b.jpg', 'https://phimimg.com/upload/vod/20250228-1/60717e20856129a2663d528ebe682d0f.jpg', '<p>Ở một thị trấn bên chân núi Phú Sĩ, có những sinh vật ngoài trái đất ẩn mình! Bà Endo Kiyomi, một bà mẹ đơn thân 41 tuổi làm việc tại khách sạn kinh doanh, đã tình cờ gặp phải người ngoài hành tinh…!? Tại một thị trấn quê nhỏ, nơi những điều kỳ lạ xen kẽ xảy ra, đây là câu chuyện hài hước về người ngoài hành tinh và con người theo phong cách địa phương, được viết kịch bản bởi Bakarhythm!</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Mikako Ichikawa","avatar":""},{"name":"Akihiro Kakuta","avatar":""},{"name":"Anne Suzuki","avatar":""},{"name":"Kami Hiraiwa","avatar":""},{"name":"Kaho","avatar":""},{"name":"Naoki Tanaka","avatar":""},{"name":"Kayo Noro","avatar":""},{"name":"Maki Sakai","avatar":""},{"name":"Moeno Sumida","avatar":""},{"name":"Fumiyo Kohinata","avatar":""},{"name":"Shunya Shiraishi","avatar":""},{"name":"Haruka Kinami","avatar":""},{"name":"Sosuke Ikematsu","avatar":""},{"name":"Rinko Kikuchi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["山脚下的外星人","Conexión extraterrestre","山の麓の宇宙人","日曜ドラマ ホットスポット","Hotto Supotto","핫 스팟: 우주인 출몰 주의!","小鎮星熱點","The Hot Spot","Hot Spot","ホットスポット"]', 1784690324157);
