INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('diem-nong-2025', 'Điểm Nóng', 'The Hot Spot', 'điểm nóng the hot spot mikako ichikawa akihiro kakuta anne suzuki kami hiraiwa kaho naoki tanaka kayo noro maki sakai moeno sumida fumiyo kohinata shunya shiraishi haruka kinami sosuke ikematsu rinko kikuchi 山脚下的外星人 conexión extraterrestre 山の麓の宇宙人 日曜ドラマ ホットスポット hotto supotto 핫 스팟: 우주인 출몰 주의! 小鎮星熱點 the hot spot hot spot ホットスポット', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-dinh-menh', 'Tình Yêu Định Mệnh', 'Destiny', 'https://phimimg.com/upload/vod/20250430-1/fa2d524b4ec9359cf50eea58c23dd165.jpg', 'https://phimimg.com/upload/vod/20250430-1/ef02ce650e70450c9471b7017178762e.jpg', '<p>Câu chuyện kể về Tống Nguyễn - một cô gái tràn đầy năng lượng, lương thiện và bình thường, do gặp khó khăn trong công việc mà tình cờ quen biết với Sở Tinh Ngôn - một ngôi sao hàng đầu đang lạc lối giữa giấc mơ sự nghiệp. Hai người với khoảng cách lớn, tính cách đối lập, thân phận chênh lệch, nhưng lại cùng nhau nỗ lực, cùng trưởng thành, mở ra một chuyện tình lãng mạn và đẹp đẽ nơi đô thị hoa lệ.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"​Vương Tinh Vĩ","avatar":""},{"name":"Trình Kim Minh","avatar":""},{"name":"Hứa Nặc Ngôn","avatar":""},{"name":"Vương Tử Tô","avatar":""},{"name":"Cô Chỉ Vân","avatar":""},{"name":"Lý Dật Huyên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Dang Yang","揺れる想い","Ripples","荡漾"]', 1784690324157);
