INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xuan-toi-dinh-phong-ba', 'Xuân Tới Định Phong Ba', 'My Destined Consort', 'https://phimimg.com/upload/vod/20250412-1/9aa7c6695b71ab8893fca785d59f0d66.jpg', 'https://phimimg.com/upload/vod/20250412-1/54cb6268e52c0f0b99e2e4b133b529bf.jpg', '<p>Thẩm Giang Ly, con gái dòng chính của Thẩm phủ, vốn là người thuần khiết lương thiện. Vào đêm thành hôn, nàng bị gài bẫy ân ái với Nhị thiếu chủ Lục Cảnh Minh, rồi lại bị vu oan và giam lỏng trong từ đường. Sau khi sinh con trong cảnh nguy nan, nàng may mắn được cứu, nhưng con trai Diễm Diễm lại mắc bệnh nan y, phương thuốc duy nhất lại nằm trong tay Lục gia. Vì muốn cứu con, Thẩm Giang Ly buộc lòng quay trở lại Lục phủ. Tại đây, nàng mạnh mẽ đối mặt, vạch trần những kẻ từng hãm hại mình, làm rõ âm mưu năm xưa và dần hóa giải hiểu lầm với Lục Cảnh Minh. Diễm Diễm, với sự ngây thơ và thông minh đáng yêu, lại trở thành &quot;thần trợ công&quot; giúp cha mẹ nối lại tình xưa, gương vỡ lại lành…</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Từ Hải Kiều","avatar":""},{"name":"Hải Lục","avatar":""},{"name":"Yên Duyệt Khê","avatar":""},{"name":"Mục Lạc Ân","avatar":""},{"name":"Quan Dục Tịch","avatar":""},{"name":"Lại Vũ Mông","avatar":""},{"name":"Tôn Huỳnh Hạo","avatar":""},{"name":"Lý Tinh Dao","avatar":""},{"name":"Tần Ngưu Chính Uy","avatar":""},{"name":"Vương Nghệ Cẩn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Chun Lai Ding Feng Bo","有凤来兮","春來定風波","有鳳來兮","You Feng Lai Xi","춘래정풍파 : 영혼이 이끄는 인연","春来定风波"]', 1784690324157);
