INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('xuan-toi-dinh-phong-ba', 'Xuân Tới Định Phong Ba', 'My Destined Consort', 'xuân tới định phong ba my destined consort từ hải kiều hải lục yên duyệt khê mục lạc ân quan dục tịch lại vũ mông tôn huỳnh hạo lý tinh dao tần ngưu chính uy vương nghệ cẩn chun lai ding feng bo 有凤来兮 春來定風波 有鳳來兮 you feng lai xi 춘래정풍파 : 영혼이 이끄는 인연 春来定风波', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hiep-khach-hanh-bat-thong', 'Hiệp Khách Hành Bất Thông', 'Hidden Master', 'https://phimimg.com/upload/vod/20250412-1/22dbe3111aef791e204a90f9b34f267d.jpg', 'https://phimimg.com/upload/vod/20250412-1/7fdce0057b82c59ab4780d390e2edf6f.jpg', '<p>Tuy có tướng mạo hung dữ nhưng Cẩu Lăng Phong lại có tấm lòng lương thiện, luôn ấp ủ trở thành đại hiệp. Vô tình, chàng học được võ công của ma giáo và bước chân vào giang hồ. Giữa những định kiến và bắt bẻ của người đời, chàng vẫn kiên trì tiến về phía trước. Trên đường đi, chàng gặp Mã Anh Đan - &quot;Bách Hoa Hiệp&quot; của Độc Tiên Cốc và Gia Cát Hằng - con trai của Kiếm Thánh. Cùng họ kề vai sát cánh tung hoành giang hồ, phá giải nhiều vụ án ly kỳ, Cẩu Lăng Phong dần dần ngộ ra chân lý &quot;Nghĩa hiệp không phân lớn nhỏ, võ công không phân chính tà&quot; và cuối cùng trở thành một đại hiệp chân chính.</p>', 'Tập 30', 30, 'series', 'ongoing', 12, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Từ Chí Thắng","avatar":""},{"name":"Phạm Tĩnh Y","avatar":""},{"name":"Vương Soái","avatar":""},{"name":"Sơ Tuấn Thần","avatar":""},{"name":"Lạc Thi Kỳ","avatar":""},{"name":"Đàm Hiểu Phàm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Xia Ke Xing Bu Tong","侠客行不通"]', 1784690324157);
