INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hiep-khach-hanh-bat-thong', 'Hiệp Khách Hành Bất Thông', 'Hidden Master', 'hiệp khách hành bất thông hidden master từ chí thắng phạm tĩnh y vương soái sơ tuấn thần lạc thi kỳ đàm hiểu phàm xia ke xing bu tong 侠客行不通', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('netsuai-prince', 'Netsuai Prince', 'Secret Love With Prince', 'https://phimimg.com/upload/vod/20250424-1/dd872f26b2bf189cde4dc56be7d7b274.jpg', 'https://phimimg.com/upload/vod/20250424-1/1a7db1da8b7b140413bd1b6aecd55bf7.jpg', '<p>Câu chuyện xoay quanh Amamiya Matsuri, một nữ sinh trung học năng động. Sau khi mẹ cô tái hôn, Matsuri bất ngờ trở thành em gái của ba anh em sinh ba nổi tiếng trong nhóm nhạc thần tượng Terzetto: Haruka, Azusa và Rihito. Ban đầu, cô cảm thấy choáng ngợp khi sống chung với những người anh mới là thần tượng quốc dân. Tuy nhiên, mối quan hệ giữa ba anh em không hề suôn sẻ như vẻ bề ngoài; họ thường xuyên mâu thuẫn và tranh cãi. Matsuri quyết tâm hàn gắn tình cảm giữa các anh em và dần dần, cô xây dựng được mối quan hệ thân thiết với họ. Tình huống trở nên phức tạp khi Azusa, người anh lạnh lùng trong nhóm, thổ lộ rằng anh không thể xem cô chỉ là em gái nữa. Đồng thời, Subaru, bạn thời thơ ấu của Matsuri, xuất hiện với tư cách là thành viên mới của nhóm nhạc đối thủ PRISM, khiến mối quan hệ giữa các nhân vật càng thêm rối rắm.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 27, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Meari Hayashi","avatar":""},{"name":"Kazuto Mokudai","avatar":""},{"name":"Minato Matsui","avatar":""},{"name":"Takato Okura","avatar":""},{"name":"Kosaku Koizumi","avatar":""},{"name":"Ohigashi Ritsuki","avatar":""},{"name":"Atsuki Mashiko","avatar":""}]', '[{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Netsuai Prince","熱愛プリンス","Secret Love with Prince","熱愛プリンス お兄ちゃんはキミが好き"]', 1784690324157);
