INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-can-bach-luong', 'Bán Cân Bách Lưỡng', 'Money Games', 'https://phimimg.com/upload/vod/20250501-1/4e8afff08d149f29d8c1b9af1182ad12.jpg', 'https://phimimg.com/upload/vod/20250501-1/9f215730d417f5a3e2899b1595844ba3.jpg', '<p>Nằm vùng làm tân binh trong một tổ chức ngầm, đội chống gian lận nọ phát hiện ra nhiều tội ác và hỗn loạn hơn họ tưởng.</p>', 'Full', 1, 'single', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Jack Lim","avatar":""},{"name":"Edmond So Chi-Wai","avatar":""},{"name":"Choo Hao Ren","avatar":""},{"name":"Tomato","avatar":""},{"name":"Ah Ya","avatar":""},{"name":"Wayne Thong","avatar":""},{"name":"Sandra Lim","avatar":""},{"name":"Jacqueline Tiang","avatar":""},{"name":"Jovi Heng","avatar":""},{"name":"Eric Tsang Chi-Wai","avatar":""},{"name":"Au-Yeung Tsan-Wah","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Money Game$","半斤百兩","半⽄百两"]', 1784690324157);
