INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ban-can-bach-luong', 'Bán Cân Bách Lưỡng', 'Money Games', 'bán cân bách lưỡng money games jack lim edmond so chi-wai choo hao ren tomato ah ya wayne thong sandra lim jacqueline tiang jovi heng eric tsang chi-wai au-yeung tsan-wah money game$ 半斤百兩 半⽄百两', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-doa-dao-hoa-nhat-the-khai', 'Thiên Đóa Đào Hoa Nhất Thế Khai', 'The Blossoming Love', 'https://phimimg.com/upload/vod/20250102-1/b7cd204a5bf95833fe7d00c062e95441.jpg', 'https://phimimg.com/upload/vod/20250102-1/0e8290d94ab105fa3b85dac5cda3d2db.jpg', '<p>Bộ phim&nbsp;xoay quanh mối tình sâu đậm từ kiếp này sang kiếp khác giữa Chiêu Minh và Hỗn Độn Châu. Thời thượng cổ, Chiêu Minh hy sinh bản thân để cứu tính mạng của vạn dân. Nhờ Hỗn Độn Châu giữ lại một sợi hồn phách nên chàng mới không vĩnh viễn biến mất khỏi thế gian. Nhiều năm sau, Chiêu Minh chuyển thế thành minh chủ Tiên Minh - Tạ Tuyết Thần; còn Hỗn Độn Châu trở thành thánh nữ Ám Vực - Mộ Huyền Linh. Khi gặp lại, đôi uyên ương từng yêu nhau tha thiết ở kiếp trước giờ đã quên đi quá khứ, lại còn rơi vào cục diện chính tà không đội trời chung.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Bân Bân","avatar":""},{"name":"Tôn Trân Ny","avatar":""},{"name":"Uông Đạc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Qian Duo Tao Hua Yi Shi Kai","千朵桃花一世开"]', 1784690324157);
