INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-gai-mot-sao-cua-toi', 'Bạn Gái Một Sao Của Tôi', 'The Quirky And The Charming', 'https://phimimg.com/upload/vod/20250315-1/edcea074c2de3e4ed098a8e130ff706f.jpg', 'https://phimimg.com/upload/vod/20250315-1/0bb3dbb5d8e6c6d7fc528dee0ffdac91.jpg', '<p>Một lần tình cờ, Dịch Nhiên, người sống nhờ đủ loại công việc bán thời gian, trở thành người đánh giá khách sạn năm sao, đồng thời quen biết Tiêu Mục Thừa trong tình huống trớ trêu. Không ngờ Tiêu Mục Thừa lại là giám đốc khách sạn, cấp trên trực tiếp của Dịch Nhiên. Trong công việc thường ngày ở khách sạn, hai người gặp phải đủ loại khách hàng cũng như những khó khăn trong việc quản lý khách sạn. Dịch Nhiên và Tiêu Mục Thừa cùng nhau hợp tác để giải quyết những khủng hoảng đó. Hai con người thuộc hai thế giới khác nhau, dù liên tục xảy ra mâu thuẫn trong cuộc sống thường ngày, nhưng họ không nhận ra rằng mình lại vô tình xích gần nhau hơn...</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hình Chiêu Lâm","avatar":""},{"name":"Lư Dương Dương","avatar":""},{"name":"Đổng Hữu Lâm","avatar":""},{"name":"Hoàng Hiểu Uyển","avatar":""},{"name":"Bào Lý Ninh","avatar":""},{"name":"Bạch Húc Hàm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["我的差评女友"]', 1784690324157);
