INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoc-dong-song-bac-phan-2', 'Ngược Dòng Sóng Bạc (Phần 2)', 'Against The Silver Waves (Season 2)', 'https://phimimg.com/upload/vod/20250430-1/df28314fe55385927272b52e0d5656df.jpg', 'https://phimimg.com/upload/vod/20250430-1/df2dd8658e5d2a764596b88ebd2d414c.jpg', '<p>Bạo lực Phần 2 xoay quanh cuộc đời của 4 người con hiếu thảo của cậu Hai, đặc biệt là Oanh Kiều, người đã trở thành nạn nhân của đường dây buôn người. Vất vả lắm mới thoát thân được, Oanh Kiều lại một lần nữa rơi xuống đáy vực khi rơi vào tay tên xã hội đen Du. Huy Khánh lên đường đi tìm chị nhưng cũng gặp vô vàn trắc trở. Ở nhà, chỉ còn lại Kiều Khanh và Minh Khang phải học cách trưởng thành và tìm cách để gìn giữ lại ngôi nhà tổ của ông bà.</p>', 'Hoàn Tất (31/31)', 31, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Khánh Trinh","avatar":""},{"name":"Quang Pháp","avatar":""},{"name":"Hoàng Phong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324157);
