INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoc-dong-song-bac-phan-1', 'Ngược Dòng Sóng Bạc (Phần 1)', 'Against The Silver Waves (Season 1)', 'https://phimimg.com/upload/vod/20250430-1/81ca10bb4c4aaf91b334c5e97780c7e4.jpg', 'https://phimimg.com/upload/vod/20250430-1/0cbd80bba2c56b52bf5d77473db8ddd4.jpg', '<p>Ông Sáu Nên là người nổi tiếng nhất vùng về nghề làm mắm cá linh. Trong số ba người con của ông, chỉ có cậu con trai đầu là yên bề gia thất và kiên nhẫn với nghề gia truyền, còn hai cô con gái thì lại luôn khiến ông phải lo lắng. Những mâu thuẫn trong gia đình ông Sáu Nên bắt đầu trở nên nghiêm trọng hơn khi tên gian thương Tám Cari xuất hiện và khiến cả nhà ông gặp phải hết bất hạnh này đến bất hạnh khác.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Cao Minh Đạt","avatar":""},{"name":"Huy Khánh","avatar":""},{"name":"Thùy Trang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324157);
