INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cocoon-aru-natsu-no-shoujotachi-yori', 'Cocoon: Aru Natsu no Shoujo-tachi yori', 'Cocoon: Aru Natsu no Shoujo-tachi yori', 'https://phimimg.com/upload/vod/20250430-1/3bfcb19a380d0e09a4196ae28dbdbbe2.jpg', 'https://phimimg.com/upload/vod/20250430-1/ed24a6499eaf2062601b7bc1f6c28b35.jpg', '<p>San và Mayu là hai nữ sinh sống tại Okinawa trong những tháng cuối của Chiến tranh Thái Bình Dương. Cùng với các bạn cùng lớp, hai người bạn được đưa vào chiến tranh với tư cách là y tá chăm sóc những người lính bị thương. Khi được lệnh phải chết vì đất nước, những thành viên còn lại của nhóm đã trốn thoát chỉ để đối mặt với môi trường khắc nghiệt của một thiên đường nhiệt đới đã trở thành chiến trường địa ngục.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Marika Ito","avatar":""},{"name":"Hikari Mitsushima","avatar":""},{"name":"Yoko Hikasa","avatar":""},{"name":"Rena Motomura","avatar":""},{"name":"Chinatsu Akasaki","avatar":""},{"name":"Aoi Koga","avatar":""},{"name":"Yume Miyamoto","avatar":""},{"name":"Izumi Aoyagi","avatar":""},{"name":"Miyuki Sawashiro","avatar":""},{"name":"Umeka Shouji","avatar":""},{"name":"Maria Abo","avatar":""},{"name":"Akane Amasawa","avatar":""},{"name":"Yui Arai","avatar":""},{"name":"Saaya Okutomo","avatar":""},{"name":"Hayato Kimura","avatar":""},{"name":"Saki Kobari","avatar":""},{"name":"Rei Sonoda","avatar":""},{"name":"Norihito Hase","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["cocoon（コクーン） ～ある夏の少女たちより～","コクーン ～ ある夏の少女たちより～","コクーン","Cocoon","cocoon ~Aru Natsu no Shouj