INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cocoon-aru-natsu-no-shoujotachi-yori', 'Cocoon: Aru Natsu no Shoujo-tachi yori', 'Cocoon: Aru Natsu no Shoujo-tachi yori', 'cocoon: aru natsu no shoujo-tachi yori cocoon: aru natsu no shoujo-tachi yori marika ito hikari mitsushima yoko hikasa rena motomura chinatsu akasaki aoi koga yume miyamoto izumi aoyagi miyuki sawashiro umeka shouji maria abo akane amasawa yui arai saaya okutomo hayato kimura saki kobari rei sonoda norihito hase j cocoon（コクーン） ～ある夏の少女たちより～ コクーン ～ ある夏の少女たちより～ コクーン cocoon cocoon ~aru natsu no shoujo-tachi yori~ cocoon ~aru natsu no shōjo-tachi yori~ cocoon: aru natsu no shōjo-tachi yori кокон cocoon – one summer of girlhood cocoon: from the girls of summer cocoon ~from the girls of summer~ cocoon～ある夏の少女たちより～', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pho-nhan', 'Phó Nhận', 'Born To Die', 'https://phimimg.com/upload/vod/20250210-1/8dcbd502b8848dc351b60f173b72509e.jpg', 'https://phimimg.com/upload/vod/20250210-1/23f32456cf71276f386eb6a4b3af7975.jpg', '<p>Nữ tướng quân Tống Điểm Tâm của nước Hải Ngân bị vu oan thông đồng với địch và chết thảm. Trước khi chết, cô phát hiện ra kẻ đã hãm hại mình chính là vị hôn phu Thẩm Mộ Tư. Khi sống lại, Tống Điểm Tâm quyết đoán hủy hôn ước, mở màn bằng một trận đòn tàn nhẫn với trai tồi, tự tay xử lý kẻ địch. Nhưng không ngờ Thẩm Mộ Tư cũng chỉ bị kẻ gian hãm hại, sau khi sống lại, hắn vừa theo đuổi tình yêu vừa truy tìm chân tướng. Từ đó, cả hai bắt đầu một cuộc tình giằng co người chạy kẻ đuổi, vừa yêu vừa hận đầy kịch tính.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tôn Thần Tuấn","avatar":""},{"name":"Hồ Diệc Dao","avatar":""},{"name":"Vương Tinh Vĩ","avatar":""},{"name":"Kiều Tịnh Văn","avatar":""},{"name":"Lôi Chú","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["女将军请自重","赴刃"]', 1784690324157);
