INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lop-hoc-29-con-tin', 'Lớp Học 29 Con Tin', 'Homeroom 29', 'https://phimimg.com/upload/vod/20250429-1/86a75a7c50146fe42798b0157931829c.jpg', 'https://phimimg.com/upload/vod/20250429-1/6c8a49b6cf7737367e6e50e204ca4b05.jpg', '<p>Một thầy giáo chủ nhiệm bất ngờ bắt giữ 29 học sinh làm con tin để trả thù cho cái chết bí ẩn của một bạn học. Cuộc đối đầu căng thẳng nhanh chóng biến thành bi kịch, vạch trần những góc tối trong tâm hồn con người. Một “bài học máu” bắt đầu – nơi lòng thù hận, nỗi đau và sự thật đan xen đến nghẹt thở.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 30, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Suppasit Jongcheveevat","avatar":""},{"name":"Jennis Oprasert","avatar":""},{"name":"Siwat Jumlongkul","avatar":""},{"name":"Ratchapat Worrasarn","avatar":""},{"name":"Kunjiranut Intarasin","avatar":""},{"name":"Praewa Suthamphong","avatar":""},{"name":"Mahidol Pibulsonggram","avatar":""},{"name":"Worrachai Sirikongsuwan","avatar":""},{"name":"Peemapol Panichtamrong","avatar":""},{"name":"Chaleeda Gilbert","avatar":""},{"name":"Anongnart Yusananda","avatar":""},{"name":"Tanatat Kunaneksin","avatar":""},{"name":"Bi","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '["HOMEROOM 29 Hostages","29 Tua Prakan","Homeroom 29 ตัวประกัน"]', 1784690324157);
