INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-hon-nhan-hanh-phuc-cua-toi-phan-2', 'Cuộc Hôn Nhân Hạnh Phúc Của Tôi (Phần 2)', 'My Happy Marriage (Season 2)', 'cuộc hôn nhân hạnh phúc của tôi (phần 2) my happy marriage (season 2) reina ueda kaito ishikawa ayane sakura koutaro nishiyama hiro shimono houko kuwashima ryohei kimura mi matrimonio felíz meu casamento feliz 我的幸福婚姻 我的美好婚事 我的幸福婚约 mi feliz matrimonio van remény a boldogságra pernikahanku yang bahagia मेरी खुशहाल शादी il mio matrimonio felice watashi no shiawase na kekkon わたしの幸せな結婚・アニメーション わたしのしあわせなけっこん moje szczęśliwe małżeństwo мой счастливый брак my happy marriage hôn nhân hạnh phúc của tôi わたしの幸せな結婚', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-trom-trang-suc-phi-vu-bat-dau', 'Kẻ Trộm Trang Sức: Phi Vụ Bắt Đầu', 'Jewel Thief: The Heist Begins', 'https://phimimg.com/upload/vod/20250428-1/191ce9cfe00a521e6c2c4f9df116f130.jpg', 'https://phimimg.com/upload/vod/20250428-1/286115e6f4e075302cd8fd9c9fe70e17.jpg', '<p>Trong cuộc chiến trí tuệ và ý chí đầy cam go này, thiên tài lừa đảo Rehan nghĩ ra một vụ trộm kim cương trong khi cố gắng qua mặt kẻ thù tàn bạo Rajan.</p>', 'Full', 1, 'single', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Saif Ali Khan","avatar":""},{"name":"Jaideep Ahlawat","avatar":""},{"name":"Nikita Dutta","avatar":""},{"name":"Kunal Kapoor","avatar":""},{"name":"Kulbhushan Kharbanda","avatar":""},{"name":"Gagan Arora","avatar":""},{"name":"Dorendra Singh Loitongbam","avatar":""},{"name":"Peter Muxka Manuel","avatar":""},{"name":"Ayaz Khan","avatar":""},{"name":"Sumit Gulati","avatar":""},{"name":"Shaji Choudhary","avatar":""},{"name":"Priya Sharma","avatar":""},{"name":"Payal Nair","avatar":""},{"name":"Vinay Sharma","avatar":""},{"name":"Chirjyot Singh","avatar":""},{"name":"Meenal Sahu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["ज्वेल थीफ़ - The Heist Begins"]', 1784690324157);
