INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ke-trom-trang-suc-phi-vu-bat-dau', 'Kẻ Trộm Trang Sức: Phi Vụ Bắt Đầu', 'Jewel Thief: The Heist Begins', 'kẻ trộm trang sức: phi vụ bắt đầu jewel thief: the heist begins saif ali khan jaideep ahlawat nikita dutta kunal kapoor kulbhushan kharbanda gagan arora dorendra singh loitongbam peter muxka manuel ayaz khan sumit gulati shaji choudhary priya sharma payal nair vinay sharma chirjyot singh meenal sahu ज्वेल थीफ़ - the heist begins', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tau-thong-nhat', 'Chuyến Tàu Thống Nhất', 'Reunification Express', 'https://phimimg.com/upload/vod/20250428-1/7117a7627b03b5773ffccb4a37088637.jpg', 'https://phimimg.com/upload/vod/20250428-1/53558343c6abc97a02b822cfe099d75b.jpg', '<p>Trên chuyến tàu dài xuyên suốt đất nước có một cô bé theo chân ông mình vào miền Nam thăm lại đồng đội năm xưa. Đó không chỉ là một chuyến đi, mà là hành trình trở về với lịch sử. Từng ga tàu, từng miền đất đi qua đều vang vọng trong lời kể của ông về những trận đánh ác liệt, những hi sinh thầm lặng, và những mốc son chói lọi trong hành trình thống nhất non sông. Chính vì thế, chuyến tàu ấy được mang tên “Thống Nhất” - như một lời nhắc nhớ thiêng liêng về ngày 30/4 lịch sử.</p>', 'Full', 1, 'hoathinh', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Đặng Trung Dũng","avatar":""},{"name":"Lê Thanh Huyền","avatar":""},{"name":"Lê Hồng Yến","avatar":""},{"name":"Ngô Ngọc Long","avatar":""},{"name":"Doãn Đạo Thùy","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324157);
