INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-so-mat-cuc-x', 'Hồ Sơ Mật Cục X', 'Secret Files of XSA', 'https://phimimg.com/upload/vod/20250420-1/a6f445720d6cefcff5385b8800ca2b78.jpg', 'https://phimimg.com/upload/vod/20250420-1/4eb33bef9507f57b333a39548f21f6ab.jpg', '<p>Celeste 1 là một dự án nghiên cứu khoa học rất được quan tâm. Vì chuyện này mà tổ chức gián điệp nước ngoài SAD tiến hành phá hoại, còn Tu La bị nước Sa Bành điều khiển thì muốn đánh cắp công nghệ cốt lõi của nó. Cảnh sát An ninh Quốc gia Hoắc Mẫn cùng các đồng đội đã phá tan âm mưu của SAD, vạch trần chiến lược thâm nhập của Tu La, cuối cùng đưa nội gián và gián điệp ra trước pháp luật.</p>', 'Tập 16', 16, 'series', 'ongoing', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cố Gia Thành","avatar":""},{"name":"Thượng Ngữ Hiền","avatar":""},{"name":"Triệu Nhân Kiệt","avatar":""},{"name":"Lâm Vĩnh Kiện","avatar":""},{"name":"Hứa Văn Quảng","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["国安局密档","X局密档"]', 1784690324157);
