INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kinh-mong', 'Kinh Mộng', 'Once Upon A Dream', 'https://phimimg.com/upload/vod/20250412-1/2a223388980497c3a23b8426ba164eaa.jpg', 'https://phimimg.com/upload/vod/20250412-1/33ccb6cc6623dc96e9af988e9abfafa8.jpg', '<p>Thẩm Thanh Đường nhà tan cửa nát từ khi còn nhỏ, được Bùi Tông Chi, con trưởng dòng chính trạc tuổi mình của phủ Thừa Bình Hầu nhận vào phủ, trở thành đứa con nuôi ăn nhờ ở đậu Bùi phủ, và là muội muội trên danh nghĩa của Bùi Tông Chi. Nhiều năm ở Bùi phủ chịu đựng bất công và chèn ép, người ca ca duy nhất có thể coi là chỗ dựa Bùi Tông Chi cũng là một nhân vật nguy hiểm, khiến cô không thể dò đoán và ứng phó. Áp lực từ mọi phía của Bùi phủ không ngừng khiến Thẩm Thanh Đường suy sụp, vì vậy cô quyết định vùng vẫy thoát khỏi Bùi phủ, rời xa Bùi Tông Chi, trốn khỏi số phận thấp thỏm bất an, nguy hiểm bủa vây này.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hồ Diệc Dao","avatar":""},{"name":"Trương Cảnh Vân","avatar":""},{"name":"Đặng Chí Hạo","avatar":""},{"name":"Tưởng Bằng Vũ","avatar":""},{"name":"Mã Khải Vy","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jing Meng","驚夢","笼中雀：惹上偏执兄长逃不掉","籠中雀：惹上偏執兄長逃不掉","Long Zhong Que: Re Shang Pian Zhi Xiong Zhang Tao Bu Diao","Опасные грёзы","Once Upon a Dream","惊梦"]', 1784690324157);
