INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dat-nuoc-cua-phan-dien', 'Đất Nước Của Phản Diện', 'Villains Everywhere', 'https://phimimg.com/upload/vod/20250325-1/84b38153649a53814c892643b5b3a0b3.jpg', 'https://phimimg.com/upload/vod/20250325-1/b899f2abd2e838a58cd7d6a144146715.jpg', '<p>&quot;Villains Everywhere&quot; là một bộ phim hài tình huống xoay quanh cuộc sống thường ngày của những người chị em trung niên và gia đình đầy cá tính của họ. Phim mang đến những câu chuyện vừa hài hước vừa ấm áp, phản ánh chân thực cuộc sống gia đình.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Oh Na-ra","avatar":""},{"name":"So Yoo-jin","avatar":""},{"name":"Seo Hyun-chul","avatar":""},{"name":"Song Jin-woo","avatar":""},{"name":"Park Young-kyu","avatar":""},{"name":"Shin Shin-ae","avatar":""},{"name":"Han Sung-min","avatar":""},{"name":"Jeong Min-gyu","avatar":""},{"name":"Choi Ye-na","avatar":""},{"name":"Park Tam-hee","avatar":""},{"name":"No Min-woo","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Vilões em Todo Lugar","Vilões pra todo lado","恶人之国","الأشرار في كل مكان","Villain''s Country","빌런의 나라"]', 1784690324157);
