INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-uu-do', 'Vô Ưu Độ', 'The Demon Hunter''s Romance', 'https://phimimg.com/upload/vod/20250412-1/3b6119f613763fd05e373009e1348c5b.jpg', 'https://phimimg.com/upload/vod/20250412-1/0fc3522572f7988eb8a3f2dd0b8134d1.jpg', '<p>Bộ phim kể về mối tình lãng mạn giữa Xuyên Dạ, một thợ săn yêu quái bí ẩn, và Bán Hạ, một cô gái có đôi mắt đặc biệt có thể nhìn thấy những điều người khác không thấy. Trong thế giới nơi con người và yêu quái sống chung, họ cùng nhau điều tra các hiện tượng kỳ lạ ở Quảng Bình. Khi mối quan hệ trở nên sâu sắc, Bán Hạ phát hiện ra bí mật có thể thay đổi tất cả – Xuyên Dạ, dù là thợ săn yêu quái, có thể chính là một yêu quái.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 18, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Nhậm Gia Luân","avatar":""},{"name":"Tống Tổ Nhi","avatar":""},{"name":"Tuyên Ngôn","avatar":""},{"name":"Phạm Soái Kỳ","avatar":""},{"name":"Tôn Phong Nghiêm","avatar":""},{"name":"Tào Tuấn","avatar":""},{"name":"Lưu Nhược Cốc","avatar":""},{"name":"Lưu Kỳ Kỳ","avatar":""},{"name":"Lệ Gia Kỳ","avatar":""},{"name":"Thường Lỗ Phong","avatar":""},{"name":"Hác Lôi","avatar":""},{"name":"Vương Ỷ Dao","avatar":""},{"name":"Lý Tiến Vinh","avatar":""},{"name":"Hani Kyzy","avatar":""},{"name":"Trần Gia Nhạc","avatar":""},{"name":"Tôn Thiên Vũ","avatar":""},{"name":"Trương Lỗi","avatar":""},{"name":"Ngô Sùng Huyền","avatar":""},{"name":"Trần Phương Đồn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387