INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-trom-ma-tuy', 'Kẻ Trộm Ma Túy', 'Dope Thief', 'https://phimimg.com/upload/vod/20250405-1/f27e7236d61de0e96c8a101a70d7bf28.jpg', 'https://phimimg.com/upload/vod/20250405-1/642bc510a87a5489f0fe419ff3d40f94.jpg', '<p>Hai người bạn thân ở Philadelphia giả làm đặc vụ DEA để cướp của các tay buôn ma túy nhỏ. Đó vốn là trò lừa đảo hoàn hảo — cho đến khi họ chọn nhầm chỗ và trở thành mục tiêu của tổ chức ma túy lớn.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Brian Tyree Henry","avatar":""},{"name":"Wagner Moura","avatar":""},{"name":"Marin Ireland","avatar":""},{"name":"Amir Arison","avatar":""},{"name":"Nesta Cooper","avatar":""},{"name":"Kate Mulgrew","avatar":""},{"name":"Ving Rhames","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Ladrões de Drogas","毒窃之徒","毒品窃贼","גנב סמים","Вор дури","Sinking Spring","Dope Thief"]', 1784690324157);
