INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-pha-thuong-khung-4-dao-vong', 'Đấu Phá Thương Khung 4: Đào Vong', 'Fights Break Sphere 4', 'https://phimimg.com/upload/vod/20250426-1/5cd224d4382ceb7c3d2c6a3d8b4258bc.jpg', 'https://phimimg.com/upload/vod/20250426-1/60f4f8df8cc0535a2c95ec50e5dddaaf.jpg', '<p>Tiêu Viêm (do Mã Bá Khiên thủ vai) và Dược Lão (Cao Thự Quang thủ vai) sau khi hóa giải được cuộc đại chiến giữa tộc Xà Nhân và con người, đã cùng Thanh Lân (do Hoàng Văn thủ vai) và Mục Lực (do Lý Cửu Tiêu thủ vai) bước vào hành trình tu luyện, không ngừng nâng cao thực lực. Mục tiêu của họ là giành chiến thắng trong cuộc ước hẹn ba năm với Nạp Lan Yên Nhiên (do Cận Dương Dương thủ vai) – đại đệ tử của Vân Lam Tông. Trên đường đến sa mạc Tagore, Thanh Lân bất ngờ bị bắt cóc...</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Victor Ma","avatar":""},{"name":"Gao Shuguang","avatar":""},{"name":"Li Jiuxiao","avatar":""},{"name":"Jiang Wu","avatar":""},{"name":"Wen Huang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Fights Break Sphere 4","Battle Through the Heavens 4 : The Escape","斗破苍穹4：逃亡"]', 1784690324157);
