INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-ta-2025', 'Chúng Ta', 'Us The Series', 'https://phimimg.com/upload/vod/20250203-1/59e4e76e84e2f6b251ab3213bc323335.jpg', 'https://phimimg.com/upload/vod/20250203-1/f6287c5fe647d6e68fb60fef95eb7a65.jpg', '<p>Mười tám tuổi, Dokrak quyết định nghỉ một năm để tìm hiểu bản thân sau khi tốt nghiệp trung học. Cô có một công việc bán thời gian tại một quán cà phê không gian làm việc chung, Cuf &amp; Co. Tại đây, cô gặp Pam, một sinh viên nha khoa hai mươi hai tuổi, thường xuyên đến quán để học. Khi quen biết Pam, Dokrak phát triển cảm tình với cô ấy. Tuy nhiên, khi anh trai của cô gặp Pam, anh ấy đã yêu cô ấy ngay từ cái nhìn đầu tiên. Kawi quay sang Dokrak, nhờ cô làm mai cho mình. Vì yêu thương anh trai và muốn thấy anh ấy hạnh phúc, Dokrak bắt đầu hướng dẫn anh. Tuy nhiên, theo thời gian, cô không thể phớt lờ tình cảm ngày càng lớn dành cho Pam. Trước khi cô kịp nhận ra, cô đã yêu Pam hoàn toàn và Pam trở thành bạn gái của Kawi.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Pussarasorn Bosuwan","avatar":""},{"name":"Thasorn Klinnium","avatar":""},{"name":"Harit Cheewagaroon","avatar":""},{"name":"Benyapa Jeenprasom","avatar":""},{"name":"Rattanawadee Wongtong","avatar":""},{"name":"Patsit Permpoonsavat","avatar":""},{"name":"Samantha Melanie Coates","avatar":""},{"name":"Leo Saussay","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["我们的爱情","US SERIES","Rak Khong Rao","US : รักของเรา","Us: Our Love","Our Love","Us: The Series","Us รักของเรา"]', 1784690324157);
