INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-thua-ke-duy-nhat', 'Người Thừa Kế Duy Nhất', 'Exclusive Love', 'https://phimimg.com/upload/vod/20250215-1/e345fe459a3ae3ca33e11559fbecbb3c.jpg', 'https://phimimg.com/upload/vod/20250215-1/8cebf092ce86a3934e0e6ca0a82cb53a.jpg', '<p>Wang Chan là người kế thừa công ty tang lễ đầy lo sợ, bị buộc phải hợp tác với giáo viên lạnh lùng Tang Tu-chih. Tu Ching-ho và Chang Yi-ching là hai người bạn thân, nhưng tình cảm bí mật của họ bị đe dọa bởi cuộc hôn nhân sắp đặt của Chang Yi-ching. Giữa những đám tang và đám cưới, hãy cùng theo dõi bốn chàng trai trẻ này vượt qua quá khứ và định nghĩa lại tình yêu có ý nghĩa gì với họ!</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Parker Mao","avatar":""},{"name":"Chang Chia-sheng","avatar":""},{"name":"Wayne Hsu","avatar":""},{"name":"Pu Jing-heng","avatar":""},{"name":"Sun Mai-chieh","avatar":""},{"name":"Leo Cheng","avatar":""},{"name":"Yu Kehong","avatar":""},{"name":"Hsin-Ling Chi","avatar":""},{"name":"An Hao-ying","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["独占接班人","獨佔接班人"]', 1784690324157);
