INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tin-nhan-bi-an', 'Tin Nhắn Bí Ẩn', 'Anonymous Signal', 'https://phimimg.com/upload/vod/20250317-1/14b0d575aff325db875166b82e80d8ec.jpg', 'https://phimimg.com/upload/vod/20250317-1/28e394eceb420a24c3f03a59f48d9aa6.jpg', '<p>Quách Bách Phi, Khương Hi Văn và Lưu Lực cùng gia nhập lực lượng cảnh sát, được cấp trên là La Hữu Bang dẫn dắt, mối quan hệ thầy trò giữa bốn người rất sâu sắc. Nhưng ba năm trước, trong một chiến dịch truy quét tội phạm, sự nóng vội của Bách Phi đã hại chết Hữu Bang, còn Lưu Lực bị trọng thương. Hi Văn từ đó không nhìn mặt Bách Phi, tình bạn rạn nứt. Gần đây, trong quá trình điều tra một vụ án mạng liên hoàn, cả ba một lần nữa kết nối khi liên tiếp nhận được những tin nhắn bí ẩn, mang tính tiên tri và cảnh báo về các vụ án đang và sắp xảy ra. Những tin nhắn bí ẩn luôn dẫn dắt đội phá án cực kỳ nhanh chóng. Nhưng rốt cuộc, người gửi là bạn hay thù?</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 8, 2025, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Trần Sơn Thông","avatar":""},{"name":"Trương Chấn Lãng","avatar":""},{"name":"Lưu Bội Nguyệt","avatar":""},{"name":"Lưu Dĩnh Tuyền","avatar":""},{"name":"Đinh Tử Lãng","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["夺命提示","Death Hint","奪命提示"]', 1784690324157);
