INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-thieu-nu', 'Lang Thiếu Nữ', 'Wolf Girl', 'https://phimimg.com/upload/vod/20250424-1/ec85fa7285874380b97b266c6a593077.jpg', 'https://phimimg.com/upload/vod/20250424-1/d161842ccf9ecf41dfc7622e00ce123d.jpg', '<p>Câu chuyện kể về sự kiện xảy ra mười năm trước, khi Việt Vương Tư Đồ Vấn Thiên (do Vu Ba thủ vai) dẫn đầu binh mã bốn phương tiến hành cuộc vây quét tộc Lang Nguyệt Bạc vào đêm trăng tròn. Vào những đêm trăng tròn, tộc người sói này sẽ hóa thân từ người thành sói, khiến sức mạnh suy giảm nghiêm trọng. Nhân cơ hội đó, họ gần như bị tàn sát đến tuyệt diệt. Chỉ còn lại một cô gái – Ngân Nguyệt Tịch (do Kim Nhã Na thủ vai) may mắn thoát chết. Mười năm sau, Ngân Nguyệt Tịch tái xuất giang hồ, bắt đầu ám sát những người từng tham gia vào cuộc thảm sát tộc mình năm xưa. Tuy nhiên, hai vị đại tướng dưới trướng Việt Vương đã phát hiện tung tích của cô và dồn cô đến bước đường cùng. Đúng lúc nguy cấp, một thiếu niên tên Lục Vân Sơ (do Thiệu Soái thủ vai) bất ngờ ra tay cứu giúp cô. Tuy nhiên, từ đây câu chuyện lại tiếp tục rẽ theo một hướng bất ngờ...</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jin Yanna","avatar":""},{"name":"Shao Shuai","avatar":""},{"name":"Apollo Yu","avatar":""},{"name":"Yang Minna","avatar":""},{"name":"He Murong","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Wolf Girl","狼少女"]', 1784690324157);
