INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xung-dang-de-yeu', 'Xứng Đáng Để Yêu', 'Such A Good Love', 'https://phimimg.com/upload/vod/20250402-1/6b127b2b62e6f79824cca31c06685573.jpg', 'https://phimimg.com/upload/vod/20250402-1/78ba826800031271246d544c53a5697a.jpg', '<p>Bộ phim kể về hành trình tình yêu vừa bình dị vừa mang tính sử thi của một cặp đôi thế hệ 8x tại Bắc Kinh. Khi Chu Thủy, chàng trai tài hoa nhất, gặp Đại Cát, cô gái nghĩa khí nhất, họ nhanh chóng rơi vào lưới tình. Cả hai cùng nhau xây dựng ước mơ trong căn phòng trọ chật chội, tìm niềm vui giữa những ngày tháng khó khăn và đồng cam cộng khổ vượt qua mọi thử thách. Mười tám năm sau, câu chuyện tình yêu ấy được một cặp đôi trẻ thuộc thế hệ 00 phát hiện. Họ trở thành những người chứng kiến và bàn luận về mối tình của thế hệ trước. Sự giao thoa giữa hai thế hệ khơi dậy những ký ức và suy tư về tình yêu: Liệu nó có xứng đáng không? Và liệu chúng ta còn dám yêu như thế nữa không?</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương An Vũ","avatar":""},{"name":"Vương Ngọc Văn","avatar":""},{"name":"Hoàng Tử Kỳ","avatar":""},{"name":"Triệu Giai Lệ","avatar":""},{"name":"Trương Phàm","avatar":""},{"name":"Dương Quân Hạo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["值得爱！","值得愛","Worthy of Love","值得爱"]', 1784690324157);
