INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-nuoc-kieu-den-ngoi-vuong', 'Phi Nước Kiệu Đến Ngôi Vương', 'Race For The Crown', 'https://phimimg.com/upload/vod/20250424-1/98c75d6a88dd31c5b0b5fd675d6ded57.jpg', 'https://phimimg.com/upload/vod/20250424-1/500baa5423f7b844b65feb87533bedea.jpg', '<p>Loạt phim tài liệu đầy cảm hứng này theo chân các nài ngựa, HLV và chủ ngựa chinh phục danh hiệu và vinh quang tại ba giải đua Triple Crown của làng đua ngựa thuần chủng.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Race for the Crown"]', 1784690324157);
