INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tau-hoa', 'Tẩu Hỏa', 'Accidental Firing', 'https://phimimg.com/upload/vod/20250412-1/0b4c850caabb9d6e8249a8d46749146f.jpg', 'https://phimimg.com/upload/vod/20250412-1/7b66cfa4273336f29fad838439fe6595.jpg', '<p>Để đòi lại công lý cho cha mẹ, Lục Diễn từ từ thực hiện kế hoạch, nhưng Mục Lan liên tục phá hỏng kế hoạch của anh. Sau khi tìm hiểu sâu hơn, Lục Diễn phát hiện ra cô chính là cô gái anh thích hồi nhỏ. Cả hai chuyển từ thù địch sang đoàn kết, nhắm vào &quot;Lục Trường Hà&quot; đeo mặt nạ, nhưng &quot;Lục Trường Hòa&quot; đã nhìn thấu mọi thủ đoạn của họ...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đặng Khải","avatar":""},{"name":"Đàm Diêm Diêm","avatar":""},{"name":"Lưu Bác","avatar":""},{"name":"Quách Tấn Đông","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Zou Huo","오발","Вспышка","走火"]', 1784690324157);
