INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muon-mang-ma-song', 'Mượn Mạng Mà Sống', 'A Life For A Life', 'https://phimimg.com/upload/vod/20250420-1/a0a7826c424cffd05ad629be5b3a2efd.jpg', 'https://phimimg.com/upload/vod/20250420-1/b6e2ee2a09df638e985b1b5ff033bb56.jpg', '<p>Vào đầu những năm 90, Đỗ Tương Đông, một sinh viên ưu tú của trường cảnh sát, không ngờ rằng mình lại bị phân công đến trại giam. Trong thời gian trực ban, hai nghi phạm bất ngờ trốn thoát. Một người tử vong, còn một người biến mất không dấu vết. Tội phạm Từ Văn Quốc, kẻ trốn thoát lâu ngày, vẫn lẩn khuất ngoài vòng pháp luật. Đỗ Tương Đông không ngừng truy bắt, nhưng vụ án vẫn bế tắc. Theo năm tháng, cuộc truy đuổi không chỉ ảnh hưởng đến cuộc sống của người thân và bạn bè, mà còn trở thành động lực quyết định, là nền tảng của số phận họ. Hơn 20 năm đối đầu trí tuệ, câu chuyện là minh chứng sống động cho lòng kiên trì và sức mạnh ý chí của con người trước dòng chảy thời gian</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tần Hạo","avatar":""},{"name":"Hàn Canh","avatar":""},{"name":"Chung Sở Hy","avatar":""},{"name":"Sử Bằng Nguyên","avatar":""},{"name":"Lâm Bác Dương","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["借命而生","A Life for a Life"]', 1784690324157);
