INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-bot-dien-thoai-so-9', 'Bí Mật Bốt Điện Thoại Số 9', 'The Secret Of Booth No. 9', 'https://phimimg.com/upload/vod/20250422-1/2e9b1bbd11883677ef1811ce809fca46.jpg', 'https://phimimg.com/upload/vod/20250422-1/147521756f35ade3e1cea6c7a7039b27.jpg', '<p>Nội dung xoay quanh nhân vật Phương Tiểu Tầm, một cô gái trở lại trường học và tình cờ nhận được cuộc gọi từ một bốt điện thoại bí ẩn, kết nối với nam thần đã qua đời nhiều năm trước. Cuộc gọi kỳ lạ này đưa cô quay trở lại quá khứ, bắt đầu hành trình cứu lấy người mình yêu và khám phá những bí mật ẩn giấu.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hàn Cạnh Đức","avatar":""},{"name":"Chu Dạng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["9 Hao Dian Hua Ting De Mi Mi","9号电话亭的秘密"]', 1784690324157);
