INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('qua-tre-de-yeu', 'Quá Trễ Để Yêu', 'Too Late To Love', 'https://phimimg.com/upload/vod/20250424-1/716dcb0e6249724a95d4ed2d5044447a.jpg', 'https://phimimg.com/upload/vod/20250424-1/68bd7b7e4e06b67a03cc7b2f707b1603.jpg', '<p>Bộ phim&nbsp;kể về Linh Tinh Nhã, một nữ bác sĩ trở về Trung Quốc và phát hiện mẹ mình bị sát hại. Cô gia nhập gia đình Phương lão gia để điều tra và trả thù, nhưng khi Phương lão gia bị giết, cô trở thành nghi phạm. Giang Bắc Trần, con nuôi của Phương lão gia và là người yêu cũ của cô, điều tra vụ án, nhưng dần dần nghi ngờ cô đã phản bội mình. Hai người đấu trí, hợp tác tìm ra kẻ giết Phương lão gia, nhưng khi Linh Tinh Nhã phát hiện Giang Bắc Trần có thể là kẻ giết mẹ cô, mọi thứ trở nên phức tạp.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Pan Yihong","avatar":""},{"name":"An Siyu","avatar":""},{"name":"Zhang Zhexu","avatar":""},{"name":"Chen Zhiyi","avatar":""},{"name":"Nie Hanming","avatar":""},{"name":"Lan Jia Zheng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Xiang Ai Hen Wan","相愛恨晚","Love Too Late","相爱恨晚"]', 1784690324157);
