INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-ky-kim-sao-the-ban-thai', 'Thư Ký Kim Sao Thế (Bản Thái)', 'Dear My Secretary (Thailand Version)', 'https://phimimg.com/upload/vod/20250125-1/74f593456b944c9f4c79e1dacd8c202a.jpg', 'https://phimimg.com/upload/vod/20250125-1/d9de7b5ae71c94aa68ef74eba6a96d6a.jpg', '<p>Thư Ký Kim Sao Thế? (Bản Thái) là phiên bản Thái Lan của bộ phim Hàn đình đám cùng tên, xoay quanh chuyện tình hài hước giữa anh sếp Thi và cô thư ký Preem. Là phó chủ tịch một công ty, Thi luôn tự tin thái quá về ngoại hình, tài năng và sự giàu có của mình. Suốt 9 năm, thư ký Preem thông minh và duyên dáng luôn đồng hành, hỗ trợ anh trong mọi việc. Khi Preem bất ngờ xin nghỉ việc, cuộc sống Thi hoàn toàn đảo lộn và anh tìm đủ phương thức, từ hài hước đến lãng mạn, để giữ cô ở lại.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 9, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Jespipat Tilapornputt","avatar":""},{"name":"Bua Nalinthip Sakulongumpai","avatar":""},{"name":"Nitit Warayanon","avatar":""},{"name":"Orn-arnin Peerachakajornpatt","avatar":""},{"name":"Pinyadar Salinvarradar","avatar":""},{"name":"Pitchatorn Santinatornkul","avatar":""},{"name":"Dao Nathapatsorn Simasthien","avatar":""},{"name":"Nont Worawat Boonchuen","avatar":""},{"name":"Patteerat Laemluang","avatar":""},{"name":"Sivakorn Lertchuchot","avatar":""},{"name":"Darina Bo","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Dear My Secretary","What''s Wrong with Secretary Kim","บอสมั่นหน้ากับเลขาตัวตึง"]', 1784690324157);
