INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('everyday-host-club', 'Everyday HOST CLUB', 'Everyday HOST CLUB', 'https://phimimg.com/upload/vod/20250415-1/86b3600e3309600337c1c638a62441b6.jpg', 'https://phimimg.com/upload/vod/20250415-1/3f2857492d866ffe94fc6d035e3c108d.jpg', '<p>Câu chuyện kể về Hajime Sekiguchi, một cựu nhân viên bán bảo hiểm nhân thọ, trong một khoảnh khắc tuyệt vọng, đã tạo ra bước nhảy vọt bất ngờ vào thế giới của chủ nhà. Tại Club One, Hajime thấy mình được bao quanh bởi một dàn nhân vật lập dị: một người dẫn chương trình em trai với 20 năm kinh nghiệm, một cựu thần tượng chuyên về các chiến thuật bán hàng lãng mạn và một người dẫn chương trình siêu hung hăng bị ám ảnh bởi các trò chơi di động. Mặc dù suy nghĩ, Đây không phải là một công việc cho bất cứ ai có tâm trí lành mạnh, Hajime sử dụng các kỹ năng bán hàng bảo hiểm được đánh bóng của mình để thu hút khách hàng và tạo ra một khả năng thích hợp đáng ngạc nhiên cho chính mình.</p>', 'Tập 3', 12, 'hoathinh', 'ongoing', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hiro Shimono","avatar":""},{"name":"Taku Yashiro","avatar":""},{"name":"Tasuku Hatanaka","avatar":""},{"name":"Nobuhiko Okamoto","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Eburi de i Hosuto","えぶりでいホスト"]', 1784690324157);
