INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-an-tran-thanh-long', 'Mê Án Trấn Thanh Long', 'The Mystery Of Dragon Town', 'https://phimimg.com/upload/vod/20250408-1/d0e3380fa9bba9f8a3113f79dd23a1f5.jpg', 'https://phimimg.com/upload/vod/20250408-1/1f61c771b4681f1058bb99032ab59f39.jpg', '<p>Tiểu Cửu là một nữ dẫn xác, vào nửa đêm bất ngờ nhận được một đơn đặt hàng từ người phụ nữ kỳ lạ, yêu cầu cô chuyển thi thể của một thiếu gia giàu có tới một căn nhà cổ. Sau khi hoàn thành nhiệm vụ giao xác, Tiểu Cửu mới phát hiện cha mẹ của cậu thiếu gia đang tổ chức âm hôn cho con trai. Không ngờ, sáng hôm sau họ lại đến nhà tìm cô, nói rằng thi thể con trai đã biến mất, yêu cầu cô phải trả lại xác…</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Nhược Thiên","avatar":""},{"name":"Doãn Nhuỵ","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Qing Long Zhen Mi An","青龙镇谜案"]', 1784690324157);
