INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhan-danh-cai-dep', 'Nhân Danh Cái Đẹp', 'Fight For Beauty', 'https://phimimg.com/upload/vod/20250331-1/4c851cd6a61738b1e7c3991faead677a.jpg', 'https://phimimg.com/upload/vod/20250331-1/f42d73caeea38cb507c863bf01b8e82d.jpg', '<p>Hai bác sĩ phẫu thuật thẩm mỹ xuất thân từ cùng sư môn Kiều Dương và Châu Tĩnh Văn vốn là oan gia nhiều năm, hai người phụ nữ bất ngờ tái ngộ vào thời điểm lúng túng nhất của cuộc đời, như một định mệnh sắp đặt. Cùng là những bác sĩ chủ lực tại bệnh viện thẩm mỹ, họ dẫn dắt đội ngũ riêng của mình, mở ra cuộc tranh luận và va chạm gay gắt xoay quanh các chủ đề về cái đẹp, về nữ giới nơi công sở và về tấm lòng y đức của người bác sĩ. Cho đến khi một kẻ thù lớn hơn xuất hiện, cả hai đã gạt bỏ thành kiến, bắt tay hợp tác, cùng nhau chống lại thế lực hắc ám trong ngành thẩm mỹ chui đầy nguy hiểm. Họ không chỉ giành lại ánh hào quang của nghề y, mà còn hoàn thiện bản thân, trở thành phiên bản đẹp nhất của chính mình.</p>', 'Hoàn Tất (29/29)', 29, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yao Chen","avatar":""},{"name":"Alyssa Chia","avatar":""},{"name":"Hou Wenyuan","avatar":""},{"name":"Yuan Hong","avatar":""},{"name":"Dai Lele","avatar":""},{"name":"Wang Xi","avatar":""},{"name":"Zuo Lingfeng","avatar":""},{"name":"Tan Xihe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["以美之名"]', 1784690324157);
