INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-thuc-mien-que-cung-edward-lee', 'Ẩm Thực Miền Quê Cùng Edward Lee', 'Edward Lee''s Country Cook', 'https://phimimg.com/upload/vod/20250216-1/f649b08727106f2e3ca32079b9bbe3cc.jpg', 'https://phimimg.com/upload/vod/20250216-1/004486e34f3be6052cd05096c615f438.jpg', '<p>Theo chân siêu đầu bếp Edward Lee cùng ba người bạn nổi tiếng trong hành trình tìm kiếm hương vị ẩm thực &quot;chuẩn cơm bà nấu&quot;. Cùng họ đi khắp xứ sở kim chi, nếm thử những món ăn theo mùa, nấu nướng theo công thức đặc biệt từ các vùng quê. Liệu các món ăn của Edward Lee có được các bà, các mẹ công nhận?</p>', 'Hoàn Tất (20/20)', 20, 'tvshows', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Edward Lee","avatar":""},{"name":"Byun Yo-han","avatar":""},{"name":"Ko A-sung","avatar":""},{"name":"Shin Si-a","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["에드워드리의 컨츄리쿡"]', 1784690324157);
