INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-danh-gia', 'Cuộc Đánh Giá', 'The Assessment', 'https://phimimg.com/upload/vod/20250420-1/40b95c8dc880e3943e60c5560bac4d63.jpg', 'https://phimimg.com/upload/vod/20250420-1/8f43e476a8cce09c55e272fdbb81c893.jpg', '<p>The Assessment 2024 Trong một bối cảnh tương lai, nơi tài nguyên cạn kiệt và việc sinh con bị kiểm soát nghiêm ngặt, mỗi cặp đôi mong muốn có con phải trải qua một &quot;bài đánh giá&quot; kéo dài bảy ngày để chứng minh họ xứng đáng làm cha mẹ.Mia (Elizabeth Olsen) và Aaryan (Himesh Patel) là một cặp vợ chồng sống trong một ngôi nhà hiện đại, biệt lập dưới mái vòm bảo vệ. Mia là một nhà thực vật học tận tụy, còn Aaryan thiết kế thú cưng ảo thay thế cho động vật thật đã tuyệt chủng. Họ háo hức chờ đợi bài đánh giá, hy vọng sẽ sớm trở thành cha mẹ.</p>', 'Full', 1, 'single', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Elizabeth Olsen","avatar":""},{"name":"Himesh Patel","avatar":""},{"name":"Alicia Vikander","avatar":""},{"name":"Minnie Driver","avatar":""},{"name":"Indira Varma","avatar":""},{"name":"Charlotte Ritchie","avatar":""},{"name":"Nicholas Pinnock","avatar":""},{"name":"Leah Harvey","avatar":""},{"name":"Benny O. Arthur","avatar":""},{"name":"Thiago Braga de Oliveira","avatar":""},{"name":"Malaya Stern Takeda","avatar":""},{"name":"Anaya Rose","avatar":""},{"name":"Suhayla Balli Al Soufi Del Diego","avatar":""},{"name":"Angeline Padrón Fi","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["La evaluación","The Assessment"]', 1784690324157);
