INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xa-thu-mien-vien-tay-cuoc-do-sung-ac-liet', 'Xạ Thủ Miền Viễn Tây: Cuộc Đọ Súng Ác Liệt', 'Gunslingers', 'https://phimimg.com/upload/vod/20250420-1/043caf8e4376907a6a5b79b8ead38fec.jpg', 'https://phimimg.com/upload/vod/20250420-1/fd99235b3333e62b38e7808a77518f93.jpg', '<p>Khi người đàn ông bị truy nã nhất ở Mỹ xuất hiện trong một thị trấn nhỏ ở Kentucky, lịch sử bạo lực của anh ta-và một đám đông đã tìm kiếm sự báo thù và một vị vua tiền chuộc-sớm theo sau. Khi anh em đối đầu với nhau và Bullets xé nát thị trấn để phá hủy, tay súng nhanh như chớp này khiến kẻ thù của anh ta phải trả giá cao cho lòng tham của họ.</p>', 'Full', 1, 'single', 'completed', 19, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Stephen Dorff","avatar":""},{"name":"Heather Graham","avatar":""},{"name":"Nicolas Cage","avatar":""},{"name":"Randall Batinkoff","avatar":""},{"name":"Cooper Barnes","avatar":""},{"name":"Tzi Ma","avatar":""},{"name":"Jeremy Kent Jackson","avatar":""},{"name":"Costas Mandylor","avatar":""},{"name":"Scarlet Rose Stallone","avatar":""},{"name":"William McNamara","avatar":""},{"name":"Mohamed Karim","avatar":""},{"name":"Bre Blair","avatar":""},{"name":"Forrest Wilder","avatar":""},{"name":"Forrie J. Smith","avatar":""},{"name":"Laurie Love","avatar":""},{"name":"Ava Monroe Tadros","avatar":""}]', '[{"name":"Miền Tây","slug":"mien-tay","id":"d111447ee87ec1a46a31182ce4623662"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["هفت‌تیرکش‌ها","אקדוחנים","Tierra de fugitivos","Gunslingers"]', 1784690324157);
