INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-tim-chon-vui', 'Trái Tim Chôn Vùi', 'Buried Hearts', 'https://phimimg.com/upload/vod/20250221-1/cb9ab4376f17d8d8aecb9eb4c8e330a2.jpg', 'https://phimimg.com/upload/vod/20250301-1/8383e451e3bc812d346970a92110d72d.jpg', '<p>Phim xoay quanh câu chuyện kể về Seo Dong Joo (Park Hyung Sik thủ vai) là một hacker thiên tài làm việc trong văn phòng thư ký chủ tịch tại Tập đoàn Daesan. Anh được biết đến với cái tên “Daesan Man”, một người sống chết vì lợi ích của Tập đoàn Daesan, nhưng che giấu tham vọng muốn chiếm lấy tập đoàn khi có cơ hội. Để làm được điều đó, Seo Dong Joo phải đánh bại được Yeom Jang Sun (Heo Jun Ho đóng) người có ảnh hưởng nhất trong thế giới chính trị Hàn Quốc, sử dụng tiền bạc và quyền lực để kiểm soát mọi người như một niềm vui.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Hyung-sik","avatar":""},{"name":"Huh Joon-ho","avatar":""},{"name":"Hong Hwa-yeon","avatar":""},{"name":"Gong Ji-ho","avatar":""},{"name":"Kwon Soo-hyun","avatar":""},{"name":"Youn Sang-hyun","avatar":""},{"name":"Woo Hyeon","avatar":""},{"name":"Cha Woo-min","avatar":""},{"name":"Lee Hae-yeong","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["金银岛","宝藏岛","قلوب مدفونة","Treasure Island","Buried Hearts","보물섬"]', 1784690324157);
