INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('trai-tim-chon-vui', 'Trái Tim Chôn Vùi', 'Buried Hearts', 'trái tim chôn vùi buried hearts park hyung-sik huh joon-ho hong hwa-yeon gong ji-ho kwon soo-hyun youn sang-hyun woo hyeon cha woo-min lee hae-yeong 金银岛 宝藏岛 قلوب مدفونة treasure island buried hearts 보물섬', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-gian-co-em', 'Thời Gian Có Em', 'With Love With You', 'https://phimimg.com/upload/vod/20250407-1/5366e0485698ab481efaa14686949c01.jpg', 'https://phimimg.com/upload/vod/20250407-1/939c714094475805dacb3a08b0611705.jpg', '<p>Hai chị em nhà họ Vương có tính cách hoàn toàn khác biệt từ nhỏ. Chị gái Vương Diễm mắc bệnh thiếu máu bẩm sinh, còn em gái Vương Linh Quân thì bướng bỉnh và nghịch ngợm. Bất chấp sự phản đối của gia đình, Vương Linh Quân đến Thâm Quyến, làm xáo trộn cuộc sống tưởng chừng yên bình của Vương Diễm – người cũng đang sống tại đây. Sau khi thất nghiệp, Vương Linh Quân chuyển đến ở nhờ nhà chị gái. Ban đầu, cuộc sống chung giữa hai người thường xuyên &quot;gà bay chó sủa&quot;, nhưng dần dần trở nên hòa thuận và ấm áp. Cả hai cũng lần lượt tìm thấy tình yêu cho riêng mình. Khi bệnh cũ của Vương Diễm tái phát, Vương Linh Quân – người từng muốn thoát khỏi chị gái – đã lựa chọn ở lại bên cạnh và chăm sóc chị. Trải qua những sóng gió trong công việc và cuộc sống, Vương Diễm cuối cùng cũng buông bỏ gánh nặng tâm lý, còn Vương Linh Quân cũng xóa bỏ mọi hiềm khích. Hai chị em cùng nhau bắt đầu một cuộc sống mới.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đồng Dao","avatar":""},{"name":"Chu Y Nhiên","avatar":""},{"name":"Lý Trạch Phong","avatar":""},{"name":"Trương Tử Hiền","avatar":""},{"name":"Mã Bá Khiêm","avatar":""},{"name":"Tưởng Mộng Kiều","avatar":""},{"name":"Vương Tĩnh Tùng","avatar":""},{"name":"Lưu Đan","avatar":""},{"name":"Lý Kiến Nghĩa","avatar":""},{"name":"Mã Đức Chung","avatar":""},{"name":"Lưu Quán Lân","avatar":""},{"name":"Đồng Thần Kiệt","avatar":""},{"name":"Dương Minh Na","avatar":""},{"name":"Lưu Khiết","avatar":""},{"name":"Đường Hiểu Thiên","avatar":""},{"name":"Kim Sủng","avatar":""},{"name":"Ninh Tâm","avatar":""},{"name":"Vương Cảnh Diễn","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["你是光阴派的糖","有你的時光裡","有你的时光里"]', 1784690324157);
