INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thoi-gian-co-em', 'Thời Gian Có Em', 'With Love With You', 'thời gian có em with love with you đồng dao chu y nhiên lý trạch phong trương tử hiền mã bá khiêm tưởng mộng kiều vương tĩnh tùng lưu đan lý kiến nghĩa mã đức chung lưu quán lân đồng thần kiệt dương minh na lưu khiết đường hiểu thiên kim sủng ninh tâm vương cảnh diễn 你是光阴派的糖 有你的時光裡 有你的时光里', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-cua-anh-ay', 'Bí Mật Của Anh Ấy', 'His Secret', 'https://phimimg.com/upload/vod/20250418-1/fbc7f941599f14ff24382b3d00c613c7.jpg', 'https://phimimg.com/upload/vod/20250418-1/bec465ca026566766eff8ed82b4c5c1a.jpg', '<p>Lý Du Nhiên vì muốn giành quyền kiểm soát công ty mà bất ngờ kết hôn chớp nhoáng với người đàn ông bí ẩn Cố Nam Sơn. Tuy nhiên, cô lại rơi vào vô số nguy cơ rình rập: bên ngoài thì bị lão thành viên kỳ cựu Lục Kiến An thách thức và mưu đoạt quyền lực, bên trong thì thân phận thật sự của Cố Nam Sơn lại đầy uẩn khúc và khó lường. Ngay cả những người bạn thân thiết bên cạnh cô cũng dần trở nên xa lạ, khiến cô không thể phân biệt đâu là bạn, đâu là thù.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Tuyết Nhi","avatar":""},{"name":"Lý Triết Hào","avatar":""},{"name":"Trương Lục","avatar":""},{"name":"Thang Gia Văn","avatar":""},{"name":"Cao Phong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ta De Mi Mi","他的秘密"]', 1784690324157);
