INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-vu-khuynh-thanh', 'Hỏa Vũ Khuynh Thành', 'Blazing Elegance', 'https://phimimg.com/upload/vod/20250327-1/bc5eb68dcf32d8eb9aac1b48a08ac198.jpg', 'https://phimimg.com/upload/vod/20250327-1/1438fccb597f212d4143b91e688935c9.jpg', '<p>Nữ giáo viên trung học Triệu Tinh Nhu và thiếu soái quyền lực của quân phiệt Dịch Thu Đình yêu nhau. Vì sự khác biệt về gia thế, tình yêu của họ gặp phải nhiều cản trở. Những hành động cưỡng ép và bá đạo của Dịch Thu Đình đã khiến mối quan hệ giữa hai người ngày càng rạn nứt. Khi tưởng rằng đã mất đi đứa con, Triệu Tinh Nhu quyết định giả chết và rời đi. Nhiều năm sau, cô quay trở lại với một con người hoàn toàn mới. Cô dùng hành động chứng minh rằng phụ nữ hoàn toàn có thể sống tỏa sáng với tính cách độc lập.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wanyan Luorong","avatar":""},{"name":"Zhong Lili","avatar":""},{"name":"Zheng Fanxing","avatar":""},{"name":"Zhang Dayuan","avatar":""},{"name":"Zhan Xuan","avatar":""},{"name":"Yu Luna","avatar":""},{"name":"Qiao Xin","avatar":""},{"name":"Jiang Shiqi","avatar":""},{"name":"Jiang Yisheng","avatar":""},{"name":"Liu Haoqun","avatar":""},{"name":"Feng Ziyi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Huo Wu Qing Cheng","화무경성: 비틀린 애정","Fire Dance","火舞倾城"]', 1784690324157);
