INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sampung-utos-kay-josh', 'Mười Điều Răn Cho Josh', 'Sampung Utos Kay Josh', 'https://phimimg.com/upload/vod/20250418-1/3c2ca714477e54e518c28bcfa0e0ba40.jpg', 'https://phimimg.com/upload/vod/20250418-1/e314827086c511ed200f753c1f16370f.jpg', '<p>Josh là một tín đồ Kitô giáo sùng đạo cho đến khi mọi thứ bất ngờ trật khỏi quỹ đạo. Giờ đây, anh lao vào thực hiện một sứ mệnh đầy hài hước: phá vỡ toàn bộ Mười Điều Răn.</p>', 'Full', 1, 'single', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Jerald Napoles","avatar":""},{"name":"Pepe Herrera","avatar":""},{"name":"Irma Adlawan","avatar":""},{"name":"Edgar Mortiz","avatar":""},{"name":"Albie Casiño","avatar":""},{"name":"Debbie Garcia","avatar":""},{"name":"James Caraan","avatar":""},{"name":"GB Labrador","avatar":""},{"name":"Ashley Rivera","avatar":""},{"name":"Blucher Abang","avatar":""},{"name":"Rolando Inocencio","avatar":""},{"name":"Alex Vincent Medina","avatar":""},{"name":"Donna Cariaga","avatar":""},{"name":"Joel Saracho","avatar":""},{"name":"Raffy Tejada","avatar":""},{"name":"Sunny Dumayas","avatar":""},{"name":"James Sales","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sampung Utos Kay Josh"]', 1784690324157);
