INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-trang', 'Phỏng Trang', 'Love Behind The Mask', 'https://phimimg.com/upload/vod/20250321-1/ce61b019534569cbc75dccbef57d1461.jpg', 'https://phimimg.com/upload/vod/20250321-1/217a9aa82ba38cd6cdc709f864ff27bc.jpg', '<p>Tư Dật Thần, con trai của Tử Thương Vương bị sát hại vào ngày đại hôn nên đã đổi tên thành Mộ Hàn và lên kế hoạch cẩn thận để lấy lòng tin của trưởng công chúa và trả thù cho gia đình mình. Vị hôn thê Hàng An Ninh của Tư Dật Thần nhầm tưởng Tư Dật Thần cũng đã bị giết nên lẻn vào phủ công chúa và đổi mặt với trưởng công chúa để tìm cơ hội trả thù. Hai con người che giấu danh tính dần dần nảy sinh tình cảm với nhau dưới một mái nhà, và sự vướng mắc yêu-ghét là điều khó tránh khỏi...</p>', 'Hoàn Tất (34/34)', 34, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Hân Dư","avatar":""},{"name":"Quản Nhạc","avatar":""},{"name":"Quyền Phái Luân","avatar":""},{"name":"Từ Chẩn Chẩn","avatar":""},{"name":"Sử Khanh Nghiên","avatar":""},{"name":"Lãnh Ba","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Fang Zhuang","방장 : 가면 뒤의 사랑","仿妆"]', 1784690324157);
