INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bach-khoa-thu-istanbul', 'Bách Khoa Thư Istanbul', 'Istanbul Encyclopedia', 'https://phimimg.com/upload/vod/20250418-1/052319a0abfbfa0f1abe6efe27eda27a.jpg', 'https://phimimg.com/upload/vod/20250418-1/57f90f7229e8b641d99aa488f1b13994.jpg', '<p>Một sinh viên trẻ chuyển đến sống cùng một người bạn xa cách của gia đình ở Istanbul, từ bỏ quê nhà khiêm tốn để đến một thành phố thử thách danh tính và niềm tin của cô.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 24, 2025, 'Vietsub', 'FHD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Helin Kandemir","avatar":""},{"name":"Canan Ergüder","avatar":""},{"name":"Kaan Mirac Sezen","avatar":""},{"name":"Müjde Ar","avatar":""},{"name":"Nezaket Erden","avatar":""},{"name":"Tolga Tekin","avatar":""},{"name":"Grégory Montel","avatar":""},{"name":"Ecem Sena Bayır","avatar":""},{"name":"Ebrar Karabakan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Istanbul Enzyklopädie","Encyclopédie d''Istanbul","موسوعة إسطنبول","İstanbul Ansiklopedisi"]', 1784690324157);
