INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-hoang-luc', 'Thành Hoàng Lục', 'Phoenix''s Gambit: Love Or Crown', 'https://phimimg.com/upload/vod/20250416-1/2cdb4b57ea92e636806d727d034eb723.jpg', 'https://phimimg.com/upload/vod/20250416-1/c1c6dc33366e0c4db79c184f9807505a.jpg', '<p>Thứ nữ của phủ Thượng thư, Bạch Tịch Nguyệt là kẻ thâm sâu khó lường. Nàng từng hại chết đích tỷ là Bạch Tịch Dao, lại còn dụ dỗ quốc công Vân Nghệ Thần, cuối cùng bước lên ngôi vị hoàng hậu. Nhưng ngay trong lễ phong hậu, nàng trúng độc và chết thảm. Sau khi sống lại, Bạch Tịch Nguyệt mang theo ký ức kiếp trước, sống lại trong thân xác của chính tỷ tỷ mình Bạch Tịch Dao. Lần này, nàng phải đối diện với phiên bản trẻ tuổi, tàn nhẫn của chính mình kiếp trước. Tất cả những mưu kế nàng từng dùng, nay lại đổ lên đầu mình. Nàng phải vừa giữ mình, chuộc lại lỗi lầm, vừa đối mặt với mối tình rối ren đầy ngang trái.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Gao Siwen","avatar":""},{"name":"Lu Dongxu","avatar":""},{"name":"Wang Yani","avatar":""},{"name":"Cui Xuyu","avatar":""},{"name":"Zhu Xingjian","avatar":""},{"name":"Tang Yuan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Cheng Huang Lu","성황록 : 내가 괴롭힌 언니에게 환생했다","成凰录"]', 1784690324157);
