INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('banh-xe-thoi-gian-phan-3', 'Bánh Xe Thời Gian (Phần 3)', 'The Wheel Of Time (Season 3)', 'https://phimimg.com/upload/vod/20250316-1/979df98aa1b6439f7664d310a1863400.jpg', 'https://phimimg.com/upload/vod/20250316-1/41ee44e07b002407899362d5730ed943.jpg', '<p>Nội dung phim dựa trên bộ sách của Robert Jordan, lấy bối cảnh một thế giới giả tưởng cao cấp, nơi có phép thuật, nhưng chỉ một số người mới có thể tiếp cận nó, một người phụ nữ tên là Moiraine băng qua đường với 5 nam nữ thanh niên. Điều này gây ra một cuộc hành trình nguy hiểm, trải dài khắp thế giới.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rosamund Pike","avatar":""},{"name":"Daniel Henney","avatar":""},{"name":"Josha Stradowski","avatar":""},{"name":"Zoë Robins","avatar":""},{"name":"Madeleine Madden","avatar":""},{"name":"Marcus Rutherford","avatar":""},{"name":"Dónal Finn","avatar":""},{"name":"Ceara Coveney","avatar":""},{"name":"Natasha O''Keeffe","avatar":""},{"name":"Ayoola Smart","avatar":""},{"name":"Kae Alexander","avatar":""},{"name":"Kate Fleetwood","avatar":""},{"name":"Sophie Okonedo","avatar":""},{"name":"Priyanka Bose","avatar":""},{"name":"Taylor Napier","avatar":""},{"name":"Jennifer Cheon Ga","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Wheel of Time Origins","The Wheel of Time Origin Stories","The Wheel of Time"]', 1784690324157);
