INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('banh-xe-thoi-gian-phan-3', 'Bánh Xe Thời Gian (Phần 3)', 'The Wheel Of Time (Season 3)', 'bánh xe thời gian (phần 3) the wheel of time (season 3) rosamund pike daniel henney josha stradowski zoë robins madeleine madden marcus rutherford dónal finn ceara coveney natasha o''keeffe ayoola smart kae alexander kate fleetwood sophie okonedo priyanka bose taylor napier jennifer cheon ga the wheel of time origins the wheel of time origin stories the wheel of time', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuy-quai-ho-nhi-long', 'Thủy Quái Hồ Nhị Long', 'Er Long Lake Monster', 'https://phimimg.com/upload/vod/20250417-1/953bf23b6034ef7c2451c23db864a1fe.jpg', 'https://phimimg.com/upload/vod/20250417-1/22309fcf8033678ca2d0e3a879170a0b.jpg', '<p>Thế chiến thứ hai nổ ra, khi quân Nhật xâm chiếm vùng Đông Bắc, họ nhiều lần cử một đội quân bí ẩn tiến vào hang động khổng lồ gần khu vực Tích Tháp Chủy Tử. Tương truyền, người Nhật đã phát hiện một kho báu khổng lồ tại nơi này. 65 năm sau, một tỷ phú Nhật Bản đến hồ Nhị Long để đầu tư xây dựng nhà máy. Không ngờ, điều này vô tình đánh thức một quái vật dưới nước, khiến hồ Nhị Long trở thành tâm điểm chú ý của cả nước. Từ đây, một loạt câu chuyện hài hước xoay quanh con thủy quái kỳ bí bắt đầu mở ra…</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jiu Kong","avatar":""},{"name":"Li Fei Er","avatar":""},{"name":"Sun Yue","avatar":""},{"name":"Chen Haoming","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Monster of Er Long Lake","Er Long Hu Shui Guai","二龍湖水怪","二龙湖水怪"]', 1784690324157);
