INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thuy-quai-ho-nhi-long', 'Thủy Quái Hồ Nhị Long', 'Er Long Lake Monster', 'thủy quái hồ nhị long er long lake monster jiu kong li fei er sun yue chen haoming monster of er long lake er long hu shui guai 二龍湖水怪 二龙湖水怪', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doat-thien-khuyet', 'Đoạt Thiên Khuyết', 'The Seized Destiny', 'https://phimimg.com/upload/vod/20250406-1/3d2301403ccdce5a1993b614095c8328.jpg', 'https://phimimg.com/upload/vod/20250406-1/904f620ae84e8613c9ebd42b46cde10f.jpg', '<p>Trong lễ thăng cấp của nữ tu Long Khưu Thừa Nhan, nàng bị sư huynh Thừa Thiên ép buộc phải song tu với hắn. Trong lúc tuyệt vọng, Thừa Nhan quyết định tự nổ nội đan và được ma thú Trần - kẻ đã ký kết khế ước linh thú với nàng cứu. Khi Thừa Nhan biết bây giờ Thừa Thiên đã bị một ma thú thượng cổ tên Sát chiếm mất xác thì quyết tâm bắt đầu con đường báo thù. Nàng luyện thần khí thượng cổ để khôi phục nội đan nhưng không may trúng độc, chẳng còn sống được bao lâu. Thừa Nhan quyết định thành thân với Trần, song ngay ngày hôm sau thì nàng lại đích thân đưa Trần trở về Ma giới, còn bản thân thì bị giết. Trần tức giận đến cực điểm, hùng hổ quay về Long Khưu. Không ngờ Thừa Nhan lại trọng sinh thành huyền nữ Lộc Minh. Nàng muốn lợi dụng thân phận này để phong ấn Sát một lần nữa nhưng lại bị đối phương phát hiện. Cuối cùng, nàng và Trần sát cánh chiến đấu trong trận quyết chiến với Sát, phong ấn hắn hoàn toàn, mang lại thái bình cho tam giới.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 33, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Phương Đồng","avatar":""},{"name":"Phương Hiểu Đông","avatar":""},{"name":"Giang Vũ Thuận","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Thần Thoại","slug":"than-thoai","id":"2276b29204c46f75064735477890afd6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Duo Tian Que","Take the Sky","The Seized Destiny","夺天阙"]', 1784690324157);
