INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chin-thi-the-noi-rung-ram-mexico', 'Chín Thi Thể Nơi Rừng Rậm Mexico', 'Nine Bodies In A Mexican Morgue', 'https://phimimg.com/upload/vod/20250327-1/9524f5a50db5dce9b1d340ebe996a49f.jpg', 'https://phimimg.com/upload/vod/20250327-1/f3442ffcc4e1c825d798e664776dd21c.jpg', '<p>Hãy theo dõi câu chuyện về chín người xa lạ bị lạc trong một khu rừng hẻo lánh ở Mexico sau khi chiếc máy bay nhỏ chở họ từ Guatemala đến Mỹ gặp nạn. Từng người một trong số họ bị sát hại, buộc những người còn sống phải tìm ra bí ẩn kinh hoàng trước khi họ cũng trở thành nạn nhân tiếp theo.</p>', 'Tập 6', 6, 'series', 'ongoing', 11, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Anh', 0, '[{"name":"Eric McCormack","avatar":""},{"name":"David Ajala","avatar":""},{"name":"Lydia Wilson","avatar":""},{"name":"Adam Long","avatar":""},{"name":"Jan Le","avatar":""},{"name":"Siobhán McSweeney","avatar":""},{"name":"Peter Gadiot","avatar":""},{"name":"Carolina Guerra","avatar":""},{"name":"Ólafur Darri Ólafsson","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Nove Ombre Nella Giungla Messicana","تسعة جثث في مشرحة مكسيكية","Nine Bodies in a Mexican Morgue"]', 1784690324157);
