INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chin-thi-the-noi-rung-ram-mexico', 'Chín Thi Thể Nơi Rừng Rậm Mexico', 'Nine Bodies In A Mexican Morgue', 'chín thi thể nơi rừng rậm mexico nine bodies in a mexican morgue eric mccormack david ajala lydia wilson adam long jan le siobhán mcsweeney peter gadiot carolina guerra ólafur darri ólafsson nove ombre nella giungla messicana تسعة جثث في مشرحة مكسيكية nine bodies in a mexican morgue', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-goi-khan-cap-119', 'Cuộc Gọi Khẩn Cấp 119', '119 Emergency Call', 'https://phimimg.com/upload/vod/20250406-1/7197cb47ebdc11a7f7be7e56bb2e8180.jpg', 'https://phimimg.com/upload/vod/20250406-1/26333c28c69154a7b0cabbdc9d53a47f.jpg', '<p>Tổng đài 119 là đầu số tiếp nhận các cuộc gọi báo cháy hoặc yêu cầu cấp cứu khẩn cấp. Chỉ dựa vào âm thanh và các thông tin có thể khai thác được, các điều phối viên phải nhanh chóng xác định trình trạng của nạn nhân để đưa ra hướng dẫn chính xác và kịp thời. Mỗi thành viên của Đội 3 – Sở cứu hỏa Yokohama đều có lý tưởng khác nhau nhưng tất cả đều cùng chung một mục tiêu: Đáp lại lời kêu cứu và giúp đỡ nạn nhân ở đầu dây bên kia.</p>', 'Full', 11, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Nana Seino","avatar":""},{"name":"Koji Seto","avatar":""},{"name":"Ai Mikami","avatar":""},{"name":"Hayate Ichinose","avatar":""},{"name":"Kou Maehara","avatar":""},{"name":"Koichi Sato","avatar":""},{"name":"Yuri Nakamura","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["119 Emergency Call","119エマージェンシーコール"]', 1784690324157);
