INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-an-ufo', 'Dự Án UFO', 'Project UFO', 'https://phimimg.com/upload/vod/20250417-1/2e40f790393d60b96f499d136740f9b0.jpg', 'https://phimimg.com/upload/vod/20250417-1/68744c7508d8e792d78e8f7d0d6e2263.jpg', '<p>Một MC tự mãn và một nhà nghiên cứu UFO ở thị trấn nhỏ cùng điều tra nguồn gốc của một vụ được cho là nhìn thấy UFO, khiến cả nước chia rẽ giữa làn sóng hoài nghi và tin tưởng.</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Ba Lan', 0, '[{"name":"Piotr Adamczyk","avatar":""},{"name":"Mateusz Kościukiewicz","avatar":""},{"name":"Maja Ostaszewska","avatar":""},{"name":"Julia Kijowska","avatar":""},{"name":"Adam Woronowicz","avatar":""},{"name":"Stanisław Pąk","avatar":""},{"name":"Marianna Zydek","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Projekt UFO"]', 1784690324157);
