INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('du-an-ufo', 'Dự Án UFO', 'Project UFO', 'dự án ufo project ufo piotr adamczyk mateusz kościukiewicz maja ostaszewska julia kijowska adam woronowicz stanisław pąk marianna zydek projekt ufo', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nua-doi-sau-cua-toi', 'Nửa Đời Sau Của Tôi', 'Love Again', 'https://phimimg.com/upload/vod/20250331-1/95033d45f4118b98676149417bd1bbeb.jpg', 'https://phimimg.com/upload/vod/20250331-1/a60ff6c8ab9de1d057458687fbbc8304.jpg', '<p>Thẩm Trác Nhiên là một giáo sư khoa Văn đã nghỉ hưu, có đủ nếp đủ tẻ, ba thế hệ cùng chung sống dưới một mái nhà. Sau khi người vợ quá cố qua đời, ông bắt đầu hành trình xem mắt dưới sự khích lệ của những người bạn cũ. Trong quá trình ấy, ông lần lượt gặp gỡ bốn đối tượng. Một y tá trưởng thấu hiểu lòng người nhưng đã rời xa ông vì chuyện nhà cửa; một nhà khoa học nữ vì bệnh ung thư tái phát mà lặng lẽ rút lui không lời từ biệt; một chủ nhiệm công đoàn với tính cách áp đặt khiến ông cảm thấy bị đè nén về mặt tâm lý; và một người phụ nữ có ngoại hình rất giống người vợ quá cố lại đưa ra một yêu cầu khiến ông lâm vào tình thế khó xử. Những trải nghiệm tình cảm khác nhau ấy đã mang đến cho Thẩm Trác Nhiên sự trưởng thành mới. Những suy ngẫm của ông về tình yêu và cuộc sống cũng ảnh hưởng đến các thành viên trong gia đình luôn bên ông trên suốt chặng đường ấy.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Quốc Lập","avatar":""},{"name":"Đồng Đại Vỹ","avatar":""},{"name":"Mai Đình","avatar":""},{"name":"Hứa Đệ","avatar":""},{"name":"Chu Dã Mang","avatar":""},{"name":"Yang Tongshu","avatar":""},{"name":"Nghiêm Hiểu Tần","avatar":""},{"name":"Đinh Gia Lệ","avatar":""},{"name":"Ổ Quân Mai","avatar":""},{"name":"Trương Phong Nghị","avatar":""},{"name":"Hàn Đồng Sinh","avatar":""},{"name":"Tề Hoan","avatar":""},{"name":"Thẩm Giai Ni","avatar":""},{"name":"Vương Chân Nhi","avatar":""},{"name":"Trịnh Vệ Lị","avatar":""},{"name":"Lương Gia Đồng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["老爸去相亲","Love Again","我的后半生"]', 1784690324157);
