INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-dat-bi-quen-lang', 'Vùng Đất Bị Quên Lãng', 'In The Lost Lands', 'https://phimimg.com/upload/vod/20250416-1/d3745356b32e5db6c9f7476cad26473a.jpg', 'https://phimimg.com/upload/vod/20250416-1/5dead262590b1f4977ca5a76e5941e24.jpg', '<p>Một nữ hoàng đã phái nữ phù thủy quyền năng và đáng sợ Gray Alys đến vùng đất ma quái Lost Lands để tìm kiếm sức mạnh ma thuật, nơi nữ phù thủy và người hướng dẫn của cô, kẻ lang thang Boyce phải đánh bại và vượt qua cả con người và ác quỷ....</p>', 'Full', 1, 'single', 'completed', 25, 2025, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Milla Jovovich","avatar":""},{"name":"Dave Bautista","avatar":""},{"name":"Arly Jover","avatar":""},{"name":"Amara Okereke","avatar":""},{"name":"Fraser James","avatar":""},{"name":"Deirdre Mullins","avatar":""},{"name":"Sebastian Stankiewicz","avatar":""},{"name":"Tue Lunding","avatar":""},{"name":"Jacek Dzisiewicz","avatar":""},{"name":"Ian Hanmore","avatar":""},{"name":"Eveline Hall","avatar":""},{"name":"Kamila Klamut","avatar":""},{"name":"Caoilinn Springall","avatar":""},{"name":"Jan Kowalewski","avatar":""},{"name":"Pawel Wysocki","avatar":""},{"name":"Simon Lööf","avatar":""},{"name":"Tomasz","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["在失落之地","في الأراضي المفقودة","Tierras perdidas","In the Lost Lands","Dans les contrées perdues","魔域女巫","A Kárhozott Vidék","Prarastose žemėse","В потерянных землях","Čarodejnica a lovec"]', 1784690324157);
