INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vung-dat-bi-quen-lang', 'Vùng Đất Bị Quên Lãng', 'In The Lost Lands', 'vùng đất bị quên lãng in the lost lands milla jovovich dave bautista arly jover amara okereke fraser james deirdre mullins sebastian stankiewicz tue lunding jacek dzisiewicz ian hanmore eveline hall kamila klamut caoilinn springall jan kowalewski pawel wysocki simon lööf tomasz 在失落之地 في الأراضي المفقودة tierras perdidas in the lost lands dans les contrées perdues 魔域女巫 a kárhozott vidék prarastose žemėse в потерянных землях čarodejnica a lovec', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-ngam-cuon-trao-12-tieng-kinh-hoang', 'Sóng Ngầm Cuộn Trào: 12 Tiếng Kinh Hoàng', 'Undercurrent: 12 Hours Of Terror', 'https://phimimg.com/upload/vod/20250415-1/fed0481a2f096bb587264abd3d9b32db.jpg', 'https://phimimg.com/upload/vod/20250415-1/4e52c3f600e8d5e9bb2d614e6d17e69e.jpg', '<p>Một câu chuyện nghẹt thở xoay quanh số tiền cá cược khổng lồ. Nhiều thế lực lao vào cuộc chiến kịch liệt và tàn khốc trong một khu biệt thự để tranh giành số tiền này. Những người trong biệt thự tận dụng các công cụ trong kho để giăng bẫy phản kích, mỗi khoảnh khắc đều như đang treo trên sợi chỉ mong manh giữa sự sống và cái chết. May mắn thay, công lý cuối cùng cũng xuyên qua màn đen tội ác. Trong tiếng còi xe cảnh sát vang vọng, cuộc tranh đấu nhuốm máu và lòng tham ấy đã đi đến hồi kết.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jurat","avatar":""},{"name":"段玮","avatar":""},{"name":"Zhang Huan","avatar":""},{"name":"陈文君","avatar":""},{"name":"盛木子易","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Undercurrent: 12 Hours of Terror","暗潮汹涌之惊魂12小时"]', 1784690324157);
