INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('song-ngam-cuon-trao-12-tieng-kinh-hoang', 'Sóng Ngầm Cuộn Trào: 12 Tiếng Kinh Hoàng', 'Undercurrent: 12 Hours Of Terror', 'sóng ngầm cuộn trào: 12 tiếng kinh hoàng undercurrent: 12 hours of terror jurat 段玮 zhang huan 陈文君 盛木子易 undercurrent: 12 hours of terror 暗潮汹涌之惊魂12小时', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luoi-dao-hiem-hoc', 'Lưỡi Dao Hiểm Hóc', 'Hyper Knife', 'https://phimimg.com/upload/vod/20250320-1/8232ddc7bd42ea8f8da28f7a72b71331.jpg', 'https://phimimg.com/upload/vod/20250320-1/9a21e966dee9e963ae1627f11b461796.jpg', '<p>Một thế giới y khoa đen tối, nơi lưỡi dao phẫu thuật không chỉ cắt qua da thịt mà còn xẻ sâu vào lòng kiêu hãnh, ân oán và những bí mật kinh hoàng. Choi Deok Hui được mệnh danh là bác sĩ phẫu thuật thần kinh giỏi nhất thế giới. Ông là người thầy từng dẫn dắt Jung Se Ok, một học trò xuất chúng với tiềm năng vô hạn. Tuy nhiên, mối quan hệ giữa họ không hề đơn giản. Trong một ca phẫu thuật định mệnh, Deok Hui đã đuổi Se Ok khỏi phòng mổ vĩnh viễn, đẩy cô vào bờ vực sự nghiệp. Jung Se Ok từng được coi là một thiên tài y khoa, nhưng sau biến cố với Deok Hui, cô bị tước bỏ giấy phép hành nghề và buộc phải trở thành &quot;bác sĩ bóng đêm&quot;, thực hiện những ca phẫu thuật bất hợp pháp trong bí mật. Dù bị xã hội ruồng bỏ, Se Ok vẫn không ngừng khao khát chứng minh năng lực của mình. Số phận run rủi đưa Se Ok và Deok Hui gặp lại nhau. Hai người, một kẻ từng là thầy, một người từng là trò, giờ đây đứng ở hai đầu chiến tuyến. Deok Hui, người từng đẩy Se Ok xuống vực sâu, giờ phải đối mặt với những hậu quả từ quyết định của mình. Còn Se Ok, với lòng tự trọng và sự kiêu hãnh, quyết tâm chứng minh rằng cô xứng đáng được công nhận.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Eun-bin","avatar":""},{"name":"Sul Kyung-gu","avatar":""},{"name":"Park Byung-eun","avatar":""},{"name":"Yoon Chan-young","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["狂医魔徒","Traición y redención","하이퍼 나이프","Haipeo Naipeu","جراحة ممنوعة","狂醫魔徒","Hyper Knife","하이퍼나이프"]', 1784690324157);
