INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-tuan-dac-canh-doi-dot-kich-chim-ruoi', 'Nữ Tuần Đặc Cảnh: Đội Đột Kích Chim Ruồi', 'Sisters In Arms', 'https://phimimg.com/upload/vod/20250402-1/72667f43d9b87b06767f0ebea35065b8.jpg', 'https://phimimg.com/upload/vod/20250402-1/2e4a0176707d7fd69a379dc0c4270be2.jpg', '<p>Bộ phim kể về câu chuyện của tiểu đội Chim Ruồi của đội cảnh sát đặc nhiệm thành phố Tân Giang, chuyên trấn áp tội phạm và bảo vệ sự bình yên cho nhân dân. Đội Chim Ruồi là tập hợp những cảnh sát anh tài với ý thức và khả năng thực thi pháp luật hiện đại, đầy lòng nhân ái và niềm tin vững chắc. Ở khu dân cư, đường phố, trong những cuộc truy bắt, trên tuyến đầu chấp pháp dù không có khói súng nhưng vẫn có sự hy sinh, khắp nơi đều có bóng dáng oai hùng luôn bận rộn của họ, là hiện thân của sự an toàn mà người dân có thể nhìn thấy được.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trình Tố","avatar":""},{"name":"Tưởng Lộ Hà","avatar":""},{"name":"Dương Hạnh","avatar":""},{"name":"Triệu Chí Dao","avatar":""},{"name":"Lý Vũ Đồng","avatar":""},{"name":"Nguỵ Nhất","avatar":""},{"name":"Từ Hùng Hạo","avatar":""},{"name":"Triệu Tuân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["冲锋车之恋","Nv Xun Te Jing Zhi Feng Niao Tu Ji Dui","Female Patrol Special Police Hummingbird Commando","Female Special Police","女巡特警之蜂鸟突击队"]', 1784690324157);
