INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cung-tuong-yem', 'Cung Tường Yếm', 'To Love Or To Defy', 'https://phimimg.com/upload/vod/20250331-1/783d51748559d4cfa9aa5bcfd75ff09f.jpg', 'https://phimimg.com/upload/vod/20250331-1/ffdd54436364b4c7e54e0d5cc86dfcc3.jpg', '<p>Sát thủ Địa Thập Thất cải trang thành công chúa hòa thân để vào cung hành thích, nhưng trong sự trớ trêu của số phận, cô lại gặp gỡ và đem lòng yêu ngũ hoàng tử Âu Dương Thiệu. Chủ nhân của cô đã lấy tính mạng gia đình cô ra để uy hiếp, ép buộc cô phải giết ngũ hoàng tử. Một bên là sứ mệnh khó trái, một bên là tình yêu không thể chối từ. Đứng giữa sự lựa chọn khó khăn, hai người quyết định cùng nhau vượt qua nghịch cảnh, chỉ để đổi lấy một khoảnh khắc được ở bên nhau.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hà Tuyên Lâm","avatar":""},{"name":"Trình Vũ Phong","avatar":""},{"name":"Vương Tinh Khải","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Gong Qiang Yan","궁성염 : 나를 사랑한 황자","宫墙厌"]', 1784690324157);
