INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cai-chet-cua-khun-phra', 'Cái Chết Của Khun Phra', 'The Death Of Khun Phra', 'https://phimimg.com/upload/vod/20250413-1/5f105852826c14abd0facfdacc732b29.jpg', 'https://phimimg.com/upload/vod/20250413-1/b4c69aa958b9050ddb997e5b76f8e410.jpg', '<p class="">Lấy bối cảnh Suwanthani thời kỳ đầu Rattanakosin, bộ phim kể về ba nô lệ — Sang Thong, Mai Phlong và Thong Bai — làm việc trong nhà Khun Phra Bamroekrung. Dù thân thiết như huynh đệ, cả ba lại cùng phải lòng Jolie, một nữ giáo sĩ ngoại quốc dạy tiếng Anh cho con cái trong nhà. Biến cố xảy ra khi chú rể bị bắn chết ngay trong lễ cưới của Khun Phra. Ba người bạn lập tức trở thành nghi phạm chính. Đứng trước hàng loạt bằng chứng buộc tội, họ buộc phải trốn chạy để truy tìm hung thủ thật sự và rửa sạch tội danh.</p><p><br/></p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Ponlawit Ketprapakorn","avatar":""},{"name":"Patchata Janngeon","avatar":""},{"name":"Daweerit Chullasapya","avatar":""},{"name":"Top Naphon Phromsuwan","avatar":""},{"name":"Napasorn Weerayuttwilai","avatar":""},{"name":"Pavadee Komchokpaisan","avatar":""},{"name":"Sukhapat Lohwacharin","avatar":""},{"name":"Thawatchanin Darayon","avatar":""},{"name":"Kamolpatch Thanwong","avatar":""},{"name":"Nawaporn Boonmee","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["สังข์ทอง ไม้พลอง ทองใบ กับการตายของคุณพระ"]', 1784690324157);
