INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giac-mong-ban-ngay-va-co-ay', 'Giấc Mộng Ban Ngày Và Cô Ấy', 'Wanna Be', 'https://phimimg.com/upload/vod/20250324-1/ed38d161bdca6b255c80d9e0b4226ba2.jpg', 'https://phimimg.com/upload/vod/20250324-1/032f4f5e1f482f25bb8f97a293b61691.jpg', '<p>Người làm công ở cửa hàng thủy sản Giả Phàm không có tiếng tăm gì, bởi vì một cơ hội ngoài ý muốn đứng trên sàn catwalk, còn tiến hành &quot;Phát biểu tử vong&quot; với siêu mẫu mới nổi Hàn Dĩ Kinh. Hàn Dĩ Kinh vốn tưởng rằng hai người sẽ không gặp lại, không nghĩ tới oan gia ngõ hẹp, Cổ Phàm lại trở thành &quot;đồng nghiệp&quot; của mình! Hai người mang theo ngạo mạn cùng thành kiến của mình, rồi lại chậm rãi tới gần như định mệnh. Băng cứng trong lòng Hàn Dĩ Kinh dần dần tan chảy, Cổ Phàm cũng phản kích trở thành ngôi sao người mẫu xứng đáng với vinh quang và hoan hô, nhưng lúc này, vận mệnh lại mở ra một trò đùa thật lớn với bọn họ.</p>', 'Hoàn Tất (29/29)', 29, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wang Zixuan","avatar":""},{"name":"Tang Xiaotian","avatar":""},{"name":"Jin Ze","avatar":""},{"name":"Feng Yunzhi","avatar":""},{"name":"Zhang Haoyue","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["如果是模特","如果不是你","Bai Ri Meng Yu Ta","Hello, Model","白日梦与她"]', 1784690324158);
