INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-den-tu-tuong-lai', 'Tôi Đến Từ Tương Lai', 'The Future Lover', 'https://phimimg.com/upload/vod/20250408-1/44b7cc458fe9037e100c6de99d2a6e39.jpg', 'https://phimimg.com/upload/vod/20250408-1/18ef66c56f3632e429dc94aebfeecf30.jpg', '<p>Châu Nam Phong dùng sổ nhật ký xuyên không về thời điểm trước khi Tần Tri Ý gặp biến cố hôn nhân, tìm cách ngăn cản Chung Tử Dạ trả thù Tần Tri Ý. Vì thời không xáo trộn giao thoa, Chung Tử Dạ cũng xuyên không theo, không ngừng tạo ra hiểu lầm chia rẽ Châu Nam Phong và Tần Tri Ý. Khi Chung Tử Dạ chết do tai nạn, Châu Nam Phong hy sinh để bảo vệ Tần Tri Ý, Tần Tri Ý mới biết được chân tướng xuyên không. Khi Tần Tri Ý dùng nhật ký để xuyên không lần nữa, cuối cùng cô phát hiện mọi chuyện năm xưa đều liên quan đến Tống Tinh Nguyệt, người mà Chung Tử Dạ yêu, bốn người rơi vào vòng lặp tử vong, nhân quả yêu hận đan xen quấn quýt trong thời không, chân tướng càng thêm mờ mịt giữa màn sương máu.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hồ Văn Huyên","avatar":""},{"name":"Châu Dạng","avatar":""},{"name":"Tống Chiêu Nghệ","avatar":""},{"name":"Hoàng Hoài Đình","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["我来自未来"]', 1784690324158);
