INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gap-go-nha-khumalo', 'Gặp Gỡ Nhà Khumalo', 'Meet The Khumalos', 'https://phimimg.com/upload/vod/20250412-1/6c5673f9e83f89e2d50082d222de2fd1.jpg', 'https://phimimg.com/upload/vod/20250412-1/eccd71dc679cf09059c28b06f6f2c484.jpg', '<p>Từng là bạn thân giờ trở mặt thành thù, hai bà mẹ sống cùng khu phố nọ khai màn cuộc chiến nhắm vào đối phương khi phát hiện hai đứa con của họ đang yêu nhau say đắm.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Khanyi Mbau","avatar":""},{"name":"Ayanda Borotho","avatar":""},{"name":"Jesse Suntele","avatar":""},{"name":"Khosi Ngema","avatar":""},{"name":"Connie Chiume","avatar":""},{"name":"Bonga Dlamini","avatar":""},{"name":"Siyabonga Melongisi Shibe","avatar":""},{"name":"Alizwa Sikhafungana","avatar":""},{"name":"Wanda Ndzambule","avatar":""},{"name":"Nandipa Khubone","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Meet the Khumalos"]', 1784690324158);
