INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('goc-khuat-2025', 'Góc Khuất', 'Speak For The Dead', 'https://phimimg.com/upload/vod/20250412-1/ffbaa4ba08a581a50111071fd2e0da3b.jpg', 'https://phimimg.com/upload/vod/20250412-1/b59259e2e3e4c56455ef2f05013f0939.jpg', '<p>Dưới bầu trời u ám của thành phố Lam Cảng, nữ cảnh sát hình sự An Dĩnh như người canh giữ nhịp đập đô thị, đối mặt trực diện với những góc khuất tăm tối của thành phố. Một vụ tai nạn giao thông ly kỳ, năm thi thể với lượng lớn ma túy giấu bên trong, đã đẩy vị tiến sĩ y khoa tài năng Lãnh Văn Vũ vào vòng xoáy của dư luận. Thế nhưng, trong quá trình điều tra, một vụ hỏa hoạn bất ngờ tại học viện y đã cướp đi mạng sống của Lãnh Văn Vũ, khiến mọi manh mối vụ án chấm dứt đột ngột. Em gái của anh – Lãnh Văn Kỳ – không chấp nhận kết luận rằng anh trai mình tự sát. Cô thề sẽ trở thành một pháp y để thay người đã khuất lên tiếng. Năm năm sau, An Dĩnh trải qua bao thử thách cuộc sống, trở thành một người mẹ đơn thân mạnh mẽ và đội trưởng xuất sắc của lực lượng cảnh sát. Lãnh Văn Kỳ cũng tốt nghiệp học viện y, hai người như được định mệnh sắp đặt mà gặp lại nhau tại hiện trường vụ án, cùng bắt tay điều tra loạt cái chết phi tự nhiên ẩn chứa nhiều uẩn khúc. Với sự giúp đỡ của phóng viên Tiêu Thần, bức màn bí ẩn quanh cái chết của Lãnh Văn Vũ dần được vén lên, từng lớp nghi ngờ bị bóc tách, hung thủ thực sự lộ diện. Lãnh Văn Kỳ hiến tặng công trình nghiên cứu của anh trai cho quốc gia, tiếp nối tâm nguyện cứu người của anh. An Dĩnh, Lãnh Văn Kỳ và Tiêu Thần, bằng lòng dũng cảm và trí tuệ, đã xua tan bóng tối, bảo vệ sự bình yên và tươi đẹp của thành phố này.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lü Xiaolin","avatar":""},{"name":"Wang Zhen","avatar":""},{"name":"Wang Fang","avatar":""},{"name":"Zhang Haoran","avatar":""},{"name":"Zhang Shulun","avatar":""},{"name":"Ma Dongyan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["消散的痕迹","Mang Dian","speak of the dead","盲点"]', 1784690324158);
