INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-vien-ky-lan', 'Học Viện Kỳ Lân (Phần 3)', 'Unicorn Academy (Season 3)', 'https://phimimg.com/upload/vod/20250412-1/4e62e1ea30f41eb0ec1e1ed501941fec.jpg', 'https://phimimg.com/upload/vod/20250412-1/6607e33bf8f5325d560eaa53667082bb.jpg', '<p>Khi thế lực hắc ám đe dọa phá hủy đảo Kỳ Lân, một thiếu nữ dũng cảm và năm người bạn cùng trường phải đứng lên bảo vệ học viện phép thuật mà họ trân quý.</p>', 'Tập 1', 9, 'hoathinh', 'ongoing', 8, 2025, 'Vietsub', 'FHD', 'Canada', 0, '[]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["独角兽骑士队","独角兽学院","Unicorn Academy"]', 1784690324158);
