INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-khong-dau', 'Anh Không Đau', 'Novocaine', 'https://phimimg.com/upload/vod/20250323-1/955daa2f6e0fd9e5ffec50fff70c134e.jpg', 'https://phimimg.com/upload/vod/20250323-1/d84e03a0c199d289afa36609c6cc6a7d.jpg', '<p>Một người đàn ông không thể cảm nhận nỗi đau thể xác đã biến căn bệnh hiếm gặp của mình thành lợi thế bất ngờ trong cuộc chiến sinh tử để giải cứu cô gái trong mơ.</p>', 'Full', 1, 'single', 'completed', 11, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Jack Quaid","avatar":""},{"name":"Amber Midthunder","avatar":""},{"name":"Ray Nicholson","avatar":""},{"name":"Jacob Batalon","avatar":""},{"name":"Betty Gabriel","avatar":""},{"name":"Matt Walsh","avatar":""},{"name":"Evan Hengst","avatar":""},{"name":"Conrad Kemp","avatar":""},{"name":"Jessica Stanley","avatar":""},{"name":"Dominique Maher","avatar":""},{"name":"Craig Jackson","avatar":""},{"name":"Lou Beatty Jr.","avatar":""},{"name":"Garth Collins","avatar":""},{"name":"Tristan de Beer","avatar":""},{"name":"Chioma Antoinette Umeala","avatar":""},{"name":"Margot Wood","avatar":""},{"name":"Dylan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mr. Novocaine","Novocaine No Pain","Novocaine: À Prova de Dor","نوفوكين","Novocaine","Novocaine: Sin dolor","Novokainë"]', 1784690324158);
