INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-mac-co-hiep', 'Đại Mạc Cô Hiệp', 'Desert Lone Hero', 'https://phimimg.com/upload/vod/20250411-1/e7a8f26b59883c8742cc63381090e701.jpg', 'https://phimimg.com/upload/vod/20250411-1/72b365cc260f96c4e1262815de8a9110.jpg', '<p>Vào triều Minh, phú thương giàu nhất thiên hạ Thẩm Thế Kiệt trước lúc lâm chung đã sử dụng kỳ môn độn giáp để xây dựng Thiên Cơ Bảo Khố phong ấn một khối tài sản khổng lồ. Không ngờ sau khi ông qua đời, kẻ gian dòm ngó, tấn công gia tộc và bắt cóc hậu nhân Thẩm Vũ Hinh. Đoàn Thập Nhất Lang vì cứu Thẩm Vũ Hinh và bảo vệ Thiên Cơ Bảo Khố đã triệu tập các hiệp khách giang hồ tiến vào hoang mạc Tây Vực, vượt muôn trùng hiểm nguy. Chính tà đối đầu, mở ra một cuộc chiến sinh tử đầy hào hùng với những màn đao kiếm rực lửa…</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Luo Liqun","avatar":""},{"name":"Gao Weiman","avatar":""},{"name":"Zhang Dong","avatar":""},{"name":"He Qiwei","avatar":""},{"name":"Liu Jingyi","avatar":""},{"name":"Kai Shen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["大漠孤侠"]', 1784690324158);
