INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dai-mac-co-hiep', 'Đại Mạc Cô Hiệp', 'Desert Lone Hero', 'đại mạc cô hiệp desert lone hero luo liqun gao weiman zhang dong he qiwei liu jingyi kai shen 大漠孤侠', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-anh-120', 'Yêu Anh 120%', 'Into You', 'https://phimimg.com/upload/vod/20250411-1/df6e66881070fbdeea079aebb6529afd.jpg', 'https://phimimg.com/upload/vod/20250411-1/be626698dc951e33b6a5846fc7a824c5.jpg', '<p>Phương Tinh Nhiên sinh ra ở một thị trấn nhỏ, từ nhỏ đã bộc lộ tài năng âm nhạc xuất chúng. Cô thường xuyên được mời tham gia biểu diễn trên các đài truyền hình quốc gia. Năm đó, thông qua một buổi biểu diễn, cô quen biết với Dịch Mộ Sanh – một người cũng tài hoa không kém. Họ có chung sở thích và lý tưởng, từ đó trở thành đôi bạn thân thiết, không chuyện gì không thể chia sẻ. Khi tuổi thiếu niên bắt đầu lớn, hai người dần nảy sinh tình cảm. Dù cách nhau hàng nghìn dặm, họ vẫn luôn đồng hành và ủng hộ nhau trên con đường theo đuổi ước mơ. Tuy nhiên, vì một âm mưu được sắp đặt, Dịch Mộ Sanh hiểu lầm rằng Phương Tinh Nhiên ham hư vinh và thay lòng đổi dạ. Trong cơn đau lòng, anh quyết định rời khỏi đất nước để tìm kiếm một sân khấu rộng lớn hơn. Cùng lúc đó, Phương Tinh Nhiên luôn ở trong nước tìm kiếm tung tích của Dịch Mộ Sanh, đau đớn tột cùng vì sự ra đi không lời từ biệt của anh. Cô biến nỗi đau thành động lực, nỗ lực học tập không ngừng và cuối cùng cũng thành công bước chân đến thành phố lớn. Sau khi tốt nghiệp đại học, cô cùng người bạn thân An Tĩnh và Kỷ Đông Đông sáng lập ra công ty truyền thông &quot;Hữu Ngư&quot;, trở thành một trong những streamer bán hàng nổi tiếng nhất cả nước. Đúng lúc Phương Tinh Nhiên dần buông bỏ nỗi nhớ Dịch Mộ Sanh...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Niu Xinxin","avatar":""},{"name":"Liu Han","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Yi Bai Er Shi Fen Xi Huan Ni","一百二十分喜欢你"]', 1784690324158);
