INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-menh-cua-cha', 'Sứ Mệnh Của Cha', 'The Dad Quest', 'https://phimimg.com/upload/vod/20250411-1/87c8f6642c15a92e912c73ceb723b53d.jpg', 'https://phimimg.com/upload/vod/20250411-1/4d2cdf2b549872126392613a3575c87d.jpg', '<p>Sau khi phát hiện ra rằng họ có thể không có quan hệ huyết thống, cha và con trai bắt đầu cuộc hành trình phiêu lưu khắp Mexico để tìm kiếm câu trả lời. Cuộc hành trình đã biến đổi họ và khiến họ đặt câu hỏi về bản sắc, mối liên hệ và ý nghĩa của gia đình.</p>', 'Full', 1, 'single', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Michel Brown","avatar":""},{"name":"Martino Leonardi","avatar":""},{"name":"Mayra Hermosillo","avatar":""},{"name":"Fernanda Castillo","avatar":""},{"name":"Julieta Egurrola","avatar":""},{"name":"Angélica Vale","avatar":""},{"name":"Erik Rubín","avatar":""},{"name":"Arath de la Torre","avatar":""},{"name":"Ricardo Fastlicht","avatar":""},{"name":"Eduardo Santamarina","avatar":""},{"name":"Ricardo O''Farrill","avatar":""},{"name":"Morena González","avatar":""},{"name":"Daniel Ábrego","avatar":""},{"name":"Ezequiel Cárdenas","avatar":""},{"name":"Angélic","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Lo mejor del mundo"]', 1784690324158);
