INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-oi-ta-la-ngong-khong-phai-thien-nga', 'Chàng Ơi Ta Là Ngỗng Không Phải Thiên Nga', 'Good Heavens I''m A Goose Not A Swan', 'https://phimimg.com/upload/vod/20250125-1/c9b9e4b7d9707def624b57f22cc99112.jpg', 'https://phimimg.com/upload/vod/20250125-1/6220dc853c26d22d10d1f3507ebc521a.jpg', '<p>Nithra vô tình xuyên không đến Bangkok những năm 1800, trong cơ thể của một kỹ nữ hàng đầu có liên quan đến vụ án mạng mà cô phải phá giải.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Nawasch Phupantachsee","avatar":""},{"name":"Maylada Susri","avatar":""},{"name":"Thatchathon Sabanun","avatar":""},{"name":"Rinlanee Sripen","avatar":""},{"name":"Tara Tipa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Khun Phi Jao Kha... Dichan Pen Han Mi Chai Hong","คุณพี่เจ้าขา...ดิฉันเป็นห่านมิใช่หงส์","คุณพี่เจ้าขาดิฉันเป็นห่านมิใช่หงส์"]', 1784690324158);
