INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chang-oi-ta-la-ngong-khong-phai-thien-nga', 'Chàng Ơi Ta Là Ngỗng Không Phải Thiên Nga', 'Good Heavens I''m A Goose Not A Swan', 'chàng ơi ta là ngỗng không phải thiên nga good heavens i''m a goose not a swan nawasch phupantachsee maylada susri thatchathon sabanun rinlanee sripen tara tipa khun phi jao kha... dichan pen han mi chai hong คุณพี่เจ้าขา...ดิฉันเป็นห่านมิใช่หงส์ คุณพี่เจ้าขาดิฉันเป็นห่านมิใช่หงส์', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-tiep-theo-chinh-la-co', 'Người Tiếp Theo Chính Là Cô', 'Atonement', 'https://phimimg.com/upload/vod/20250411-1/97e58e18b8273df18b62da2926a2575d.jpg', 'https://phimimg.com/upload/vod/20250411-1/5269d95d0d42252dcfa78c68dbfec735.jpg', '<p>Tần Tô Ngôn - một phụ nữ trẻ đang đứng trước ngã rẽ sự nghiệp - vô tình bước vào trò chơi sinh tử khi tham dự buổi họp lớp. Mọi thứ từ nhịp đếm ngược chết chóc, luật lệ tàn khốc đến những cái chết thật sự, đều được thiết kế để đẩy họ vào đường cùng, khoét sâu ác niệm rồi để chính nó nuốt chửng họ. Điều kinh hoàng nhất: người tạo ra trò chơi đang ẩn mình giữa các người chơi. Trong khi vật lộn giữa lằn ranh sinh tử, họ buộc phải đề phòng chính đồng đội. Giữa mê cung tăm tối ấy, Tần Tô Ngôn hiểu rõ: cách đánh bại bóng tối không phải là hòa làm một với nó, mà phải trở thành tia sáng le lói duy nhất. Khi mọi người tranh giành sự sống bằng móng vuốt và răng nanh, cô vẫn giữ vững lòng lương thiện. Song hành với cuộc chơi là cảm giác quen thuộc kỳ lạ. Khi trò chơi tiến triển và các người chơi lần lượt tử vong, sự thật kinh hoàng dần lộ diện: một vụ án ngầm từ hơn chục năm trước. Kẻ chủ mưu hiện nguyên hình, nhưng đúng lúc này, Tần Tô Ngôn lại do dự - liệu cô có nên vạch trần sự thật?</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Liu Yongxi","avatar":""},{"name":"Lan Bo","avatar":""},{"name":"Luan Yujia","avatar":""},{"name":"Lin Yi","avatar":""},{"name":"Zhu Zhu","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Xia Yi Ge Jiu Shi Ni","You Are The Next","下一个就是你"]', 1784690324158);
