INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bao-cat-2025', 'Bão Cát', 'Sandstorm', 'https://phimimg.com/upload/vod/20250328-1/9f3bca3992c26ebc2011f9fe20b9f088.jpg', 'https://phimimg.com/upload/vod/20250328-1/d1dabdce06b172e532c332b0dfe387bc.jpg', '<p>Một vụ án thiêu xác cũ bất ngờ được lật lại, và cảnh sát cấp cơ sở Trần Giang Hà cũng bị triệu tập khẩn cấp trở về. Khi anh một lần nữa bước vào thị trấn nhỏ, những kẻ lừa đảo gây rối, hung thủ dối trá và những người bị cuốn vào vòng xoáy báo thù như một cơn bão cát nhấn chìm anh. Nhưng anh tin rằng mọi tội ác đều có nguồn gốc, dù cơn bão có lớn đến đâu rồi cũng sẽ lặng, và công lý sẽ mang lại ánh sáng trong lành cho thế gian.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Duan Yihong","avatar":""},{"name":"Wang Qiang","avatar":""},{"name":"Karlina Zhang","avatar":""},{"name":"Zhang Yao","avatar":""},{"name":"Yang Xinming","avatar":""},{"name":"Huang Xiaolei","avatar":""},{"name":"Zheng Hao","avatar":""},{"name":"Zheng Chuyi","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["沙尘暴","Sandstorm"]', 1784690324158);
