INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bao-cat-2025', 'Bão Cát', 'Sandstorm', 'bão cát sandstorm duan yihong wang qiang karlina zhang zhang yao yang xinming huang xiaolei zheng hao zheng chuyi 沙尘暴 sandstorm', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('o-van-chi-thuong-ven-man-may-den', 'Ô Vân Chi Thượng : Vén Màn Mây Đen', 'Breaking The Shadows', 'https://phimimg.com/upload/vod/20250404-1/9e657922541569c5fbedb54fe35843ab.jpg', 'https://phimimg.com/upload/vod/20250404-1/4e40c9052669ec3d88ec15b5c28bc417.jpg', '<p>Hàn Thanh là nữ cảnh sát thuộc đội điều tra hình sự Tam Hợp. Vì nghiêm túc, ít nói và chỉ tập trung vào công việc, cô được gắn biệt danh “Không Vui”. Cô đã hợp tác ăn ý với đồng nghiệp Chung Vĩ nhiều năm, nhưng Chung Vĩ lại mất tích sau khi theo dõi một nghi phạm và không có tin tức suốt gần hai tháng. Trong khi lo lắng và đau khổ, Hàn Thanh vẫn xử lý các vụ án khác, không từ bỏ bất kỳ manh mối nào liên quan đến Chung Vĩ. Một vụ án mạng mới khiến Hàn Thanh cảnh giác cao độ. Qua các chi tiết nhỏ, cô phán đoán vụ án mạng này có liên quan đến sự mất tích của Chung Vĩ. Dù gặp nhiều trở ngại trong quá trình điều tra, kẻ phạm tội thực sự cuối cùng đã lộ diện và những gì mà Chung Vĩ đã trải qua cũng dần trở nên rõ ràng. Cảnh sát lần theo các manh mối, phát hiện mối liên hệ giữa ba vụ án lớn: mất tích, giết người và buôn ma túy, từ đó lần ra mạng lưới tổ chức tội phạm phức tạp và những bí mật ẩn giấu đằng sau nó. Đội điều tra Tam Hợp hợp lực, phá án thành công, toàn bộ tội phạm đều bị bắt giữ.</p>', 'Hoàn Tất (17/17)', 17, 'series', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Sun Li","avatar":""},{"name":"Luo Jin","avatar":""},{"name":"Ding Guansen","avatar":""},{"name":"Li Xiaoran","avatar":""},{"name":"Wang Ziyi","avatar":""},{"name":"Huang Man","avatar":""},{"name":"Yiying Liu","avatar":""},{"name":"Kaavie Wong","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["乌云之上"]', 1784690324158);
