INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-chim-nhan-tro-ve', 'Khi Chim Nhạn Trở Về', 'The Glory', 'https://phimimg.com/upload/vod/20250318-1/624427d369d006789b4030eadf9d1343.jpg', 'https://phimimg.com/upload/vod/20250318-1/f8faa7f0d3121dd325483b44ea7c96e3.jpg', '<p>Từ nhỏ, Trang Hàn Nhạn bị bỏ rơi ở nơi miền quê phương Nam. Trải qua muôn vàn khó khăn, cô trở về nhà họ Trang ở kinh thành và và lọt vào mắt xanh của Phó Vân Tịch, Phó Thiếu khanh Đại Lý Tự. Phó Vân Tịch mắc một chứng bệnh kỳ lạ, muốn cưới một thê tử tài đức vẹn toàn để có thể chăm sóc cho mình. Với sự gan dạ và tấm lòng lương thiện, Trang Hàn Nhạn trở thành lựa chọn lý tưởng nhất. Trong quá trình thăm dò và thử thách lẫn nhau, cả hai dần nảy sinh tình cảm. Hàn Nhạn không chỉ hóa giải khúc mắc với mẹ, tìm lại tình thân đã đánh mất mà còn cảm nhận được tình cảm ấm áp của gia đình khi sống chung với người nhà họ Phó. Cô và Phó Vân Tịch liên thủ vạch trần bộ mặt giả nhân giả nghĩa của Trang Sĩ Dương – gia chủ nhà họ Trang, kẻ lộng quyền làm trái pháp luật và trở thành đôi phu thê hạnh phúc.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Đô Linh","avatar":""},{"name":"Tân Vân Lai","avatar":""},{"name":"Hà Hoằng San","avatar":""},{"name":"Dụ Ân Thái","avatar":""},{"name":"Ôn Tranh Vanh","avatar":""},{"name":"Vương Diễm","avatar":""},{"name":"Lưu Húc Uy","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["A glória de uma nobre","贵女","雁回时丨贵女","안회시 : 귀녀","สตรีเช่นข้าหาได้ยากยิ่ง","The Glory","雁回时"]', 1784690324158);
