INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huong-vi-cuoc-doi', 'Hương Vị Cuộc Đời', 'Another Wok Of Life', 'https://phimimg.com/upload/vod/20250409-1/b40d2620f312a3e706ec80f8b522316b.jpg', 'https://phimimg.com/upload/vod/20250409-1/0efd8e9f691a3fb4d54da74c3b289736.jpg', '<p>Một kẻ sát nhân tên Nhan Chấn Bang, cùng với vài cựu tù nhân khác – trong đó có Lý Tự Thành, con trai chủ một quán lẩu, người luôn coi họ là cái gai trong mắt – đã cùng nhau biến một quán lẩu tưởng chừng không còn hy vọng trở thành một chốn dừng chân ấm áp tình người. Họ không chỉ mang đến hương vị làm say lòng thực khách, mà còn chữa lành chính bản thân mình, từ đó tìm thấy ý nghĩa cuộc sống…</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Singapore', 0, '[{"name":"Richie Koh","avatar":""},{"name":"Shane Pow","avatar":""},{"name":"Jeremy Chan","avatar":""},{"name":"James Seah","avatar":""},{"name":"Guo Liang","avatar":""},{"name":"Jasmine Sim","avatar":""},{"name":"Bonnie Loo","avatar":""},{"name":"Fang Rong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["人生酱美味"]', 1784690324158);
