INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-trai-say-hi-ke-phan-dien-tao-nen-nguoi-hung', 'Anh Trai Say Hi: Kẻ Phản Diện Tạo Nên Người Hùng', 'Brother Says Hi: The Villain Who Created The Hero', 'https://phimimg.com/upload/vod/20250409-1/a8c0b698e3983ab2f5b54a1b5108421e.jpg', 'https://phimimg.com/upload/vod/20250409-1/921949c2fda08ec327e093aae8990b54.jpg', '<p>Anh trai ‘say hi’”, hơn cả một chương trình âm nhạc thực tế sống còn 100% thuần Việt, được sáng tạo bởi trí tuệ Việt Nam, đáp ứng khao khát “đu idol quốc nội” của người trẻ Việt và được yêu thương, ủng hộ bởi người hâm mộ văn hoá bản địa. “Anh trai ‘say hi’” là người hùng trong công cuộc thay đổi nền công nghiệp giải trí Việt Nam, và người hùng “Anh trai ‘say hi’” đã chiến đấu với những “kẻ phản diện” của chính mình để viết nên lịch sử. “Kẻ phản diện” mang tên hoài nghi, lo sợ trước cam kết “100% mới”: format hoàn toàn mới, âm nhạc hoàn toàn mới, diện mạo thần tượng hoàn toàn mới; “kẻ phản diện” mang tên “định kiến thần tượng quốc nội” luôn thua kém những tên tuổi quốc tế. Chưa bao giờ trong lịch sử concert âm nhạc Việt Nam được chứng kiến chuỗi đêm diễn tại các thành phố lớn đạt kỷ lục “cháy” hơn 178,000 vé mà không cần bất cứ “idol” quốc tế nào tham gia. “Kẻ phản diện” thậm chí ẩn náu trong mỗi anh trai, họ không thấy mặt, không gọi được tên và tất nhiên không thể vượt qua nếu không cùng “Anh trai ‘say hi’” trải qua hành trình lịch sử. KHÔNG CÓ NGƯỜI HÙNG VĨ ĐẠI NẾU THIẾU KẺ PHẢN DIỆN ĐÁNG GỜM. &quot;Anh trai &#39;say hi&#39;” đã thay đổi nền văn hoá thần tượng Việt Nam mãi mãi.</p>', 'Full', 1, 'single', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"HIEUTHUHAI","avatar":""},{"name":"Isaac","avatar":""},{"name":"Đức Phúc","avatar":""},{"name":"Erik","avatar":""},{"name":"Quang Hùng MasterD","avatar":""},{"name":"Wean Lê","avatar":""},{"name":"Công Dương","avatar":""},{"name":"Anh Tú","avatar":""},{"name":"Anh Tú","avatar":""},{"name":"Lou Hoàng","avatar":""},{"name":"Quang Trung","avatar":""},{"name":"Jsol","avatar":""},{"name":"Đỗ Phú Quí","avatar":""},{"name":"Song Luân","avatar":""},{"name":"Gin Tuấn Kiệt","avatar":""},{"name":"Quân A.P","avatar":""},{"name":"Hùng Huỳnh","avatar":""},{"name":"Nicky","avatar":""},{"name":"Tage","avatar":""},{"name":"Hải Đăng Doo","avatar":""},{"name":"Dương Domic","avatar":""},{"name":"Pháp Kiều","avatar":""},{"name":"Ali Hoàng Dương","avatar":""},{"name":"Negav","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["ANH TRAI SAY HI","Anh Trai \"Say Hi\""]', 1784690324158);
