INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-hiem-nguy', 'Thế Giới Hiểm Nguy', 'The World Will Tremble', 'https://phimimg.com/upload/vod/20250409-1/96dfe6e4718afba2e14be08c4dd0ff33.jpg', 'https://phimimg.com/upload/vod/20250409-1/a58fe771f166cf1551889b55bf7294b2.jpg', '<p>Bộ phim dựa trên câu chuyện có thật đầy kinh ngạc về một nhóm tù nhân trong Thế chiến thứ hai, những người đã thực hiện một cuộc trốn thoát tưởng chừng bất khả thi khỏi trại hủy diệt Chełmno - trại tử thần đầu tiên của Đức Quốc xã - nhằm cung cấp bằng chứng trực tiếp đầu tiên về Holocaust (Cuộc diệt chủng Do Thái).phim xoay quanh Solomon Wiener (Oliver Jackson-Cohen) và Michael Podchlebnik (Jeremy Neumark Jones), hai tù nhân tại trại Chełmno, nơi hàng ngàn người, chủ yếu là người Do Thái, bị sát hại dã man bằng cách ngạt khí trong các xe tải. Họ chứng kiến những cảnh tượng kinh hoàng: những con người bị giết chết bằng khí độc, tiếng hét của các nạn nhân khi họ ngạt thở, và những thi thể bị chôn vùi trong các hố chôn tập thể. Trước thực tại rằng cái chết là không thể tránh khỏi nếu ở lại, nhóm tù nhân, bao gồm cả Solomon và Michael, quyết định lên kế hoạch trốn thoát để cảnh báo thế giới về những gì đang xảy ra.</p>', 'Full', 1, 'single', 'completed', 13, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Oliver Jackson-Cohen","avatar":""},{"name":"Jeremy Neumark Jones","avatar":""},{"name":"David Kross","avatar":""},{"name":"Michael Epp","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["O Mundo Vai Tremer","The World Will Tremble"]', 1784690324158);
