INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('niem-vo-song-2025', 'Niệm Vô Song', 'A Moment But Forever', 'https://phimimg.com/upload/vod/20250327-1/319a32138a3285be0d4da05cac7da1a2.jpg', 'https://phimimg.com/upload/vod/20250327-1/507ec05662a0f9cf73be43b423a2b34d.jpg', '<p>Niệm Vô Song là câu chuyện tình cảm động lòng người giữa thánh nữ Vô Song và Tộc trưởng Hồ tộc Nguyên Trọng. Sau khi thánh vật Thần Thủ của thần giới rơi xuống nhân gian thì rơi vào tay Nguyên Trọng của Hồ tộc. Nhờ có nó, chàng đánh bại kẻ thù, mở ra thời kì vẻ vang cho Hồ tộc. Để lấy lại Thần Thủ, thần giới cử thánh nữ Vô Song xuống trần, trà trộn vào Hồ tộc để tiếp cận Nguyên Trọng. Trong quá trình này, Vô Song phát hiện ra nhiều bí ẩn liên quan đến Thần Thủ và đồng thời cũng rơi vào lưới tình với Nguyên Trọng.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 6, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Đường Yên","avatar":""},{"name":"Lưu Học Nghĩa","avatar":""},{"name":"Quách Hiểu Đình","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["天下无双","Nian Wu Shuang","念无双","ขณะหนึ่งชั่วนิจนิรันดร์","A Moment But Forever"]', 1784690324158);
