INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('niem-vo-song-2025', 'Niệm Vô Song', 'A Moment But Forever', 'niệm vô song a moment but forever đường yên lưu học nghĩa quách hiểu đình 天下无双 nian wu shuang 念无双 ขณะหนึ่งชั่วนิจนิรันดร์ a moment but forever', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ky-uc-ky-la', 'Ký Ức Kỳ Lạ', 'Strange Memories', 'https://phimimg.com/upload/vod/20250408-1/42e170b218c9c8844f5a8eccaa765e28.jpg', 'https://phimimg.com/upload/vod/20250408-1/9701c285600c9b86040cc3cdbace5a1b.jpg', '<p>Ẩn tu sĩ Ưu Văn Hóa và yêu cơ Diệp Thiên Mạch đã trải qua nhiều kiếp gặp gỡ rồi lại quên nhau. Lần này, họ lại tình cờ tái ngộ vào thế kỷ 21. Nhưng Diệp Thiên Mạch đã bị Thiên tôn lợi dụng, hóa thân thành ba hình tượng khác nhau, một chị đại quyến rũ, một người phụ nữ trưởng thành, và một mỹ nhân lạnh lùng để tiếp cận Ưu Văn Hóa, nhằm chiếm đoạt tinh nguyên của anh. Đối mặt với cuộc truy sát của người yêu qua nhiều kiếp, sự phục hồi ký ức, đại kiếp nạn của giới ẩn tu và cả lôi kiếp trăm năm của bản thân, trong tình thế rối ren chồng chất, Ưu Văn Hóa phải làm thế nào để xoay chuyển cục diện, giữ vững tình yêu của mình và lật ngược ván cờ?</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wu Di","avatar":""},{"name":"Ren Zihao","avatar":""},{"name":"Qin Xiao","avatar":""},{"name":"Zhang Zhang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["奇怪的记忆"]', 1784690324158);
