INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gio-xuan-cham-lua-tinh', 'Gió Xuân Châm Lửa Tình', 'Spring Burning', 'https://phimimg.com/upload/vod/20250323-1/e241da9992aed1134135bfafe4f0642f.jpg', 'https://phimimg.com/upload/vod/20250323-1/07ba687cec8fc5029af017a93f378c97.jpg', '<p>Vào những năm 80, Lục Nhiên, một nữ sinh viên thông minh và cứng đầu bị chú thím độc ác ép gả cho một tên lùn nghèo xấu, có con gái, lại còn là một kẻ bạo lực gia đình với sính lễ đắt đỏ! Với suy nghĩ số phận không phải do ông trời quyết định, Lục Nhiên không hề do dự bỏ trốn, không ngờ trên đường bỏ trốn cô lại vô tình gặp được một người đàn ông dịu dàng, cao lớn, đẹp trai và ngây thơ. Anh ta lại còn là người cô đang trốn kết hôn?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"La Chính","avatar":""},{"name":"Trần Phương Đồng","avatar":""},{"name":"Vương Yên Dương","avatar":""},{"name":"Chương Già Duyệt","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["춘풍연정: 첫사랑 성공기","春风燃情"]', 1784690324158);
