INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('my-vi-tran-yeu-ky', 'Mỹ Vị Trấn Yêu Ký', 'Monster Chef', 'https://phimimg.com/upload/vod/20250408-1/8309b0674f3faf644bdf44cd42dee1b6.jpg', 'https://phimimg.com/upload/vod/20250408-1/aed2dd964c3a99f06a5b95d107859a71.jpg', '<p>Cô nàng dân văn phòng Thị Tử bất ngờ xuyên không vào trò chơi do chính mình thiết kế và trở thành ngự yêu sư kiêm đầu bếp. Muốn quay lại thế giới thực, cô phải thu phục yêu quái bằng cách nấu những món ăn chữa lành và hoàn thành yêu đồ. Trên hành trình, cô kết bạn với một thiếu niên bí ẩn, cùng nhau thu phục các yêu linh và dần khám phá ra thân phận thật sự của thiếu niên – thái tử bị hãm hại. Sau trận chiến lật đổ thái tử giả, Thị Tử hoàn thành nhiệm vụ và trở lại hiện tại. Dù được khen ngợi vì ý tưởng mới, cô lại cảm thấy trống vắng vì đã lỡ yêu người trong thế giới ảo. Nhưng bất ngờ thay, chàng trai ấy đã xuyên không đến thế giới thực, trở thành thực tập sinh mới của cô...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Từ Nghệ Dương","avatar":""},{"name":"Tôn Trạch Nguyên","avatar":""},{"name":"Hoàng Đình Đình","avatar":""},{"name":"Hoàng Ân Dự","avatar":""},{"name":"Chu Vân Long","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Yu Yao Chu Niang","The Demon Cook","御妖厨娘"]', 1784690324158);
