INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('alexander-va-chuyen-di-toi-te-kinh-khung-chan-nan-buc-boi', 'Alexander Và Chuyến Đi Tồi Tệ, Kinh Khủng, Chán Nản, Bực Bội', 'Alexander and the Terrible, Horrible, No Good, Very Bad Road Trip', 'https://phimimg.com/upload/vod/20250408-1/902e13859eb013c21cd196d229b24f64.jpg', 'https://phimimg.com/upload/vod/20250408-1/7b2bbed8c3d353cddc3ada9460341762.jpg', '<p>Alexander, cậu bé 11 tuổi, cùng gia đình háo hức bắt đầu kỳ nghỉ xuân mơ ước tại thành phố Mexico náo nhiệt. Thế nhưng, chuyến đi trong mơ nhanh chóng biến thành cơn ác mộng khi cả nhà vô tình chạm vào một bức tượng cổ bị nguyền rủa, kéo theo hàng loạt sự cố dở khóc dở cười không hồi kết.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Thom Nemer","avatar":""},{"name":"Eva Longoria","avatar":""},{"name":"Cheech Marin","avatar":""},{"name":"Jesse Garcia","avatar":""},{"name":"Paulina Chávez","avatar":""},{"name":"Rose Portillo","avatar":""},{"name":"Tiffany Vi","avatar":""},{"name":"Alexander Alayon Jr.","avatar":""},{"name":"Michelle Buteau","avatar":""},{"name":"Carl Savering","avatar":""},{"name":"Angela L. Wilson","avatar":""},{"name":"Harvey Guillén","avatar":""},{"name":"Mabel Cadena","avatar":""},{"name":"Cristo Fernández","avatar":""},{"name":"Jacqueline Torres","avatar":""},{"name":"Alicia Lueras Maldo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Alexander and the Terrible, Horrible, No Good, Very Bad Road Trip","Alexander 2"]', 1784690324158);
