INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-cung-dao', 'Nam Cung Dao', 'Touch Of The Frozen Heart', 'https://phimimg.com/upload/vod/20250404-1/2122843a32da923bb06cf7b0d000c792.jpg', 'https://phimimg.com/upload/vod/20250404-1/1f774d92deb6eb1da45dcdc782202b54.jpg', '<p>Nam Cung Doanh là công chúa của đất nước đã diệt vong, vì muốn báo thù cho đất nước mình, nàng đã tự tay đâm thái tử Tô Vô Dạng – người yêu nàng sâu đậm bị thương. Tô Vô Dạng từng nghĩ rằng trái tim mình đã chết từ khoảnh khắc bị Nam Cung Doanh hạ độc. Thế nhưng, năm năm sau, khi hắn nhìn thấy Nam Cung Doanh và tiểu tướng quân Bùi Hiển ân ái hòa hợp, trái tim đã chết của hắn lại đau đớn, ghen tuông điên cuồng.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Minh Gia Gia","avatar":""},{"name":"Kim Bằng Bác","avatar":""},{"name":"Lam Bác","avatar":""},{"name":"Từ Ngọc Hàn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Nan Gong Yao","南宫瑶","Yin''s Rumor","Story of Nangong","南宫谣"]', 1784690324158);
