INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dot-lua-tinh', 'Đốt Lửa Tình', 'Burning Passion', 'https://phimimg.com/upload/vod/20250328-1/40bd13364df5d30f4dbcdaa2fd56eef6.jpg', 'https://phimimg.com/upload/vod/20250328-1/2048db2a55639ff73e64be2967a99fce.jpg', '<p>Nhiều năm trước, mẹ của Thẩm Thanh Như bị trừng phạt dìm xuống hồ vì ngoại tình, còn cô thì mang danh &quot;con gái của kẻ lẳng lơ&quot;, lớn lên trong sự nhục mạ và khinh thường của dân làng, mang theo mối hận của người mẹ đã khuất. Cho đến khi &quot;gã câm&quot; Thẩm Sính xuất hiện, hai người trở thành sự cứu rỗi duy nhất và là giới hạn của nhau. Ranh giới &quot;chị em&quot; mong manh ngăn cách giữa họ. Trước bao ánh mắt dòm ngó, Thẩm Thanh Như rưng rưng nước mắt và thề rằng sẽ không rung động. Bố ruột ép cô gả cho nhà họ Mạc để &quot;xung hỉ&quot;, nhưng cậu chủ mắc bệnh lao của nhà họ Mạc lại qua đời ngay trước đêm tân hôn. Bà Mạc tức giận ép Thẩm Thanh Như tuẫn táng theo con trai.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Cửu Lâm","avatar":""},{"name":"Chu Cận Đồng","avatar":""},{"name":"Lưu Diệu Dương","avatar":""},{"name":"Ngô Phi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ran Qing","燃情"]', 1784690324158);
