INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-tuong-quan-co-mot-nang-dau-bep-thien-kim-gap-nan', 'Phủ Tướng Quân Có Một Nàng Đầu Bếp: Thiên Kim Gặp Nạn', 'Culinary Vendetta', 'https://phimimg.com/upload/vod/20250309-1/fbdcaf3b705b22a5009e54b8b4417070.jpg', 'https://phimimg.com/upload/vod/20250309-1/7a6bdffef0b6fb0f71b8559392108919.jpg', '<p>Quận chúa Minh Châu vì muốn gả vào phủ đại tướng quân nên đã bày mưu hãm hại cả nhà Tô Thiển Thiển. Tô Thiển Thiển bắt đầu vùng lên phản kích. Minh Châu và Tô Thiển Thiển lần lượt gả vào phủ tướng quân, đấu trí đấu sức gay gắt trong nội trạch. Cuối cùng, Tô Thiển Thiển cùng tướng quân trẻ tuổi Sở Quân Dao hoàn thành công cuộc báo thù, đồng thời chinh phục tất cả mọi người bằng tài nấu nướng hết sảy của mình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Phương Đồng","avatar":""},{"name":"Nghiêm Tử Hiền","avatar":""},{"name":"Thi Nam","avatar":""},{"name":"Nhiếp Tân Nguyên","avatar":""},{"name":"Diêm Cần","avatar":""},{"name":"Mã Đinh","avatar":""},{"name":"Tiền Tư Di","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Jiang Jun Fu Lai Le Ge Xiao Chu Niang Zhi Luo Nan Qian Jin","The Little Wife of the General 2","将军府来了个小厨娘2","小厨娘2","军府来了个小厨娘之落难千金","将军府来了个小厨娘之落难千金"]', 1784690324158);
