INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phu-tuong-quan-co-mot-nang-dau-bep-thien-kim-gap-nan', 'Phủ Tướng Quân Có Một Nàng Đầu Bếp: Thiên Kim Gặp Nạn', 'Culinary Vendetta', 'phủ tướng quân có một nàng đầu bếp: thiên kim gặp nạn culinary vendetta trần phương đồng nghiêm tử hiền thi nam nhiếp tân nguyên diêm cần mã đinh tiền tư di jiang jun fu lai le ge xiao chu niang zhi luo nan qian jin the little wife of the general 2 将军府来了个小厨娘2 小厨娘2 军府来了个小厨娘之落难千金 将军府来了个小厨娘之落难千金', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chim-se-trong-long-ban-tay', 'Chim Sẻ Trong Lòng Bàn Tay', 'Sadistic Love', 'https://phimimg.com/upload/vod/20250314-1/62987ec1492f056c36be0cef0ffdb41e.jpg', 'https://phimimg.com/upload/vod/20250314-1/9e4038407dd893c1ea9afd30f8e06880.jpg', '<p>Hách Liên Tranh yêu em gái kế Hà An Nhiên sâu sắc, nhưng lại tận mắt chứng kiến cha cô giam cầm mẹ mình đến chết. Năm năm sau, Hách Liên Tranh trở về với thân phận đốc quân, anh bắt giữ cha dượng và ép cưới em gái kế để báo thù cho mẹ. Mạch Vũ Đường từ nhỏ sống nương tựa vào Hách Liên Tranh, nhưng lại vì anh mà bị què một chân. Sau nhiều năm gặp lại, đằng sau lớp hóa trang đẹp đẽ của Mạch Vũ Đường lại ẩn chứa sự hận thù thấu xương...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đại Cao Chính","avatar":""},{"name":"Quản Nhạc","avatar":""},{"name":"Hồ Diệc Dao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["袖中蝶","掌中雀"]', 1784690324158);
