INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-trai-noi-tro-cua-toi', 'Bạn Trai Nội Trợ Của Tôi', 'My Boyfriend', 'https://phimimg.com/upload/vod/20250323-1/56c58ea00c80349e9b89ab55cf788b84.jpg', 'https://phimimg.com/upload/vod/20250323-1/112d5e214caa9b0f2bd1e1784bfc64dd.jpg', '<p>Nữ tổng tài bá đạo Dịch Ninh buộc phải kết hôn mới được thừa kế cơ ngơi, vì thế cô đã tìm đến chàng đầu bếp đẹp trai đảm đang Thẩm Khiên Trạch để thực hiện hôn nhân hợp đồng. Cuộc sống “vợ kiếm tiền, chồng chăm lo gia đình” khiến Dịch Ninh dần nảy sinh tình cảm. Không ngờ Thẩm Khiên Trạch lại giấu một bí mật động trời. Anh cố ý tiếp cận với mục đích riêng, cô cũng cam tâm chìm đắm trong vô thức.</p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Thánh Hanh","avatar":""},{"name":"Cao Dục Phi","avatar":""},{"name":"Lục Lộ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wo De Zhu Fu Nan You","아적주부남우 : 내 남친은 하우스와이프","My House Husband Boyfriend","我的主夫男友"]', 1784690324158);
