INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('kinnikuman-hoan-my-thuy-to-phan-2', 'Kinnikuman: Hoàn Mỹ Thủy Tổ (Phần 2)', 'Kinnikuman Perfect Origin Arc (Season 2)', 'kinnikuman: hoàn mỹ thủy tổ (phần 2) kinnikuman perfect origin arc (season 2) mamoru miyano akira kamiya kendo kobayashi daisuke ono katsuyuki konishi sumire uesaka tomokazu seki jun kasama kensho ono yuki kaji hiroki yasumoto yuichi nakamura akio otsuka hiroyuki yoshino toshiya miyata yasuhiro mamiya wataru komada 金肉人 完美超人始祖篇 筋肉人：完美超人始祖篇 kinnikuman kanpeki chо̄jin shiso-hen kinnikuman perfect origin-hen kinnikuman kanpeki choujin shisohen 근육맨 완벽초인시조편 muscleman (2024) キン肉マン 完璧超人始祖編', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-la-trieu-xuat-tuc', 'Tôi Là Triệu Xuất Tức', 'My Name is Zhao Chuxi', 'https://phimimg.com/upload/vod/20250314-1/eed3f18da60315f9f636b83f2f4b252f.jpg', 'https://phimimg.com/upload/vod/20250314-1/3c828e6e1b62f8fe4a9ab14c9fd10141.jpg', '<p>Triệu Xuất Tức, một cô nhi, được sinh ra tại Vạn Cảnh Sơn và lớn lên dưới sự chăm sóc, nuôi dưỡng của Lý Thành Càn. Cái chết của Tiểu Bình An và Lý Thành Càn khiến Triệu Xuất Tức bị sốc. Anh quyết định kế thừa di nguyện của vị hiệu trưởng già Lý Thành Càn, rời khỏi ngôi làng để đến Gia Thị làm việc kiếm tiền nhằm cải thiện điều kiện sống của dân làng, đồng thời cũng không muốn mất đi những người thân yêu chỉ vì giao thông không thuận tiện. Vừa đặt chân đến Gia Thị, Triệu Xuất Tức vẫn giữ vững bản tính giữa thế giới đầy cám dỗ vật chất, hết lòng giúp đỡ người khác. Chính điều này này đã mang lại cảm giác an toàn cho cô chủ Tô Tây Lạc, nảy sinh tình cảm với anh nhưng điều đó cũng khiến anh trở thành đối tượng bị Từ Thiếu Khanh thù hận và trả thù. Dưới sự giúp đỡ và hy sinh của bạn bè, Triệu Xuất Tức trốn thoát khỏi Gia Thị và đến Tam Giang. Nhưng mọi nỗ lực trong hai năm của anh đều tan thành mây khói. Tuy nhiên, chính cơ hội này đã giúp Triệu Xuất Tức trưởng thành hoàn toàn. Trải qua nhiều thử thách, cuối cùng anh trở thành Chủ tịch của Tập đoàn Tam Giang, quay trở lại Gia Thị để đòi lại công bằng cho Lý Thành Càn. Sau khi thành công, Triệu Xuất Tức trở về thôn Phượng Hoàng, thực hiện lý tư ban đầu của mình và hoàn thành tâm nguyện bao năm qua của Lý Thành Càn.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Bính Nhuệ","avatar":""},{"name":"Trương Hinh Dư","avatar":""},{"name":"Lộ Hoành","avatar":""},{"name":"Sử Nguyên Đình","avatar":""},{"name":"Phụng Lị","avatar":""},{"name":"Sư Tiểu Hồng","avatar":""},{"name":"Trương Xuân Trọng","avatar":""},{"name":"Lưu Ba","avatar":""},{"name":"Hàn Vũ Đồng","avatar":""},{"name":"Trương San Manh","avatar":""},{"name":"Vương Tử Duệ","avatar":""},{"name":"Quảng Hiểu Đồng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wo Jiao Zhao Chu Xi","我叫赵出息"]', 1784690324158);
