INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-anh-ngan-chong-gai', 'Yêu Anh Ngàn Chông Gai', 'Love''s Ultimate Test', 'https://phimimg.com/upload/vod/20250402-1/ac2a5b107d9c1dbe5dc19042eb8c998a.jpg', 'https://phimimg.com/upload/vod/20250402-1/163247233a6cb6022523de07417be32e.jpg', '<p>Yên Đan chuyên nhận test-người-yêu với kết quả siêu chuẩn. Lần này cô đã nhận hợp đồng tiền tỉ để test “độ đàn ông” của chàng trai Henry đúng chuẩn tổng tài mà không ngờ mình sẽ dần sa vào lưới tình.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Kiều Diễm","avatar":""},{"name":"Hà Phương","avatar":""},{"name":"Phi Thanh Vân","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Big Brother''s Bit on the Psych"]', 1784690324158);
