INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-ve-tranh', 'Vua Vẽ Tranh', 'King Of Painting', 'https://phimimg.com/upload/vod/20250405-1/533d9b001b5824fa1584600abe8dbdf9.jpg', 'https://phimimg.com/upload/vod/20250405-1/9464a46ebdcc4342a4e3335f0ab03be1.jpg', '<p>Nhân vật chính Kha Hoán (do Lý Khắc Long thủ vai) là một họa sĩ tài năng, đầy đam mê, nhưng trong thời đại mà mọi thứ đều bị thương mại hóa và chiêu trò, một người chỉ biết cắm cúi vẽ tranh như anh lại trở thành trò cười tại làng họa sĩ Đường Trang. Khi rơi xuống đáy vực của cuộc đời, không đủ tiền thuê nhà, bị đồng nghiệp khinh thường, bạn gái bị đối thủ cướp mất, Kha Hoán ngỡ như không còn lối thoát. Nhưng đúng lúc tuyệt vọng nhất, một vị khách đến từ ngoài hành tinh đã thay đổi số phận của anh…!</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Kelong","avatar":""},{"name":"He Huan","avatar":""},{"name":"Pari","avatar":""},{"name":"Zhu Rong Jun","avatar":""},{"name":"Xu Juncong","avatar":""},{"name":"Du Yuan","avatar":""},{"name":"Han Yunyun","avatar":""},{"name":"Han Yanbo","avatar":""},{"name":"Shao Bing","avatar":""},{"name":"Lai Xi","avatar":""},{"name":"Wang Chengsi","avatar":""},{"name":"Zhu Tianfu","avatar":""},{"name":"Yu Weiwei","avatar":""},{"name":"Wang Deshun","avatar":""},{"name":"Na Wei","avatar":""},{"name":"Pan Yuanjia","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[