INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-tim-sat-da', 'Con Tim Sắt Đá', 'Heart Of Stone', 'https://phimimg.com/upload/vod/20250325-1/3a4a27ee1d65438343ded7f5cbc97fcb.jpg', 'https://phimimg.com/upload/vod/20250325-1/085bb8f8441c5bb1ce9a2ec12d9acfd6.jpg', '<p>Tiêu Lãng, chủ tịch mới nhậm chức rầm rộ của Tập đoàn Chí Trăn, lại có thân phận thật bí mật. Anh từng là con trai duy nhất kế thừa Tập đoàn Chí Trăn, nhưng lại bị mẹ kế cướp mất toàn bộ mọi thứ vốn thuộc về mình. Tô Minh Vũ từng là ánh sáng duy nhất trong thời thơ ấu thê thảm của Tiêu Lãng. Tiêu Lãng phẫu thuật thẩm mỹ, quay về trả thù, nhưng tình yêu và sự kiên trì của Tô Minh Vũ đã hết lần này đến lần khác cứu rỗi thế giới tối tăm của anh.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Dai Gaozheng","avatar":""},{"name":"Jin Zixuan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Tie Shi Xin Chang","อสูรเริงไฟ","铁石心肠"]', 1784690324158);
