INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khat-khao-ruc-lua', 'Khát Khao Rực Lửa', 'House Of Flames', 'https://phimimg.com/upload/vod/20250204-1/c40977cf2738691fd2462e53743454d2.jpg', 'https://phimimg.com/upload/vod/20250204-1/94f4423b5f68dfea6bde45e2b6c8c0d5.jpg', '<p>Năm 1912, một vụ hỏa hoạn khủng khiếp xảy ra tại bữa tiệc lớn ở dinh thự Sila Kram, dẫn đến cái chết của Khun Phra Phakdee và sự mất tích của cháu gái ông, Kaewta. Mười năm sau, Kaewta quay trở lại để làm sáng tỏ bí ẩn đằng sau đêm định mệnh ấy. Liệu ngọn lửa năm xưa đã thật sự tắt hẳn hay Khát Khao Rực Lửa trong trái tim con người sẽ tiếp tục thiêu đốt và tán phá mà không bao giờ có hồi kết?</p>', 'Hoàn Tất (20/20)', 20, 'series', 'ongoing', 10, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Jam Rachata Hampanont","avatar":""},{"name":"Toy Pathompong Reonchaidee","avatar":""},{"name":"Camilla Kittivat Kirn","avatar":""},{"name":"Paifah Nutchaporn Ounsawad","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ruean Chon Saeng","เรือนโชนแสง"]', 1784690324158);
