INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hen-nguoi-o-dia-nguc', 'Hẹn Ngươi Ở Địa Ngục', 'Hell For You', 'https://phimimg.com/upload/vod/20250209-1/8c3edac459063cb0a73c248620240328.jpg', 'https://phimimg.com/upload/vod/20250209-1/215af795177d0856fd25859c9d8b14ae.jpg', '<p>Muốn trả thù sau khi bị gài tội giết người 14 năm trước, Sachiko thay đổi ngoại hình và thâm nhập vào nhà của một người có tầm ảnh hưởng nổi tiếng dưới vỏ bọc bảo mẫu.</p>', 'Full', 11, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Nozomi Sasaki","avatar":""},{"name":"Shibuya Nagisa","avatar":""},{"name":"Yuki Inoue","avatar":""},{"name":"Yoshizawa Shizuya","avatar":""},{"name":"Itsuji Itao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["De ta vie un enfer","Jigoku no Hate made Tsurete Iku","Jigoku no Hate made Tsureteiku","ลากลงนรก","I''ll Take You to The End of Hell","地獄の果てまで連れていく"]', 1784690324158);
