INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-gac-dem-mao-son', 'Người Gác Đêm Mao Sơn', 'Maoshan Night Watchman', 'https://phimimg.com/upload/vod/20250331-1/ddefd7600bec19e507f76893f916886c.jpg', 'https://phimimg.com/upload/vod/20250331-1/e4106e9f517e1406d5fd3b608dfff174.jpg', '<p>Bộ phim kể về câu chuyện của Hứa Tùng, đại thiếu gia của gia tộc Hứa thị ở trấn Thiên An vào cuối triều Thanh – đầu thời Dân Quốc. Sau khi thoát chết từ cánh cổng địa ngục, anh phải chịu đựng nỗi đau mất đi tất cả người thân và chịu đựng hành hạ thể xác với việc cạo xương đổi mặt. Anh cải trang thành Mao Tiểu Sơn, một người tuần đêm, và quay trở lại trấn Thiên An. Nhưng lúc này, trấn nhỏ lại liên tục xảy ra những sự kiện kinh hoàng. Mang theo mối hận sâu như biển, anh buộc phải ẩn nhẫn đối diện với người yêu cũ từng có hôn ước và người bạn thân nhất mà không thể tiết lộ thân phận. Những ngôi mộ hoang lạnh lẽo, căn nhà cổ u ám và những hang động kỳ bí trở thành chướng ngại khiến hành trình tìm kiếm sự thật của Mao Tiểu Sơn đầy rẫy nguy hiểm. Nhưng anh không lùi bước, dùng lòng can đảm phi thường để vén màn bí ẩn. Khi đối mặt với cái chết cận kề, với ba năm khổ luyện đạo thuật Mao Sơn, anh tạo ra một trận quyết chiến đẫm máu, tự tay tiêu diệt kẻ thù và giải oan cho những linh hồn thân yêu đã khuất.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Kong Qili","avatar":""},{"name":"Lin Wenjie","avatar":""},{"name":"Xie Jingwen","avatar":""},{"name":"Zhang Lin","avatar":""},{"name":"Zhu Qinglei","avatar":""},{"name":"Li Hongwei","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Mao Shan Da Geng Ren","Maoshan Night Watchman","茅山打更人"]', 1784690324158);
