INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-dich-tui-den', 'Chiến Dịch Túi Đen', 'Black Bag', 'https://phimimg.com/upload/vod/20250403-1/9ec0abbd3cda70aefc44e8ab43094f42.jpg', 'https://phimimg.com/upload/vod/20250403-1/fa176a509a7cec4c01313d7d0b8bfb82.jpg', '<p>Khi một đặc vụ tình báo bị nghi ngờ phản bội đất nước, chồng cô—một huyền thoại trong giới điệp viên—phải đối mặt với thử thách lớn nhất: trung thành với hôn nhân hay với tổ quốc ?</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Cate Blanchett","avatar":""},{"name":"Michael Fassbender","avatar":""},{"name":"Marisa Abela","avatar":""},{"name":"Tom Burke","avatar":""},{"name":"Naomie Harris","avatar":""},{"name":"Regé-Jean Page","avatar":""},{"name":"Pierce Brosnan","avatar":""},{"name":"Gustaf Skarsgård","avatar":""},{"name":"Kae Alexander","avatar":""},{"name":"Martin Bassindale","avatar":""},{"name":"Megan Kimber","avatar":""},{"name":"Paul Bailey","avatar":""},{"name":"Bruce Mackinnon","avatar":""},{"name":"Orli Shuka","avatar":""},{"name":"Daniel Dow","avatar":""},{"name":"Dane Juler","avatar":""},{"name":"Reena Dusila","avatar":""},{"name":"A","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Confidencial","黑袋行動","Operacja Black Bag","Սև Տոպրակ","Sev Toprak","Le sac noir","ブラックバッグ","Black Bag"]', 1784690324158);
