INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chien-dich-tui-den', 'Chiến Dịch Túi Đen', 'Black Bag', 'chiến dịch túi đen black bag cate blanchett michael fassbender marisa abela tom burke naomie harris regé-jean page pierce brosnan gustaf skarsgård kae alexander martin bassindale megan kimber paul bailey bruce mackinnon orli shuka daniel dow dane juler reena dusila a confidencial 黑袋行動 operacja black bag սև տոպրակ sev toprak le sac noir ブラックバッグ black bag', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lao-cau', 'Lão Cẩu', 'Bleed For Past', 'https://phimimg.com/upload/vod/20250324-1/3dfd111887d4d2045f6a0b827986d524.jpg', 'https://phimimg.com/upload/vod/20250324-1/2e1a0a1a4ac56335095b726ef826f6a2.jpg', '<p>Đông Tử, một cảnh sát chìm luôn khao khát phá được một vụ án ma túy lớn, được giao nhiệm vụ thâm nhập vào tổ chức của Lão Cẩu – một tay anh chị giang hồ đang ngày đêm nghĩ đến chuyện “rửa tay gác kiếm”. Từ đó bắt đầu một hành trình kịch tính, nơi sự sống và cái chết luôn cận kề, nơi nhiệm vụ và lòng người bị thử thách đến tận cùng. Cuộc đối đầu giữa cảnh sát và tội phạm không đơn thuần là chính – tà, mà là câu chuyện về hai linh hồn cô độc: kẻ ngoài vòng pháp luật – Lão Cẩu, và chàng cảnh sát sống trong vỏ bọc – Đông Tử. Trong vở kịch &quot;công lý đầy dối trá&quot;, họ dần trao cho nhau sự tin tưởng và tình huynh đệ. Khi tình thân, lý trí và tình yêu bị đẩy đến giới hạn, cả hai buộc phải đưa ra những lựa chọn sinh tử. Lão Cẩu và Đông Tử, hai người anh em vào sinh ra tử, cuối cùng đều tìm thấy lối ra cho số phận của riêng mình.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jiang Wu","avatar":""},{"name":"Liu Yitie","avatar":""},{"name":"Bao Bei Er","avatar":""},{"name":"Ma Su","avatar":""},{"name":"Zhu Shimao","avatar":""},{"name":"Hu Zicheng","avatar":""},{"name":"Liu Yitong","avatar":""},{"name":"An Hu","avatar":""},{"name":"Ning Xiaohua","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["老狗"]', 1784690324158);
