INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ben-trong-may-trang', 'Bên Trong Mây Trắng', 'The Ranger', 'https://phimimg.com/upload/vod/20250402-1/a8eae5814d543f1e64340f53c94350d3.jpg', 'https://phimimg.com/upload/vod/20250402-1/bb4d4f4c125c2ae5e547f4e07456e1f1.jpg', '<p>Lý Văn Thiên thi trượt đại học và đến thị trấn lập nghiệp. Nhờ sự giới thiệu của bạn thân, anh bắt đầu làm việc dưới trướng Bân ca. Cùng lúc đó, cha anh là Lý Trọng Sơn mất tích bí ẩn khi điều tra một vụ săn trộm. Sự sống chết của ông vẫn chưa được làm rõ. Trong quá trình lần theo những manh mối cha để lại, Văn Thiên phát hiện tất cả mọi chuyện đều có liên quan đến Bân ca. Săn trộm, giết người, giấu xác… Mỗi bí ẩn mở ra lại kéo theo một sự thật rợn người. Văn Thiên thề rằng anh phải tìm ra cha mình bằng mọi giá! Một bữa tiệc của tình yêu, thù hận và những màn báo thù nghẹt thở sắp bắt đầu!</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Liu Ninghao","avatar":""},{"name":"Liu Xinlei","avatar":""},{"name":"Lu Menglin","avatar":""},{"name":"李森","avatar":""},{"name":"Sun Hao","avatar":""},{"name":"Zhou Bo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["白云深处"]', 1784690324158);
