INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-an-thi-tran-holland', 'Bí Ẩn Thị Trấn Holland', 'Holland', 'https://phimimg.com/upload/vod/20250402-1/5b71a3ac5fbf0496c88747c802cc73de.jpg', 'https://phimimg.com/upload/vod/20250402-1/02fa298edf4f2089d5fb4bfb22d82dab.jpg', '<p>Phim &quot;Holland&quot; (2025) kể về một giáo viên ở thị trấn nhỏ bắt đầu nghi ngờ chồng mình đang che giấu bí mật đen tối. Cô phát hiện ra những sự thật đáng sợ và cuộc sống dần bị cuốn vào những âm mưu đầy rối ren. Với sự tham gia của Nicole Kidman, Matthew Macfadyen và Gael García Bernal, bộ phim tạo nên sự hồi hộp và bất ngờ qua từng khung hình.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Nicole Kidman","avatar":""},{"name":"Gael García Bernal","avatar":""},{"name":"Matthew Macfadyen","avatar":""},{"name":"Jude Hill","avatar":""},{"name":"Jeff Pope","avatar":""},{"name":"Isaac Krasner","avatar":""},{"name":"Lennon Parham","avatar":""},{"name":"Rachel Sennott","avatar":""},{"name":"Chris Witaske","avatar":""},{"name":"River Brooks","avatar":""},{"name":"Jens Frederiksen","avatar":""},{"name":"Bill Russell","avatar":""},{"name":"Andrew Sodroski","avatar":""},{"name":"Jacob Moran","avatar":""},{"name":"Irene Dewyn","avatar":""},{"name":"Jonathon Pawlowski","avatar":""},{"name":"Sue Rock","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Holland, Michigan","Welcome to Holland","荷兰镇","Հոլլանդ","Holland, MI","Holland"]', 1784690324158);
