INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-cuop-sieu-xe', 'Băng Cướp Siêu Xe', 'Carjackers', 'https://phimimg.com/upload/vod/20250402-1/77d51e361aebf24e15b5795a40c3121f.jpg', 'https://phimimg.com/upload/vod/20250402-1/2f8e2d6b822ce23648450bbe2a441306.jpg', '<p>Phim kể về nhóm bạn trẻ Nora, Zoé, Steve và Prestance, những người làm việc tại các khách sạn sang trọng với vai trò như nhân viên đỗ xe, tiếp tân, khuân vác và bartender. Ban ngày, họ phục vụ khách hàng giàu có; ban đêm, họ lợi dụng thông tin thu thập được để thực hiện các vụ cướp xe táo bạo trên đường. Họ tự gọi mình là &quot;Carjackers&quot; và hoạt động với sự gắn kết như một gia đình, luôn giữ bí mật và không để lại dấu vết.Khi họ lên kế hoạch cho phi vụ cuối cùng nhằm đạt được tự do tài chính, một giám đốc khách sạn đã thuê Elias, một sát thủ chuyên nghiệp, để truy lùng và tiêu diệt nhóm này.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Zoé Marchal","avatar":""},{"name":"Franck Gastambide","avatar":""},{"name":"Bosh","avatar":""},{"name":"Mareva Ranarivelo","avatar":""},{"name":"Alassane Diong","avatar":""},{"name":"Sérigne Gueye","avatar":""},{"name":"Mylène Jampanoï","avatar":""},{"name":"Alix Bénézech","avatar":""},{"name":"Hafid F. Benamar","avatar":""},{"name":"Zoé Diowo-Ceccaldi","avatar":""},{"name":"Florence Fauquet","avatar":""},{"name":"Jonathan Demurger","avatar":""},{"name":"Pascal Elso","avatar":""},{"name":"Agnès Godey","avatar":""},{"name":"Noémie Desbordes","avatar":""},{"name":"Colin Bates","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["劫车王","Carjackers"]', 1784690324158);
