INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuyen-truong-popeye', 'Thuyền Trưởng Popeye', 'Popeye the Slayer Man', 'https://phimimg.com/upload/vod/20250402-1/326078d0fbc0197b2bbc9d5a8be814fd.jpg', 'https://phimimg.com/upload/vod/20250402-1/cb5659a6845fe6b189fb92b1eba8ba2f.jpg', '<p>Một nhóm sinh viên quyết định quay phim tài liệu về truyền thuyết &quot;Người thủy thủ&quot; tại nhà máy đóng hộp rau bina bỏ hoang, nơi được cho là bị ám bởi nhân vật này. Trong quá trình khám phá, họ phát hiện ra rằng truyền thuyết không chỉ là hư cấu khi đối mặt với một thực thể siêu nhiên có sức mạnh khủng khiếp. Những bí mật đen tối về sự ô nhiễm tại nhà máy và sự biến đổi của &quot;Người thủy thủ&quot; dần được hé lộ, đặt nhóm bạn trẻ vào tình thế nguy hiểm chết người.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sarah Nicklin","avatar":""},{"name":"Scott Swope","avatar":""},{"name":"Angela Relucio","avatar":""},{"name":"Steven McCormack","avatar":""},{"name":"Mabel Thomas","avatar":""},{"name":"Rich Lounello","avatar":""},{"name":"Sean Michael Conway","avatar":""},{"name":"Joel Frometa","avatar":""},{"name":"Nathan Todaro","avatar":""},{"name":"Elena Juliano","avatar":""},{"name":"Marie-Louise Boisnier","avatar":""},{"name":"Jeff Thomas","avatar":""},{"name":"Doug Decker","avatar":""},{"name":"Jason Robert Stephens","avatar":""},{"name":"Paul Konye","avatar":""},{"name":"Clayton Turner","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Popeye: The Slayer Man","大力杀手波派","大力水手：血腥菠菜","Popeye the Slayer Man"]', 1784690324158);
