INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vang-va-long-tham-cuoc-san-tim-kho-bau-cua-fenn', 'Vàng Và Lòng Tham: Cuộc Săn Tìm Kho Báu Của Fenn', 'Gold & Greed: The Hunt For Fenn''s Treasure', 'https://phimimg.com/upload/vod/20250328-1/bc5f362cd6940fca1b70510fc4c9ae60.jpg', 'https://phimimg.com/upload/vod/20250328-1/c2d52104f4ad705bb33d351b37f51ef1.jpg', '<p>Một người đàn ông lập dị tên là Forrest Fenn khơi mào cuộc săn tìm kho báu ngoài đời thực khi giấu một rương vàng ở dãy núi Rocky – và cài manh mối trong một bài thơ bí ẩn.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Gold & Greed: The Hunt for Fenn''s Treasure"]', 1784690324158);
