INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('giot-tinh-cua-niyala', 'Giọt tình của Niyala', 'Promised Hearts', 'giọt tình của niyala promised hearts beby tsabina deva mahenra caitlin halderman dito darmawan imran ismail kiki narendra alya rohali ayez kassar arry febrian cinta dewi vonny anggraini jasmine elfira burhan muhammad fauzan rafi fachryan felix curly promesas del corazón les promesses du cœur obećana srca a szív ígérete obiecane serca corações prometidos inimi promise giọt tình của niyala vadedilmiş kalpler příslib srdce υπόσχεση καρδιάς обіцяні серця ליבה של ניאלה قلوب موعودة 心有所约 心抱きしめて 나얄라의 사랑은 setetes embun cinta niyala', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-vien-ke-can', 'Điệp Viên Kế Cận', 'Inheritance', 'https://phimimg.com/upload/vod/20250331-1/1a75e44084dfb6d7f0f7f3865ad8673f.jpg', 'https://phimimg.com/upload/vod/20250331-1/1dea520650b57f5bd2084a9aabc89063.jpg', '<p>Maya, một cô gái bình thường, bất ngờ phát hiện cha mình từng là một điệp viên với quá khứ đầy bí ẩn. Khi sự thật bị phơi bày, Maya rơi vào vòng xoáy của một âm mưu quốc tế và trở thành mục tiêu truy sát. Để sống sót, cô phải khai thác kinh nghiệm và học những kỹ năng của cha mình, bước vào thế giới gián điệp đầy nguy hiểm, nơi không ai có thể tin tưởng.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Phoebe Dynevor","avatar":""},{"name":"Rhys Ifans","avatar":""},{"name":"Ciara Baxendale","avatar":""},{"name":"Kersti Bryan","avatar":""},{"name":"Majd Eid","avatar":""},{"name":"Byron Clohessy","avatar":""},{"name":"Joey Albright","avatar":""},{"name":"José Alvarez","avatar":""},{"name":"Jack Lyons","avatar":""},{"name":"Mitchell Hochman","avatar":""},{"name":"Salim Siddiqui","avatar":""},{"name":"John Garet Stoker","avatar":""},{"name":"Necar Zadegan","avatar":""},{"name":"Adam El Nahas","avatar":""},{"name":"Ihab Ebrahim","avatar":""},{"name":"Kashyap Harsha Shangari","avatar":""},{"name":"Nishant","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["인헤리턴스","Inheritance"]', 1784690324158);
