INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('may-va-am-duong', 'May Vá Âm Dương', 'Stitching Life And Death', 'https://phimimg.com/upload/vod/20250316-1/0cdd61499bbf1bc4f3a6303b69458a7d.jpg', 'https://phimimg.com/upload/vod/20250316-1/65a3f3e929832d67e0077e7c85b1c40a.jpg', '<p>Mã Tam, truyền nhân phái Âm Dương may vá dùng kỹ thuật khâu thần kỳ giúp trạng sư Tống Nguyên khâu đầu để giữ mạng sống, thoát khỏi kiếp nạn. Cả hai cùng nhau điều tra, phá hàng loạt vụ án ly kỳ, trả lại công bằng cho người dân. Sau cùng, họ hợp lực đưa cha con tham quan ra trước công lý.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ứng Hạo Minh","avatar":""},{"name":"Thị Tuyên Như","avatar":""},{"name":"Nhạc Đông Phong","avatar":""},{"name":"Trịnh Tinh Tinh","avatar":""},{"name":"Thang Duy Văn","avatar":""},{"name":"Dương Hàm Bân","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yin Yang Cai Feng","Yin Yang Tailor","阴阳裁缝"]', 1784690324158);
