INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('may-va-am-duong', 'May Vá Âm Dương', 'Stitching Life And Death', 'may vá âm dương stitching life and death ứng hạo minh thị tuyên như nhạc đông phong trịnh tinh tinh thang duy văn dương hàm bân yin yang cai feng yin yang tailor 阴阳裁缝', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dua-anh-vao-cuoc-choi', 'Đưa Anh Vào Cuộc Chơi', 'Rising From The Ashes', 'https://phimimg.com/upload/vod/20250320-1/0a15c7fee489558ecc0fdf0c2486e2d1.jpg', 'https://phimimg.com/upload/vod/20250320-1/97795b56939c1b407404fb352a5519c1.jpg', '<p>Hứa Tranh là một bà nội trợ toàn thời gian, Lục Diễn chồng cô là bác sĩ chính tại một bệnh viện tư nhân. Sau năm năm kết hôn, hai người có một cô con gái đáng yêu tên Lục Gia Gia. Một năm trước, Hứa Tranh bắt đầu gặp vấn đề về giấc ngủ, tình trạng ngày càng nghiêm trọng, đôi khi còn xuất hiện ảo giác và có xu hướng tự làm hại bản thân hoặc người khác. Tuy nhiên, một vụ tai nạn xe hơi đã thay đổi cuộc hôn nhân vốn dĩ hạnh phúc này. Chiếc xe lao xuống hồ, Lục Diễn may mắn được người qua đường cứu giúp và giữ được mạng sống, nhưng Hứa Tranh lại mất tích.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Soái","avatar":""},{"name":"Từ Khải Hâm","avatar":""},{"name":"Trương Duyệt","avatar":""},{"name":"La Dư Điềm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["她在深渊时","Zong Ta Ru Ju","Let Him Fall Into the Trap","纵他入局"]', 1784690324158);
