INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dua-anh-vao-cuoc-choi', 'Đưa Anh Vào Cuộc Chơi', 'Rising From The Ashes', 'đưa anh vào cuộc chơi rising from the ashes triệu soái từ khải hâm trương duyệt la dư điềm 她在深渊时 zong ta ru ju let him fall into the trap 纵他入局', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('so-tay-cong-luoc-cua-mau-phi', 'Sổ Tay Công Lược Của Mẫu Phi', 'Consort Strategy Manual', 'https://phimimg.com/upload/vod/20250321-1/a8dd03b6d18ce33988b1e6143e19ee37.jpg', 'https://phimimg.com/upload/vod/20250321-1/d49c16a64130c5fd97718d9e1a70c9ff.jpg', '<p>Lữ Thược và Lý Đôn từng là một đôi tình nhân yêu nhau say đắm, nhưng số phận trớ trêu, một người trở thành mẫu phi, một người trở thành hoàng tử. Lý Đôn yêu mà không thể có được Lữ Thược, lại vì ghét cay ghét đắng Lữ Tuân – anh trai của nàng và cũng là tình địch của mình, nên sau khi lên ngôi, hắn dần chuyển tình yêu thành sự hành hạ tàn nhẫn đối với Lữ Thược. Để thoát khỏi Lý Đôn, Lữ Thược lập kế hoạch bỏ trốn nhưng giữa đường lại chạm mặt Quý phi Văn Chiêu. Trong lúc tranh cãi, cả hai bị sét đánh trúng, khi tỉnh lại thì phát hiện họ đã hoán đổi thân xác cho nhau. Lý Đôn dần nhận ra sự khác biệt của vị Quý phi trước mắt. Trong khi đó, Văn Chiêu trong thân xác Lữ Thược cũng tỉnh lại, với tham vọng quyền lực, nàng phát hiện mình đã trở thành Thái hậu đầy quyền uy. Cô lợi dụng tình yêu của Lữ Tuân dành cho em gái và thân phận Thái hậu để nhiều lần mưu hại Lữ Thược, nhưng đều bị nàng phản kích mạnh mẽ. Khi Lý Đôn phát hiện ra sự thật về việc hoán đổi thân xác, Lữ Thược mong muốn rời cung để có được tự do. Tuy nhiên, vì không muốn mất nàng, Lý Đôn đã một lần nữa giam cầm Lữ Thược bên mình và từ đó phạm phải sai lầm nghiêm trọng.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wang Junbi","avatar":""},{"name":"Guo Xingye","avatar":""},{"name":"Zhang Ce","avatar":""},{"name":"Nie Hanming","avatar":""},{"name":"Long Xing''er","avatar":""},{"name":"Qi Xueting","avatar":""},{"name":"Quan Xin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mu Fei Gong Lue Shou Ce","모비공략수책: 폐하는 그녀를 유혹 중","Consort Strategy Manual","母妃攻略手册"]', 1784690324158);
