INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-thay-tang-su', 'Bậc Thầy Tang Sự', 'Mr. Funera', 'https://phimimg.com/upload/vod/20250330-1/d64b4ad75535208a7354c818f64ac08a.jpg', 'https://phimimg.com/upload/vod/20250330-1/1eb6a7005885289a7598c541df9c0dcb.jpg', '<p>Bộ phim kể về hành trình của Thuận Hỷ, người dần trưởng thành và trở thành một bậc thầy tang lễ thông qua những lần nhận ủy thác tổ chức tang sự. Trải qua nhiều câu chuyện, anh dần hiểu ra ý nghĩa thực sự của công việc này: tiễn đưa người đã khuất trong sự tôn nghiêm và giúp người ở lại tìm được sự an ủi, thanh thản.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Shi Yuanting","avatar":""},{"name":"Johnson Wang","avatar":""},{"name":"Wang Gang","avatar":""},{"name":"Li Yuanbing","avatar":""},{"name":"Wang Yifan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bai Shi Xian Sheng","Mr. Funeral","白事先生"]', 1784690324158);
