INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-ma-ma-ma-ca-rong', 'Ma ma ma ma cà rồng', 'Babanba Banban Vampire', 'https://phimimg.com/upload/vod/20250112-1/570767bc697685d2856957c36ad24ad2.jpg', 'https://phimimg.com/upload/vod/20250112-1/ffbd79f4d68ef082674d7e955ffae519.jpg', '<p>Một ma cà rồng làm việc ở nhà tắm nọ với hi vọng được uống máu trai tân của người thừa kế nơi này, Rihito. Nhưng Rihito lại vô tình rơi vào lưới tình ngay ngày đầu tiên vào cấp ba.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Daisuke Namikawa","avatar":""},{"name":"Yusuke Kobayashi","avatar":""},{"name":"Mayuko Kazama","avatar":""},{"name":"Taku Yashiro","avatar":""},{"name":"Akira Sekine","avatar":""},{"name":"Katsuyuki Konishi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["吸吸吸吸吸血鬼","バババ","Babanba Banban Vampire","ババンババンバンバンパイア"]', 1784690324158);
