INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ubel-blatt', 'Ubel Blatt', 'Übel Blatt', 'https://phimimg.com/upload/vod/20250209-1/7d62b24192b24adeffc1651798ca0cb4.jpg', 'https://phimimg.com/upload/vod/20250209-1/31f7adc1d479e0c988e4cc091f4420b1.jpg', '<p>Köinzell, cậu bé bí ẩn mang thanh kiếm đen, không thể phủ nhận rằng cậu sử dụng nó với kỹ năng đặc biệt, nhưng liệu cậu có thực sự chịu trách nhiệm cho những tin đồn đẫm máu không? Bị truy đuổi bởi Traitorous Lances, bốn chiến binh mạnh mẽ được cho là đã bị Seven Heroes đánh bại, sức mạnh của kiếm sĩ trẻ sẽ được thử thách đến giới hạn. Vào cuối trận chiến, chỉ có sự thật gây sốc về nhiệm vụ của Köinzell mới có thể đứng vững trên xác chết của kẻ thù... Một sử thi giả tưởng trên quy mô lớn nhất!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuya Hirose","avatar":""},{"name":"Hina Tachibana","avatar":""},{"name":"Toshiki Masuda","avatar":""},{"name":"Hitomi Ueda","avatar":""},{"name":"Yui Kanari","avatar":""},{"name":"Kenichirou Matsuda","avatar":""},{"name":"Kohsuke Toriumi","avatar":""},{"name":"Ryota Suzuki","avatar":""},{"name":"Kazuhiko Inoue","avatar":""},{"name":"Taiten Kusunoki","avatar":""},{"name":"Naoya Uchida","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["魔域英雄传说","Übel Blatt","위벨블라트","ดาบคลั่งทวงแค้น","魔域英雄傳說","Evil Blade","Übel Blatt～ユーベルブラット～"]', 1784690324158);
