INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-vi-sua-tuoi', 'Yêu Vị Sữa Tươi', 'Flirt Milk', 'https://phimimg.com/upload/vod/20250127-1/cca28a9868fb6d29eae5328b12881310.jpg', 'https://phimimg.com/upload/vod/20250127-1/80a0955da14728ebe16933b98e874380.jpg', '<p>Nomjuet, một chàng trai trẻ có tính cách và cuộc sống buồn tẻ đúng như tên gọi, mang ly cà phê bị bỏ quên đến khoa. Ở đó, anh gặp một chàng trai tên Phra-ek có tính cách và cái tên rất khác nhau.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Pooh Poohrin Pattanawiriyawanich","avatar":""},{"name":"Neel Kawich Sansai","avatar":""},{"name":"Newton Waiyakorn Wongkhakaew","avatar":""},{"name":"Paul Somphop Armartmoontree","avatar":""},{"name":"Thunyaphat Inyawilert","avatar":""},{"name":"Putticha Boonyamas","avatar":""},{"name":"Pete Wacharanon Seeduan","avatar":""},{"name":"Rathasat Butwong","avatar":""},{"name":"Bovorn Kongnawdee","avatar":""},{"name":"Chang Jayapol Chiopittayakarn","avatar":""},{"name":"Nattha","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["รักรสนม(จืด)"]', 1784690324158);
