INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-hanh-cung-tho-duong-1-thanh-tho-la-ban-dong-hanh-cua-toi', 'Du Hành Cùng Thơ Đường 1: Thánh Thơ Là Bạn Đồng Hành Của Tôi', 'Roaming China With Tang Poetry', 'https://phimimg.com/upload/vod/20250329-1/acbd48228b93d1e20315db20f202529d.jpg', 'https://phimimg.com/upload/vod/20250329-1/8fff430bfe1fd56f35c2595bbedd2af0.jpg', '<p>Bộ phim xoay quanh hành trình mộng ảo của cô gái hiện đại Sở Từ và thánh thơ Đỗ Phủ xuyên không tới. Vì một lần tai nạn rơi xuống nước, hai người bị trói buộc trở thành bạn đồng hành định mệnh. Sở Từ phải đợi Đỗ Phủ trở về thời cổ đại mới có thể giành lại tự do. Du ngoạn Thành Đô, về Thảo Đường, thăm từ đường Võ Hầu, lên núi Nga Mi...</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Tú","avatar":""},{"name":"Kim Mạn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Gen Zhe Tang Shi Qu Lv Xing Di Yi Ji: Wo He Shi Sheng Zuo Da Zi","跟着唐诗去旅行第一季：我和诗圣做搭子","Traveling with Tang Poetry Season 1: I partnered with the Poet Saint","跟着唐诗去旅行"]', 1784690324158);
