INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('du-hanh-cung-tho-duong-1-thanh-tho-la-ban-dong-hanh-cua-toi', 'Du Hành Cùng Thơ Đường 1: Thánh Thơ Là Bạn Đồng Hành Của Tôi', 'Roaming China With Tang Poetry', 'du hành cùng thơ đường 1: thánh thơ là bạn đồng hành của tôi roaming china with tang poetry lưu tú kim mạn gen zhe tang shi qu lv xing di yi ji: wo he shi sheng zuo da zi 跟着唐诗去旅行第一季：我和诗圣做搭子 traveling with tang poetry season 1: i partnered with the poet saint 跟着唐诗去旅行', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duoi-kip-anh-se-yeu-em', 'Đuổi Kịp Anh Sẽ Yêu Em', 'Race To Romance', 'https://phimimg.com/upload/vod/20250322-1/db17e85a50594517d69f5bd9e86f3b58.jpg', 'https://phimimg.com/upload/vod/20250322-1/ebd63468ec90a9a11c12f316581864ef.jpg', '<p>Để tham gia giải vô địch đua xe thế giới, Thẩm Nghi thay người anh trai hôn mê gia nhập đội đua Trường Cốc, và quen biết Cố Dịch Thần. Qua quá trình tiếp xúc, Thẩm Nghi và Cố Dịch Thần từ không đánh không quen biết đến dần nảy sinh tình cảm. Cuối cùng, hai người vượt qua muôn vàn khó khăn, ngọt ngào bên nhau, cùng nhau lao về đích.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Thân Hạo Nam","avatar":""},{"name":"Đoàn Cảnh Dịch","avatar":""},{"name":"Trương Thần Quang","avatar":""},{"name":"Ngu Tử Phiên","avatar":""},{"name":"Cung Chính Diệp","avatar":""},{"name":"Dương Hy","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Zhui Shang Wo Jiu Ai Shang Ni","追上我就爱上你"]', 1784690324158);
