INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-the-toi-chi-la-mot-le-tan-hoi-nhung-toi-se-mot-minh-danh-bai-bat-ky-boss-nao-de-tan-lam-dung-gio', 'Có thể tôi chỉ là một lễ tân hội, nhưng tôi sẽ một mình đánh bại bất kỳ Boss nào để tan làm đúng giờ', 'I May Be a Guild Receptionist, but I''ll Solo Any Boss to Clock Out on Time', 'https://phimimg.com/upload/vod/20250111-1/94c08a22d90b38fbbb49392b8377ad30.jpg', 'https://phimimg.com/upload/vod/20250111-1/447a76c70474408015193c8648825038.jpg', '<p>Gặp gỡ Alina: lễ tân hội vào ban ngày, anh hùng giết Boss bí mật vào ban đêm. Nhưng nếu ai đó phát hiện ra cuộc sống hai mặt của cô, cô có thể mất tất cả.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Rie Takahashi","avatar":""},{"name":"Kentaro Kumagai","avatar":""},{"name":"Aoi Koga","avatar":""},{"name":"Rikuya Yasuda","avatar":""},{"name":"Yu Serizawa","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["虽然是公会柜台小姐，但是因为讨厌加班所以要去单挑BOSS","虽然是公会的前台小姐，因为讨厌加班，所以打算自己讨伐boss","虽然是公会的柜台小姐，但因为不想加班所以打算独自讨伐首领","虽然是公会的柜台小姐，但因为不想加班所以打算独自讨伐迷宫头目","Guild no Uketsuke Jō Desu ga, Zangyō wa Iyananode Boss o Solo Tōbatsu Shiyou to Omoimasu","Guild no Uketsuke Jou Desu ga, Zangyou wa Iyananode Boss wo Solo Toubatsu Shiyou to Omoimasu","ギルます","Guild no Uketsukejou desu ga, Zangyou wa Iya nanode Boss wo Solo Toubatsu Shiyou to Omoimasu","Guild no Uketsukejou desu ga Zangyou wa Iya nanode Boss wo Solo Tobatsu Shiyou to Omoimasu","ギルドの受付嬢ですが、残業は嫌なのでボスをソロ討伐しようと思います","Girumasu"]', 1784690324158);
