INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-the-toi-chi-la-mot-le-tan-hoi-nhung-toi-se-mot-minh-danh-bai-bat-ky-boss-nao-de-tan-lam-dung-gio', 'Có thể tôi chỉ là một lễ tân hội, nhưng tôi sẽ một mình đánh bại bất kỳ Boss nào để tan làm đúng giờ', 'I May Be a Guild Receptionist, but I''ll Solo Any Boss to Clock Out on Time', 'có thể tôi chỉ là một lễ tân hội, nhưng tôi sẽ một mình đánh bại bất kỳ boss nào để tan làm đúng giờ i may be a guild receptionist, but i''ll solo any boss to clock out on time rie takahashi kentaro kumagai aoi koga rikuya yasuda yu serizawa 虽然是公会柜台小姐，但是因为讨厌加班所以要去单挑boss 虽然是公会的前台小姐，因为讨厌加班，所以打算自己讨伐boss 虽然是公会的柜台小姐，但因为不想加班所以打算独自讨伐首领 虽然是公会的柜台小姐，但因为不想加班所以打算独自讨伐迷宫头目 guild no uketsuke jō desu ga, zangyō wa iyananode boss o solo tōbatsu shiyou to omoimasu guild no uketsuke jou desu ga, zangyou wa iyananode boss wo solo toubatsu shiyou to omoimasu ギルます guild no uketsukejou desu ga, zangyou wa iya nanode boss wo solo toubatsu shiyou to omoimasu guild no uketsukejou desu ga zangyou wa iya nanode boss wo solo tobatsu shiyou to omoimasu ギルドの受付嬢ですが、残業は嫌なのでボスをソロ討伐しようと思います girumasu', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ai-da-thay-con-cong-nhay-mua-trong-rung', 'Ai Đã Thấy Con Công Nhảy Múa Trong Rừng', 'Who Saw The Peacock Dance In The Jungle', 'https://phimimg.com/upload/vod/20250125-1/b67329ce604a02d7c5d4035eb342edc7.jpg', 'https://phimimg.com/upload/vod/20250125-1/99230aee0568b914bba2c2f659cbb5e6.jpg', '<p>Tìm thấy lá thư ám chỉ một âm mưu đen tối sau khi người cha từng là thanh tra cảnh sát bị sát hại vào đêm Giáng sinh, Komugi hợp tác với một luật sư để khám phá sự thật.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Suzu Hirose","avatar":""},{"name":"Kenichi Matsuyama","avatar":""},{"name":"Lily Franky","avatar":""},{"name":"Hayato Isomura","avatar":""},{"name":"Win Morisaki","avatar":""},{"name":"Kumi Takiuchi","avatar":""},{"name":"Itose Soichi","avatar":""},{"name":"Kouta Nomura","avatar":""},{"name":"Asahi Seino","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["¿Quién vio al pavo real bailar en la jungla?","Kujaku no Dance , Dare ga Mita?","El pavo real bailaba","Who Saw the Peacock Dance in the Jungle?","クジャクのダンス、誰が見た？"]', 1784690324158);
