INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ai-da-thay-con-cong-nhay-mua-trong-rung', 'Ai Đã Thấy Con Công Nhảy Múa Trong Rừng', 'Who Saw The Peacock Dance In The Jungle', 'ai đã thấy con công nhảy múa trong rừng who saw the peacock dance in the jungle suzu hirose kenichi matsuyama lily franky hayato isomura win morisaki kumi takiuchi itose soichi kouta nomura asahi seino ¿quién vio al pavo real bailar en la jungla? kujaku no dance , dare ga mita? el pavo real bailaba who saw the peacock dance in the jungle? クジャクのダンス、誰が見た？', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-la-di-gioi-phan-2', 'Tu La Dị Giới (Phần 2)', 'Ishura (Season 2)', 'https://phimimg.com/upload/vod/20250214-1/e037535c7ab767e2b86a152e4289e844.jpg', 'https://phimimg.com/upload/vod/20250214-1/82a3165e84c1f597321a363c68273685.jpg', '<p><span style="text-wrap-mode: wrap;">Thế giới còn lại các Tu La, những kẻ đều có năng lực giết Ma Vương. Bậc thầy kiếm thuật của Dị Giới, kẻ nhìn ra chiêu tất sát hạ gục đối phương chỉ trong nháy mắt. Lính đánh thuê thần tốc, với tốc độ vượt xa âm thanh. Nhà thám hiểm điểu long sử dụng món vũ khí huyền thoại bằng ba tay. Từ Thuật Sĩ với năng lực tái hiện mọi thứ bằng lời nói. Kẻ ám sát và là thiên sứ reo rắc cái chết người không biết, quỷ không hay… Mồi lửa chiến tranh lại tiếp tục nhen nhóm giữa các Tu La đã ở đỉnh cao sức mạnh từ nhiều chủng tộc và những kẻ địch còn cường bạo hơn nữa, tất cả vì danh hiệu “Dũng Giả chân chính”. Tất cả là mạnh nhất, tất cả là anh hùng, nhưng chỉ một trong số họ sẽ trở thành Dũng Giả. Cuộc chiến tranh đoạt danh vị “Dũng Giả” chính thức khai màn…</span></p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuki Kaji","avatar":""},{"name":"Reina Ueda","avatar":""},{"name":"Aoi Yuki","avatar":""},{"name":"Mamiko Noto","avatar":""},{"name":"Rie Takahashi","avatar":""},{"name":"Sora Amamiya","avatar":""},{"name":"Showtaro Morikubo","avatar":""},{"name":"Romi Park","avatar":""},{"name":"Soichiro Hoshi","avatar":""},{"name":"Koichi Yamadera","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Ishura","lshura","Ищура","Исура","Исура: Война нового короля демонов","Исюра","異修羅"]', 1784690324158);
