INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ban-danh-sach-cuoc-doi', 'Bản Danh Sách Cuộc Đời', 'The Life List', 'bản danh sách cuộc đời the life list sofia carson kyle allen sebastian de souza connie britton josé zúñiga jordi mollà dario ladani sanchez federico rodriguez marianne rendón michael rowland chelsea frei luca padovan rachel zeiger-haag maria jung donnetta lavinia grays ben war the life list', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('suyt-quoc-vuong-dang-ngu-dong', 'Suỵt, Quốc Vương Đang Ngủ Đông', 'Ski Into Love', 'https://phimimg.com/upload/vod/20250311-1/4a3a2982fe3374ff3a2516b882868e70.jpg', 'https://phimimg.com/upload/vod/20250311-1/1850afb0ad54e9e985fb9e44bb9c64b1.jpg', '<p>Tác giả truyện tranh Vệ Chi bất ngờ vướng vào scandal, bị công ty tước mất bút danh và bản quyền tác phẩm. Chìm trong thất vọng, cô vô tình xem được một video về trượt tuyết ván đơn và bị tinh thần dũng cảm của các vận động viên cuốn hút. Điều đó đã thôi thúc cô bắt đầu lại từ đầu với một tác phẩm mới lấy chủ đề trượt tuyết.Vệ Chi lên đường đến khu trượt tuyết Bắc Sơn để tìm cảm hứng và tình cờ gặp huấn luyện viên Thiện Sùng. Trong quá trình luyện tập đầy vất vả, cô không chỉ rèn giũa ý chí kiên cường mà còn dần nảy sinh tình cảm với anh.Thiện Sùng từng là một vận động viên trượt tuyết chuyên nghiệp, nhưng vì em gái bị tàn tật và bản thân cũng bị chấn thương, anh buộc phải từ giã sự nghiệp theo ý nguyện của cha mẹ, nhưng trong tim mình, anh vẫn luôn giữ ngọn lửa đam mê dành cho bộ môn này.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 9, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngu Thư Hân","avatar":""},{"name":"Lâm Nhất","avatar":""},{"name":"Phí Khải Minh","avatar":""},{"name":"Tăng Khả Ny","avatar":""},{"name":"Hạ Hạo Nhiên","avatar":""},{"name":"Hồ Văn Huyên","avatar":""},{"name":"Vương Nhuận Trạch","avatar":""},{"name":"Hứa Thi Duyệt","avatar":""},{"name":"Tằng Hựu Trăn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Esquie no Amor","噓，國王在冬眠","Xu Guo Wang Zai Dong Mian","国王在冬眠","Ski into Love","Shh, The King is Hibernating","Hush, the King Is Hibernating","嘘，国王在冬眠"]', 1784690324158);
