INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('suyt-quoc-vuong-dang-ngu-dong', 'Suỵt, Quốc Vương Đang Ngủ Đông', 'Ski Into Love', 'suỵt, quốc vương đang ngủ đông ski into love ngu thư hân lâm nhất phí khải minh tăng khả ny hạ hạo nhiên hồ văn huyên vương nhuận trạch hứa thi duyệt tằng hựu trăn esquie no amor 噓，國王在冬眠 xu guo wang zai dong mian 国王在冬眠 ski into love shh, the king is hibernating hush, the king is hibernating 嘘，国王在冬眠', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-cuoc-doi-cho-ban-qua-quyt', 'Khi Cuộc Đời Cho Bạn Quả Quýt', 'When Life Gives You Tangerines', 'https://phimimg.com/upload/vod/20250308-1/4ee92d3cb1dbc3e7296a8b0a6edba310.jpg', 'https://phimimg.com/upload/vod/20250308-1/1a65ac6c00bbb15df8431f6d918c6760.jpg', '<p>Ở Jeju, câu chuyện về một cô nàng nhiệt huyết và chàng trai kiên cường trên đảo nảy nở thành câu chuyện trọn đời đầy thăng trầm, minh chứng tình yêu vẫn trường tồn theo thời gian.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"IU","avatar":""},{"name":"Park Bo-gum","avatar":""},{"name":"Moon So-ri","avatar":""},{"name":"Park Hae-jun","avatar":""},{"name":"Choi Dae-hoon","avatar":""},{"name":"Na Moon-hee","avatar":""},{"name":"Kim Yong-rim","avatar":""},{"name":"Lee Jun-young","avatar":""},{"name":"Oh Jung-se","avatar":""},{"name":"Baek Ji-won","avatar":""},{"name":"Hwang Jae-yeol","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["辛苦了","苦尽柑来遇见你","苦尽甘来遇见你","أحسنت عملًا","La vie portera ses fruits","pok-ssak sog-ass-su-da","폭삭 속았수다","Dobra robota","أبليت حسنًا","ยิ้มไว้ในวันที่ส้มไม่หวาน","苦盡柑來遇見你","Thank You For Your Hard Work","When Life Gives You Tangerines","Khi Cuộc Đời Cho Bạn Quả Quýt","폭싹 속았수다"]', 1784690324158);
