INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khi-cuoc-doi-cho-ban-qua-quyt', 'Khi Cuộc Đời Cho Bạn Quả Quýt', 'When Life Gives You Tangerines', 'khi cuộc đời cho bạn quả quýt when life gives you tangerines iu park bo-gum moon so-ri park hae-jun choi dae-hoon na moon-hee kim yong-rim lee jun-young oh jung-se baek ji-won hwang jae-yeol 辛苦了 苦尽柑来遇见你 苦尽甘来遇见你 أحسنت عملًا la vie portera ses fruits pok-ssak sog-ass-su-da 폭삭 속았수다 dobra robota أبليت حسنًا ยิ้มไว้ในวันที่ส้มไม่หวาน 苦盡柑來遇見你 thank you for your hard work when life gives you tangerines khi cuộc đời cho bạn quả quýt 폭싹 속았수다', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-choi-mao-hiem-2025', 'Cuộc Chơi Mạo Hiểm', 'Gazer', 'https://phimimg.com/upload/vod/20250328-1/6c1f8129ebac3322cd2a7fa9654c3ca9.jpg', 'https://phimimg.com/upload/vod/20250328-1/16b4f5caa1e27ed8d0f8c958e8f78ac3.jpg', '<p>Frankie, một bà mẹ trẻ mắc chứng rối loạn nhận thức thời gian, gặp khó khăn trong việc cảm nhận thời gian. Sử dụng băng cassette để hướng dẫn, cô nhận một công việc mạo hiểm từ một người phụ nữ bí ẩn để nuôi gia đình, không hề hay biết những hậu quả đen tối đang chờ đợi.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ariella Mastroianni","avatar":""},{"name":"Marcia DeBonis","avatar":""},{"name":"Renee Gagner","avatar":""},{"name":"Jack Alberts","avatar":""},{"name":"Tommy Kang","avatar":""},{"name":"Emma Pearson","avatar":""},{"name":"Marianne Goodell","avatar":""},{"name":"Grant Schumacher","avatar":""},{"name":"LeJon Woods","avatar":""},{"name":"Jarrett Austin Brown","avatar":""},{"name":"Frank Huerta","avatar":""},{"name":"Annie Pisapia","avatar":""},{"name":"Sheilagh Weymouth","avatar":""},{"name":"Mitchell Cetuk","avatar":""},{"name":"Luis Arroyo Jr.","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Gazer"]', 1784690324158);
