INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-cha-lam-me', 'Làm Cha Làm Mẹ', 'The Parenting', 'https://phimimg.com/upload/vod/20250328-1/c663b56f1330462ba13606fe6b79b668.jpg', 'https://phimimg.com/upload/vod/20250328-1/7db43270e23afcc21b602f0df9bec485.jpg', '<p>Josh và Rohan dự định ra mắt gia đình hai bên vào dịp nghỉ dưỡng cuối tuần nhưng oái oăm thay, ngôi nhà họ thuê là nơi trú ngụ của một hồn ma đã tồn tại 400 năm.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Brandon Flynn","avatar":""},{"name":"Nik Dodani","avatar":""},{"name":"Brian Cox","avatar":""},{"name":"Edie Falco","avatar":""},{"name":"Lisa Kudrow","avatar":""},{"name":"Dean Norris","avatar":""},{"name":"Vivian Bang","avatar":""},{"name":"Parker Posey","avatar":""},{"name":"Kate Avallone","avatar":""},{"name":"Elle Kaye","avatar":""},{"name":"Chloe Sciore","avatar":""},{"name":"Keith R. Beck","avatar":""},{"name":"Johnny Hawe","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["家教","一屋冤鬼亲家","The Parenting"]', 1784690324158);
