INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('batman-ninja-doi-dau-lien-minh-yakuza', 'Batman Ninja Đối Đầu Liên Minh Yakuza', 'Batman Ninja vs. Yakuza League', 'https://phimimg.com/upload/vod/20250328-1/7e743bf2f82e6a4383f9add3ac5fdec0.jpg', 'https://phimimg.com/upload/vod/20250328-1/844101bcb965fcf508838d4b9356649c.jpg', '<p>Gia đình Batman trở về hiện tại và phát hiện Nhật Bản đã biến mất, thay vào đó là một hòn đảo khổng lồ tên Hinomoto lơ lửng trên bầu trời Gotham. Trên đỉnh quyền lực là Yakuza – một nhóm siêu nhân cai trị tàn bạo và trông rất giống Justice League. Giờ đây, Batman và đồng đội phải chiến đấu để cứu Gotham!</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Koichi Yamadera","avatar":""},{"name":"Yuki Kaji","avatar":""},{"name":"Kengo Kawanishi","avatar":""},{"name":"Daisuke Ono","avatar":""},{"name":"Akira Ishida","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Akio Otsuka","avatar":""},{"name":"Nobuyuki Hiyama","avatar":""},{"name":"Romi Park","avatar":""},{"name":"Rie Kugimiya","avatar":""},{"name":"Wataru Takagi","avatar":""},{"name":"Hochu Otsuka","avatar":""},{"name":"Masaki Terasoma","avatar":""},{"name":"Kazuhiro Yamaji","avatar":""},{"name":"Takaya Kamikawa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["忍者蝙蝠侠大战极道联盟","忍者蝙蝠侠对极道联盟","Batman Ninja 2","Batman Ninja Contra A Liga da Yakuza","Batman Ninja Contra Liga da Yakuza","ニンジャバットマン対ヤクザリーグ"]', 1784690324158);
