INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-tuoc', 'Hoàng Tước', 'Watch Your Back', 'https://phimimg.com/upload/vod/20250318-1/e1a7bddeeb767a585cb2acfbb9ec29f2.jpg', 'https://phimimg.com/upload/vod/20250318-1/8d59600134e8c28b6a4573b087f14103.jpg', '<p>Một chuyến tàu xuôi Nam đã đưa viên cảnh sát phương Bắc – Quách Bằng Phi (do Quách Kính Phi thủ vai) – bước vào hành trình truy bắt tội phạm móc túi đầy sóng ngầm. Trong những lần chạm trán căng thẳng với bọn trộm cắp, anh tình cờ gặp được Lê Tiểu Liên (do Tần Lam thủ vai), một nữ bác sĩ lạnh lùng và bí ẩn. Cuộc sống muôn hình vạn trạng dần hiện ra trước mắt – ai là bạn, ai là thù? Một vụ án tưởng chừng đơn giản lại ẩn chứa bí mật phức tạp đến không ngờ. Lần theo dấu vết tội ác, gỡ từng lớp màn che giấu sự thật, một trận chiến trong đêm tối chính thức bắt đầu.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Guo Jingfei","avatar":""},{"name":"Qin Lan","avatar":""},{"name":"Zu Feng","avatar":""},{"name":"Chen Jingke","avatar":""},{"name":"Guo Keyu","avatar":""},{"name":"Zhao Bin","avatar":""},{"name":"Vincent Wong Ho-Shun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["黄雀","黃雀","Stealing Time"]', 1784690324158);
