INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dot-chay-toi-ac', 'Đốt Cháy Tội Ác', 'Unnatural Fire', 'https://phimimg.com/upload/vod/20250314-1/a02b759d64135eb90c998f6873601d40.jpg', 'https://phimimg.com/upload/vod/20250314-1/3f76fbd99c1aaaf8dc44919736b0f940.jpg', '<p>Bộ phim kể về câu chuyện của điều tra viên hỏa hoạn Hứa Đồng Sinh, người kiên trì tìm kiếm sự thật về vụ án cũ của gia đình mình. Trong quá trình làm việc, anh tình cờ tái ngộ người bạn thanh mai trúc mã, pháp y Tân Xuân và phó đội trưởng đội hình sự Thẩm Dã. Ba người cùng nhau thiết lập cơ chế phản ứng nhanh để đối phó với các vụ hỏa hoạn nghiêm trọng, phối hợp phá giải nhiều vụ án cháy nổ bí ẩn, cuối cùng làm sáng tỏ chân tướng vụ án cũ của nhà họ Hứa.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Leon Zhang","avatar":""},{"name":"Cai Wenjing","avatar":""},{"name":"Dai Xu","avatar":""},{"name":"Tu Songyan","avatar":""},{"name":"Wang Longzheng","avatar":""},{"name":"Wang Tonghui","avatar":""},{"name":"Zhang Fan","avatar":""},{"name":"Su Jinyuan","avatar":""},{"name":"Jeremiah Li","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["火调者","火調者","Ran Zui","Huo Diao Zhe","燃罪"]', 1784690324158);
