INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-cuoc-hen-de-yeu', 'Năm Cuộc Hẹn Để Yêu', 'Picture This', 'https://phimimg.com/upload/vod/20250327-1/2e96db48732cb5d3d7f878db6a1d2bc6.jpg', 'https://phimimg.com/upload/vod/20250327-1/76f35c90472b90bcf8a09eccb6a0daf4.jpg', '<p>Đoạn văn trên là phần tóm tắt cốt truyện của một bộ phim hài lãng mạn. Nội dung xoay quanh Pia, một cô gái độc thân đang điều hành một studio nhiếp ảnh gặp khó khăn ở London cùng với người bạn thân Jay. Khi gia đình cô—chị Sonal sắp lập gia đình và mẹ Laxmi thúc giục cô tìm một người bạn đời—cùng với lời tiên tri từ một nhà sư tâm linh rằng cô sẽ gặp được tình yêu đích thực trong năm cuộc hẹn hò tiếp theo, Pia đã bắt đầu một hành trình tìm kiếm tình yêu vừa hài hước vừa đầy cảm xúc, dù phải đối mặt với sự can thiệp của gia đình.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Simone Ashley","avatar":""},{"name":"Hero Fiennes Tiffin","avatar":""},{"name":"Sindhu Vee","avatar":""},{"name":"Luke Fetherston","avatar":""},{"name":"Nikesh Patel","avatar":""},{"name":"Adil Ray","avatar":""},{"name":"Anoushka Chadha","avatar":""},{"name":"Eben Figueiredo","avatar":""},{"name":"Kulvinder Ghir","avatar":""},{"name":"Asim Chaudhry","avatar":""},{"name":"Phil Dunster","avatar":""},{"name":"Sophia La Porta","avatar":""},{"name":"Richard Glover","avatar":""},{"name":"Cordelia Bugeja","avatar":""},{"name":"Christopher Goh","avatar":""},{"name":"Ashwin Sakthivel","avatar":""},{"name":"Ad","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Five Blind Dates","约会五重奏","Picture This"]', 1784690324158);
