INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('soda-chanh-mat-ong', 'Soda Chanh Mật Ong', 'Honey Lemon Soda', 'https://phimimg.com/upload/vod/20250109-1/e95c41356e728d0c43b4e1fd33c79395.jpg', 'https://phimimg.com/upload/vod/20250109-1/b4bd7497bda7875a96060db27b95c882.jpg', '<p>Thường xuyên bị bắt nạt trong suốt thời gian học cấp hai, cô gái nhút nhát Ishimori Uka quyết tâm thay đổi bản thân trước khi bước vào những năm học cấp ba. Ngay trong tuần đầu tiên, cô tình cờ gặp Miura Kai, một chàng trai nổi bật với mái tóc màu vàng chanh. Hoàn toàn trái ngược với Uka, anh ấy nổi tiếng, tự tin và luôn nói lên suy nghĩ của mình. Dù có nhiều khác biệt, Kai đã giúp Uka dần dần thoát khỏi vỏ bọc và trở nên mạnh mẽ hơn. Từ những tình huống hài hước và cảm động, mối quan hệ giữa Uka - Kai phát triển thành tình yêu, thay đổi cuộc sống của cả hai mãi mãi.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yano Shougo","avatar":""},{"name":"Kana Ichinose","avatar":""},{"name":"Rie Takahashi","avatar":""},{"name":"Shunichi Toki","avatar":""},{"name":"Taku Yashiro","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["蜂蜜柠檬碳酸水","青春特调蜂蜜柠檬苏打","Hanī Remon Sōda","Honey Lemon Soda","ฮันนี่ เลมอน โซดา","青春特調蜂蜜檸檬蘇打","ハニーレモンソーダ"]', 1784690324158);
