INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoc-dong-quy-dao', 'Ngược Dòng Quỹ Đạo', 'Reverse With Me', 'https://phimimg.com/upload/vod/20250206-1/8b246ae30bb5eef961be613f4feb8e68.jpg', 'https://phimimg.com/upload/vod/20250206-1/12f97ae3ae4b0df0b57fd8593454794b.jpg', '<p>Karan và Kliao Khluen, hai linh hồn gắn kết bởi tình yêu được nuôi dưỡng trong thế giới của những giấc mơ. Du hành ngược thời gian, họ tìm cách hàn gắn những vết rạn nứt của quá khứ. Tuy nhiên, việc thay đổi quá khứ đã giải phóng những hậu quả không lường trước được, một số hậu quả ngoài tầm với của cả thời gian.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Nattamon Chokejindachai","avatar":""},{"name":"Pitchatorn Santinatornkul","avatar":""},{"name":"Natruja Chutiwansopon","avatar":""},{"name":"Jennis Oprasert","avatar":""},{"name":"Kanteera Wadcharathadsanakul","avatar":""},{"name":"Isarapa Thawatpakdee","avatar":""},{"name":"Tanakorn Tiyanont","avatar":""},{"name":"Talay Sanguandikul","avatar":""},{"name":"Nont Worawat Boonchuen","avatar":""},{"name":"Peerapol Kijreunpiromsuk","avatar":""},{"name":"Gasab Jumpadib","avatar":""},{"name":"New Ph","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["ล้านวงโคจร The Series","ล้านวงโคจร"]', 1784690324158);
