INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rider-giao-hang-cho-ma', 'Rider: Giao Hàng Cho Ma', 'Rider: Ghost Delivery', 'https://phimimg.com/upload/vod/20250327-1/8c3c90cb4116331e55a299726edea4bb.jpg', 'https://phimimg.com/upload/vod/20250327-1/69fefc35691be577ad7738f9fa92c5dd.jpg', '<p>Một cuộc phiêu lưu ma quái của 3 tay đua giao hàng – NAT (Mario Maurer), KAI (Marut Chuensomboon) và YOD (Puwanet Seechompu). Việc giao hàng của 3 người bạn rất ổn vào ban ngày, nhưng ban đêm thì lại khác. Họ thường nhận được “những đơn hàng rùng rợn” với những chỉ dẫn bất thường và địa chỉ giao nhận là những ngôi nhà ma ám nổi tiếng. Những nhiệm vụ giao hàng đơn giản của họ thường biến thành những cuộc phiêu lưu đáng sợ tới những địa điểm kỳ lạ.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Thái Lan', 1, '[{"name":"Mario Maurer","avatar":""},{"name":"Freen Sarocha Chankimha","avatar":""},{"name":"Marut Chuensomboon","avatar":""},{"name":"Puwanet Seechompu","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324158);
