INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('rider-giao-hang-cho-ma', 'Rider: Giao Hàng Cho Ma', 'Rider: Ghost Delivery', 'rider: giao hàng cho ma rider: ghost delivery mario maurer freen sarocha chankimha marut chuensomboon puwanet seechompu ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-thuong', 'Bắc Thượng', 'Northward', 'https://phimimg.com/upload/vod/20250303-1/b96006ef4b81a10728e82b5a85bc565d.jpg', 'https://phimimg.com/upload/vod/20250303-1/8c74719be507483a90c07a5193874fab.jpg', '<p>Bắc Thượng là một bộ phim hiện đại do đạo diễn chính là Diêu Hiểu Phong, người đã đạo diễn bộ phim nổi tiếng (&quot;Cùng Nhau&quot;) và Chu Nam, đạo diễn của &quot;Đại Tống Thiếu Niên Chí 2,&quot; đảm nhiệm vai trò đạo diễn phụ. Bạch Lộc (trong &quot;Cảnh Sát Vinh Dự&quot;) và u Hào (trong &quot;Mãn Giang Hồ&quot;) là hai diễn viên chính của bộ phim. Phim dựa trên cuốn tiểu thuyết cùng tên của nhà văn Từ Tức Thần, người đã giành giải thưởng văn học Mao Đồng năm 2019. Câu chuyện xoay quanh một nhóm nam nữ thanh niên đã lớn lên cùng nhau, rồi sau nhiều năm tái ngộ tại phố Hoa Gia, một nơi xa lạ với quá khứ. Qua hành trình đối mặt với cạm bẫy và áp lực cuộc sống, họ tìm thấy hy vọng mới. Bằng cái nhìn của những thanh niên Giang Nam này, khán giả không chỉ được chứng kiến sự phát triển của họ mà còn cảm nhận được sự biến đổi của Đại Vận Hà, từ thời kỳ đình trệ đến hồi sinh mới, là một phần của lịch sử giàu có và sâu sắc của văn hóa kênh đào Trung Quốc trong suốt hơn một thế kỷ.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 12, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Bạch Lộc","avatar":""},{"name":"Âu Hào","avatar":""},{"name":"Trạch Tử Lộ","avatar":""},{"name":"Cao Chí Đình","avatar":""},{"name":"Lý Uyển Đạt","avatar":""},{"name":"Lưu Hằng Phủ","avatar":""},{"name":"Hồ Quân","avatar":""},{"name":"Lý Nãi Văn","avatar":""},{"name":"Nhạc Dương","avatar":""},{"name":"Tề Hoan","avatar":""},{"name":"Lưu Vi Vi","avatar":""},{"name":"Đồng Lôi","avatar":""},{"name":"Đồ Lăng","avatar":""},{"name":"Lưu Mẫn","avatar":""},{"name":"Chu Thiết","avatar":""},{"name":"Sở Toàn Trung","avatar":""},{"name":"Vương Học Kỳ","avatar":""},{"name":"Tát Nhật Na.","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bei Shang","Northward","北上"]', 1784690324158);
