INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bac-thuong', 'Bắc Thượng', 'Northward', 'bắc thượng northward bạch lộc âu hào trạch tử lộ cao chí đình lý uyển đạt lưu hằng phủ hồ quân lý nãi văn nhạc dương tề hoan lưu vi vi đồng lôi đồ lăng lưu mẫn chu thiết sở toàn trung vương học kỳ tát nhật na. bei shang northward 北上', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghe-sieu-kho-noi', 'Nghề Siêu Khó Nói', 'Forbidden Fairytale', 'https://phimimg.com/upload/vod/20250301-1/8d181b81cc1b4f5596bd4187254b23a2.jpg', 'https://phimimg.com/upload/vod/20250301-1/a2430d25cb0b208fca887368aa81ac8d.jpg', '<p>Dan-bi vốn mơ ước trở thành một tác giả truyện thiếu nhi, nhưng trớ trêu thay, cô lại khởi đầu sự nghiệp tại Đội Bảo vệ Thanh thiếu niên, nơi chuyên kiểm duyệt nội dung khiêu dâm bất hợp pháp. Một ngày nọ, Dan-bi vô tình gây ra tai nạn và phải bồi thường một khoản tiền khổng lồ cho CEO Hwang – ông trùm trong ngành văn học mạng 18+. Từ đây, cô buộc phải ký thỏa thuận viết truyện người lớn để trả nợ. Vốn chưa từng viết truyện người lớn, Dan-bi gặp đủ tình huống dở khóc dở cười. Nhưng nhờ sự cổ vũ của đồng nghiệp Jung-seok - người đang vật lộn với chứng khó “lên”, và nhờ vốn sống phong phú từ hội bạn thân mê buôn chuyện giường chiếu, cô bỗng phát hiện ra tài năng sáng tác thiên phú mà chính mình cũng không ngờ tới…</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"Park Ji-hyun","avatar":""},{"name":"Choi Si-won","avatar":""},{"name":"Sung Dong-il","avatar":""},{"name":"Park Geon-il","avatar":""},{"name":"Hwang Se-on","avatar":""},{"name":"Seol Woo-in","avatar":""},{"name":"Park Cheol-min","avatar":""},{"name":"Kim Young-ah","avatar":""},{"name":"Lee Si-el","avatar":""},{"name":"Nam Joong-gyu","avatar":""},{"name":"Lee Jung-hyoung","avatar":""},{"name":"Gwag Ja-hyeong","avatar":""},{"name":"Kim Chang-hwan","avatar":""},{"name":"Hwang Hyun-bin","avatar":""},{"name":"Moon Jin-seung","avatar":""},{"name":"Choi Jae-hee","avatar":""},{"name":"Park Ho-san","avatar":""},{"name":"Kim Seo-ra","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Forbidden Fairytale","어른동화","동화지만 청불입니다"]', 1784690324158);
