INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-du-hang-ma-truyen-khoai-hoat-thanh', 'Tây Du Hàng Ma Truyện: Khoái Hoạt Thành', 'Journey to the West: The Helltown of Heaven', 'https://phimimg.com/upload/vod/20250326-1/341bd917d8e8de81d0a82f30a5bb01a7.jpg', 'https://phimimg.com/upload/vod/20250326-1/988aa1859f6b1e5be190b525e36dfd89.jpg', '<p>Tại tòa nhà Hoa Viễn, quản lý sảnh Tô Tiểu Ninh đang trong giai đoạn quan trọng để trở thành nhân viên chính thức. Cùng lúc đó, chàng trai trẻ tài năng Kỷ Dục Hành, làm việc tại tầng 17, là nhân viên cốt cán đang nổi bật trong công việc. Họ có cùng nhu cầu là nhanh chóng kết hôn, và thế là hai con đường song song bắt đầu giao nhau. Trong mắt Đồ Tiểu Ninh, Kỷ Dục Hành là người bạn đời lý tưởng vượt xa mong đợi, còn trong mắt Kỷ Dục Hành, Đồ Tiểu Ninh là ánh sáng đã từng chiếu rọi cuộc đời anh, kết hôn với cô là sự lựa chọn duy nhất mà anh kiên định. Sau khi cả hai vừa đủ dũng khí để xác nhận quan hệ hôn nhân, Kỷ Dục Hành bất ngờ trở thành cấp trên của Đồ Tiểu Ninh. Họ, những người bạn học từ mười năm trước, giờ đây lại tình cờ có mối quan hệ công việc và vợ chồng, cùng nhau khám phá ý nghĩa của hôn nhân và cuộc sống.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Eric Hsiao","avatar":""},{"name":"Liu Sichen","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["西游降魔篇之快活城"]', 1784690324158);
