INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-khong-ton-tai', 'Ngày Không Tồn Tại', 'The 8th Day', 'https://phimimg.com/upload/vod/20250326-1/0d20868c687d59c27ab991bea3d66457.jpg', 'https://phimimg.com/upload/vod/20250326-1/28fec3613ddfa91bfc9f5e921ef6ad35.jpg', '<p>Cốt truyện theo chân một người phụ nữ đang vật lộn với nỗi đau mất con, và cô được trao cơ hội trải nghiệm lại &quot;ngày thứ 8&quot; — ngày cuối cùng cô ở bên con mình. Trong quá trình đó, cô phải đối mặt với câu hỏi đạo đức về việc liệu có nên thay đổi quá khứ và can thiệp vào số phận.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Phoebe Tonkin","avatar":""},{"name":"Darren Mann","avatar":""},{"name":"Mustafa Speaks","avatar":""},{"name":"Alexis Berent","avatar":""},{"name":"Valerie Mahaffey","avatar":""},{"name":"Lindsey Morgan","avatar":""},{"name":"Melissa Chambers","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324158);
