INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-thu-jones-suy-vi-anh', 'Tiểu Thư Jones: Suy Vì Anh', 'Bridget Jones: Mad About the Boy', 'https://phimimg.com/upload/vod/20250325-1/36557a78dd3b9c2caeb9115fd7b95e46.jpg', 'https://phimimg.com/upload/vod/20250325-1/7ac315d57aec8158bafd31fd504f1d3a.jpg', '<p>Tiểu thư Jones đối mặt với cuộc sống là một góa phụ và mẹ đơn thân, nhận sự hỗ trợ từ gia đình và bạn bè. Cô trở lại với công việc và tìm kiếm những mối quan hệ mới qua các ứng dụng hẹn hò.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Renée Zellweger","avatar":""},{"name":"Chiwetel Ejiofor","avatar":""},{"name":"Leo Woodall","avatar":""},{"name":"Hugh Grant","avatar":""},{"name":"Jim Broadbent","avatar":""},{"name":"Gemma Jones","avatar":""},{"name":"Colin Firth","avatar":""},{"name":"Sarah Solemani","avatar":""},{"name":"Josette Simon","avatar":""},{"name":"Nico Parker","avatar":""},{"name":"Mila Jankovic","avatar":""},{"name":"Casper Knopf","avatar":""},{"name":"Leila Farzad","avatar":""},{"name":"Shirley Henderson","avatar":""},{"name":"James Callis","avatar":""},{"name":"Sally Phillips","avatar":""},{"name":"Celia Imrie","avatar":""},{"name":"Neil","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["BJ單身日記：戀上小鮮肉","Бриджит Джонс. Без ума от мальчишки","Tiểu Thư Jones: Suy Vì Anh","Bridget Jones: Mad About the Boy"]', 1784690324158);
