INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-me-lua-dao', 'Bà Mẹ Lừa Đảo', 'Con Mum', 'https://phimimg.com/upload/vod/20250325-1/f95c077c757ca8fbc3e7c0384f2764a0.jpg', 'https://phimimg.com/upload/vod/20250325-1/53e10531d6cdca1646ccb64ceee264c6.jpg', '<p>Triệu phú. Kẻ thao túng. Mẹ? Liệu bà lão Dionne 85 tuổi có thực sự đang tìm kiếm đứa con trai thất lạc từ lâu – hay chỉ đang thực hiện một màn lừa gạt đỉnh cao?</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["我被妈妈诈骗了","我被媽媽詐騙了","Svindlet af mor","Con Mum"]', 1784690324159);
