INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ba-me-lua-dao', 'Bà Mẹ Lừa Đảo', 'Con Mum', 'bà mẹ lừa đảo con mum  我被妈妈诈骗了 我被媽媽詐騙了 svindlet af mor con mum', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kho-do-danh', 'Khó Dỗ Dành', 'The First Frost', 'https://phimimg.com/upload/vod/20250218-1/397055acaa0da79ba975b51df4dbf50f.jpg', 'https://phimimg.com/upload/vod/20250218-1/7812aa97a4c6bfdd29e1bc33386b72e1.jpg', '<p>Phim kể về chuyện tình đầy trắc trở của đôi bạn trẻ Ôn Dĩ Phàm và Tang Diên khi họ phải yêu đi yêu lại và đối mặt với những rào cản mà đối với nhiều người có thể là sẽ phải sớm buông tay. Ôn Dĩ Phàm là một cô gái trẻ trung, nhiệt huyết và luôn khao khát khám phá những điều mới mẻ, tình đầu của cô là Tang Diên, một anh chàng khá điển trai và phong lưu.

Tuy nhiên mọi thứ quay ngoắt lại và họ phải chia tay để mỗi người bước đi trên con đường của riêng mình. Cho đến khi gặp lại ở một bán bar, họ vờ như không nhận ra nhau, thử lòng nhau và cũng muốn bắt đầu thêm một lần nữa. Khi mà cả Ôn Dĩ Phàm và Tang Diên nhận ra được tình cảm của mình là hoàn toàn chân thật thì họ lại một lần nữa vướng phải những rào cản từ phía gia đình và cả công việc. Cuối cùng thì họ nhận ra rằng chỉ tình yêu đích thực mới đưa họ vượt qua được những rào cản và có thể đến với nhau một cách bền vững nhất.</p>', 'Hoàn Tất (32/32)', 32, 'series', 'completed', 26, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Bạch Kính Đình","avatar":""},{"name":"Chương Nhược Nam","avatar":""},{"name":"Trần Hạo Sâm","avatar":""},{"name":"Trương Miểu Di","avatar":""},{"name":"Trạch Tiêu Văn","avatar":""},{"name":"Nguyên Dã","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '["A Primeira Geada","Nan Hong","难哄","วันนี้ วันไหน ยังไงก็เธอ","The First Frost"]', 1784690324159);
