INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('kho-do-danh', 'Khó Dỗ Dành', 'The First Frost', 'khó dỗ dành the first frost bạch kính đình chương nhược nam trần hạo sâm trương miểu di trạch tiêu văn nguyên dã a primeira geada nan hong 难哄 วันนี้ วันไหน ยังไงก็เธอ the first frost', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vu-ai-thien-kim', 'Vũ Ái Thiên Kim', 'Rainkissed Fate', 'https://phimimg.com/upload/vod/20250216-1/32aedcea25f6393afe51aecbd672761d.jpg', 'https://phimimg.com/upload/vod/20250216-1/a4e4027e07bfcab0469fda96f2b9e379.jpg', '<p>Lãng mạn, tâm lý xoay quanh câu chuyện đầy kịch tính giữa một thiên kim tiểu thư và một võ sĩ quyền anh, khi định mệnh buộc họ phải đối mặt với quá khứ và sự thật bị chôn vùi.

Bộ gia thiên kim Bước Ngôn bị kẻ khác hãm hại, khiến cô qua đêm với võ sĩ quyền anh Hà Vũ Thần. Ngay sau đó, cô biến mất không dấu vết. Sáu năm sau, Bước Ngôn quay trở lại cùng cặp song sinh một trai một gái, bất ngờ gặp lại Hà Vũ Thần – người đàn ông năm xưa nay đã sa sút tinh thần sau bê bối dàn xếp trận đấu.

Vì muốn ghép tủy dây rốn cho con trai, Bước Ngôn quyết định lợi dụng Hà Vũ Thần và cùng anh ký kết một cuộc hôn nhân hợp đồng. Tuy nhiên, trong quá trình sống chung, cả hai dần nhận ra tình cảm thật sự dành cho nhau. Đồng thời, họ cũng từng bước vén màn những bí mật đen tối trong quá khứ, tìm ra kẻ đứng sau mọi âm mưu tàn nhẫn năm xưa.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Phương Đồng","avatar":""},{"name":"Đại Cao Chính","avatar":""},{"name":"Phạm Hiểu Đông","avatar":""},{"name":"Trương Hinh Nguyệt","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yu Ai Qian Jin","金生雨你","우애천금 : 하룻밤의 남자","雨爱千金"]', 1784690324159);
