INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-ong-chu', 'Tình Yêu Ông Chú', 'Ossan''s Love Thailand', 'https://phimimg.com/upload/vod/20250107-1/458c41bf6b63b24a42df8e9005a483c3.jpg', 'https://phimimg.com/upload/vod/20250107-1/a9b16a838e3be46f01987d65d6ef21c4.jpg', '<p>Chuyên viên tư vấn bất động sản xui xẻo, Heng, đột ngột thấy thế giới của mình đảo lộn khi anh bị cuốn vào một mối tình tay ba hỗn loạn.&nbsp; Sếp của anh, Kongdech, và đồng nghiệp kiêm bạn cùng phòng, Mo, đều nảy sinh tình cảm với anh, khiến cuộc sống của anh rơi vào hỗn loạn. Để làm cho mọi thứ trở nên phức tạp hơn, người bạn thời thơ ấu Chicha của anh bất ngờ cũng thú nhận tình yêu của cô dành cho anh. Giữa vòng xoáy cảm xúc và những mối quan hệ rối rắm này, cuối cùng ai sẽ chiếm được trái tim của Heng?</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Pirapat Watthanasetsiri","avatar":""},{"name":"Sahaphap Wongratch","avatar":""},{"name":"Shahkrit Yamnarm","avatar":""},{"name":"Thinnaphan Tantui","avatar":""},{"name":"Nachcha Chuedang","avatar":""},{"name":"Phudtripart Bhudthonamochai","avatar":""},{"name":"Nattharat Kornkaew","avatar":""},{"name":"Ploynira Hiruntaveesin","avatar":""},{"name":"Warinda Damrongphol","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["大叔的爱 泰版","OSSAN''S LOVE TH","OLT","OSSAN''S LOVE THAILAND","おっさんずラブ","Rak Ni Hai \"Nai\"","大叔的愛(泰國版)","大叔的愛（泰國版）","大叔的愛 泰國版","大叔的愛泰國版","รักนี้ให้ \"นาย\""]', 1784690324159);
