INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-mat-tinh-yeu-noi-cong-so', 'Bí Mật Tình Yêu Nơi Công Sở', 'I Have A Crush At Work', 'https://phimimg.com/upload/vod/20250114-1/871a3848e824974cd3dc1acf6e1ca562.jpg', 'https://phimimg.com/upload/vod/20250114-1/107ecbe89131438076d148eec542fd0f.jpg', '<p>Yui Mitsuya và Masugu Tateishi không chỉ là đồng nghiệp bình thường mà họ hoàn toàn có tình cảm với nhau. Thái độ hướng dẫn nhưng khiêm tốn của anh khiến cô phát cuồng, và vẻ dễ thương của cô lại khiến anh mỉm cười như một kẻ ngốc. Vấn đề là, họ đang cố gắng giữ cho mối quan hệ mới này bí mật để tránh làm cho công việc trở nên khó xử. Nhưng khi họ không thể kiềm chế được sự quan tâm đối với nhau, họ đang rủi ro tiết lộ bí mật nhỏ của mình qua từng ngày làm việc tại văn phòng.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Seiichiro Yamashita","avatar":""},{"name":"Yume Miyamoto","avatar":""},{"name":"Shizuka Itoh","avatar":""},{"name":"Reiou Tsuchida","avatar":""},{"name":"You Taichi","avatar":""},{"name":"Misaki Watada","avatar":""},{"name":"Sora Tokui","avatar":""},{"name":"Kentaro Tone","avatar":""},{"name":"Kensho Ono","avatar":""},{"name":"Shin-ichiro Miki","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["这家公司里有我喜欢的人","Kono Kaisha ni Suki na Hito ga Imasu","У цій компанії є людина, в яку закоханий","Can You Keep a Secret?","この会社に好きな人がいます"]', 1784690324159);
