INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-thu-dau-yeu', 'Kẻ Thù Dấu Yêu', 'My Dearest Nemesis', 'https://phimimg.com/upload/vod/20250217-1/9685d26503cd6102a3b3ef7f84773f14.jpg', 'https://phimimg.com/upload/vod/20250217-1/3102759f9632289009b73ad5158a51fc.jpg', '<p>Kẻ Thù Dấu Yêu là hành trình nối lại tình xưa của cặp oan gia Baek Su Jeong và Ban Ju Yeon. Thời học sinh, họ quen nhau qua một trò chơi trực tuyến rồi dần dần nảy sinh tình cảm, nhưng sau cùng lại đường ai nấy đi trong cay đắng. 16 năm sau, họ bất ngờ gặp lại trong cương vị mới. Ju Yeon là ông chủ lạnh lùng, còn Su Jeong là cô nhân viên cấp dưới đầy nhiệt huyết. Đứng giữa tình cảm cũ lẫn cảm xúc mới, liệu họ có thể vượt qua quá khứ để cùng nhau tiến về phía trước hay không?</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 5, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Mun Ka-young","avatar":""},{"name":"Choi Hyun-wook","avatar":""},{"name":"Lim Se-mi","avatar":""},{"name":"Kwak Si-yang","avatar":""},{"name":"Kim Young-ah","avatar":""},{"name":"Ban Hyo-jung","avatar":""},{"name":"Ko Chang-seok","avatar":""},{"name":"Lim Young-joo","avatar":""},{"name":"Kim Woo-kyum","avatar":""},{"name":"Son Sang-yeon","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["那家伙是黑炎龙","그 남자는 흑염룡","عدوي العزيز","That Guy is a Black Flame Dragon","Black Salt Dragon","That Man Is Black Salt Dragon","그놈은 흑염룡"]', 1784690324159);
