INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-tho-cuoi-cung', 'Hơi Thở Cuối Cùng', 'Last Breath', 'https://phimimg.com/upload/vod/20250324-1/ce210f776fb9205f79f4b8747591fe80.jpg', 'https://phimimg.com/upload/vod/20250324-1/40341f587d59fa59eb51286f7854824a.jpg', '<p>Dựa trên câu chuyện có thật về một tai nạn lặn biển sâu xảy ra vào năm 2012. Câu chuyện xoay quanh Chris Lemons (do Finn Cole thủ vai), một thợ lặn trẻ làm việc trong một đội lặn bão hòa ở Biển Bắc. Trong một nhiệm vụ bảo trì đường ống dưới đáy biển, hệ thống định vị của tàu hỗ trợ bị hỏng, khiến Chris bị mắc kẹt ở độ sâu khoảng 91 mét, không có nguồn oxy dự trữ và không thể liên lạc với đội cứu hộ. Anh chỉ còn khoảng 10 phút oxy trong bình.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Woody Harrelson","avatar":""},{"name":"Simu Liu","avatar":""},{"name":"Finn Cole","avatar":""},{"name":"Cliff Curtis","avatar":""},{"name":"Mark Bonnar","avatar":""},{"name":"MyAnna Buring","avatar":""},{"name":"Josef Altin","avatar":""},{"name":"Bobby Rainsbury","avatar":""},{"name":"Connor Reed","avatar":""},{"name":"Nick Biadon","avatar":""},{"name":"Riz Khan","avatar":""},{"name":"Aldo Silvio","avatar":""},{"name":"Kevin Naudi","avatar":""},{"name":"Claudiu Baciu","avatar":""},{"name":"Brett Murray","avatar":""},{"name":"Muhammad Arnini Bin Ariffin","avatar":""},{"name":"Yaroslav Musii","avatar":""},{"name":"Ramon Cam","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["最后的呼吸","Son Nəfəs","窒息倒數","Prisonnier des Abysses","Last Breath","النفس الأخير","一息尚存","5 Minuten bis zum unwürdigsten Tod","O Último Suspiro","300呎窒息倒數"]', 1784690324159);
