INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoi-tho-cuoi-cung', 'Hơi Thở Cuối Cùng', 'Last Breath', 'hơi thở cuối cùng last breath woody harrelson simu liu finn cole cliff curtis mark bonnar myanna buring josef altin bobby rainsbury connor reed nick biadon riz khan aldo silvio kevin naudi claudiu baciu brett murray muhammad arnini bin ariffin yaroslav musii ramon cam 最后的呼吸 son nəfəs 窒息倒數 prisonnier des abysses last breath النفس الأخير 一息尚存 5 minuten bis zum unwürdigsten tod o último suspiro 300呎窒息倒數', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-cuu-xich-huyet', 'Giải Cứu Xích Huyết', 'Red Blood Rescue', 'https://phimimg.com/upload/vod/20250324-1/09be8edccd3b86c53108ff08c5fccf50.jpg', 'https://phimimg.com/upload/vod/20250324-1/22955626b4631992c440f08274b77439.jpg', '<p>Võ sĩ quyền anh Giang Ly sống trong day dứt và hối hận sau khi mất vợ con, ngày ngày chỉ biết dựa vào việc đấu quyền mưu sinh. Cho đến khi lưu lạc đến nước K và gặp cô bé hàng xóm Tiểu Chân, trong quá trình quen biết và gắn bó, anh dần tìm lại được hy vọng và ánh sáng trong cuộc đời. Nhưng khi Tiểu Chân bị bắt cóc, Giang Ly vực dậy tinh thần, được sức mạnh của tình thân tiếp thêm ý chí, dùng lòng quả cảm đơn độc lao vào một cuộc giải cứu đầy kịch tính, gay cấn như sấm sét bùng nổ.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jiang Yisheng","avatar":""},{"name":"Shao Feng","avatar":""},{"name":"Zeng Chen","avatar":""},{"name":"Zhang Tianqi","avatar":""},{"name":"Zuo Tengyun","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["赤血营救"]', 1784690324159);
