INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('azaad', 'Azaad', 'Azaad', 'https://phimimg.com/upload/vod/20250324-1/93f35801b7c828c53c1ae29eb1105396.jpg', 'https://phimimg.com/upload/vod/20250324-1/669c5c53df7ec389905aa61d3b78beab.jpg', '<p>Lấy bối cảnh Ấn Độ những năm 1920, bộ phim kể về một cậu bé làm việc trong chuồng ngựa, vô tình tạo nên mối liên kết đặc biệt với một chú ngựa đầy sức sống. Giữa thời kỳ nổi loạn và áp bức, khát khao được cưỡi con tuấn mã ấy đã dẫn cậu bước vào hành trình của lòng dũng cảm — nơi cậu dần thức tỉnh trước cuộc đấu tranh giành tự do của dân tộc.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Ajay Devgn","avatar":""},{"name":"Aaman Devgan","avatar":""},{"name":"Rasha Thadani","avatar":""},{"name":"Diana Penty","avatar":""},{"name":"Mohit Malik","avatar":""},{"name":"Piyush Mishra","avatar":""},{"name":"Natasha Rastogi","avatar":""},{"name":"Sandeep Shikhar","avatar":""},{"name":"Jiya Amin","avatar":""},{"name":"Mukund Ramesh Pal","avatar":""},{"name":"Gaurav Yavanika","avatar":""},{"name":"Andrew Crouch","avatar":""},{"name":"Dylan Jones","avatar":""},{"name":"Rakesh Sharma","avatar":""},{"name":"Akshay Anand","avatar":""},{"name":"Alok Kumar","avatar":""},{"name":"Jagannath Seth","avatar":""},{"name":"Khusboo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["आज़ाद"]', 1784690324159);
