INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-pursuit-of-lust', 'Ám Ảnh Dục Vọng', 'The Pursuit Of Lust', 'https://phimimg.com/upload/vod/20250323-1/82db373e7b7537876f46bc89b9db127c.jpg', 'https://phimimg.com/upload/vod/20250323-1/e26ccd124fbc3b4c7b02c49a7573d7cb.jpg', '<p>Nữ diễn viên Mông Cổ quyến rũ E. Khandmaa đảm nhận vai chính trong bộ phim tình cảm lãng mạn này, xoay quanh câu chuyện của một người vợ nội trợ đang khao khát những cảm xúc yêu đương mà người chồng lạnh nhạt của cô không thể mang lại. Mọi chuyện bắt đầu thay đổi khi một đối tác làm ăn của chồng cô dần dần không thể cưỡng lại sức hấp dẫn và khao khát cháy bỏng từ cô.</p>', 'Full', 1, 'single', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Mongolia', 0, '[{"name":"STEPINSTONE","avatar":""},{"name":"E.KHANDMAA","avatar":""},{"name":"E.BATKHULEG","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Дур тачаалын эрэлд"]', 1784690324159);
