INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ac-thu', 'Ác Thú', 'Nemesis', 'https://phimimg.com/upload/vod/20250323-1/a840352c67260ab0a25be839ba4720f7.jpg', 'https://phimimg.com/upload/vod/20250323-1/71f3e88cffc19860626022f5fb864bae.jpg', '<p>Trong giải đua xe lớn tại thành Phượng Hoàng, con quái thú khổng lồ Vũ La vốn đã biến mất suốt 20 năm bất ngờ tái xuất, mang đến sự tàn phá và nỗi kinh hoàng cho toàn thành phố. Thiên tài đua xe trẻ tuổi Trương Tiểu Tảo cùng nhóm bốn người của mình liều lĩnh tấn công Vũ La khi nó bị thương, nhưng lại vô tình kích động một thảm họa nghiêm trọng hơn. Giữa những đòn giáng mạnh mẽ của số phận, dưới sự giúp đỡ và khích lệ của chuyên gia vũ khí Lại Đạo Trương, Trương Tiểu Tảo lấy lại lòng tin, trưởng thành và trở thành anh hùng mới của thành phố.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ma Yang","avatar":""},{"name":"Zhang Xin","avatar":""},{"name":"李梦洁","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["恶兽"]', 1784690324159);
