INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tru-phi', 'Trừ Phỉ', 'Beat The Tiger', 'https://phimimg.com/upload/vod/20250317-1/3b5a094859428b5f1b1115882f0b97ca.jpg', 'https://phimimg.com/upload/vod/20250317-1/5106a5cfcb43d7d2ecda55481d88b593.jpg', '<p>Phim được chuyển thể từ tiểu thuyết &quot;Rừng Sâu Tuyết Trắng&quot; của nhà văn hiện đại Khúc Ba, kể về hành trình chiến đấu quả cảm của một phân đội thuộc Quân Giải phóng Dân chủ Đông Bắc. Dưới sự chỉ huy của Tham mưu trưởng Thiếu Kiếm Ba, họ dấn thân vào vùng rừng sâu tuyết phủ để thực hiện nhiệm vụ tiêu diệt bọn thổ phỉ. Trong đó, trung đội trưởng trinh sát Dương Tử Vinh trải qua muôn vàn hiểm nguy như &quot;một mình vào hang cọp&quot;, đấu trí bằng mật ngữ, vượt qua những chướng ngại chết người... Anh cùng đồng đội đã đấu trí, đấu dũng với bọn cướp do Tọa Sơn Điêu cầm đầu ở núi Uy Hổ, viết nên một khúc tráng ca anh hùng giữa núi rừng tuyết trắng.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Su Ke","avatar":""},{"name":"Zhao Bingrui","avatar":""},{"name":"Rain","avatar":""},{"name":"Zhang Chunzhong","avatar":""},{"name":"Shi Yuanting","avatar":""},{"name":"Yang Xi","avatar":""},{"name":"Rong Erjia","avatar":""},{"name":"Liu Bo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["除匪"]', 1784690324159);
