INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('buoc-chan-dung-cam', 'Bước Chân Dũng Cảm', 'The Unbreakable Boy', 'https://phimimg.com/upload/vod/20250320-1/4a60f45fbe6fad0837748a4b3fde57fb.jpg', 'https://phimimg.com/upload/vod/20250320-1/2969b7bae0a7ae5998cee9228b94d9bd.jpg', '<p>Một cậu bé mắc phải bệnh xương thủy tinh hiếm gặp cùng bệnh tự kỷ. Thế nhưng điều khiến cậu trở nên đặc biệt chính là cách nhìn nhận thế giới đầy niềm tin và hy vọng đã thay đổi và gắn kết những người xung quanh cậu.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Zachary Levi","avatar":""},{"name":"Gavin Warren","avatar":""},{"name":"Jacob Laval","avatar":""},{"name":"Amy Acker","avatar":""},{"name":"Meghann Fahy","avatar":""},{"name":"Bruce Davis","avatar":""},{"name":"Kellen Martelli","avatar":""},{"name":"Roy Jackson Miller","avatar":""},{"name":"Elle Adler","avatar":""},{"name":"Patricia Heaton","avatar":""},{"name":"Drew Powell","avatar":""},{"name":"Todd Terry","avatar":""},{"name":"Peter Facinelli","avatar":""},{"name":"Liza Marie Gonzalez","avatar":""},{"name":"Arianne Martin","avatar":""},{"name":"Kurt Yue","avatar":""},{"name":"Eric Starkey","avatar":""},{"name":"Pilot B","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Invencible: Un niño fuera de serie","坚不可摧的男孩","Nesalomljivi dječak","Minu eriline poeg","Il bambino di cristallo","Mano ypatingas sūnus","Jeden na milion","Bước Chân Dũng Cảm","The Unbreakable Boy"]', 1784690324159);
