INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doat-vo', 'Đoạt Vợ', 'Stolen Love', 'https://phimimg.com/upload/vod/20250115-1/ba95d9a87c955456a8d17731721ee1eb.jpg', 'https://phimimg.com/upload/vod/20250115-1/47e3af74b37e900af5c912db0af71fe1.jpg', '<p>Tướng quân trẻ tuổi hào nhoáng Tiêu Sở Dực và cô gái mồ côi Lục Vân Hi vốn là thanh mai trúc mã, sau khi thành hôn lại càng ân ái bên nhau. Nào ngờ Tiêu Sở Dực lại bị đày đến biên cương, thập tử nhất sinh vì tội cướp dâu, đến khi trở về lại hay tin Vân Hi đã tái giá với biểu ca Châu Ngạn Ngọc, mẫu thân qua đời. Yêu hận đan xen, Tiêu Sở Dực và Lục Vân Hi rơi vào một mối quan hệ tình cảm giằng xé đầy cấm kỵ.</p>', 'Hoàn Tất (42/42)', 42, 'series', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Mộc Thần","avatar":""},{"name":"Chu Tuấn Vĩ","avatar":""},{"name":"Từ Hạo Tường","avatar":""},{"name":"Hồ Nghiên Nghiên","avatar":""},{"name":"Tống Nhất Hùng","avatar":""},{"name":"Hách Minh Kỳ","avatar":""},{"name":"Vu Ất","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Take by Force","夺娶"]', 1784690324159);
