INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('treu-nham-sac-son', 'Trêu Nhầm Sắc Son', 'The Prisoner Of Love', 'https://phimimg.com/upload/vod/20250307-1/2f249d88985e26bd8a8fe9d9865a4d3e.jpg', 'https://phimimg.com/upload/vod/20250307-1/364aa8fac1da2c76c1d92b3622416be9.jpg', '<p>Công chúa Tiêu Ninh Vân của nước Thiên Vân chịu cảnh nước mất nhà tan, phải làm huyết nô, được Đoan vương Trần Phong Tuyết của Đại Lương mua về. Vì mối hận thù trong quá khứ, Trần Phong Tuyết hành hạ Tiêu Ninh Vân thậm tệ. Nhưng trong khi lợi dụng nàng, hắn lại vô tình bị nàng thu hút lúc nào không hay. Hai người trải qua rất nhiều gian nan, sau khi gỡ bỏ hiểu lầm đã thổ lộ tình cảm, cuối cùng nắm tay nhau ẩn cư nơi núi rừng.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Minh Nguyên","avatar":""},{"name":"Chu Lệ Nham","avatar":""},{"name":"Triệu Hi Nguyệt","avatar":""},{"name":"Đổng Tử Minh","avatar":""},{"name":"Châu Hằng Vũ","avatar":""},{"name":"Lý Chinh","avatar":""},{"name":"Vương Chiêu","avatar":""},{"name":"Thôi Địch","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Cuo Re Yan Zhi Se","画心为牢","错惹胭脂色"]', 1784690324159);
