INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('am-huong-lai', 'Ám Hương Lai', 'Scent Of New Dawn', 'https://phimimg.com/upload/vod/20250202-1/a55e3a4ab064ca11047069866b3fce28.jpg', 'https://phimimg.com/upload/vod/20250202-1/cd935e96ec0ee8155940db638e2d5511.jpg', '<p>Gia tộc điều chế hương hàng đầu Giang Thành bị quản gia phóng hỏa chiếm đoạt tài sản, cô gái mồ côi Lâm Uyển Nguyệt ẩn mình nhiều năm, trở về để trả thù. Cô tình cờ tái ngộ với Trương Hàn Ý, con trai của quản gia. Hai người hợp sức trả thù, đấu đá trong gia tộc và cạnh tranh trên thương trường. Từ tiểu viện nghèo nàn, họ từng bước vươn lên đến đỉnh cao của ngành thương mại, cùng nhau vượt qua muôn vàn khó khăn, đối đầu với kẻ thù và cả số phận.</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lâm Trạch Huy","avatar":""},{"name":"Thang Gia Văn","avatar":""},{"name":"Hồ Bác Văn","avatar":""},{"name":"Lưu Tích Minh","avatar":""},{"name":"Mục Lạc Ân","avatar":""},{"name":"Tăng Hi Đường","avatar":""},{"name":"Triệu Tịch Tịch","avatar":""},{"name":"Mã Kỳ Văn","avatar":""},{"name":"Giả Thư Di","avatar":""},{"name":"Lưu Yến Kiều","avatar":""},{"name":"Phùng Hi Nghiêu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["An Xiang Lai","The Scent of Secret","암향래 : 복수의 향기","暗香来"]', 1784690324159);
