INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('am-huong-lai', 'Ám Hương Lai', 'Scent Of New Dawn', 'ám hương lai scent of new dawn lâm trạch huy thang gia văn hồ bác văn lưu tích minh mục lạc ân tăng hi đường triệu tịch tịch mã kỳ văn giả thư di lưu yến kiều phùng hi nghiêu an xiang lai the scent of secret 암향래 : 복수의 향기 暗香来', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-than-quen', 'Cô Gái Thân Quen', 'Wild Rose', 'https://phimimg.com/upload/vod/20250310-1/2205b50ac6926b19f6b91beda26daaa9.jpg', 'https://phimimg.com/upload/vod/20250310-1/6d7741091e8afee11dcdfe0181c121d5.jpg', '<p>Để trả mối thù giết mẹ và cướp gia tộc mà cô chủ sa cơ Trình Hựu Nhiên đã thay đổi gương mặt, che giấu danh tính, mượn thân phận của người bạn thân Tô Tâm Duyệt để giả vờ đính hôn với Hứa Thời An, người thừa kế tập đoàn Tinh Vân và cũng là con trai của kẻ thù giết mẹ cô. Trong quá trình cô thu thập chứng cứ, Hứa Thời An dần phát hiện danh tính thực sự của Trình Hựu Nhiên. Thế nhưng thay vì vạch trần, anh lại lặng lẽ bảo vệ và âm thầm giúp cô hoàn thành kế hoạch trả thù. Khi từng lớp bí ẩn được bóc trần, Trình Hựu Nhiên phát hiện kẻ chủ mưu thực sự đứng sau thảm kịch năm xưa lại là một người khác.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Cửu Lâm","avatar":""},{"name":"Chu Cận Đồng","avatar":""},{"name":"Vương Dữ","avatar":""},{"name":"Chu Mân Hân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shu Xi De Ta","熟悉的她"]', 1784690324159);
