INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-khi-sap-ly-hon', 'Yêu Khi Sắp Ly Hôn', 'Love In The Edge Of Divorce', 'https://phimimg.com/upload/vod/20250110-1/7c9b4c84fa1f1ecfcfdf953882485422.jpg', 'https://phimimg.com/upload/vod/20250110-1/bc02644bcebc707445731434e8f24a80.jpg', '<p>Một cuộc hôn nhân thương mại, sau ba năm, hai người chưa từng gặp mặt đều muốn chấm dứt cuộc hôn nhân không có tình yêu này. Trùng hợp thế nào nhiều lần hẹn gặp đều không thành công, nhưng một sự cố ngoài ý muốn lại khiến họ phát sinh quan hệ thân mật. Hai người gặp lại nhau, việc bày tỏ tình cảm sai cách càng khiến hiểu lầm giữa họ thêm sâu sắc. Khi biết được Thịnh Miên chính là Penny và đang mang thai, Phó Yến Thành vô cùng hối hận, tìm mọi cách để níu kéo. Cuối cùng, cả hai hóa giải hiểu lầm, nhận ra tình cảm chân thành và quyết định gắn bó trọn đời.</p>', 'Hoàn Tất (31/31)', 31, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Nhâm Thế Hào","avatar":""},{"name":"Lý Tinh Dao","avatar":""},{"name":"Lý Chi Phồn","avatar":""},{"name":"Sử Nhuế Y","avatar":""},{"name":"Chu Bái Thần","avatar":""},{"name":"Trang Cảnh Hàm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["애재이혼진행시 : 이혼했지만 이혼하기 싫어","爱在离婚进行时"]', 1784690324159);
