INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('yeu-khi-sap-ly-hon', 'Yêu Khi Sắp Ly Hôn', 'Love In The Edge Of Divorce', 'yêu khi sắp ly hôn love in the edge of divorce nhâm thế hào lý tinh dao lý chi phồn sử nhuế y chu bái thần trang cảnh hàm 애재이혼진행시 : 이혼했지만 이혼하기 싫어 爱在离婚进行时', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-the-tron-thoat', 'Không Thể Trốn Thoát', 'There Is No Place To Escape', 'https://phimimg.com/upload/vod/20250318-1/4393e3bbfb9f8e2688bd18911dfa7cb1.jpg', 'https://phimimg.com/upload/vod/20250318-1/b9c29a24192e5d3927988e0afdf80b9b.jpg', '<p>Hai vụ án mạng liên tiếp xảy ra, nạn nhân đều là nghi phạm trong vụ cướp tiệm vàng chấn động. Đây là kết cục của việc chia chác không đều dẫn đến tàn sát lẫn nhau, hay là luật trời công bằng, gieo gió gặt bão? Ông chủ tiệm vàng có biểu hiện bất thường sau vụ cướp, người vợ lại cố tình che giấu sự thật — liệu tất cả có liên quan đến một vụ tử vong bất ngờ khác? Một vụ cướp, hai vụ án mạng, ba người thiệt mạng — phía sau là những rối ren của lòng người và những mối quan hệ tình cảm chồng chéo. Nhưng dưới con mắt sắc bén của cảnh sát hình sự Phó Bắc Thần và chuyên gia &quot;Thiên Nhãn&quot; Đinh Pháp Nam, không tên tội phạm nào có thể trốn thoát. Cuối cùng, cả hai hợp sức phá tan âm mưu của tên phản diện lớn, bắt giữ toàn bộ nghi phạm, bảo vệ thành công tính mạng và tài sản của người dân thành phố Đông Phú.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dai Jingyao","avatar":""},{"name":"Xie Xin","avatar":""},{"name":"Liu Xinnian","avatar":""},{"name":"Zhao Bosong","avatar":""},{"name":"Ning Xiaohua","avatar":""},{"name":"Du Le","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wu Chu Dun Tao","Nowhere to Escape","There is No Place to Escape","无处遁逃"]', 1784690324159);
