INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phai-long-nang-phu-thuy', 'Phải Lòng Nàng Phù Thủy', 'The Witch', 'https://phimimg.com/upload/vod/20250217-1/f97e6a1a633ab32e79b454512c33da8b.jpg', 'https://phimimg.com/upload/vod/20250217-1/c0d38d5e0677e75b8508ba6ba929f8c4.jpg', '<p>Phim kể về câu chuyện của Mi Jeong (Roh Jeong Eui), một người phụ nữ bị gọi là phù thủy, và Dong Jin (Park Jin Young), một người đàn ông cố gắng khám phá những quy luật bất thường gây ra xui xẻo cho cô. Hành trình của Dong Jin khi theo đuổi sự thật về những bất hạnh đến với Mi Jeong đầy những sự kiện không thể lường trước, như một bánh xe định mệnh khổng lồ. Càng cố gắng khám phá bí ẩn xung quanh Mi Jeong, Dong Jin càng rơi vào sự hỗn loạn. Dù là một người được trang bị kiến thức khoa học và khả năng lý luận logic, anh vẫn cảm thấy bối rối trước những hiện tượng kỳ lạ không thể giải thích. Liệu Dong Jin có thể tìm ra bản chất của sự bất hạnh đang bao trùm Mi Jeong, và cứu rỗi cô ấy?</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jinyoung","avatar":""},{"name":"Roh Jeong-eui","avatar":""},{"name":"Lim Jae-hyeok","avatar":""},{"name":"Jang Hui-ryeong","avatar":""},{"name":"Jang Hye-jin","avatar":""},{"name":"Ahn Nae-sang","avatar":""},{"name":"Kwon Han-sol","avatar":""},{"name":"Joo Jong-hyuk","avatar":""},{"name":"Nam Joong-gyu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["魔女","마녀"]', 1784690324159);
