INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vung-im-lang', 'Vùng Im Lặng', 'Silent Zone', 'https://phimimg.com/upload/vod/20250318-1/796401a7d9f1506f049466b77254055c.jpg', 'https://phimimg.com/upload/vod/20250318-1/d03bcc82826a2ca3333f29fc8cd31c18.jpg', '<p>Trong thế giới hoang tàn sau đại dịch, ranh giới giữa sống và chết chỉ mong manh như một hơi thở. Cassius và Abigail - hai người sống sót đang tìm kiếm nơi trú ẩn an toàn thì họ tình cờ gặp một cặp đôi đang chờ đón đứa con đầu lòng, số phận của họ đan xen vào nhau trong cuộc hành trình đến &quot;thị trấn nổi&quot; - nơi được đồn đại là thiên đường cuối cùng của loài người.</p>', 'Full', 1, 'single', 'completed', 19, 2025, 'Vietsub', 'FHD', 'Quốc Gia Khác', 0, '[{"name":"Matt Devere","avatar":""},{"name":"Luca Papp","avatar":""},{"name":"Nikolett Barabas","avatar":""},{"name":"Declan Hannigan","avatar":""},{"name":"Alexis Latham","avatar":""},{"name":"Julian Krenn","avatar":""},{"name":"Roderick Hill","avatar":""},{"name":"Anders Grundberg","avatar":""},{"name":"Ágota Dunai","avatar":""},{"name":"Katia Bokor","avatar":""},{"name":"Harry Szovik","avatar":""},{"name":"Robert Jackson","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["サイレントゾーン　人類VSアンデッド","Silent Zone"]', 1784690324159);
