INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-bac-cuoi-cung', 'Canh Bạc Cuối Cùng', 'High Rollers', 'https://phimimg.com/upload/vod/20250318-1/9e27c35386cf15f55ce6422b15deb852.jpg', 'https://phimimg.com/upload/vod/20250318-1/eb220755c50fc8c54aa0b8ce7186be0a.jpg', '<p>Cốt truyện xoay quanh Mason Goddard (John Travolta), một siêu trộm đang tận hưởng cuộc sống mơ ước cùng đồng đội và người phụ nữ anh yêu, Amelia Decker (Gina Gershon). Tuy nhiên, khi kẻ thù không đội trời chung là Salazar bắt cóc Decker, Mason buộc phải thực hiện một vụ cướp sòng bạc gần như không thể để đổi lấy sự tự do của cô. Trong khi đó, anh phải đối mặt với các đối thủ tàn nhẫn khác của Salazar và sự truy đuổi gắt gao từ FBI, đặt cược tất cả để cứu Decker.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"John Travolta","avatar":""},{"name":"Gina Gershon","avatar":""},{"name":"Lukas Haas","avatar":""},{"name":"Quavo","avatar":""},{"name":"Kelly Greyson","avatar":""},{"name":"Joel Cohen","avatar":""},{"name":"Daniel Louis Rivas","avatar":""},{"name":"Natali Yura","avatar":""},{"name":"Joey Shear","avatar":""},{"name":"Jeff Sapp","avatar":""},{"name":"Demi Castro","avatar":""},{"name":"Wade Hammond","avatar":""},{"name":"Leslee Emmett","avatar":""},{"name":"Miller Garfinkel","avatar":""},{"name":"Faith Stowers","avatar":""},{"name":"Derrick Goodman Jr.","avatar":""},{"name":"Danny Pardo","avatar":""},{"name":"Abigail Spear","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Cash Out 2: High Rollers","Transação Perigosa 2","套现2：大赌客","کلاهبردارا