INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-da-da-da-da', 'Đá Đá Đá Đá Đá', 'Kick Kick Kick Kick', 'https://phimimg.com/upload/vod/20250208-1/61ba5ad8d22d3a56f86401c07462edf6.jpg', 'https://phimimg.com/upload/vod/20250208-1/d13afbba7b9dd1d1ff2b37a97d2d0163.jpg', '<p>Diễn viên Ji Jin-hee và cựu PD nổi tiếng Jo Young-sik cùng hợp tác để ra mắt một công ty nội dung với mục tiêu đạt 3 triệu người đăng ký.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ji Jin-hee","avatar":""},{"name":"Lee Kyoo-hyung","avatar":""},{"name":"Baek Ji-won","avatar":""},{"name":"Lee Min-jae","avatar":""},{"name":"Jeong Han-seol","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["킥킥킥킥"]', 1784690324159);
