INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nuoc-song-dai-ha', 'Nước Sông Đại Hà', 'The Source Of River', 'https://phimimg.com/upload/vod/20250228-1/cd07058600ceb59aad9b1ac900c619ee.jpg', 'https://phimimg.com/upload/vod/20250228-1/5e0b26692efe1cc50a97298dca82f2f0.jpg', '<p>Năm 2012, Trịnh Hạo là trụ cột của Cục Thanh tra Thuế thành phố Tân Đông. Khi anh đang bàn chuyện kết hôn với bạn gái Lương Cẩm Thu, cha của cô lại bị bắt giam vì vi phạm pháp luật về thuế. Cùng lúc đó, sư phụ của Trịnh Hạo, Trần Đại Quân, thiệt mạng trong quá trình điều tra một vụ án. Sau biến cố, mẹ con Lương Cẩm Thu bị chủ nợ truy đuổi và buộc phải ra nước ngoài. Đối mặt với cái chết đầy nghi vấn của Đại Quân và sự ra đi của Cẩm Thu, Trịnh Hạo rơi vào đau khổ vì bất lực trước mọi chuyện. Sáu năm sau, Trịnh Hạo – lúc này là Cục trưởng Cục Kiểm soát rủi ro thuế vụ quận Lĩnh Thủy, thành phố Tân Đông – đã phá nhiều vụ án lớn nhờ công nghệ dữ liệu lớn. Anh được điều động về Cục Thanh tra Thuế, giữ chức Trưởng phòng Thanh tra số Hai. Cùng thời điểm đó, Lương Cẩm Thu sau nhiều năm bươn chải ở nước ngoài cũng trở về quê hương để phát triển sự nghiệp. Còn Triệu Minh Đạt – người từng cùng họ tạo nên &quot;bộ ba thiên tài&quot; thời đại học, nay là giáo sư tài chính – lại rơi vào khủng hoảng vì căn bệnh của con gái. Bên dưới vẻ ngoài yên bình của Tân Đông là một mạng lưới tội phạm khổng lồ chuyên trục lợi từ hành vi trốn thuế. Số phận của ba con người tưởng chừng đã rẽ lối nay lại bị cuốn vào vòng xoáy đầy biến động và hiểm nguy phía trước...</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Nie Yuan","avatar":""},{"name":"Yang Rong","avatar":""},{"name":"Zhang Duo","avatar":""},{"name":"Shi Jingming","avatar":""},{"name":"Wu Mian","avatar":""},{"name":"Yang Boxiao","avatar":""},{"name":"Wang Ruixin","avatar":""},{"name":"Huang Meng","avatar":""},{"name":"Zeng Kelang","avatar":""},{"name":"Xu Yajun","avatar":""},{"name":"Guo Jinglin","avatar":""},{"name":"Li Hongtao","avatar":""},{"name":"Shi Ke","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Da He Zhi Shui","大河之水","River of Tax Justice"]', 1784690324159);
