INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nuoc-song-dai-ha', 'Nước Sông Đại Hà', 'The Source Of River', 'nước sông đại hà the source of river nie yuan yang rong zhang duo shi jingming wu mian yang boxiao wang ruixin huang meng zeng kelang xu yajun guo jinglin li hongtao shi ke da he zhi shui 大河之水 river of tax justice', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-manh-vo-gian-dao', 'Ma Mãnh Vô Gian Đạo', 'Your Finesse', 'https://phimimg.com/upload/vod/20250226-1/9886951e605fbae3a7d1c73603fd7d54.jpg', 'https://phimimg.com/upload/vod/20250226-1/a74a6eb087fd56d2ea0fc2ca7ac32f17.jpg', '<p>Phí Nhân và em gái kết nghĩa Cao Cường vì kiếm tiền mà làm bổ khoái nha môn huyện Lỗ Nhân. Bổ trưởng tân nhiệm Huỳnh Xà phái Phí Nhân thâm nhập vào Nhất Tướng Cung Thành – một nơi vô pháp vô thiên, nhằm tìm kiếm các tế tác (cảnh sát nội gián thời phong kiến) bị mất tích. Trong thành, bề ngoài rất phồn hoa, nhưng thật ra tứ đại môn phái gồm: Từ Ý Môn, Lý Như Môn, La Sinh Môn và Ban Long Môn âm thầm tranh đấu lẫn nhau. Phí Nhân và Cung Tử cùng rút thanh bảo kiếm một cách vô tình, trở thành hai chàng rể ứng viên cho đại tỷ của Từ Ý Môn là Phù Linh. Thân phận tế tác là một câu đố, là họa hay phước thật khó đoán...</p>', 'Tập 25', 25, 'series', 'ongoing', 11, 2025, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Châu Gia Lạc","avatar":""},{"name":"Trần Oánh","avatar":""},{"name":"Chu Mẫn Hãn","avatar":""},{"name":"Vương Hạo Nhi","avatar":""},{"name":"Mạch Mỹ Ân","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["痞子殿下2","Your Highness 2","痞子無間道"]', 1784690324159);
