INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bien-co-tuoi-thanh-nien', 'Biến Cố Tuổi Thành Niên', 'Adolescence', 'https://phimimg.com/upload/vod/20250316-1/8f6d08effb5fe7c2d68d521267084225.jpg', 'https://phimimg.com/upload/vod/20250316-1/af14b4efd0a45ee6c0d0c11cf7511800.jpg', '<p>Khi một cậu bé 13 tuổi bị buộc tội giết bạn cùng lớp, gia đình cậu bé, bác sĩ trị liệu và thanh tra phụ trách đều tự hỏi: chuyện gì đã thực sự xảy ra?</p>', 'Hoàn Tất (4/4)', 4, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Owen Cooper","avatar":""},{"name":"Stephen Graham","avatar":""},{"name":"Ashley Walters","avatar":""},{"name":"Erin Doherty","avatar":""},{"name":"Faye Marsay","avatar":""},{"name":"Christine Tremarco","avatar":""},{"name":"Mark Stanley","avatar":""},{"name":"Jo Hartley","avatar":""},{"name":"Amelie Pease","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Դեռահաս","Derahas","Малалецтва","混沌少年时","混沌少年時","Переходный возраст","مراهق العائلة","Adolescence"]', 1784690324159);
