INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-cuoi-quy-quai', 'Nụ Cười Quỷ Quái', 'Abyss Live', 'https://phimimg.com/upload/vod/20250303-1/f07fdb237dd4172e90dd1a68549b1d6f.jpg', 'https://phimimg.com/upload/vod/20250303-1/c21d2717a3b5134de5698f90db441f34.jpg', '<p>Trong lúc ngành công nghiệp điện ảnh ảm đạm, công ty điện ảnh Nhất Bình cho ra mắt &quot;Show thực tế thám hiểm hang động phát sóng trực tiếp&quot; với mô típ đổi mới sáng tạo. Diễn viên nổi tiếng Lý Khải Toàn và một vài quần chúng đi thám hiểm hang động, nhưng liên tiếp xảy ra những chuyện lạ kinh dị và huyền bí, đồng thời mắc kẹt trong cái bẫy do người bí ẩn giăng ra. Sau khi trải qua thử thách về nhân tính và thanh lọc tâm hồn, sự thật kinh hoàng dần dần lộ diện.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Khương Siêu","avatar":""},{"name":"Khương Nghệ Thanh","avatar":""},{"name":"Triệu Tử Hàm","avatar":""},{"name":"Kỷ Hải Tinh","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Gui Mi Xin Xiao","诡迷心笑"]', 1784690324159);
