INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('san-ho-2025', 'Săn Hổ', 'The Hunt Down', 'https://phimimg.com/upload/vod/20250314-1/3b79afc9723edef54805a88e5cb4dc9d.jpg', 'https://phimimg.com/upload/vod/20250314-1/f88c5f41b0db97b39cbdcd03833f68b3.jpeg', '<p>Trùm ma túy Trương Hổ giết hại cảnh sát truy bắt mình rồi bỏ trốn. Ba năm sau, băng nhóm buôn ma túy dưới trướng Trương Hổ tìm đến tài xế xe không giấy phép Lý Quân, ép anh vận chuyển hàng. Đội trưởng đội phòng chống ma túy Đường Húc Đông thuyết phục Lý Quân làm nội gián. Vì cần tiền để chữa bệnh cho vợ, Lý Quân đồng ý và bắt đầu một nhiệm vụ đầy nguy hiểm. Tuy nhiên, khi sự việc ngày càng tiến triển, mọi thứ đã vượt xa kế hoạch ban đầu của Đường Húc Đông, bởi Lý Quân còn có một mục đích lớn hơn.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tư Lực Canh","avatar":""},{"name":"Nặc Mẫn Đạt Lai","avatar":""},{"name":"Vương Tiêu","avatar":""},{"name":"Lưu Thượng","avatar":""},{"name":"Trần Tinh Vũ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["The Tiger Hunter"]', 1784690324159);
