INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-quan-ky-mon', 'Cơ Quan Kỳ Môn', 'Qimen Mechanism Volume', 'https://phimimg.com/upload/vod/20250314-1/5198ecb81dc440a9536bba1093da5be1.jpg', 'https://phimimg.com/upload/vod/20250314-1/b2742eccd99f3ee4b337225cf1603bf6.jpg', '<p>Bộ phim kể về sự xuất hiện bất ngờ của Quyển Cơ Quan Kỳ Môn trong lăng mộ Quỷ Cốc, khiến nước Tề và nước Sở tranh giành báu vật mà cùng tiến vào ngôi mộ, dẫn đến thương vong nặng nề. Mặc gia cự tử Mặc Tâm nhận được thư truyền tin từ Mộc Diên, liền cùng sư huynh Công Thâu Dã và sư muội A Bao mang theo hy vọng chấm dứt chiến tranh, cấp tốc lao đến lăng mộ Quỷ Cốc. Trải qua muôn vàn hiểm nguy, họ phá giải được kỳ cuộc của lão tặc Quỷ Cốc, nhưng lại rơi vào một khủng hoảng lớn hơn. Cuối cùng, Mặc Tâm cùng sư huynh và sư muội hợp sức hóa giải nguy cơ, viết nên câu chuyện về trí tuệ, nghĩa hiệp và lòng dũng cảm.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jerry Lee","avatar":""},{"name":"Zhao Wang","avatar":""},{"name":"Shang Na","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Qimen Mechanism Volume","기문기관권","奇门机关卷"]', 1784690324159);
