INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-la-giac-mong-giang-ho', 'Chỉ Là Giấc Mộng Giang Hồ', 'Love And Sword', 'https://phimimg.com/upload/vod/20250226-1/7a013182fb8bfccae4cf6bcf19c976b2.jpg', 'https://phimimg.com/upload/vod/20250226-1/8461ebfa75793f208f0e1306dbe2466c.jpg', '<p>Bộ phim kể về cao thủ bí ẩn lánh đời Diễm thiếu gia cứu giúp nữ đao khách Dung Sơ Cuồng bị Quỷ Cốc Minh hãm hại dẫn đến mất trí nhớ, hộ tống cô về Ngự Trì sơn trang. Không ngờ trong sơn trang sóng ngầm cuộn trào, giang hồ ngập tràn âm mưu, các môn phái tranh đấu không ngừng. Hai người bị cuốn vào cuộc đấu tranh giang hồ đẫm máu, chung tay trừ gian diệt ác, phát huy cái thiện, chống lại thế lực tà ác Quỷ Cốc Minh. Thế nhưng bí ẩn quá khứ và hiện tại cũng đang chờ hai người phá giải…</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cao Vỹ Quang","avatar":""},{"name":"Tuyên Lộ","avatar":""},{"name":"Nhậm Hào","avatar":""},{"name":"Gia Nại Na","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["与艳少同眠","江湖宅女记","只此江湖梦","love and sword"]', 1784690324159);
