INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chi-la-giac-mong-giang-ho', 'Chỉ Là Giấc Mộng Giang Hồ', 'Love And Sword', 'chỉ là giấc mộng giang hồ love and sword cao vỹ quang tuyên lộ nhậm hào gia nại na 与艳少同眠 江湖宅女记 只此江湖梦 love and sword', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muoi-nam-khong-muon', 'Mười Năm Không Muộn', 'Revenge Waits In The Shadows', 'https://phimimg.com/upload/vod/20250312-1/67fc44b4ef6fbfb287f1a5c7d295ca2e.jpg', 'https://phimimg.com/upload/vod/20250312-1/e8a32ef21ca28cf4aa70c7da65346736.jpg', '<p>Vào cuối triều đại nhà Thanh, đêm tân hôn của Vũ Văn Lượng lại trở thành khởi đầu cho một bi kịch kinh hoàng. Cả gia tộc Vũ Văn bị thế lực tà ác vu oan hãm hại, bị giam cầm trong lao ngục, rồi lần lượt chết trong thảm cảnh. Trưởng nam Vũ Văn Lượng may mắn sống sót nhờ sự che chở của bạn tù già là Lão La, cùng nhau trải qua bao phen sinh tử, cuối cùng liều mạng vượt ngục. Trước khi qua đời, Lão La ủy thác Vũ Văn Lượng đi tìm con gái mình là Hiển Tình, đồng thời tặng lại cho anh một khoản tài sản quý giá. Mười năm sau, Vũ Văn Lượng trở lại Thượng Hải, nay đã đổi tên thành Henry La – một thương nhân giàu có đến từ Nam Dương. Với khối tài sản khổng lồ và thần thái bí ẩn, Henry nhanh chóng thu hút sự chú ý của giới thượng lưu. Anh tình cờ gặp lại Lý Tư Văn – người bạn cũ năm xưa, và Lam Tâm Di – mối tình đầu đã từng khắc cốt ghi tâm. Henry âm thầm lên kế hoạch, từng bước vạch trần và tiêu diệt những kẻ năm xưa đã hãm hại nhà họ Vũ Văn. Khi sự thật được phơi bày, người đứng sau tất cả lại chính là Lý Tư Văn – người bạn thân nhất thuở ấu thơ. Trong cơn hỗn loạn, Lam Tâm Di vì cứu Henry mà hy sinh, hương tiêu ngọc vẫn, khiến người người thương tiếc. Cuối cùng, Lý Tư Văn phải trả giá bằng mạng sống, chính nghĩa được thực thi. Sau bao năm mưa gió phong ba, Henry mang theo đứa con gái nhỏ Lý Thi Nguyệt trở về – đứa trẻ là kết tinh tình yêu giữa anh và Lam Tâm Di. Mười năm sau, Thi Nguyệt nay đã trưởng thành, xinh đẹp như hoa. Mọi người quây quần bên nhau, mang theo hy vọng về một tương lai tươi sáng cho vùng đất Thượng Hải đầy biến động.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Pan Zijian","avatar":""},{"name":"Jiang Shen","avatar":""},{"name":"Xuan Hao","avatar":""},{"name":"Yu Luna","avatar":""},{"name":"Zhang Yike","avatar":""},{"name":"Wang Kaimu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shi Nian Bu Wan","Ten Years is Not Too Late","十年不晚"]', 1784690324159);
