INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('may-man-sap-den', 'May Mắn Sắp Đến', 'Fortune Awaits', 'https://phimimg.com/upload/vod/20250228-1/74249a93bc9da24a0435cb94922ce5cd.jpg', 'https://phimimg.com/upload/vod/20250228-1/e13e870fa622129f94d0df649b585b7c.jpg', '<p>Bộ phim hiện đại này kể về câu chuyện một người bình thường đang chật vật duy trì trại heo hoán đổi cuộc sống với một cậu ấm sống trong nhung lụa. Hà Phương, ông chủ trại heo và Kim Tiêu, cậu hai của tập đoàn Kim Thị có ngoại hình giống hệt nhau. Hai người vốn không hề liên quan nhưng lại hoán đổi thân phận cho nhau sau một sự cố bất ngờ. Cậu chủ nhà giàu buộc phải quản lý trại heo, trong khi ông chủ trại heo phải xoay sở trong thế giới xa hoa của tập đoàn Kim Thị. Cả hai bắt đầu một cuộc sống hoàn toàn mới…</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lu Yunfeng","avatar":""},{"name":"Xu Xiaonuo","avatar":""},{"name":"Ma Jiaming","avatar":""},{"name":"Peng Yihang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["好运将至"]', 1784690324159);
