INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diep-do-me-cuc', 'Điệp Đồ Mê Cục', 'Spy Puzzle', 'https://phimimg.com/upload/vod/20250313-1/f7df8ddf5c1b6d252cbd550eb4e98e2d.jpg', 'https://phimimg.com/upload/vod/20250313-1/7ac7478572f0879703febbf384dc0e9c.jpg', '<p>Tù Tân Trị cảm thấy mệt mỏi với cuộc sống ngầm đầy căng thẳng, nhưng một vụ mất tích của người dân lại đưa anh vào một tình huống đầy nguy hiểm. Anh định giả làm một điệp viên để tìm ra hung thủ và phá giải vụ án, nhưng không ngờ rằng đằng sau vụ án rối rắm này, một tội ác và âm mưu lớn hơn đang dần lộ diện, đang nhắm vào anh. Để phá án, Tù Tân Trị dùng trí tuệ để trừng trị kẻ ác và loại bỏ cái xấu. Cuối cùng, anh đã giải cứu người dân khổ đau và đưa kẻ chủ mưu ra trước vành móng ngựa.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wang Luojia","avatar":""},{"name":"Wang Jiusheng","avatar":""},{"name":"Li Zhen''an","avatar":""},{"name":"Zhang Chunzhong","avatar":""},{"name":"Shi Zhaoqi","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["谍徒迷局"]', 1784690324159);
