INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chao-mung-den-voi-gia-dinh', 'Chào Mừng Đến Với Gia Đình', 'Welcome To The Family', 'https://phimimg.com/upload/vod/20250313-1/33ac5b95d64bdb0edcc2823e90be7e64.jpg', 'https://phimimg.com/upload/vod/20250313-1/efec1cfeeef57c87818406976758e400.jpg', '<p>Một bà mẹ đơn thân đang gặp khó khăn đã tập hợp gia đình lập dị của mình để đánh bại tay trùm mafia sau khi người cha giàu có, xa cách của cô qua đời, để lại khoản nợ khổng lồ.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Mexico', 0, '[{"name":"Marimar Vega","avatar":""},{"name":"Erika Buenfil","avatar":""},{"name":"Ana Layevska","avatar":""},{"name":"Erick Elías","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Bienvenidos a la familia"]', 1784690324159);
