INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuong-tam', 'Chưởng Tâm', 'Kill My Sins', 'https://phimimg.com/upload/vod/20250207-1/4925829759633fd78b880ec88af4f686.jpg', 'https://phimimg.com/upload/vod/20250207-1/ea0e12d43168df2a9658baeec31c93e8.jpg', '<p>Câu chuyện kể về Diệp Bình An (do Lưu Thi Thi thủ vai), một bác sĩ tim mạch đến Thịnh Đô để điều tra một vụ án cũ. Tin đồn lan ra rằng cô ta thao túng tâm trí và trái tim người khác, kiếm cho mình danh hiệu &quot;phù thủy&quot;. Khi một vụ giết người đột ngột xảy ra, cô bị buộc tội. Viên quan tham vọng, Nguyên Thiếu Thành (do Đậu Kiêu thủ vai), nhận ra vụ án còn nhiều điều ẩn giấu nhưng vẫn tìm cách xử tử cô. Nhưng Diệp Bình An đã bước đầu tiên trên con đường trả thù của mình.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 4, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Thi Thi","avatar":""},{"name":"Đậu Kiêu","avatar":""},{"name":"Trịnh Nghiệp Thành","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["掌心","ล้างบ่วงบาป","Kill My Sins"]', 1784690324159);
