INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoi-cac-vi-sao', 'Hỏi Các Vì Sao', 'When The Stars Gossip', 'hỏi các vì sao when the stars gossip lee min-ho gong hyo-jin oh jung-se han ji-eun heo nam-jun lee cho-hee kim ju-hun lee el lee hyun-kyun park ye-yeong baek eun-hae jeon su-kyung jung young-ju kim eung-soo lee doo-seok pergunte às estrelas وقتی ستاره‌ها خبرچینی می‌کنند وقتی ستاره‌ها شایعه‌سازی می‌کنند وقتی ستاره ها شایعه میسازن وقتی ستاره‌ها نجوا می‌کنند byeoldeulege muleobwa when the stars gossip ask the stars 별들에게 물어봐', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('zenshu', 'Zenshu', 'ZENSHU', 'https://phimimg.com/upload/vod/20250310-1/bacb0c576c6abb32aa085c9dde4b44b6.jpg', 'https://phimimg.com/upload/vod/20250310-1/e20ac0c2f202f0013da82ecabd91d04b.jpg', '<p>Sau khi tốt nghiệp trung học, Natsuko Hirose bắt đầu sự nghiệp của mình với tư cách là một họa sĩ hoạt hình. Tài năng của cô nhanh chóng phát triển và cô đã ra mắt với tư cách là một đạo diễn trong thời gian ngắn. Bộ phim hoạt hình đầu tiên của cô đã trở thành một hit lớn, tạo nên một hiện tượng xã hội và giúp cô được công nhận là một đạo diễn thiên tài mới nổi. Dự án tiếp theo của cô sẽ là một bộ phim hài lãng mạn lấy chủ đề về mối tình đầu! Tuy nhiên, bản thân chưa bao giờ yêu, Natsuko phải vật lộn để hiểu được khái niệm về mối tình đầu và kết quả là cô không thể tạo ra bảng phân cảnh, khiến cho quá trình sản xuất bộ phim bị đình trệ.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Anna Nagase","avatar":""},{"name":"Kazuki Ura","avatar":""},{"name":"Rie Kugimiya","avatar":""},{"name":"Minori Suzuki","avatar":""},{"name":"Akio Suyama","avatar":""},{"name":"Romi Park","avatar":""},{"name":"Manaka Iwami","avatar":""},{"name":"Kentaro Tone","avatar":""},{"name":"Masashi Yamane","avatar":""},{"name":"Katsuhisa Houki","avatar":""},{"name":"Sayaka Ohara","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b93