INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-ta-nguoc-dong-thoi-gian', 'Chúng Ta Ngược Dòng Thời Gian', 'Cycle Of Terror', 'https://phimimg.com/upload/vod/20250310-1/2828da592f39a6886b239a810a819242.jpg', 'https://phimimg.com/upload/vod/20250310-1/114c627ceab0e03432e62a893215d3d2.jpg', '<p>Đường Tiểu Thất (sinh viên năm tư, thực tập sinh phóng viên) và Lạc Nhất (sinh viên năm tư, thực tập sinh thiết kế mỹ thuật) trong một lần đi thang máy đã bất ngờ cùng ba nam sinh khác rơi vào vòng lặp thời gian vô hạn. Trải qua vô số lần tái sinh, năm người họ cuối cùng đã phá giải được bí ẩn của vòng lặp, làm sáng tỏ sự thật về vụ rơi lầu của Tống Lương, đồng thời vạch trần âm mưu khổng lồ đằng sau việc các nền tảng truyền thông tự do tung tin giả.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Xiyuan","avatar":""},{"name":"Xing Ze","avatar":""},{"name":"Gao Kai","avatar":""},{"name":"Miao Yaning","avatar":""},{"name":"Lei Shu","avatar":""},{"name":"Shen Baoping","avatar":""},{"name":"Jiao Peng","avatar":""},{"name":"Mo Xiyang","avatar":""},{"name":"Tian Miao","avatar":""},{"name":"Jia Shuyi","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["逆时的我们"]', 1784690324159);
