INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-vuot-thoi-khong', 'Yêu Vượt Thời Không', 'The Boy Next World', 'https://phimimg.com/upload/vod/20250106-1/6d8d007ea30d6aab25f14261df426685.jpg', 'https://phimimg.com/upload/vod/20250106-1/6638d6c5fda6a7b93128eb55b9020bef.jpg', '<p>Nếu một ngày nào đó, có người nói với bạn rằng anh ấy là người yêu của bạn từ thế giới đa vũ trụ, bạn có tin không?. Chuyện kể rằng một ngày nọ, đàn anh nổi tiếng, Cirrus, một người đàn ông hoàn hảo bước tới và nói với Phukan, &#39;Chúng ta là người yêu của nhau&#39;. Làm sao Phukan có thể tin được đây, khi cả hai chưa từng gặp nhau trước đây? Mặc dù có chút nghi ngờ, nhưng anh ấy dường như biết mọi thứ về cuộc sống của Phukan. Cho đến khi trái tim nhỏ bé của cậu ấy dần dần hướng về anh. Hơn nữa, anh ấy còn nói rằng nếu chúng tôi không quen nhau, anh ấy sẽ tìm cơ hội để bắt đầu lại. Trái tim của Phukan cuối cùng cũng mềm lòng và tan chảy. Dù thích anh ấy và anh ấy chính là mẫu người Phukan thích, nhưng có một vấn đề. Anh ấy là người yêu trong thế giới đa vũ trụ. Vì vậy, Phukan phải quyết định xem có nên để người yêu của mình ra đi hay giữ anh ấy cho riêng mình.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Chaikamon Sermsongwittaya","avatar":""},{"name":"Nuttarat Tangwai","avatar":""},{"name":"Donut Suppawit Thongyuen","avatar":""},{"name":"Forth Kashane Pichetsopon","avatar":""},{"name":"Creamy Ploypapas Isarapongporn","avatar":""},{"name":"Kanoklak Sinngam","avatar":""},{"name":"Sinsophak Wijitwerot","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b