INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-giac-ngo-cua-ba-noi-tro', 'Sự Giác Ngộ Của Bà Nội Trợ', 'The Awakening Of Housewives', 'https://phimimg.com/upload/vod/20250307-1/defe18e5871a0f44e4ace91de51ceca2.jpg', 'https://phimimg.com/upload/vod/20250307-1/589dcc60b53d92ed2a1db76ce3af52e6.jpg', '<p>Sau khi kết hôn, bạch phú mỹ Lý Chỉ Tinh chấp nhận lui về làm nội trợ toàn thời gian, tận tâm chăm lo cho gia đình. Nhưng cô không ngờ rằng, đằng sau cuộc hôn nhân tưởng chừng hạnh phúc lại là sự phản bội cay đắng - chồng cô, Vương Nham, ngoại tình với chính người bạn thân nhất. Cha cô bất ngờ rơi lầu, công ty rơi vào khủng hoảng, còn người chồng từng yêu thương nay lộ rõ bộ mặt tham lam, ra sức tranh quyền đoạt lợi. Đứng trước vực thẳm tuyệt vọng, Lý Chỉ Tinh giác ngộ mạnh mẽ. Cô quyết không khoanh tay chịu trận mà vùng lên phản kích. Trừng trị kẻ phản bội, giành lại quyền lực, báo thù rửa hận, từng bước viết lại số phận của chính mình!</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Bai Xuhan","avatar":""},{"name":"Fan Yining","avatar":""},{"name":"Pan Xiaoxue","avatar":""},{"name":"Zhu Chenhao","avatar":""},{"name":"Hong Yutong","avatar":""},{"name":"Yan Yaying","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Zhu Fu De Jue Xing","主妇的觉醒"]', 1784690324159);
