INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-vat-yeu-tru', 'Phong Vật Yêu Trù', 'Fengwu Demon Chef, Feng Wu Yao Chu', 'https://phimimg.com/upload/vod/20250308-1/6e9193d6611dbc027f770b97444ecea3.jpg', 'https://phimimg.com/upload/vod/20250308-1/10ed97c0bb006e3bf9b875c048d5c044.jpg', '<p>Phong Vật Yêu Trù kể về những thù hận trong giang hồ, sơn hào hải vị trong nhân gian, cùng cảnh vật cửu châu tam hải thời cổ đại, hội tụ những tinh hoa ẩm thực của Trung Hoa. Bộ phim sẽ là chuyến hành trình kỳ ảo trong thế giới của các đầu bếp yêu thú</p>', 'Hoàn Tất (8/8)', 8, 'hoathinh', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Fengwu Yao Chu","Feng Wu Yao Chu","Fengwuyaochu","山海经","Shānhǎi Jīng","Shan-hai Ching","Fengwu Yaochu","山海經","The Demonic Chef","Fengwu Monster Chef","The Demonic Chef: A Culinary Journey through the Classic of Mountains and Seas","The Demonic Chef of Scenery","The Magic Chef","The Monster Chef","The Magic Demon Chef","Fengwu Magic Chef","风物妖厨"]', 1784690324159);
