INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-luc', 'Không Lực', 'Sky Force', 'https://phimimg.com/upload/vod/20250308-1/667786dd55d18baed3d90b27412884c2.jpg', 'https://phimimg.com/upload/vod/20250308-1/fb9bca974d1896852c301dbd40072b99.jpg', '<p>Bộ phim hé lộ một câu chuyện đầy kịch tính, lấy cảm hứng từ những sự kiện có thật trong một trong những cuộc không kích khốc liệt nhất giữa Ấn Độ và Pakistan. Một người hùng ngã xuống, một đồng đội quyết tâm tìm ra sự thật – bản anh hùng ca tôn vinh lòng dũng cảm, sự hy sinh và tinh thần kiên cường bất diệt.&quot;</p>', 'Full', 1, 'single', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Ấn Độ', 1, '[{"name":"Akshay Kumar","avatar":""},{"name":"Veer Pahariya","avatar":""},{"name":"Nimrat Kaur","avatar":""},{"name":"Sara Ali Khan","avatar":""},{"name":"Sharad Kelkar","avatar":""},{"name":"Mohit Chauhan","avatar":""},{"name":"Manish Chaudhary","avatar":""},{"name":"Naisha Khanna","avatar":""},{"name":"Soham Majumdar","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["स्काई फ़ोर्स","Владыки небес","Sky Force","نیروی هوایی"]', 1784690324159);
