INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khong-luc', 'Không Lực', 'Sky Force', 'không lực sky force akshay kumar veer pahariya nimrat kaur sara ali khan sharad kelkar mohit chauhan manish chaudhary naisha khanna soham majumdar स्काई फ़ोर्स владыки небес sky force نیروی هوایی', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-dot-kich-thien-ho', 'Đội Đột Kích Thiên Hổ', 'Tiger Squad', 'https://phimimg.com/upload/vod/20250308-1/33e4f1f23d9debd7742659ac608a537d.jpg', 'https://phimimg.com/upload/vod/20250308-1/a76c22c6bb33d9b366eb8ba00ad518bc.jpg', '<p>Bộ phim kể về cuộc đối đầu khốc liệt giữa đội quân không người lái của Trung Quốc và chiến tranh điện tử hiện đại. Đội đột kích Thiên Hổ của quân đỏ trong lúc thực hiện nhiệm vụ do thám sâu sau tuyến phòng thủ của địch đã không may rơi vào vòng vây của quân xanh. Sáu chiến binh ưu tú, bao gồm xạ thủ Lật Kiếm may mắn thoát ra, và họ sẽ đối đầu với số đông, quyết định thắng thua của cả trận chiến. Khi trận chiến trên mặt trận chính thức bùng nổ, quân xanh, với trang bị vũ khí hiện đại đạt trình độ thế giới và chiến lược chỉ huy tài ba, đã bố trí một mạng lưới vây bủa. Những khủng hoảng lòng tin trong đội, thiết bị thông tin bị phá hủy, quân địch chiếm lĩnh điểm cao… Đứng trước sức ép đa chiều, đội đột kích Thiên Hổ đang lâm vào tình thế tiến thoái lưỡng nan, họ sẽ đi đâu về đâu? Trong khoảnh khắc sinh tử, cả hai bên sẽ có một cuộc đối đầu quyết liệt, ai sẽ là người chiến thắng?</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Shi Zhaoqi","avatar":""},{"name":"Yutian Wang","avatar":""},{"name":"Hao Shuai","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["天虎突击队"]', 1784690324159);
