INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chaos-vu-tham-sat-manson', 'Chaos: Vụ Thảm Sát Manson', 'Chaos: The Manson Murders', 'https://phimimg.com/upload/vod/20250308-1/c3ad953745d16919099f7e541487f3f4.jpg', 'https://phimimg.com/upload/vod/20250308-1/498f93e7a53b452f137c55f88ff5afb8.jpg', '<p>Vào tháng 8 năm 1969, những tín đồ của Charles Manson đã giết bảy người theo lệnh của hắn. Vì sao vậy? Cùng khám phá âm mưu thao túng tâm trí, thử nghiệm của CIA và vụ giết người.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Charles Manson","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["Chaos: The Manson Murders"]', 1784690324159);
