INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguyen-tieu-phong-than-yeu', 'Nguyễn Tiểu Phong Thân Yêu', 'Ruan Xiaofeng''s Royal Love Quest', 'https://phimimg.com/upload/vod/20250303-1/0e4491e5cfb11e265197fca2c5b79b45.jpg', 'https://phimimg.com/upload/vod/20250303-1/efc6b1123dd636c6eeb8c602cefff889.jpg', '<p>Một nhân viên văn phòng hiện đại xuyên không thành vương phi cao quý, nhưng lại nhận ra cô không hề được chào đón. Ngay cả Linh vương, phu quân mới cưới của cô cũng lạnh nhạt với cô. Sau nhiều lần bị chơi khăm, cô mới nhận ra rằng &quot;kẻ xấu&quot; thực sự là chính bản thân mình? Không những thế, cô còn bị tình nghi có liên quan đến án mạng của mẫu thân Linh vương? Cô lập ra &quot;Đức Vân Xã&quot; phiên bản cổ đại, đưa &quot;Ma Sói&quot; vào phá án, mưu mẹo linh hoạt, nhờ đó khiến vương gia lạnh lùng phải nhìn cô bằng con mắt khác. Hai người hợp tác phá giải bí ẩn vụ án mẫu thân Linh vương ngã lầu năm xưa...</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngụy Tiếu","avatar":""},{"name":"Đặng Khải","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Qin Ai De Ruan Xiao Feng","亲爱的阮小枫"]', 1784690324159);
