INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguyen-tieu-phong-than-yeu', 'Nguyễn Tiểu Phong Thân Yêu', 'Ruan Xiaofeng''s Royal Love Quest', 'nguyễn tiểu phong thân yêu ruan xiaofeng''s royal love quest ngụy tiếu đặng khải qin ai de ruan xiao feng 亲爱的阮小枫', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duoi-tan-cay-co-ngoi-nha-mai-do', 'Dưới Tán Cây Có Ngôi Nhà Mái Đỏ', 'Always Home', 'https://phimimg.com/upload/vod/20250216-1/ccdd0bcb6349959d98b6dc1f875795a2.jpg', 'https://phimimg.com/upload/vod/20250216-1/402cda244905f77ef5693fa5ad499df9.jpg', '<p>Cô gái từ thị trấn nhỏ, Trần Hoan Nhĩ, cùng cha mẹ chuyển đến thành phố lớn. Cô và hai người bạn mới quen, Cảnh Tê Trì và Tống Tùng, từ thời cấp ba, đến đại học cho đến khi ra trường, đã cùng nhau trải qua tất cả những cột mốc quan trọng trong cuộc đời. Những ngày tháng giản dị và bình yên với việc học, đi dã ngoại, tham gia hội thể thao, và những chuyến &quot;sách lưu động&quot; cũng như những cảm xúc ngọt ngào, nỗi đắng cay của mối tình đơn phương, sự tiếc nuối khi lý tưởng bị gãy vụn, những cú sốc khi đối mặt với biến cố gia đình, và cả sự lúng túng, đau đớn khi lần đầu tiên đối diện với sự ra đi của người thân... Ba người trẻ tuổi này đã luôn giúp đỡ nhau vượt qua nỗi đau của sự trưởng thành, từ những thiếu niên ngây thơ trở thành người lớn hòa nhập với xã hội. Cuối cùng, họ trở thành một phiên bản tốt đẹp nhưng hoàn toàn khác xa với tưởng tượng thời cấp ba. Quan trọng hơn cả là họ luôn đồng hành bên nhau, chưa từng tách rời.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trạch Tiêu Văn","avatar":""},{"name":"Châu Kha Vũ","avatar":""},{"name":"Dương Hất Tử","avatar":""},{"name":"Hạc Thu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shu Xia You Pian Hong Fang Zi","Dear Us","树下有片红房子"]', 1784690324159);
