INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('larissa-bo-mat-khac-cua-anitta', 'Larissa: Bộ Mặt Khác Của Anitta', 'Larissa: The Other Side Of Anitta', 'https://phimimg.com/upload/vod/20250307-1/165e941b9fc7cf2bbc7448676f95282e.jpg', 'https://phimimg.com/upload/vod/20250307-1/54e111b991580d5a245be3e73c20885d.jpg', '<p>Ngôi sao nhạc pop Brazil Anitta hé lộ thế giới riêng tư nhất từ trước đến nay trong bộ phim tài liệu khám phá hai bản thể, khó khăn cá nhân và hành trình tìm kiếm niềm vui của cô.</p>', 'Full', 1, 'single', 'completed', 17, 2025, 'Vietsub', 'FHD', 'Brazil', 0, '[{"name":"Anitta","avatar":""},{"name":"Pedro Cantelmo","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '["Larissa: O Outro Lado de Anitta"]', 1784690324159);
