INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-tu-bong-toi', 'Nữ Tu Bóng Tối', 'Dark Nuns', 'https://phimimg.com/upload/vod/20250304-1/a6ede86ef7c4098fe8548e834146f536.jpg', 'https://phimimg.com/upload/vod/20250304-1/9154673a50f8bcd1cf3d96366ecdf74b.jpg', '<p>Sự tuyệt vọng đã thúc đẩy hai nữ tu thực hiện một lễ trừ tà mà không một nữ tu nào đáng ra nên thử. Với một đứa trẻ bị quỷ ám nằm dưới sự thao túng của cái ác và sự phản đối từ Giáo hội Công giáo, họ tự mình thực hiện những nghi lễ cấm kỵ đầy nguy hiểm, đặt linh hồn bất tử của họ vào hiểm họa khôn lường. Họ buộc phải đối mặt với cái giá kinh hoàng của những hành động phạm thượng, nhưng vẫn có một mục tiêu duy nhất: phải cứu được cậu bé bằng mọi giá.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"Song Hye-kyo","avatar":""},{"name":"Jeon Yeo-been","avatar":""},{"name":"Lee Jin-uk","avatar":""},{"name":"Moon Woo-jin","avatar":""},{"name":"Huh Joon-ho","avatar":""},{"name":"Kim Kuk-hee","avatar":""},{"name":"Shin Jae-hwi","avatar":""},{"name":"Gang Dong-won","avatar":""},{"name":"Han Dong-hee","avatar":""},{"name":"Park Jeong-hak","avatar":""},{"name":"Jeon Su-ji","avatar":""},{"name":"Park Ji-il","avatar":""},{"name":"Jeon Yu-na","avatar":""},{"name":"Choi Yu-ri","avatar":""},{"name":"Oh Man-seok","avatar":""},{"name":"Massimo Fierro","avatar":""},{"name":"Adriana Maria Duello","avatar":""},{"name":"Lee Kyung-seong","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Geomeun Sunyeode