INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('william-tell', 'William Tell', 'William Tell', 'https://phimimg.com/upload/vod/20250306-1/39e8adcd5e6a40ffc0b35d7bba653954.jpg', 'https://phimimg.com/upload/vod/20250306-1/f60c9bfd16b433b0d7824945ac2dfb2b.jpg', '<p>Câu chuyện diễn ra vào thế kỷ 14, khi các quốc gia châu Âu tranh giành quyền lực trong Đế chế La Mã Thần thánh. Đế quốc Áo, với tham vọng mở rộng lãnh thổ, đã xâm lược Thụy Sĩ, một quốc gia yên bình và thanh bình. William Tell, một thợ săn từng sống trong hòa bình, buộc phải đứng lên chiến đấu khi gia đình và quê hương của anh bị đe dọa bởi vua Áo tàn bạo.</p>', 'Full', 1, 'single', 'completed', 31, 2025, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Claes Bang","avatar":""},{"name":"Connor Swindells","avatar":""},{"name":"Golshifteh Farahani","avatar":""},{"name":"Jonah Hauer-King","avatar":""},{"name":"Ellie Bamber","avatar":""},{"name":"Rafe Spall","avatar":""},{"name":"Emily Beecham","avatar":""},{"name":"Jonathan Pryce","avatar":""},{"name":"Ben Kingsley","avatar":""},{"name":"Solly McLeod","avatar":""},{"name":"Amar Chadha-Patel","avatar":""},{"name":"Sam Keeley","avatar":""},{"name":"Tobias Jowett","avatar":""},{"name":"Jake Dunn","avatar":""},{"name":"Angus Kennedy","avatar":""},{"name":"Samuel Edward-Cook","avatar":""},{"name":"Paul Bull","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["威廉·退尔","William Tell"]', 1784690324159);
