INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cung-toa-kim-chi', 'Cung Tỏa Kim Chi', 'Love And Strife', 'https://phimimg.com/upload/vod/20250304-1/0acb5d3fecbf06d0ed7533008c30b2bd.jpg', 'https://phimimg.com/upload/vod/20250304-1/855f25add901585161e28d6404be9142.jpg', '<p>Tiểu thư dòng dõi tướng quân Từ Sở Vận vì vụ thảm án diệt môn của gia tộc mà một mình tiến vào kinh thành, quyết tâm tìm ra chân tướng. Cô nghi ngờ hung thủ chính là Giang Vân Thăng, thái tử tàn phế phải ngồi xe lăn, nên tìm mọi cách gả vào phủ thái tử để tiếp cận và điều tra. Trong quá trình chung sống, cả hai dần hóa giải hiểu lầm, cùng nhau phá giải nhiều vụ án ly kỳ. Cuối cùng, họ tìm ra sự thật, đồng hành bên nhau, vượt qua mọi khó khăn.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cai Zhengjie","avatar":""},{"name":"Chen Siche","avatar":""},{"name":"Luo Yutian","avatar":""},{"name":"Jiang Chen","avatar":""},{"name":"Hu Caihong","avatar":""},{"name":"Wang Ruizi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Gong Suo Jin Zhi","Love and Strife","宫锁金枝"]', 1784690324159);
