INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gap-nhau-o-toa', 'Gặp Nhau Ở Toà', 'Coming To Court Soon', 'https://phimimg.com/upload/vod/20250228-1/566a5a8789535c0b9246c1c25e90ab9e.jpg', 'https://phimimg.com/upload/vod/20250228-1/bb044df7c253c2ff5b092a363cb88dfd.jpg', '<p>Bộ phim kể về câu chuyện của Kiểm sát viên Chung Khâm Dương và Trợ lý Kiểm sát viên Tống Tô, những người bảo vệ sự công bằng và chính nghĩa trong khi xử lý một loạt các vụ án vị thành niên. Trong khi đó, Chung Khâm Dương kết bạn với học sinh trung học Lý Tùng Yến và dần khám phá ra sự thật đằng sau vụ tai nạn xe hơi của cha mẹ mình. Khi thủ phạm thực sự bị đưa ra công lý, mọi người bắt đầu một chương mới của cuộc sống dưới ánh sáng ấm áp của công lý.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Quách Già Nam","avatar":""},{"name":"Thiệu Vũ Thất","avatar":""},{"name":"Trần Trí Tuệ","avatar":""},{"name":"Dương Vĩnh Quân","avatar":""},{"name":"Lữ Ninh","avatar":""},{"name":"Triệu Khởi Nguyệt","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["身边的检察官","A Little Warm Prosecutor","即将出庭"]', 1784690324159);
