INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-ma-so-nguyen-to', 'Giải Mã Số Nguyên Tố', 'Prime Target', 'https://phimimg.com/upload/vod/20250225-1/e02f00349ab818d36988386392a5c16a.jpg', 'https://phimimg.com/upload/vod/20250225-1/1684ef70d9ca5597d5da8fc9668dcbb8.jpg', '<p>Một sinh viên toán xuất sắc đang trên đà đạt được một bước đột phá lớn thì kẻ thù đen tối cố gắng ngăn cản anh. Chiến đấu tìm câu trả lời và giữ mạng sống của mình, anh hợp tác với một đặc vụ chính phủ để làm sáng tỏ một âm mưu nguy hiểm.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Leo Woodall","avatar":""},{"name":"Quintessa Swindell","avatar":""},{"name":"Sidse Babett Knudsen","avatar":""},{"name":"David Morrissey","avatar":""},{"name":"Stephen Rea","avatar":""},{"name":"Fra Fee","avatar":""},{"name":"Jason Flemyng","avatar":""},{"name":"Joseph Mydell","avatar":""},{"name":"Martha Plimpton","avatar":""},{"name":"Harry Lloyd","avatar":""},{"name":"Ali Suliman","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Der Zahlen-Detektor","Πρώτος στόχος","יעד ראשוני","Prime Target"]', 1784690324159);
