INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('han-hai-than-long', 'Hãn Hải Thần Long', 'Loong of the Oceans', 'https://phimimg.com/upload/vod/20250305-1/78ca2be9defb737504eb48af51965de5.jpg', 'https://phimimg.com/upload/vod/20250305-1/ebaeedc353b68aee8ff04905a59da72b.jpg', '<p>Nghìn năm trước, Long Vương Hạo Nhất phong ấn người em cùng mẹ bị sa vào ma đạo là Diệp Anh để đổi lấy sự yên bình cho tam giới. Ngàn năm sau, con trai của Hạo Nhất là Phó Hi vô tình cứu con quái vật sò Bạch Dực, gây ra sự hỗn loạn tại chợ yêu. Phó Hi vô tình sử dụng pháp lực để phân phát tài sản, khiến Long Cung bị thua lỗ. Diệp Anh phá vỡ phong ấn, dùng anh trai của Phó Hi để uy hiếp Phó Hi giao ra pháp lực. Hạo Nhất đánh trọng thương Diệp Anh, khiến hắn hôn mê không tỉnh. Phó Hi tìm kiếm Giáng Ma Kiếm, cố gắng chém yêu diệt ma, nhưng lại phát hiện ra một màn sương mù dày đặc...</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yu Binghui","avatar":""},{"name":"Jin Cheng","avatar":""},{"name":"Zheng Qi","avatar":""},{"name":"Zhang Lei","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Han Hai Shen Long","Dragon Seduction","瀚海神龙"]', 1784690324159);
