INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-than-nguy-hiem', 'Thế Thân Nguy Hiểm', 'The Other Me', 'https://phimimg.com/upload/vod/20250305-1/8fd7db235e837fae28121cf1dda902a4.jpg', 'https://phimimg.com/upload/vod/20250305-1/9f1bb4a848609fdc8dcca465201bb139.jpg', '<p>Nhân viên giao hàng Tiểu Tuyết tình cờ gặp cô chủ Tống Vũ Nhàn của tập đoàn Tống Thị, phát hiện hai người có ngoại hình giống hệt nhau. Hai người vừa gặp đã thân, kết làm bạn tốt. Trong quá trình tiếp xúc với cuộc sống của nhau, cả hai đều thấy ngưỡng mộ người còn lại. Mà lúc này, Hạ Thanh Dương, chồng của Tống Vũ Nhàn, sếp tổng tập đoàn Tống Thị lại mang nặng tâm sự, dường như anh biết rõ mọi chuyện về Tiểu Tuyết.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Phan Mỹ Hoa","avatar":""},{"name":"Tô Kính Nguyên","avatar":""},{"name":"Hàn Tiêu Diêu","avatar":""},{"name":"Lưu Giai Du","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wei Xian Ti Shen","危险替身"]', 1784690324159);
