INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hien-truong-dieu-tra', 'Hiện Trường Điều Tra', 'Criminal Scene', 'https://phimimg.com/upload/vod/20250220-1/dc9146d59b1631309340fd09fd3d0450.jpg', 'https://phimimg.com/upload/vod/20250220-1/64a2c0bdff47adef6c6c7158c7fd8436.jpg', '<p>Đội trưởng đội điều tra hình sự Cố Trấn dẫn dắt đồng đội điều tra hàng loạt vụ án, liên tiếp phá giải những vụ án kỳ lạ nhờ trí tuệ nhạy bén. Đồng thời, Cố Trấn phát hiện ra mình đã rơi vào cạm bẫy báo thù được sắp đặt bởi người nhà của nạn nhân trong một vụ án cũ. Để bảo vệ nhân dân và những người thân yêu xung quanh, Cố Trấn phải đối đầu với kẻ báo thù đã sa ngã vào bóng tối. Cuối cùng, kẻ phạm tội cũng phải nhận lấy sự trừng phạt thích đáng.</p>', 'Tập 18', 18, 'series', 'ongoing', 12, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Tuấn Hiếu","avatar":""},{"name":"Lạc Minh Cật","avatar":""},{"name":"Vương Song","avatar":""},{"name":"Dương Kỳ Quân","avatar":""},{"name":"Đường Lự Tinh","avatar":""},{"name":"Tôn Hiểu Luân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Xing Zhen Xian Chang","형정현장 :범죄 현장","Criminal Investigation Site","刑侦现场"]', 1784690324159);
