INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngu-phuc-lam-mon-ban-be-cung-huong', 'Ngũ Phúc Lâm Môn : Bạn Bè Cùng Hưởng', 'Perfect Match : Friendship Sharing', 'https://phimimg.com/upload/vod/20250305-1/2ed0088a798bf8ecff546e1e26b41b90.jpg', 'https://phimimg.com/upload/vod/20250305-1/8d2222c65776ea24782fb00e45395f88.jpg', '<p>Chị em nhà Lý cùng nhóm &quot;con rể&quot; bước vào chế độ du xuân đầy thú vị. Ai sẽ khiến trái tim bạn tan chảy với những lời ngọt ngào tinh tế từ mỗi gia đình? Họ sẽ trải qua những câu chuyện gì trong một không gian và thời gian khác biệt? Hành trình hạnh phúc của tình bạn sắp bắt đầu!</p>', 'Hoàn Tất (6/6)', 6, 'tvshows', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lu Yuxiao","avatar":""},{"name":"Wang Xingyue","avatar":""},{"name":"Liu Xiening","avatar":""},{"name":"Chen Heyi","avatar":""},{"name":"Wu Xuanyi","avatar":""},{"name":"Huang Shengchi","avatar":""},{"name":"Huangyang Tiantian","avatar":""},{"name":"Winwin","avatar":""},{"name":"Zhao Qing","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Perfect Match · Friendship Sharing","友福同享"]', 1784690324159);
