INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rang-buoc-toi-loi', 'Ràng Buộc Tội Lỗi', 'Bound By Sin', 'https://phimimg.com/upload/vod/20250224-1/ac6bb963e5bd0e757d8ac33014210b92.jpg', 'https://phimimg.com/upload/vod/20250224-1/a04d5413dc6e06c66acb1ea21d3eb5ed.jpg', '<p>Cô ba nhà họ Tưởng, người luôn khao khát phá bỏ định kiến xã hội và kế thừa gia nghiệp, đã thuê nam chính - một chàng trai xuất thân thấp kém nhưng sống đúng mực - làm vệ sĩ để bảo vệ bản thân. Hai người thuộc về hai thế giới hoàn toàn khác biệt. Nữ chính với tính cách phóng túng, không màng khuôn phép, liên tục thử thách giới hạn của nam chính, đồng thời cũng khiến anh dần sa vào lưới tình. Thế nhưng, hiện thực nghiệt ngã đã chia cắt họ, nữ chính bị ép gả cho người khác, còn nam chính lên đường nhập ngũ. Đến khi đất nước lâm nguy, gia tộc suy tàn, nữ chính rơi vào cảnh khốn cùng, nam chính lại một lần nữa xuất hiện, cứu cô khỏi bể khổ, hai người thấu hiểu tình cảm của nhau.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hao Fushen","avatar":""},{"name":"Hu Yiyao","avatar":""},{"name":"Li Songci","avatar":""},{"name":"Wang Yizhou","avatar":""},{"name":"Luo Siqi","avatar":""},{"name":"Chang Zhekuan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["E Rong Xue","Goose Down Lock","鹅绒锁","鹅绒雪"]', 1784690324159);
