INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-binh-qua-cam', 'Chiến Binh Quả Cảm', 'Valiant One', 'https://phimimg.com/upload/vod/20250304-1/4041fbeaa6666e3a374ce2aa6340c3d6.jpg', 'https://phimimg.com/upload/vod/20250304-1/33ab55b28191ebf6b3d65b32febc47ea.jpg', '<p>&quot;Valiant One&quot; kể về một nhiệm vụ thường lệ của đội trực thăng quân đội Hoa Kỳ gần khu phi quân sự giữa Bắc và Nam Triều Tiên. Do cơn bão bất ngờ, trực thăng bị rơi sâu trong lãnh thổ Bắc Triều Tiên. Sergeant Edward Brockman (do Chase Stokes thủ vai) phải dẫn dắt những người sống sót, bao gồm cả chuyên gia kỹ thuật dân sự, tìm đường trở về Nam Triều Tiên mà không có sự hỗ trợ từ quân đội Hoa Kỳ. Họ phải đối mặt với nhiều nguy hiểm từ lực lượng Bắc Triều Tiên và vượt qua khu vực phi quân sự đầy hiểm trở.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Chase Stokes","avatar":""},{"name":"Lana Condor","avatar":""},{"name":"Desmin Borges","avatar":""},{"name":"Callan Mulvey","avatar":""},{"name":"Diana Tsoy","avatar":""},{"name":"Daniel Jun","avatar":""},{"name":"Jonathan Whitesell","avatar":""},{"name":"Stephen Adekolu","avatar":""},{"name":"Ronald Patrick Thompson","avatar":""},{"name":"Leo Chiang","avatar":""},{"name":"Dimitry Tsoy","avatar":""},{"name":"Jerina Son","avatar":""},{"name":"Tyrone Pak","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["یک دلاور","El Valiente","발리언트 원","Valiant One"]', 1784690324159);
