INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-hon-bao-ho', 'Linh Hồn Bảo Hộ', 'Presence', 'https://phimimg.com/upload/vod/20250303-1/fcd2a2fd1dfc00e7523ff4c54921ff90.jpg', 'https://phimimg.com/upload/vod/20250303-1/60c18ace25b3675de9dd39ef97c81b0c.jpg', '<p>Một gia đình chuyển đến một ngôi nhà mới ở vùng ngoại ô và dần tin rằng họ không đơn độc. Bộ phim được quay từ góc nhìn của một hồn ma/linh hồn và lấy bối cảnh trong một ngôi nhà trống trải, xinh đẹp. Ngôi nhà rất đẹp và cách quay phim rất xuất sắc.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Callina Liang","avatar":""},{"name":"Lucy Liu","avatar":""},{"name":"Chris Sullivan","avatar":""},{"name":"Eddy Maday","avatar":""},{"name":"Julia Fox","avatar":""},{"name":"Lucas Papaelias","avatar":""},{"name":"West Mulholland","avatar":""},{"name":"Daniel Danielson","avatar":""},{"name":"Benny Elledge","avatar":""},{"name":"Natalie Woolams-Torres","avatar":""},{"name":"Jared Wiseman","avatar":""},{"name":"Robert M. Jimenez","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["感应","A Presença","プレゼンス　存在","Přítomnost","Linh Hồn Bảo Hộ","Presença","Присутність","鬼魂","存在","Presence"]', 1784690324159);
