INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-cau-nguy-hiem', 'Mồi Câu Nguy Hiểm', 'Hook Bait', 'https://phimimg.com/upload/vod/20250218-1/e8957c5d4dce270ac927237936e23f82.jpg', 'https://phimimg.com/upload/vod/20250218-1/f49f5a811b63d7c0e3f546e54cbf27be.jpg', '<p>Trình Du tuy là chim hoàng yến trong lồng son nhưng lại luôn phản nghịch, khao khát thoát khỏi sự kìm kẹp của Châu Cận. Trong một lần cố tình tạo ra &quot;sự kiện cắm sừng&quot;, cô gặp gỡ người mẫu nam Bùi Tranh. Trình Du nhiều lần trêu đùa Bùi Tranh, tạo cơ hội để anh trở thành anh hùng cứu mỹ nhân. Bùi Tranh từ lạnh lùng, dửng dưng dần thành phản công mãnh liệt. Cả hai lợi dụng lẫn nhau, nhưng lại dần trao nhau tấm chân tình...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Tổ Nhất","avatar":""},{"name":"Từ Chẩn Chẩn","avatar":""},{"name":"Tăng Hi Đường","avatar":""},{"name":"Tôn Nghiên Ân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["危险垂钓"]', 1784690324160);
