INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bach-nguyet-phan-tinh', 'Bạch Nguyệt Phạn Tinh', 'Moonlight Mystique', 'https://phimimg.com/upload/vod/20250107-1/a29c2f6b2683c6064342d52b027beb9d.jpg', 'https://phimimg.com/upload/vod/20250107-1/fd4c6b3e935343506feb4bc447ee4009.jpg', '<p>&quot;Bạch Nguyệt Phạn Tinh&quot; là một bộ phim cổ trang lãng mạn do Chu Nhuệ Bân đạo diễn, có sự tham gia của Bạch Lộc (đóng vai Bạch Thước - &quot;Cảnh Sát Vinh Dự, Trường An Như Cố, Một Đời Một Kiếp&quot;), Ngao Thụy Bằng (đóng vai Phạm Việt - &quot;Thiếu niên ca hành&quot;), Đại Lộ Oa và Thường Hoa Sâm . Bộ phim được chuyển thể từ tiểu thuyết &quot;Bạch Thước Thượng Thần&quot; của Tinh Linh, kể về Bạch Thước, con gái út trong gia đình tướng quân, nguyện lập chí trở thành tiên nhân để đền đáp ơn nghĩa người đã cứu mình thuở nhỏ. Trên đường tìm kiếm tiên nhân, cô vô tình cứu sống Phạn Việt - yêu vương của yêu tộc. Từ sự gặp gỡ không ngờ, họ trải qua nhiều thăng trầm, từ lợi dụng lẫn nhau đến nảy sinh tình cảm, và cuối cùng là câu chuyện tình lãng mạn nhưng không kém phần đau thương khi cả hai đối diện với những khó khăn và chia cách. Dù có những khó khăn, tình yêu đó vẫn đủ mạnh mẽ để vượt qua mọi thử thách, ôm trọn lấy tình cảm chân thật nhất.</p>', 'Hoàn Tất (41/41)', 41, 'series', 'completed', 14, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Bạch Lộc","avatar":""},{"name":"Ngao Thụy Bằng","avatar":""},{"name":"Thường Hoa Sâm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["白烁上神","逐月","В погоне за луной","ตำนานรักสวรรค์จันทรา","Chasing the Moon","Moonlight Mystique","白月梵星"]', 1784690324160);
