INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vet-tim', 'Vết Tim', 'Heart Stain', 'https://phimimg.com/upload/vod/20250206-1/3a0577c31eeed8ad09b85360e33a1e7c.jpg', 'https://phimimg.com/upload/vod/20250206-1/cabd4cd1bcafda3aeea45ec22729639a.jpg', '<p>U-hyeon có tình cảm với giáo viên chủ nhiệm của mình và dự định giữ bí mật này cho đến khi tốt nghiệp. Tuy nhiên, khi người bạn thân nhất của anh, Do-ha, phát hiện ra, U-hyeon lo sợ rằng Do-ha sẽ đánh giá anh vì thích đàn ông. Thật bất ngờ, Do-ha đã phản ứng với một đề nghị không ngờ tới—hẹn hò nhau cho đến khi tốt nghiệp—Và vậy là, U-hyeon, muốn từ bỏ tình cảm của mình đối với giáo viên, đã đồng ý với đề xuất của Do-ha.</p><p><br/></p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Hamin","avatar":""},{"name":"Kim Ji-oh","avatar":""},{"name":"Kang Yeon-jae","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["我心臟的染色劑","心臟染色","Heart Stain","하트 스테인"]', 1784690324160);
