INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sao-dich-noi-sac-dep-tuyet-tran', 'Sao Địch Nổi Sắc Đẹp Tuyệt Trần', 'Les Belles', 'https://phimimg.com/upload/vod/20250214-1/a45f64c9cea646e23fb4183ae91db9cf.jpg', 'https://phimimg.com/upload/vod/20250214-1/fb5daf2ded7b903169719bdbdf575bed.jpg', '<p>Cô con gái của thế gia sa cơ lỡ vận La Lệnh Dư đưa muội muội đến Kiến Nghiệp nhờ cậy họ hàng. Dọc đường đã cứu một chàng trai sa cơ lỡ vận. Vì trở ngại thân phận và lễ giáo, nửa đêm cô đã ép chàng trai nhảy khỏi thuyền. Đến Lục gia, cô một lòng muốn chọn một người chồng tốt, mà không hề hay biết, tam công tử Lục gia cô để ý chính là chàng trai bị cô ép nhảy xuống nước đêm hôm đó. Cô dùng mọi cách để lấy lòng y nhưng liên tục thất bại, y lặng lẽ nhìn cô diễn trò và tàn nhẫn vạch trần cô hết lần này đến lần khác. Thế nhưng, khi cô nản lòng thoái chí, quay ra lấy lòng người khác, y lại không đồng ý. Lòng chàng sắt đá, sao địch nổi sắc đẹp tuyệt trần.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lâm Duẫn","avatar":""},{"name":"Phương Dật Luân","avatar":""},{"name":"Triệu Tinh","avatar":""},{"name":"Lâm Bá Duệ","avatar":""},{"name":"Quách Già Nam","avatar":""},{"name":"Đặng Hiếu Từ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Zen Di Ta Qian Jiao Bai Mei","즘활저천교백미 : 찾았다, 내 낭군님","Чарующая красота и обаяние","Les Belles","怎敌她千娇百媚"]', 1784690324160);
