INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sao-dich-noi-sac-dep-tuyet-tran', 'Sao Địch Nổi Sắc Đẹp Tuyệt Trần', 'Les Belles', 'sao địch nổi sắc đẹp tuyệt trần les belles lâm duẫn phương dật luân triệu tinh lâm bá duệ quách già nam đặng hiếu từ zen di ta qian jiao bai mei 즘활저천교백미 : 찾았다, 내 낭군님 чарующая красота и обаяние les belles 怎敌她千娇百媚', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-tinh-sai-lech', 'Người Tình Sai Lệch', 'Misaligned Lover', 'https://phimimg.com/upload/vod/20250225-1/10a9916c9c76f007e411fad02c2cd198.jpg', 'https://phimimg.com/upload/vod/20250225-1/cf3399467c2f4653348dd4bdb9760e66.jpg', '<p>Trong những thăng trầm của hôn nhân, số phận của Diêm Lập Đông và Mộc Thần Hi gắn kết với nhau. Vì những hiểu lầm và mâu thuẫn, cả hai dần đi đến bờ vực ly hôn. Tuy nhiên,Diêm Lập Đông bị thương vì cứu Mộc Thần Hi, khiến ký ức của anh quay trở lại năm 19 tuổi. Trong quá trình ấy, Mộc Thần Hi dần nhận ra sự vô tâm và lạnh nhạt trước đây của mình. Khi chung sống với người chồng với ký ức dừng lại ở tuổi 19, cô dần cảm nhận sức mạnh và sự ngọt ngào của tình yêu.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Maggie Chen","avatar":""},{"name":"Zhang Xinyao","avatar":""},{"name":"Sun Yinghao","avatar":""},{"name":"Jiang Shen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["听说你外面有狗了? 离婚","착위애인 :엇갈린 애인","Misplaced Lover","错位爱人"]', 1784690324160);
