INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-gian-nhat-khuynh-thanh', 'Hoa Gian Nhất Khuynh Thành', 'Love Of Petals', 'https://phimimg.com/upload/vod/20250227-1/c86cb9243b7d2529a4b3e22dd7c5105e.jpg', 'https://phimimg.com/upload/vod/20250227-1/14d4c1e668ba64f45f33cf41ffd79ea4.jpg', '<p>Cô gái trồng hoa nhỏ bé Cố Thanh Tranh (Lệ Lận Phi thủ vai) đến từ &quot;Hoa đô&quot; Bình Thành, tình cờ hít phải Hoa linh khi đang cứu chữa một đóa mẫu đơn trắng theo sự dẫn đường của một con đom đóm bí ẩn. Không ngờ, đóa mẫu đơn ấy chính là hóa thân của bán yêu ngàn năm Lữ Canh Vân (Hà Sướng Hi thủ vai). Từ nhỏ, Cố Thanh Tranh đã mang trong lòng di nguyện của cha, quyết tâm cứu sống 9999 đóa hoa với hy vọng Bách Hoa Tiên quân sẽ đưa cô lên Thiên giới gặp người cô luôn mong nhớ. Trong đêm định mệnh ấy, Lữ Canh Vân tỉnh giấc từ một đóa mẫu đơn khổng lồ, khiến Cố Thanh Tranh tin chắc rằng anh chính là Bách Hoa Tiên quân, liền bái anh làm sư phụ. Còn Lữ Canh Vân, để tìm cách lấy lại Hoa linh và điều tra chân tướng vụ án oan của cha mẹ mình, buộc phải giả danh ở lại bên cô, chờ thời cơ hành động. Nhưng không ngờ, Cố Thanh Tranh lại chính là &quot;Đạo tặc hái hoa&quot;khét tiếng, kẻ khiến cả giới yêu ma khiếp sợ … Sau hàng loạt câu chuyện kỳ ảo, hai người dần thấu hiểu và nảy sinh tình cảm.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Linfei","avatar":""},{"name":"He Changxi","avatar":""},{"name":"Wang Haoxuan","avatar":""},{"name":"Gao Jicai","avatar":""},{"name":"Wang Muxuan","avatar":""},{"name":"Xie Zecheng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["落花倾城","我和花妖恋爱了","Hua Jia Yi Qing Cheng","花间一倾城"]', 1784690324160);
