INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-ngay-trai-chu-mot-ngay-quan', 'Một Ngày Trại Chủ Một Ngày Quan', 'Swap Face', 'https://phimimg.com/upload/vod/20250224-1/42ccb49bf5a46e1777e2160f6a85425c.jpg', 'https://phimimg.com/upload/vod/20250224-1/f07aea9aa8bd91dac771b1043321013a.jpg', '<p>Bổ khoái thực tập Tô Tiểu Kiều vì muốn điều tra manh mối chuyện mẹ mình bị diệt khẩu nên đã hoán đổi thân phận và dung mạo với Cố Thanh Đại, góa phụ của thủ lĩnh Thanh Phong Trại, trở thành trại chủ của Thanh Phong Trại, sau đó cưới các chủ Sở Yến của Túc Chính Các đang nằm vùng trong trại làm áp trại phu quân với danh nghĩa Cố Thanh Đại, mục đích là tìm ra sự thật đằng sau âm mưu này.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Qu Mengru","avatar":""},{"name":"Pan Yihong","avatar":""},{"name":"Zhang Chenxi","avatar":""},{"name":"Hou Yige","avatar":""},{"name":"Liu Jianyu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Yi Ri Zhai Zhu Yi Ri Guan","일일채주일일관","一日寨主一日官"]', 1784690324160);
