INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-la-dau-2025', 'Yêu Là Đau', 'Love Hurts', 'https://phimimg.com/upload/vod/20250227-1/0b0db32f696539c09922afbc7f60baeb.jpg', 'https://phimimg.com/upload/vod/20250227-1/1c3e6e74b0ce061e3048154e5c90bc35.jpg', '<p>Một nhà môi giới bất động sản bị kéo trở lại cuộc sống mà anh đã bỏ lại sau khi đồng phạm cũ của anh xuất hiện với một thông điệp đáng ngại. Với người anh trai là trùm tội phạm cũng đang truy đuổi, anh phải đối mặt với quá khứ và lịch sử mà anh chôn vùi.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Ke Huy Quan","avatar":""},{"name":"Ariana DeBose","avatar":""},{"name":"Mustafa Shakir","avatar":""},{"name":"Lio Tipton","avatar":""},{"name":"Daniel Wu","avatar":""},{"name":"Cam Gigandet","avatar":""},{"name":"Marshawn Lynch","avatar":""},{"name":"André Eriksen","avatar":""},{"name":"Rhys Darby","avatar":""},{"name":"Sean Astin","avatar":""},{"name":"Drew Scott","avatar":""},{"name":"Stephanie Sy","avatar":""},{"name":"Adam Hurtig","avatar":""},{"name":"Liam Stewart-Kanigan","avatar":""},{"name":"Yoko Hamamura","avatar":""},{"name":"Rawleigh Clements-Willis","avatar":""},{"name":"David MacInnis","avatar":""},{"name":"P","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["With Love","אהבה ומכות אחרות","L''Amour fait Mal","Sevgi Ağrıdır","Amor explosivo","前任杀神","Back to Business","Love Hurts - Liebe tut weh","A szerelem fáj","Colpi d''amore","O Amor Dói","Любовь - боль","狠狠愛","Kırarım Kalbini","Любов зла","Yêu Là Đau","Ljubavi Boli","Ljubezen Boli","Armas