INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('yeu-la-dau-2025', 'Yêu Là Đau', 'Love Hurts', 'yêu là đau love hurts ke huy quan ariana debose mustafa shakir lio tipton daniel wu cam gigandet marshawn lynch andré eriksen rhys darby sean astin drew scott stephanie sy adam hurtig liam stewart-kanigan yoko hamamura rawleigh clements-willis david macinnis p with love אהבה ומכות אחרות l''amour fait mal sevgi ağrıdır amor explosivo 前任杀神 back to business love hurts - liebe tut weh a szerelem fáj colpi d''amore o amor dói любовь - боль 狠狠愛 kırarım kalbini любов зла yêu là đau ljubavi boli ljubezen boli armastus teeb haiget სასტიკე სიყვარულე love hurts／ラブ・ハーツ love hurts', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truy-tim-hung-thu', 'Truy Tìm Hung Thủ', 'The Truth Is Murky', 'https://phimimg.com/upload/vod/20250228-1/81e3dfe4085bdce4bbbc3157d8d30bb1.jpg', 'https://phimimg.com/upload/vod/20250228-1/54836b2a977828d4089b54ae80c57bdd.jpg', '<p>Một đêm mưa bão, bảy người với những dáng vẻ khác nhau tạm trú trong một quán trọ hẻo lánh. Họ không biết rằng, khi màn đêm buông xuống, nguy hiểm sẽ đến một cách lặng lẽ. Mọi chuyện bắt đầu khi một người phục vụ chết một cách kỳ lạ, và sau đó, người tiếp theo lại chết! Đêm đó trở thành một trò chơi đầy giết chóc, mỗi người đều có mục đích riêng, và họ tìm kiếm kẻ giết người giữa những cái chết liên tiếp, nhưng kết quả lại liên tục thay đổi.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jia Zi","avatar":""},{"name":"Xie Shixin","avatar":""},{"name":"Hang Chengyu","avatar":""},{"name":"Ye Xinyu","avatar":""},{"name":"Liu Xinyu","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["寻凶","尋凶～薄暗い真相～","심흉 : 어슴푸레한 진상","หลังเงาฆาตกร","Truy Tìm Hung Thủ","尋凶","xun xiong"]', 1784690324160);
