INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-pho-quy-2025', 'Thành phố quỷ', 'Demon City', 'https://phimimg.com/upload/vod/20250227-1/4509454bf2861211b23c48f7cefec5f0.jpg', 'https://phimimg.com/upload/vod/20250227-1/2bd71b173cfe0d19644b5ad84d290f24.jpg', '<p>Bị đổ tội giết hại gia đình và bỏ mặc đến chết, sát thủ đã giải nghệ nọ tìm mọi cách để trả thù bọn &quot;quỷ&quot; đeo mặt nạ đã chiếm lấy thành phố của anh.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Toma Ikuta","avatar":""},{"name":"Masahiro Higashide","avatar":""},{"name":"Miou Tanaka","avatar":""},{"name":"Ami Touma","avatar":""},{"name":"Taro Suruga","avatar":""},{"name":"Mai Kiryu","avatar":""},{"name":"Naoto Takenaka","avatar":""},{"name":"Takuma Otoo","avatar":""},{"name":"Masahiro Takashima","avatar":""},{"name":"Matsuya Onoe","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["恶魔都市：鬼杀","鬼ゴロシ","Oni Goroshi","עיר השדים","Şeytan Şəhəri","დემონების ქალაქი","Demon City 鬼ゴロシ"]', 1784690324160);
