INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sau-chi-em', 'Sáu Chị Em', 'Six Sisters', 'https://phimimg.com/upload/vod/20250204-1/551b830b560d68ef270caa22f21df4e4.jpg', 'https://phimimg.com/upload/vod/20250204-1/7ebfdb7a8d8c0498b56fec154f8f36ed.jpg', '<p>Sau khi nước Trung Hoa mới được thành lập, Hà Thường Thắng quyết định rời quê hương Dương Châu, Giang Đô, đưa cả gia đình đến Hoài Nam, An Huy để góp sức xây dựng chủ nghĩa xã hội, lập nghiệp bên bờ sông Hoài. Trong hai mươi năm tiếp theo, ông lần lượt chào đón sáu cô con gái, nhưng một tai nạn xe cộ bất ngờ đã cướp đi sinh mạng của ông. Chị cả Hà Gia Lệ cùng bà nội Hà Văn Thị và mẹ Lưu Mỹ Tâm gánh vác trọng trách gia đình, giúp các em gái thành gia lập nghiệp. Thời thế đổi thay, sáu chị em nhà họ Hà cũng trải qua những thăng trầm trong tình yêu, hôn nhân, công việc và cuộc sống. Nhưng dù đối diện với bao sóng gió trong cuộc sống, họ vẫn luôn đoàn kết một lòng. Trải qua những thử thách trong đời, cuối cùng họ cũng thấu hiểu lời dặn dò mà người cha quá cố từng nhấn mạnh - ý nghĩa của hai chữ &quot;gia đình&quot;.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Mai Đình","avatar":""},{"name":"Lục Nghị","avatar":""},{"name":"Ổ Quân Mai","avatar":""},{"name":"Hề Mỹ Quyên","avatar":""},{"name":"Lưu Quân","avatar":""},{"name":"Ngô Thiến","avatar":""},{"name":"Cao Lộ","avatar":""},{"name":"Dĩnh Nhi","avatar":""},{"name":"Tào Phỉ Nhiên","avatar":""},{"name":"Lạt Mục Dương Tử","avatar":""},{"name":"Đổng Khiết","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Six Sisters","Six.Sister","Seis Hermanas","Seis Irmãs","Шесть сестёр","六姊妹"]', 1784690324160);
