INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tren-dong-tro-tan', 'Trên Đống Tro Tàn', 'The Embers', 'https://phimimg.com/upload/vod/20250208-1/ef6521c179fb12b253d88994048f172f.jpg', 'https://phimimg.com/upload/vod/20250208-1/b8edc0cb6fcdd41a989516a6d2ba9986.jpg', '<p>Vụ thảm án diệt môn thời thơ ấu khiến vận mệnh của hai anh em nhà họ Liêu thay đổi hoàn toàn. Là tự xông qua bóng tối cứu rỗi bản thân hay là rơi xuống vực sâu để trả thù? Hai anh em từng thân thiết vô cùng, phá liên tiếp bao vụ án kỳ lạ tới cuối lại đứng về hai phía trắng, đen đối lập.</p>', 'Tập 28', 28, 'series', 'ongoing', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Tử Kỳ","avatar":""},{"name":"Tôn Dương","avatar":""},{"name":"Tôn Di","avatar":""},{"name":"Lưu Mẫn Đào","avatar":""},{"name":"Trương Vũ Kiếm","avatar":""},{"name":"Đinh Tiếu Oánh","avatar":""},{"name":"Hoàng Duy Đức","avatar":""},{"name":"Trần Nhược Huyên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["余烬之上","The Embers"]', 1784690324160);
