INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tren-dong-tro-tan', 'Trên Đống Tro Tàn', 'The Embers', 'trên đống tro tàn the embers vương tử kỳ tôn dương tôn di lưu mẫn đào trương vũ kiếm đinh tiếu oánh hoàng duy đức trần nhược huyên 余烬之上 the embers', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kho-co-the-lua-chon', 'Khó Có Thể Lựa Chọn', 'Love''s Dilemma', 'https://phimimg.com/upload/vod/20250227-1/4145935b74c2ad5ba2025b3dd4af4e53.jpg', 'https://phimimg.com/upload/vod/20250227-1/afa6448b5b535eaed4bb8e0e01c19fa5.jpg', '<p>Giang Uyển Tình và Cận Mặc đã kết hôn được sáu năm, cuộc sống vốn dĩ hạnh phúc. Tuy nhiên, sau khi Cận Mặc đi công tác nước ngoài trở về, thái độ của anh đột nhiên thay đổi, trở nên lạnh lùng và xa cách. Hóa ra, trong chuyến đi, Cận Mặc gặp phải tai nạn khiến tủy sống bị tổn thương, có nguy cơ bị liệt. Để không trở thành gánh nặng cho gia đình, anh cố tình lạnh nhạt với Uyển Tình, hy vọng cô sẽ ly hôn. Tuy nhiên, Giang Uyển Tình lại hiểu lầm rằng Cận Mặc tái hợp với người yêu cũ Thẩm Hạ, nên quyết định ly hôn và bắt đầu thu thập bằng chứng ngoại tình. Cận Mặc thuận theo tình thế, muốn nhân cơ hội này để Uyển Tình hoàn toàn từ bỏ mình. Cuối cùng, Uyển Tình đề nghị ly hôn. Đúng lúc này, Cận Mặc phát hiện ra tai nạn của mình là do đồng nghiệp Cố Thành Phong gây ra, và Cố Thành Phong đang theo đuổi Uyển Tình. Lo lắng và bất an, Cận Mặc nhờ sự giúp đỡ của Thẩm Hạ để tìm bằng chứng chống lại Cố Thành Phong. Tuy nhiên, Uyển Tình và Cố Thành Phong lại quyết định đính hôn. Trong giây phút quyết định, Cận Mặc tìm đến Cố Thành Phong nhưng lại bị hắn làm tổn thương tủy sống lần nữa, khiến anh bị liệt. Khi Uyển Tình biết được sự thật, cô từ chối Cố Thành Phong và giao hắn cho pháp luật xử lý. Uyển Tình tìm đến Cận Mặc, hai người gặp lại nhau tại nơi họ từng gặp gỡ lần đầu tiên. Nhưng thời gian đã qua đi, những khoảnh khắc đã mất trở thành nỗi tiếc nuối không thể cứu vãn.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lan Bo","avatar":""},{"name":"Yu Xinyan","avatar":""},{"name":"Fu Honglin","avatar":""},{"name":"Yang Jingru","avatar":""},{"name":"Gao Tian","avatar":""},{"name":"He Yuchen","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Nan Yi Jue Ze","Difficult to Choose","难以抉择"]', 1784690324160);
