INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phuong-lau-truyen-truyen-thuyet-linh-ho', 'Phượng Lâu Truyện: Truyền Thuyết Linh Hồ', 'Fenglou Chronicles: Tale Of The Spirit Fox', 'https://phimimg.com/upload/vod/20250226-1/491e76073e9de377492b63b50cdc3cef.jpg', 'https://phimimg.com/upload/vod/20250226-1/5df76403ba0c35a5fe0c089c1cc56c7a.jpg', '<p>Ông của thiếu nữ loài người đã xúc phạm hồ tiên nơi rừng dã và bị giết hại. Mười tám năm sau, cô gái gả cho kẻ thù giết cha là Phượng Lâu để tìm cách báo thù. Đúng lúc này, nội bộ hồ tộc xảy ra tranh đấu, ông nội của Phượng Lâu, trưởng lão của hồ tộc cấu kết với thế lực Đông Doanh nhằm đoạt lấy vị trí thủ lĩnh hồ tộc. Không ngờ sau khi thức thần của người Đông Doanh đổ bộ, chúng điên cuồng tàn sát dân lành, hút cạn tinh khí. Trước tình cảnh đó, thủ lĩnh hồ tộc quyết định hy sinh bản thân để cứu lấy muôn dân.</p>', 'Full', 1, 'single', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhu Minxin","avatar":""},{"name":"Peng Jing","avatar":""},{"name":"Lu Zhuo","avatar":""},{"name":"Wang Zhengxuan","avatar":""},{"name":"Tang Yongyu","avatar":""},{"name":"Hong Yungang","avatar":""},{"name":"Yu Bufan","avatar":""},{"name":"Huo Zanchen","avatar":""},{"name":"Li Songci","avatar":""},{"name":"Fang Mengxi","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Legend of Phoenix Tower: Legend of the Fox","봉루전: 영호전설","凤楼传之灵狐传说"]', 1784690324160);
