INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phuong-lau-truyen-truyen-thuyet-linh-ho', 'Phượng Lâu Truyện: Truyền Thuyết Linh Hồ', 'Fenglou Chronicles: Tale Of The Spirit Fox', 'phượng lâu truyện: truyền thuyết linh hồ fenglou chronicles: tale of the spirit fox zhu minxin peng jing lu zhuo wang zhengxuan tang yongyu hong yungang yu bufan huo zanchen li songci fang mengxi legend of phoenix tower: legend of the fox 봉루전: 영호전설 凤楼传之灵狐传说', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-dau-y-hop', 'Tâm Đầu Ý Hợp', 'A Perfect Match', 'https://phimimg.com/upload/vod/20250225-1/a84c2ac97b6ab6cdd6c3d1415417b26a.jpg', 'https://phimimg.com/upload/vod/20250225-1/8065eb34bf87c952657e97f94c38ed90.jpg', '<p>Thành Thiên Tường là một chàng trai trẻ đam mê quần vợt. Mồ côi cha mẹ từ nhỏ, anh được bà nội nuôi nấng trưởng thành. Một ngày nọ, trên đường đi phỏng vấn cho một công ty quan trọng, anh đã lỡ hẹn vì dừng lại giúp đỡ cô bé Lâm Hiểu Nhược. Chính sự kiện này đã đưa anh vào quỹ đạo của Lâm Hiểu Nam – tổng giám đốc lạnh lùng và quyền lực của một tập đoàn lớn. Bề ngoài, Lâm Hiểu Nam luôn tỏ ra xa cách và nghiêm khắc, nhưng sâu thẳm trong lòng, anh dành trọn sự dịu dàng và bảo vệ cho em gái mình, Lâm Hiểu Nhược, vì cô bé có một hoàn cảnh đặc biệt. Thiên Tường từng bị tổn thương sâu sắc bởi sự phản bội của người yêu cũ Trương Vĩ Hùng. Vì muốn trèo cao, Vĩ Hùng đã ruồng bỏ anh để theo đuổi tiểu thư giàu có Lý Na, khiến trái tim Thiên Tường tan nát. Khi dần bước vào cuộc sống của anh em nhà họ Lâm, Thiên Tường không chỉ trở nên gắn bó với Hiểu Nhược mà còn vô tình thu hút sự chú ý của Hiểu Nam. Ban đầu, giữa họ là sự đối đầu và xa lánh, nhưng dần dần, Hiểu Nam bị sự chân thành và lương thiện của Thiên Tường làm rung động. Mối quan hệ của cả hai từ căng thẳng chuyển thành mập mờ, nhưng Hiểu Nam lại luôn giằng xé giữa lý trí và cảm xúc của chính mình. Đến cuối cùng, Thiên Tường không chỉ phải đối mặt với sự theo đuổi điên cuồng của Trương Vĩ Hùng mà còn phải nhìn thẳng vào tình cảm thực sự của mình dành cho Hiểu Nam. Sau nhiều hiểu lầm, đấu tranh và những thử thách tình cảm, cả hai cuối cùng cũng mở lòng, chấp nhận tình yêu dành cho nhau. Câu chuyện khép lại bằng hành trình trưởng thành của ba người, khi họ cùng nhau vượt qua những khó khăn, thử thách, để rồi tìm thấy tình yêu và ý nghĩa đích thực của cuộc sống.</p><p><br/></p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 15, 2025, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Chuck You","avatar":""},{"name":"Ricky Liu","avatar":""},{"name":"Wei Li Du","avatar":""},{"name":"Rainie Dun","avatar":""},{"name":"Lee Yo-jou","avatar":""},{"name":"Hui-Chen Ma","avatar":""},{"name":"Hsu Ni-en","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["一拍即合"]', 1784690324160);
