INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trien-chieu-tham-an', 'Triển Chiêu Thám Án', 'The Story Of Detective Zhan Zhao', 'https://phimimg.com/upload/vod/20250223-1/aa65ba52206e9841043542c991d17623.jpg', 'https://phimimg.com/upload/vod/20250223-1/c6d3d7cf423961285e80a64e96e17939.jpg', '<p>Năm Gia Hữu thứ tư thời Bắc Tống, vụ án buôn lậu muối tư chấn động triều đình bị phanh phui, kéo theo việc Trương Khả Cửu, quan chuyển vận vùng Hoài Nam bị lộ tội danh câu kết với người Liêu phản quốc. Khai Phong phủ nhận lệnh bắt giữ, Triển Chiêu lập tức ra tay. Nghe tin, Trương Khả Cửu vội vã bỏ trốn dưới sự giúp đỡ của do thám nước Liêu. Một cuộc đối đầu lớn hơn, ẩn sau vụ án muối tư đang âm thầm khởi động.</p>', 'Full', 1, 'single', 'completed', 5, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"王轩","avatar":""},{"name":"Li Xingyao","avatar":""},{"name":"卢星月","avatar":""},{"name":"Yi Shi","avatar":""},{"name":"Zhang Junjie","avatar":""},{"name":"高明","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Zhan Zhao: Detective Cases","Zhan Zhao Tan An","展昭·探案"]', 1784690324160);
