INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doan-doc', 'Đoạn Độc', 'Anti Drug Operations', 'https://phimimg.com/upload/vod/20250222-1/c91ac970cbe8eee6dc214667597286d2.jpg', 'https://phimimg.com/upload/vod/20250222-1/383d978cb2e88e4a5815ff8ec5760ff3.jpg', '<p>Đội trưởng đặc cảnh Thẩm Ngạo được điều đến đội chống ma túy trên một hòn đảo. Một cuộc thanh trừng lẫn nhau giữa các băng nhóm buôn ma túy đã khiến Tân Ngô lọt vào tầm ngắm của cảnh sát. Thẩm Ngạo xác định được tuyến đường vận chuyển ma túy do băng nhóm mới thiết lập thông qua máy bay không người lái. Con gái của đội trưởng là Lưu Băng bị bọn buôn ma túy bắt cóc. Thẩm Ngạo một mình đột nhập vào hòn đảo hoang để giải cứu Lưu Băng và thực thi chiến dịch triệt phá đường dây ma túy.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Liu Junxiao","avatar":""},{"name":"Wang Tao","avatar":""},{"name":"Huang Junpeng","avatar":""},{"name":"Ken Lok Tat-Wah","avatar":""},{"name":"Vincent Lam Wai","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Detoxification","Duan Du","Anti-Drug Operations","断毒"]', 1784690324160);
