INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-sinh-ca-biet', 'Học Sinh Cá Biệt', 'Study Group', 'https://phimimg.com/upload/vod/20250124-1/690dbf120925af173f5b01e0821b46f0.jpg', 'https://phimimg.com/upload/vod/20250124-1/986b7f18c6154a4b72d9f6292e55f6a6.jpg', '<p>Học Sinh Cá Biệt xoay quanh hành trình vươn lên trong học tập đầy cam go của cậu học sinh chỉ giỏi đánh nhau Yun Ga Min. Học tại một trường trung học đầy tai tiếng với thành phần học sinh đa số thuộc diện cá biệt, Ga Min vẫn nuôi quyết tâm cải thiện học lực để có thể vào được đại học. Để đạt được mục tiêu này, cậu thành lập một nhóm học tập với một nhóm bạn học đa dạng. Cùng nhau, họ đối mặt với những thử thách trong cuộc sống học đường, bao gồm áp lực học hành, nạn bắt nạt và đủ thứ vấn đề khác của tuổi mới lớn.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 12, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Minhyun","avatar":""},{"name":"Han Ji-eun","avatar":""},{"name":"Cha Woo-min","avatar":""},{"name":"Shin Su-hyun","avatar":""},{"name":"Yun Sang-jeong","avatar":""},{"name":"Gong Do-yu","avatar":""},{"name":"Lee Kwang-hee","avatar":""},{"name":"Lee Jong-hyun","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["学习小组","Study group","Исследовательская группа","مجموعة دراسية","กลุ่มติวเดือด เลือดนักสู้","Học Nhóm","스터디그룹"]', 1784690324160);
