INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoc-sinh-ca-biet', 'Học Sinh Cá Biệt', 'Study Group', 'học sinh cá biệt study group minhyun han ji-eun cha woo-min shin su-hyun yun sang-jeong gong do-yu lee kwang-hee lee jong-hyun 学习小组 study group исследовательская группа مجموعة دراسية กลุ่มติวเดือด เลือดนักสู้ học nhóm 스터디그룹', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('my-nhan-tro-ve', 'Mỹ Nhân Trở Về', 'Return Of Fated Love', 'https://phimimg.com/upload/vod/20250216-1/b42e46ec4b43d72ec6e654271eee815b.jpg', 'https://phimimg.com/upload/vod/20250216-1/200f3fb56faa62cb22e791efc02f4670.jpg', '<p>Dư Sơ Tâm và Châu Sở Minh vốn là một cặp vợ chồng yêu nhau sâu đậm, nhưng cuối cùng cuộc hôn nhân của họ tan vỡ vì sự chen chân của Lâm Thanh Thanh. Không chỉ mất đi đứa con, Dư Sơ Tâm còn suýt mất mạng. Cô tuyệt vọng nghĩ đến những gì mà mình và gia đình gặp phải, cố chống tinh thần đang trên bờ vực sụp đổ. Cô quyết định giả vờ bị mất trí nhớ có chọn lọc, giữ ký ức dừng lại ở thời điểm mới kết hôn với Châu Sở Minh. Nhờ đó cô có thể quay lại nhà họ Châu, âm thầm thu thập chứng cứ, từng bước khiến những kẻ đã hại cô phải trả giá thích đáng.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Bao Thần Hi","avatar":""},{"name":"Ngô Quý Phong","avatar":""},{"name":"Khuất Uyển Quỳnh","avatar":""},{"name":"Vương Sâm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Beauty Returns","丽人归来"]', 1784690324160);
