INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('my-nhan-tro-ve', 'Mỹ Nhân Trở Về', 'Return Of Fated Love', 'mỹ nhân trở về return of fated love bao thần hi ngô quý phong khuất uyển quỳnh vương sâm the beauty returns 丽人归来', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ly-cau-oa', 'Lý Cẩu Oa', 'Legal Boy', 'https://phimimg.com/upload/vod/20250208-1/6d7fd75cd33ff004ed5c3acab0d66835.jpg', 'https://phimimg.com/upload/vod/20250208-1/42c7852793359f574e8a4ff7513a2ea3.jpg', '<p>Vận may giàu sang ập đến bất ngờ, anh công nhân nghèo Lý Cẩu Oa vô tình bước chân vào thế giới của gia đình giàu có, chỉ với mục đích đòi lại công bằng cho người anh em. Nhưng không ngờ tất cả lại là một âm mưu giết người được tính toán kỹ lưỡng. Sự xuất hiện của anh đã châm ngòi cho cuộc chiến thừa kế của tập đoàn Đông Xán, ba người con nhà họ Trương lao vào đấu đá không khoan nhượng, âm mưu chồng chất. Lý Cẩu Oa tầm ngẩm tầm ngầm mà đấm chết voi, từng bước thâm nhập vào vòng xoáy hiểm ác. Đối mặt với đám người lòng lang dạ sói này, anh như một con gián đánh mãi không chết, vượt qua nghịch cảnh hết lần này đến lần khác. Cuối cùng, Lý Cẩu Oa theo đuổi chính nghĩa đã lật đổ kim tự tháp quyền lực, phá được tình thế nan giải.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Tuấn Đình","avatar":""},{"name":"Diêu Tiểu Tiểu","avatar":""},{"name":"Dương Y Mặc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Li Gou Wa","李狗娃"]', 1784690324160);
