INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hem-nui', 'Hẻm Núi', 'The Gorge', 'https://phimimg.com/upload/vod/20250215-1/8f4d09ca4d943890833a636050a0e5cb.jpg', 'https://phimimg.com/upload/vod/20250215-1/50b69d7f9fae15d537496885795691bf.jpg', '<p>Hai đặc vụ được huấn luyện bài bản dần trở nên thân thiết từ xa sau khi được cử đến canh gác hai bên hẻm núi bí ẩn. Khi thế lực tà ác ở bên dưới xuất hiện, họ phải hợp tác để sống sót trước những gì ẩn chứa bên trong.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Miles Teller","avatar":""},{"name":"Anya Taylor-Joy","avatar":""},{"name":"Sigourney Weaver","avatar":""},{"name":"Sope Dirisu","avatar":""},{"name":"William Houston","avatar":""},{"name":"Kobna Holdbrook-Smith","avatar":""},{"name":"James Marlowe","avatar":""},{"name":"Julianna Kurokawa","avatar":""},{"name":"Ruta Gedmintas","avatar":""},{"name":"Oliver Trevena","avatar":""},{"name":"Samantha Coughlan","avatar":""},{"name":"Alessandro Garcia","avatar":""},{"name":"Greta Hansen","avatar":""},{"name":"Adam Scott-Rowley","avatar":""},{"name":"Sachin Bhatt","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["La inmensidad","더 캐니언","The Canyon","הגיא","Tarpeklis","Ущелье","禁谷","Hẻm Núi","峡谷","ხეობა","الأخدود","The Gorge"]', 1784690324160);
