INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-bup-be-cua-gabby-phan-11', 'Nhà Búp Bê Của Gabby (Phần 11)', 'Gabby''s Dollhouse (Season 11)', 'https://phimimg.com/upload/vod/20250221-1/03c71d26be91a4557ea5c1db44f143bf.jpg', 'https://phimimg.com/upload/vod/20250221-1/e048817e36f48a4a66d6d4ed4bfc6668.jpg', '<p>Những chú mèo đáng yêu, đồ thủ công kỳ quặc và ma thuật đầy màu sắc! Hãy cùng cô bạn mê mèo Gabby và trợ thủ Pandy Paws bước vào vô vàn các chuyến phiêu lưu hoạt hình.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Laila Lockhart Kraner","avatar":""}]', '[{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["개비의 매직하우스","Волшебный домик Габби","Gabby''s Dollhouse"]', 1784690324160);
