INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('marketing-khong-chinh-thuc', 'Marketing Không Chính Thức', 'Buzz Marketing', 'https://phimimg.com/upload/vod/20250220-1/901054f46a8518d32b43f05584a35b90.jpg', 'https://phimimg.com/upload/vod/20250220-1/14929bab046bf7183c2ee7bff5af29e0.jpg', '<p>Khởi Minh đầy tự tin đến Đại Vịnh, tưởng rằng với kinh nghiệm và hiểu biết của mình, anh có thể nhanh chóng tạo dựng được chỗ đứng. Nhưng không ngờ những người có hồ sơ tương tự như anh ở Đại Vịnh không hề ít, và vì vấn đề ngôn ngữ, anh liên tục gặp trở ngại trong việc tìm kiếm công việc. Khi đang bối rối và muốn từ bỏ, anh đã gặp được một vài người bạn có cùng chí hướng. Mặc dù năm người họ có tính cách và xuất thân khác nhau, nhưng đều tràn đầy hy vọng về tương lai. Trong các cuộc trò chuyện, Khởi Minh nhận thấy khả năng và tính cách của năm người họ bổ sung cho nhau, có thể cùng nhau khởi nghiệp. Do đó, dưới sự dẫn dắt của Khởi Minh, họ đã thành lập Công ty Khởi Minh với quyết tâm phá vỡ những suy nghĩ truyền thống và biến nó thành một công ty tiếp thị nổi tiếng, phù hợp nhất với tâm lý người tiêu dùng hiện nay.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Gao Xuyang","avatar":""},{"name":"Qi Peixin","avatar":""},{"name":"Zhou Tishun","avatar":""},{"name":"Chen Jieyi","avatar":""},{"name":"Zhang Xinghe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["非正式营销"]', 1784690324160);
