INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lao-thi-thuong-xuat-hien', 'Lão Thị Thường Xuất Hiện', 'Golden Oldies', 'https://phimimg.com/upload/vod/20250220-1/63890cdb07dbc965f3c1e00107c4406b.jpg', 'https://phimimg.com/upload/vod/20250220-1/4afe43fa071eeb775bbb10d82866fc66.jpg', '<p>Trung niên thất bại A Su rời khỏi &#39;địa ngục trần gian&#39; của tổ chức lừa đảo, và tình cờ gia nhập Trại dưỡng lão Trương, nơi anh được giao trọng trách làm quản lý hành chính. A Su nắm bắt cơ hội và nỗ lực làm lại cuộc đời, nhưng phát hiện ra rằng các thành viên trong trại dưỡng lão đều là những nhân vật &#39;cao thủ giấu mình&#39;, không hề đơn giản. Các nhân vật đặc biệt trong trại bao gồm: ông chủ, tài tử hết thời Kimura, cựu lính cứu hỏa hài hước Chú Mèo và cựu biên tập viên tinh nghịch Bà Mèo, cùng tạo nên nhóm &#39;cư dân mạnh nhất&#39;, gây ra đủ loại chuyện rắc rối mỗi ngày. Các nhân viên cũng không kém phần nổi bật: A Ca tham vọng quá mức, Nana bề ngoài ngọt ngào nhưng thực chất hiểm ác, Ban Ban tràn đầy năng lượng tiêu cực và Martin cực kỳ trong sáng và tốt bụng, luôn đóng vai trò là &#39;đồng đội vô địch&#39; khiến A Su thêm đau đầu. Cùng với cặp đôi tình yêu trong sáng hơn cả &#39;First Love&#39; là Liên Muội và Peter, Trại dưỡng lão Trương mỗi ngày đều diễn ra những câu chuyện điên rồ khác nhau, khiến A Su mệt mỏi nhưng đồng thời cũng vui vẻ trong vô thức.</p><p><br/></p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Trần Chiến Văn","avatar":""},{"name":"Trần Nhất Thâm","avatar":""},{"name":"Lưu Giang","avatar":""},{"name":"Thạch Tú","avatar":""},{"name":"Trương Lỗi","avatar":""},{"name":"Lưu Bội Hằng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["老是常出现","Golden Oldies","老是常出現"]', 1784690324160);
