INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-linh-me-vu', 'Tâm Linh Mê Vụ', 'Lies Never Lie', 'https://phimimg.com/upload/vod/20250209-1/007fe35006a923e0985a7dc78e0ab21d.jpg', 'https://phimimg.com/upload/vod/20250209-1/ba4d7d2e8535d02b7fb17b09d7eceef9.jpg', '<p>Sau khi chuyên gia tâm lý Lý Mạc Sầu gia nhập vào Cục Công an thành phố Bạch Châu, đội trưởng đội cảnh sát hình sự Đinh Uy như hổ mọc thêm cánh. Nhờ khả năng phác họa tâm lý của Lý Mạc Sầu, Đinh Uy đã dẫn dắt cả đội phá giải hàng loạt vụ án kỳ lạ, đồng thời khiến hung thủ đứng sau một vụ án nghiêm trọng nhiều năm trước phải lộ diện. Sự thật bị vùi lấp bấy lâu cuối cùng cũng được đưa ra ánh sáng.</p>', 'Tập 21', 21, 'series', 'ongoing', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Chân Nhi","avatar":""},{"name":"Lý Viện","avatar":""},{"name":"Vương Bạc Văn","avatar":""},{"name":"Lưu Lâm Thành","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Xin Ling Mi Wu","Lies Never Lie","心灵迷雾"]', 1784690324160);
