INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lat-tay-toi-ac', 'Lật Tẩy Tội Ác', 'Unmasked', 'https://phimimg.com/upload/vod/20250117-1/5c8d7696c91b2c3d825a1a22b073f59a.jpg', 'https://phimimg.com/upload/vod/20250117-1/b7e3ca6cd43dcca20a3879611519e0cf.jpg', '<p>Khám phá sự thật đầy kịch tính trong Lật Tẩy Tội Ác - Unmasked (2025), khi nhóm phóng viên dũng cảm bắt tay vào cuộc truy tìm với những bí ẩn kỳ lạ. Với sự hấp dẫn từ đội trưởng Trigger đầy chí nghĩa và PD theo lối tư duy cực đoan, họ đã không chỉ cứu rỗi một chương trình sắp tan rã mà còn mang lại cho khán giả những trải nghiệm đầy hành động, tính hài hước và không thể dự đoán. Đạo diễn Yoo Seon Dong đã tạo nên một tác phẩm xuất sắc với sự tham gia của các diễn viên tài năng như Kim Hye Soo, Jung Sung Il, Joo Jong Hyuk, Jang Hye Jin, Lee Hae Young và Shin Jung Keun.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Hye-soo","avatar":""},{"name":"Jung Sung-il","avatar":""},{"name":"Joo Jong-hyuk","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["揭秘最前线","트리거(디즈니+)","Unmasked","Trigger","트리거"]', 1784690324160);
