INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cay-o-liu-mau-trang', 'Cây Ô Liu Màu Trắng', 'The White Olive Tree', 'https://phimimg.com/upload/vod/20250202-1/2cd5be78b8084ab8787ec2596b0dea29.jpg', 'https://phimimg.com/upload/vod/20250202-1/790ed4d25806cbf45b6b12e6ca137393.jpg', '<p>Cây Ô Liu Màu Trắng khắc họa mối tình lãng mạn nhưng không kém phần chông gai giữa cô phóng viên Tống Nhiễm và anh quân nhân Lý Toản. Trong một lần đi thực hiện nhiệm vụ phỏng vấn, Tống Nhiễm quen biết Lý Toản khi được anh giải cứu khỏi nguy hiểm. Tình yêu giữa hai người nảy nở, nhưng chưa được bao lâu thì biến cố ập đến, khiến họ phải chia xa. Ngày gặp lại, cả hai đều mang trên người nhiều tổn thương về thể xác lẫn tinh thần. Họ sẽ làm thế nào để có thể chữa lành cho nhau?</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 10, 2025, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Triết Viễn","avatar":""},{"name":"Vương Thiên Thần","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["白色橄榄树"]', 1784690324160);
