INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-trong-kinh-moi', 'Trân Trọng Kính Mời', 'You''re Cordially Invited', 'https://phimimg.com/upload/vod/20250219-1/4cca6a74360f94afc620cc92f0f9d734.jpg', 'https://phimimg.com/upload/vod/20250219-1/1692253256b7fe38f12f3dc4c2856cfd.jpg', '<p>Khi hai đám cưới vô tình được đặt vào cùng một ngày tại cùng một địa điểm, mỗi bữa tiệc cô dâu được thử thách với việc bảo tồn khoảnh khắc đặc biệt của gia đình họ trong khi tận dụng tối đa các khu vực kín đáo không được dự đoán. Trong một trận chiến quyết tâm và nghiệt ngã vui nhộn, cha của cô dâu và em gái của cô dâu khác đã trò chuyện trực tiếp khi họ dừng lại không có gì để duy trì một lễ kỷ niệm khó quên cho những người thân yêu của họ.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Will Ferrell","avatar":""},{"name":"Reese Witherspoon","avatar":""},{"name":"Geraldine Viswanathan","avatar":""},{"name":"Meredith Hagner","avatar":""},{"name":"Jimmy Tatro","avatar":""},{"name":"Stony Blyden","avatar":""},{"name":"Leanne Morgan","avatar":""},{"name":"Rory Scovel","avatar":""},{"name":"Keyla Monterroso Mejia","avatar":""},{"name":"Ramona Young","avatar":""},{"name":"Jack McBrayer","avatar":""},{"name":"Fortune Feimster","avatar":""},{"name":"Celia Weston","avatar":""},{"name":"Martha B. Knighton","avatar":""},{"name":"Bobby Moynihan","avatar":""},{"name":"Ava Hi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Cordialmente Convidados","Youre Cordially Invited","Сердечно Приглашены","热情邀约","You''re Cordially Invited"]', 1784690