INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-cua-toi-luan-don', 'Lỗi Của Tôi: Luân Đôn', 'My Fault: London', 'https://phimimg.com/upload/vod/20250219-1/f3746062e048ac2a137e39828ff224b8.jpg', 'https://phimimg.com/upload/vod/20250219-1/9b4ef6286e46f125a56cd6c0887d7185.jpg', '<p>Phim là phiên bản làm lại bằng tiếng Anh của bộ phim Tây Ban Nha nổi tiếng &quot;Culpa Mía&quot; (tựa Việt: &quot;Lỗi Của Tôi&quot;) và dựa trên tiểu thuyết cùng tên của tác giả Mercedes Ron. Noah, một cô gái 18 tuổi, chuyển từ Mỹ đến London sau khi mẹ cô, Ella, kết hôn với William, một doanh nhân giàu có người Anh. Tại đây, Noah gặp Nick, con trai của William và cũng là anh kế của cô. Mặc dù ban đầu có mâu thuẫn, nhưng giữa họ dần nảy sinh một sự hấp dẫn mạnh mẽ. Trong khi Noah cố gắng thích nghi với cuộc sống mới và đối mặt với quá khứ đau buồn, cô phải đối diện với những cảm xúc phức tạp dành cho Nick.</p>', 'Full', 1, 'single', 'completed', 18, 2025, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Asha Banks","avatar":""},{"name":"Matthew Broome","avatar":""},{"name":"Eve Macklin","avatar":""},{"name":"Ray Fearon","avatar":""},{"name":"Enva Lewis","avatar":""},{"name":"Jason Flemyng","avatar":""},{"name":"Kerim Hassan","avatar":""},{"name":"Sam Buchanan","avatar":""},{"name":"Amelia Kenworthy","avatar":""},{"name":"Harry Gilby","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["俺の過ち ロンドン編","My Fault London คำขอโทษ: ลอนดอน","À contre-sens Londres","À contre-sens - Londres","À contre-sens, Londres","我的错误：伦敦版","À Contre-Sens : Londres","Culpa Mía London","My Fault: London"]', 1784690324160);
