INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('soi-len-ky-la', 'Sợi Len Kỳ Lạ', 'The Yarn', 'https://phimimg.com/upload/vod/20250218-1/f9d7154b587d1fc009335c35e8712f76.jpg', 'https://phimimg.com/upload/vod/20250218-1/57248d0e19ace0ef33475f98c14174b7.jpg', '<p>Phim kể về câu chuyện của một kẻ giết người hàng loạt không để lại dấu vết, chỉ để lại những cuộn len được đan kỳ lạ trên các nạn nhân. Thanh tra Pilanthorn hợp tác với Sky, một phụ nữ tự kỷ có khả năng phi thường để giải mã các mẫu phức tạp, nhằm tìm ra ý nghĩa đằng sau những cuộn len và ngăn chặn kẻ giết người trước khi vụ án mạng tiếp theo xảy ra.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Bua Nalinthip Sakulongumpai","avatar":""},{"name":"Chaiyapol Poupart","avatar":""},{"name":"Neen Chatchaya Samroengraja","avatar":""},{"name":"Heng Thatpong Rojsangruang","avatar":""},{"name":"Hattaya Wongkrachang","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["ปริศนาปมไหม"]', 1784690324160);
