INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuoc-dao-mon-truyen-ky-phan-2', 'Thước Đao Môn Truyền Kỳ (Phần 2)', 'Legend Of The Undercover Chef (Season 2)', 'https://phimimg.com/upload/vod/20250122-1/17ded45f502cb0991dd4e37aa749728e.jpg', 'https://phimimg.com/upload/vod/20250122-1/0a8a143014035cdbfa21301fa949a6d9.jpg', '<p>Tây Môn Trường Hải gặp nạn mà không chết, và đã trở về liên minh Định Nguyên sau khi bình phục, tiếp tục gánh vác trách nhiệm bảo vệ biên cương, chiến đấu chống lại giặc Nhật. Huynh trưởng của y là Tây Môn Trường Tại cũng dần trở thành thủ lĩnh của Thước Đao Môn, thỉnh thoảng đắm mình và tận hưởng thế giới đại hiệp tưởng tượng. Giặc Nhật không vì thất bại mà rút lui, chúng thay phiên nhau xuất hiện, cố gắng thu thập thông tin về các thế lực khác đang cạnh tranh với chúng từ Tây Môn Trường Hải. Vua Cẩm Lô có ý đồ tạo phản, tình cờ gặp Cao Đại Mao cải trang thành thầy bói, tưởng Cao Đại Mao là một vị cao thủ phi phàm, thành tâm mời Cao Đại Mao xuống núi, giao cho chức thiên sư. Vương công công từ kinh đô đi tịch thu tài sản nhà họ Tào, vô tình phát hiện ra cháu trai của Tào công công là Tào Đông Đông. Để được sống sót, Tào Đông Đông đã mượn danh bảo vật lừa gạt lòng tin của Vương công công, nhờ đó mà thoát nạn. Các thế lực khác nhau đã tập trung tại Liêu Đông, Thước Đao Môn bị cuốn vào một trận sóng gió mới. Hai huynh đệ Trường Hải và Trường Tại đã cùng các đệ tử chung tay chiến đấu chống lại kẻ thù ngoại xâm. Cuối cùng họ đã cùng nhau tiêu diệt giặc Nhật, vua Cẩm Lô và các thế lực thù địch khác, mang lại hòa bình và sự yên bình đã mất từ lâu cho Liêu Đông.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Bổn Sơn","avatar":""},{"name":"Tống Tiểu Bảo","avatar":""},{"name":"Tống Hiểu Phong","avatar":""},{"name":"Văn Tống","avatar":""},{"name":"Trình Dã","avatar":""},{"name":"Lịch Hiểu Hạ","avatar":""},{"name":"Cát San San","avatar":""},{"name":"Đường Giám Quân","avatar":""},{"name":"Dương Thụ Lâm","avatar":""},{"name":"Trương Tiểu Anh","avatar":""},{"name":"Vương Tiểu Hổ","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Que Dao Men Chuan Qi","鹊刀门传奇 2","鹊刀门传奇 第二季","Legend of the Undercover Chef","鹊刀门传奇"]', 1784690324160);
