INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('man-thanh', 'Mạn Thành', 'City Of Romance', 'https://phimimg.com/upload/vod/20250214-1/ba8bb50bffaf0e1f043939ff7e9b292a.jpg', 'https://phimimg.com/upload/vod/20250214-1/4c72fd6d7fae55011785f864aed3ad5a.jpg', '<p>Câu chuyện kể về Bạch Tiểu Đóa, một cô gái từng bị bị lực học đường thời trung học, đã vượt qua hàng ngàn Black. Tuy nhiên, câu lạc bộ truyện tranh mà cô hướng đến đang đứng trước nguy cơ giải thể. Black, hành thật sự chính là Black. làngười Tiểu Đóa. hiểu nhau, cả hai dần dần chữa lành những vết thương lòng sâu kín trong tâm hồn nhau.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yu Chengen","avatar":""},{"name":"Wang Zixuan","avatar":""},{"name":"Gao Maotong","avatar":""},{"name":"Lin Qiyu","avatar":""},{"name":"Xu Bin","avatar":""},{"name":"Jane Xiong","avatar":""},{"name":"Xiao Yuanxi","avatar":""},{"name":"Feng Yiran","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Man Cheng","我不是坏女生","漫城"]', 1784690324160);
