INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nha-nghi-california', 'Nhà Nghỉ California', 'Motel California', 'https://phimimg.com/upload/vod/20250110-1/47b3ff5975c16f3115b9e34337b610ec.jpg', 'https://phimimg.com/upload/vod/20250110-1/b250e2e073af4782ee3b2b3a1f685e77.jpg', '<p>Phim được sản xuất dựa trên cuốn tiểu thuyết Home, Bitter Home năm 2019 của Shim Yoon Seo. Trong đó: Lee Se Young vào vai Ji Kang Hee, một cô gái sinh ra và lớn lên trong một nhà nghỉ ở vùng quê. Vì cha cô quản lý nhà nghỉ nên nhà cũng chính là nơi làm việc. Ji Kang Hee là con lai, sinh ra giữa một người cha nhiều chuyện nhất vùng và một người mẹ ngoại quốc. Hoàn cảnh gia đình đặc biệt khiến cô lớn lên giữa những lời bàn tán, mang trong mình nhiều tổn thương. Kang Hee yêu người bạn thời thơ ấu Cheon Yeon Soo (Na In Woo), nhưng vào ngày sinh nhật thứ 20 của mình, cô đã bỏ lại mối tình đầu, gia đình và lên thành phố theo đuổi ước mơ trở thành nhà thiết kế nội thất. 12 năm sau, khi đang ở đỉnh cao sự nghiệp, cô bất đắc dĩ phải trở về Motel California, gặp lại mối tình đầu Yeon Soo và đối mặt với quá khứ mà cô muốn quên đi. Na In Woo sẽ vào vai Cheon Yeon Soo - chàng trai chung tình, chỉ yêu một người con gái duy nhất, và cũng là bác sĩ thú y được mọi người trong vùng yêu mến. Cheon Yeon Soo có tính cách trong sáng và ấm áp. Để tránh sự quan tâm quá mức từ những người hàng xóm muốn mai mối, anh đã để mặc tin đồn mình sắp kết hôn với một đồng nghiệp nữ. Cuộc sống bình yên của anh bỗng chốc bị đảo lộn khi Kang Hee, mối tình đầu mà anh luôn mong nhớ, trở về sau 12 năm. Anh bị Kang Hee hiểu lầm là sắp kết hôn với người khác. Tuy nhiên, cuộc gặp gỡ này cũng chính là cơ hội để anh chữa lành những vết thương trong quá khứ và bắt đầu một tình yêu mới.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Se-young","avatar":""},{"name":"Na In-woo","avatar":""},{"name":"Choi Min-soo","avatar":""},{"name":"Kim Tae-hyung","avatar":""},{"name":"Choi Hee-jin","avatar":""},{"name":"Oh Seung-ah","avatar":""},{"name":"Ji Soo-won","avatar":""},{"name":"Woo Mi-hwa","avatar":""},{"name":"Koo Ja-sung","avatar":""},{"name":"Jung Yong-ju","avatar":""},{"name":"Seo Ye-hwa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["加州汽車旅館","모텔 캘리포니아","Мотель Калифорния","فندق كاليفورنيا"]', 1784690324160);
