INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gui-toi-cua-nam-1999', 'Gửi Tôi Của Năm 1999', 'Reopen My Journals', 'https://phimimg.com/upload/vod/20250124-1/d40d1d57158e27ff473bb545a6a213bd.jpg', 'https://phimimg.com/upload/vod/20250124-1/a48cf8733a475076efa986721e79a8de.jpg', '<p>&quot;Cô bé ngoan ngoãn&quot; Tiền Giai Nguyệt, 15 tuổi, thi đỗ vào trường trung học trọng điểm, bắt đầu đối mặt với nhiều thử thách trong học tập. Kế hoạch tỏ tình với anh hàng xóm Tiêu Hàm, một đàn anh học giỏi, cuối cùng cũng không thành công. Em trai nuôi Mao Đầu tuy thông minh nhưng lại thường xuyên gây rắc rối. Tiền Giai Nguyệt kết bạn với người bạn mới là Trần Mạt, một cô gái cá tính và mạnh mẽ, và họ cùng trưởng thành trong tình bạn. Đồng thời, bố mẹ của các cô gái cũng trải qua khủng hoảng tình cảm, dẫn đến nhiều xáo trộn gia đình và một loạt thay đổi lớn trong cuộc sống. Trần Tú Nga, một phụ nữ tri thức, trở về thành phố, nhưng vì không thường xuyên ở bên cạnh Tiền Giai Nguyệt nên giữa hai mẹ con dần xuất hiện sự xa cách. Khi bà ngoại Trần qua đời, những khúc mắc tình cảm giữa ba thế hệ cuối cùng cũng được hóa giải. Trần Bành Vũ, người luôn tự xem mình là tinh anh, lại nuôi dạy nên một cô con gái &quot;không có chí&quot; và nổi loạn là Trần Mạt. Sau nhiều xung đột với con gái, ông nhận ra rằng mỗi thế hệ đều có &quot;sứ mệnh&quot; riêng của mình. Quan Ái Bình, người phụ nữ mạnh mẽ, đã một mình nuôi dạy Tiêu Hàm sau khi thất nghiệp. &quot;Ông chủ nhỏ&quot; Trương Khải Minh phải học cách chung sống hòa hợp với cậu con trai nghịch ngợm Mao Đầu, và sau nhiều biến cố, đã tái hợp gia đình với Quan Ái Bình. Thời đại có thể thay đổi, nhưng tình thân ấm áp và tình làng nghĩa xóm vẫn luôn trường tồn qua thời gian.</p>', 'Tập 33', 33, 'series', 'ongoing', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Quân Nhuệ","avatar":""},{"name":"Hoàng Dương Điền Điềm","avatar":""},{"name":"Nghê Hồng Khiết","avatar":""},{"name":"Dương Hạo Vũ","avatar":""},{"name":"Đổng Khiết","avatar":""},{"name":"Dụ Ân Thái","avatar":""},{"name":"Trần Hạc Nhất","avatar":""},{"name":"Trương Hân Ý","avatar":""},{"name":"Huỳnh Nghị","avatar":""},{"name":"Trần Phương Đồng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["致15岁","우리들의 1999","致1999年的自己"]', 1784690324160);
