INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('umjolo-yeu-vo-phuong-cuu', 'Umjolo: Yêu Vô Phương Cứu', 'Umjolo: There Is No Cure', 'https://phimimg.com/upload/vod/20250215-1/c367dc75aab460d6db4b4dcb12fa49f2.jpg', 'https://phimimg.com/upload/vod/20250215-1/898ab53a7c1edf1182f4116b01ccb7f3.jpg', '<p>Sau khi mất danh hiệu vì công khai vạch trần một vụ bê bối, cựu hoa hậu nọ viết một cuốn sách tiết lộ mọi chuyện – trong khi chuyện tình cảm của cô vẫn còn bỏ ngỏ.</p>', 'Full', 1, 'single', 'completed', 13, 2025, 'Vietsub', 'FHD', 'Nam Phi', 0, '[{"name":"Londeka Sishi","avatar":""},{"name":"Busisiwe Mtshali","avatar":""},{"name":"Tina Redman","avatar":""},{"name":"Nombulelo Mhlongo","avatar":""},{"name":"Yonda Thomas","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Umjolo: There Is No Cure"]', 1784690324160);
