INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-xa-duyen-khoi', 'Thanh Xà: Duyên Khởi', 'Green Snake: The Origin', 'https://phimimg.com/upload/vod/20250215-1/aad1ff5701db08ba2289424fcf4e45bc.jpg', 'https://phimimg.com/upload/vod/20250215-1/fbf72a90c0cd16f7f961013c68ff90d7.jpg', '<p>Thanh Xà không ăn thịt người, chỉ ăn yêu quái, nhưng lại bị dân chúng ở thành Hàng Châu hiểu lầm. Nàng bị truy đuổi và tấn công, buộc phải trốn chạy trong tình trạng bị thương. Trên đường, Thanh Xà gặp Tiểu Quỷ, hai người kết bạn và đồng hành cùng nhau. Thanh Xà tiến vào yêu vực, cố gắng cứu những yêu tộc bị bắt, nhưng lại bị nghi ngờ và xa lánh. Yêu Vương nhận ra năng lực của Thanh Xà và để nàng tiếp tục nhiệm vụ. Trong quá trình đồng hành cùng Tiểu Quỷ, Thanh Xà dần cảm nhận được những cảm xúc của con người, và giữa hai người nảy sinh một tình bạn sâu sắc.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ke Ying","avatar":""},{"name":"Shang Na","avatar":""},{"name":"Zhang Yaqi","avatar":""},{"name":"Ashin Shu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Qing She Yuan Qi","Green Snake The Origin","青蛇缘起"]', 1784690324160);
