INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nuoc-hoa-kich-duc', 'Nước Hoa Kích Dục', 'Halimuyak', 'https://phimimg.com/upload/vod/20250215-1/e95f3f06a285cee4fa04f1dfce780862.jpg', 'https://phimimg.com/upload/vod/20250215-1/da43dbcfef1d68ccc0b46f855a09bf86.jpg', '<p>Mikee cuối cùng cũng tìm thấy tình yêu sau nhiều năm đau khổ, dưới hình dáng của Divine, một nghệ nhân nước hoa tuyệt đẹp. Nhưng khi một hương thơm ám ảnh từ quá khứ của Divine gắn liền với chương đau đớn nhất trong cuộc đời Mikee, liệu tình yêu có thể tồn tại khi sự thật đe dọa phá hủy tất cả?</p>', 'Full', 1, 'single', 'completed', 14, 2025, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Christy Imperial","avatar":""},{"name":"Skye Gonzaga","avatar":""},{"name":"Chester Grecia","avatar":""},{"name":"Carlo Lacana","avatar":""},{"name":"Gaye Piccio","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Halimuyak"]', 1784690324160);
