INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('co-gai-dep-nhat-tren-doi', 'Cô Gái Đẹp Nhất Trên Đời', 'The Most Beautiful Girl In The World', 'cô gái đẹp nhất trên đời the most beautiful girl in the world reza rahadian sheila dara kevin julio indra birowo jihane almira bucek depp ira wibowo frederika cull dea panendra agastya kandou ferry salim patricia gouw shakeel fauzi aisy dewi ratna ningsih jafari omid riyanti roy raider wenas dewi so wanita tercantik di dunia la chica más hermosa del mundo najljepša djevojka na svijetu a legszebb lány a világon najpiękniejsza dziewczyna na świecie a garota mais linda do mundo cea mai frumoasă fată din lume cô gái đẹp nhất trên đời dünyanın en güzel kızı 世界で一番美しい人 세상에서 가장 아름다운 여자 la chica más hermosa del mundo the most beautiful girl in the world a garota mais linda do mundo 全世界最美的女孩 das schönste mädchen der welt самая красивая девушка в мире', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-ay-khong-de-thuong', 'Cô Ấy Không Dễ Thương', 'She May Not Be Cute', 'https://phimimg.com/upload/vod/20250213-1/91f4b1923c38664c140f1a61f1975e8e.jpg', 'https://phimimg.com/upload/vod/20250213-1/a4e053d80eac6fe0331fbf0840e72da3.jpg', '<p>Biên tập viên tạp chí thời trang đầy tham vọng Xia Anran hợp tác với đầu bếp tráng miệng bí ẩn Lin Hao để tạo ra một chuyên mục mới. Khi sự hợp tác của họ sâu sắc hơn, những căng thẳng lãng mạn và sự cạnh tranh nghề nghiệp thử thách mối quan hệ của họ. Cùng nhau, họ vượt qua những thử thách của tình yêu và tham vọng trong một thế giới đầy cạnh tranh và những sự thật ẩn giấu.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Christine Zheng","avatar":""},{"name":"Deng Zeming","avatar":""},{"name":"Huang Tingting","avatar":""},{"name":"Qin Fen","avatar":""},{"name":"Su Danping","avatar":""},{"name":"Ceng Yitong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["不可爱的TA","不可爱的她"]', 1784690324160);
