INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-thu-ky-hoan-hao', 'Chàng Thư Ký Hoàn Hảo', 'Love Scout', 'https://phimimg.com/upload/vod/20250104-1/72cb9d786d4ea3e32c8e50fbb04d70e6.jpg', 'https://phimimg.com/upload/vod/20250104-1/91b8ac55448776769f5643951d89dba6.jpg', '<p>Chàng Thư Ký Hoàn Hảo - Love Scout xoay quanh mối tình bí mật chốn văn phòng giữa nam thư ký và nữ giám đốc. Sau khi bị vu khống và bị công ty cũ sa thải, ông bố đơn thân Yoo Eun Ho đến công ty mới và làm việc dưới trướng nữ giám đốc Kang Ji Yoon. Eun Ho là một người hiền lành, dịu dàng, biết quan tâm đến người khác; còn Ji Yoon thì lại mạnh mẽ, hoàn hảo trong công việc nhưng lại vụng về trong tình yêu. Với thế giới quan trái ngược, tình cảm của họ sẽ nảy nở và phát triển như thế nào?</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Han Ji-min","avatar":""},{"name":"Lee Jun-hyuk","avatar":""},{"name":"Kim Do-hoon","avatar":""},{"name":"Kim Yoon-hye","avatar":""},{"name":"Park Bo-kyung","avatar":""},{"name":"Gi So-you","avatar":""},{"name":"Lee Sang-hee","avatar":""},{"name":"Heo Dong-won","avatar":""},{"name":"Yoon Ga-i","avatar":""},{"name":"Seo Hye-won","avatar":""},{"name":"Ko Gun-han","avatar":""},{"name":"Lee Jae-woo","avatar":""},{"name":"Song Ji-in","avatar":""},{"name":"Yun Yoo-sun","avatar":""},{"name":"Cho Seung-yeon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Скаут любви","Между приветствиями","나의 완벽한 비서"]', 1784690324160);
