INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vong-tran-nguyet', 'Vong Trần Nguyệt', 'Heal the Moon', 'https://phimimg.com/upload/vod/20250211-1/953d709aca7ce1024b1788159f7d252e.jpg', 'https://phimimg.com/upload/vod/20250211-1/b988c84c8032e667879d9530cef1bd8b.jpg', '<p>&quot;Sau khi bị chồng là Chu Tịnh Viêm và Vu Lưu Ly mưu hại dẫn đến cái chết, Thẩm Gia Nguyệt tái sinh và quyết định trả thù gia tộc Vu, thay đổi số phận. Thẩm Gia Nguyệt phát hiện ra gia tộc Vu ham muốn bí bảo của gia tộc Chu và đã giết hại toàn bộ gia đình Chu Tịnh Viêm. Kẻ thù của kẻ thù chính là bạn, Thẩm Gia Nguyệt quyết định gạt bỏ mối thù cũ và liên thủ với Chu Tịnh Viêm. Sau một thời gian, Chu Tịnh Viêm cuối cùng cũng đồng ý liên minh với Thẩm Gia Nguyệt. Bất đắc dĩ, hai chiếc kiệu hoa được rước vào phủ của Chu Tịnh Viêm, nhưng Vu Lưu Ly không dễ đối phó, vừa có mưu kế lại vừa lôi kéo được chị gái mới vào Đông Cung, đồng thời còn quen biết lâu năm với thị vệ Sơ Nhất. Quan trọng hơn, Vu Lưu Ly thật sự đã yêu Chu Tịnh Viêm! Vì vậy, dù thế nào cũng phải trừ khử Thẩm Gia Nguyệt, không ngờ rằng tất cả những điều này đều là kế hoạch tỉ mỉ của Chu Tịnh Viêm...</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chen Fangtong","avatar":""},{"name":"Chen Minghao","avatar":""},{"name":"Yuan Yuhan","avatar":""},{"name":"Li Muyu","avatar":""},{"name":"Li Yi","avatar":""},{"name":"Shao Jie","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Fan Hua Mi Meng","繁花迷梦","Blossom Reverie","忘尘月"]', 1784690324160);
