INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-gian-lap-bang', 'Vô Gian Lạp Băng', 'Unrelenting Drug Interdiction', 'https://phimimg.com/upload/vod/20250214-1/5d9442bd09907ae5763bf5a9c9d6d36f.jpg', 'https://phimimg.com/upload/vod/20250214-1/62e778845613a896ad4fad298bbdf6ea.jpg', '<p>Trình Ảnh của đội đặc nhiệm nữ đã dùng khổ nhục kế để phá án và tiêu diệt trùm ma túy xảo quyệt Nguyên Lân. Trong một cuộc thi đấu tại sở cảnh sát, cô cố ý làm bạn thân là Trần Trung Di bị trọng thương, sau khi bị phía cảnh sát sa thải, Trình Ảnh trà trộn vào tổ chức của bọn buôn ma túy để làm nội gián. Tuy nhiên, sự xảo quyệt của Nguyên Lân vượt xa những gì cô có thể tưởng tượng. Cuối cùng, để hoàn thành nhiệm vụ, Trình Ảnh chỉ đành mạo hiểm, dùng cái chết để truyền thông tin tình báo ra ngoài, cuối cùng giúp cảnh sát triệt phá toàn bộ đường dây ma túy.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chen Liwei","avatar":""},{"name":"Li Qia","avatar":""},{"name":"Zhang Yuhan","avatar":""},{"name":"刘羽霄","avatar":""},{"name":"刘依洋","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["无间猎冰"]', 1784690324160);
