INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-giao-dich-phan-2', 'Cuộc Giao Dịch (Phần 2)', 'The Exchange (Season 2)', 'https://phimimg.com/upload/vod/20250213-1/e4ce01731f9996a03ccc6b390b6d7bee.jpg', 'https://phimimg.com/upload/vod/20250213-1/228d84f7a398c0dd8c52b8d72de92b86.jpg', '<p>Hai phụ nữ bắt đầu tiên phong trong thị trường chứng khoán khốc liệt của Kuwait những năm 1980 rồi xóa bỏ định kiến giới đầy sai lầm của thị trường này. Phim dựa trên sự kiện thật.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Kuwait', 0, '[{"name":"Mona Hussein","avatar":""},{"name":"Rayan Dashti","avatar":""},{"name":"Mohammed Al-Mansour","avatar":""},{"name":"Jassim Al-Nabhan","avatar":""},{"name":"Hussain Al-Mahdi","avatar":""},{"name":"Faisal Al-Amiri","avatar":""},{"name":"Mariam Al-Saleh","avatar":""},{"name":"Asmahan Tawfiq","avatar":""},{"name":"Abdullah Bahman","avatar":""},{"name":"Huda Al-Khateeb","avatar":""},{"name":"Hasan Ibrahim","avatar":""},{"name":"Moustafa Ashkanani","avatar":""},{"name":"محمد الكاظمي","avatar":""},{"name":"عباس الخليفي","avatar":""},{"name":"سعود بوشهري","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["الصفقة"]', 1784690324173);
