INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuoc-giao-dich-phan-2', 'Cuộc Giao Dịch (Phần 2)', 'The Exchange (Season 2)', 'cuộc giao dịch (phần 2) the exchange (season 2) mona hussein rayan dashti mohammed al-mansour jassim al-nabhan hussain al-mahdi faisal al-amiri mariam al-saleh asmahan tawfiq abdullah bahman huda al-khateeb hasan ibrahim moustafa ashkanani محمد الكاظمي عباس الخليفي سعود بوشهري الصفقة', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-ba-lao-lang-phan-2', 'Bộ Ba Lão Làng (Phần 2)', 'Three Old Boys (Season 2)', 'https://phimimg.com/upload/vod/20250126-1/685d9a9c34c80444863cb36bf692c8e8.jpg', 'https://phimimg.com/upload/vod/20250126-1/9d6c8c0d8811ef5fe5341f9fc48559fc.jpg', '<p>Ba cảnh sát kỳ cựu của Cục Công an thành phố, gồm có Truyền Thiết Quân, Từ Quốc Trụ và Phan Giang Hải, trong quá trình điều tra phá án một vụ lừa đảo đa cấp, đã phát hiện ra nghi phạm chính có liên quan đến một vụ án mạng từ hai mươi năm trước. Để có thể điều tra triệt để vụ án, ba cảnh sát kỳ cựu đã thành lập Phòng ba mũi nhọn với sự hỗ trợ của Cục trưởng Quách. Phòng ba mũi nhọn đã hỗ trợ các đơn vị cảnh sát phá được nhiều vụ án lớn và nghiêm trọng, và trong quá trình điều tra, họ đã phát hiện ra tất cả những điều này đều có liên quan đến một băng nhóm tội phạm có tên là “Hội Thanh Sơn”. Ba mũi nhọn đã dũng cảm đối mặt với khó khăn, sử dụng những phương pháp cũ để chống lại những âm mưu mới, bảo vệ an toàn tính mạng và tài sản của nhân dân.</p>', 'Hoàn Tất (34/34)', 34, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chen Jianbin","avatar":""},{"name":"Dong Yong","avatar":""},{"name":"Hao Ping","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["三叉戟2","三叉戟","Trident"]', 1784690324173);
