INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuong-hau-wongyeong', 'Vương Hậu Wongyeong', 'The Queen Who Crowns', 'https://phimimg.com/upload/vod/20250107-1/6dec036997a9f9cc5de595d74e26f65c.jpg', 'https://phimimg.com/upload/vod/20250107-1/db9c649ee542b9121965e16d235efd3e.jpg', '<p>Bộ phim khắc họa cuộc đời đầy nhiệt huyết của Vương hậu Wongyeong, người luôn ấp ủ mơ ước xây dựng một nền thái bình thịnh trị ở những năm đầu của triều đại Joseon. Bà đã hỗ trợ chồng mình Lee Bang Won lên ngôi vua và cùng ông cai trị đất nước.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Cha Joo-young","avatar":""},{"name":"Lee Hyun-wook","avatar":""},{"name":"Lee Sung-min","avatar":""},{"name":"Lee E-dam","avatar":""},{"name":"Lee Xia","avatar":""},{"name":"Choi Deok-moon","avatar":""},{"name":"So Hee-jung","avatar":""},{"name":"Jeong Eui-soon","avatar":""},{"name":"Kim Jung","avatar":""},{"name":"Hwang Young-hee","avatar":""},{"name":"Kim Woo-Dam","avatar":""},{"name":"Park Ji-il","avatar":""},{"name":"Song Jae-ryong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["원경"]', 1784690324173);
