INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diem-da-hoa-vang', 'Điểm Đá Hóa Vàng', 'The Gold Behind The Stone', 'https://phimimg.com/upload/vod/20250124-1/1e6c10513075e11c320502f5082f107d.jpg', 'https://phimimg.com/upload/vod/20250124-1/08267998221b600fe76f6d8b4867b5fa.jpg', '<p>Chàng trai Ngụy Kiến Hảo, người sở hữu Tay Phật Ngọc - khả năng thẩm định đá đặc biệt, sau khi trở lại Trùng Giang đã bị cuốn vào cuộc tranh đấu giữa hai gia tộc Đường và Cố, thậm chí còn thường xuyên bị các cao thủ thách thức. Không đành lòng nhìn phố ngọc thạch bị hủy hoại, Ngụy Kiến Hảo nhờ vào khả năng siêu phàm, đứng ra xoay sở, từ chỉ muốn thoát thân đến hết mình bảo vệ, dốc sức đấu tranh cho chính nghĩa giữa muôn trùng âm mưu.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lu Yunfeng","avatar":""},{"name":"Liu Ruiqiao","avatar":""},{"name":"Zhao Qiyue","avatar":""},{"name":"Zhang Xinyue","avatar":""},{"name":"Liu Xiyuan","avatar":""},{"name":"Wu Luohan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["金生雨你","Dian Shi Cheng Jin","点石成金"]', 1784690324173);
