INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dieu-hau-gay-canh-song-sot-sau-tran-chien', 'Diều Hâu Gãy Cánh: Sống Sót Sau Trận Chiến', 'Surviving Black Hawk Down', 'https://phimimg.com/upload/vod/20250210-1/49922ffe78034a975020f3cec487cb58.jpg', 'https://phimimg.com/upload/vod/20250210-1/c68fdfa8f0e111db7342111c33d5b208.jpg', '<p>Binh sĩ Mỹ và các chiến binh Somalia nhớ lại trận Mogadishu năm 1993 và vụ bắn hạ ba chiếc trực thăng Black Hawk nổi tiếng một cách vô cùng chi tiết.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["黑鹰坠落：死里逃生","Surviving Black Hawk Down – Die Schlacht von Mogadischu","The Battle of Mogadishu","Surviving Black Hawk Down"]', 1784690324173);
