INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-sinh-thanh-quy-toc-toi-su-dung-ky-nang-giam-dinh-de-tien-than-trong-the-gioi-phan-2', 'Chuyển Sinh Thành Quý Tộc, Tôi Sử Dụng Kỹ Năng Giám Định Để Tiến Thân Trong Thế Giới (Phần 2)', 'As A Reincarnated Aristocrat, I''ll Use My Appraisal Skill To Rise In The World (Season 2)', 'https://phimimg.com/upload/vod/20250210-1/3895fd16794d278ae1c173ac6bb53d77.jpg', 'https://phimimg.com/upload/vod/20250210-1/f4ffc5d397d64aafa21222a3d212a2b5.jpg', '<p>Series phim kể về cuộc sống sau khi tái sinh từ một người làm công ăn lương bình thường thành Ars Louvent, &quot;con trai của một quý tộc&quot;. Mặc dù không có tài về phép thuật hay kiếm thuật nhưng anh ấy có một kỹ năng mà không ai có: Thẩm định. Sử dụng khả năng này, Ars có thể xác định sức mạnh hiện tại của một người, tiềm năng của họ và tài năng của họ nằm ở đâu.

Với mong muốn xây dựng một lãnh thổ hưng thịnh, Ars bắt đầu tìm kiếm những cộng sự tài năng. Một người nước ngoài bị đàn áp với thanh kiếm vô song, một nô lệ với tài năng ma thuật vô danh và một cậu bé nhút nhát với niềm khao khát kiến thức không thể nguôi - những tài năng này hỗ trợ Ars rất nhiều trong công cuộc tạo ra lãnh thổ hùng mạnh nhất.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Natsumi Fujiwara","avatar":""},{"name":"Taito Ban","avatar":""},{"name":"Narumi Kaho","avatar":""},{"name":"Miho Okasaki","avatar":""},{"name":"Kana Hanazawa","avatar":""},{"name":"Hiroki Touchi","avatar":""},{"name":"Hitomi Nabatame","avatar":""},{"name":"Haruka Tomatsu","avatar":""},{"name":"Yuki Tanaka","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["轉生貴族憑鑑定技能扭轉人生 ～繼承弱小領土後，招募優秀人才打造最強領土～","轉生貴族憑鑑定技能扭轉人生","转生贵族凭鉴定技能扭转人生","Tensei Kizoku, Kantei Skill de Nariagaru","Tensei Kizoku","เกิดใหม่เป็นขุนนาง ขึ้นเป็นใหญ่ด้วยสกิลประเมิน -พอบุคคลชั้นยอดเข้ามา แคว้นแสนงอกง่อยที่รับสืบทอดก็กลายเป็นแคว้นสุดแกร่ง","เกิดใหม่เป็นขุนนาง ขึ้นเป็นใหญ่ด้วยสกิลประเมิน","轉生貴族憑鑑定技能扭轉人生～繼承弱小領土後，招募優秀人才打造最強領土～","Перероджений в аристократа, я використовуватиму свої навички оцінювання, щоб піднятися у світі","As A Reincarnated Aristocrat, I''ll Use My Appraisal Skill To Rise In The World","Chuyển Sinh Thành Quý Tộc, Tôi Sử Dụng Kỹ Năng Giám Định Để Tiến Thân Trong Thế Giới","Chuyển Sinh Thành Quý Tộc Với Kĩ Năng Thẩm Định","Tái Sinh Thành Quý Tộc, Tôi Có Kỹ Năng Thẩm Định Bá Đạo","転生貴族、鑑定スキルで成り上がる"]', 1784690324173);
