INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-sinh-thanh-quy-toc-toi-su-dung-ky-nang-giam-dinh-de-tien-than-trong-the-gioi-phan-2', 'Chuyển Sinh Thành Quý Tộc, Tôi Sử Dụng Kỹ Năng Giám Định Để Tiến Thân Trong Thế Giới (Phần 2)', 'As A Reincarnated Aristocrat, I''ll Use My Appraisal Skill To Rise In The World (Season 2)', 'chuyển sinh thành quý tộc, tôi sử dụng kỹ năng giám định để tiến thân trong thế giới (phần 2) as a reincarnated aristocrat, i''ll use my appraisal skill to rise in the world (season 2) natsumi fujiwara taito ban narumi kaho miho okasaki kana hanazawa hiroki touchi hitomi nabatame haruka tomatsu yuki tanaka 轉生貴族憑鑑定技能扭轉人生 ～繼承弱小領土後，招募優秀人才打造最強領土～ 轉生貴族憑鑑定技能扭轉人生 转生贵族凭鉴定技能扭转人生 tensei kizoku, kantei skill de nariagaru tensei kizoku เกิดใหม่เป็นขุนนาง ขึ้นเป็นใหญ่ด้วยสกิลประเมิน -พอบุคคลชั้นยอดเข้ามา แคว้นแสนงอกง่อยที่รับสืบทอดก็กลายเป็นแคว้นสุดแกร่ง เกิดใหม่เป็นขุนนาง ขึ้นเป็นใหญ่ด้วยสกิลประเมิน 轉生貴族憑鑑定技能扭轉人生～繼承弱小領土後，招募優秀人才打造最強領土～ перероджений в аристократа, я використовуватиму свої навички оцінювання, щоб піднятися у світі as a reincarnated aristocrat, i''ll use my appraisal skill to rise in the world chuyển sinh thành quý tộc, tôi sử dụng kỹ năng giám định để tiến thân trong thế giới chuyển sinh thành quý tộc với kĩ năng thẩm định tái sinh thành quý tộc, tôi có kỹ năng thẩm định bá đạo 転生貴族、鑑定スキルで成り上がる', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tia-nang-nguoi-linh-guc-nga', 'Tia Nắng: Người Lính Gục Ngã', 'Sunray: Fallen Soldier', 'https://phimimg.com/upload/vod/20250209-1/6f278d58012034d506ce30d3699aa038.jpg', 'https://phimimg.com/upload/vod/20250209-1/6b312504b69a431b2ebe76becb732501.jpg', '<p>Một cựu chiến binh kêu gọi những người bạn từ quá khứ của mình truy tìm những kẻ chịu trách nhiệm cho cái chết của con gái mình. Trên đường đi, anh ta biết được nhiều điều về bản thân mình hơn anh ta mong đợi khi một tổ chức tội phạm bạo lực bị lật tẩy sau lưng anh ta.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Tip Cullen","avatar":""},{"name":"Tom Leigh","avatar":""},{"name":"Luke Solomon","avatar":""},{"name":"Steven Blades","avatar":""},{"name":"Andy Gatenby","avatar":""},{"name":"Kevin Golding","avatar":""},{"name":"Franky Lankester","avatar":""},{"name":"Alex Montagnani","avatar":""},{"name":"Will Bowden","avatar":""},{"name":"Denver White","avatar":""},{"name":"Doireann May White","avatar":""},{"name":"Daniel Davids","avatar":""},{"name":"Nicholas Clarke","avatar":""},{"name":"Karlina Grace-Paseda","avatar":""},{"name":"Gemma Knight Jones","avatar":""},{"name":"Saskia Rose","avatar":""},{"name":"Lewis","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["پرتو خورشید: سرباز افتاده","战魂终回","残阳猎杀","Sunray: Fallen Soldier"]', 1784690324173);
