INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-nay-chang-thay-trang-xua', 'Người Nay Chẳng Thấy Trăng Xưa', 'The Relic Keeper', 'https://phimimg.com/upload/vod/20250201-1/79f7b23a59caa0facc3e0f6b777709b2.jpg', 'https://phimimg.com/upload/vod/20250201-1/960bcad29b65b57db4a6bc20a9253f40.jpg', '<p>Hiểu Nguyệt, nhân viên quản lý hiện vật tại viện bảo tàng đã gặp gỡ nha hoàn Yêu Yêu và bổ khoái Lão Tần thời Tây Hán do một sự cố bất ngờ. Yêu Yêu và Vương Tiêu, mẹ của Hiểu Nguyệt bị hoán đổi thân phận bởi một sức mạnh bí ẩn. Vương Tiêu bị đưa về thời Tây Hán, còn Yêu Yêu thì ở lại thời hiện đại. Hiểu Nguyệt và Yêu Yêu cùng nhau cố gắng tìm cách xuyên không, cuối cùng phát hiện bí mật của phu nhân Tân Truy và Lợi Hi.</p>', 'Hoàn Tất (15/15)', 15, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wang Bingbing","avatar":""},{"name":"Lu Zhaohua","avatar":""},{"name":"Zhang Youwei","avatar":""},{"name":"Han Zhang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Jin Ren Bu Jian Gu Shi Yue","今人不见古时玥"]', 1784690324173);
