INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kinh-dich-lon-nhat-an-do-va-pakistan', 'Kình Địch Lớn Nhất: Ấn Độ Và Pakistan', 'The Greatest Rivalry: India Vs Pakistan', 'https://phimimg.com/upload/vod/20250209-1/9cf19b1a8a20c34d29dc62821997dc8a.jpg', 'https://phimimg.com/upload/vod/20250209-1/e3b80f9e0a06a21935a5d9e0a66e0743.jpg', '<p>Theo dấu mối kỳ phùng địch thủ giữa Ấn Độ và Pakistan trong bộ môn cricket, loạt phim tài liệu này khám phá quá khứ đầy phức tạp và hiện tại nhiều bất định của họ trên sân cỏ.</p>', 'Hoàn Tất (3/3)', 3, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Virender Sehwag","avatar":""},{"name":"Shoaib Akhtar","avatar":""},{"name":"Sourav Ganguly","avatar":""},{"name":"Ramiz Raja","avatar":""},{"name":"Sharda Ugra","avatar":""},{"name":"Ayaz Memon","avatar":""},{"name":"Ravichandran Ashwin","avatar":""},{"name":"Osman Samiuddin","avatar":""},{"name":"Javed Miandad","avatar":""},{"name":"Sunil Gavaskar","avatar":""},{"name":"John Wright","avatar":""},{"name":"Kris Srikkanth","avatar":""},{"name":"Waqar Younis","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["India vs Pakistan","The Greatest Rivalry: India vs Pakistan"]', 1784690324173);
