INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('man-anh-tam-tung', 'Mạn Ảnh Tầm Tung', 'Back For You', 'https://phimimg.com/upload/vod/20250205-1/8aa4564ac1776a4b6f5e9124e52abaf0.jpg', 'https://phimimg.com/upload/vod/20250205-1/157ed68ac8facddc5a55d1bea943e7dc.jpg', '<p>Trong thời kỳ đầu của Trung Hoa Dân Quốc, cảnh sát viên A Lai được một người phụ nữ bí ẩn tên Lu Na cứu sống, nhưng cô ấy rơi vào trạng thái hôn mê. Sử dụng những cuốn truyện tranh của cô ấy, anh ta giải quyết các vụ án và khám phá manh mối về quá khứ của cô, đồng thời đối mặt với những nguy hiểm ngày càng gia tăng liên quan đến thành công mới đạt được của mình.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"AngelaBaby","avatar":""},{"name":"Wang Anyu","avatar":""},{"name":"Muye Kuang","avatar":""},{"name":"Zhang Yujian","avatar":""},{"name":"Jim Yu","avatar":""},{"name":"Cheng Xiao","avatar":""},{"name":"Sheng Yinghao","avatar":""},{"name":"Zhang Haiyu","avatar":""},{"name":"Chen Bohao","avatar":""},{"name":"Wang Zixuan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["漫影尋蹤","漫影寻踪"]', 1784690324173);
