INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gieo-gi-gat-nay-ngoai-truyen', 'Gieo Gì Gặt Nấy: Ngoại Truyện', 'GBRB Spin Off: Cafeteria Operation', 'https://phimimg.com/upload/vod/20250119-1/eeb859e44e2a5dbf8f8943cc4dac3163.jpg', 'https://phimimg.com/upload/vod/20250119-1/c5a1f8cc386cf2298949d84a9ad0c7ce.jpg', '<p>Điều gì xảy ra khi Lee Kwang Soo cùng trợ thủ đắc lực Doh Kyung Soo thầu căn tin công ty của PD Na trong 3 ngày? Dù đôi khi bất đồng quan điểm, cả hai vẫn đồng lòng xắn tay vào bếp để phục vụ những bữa cơm ngon lành cho các nhân viên và chào đón những vị khách đặc biệt xuất hiện bất ngờ.</p>', 'Hoàn Tất (10/10)', 10, 'tvshows', 'completed', 16, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Kwang Soo","avatar":""},{"name":"Doh Kyung Soo","avatar":""},{"name":"Kim Woo Bin","avatar":""},{"name":"Lee Young Ji","avatar":""},{"name":"SEVENTEEN","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Agter Elke Man"]', 1784690324173);
