INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-soi-2025', 'Người Sói', 'Wolf Man', 'https://phimimg.com/upload/vod/20250208-1/ec184c98ec565e87b90790b6336956b9.jpg', 'https://phimimg.com/upload/vod/20250208-1/1028b056c8cc0b7ca818e873f9829a1f.jpg', '<p>Một gia đình chuyển đến sinh sống tại một ngôi nhà của người cha bị mất tích bí ẩn. Vào đêm trăng tròn, họ bị tấn công bởi một người sói, khiến người chồng bị cào vào tay. Khi cố thủ trong nhà, anh bắt đầu biến đổi thành một sinh vật đáng sợ, đe dọa tính mạng vợ và con gái.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Christopher Abbott","avatar":""},{"name":"Julia Garner","avatar":""},{"name":"Matilda Firth","avatar":""},{"name":"Sam Jaeger","avatar":""},{"name":"Ben Prendergast","avatar":""},{"name":"Benedict Hardie","avatar":""},{"name":"Zac Chandler","avatar":""},{"name":"Milo Cawthorne","avatar":""},{"name":"Leigh Whannell","avatar":""},{"name":"Rob MacBride","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hombre Lobo","The Wolf Man","新狼人","Qurd Adam","狼人","Մարդագայլը","گرگینه","مرد گرگ نما","მაქცია: Wolf Man","Farkasember","Wolf Man"]', 1784690324173);
