INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-dan-ong-khong-co-qua-khu', 'Người Đàn Ông Không Có Quá Khứ', 'Man With No Past', 'người đàn ông không có quá khứ man with no past jon voight adam woodward marton csokas charlotte vega philip winchester charlotte weston jeff alexander nathan cooper tim fellingham anaya yalamov nico seedsman joseph al ahmad 无迹之人 l''amnésique אדם ללא עבר man with no past', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuong-tu-lenh', 'Tương Tư Lệnh', 'Everlasting Longing', 'https://phimimg.com/upload/vod/20250120-1/db0261ac43aeca4a8d40e99e94a06fc2.jpg', 'https://phimimg.com/upload/vod/20250120-1/4aaf0ac62a5396ce48c356e2aeb53f12.jpg', '<p>Câu chuyện kể về Quân Ỷ La - trưởng nữ nhà họ Quân ở thành bang Diễm Nam, trong một chuyến giao thương tình cờ gặp gỡ Huyền Liệt - tộc trưởng bộ tộc Huyền thuộc thành bang Bắc Huyền. Họ cùng vào sinh ra tử, cuối cùng đem lòng yêu nhau. Mặc dù nam nữ chính sống ở hai thành bang Nam - Bắc với nhiều sự khác biệt về văn hóa, nhưng qua thời gian dài tiếp xúc và tìm hiểu, hai người đã xóa bỏ định kiến về nhau, khám phá ra những ưu điểm của đối phương và dần nảy sinh tình cảm. Tuy rằng tình yêu của họ không được người đời ủng hộ, nhưng họ vẫn hết sức trân trọng và bảo vệ mối tình khó có được này. Vượt qua muôn ngàn trắc trở, cuối cùng hai người đã thành đôi, viết nên chuyện tình đẹp đi vào truyền thuyết. Đồng thời, bằng những nỗ lực không ngừng nghỉ, hai người đã phát triển việc buôn bán tơ lụa, từ đó làm giàu cho dân, củng cố sức mạnh của thành bang, hóa thù hận thành tình hữu nghị, duy trì sự thịnh vượng và hòa bình giữa hai miền Nam - Bắc.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Angelababy","avatar":""},{"name":"Tống Uy Long","avatar":""},{"name":"Nhậm Hào","avatar":""},{"name":"Bạch Băng Khả","avatar":""},{"name":"Diêu Trì","avatar":""},{"name":"Vương Dịch Đình","avatar":""},{"name":"Nhậm Trọng","avatar":""},{"name":"Sa Bảo Lượng","avatar":""},{"name":"Điền Lệ","avatar":""},{"name":"Trương Tuấn Ninh","avatar":""},{"name":"Hạ Nam","avatar":""},{"name":"La Gia Lương","avatar":""},{"name":"Trần Đào","avatar":""},{"name":"Trần Thần","avatar":""},{"name":"Tần Hiểu Hiên","avatar":""},{"name":"Lý Thục Đình","avatar":""},{"name":"Long Thủy Đình","avatar":""},{"name":"Ngô Dật Già","avatar":""},{"name":"Nhan An","avatar":""},{"name":"Trần Thiên Ngọ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["抢来的新娘","相思令"]', 1784690324173);
