INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trung-tam-cham-soc-chan-thuong', 'Trung Tâm Chăm Sóc Chấn Thương', 'The Trauma Code: Heroes On Call', 'https://phimimg.com/upload/vod/20250125-1/48e185362ae4624fe58084640140edbd.jpg', 'https://phimimg.com/upload/vod/20250125-1/3fb5a0e76bd15e648673727e110c7fc5.jpg', '<p>Để lập Trung tâm Chăm sóc Chấn thương hàng đầu, một bác sĩ dày dạn chiến trường, cộc cằn nhưng tài ba, dẫn dắt đội ngũ của mình trở thành các chiến binh cứu người dám nghĩ dám làm.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 18, 2025, 'Vietsub + Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ju Ji-hoon","avatar":""},{"name":"Choo Young-woo","avatar":""},{"name":"Ha Young","avatar":""},{"name":"Yoon Kyung-ho","avatar":""},{"name":"Jeong Jae-kwang","avatar":""},{"name":"Kim Eui-sung","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["外伤重症中心","The Trauma Code Heroes on Call","중증외상센터"]', 1784690324173);
