INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-lai-cuoc-doi-2025', 'Làm Lại Cuộc Đời', 'Live Or Love', 'https://phimimg.com/upload/vod/20250119-1/33fcf3f84a90b44871f94988ef8c8eea.jpg', 'https://phimimg.com/upload/vod/20250119-1/07ab7de167b9a0475bc0ab1f952c7430.jpg', '<p>Phương Lê và An Hàng là đối thủ cạnh tranh ngoài đời thực. Một tai nạn bất ngờ đã khiến họ mắc kẹt trong thế giới ảo và trở thành vợ chồng. Nhưng nhiệm vụ hệ thống của hai người lại đối lập, buộc phải đánh bại đối phương mới có thể quay về hiện thực. Do đó hai người liên tục đọ sức, trở thành &quot;Ông bà Smith&quot; trong hệ thống. Trong quá trình thương nhau lắm cắn nhau đau, đôi bên đã rung động và thành công sửa đổi quy tắc của hệ thống.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Diệu","avatar":""},{"name":"Lư Dương Dương","avatar":""},{"name":"Quách Già Nam","avatar":""},{"name":"Lý Áo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Live or Love","再次人生"]', 1784690324173);
