INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phong-giam-211', 'Phòng Giam 211', 'Prison Cell 211', 'https://phimimg.com/upload/vod/20250205-1/09d117ceb9661683452ba44c4ecbf56b.jpg', 'https://phimimg.com/upload/vod/20250205-1/6000247077de3903c45d911e8fd1398a.jpg', '<p>Bị cuốn vào một cuộc bạo loạn trong tù, luật sư nhân quyền nọ giả làm tù nhân để sống sót. Khi anh hòa vào đám đông, hỗn loạn và nỗi mất mát cá nhân phơi bày bóng tối trong anh.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 13, 2025, 'Vietsub', 'FHD', 'Mexico', 0, '[{"name":"Diego Calva","avatar":""},{"name":"Noé Hernández","avatar":""},{"name":"Alejandro Puente","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Celda 211"]', 1784690324173);
