INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phong-giam-211', 'Phòng Giam 211', 'Prison Cell 211', 'phòng giam 211 prison cell 211 diego calva noé hernández alejandro puente celda 211', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-nang-dieu-luc', 'Cẩm Nang Diệu Lục', 'Under The Moonlight', 'https://phimimg.com/upload/vod/20250114-1/5a8af005131fe671f33ffa8f6f4f1924.jpg', 'https://phimimg.com/upload/vod/20250114-1/e658db3ae3f668c686bc919e3efa44a2.jpg', '<p>Cô gái trẻ La Sơ gia cảnh sa sút, bị đày vào tiện tịch. Nhờ sự tâm lý, thấu hiểu lòng người mà cô được đặt biệt danh Túi Gấm. Để thay đổi số phận, cô chủ động xin được giúp đỡ tân huyện lệnh Hàn Mộ Chi phá một vụ án lớn. Từ đó, cô tạm thời ở lại huyện nha, hóa thân thành bổ khoái hỗ trợ điều tra. Trong quá trình này, cô kết giao với chàng công tử trẻ tuổi Tề Mộng Lân, người ấp ủ ước mơ du ngoạn giang hồ. La Sơ rất giỏi phá những vụ án hóc búa ly kỳ. Mười vụ kỳ án lớn chốn dân gian như &quot;Vụ án xác nữ không đầu&quot; thảm khốc rùng rợn, &quot;Vụ án xác chết lõa lồ ở sông Phần&quot; kỳ dị, &quot;Vụ án giết người tại xưởng rượu&quot; âm mưu khôn lường... liên tiếp xảy ra. Mỗi khi thấy những người phụ nữ đáng thương trong vụ án, La Sơ và Tề Mộng Lân đều cố gắng hết sức để đòi lại công lý cho họ. Cùng với việc giải quyết từng vụ án, tình cảm giữa La Sơ và Tề Mộng Lân cũng ngày càng sâu đậm. Mà chẳng hay, một âm mưu lớn hơn đang lặng lẽ đến gần.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hu Bingqing","avatar":""},{"name":"Zhai Zilu","avatar":""},{"name":"He Peng","avatar":""},{"name":"Ding Xiaoying","avatar":""},{"name":"Feng Xiaotong","avatar":""},{"name":"Li Jiaxin","avatar":""},{"name":"Zhai Yujia","avatar":""},{"name":"Sun Yali","avatar":""},{"name":"Liu Changde","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["柳暗花明又一村","风月锦囊","Under.the.Moonlight","锦囊妙录"]', 1784690324173);
