INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ve-si-3-quyet-chien', 'Vệ Sĩ 3: Quyết Chiến', 'Bodyguard 3', 'https://phimimg.com/upload/vod/20250204-1/b59a8a779f2be3cd7d06b7caabf1ff56.jpg', 'https://phimimg.com/upload/vod/20250204-1/ff7bd5e08c0cdcb041fa7405fe302372.jpg', '<p>Bộ phim kể về câu chuyện của Cao Thiên, một vệ sĩ mới vào nghề, trong hành trình giải cứu vị hôn thê bị bắt cóc, anh vô tình bị cuốn vào một nhiệm vụ điều tra ngầm nhằm triệt phá một tổ chức tội phạm. Nhờ sự phối hợp với cảnh sát chìm Chim Ưng, Cao Thiên đã vượt qua muôn vàn nguy hiểm, cửu tử nhất sinh, cuối cùng thành công giải cứu vị hôn thê và đưa tất cả tội phạm ra ánh sáng pháp luật.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 1, '[{"name":"Nie Rongxin","avatar":""},{"name":"Jacky Heung","avatar":""},{"name":"Li Huan","avatar":""},{"name":"Shi Xuanru","avatar":""},{"name":"Jiang Baocheng","avatar":""},{"name":"Han Wenjun","avatar":""},{"name":"Zhaoyan Guozhang","avatar":""},{"name":"Wang Shuangbao","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Bodyguard 3","护卫者III：决战","护卫者 3: 决战"]', 1784690324173);
