INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-xe-tuong-nha-son', 'Thần Xe Tượng Nha Sơn', 'God Of Driving', 'https://phimimg.com/upload/vod/20250204-1/958c5137d8f39d7ea93b6c38c5a72888.jpg', 'https://phimimg.com/upload/vod/20250204-1/073af9f2894b7777b2e0baf0cc2167c1.jpg', '<p>Tay đua chuyên nghiệp Cao Lương rơi vào trầm cảm và chán nản sau khi bị đội đua sa thải. Trong một lần trở về quê hương là núi Tượng Nha thăm người thân, anh bất ngờ giành chiến thắng trong cuộc thi tuyển chọn “Thần xe núi Tượng Nha” mới. Nhờ đó, anh được bái sư và học hỏi từ cựu “Thần xe” Lý Hồng Quang. Mối quan hệ thầy trò giữa họ vừa yêu thương vừa đối đầu, tạo nên nhiều tình huống dở khóc dở cười. Cuối cùng, họ đã cùng nhau giành chiến thắng trong cuộc đua mang ý nghĩa quan trọng đối với sự phát triển nông thôn, đồng thời đạt được sự trưởng thành và khám phá bản thân.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 1, '[{"name":"Liu Xiaoguang","avatar":""},{"name":"Shi Yuanting","avatar":""},{"name":"Cui Zhenzhen","avatar":""},{"name":"Zhang Xiaoying","avatar":""},{"name":"Liu Yajin","avatar":""},{"name":"Li Tianyu","avatar":""},{"name":"Chen Zhuo","avatar":""},{"name":"Johnson Wang","avatar":""},{"name":"张钿悦","avatar":""},{"name":"Cheng Jian","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Xiang Ya Shan Che Shen","象牙山车神"]', 1784690324173);
