INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-ac-tan-bao', 'Tội Ác Tàn Bạo', 'Atrocious', 'https://phimimg.com/upload/vod/20250204-1/ad64d7ff1d7a914f2d404d0bce2392a6.jpg', 'https://phimimg.com/upload/vod/20250204-1/85a54773120e6195b7ecc99f32dbf346.jpg', '<p>Vào thời Dân Quốc, mỗi khi sương mù dày đặc phủ kín và âm thanh kỳ bí vang lên, một ngôi mộ thần bí trên ngọn núi sau làng Ba Thục, Tứ Xuyên, sẽ xuất hiện báu vật. Một nhóm lữ khách tụ họp tại làng Ba Thục, nhưng mục đích của họ đều là chiếm đoạt báu vật trong làng. Họ không hề hay biết rằng, từ trong bóng tối, có một thực thể bí ẩn đang dõi theo từng hành động của họ… Khi nhóm người tham lam này cuối cùng đào được báu vật, họ lần lượt chết thảm xung quanh ngôi mộ, không ai thoát khỏi sự trừng phạt…</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 1, '[{"name":"Wang Shuangbao","avatar":""},{"name":"Shi Xuanru","avatar":""},{"name":"An Zehao","avatar":""},{"name":"Yue Dongfeng","avatar":""},{"name":"Yang Hanbin","avatar":""},{"name":"Ge Shuai","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Qiong Xiong Ji E","極悪非道","궁흉극악","穷凶极恶"]', 1784690324173);
