INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-linh-quy-su-nguoi-bao-ve', 'Tần Lĩnh Quỷ Sự: Người Bảo Vệ', 'Guardian Of Graveyard', 'https://phimimg.com/upload/vod/20250204-1/b08bd4fa9bdfeee5bf4bd553e490fb14.jpg', 'https://phimimg.com/upload/vod/20250204-1/7cdcb1e531c5de16e47cbfd95809a929.jpg', '<p>Câu chuyện này kể về hành trình của nhóm săn tìm kho báu gồm Tuần gia, Phượng Dao, Thái Thanh Vân, Vương Áp Tử và những người khác, nhằm cứu trợ dân gặp nạn. Họ tiến vào núi Phượng Hoàng ở Tần Lĩnh để tìm kho báu đã đối mặt với vô vàn nguy hiểm. Nhờ tinh thần đoàn kết, mọi người đã vượt qua hiểm cảnh. Thông qua cuộc đấu tranh với các thế lực như quan chức cũ, hào phú địa phương, và người nước ngoài, họ đã phá tan âm mưu hiểm độc của người nước ngoài muốn chiếm đoạt quốc bảo của Trung Quốc.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 1, '[{"name":"Hàn Đông","avatar":""},{"name":"Phương Nguyên","avatar":""},{"name":"Đỗ Chí Quốc","avatar":""},{"name":"Lưu Bác","avatar":""},{"name":"Tiêu Tùng Nguyên","avatar":""},{"name":"Cao Vũ Thanh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["秦岭诡事之守护者"]', 1784690324173);
