INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pha-cuc', 'Phá Cục', 'Bleed For Justice', 'https://phimimg.com/upload/vod/20250204-1/9e3f011d6cd63df2b5e1e9c42c74cb6e.jpg', 'https://phimimg.com/upload/vod/20250204-1/eab6daa84a5d304098a08fc3fc95f988.jpg', '<p>Sự yên bình của thành phố Đông Hải bị phá vỡ bởi một cuộc thanh toán đẫm máu giữa các băng đảng. Cặp đôi sát thủ Điện Cư và Dương Dương đã càn quét các tiền trang, chiếm đoạt toàn bộ tài sản. Những sát thủ này thực chất là do giám đốc tập đoàn là Triệu Bình An, chỉ thị thực hiện, đây là một vụ cá lớn nuốt cá bé điển hình. Cùng lúc đó, đội đặc cảnh đồng loạt xuất kích, lập nên một mạng lưới vây bắt toàn diện. Sau nhiều lần chặn đứng, họ cuối cùng đã tóm gọn bọn tội phạm, triệt để đập tan âm mưu của tập đoàn quốc tế muốn chuyển dịch tài sản phi pháp.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 1, '[{"name":"Shen Tai","avatar":""},{"name":"He Meixuan","avatar":""},{"name":"Chen Yiming","avatar":""},{"name":"Yuming Du","avatar":""},{"name":"Wang Bo Qing","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Bleed for Justice","Collapse","파국: 정의를 위한 피","破局"]', 1784690324173);
