INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-bac-dai-tien-nhi', 'Đông Bắc Đại Tiên Nhi', 'Fortune Teller', 'https://phimimg.com/upload/vod/20250204-1/10552ca3d1851c572ea7237eaf8cb2a4.jpg', 'https://phimimg.com/upload/vod/20250204-1/4f43a8e4d0a73dfde4c07f84c6b5e1fe.jpg', '<p>Triệu Đại Xuân là một &quot;đại tiên nhân&quot; khá nổi tiếng ở vùng Đông Bắc. Để nâng cao danh tiếng của mình trong nghề xem bói, bên ngoài anh ta tỏ ra chuyên sâu về huyền học, nhưng thực chất lại âm thầm phối hợp với đàn em Bưu Tử để giúp khách hàng giải quyết những vấn đề thực tế, tạo ra không ít tình huống dở khóc dở cười. Sau này, vì lòng tham nhất thời, anh bị cuốn vào một vụ lừa đảo tà thuật phong kiến, nhưng sau khi tỉnh ngộ, anh đã vạch trần âm mưu của những kẻ xấu.</p>', 'Full', 1, 'single', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 1, '[{"name":"Peng Yu Si","avatar":""},{"name":"Du Yiheng","avatar":""},{"name":"Wei Xiaoxuan","avatar":""},{"name":"Shi Yuanting","avatar":""},{"name":"Li Sibo","avatar":""},{"name":"Wu Chunyi","avatar":""},{"name":"Marsel Sharipov","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["东北“大仙儿”"]', 1784690324173);
