INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-la-dan-gian-xich-ma-tien', 'Chuyện Lạ Dân Gian: Xích Mã Tiên', 'Folk tales of Chu Maxian', 'https://phimimg.com/upload/vod/20250204-1/30c6250f47fa33824b86335efa07938c.jpg', 'https://phimimg.com/upload/vod/20250204-1/b202a739946dc8c5e5bbfc0775675edc.jpg', '<p>Trong dân gian Đông Bắc, những loài động vật có linh tính được gọi là tiên gia”. Thời Dân Quốc loạn lạc, các thiếu nữ ở thôn Thanh Liễu liên tục bị Tao tiên bắt đi và chết thảm, dân làng bị quỷ ám vào nửa đêm và bị đoạt mạng. Cả thôn Thanh Liễu chìm trong nỗi kinh hoàng của Tao tiên đoạt mạng. Pháp y Phương Thiên Dực am hiểu thuật trừ tà và phá giải hiện tượng kỳ bí đã dấn thân vào cánh rừng già Đông Bắc để điều tra chân tướng và vén màn vụ án quỷ dị bị chôn vùi trong quá khứ…</p>', 'Full', 1, 'single', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Liu Xinyu","avatar":""},{"name":"Jason Sze","avatar":""},{"name":"Xie Shixin","avatar":""},{"name":"Chen Chuang","avatar":""},{"name":"Cong Sihan","avatar":""},{"name":"Yue Dongfeng","avatar":""},{"name":"Zhao Qiusheng","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Min Su Guai Wen Lu Zhi Chu Ma Xian","民俗怪闻录之出马仙"]', 1784690324173);
