INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cha-gia', 'Cha Giả', 'Fake Dad', 'https://phimimg.com/upload/vod/20250204-1/fbe6518d01b6093ca80836dfe1f6ac78.jpg', 'https://phimimg.com/upload/vod/20250204-1/1783bebec117fb1884340aa173343fca.jpg', '<p>Ngôi sao ca nhạc lừng lẫy một thời Dương Hạo Lương (do Giả Băng thủ vai) tình cờ phát hiện có kẻ mạo danh mình để lừa đảo. Ông lập tức yêu cầu con trai là Dương Thập Nguyệt (do Doãn Chính thủ vai) điều tra sự việc. Tuy nhiên, để có đủ tiền phẫu thuật cho cha, Dương Thập Nguyệt đã bắt tay với “bố giả” Vương Xuân Sinh (cũng do Giả Băng thủ vai), mở ra một hành trình dở khóc dở cười với vô số tình huống hài hước &quot;lừa đảo kiếm tiền&quot; đầy kịch tính. Những sự cố rối ren trong các buổi biểu diễn cuối cùng đã dừng lại trước đêm diễn quan trọng nhất, và họ cũng bất ngờ nhận ra một thứ tình cảm chân thành quý giá – tình người ấm áp nhất.</p>', 'Full', 1, 'single', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 1, '[{"name":"Jia Bing","avatar":""},{"name":"Yin Zheng","avatar":""},{"name":"Ni Hongjie","avatar":""},{"name":"Xu Zheng","avatar":""},{"name":"Ding Jiali","avatar":""},{"name":"Yang Haoyu","avatar":""},{"name":"Pan Binlong","avatar":""},{"name":"Bao Bei Er","avatar":""},{"name":"Yu Yang","avatar":""},{"name":"Liu Hua","avatar":""},{"name":"Shaogang Zhang","avatar":""},{"name":"Zong Juntao","avatar":""},{"name":"Xia Meng","avatar":""},{"name":"Sun Hao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Dad Dad","大歌唱家","Fake Dad","假爸爸"]', 1784690324173);
