INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bogota-thanh-pho-cua-nhung-ke-luu-lac', 'Bogotá: Thành Phố Của Những Kẻ Lưu Lạc', 'Bogotá: City Of The Lost', 'https://phimimg.com/upload/vod/20250204-1/4ac516ad33bcc168edd923335b62b2a1.jpg', 'https://phimimg.com/upload/vod/20250204-1/e4383f4775e051e3d6344dc9c3b8c82b.jpg', '<p>Sau khi chuyển đến Bogotá để tìm cơ hội đổi đời, chàng trai Hàn Quốc nọ từng bước vươn lên ở chợ đen Colombia – liều mình đối mặt với hiểm nguy để nắm lấy cơ hội thành công.</p>', 'Full', 1, 'single', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"Song Joong-ki","avatar":""},{"name":"Lee Hee-jun","avatar":""},{"name":"Kwon Hae-hyo","avatar":""},{"name":"Cho Hyun-chul","avatar":""},{"name":"Park Ji-hwan","avatar":""},{"name":"Kim Jong-soo","avatar":""},{"name":"Juana del Río","avatar":""},{"name":"Im Sung-jae","avatar":""},{"name":"Kim Tae-baek","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Bogota: City of the Lost","愁城波哥大","波哥大","보고타: 마지막 기회의 땅"]', 1784690324173);
