INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-hai-phat-tai', 'Tứ Hải Phát Tài', 'Four Sea Get Rich', 'https://phimimg.com/upload/vod/20250115-1/a71df2f0c8d5429dabb302b887457d70.jpg', 'https://phimimg.com/upload/vod/20250115-1/2c4802995d58b0994e437711abb684f2.jpg', '<p>Tứ Hải Phát Tài kể về những ngày cuối năm của đoàn hát Tứ Hải, từng nức tiếng một vùng. Trước khi bước sang năm mới, cả đoàn chật vật với nỗi lo “cơm áo gạo tiền”, không có show. Khó khăn chồng chất khi trưởng đoàn đột ngột nghỉ hưu, nhường lại vị trí cho con trai Thành An – vốn chưa biết gì về gánh tạp kỹ.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Gin Tuấn Kiệt","avatar":""},{"name":"Võ Cảnh","avatar":""},{"name":"Võ Tấn Phát","avatar":""},{"name":"Lê Tam Triều Dâng","avatar":""},{"name":"Ngân Quỳnh","avatar":""},{"name":"Tiko Tiến Công","avatar":""},{"name":"Tôn Kinh Lâm","avatar":""},{"name":"Jun Vũ","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["אננדה"]', 1784690324173);
