INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-biet-lop-18-2025', 'Tạm Biệt Lớp 18', 'Too Young To Grow Old', 'https://phimimg.com/upload/vod/20250124-1/6500f86b8c9ddf6e6f31bf919a585a48.jpg', 'https://phimimg.com/upload/vod/20250124-1/3fbe0ffcbc20514e1fbdc85bd698d616.jpg', '<p>Cựu phiến quân Song Chen, được người thầy truyền cảm hứng, trở thành một giáo viên tận tâm giúp đỡ học sinh vượt qua khó khăn. Hợp tác với Tan Shutong đầy nghị lực nhưng bất đắc dĩ, anh phải đối mặt với những thách thức trong công việc giảng dạy đồng thời thu hẹp khoảng cách giữa các thế hệ. Cùng với các học sinh và bạn bè đồng trang lứa, họ bắt đầu một hành trình trưởng thành, đặt câu hỏi về ý nghĩa thực sự của việc trở thành người lớn mà họ mong muốn.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yi Daqian","avatar":""},{"name":"Deng Meng","avatar":""},{"name":"Xiong Jingwen","avatar":""},{"name":"Wu Chongxuan","avatar":""},{"name":"Chen Minghao","avatar":""},{"name":"Zhu Ran","avatar":""},{"name":"Bai Yufei","avatar":""},{"name":"Lin Chenhan","avatar":""},{"name":"Lu Zhanxiang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Goodbye Class 18","再见十八班"]', 1784690324173);
