INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rung-dong-ngan-nam', 'Rung Động Ngàn Năm', 'Millennium Heart', 'https://phimimg.com/upload/vod/20250121-1/60bb855a701f6b84a23c280da8593165.jpg', 'https://phimimg.com/upload/vod/20250121-1/00583f813eac4d5707479e7a9e8ba444.jpg', '<p>Khi kho báu thiên thể, Sách Thiên Đường, rơi xuống thế giới phàm trần, hai vị thần tái sinh, Ao Qi và Qian Mo, phải khám phá vận mệnh chung của họ. Tái sinh thành con người, Cheng Qi và A Lin, họ hợp lực để bảo vệ cuốn sách và đối mặt với những thử thách thách thức sức mạnh và cam kết của họ đối với công lý.</p>', 'Tập 30', 34, 'series', 'ongoing', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Aaron Deng","avatar":""},{"name":"Tu Zhiying","avatar":""},{"name":"Wang Jiaxuan","avatar":""},{"name":"Xin Ruiqi","avatar":""},{"name":"Wang Xuan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["心動千年","心动千年"]', 1784690324173);
