INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-te-nguy-hiem', 'Nữ Tế Nguy Hiểm', 'The Resurrection Of Justice', 'https://phimimg.com/upload/vod/20250117-1/d53d7c801b6dfac5c24d39143280507a.jpg', 'https://phimimg.com/upload/vod/20250117-1/f2c20d488f5e40190a3e3e92356b7f34.jpg', '<p>Zhang Xin phát hiện ra vụ sát hại cha mình bởi con trai một tỷ phú và quyết tâm tìm kiếm công lý, nhưng một vụ tai nạn xe hơi đã đưa anh trở về năm 2001 trong cơ thể của một tài xế cho cùng một gia đình. Bất ngờ kết hôn với cô con gái út của gia đình, anh lợi dụng chức vụ mới của mình để vạch trần những sai trái từ bên trong của họ.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Leo Yang","avatar":""},{"name":"Yu Binghui","avatar":""},{"name":"Cao Tiankai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["危险女婿"]', 1784690324173);
