INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-ay-dap-gio-ma-toi', 'Cô Ấy Đạp Gió Mà Tới', 'She Rides The Wind', 'https://phimimg.com/upload/vod/20250114-1/e01d4312a5b025bc68caa0001c9ceed6.jpg', 'https://phimimg.com/upload/vod/20250114-1/51b48315f5676cbdfa5ea6cbd97aa810.jpg', '<p>Tần Nam, nữ tổng giám đốc sắp kế nhiệm tập đoàn Tần Thị bất ngờ phát hiện La Sâm, chồng mình có quan hệ bất chính với Đồng Thiến, thư ký của bố, chính cô cũng rơi vào tình cảnh khó khăn. Sau khi tái sinh, Tần Nam quyết tâm tìm ra sự thật đằng sau sự lung lay của tập đoàn Tần Thị. Cô mời Phó Quân Lam, giám đốc kỹ thuật mô phỏng khoang tàu về để củng cố vị trí của mình trong công ty. Nhờ sự hỗ trợ của Phó Quân Lam, Tần Nam nhiều lần thoát khỏi những âm mưu của Đồng Thiến và La Sâm. Trong lúc đối mặt với nguy cơ, tình cảm nơi công sở giữa hai người lặng lẽ nảy nở. Tần Nam tìm được chứng cứ cho thấy Đồng Thiến đã biển thủ công quỹ nên sa thải cô ta, còn La Sâm, đồng phạm của Đồng Thiến cũng phải rời khỏi cuộc chơi trong nhục nhã. Tuy nhiên đúng lúc này, Tần Nam phát hiện ra mục đích thực sự của Phó Quân Lam khi gia nhập công ty, đó là để điều tra sự thật đằng sau cái chết của em gái anh, Phó Quân Nhã. Sau quá trình điều tra, tội ác của Triệu Tử Thành, một đối tác của tập đoàn Tần Thị dần sáng tỏ, chính anh ta đã xâm hại Phó Quân Nhã khiến cô tự sát. Phó Quân Lam quyết định trả thù nhưng lại rơi vào tình thế nguy hiểm. Tần Nam bất chấp mạng sống để cứu anh và cuối cùng đưa Triệu Tử Thành ra trước công lý. Khi mọi chuyện tưởng chừng kết thúc thì Tần Nam lại bị Tiết Mẫn Mẫn, người bạn thân nhất bắt giam, hóa ra Tiết Mẫn Mẫn cũng là một quân cờ trong âm mưu của Đồng Thiến. Trong khoảnh khắc sinh tử, Phó Quân Lam mạo hiểm để phá vỡ âm mưu của Đồng Thiến và Tiết Mẫn Mẫn, nhưng anh lại biến mất khỏi cuộc đời của Tần Nam. Anh đã đi đâu? Sau nhiều lần tìm kiếm vô vọng, vào một buổi chiều yên bình, anh đột nhiên xuất hiện trước mặt cô...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dai Gaozheng","avatar":""},{"name":"He Hua","avatar":""},{"name":"Luo Yan","avatar":""},{"name":"Xie Zhixun","avatar":""},{"name":"Li Jiabing","avatar":""},{"name":"Liu Wenxue","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["迫降在我心","Forced Landing in My Heart","乘风而上的她"]', 1784690324173);
