INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mang-luoi-alarum', 'Mạng Lưới Alarum', 'Alarum', 'https://phimimg.com/upload/vod/20250124-1/94c50601d62085ee1811f9d3e5e40fbb.jpg', 'https://phimimg.com/upload/vod/20250124-1/ac861a9c212e6c6ac42be0bbd02f4b74.jpg', '<p>Hai điệp viên đào ngũ quyết định rời bỏ cuộc sống cũ, sống ẩn dật và kết hôn tại một căn cabin hẻo lánh. Tuy nhiên, bình yên không kéo dài lâu khi họ trở thành mục tiêu truy lùng của nhiều cơ quan tình báo. Tất cả đều nhắm đến một ổ cứng chứa bí mật bị đánh cắp, thứ có thể thay đổi cục diện quyền lực. Giữa sự truy sát và phản bội, họ phải đấu tranh để sinh tồn và bảo vệ lẫn nhau.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Scott Eastwood","avatar":""},{"name":"Sylvester Stallone","avatar":""},{"name":"Willa Fitzgerald","avatar":""},{"name":"Mike Colter","avatar":""},{"name":"D.W. Moffett","avatar":""},{"name":"Isis Valverde","avatar":""},{"name":"Joel Cohen","avatar":""},{"name":"Mark Polish","avatar":""},{"name":"Anton Narinskiy","avatar":""},{"name":"Patrick Millin","avatar":""},{"name":"La Monde Byrd","avatar":""},{"name":"Beau Bommarito","avatar":""},{"name":"Bret Aaron Knower","avatar":""},{"name":"John E. Brownlee","avatar":""},{"name":"Derek Polen","avatar":""},{"name":"Kevin W. Shiveley","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Аларум","آلارم","Alarum Código Letal","警报战","Codename: Alarum","Mission Alarum","警報戰","Alarum"]', 1784690324173);
