INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-ban-tia-11-chot-chan-cuoi-cung', 'Lính Bắn Tỉa 11: Chốt Chặn Cuối Cùng', 'Sniper: The Last Stand', 'https://phimimg.com/upload/vod/20250124-1/93ac0b479418436def55f05f7f691109.jpg', 'https://phimimg.com/upload/vod/20250124-1/a48fd6acd4e487ed6f0e3978aa4f0da6.jpg', '<p>Xạ thủ Brandon Beckett và đặc vụ Zero được điều đến Costa Verde để dẫn dắt nhóm lính đối đầu với một lực lượng tàn bạo. Họ không chỉ chiến đấu vì tính mạng mà còn để ngăn chặn một thảm họa sắp xảy ra.</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Chad Michael Collins","avatar":""},{"name":"Ryan Robbins","avatar":""},{"name":"Sharon Taylor","avatar":""},{"name":"Manuel Rodriguez-Saenz","avatar":""},{"name":"Scott George","avatar":""},{"name":"Vusi Kunene","avatar":""},{"name":"Sizo Mahlangu","avatar":""},{"name":"Noxolo Dlamini","avatar":""},{"name":"Arnold Vosloo","avatar":""},{"name":"Rob van Vuuren","avatar":""},{"name":"Hope Thangata","avatar":""},{"name":"Kathleen Stephens","avatar":""},{"name":"Kiroshan Naidoo","avatar":""},{"name":"Duane Behrens","avatar":""},{"name":"Clayton Evertson","avatar":""},{"name":"Stavros","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sniper - The Last Stand","狙击精英：背水一战","تک تیرانداز: آخرین ایستادگی","צלף: הקרב האחרון","Lunetistul: Ultima redută","Sniper: The Last Stand"]', 1784690324173);
