INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('linh-ban-tia-11-chot-chan-cuoi-cung', 'Lính Bắn Tỉa 11: Chốt Chặn Cuối Cùng', 'Sniper: The Last Stand', 'lính bắn tỉa 11: chốt chặn cuối cùng sniper: the last stand chad michael collins ryan robbins sharon taylor manuel rodriguez-saenz scott george vusi kunene sizo mahlangu noxolo dlamini arnold vosloo rob van vuuren hope thangata kathleen stephens kiroshan naidoo duane behrens clayton evertson stavros sniper - the last stand 狙击精英：背水一战 تک تیرانداز: آخرین ایستادگی צלף: הקרב האחרון lunetistul: ultima redută sniper: the last stand', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-trang', 'Tẩy Trắng', 'Drifting Away', 'https://phimimg.com/upload/vod/20250119-1/2d323dd60e085547ee4faf281fef7305.jpg', 'https://phimimg.com/upload/vod/20250119-1/c880147467377ba1b7a246d1406c1857.jpg', '<p>Tẩy Trắng kết hợp nhiều yếu tố như tội phạm, điều tra hình sự, tâm lý học để xây dựng cốt truyện, kể về câu chuyện của đội trưởng đội cảnh sát hình sự Bành Triệu Lâm, người luôn kiên định giữ vững lý tưởng về công lý. Trong cuộc đấu tranh giữa ánh sáng và bóng tối, anh không ngừng truy đuổi tội phạm, trải qua mười năm và vượt qua ngàn dặm, cuối cùng đưa những kẻ tội phạm cực đoan, cố chấp và độc ác ra trước pháp luật. Bộ phim có sự tham gia của các diễn viên thực lực như Quách Kinh Phi, Vương Thiên Nguyên, Triệu Kim Mạch, do đạo diễn Tào Khải chỉ đạo, biên kịch Trần Bình chắp bút, thể hiện niềm tin và sự kiên trì chảy trong huyết quản của lực lượng cảnh sát nhân dân, chính nghĩa luôn chiến thắng tà ác.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 12, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Guo Jingfei","avatar":""},{"name":"Wang Qian-yuan","avatar":""},{"name":"Zhao Jinmai","avatar":""},{"name":"Ren Zhong","avatar":""},{"name":"Wang Jiajia","avatar":""},{"name":"Zong Juntao","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["漂白","A la Deriva","표백","À Deriva","หนี ตาย","Drifting Away","Tẩy Trắng"]', 1784690324173);
