INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toa-hong-nhan', 'Tỏa Hồng Nhan', 'May Your Heart Be Like Mine', 'https://phimimg.com/upload/vod/20250116-1/07a3b42674e44629a442e6f69ec4d77a.jpg', 'https://phimimg.com/upload/vod/20250116-1/84a58d6d01bec09d954ee27e03f717ba.jpg', '<p>Xuất thân danh giá nhưng gia cảnh sa sút, hiệp đạo Tạ Thiên Hành nằm mơ cũng không ngờ rằng chỉ nhận một nhiệm vụ đã khiến thân phận của mình thay đổi kinh thiên động địa! Vì dung mạo giống hệt mục tiêu nhiệm vụ Lục Thần, chỉ sau một đêm, Tạ Thiên Hành từ một hiệp đạo khốn khó biến thành một phú thương hưởng vinh hoa phú quý không hết! Tuy nhiên, bên dưới vẻ ngoài tưởng chừng tươi đẹp ấy lại ẩn chứa vô số ý định giết người, tất cả những người xung quanh dường như đều mang hai bộ mặt.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hao Fushen","avatar":""},{"name":"Tan Yanyan","avatar":""},{"name":"Liu Shanglin","avatar":""},{"name":"Sun Qixuan","avatar":""},{"name":"Li Boyan","avatar":""},{"name":"Ren Xuehai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Wei Yuan Jun Xin Si Wo Xin","唯愿君心似我心","Suo Hong Yan","紅顔を鎖す","쇄홍안","O Rosto Prisioneiro","ภารกิจลับโจรสองหน้า","May Your Heart Be Like Mine","锁红颜"]', 1784690324173);
