INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ma-dao-thien-su-u-minh-hoang-tuyen', 'Ma Đạo Thiên Sư: U Minh Hoàng Tuyền', 'The Savior of the World', 'https://phimimg.com/upload/vod/20250116-1/99cc5c8c03193fc384e2e8c7100e57e6.jpg', 'https://phimimg.com/upload/vod/20250116-1/6cf33fd00f942688c847ef7e4ef99cb5.jpg', '<p>Vương Huyền Chi ngay từ ngày sinh ra đã bị gieo vào Ma Hồn, chỉ cần một chút bất cẩn sẽ mất đi lý trí. Để hoàn toàn trừ khử Ma Hồn, Vương Huyền Chi cùng đồng đội đến trấn Vong Xuyên, với ý định vượt qua Vong Xuyên để tiến đến nơi phân cách ba giới, chỉ còn cách hơn nửa bước chân. Tuy nhiên, họ nghe được câu chuyện về mối tình đầy đau khổ giữa người lái đò Lương Nhân và nữ yêu tinh. Vương Huyền Chi và những người đồng hành quyết định tiến vào địa cung, tìm bức họa chân dung của nữ yêu tinh để đánh thức nàng, giúp hai người trùng phùng.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Ryan Kuo","avatar":""},{"name":"吕燕蓓","avatar":""},{"name":"Zhang Jiachuan","avatar":""},{"name":"Mao Fan","avatar":""},{"name":"赵启航","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["마도천사: 유명황천","魔道天师: 幽冥黄泉"]', 1784690324173);
