INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-chuot', 'Vua Chuột', 'EVIL OF THE RAT', 'https://phimimg.com/upload/vod/20250116-1/a8cb7ae912c8cc6e179f84fa71d64586.jpg', 'https://phimimg.com/upload/vod/20250116-1/3c3bfbe6034bc8097e6b670d5fe4d7fd.jpg', '<p>Hạ Thiên và Lâm Phong vì muốn cứu một cô bé câm điếc mà xâm nhập vào một nhà máy đen tối. Từng bước một, họ dần vạch trần âm mưu tham lam của tên giám đốc. Tuy nhiên, đàn chuột đột biến bất ngờ phản công, và Lâm Phong đã hy sinh bản thân để cứu Hạ Thiên. Cuối cùng, Hạ Thiên tiêu diệt được Vua chuột, giải cứu cô bé, đồng thời ngăn chặn âm mưu của nhà máy đen tối khi lợi dụng Vua Chuột để trục lợi, gây hại cho mô trường và các loài sinh vật.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Candice Zhao","avatar":""},{"name":"Dong Yan Lei","avatar":""},{"name":"张婕","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The King of Disaster","鼠王"]', 1784690324173);
