INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-san-ma-tuy-2', 'Thợ Săn Ma Túy 2', 'Drug Hunter 2', 'https://phimimg.com/upload/vod/20250116-1/e585efc602d2655aea3b7a3daa760195.jpg', 'https://phimimg.com/upload/vod/20250116-1/ea72f6ca6d6b12f4779ed811160f502d.jpg', '<p>Đội trưởng Đội Phòng chống Ma túy thành phố, Nhâm Vũ Phàm, đã nhắm đến một nhóm buôn ma túy xảo quyệt. Khi nhận được tin nhóm này sẽ tiến hành giao dịch ma túy tại bến cảng cũ, Nhâm Vũ Phàm dẫn đội mai phục, chuẩn bị bắt quả tang. Tuy nhiên, không ngờ rằng bọn buôn ma túy gồm Tạ Đại Phúc và Tạ Nhị Đầu lại dùng đám tang làm vỏ bọc ở làng Lam Khê. Nhâm Vũ Phàm không ngại hiểm nguy, dấn thân vào ngôi làng Lam Khê bí ẩn và phức tạp, từ đó hé lộ một bí mật chưa từng được biết đến...</p>', 'Full', 1, 'single', 'completed', 7, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Gao Jian","avatar":""},{"name":"Peng Bo","avatar":""},{"name":"Chunyu Shanshan","avatar":""},{"name":"Jackson Liu","avatar":""},{"name":"Zhao Jing","avatar":""},{"name":"Wang Yabin","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["猎毒者2"]', 1784690324173);
