INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-quy-ao-at', 'Phú Quý Ào Ạt', 'Money Is Coming', 'https://phimimg.com/upload/vod/20250103-1/bd7437f3eb4781aabd7e49b50954a87d.jpg', 'https://phimimg.com/upload/vod/20250103-1/dafdb20101bf3fc244c93be5501259d4.jpg', '<p>Một nữ sinh viên đại học vô tình xuyên vào một cuốn sách, trở thành quận chúa Việt Hi - nữ phụ độc ác sống không quá ba chương. Để bảo vệ mạng sống, cô quyết đoán chọn cách về quê sống, tránh xa cốt truyện. Nhưng sau khi Ninh Sơ Hi cảm nhận được sự tốt đẹp của tình thân ở quê, cô dần có sự đồng cảm với thế giới này. Cô không chỉ muốn cứu lấy bản thân mà còn muốn cứu những sinh mệnh cũng đang bị cốt truyện chính giày vò. Ninh Sơ Hi quyết định cứu Tiêu Tinh Hành, nhân vật nam phụ vốn sẽ chết vào một thời điểm đã được định sẵn, đồng thời kết làm đồng minh với hắn để chống lại cốt truyện chính, giải cứu gia tộc bị tiêu diệt oan uổng của nguyên chủ.</p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lin Zehui","avatar":""},{"name":"Zhi Yue","avatar":""},{"name":"Wang Xingwei","avatar":""},{"name":"Quan Rui","avatar":""},{"name":"Ning Xianzhou","avatar":""},{"name":"Mu Leen","avatar":""},{"name":"Yu Junyi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["穿书后成了大佬的咸鱼抱枕","Money is Coming","Fu.Gui.Bi.Ren.Tai.Shen","富贵逼人太甚"]', 1784690324173);
