INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-va-luat', 'Người Và Luật', 'Laws of Man', 'https://phimimg.com/upload/vod/20250118-1/9e8477f2e798f0ced4575de74761fc50.jpg', 'https://phimimg.com/upload/vod/20250118-1/b077f70129e72be9189a71865acb28c5.jpg', '<p>Vào đầu Chiến tranh Lạnh, hai cảnh sát liên bang Mỹ truy đuổi một sát nhân nguy hiểm qua những sa mạc khắc nghiệt ở Nevada. Hành trình này không chỉ là cuộc chiến sinh tồn mà còn phơi bày ranh giới mong manh giữa công lý và đạo đức trong bối cảnh thế giới đầy biến động.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jacob Keohane","avatar":""},{"name":"Jackson Rathbone","avatar":""},{"name":"Dermot Mulroney","avatar":""},{"name":"Harvey Keitel","avatar":""},{"name":"Keith Carradine","avatar":""},{"name":"Graham Greene","avatar":""},{"name":"Kelly Lynn Reiter","avatar":""},{"name":"James Urbaniak","avatar":""},{"name":"Forrie J. Smith","avatar":""},{"name":"Richard Brake","avatar":""},{"name":"Michael P. Walker","avatar":""},{"name":"Johnny Ray","avatar":""},{"name":"Scott Hunter","avatar":""},{"name":"William Shannon Williams","avatar":""},{"name":"Ashley Gallegos","avatar":""},{"name":"Jas","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Laws of Man"]', 1784690324173);
