INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-tong-co-ky-an', 'Đại Tống Có Kỳ Án', 'The Song Inquisitor', 'https://phimimg.com/upload/vod/20250109-1/49872281b5637a789718331ae2910c0a.jpg', 'https://phimimg.com/upload/vod/20250109-1/646a11fe621a6c8d9b9fe9514003858d.jpg', '<p>Bộ phim kể về câu chuyện thời kỳ Nam Tống. Quan đề hình Tống Từ trong chuyến đi tuần tra bên ngoài đã gặp nguy hiểm và vô tình kết bạn với nghệ nhân kịch Nam là Triệu Tri Đình, Vương Lăng và vũ cơ Hà Ôn Ngưng. Bốn con người với xuất thân khác nhau, cùng nhau trải qua nhiều thử thách, nỗ lực hợp tác, chung tay liên tiếp giải quyết bốn vụ án giết người thông qua các phương pháp như suy luận, thẩm vấn, nghiệm thi. Họ đã đòi lại công lý cho người đã khuất và trả lại công bằng cho người còn sống.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Gao Yiwei","avatar":""},{"name":"Cai Zhengjie","avatar":""},{"name":"Wang Junbi","avatar":""},{"name":"Liu Jianyu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Da Song You Qi An","大宋提刑官之伶人传","大宋有奇案"]', 1784690324173);
