INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bat-phu-tuong-quan-bat-phu-khanh', 'Bất Phụ Tướng Quân Bất Phụ Khanh', 'Always My General', 'https://phimimg.com/upload/vod/20250115-1/2b7cb4a3e00b53bc84025a11a5e4c112.jpg', 'https://phimimg.com/upload/vod/20250115-1/c0a6a6b5c49975982fa130790518e2c4.jpg', '<p>Châu Sơ, chủ soái quân Huyền Giáp từ bé đã nữ cải trang nam, cô khải hoàn về Bắc Chiêu nhưng lại bị vây đánh, mà kẻ chủ mưu chính là phó tướng Từ Hàn Chi kết nghĩa huynh đệ với cô. May mắn thay, cô được Thượng Khả Phong, kình địch ngày xưa trên chiến trường cứu giúp. Châu Sơ khôi phục lại thân phận nữ nhi và lấy biệt danh Tiết Thập Tam để đột nhập Đăng Doanh Lâu, nơi ở của Từ Hàn Chi, chờ thời cơ trả thù. Cô khéo léo xoay chuyển giữa hai người đàn ông để tìm ra chân tướng, vừa được cưng chiều nhưng thực chất vừa phải đối diện với nguy cơ luôn rình rập.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"He Xuanlin","avatar":""},{"name":"Gao Mingchen","avatar":""},{"name":"Zhou Haoshan","avatar":""},{"name":"Jiang Yushun","avatar":""},{"name":"Niu Xinxin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["不负将军不负卿"]', 1784690324173);
