INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngan-hang-cua-dave-2-nguoi-cho-vay-co-don', 'Ngân Hàng Của Dave 2: Người Cho Vay Cô Đơn', 'Bank Of Dave 2: The Loan Ranger', 'https://phimimg.com/upload/vod/20250113-1/cf2a4b4edfc93303ae482708568bacd8.jpg', 'https://phimimg.com/upload/vod/20250113-1/b39593a147977ffd08995c0054778222.jpg', '<p>Hai người lạ bí mật được cơ quan điệp viên cung cấp công việc mới, đưa họ vào một cuộc sống đầy kịch tính, giàu có và khám phá du lịch. Duy nhất điều kiện: họ phải nhận danh tính mới thông qua một cuộc hôn nhân sắp xếp.</p>', 'Full', 1, 'single', 'completed', 8, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Rory Kinnear","avatar":""},{"name":"Jo Hartley","avatar":""},{"name":"Chrissy Metz","avatar":""},{"name":"Amit Shah","avatar":""},{"name":"Rob Delaney","avatar":""},{"name":"Leila Farzad","avatar":""},{"name":"Hugh Bonneville","avatar":""},{"name":"Dan Fogler","avatar":""},{"name":"Ella Bruccoleri","avatar":""},{"name":"Samantha Power","avatar":""},{"name":"Pearce Quigley","avatar":""},{"name":"Jaimi Barbakoff","avatar":""},{"name":"Jenny Fitzpatrick","avatar":""},{"name":"Calvin A. Dean","avatar":""},{"name":"George Rainsford","avatar":""},{"name":"William Travis","avatar":""},{"name":"Bill Blackwoo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Bank of Dave: The Sequel","Bank of Dave 2: The Loan Ranger"]', 1784690324174);
