INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trieu-van-tan', 'Triều Vân Tán', 'Towards The Truth', 'https://phimimg.com/upload/vod/20250109-1/1c1e108eeea6dff6eb214d6d15a3de33.jpg', 'https://phimimg.com/upload/vod/20250109-1/08049e183a2dee8a3f2fea13fadca1ef.jpg', '<p>Mười năm sau khi sống sót sau vụ thảm sát gia tộc của mình, Shen Song, hiện là một đầu bếp khiêm tốn, bị cuốn vào hành trình tìm kiếm công lý khi một đám cháy lễ hội phát hiện ra những tàn tích ẩn giấu. Được bổ nhiệm làm điều tra viên dân sự của hoàng đế, anh giải quyết hàng loạt vụ án kỳ lạ, vạch trần những âm mưu gắn liền với quá khứ bi thảm của gia đình anh.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 11, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wang Youshuo","avatar":""},{"name":"Zhang Chenxiao","avatar":""},{"name":"Jin Jiayue","avatar":""},{"name":"Liu Di","avatar":""},{"name":"Jason Sze","avatar":""},{"name":"Yilia","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Zhao Yun San","朝云散"]', 1784690324174);
