INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-doi-la-nhung-su-lua-chon', 'Cuộc Đời Là Những Sự Lựa Chọn', 'Life Is A Choice', 'https://phimimg.com/upload/vod/20250103-1/b1685b719de2f75aec01d871ff3ae29d.jpg', 'https://phimimg.com/upload/vod/20250103-1/4a0062b2c6b9cc2e22e04d8f397ed65c.jpg', '<p>Bị áp lực bởi cuộc sống hôn nhân, Cố Niệm, một người phụ nữ đã mệt mỏi với cuộc sống gia đình, bất ngờ có cơ hội trải nghiệm công nghệ cao để quay ngược thời gian và lựa chọn lại cuộc đời. Cô quyết định sẽ thay đổi thái độ sống của mình và không còn bị cuốn vào tình yêu. Tuy nhiên, điều bất ngờ là cô đã bỏ qua giới tính của nhân vật và vô tình xuyên không vào thân xác của một người đàn ông hoàn toàn xa lạ. Cô phải sử dụng hình hài nam giới này để cứu vớt chính mình trong quá khứ. Những lựa chọn khó khăn trong cuộc sống như thế nào sẽ chờ đợi cô phía trước?</p>', 'Tập 23', 23, 'series', 'ongoing', 13, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Gai Yuexi","avatar":""},{"name":"Luo Zheng","avatar":""},{"name":"Xu Yanghao","avatar":""},{"name":"Jingge Cui","avatar":""},{"name":"Li Xinran","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["人生とは選択問題である","인생시도선택제","เลือกชีวิตลิขิตฝัน","人生是道選擇題","Life is a Choice","Cuộc Đời Là Những Sự Lựa Chọn","人生是道选择题"]', 1784690324174);
