INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('minh-nguyet-dan', 'Minh Nguyệt Dẫn', 'Bright Moon', 'https://phimimg.com/upload/vod/20250103-1/b099a58ddd63c42f6d6be7bb3e16d8d2.jpg', 'https://phimimg.com/upload/vod/20250103-1/fc0fde73a5ab6b40123266f5b4e9c9e0.jpg', '<p>Bảy năm sau vụ thảm sát gia đình cô, Jiang Chan phát hiện ra mối liên hệ với Li Sha Lou, một tổ chức sát thủ bí mật. Để khám phá sự thật, cô thông thạo võ thuật của gia đình mình, lấy bí danh Hua Shan và thâm nhập vào nhóm.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 13, 2025, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wang Haoxuan","avatar":""},{"name":"Cao Saiya","avatar":""},{"name":"Yuan Ziming","avatar":""},{"name":"Ziyi Fang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Ming Yue Yin","Bright Moon Citation","明月引"]', 1784690324174);
