INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('missing-you', 'Missing You', 'Missing You', 'https://phimimg.com/upload/vod/20250102-1/92c6f411a5f9cc9b2a2033772bfa1923.jpg', 'https://phimimg.com/upload/vod/20250102-1/d5a5940faf7f64f89da9335a1c68e5d0.jpg', '<p>Sau khi được ghép đôi với vị hôn phu đã mất tích nhiều năm trước trên ứng dụng hẹn hò, thanh tra Kat Donovan nhận ra rằng có một số bí mật tốt nhất nên ngủ yên trong quá khứ.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 13, 2025, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Rosalind Eleazar","avatar":""},{"name":"Jessica Kate Plummer","avatar":""},{"name":"Richard Armitage","avatar":""},{"name":"Lenny Henry","avatar":""},{"name":"Steve Pemberton","avatar":""},{"name":"Paul Kaye","avatar":""},{"name":"Samantha Spiro","avatar":""},{"name":"Lisa Faulkner","avatar":""},{"name":"Mary Malone","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Tu me manques","Harlan Coben''s Missing You","Missing You"]', 1784690324174);
