INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bryan-johnson-nguoi-khao-khat-truong-sinh', 'Bryan Johnson: Người Khao Khát Trường Sinh', 'Don''t Die: The Man Who Wants to Live Forever', 'https://phimimg.com/upload/vod/20250102-1/6453f18222168e0120b12f738528b6f7.jpg', 'https://phimimg.com/upload/vod/20250102-1/83a8620dd569e08f01e00c5ad2befeff.jpg', '<p>Trong bộ phim tài liệu này, doanh nhân giàu có Bryan Johnson mạo hiểm cả sức khỏe và tài sản để thách thức quá trình lão hóa và kéo dài tuổi thọ vượt qua mọi giới hạn đã biết.</p>', 'Full', 1, 'single', 'completed', 10, 2025, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Bryan Johnson","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["O Homem que Quer Viver para Sempre","长生不死：硅谷富豪的逆龄人生","Don''t Die - Der Mann, der unsterblich sein will","Dö inte: Mannen som vill leva för evigt","Don''t Die: The Man Who Wants to Live Forever"]', 1784690324174);
