INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bryan-johnson-nguoi-khao-khat-truong-sinh', 'Bryan Johnson: Người Khao Khát Trường Sinh', 'Don''t Die: The Man Who Wants to Live Forever', 'bryan johnson: người khao khát trường sinh don''t die: the man who wants to live forever bryan johnson o homem que quer viver para sempre 长生不死：硅谷富豪的逆龄人生 don''t die - der mann, der unsterblich sein will dö inte: mannen som vill leva för evigt don''t die: the man who wants to live forever', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muc-than-ky', 'Mục Thần Ký', 'Tales Of Herding Gods', 'https://phimimg.com/upload/vod/20241028-1/79ad9da402005ec184aa14bd1f781d05.jpg', 'https://phimimg.com/upload/vod/20241028-1/33727a6c4cec6ab127dbb0092bc99c9e.jpg', '<p>Tần Mục sinh ra đã có thân thể phàm trần, sau khi khảo nghiệm, hắn trở thành thủ lĩnh của Thiên Ma Phái, được nước Diên Khang phong làm đệ nhất Thái Tuyết. Trong trận chiến phản loạn của Vương quốc Yankang, Tần Mục đã thu hút quỷ thần, gây ra một cơn bão lớn, sau đó theo Wu Khan vào Hoàng cung Lâu Lan, và tự mình chiến đấu khắp Thánh Cung. Ông trở về Diên Khang, hỗ trợ sư đoàn quốc gia dập tắt cuộc nổi loạn, xây dựng và bắn Đại bác Thần Mặt trời, và sau đó giành được quyền thừa kế của hoàng đế loài người và trở thành một thế hệ hoàng đế loài người mới. Tình cờ, Tần Mục biết được kinh nghiệm sống của mình, dưới sự giúp đỡ của Đạo Môn Tiểu Vũ Cảnh và những người khác, hắn đã mở ra đại thế giới cải cách siêu nhiên Đạo giáo.</p>', 'Tập 91', 120, 'hoathinh', 'ongoing', 81, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Ruoyu Zhang","avatar":""},{"name":"李欣","avatar":""},{"name":"程玉珠","avatar":""},{"name":"Qingqing Du","avatar":""},{"name":"虞晓旭","avatar":""},{"name":"于凯隆","avatar":""},{"name":"高嗣航","avatar":""},{"name":"Yuhang Wang","avatar":""},{"name":"Hao Tang","avatar":""},{"name":"张恒","avatar":""},{"name":"刘宇轩","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["牧神记","Mu Shen Ji","Mushen Ji","牧神记动画","Contos dos Deuses Pastores","Contos de Qin Mu","Notas do Pastor","Diário do Pastor","O Conto do Pastor","Tales of Qin Mu","Shepherd''s Notes","Shepherd''s Diary","The Shepherd''s Tale","Tales of Herding Gods"]', 1784690324174);
