INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('do-thi-co-tien-y', 'Đô Thị Cổ Tiên Y', 'Urban Miracle Doctor', 'https://phimimg.com/upload/vod/20241018-1/f39df234908b4305fdd20c97020c0eea.jpg', 'https://phimimg.com/upload/vod/20241018-1/422e01866d2bfcb0adfd4ae2a31ef32f.jpg', '<p>Sinh viên đại học năm thứ ba Diệp Bất Phàm, làm người giả bị đụng cho mẫu thân gom góp tiền chữa bệnh, nhưng gặp phải không theo như chiêu thức ra bài nữ tài xế, bị đụng sau lấy được được Cổ y môn truyền thừa, từ đây thông y thuật, tu công pháp, chơi chuyển đô thị, thắng được vô số người đẹp xem trọng.</p>', 'Tập 192', 240, 'hoathinh', 'ongoing', 77, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Dushi Gu Xian Yi","都市古仙医","Du Shi Gu Xian Yi","Antiguo Doctor Inmortal Urbano","The Immortal Doctor","Urban Ancient Immortal","Medicine City Ancient Fairy Doctor","Urban Ancient Fairy Doctor","Urban Ancient Immortal Doctor","Immortal Doctor In Modern City","Urban Miracle Doctor"]', 1784690324174);
