INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('goc-toi-nhan-ban', 'Góc Tối Nhân Bản', 'Orphan Black: Echoes', 'https://phimimg.com/upload/vod/20260624-1/a5b24deb3ecb5891b80f4cc1e1263db2.jpg', 'https://phimimg.com/upload/vod/20260624-1/95306f54f4f39c93a66c6fca28c57ac2.jpg', '<p>Orphan Black: Echoes là phần ngoại truyện của Orphan Black, lấy bối cảnh năm 2052, khoảng 37 năm sau các sự kiện của loạt phim gốc. Câu chuyện xoay quanh Lucy (Krysten Ritter), một phụ nữ tỉnh dậy mà không có ký ức về bản thân. Cô nhanh chóng phát hiện mình không phải con người bình thường mà là một “bản in sinh học” (print-out) được tạo ra bằng công nghệ tiên tiến.</p>', 'Tập 9', 10, 'series', 'ongoing', 100, 2024, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Krysten Ritter","avatar":""},{"name":"Keeley Hawes","avatar":""},{"name":"Rya Kihlstedt","avatar":""},{"name":"Amanda Fix","avatar":""},{"name":"Avan Jogia","avatar":""},{"name":"James Hiroyuki Liao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Orphan Black Echoes (2023)","Клонинги: Ехо","Orphan Black: Echoes (2023)","Orphan Black: Echoes"]', 1784690324174);
