INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-la-mu-quang-argentina-phan-1', 'Yêu Là Mù Quáng: Argentina (Phần 1)', 'Love Is Blind: Argentina (Season 1)', 'https://phimimg.com/upload/vod/20241129-1/d743562d560c52830d7c5b1d50dc68a2.jpg', 'https://phimimg.com/upload/vod/20241129-1/ac4fdacb4a9b218dea66a0ffe18143a3.jpg', '<p>Các lô mở ra và cả trái tim cũng vậy – ngay lúc này ở Argentina. Ai sẽ vượt qua được vẻ bề ngoài trong thử nghiệm nơi câu nói &quot;Anh/em đồng ý&quot; được thốt lên dù chưa từng gặp mặt?</p>', 'Full', 11, 'tvshows', 'completed', 42, 2024, 'Vietsub', 'FHD', 'Argentina', 0, '[{"name":"Darío Barassi","avatar":""},{"name":"Wanda Nara","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Love Is Blind: Argentina"]', 1784690324174);
