INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hen-ho-voi-sat-nhan', 'Hẹn Hò Với Sát Nhân', 'Woman of the Hour', 'https://phimimg.com/uploads/movies/20260710/hen-ho-voi-sat-nhan-thumb.webp', 'https://phimimg.com/uploads/movies/20260710/hen-ho-voi-sat-nhan-poster.webp', '<p>Cheryl Bradshaw (Anna Kendrick thủ vai) tham gia chương trình truyền hình về hẹn hò - The Dating Game với khát khao được nổi tiếng. Tại đây, cô nàng đã gặp gỡ Rodney Alcala - tên sát nhân đội lốt một nhiếp ảnh gia lãng tử và đối đáp cực kỳ hài hước, thông minh trong chương trình hẹn hò. Quyết định kết đôi cùng Rodney Alcala, trong quá trình hẹn hò, Cheryl Bradshaw dần khám phá ra hàng loạt bí mật gây sốc được che giấu khéo léo bởi cái lốt người đàn ông hoàn hảo: đội lốt một gã sát nhân, kẻ biến thái đã chủ mưu rất nhiều vụ hiếp dâm và giết người man rợ.</p>', 'Full', 1, 'single', 'completed', 50, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Anna Kendrick","avatar":""},{"name":"Daniel Zovatto","avatar":""},{"name":"Nicolette Robinson","avatar":""},{"name":"Jedidiah Goodacre","avatar":""},{"name":"Autumn Best","avatar":""},{"name":"Pete Holmes","avatar":""},{"name":"Kelley Jakle","avatar":""},{"name":"Kathryn Gallagher","avatar":""},{"name":"Tony Hale","avatar":""},{"name":"Matt Visser","avatar":""},{"name":"Rob Morton","avatar":""},{"name":"Dylan Schmid","avatar":""},{"name":"Karen Holness","avatar":""},{"name":"Denalda Williams","avatar":""},{"name":"Jessie Fraser","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Rodney & Sheryl","The Dating Game","El Asesino Del Juego De Citas","