INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-luc-linh-vo', 'Đại Lục Linh Võ', 'Legend of Lingwu Continent', 'https://phimimg.com/upload/vod/20250224-1/f68af9aa9f67c035f72938fb5291ba55.jpg', 'https://phimimg.com/upload/vod/20250224-1/f10d225c86bd40ae0eaa2ef5d957c24e.jpg', '<p>Một thế giới mà linh lực và võ hồn cùng tồn tại, chỉ một ý niệm của linh tu có thể dời non lấp biển, võ giả tay không phá vỡ thiên địa. Thiên tài Thần Thiên, sau 10 tuổi võ hồn không thấy, linh hải khô cạn, trở thành phế vật của gia tộc. Sau đó vào nhầm đại trận của Cổ Kiếm Đế, có được cơ duyên lớn, từ đó cuộc đời thay đổi, phá Thiên Đạo, nắm giữ luân hồi, độ Đế kiếp, trở thành người đứng đầu Linh Võ Đại Lục.</p>', 'Tập 193', 240, 'hoathinh', 'ongoing', 44, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Emperor Lingwu","Ling Wu Da Lu","Lingwu Dizun","灵武大陆","Ling Wu Dalu","Lingwu Dalu","Legend of Lingwu Continent"]', 1784690324174);
