INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tau-dem-kinh-hoang', 'Chuyến Tàu Đêm Kinh Hoàng', 'Nightsleeper', 'https://phimimg.com/upload/vod/20260622-1/66c639c7c15a9cbe387cb66bd1bf15cc.jpg', 'https://phimimg.com/upload/vod/20260622-1/82d0862b8e50a4f494331ad769349d9e.jpg', '<p>Cảnh sát ngoài giờ Joe Roag lên chuyến tàu đêm như một hành khách bình thường. Tuy nhiên, anh phát hiện hệ thống điều khiển đoàn tàu đã bị tin tặc xâm nhập. Đoàn tàu bị điều khiển từ xa, không thể dừng lại và đang lao thẳng về London với hàng trăm hành khách mắc kẹt bên trong.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 63, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Alexandra Roach","avatar":""},{"name":"Joe Cole","avatar":""},{"name":"Alex Ferns","avatar":""},{"name":"Sharon Small","avatar":""},{"name":"James Cosmo","avatar":""},{"name":"David Threlfall","avatar":""},{"name":"Daniel Cahill","avatar":""},{"name":"Lois Chimimba","avatar":""},{"name":"Sharon Rooney","avatar":""},{"name":"Ruth Madeley","avatar":""},{"name":"Katie Leung","avatar":""},{"name":"Leah MacRae","avatar":""},{"name":"Gabriel Howell","avatar":""},{"name":"Scott Reid","avatar":""},{"name":"Pamela Nomvete","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Night Sleeper - Ein Zug außer Kontrolle","Nightsleeper"]', 1784690324174);
