INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-nhan-97-phan-1', 'Dị Nhân ''97 (Phần 1)', 'X-Men ''97 (Season 1)', 'https://phimimg.com/upload/vod/20260706-1/1578b0b0bc853d20f595f85803113417.jpg', 'https://phimimg.com/upload/vod/20260706-1/3b6b3679f3c76dcc329a9df6333ab36f.jpg', '<p>&quot;X-Men &quot;97&quot; tiếp tục câu chuyện sau loạt phim hoạt hình gốc. Sau cái chết của Giáo sư Xavier, nhóm X-Men phải đối mặt với một thế giới ngày càng thù địch với người đột biến (mutants). Trong khi cố gắng giữ vững di sản của giáo sư và bảo vệ những người bị xã hội ruồng bỏ, họ đối đầu với các thế lực cũ và mới – bao gồm cả những kẻ từng là đồng minh.

Dưới sự lãnh đạo mới của Magneto, các thành viên như Cyclops, Jean Grey, Storm, Wolverine, Rogue, Beast, và Gambit phải học cách thích nghi, gắn kết và chiến đấu vì một tương lai mà cả người thường lẫn dị nhân đều có thể cùng tồn tại.</p>', 'Hoàn Tất (10/10)', 10, 'hoathinh', 'completed', 43, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["X战警97","එක්ස්-මෙන් ''97","X-මෙන් ''97","X-Men 97","Marvel Animation''s X-Men ''97","Marvel Studios'' X-Men ''97","X-Force ''97","X-Men ''97"]', 1784690324174);
