INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cham-vao-ky-uc', 'Chạm Vào Ký Ức', 'Touch', 'https://phimimg.com/upload/vod/20260704-1/7cd693990a87cba1907ac0a31ca95001.jpg', 'https://phimimg.com/upload/vod/20260704-1/a4e20cfdb6e90885f40b23b19431e49f.jpg', '<p>Câu chuyện tình yêu vượt thời gian, khi một người đàn ông dành cả cuộc đời tìm kiếm mối tình đầu đã biến mất 50 năm trước. Cuộc hành trình trải dài khắp các lục địa, mang đến cho ông những trải nghiệm lãng mạn và hồi hộp, khi ông đối mặt với sự thật và ý nghĩa của tình yêu đích thực trước khi thời gian của mình cạn kiệt.</p>', 'Full', 1, 'single', 'completed', 47, 2024, 'Vietsub', 'FHD', 'Iceland', 0, '[{"name":"Egill Ólafsson","avatar":""},{"name":"Kōki","avatar":""},{"name":"Pálmi Kormákur Baltasarsson","avatar":""},{"name":"Masahiro Motoki","avatar":""},{"name":"Yoko Narahashi","avatar":""},{"name":"Ruth Sheen","avatar":""},{"name":"Masatoshi Nakamura","avatar":""},{"name":"Meg Kubota","avatar":""},{"name":"María Ellingsen","avatar":""},{"name":"Benedikt Erlingsson","avatar":""},{"name":"Sigurður Ingvarsson","avatar":""},{"name":"Starkadur Petursson","avatar":""},{"name":"Tatsuya Tagawa","avatar":""},{"name":"Charles Nishikawa","avatar":""},{"name":"Eiji Mihara","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Touch","Touch - Nos étreintes passées","첫사랑을 찾아","Snerting"]', 1784690324174);
