INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoi-2', 'Cười 2', 'Smile 2', 'https://phimimg.com/upload/vod/20241109-1/350c66465aa00bd060e1ac247b076021.jpg', 'https://phimimg.com/upload/vod/20241109-1/a8d5f6a6b3e04b3e3db511f15ac151f2.jpg', '<p>Chuẩn bị bắt tay vào chuyến lưu diễn vòng quanh thế giới mới, ngôi sao nhạc pop toàn cầu Skye Riley bắt đầu trải qua những sự kiện ngày càng đáng sợ và không thể giải thích được. Bị choáng ngợp bởi nỗi kinh hoàng ngày càng leo thang và áp lực của sự nổi tiếng, Skye buộc phải đối mặt với quá khứ đen tối của mình để giành lại quyền kiểm soát cuộc sống trước khi nó vượt khỏi tầm kiểm soát.</p>', 'Full', 1, 'single', 'completed', 72, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Naomi Scott","avatar":""},{"name":"Rosemarie DeWitt","avatar":""},{"name":"Dylan Gelula","avatar":""},{"name":"Lukas Gage","avatar":""},{"name":"Peter Jacobson","avatar":""},{"name":"Miles Gutierrez-Riley","avatar":""},{"name":"Raúl Castillo","avatar":""},{"name":"Ray Nicholson","avatar":""},{"name":"Jon Rua","avatar":""},{"name":"Kyle Gallner","avatar":""},{"name":"Erika Chase","avatar":""},{"name":"Drew Barrymore","avatar":""},{"name":"Mila Falkof","avatar":""},{"name":"Daphne Zelle","avatar":""},{"name":"Ivan Carlo","avatar":""},{"name":"Delphi Harrington","avatar":""},{"name":"Zebedee Row","avatar":""},{"name":"Jon Se","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Too Much for One Heart.","Smile Deluxe","Gülümse 2","危笑 2","لبخند ۲","Úsměv 2","Sorria 2","Sonríe 2","Smile 2","Smiješak 2","ابتسم 2","夺命微笑2","微笑2","Buzëqeshja 2","Ժպիտ 2"]', 178469