INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ham-silo-phan-2', 'Hầm SILO (Phần 2)', 'Silo (Season 2)', 'https://phimimg.com/upload/vod/20241118-1/5ba867d65bb2970fedc0f75c7020198d.jpg', 'https://phimimg.com/upload/vod/20260704-1/ae99f0ea394e499a1dd13d3245c703db.jpg', '<p>Trong một tương lai điêu tàn và độc hại, hàng ngàn người sống trong một silo khổng lồ ở sâu trong lòng đất. Sau khi cảnh sát trưởng phá vỡ một nguyên tắc chủ chốt và cư dân mất mạng một cách bí ẩn, kỹ sư Juliette bắt đầu phát hiện ra những bí mật gây sốc và sự thật về silo.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 33, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rebecca Ferguson","avatar":""},{"name":"Common","avatar":""},{"name":"Harriet Walter","avatar":""},{"name":"Chinaza Uche","avatar":""},{"name":"Avi Nash","avatar":""},{"name":"Rick Gomez","avatar":""},{"name":"Tim Robbins","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["羊毛战记","სილოსი","사일로","지하창고 사일로의 비밀","Бункер","الصومعة","Wool","Silo"]', 1784690324174);
