INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tu-pho-tau-2-2014', 'Thám Tử Phố Tàu 2', 'Detective Chinatown 2', 'https://phimimg.com/upload/vod/20240301-1/7edf918650117b7ff9cde28f0d5e382f.jpg', 'https://phimimg.com/upload/vod/20240301-1/f6b0ea28502c693608654dbc4ed1b46d.jpg', '<p>Có nhiều vụ án kỳ lạ hơn ở nước ngoài, đệ tử Lâm Mặc của Đường Nhân, hacker thiên tài Kiko và nhiều thám tử và nhân vật mới đã xuất hiện! Để tìm ra sự thật, các thám tử cũ tập hợp lại để làm rung chuyển tình hình ở khu phố Tàu! Phong cách hài hước của câu chuyện hồi hộp có hàm ý sâu sắc, thể hiện một xu hướng mới trong điều tra vụ án.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 45, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Roy Chiu","avatar":""},{"name":"Shang Yuxian","avatar":""},{"name":"Zhang Yishang","avatar":""},{"name":"Kenny Bee","avatar":""},{"name":"Yu Haoming","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Gây Cấn","slug":"gay-can","id":"e51b1ce9565c571ef91ac5a1569631e5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324174);
