INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tram-than-pham-tran-than-vuc-phan-1', 'Trảm Thần: Phàm Trần Thần Vực (Phần 1)', 'Slay The Gods (Season 1)', 'trảm thần: phàm trần thần vực (phần 1) slay the gods (season 1) mã chính dương viên minh triết tam thạch hồ lương vĩ tôn hy hạc tôn duệ dương lưu thiên hàm đoàn nghệ tuyền hạ mịch trần dư hạo uy gia minh ngâm lương khuyển văn sâm đường sách bảo mộc trung dương trần trương thái khang 我在精神病院学斩神 斩神 斩神动画 zhan shen: fanchen shen yu zhan shen wo zai jingshenbing yuan xue zhan shen zhan shen zhanshenzhifanchenshenyu zhan shen zhi fan chen shen yu slay the gods 斩神之凡尘神域 zhanshen i was learning to kill gods in a mental hospital i learn to kill gods in an asylum trảm thần: phàm trần thần vực trảm thần phàm trần thần vực phàm trần thần vực', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-thua-ke-bat-kha-thi', 'Người Thừa Kế Bất Khả Thi', 'The Impossible Heir', 'https://phimimg.com/upload/vod/20240301-1/fa1bb021f14650dda945c589751f9b14.jpg', 'https://phimimg.com/upload/vod/20240301-1/acf599b91478d01bd88d0f0ee2c2b680.jpg', '<p>Câu chuyện xoay quanh một chaebol lớn bậc nhất Hàn Quốc, những con người ấy đã và đang cố gắng để giành lấy ngai vàng tại tập đoàn. Han Tae-O (Lee Jae-Wook) là một người thanh lịch và lạnh lùng. Trong khi Kang In-Ha (Lee Jun-Young),cả mặt tốt và mặt xấu đều tồn tại. Na Hye-won (Hong Su-Zu) là một phụ nữ trẻ.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 43, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Jae-wook","avatar":""},{"name":"Lee Jun-young","avatar":""},{"name":"Hong Su-zu","avatar":""},{"name":"Lee Ji-hoon","avatar":""},{"name":"Lee Hwang-eui","avatar":""},{"name":"Han Sang-jin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324174);
