INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mot-ban-than-khac-phan-2', 'Một Bản Thân Khác (Phần 2)', 'Another Self (Season 2)', 'https://phimimg.com/upload/vod/20260624-1/1b8a2990f41dd8a081436204272f406b.jpg', 'https://phimimg.com/upload/vod/20260624-1/c96819bfde90ff2af4337378a0305b23.jpg', '<p>Khi đến một thị trấn ven biển, ba người bạn kết nối với linh hồn của họ rồi bất ngờ phải đối mặt với những nỗi đau chưa nguôi tù quá khứ của gia đình.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 47, 2024, 'Vietsub', 'FHD', 'Thổ Nhĩ Kỳ', 0, '[{"name":"Tuba Büyüküstün","avatar":""},{"name":"Rıza Kocaoğlu","avatar":""},{"name":"Fırat Tanış","avatar":""},{"name":"Murat Boz","avatar":""},{"name":"Serkan Altunorak","avatar":""},{"name":"Boncuk Yilmaz","avatar":""},{"name":"Füsun Demirel","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Le chemin de l''olivier","또다른 나","الروح الأخرى","Zeytin Ağacı"]', 1784690324174);
