INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-sinh-thanh-nhan-tinh', 'Tái Sinh Thành Nhân Tình', 'Mistress Reincarnation / Aijin Tensei -Sare Tsuma wa Shinda Nochi ni Fukushuu Suru-', 'https://phimimg.com/upload/vod/20260622-1/e87d33c5b4c25b95099dee145a4f2d9a.jpg', 'https://phimimg.com/upload/vod/20260622-1/269023cc6818763d8e30e2201a6ee515.jpg', '<p>Sau nhiều năm nhẫn nhịn thái độ xem thường của gia đình chồng, nỗi phẫn uất của Mayama Chisato lên đến đỉnh điểm khi cô phát hiện chồng mình ngoại tình với cô gái trẻ Mitsui Runa. Khi Chisato đến gặp Runa để chất vấn, giữa họ đã xảy ra xô xát rồi cùng bị xe tông. Khi tỉnh lại trong bệnh viện, Chisato kinh hoàng nhận ra linh hồn mình đang ở trong cơ thể nhân tình của chồng. Tận dụng thân xác mới, cô bắt đầu kế hoạch trả thù tất cả những kẻ đã từng phản bội và hành hạ mình.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 34, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kanon","avatar":""},{"name":"Kento Senga","avatar":""},{"name":"Fujiko Kojima","avatar":""},{"name":"Taiki Sato","avatar":""},{"name":"Riho Takada","avatar":""},{"name":"Atsuko Sakurai","avatar":""},{"name":"Kisuke Iida","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["愛人転生 ーサレ妻は死んだ後に復讐するー","Aijin Tensei - Sare Tsuma wa Shinda Ato ni Fukushuu Suru","Aijin Tensei: Sare Tsuma wa Shinda Nochi ni Fukushu Suru","Mistress Reincarnation: The Cheated Wife Takes Revenge After Death","Aijin Tensei -Sare Tsuma wa Shinda Nochi ni Fukushuu Suru-","Mistress Reincarnation","愛人転生 ―サレ妻は死んだ後に復讐する―"]', 1784690324174);
