INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('wistoria-truong-va-kiem-phan-1', 'Wistoria: Trượng Và Kiếm (Phần 1)', 'Wistoria: Wand And Sword (Season 1)', 'https://phimimg.com/upload/vod/20260413-1/07f7859b2e0fbd38354ff4376ca70dac.jpg', 'https://phimimg.com/upload/vod/20260413-1/ffa72ffce6c681b73586e99c120396ff.jpg', '<p>Will là một cậu bé bước vào học viện ma pháp với mục tiêu trở thành một ma pháp sư. Tuy là một người chăm chỉ thế nhưng cậu có một điểm yếu chết người đó là không thể sử dụng ma pháp. Nhận lại những cái nhìn lạnh lùng của các giáo viên và những bạn bè trong trường nhưng Will không bỏ cuộc mà vẫn hướng về phía trước. Ngay cả khi không thể sử dụng trượng, cậu vẫn cầm thanh kiếm trên tay chiến đấu theo cách riêng của mình trong một thế giới nơi ma pháp là tối cao. Tin vào sức mạnh của bản thân và để giữ lời hứa với người mình yêu quý.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 20, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Reiko Suzuki","avatar":""},{"name":"Atsushi Tamaru","avatar":""},{"name":"Tomohiro Ono","avatar":""},{"name":"Jun Fukuyama","avatar":""},{"name":"Makoto Furukawa","avatar":""},{"name":"Akio Otsuka","avatar":""},{"name":"Hochu Otsuka","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wistoria: Varinha e Espada","Wistoria: Varinhas e Espadas","Wistoria: Varinhas e Espada","杖与剑的魔剑谭","Tsue to Tsurugi no Wistoria","杖と剣のウィストリア Season2","Wistoria''