INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('luc-do-toi-da-chuyen-sinh-thanh-slime-phan-3', 'Lúc Đó Tôi Đã Chuyển Sinh Thành Slime (Phần 3)', 'That Time I Got Reincarnated As A Slime (Season 3)', 'lúc đó tôi đã chuyển sinh thành slime (phần 3) that time i got reincarnated as a slime (season 3) miho okasaki tomoaki maeno takuya eguchi hochu otsuka asuna tomari chikahiro kobayashi jun fukushima rie tanaka rina hidaka anzu haruno aquella vez que reencarne como un slime 關於我轉生變成史萊姆這檔事 tensei shitara slime datta ken 关于我转生变成史莱姆这档事 that time i got reincarnated as a slime tensura regarding reincarnated to slime aquella vez que me convertí en slime moi, quand je me réincarne en slime تولد دوباره به‌عنوان یک اسلایم وقتی به‌عنوان یک اسلایم تناسخ پیدا کردم آن زمان که به‌عنوان یک اسلایم زندگی دوباره یافتم tensei shitara slime datta ken tensei slime tensura 2 tensei shitara slime datta ken 2 転生したらスライムだった件 転スラ tensei shitara slime datta ken 3rd season tensei shitara slime datta ken: coleus no yume tensei shitara slime datta ken s4 tensei shitara slime datta ken 4th season 전생했더니 슬라임이었던 건에 대하여 전생했더니 슬라임이었던 건에 대하여 3기 關於我轉生變成史萊姆這檔事 柯里烏斯之夢 моє переродження в слиз that time i got reincarnated as a slime 2 that time i got reincarnated as a slime: visions of coleus chuyển sinh thành slime', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuyet-the-chien-hon', 'Tuyệt Thế Chiến Hồn', 'Peerless Soul', 'https://phimimg.com/upload/vod/20250219-1/b2facbf6cebbf66d0c728df0b75ad5b9.jpg', 'https://phimimg.com/upload/vod/20250219-1/b880c627b5571d9afd22e58d056e772a.jpg', '<p>Đại lục Thương Lam là nơi nếu muốn thành võ giả thì bắt buộc phải thức tỉnh được võ hồn, từ đó kết nối với trời đất, hấp thụ linh khí, tiến hành tu luyện. Thiếu niên bình thường Tần Nam thức tỉnh được Chiến Thần Chi Hồn để không ngừng trở nên mạnh, để báo đáp ơn tri ngộ của Tiêu Khinh Tuyết, đã trải qua bao trắc trở, bị cuốn vào những cuộc tranh đấu khốc liệt, cuối cùng danh chấn Thương Lam, đứng trên vạn người.</p>', 'Tập 180', 240, 'hoathinh', 'ongoing', 45, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Thần Thoại","slug":"than-thoai","id":"2276b29204c46f75064735477890afd6"}]', '[]', 1784690324174);
