INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-chien-mafia', 'Cuộc Chiến Mafia', 'Mafia Wars', 'https://phimimg.com/upload/vod/20260602-1/62afb0f731584ef8d4b90767ae91c640.jpg', 'https://phimimg.com/upload/vod/20260602-1/c95f23aba9b89c25cfdefac7bd440704.jpg', '<p>&quot;Mafia Wars&quot; (2024) kể về Terry Jacobs (do Tom Welling thủ vai), một cựu tù nhân được thả sớm với điều kiện anh phải tham gia vào một đơn vị cảnh sát chìm gồm sáu người, nhằm điều tra một trùm ma túy khét tiếng người Ý. Tuy nhiên, ngay trong ngày đầu tiên, năm thành viên khác của đơn vị bị giết hại, khiến Terry phải đối mặt trực tiếp với những tên mafia mà anh được giao nhiệm vụ theo dõi, mà không biết liệu chúng có nhận ra danh tính thực sự của anh hay không.</p>', 'Full', 1, 'single', 'completed', 21, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tom Welling","avatar":""},{"name":"Cam Gigandet","avatar":""},{"name":"Cher Cosenza","avatar":""},{"name":"Chris Mullinax","avatar":""},{"name":"Alessia Alciati","avatar":""},{"name":"Davide Cincis","avatar":""},{"name":"Al Linea","avatar":""},{"name":"Sidhartha Mallya","avatar":""},{"name":"Sterling Griffin","avatar":""},{"name":"Desiree Hall","avatar":""},{"name":"Luca Malacrino","avatar":""},{"name":"Ludovica Frasca","avatar":""},{"name":"Brice Martinet","avatar":""},{"name":"Anis Gharbi","avatar":""},{"name":"Sherrod Taylor","avatar":""},{"name":"Jeffrey Dean Morgan","avatar":""},{"name":"Marco G","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Deep Six","Six Undercover (Mafia Wars)","جنگ‌های مافیا","Mafia Wars"]', 1784690324174);
