INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gau-boonie-biet-doi-thu-nho-phan-1', 'Gấu Boonie: Biệt Đội Thu Nhỏ (Phần 1)', 'Boonie Bears: Shrunk (Season 1)', 'https://phimimg.com/upload/vod/20260429-1/15731c36caaaffebc6329aa3bebcc004.jpg', 'https://phimimg.com/upload/vod/20260429-1/a3b7919c55a0f99f985fc00d4084ae5d.jpg', '<p>Cả thế giới bỗng chốc trở nên khổng lồ sau khi tiều phu Vick vô tình khiến chiếc máy thu nhỏ kỳ bí gặp sự cố, biến bản thân và cả anh em gấu Boonie thành những sinh vật tí hon. Giờ đây, khu rừng quen thuộc đã trở thành một vùng đất đầy rẫy hiểm nguy, ẩn chứa những chướng ngại không thể lường trước. Trong cuộc chạy đua với thời gian nhằm tìm lại chiếc máy và trở về kích thước cũ, bộ ba &quot;oan gia&quot; này phải học cách gạt bỏ hiềm khích để cùng nhau sống sót giữa một thế giới mà chỉ một giọt sương cũng có thể trở thành thảm họa</p>', 'Hoàn Tất (52/52)', 52, 'hoathinh', 'completed', 46, 2024, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Wei","avatar":""},{"name":"Zhang Bingjun","avatar":""},{"name":"Tan Xiao","avatar":""},{"name":"贾晨露","avatar":""},{"name":"周子瑜","avatar":""}]', '[{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["熊出没之小小世界","Boonie Bears: Shrunk","熊出没之小小世界第二季","Boonie Bears：Shrunk 2","Отважные Мишки. Новые приключения"]', 1784690324174);
