INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-la-mu-quang-anh-phan-1', 'Yêu Là Mù Quáng: Anh (Phần 1)', 'Love Is Blind: UK (Season 1)', 'https://phimimg.com/upload/vod/20260525-1/2c2c2b2e16e6c7bc526be40d7d0e8e1a.jpg', 'https://phimimg.com/upload/vod/20260525-1/50bfebd98e0c289b92a1fee07ccd210e.jpg', '<p>Emma và Matt Willis cùng dẫn dắt một thử nghiệm xã hội đầy thú vị, nơi những người độc thân Anh Quốc tìm kiếm tình yêu đích thực và quyết định đính hôn ngay cả trước khi nhìn thấy mặt nhau ngoài đời. Liệu ai sẽ là người sẵn sàng bước vào lễ đường và nói lời &quot;Thề nguyện&quot;?</p>', 'Hoàn Tất (12/12)', 12, 'tvshows', 'completed', 34, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Emma Willis","avatar":""},{"name":"Matt Willis","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Love Is Blind: UK"]', 1784690324174);
