INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-sinh-tan-sinh', 'Tái Sinh (Tân Sinh)', 'Regeneration', 'https://phimimg.com/upload/vod/20260524-1/e2e8094171d11e537368f678c332158f.jpg', 'https://phimimg.com/upload/vod/20260524-1/442a632d127780c9c2aecd865a450d2d.jpg', '<p>Sau cái chết bí ẩn của Phí Khả, một nữ phóng viên cùng nhiều người từng quen biết anh được mời tới dự lễ tưởng niệm. Qua lời kể của từng người, họ dần phát hiện mỗi người lại biết một “Phí Khả” hoàn toàn khác nhau, kéo theo hàng loạt bí mật và sự thật gây chấn động...</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 22, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tỉnh Bách Nhiên","avatar":""},{"name":"Châu Y Nhiên","avatar":""},{"name":"Vương Nghiễn Huy","avatar":""},{"name":"Hoàng Giác","avatar":""},{"name":"Trương Nghệ Phàm","avatar":""},{"name":"Bành Dương","avatar":""},{"name":"Liêu Phàm","avatar":""},{"name":"Trần Vũ Hiền","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["新生","费可的晚宴","新生2","新生 第二季","بازآفرینی","Regeneration","Regeneration 2"]', 1784690324174);
