INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-tri-tu-than', 'Tiên Tri Tử Thần', 'You Will Die In 6 Hours', 'https://phimimg.com/upload/vod/20250226-1/1125e0b8a8f1d66744bdc1019f2f0e3e.jpg', 'https://phimimg.com/upload/vod/20260524-1/ce4cb2ee8e2161c773a1e311bd9000dd.jpg', '<p>Một kẻ lạ mặt Jun-woo (JaeHyun NCT) dự báo cái chết sẽ đến với Jeong-yun (PARK Ju-hyun) trong 6 tiếng sắp tới. Từ phớt lờ, đến hoang mang, và nhận ra hiểm họa gần kề, cô buộc phải đồng hành cùng kẻ tiên tri bí ẩn. Càng cố tìm hiểu cô lại nhận ra Jun-woo chính là manh mối duy nhất liên quan đến những vụ án sát nhân hàng loạt. Căng thẳng tột độ, liệu Jun-woo đã nhìn thấy tương lai hay chỉ đang giăng bẫy một nạn nhân xấu số?</p>', 'Full', 1, 'single', 'completed', 19, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"Jaehyun","avatar":""},{"name":"Park Ju-hyun","avatar":""},{"name":"Kwak Si-yang","avatar":""},{"name":"Lee Soo-jung","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["六小时后你将死去","You Will Die In 6 Hours","Morirás en 6 horas","6시간 후 너는 죽는다"]', 1784690324174);
