INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-dong-the', 'Kẻ Đóng Thế', 'Stuntman', 'https://phimimg.com/upload/vod/20250808-1/40cc095d30d3b0c9962e664c66f6fae6.jpg', 'https://phimimg.com/upload/vod/20250808-1/87c73a000fa3493968c26b76a73b2038.jpg', '<p>Một đạo diễn đóng thế hết thời đang vật lộn để tìm lối đi trong ngành công nghiệp điện ảnh nhiều biến động. Ông đánh cược tất cả để tạo nên màn tái xuất cuối cùng, đồng thời cố gắng hàn gắn mối quan hệ với cô con gái xa cách của mình.</p>', 'Full', 1, 'single', 'completed', 26, 2024, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Terrance Lau Chun-Him","avatar":""},{"name":"Stephen Tung","avatar":""},{"name":"Cecilia Choi","avatar":""},{"name":"Philip Ng Wan-Lung","avatar":""},{"name":"Max Cheung Tat-Lun","avatar":""},{"name":"To Yin-Gor","avatar":""},{"name":"Lam Yiu-Sing","avatar":""},{"name":"Rachel Leung","avatar":""},{"name":"Terry Zou Wen-Zheng","avatar":""},{"name":"Stephanie Che Yuen-Yuen","avatar":""},{"name":"Keith Ng Shui-Ting","avatar":""},{"name":"Honey Ho","avatar":""},{"name":"Tse Sze-Wing","avatar":""},{"name":"Wong Sze-Yan","avatar":""},{"name":"Kanice Lau Ka-Ki","avatar":""},{"name":"Sa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Stuntman","スタントマン","武替道"]', 1784690324174);
