INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-tu-bao', 'Biệt Đội Tứ Bảo', 'The Four Misfits', 'https://phimimg.com/upload/vod/20260519-1/4ad7149c61c553451532d499d056c8dc.jpg', 'https://phimimg.com/upload/vod/20260519-1/c3b8faa55bced26dac9ccb730b846aa0.jpg', '<p>Thẩm Thanh Nhan bị ép gánh tội thay cho em gái Thẩm Hoan. Trên đường chạy trốn, cô vô tình gặp Mặc Thời Quân đang bị bỏ thuốc. Mười tháng sau, cô sinh tư nhưng bị Thẩm Hoan vu oan giết con, khiến cô phải ngồi tù năm năm. Ra tù, Thanh Nhan suýt bị bán vào hộp đêm nhưng được chính các con tìm đến cứu. Cuối cùng mọi bí mật được phơi bày, tất cả đều chứng minh Thanh Nhan mới là người Mặc Thời Quân từng cứu và yêu.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 21, 2024, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324174);
