INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('beetlejuice-ma-sieu-quay', 'Beetlejuice: Ma Siêu Quậy', 'Beetlejuice Beetlejuice', 'https://phimimg.com/upload/vod/20260519-1/c1781f1908ab93d6848b87a9cd5bee87.jpg', 'https://phimimg.com/upload/vod/20260519-1/216dcacafc61f9c8294a79530ca58790.jpg', '<p>Beetlejuice trở lại! Sau một bi kịch gia đình bất ngờ, ba thế hệ gia đình Deetz trở về nhà ở Winter River. Vẫn bị Beetlejuice ám ảnh, cuộc sống của Lydia bị đảo lộn khi cô con gái tuổi teen nổi loạn của cô, Astrid, phát hiện mô hình bí ẩn của thị trấn trong gác mái và cổng đến Thế giới bên kia vô tình được mở ra. Khi rắc rối đang diễn ra ở cả hai thế giới, chỉ còn là vấn đề thời gian trước khi ai đó nói tên Beetlejuice ba lần và con quỷ nghịch ngợm trở lại để gây ra sự hỗn loạn của riêng mình.</p>', 'Full', 1, 'single', 'completed', 18, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Michael Keaton","avatar":""},{"name":"Winona Ryder","avatar":""},{"name":"Catherine O''Hara","avatar":""},{"name":"Jenna Ortega","avatar":""},{"name":"Justin Theroux","avatar":""},{"name":"Willem Dafoe","avatar":""},{"name":"Monica Bellucci","avatar":""},{"name":"Arthur Conti","avatar":""},{"name":"Nick Kellington","avatar":""},{"name":"Santiago Cabrera","avatar":""},{"name":"Burn Gorman","avatar":""},{"name":"Danny DeVito","avatar":""},{"name":"Sami Slimane","avatar":""},{"name":"Amy Nuttall","avatar":""},{"name":"Mark Heenehan","avatar":""},{"name":"Charlie Hopkinson","avatar":""},{"name":"Liv","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Beetlejuice 2","비틀쥬스 2","Beetlejuice Beetlejuice 2024 A.D.","Битлджус 2","Beterböcek Beterböcek","ביטלג''וס 2","Os Fantasmas Ainda se Divertem: Beetlejuice Beetlejuice 2024 P.M.","BeetleJuice BeetleJuice","Beterböcek Beterböcek 2024 Ö.S.","阴间大法师2","Bitlcus Bitlcus","Bitlcus 2","Bételgeuse Bételgeuse","Os Fantasmas Divertem-se 2","Os Fantasmas Divertem-se Ainda","Os Fantasmas Ainda Divertem-se","Beetlejuice 2.","哗鬼家族2","陰間大法師 BEETLEJUICE","Beetlejuice Beetlejuice"]', 1784690324174);
