INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('linh-muc-nhiet-huyet-phan-2', 'Linh Mục Nhiệt Huyết (Phần 2)', 'The Fiery Priest (Season 2)', 'https://phimimg.com/upload/vod/20250109-1/b5161dbe68915ec7998d567fb8ae1c21.jpg', 'https://phimimg.com/upload/vod/20250109-1/8791faa09ddc1310d783dc3e60a8ef5b.jpg', '<p><span style="text-wrap-mode: wrap;">Kim Hae-Il là một linh mục Công giáo. Anh ta đưa ra những nhận xét cay nghiệt và anh ta đối xử thô lỗ với người khác. Koo Dae-Young là một thám tử. Anh ta nói rất nhiều nhưng cũng rất rụt rè. Park Kyung-Sun là một công tố viên. Cô ấy thông minh và xinh đẹp. Cô ấy luôn có tham vọng là một công tố viên và luôn hoàn thành tốt công việc của mình. Linh mục Công giáo Kim Hae-Il, Thám tử Koo Dae-Young và Công tố viên Park Kyung-Sun làm việc cùng nhau để giải quyết một vụ án giết người liên quan đến một linh mục Công giáo cao cấp.</span><span style="text-wrap-mode: wrap;"></span></p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 29, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Nam Gil","avatar":""},{"name":"Kim Sung-kyun","avatar":""},{"name":"Lý Hàn Nhi","avatar":""},{"name":"Ko Jun","avatar":""},{"name":"Keum Sae-rok","avatar":""},{"name":"Sung Joon","avatar":""},{"name":"Seo Hyun Woo","avatar":""},{"name":"Kim Hyeong-seo","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Кибритлия в расо","열혈사제 2","الكاهن الناري","The Fiery Priest","열혈사제"]', 1784690324174);
