INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoac-phu-nhan-ra-tay', 'Hoắc Phu Nhân Ra Tay', 'When the Lady Takes Action', 'https://phimimg.com/upload/vod/20260518-1/66e3db042a67e312f024eb5cbfba64da.jpg', 'https://phimimg.com/upload/vod/20260518-1/bad0a0fcdb6f063e76b35da011be8e1f.jpg', '<p>Cố Vãn Đường vì muốn báo ơn mà kết hôn với Lục Thịnh. Thế nhưng trong buổi họp báo của công ty, cô phát hiện anh ta đang lén lút ngoại tình với bạn thân mình. Tới nơi bắt gian, cô vô tình ngã vào vòng tay của tổng tài Hoắc Vân Thâm. Sau ly hôn, Cố Vãn Đường sát cánh cùng Hoắc Vân Thâm trên thương trường, và cũng từ đó mà cô dần nhận ra tình cảm thật sự của mình.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 21, 2024, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324174);
