INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mau-nong-va-con-thinh-no-bung-no', 'Máu Nóng Và Cơn Thịnh Nộ Bùng Nổ', 'Hot Blood & Outburst Of Rage', 'https://phimimg.com/upload/vod/20260518-1/7cc28ea58e4b9c9b83abd4a04fad62e8.jpg', 'https://phimimg.com/upload/vod/20260518-1/43db9809b8dabf6527c06df064be0153.jpg', '<p>Liao và Bruce sắp tốt nghiệp đại học, Liao cũng đang phải đối mặt với kỳ thi nghĩa vụ quân sự sắp tới. Kỳ thi khiến Liao lo lắng, không chỉ về việc nhập ngũ mà còn về chính bản thân mình. Một đêm nọ, Bruce đi cùng Liao và cuối cùng bị cuốn vào cuộc đấu tranh cảm xúc. Đâu là ranh giới giữa tình bạn và đam mê giữa hai người?</p>', 'Full', 1, 'single', 'completed', 34, 2024, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"廖子嘉","avatar":""},{"name":"江冠勳","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["熱血"]', 1784690324174);
