INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuc-ngu-ngon-ban-dong-hanh', 'Chúc Ngủ Ngon. Bạn đồng Hành.', 'Good Night. Partner.', 'https://phimimg.com/upload/vod/20260518-1/667f4cf03a520820109114977b9c1699.jpg', 'https://phimimg.com/upload/vod/20260518-1/037a96c696115f28ca3a778c41eef367.jpg', '<p>Anh chàng lực lưỡng Lâm Trường Đằng thầm yêu cô bạn cùng phòng dị tính Dương Trí Gia, nhưng anh không bao giờ dám thổ lộ tình cảm. Đúng lúc anh sắp chạm đến giới hạn chịu đựng, Trí Gia nói với anh rằng anh sắp kết hôn và mời anh làm chứng. Đối mặt với một mối quan hệ bi đát chưa từng bắt đầu, Trường Đằng phải đối mặt với viễn cảnh thực sự phải ngủ một mình.</p>', 'Full', 1, 'single', 'completed', 31, 2024, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Duncan Ku","avatar":""},{"name":"Jeff Kuo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["你要練習自己一個人睡"]', 1784690324174);
