INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhip-dap-tinh-yeu', 'Nhịp Đập Tình Yêu', 'MBTI Love', 'https://phimimg.com/upload/vod/20250411-1/0a1d99c6d0072e1b2b86531b94acb953.jpg', 'https://phimimg.com/upload/vod/20250411-1/fbf08329fce6d57be38c89de706bef68.jpg', '<p>Cuộc sống của Ôn Mạn đảo lộn khi bạn trai cũ không những phản bội mà còn vu khống bố cô tội tham ô. Trớ trêu thay, luật sư duy nhất đồng ý tiếp nhận vụ án của bố cô lại chính là Hoắc Thiệu Đình, anh trai của bạn gái mới của gã người yêu cũ tệ bạc kia. Vốn luôn tự tin rằng mình có thể đánh giá chính xác nhóm tính cách MBTI của bất kì ai, Ôn Mạn lại hoàn toàn bối rối trước Thiệu Đình. Liệu anh có thể giúp cô chữa lành vết thương lòng và tìm lại hạnh phúc hay không?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 25, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tiêu Tường Ân","avatar":""},{"name":"Lôi Tiếu Ngữ","avatar":""},{"name":"Tạ An Nhiên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["霍先生乖乖宠我","真愛節拍","Zhen Ai Jie Pai","Huo Xian Sheng Guai Guai Chong Wo","Любовь по MBTI","MBTI Love","真爱节拍"]', 1784690324174);
