INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghich-thien-than-y', 'Nghịch Thiên Thần Y', 'Heaven-Defying Divine Doctor', 'https://phimimg.com/upload/vod/20260514-1/3158d27a4ec0fafbaf58a4ed4cc6bfc6.jpg', 'https://phimimg.com/upload/vod/20260514-1/717189a382a7dfa0dbddfb9ee1421b16.jpg', '<p>Để cứu sống ông nội, Trình Bách Linh chấp nhận trở thành vị hôn thê của thần y Trác Nhất Thần. Không ngờ, sau khi ra tay đưa ông Trình trở về từ cửa tử, Trác Nhất Thần lại vô tình đắc tội với bác sĩ riêng của Trình gia. Kể từ đó, anh bị cuốn vào hàng loạt âm mưu thâm độc và phải đối mặt với vô vàn hiểm nguy.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 15, 2024, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324174);
