INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-yeu-dau', 'Bạn Yêu Dấu', 'Sweethearts', 'https://phimimg.com/upload/vod/20260512-1/77dd91ba67e97ecffaa38cb338263ed9.jpg', 'https://phimimg.com/upload/vod/20260512-1/52d0ff7618db9e191bb8fd2e0381ec10.jpg', '<p>Hai sinh viên năm nhất đại học quyết định gắn bó với mối tình thời trung học của mình phải thực hiện một cuộc đổ gà tây và chia tay họ trong Lễ Tạ ơn vào một đêm hỗn loạn trước Lễ Tạ ơn tại quê nhà, đặt tình bạn phụ thuộc lẫn nhau của họ vào thử thách.</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kiernan Shipka","avatar":""},{"name":"Nico Hiraga","avatar":""},{"name":"Caleb Hearon","avatar":""},{"name":"Ava DeMary","avatar":""},{"name":"Charlie Hall","avatar":""},{"name":"Tramell Tillman","avatar":""},{"name":"Joel Kim Booster","avatar":""},{"name":"Miles Gutierrez-Riley","avatar":""},{"name":"Zach Zucker","avatar":""},{"name":"Christine Taylor","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Возлюбленные","Sevgililər","再见甜心","甜心","Sweethearts"]', 1784690324174);
