INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-sinh', 'Song Sinh', 'The Image Of You', 'https://phimimg.com/upload/vod/20260512-1/2444e593a52ac009b84aa23c7a6c6eaf.jpg', 'https://phimimg.com/upload/vod/20260512-1/aa2f67746243c2cc574475a06b13b8b5.jpg', '<p>Cặp song sinh Anna và Zoe thấy mối quan hệ của họ bị thử thách vì tình yêu mới của Anna, Nick. Trong khi Anna, người luôn tin tưởng, đang say đắm trong tình yêu, thì cô em gái đa nghi Zoe lại cảm nhận được một mạng lưới lừa dối. Nhưng khi Zoe tìm kiếm sự thật, tất cả họ bị cuốn vào một trò chơi nguy hiểm, nơi sự trung thực có thể trở thành thảm họa.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sasha Pieterse","avatar":""},{"name":"Parker Young","avatar":""},{"name":"Mira Sorvino","avatar":""},{"name":"Nestor Carbonell","avatar":""},{"name":"Michele Nordin","avatar":""},{"name":"Rebekah Graf","avatar":""},{"name":"Ben Milliken","avatar":""},{"name":"Ogy Durham","avatar":""},{"name":"Kate Rachesky","avatar":""},{"name":"Anne Sward","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["隐秘的自我","一模一样","姐妹如一","The Image of You"]', 1784690324174);
