INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bong-toi-cua-chi-huy', 'Bóng Tối Của Chỉ Huy', 'The Commandant''s Shadow', 'https://phimimg.com/upload/vod/20260512-1/c7186d7320b24143df16412628f947dd.jpg', 'https://phimimg.com/upload/vod/20260512-1/543e5c31093116635ba49c2e71440cd6.jpg', '<p>Trong khi Hans Jurgen Höss tận hưởng tuổi thơ hạnh phúc trong biệt thự gia đình tại Auschwitz, thì nữ tù nhân Do Thái Anita Lasker-Wallfisch đang cố gắng sống sót trong trại tập trung khét tiếng. Trọng tâm của bộ phim là khoảnh khắc lịch sử và đầy cảm hứng - tám thập kỷ sau - khi hai người đối mặt với nhau. Đây là lần đầu tiên hậu duệ của một tên tội phạm chiến tranh khét tiếng gặp gỡ một người sống sót trong một bối cảnh riêng tư và thân mật như vậy, phòng khách của Anita ở London. Cùng với các con, Kai Höss và Maya Lasker-Wallfisch, bốn nhân vật chính khám phá những gánh nặng di truyền rất khác biệt của họ.</p>', 'Full', 1, 'single', 'completed', 38, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Hans-Jürgen Höss","avatar":""},{"name":"Kai Höss","avatar":""},{"name":"Anita Lasker-Wallfisch","avatar":""},{"name":"Maya Lasker-Wallfisch","avatar":""},{"name":"Rudolf Höss","avatar":""},{"name":"Adolf Hitler","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["La sombra del comandante","The Commandant''s Shadow"]', 1784690324174);
