INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-dien-tu-bi-an-ve-bitcoin', 'Tiền Điện Tử: Bí Ẩn Về Bitcoin', 'Money Electric: The Bitcoin Mystery', 'https://phimimg.com/upload/vod/20260512-1/ec926b613d6b21f5888c9cb2de832626.jpg', 'https://phimimg.com/upload/vod/20260512-1/b2ffc8fb1fd73b3e19521373837e9c4f.jpg', '<p>Đi sâu vào một trong những bí ẩn lâu đời và có mức độ rủi ro cao nhất trong công nghệ và tài chính: nguồn gốc của Bitcoin và danh tính của người sáng tạo ẩn danh, Satoshi Nakamoto.</p>', 'Full', 1, 'single', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Roger Ver","avatar":""},{"name":"Peter Todd","avatar":""},{"name":"Adam Back","avatar":""},{"name":"Ricardo Salinas Pliego","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Moeda Digital: O Mistério do Bitcoin","币电奇缘：比特疑云","Dinero Digital: El Misterio del Bitcoin","虛擬貨幣 : 比特幣之謎","Money Electric: The Bitcoin Mystery"]', 1784690324174);
