INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-goi-anh-ta-la-gan-nhu-vo-hai', 'Họ Gọi Anh Ta Là Gần Như Vô Hại', 'They Called Him Mostly Harmless', 'https://phimimg.com/upload/vod/20260512-1/d0088318616d203f0d67586e3efe8a3f.jpg', 'https://phimimg.com/upload/vod/20260512-1/8be51a11f5abc0835af023479a014e63.jpg', '<p>Khi một người đi bộ đường dài không rõ danh tính được tìm thấy đã chết trong vùng hoang dã Florida, chính quyền đã công bố một bản phác thảo. Nhiều người đi bộ đường dài đã gọi điện đến và nói rằng đã gặp người đàn ông này. Chỉ có một vấn đề duy nhất - anh ta chưa bao giờ nói cho họ biết tên mình. Phải mất hai năm, hàng ngàn thám tử internet tận tụy, và một phép màu của khoa học để xác định danh tính của anh ta, và đó là lúc rắc rối thực sự bắt đầu.</p>', 'Full', 1, 'single', 'completed', 14, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["They Called Him Mostly Harmless"]', 1784690324174);
