INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-lai-voi-mau-den', 'Trở Lại Với Màu Đen', 'Back To Black', 'https://phimimg.com/upload/vod/20260509-1/21a8e476a68ebf883d24d0ec3a49fb5a.jpg', 'https://phimimg.com/upload/vod/20260509-1/317429c4db423da61fd1caa59c4e67f5.jpg', '<p>Câu chuyện phi thường về hành trình vươn tới đỉnh cao của Amy Winehouse, từ những ngày đầu ở Camden cho đến quá trình tạo nên album đột phá &quot;Back to Black&quot; – tác phẩm đã đưa cô trở thành ngôi sao toàn cầu. Được kể qua lăng kính của chính Amy và lấy cảm hứng từ những lời ca đậm chất riêng tư, bộ phim khám phá và tôn vinh những góc cạnh đa dạng của người nghệ sĩ biểu tượng, đồng thời khắc họa mối tình đầy giông bão là nguồn cơn cho một trong những album huyền thoại nhất mọi thời đại.</p>', 'Full', 1, 'single', 'completed', 43, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Marisa Abela","avatar":""},{"name":"Jack O''Connell","avatar":""},{"name":"Eddie Marsan","avatar":""},{"name":"Lesley Manville","avatar":""},{"name":"Juliet Cowan","avatar":""},{"name":"Sam Buchanan","avatar":""},{"name":"Pete Lee-Wilson","avatar":""},{"name":"Thelma Ruby","avatar":""},{"name":"Michael S. Siegel","avatar":""},{"name":"Matilda Thorpe","avatar":""},{"name":"Anna Darvas","avatar":""},{"name":"Tracey Lushington","avatar":""},{"name":"Ryan O''Doherty","avatar":""},{"name":"Spike Fearn","avatar":""},{"name":"Harley Bird","avatar":""},{"name":"Francesca Henry","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Емі Вайнгауз