INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pha-dia-nguc', 'Phá Địa Ngục', 'The Last Dance', 'https://phimimg.com/upload/vod/20250408-1/fe62f1802910262276fa83e230b66be4.jpg', 'https://phimimg.com/upload/vod/20250408-1/9cfc6cd5d8ee5fc397f16f170382e06f.jpg', '<p>Phá ngục cứu vong - một nghi thức đậm màu truyền thống nhưng cũng đầy tính tâm linh huyền bí. Theo niềm tin Đạo giáo, điệu múa “Phá địa ngục” sẽ giúp người quá cố thoát khỏi địa ngục và siêu thoát đến miền cực lạc. Với nội dung vừa gây tò mò, vừa đậm màu sắc văn hóa Á Đông, “Phá Địa Ngục” được khán giả cũng như giới phê bình đón nhận nhiệt liệt, trở thành phim nội địa ăn khách nhất mọi thời đại tại Hong Kong. Những thông điệp vừa gần gũi vừa mang tính triết lý về đời sống và kiếp người sẽ được kể một cách khéo léo qua chuyện đời và nghiệp của sư phụ Văn (Hứa Quán Văn thủ vai - ảnh đế đầu tiên giải Kim Tượng) cùng Đạo Sinh (Huỳnh Tử Hoa thủ vai).</p>', 'Full', 1, 'single', 'completed', 14, 2024, 'Vietsub', 'FHD', 'Hồng Kông', 1, '[{"name":"Michael Hui Koon-Man","avatar":""},{"name":"Dayo Wong","avatar":""},{"name":"Michelle Wai Si-Nga","avatar":""},{"name":"Tommy Chu Pak-Hong","avatar":""},{"name":"Catherine Chau","avatar":""},{"name":"Paul Chun Pui","avatar":""},{"name":"Elaine Jin Yan-Ling","avatar":""},{"name":"Rosa Maria Velasco","avatar":""},{"name":"Rachel Leung","avatar":""},{"name":"Michael Ning","avatar":""},{"name":"Chung Suet-Ying","avatar":""},{"name":"Edward Ma","avatar":""},{"name":"Elly Lam","avatar":""},{"name":"Polly Lau","avatar":""},{"name":"Thor Lok","avatar":""},{"name":"Kiki Cheung Hoi-Kei","avatar":""},{"name":"K","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c