INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cau-hanh-phuc-den-the-gian', 'Cầu Hạnh Phúc Đến Thế Gian', 'Best Wishes to All', 'https://phimimg.com/upload/vod/20260502-1/0bbe01ca2673b7e98606cf638d4cfb4a.jpg', 'https://phimimg.com/upload/vod/20260502-1/5f1b753209af5d256b7db1d85d74c93f.jpg', '<p>Best Wishes to All là một bộ phim kinh dị của đạo diễn Yuto Shimotsu được phát triển từ bộ phim ngắn cùng tên vào năm 2021. Bộ phim kể về chuyến về miền quê thăm ông bà nội của cô gái học ngành điều dưỡng. Thoạt đầu, chuyến về thăm quê diễn ra êm đềm và vui vẻ khi cô dành thời gian ở cùng với người ông người bà yêu dấu của mình. Nhưng dưới bầu không khí hạnh phúc đó ẩn giấu một bí mật kinh hãi, một bầu không khí rùng rợn len lỏi trong từng ngóc ngách nơi miền quê thanh bình này.</p>', 'Full', 1, 'single', 'ongoing', 9, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kotone Furukawa","avatar":""},{"name":"Koya Matsudai","avatar":""},{"name":"Masashi Arifuku","avatar":""},{"name":"Yoshiko Inuyama","avatar":""},{"name":"Kazuo Hashimoto","avatar":""},{"name":"Shiho Yoshimura","avatar":""},{"name":"Hirofumi Nishida","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Meus Melhores Desejos a Todos","Happiness to All","Best Regards to All","みなに幸あれ"]', 1784690324175);
