INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuc-cung', 'Cục cưng', 'Babes', 'https://phimimg.com/upload/vod/20260502-1/2b685e42bd1c1e8d3128221a786459ef.jpg', 'https://phimimg.com/upload/vod/20260502-1/91a88f6717716d1384c59ea56728bc02.jpg', '<p>Khi cô nàng vô tư Eden bất ngờ mang thai sau tình một đêm, cô trông cậy bạn thân Dawn để giúp mình xoay xở với mớ hỗn độn của việc làm mẹ thời hiện đại.</p>', 'Full', 1, 'single', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ilana Glazer","avatar":""},{"name":"Michelle Buteau","avatar":""},{"name":"John Carroll Lynch","avatar":""},{"name":"Oliver Platt","avatar":""},{"name":"Sandra Bernhard","avatar":""},{"name":"Stephan James","avatar":""},{"name":"Hasan Minhaj","avatar":""},{"name":"Keith Lucas","avatar":""},{"name":"Kenneth Lucas","avatar":""},{"name":"Caleb Mermelstein-Knox","avatar":""},{"name":"Elena Ouspenskaia","avatar":""},{"name":"Josh Rabinowitz","avatar":""},{"name":"Mario Polit","avatar":""},{"name":"Julia Scotti","avatar":""},{"name":"Crystal Finn","avatar":""},{"name":"Donna Glaesener","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Круті дівчата","Peques","Guia Para Ser Mamá","내 절친의 임신","Babes"]', 1784690324175);
