INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xa-dao-nhan', 'Xa Đao Nhân', 'Credit Knife People', 'https://phimimg.com/upload/vod/20240902-1/e81136564ff06b044358ea39bd2c38f2.jpg', 'https://phimimg.com/upload/vod/20240902-1/11b6cce573163ddb46cadd69faf49db7.jpg', '<p>Trên giang hồ luôn lưu truyền truyền thuyết về người bán dao nợ, tương truyền rằng người này đã rèn ra một thanh thần binh bất khả chiến bại là kiếm Trạm Lư, và sẽ cho người có duyên mà mình gặp mượn thanh kiếm này... Hai mươi ba năm trước, người bán dao nợ đã cho một thanh niên trong tình cảnh tuyệt vọng mượn kiếm Trạm Lư. Thanh niên đó đã dựa vào thanh kiếm này để trở thành &quot;Kiếm Cuồng&quot; khiến giang hồ khiếp sợ. Ba năm sau, người bán dao nợ xuất hiện trở lại, muốn lấy lại kiếm Trạm Lư, nhưng Kiếm Cuồng vì mê đắm kiếm Trạm Lư mà nhập ma, hủy bỏ lời hứa ban đầu. Thế là người bán dao nợ để lại một lời tiên tri: Kiếm Trạm Lư sẽ giết chết người mà Kiếm Cuồng yêu thương nhất. Cuối cùng, điều đó đã dẫn đến việc hắn thê vong tử tán, rồi Kiếm Cuồng tỉnh ngộ, mai danh ẩn tích, sống mờ mịt suốt hai mươi năm. Cho đến khi anh ta gặp được Hạ Hầu Linh, cô gái như một luồng ánh sáng ấm áp chiếu sáng trái tim đã nguội lạnh của Kiếm Cuồng. Khi Hạ Hầu Linh đối mặt với nguy hiểm sinh tử, anh ta cuối cùng đã dũng cảm cầm lại thanh kiếm Trạm Lư. Kiếm Cuồng tái xuất giang hồ, và lời tiên tri của người bán dao nợ vẫn sẽ ứng nghiệm, bánh xe định mệnh lại một lần nữa quay, Kiếm Cuồng sẽ lại phải đưa ra lựa chọn...</p>', 'Full', 1, 'single', 'completed', 12, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Wu Di-wen","avatar":""},{"name":"Morning Chang","avatar":""},{"name":"Li Xiaomeng","avatar":""},{"name":"李子雄","avatar":""},{"name":"Gabriel Wong","avatar":""},{"name":"张卫","avatar":""},{"name":"Tong Xi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["She Dao Ren","اعتبار شمشیر مردم","赊刀人"]', 1784690324175);
