INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-xuan-dao-3-vo-gian-luyen-nguc', 'Tú Xuân Đao 3: Vô Gian Luyện Ngục', 'Brotherhood of Blades III', 'https://phimimg.com/upload/vod/20240504-1/0c16a9f8a35b02fb29bf2a51d788eda6.jpg', 'https://phimimg.com/upload/vod/20240504-1/d494f30a19350c676474ea1d22ce5c55.jpg', '<p>Trong thời kỳ Thiên Khải của triều Minh, phe cánh tả đảng chiếm lĩnh triều đại, cường đạo giang hồ hoành hành. Thiếu niên giặc cỏ Quý Hiển, bất ngờ mạo danh thân phận Cẩm Y Vệ, nhưng lại bị cuốn vào âm mưu lật đổ vương triều. Trước nguy cơ sống chết đang đến gần, với sự đối lập giữa xuất thân và bản tâm, thà liều chết chiến đấu còn hơn sống trong thời loạn để thay đổi cách sống!</p>', 'Full', 1, 'single', 'completed', 31, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Leon Lee","avatar":""},{"name":"Yang Yi","avatar":""},{"name":"Yuen Cheung-Yan","avatar":""},{"name":"Zu Ka Er","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f80eb493b08d175c7a0c29687cbdf"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["The Embroidered Sword: Infinite Purgatory","Brotherhood of Blades","The Embroidered Sword","绣春刀：无间炼狱","xiu chun dao: wu jian lian yu"]', 1784690324175);
