INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khach-san-tan-long-mon', 'Khách Sạn Tân Long Môn', 'New Dragon Gate Inn', 'https://phimimg.com/upload/vod/20240425-1/0d6cb0158bcef0a1a0725467b475e0ce.jpg', 'https://phimimg.com/upload/vod/20240425-1/eb3c5f2f3dd01f94d267e62c9c77e6be.jpg', '<p>Vào năm Vạn Lịch nhà Minh, giặc Oa kết hợp với gián điệp trong triều hãm hại cả gia đình Binh bộ Thượng thư Khưu đại nhân, duy nhất cô con gái nhỏ Khưu Mạc Ngôn được hiệp khách giang hồ Chu Hoài An giải cứu. Trước khi chết, Khưu đại nhân giao lại bản đồ phòng thủ bờ biển của nhà Minh cho con gái, hy vọng đợi đến Tết Thanh Minh đem kế hoạch phòng thủ liên quan đến an nguy của nhà Minh này giao cho người có thể gánh vác trách nhiệm quan trọng. Để có được kế hoạch phòng thủ, giặc Oa đã truy sát hai người Chu Hoài An và Khưu Mạc Ngôn trong giang hồ, triều đình cũng liệt hai người này vào danh sách tội phạm chữ Thiên số một. Vì bản đồ phòng thủ và an nguy của hậu nhân nhà họ Khưu, Chu Hoài An đã tìm được bà chủ quán trọ Long Môn là Kim Tương Ngọc giúp đỡ, Kim Tương Ngọc vì tình cảm chân thành đã giấu bản đồ phòng thủ trong nhà trọ, sửa quán trọ thành một chiếc thuyền rồng giấu ngoài giang hồ, bảo vệ tốt bản đồ phòng thủ trước khi thời cơ thích hợp đến. Không ngờ Khưu Mạc Ngôn vô tình rơi vào tay bọn giặc Oa. Đồng thời triều đình cũng cử cao thủ phá án Từ Nghi lên tàu để bắt giữ Chu Hoài An và Khưu Mạc Ngôn, mấy thế lực đã phát động một cuộc chiến quyết tử trên con tàu rồng kỳ lạ này vì mục đích riêng của họ.</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lou Yixiao","avatar":""},{"name":"Liang Sen","avatar":""},{"name":"Julian Chen","avatar":""},{"name":"Chunqing Awei","avatar":""},{"name":"位林峰","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324175);
