INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-giang-ho-bat-luong-soai', 'Họa Giang Hồ: Bất Lương Soái', 'The Story of Yuan Tiangang', 'https://phimimg.com/upload/vod/20240303-1/276dd2f6d942e4c8d3e28e0a4d2c48a7.jpg', 'https://phimimg.com/upload/vod/20240303-1/3f0ad5593121872a1d337b30afe8f59a.jpg', '<p>Ba trăm năm trước, Thiếu niên xuất sắc Viên Thiên Cương, do số mệnh tự nhiên bị bỏ rơi, từ nhỏ đã giết chết những người thân xung quanh mình. Từ đó, anh quyết định sử dụng nghệ thuật chiêm tinh &quot;Châm Cốt Chiêm Mệnh&quot;, chuyên sát hại những người có số mệnh không nên chấm dứt. Lúc đó, là cuối thời kỳ nhà Tùy, khi đất nước hỗn loạn Viên Thiên Cương sẽ làm thế nào để thay đổi số phận và trở thành một tướng quân mà mọi người kính trọng?</p>', 'Full', 1, 'single', 'completed', 39, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Danny Chan Kwok-kwan","avatar":""},{"name":"Mao Xiaohui","avatar":""},{"name":"Hei Ze","avatar":""},{"name":"Kang Enhe","avatar":""},{"name":"Min Zheng","avatar":""},{"name":"赵广斌","avatar":""},{"name":"Qu Aohui","avatar":""},{"name":"冯俊杰","avatar":""},{"name":"姚清俊","avatar":""},{"name":"沈泰","avatar":""},{"name":"Lu Xin","avatar":""},{"name":"Chen Jiming","avatar":""},{"name":"Qishan Ye","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Giả Tượng","slug":"gia-tuong","id":"97e7ed4c52ce3737e18bdf0bd1331ce8"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '[]', 1784690324175);
