INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hoa-giang-ho-bat-luong-soai', 'Họa Giang Hồ: Bất Lương Soái', 'The Story of Yuan Tiangang', 'họa giang hồ: bất lương soái the story of yuan tiangang danny chan kwok-kwan mao xiaohui hei ze kang enhe min zheng 赵广斌 qu aohui 冯俊杰 姚清俊 沈泰 lu xin chen jiming qishan ye ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-nhan-kiet-thong-thien-huyen-an', 'Địch Nhân Kiệt: Thông Thiên Huyền Án', 'Detective Dee And The Phantom Of Waning Moon', 'https://phimimg.com/upload/vod/20240303-1/1765bed15cef3b9e41d9022c37405a05.jpg', 'https://phimimg.com/upload/vod/20240303-1/290e7f7a4e98f056d54d7b5e85870ea3.jpg', '<p>Vào thời nhà Đường, Công chúa Thái Bình có một &quot;giấc mơ về xứ sở thần tiên&quot;, trong đó Cô cưỡi &quot;ngựa bạch tuyết bạc&quot; phi nước đại dưới ánh trăng, nữ nhà giả kim Huyền Cơ đã giải thích giấc mơ của mình và con ngựa trắng được gọi là &quot;Pegasus&quot;, và biến giấc mơ của công chúa thành hiện thực. Huyễn Cơ được sủng ái. Lúc này, thám tử Địch Nhân Kiệt của nhà Đường đã phá được một “vụ án tiêu diệt gia đình”, nhưng hóa ra đó lại là một bi kịch cuộc đời do “Thiên Mã” gây ra.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Cao Dương","avatar":""},{"name":"Trịnh Hy Di","avatar":""},{"name":"Lương Duyên","avatar":""},{"name":"Vu Địch Văn","avatar":""},{"name":"Huệ Tường Ý","avatar":""},{"name":"Thẩm Tuyết Vĩ","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324175);
