INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuu-chau-long-quy', 'Cửu Châu Long Quý', 'Novoland', 'https://phimimg.com/upload/vod/20240524-1/1d07c60a91c39b8da6731d8baabefb71.jpg', 'https://phimimg.com/upload/vod/20240524-1/ee1e928086348fa84daca4c4c127849a.jpg', '<p>Trên lục địa Cửu châu, thanh niên thám tử Vân Trạm cùng sư phụ tham dự bữa tiệc và không may bị cuốn vào một vụ án li kì. Anh bị công chúa Thạch Thu Đồng và đội trưởng hộ vệ An Học Võ nhầm là nghi phạm phạm tội. Để chứng minh sự trong sạch, Vân Trạm cùng một số người khác cùng điều tra chân tướng. Cuối cùng, trong tình hình vụ án thay đổi liên tục, họ đã phơi bày một âm mưu lớn đằng sau...</p>', 'Full', 1, 'single', 'completed', 17, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Dực Tiêu","avatar":""},{"name":"Lâm Tử","avatar":""},{"name":"Ngô Húc Đông","avatar":""},{"name":"Hạ Gia Vĩ","avatar":""},{"name":"Bạch Dực Hoa","avatar":""},{"name":"Từ Thiếu Cường","avatar":""},{"name":"Lâu Học Hiền","avatar":""}]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324175);
