INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hinh-the-phan-3', 'Hình Thể (Phần 3)', 'Physical (Season 3)', 'https://phimimg.com/upload/vod/20260430-1/08ba6e0db76650704c6f0112287ff618.jpg', 'https://phimimg.com/upload/vod/20260430-1/1884bcabbe0c5646689877e5909971b8.jpg', '<p>Trong mùa thứ ba và mùa kết thúc, Sheila nhận thấy địa vị của mình bị thách thức bởi nữ thần tập thể dục nổi tiếng đang lên Kelly Kilmartin, người không chỉ trở thành mối đe dọa nghề nghiệp mà còn tìm cách xâm nhập vào đầu cô. Sheila sẽ thắng thế hay sự hiện diện của Kelly trong cuộc đời cô ấy sẽ làm suy yếu quá trình hàn gắn và ổn định khó kiếm được mà Sheila đã rất nỗ lực để có được?</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 12, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Rose Byrne","avatar":""},{"name":"Rory Scovel","avatar":""},{"name":"Dierdre Friel","avatar":""},{"name":"Paul Sparks","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["جسمانی","فیزیکی","Physical"]', 1784690324175);
