INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-so-toi-pham-phan-1', 'Hồ Sơ Tội Phạm (Phần 1)', 'Criminal Record (Season 1)', 'https://phimimg.com/upload/vod/20240418-1/d7cd84611f6429ce07a67df09e698cc3.jpg', 'https://phimimg.com/upload/vod/20240418-1/f39d93d9f1640a8248d26d89a23bac86.jpg', '<p>Ở trung tâm London, một cuộc điện thoại ẩn danh đã thu hút hai thanh tra tài giỏi — một phụ nữ trẻ đang ở giai đoạn đầu sự nghiệp và một người đàn ông có giao thiệp tốt quyết tâm bảo vệ di sản của mình — tham gia vào cuộc chiến sửa sai một vụ án oan cũ.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 20, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Peter Capaldi","avatar":""},{"name":"Cush Jumbo","avatar":""},{"name":"Shaun Dooley","avatar":""},{"name":"Zoë Wanamaker","avatar":""},{"name":"Charlie Creed-Miles","avatar":""},{"name":"Cathy Tyson","avatar":""},{"name":"Stephen Campbell Moore","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324175);
