INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-luat-su-lidia-pot-la-legge-di-lidia-pot-phan-2', 'Nữ Luật Sư Lidia Poët (La legge di Lidia Poët) (Phần 2)', 'The Law According To Lidia Poët (Season 2)', 'https://phimimg.com/upload/vod/20241101-1/fa6a8ef3bee1fa4e67b87db897ab912e.jpg', 'https://phimimg.com/upload/vod/20241101-1/7484e447dd154ce817e6dbc13e787806.jpg', '<p>Dựa trên chuyện có thật về nữ luật sư đầu tiên của Ý, bộ phim chính kịch lịch sử hấp dẫn này theo chân Lidia Poët khi cô điều tra các án mạng và đấu tranh để hành nghề luật.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 18, 2024, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Matilda De Angelis","avatar":""},{"name":"Sara Lazzaro","avatar":""},{"name":"Eduardo Scarpetta","avatar":""},{"name":"Pier Luigi Pasino","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["律政女杰莉迪亚","Lidia Poët","The Law According to Lidia Poet","La legge di Lidia Poët"]', 1784690324175);
