INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nu-luat-su-lidia-pot-la-legge-di-lidia-pot-phan-2', 'Nữ Luật Sư Lidia Poët (La legge di Lidia Poët) (Phần 2)', 'The Law According To Lidia Poët (Season 2)', 'nữ luật sư lidia poët (la legge di lidia poët) (phần 2) the law according to lidia poët (season 2) matilda de angelis sara lazzaro eduardo scarpetta pier luigi pasino 律政女杰莉迪亚 lidia poët the law according to lidia poet la legge di lidia poët', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vinh-an-mong', 'Vĩnh An Mộng', 'Yong An Dream', 'https://phimimg.com/upload/vod/20260415-1/8d809215ba6344e1234d14ad7527aae3.jpg', 'https://phimimg.com/upload/vod/20260415-1/9a5920c6fae1a2a2a60346b54b8b9a34.jpg', '<p>Tại kinh đô Vĩnh An, con kênh đào phía Tây thành bị sập khiến đô quan thượng thư Thẩm Văn Kỳ phụ trách công trình phải chịu tội sau một đêm, lâm vào cảnh lao tù. Tổ vỡ trứng cũng tan tành, hai cô con gái của Thẩm gia là Thẩm Nhiễm và Thẩm Chân cũng lần lượt sa lầy. Nhất là cô con gái út Thẩm Chân xưa nay được nuôi dưỡng nơi khuê các, không rành thế sự, giờ đây phải lang thang đầu đường, khó tự bảo vệ bản thân. Lúc này đình úy Lục Thời Nghiên phụ trách điều tra vụ án cũng bối rối vì thường xuyên mơ thấy mình và một nữ tử bí ẩn có quan hệ dây mơ rễ má. Sau khi xác minh, nữ tử bí ẩn xuất hiện trong mơ không ai khác chính là Thẩm Chân, con gái của tội thần. Lục Thời Nghiên từng bước tiếp cận cô, cũng từng bước đi về phía vận mệnh bí ẩn. Xoay quanh vụ án kênh đào phía Tây thành, cả hai cùng trải qua sinh tử, trao nhau lòng tin, cắm sâu rễ tình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 19, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Âu Dương Na Na","avatar":""},{"name":"Từ Chính Khê","avatar":""},{"name":"Tôn Kiên","avatar":""},{"name":"Hạ Nam","avatar":""},{"name":"Lưu Hải Khoan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yongan Dream","永安梦"]', 1784690324175);
