INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bi-kich-duoi-chan-cau', 'Bi Kịch Dưới Chân Cầu', 'Under The Bridge', 'https://phimimg.com/upload/vod/20260404-1/982a35ba8675e8897dbdb2bcdc0d7fab.jpg', 'https://phimimg.com/upload/vod/20260404-1/7247a2f30c5eff3ebb93e7c847c8ebc0.jpg', '<p>Cô bé 14 tuổi Reena Virk rời nhà để đến tham gia một bữa tiệc cùng bạn bè và đã mãi mãi không bao giờ trở về. Qua góc nhìn của nhà văn Rebecca Godfrey và một nữ cảnh sát địa phương, chúng ta sẽ dần bước vào thế giới ngầm đầy bí ẩn của những cô gái trẻ bị buộc tội giết người — từ đó hé lộ những sự thật bàng hoàng về kẻ thủ ác mà không ai có thể ngờ tới.</p>', 'Tập 5', 8, 'series', 'ongoing', 26, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lily Gladstone","avatar":""},{"name":"Riley Keough","avatar":""},{"name":"Vritika Gupta","avatar":""},{"name":"Chloe Guidry","avatar":""},{"name":"Javon Walton","avatar":""},{"name":"Izzy G.","avatar":""},{"name":"Aiyana Goodfellow","avatar":""},{"name":"Ezra Faroque Khan","avatar":""},{"name":"Archie Panjabi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Debaixo da Ponte: A Verdadeira História do Assassinato de Reena Virk","桥下杀人事件","Under the Bridge"]', 1784690324175);
