INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuyet-menh-thu-kich', 'Tuyệt Mệnh Thư Kích', 'Desperate Sniper', 'https://phimimg.com/upload/vod/20260409-1/640080a90d205d1a6dd5705d2ff32fc7.jpg', 'https://phimimg.com/upload/vod/20260409-1/47b694361f6f10c5796f71fd1e8623a8.jpg', '<p>Câu chuyện xảy ra tại quốc gia A, đội trưởng Triệu Kiện dẫn dắt đội đặc nhiệm Sói Đen hộ tống một lô hàng cho tướng quân Sát Sai thì bị quân du kích phục kích. Sau khi bắt được nữ đội trưởng du kích Chương Linh, Triệu Kiện mới bàng hoàng nhận ra thứ họ đang vận chuyển không phải hàng cứu trợ nhân đạo mà là nguyên liệu cho các thí nghiệm trên cơ thể người. Vì lòng tham vô độ, tướng Sát Sai đã dùng chính đồng bào mình làm vật thí nghiệm. Chứng kiến cảnh tượng thảm khốc trong rừng sâu, Triệu Kiện cùng các đồng đội quyết định quay xe, bắt tay cùng Chương Linh để tiêu diệt tổ chức của Sát Sai, đòi lại công lý cho những linh hồn oan khuất.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Cam Đình Đình","avatar":""},{"name":"Mạch Hanh Lợi","avatar":""},{"name":"Lý Tử Hùng","avatar":""},{"name":"Lạc Đạt Hoa","avatar":""},{"name":"Trương Tiếu Quân","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Desperate Sniper","绝命狙击"]', 1784690324175);
