INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('su-that-sau-giac-ngu', 'Sự Thật Sau Giấc Ngủ', 'While You Were Sleeping', 'https://phimimg.com/upload/vod/20260409-1/66081c21f3cbca0f764f85ea7426d33e.jpg', 'https://phimimg.com/upload/vod/20260409-1/054939b7aab94b8d0076bd5dce622787.jpg', '<p>Joon Seok và Deok Hee đã sống rất bình yên, cho đến khi chứng mất trí nhớ chọn lọc của cô hé lộ những điều kỳ lạ. Sau cái chết của Joon Seok, cô dần lần theo ký ức và phát hiện sự thật chấn động.</p>', 'Full', 1, 'single', 'completed', 13, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Choo Ja-hyun","avatar":""},{"name":"Lee Mu-saeng","avatar":""},{"name":"Son Sook","avatar":""},{"name":"Park Min-jung","avatar":""},{"name":"Sung Ji-ru","avatar":""},{"name":"Kim Jin-soo","avatar":""},{"name":"Nam Dae-hyeop","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["وقتی تو خواب بودی","While You Were Sleeping","당신이 잠든 사이"]', 1784690324175);
