INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rap-public', 'Rap: Public', 'RAP:PUBLIC', 'https://phimimg.com/upload/vod/20260404-1/680668f9354d2ef9be744ef2dbbde1d9.jpg', 'https://phimimg.com/upload/vod/20260404-1/19f91626659acdec30fac44f3e923996.jpg', '<p>RAP:PUBLIC là một đấu trường Hip-hop thực thụ, nơi 60 thí sinh (được gọi là các &quot;Player&quot;) cùng tham gia vào một cuộc chiến sinh tồn đầy tính chiến thuật. Khác với các chương trình rap thông thường, tại đây, &quot;Rap&quot; không chỉ là nghệ thuật biểu diễn mà còn là vũ khí sắc bén nhất để các người chơi tấn công, phòng thủ và giành lấy quyền lực trong một xã hội giả lập. Những người tham gia phải sử dụng kỹ năng gieo vần, nhịp điệu và tư duy chiến lược để vượt qua các thử thách khắc nghiệt, nhằm khẳng định vị thế độc tôn của mình trong cộng đồng Hip-hop này.</p>', 'Hoàn Tất (12/12)', 12, 'tvshows', 'completed', 18, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jay Park","avatar":""},{"name":"Park Gyu-jung","avatar":""},{"name":"Lee Hwi-min","avatar":""},{"name":"Vangdale","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '["랩:퍼블릭"]', 1784690324175);
