INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-co-gai-hokkaido-cuc-ky-de-thuong', 'Những Cô Gái Hokkaido Cực Kỳ Dễ Thương', 'Hokkaido Gals Are Super Adorable!', 'https://phimimg.com/upload/vod/20260404-1/6a667b57ba955eb171cc6c635c7a028e.jpg', 'https://phimimg.com/upload/vod/20260404-1/c161eab7261b23794829ab697f0bd0db.jpg', '<p>Ở Hokkaido, tuyết rơi không phải là thứ duy nhất khiến người ta phải ngước nhìn — mà chính là những cô nàng siêu cấp đáng yêu đang biến phương Bắc băng giá thành một &quot;điểm nóng&quot; của thời trang và niềm vui.</p><p>Hãy sẵn sàng đón nhận một trận bão mùa đông đầy ắp tiếng cười, tình yêu và những bộ cánh cực chất, khi các cô nàng này chứng minh rằng &quot;xinh đẹp&quot; là tôn chỉ bất kể mùa nào trong năm. Tại nơi đây, cái lạnh cắt da cũng phải chào thua những tín đồ thời trang chính hiệu!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 15, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ayane Sakura","avatar":""},{"name":"Nobunaga Shimazaki","avatar":""},{"name":"Yumiri Hanamori","avatar":""},{"name":"Reina Ueda","avatar":""},{"name":"Yoshitsugu Matsuoka","avatar":""},{"name":"Rika Nagae","avatar":""},{"name":"Eri Kitamura","avatar":""},{"name":"Mariko Nagai","avatar":""},{"name":"Yurika Kubo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["¡Las chicas de Hokkaido son súper adorables!","北海道辣妹儿贼招人稀罕","Dosanko Gyaru wa Namaramenkoi","Dosanko Gal wa Namaramenkoi","Dosanko Gal wa Namara Menkoi","Dosanko Gyaru wa Namara Menkoi","Hokkaido Gals Are Super Adorable!","道産子ギャルはなまらめんこい"]', 1784690324175);
