INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhung-co-gai-hokkaido-cuc-ky-de-thuong', 'Những Cô Gái Hokkaido Cực Kỳ Dễ Thương', 'Hokkaido Gals Are Super Adorable!', 'những cô gái hokkaido cực kỳ dễ thương hokkaido gals are super adorable! ayane sakura nobunaga shimazaki yumiri hanamori reina ueda yoshitsugu matsuoka rika nagae eri kitamura mariko nagai yurika kubo ¡las chicas de hokkaido son súper adorables! 北海道辣妹儿贼招人稀罕 dosanko gyaru wa namaramenkoi dosanko gal wa namaramenkoi dosanko gal wa namara menkoi dosanko gyaru wa namara menkoi hokkaido gals are super adorable! 道産子ギャルはなまらめんこい', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chao-mung-den-voi-lop-hoc-de-cao-thuc-luc-phan-3', 'Chào Mừng Đến Với Lớp Học Đề Cao Thực Lực (Phần 3)', 'Classroom Of The Elite (Season 3)', 'https://phimimg.com/upload/vod/20260404-1/75293dfd049047001671fad7fe8c7bc2.jpg', 'https://phimimg.com/upload/vod/20260404-1/a81442412422f132c7038f320f196b1d.jpg', '<p>Tiếp nối những thành công vang dội của hai mùa trước, Classroom Of The Elite (Season 3) hứa hẹn sẽ mang đến những cuộc chiến trí tuệ đầy bất ngờ và căng thẳng hơn bao giờ hết. Khi bước vào một năm học mới, các học sinh lớp D, dẫn đầu bởi Ayanokoji Kiyotaka, sẽ phải đối mặt với thử thách mới, nhiều khó khăn hơn và cả những đối thủ đáng gờm hơn. Liệu họ có thể vượt qua mọi giới hạn để đạt được mục tiêu của mình? Những bí ẩn về quá khứ của Kiyotaka cũng dần được hé lộ, đồng thời mối quan hệ giữa các nhân vật sẽ có những bước ngoặt đầy kịch tính.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 16, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shoya Chiba","avatar":""},{"name":"Akari Kito","avatar":""},{"name":"Ayana Taketatsu","avatar":""},{"name":"Yurika Kubo","avatar":""},{"name":"Mao Ichimichi","avatar":""},{"name":"Ryota Osaka","avatar":""},{"name":"Eiji Takeuchi","avatar":""},{"name":"Rina Hidaka","avatar":""},{"name":"Nao Toyama","avatar":""},{"name":"Rina Sato","avatar":""},{"name":"Rie Takahashi","avatar":""},{"name":"Momoko Seto","avatar":""},{"name":"Mao Ichimichi","avatar":""},{"name":"Masaaki Mizunaka","avatar":""},{"name":"Toshiki Iwasawa","avatar":""},{"name":"Shinnosuke Tokudome","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Classroom of the Elite","欢迎来到实力至上主义的教室","欢迎来到实力至上主义的教室 第二季","欢迎来到实力至上主义的教室 第2季","ようこそ実力至上主義の教室へ 2nd Season","欢迎来到实力至上主义教室","अभिजात वर्ग की कक्षा","Youkoso Jitsuryoku Shijou Shugi no Kyoushitsu e","You-Zitsu","Youzitsu","You-Jitsu","Youjitsu","Youkoso Jitsuryoku Shijou Shugi no Kyoushitsu e 3rd Season","ようこそ実力至上主義の教室へ 3rd Season","ようこそ実力至上主義の教室へ 4th Season 2年生編1学期","어서오세요 실력지상주의 교실에","Добро пожаловать в класс для особо одарённых","Добро пожаловать в класс превосходства","歡迎來到實力至上主義的教室","歡迎來到實力至上主義的教室 第四季 2年級篇 第一學期","Ласкаво просимо до класу верховенства","Welcome to the Classroom of the Elite","Classroom of the Elite 4th Season: Second Year, First Semester","Mukammalik sinfiga xush kelibsiz","Elita sinfi","ようこそ実力至上主義の教室へ"]', 1784690324175);
