INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chao-mung-den-voi-lop-hoc-de-cao-thuc-luc-phan-3', 'Chào Mừng Đến Với Lớp Học Đề Cao Thực Lực (Phần 3)', 'Classroom Of The Elite (Season 3)', 'chào mừng đến với lớp học đề cao thực lực (phần 3) classroom of the elite (season 3) shoya chiba akari kito ayana taketatsu yurika kubo mao ichimichi ryota osaka eiji takeuchi rina hidaka nao toyama rina sato rie takahashi momoko seto mao ichimichi masaaki mizunaka toshiki iwasawa shinnosuke tokudome classroom of the elite 欢迎来到实力至上主义的教室 欢迎来到实力至上主义的教室 第二季 欢迎来到实力至上主义的教室 第2季 ようこそ実力至上主義の教室へ 2nd season 欢迎来到实力至上主义教室 अभिजात वर्ग की कक्षा youkoso jitsuryoku shijou shugi no kyoushitsu e you-zitsu youzitsu you-jitsu youjitsu youkoso jitsuryoku shijou shugi no kyoushitsu e 3rd season ようこそ実力至上主義の教室へ 3rd season ようこそ実力至上主義の教室へ 4th season 2年生編1学期 어서오세요 실력지상주의 교실에 добро пожаловать в класс для особо одарённых добро пожаловать в класс превосходства 歡迎來到實力至上主義的教室 歡迎來到實力至上主義的教室 第四季 2年級篇 第一學期 ласкаво просимо до класу верховенства welcome to the classroom of the elite classroom of the elite 4th season: second year, first semester mukammalik sinfiga xush kelibsiz elita sinfi ようこそ実力至上主義の教室へ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bo-tinh-ti-nguyen-khoi', 'Bộ Tinh Ti: Nguyên Khởi', 'Blader Soul', 'https://phimimg.com/upload/vod/20260404-1/e3324a0a983d9dbd6de8a63984f4d1a5.jpg', 'https://phimimg.com/upload/vod/20260404-1/45af965a9b8c75928c4b77d01433577a.jpg', '<p>Hai thiếu niên dưới cái bóng của gia đình quý tộc khao khát vùng đất thần tiên huyền thoại Bồng Lai. Một sự kiện đặc biệt xảy ra đã đánh thức sức mạnh tiềm ẩn trong cơ thể họ, đồng thời đánh thức niềm khao khát chưa từng thấy của họ.</p>', 'Hoàn Tất (18/18)', 18, 'hoathinh', 'completed', 18, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["捕星司·源起","Star Catcher","Star Catcher: Origin","Bu Xing Si: Yuan Qi","捕星司源起","Blader Soul"]', 1784690324175);
