INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-phap-su-nhiem-vu-100-nam', 'Hội Pháp Sư: Nhiệm Vụ 100 Năm', 'Fairy Tail: 100 Years Quest', 'https://phimimg.com/upload/vod/20240713-1/e57e74bcee53168d1a1281a3d8d21796.jpg', 'https://phimimg.com/upload/vod/20240713-1/5456fc99ccd18aa112302f866b287582.jpg', '<p>Một năm sau khi hội Fairy Tail vượt qua được thế lực ma quỷ của Acnologia và Zeref, Nats và nhóm của mình hành trình đến lục địa phía bắc Guiltina, nơi họ tìm kiếm chủ nhân của Nhiệm vụ 100 năm và nhận được nhiệm vụ gần như bất khả thi: phong ấn Ngũ Long Thần—một nhóm cá nhân có sức mạnh to lớn đến mức nếu để yên có thể gây ra sự tàn phá toàn cầu. Trong khi đó, một thành viên mới đầy nghị lực tên là Touka được tuyển vào Fairy Tail. Mặc dù năng lượng sôi nổi và bản chất đam mê khiến cô ấy trở thành người hoàn hảo cho hội, nhưng dường như cô ấy có nhiều điều hơn những gì bạn thấy.</p>', 'Hoàn Tất (25/25)', 25, 'hoathinh', 'completed', 21, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Tetsuya Kakihara","avatar":""},{"name":"Aya Hirano","avatar":""},{"name":"Rie Kugimiya","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324175);
