INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-tren-pho-tu-ky-phan-2', 'Tình Yêu Trên Phổ Tự Kỷ (Phần 2)', 'Love On The Spectrum (Season 2)', 'https://phimimg.com/upload/vod/20260403-1/090e34988f208f2f26a8ccc815665457.jpg', 'https://phimimg.com/upload/vod/20260403-1/ccb407f215918e92461bac8ed5a74b14.jpg', '<p>Trong loạt phim tài liệu lãng mạn này, những người rối loạn phổ tự kỷ tìm kiếm tình yêu cũng như xoay xở trong thế giới hẹn hò và các mối quan hệ không ngừng thay đổi.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 20, 2024, 'Vietsub', 'FHD', 'Úc', 0, '[]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Amor no Espectro: EUA","Láska ve spektru: USA","Liebe im Spektrum: USA","El amor en el espectro autista: EE.UU.","Histoires d''amour et d''autisme : États-Unis","Στο Φάσμα του Έρωτα: ΗΠΑ","Szerelem az autizmus spektrumban USA","L''amore nello spettro USA","러브 온 더 스펙트럼: 미국","Amor en el espectro: EE. UU.","Kjærlighet på spekteret – USA","Кохання в спектрі: США","Love on the Spectrum U.S.","Tình yêu trên phổ tự kỷ","Love on the Spectrum"]', 1784690324175);
