INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-oi-con-xin-loi', 'Mẹ Ơi Con Xin Lỗi', 'Mom, I''m Sorry', 'https://phimimg.com/upload/vod/20260403-1/8334106bf961f6e95e27f50154857e4f.jpg', 'https://phimimg.com/upload/vod/20260403-1/bf4b245a450ebd2e363376c8b05cfbd1.jpg', '<p>Bộ phim xoay quanh một cơ hội đặc biệt khi nhân vật chính được “gặp lại” mẹ mình thời thiếu nữ. Thông qua những khoảnh khắc đời thường, câu chuyện dần hé lộ những hy sinh thầm lặng, ước mơ dang dở và tình cảm sâu sắc của người mẹ. Phim khai thác đề tài gia đình theo cách nhẹ nhàng nhưng chạm cảm xúc, kết hợp yếu tố hoài niệm và chữa lành. Nội dung phù hợp với khán giả yêu thích slice of life, giàu cảm xúc và thông điệp về sự thấu hiểu, trân trọng tình thân...</p>', 'Hoàn Tất (18/18)', 18, 'hoathinh', 'completed', 14, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Li Jiaxiang","avatar":""},{"name":"Li Ai","avatar":""},{"name":"Xiaofeng Lai","avatar":""},{"name":"Su Dawei","avatar":""},{"name":"Xu Xu","avatar":""},{"name":"Hu Lin","avatar":""},{"name":"Tang Yi","avatar":""},{"name":"Zhou Jian","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mamá, Lo Siento","Xiehou ta de Shaonu Shidai","Xie Hou Ta De Shao Nv Shi Dai","我的妈妈是校花","ママミアン","Mam-ma-mi-an","맘마미안","Mammamian","Mamma Mian","Mom, I''m Sorry","邂逅她的少女时代"]', 1784690324175);
