INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nut-that-uan-khuc', 'Nút Thắt Uẩn Khúc', 'Sister Yujeong', 'https://phimimg.com/upload/vod/20260402-1/6a380fdf2877c1cc9630dc0ebd7d2bf4.jpg', 'https://phimimg.com/upload/vod/20260402-1/dc3c36c5bfba05c2fba7afe60c0813fa.jpg', '<p>Yujeong luôn nghĩ sự bình lặng giữa mình và em gái là sự hài hòa đáng có cho đến ngày cô hay tin vụ án chấn động của em gái. Từ đây, cô mới thực sự tìm hiểu những uẩn khúc trong chính tâm hồn cô bé.</p>', 'Full', 1, 'single', 'completed', 14, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Ye-yeong","avatar":""},{"name":"Lee Ha-eun","avatar":""},{"name":"Kim Yi-kyeong","avatar":""},{"name":"Lee Chang-hoon","avatar":""},{"name":"Park Jong-hwan","avatar":""},{"name":"Han Hae-in","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sister Yoojung","Eonni Yujeong","玉贞姐姐","언니 유정"]', 1784690324175);
