INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-noi-voi-me-rang-nguoi-giu-tre-da-chet-2024', 'Đừng Nói Với Mẹ Rằng Người Giữ Trẻ Đã Chết', 'Don''t Tell Mom The Babysitter''s Dead', 'https://phimimg.com/upload/vod/20260402-1/3d567a217e9f727035cea2e8dc4df40c.jpg', 'https://phimimg.com/upload/vod/20260402-1/b4f91b1c340c9804048b9121ac3ded38.jpg', '<p>Kế hoạch cho một mùa hè vô tư lự của cô nàng Tanya mười bảy tuổi bỗng chốc tan thành mây khói khi người mẹ đang bị căng thẳng quá độ của cô quyết định lên đường đi nghỉ dưỡng và gửi gắm Tanya cùng ba anh em cho một bà giữ trẻ già nua, khó tính (và có tư tưởng phân biệt chủng tộc). Cái chết đột ngột của bà giữ trẻ khiến lũ trẻ rơi vào tình cảnh thiếu hụt tiền bạc, nhưng chúng lại không nỡ gọi mẹ về sớm, phá hỏng kỳ nghỉ phục hồi sức khỏe quý giá của bà. Trước tình thế đó, Tanya buộc phải đi tìm việc làm. Bằng cách giả dạng làm người trưởng thành, cô đã trúng tuyển vị trí trợ lý giám đốc tại một công ty thời trang. Chỉ sau một đêm, Tanya bị đẩy vào thế giới của người lớn, vừa phải gánh vác công việc văn phòng áp lực, vừa phải học cách &quot;làm cha làm mẹ&quot; để chăm sóc các em mình.</p>', 'Full', 1, 'single', 'completed', 13, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Simone Joy Jones","avatar":""},{"name":"Nicole Richie","avatar":""},{"name":"Donielle T. Hansley Jr.","avatar":""},{"name":"Ayaamii Sledge","avatar":""},{"name":"Carter Young","avatar":""},{"name":"Miles Fowler","avatar":""},{"name":"Iantha Richardson","avatar":""},{"name":"Patricia Williams","avatar":""},{"name":"June Squibb","avatar":""},{"name":"Tyriq Withers","avatar":""},{"name":"Tyshawn Jones","avatar":""},{"name":"Jermaine Fowler","avatar":""},{"name":"Gus Kenworthy","avatar":""},{"name":"Olivia Ritchie","avatar":""},{"name":"Brandon Severs","avatar":""},{"name":"Lizet Up","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["No Le Digas A Mamá Que La Niñera Ha Muerto","Mos i thuaj mamit që bebisiteri ka vdekur","打工淑女","Don''t Tell Mom the Babysitter''s Dead"]', 1784690324175);
