INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dung-noi-voi-me-rang-nguoi-giu-tre-da-chet-2024', 'Đừng Nói Với Mẹ Rằng Người Giữ Trẻ Đã Chết', 'Don''t Tell Mom The Babysitter''s Dead', 'đừng nói với mẹ rằng người giữ trẻ đã chết don''t tell mom the babysitter''s dead simone joy jones nicole richie donielle t. hansley jr. ayaamii sledge carter young miles fowler iantha richardson patricia williams june squibb tyriq withers tyshawn jones jermaine fowler gus kenworthy olivia ritchie brandon severs lizet up no le digas a mamá que la niñera ha muerto mos i thuaj mamit që bebisiteri ka vdekur 打工淑女 don''t tell mom the babysitter''s dead', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-sot', 'Sống Sót', 'Survive', 'https://phimimg.com/upload/vod/20250519-1/051a8f2ea3d37371a83e3a1e628c0395.jpg', 'https://phimimg.com/upload/vod/20250519-1/443b206213c2c470a02026d0cf8cc24d.jpg', '<p>Trong khi tổ chức sinh nhật cho con trai trên một chiếc du thuyền giữa đại dương, một cặp vợ chồng bất ngờ gặp phải cơn bão dữ dội. Tuy nhiên, nỗi kinh hoàng thực sự chỉ bắt đầu khi cơn bão đánh thức những sinh vật săn mồi từ đáy biển sâu. Bị mắc kẹt giữa biển khơi và bao vây bởi nỗi kinh hoàng trỗi dậy từ lòng đại dương, gia đình ấy buộc phải chiến đấu để sống sót — không chỉ chống lại quái vật, mà cả chính nỗi sợ và mâu thuẫn giữa họ.</p>', 'Full', 1, 'single', 'completed', 16, 2024, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Émilie Dequenne","avatar":""},{"name":"Andreas Pietschmann","avatar":""},{"name":"Lisa Delamar","avatar":""},{"name":"Lucas Ebel","avatar":""},{"name":"Arben Bajraktaraj","avatar":""},{"name":"Olivier Ho Hio Hen","avatar":""},{"name":"Stéphanie Guerin","avatar":""},{"name":"Rida Ait Oufqir","avatar":""},{"name":"Youssef El Hiaboui","avatar":""},{"name":"Simon Rérolle","avatar":""},{"name":"Ranger","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["بقا","只要活着","Catástrofe inminente","Sobreviviendo","Survive","La extinción","Survivre"]', 1784690324175);
