INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('song-sot', 'Sống Sót', 'Survive', 'sống sót survive émilie dequenne andreas pietschmann lisa delamar lucas ebel arben bajraktaraj olivier ho hio hen stéphanie guerin rida ait oufqir youssef el hiaboui simon rérolle ranger بقا 只要活着 catástrofe inminente sobreviviendo survive la extinción survivre', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('fatestrange-fake', 'Fate/strange Fake', 'Fate/strange Fake', 'https://phimimg.com/upload/vod/20260204-1/60bbcc1d188601e70aba13b926a1f582.jpg', 'https://phimimg.com/upload/vod/20260204-1/1d5e118448335147595bdfc4c59f05bf.jpg', '<p>Trong một cuộc Chiến Tranh Chén Thánh, các Pháp sư (Master) và Anh linh của họ (Servant) chiến đấu để giành quyền kiểm soát Chén Thánh — một thiết kế ban điều ước vạn năng được cho là có thể thực hiện mọi nguyện vọng. &nbsp;Nhiều năm đã trôi qua kể từ khi Cuộc Chiến Tranh Chén Thánh lần thứ năm kết thúc tại Nhật Bản. Giờ đây, những dấu hiệu cho thấy sự xuất hiện của một Chén Thánh mới tại thành phố Snowfield phía Tây nước Mỹ. Đúng như dự đoán, các Master và Servant bắt đầu tụ hội... Một lớp Servant bị mất tích... Những lần triệu hồi Servant không thể xảy ra... Một quốc gia bị bao phủ trong bức màn bí mật... Và một thành phố được tạo ra để làm chiến trường. &nbsp;Trước những bất thường như vậy, Cuộc Chiến Tranh Chén Thánh bị bẻ cong và đẩy vào vực thẳm của sự điên rồ. Bức màn hãy kéo lên cho một buổi dạ vũ của con người và những anh hùng, được tạo ra để nhảy múa trên sân khấu của một Chén Thánh giả tạo.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 14, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kana Hanazawa","avatar":""},{"name":"Yuki Ono","avatar":""},{"name":"Wataru Hatano","avatar":""},{"name":"Showtaro Morikubo","avatar":""},{"name":"Yoshitsugu Matsuoka","avatar":""},{"name":"Lynn","avatar":""},{"name":"Maaya Uchida","avatar":""},{"name":"Junya Enoki","avatar":""},{"name":"Shunsuke Sakuya","avatar":""},{"name":"Daisuke Namikawa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324175);
