INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-mon-quan-phong-an', 'Quỷ Môn Quan Phong Ấn', 'Them, Behind The Door', 'https://phimimg.com/upload/vod/20260330-1/935036ca6ca139462adb9ce1acfecb20.jpg', 'https://phimimg.com/upload/vod/20260330-1/fe012b815933f07d1c495529aec9f409.jpg', '<p>Gắn liền với nhiều lời đồn kinh hoàng, những vụ tự sát và chết người bí ẩn, toà nhà Hồ Điệp trở thành địa điểm gây ám ảnh nhất tại thành phố Đài Bắc. Phức tạp là vậy, nhưng nơi này vẫn thu hút nhiều người lao động tới sinh sống vì giá thuê rẻ mạt, trong đó có Trần Vi - người phụ nữ khốn khổ đang phải tìm nơi ẩn nấp cho mình và con gái khỏi người chồng bạo lực. Câu chuyện về cánh cửa phòng 613 bị niêm phong, hành động kì lạ của cô con gái Nhã Nhã khi liên tục nói chuyện một mình với những bức tường, cùng lời cảnh báo “hãy rời đi càng sớm càng tốt” của quản lý tòa nhà và người trông coi đền thờ khiến Trần Vi ngày càng sợ hãi. Những sự kiện kinh hoàng liên tiếp ập đến kéo theo hàng loạt bí mật đáng sợ dần lộ tẩy, liệu cô có thể bảo vệ được con gái của mình và chiến thắng các linh hồn oán hận đang cuồng nộ?</p>', 'Full', 1, 'single', 'completed', 19, 2024, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Ivy Yin","avatar":""},{"name":"Tsao Yu-ning","avatar":""},{"name":"Bai Ling","avatar":""},{"name":"Bai Run-Yin","avatar":""},{"name":"Kaiser Chuang","avatar":""},{"name":"Vicky Tseng","avatar":""},{"name":"Stanley Fung Shui-Fan","avatar":""},{"name":"Tsai Chen-nan","avatar":""},{"name":"Amy Lin","avatar":""},{"name":"Tong Chih-wei","avatar":""},{"name":"Josie Ho","avatar":""},{"name":"JC Lin","avatar":""},{"name":"Amber An","avatar":""},{"name":"Yen Cheng-kuo","avatar":""},{"name":"Mario Pu","avatar":""},{"name":"Cheng Chih-wei","avatar":""},{"name":"Wu Jen-ya","avatar":""},{"name":"Lin Dao-yu","avatar":""},{"name":"Jack Chu","avatar":""},{"name":"Ya-Wei Chang","avatar":""},{"name":"Kee","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Butterfly Mansion","The Mansion of Butterfly","蝴蝶大廈","Hu Die Da Shia","鬼們之蝴蝶大廈"]', 1784690324175);
