INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-chien-nguoi-khong-lo-lan-tan-cong-cuoi-cung-dai-chien-titan', 'Đại Chiến Người Khổng Lồ: Lần Tấn Công Cuối Cùng (Đại Chiến Titan)', 'Attack On Titan: The Last Attack', 'https://phimimg.com/upload/vod/20250419-1/5592e992bf3e556c9660f30d058dce71.jpg', 'https://phimimg.com/upload/vod/20250419-1/50cf359f6ed6307597fc160044132ac3.jpg', '<p>Trong cuộc chiến cuối cùng định đoạt số phận thế giới, Eren Yeager đã giải phóng sức mạnh tối thượng của các Titan. Dẫn đầu đội quân Titan Đại hình khổng lồ, Eren quyết tâm hủy diệt mọi kẻ thù đe dọa đến quê hương Eldia. Thế nhưng, cuộc chiến này không chỉ là về sự sống còn, mà còn là cuộc đối đầu giữa lòng thù hận và hy vọng. Kết thúc khúc hùng ca đầy bi tráng, di sản của chiến tranh và những ám ảnh về tự do vẫn tiếp tục đeo bám nhân loại, để lại câu hỏi về giá trị của sự hy sinh và tự do thật sự.</p>', 'Full', 1, 'hoathinh', 'completed', 24, 2024, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 1, '[{"name":"Yuki Kaji","avatar":""},{"name":"Yui Ishikawa","avatar":""},{"name":"Marina Inoue","avatar":""},{"name":"Hiroshi Kamiya","avatar":""},{"name":"Yu Shimamura","avatar":""},{"name":"Romi Park","avatar":""},{"name":"Yoshimasa Hosoya","avatar":""},{"name":"Kisho Taniyama","avatar":""},{"name":"Hiro Shimono","avatar":""},{"name":"Koji Hiwatari","avatar":""},{"name":"Takehito Koyasu","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Natsuki Hanae","avatar":""},{"name":"Manami Numakura","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Атака титанов: Последняя атака","Attack on Titan: O Último Ataque","Attack on Titan the Movie: The Last Attack","劇場版「進擊的巨人」完結篇 THE LAST ATTACK","Attack on Titan: El ataque final","L''Attaque des titans : La dernière attaque","Shingeki no Kyojin Movie: The Last Attack","劇場版 進撃の巨人　完結編 THE LAST ATTACK","進撃の巨人 THE LAST ATTACK","劇場版「進擊的巨人」完結篇","Gekijōban Shingeki no Kyojin Kanketsu-hen THE LAST ATTACK","进击的巨人剧场版：完结篇 · 最后的进击","Attack on Titan: The Last Attack","劇場版「進撃の巨人」完結編 THE LAST ATTACK"]', 1784690324175);
