INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tuyet-dia-phi-hanh', 'Tuyệt Địa Phi Hành', 'The Simulator', 'https://phimimg.com/upload/vod/20260320-1/03b3a8f307ecf82c8a97c32e6b466bd9.jpg', 'https://phimimg.com/upload/vod/20260320-1/ededd91ac877b576db8c30d6930f3df5.jpg', '<p>Trong bộ phim do AI và con người cùng sáng tạo, May là vợ của nhân vật chính Lưu Nhất, cô là tiếp viên của một hãng hàng không. Một ngày nọ khi thực hiện nhiệm vụ phục vụ cho chuyên cơ chở tổng thống một quốc gia, cô bị bọn khủng bố cướp máy bay. Lúc này Lưu Nhất, một kỹ sư bảo trì hàng không buộc phải sử dụng kỹ năng chơi game và kiến thức kỹ thuật về hàng không của mình để giải cứu người vợ đang ở cách xa hàng nghìn dặm khỏi chiếc máy bay chở khách đang gặp nạn.</p>', 'Full', 1, 'single', 'completed', 12, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Lâm Sinh","avatar":""},{"name":"Vương Đan Mộng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["绝地飞行"]', 1784690324175);
