INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sac-den-huyen-dieu-phan-1', 'Sắc Đen Huyền Diệu (Phần 1)', 'Beauty In Black (Season 1)', 'https://phimimg.com/upload/vod/20250308-1/8ca769a25825dcafd1663e7753082b22.jpg', 'https://phimimg.com/upload/vod/20250308-1/f4a3c0da21ede09ca7c7c49535d49ba7.jpg', '<p>Số phận của một vũ nữ thoát y thay đổi khi cô vướng vào một gia đình giàu có nhưng đầy bất ổn đứng sau một đế chế mỹ phẩm và một âm mưu buôn người xảo quyệt.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 15, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Taylor Polidore","avatar":""},{"name":"Crystle Stewart","avatar":""},{"name":"Amber Reign Smith","avatar":""},{"name":"Xavier Smalls","avatar":""},{"name":"Julian Horton","avatar":""},{"name":"Steven G. Norfleet","avatar":""},{"name":"Richard Lawson","avatar":""},{"name":"Terrell Carter","avatar":""},{"name":"Shannon Wallace","avatar":""},{"name":"Charles Malik Whitfield","avatar":""},{"name":"Debbi Morgan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["زیبای سیاه","Tyler Perry''s Beauty in Black","Beauty in Black"]', 1784690324175);
