INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nina-cua-dat-nuoc-ngan-sao', 'Nina Của Đất Nước Ngàn Sao', 'Nina The Starry Bride', 'https://phimimg.com/upload/vod/20250504-1/6de36690f67f33fd74393f5523e2d44f.jpg', 'https://phimimg.com/upload/vod/20250504-1/741c04fb2c43ef017be09312626deb9a.jpg', '<p>Nina có một khởi đầu khó khăn trong cuộc sống, phải ăn trộm để sinh tồn và cuối cùng bị chính anh trai mình bán làm nô lệ. Nhưng trái với mong đợi, kẻ bắt giữ cô – Hoàng tử Azure – lại quyết định cho cô sống cuộc đời của một công chúa… cụ thể là công chúa-tư tế Alisha vừa mới qua đời.

Dù cuộc đời có thay đổi, Nina vẫn không dễ dàng từ bỏ cuộc sống cũ mà không chiến đấu. Và có lẽ, Azure chính là người duy nhất có thể đấu trí với cô. Nhưng Nina có thể tin tưởng Azure bao nhiêu? Và liệu cô có thể ngăn những cảm xúc đang nảy sinh trong trái tim mình, khi biết rằng cuối cùng cô phải kết hôn với một người khác…?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 14, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Minami Tanaka","avatar":""},{"name":"Yuuichirou Umehara","avatar":""},{"name":"Koki Uchiyama","avatar":""},{"name":"Nao Toyama","avatar":""},{"name":"Tatsuya Tomizawa","avatar":""},{"name":"Seiichiro Yamashita","avatar":""},{"name":"Kaito Ishikawa","avatar":""},{"name":"Shun Horie","avatar":""},{"name":"Mitsuki Saiga","avatar":""},{"name":"Masumi Tazawa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["星辰坠落之国的妮娜","Hoshifuru Oukoku no Nina","Hoshi Furu Oukoku no Nina","Hoshifuru Ōkoku no Nina","โฮชิฟูรุ โอโกกุ โนะ นินะ","Nina of the Starry Kingdom","星降る王国のニナ"]', 1784690324175);
