INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-luat-su-di-biet', 'Nữ Luật Sư Dị Biệt', 'MONSTER', 'https://phimimg.com/upload/vod/20260309-1/cd4274635aeec52d2831f08aba21fee7.jpg', 'https://phimimg.com/upload/vod/20260309-1/b3ee2c9f0dd9562984edab329201dbe7.jpg', '<p>Nhờ năng khiếu bẩm sinh xuất sắc và tích lũy được nhiều kiến thức qua việc tham dự các phiên tòa, Ryoko Kannami đã vượt qua được kỳ thi luật sư ngay từ khi mới học cấp ba. Sau thời gian dài sống cô độc vì một biến cố bất ngờ trong gia đình, cô quyết định trở thành luật sư và gia nhập một công ty luật. Là người có tính cách dị biệt, Ryoko xem mỗi phiên tòa như một trò chơi và luôn sẵn sàng dùng đủ mọi phương pháp khác thường không ai ngờ đến để giành chiến thắng.</p>', 'Full', 11, 'series', 'completed', 12, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shuri","avatar":""},{"name":"Jesse","avatar":""},{"name":"Arata Furuta","avatar":""},{"name":"YOU","avatar":""},{"name":"Shohei Uno","avatar":""},{"name":"Kei Otozuki","avatar":""},{"name":"Tsubasa Nakagawa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["モンスター"]', 1784690324175);
