INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-nuoc-phap', 'Cô Gái Nước Pháp', 'French Girl', 'https://phimimg.com/upload/vod/20260305-1/da2ec2a0697215e9fd450464bf919527.jpg', 'https://phimimg.com/upload/vod/20260305-1/55ed39396580fe0ad0e93323b5620e17.jpg', '<p>Gordon Sweet, một giáo viên tiếng Anh hiền lành ở Brooklyn, bất ngờ tìm được tình yêu với một cô gái người Pháp và anh cũng yêu cô sâu đậm. Tuy nhiên, mối quan hệ của họ đứng trước thử thách khi cô trở về quê nhà ở thành phố Quebec để phỏng vấn vị trí bếp trưởng điều hành.&nbsp; Mọi chuyện trở nên phức tạp khi người sẽ tuyển dụng cô lại chính là người yêu cũ của cô – một đầu bếp nổi tiếng, có chương trình truyền hình đình đám. Trước đối thủ vừa tài giỏi vừa quyến rũ này, Gordon phải đối mặt với nỗi lo mất đi người mình yêu và tìm cách giữ gìn tình cảm của họ.</p>', 'Full', 1, 'single', 'completed', 19, 2024, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Zach Braff","avatar":""},{"name":"Evelyne Brochu","avatar":""},{"name":"Vanessa Hudgens","avatar":""},{"name":"Antoine Olivier Pilon","avatar":""},{"name":"Luc Picard","avatar":""},{"name":"Isabelle Vincent","avatar":""},{"name":"Charlotte Aubin","avatar":""},{"name":"Muriel Dutil","avatar":""},{"name":"William Fichtner","avatar":""},{"name":"Rémi Goulet","avatar":""},{"name":"Ed Weeks","avatar":""},{"name":"Olivier Gervais-Courchesne","avatar":""},{"name":"Ralph Prosper","avatar":""},{"name":"Hazel Nugent","avatar":""},{"name":"Catherine De Sève","avatar":""},{"name":"Luc-Marti","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","