INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giao-lo-sullivan-phan-2', 'Giao Lộ Sullivan (Phần 2)', 'Sullivan''s Crossing (Season 2)', 'https://phimimg.com/upload/vod/20260222-1/b8f6dcbf408b636fc6485adfec7fa09f.jpg', 'https://phimimg.com/upload/vod/20260222-1/20a0f5c86064715a306df2a068af99d1.jpg', '<p>Sau khi cuộc sống cá nhân và sự nghiệp của bác sĩ phẫu thuật thần kinh Maggie Sullivan rơi vào khủng hoảng, cô quyết định trở về quê nhà tại Sullivan’s Crossing. Tại đó, Maggie buộc phải tìm cách điều hướng thực tại đầy rắc rối của mình, đồng thời đối mặt với quá khứ đau thương mà cô đã cố tình phớt lờ trong nhiều năm.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 21, 2024, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Morgan Kohan","avatar":""},{"name":"Chad Michael Murray","avatar":""},{"name":"Scott Patterson","avatar":""},{"name":"Tom Jackson","avatar":""},{"name":"Andrea Menard","avatar":""},{"name":"Amalia Williamson","avatar":""},{"name":"Joel Oulette","avatar":""},{"name":"Lindura","avatar":""},{"name":"Reid Price","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["苏利文的十字路口","Sullivan''s Crossing"]', 1784690324175);
