INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dai-chien-xu-so-coi-xay-gio-gigantes-una-aventura-extraordinaria', 'Đại Chiến Xứ Sở Cối Xay Gió (Gigantes, una Aventura extraordinaria)', 'Storm Crashers (Giants Of La Mancha)', 'đại chiến xứ sở cối xay gió (gigantes, una aventura extraordinaria) storm crashers (giants of la mancha) karol sevilla carla peterson facundo reyes cassie glow micke moreno marina blanke matthew moreno demián velazco quixotes: the heirs of la mancha велетні ла-манчі los exploradores gigantes gigantes, una aventura extraordinaria la banda di don chisciotte: missione mulini a vento das geheimnis von la mancha giants of la mancha küçük don kişot''un maceraları гиганты ла-манша giganții din la mancha os gigantes de la mancha łowcy przygód gigantes: una aventura extraordinaria storm riddarinn στα ίχνη του δον κιχώτη hiiglased la manchast gigantes; una aventura extraordinaria героите на ла манча giants of la mancha les explorateurs, l''aventure fantastique gigantes, una aventura extraordinaria', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thao-thiet-ky', 'Thao Thiết Ký', 'The Legend Of Taotie', 'https://phimimg.com/upload/vod/20241210-1/d8ffd9480c0b051d4b3e90abbcb360af.jpg', 'https://phimimg.com/upload/vod/20260216-1/b432fa44a710b588f419f4ae1f99a9ef.jpg', '<p>Ở Thiên Hương Lâu của thành Vô Hạ, có một người là cô nương Châu Thành Bích- trưởng quầy xinh đẹp hoạt bát có tài nấu nướng, người còn lại là công tử thương gia Thường Thanh phất bút thành họa. Châu Thành Bích vốn tính ham ăn, dù là nguyên liệu nào cô cũng có thể biến thành món ăn ngon, ví như Giao Nhân Khoái, Hồ Nhãn Phong, Chưởng Gian Châu, Thiên Địa Xuân, Phù Dung Diệm, Vô Trường Công, Nấm Song Sinh, Đồng Tâm Tiêm, Mì Thiên Tê,... Mà những món ăn này cũng là sự vui buồn hợp tan của nhân gian, tình yêu, tình huynh đệ, tình phu thê, tình mẫu tử, nguy cơ của quốc gia thiên hạ... Trong quá trình hai người dây dưa với nhau, đã cùng trải qua nhiều chuyện. Tình cảm đến từ hai phía của họ chính là đích đến của vận mệnh, mối tình thâm này sinh ra từ đâu, nên đi về đâu đây ?</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 13, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"An Duyệt Khê","avatar":""},{"name":"Vương Hựu Thạc","avatar":""},{"name":"Ngưu Tử Phiên","avatar":""},{"name":"Sơ Tuấn Thần","avatar":""},{"name":"Triệu Gia Huyên","avatar":""},{"name":"Lan Hi","avatar":""},{"name":"Hứa Chi Nhược","avatar":""},{"name":"Giang Khải Đồng","avatar":""},{"name":"Trần Chính Dương","avatar":""},{"name":"Cao Tử Phong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Legend of Taotie","饕餮记"]', 1784690324175);
