INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('muc-trung-vo-nhan-dung-mat-tra-mat', 'Mục Trung Vô Nhân: Dùng Mắt Trả Mắt', 'Eye For An Eye 2', 'https://phimimg.com/upload/vod/20240303-1/f023b076e18b2c5ccd46421b5a5b1a58.jpg', 'https://phimimg.com/upload/vod/20240303-1/a4a1ec0d6fb82a54153a9c35ced66f5f.jpg', '<p>Bộ phim rạp này là phần tiếp theo của bộ phim trực tuyến năm 2022 mang tên &quot;Mục Trung Vô Nhân&quot; kể về Thành Hạt Tử ( Tạ Miêu thủ vai), một người mù có võ nghệ cao cường. Thành Hạt Tử tình cờ cứu sống Trương Tiểu Ngư ( Dương n Hữu thủ vai) có gia đình bị sát hại . Dưới sự thuyết phục của Tiểu Ngư, Thành Hạt Tử không thể từ chối cậu nên đã đồng ý giữ cậu lại và dạy cho cậu võ thuật. Tiểu Ngư cũng đang chờ đợi thời cơ để bắt đầu hành trình trả thù.</p>', 'Full', 1, 'single', 'completed', 14, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tse Miu","avatar":""},{"name":"Yang Enyou","avatar":""},{"name":"Huang Tao","avatar":""},{"name":"Pei Kuishan","avatar":""},{"name":"Pema Jyad","avatar":""},{"name":"Liu Fengchao","avatar":""},{"name":"Jampa Tseten","avatar":""},{"name":"Xiao Songyuan","avatar":""},{"name":"Jiang Yixuan","avatar":""},{"name":"Zhang Haosen","avatar":""},{"name":"Tu Ling","avatar":""},{"name":"Dong Bo","avatar":""},{"name":"Wang Yitong","avatar":""},{"name":"Liu Hanning","avatar":""},{"name":"Liu Haoning","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324175);
