INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('muc-trung-vo-nhan-dung-mat-tra-mat', 'Mục Trung Vô Nhân: Dùng Mắt Trả Mắt', 'Eye For An Eye 2', 'mục trung vô nhân: dùng mắt trả mắt eye for an eye 2 tse miu yang enyou huang tao pei kuishan pema jyad liu fengchao jampa tseten xiao songyuan jiang yixuan zhang haosen tu ling dong bo wang yitong liu hanning liu haoning ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-nhan-kiet-khang-long-huu-hoi', 'Địch Nhân Kiệt: Kháng Long Hữu Hối', 'Detective Dee And The Arrogant Ruler (Detective Dee And The Punished Swellhead)', 'https://phimimg.com/upload/vod/20260215-1/b579bda5722203007e1bbea325c4d5a9.jpg', 'https://phimimg.com/upload/vod/20260215-1/804749d62e46e864ed394e6bd4535d43.jpg', '<p>Vào năm 697 Công nguyên, Hoàng đế Đại Chu Võ Tắc Thiên ra lệnh tổ chức đại lễ tế đỉnh tại đàn tế gần đập Cốc Tuyền vào ngày rằm tháng tám để củng cố hoàng quyền. Ngày 12 tháng 8, đập Cốc Tuyền xảy ra sự việc Long thần trù ếm, nhiều người biến đổi kỳ lạ về thể xác, bị yêu long canh giữ kho báu của Long thần nuốt chửng mà chết. Sự việc Long thần trù ếm liên tục diễn ra, điều kỳ lạ hơn nữa là Thủy bộ Viên ngoại lang Vương Ngụy Hòa, người luôn không tin vào lời trù ếm của Long thần đã hóa rồng và tấn công Hoàng đế Võ Tắc Thiên khi lên triều diện thánh. Địch Nhân Kiệt nhận lệnh điều tra vụ án, phát hiện những người chết đều có liên quan đến kho báu của Long thần dưới đập Cốc Tuyền.</p>', 'Full', 1, 'single', 'completed', 12, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Tử Kiện","avatar":""},{"name":"Từ Thiếu Cường","avatar":""},{"name":"Mễ Tuyết","avatar":""},{"name":"Mã Nham","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Detective Dee and the Arrogant Ruler","Detective Dee: The Regrets of the Dragon","Detective Dee: The Arrogant Ruler","狄仁杰之亢龙有悔"]', 1784690324175);
