INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phan-dau-phan-3', 'Phấn Đấu (Phần 3)', 'Industry (Season 3)', 'https://phimimg.com/upload/vod/20260210-1/a8f16c627323bdfc446e9f7974ea3ea9.jpg', 'https://phimimg.com/upload/vod/20260210-1/2a22f9fe8ff66ab5c37147338bf7652c.jpg', '<p><span style="text-wrap-mode: wrap;">Trong thế giới khốc liệt của tài chính quốc tế, một nhóm sinh viên mới tốt nghiệp cùng nhau cạnh tranh cho một số lượng giới hạn các vị trí chính thức tại một ngân hàng đầu tư hàng đầu ở London. Ranh giới giữa đồng nghiệp, bạn bè, người tình và kẻ thù sớm trở nên mờ nhạt khi họ đắm mình vào một văn hóa công ty được định nghĩa bởi tình dục, ma túy và cái tôi cá nhân cũng nhiều như bởi các thương vụ và cổ tức.</span></p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Myha''la","avatar":""},{"name":"Marisa Abela","avatar":""},{"name":"Ken Leung","avatar":""},{"name":"Kit Harington","avatar":""},{"name":"Max Minghella","avatar":""},{"name":"Kiernan Shipka","avatar":""},{"name":"Miriam Petche","avatar":""},{"name":"Toheeb Jimoh","avatar":""},{"name":"Charlie Heaton","avatar":""},{"name":"Sagar Radia","avatar":""},{"name":"Kal Penn","avatar":""},{"name":"Amy James-Kelly","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["投行风云","投行迷情","金融业实录","金融围城","Industry"]', 1784690324175);
