INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thieu-nu-nguoi-may', 'Thiếu Nữ Người Máy', 'Shell Girl', 'https://phimimg.com/upload/vod/20260208-1/e7f36f5b97a1e8c4c4394e0f116b738e.jpg', 'https://phimimg.com/upload/vod/20260208-1/d0db29a9f4a59a2a43cfc47393f2e1af.jpg', '<p>Cô gái Annie tỉnh dậy trong phòng thí nghiệm, phát hiện mình sở hữu kỹ năng võ thuật vượt trội nhưng lại mất hết trí nhớ, đồng thời bị một người đàn ông lạ mặt truy sát. Nhờ sự giúp đỡ của chàng trai hài hước Lý Hạo Nhiên, Annie thoát khỏi cuộc truy sát, và bắt đầu hành trình tìm lại thân phận của mình qua những mảnh ký ức vỡ vụn trong đầu. Tuy nhiên, mọi chuyện không đơn giản như vẻ bề ngoài. Annie phát hiện ra rằng mỗi người tiếp xúc với cô dường như đều có những bí mật không thể nói ra.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Miya","avatar":""},{"name":"Ki-a-nu","avatar":""},{"name":"Trần Mỗ","avatar":""},{"name":"Lưu Tuyết Hiên","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Shell Hirl","机壳少女"]', 1784690324175);
