INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-sung-ban-tia-truong-tieu-long-tay-ngam-vung-chac', 'Tay Súng Bắn Tỉa Trương Tiểu Long (Tay Ngắm Vững Chắc)', 'Hard Guy Sniper', 'https://phimimg.com/upload/vod/20260208-1/06c085f77b508a8dea8755bfdbbe4952.jpg', 'https://phimimg.com/upload/vod/20260208-1/3d64de92151817475867d66a2c512e8d.jpg', '<p>Trong bộ phim, Trương Tiểu Long và Vương Thái cùng những người khác từng là đồng đội gắn bó trải qua hoạn nạn, tình như anh em ruột thịt. Sau này, Trương Tiểu Long và Vương Thái nảy sinh mâu thuẫn, Vương Thái ôm lòng hận thù mà trở nên hắc hóa. Trong một nhiệm vụ, Vương Thái âm mưu hãm hại Trương Tiểu Long, A Liên hy sinh tính mạng để cứu Trương Tiểu Long. Trương Tiểu Long chán nản và biến mất. Vương Thái bị lòng tham làm mờ mắt, trở thành kẻ phản diện và tiếp tục hãm hại Trương Tiểu Long. Trương Tiểu Long gặp phải cái chết bi thảm của bạn gái, sự phản bội của anh em và bị truy nã bởi cả hai phe hắc bạch vì tội giết người. Tuy nhiên, anh không gục ngã mà ngược lại, đối mặt với mọi thứ một cách tích cực. Anh triệu tập những người bạn đồng chí cũ để cùng nhau chiến đấu quyết liệt chống lại thế lực đen tối của Vương Thái.</p>', 'Full', 1, 'single', 'completed', 11, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Giang Nghệ Thăng","avatar":""},{"name":"Bruce","avatar":""},{"name":"Sư Triệu Kỳ","avatar":""},{"name":"Thiêu Phong","avatar":""},{"name":"Siêu Long Lương","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Tough Sniper",