INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rua-moi-nhuc-xua', 'Rửa Mối Nhục Xưa', 'A Frozen Rage', 'https://phimimg.com/upload/vod/20260208-1/7ff019eb68219c7293a4acf59c16bbbf.jpg', 'https://phimimg.com/upload/vod/20260208-1/61687605e7ab87d81cca0fe6128ce577.jpg', '<p>Trong vụ tai nạn 15 năm trước, người anh cả hèn nhát bất lực nhìn chiếc xe gây tai nạn bỏ trốn, khiến em trai bị tàn tật. Khi anh cả tình cờ phát hiện người đứng đầu băng đảng trộm cắp xăng dầu là tài xế gây tai nạn năm đó, một vụ việc bất ngờ đã cuốn anh vào cuộc xung đột của băng đảng trộm cắp xăng dầu, cuộc đời anh chìm xuống đáy vực. Anh đã dũng cảm đối mặt, tự cứu bản thân và trở thành người hùng trong cuộc chiến chống trộm cắp xăng dầu.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Kiều Sơn","avatar":""},{"name":"Mari","avatar":""},{"name":"Lưu Nhất Di","avatar":""},{"name":"Bao Bối Nhĩ","avatar":""},{"name":"Chu Anh Sướng","avatar":""},{"name":"Paul","avatar":""},{"name":"Phan Bân Long","avatar":""},{"name":"Tu Tu","avatar":""},{"name":"Ngải Lệ Á","avatar":""},{"name":"Vương Nai Tuyển","avatar":""},{"name":"Bân Tử","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324175);
