INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoang-phi-hong-thiet-huyet-thap-tam-di', 'Hoàng Phi Hồng: Thiết Huyết Thập Tam Di', 'Iron Blood Thirteen Aunt (Wong Fei Hung Aunt''s Revenge)', 'https://phimimg.com/upload/vod/20260208-1/4af188aaef1da0a16322c327b7f8b690.jpg', 'https://phimimg.com/upload/vod/20260208-1/cc0f34cd8a6cc3fcdd6d81a55361070e.jpg', '<p>Thời Dân Quốc, nạn buôn người hoành hành ở Quảng Châu. Khi Hoàng Phi Hồng truy tìm hung thủ để trừ gian diệt ác, anh đã liều mình bảo vệ dì Thập Tam và mất tích trong tình huống không rõ sống chết. Để tìm ra sự thật, dì Thập Tam đã giả làm gián điệp, thâm nhập vào sào huyệt đứng sau vụ buôn người – một ngôi trường do người phương Tây điều hành. Sau khi điều tra, dì Thập Tam phát hiện ra một âm mưu lớn hơn! Cuối cùng, cô cùng các nữ sinh đoàn kết, hợp sức đánh bại thế lực tà ác đến từ phương Tây.</p>', 'Full', 1, 'single', 'completed', 15, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Đỗ Minh","avatar":""},{"name":"Nam Thăng","avatar":""},{"name":"Đỗ Vũ Hàng","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Huang Fei Hong Zhi Tie Xue Shi San Yi","Huang Fei-Hong and 13th Aunt","Once Upon a Time in China","황비홍: 철혈십삼이","黄飞鸿之铁血十三姨"]', 1784690324175);
