INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-quai-vat-phan-1', 'Trò Chơi Quái Vật (Phần 1)', 'Beast Games (Season 1)', 'https://phimimg.com/upload/vod/20241220-1/f628cd8015b95b3e91144bca8db2e095.jpg', 'https://phimimg.com/upload/vod/20241220-1/e9c519a694573b1596b962e36d902c64.jpg', '<p>Chúng tôi đã tập hợp 1000 người để tranh giành 5.000.000 USD, giải thưởng tiền mặt LỚN NHẤT trong lịch sử truyền hình! Chúng tôi cũng sẽ tặng một hòn đảo tư nhân, những chiếc Lamborghini và hàng triệu tiền mặt khác trong suốt cuộc thi! Hãy xem để xem chương trình tuyệt vời nhất từng được thực hiện!</p>', 'Hoàn Tất (10/10)', 10, 'tvshows', 'completed', 21, 2024, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jimmy Donaldson","avatar":""},{"name":"Chandler Hallow","avatar":""},{"name":"Karl Jacobs","avatar":""},{"name":"Nolan Hansen","avatar":""},{"name":"Tareq Salameh","avatar":""},{"name":"Mack Hopkins","avatar":""},{"name":"Sean Klitzner","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Beast Games: Forte vs. Esperto","משחקי הביסט","משחקי ביסט","بازی‌های مستر بیست","Игры Мистера Биста","Beast Games: Strong vs Smart","Beast Games: Strong vs. Smart","Beast Games 2: Strong vs Smart","Beast Games"]', 1784690324175);
