INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luat-su-lincoln-phan-3', 'Luật Sư Lincoln (Phần 3)', 'The Lincoln Lawyer (Season 3)', 'https://phimimg.com/upload/vod/20260206-1/0d3dcd3e8ce6535296975321e42c6523.jpg', 'https://phimimg.com/upload/vod/20260206-1/17c6e3068fe7eb29a1d7bdb143bcf46d.jpg', '<p>Là một luật sư bào chữa tài ba ở Los Angeles, Mickey Haller sẽ tìm mọi cách để chiến thắng trong khi xoay xở với hệ thống tư pháp hình sự trên chiếc xe Lincoln đặc trưng của mình.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Manuel Garcia-Rulfo","avatar":""},{"name":"Becki Newton","avatar":""},{"name":"Angus Sampson","avatar":""},{"name":"Jazz Raycole","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Адвокат на Лінкольні","The Lincoln Lawyer"]', 1784690324175);
