INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-phong-pha-lang', 'Trường Phong Phá Lãng', 'War Of Faith', 'https://phimimg.com/upload/vod/20260206-1/1cac4a7c5c27f6d67fc8e625efa3b5cd.jpg', 'https://phimimg.com/upload/vod/20260206-1/83fd25f25bad79b1117cbc07cbd0756f.jpg', '<p>Bộ phim này kể về câu chuyện của Ngụy Nhược Lai (do Vương Nhất Bác thủ vai), là một thiên tài tài chính là nhân viên cấp thấp của Ngân hàng Trung ương Quốc Dân Đảng từ năm 1929 đến năm 1934. Nhược Lai là đệ tử của cố vấn cấp cao Thẩm Đồ Nam (do Vương Dương thủ vai). Sống trong thời buổi khó khăn, do dự không biết nên lựa chọn con đường nào, thì anh gặp em gái của Thẩm Tú Nam - Đảng viên Đảng Cộng sản Thẩm Cận Chân (do Lý Thấm thủ vai). Do chịu ảnh hưởng từ cô, anh dần dần thiết lập niềm tin cộng sản của mình và trở thành một nhà tài chính nắm quyền dẫn đầu mặt trận tài chính của Đảng.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 12, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Nhất Bác","avatar":""},{"name":"Lý Thấm","avatar":""},{"name":"Vương Dương","avatar":""},{"name":"Trương Hải Kiệt","avatar":""},{"name":"Lý Trường Cần","avatar":""},{"name":"Lưu Quân","avatar":""},{"name":"Tôn Tử Nam","avatar":""},{"name":"Quan Vân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["长风破浪","ZhuiFengZhe","В погоне за ветром","Тот, за кем следуют","War of Faith","追风者"]', 1784690324175);
