INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('truong-phong-pha-lang', 'Trường Phong Phá Lãng', 'War Of Faith', 'trường phong phá lãng war of faith vương nhất bác lý thấm vương dương trương hải kiệt lý trường cần lưu quân tôn tử nam quan vân 长风破浪 zhuifengzhe в погоне за ветром тот, за кем следуют war of faith 追风者', '');
