INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-phien-dich-cua-chung-toi', 'Người Phiên Dịch Của Chúng Tôi', 'Our Interpreter', 'https://phimimg.com/upload/vod/20260206-1/3e2d9c91e3038a994abbafec72d731e9.jpg', 'https://phimimg.com/upload/vod/20260206-1/372d81fc6ea888a50da70804c417a674.jpg', '<p>Người Phiên Dịch Của Chúng Tôi là câu chuyện tình &quot;gương vỡ lại lành&quot; giữa nữ phiên dịch viên tài năng Lâm Tây và chàng người yêu cũ Tiêu Nhất Thành. Họ từng yêu nhau nhưng vì lý do bất đắc dĩ, Lâm Tây phải nói lời chia tay. Nhiều năm sau, vì công việc, hai người một lần nữa gặp lại và thường xuyên phải tiếp xúc với nhau. Ngoài mặt luôn tỏ ra cay nghiệt với Lâm Tây, nhưng liệu Nhất Thành đã thực sự quên được tình cảm ngày xưa giữa hai người hay chưa?</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 12, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Tinh Húc","avatar":""},{"name":"Tống Thiến","avatar":""},{"name":"Phí Khiêm Minh","avatar":""},{"name":"Lâm Tử Lộ","avatar":""},{"name":"Vu Sa Sa","avatar":""},{"name":"Vương Sâm","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wo Men De Fan Yi Guan","Our Interpreter","我们的翻译官"]', 1784690324175);
