INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-ta-se-ket-hon-that-sao', 'Chúng Ta Sẽ Kết Hôn Thật Sao', '365 Days To The Wedding', 'https://phimimg.com/upload/vod/20260206-1/ec226fa000051757a697acd1b23b14d0.jpg', 'https://phimimg.com/upload/vod/20260206-1/f39cd1d393b7034c175836253abd14b0.jpg', '<p>Takuya và Rika cùng làm việc tại một công ty du lịch ở Tokyo. Cả hai đều là những người hướng nội và đang tận hưởng cuộc sống độc thân hạnh phúc. Tuy nhiên, công ty của họ sắp mở một chi nhánh mới tại Alaska vào năm tới, và những nhân viên chưa lập gia đình sẽ bị ưu tiên điều động đi làm việc tại đó.&nbsp; Để tránh việc phải chuyển đi xa, dù trước đó hầu như chưa từng nói chuyện với nhau, họ đã quyết định lập một kế hoạch táo bạo: giả vờ đính hôn. Liệu hai đồng nghiệp trầm lặng này có thể trở thành một cặp đôi thuyết phục trong mắt mọi người hay không?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kentaro Kumagai","avatar":""},{"name":"Saori Hayami","avatar":""},{"name":"Ami Koshimizu","avatar":""},{"name":"Fukushi Ochiai","avatar":""},{"name":"Kana Asumi","avatar":""},{"name":"Haruki Ishiya","avatar":""},{"name":"Kentaro Tone","avatar":""},{"name":"Jouji Nakata","avatar":""},{"name":"Nao Toyama","avatar":""},{"name":"Fairouz Ai","avatar":""},{"name":"Tessyo Genda","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["听说你们要结婚","聽說你們要結婚","真的要结婚吗","你们还真就结婚啦？","Kekkon Surutte, Hontou desu ka?","Kekkon Surutte, Hontō desu ka?","Kekkon Suru Tte Hontou Desu Ka 365 Days To The Wedding","Sham Marrage Or Not","Kekkon Surutte, Hontou Desuka","แต่งงานที่ว่านี่เรื่องจริงเหรอครับ?","365 днів до весілля","Are You Really Getting Married?","結婚するって、本当ですか"]', 1784690324175);
