INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('moi-luc-moi-noi-phan-4', 'Mọi Lúc Mọi Nơi (Phần 4)', 'Whenever Possible (Season 4)', 'https://phimimg.com/upload/vod/20251223-1/cc8b6c9e7727861e175d5ee2792226cb.jpg', 'https://phimimg.com/upload/vod/20251223-1/d785ae77fc1868d2810d3e7cc6b6694d.jpg', '<p>&quot;Whenever Possible&quot; là chương trình tạp kỹ nơi các MC Yoo Jae Suk và Yoo Yeon Seok đến thăm những người bình thường trong những khoảnh khắc rảnh rỗi ngắn ngủi của họ, với mong muốn mang đến một chút may mắn cho cuộc sống của họ. Chương trình là sự hợp tác giữa PD Choi Bo Pil của &quot; Running Man &quot; và biên kịch Chae Jin Ah của &quot;Siren: Survive the Island&quot;.</p>', 'Tập 6', 10, 'tvshows', 'ongoing', 21, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yoo Jae-suk","avatar":""},{"name":"Yoo Yeon-seok","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Kapanpun memungkinkan.","틈만나면,","틈만 나면,","Whenever Possible","只要有空，"]', 1784690324176);
