INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguyen-toi-nguon-goc-toi-loi', 'Nguyên Tội (Nguồn Gốc Tội Lỗi)', 'Original Sin', 'https://phimimg.com/upload/vod/20260131-1/2bc0fa1aaa79adecff3b572fdc1d981b.jpg', 'https://phimimg.com/upload/vod/20260131-1/43eecb5bdb74e99b593fbcee898b7cf9.jpg', '<p>Bộ phim kể về câu chuyện của Đới Dữ – một bác sĩ pháp y không dám tháo găng tay, và Trịnh Minh – một cảnh sát hình sự không dám nổ súng. Hai người hợp tác đấu tranh với tội phạm, cùng nhau trưởng thành qua từng vụ án.&nbsp; Dưới đáy hồ bất ngờ xuất hiện thi thể một người phụ nữ không đầu. Nhân chứng duy nhất sau khi phát hiện chiếc đầu bị mất tích lại biến mất một cách bí ẩn. Khi cảnh sát vất vả truy tìm tung tích nhân chứng, họ lại phát hiện thêm một bộ hài cốt đã tồn tại nhiều năm.&nbsp; Một nữ sinh viên đại học thiệt mạng trong chuyến leo núi đêm, những người bạn đi cùng ai nấy đều mang trong lòng âm mưu riêng. Hung thủ đánh tráo sự thật, gây ra một vụ thảm án đẫm máu. Tên cầm đầu đường dây buôn bán nội tạng bị người khác móc mất quả thận, và quả thận biến mất ấy lại bất ngờ xuất hiện trong cơ thể của một nạn nhân khác.&nbsp; Kẻ thủ ác chặt ngón tay để giết người cướp của, trong khi đứa con trai đang nằm trên giường bệnh cận kề cái chết. Đới Dữ lao mình xuống sông cứu người, nhưng cô gái được cứu không lâu sau lại bị nghi tự sát. Tại hiện trường vụ án, hai nghi phạm có ngoại hình giống hệt nhau bất ngờ xuất hiện.&nbsp; Một cô gái mù trúng độc kịch liệt rồi bị phân xác, nghi phạm bắt đầu đếm ngược kỳ quái, từng bước dẫn Đới Dữ rơi vào cạm bẫy. Trong khoảnh khắc sinh tử, Trịnh Minh lại bất ngờ nổ súng bắn về phía Đới Dữ.</p>', 'Hoàn Tất (25/25)', 25, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Hạo Hiên","avatar":""},{"name":"Trần Hoàn","avatar":""},{"name":"Tiền Vịnh Thần","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Yuan Zui","原罪2","原罪"]', 1784690324176);
