INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lieu-phap-su-that-phan-2', 'Liệu Pháp Sự Thật (Phần 2)', 'Shrinking (Season 2)', 'https://phimimg.com/upload/vod/20260129-1/0792357ad00cc5d6a2a5c7da66711256.jpg', 'https://phimimg.com/upload/vod/20260129-1/e14ef37ec5c1f1939eb7c2025a0db740.jpg', '<p>Jimmy đang vật lộn để vượt qua nỗi đau mất vợ trong khi vẫn phải làm cha, làm bạn và làm nhà trị liệu. Anh quyết định thử cách tiếp cận mới với mọi người: thẳng thắn không kiêng nể. Liệu điều đó có khiến mọi chuyện trở nên tốt hơn — hay sẽ gây ra hỗn loạn?</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jason Segel","avatar":""},{"name":"Harrison Ford","avatar":""},{"name":"Jessica Williams","avatar":""},{"name":"Luke Tennie","avatar":""},{"name":"Michael Urie","avatar":""},{"name":"Lukita Maxwell","avatar":""},{"name":"Christa Miller","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["诊疗中","诚实诊疗室","Terapia sin filtro","שרינקינג","シュリンキング 悩めるセラピスト","Мозгоправство","Shrinking"]', 1784690324176);
