INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lieu-chu-ky', 'Liễu Chu Ký', 'Are You The One', 'https://phimimg.com/upload/vod/20260126-1/77f7083cb564a4c050b9de49d060e21b.jpg', 'https://phimimg.com/upload/vod/20260126-1/d76dce390859b6e1e3b503a8ada22096.jpg', '<p>Bộ phim kể về câu chuyện tình yêu &quot;mèo vờn chuột&quot; giữa vị vương gia xảo quyệt, bụng dạ khó lường Thôi Hành Chu và nữ trại chủ thông minh, tinh quái Liễu Miên Đường. Thôi Hành Chu được giao nhiệm vụ tiêu diệt đám cướp ở Ngưỡng Sơn, trong một lần tình cờ đã cứu mạng Liễu Miên Đường - người chưa từng gặp nhưng lại chính là kẻ thù đáng gờm của mình và lại tưởng nhầm rằng cô là thiếp được yêu chiều của thủ lĩnh Ngưỡng Sơn. Sau khi trọng thương và tỉnh dậy, Liễu Miên Đường mất đi một phần ký ức và nhận nhầm Thôi Hành Chu là &quot;phu quân&quot; của mình, Thôi Cửu. Thôi Hành Chu tương kế tựu kế, giả làm Thôi Cửu - một thương nhân thất bại, chán nản và đóng giả thành phu thê với cô. Không ngờ dù mất trí nhớ và phải trở thành một nữ nhân lo liệu chuyện gia đình, Liễu Miên Đường vẫn thể hiện sự can đảm và tài trí phi thường của mình khi mở một cửa tiệm đồ sứ và kinh doanh rất phát đạt.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 28, 2024, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Vãn Ý","avatar":""},{"name":"Vương Sở Nhiên","avatar":""},{"name":"Lưu Lệnh Tư","avatar":""},{"name":"Thường Hoa Sâm","avatar":""},{"name":"Trương Thỉ","avatar":""},{"name":"Viên Vũ Huyên","avatar":""},{"name":"Lại Nghệ","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Você é o Único","A Pessoa Prometida","Liu Zhou Ji","Jiao Cang","娇藏","ซ่อนรักชายาลับ","Liu Zhou Story","Hidden Charm","Are You the One","柳舟记"]', 1784690324176);
