INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lieu-chu-ky', 'Liễu Chu Ký', 'Are You The One', 'liễu chu ký are you the one trương vãn ý vương sở nhiên lưu lệnh tư thường hoa sâm trương thỉ viên vũ huyên lại nghệ você é o único a pessoa prometida liu zhou ji jiao cang 娇藏 ซ่อนรักชายาลับ liu zhou story hidden charm are you the one 柳舟记', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giua-con-bao-tuyet', 'Giữa Cơn Bão Tuyết', 'Amidst A Snowstorm Of Love', 'https://phimimg.com/upload/vod/20260126-1/b8bafa0d2e3e0f1d6dc36ddcc8868f43.jpg', 'https://phimimg.com/upload/vod/20260126-1/93eb0168e1ba7f3d070ebb1a6f0fcab7.jpg', '<p>Lâm Diệc Dương - cựu cơ thủ bida thiên tài và Ân Quả - cơ thủ 9 bi đang nổi gặp nhau vào một đêm bão tuyết hiếm gặp mười năm mới có một lần. Được sự giúp đỡ của em họ Ân Quả, hai người dần thân quen, Ân Quả cũng hiểu được quá khứ của Lâm Diệc Dương. Thì ra Lâm Diệc Dương cũng từng là thiên tài bida chấn động một thời, trong một trận đấu, anh bị cấm thi vì không đồng tình với quyết định của trọng tài và vô tình xảy ra va chạm trong lúc phân bua với trọng tài. Anh trẻ tuổi cao ngạo nên không chấp nhận hình phạt, trực tiếp tuyên bố giải nghệ, từ đó rút khỏi sự nghiệp bida mà mình luôn tự hào. Sự xuất hiện của Ân Quả làm quỹ đạo cuộc đời của Lâm Diệc Dương một lần nữa đổi hướng, Lâm Diệc Dương không những bắt đầu cố gắng theo đuổi Ân Quả, mà dưới tác động của Ân Quả, anh tìm lại ước mơ ban đầu, quay lại đấu trường bida.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 17, 2024, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngô Lỗi","avatar":""},{"name":"Triệu Kim Mạch","avatar":""},{"name":"Vương Tinh Việt","avatar":""},{"name":"Đinh Tiếu Huỳnh","avatar":""},{"name":"Trần Tĩnh Khả","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["No Meio de Uma Tempestade de Neve de Amor","在暴雪時分","Amidst a Snowstorm of Love","在暴雪时分"]', 1784690324176);
