INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('toi-se-do-het-moi-thu-nguoi-manh-nhat-the-gioi-voi-hieu-lam-nguoc-doi-muon-lam-mao-hiem-gia', 'Tôi Sẽ Đỡ Hết Mọi Thứ: Người Mạnh Nhất Thế Giới Với Hiểu Lầm Ngược Đời Muốn Làm Mạo Hiểm Giả', 'I Parry Everything', 'tôi sẽ đỡ hết mọi thứ: người mạnh nhất thế giới với hiểu lầm ngược đời muốn làm mạo hiểm giả i parry everything daiki hamano ryoko maekawa nanako mori jin yamanoi junta terashima shin-ichiro miki kenta miyake megumi toyoguchi toshihiko seki hidenari ugaki wataru hatano 我要招架一切 要招架一切 反误解的世界最强想成为冒险者 我要【招架】一切～反误解的世界最强想成为冒险家 ore wa subete o "parry" suru: gyaku kanchigai no sekai saikyou wa boukensha ni narita ore wa subete o "parry" suru: gyaku kanchigai no sekai saikyō wa bōken-sha ni naritai ore wa subete wo parry suru gyaku kanchigai no sekai saikyou wa boukensha ni naritai ore wa subete wo parry suru 俺は全てを【パリイ】する 나는 모든 것을 패리 한다 i parry everything to become the greatest adventure! i parry everything: what do you mean i''m the strongest? i''m not even an adventurer yet! người mạnh nhất thế giới với hiểu lầm ngược đời muốn làm mạo hiểm giả tôi sẽ đỡ hết mọi thứ 俺は全てを【パリイ】する〜逆勘違いの世界最強は冒険者になりたい〜', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lisa-frankenstein-va-nguoi-tinh-hoi-sinh-cuoc-tinh-xac-song', 'Lisa Frankenstein Và Người Tình Hồi Sinh (Cuộc Tình Xác Sống)', 'Lisa Frankenstein', 'https://phimimg.com/upload/vod/20260123-1/09aa6ccac0fd0eb38fea7cafdd1ccb3a.jpg', 'https://phimimg.com/upload/vod/20260123-1/a7af718784d682b870c644aa2b5c7996.jpg', '<p>Đặt trong năm 1989, câu chuyện tập trung vào Lisa (Kathryn Newton), một học sinh trung học sống với cha (Joe Chrest), mẹ kế (Carla Gugino) và em gái kế Taffy (Liza Soberano), nhưng thích dành thời gian ở nghĩa địa địa phương giữa những mảnh đá tombstone. &nbsp;Mặc dù cô ấy thích chàng biên tập trưởng của tạp chí văn học của trường (Henry Eikenberry), Lisa sớm tìm thấy tình yêu thực sự của mình – tại nghĩa địa – khi một xác chết (Cole Sprouse của Riverdale) sống lại. Anh ấy không nói và khóc nước mắt mùi nôn. Tuy nhiên, giấu anh ta ở nhà trong tủ quần áo của mình, Lisa đắm chìm – và trở nên như vậy khi mọi thứ trở nên ngày càng kinh dị hơn.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kathryn Newton","avatar":""},{"name":"Cole Sprouse","avatar":""},{"name":"Liza Soberano","avatar":""},{"name":"Henry Eikenberry","avatar":""},{"name":"Joe Chrest","avatar":""},{"name":"Carla Gugino","avatar":""},{"name":"Joey Harris","avatar":""},{"name":"Bryce Romero","avatar":""},{"name":"Jenna Davis","avatar":""},{"name":"Joshua Montes","avatar":""},{"name":"Trina LaFargue","avatar":""},{"name":"Paola Andino","avatar":""},{"name":"Jennifer Pierce Mathus","avatar":""},{"name":"Luke Sexton","avatar":""},{"name":"Chris Greening","avatar":""},{"name":"Mae Anglim","avatar":""},{"name":"Ayla Miller","avatar":""},{"name":"Jai","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Lisa Frankenstein"]', 1784690324176);
