INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sat-thu-mat-danh-13', 'Sát thủ mật danh 13', 'The Shadow Strays', 'sát thủ mật danh 13 the shadow strays aurora ribero hana malasan andri mashadi adipati dolken kristo immanuel ali fikry taskya namya arswendy bening swara chew kin-wah agra piliang daniel eka putra tanta ginting yayan ruhian eva celia mawar eva de jongh hiroaki kato nobuyuki s the shadow strays fuera de las sombras codename 13 відступна тінь asi̇ 13 nume de cod 13 섀도우의 13 l''ombre rebelle ze stínů سایه‌های سرگردان سایه‌گردها блуждающая тень através das sombras', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('danh-tieng-gia-toc-2', 'Danh Tiếng Gia Tộc 2', 'The Heir To The Throne', 'https://phimimg.com/upload/vod/20260116-1/fd791850d4d58395cb8e8ec67a372f5c.jpg', 'https://phimimg.com/upload/vod/20260116-1/e1b2b375d02c6b1d0e58dc3ac31e5137.jpg', '<p>Chủ tịch Khâu Hàn Dương (Lưu Giang) với tư tưởng trọng nam khinh nữ giao công ty cho con trai thứ là Khâu Thủ Nghĩa (La Gia Lương) làm phó chủ tịch, cháu trai duy nhất là Khâu Trí Bân (La Tử Dật) làm CEO. Con trai trưởng của ông Dương là Khâu Thủ Nhân (Hứa Thiệu Hùng) không màng danh lợi, chỉ muốn an phận nên con gái Nhân là Khâu Hạo Nhi (Xa Thi Mạn) không được trọng dụng. Ông Dương bị tai biến &amp; hôn mê. Trước đó, ông ủy quyền giao chức chủ tịch cho Khâu Hạo Nhi nên gia đình ông Nghĩa luôn tìm cách đối phó Nhi. May mắn thay, Nhi có bạn trai cũ là đại luật sư Cao Tuấn (Lâm Phong) giúp đỡ. Tuấn vẫn còn tình cảm với Nhi. Em cùng cha khác mẹ của Bân là chị em song sinh Khâu Chỉ Lam (Lương Tịnh Kỳ) suốt ngày ăn chơi và nữ luật sư Khâu Chỉ Đồng (Trần Oánh). Lam yêu thầm Tuấn nhiều năm. Lúc này, Nhi phát hiện thân phận thực sự của Bân. Nhưng ông Dương đột nhiên qua đời, để lại sản nghiệp cho cha con Khâu Thủ Nghĩa và Khâu Trí Bân. Cuộc chiến tranh giành quyền lực của gia tộc hào môn bắt đầu.</p>', 'Hoàn Tất (30/30)', 30, 'series', 'completed', 22, 2024, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Xa Thi Mạn","avatar":""},{"name":"Lâm Phong","avatar":""},{"name":"Him Law","avatar":""},{"name":"Hứa Thiệu Hùng","avatar":""},{"name":"Lương Minh Nhiên","avatar":""},{"name":"Trần Ứng","avatar":""},{"name":"Vương Mẫn Dịch","avatar":""},{"name":"Hoàng Hạo Nhiên","avatar":""},{"name":"Kiều Tĩnh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c