INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-ve-nam-1997', 'Trở Về Năm 1997', 'Once Again', 'https://phimimg.com/upload/vod/20260112-1/1c6eab5cd0bb94f587d07b330d15d892.jpg', 'https://phimimg.com/upload/vod/20260112-1/1c850d6e9074fd706c6f739076566b36.jpg', '<p>Ở tuổi 40, diễn viên đóng thế Woo-seok luôn khao khát được quay trở lại thời kỳ đỉnh cao năm 1997, trước khi vết sẹo trên mặt chấm dứt giấc mơ diễn xuất của anh. Một ngày nọ, anh mua năm lá bùa từ một nhà sư vô danh với hy vọng thay đổi cuộc đời. Thế nhưng trong một buổi quay phim, một tai nạn xe hơi đã đưa anh trở về năm 1997, thời trung học của mình. Giờ đây, sống lại trong thân xác cậu học sinh năm xưa, Woo-seok bắt tay vào “cải tạo” quá khứ đầy sai lầm của mình, với tư cách một người con, người chồng và người cha từng khiến gia đình khổ sở.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Cho Byeong-kyu","avatar":""},{"name":"Han Eun-su","avatar":""},{"name":"Koo Jun-hoe","avatar":""},{"name":"Choi Hui-seung","avatar":""},{"name":"Park Cheol-min","avatar":""},{"name":"Lee Mi-do","avatar":""},{"name":"Kim Da-hyun","avatar":""},{"name":"Kim Hyung-suk","avatar":""},{"name":"Kim Nu-ri","avatar":""},{"name":"Kim Kyeol","avatar":""},{"name":"Seo Hye-won","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Once Again Even if I Die","Even If I Die Once Again","Again 1997","어게인 1997"]', 1784690324176);
