INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-quy-nhi-ma-thu-ba-takagi-treu-roi-yeu', 'Nhất Quỷ Nhì Ma, Thứ Ba Takagi: Trêu Rồi Yêu', 'Teasing Master Takagi-san', 'https://phimimg.com/upload/vod/20260110-1/ade0f69bbef4f4ffbf96d4b6e7d79419.jpg', 'https://phimimg.com/upload/vod/20260110-1/ddc421e82c6a035af9c7f2a95ab305b1.jpg', '<p>Bản điện ảnh từ loạt truyện manga cùng tên, vốn gây ấn tượng với độc giả về những trò nghịch ngợm tuổi học trò của Takagi và cậu bạn Nishikita. Lấy bối cảnh 10 năm sau khi cả hai đã trưởng thành, bộ đôi Takagi - Nishikata sẽ có màn thả thính cực ngọt cùng lời tỏ tình vụng dại hứa hẹn làm xiêu lòng khán giả ngay trên màn ảnh rộng.</p>', 'Full', 1, 'single', 'completed', 30, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 1, '[{"name":"Mei Nagano","avatar":""},{"name":"Fumiya Takahashi","avatar":""},{"name":"Jin Suzuki","avatar":""},{"name":"Yuna Taira","avatar":""},{"name":"Oshirō Maeda","avatar":""},{"name":"Sara Shida","avatar":""},{"name":"Tamaki Shiratori","avatar":""},{"name":"Jun Saito","avatar":""},{"name":"Yosuke Eguchi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"}]', '["Karakai Jōzu no Takagi-san","Karakai Jouzu no Takagi-san","擅长捉弄的高木同学 真人电影","แกล้งนัก (รัก) นะรู้ยัง?","Teasing Master Takagi-san Movie","からかい上手の高木さん"]', 1784690324176);
