INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-nhan-chi-ha-tu-thiet-trong-hien-movie', 'Nhất Nhân Chi Hạ : Tú Thiết Trọng Hiện (Movie)', 'Hitori no Shita - The Outcast - Rust Iron Returns', 'https://phimimg.com/upload/vod/20260110-1/0135ae043b06d7834f8f170fb846f4e3.jpg', 'https://phimimg.com/upload/vod/20260110-1/e1387ac02d195d8b3c859c23af57fb2b.jpg', '<p>Trương Sở Lam và Phùng Bảo Bảo được công ty Đâu Cũng Được phái đi làm 1 nhiệm vụ đặc biệt: hộ tống 1 bảo đao cổ Điệt Hoàn đến biên giới, hoàn thành ước định mấy chục năm với nhà&nbsp; Ishikawa Doanh quốc. 2 người sẽ phải đối mặt với đồng đội xa lạ, hoàn cảnh ác liệt của mùa đông phía Bắc và cả cường địch lúc nào cũng chăm chăm cướp đao. 1 trận chiến bảo vệ Điệt Hoàn ở nhà Ishikawa sắp bắt đầu…</p>', 'Full', 1, 'hoathinh', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yuntu Cao","avatar":""},{"name":"Xiao Liansha","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["一人之下·锈铁重现","Under One Person - Rust Iron Returns","Yi Ren Zhi Xia: Xiu Tie Chong Xian","The Outcast : Rust Iron Returns","一人之下锈铁重现","Hitori no Shita","Yi Ren Zhi Xia: Xiutie Chongxian","Yi Ren Zhi Xia Juchang Ban: Xuetie Pian","一人之下剧场版：锈铁篇"]', 1784690324176);
