INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-doa-anh-tuc-do', 'Những Đoá Anh Túc Đỏ', 'Red Poppies', 'https://phimimg.com/upload/vod/20250602-1/d0e119388cac132b37d6ff92a429dd75.jpg', 'https://phimimg.com/upload/vod/20250602-1/e2d6dbbf390095540d96e477a0567d8c.jpg', '<p>Trong bối cảnh khốc liệt của Thế chiến II, cậu bé mồ côi Jędrek trốn khỏi trại cải tạo Liên Xô và gia nhập Quân đoàn II Ba Lan. Tại chiến trường Monte Cassino, cậu gặp Pola – một nữ y tá quả cảm. Giữa bom đạn, họ tìm thấy hy vọng, tình yêu và lý tưởng sống. Red Poppies là câu chuyện cảm động về tuổi trẻ, sự hy sinh và lòng dũng cảm giữa những tàn phá của chiến tranh.</p>', 'Full', 1, 'single', 'completed', 31, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Ba Lan', 0, '[{"name":"Nicolas Przygoda","avatar":""},{"name":"Leszek Lichota","avatar":""},{"name":"Michał Żurawski","avatar":""},{"name":"Magdalena Żak","avatar":""},{"name":"Szymon Piotr Warszawski","avatar":""},{"name":"Mateusz Banasiuk","avatar":""},{"name":"Dariusz Toczek","avatar":""},{"name":"Bartłomiej Topa","avatar":""},{"name":"Łukasz Garlicki","avatar":""},{"name":"Radosław Pazura","avatar":""},{"name":"Zbigniew Stryj","avatar":""},{"name":"Karol Wróblewski","avatar":""},{"name":"Mark Kitto","avatar":""},{"name":"Andrzej Mastalerz","avatar":""},{"name":"Jacek Pluta","avatar":""},{"name":"J","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["Czerwone maki"]', 1784690324176);
