INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-than', 'Hỏa Thần', 'Firefighters / The Siren', 'https://phimimg.com/upload/vod/20250416-1/c0c07f999a762a47561292515bb7b05a.jpg', 'https://phimimg.com/upload/vod/20250416-1/96f9411e83de73829a71574cedb14ed5.jpg', '<p>Đội cứu hoả khu Tây Seoul luôn phải làm việc trong điều kiện thiếu thốn và khắc nghiệt. Ngày nào họ cũng phải lặp lại câu hỏi: đây có phải là lần làm nhiệm vụ cuối cùng? Phải tập trung cứu người hay bảo vệ mạng sống của chính mình? Một ngày, đường dây khẩn báo động về một đám cháy tại Hongje-dong. Ngay lập tức, cả đội cảm nhận được sự nghiêm trọng của tình hình…</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 1, '[{"name":"Joo Won","avatar":""},{"name":"Kwak Do-won","avatar":""},{"name":"Yoo Jae-myung","avatar":""},{"name":"Lee You-young","avatar":""},{"name":"Kim Min-jae","avatar":""},{"name":"Oh Dae-hwan","avatar":""},{"name":"Lee Jun-hyuk","avatar":""},{"name":"Jang Young-nam","avatar":""},{"name":"Hwang Sung-joon","avatar":""},{"name":"Heo Jin","avatar":""},{"name":"Hong Sang-pyo","avatar":""},{"name":"Seo Min-ju","avatar":""},{"name":"Han Jae-woong","avatar":""},{"name":"Kwak Young-sin","avatar":""},{"name":"Heo Seung","avatar":""},{"name":"Lee Min-seong","avatar":""},{"name":"Lee Yong-i","avatar":""},{"name":"Jeong Jong-jun","avatar":""},{"name":"Jeong Gi-","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["FIREFIGHTERS","消防员","烈火救援","消防官","Infierno en la torre","소방관"]', 1784690324176);
