INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-thien-tai-phan-7', 'Bác Sĩ Thiên Tài (Phần 7)', 'The Good Doctor (Season 7)', 'https://phimimg.com/upload/vod/20240930-1/5c77da3e1e65c9b128dc88bef5b6a4fb.jpg', 'https://phimimg.com/upload/vod/20260104-1/b078940019ca5b2b1b35d3c98c05d66a.jpg', '<p>Một bác sĩ phẫu thuật tài năng tự kỷ và mắc cả hội chứng bác học đến làm ở một bệnh viện danh tiếng, nơi anh gặp phải sự hoài nghi từ cả bệnh nhân và các đồng nghiệp.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Freddie Highmore","avatar":""},{"name":"Fiona Gubelmann","avatar":""},{"name":"Will Yun Lee","avatar":""},{"name":"Christina Chang","avatar":""},{"name":"Paige Spara","avatar":""},{"name":"Bria Samoné Henderson","avatar":""},{"name":"Noah Galvin","avatar":""},{"name":"Chuku Modu","avatar":""},{"name":"Richard Schiff","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Le bon docteur","好医生","Dobrý doktor","Good Doctor","Ο Καλός Γιατρός","Good doctor","The Good Doctor","İyi Doktor","Хороший лікар"]', 1784690324176);
