INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-dua-mf-ghost-phan-2', 'Giải Đua MF Ghost (Phần 2)', 'MF Ghost (Season 2)', 'https://phimimg.com/upload/vod/20260102-1/0dda48177f3280a5f12f1fd3ffff413d.jpg', 'https://phimimg.com/upload/vod/20260102-1/2960d454652827f1f89fcc5e19ef17e1.jpg', '<p>Trong vòng thi ở hồ Ashi, tay đua thiên tài Katagiri Kanata cùng với chiếc Toyota 86 tiếp tục có màn trình diễn bùng nổ tại giải MF Ghost (MFG). Nếu hoàn thành vòng thi này, cậu sẽ vươn lên thứ hạng mới khiến những tay đua lão luyện phải dè chừng. Bên cạnh đó, chuyện tình cảm của Kanata với Ren - thiên thần số bảy xinh đẹp của MFG cũng đang tiến triển theo hướng bất ngờ. Đồng thời, Kanata biết rằng người cha mình đang tìm kiếm, từng sinh sống tại vùng đất này. Qua những dữ liệu từ giới đua xe, liệu cậu có tìm được chút thông tin nào về ông không?</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuma Uchida","avatar":""},{"name":"Ayane Sakura","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["燃油车斗魂","MF Ghost","MF고스트","MFゴースト"]', 1784690324176);
