INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vua-suu-tap-nha-dau-gia-goldin-phan-2', 'Vua Sưu Tập: Nhà Đấu Giá Goldin (Phần 2)', 'King Of Collectibles: The Goldin Touch (Season 2)', 'https://phimimg.com/upload/vod/20251230-1/c1e46b386f03a0df51ae0c175ea4fba8.jpg', 'https://phimimg.com/upload/vod/20251230-1/eb44d55162844cfeff7b36cce9f95ace.jpg', '<p>Ken Goldin cùng đội ngũ tài năng của mình dẫn dắt các hoạt động trong loạt phim này, mang đến cái nhìn cận cảnh bên trong một nhà đấu giá hàng đầu chuyên về các món đồ sưu tầm quý hiếm.</p>', 'Hoàn Tất (8/8)', 8, 'tvshows', 'completed', 16, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["King of Collectibles: The Goldin Touch"]', 1784690324176);
