INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thang-cap-mot-minh', 'Thăng cấp một mình', 'Solo Leveling', 'https://phimimg.com/upload/vod/20251228-1/09c9117969b2202d630d035456b6f6b0.jpg', 'https://phimimg.com/upload/vod/20251228-1/1ea9e68e59a1061cdadaa768314b7b49.jpg', '<p>Thợ săn hạng E Sung Jinwoo là người yếu nhất trong số họ. Bị mọi người coi thường, anh ta không có tiền, không có khả năng nói và không có triển vọng công việc nào khác. Vì vậy, khi nhóm của anh ấy tìm thấy một hầm ngục ẩn giấu, anh ấy quyết tâm sử dụng cơ hội này để thay đổi cuộc sống của mình tốt hơn... nhưng cơ hội mà anh ấy tìm thấy hơi khác so với những gì anh ấy nghĩ trong đầu!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Taito Ban","avatar":""},{"name":"Genta Nakamura","avatar":""},{"name":"Haruna Mikawa","avatar":""},{"name":"Reina Ueda","avatar":""},{"name":"Daisuke Hirakawa","avatar":""},{"name":"Hiroki Touchi","avatar":""},{"name":"Banjo Ginga","avatar":""},{"name":"Makoto Furukawa","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Solo Leveling 2ª Temporada -Ergam-se das Sombras-","我独自升级","我独自升级 第二季 -起于暗影-","我獨自升級","Ore dake Level Up na Ken","俺だけレベルアップな件 Season 2 -Arise from the Shadow-","Ore dake Level Up na Ken Season 2 -Arise from the Shadow-","俺レベ","Na Honjaman Level Up","나 혼자만 레벨 업","나혼자만 레벨업","Na Honjaman Rebeleop","나 혼자만 레벨업 Season 2 -Arise from the Shadow-","나 혼자만 레벨업 -ARISE FROM THE SHADOW-","Поднятие уровня в од