INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thang-cap-mot-minh', 'Thăng cấp một mình', 'Solo Leveling', 'thăng cấp một mình solo leveling taito ban genta nakamura haruna mikawa reina ueda daisuke hirakawa hiroki touchi banjo ginga makoto furukawa solo leveling 2ª temporada -ergam-se das sombras- 我独自升级 我独自升级 第二季 -起于暗影- 我獨自升級 ore dake level up na ken 俺だけレベルアップな件 season 2 -arise from the shadow- ore dake level up na ken season 2 -arise from the shadow- 俺レベ na honjaman level up 나 혼자만 레벨 업 나혼자만 레벨업 na honjaman rebeleop 나 혼자만 레벨업 season 2 -arise from the shadow- 나 혼자만 레벨업 -arise from the shadow- поднятие уровня в одиночку سولو ليفلينغ โซโลเลเวลลิง solo leveling 我獨自升級 第二季 -起於闇影- тільки я візьму новий рівень сезон 2 -повстань із тіні- solo leveling season 2 -arise from the shadow- 俺だけレベルアップな件', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-bong-bat-hao', 'Đội Bóng Bất Hảo', 'You Gotta Believe', 'https://phimimg.com/upload/vod/20251227-1/0d5dc38da35b4e5c7e1de19254d9ee75.jpg', 'https://phimimg.com/upload/vod/20251227-1/3d68eddc61d618b505976370677a18b9.jpg', '<p>Sau khi dành trọn mùa giải để cổ vũ cho người cha đang lâm bệnh của một đồng đội, một nhóm cầu thủ bóng chày nhí không mấy tên tuổi tại Fort Worth đã tạo nên một hành trình &quot;Cinderella&quot; đầy kinh ngạc. Họ thẳng tiến vào giải vô địch thế giới dành cho thiếu nhi năm 2002, mà đỉnh điểm là trận đối đầu phá vỡ mọi kỷ lục và trở thành một trong những trận đấu kinh điển ngay lập tức trên sóng ESPN.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Luke Wilson","avatar":""},{"name":"Greg Kinnear","avatar":""},{"name":"Sarah Gadon","avatar":""},{"name":"Molly Parker","avatar":""},{"name":"Lew Temple","avatar":""},{"name":"Joaquin Roberts","avatar":""},{"name":"Martin Roach","avatar":""},{"name":"Patrick Renna","avatar":""},{"name":"Blake DeLong","avatar":""},{"name":"Justin Adams","avatar":""},{"name":"King Orba","avatar":""},{"name":"Taylor Hunt Wright","avatar":""},{"name":"Ali Hassan","avatar":""},{"name":"Michael Cash","avatar":""},{"name":"Etienne Kellici","avatar":""},{"name":"Nicholas Fry","avatar":""},{"name":"Jacob Mazeral","avatar":""},{"name":"Gavin MacIve","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["You Gotta Believe"]', 1784690324176);
