INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dai-chien-tang-lop-am-thuc-phan-1', 'Đại Chiến Tầng Lớp Ẩm Thực (Phần 1)', 'Culinary Class Wars (Season 1)', 'đại chiến tầng lớp ẩm thực (phần 1) culinary class wars (season 1) paik jong-won sung anh nam doh-hyeong roi choi raymon kim song hoon jung ho-young jennie walldén son jong-won im seong-geun seonjae shin gye-sook hu deok-juk sam kim guerra de cucharas blancas contra negras culinary class wars guerra culinária 黑白厨师：料理阶级战争 무명 요리사 무명요리사 흑백요리사 요리 계급 전쟁 heugbaekyorisa: yori gyegeub jeonjaeng unknown chefs 흑백요리사: 요리 계급 전쟁', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('boi-dem', 'Bơi Đêm', 'Night Swim', 'https://phimimg.com/upload/vod/20251226-1/be03d10c96f9bbc47f6d3453ae605a1f.jpg', 'https://phimimg.com/upload/vod/20251226-1/8010774d40c9bc44444fa6b7295b31e7.jpg', '<p>Từ câu chuyện về cuộc sống gia đình bình thường đã biến thành một nỗi ám ảnh kinh hoàng. Không chạy, không lặn, không cứu hộ và không bơi sau khi màn đêm buông xuống. Bơi Đêm chạm đến nỗi sợ hãi sâu thẳm của bất kỳ ai mỗi khi bước xuống hồ bơi rằng họ sẽ bị mắc kẹt dưới nước.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Wyatt Russell","avatar":""},{"name":"Kerry Condon","avatar":""},{"name":"Amélie Hoeferle","avatar":""},{"name":"Gavin Warren","avatar":""},{"name":"Nancy Lenehan","avatar":""},{"name":"Ellie Araiza","avatar":""},{"name":"Rahnuma Panthaky","avatar":""},{"name":"Eddie Martinez","avatar":""},{"name":"Jodi Long","avatar":""},{"name":"Aivan Uttapa","avatar":""},{"name":"Preston Galli","avatar":""},{"name":"Elijah J. Roberts","avatar":""},{"name":"Ben Sinclair","avatar":""},{"name":"Ayazhan","avatar":""},{"name":"Joziah Lagonoy","avatar":""},{"name":"Liz Parkinson","avatar":""},{"name":"Mike Avery","avatar":""},{"name":"Eleanor","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Águas Negras","שחייה לילית","Нощно плуване","شنای شبانه","Aguas Siniestras","夜泳","暗泳","游夜水","ค่ำคืนอย่าแหวกว่าย","Night Swim"]', 1784690324176);
