INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kiem-lai-phan-1', 'Kiếm Lai (Phần 1)', 'The Swords (Season 1)', 'https://phimimg.com/upload/vod/20251226-1/2a10af9851447b2e9348d01c681e33dc.jpg', 'https://phimimg.com/upload/vod/20251226-1/72f08342b0b4a75a66b6c57c92974c22.jpg', '<p>Trần Bình An từ một thiếu niên vô danh buộc phải gánh lấy sứ mệnh dẫn dắt Lý Bảo Bình cùng đồng hành vượt biên, tìm đường đến nước Tùy xa xôi để nối tiếp học nghiệp còn chưa hoàn thành. Hành trình mở ra giữa non sông rộng lớn, phong cảnh tuy đẹp như tranh, nhưng sát cơ ẩn sâu trong từng bước chân. Thiết kỵ lạnh lùng truy bức không ngừng, yêu tà quỷ mị rình rập trong bóng tối, sinh tử chỉ cách nhau một nhịp thở. Trước gió bụi mịt mờ ấy, Trần Bình An không còn đường lùi, chỉ có thể tiến lên, dùng ý chí và nắm đấm mở lối sinh tồn. Giữa cơn loạn thế, những cường giả giấu tên lần lượt xuất hiện, âm thầm dang tay che chở, cũng đồng thời đẩy chàng vào vòng xoáy sâu hơn của võ đạo và đại cục.</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 7, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Chen Zhangtaikang","avatar":""},{"name":"Chen Hao","avatar":""},{"name":"Yun Wei Yi","avatar":""},{"name":"徐宇隆","avatar":""},{"name":"He Wenxiao","avatar":""},{"name":"Liu Xiaoyu","avatar":""},{"name":"Ling Zhenhe","avatar":""},{"name":"Bai Xuecen","avatar":""},{"name":"Shuxin Wan","avatar":""},{"name":"Li Min","avatar":""},{"name":"Yang Mo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["剑来 动画版","剑来","Jianlai","Jian Lai","The Swords","Sword of Coming"]', 1784690324176);
