INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('con-bao-den-tran-ap-toi-pham', 'Cơn Bão Đen (Trấn Áp Tội Phạm)', 'Black Storm', 'https://phimimg.com/upload/vod/20251226-1/532298a6bed6da806e382e932f7500ec.jpg', 'https://phimimg.com/upload/vod/20251226-1/ef0a7b7cb6bbd70a70eb611cf9ef2027.jpg', '<p>Dân làng Cổ Đại Hạc bị cưỡng chế phá dỡ mộ, sau khi dùng tên thật tố cáo tên cầm đầu băng nhóm tội phạm Ngụy Thiên Lãng thì đột ngột mất tích. Trong thời gian này, em gái của ông cũng bất ngờ qua đời. Đúng lúc Trung ương Đảng Cộng sản Trung Quốc phát động chiến dịch đặc biệt &quot;Trấn áp tội phạm và loại bỏ thế lực đen tối&quot;, đội trưởng đội điều tra hình sự của Sở Công an thành phố là Lôi Dương đã tiến hành điều tra, cuối cùng làm sáng tỏ sự thật và triệt phá hoàn toàn thế lực tội phạm đã tồn tại nhiều năm.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Thích Tiểu Long","avatar":""},{"name":"Bào Bối Nhĩ","avatar":""},{"name":"Lưu Phong Siêu","avatar":""},{"name":"Cao Cường","avatar":""},{"name":"Cao Vệ Mẫn","avatar":""},{"name":"Lý Đại Cường","avatar":""},{"name":"Tần Yến","avatar":""},{"name":"Khúc San San","avatar":""},{"name":"Nhậm Chính Bân","avatar":""},{"name":"Vương Hồng","avatar":""},{"name":"Vương Chính Toàn","avatar":""},{"name":"Triệu Nhân Nhiên","avatar":""},{"name":"Chu Bác","avatar":""},{"name":"Chu Khải Khải","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Da Hei","打黑"]', 1784690324176);
