INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngu-hanh-bi-thuat', 'Ngũ Hành Bí Thuật', 'Five Elements Secret Art (Five Elements)', 'https://phimimg.com/upload/vod/20251226-1/b3382d629fc3b382857b32e0b67caac2.jpg', 'https://phimimg.com/upload/vod/20251226-1/f1b58b19e259f18259907324a8c9f229.jpg', '<p>Người xưa sáng tạo ra Bí thuật Ngũ hành dựa trên nguyên lý tương sinh tương khắc của ngũ hành, đó là năm loại kim, mộc, thủy, hỏa, thổ, hình thành nên năm môn phái tương ứng. Truyền nhân Kim môn lão Dương và con trai Dương Nhất Cân đến trấn Đào Nguyên dấu tên đổi họ sống bằng nghề bán rau và rèn sắt, Dương Nhất Cân muốn ra ngoài lập nghiệp, đóng vai một thiếu niên phóng túng và từng bước phát triển thành hiệp sĩ.Bộ phim mang đậm nét văn hóa Ngũ hành cổ xưa của Trung Quốc, kết hợp với phong cách thẩm mỹ Nhật Bản.</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Gia Hàng","avatar":""},{"name":"Lý Nhược Hy","avatar":""},{"name":"Nhạc Đông Phong","avatar":""},{"name":"Vương Cửu Thắng","avatar":""},{"name":"Hazy Yu","avatar":""},{"name":"King Wang","avatar":""},{"name":"Lưu Minh","avatar":""},{"name":"Dương Tiểu Đan","avatar":""},{"name":"Trương Hân Phong","avatar":""},{"name":"Lưu Di Nhiên","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["五行秘術","五行秘术"]', 1784690324176);
