INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoa-thanh-ca-cong-chua-khac-biet', 'Hoa Thanh Ca (Công Chúa Khác Biệt)', 'Different Princess', 'https://phimimg.com/upload/vod/20251224-1/8b4e61d67b60b4d0005634f69d4bcc97.jpg', 'https://phimimg.com/upload/vod/20251224-1/146865c6722e7d291fe4840032e0763b.jpg', '<p>Phim kể về Hoa Thanh Ca, một nhà văn nữ, xuyên không vào thế giới trong cuốn tiểu thuyết mà mình viết, trở thành nữ phụ. Cô vốn nghĩ nắm trong tay kịch bản thì có thể xoay chuyển tình thế, nào ngờ kế hoạch không thành, từ đó viết nên câu chuyện tình yêu “yêu cho roi cho vọt” với Kỷ Sở.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 12, 2024, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Ireine Song","avatar":""},{"name":"Ding Zeren","avatar":""},{"name":"Zhu Rongjun","avatar":""},{"name":"Sun Zujun","avatar":""},{"name":"Zhang Yuenan","avatar":""},{"name":"Lin Lu","avatar":""},{"name":"Yu Xiaolei","avatar":""},{"name":"Xu Qi","avatar":""},{"name":"Wang Junzhe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Princesas Diferentes","花青歌","Different Princess"]', 1784690324176);
