INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chac-chu-nguoi-anh-em-phan-1', 'Chắc Chứ Người Anh Em (Phần 1)', 'Are You Sure (Season 1)', 'https://phimimg.com/upload/vod/20251225-1/513b83487ad8645ea9e82ed5f5f8a262.jpg', 'https://phimimg.com/upload/vod/20251225-1/9cb24307e423cd760899aa9610e57a2d.jpg', '<p>Are You Sure?! ghi lại hành trình du lịch ngẫu hứng của bộ đôi Jimin và Jungkook, hay còn được gọi là “anh em Busan” vì cả hai cùng đến từ tỉnh Busan. Không có hướng dẫn viên, cả hai tự đưa ra quyết định và “sinh tồn” trong chuyến hành trình du lịch của mình. Chỉ một tuần sau khi cả hai xuất ngũ, Mùa 2 bắt đầu với ngân sách khiêm tốn và một cuốn sổ tay du lịch cũ kỹ, họ lên đường khám phá Thụy Sĩ và Việt Nam. Họ sẽ trải qua 12 ngày “bôn ba” ở những đất nước xa lạ, hứa hẹn mang đến cho khán giả những tiếng cười lẫn khoảnh khắc cảm động, đắm chìm trong “chemistry” thân thiết của hai thành viên.</p>', 'Hoàn Tất (8/8)', 8, 'tvshows', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jimin","avatar":""},{"name":"Jung Kook","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Are You Sure?","这样对吗？！","이게 맞아?!","Are You Sure"]', 1784690324176);
