INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sugar-baby-nghiep', 'Sugar Baby: Nghiệp', 'Sugar Baby: Karma', 'https://phimimg.com/upload/vod/20240926-1/9cc8575f7ff72a25ed05dc137da5b28b.jpg', 'https://phimimg.com/upload/vod/20251224-1/5e11801119bd18ba98561e787ecd6f5f.jpg', '<p>Thấm thía nỗi cô đơn, ông Trung muốn có gia đình yên ấm sau khi phải lòng bác sĩ Phương Anh. Nhưng sự đời tréo ngoe khiến ông phải tìm một sugar tạm thời. Nhưng đã là chơi dữ thì nghiệp báo càng đau.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 16, 2024, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Quang Minh","avatar":""},{"name":"Woni","avatar":""},{"name":"Kim Tuyến","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sugar Mommy vs Sugar Boy"]', 1784690324176);
