INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ultraman-blazar-dai-chien-quai-thu-tokyo', 'Ultraman Blazar: Đại Chiến Quái Thú Tokyo', 'Ultraman Blazar The Movie: Tokyo Kaiju Showdown', 'https://phimimg.com/upload/vod/20251223-1/9f7b1fd2f78757e50da106e31aa5d14f.jpg', 'https://phimimg.com/upload/vod/20251223-1/08d0e2ce4cdb80ea090bf764d16af7af.jpg', '<p>Tokyo rơi vào khủng hoảng khi những quái thú khổng lồ bất ngờ xuất hiện và tàn phá thành phố. Đội phản ứng đặc biệt chống quái vật phải căng mình chiến đấu nhưng nhanh chóng rơi vào thế bị động trước mối đe dọa chưa từng có. Đúng lúc đó, Ultraman Blazar xuất hiện, mang theo sức mạnh bí ẩn và phong cách chiến đấu hoang dã. Cuộc đối đầu giữa các quái thú bùng nổ, đẩy Tokyo vào trận chiến sinh tử. Giữa khói lửa dữ dội, con người và Ultraman buộc phải đặt niềm tin vào nhau để tồn tại.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Tomoya Warabino","avatar":""},{"name":"Hideyoshi Iwata","avatar":""},{"name":"Yamada Himina","avatar":""},{"name":"Konomi Naito","avatar":""},{"name":"Hayate Kajihara","avatar":""},{"name":"Yuki Ito","avatar":""},{"name":"Kisuke Iida","avatar":""},{"name":"Maya Okano","avatar":""},{"name":"Haru Iwakawa","avatar":""},{"name":"Ritsuto Morishima","avatar":""},{"name":"Miou Tanaka","avatar":""},{"name":"Hitomi Yaesawa","avatar":""},{"name":"Temujin Hijikata","avatar":""},{"name":"Yuko Takeda","avatar":""},{"name":"Kenichi Ugajin","avatar":""},{"name":"Yuri Amasaki","avatar":""},{"name":"Kiyohiro Nagumo","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172