INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('topakk', 'Topakk', 'Triggered', 'https://phimimg.com/upload/vod/20251223-1/d00dc330b698d71e310c01457e2fbec7.jpg', 'https://phimimg.com/upload/vod/20251223-1/b57f8e3ba75b8805cdb17341ffb53bc4.jpg', '<p>Mắc chứng rối loạn căng thẳng sau sang chấn, cựu binh tinh nhuệ nọ trở lại thế giới bạo lực khi anh giúp một người phụ nữ và em trai cô đang bị một băng đảng nguy hiểm nhắm tới.</p>', 'Full', 1, 'single', 'completed', 24, 2024, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Arjo Atayde","avatar":""},{"name":"Julia Montes","avatar":""},{"name":"Sid Lucero","avatar":""},{"name":"Paolo Paraiso","avatar":""},{"name":"Cholo Barretto","avatar":""},{"name":"Bernard Palanca","avatar":""},{"name":"Kayley Carrigan","avatar":""},{"name":"Elora Españo","avatar":""},{"name":"Ivan Carapiet","avatar":""},{"name":"Geli Bulaong","avatar":""},{"name":"Levi Ignacio","avatar":""},{"name":"Anne Feo","avatar":""},{"name":"Jeffrey Tam","avatar":""},{"name":"Ian Lee","avatar":""},{"name":"Julio Alberto De Leon","avatar":""},{"name":"Enchong Dee","avatar":""},{"name":"Vin Abrenica","avatar":""},{"name":"Rosh Barman","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Triggered","ทริกเกอร์: สัญชาตญาณสังหาร","Topakk"]', 1784690324176);
