INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('do-hoa-nien', 'Độ Hoa Niên', 'The Princess Royal', 'https://phimimg.com/upload/vod/20251220-1/da094eb9fab13571065531c8561efd9d.jpg', 'https://phimimg.com/upload/vod/20251220-1/5de35ae8c11505487a65a1674488b1e6.jpg', '<p>Bộ phim được chuyển thể từ tiểu thuyết &quot;Trưởng Công chúa&quot; của tác giả Mặc Thư Bạch, kể về câu chuyện tình yêu đầy trắc trở và lãng mạn giữa Lý Dung (Triệu Kim Mạch thủ vai) - vị Trường công chúa nắm quyền nhiếp chính của Đại Hạ và Bùi Văn Tuyên (Trương Lăng Hách thủ vai) - vị quan Thủ phụ tài giỏi. Ở kiếp trước, họ là vợ chồng nhưng lại bị chia cắt bởi hiểu lầm và thù hận, dẫn đến kết cục bi thảm. May mắn thay, cả hai được trao cơ hội sống lại, trở về thời điểm họ gặp nhau lần đầu khi còn trẻ. Trong cuộc sống mới này, Lý Dung và Bùi Văn Tuyên cùng nhau điều tra, phanh phui những âm mưu thâm độc để thay đổi số phận. Từ những người thù địch, họ dần thấu hiểu và trở thành tri kỷ, tình yêu cũng nảy nở từ đó. Cả hai dành cho nhau sự tin tưởng tuyệt đối, luôn ở bên hỗ trợ và giúp đỡ đối phương vượt qua mọi khó khăn. Cuối cùng, họ cũng hóa giải hiểu lầm năm xưa, gương vỡ lại lành, cùng nhau gây dựng sự nghiệp, khám phá bí mật về thân thế và tìm thấy tình yêu đích thực.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 14, 2024, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Kim Mạch","avatar":""},{"name":"Trương Lăng Hách","avatar":""},{"name":"Trần Hạc Nhất","avatar":""},{"name":"Lưu Húc Uy","avatar":""},{"name":"Hạc Thu","avatar":""},{"name":"Thành Quả","avatar":""},{"name":"Tăng Hựu Trân","avatar":""},{"name":"Vu Cẩn Duy","avatar":""},{"name":"Triệu Kha","avatar":""},{"name":"Tôn Nhuế","avatar":""},{"name":"Vương Bác Văn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["度华年","Princesa Real","شاهدخت سلطنتی","شاهزاده خانم سلطنتی","องค์หญิงใหญ่","度華年","The Grand Princess","The Princess Royal","Độ Hoa Niên"]', 1784690324176);
