INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chang-giu-tre-phan-2', 'Chàng Giữ Trẻ (Phần 2)', 'The Manny (Season 2)', 'https://phimimg.com/upload/vod/20241219-1/3e224a2eee9bea884b4d750ebba2f287.jpg', 'https://phimimg.com/upload/vod/20241219-1/4d8ddc228f6fb75c8a49fcda2f4fcf0d.jpg', '<p>Trong hoảng loạn, một giám đốc bận rộn thuê một chủ trang trại chăm sóc các con của mình. Cô nào ngờ anh sẽ thách thức quan điểm của cô về vai trò của các giới và cả tình yêu.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 17, 2024, 'Vietsub', 'FHD', 'Mexico', 0, '[{"name":"Sandra Echeverría","avatar":""},{"name":"Iván Amozurrutia","avatar":""},{"name":"Anthony Giuletti","avatar":""},{"name":"Alexander Tavizon","avatar":""},{"name":"Cassandra Iturralde","avatar":""},{"name":"Moisés Arizmendi","avatar":""},{"name":"Diana Bovio","avatar":""},{"name":"Eugenio Montessoro","avatar":""},{"name":"Josemaría Torre Hütt","avatar":""},{"name":"Sara Isabel Quintero","avatar":""},{"name":"Matías Desiderio","avatar":""},{"name":"Pamela Almanza","avatar":""},{"name":"Ivanna Castro","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Manny","曼尼酒店","El niñero"]', 1784690324176);
