INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hightown-phan-3', 'Hightown (Phần 3)', 'Hightown (Season 3)', 'https://phimimg.com/upload/vod/20251216-1/386586f0012686e615964f5ee660a0d9.jpg', 'https://phimimg.com/upload/vod/20251216-1/536ec87dd109cca5c67adcf123890753.jpg', '<p>Một nhân viên quản lý động vật hoang dã ở Cape Cod vướng vào cuộc điều tra án mạng, khiến cô đối mặt với luật pháp, bí mật giấu kín từ lâu và cả quá trình hồi phục của chính mình.</p>', 'Hoàn Tất (7/7)', 7, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Monica Raymund","avatar":""},{"name":"Riley Voelkel","avatar":""},{"name":"Atkins Estimond","avatar":""},{"name":"Amaury Nolasco","avatar":""},{"name":"Dohn Norwood","avatar":""},{"name":"James Badge Dale","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hightown"]', 1784690324176);
