INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vong-linh-dau-kho-muon-giai-nghe', 'Vong Linh Đau Khổ Muốn Giải Nghệ', 'Let This Grieving Soul Retire', 'https://phimimg.com/upload/vod/20241227-1/28fe172be1731e9a4c06c0fd6c46e608.jpg', 'https://phimimg.com/upload/vod/20241227-1/0cbf531011ba54fceae6be6c9e811f81.jpg', '<p>Krai Andrey và bạn bè hứa hẹn trở thành thợ săn kho báu, nhưng Krai nhận ra mình không có tố chất này, trong khi những kỳ vọng của mọi người và nguy hiểm xung quanh anh ngày càng gia tăng.</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 13, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kensho Ono","avatar":""},{"name":"Miyu Kubota","avatar":""},{"name":"Fairouz Ai","avatar":""},{"name":"Konomi Kohara","avatar":""},{"name":"Kohei Amasaki","avatar":""},{"name":"Tomokazu Sugita","avatar":""},{"name":"Aoi Koga","avatar":""},{"name":"You Taichi","avatar":""},{"name":"Akira Sekine","avatar":""},{"name":"Koji Seki","avatar":""},{"name":"Seiji Maeda","avatar":""},{"name":"Jun Fukuyama","avatar":""},{"name":"Akio Otsuka","avatar":""},{"name":"Haruka Michii","avatar":""},{"name":"Ryohei Kimura","avatar":""},{"name":"Takashi Matsuyama","avatar":""},{"name":"Reina Ueda","avatar":""},{"name":"Tetsu Inada","avatar":""},{"name":"Haruka Shi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Nageki No Bourei Ha Intai Shitai","叹息的亡灵好想隐退","叹息的亡灵好想隐退~最弱猎手的最强队伍养成术~","תן לנפש המתאבלת הזו לפרוש","Nageki no Bourei wa Intai Shitai","Nageki no Bōrei wa Intai Shitai","Nageki no Bōrei wa Intai Shitai: Saijaku Hunter ni Yoru Saikyō Party Ikusei-jutsu"