INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-hen-giang-sinh-hoan-hao', 'Cuộc Hẹn Giáng Sinh Hoàn Hảo', 'The Perfect Christmas Date', 'https://phimimg.com/upload/vod/20251211-1/de179b6929832f082076f6e36daeeb1d.jpg', 'https://phimimg.com/upload/vod/20251211-1/003f445c9b70870a6dee39d4df5e7d5d.jpg', '<p>Marie là một phụ nữ 31 tuổi, cô tham gia trò chơi &quot;hẹn hò tốc độ&quot; với hy vọng tìm được người bạn đời để cùng đón Giáng sinh. Trong sự kiện, cô vô tình đổi nhật ký của mình với một người lạ. Liệu phép màu của mùa lễ hội cuối năm có giúp Marie tìm lại được cuốn nhật ký và người đàn ông hoàn hảo, khiến kỳ nghỉ Giáng sinh của cô trở nên đáng nhớ?</p>', 'Full', 1, 'single', 'completed', 14, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Canada', 0, '[{"name":"Emily Alatalo","avatar":""},{"name":"Andrew Bushell","avatar":""},{"name":"Julia Knope","avatar":""},{"name":"Paula Boudreau","avatar":""},{"name":"Noah Berc","avatar":""},{"name":"Nico DeCastris","avatar":""},{"name":"D.J. Demers","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Merry Missed Connection","The Perfect Christmas Date"]', 1784690324176);
