INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thu-thach-giang-sinh', 'Thử Thách Giáng Sinh', 'Snowy With A Chance Of Christmas', 'https://phimimg.com/upload/vod/20251211-1/cf38822eedbe3f06a77dfd5a40c2822e.jpg', 'https://phimimg.com/upload/vod/20251211-1/86beece66ec96fc35b33a5045d173e27.jpg', '<p>Đài truyền hình nơi nữ phát thanh viên thời tiết Gwen Marley làm việc đang gặp khó khăn và cần một cú hích để duy trì hoạt động. Gwen đề xuất được hợp tác với Adam, người điều hành một chiến dịch quyên góp đồ chơi vào dịp Giáng sinh. Tuy nhiên, Adam chỉ quan tâm đến việc giúp đỡ người khác và không mấy hứng thú với sự kiện mà Gwen tổ chức. Trong lúc thuyết phục anh chàng, cô phát hiện mình bắt đầu có tình cảm với Adam. Liệu đây có là sự khởi đầu của một tình yêu đẹp?</p>', 'Full', 1, 'single', 'completed', 17, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Canada', 0, '[{"name":"Andrea Brooks","avatar":""},{"name":"Giles Panton","avatar":""},{"name":"Edward Lafferty","avatar":""},{"name":"Shiraine Haas","avatar":""},{"name":"Carly Fawcett","avatar":""},{"name":"Anna Jacyszyn","avatar":""},{"name":"Damon Gregory","avatar":""},{"name":"Elijah Fox","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Snowy with a Chance of Christmas"]', 1784690324176);
