INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieng-chuong-tinh-yeu', 'Tiếng Chuông Tình Yêu', 'Jingle All The Way To Love', 'https://phimimg.com/upload/vod/20251211-1/47246571f67c8d5787178c554118814d.jpg', 'https://phimimg.com/upload/vod/20251211-1/8bc0b10efef191f25efdc4a27b31003b.jpg', '<p>Vào dịp Giáng sinh của bảy năm trước, nữ luật sư Andi đã nhận được một chiếc chuông xe trượt tuyết may mắn từ một người lạ. Dù có cảm tình với người tặng quà nhưng cô đã &quot;mất dấu&quot; anh chàng từ sau lần gặp đầu tiên. Cô chia sẻ câu chuyện của mình trên một chương trình phát thanh với sự tham gia của người dẫn chuyện Jake và các thính giả. Trong không khí vui nhộn của mùa lễ hội, tất cả họ háo hức bắt đầu hành trình tìm lại tình yêu đã mất của Andi.</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Erin Agostino","avatar":""},{"name":"Romaine Waite","avatar":""},{"name":"Connie Manfredi","avatar":""},{"name":"Richard Waugh","avatar":""},{"name":"Delia Lisette Chambers","avatar":""},{"name":"Madeleine Claude","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jingle All the Way to Love"]', 1784690324176);
