INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('12-buoi-hen-giang-sinh', '12 Buổi Hẹn Giáng Sinh', 'Engaged By Christmas', 'https://phimimg.com/upload/vod/20251211-1/c2c9e9e2ea066450e7b6865b7bbd1ec1.jpg', 'https://phimimg.com/upload/vod/20251211-1/7bb1df5c144849fd4596f8b71ebe98b5.jpg', '<p>Phim xoay quanh câu chuyện của Zoe, một cô gái tìm đến chuyên mục tư vấn Dear Adora để cứu vãn mối quan hệ của mình trước kỳ nghỉ lễ. Tuy nhiên, khi áp dụng lời khuyên, cô thấy mọi thứ trở nên tồi tệ, thậm chí bị bạn trai chia tay. Tìm hiểu mọi chuyện, Zoe phát hiện ra Dear Adora thực chất là một người đàn ông tên Adam. Cô đưa ra điều kiện để giữ bí mật danh tính của Adam là anh phải giúp cô tổ chức một loạt sự kiện theo chủ đề Giáng sinh. Lần hợp tác này thành công ngoài mong đợi và tình yêu giữa cặp đôi oan gia cũng bắt đầu &quot;đơm hoa kết trái&quot;.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Marcus Rosner","avatar":""},{"name":"Brittany Bristow","avatar":""},{"name":"Michael Lazarovitch","avatar":""},{"name":"Megan Tracz","avatar":""},{"name":"Colette Nwachi","avatar":""},{"name":"Stafford Perry","avatar":""},{"name":"Adam Keefe","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Dear Christmas Hearts","Verlobung unter dem Weihnachtsbaum","Engaged by Christmas"]', 1784690324176);
