INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('12-buoi-hen-giang-sinh', '12 Buổi Hẹn Giáng Sinh', 'Engaged By Christmas', '12 buổi hẹn giáng sinh engaged by christmas marcus rosner brittany bristow michael lazarovitch megan tracz colette nwachi stafford perry adam keefe dear christmas hearts verlobung unter dem weihnachtsbaum engaged by christmas', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-sinh-sot-deo', 'Giáng Sinh Sốt Dẻo', 'Christmas, Love And Fudge', 'https://phimimg.com/upload/vod/20251211-1/0ec9c75b03714f690b86553f394c51b4.jpg', 'https://phimimg.com/upload/vod/20251211-1/fb02b2b4e0aa4a3021d2bfcdcf2d287f.jpg', '<p>Đầu bếp chuyên làm món bánh, kẹo ngọt Amanda và doanh nhân Simon hợp tác để tái tạo công thức làm bánh nổi tiếng cho cuộc thi Big Holiday Pastry Show. Trong quá trình chạy đua với thời gian để hoàn thành món ăn, tình yêu nảy nở giữa cặp đôi không giống ai này. Câu chuyện tình lãng mạn vào mùa Giáng sinh cũng chính thức bắt đầu từ đây.</p>', 'Full', 1, 'single', 'completed', 16, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Canada', 0, '[{"name":"Erin Karpluk","avatar":""},{"name":"Christopher Russell","avatar":""},{"name":"Ashley Alexander","avatar":""},{"name":"Janet Anderson","avatar":""},{"name":"Dalias Blake","avatar":""},{"name":"Brian (B Mack) Mccune","avatar":""},{"name":"Toby Marks","avatar":""},{"name":"Edward Lafferty","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["A Recipe For Christmas Romance","Sweet Holiday Romance","Christmas, Love and Fudge"]', 1784690324176);
