INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giang-sinh-o-alaska', 'Giáng Sinh Ở Alaska', 'Christmas In Alaska', 'https://phimimg.com/upload/vod/20251211-1/1058f4563526535671fed45d37fe5257.jpg', 'https://phimimg.com/upload/vod/20251211-1/c78f3ce03f06023e6711702ae0e4272f.jpg', '<p>Oliver và Megan là hai nhà báo đối thủ, đang cạnh tranh nhau vô cùng gay gắt để giành được vị trí Tổng biên tập Voyage Voyage. Trong một chuyến bay công tác chung, máy bay gặp sự cố phải hạ cánh khẩn cấp, họ bị mắc kẹt ở Alaska lạnh lẽo và đầy tuyết. Tại vùng đất băng giá này, cả hai bất ngờ bị cuốn vào câu chuyện tình lãng mạn đúng ngay dịp Giáng sinh.</p>', 'Full', 1, 'single', 'completed', 16, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Canada', 0, '[{"name":"Marcus Rosner","avatar":""},{"name":"Emma Johnson","avatar":""},{"name":"Ryan Northcott","avatar":""},{"name":"Paul J. Ballin","avatar":""},{"name":"Stephanie Wolfe","avatar":""},{"name":"Essek Moore","avatar":""},{"name":"Charlize Adelyn","avatar":""},{"name":"Ashlee Pearce","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Christmas in Alaska"]', 1784690324176);
