INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-xoay-chai', 'Trò Chơi Xoay Chai', 'Spin The Bottle', 'https://phimimg.com/upload/vod/20251207-1/0e173a44e97ac951fc0c2c8a5b3c3e52.jpg', 'https://phimimg.com/upload/vod/20251207-1/eb405e697dc151086bb6fa2d0e9f6dcc.jpg', '<p>Khi một nhóm bạn chơi trò Quay Chai (Spin the Bottle) trong một ngôi nhà bị ám bởi một vụ thảm sát tàn bạo, họ đã vô tình giải thoát một linh hồn quỷ dữ và bắt đầu bị giết theo những cách kinh hoàng. Giờ đây, những người sống sót phải bám víu vào nhau để khám phá những bí mật đen tối của ngôi nhà và chấm dứt cuộc đổ máu.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Tanner Stine","avatar":""},{"name":"Kaylee Kaneshiro","avatar":""},{"name":"Tony Amendola","avatar":""},{"name":"Ryan Whitney","avatar":""},{"name":"Hal Cumpston","avatar":""},{"name":"Angela Halili","avatar":""},{"name":"Scarlett DeMeo","avatar":""},{"name":"Ali Larter","avatar":""},{"name":"Justin Long","avatar":""},{"name":"Christopher Ammanuel","avatar":""},{"name":"Emily Skinner","avatar":""},{"name":"Tyler Wolfe","avatar":""},{"name":"Grant Morningstar","avatar":""},{"name":"Nathan Kohnen","avatar":""},{"name":"Sophia DeWier","avatar":""},{"name":"Jacob Radin","avatar":""},{"name":"Kees DeVos","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Spin the Bottle"]', 1784690324176);
