INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-hoc-chien-tranh-phan-2', 'Đại Học Chiến Tranh (Phần 2)', 'University War (Season 2)', 'https://phimimg.com/upload/vod/20251205-1/2f0c0e2cf7840343800b081ba21c1fac.jpg', 'https://phimimg.com/upload/vod/20251205-1/f3265fd622f0b10e159b19d99d82e99a.jpg', '<p>Mỗi tập của Elite League là một cuộc chiến trí tuệ căng thẳng, nơi các thí sinh phải vận dụng tối đa khả năng logic, toán học và ghi nhớ để vượt qua các thử thách. Chương trình không chỉ là cuộc thi, mà còn là sân chơi để các &quot;học bá&quot; thể hiện tài năng và chiến lược cá nhân. Đặc biệt, các trò chơi được thiết kế sáng tạo và kịch tính, kết hợp với những màn đấu trí hấp dẫn, khiến người xem không thể rời mắt.</p>', 'Hoàn Tất (8/8)', 8, 'tvshows', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["大学战争","Elite League","대학전쟁"]', 1784690324176);
