INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('satu-tin-do-phan-1', 'Satu: Tín Đồ (Phần 1)', 'The Believers (Season 1)', 'https://phimimg.com/upload/vod/20250404-1/31cf752027dcd95ad067899609953692.jpg', 'https://phimimg.com/upload/vod/20251205-1/e284c7cc20ab99eb4f237135e16953ef.jpg', '<p>Khi công ty khởi nghiệp của họ ngập trong nợ nần, ba doanh nhân dàn dựng vụ lừa đảo đầy rủi ro bằng cách lợi dụng ngôi chùa Phật giáo để trả khoản vay lớn trước khi hết thời hạn.</p>', 'Hoàn Tất (9/9)', 9, 'series', 'completed', 10, 2024, 'Vietsub + Lồng Tiếng', 'FHD', 'Thái Lan', 0, '[{"name":"Teeradon Supapunpinyo","avatar":""},{"name":"Achiraya Nitibhon","avatar":""},{"name":"Pachara Chirathivat","avatar":""},{"name":"Patchai Pakdesusuk","avatar":""},{"name":"Paopetch Charoensook","avatar":""},{"name":"Channarong Khuntee-tao","avatar":""},{"name":"Manatsanun Panlertwongskul","avatar":""},{"name":"Chintara Sukapatana","avatar":""},{"name":"Surasee Patham","avatar":""},{"name":"Pramote Seangsorn","avatar":""},{"name":"Torphong Kul-on","avatar":""},{"name":"Paradorn Vesurai","avatar":""},{"name":"Michael","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Sathu","The Believers","สาธุ"]', 1784690324176);
