INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khe-hat-loi-yeu-sasayaku-you-ni-koi-wo-utau', 'Khẽ Hát Lời Yêu (Sasayaku You ni Koi wo Utau)', 'Whisper Me A Love Song', 'https://phimimg.com/upload/vod/20251204-1/49f3a89a53bc6657cb0b6f6aea75f178.jpg', 'https://phimimg.com/upload/vod/20251204-1/072d6710b61fcc020816f7a7dce7adb8.jpg', '<p>Himari, nữ sinh mới lên cao trung, đã đem lòng ngưỡng mộ Yori, người hát chính của ban nhạc biểu diễn trong buổi lễ chào đón tân học sinh. Và khi tình cờ gặp nhau ở trường, Himari bèn bày tỏ cảm xúc của mình với Yori. Ấn tượng với thái độ thẳng thắn ấy, Yori nhanh chóng nảy sinh tình cảm với Himari…Vậy câu chuyện tình giữa hai người sẽ đi đến đâu? Cùng đón xem ngay nào!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hana Shimano","avatar":""},{"name":"Asami Seto","avatar":""},{"name":"Kana Sasakura","avatar":""},{"name":"Mikako Komatsu","avatar":""},{"name":"Konomi Kohara","avatar":""},{"name":"Ai Kakuma","avatar":""},{"name":"Yuna Nemoto","avatar":""},{"name":"Reina Ueda","avatar":""},{"name":"Chika Anzai","avatar":""},{"name":"Aoi Koga","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["恰如细语般的恋歌","宛若呢喃细语般浅唱恋歌","Sasayaku You ni Koi wo Utau","Sasayaku Yō ni Koi wo Utau","Sasayaku You ni Koi o Utau","Sasakoi","ささこい","Sasayaku Yō ni Koi o Utau","戀語輕唱","Whispering You a Love Song","ささやくように恋を唄う"]', 1784690324176);
