INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khe-hat-loi-yeu-sasayaku-you-ni-koi-wo-utau', 'Khẽ Hát Lời Yêu (Sasayaku You ni Koi wo Utau)', 'Whisper Me A Love Song', 'khẽ hát lời yêu (sasayaku you ni koi wo utau) whisper me a love song hana shimano asami seto kana sasakura mikako komatsu konomi kohara ai kakuma yuna nemoto reina ueda chika anzai aoi koga 恰如细语般的恋歌 宛若呢喃细语般浅唱恋歌 sasayaku you ni koi wo utau sasayaku yō ni koi wo utau sasayaku you ni koi o utau sasakoi ささこい sasayaku yō ni koi o utau 戀語輕唱 whispering you a love song ささやくように恋を唄う', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chien-tuyen-hai-quan', 'Chiến Tuyến Hải Quan', 'Customs Frontline', 'https://phimimg.com/upload/vod/20251204-1/15cd0263454fe15dd27873919da7beef.jpg', 'https://phimimg.com/upload/vod/20251204-1/051788384e03957bc38e325a130e70fe.jpg', '<p>Châu Chính Lễ (do Tạ Đình Phong thủ vai) là một nhân viên của Hải quan Hồng Kông, có mối quan hệ thân thiết như thầy trò với cấp trên của mình, Trương Vận Nam (do Trương Học Hữu thủ vai). Trương, dưới áp lực từ cấp trên là Trợ lý Cục trưởng (biên giới và cảng) Quách Tử Cường (do Ngô Chấn Vũ thủ vai), đã mạnh mẽ đề xuất Lễ tham gia vào chiến dịch hợp tác giữa Tổ chức Hải quan Thế giới và Tổ chức Cảnh sát Hình sự Quốc tế, nhằm điều tra một vụ buôn lậu vũ khí quy mô lớn liên quan đến Hồng Kông trước đó. Lễ cùng với đặc vụ tình báo Thái Lan Ying (do Lưu Nhã Sắc thủ vai) thâm nhập vào khu vực giao dịch vũ khí sôi động để truy tìm kẻ đứng sau. Cùng lúc đó, nội bộ Hải quan Hồng Kông truyền đến tin tức dữ dội! Lễ, không sợ hãi, kiên quyết truy tìm sự thật, một cuộc chiến tranh thảm khốc sắp nổ ra...</p>', 'Full', 1, 'single', 'completed', 16, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Nicholas Tse Ting-Fung","avatar":""},{"name":"Jacky Cheung Hok-Yau","avatar":""},{"name":"Francis Ng Chun-Yu","avatar":""},{"name":"Karena Lam Kar-Yan","avatar":""},{"name":"Liu Yase","avatar":""},{"name":"Shek Sau","avatar":""},{"name":"Kenny Kwan","avatar":""},{"name":"Michelle Wai Si-Nga","avatar":""},{"name":"Angus Yeung Tin-Yue","avatar":""},{"name":"Justin Chu","avatar":""},{"name":"Kenneth Lai","avatar":""},{"name":"Melvin Wong Gam-Sam","avatar":""},{"name":"Michelle Yim","avatar":""},{"name":"Carlos Chan","avatar":""},{"name":"Polly Lau","avatar":""},{"name":"Ben Yuen Fo","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["War Customized","海关战线","Customs.Frontline","خط مقدم گمرک","海關戰線"]', 1784690324176);
