INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bob-marley-mot-tinh-yeu', 'Bob Marley: Một Tình Yêu', 'Bob Marley: One Love', 'bob marley: một tình yêu bob marley: one love kingsley ben-adir lashana lynch james norton tosin cole umi myers anthony welsh nia ashi aston barrett jr. anna-sharé blake gawaine ''j-summa'' campbell naomi cowan alexx a-game michael gandolfini quan-dajai henriques david marvin ke боб марлі: одне кохання 雷鬼之父：音乐无国界 音乐传奇卜马利：人生爱与梦 בוב מארלי אהבה אחת bob marley one love bob marley - one love bob marley, one love 鲍勃·马利的一份爱 bob marley: one love', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-vu-cuop-nguoi-yeu', 'Dịch Vụ Cướp Người Yêu', 'I Will Rob Your Lover', 'https://phimimg.com/upload/vod/20251130-1/b4b5408bfd930a1d3391e6b0265fc635.jpg', 'https://phimimg.com/upload/vod/20251130-1/0b87bfaaa02571d6dbd32a351e9a150e.jpg', '<p>Luôn lo sợ vì người bạn trai bạo lực, Hayakawa Risa lang thang trên trang tư vấn gỡ rối và tình cờ biết đến văn phòng CAT với khẩu hiệu: “Tôi sẽ đến cướp người yêu của bạn.” Nơi đây hướng đến mục tiêu giúp đỡ khách hàng giải quyết mối quan hệ tình cảm cá nhân thông qua dịch vụ “cướp” người yêu nam giới một cách hợp pháp. Giám đốc Minami Hinako có tỷ lệ thành công 100% với sự trợ giúp của chàng nhân viên duy nhất Asanuma Yosuke rồi sẽ khéo léo cướp lấy người yêu của Risa và những khách hàng khác như thế nào đây?</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Rena Takeda","avatar":""},{"name":"Keisuke Watanabe","avatar":""},{"name":"Miho Watanabe","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["당신의 애인, 강탈합니다.","あなたの恋人、強奪します。"]', 1784690324176);
