INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-tim-wondla-phan-1', 'Đi Tìm WondLa (Phần 1)', 'WondLa (Season 1)', 'https://phimimg.com/upload/vod/20251128-1/70256d588d7bbf9af19f419efab59a2d.jpg', 'https://phimimg.com/upload/vod/20251128-1/e82aef18073fd0ca7a1f3c1a12d80486.jpg', '<p>Bị buộc phải tháo chạy khỏi một hầm trú ẩn dưới lòng đất, Eva phát hiện ra một thế giới không hề giống như mình đã hình dung. Trong hành trình vượt qua môi trường đầy hiểm nguy với những nền văn minh xa lạ, Eva đi tìm câu trả lời cho câu hỏi lớn nhất: Liệu mình có phải con người cuối cùng?</p>', 'Hoàn Tất (7/7)', 7, 'hoathinh', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jeanine Mason","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["寻家","云朵拉传奇","واندلا","원더라","Пошук WondLa","The Search for WondLa","WondLa"]', 1784690324176);
