INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mach-lo-cuong-dao', 'Mạch Lộ Cuồng Đao', 'The Wild Blade Of Strangers', 'https://phimimg.com/upload/vod/20251126-1/d4716ef2137610f65b66ad52a7d64d8a.jpg', 'https://phimimg.com/upload/vod/20251126-1/ee4448e38f71343778969abc3dcc2244.jpg', '<p>Mạch Đao huấn luyện viên quân sự Điền An Nghiệp bảo vệ đất nước và canh giữ biên giới, giết chết vô số kẻ thù. Tuy nhiên, anh ta lại vướng vào cuộc tranh giành chính tử, và đồn trú của Lương Thành bị thảm sát, và ba trăm anh em Mạch Đao chết một cách bi thảm. Điền An Nghiệp chán nản và sống ẩn dật ở thành phố Lạc Dương bán than để kiếm sống. Tân hoàng đế sắp lên ngôi, Điền An Nghiệp vào thành bán than và vô tình cứu được một người phụ nữ và một em bé đang bị săn đuổi. Họ không hề biết rằng đứa bé chính là xương thịt duy nhất của hoàng tử bị sát hại. Dòng dõi trực hệ của vua nước Tề, Thứ Phi Quân, nghe tin và đến. Thứ Phi Quân người đã quyết định phần còn lại của cuộc đời mình, một lần nữa gây ra một làn sóng lớn ở thành phố Lạc Dương.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Tấn","avatar":""},{"name":"Căng Lạc","avatar":""},{"name":"Hạ Mộng","avatar":""},{"name":"Tưởng Lỗ Hạ","avatar":""},{"name":"Lưu Hoa","avatar":""},{"name":"Lưu Phong Siêu","avatar":""},{"name":"Phùng Lôi","avatar":""},{"name":"Chu Thời Mậu","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Mo Lu Kuang Dao","​​Stranger Crazy Knife","นักดาบคนแปลกหน้า","陌路狂刀"]', 1784690324176);
