INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mach-lo-cuong-dao', 'Mạch Lộ Cuồng Đao', 'The Wild Blade Of Strangers', 'mạch lộ cuồng đao the wild blade of strangers trương tấn căng lạc hạ mộng tưởng lỗ hạ lưu hoa lưu phong siêu phùng lôi chu thời mậu mo lu kuang dao ​​stranger crazy knife นักดาบคนแปลกหน้า 陌路狂刀', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-doi-thu-2', 'Cuộc Đời Thứ 2', 'Second Life', 'https://phimimg.com/upload/vod/20251126-1/28ca4c19d5b2ce89b167ad084e2eb4c3.jpg', 'https://phimimg.com/upload/vod/20251126-1/a7d0bfb35648f360e876af8475ec5ed5.jpg', '<p>Trong nhà tù nữ, “Chiến thần” Lão Lương (do Nguyên Thu thủ vai) – người khiến ai cũng khiếp sợ, và A Quỷ (do Ngô Vĩnh Long thủ vai) – sát thủ mù lòa của băng Thanh Long từng một thời nổi tiếng, vô tình gặp lại nhau. Từ đó, giữa hai mẹ con tại một tiệm thuốc Đông y đã xảy ra một loạt những cuộc đấu trí, đấu sức đầy kịch tính. Một người là bậc thầy võ học Đông y, đã thất lạc con trai nhiều năm, luôn mong muốn yêu thương con bằng cách tốt nhất; người kia là một đứa trẻ mồ côi bị băng đảng bỏ rơi, nay đã quay về gia đình nhưng lại luôn tìm cách ám sát mẹ mình. Cả hai gặp lại nhau trong hoàn cảnh sai lầm, thời điểm sai lầm, dẫn đến hàng loạt các màn đối đầu võ thuật đỉnh cao, gây ra những tình huống dở khóc dở cười nhưng cũng đầy nhiệt huyết, cuối cùng tạo nên một mối duyên kỳ diệu về sự cứu rỗi lẫn nhau và cùng hoàn thiện lẫn nhau.</p>', 'Full', 1, 'single', 'completed', 30, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Nguyên Thu","avatar":""},{"name":"Ngô Vĩnh Long","avatar":""},{"name":"Kỷ Gia Hòa","avatar":""},{"name":"Lôi Mộc","avatar":""},{"name":"Trần Chi Huy","avatar":""},{"name":"Chu Tiểu Phi","avatar":""},{"name":"Đáo Đáo","avatar":""},{"name":"Chu Ân Tây","avatar":""},{"name":"Hứa Chiếm Vĩ","avatar":""},{"name":"Neguin","avatar":""},{"name":"Pavel","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Võ Thuật","slug":"vo-thuat","id":"578f