INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-vuc-vo-tan', 'Thần Vực Vô Tận', 'Eternal Realm', 'https://phimimg.com/upload/vod/20250224-1/c00acb337ce30599a94da004913cb9c2.jpg', 'https://phimimg.com/upload/vod/20250224-1/604af3794a750abf71de8e1703d03359.jpg', '<p>Bảy năm trước, Thái tử người phàm Lệ Hàn và cả gia đình bị 7 tiên nhân giết chết. Trong lúc thoi thóp, hắn và muội muội Lệ Dao được Thần Vực vô tận trong truyền thuyết cứu. Bảy năm sau, Lệ Hàn trở về. Để đánh thức muội muội, hắn buộc phải không ngừng tăng tu vi để bảo vệ chúng sinh theo yêu cầu của Thần Vực. Đồng thời, hắn cũng thề phải tìm ra hung thủ năm đó để báo thù rửa hận! Nhưng mọi việc phức tạp hơn hắn nghĩ nhiều. Khi sự thật dần được tiết lộ, Lệ Hàn phải lựa chọn giữa hai quyết định khó khăn, đó là trả thù hoặc trả ơn…</p>', 'Hoàn Tất (80/80)', 80, 'hoathinh', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324176);
