INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('luc-dia-kien-tien', 'Lục Địa Kiện Tiên', 'Land Key Immortal', 'https://phimimg.com/upload/vod/20250224-1/df633202b6ab9e26d966e19e4186979f.jpg', 'https://phimimg.com/upload/vod/20250224-1/09d096b856580e53597d20ab1f9ca2cf.jpg', '<p>Một thiếu niên đang chơi game thì bị sét đánh. Sau khi tỉnh lại phát hiện bản thân đã xuyên không và đang ở rể trong phủ Công Tước. Đêm tân hôn, người ta phát hiện hắn ngủ trên giường em gái vợ. Xuyên không mà mở màn đã như địa ngục như vậy, hãy xem hắn dùng bàn phím để hoá dữ thành lành như thế nào.</p>', 'Hoàn Tất (150/150)', 150, 'hoathinh', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"清殇","avatar":""},{"name":"Qiao Su","avatar":""},{"name":"Shuang Zhao","avatar":""},{"name":"Qian Chen","avatar":""},{"name":"Yi Ruoxun","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["陆地键仙","Ludi Jian Xian","Lu Di Jian Xian","Land Key Immortal","Earthern Keyboard Immortal","Keyboard Crusader of the Mystical World","The Keyboard Immortal"]', 1784690324176);
