INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('so-huu-manhattan', 'Sở Hữu Manhattan', 'Owning Manhattan', 'https://phimimg.com/upload/vod/20251115-1/f6ed04614d6f565331b01d6612020a60.jpg', 'https://phimimg.com/upload/vod/20251115-1/0f55767c33e6118f37cd13e33aa51bd4.jpg', '<p>Ông trùm bất động sản Ryan Serhant lãnh đạo một trong những công ty lớn nhất tại New York và thúc đẩy các đại lý của mình đạt đến đỉnh cao trong khi giải quyết những vụ niêm yết đắt giá nhất.</p>', 'Hoàn Tất (8/8)', 8, 'tvshows', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ryan Serhant","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Owning Manhattan"]', 1784690324176);
