INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-dieu-hanh-phuc-phan-2', 'Cánh Diều Hạnh Phúc (Phần 2)', 'Happy Kite (Season 2)', 'https://phimimg.com/upload/vod/20251115-1/a9e82ff0d1327b326f3e80dc8d53534c.jpg', 'https://phimimg.com/upload/vod/20251115-1/8a200611e43f3b4a132ad731b606b6e8.jpg', '<p>Sau nhiều năm tận tụy vun vén cho mái ấm, người vợ tin rằng mình đang sống trong một cuộc hôn nhân trọn vẹn. Thế nhưng, sự thật phũ phàng ập đến khi cô phát hiện chồng ngoại tình. Cú sốc ấy không chỉ làm tan vỡ niềm tin, mà còn đẩy cô vào vòng xoáy giằng xé: nên dứt khoát từ bỏ để bảo vệ lòng tự trọng, hay lựa chọn tha thứ và đấu tranh để níu giữ gia đình, vì những kỷ niệm, vì con cái và vì tình yêu từng có? Giữa tổn thương và hy vọng, người vợ phải tìm ra con đường cho riêng mình, để biết đâu mới là hạnh phúc thật sự.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 31, 2024, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Shukri Yahaya","avatar":""},{"name":"Lisdawati","avatar":""},{"name":"Arash Mohamad","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324176);
