INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-ay-tua-ngon-lua', 'Anh Ấy Tựa Ngọn Lửa', 'Be Your Knight', 'https://phimimg.com/upload/vod/20251110-1/ea34520470e95c1e0ed1c24cf9800ba3.jpg', 'https://phimimg.com/upload/vod/20251110-1/eb36300ff0aac14b2eafbe84f10e1167.jpg', '<p>Hướng Đình Đông, người thừa kế của gia tộc y dược nổi tiếng họ Hướng tại Đường Thành đã bị thương và hôn mê trong khi tranh chấp với vị hôn thê Trình Triệt. Để cứu nhà họ Hướng, Trình Triệt tìm Diệp Nhiên, người em trai bí ẩn bị thất lạc của Hướng Đình Đông về, nhờ anh ta giả mạo Hướng Đình Đông để giúp cô vượt qua khó khăn. Cả hai hợp tác lật tẩy băng nhóm buôn thuốc phiện mà Hướng Đình Đông câu kết, và cuối cùng tiêu diệt được chúng.</p>', 'Hoàn Tất (29/29)', 29, 'series', 'completed', 10, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Phàn Trị Hân","avatar":""},{"name":"Dương Vũ Hi","avatar":""},{"name":"Vương Quân Hạo","avatar":""},{"name":"Y Linh","avatar":""},{"name":"Quách Gia Ngữ","avatar":""},{"name":"Vương Nhã Lân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["他似火"]', 1784690324176);
