INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('minh-yeu-nhau-binh-yen-thoi', 'Mình Yêu Nhau, Bình Yên Thôi', 'Let''s Love Each Other Peacefully', 'https://phimimg.com/upload/vod/20251109-1/8045c871677df90ce05d93d03e9bbc96.jpg', 'https://phimimg.com/upload/vod/20251109-1/86a9936fb92c9e4c2340e9a39468b8d3.jpg', '<p>Bộ phim xoay quanh cuộc sống hôn nhân của cặp vợ chồng trẻ Đức và Hà. Họ kết hôn dựa trên tình yêu nhưng lại phải đối mặt với nhiều thử thách, chủ yếu đến từ mâu thuẫn mẹ chồng nàng dâu gay gắt khi bà Giang (mẹ Đức) luôn can thiệp quá sâu vào cuộc sống riêng của con cái.Mặc dù vợ chồng Đức và Hà liên tục cãi vã, hiểu lầm do áp lực từ mẹ chồng và những khác biệt tính cách, nhưng sâu thẳm họ vẫn yêu thương nhau. Phim là hành trình vượt qua mâu thuẫn, học cách thấu hiểu, và trưởng thành để bảo vệ tình yêu và xây dựng một gia đình đúng như cái tên: "yêu nhau, bình yên thôi".</p>', 'Hoàn Tất (105/105)', 105, 'series', 'completed', 24, 2024, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Thanh Sơn","avatar":""},{"name":"Trọng Lân","avatar":""},{"name":"Việt Hoa","avatar":""},{"name":"Doãn Quốc Đam","avatar":""},{"name":"Maya","avatar":""},{"name":"Tú Oanh","avatar":""},{"name":"Trình Mỹ Duyên","avatar":""},{"name":"Lưu Duy Khánh","avatar":""},{"name":"Vi Thường","avatar":""},{"name":"Trần Chiến","avatar":""},{"name":"Vũ Thanh Tú","avatar":""},{"name":"Hoa Thúy","avatar":""},{"name":"Hằng Nga","avatar":""},{"name":"Quỳnh Dương","avatar":""},{"name":"Châu Dương","avatar":""},{"name":"Vân Anh","avatar":""},{"name":"Hoàng Triều Dương","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad