INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-truong-kingstown-phan-3', 'Thị Trưởng Kingstown (Phần 3)', 'Mayor Of Kingstown (Season 3)', 'https://phimimg.com/upload/vod/20251101-1/a174d30b90d66b7cecda3896435f7e0f.jpg', 'https://phimimg.com/upload/vod/20251101-1/5ff95a896f37266314070fa0150c7da6.jpg', '<p>Tại một thị trấn nhỏ ở Michigan, nơi kinh doanh nhà tù là ngành phát đạt duy nhất, gia đình McClusky là những người môi giới quyền lực giữa cảnh sát, tội phạm, tù nhân, cai ngục và chính trị gia trong một thành phố hoàn toàn phụ thuộc vào nhà tù và những tù nhân mà họ giam giữ.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jeremy Renner","avatar":""},{"name":"Hugh Dillon","avatar":""},{"name":"Tobi Bamtefa","avatar":""},{"name":"Taylor Handley","avatar":""},{"name":"Derek Webster","avatar":""},{"name":"Hamish Allan-Headley","avatar":""},{"name":"Edie Falco","avatar":""},{"name":"Lennie James","avatar":""},{"name":"Laura Benanti","avatar":""},{"name":"Necar Zadegan","avatar":""},{"name":"Nishi Munshi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["O Dono de Kingstown","El Jefe de Kingstown","Mayor of Kingstown"]', 1784690324177);
