INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hieu-ung-nha-trang', 'Hiệu Ứng Nhà Trắng', 'The White House Effect', 'https://phimimg.com/upload/vod/20251101-1/92a4e6f81a056053e9c31c1df08e52ac.jpg', 'https://phimimg.com/upload/vod/20251101-1/b4fc0b28026b39087d6233b788728dac.jpg', '<p>Ba thập kỷ trước, thế giới từng ở ngưỡng cửa ngăn chặn biến đổi khí hậu toàn cầu. Bộ phim được dựng hoàn toàn từ tư liệu lưu trữ, kể lại câu chuyện nguồn gốc đầy kịch tính của cuộc khủng hoảng khí hậu — và cách một cuộc chiến chính trị trong chính quyền Tổng thống George H. W. Bush đã thay đổi tiến trình lịch sử nhân loại.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"George H. W. Bush","avatar":""},{"name":"Ronald Reagan","avatar":""},{"name":"William K. Reilly","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["O Efeito Casa Branca","白宫效应：气候危机角力战","Efekt Białego Domu","The White House Effect: Klimatet och politiken","Beyaz Saray Etkisi","白宫效应","The White House Effect"]', 1784690324177);
