INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lucky-star', 'Con Bạc Hoàn Lương', 'Lucky Star', 'https://phimimg.com/upload/vod/20251031-1/4e039c520815472be0b97a9864fda093.jpg', 'https://phimimg.com/upload/vod/20251031-1/0333140fb697c32203d8d5d2f6c68c6f.jpg', '<p>Khi Lucky, một cựu con bạc hoàn lương, trở thành nạn nhân của một vụ lừa đảo thuế, anh buộc phải trở lại bàn poker để kiếm lại số tiền đã mất — trong khi gia đình anh chật vật xoay xở từng ngày để duy trì cuộc sống.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Terry Chen","avatar":""},{"name":"Olivia Cheng","avatar":""},{"name":"Conni Miu","avatar":""},{"name":"Andrew Phung","avatar":""},{"name":"Austyn Van de Kamp","avatar":""},{"name":"John Dylan Louie","avatar":""},{"name":"CJ Collard","avatar":""},{"name":"Summer Ly","avatar":""},{"name":"Isra Abdelrahim","avatar":""},{"name":"Mary Armstrong","avatar":""},{"name":"Carlo Cuizon","avatar":""},{"name":"Dustin Nelson","avatar":""},{"name":"Sharon Umeh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Lucky Star"]', 1784690324177);
