INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-giam-ho', 'Người Giám Hộ', 'Million Dollar Baby', 'https://phimimg.com/upload/vod/20251031-1/d79cbe9916d7364eb7b0518f6af707e4.jpg', 'https://phimimg.com/upload/vod/20251031-1/50de5eacbf4aa6480c2b997dcf564f39.jpg', '<p>Sung Seo-Yeon (Kang Shin), 18 tuổi, là một học sinh trung học, con cái trong một gia đình tái hôn, luôn cảm thấy bản thân là một kẻ dư thừa và thường xuyên bị tổn thương bởi chính những người thân. Ước mơ lớn nhất của cô là rời khỏi gia đình và sống một cuộc đời tự lập. Một ngày nọ, Seo-Yeon trúng số độc đắc trị giá 5 tỷ won, nhưng cô phát hiện ra rằng trẻ vị thành niên không đủ điều kiện nhận thưởng. Để có được số tiền đó, cô tìm đến Hwang Yi-Deun (Jo Joon-Young), 20 tuổi, học cùng trường — con trai của một gia đình giàu có, vừa thất bại trong việc du học và trở về Hàn Quốc. Seo-Yeon đề nghị Yi-Deun trở thành người giám hộ hợp pháp của mình, mở đầu cho một câu chuyện đầy mâu thuẫn, toan tính và cảm xúc tuổi trẻ.</p>', 'Hoàn Tất (2/2)', 2, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Cho Jun-young","avatar":""},{"name":"Ro Jong-hyun","avatar":""},{"name":"Baek Seo-hoo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324177);
