INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-thuy-thuong-tru-tai-xu-waverly-phan-1', 'Phù Thủy Thường Trú Tại Xứ Waverly (Phần 1)', 'Wizards Beyond Waverly Place (Season 1)', 'https://phimimg.com/upload/vod/20251030-1/3e94e17783689ee8ec45a9c78966b2f8.jpg', 'https://phimimg.com/upload/vod/20251030-1/f50ed7fe1e593f82ee02ba9a5393a6d4.jpg', '<p>Justin Russo đã lựa chọn cuộc sống người thường bên người vợ và các con của mình, Giada, Roman và Milo. Nhưng một ngày, người em gái của Justin - Alex mang theo Billie để nhờ vả giúp đỡ huấn luyện, Justin nhận ra, anh cần phải sử dụng những kĩ năng phù thủy của mình để giúp đỡ cho Phù thủy trẻ tiềm năng này. Một sự pha trộn giữa thế giới đương đại và Thế giới Phù thủy giữa lòng Waverly.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Janice LeAnn Brown","avatar":""},{"name":"Alkaio Thiele","avatar":""},{"name":"Max Matenko","avatar":""},{"name":"Taylor Cora","avatar":""},{"name":"Mimi Gianopulos","avatar":""},{"name":"David Henrie","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["少年魔法师续集","Magi efter Waverly Place","Waverly hely: Az új varázslók","우리 가족 마법사 리부트","우리 가족 또 다른 마법사","우리 가족 또다른 마법사","우리가족 또 다른 마법사","우리가족 또다른 마법사","Чаклуни поза Вейверлі","Wizards Beyond Waverly Place"]', 1784690324177);
