INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('phu-thuy-thuong-tru-tai-xu-waverly-phan-1', 'Phù Thủy Thường Trú Tại Xứ Waverly (Phần 1)', 'Wizards Beyond Waverly Place (Season 1)', 'phù thủy thường trú tại xứ waverly (phần 1) wizards beyond waverly place (season 1) janice leann brown alkaio thiele max matenko taylor cora mimi gianopulos david henrie 少年魔法师续集 magi efter waverly place waverly hely: az új varázslók 우리 가족 마법사 리부트 우리 가족 또 다른 마법사 우리 가족 또다른 마법사 우리가족 또 다른 마법사 우리가족 또다른 마법사 чаклуни поза вейверлі wizards beyond waverly place', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ly-thoi-lau-ca', 'Lý Thời Láu Cá', 'The Slick Guy', 'https://phimimg.com/upload/vod/20251026-1/d5d83996ff4f1d66171015dfa63145b1.jpg', 'https://phimimg.com/upload/vod/20251026-1/5d8755f90c5f986ed444aa6049b8bf0c.jpg', '<p>Năm Thiên Khánh thứ ba mươi ba, hai vị thái y Lý, Tống phụng mệnh Thiên Khánh Đế trải qua đau khổ tìm kiếm thần dược &quot;Không có kết quả&quot;, lại ngoài ý muốn gây thành đại họa, hai nhà cũng bởi vì một cọc đạo dược hiểu lầm thâm cừu ám kết. Nhiều năm sau, hậu nhân của thần y Lý Khoát là Lý Thời lưu lạc làm bác sĩ thú y nghèo túng, chưa từng nghĩ bởi vì ở Hợp Hoan lâu thành công cứu tính mạng mà thành danh trong một trận chiến trên phố. Cùng lúc đó, hậu nhân kẻ thù Tống Như Tuyết đổi tên đổi họ giấu diếm Lý Thời bên người tùy thời mưu sát, cũng không ngờ ngoài ý muốn bị thương, trong quá trình ở chung chăm sóc, trong lòng hai người nảy sinh tình cảm lẫn nhau. Tay cầm nhật ký tìm thuốc tiền bối lưu lại, Lý Thời cùng tam thúc Lý Nhất Phong, Tống Như Tuyết bước lên con đường tìm kiếm thần dược thất truyền đã lâu &quot;Không có kết quả&quot;, ba người đều mang tâm tư nhỏ nhặt, một đường 囧 sự tình không ngừng, theo nữ tử đứng đầu Hợp Hoan lâu Mộng Phạm, nữ chưởng quỹ Nghênh Xuân Hoa thân phận chân tướng rõ ràng, Thiên Khánh đế ngoài ý muốn cải tử hồi sinh, bí ẩn năm đó cuối cùng bị vạch trần......</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Diệu Tường","avatar":""},{"name":"Dương Cửu Lang","avatar":""},{"name":"Bùi Thần Vĩ","avatar":""},{"name":"Quách Tiểu Khôi","avatar":""},{"name":"Tông Mộc Tử","avatar":""},{"name":"Trương Tiểu Oản","avatar":""},{"name":"Ngô Hiệu Húc","avatar":""},{"name":"Vương Nam Thiên","avatar":""},{"name":"Khúc Thiếu Thạch","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Slick Boy","You''re so naughty, Li Shi","李时你是真顽皮"]', 1784690324177);
