INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-do-ky-dam', 'Lâm Đô Kỳ Đàm', 'Northeast Folktales', 'https://phimimg.com/upload/vod/20251026-1/11f11927e8fa9d2037ac5aedd7c6b4ca.jpg', 'https://phimimg.com/upload/vod/20251026-1/88b375b02a021f1b1be13234ca068d7d.jpg', '<p>Vào thời Dân Quốc, Vọng Thôn trong núi sâu lưu truyền không ít truyền thuyết chí quái. Một nhân viên văn hóa đến từ thành phố, đi sâu thăm hỏi huyện Chí, phát hiện chân tướng phía sau một loạt hiện tượng ly kỳ như da vàng bái Nguyệt, chuột tinh báo thù, bạch tiên chữa bệnh, hồ tiên báo ân, đấu pháp của Xà Tiên nương, v. v., đã tái nguyên cuộc đời hữu tình hữu nghĩa của một nhân vật truyền kỳ.</p>', 'Full', 1, 'single', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cuối Trí Gia","avatar":""},{"name":"Lưu Quán Lân","avatar":""},{"name":"Trần Sáng","avatar":""},{"name":"Tống Gia Đằng","avatar":""},{"name":"Phụ Hác An Kỳ","avatar":""},{"name":"Lý Côn Anh","avatar":""},{"name":"Hà Thông Nghị","avatar":""},{"name":"Vu Tân Hà","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Strange Story of Lindu","林都奇谭"]', 1784690324177);
