INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lam-do-ky-dam', 'Lâm Đô Kỳ Đàm', 'Northeast Folktales', 'lâm đô kỳ đàm northeast folktales cuối trí gia lưu quán lân trần sáng tống gia đằng phụ hác an kỳ lý côn anh hà thông nghị vu tân hà the strange story of lindu 林都奇谭', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoan-nghenh-em-den-ben-toi', 'Hoan Nghênh Em Đến Bên Tôi', 'Welcome To My Side', 'https://phimimg.com/upload/vod/20251026-1/a44466fbba844d10f1e8414cb0de5933.jpg', 'https://phimimg.com/upload/vod/20251026-1/d68cb84660452930560397cb979cef5b.jpg', '<p>Phim kể về Trần Tiểu Chu (do Vu Thích thủ vai) — sau khi thất tình, anh gặp phải một tai nạn ngoài ý muốn. Từ đó, anh thường xuyên nhìn thấy những đàn vịt cao su “cạp cạp” bay quanh mình, khiến cuộc sống trở nên rối loạn. Mãi đến khi Phùng Giai Nam (do Vương Ảnh Lộ thủ vai) xuất hiện, Trần Tiểu Chu kinh ngạc phát hiện rằng chỉ cần ở bên cô, những con vịt kia sẽ biến mất. Và thế là, một hành trình lãng mạn xen lẫn dở khóc dở cười bắt đầu…</p>', 'Full', 1, 'single', 'completed', 15, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vũ Thích","avatar":""},{"name":"Vương Ảnh Lộ","avatar":""},{"name":"Hoàng Viêm","avatar":""},{"name":"Lưu Dương","avatar":""},{"name":"La Hồng","avatar":""},{"name":"Triệu Thiên Dương","avatar":""},{"name":"Mã Đại Trí","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Welcome to My Side","내 곁에 온 걸 환영해","欢迎来到我身边"]', 1784690324177);
