INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-cu-toi-loi', 'Chung Cư Tội Lỗi', 'The Unrighteous', 'https://phimimg.com/upload/vod/20251023-1/216b97974eede577fe4dce310f0f7102.jpg', 'https://phimimg.com/upload/vod/20251023-1/b802a8f0cd91e6e9e81d45566a62c72c.jpg', '<p>Trong một khu nhà chung cũ tên Wonjung Villa, Joo-hyun vô tình nhận được một tờ truyền đạo của một giáo phái và tiện tay bỏ nó vào hòm thư của Shin-hye. Từ đó, Shin-hye dần bị cuốn vào giáo phái ấy, mù quáng tin tưởng và sùng bái, rồi nhiệt tình truyền đạo cho hàng xóm, với hy vọng chữa lành căn bệnh cho cậu con trai ốm yếu của mình.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Hyun-woo","avatar":""},{"name":"Moon Jeong-hee","avatar":""},{"name":"Bang Min-ah","avatar":""},{"name":"Seong Byeong-suk","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Wonjeong Bil-la","Expedition Villa","Home, Sweet Home","Villa Wonjung","원정빌라"]', 1784690324177);
