INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cho-den-khi-toi-pha-huy-gia-dinh-cua-chong', 'Cho Đến Khi Tôi Phá Huỷ Gia Đình Của Chồng', 'Until I Destroyed My Husband''s Other Family', 'https://phimimg.com/upload/vod/20251020-1/592d023cd58180c79ff0bcb8acee67f6.jpg', 'https://phimimg.com/upload/vod/20251020-1/8e098e86e926b950a6348bb4399374e8.jpg', '<p>Kisaragi Minori, người từng nghĩ rằng mình có một gia đình hạnh phúc với tình yêu trong sáng từ khi còn là học sinh và đã kết hôn với chồng là Yudai, được ban phước với những đứa con, nhưng câu chuyện bắt đầu khi cô phát hiện ra rằng chồng mình đã lừa dối cô suốt 15 năm. Minori, người đã thề sẽ trả thù Yudai, người có một gia đình khác, và người tình của anh ta, Riko Miyake, lên kế hoạch trả thù bằng cách sử dụng con trai của Riko, Wataru.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Marika Matsumoto","avatar":""},{"name":"Terunosuke Takezai","avatar":""},{"name":"Maho Nonami","avatar":""},{"name":"Kouta Nomura","avatar":""},{"name":"Yumi Aso","avatar":""},{"name":"Rina Ohta","avatar":""},{"name":"Miku Tanaka","avatar":""},{"name":"Masaki Ota","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Otto no Katei wo Kowasu Made","夫の家庭を壊すまで"]', 1784690324177);
