INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cho-den-khi-toi-pha-huy-gia-dinh-cua-chong', 'Cho Đến Khi Tôi Phá Huỷ Gia Đình Của Chồng', 'Until I Destroyed My Husband''s Other Family', 'cho đến khi tôi phá huỷ gia đình của chồng until i destroyed my husband''s other family marika matsumoto terunosuke takezai maho nonami kouta nomura yumi aso rina ohta miku tanaka masaki ota otto no katei wo kowasu made 夫の家庭を壊すまで', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-khau-duyen-khoi', 'Thanh Khâu Duyên Khởi', 'Lost Destiny', 'https://phimimg.com/upload/vod/20251020-1/902df6d075a9abca576a31ebf74e0e92.jpg', 'https://phimimg.com/upload/vod/20251020-1/35eb56f6d283a7f927e59eee1c52e691.jpg', '<p>Bộ phim là một câu chuyện tình yêu huyền ảo giữa thiếu niên thư sinh Bồ Tùng Lăng và hồ ly chín đuôi. Câu chuyện kể về Bồ Tùng Lăng trên đường đi thi mà yêu quái hoành hành đã gặp hồ ly chín đuôi đến tìm mình để báo đáp ân tình từ kiếp trước tên là Tố Tiên. Tố Tiên nhiều lần bảo vệ Bồ Tùng Lăng, khiến Bồ Tùng Lăng rơi vào lưới tình với cô. Nhưng sau khi biết được thân phận thực sự của Tố Tiên, Bồ Tùng Lăng không thể chấp nhận việc cô là hồ yêu, nên chia tay và tiếp tục đi thi một mình. Tố Tiên lặng lẽ theo sau, nhiều lần bảo vệ và cuối cùng hy sinh nội đan cho xà yêu để cứu Bồ Tùng Lăng, cuối cùng đồng quy vu tận với xà yêu. Bồ Tùng Lăng lúc này cảm nhận được sự chân thật và thiện lương của Tố Tiên, từ bỏ định kiến về yêu quái và chân thành đối diện với tình cảm của mình.</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Khang Ninh","avatar":""},{"name":"Giả Chính Vũ","avatar":""},{"name":"Lý Mộng Úy","avatar":""},{"name":"Trương Nguyên Soái","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Story of Qing Qiu","青丘缘起"]', 1784690324177);
