INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tay-sung-ban-tia-2', 'Tay Súng Bắn Tỉa 2', 'Sniper 2', 'https://phimimg.com/upload/vod/20251020-1/5ba0515c715c94c2bd27faac3d54a28b.jpg', 'https://phimimg.com/upload/vod/20251020-1/bbfafe79e2805c97ae52ed98d0dd93c1.jpg', '<p>Nữ đặc cảnh bắn tỉa Tống Niệm cùng đồng đội sát cánh chiến đấu quyết liệt với bọn cướp xe vận chuyển kim cương. Đội trưởng đội đặc cảnh Hàn Tùng Lôi bị trọng thương khi bảo vệ đồng đội. Tống Niệm biến đau thương thành sức mạnh, sau đó tiến hành cuộc đấu trí đấu dũng với tay súng cướp Tô Tuyết và tên gian thương Trương Mạo Luân, cùng vạch trần âm mưu đằng sau vụ cướp kim cương và đưa bọn cướp ra trước pháp luật.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Từ Đông Đông","avatar":""},{"name":"Dương Ỷ","avatar":""},{"name":"Cao Thiên","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["狙击者 2"]', 1784690324177);
