INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngo-khong-dai-nao-su-da-linh', 'Ngộ Không Đại Náo Sư Đà Lĩnh', 'Monkey King Fight Lion Camel', 'https://phimimg.com/upload/vod/20240921-1/9cc13ece84764cd51bfb4d10ff699ecf.jpg', 'https://phimimg.com/upload/vod/20240921-1/a34d2fa05c89bd3149c67938d86eb357.jpg', '<p>Đường Tăng và các đồ đệ đi đến sườn núi Sư Đà, gặp phải dân làng Sư Đà tộc bị yêu quái bắt giữ. Khi Ngộ Không giải cứu họ, bị yêu quái nhận ra. Ngộ Không và Bát Giới mỗi người tự chiến đấu, nhưng chủ quan khinh địch, khiến cả nhóm trúng kế. Ba yêu vương với ba pháp bảo mạnh mẽ đã đánh bại Ngộ Không, tung tin rằng Đường Tăng đã bị ăn sống. Ngộ Không thất thần tìm Phật Tổ giúp đỡ, hiểu ra rằng chim đơn côi khó bay, cần sự đoàn kết và hợp tác. Ba huynh đệ hợp lực, may mắn được Bồ Tát trợ giúp, cuối cùng giải cứu những người dân còn lại. Bốn thầy trò tiếp tục lên đường Tây Trúc, đoàn kết không chia lìa.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 1, '[{"name":"Tạ Miêu","avatar":""},{"name":"Ân Tĩnh","avatar":""},{"name":"Chải Viên Lạc","avatar":""},{"name":"Kim Gia Ngộ","avatar":""},{"name":"Lôi Lôi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Make a Scene of Lion Camels Ridge","손오공대요사타령","孙悟空大闹狮驼岭"]', 1784690324177);
