INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-dac-canh-phan-cong', 'Nữ Đặc Cảnh Phản Công', 'SWAT: Angels In Mission', 'https://phimimg.com/upload/vod/20251020-1/a7a484845bfa138d82168e400afc7557.jpg', 'https://phimimg.com/upload/vod/20251020-1/f269b71b628eea367a9e1f876d85d2e5.jpg', '<p>Chim Ruồi, để cứu anh trai Kền Kền, đã lén trở về nước và nhanh chóng tập hợp lại thuộc hạ cũ của Kền Kền, tổ chức các hoạt động khủng bố nhắm vào cảnh sát. Trước mối đe dọa từ Chim Ruồi, các đặc cảnh không lùi bước mà khéo léo lên kế hoạch dựa trên những điểm yếu trong tính cách của đối phương. Các đặc cảnh thế hệ mới như Mai Tĩnh, Lương Tráng cùng thế hệ đặc viên trung niên là Cục trưởng Cao và Mai Hiểu Đông đã phối hợp chặt chẽ trong các hành động, cuối cùng nhổ tận gốc băng nhóm tội phạm tàn ác.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Thẩm Thái","avatar":""},{"name":"Hà Mỹ Huyên","avatar":""},{"name":"Dương Tử Hoa","avatar":""},{"name":"Vương Bác Thanh","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["여특경 : 역전","Nữ Đặc Cảnh Phản Công","女特警之逆战"]', 1784690324177);
