INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mieu-linh-quy-su', 'Miêu Lĩnh Quỷ Sự', 'Horror Legend Of Miao Ling', 'https://phimimg.com/upload/vod/20251020-1/570d1b6c615ede352cb44efcee15e412.jpg', 'https://phimimg.com/upload/vod/20251020-1/5382d70567573ef20ee2486a27c6e9b5.jpg', '<p>Trong những năm cuối thời Dân Quốc, ở một vùng núi hẻo lánh, một vài người dân trong làng đã đi đào mộ ban đêm và gặp phải tai họa. Lục Văn Lương và Trương Trì Nghĩa phát hiện những điều kỳ quái về xác chết, và hai người quyết định điều tra vụ việc ở &quot;làng đoản mệnh&quot;. Nhưng không ngờ, người dân trong làng tin rằng đó là lời nguyền từ 20 năm trước của bà phù thủy, và hai người trở thành đối tượng bị ghét bỏ vì đã phá hỏng nghi lễ trừ tà. Sự thật chỉ cách họ một bước, nhưng họ không biết rằng mình đã dấn thân vào nguy hiểm...</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Quán Lân","avatar":""},{"name":"Trương Đạt","avatar":""},{"name":"Lương Tụng Thanh","avatar":""},{"name":"Viên Tưởng Nhân","avatar":""},{"name":"Ỷ Linh","avatar":""},{"name":"Vương Chí Bằng","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["苗岭诡事 鬼吹灯外传之苗疆蛊婆","苗嶺詭事","苗岭诡事"]', 1784690324177);
