INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('grande-maison-tokyo-dac-biet', 'Grande Maison Tokyo Đặc biệt', 'Grande Maison Tokyo Special', 'https://phimimg.com/upload/vod/20251020-1/b8339f4f6787a67c2df4eee67b76a4a7.jpg', 'https://phimimg.com/upload/vod/20251020-1/1481e3f1c749ce348437e730d54d8ee5.jpg', '<p>Chỉ sau một năm khai trương, Hayami Rinko đã trở thành người phụ nữ châu Á đầu tiên làm bếp trưởng của một nhà hàng đạt ba sao Michelin. Tuy nhiên, không lâu sau đó, đại dịch COVID-19 bùng phát, khiến ngành ẩm thực và nhà hàng chịu ảnh hưởng nặng nề — và “Grand Maison Tokyo” cũng không ngoại lệ. Để duy trì hoạt động, nhà hàng buộc phải hợp tác với một công ty tư vấn ẩm thực thuộc tập đoàn lớn, đồng thời tìm hướng đi mới thông qua sản xuất thực phẩm đông lạnh bán qua đường bưu điện và xây dựng các trang web chia sẻ công thức nấu ăn…</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Takuya Kimura","avatar":""},{"name":"Kyoka Suzuki","avatar":""},{"name":"Yuta Tamamori","avatar":""},{"name":"Mitsuhiro Oikawa","avatar":""},{"name":"Ikki Sawamura","avatar":""},{"name":"Kikunosuke Onoe V","avatar":""},{"name":"Kanichiro Sato","avatar":""},{"name":"Ai Tominaga","avatar":""},{"name":"Ayako Yoshitani","avatar":""},{"name":"Anne Nakamura","avatar":""},{"name":"Aki Asakura","avatar":""},{"name":"Masataka Kubota","avatar":""},{"name":"Kazuki Kitamura","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Grand Maison Tokyo Special","La Grande Maison Tokyo Special","グランメゾン東京 スペシャル"]', 1784690324177);
