INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-choi-cua-ba-nguoi-tatsulok-tatlo-magkasalo', 'Cuộc Chơi Của Ba Người (Tatsulok: Tatlo Magkasalo)', 'Triangle', 'https://phimimg.com/upload/vod/20251020-1/f14d0e74634169217d2f512eb3c8c6c4.jpg', 'https://phimimg.com/upload/vod/20251020-1/acf2bbefb613638e9799eae79d640973.jpg', '<p>Câu chuyện xoay quanh một cặp vợ chồng hạnh phúc bất ngờ được một người bạn cũ ghé thăm. Tuy nhiên, sự xuất hiện của người bạn này đã khuấy đảo cuộc sống yên bình của họ, khi anh ta vướng vào mối quan hệ tình cảm và thể xác với cả người chồng lẫn người vợ, khiến mọi thứ trở nên rối ren và đầy kịch tính.</p>', 'Full', 1, 'single', 'completed', 19, 2024, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Mariane Saint","avatar":""},{"name":"Marlon Marcia","avatar":""},{"name":"Skye Gonzaga","avatar":""},{"name":"Daniela Carolino","avatar":""},{"name":"Mianne Agualada","avatar":""},{"name":"Byuti Veloso","avatar":""},{"name":"Jeffrey Carl Baltazar","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Tatsulok: Tatlo Magkasalo"]', 1784690324177);
