INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-nai-nokotan-cua-toi-shikanoko-nokonoko-koshitantan', 'Bạn Nai Nokotan Của Tôi (Shikanoko Nokonoko Koshitantan)', 'My Deer Friend Nokotan', 'https://phimimg.com/upload/vod/20251018-1/e68ac8a498fb4db031bb8d8278352a1f.jpg', 'https://phimimg.com/upload/vod/20251018-1/cfbc4e1c264908eafce0b43188eeffc2.jpg', '<p>Hỡi con người, hãy &quot;nai&quot; lên! &nbsp;Toraishi Torako là nữ sinh tại trường cấp ba Hino Minami, Tokyo. Một ngày nọ, khi đang đến trường, cô bỗng thấy lạnh toát sống lưng. Ngẩng đầu lên, cô thấy một cô gái với nước mũi chảy thòng lòng đang bị kẹt sừng trên dây điện!? Cuộc sống của cô học sinh gương mẫu (bề ngoài), đã bị đảo lộn. Và thế là câu chuyện gái (một cựu nữ quái) gặp nai (?) đã bắt dầu!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 27, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Megumi Han","avatar":""},{"name":"Saki Fujita","avatar":""},{"name":"Rui Tanabe","avatar":""},{"name":"Fuka Izumi","avatar":""},{"name":"Kohsuke Toriumi","avatar":""},{"name":"Yurika Kubo","avatar":""},{"name":"Rio Tsuchiya","avatar":""},{"name":"Chinatsu Akasaki","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Học Đường","slug":"hoc-duong","id":"01c8abbb7796a1cf1989616ca5c175e6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["鹿乃子大摇大摆虎视眈眈","鹿乃子乃子乃子虎视眈眈","My Deer Friend Nokotan","Shikanoko Nokonoko Koshitantan","사슴아이어슬렁어슬렁호시탐탐","사슴아이 어슬렁어슬렁 호시탐탐","사슴킥","Mi  Amiga Nokotan es un Ciervo","Моя подруга-олениха, Нокотан","Cô Bạn Nai Của Tôi","しかのこのこのここしたんたん"]', 1784690324177);
