INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('so-canh-sat-chicago-phan-12', 'Sở Cảnh Sát Chicago (Phần 12)', 'Chicago P.D. (Season 12)', 'https://phimimg.com/upload/vod/20250422-1/82f75b9eed0b7f936dab8b5b12a45e8d.jpg', 'https://phimimg.com/upload/vod/20250422-1/dbcf9b186be60f3f433b5637be76dbce.jpg', '<p>Một bộ phim hình sự hấp dẫn xoay quanh những người đàn ông và phụ nữ thuộc Đội 21 của Sở Cảnh sát Chicago, những người luôn sẵn sàng hy sinh tất cả để phục vụ và bảo vệ cộng đồng của họ. Đội 21 bao gồm hai nhóm rất khác biệt: các cảnh sát mặc đồng phục tuần tra trên đường phố, trực tiếp đối mặt với tội phạm đường phố; và Đơn vị Tình báo chuyên xử lý các vụ án nghiêm trọng hơn của thành phố – từ tội phạm có tổ chức, buôn bán ma túy, những vụ giết người gây chấn động và nhiều hơn thế nữa.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jason Beghe","avatar":""},{"name":"Marina Squerciati","avatar":""},{"name":"Patrick John Flueger","avatar":""},{"name":"LaRoyce Hawkins","avatar":""},{"name":"Benjamin Levy Aguilar","avatar":""},{"name":"Toya Turner","avatar":""},{"name":"Amy Morton","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["芝加哥警署","Chicago PD","اداره پلیس شیکاگو","One Chicago","Chicago P.D."]', 1784690324177);
