INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tee-yod-quy-an-tang-2', 'Tee Yod: Quỷ Ăn Tạng 2', 'Death Whisperer 2', 'https://phimimg.com/upload/vod/20250207-1/82c414e93dc3f9643b57b140160e2a71.jpg', 'https://phimimg.com/upload/vod/20250207-1/3ba031e042bf609d8c6b0cf6961f2d76.jpg', '<p>Ba năm sau cái chết của Yam, Yak vẫn tiếp tục săn lùng linh hồn bí ẩn mặc áo choàng đen. Gặp một cô gái có triệu chứng giống Yam, Yak phát hiện ra người bảo vệ linh hồn, pháp sư ẩn dật Puang, sống trong một khu rừng đầy nguy hiểm. Giữa những phép thuật ma quỷ và những sinh vật nguy hiểm. Khi họ đuổi theo linh hồn mặc áo choàng đen, tiếng kêu đầy ám ảnh của Tee Yod sắp quay trở lại một lần nữa...</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Thái Lan', 1, '[{"name":"Nadech Kugimiya","avatar":""},{"name":"Ongart Cheamcharoenpornkul","avatar":""},{"name":"Kajbhunditt Jaidee","avatar":""},{"name":"Peerakrit Phacharaboonyakiat","avatar":""},{"name":"Denise Jelilcha Kapaun","avatar":""},{"name":"Rattanawadee Wongtong","avatar":""},{"name":"Nutthacha Padovan","avatar":""},{"name":"Paramej Noiam","avatar":""},{"name":"Arisara Wongchalee","avatar":""},{"name":"Phiravich Attachitsataporn","avatar":""},{"name":"Sahatchai Chumrum","avatar":""},{"name":"Todsapol Mai","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Tee Yod 2","Susurros Mortales 2","噬魂灵声2","Ölümü Fısıldayan 2","鬼滴语2","ธี่หยด 2"]', 1784690324177);
