INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-la-canh-sat-hinh-su', 'Tôi Là Cảnh Sát Hình Sự', 'We Are Criminal Police', 'https://phimimg.com/upload/vod/20241128-1/141eb97ae755a183e67d97734ee28cc6.jpg', 'https://phimimg.com/upload/vod/20241128-1/f242457e3f121b85cd505877cc8aaffc.jpg', '<p>Tần Xuyên, cùng hai người bạn thân là Diệp Mậu Sinh và Lý Văn, sau khi tốt nghiệp Học viện Cảnh sát đã mang theo giấc mơ trở thành anh hùng và cảnh sát hình sự quay về quê hương, trở thành những cảnh sát bình thường tại đồn công an địa phương. Tuy nhiên, khoảng cách lớn giữa thực tế và lý tưởng không khiến anh từ bỏ việc theo đuổi ước mơ của mình. Trong một lần tình cờ, Tần Xuyên tay không chế ngự một tên tội phạm đang âm mưu gây ra vụ nổ, mở ra bước ngoặt mới trong sự nghiệp cảnh sát hình sự của anh. Dưới sự dẫn dắt của cấp trên, anh dần trưởng thành và lần lượt phá được nhiều vụ án lớn gây chấn động cả nước.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 10, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Vũ Hòa Uy","avatar":""},{"name":"Phú Đại Long","avatar":""},{"name":"Đinh Vũ Đái","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["中国刑警","Wo Shi Xing Jing","我是刑警","We Are Criminal Police","i am police","I am a detective"]', 1784690324177);
