INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-hoach-hoi-sinh-tieu-thu-tai-phiet', 'Kế Hoạch Hồi Sinh Tiểu Thư Tài Phiệt', 'Raising A Hikikomori Heiress', 'https://phimimg.com/upload/vod/20251014-1/fa763688c6ecc650f44bfa43d94661f4.jpg', 'https://phimimg.com/upload/vod/20251014-1/57dc6d029a4d991126d643c1b0568405.jpg', '<p>Một người đàn ông bước vào căn nhà sang trọng. Nhiệm vụ của anh là đưa cô tiểu thư tài phiệt tự kỷ ra khỏi phòng. Anh tên Lim Hyung Joon, đã vượt qua tỷ lệ chọi 300:1 đầy khốc liệt để trở thành &quot;chồng hợp đồng&quot; của cô. Vì một lý do khó nói, Kim Hyo Jin đã khóa chặt bản thân trong phòng, suốt ngày chỉ ăn mì gói, chơi game, sống một cuộc đời tách biệt với thế giới bên ngoài. Thế nhưng sự xuất hiện của người đàn ông này đã hoàn toàn phá vỡ nhịp sống yên tĩnh của cô. Trước những chiêu trò dụ dỗ bằng đồ ăn của anh, Kim Hyo Jin hết sức khinh thường. Nhưng dần dần, cô nhận ra anh không giống những người đàn ông chỉ biết đến tiền. Anh cùng cô chơi game, nấu ăn cho cô, dùng sự ấm áp mà cô không thể kháng cự từng chút một làm tan chảy bức tường bao quanh trái tim cô. Kim Hyo Jin bắt đầu nảy sinh những cảm xúc khác lạ với người &quot;chăm nuôi&quot; này. Thế nhưng cô không hề biết rằng, Lim Hyung Joon từ lâu đã nắm rõ mọi điều về cô nhờ vào cuốn &quot;Bách khoa toàn thư Kim Hyo Jin&quot;. Đúng lúc ấy, cô em gái thảo mai Kim Hee Jin và cậu bạn thân điên rồ Kyung Min xuất hiện. Để chuẩn bị cho đại hội cổ đông sẽ diễn ra sau một tuần nữa, hai vợ chồng bắt đầu vạch ra &quot;Kế hoạch biến Kim Hyo Jin thành chiến thần xã giao&quot;. Khi những ngày tháng bình yên bị phá vỡ, âm mưu gia tộc cùng mối tình méo mó dần lộ diện. Liệu Kim Hyo Jin có thể vượt qua cú sốc quá khứ từng giam cầm cô trong căn phòng kia, và chiến thắng cả đường đua sự nghiệp lẫn đường tình hay không?</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 15, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Dong-hyun","avatar":""},{"name":"Kim Jung-yeon","avatar":""},{"name":"Sung Eun Woo","avatar":""},{"name":"Lee Sang-hoon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phim Ngắn","slug":"phim-ngan","id":"4f02d28224c0747511790d57fbb63a62"}]', '["Raising Heirs Who Became Hikikomori","히키코모리 재벌키우기","히키코모리 재벌 키우기"]', 1784690324177);
