INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-muon-o-ben-anh', 'Em Muốn Ở Bên Anh', 'Love Beside Me', 'https://phimimg.com/upload/vod/20251013-1/5bf6ab20986ec098d0b4b8f355b30a83.jpg', 'https://phimimg.com/upload/vod/20251013-1/8b460b637e93f71a4b73d81e7639b990.jpg', '<p>Bộ phim kể về một nhóm bạn trẻ bước vào ngưỡng cửa trưởng thành, nơi họ phải đối mặt với những lựa chọn giữa tình yêu, ước mơ và hiện thực.Lâm Ánh Đồng vào vai một cô gái nhiệt huyết, lạc quan, luôn tin rằng chỉ cần nỗ lực hết mình thì hạnh phúc sẽ đến. Cô gặp một chàng trai hiền lành, chân thành (do Hoàng Hoành Hiên thủ vai), người dần trở thành chỗ dựa tinh thần cho cô giữa những biến động của cuộc sống.Trong hành trình theo đuổi ước mơ, họ cùng trải qua những hiểu lầm, chia ly và tổn thương, nhưng cũng chính từ đó mà học được ý nghĩa thật sự của tình yêu và sự trưởng thành.Bộ phim mang đến cảm xúc nhẹ nhàng, trong trẻo, đậm chất thanh xuân, với thông điệp rằng:“Yêu không chỉ là ở bên nhau, mà là cùng nhau trưởng thành.”</p>', 'Full', 1, 'single', 'completed', 15, 2024, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Lâm Ánh Đồng","avatar":""},{"name":"Hoàng Hoành Hiên","avatar":""},{"name":"Đồ Thiện Tồn","avatar":""},{"name":"Tịch Duy Lân","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["My Secret Romance","我想和你在一起"]', 1784690324177);
