INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('em-muon-o-ben-anh', 'Em Muốn Ở Bên Anh', 'Love Beside Me', 'em muốn ở bên anh love beside me lâm ánh đồng hoàng hoành hiên đồ thiện tồn tịch duy lân my secret romance 我想和你在一起', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-cua-con-gai', 'Mẹ Của Con Gái', 'Daughter''s Daughter', 'https://phimimg.com/upload/vod/20251014-1/db1b5db486a27e9d3ab49a52e2fd79dd.jpg', 'https://phimimg.com/upload/vod/20251014-1/db12e364623d55c99026331afdc0e7bf.jpg', '<p>Bộ phim xoay quanh mối quan hệ phức tạp, sâu sắc và nhiều tổn thương giữa ba thế hệ phụ nữ trong một gia đình — bà ngoại, người mẹ và cô con gái. Trương Ái Gia vào vai người mẹ, một phụ nữ từng mạnh mẽ, độc lập nhưng cũng mang trong lòng nhiều vết thương từ quá khứ. Lâm Gia Hân thủ vai người con gái, một phụ nữ hiện đại, thành đạt nhưng lạnh lùng, luôn cảm thấy mâu thuẫn và xa cách với mẹ mình. Trong khi đó, Lưu Dực Nhi đảm nhận vai đứa con gái nhỏ của Lâm Gia Hân, người đại diện cho thế hệ mới – hồn nhiên, chân thành nhưng cũng là tấm gương phản chiếu lại những sai lầm của thế hệ trước. Khi người mẹ lớn tuổi ngã bệnh, ba thế hệ phụ nữ buộc phải cùng đối diện với quá khứ, với những hiểu lầm, tổn thương và sự im lặng đã kéo dài suốt nhiều năm. Từng bước, họ học cách tha thứ, yêu thương và thấu hiểu nhau hơn. Phim khai thác tình mẫu tử qua nhiều góc độ – vừa ấm áp, vừa đau đớn, cho thấy rằng đôi khi, tình yêu giữa mẹ và con gái không cần lời nói, mà được thể hiện qua sự hy sinh, chịu đựng và thời gian.</p>', 'Full', 1, 'single', 'completed', 15, 2024, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Trương Ái Gia","avatar":""},{"name":"Lâm Gia Hân","avatar":""},{"name":"Lưu Dực Nhi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["母親的女兒"]', 1784690324177);
