INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-anh-hung-na-tra', 'Tiểu Anh Hùng Na Tra', 'The Little Hero Nezha', 'https://phimimg.com/upload/vod/20250919-1/e0d5c7dfab5d5738839dae2add154a89.jpg', 'https://phimimg.com/upload/vod/20250919-1/458542abce567832aa0017f82b573279.jpg', '<p>Được sinh ra một cách thần kỳ, Na Tra là một cậu bé bẩm sinh khác người, dần trưởng thành trở thành một tiểu anh hùng viết lại lịch sử của thời đại hỗn loạn. Na Tra học văn luyện võ, trừng trị kẻ ác, làm việc tốt, dẫn dắt dân chúng trồng trà, nuôi ngựa, làm giàu, củng cố sức mạnh... tất cả đều là vì cứu giúp người đời.</p>', 'Hoàn Tất (52/52)', 52, 'hoathinh', 'completed', 42, 2024, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Thần Thoại","slug":"than-thoai","id":"2276b29204c46f75064735477890afd6"}]', '["少年英雄小哪吒 第2季"]', 1784690324177);
