INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-ca-map', 'Cô Gái Cá Mập', 'Shark Girl', 'https://phimimg.com/upload/vod/20251014-1/028a1d40baad7690793bada2dd91ffaa.jpg', 'https://phimimg.com/upload/vod/20251014-1/250435fb196221d83b192e27eb45761c.jpg', '<p>Phim Shark Girl (2024) kể về Heidi, một cô gái trẻ đam mê mạng xã hội, bị cá mập đột biến cắn trong vùng biển ô nhiễm phóng xạ. Sống sót sau vụ tấn công, Heidi dần biến đổi — cơ thể và bản năng của cô hòa lẫn giữa người và cá mập, khiến cô khát máu và không thể kiểm soát.Khi hàng loạt vụ giết người bí ẩn xảy ra.</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Alexandra Corin Johnston","avatar":""},{"name":"Sumayyah Ameerah","avatar":""},{"name":"Nick Tag","avatar":""},{"name":"Ryan Bertroche","avatar":""},{"name":"Devon Odessa","avatar":""},{"name":"John Griffin","avatar":""},{"name":"Randolph Summiel","avatar":""},{"name":"Brian Guest","avatar":""},{"name":"Rob Zazzali","avatar":""},{"name":"Delaney Hogan","avatar":""},{"name":"Scott Connors","avatar":""},{"name":"Elle Chapman","avatar":""},{"name":"Patrick Luwis","avatar":""},{"name":"Gabrielle Montes de Oca","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["鲨鱼女孩","Shark Girl"]', 1784690324177);
