INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-diet-ca-map', 'Tiêu Diệt Cá Mập', 'Shark Warning', 'https://phimimg.com/upload/vod/20251014-1/59719e2a8d4b3c65e589748f6ebf94a8.jpg', 'https://phimimg.com/upload/vod/20251014-1/e18bef407d3faf4e8e64ca0ccb4f12bb.jpg', '<p>Hai thập kỷ sau, một người đàn ông trở về quê hương sau khi một con cá mập giết chết anh trai mình. Khi con cá mập nổi lên và cướp đi nhiều nạn nhân hơn, anh ta lập liên minh để săn lùng và tiêu diệt kẻ săn mồi một lần và mãi mãi.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"David Chokachi","avatar":""},{"name":"Andrew J Katers","avatar":""},{"name":"Angela Cole","avatar":""},{"name":"Rebecca Ritz","avatar":""},{"name":"Canyon Prince","avatar":""},{"name":"Lauren Pike","avatar":""},{"name":"James Dash","avatar":""},{"name":"Andi Rexha","avatar":""},{"name":"Gordon Mudd","avatar":""},{"name":"Stephen Girouard","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Blood in the Water","Shark Warning"]', 1784690324177);
