INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('le-tien-sinh-sung-the-vo-han', 'Lệ Tiên Sinh Sủng Thê Vô Hạn', 'Unlimited Love', 'https://phimimg.com/upload/vod/20251013-1/03cc1f5b5231ae468d541024ad625a05.jpg', 'https://phimimg.com/upload/vod/20251013-1/5aee0e6bf2807a27ef98b0c7e9d67076.jpg', '<p>Sau khi bị bạn trai phản bội, Hứa Niệm phát hiện ra hắn ta đã ngoại tình với cô em gái cùng cha khác mẹ của mình. Quá đau khổ, cô trở về nhà tìm cha để giãi bày, nhưng không ngờ lại bị chính cha ruột bán cho một công tử nhà giàu ăn chơi trác táng. Trong lúc liều mình trốn chạy, Hứa Niệm được Lệ Thừa Uyên cứu giúp. Không ngờ thuốc trong cơ thể cô phát tác, khiến hai người xảy ra quan hệ trong tình huống bất ngờ. Tưởng rằng đó chỉ là một đêm nghiệt duyên, nào ngờ người đàn ông ấy lại chính là cậu của gã bạn trai phản bội — hơn nữa, anh còn vừa gặp đã yêu Hứa Niệm. Từ đó, hai người bắt tay nhau vạch mặt đôi “tra nam tra nữ”, mở màn cho một câu chuyện trả thù và yêu thương đầy kịch tính.</p>', 'Hoàn Tất (85/85)', 85, 'series', 'completed', 18, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phim Ngắn","slug":"phim-ngan","id":"4f02d28224c0747511790d57fbb63a62"}]', '[]', 1784690324177);
