INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-cua-ban', 'Quái vật của bạn', 'Your Monster', 'https://phimimg.com/upload/vod/20251012-1/63e184b83309b19e3a3fdfa6e7457f9b.jpg', 'https://phimimg.com/upload/vod/20251012-1/d5ba1bf9d183242ba973dce07de199df.jpg', '<p>Sau khi cuộc sống tan vỡ, nữ diễn viên ăn nói nhẹ nhàng Laura Franco đã tìm lại được giọng nói của mình khi cô gặp một con quái vật đáng sợ nhưng lại kỳ lạ và quyến rũ sống trong tủ quần áo của mình.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Melissa Barrera","avatar":""},{"name":"Tommy Dewey","avatar":""},{"name":"Edmund Donovan","avatar":""},{"name":"Kayla Foster","avatar":""},{"name":"Taylor Trensch","avatar":""},{"name":"Brandon Victor Dixon","avatar":""},{"name":"Meghann Fahy","avatar":""},{"name":"Ikechukwu Ufomadu","avatar":""},{"name":"Matthew Lamb","avatar":""},{"name":"Lana Young","avatar":""},{"name":"Brian McCarthy","avatar":""},{"name":"Megan Haley","avatar":""},{"name":"Katy Grenfell","avatar":""},{"name":"Woody Fu","avatar":""},{"name":"Jawan M. Jackson","avatar":""},{"name":"Kasey Bella Suarez","avatar":""},{"name":"Matthe","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["هیولا","Your Monster"]', 1784690324177);
