INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vien-chinh-vo-hoi', 'Viễn Chinh Vô Hối', 'The Relentless Quest', 'https://phimimg.com/upload/vod/20251012-1/a1061891fbe94a91496d825ba0709eec.jpg', 'https://phimimg.com/upload/vod/20251012-1/06975f6c2e2efc7eae03bbd9040ef209.jpg', '<p>Một thiếu niên mang trong mình thiên mệnh, vì cứu vớt muôn dân mà kiên định bước lên con đường đầy gian khổ. Dẫu hành trình trắc trở, hiểm nguy bủa vây, lòng cậu vẫn không hề hối tiếc — chỉ mong thiên hạ sớm trở lại cảnh thái bình yên ổn.&nbsp;</p>', 'Hoàn Tất (7/7)', 7, 'hoathinh', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["无悔远征"]', 1784690324177);
