INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thua-lo-thanh-thu-phu-tu-tro-choi', 'Thua Lỗ Thành Thủ Phủ Từ Trò Chơi', 'The Richest Man In Game', 'https://phimimg.com/upload/vod/20251012-1/df680b4857675b91de9c159b56733160.jpg', 'https://phimimg.com/upload/vod/20251012-1/17ece8b848f970d18ad23fc9f226f2e0.jpg', '<p>Ngày gần đây, mời riêng phóng viên đối với Đằng Đạt tập đoàn tổng giám đốc Bùi Khiêm làm sưu tầm. Đằng Đạt tập đoàn hiện nay cổ giá trị đã đạt trăm tỉ cấp bậc, nghiệp vụ liên quan đến trò chơi, Inteet, chữ số phần cứng, văn hóa truyền thông, ăn uống các loại nhiều lĩnh vực, khắc sâu thay đổi mọi người sinh hoạt mọi phương diện.</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Shujun Lv","avatar":""},{"name":"Xiaozheng","avatar":""},{"name":"Shen Dawei","avatar":""},{"name":"Feng Junhua","avatar":""},{"name":"德智","avatar":""},{"name":"Guo Hongbo","avatar":""},{"name":"Xia Lei","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Kui Cheng Shoufu Cong Youxi Kaishi","Kuī Chéng Shǒu Fù Cóng Yóu Xì Kāi Shǐ","Kui Cheng Shou Fu Cong You Xi Kai Shi","はさんふごうざりっちぇすとまんいんげーむ","Hasan Fugou","HasanFugou","Стать игровым магнатом благодаря убыткам","Losing Money to Be a Tycoon","The.Richest.Man.in.Game","The Richest Man In Game","Thua Lỗ Thành Thủ Phủ Từ Trò Chơi","亏成首富从游戏开始"]', 1784690324177);
