INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-tuong-thu', 'Quái Tưởng Thụ', 'Whimsical Wish', 'https://phimimg.com/upload/vod/20251012-1/ee13b5cdf6a2a6769fbad2f44192e347.jpg', 'https://phimimg.com/upload/vod/20251012-1/b81e0b472117bb0befad788c3d19b374.jpg', '<p>Nội dung của anime xoay quanh những hiện tượng kỳ bí và các sự kiện siêu nhiên liên quan đến một nơi bí ẩn và tăm tối. Câu chuyện thường diễn ra trong một bối cảnh rùng rợn, nơi các nhân vật phải đối mặt với những tình huống đáng sợ và điều tra những bí ẩn không thể giải thích. Các yếu tố tâm lý và sự căng thẳng thường là trọng tâm của câu chuyện, tạo nên một trải nghiệm kịch tính cho người xem.</p>', 'Hoàn Tất (8/8)', 8, 'hoathinh', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Guai Xiang Shou","Whimsical Wish","Monster Sale","Strange idea for sale","Inspired Dragon","Strange Imaginings for Sale","Quái Tưởng Thụ","怪想售"]', 1784690324177);
