INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nai-long-va-tieu-that-dai-chien-bao-bao-long', 'Nãi Long Và Tiểu Thất Đại Chiến Bạo Bạo Long', 'Nailoong VS Bombloong', 'https://phimimg.com/upload/vod/20251012-1/9a7b1049f1e6b62a9a0af9930391497f.jpg', 'https://phimimg.com/upload/vod/20251012-1/9557b9bfee5643d9c66db2e970bad998.jpg', '<p>Trong một ngôi làng sơn thủy hữu tình, cuộc sống yên bình của Nãi Long và Tiểu Thất bị phá vỡ. Bạo Bạo Long muốn thay thế Nãi Long để trở thành con rồng mạnh nhất vũ trụ, nên đã giở đủ mọi trò quấy phá trong làng. Để ngăn chặn những hành động xấu xa đó, Nãi Long và Tiểu Thất đã dấn thân vào hàng loạt cuộc chiến anh dũng, tạo nên những câu chuyện vừa nghĩa hiệp, vừa ấm áp, hài hước và tràn đầy năng lượng tích cực — tất cả chỉ để bảo vệ vẻ đẹp thuần khiết trong trái tim mỗi người.</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 19, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Nai Long Yu Xiao Qi Zhi Da Zhan Bao Bao Long","奶龙与小七之大战暴暴龙"]', 1784690324177);
