INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nai-long-va-tieu-that-dai-chien-bao-bao-long', 'Nãi Long Và Tiểu Thất Đại Chiến Bạo Bạo Long', 'Nailoong VS Bombloong', 'nãi long và tiểu thất đại chiến bạo bạo long nailoong vs bombloong  nai long yu xiao qi zhi da zhan bao bao long 奶龙与小七之大战暴暴龙', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bua-toi-toi-nay-chinh-la-nguoi', 'Bữa Tối Tối Nay Chính Là Ngươi', 'Mythical Creatures Are My Dinners', 'https://phimimg.com/upload/vod/20251012-1/01d8f10d02b1c9cc861f90dce0c9d79a.jpg', 'https://phimimg.com/upload/vod/20251012-1/f6c0c85f2ee34782bb2239ff14ca9db5.jpg', '<p>Mặc Bạch, đại đệ tử của Thiên Cơ Môn, là người thiên tư hơn người nhưng lại chẳng mấy hứng thú với việc tu tiên — trong lòng chỉ có đam mê ăn uống và ước mơ nếm hết mỹ vị nhân gian. Trong một cơ duyên kỳ lạ, Mặc Bạch kết bạn với Tiểu Hắc, một yêu quái đầu bếp, và Tinh Hồng, sư muội cùng môn phái. Ba người họ cùng nhau lập nên “Đội Ẩm Thực Du Hành”, chu du khắp thiên hạ, săn tìm dị thú và món ăn kỳ vị. Thế nhưng, trên hành trình ngập tràn hương vị và tiếng cười ấy, họ lại vô tình khám phá ra bí mật động trời ẩn giấu sau cuộc hỗn loạn giữa người và yêu năm xưa…</p>', 'Hoàn Tất (32/32)', 32, 'hoathinh', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Jintian de Wancan Jiushi Ni","Jin Tian De Wan Can Jiu Shi Ni","Jīntiān De Wǎncān Jiùshì Nǐ","今天的晚餐是山海神兽！","Tonight''s Menu: Magical Beasts!","今天的晚餐就是你"]', 1784690324177);
