INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bua-toi-toi-nay-chinh-la-nguoi', 'Bữa Tối Tối Nay Chính Là Ngươi', 'Mythical Creatures Are My Dinners', 'bữa tối tối nay chính là ngươi mythical creatures are my dinners  jintian de wancan jiushi ni jin tian de wan can jiu shi ni jīntiān de wǎncān jiùshì nǐ 今天的晚餐是山海神兽！ tonight''s menu: magical beasts! 今天的晚餐就是你', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-phuong-hanh', 'Dữ Phượng Hành', 'The Legend of ShenLi', 'https://phimimg.com/upload/vod/20240310-1/759bbb161873247310b3ad71ac96d95b.jpg', 'https://phimimg.com/upload/vod/20240310-1/442c4194f981de53764aba49a92e9781.jpg', '<p>Bộ phim này được chuyển thể từ tiểu thuyết của Jiulu Feixiang. Vào thời cổ đại, nhiều vị thần đã chết nhưng chỉ có một vị thần cuối cùng là Xing Zhi sống sót. Hoàng đế Xing Zhi, không có bất kỳ cảm xúc hay ham muốn nào, đã sống ngoài bầu trời hàng chục ngàn năm. Trong cuộc chiến giữa thần và ác quỷ, anh đã một mình cứu vãn tình thế. Nhưng sau đó, anh ta từ chối gặp ai và không tìm thấy ở đâu cả. Vài trăm năm sau, nữ quỷ vương Thẩm Lệ ra đời với một viên ngọc trong miệng. Vào ngày sinh nhật thứ một nghìn của mình, cô được sắp xếp một cuộc hôn nhân vì liên minh chính trị. Trên đường thoát khỏi cuộc hôn nhân này, Thẩm Lệ bị tấn công và biến trở lại hình dạng phượng hoàng. Cô rơi xuống thế giới loài người trong tình trạng hôn mê với những vết thương nghiêm trọng. Một người bán hàng coi cô như một con gà béo, nhổ hết lông rồi nhốt vào lồng để bán. Thẩm Lệ tỉnh dậy, thấy mình đang ở trong hoàn cảnh này, tức giận đến ngã ngửa. Khi cô đang cảm thấy chán nản và tuyệt vọng, một người đàn ông mặc đồ trắng đen thanh tú dừng lại, trầm ngâm nhìn cô: “Tôi muốn con gà này.” Cứ như vậy, số phận của hai người đã gắn bó chặt chẽ với nhau vì sự buôn bán tưởng chừng như vô tình này.</p>', 'Hoàn Tất (39/39)', 39, 'series', 'completed', 9, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhao Liying","avatar":""},{"name":"Lin Gengxin","avatar":""},{"name":"Yunlai Xin","avatar":""},{"name":"Li Qianfeng","avatar":""},{"name":"He Yu","avatar":""},{"name":"Jackie Li","avatar":""},{"name":"Zeng Li","avatar":""},{"name":"Zhang Tianyang","avatar":""},{"name":"Wei Zixin","avatar":""},{"name":"Li Zifeng","avatar":""},{"name":"Huang Yi","avatar":""},{"name":"Hu Dandan","avatar":""},{"name":"Zhou Xiaochuan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324177);
