INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('du-phuong-hanh', 'Dữ Phượng Hành', 'The Legend of ShenLi', 'dữ phượng hành the legend of shenli zhao liying lin gengxin yunlai xin li qianfeng he yu jackie li zeng li zhang tianyang wei zixin li zifeng huang yi hu dandan zhou xiaochuan ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-ton-tuu-vi', 'Bản Tôn Tựu Vi', 'A Fallen Xian', 'https://phimimg.com/upload/vod/20251010-1/47a3c5d19f39b584007c14eebb874eda.jpg', 'https://phimimg.com/upload/vod/20251010-1/dcccec77e631316ca0081bcf6af30439.jpg', '<p>Đạo sĩ bịp bợm Trần Mộc Côn (Khổng Đức Hiền) mượn danh thần tiên Lữ Động Tân để lừa tiền người dân. Một lần đắc tội với ác bá, Côn đã đến trấn Ngũ Tộc Phường. Vào lúc này, thần tiên Lữ Động Tân (Tạ Đông Mẫn) quyết định xuống nhân gian để trừng trị Trần Mộc Côn. Côn vô tình đốt râu của Lữ Động Tân khiến thần tiên bị mất pháp lực, buộc phải ở lại trần gian. Lần đầu gặp cô gái thanh lâu Bạch Tuyết Hoa (Trần Gia Tuệ), Lữ Động Tân có cảm giác quen thuộc. Trong khi đó, Mộc Côn cũng có tình ý với Hoa. Lữ Động Tân đổi tên thành Lôi Thạch, hướng dẫn Côn theo chính đạo. Mộc Côn nhanh chóng trở thành “đại tiên”, được nhiều người kính trọng. Họ nhiều lần hợp tác, cùng nhau phá nhiều vụ án ở trấn Ngũ Tộc Phường. Trấn trưởng Tân Hổ (Lý Thành Xương) từ chức, Mộc Côn âm thầm gây cản trở ác bá Kim Sĩ Hào (Vi Gia Hùng) ứng tuyển. Trấn trưởng mới Tân Chính Nghĩa (Huỳnh Gia Lạc) nhằm vào những việc xấu của Sĩ Hào, tiến hành cải cách. Trấn Ngũ Tộc Phường từ đó dấy lên nhiều trận sóng gió</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 7, 2024, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Brian Tse Tung Man","avatar":""},{"name":"Danny Hung","avatar":""},{"name":"Erica Chan","avatar":""},{"name":"Wong Ka-Lok","avatar":""},{"name":"Bert Mok","avatar":""},{"name":"Lee Shing-Cheong","avatar":""},{"name":"Eva Lai","avatar":""},{"name":"Willie Wai Ga-Hung","avatar":""},{"name":"Amy Fan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["A Fallen Xian","本尊就位"]', 1784690324177);
