INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('noi-tru-an-cuoi-cung', 'Nơi Trú Ẩn Cuối Cùng', 'Homestead', 'https://phimimg.com/upload/vod/20251010-1/a46f53fb9c8d3bf86699907c72e9f0dd.jpg', 'https://phimimg.com/upload/vod/20251010-1/af6167bc93f80ed24905209eb22534a7.jpg', '<p>Sau khi một quả bom hạt nhân phát nổ tại Los Angeles, nước Mỹ rơi vào tình trạng hỗn loạn chưa từng có. Cựu lính Đặc nhiệm Xanh Jeff Eriksson cùng gia đình tìm đến “The Homestead”, một khu trú ẩn kiên cố nằm sâu trong núi, thuộc sở hữu của tỷ phú Ian Ross và vợ là Jenna. Nơi đây được đồn đại là một nơi an toàn giữa thế giới đang sụp đổ.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dawn Olivieri","avatar":""},{"name":"Neal McDonough","avatar":""},{"name":"Susan Misner","avatar":""},{"name":"Bailey Chase","avatar":""},{"name":"Jesse Hutch","avatar":""},{"name":"Kevin Lawson","avatar":""},{"name":"Kearran Giovanni","avatar":""},{"name":"Currie Graham","avatar":""},{"name":"Olivia Sanabia","avatar":""},{"name":"Tyler Lofton","avatar":""},{"name":"Grace Powell","avatar":""},{"name":"Manny McCord","avatar":""},{"name":"Alireza Mirmontazeri","avatar":""},{"name":"Jarret LeMaster","avatar":""},{"name":"Ariel Llinas","avatar":""},{"name":"Colby Strong","avatar":""},{"name":"Ivey Lloyd","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Домашний очаг","O Legado","Homestead"]', 1784690324177);
