INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-su-cua-kieu-nghien', 'Tâm Sự Của Kiều Nghiên', 'The Unseen Sister', 'https://phimimg.com/upload/vod/20251010-1/b25450bae4af76dc20f9870494a74e3e.jpg', 'https://phimimg.com/upload/vod/20251010-1/0c9b1c71d69bdae349e3143c4ce20bae.jpg', '<p>Bộ phim chuyển thể từ tiểu thuyết Đại Kiều Tiểu Kiều của Trương Duyệt Nhiên, kể về Kiều Nghiên (do Triệu Lệ Dĩnh thủ vai), một minh tinh hạng A từ thị trấn biên giới, phải đối mặt với quá khứ và bí mật gia đình bị đe dọa khi người chị gái thất lạc đột ngột xuất hiện. Phim đề cập đến những áp lực trong showbiz, sự kiểm soát của người quản lý, và cuộc đối đầu căng thẳng giữa hai chị em sau nhiều năm xa cách.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Triệu Lệ Dĩnh","avatar":""},{"name":"Tân Chỉ Lôi","avatar":""},{"name":"Hoàng Giác","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["大乔小乔","两生","乔妍的心事"]', 1784690324177);
