INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-tri-menh-kinh-van-hoa-chet-choc', 'Trò Chơi Trí Mệnh : Kính Vạn Hoa Chết Chóc', 'The Spirealm', 'https://phimimg.com/upload/vod/20250418-1/da6adad5d3c81c91c90038ed155b86cf.jpg', 'https://phimimg.com/upload/vod/20250418-1/988a1a846761ffec7c3d7296522577b8.jpg', '<p>Sau khi nghỉ việc, nhà thiết kế trò chơi Lăng Cửu Thời nhận được một đĩa trò chơi thử nghiệm đưa anh vào thế giới ảo cùng chuyến phiêu lưu đi qua 12 cánh cửa sắt. Mỗi cánh cửa là mở ra ảo cảnh đầy nguy hiểm với những bí ẩn vừa kinh dị vừa hóc búa. Điều đáng sợ là mỗi lần gặp khó khăn bên trong trò chơi, Cửu Thời cũng sẽ phải đối diện với rủi ro khi trở lại thế giới bên ngoài.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 10, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hạ Chi Quang","avatar":""},{"name":"Hoàng Tuấn Tiệp","avatar":""},{"name":"Lưu Nhược Cốc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Zhi Ming You Xi","Si Wang Wan Hua Tong","死亡万花筒","Le royaume espion","Kaleidoscope of Death","Death Kaleidoscope","致命遊戯","မရဏကစားပွဲ","The Spirealm","致命游戏"]', 1784690324177);
