INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-hoang-tu-than-nu-sat-thu', 'Nữ Hoàng Tử Thần (Nữ Sát Thủ)', 'The Killer', 'https://phimimg.com/upload/vod/20251010-1/0c6efe6f0c5cb8f7514cc75a5b54e138.jpg', 'https://phimimg.com/upload/vod/20251010-1/08105814f028098856bfb9cdef77e77d.jpg', '<p>Zee là một kẻ giết người theo hợp đồng đáng sợ được gọi là &quot;Nữ Hoàng Tử Thần&quot;, nhưng khi cô từ chối giết một phụ nữ mù, cô thấy mình bị săn lùng bởi cả các tội phạm và một thanh tra cảnh sát.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Canada', 0, '[{"name":"Nathalie Emmanuel","avatar":""},{"name":"Omar Sy","avatar":""},{"name":"Sam Worthington","avatar":""},{"name":"Diana Silvers","avatar":""},{"name":"Saïd Taghmaoui","avatar":""},{"name":"Angeles Woo","avatar":""},{"name":"Éric Cantona","avatar":""},{"name":"Tchéky Karyo","avatar":""},{"name":"Grégory Montel","avatar":""},{"name":"Hugo Diego Garcia","avatar":""},{"name":"Michaël Erpelding","avatar":""},{"name":"Aurélia Agel","avatar":""},{"name":"Guillaume Kerbusch","avatar":""},{"name":"Fabrice Scott","avatar":""},{"name":"Kelian Maréchaux","avatar":""},{"name":"Elie Haddad","avatar":""},{"name":"Lydi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["첩혈쌍웅","喋血双雄美版","新喋血双雄","喋血雌雄","آدمکش","قاتل","喋血雙雄(2024)","John Woo''s The Killer","得祭勒","דה קילר","הקילר","The Killer"]', 1784690324177);
