INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tam-tri-ruc-ro-phan-1', 'Tâm Trí Rực Rỡ (Phần 1)', 'Brilliant Minds (Season 1)', 'https://phimimg.com/upload/vod/20251010-1/41d2a33a3497b28deb614042b5f6e8bd.jpg', 'https://phimimg.com/upload/vod/20251010-1/72c1746b58c40cdc43d458e288561e5f.jpg', '<p>Bộ phim đưa khán giả vào một thế giới đầy mê hoặc của khoa học thần kinh, nơi những khám phá mới về bộ não liên tục được hé lộ. Qua đó, khán giả sẽ cùng các nhân vật trải nghiệm những cảm xúc thăng trầm, những mối quan hệ phức tạp và những câu hỏi về bản chất con người.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Zachary Quinto","avatar":""},{"name":"Tamberla Perry","avatar":""},{"name":"Ashleigh LaThrop","avatar":""},{"name":"Aury Krebs","avatar":""},{"name":"Teddy Sears","avatar":""},{"name":"Brian Altemus","avatar":""},{"name":"John Clarence Stewart","avatar":""},{"name":"Alex MacNicoll","avatar":""},{"name":"Spence Moore II","avatar":""},{"name":"Al Calderon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["仁者医心","沃尔夫医生","Wolf","Dr. Wolf","Brilliant Minds"]', 1784690324177);
