INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-san-phu-thuy', 'Thợ Săn Phù Thủy', 'Witch Hunter', 'https://phimimg.com/upload/vod/20251009-1/dbab1e3901dea7d9bceb48f745fd0004.jpg', 'https://phimimg.com/upload/vod/20251009-1/b74be3c6404f1b4fdc7d9b4a37bc8580.jpg', '<p>Phim lấy bối cảnh một thị trấn thời trung cổ bị quái vật hoành hành—những sinh vật từng là thú rừng hiền lành, nay bị biến đổi bởi ma thuật của một phù thủy quyền năng. Một thợ săn dũng cảm cùng đội chiến binh của mình phải đối đầu với thế lực hắc ám để khôi phục hòa bình</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Doug Bradley","avatar":""},{"name":"George Pakola","avatar":""},{"name":"Bix Krieger","avatar":""},{"name":"Ivan Klousia","avatar":""},{"name":"Dylan Vox","avatar":""},{"name":"D. C. Douglas","avatar":""},{"name":"Daniel Collins","avatar":""},{"name":"Kalinda Gray","avatar":""},{"name":"Vince Cusimano","avatar":""},{"name":"Theo Rosenfeld","avatar":""},{"name":"Danezion Mills","avatar":""},{"name":"Angela Mavropoulos","avatar":""},{"name":"Andrei Prunila","avatar":""},{"name":"Jared Rivet","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["The Witch Hunters","Witch Hunter"]', 1784690324177);
