INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nong-no-2', 'Nông Nô 2', 'Son Of A Rich 2', 'https://phimimg.com/upload/vod/20251009-1/f4eb57993d85b850eaf4bc007267dd1b.jpg', 'https://phimimg.com/upload/vod/20251009-1/274af95962b37d10d2e277fc95ab72db.jpg', '<p>Sau khi trải qua biến cố bị “gửi ngược thời gian” và sống kiếp nông nô thế kỷ 19, Grigory, con trai một tài phiệt Nga, đã hoàn toàn thay đổi — anh trở nên khiêm nhường và mang trong mình tinh thần công lý. Khi gặp Katya, một tiểu thư nhà giàu kiêu ngạo và ích kỷ, Grigory nhận ra cô đang lặp lại chính con đường sai lầm mà anh từng đi qua. Để giúp Katya học được bài học về lòng nhân ái và sự khiêm nhường, anh quyết định đưa cô “du hành” về quá khứ — nơi mọi đặc quyền đều tan biến, và sự thật về giá trị con người mới được phơi bày.</p>', 'Full', 1, 'single', 'completed', 30, 2024, 'Vietsub', 'FHD', 'Nga', 0, '[{"name":"Miloš Biković","avatar":""},{"name":"Aleksandr Samoylenko","avatar":""},{"name":"Mariya Mironova","avatar":""},{"name":"Ivan Okhlobystin","avatar":""},{"name":"Olga Dibtseva","avatar":""},{"name":"Aglaya Tarasova","avatar":""},{"name":"Natalya Rogozhkina","avatar":""},{"name":"Oleg Komarov","avatar":""},{"name":"Sofya Zaika","avatar":""},{"name":"Sergey Sotserdotsky","avatar":""},{"name":"Kirill Nagiev","avatar":""},{"name":"Mikhail Babichev","avatar":""},{"name":"Pavel Derevyanko","avatar":""},{"name":"Sergey Abroskin","avatar":""},{"name":"Pyotr Buslov","avatar":""},{"name":"D","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Kholop 2","Крепостен 2","Serf 2","富家之子2","Холоп 2"]', 17