INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-len-chien-doi-that-sung-sentai-daishikkaku-phan-1', 'Tiến Lên! Chiến Đội Thất Sủng! (Sentai Daishikkaku) (Phần 1)', 'Go! Go! Loser Ranger! (Season 1)', 'https://phimimg.com/upload/vod/20251008-1/e436cb00933ea4e2826e1c87a7f51bf4.jpg', 'https://phimimg.com/upload/vod/20251008-1/ea7d15e224b65b7618a5d9591c8d6422.jpg', '<p>Sau khi sào huyệt cũ và các thủ lĩnh bị tiêu diệt, những thành viên còn sống sót của nhóm Dusters đã bí mật thỏa thuận với Chiến Đội tham gia vào trận chiến hàng tuần vào Chủ nhật - một trận chiến mà họ sẽ luôn bị đánh bại. Mệt mỏi với trò giả vờ này, Fighter D cuối cùng đã đứng lên để thay đổi mọi thứ một lần và mãi mãi!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Daishi Kajita","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ranger Reject","战队大失格","戰隊大失格","No Longer Rangers","ריינג’ר לוזר GO! GO!","GO! GO! לוזר רינג''ר!","גו גו ריינג''ר לוזר","Squalificati - Ranger Reject","Sentai Daishikkaku","Sentai Dai Shikkaku","전대대실격","ขบวนการกำมะลอ","Go! Go! Loser Ranger! (2025)","Go! Go! Loser Ranger! Season 2","戦隊大失格"]', 1784690324177);
