INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-ac', 'Tội & Ác', 'Sin And Evil', 'https://phimimg.com/upload/vod/20251007-1/9080e0256dc7862dd68b8143530f44bf.jpg', 'https://phimimg.com/upload/vod/20251007-1/9371dd44bef669e5e8e60a9724c93ab1.jpg', '<p>Một ngày nọ, thi thể của một cậu bé lại được phát hiện dưới cây cầu – trong hoàn cảnh giống hệt vụ án của Masaki cách đây 22 năm. Haru có mối liên hệ bí ẩn với cậu bé đã chết, còn Akira, trong quá trình điều tra, tình cờ gặp lại Haru. Cuộc gặp gỡ ấy khiến cả ba người đàn ông phải đối diện với ký ức kinh hoàng mà họ từng cố chôn giấu suốt hơn hai thập kỷ – một bí mật chưa bao giờ thực sự được chôn vùi.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kengo Kora","avatar":""},{"name":"Shunsuke Daitoh","avatar":""},{"name":"Takuya Ishida","avatar":""},{"name":"Jun Murakami","avatar":""},{"name":"Koichi Sato","avatar":""},{"name":"Kippei Shiina","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Günah və Şeytan","罪と悪"]', 1784690324177);
