INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-thoat-khong-hoan-hao', 'Lối Thoát Không Hoàn Hảo', 'A Long Shot', 'https://phimimg.com/upload/vod/20251006-1/e12c974f73abcc9c7f33dbae411d6fd1.jpg', 'https://phimimg.com/upload/vod/20251006-1/98986944e18077fd796018c28eeac688.jpg', '<p>Nữ sinh đại học Bạch Giai Nghi (do Bốc Quan Kim thủ vai) bất ngờ bị cuốn vào một vụ án mạng. Trong quá trình bị nỗi sợ hãi vô hình bao vây, cô gặp gỡ nhiếp ảnh gia Quảng Nhất (do Bàng Hãn Thần thủ vai). Thân phận của người chết khiến sự việc dần mất kiểm soát, để thoát thân họ buộc phải liều lĩnh đánh cược. Đến cuối con đường, đây chắc chắn sẽ là một cuộc đào tẩu không hoàn hảo...</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Bộc Quán Kim","avatar":""},{"name":"Bàng Hãn Trần","avatar":""},{"name":"Trương Triệu Bắc","avatar":""},{"name":"Thì Ái Dân","avatar":""},{"name":"Vương Tử Mộc","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["不完美逃脱"]', 1784690324177);
