INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thuc-mang-vi-tien-nhiem-vu-tokyo', 'Thục Mạng Vì Tiền: Nhiệm Vụ Tokyo', 'Run For Money: Tokyo Mission', 'https://phimimg.com/upload/vod/20251004-1/7445b0260f8a9584ec2645d2a978c7c3.jpg', 'https://phimimg.com/upload/vod/20251004-1/f8a5183dbd37f01fd90c3b8709b2e143.jpg', '<p>Sau những năm trung học, Yamato, Eijiro, Ken, Riku, Yugo và Joji từng là những người bạn thân thiết trong đội điền kinh, gắn kết bằng những chiếc vòng tay giống hệt nhau. Thời gian trôi, mỗi người rẽ sang một con đường, cho đến ngày cả sáu nhận được lời mời gia nhập “Runaway” – một nhóm tham gia chương trình “On the Run – Mission in Tokyo”. Luật chơi nghe thật đơn giản: chỉ cần chạy thoát đến cuối cùng, họ sẽ cùng chia phần thưởng 100 triệu yên. Cuộc hội ngộ tưởng chừng chỉ là cơ hội hâm nóng tình bạn xưa, nhưng trò chơi nhanh chóng biến thành cơn ác mộng. Kronos – công ty quản lý chương trình – nay rơi vào tay một “game master” mới. Những thợ săn không còn tuân theo luật, còn những ai bị bắt sẽ lập tức hóa thành bóng đen và biến mất không dấu vết. Từ một chương trình giải trí, cuộc chạy trốn đã trở thành “trò chơi tử thần” với giải thưởng lên tới 10 tỷ yên. Giữa ranh giới sống – chết, sáu người bạn buộc phải đối mặt với sự phản bội, nỗi sợ hãi và cả câu hỏi cuối cùng: Ai sẽ sống sót… và bằng cái giá nào?</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Takumi Kawanishi","avatar":""},{"name":"Sota Nakajima","avatar":""},{"name":"Syoya Kimata","avatar":""},{"name":"Sukai Kinjo","avatar":""},{"name":"Taiki Sato","avatar":""},{"name":"Ririka Tanabe","avatar":""},{"name":"Eito Kawahara","avatar":""},{"name":"Mijika Nagai","avatar":""},{"name":"HIKAKIN","avatar":""},{"name":"Chika Uchida","avatar":""},{"name":"Hideyuki Kasahara","avatar":""},{"name":"Chikara Honda","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["逃走中 THE MOVIE : TOKYO MISSION","全员逃走中 电影版","Tôsôchû the Movie: Tokyo Mission","逃走中 THE MOVIE"]', 1784690324177);
