INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('driveaway-dolls', 'Drive-Away Dolls', 'Drive-Away Dolls', 'https://phimimg.com/upload/vod/20250930-1/af7e1ac4afbe4662c9d39d9269bd39a3.jpg', 'https://phimimg.com/upload/vod/20250930-1/e2067b3430c5b806cb4620e7d36e5f8f.jpg', '<p>Cặp đôi Jamie và Marian quyết định cả hai cần có một chuyến đi nghỉ và cuối cùng họ quyết định đến Tallahassee. Tuy nhiên, cửa hàng cho thuê ô tô đã giao nhầm chiếc xe mà một nhóm khách khác đã sử dụng trước đó. Trên xe có một món hàng quan trọng và kẻ sở hữu nó thực chất lại là một băng đảng tội phạm nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Margaret Qualley","avatar":""},{"name":"Geraldine Viswanathan","avatar":""},{"name":"Beanie Feldstein","avatar":""},{"name":"Joey Slotnick","avatar":""},{"name":"C.J. Wilson","avatar":""},{"name":"Colman Domingo","avatar":""},{"name":"Pedro Pascal","avatar":""},{"name":"Bill Camp","avatar":""},{"name":"Matt Damon","avatar":""},{"name":"Connie Jackson","avatar":""},{"name":"Annie Gonzalez","avatar":""},{"name":"Gordon MacDonald","avatar":""},{"name":"Sam Vartholomeos","avatar":""},{"name":"John Menchion","avatar":""},{"name":"Michael Counihan","avatar":""},{"name":"Abby Hilden","avatar":""},{"name":"H","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Drive-Away Dykes","Henry James'' Drive-Away Dykes","驾车出走的女人","Păpuși fugare","Drive-Away Dolls"]', 1784690324177);
