INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-cung-co-ngay-nay', 'Anh Cũng Có Ngày Này', 'My Boss', 'https://phimimg.com/upload/vod/20250928-1/11aae5d8736fd05911ebf1d70a5a8aad.jpg', 'https://phimimg.com/upload/vod/20250928-1/b66f04725bf3db42666e69e722614e95.jpg', '<p>Bộ phim kể về Tiền Hằng - người sáng lập công ty luật Quân Hằng. Vì chứng mất ngủ nên anh đã chuyển về ngôi nhà cũ nát, nơi mà anh đã ở khi mới tập tành kinh doanh. Không ngờ tại đây anh gặp phải chủ nhà &quot;một phòng hai tiền thuê&quot;, mà người thuê chung nhà chính là nữ đồng nghiệp mới Thành Dao. Ban đầu, Tiền Hằng muốn Thành Dao rút lui khỏi việc thuê nhà, nhưng không ngờ cô lại có thể chữa khỏi chứng mất ngủ cho anh. Bất đắc dĩ cả hai người họ phải sống chung trong một mái nhà. Thói quen sinh hoạt và triết lý khi làm việc của cả hai cũng hoàn toàn khác nhau. Vì quan điểm khác nhau nên họ thường xuyên xảy ra tranh cãi. Tuy nhiên, trải qua thời gian dài cộng tác cả hai hiểu ra những giá trị sâu sắc về tam quan của đối phương.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 9, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Tinh Húc","avatar":""},{"name":"Chương Nhược Nam","avatar":""},{"name":"Trần Tiểu Vân","avatar":""},{"name":"Lý Tuấn Hiền","avatar":""},{"name":"Hợp Văn Tuấn","avatar":""},{"name":"Phạm Soái Kỳ","avatar":""},{"name":"Minh Đạo","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ni Ye You Jin Tian","你也有今天","Mi Jefe"]', 1784690324177);
