INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-xoay-quanh-em', 'Thế Giới Xoay Quanh Em', 'Never Enough', 'https://phimimg.com/upload/vod/20250922-1/578943593a21cc7525c0028e0124d03b.jpg', 'https://phimimg.com/upload/vod/20250922-1/bf3e372330befa3e0e594b26ba7f65e1.jpg', '<p>Tawan, Mana và Shin là ba cô nhi cùng lớn lên bên nhau ở vùng biên giới Thái - Lào. Mana và Shin thầm yêu Tawan nhưng lại không muốn làm tổn thương tình bạn thân thiết của cả ba. Niềm khát khao một cuộc sống tốt đẹp hơn và những nỗ lực để vượt lên trên bất công xã hội đã dẫn họ đến một bước ngoặt chết người, làm thay đổi cuộc đời họ mãi mãi. Bị buộc phải chia lìa nhau, sợi dây gắn kết của tình yêu, ước mơ và tình bạn giữa Tawan, Mana và Shin dần tan vỡ.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Jirayu Tangsrisuk","avatar":""},{"name":"Maylada Susri","avatar":""},{"name":"Paris Intarakomalyasut","avatar":""},{"name":"Warintorn Panhakarn","avatar":""},{"name":"Myria Benedetti","avatar":""},{"name":"Henry Myron","avatar":""},{"name":"Pornthip Skidjai","avatar":""},{"name":"Nawinda Bertotti","avatar":""},{"name":"Witsarut Himmarat","avatar":""},{"name":"Penpetch Benyakul","avatar":""},{"name":"Pawanrat Naksuriya","avatar":""},{"name":"Ratchanont Suprakob","avatar":""},{"name":"Danny Luciano","avatar":""},{"name":"Phutharit Promba","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Lok Mun Rop Thoe","We and Us","The World Revolves Around You","โลกหมุนรอบเธอ"]', 1784690324177);
