INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giao-nhan-truyen', 'Giao Nhân Truyện', 'Legend Of Mermaid: Human Love', 'https://phimimg.com/upload/vod/20250926-1/8034bad024eb9e5bc3cc8eb1de2e11aa.jpg', 'https://phimimg.com/upload/vod/20250926-1/3fcb5b73c72c9b98da2628312efe8bca.jpg', '<p>Hàng loạt vụ giết người liên tiếp xảy ra ở trấn Vân Ẩn. Người dân khi đó lo âu, hoảng sợ, quyết định tổ chức lễ cúng thần sông để cầu bình an. Y sư Đào Nhiễm được lệnh phối hợp điều tra án mạng. Trong quá trình điều tra, cùng với đồ đệ của mình, đã vô tình cứu được tiểu hồ ly Hoa Chi, nhân chứng án mạng và kết giao với Tiêu Thúc, thuật sĩ giang hồ mê rượu hơn cả tính mạng. Họ cùng hợp lực phá án và đã chú ý đến một phường thêu. Sự thật dần dần được hé lộ. Hóa ra, những sự việc kỳ lạ xảy ra liên tiếp đều có mối quan hệ mật thiết với lễ cúng thần sông.</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hoàng Nhật Anh","avatar":""},{"name":"Minh Lượng","avatar":""},{"name":"Trương Thiên Nghi","avatar":""},{"name":"Kỳ Cách","avatar":""},{"name":"Thí Vũ","avatar":""},{"name":"Kim Phổ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["鲛珠幻视","Mermaid","Legend of Mermaid: Human Love","The Mermaid Forever Love","鲛人传说之人间情"]', 1784690324177);
