INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phuc-lanh-cho-the-gioi-tuyet-voi-nay-phan-3', 'Phúc Lành Cho Thế Giới Tuyệt Vời Này (Phần 3)', 'KonoSuba God''s Blessing On This Wonderful World! (Season 3)', 'https://phimimg.com/upload/vod/20250925-1/d81a21000f6785433bb9d34fd6744ccf.jpg', 'https://phimimg.com/upload/vod/20250925-1/f85663e8b70ed1a31b93b2323aa637c9.jpg', '<p>Satou Kazuma, một hikikomori đam mê trò chơi, Nhưng cuộc sống ngắn ngủi của anh kết thúc vì tai nạn giao thông lãng xẹt ... Nhưng khi anh ta tỉnh dậy, một cô gái xinh đẹp, người tự gọi mình là một nữ thần đã ở phía trước đôi mắt anh ấy và đưa anh ấy đến một thế giới khác, Khi sang thế giới mới, cậu gặp ngày càng nhiều mấy cô nàng không điên thì cũng tâm thần, riết rồi cậu muốn quay trở về thế giới cũ càng nhanh càng tốt...</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Jun Fukushima","avatar":""},{"name":"Sora Amamiya","avatar":""},{"name":"Rie Takahashi","avatar":""},{"name":"Ai Kayano","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["KonoSuba: As Bênçãos de Deus Neste Mundo Maravilhoso!","KonoSuba: Abençoado Mundo Maravilhoso!","素晴","素晴3","Bůh žehnej tomuto nádhernému světu","Konosuba: Un Mundo Maravilloso!","Konosuba - Sois Béni Monde Merveilleux !","KonoSuba","このすば","Kono Subarashii Sekai ni Syukufuku Wo!","Kono Subarashii Sekai ni Shukufuku wo! 3","Kono Subarashii Sekai ni Shukufuku wo!","Kono Subarashii Sekai ni Shukufuku o! 3","Kono Subarashii Sekai ni Syukufuku Wo! 2","Kono Subarashii Sekai ni Syukufuku Wo! 3","코노스바","Konosuba: ¡Una bendición para este maravilloso mundo!","Богиня благословляет этот прекрасный мир","Коносуба","Богиня благословляет этот замечательный мир!","Да благословят боги сей расчудесный мир!","Этот замечательный мир!","美好世界","為美好的世界獻上祝福","Give Blessings to This Wonderful World!","KONOSUBA - God''s blessing on this wonderful world!!","KonoSuba: God''s Blessing on This Wonderful World","この素晴らしい世界に祝福を！"]', 1784690324177);
