INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('duyen-vi-tinh-nong', 'Duyên Vị Tình Nồng', 'My Love In The Countryside', 'https://phimimg.com/upload/vod/20250827-1/efc1f0f2effa707844f12c1111d08dfd.jpg', 'https://phimimg.com/upload/vod/20250827-1/113d8c98a3d9c32d7ecc477d855c1726.jpg', '<p>Saisamorn Suaisamoe, một diễn viên hàng đầu xuất thân từ một gia đình giàu có, được giám đốc dự án mới của cô cử đến sống ở Lat Chado ở Ayutthaya và tìm hiểu về tình yêu. Tại đây, cô phải chuyển đến nhà của Marasri, một người phụ nữ mồm mép và đang bị theo dõi bởi một người tên là Mha.</p>', 'Tập 24', 24, 'series', 'completed', 10, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Vachiravit Paisarnkulwong","avatar":""},{"name":"Thunyaphat Phatrathinchaicherin","avatar":""},{"name":"Nichaphat Chatchaipholrat","avatar":""},{"name":"Nichakoon Khajornborirak","avatar":""},{"name":"Passaranan Ussadamongkol","avatar":""},{"name":"Boonthong Hanchanang","avatar":""},{"name":"Sueangsuda Lawanprasert","avatar":""},{"name":"Minraya Tangsaebwong","avatar":""},{"name":"Chamaiporn Sitthiworanang","avatar":""},{"name":"Jaturong Mokjok","avatar":""},{"name":"May","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Rak Thuam Thung","Ruk Tuam Toong","Rak Thum Tung","รักท่วมทุ่ง"]', 1784690324177);
