INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tri-tue-tiem-nang-phan-1', 'Trí Tuệ Tiềm Năng (Phần 1)', 'High Potential (Season 1)', 'https://phimimg.com/upload/vod/20241121-1/809185807545d44718568f2e0243d85f.jpg', 'https://phimimg.com/upload/vod/20241121-1/e432600e90dccfc811cf94746a1ffbb3.jpg', '<p>&quot;High Potential&quot; là một bộ phim truyền hình mới tập trung vào câu chuyện của Morgan, một bà mẹ đơn thân trí tuệ hơn người và óc phán đoán sắc sảo, có ba người con. Morgan làm việc tại sở cảnh sát với vai trò là nhân viên vệ sinh, nhưng nhờ vào trí tuệ và khả năng quan sát phi thường, cô vô tình phát hiện ra các chi tiết quan trọng bị bỏ lỡ trong một vụ án. Trong quá trình sắp xếp bằng chứng trong ca làm việc, Morgan nhận ra manh mối mà các điều tra viên đã bỏ qua, và nhờ vậy, cô có cơ hội hỗ trợ cảnh sát trong việc tìm ra thủ phạm.</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Kaitlin Olson","avatar":""},{"name":"Daniel Sunjata","avatar":""},{"name":"Javicia Leslie","avatar":""},{"name":"Deniz Akdeniz","avatar":""},{"name":"Amirah J","avatar":""},{"name":"Matthew Lamb","avatar":""},{"name":"Judy Reyes","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["拂尘奇探","潜能探案组","高度潜力","HPI USA","Великий потенціал","High Potential"]', 1784690324177);
