INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-nhan-chi-ha-ban-dien-anh', 'Dị Nhân Chi Hạ (Bản Điện Ảnh)', 'The Traveller', 'https://phimimg.com/upload/vod/20250730-1/cb423ae5638dca68d9b86cb4aff96e2b.jpg', 'https://phimimg.com/upload/vod/20250730-1/a8db6d68056bdb16314934481f773792.jpg', '<p>Bộ phim kể về Trương Sở Lam (do Hồ Tiên Túc thủ vai), người luôn giấu kín thân phận dị nhân. Kể từ khi gặp Phùng Bảo Bảo (do Lý Uyển Đa thủ vai) với thân thế bí ẩn, anh bị cuốn vào vòng xoáy tranh đấu giữa các môn phái dị nhân. Khi bí mật về việc anh là truyền nhân của công pháp thần bí “Khí Thể Nguyên Lưu” bị lộ, toàn bộ giới dị nhân đều lao vào cuộc tranh đoạt khốc liệt. Nhã Đâu Thông, Toàn Tính Phái, Thiên Hạ Hội, Thiên Nhất Môn… lần lượt xuất hiện, hỗn chiến sắp bùng nổ. Trong lúc này, Trương Sở Lam tình cờ phát hiện ra bí mật kinh thiên động địa bị chôn vùi nhiều năm trước....</p>', 'Full', 1, 'single', 'completed', 39, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 1, '[{"name":"Hu Tiên Túc","avatar":""},{"name":"Lý Uyển Đa","avatar":""},{"name":"Phùng Thiệu Phong","avatar":""},{"name":"Kiều Chấn Vũ","avatar":""},{"name":"Tống Ninh Phong","avatar":""},{"name":"Na Nhiên","avatar":""},{"name":"Na Nhĩ Na Tế","avatar":""},{"name":"Lan Tây Nha","avatar":""},{"name":"Ngô Gia Khải","avatar":""},{"name":"Hùng Ổn Ổn","avatar":""},{"name":"Tráng Nhất Kiệt","avatar":""},{"name":"Lưu Thuần Yên","avatar":""},{"name":"Tang Bình","avatar":""},{"name":"Lưu Tinh Thần","avatar":""},{"name":"Tùy Vịnh Lương","avatar":""},{"name":"Hàn Bằng Dực","avatar":""},{"name":"Phùng Lự","avatar":""},{"name":"Thượng Thiết Long","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f0084903