INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngang-qua-thi-tran-ngan-may', 'Ngang Qua Thị Trấn Ngàn Mây', 'Moments We Shared', 'https://phimimg.com/upload/vod/20250918-1/b3341e8cd002c30637a94211570fa377.jpg', 'https://phimimg.com/upload/vod/20250918-1/a28567371c305a482db177316ab7a2b2.jpg', '<p>Ngang Qua Thị Trấn Ngàn Mây là một bộ phim truyền hình Trung Quốc được ra mắt vào năm 2024, nhanh chóng thu hút sự quan tâm của khán giả bởi câu chuyện tình yêu lãng mạn và đầy xúc động. Bộ phim xoay quanh cuộc sống của những người trẻ tuổi, những mối quan hệ phức tạp và những ước mơ hoài bão.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Peng Yuchang","avatar":""},{"name":"Zhou Ye","avatar":""},{"name":"Ai Liya","avatar":""},{"name":"Chen Xianen","avatar":""},{"name":"Kong Lianshun","avatar":""},{"name":"Zhang Yifan","avatar":""},{"name":"Tian Yitong","avatar":""},{"name":"Lin Jiachuan","avatar":""},{"name":"Wang Luodan","avatar":""},{"name":"Darren Wang","avatar":""},{"name":"Victor Ma","avatar":""},{"name":"Meng Ziyi","avatar":""},{"name":"Michelle Chen Yan-Hsi","avatar":""},{"name":"Jackie Li","avatar":""},{"name":"Zhang Youwei","avatar":""},{"name":"Xiaoxing Yi","avatar":""},{"name":"Teng Zhe","avatar":""},{"name":"Wang Tianfang","avatar":""},{"name":"沈南","avatar":""},{"name":"Liu Haoran","avatar":""},{"name":"Qiao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["云边有个小卖部","yun bian you ge xiao mai bu","电影版云边有个小卖部","Moments We Shared"]', 1784690324177);
