INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngang-qua-thi-tran-ngan-may', 'Ngang Qua Thị Trấn Ngàn Mây', 'Moments We Shared', 'ngang qua thị trấn ngàn mây moments we shared peng yuchang zhou ye ai liya chen xianen kong lianshun zhang yifan tian yitong lin jiachuan wang luodan darren wang victor ma meng ziyi michelle chen yan-hsi jackie li zhang youwei xiaoxing yi teng zhe wang tianfang 沈南 liu haoran qiao 云边有个小卖部 yun bian you ge xiao mai bu 电影版云边有个小卖部 moments we shared', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-chien-me-thanh', 'Cô Chiến Mê Thành', 'Lost Identity', 'https://phimimg.com/upload/vod/20250918-1/d6abb82fb0a3a5c35e3e116e89b340bc.jpg', 'https://phimimg.com/upload/vod/20250918-1/b477f3d5f25b819958b55f7b39ccb8d1.jpg', '<p>Năm 1945, khi cuộc kháng chiến chống Nhật sắp kết thúc, quân đội Nhật bí mật vận chuyển một lượng lớn bom độc đến Trung Quốc. Đặc công ưu tú của quân thống là Âu Hiếu An bị thương trong quá trình liều mình trốn thoát khỏi viện nghiên cứu khí độc &quot;810&quot;, và tình cờ được đặc công Đàm Mặc Khanh cứu. Khi tỉnh lại, anh phát hiện mình đã mất gần bốn năm ký ức. Trong quá trình phơi bày âm mưu của quân Nhật, Âu Hiếu An và Đàm Mặc Khanh nhiều lần hợp tác, cuối cùng vạch trần được bộ mặt thật của gián điệp Nhật Bản và xác nhận danh tính của mình là thành viên bí mật của Đảng. Tuy nhiên, một khủng hoảng lớn hơn đang chờ đợi họ, tài liệu nghiên cứu của &quot;810&quot; và vị trí cất giấu bom độc thực sự ở đâu? Đối mặt với vô số hiểm nguy, đoàn những chiến binh cô độc dũng cảm tiến lên phía trước nên chiến đấu như thế nào.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 7, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hoàng Cảnh Du","avatar":""},{"name":"Tân Chỉ Lôi","avatar":""},{"name":"Mã Tư Siêu","avatar":""},{"name":"Mã Nguyệt","avatar":""},{"name":"La Thuỵ Vận","avatar":""},{"name":"Đổng Tuyền","avatar":""},{"name":"Quách Thu Thành","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["GuZhanMiCheng","孤战","失落在东经97度的记忆","Lost Identity","孤战迷城"]', 1784690324177);
