INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ga-he-dien-loan-3', 'Gã Hề Điên Loạn 3', 'Terrifier 3', 'https://phimimg.com/upload/vod/20250918-1/d343379f4a98aaea6d2bf9659f91155b.jpg', 'https://phimimg.com/upload/vod/20250918-1/a68c4db3ebc7a4d254628efe87eae507.jpg', '<p>Tiếp tục câu chuyện rùng rợn của Art the Clown (do David Howard Thornton thủ vai), diễn ra trong bối cảnh mùa Giáng sinh. Lần này Art tái xuất và tàn phá dân cư tại quận Miles với những hành vi tàn ác đẫm máu từ xâm nhập các quán bar, giả dạng ông già Noel và mang &quot;quà&quot; đầy kinh dị đến cho trẻ em tại trung tâm thương mại. Các món quà mà Art trao cho bọn trẻ chứa đựng những quả bom gây ra cảnh tượng hỗn loạn khi hàng loạt người chết.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lauren LaVera","avatar":""},{"name":"David Howard Thornton","avatar":""},{"name":"Samantha Scaffidi","avatar":""},{"name":"Elliott Fullam","avatar":""},{"name":"Margaret Anne Florence","avatar":""},{"name":"Bryce Johnson","avatar":""},{"name":"Alexa Blair Robertson","avatar":""},{"name":"Antonella Rose","avatar":""},{"name":"Mason Mecartea","avatar":""},{"name":"Krsy Fox","avatar":""},{"name":"Luciana VanDette","avatar":""},{"name":"Clint Howard","avatar":""},{"name":"Bradley Stryker","avatar":""},{"name":"Daniel Roebuck","avatar":""},{"name":"Chris Irvine","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["مرعب ۳","Ужасающий 3","断魂小丑3","Terrifier 3: Payaso siniestro","Ужасяващо 3","Damien Leone''s Terrifier 3","Aterrorizante 3","Klaunovy Vánoce","劊樂小丑3","Terrifier 3"]', 1784690324177);
