INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('senpai-thich-gia-gai', 'Senpai Thích Giả Gái', 'Senpai Is An Otokonoko', 'https://phimimg.com/upload/vod/20250916-1/77d14fa00a0c0c99c06cb8d38e35d95f.jpg', 'https://phimimg.com/upload/vod/20250916-1/91d6ad6c61b3b5bbed4d8fedcb054ae1.jpg', '<p>Đối với Makoto Hanaoka, cuộc sống sắp trở nên rắc rối hơn. Saki Aoi, một cô gái hoạt bát và đầy tự tin, bất ngờ tỏ tình với Makoto. Khi cậu không đáp lại, Saki liền tuyên bố rằng cô sẽ trở thành mối tình đầu của cậu! Cô chia sẻ mục tiêu này với một người bạn chung là Ryuji Taiga, người cũng thú nhận rằng mình thích Makoto. Bị cuốn vào tam giác tình yêu, Makoto buộc phải tìm cách dung hòa và tận hưởng niềm vui.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Shuichiro Umeda","avatar":""},{"name":"Akira Sekine","avatar":""},{"name":"Yuma Uchida","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["前辈是伪娘","学姐是男孩","This Is Him (Can''t Be Anyone Else)","學姊是男孩","前輩是偽娘","Сенпай - Отоконоко","Мій семпай - Отаку","Senpai wa Otokonoko","Painoko","My Crossdressing Senpai","Otokonoko ga Kouhai ni Kokuhaku sareru Hanashi","先輩はおとこのこ"]', 1784690324177);
