INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('senpai-thich-gia-gai', 'Senpai Thích Giả Gái', 'Senpai Is An Otokonoko', 'senpai thích giả gái senpai is an otokonoko shuichiro umeda akira sekine yuma uchida 前辈是伪娘 学姐是男孩 this is him (can''t be anyone else) 學姊是男孩 前輩是偽娘 сенпай - отоконоко мій семпай - отаку senpai wa otokonoko painoko my crossdressing senpai otokonoko ga kouhai ni kokuhaku sareru hanashi 先輩はおとこのこ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhi-long-ho-giac-mong-thon-que-phan-1', 'Nhị Long Hồ: Giấc Mộng Thôn Quê (Phần 1)', 'Erlong Lake Blossoms Of Hometown Dreams (Season 1)', 'https://phimimg.com/upload/vod/20250913-1/fff5fb28737da4e44d8159ec741c9e90.jpg', 'https://phimimg.com/upload/vod/20250913-1/b72b8aa3db7eb96b5979c9655b4f3a4a.jpg', '<p>Phim kể về cuộc sống của dân làng ở vùng Nhị Long Hồ – nơi người dân chịu nhiều khó khăn trong chuyện phát triển kinh tế và cải thiện đời sống. Nhân vật chính thường là những người trẻ ở quê, họ nỗ lực mang lại sự thay đổi cho cộng đồng: từ việc làm nông truyền thống đến các hoạt động khởi nghiệp, du lịch nông thôn, và dự án bảo tồn văn hóa địa phương. Qua đó, phim khắc họa tình làng nghĩa xóm, những mâu thuẫn giữa truyền thống và hiện đại, giữa người ở quê và người đi xa muốn trở về để xây dựng quê hương. Phim mang sắc thái ấm áp, hài hước nhưng cũng đầy cảm động, khi những câu chuyện nhỏ trong làng – tình cảm gia đình, sự gắn bó, tinh thần vượt khó – được khắc họa rõ, để rồi len lỏi hy vọng về một tương lai tươi sáng hơn cho vùng quê.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Hạo","avatar":""},{"name":"Châu Lệ Lan","avatar":""},{"name":"Quách Thiết Thành","avatar":""},{"name":"Hoàng Hiểu Quyên","avatar":""},{"name":"Lai Hỉ","avatar":""},{"name":"Trương Đào","avatar":""},{"name":"Trác Nghĩ Âm","avatar":""},{"name":"Tích Đại Trang","avatar":""},{"name":"Viện Hàng Minh","avatar":""},{"name":"Quan Hạo","avatar":""},{"name":"Vương Thông","avatar":""},{"name":"Địa Lôi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["二龙湖村暖花开","Er Long Hu Cun Nuan Hua Kai","Cun Nuan Hua Kai","村暖花开","二龙湖·村暖花开","二龙湖·“村”暖花开2","Erlong Lake Blossoms of Hometown Dreams","二龙湖·“村”暖花开"]', 1784690324177);
