INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhi-long-ho-giac-mong-thon-que-phan-1', 'Nhị Long Hồ: Giấc Mộng Thôn Quê (Phần 1)', 'Erlong Lake Blossoms Of Hometown Dreams (Season 1)', 'nhị long hồ: giấc mộng thôn quê (phần 1) erlong lake blossoms of hometown dreams (season 1) trương hạo châu lệ lan quách thiết thành hoàng hiểu quyên lai hỉ trương đào trác nghĩ âm tích đại trang viện hàng minh quan hạo vương thông địa lôi 二龙湖村暖花开 er long hu cun nuan hua kai cun nuan hua kai 村暖花开 二龙湖·村暖花开 二龙湖·“村”暖花开2 erlong lake blossoms of hometown dreams 二龙湖·“村”暖花开', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-trom-danh-tinh-3-tin-tac-cuoi-cung', 'Kẻ Trộm Danh Tính 3: Tin Tặc Cuối Cùng', 'Stolen Identity: The Last Hacker', 'https://phimimg.com/upload/vod/20250913-1/e8bef0e55646961504ac1ae73d7b061a.jpg', 'https://phimimg.com/upload/vod/20250913-1/360f700da0fc53fac29dfde7ef64ecb9.jpg', '<p>Thiên tài hacker kiêm sát nhân Urano trốn thoát khỏi nhà tù và chạy sang Hàn Quốc. Ở đây, Urano được một tổ chức chống chính phủ Hàn Quốc thuê để giăng bẫy nhằm vào hội nghị thượng đỉnh Hàn – Nhật. Sumin được giao nhiệm vụ giám sát Urano, nhưng lại bị choáng ngợp trước sự điên cuồng và khó đoán của hắn. Urano thì không tin tưởng cô, nhưng theo thời gian, giữa hai người bắt đầu nảy sinh những thay đổi trong cảm xúc…</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ryo Narita","avatar":""},{"name":"Kwon Eun-bi","avatar":""},{"name":"Yudai Chiba","avatar":""},{"name":"Arata Iura","avatar":""},{"name":"Kei Tanaka","avatar":""},{"name":"Mai Shiraishi","avatar":""},{"name":"Taizo Harada","avatar":""},{"name":"Ryohei Otani","avatar":""},{"name":"Shiro Sano","avatar":""},{"name":"Sei Matobu","avatar":""},{"name":"Kenta Izuka","avatar":""},{"name":"Akari Takaishi","avatar":""},{"name":"Hyeonwoo","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Stolen Identity 3","Stolen Identity: Final Hacking Game","我的手机掉了～最终章～最终黑客游戏","スマホを落としただけなのに 最終章 ファイナル ハッキング ゲーム","Sumaho o otoshita dake na no ni: Saishusho Final Hacking Game","