INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-lang-man-o-hagwon', 'Đêm Lãng Mạn Ở Hagwon', 'The Midnight Romance In Hagwon', 'https://phimimg.com/upload/vod/20250912-1/7974c46a4345448c9df4b343991bb6af.jpg', 'https://phimimg.com/upload/vod/20250912-1/e3bc98f19a32968be32cc6cf5ec91260.jpg', '<p>Đêm Lãng Mạn Ở Hagwon là câu chuyện tình đẹp giữa cô giáo Seo Hye Jin và cậu học trò cũ Lee Jun Ho. Hye Jin là giảng viên ngôi sao tại một học viện nổi tiếng, từng giúp nhiều học sinh thi đỗ vào các trường danh giá. Cuộc sống của cô đang êm đềm trôi qua thì bỗng bị xáo trộn trước sự xuất hiện của Lee Jun Ho, giáo viên mới và cũng là cậu học trò cá biệt ngày xưa từng yêu thầm Hye Jin.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 10, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jung Ryeo-won","avatar":""},{"name":"Wi Ha-jun","avatar":""},{"name":"Kim Jong-tae","avatar":""},{"name":"So Joo-yeon","avatar":""},{"name":"Kim Jung-young","avatar":""},{"name":"Yang Jo-a","avatar":""},{"name":"Jang In-sub","avatar":""},{"name":"Oh Man-seok","avatar":""},{"name":"Yoon Bok-in","avatar":""},{"name":"Shin Joo-hyup","avatar":""},{"name":"Cha Kang-yoon","avatar":""},{"name":"Hwang Eun-hoo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["毕业","TMRIH","卒業","Выпускник","عشق منتصف الليل في هاغوون","畢業","Graduation","The Midnight Romance","The Midnight Romance In Hagwon","졸업"]', 1784690324177);
