INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-biet-ro-con-co-y-yeu', 'Đã Biết Rõ Còn Cố Ý Yêu', 'First Choice', 'https://phimimg.com/upload/vod/20250911-1/ee13b1e17e322dbff867e504c6dbea57.jpg', 'https://phimimg.com/upload/vod/20250911-1/4d5992de22998b9b3258a95a84a56e44.jpg', '<p>Bạch Lạc An và Hác Lăng từng yêu nhau, rồi vì hiểu lầm mà ly hôn. Năm năm sau, họ tình cờ gặp lại và rơi vào một mối quan hệ phức tạp: đấu đá trong công việc, rồi dần tìm lại tình cảm, vượt qua mọi hiểu lầm để hàn gắn và yêu lại từ đầu.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Tử Giáp","avatar":""},{"name":"Vương Tinh Vĩ","avatar":""},{"name":"Cao Khải","avatar":""},{"name":"Đỗ An Kỳ","avatar":""},{"name":"Hà Tinh Vũ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["明知故愛","明知故爱"]', 1784690324177);
