INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('da-biet-ro-con-co-y-yeu', 'Đã Biết Rõ Còn Cố Ý Yêu', 'First Choice', 'đã biết rõ còn cố ý yêu first choice vương tử giáp vương tinh vĩ cao khải đỗ an kỳ hà tinh vũ 明知故愛 明知故爱', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('niki', 'Niki', 'Niki', 'https://phimimg.com/upload/vod/20250911-1/7474fef7390f277f519db805b35733b7.jpg', 'https://phimimg.com/upload/vod/20250911-1/0895d8ca9ee3a5a685a7329a2e926cf8.jpg', '<p>Niki de Saint-Phalle, nghệ sĩ Pháp-Mỹ, bước vào tuổi 23 với nhiều vai trò: người mẫu rực rỡ, nữ diễn viên đầy khát vọng, người vợ trẻ và mẹ của một bé gái lên hai. Khi bóng tối của thời kỳ McCarthy bao trùm, cô cùng gia đình rời bỏ nước Mỹ, tìm đến nước Pháp với niềm hân hoan ngắn ngủi. Nhưng quá khứ không dễ lãng quên — những ký ức xa xăm và đáng sợ dần trỗi dậy trong tâm trí. Trên bờ vực đổ vỡ, Niki tìm thấy lối thoát duy nhất: biến nỗi đau thành nghệ thuật, và nghệ thuật thành sự cứu rỗi của đời mình.</p>', 'Full', 1, 'single', 'completed', 18, 2024, 'Vietsub', 'FHD', 'Pháp', 0, '[{"name":"Charlotte Le Bon","avatar":""},{"name":"Damien Bonnard","avatar":""},{"name":"John Robinson","avatar":""},{"name":"Quentin Dolmaire","avatar":""},{"name":"Judith Chemla","avatar":""},{"name":"Virgile Bramly","avatar":""},{"name":"Marie Zabukovec","avatar":""},{"name":"Pierre X. Garnier","avatar":""},{"name":"Radu Mihăileanu","avatar":""},{"name":"Eric Pucheu","avatar":""},{"name":"Grégoire Monsaingeon","avatar":""},{"name":"Léo Dussollier","avatar":""},{"name":"Xavier de Guillebon","avatar":""},{"name":"Romain Sandère","avatar":""},{"name":"Hugo Brunswick","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["妮基的重生","Ники","Niki de Saint Phalle","Niki"]', 1784690324177);
