INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('niki', 'Niki', 'Niki', 'niki niki charlotte le bon damien bonnard john robinson quentin dolmaire judith chemla virgile bramly marie zabukovec pierre x. garnier radu mihăileanu eric pucheu grégoire monsaingeon léo dussollier xavier de guillebon romain sandère hugo brunswick 妮基的重生 ники niki de saint phalle niki', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-y-ve-luyen-hoa-ky', 'Cẩm Y Vệ: Luyện Hỏa Ký', 'The Plot Of Fire', 'https://phimimg.com/upload/vod/20250808-1/3cfbbba69c7bbc6d653ed69888db39c5.jpg', 'https://phimimg.com/upload/vod/20250808-1/9642b7c2f8b7396abc7a17aac7dc67b9.jpg', '<p>Phim lấy bối cảnh cuối thời Minh, khi triều đình rối ren, nội bộ tranh giành quyền lực, biên cương liên tiếp xảy ra biến loạn. Nhân vật chính Chu Hoài An, một cẩm y vệ, vốn không hứng thú với đấu đá chính trị nhưng lại căm ghét sự tàn bạo của Đông Xưởng. Sau khi biết con trai duy nhất của lão Anh Vương – một trung thần – bị truy sát, Chu Hoài An bất chấp nguy hiểm đứng ra bảo vệ. Trong quá trình này, anh bị cuốn vào âm mưu liên quan đến cả triều đình lẫn thế lực ngầm, vừa phải đấu trí với kẻ thù, vừa tìm cách giữ mạng cho người mình bảo vệ.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lăng Vân","avatar":""},{"name":"Hoàng Thao","avatar":""},{"name":"Lương Gia Nhiên","avatar":""},{"name":"Tưởng Nhụy Tằng","avatar":""},{"name":"Lục Giang Sơn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Plot of Fire","锦衣卫之炼火记"]', 1784690324177);
