INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-than-lenh', 'Yêu Thần Lệnh', 'The Lord Of The Monsters', 'https://phimimg.com/upload/vod/20250907-1/9b940cc99e6a58ed02f7466ab5d75e45.jpg', 'https://phimimg.com/upload/vod/20250907-1/58a77b2ace9147d54d9f074c3657a42c.jpg', '<p>Yêu Vương Bạch Trạch sắp thức tỉnh, trước khi Tam giới rối loạn Tiên Đồ Mộ Thanh đi vào Yêu giới tìm kiếm Pháp khí Thanh Loan Kính để tiêu diệt Yêu Vương, trời xui đất khiến cùng bắt đầu hành trính với tiểu yêu Triều Nhan. Hai người hiểu và yêu nhau trong cuộc mạo hiểm, lúc sắp hoàn thành sứ mệnh, Mộ Thanh mới phát hiện ra Triều Nhan chính là Yêu Vương chuyển thế, căn nguyên hai kiếp lại định sẵn bi kịch.</p>', 'Full', 1, 'single', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Tử Thụy","avatar":""},{"name":"Trình Kim Minh","avatar":""},{"name":"Giang Ngữ Tâm","avatar":""},{"name":"Hòa Trung Hoa","avatar":""},{"name":"Phan Trường Giang","avatar":""},{"name":"Triệu Anh Tử","avatar":""},{"name":"Hàn Đống","avatar":""},{"name":"Lý Tâm Ái","avatar":""},{"name":"Trần Bỉnh Cường","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Lord of the Monsters","妖神令"]', 1784690324177);
