INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khoang-troi-cua-rieng-em', 'Khoảng Trời Của Riêng Em', 'My Secret Zone', 'https://phimimg.com/upload/vod/20250907-1/03b858541796a56250b733600e62864a.jpg', 'https://phimimg.com/upload/vod/20250907-1/0bfd182f488cef091f6581869792a596.jpg', '<p>Cả nhà bị giết trong một vụ án mạng thảm khốc, Nam được gia đình bạn thân của bố mẹ nhận nuôi và lớn lên cùng con trai của họ là Nantawan. Khi trưởng thành, sự quan tâm và bảo bọc Nantawan dành cho Nam dần dần phát triển thành tình yêu. Thế nhưng vào lúc này, trong cuộc đời Nam lại xuất hiện một người đàn ông khác là Fakhram - cấp trên ở công ty của cô. Mối tình tay ba vốn đã trớ trêu này càng ngày càng phức tạp hơn khi Nam phát hiện người thân của cả Nantawan và Fakhram đều có mối liên quan đáng ngờ đến cái chết của bố mẹ mình năm xưa.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 9, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"James Ma","avatar":""},{"name":"Nuttanicha Dungwattanawanich","avatar":""},{"name":"Phiravich Attachitsataporn","avatar":""},{"name":"Kajbhunditt Jaidee","avatar":""},{"name":"Chattarika Sittiprom","avatar":""},{"name":"Chayanit Chayjaroen","avatar":""},{"name":"Chartayodom Hiranyatithi","avatar":""},{"name":"Sarut Vichitrananda","avatar":""},{"name":"Sarocha Watittapan","avatar":""},{"name":"Chinnaphat Kitichaivaranggoon","avatar":""},{"name":"Noppachai Muttaweevong","avatar":""},{"name":"Kh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["秘密港湾","跨越爱的边界","น่านฟ้าชลาลัย","Nan Fah Chalalai","Nan Fa Chalalai","My Secret Zone","น่าน ฟ้า ชลาลัย"]', 1784690324177);
