INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xin-chao-thu-bay-mua-3', 'Xin Chào, Thứ Bảy (Mùa 3)', 'Hello, Saturday (Season 3)', 'https://phimimg.com/upload/vod/20250906-1/c65960b7f567e7a364cd30665084a1bb.jpg', 'https://phimimg.com/upload/vod/20250906-1/9fdcf4cb9124847eb3205d75249a6fb7.jpg', '<p>Xin Chào Thứ 7&quot;được sản xuất bởi đài truyền hình Hồ Nam, với sự dẫn dắt của các MC He Jiong, Ngô Tắc Lâm và Tiểu Dương (MC ảo thực tập).Đinh Thành Tân, Đan Kiện Tư, Tần Tiêu Hiền, Thái Văn Tĩnh, Lý Tuyết Khâm, VươngHạcĐệ, Dương Địch đảm nhận chương trình tạp kỹ nghệ thuật thú vị của nhóm Sáu Tốt. Chương trình mỗi kỳ sẽ mời một vài khách mời tham gia ghi hình, với bối cảnh là khu phố mới được xây dựng Haoliu, mang không khí đời sống bình dị vào trường quay, thể hiện đủ mọi sắc thái của cuộc sống phố phường.</p>', 'Hoàn Tất (49/49)', 49, 'tvshows', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"He Jiong","avatar":""},{"name":"Li Xueqin","avatar":""},{"name":"Yang Di","avatar":""},{"name":"Ding Chengxin","avatar":""},{"name":"Wu Ze Lin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["H!6","Hi6","你好，星期六"]', 1784690324177);
