INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cap-nhi-tan-1944', 'Cáp Nhĩ Tân 1944', 'In The Name Of The Brother', 'https://phimimg.com/upload/vod/20250905-1/e67625efe0232c1cada80644b989582c.jpg', 'https://phimimg.com/upload/vod/20250905-1/e3b2fa8ad37b8be674082bc49695d73f.jpg', '<p>Cáp Nhĩ Tân 1944 là một bộ phim thời đại trinh thám gián điệp do đạo diễn Trương Lê (Ở Bên Nhau) chỉ đạo, với sự tham gia diễn xuất của Tần Hạo (Góc Bí Mật) và Dương Mịch (Tiểu Thời Đại) tham gia đóng chính. Năm 1944, Cáp Nhĩ Tân dưới sự cai trị phi pháp của Nhật Bản, Tống Trác Văn, một đảng viên đóng giả làm cảnh sát tuần tra đường sắt, đã bị trưởng phòng Đặc vụ Quan Tuyết nhầm là ân nhân cứu mạng của mình - thực ra là Tống Trác Vũ, anh sinh đôi thất lạc nhiều năm của Trác Văn. Trác Văn được giao nhiệm vụ cao nhất là điều tra vụ việc quân đội Kanto của Trưởng phòng Asano Daigo đến Cáp Nhĩ Tân, và lợi dụng Quan Tuyết để tiếp cận phòng Đặc vụ. Nhưng đột nhiên Tống Trác Vũ lại xuất hiện, đẩy Trác Văn vào tình thế khó lường. Quan Tuyết máu lạnh đa nghi, tàn nhẫn và độc ác, còn Trác Vũ lại hành động bốc đồng, thường xuyên vô tình phá hỏng kế hoạch của Trác Văn.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 7, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tần Hải Lộ","avatar":""},{"name":"Tần Hạo","avatar":""},{"name":"Dương Mịch","avatar":""},{"name":"Chu Á Văn","avatar":""},{"name":"La Tấn","avatar":""},{"name":"Trương Quốc Lập","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["没有我的城","风城","哈尔滨1944","Harbin 1944","HaErBin1944","哈爾濱一九四四","In the Name of the Brother","哈尔滨一九四四"]', 1784690324177);
