INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-so-la-benh-vien-sat-nhan-dai-loan', 'Tần Số Lạ: Bệnh Viện Sát Nhân Đài Loan', 'Strange Frequencies: Taiwan Killer Hospital', 'https://phimimg.com/upload/vod/20250904-1/4bc9b7f32b88b0c57c7149dcab8a0050.jpg', 'https://phimimg.com/upload/vod/20250904-1/bbb43f0f175b4a101d4136fc2ba5454e.jpg', '<p>Trong cuộc săn ma được phát trực tiếp, bảy người nổi tiếng khám phá một bệnh viện ma ám, hoang tàn rồi phát hiện thế lực quỷ dữ còn khủng khiếp hơn họ có thể tưởng tượng.</p>', 'Full', 1, 'single', 'completed', 15, 2024, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Enrique Gil","avatar":""},{"name":"Jane De Leon","avatar":""},{"name":"Alexa Miro","avatar":""},{"name":"Mary Jean Lastimosa","avatar":""},{"name":"Rob Gomez","avatar":""},{"name":"Raf Pineda","avatar":""},{"name":"Ryan Azurin","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Strange Frequencies: Taiwan Killer Hospital"]', 1784690324177);
