INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kamen-rider-gavv', 'Kamen Rider Gavv', 'Kamen Rider Gavv', 'https://phimimg.com/upload/vod/20250414-1/0a520faaaf09537f5656a62de92542b5.jpg', 'https://phimimg.com/upload/vod/20250414-1/1d46fd1b3a23a916fc3d6565f2b845fa.jpg', '<p>Granutes là những sinh vật thông minh sống ẩn mình trong thế giới loài người. Chúng bắt cóc con người để phục vụ cho mục đích tạo ra “Kẹo chợ đen”. Khi ngày càng nhiều người bị tấn công bởi Granutes, một chàng trai trẻ đến từ thế giới khác tên là Shoma đã đứng lên để bảo vệ nhân loại. Cùng với Gochizo — những quái vật nhỏ sinh ra từ việc ăn kẹo — Shoma biến thân thành Kamen Rider Gavv bằng một chiếc thắt lưng có hình dáng như miệng!</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 21, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hidekazu Chinen","avatar":""},{"name":"Yusuke Hino","avatar":""},{"name":"Nozomi Miyabe","avatar":""},{"name":"Kohei Shoji","avatar":""},{"name":"Machi Chitose","avatar":""},{"name":"Ryo Takizawa","avatar":""},{"name":"Ruito Koga","avatar":""},{"name":"Honoka Kawasaki","avatar":""},{"name":"Takashi Tsukamoto","avatar":""},{"name":"Shintaro Asanuma","avatar":""},{"name":"Kouki Sakurai","avatar":""},{"name":"Ayu Shoji","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["假面骑士加布","假面骑士Gavv","Rider Gavv","Masked Rider