INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-xua-co-mot-chuyen-tinh', 'Ngày Xưa Có Một Chuyện Tình', 'Once Upon A Love Story', 'https://phimimg.com/upload/vod/20250901-1/377ca3402a12c55372f0145f49c0e4a5.jpg', 'https://phimimg.com/upload/vod/20250901-1/e8b2e71c237e7dbbee1c014091f44351.jpg', '<p>Ngày Xưa Có Một Chuyện Tình xoay quanh câu chuyện tình bạn, tình yêu giữa hai chàng trai và một cô gái từ thuở ấu thơ cho đến khi trưởng thành, phải đối mặt với những thử thách của số phận. Trải dài trong 4 giai đoạn từ năm 1987 - 2000, ba người bạn cùng tuổi - Vinh, Miền, Phúc đã cùng yêu, cùng bỡ ngỡ bước vào đời, va vấp và vượt qua.</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Ngọc Xuân","avatar":""},{"name":"Lương Anh Vũ","avatar":""},{"name":"Đỗ Nhật Hoàng","avatar":""},{"name":"Hạo Khang","avatar":""},{"name":"Rima Thanh Vy","avatar":""},{"name":"Kiều Trinh","avatar":""},{"name":"Mai Thế Hiệp","avatar":""},{"name":"Tấn Thi","avatar":""},{"name":"Bá Cường","avatar":""},{"name":"Ngân Quỳnh","avatar":""},{"name":"Xuân Nghị","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ngày Xưa Có Một Chuyện Tình"]', 1784690324178);
