INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tran-chien-song-con', 'Trận Chiến Sống Còn', 'To Live Through Death', 'https://phimimg.com/upload/vod/20250825-1/07ecd7122e0d34f9c875e129fcea6844.jpg', 'https://phimimg.com/upload/vod/20250825-1/64c1e1551d4657705a2c514b357fb89e.jpg', '<p>Trên một hòn đảo nào đó ở Thái Bình Dương, tổ chức buôn người phi pháp thủ đoạn tày trời bắt cóc và lừa đảo người Trung Quốc ở nước ngoài. Để giải cứu con gái nuôi bị bắt cóc, ông Trần, người thường ngày ít nói, không ngần ngại tiết lộ bí mật đã giấu kín suốt 20 năm qua, hợp tác với cảnh sát trẻ địa phương A Xán để chống lại tập đoàn tội phạm khổng lồ và tiến hành cuộc quyết chiến sinh tử với thế lực đen tối.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Louis Fan Siu-Wong","avatar":""},{"name":"Andy On","avatar":""},{"name":"Zhao Ziqi","avatar":""},{"name":"Eleanor Lee","avatar":""},{"name":"Yu Kang","avatar":""},{"name":"Jackson Liu","avatar":""},{"name":"Zhang Di","avatar":""},{"name":"Bingo Zhou","avatar":""},{"name":"Jing Gangshan","avatar":""},{"name":"Chen Kaixin","avatar":""},{"name":"Johnny Zhao","avatar":""},{"name":"He Yutong","avatar":""},{"name":"Wang Teng","avatar":""},{"name":"Du Jingyi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["To Live through Death","Deadly Impact","수사일박","殊死一搏"]', 1784690324178);
