INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mobile-suit-gundam-seed-freedom', 'Mobile Suit Gundam SEED FREEDOM', 'Mobile Suit Gundam SEED FREEDOM', 'https://phimimg.com/upload/vod/20250821-1/617e4d67f1a5974f9ef5b26fa1239136.jpg', 'https://phimimg.com/upload/vod/20250821-1/98d8d5993baa8f3cea994d7ecf1cba00.jpg', '<p>C.E 75, ngọn lửa xung đột vẫn không dừng. Trong đó là những phong trào giành độc lập, và những cuộc kích động vũ trang gây ra bởi Blue Cosmos… Để xoa dịu tình hình, tổ chức giám sát hòa bình quốc tế mang tên Compass được sáng lập, với Lacus là Tổng thư ký đầu tiên. Là thành viên của Compass, Kira cùng đồng đội bắt đầu can thiệp vào những cuộc chiến trên khắp thế giới. Nhân cơ hội đó, Foundation, một đất nước mới nổi đã đề xuất một chiến dịch chung nhắm vào đầu não của Blue Cosmos.</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Soichiro Hoshi","avatar":""},{"name":"Rie Tanaka","avatar":""},{"name":"Akira Ishida","avatar":""},{"name":"Nanako Mori","avatar":""},{"name":"Kenichi Suzumura","avatar":""},{"name":"Maaya Sakamoto","avatar":""},{"name":"Houko Kuwashima","avatar":""},{"name":"Fumiko Orikasa","avatar":""},{"name":"Kotono Mitsuishi","avatar":""},{"name":"Takehito Koyasu","avatar":""},{"name":"Tomokazu Seki","avatar":""},{"name":"Akira Sasanuma","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Hochu Otsuka","avatar":""},{"name":"Jun Fukuyama","avatar":""},{"name":"Michiko Neya","avatar":""},{"name":"Taiten Kusu","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kị