INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('deadpool-va-wolverine', 'Deadpool Và Wolverine', 'Deadpool & Wolverine', 'https://phimimg.com/upload/vod/20250821-1/1ec414f82adc729512410edd1b083996.jpg', 'https://phimimg.com/upload/vod/20250821-1/45b6b9aad03ae0aa2aceb5d73419831a.jpg', '<p>Wade Wilson, chán nản, đang cố gắng sống cuộc đời bình thường sau những ngày làm lính đánh thuê không mấy lương thiện, Deadpool. Nhưng khi quê hương của anh đứng trước nguy cơ diệt vong, Wade buộc phải khoác lại bộ đồ một lần nữa, cùng với một Wolverine còn miễn cưỡng hơn.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ryan Reynolds","avatar":""},{"name":"Hugh Jackman","avatar":""},{"name":"Emma Corrin","avatar":""},{"name":"Matthew Macfadyen","avatar":""},{"name":"Dafne Keen","avatar":""},{"name":"Jon Favreau","avatar":""},{"name":"Morena Baccarin","avatar":""},{"name":"Rob Delaney","avatar":""},{"name":"Leslie Uggams","avatar":""},{"name":"Jennifer Garner","avatar":""},{"name":"Wesley Snipes","avatar":""},{"name":"Channing Tatum","avatar":""},{"name":"Chris Evans","avatar":""},{"name":"Henry Cavill","avatar":""},{"name":"Wunmi Mosaku","avatar":""},{"name":"Aaron Stanford","avatar":""},{"name":"Tyler Mane","avatar":""},{"name":"Karan S","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Quái Nhân Deadpool 3","Deadpool 3","Marvel Studios'' Deadpool & Wolve