INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-gioi-tuoi-dep', 'Thế Giới Tươi Đẹp', 'Wonderful World', 'https://phimimg.com/upload/vod/20250820-1/ce991d000b59e52110b876a33edddda5.jpg', 'https://phimimg.com/upload/vod/20250820-1/264e96bf6d9003fd8c563aa64411a6cd.jpg', '<p>Một bộ phim trả thù hồi hộp, trong đó nhân vật nữ chính, người bị mất đi đứa con trai nhỏ của mình một cách bất công, trả thù kẻ thủ ác đã được pháp luật tha thứ và chữa lành vết thương cho cô.</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 9, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Nam-ju","avatar":""},{"name":"Cha Eun-woo","avatar":""},{"name":"Kim Kang-woo","avatar":""},{"name":"Lim Se-mi","avatar":""},{"name":"Yang Hye-ji","avatar":""},{"name":"Cha Soo-yeon","avatar":""},{"name":"Jeon Jung-il","avatar":""},{"name":"Park Hyuk-kwon","avatar":""},{"name":"Kil Hae-yeon","avatar":""},{"name":"Kang Myeong-ju","avatar":""},{"name":"Jin Geon-woo","avatar":""},{"name":"Lim Ji-sub","avatar":""},{"name":"Jin Jae-hee","avatar":""},{"name":"Kang Ae-sim","avatar":""},{"name":"Won Mi-kyung","avatar":""},{"name":"Oh Man-seok","avatar":""},{"name":"Kim Woo-hyun","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["원더풀월드","원더풀 월드","عالم رائع","美好世界","Thế Giới Tươi Đẹp"]', 1784690324178);
