INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-bay-tinh-yeu-2024', 'Cạm Bẫy Tình Yêu', 'Dosa Cinta', 'https://phimimg.com/upload/vod/20250715-1/4a609dd411b92428e70449c5a1567a11.jpg', 'https://phimimg.com/upload/vod/20250715-1/fa487c1eddfb947eaaebd1860d2e0560.jpg', '<p>Bộ phim kể về câu chuyện của nữ sinh đại học Adelia (do Rita Nadira thủ vai). Cô có nhiệm vụ vén màn bí mật đen tối em gái mình là Kai (do Izzati Abdullah thủ vai) tự sát vào sáu năm trước. Sau đó, Adelia gặp Medha (do Tiz Zaqyah thủ vai), chủ của một khu nghỉ dưỡng ở Langkawi và là vợ của Ehad - người đàn ông hoàn hảo trong mắt Medha. Thông qua lần gặp gỡ này, Adelia có thể trả thù cho cái chết của em gái mình không?</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 15, 2024, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Rita Nadira","avatar":""},{"name":"Tiz Zaqyah","avatar":""},{"name":"Ikmal Amry","avatar":""},{"name":"Azlee Khairi","avatar":""},{"name":"Aidit Noh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324178);
