INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cam-bay-tinh-yeu-2024', 'Cạm Bẫy Tình Yêu', 'Dosa Cinta', 'cạm bẫy tình yêu dosa cinta rita nadira tiz zaqyah ikmal amry azlee khairi aidit noh ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-cuoi-the-ky', 'Tình Yêu Cuối Thế Kỷ', 'Ms. Apocalypse', 'https://phimimg.com/upload/vod/20250817-1/df10b2855e2817d89868b924b3d4571c.jpg', 'https://phimimg.com/upload/vod/20250817-1/a0c0b8c81b7aebe65d8aebf015869c1d.jpg', '<p>Young-mi, nhân viên ghi sổ của một nhà máy, bị đồng nghiệp chế giễu vì vẻ ngoài tầm thường, đến mức đặt cho cô biệt danh “Cô Tận Thế”. Người duy nhất đối xử tử tế với cô là Do-young, một tài xế giao hàng. Nuôi dưỡng tình cảm dành cho anh, Young-mi tìm mọi cách để che chở cho Do-young — ngay cả khi phát hiện ra anh đã biển thủ tiền công ty. Đêm cuối cùng của năm 1999, khi cả thế giới hoang mang trước viễn cảnh tận thế, Young-mi bị bắt vì tiếp tay cho tội lỗi của Do-young. Thiên niên kỷ mới của cô khởi đầu trong cay đắng. Vài tháng sau khi ra tù, Young-mi bất ngờ chạm mặt Yu-jin — vợ của Do-young. Nhưng thay vì oán trách, Yu-jin lại đưa ra một đề nghị khó tin… và cũng khó cưỡng.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee You-young","avatar":""},{"name":"Lim Sun-woo","avatar":""},{"name":"Roh Jae-won","avatar":""},{"name":"Jang Sung-yoon","avatar":""},{"name":"Moon Dong-hyeok","avatar":""},{"name":"Kim Gi-ri","avatar":""},{"name":"Byun Joong-hee","avatar":""},{"name":"Shon Jung-hwan","avatar":""},{"name":"Park So-yoon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Love at the End of the Century","세기말의 사랑"]', 1784690324178);
