INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-thay-va-margarita', 'Bậc Thầy Và Margarita', 'The Master And Margarita', 'https://phimimg.com/upload/vod/20250817-1/8865f94338237b6d0ac5dc1f92f595fc.jpg', 'https://phimimg.com/upload/vod/20250817-1/fb4d3519f403d9603ad6df67f40fee7d.jpg', '<p>Moscow, thập niên 1930. Một nhà văn bị cấm xuất bản và khai trừ khỏi hội chính thức, mất sạch kế sinh nhai. Anh bắt đầu viết cuốn tiểu thuyết về một vị khách bí ẩn từ bóng tối… và dần không phân biệt nổi giữa câu chuyện mình viết và hiện thực quanh mình.</p>', 'Full', 1, 'single', 'completed', 22, 2024, 'Vietsub', 'FHD', 'Nga', 0, '[{"name":"Evgeny Tsyganov","avatar":""},{"name":"Yuliya Snigir","avatar":""},{"name":"August Diehl","avatar":""},{"name":"Yuri Kolokolnikov","avatar":""},{"name":"Leonid Yarmolnik","avatar":""},{"name":"Aleksandr Yatsenko","avatar":""},{"name":"Aleksey Guskov","avatar":""},{"name":"Aleksey Rozin","avatar":""},{"name":"Igor Vernik","avatar":""},{"name":"Marat Basharov","avatar":""},{"name":"Polina Aug","avatar":""},{"name":"Dmitry Lysenkov","avatar":""},{"name":"Yana Sekste","avatar":""},{"name":"Pavel Vorozhtsov","avatar":""},{"name":"Claes Bang","avatar":""},{"name":"Aaron Vodovoz","avatar":""},{"name":"Yura","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Master i Margarita","Woland","Воланд","大師與瑪格麗特","Мастер и Маргарита","Майсторът и Маргарита"]', 1784690324178);
