INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-giau-voi-ma', 'Làm Giàu Với Ma', 'Betting With Ghost', 'https://phimimg.com/upload/vod/20250323-1/5c8b4a2c724d8cbee887c0b90767633d.jpg', 'https://phimimg.com/upload/vod/20250323-1/1b5a22c27996cde1f32b19c449853063.jpg', '<p>Trong Làm Giàu Với Ma, Tuấn Trần vào vai Lanh - một thanh niên lêu lổng, ngỗ ngược, dính vào cờ bạc nợ nần. Trên quãng đường chạy trốn khỏi đám giang hồ chủ nợ hung hăng, anh vô tình &quot;đụng&quot; phải ma nữ Na (Diệp Bảo Ngọc) và bị cô nàng nhờ vả giúp mình tìm gặp đứa con mà cô đã phải lìa xa từ lúc chào đời. Đổi lại, cô sẽ dùng quyền năng tâm linh để giúp anh &quot;làm giàu&quot;.</p>', 'Full', 1, 'single', 'completed', 19, 2024, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Tuấn Trần","avatar":""},{"name":"Diệp Bảo Ngọc","avatar":""},{"name":"Hoài Linh","avatar":""},{"name":"Lê Giang","avatar":""},{"name":"La Thành","avatar":""},{"name":"Quang Minh","avatar":""},{"name":"Hoàng Phi","avatar":""},{"name":"Bình Hưng","avatar":""},{"name":"Hữu Châu","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["见鬼发财","見鬼發財","Làm Giàu Với Ma"]', 1784690324178);
