INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('long-vu-den-dieu-mua-cua-geisha', 'Lông Vũ Đen: Điệu Múa Của Geisha', 'Dark Feathers: Dance Of The Geisha', 'https://phimimg.com/upload/vod/20250813-1/eff119cb442a8528c4b2ac0ee6d4cde5.jpg', 'https://phimimg.com/upload/vod/20250813-1/f37a03382202ecd9ed9132f0637da188.jpg', '<p>Kate sống ẩn mình ở San Francisco với công việc nhiếp ảnh và vũ công. Khi bạn nhảy của cô lần lượt bị sát hại, cô rơi vào tầm ngắm của cảnh sát, từ đó hé lộ bí mật về thân phận của cô.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Crystal J. Huang","avatar":""},{"name":"Gilles Marini","avatar":""},{"name":"Karina Smirnoff","avatar":""},{"name":"Michael Madsen","avatar":""},{"name":"Natalya Nikolaeva","avatar":""},{"name":"Lan Kay","avatar":""},{"name":"Phoebe Ho","avatar":""},{"name":"Rico Simonini","avatar":""},{"name":"Kyosuke Mukai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Dark Feathers: Dance of the Geisha"]', 1784690324178);
