INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('shoshimin-cach-de-tro-nen-binh-thuong-phan-1-tieu-thi-dan', 'SHOSHIMIN: Cách Để Trở Nên Bình Thường (Phần 1) (Tiểu Thị Dân)', 'How To Become Ordinary (Season 1)', 'shoshimin: cách để trở nên bình thường (phần 1) (tiểu thị dân) how to become ordinary (season 1) shuichiro umeda hina youmiya makoto furukawa shōshimin shirīzu 소시민 시리즈 2기 как стать обычным โชชิมิง ซีรีส์ shoshimin: how to become ordinary shoushimin series shōshimin series the petit bourgeois series how to become ordinary 小市民シリーズ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thap-tam-thai-bao-phong-van-tai-khoi', 'Thập Tam Thái Bảo: Phong Vân Tái Khởi', 'Thirteen Generals: Wind And The Cloud Rise Again', 'https://phimimg.com/upload/vod/20250808-1/5b91cae78523121b4451b2252f9b7261.jpg', 'https://phimimg.com/upload/vod/20250808-1/f6d889b6905dcce022e71da356973358.jpg', '<p>Bộ phim lấy bối cảnh giang hồ đầy biến động, khi thế lực hắc đạo trỗi dậy âm mưu thao túng võ lâm. Mười ba nghĩa sĩ từng nổi danh một thời nay lại phải tái hợp sau nhiều năm chia cách. Mỗi người mang trong mình bí mật và vết thương riêng, nhưng vì lời thề xưa và nghĩa khí huynh đệ, họ cùng nhau đối mặt với những âm mưu hiểm độc, các trận quyết đấu sinh tử và những biến cố xoay chuyển cục diện võ lâm. Câu chuyện là hành trình của tình bằng hữu, lòng trung nghĩa và khát vọng bảo vệ chính đạo trước bóng tối đang lan tràn.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Chiêu","avatar":""},{"name":"Quản Kim Lân","avatar":""},{"name":"Tào Ngự Trình","avatar":""},{"name":"Trần Tĩnh Khang","avatar":""},{"name":"Ngô Xuân Di","avatar":""},{"name":"Đỗ Dật Hành","avatar":""},{"name":"Đỗ Ngọc Minh","avatar":""},{"name":"Viên Tường Nhân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Thirteen Generals Wind and the Cloud Rise Again","十三太保之风云再起"]', 1784690324178);
