INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thap-tam-thai-bao-phong-van-tai-khoi', 'Thập Tam Thái Bảo: Phong Vân Tái Khởi', 'Thirteen Generals: Wind And The Cloud Rise Again', 'thập tam thái bảo: phong vân tái khởi thirteen generals: wind and the cloud rise again vương chiêu quản kim lân tào ngự trình trần tĩnh khang ngô xuân di đỗ dật hành đỗ ngọc minh viên tường nhân thirteen generals wind and the cloud rise again 十三太保之风云再起', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('na-tra-ma-dong-quy-lai', 'Na Tra: Ma Đồng Quy Lai', 'Nezha: Demon Child Is Back', 'https://phimimg.com/upload/vod/20250808-1/a53e6f44d7e5694830cf8453b8b2de08.jpg', 'https://phimimg.com/upload/vod/20250808-1/ec8fba9e48ee3e4df89c5ab317eb5426.jpg', '<p>Long Vương dẫn theo Tứ Hải Long Vương dùng nước dìm Trần Đường Quan để ép Lý Tịnh giao nộp Na Tra. Na Tra tự vẫn khiến thân xác tiêu tan, Thái Ất muốn xây dựng đền thờ để giúp Na Tra tái sinh. Nhiên Đăng Đạo Nhân tặng Lý Tịnh tháp Linh Lung, nói rằng nếu Na Tra nhận hương khói mà không lập công, sẽ bị ma tâm phản phệ. Lý Tịnh không nỡ để Na Tra lầm đường lạc lối nên quyết định phá đền, khiến Na Tra hiểu lầm, trong khi đó, mẹ Na Tra và Thái Ất lén thờ phụng bài vị của Na Tra. Long Vương tấn công bất ngờ khi Na Tra tái sinh, mọi người đều bị đè dưới tháp. Cha con Lý Tịnh và Na Tra hiểu lầm nhau sâu sắc, trước sau đều có địch, vừa phải chiến đấu với nhau, vừa phải đề phòng Long tộc và quái vật trong tháp tấn công, nên quyết định tạm gác mâu thuẫn để thoát khỏi nơi nguy hiểm. Hai người tiến sâu vào trong tháp, gặp nhiều ảo cảnh, kẻ thù ẩn náu bên trong, liên tục tấn công khiến cha con Lý Tịnh kiệt sức. Cuối cùng, hai người bỏ qua hiềm khích, cùng nhau đánh bại Long Vương.</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hạ Trung Hoa","avatar":""},{"name":"Trần Dực Đồng","avatar":""},{"name":"Thương Na","avatar":""},{"name":"Triệu Tử Lạc","avatar":""},{"name":"Dự Khánh Huyển","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Nezha.Demon.Child.is.Back","Nezha Demon Child is Back","哪吒·魔童归来"]', 1784690324178);
