INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('diem-hen-tu-than', 'Điểm Hẹn Tử Thần', 'The Killers', 'https://phimimg.com/upload/vod/20250808-1/ed4b78c313d55cf5bad7f74648dcdfc6.jpg', 'https://phimimg.com/upload/vod/20250808-1/c0c421cd5ffb36f45b6daa431b96af87.jpg', '<p>Bốn đạo diễn - bốn câu chuyện nghẹt thở đen tối, chẳng thể đoán trước. Những cuộc gặp xa lạ lại đủ thay đổi số phận của một gã đàn ông, một nữ bartender, ba tên tội phạm và hai sát thủ.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Shim Eun-kyung","avatar":""},{"name":"Yeon Woo-jin","avatar":""},{"name":"Yang Ik-june","avatar":""},{"name":"Jeon Seong-woo","avatar":""},{"name":"Jung Yi-seo","avatar":""},{"name":"Jang Seo-won","avatar":""},{"name":"Hong Xa-bin","avatar":""},{"name":"Ji Woo","avatar":""},{"name":"Kim Jong-soo","avatar":""},{"name":"Bek Hyun-jin","avatar":""},{"name":"Tae Won-seok","avatar":""},{"name":"Nana","avatar":""},{"name":"Oh Yeon-ah","avatar":""},{"name":"Jang Hyun-sung","avatar":""},{"name":"Lee Jun-hyeok","avatar":""},{"name":"Kim Min","avatar":""},{"name":"Jun Suk-ho","avatar":""},{"name":"Park Sang-myeon","avatar":""},{"name":"Kwak Min-kyu","avatar":""},{"name":"Lee","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Killers","杀手们","더 킬러스"]', 1784690324178);
