INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-tram-co-doc-phan-2', 'Không Trạm Cô Độc (Phần 2)', 'Beacon 23 (Season 2)', 'https://phimimg.com/upload/vod/20250724-1/f850841c4a154371997bf56cdc83ab38.jpg', 'https://phimimg.com/upload/vod/20250724-1/5f879af729234a094798bbe12fb19d4c.jpg', '<p>Halan là người duy nhất vận hành Beacon 23, ngọn hải đăng cô độc giữa các vì sao trong không gian sâu thẳm. Một ngày nọ, khi phi thuyền Crest gặp tai nạn gần hải đăng, Halan chỉ kịp thời cứu được Aster - một đặc vụ được chính phủ cử đến. Mắc kẹt cùng nhau ở nơi tận cùng vũ trụ, một cuộc chiến tâm lý căng thẳng bắt đầu diễn ra giữa hai con người đang cố gắng che giấu những bí mật của riêng mình.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Lena Headey","avatar":""},{"name":"Stephan James","avatar":""},{"name":"Natasha Mumba","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Маяк 23","فانوس راهنما ۲۳","Beacon 23"]', 1784690324178);
