INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-kich-diet-soi-chien-dich-san-mau', 'Biệt Kích Diệt Sói (Chiến Dịch Săn Máu)', 'Operation Blood Hunt', 'https://phimimg.com/upload/vod/20250804-1/56517c87df53ccdafefd4e3eb7778371.jpg', 'https://phimimg.com/upload/vod/20250804-1/6304ef639c183d9c3dd6702b6ee0c521.jpg', '<p>Phim lấy bối cảnh năm 1944, trong Thế Chiến II. Một đơn vị biệt kích bao gồm những quân nhân bị loại và không đội trời chung được giao nhiệm vụ đến một hòn đảo biệt lập ở Nam Thái Bình Dương, để điều tra sự biến mất bí ẩn của một đơn vị Thủy quân Lục chiến Hoa Kỳ. Lúc đầu, họ tin rằng người Nhật là thủ phạm
 Khi đến nơi, nhóm phát hiện dấu hiệu của một thảm sát kinh hoàng: xác chết nằm rải rác, thi thể bị tra tấn, có chữ “WEREWOLVES” được khắc lên tường. Họ nhanh chóng nhận ra rằng kẻ gây ra không phải là con người mà là một bầy sói biến dị—werewolves với sức mạnh siêu nhiên.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Jonathan Rhys Meyers","avatar":""},{"name":"Louis Mandylor","avatar":""},{"name":"Peter Dobson","avatar":""},{"name":"Quinton ''Rampage'' Jackson","avatar":""},{"name":"Sonia Couling","avatar":""},{"name":"Gary Cairns","avatar":""},{"name":"Myles Clohessy","avatar":""},{"name":"Ulf Pilblad","avatar":""},{"name":"Tofan Pirani","avatar":""},{"name":"Bear Williams","avatar":""},{"name":"Alejandra Norris","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["Operation Blood Hunt"]', 1784690324178);
