INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuu-long-thanh-trai-vay-thanh', 'Cửu Long Thành Trại: Vây Thành', 'Twilight Of The Warriors: Walled In', 'https://phimimg.com/upload/vod/20250804-1/e220a409c2591bc567d2b38c56e7a811.jpg', 'https://phimimg.com/upload/vod/20250804-1/83e5e2dea45fbff6878a24b893b54a26.jpg', '<p>Lạc Quân nhập cảnh trái phép vào Hồng Kông và được Quyền Phong giúp đỡ để tồn tại ở Cửu Long Thành Trại - khu vực phức tạp có rất nhiều băng đảng xã hội đen. Trong lúc gặp nạn họ vô tình phát hiện ra quy luật ngầm giữa sự hỗn loạn phía sau nó. Đứng trước những thế lực tội ác, họ đứng lên chống lại âm mưu đen tối của kẻ thù để giữ lời thề bảo vệ sự bình yên của nơi này.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cổ Thiên Lạc","avatar":""},{"name":"Hồng Kim Bảo","avatar":""},{"name":"Lâm Phong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["เมืองพญายมปิดบัญชียมบาล","Jiu Long cheng zhai: Wei cheng","九龙城寨之围城","Gau2lung4sing4zaai6 zi1 Wai4sing4","九龍城寨．圍城","گرگ و میش جنگجویان : محصور","トワイライト・ウォリアーズ 決戦！九龍城砦","Twilight of the Warriors: Walled In","Hongkong Warriors","九龍城寨之圍城"]', 1784690324178);
