INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuu-long-thanh-trai-vay-thanh', 'Cửu Long Thành Trại: Vây Thành', 'Twilight Of The Warriors: Walled In', 'cửu long thành trại: vây thành twilight of the warriors: walled in cổ thiên lạc hồng kim bảo lâm phong เมืองพญายมปิดบัญชียมบาล jiu long cheng zhai: wei cheng 九龙城寨之围城 gau2lung4sing4zaai6 zi1 wai4sing4 九龍城寨．圍城 گرگ و میش جنگجویان : محصور トワイライト・ウォリアーズ 決戦！九龍城砦 twilight of the warriors: walled in hongkong warriors 九龍城寨之圍城', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam', 'Cám', 'The Sisters', 'https://phimimg.com/upload/vod/20250302-1/887291d6f943171d2815f048130232dd.jpg', 'https://phimimg.com/upload/vod/20250302-1/95297d8023e0e6cca061455cdc22cef0.jpg', '<p>Cám - một cô gái sinh ra với khuôn mặt dị dạng do một lời nguyền truyền qua nhiều thế hệ. Cám bị cha mình xem như một vết nhơ của gia đình và bị đày xuống nhà sau, sống như người hầu và chịu đựng sự ngược đãi. Trong khi đó, người chị cùng cha khác mẹ của cô là Tấm nhận được tình yêu thương và sự nuông chiều của cha. Mặc dù được bao bọc, Tấm vẫn cố gắng chăm sóc Cám, nhưng lòng căm thù của Cám ngày càng sâu sắc do sự lạnh lùng của gia đình.</p>', 'Full', 1, 'single', 'completed', 21, 2024, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Lam Thanh My","avatar":""},{"name":"Rima Thanh Vy","avatar":""},{"name":"Thuý Diễm","avatar":""},{"name":"Quốc Cường","avatar":""},{"name":"Ngô Hải Nam","avatar":""},{"name":"Nguyễn Thị Ngọc Hiệp","avatar":""},{"name":"Mai Thế Hiệp","avatar":""},{"name":"Ngô Phạm Hạnh Thúy","avatar":""},{"name":"Nguyen Phuoc Loc","avatar":""},{"name":"Trần Doãn Hoàng","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["CÁM"]', 1784690324178);
