INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cam', 'Cám', 'The Sisters', 'cám the sisters lam thanh my rima thanh vy thuý diễm quốc cường ngô hải nam nguyễn thị ngọc hiệp mai thế hiệp ngô phạm hạnh thúy nguyen phuoc loc trần doãn hoàng cám', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-se-tro-thanh-nu-phan-dien-di-vao-lich-su', 'Tôi Sẽ Trở Thành Nữ Phản Diện Đi Vào Lịch Sử', 'I''ll Become A Villainess Who Goes Down In History', 'https://phimimg.com/upload/vod/20250804-1/75a689a23e3c61b1273a31e1c131f2fe.jpg', 'https://phimimg.com/upload/vod/20250804-1/7f435895e0d6adc7388ea7e0b8cca36d.jpg', '<p>Alicia là một thiên kim tiểu thư tái sinh trong thế giới game. Không giống những nữ chính thường thấy, cô không ham thích vai trò anh hùng hay trở thành người được yêu thương, quý mến mà quyết định chiếm lấy vị trí nữ phản diện vĩ đại nhất lịch sử, để sống theo cách mình muốn và phá vỡ mọi định kiến trong giới quý tộc. Với trí tuệ sắc bén, khả năng giao tiếp khéo léo và tinh thần không chịu khuất phục, Alicia bắt đầu hành trình gây dựng thanh danh phản diện, chinh phục cả trái tim những người từng xem thường cô.</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kanna Nakamura","avatar":""},{"name":"Kaito Ishikawa","avatar":""},{"name":"Manaka Iwami","avatar":""},{"name":"Hiroshi Yanaka","avatar":""},{"name":"Rumi Okubo","avatar":""},{"name":"Haruki Ishiya","avatar":""},{"name":"Kaede Hondo","avatar":""},{"name":"Rie Takahashi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["成为名垂青史的恶役千金吧","成为名垂青史的反派大小姐吧","بزرگترین شرور دنیا","من به شروری تبدیل می‌شوم که در تاریخ ثبت می‌شود","من به شروری تبدیل می‌شوم که تاریخ از او یاد خواهد کرد","Rekishi ni Nokoru Akujo ni Naru zo: Akuyaku Reijou ni Naru hodo Ouji no Dekiai wa Kasoku suru you desu!","歴史に残る悪女になるぞ","Rekishi ni Nokoru Akujo ni Naru zo: Akuyaku Reijō ni Naru hodo Ōji no Dekiai wa Kasoku suru yō desu!","Rekishi Ni Nokoru Akujo Ni Naruzo","I''ll Become a Villainess That Will Go Down in History","I''ll Become a Villainess That Will Go Down in History: The More of a Villainess I Become, the More the Prince Will Dote on Me"]', 1784690324178);
