INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('toi-se-tro-thanh-nu-phan-dien-di-vao-lich-su', 'Tôi Sẽ Trở Thành Nữ Phản Diện Đi Vào Lịch Sử', 'I''ll Become A Villainess Who Goes Down In History', 'tôi sẽ trở thành nữ phản diện đi vào lịch sử i''ll become a villainess who goes down in history kanna nakamura kaito ishikawa manaka iwami hiroshi yanaka rumi okubo haruki ishiya kaede hondo rie takahashi 成为名垂青史的恶役千金吧 成为名垂青史的反派大小姐吧 بزرگترین شرور دنیا من به شروری تبدیل می‌شوم که در تاریخ ثبت می‌شود من به شروری تبدیل می‌شوم که تاریخ از او یاد خواهد کرد rekishi ni nokoru akujo ni naru zo: akuyaku reijou ni naru hodo ouji no dekiai wa kasoku suru you desu! 歴史に残る悪女になるぞ rekishi ni nokoru akujo ni naru zo: akuyaku reijō ni naru hodo ōji no dekiai wa kasoku suru yō desu! rekishi ni nokoru akujo ni naruzo i''ll become a villainess that will go down in history i''ll become a villainess that will go down in history: the more of a villainess i become, the more the prince will dote on me', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-gioi-that-cach', 'Dị Giới Thất Cách', 'No Longer Allowed in Another World', 'https://phimimg.com/upload/vod/20250804-1/f548717fae30c1a7f9cb58094cf8cbef.jpg', 'https://phimimg.com/upload/vod/20250804-1/1ad5cef79e0053841b85df186aaae403.jpg', '<p>Nhà văn Sensei bị tai nạn ngay trước khi định kết thúc cuộc sống cùng người yêu Sacchan và tỉnh dậy ở một thế giới khác. Bị nhận nhầm là nhà thám hiểm, anh được giao nhiệm vụ tiêu diệt quỷ vương nhưng chỉ muốn tìm Sacchan. Trên đường đi, anh cứu võ sư Tama và được cô đồng hành để trả ơn. Nữ tư tế Annette cũng gia nhập nhóm và bị cuốn hút bởi ý chí mạnh mẽ của Sensei. Cả ba dấn thân vào hành trình phiêu lưu với đầy quái vật và hiểm nguy đang chờ đợi, nơi con người có thể là kẻ thù đáng sợ nhất.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hiroshi Kamiya","avatar":""},{"name":"Rumi Okubo","avatar":""},{"name":"Sayumi Suzushiro","avatar":""},{"name":"Makoto Koichi","avatar":""},{"name":"Hina Kino","avatar":""},{"name":"Aoi Yuuki","avatar":""},{"name":"Mai Nakahara","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Isekai Shikkaku","異世界失格","No Longer Human… In Another World","No Longer Allowed in Another World"]', 1784690324178);
