INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cach-nuong-tinh-yeu-cua-chung-ta-yaiteru-futari-2024', 'Cách Nướng Tình Yêu Của Chúng Ta (Yaiteru Futari)', 'How To Grill Our Love', 'https://phimimg.com/upload/vod/20250731-1/ad74e6f456ef6baedbf40b8b6a7f9175.jpg', 'https://phimimg.com/upload/vod/20250731-1/4c4a5d0585f8acdf04807321d0fc66d1.jpg', '<p>Cuộc sống hôn nhân của hai người bắt đầu từ &quot;ngày hẹn hò thứ 0&quot;, là một cuộc hôn nhân cuối tuần khi sống xa nhau giữa Tokyo và Hamamatsu. Hai người vẫn dùng kính ngữ với nhau... Cảm giác hồi hộp khi nắm tay, và rồi lần đầu tiên... Một điểm hấp dẫn của bộ phim là mối tình chậm rãi, vụng về nhưng đầy day dứt của hai người không giỏi trong chuyện yêu đương.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Mario Kuroba","avatar":""},{"name":"Sayuri Matsumura","avatar":""},{"name":"Shogo Hama","avatar":""},{"name":"Mahiru Konno","avatar":""},{"name":"Shunya Kaneko","avatar":""},{"name":"Watanabe Mina","avatar":""},{"name":"Yagi Hibiki","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["小夫妻的火烤新婚生活","爱情是烤肉的滋味","Yaiteru Futari Kosai 0Nichi Kekkon kara Koi wo Hajimeyo","焼いてるふたり","小夫妻的火烤新婚生活－交往0天 先結婚再談戀愛吧－","Grilling Together","Grilling For Two","Grilling Couple","焼いてるふたり ～交際0日 結婚から恋をはじめよう～"]', 1784690324178);
