INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tau-bang-gia-phan-4', 'Chuyến Tàu Băng Giá (Phần 4)', 'Snowpiercer (Season 4)', 'https://phimimg.com/upload/vod/20250729-1/52e3957638c65c53c5a48d943277ac6c.jpg', 'https://phimimg.com/upload/vod/20250729-1/c0c783420fca5ee896966b3430ff515a.jpg', '<p>Trái Đất đã đóng băng. Những người sống sót cuối cùng phải ở trên một con tàu khổng lồ chạy quanh thế giới, chật vật để cùng tồn tại trước sự cân bằng mong manh trên tàu.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Daveed Diggs","avatar":""},{"name":"Mickey Sumner","avatar":""},{"name":"Alison Wright","avatar":""},{"name":"Iddo Goldberg","avatar":""},{"name":"Roberto Urbina","avatar":""},{"name":"Rowan Blanchard","avatar":""},{"name":"Katie McGuinness","avatar":""},{"name":"Sam Otto","avatar":""},{"name":"Clark Gregg","avatar":""},{"name":"Michael Aronov","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["雪国列车","Snowpiercer","末世列車","רכבת הקרח","برف‌شکن","یخ‌شکن","قطار برف‌شکن","قطار یخ‌شکن","スノーピアサー","설국열차","Ледоломац","Сквозь снег","末日列車","Крізь сніг","Снігокол"]', 1784690324178);
