INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-tau-bang-gia-phan-4', 'Chuyến Tàu Băng Giá (Phần 4)', 'Snowpiercer (Season 4)', 'chuyến tàu băng giá (phần 4) snowpiercer (season 4) daveed diggs mickey sumner alison wright iddo goldberg roberto urbina rowan blanchard katie mcguinness sam otto clark gregg michael aronov 雪国列车 snowpiercer 末世列車 רכבת הקרח برف‌شکن یخ‌شکن قطار برف‌شکن قطار یخ‌شکن スノーピアサー 설국열차 ледоломац сквозь снег 末日列車 крізь сніг снігокол', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-thu-trung-sinh-chinh-phuc-long-de-be-ha', 'Tiểu Thư Trùng Sinh Chinh Phục Long Đế Bệ Hạ', 'The Do-Over Damsel Conquers The Dragon Emperor', 'https://phimimg.com/upload/vod/20250728-1/6396c60bafe6429f3f3a413e74150d3a.jpg', 'https://phimimg.com/upload/vod/20250728-1/401da7e6fc47b979517111427248387a.jpg', '<p>Jill là một nữ hiệp sĩ tài năng, đã tận tụy cống hiến, chiến đấu vì vương quốc nhưng lại nhận lấy sự phản bội tàn nhẫn từ người yêu và cả hoàng đế mà cô trung thành. Được ban cho cơ hội tái sinh, Jill quay về quá khứ trong hình hài của một cô bé quý tộc 10 tuổi, quyết tâm thay đổi số phận. Với ký ức kiếp trước, cô quyết định &quot;quyến rũ&quot; chính kẻ từng giết mình: Long Đế Hadis tàn bạo. Nhưng con đường mới này lại hé lộ nhiều bí ẩn, toan tính chính trị và dẫn đến mối quan hệ tréo ngoe giữa tiểu thư trùng sinh và vị đế vương cô độc.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kikunosuke Toya","avatar":""},{"name":"Mari Hino","avatar":""},{"name":"Shu Uchida","avatar":""},{"name":"Makoto Furukawa","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["La damisela que vuelve a intentarlo conquista al Emperador Dragón","重生大小姐正在攻略龙帝陛下","重启人生的千金小姐正在攻略龙帝陛下","Yarinaoshi Reijō wa Ryūtei Heika o Kōryaku-chū","Yarinaoshi Reijou wa Ryuutei Heika wo Kouryaku-chuu","Повернувшись, аристократка завойовує його величність імператора Дракона","The Returnee Noble Lady Attacks His Majesty the Dragon Emperor, Win Over the Dragon Emperor This Time Around, Noble Girl!","やり直し令嬢は竜帝陛下を攻略中"]', 1784690324178);
