INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tieu-thu-trung-sinh-chinh-phuc-long-de-be-ha', 'Tiểu Thư Trùng Sinh Chinh Phục Long Đế Bệ Hạ', 'The Do-Over Damsel Conquers The Dragon Emperor', 'tiểu thư trùng sinh chinh phục long đế bệ hạ the do-over damsel conquers the dragon emperor kikunosuke toya mari hino shu uchida makoto furukawa la damisela que vuelve a intentarlo conquista al emperador dragón 重生大小姐正在攻略龙帝陛下 重启人生的千金小姐正在攻略龙帝陛下 yarinaoshi reijō wa ryūtei heika o kōryaku-chū yarinaoshi reijou wa ryuutei heika wo kouryaku-chuu повернувшись, аристократка завойовує його величність імператора дракона the returnee noble lady attacks his majesty the dragon emperor, win over the dragon emperor this time around, noble girl! やり直し令嬢は竜帝陛下を攻略中', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-cung-em-ke', 'Sống Cùng Em Kế', 'Days With My Stepsister', 'https://phimimg.com/upload/vod/20250728-1/60b7bcec6a34fc00f3b3041d049b65d8.jpg', 'https://phimimg.com/upload/vod/20250728-1/56729d1241f5f3d244c7b5f403d29272.jpg', '<p>Sau cuộc tái hôn của bố cùng mẹ kế, nam sinh trung học Yuta bắt đầu sống chung một mái nhà với Saki - cô bạn cùng lớp xinh đẹp nay đã trở thành em gái. Ban đầu xa cách vì ngại ngùng và chưa hiểu nhau, cả hai dần xích lại qua những khoảnh khắc đời thường. Tình cảm giữa họ lớn dần theo cách nhẹ nhàng, vụng về nhưng đầy ấm áp qua những bữa cơm, bài học cùng sinh hoạt thường ngày. Tất cả tạo nên một câu chuyện thanh xuân pha trộn giữa sự lúng túng ngọt ngào và cảm xúc trong sáng tuổi mới lớn.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuki Nakashima","avatar":""},{"name":"Kouhei Amasaki","avatar":""},{"name":"Minori Suzuki","avatar":""},{"name":"Atsumi Tanezaki","avatar":""},{"name":"Daiki Hamano","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Gimai Seikatsu","義妹生活"]', 1784690324178);
