INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rezero-bat-dau-lai-o-the-gioi-khac-phan-3', 'ReZERO - Bắt Đầu Lại Ở Thế Giới Khác (Phần 3)', 'ReZERO - Starting Life In Another World (Season 3)', 'https://phimimg.com/upload/vod/20241011-1/d2ae4728aeae4c6266283f1d1e877ad4.jpg', 'https://phimimg.com/upload/vod/20241011-1/9518d679c888d385c5985d3113e4b14a.jpg', '<p>Re:ZERO - Bắt Đầu Lại Ở Thế Giới Khác (Phần 3) diễn ra ngay sau sự kiện giải phóng dinh thự Roswaal và Great Rabbit bị tiêu diệt. Subaru cùng Emilia đã trải qua một năm tương đối yên bình sau nhiều biến động. Nhưng những giây phút yên bình mong manh đó sớm bị phá vỡ khi họ đặt chân đến Thành Phố Cổng Nước Priestella xinh đẹp. Tại đây, Subaru trải qua những cái chết đau khổ được lặp đi lặp lại không hồi kết. Tình hình càng tệ hơn khi cậu phải đối mặt với Đại Tội Giám Mục Tham Lam Regulus Corneas và các thuộc hạ của hắn trong Giáo Phái Phù Thủy.</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 20, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Rie Takahashi","avatar":""},{"name":"Kobayashi Yuusuke","avatar":""},{"name":"Inori Minase","avatar":""},{"name":"Satomi Arai","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["Re:Zero -Começando uma Vida em Outro Mundo-","Re:ZERO -Começando a Vida em Outro Mundo-","从零开始的异世界生活","Re Zero Starting Life in Another World 2nd Season Part 2","Each One''s Promise","Re Zero Empezar de cero en un mundo diferente","RE:ZERO - Re:vivre dans un autre monde à partir de zéro","ReZERO - Starting Life in Another World","Re ZERO - Starting Life in Another World","Re Zero Starting Life in Another World","विषय: शून्य - एक दूसरी दुनिया में जीवन की शुरुआत","دوباره: هیچ، شروع زندگی در دنیایی دیگر","دوباره: صفر، شروع زندگی در دنیایی دیگر","Re zero Ricominciare in un altro mondo","Re:Zero kara Hajimeru Isekai Seikatsu","ReZero kara Hajimeru Isekai Seikatsu","Re:ゼロから始める異世界生活 2nd season","Re:ゼロから始める異世界生活 新編集版","Re:ゼロから始める異世界生活 3rd season 襲撃編","Re:ゼロから始める異世界生活 3rd season 反撃編","リゼロ","리제로","ReZero","Re Zero Empezar de cero en un mundo diferente Temporada 2","Re:Zero","Re Zero","Re: Жизнь в другом мире с нуля","Re: Жизнь в альтернативном мире с нуля","Re:Zero — жизнь с нуля в другом мире","Re:Zero. Жизнь с нуля в альтернативном мире","С нуля: Жизнь с нуля в альтернативном мире","Жизнь с нуля в альтернативном мире","Жизнь в альтернативном мире с нуля","Re:Zero.  Жизнь в aльтepнaтивнoм мире c нyля","Жизнь в другом мире с нуля","Ре Зеро Жизнь с нуля в альтернативном мире","Re：從零開始的異世界生活","Re:0","Re: Life in a Different World From Zero","Re:ゼロから始める異世界生活"]', 1784690324178);
