INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vasilisa-va-nhung-nguoi-bao-ve-thoi-gian', 'Vasilisa Và Những Người Bảo Vệ Thời Gian', 'Vasilisa and the Queen of Likes', 'https://phimimg.com/upload/vod/20250726-1/ecec3e32955059b9cf2f61fc464a811f.jpg', 'https://phimimg.com/upload/vod/20250726-1/76abee221bb8102f173dae40b3aa1257.jpg', '<p>Vì một số lỗi lầm, Người Giữ Thời Gian từ vũ trụ xa xôi đã đày một Pháp Sư xuống Trái Đất. Tại đây, ông gặp cháu gái Vasilisa, cũng sở hữu phép thuật kỳ diệu. Hai ông cháu làm quen với Dasha, một ngôi sao mạng xã hội sống nhờ sự chú ý và tình yêu của người hâm mộ: càng nhiều người theo dõi và lượt thích, cô càng trẻ đẹp. Mưu đồ của Dasha là chiếm đoạt sức mạnh phép thuật của Vasilisa để đạt được tuổi xuân vĩnh cửu.</p>', 'Full', 1, 'single', 'completed', 28, 2024, 'Vietsub', 'FHD', 'Nga', 0, '[{"name":"Masha Koshina","avatar":""},{"name":"Darya Moroz","avatar":""},{"name":"Sergey Garmash","avatar":""},{"name":"Yuriy Kuznetsov","avatar":""},{"name":"Agrippina Steklova","avatar":""},{"name":"Dmitriy Kulichkov","avatar":""},{"name":"Anton Rogachev","avatar":""},{"name":"Evgeny Zelensky","avatar":""},{"name":"Maks Klimka","avatar":""},{"name":"Leonid Yarmolnik","avatar":""},{"name":"Vitaliya Kornienko","avatar":""},{"name":"Anna Izotova","avatar":""},{"name":"Mariya Stolyarova","avatar":""},{"name":"Vladimir Kotov","avatar":""},{"name":"Askar Nigamedzyanov","avatar":""},{"name":"T","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm