INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-sat-2', 'Tàn Sát 2', 'Kill ''Em All 2', 'https://phimimg.com/upload/vod/20240924-1/3ed4794876d5e81d22c64ea35aad00a1.jpg', 'https://phimimg.com/upload/vod/20240924-1/be58812e40f61c00a376ab0b9332575f.jpg', '<p>Kill &#39;Em All 2 là một bộ phim hành động trực tiếp của Mỹ do Valeri Milev đạo diễn và James Agnew viết kịch bản. Đây là phần tiếp theo trực tiếp của Kill &#39;Em All (2017), với sự tham gia của Jean-Claude Van Damme, Jacqueline Fernandez, Peter Stormare và María Conchita Alonso. Phillip phải đối mặt với một tên khủng bố Nga-Pháp, người đã trả thù chính xác anh ta vì đã giết anh trai mình.</p>', 'Full', 1, 'single', 'completed', 17, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Ý', 0, '[{"name":"Jean-Claude Van Damme","avatar":""},{"name":"Peter Stormare","avatar":""},{"name":"Jacqueline Fernandez","avatar":""},{"name":"María Conchita Alonso","avatar":""},{"name":"Autumn Reeser","avatar":""},{"name":"Bianca Bree","avatar":""},{"name":"Talia Asseraf","avatar":""},{"name":"Nicolas Van Varenberg","avatar":""},{"name":"Andrei Lenart","avatar":""},{"name":"Dominic Salvatore","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["همه را بکش ۲","Mátalos a todos 2","שיהרגו את כולם 2","Tötet sie! 2","Kill Them All Again","Kill ''em All 2"]', 1784690324178);
