INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bac-si-ngoai-hanh-tinh-phan-3', 'Bác Sĩ Ngoài Hành Tinh (Phần 3)', 'Resident Alien (Season 3)', 'bác sĩ ngoài hành tinh (phần 3) resident alien (season 3) alan tudyk sara tomko corey reynolds alice wetterlund levi fiehler elizabeth bowen meredith garretson judah prehn местен извънземен 外星居民 תושב חייזרי レジデント・エイリアン ～宇宙からの訪問者～ местный пришелец пришелец-постоялец резидент прибулець постоялець з космосу resident alien', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sac-xuan-gui-nguoi-tinh', 'Sắc Xuân Gửi Người Tình', 'Will Love In Spring', 'https://phimimg.com/upload/vod/20250720-1/46c17a3379740d5ee6a33adf44bee0ba.jpg', 'https://phimimg.com/upload/vod/20250720-1/4cec8211f8d1903bf33d54e4b64de545.jpg', '<p>Bộ phim lấy bối cảnh cuộc sống đời thường bình dị chữa lành, mang đến câu chuyện nhân văn về những con người đầy ắp tình yêu thương. Bộ phim xoay quanh tình yêu đầy cam go thử thách và cứu rỗi lẫn nhau giữa những con người trưởng thành. Trần Mạch Đông thời trẻ tính tình ngang bướng, sau biến cố cuộc đời, anh chọn trở thành nhân viên trang điểm cho di hài. Trang Khiết vì tai nạn giao thông mà trở thành người tàn tật. Để theo đuổi phiên bản tốt hơn của chính mình, cô một mình lăn lộn nơi đất khách quê người rồi trở thành tầng lớp tinh anh thành đạt ở thành phố lớn. Một người là nhân viên trang điểm cho di hài tính tình ngang bướng nhưng tâm hồn cô đơn, một người là nhân viên bán hàng y tế tuy mang khiếm khuyết cơ thể nhưng rực rỡ can đảm. Sau nhiều lần mâu thuẫn, họ dần thấu hiểu và tôn trọng nhau, dùng tình yêu để chữa lành sự không hoàn hảo của nhau.</p>', 'Hoàn Tất (21/21)', 21, 'series', 'completed', 13, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Hiện","avatar":""},{"name":"Châu Vũ Đồng","avatar":""},{"name":"Ngô Tuấn Đình","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["吾乡有情人","Chun Se Ji Qing Ren","春色寄情人","Will Love in Spring"]', 1784690324178);
