INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dhevaprom-kwanruetai', 'Dhevaprom: Kwanruetai', 'Dhevaprom: Kwanruetai', 'https://phimimg.com/upload/vod/20250108-1/e9d842fc2c6b592bbdb6d02ffadcb757.jpg', 'https://phimimg.com/upload/vod/20250108-1/62bcc7a1fef1a20f7328e7773b49f2ac.jpg', '<p>Giữa cuộc chiến chống buôn bán ma túy, Kwanruetai, cô con gái tốt bụng của một gia đình quý tộc, gặp Thiếu tá Tiến sĩ Chatklao Juthathep, một bác sĩ quân y. Mặc dù tình yêu của họ ngày càng lớn, Kwanruetai vẫn bị giằng xé vì mối thù lâu đời của gia đình cô với Juthatheps, do nỗi đau trong quá khứ của mẹ cô. Khi Kwanruetai vật lộn với quá khứ và cảm xúc của mình, Chatklao vẫn quyết tâm giành được trái tim cô. Liệu tình yêu có vượt qua được xung đột của gia đình họ, hay họ phải chịu số phận xa cách?</p>', 'Hoàn Tất (14/14)', 14, 'series', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Kanawut Traipipattanapong","avatar":""},{"name":"Mike Theodor Platte","avatar":""},{"name":"Henry Myron","avatar":""},{"name":"Kongthap Yuttapichai","avatar":""},{"name":"Noppakao Dechaphatthanakun","avatar":""},{"name":"Duangta Toongkamanee","avatar":""},{"name":"Suppapong Udomkaewkanjana","avatar":""},{"name":"Siriam Pakdeedumrongrit","avatar":""},{"name":"Penpetch Benyakul","avatar":""},{"name":"Rinlanee Sripen","avatar":""},{"name":"Punpreedee Khumprom Rodsawat","avatar":""},{"name":"Dom","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Duang Jai Thewaphrom: Jaiphisut","ดวงใจเทวพรหม: ใจพิสุทธิ์","Duang Jai Thewaphrom: Dujapsorn","ดวงใจเทวพรหม: ดุจอัปสร","ดวงใจเทวพรห