INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('that-tieu', 'Thất Tiếu', 'Smile Code', 'https://phimimg.com/upload/vod/20241109-1/daadeb80379ff4a1992a7ca0f7761a1e.jpg', 'https://phimimg.com/upload/vod/20241109-1/4b500722d0e8c9eec623b85ec8818dea.jpg', '<p>Cố Dật (Thẩm Nguyệt), ban ngày làm việc cho tạp chí, ban đêm lại dẫn talkshow với mong muốn có thể khiến cho tất cả khán giả đều cười. Một ngày nọ, một khán giả nam tên Lương Đại Văn (Lâm Nhất) xuất hiện ở hàng ghế đầu, dù làm cách nào anh ta cũng không cười, khiến Cố Dật vô cùng bực bội. Tức mình, Cố Dật thầm hạ quyết tâm phải đánh bại &quot;bức tường băng&quot; này và kể từ đó, sợi dây nhân duyên đã liên kết họ với nhau.</p>', 'Hoàn Tất (34/34)', 34, 'series', 'completed', 14, 2024, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Lâm Nhất","avatar":""},{"name":"Thẩm Nguyệt","avatar":""},{"name":"Diệp Tiểu Vỹ","avatar":""},{"name":"Thiên Ái","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["失笑","Smile Code"]', 1784690324178);
