INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngay-tot-canh-dep-gap-lai-chang', 'Ngày Tốt Cảnh Đẹp Gặp Lại Chàng', 'In The Wake Of Shadow', 'https://phimimg.com/upload/vod/20250416-1/d81fe86443b91fdcbe4b589c5760b612.jpg', 'https://phimimg.com/upload/vod/20250416-1/e0cf85a94bc053cc7eb885edb2ea0cbd.jpg', '<p>Sau khi cha mất, Đỗ Tâm Nguyệt phải một thân một mình lo toan cho bản thân lẫn quán rượu của gia đình. Trong một lúc túng quẫn, cô thậm chí còn đồng ý minh hôn với con trai đã mất của nhà họ Tô là Tô Tinh Lạc. Trong đêm tân hôn, Tâm Nguyệt bất ngờ phát hiện Tinh Lạc thật ra vẫn còn sống. Để đền đáp việc Tâm Nguyệt giữ bí mật cho mình, Tinh Lạc đồng ý giúp cô điều tra về cái chết bí ẩn của cha cô.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 8, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Mã Tư Hàm","avatar":""},{"name":"Lý Hoan","avatar":""},{"name":"Dương Đào","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Liang Chen Hao Jing Zai Feng Jun","A Beautiful Reunion","赤狐大人别宠我","良辰好景再逢君"]', 1784690324178);
