INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-dau-19', 'Tình Đầu 19+', '19+ First Love', 'https://phimimg.com/upload/vod/20250714-1/e42c2c9516774aafadcc974677b22fa3.jpg', 'https://phimimg.com/upload/vod/20250714-1/90c3357b2ab820e1f3165bb3bbd6d8c5.jpg', '<p>Nhân vật chính là một nhà văn viết truyện lãng mạn cấp thấp, phát hiện ra người hùng trong cuốn tiểu thuyết mạng 19+ của chính mình bước ra đời thực. Cô tái hợp với tiền bối thời đại học, người đã truyền cảm hứng cho cuốn tiểu thuyết của cô, dẫn đến một câu chuyện tình yêu hài hước và mãnh liệt.</p>', 'Hoàn Tất (50/50)', 50, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324178);
