INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lieu-diep-trich-tinh-than', 'Liễu Diệp Trích Tinh Thần', 'My Wife''s Double Life', 'https://phimimg.com/upload/vod/20250712-1/c3ef85167db519535b0533d05db3b6c1.jpg', 'https://phimimg.com/upload/vod/20250712-1/bc891be8ffd22d0d7ea635c9cc44bca3.jpg', '<p>Bộ phim được chuyển thể từ tiểu thuyết &quot;Nữ Trộm&quot; của nhà văn nổi tiếng Tân Giang. Tên trộm bí ẩn tên là Lưu Dung được Quốc công Tô cứu vào 13 năm trước trong một trận lụt ở miền nam, để trả ơn cho lòng tốt của ân nhân, Lưu Dung đã quyết định giúp Quốc công tìm một cuốn sổ ghi về việc kiểm soát lũ lụt cách đây 13 năm tại nhà Hứa Thừa Tự. Cô với thân phận là con gái của Tô Quốc công Vì vậy, cô đã kết hôn với Hứa Mộ Thần con trai của Hứa Thừa Tự Sau khi kết hôn với Hứa Mộ Thần, Lưu Dung ngoài mặt là Tô phu nhân dịu dàng và ân cần, nhưng cô đã bí mật xâm nhập vào nhiều nơi khác nhau trong nhà họ Từ theo sự chỉ dẫn của Tô Quốc công để tìm sổ sách, và cũng nhiều lần chạm mặt với Hứa Mộ Thần. Khi Hứa Mộ Thần gây rắc rối cho &quot;Vợ trộm&quot;, thì khi trở về đều bị phu nhân của mình quở trách.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Đường Tiểu Thiên","avatar":""},{"name":"Trang Đạt Phi","avatar":""},{"name":"Lâm Phong Tùng","avatar":""},{"name":"Trình Tử","avatar":""},{"name":"Lý Bội Ân","avatar":""},{"name":"Lý Bác Dương","avatar":""},{"name":"Vương Tử Kiệt","avatar":""},{"name":"Hoàng Thánh Kiệt","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["LiuYeZhaiXingChen","Моя жена воровка","柳葉摘星辰","My Wife''s Double Life","My wife is a thief","柳叶摘星辰"]', 1784690324178);
