INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giai-thoai-phu-nhan-ok-chuyen-nang-ok', 'Giai Thoại Phu Nhân Ok (Chuyện Nàng Ok)', 'The Tale Of Lady Ok', 'https://phimimg.com/upload/vod/20241201-1/ffbbd02c12cd9e17cfbe6dd1353fb157.jpg', 'https://phimimg.com/upload/vod/20241201-1/fb3957b83c60971f8717dc2226b3e76b.jpg', '<p>Phim kể về câu chuyện sinh tồn đầy kịch tính của Gu Deok Yi, một nô lệ đào tẩu khỏi Hanyang. Bị đánh đập dã man đến thập tử nhất sinh, cô được một tiểu thư tốt bụng chăm sóc mà không hề có thành kiến về sự cách biệt thân phận. Tuy nhiên, sau vụ tấn công, cuộc đời Gu Deok Yi bước sang một trang mới không ngờ tới. Khác xa với kiếp nô lệ bị khinh rẻ, cô sống trong vai một quý bà hoàn hảo, Ok Tae Young. Bên cạnh cô còn có sự xuất hiện của Cheon Seung Hwi (Chu Young Woo đóng), một nghệ sĩ quyết đánh cược cả mạng sống để bảo vệ cô kể từ lần gặp mặt đầu tiên.</p>', 'Hoàn Tất (16/16)', 16, 'series', 'completed', 11, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lim Ji-yeon","avatar":""},{"name":"Choo Young-woo","avatar":""},{"name":"Yeon-woo","avatar":""},{"name":"Kim Jae-won","avatar":""},{"name":"Sung Dong-il","avatar":""},{"name":"Kim Mi-sook","avatar":""},{"name":"Lee Jae-won","avatar":""},{"name":"Kim Jae-hwa","avatar":""},{"name":"Oh Dae-hwan","avatar":""},{"name":"Kim Jong-tae","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["حکایت بانو اوک","افسانه بانو اوک","حكاية السيدة أوك","玉氏夫人傳","Okssibuinjeon","Mrs. Ok","Story of Lady Ok","The Tale of Mrs. Ok","Tale of Mrs. Ok","The Life of Mrs. Ock","옥씨부인전"]', 1784690324178);
