INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('chuyen-sinh-thanh-de-that-hoang-tu-toi-quyet-dinh-trau-doi-ma-thuat-phan-1', 'Chuyển Sinh Thành Đệ Thất Hoàng Tử, Tôi Quyết Định Trau Dồi Ma Thuật (Phần 1)', 'I Was Reincarnated As The 7th Prince So I Can Take My Time Perfecting My Magical Ability (Season 1)', 'chuyển sinh thành đệ thất hoàng tử, tôi quyết định trau dồi ma thuật (phần 1) i was reincarnated as the 7th prince so i can take my time perfecting my magical ability (season 1) makoto koichi fairouz ai lynn akira sekine rie takahashi shun horie yuya hirose akane kumada eriko matsui tomokazu sugita satomi akesaka shunichi toki takuma nagatsuka nobunaga shimazaki 随心所欲的魔法学习之路 转生七王子的魔法全解 转生为第七王子 tensei shitara dainana ōji datta no de, kimamani majutsu o kiwamemasu tensei shitara dainana ouji datta no de, kimamani majutsu o kiwamemasu dainana ouji 第七王子 tensei shitara dainana ouji datta node, kimama ni majutsu wo kiwamemasu tensei shitara dai nana ouji datta no de, kimamani majutsu o kiwamemasu dainanaoji tensei shitara dai nana ouji datta node, kimamani majutsu wo kiwamemasu tensei shitara dai nana ōji datta no de, kimamani majutsu o kiwamemasu tensei shitara dai nana ōji datta node, kimamani majutsu wo kiwamemasu tensei shitara dai nana ouji dattanode kimamani majutsu wo kiwamemasu てんせいしたらだいななおうじだったので、きままにまじゅつをきわめます tensei shitara dai nana ōji datta no de, kimama ni majutsu o kiwamemasu dainanaouji tensei shitara dainana ouji 환생했는데 제7왕자라 내맘대로 마술을 연마합니다 환생했는데 제7왕자라 내 맘대로 마술을 연마합니다 轉生為第七王子，隨心所欲的魔法學習之路 轉生為第七王子隨心所欲的魔法學習之路第二季 i was reincarnated as the 7th prince so i can take my time perfecting my magical ability i can take my time perfecting my magical ability i was reincarnated as the 7th prince chuyển sinh thành đệ thất hoàng tử, tôi quyết định trau dồi ma thuật chuyển sinh thành đệ thất hoàng tử 転生したら第七王子だったので、気ままに魔術を極めます', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-tuong-tu-phan-2', 'Trường Tương Tư (Phần 2)', 'Lost You Forever (Season 2)', 'https://phimimg.com/upload/vod/20250708-1/542c35a122ae86a245842eedb5680f47.jpg', 'https://phimimg.com/upload/vod/20250708-1/43ac660e5b770f8b391980bce904020d.jpg', '<p>Vào thời thượng cổ, người, thần, yêu chung sống cùng nhau, ba nước Thần Nông, Hiên Viên, Cao Tân tạo thế chân vạc. Cửu Dao, Vương cơ của Cao Tân lưu lạc Đại Hoang trải qua trăm năm khốn khổ, không những mất đi thân phận, cũng mất cả dung mạo, dừng chân ở trấn Thanh Thủy, trở thành Văn Tiểu Lục &quot;không nơi nào để đi, không có ai để nương tựa, không thể tự bảo vệ mình&quot;. Cô hành nghề y làm kế sinh nhai, sống tự do bất kham. Thương Huyền, anh họ của Tiểu Yêu cũng là vương tử Hiên Viên tuy ăn nhờ ở đậu, nhẫn nhịn chờ thời, những cũng muốn tìm kiếm Tiểu Yêu nên đã đi khắp Đại Hoang rồi đến trấn Thanh Thủy. Cuộc sống ở trấn Thanh Thủy bình dị ấm áp, Văn Tiểu Lục vô tình cứu Đồ Sơn Cảnh công tử Thanh Khâu đang hấp hối, sớm tối ở chung làm hai người dần nảy sinh tình cảm; Văn Tiểu Lục lại không đánh không quen với yêu chín đầu Tương Liễu, đồng cảm với nhau và trở thành tri kỷ. Văn Tiểu Lục và Thương Huyền gặp gỡ nhưng không nhận ra nhau, qua vài lần trắc trở, cuối cùng mới nhận ra Thương Huyền, khôi phục thân phận Vương cơ. Để thống nhất thiên hạ, Thương Huyền từ bỏ tình riêng, muốn giành ngôi vương, Tương Liễu giữ trọn chữ nghĩa chiến đấu đến chết, Tiểu Yêu giúp Thương Huyền hoàn thành xong đại nghiệp thì cùng Đồ Sơn Cảnh ẩn dật chốn giang hồ. Thương Huyền yêu mà không có được nên dồn toàn bộ tinh thần sức lực vào việc trị quốc, vì hắn biết, chỉ cần thiên hạ thái bình, Tiểu Yêu của hắn sẽ được hạnh phúc an khang.</p>', 'Hoàn Tất (23/23)', 23, 'series', 'completed', 6, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Tử","avatar":""},{"name":"Trương Vãn Ý","avatar":""},{"name":"Đặng Vi","avatar":""},{"name":"Đàn Kiện Thứ","avatar":""},{"name":"Đại Lộ Oa","avatar":""},{"name":"Vương Hoằng Nghị","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["An AllConsuming Love","Perdu pour toujours","ห้วงคำนึง ดวงใจนิรันดร์","Lost You Forever","Trường Tương Tư","长相思"]', 1784690324178);
