INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('truong-tuong-tu-phan-2', 'Trường Tương Tư (Phần 2)', 'Lost You Forever (Season 2)', 'trường tương tư (phần 2) lost you forever (season 2) dương tử trương vãn ý đặng vi đàn kiện thứ đại lộ oa vương hoằng nghị an allconsuming love perdu pour toujours ห้วงคำนึง ดวงใจนิรันดร์ lost you forever trường tương tư 长相思', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-tuong-tu-ban-dac-biet', 'Trường Tương Tư (Bản Đặc Biệt)', 'Lost You Forever (Special Edition)', 'https://phimimg.com/upload/vod/20250708-1/4aff41fc26a0e2a2e473cc6e25a18ee5.jpg', 'https://phimimg.com/upload/vod/20250708-1/d2de6d0a731d6684d5066c59e11da61a.jpg', '<p>Bộ phim Trường tương tư kể về nàng Tiểu Yêu (Dương Tử) sống nay đây mai đó nhưng sau này lại trở thành Vương cơ của Cao Tân. Cuộc đời của Tiểu Yêu gắn liền với nhiều trắc trở, đặc biệt là mối quan hệ của cô với Thương Huyền (Trương Vãn Ý), Đồ Sơn Cảnh (Đặng Vi) và Tương Liễu (Đàn Kiện Thứ). Sau khi hoàn thành đại nghiệp, Tiểu Yêu đã lựa chọn từ bỏ tất cả và quy ẩn giang hồ. Vào thời thượng cổ, người, thần, yêu chung sống cùng nhau, ba nước Thần Nông, Hiên Viên, Cao Tân tạo thế chân vạc. Cửu Dao, Vương cơ của Cao Tân lưu lạc Đại Hoang trải qua trăm năm khốn khổ, không những mất đi thân phận, cũng mất cả dung mạo, dừng chân ở trấn Thanh Thủy, trở thành Văn Tiểu Lục không nơi nào để đi, không có ai để nương tựa, không thể tự bảo vệ mình. Cô hành nghề y làm kế sinh nhai, sống tự do bất kham.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Tử","avatar":""},{"name":"Trương Vãn Ý","avatar":""},{"name":"Đặng Vi","avatar":""},{"name":"Đàn Kiện Thứ","avatar":""},{"name":"Đại Lộ Oa","avatar":""},{"name":"Vương Hoằng Nghị","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["An AllConsuming Love","Perdu pour toujours","ห้วงคำนึง ดวงใจนิรันดร์","Lost You Forever","Trường Tương Tư","长相思"]', 1784690324178);
