INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tu-hai-trong-minh', 'Tứ Hải Trọng Minh', 'Love''s Rebellion', 'https://phimimg.com/upload/vod/20250708-1/862f01c2305c1036f6d6a91f9bdc10ec.jpg', 'https://phimimg.com/upload/vod/20250708-1/3beceeec32b8f57abc6814ee0d3d1f19.jpg', '<p>Tứ Hải Trọng Minh kể về mối duyên giữa Nam Nhan, một cô gái bình thường bất đắc dĩ rơi vào con đường tu tiên và Kê Dương, một vị đế quân đang che giấu thân phận của mình. Để tìm ra phương thuốc chữa bệnh cho mẹ, Nam Nhan quyết tâm phải đi tìm bằng được những vị thuốc quý hiếm nhất. Trong hành trình đó, nàng vô tình gặp gỡ Kê Dương, cả hai bất đắc dĩ nên duyên vợ chồng và cùng sát cánh bên nhau trong cuộc chiến tranh đoạt của Tiên giới.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 9, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Cảnh Điềm","avatar":""},{"name":"Trương Lăng Hách","avatar":""},{"name":"Trần Quang Hồng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["四海颜歌","เทพบุตรจุติมารัก","Reborn For Love","Love''s Rebellion","四海重明"]', 1784690324178);
