INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('say-me-nhung-co-gai-phep-thuat-mahou-shoujo-ni-akogarete', 'Say Mê Những Cô Gái Phép Thuật (Mahou Shoujo ni Akogarete)', 'Gushing Over Magical Girls', 'https://phimimg.com/upload/vod/20250708-1/446adf9ecb7affd1512e1d863739ee78.jpg', 'https://phimimg.com/upload/vod/20250708-1/c043b74605025565b0d8398b801000bb.jpg', '<p>Hiragi Utena là một fan cuồng nhiệt của những thiếu nữ phép thuật bảo vệ thành phố và luôn khao khát được gia nhập hàng ngũ của họ. Nhưng khi cô biến hình, cô phát hiện ra mình là một phản diện, một kẻ tàn bạo thích hành hạ các thiếu nữ phép thuật!</p>', 'Hoàn Tất (13/13)', 13, 'hoathinh', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Fuka Izumi","avatar":""},{"name":"Misato Fukuen","avatar":""},{"name":"Aoi Koga","avatar":""},{"name":"Shiori Sugiura","avatar":""},{"name":"Kaori Maeda","avatar":""},{"name":"Mayuko Kazama","avatar":""},{"name":"Misaki Ikeda","avatar":""},{"name":"Kana Asumi","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["梦想成为魔法少女","憧憬成为魔法少女","想要成为魔法少女","Gushing over Magical Girls Mahou Shoujo ni Akogarete","Mahou Shoujo ni Akogarete","I Admire Magical Girls, and...","Mahō Shōjo ni Akogarete","まほあこ","MahoAko","Восхищаясь девочками-волшебницами","憧憬成為魔法少女","Looking Up to Magical Girls","魔法少女にあこがれて"]', 1784690324178);
