INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('do-de-cua-ta-deu-la-dai-lao', 'Đồ Đệ Của Ta Đều Là Đại Lão', 'Apprentices Are All Bosses', 'https://phimimg.com/upload/vod/20250705-1/b0e7f60c05b77828f6b5abc2d71c9583.jpg', 'https://phimimg.com/upload/vod/20241101-1/7ccee1c6d7e9b20216492dd6e64093b2.jpg', '<p>Chuyển thể từ tiểu thuyết cùng tên, câu chuyện kể về vị chúa tể tối cao xa cách của vô vàn cõi giới. Ông ta tuyển chọn những cô gái trẻ, mỗi người đều có tiềm năng trở thành những vị thần tương lai, và bắt đầu một nhiệm vụ gian nan để định hình lại vận mệnh của các cõi giới. Đối mặt với những thách thức và trở ngại to lớn, liệu những cô gái trẻ này có chiến thắng trong thử thách của mình và tạo nên một thế giới mới từ đống tro tàn của thế giới cũ?</p>', 'Hoàn Tất (40/40)', 40, 'hoathinh', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Tu Di Ge Ge Shi Da Lao","Tudi Ge Ge Shi Da Lao","我的女徒弟们都是未来诸天大佬","My Female Disciples Are All Future Big Shots of the Heavens","Every Disciple Is a Big Shots","My Female Disciples Are Future Deities","My Female Apprentices Are All Future Big Shots","My Female Disciples Are Big Cheeses","My Female Disciples Are Future Big Shots","OverGoddess","Over-Goddess","Apprentices Are All Bosses","My Apprentices Are All Bosses","徒弟个个是大佬"]', 1784690324178);
