INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-xe-chuyen-doi', 'Chuyến Xe Chuyện Đời', 'Daddio', 'https://phimimg.com/upload/vod/20250704-1/66825a872e09a9825df2236be86c1ca2.jpg', 'https://phimimg.com/upload/vod/20250704-1/dcf3b77171ca2cd10d0c7338b5ca5ebd.jpg', '<p>Sau khi hạ cánh tại sân bay quốc tế John F. Kennedy, một phụ nữ trẻ bắt taxi trở về căn hộ của mình ở Manhattan. Trong suốt chuyến đi, cô cùng tài xế taxi - Clark - đã có những cuộc trò chuyện trung thực và đầy bất ngờ về nhiều chủ đề, bao gồm các mối quan hệ trong quá khứ cũng như hiện tại của họ. Thậm chí, cả hai còn có nhiều chia sẻ cởi mở về tình dục và quyền lực, sự mất mát và tổn thương.</p>', 'Full', 1, 'single', 'completed', 17, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dakota Johnson","avatar":""},{"name":"Sean Penn","avatar":""},{"name":"Marcos A. Gonzalez","avatar":""},{"name":"Zora Lloyd","avatar":""},{"name":"Shannon Gannon","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["搭车奇缘","Una notte a New York","Випадкова розмова","Daddio"]', 1784690324178);
