INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-goi-khan-cap', 'Cuộc Gọi Khẩn Cấp', 'Asphalt City', 'https://phimimg.com/upload/vod/20250704-1/06324eb5f4d84069449e1c4e351c2aa9.jpg', 'https://phimimg.com/upload/vod/20250704-1/8dbbbb95ebaa4e8a8e6f45da90c8f09c.jpg', '<p>Dựa trên cuốn tiểu thuyết Black Flies của Shannon Burke. Câu chuyện xoay quanh nhân vật Ollie Cross, một nhân viên y tế mới vào nghề. Cùng với Gene Rutkovsky, một nhân viên y tế dày dạn kinh nghiệm, cả hai phải đối mặt với tình huống cấp cứu khẩn cấp nhưng cũng đầy thử thách ở New York.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Anh', 0, '[{"name":"Sean Penn","avatar":""},{"name":"Tye Sheridan","avatar":""},{"name":"Gbenga Akinnagbe","avatar":""},{"name":"Raquel Nave","avatar":""},{"name":"Kali Reis","avatar":""},{"name":"Michael Pitt","avatar":""},{"name":"Katherine Waterston","avatar":""},{"name":"Mike Tyson","avatar":""},{"name":"Onie Maceo Watlington","avatar":""},{"name":"Alisa Mironova","avatar":""},{"name":"Robert Oppel","avatar":""},{"name":"Donna Glaesener","avatar":""},{"name":"Decater James","avatar":""},{"name":"Charrisse Matthews","avatar":""},{"name":"Kareemeh Odeh","avatar":""},{"name":"Jagan Badvel","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Black Flies","黑蝇","亡命救护","กู้ชีพ วิกฤตเมืองเถื่อน","Kara Sinekler","Asphalt City"]', 1784690324178);
