INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ai-cung-yeu-men-touda', 'Ai Cũng Yêu Mến Touda', 'Everybody Loves Touda', 'https://phimimg.com/upload/vod/20250703-1/ae0a044fb63b64fb83533f68ca028d0f.jpg', 'https://phimimg.com/upload/vod/20250703-1/203d296bc593240ad0d6baa2d543611f.jpg', '<p>Touda – một Sheikha (nữ ca sĩ truyền thống của Morocco) đầy đam mê và bản lĩnh – ngày ngày cất giọng hát trong những quán bar chật hẹp nơi thị trấn nhỏ, dưới ánh mắt xét nét của những người đàn ông xung quanh. Nhưng sau lớp phấn son và nỗi cô đơn là một người mẹ mạnh mẽ, đang đấu tranh cho hy vọng và tình thương. Khát khao được công nhận và mưu cầu một cuộc sống xứng đáng cho con trai câm điếc, Touda quyết định rời bỏ tất cả – quá khứ, định kiến, và thị trấn nhỏ chật chội – để hướng đến Casablanca, thành phố rực rỡ ánh đèn, nơi cô tin rằng tiếng hát của mình sẽ được lắng nghe và trân trọng.</p>', 'Full', 1, 'single', 'completed', 30, 2024, 'Vietsub', 'FHD', 'Ả Rập Xê Út', 0, '[{"name":"Nisrin Erradi","avatar":""},{"name":"Jalila Talemsi","avatar":""},{"name":"Joud Chamihy","avatar":""},{"name":"El Moustafa Boutankite","avatar":""},{"name":"Lahcen Razzougui","avatar":""},{"name":"Khalil Oubaaqa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["غناء تودة","Todo el mundo ama a Touda","في حب تودا"]', 1784690324178);
