INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-kich-giang-sinh-dinh-nhat', 'Vở Kịch Giáng Sinh Đỉnh Nhất', 'The Best Christmas Pageant Ever', 'https://phimimg.com/upload/vod/20250701-1/8430668d02f19630cc4281c9f746c80f.jpg', 'https://phimimg.com/upload/vod/20250701-1/0ddbbcfd7321db6a61d890e338cea099.jpg', '<p>Sáu đứa con nhà Herdman: Imogene, Ralph, Claude, Leroy, Ollie và Gladys &quot;nổi tiếng&quot; khắp nơi vì những trò nghịch ngợm và hành vi ngông cuồng như hút xì gà, chửi thề,... thậm chí là đốt phá. Nhưng điều bất ngờ nhất là chúng tuyên bố sẽ tham gia buổi biểu diễn Giáng sinh hàng năm của cộng đồng. Trong khi cư dân ở đây lo sợ về một &quot;thảm họa&quot; không tránh khỏi thì điều kỳ diệu xảy ra. Bằng sự nỗ lực và diễn xuất đầy sáng tạo, những đứa trẻ đã tạo nên vở kịch Giáng sinh tuyệt vời nhất mà cả thị trấn từng được thưởng thức.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Judy Greer","avatar":""},{"name":"Pete Holmes","avatar":""},{"name":"Molly Belle Wright","avatar":""},{"name":"Lauren Graham","avatar":""},{"name":"Sebastian Billingsley-Rodriguez","avatar":""},{"name":"Kynlee Heiman","avatar":""},{"name":"Matthew Lamb","avatar":""},{"name":"Beatrice Schneider","avatar":""},{"name":"Ewan Wood","avatar":""},{"name":"Essek Moore","avatar":""},{"name":"Mason D Nelligan","avatar":""},{"name":"Lorelei Olivia Mote","avatar":""},{"name":"Danielle Hoetmer","avatar":""},{"name":"Kirk B.R. Woller","avatar":""},{"name":"Elizabeth Tabi","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["La peor obra de navidad","Le meilleur concours de Noël de tous les temps","The Best Christmas Pageant Ever"]', 1784690324178);
