INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-thay-tv-bung-sang', 'Tôi Thấy TV Bừng Sáng', 'I Saw The TV Glow', 'https://phimimg.com/upload/vod/20250701-1/0313ea0ac9aeb7012c7e818470096e7c.jpg', 'https://phimimg.com/upload/vod/20250701-1/f1a96929ad78236aa5168fd9ae51aae4.jpg', '<p>Phim&nbsp;xoay quanh Owen, một thiếu niên đang cố gắng thích nghi với cuộc sống mới ở ngoại ô. Khi tình cờ phát hiện một chương trình truyền hình bí ẩn, cậu bé dần bị cuốn vào một thế giới khác biệt, nơi ranh giới giữa thực tại và ảo giác trở nên mờ nhạt. Ánh sáng mờ ảo của màn hình tivi chiếu rọi những hình ảnh kỳ lạ, khơi gợi trong Owen những câu hỏi về bản thân và cuộc sống xung quanh. Liệu những gì cậu thấy trên tivi chỉ là sản phẩm của trí tưởng tượng hay là một thực tại song song đang chờ đợi để được khám phá?</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Justice Smith","avatar":""},{"name":"Jack Haven","avatar":""},{"name":"Ian Foreman","avatar":""},{"name":"Helena Howard","avatar":""},{"name":"Lindsey Jordan","avatar":""},{"name":"Danielle Deadwyler","avatar":""},{"name":"Fred Durst","avatar":""},{"name":"Conner O''Malley","avatar":""},{"name":"Emma Portner","avatar":""},{"name":"Madaline Riley","avatar":""},{"name":"Amber Benson","avatar":""},{"name":"Albert Birney","avatar":""},{"name":"Michael C. Maronna","avatar":""},{"name":"Danny Tamberelli","avatar":""},{"name":"Timothy Allan","avatar":""},{"name":"Tyler Dean Flores","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Я видел свечение телевизора","我看到电视发光","J''ai vu la télé briller","아이 쏘우 더 티비 글로우","Я видел свет телевизора","El brillo de la televisión","ראיתי את זוהר הטלוויזיה","ראיתי את הטלוויזיה זוהרת","Osvícení televizí","テレビの中に入りたい","I Saw the TV Glow"]', 1784690324178);
