INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('toi-thay-tv-bung-sang', 'Tôi Thấy TV Bừng Sáng', 'I Saw The TV Glow', 'tôi thấy tv bừng sáng i saw the tv glow justice smith jack haven ian foreman helena howard lindsey jordan danielle deadwyler fred durst conner o''malley emma portner madaline riley amber benson albert birney michael c. maronna danny tamberelli timothy allan tyler dean flores я видел свечение телевизора 我看到电视发光 j''ai vu la télé briller 아이 쏘우 더 티비 글로우 я видел свет телевизора el brillo de la televisión ראיתי את זוהר הטלוויזיה ראיתי את הטלוויזיה זוהרת osvícení televizí テレビの中に入りたい i saw the tv glow', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguoi-hung-tham-lang', 'Người Hùng Thầm Lặng', 'Unsung Hero', 'https://phimimg.com/upload/vod/20250701-1/71e1725b0152f58174c3fac8383f29f9.jpg', 'https://phimimg.com/upload/vod/20250701-1/460c5acbe94c434cd873096187c356f3.jpg', '<p>Dựa trên câu chuyện có thật, phim theo chân David Smallbone khi anh cùng cả nhà chuyển đến Hoa Kỳ, tìm kiếm một tương lai mới sau khi công ty của họ sụp đổ. Chỉ với sáu đứa con, những chiếc vali và tình yêu âm nhạc, David cùng người vợ đang mang thai Helen đã lên đường xây dựng lại cuộc sống. Đôi vợ chồng cũng bắt đầu nhận ra tài năng âm nhạc ở những đứa con mà sau này chúng sẽ trở thành những nghệ sĩ nổi tiếng với năm lần giành giải Grammy: bộ đôi nhạc pop Cơ Đốc giáo có nghệ danh For King &amp; Country (anh em Joel và Luke) cùng chị gái của họ là Rebecca St. James.</p>', 'Full', 1, 'single', 'completed', 16, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Joel Smallbone","avatar":""},{"name":"Daisy Betts","avatar":""},{"name":"Kirrilee Berger","avatar":""},{"name":"Jonathan Jackson","avatar":""},{"name":"Candace Cameron Bure","avatar":""},{"name":"Terry O''Quinn","avatar":""},{"name":"Lucas Black","avatar":""},{"name":"Paul Luke Bonenfant","avatar":""},{"name":"JJ Pantano","avatar":""},{"name":"Tenz McCall","avatar":""},{"name":"Angus K. Caldwell","avatar":""},{"name":"Hillary Scott","avatar":""},{"name":"Lance E. Nichols","avatar":""},{"name":"Roslyn Gentle","avatar":""},{"name":"Don Most","avatar":""},{"name":"Rachel Hendri","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e