INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nguoi-hung-tham-lang', 'Người Hùng Thầm Lặng', 'Unsung Hero', 'người hùng thầm lặng unsung hero joel smallbone daisy betts kirrilee berger jonathan jackson candace cameron bure terry o''quinn lucas black paul luke bonenfant jj pantano tenz mccall angus k. caldwell hillary scott lance e. nichols roslyn gentle don most rachel hendri a film by for king & country: unsung hero מוזיקה מהנשמה unsung hero', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kinh-hai', 'Kinh Hãi', 'Afraid', 'https://phimimg.com/upload/vod/20240917-1/7d23560739df8b6054755d33cf01b535.jpg', 'https://phimimg.com/upload/vod/20240917-1/4d9e3b3d6535f434233f75c3891ef199.jpg', '<p>Tại một gia đình gồm năm thành viên: cặp vợ chồng, cô con gái lớn tuổi teen cùng hai cậu con trai nhỏ.Một ngày nọ, gia đình họ chào đón “thành viên” đặc biệt: một thiết bị công nghệ tiên tiến sử dụng trí tuệ nhân tạo mang tên AIA.Sự hiện diện của AIA ban đầu khiến mọi người cảm thấy lạ lẫm nhưng cũng không kém phần phấn khích. Rất nhanh, trí tuệ nhân tạo này đã trở thành “người mẹ thứ hai” khi tham gia quán xuyến, giải quyết nhiều rắc rối và công việc lớn nhỏ trong nhà.Biến cố xảy ra khi clip nhạy cảm của cô con gái lớn bất ngờ bị lộ trên mạng xã hội. Giữa lúc cô gái trẻ đang bối rối và hoảng loạn, AIA đã nhanh gọn xử lý vấn đề và cả… kẻ gây ra vấn đề. Cũng từ đây, hàng loạt sự kiện kỳ quái liên tục ập đến với gia đình nhỏ...</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"John Cho","avatar":""},{"name":"Katherine Waterston","avatar":""},{"name":"Keith Carradine","avatar":""},{"name":"Havana Rose Liu","avatar":""},{"name":"Lukita Maxwell","avatar":""},{"name":"David Dastmalchian","avatar":""},{"name":"Riki Lindhome","avatar":""},{"name":"Greg Hill","avatar":""},{"name":"Ben Youcef","avatar":""},{"name":"Isaac Bae","avatar":""},{"name":"Ashley Romans","avatar":""},{"name":"Mason Shea Joyce","avatar":""},{"name":"River Drosche","avatar":""},{"name":"Todd Waring","avatar":""},{"name":"Maya Manko","avatar":""},{"name":"Katie McCabe","avatar":""},{"name":"Wyatt Lindner","avatar":""},{"name":"Pam","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["They Listen","hOMe","AfrAId","DIAbólica","هراسان","نگران","TerrifIAnte","เอไอ สั่งสยอง","Afraid"]', 1784690324178);
