INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cay-nong-hoi-hoi-nhiet-lat-con-thang', 'Cay Nóng Hôi Hổi (Nhiệt Lạt Cổn Thang)', 'Yolo', 'https://phimimg.com/upload/vod/20250701-1/6277c9a1e77a5b14af949980b7558d8d.jpg', 'https://phimimg.com/upload/vod/20250701-1/1d1ffed3edae586ebd534f8bf39883d5.jpg', '<p>Phim kể về câu chuyện của Lạc Oánh - một người phụ nữ thừa cân, thất nghiệp, sống không mục đích và đang ăn bám bố mẹ. Sau lần cãi vã căng thẳng với em gái, cô quyết định bỏ nhà ra đi, bắt đầu cuộc sống tự lập. Trong lúc đang vật lộn với mọi thứ, vào thời khắc khó khăn nhất, cô gặp được một huấn luyện viên đấm bốc. Kể từ đó, Lạc Oánh dần dần tìm thấy niềm đam mê với bộ môn &quot;boxing&quot;, vượt qua những thử thách, vực dậy bản thân và tìm kiếm vinh quang.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Giả Linh","avatar":""},{"name":"Lôi Gia Âm","avatar":""},{"name":"Sa Dật","avatar":""},{"name":"Kiều Sam","avatar":""},{"name":"Dương Tử","avatar":""},{"name":"Trương Tiểu Phỉ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["中国版百元之恋","Re La Gun Tang","Yolo","You Only Live Once","เผ็ด แซ่บ เดือด","热辣滚烫"]', 1784690324178);
