INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ai-do-nhu-em', 'Ai Đó Như Em', 'Someone Like You', 'https://phimimg.com/upload/vod/20250701-1/966afc86918e62ec4928a8d0db6ade09.jpg', 'https://phimimg.com/upload/vod/20250701-1/243c89991d47c70d15ef341cb2030ed4.jpg', '<p>Kiến trúc sư trẻ Dawson Gage vẫn chưa hết bàng hoàng vì đột ngột mất đi người bạn thân nhất, đồng thời là người anh thầm yêu - London Quinn trong một vụ tai nạn ô tô. Trong nỗi đau khổ tột cùng, Dawson phát hiện ra một bí mật: London được thụ thai bằng phương pháp thụ tinh trong ống nghiệm và có một người em sinh đôi đã bị cho làm con nuôi từ nhỏ. Anh bắt đầu hành trình tìm kiếm em gái của London dù đây là việc hầu như bất khả thi. Dawson tìm ra Andi Allen và dù vẫn chưa có ý định yêu ai, anh lại rơi vào lưới tình một cách bất ngờ.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Sarah Fisher","avatar":""},{"name":"Jake Allyn","avatar":""},{"name":"Lynn Collins","avatar":""},{"name":"Robyn Lively","avatar":""},{"name":"Bart Johnson","avatar":""},{"name":"Scott Reeves","avatar":""},{"name":"Brandon Hirsch","avatar":""},{"name":"Austin Robert Russell","avatar":""},{"name":"Mary Marguerite Hall","avatar":""},{"name":"Lindsay Ross Davenport","avatar":""},{"name":"Yvonne Landry","avatar":""},{"name":"Jenique Bennett","avatar":""},{"name":"Sharon Parra","avatar":""},{"name":"Robert Way","avatar":""},{"name":"Lisa Buttrum","avatar":""},{"name":"Robert G. Harris","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Outra Chance para o Amor","یکی مثل تو","Karen Kingsbury''s Someone Like You","Someone Like You"]', 1784690324178);
