INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ai-do-nhu-em', 'Ai Đó Như Em', 'Someone Like You', 'ai đó như em someone like you sarah fisher jake allyn lynn collins robyn lively bart johnson scott reeves brandon hirsch austin robert russell mary marguerite hall lindsay ross davenport yvonne landry jenique bennett sharon parra robert way lisa buttrum robert g. harris outra chance para o amor یکی مثل تو karen kingsbury''s someone like you someone like you', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-ay-doc-nhat-huu-nhi', 'Cô Ấy Độc Nhất Hữu Nhị', 'My Special Girl', 'https://phimimg.com/upload/vod/20250629-1/770aa95c4c938f365cf63289f997c42d.jpg', 'https://phimimg.com/upload/vod/20250629-1/40e2dc01951cfbbf223eaf0a05df9eb2.jpg', '<p>Phim mang đến câu chuyện về sự trưởng thành của kỹ sư AI Cố Cửu Lễ và cô gái thực tập giáo dục mầm non, với hai thân phận khác nhau. Cố Cửu Lễ (do Trương Vân Long thủ vai) là một kỹ sư AI, sáng lập công ty Cửu Thiên Khoa Học, đam mê nghiên cứu và phát triển robot chăm sóc. Trong khi đó, Hác Tịnh (do Tống Y Nhân thủ vai) là một sinh viên vừa tốt nghiệp chuyên ngành giáo dục mầm non, đam mê ca hát nhưng không được mẹ ủng hộ. Mẹ cô chỉ hy vọng Hác Tịnh có thể tìm được một công việc ổn định và thành công, do đó cô chỉ có thể trở thành một streamer hát trực tiếp vào ban đêm và làm thực tập sinh tại công ty Cửu Lễ vào ban ngày. Với hai thân phận khác nhau, Hạo Tinh với những tính cách khác nhau, Cửu Lễ không nhận ra rằng hai người này thực chất là cùng một người. Điều này dẫn đến một loạt tình huống hài hước.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 9, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Vân Long","avatar":""},{"name":"Tống Y Nhân","avatar":""},{"name":"Chu Ngạn Thần","avatar":""},{"name":"Mao Lâm Lâm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["独一有二的她"]', 1784690324178);
