INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('a-mach-tong-quan', 'A Mạch Tòng Quân', 'Fighting For Love', 'https://phimimg.com/upload/vod/20250626-1/058d207e1fac2c5e2dd0ebe674d7d5c1.jpg', 'https://phimimg.com/upload/vod/20250626-1/e1e5b9e3ec669d7163dc77bf57230048.jpg', '<p>Cả gia đình bị sát hại từ lúc cô còn nhỏ, A Mạch lớn lên với quyết tâm trả thù. Trong quá trình cải nam trang để lang bạt giang hồ tìm kẻ thù, A Mạch vô tình cứu được Thương Dịch Chi, một công tử hoàng tộc bề ngoài có vẻ là tay ăn chơi trác táng. Khi chiến tranh bùng nổ, A Mạch tòng quân cùng Thương Dịch Chi và bắt đầu phát hiện ra bí mật về thân thế của anh.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 8, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Thiên Ái","avatar":""},{"name":"Trương Hạo Duy","avatar":""},{"name":"Vương Thụy Xương","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Peleando por Amor","阿麦从军"]', 1784690324178);
