INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lang-chien', 'Lang Chiến', 'Fangs & Fury', 'https://phimimg.com/upload/vod/20241112-1/09c7c40c0b0f95f2695253942138ab2d.jpg', 'https://phimimg.com/upload/vod/20241112-1/80b6820b76be7503e9890b1f7582d93c.jpg', '<p>Chàng trai trẻ mất trí nhớ Viên Bố được chị em Ngô Đình và Tiểu Thạch cứu sống tại cửa hàng hoa của họ. Bệnh ở não bẩm sinh của Ngô Đình ngày càng nghiêm trọng, và chi phí y tế đắt đỏ khiến cả ba người cảm thấy ngột ngạt. Để kiếm tiền chữa bệnh cho Ngô Đình, Viên Bố không ngại mạo hiểm tính mạng tham gia các trận đấu quyền anh ngầm. Tuy nhiên, vì trở nên nổi tiếng trong sàn đấu, anh đã bị Phó Nghĩa, nhà sinh vật học độc ác từng coi anh là &quot;vật thí nghiệm&quot; phát hiện. Hóa ra, Viên Bố là một chiến binh siêu đẳng đã được cải tạo bằng công nghệ gen.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Haoran","avatar":""},{"name":"Amy Su","avatar":""},{"name":"Guo Zhen","avatar":""},{"name":"Mou Fengbin","avatar":""},{"name":"Zhang Xinyuan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Lang Zhan","Wolf Battle","랑전","狼战"]', 1784690324178);
