INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hao-ca-dai-nao-huyen-nha', 'Hạo Ca Đại Náo Huyện Nha', 'The Petty Official', 'https://phimimg.com/upload/vod/20250624-1/ea18c0748a7a2e2a922746dc0b075895.jpg', 'https://phimimg.com/upload/vod/20250624-1/158c0549abc976636d1956173967bd9a.jpg', '<p>Bộ phim kể về Trương Hạo – một cô nhi được nuôi lớn bởi tham quan, vì mưu sinh mà buộc phải học đủ mọi mánh khóe giang hồ. Trong một lần tình cờ, anh mạo danh trở thành huyện trưởng của huyện An Thành. Trên hành trình tìm ra bí ẩn thân thế của mình, Trương Hạo dần khơi dậy lương tri và chính nghĩa còn tiềm ẩn trong lòng. Anh đã sử dụng đủ chiêu trò “vô lại” đầy bất ngờ để đối đầu với cường hào ác bá Cao Đăng Đường – kẻ đang che trời bằng một tay, tạo nên một cuộc đấu trí sinh tử đầy khúc khuỷu và cam go.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Hạo","avatar":""},{"name":"Đồng Phi","avatar":""},{"name":"Triệu Tiểu Duệ","avatar":""},{"name":"Ngô Khải Hoa","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Petty Official","浩哥闹县衙"]', 1784690324178);
