INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-phung-da-canh-nhan', 'Đại Phụng Đả Canh Nhân', 'Guardians Of The Dafeng', 'https://phimimg.com/upload/vod/20241228-1/5bca87d4461855cdfce570faadfadb94.jpg', 'https://phimimg.com/upload/vod/20241228-1/4e4de1aba500132bbaec6f07035fd2c5.jpg', '<p>Dương Lăng có khao khát trở thành cảnh sát, nhưng một tai nạn ập đến khiến anh lạc vào một thế giới khác. Khi tỉnh lại, anh thấy mình đang bị giam trong ngục chờ bị áp giải ra biên cương. Để thay đổi số mệnh bi đát, anh bắt buộc phải tự rửa oan cho mình và gia nhập tổ chức Đả Canh Nhân.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 8, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Hạc Đệ","avatar":""},{"name":"Điền Hi Vi","avatar":""},{"name":"Lưu Dịch Quân","avatar":""},{"name":"Yến Tử Đông","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["大奉打更人-TVB版","Guardians of the Dafeng","大奉打更人"]', 1784690324178);
