INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('green-bones', 'Green Bones', 'Green Bones', 'https://phimimg.com/upload/vod/20250620-1/182b5c3b7971e9beeba5028d9b4d07dc.jpg', 'https://phimimg.com/upload/vod/20250620-1/a7f8880a5a761a4fdec1c36d7cb18e65.jpg', '<p>Một quản giáo, đang chìm trong đau buồn, hoài nghi quan điểm về sự chuộc lỗi và những chuẩn mực đạo đức tưởng chừng rạch ròi của bản thân khi lật mở quá khứ của một tù nhân rụt rè.</p>', 'Full', 1, 'single', 'completed', 15, 2024, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Dennis Trillo","avatar":""},{"name":"Ruru Madrid","avatar":""},{"name":"Iza Calzado","avatar":""},{"name":"Alessandra de Rossi","avatar":""},{"name":"Michael De Mesa","avatar":""},{"name":"Sofia Pablo","avatar":""},{"name":"Kylie Padilla","avatar":""},{"name":"Wendell Ramos","avatar":""},{"name":"Sienna Stevens","avatar":""},{"name":"Ronnie Lazaro","avatar":""},{"name":"Mikoy Morales","avatar":""},{"name":"Royce Cabrera","avatar":""},{"name":"Ruby Ruiz","avatar":""},{"name":"Gerhard Acao","avatar":""},{"name":"Raul Morit","avatar":""},{"name":"Victor Neri","avatar":""},{"name":"Pauline Mendoza","avatar":""},{"name":"Enzo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Green Bones"]', 1784690324178);
