INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-trinh-am-thuc-cua-phil-phan-7', 'Hành Trình Ẩm Thực Của Phil (Phần 7)', 'Somebody Feed Phil (Season 7)', 'https://phimimg.com/upload/vod/20241021-1/0df5b67e99bec68b849bbd7f4caba43e.jpg', 'https://phimimg.com/upload/vod/20250620-1/1a2d44935a46bad70d81a85469fbe428.jpg', '<p>Hương vị mới mẻ và những người bạn mới đang chờ đón khi tín đồ ẩm thực toàn cầu Phil Rosenthal mở mang góc nhìn ẩm thực đến Amsterdam, Boston, xứ Basque và nhiều nơi khác.</p>', 'Hoàn Tất (8/8)', 8, 'tvshows', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Philip Rosenthal","avatar":""}]', '[{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Somebody Feed Phil"]', 1784690324178);
