INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('can-phong-ke-ben', 'Căn Phòng Kế Bên', 'The Room Next Door', 'https://phimimg.com/upload/vod/20250515-1/898d5e9fcebce75517c7d511c2b22d52.jpg', 'https://phimimg.com/upload/vod/20250515-1/2e8d0ef0ee7032f162fe0f11f397c5df.jpg', '<p>Ingrid và Martha từng là đôi bạn thân thiết thời trẻ, khi cả hai cùng làm việc tại một tạp chí. Về sau, Ingrid trở thành một tiểu thuyết gia chuyên viết autofiction (tự truyện hư cấu), còn Martha trở thành một phóng viên chiến trường. Cuộc sống đã đưa đẩy họ xa cách. Rồi một ngày, họ tình cờ gặp lại nhau trong một tình huống đầy bất ngờ, vừa căng thẳng lại vừa cảm động.</p>', 'Full', 1, 'single', 'completed', 13, 2024, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Julianne Moore","avatar":""},{"name":"Tilda Swinton","avatar":""},{"name":"John Turturro","avatar":""},{"name":"Alessandro Nivola","avatar":""},{"name":"Juan Diego Botto","avatar":""},{"name":"Raúl Arévalo","avatar":""},{"name":"Victoria Luengo","avatar":""},{"name":"Alex Høgh Andersen","avatar":""},{"name":"Esther-Rose McGregor","avatar":""},{"name":"Alvise Rigo","avatar":""},{"name":"Melina Matthews","avatar":""},{"name":"Sarah Demeestere","avatar":""},{"name":"Anh Duong","avatar":""},{"name":"Bobbi Salvör Menuez","avatar":""},{"name":"Annika Wahlsten","avatar":""},{"name":"Sh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["隔壁的房間","隔壁房间","The Room Next Door","A szomszéd szoba","Qonşu Otaq","La habitación de al lado"]', 1784690324178);
