INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chuyen-tinh-ngay-ha', 'Chuyện Tình Ngày Hạ', 'What Summer Loves!', 'https://phimimg.com/upload/vod/20250619-1/2ae6a98bda8750b104c6056858531a3d.jpg', 'https://phimimg.com/upload/vod/20250619-1/90bf31e38920fbd5c08c2c7ae1f683be.jpg', '<p>Nữ ca sĩ kiêm nhạc sĩ Yeoreum – biểu tượng của “mối tình đầu”, gặp lại Geon - mối tình đầu mà cô thầm thương nhớ qua một dự án quay video ca nhạc mới đầy hỗn loạn.</p>', 'Hoàn Tất (58/58)', 58, 'series', 'completed', 29, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324178);
