INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoat-y', 'Thoát Y', 'Un/Dressed', 'https://phimimg.com/upload/vod/20250619-1/a6eeee5d0e551fe8b592844df93a0004.jpg', 'https://phimimg.com/upload/vod/20250619-1/cffe5fb48e45d0d8dd545d8dc3cd5d97.jpg', '<p>Elle là một nữ doanh nhân trẻ đầy tham vọng, mong muốn đưa nhà mốt của bà ngoại Margot bước vào một kỷ nguyên mới. Cô đang hẹn hò với Thilo, con trai của một gia đình quyền lực ở Hamburg. Tuy nhiên, sau khi bà Margot nhận được những lời đe dọa nặc danh, Ben – một người từng ngồi tù – được giao nhiệm vụ làm vệ sĩ bảo vệ bà. Elle bị giằng xé giữa Thilo và Ben. Khi cô càng dấn sâu vào thế giới của Ben, những bí mật đen tối về Thilo dần được hé lộ — những bí mật có thể khiến toàn bộ sự nghiệp mà bà Margot đã gây dựng suốt đời rơi vào nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 16, 2024, 'Vietsub', 'FHD', 'Đức', 0, '[{"name":"Lena Meckel","avatar":""},{"name":"Malik Blumenthal","avatar":""},{"name":"Gerrit Klein","avatar":""},{"name":"Brigitte Karner","avatar":""},{"name":"Roman Knižka","avatar":""},{"name":"Sophie Pfennigstorf","avatar":""},{"name":"Jakob Geßner","avatar":""},{"name":"Peter Kremer","avatar":""},{"name":"Carl Achleitner","avatar":""},{"name":"Farba Dieng","avatar":""},{"name":"Merzeede Liis Ork","avatar":""},{"name":"Sebastian Freiberg","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["UnDressed","Un Dressed","Un/Dressed"]', 1784690324178);
