INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('grafted', 'Grafted', 'Grafted', 'https://phimimg.com/upload/vod/20250618-1/2f99a5a65e0884f6b69544232e547c60.jpg', 'https://phimimg.com/upload/vod/20250618-1/8ab0b491ead1577eb15928bd5f9b7a18.jpg', '<p>Khi một nữ sinh người Trung Quốc vụng về nhưng tài giỏi giành được học bổng vào một trường đại học danh tiếng ở New Zealand, cô phát hiện ra một cách mới để đạt được sự nổi tiếng mà mình khao khát — bằng máu và xác chết, từng người một.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'New Zealand', 0, '[{"name":"Joyena Sun","avatar":""},{"name":"Jess Hong","avatar":""},{"name":"Eden Hart","avatar":""},{"name":"Jared Turner","avatar":""},{"name":"Sepi Toa","avatar":""},{"name":"Xiao Hu","avatar":""},{"name":"Gideon Smith","avatar":""},{"name":"Ginette McDonald","avatar":""},{"name":"Mark Mitchinson","avatar":""},{"name":"Sam Wang","avatar":""},{"name":"Mohan Liu","avatar":""},{"name":"Phillip Brooks","avatar":""},{"name":"Andrew Munro","avatar":""},{"name":"Aleni Tufuga","avatar":""},{"name":"Alison Quigan","avatar":""},{"name":"Sherry Zhang","avatar":""},{"name":"Trendall Pulini","avatar":""},{"name":"Jaden McLeod","avatar":""},{"name":"Benjamin Hudso","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["移植","이식된 욕망","Grafted"]', 1784690324178);
