INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dien-thoai-ma-am', 'Điện Thoại Ma Ám', 'Cellphone', 'https://phimimg.com/upload/vod/20250618-1/459e5e1b418a81197ae568d15add3748.jpg', 'https://phimimg.com/upload/vod/20250618-1/3dc225dadab93fd6194471c24a10a608.jpg', '<p>Dự án do Luke Sommer chỉ đạo. Wynne (Whitney Rose Pynn đóng) bị chấn thương tâm lý sau cái chết của chồng sắp cưới. Cô quyết định chuyển đến nơi khác để quên đi những buồn đau. Thế nhưng, những hiện tượng bí ẩn xuất hiện tại ngôi nhà mới, đồng thời Wynne nhìn thấy những hình ảnh báo hiệu cái chết của mình trong điện thoại. Cô trở nên lo lắng, bắt đầu tìm cách đối phó những hiện tượng siêu nhiên để bảo vệ tính mạng.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Whitney Rose Pynn","avatar":""},{"name":"Justin Malik Jackson","avatar":""},{"name":"Jared Noble","avatar":""},{"name":"Isaac Versaw","avatar":""},{"name":"Katherine Barber","avatar":""},{"name":"Malcolm McDowell","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Cellphone"]', 1784690324178);
