INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('day-chinh-la-toihien-tai', 'Đây Chính Là Tôi...Hiện Tại', 'This Is Me... Now', 'https://phimimg.com/upload/vod/20250502-1/e44df3be1356ea29fe656a4066a1be94.jpg', 'https://phimimg.com/upload/vod/20250502-1/2cfc2564e552a1000c4b61acb00c692c.jpg', '<p>Một hành trình đầy cảm xúc, mang màu sắc kỳ ảo và đậm tính kể chuyện, phản ánh quá trình tự chữa lành và yêu thương bản thân của Jennifer Lopez. Trong một thế giới đắm chìm nơi âm nhạc và hình ảnh hòa quyện, bộ phim hé lộ những thử thách cô từng đối mặt và những chiến thắng cô đã đạt được.</p>', 'Full', 1, 'single', 'completed', 15, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jennifer Lopez","avatar":""},{"name":"Ben Affleck","avatar":""},{"name":"Idaliz Christian","avatar":""},{"name":"Fat Joe","avatar":""},{"name":"Matthew Law","avatar":""},{"name":"Brandon Delsid","avatar":""},{"name":"Alix Angelis","avatar":""},{"name":"Malcolm Kelner","avatar":""},{"name":"Ashley Versher","avatar":""},{"name":"Danielle Larracuente","avatar":""},{"name":"Gilbert Saldivar","avatar":""},{"name":"Jane Fonda","avatar":""},{"name":"Trevor Noah","avatar":""},{"name":"Kim Petras","avatar":""},{"name":"Post Malone","avatar":""},{"name":"Keke Palmer","avatar":""},{"name":"Sofía Vergara","avatar":""},{"name":"Jenife","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hummingbird","This Is Me... Now: A Love Story","这就是我","This Is Me Now","This Is Me…Now"]', 1784690324178);
