INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-an-tu-qua-khu', 'Bản Án Từ Quá Khứ', 'See Her Again', 'https://phimimg.com/upload/vod/20250508-1/e0395f12f5d4b7941d45ce67194d29de.jpg', 'https://phimimg.com/upload/vod/20250508-1/576075468d29d0762cec6f560d36abb2.jpg', '<p>Một loạt vụ án mạng bắt nguồn từ một vụ cháy chung cư lớn vào những năm 1990. Cảnh sát Hong Kong Dương Quang Diệu (Trần Vỹ Đình) vì lần theo dấu vết của hung thủ, gặp một sự cố xuyên không đến năm 2018. Tại đây anh gặp nữ cảnh sát Trần Khải Tinh (Lưu Nhã Sắt) tiếp tục hành trình tìm ra sự thật đằng sau vụ án kéo dài hơn 20 năm để bảo vệ những người mình yêu thương và giữ vững pháp luật, đòi lại công lý cho nạn nhân.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 7, 2024, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"William Chan","avatar":""},{"name":"Liu Yase","avatar":""},{"name":"Stephen Fung","avatar":""},{"name":"Tse Kwan-Ho","avatar":""},{"name":"Niki Chow","avatar":""},{"name":"Kevin Chu","avatar":""},{"name":"Alan Luk","avatar":""},{"name":"Ling Man-Lung","avatar":""},{"name":"He Dujuan","avatar":""},{"name":"Kumer So","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Protegendo o passado","See Her Again","太陽星辰"]', 1784690324179);
