INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('gau-beo-tung-chuong', 'Gấu Béo Tung Chưởng', 'Combat Wombat: Back 2 Back', 'gấu béo tung chưởng combat wombat: back 2 back deborah mailman ed oxenbould david wenham elizabeth cullen mark coles smith dan brumm grant denyer lorenzo shakhovskoy ricard cussó adam lochowicz kate murphy thalia colettis salena raine ben stewart poppy fitzpatrick combat wombat: double trouble وامبت قهرمان 2 : پشت به پشت גיבורה בהפתעה 2 - טובים השניים מן האחד גיבורה בהפתעה 2 la patrulla salvatge: missió en equip vaprad päästjad combat wombat: back 2 back', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-chua-quen-nguoi-yeu-cu', 'Anh Chưa Quên Người Yêu Cũ', 'Depression Or Just Selfishness', 'https://phimimg.com/upload/vod/20250610-1/8188ef8765e1c0f64673ff58faaa8265.jpg', 'https://phimimg.com/upload/vod/20250610-1/62060a7050abbb4ab910c3c22fedf085.jpg', '<p>Gặp lại mối tình đầu, cô gái lao vào với tất cả lòng chân thành mong có được tình yêu của anh. Hy sinh công việc, cảm xúc và dành thời gian vun vén cho tình đầu của mình nhưng điều mà cô nhận lại chỉ là những tình cảm như một chiếc bóng, người yêu của cô vẫn chỉ xem cô là chiếc bóng của người yêu cũ.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Lồng Tiếng', 'FHD', 'Thái Lan', 0, '[{"name":"Pim Pimprapa Tangprabhaporn","avatar":""},{"name":"March Chutavuth Pattarakhumphol","avatar":""},{"name":"Pim Latthgarmon Pinrojkeerathi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Club Friday Season 16: Depression or Just Selfishness"]', 1784690324179);
