INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-ha-canh', 'Dù hạ cánh', 'Parachute', 'https://phimimg.com/upload/vod/20250608-1/0f5e7452efd69113ce7596425f8e9804.jpg', 'https://phimimg.com/upload/vod/20250608-1/dee38b66582e1d2d474ceef7a46d74b8.jpg', '<p>Rời khỏi cơ sở phục hồi sau hành trình vật lộn với chứng rối loạn ăn uống và ám ảnh ngoại hình, Riley gặp Ethan — và sớm thấy mình chênh vênh giữa ranh giới của tình yêu vô điều kiện... và một cơn nghiện mới.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Courtney Eaton","avatar":""},{"name":"Thomas Mann","avatar":""},{"name":"Francesca Reale","avatar":""},{"name":"Gina Rodriguez","avatar":""},{"name":"Joel McHale","avatar":""},{"name":"Dave Bautista","avatar":""},{"name":"Kid Cudi","avatar":""},{"name":"Celeste Oliva","avatar":""},{"name":"Jennifer Westfeldt","avatar":""},{"name":"Kathryn Gallagher","avatar":""},{"name":"Ekaterina Baker","avatar":""},{"name":"Jeremy Kucharek","avatar":""},{"name":"Rico Paris","avatar":""},{"name":"Kelley Jakle","avatar":""},{"name":"Owen Thiele","avatar":""},{"name":"Chrissie Fit","avatar":""},{"name":"Bunny Gibson","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["September 17th","Parachute"]', 1784690324179);
