INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-tinh-nguyen-tran-chien-sinh-tu', 'Quân Tình Nguyện: Trận Chiến Sinh Tử', 'The Volunteers: The Battle of Life and Death', 'https://phimimg.com/upload/vod/20250608-1/625bd44ac98159745eaae6839ae495e9.jpg', 'https://phimimg.com/upload/vod/20250608-1/d8b98708f5bacf6b21b933e7f6130c13.jpg', '<p>Bộ phim tập trung vào trận chiến Cheolwon, nơi Quân đoàn 63 của Quân đội Tình nguyện Nhân dân Trung Quốc (CPVA) được lệnh tiến vào chiến trường Cheolwon. Vào tháng 5 năm 1951, chỉ sau một tháng chiến đấu với bốn sư đoàn của Quân đội Liên hợp quốc (UNA), những người tình nguyện đã chiến đấu bằng máu và cuối cùng đã đưa kẻ thù vào bàn đàm phán.</p>', 'Full', 1, 'single', 'completed', 13, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhu Yilong","avatar":""},{"name":"Xin Baiqing","avatar":""},{"name":"Zhang Zifeng","avatar":""},{"name":"Zhu Yawen","avatar":""},{"name":"Arthur Chen","avatar":""},{"name":"Wang Yanhui","avatar":""},{"name":"Xiao Yang","avatar":""},{"name":"Wu Jing","avatar":""},{"name":"Zhang Youhao","avatar":""},{"name":"Ou Hao","avatar":""},{"name":"Elvis Han","avatar":""},{"name":"Guo Xiaodong","avatar":""},{"name":"Li Zhuoyang","avatar":""},{"name":"Ren Zhong","avatar":""},{"name":"Li Naiwen","avatar":""},{"name":"Nie Yuan","avatar":""},{"name":"Tang Zeng","avatar":""},{"name":"Wang Ting","avatar":""},{"name":"He Ziming","avatar":""},{"name":"Wang Yang","avatar":""},{"name":"Jia Bing","avatar":""},{"name":"Tang Guoqiang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["志愿军：雄兵出击2","志愿军：再起风云","志愿军三部曲2","伟大的胜利2","战与祀","The Volunteers: To the War 2","The Volunteers: The Battle of Life and Death","志愿军：存亡之战"]', 1784690324179);
