INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('rocky-anh-tho-may-ba-dao', 'Rocky: Anh Thợ Máy Bá Đạo', 'Mechanic Rocky', 'https://phimimg.com/upload/vod/20250608-1/77b7dea3dc37b30bf8596d393d98a0c3.jpg', 'https://phimimg.com/upload/vod/20250608-1/831e2251946eec98cd4373273514e4ec.jpg', '<p>Câu chuyện xoay quanh Rakesh, biệt danh &quot;Rocky&quot;, một thợ máy trẻ sống cùng cha mình, Ramakrishna, và điều hành một gara ô tô kiêm trường dạy lái xe. Cuộc sống của Rocky bị đảo lộn khi một tay xã hội đen tên Rankireddy cố gắng chiếm đoạt gara của gia đình anh. Trong lúc đối mặt với áp lực tài chính và cái chết đột ngột của cha, Rocky phát hiện ra cha anh có một hợp đồng bảo hiểm trị giá 20.000.000 Rupee, nhưng người thụ hưởng không phải là anh. Điều này dẫn đến một chuỗi sự kiện phức tạp, khi Rocky cố gắng tìm hiểu sự thật và bảo vệ di sản của gia đình mình.</p>', 'Full', 1, 'single', 'completed', 14, 2024, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Vishwak Sen","avatar":""},{"name":"Meenakshi Chaudhary","avatar":""},{"name":"Shraddha Srinath","avatar":""},{"name":"Sunil Varma","avatar":""},{"name":"Naresh","avatar":""},{"name":"Hyper Adhi","avatar":""},{"name":"Harsha Chemudu","avatar":""},{"name":"Harshavardhan","avatar":""},{"name":"Vishwadev Rachakonda","avatar":""},{"name":"Jeevan Kumar","avatar":""},{"name":"Raghu Ram","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Vishwak Sen Untitled","VS10","మెకానిక్ రాకీ"]', 1784690324179);
