INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chua-te-cua-nhung-chiec-nhan-cuoc-chien-cua-rohirrim', 'Chúa Tể Của Những Chiếc Nhẫn: Cuộc Chiến Của Rohirrim', 'The Lord Of The Rings: The War Of The Rohirrim', 'https://phimimg.com/upload/vod/20250608-1/10cd211aebedd94e716d0acb30b78124.jpg', 'https://phimimg.com/upload/vod/20250106-1/0204e0f472f614a6a5f899b4abfb5fcd.jpg', '<p>Lấy bối cảnh 183 năm trước những sự kiện trong bộ ba phim gốc, “Chúa Tể Của Những Chiếc Nhẫn: Cuộc Chiến Của Rohirrim&quot; kể về số phận của Gia tộc của Helm Hammerhand, vị vua huyền thoại của Rohan. Cuộc tấn công bất ngờ của Wulf, lãnh chúa xảo trá và tàn nhẫn của tộc Dunlending, nhằm báo thù cho cái chết của cha hắn, đã buộc Helm và thần dân của ngài phải chống cự trong pháo đài cổ Hornburg - một thành trì vững chãi sau này được biết đến với tên gọi Helm&quot;s Deep. Tình thế ngày càng tuyệt vọng, Héra, con gái của Helm, phải dốc hết sức dẫn dắt cuộc chiến chống lại kẻ địch nguy hiểm, quyết tâm tiêu diệt bọn chúng.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Brian Cox","avatar":""},{"name":"Gaia Wise","avatar":""},{"name":"Luke Pasqualino","avatar":""},{"name":"Laurence Ubong Williams","avatar":""},{"name":"Lorraine Ashbourne","avatar":""},{"name":"Miranda Otto","avatar":""},{"name":"Shaun Dooley","avatar":""},{"name":"Benjamin Wainwright","avatar":""},{"name":"Yazdan Qafouri","avatar":""},{"name":"Michael Wildman","avatar":""},{"name":"Janine Duvitski","avatar":""},{"name":"Bilal Hasna","avatar":""},{"name":"Jude Akuwudike","avatar":""},{"name":"Billy Boyd","avatar":""},{"name":"Dominic Monaghan","avatar":""},{"name":"Alex Jordan","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Ringenes Herre: Krigen om Rohan","洛汗之战","The Lord of the Rings: Rohan no Tatakai","映画『ロード・オブ・ザ・リング ローハンの戦い』","Władca Pierścieni Wojna Rohirrimów","Le Seigneur des Anneaux : La Guerre des Rohirrim","The Lord of the Rings: The War of the Rohirrim"]', 1784690324179);
