INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('transformers-mot', 'Transformers Một', 'Transformers One', 'transformers một transformers one chris hemsworth brian tyree henry scarlett johansson keegan-michael key steve buscemi laurence fishburne jon hamm vanessa liguori jon bailey jason konopisos-alvarez evan michael lee james remar isaac c. singleton jr. steve blum jinny chung transformers: a new generation 变形金刚：初代 트랜스포머 원 transformers: o início robot đại chiến một transformers : le commencement transformers un transformers - le commencement transformers, le commencement transformers one 变形金刚：起源 變形金剛：源起 transformerid üks transformers le commencement 变形金刚初始篇', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cu-li-khong-bao-gio-khoc', 'Cu Li Không Bao Giờ Khóc', 'Cu Li Never Cries', 'https://phimimg.com/upload/vod/20250608-1/f22206496046a3316f5c134bbc5682ae.jpg', 'https://phimimg.com/upload/vod/20250608-1/bbb55e7d83324b5a998e240a0acbb012.jpg', '<p>Sau đám tang người chồng cũ ở nước ngoài, bà Nguyện quay lại Hà Nội với một bình tro và một con cu li nhỏ - loài linh trưởng đặc hữu của bán đảo Đông Dương. Về tới nơi, bà phát hiện ra cô cháu gái mang bầu đang vội vã chuẩn bị đám cưới. Lo sợ cô đi theo vết xe đổ của đời mình, bà kịch liệt phản đối. Bộ phim Cu Li Không Bao Giờ Khóc khéo léo pha trộn đời sống hiện tại và những dư âm phức tạp của lịch sử Việt Nam bằng cách đan xen hoài niệm về quá khứ của người dì lớn tuổi và dự cảm về tương lai đầy bất định của cặp đôi trẻ.</p>', 'Full', 1, 'single', 'completed', 12, 2024, 'Vietsub', 'FHD', 'Pháp', 1, '[{"name":"Minh-Châu","avatar":""},{"name":"Ha-Phuong","avatar":""},{"name":"Ngô Xuân An","avatar":""},{"name":"Hoàng-Hà","avatar":""},{"name":"Cao Sang","avatar":""},{"name":"Tâm Anh","avatar":""},{"name":"Thương Tín","avatar":""},{"name":"Thanh Hiền","avatar":""},{"name":"Van Thai Nguyen","avatar":""},{"name":"Kieu-Trinh","avatar":""},{"name":"Phí-Linh","avatar":""},{"name":"Quốc Tuấn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["小懶猴不哭","Cu li không bao giờ khóc"]', 1784690324179);
