INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhoc-quay-va-khu-rung-ky-dieu', 'Nhóc Quậy và Khu Rừng Kỳ Diệu', 'Into The Wonderwoods', 'https://phimimg.com/upload/vod/20250606-1/6127fc4aa77b17f0bcd721bf728c8207.jpg', 'https://phimimg.com/upload/vod/20250606-1/44b7befcff635399fbaff96ec3df99f0.jpg', '<p>Angelo mơ ước trở thành một nhà thám hiểm và nhà động vật học. Khi cậu lên đường cùng gia đình để thăm người bà yêu quý đang đau yếu của mình, cha mẹ cậu đã bỏ cậu lại ở một trạm dừng chân. Bị bỏ mặc, Angelo quyết định băng qua khu rừng để tìm kiếm gia đình mình. Cậu bước vào một thế giới đen tối và bí ẩn, nơi sinh sống của những sinh vật kỳ lạ.</p>', 'Full', 1, 'single', 'completed', 22, 2024, 'Vietsub', 'FHD', 'Pháp', 1, '[{"name":"Yolande Moreau","avatar":""},{"name":"Philippe Katerine","avatar":""},{"name":"José Garcia","avatar":""},{"name":"Dario Hardouin Spurio","avatar":""},{"name":"Prune Bozo","avatar":""},{"name":"Raphaël Lamarque","avatar":""},{"name":"Marie Nonnenmacher","avatar":""},{"name":"Benjamin Carlier","avatar":""},{"name":"Antoine Tomé","avatar":""},{"name":"Emmanuel Garijo","avatar":""},{"name":"Boris Rehlinger","avatar":""},{"name":"Augustin Jacob","avatar":""},{"name":"Jérôme Pauwels","avatar":""},{"name":"Stephan Kalb","avatar":""},{"name":"Vincent Paronnaud","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["In the Dark and Mysterious Forest","ANGELO, DANS LA FORÊT MYSTÉRIEUSE","Angelo a varázserdőben","Angelo en el Bosque Mágico","Angelo dans la forêt mystérieuse"]', 1784690324179);
