INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-ti-hon', 'Biệt Đội Tí Hon', 'The Super Elfkins', 'https://phimimg.com/upload/vod/20250606-1/303d6cff507e0de6a2d7164c3bf36a8d.jpg', 'https://phimimg.com/upload/vod/20250606-1/97ebdcf46f6c35d98daa00de25bc62ca.jpg', '<p>Thế giới của Elfie bị đảo lộn khi phát hiện ra băng đảng Elfkin - trái ngược hoàn toàn với gia tộc mình. Liệu tình bạn &quot;hai bờ chiến tuyến&quot; của Helvi và Bo có thể hòa giải mâu thuẫn hơn 250 năm này?</p>', 'Full', 1, 'single', 'completed', 17, 2024, 'Lồng Tiếng', 'FHD', 'Đức', 1, '[{"name":"Jella Haase","avatar":""},{"name":"Leon Seidel","avatar":""},{"name":"Annette Frier","avatar":""},{"name":"Paul Pizzera","avatar":""},{"name":"Michael Ostrowski","avatar":""},{"name":"Cesár Sampson","avatar":""},{"name":"Hilde Dalik","avatar":""},{"name":"Bill Mockridge","avatar":""},{"name":"Margie Kinsky","avatar":""},{"name":"Siham El-Maimouni","avatar":""},{"name":"Dave Davis","avatar":""},{"name":"Sophia Heinzmann","avatar":""},{"name":"Lars Walther","avatar":""},{"name":"Sibylle Kuhne","avatar":""},{"name":"Thomas Balou Martin","avatar":""},{"name":"Julia von Tettenborn","avatar":""},{"name":"A","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Haldjarahvas 2","Die Heinzels - Neue Mützen, neue Mission"]', 1784690324179);
