INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('soi-thu-doi-dau', '"Sói" Thủ Đối Đầu', 'Wolfs', 'https://phimimg.com/upload/vod/20240927-1/8256b460d95f2aed10f1f5c41d169d26.jpg', 'https://phimimg.com/upload/vod/20240927-1/704d0dd2c11f9d7ff7e2501e58521961.jpg', '<p>Hai địch thủ &quot;gỡ rối&quot; đụng độ khi cả hai được gọi đến để giúp che đậy sai lầm cho một nhân vật có tiếng ở New York. Sau một đêm dữ dội, họ sẽ phải gác lại những bất đồng nhỏ nhặt — và cái tôi — để hoàn thành công việc.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"George Clooney","avatar":""},{"name":"Brad Pitt","avatar":""},{"name":"Austin Abrams","avatar":""},{"name":"Amy Ryan","avatar":""},{"name":"Poorna Jagannathan","avatar":""},{"name":"Richard Kind","avatar":""},{"name":"Zlatko Burić","avatar":""},{"name":"Irina Dubova","avatar":""},{"name":"Linda Carola","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["울프스","گرگ ها","狼性修理工","Loups","Canavarlar","זאבים","Wolfs"]', 1784690324179);
