INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-vu-ong', 'Mật Vụ Ong', 'The Beekeeper', 'https://phimimg.com/upload/vod/20250604-1/95191b6457d6487877fc41566a9cfe32.jpg', 'https://phimimg.com/upload/vod/20250604-1/b8bd87be9d6fbbafa77ce4e17e43f958.jpg', '<p>Jason Statham vào vai Adam Clay, một người nuôi ong cần mẫn và đơn độc. Anh có mối quan hệ tốt với bà chủ nhà, thậm chí coi bà như người thân duy nhất của mình. Thế nhưng, một sự kiện xảy ra khiến bà qua đời, và “người nuôi ong” Adam Clay quyết định bắt đầu kế hoạch trả thù tàn bạo của mình. Trong khi Clay vạch trần bí mật đằng sau đường dây lừa đảo cỡ lớn và bắt những kẻ có tội phải trả giá, thân phận thật của anh cũng dần được hé lộ.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Anh', 1, '[{"name":"Jason Statham","avatar":""},{"name":"Emmy Raver-Lampman","avatar":""},{"name":"Bobby Naderi","avatar":""},{"name":"Josh Hutcherson","avatar":""},{"name":"Jeremy Irons","avatar":""},{"name":"David Witts","avatar":""},{"name":"Michael Epp","avatar":""},{"name":"Taylor James","avatar":""},{"name":"Phylicia Rashād","avatar":""},{"name":"Jemma Redgrave","avatar":""},{"name":"Minnie Driver","avatar":""},{"name":"Don Gilet","avatar":""},{"name":"Sophia Feliciano","avatar":""},{"name":"Enzo Cilenti","avatar":""},{"name":"Megan Le","avatar":""},{"name":"Dan Li","avatar":""},{"name":"Georgia Goodman","avatar":""},{"name":"Derek Sio","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["A méhész","Beekeeper: Sentencia de Muerte","Beekeeper: Sentencia de muerte","Beekeeper - Rede de V