INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mat-vu-ong', 'Mật Vụ Ong', 'The Beekeeper', 'mật vụ ong the beekeeper jason statham emmy raver-lampman bobby naderi josh hutcherson jeremy irons david witts michael epp taylor james phylicia rashād jemma redgrave minnie driver don gilet sophia feliciano enzo cilenti megan le dan li georgia goodman derek sio a méhész beekeeper: sentencia de muerte beekeeper: sentencia de muerte beekeeper - rede de vingança the beekeeper (english) le gardien (french) 养蜂人 pčelar пчеловод pszczelarz the beekeeper - o protector čebelar beekeeper: el protector 蜂刑者 arıcı: ölüm kovanı бджоляр mật vụ ong زنبوردار ザ・ビーキーパー arıçı ο μελισσοκόμος le gardien the beekeeper', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-cuu-hoa-chicago-phan-13-2024', 'Đội Cứu Hoả Chicago (Phần 13)', 'Chicago Fire (Season 13)', 'https://phimimg.com/upload/vod/20250517-1/f529c709c74d82703249b62e9fffee7d.jpg', 'https://phimimg.com/upload/vod/20250603-1/714ebfd5e367b0fea0aab534fcb09d09.jpg', '<p>Góc nhìn trực tiếp về cuộc sống hàng ngày của những anh hùng với một trong những nghề cao quý nhất của nước Mỹ. &nbsp;Đối với các nhân viên cứu hỏa, đội cứu hộ và nhân viên y tế của Chicago Firehouse 51, không có nghề nghiệp nào căng thẳng hoặc nguy hiểm hơn, nhưng lại đáng làm và phấn khích như vậy. &nbsp;Những người đàn ông và phụ nữ can đảm này là một trong số những người ưu tú đâm đầu vào nguy hiểm khi những người khác đang chạy theo hướng khác và hành động của họ tạo ra sự khác biệt giữa sự sống và cái chết.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Taylor Kinney","avatar":""},{"name":"David Eigenberg","avatar":""},{"name":"Joe Miñoso","avatar":""},{"name":"Christian Stolte","avatar":""},{"name":"Miranda Rae Mayo","avatar":""},{"name":"Daniel Kyri","avatar":""},{"name":"Hanako Greensmith","avatar":""},{"name":"Jocelyn Hudon","avatar":""},{"name":"Jake Lockett","avatar":""},{"name":"Dermot Mulroney","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chicago Fire : Caserne 51","风城烈火","芝加哥烈火群英","Chicago fire","שיקגו Fire","שיקגו פייר","آتش‌نشانی شیکاگو","Чикаго в огне","One Chicago","Chicago Fire"]', 1784690324179);
