INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-co-seon-ju-phuc-thu', 'Quý Cô Seon Ju Phục Thù', 'Desperate Mrs. Seon Ju', 'https://phimimg.com/upload/vod/20241120-1/0d48bf417de0adb32b6812145b0ea317.jpg', 'https://phimimg.com/upload/vod/20241120-1/05e935ee1659e79b7c50e9c8346aa2b1.jpg', '<p>Một người phụ nữ mạnh mẽ phá bỏ cuộc hôn nhân đầy bất hạnh của mình và xây dựng một &quot;ngôi nhà mới&quot; để bắt đầu lại từ đầu.</p>', 'Hoàn Tất (126/126)', 126, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Sim Yi Young","avatar":""},{"name":"Song Chang Eui","avatar":""},{"name":"Choi Jung Yoon","avatar":""},{"name":"Joung Young Sub","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["亲切的善珠小姐","Desperate Mrs Seon Ju","Quý Cô Seon Ju Phục Thù","친절한 선주씨"]', 1784690324179);
