INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-tieu-thu-vuot-qua-chong-gai', 'Đại Tiểu Thư Vượt Qua Chông Gai', 'Lady Revenger Returns From The Fire', 'https://phimimg.com/upload/vod/20250602-1/7e0b79ad70175146def6fa6639782488.jpg', 'https://phimimg.com/upload/vod/20250602-1/a48cf847961a671264642289d139fbaf.jpg', '<p>Thẩm Đan Thanh (Từ Lộ) vốn là tiểu thư La Ái Liên của gia tộc sản xuất rượu nổi tiếng họ La, bất hạnh bị một trận hỏa hoạn đảo lộn cuộc đời, buộc phải tái sinh từ tro tàn. Thay đổi dung mạo trở thành đại tiểu thư của một tiêu cục, lấy tên là Thẩm Đan Thanh. Thẩm Đan Thanh thông minh, dũng cảm, âm thầm điều tra, từng bước trả thù những kẻ đã hãm hại mình. Nam chính Từ Trình Phong (Ngụy Triết Minh) là một vị tướng quân phong độ ngời ngời, mưu lược hơn người, trong quá trình điều tra án đã quen biết Thẩm Đan Thanh. Mối quan hệ giữa hai người có cá tính mạnh mẽ, thông qua những lần so tài trí tuệ và võ nghệ, họ dần nảy sinh tình cảm, trở thành người yêu có thể kề vai sát cánh chiến đấu.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2024, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Từ Lộ","avatar":""},{"name":"Ngụy Triết Minh","avatar":""},{"name":"Lưu Tá Ninh","avatar":""},{"name":"Ngô Sùng Hiên","avatar":""},{"name":"Trình Kim Minh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["PiJingZhanJiDeDaXiaoJie","Lady Revenger Returns From the Fire","披荆斩棘的大小姐"]', 1784690324179);
