INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ba-thim-bao-thu', 'Bà Thím Báo Thù', 'Citizen Of A Kind', 'https://phimimg.com/upload/vod/20250530-1/efe06c4df01ca14db7fe25a2b7970aeb.jpg', 'https://phimimg.com/upload/vod/20250530-1/f2d38691fc48446c112f6fd93468610b.jpg', '<p>Kẻ lừa tiền “quay xe”, cầu cứu sự trợ giúp từ chính nạn nhân mà mình đã lừa đảo! Đang chật vật vay mượn khắp nơi để tiếp tục duy trì cửa tiệm giặt ủi sau hoả hoạn, Duk Hee nhận được cú điện thoại từ Son, tự xưng là nhân viên ngân hàng với lời hứa hẹn sẽ cấp cho cô một khoản vay với lãi suất ưu đãi. Tuy nhiên, Son yêu cầu Duk Hee phải gửi trước cho anh ta một khoản tiền gọi là “phí vay mượn”. Sau khi chuyển tiền, người phụ nữ tội nghiệp mới bàng hoàng nhận ra mình vừa trở thành nạn nhân của một kẻ chuyên lừa đảo qua điện thoại di động. Cú lừa này đã khiến Duk Hee mất toàn bộ tài sản và đối mặt với nguy cơ bị tống ra đường cùng hai đứa con. Giận dữ, oán trách nhưng Duk Hee nghĩ rằng cô sẽ không thể tìm được danh tính của Son. Cho tới một ngày nọ, Son bỗng chủ động liên lạc với Duk Hee và đưa ra một lời cầu cứu thảm thiết…</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Ra Mi-ran","avatar":""},{"name":"Gong Myoung","avatar":""},{"name":"Yeom Hye-ran","avatar":""},{"name":"Park Byung-eun","avatar":""},{"name":"Jang Yoon-ju","avatar":""},{"name":"Lee Mu-saeng","avatar":""},{"name":"Ahn Eun-jin","avatar":""},{"name":"Lee Ju-seung","avatar":""},{"name":"Sung Hyuk","avatar":""},{"name":"Seo Ji-hoo","avatar":""},{"name":"Park Seong-geun","avatar":""},{"name":"Pyo Chang-won","avatar":""},{"name":"Lim Ha-bi","avatar":""},{"name":"Kwon Eun-seong","avatar":""},{"name":"Moon Dong-hyeok","avatar":""},{"name":"Ahn So-yo","avatar":""},{"name":"Lee Hae-woon","avatar":""},{"name":"Kim Ki-moo","avatar":""},{"name":"Shim Wan-j","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["시민 덕희","金派特攻隊","Bà Thím Báo Thù","Citizen of a Kind","Simin Deok-hee","시민덕희"]', 1784690324179);
