INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('minh-hon', 'Minh Hôn', 'Baridegi: The Abandoned Girl', 'https://phimimg.com/upload/vod/20250530-1/0b971acb0abc710cb9be8a81f8225182.jpg', 'https://phimimg.com/upload/vod/20250530-1/e6020255558f51452ae164cc363b8583.jpg', '<p>Sau khi mất vợ và con gái, Won Go Myeong – một pháp sư đầy hận thù đã phát hiện gã tài phiệt đã đứng sau cái chết gia đình ông. Với ma thuật đen, Go Myeong đã gọi hồn, triệu vong vạch trần sự thật và khiến gã tài phiệt đền mạng thế nhưng mọi chuyện chỉ là khởi đầu….</p>', 'Full', 1, 'single', 'completed', 12, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"Kong Jeong-hwan","avatar":""},{"name":"Ji Dae-han","avatar":""},{"name":"Hwang Seol-ah","avatar":""},{"name":"Son Eun-ho","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["바리데기"]', 1784690324179);
