INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('reagan', 'Reagan', 'Reagan', 'https://phimimg.com/upload/vod/20250530-1/db535a844301480ffb89e3ece144feb7.jpg', 'https://phimimg.com/upload/vod/20250530-1/51dc89c61f935d25828f185e231b522e.jpg', '<p>Phim tiểu sử về Ronald Reagan, từ ngôi sao điện ảnh đến Tổng thống Mỹ có ảnh hưởng lớn thời Chiến tranh Lạnh.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Dennis Quaid","avatar":""},{"name":"Penelope Ann Miller","avatar":""},{"name":"Jon Voight","avatar":""},{"name":"Kevin Dillon","avatar":""},{"name":"Olek Krupa","avatar":""},{"name":"David Henrie","avatar":""},{"name":"Mark Moses","avatar":""},{"name":"Xander Berkeley","avatar":""},{"name":"Nick Searcy","avatar":""},{"name":"C. Thomas Howell","avatar":""},{"name":"Robert Davi","avatar":""},{"name":"Lesley-Anne Down","avatar":""},{"name":"Dan Lauria","avatar":""},{"name":"Mena Suvari","avatar":""},{"name":"Amanda Righetti","avatar":""},{"name":"Justin Chatwin","avatar":""},{"name":"Jennifer O''Nei","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Crusader: Ronald Reagan and the Fall of Communism","ریگان","ראייגן","Reagan: de Hollywood a la Casa Blanca","Reagan"]', 1784690324179);
