INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('reagan', 'Reagan', 'Reagan', 'reagan reagan dennis quaid penelope ann miller jon voight kevin dillon olek krupa david henrie mark moses xander berkeley nick searcy c. thomas howell robert davi lesley-anne down dan lauria mena suvari amanda righetti justin chatwin jennifer o''nei the crusader: ronald reagan and the fall of communism ریگان ראייגן reagan: de hollywood a la casa blanca reagan', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-trai-vuot-moi-tam-tai', 'Anh Trai Vượt Mọi Tam Tai', 'The Desperate Chase', 'https://phimimg.com/upload/vod/20240917-1/45d22a4d538ed1c21a594720a3c8ce86.jpg', 'https://phimimg.com/upload/vod/20240917-1/bf0a663345cd5edc146586c0235afa48.jpg', '<p>Cho Su Gwang là một thanh tra cực kỳ nóng tính, dù có tỷ lệ bắt giữ tội phạm ấn tượng nhưng anh luôn gặp khó khăn trong việc kiểm soát cơn giận của mình. Vì liên tục tấn công các nghi phạm, Cho Su Gwang bị chuyển đến đảo Jeju. Tại đây, vị thanh tra nhận nhiệm vụ truy bắt kẻ lừa đảo giỏi nhất Hàn Quốc - Kim In Hae với 7 tiền án, nổi tiếng thông minh và có khả năng “thiên biến vạn hoá” để ngụy trang hoàn hảo mọi nhân dạng. Cùng lúc đó, Kim In Hae bất ngờ dính vào vụ án mạng nghiêm trọng có liên quan đến tên trùm xã hội đen đang nhăm nhe “thôn tính” đảo Jeju. Trước tình hình nguy cấp phải “giải cứu” hòn đảo Jeju và triệt phá đường dây nguy hiểm của tên trùm xã hội đen, thanh tra Cho Su Gwang bất đắc dĩ phải hợp tác cùng nghi phạm Kim In Hae, tận dụng triệt để các kỹ năng từ phá án đến lừa đảo trên hành trình rượt đuổi vừa gay cấn vừa hài hước để có thể hoàn thành nhiệm vụ cam go.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"Park Sung Woong","avatar":""},{"name":"Kwak Si Yang","avatar":""},{"name":"Yoon Kyung Ho","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["تعقیب ناامیدانه","تعقیب غیرمعمولی","필사의 추격"]', 1784690324179);
