INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-kich-di-giao', 'Thảm Kịch Dị Giáo', 'Longlegs', 'https://phimimg.com/upload/vod/20250530-1/0989917e12436a76887d47f9b32a6b2e.jpg', 'https://phimimg.com/upload/vod/20250530-1/eeeb7ce529c0f18199bfdeac530f0cad.jpg', '<p>Đặc vụ FBI Lee Harker được giao phụ trách một vụ án giết người hàng loạt chưa được giải quyết và diễn biến bất ngờ, tiết lộ bằng chứng về điều huyền bí. Harker phát hiện ra mối liên hệ cá nhân với kẻ giết người và phải ngăn chặn hắn trước khi hắn tấn công lần nữa.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Maika Monroe","avatar":""},{"name":"Nicolas Cage","avatar":""},{"name":"Blair Underwood","avatar":""},{"name":"Alicia Witt","avatar":""},{"name":"Michelle Choi-Lee","avatar":""},{"name":"Dakota Daulby","avatar":""},{"name":"Lauren Acala","avatar":""},{"name":"Kiernan Shipka","avatar":""},{"name":"Maïla Hosie","avatar":""},{"name":"Jason William Day","avatar":""},{"name":"Lisa Chandler","avatar":""},{"name":"Ava Kelders","avatar":""},{"name":"Rryla McIntosh","avatar":""},{"name":"Carmel Amit","avatar":""},{"name":"Shafin Karim","avatar":""},{"name":"Trey Helten","avatar":""},{"name":"Daniel Bacon","avatar":""},{"name":"Van","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Longlegs: Coleccionista De Almas","Kod Zła","O Colecionador de Almas","長腿","Ruh Toplayici","لنگ‌درازها","Sielų Kolekcionierius","长腿怪","长脚怪","Лонглес","გრძელფეხება: სულებზე მონადირე","Longlegs - Vínculo Mortal","Sekáč","Longlegs"]', 1784690324179);
