INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tham-kich-di-giao', 'Thảm Kịch Dị Giáo', 'Longlegs', 'thảm kịch dị giáo longlegs maika monroe nicolas cage blair underwood alicia witt michelle choi-lee dakota daulby lauren acala kiernan shipka maïla hosie jason william day lisa chandler ava kelders rryla mcintosh carmel amit shafin karim trey helten daniel bacon van longlegs: coleccionista de almas kod zła o colecionador de almas 長腿 ruh toplayici لنگ‌درازها sielų kolekcionierius 长腿怪 长脚怪 лонглес გრძელფეხება: სულებზე მონადირე longlegs - vínculo mortal sekáč longlegs', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chi-dau-2025', 'Chị Dâu', 'The Real Sister', 'https://phimimg.com/upload/vod/20250529-1/3a81e181a5f643bb9108bce41e22de5d.jpg', 'https://phimimg.com/upload/vod/20250529-1/82672132c0a2e07e915af631ff52484b.jpg', '<p>Chuyện bắt đầu khi bà Nhị - con dâu cả của gia đình quyết định nhân dịp đám giỗ của mẹ chồng, tụ họp cả bốn chị em gái - con ruột trong nhà lại để thông báo chuyện sẽ tự bỏ tiền túi ra sửa sang căn nhà từ đường cũ kỹ trước khi bão về. Vấn đề này khiến cho nội bộ gia đình bắt đầu có những lục đục, chị dâu và các em chồng cũng xảy ra mâu thuẫn, bất hoà. Dần dà những sự thật đằng sau việc &quot;bằng mặt mà không bằng lòng&quot; giữa các chị em cũng dần được hé lộ, những bí mật, nỗi đau sâu thẳm nhất trong mỗi cá nhân cũng dần được bóc tách. Liệu sợi dây liên kết vốn đã mong manh giữa các chị em có bị cắt đứt và liệu “căn nhà” vốn đã dột nát ấy có còn nguyên vẹn sau cơn bão lớn?</p>', 'Full', 1, 'single', 'completed', 15, 2024, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Ngọc Trinh","avatar":""},{"name":"Hồng Đào","avatar":""},{"name":"Việt Hương","avatar":""},{"name":"Đinh Y Nhung","avatar":""},{"name":"Lê Khánh","avatar":""},{"name":"Trung Dũng","avatar":""},{"name":"Khương Ngọc","avatar":""},{"name":"Vinh Râu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Chị dâu"]', 1784690324179);
