INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-truong-muon-thu', 'Đấu Trường Muôn Thú', 'Noah''s Ark', 'https://phimimg.com/upload/vod/20250527-1/9bf86adcf59c4d2ae7e07b02d85e5efc.jpg', 'https://phimimg.com/upload/vod/20250527-1/887a5a7dd80923b6cdb0b24f81f788cd.jpg', '<p>Khi Trận Đại Hồng Thủy xảy ra, mỗi loài chỉ có một đực và một cái được lên tàu Noah. Trên con tàu lánh nạn đó, những cuộc tranh tài giữa muôn loài diễn ra đầy thú vị với nhiều bài học ý nghĩa.</p>', 'Full', 1, 'hoathinh', 'completed', 13, 2024, 'Vietsub + Lồng Tiếng', 'FHD', 'Brazil', 0, '[{"name":"Rodrigo Santoro","avatar":""},{"name":"Marcelo Adnet","avatar":""},{"name":"Alice Braga","avatar":""},{"name":"Lázaro Ramos","avatar":""},{"name":"Júlio Andrade","avatar":""},{"name":"Bruno Gagliasso","avatar":""},{"name":"Rihanna Barbosa","avatar":""},{"name":"Edvana Carvalho","avatar":""},{"name":"Gregório Duvivier","avatar":""},{"name":"Ingrid Guimarães","avatar":""},{"name":"Heloísa Périssé","avatar":""},{"name":"Daniel Furlan","avatar":""},{"name":"Débora Nascimento","avatar":""},{"name":"Seu Jorge","avatar":""},{"name":"Giovanna Ewbank","avatar":""},{"name":"Luis Miranda","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["نوح کی کشتی","诺亚方舟历险记","诺亚方舟","Arca de Noé"]', 1784690324179);
