INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dia-nguc-ngot-dang', 'Địa Ngục Ngọt Đắng', 'Bitter Sweet Hell', 'https://phimimg.com/upload/vod/20250525-1/877d375e903ef6fe5a1792fa27826347.jpg', 'https://phimimg.com/upload/vod/20250525-1/26784bc78a6f32675fd466770d4f8f46.jpg', '<p>Bộ phim xoay quanh một cố vấn tâm lý tài năng hàng đầu của Hàn Quốc tên là No Young Won, cô gái thường xuyên phải đối đầu với mẹ chồng mình vì những câu chuyện, thậm chí là những bí mật mà do chồng cô gây ra. Tưởng chừng như cuộc sống của gia đình cô là viên mãn để khiến nhiều người ghen tị nhưng thực tế thì cũng khá nhiều những điều vừa bí ẩn và cũng khá bi hài. No Young Won vừa vướng vào một vụ án đầy bất ngờ. Điều này khiến cô và gia đình cô gặp nguy hiểm. No Young Won cùng với mẹ mẹ chồng Hong Sa Gang quyết tâm đấu tranh để có thể bảo vệ gia đình họ.</p>', 'Hoàn Tất (17/17)', 17, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Hee-seon","avatar":""},{"name":"Lee Hye-young","avatar":""},{"name":"Kim Nam-hee","avatar":""},{"name":"Lee Kyung-hoon","avatar":""},{"name":"Shin So-yul","avatar":""},{"name":"Yeon-woo","avatar":""},{"name":"Hwang Chan-seong","avatar":""},{"name":"Park Jae-chan","avatar":""},{"name":"Lee Ga-yeon","avatar":""},{"name":"Kwon Hae-hyo","avatar":""},{"name":"Jung Woong-in","avatar":""},{"name":"An Kil-kang","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["我们家","我们，家","BSH","လျှို့ဝှက်သောမိသားစု","الجحيم الحلو المر","我們，家","Our Home","우리, 집"]', 1784690