INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khanh-du-nien-phan-2', 'Khánh Dư Niên (Phần 2)', 'Joy Of Life (Season 2)', 'https://phimimg.com/upload/vod/20240516-1/463f4f66edfa984adba1201731fea4e4.jpg', 'https://phimimg.com/upload/vod/20240516-1/e63204ec4c8e01363683674fa2eccf71.jpg', '<p>Phim dựa trên tiểu thuyết cùng tên của tác giả Miêu Nị, kể về hành trình gian nan của Phạm Nhàn, một thiếu niên mang thân phận bí ẩn. Trải qua muôn vàn thử thách chốn giang hồ, chốn triều đình, Phạm Nhàn dần trưởng thành và viết nên trang sử cuộc đời đầy cảm xúc.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 7, 2024, 'Vietsub + Thuyết Minh + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Nhược Quân","avatar":""},{"name":"Trần Đạo Minh","avatar":""},{"name":"Lý Thấm","avatar":""},{"name":"Ngô Cương","avatar":""},{"name":"Lý Tiểu Nhiễm","avatar":""},{"name":"Quách Kỳ Lân","avatar":""},{"name":"Tống Dật","avatar":""},{"name":"Tân Chỉ Lôi","avatar":""},{"name":"Kim Thần","avatar":""},{"name":"Phó Tân Bác","avatar":""},{"name":"Mao Hiểu Đồng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324179);
