INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tiem-do-co-a-xa', 'Tiệm Đồ Cổ A Xá', 'Ya She', 'https://phimimg.com/upload/vod/20241030-1/ff2a55456ff4f4884d5685a3817bd3e5.jpg', 'https://phimimg.com/upload/vod/20241030-1/e7722e0a87136932bc30a85711fad01f.jpg', '<p>Thành phố hiện đại ồn ào náo nhiệt, nhưng thời gian như lắng đọng nơi đây. Những kho báu huyền thoại thật thật giả giả, từng bị lãng quên trong dòng chảy dài của thời gian. Tuy nhiên, ngay lúc này, chúng đang hiện diện tại tiệm đồ cổ mang tên &quot;Ách Xá &quot;. Ông chủ tiệm, Cam Tất Chi, có khả năng lắng nghe tiếng gọi của đồ cổ, tìm kiếm những người có duyên để hoàn thành tâm nguyện của chúng. Ông kết thân với vị bác sĩ nhiệt tình Tô Bắc Lục và trở thành bạn tốt. Chỉ ông chủ Cam mới biết vị bác sĩ này cũng ẩn chứa điều gì đó khác thường...</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tao Wu","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["哑舍动画","Ya She","哑舍","Yashe","Yǎ Shè","哑舍动画版","Mute House","Dumb House","Silence House","Silent House"]', 1784690324179);
