INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bonhoeffer-muc-su-gian-diep-ke-am-sat', 'Bonhoeffer: Mục Sư, Gián Điệp, Kẻ Ám Sát', 'Bonhoeffer: Pastor. Spy. Assassin', 'https://phimimg.com/upload/vod/20250523-1/e5292501444b5ab8b66a94793fc8267c.jpg', 'https://phimimg.com/upload/vod/20250523-1/4e54c5bb56dd70e332f3c1573532664d.jpg', '<p>Phim kể về Dietrich Bonhoeffer, một mục sư và nhà thần học người Đức, người đã dũng cảm chống lại chế độ phát xít Đức dưới thời Hitler. Sau khi chứng kiến sự tàn bạo của Đức Quốc xã và sự thoái hóa của các nhà thờ quốc doanh, ông quyết định tham gia vào phong trào kháng chiến. Không chỉ giảng đạo, Bonhoeffer còn trở thành gián điệp và âm thầm hỗ trợ các kế hoạch ám sát Hitler.Trong khi đào tạo các mục sư ngầm và giúp người Do Thái trốn thoát, Bonhoeffer bị bắt vào năm 1943 và cuối cùng bị xử tử năm 1945 tại trại tập trung Flossenbürg, chỉ vài tuần trước khi chiến tranh kết thúc.</p>', 'Full', 1, 'single', 'completed', 19, 2024, 'Vietsub', 'FHD', 'Bỉ', 0, '[{"name":"Jonas Dassler","avatar":""},{"name":"Phileas Heyblom","avatar":""},{"name":"August Diehl","avatar":""},{"name":"David Jonsson","avatar":""},{"name":"Moritz Bleibtreu","avatar":""},{"name":"Nadine Heidenreich","avatar":""},{"name":"Clarke Peters","avatar":""},{"name":"Flula Borg","avatar":""},{"name":"Lisa Hofer","avatar":""},{"name":"Arthur Riordan","avatar":""},{"name":"Luise Landau","avatar":""},{"name":"William Robinson","avatar":""},{"name":"James Flynn","avatar":""},{"name":"Greg Kolpakchi","avatar":""},{"name":"Simon Licht","avatar":""},{"name":"Mark Wingett","avatar":""},{"name":"Evan Hart","avatar":""},{"name":"Vi","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["God''s Spy","A Redenção – A História Real de Bonhoeffer","Bonhoeffer","Bonhoeffer, el espía","Bonhoeffer: Pastor. Spy. Assassin"]', 1784690324179);
