INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('the-mole-ai-la-noi-gian-phan-2', 'The Mole: Ai Là Nội Gián (Phần 2)', 'The Mole (Season 2)', 'https://phimimg.com/upload/vod/20250523-1/97b1bfe7448817e4d7c458c9950bab94.jpg', 'https://phimimg.com/upload/vod/20250523-1/2c3d43efa24fb83215a7e331743d6305.jpg', '<p>Trong bản làm lại chương trình kinh điển đình đám này, mười hai người chơi hoàn thành các thử thách trong khi cố nhận dạng một kẻ trong số họ đang phá hoại các nhiệm vụ.</p>', 'Hoàn Tất (10/10)', 10, 'tvshows', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ari Shapiro","avatar":""},{"name":"Antonio Alejandro Castellanos","avatar":""},{"name":"Quaylyn","avatar":""},{"name":"Sean","avatar":""},{"name":"Ryan Warner","avatar":""},{"name":"Neesh Riaz","avatar":""},{"name":"Muna Abdulahi","avatar":""},{"name":"Michael O''Brien","avatar":""},{"name":"Melissa Lummus","avatar":""},{"name":"Jennifer","avatar":""},{"name":"Hannah Burns","avatar":""},{"name":"Deanna Thompson","avatar":""},{"name":"Andy Mintzer","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["เดอะ โมล","The Mole"]', 1784690324179);
