INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cam-on-moi-nguoi-tiep-theo-phan-1', 'Cảm Ơn, Mời Người Tiếp Theo (Phần 1)', 'Thank You, Next (Season 1)', 'cảm ơn, mời người tiếp theo (phần 1) thank you, next (season 1) serenay sarıkaya metin akdülger hakan kurtaş boran kuzum ahmet rıfat şungar bade i̇şçil esra ruşan️️️️ meriç aral efe tunçer kamil güler cem güler fatih artman batuhan bayar ege aydan perihan savaş seray sever спасибо. следующий! thank you, next kimler geldi kimler geçti', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-nghin-ty-2024', 'Trò Chơi Nghìn Tỷ', 'Trillion Game', 'https://phimimg.com/upload/vod/20250328-1/8c16f70da4f904deb5dc3da068510f28.jpg', 'https://phimimg.com/upload/vod/20250328-1/7e6ab7e0e271f13419f3584e496292c6.jpg', '<p>Haru – một kẻ láu cá, nhanh trí và có tài thu phục lòng người, cùng Gaku – một mọt máy tính nhút nhát, luôn gặp khó khăn trong giao tiếp. Hai con người với tính cách trái ngược hoàn toàn dần trở nên thân thiết sau một sự kiện xảy ra từ thời trung học. Vài năm sau, khi đã trở thành sinh viên đại học, Gaku miệt mài tìm việc nhưng liên tục thất bại trong các buổi phỏng vấn do bản tính rụt rè của mình. Trong lúc làm công việc lau kính tại trụ sở tập đoàn lớn Dragon Bank – công ty mà cậu khao khát được vào làm, Gaku bất ngờ nhận được lời đề nghị từ Haru: “Cùng nhau khởi nghiệp đi!” “Chúng ta sẽ sống theo cách của riêng mình, không ai có thể ngăn cản!” Để chạm tay vào tất cả mọi thứ trên thế gian này, cả hai lao vào một cuộc chiến khởi nghiệp đầy bất ngờ, với mục tiêu kiếm được 1 nghìn tỷ đô la và vươn lên đỉnh cao!</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Takeo Otsuka","avatar":""},{"name":"Shoya Ishige","avatar":""},{"name":"Yuki Tanaka","avatar":""},{"name":"Mao Ichimichi","avatar":""},{"name":"Hiroki Touchi","avatar":""},{"name":"Takaya Hashi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["一兆遊戲","一兆游戏","一兆＄游戏","1,000,000,000,000$ Game","Trillion Game","トリリオンゲーム"]', 1784690324179);
