INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('overlord-thanh-quoc', 'OVERLORD: Thánh Quốc', 'OVERLORD: The Sacred Kingdom', 'overlord: thánh quốc overlord: the sacred kingdom satoshi hino yoshino aoyama hitomi nabatame saori hayami haruka tomatsu asami seto yumi hara masayuki katou yuuya uchida hidenobu kiuchi kohsuke toriumi masami iwasaki ryunosuke watanuki hiromichi tezuka akinori egoshi taiki yamashita yuki overlord 聖王国編 overlord movie 3: sei oukoku-hen overlord movie 3 - sei oukoku-hen gekijouban overlord: sei oukoku hen gekijouban overlord - sei oukoku hen 劇場版 オーバーロード 聖王国編 overlord: holy kingdom overlord: el reino sagrado 不死者之王 剧场版 圣王国篇 ارباب: پادشاهی مقدس 剧场版 overlord：圣王国篇 overlord - the sacred kingdom overlord the sacred kingdom overlord, the sacred kingdom overlord movie - sei oukoku-hen overlord: the sacred kingdom 劇場版「オーバーロード」聖王国編', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doraemon-nobita-va-ban-giao-huong-dia-cau', 'Doraemon: Nobita và Bản Giao Hưởng Địa Cầu', 'Doraemon the Movie: Nobita''s Earth Symphony', 'https://phimimg.com/upload/vod/20250521-1/0514f6f2eef84b1340afd31c42574a2d.jpg', 'https://phimimg.com/upload/vod/20250521-1/3b5ed51c3fb1dca303cfedbbfd59c904.jpg', '<p>Nobita đang tập chơi nhạc, môn mà cậu không giỏi để chuẩn bị cho buổi hòa nhạc ở trường. Một cô gái bí ẩn, Mika, xuất hiện trước mặt cậu, cô ấy thích âm thanh thư giãn và vô tư của Nobita, nên mời cậu và những người bạn của cậu đến Đại Sảnh Danh Vọng Fare, nơi được tạo ra trên một hành tinh nơi âm nhạc trở thành năng lượng. Để cứu lấy đại sảnh danh vọng này, Mika đang tìm kiếm một bậc thầy âm nhạc để biểu diễn cùng mình! Doraemon và những người bạn sử dụng &quot;Giấy phép Nhạc sĩ&quot; để chọn nhạc cụ và chơi với Mika, dần dần khôi phục lại Đại sảnh Danh Vọng Fare. Tuy nhiên, một sinh vật đáng sợ xóa bỏ âm nhạc khỏi thế giới đang đến gần và trái đất đang gặp nguy hiểm...! Liệu có thể cứu được “tương lai của âm nhạc” và trái đất?</p>', 'Full', 1, 'hoathinh', 'completed', 16, 2024, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 1, '[{"name":"Wasabi Mizuta","avatar":""},{"name":"Megumi Oohara","avatar":""},{"name":"Yumi Kakazu","avatar":""},{"name":"Subaru Kimura","avatar":""},{"name":"Tomokazu Seki","avatar":""},{"name":"Riana Hirano","avatar":""},{"name":"Cocoro Kikuchi","avatar":""},{"name":"Kyoko Yoshine","avatar":""},{"name":"Koji Kikkawa","avatar":""},{"name":"Kanji Ishimaru","avatar":""},{"name":"Mutsumi Tamura","avatar":""},{"name":"Cho","avatar":""},{"name":"Kaya Soya","avatar":""},{"name":"Sho Kaga","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["映画ドラえもん のび太の地球交響楽（ちきゅうシンフォニー）","電影哆啦A夢：大雄的地球交響樂","Eiga Doraemon: Nobita no Chikyū Symphony","โดราเอมอนเดอะมูฟวี่ ตอน โลกแห่งซิมโฟนี่ของโนบิตะ","โดราเอมอน เดอะมูฟวี่ ตอนโลกแห่งซิมโฟนี่ของโนบิตะ","Doraemon: Nobita''s Earth Symphony","多啦A梦：大雄之地球交响乐","डोरेमोन: नोबिताज की पृथ्वी सिम्फनी","डोरीमोन: नोबिताज अर्थ सिंफनी","多啦 A 夢大長篇 43：大雄之地球交響樂","映画ドラえもん のび太の地球交響楽"]', 1784690324179);
