INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doraemon-nobita-va-ban-giao-huong-dia-cau', 'Doraemon: Nobita và Bản Giao Hưởng Địa Cầu', 'Doraemon the Movie: Nobita''s Earth Symphony', 'doraemon: nobita và bản giao hưởng địa cầu doraemon the movie: nobita''s earth symphony wasabi mizuta megumi oohara yumi kakazu subaru kimura tomokazu seki riana hirano cocoro kikuchi kyoko yoshine koji kikkawa kanji ishimaru mutsumi tamura cho kaya soya sho kaga 映画ドラえもん のび太の地球交響楽（ちきゅうシンフォニー） 電影哆啦a夢：大雄的地球交響樂 eiga doraemon: nobita no chikyū symphony โดราเอมอนเดอะมูฟวี่ ตอน โลกแห่งซิมโฟนี่ของโนบิตะ โดราเอมอน เดอะมูฟวี่ ตอนโลกแห่งซิมโฟนี่ของโนบิตะ doraemon: nobita''s earth symphony 多啦a梦：大雄之地球交响乐 डोरेमोन: नोबिताज की पृथ्वी सिम्फनी डोरीमोन: नोबिताज अर्थ सिंफनी 多啦 a 夢大長篇 43：大雄之地球交響樂 映画ドラえもん のび太の地球交響楽', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kim-oc-tang-phu', 'Kim Ốc Tàng Phu', 'Golden House Hidden Love', 'https://phimimg.com/upload/vod/20240123-1/ff94972ba1ef78fe60aa85e253c300c3.jpg', 'https://phimimg.com/upload/vod/20240123-1/ffd9de5182146324206acc833bd2683a.jpg', '<p>Cô gái Kim Hạ, nghĩ rằng mình sẽ sống cô đơn suốt đời, đã vay một khoản vay 30 năm để mua một căn biệt thự giá đặc biệt trong thị trấn biển &quot;Vọng Thê Trấn&quot;. Đêm đầu tiên chuyển đến ngôi nhà cổ, Kim Hạ gặp một chàng trai giống như người cổ đại tên là Nam Hoa, người này mất trí nhớ và tự nhận là đã sống trong ngôi nhà cổ nghìn năm. Sau nhiều lần cố gắng đuổi Nam Hoa mà không thành công, Kim Hạ, để bảo vệ ngôi nhà cổ mà mình đã trả góp bằng công sức suốt tháng, buộc phải giữ kín sự tồn tại của Nam Hoa, từ đó bắt đầu cuộc sống chung trong &quot;Ngôi Nhà Vàng ẩn mình&quot;. Trong thời gian sống chung, Nam Hoa nhớ lại rằng anh ta thực sự là một &quot;người cổ đại&quot; sống đã hàng nghìn năm, và lý do anh ta ở lại ngôi nhà cổ hàng nghìn năm là để đợi một người, trong khi mọi dấu hiệu cho thấy người đó có thể chính là bạn cùng phòng của anh ta - Kim Hạ.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lại Mỹ Vân","avatar":""},{"name":"Vương Tử Hào","avatar":""},{"name":"Cốc Lam Đế","avatar":""},{"name":"Bành Tất Dao","avatar":""},{"name":"Đồng Dĩ Huyên","avatar":""},{"name":"Lý Văn Linh","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324179);
