INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phai-chang-la-dinh-menh', 'Phải Chăng Là Định Mệnh?', 'Serendipity''s Embrace', 'https://phimimg.com/upload/vod/20240726-1/e4841c9e39bf3f9baa0d2176e4fb3d13.jpg', 'https://phimimg.com/upload/vod/20240726-1/e76559842c0b588f33037f89b7da14a9.jpg', '<p>Bộ phim kể câu chuyện về những người trẻ tình cờ gặp lại mối tình đầu của mình sau 10 năm, cùng bước trên hành trình tìm kiếm ước mơ và tình yêu chân thành. Lee Hong Ju (Kim So Hyun), một nhà sản xuất (PD) phim hoạt hình luôn sợ hãi tình yêu sau khi gặp phải những tổn thương trong quá khứ. Kang Hoo Yeong (Chae Jong Hyeop), một chuyên viên tài chính làm việc tại trụ sở chính một công ty lớn ở Mỹ. Tái ngộ mối tình đầu 10 năm trước, Kang Hoo Yeong cảm nhận được trái tim anh loạn nhịp một lần nữa.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim So Hyun","avatar":""},{"name":"Chae Jong Hyeop","avatar":""},{"name":"Yun Ji On","avatar":""},{"name":"Kim Da Som","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324179);
