INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bang-tuyet-dao', 'Băng Tuyết Dao', 'Snow Fall', 'https://phimimg.com/upload/vod/20240730-1/ee90442cfafb2c450c938946375f24f7.jpg', 'https://phimimg.com/upload/vod/20240730-1/cc207c484173a0f3cde51c1760123318.jpg', '<p>Vào một đêm định mệnh, nhà trí thức nổi tiếng Thẩm Chi Hoành vô tình chạm trán Mễ Lam, con gái của một thương gia giàu có nhưng bị mù từ nhỏ. Mễ Lam tình cờ nhìn thấy ánh sáng trong chốc lát và phát hiện bí mật bất tử của Thẩm Chi Hoành. Kể từ đó, giữa hai người hình thành mối liên kết chặt chẽ, giúp họ cứu rỗi nhau giữa bão táp của thời buổi loạn lạc.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Cao Vỹ Quang","avatar":""},{"name":"Âu Dương Na Na","avatar":""},{"name":"Đổng Tư Thành","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324179);
