INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-gian-vua-dung', 'Thời Gian Vừa Đúng', 'Just In Time', 'https://phimimg.com/upload/vod/20250520-1/de00ce2b781c9b76f0e01796b7e6f682.jpg', 'https://phimimg.com/upload/vod/20250520-1/ce963f3c7424916c95c69f25379abf0c.jpg', '<p>Hứa Mộng An, người đã đến tuổi trung niên và tưởng rằng mọi thứ đều trong tầm kiểm soát, đột nhiên mất kiểm soát cuộc sống của mình, công ty sa thải nhân viên trên diện rộng, sự thăng tiến trong sự nghiệp bị cản trở, chồng cô là Lý Lâm bị mất việc, con gái anh bị nghi ngờ yêu cún con và anh bất ngờ sinh đứa con thứ hai, những câu hỏi dồn dập khiến cô kiệt sức cả về tinh thần lẫn thể chất...</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 8, 2024, 'Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Tần Hải Lộ","avatar":""},{"name":"Bảo Kiếm Phong","avatar":""},{"name":"Tả Tiểu Thanh","avatar":""},{"name":"Điền Vũ","avatar":""},{"name":"Phan Chi Lâm","avatar":""},{"name":"Tôn Hạo","avatar":""},{"name":"Đỗ Nguyên","avatar":""},{"name":"Giả Tiếu Hàm","avatar":""},{"name":"Lý Y Hiểu","avatar":""},{"name":"Đàm Khải","avatar":""},{"name":"Mục Lệ Yến","avatar":""},{"name":"Lương Lệ","avatar":""},{"name":"Chương Đào","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["ShiGuangZhengHao","Как раз вовремя","Идеальное время","Just in Time","时光正好"]', 1784690324179);
