INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thoi-gian-vua-dung', 'Thời Gian Vừa Đúng', 'Just In Time', 'thời gian vừa đúng just in time tần hải lộ bảo kiếm phong tả tiểu thanh điền vũ phan chi lâm tôn hạo đỗ nguyên giả tiếu hàm lý y hiểu đàm khải mục lệ yến lương lệ chương đào shiguangzhenghao как раз вовремя идеальное время just in time 时光正好', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hanh-phuc-bi-danh-cap', 'Hạnh Phúc Bị Đánh Cắp', 'Stolen Happiness', 'https://phimimg.com/upload/vod/20240821-1/4c92222e6d20720d84e587e959bb2ca9.jpg', 'https://phimimg.com/upload/vod/20240821-1/dd4dd618bd2e53e356f0665f5567103d.jpg', '<p>Bộ phim được Việt hóa từ bộ phim tình cảm đình đám Hàn Quốc - Jang Bo Ri is here do đài MBC sản xuất và phát sóng năm 2014. Thời điểm phát sóng, bộ phim đã nhận được nhiều sự quan tâm theo dõi của khán giả với mức rating &quot;khủng&quot;. Bộ phim đã gây bão khắp quốc gia châu Á, trong đó có Việt Nam và nhận được hàng loạt giải thưởng danh giá. Phim Hạnh phúc bị đánh cắp quy tụ dàn diễn viên hai miền Bắc - Nam, với sự kết hợp giữa những cái tên đình đám bên cạnh nhiều gương mặt trẻ triển vọng. Để phù hợp với văn hóa và đời sống của người Việt, nếu bản gốc xoay quanh nghề làm hanbok thì bản Việt hóa khai thác nghề thêu trên nền áo dài - tranh vẽ của gia tộc họ Đỗ. Bên cạnh đó là những thử thách, sự tranh đấu của thế hệ trẻ để trở thành truyền nhân thêu của gia tộc họ Đỗ.</p>', 'Hoàn Tất (85/85)', 85, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Thuận Nguyễn","avatar":""},{"name":"Bích Ngọc","avatar":""},{"name":"Steven Nguyễn","avatar":""},{"name":"Quỳnh Lương","avatar":""},{"name":"Hạnh Thúy","avatar":""},{"name":"Trung Dũng","avatar":""},{"name":"Cát Tường","avatar":""},{"name":"Đại Nghĩa","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324179);
