INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-on-trong-co-the-co-ayanother-soul-in-me', 'Làm Ơn Trong Cơ Thể Cô Ấy', 'Another Soul In Me', 'https://phimimg.com/upload/vod/20250117-1/3c2bd2db82d22524a3bcd98b12f8b7ba.jpg', 'https://phimimg.com/upload/vod/20250117-1/4be5661f99b6d81a2eff6855ba493f37.jpg', '<p>Lưu Tú Anh (do Dương Khôn thủ vai) là một người bà hoạt bát, giỏi giao tiếp, sống cùng cháu gái Lưu Khải Mộng (do Ngô Giai Di thủ vai), một cô gái trẻ hướng nội và thiếu tự tin. Dù sống cùng nhau nhiều năm, hai bà cháu vẫn tồn tại khoảng cách do khác biệt thế hệ và thiếu giao tiếp. Một tai nạn bất ngờ khiến họ hoán đổi linh hồn: bà Tú Anh phải thích nghi với cuộc sống của một cô gái trẻ trong môi trường công sở hiện đại, trong khi Khải Mộng trải nghiệm cuộc sống của một người lớn tuổi với những thói quen và mối quan hệ khác biệt. Trong quá trình sống cuộc đời của nhau, họ dần thấu hiểu và cảm thông, từ đó hàn gắn mối quan hệ gia đình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Ngô Giai Di","avatar":""},{"name":"Dương Khôn","avatar":""},{"name":"Trương Dịch Kiệt","avatar":""},{"name":"Lục Vân Phong","avatar":""},{"name":"Mã Lệ","avatar":""},{"name":"Trương Bác Vũ","avatar":""},{"name":"Lưu Á Cẩm","avatar":""},{"name":"Bảo Thần Hy","avatar":""},{"name":"Trương Ái Nguyệt","avatar":""},{"name":"Ngụy Trần Phi","avatar":""},{"name":"Cảnh Lộ","avatar":""},{"name":"Chu Lệ Quân","avatar":""},{"name":"Lưu Nguyên Phong","avatar":""},{"name":"Ôn Trác","avatar":""},{"name":"Hạo Trúc Vũ","avatar":""},{"name":"Từ Hồng Kiệt","avatar":""},{"name":"Lý Văn Sở","avatar":""},{"name":"Dương Tác Cửu","avatar":""},{"name":"Khương Hiểu Đồng","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Another Soul In Me","拜托了，身体里的她"]', 1784690324179);
