INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-bay-ngot-ngao', 'Cạm Bẫy Ngọt Ngào', 'Sweet Trap', 'https://phimimg.com/upload/vod/20240205-1/6852b7f17827119748fc29932669c2f4.jpg', 'https://phimimg.com/upload/vod/20240205-1/feddcebb4aa1932f581297d51a7b0243.jpg', '<p>Bếp trưởng kém tiếng tăm Khương Giới và cô học trò đầy sức sống Lý Nại từng là thanh mai trúc mã, nhiều năm sau trùng phùng lại trở thành đối thủ mang mối hận “đoạt đao”. Để trả thù Khương Giới đoạt đao, Lý Nại đành thâm nhập “nằm vùng” ở nhà hàng của Khương Giới. Từ thuở đầu không ưa nhau đến khi hiểu được lòng mình rồi hướng về phía nhau, cả hai cùng gặt hái được tình yêu và trưởng thành qua những cuộc đọ sức tài nấu bếp.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 10, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tạ Bân Bân","avatar":""},{"name":"Trương Miểu Di","avatar":""},{"name":"Điền Hử Ninh","avatar":""},{"name":"Bành Nhã Kỳ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324179);
