INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ta-co-the-giac-ngo-vo-han', 'Ta Có Thể Giác Ngộ Vô Hạn', 'I Can Infinite Epiphany', 'https://phimimg.com/upload/vod/20250224-1/45661fa96f864849ba1272a970e8fede.jpg', 'https://phimimg.com/upload/vod/20250224-1/671142302e840bfc94145846b03b2f7e.jpg', '<p>Dựa vào khí phách, lòng dũng cảm, cũng như sự trợ giúp của hệ thống giác ngộ, thiếu niên Tiêu Vân với cơ thể phàm trần tham gia giải đấu Thần thể đại năng tranh đoạt tư cách Đại đế. Nhưng mà, sao Đại Đế trăm vạn năm trước lại biết đến hắn? Sao hắn trong tương lai lại để lại bút ký? Lai lịch thực sự của hệ thống giác ngộ lại là gì nữa? Tất cả thế giới bình hành đang đối diện với nguy cơ cực lớn, người duy nhất có thể cứu vớt được thế giới chính là thiếu niên trái đất mà chúng thần triệu hồi đến.</p>', 'Hoàn Tất (52/52)', 52, 'hoathinh', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yuantao Zhang","avatar":""},{"name":"Zhou Dong","avatar":""},{"name":"Tang Zixi","avatar":""},{"name":"Haiting Cai","avatar":""},{"name":"Yin Boyi","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["玄幻，我顿悟了混沌体","Wo Neng Wuxian Dunwu","Xuanhuan, Wo Neng Wuxian Dunwu","我能无限顿悟","Wo Neng Wu Xian Dun Wu","Puedo Alcanzar Infinitas Iluminaciones","Fusion Fantasy: I Can Infinite Epiphany","Fantasy: I Can Experience Limitless Enlightenment","I Can Have Infinite Epiphanies","I Can Infinite Epiphany","I Can Have Infinite Epiphany","I Can Have Unlimited Epiphanies","Vô Địch Đốn Ngộ","Ta Có Thể Giác Ngộ Vô Hạn"]', 1784690324179);
