INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('c4-tinh-yeu', 'C4 Tình Yêu', 'C4 Cinta', 'null', 'https://phimimg.com/upload/vod/20250520-1/dd31a78ac6f93f4d1940bf0179db6610.jpg', '<p>Hari, Soniya và những người bạn đi qua Singapore và Malaysia, đối mặt với những mối quan hệ được hồi sinh, những thực tế không được nói ra. Hành trình của họ khám phá tình yêu, ký ức, bản sắc thông qua những bi kịch cảm xúc liên quan đến gia đình và tình bạn.</p>', 'Full', 1, 'single', 'completed', 13, 2024, 'Vietsub', 'FHD', 'Malaysia', 0, '[{"name":"Yuvaraj Krishnasamy","avatar":""},{"name":"Pashini Sivakumar","avatar":""},{"name":"Loga Varman Strideran","avatar":""},{"name":"Ravin Rao Santeran","avatar":""},{"name":"K. S. Maniam","avatar":""},{"name":"Thia Lakshana","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["ชื่นรัก ชื่นหัวใจ","C 4 Love","C4 Cinta"]', 1784690324179);
