INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('biet-doi-xe-doi-phan-2', 'Biệt Đội Xe Dơi (Phần 2)', 'Batwheels (Season 2)', 'https://phimimg.com/upload/vod/20241224-1/ef23e9663b20f6ab8ad32334c21fb97f.jpg', 'https://phimimg.com/upload/vod/20241224-1/01369000f8161c7a8de42079d58aec78.jpg', '<p>Batwheels theo chân một đội chống tội phạm tài năng. Họ kết hợp với nhau để chống lại cái xấu, hóa giải các vụ án, và dọn dẹp các con phố của Gotham. Họ là Batwheels, một nhóm những phương tiện chống tội phạm ở thành phố Gotham.</p>', 'Tập 16', 37, 'hoathinh', 'ongoing', 9, 2024, 'Thuyết Minh', 'FHD', 'Âu Mỹ', 0, '[{"name":"Noah Kaye Bentley","avatar":""},{"name":"Jacob Bertrand","avatar":""},{"name":"Kimberly Brooks","avatar":""},{"name":"Madigan Kacmar","avatar":""},{"name":"Lilimar","avatar":""},{"name":"Mick Wingert","avatar":""},{"name":"Ethan Hawke","avatar":""},{"name":"Titus Blake","avatar":""}]', '[{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["超级蝙蝠车","Meet the Batwheels","Batwheels: Holidays on Ice","Batwheels"]', 1784690324179);
