INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-trom-mat-trang-4', 'Kẻ Trộm Mặt Trăng 4', 'Despicable Me 4', 'https://phimimg.com/upload/vod/20250516-1/b8b7c5300932cdfa63990ae789a8d9d8.jpg', 'https://phimimg.com/upload/vod/20250516-1/ba774c09dabd7ef4878dd53e70e01183.jpg', '<p>Tiếp nối những sự kiện trong phần ba Despicable Me 3 (2017), giờ đây Gru (Steve Carrell lồng tiếng) đã hoàn lương, hạn chế tham gia các hoạt động phi pháp. Ngoài vợ Lucy Wilde và các cô con gái nuôi Margo, Edith, Agnes, giờ đây gia đình Gru còn đón thêm thành viên mới là nhóc tì Gru Junior - con trai đầu lòng của anh. Tuy nhiên, sự an toàn của gia đình Gru nhanh chóng bị đe dọa khi kẻ thù cũ của anh là Maxime Le Mal (Will Ferrell lồng tiếng) đã trốn khỏi nhà tù, hắn lên kế hoạch trả thù và thanh toán nợ cũ với Gru. Đồng hành với Maxime còn có người yêu Valentina của gã. Do đó, Gru buộc phải đứng lên đối mặt với kẻ thù để bảo vệ gia đình và các Minions.</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2024, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Steve Carell","avatar":""},{"name":"Kristen Wiig","avatar":""},{"name":"Will Ferrell","avatar":""},{"name":"Sofía Vergara","avatar":""},{"name":"Miranda Cosgrove","avatar":""},{"name":"Dana Gaier","avatar":""},{"name":"Madison Polan","avatar":""},{"name":"Pierre Coffin","avatar":""},{"name":"Chris Renaud","avatar":""},{"name":"Steve Coogan","avatar":""},{"name":"Stephen Colbert","avatar":""},{"name":"Chloe Fineman","avatar":""},{"name":"Joey King","avatar":""},{"name":"Laraine Newman","avatar":""},{"name":"John DiMaggio","avatar":""},{"name":"Tara Strong","avatar":""},{"name":"Romesh Ranganathan","avatar":""},{"name":"Bra","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["卑鄙的我4","من نفرت‌انگیز ۴","Moi, Moche et Méchant 4","Détestable Moi 4","Grusomme meg 4","İyrənc mən 4","Yaramaz Mən 4","Mi villano favorito 4","坏蛋奖门人4","Mina, Supervaras 4","Aulinn ég 4","神偷奶爸4","壞蛋獎門人4","Ich - Einfach unverbesserlich 4","Gru 4. Mi villano favorito","Illumination''s Despicable Me 4","Despicable Me 4"]', 1784690324179);
