INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ke-trom-mat-trang-4', 'Kẻ Trộm Mặt Trăng 4', 'Despicable Me 4', 'kẻ trộm mặt trăng 4 despicable me 4 steve carell kristen wiig will ferrell sofía vergara miranda cosgrove dana gaier madison polan pierre coffin chris renaud steve coogan stephen colbert chloe fineman joey king laraine newman john dimaggio tara strong romesh ranganathan bra 卑鄙的我4 من نفرت‌انگیز ۴ moi, moche et méchant 4 détestable moi 4 grusomme meg 4 i̇yrənc mən 4 yaramaz mən 4 mi villano favorito 4 坏蛋奖门人4 mina, supervaras 4 aulinn ég 4 神偷奶爸4 壞蛋獎門人4 ich - einfach unverbesserlich 4 gru 4. mi villano favorito illumination''s despicable me 4 despicable me 4', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('yeu-vi-tien-dien-vi-tinh', 'Yêu Vì Tiền, Điên Vì Tình', 'Love Lies', 'https://phimimg.com/upload/vod/20250516-1/41dbdcd0169a257b5832a9b32d582523.jpg', 'https://phimimg.com/upload/vod/20250516-1/668d419a8c2303c97a29d97ecb1b713b.jpg', '<p>Một tổ chức lừa đảo trực tuyến vừa bị triệt phá. Một bác sĩ nổi tiếng, thành đạt - Tiến sĩ Veronica Yu, được cho là nạn nhân, và chàng trai trẻ Joe Lee, được nhìn thấy gần hang ổ của tổ chức lừa đảo. Khi ranh giới giữa giả dối và cảm xúc dần xóa nhòa, tình yêu liệu có thật sự tồn tại hay chỉ là một màn kịch hoàn hảo?</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Hồng Kông', 1, '[{"name":"Sandra Ng","avatar":""},{"name":"MC Cheung","avatar":""},{"name":"Stephy Tang Lai-Yan","avatar":""},{"name":"Chan Fai-Hung","avatar":""},{"name":"Emotion Cheung Kam-Ching","avatar":""},{"name":"Ronald Cheng","avatar":""},{"name":"Jo Kok","avatar":""},{"name":"Elva Ni Chen-Xi","avatar":""},{"name":"Joman Chiang","avatar":""},{"name":"Lam Yiu-Sing","avatar":""},{"name":"Alice Hui","avatar":""},{"name":"Keith Ng Shui-Ting","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Wo tan dì na chang lian''ai","我談的那場戀愛"]', 1784690324179);
