INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kho-luu-tru-234', 'Kho Lưu Trữ 234', 'Unit 234', 'https://phimimg.com/upload/vod/20250516-1/f4317958a232382fcd0f27db3bef78fb.jpg', 'https://phimimg.com/upload/vod/20250516-1/8863c80509db6569a4f0be9abddf44a5.jpg', '<p>Phim kể về Laurie Saltair, một nhân viên làm ca đêm tại một cơ sở lưu trữ. Trong một ca trực, cô phát hiện một người đàn ông tên Clayton bị nhốt trong một kho chứa, bị xích vào cáng và mất một quả thận. Khi Laurie cố gắng giúp anh ta, một nhóm tội phạm xuất hiện, sẵn sàng làm mọi cách để lấy lại &quot;hàng hóa&quot; của mình.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Don Johnson","avatar":""},{"name":"Isabelle Fuhrman","avatar":""},{"name":"Jack Huston","avatar":""},{"name":"James DuMont","avatar":""},{"name":"Christopher James Baker","avatar":""},{"name":"Manny Galan","avatar":""},{"name":"Juvian Marquez","avatar":""},{"name":"Anirudh Pisharody","avatar":""},{"name":"Rosemberg Salgado","avatar":""},{"name":"Jenna Z. Alvarez","avatar":""},{"name":"Jason Altman","avatar":""},{"name":"Lia Lando","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Unit 234: The Lock Up","Unit 234"]', 1784690324179);
