INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-cua-tuong-lai', 'Em của Tương Lai', 'My Future You', 'https://phimimg.com/upload/vod/20250515-1/6169b39a6d082b9b2ebfd3208b3d5af2.jpg', 'https://phimimg.com/upload/vod/20250515-1/ac1f7ad79ff3bf2dd540c7647d8f503f.jpg', '<p>Lex gặp Karen trên ứng dụng hẹn hò, nhưng anh ở năm 2009 và cô ở năm 2024. Qua khoảng cách thời gian, anh giúp thay đổi quá khứ của cô, đồng thời định hình lại tương lai của mình.</p>', 'Full', 1, 'single', 'completed', 13, 2024, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Francine Diaz","avatar":""},{"name":"Seth Fedelin","avatar":""},{"name":"Almira Muhlach","avatar":""},{"name":"Christian Vasquez","avatar":""},{"name":"Peewee O''Hara","avatar":""},{"name":"Bodjie Pascua","avatar":""},{"name":"Mosang","avatar":""},{"name":"Marcus Madrigal","avatar":""},{"name":"Izzy Canillo","avatar":""},{"name":"Vance Larena","avatar":""},{"name":"Angelica Lao","avatar":""},{"name":"Donna Cariaga","avatar":""},{"name":"Alex Calleja","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["My Future You"]', 1784690324179);
