INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('that-bai-trong-buoi-xem-mat-toi-keo-tong-tai-di-ket-hon-chop-nhoang', 'Thất Bại Trong Buổi Xem Mắt Tôi Kéo Tổng Tài Đi Kết Hôn Chớp Nhoáng', 'Mr. Wrong And Mr. Right', 'https://phimimg.com/upload/vod/20250515-1/2663daeecb10e0a085bfa7318f41e75d.jpg', 'https://phimimg.com/upload/vod/20250515-1/50bf1c0ccc84f90d81822770c6636d62.jpg', '<p>Giản Mặc cố ý khiến đối tượng xem mắt nhàm chán bỏ đi, rồi bất ngờ kết hôn chớp nhoáng với tổng tài Hách Kỳ Thâm. Tưởng chỉ là cuộc hôn nhân đôi bên cùng có lợi, nào ngờ trong quá trình sống chung, cả hai lại dần nảy sinh tình cảm chân thành. Dù chặng đường ấy không thiếu những kẻ muốn chia rẽ họ, nhưng họ chưa từng nghi ngờ trái tim của đối phương. Cùng nhau vượt qua sóng gió, họ còn khám phá được bí mật thân thế của Giản Mặc. Khi mọi chuyện được sáng tỏ, cả hai đã tổ chức lễ cưới chính thức — viên mãn và hạnh phúc.</p>', 'Hoàn Tất (95/95)', 95, 'series', 'completed', 34, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324179);
