INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-tinh-nhat-duoc-tong-tai-sieu-giau-lam-chong', 'Vô Tình Nhặt Được Tổng Tài Siêu Giàu Làm Chồng', 'My Tycoon Husband', 'https://phimimg.com/upload/vod/20250515-1/26d8eb64980acdf3defaa54ab29126d5.jpg', 'https://phimimg.com/upload/vod/20250515-1/199e507de71088661ba08d66299cafca.jpg', '<p>Ngôi sao nổi tiếng Lương Hạ bất ngờ bắt gặp bạn trai mình phản bội với chính người bạn trong giới giải trí. Quá tức giận, cô say xỉn và qua đêm với Mạnh Đình Phi – tổng tài của tập đoàn M. Lương Hạ nhầm anh là trai bao, sáng hôm sau ném tiền rồi bỏ đi không một lời. Nào ngờ, ảnh hai người ra vào khách sạn bị kẻ xấu tung lên mạng, khiến scandal bùng nổ. Bất đắc dĩ, hai người quyết định kết hôn giả. Nhưng Lương Hạ không hề biết thân phận thật sự của Mạnh Đình Phi – người đàn ông lạnh lùng, tài giỏi, lại âm thầm ở bên bảo vệ cô… Từ đó, một loạt câu chuyện dở khóc dở cười bắt đầu.</p>', 'Hoàn Tất (85/85)', 85, 'series', 'completed', 41, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jian Ge Hao Men Zong Cai Dang Lao Gong","捡个豪门总裁当老公"]', 1784690324179);
