INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-kim-hai-mat', 'Thiên Kim Hai Mặt', 'The Other Her', 'https://phimimg.com/upload/vod/20250515-1/7c24904d3c3108b478a4f4cdf0df8475.jpg', 'https://phimimg.com/upload/vod/20250515-1/e9153cb198850454533b50b7477855ef.jpg', '<p>Thiên kim nhà họ Mộ – Mộ Hoàn Hoàn – thực chất là Dạ Ca, nữ sát thủ hàng đầu trong thế giới ngầm. Trong lần ám sát đại thiếu gia nhà họ Hách – Hách Ninh Viễn, cô bất ngờ phát hiện anh ta không hề bệnh tật yếu ớt như lời đồn. Dưới tác dụng của thuốc, hai người xảy ra quan hệ. Sau đó, Mộ Hoàn Hoàn lập tức biến mất. Một tháng sau, cô phát hiện mình mang thai. Nhà họ Mộ vội vàng sắp xếp một buổi xem mắt, không ngờ tại đó, cô lại tái ngộ Hách Ninh Viễn – và định mệnh giữa hai người một lần nữa bắt đầu...</p>', 'Hoàn Tất (66/66)', 66, 'series', 'completed', 25, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Double-Faced Daugter","双面千金"]', 1784690324179);
