INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tong-tai-le-cung-vo-vo-doi', 'Tổng Tài Lệ Cưng Vợ Vô Đối', 'Unlimited Love', 'https://phimimg.com/upload/vod/20250515-1/55fb642a15e52ac6020cf0ac20bc4687.jpg', 'https://phimimg.com/upload/vod/20250515-1/4e3b0e5781273040ffdf58e7b4415b2d.jpg', '<p>Sau khi bị bạn trai phản bội, Hứa Niệm phát hiện anh ta đã lén lút qua lại với người em gái cùng cha khác mẹ của mình. Cô quay về tìm cha để cầu cứu, nhưng không ngờ lại bị ông bán cho một công tử nhà giàu ăn chơi trác táng. Trong lúc liều mạng chạy trốn, cô được Lệ Thừa Uyên cứu giúp. Không ngờ thuốc trong cơ thể phát tác, khiến cô và anh phát sinh quan hệ. Tưởng rằng chỉ là một đêm sai lầm, ai ngờ người đàn ông ấy lại chính là cậu ruột của tên bạn trai tệ bạc – và anh đã phải lòng cô ngay từ cái nhìn đầu tiên. Từ đó, cả hai bắt tay nhau vạch trần và “vả mặt” cặp đôi phản bội…</p>', 'Hoàn Tất (85/85)', 85, 'series', 'completed', 25, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["厉先生宠妻无限"]', 1784690324179);
