INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('me-oi-chay-mau-bo-duoi-den-noi-roi', 'Mẹ Ơi Chạy Mau, Bố Đuổi Đến Nơi Rồi', 'Mommy Run Away, Daddy Is Chasing You', 'https://phimimg.com/upload/vod/20250515-1/9e8eef38b54b073490cfd55d1115e35e.jpg', 'https://phimimg.com/upload/vod/20250515-1/1af285fae0f9b5b3aa3302e3eddbd979.jpg', '<p>Qua một loạt hiểu lầm, cô và anh gặp nhau rồi chia xa. Vài năm sau, cô trở lại với một đứa bé cực kì đáng yêu! Đứa bé ấy, với phong thái của một &quot;đấng nam nhi&quot;, có ước mơ lớn nhất là tìm được một người chồng hoàn hảo, xứng đáng với &quot;tiểu tiên nữ&quot; của nhà mình. &quot;Chạy lâu như vậy, cũng đến lúc quay về nhận lỗi rồi nhỉ!&quot; - Người đàn ông xuất hiện đầy ngang ngược, muốn gánh vác trách nhiệm của một người cha. Lâm Chỉ không những không giữ được đứa trẻ, mà cả trái tim mình cũng dần để mất.</p>', 'Hoàn Tất (69/69)', 69, 'series', 'completed', 31, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Ma Mi Kuai Pao Die Di Zhui Lai Le","妈咪快跑，爹地追来了"]', 1784690324179);
