INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-phu-phan-dien-cap-99-toi-la-trum-cuoi-nhung-khong-phai-ma-vuong', 'Nữ Phụ Phản Diện Cấp 99: Tôi là trùm cuối nhưng không phải Ma Vương', 'Villainess Level 99: I May Be the Hidden Boss But I''m Not the Demon Lord', 'https://phimimg.com/upload/vod/20250514-1/f561959e27ccc5a36d76698854638470.jpg', 'https://phimimg.com/upload/vod/20250514-1/4db8ab32afc9dbae945556f95ccd297c.jpg', '<p>Một tựa game otome nhất định diễn ra trong Vương quốc Varschein, nơi mà tóc đen bị đánh đồng một cách không bình thường. Eumiella Dolkness là con gái của một bá tước, bị ghét bỏ ngay từ khi còn nhỏ do mái tóc đen huyền của mình - và cô ấy cũng chính là &quot;hidden boss&quot; (đối thủ mạnh mẽ nhưng ẩn dật) trong trò chơi! Trong một sự thay đổi bất ngờ, ở tuổi năm, Eumiella nhớ lại kí ức của kiếp sống trước ở Nhật Bản. Không quan tâm đến khía cạnh lãng mạn của trò chơi gốc, cô ấy bắt đầu tập trung đào tạo kỹ thuật ma thuật độc đáo của mình.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Fairouz Ai","avatar":""},{"name":"Azumi Waki","avatar":""},{"name":"Taku Yashiro","avatar":""},{"name":"Rina Hidaka","avatar":""},{"name":"Kohei Amasaki","avatar":""},{"name":"Yuma Uchida","avatar":""},{"name":"Haruki Ishiya","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["反派千金等级99～我是隐藏头目但不是魔王～","反派大小姐等级99～我是隐藏BOSS但不是魔王","反派千金Lv99 ~虽然我是隐藏BOSS但我可不是魔王~","反派千金等級 99～我是隱藏頭目但不是魔王～","恶役千金LV99","悪役令嬢レベル99 ～私は裏ボスですが魔王ではありません～","Akuyaku Reijō Level 99: Watashi wa Ura-Boss desu ga Maō dewa Arimasen","悪役令嬢LV99","Akuyaku Reijou Level 99: Watashi wa Ura Boss desu ga Maou de wa Arimasen","Akuyaku Reijō Level 99: Watashi wa Ura Boss desu ga Maō de wa Arimasen","AkuyakuLV99","Akuyaku Reijou Level 99: Watashi wa Ura-Boss desu ga Maou dewa Arimasen","Akuyaku Reijou Level 99","悪役令嬢レベル99～私は裏ボスですが魔王ではありません～"]', 1784690324179);
