INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nu-phu-phan-dien-cap-99-toi-la-trum-cuoi-nhung-khong-phai-ma-vuong', 'Nữ Phụ Phản Diện Cấp 99: Tôi là trùm cuối nhưng không phải Ma Vương', 'Villainess Level 99: I May Be the Hidden Boss But I''m Not the Demon Lord', 'nữ phụ phản diện cấp 99: tôi là trùm cuối nhưng không phải ma vương villainess level 99: i may be the hidden boss but i''m not the demon lord fairouz ai azumi waki taku yashiro rina hidaka kohei amasaki yuma uchida haruki ishiya 反派千金等级99～我是隐藏头目但不是魔王～ 反派大小姐等级99～我是隐藏boss但不是魔王 反派千金lv99 ~虽然我是隐藏boss但我可不是魔王~ 反派千金等級 99～我是隱藏頭目但不是魔王～ 恶役千金lv99 悪役令嬢レベル99 ～私は裏ボスですが魔王ではありません～ akuyaku reijō level 99: watashi wa ura-boss desu ga maō dewa arimasen 悪役令嬢lv99 akuyaku reijou level 99: watashi wa ura boss desu ga maou de wa arimasen akuyaku reijō level 99: watashi wa ura boss desu ga maō de wa arimasen akuyakulv99 akuyaku reijou level 99: watashi wa ura-boss desu ga maou dewa arimasen akuyaku reijou level 99 悪役令嬢レベル99～私は裏ボスですが魔王ではありません～', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-mi', 'Tình Mị', 'A Love Beyond Secrets', 'https://phimimg.com/upload/vod/20250513-1/a6165be8090bf41fe5db00f170ee1d54.jpg', 'https://phimimg.com/upload/vod/20250513-1/b0dc7dd573fd521c7ed3adfd2553ee69.jpg', '<p>Do bị đánh thuốc ngoài ý muốn, Kỷ Toàn và Tống Chiêu Lễ tình cờ gặp gỡ, phá vỡ cuộc sống vốn yên bình của Kỷ Toàn. Mọi người đều cho rằng Kỷ Toàn trèo cao, chỉ có Tống Chiêu Lễ biết đây là kế hoạch anh ấp ủ từ lâu. Kỷ Toàn cũng dần dần vén màn bí ẩn trong những lần giằng co. Cả hai mở ra một chuyện tình đầy giằng xé, cứu rỗi đời nhau.</p>', 'Hoàn Tất (92/92)', 92, 'series', 'completed', 26, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Cách Cách","avatar":""},{"name":"Thân Hạo Nam","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["情靡","รักลวงตา"]', 1784690324179);
