INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tieu-thu-bi-an', 'Tiểu Thư Bí Ẩn', 'Who Are You My Lady', 'https://phimimg.com/upload/vod/20250513-1/cfd61ec168c64dede70dc1ba76950245.jpg', 'https://phimimg.com/upload/vod/20250513-1/b181bf3c29dd03bc4fc024c3466895c4.jpg', '<p>Lâm Chí Viễn cấu kết với bạn thân của vợ để sát hại vợ mình là Thẩm Tân Dương. Nhưng ngay trong ngày tang lễ, “Thẩm Tân Dương” lại bất ngờ trở về, khiến tất cả mọi người trở tay không kịp. Hóa ra, Khưu Hiểu Nam – em gái song sinh của Thẩm Tân Dương – đã cải trang thành chị để quay về nhà họ Thẩm, âm thầm điều tra nguyên nhân cái chết và lập kế hoạch báo thù cho chị gái. Khi kế hoạch trả thù sắp thành công thì bất ngờ Thẩm Tân Dương thật trở lại, nhưng cô đã mất trí nhớ… và thậm chí còn đứng về phía Lâm Chí Viễn – kẻ đã giết mình.</p>', 'Hoàn Tất (74/74)', 74, 'series', 'completed', 23, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["千金你是谁"]', 1784690324179);
