INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jane-phan-2', 'Jane (Phần 2)', 'Jane (Season 2)', 'https://phimimg.com/upload/vod/20240628-1/5c5fdd1cf11b069c1bce91622460323b.jpg', 'https://phimimg.com/upload/vod/20250512-1/3e94726c2e6c77d121661a37b5191c97.jpg', '<p>Nhà bảo vệ môi trường đầy hứa hẹn Jane là một cô bé 9 tuổi đang thực hiện nhiệm vụ cứu các động vật đang bị đe dọa. Sử dụng trí tưởng tượng mạnh mẽ của mình, Jane đưa những người bạn thân nhất của mình là David và chú tinh tinh Greybeard vào các cuộc phiêu lưu kì thú để giúp bảo vệ động vật hoang dã trên toàn thế giới.</p>', 'Hoàn Tất (5/5)', 5, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ava Louise Murchison","avatar":""},{"name":"Mason Blomberg","avatar":""},{"name":"Dan Abramovici","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324179);
