INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('meo-map-mang-10-mang', 'Mèo Mập Mang 10 Mạng', '10 Lives', 'https://phimimg.com/upload/vod/20250512-1/ef757d6ddf341d73c103c7612cfaf6e5.jpg', 'https://phimimg.com/upload/vod/20250512-1/796146eaea54241d7b9f2ea2a13b0e80.jpg', '<p>Nhân vật chính của 10 LIVES là Beckett – một chú mèo được nuông chiều tới mức sinh ra ích kỷ, không trân trọng những may mắn mà mình đang được tận hưởng. Nhưng tất cả sắp sửa thay đổi khi cậu ta bất cẩn làm mất đi 9 cái mạng của mình. Không còn mạng nào để phòng thân và phải đối mặt với những điều không thể tránh khỏi, Beckett đã cầu xin để mọi thứ trở lại như xưa. Thoạt đầu, thỉnh cầu này bị bác bỏ, nhưng trong một khoảnh khắc đặc biệt đồng cảm, trái tim của “Người gác cổng” đã lay động và cho phép Beckett có thể quay trở lại Trái đất với một loạt mạng mới. Nhưng điều mà Beckett không nhận ra ngay lập tức chính là cứ với mỗi một mạng mới, cậu ta sẽ chuyển sinh thành một hình dạng khác… Mỗi hình dạng sẽ lại dạy cho Beckett một bài học kịp thời và giá trị.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub + Lồng Tiếng', 'FHD', 'Canada', 0, '[{"name":"Mo Gilligan","avatar":""},{"name":"Simone Ashley","avatar":""},{"name":"Sophie Okonedo","avatar":""},{"name":"Zayn Malik","avatar":""},{"name":"Dylan Llewellyn","avatar":""},{"name":"Jeremy Swift","avatar":""},{"name":"Bill Nighy","avatar":""},{"name":"Tabitha Cross","avatar":""},{"name":"Christopher Jenkins","avatar":""},{"name":"Naomi McDonald","avatar":""},{"name":"Alexis Rodney","avatar":""},{"name":"Nigel Pilkington","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["10 життя","ده زندگی","10 Liv","10 Elu","10 Lives"]', 1784690324179);
