INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ham-tru-an', 'Hầm Trú Ẩn', 'Dugout', 'https://phimimg.com/upload/vod/20250512-1/1b8e245bf2a817ca4d0ef01cc310216c.jpg', 'https://phimimg.com/upload/vod/20250512-1/c0bc3e1895fc6a849bc27346e05c9ddb.jpg', '<p>Hai người bạn đến Saur-Mogila – y tá Sergey từ Nga và Paul người Đức. Họ đang tìm kiếm hiện vật từ Thế chiến thứ hai thì bất ngờ bị đưa ngược về năm 1941, ngay trong trận chiến ở Saur-Mogila. Hai nhân vật chính đứng trước lựa chọn: ở lại và giúp đỡ hoặc trở về thời hiện tại.</p>', 'Full', 1, 'single', 'completed', 18, 2024, 'Vietsub', 'FHD', 'Nga', 0, '[{"name":"Alexandr Metelkin","avatar":""},{"name":"Daniel Littau","avatar":""},{"name":"Veronika Mokhireva","avatar":""},{"name":"Margarita Abroskina","avatar":""},{"name":"Igor Petrenko","avatar":""},{"name":"Vladimir Seleznyov","avatar":""},{"name":"Aleksei Shevchenkov","avatar":""},{"name":"Roman Bogomazov","avatar":""},{"name":"Dean Mayer","avatar":""},{"name":"Elshan Aleskerov","avatar":""},{"name":"Aleksandr Bobrov","avatar":""},{"name":"Denis Volkov","avatar":""},{"name":"Maksim Saprykin","avatar":""}]', '[{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Blindazh","Dugout","Блиндаж"]', 1784690324179);
