INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-sinh-tu-2024', 'Trò Chơi Sinh Tử', 'The Death Game', 'https://phimimg.com/upload/vod/20250511-1/e0f035d67ca3096aa9c2b0a935e9a6b7.jpg', 'https://phimimg.com/upload/vod/20250511-1/8c44aeef971ba41899c3b4fe711e3c5a.jpg', '<p>Truyền thuyết giang hồ &quot;Thử thách Ngũ Độc&quot; là một trò chơi sinh tử, chỉ có một người sống sót có thể giành được phần thưởng là một 1000 lượng vàng. Lãng khách bí ẩn Lâm Vân cùng với Kiều Vũ, Phong Ích Dương và những người khác vượt qua năm cửa ải, chém giết lẫn nhau. Trong quá trình đó, lòng tham, sự tức giận, si mê, kiêu ngạo, và sự nghi ngờ, những mặt tối của nhân tính lộ ra một cách trần trụi. Lâm Vân và Kiều Vũ đã diễn một màn đấu trí, loại bỏ kẻ chủ mưu đứng sau và thành công báo thù.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Wu Shuang","avatar":""},{"name":"Huang Tao","avatar":""},{"name":"Zhao Yiji","avatar":""},{"name":"Wang Maolei","avatar":""},{"name":"Liu Chuxuan","avatar":""},{"name":"Zhuang Qiqian","avatar":""},{"name":"Shang Chengjun","avatar":""},{"name":"Zhang Kai","avatar":""},{"name":"Li Xuan","avatar":""},{"name":"Tong Xiyu","avatar":""},{"name":"Tong Xiqiao","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["生死试炼"]', 1784690324179);
