INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giam-giu', 'Giam Giữ', 'Detained', 'https://phimimg.com/upload/vod/20250511-1/abcbd81e62003a7c1a879db389c5f108.jpg', 'https://phimimg.com/upload/vod/20250511-1/fe9a9f79406d0414d5b89c2431dcbcdb.jpg', '<p>Một người phụ nữ tỉnh dậy trong phòng thẩm vấn của cảnh sát mà không có ký ức về đêm hôm trước. Tuy nhiên, có điều gì đó dường như không hoàn toàn đúng trong đồn cảnh sát này.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Abbie Cornish","avatar":""},{"name":"Laz Alonso","avatar":""},{"name":"John Patrick Amedori","avatar":""},{"name":"Justin H. Min","avatar":""},{"name":"Josefine Lindegaard","avatar":""},{"name":"Breeda Wool","avatar":""},{"name":"Silas Weir Mitchell","avatar":""},{"name":"Moon Bloodgood","avatar":""},{"name":"Bernardo de Paula","avatar":""},{"name":"Jeremiah OC Jahi","avatar":""},{"name":"Eduardo Roman","avatar":""},{"name":"Esther Brown","avatar":""},{"name":"Alexandra Blake","avatar":""},{"name":"Larry Stenseth","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Detida","Bajo Custodia","Presunta inocente","Detained"]', 1784690324179);
