INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bon-mua-yeu', 'Bốn Mùa Yêu', 'Winter Spring Summer or Fall', 'https://phimimg.com/upload/vod/20250510-1/13da9e308d92c40e6c41e174a2bb07e5.jpg', 'https://phimimg.com/upload/vod/20250510-1/3ee0274d2dab075b10be3d8f73f4b17e.jpg', '<p>Winter Spring Summer or Fall 2024 là câu chuyện về Remi, một cô gái có kế hoạch rõ ràng cho tương lai, và Barnes, chàng trai phóng khoáng, sống hết mình cho hiện tại. Cuộc gặp gỡ giữa họ diễn ra trong bốn ngày quan trọng của năm, mỗi mùa mang đến một lựa chọn và thử thách mới. Khi tình cảm dần lớn lên, Remi phải quyết định: đi theo con đường đã định hay bước vào thế giới đầy bất ngờ cùng Barnes.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jenna Ortega","avatar":""},{"name":"Percy Hynes White","avatar":""},{"name":"Adam Rodriguez","avatar":""},{"name":"Marisol Nichols","avatar":""},{"name":"Elias Kacavas","avatar":""},{"name":"Jacqueline Emerson","avatar":""},{"name":"John Raymond Barker","avatar":""},{"name":"Kate Rachesky","avatar":""},{"name":"Alireza Mirmontazeri","avatar":""},{"name":"Kylee Anderson","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Winter, Spring, Summer or Fall","四季情歌","四季之后","冬春夏秋","Dimër, pranverë, verë apo vjeshtë","Winter Spring Summer or Fall"]', 1784690324179);
