INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoi-xuyen-bien-gioi', 'Cười Xuyên Biên Giới', 'Amazon Bullseye', 'https://phimimg.com/upload/vod/20241204-1/0dde026960c5714488ee6c65a5e69f46.jpg', 'https://phimimg.com/upload/vod/20241204-1/d1a9ab93e3782188bf74862074f1bf7e.jpg', '<p>Cười Xuyên Biên Giới kể về hành trình của Jin-bong (Ryu Seung-ryong) - cựu vô địch bắn cung quốc gia, sau khi nghỉ hưu, anh đã trở thành một nhân viên văn phòng bình thường. Đứng trước nguy cơ bị sa thải, Jin-bong phải nhận một nhiệm vụ bất khả thi là bay đến nửa kia của trái đất trong nỗ lực tuyệt vọng để sinh tồn. Sống sót sau một sự cố đe doạ tính mạng, Jin-bong đã “hạ cánh” xuống khu rừng Amazon, nơi anh gặp bộ ba thổ dân bản địa có kỹ năng bắn cung thượng thừa: Sika, Eeba và Walbu. Tin rằng đã tìm ra cách để tự cứu mình, Jin-bong hợp tác với phiên dịch ngáo ngơ Bbang-sik (Jin Sun-kyu) và đưa ba chiến thần cung thủ đến Hàn Quốc cho một nhiệm vụ táo bạo.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"Ryu Seung-ryong","avatar":""},{"name":"Jin Sun-kyu","avatar":""},{"name":"Igor Pedroso","avatar":""},{"name":"Luan Brum","avatar":""},{"name":"J.B. Oliveira","avatar":""},{"name":"Yeom Hye-ran","avatar":""},{"name":"Go Kyung-pyo","avatar":""},{"name":"Jun Suk-ho","avatar":""},{"name":"Lee Soon-won","avatar":""},{"name":"Ana Ruggiero","avatar":""},{"name":"Jung Soon-won","avatar":""},{"name":"Park Young-kyu","avatar":""},{"name":"Jo Woo-jin","avatar":""},{"name":"Joo Hyun-young","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Cười Xuyên Biên Giới","亚马逊弓箭高手","아마존 활명수"]', 1784690324179);
