INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phan-thanh', 'Phẫn Thành', 'Cesium Fallout', 'https://phimimg.com/upload/vod/20250509-1/bb7fa1600cc31f8c5471b8de872770d8.jpg', 'https://phimimg.com/upload/vod/20250509-1/faa835fc86397a6ef8850393cd7b12e6.jpg', '<p>Chất phóng xạ rò rỉ đột ngột! 24 giờ nữa, toàn Hồng Kông sẽ chìm trong thảm họa. Làm thế nào để ngăn chặn ngày tận thế sắp ập đến? Chuyên gia Phạm Vĩ Lập (do Lưu Đức Hoa thủ vai) và Cecilia (do Mạc Văn Úy đóng) mỗi người một kế, căng thẳng leo thang ngay trong đội ngũ chỉ huy. Trong khi đó, đội trưởng cứu hỏa Lê Kiệt Phong (Bạch Vũ thủ vai) và đồng đội đã nhận lệnh lên đường tới tiền tuyến – nơi không ai biết điều gì đang chờ đợi. Thảm họa cận kề, nhưng mặt trái đen tối của giới tài phiệt cũng dần lộ diện. Khi của cải chỉ thuộc về số ít, còn hậu quả thì tất cả cùng gánh chịu – liệu cuộc khủng hoảng lần này có lối thoát nào hay không?</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Đức Hoa","avatar":""},{"name":"Bạch Vũ","avatar":""},{"name":"Mạc Văn Úy","avatar":""},{"name":"Tạ Quân Hào","avatar":""},{"name":"Huỳnh Vịnh Chi","avatar":""},{"name":"Vương Đan Ni","avatar":""},{"name":"Liêu Phàm","avatar":""},{"name":"Vương Mẫn Đức","avatar":""},{"name":"Lâm Bảo Di","avatar":""},{"name":"Trịnh Tắc Sâm","avatar":""},{"name":"Ngô Quân Như","avatar":""},{"name":"Ngô Diệc Phàm","avatar":""},{"name":"Trương Gia Huy","avatar":""},{"name":"Trương Học Hữu","avatar":""},{"name":"Lương Triều Vỹ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý"