INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-cham', 'Nhúng Chàm', 'Indulgence', 'https://phimimg.com/upload/vod/20241225-1/d1e85c9a8da1cb18ce00777fae8d7190.jpg', 'https://phimimg.com/upload/vod/20241225-1/33e6d15544824ee99d6eebf9f4c39f3f.jpg', '<p>Chàng trai và cô gái chơi với nhau từ nhỏ vì một vụ tai nạn giao thông mà bỏ lỡ nhau rất nhiều năm. Ấy thế mà khi gặp lại họ đã trở thành chị em không phải ruột thịt gì. Cả hai đi từ thăm dò lẫn nhau đến giằng xé tâm can, vùng vẫy đấu tranh giữa tình yêu và hận thù gia tộc có thể xảy ra. Sau khi lần theo manh mối, họ cùng nhau tìm ra sự thật về vụ tai nạn giao thông đó, hai người yêu nhau đi đến kết cục viên mãn.</p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 8, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Quân Hạo","avatar":""},{"name":"Phùng Hy Diêu","avatar":""},{"name":"Trương Quán Sâm","avatar":""},{"name":"Lý Giai Hinh","avatar":""},{"name":"Lưu Thuần Túy","avatar":""},{"name":"Hồ Bảo Sâm","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["染指","Indulgence"]', 1784690324179);
