INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('shin-cau-be-but-chi-32-nhat-ky-khung-long-cua-minh', 'Shin - Cậu Bé Bút Chì 32: Nhật Ký Khủng Long Của Mình', 'Crayon Shin-chan the Movie: Our Dinosaur Diary', 'https://phimimg.com/upload/vod/20250508-1/1d59a912ee4c9da9e6b321678c1c1b08.jpg', 'https://phimimg.com/upload/vod/20250508-1/7dffa69701f86d830869f1162afa7df4.jpg', '<p>Kỳ nghỉ hè bắt đầu, Shin cùng nhóm bạn thân trong &quot;biệt đội Kasukabe&quot; nhận được lời mời đến thăm công viên giải trí Đảo Khủng Long. Tình cờ thay, Shin cũng gặp gỡ chú khủng long nhỏ Nana và chú khủng long này gia nhập hội bạn của Shin. Tuy nhiên, sau đó bí mật đằng sau &quot;thân thế&quot; của Nana được tiết lộ và âm mưu độc ác xuất hiện khiến Shin và hội bạn phải ra tay cứu giúp.</p>', 'Full', 1, 'hoathinh', 'completed', 6, 2024, 'Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Yumiko Kobayashi","avatar":""},{"name":"Miki Narahashi","avatar":""},{"name":"Toshiyuki Morikawa","avatar":""},{"name":"Satomi Korogi","avatar":""},{"name":"Mari Mashiba","avatar":""},{"name":"Tamao Hayashi","avatar":""},{"name":"Teiyu Ichiryusai","avatar":""},{"name":"Takumi Kitamura","avatar":""},{"name":"Hatanaka Yū","avatar":""},{"name":"Shunsuke Ito","avatar":""},{"name":"Nana Mizuki","avatar":""},{"name":"Haruka Tomatsu","avatar":""},{"name":"Hiroki Yasumoto","avatar":""},{"name":"Yu Kobayashi","avatar":""},{"name":"Tomoko Kaneda","avatar":""},{"name":"Maaya Uchida","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]',