INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('om-em-that-chat', 'Ôm Em Thật Chặt', 'Hold Me Close', 'https://phimimg.com/upload/vod/20250508-1/4b318a14c68798702ed906ad51511ccb.jpg', 'https://phimimg.com/upload/vod/20250508-1/2f2d9cd8663e0cd37ffa9ad66a948310.jpg', '<p>Lynlyn có năng lực đặc biệt là cảm nhận được liệu một người sẽ mang lại cho cô niềm vui hay khổ đau. Nhưng khi gặp anh chàng du mục Woody, cô lại chẳng nhìn thấu điều gì.</p>', 'Full', 1, 'single', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Philippines', 0, '[{"name":"Carlo Aquino","avatar":""},{"name":"Julia Barretto","avatar":""},{"name":"Jairus Aquino","avatar":""},{"name":"Migo Valid","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Hold Me Close"]', 1784690324180);
