INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-tam-hoang-3-nghia-khi-ngut-troi', 'Hội Tam Hoàng 3: Nghĩa Khí Ngút Trời', 'Triad 3: The Unwavering Brotherhood', 'https://phimimg.com/upload/vod/20250508-1/400d4a0e803b65577dcd791aa063bf31.jpg', 'https://phimimg.com/upload/vod/20250508-1/9413cccdd67890341ad65cc0704cf6cb.jpg', '<p>Bộ ba anh em A Hoa, A Phi và Quốc Tử bị phục kích, và nhiệm vụ chuyển tiền thất bại. Sóng gió nối tiếp sóng gió, khi cả ba phải tham gia cuộc chiến quyền lực giữa các băng đảng. Họ sẽ làm gì giữa tiền bạc và đạo lý? Ai sẽ giành chiến thắng trong cuộc đối đầu giữa hai kẻ mạnh?</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Hồng Kông', 0, '[{"name":"Huỳnh Tông Trạch","avatar":""},{"name":"Đào Đại Vũ","avatar":""},{"name":"Trương Kế Thông","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["The Unwavering Brotherhood","Triad 3","扎职3：义薄云天","紮職3"]', 1784690324180);
