INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-la-nguoi-mac-hoi-chung-asperger', 'Tôi Là Người Mắc Hội Chứng Asperger', 'Aku Jati, Aku Asperger', 'https://phimimg.com/upload/vod/20250508-1/7a75067209225b25e871a36c8949c849.jpg', 'https://phimimg.com/upload/vod/20250508-1/acaeb8b53723fc0b6d6915ce954549e9.jpg', '<p>Jati, một thiếu niên mắc chứng tự kỷ, rất sợ sự thay đổi. Khi anh trai chia tay bạn gái và phá vỡ nhịp sống quen thuộc của hai anh em, Jati quyết tâm giúp anh tìm một người yêu mới để mọi thứ trở lại như cũ. Nhưng hành trình “mai mối” của cậu lại mở ra nhiều điều không ngờ tới, khiến Jati dần hiểu hơn về cảm xúc và sự trưởng thành.</p>', 'Full', 1, 'single', 'completed', 15, 2024, 'Vietsub', 'FHD', 'Indonesia', 0, '[{"name":"Jefri Nichol","avatar":""},{"name":"Hanggini Purinda Retto","avatar":""},{"name":"Pradikta Wicaksono","avatar":""},{"name":"Carissa Perusset","avatar":""},{"name":"Ziva Magnolya","avatar":""},{"name":"Keisya Levronka","avatar":""},{"name":"Mamat Alkatiri","avatar":""},{"name":"Livy Renata","avatar":""},{"name":"Nopek","avatar":""},{"name":"Gabriel Prince","avatar":""},{"name":"Kathrina Irene","avatar":""},{"name":"Eka Nusa Pertiwi","avatar":""},{"name":"Willem Bevers","avatar":""},{"name":"Vonny Anggraini","avatar":""},{"name":"Siti Fauziah","avatar":""},{"name":"Putri Manjo","avatar":""},{"name":"Ke","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Aku Jati, Aku Asperger"]', 1784690324180);
