INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-dac-nhiem-cid-phan-2', 'Đội Đặc Nhiệm CID (Phần 2)', 'CID (Season 2)', 'https://phimimg.com/upload/vod/20250224-1/960a409710fb4884129734bf681229fb.jpg', 'https://phimimg.com/upload/vod/20250224-1/02fb0a60b9dac7bd0ede9d55aba04b11.jpg', '<p>Đội đặc nhiệm CID xoay quanh cuộc điều tra các vụ án hình sự của Cục điều tra tội phạm CID (có trụ sở chính tại Mumbai, bang Maharashtra, Ấn Độ). Thanh tra trưởng Pradyuman (Shivaji Satam), Thanh tra phó Abhijeet (Aditya Srivastava), Thanh tra Daya (Dayanand Shetty) và Thanh tra Fredericks (Dinesh Phadnis) là một bộ tứ sĩ quan ưu tú. Họ là những người không ngại hiểm nguy để truy vết bọn tội phạm đến cùng, mang trong lòng một trái tim quả cảm, cùng niềm tin bất diệt vào sự trường tồn của hai từ &quot;công lý&quot;. Cùng sự hỗ trợ của các thanh tra Shreya (Janvi Chheda), Purvi (Ansha Sayed) và Pankaj (Ajay Nagrath), sự giúp đỡ của các chuyên gia pháp y là Tiến sỹ Salunkhe (Narendra Gupta) – Trưởng phòng pháp y và Tarika (Shraddha Musale) để phá các vụ án phức tạp và quan trọng, tiêu biểu là các vụ án giết người.</p>', 'Hoàn Tất (40/40)', 40, 'series', 'completed', 17, 2024, 'Vietsub', 'FHD', 'Ấn Độ', 0, '[{"name":"Shivaji Satham","avatar":""},{"name":"Aditya Srivastava","avatar":""},{"name":"Dayanand Shetty","avatar":""},{"name":"Shraddha Musale","avatar":""},{"name":"Manav Gohil","avatar":""},{"name":"Smita Bansal","avatar":""},{"name":"Amit Misra","avatar":""},{"name":"Kunal Madhiwala","avatar":""},{"name":"Dhananjay Mandrekar","avatar":""},{"name":"Ansha Sayed","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["सीआई डी","CID","சிஐடி","సిఐడి","सीआय डी","সিআইডি","सीआईडी"]', 1784690324180);
