INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-den-ky-quai-4', 'Ngôi Đền Kỳ Quái 4', 'Pee Nak 4', 'https://phimimg.com/upload/vod/20240729-1/f7d4044fe6da0614d5471198db232cfb.jpg', 'https://phimimg.com/upload/vod/20240729-1/922b5732aee3c0238d9c9c414b9e5374.jpg', '<p>Hồn ma Nak với sức mạnh khủng khiếp nhất, đáng sợ nhất mà bộ đôi mỏ hỗn Balloon &amp; First phải đối mặt để giải cứu cho trai đẹp Min Joon. Liệu hội bạn này sẽ giải được nghiệp mình tạo ra hay sẽ tan rã từ đây?</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 1, '[{"name":"พีรวิชญ์ อรรถชิตสถาพร","avatar":""},{"name":"Witthawat Rattanaboonbaramee","avatar":""},{"name":"ภูริพรรธน์ เวชวงศาเตชาวัชร์","avatar":""},{"name":"Atiwat Saengtien","avatar":""},{"name":"รัฐวิทย์ กิจวรลักษณ์","avatar":""},{"name":"Pannawit Phattanasiri","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324180);
