INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lua-mot-chut-yeu-mot-long', 'Lừa Một Chút, Yêu Một Lòng', 'Honey Money Phony', 'https://phimimg.com/upload/vod/20250506-1/e4fce3ce46eceab03d94db70e231585c.jpg', 'https://phimimg.com/upload/vod/20250506-1/71736983c96c4022812aea3b78deb429.jpg', '<p>Cô gái công sở Lâm Thanh Lãng bị bạn trai tồi Trương Tử Tuấn lừa tình lừa tiền, biến lời thề ngọt ngào trong một đêm thành khoản nợ khổng lồ 201.314 tệ. Khi đang rơi vào tuyệt vọng, cô bất ngờ gặp trùm lừa đảo Âu Dương Huy, người mang đến bước ngoặt cho cuộc đời cô. Cùng nhau, họ kết hợp với thần xe điện đụng Đổng Hiểu Huệ và lão làng lừa đảo Bách Sĩ Thông, lập đội &quot;lừa đảo siêu cấp&quot;, lên kế hoạch &quot;phản đòn&quot; cao tay với Trương Tử Tuấn. Một cặp oan gia ngọt ngào, một biệt đội lừa đảo bá đạo, một trò chơi tình – tiền gay cấn… Liệu họ sẽ phục thù thành công, hay lại rơi vào một vòng xoáy dối trá khác?</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Jin Chen","avatar":""},{"name":"Sunny Sun","avatar":""},{"name":"Li Xueqin","avatar":""},{"name":"Wang Hao","avatar":""},{"name":"David Wang","avatar":""},{"name":"Liu Yan","avatar":""},{"name":"Song Muzi","avatar":""},{"name":"Tong Mo-nan","avatar":""},{"name":"Yi Yunhe","avatar":""},{"name":"Xiao Ai","avatar":""},{"name":"Gabriel Wong Yat-Shan","avatar":""},{"name":"Zhang Quandan","avatar":""},{"name":"Richie Jen","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["恋爱局中局中国版","真心骗徒","Honey Money Phony","“骗骗”喜欢你"]', 1784690324180);
