INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bay-nuot-mang', 'Bẫy Nuốt Mạng', 'The Plot', 'https://phimimg.com/upload/vod/20240619-1/3c11262bf23a6c125ef979c4c63f7e72.jpg', 'https://phimimg.com/upload/vod/20240619-1/ad62656927ccc58b42e92bedb10133fb.jpg', '<p>Những vụ án tưởng như chỉ là tai nạn thông thường, nhưng lại là kế hoạch được chuẩn bị vô cùng tinh vi của một tổ chức trong bóng tối. Cho đến một ngày, một thành viên trong tổ chức vô tình mất mạng trong nhiệm vụ. Sự nghi hoặc bắt đầu dấy lên trong nội bộ, là các thành viên gài bẫy nhau hay có người khác đứng sau mọi chuyện?</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 1, '[{"name":"Kang Dong Won","avatar":""},{"name":"Lee Moo Saeng","avatar":""},{"name":"Lee Hyun Wook","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324180);
