INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngo-nhap-quan-mong', 'Ngộ Nhập Quân Mộng', 'Unspeakable Longing', 'https://phimimg.com/upload/vod/20240916-1/ef0f886f65f70d2fdd98e38e0eba4d72.jpg', 'https://phimimg.com/upload/vod/20240916-1/0cd470942af5c698d573688aebfc3642.jpg', '<p>Bạch Dữu Khả bất ngờ bước vào trong thế giới truyện tranh do mình tạo ra và trở thành nữ chính. Muốn trở về thực tại thì phải khiến nam chính Hứa Trạch Vũ mắc chứng sợ nữ nhân yêu mình. Bạch Dữu Khả đành phải theo đuổi Hứa Trạch Vũ nhưng dần dà lại rung động với chàng. Nhưng chuyện nào có đơn giản như vậy, số mệnh nhắm vào thanh máu của hai người và âm mưu đang lặng lẽ kéo đến...</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lâm Hân Nghi","avatar":""},{"name":"Nghiêm Tử Hiền","avatar":""},{"name":"Lý Bách Ngôn","avatar":""},{"name":"Hà Thích","avatar":""},{"name":"Vương Gia Mậu","avatar":""},{"name":"Liễu Bính Lộ","avatar":""},{"name":"Lưu Uy Châu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324180);
