INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ngo-nhap-quan-mong', 'Ngộ Nhập Quân Mộng', 'Unspeakable Longing', 'ngộ nhập quân mộng unspeakable longing lâm hân nghi nghiêm tử hiền lý bách ngôn hà thích vương gia mậu liễu bính lộ lưu uy châu ', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mat-na-chan-tinh', 'Mặt Nạ Chân Tình', 'False Face And True Feelings', 'https://phimimg.com/upload/vod/20240609-1/15734c599a94c733a9a36c6a2bb59932.jpg', 'https://phimimg.com/upload/vod/20240609-1/de24b9dfaba7df2f35013b532890c118.jpg', '<p>Diệp Nhất Phàm vốn là một chàng trai vui vẻ, nhưng sau khi cả gia đình bị tàn sát, anh đã thề sẽ trả thù và trở thành ông chủ bí ẩn, lạnh lùng, tàn bạo - Ngài Mạc. Anh tình cờ gặp được vũ công Hạ Tri Thu, một trò chơi tình yêu giữa thợ săn và con mồi cũng bắt đầu từ đây! Hạ Tri Thu từng bước cưa đổ, Diệp Nhất Phàm dần dần lún sâu, nhưng chính lúc này anh phát hiện ra thân phận thực sự của cô chính là Cố Thanh Nhan, con gái kẻ thù của anh! Đồng thời để trả thù giết cha, Cố Thanh Nhan cũng giăng bẫy, trong khi Diệp Nhất Phàm sẵn sàng chết vì tình. Hai người vốn là kẻ thù nhưng không ngừng bị cuốn vào vòng xoáy yêu hận. Đằng sau lớp mặt nạ, tình yêu đích thực trào dâng, cuối cùng cặp đôi này sẽ đi về đâu?</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 8, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hàn Đông Lâm","avatar":""},{"name":"Thôi Nhất Lương","avatar":""},{"name":"Triệu Nguyên Hữu","avatar":""},{"name":"Lý Trác Diêu","avatar":""},{"name":"Giang Hy Nhiêu","avatar":""},{"name":"Giang Vũ Giai","avatar":""},{"name":"Nhâm Vĩnh Quốc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324180);
