INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lam-hoa-diet-quy-phan-3', 'Lam Hỏa Diệt Quỷ (Phần 3)', 'Blue Exorcist (Season 3)', 'https://phimimg.com/upload/vod/20250203-1/d16209a50645e89d493224c26cc9a7e3.jpg', 'https://phimimg.com/upload/vod/20250203-1/4c2fe0a4b8a1b9fd0510c655e9cfe470.jpg', '<p>Câu truyện xoay quanh một chàng trai tên là Okumura Rin, cậu được nuôi lớn bởi một Chuyên Gia Diệt Quỷ (Exorcist) nổi tiếng tên là Fujimoto Shirou, rồi một ngày cậu chợt biết được rằng mình chính là con trai của quỷ dữ Satan, rồi số phận của cậu đứng giữa sự lựa chọn: làm con trai của quỷ hoặc là trở thành một Chuyên Gia Diệt Quỷ.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Hiroshi Kamiya","avatar":""}]', '[{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["青之驱魔师 岛根启明结社篇","青之驱魔师 雪之尽头篇","青之驱魔师 终夜篇","青之驱魔师 京都不净王篇","青之驅魔師 京都不淨王篇","青之驅魔師 島根啟明結社篇","青之驅魔師 雪之盡頭篇","青之驅魔師 終夜篇","Blue Exorcist","Ao no Exorcist","Ao no Ekusoshisuto","エクソシスト","Ao no Exorcist: Kyoto Fujouou-hen","Ao no Exorcist: Kyoto Fujō Ō-hen","Ao no Futsumashi","青の祓魔師 京都不浄王篇","青の祓魔師 島根啓明結社篇","青の祓魔師 雪ノ果篇","青の祓魔師 終夜篇","청의 엑소시스트 시마네 일루미너티편","청의 엑소시스트 시마네 일루미너티 편","청의 엑소시스트 교토 부정왕편","청의 엑소시스트 눈의 최후편","청의 엑소시스트 종야편","Blue Exorcist: Kyoto Saga","Blue Exꚛrcis♰","Blue Exꚛrcis♰: Kyoto Saga","Blue Exorcist -Shimane Illuminati Saga-","Blue Exorcist -Beyond the Snow Saga-","Blue Exorcist -The Blue Night Saga-","La