INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-hu-2024', 'Trai Hư', 'Bad Boy', 'https://phimimg.com/upload/vod/20250504-1/80f3de14c5b8ea5b5accfe1439c9203d.jpg', 'https://phimimg.com/upload/vod/20250504-1/f1df9326bc874891de0389b0ad75eccc.jpg', '<p>Trong bộ phim trần trụi về tuổi mới lớn lấy cảm hứng từ sự kiện có thật này, cây hài nọ kể lại cách anh sống sót trong trại giam trẻ vị thành niên tàn bạo nhờ vào sự dí dỏm.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Israel', 0, '[{"name":"Guy Menaster","avatar":""},{"name":"Daniel Chen","avatar":""},{"name":"Liraz Chamami","avatar":""},{"name":"Havtamo Freda","avatar":""},{"name":"Yishai Lalush","avatar":""},{"name":"Bat-Chen Sabag","avatar":""},{"name":"Neta Plotnik","avatar":""},{"name":"Ben Sultan","avatar":""},{"name":"Amjad Shawa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Bad Boy","ילד רע"]', 1784690324180);
