INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('trai-hu-2024', 'Trai Hư', 'Bad Boy', 'trai hư bad boy guy menaster daniel chen liraz chamami havtamo freda yishai lalush bat-chen sabag neta plotnik ben sultan amjad shawa bad boy ילד רע', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-yeu-tieu-hong-nuong-nguyet-hong-thien', 'Hồ Yêu Tiểu Hồng Nương: Nguyệt Hồng Thiên', 'Fox Spirit Matchmaker: Red-Moon Pact', 'https://phimimg.com/upload/vod/20240524-1/55ee9e096b3442efeb6da74e8bc3b0b4.jpg', 'https://phimimg.com/upload/vod/20240524-1/826f8f18736f9edad9791d924e6d65ed.jpg', '<p>Phim&nbsp;kể về Hồ tộc Đồ Sơn Hồng Hồng – một gia tộc hồ ly Đồ Sơn lớn mạnh. Yêu tộc Đồ Sơn được giao cho việc canh giữ cây khổ tình và gánh vác se duyên cho các cặp đôi trên khắp thế gian. Đồ Sơn Hồng Hồng (Dương Mịch) – là nữ vương của tộc Hồ Yêu đồng thời cô cũng là hồ vương được sinh ra từ cây khổ tình. Hồi còn bé, Đồ Sơn Hồng Hồng không may bị bắt, cô được cứu bởi một đạo sĩ nhưng do quá sợ hãi nên cô đã ra tay giết đạo sĩ này. Sau khi mọi chuyện sáng tỏ cô rất hối hận và từ đó cô tự giam cầm mình trong tội lỗi cho đến khi Đông Phương Nguyệt Sơ xuất hiện. Đông Phương Nguyệt Sơ (Cung Tuấn) là tộc nhân của Đông Phương linh tộc, anh được Đồ Sơn Hồng Hồng cứu lúc còn nhỏ và luôn gọi nàng Yêu Tiên Tỉ Tỉ, từ đó nảy sinh tình cảm. Đông Phương Nguyệt Sơ vì yêu Đồ Sơn Hồng Hồng mà không ngần ngại hi sinh tính mạng của mình vì nàng, điều đó đã làm cho nàng không ngừng rung động vì tấm chân tình của chàng. Ngày Đông Phương Nguyệt Sơ tỏ tình với nàng nhưng nàng lại từ chối chỉ vì những chấp niệm với đạo sĩ thủa nhỏ. Đông Phương Nguyệt Sơ đã rời khỏi Đồ Sơn quyết tâm đi tu luyện phép thuật và trở thành đạo sĩ giỏi nhất thiên hạ khiến ai cũng phải khiếp sợ khi đối mặt. Sau hàng chục năm xa cách đến khi gặp lại Đông Phương Nguyệt Sơ thì anh lại trong tình trạng sắp chết. Đồ Sơn Hồng Hồng quyết định từ bỏ đạo hạnh ngàn năm chỉ để đổi lại được gặp lại Đông Phương Nguyệt Sơ ở kiếp chuyển sinh mới. Mọi chuyện đâu có dễ dàng như vậy, liệu những biến cố nào đang chờ đợi họ?</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 9, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Mịch","avatar":""},{"name":"Cung Tuấn","avatar":""},{"name":"Quách Hiểu Đình","avatar":""},{"name":"Ngụy Triết Minh","avatar":""},{"name":"Hồ Liên Hinh","avatar":""},{"name":"Ôn Tranh Vanh","avatar":""},{"name":"Phạm Minh","avatar":""},{"name":"Lương Siêu","avatar":""},{"name":"Hoàng Chí Vĩ","avatar":""},{"name":"Lý Vũ Hạo","avatar":""},{"name":"Hồng Tiêu","avatar":""},{"name":"Phùng Tiêu Đồng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324180);
