INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nang-luc-mot-cau-chet-luon-cua-toi-qua-ba-dao-nen-vo-doi-o-di-gioi', 'Năng Lực Một Câu Chết Luôn Của Tôi Quá Bá Đạo Nên Vô Đối Ở Dị Giới', 'My Instant Death Ability Is Overpowered', 'https://phimimg.com/upload/vod/20250502-1/32469194f494409bea7637701342c2e9.jpg', 'https://phimimg.com/upload/vod/20250502-1/52c6508a2278e84d41981af22e4428c3.jpg', '<p>Cheats tối thượng? Ma thuật vô hạn? Khả năng nắm giữ mọi nguyên mẫu? Anh đây cho một hit không phải cả đám cùng chết? Học sinh cao trung Yogiri Takatou tham gia chuyến đi dã ngoại của trường nhưng vừa tỉnh dậy, trước mặt cậu đã là một con rồng đang cố làm &quot;tềnh&quot; với xe buýt tham quan của lớp, và những người duy nhất còn lại trên xe là Yogiri cùng cô bạn cùng lớp Tomochika Dannoura. Dường như các bạn học khác đã được Sion, một người phụ nữ tự nhận mình là nhà hiền triết ban tặng sức mạnh đặc biệt và trốn thoát khỏi con rồng, quẳng lại mồi-rồng là những người không nhận được bất kì sức mạnh nào. Cứ như thế, Yogiri, trong một trạng thái mơ hồ chưa kịp nhận thức chuyện gì đang diễn ra, bị ném vào vị diện song song tràn ngập hiểm nguy chờ đón. Cùng lúc đó, Sion không hề biết được cô đã chào đón thứ tồn tại khủng bố nào đến với thế giới của họ.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Koki Uchiyama","avatar":""},{"name":"Miyu Tomita","avatar":""},{"name":"Tomoko Kaneda","avatar":""},{"name":"Yui Horie","avatar":""},{"name":"Sayaka Kikuchi","avatar":""},{"name":"Kiyono Yasuno","avatar":""},{"name":"Aina Suzuki","avatar":""},{"name":"Shohei Komatsu","avatar":""},{"name":"Shogo Sakata","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["¡Mi habilidad de muerte instantánea","秒杀外挂太强了，异世界的家伙们根本就不是对手","秒杀外挂太强了，异世界的家伙们根本就不是对手。","秒杀外挂太强了异世界的家伙们根本就不是对手","秒杀外挂太强了异世界的家伙们根本就不是对手。","My.Instant.Death.Ability.Is.Overpowered","Ma capacité de mort instantanée est tellement maîtrisée que personne dans cet autre monde n’a une chance contre moi !","秒殺外掛太強了，異世界的傢伙們根本就不是對手","秒殺外掛太強了異世界的傢伙們根本就不是對手。","秒殺外掛太強了，異世界的傢伙們根本就不是對手。","秒殺外掛太強了異世界的傢伙們根本就不是對手","即死チートが最強すぎて","Sokushi Cheat ga Saikyou Sugite, Isekai no Yatsura ga Marude Aite ni Naranain desu ga.","Sokushi Chīto ga Saikyōsugite, Isekai no Yatsura ga marude Aite ni Naranain Desu ga.","Sokushi Cheat ga Saikyou Sugite, Isekai no Yatsura ga Marude Aite ni Naranaindesu ga.","Sokushi Cheat ga Saikyō Sugite, Isekai no Yatsura ga Marude Aite ni Naranaindesu ga.","Sokushi Cheat ga Saikyō Sugite, Isekai no Yatsura ga Marude Aite ni Naranain desu ga.","Sokushi Cheat","Sokushi Cheat-Pr","Sokushi Cheat Ga Saikyou Sugite","즉사 치트가 너무 최강이라","Другой мир не может противостоять силе мгновенной смерти","My Instant Death Ability Is So Overpowered, No One in This Other World Stands a Chance Against Me!","My Instant Death Ability Is So Overpowered","Năng Lực Một Câu Chết Luôn Của Tôi Quá Bá Đạo Nên Vô Đối Ở Dị Giới","即死チートが最強すぎて、異世界のやつらがまるで相手にならないんですが。"]', 1784690324180);
