INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hom-nay-co-ay-co-chut-ky-la', 'Hôm Nay Cô Ấy Có Chút Kỳ Lạ', 'She''s A Little Weird Today', 'https://phimimg.com/upload/vod/20250430-1/8cbf38129adc82a9e5425bf7260ae024.jpg', 'https://phimimg.com/upload/vod/20250430-1/aafd1b025535a4410818fdc89ce176eb.jpg', '<p>Vào đúng ngày bị mẹ ép đi xem mắt, nữ tác giả truyện tranh Trần Sơ Vận gặp gỡ Liễu Thiên, một cô gái ngoài hành tinh đến để giúp cô tìm một nửa kia hoàn hảo. Theo đánh giá của Liễu Thiên, đối tượng xem mắt Hàn Tử Ngang hoàn toàn không phù hợp với Sơ Vận. Thế là cô tìm đủ mọi cách để khiến hai người phải chia tay, nhưng nào ngờ những việc đó lại có tác dụng ngược, khiến Tử Ngang và Sơ Vận ngày càng hiểu nhau và yêu nhau sâu đậm hơn.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Huỳnh Phán Phán","avatar":""},{"name":"Châu Thiên Tiểu","avatar":""},{"name":"Lý Thị Nghiêu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["她今天有点奇怪"]', 1784690324180);
