INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-doi-cua-bach-tieu-thu-bi-tiet-lo-roi', 'Cuộc Đời Của Bạch Tiểu Thư Bị Tiết Lộ Rồi', 'Miss Bai', 'https://phimimg.com/upload/vod/20250325-1/c07bdcb01be31dc81b6183cb8eb168f2.jpg', 'https://phimimg.com/upload/vod/20250325-1/e377ca5bfd683df54b83d0efb3974407.jpg', '<p>Là quản lý cấp cao ở một công ty game, thú tiêu khiển sau giờ làm của Bạch Tư Duyệt là xem phim ngôn tình. Một ngày nọ, cô bất ngờ nhận được một trailer phim cổ trang kỳ lạ: quận chúa đanh đá và tướng quân lạnh lùng trong phim trông giống y hệt cô và Đoan Mộc Văn Vũ, giám đốc mới đến làm ở công ty. Những ngày sau đó, Tư Duyệt tiếp tục nhận được các đoạn phim có nội dung tương tự với chuyện xảy ra trong đời thực. Để ngăn kết cục bi thảm trong phim trở thành sự thật, Tư Duyệt quyết tâm tìm cách thay đổi số trời.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 11, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lưu Niệm","avatar":""},{"name":"Lê Minh Húc","avatar":""},{"name":"Trần Mộc","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["白小姐的人生被劇透了","白小姐的人生被剧透了"]', 1784690324180);
