INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truc-tam', 'Trục Tâm', 'Chasing Love', 'https://phimimg.com/upload/vod/20240919-1/c0bdc9f0414f8befb048f003f7663b56.jpg', 'https://phimimg.com/upload/vod/20240919-1/9b5880a9dd91c8c5417b1d3b3baa64be.jpg', '<p>Bị tấn công ngay tại lễ tang của cha, tiểu thư danh giá Âu Dương Nguyệt may mắn được một thành viên băng đảng tội phạm tên Tần Tế Phong cứu mạng. Sau đó, Âu Dương Nguyệt nhận Tần Tế Phong làm vệ sĩ bất chấp sự phản đội của Lương Gia Hạo, vị hôn phu của cô. Âu Dương Nguyệt không hề hay biết giữa Tế Phong và Gia Hạo vốn có mối quan hệ vô cùng phức tạp và quyết định của cô đã khơi mào một chuyện tình tay ba chỉ có thể kết thúc trong bi kịch.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hắc Trạch","avatar":""},{"name":"Từ Chẩn Chẩn","avatar":""},{"name":"Vương Tinh Vĩ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Catch Your Heart","风月不知恨","大小姐的偷心保镖","Gun and Rose","逐心"]', 1784690324180);
