INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phep-la-thu-2-o-phong-giam-so-7', 'Phép Lạ Thứ 2 Ở Phòng Giam Số 7', '2nd Miracle In Cell No. 7', 'https://phimimg.com/upload/vod/20250428-1/01a42af6c2b0b06bd91b96c2f56b1983.jpg', 'https://phimimg.com/upload/vod/20250428-1/d10c5d76a0bfe4796e77c803d34f287a.jpg', '<p>Hai năm sau cái chết oan uổng của Dodo Rozak, con gái anh – Kartika (Graciella Abigail) – vẫn chưa biết sự thật về cha mình. Cô bé sống cùng vợ chồng cai ngục Hendro (Denny Sumargo) và Linda (Agla Artalidia), những người luôn yêu thương và chăm sóc cô như con ruột. Kartika vẫn thường xuyên được đưa vào phòng giam số 7 để gặp những người bạn tù cũ của cha mình, những người luôn giữ kín bí mật về số phận thật sự của Dodo. Khi Hendro quyết định nhận nuôi Kartika, anh vấp phải sự phản đối từ cơ quan bảo trợ xã hội, dẫn đến một cuộc đấu tranh pháp lý đầy cam go. Những người bạn tù của Dodo cùng Hendro quyết tâm bảo vệ Kartika và tìm kiếm công lý cho cô bé.&nbsp;</p>', 'Full', 1, 'single', 'completed', 14, 2024, 'Vietsub', 'FHD', 'Indonesia', 0, '[{"name":"Vino G. Bastian","avatar":""},{"name":"Graciella Abigail","avatar":""},{"name":"Marsha Timothy","avatar":""},{"name":"Indro","avatar":""},{"name":"Tora Sudiro","avatar":""},{"name":"Indra Jegel","avatar":""},{"name":"Rigen Rakelna","avatar":""},{"name":"Bryan Domani","avatar":""},{"name":"Denny Sumargo","avatar":""},{"name":"Muhadkly Acho","avatar":""},{"name":"Coki Pardede","avatar":""},{"name":"Agus Kencrot","avatar":""},{"name":"Agla Artalidia","avatar":""},{"name":"Ayushita Nugraha","avatar":""},{"name":"Della Dartyan","avatar":""},{"name":"Yati Surachman","avatar":""},{"name":"Megarita","avatar":""},{"name":"Keanu Az","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5