INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('pha-chien', 'Phá Chiến', 'Break War', 'https://phimimg.com/upload/vod/20240305-1/b2fb0a42f68a20a0d585c03b660425c7.jpg', 'https://phimimg.com/upload/vod/20240305-1/2e5c4897a63b1a96e76ab017d38b50e9.jpg', '<p>Hồng Kông, thành phố an toàn nhất châu Á và cũng là trung tâm tài chính quốc tế nổi tiếng trên thế giới. Bốn giá trị cốt lõi của thành phố này được đặc trưng là &quot;Tài chính, Bất động sản, Giáo dục, Tư pháp&quot;, tạo nên biểu tượng của vị thế lẫn lộng lẫy của thủ đô quốc tế này. Mạc Vân, Phó Trưởng Cơ quan Cảnh sát Hồng Kông, trong thời gian ngắn chỉ ba năm, đã liên tục phá giải mười vụ án hóc búa tại Hồng Kông, trở thành một nhà điều tra tài năng không thể phủ nhận. Lần này, anh phải đối mặt với thách thức từ tổ chức khủng bố mang tên &quot;FREE&quot;, họ đang đề xuất một cuộc tấn công vào bốn giá trị cốt lõi của Hồng Kông.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Francis Ng","avatar":""},{"name":"Simon Yam","avatar":""},{"name":"Cheng Yuanyuan","avatar":""},{"name":"Michael Tong","avatar":""},{"name":"Gigi Lau","avatar":""},{"name":"Angus Yeung","avatar":""},{"name":"Cheuk-lap Hung","avatar":""},{"name":"Lam Suet","avatar":""},{"name":"Felix Lok Ying-Kwan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324180);
