INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dich-nhan-kiet-thong-thien-nhan-ngau', 'Địch Nhân Kiệt Thông Thiên Nhân Ngẫu', 'The Mystery Of Humanoid Puppet', 'https://phimimg.com/upload/vod/20240719-1/6ca74096951861aa44454e4998e7aced.jpg', 'https://phimimg.com/upload/vod/20240719-1/2e3e50c7d820f8d41eae05eeefc5f675.jpg', '<p>Sau một trận hỏa hoạn kỳ lạ tại hành cung Lạc Dương, nhiều sự việc khó tin liên tiếp xảy ra: Thuật điều khiển con rối kỳ bí, thần mộc Côn Lôn bị đóng băng nghìn năm, vụ án mạng kinh hoàng đẫm máu, và những vệ sĩ Mai Hoa Ảnh Vệ bí ẩn của Võ Tắc Thiên. Bất ngờ, hai Võ Tắc Thiên xuất hiện cùng lúc trên thế gian, một loạt vụ án huyền bí liên tiếp nổi lên. Hãy xem Địch Nhân Kiệt làm thế nào để từng bước vén màn và khám phá âm mưu kinh thiên động địa đang ẩn giấu.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"郭品超","avatar":""},{"name":"Kimmy Tong Fei","avatar":""},{"name":"Ken Lok Tat-Wah","avatar":""},{"name":"黄一晗","avatar":""},{"name":"Zhang Mingming","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '[]', 1784690324180);
