INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-manh-ghep-cam-xuc-2', 'Những Mảnh Ghép Cảm Xúc 2', 'Inside Out 2', 'https://phimimg.com/upload/vod/20240820-1/f8da252be95d197b851f0932084a106d.jpg', 'https://phimimg.com/upload/vod/20240820-1/5e2380f7a7abe200ebbe8b3cc5fc04f0.jpg', '<p>Những Mảnh Ghép Cảm Xúc 2 sẽ quay trở lại phần tâm trí mới của cô bé thiếu niên Riley. Một ngày, trụ sở chính đột ngột bị phá hủy để nhường chỗ cho một thứ hoàn toàn mới: Một cảm xúc mới! Vui Vẻ, Buồn Bã, Giận Dữ, Sợ Hãi và Chán Ghét phải &quot;chào đón&quot; sự xuất hiện của một loại cảm xúc mới là Lo Âu. Và có vẻ như cô ấy không chỉ xuất hiện một mình.</p>', 'Full', 1, 'hoathinh', 'completed', 6, 2024, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 1, '[{"name":"Amy Poehler","avatar":""},{"name":"Maya Hawke","avatar":""},{"name":"Kensington Tallman","avatar":""},{"name":"Liza Lapira","avatar":""},{"name":"Phyllis Smith","avatar":""},{"name":"Lewis Black","avatar":""},{"name":"Tony Hale","avatar":""},{"name":"Ayo Edebiri","avatar":""},{"name":"Adèle Exarchopoulos","avatar":""},{"name":"Lilimar","avatar":""},{"name":"Grace Lu","avatar":""},{"name":"Sumayyah Nuriddin-Green","avatar":""},{"name":"Diane Lane","avatar":""},{"name":"Kyle MacLachlan","avatar":""},{"name":"Paul Walter Hauser","avatar":""},{"name":"Yvette Nicole Brown","avatar":""},{"name":"Ron Funche","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '[]', 1784690324180);
