INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thanh-guom-diet-quy-phan-5-dai-tru-dac-huan', 'Thanh Gươm Diệt Quỷ (Phần 5) (Đại Trụ Đặc Huấn)', 'Demon Slayer (Season 5) (Hashira Training Arc)', 'https://phimimg.com/upload/vod/20240514-1/067d03e151d819be3d3d60f2b1eaea42.jpg', 'https://phimimg.com/upload/vod/20250427-1/f6a0dabb17cd90e280bf8543b9089d8f.jpg', '<p>Tanjiro đến gặp Nham Trụ Himejima Gyoumei, người sẽ huấn luyện cậu chuẩn bị cho các trận chiến sắp tới. Quá trình đào tạo để trở thành Trụ Cột tương lai của Quân Đoàn Diệt Quỷ vô cùng căng thẳng và khắt khe. Có được sự chấp thuận của Himejima dường như là điều không thể, nhưng Tanjiro sẽ không bỏ cuộc! Trong khi đó, Muzan vẫn đang tiếp tục săn lùng Nezuko và Ubuyashiki.</p>', 'Hoàn Tất (8/8)', 8, 'hoathinh', 'completed', 5, 2024, 'Vietsub + Lồng Tiếng', 'FHD', 'Nhật Bản', 0, '[{"name":"Natsuki Hanae","avatar":""},{"name":"Hiro Shimono","avatar":""},{"name":"Akari Kito","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324180);
