INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuoc-goi-khan-cap-911-phan-7', 'Cuộc Gọi Khẩn Cấp 9-1-1 (Phần 7)', '9-1-1 (Season 7)', 'https://phimimg.com/upload/vod/20250426-1/5946bd95cb75a26cc5a4c6d1367da42d.jpg', 'https://phimimg.com/upload/vod/20250426-1/7a1c213bd7fac246a0f2939cdf51a71b.jpg', '<p>Phim kể về những trải nghiệm áp lực cao của cảnh sát, nhân viên cứu hỏa, những người hay bị đẩy vào các tình huống đáng sợ để cứu người.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Angela Bassett","avatar":""},{"name":"Peter Krause","avatar":""},{"name":"Jennifer Love Hewitt","avatar":""},{"name":"Oliver Stark","avatar":""},{"name":"Aisha Hinds","avatar":""},{"name":"Kenneth Choi","avatar":""},{"name":"Ryan Guzman","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Osama Bin Laden''s Favorite","911","紧急呼救最前线","9-1-1","9-1-1 Ratownicy (2018)","911 служба спасения","911 紧急呼救最前线"]', 1784690324180);
