INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguy-trang-cua-co-ay', 'Ngụy Trang Của Cô Ấy', 'Her Disguise', 'https://phimimg.com/upload/vod/20250424-1/1fc5bb1790f72081b61176126d3cab07.jpg', 'https://phimimg.com/upload/vod/20250424-1/460a9f846433ea17c13d8ac432a2a850.jpg', '<p>Để trả thù cho một người bạn thân đã mất, sinh viên y khoa Lâm Mạn Ca tiếp cận Lộ Quang Hạc và trở thành vị hôn thê của anh. Ban đầu, cô nghi ngờ kẻ đứng sau cái chết của bạn mình là Lộ Hạo Nhiên, em trai của Quang Hạc. Nhưng sau một thời gian ở nhà họ Lộ, Mạn Ca phát hiện Hạo Nhiên không phải người hung tàn, ngang ngược như vẻ bề ngoài và cô dần dần rơi vào lưới tình.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Nghiệp Minh","avatar":""},{"name":"Phùng Uyển Hạ","avatar":""},{"name":"Kim Hạo Bằng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["她的伪装"]', 1784690324180);
