INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-rung-dong-vi-anh', 'Đừng Rung Động Vì Anh', 'Everyone Loves Me', 'https://phimimg.com/upload/vod/20240309-1/4e48883be3a922c5550b4293b83ef4d1.jpg', 'https://phimimg.com/upload/vod/20240309-1/cd65e5930a928cbda20fb27a02d6c533.jpg', '<p>Vào ngày từ chức, Nhạc Thiên Linh (do Châu Dã thủ vai) lướt ngang qua lãnh đạo mới nhậm chức của Phòng kinh doanh số 9, đồng thời là người cô luôn thầm thương trộm nhớ, Cố Tầm (do Lâm Nhất thủ vai). Vì lý do này, cô không ngần ngại quay lại công ty, mạnh dạn theo đuổi tình yêu. Dù vậy, Cố Tầm lại đối xử lạnh lùng, thậm chí còn từ chối lời tỏ tình của Nhạc Thiên Linh trước mặt toàn thể giáo viên và học sinh trong trường… Thì ra Cố Tầm đã sớm phải lòng người bạn qua mạng ngổ ngáo lại phóng khoáng “Quẩy Nếp Xoắn. Nhưng ai có thể ngờ rằng Quẩy Nếp Xoắn lại chính là Nhạc Thiên Linh. Cuối cùng, sau khi biết được sự thật, Cố Tầm đã phải bắt đầu cuộc theo đuổi ngược chiều vừa hài hước vừa cảm động...&nbsp;</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 11, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Châu Dã","avatar":""},{"name":"Lâm Nhất","avatar":""},{"name":"Thang Mộng Giai","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324180);
