INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('doi-khi-toi-nghi-ve-cai-chet', 'Đôi khi tôi nghĩ về cái chết', 'Sometimes I Think About Dying', 'https://phimimg.com/upload/vod/20250424-1/48a92f0e260ffc437803adaaee7c6109.jpg', 'https://phimimg.com/upload/vod/20250424-1/c61e2a61e25ba5f3ffb50f03f8795cb4.jpg', '<p>Fran thích nghĩ về cái chết. Điều đó mang lại cảm giác cho cuộc sống tẻ nhạt của cô. Khi cô khiến chàng trai mới ở chỗ làm bật cười, mọi thứ bắt đầu thay đổi: một buổi hẹn, một miếng bánh, một cuộc trò chuyện, một tia hy vọng. Thứ duy nhất cản trở họ chính là bản thân Fran.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Daisy Ridley","avatar":""},{"name":"Dave Merheje","avatar":""},{"name":"Parvesh Cheena","avatar":""},{"name":"Marcia DeBonis","avatar":""},{"name":"Megan Stalter","avatar":""},{"name":"Brittany O''Grady","avatar":""},{"name":"Bree Elrod","avatar":""},{"name":"Lauren Beveridge","avatar":""},{"name":"Ayanna Berkshire","avatar":""},{"name":"Sean Tarjyoto","avatar":""},{"name":"Jeb Berrier","avatar":""},{"name":"Rich Hinz","avatar":""},{"name":"June Eisler","avatar":""},{"name":"Audrey Blanchet","avatar":""},{"name":"Nicole Marie Green","avatar":""},{"name":"Treasure Lunan","avatar":""},{"name":"Andy","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["SITAD","Às Vezes Quero Sumir","A Veces Pienso En Morir","당신은 죽음을 상상하나요?","A veces pienso en desaparecer","La vida soñada de miss Fran","時々、私は考える","Понякога си мисля за смъртта","Sometimes I Think About Dying"]', 1784690324180);
