INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('doi-khi-toi-nghi-ve-cai-chet', 'Đôi khi tôi nghĩ về cái chết', 'Sometimes I Think About Dying', 'đôi khi tôi nghĩ về cái chết sometimes i think about dying daisy ridley dave merheje parvesh cheena marcia debonis megan stalter brittany o''grady bree elrod lauren beveridge ayanna berkshire sean tarjyoto jeb berrier rich hinz june eisler audrey blanchet nicole marie green treasure lunan andy sitad às vezes quero sumir a veces pienso en morir 당신은 죽음을 상상하나요? a veces pienso en desaparecer la vida soñada de miss fran 時々、私は考える понякога си мисля за смъртта sometimes i think about dying', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phu-quan-dai-nhan-dung-so-thiep', 'Phu Quân Đại Nhân Đừng Sợ Thiếp', 'The Expect Love', 'https://phimimg.com/upload/vod/20250424-1/c5b88830640de0efc112a7ebf8af705f.jpg', 'https://phimimg.com/upload/vod/20250424-1/35700f8ff24481ca4f5aa430a1b4a073.jpg', '<p>Sau một tai nạn, nữ sinh viên ngành hóa sinh Đỗ Nhược Phi bị cuốn vào thế giới của quyển tiểu thuyết mình đang đọc và trở thành vợ của Thị lang Hình bộ Tuân Trường Hạo. Mặc dù tư duy và phong cách hiện đại của Nhược Phi hoàn toàn không phù hợp với thời cổ đại, cô lại thấy mình vô cùng ăn ý với Trường Hạo. Thuở ban đầu chỉ kết hôn do mai mối, nhưng trong quá trình cùng nhau phá án, dần dà giữa Nhược Phi và người chồng trong sách đã nảy sinh tình yêu chân thành.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Trương Tử Ninh","avatar":""},{"name":"Lý Cửu Lâm","avatar":""},{"name":"Chu Mạt Nhan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["夫人，你不对劲","夫君大人別怕我","The Expect Love","夫君大人别怕我"]', 1784690324180);
