INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-sinh-thanh-quai-vat', 'Hồi Sinh Thành Quái Vật', 'Re:Monster', 'https://phimimg.com/upload/vod/20240402-1/5891151ef46c22485f1addc4d50267e0.jpg', 'https://phimimg.com/upload/vod/20240402-1/efd7e5fd2496fc03f6aedd8714b7edae.jpg', '<p>Gob-Rou đã bất ngờ bị đâm bởi một kẻ bám đuôi, khi tỉnh dậy thì anh thấy mình đã chuyển sinh thành Goblin yếu nhất. Nhờ Năng Lực Thôn Phệ cho phép càng ăn nhiều thì càng mạnh, anh đã tiến hóa phi thường, trở thành thủ lĩnh của quần thể Goblin... Tại dị giới nơi mạnh được yếu thua, Gob-Rou sẽ cùng những người bạn tài năng của mình vươn lên thì dưới đáy! Câu chuyện chuyển sinh sang thế giới huyễn tưởng sẽ bùng nổ!</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2024, 'Vietsub', 'HD', 'Nhật Bản', 0, '[{"name":"Sato Takuya","avatar":""},{"name":"Hosoda Kenta","avatar":""},{"name":"Kakuma Ai","avatar":""},{"name":"Ueda Kana","avatar":""},{"name":"Tobita Nobuo","avatar":""},{"name":"Yamane Aya","avatar":""},{"name":"Omori Nichika","avatar":""},{"name":"Mai Kanno","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"}]', '[]', 1784690324180);
