INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('du-quan-tuong-nhan', 'Dữ Quân Tương Nhận', 'Blade''s Dance With You', 'https://phimimg.com/upload/vod/20240825-1/494616d89342d75f7e37ee3e495a8c4c.jpg', 'https://phimimg.com/upload/vod/20240825-1/794f76fe03fda2c0f0efb7b1fd960c44.jpg', '<p>Sát thủ Triệu Tiểu Nhẫn nhận nhiệm vụ ám sát Quân Mạch của sơn trang Mạt Lị. Để thực hiện nhiệm vụ, nàng đóng giả thành tân nương của Quân Mạch. Vì đều có động cơ riêng nên trước mặt người khác cả hai luôn giả vờ tình tứ, nhưng rồi dần dà thực sự phải lòng nhau lúc nào không hay.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hồng Tiêu","avatar":""},{"name":"Dương Trạch","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324180);
