INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuon-nhat-ky-cua-trieu-tieu-thu', 'Cuốn Nhật Ký Của Triệu Tiểu Thư', 'Diary Of Miss Zhao', 'https://phimimg.com/upload/vod/20250423-1/da95042ecb781b5e674c41deb4da0573.jpg', 'https://phimimg.com/upload/vod/20250423-1/0ce86bcf0bd33a3ac29f50f131fc82dc.jpg', '<p>Chuyên gia phục chế di vật Lưu Viện được giao nhiệm vụ khôi phục một cuốn nhật ký từ thời Dân quốc của một cô gái tên Triệu Đăng Mạn. Cộng sự của cô trong dự án này tình cờ lại là người yêu cũ đã chia tay được năm năm, Vương Trạch. Quá trình ghép lại hàng trăm mảnh nhật ký không chỉ hé mở chuyện đời phi thường của Triệu tiểu thư mà còn giúp Lưu Viện và Vương Trạch hàn gắn tình cảm, nối lại duyên xưa.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Mộc Thần","avatar":""},{"name":"Cát Thu Cốc","avatar":""},{"name":"Mã Giai Oánh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["趙小姐的日記","Diary of Miss Zhao","赵小姐的日记"]', 1784690324180);
