INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cuon-nhat-ky-cua-trieu-tieu-thu', 'Cuốn Nhật Ký Của Triệu Tiểu Thư', 'Diary Of Miss Zhao', 'cuốn nhật ký của triệu tiểu thư diary of miss zhao lý mộc thần cát thu cốc mã giai oánh 趙小姐的日記 diary of miss zhao 赵小姐的日记', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-nghich', 'Võ Nghịch', 'Martial Inverse', 'https://phimimg.com/upload/vod/20250224-1/b05e628bae3fcf6e2be424d1737bcc0a.jpg', 'https://phimimg.com/upload/vod/20250224-1/f7606401bfef85a5570c6d36c2dbbc61.jpg', '<p>Bộ phim kể đại thiếu gia Phong Hạo của Phong gia, người có thể chất đỉnh nóc kịch trần bay phấp phới thế nhưng lại bị đánh giá là một kẻ tên phế không thể nào phế hơn, đến mức cô nương hắn thích cũng phải quay xe. Đúng lúc ấy, một người xuất hiện, chính là vị cứu tinh của đời hắn, người đã cho hắn một cơ hội nghịch thiên cải mệnh. Vì thể chất của hắn nên hắn chỉ cần tu luyện là hắn có thể trở thành cao thủ tuyệt thế. Nhưng nếu thất bại thì sẽ chết. Ban đầu được người chỉ dạy tu luyện, sau đó nhờ có thiên phú có sẵn và các cơ duyên gặp được, hắn tu luyện với tốc độ bàn thờ, trở thành Hư Vô chi chủ.</p>', 'Hoàn Tất (30/30)', 30, 'hoathinh', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Wu Ni","武逆","Wuni","Marcial Renegado","Inverse Martial","Martial Rebel","Martial Reversal"]', 1784690324180);
