INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('vo-nghich', 'Võ Nghịch', 'Martial Inverse', 'võ nghịch martial inverse  wu ni 武逆 wuni marcial renegado inverse martial martial rebel martial reversal', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vo-luyen-dinh-phong-3d', 'Võ Luyện Đỉnh Phong 3D', 'Martial Arts Peak', 'https://phimimg.com/upload/vod/20250224-1/dae5dd2ef5e48a06d048947167fc573e.jpg', 'https://phimimg.com/upload/vod/20250224-1/c888f37c829598f446f7ef8fb7a430b7.jpg', '<p>Câu chuyện về anh chàng Dương Khai, một cậu thiếu niên không có thiên phú gì nổi trội và chỉ được làm đệ tử thí luyện, đồng thời ôm luôn chân quét dọn cho Lăng Tiêu Các tại Trung Đô đó. Ngoài ra, trong 3 năm tu luyện mà không đạt được thành tựu gì nổi bật thì khả năng rất cao là Dương Khai sẽ bị cho out khỏi tông môn ngay lập tức. Đứng trước những bế tắc đó, Dương Khai chỉ biết chăm chỉ tập luyện và hy vọng có một chút thành công cho cậu. Nhưng tình cờ một ngày kia, Dương Khai đã gặp một chiếc gối đá hết sức bí ẩn, chiếc gối đá đã giúp cậu có được những kỹ năng chiến đấu cao cấp, đồng thời tiếp thêm rất nhiều động lực tu luyện cho cậu. Nhờ vậy mà Dương Khai đã dần dần khẳng định được bản thân tại Trung Đô. Cùng với chiến hữu Tô Nhan, họ đã đạt được truyền thừa với một bộ công pháp tu luyện rất thần kỳ. Từ đó mà Dương Khai đã tiếp nối và xây dựng nên giai thoại về võ luyện đỉnh phong mà chúng ta đang theo dõi.</p>', 'Hoàn Tất (48/48)', 48, 'hoathinh', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324180);
