INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('than-dao-de-ton', 'Thần Đạo Đế Tôn', 'Divine Lord of the Heavens', 'https://phimimg.com/upload/vod/20250219-1/0de3bfce7ea1a586d1cf1244eda49fed.jpg', 'https://phimimg.com/upload/vod/20250219-1/7d06e4b78d0aabefda01bde76ca34c47.jpg', '<p>Thiếu niên Tần Dương tố chất phi phàm, sở hữu &quot;Tinh Môn&quot; - một thần khí tu luyện mà ai cũng ao ước có được. Tuy nhiên, may mắn này của cậu đã bị người ta cướp mất chỉ trong một đêm. Lúc cận kề cái chết, bảo vật tối cao &quot;Phong Thần Châu&quot; ở trong người Tần Dương bỗng nhiên được kích hoạt. Nó đã giúp cậu khôi phục ký ức của chín kiếp trước và được tái sinh một lần nữa. Cùng lúc đó, gia tộc của cậu rơi vào một cuộc khủng hoảng chưa từng có. Tần Dương phải một mình đối mặt với vô vàn thách thức, dùng kinh nghiệm và kiến thức đã tích luỹ trong chín kiếp để vượt qua khó khăn. Tuy nhiên, những kẻ mưu mô vẫn dí nhà cậu, để bảo vệ những người cậu yêu thương, Tần Dương quyết định tranh đấu đến cùng.</p>', 'Hoàn Tất (48/48)', 48, 'hoathinh', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Shendao Dizun","Shendao Di Zun","Shen Dao Di Zun","ShendaoDizun","神道帝尊","Divine Dao Emperor","Shinto Emperor","Shéndào Dì Zūn","Emperador Supremo del Camino Divino","Divine Lord of the Heavens","The Lord of Heaven"]', 1784690324180);
