INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-em-anh-muon-gi', 'Hỏi Em Anh Muốn Gì', 'Ask Me What You Want', 'https://phimimg.com/upload/vod/20250422-1/bac8515ae01197630f17d87fda69e66f.jpg', 'https://phimimg.com/upload/vod/20250422-1/fc9ff6cd77b807c8ae52ca44b2beaa6a.jpg', '<p>Sau cái chết của cha mình, Eric Zimmerman đến Tây Ban Nha để giám sát các chi nhánh của công ty. Tại Madrid, anh đem lòng yêu Judith và cả hai bước vào một mối quan hệ đầy đam mê, nóng bỏng và khám phá. Tuy nhiên, Eric lo sợ rằng bí mật của anh có thể chấm dứt mối quan hệ này.</p>', 'Full', 1, 'single', 'completed', 14, 2024, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Gabriela Andrada","avatar":""},{"name":"Mario Ermito","avatar":""},{"name":"Celia Freijeiro","avatar":""},{"name":"David Solans","avatar":""},{"name":"Alba Ribas","avatar":""},{"name":"Joel Bosqued","avatar":""},{"name":"Alicia Bercan","avatar":""},{"name":"Anna Karinvinge","avatar":""},{"name":"Fernando Oyagüez","avatar":""},{"name":"Paco Tous","avatar":""},{"name":"Adriana Fornés","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["告诉我你想要什么","Скажи мне чего ты хочешь","Ask Me What You Want","Ты только попроси","Pídeme lo que quieras"]', 1784690324180);
