INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dau-pha-thuong-khung-3-tru-gian-diet-ac', 'Đấu Phá Thương Khung 3: Trừ Gian Diệt Ác', 'Fights Break Sphere 3', 'https://phimimg.com/upload/vod/20250421-1/3cc0bba6829dddb6298853026e9a87eb.jpg', 'https://phimimg.com/upload/vod/20250421-1/d3841ec78cc50b6ad419e8c4ace621d8.jpg', '<p>Tiêu Viêm (do Mã Bá Khiên thủ vai) và Dược Lão (Cao Thự Quang thủ vai) sau khi hóa giải được cuộc đại chiến giữa tộc Xà Nhân và con người, đã cùng Thanh Lân (do Hoàng Văn thủ vai) và Mục Lực (do Lý Cửu Tiêu thủ vai) bước vào hành trình tu luyện, không ngừng nâng cao thực lực. Mục tiêu của họ là giành chiến thắng trong cuộc ước hẹn ba năm với Nạp Lan Yên Nhiên (do Cận Dương Dương thủ vai) – đại đệ tử của Vân Lam Tông. Trên đường đến sa mạc Tagore, Thanh Lân bất ngờ bị bắt cóc. Để cứu cô, nhóm Tiêu Viêm đã kết giao với Băng Hoàng Hải Ba Đông – một cao thủ vang danh một thời, và cùng nhau tiến vào Xích Diêm Thành. Trong thành phố hỗn loạn và kỳ quái ấy, một bàn tay đen tối từ trong bóng tối dần lộ diện, âm mưu thâu tóm tất cả. Qua hành trình điều tra, Tiêu Viêm còn dần khám phá ra sự thật về cái chết của mẹ mình thuở nhỏ...</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Victor Ma","avatar":""},{"name":"Li Jiuxiao","avatar":""},{"name":"Gao Shuguang","avatar":""},{"name":"Jiang Wu","avatar":""},{"name":"Hu Jing","avatar":""},{"name":"Zhang Hanyu","avatar":""},{"name":"Wen Huang","avatar":""},{"name":"Nita Xia","avatar":""},{"name":"Dong Jingchuan","avatar":""},{"name":"Jiang Zhuojun","avatar":""},{"name":"Jin Yangyang","avatar":""},{"name":"Xu Kelong","avatar":""},{"name":"Guo Yiqian","avatar":""},{"name":"Yu Yue","avatar":""},{"name":"Dai Xiangyu","avatar":""},{"name":"Li Mengnan","avatar":""},{"name":"Xing Hanqing","avatar":""},{"name":"Ai Liya","avatar":""}]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Fights to Break the Sphere 3: Eliminate Evil","Fights Break Sphere 3","斗破蒼穹·除惡","斗破苍穹3: 除恶","斗破苍穹·除恶","Dòu Pò Cāngqióng·Chú È","Dou Po Cangqiong·Chu E","Dou Po Cangqiong 3: Chu E","Dou Po Cang Qiong 3: Chu E","Battle Through the Heavens 3 : The Origin","斗破苍穹3：除恶"]', 1784690324180);
