INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dau-pha-thuong-khung-3-tru-gian-diet-ac', 'Đấu Phá Thương Khung 3: Trừ Gian Diệt Ác', 'Fights Break Sphere 3', 'đấu phá thương khung 3: trừ gian diệt ác fights break sphere 3 victor ma li jiuxiao gao shuguang jiang wu hu jing zhang hanyu wen huang nita xia dong jingchuan jiang zhuojun jin yangyang xu kelong guo yiqian yu yue dai xiangyu li mengnan xing hanqing ai liya fights to break the sphere 3: eliminate evil fights break sphere 3 斗破蒼穹·除惡 斗破苍穹3: 除恶 斗破苍穹·除恶 dòu pò cāngqióng·chú è dou po cangqiong·chu e dou po cangqiong 3: chu e dou po cang qiong 3: chu e battle through the heavens 3 : the origin 斗破苍穹3：除恶', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-gai-va-cay-kim', 'Cô Gái và Cây Kim', 'The Girl with the Needle', 'https://phimimg.com/upload/vod/20250421-1/e7773c0a3cdf783d672cdca85518662f.jpg', 'https://phimimg.com/upload/vod/20250421-1/6550f37dd8f6ad1f8b1bbe96c8b240df.jpg', '<p>The Girl with the Needle là một bộ phim chính kịch đầy ám ảnh, lấy bối cảnh Copenhagen sau Thế chiến thứ nhất – nơi cuộc sống còn ngổn ngang trong khói bụi hậu chiến. Trong lúc vật lộn với cuộc sống sau khi mất việc, một cô gái trẻ đang mang thai được một người phụ nữ lớn tuổi, quyến rũ và bí ẩn cưu mang. Bà đưa cô vào làm việc trong một &quot;trung tâm nhận con nuôi&quot; bí mật – nơi che giấu nhiều điều uẩn khúc đằng sau vẻ ngoài nhân đạo. Giữa hai người phụ nữ dần hình thành một mối quan hệ gắn bó, vượt lên sự chênh lệch về tuổi tác và hoàn cảnh. Tuy nhiên, một phát hiện bất ngờ đã phá vỡ tất cả – phơi bày sự thật tàn nhẫn và buộc cả hai phải đối mặt với lương tri, tình mẫu tử và những lựa chọn không thể quay đầu.</p>', 'Full', 1, 'single', 'completed', 26, 2024, 'Vietsub', 'FHD', 'Đan Mạch', 0, '[{"name":"Vic Carmen Sonne","avatar":""},{"name":"Trine Dyrholm","avatar":""},{"name":"Besir Zeciri","avatar":""},{"name":"Joachim Fjelstrup","avatar":""},{"name":"Tessa Hoder","avatar":""},{"name":"Ava Knox Martin","avatar":""},{"name":"Ari Alexander","avatar":""},{"name":"Søren Sætter-Lassen","avatar":""},{"name":"Magnus von Horn","avatar":""},{"name":"Anna Terpiłowska","avatar":""},{"name":"Dan Jakobsen","avatar":""},{"name":"Anna Tulestedt","avatar":""},{"name":"Benedikte Hansen","avatar":""},{"name":"Monika Kępka","avatar":""},{"name":"Maciej Berezowski","avatar":""},{"name":"Nela Ła","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["La Jeune Femme à l''aiguille","藏針女子","A Rapariga da Agulha","Pigen med nålen"]', 1784690324180);
