INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('phi-vu-nghin-can', 'Phi Vụ Nghìn Cân', 'Hitpig!', 'https://phimimg.com/upload/vod/20250420-1/6b59d5939a806506f9af30f4d5028230.jpg', 'https://phimimg.com/upload/vod/20250420-1/7db950599256bf4dc80233da04d24a6b.jpg', '<p>Câu chuyện xoay quanh chú heo Quý Hợi chuyên nghề tìm kiếm thú đi lạc trả về cho chủ. Mọi chuyện vẫn diễn ra êm đềm cho đến ngày Quý Hợi nhận lời ông chủ gánh xiếc đi tìm bé voi Dưa Mắm.</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Canada', 1, '[{"name":"Jason Sudeikis","avatar":""},{"name":"Lilly Singh","avatar":""},{"name":"Rainn Wilson","avatar":""},{"name":"Anitta","avatar":""},{"name":"Hannah Gadsby","avatar":""},{"name":"RuPaul","avatar":""},{"name":"Charlie Adler","avatar":""},{"name":"Flavor Flav","avatar":""},{"name":"Lorraine Ashbourne","avatar":""},{"name":"Andy Serkis","avatar":""},{"name":"Shelby Young","avatar":""},{"name":"Dave Rosenbaum","avatar":""},{"name":"Isabella Summers","avatar":""},{"name":"Dennis Leonard","avatar":""},{"name":"Rory Kardos-Ivess","avatar":""},{"name":"Aislinn Kardos","avatar":""},{"name":"Larissa Gallagher","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Skotgrís!","豬排特務","Hitpig!"]', 1784690324180);
