INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('venom-keo-cuoi', 'Venom: Kèo Cuối', 'Venom: The Last Dance', 'https://phimimg.com/upload/vod/20250420-1/831e394435dfd36bedad54d79d1884b5.jpg', 'https://phimimg.com/upload/vod/20250420-1/585fe9d01af1aa30a1051920e7e5bb02.jpg', '<p>Đây là phần phim cuối cùng và hoành tráng nhất về cặp đôi Venom và Eddie Brock (Tom Hardy). Sau khi dịch chuyển từ Vũ trụ Marvel trong ‘Spider-man: No way home’ (2021) trở về thực tại, Eddie Brock giờ đây cùng Venom sẽ phải đối mặt với ác thần Knull hùng mạnh - kẻ tạo ra cả chủng tộc Symbiote và những thế lực đang rình rập khác. Cặp đôi Eddie và Venom sẽ phải đưa ra lựa quyết định khốc liệt để hạ màn kèo cuối này.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Âu Mỹ', 1, '[{"name":"Tom Hardy","avatar":""},{"name":"Chiwetel Ejiofor","avatar":""},{"name":"Juno Temple","avatar":""},{"name":"Rhys Ifans","avatar":""},{"name":"Stephen Graham","avatar":""},{"name":"Peggy Lu","avatar":""},{"name":"Clark Backo","avatar":""},{"name":"Alanna Ubach","avatar":""},{"name":"Cristo Fernández","avatar":""},{"name":"Jared Abrahamson","avatar":""},{"name":"Hala Finley","avatar":""},{"name":"Dash McCloud","avatar":""},{"name":"Andy Serkis","avatar":""},{"name":"Reid Scott","avatar":""},{"name":"Jack Brady","avatar":""},{"name":"Ivo Nandi","avatar":""},{"name":"Jake Allyn","avatar":""},{"name":"Otis Winston","avatar":""},{"name":"Jacob Tomur","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244