INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-trang-ben-cua-so', 'Ánh Trăng Bên Cửa Sổ', 'Out of Order', 'https://phimimg.com/upload/vod/20250420-1/cd0a5edb8353c679c50a905ca02c36c1.jpg', 'https://phimimg.com/upload/vod/20250420-1/31b6917f23b8c5133aa78f63dc620a24.jpg', '<p>Một luật sư danh tiếng gặp rắc rối khi một xác chết bất ngờ rơi xuống trong lúc đang gặp người tình. Những lời nói dối nhằm che đậy sự việc lại gây ra hàng loạt tình huống oái oăm. Khi nhiều nhân vật bí ẩn xuất hiện, mọi chuyện càng rối ren hơn. Phim là một chuỗi tình huống hài hước, bất ngờ với nhiều cú twist khó lường.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Kris Phillips","avatar":""},{"name":"Zuo Lingfeng","avatar":""},{"name":"Fu Jing","avatar":""},{"name":"Don Lee","avatar":""},{"name":"Song Xiaobao","avatar":""},{"name":"Huang Xiaolei","avatar":""},{"name":"Cailun Huang","avatar":""},{"name":"Shi Ce","avatar":""},{"name":"Du Xiaoyu","avatar":""},{"name":"Xu Juncong","avatar":""},{"name":"Bu Yu","avatar":""},{"name":"Zhou Dayong","avatar":""},{"name":"Zhang Baiqiao","avatar":""},{"name":"Liu Tong","avatar":""},{"name":"Liu Jia","avatar":""},{"name":"Clara Lee","avatar":""},{"name":"Jia Zhangke","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Out of Order","窗前明月，咣！"]', 1784690324180);
