INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lego-ninjago-nhung-con-rong-troi-day-phan-2', 'LEGO Ninjago: Những Con Rồng Trỗi Dậy (Phần 2)', 'LEGO Ninjago: Dragons Rising (Season 2)', 'https://phimimg.com/upload/vod/20241224-1/64189d87cf84a938cadd4c0ba18ba9b5.jpg', 'https://phimimg.com/upload/vod/20250419-1/df2adf9e8047ac6d37e5e1d394622be8.jpg', '<p>Hai thiếu niên đến từ hai thế giới khác nhau sử dụng sức mạnh Ninja mới được phát hiện để bảo vệ rồng khỏi những kẻ hung ác muốn sử dụng sinh khí cho mục đích xấu xa.</p>', 'Hoàn Tất (20/20)', 20, 'hoathinh', 'completed', 6, 2024, 'Vietsub + Lồng Tiếng + Thuyết Minh', 'FHD', 'Canada', 0, '[{"name":"Sam Vincent","avatar":""},{"name":"Deven Mack","avatar":""},{"name":"Kelly Metzger","avatar":""},{"name":"Vincent Tong","avatar":""},{"name":"Kazumi Evans","avatar":""}]', '[{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["LEGO Ninjago: Ascenção dos Dragões","乐高幻影忍者：神龙崛起","乐高幻影忍者第17季","乐高幻影忍者第18季","לגו נינג''גו עליית הדרקונים","LEGO 닌자고: 드래곤 라이징","레고 닌자고: 드래곤 라이징","New 닌자고 드래곤 라이징","樂高旋風忍者：猛龍崛起","Ніндзяґо: Повстання драконів","Ninjago: United","Ninjago: Dragons Rising","LEGO Ninjago: Dragons Rising - The Elemental Mechs","LEGO Ninjago: Dragons Rising"]', 1784690324180);
