INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('lego-ninjago-nhung-con-rong-troi-day-phan-2', 'LEGO Ninjago: Những Con Rồng Trỗi Dậy (Phần 2)', 'LEGO Ninjago: Dragons Rising (Season 2)', 'lego ninjago: những con rồng trỗi dậy (phần 2) lego ninjago: dragons rising (season 2) sam vincent deven mack kelly metzger vincent tong kazumi evans lego ninjago: ascenção dos dragões 乐高幻影忍者：神龙崛起 乐高幻影忍者第17季 乐高幻影忍者第18季 לגו נינג''גו עליית הדרקונים lego 닌자고: 드래곤 라이징 레고 닌자고: 드래곤 라이징 new 닌자고 드래곤 라이징 樂高旋風忍者：猛龍崛起 ніндзяґо: повстання драконів ninjago: united ninjago: dragons rising lego ninjago: dragons rising - the elemental mechs lego ninjago: dragons rising', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chong-toi-la-tien-ton', 'Chồng Tôi Là Tiên Tôn', 'From God To Husband', 'https://phimimg.com/upload/vod/20250419-1/c1b8fd43e9d134e8d6273648643b0613.jpg', 'https://phimimg.com/upload/vod/20250419-1/bc9c8246cba5feb390336723f8b80146.jpg', '<p>Khương Phong bị kẻ xấu hại chết, vợ anh là Thần Phi sau một thời gian cũng tự kết liễu đời mình. Điều mà Thần Phi không thể ngờ là chồng mình đã may mắn được một vị thần tiên cứu và thu nhận làm đồ đệ. Sau nghìn năm tu luyện vất vả, Khương Phong cuối cùng cũng trở thành tiên tôn có quyền năng vô biên. Anh quyết định quay về thời điểm trước khi Thần Phi tự sát để cứu cô và trừng trị những kẻ đã từng đẩy vợ chồng anh đến bước đường cùng.</p>', 'Hoàn Tất (22/22)', 22, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Chu Trí Linh","avatar":""},{"name":"Trần Tư Triệt","avatar":""},{"name":"Chu Thịnh Kỳ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["仙帝歸來當贅婿","仙帝归来当赘婿"]', 1784690324180);
