INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-chua-bien-hinh-ky', 'Công Chúa Biến Hình Ký', 'Princess Deformation Meter', 'https://phimimg.com/upload/vod/20240425-1/da065fffde0bf081663d93342bea30a1.jpg', 'https://phimimg.com/upload/vod/20240425-1/12e201e1d90f3d4c522345a746a34f52.jpg', '<p>Công chúa Thịnh Đào Đào bị nuông chiều quá mức, thường xuyên gây ra nhiều rắc rối khiến vua cha cũng phải đau đầu. Để rèn giũa lại tính nết của con gái, hoàng đế đày nàng đến huyện Thanh Thành để tự kiểm điểm. Ở Thanh Thành, trong quá trình giúp người dân nơi đây khôi phục lại nghề may đang sắp mai một, Đào Đào đã dần trưởng thành hơn. Đồng thời, nàng cũng nảy sinh tình cảm với Mạc tướng quân, người được hoàng đế giao trọng trách bảo vệ nàng.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Mao Na","avatar":""},{"name":"Trần Tử Do","avatar":""},{"name":"Tô Thần","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324180);
