INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vuong-phi-xuyen-thoi-gian', 'Vương Phi Xuyên Thời Gian', 'Princess Across Time', 'https://phimimg.com/upload/vod/20250418-1/3c2dac8962dc1490a2fea6ae53e7297f.jpg', 'https://phimimg.com/upload/vod/20250418-1/ea882b5ab5579b5dfbcd0f450616b9e5.jpg', '<p>Sinh viên khoa học pháp y Đường Băng Nhi bất ngờ xuyên sách và nhập vào cơ thể của nhân vật Tần Hy Nguyệt, thái tử phi ác độc bị người dân căm ghét của Hằng quốc. Ở thế giới trong sách, cô áp dụng các kiến thức hiện đại đã học được để giúp Thái tử Lăng Hiên giải quyết nhiều kỳ án. Cùng nhau, họ bảo vệ Hằng quốc và mang lại cuộc sống ấm êm cho muôn dân.</p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Tuấn Thần","avatar":""},{"name":"Kim Tử Tuyền","avatar":""},{"name":"Hàn Hạo Thiên","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Counter Attack Bestowed Favor","双世异闻录"]', 1784690324180);
