INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cam-y-phong-hoa', 'Cẩm Y Phong Hoa', 'The Resilient Dr. Ling', 'https://phimimg.com/upload/vod/20250418-1/45c41b27d8a9ee0a2785e5a123149a21.jpg', 'https://phimimg.com/upload/vod/20250418-1/033ed132b9f0e46e82a2976cdbfad422.jpg', '<p>Nữ bác sĩ Lăng Nhược Cẩm xuyên không về quá khứ, nhập vào thân xác của một tiểu thư nhà giàu cùng tên có tính tình yếu đuối, ngoại hình cũng không ưa nhìn. Nhược Cẩm có hôn ước với Vương gia Tiêu Dạ Hàn, nhưng vì bị kẻ xấu ly gián mà vị phu quân này luôn ghét cô đến tận xương tủy. Bằng kiến thức y khoa hiện đại và sự thông minh của mình, Nhược Cẩm thành công đối phó với đủ mưu hèn kế bẩn từ những người xung quanh và dần dần khiến Tiêu Dạ Hàn thay đổi suy nghĩ về cô.</p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tôn Nghệ Ninh","avatar":""},{"name":"Vương Đình Húc","avatar":""},{"name":"Vương Nam Nam","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["锦医风华"]', 1784690324180);
