INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nguyet-man-van-tri', 'Nguyệt Mãn Vân Tri', 'The Cloud Embracing The Moon', 'https://phimimg.com/upload/vod/20250418-1/0b94c659fa901de7856e16a4487787c7.jpg', 'https://phimimg.com/upload/vod/20250418-1/513ea2319794a458b387521246cfd039.jpg', '<p>Vì một tấm bản đồ châu báu mà cả nhà quan đại thần họ Lý bị sát hại, người duy nhất may mắn sống sót duy nhất là Lý Vân Tri. Nhiều năm sau, Vân Tri giờ đã trưởng thành trở về với quyết tâm trả thù. Với sự giúp đỡ của Quận chúa Linh Nguyệt, Vân Tri tiếp cận hoàng tử yếu ớt Tống Trần để tìm hiểu chân tướng sự việc. Thế nhưng, trong quá trình điều tra, nàng bỗng phát hiện có lẽ mình đã quen biết Tống Trần từ thời thơ ấu.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Tôn Nghệ Nhiên","avatar":""},{"name":"Quách Ca Nam","avatar":""},{"name":"Hoàng Vân Vân","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["月滿雲知","Embracing the Moon the Cloud","月满云知"]', 1784690324180);
