INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truoc-khi-toi-thay-doi-suy-nghi', 'Trước Khi Tôi Thay Đổi Suy Nghĩ', 'Before I Change My Mind', 'https://phimimg.com/upload/vod/20250418-1/e27223249cbe87527e22218beb58c4ff.jpg', 'https://phimimg.com/upload/vod/20250418-1/811cf891e70761dc802aea856fbc479c.jpg', '<p>Trong khi các bạn học sinh khác đang băn khoăn không biết bạn học sinh mới tên Robin là con trai hay con gái, thì Robin lại đang xây dựng một mối quan hệ phức tạp với bạn học sinh hay bắt nạt người khác trong trường. Để được chấp nhận và hoà nhập, Robin dần dần đưa ra những lựa chọn ngày càng nguy hiểm.</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Vaughan Murrae","avatar":""},{"name":"Dominic Lippa","avatar":""},{"name":"Lacey Oake","avatar":""},{"name":"Matthew Rankin","avatar":""},{"name":"Shannon Blanchet","avatar":""},{"name":"Rohan Khare","avatar":""},{"name":"Jhztyn Contado","avatar":""},{"name":"Milana Bochinski","avatar":""},{"name":"Kaitlyn Haugen","avatar":""},{"name":"Kristin Johnston","avatar":""},{"name":"Trevor Anderson","avatar":""},{"name":"Heather Noel","avatar":""},{"name":"Etta George House","avatar":""},{"name":"Andrea House","avatar":""},{"name":"Ethan Nasr","avatar":""},{"name":"Joshua Carter","avatar":""},{"name":"Onika","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Before I Change My Mind"]', 1784690324180);
