INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thao-go-loi-nguyen-taekwondo', 'Tháo Gỡ Lời Nguyền Taekwondo', 'Let Free The Curse Of Taekwondo', 'https://phimimg.com/upload/vod/20250416-1/ac2454b1f25e128d376f4f3ec0e47425.jpg', 'https://phimimg.com/upload/vod/20250416-1/ff512c6c47078fa1499ffb9a34b83c67.jpg', '<p>Ju-young tái ngộ mối tình đầu thất lạc của mình – Do-hoe – người anh đã tìm kiếm suốt bao năm trời, tại một đám tang sau mười hai năm xa cách. “Cứ như mọi thứ đều bị nguyền rủa vậy…” Mười hai năm trước, họ đã từng có một tình yêu dịu dàng, cùng đồng cảm với những vết thương lòng của nhau. Thế nhưng điều gì đã khiến họ trở nên xa lạ? Do-hoe – người đã tìm ra ước mơ thật sự của mình thay vì tiếp tục với Taekwondo như từng mong muốn, và Ju-young – người vẫn kiên trì theo đuổi Taekwondo đến tận hôm nay… Liệu họ có thể phá vỡ lời nguyền của quá khứ, sau mười hai năm cách biệt?</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Nu-rim","avatar":""},{"name":"Lee Sun","avatar":""},{"name":"Jang Yeon-woo","avatar":""},{"name":"Yoo Ha-bok","avatar":""},{"name":"Kim Gyeong-ryong","avatar":""},{"name":"Han So-hyun","avatar":""},{"name":"Yoon Ji-won","avatar":""},{"name":"Ham Sang-hyeok","avatar":""},{"name":"Ko Na-yul","avatar":""},{"name":"Kong Na-ye","avatar":""},{"name":"Jang Seo-yeong","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["解开跆拳道的诅咒","Break The Curse of Taekwondo","解除跆拳道的詛咒","Uncovering the Curse of Taekwondo","태권도의 저주를 풀어줘"]', 1784690324180);
