INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoc-no-kieu', 'Ngọc Nô Kiều', 'Enslaved By Love', 'https://phimimg.com/upload/vod/20240627-1/a2a1de14991930b3f2dff6a1d085c3f0.jpg', 'https://phimimg.com/upload/vod/20240627-1/b3af42369cf42643c294f9bff098a4a3.jpg', '<p>Tạ Uẩn, thiên kim của Tạ gia, từng có mối tình sâu đậm với Ân Tắc. Nhưng rồi biến cố xảy ra, nàng bị hiểu lầm là kẻ bạc tình bạc nghĩa, phản bội Ân Tắc để lấy người khác. Sau này, khi thế sự đổi thay và Ân Tắc trở thành kẻ có quyền, hắn tìm đủ mọi cách để tra tấn, dày vò Tạ Uẩn. Liên tục bị giằng xé giữa yêu và hận, liệu họ có thể hóa giải mọi hiểu lầm để về lại bên nhau hay không?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Từ Chẩn Chẩn","avatar":""},{"name":"Trình Vũ Phong","avatar":""},{"name":"Đằng Trạch Văn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324180);
