INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huong-vi-cua-bien-mua-1', 'Hương Vị Của Biển (Mùa 1)', 'Fresh Off The Sea (Season 1)', 'https://phimimg.com/upload/vod/20241001-1/ee7aea17368e5a8b585ff549fd50a2a6.jpg', 'https://phimimg.com/upload/vod/20241001-1/63e9e3d97d90646ba58ce6cdacf85590.jpg', '<p>Đội quân hùng hậu toàn sao bao gồm minh tinh xinh đẹp Yeom Jung Ah, chị đại hài hước Park Jun Myun, cô em vui vẻ Ahn Eun Jin và cậu út mạnh mẽ Dex phút chốc trở thành những ngư dân thực thụ, sống trôi dạt khắp các làng chài ven biển xứ Hàn. Ngày ngày đánh bắt, buôn bán cá tôm, tối tối trưa trưa nấu bữa cơm thân mật sum vầy, cả bốn chị em cùng khám phá những trải nghiệm mới lạ và tận hưởng những niềm vui chưa từng có.</p>', 'Hoàn Tất (24/24)', 24, 'tvshows', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Yeom Jung Ah","avatar":""},{"name":"Ahn Eun Jin","avatar":""},{"name":"Park Jun Myun","avatar":""},{"name":"Dex","avatar":""},{"name":"Hwang Jung Min","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"}]', '["언니네 산지직송 in 칼라페","姐姐們的產地直送","Direct delivery from my sister’s place","Fresh of the Sea","언니네 산지직송"]', 1784690324180);
