INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('huong-vi-cua-bien-mua-1', 'Hương Vị Của Biển (Mùa 1)', 'Fresh Off The Sea (Season 1)', 'hương vị của biển (mùa 1) fresh off the sea (season 1) yeom jung ah ahn eun jin park jun myun dex hwang jung min 언니네 산지직송 in 칼라페 姐姐們的產地直送 direct delivery from my sister’s place fresh of the sea 언니네 산지직송', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-ta-hay-ket-hon-nhe', 'Chúng Ta Hãy Kết Hôn Nhé', 'My Merry Marriage', 'https://phimimg.com/upload/vod/20241009-1/dbefbe95135961f8c5435bfcb34c369d.jpg', 'https://phimimg.com/upload/vod/20241009-1/5f764cfa77ce1266b660a762e1291a4c.jpg', '<p><span style="text-wrap: nowrap;">Một bộ phim gia đình thú vị hỏi về ý nghĩa thực sự của &#39;hạnh phúc&#39; bằng cách thể hiện nhiều khía cạnh khác nhau của hôn nhân như ly hôn, tái hôn và cuộc sống độc thân, đồng thời mang lại sự đồng cảm và tiếng cười cho mọi thế hệ.</span></p><p><span style="text-wrap: nowrap;">Maeng Gong Hee là nhà thiết kế hợp đồng tại Jayce Fashion. Thừa hưởng tinh thần mạnh mẽ của người mẹ và khả năng thể thao của người cha cựu thám tử, cô là một phụ nữ hoang dã hiếm hoi ngày nay có đủ can đảm để sống sót ngay cả khi bị mắc kẹt trên một hòn đảo hoang.</span><br/></p><p><span style="text-wrap: nowrap;">Gu Dan Soo là cháu trai của Chủ tịch Jayce Fashion Hwang Ik Seon và sinh ra trong một người cha giàu có, mẹ nghèo. Dan Soo, người đang sống như một linh hồn tự do ở nước ngoài, đến Hàn Quốc theo kế hoạch của bà anh để trở thành người kế vị chủ tịch và anh đoàn tụ với người bạn thời thơ ấu Maeng Gong Hee một lần nữa.</span><br/></p>', 'Hoàn Tất (125/125)', 125, 'series', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Ha-na","avatar":""},{"name":"Park Sang-nam","avatar":""},{"name":"Kim Sa-kwon","avatar":""},{"name":"Lee Yeon-doo","avatar":""},{"name":"Yang Mi-kyung","avatar":""},{"name":"Choi Jae-sung","avatar":""},{"name":"Ban Hyo-jung","avatar":""},{"name":"Yang Hee-kyung","avatar":""},{"name":"Lee Eun-hyung","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Gyeolhonhaja Maengkkonga!","Let''s Get Married, Frog!","결혼하자 맹꽁아!"]', 1784690324180);
