INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kung-fu-gau-truc-4', 'Kung Fu Gấu Trúc 4', 'Kung Fu Panda 4', 'https://phimimg.com/upload/vod/20250412-1/d99383031a083b44810116f4da06aaf8.jpg', 'https://phimimg.com/upload/vod/20250412-1/f23da8f2ba623267bfa68272d444026d.jpg', '<p>Sau khi Po được chọn trở thành Thủ lĩnh tinh thần của Thung lũng Bình Yên, Po cần tìm và huấn luyện một Chiến binh Rồng mới, trong khi đó một mụ phù thủy độc ác lên kế hoạch triệu hồi lại tất cả những kẻ phản diện mà Po đã đánh bại về cõi linh hồn.</p>', 'Full', 1, 'hoathinh', 'completed', 7, 2024, 'Vietsub + Lồng Tiếng', 'FHD', 'Âu Mỹ', 1, '[{"name":"Jack Black","avatar":""},{"name":"Awkwafina","avatar":""},{"name":"Viola Davis","avatar":""},{"name":"Dustin Hoffman","avatar":""},{"name":"Bryan Cranston","avatar":""},{"name":"James Hong","avatar":""},{"name":"Ian McShane","avatar":""},{"name":"Ke Huy Quan","avatar":""},{"name":"Ronny Chieng","avatar":""},{"name":"Lori Tan Chinn","avatar":""},{"name":"Seth Rogen","avatar":""},{"name":"Jimmy Donaldson","avatar":""},{"name":"James Murray","avatar":""},{"name":"James Sie","avatar":""},{"name":"Cedric Yarbrough","avatar":""},{"name":"Vic Chao","avatar":""},{"name":"Audrey Brooke","avatar":""},{"name":"Lincoln Nakamura","avatar":""},{"name":"Cece","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["功夫熊猫4","O Panda do Kung Fu 4","쿵푸팬더4","Κουγκ Φου Πάντα 4","Công Phu Gấu Trúc 4