INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoc-vien-ky-lan-phan-2', 'Học Viện Kỳ Lân (Phần 2)', 'Unicorn Academy (Season 2)', 'https://phimimg.com/upload/vod/20240628-1/4ae8665d84bca9189a38f3abbb9d8837.jpg', 'https://phimimg.com/upload/vod/20240628-1/9783005e80f4b35214e5b53bbbc76f4b.jpg', '<p>Khi thế lực hắc ám đe dọa phá hủy đảo Kỳ Lân, một thiếu nữ dũng cảm và năm người bạn cùng trường phải đứng lên bảo vệ học viện phép thuật mà họ trân quý.</p>', 'Hoàn Tất (10/10)', 10, 'hoathinh', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Canada', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '[]', 1784690324180);
