INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('da-thanh-phu-reborn', 'Dạ Thành Phú (Reborn)', 'Ye Cheng (Reborn)', 'https://phimimg.com/upload/vod/20250412-1/a95e7287be359f34c5fb2baf399ce8cf.jpg', 'https://phimimg.com/upload/vod/20250412-1/5ee51e31749680817c245f8bfb305737.jpg', '<p>Dưới thời loạn lạc của triều đại Chu, Thân Dạ — con trai của Hoàng hậu — nổi dậy để báo thù cho cha mình và đoạt ngôi vua nhằm trao cho người mình yêu, Thái tử Thục Trình. Tuy nhiên, vì Thục Trình phản đối đổ máu nên Thân Dạ buộc phải từ bỏ kế hoạch, khiến triều Chu rơi vào thế suy yếu, đồng thời lan truyền tin đồn rằng Thục Trình đã tử trận nơi sa trường. Nhiều năm sau, Thân Dạ — giờ đã trở thành một quyền thần tàn nhẫn, bị ám ảnh bởi việc tìm lại Thục Trình — bị một công chúa có dung mạo giống hệt người xưa kéo ra khỏi nơi ẩn mình. Cuộc hội ngộ ấy, cùng với sự trở lại của những người bạn cũ, thắp lên ngọn lửa của tình yêu, lòng trung thành và sợi dây định mệnh không thể trốn thoát.</p>', 'Hoàn Tất (19/19)', 19, 'series', 'completed', 6, 2024, 'Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Yuan Hao","avatar":""},{"name":"Jia Ze","avatar":""},{"name":"Li Zhehao","avatar":""},{"name":"Peng Yaqi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["夜郎自大","夜城赋之离生","Ye Cheng Fu Zhi Li Sheng","Ye Cheng 2","Е Чен Перерождение","Ye Cheng","Reborn","夜城赋"]', 1784690324180);
