INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('da-thanh-phu-reborn', 'Dạ Thành Phú (Reborn)', 'Ye Cheng (Reborn)', 'dạ thành phú (reborn) ye cheng (reborn) yuan hao jia ze li zhehao peng yaqi 夜郎自大 夜城赋之离生 ye cheng fu zhi li sheng ye cheng 2 е чен перерождение ye cheng reborn 夜城赋', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thien-duong-qua-bao', 'Thiên Đường Quả Báo', 'The Paradise of Thorns', 'https://phimimg.com/upload/vod/20250411-1/92e42f7ea0bd92c52e429179ea2d216e.jpg', 'https://phimimg.com/upload/vod/20250411-1/8065518b9fe42fcd98604ca6728a1128.jpg', '<p>Thongkam (Jeff Satur) và Sek (Pongsakorn) làm lụng vất vả, cày ngày cày đêm để xây dựng một mái ấm. Sau bao nỗ lực, cuối cùng họ cũng có quyền sở hữu trang trại sầu riêng ở Mae Hong Son. Tuy nhiên, bi kịch bỗng ập tới khi Sek đột ngột qua đời trong một vụ tai nạn vào thời điểm họ chưa kịp đăng ký kết hôn. Chính điều này đã khiến Thongkam không có quyền sở hữu tài sản mà 2 người đã cùng gây dựng. Ngôi nhà và đất đai bao gồm vườn sầu riêng đương nhiên thuộc về mẹ của Sek, người sẽ chuyển đến sống cùng con gái nuôi Mo (Engfa) và người làm vườn Jingna. Thongkam giờ phải đấu tranh để giành lại thành quả của tình yêu và công sức lao động của mình. Liệu giữa Thongkam và Mo, ai sẽ giành được quyền thừa kế , trở thành chủ vựa sầu riêng?</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Thái Lan', 1, '[{"name":"Jeff Satur","avatar":""},{"name":"Pongsakorn Mettarikanon","avatar":""},{"name":"Engfa Waraha","avatar":""},{"name":"Seeda Puapimon","avatar":""},{"name":"Harit Buayoi","avatar":""},{"name":"Nikorn Saetang","avatar":""},{"name":"Paphon Jirahitaphat","avatar":""},{"name":"Ampon Phonram","avatar":""},{"name":"Pornchai Hongrattanaporn","avatar":""},{"name":"Prawee Saeueng","avatar":""},{"name":"Prow Vassatanakorn","avatar":""},{"name":"Pongpun Suwee","avatar":""},{"name":"Terapatt Vannaruemol","avatar":""},{"name":"Sirin Wannavalee","avatar":""},{"name":"Srisa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Wiman Nam","បំណុលស្នេហ៍ចម្ការទុរេន","TPOT","O Paraíso dos Espinhos","荊棘天堂","いばらの楽園","El paraíso de las espinas","Терновый рай","Рай в терновом саду","Рай из шипов","The Paradise of Thorns","วิมานหนาม"]', 1784690324180);
