INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thien-duong-qua-bao', 'Thiên Đường Quả Báo', 'The Paradise of Thorns', 'thiên đường quả báo the paradise of thorns jeff satur pongsakorn mettarikanon engfa waraha seeda puapimon harit buayoi nikorn saetang paphon jirahitaphat ampon phonram pornchai hongrattanaporn prawee saeueng prow vassatanakorn pongpun suwee terapatt vannaruemol sirin wannavalee srisa wiman nam បំណុលស្នេហ៍ចម្ការទុរេន tpot o paraíso dos espinhos 荊棘天堂 いばらの楽園 el paraíso de las espinas терновый рай рай в терновом саду рай из шипов the paradise of thorns วิมานหนาม', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-kho-kiem-che', 'Tình Khó Kiềm Chế', 'Lost You, Found You', 'https://phimimg.com/upload/vod/20240810-1/5a63e67a55aa11eb8d2e9e527afa5bf8.jpg', 'https://phimimg.com/upload/vod/20240810-1/afa9a88d1bc382d16a5dcf023ee869c1.jpg', '<p>Đến từ hai bang phái đối địch, Vân Phi Phi và Cố Lâm Uyên từ lần đầu gặp gỡ đã là kẻ thù không đội trời chung. Thế nhưng, sau khi phát hiện thân phận thật của nhau, cả hai bàng hoàng nhận ra mình chính là mối tình khắc cốt ghi tâm đã xa cách nhiều năm của người kia. Kể từ đó, họ lại một lần nữa không thể kiềm chế tình cảm và bất chấp tất cả để ở bên nhau.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Đại Cao Chính","avatar":""},{"name":"Đồ Chỉ Oánh","avatar":""},{"name":"Chu Vân Long","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '[]', 1784690324180);
