INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ta-ninh-an', 'Tá Ninh An', 'Love In A Dream', 'https://phimimg.com/upload/vod/20240909-1/8848467c259bb5afd32a96d18c54b213.jpg', 'https://phimimg.com/upload/vod/20240909-1/913c76acc49f4c8cf6be7b42b260a5c7.jpg', '<p>Vừa mới vào cung, con gái của Tô tướng quân là Tô Cầm đã bị đày vào lãnh cung. Tại đây, nàng bị một kẻ áo đen lạ mặt đe dọa, buộc nàng phải hỗ trợ hắn ám sát hoàng đế. Đổi lại, hắn sẽ giúp nàng đến với ý trung nhân. Giữa chốn cung đình nguy hiểm trùng trùng, lại còn rơi vào thế trên đe dưới búa, Tô Cầm sẽ phải làm thế nào để sống sót?</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hoàng Dương Điềm Điềm","avatar":""},{"name":"Trương Cảnh Vân","avatar":""},{"name":"Khưu Hồng Khải","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324180);
