INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quan-dien-tu-dao-hoa', 'Quân Diện Tự Đào Hoa', 'Pavilion Secrets', 'https://phimimg.com/upload/vod/20250411-1/c07dcdc08e424f0ca5acc2fe54ad1389.jpg', 'https://phimimg.com/upload/vod/20250411-1/f84a5b95f1d110ad059060498d8b5c58.jpg', '<p>Có dung mạo xinh đẹp bẩm sinh, nhưng vì luôn ra tay tàn nhẫn với kẻ thù nên Vân Khê có thể thành công cải trang thành nam nhân và làm đại tướng quân suốt nhiều năm. Trong một lần thực hiện nhiệm vụ, nàng được cầm sư Tống Hoán Bắc cứu mạng. Vân Khê không biết rằng hắn cố tình tiếp cận nàng để điều tra thảm án của Mặc gia năm xưa, còn Tống Hoán Bắc lại chẳng thể ngờ nàng chính là người sống sót duy nhất còn lại của Mặc gia.</p>', 'Hoàn Tất (26/26)', 26, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Cao Mậu Đồng","avatar":""},{"name":"Hồ Diệc Dao","avatar":""},{"name":"Trần Kiến Vũ","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jun Mian Shi Tao Hua","Your face is like peach blossom","君面似桃花"]', 1784690324180);
