INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('liet-diem-tan-nuong', 'Liệt Diễm Tân Nương', 'Flame Bride', 'https://phimimg.com/upload/vod/20250411-1/e674b521941379a51b26dbaaff541cc4.jpg', 'https://phimimg.com/upload/vod/20250411-1/03347abe587691c466a717bd1f20583a.jpg', '<p>Toàn quân bị tiêu diệt trong một trận chiến nhưng Thiếu soái Lưu Tử Nhuận lại may mắn sống sót. Tin rằng các đồng đội bỏ mạng vì vị hôn thê Chung Uyển Nhược đã bán tin cho kẻ địch, Tử Nhuận thay đổi dung mạo, lấy tên là Mộc Thiếu Ly để quay về trả thù. Trong thân phận mới, Tử Nhuận tìm đủ mọi cách để trừng phạt Uyển Nhược, nhưng liệu cô có đúng là kẻ đã phản bội anh năm xưa như lời đồn hay không?</p>', 'Hoàn Tất (28/28)', 28, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Lâm Nghiên Nhu","avatar":""},{"name":"Văn Uyên","avatar":""},{"name":"Hứa Nhược Đồng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["烈焰新娘","Flame Bride"]', 1784690324180);
