INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-ke-quyet-tu', 'Những Kẻ Quyết Tử', 'Those About to Die', 'https://phimimg.com/upload/vod/20250409-1/3c2b175193a227218fba06a3aa5786ee.jpg', 'https://phimimg.com/upload/vod/20250409-1/82c2742f9aecbbf4d7c0eb602097901c.jpg', '<p>Trong thế giới ngoạn mục, phức tạp và thối nát của các môn thể thao đấu sĩ ở La Mã cổ đại, hãy theo chân một nhóm các nhân vật đa dạng thuộc nhiều tầng lớp của xã hội La Mã, nơi thể thao, chính trị và kinh doanh giao thoa và va chạm.</p>', 'Hoàn Tất (10/10)', 10, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Anthony Hopkins","avatar":""},{"name":"Tom Hughes","avatar":""},{"name":"Jojo Macari","avatar":""},{"name":"Iwan Rheon","avatar":""},{"name":"Gabriella Pession","avatar":""},{"name":"Rupert Penry-Jones","avatar":""},{"name":"Lara Wolf","avatar":""},{"name":"Sara Martins","avatar":""},{"name":"Kyshan Wilson","avatar":""},{"name":"Alicia Ann Edogamhe","avatar":""},{"name":"Moe Hashim","avatar":""},{"name":"Dimitri Leonidas","avatar":""},{"name":"Emilio Sakraya","avatar":""},{"name":"Jóhannes Haukur Jóhannesson","avatar":""},{"name":"Eneko Sagardoy","avatar":""},{"name":"Pepe Barro","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Aqueles Prestes a Morrer","Обреченные на славу","Идущие на смерть","Those About to Die"]', 1784690324180);
