INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('nhung-ke-quyet-tu', 'Những Kẻ Quyết Tử', 'Those About to Die', 'những kẻ quyết tử those about to die anthony hopkins tom hughes jojo macari iwan rheon gabriella pession rupert penry-jones lara wolf sara martins kyshan wilson alicia ann edogamhe moe hashim dimitri leonidas emilio sakraya jóhannes haukur jóhannesson eneko sagardoy pepe barro aqueles prestes a morrer обреченные на славу идущие на смерть those about to die', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-co-ba-nguoi-ban-trai', 'Tôi Có Ba Người Bạn Trai', 'The Irresistible Boyfriend', 'https://phimimg.com/upload/vod/20250409-1/636faebe997f910449d969b135fd1b12.jpg', 'https://phimimg.com/upload/vod/20250409-1/03384539ed6898e97f86464bcb65660f.jpg', '<p>Một hôm tỉnh dậy, Cố Hâm Điềm bỗng phát hiện mình đã mất đi ký ức của tám năm cuộc đời. Bất ngờ hơn là cô hiện đang có đến ba người bạn trai cùng làm ở một công ty với mình. Trong quá trình vừa cố gắng khôi phục trí nhớ vừa phải &quot;tung hứng&quot; ba mối quan hệ một lúc, Hâm Điềm đã khám phá ra ý nghĩa thực sự của tình yêu và dũng cảm đối mặt với những sai lầm của bản thân.</p>', 'Hoàn Tất (20/20)', 20, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Vương Tử Thanh","avatar":""},{"name":"Văn Dĩ Phàm","avatar":""},{"name":"Tả Kỳ Bạch","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["세 남자와 사내연애 : 무법항거적남우문","the Irresistible Boyfriend","无法抗拒的男友们"]', 1784690324180);
