INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('toi-co-ba-nguoi-ban-trai', 'Tôi Có Ba Người Bạn Trai', 'The Irresistible Boyfriend', 'tôi có ba người bạn trai the irresistible boyfriend vương tử thanh văn dĩ phàm tả kỳ bạch 세 남자와 사내연애 : 무법항거적남우문 the irresistible boyfriend 无法抗拒的男友们', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cuu-trung-tu', 'Cửu Trùng Tử', 'Blossom', 'https://phimimg.com/upload/vod/20241207-1/e9615fa2df220a9d31f9c897e839b502.jpg', 'https://phimimg.com/upload/vod/20241207-1/ba7312d6e04169f1158086b6ce67892c.jpg', '<p>Đậu Chiêu từ nhỏ đã mất mẹ, vì biến cố gia đình và số phận long đong lận đận nên đã tuyệt vọng với tình yêu và tình thân. Cô đấu đá với mẹ kế, bảo vệ gia sản, lánh về điền trang hẻo lánh, học hành trau dồi kiến thức để tự bảo vệ mình. Vào một đêm mưa lớn, Đậu Chiêu gặp gỡ Tống Mặc đang cải trang thành thương nhân đến trọ tại điền trang. Cô dùng trí tuệ của mình giúp chàng bảo vệ đứa trẻ mồ côi hậu duệ của Định Quốc Công, người có công dẹp giặc. Cũng từ đó, số phận của hai người gắn chặt với nhau. Tống Mặc xuất thân từ gia đình quan lại bị cuốn vào vòng xoáy bí ẩn của biến cố gia tộc. Đậu Chiêu cũng bị mẹ kế hãm hại, vướng vào tin đồn gả thay. Hai người quyết định thành thân để liên minh, cùng nhau vượt qua khó khăn. Từ ban đầu nghi ngờ nhau, họ giúp đỡ nhau cùng vượt qua gian nan, từ đó dần dần hiểu nhau, trân trọng nhau và trở thành tri kỷ.</p>', 'Hoàn Tất (34/34)', 34, 'series', 'completed', 9, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Mạnh Tử Nghĩa","avatar":""},{"name":"Lý Quân Nhuệ","avatar":""},{"name":"Khổng Tuyết Nhi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["Jiu chong zi","Blossom","九重紫"]', 1784690324180);
