INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('sat-nhan-trong-toa-nha-phan-4', 'Sát Nhân Trong Tòa Nhà (Phần 4)', 'Only Murders in the Building (Season 4)', 'sát nhân trong tòa nhà (phần 4) only murders in the building (season 4) steve martin martin short selena gomez michael cyril creighton homicídios ao domicílio só os assassinos no edifício só os assassinos do edifício 大楼里只有谋杀 公寓大楼里的谋杀案 רק רציחות בבניין فقط قتل‌های داخل ساختمان убийства в пределах здания тільки вбивства у будівлі omitb only murders in the building', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('gia-toc-ma-so-than-thanh', 'Gia Tộc Mã Số Thần Thánh', 'Perfect 10 Liners', 'https://phimimg.com/upload/vod/20250303-1/37a6973f8e998193fabb7a93d33cd106.jpg', 'https://phimimg.com/upload/vod/20250303-1/ab8188b0f8940595909b5ef0d2784691.jpg', '<p>Perfect 10 Liners xoay quanh một nhóm sinh viên khoa Kỹ thuật nổi tiếng với vẻ ngoài hoàn hảo và cá tính độc đáo. Khi Arm, người quản lý trang Engineer Cute Boy, vô tình phá vỡ quy tắc bằng cách đăng ảnh của Arc – tiền bối của cố vấn mình, còn được biết đến với biệt danh Perfect 10 Ferocious, mọi chuyện bắt đầu rối ren. Trong khi đó, Gun gặp vấn đề với chứng mất ngủ khi ở trong bóng tối, nhưng Perfect 10 Mysterious Yotha, đàn em của Arm, tình nguyện làm bạn cùng phòng để giúp cậu vượt qua nỗi sợ hãi. Còn Perfect 10 Piteous Wine, một đàn em khác của Yotha, lại quá bận rộn để tự chăm sóc bản thân, buộc em trai của Yotha – Faifa – phải ra tay giúp đỡ. Câu chuyện hài hước nhưng cũng đầy cảm xúc này sẽ đưa khán giả khám phá những mối quan hệ và chuyện tình cảm của ba cặp đôi sinh viên kỹ thuật thuộc nhóm Perfect 10 Liners, khi sự hoàn hảo đối mặt với thực tế đầy bất ngờ.</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Kasidet Plookphol","avatar":""},{"name":"Jiratchapong Srisang","avatar":""},{"name":"Tanapon Sukumpantanasan","avatar":""},{"name":"Pongsapak Oudompoch","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["男神俱乐部","Sai Rahat Thewada","Witsawakam Prasat","Witsawa Gun Yotha","Witsawa Kap Faifa","วิศวะกับไฟฟ้า","วิศวกรรมประสาท","วิศวกรรณโยธา","สายรหัสเทวดา"]', 1784690324180);
