INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-choi-chet-choc', 'Trò Chơi Chết Chóc', 'Petak Umpet', 'https://phimimg.com/upload/vod/20250408-1/a7b9fe8127d642055942ff06fb50f74e.jpg', 'https://phimimg.com/upload/vod/20250408-1/e4fe1a5ce341ff2f4eb992814a5cad46.jpg', '<p>Sari bị Wewe Gombel bắt cóc khi đang chơi trốn tìm trong một ngôi nhà hoang, do anh trai cô – Rahman – sơ ý không để mắt đến. Giờ đây, Rahman phải cùng các bạn của mình lên đường giải cứu em gái, vượt qua những thế lực siêu nhiên rùng rợn đang rình rập họ.</p>', 'Full', 1, 'single', 'completed', 16, 2024, 'Vietsub', 'FHD', 'Indonesia', 1, '[{"name":"Randy Martin","avatar":""},{"name":"Saskia Chadwick","avatar":""},{"name":"Alesha Fadillah","avatar":""},{"name":"Adam Farrel","avatar":""},{"name":"Jared Ali","avatar":""},{"name":"Putri Ayudya","avatar":""},{"name":"Lisye Herliman","avatar":""},{"name":"Monique Henry","avatar":""},{"name":"Gilbert Pattiruhu","avatar":""},{"name":"Freya Mikhayla","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Petak Umpet: Wewe Gombel","ល្បែងខ្មោចបិទពួន","Petak Umpet"]', 1784690324180);
