INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('235-do-nghieng', '23,5 Độ Nghiêng', '23.5', '23,5 độ nghiêng 23.5 pansa vosbein pattranite limpatiyakorn benyapa jeenprasom wanwimol jaenasavamethee thanaset suriyapornchaikul allan asawasuebsakul preeyaphat lawsuwansiri chayapol jutamas rutricha phapakithi tachakorn boonlupyanun kittipat chalaragse suchada p 地球倾斜23.5度 23.5 ongsa thi lok iang 23.5 degree the world incline 23point5 the earth''s axis tilts by 23.5 degrees 23.5 when the earth is spinning around 23 point 5 23.5 องศาที่โลกเอียง', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-chac-phan-thang', 'Nắm Chắc Phần Thắng', 'To Gather Around', 'https://phimimg.com/upload/vod/20250407-1/8bf58d2472dc8ac509b86635741ae52f.jpg', 'https://phimimg.com/upload/vod/20250407-1/cf0b5f6ada641fd1703d928d384e0c92.jpg', '<p>Bạch Thắng, nhân viên số 11 của một công ty công nghệ, bất ngờ bị sa thải đúng lúc đang bị đòi nợ. Để giành lại 8 triệu quyền chọn cổ phiếu, anh buộc phải trụ lại công ty thêm 100 ngày. Bằng một kế hoạch gian dối, anh quay lại công ty và nhờ có người bảo lãnh, anh được trao cơ hội khởi nghiệp nội bộ. Bạch Thắng lập nhóm khởi nghiệp mang tên “Nhà Máy Bong Bóng”, tập hợp những nhân tài xuất sắc ở các lĩnh vực: nhân sự, công nghệ và truyền thông. Nhưng khi mọi chuyện tưởng như đang suôn sẻ, sự xuất hiện của giám sát viên Chu Vọng Cao khiến kế hoạch của anh đứng trước nguy cơ sụp đổ, kéo theo một âm mưu còn lớn hơn đang dần lộ diện...</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Deng Chao","avatar":""},{"name":"Deng Jiajia","avatar":""},{"name":"Zheng Yunlong","avatar":""},{"name":"Yu Entai","avatar":""},{"name":"Zhang Benyu","avatar":""},{"name":"Ke Da","avatar":""},{"name":"Li Naiwen","avatar":""},{"name":"Yang Haoyu","avatar":""},{"name":"Bu Yu","avatar":""},{"name":"Ning Li","avatar":""},{"name":"Chen Minghao","avatar":""},{"name":"White-K","avatar":""},{"name":"Tong Chenjie","avatar":""},{"name":"Xiao Ai","avatar":""},{"name":"Li Xiaochuan","avatar":""},{"name":"Zhang Yijie","avatar":""},{"name":"Qu Zheming","avatar":""},{"name":"Qu Gaowei","avatar":""},{"name":"Xunzimo Liu","avatar":""},{"name":"Chen Siyu","avatar":""},{"name":"Huang Erchun","avatar":""},{"name":"Bai Yufei","avatar":""},{"name":"Ch","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["梦想家","Brave New World","胜券在握"]', 1784690324180);
