INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngo-sat-3', 'Ngộ Sát 3', 'Octopus With Broken Arms', 'https://phimimg.com/upload/vod/20250404-1/30351c14d3c3f87d11eb11f52b073739.jpg', 'https://phimimg.com/upload/vod/20250404-1/d92f5387b67c9dd9913907b2674849f8.jpg', '<p>Một doanh nhân giàu có lao vào giải cứu con gái mình, nhưng rồi nhận ra vụ bắt cóc cô là một phần trong nước đi có tính toán nhằm vạch trần một âm mưu quy mô lớn.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Xiao Yang","avatar":""},{"name":"Tong Liya","avatar":""},{"name":"Duan Yihong","avatar":""},{"name":"Liu Yase","avatar":""},{"name":"Wang Longzheng","avatar":""},{"name":"Feng Bing","avatar":""},{"name":"Zhou Chuchu","avatar":""},{"name":"Yi-Fan Hsu","avatar":""},{"name":"Jack Kao","avatar":""},{"name":"Terence Yin Chi-Wai","avatar":""},{"name":"Sandrine Pinna","avatar":""},{"name":"Amy Lo","avatar":""},{"name":"Chen Hao","avatar":""},{"name":"Fan Jingyi","avatar":""},{"name":"Ye Quanxi","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["误杀3"]', 1784690324180);
