INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nu-cong-tuoc-tai-ba', 'Nữ Công Tước Tài Ba', 'Duchess', 'https://phimimg.com/upload/vod/20250404-1/c9206c4e951ed46831cc6f58cf7fe530.jpg', 'https://phimimg.com/upload/vod/20250404-1/2d61051cab95486685bae2bd213cc804.jpg', '<p>Câu chuyện xoay quanh Scarlett, một kẻ móc túi và tội phạm nhỏ lẻ ở London, người bị cuốn vào thế giới buôn lậu kim cương sau khi gặp gỡ và yêu Robert McNaughton (Philip Winchester), một cựu lính thủy đánh bộ trở thành kẻ buôn lậu kim cương.Sau cái chết của Robert do bị đồng bọn phản bội, Scarlett, với biệt danh &quot;Duchess&quot;, quyết tâm trả thù những kẻ đã hại anh. Cô hợp tác với Danny Oswald (Sean Pertwee) và Billy Baraka (Hoji Fortuna), những người trung thành với Robert, để thực hiện kế hoạch báo thù.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Charlotte Kirk","avatar":""},{"name":"Philip Winchester","avatar":""},{"name":"Colm Meaney","avatar":""},{"name":"Hoji Fortuna","avatar":""},{"name":"Stephanie Beacham","avatar":""},{"name":"Sean Pertwee","avatar":""},{"name":"Colin Egglesfield","avatar":""},{"name":"Pau Poch","avatar":""},{"name":"Yan Tual","avatar":""},{"name":"Harvey Dean","avatar":""},{"name":"Mellissa Laycy","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Duchess"]', 1784690324180);
