INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cong-tu-bac-lieu', 'Công Tử Bạc Liêu', 'Once Upon A Time In Indochine', 'https://phimimg.com/upload/vod/20250403-1/6cc48ac44f9e5bd02a3b4c2301865d9e.jpg', 'https://phimimg.com/upload/vod/20250403-1/2598439800e1d56a3ab37ed88160a364.jpg', '<p>Lấy bối cảnh thập niên 1930, bộ phim là câu chuyện kể về một nhân vật ăn chơi bậc nhất Nam Kỳ lục tỉnh thời bấy giờ, Công tử Bạc Liêu Trần Đắc Hơn, với những giai thoại nổi tiếng như đốt tiền nấu chè, đấu xảo sắc đẹp, v.v... &nbsp;Dù là một người có tư tưởng cấp tiến Tây học, luôn thích phá cách và làm trái ngược lại những truyền thống mà cậu cho là cổ hủ của cha mình, nhưng vì đã sớm hiểu được bản thân có cuộc sống sung túc từ bé nên cậu chỉ biết hưởng thụ mà chưa bao giờ nghĩ đến chuyện sẽ tạo dựng sự nghiệp cho bản thân, kể cả tiếp nối sự nghiệp của gia đình. Song, vô tình những cuộc chơi của cậu lại tạo nên tiếng vang và những lợi ích lớn cho cộng đồng người Việt lẫn gia đình nằm ngoài mong đợi.</p>', 'Full', 1, 'single', 'completed', 13, 2024, 'Vietsub', 'FHD', 'Việt Nam', 1, '[{"name":"Song Luân","avatar":""},{"name":"Kaity Nguyễn","avatar":""},{"name":"Thành Lộc","avatar":""},{"name":"Hữu Châu","avatar":""},{"name":"Thanh Thủy","avatar":""},{"name":"Công Dương","avatar":""},{"name":"Đoàn Thiên Ân","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Công Tử Bạc Liêu"]', 1784690324180);
