INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('cong-tu-bac-lieu', 'Công Tử Bạc Liêu', 'Once Upon A Time In Indochine', 'công tử bạc liêu once upon a time in indochine song luân kaity nguyễn thành lộc hữu châu thanh thủy công dương đoàn thiên ân công tử bạc liêu', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('run-jin', 'Run Jin', 'Run Jin', 'https://phimimg.com/upload/vod/20250403-1/70032c12c2f5f5878584432b260c41c1.jpg', 'https://phimimg.com/upload/vod/20250403-1/068e11b17b3f189e1bcff1759f163959.jpg', '<p>Khởi đầu của một hành trình gian nan do chính mình đặt ra. &quot;Run Jin&quot; là phiên bản làm lại của chương trình đình đám &quot;Run BTS!&quot;, nhưng lần này với Jin – anh cả của BTS – là nhân vật chính. Chương trình mang đến sự kết hợp giữa vui nhộn, phấn khích và những khoảnh khắc ấm áp, thể hiện cá tính độc đáo và khiếu hài hước của Jin. Anh sẽ tham gia các trò chơi, thử thách và thực hiện các nhiệm vụ bí mật với mục tiêu giành chiến thắng hoặc nhận hình phạt. Bối cảnh diễn ra trong một kỳ nghỉ thú vị trên đảo Jeju, nơi Jin phải vượt qua hàng loạt thử thách để kiểm tra sự nhanh trí và kỹ năng của mình. Chương trình chắc chắn sẽ gợi nhớ đến &quot;Run BTS!&quot;, series đã gắn bó với người hâm mộ trong nhiều năm và được phát sóng vào mỗi thứ Ba.</p>', 'Tập 28', 99, 'tvshows', 'ongoing', 9, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jin","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["달려라석진"]', 1784690324180);
