INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('canh-bac-ai-tinh', 'Canh Bạc Ái Tình', 'Past Life Present Love', 'https://phimimg.com/upload/vod/20240928-1/4bf4a9dca6209629bfdcd35413ccd14a.jpg', 'https://phimimg.com/upload/vod/20240928-1/95852804ce44226e858cf13e0eff8537.jpg', '<p>Canh Bạc Ái Tình là chuyện tình oái oăm giữa một nữ dược sĩ trẻ Mild và linh hồn đang trú ngụ trong thân xác kẻ thù của cô. Sau khi từ Mỹ trở về Thái Lan, bi kịch liên tục ập đến với Mild: mẹ cô qua đời trong một sự cố đáng ngờ, người yêu cũ là Phas cũng mất vì tai nạn giao thông. Nghi ngờ cái chết của họ có liên quan đến cha con tỷ phú Thana và Theethat, Mild tìm cách quyến rũ Theethat để điều tra chân tướng. Điều cô không thể ngờ là từ sau tai nạn kia, linh hồn Phas đã được chuyển vào thân xác của Theethat.</p>', 'Hoàn Tất (18/18)', 18, 'series', 'completed', 6, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Min Pechaya Wattanamontree","avatar":""},{"name":"Film Thanapat Kawila","avatar":""},{"name":"Sam Yuranunt Pamornmontri","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Game Rak Patihan","เกมรักปาฏิหาริย์"]', 1784690324180);
