INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sujo', 'Sujo', 'Sujo', 'https://phimimg.com/upload/vod/20250401-1/e7c099896ed7d47339a31d32cbf2a926.jpg', 'https://phimimg.com/upload/vod/20250401-1/9efef64c64567aa01ed86878dedf9e39.jpg', '<p>Sujo, một cậu bé lớn lên trong vùng quê Mexico đầy rẫy bạo lực, mất cha khi còn nhỏ – một tay súng trong băng đảng ma túy. Dù cố gắng thoát khỏi quá khứ, Sujo không thể tránh khỏi ảnh hưởng của cha mình. Mỗi bước đi trong cuộc đời cậu đều bị bóng ma bạo lực bủa vây, buộc cậu phải đối diện với câu hỏi: Liệu cậu có thể thoát khỏi số phận đã được định sẵn, hay sẽ bước vào con đường đẫm máu như cha mình?</p>', 'Full', 1, 'single', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Juan Jesús Varela","avatar":""},{"name":"Yadira Pérez","avatar":""},{"name":"Sandra Lorenzano","avatar":""},{"name":"Alexis Varela","avatar":""},{"name":"Jhon Jairo Hernández","avatar":""},{"name":"Karla Garrido","avatar":""},{"name":"Ricardo Luna","avatar":""},{"name":"Kevin Aguilar","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Hijo de sicario","Sujo"]', 1784690324180);
