INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tro-thanh-giao-vien-tai-truong-hoc-quai-vat', 'Trở Thành Giáo Viên Tại Trường Học Quái Vật', 'A Terrified Teacher At Ghoul School', 'https://phimimg.com/upload/vod/20250331-1/5be174da7fa34106d325b08a32494e45.jpg', 'https://phimimg.com/upload/vod/20250331-1/bf3401c88e3b06a8f5704accffc25170.jpg', '<p>Abe Haruaki là một giáo viên mới, nhút nhát và dễ bị bắt nạt. Anh chàng vô cùng phấn khích khi được phân công giảng dạy tại một hòn đảo xa xôi, ít người lui tới. Tuy nhiên, niềm vui nhanh chóng tan biến khi Haruaki phát hiện ngôi trường mới của mình thực chất là &quot;đại bản doanh&quot; của bọn yêu quái, bao gồm cả ma cà rồng!</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ryota Osaka","avatar":""},{"name":"Ryota Suzuki","avatar":""},{"name":"Reon Tanie","avatar":""},{"name":"Taito Ban","avatar":""},{"name":"Akari Kito","avatar":""},{"name":"Shun Horie","avatar":""},{"name":"Ryota Iwasaki","avatar":""},{"name":"Jun Fukuyama","avatar":""},{"name":"Hana Ayasaka","avatar":""},{"name":"Akira Takano","avatar":""},{"name":"Yuki Sakakihara","avatar":""},{"name":"Takao Mitsutomi","avatar":""},{"name":"Tomokazu Sugita","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["¡Empecé a trabajar como profesor en una escuela de monstruos!","妖怪学校的新人教师","妖怪学校的菜鸟教师","یک معلم وحشت‌زده در مدرسه غول‌ها!","معلم وحشت‌زده مدرسه غول‌ها","Youkai Gakkou no Sensei Hajimemashita!","Yohaji","妖怪学校の先生はじめました！"]', 1784690324180);
