INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tro-thanh-giao-vien-tai-truong-hoc-quai-vat', 'Trở Thành Giáo Viên Tại Trường Học Quái Vật', 'A Terrified Teacher At Ghoul School', 'trở thành giáo viên tại trường học quái vật a terrified teacher at ghoul school ryota osaka ryota suzuki reon tanie taito ban akari kito shun horie ryota iwasaki jun fukuyama hana ayasaka akira takano yuki sakakihara takao mitsutomi tomokazu sugita ¡empecé a trabajar como profesor en una escuela de monstruos! 妖怪学校的新人教师 妖怪学校的菜鸟教师 یک معلم وحشت‌زده در مدرسه غول‌ها! معلم وحشت‌زده مدرسه غول‌ها youkai gakkou no sensei hajimemashita! yohaji 妖怪学校の先生はじめました！', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tho-san-game-rac-phan-2', 'Thợ Săn Game Rác (Phần 2)', 'Shangri-La Frontier (Season 2)', 'https://phimimg.com/upload/vod/20241219-1/9ddd81c6f35c6db24d0e88f7b27a352b.jpg', 'https://phimimg.com/upload/vod/20241219-1/d24b17f1d5a98c281d3a9f09a601c66e.jpg', '<p>Nam sinh cao trung năm hai Rakurou Hizutome chỉ quan tâm đến một chuyện duy nhất là tìm ra &quot;những trò chơi tồi tệ&quot; và phá đảo chúng. Kỹ năng chơi game của anh đã trở nên bất bại khi không ai sánh kịp và không còn trò chơi nào đủ tệ để anh có thể thưởng thức. Cho nên, khi được giới thiệu về một game VR mới Shangri-La Frontier, anh đã bước vào game ngay lập tức và bỏ qua cả hướng dẫn mở đầu dành cho tân binh. Nhưng liệu lão làng game thủ &quot;rank thách đấu&quot; có thể phá đảo những gì đang tồn tại trong Shangri-La Frontier?</p>', 'Hoàn Tất (25/25)', 25, 'hoathinh', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuma Uchida","avatar":""},{"name":"Azumi Waki","avatar":""},{"name":"Yoko Hikasa","avatar":""},{"name":"Makoto Koichi","avatar":""},{"name":"Rina Hidaka","avatar":""},{"name":"Akio Otsuka","avatar":""},{"name":"Seiichiro Yamashita","avatar":""},{"name":"Yumiri Hanamori","avatar":""},{"name":"Sayaka Senbongi","avatar":""},{"name":"Umeka Shouji","avatar":""},{"name":"Asaki Yuikawa","avatar":""},{"name":"Satomi Sato","avatar":""},{"name":"Megumi Han","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id"