INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhat-ky-hai-trinh-one-piece-truyen-ky-dao-nguoi-ca', 'Nhật Ký Hải Trình: One Piece Truyền Kỳ Đảo Người Cá', 'One Piece Log: Fish-Man Island Saga', 'https://phimimg.com/upload/vod/20241114-1/d0dd76a6d1828df65fca9fcb141e8f9a.jpg', 'https://phimimg.com/upload/vod/20241114-1/b145f04a857ff4f425308b1592da0cf0.jpg', '<p>Phiên bản đặc biệt đã chỉnh sửa - One Piece: Fish-Man Island Saga là phiên bản chỉnh sửa và cô đọng của bảnchuyển thể anime One Piece của Fish-Man Island Saga . Hiện tại, phim đang được phát sóng trong thời gian nghỉ năm tháng của anime gốc từ ngày 3 tháng 11 năm 2024, [1] đến ngày 6 tháng 4 năm 2025, trước khi bộ phim chuyển sang khung giờ mới. [2] Số tập phim sẽ được cô đọng từ 57 xuống còn 21.</p>', 'Tập 21', 99, 'hoathinh', 'ongoing', 8, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '[]', 1784690324180);
