INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ket-duyen-voi-chi-em-nha-amagami', 'Duyên Nợ Nhà Amagami', 'Tying the Knot with an Amagami Sister', 'https://phimimg.com/upload/vod/20250307-1/bddf62726c61cd72328fcb3ccadedd15.jpg', 'https://phimimg.com/upload/vod/20250307-1/cacaf3185c56dfe54c45330a2f37bfb9.jpg', '<p>Uryu Kamihate là một học sinh trung học với ước mơ vào trường y Đại học Kyoto. Sau khi được vị chủ tế tại Đền Amagami cưu mang, cậu được cho biết mình phải kết hôn với một trong ba chị em gái - Yae, Yuna, hoặc Asahi - để sống tại đó và một ngày nào đó sẽ thừa kế Đền Amagami. Kamihate sẽ cần phải chinh phục trái tim của một trong ba cô gái trong câu chuyện về tình yêu, tình bạn và niềm vui này.</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Ryota Suzuki","avatar":""},{"name":"Sumire Uesaka","avatar":""},{"name":"Kaede Hondo","avatar":""},{"name":"Shion Wakayama","avatar":""},{"name":"Nana Mizuki","avatar":""},{"name":"Chika Anzai","avatar":""},{"name":"Yui Horie","avatar":""},{"name":"Koji Yusa","avatar":""},{"name":"Ayasa Ito","avatar":""},{"name":"Haruka Shiraishi","avatar":""},{"name":"Natsuko Abe","avatar":""},{"name":"Bin Shimada","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["缘结甘神家","结缘甘神神社","Amagami-san Chi no Enmusubi","Tying the Knot with an Amagami Sister","अमागामी बहन के साथ शादी करना","Amagamisan Chi no Enmusubi","Весілля з сестрою Амаґамі","Matchmaking of the Amagami Household","How I Married an Amagami Sister","甘神さんちの縁結び"]', 1784690324180);
