INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-san-ky-bi', 'Di Sản Kỳ Bí', 'The Bequeathed', 'https://phimimg.com/upload/vod/20240119-1/e97ab38a6e482d1d746b26e1a701e7b9.jpg', 'https://phimimg.com/upload/vod/20240119-1/330753ed6f75e3d42b96e995b44c4d3f.jpg', '<p>Sau cái chết của một người chú vô danh, một người phụ nữ thừa kế một khu chôn cất và thấy mình là trung tâm của một chuỗi vụ giết người và những bí mật đen tối.</p>', 'Hoàn Tất (6/6)', 6, 'series', 'completed', 8, 2024, 'Vietsub + Lồng Tiếng', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Hyun-joo","avatar":""},{"name":"Park Hee-soon","avatar":""},{"name":"Park Byung-eun","avatar":""},{"name":"Ryu Kyung-soo","avatar":""},{"name":"Park Sung-hoon","avatar":""},{"name":"Hyun Bong-sik","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '[]', 1784690324180);
