INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('niem-vo-song-ban-hoat-hinh', 'Niệm Vô Song (Bản Hoạt Hình)', 'A Moment But Forever', 'https://phimimg.com/upload/vod/20240816-1/9531e92fe58373dd1e26c0d709ce19d5.jpg', 'https://phimimg.com/upload/vod/20240816-1/fd5054ba06aeb6c4a5cd7888c8f32a03.jpg', '<p>Để lấy lại bảo vật của thần giới, thần nữ Vô Song hạ phàm thích sát Đai tế tư Nguyên Trọng của Hồ tộc. Nhưng sau đó, nàng lại phát hiện trong chuyện này có ẩn tình. Trong quá trình điều tra, hai người nảy sinh tình cảm với nhau, đồng thời cùng nhau cứu lấy thế giới.</p>', 'Hoàn Tất (14/14)', 14, 'hoathinh', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324180);
