INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tim-kiem-tai-nang-am-phu', 'Tìm Kiếm Tài Năng Âm Phủ', 'Dead Talents Society', 'https://phimimg.com/upload/vod/20250327-1/3e4646fe0aacbcd7830fc61e68c21732.jpg', 'https://phimimg.com/upload/vod/20250327-1/e05a8e3145bc4f7ff12ed096148853c6.jpg', '<p>Sinh ra là một con người đã đủ khó khăn, nhưng hóa ra trở thành một hồn ma cũng không hề dễ dàng. Newbie - một hồn ma mới, kinh hoàng nhận ra rằng cô chỉ còn 28 ngày nữa cho đến khi linh hồn của cô biến mất khỏi thế giới. Makoto, một “chuyên viên ám quẻ” tiếp cận Newbie với lời đề nghị kết hợp cùng ngôi sao ma Catherine để dựng lại câu chuyện kinh dị huyền thoại về khách sạn Wang Lai. Nếu câu chuyện đủ sức hù dọa người sống thì cái tên của cô sẽ trở thành huyền thoại và linh hồn của Newbie sẽ tiếp tục được sống dưới địa ngục mà không bị tan biến vĩnh viễn.</p>', 'Full', 1, 'single', 'completed', 14, 2024, 'Vietsub', 'FHD', 'Đài Loan', 1, '[{"name":"Chen Bolin","avatar":""},{"name":"Sandrine Pinna","avatar":""},{"name":"Gingle Wang","avatar":""},{"name":"Yao Yi Ti","avatar":""},{"name":"Bai Jing-yi","avatar":""},{"name":"Soso Tseng","avatar":""},{"name":"Ya-Ling Chang","avatar":""},{"name":"Lin He-Hsuan","avatar":""},{"name":"Hau-Ping Huang","avatar":""},{"name":"Hannah Tung","avatar":""},{"name":"McFly Wu","avatar":""},{"name":"Huang Di-yang","avatar":""},{"name":"Milia Luo","avatar":""},{"name":"Tiffany Anais Lin","avatar":""},{"name":"Chang-Ying Hsieh","avatar":""},{"name":"Peace Yang","avatar":""},{"name":"Lung Hor","avatar":""},{"name":"Geifan","avatar":""},{"name":"Jaw Cheng Hung","avatar":""},{"name":"W","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1