INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('modi-ba-ngay-tren-doi-canh-mong-ao', 'Modì: Ba Ngày Trên Đôi Cánh Mộng Ảo', 'Modì, Three Days on the Wing of Madness', 'https://phimimg.com/upload/vod/20250326-1/790788be6e07df58a4e18946b587832a.jpg', 'https://phimimg.com/upload/vod/20250326-1/1a03c4e09a862d301154153bb7a88a57.jpg', '<p>Bộ phim theo chân 72 giờ đầy biến động trong cuộc đời của họa sĩ Amedeo Modigliani giữa Paris thời chiến năm 1916. Khi bị cảnh sát truy đuổi và muốn rời bỏ sự nghiệp, ông bị bạn bè ngăn cản. Trong cơn khủng hoảng, ông tìm đến người buôn tranh để tìm lối thoát, nhưng những ảo giác và sự hỗn loạn trong tâm trí ngày càng dâng cao. Đỉnh điểm là khi ông gặp một nhà sưu tầm nghệ thuật người Mỹ, người có thể thay đổi số phận ông mãi mãi.</p>', 'Full', 1, 'single', 'completed', 14, 2024, 'Vietsub', 'FHD', 'Ý', 0, '[{"name":"Riccardo Scamarcio","avatar":""},{"name":"Antonia Desplat","avatar":""},{"name":"Al Pacino","avatar":""},{"name":"Stephen Graham","avatar":""},{"name":"Benjamin Lavernhe","avatar":""},{"name":"Bruno Gouery","avatar":""},{"name":"Ryan McParland","avatar":""},{"name":"Sally Phillips","avatar":""},{"name":"Eva Jane Willis","avatar":""},{"name":"Luisa Ranieri","avatar":""},{"name":"G. Maximilian Zarou","avatar":""},{"name":"Hugo Nicolau","avatar":""},{"name":"Kat Fairaway","avatar":""},{"name":"Eddie Loodmer-Elliott","avatar":""},{"name":"C.J. Byrnes","avatar":""},{"name":"Kembe Sor","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"}]', '["Modìgliani: Three Days on the Wing of Madness","Modi, Three Days on the Wing of Madness"]', 1784690324180);
