INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('toi-nho-nho', 'Tôi Nho Nhỏ', 'Big World', 'https://phimimg.com/upload/vod/20250204-1/3dfb5798343f6edbc9e23124f7bd945f.jpg', 'https://phimimg.com/upload/vod/20250204-1/f493a74f2bbf4182102b270569070b9a.jpg', '<p>Chàng trai trẻ bị bại não nọ cố gắng giúp bà mình thực hiện ước mơ đứng trên sân khấu đã ấp ủ từ lâu, đồng thời hàn gắn các mối quan hệ gia đình và tìm ra con đường của riêng mình.</p>', 'Full', 1, 'single', 'completed', 9, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Dịch Dương Thiên Tỉ","avatar":""},{"name":"Lâm Hiểu Kiệt","avatar":""},{"name":"Tưởng Cần Cần","avatar":""},{"name":"Châu Vũ Đồng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"}]', '["Xiao Xiao De Wo","작고작은 나","Big World","小小的我"]', 1784690324181);
