INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('mujigae', 'Mujigae', 'Mujigae', 'mujigae mujigae kim ji-soo alexa ilacad ryrie sophia rufa mae quinto richard quan kate alejandrino donna cariaga cai cortez roli inocencio anna luna lui manansala peewee o''hara mujigae', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-sam-hoi-muon-mang', 'Lời Sám Hối Muộn Màng', 'The Redemption Of Sin', 'https://phimimg.com/upload/vod/20250324-1/35c57744b688a9572d2879b3e43f45b1.jpg', 'https://phimimg.com/upload/vod/20250324-1/3f18fe359ceb0a8bf1a33bd143758ca7.jpg', '<p>Wening, một người mẹ đơn thân, rơi vào bi kịch khi con gái cô – Nirmala, 11 tuổi – mất tích sau một vụ tai nạn xe máy trên cây cầu định mệnh. Tai nạn ấy cũng đã cướp đi sinh mạng của Uti Yah, mẹ ruột của Wening. Dằn vặt trong tội lỗi vì vừa làm mất mẹ, vừa khiến con gái trôi theo dòng sông, Wening vẫn không từ bỏ niềm tin rằng Nirmala còn sống. Một nữ podcaster chuyên kể chuyện kỳ bí tên Tirta quyết định lan tỏa câu chuyện thương tâm của Wening lên mạng. Thế nhưng, hành động giúp đỡ ấy lại vô tình kéo Tirta vào vòng xoáy những bí mật đen tối trong quá khứ của Wening – chính những bí mật ấy có thể là nguyên nhân thật sự khiến Nirmala biến mất. Với tất cả hy vọng và nỗ lực, Wening lên đường tìm con, nhờ đến sự giúp đỡ của Tetsuya, một nhà nghiên cứu đến từ Nhật Bản, và Mbah Gowa, một pháp sư bí ẩn. Thế nhưng trong suốt hành trình, Wening liên tục bị hồn ma của mẹ mình – Uti Yah – tìm đến và ám ảnh. Liệu Wening có thể tìm lại được Nirmala và đoàn tụ cùng con gái? Hay tất cả chỉ là một ảo vọng bị ma quỷ dẫn lối?</p>', 'Full', 1, 'single', 'completed', 14, 2024, 'Vietsub', 'FHD', 'Indonesia', 0, '[{"name":"Happy Salma","avatar":""},{"name":"Putri Marino","avatar":""},{"name":"Shogen","avatar":""},{"name":"Keiko Ananta","avatar":""},{"name":"Bhisma Mulia","avatar":""},{"name":"Laksmi Notokusumo","avatar":""},{"name":"Bambang Gundul","avatar":""},{"name":"Haru Sandra","avatar":""},{"name":"Eduwart Manalu","avatar":""},{"name":"Noel Kefas","avatar":""},{"name":"M. Dinu Imansyah","avatar":""},{"name":"Eza Yoga","avatar":""},{"name":"Sulis Kusuma","avatar":""},{"name":"Arya Sweta","avatar":""},{"name":"Joanna Dyah","avatar":""},{"name":"Fabyan Barrayudha Pratama","avatar":""},{"name":"Nizar Azza Faezya","avatar":""},{"name":"Mao","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Tebusan Dosa"]', 1784690324181);
