INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('loi-sam-hoi-muon-mang', 'Lời Sám Hối Muộn Màng', 'The Redemption Of Sin', 'lời sám hối muộn màng the redemption of sin happy salma putri marino shogen keiko ananta bhisma mulia laksmi notokusumo bambang gundul haru sandra eduwart manalu noel kefas m. dinu imansyah eza yoga sulis kusuma arya sweta joanna dyah fabyan barrayudha pratama nizar azza faezya mao tebusan dosa', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('loi-nguyen-hac-am-bay-bien', 'Lời Nguyền Hắc Ám Bảy Biển', 'Curse Of The Seven Seas', 'https://phimimg.com/upload/vod/20250324-1/3a80851038bd0e59406017d9ff21838c.jpg', 'https://phimimg.com/upload/vod/20250324-1/cf3709d75737e2b37eb9d5a5ef0aebcd.jpg', '<p>Kể từ khi người cha phát hiện một gói đồ bí ẩn và nghe thấy những âm thanh rùng rợn từ một bộ tộc bí ẩn nơi rừng sâu, Ardi cùng gia đình bắt đầu trải qua những hiện tượng kỳ lạ. Sucipto (cha), Marni (mẹ), và Arif (em trai) lần lượt đổ bệnh một cách kỳ lạ. Ardi và em gái Syifa tin rằng đây là một cuộc tấn công bằng bùa ngải, và hai người họ chính là những nạn nhân tiếp theo. Đó là một loại santet (tà thuật) cấp cao đến từ ngoài vùng đất Java – được gọi là Santet Segoro Pitu.</p>', 'Full', 1, 'single', 'completed', 14, 2024, 'Vietsub', 'FHD', 'Indonesia', 0, '[{"name":"Ari Irham","avatar":""},{"name":"Sandrinna Michelle","avatar":""},{"name":"Christian Sugiono","avatar":""},{"name":"Sara Wijayanto","avatar":""},{"name":"Agus Firmansyah","avatar":""},{"name":"Erwin Moron","avatar":""},{"name":"Eduwart Manalu","avatar":""},{"name":"Khalif Al Juna","avatar":""},{"name":"Monica Jauwry","avatar":""},{"name":"Dinda Arinie","avatar":""},{"name":"Dimar Han","avatar":""},{"name":"Manuel Pribadi","avatar":""},{"name":"Sri Siswati","avatar":""},{"name":"Luthi Saputra","avatar":""},{"name":"Chiara","avatar":""},{"name":"Yati Surachman","avatar":""},{"name":"Chaca Amanda","avatar":""},{"name":"Dewi","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["ฅนปล่อยของ","បណ្ដាសាមហាសមុទ្រទាំង៧","Curse of the Seven Oceans","Santet Segoro Pitu"]', 1784690324181);
