INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('loi-nguyen-hac-am-bay-bien', 'Lời Nguyền Hắc Ám Bảy Biển', 'Curse Of The Seven Seas', 'lời nguyền hắc ám bảy biển curse of the seven seas ari irham sandrinna michelle christian sugiono sara wijayanto agus firmansyah erwin moron eduwart manalu khalif al juna monica jauwry dinda arinie dimar han manuel pribadi sri siswati luthi saputra chiara yati surachman chaca amanda dewi ฅนปล่อยของ បណ្ដាសាមហាសមុទ្រទាំង៧ curse of the seven oceans santet segoro pitu', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-dich-chon-phu-hoa', 'Đại Dịch Chốn Phù Hoa', 'Rich Flu', 'https://phimimg.com/upload/vod/20250323-1/efc2fc6ae07504f72fc4335d9791a22d.jpg', 'https://phimimg.com/upload/vod/20250323-1/a827c430d99a3ad3294664df40bb74bc.jpg', '<p>Một đại dịch bí ẩn quét qua giới siêu giàu, giết chết các tỷ phú, triệu phú và dần dần đe dọa bất kỳ ai có tài sản. Khi nỗi sợ hãi lan rộng, thị trường tài chính rơi vào hỗn loạn khi mọi người tuyệt vọng tìm cách thoát khỏi sự giàu có của mình, thứ vốn từng là quyền lực, giờ lại trở thành bản án tử.</p>', 'Full', 1, 'single', 'completed', 16, 2024, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Mary Elizabeth Winstead","avatar":""},{"name":"Rafe Spall","avatar":""},{"name":"Lorraine Bracco","avatar":""},{"name":"Dixie Egerickx","avatar":""},{"name":"César Domboy","avatar":""},{"name":"Timothy Spall","avatar":""},{"name":"Jonah Hauer-King","avatar":""},{"name":"Dayana Esebe","avatar":""},{"name":"Richard Sammel","avatar":""},{"name":"Alexandra Masangkay","avatar":""},{"name":"Greg Orvis","avatar":""},{"name":"Michael John Treanor","avatar":""},{"name":"Diogo Sales","avatar":""},{"name":"Bernard Bullen","avatar":""},{"name":"Philip Schurer","avatar":""},{"name":"Michael","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["富贵病","钱流感","La fiebre de los ricos"]', 1784690324181);
