INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dai-dich-chon-phu-hoa', 'Đại Dịch Chốn Phù Hoa', 'Rich Flu', 'đại dịch chốn phù hoa rich flu mary elizabeth winstead rafe spall lorraine bracco dixie egerickx césar domboy timothy spall jonah hauer-king dayana esebe richard sammel alexandra masangkay greg orvis michael john treanor diogo sales bernard bullen philip schurer michael 富贵病 钱流感 la fiebre de los ricos', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-xin-loi-dau-nhe', 'Không Xin Lỗi Đâu Nhé', 'Sorry Not Sorry', 'https://phimimg.com/upload/vod/20241207-1/2444d9e607af9eae34a280a65bdd29b6.jpg', 'https://phimimg.com/upload/vod/20241207-1/86a91df72206cd4d486725751c37bf5a.jpg', '<p>Không Xin Lỗi Đâu Nhé - Sorry Not Sorry kể về Song Yi, một cô gái bị bạn trai lừa dối ngay trước khi kết hôn, khiến cô trở thành &quot;đã ly hôn&quot; trước cả khi cưới. Để trả nợ, cô nhận chăm sóc cháu trai và trở thành &quot;mẹ giả&quot; của một cậu bé 5 tuổi. Trong hành trình đó, Song Yi phải đối mặt với những mối quan hệ phức tạp, từ luật sư ly hôn, chủ quán cà phê trẻ tuổi, đến người chồng cũ và các buổi xem mắt. Bộ phim mang đến câu chuyện hài hước và cảm động về tình yêu và cuộc sống.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Jeon So-min","avatar":""},{"name":"Gong Min-jeung","avatar":""},{"name":"Jang Hui-ryeong","avatar":""},{"name":"Choi Daniel","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["هیچم پشیمون نیستم","ببخشید که متاسف نیستم","اسفة ولكنني لست اسفة","오늘도 지송합니다"]', 1784690324181);
