INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khong-xin-loi-dau-nhe', 'Không Xin Lỗi Đâu Nhé', 'Sorry Not Sorry', 'không xin lỗi đâu nhé sorry not sorry jeon so-min gong min-jeung jang hui-ryeong choi daniel هیچم پشیمون نیستم ببخشید که متاسف نیستم اسفة ولكنني لست اسفة 오늘도 지송합니다', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-nay-lam-chuyen-ay-nhe', 'Đêm Nay Làm Chuyện Ấy Nhé', 'Us Without Sex', 'https://phimimg.com/upload/vod/20250321-1/54d6c1636d2a6331a0b3990bc45086f0.jpg', 'https://phimimg.com/upload/vod/20250321-1/761413c59189802fe1767cafad1de437.jpg', '<p>Trương Gia Trân (do Dương Cẩn Hoa thủ vai) – một chuyên gia trị liệu tình dục đầy tự tin và phóng khoáng – đang đối mặt với khủng hoảng trong sự nghiệp, đồng thời cũng lạc lối trong chuyện tình cảm. Trong khi đó, Tống Thanh Vũ (do Ella Trần Gia Hoa thủ vai) – một người phụ nữ nhạy cảm và trầm lặng – sống trong cuộc hôn nhân tưởng như viên mãn, nhưng lại không thể quan hệ thể xác với chồng. Hai người phụ nữ với hai tính cách trái ngược, trên hành trình khám phá bản thân và tình dục, dần tìm thấy sự cứu rỗi của tình yêu.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 14, 2024, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Cheryl Yang","avatar":""},{"name":"Ella Chen Chia-hwa","avatar":""},{"name":"Tony Yang","avatar":""},{"name":"Wang Bo-chieh","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["今夜一起为爱鼓掌","今夜一起為愛鼓掌"]', 1784690324181);
