INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dem-nay-lam-chuyen-ay-nhe', 'Đêm Nay Làm Chuyện Ấy Nhé', 'Us Without Sex', 'đêm nay làm chuyện ấy nhé us without sex cheryl yang ella chen chia-hwa tony yang wang bo-chieh 今夜一起为爱鼓掌 今夜一起為愛鼓掌', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chung-ta-khong-hoan-hao', 'Chúng Ta Không Hoàn Hảo', 'Imperfect Us', 'https://phimimg.com/upload/vod/20250321-1/4cee33ac170fd7115c87b6d6ee69b3aa.jpg', 'https://phimimg.com/upload/vod/20250321-1/a5d5cbd4b791d60b2120a04e77aa633a.jpg', '<p>Giản Khánh Phân – người phụ nữ sắp bước qua tuổi 40 – có một gia đình tưởng chừng hoàn hảo: chồng yêu thương, con ngoan ngoãn, cuộc sống yên ổn không thiếu thốn điều gì. Nhưng chính sự lặp lại nhàm chán mỗi ngày khiến cô cảm thấy trống rỗng, khao khát một điều gì đó mới mẻ, một mục tiêu để trái tim được đánh thức. Trong lúc nhâm nhi ly rượu vang, cô bỗng nhớ đến Rebecca – đồng nghiệp cũ từng là &quot;đối thủ ngầm&quot; khi mới đi làm. Hai người sinh cùng ngày, hay vô tình mặc trùng đồ, thậm chí gu đàn ông cũng giống nhau. Bị thôi thúc bởi sự tò mò, Khánh Phân tìm tên Rebecca trên mạng và phát hiện cuộc sống của cô ta giờ đây thật rực rỡ: tự do, vui vẻ, thường xuyên chia sẻ cảm xúc trên mạng xã hội, bạn trai lại còn trẻ trung và quyến rũ. Mỗi ngày của Rebecca đều như một cuộc phiêu lưu đầy màu sắc. Khánh Phân cảm thấy không cam lòng. Trong trò chơi mang tên &quot;cuộc đời&quot;, cô nhất định phải là người chiến thắng!</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 14, 2024, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Ariel Lin","avatar":""},{"name":"Tiffany Hsu Wei-Ning","avatar":""},{"name":"Mike He","avatar":""},{"name":"Kai Ko","avatar":""},{"name":"Lu Yi-ching","avatar":""},{"name":"Hsieh Ying-shiuan","avatar":""},{"name":"Johnny Lu","avatar":""},{"name":"Lawrence Ko Yu-Luen","avatar":""},{"name":"Kang In","avatar":""},{"name":"Gabriel Lan","avatar":""},{"name":"Ray Chang","avatar":""},{"name":"Amber An","avatar":""},{"name":"Joseph Hsia","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["不够善良的我们","不夠善良的我們"]', 1784690324181);
