INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('mon-tien-bao-dia', 'Môn Tiền Bảo Địa', '100 Yards', 'https://phimimg.com/upload/vod/20250305-1/2bbf611b26b9e0c01e4b37f9775d92b1.jpg', 'https://phimimg.com/upload/vod/20250305-1/740fa151d4103e4ec04b1204bdfe315a.jpg', '<p>Môn tiền bảo địa - 100 Yards (2024) Bối cảnh phim diễn ra tại Thiên Tân, Trung Quốc vào những năm 1920. Sau khi một võ sư nổi tiếng qua đời, hai học trò của ông trở thành đối thủ không đội trời chung để tranh giành quyền thừa kế võ đường. Một bên là Tề, đại đệ tử và người thừa kế được kỳ vọng, trong khi bên kia là Thẩm, con trai của sư phụ, người lẽ ra không theo nghiệp võ nhưng lại có đam mê mãnh liệt với nó. Cuộc tranh chấp được quyết định bằng võ đấu, nhưng kết quả chỉ làm tăng thêm mâu thuẫn. Khi những thách thức giữa họ ngày càng nhiều, các quy tắc truyền thống dần bị phá vỡ, gây chấn động cộng đồng võ thuật.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 1, '[{"name":"Jacky Heung","avatar":""},{"name":"Andy On Chi-Kit","avatar":""},{"name":"Bea Hayden Kuo","avatar":""},{"name":"Tang Shiyi","avatar":""},{"name":"Li Yuan","avatar":""},{"name":"Zhao Zheng","avatar":""},{"name":"Li Mei","avatar":""},{"name":"Kevin Lee","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["100 Yards","门前宝地"]', 1784690324181);
