INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('song-sot-trong-co-doc', 'Sống Sót Trong Cô Độc', 'Die Alone', 'https://phimimg.com/upload/vod/20250318-1/976bdc4bac1fde9982553f854fe28a7e.jpg', 'https://phimimg.com/upload/vod/20250318-1/6c68f4eb6f8bc243eb2346ccaa3fc99f.jpg', '<p>Trong một thế giới hậu tận thế bị tàn phá bởi virus biến con người thành quái vật lai thực vật, Ethan—một kẻ mất trí nhớ—tuyệt vọng tìm kiếm bạn gái mất tích. Được Mae, một người sống sót bí ẩn, cưu mang, anh dần khám phá sự thật kinh hoàng: chính anh cũng đang biến đổi. Khi ký ức trở lại, Ethan nhận ra Mae không phải ai khác mà chính là Emma—người anh từng yêu. Nhưng sự thật tàn nhẫn hơn: suốt thời gian qua, cô đã nuôi sống anh bằng thịt người để giữ lại chút nhân tính mong manh.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Carrie-Anne Moss","avatar":""},{"name":"Douglas Smith","avatar":""},{"name":"Frank Grillo","avatar":""},{"name":"Kimberly-Sue Murray","avatar":""},{"name":"Jonathan Cherry","avatar":""},{"name":"Amy Matysio","avatar":""},{"name":"Steven Roy","avatar":""},{"name":"Harlan Blayne Kytwayhat","avatar":""},{"name":"Sari Mercer","avatar":""},{"name":"Leo Fafard","avatar":""},{"name":"Laura Abramsen","avatar":""},{"name":"Ryland Alexander","avatar":""},{"name":"Jason Truong","avatar":""},{"name":"Palmer Tastad","avatar":""},{"name":"George Grassick","avatar":""},{"name":"Greyson Dubois","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["تنها بمیر"