INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('thame-po-nhip-dap-con-tim', 'Thame Po: Nhịp Đập Con Tim', 'Thame Po: Heart That Skips A Beat', 'thame po: nhịp đập con tim thame po: heart that skips a beat william jakrapatr kaewpanpong supha sangaworawong rapeepong supatineekitdecha pichetpong chiradatesakunvong nut thanat danjesda tui chayatorn trairattanapradit yongwaree anilbol samantha melanie coates rutricha phapakithi leo saussay sattabut la 谭米-阿珀的心漏跳了一拍 心跳为你停 心跳为你漏跳一拍 心动漏拍 错拍心动 tps thame po thame po series thame - po heart that skips a beat थेमपो: दिल जो एक धड़कन छोड़ देता है 落拍的心 心跳節拍 เธมโป้ heart that skips a beat', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-kiem-ky-hiep-6-ky-kim-trieu', 'Tiên Kiếm Kỳ Hiệp 6: Kỳ Kim Triêu', 'Sword And Fairy 6', 'https://phimimg.com/upload/vod/20240206-1/2bb81451eb1158f3b0e10336f1d231c7.jpg', 'https://phimimg.com/upload/vod/20240206-1/dfc5c0656387d214552d5338372b3dcd.jpg', '<p>Kỳ Kim Triêu là phần mới nhất trong loạt phim truyền hình được chuyển thể từ tựa game nổi tiếng Tiên Kiếm Kỳ Hiệp Truyện. Chàng thanh niên Việt Kim Triêu cùng nghĩa muội Việt Kỳ ngao du chốn giang hồ để tìm hiểu thân thế của mình. Trong hành trình đó, họ bị cuốn vào hàng loạt các sự kiện bí ẩn cũng như gặp gỡ nhiều nhân vật thú vị chốn giang hồ. Qua mỗi cuộc chạm trán, thân phận thực sự của hai người dần được hé lộ, đẩy Việt Kỳ vào chặng đường chông gai nhất của cuộc đời mình.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 8, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hứa Khải","avatar":""},{"name":"Ngu Thư Hân","avatar":""},{"name":"Vạn Bằng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '[]', 1784690324181);
