INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tien-kiem-ky-hiep-4', 'Tiên Kiếm Kỳ Hiệp 4', 'Sword And Fairy 4', 'https://phimimg.com/upload/vod/20240123-1/3372332c572ae5ae47dc998bd82e5d28.jpg', 'https://phimimg.com/upload/vod/20240123-1/a93b5bd3946f6b07ca80ffad9c5578ed.jpg', '<p>Tiên Kiếm Kỳ Hiệp 4 kể về câu chuyện của Vân Thiên Hà và Hàn Lăng Sa. Mười chín năm trước, Quỳnh Hoa phái lợi dụng tình hình chiếm lấy linh lực, gây ra cuộc chiến lớn giữa người và yêu, cả hai bên đều chịu tổn thất nặng nề. Đệ tử của Quỳnh Hoa Hoa phái, Vân Thiên Thanh và Tố Ngọc do có sự khác biệt về triết lý tu luyện mà cùng nhau rời đi đến Thanh Loan Phong sinh hạ một con trai Vân Thiên Hà. Không lâu sau, Tố Ngọc qua đời. Vân Thiên Hà khi còn nhỏ không hiểu rõ về quá khứ của cha mẹ, một mình lớn lên trên núi. Vân Thiên Hà gặp gỡ thiếu nữ Hàn Lăng Sa trong quá trình đột nhập vào mộ phần trên núi, để rồi cả hai cùng nhau xuống núi tìm hiểu về quá khứ của cha mẹ Vân Thiên Hà. Sau đó họ đã gặp một cô gái khác là Lục Mộng Lệ. Để hiểu rõ về quá khứ của cha, Vân Thiên Hà và Hàn Lăng Sa, Lục Mộng Lệ cùng nhau nhập môn trở thành đệ tử phái Quỳnh Hoa. Tại đây họ gặp Mục Dung Tử Anh, bốn người trở thành bạn đồng hành.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 8, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Triết Viễn","avatar":""},{"name":"Cúc Tịnh Y","avatar":""},{"name":"Mao Tử Tuấn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '[]', 1784690324181);
