INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngon-lua-trong-toi', 'Ngọn Lửa Trong Tôi', 'The Fire Inside', 'https://phimimg.com/upload/vod/20250314-1/726be3507db858288c683c396dced0d1.jpg', 'https://phimimg.com/upload/vod/20250314-1/640ebeeedae2eccd19db3a665469088f.jpg', '<p>Phim kể về hành trình của võ sĩ quyền Anh Claressa &quot;T-Rex&quot; Shields từ Flint, Michigan, trở thành người phụ nữ Mỹ đầu tiên giành huy chương vàng Olympic trong môn quyền Anh. Bộ phim bắt đầu với hình ảnh Claressa Shields, một cô bé 11 tuổi sống tại Flint, Michigan, chạy đến phòng tập của huấn luyện viên Jason Crutchfield với mong muốn học quyền Anh. Ban đầu, Jason từ chối vì không huấn luyện nữ giới, nhưng sau khi chứng kiến sự quyết tâm và tài năng của Claressa, ông đã đồng ý huấn luyện cô. Dưới sự hướng dẫn nghiêm khắc nhưng tận tâm của Jason, Claressa vượt qua nhiều khó khăn cá nhân và xã hội để đạt được thành công trong sự nghiệp quyền Anh. Bộ phim không chỉ tập trung vào những chiến thắng của Claressa mà còn khắc họa những thách thức cô phải đối mặt sau khi đạt được đỉnh cao</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ryan Destiny","avatar":""},{"name":"Brian Tyree Henry","avatar":""},{"name":"Oluniké Adeliyi","avatar":""},{"name":"Kylee D. Allen","avatar":""},{"name":"Emmanuel Igboke","avatar":""},{"name":"Lanette Ware","avatar":""},{"name":"Amanda Barker","avatar":""},{"name":"De''Adre Aziza","avatar":""},{"name":"Adam Clark","avatar":""},{"name":"Jessica Grossi","avatar":""},{"name":"Michael Brown","avatar":""},{"name":"Tyrone Benskin","avatar":""},{"name":"Cynthia Zhou","avatar":""},{"name":"Jazmin Headley","avatar":""},{"name":"Chrystian Buddington","avatar":""},{"name":"Maurice Wayn","avatar":""}]', '[{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Flint Strong","内心之火","心火","The Fire Inside","La fuerza de una campeona"]', 1784690324181);
