INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kiem-soat-tuyet-doi', 'Kiểm Soát Tuyệt Đối', 'Eternal Butler', 'https://phimimg.com/upload/vod/20250109-1/4f42997e6f364deddfb11965d31009b0.jpg', 'https://phimimg.com/upload/vod/20250109-1/d3d56cd6d76a9018e6794ccfe89a1840.jpg', '<p>Khi một robot AI phức tạp biến thành quản gia riêng của một người thừa kế trẻ hư hỏng, nó đã khắc họa một cách tuyệt vời câu chuyện tình yêu cảm động giữa AI và con người giữa các loài.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 19, 2024, 'Vietsub', 'FHD', 'Đài Loan', 0, '[{"name":"Kevin Chang","avatar":""},{"name":"Eden Chen","avatar":""},{"name":"Lawrence Lo","avatar":""},{"name":"Sing Hom","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["VBL系列《全面管控》","VBL Series - Eternal Butler","Anti Reset spin-off","Comprehensive Control","全面管控"]', 1784690324181);
