INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('kiem-soat-tuyet-doi', 'Kiểm Soát Tuyệt Đối', 'Eternal Butler', 'kiểm soát tuyệt đối eternal butler kevin chang eden chen lawrence lo sing hom vbl系列《全面管控》 vbl series - eternal butler anti reset spin-off comprehensive control 全面管控', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trong-long-dat-2024', 'Trong Lòng Đất', 'Việt And Nam', 'https://phimimg.com/upload/vod/20250313-1/d1431e7593519dad51b3668ee4442aa0.jpg', 'https://phimimg.com/upload/vod/20250313-1/85be7d7fb1affb29bf715b6a80f6bf42.jpg', '<p>Phim xoay quanh hai thợ mỏ là Nam và người yêu là Việt phải làm việc bên dưới lòng đất sâu 300 m, nơi được xem là chứa đầy nguy hiểm và bóng tối bao trùm. Lúc này, Nam không muốn tiếp tục tương lai của bản thân mình ở một nơi chỉ quanh quẩn là than đá nên đã nhờ những kẻ buôn người đưa mình đến phương Tây để đổi đời. Trước khi rời đi, Nam cùng với Việt và mẹ của anh đã đi tìm hài cốt của cha mình khi linh hồn cha anh là một người lính của Quân đội nhân dân Việt Nam báo mộng giấc mơ của mẹ. Tuy nhiên, sau cùng, cuộc tìm kiếm của họ lại không mang về kết quả nào. Sau đó, cả hai người phải quay về khu mỏ và bị mắc kẹt lại đây sau cơn mưa dữ dội. Tại đây, Nam chợt nhìn thấy được tương lai sắp tới của mình, bị nhốt trong thùng xe tải, trong bóng tối, trong cái nóng bức và ngột ngạt của quá khứ. Nam và Việt cả hai vẫn nằm cạnh nhau, cởi trần, nóng bức.</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"Phąm Thanh Hài","avatar":""},{"name":"Đào Duy Bảo Định","avatar":""},{"name":"Nguyên Thį Nga","avatar":""},{"name":"Lê Viêt Tųng","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["越與南","Viet i Nam","Trong lòng đất"]', 1784690324181);
