INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quai-vat-tap-kich', 'Quái Vật Tập Kích', 'The Monster Is Coming', 'https://phimimg.com/upload/vod/20250313-1/de9abbb3aca1804387d58adf7417192e.jpg', 'https://phimimg.com/upload/vod/20250313-1/9e0b0c02ce124d9d1b2e31fbb924858f.jpg', '<p>Trong tương lai không xa, đảo Chaos do hải phận quốc tế chung tay xây dựng rất giàu tài nguyên sinh thái và là vùng đất bình yên cuối cùng để các loài động vật hoang dã quý hiếm sinh sống. Trong một lần giao dịch, Khoa học kỹ thuật Tinder một tay che trời trên đảo vô tình làm sổng hai con quái vật đột biến gen, gây ra hàng loạt vụ tấn công con người. Không ai ngờ được, Tiểu Đình, con gái của nhà sinh vật học trẻ Tống Nam đã bị quái vật bắt đi trong lúc anh đang điều tra vụ việc. Không chỉ thế, hai con quái vật này còn có quan hệ bí mật với vợ cũ của anh là Châu Thiến. Nhiệm vụ tìm kiếm, chế ngự quái vật và giải cứu Tiểu Đình vô cùng gian khổ và cấp bách, thế nhưng Tống Nam lại vướng vào một âm mưu to lớn hơn...</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Zhang Haocheng","avatar":""},{"name":"Ao Lei","avatar":""},{"name":"Norman Tsui Siu-Keung","avatar":""},{"name":"Su Jing","avatar":""},{"name":"Yang Qingqian","avatar":""},{"name":"Ma Zhe","avatar":""},{"name":"Alexandre Robillard","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["怪物来袭"]', 1784690324181);
