INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('12-gio-cua-lua-gian', '12 Giờ Của Lửa Giận', 'Fury 12 Hours', 'https://phimimg.com/upload/vod/20250313-1/47c967937a6ed0506582e96e0a26b675.jpg', 'https://phimimg.com/upload/vod/20250313-1/531372020d2f804a76c5913dad1517fa.jpg', '<p>Một người lính Trung Quốc đã nghỉ hưu, Lei Jun, thấy mình đang chạy đua với thời gian khi một cuộc tấn công khủng bố nhắm vào cộng đồng người Hoa ở nước ngoài. Chỉ còn 12 giờ để hành động, anh phải dồn hết sức mạnh và lòng dũng cảm của mình để bảo vệ đồng bào của mình và sống sót trong tình thế thảm khốc.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub + Lồng Tiếng', 'FHD', 'Trung Quốc', 0, '[{"name":"Andy On Chi-Kit","avatar":""},{"name":"Ni Kexin","avatar":""},{"name":"Huafeng Chen","avatar":""},{"name":"Bi Xue","avatar":""},{"name":"Zheng Pang","avatar":""},{"name":"Yang Hanbin","avatar":""},{"name":"Zhen Qi","avatar":""},{"name":"Feng Qinchuan","avatar":""},{"name":"Liu Huiyi","avatar":""},{"name":"Xia Zixuan","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Fury 12 Hours","12 ساعت خشم","怒火十二小时"]', 1784690324181);
