INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hoi-uc-khong-ten-phan-2', 'Hồi Ức Không Tên (Phần 2)', 'Unnamed Memory (Season 2)', 'https://phimimg.com/upload/vod/20250313-1/73065be2148d2e85bafd50242c345f99.jpg', 'https://phimimg.com/upload/vod/20250313-1/a9e17e6f8570925a74ab29be15e15c80.jpg', '<p>“Chừng nào anh còn là chủ nhân của thanh kiếm đó và em còn là một phù thủy, rồi sẽ có một ngày anh thật sự phải giết em.”

Khi còn nhỏ, Oscar, Thái tử của Farsas đã bị nguyền là không thể có người nối dõi. Đến năm hai mươi tuổi, anh đã tới gặp Tinassha, phù thủy mạnh nhất lục địa này, để phá giải lời nguyền. Anh trở về đồng thời mang Tinassha theo cùng dưới tư cách một hộ vệ, và trong một năm tới khi hai người hết giao kèo, anh đã bị cuốn vào quá khứ của cô, và một vòng xoáy định mệnh còn lớn hơn thế.</p>', 'Hoàn Tất (10/10)', 10, 'hoathinh', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yoshiki Nakajima","avatar":""},{"name":"Atsumi Tanezaki","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Неназован спомен","Unnamed Memory Act.2","アンネームドメモリー","Unnamed Memory","Безіменна пам''ять","Hồi Ức Không Tên"]', 1784690324181);
