INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('chu-meo-cua-simon-phan-7', 'Chú Mèo Của Simon (Phần 7)', 'Simon''s Cat (Season 7)', 'https://phimimg.com/upload/vod/20250313-1/c7a85e265fc4a083b70e651a574522b3.jpg', 'https://phimimg.com/upload/vod/20250313-1/763adb84a96c6a42dd2b9ef8bdc380bb.jpg', '<p>Phim là những cuộc phiêu lưu dường như vô tận của chú mèo béo ú, thông minh và vô cùng nghịch ngợm nhà Simon. Là chú mèo luôn đói bụng, chú ta đã khiến cậu chủ Simon thường xuyên rơi vào các tình huống khó xử nhưng không kém phần vui nhộn.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Simon Tofield","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["西蒙和他的猫","Simon''s Cat"]', 1784690324181);
