INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('hon-ma-xac-me', 'Hồn Ma Xác Mẹ', 'Perewangan', 'https://phimimg.com/upload/vod/20250313-1/6b4cc443a8144fbcd3e4a0c9c6f3120d.jpg', 'https://phimimg.com/upload/vod/20250313-1/88b6fe86ca2f7ca4cbce1dddf770f192.jpg', '<p>Những sự kiện kỳ lạ ám ảnh cuộc sống của Maya và gia đình cô. Maya nghi ngờ dì và chú của mình, những người luôn nhăm nhe bán đi ngôi nhà được thừa kế từ ông bà của họ. Tuy nhiên, có một thế lực tà ác và mối nguy hiểm lớn hơn đang rình rập, xuất phát từ giao kèo với một sinh vật giúp gia đình đạt được sự giàu có qua nhiều thế hệ. Giờ đây, sinh vật này đang săn lùng gia đình Maya, đòi mạng sống của người họ yêu thương.</p>', 'Full', 1, 'single', 'completed', 13, 2024, 'Vietsub', 'FHD', 'Indonesia', 1, '[{"name":"Davina Karamoy","avatar":""},{"name":"Ully Triani","avatar":""},{"name":"Shanty","avatar":""},{"name":"Septian Dwicahyo","avatar":""},{"name":"Randy Danistha","avatar":""},{"name":"Eduwart Manalu","avatar":""},{"name":"Restu Triandy","avatar":""},{"name":"Dian Sidik","avatar":""},{"name":"Beby Evelyn","avatar":""},{"name":"Syifa Aulia","avatar":""},{"name":"Dewi Sri","avatar":""},{"name":"Raffan Al Aryan","avatar":""},{"name":"Dimar Hanafiah","avatar":""},{"name":"Toto Sudarman","avatar":""},{"name":"Amanda Gondowijoyo","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["បំណន់មរណៈ","Hồn Ma Xác Mẹ","Perewangan"]', 1784690324181);
