INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('hon-ma-xac-me', 'Hồn Ma Xác Mẹ', 'Perewangan', 'hồn ma xác mẹ perewangan davina karamoy ully triani shanty septian dwicahyo randy danistha eduwart manalu restu triandy dian sidik beby evelyn syifa aulia dewi sri raffan al aryan dimar hanafiah toto sudarman amanda gondowijoyo បំណន់មរណៈ hồn ma xác mẹ perewangan', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thua-hoan-ky', 'Thừa Hoan Ký', 'Best Choice Ever', 'https://phimimg.com/upload/vod/20240410-1/4a990416c042dad73004438c46aa25bb.jpg', 'https://phimimg.com/upload/vod/20240410-1/0fbbccd0c15e30db75fd7def27ceddff.jpg', '<p>Mạch Thừa Hoan, cô gái Thượng Hải sinh sau 1995 đồng ý kết hôn với bạn trai Tân Gia Lượng dưới sự thúc giục của mẹ cô là Lưu Uyển Ngọc. Tuy nhiên gia cảnh tốt của nhà họ Tân khiến mối quan hệ này mất cân bằng, đồng thời mẹ Mạch Thừa Hoan can thiệp quá sâu khiến họ nhanh chóng chia tay. Mạch Thừa Hoan vật lộn giữa sự hiếu thảo và được làm chính mình, dần thoát khỏi tình yêu thương áp đặt của mẹ cô, phấn đấu vươn lên trong công việc. Sự lột xác của cô được bà nội kế ghi nhận, giao trọng trách quản lý khách sạn cho cô. Trong quá trình hợp tác, cháu trai của bà nội kế là Diêu Chí Minh – một quản lý khách sạn chuyên nghiệp đã dần dần hiểu Thừa Hoan hơn, hai người trở thành đối tác làm việc, sát cánh bên nhau. Trong cuộc sống, Diêu Chí Minh được gia đình họ Mạch yêu thương, tình cảm với Mạch Thừa Hoan dần tốt đẹp. Cuối cùng, Mạch Thừa Hoan đã bước trên con đường trưởng thành thuộc về chính mình.</p>', 'Hoàn Tất (37/37)', 37, 'series', 'completed', 7, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Dương Tử","avatar":""},{"name":"Hứa Khải","avatar":""},{"name":"Ngưu Tuấn Phong","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324181);
