INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('di-tim-uoc-mo', 'Đi Tìm Ước Mơ', 'Dream In Heng Qin And Macau', 'https://phimimg.com/upload/vod/20250311-1/fff80c1da2cdf5e1153e5235095a09d3.jpg', 'https://phimimg.com/upload/vod/20250311-1/067956d203af4f26a3cab1d9198bc101.jpg', '<p>Sáu người Hồng Kong do cơ duyên trùng hợp đã đến đảo Hoành Cầm làm việc và trú ngụ, họ cùng nhau phát triển sự nghiệp, tình yêu, tình bạn, tương lai của họ thật tốt đẹp. Thi Lượng (Đàm Tuấn Ngạn) và cô vợ Trương Hy Du (Hồ Định Hân) đã kết hôn lâu năm, họ có một cuộc sống tốt đẹp ở Hoành Cầm, nhưng bởi chuyện sinh con, hai người đã xảy ra cãi vã, Hơn nữa Hy Du cho rằng Thi Lượng có ngoại tình. Giám đốc đối ngoại Châu Vinh Sân (Trần Triển Bàng), Phương Tư Tư (Lâm Hạ Vi) đối chọi nhau nơi công sở; Tư Tư suýt bị sập bẫy tình trên mạng, rất may được Vinh Sân giúp đỡ nên được an toàn; đối thủ cạnh tranh có thể biến địch thành bạn? Trang Nhã Du (Trương Hy Văn) tài sắc song toàn giao thiệp tình cảm giữa bạn trai Vinh Sân và công tử giàu có xinh trai Đổng Trác Nhiên (Mã Quốc Minh), đã gây nên những gợn sóng không thể ngờ tới...Đối mặt với những bước ngoặt cuộc đời, mọi người làm thế nào nhìn rõ phương hướng phía trước trong sự vật lộn và mê hoặc?</p>', 'Hoàn Tất (2/2)', 2, 'series', 'completed', 7, 2024, 'Lồng Tiếng', 'FHD', 'Hồng Kông', 0, '[{"name":"Đàm Tuấn Ngạn","avatar":""},{"name":"Hồ Định Hân","avatar":""},{"name":"Trần Triển Bằng","avatar":""},{"name":"Lâm Hạ Vy","avatar":""},{"name":"Mã Quốc Minh","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324181);
