INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('co-chau', 'Cô Châu', 'A Lonely Hero''s Journey', 'https://phimimg.com/upload/vod/20240809-1/05634fd58385307fd252f6f2ea3d0f37.jpg', 'https://phimimg.com/upload/vod/20240809-1/1804fa47619b59e996b7e2084504bb0a.jpg', '<p>Cô Châu&quot; là một bộ phim trinh thám do Lâm Lê Thắng đạo diễn, với sự tham gia của các diễn viên Tăng Thuấn Hy và Trương Tụng Văn, Trương Ninh Giang và các diễn viên khác. Trong phim, Cố Dị Trung (do Tăng Thuấn Hy thủ vai) - con trai của một gia đình ở Gia Tây, trở về nước sau khi tốt nghiệp ngành kiến trúc tại Đại học Pennsylvania. Sau khi xảy ra cuộc kháng chiến, toàn bộ liên lạc của tổ chức ngầm ở Gia Tây cũng bị phơi bày. Vì bị Nhật Bản và phản động đổ lỗi với mục đích hãm hại, Cố Dị Trung bị nhận nhầm là một phản động trong Đảng và không thể chứng minh mình vô tội. Trong tình huống không thể chứng minh rõ ràng sự trong sạch của mình, anh tự nguyện xâm nhập vào phe đối lập Nhật Bản và sau nhiều khó khăn cuối cùng trở thành một đặc vụ ngầm trong đội ngũ tình báo Đảng ở Gia Tây. i Nhật Bản, Cận Đường Lợi Nam, để phát hiện ra kẻ phản bội thật sự trong Đảng, và loại bỏ hắn.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 6, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Tăng Thuấn Hi","avatar":""},{"name":"Trương Tụng Văn","avatar":""},{"name":"Trần Đô Linh","avatar":""},{"name":"Vương Ngọc Văn","avatar":""},{"name":"Chu Nhất Vi","avatar":""}]', '[{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '[]', 1784690324181);
