INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-dien-hoa-le-cuoi-cung', 'Đêm Diễn Hoa Lệ Cuối Cùng', 'The Last Showgirl', 'https://phimimg.com/upload/vod/20250312-1/c2accd812b8cbff3605cc51a6e6a4f07.jpg', 'https://phimimg.com/upload/vod/20250312-1/620a27ad51244067f6e89b2b5dcfba46.jpg', '<p>Một vũ công kỳ cựu tại Las Vegas phải đối mặt với sự thay đổi khi chương trình biểu diễn vũ nữ mà cô gắn bó suốt nhiều thập kỷ sắp đóng cửa. Giữa những hoài niệm và lựa chọn trong quá khứ, cô tìm cách định hình tương lai và bước vào một hành trình mới.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Pamela Anderson","avatar":""},{"name":"Jamie Lee Curtis","avatar":""},{"name":"Dave Bautista","avatar":""},{"name":"Brenda Song","avatar":""},{"name":"Kiernan Shipka","avatar":""},{"name":"Billie Lourd","avatar":""},{"name":"John Clofine","avatar":""},{"name":"Jason Schwartzman","avatar":""},{"name":"Patrick Hilgart","avatar":""},{"name":"Jesse Phillips","avatar":""},{"name":"David Avne","avatar":""},{"name":"Sean Patrick Bryan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["فتاة الإستعراض الأخيرة","آخرین دختر نمایش","Son Şov Kızı","נערת השעשועים האחרונה","The Last Showgirl"]', 1784690324181);
