INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngai-quy', 'Ngài Quỷ', 'Devils Stay', 'https://phimimg.com/upload/vod/20241218-1/1d913430c4eadf091eb8f07f9a6cc423.jpg', 'https://phimimg.com/upload/vod/20241218-1/9a4140f9f2fda630e0633803e01fb649.jpg', '<p>Một bác sĩ nghi ngờ rằng cái chết kỳ lạ của cô con gái vừa được cấy ghép tim là do buổi trừ tà quái dị gây ra, những âm thanh rên rỉ bên tai khiến người đàn ông tin rằng con gái của mình chưa hề chết. Sau 3 ngày khâm liệm, vị bác sĩ cùng cha xứ quyết tâm tìm ra uẩn khúc về con quỷ ẩn mình trong cơ thể cô bé và đưa cô trở về từ cõi chết.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 1, '[{"name":"Park Shin-yang","avatar":""},{"name":"Lee Min-ki","avatar":""},{"name":"Lee Re","avatar":""},{"name":"Tae In-ho","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["Three Days","شیاطین می مانند","El Huésped del Diablo","La última posesión","Le Séjour du diable","사흘"]', 1784690324181);
