INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tri-lieu-su-bi-duoi-khoi-to-doi-lai-la-nguoi-manh-nhat', 'Trị Liệu Sư Bị Đuổi Khỏi Tổ Đội Lại Là Người Mạnh Nhất', 'The Healer Who Was Banished From His Party, Is, In Fact, The Strongest', 'https://phimimg.com/upload/vod/20250310-1/4c472937323db1bae5be8d9a75ec7535.jpg', 'https://phimimg.com/upload/vod/20250310-1/6be5ed2793972facc83b3b78e8c58564.jpg', '<p>&quot;Anh trai, lập đội với em nhé?&quot;

Laust, một Trị Liệu Sư bị gán mác &quot;vô năng&quot; vừa bị nhóm của mình ruồng bỏ, bất ngờ nhận được lời mời hợp tác từ Narsena, một Nữ Quyền Đấu Sĩ tràn đầy năng lượng. Cuộc gặp gỡ định mệnh này hóa ra lại là một cuộc tái ngộ.

Từ đây, hành trình phiêu lưu của hai người chính thức bắt đầu. Liệu bí mật về sức mạnh thực sự của Laust sẽ được hé lộ?</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Kaori Maeda","avatar":""},{"name":"Kensho Ono","avatar":""},{"name":"Hina Tachibana","avatar":""},{"name":"Ayaka Asai","avatar":""},{"name":"Yuuichirou Umehara","avatar":""},{"name":"Shunichi Toki","avatar":""},{"name":"Marie Hashimoto","avatar":""},{"name":"Rie Hikisaka","avatar":""},{"name":"Yukari Tamura","avatar":""},{"name":"Shin-ichiro Miki","avatar":""},{"name":"Toshiya Miyata","avatar":""},{"name":"Hiroshi Iwasaki","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["El curandero que fue desterrado de su grupo es, de hecho, el más fuerte","被队伍驱逐的治愈师其实是最强的","Party kara Tsuihō Sareta Sono Chiyushi, Jitsu wa Saikyō ni Tsuki","Party kara Tsuihou sareta Sono Chiyushi, Jitsu wa Saikyou ni Tsuki","파티에서 추방당한 그 치유사, 실은 최강인 것에 대해","The Healer Who Was Banished From His Party, Is, in Fact, the Strongest","被逐出隊伍的治癒師，其實是最強的","被隊伍驅逐的治癒師，其實是最強的","パーティーから追放されたその治癒師、実は最強につき"]', 1784690324181);
