INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('tri-lieu-su-bi-duoi-khoi-to-doi-lai-la-nguoi-manh-nhat', 'Trị Liệu Sư Bị Đuổi Khỏi Tổ Đội Lại Là Người Mạnh Nhất', 'The Healer Who Was Banished From His Party, Is, In Fact, The Strongest', 'trị liệu sư bị đuổi khỏi tổ đội lại là người mạnh nhất the healer who was banished from his party, is, in fact, the strongest kaori maeda kensho ono hina tachibana ayaka asai yuuichirou umehara shunichi toki marie hashimoto rie hikisaka yukari tamura shin-ichiro miki toshiya miyata hiroshi iwasaki el curandero que fue desterrado de su grupo es, de hecho, el más fuerte 被队伍驱逐的治愈师其实是最强的 party kara tsuihō sareta sono chiyushi, jitsu wa saikyō ni tsuki party kara tsuihou sareta sono chiyushi, jitsu wa saikyou ni tsuki 파티에서 추방당한 그 치유사, 실은 최강인 것에 대해 the healer who was banished from his party, is, in fact, the strongest 被逐出隊伍的治癒師，其實是最強的 被隊伍驅逐的治癒師，其實是最強的 パーティーから追放されたその治癒師、実は最強につき', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('em-la-nang-hau-gai', 'Em Là Nàng Hầu Gái', 'You Are Ms. Servant', 'https://phimimg.com/upload/vod/20250310-1/d5eb2fc927478063b9508f0b13963761.jpg', 'https://phimimg.com/upload/vod/20250310-1/e6de7f579e31cd49a9f8ad36560bda34.jpg', '<p>Một ngày nọ, đột nhiên có một cô hầu gái đến gõ cửa nhà—.

Yokoya Hitoyoshi, một nam sinh trung học, bất ngờ nhận được một vị khách không mời. Đó là một cô hầu gái với mái tóc đen, tính cách nghiêm trang và lời nói lịch sự. Câu đầu tiên cô ấy nói là: “Xin hãy thuê tôi.”

Trước đây, cô ấy là một “sát thủ”, sở trường của cô là “ám sát”, và việc nhà thì lại rất vụng về. Cuộc sống chung dưới một mái nhà cùng cô hầu gái ấy bắt đầu từ cuộc gặp gỡ định mệnh này…!?

Dần dần, trái tim của cô gái không biết đến cảm xúc ấy bắt đầu dao động—.

Đây là câu chuyện về một cô hầu gái từng cô độc, nhưng rồi đã tìm thấy một “gia đình” cho mình.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Toshiki Kumagai","avatar":""},{"name":"Reina Ueda","avatar":""},{"name":"Eriko Matsui","avatar":""},{"name":"Hikaru Iida","avatar":""},{"name":"Lynn","avatar":""},{"name":"Konomi Inagaki","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["女仆冥土小姐","暗杀女仆冥土小姐","女仆冥土小姐。","暗杀女仆冥土酱","女仆冥土酱。","Kimi wa Meido-sama.","Kimi wa Maid-sama.","Kimi wa meido sama","女僕冥土小姐","君は冥土様。"]', 1784690324181);
