INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('layla', 'Layla', 'Layla', 'https://phimimg.com/upload/vod/20250309-1/507e0dd26f8a8bcb27e2d834eb4380f4.jpg', 'https://phimimg.com/upload/vod/20250309-1/e3564df679c51f552f49c429acbbe323.jpg', '<p>Bộ phim kể về Layla, một drag queen (nghệ sĩ biểu diễn cải trang) gốc Ả Rập đang gặp khó khăn trong cuộc sống. Layla lần đầu tiên trải qua cảm giác yêu, nhưng mối quan hệ này đưa họ vào một hành trình biến đổi đầy thử thách. Trong tình yêu, Layla vừa đánh mất chính mình vừa tìm lại bản thân, đối mặt với những câu hỏi sâu sắc về danh tính, văn hóa và con người thật của mình.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Bilal Hasna","avatar":""},{"name":"Louis Greatorex","avatar":""},{"name":"Safiyya Ingar","avatar":""},{"name":"Terique Jarrett","avatar":""},{"name":"Darkwah","avatar":""},{"name":"Sarah Agha","avatar":""},{"name":"Self Esteem","avatar":""},{"name":"Emma McDonald","avatar":""},{"name":"Ghazi Al Ruffai","avatar":""},{"name":"Baby","avatar":""},{"name":"Tim Bowie","avatar":""},{"name":"Freddie Thorp","avatar":""},{"name":"Adam Howden","avatar":""},{"name":"Ali Barouti","avatar":""},{"name":"Rania Kurdi","avatar":""},{"name":"Adnan Rashed","avatar":""},{"name":"Buket Komur","avatar":""},{"name":"Matthew Jacobs Morgan","avatar":""},{"name":"Huw Mo","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["Layla"]', 1784690324181);
