INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('truong-sinh-gioi', 'Trường Sinh Giới', 'World Of Immortals', 'https://phimimg.com/upload/vod/20241030-1/46a8329a740d54c1bfc72c949d4a8689.jpg', 'https://phimimg.com/upload/vod/20241030-1/9d015b9bdd7820c81e867ab252a72927.jpg', '<p>Trên đời này liệu có ai bất tử? Dù có tài hoa tuyệt đỉnh, nổi tiếng thiên hạ, cuối cùng cũng phải hóa thành đống xương khô; Dù có là con của trời, nắm trong tay vạn dặm giang sơn, cuối cùng cũng sẽ biến thành một nắm hoàng thổ. Câu chuyện kể về Tiêu Thần bị thiên nữ hoàng gia Triệu Lâm Nhi truy sát, vô tình lạc vào Đảo Rồng hoang dã ở Trường Sinh Giới. Đây là một con đường cụt không có lối về nhà, phải đối mặt với đầy rẫy quái thú và kẻ thù. Sự lưu luyến với người thân, bằng hữu và cố hương luôn là điểm tựa để Tiêu Thần đứng vững chiến đấu với quái thú và kẻ thù ở vùng đất kỳ lạ này. Trong cuộc chiến cuồng nhiệt, sự cám dỗ của cảm xúc và dục vọng, Tiêu Thần đi theo bước chân của những người trường sinh bất tử, từ từ vén lên bức màn bí ẩn về một thế giới thần thoại cổ xưa bị cát bụi phong ấn...</p>', 'Hoàn Tất (26/26)', 26, 'hoathinh', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["长生界 龙岛篇","Chang Sheng Jie","长生界动画","Changshengjie","Changsheng Jie","Cháng Shēng Jiè","The Eternal Realm","World of Immortals","Immortality World","Eternal Realm","长生界"]', 1784690324181);
