INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ngoi-nha-tram-ty', 'Ngôi Nhà Trăm Tỷ', 'The Hundred Billion House', 'https://phimimg.com/upload/vod/20250306-1/3aca028febf6dec496d15140ba40b008.jpg', 'https://phimimg.com/upload/vod/20250306-1/c7cef7b8437f70566e78ab7421fa888d.jpg', '<p>Bà Bông sống trong ngôi biệt thự rộng lớn cùng các con. Con trai lớn bị lừa, đuổi khỏi công ty. Con gái thứ 3 muốn bỏ chồng theo nhân tình nhưng sợ mất phần thừa kế. Cậu con trai út muốn kết hôn nhưng gia đình lại đang rối ren. Sau mọi chuyện vui buồn, các thành viên đều nhận ra: Nhà là nơi để về.</p>', 'Hoàn Tất (27/27)', 27, 'series', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Việt Nam', 0, '[{"name":"NSND Lan Hương","avatar":""},{"name":"Bảo Trung","avatar":""},{"name":"Lâm Mỹ Vân","avatar":""},{"name":"Quản Hân","avatar":""},{"name":"Phước Bùi","avatar":""},{"name":"Sỹ Hậu","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Huge Moves","神奇搬运家","Valtava muutto","Impossible Moves","Monster Moves"]', 1784690324181);
