INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-hac-yeu-su-luc-3d', 'Hổ Hạc Yêu Sư Lục 3D', 'Tiger Crane, Hu He Yao Shi Lu 3D', 'https://phimimg.com/upload/vod/20250308-1/0fa106591b42e2bf825e7bc43fdc7ae0.jpg', 'https://phimimg.com/upload/vod/20250308-1/905effcf881314e2c67eeb9539d409d7.jpg', '<p>Một thế giới nơi nhân và yêu cùng tồn tại và đấu đá lẫn nhau. Những người tu luyện thuật pháp để tiêu diệt yêu ma quỷ quái được gọi là các yêu sư. Kỳ Hiểu Hiên do một sự cố nên tình cờ kết giao với Hổ Tử, từ đó hai người đã đồng hành cùng nhau trên con đường diệt trừ yêu ma, bảo vệ chính đạo.</p>', 'Hoàn Tất (24/24)', 24, 'hoathinh', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Shen Dawei","avatar":""},{"name":"Shujun Lv","avatar":""},{"name":"Xiaozheng","avatar":""},{"name":"灯果","avatar":""},{"name":"Xia Lei","avatar":""},{"name":"Ou Yang","avatar":""},{"name":"Liu Yuxuan","avatar":""},{"name":"Zhu Jun","avatar":""},{"name":"Gao Qichang","avatar":""},{"name":"Wen Xiaoyi","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Hu x He Yao Shi Lu","虎x鹤妖师录","Hu He Yao Shi Lu","Tiger Crane Demon Master Record","虎鹤妖师录","Tiger x Crane","Tiger and Crane","Tiger x Crane Record of the Demon Master"]', 1784690324181);
