INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('11-phien-quan', '11 Phiến Quân', '11 Rebels', 'https://phimimg.com/upload/vod/20250307-1/acc358ff24bcbcee9f484c400b134082.jpg', 'https://phimimg.com/upload/vod/20250307-1/314ec39f4b4bacaf0814ebc9095b890c.jpg', '<p>Bộ phim chuyển thể từ bản thảo huyền thoại của Kasahara Kazuo – biên kịch đã đặt nền móng cho thời kỳ hoàng kim của Toei với các tác phẩm như <em>日本侠客伝</em> và <em>仁義なき戦い</em>. Sau 60 năm chờ đợi, câu chuyện được đưa lên màn ảnh với bối cảnh cuối thời Mạc phủ năm 1868, kể về trận chiến sinh tử và những xung đột nội tâm của những tội nhân bị ép buộc làm “đội quyết tử” để bảo vệ thành trì cho một phiên bang mà họ căm ghét.Ban đầu, Kasahara đã xây dựng câu chuyện để chất vấn quan niệm “nếu thắng là chính quân, nếu thua là tặc quân” – tức việc phân định thiện ác dựa trên kết quả chiến thắng. Ông muốn đặt ra câu hỏi: “Liệu chỉ chiến thắng mới là công lý thực sự?”. Phim có sự tham gia của các diễn viên nổi tiếng như Yamada Takayuki và Nakano Taiga.</p><p><br/></p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 1, '[{"name":"Takayuki Yamada","avatar":""},{"name":"Taiga Nakano","avatar":""},{"name":"Riho Sayashi","avatar":""},{"name":"Ukon Onoe","avatar":""},{"name":"Takara Sakumoto","avatar":""},{"name":"Amane Okayama","avatar":""},{"name":"Yuya Matsuura","avatar":""},{"name":"Shuhei Nomura","avatar":""},{"name":"Takuma Otoo","avatar":""},{"name":"Hiroshi Tamaki","avatar":""},{"name":"Sadawo Abe","avatar":""},{"name":"Seiji Chihara","avatar":""},{"name":"Hayate Ichinose","avatar":""},{"name":"Ryota Oyanagi","avatar":""},{"name":"Chikara Motoyama","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["11 no Zokugun","Juuichinin no Zokugun","Eleven Rebels","11-nin no Zokugun","十一人的贼军","十一人贼军","十一人の賊軍"]', 1784690324181);
