INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhung-cau-chuyen-ve-ninja-rua', 'Những Câu Chuyện Về Ninja Rùa', 'Tales Of The Teenage Mutant Ninja Turtles', 'https://phimimg.com/upload/vod/20250307-1/f305c0b1e51122b56deb588057c90de9.jpg', 'https://phimimg.com/upload/vod/20250307-1/6178ff4c1776e8b67dbd95067304eabe.jpg', '<p>Bộ tứ Ninja Rùa – Leo, Raph, Donnie và Mikey – lần đầu tiên phải bước đi trên con đường riêng của mình. Đối mặt với những mối đe dọa mới và sát cánh cùng những đồng minh cũ, họ sẽ phải tự tìm ra bản sắc thật sự của mình khi không còn anh em bên cạnh.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Micah Abbey","avatar":""},{"name":"Shamon Brown Jr.","avatar":""},{"name":"Nicolas Cantu","avatar":""},{"name":"Brady Noon","avatar":""},{"name":"Ayo Edebiri","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["忍者神龟","忍者神龟之都市传奇","Tales of the TMNT","TOTTMNT","Tales of the Teenage Mutant Ninja Turtles"]', 1784690324181);
