INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nam-2073', 'Năm 2073', '2073', 'https://phimimg.com/upload/vod/20250306-1/ffec3df188cac0487ebdff4999bd554f.jpg', 'https://phimimg.com/upload/vod/20250306-1/927794093266f62d8bce444196a98a93.jpg', '<p>Trong bối cảnh năm 2073, Trái Đất bị tàn phá, các lực lượng cảnh sát quân sự tuần tra trên đường phố, và máy bay không người lái giám sát tràn ngập bầu trời. Những người sống sót ẩn náu dưới lòng đất, cố gắng nhớ lại một thời kỳ tự do và hy vọng. Bộ phim kết hợp giữa viễn tưởng và tài liệu, liên kết các mối đe dọa toàn cầu hiện nay như chủ nghĩa độc tài, công nghệ lớn và sự sụp đổ khí hậu, nhằm đưa ra lời cảnh báo khẩn cấp về việc bảo vệ nhân loại và tự do của chúng ta.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Samantha Morton","avatar":""},{"name":"Naomi Ackie","avatar":""},{"name":"Hector Hewer","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Tài Liệu","slug":"tai-lieu","id":"1645fa23fa33651cef84428b0dcc2130"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["2073"]', 1784690324181);
