INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trai-cam-am-hon-tap-the', 'Trại Cấm: Ám Hồn Tập Thể', 'Kemah Terlarang: Kesurupan Massal', 'https://phimimg.com/upload/vod/20250305-1/2f8e61aa243f391aae9d8ef3bf446876.jpg', 'https://phimimg.com/upload/vod/20250305-1/f413ffad6d12c730c5fbecd0091016f7.jpg', '<p>Rini, học sinh trung học Pandega, tham gia vào vở kịch và thủ vai nhân vật Roro Putri – người đã mất cách đây hàng trăm năm – bất ngờ bị ám ảnh bởi linh hồn của Roro Putri và từ đó kích hoạt cơn ám tập thể lan rộng khắp các thành viên tham gia. Nhiều nạn nhân bị thương, thậm chí có người bị đe dọa tính mạng. Liệu ban tổ chức/dewan ambalan có thể đưa tất cả các thành viên về nhà an toàn không?</p>', 'Full', 1, 'single', 'completed', 15, 2024, 'Vietsub', 'FHD', 'Indonesia', 0, '[{"name":"Callista Arum","avatar":""},{"name":"Nayla D. Purnama","avatar":""},{"name":"Fatih Unru","avatar":""},{"name":"Derby Romero","avatar":""},{"name":"Zenia Zein","avatar":""},{"name":"Azela Putri","avatar":""},{"name":"Callista Mercy","avatar":""},{"name":"Moh Iqbal Sulaiman","avatar":""},{"name":"Landung Simatupang","avatar":""},{"name":"Nihna Fitria","avatar":""},{"name":"Dimas Juju","avatar":""},{"name":"Ibnu Widodo","avatar":""},{"name":"Banyu Bening","avatar":""},{"name":"Dimas Herjuna Tuwek","avatar":""},{"name":"Axcel Bensza Amartya","avatar":""},{"name":"Veri Sulistyo","avatar":""},{"name":"Satr","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["ជំរុំហាមឃាត់ - ព្រៃខ្មោចសណ្ឋិត","猛鬼夏令营","Kemah Terlarang: Kesurupan Massal"]', 1784690324181);
