INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nghi-le-truc-quy', 'Nghi Lễ Trục Quỷ', 'Dominion Of Darkness', 'https://phimimg.com/upload/vod/20250304-1/8cd2ef504f9a8edfd77c9b7f41279cf6.jpg', 'https://phimimg.com/upload/vod/20250304-1/d4607d35cb05a88bd2b5e6088bc7e5de.jpg', '<p>Câu chuyện tiết lộ hành trình tâm linh sâu sắc của một linh mục trẻ tên là Thomas, người đã mất niềm tin sau một tai nạn gia đình đau thương. Khi được Rendra, một linh mục trừ tà kỳ cựu, mời trở thành học trò của mình, Thomas miễn cưỡng đồng ý. Tuy nhiên, niềm tin của anh được thắp lại khi họ đối mặt với một vụ ám quỷ liên quan đến một cô gái tên Kayla. Sự suy sụp của Kayla sau khi thực hiện một nghi lễ, cô bị biến đổi đến mức không thể nhận ra, những vết thương tự xuất hiện trên cơ thể cô, hay ánh mắt ma quái đầy đe dọa khi bị thế lực quỷ dữ thao túng. Quyết tâm cứu Kayla bằng mọi giá, Thomas đã phải trải qua một hành trình hết sức khó khăn để chống lại các thế lực đen tối.</p>', 'Full', 1, 'single', 'completed', 14, 2024, 'Vietsub', 'FHD', 'Indonesia', 1, '[{"name":"Jerome Kurnia","avatar":""},{"name":"Lukman Sardi","avatar":""},{"name":"Astrid Tiar","avatar":""},{"name":"Lea Ciarachel","avatar":""},{"name":"Freya Jayawardana","avatar":""},{"name":"Joshua Pandelaki","avatar":""},{"name":"Erdin Werdrayana","avatar":""},{"name":"Delia Husein","avatar":""},{"name":"Viki Maintrova","avatar":""},{"name":"Eistevanya Alexandra","avatar":""},{"name":"Wina Marino","avatar":""},{"name":"Saleh Ceper","avatar":""},{"name":"Kameo Lova","avatar":""},{"name":"Jordan Omar","avatar":""},{"name":"Yovella Ardystia","avatar":""},{"name":"Martha Ludiya","avatar":""},{"name":"Runny R","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["กัวซาผีสาปนรกส่ง","ខ្មោចកាន់","Nghi Lễ Trục Quỷ","El Poder del Exorcista","Kuasa Gelap"]', 1784690324181);
