INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anora-lo-lem-thoi-hien-dai', 'Anora: Lọ Lem Thời Hiện Đại', 'Anora', 'https://phimimg.com/upload/vod/20241219-1/6106962489b853883f360d0ff9387728.jpg', 'https://phimimg.com/upload/vod/20241219-1/2dbac350e2cf09750048d44efccb8ec6.jpg', '<p>Bộ phim kể về Anora, một cô gái trẻ làm vũ công thoát y kiêm gái mại dâm ở Brooklyn. Cuộc sống của cô hoàn toàn thay đổi khi cô gặp và nhanh chóng kết hôn với con trai của một gia đình giàu có người Nga. Tuy nhiên, gia đình chồng cô không chấp nhận cuộc hôn nhân này và bay từ Nga đến New York để tìm cách hủy bỏ kết hôn.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Mikey Madison","avatar":""},{"name":"Mark Eydelshteyn","avatar":""},{"name":"Yura Borisov","avatar":""},{"name":"Karren Karagulian","avatar":""},{"name":"Vache Tovmasyan","avatar":""},{"name":"Luna Sofía Miranda","avatar":""},{"name":"Lindsey Normington","avatar":""},{"name":"Darya Ekamasova","avatar":""},{"name":"Aleksey Serebryakov","avatar":""},{"name":"Anton Bitter","avatar":""},{"name":"Ivy Wolk","avatar":""},{"name":"Vlad Mamai","avatar":""},{"name":"Maria Tichinskaya","avatar":""},{"name":"Paul Weissman","avatar":""},{"name":"Emily Weider","avatar":""},{"name":"Vincent Ra","avatar":""}]', '[{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["آنورا","อโนรา","阿諾拉","Անորա","Anora","Анора"]', 1784690324181);
