INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bac-si-quai-di-ban-dien-anh', 'Bác Sĩ Quái Dị (Bản Điện Ảnh)', 'Black Jack', 'https://phimimg.com/upload/vod/20250303-1/625635b94a2b6938598a71af7d8f876c.jpg', 'https://phimimg.com/upload/vod/20250303-1/e760674e25c432ae1190448648d50e96.jpg', '<p>Là “kim tự tháp của manga y tế” không bao giờ phai mờ và luôn được đông đảo người hâm mộ yêu mến, tác phẩm này đã kỷ niệm 50 năm ra mắt tuần tự vào năm 2023. Bác sĩ phẫu thuật thiên tài không có giấy phép – Black Jack, người có thể đảm bảo thành công cho bất kỳ ca phẫu thuật nào với mức phí điều trị khổng lồ, đã được hồi sinh một cách gây sốc trong thời đại Reiwa, khi sau đại dịch, cách thức tồn tại của ngành y tế lại bị đặt ra câu hỏi.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Issey Takahashi","avatar":""},{"name":"Yuno Nagao","avatar":""},{"name":"Shizuka Ishibashi","avatar":""},{"name":"Marika Matsumoto","avatar":""},{"name":"Pistol Takehara","avatar":""},{"name":"Ryosuke Mikata","avatar":""},{"name":"Takaya Yamauchi","avatar":""},{"name":"Chiba Tetsuya","avatar":""},{"name":"Takamasa Tamaki","avatar":""},{"name":"Eiji Okuda","avatar":""},{"name":"Kai Inowaki","avatar":""},{"name":"Taichi Saotome","avatar":""},{"name":"Shohei Uno","avatar":""},{"name":"Takashi Yamanaka","avatar":""},{"name":"Isao Hashizume","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["怪醫秦博士 (真人版)","ブラック・ジャック"]', 1784690324181);
