INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-du-ca-vo-dinh', 'Kẻ Du Ca Vô Định', 'A Complete Unknown', 'https://phimimg.com/upload/vod/20250303-1/229694f79c239cbe9940da72f2cd91c3.jpg', 'https://phimimg.com/upload/vod/20250303-1/802a76a30b7507caafb951abe30be17e.jpg', '<p>New York 1961. Trong bối cảnh của âm nhạc sôi động và sự biến động văn hóa dữ dội, một chàng trai 19 tuổi bí ẩn đến từ Minnesota với cây đàn guitar và tài năng cách mạng của mình, được định sẵn để thay đổi nền âm nhạc Mỹ. Anh ấy xây dựng mối quan hệ thân mật với các biểu tượng âm nhạc của Greenwich Village trong sự thăng tiến nhanh chóng của mình, lên đến đỉnh điểm trong một màn trình diễn mang tính đột phá và gây tranh cãi vang dội trên toàn thế giới. &nbsp;Timothée Chalamet đóng vai chính và hát với tư cách là Bob Dylan trong bộ phim được đề cử Oscar 2025 nặng ký của đạo diễn James Mangold, câu chuyện có thật đầy tính điện ảnh của một trong những ca sĩ kiêm nhạc sĩ biểu tượng nhất trong lịch sử.</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Timothée Chalamet","avatar":""},{"name":"Edward Norton","avatar":""},{"name":"Elle Fanning","avatar":""},{"name":"Monica Barbaro","avatar":""},{"name":"Scoot McNairy","avatar":""},{"name":"Dan Fogler","avatar":""},{"name":"Boyd Holbrook","avatar":""},{"name":"Will Harrison","avatar":""},{"name":"Joe Tippett","avatar":""},{"name":"Eriko Hatsune","avatar":""},{"name":"Peter Gray Lewis","avatar":""},{"name":"Peter Gerety","avatar":""},{"name":"Lenny Grossman","avatar":""},{"name":"David Wenzel","avatar":""},{"name":"Riley Hashimoto","avatar":""},{"name":"Eloise Peyrot","avatar":""},{"name":"Maya Feldman","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '["Going Electric","Potpuni neznanac","巴布狄倫：搖滾詩人","无名小辈","Un Completo Desconocido","O necunoscută completă","Tamamiylə Bilinməyən","Un Parfait Inconnu","Like A Complete Unknown","名もなき者／A COMPLETE UNKNOWN","Um Completo Desconhecido","A Complete Unknown","Bob Dylan: Úplně neznámý","Bob Dylan: Tam Bir Bilinmez"]', 1784690324181);
