INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('ke-du-ca-vo-dinh', 'Kẻ Du Ca Vô Định', 'A Complete Unknown', 'kẻ du ca vô định a complete unknown timothée chalamet edward norton elle fanning monica barbaro scoot mcnairy dan fogler boyd holbrook will harrison joe tippett eriko hatsune peter gray lewis peter gerety lenny grossman david wenzel riley hashimoto eloise peyrot maya feldman going electric potpuni neznanac 巴布狄倫：搖滾詩人 无名小辈 un completo desconocido o necunoscută completă tamamiylə bilinməyən un parfait inconnu like a complete unknown 名もなき者／a complete unknown um completo desconhecido a complete unknown bob dylan: úplně neznámý bob dylan: tam bir bilinmez', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tan-tu-chi-vuong', 'Tán Tu Chi Vương', 'The King of Wandering Cultivators, San Xiu Zhi Wang', 'https://phimimg.com/upload/vod/20250219-1/ec85709f657d190c264be536ebde4f09.jpg', 'https://phimimg.com/upload/vod/20250219-1/0294b1b7c2f4ba87f16975e14030c29f.jpg', '<p>Nhờ vào việc tình cờ phát hiện ra và quen biết với khí linh thượng cổ, một ông già nhỏ bé nhưng ẩn chưa đầy năng lực siêu phàm đã giúp sức cho một thanh niên phế vật trở thành một siêu cao thủ đầu mưng mủ. Từ đó mà thanh niên đó dốc hết sức tu luyện, kết giao với đủ mọi thể loại người từ các danh sĩ cho đến các cao thủ võ thuật, để có thể tiếp tục học hỏi và nâng cao sức mạnh, bảo vệ đại lục đấu khí khỏi những dòm ngó từ bên ngoài và có được những chân dài vô cùng quyến rũ.</p>', 'Hoàn Tất (52/52)', 52, 'hoathinh', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["The King of Wandering Cultivators","San Xiu Zhi Wang","San Xiuzhi Wang","King of Loose Cultivators","The King of Casual Cultivators","King of Casual Cultivators","散修之王"]', 1784690324181);
