INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dong-chi', 'Đông Chí', 'Love Song In Winter', 'https://phimimg.com/upload/vod/20241220-1/2c45846333ed2f9055a71036beb47938.jpg', 'https://phimimg.com/upload/vod/20241220-1/2e20467da2cd5927695d5011ead6562a.jpg', '<p>&quot;Đông Chí&quot; là một bộ phim đô thị kinh dị tình cảm lãng mạn do Trung Trung (&quot;Nửa Là Đường Mật, Nửa Là Đau Thương&quot;) và Dị Dũng (&quot;Anh Ấy Bước Ra Từ Ánh Lửa&quot;) đồng đạo diễn, với sự tham gia của Hoàng Cảnh Du (&quot;Hành Động Phá Băng&quot;) và Tôn Thiên (&quot;Gió Thổi Bán Hạ&quot;) làm vai chính. Bộ phim được chuyển thể từ tiểu thuyết cùng tên của Ngưng Lũng, kể về câu chuyện tình lãng mạn giữa cảnh sát Giang Thành Ngật và bác sĩ gây mê Lục Yên, sau tám năm xa cách, họ ngẫu nhiên gặp lại nhau trong quá trình giải quyết một vụ án giết người hàng loạt và làm sáng tỏ những hiểu lầm từ quá khứ. Lục Yên (do Tôn Thiên thủ vai), một bác sĩ gây mê, sau nhiều sự kiện kỳ quái, “tình cờ” gặp lại người bạn thân đã qua đời khi làm ca đêm nhiều năm trước Đặng Man (do Hà Hoằng San thủ vai). Trong quá trình tìm hiểu sự thật, cựu bạn trai của Lục Yên, cảnh sát Giang Thành Ngật (do Hoàng Cảnh Du thủ vai), cũng bị cuốn vào vụ án. Sự thật được giữ kín tám năm, từng bước sẽ được mở ra.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 6, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hoàng Cảnh Du","avatar":""},{"name":"Tôn Thiên","avatar":""},{"name":"Tiêu Khải Trung","avatar":""},{"name":"Quản Tử Tịnh","avatar":""},{"name":"Thi Thi","avatar":""},{"name":"Hà Hoằng San","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["love song in winter","冬至"]', 1784690324181);
