INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('dong-chi', 'Đông Chí', 'Love Song In Winter', 'đông chí love song in winter hoàng cảnh du tôn thiên tiêu khải trung quản tử tịnh thi thi hà hoằng san love song in winter 冬至', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bocchi-the-rock-recap-part-2', 'Bocchi The Rock! Recap Part 2', 'Bocchi The Rock! Recap Part 2', 'https://phimimg.com/upload/vod/20250303-1/622e9ee1075147e19327d5620406b479.jpg', 'https://phimimg.com/upload/vod/20250303-1/631a59d64bae1b09520afd512f275b69.jpg', '<p>Manga 4 khung tranh nổi tiếng của Aki Hamazi, Bocchi the Rock!, lần đầu được đăng trên tạp chí Manga Time Kirara Max của Houbunsha. Câu chuyện xoay quanh Hitori Gotoh, một cô gái cực kỳ nhút nhát và lo lắng khi giao tiếp xã hội, đã tham gia vào ban nhạc tên là Kessoku Band và dần trưởng thành bên cạnh ba người bạn cùng ban nhạc lập dị của mình: Nijika Ijichi, Ryo Yamada và Ikuyo Kita. Câu chuyện này đã chạm đến trái tim của rất nhiều người. Khi anime bắt đầu phát sóng vào mùa thu năm 2022, nó nhanh chóng trở nên cực kỳ nổi tiếng, đặc biệt là trong giới trẻ. Bộ phim đã giành được nhiều giải thưởng và nhận được sự ủng hộ nồng nhiệt từ người hâm mộ trong nước và quốc tế. Âm nhạc của phim cũng gây tiếng vang lớn, với album &quot;Kessoku Band&quot; của ban nhạc xếp hạng số 1 trên bảng xếp hạng album kỹ thuật số của Oricon năm 2023 và đứng đầu bảng xếp hạng album tải về của Billboard Nhật Bản. Câu chuyện về Kessoku Band, với sự thành công vang dội cả về anime lẫn âm nhạc, sẽ ra rạp vào năm 2024 dưới dạng một bộ phim tổng hợp từ loạt phim TV, với hiệu ứng hình ảnh và âm thanh mạnh mẽ trên màn ảnh lớn! Nếu bạn là người hướng nội, hãy thử sức với rock!</p>', 'Full', 1, 'hoathinh', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yoshino Aoyama","avatar":""},{"name":"Sayumi Suzushiro","avatar":""},{"name":"Saku Mizuno","avatar":""},{"name":"Ikumi Hasegawa","avatar":""},{"name":"Maaya Uchida","avatar":""},{"name":"Sayaka Senbongi","avatar":""},{"name":"Kotori Koiwai","avatar":""},{"name":"Misaki Watada","avatar":""},{"name":"Junji Majima","avatar":""},{"name":"Rie Suegara","avatar":""},{"name":"Kana Ichinose","avatar":""},{"name":"Miyuri Shimabukuro","avatar":""},{"name":"Katsuyuki Miura","avatar":""},{"name":"Sally Amaki","avatar":""},{"name":"Maki Kawase","avatar":""},{"name":"Atsushi Kosaka","avatar":""},{"name":"Shigeru Ch","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '["Gekijou Soushuuhen BOCCHI THE ROCK! Re:Re:","Gekijō Sōshūhen BOCCHI THE ROCK! Re:Re:","BOCCHI THE ROCK! Recap Part 1 & 2","Bocchi the Rock! Re:Re:","Theater Compilation Bocchi the Rock! Re:Re:","孤独摇滚（下）","剧场总集篇 孤独摇滚！ Re:Re:","剧场总集篇 孤独摇滚！：后半部分","孤独摇滚 后篇","劇場総集編ぼっち・ざ・ろっく！Re:Re:"]', 1784690324181);
