INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bocchi-the-rock-recap-part-2', 'Bocchi The Rock! Recap Part 2', 'Bocchi The Rock! Recap Part 2', 'bocchi the rock! recap part 2 bocchi the rock! recap part 2 yoshino aoyama sayumi suzushiro saku mizuno ikumi hasegawa maaya uchida sayaka senbongi kotori koiwai misaki watada junji majima rie suegara kana ichinose miyuri shimabukuro katsuyuki miura sally amaki maki kawase atsushi kosaka shigeru ch gekijou soushuuhen bocchi the rock! re:re: gekijō sōshūhen bocchi the rock! re:re: bocchi the rock! recap part 1 & 2 bocchi the rock! re:re: theater compilation bocchi the rock! re:re: 孤独摇滚（下） 剧场总集篇 孤独摇滚！ re:re: 剧场总集篇 孤独摇滚！：后半部分 孤独摇滚 后篇 劇場総集編ぼっち・ざ・ろっく！re:re:', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bocchi-the-rock-recap-part-1', 'Bocchi The Rock! Recap Part 1', 'Bocchi The Rock! Recap Part 1', 'https://phimimg.com/upload/vod/20250303-1/d9e3ffcd9c11a29da216faa1d0502a5a.jpg', 'https://phimimg.com/upload/vod/20250303-1/c0afab20d55f98593ae07cfe4ec10c15.jpg', '<p>Hitori Gotoh, hay còn gọi là &quot;Bocchi-chan&quot;, là một cô gái cực kỳ nhút nhát và luôn e ngại khi tiếp xúc với người khác. Mỗi khi nói chuyện, cô thường bắt đầu với câu “À...”. Khi còn học cấp hai, cô bắt đầu học guitar vì mong muốn tham gia một ban nhạc. Cô nghĩ rằng, nhờ chơi nhạc, ngay cả một người nhút nhát như mình cũng có thể tỏa sáng. Nhưng vì không có bạn, cô chỉ có thể tập đàn một mình mỗi ngày suốt 6 tiếng. Sau khi trở thành một tay guitar giỏi, cô đăng các video chơi đàn lên mạng dưới tên “Guitar Hero” và luôn mơ mộng về việc biểu diễn tại lễ hội trường. Tuy nhiên, cô không tìm được ai để cùng lập ban nhạc, và rồi cô nhận ra mình đã lên cấp ba mà vẫn chưa kết bạn được với ai! Cô gần như trở thành một người sống thu mình, nhưng một ngày nọ, Nijika Ijichi, tay trống của ban nhạc Kessoku, đã tìm đến cô. Từ đó, cuộc sống hàng ngày của cô bắt đầu thay đổi từng chút một...</p>', 'Full', 1, 'hoathinh', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yoshino Aoyama","avatar":""},{"name":"Sayumi Suzushiro","avatar":""},{"name":"Saku Mizuno","avatar":""},{"name":"Ikumi Hasegawa","avatar":""},{"name":"Maaya Uchida","avatar":""},{"name":"Sayaka Senbongi","avatar":""},{"name":"Kotori Koiwai","avatar":""},{"name":"Misaki Watada","avatar":""},{"name":"Junji Majima","avatar":""},{"name":"Rie Suegara","avatar":""},{"name":"Kana Ichinose","avatar":""},{"name":"Miyuri Shimabukuro","avatar":""},{"name":"Yume Miyamoto","avatar":""},{"name":"Hinaki Yano","avatar":""},{"name":"Rina Endou","avatar":""},{"name":"Coco Hayashi","avatar":""},{"name":"Hayato Komiya","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"}]', '["Gekijou Soushuuhen BOCCHI THE ROCK! Re:","Gekijō Sōshūhen BOCCHI THE ROCK! Re:","Theater Compilation Bocchi the Rock! Re:","Bocchi the Rock! Re:","BOCCHI THE ROCK Recap Part 1","BOCCHI THE ROCK! Recap Part 1 & 2","孤独摇滚（上）","剧场总集篇 孤独摇滚！ Re:","剧场总集篇 孤独摇滚！：前半部分","孤独摇滚 后篇","劇場総集編ぼっち・ざ・ろっく！Re:"]', 1784690324181);
