INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('bocchi-the-rock-recap-part-1', 'Bocchi The Rock! Recap Part 1', 'Bocchi The Rock! Recap Part 1', 'bocchi the rock! recap part 1 bocchi the rock! recap part 1 yoshino aoyama sayumi suzushiro saku mizuno ikumi hasegawa maaya uchida sayaka senbongi kotori koiwai misaki watada junji majima rie suegara kana ichinose miyuri shimabukuro yume miyamoto hinaki yano rina endou coco hayashi hayato komiya gekijou soushuuhen bocchi the rock! re: gekijō sōshūhen bocchi the rock! re: theater compilation bocchi the rock! re: bocchi the rock! re: bocchi the rock recap part 1 bocchi the rock! recap part 1 & 2 孤独摇滚（上） 剧场总集篇 孤独摇滚！ re: 剧场总集篇 孤独摇滚！：前半部分 孤独摇滚 后篇 劇場総集編ぼっち・ざ・ろっく！re:', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nhiem-vu-ngoai-ke-hoach', 'Nhiệm Vụ Ngoài Kế Hoạch', 'Bonus Trip', 'https://phimimg.com/upload/vod/20250303-1/910e1fb55160fa2de1dcafd72fcfd1be.jpg', 'https://phimimg.com/upload/vod/20250303-1/f9524dec44e2a6d7b396726639b6e805.jpg', '<p>Phim kể về hai đặc vụ FBI, Marshall và Demetrius, được giao nhiệm vụ điều tra một vụ vi phạm bản quyền tại châu Âu. Trong quá trình điều tra, họ phát hiện ra một âm mưu toàn cầu liên quan đến việc sử dụng người vô gia cư làm sát thủ. Cùng với Maya, một phiên dịch viên, họ quyết định bất chấp mệnh lệnh để giải cứu cha của Maya và vạch trần âm mưu này. Hành trình của họ đầy ắp những tình huống hài hước, bất ngờ và nguy hiểm đến tính mạng.</p>', 'Full', 1, 'single', 'completed', 14, 2024, 'Vietsub', 'FHD', 'Quốc Gia Khác', 0, '[{"name":"Spencer Vaughn Kelly","avatar":""},{"name":"Camryn Jackson","avatar":""},{"name":"Vanessa Aleksander","avatar":""},{"name":"Matthew Simpson","avatar":""},{"name":"Bruce Lester-Johnson","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Bonus Trip"]', 1784690324181);
