INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tham-tiem-giau-kin', 'Thâm Tiềm Giấu Kín', 'Deep Lurk', 'https://phimimg.com/upload/vod/20241113-1/157a1470a1b30f546e190c948737cdb4.jpg', 'https://phimimg.com/upload/vod/20241113-1/e29dc182e447b2a9bca452970e92bd8b.jpg', '<p>Trong thời kỳ Chiến tranh chống Nhật, để thuận lợi chiếm đóng Trường Sa, quân Nhật sử dụng chiến lược đặc công “Hắc Chấp Sự” đã ẩn náu tại Trung Quốc 15 năm, thực hiện kế hoạch lừa dối chiến lược đã được lên kế hoạch từ lâu. Thành viên của Đảng Cộng sản Trung Quốc dưới lòng đất Vân Mộ Chi đã bị giết trong quá trình điều tra “Hắc Chấp Sự”. Con trai ông Vân Hoằng Thâm không biết thân phận thực sự của cha mình khi điều tra kẻ giết người, đã bị cuốn vào bẫy mà “Hắc Chấp Sự” đã sắp xếp từ trước. Trong lúc Vân Hoằng Thâm cảm thấy mê man và bất lực, bạn thân của cha anh khi còn sống đã đem đến cho anh sự giúp đỡ và bảo vệ lớn lao, cuối cùng anh đã nhận ra trò lừa của đối phương. Dưới sự lãnh đạo của Đảng Cộng sản, Vân Hoằng Thâm cùng với người trẻ yêu nước Văn Dạ Minh hợp sức lập kế trong kế, tiến từng bước một, bỏ qua thù nhà trước nỗi hận quốc gia, tự đem mình làm quân cờ tử, khai quật đặc vụ chiến lược Nhật Bản ẩn náu bên trong quân đội Quốc gia, làm thay đổi cục diện chiến tranh, đóng góp lớn vào chiến thắng Trường Sa lần thứ nhất.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Thành Nghị","avatar":""},{"name":"Vương Kính Tùng","avatar":""},{"name":"Đình Nhi","avatar":""},{"name":"Hầu Mộng Diệu","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["迷局破之深潜","深潜"]', 1784690324181);
