INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('lan-thu-hai-gap-go', 'Lần Thứ Hai Gặp Gỡ', 'Her Fantastic Adventures', 'https://phimimg.com/upload/vod/20240713-1/7ef762d23bd0a1da18e1d52c92b6a9e8.jpg', 'https://phimimg.com/upload/vod/20240713-1/27db21e868187aa00ed64117ea3314a5.jpg', '<p>Bộ phim này được chuyển thể từ tiểu thuyết &quot;Chuyện ngại ngùng gây cười ở Ngọ Môn&quot; của Ảnh Chiếu, kể về cô gái vận động viên Tề Xuân Kiều bất ngờ hóa thân thành Cố Thanh Kiều, một cô gái ở quán rượu thời xưa. Cô cùng với Đoàn Ngọc, Lục Tử Tranh, Nguyễn Tự Khung và những người khác bắt đầu một hành trình khám phá và tìm báu vật xuyên thời không. Cuối cùng, họ thu hoạch được tình thân, tình yêu, tình bạn, và hòa giải với sự không hoàn hảo của bản thân, tìm thấy hướng đi của cuộc đời trong một câu chuyện lãng mạn, hài hước và đầy cảm hứng.</p>', 'Hoàn Tất (36/36)', 36, 'series', 'completed', 7, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Lý Cửu Lâm","avatar":""},{"name":"Khương Tử Tân","avatar":""},{"name":"Tống Y Nhân","avatar":""},{"name":"Quách Tuấn Trần","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '[]', 1784690324181);
