INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('huyen-nhac-sam-lam', 'Huyễn Nhạc Sâm Lâm', 'Echo Of Her Voice', 'https://phimimg.com/upload/vod/20240922-1/711d06f2fc43a49c195faccb7b79245b.jpg', 'https://phimimg.com/upload/vod/20240922-1/cc743c9408eb98a6b275208dbf3e96e2.jpg', '<p>&quot;Huyễn Nhạc Sâm Lâm&quot; là bộ phim cổ trang do Hà Hoằng Huân và Lương Văn Dực chỉ đạo, với sự tham gia của các diễn viên Hứa Giai Kỳ, Ngụy Triết Minh, Ngô Hi Trạch, Trương Nguyệt, Hoàng Hựu Minh,.. Bộ phim kể về câu chuyện xảy ra tại Đông Thịnh đại lục, nơi mà ai ai cũng am hiểu về âm nhạc. Nhân vật chính là Vân Mộc Thiếu Quân chàng công tử được người người biết đến là một kẻ say mê âm nhạc, nhưng ẩn sâu bên trong con người nho nhã đó lại ẩn chứa một bí mật động trời mà không phải ai cũng biết. Vì muốn tuyển người dạy nhạc cho mình hắn đã đến vùng đất Vân Diêu, tại đây Vân Mộc đã phải lòng với khúc trống Hạt của Tô Nhược Phi - bà chủ nhạc phường mà dốc lòng lên kế hoạch lôi kéo nàng làm thầy dạy nhạc cho mình, nhưng hắn không biết rằng vận mệnh của hai người họ đã sớm nối chặt với nhau bởi một thứ phép thuật kì lạ. Bộ phim sẽ được phát sóng trực tuyến trên iQiyi Quốc tế (iq.com).</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 7, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Hứa Giai Kỳ","avatar":""},{"name":"Ngụy Triết Minh","avatar":""},{"name":"Ngô Hi Trạch","avatar":""},{"name":"Trương Nguyệt","avatar":""},{"name":"Hoàng Hựu Minh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["幻樂森林","Meet Me in Your Sound","Echo of Her Voice","幻乐森林"]', 1784690324181);
