INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dem-toi-va-binh-minh', 'Đêm Tối Và Bình Minh', 'Dark Night And Dawn', 'https://phimimg.com/upload/vod/20240919-1/db2abadd4b8c5643d9515d2607b7b0f5.jpg', 'https://phimimg.com/upload/vod/20240919-1/94accebfa2fce43cd6f14f123212c4c7.jpg', '<p>Câu chuyện kể về thế hệ các chiến sĩ công an Trung Quốc mới đầu tiên tại Thượng Hải giai đoạn những năm 1950 đối đầu với âm mưu lật đổ Trung Quốc mới của các đặc vụ Tưởng Giới Thạch. Cốt truyện xoay quanh một cựu cảnh sát thời kỳ cũ, người có trí thông minh cao nhưng không thành công trong xã hội cũ, và sau khi Trung Quốc mới ra đời, anh đã tự thay đổi và trưởng thành. Anh hợp tác với một đặc công giàu kinh nghiệm của Đảng Cộng sản Trung Quốc, cùng nhau chống lại kẻ thù.</p>', 'Hoàn Tất (38/38)', 38, 'series', 'completed', 6, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Trung Quốc', 0, '[{"name":"Trần Triết Viễn","avatar":""},{"name":"Nhiếp Viễn","avatar":""},{"name":"Hình Phu","avatar":""},{"name":"Vương Kính Tùng","avatar":""},{"name":"Ôn Tranh Vanh","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"}]', '["An Ye Yu Li Ming","暗夜与黎明","Dark Night And Dawn"]', 1784690324181);
