INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('kinnikuman-hoan-my-thuy-to-phan-1', 'Kinnikuman: Hoàn Mỹ Thủy Tổ (Phần 1)', 'Kinnikuman Perfect Origin Arc (Season 1)', 'https://phimimg.com/upload/vod/20250302-1/2b842a0612cf696a5b8007e9f4bb3071.jpg', 'https://phimimg.com/upload/vod/20250302-1/45ee12447876b88970b0875ac4422512.jpg', '<p>Kinnikuman trở lại võ đài trong trận đấu tay ba hoành tráng giữa các phe Chojin Công Lý, Ác Quỷ và Toàn Mỹ, đồng thời hé lộ nguồn gốc của Chojin.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Mamoru Miyano","avatar":""},{"name":"Akira Kamiya","avatar":""},{"name":"Kendo Kobayashi","avatar":""},{"name":"Daisuke Ono","avatar":""},{"name":"Katsuyuki Konishi","avatar":""},{"name":"Sumire Uesaka","avatar":""},{"name":"Tomokazu Seki","avatar":""},{"name":"Jun Kasama","avatar":""},{"name":"Kensho Ono","avatar":""},{"name":"Yuki Kaji","avatar":""},{"name":"Hiroki Yasumoto","avatar":""},{"name":"Yuichi Nakamura","avatar":""},{"name":"Akio Otsuka","avatar":""},{"name":"Hiroyuki Yoshino","avatar":""},{"name":"Toshiya Miyata","avatar":""},{"name":"Yasuhiro Mamiya","avatar":""},{"name":"Wataru Komada","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["金肉人 完美超人始祖篇","筋肉人：完美超人始祖篇","Kinnikuman Kanpeki Chо̄jin Shiso-hen","Kinnikuman Perfect Origin-Hen","Kinnikuman Kanpeki Choujin Shisohen","근육맨 완벽초인시조편","Muscleman (2024)","キン肉マン 完璧超人始祖編"]', 1784690324181);
