INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('kinnikuman-hoan-my-thuy-to-phan-1', 'Kinnikuman: Hoàn Mỹ Thủy Tổ (Phần 1)', 'Kinnikuman Perfect Origin Arc (Season 1)', 'kinnikuman: hoàn mỹ thủy tổ (phần 1) kinnikuman perfect origin arc (season 1) mamoru miyano akira kamiya kendo kobayashi daisuke ono katsuyuki konishi sumire uesaka tomokazu seki jun kasama kensho ono yuki kaji hiroki yasumoto yuichi nakamura akio otsuka hiroyuki yoshino toshiya miyata yasuhiro mamiya wataru komada 金肉人 完美超人始祖篇 筋肉人：完美超人始祖篇 kinnikuman kanpeki chо̄jin shiso-hen kinnikuman perfect origin-hen kinnikuman kanpeki choujin shisohen 근육맨 완벽초인시조편 muscleman (2024) キン肉マン 完璧超人始祖編', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thoi-ky-xanh', 'Thời Kỳ Xanh', 'Blue Period', 'https://phimimg.com/upload/vod/20250302-1/566269a93e78c4b09dc07155b01073b3.jpg', 'https://phimimg.com/upload/vod/20250302-1/f92c633fe09aa0385212fdd3cb36de39.jpg', '<p>Dựa trên bộ manga ăn khách cùng tên của tác giả Yamaguchi Tsubasa đã chiến thắng giải Manga Taisho năm 2020. Dưới vỏ bọc của một nam sinh xuất sắc, Yatora Yaguchi luôn cố gắng hết sức để làm hài lòng mọi người. Cậu chưa bao giờ cảm thấy mình thật sự đang sống cho đến khi cậu bắt đầu vẽ bức tranh về khung cảnh sáng sớm dưới màu xanh huyền ảo tại Shibuya. Lần đầu tiên trong cuộc đời tăm tối của mình, Yatora nhận ra được nhịp đập trái tim mạnh mẽ dành cho hội họa và nghệ thuật. &quot;Tôi không phải thiên tài, nhưng tôi sẽ phấn đấu cho đến khi trở thành thiên tài!&quot;</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 1, '[{"name":"Gordon Maeda","avatar":""},{"name":"Fumiya Takahashi","avatar":""},{"name":"Rihito Itagaki","avatar":""},{"name":"Hiyori Sakurada","avatar":""},{"name":"Sena Nakajima","avatar":""},{"name":"Ikuho Akiya","avatar":""},{"name":"Katsumi Hyodo","avatar":""},{"name":"Masaki Miura","avatar":""},{"name":"Yasuhide Aiki","avatar":""},{"name":"Hikari Ishida","avatar":""},{"name":"Noriko Eguchi","avatar":""},{"name":"Hiroko Yakushimaru","avatar":""},{"name":"Haruka Imou","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Burū Piriodo","ブルーピリオド"]', 1784690324181);
