INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('cap-nhi-tan', 'Cáp Nhĩ Tân', 'Harbin', 'https://phimimg.com/upload/vod/20250227-1/5c8f2a3237892ffde13df86f8fda001c.jpg', 'https://phimimg.com/upload/vod/20250227-1/dab175f97e7f49d5d3005db75084fd9c.jpg', '<p>Cáp Nhĩ Tân Harbin 2024 Bối cảnh phim diễn ra vào năm 1909 tại thành phố Harbin, Trung Quốc. Ahn Jung-geun (do Hyun Bin thủ vai) cùng các đồng đội lên kế hoạch ám sát Itō Hirobumi, nhằm đấu tranh cho độc lập của Hàn Quốc trước sự chiếm đóng của Nhật Bản. Phim tái hiện những khó khăn, hy sinh và lòng dũng cảm của những chiến sĩ yêu nước trong cuộc chiến giành lại tự do cho quê hương.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Hàn Quốc', 0, '[{"name":"Hyun Bin","avatar":""},{"name":"Park Jeong-min","avatar":""},{"name":"Jo Woo-jin","avatar":""},{"name":"Jeon Yeo-been","avatar":""},{"name":"Lee Dong-wook","avatar":""},{"name":"Park Hoon","avatar":""},{"name":"Yoo Jae-myung","avatar":""},{"name":"Lily Franky","avatar":""},{"name":"Jung Woo-sung","avatar":""},{"name":"Kim Zio","avatar":""},{"name":"Lee Tae-hyeong","avatar":""},{"name":"Ahn Se-ho","avatar":""},{"name":"Yun Yeo-won","avatar":""},{"name":"Yoon Sang-ho","avatar":""},{"name":"Pak Ton-ha","avatar":""},{"name":"Heo Seung","avatar":""},{"name":"Son In-yong","avatar":""},{"name":"Son Seung-hoon","avatar":""},{"name":"Ego Mikitas","avatar":""},{"name":"Park","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Lịch Sử","slug":"lich-su","id":"f8ec3e9b77c509fdf64f0c387119b916"},{"name":"Chiến Tranh","slug":"chien-tranh","id":"1bae5183d681b7649f9bf349177f7123"}]', '["Harbin","하얼빈"]', 17846903