INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('man-hoang-tien-gioi', 'Man Hoang Tiên Giới', 'The Uninhabited Wonderland', 'https://phimimg.com/upload/vod/20250224-1/a8a610d3609bfd7acf74644457eb7b99.jpg', 'https://phimimg.com/upload/vod/20250224-1/0b3704b23be13fefdbb701c026d5998d.jpg', '<p>Ở Man Hoang Tiên Giới bao la vô tận, văn hoá tu tiên vô cùng thịnh hành. Người phàm ai cũng muốn khát khao trở thành tu sĩ. Lục Hàng Chi, một sinh viên đại học, đã xuyên không từ thời hiện đại đến làm một người phàm ở trấn Tử Vân, ngày nào cũng phải sống trong lo sợ. Tuy nhiên, hắn không cam chịu sống một cuộc sống như vậy, luôn cố gắng tiến về phía để thoát khỏi hoàn cảnh hiện tại. Sau đó, nhờ một hành động thiện mà hắn được đại tiểu thư của Chu phủ và sư huynh của cô ấy để ý tới. Họ đưa hắn tới Chu phủ để trải qua thử thách. Sau cố gắng không ngừng và may mắn có được một vài cơ duyên, hắn đã trở thành đệ tử ngoại môn của Huyền Tâm Tông và bắt đầu hành trình tu tiên của mình.</p>', 'Hoàn Tất (48/48)', 48, 'hoathinh', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Gu Jiangshan","avatar":""},{"name":"Mace","avatar":""},{"name":"Yan Ning","avatar":""},{"name":"Xiang Xu","avatar":""}]', '[{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Man Huang Xian Jie","蛮荒仙界","The Uninhabited Wonderland"]', 1784690324181);
