INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('thi-tran-tu-than', 'Thị Trấn Tử Thần', 'Death Town', 'https://phimimg.com/upload/vod/20250228-1/7f29b79a65681d48b32c65138481e30a.jpg', 'https://phimimg.com/upload/vod/20250228-1/b6415daf86655a3f070f621d67bf2fae.jpg', '<p>Suốt nhiều năm xa cách chiến tranh, nơi những năm tháng bình yên trôi qua, thị trấn Vô Thường bỗng dưng xảy ra hàng loạt các vụ tử vong bất ngờ. Trong quá trình điều tra, đội trưởng trinh sát Trần Mặc đã cứu được cô thiếu nữ Bạch Sương khi cô gặp nạn đuối nước. Nhờ sự phối hợp nhịp nhàng với Bạch Sương, họ liên tục có mặt tại hiện trường của các vụ tử vong, nhưng mỗi lần lại suýt chạm mặt với Thần Chết. Dưới ánh mắt chứng kiến của đám đông, liệu những cái chết bất ngờ ấy thực sự là do thiên tai hay do tai họa do con người gây ra?</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Hao Ze","avatar":""},{"name":"王可","avatar":""},{"name":"海颜","avatar":""},{"name":"Zhang Luyao","avatar":""},{"name":"Qiu Bin","avatar":""},{"name":"Sun Xiaomin","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["绝命无常镇"]', 1784690324181);
