INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-lua-dao-vi-dai-razbliuto', 'Kẻ Lừa Đảo Vĩ Đại: Razbliuto', 'Great Pretender: Razbliuto', 'https://phimimg.com/upload/vod/20250228-1/8ccff6f49109887778e6694cd51898db.jpg', 'https://phimimg.com/upload/vod/20250228-1/54ccc61efeecc879c8a74bb0ebfec7f6.jpg', '<p>Người tự xưng là thiên tài lừa đảo, Dorothy đã dụ dỗ Laurent Thierry bước vào thế giới của những trò lừa đảo. Sau khi thua một ván chơi với băng nhóm Rồng Hổ Thượng Hải, cô được cho là đã mất mạng… ít nhất là như vậy. Tuy nhiên, hình bóng của cô lại xuất hiện tại một ngôi làng nhỏ ven biển, không xa thành phố Taipei. Bị truy đuổi bởi thế giới ngầm của Taipei và hướng về Kyoto, liệu điều gì đang chờ đợi cô ở phía trước…!?</p>', 'Hoàn Tất (4/4)', 4, 'hoathinh', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yuka Komatsu","avatar":""},{"name":"Shunsuke Takeuchi","avatar":""},{"name":"Yasuhiro Mamiya","avatar":""},{"name":"Kazuyuki Okitsu","avatar":""},{"name":"Yasuyuki Kase","avatar":""},{"name":"Mitsuaki Kanuka","avatar":""},{"name":"Mariya Ise","avatar":""},{"name":"Chiaki Kobayashi","avatar":""},{"name":"Natsumi Fujiwara","avatar":""},{"name":"Mie Sonozaki","avatar":""},{"name":"Junichi Suwabe","avatar":""},{"name":"Shinya Kote","avatar":""},{"name":"Shunsuke Sakuya","avatar":""},{"name":"Kaoru Katakai","avatar":""},{"name":"Wataru Tsuyuzaki","avatar":""},{"name":"Masafumi Kobata","avatar":""}]', '[{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"}]', '["Great Pretender razbliuto","The Great Pretender","詐騙之王 Razbliuto","大欺诈师 razbliuto","グレートプリテンダー ラズブリウト","GREAT PRETENDER razbliuto"]', 1784690324181);
