INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giac-mo-my', 'Giấc Mơ Mỹ', 'The Brutalist', 'https://phimimg.com/upload/vod/20250228-1/0f5718e86639bb7cd557de39f14f8f86.jpg', 'https://phimimg.com/upload/vod/20250228-1/a3e8c190c57fcbd9bfe717f1cf462f9a.jpg', '<p>Phim ghi lại 30 năm cuộc đời của László Tóth (Adrien Brody), một kiến trúc sư người Do Thái gốc Hungary sống sót sau thảm họa diệt chủng Holocaust. Sau khi Thế chiến thứ hai kết thúc, ông di cư sang Hoa Kỳ cùng với vợ mình, Erzsébet (Felicity Jones) để trải nghiệm “giấc mơ Mỹ”. László ban đầu phải chịu đựng nghèo đói và sự sỉ nhục, nhưng anh sớm đạt được hợp đồng với một khách hàng bí ẩn và giàu có, Harrison Lee Van Buren, điều đó sẽ thay đổi cuộc đời anh.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Adrien Brody","avatar":""},{"name":"Felicity Jones","avatar":""},{"name":"Guy Pearce","avatar":""},{"name":"Joe Alwyn","avatar":""},{"name":"Raffey Cassidy","avatar":""},{"name":"Stacy Martin","avatar":""},{"name":"Isaach de Bankolé","avatar":""},{"name":"Alessandro Nivola","avatar":""},{"name":"Ariane Labed","avatar":""},{"name":"Michael Epp","avatar":""},{"name":"Emma Laird","avatar":""},{"name":"Jonathan Hyde","avatar":""},{"name":"Peter Polycarpou","avatar":""},{"name":"Maria Sand","avatar":""},{"name":"Salvatore Sansone","avatar":""},{"name":"Zephan Amissah","avatar":""},{"name":"Charlie Esoko","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Բռուտալիստը","El Brutalista","Le Brutaliste","粗野派","Brutalista","브루탈리스트","The Brutalist"]', 1784690324181);
