INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('anh-trai-phien-phuc-cua-toi', 'Anh Trai Phiền Phức Của Tôi', 'My Annoying Brother', 'https://phimimg.com/upload/vod/20250228-1/355676ab128c0f225045bccddd68bd5d.jpg', 'https://phimimg.com/upload/vod/20250228-1/0205b50e2650969acdb5e34077d63661.jpg', '<p>Khi một vận động viên tài năng mất đi thị lực, người anh em tù nhân của anh ta nhận ra đó là cơ hội để được ân xá sớm. Nhưng cuộc đoàn tụ hân hoan của họ lại mang đến bi kịch.</p>', 'Full', 1, 'single', 'completed', 14, 2024, 'Vietsub', 'FHD', 'Indonesia', 0, '[{"name":"Vino G. Bastian","avatar":""},{"name":"Angga Yunanda","avatar":""},{"name":"Caitlin Halderman","avatar":""},{"name":"Kristo Immanuel","avatar":""},{"name":"Marsha Timothy","avatar":""},{"name":"Fariz Alfarazi","avatar":""},{"name":"Andini Effendi","avatar":""},{"name":"Edwin Nazir","avatar":""},{"name":"Macho Hungan","avatar":""},{"name":"Yogi Indra Prasetyo","avatar":""},{"name":"Askari Danish Zharvi","avatar":""},{"name":"Jared Ali","avatar":""},{"name":"Delon Mercy","avatar":""},{"name":"Quentin Stanislavski","avatar":""},{"name":"Puty Sjahrul","avatar":""},{"name":"Julius He","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["My Annoying Brother"]', 1784690324181);
