INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tin-don', 'Tin Đồn', 'Rumours', 'https://phimimg.com/upload/vod/20250227-1/27eb872aa3f024bd612894629aa45ff2.jpg', 'https://phimimg.com/upload/vod/20250227-1/f0e091a7374091126bac65b7d55758a0.jpg', '<p>Tin Đồn Rumours 2024 xoay quanh bảy nhà lãnh đạo của các quốc gia giàu có nhất thế giới tham dự hội nghị thượng đỉnh G7. Trong quá trình soạn thảo tuyên bố chung về một cuộc khủng hoảng toàn cầu không xác định, họ bị lạc trong một khu rừng dày đặc sương mù. Tại đây họ phải đối mặt với những xác chết sống lại từ đầm lầy và một bộ não khổng lồ, đồng thời phải giải quyết những mâu thuẫn nội bộ để tìm đường thoát khỏi tình huống hiểm nghèo này.</p>', 'Full', 1, 'single', 'completed', 16, 2024, 'Vietsub', 'FHD', 'Canada', 0, '[{"name":"Cate Blanchett","avatar":""},{"name":"Roy Dupuis","avatar":""},{"name":"Nikki Amuka-Bird","avatar":""},{"name":"Charles Dance","avatar":""},{"name":"Takehiro Hira","avatar":""},{"name":"Denis Ménochet","avatar":""},{"name":"Rolando Ravello","avatar":""},{"name":"Zlatko Burić","avatar":""},{"name":"Alicia Vikander","avatar":""},{"name":"Alexa Kennedy","avatar":""},{"name":"Ralph Berkin","avatar":""},{"name":"Tomi Kosynus","avatar":""},{"name":"Ádám Bot","avatar":""},{"name":"Viktória Dányi","avatar":""},{"name":"Vivien Ferencz","avatar":""},{"name":"Dorina Mayer","avatar":""},{"name":"Zsófia Temesvári","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"}]', '["G7高瘋會：首腦危機","شایعه‌ها","루머스","Tanz der Titanen","Rumours"]', 1784690324181);
