INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khi-hart-ra-tay-2', 'Khi Hart Ra Tay 2', 'Die Hart 2', 'https://phimimg.com/upload/vod/20250227-1/0d62b7883dd00614d62f3b88efa6aa42.jpg', 'https://phimimg.com/upload/vod/20250227-1/42cc3436dc9708aefd954adda92b3302.jpg', '<p>Khi Hart Ra Tay 2 Die Hart 2: Die Harter 2024 là một bộ phim hành động Mỹ sắp ra mắt do Eric Appel đạo diễn. Trong phần tiếp theo này, Kevin Hart trở lại với vai trò ngôi sao hành động, đang lên kế hoạch cho một bộ phim hành động đột phá với những cảnh quay không theo kịch bản và bất ngờ để củng cố danh tiếng của mình. Tuy nhiên, kế hoạch của anh bị đảo lộn khi anh trở thành mục tiêu của một âm mưu báo thù từ quá khứ. Để vượt qua điều này, anh phải nhờ đến sự giúp đỡ của ngôi sao đồng đội yêu thích và trợ lý quá khích của mình.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Kevin Hart","avatar":""},{"name":"John Travolta","avatar":""},{"name":"Nathalie Emmanuel","avatar":""},{"name":"Jean Reno","avatar":""},{"name":"Josh Hartnett","avatar":""},{"name":"Kenneth Trujillo","avatar":""},{"name":"Joshua Lamboy","avatar":""},{"name":"Brandon Quinn","avatar":""},{"name":"Milana Vayntrub","avatar":""},{"name":"Stephan Jones","avatar":""},{"name":"Jason Jones","avatar":""},{"name":"Eric Mainade","avatar":""},{"name":"Haley Dumas","avatar":""},{"name":"Danielle Madison","avatar":""},{"name":"Ronny Mathew","avatar":""},{"name":"Gary Weeks","avatar":""},{"name":"Rahiem Riley","avatar":""},{"name":"Chloe","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Die Hart","ฮาร์ต อึดสุดพลัง","Die Hart: The Movie","תמות הארט: הסרט","Die Hart - Il Film","Hart: Duro de entrenar","終極哈特","猫胆虫威","动作巨星","Muere, Hart","动作明星梦"]', 1784690324181);
