INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('khi-hart-ra-tay-2', 'Khi Hart Ra Tay 2', 'Die Hart 2', 'khi hart ra tay 2 die hart 2 kevin hart john travolta nathalie emmanuel jean reno josh hartnett kenneth trujillo joshua lamboy brandon quinn milana vayntrub stephan jones jason jones eric mainade haley dumas danielle madison ronny mathew gary weeks rahiem riley chloe die hart ฮาร์ต อึดสุดพลัง die hart: the movie תמות הארט: הסרט die hart - il film hart: duro de entrenar 終極哈特 猫胆虫威 动作巨星 muere, hart 动作明星梦', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-bi-chiem-huu-phan-1', 'Tình Yêu Bị Chiếm Hữu (Phần 1)', 'Possessed Love (Season 1)', 'https://phimimg.com/upload/vod/20250227-1/c948e0bc4236e15122a570e734a7b33f.jpg', 'https://phimimg.com/upload/vod/20250227-1/63dfb2601d18d259cf01269c602654de.jpg', '<p>Những nhà tiên tri của số phận rơi vào lưới tình. Những nhà tiên tri Gen Z huyền bí và cuốn hút tụ hội để tìm kiếm người thương của mình. Dù có thể nhìn thấu tương lai, nhưng tình yêu lại là thứ duy nhất họ không thể đoán trước. Liệu họ có chấp nhận số phận đã an bài, hay sẽ để bản năng dẫn lối? Những mối quan hệ lãng mạn của họ dần trở nên rắc rối, cảm xúc khó định nghĩa cũng đan xen vào nhau. Một sự hỗn loạn đầy rung động con tim, nhưng tình yêu của họ lại mãnh liệt và đầy biến động. Ngay cả các vị thần cũng không thể tiên đoán được những màn tán tỉnh táo bạo giữa họ.Câu chuyện tình yêu kỳ lạ của những thầy bói lại bắt đầu lần nữa—liệu trái tim họ sẽ hướng về đâu?</p>', 'Hoàn Tất (6/6)', 6, 'tvshows', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Shin Dong Yeob","avatar":""},{"name":"Yoo In Na","avatar":""},{"name":"Gabee Yoo","avatar":""},{"name":"Seon Ho","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["Mo Shen S01","신들린 연애"]', 1784690324181);
