INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tai-sinh-2024', 'Tái Sinh', 'Eternal Rebirths', 'https://phimimg.com/upload/vod/20241210-1/827c54d5f814c8b0cd966059a3adb4dd.jpg', 'https://phimimg.com/upload/vod/20241210-1/4b9dcf18f693953272de31122e80550c.jpg', '<p>Mạnh Phàm mắc phải căn bệnh nan y và qua đời, nhưng bất ngờ mở ra một vòng hồi sinh tuần hoàn vô hạn kéo dài một năm. Sau khi trải qua 1001 lần sống lại, cuối cùng anh thoát khỏi vòng lặp một năm và trở về thời cấp ba cách đây mười năm. Từ đó, Mạnh Phàm đã trở thành người có trí tuệ và tài năng toàn diện, mọi tiếc nuối trong quá khứ đều có thể bắt đầu lại!</p>', 'Hoàn Tất (24/24)', 24, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Min Xinghan","avatar":""},{"name":"Elaine Yi","avatar":""},{"name":"Luo Yutian","avatar":""},{"name":"Shen Yu","avatar":""},{"name":"Gao Weiman","avatar":""},{"name":"Sun Yiran","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["重启人生","Restart Life","Chong Ran","重燃"]', 1784690324181);
