INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('nickel-boys', 'Nickel Boys', 'Nickel Boys', 'https://phimimg.com/upload/vod/20250226-1/08937e27c1d83115b4f5fa0e87c47315.jpg', 'https://phimimg.com/upload/vod/20250226-1/6283d896f8758afe9065025bba1dd9b4.jpg', '<p>Bộ phim câu chuyện về Elwood Curtis, một cậu bé người Mỹ gốc Phi trẻ tuổi bị gửi đến Học viện Nickel (nơi khét tiếng về việc ngược đãi học sinh) sau khi bị buộc tội oan về một tội ác vào những năm 1960. Trong thời gian ở đó, cậu gặp một cậu bé tên là Turner, và cả hai hình thành một tình bạn thân thiết khi cố gắng sống sót sau những nỗi kinh hoàng của ngôi trường và những người quản lý tham lam</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Ethan Herisse","avatar":""},{"name":"Brandon Wilson","avatar":""},{"name":"Aunjanue Ellis-Taylor","avatar":""},{"name":"Hamish Linklater","avatar":""},{"name":"Gralen Bryant Banks","avatar":""},{"name":"Fred Hechinger","avatar":""},{"name":"Jimmie Fails","avatar":""},{"name":"Luke Tennie","avatar":""},{"name":"Bryan Gael Guzman","avatar":""},{"name":"Ethan Cole Sharp","avatar":""},{"name":"Daveed Diggs","avatar":""},{"name":"Sam Malone","avatar":""},{"name":"Najah Bradley","avatar":""},{"name":"Jase Stidwell","avatar":""},{"name":"Legacy Jones","avatar":""},{"name":"Ky''drui","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["The Nickel Boys","五分钱男孩","黑男孩","Nickel Boys"]', 1784690324181);
