INSERT INTO movies_fts (slug, name, origin_name, actors, alternative_names) VALUES ('pushpa-2-luat-le', 'Pushpa 2: Luật Lệ', 'Pushpa 2: The Rule', 'pushpa 2: luật lệ pushpa 2: the rule allu arjun rashmika mandanna fahadh faasil jagadeesh bandari rao ramesh sunil varma anasuya bharadwaj ajay kalpalatha pavani karanam shri tej brahmaji jagapati babu tarak ponnappa adithya menon divi vadthya aadukalam naren saurabh sachdev pushpa 2 pushpa part 2 pushpa the rule புஷ்பா 2: the rule 普什帕：裁决 پوشپا 2: قانون pushpa 2 the rule reloaded プシュパ 君臨 పుష్పా 2 - the rule', '');
INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('blue-archive-the-animation', 'Blue Archive The Animation', 'Blue Archive the Animation', 'https://phimimg.com/upload/vod/20250226-1/ed902efeea32812a829d23cff5a82034.jpg', 'https://phimimg.com/upload/vod/20250226-1/cdffc778f0927385b5245ba55222161a.jpg', '<p>Chủ tịch Hội học sinh liên bang mất tích một cách bí ẩn. Vô số vấn đề đã bắt đầu nổi lên khắp Kivotos khi thiếu sự lãnh đạo của người đứng đầu. &nbsp;Để tránh thảm họa, Hội học sinh liên bang yêu cầu sự hỗ trợ từ Câu lạc bộ Điều tra Liên bang, hay còn gọi là Schale. Trên thực tế, Schale là câu lạc bộ mới nhất của thành phố và là câu lạc bộ cuối cùng được phê duyệt trước khi tổng thống mất tích.

Để hoàn thành nhiệm vụ của mình, Schale dựa vào sự hướng dẫn của một Sensei, người có thể giúp họ giải quyết các sự cố xung quanh Kivotos.

(Học sinh được yêu cầu mang theo vũ khí cá nhân và điện thoại thông minh! Hãy trải nghiệm những tình tiết hành động gay cấn, tình yêu và tình bạn mà Blue Archive The Animation mang lại)</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Yui Ogura","avatar":""},{"name":"Yumiri Hanamori","avatar":""},{"name":"Ayaka Ohashi","avatar":""},{"name":"Chiyuki Miura","avatar":""},{"name":"Sayaka Harada","avatar":""},{"name":"Reina Kondo","avatar":""},{"name":"Yukiyo Fujii","avatar":""},{"name":"Erika Ishitobi","avatar":""},{"name":"Rumi Okubo","avatar":""},{"name":"Ryo Hirohashi","avatar":""},{"name":"Marika Kouno","avatar":""},{"name":"Ayane Sakura","avatar":""},{"name":"Haruka Kouzuki","avatar":""},{"name":"Kaede Hondo","avatar":""},{"name":"Konomi Kohara","avatar":""},{"name":"Shogo Sakata","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["蔚蓝档案 The Animation","Blue Archive The Animation","蔚蓝档案","蔚藍檔案 The Animation","Blue Archive","ブルーアーカイブ The Animation"]', 1784690324181);
