INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('khong-co-thien-duong-chi-co-tinh-yeu', 'Không Có Thiên Đường Chỉ Có Tình Yêu', 'No Heaven But Love', 'https://phimimg.com/upload/vod/20250226-1/dae5c4c65223f8f5bb36a0e2092acc27.jpg', 'https://phimimg.com/upload/vod/20250226-1/25cc4d8da5d2dd8b292d0fd2e15675ba.jpg', '<p>1999— Thời đại của sự hỗn loạn, nơi bạo lực hoành hành khắp nơi. Khi đó, chẳng có gì là dễ dàng. Đây là câu chuyện về tình yêu và tình bạn của những cô gái, rực lửa hơn bất kỳ mùa hè nào... Mối quan hệ giữa Joo-young và Ye-ji đầy dịu dàng nhưng cuối cùng lại mang cảm giác như một điều không thể.</p>', 'Full', 1, 'single', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Park Soo-yeon","avatar":""},{"name":"Lee You-mi","avatar":""},{"name":"Shin Gi-hwan","avatar":""},{"name":"Kim Hyeon-mok","avatar":""},{"name":"Geum Hannah","avatar":""},{"name":"Oh Min-ae","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["We Can''t Go To Heaven, But We Can Love","우천사","天堂不在彼岸","没有天堂，但有爱情","우리는 천국에 갈 순 없지만 사랑은 할 수 있겠지"]', 1784690324181);
