INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-co-toi-cuong-tong', 'Vạn Cổ Tối Cường Tông', 'All Hail the Sect Leader', 'https://phimimg.com/upload/vod/20250224-1/334d7f4c96cd7bdd6f630ba3026d2691.jpg', 'https://phimimg.com/upload/vod/20250224-1/8e23a8186058546f5a1a304d559f98f5.jpg', '<p>Quân Thường Tiếu trong vòng 100 năm mục tiêu xây dựng tông môn mạnh mẽ, ông phải đối mặt với nhiều khó khăn khác nhau. Khi mở rộng môn phái, ông phải chọn lựa những đệ tử có tài năng huấn luyện họ. Sự tận tụy và tâm huyết của ông đã giúp đệ tử phát triển mạnh mẽ. Bên cạnh đó ông phải đối mặt với nhiều môn phái khác nhau và những rắc rối nội bộ. Những khó khăn thử thách liệu Quân Thường Tiếu có gây dựng được môn phái mạnh mẽ và tạo được danh tiếng của mình?</p>', 'Hoàn Tất (36/36)', 36, 'hoathinh', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["Wan Gu Zui Qiang Zong","万古最强宗 动画版","The Strongest Sect of All Times","The Strongest Sect of All Time","All Hail the Sect Leader","万古最强宗"]', 1784690324181);
