INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('van-gioi-chua-te', 'Vạn Giới Chúa Tể', 'Presiding Over The World', 'https://phimimg.com/upload/vod/20250224-1/da8ce294532a64dce51d6de7f8ee17b2.jpg', 'https://phimimg.com/upload/vod/20250224-1/aa8970412bfefcdfeb7b4ec0baf3bde3.jpg', '<p>Nhân vật chính Lâm Phong vốn là một kỹ sư AI thiên tài, dốc bao tâm huyết và công sức để nâng cao chức năng của người máy siêu cấp mà anh đang nghiên cứu. Anh đào được một con mắt của tổ loài rồng (Tổ Long Chi Mâu), báu vật từ thời thượng cổ ở dưới một vực sâu. Khi anh đang lắp con mắt đó vào trong người máy, thần lực trong mắt rồng bỗng được kích hoạt mở ra một vòng xoáy thời không đưa Lâm Phong đến Đại lục Cổ Thần - nơi vẫn đang thịnh hành võ đạo. Từ đó Lâm Phong chuyển kiếp sống lại. Sau khi sống lại, Lâm Phong bị phong ấn ký ức của kiếp trước, trở thành một người bình thường thức tỉnh võ hồn hệ trị liệu. Anh bị ghét, còn bị vị hôn thê huỷ hôn. Tộc nhân của vị hôn thê đó tàn nhẫn đánh lén muốn giết Lâm Phong để diệt cỏ tận gốc. Lúc nguy hiểm, Lâm Phong đã thức tỉnh ký ức về Tổ Long Chi Mâu và bất ngờ phát hiện ra thần lực của nó và siêu người máy anh nghiên cứu đã dung hợp. Dưới sự giúp đỡ của người máy, anh dần dần khống chế được thần lực của con mắt và bước vào con đường võ giả.</p>', 'Hoàn Tất (32/32)', 32, 'hoathinh', 'completed', 4, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[]', '[{"name":"Cổ Trang","slug":"co-trang","id":"3a17c7283b71fa84e5a8d76fb790ed3e"}]', '["万界主宰","Wan Jie Zhuzai","Wan Jie Zhu Zai","Lord of All Realms","Lord of Wonderlands"]', 1784690324181);
