INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('son-hai-phuc-ma-luc', 'Sơn Hải Phục Ma Lục', 'Adventures in Subduing the Demons', 'https://phimimg.com/upload/vod/20250224-1/660c490ac51ad80823113f27f760a66a.jpg', 'https://phimimg.com/upload/vod/20250224-1/d5212da1e59aaff144d509a9ff6fcadc.jpg', '<p>Các Đại lão dùng quyền và sức mạnh của mình bắt đầu âm mưu con đường thành công của riêng mình. Khương Hạo, một con cờ nhỏ bé trong cuộc đấu quyền lực của những đại lão, bỗng nhiên trở thành một nhân vật quan trọng. Để tìm kiếm cha mình, Khương Hạo bước chân vào đại hoang của tiền sử. Không chỉ phải đối đầu với những đối thủ mạnh mà còn phải tìm kiếm bản thân của quá khứ</p>', 'Tập 7', 26, 'hoathinh', 'ongoing', 4, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 0, '[{"name":"Yuhao Xu","avatar":""},{"name":"Jinger Wang","avatar":""},{"name":"Ling Jun","avatar":""},{"name":"Li Haojia","avatar":""},{"name":"Zhuang Miao","avatar":""},{"name":"Shuai Guan","avatar":""},{"name":"Ba He","avatar":""},{"name":"Wentao Chang","avatar":""},{"name":"Jingxing Ren","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["山海伏魔录","Shanhai Fu Mo Lu","巫皇","Wu Huang","Shan Hai Fu Mo Lu","Shanhai Fumolu","Shanhai Fumo Lu","Shanhai Fu Mo Lu: Wu Huang","The Wizard Lord","Shanhai Conquer Demon Record","Adventures in Subduing the Demons"]', 1784690324181);
