INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vi-tinh-yeu-dan-loi', 'Vì Tình Yêu Dẫn Lối', 'Fourever You', 'https://phimimg.com/upload/vod/20241006-1/aa01515e350532fec733a9e82391111f.jpg', 'https://phimimg.com/upload/vod/20241006-1/06545fe4214ee958d2f77095ac61b23c.jpg', '<p>Easter cố tình theo học tại một trường đại học ở phía bắc Thái Lan. Anh mong tìm được một nơi mới để xóa đi những ký ức về mối tình cũ kết thúc không rõ ràng. Nhưng ai nghĩ rằng anh sẽ gặp lại Hill, mối quan hệ cũ của anh, tại trường đại học này? Và đó là sự khởi đầu của một mối quan hệ sẽ không bao giờ kết thúc theo cách tương tự. Cùng lúc đó, bạn cùng phòng của anh là North cũng phải đối mặt với sự hỗn loạn vì say rượu gây ra cãi vã, sau đó tỉnh dậy với khoản nợ. Nhưng mọi chuyện có thể còn hỗn loạn hơn vì ông trời vừa gửi cho anh một chủ nợ hay tán tỉnh và rất hư hỏng, Johan. Vậy là câu chuyện của những người bạn cùng phòng này đã bắt đầu trong tiếng cười của những người bạn đến từ câu lạc bộ Nghệ thuật như Typhoon và Dao-Tok. Ngoài ra còn có các sinh viên y khoa cấp cao Tonfah và Arthit. Tình bạn của họ trong trường đại học này và những câu chuyện tình yêu của họ sẽ là những nốt nhạc đáng nhớ trong một thời gian dài.</p>', 'Hoàn Tất (17/17)', 17, 'series', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Katsamonnat Namwirote","avatar":""},{"name":"พลวิชญ์ เกตุประภากร","avatar":""},{"name":"Suradej Pinnirat","avatar":""},{"name":"Methaphat Chimkul","avatar":""},{"name":"Oat Tharathon Phumphothingam","avatar":""},{"name":"Ratchata Pichetshote","avatar":""},{"name":"Patsapon Jansuppakitkun","avatar":""},{"name":"Anupart Luangsodsai","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Four ever You Project","포에버 유 스페셜 에피소드 -조한 노스-","เซ็ตพี่หมอ","ไทเกอร์เดือนหนาว","Lately, It''s Winter Season","อาทิตย์ดาวตก","The Sun From Another Star","ต้นฟ้าไต้ฝุ่น","Beside The Sky","เพราะรักนำทาง พาร์ท 2","เพราะรักนำทาง"]', 1784690324181);
