INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ban-than-men-oi', 'Bạn Thân Mến Ơi', 'Mate The Series', 'https://phimimg.com/upload/vod/20241130-1/8337ef1c5f8f0252f74b264aeb407003.jpg', 'https://phimimg.com/upload/vod/20241130-1/d13fef6ab2f592c6f49e6c11cd44f896.jpg', '<p>Kenlong luôn có tất cả—sắc đẹp, sự giàu có và trí tuệ. Sự hoàn hảo là tiêu chuẩn của cô ấy, đặc biệt là trong tình yêu. Nhưng thế giới của cô bị đảo lộn khi cô gặp lại người bạn thời thơ ấu của mình, Oengoei, một cô gái ngây thơ và vô tư. Khi con đường của họ đan xen, Kenlong thấy mình bị thu hút bởi Oengoei, dẫn đến một sự hấp dẫn bị cấm đoán thách thức cuộc sống được tạo dựng tỉ mỉ của cô.</p>', 'Tập 12', 12, 'series', 'ongoing', 12, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Ponchanok Theerawan","avatar":""},{"name":"Budsarin Wonglelanont","avatar":""},{"name":"Boss Thapanat Athikompokin","avatar":""},{"name":"Palita Visitsak","avatar":""},{"name":"Thanaporn Suriyakham","avatar":""},{"name":"Chawinroj Likitchareonsakul","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Mate Series","Mate The Series","Mate เพื่อนรัก"]', 1784690324181);
