INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('arifureta-tu-tam-thuong-den-bat-kha-chien-bai-phan-3', 'Arifureta: Từ Tầm Thường Đến Bất Khả Chiến Bại (Phần 3)', 'Arifureta: From Commonplace To World''s Strongest (Season 3)', 'https://phimimg.com/upload/vod/20241118-1/e45b3df1be212b42ef7227502dc190a1.jpg', 'https://phimimg.com/upload/vod/20241118-1/3e67d17a8bfe0278789238866fc5a8fa.jpg', '<p>Chuyển thể từ light novel cùng tên của tác giả Hakumai Ryo. Câu chuyện về anh chàng Nagumo Hajime nổi tiếng vô dụng, ngày nọ được xuyên không sang thế giới khác rồi trở thành anh hùng cứu thế nơi đây. Nam sinh trung học Hajime là một otaku chính hiệu, đời này cậu chỉ giỏi có hai việc: một là thức thâu đêm suốt sáng, hai là ngủ gật trên lớp. Khi Hajime và cả lớp cùng được triệu hồi sang thế giới khác để thành những anh hùng với sứ mệnh cứu nhân loại khỏi sự diệt vong. Trong khi mọi người trong lớp đều được ban cho những năng lực phi thường, thì chỉ duy nhất năng lực của Hajime lại rất chi là cùi bắp. Bị chế nhạo từ thế giới này sang thế giới khác, Hajime quyết tâm làm thanh niên nghiêm túc. Để lột xác trở thành con người mới nên cậu ấy quyết định ra đi một mình. Liệu Hajime có thể sống sót trong thế giới đầy rẫy quái vật và ác ma này chỉ với năng lực cỏn con được ban cho? Cuộc chiến sinh tồn của chàng trai Hajime bắt đầu!</p>', 'Hoàn Tất (16/16)', 16, 'hoathinh', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Toshinari Fukamachi","avatar":""},{"name":"Yuuki Kuwahara","avatar":""},{"name":"Minami Takahashi","avatar":""},{"name":"Yoko Hikasa","avatar":""},{"name":"Saori Onishi","avatar":""},{"name":"Yumiri Hanamori","avatar":""},{"name":"Ai Kakuma","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Khoa Học","slug":"khoa-hoc","id":"0bcf4077916678de9b48c89221fcf8ae"},{"name":"Viễn Tưởng","slug":"vien-tuong","id":"68564911f00849030f9c9c144ea1b931"}]', '["Arifureta: From Commonplace to World’s Strongest","Arifureta","Arifureta: From Commonplace to World''s Strongest","Arifureta - Il più forte del mondo con un mestiere comune","Arifureta Shokugyou de Sekai Saikyou","ありふれた職業で世界最強 2nd season","Arifureta Shokugyō de Sekai Saikyō","흔해 빠진 직업으로 세계 최강","흔해빠진 직업으로 세계 최강","흔해빠진 직업으로 세계최강 3기","Arifureta - From Commonplace to World’s Strongest","From Common Job Class to the Strongest in the World","Arifureta World''s Strongest","Arifureta From Commonplace to World''s Strongest","Arifureta Commonplace to Worlds Strongest","Arifureta Worlds Strongest","Từ Tầm Thường Đến Phi Thường","Từ Kẻ Tầm Thường Trở Thành Người Phi Thường","Từ Tầm Thường Trở Thành Kẻ Mạnh Nhất","ありふれた職業で世界最強"]', 1784690324181);
