INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('bartender-ly-ruou-than-thanh', 'Bartender: Ly Rượu Thần Thánh', 'Bartender: Glass Of God', 'https://phimimg.com/upload/vod/20250222-1/0d21b68e4b6bf7d8d74d98115215d94e.jpg', 'https://phimimg.com/upload/vod/20250222-1/c1540eacfc545523cc07a7c190004846.jpg', '<p>Ẩn mình trong những con phố phía sau của quận Ginza là Eden Hall, một quán bar đặc biệt được điều hành bởi một thần đồng pha chế, Ryuu Sasakura, người được cho là pha chế những loại cocktail tuyệt vời nhất mà bất kỳ ai từng nếm thử. &nbsp;Tuy nhiên, không phải ai cũng có thể tìm thấy Eden Hall; đúng hơn, chính Eden Hall phải tìm thấy bạn. Những khách hàng thuộc nhiều hoàn cảnh khác nhau, mỗi người đều gặp phải những rắc rối riêng. Tuy nhiên, Ryuu luôn biết loại cocktail lý tưởng để an ủi và hướng dẫn từng tâm hồn quẫn trí.</p>', 'Hoàn Tất (12/12)', 12, 'hoathinh', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Nhật Bản', 0, '[{"name":"Takuma Terashima","avatar":""},{"name":"Yoshino Nanjo","avatar":""},{"name":"Haruka Shiraishi","avatar":""},{"name":"Eriko Matsui","avatar":""},{"name":"Ryoko Shiraishi","avatar":""},{"name":"Makoto Furukawa","avatar":""},{"name":"Hiroki Touchi","avatar":""},{"name":"Naoya Uchida","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["调酒师 神之杯","王牌酒保 Glass of God","王牌酒保 神之杯","王牌酒保 神之酒杯","نادل كأس الإله","Bartender Kami no Glass","Bartender: Glass of God","バーテンダー 神のグラス"]', 1784690324181);
