INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('jeong-nyeon-ngoi-sao-vut-sang', 'Jeong Nyeon: Ngôi Sao Vụt Sáng', 'Jeongnyeon: The Star Is Born', 'https://phimimg.com/upload/vod/20250222-1/4d34b17842914d0c35305198479b6821.jpg', 'https://phimimg.com/upload/vod/20250222-1/3c48df10c5f66bcfae959229e7397f03.jpg', '<p>Jeongnyeon: The Star Is Born lấy bối cảnh Hàn Quốc những năm 1950 sau chiến tranh. Phim xoáy sâu vào hành trình phát triển bản thân của Jeong Nyeon, một cô gái nông thôn làm nghề bán cá ở chợ với niềm đam mê ca hát mãnh liệt. Jeong Nyeon đã vượt qua mọi sự cấm cảm từ gia đình, khó khăn của thời đại và thách thức đến từ cuộc sống nơi đoàn kịch để trở thành diễn viên pansori (một loại hình âm nhạc diễn xướng truyền thống của Hàn Quốc) xuất sắc nhất Hàn Quốc.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Kim Tae-ri","avatar":""},{"name":"Shin Ye-eun","avatar":""},{"name":"Ra Mi-ran","avatar":""},{"name":"Jung Eun-chae","avatar":""},{"name":"Kim Yoon-hye","avatar":""},{"name":"Woo Da-vi","avatar":""},{"name":"Hyun Seung-hee","avatar":""},{"name":"Jung Lael","avatar":""},{"name":"Moon So-ri","avatar":""},{"name":"Jang Hye-jin","avatar":""},{"name":"Lee Duck-hwa","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["正年","جئونگ‌نیون: تولد یک ستاره","جونغ يون: ولادة النجم","Jeongnyeon","정년이"]', 1784690324181);
