INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ke-hoach-panda', 'Kế Hoạch Panda', 'Panda Plan', 'https://phimimg.com/upload/vod/20241221-1/d278eee76fa741fafc6f482492820f33.jpg', 'https://phimimg.com/upload/vod/20241221-1/bce47d83eebc4944fc112406b676f65d.jpg', '<p>Thành Long, ngôi sao Kung Fu huyền thoại, được mời nhận nuôi một chú gấu trúc con đáng yêu tên là Huhu. Nổi tiếng với nét quyến rũ độc đáo và đôi mắt lệch nhau đặc biệt, Huhu thu hút sự chú ý của một tập đoàn tội phạm quốc tế khét tiếng. Quyết tâm bắt được con gấu trúc, họ treo một khoản tiền thưởng khổng lồ cho ai lấy được đầu Huhu. Đối mặt với cuộc khủng hoảng bất ngờ này, Jackie hợp tác với người đại diện hiểu biết của mình, David, và người chăm sóc gấu trúc tận tâm, Xiaozhu. Cùng nhau, bộ ba năng động này sử dụng các kỹ năng và chiến thuật thông minh của mình để đánh bại những kẻ phản diện và giữ cho Huhu được an toàn. Hãy sẵn sàng cho một cuộc phiêu lưu khó quên với những khúc mắc bất ngờ, nhiều tiếng cười và trận chiến cuối cùng để giành lấy kho báu dễ thương nhất trong sở thú!</p>', 'Full', 1, 'single', 'completed', 8, 2024, 'Vietsub', 'FHD', 'Trung Quốc', 1, '[{"name":"Jackie Chan","avatar":""},{"name":"Wei Xiang","avatar":""},{"name":"Han Yanbo","avatar":""},{"name":"Shi Ce","avatar":""},{"name":"Andy Friend","avatar":""},{"name":"Xu Juncong","avatar":""},{"name":"Huang Yuntong","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"}]', '["Panda Plan","Project P","我不是熊猫","Xiong Mao Ji Hua","Operación Panda: Misión Rescate","Panda Project","熊猫计划"]', 1784690324181);
