INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dung-ngoanh-lai-toi-biet-goc-gac-cua-co', 'Đừng Ngoảnh Lại... Tôi Biết Gốc Gác Của Cô', 'Don''t Look Back... I Know Your Origins', 'https://phimimg.com/upload/vod/20250222-1/c92515db70025843441cd4b20da25c76.jpg', 'https://phimimg.com/upload/vod/20250222-1/87ce9f79eba88d996751b6c8d54dce89.jpg', '<p>Khi người mẹ bắt đầu bị một thực thể tà ác ám, Lynn biết được sự thật kinh hoàng: linh hồn báo thù, còn gọi là Saka, đã trở lại, và nó đang đến tìm cô.</p>', 'Full', 1, 'single', 'completed', 17, 2024, 'Vietsub', 'FHD', 'Malaysia', 1, '[{"name":"Emma Maembong","avatar":""},{"name":"Iedil Putra","avatar":""},{"name":"Alif Hadi","avatar":""},{"name":"Hafidzuddin Fazil","avatar":""},{"name":"Cat Farish","avatar":""},{"name":"Khatijah Tan","avatar":""},{"name":"Mawar Rashid","avatar":""},{"name":"Ruminah Sidek","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Bí Ẩn","slug":"bi-an","id":"2fb53017b3be83cd754a08adab3e916c"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Jangan Pandang Belakang 2","Jangan Pandang Belak2ng: Aku Tahu Asal Usulmu","វិញ្ញាណសណ្ឋិតអ្នកម៉ែ 2","ญินตามติด","Jangan Pandang Belakang 2: Aku Tahu Asal Usulmu"]', 1784690324181);
