INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('dai-chien-bong-dem', 'Đại Chiến Bóng Đêm', 'Out of Darkness', 'https://phimimg.com/upload/vod/20250222-1/88107f6757f7e8d7d25d0263a74b87b1.jpg', 'https://phimimg.com/upload/vod/20250222-1/04a2fe64443da1bad01902bf25acd5fd.jpg', '<p>Vào thời kỳ Đồ đá, một nhóm người tiền sử đã hợp lực để tìm kiếm một vùng đất mới. Nhưng khi họ nghi ngờ rằng một linh hồn ác quỷ, bí ẩn đang săn lùng họ, bộ tộc phải đối diện với một sự nguy hiểm mà họ chưa từng tưởng tượng.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Anh', 0, '[{"name":"Safia Oakley-Green","avatar":""},{"name":"Kit Young","avatar":""},{"name":"Chuku Modu","avatar":""},{"name":"Iola Evans","avatar":""},{"name":"Arno Luening","avatar":""},{"name":"Luna Mwezi","avatar":""},{"name":"Rosebud Melarkey","avatar":""},{"name":"Tyrell Mhlanga","avatar":""}]', '[{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["The Origin","Из тьмы","走出黑暗","Out of Darkness"]', 1784690324181);
