INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('paddington-gau-thu-chu-du', 'Paddington: Gấu Thủ Chu Du', 'Paddington In Peru', 'https://phimimg.com/upload/vod/20250217-1/518ae8207dfb49ae6e60494bf4fc0563.jpg', 'https://phimimg.com/upload/vod/20250217-1/b9f71974631c16f3c9243d1073becbba.jpg', '<p>&quot;Paddington: Gấu Thủ Chu Du&quot; đưa khán giả theo chân chú gấu được nhiều người yêu mến, thích ăn mứt cam đang trong một chuyến phiêu lưu đầy mạo hiểm. Khi Paddington phát hiện ra dì Lucy yêu quý của mình đã biến mất khỏi Ngôi Nhà Dành Cho Các Chú Gấu Nghỉ Hưu, Paddington và gia đình Brown lên đường đến vùng hoang dã Peru để tìm kiếm, với manh mối duy nhất về nơi dì ấy ở là một điểm đánh dấu trên một bản đồ bí ẩn. Quyết tâm giải mã những bí mật đằng sau, Paddington bắt đầu một cuộc hành trình qua rừng nhiệt đới Amazon để tìm dì của mình... và có thể chú sẽ phát hiện ra một trong những kho báu huyền thoại nhất thế giới.</p>', 'Full', 1, 'single', 'completed', 13, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 1, '[{"name":"Ben Whishaw","avatar":""},{"name":"Hugh Bonneville","avatar":""},{"name":"Emily Mortimer","avatar":""},{"name":"Samuel Joslin","avatar":""},{"name":"Madeleine Harris","avatar":""},{"name":"Antonio Banderas","avatar":""},{"name":"Olivia Colman","avatar":""},{"name":"Julie Walters","avatar":""},{"name":"Jim Broadbent","avatar":""},{"name":"Carla Tous","avatar":""},{"name":"Hayley Atwell","avatar":""},{"name":"Oliver Maltman","avatar":""},{"name":"Joel Fry","avatar":""},{"name":"Robbie Gee","avatar":""},{"name":"Sanjeev Bhaskar","avatar":""},{"name":"Imelda Staunton","avatar":""},{"name":"Ben Miller","avatar":""},{"name":"Je","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu