INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quy-ong-hoan-hao-2024', 'Quý Ông Hoàn Hảo', 'Better Man', 'https://phimimg.com/upload/vod/20250219-1/af42ead6c73a7c066d61c1fdd98f2271.jpg', 'https://phimimg.com/upload/vod/20250219-1/9e5cda7ab4f1b2818d35414b23013ac0.jpg', '<p>Dựa trên câu chuyện có thật về sự trỗi dậy của thiên thạch, mùa thu kịch tính và sự hồi sinh đáng chú ý của siêu sao nhạc pop người Anh Robbie Williams, một trong những nghệ sĩ giải trí vĩ đại nhất mọi thời đại. Dưới sự chỉ đạo có tầm nhìn của Michael Gracey (người biểu diễn vĩ đại nhất), bộ phim được kể một cách độc đáo từ quan điểm của Robbie, nắm bắt được sự dí dỏm đặc trưng của anh ấy và tinh thần bất khuất. Nó đi theo hành trình của Robbie từ thời thơ ấu, trở thành thành viên trẻ nhất của nhóm nhạc nam đứng đầu bảng xếp hạng, thông qua những thành tựu vô song của anh như một nghệ sĩ solo phá kỷ lục-trong khi đối mặt với những thách thức mà sự nổi tiếng và thành công của tầng bình lưu có thể mang lại.</p>', 'Full', 1, 'single', 'completed', 10, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Robbie Williams","avatar":""},{"name":"Jonno Davies","avatar":""},{"name":"Steve Pemberton","avatar":""},{"name":"Alison Steadman","avatar":""},{"name":"Kate Mulvany","avatar":""},{"name":"Frazer Hadfield","avatar":""},{"name":"Damon Herriman","avatar":""},{"name":"Raechelle Banno","avatar":""},{"name":"Tom Budge","avatar":""},{"name":"Jake Simmance","avatar":""},{"name":"Liam Head","avatar":""},{"name":"Chase Vollenweider","avatar":""},{"name":"Jesse Hyde","avatar":""},{"name":"Anthony Hayes","avatar":""},{"name":"John Waters","avatar":""},{"name":"Leo Harvey-Elledge","avatar":""},{"name":"Chris Gun","avatar":""}]', '[{"name":"Âm Nhạc","slug":"am-nhac","id":"252e74b4c832ddb4233d7499f5ed122e"},{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"}]', '["ベター・マン","אדם טוב יותר: סיפורו של רובי וויליאמס","Polepšený: Robbie Williams","Better Man"]', 1784690324182);
