INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('sangmin-dinneaw', 'Sangmin Dinneaw', 'Sangmin Dinneaw', 'https://phimimg.com/upload/vod/20250103-1/eb9fe3aa9f52f78090ecf432d9fe3950.jpg', 'https://phimimg.com/upload/vod/20250103-1/bf9490741a8893e569c3af3166b568cf.jpg', '<p>Khi còn nhỏ, Sang Min đã có thời gian tham gia trao đổi sinh viên ở Thái Lan, nơi anh ở cùng với Orn, mẹ của Dinneaw lúc đó còn rất trẻ. Hơn mười năm đã trôi qua cùng Sang Min trở lại Hàn Quốc. Suốt thời gian qua, anh không giữ liên lạc với gia đình, cho đến một ngày, Sang Min có lý do để trở về Thái Lan và ở lại với Orn một lần nữa. Ở đó, anh gặp lại Dinneaw, người lớn lên khá đẹp trai.</p>', 'Tập 8', 10, 'series', 'ongoing', 8, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Sangmin Choi","avatar":""},{"name":"Ratana Aiamsaart","avatar":""},{"name":"Joke Chaloemdet Thammawut","avatar":""},{"name":"Ratchanon Kanpiang","avatar":""},{"name":"Krin Preechachaisurat","avatar":""},{"name":"Bom Thunpisit Larpsumritphon","avatar":""},{"name":"Poom Pathai","avatar":""},{"name":"Little Siravit Imsee","avatar":""},{"name":"Nonthakorn Chatchue","avatar":""},{"name":"Narumon Phongsupan","avatar":""},{"name":"Toktak Suthirat","avatar":""},{"name":"Creamy Ploypapas Isarapongporn","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["ซังมินดินเหนียว"]', 1784690324182);
