INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('self-reliance', 'Tự Lực Cánh Sinh', 'Self Reliance', 'https://phimimg.com/upload/vod/20250214-1/30558cb2686e6ed6a8c433f82653d3e5.jpg', 'https://phimimg.com/upload/vod/20250214-1/a5383dcf53d1199c4045372df63bcbbe.jpg', '<p>Được trao cơ hội tham gia một chương trình trò chơi thực tế sinh tử, một người đàn ông nhận ra rằng mình có nhiều lí do để sống.</p>', 'Full', 1, 'single', 'completed', 7, 2024, 'Vietsub', 'FHD', 'Âu Mỹ', 0, '[{"name":"Jake Johnson","avatar":""},{"name":"Anna Kendrick","avatar":""},{"name":"Natalie Morales","avatar":""},{"name":"Andy Samberg","avatar":""},{"name":"Mary Holland","avatar":""},{"name":"Emily Hampshire","avatar":""},{"name":"Nancy Lenehan","avatar":""},{"name":"Daryl J. Johnson","avatar":""},{"name":"Miriam Flynn","avatar":""},{"name":"Boban Marjanović","avatar":""},{"name":"Biff Wiff","avatar":""},{"name":"Eduardo Franco","avatar":""},{"name":"Jeff Kober","avatar":""},{"name":"Christopher Lloyd","avatar":""},{"name":"Theo Wilson","avatar":""},{"name":"Bjorn Johnson","avatar":""},{"name":"John Hans Tes","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["خودباوری","自力更生","Allein sein verboten","Autosufficienza","Самодостатність","Samopouzdanje","Self Reliance"]', 1784690324182);
