INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('vong-lap-chet-choc', 'Vòng Lặp Chết Chóc', 'Time: The Series', 'https://phimimg.com/upload/vod/20241112-1/597cf8a1fb537d81a05ee56d73ffe880.jpg', 'https://phimimg.com/upload/vod/20241112-1/3ff82ec14c4f01999cf71d5f49c62c5b.jpg', '<p>Diễn viên Foam nổi tiếng tận mắt chứng kiến người yêu mình là Chris bị cảnh sát ngộ sát. May mắn thay, số phận cho anh một cơ hội nữa, để anh trở về quá khứ, thay đổi tình huống đã khiến Chris gặp nạn. Khi một người đàn ông bí ẩn đưa cho Foam một chiếc đồng hồ có thể trở lại quá khứ, liệu anh có thể thành công thay đổi quá khứ, hoàn thành việc ngược dòng thời gian cứu người yêu này hay không, chúng ta hãy cùng chờ xem nhé!</p>', 'Hoàn Tất (13/13)', 13, 'series', 'completed', 7, 2024, 'Vietsub + Thuyết Minh', 'FHD', 'Thái Lan', 0, '[{"name":"Pancake Khemanit Jamikorn","avatar":""},{"name":"Boy Pakorn Chatborirak","avatar":""},{"name":"Jackie Jacqueline Muench","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["Tempo","时空救爱之旅","Time The Series","TIME* ผ่านเวลา","ไทม์ผ่านเวลา","逆時拯救","Time: The Series","ไทม์ ผ่าน เวลา"]', 1784690324182);
