INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('ho-thue-toi-tan-tinh-sat-thu', 'Họ Thuê Tôi Tán Tỉnh Sát Thủ', 'The Heart Killers', 'https://phimimg.com/upload/vod/20241127-1/62440c257384451a645a5c9fe7f1f26b.jpg', 'https://phimimg.com/upload/vod/20241127-1/e3116ae39d72903c015fc215668b4295.jpg', '<p>Thợ xăm Kant làm gián điệp cho cảnh sát. Khi được giao nhiệm vụ điều tra một cặp anh em tay súng, anh phát hiện ra rằng một trong số họ là tình một đêm mà anh không thể quên được—Bison. Hai sát thủ sở hữu một cửa hàng hamburger. Kant đến đó và tập trung nỗ lực thuyết phục Bison tiết lộ thông tin. Khi những nỗ lực của anh bị cản trở bởi Fadel, người anh trai đáng sợ và luôn bảo vệ Bison, anh đã thuê một người có thể đối đầu với anh. Anh nhờ đến sự giúp đỡ của người bạn thân đẹp trai Style, người bị đau cổ và không sợ bất cứ điều gì. Mechanic Style từng đánh bại Fadel từ phía sau và họ đã chiến đấu. Kant hứa với Style chiếc xe mà anh đã để mắt tới nếu có thể chiếm được trái tim của Fadel. Nếu nhiệm vụ của anh thành công, Kant được hứa hẹn sẽ sạch tội để anh có thể bắt đầu một cuộc sống mới.</p>', 'Hoàn Tất (12/12)', 12, 'series', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Thái Lan', 0, '[{"name":"Kanaphan Puitrakul","avatar":""},{"name":"Thanawat Ratanakitpaisan","avatar":""},{"name":"Archen Aydin","avatar":""},{"name":"Natachai Boonprasert","avatar":""},{"name":"Phanuroj Chalermkijporntavee","avatar":""},{"name":"Thanaporn Wagprayoon","avatar":""},{"name":"Peter Tuinstra","avatar":""},{"name":"Chayakorn Jutamas","avatar":""},{"name":"Tanan Lohawatanakul","avatar":""},{"name":"Jeeratch Wongpian","avatar":""}]', '[{"name":"Hành Động","slug":"hanh-dong","id":"9822be111d2ccc29c7172c78b8af8ff5"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a24