INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('giua-hai-duong-ray-phan-4', 'Giữa Hai Đường Ray (Phần 4)', 'Wrong Side Of The Tracks (Season 4)', 'https://phimimg.com/upload/vod/20250212-1/b214187ec00a4f90d11886f96fbd4cc9.jpg', 'https://phimimg.com/upload/vod/20250212-1/db8df516510087eb45a38ebb90bd229e.jpg', '<p>Khi cháu gái tuổi teen của mình trở thành nạn nhân của những kẻ buôn ma túy lấn át khu phố, một cựu chiến binh chán nản quyết định tự mình giải quyết vấn đề.</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 12, 2024, 'Vietsub', 'FHD', 'Tây Ban Nha', 0, '[{"name":"Jose Coronado","avatar":""},{"name":"Luis Zahera","avatar":""},{"name":"Felipe Londoño","avatar":""},{"name":"Laura Ramos","avatar":""},{"name":"Manuel Tallafé","avatar":""},{"name":"Manolo Caro","avatar":""},{"name":"Itziar Atienza","avatar":""},{"name":"Franky Martín","avatar":""},{"name":"María de Nati","avatar":""},{"name":"Miguel Ángel Jiménez","avatar":""},{"name":"María Molins","avatar":""},{"name":"Raúl Sanz","avatar":""},{"name":"Bruno Lastra","avatar":""},{"name":"Adil Koukouh","avatar":""},{"name":"Carmen Esteban","avatar":""},{"name":"Mariona Terés","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hình Sự","slug":"hinh-su","id":"7a035ac0b37f5854f0f6979260899c90"}]', '["Entrevías"]', 1784690324182);
