INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('quay-ray', 'Quấy Rầy', 'Fester', 'https://phimimg.com/upload/vod/20250211-1/792d0e58bcdffb914a6c8303cdfa2748.jpg', 'https://phimimg.com/upload/vod/20250211-1/93e5efde6f2d1ddc60f6d1f1b2cfa7a7.jpg', '<p>Vào ngày 19 tháng 11 năm 2023, một cặp vợ chồng giàu có ở độ tuổi 40 bước vào nhà hàng Umi của Bum Jin. Tuy nhiên, sau khi tỉnh dậy sau một cơn mất trí nhớ ngắn, Bum Jin phát hiện ra một mẩu giấy với đơn đặt hàng của họ được viết trên tay anh, kèm theo những con số lạ 2311192359.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Seol Junsu","avatar":""},{"name":"Kim Si Ho","avatar":""},{"name":"Shin Jun Young","avatar":""},{"name":"Ibada","avatar":""},{"name":"Lee Myung Ha","avatar":""}]', '[{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"},{"name":"Kinh Dị","slug":"kinh-di","id":"4db8d7d4b9873981e3eeb76d02997d58"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"}]', '["페스터"]', 1784690324182);
