INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('xe-mui-tran', 'Xe Mui Trần', 'Cabriolet', 'https://phimimg.com/upload/vod/20250211-1/208056d37451d8c17c0f97b00e174d4d.jpg', 'https://phimimg.com/upload/vod/20250211-1/151b5f776ab738c41ba015b39a003ffe.jpg', '<p>Luôn nở nụ cười trên khuôn mặt, Oh Ji-ah luôn nỗ lực bất kể điều gì, mơ về một tương lai tươi sáng và rực rỡ. Nhưng rồi, cô bất ngờ được chẩn đoán mắc ung thư tuyến ức. Dù vậy, công ty và gia đình vẫn ép buộc cô như thường lệ… Khi đang sống cuộc sống hàng ngày của mình, bạn của cô, Anna, đến thăm. Anna, người mà Ji-ah coi là hình mẫu lý tưởng với vai trò CEO của một công ty, đề nghị đi du lịch khắp đất nước bằng xe mui trần vào ngày hôm sau, nhưng Ji-ah từ chối vì công việc ngập đầu và ca phẫu thuật sắp tới. Và ngày hôm sau, Ji-ah đối diện với di ảnh của Anna. Đang chịu đựng sự kiệt sức, Ji-ah mua một chiếc xe mui trần &#39;Cabriolet&#39; bằng số tiền cô đã dành dụm cho ca phẫu thuật và bắt đầu chuyến du lịch khắp đất nước.</p>', 'Full', 1, 'single', 'completed', 6, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Geum Sae-rok","avatar":""},{"name":"Ryu Kyung-soo","avatar":""},{"name":"Kang Young-suk","avatar":""}]', '[{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"},{"name":"Tình Cảm","slug":"tinh-cam","id":"bb2b4b030608ca5984c8dd0770f5b40b"},{"name":"Tâm Lý","slug":"tam-ly","id":"a7b065b92ad356387ef2e075dee66529"}]', '["카브리올레"]', 1784690324182);
