INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('tinh-yeu-ap-u', 'Tình Yêu Ấp Ủ', 'Heartsping : Teenieping Of Love', 'https://phimimg.com/upload/vod/20250211-1/db55eb1a118451b59ecf2fe6e77666a0.jpg', 'https://phimimg.com/upload/vod/20250211-1/ae8085ef2d13a8def3bc43f3d1e0a5b3.jpg', '<p>Để tìm được bạn đời lý tưởng của mình, Heartsping, Romi đã tiến sâu vào khu rừng phép thuật bí ẩn và nguy hiểm. Cô ấy không sợ hãi, quyết tâm và dũng cảm, làm việc cùng các đồng đội để giải quyết thành công sự hiểu lầm này và cứu Heartsping, người đang gặp khủng hoảng. Cuối cùng, Heartsping đã bị chinh phục bởi lòng dũng cảm phi thường và trái tim nhân hậu của Romi. Bị ấn tượng, và đã hợp tác với Romi.</p>', 'Full', 1, 'hoathinh', 'completed', 9, 2024, 'Vietsub', 'FHD', 'Hàn Quốc', 0, '[{"name":"Lee Ji-hyun","avatar":""},{"name":"Jo Kyoung-i","avatar":""},{"name":"Choi Nak-yoon","avatar":""},{"name":"Yeo Min-jeong","avatar":""},{"name":"Hong So-young","avatar":""},{"name":"Hong Bum-ki","avatar":""},{"name":"Kim Ha-yeong","avatar":""},{"name":"Ryu Seung-gone","avatar":""},{"name":"Cho Hyun-jung","avatar":""},{"name":"Kim Eun-ah","avatar":""},{"name":"Jang Ye-na","avatar":""},{"name":"Um Sang-hyun","avatar":""}]', '[{"name":"Gia Đình","slug":"gia-dinh","id":"a2492d6cbc4d58f115406ca14e5ec7b6"},{"name":"Phiêu Lưu","slug":"phieu-luu","id":"66c78b23908113d478d8d85390a244b4"},{"name":"Trẻ Em","slug":"tre-em","id":"0c853f6238e0997ee318b646bb1978bc"}]', '["The Perfect Match","Heartsping Teenieping of Love","사랑의 하츄핑 싱어롱","사랑의 하츄핑"]', 1784690324182);
