INSERT OR REPLACE INTO movies (slug, name, origin_name, thumb_url, poster_url, description, episode_current, episode_total, type, status, view, year, lang, quality, country_name, chieurap, actor_json, category_json, alternative_names_json, last_updated) VALUES ('trang-trai-clarkson-phan-3', 'Trang Trại Clarkson (Phần 3)', 'Clarkson''s Farm (Season 3)', 'https://phimimg.com/upload/vod/20250211-1/a24b4b3d58b65a6dc38ba0a35524aa8c.jpg', 'https://phimimg.com/upload/vod/20250211-1/67f3424e6894cd02fab7d09b0daf8a35.jpg', '<p>Clarkson&#39;s Farm là loạt phim tài liệu truyền hình Anhvề Jeremy Clarkson và trang trại của ông ở Cotswolds . Loạt phim ghi lại những nỗ lực của Clarkson trong việc điều hành một trang trại rộng 1.000 mẫu Anh (400 ha) gần Chipping Norton ở West Oxfordshire . Được Clarkson mô tả là &quot; chương trình truyền hình thực tế đích thực &quot;, loạt phim đã nhận được những đánh giá tích cực và được ca ngợi vì đã nâng cao nhận thức của công chúng về ngành nông nghiệp Anh trên trường quốc tế</p>', 'Hoàn Tất (8/8)', 8, 'series', 'completed', 5, 2024, 'Vietsub', 'FHD', 'Anh', 0, '[{"name":"Jeremy Clarkson","avatar":""},{"name":"Kaleb Cooper","avatar":""},{"name":"Charlie Ireland","avatar":""},{"name":"Lisa Hogan","avatar":""}]', '[{"name":"Chính Kịch","slug":"chinh-kich","id":"37a7b38b6184a5ebd3c43015aa20709d"},{"name":"Hài Hước","slug":"hai-huoc","id":"ba6fd52e5a3aca80eaaf1a3b50a182db"}]', '["La granja de clarkson","La Ferme de Clarkson","Before I bought the farm","I Bought the Farm","Ферма Кларксона","克拉克森農場趣","Jeremy Clarkson: I Bought the Farm","Clarksons Farm","Clarkson''s Farm"]', 1784690324182);
